local addonName, addonTable = ...

addonTable.questData['fr'] = {
[1] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINVous allez être la cible du sort suivant :\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINVous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nPoulet autre\n\nVous recevrez :\n\n"},
[2] = {title = "La griffe de Serres-tranchantes", objective = "Apporter la griffe de Serres-tranchantes à Senani Thunderheart, au poste de Bois-brisé, en Ashenvale.", description = "Le grand hippogryphe Serres-tranchantes a été tué, et la griffe arrachée à son cadavre témoigne de votre victoire. Senani Thunderheart, au poste de Bois-brisé, sera sans doute intéressée de voir ce trophée qui est la preuve de votre exploit.", progress = "Oui, j'ai senti votre arrivée, puissant <classe>. J'espère que vous avez d'autres nouvelles à me donner sur votre chasse ?", completion = "Très impressionnant, &lt;nom&gt;... la griffe de Serres-tranchantes n'a pas dû être facile à se procurer ! La Chasse d'Ashenvale se déroule bien pour vous !\n\nSerres-tranchantes terrorisait depuis longtemps les péons du camp de bûcherons qui essayaient de voyager entre ici et le poste de Bois-brisé. Dès que les gens sauront que c'est vous qui avez défait cette bête, ils composeront sans doute des chants sur votre bravoure, et ils seront chantés dans tous les camps de bûcherons et toutes les scieries d'Ashenvale !", rewards = "Vous recevrez :\n\n"},
[5] = {title = "L'estomac qui gargouille", objective = "Parler au chef Grual.", description = "Je suis resté caché dans cette ville fantôme depuis des semaines.\n\nApportez-moi de quoi festoyer et je vous payerai généreusement.\n\nJ'ai entendu parler d'un certain chef Grual qui fait de succulents gâteaux au crabe brun, à la taverne du Corbeau écarlate à Darkshire...", progress = nil, completion = "Ah ! Vous voulez des gâteaux au crabe, n'est-ce pas ? Bien, je peux peut-être en préparer quelques pour vous...", rewards = "Vous recevrez :\n\n"},
[6] = {title = "La prime pour Garrick Padfoot", objective = "Tuer Garrick Padfoot et rapporter sa tête à l'Adjoint Willem de l'Abbaye du Northshire.", description = "Garrick Padfoot – un brigand qui harcèle les fermiers et les marchands de la région depuis des semaines – a été vu dans une cabane près des vignes qui se trouvent à l'est de l'abbaye, juste après le pont. Rapportez-moi la tête de ce mécréant, et vous empocherez la récompense !\n\nMais soyez <prudent/prudente> <nom>. Garrick a rassemblé une bande de voyous autour de lui. Il ne sera pas aisé de l'approcher.", progress = "Avez-vous trouvé la cabane de Garrick ? Sommes-nous finalement débarrassés de ce scélérat ?", completion = "Ah ! vous l'avez eu. Vous avez rendu un grand service à Elwynn, et gagné une belle prime !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon moulantTunique doubléeCape d'enseigne\n\nVous recevrez également :\n\n"},
[7] = {title = "Nettoyer le camp des kobolds", objective = "Tuer 10 Vermines kobold, puis revenir voir le maréchal McBride.", description = "Votre première tâche est un nettoyage, <nom>. Un clan de kobolds a envahi les bois se trouvant au nord. Allez là-bas et combattez cette vermine. Affaiblissez-la assez, pour qu'un jour nous puissions la repousser hors du Northshire.", progress = nil, completion = "Bien. Ces kobolds sont des voleurs et des lâches, mais en grand nombre ils deviennent dangereux. Et les humains de Stormwind n'ont pas besoin d'une menace de plus.\n\nVous avez toute ma gratitude pour les avoir détruits.", rewards = "Vous recevrez :\n\n"},
[8] = {title = "Un marché de voleur", objective = "Livrer une Lettre à Renée dans les Clairières de Tirisfal.", description = "Hé ! Voudriez-vous faire une faveur à un homme qui a eu plus que sa part de combats contre des zombies et des araignées ?\n\nJ'ai ici une lettre qui doit être livrée à Brill... à une aubergiste du nom de Renée quelque chose. Enfin c'est pas important son nom de famille.\n\nBref, c'est un joli petit coin, plein de personnes victimes de la peste qui essayent de trouver leur voie en ce bas monde. De plus, c’est un bon endroit pour se reposer. Vous devriez aller voir... D'autant que je vous payerai bien.", progress = "Oui ? Oui ? Qu'est-ce que c'est ?\n\nPour une race qui n'a pas besoin de respirer sous l'eau, ils ont vraiment un appétit féroce. Faites comme chez vous... Je m'appelle Renée, si vous avez besoin de quoi que ce soit.", completion = "Comment ? Une lettre ? Magnifique ! J'attends justement des nouvelles de ma chère mère qui habite au Glas. C'est une sainte. Je me demande comment elle va.\n\nHein ? Trop gaie ? Vous ne me croyez pas, hein ?\n\nMêlez-vous de vos affaires alors... Ça ne vous regarde pas. Allez ! Ouste !\n\nRevenez quand vous aurez de l'argent à dépenser... Tire-au-flanc !\n\nVous verrez, vous reviendrez bien vite vous reposer quand vous en aurez assez de courir l'aventure ou après avoir fait des choses aussi stupides dans le même genre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTête de champignon sylvestreEau de source\n\nVous recevrez également :\n\n"},
[9] = {title = "Les champs de mort", objective = "Le Fermier Saldean veut que vous tuiez 20 Gardiens des moissons.", description = "Regardez ce qu'il s'est passé ici ! Ces terres étaient autrefois habitées par de braves fermiers. Mais ces maudits voleurs les ont tous chassés. Pas moi, pour sûr ! Mais il semble que quelques Gardiens des moissons ont pris possession des champs.\n\nSi vous êtes d'accord, j'aimerais que vous y alliez et que vous en détruisiez une vingtaine. Revenez quand vous aurez fini pour recevoir votre dû. Une fois que vous aurez débarrassé ceux de mon champ, occupez-vous des champs alentours.", progress = "Ah ! je vois que vous êtes revenu ! J'espère que vous avez bien fait votre travail et débarrassé les champs des Gardiens des moissons. En avez-vous tué 20 ?", completion = "Beau travail. Vous avez bien mérité votre paye. Qui sait, peut-être qu'un jour la marche de l'Ouest prospérera à nouveau.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon de moissonneurRobe de moissonneur\n\nVous recevrez également :\n\n"},
[10] = {title = "La rédemption de Scrimshank", objective = "Découvrir ce qu'est devenu le géomètre Scrimshank, et rapporter son équipement topographique au grand géomètre Fizzledowser à Gadgetzan.", description = "Oh, c'est terrible ! J'ai envoyé mon premier assistant, le géomètre novice Scrimshank, dans le désert au sud-est d'ici. C'est un endroit appelé le Gouffre béant. Et il est porté disparu. Dans son dernier rapport, il faisait allusion à ces étranges insectes près de là où il était. Serait-il possible qu'ils aient maintenant infesté deux grandes régions du désert ?\n\nJ'ai besoin que vous alliez retrouver Scrimshank dans le Gouffre béant ! Ou, au pire, que vous retrouviez son équipement topographique. Je crains que ce soit tout ce qu'il reste de lui.", progress = "Bien, quelles nouvelles avez-vous ? Vous semblez avoir passé de sales moments... Scrimshank est-il vivant ?", completion = "C'était un brave gobelin, ce jeune Scrimshank. Espérons que les enregistrements de son équipement topographique rendront sa mort moins vaine.\n\nIl semble que le problème des insectes soit encore plus grave que nous le pensions. Ils sont bien trop astucieux pour des insectes et les recherches que nous avons faites jusqu'ici nous amènent à penser qu'ils seraient contrôlés par quelqu'un ! Si c'est le cas, c'est un mauvais présage non seulement pour Gadgetzan, mais pour le désert entier !", rewards = "Vous recevrez :\n\n"},
[11] = {title = "Prime pour les gnolls Rivepatte", objective = "Apporter 8 Brassards peints de gnolls à l'Adjoint Rainer à la Caserne.", description = "Des gnolls, des animaux brutaux qui n'ont rien à faire ici, ont été aperçus à la lisière de la forêt d'Elwynn. C'est un très grand groupe, bien trop nombreux pour que nous nous en occupions seuls. Ils ont envahi les bois au sud de la tour de garde. Un autre groupe à envahi les zones autour du lac du Cairn à l'est.\n\nL'armée de Stormwind engage quiconque pourrait en tuer. Apportez-moi des Brassards peints de gnolls pour me prouver vos actions.", progress = "Bonjour, <nom>. Vous avez tué des gnolls ?", completion = "Je vois que vous avez été sacrément occupé ! Vous avez tous nos remerciements, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge de la milicePantalon de gavroche\n\nVous recevrez également :\n\n"},
[12] = {title = "La milice du peuple", objective = "Tuer 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", description = "La Milice du peuple n'a qu'un seul objectif : défendre la marche de l'Ouest et ramener le calme dans les environs. Malheureusement, le prix de la paix est souvent le sang.\n\nUn de mes éclaireurs rapporte qu'une bande de Trappeurs défias sème le trouble dans le coin. Ils auraient été aperçus près de la Mine de Jangolode, au nord-ouest, ainsi que dans la Ferme des Molsen et la Ferme de potirons des Furlbrow. Si vous voulez rejoindre nos rangs, tuez 15 Trappeurs défias et 15 Contrebandiers défias, puis revenez me voir.", progress = "Peut-être que je ne me suis pas bien fait comprendre. Pour prouver que vous méritez de faire partie de la Milice du peuple et de la Lumière, vous devez impérativement tuer 15 Trappeurs défias et 15 Contrebandiers défias et ne revenir que lorsque vous aurez accompli cela.", completion = "Bien joué, &lt;nom&gt;. Mon éclaireur a été témoin de votre courage et de votre vaillance. Vous avez largement fait vos preuves.", rewards = "Vous recevrez :\n\n"},
[13] = {title = "La milice du peuple", objective = "Tuer 15 Pilleurs défias et 15 Pillards défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", description = "Une bande de pilleurs défias a été vue en train de saccager la carrière de la Côte de l'or ainsi que Ruisselune et la ferme des Alexston. La Milice du peuple n'acceptera pas ce genre de comportement. Déployez-vous immédiatement, <nom>, et faites en sorte que l'on sache que la Lumière est présente dans la marche de l'Ouest.\n\nLa carrière est près de la côte, à l'ouest de la tour. Comme étape de votre instruction, je veux que vous tuiez 15 Pilleurs défias et 15 Pillards défias.", progress = "Nous n'avons pas le temps de discuter, <nom>. Les pilleurs défias empêchent les gens de la marche de l'Ouest de prospérer et de vivre en paix. Débarrassez-nous au moins de 15 Pilleurs défias et de 15 Pillards défias. Le message devrait être assez clair, nous ne voulons pas de cette corruption chez nous.", completion = "Vous avez prouvé votre valeur à la Milice du peuple par vos actes de bravoure.", rewards = "Vous recevrez :\n\n"},
[14] = {title = "La milice du peuple", objective = "Tuer 15 Malandrins défias, 5 Eclaireurs défias et 5 Truands défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", description = "Quelques Défias nous ont échappé. Mon éclaireur le plus fiable fait état de pillages défias dans les campagnes, au sud de la marche de l'Ouest. Nous pensons qu'ils se cachent dans les collines de la Dague, fomentant leur prochain coup. Détruisez ces misérables au nom de la Milice du peuple.", progress = "<nom>, le temps n'est pas aux bavardages inutiles. Si vous voulez prouver votre valeur à la Milice du peuple vous devez tuer les Défias dont je vous ai parlé tout à l'heure. Revenez me voir quand vous aurez accompli votre devoir.", completion = "Quand j'ai quitté les terres impures de Lordaeron, je suis venu faire ce macabre travail, ici, chez moi. Mais il y a encore de l'espoir pour la marche de l'Ouest. Comme vous l'avez prouvé au combat, il est incontestable que vous êtes de notre côté, et que vous servez notre cause avec vaillance. Et c'est avec un grand honneur que je vous accueille au sein de la Milice du peuple. Que la Lumière vous protège.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrande lame de la milice du peupleMarteau de la milice du peupleEclat de la milice du peuple\n\nVous recevrez également :\n\n"},
[15] = {title = "Enquête sur la crête aux échos", objective = "Tuer 10 Ouvriers kobolds, puis revenir faire son rapport au maréchal McBride.", description = "<nom>, mes éclaireurs me rapportent que l'infestation kobold est d'une plus grande envergure que nous le pensions. Un groupe d'ouvriers kobolds a établi son campement près de la mine de la Crête aux échos au nord.\n\nAllez à la mine et faites en sorte qu'il n'y en ait plus. Nous savons qu'il y en a au moins 10. Tuez-les, voyez s'il y en a davantage, et revenez me présenter votre rapport.", progress = nil, completion = "Je n'aime pas ça, tous ces kobolds dans nos mines. Rien de bon ne peut en sortir. Tenez, prenez ceci comme paiement, et quand vous serez prêt, revenez me voir. J'aimerais que vous retourniez une fois de plus dans les mines...", rewards = "Vous recevrez :\n\n"},
[16] = {title = "Procurer de l'eau à Gerard", objective = "Cultiver la terre est un travail difficile et qui donne diablement soif, je suis toujours partant pour un peu d'eau claire et fraîche.\n\nSi vous en avez, eh bien ! je ferai bien affaire avec vous.", description = nil, progress = "Cultiver la terre est un travail difficile et qui donne diablement soif, je suis toujours partant pour un peu d'eau claire et fraîche.\n\nSi vous en avez, eh bien ! je ferai bien affaire avec vous.", completion = "Merci, &lt;nom&gt; ! Et revenez si vous voulez refaire affaire.", rewards = "Vous recevrez :\n\nPomme rouge brillante"},
[17] = {title = "Rechercher les composants à Uldaman", objective = "Apporter 12 Champignons magenta à Ghak Healtouch à Thelsamar.", description = "On a découvert récemment une nouvelle plante : les champignons magenta. Ils poussent en grappes, au plus profond des excavations d'Uldaman ; il en existe peut-être ailleurs, mais je ne connais que cet endroit. Je veux étudier leur utilité éventuelle en alchimie, et c'est là que vous entrez en scène.\n\nTrouvez les Champignons magenta et rapportez-m'en une douzaine. Attention, les grappes peuvent projeter des spores vénéneux quand on les manipule !\n\nRendez-moi ce service et je sortirai pour vous un petit Elixir revigorant de derrière les fagots.", progress = "Vous avez les champignons magenta dont j'ai besoin pour mes travaux ? Pas de champignons, pas de récompense !", completion = "Bon travail, &lt;nom&gt;, vous avez prouvé encore une fois votre valeur ! Cela va vraiment être intéressant d'étudier ces champignons !\n\nEt maintenant, comme promis, appréciez un de mes breuvages les plus revigorants, de ma réserve personnelle...\n\nSi vous êtes un alchimiste compétent, j'aurai peut-être une autre mission pour vous. Quoi qu'il en soit, merci de votre aide !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPotion de restauration"},
[18] = {title = "La confrérie des voleurs", objective = "Apporter 12 Masques rouges à l’Adjoint Willem à l’extérieur de l’Abbaye de Northshire.", description = "Un groupe de voleurs traîne depuis peu autour de Northshire. Ils se nomment eux-mêmes la Confrérie défias, et ont été aperçus de l'autre côté de la rivière à l'est.\n\nJe ne sais pas ce qu'ils préparent, mais il est certain que ce n'est rien de bon ! Apportez-moi les Masques qu'ils portent, et je vous récompenserai d'une arme.", progress = "M'avez-vous déjà ramené les Masques ?", completion = "Je vois que vous revenez avec les Masques. L'armée de Stormwind apprécie votre aide.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague de la miliceMarteau de la miliceEpée courte de la miliceMarteau de guerre de la miliceBâton de la milice\n\nVous recevrez également :\n\n"},
[19] = {title = "Tharil'zun", objective = "Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines.", description = "Les renégats et les estafettes Blackrock tendent des embuscades entre ici et le donjon de Guet-de-pierre. Le chef des estafettes est un orc du nom de Tharil'zun – nous voulons qu'il meure. Rapportez-moi la tête de Tharil'zun !", progress = "La pression des orcs Blackrock est toujours forte. Mais nous avez-vous débarrassés de Tharil'zun ?", completion = "Tharil'zun était un orc vicieux et rusé. Bon travail ! Je suis certain que cela n'a pas été de tout repos. Voici votre récompense, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge en acier trempéConcassorc\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[20] = {title = "La menace des Blackrock", objective = "Rapporter 10 Haches détériorées au maréchal Marris de Lakeshire.", description = "Les orcs Blackrock ont voyagé depuis les Steppes ardentes et ont pris possession du donjon de Guet-de-pierre, depuis le nord. De cette base, ils patrouillent dans toutes les zones au nord de Lakeshire et forcent les citoyens à rester en ville, parqués comme du bétail.\n\nAidez à libérer Lakeshire de cette oppression. Tuez ces orcs Blackrock et rapportez-moi 10 haches détériorées comme preuve de votre réussite.\n\nBien que les orcs Blackrock nous menacent au nord, nous avons des informations disant qu’il y aurait aussi des orcs au sud-est des Carmines. Si vous en trouvez là-bas, tuez-les.", progress = "Avez-vous exterminé les orcs, <nom> ? Si c'est le cas, alors montrez-moi...", completion = "Cela fera autant d'orcs en moins dont se soucier, merci.", rewards = "Vous recevrez :\n\n"},
[21] = {title = "La bataille de la Crête aux échos", objective = "Tuer 12 Travailleurs kobold, puis revenir voir le maréchal McBride, à l’Abbaye de Northshire.", description = "Vos dernières investigations ont prouvé que la mine de la Crête aux échos devait être nettoyée. Retournez-y et chassez les kobolds.\n\nNe perdez pas de temps, <nom>. Plus les kobolds seront tranquilles dans la mine, plus ils renforceront leurs positions dans le Northshire.", progress = nil, completion = "Une fois encore, vous avez gagné mon respect et toute la gratitude de l'armée de Stormwind. Il se peut qu'il reste quelques kobolds dans la mine, mais je vais envoyer d'autres personnes contre eux. J'ai d'autres tâches plus importantes pour vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de tailleurBottes de tailleurGants de tailleur\n\nVous recevrez également :\n\n"},
[22] = {title = "La tourte au foie de Broche-tripes", objective = "Salma Saldean a besoin de 8 Foies de Broche-tripes pour faire une Tourte au foie de Broche-tripes.", description = "Les oignons sont pelés et l'ail émincé. Le romarin est pilé. La pâte est cuite et le fenouil haché. La sauce finit de mijoter. Il ne me manque que 8 foies de Broche-tripes pour réussir ma fameuse tourte à la viande !", progress = "Tout ce dont j'ai besoin pour faire ma fameuse tourte à la viande, c'est de 8 foies de Broche-tripes !", completion = "Ils sont juste comme il faut, &lt;nom&gt; ! Merci beaucoup. Saldean le fermier et moi-même allons faire un festin ce soir. Et tenez, un petit quelque chose pour vous, pour votre peine. Vous ne pensiez tout de même pas que j'allais laisser un &lt;classe&gt; comme vous mourir de faim ?", rewards = "Vous recevrez :\n\nTourte au foie de Broche-tripesRecette : Tourte au foie de Broche-tripes"},
[23] = {title = "La patte d'Ursangous", objective = "Apporter la Patte d'Ursangous à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", description = "La patte du puissant ours Ursangous représente votre trophée pour cette partie de la Chasse d'Ashenvale. Sur la patte figure un petit emblème en forme de croissant de lune, dont la signification reste mystérieuse.\n\nLa Patte doit être apportée à Senani Thunderheart, au Poste de Bois-brisé, comme preuve que vous avez abattu la puissante créature et terminé cette partie de la Chasse.", progress = "Ah, <nom>, je pensais à vous justement ! Et cette chasse ?", completion = "Ha, la patte d'Ursangous ! Votre talent est impressionnant, &lt;classe&gt; ; on dit l'animal meurtrier. Le croissant sur la patte prouve avec certitude qu'il a été entraîné par les elfes de la nuit qui rôdent dans Ashenvale. Ursangous est... était un des plus puissants ours dans ces parages. Avoir battu cette bête est une preuve de votre volonté et de votre résolution.\n\nVos ancêtres seraient fiers !", rewards = "Vous recevrez :\n\n"},
[24] = {title = "La tête de Shadumbra", objective = "Apporter la Tête de Shadumbra à Senani Thunderheart, au Poste de Bois-brisé, dans Ashenvale.", description = "Le rapide et redoutable Shadumbra gît, immobile et silencieux, maintenant que vous l'avez vaincu. La tête du sabre-de-nuit est un trophée de première classe, parfaitement à même de satisfaire les conditions de la Chasse d'Ashenvale. Senani Thunderheart, au Poste de Bois-brisé, aimerait voir un tel trophée pour pouvoir valider cette partie de la Chasse d'Ashenvale.", progress = "Bonjour, <nom> ! Revenez-vous avec la preuve de votre chasse ?", completion = "Une victoire pour &lt;nom&gt; dans la chasse d'Ashenvale ! Bien joué ! La tête de Shadumbra est le trophée qu'il convient de réclamer pour un combat aussi impressionnant, il n'y a pas de doute.\n\nLa sauvagerie de Shadumbra était bien connue par ici. Chaque voyage vers l'ouest, plus spécialement ceux qui se font à pied pour s'éloigner de la grève de Zoram, se faisait avec la menace de ce tigre. Grâce à vous, ce danger ne pèse plus.", rewards = "Vous recevrez :\n\n"},
[25] = {title = "Impasse aux Serres-Rocheuses", objective = "Tuer 12 Elémentaires d’eau corrompus au lac Mystral, à l’est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.\n\nFaire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l’avant-poste de l’Alliance.\n\nRetourner voir Mastok Wrilehiss, au poste de Bois-brisé, dans Ashenvale.", description = "Si vous voulez vous rendre utile, pourquoi n'iriez-vous pas essayer de régler le problème près de la Perce des Serres ?\n\nLes convois entre Ashenvale et les Serres-Rocheuses sont au point mort. En effet, c'est comme si le lac avait pris vie et attaquait tout ce qui s'approche à proximité... c'est à dire quiconque s'aventure sur la Perce. Au lieu de simplement massacrer ces élémentaires d'eau, il serait vraiment utile que quelqu'un aille reconnaître le kiosque du lac Mystral ; celui qui offre une si belle vue sur l'avant-poste de l'Alliance à cet endroit.\n\nAlors, voulez-vous vous rendre utile ?", progress = nil, completion = "Oui, j'ai entendu que quelqu'un avait ravagé les alentours du lac, comme un diable de poussière dans les Tarides. D'après ce que cela m'inspire, nous devrions être capables d'installer un point d'observation dans cette zone, de manière à garder un oeil sur nos amis de l'Alliance. Il faut juste faire cela discrètement...\n\nIl semblerait que vous ayez prouvé votre utilité, au bout du compte. Les transports entre ici et les Serres-rocheuses ne devraient s'en porter que mieux. Prenez ceci, vous l'avez mérité.", rewards = "Vous recevrez :\n\n"},
[26] = {title = "Une leçon à apprendre", objective = "Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", description = "<nom>, j'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir <un véritable gardien et protecteur/une véritable gardienne et protectrice> de la nature.\n\nLe temps est venu pour vous d'en apprendre plus à propos de l'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l'eau. Pour cela, vous devez voyager jusqu'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Starblaze, du Cercle cénarien. Il vous guidera plus avant.", progress = nil, completion = "Salutations, jeune &lt;classe&gt; ; le temps est venu pour vous d'apprendre votre forme aquatique. Elle vous permettra de vous déplacer dans l'eau librement et indéfiniment. Vous trouverez cela utile... mais c'est quelque chose qui doit se mériter avant de pouvoir le maîtriser.\n\nVous allez avoir à passer deux tests. Le premier va tester votre habileté à travailler sous l'eau en situation de stress. Le second va tester votre capacité à comprendre les différents aspects de la forme elle-même.\n\nPréparez-vous, le moment de vous tester est venu.", rewards = "Vous recevrez :\n\n"},
[27] = {title = "Une leçon à apprendre", objective = "Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", description = "<nom>, j'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir <un véritable gardien et protecteur/une véritable gardienne et protectrice> de la nature.\n\nLe temps est venu pour vous d'en apprendre plus à propos de l'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l'eau. Pour cela, vous devez voyager jusqu'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Starblaze, du Cercle cénarien. Il vous guidera plus avant.", progress = nil, completion = "Salutations, jeune &lt;classe&gt; ; le temps est venu pour vous d'apprendre votre forme aquatique. Elle vous permettra de vous déplacer dans l'eau librement et indéfiniment. Vous trouverez cela utile... mais c'est quelque chose qui doit se mériter avant de pouvoir le maîtriser.\n\nVous allez avoir à passer deux tests. Le premier va tester votre habileté à travailler sous l'eau en situation de stress. Le second va tester votre capacité à comprendre les différents aspects de la forme elle-même.\n\nPréparez-vous, le moment de vous tester est venu.", rewards = "Vous recevrez :\n\n"},
[28] = {title = "L'épreuve du lac", objective = "Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.\n\nVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.", description = "Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Elune'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l'un des gardiens les plus fiables de Reflet-de-Lune.\n\nVous devez réussir cette quête avant l'expiration du temps imparti, et vous serez peut-être en concurrence avec d'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.\n\nBonne chance, <nom>.", progress = "Pour mener à bien l'épreuve du lac, vous devez utiliser le Colifichet du sanctuaire dans les limites de cet autel. Tant que ce n'est pas fait, l'épreuve n'est pas terminée et vous risquez l'échec.", completion = "Bien, il semble qu'un &lt;classe&gt; de plus ait réussi à passer l'épreuve du lac ! Bien joué, jeune &lt;classe&gt; - bien joué.\n\nComme je l'ai dit, mon nom est Tajarri. C'est mon devoir et un privilège d'être un Gardien de Reflet-de-Lune, et tout spécialement de ce sanctuaire. Le Gardien Remulos guide le Cercle cénarien pour préserver la nature et l'équilibre, son sanctuaire en est la démonstration. Il prouve l'importance de ce lieu dans le Cercle.", rewards = "Vous recevrez :\n\n"},
[29] = {title = "L'épreuve du lac", objective = "Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.\n\nVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.", description = "Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Elune'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l'un des gardiens les plus fiables de Reflet-de-Lune.\n\nVous devez réussir cette quête avant l'expiration du temps imparti, et vous serez peut-être en concurrence avec d'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.\n\nBonne chance, <nom>.", progress = "Pour mener à bien l'épreuve du lac, vous devez utiliser le Colifichet du sanctuaire dans les limites de cet autel. Tant que ce n'est pas fait, l'épreuve n'est pas terminée et vous risquez l'échec.", completion = "Bien, il semble qu'un &lt;classe&gt; de plus ait réussi à passer l'épreuve du lac ! Bien joué, jeune &lt;classe&gt; - bien joué.\n\nComme je l'ai dit, mon nom est Tajarri. C'est mon devoir et un privilège d'être un Gardien de Reflet-de-Lune, et tout spécialement de ce sanctuaire. Le Gardien Remulos guide le Cercle cénarien pour préserver la nature et l'équilibre, son sanctuaire en est la démonstration. Il prouve l'importance de ce lieu dans le Cercle.", rewards = "Vous recevrez :\n\n"},
[30] = {title = "L'épreuve du lion de mer", objective = "Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.\n\nReformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.\n\nApporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", description = "Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L'autre moitié emprunte à l'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.\n\nAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Starblaze.", progress = "Avez-vous assemblé le pendentif pour que je puisse le vérifier, <nom> ? Si vous avez besoin d'aide pour trouver les morceaux, essayez d'interroger la population locale. Non seulement cela vous mènera à ce que vous cherchez mais cela vous donnera de surcroît un prétexte pour explorer ces magnifiques contrées sacrées.", completion = "Vous avez réussi l'épreuve du lion de mer, &lt;nom&gt;, félicitations.\n\nChacune des tâches nécessaires pour acquérir le pendentif souligne que l'agilité et l'endurance doivent agir en harmonie lorsque l'on se trouve sous l'eau. L'une ne peut pas exister sans l'autre, et les deux ne peuvent être sans votre détermination à comprendre les différents aspects du lion de mer.\n\nRappelez-vous bien ces leçons, et comptez sur elles une fois que vous aurez obtenu votre forme aquatique.", rewards = "Vous recevrez :\n\n"},
[31] = {title = "Forme aquatique", objective = "Retourner à Thunder Bluff et montrer le Pendentif du lion de mer à Turak Runetotem.", description = "Vous avez terminé les leçons nécessaires, enseignées à tous les jeunes druides avant qu'ils ne puissent adopter un aspect aquatique. Retournez voir votre Maître, Turak Runetotem, à Thunder Bluff. Présentez-lui votre pendentif et montrez-lui que vous êtes en mesure d'apprendre ce qu'il est prêt à vous enseigner. Il veillera à parachever votre entraînement, vous permettant de revêtir une forme aquatique.\n\nAu revoir, jeune druide. Nous nous reparlerons plus tard.", progress = "Votre retour à Thunder Bluff m'a été annoncé, cependant je vais avoir besoin d'une preuve comme quoi vous avez étudié à Reflet-de-Lune avant de vous enseigner votre forme aquatique.\n\nAvez-vous le Pendentif du lion de mer ?", completion = "Très impressionnant, &lt;nom&gt;. Vos ancêtres seraient ravis de vos progrès ! Vous pouvez maintenant acquérir votre forme aquatique, et cela sera un plaisir pour moi de vous l'enseigner.\n\nDe plus, pour votre performance lors des deux dernières épreuves, je vous offre cet objet. J'espère qu'il vous sera utile dans votre rôle de protecteur de la nature et de gardien de l'équilibre.", rewards = "Vous allez être la cible du sort suivant :\n\nForme aquatique\n\nVous recevrez :\n\nCeinture du Verseau"},
[32] = {title = "L'ascension des silithides", objective = "Apporter le rapport à Zilzibin Drumlore à Orgrimmar.", description = "Voici votre rapport. Je vous demande de l'apporter de toute urgence à quelqu'un qui a de l'expérience dans ce domaine.\n\nJe connais un troll érudit du nom de Zilzibin Drumlore. Il a passé beaucoup de temps à étudier les formes de vie exceptionnelles de l'écologie d'Azeroth ; de plus, c'est un historien ! Si vous voulez rencontrer quelqu'un capable de comprendre la nature de ce danger et comment l'arrêter, apportez-lui ce rapport. Nous allons avoir besoin de toute l'aide disponible.\n\nZil réside dans une maison sur le second tiers de la Herse, à Orgrimmar.", progress = "Veuillez m'excuser, je ne vous connais pas... Mais il semble que vous, vous avez entendu parler de moi. Maintenant, comment puis-je vous aider ? Avez-vous quelque chose pour moi ?", completion = "Oui… J'ai déjà eu affaire à ces bêtes dans le passé. Fizzledowser a été bien avisé de vous envoyer avec ce rapport.\n\nCes créatures vont consumer le désert de Tanaris très rapidement. Elles ne sont rien de moins que l'un des plus grands dangers auxquels nous aurons jamais à faire face. Retenez ce nom, &lt;nom&gt; : les silithides. Les insectes mentionnés ici sont des silithides et ce sont les instruments de l'une des plus grandes menaces que l'Alliance et la Horde affronteront jamais.\n\nSi seulement nous avions été plus perspicaces.", rewards = "Vous recevrez :\n\n"},
[33] = {title = "Les loups derrière la frontière", objective = "Apporter 8 pièces de Viande de loup coriace à Eagan Peltskinner, à l’extérieur de l’Abbaye de Northshire.", description = "J'ai horreur de ces maudits loups des bois ! Mais j'aime beaucoup en déguster des steaks… Apportez-moi de la viande de loup coriace et je vous donnerai en contrepartie quelque chose que vous devriez trouver utile.\n\nOn peut trouver de la viande de loup coriace en chassant les loups des bois et les jeunes loups qui parcourent la campagne de Northshire.", progress = "Hé <nom>. J'ai faim… vous avez trouvé de la viande de loup coriace ?", completion = "Ça n'a pas dû être facile ! Je n'en peux plus d'attendre pour cuisiner cette viande de loup...\n\nJ'ai des choses ici qui peuvent vous intéresser : faites votre choix !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChaussures bordées de fourrureBrassards en peau de loup\n\nVous recevrez également :\n\n"},
[34] = {title = "Un indésirable", objective = "Martie Jainrose de Lakeshire veut que vous tuiez Fouailleventre. Ramenez-lui ses défenses comme preuve.", description = "Mes jardins ont encore été saccagés. Et je connais le responsable. C'est ce satané sanglier, celui que le maréchal Marris appelle Fouailleventre.\n\nJe ne vais pas pouvoir replanter mes jonquilles avant la prochaine saison maintenant. Ruinée ! Je suis complètement ruinée à cause de ce sanglier ! Mettez un terme à cette nuisance ! Montrez-moi ses défenses et je serai heureuse de vous récompenser. Il semble qu'il passe son temps dans les champs au sud-ouest de Lakeshire, mais il vagabonde de temps en temps jusque dans mon jardin.", progress = "Fouailleventre est-il toujours en vie, ou avez-vous débarrassé Lakeshire de cette nuisance une bonne fois pour toutes ?", completion = "Finalement, ce danger public a disparu ! Merci, &lt;nom&gt;, vous m'avez rendu un immense service. Le jardin va être plein de fleurs cette saison !", rewards = "Vous recevrez :\n\nBouquet de bégonias écarlates"},
[35] = {title = "Inquiétudes supplémentaires", objective = "Le maréchal Dughan veut que vous parliez au garde Thomas.", description = "Si vous voulez savoir si les rumeurs concernant les murlocs sont vraies, allez donc au pont, à l'est d’Elwynn et parlez au garde Thomas. Il y est en poste depuis une semaine, il saura de quoi il retourne.\n\nRamenez-moi son compte rendu.", progress = nil, completion = "Oui, les murlocs se sont installés sur la rive est de l'Elwynn. Nous ne savons pas pourquoi ils sont là, mais ils sont agressifs et ont une certaine forme d'intelligence.", rewards = "Vous recevrez :\n\n"},
[36] = {title = "Le ragoût de la marche de l'Ouest", objective = "Verna Furlbrow veut que vous apportiez la Recette du ragoût de la marche de l'Ouest à Salma Saldean.", description = "Je n'avais jamais pensé un jour quitter ma ferme. Mais les champs grouillent de voleurs, et cela devient vraiment trop dangereux pour nous. Dès que la charrette du Fermier Furlbrow sera réparée, nous partirons. \n\nVous pourriez peut-être me faire une faveur? Laissez-moi écrire la recette du ragoût de la marche de l'Ouest. S'il vous plaît, apportez-la à Salma Saldean à la ferme de l'autre côté, là-bas. La ferme des Saldean est un peu plus loin sur la route, juste après l'embranchement.", progress = "Verna Furlbrow va beaucoup me manquer. Je suppose que vous ne l'avez pas vue en venant ?", completion = "Verna a toujours été une bonne amie. Elle nous manquera, mais de vous à moi, c'est une citadine dans l'âme et Stormwind lui conviendra parfaitement. Bon, assez bavardé ! Maintenant nous pouvons faire du ragoût de la marche de l'Ouest !", rewards = "Vous recevrez :\n\n"},
[37] = {title = "Trouver les gardes disparus", objective = "Le garde Thomas veut que vous alliez vers le nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai.", description = "Il y a quelques jours, j'ai envoyé deux gardes, Rolf et Malakai, patrouiller le long de la rivière, et ils ne sont toujours pas revenus. Afin de finaliser mon rapport, je dois absolument savoir ce qu'il est advenu de ces hommes.\n\nAllez vers le nord, le long de la rivière, et trouvez les gardes... ou ce qu'il en reste.", progress = nil, completion = "Bien que le corps ait été presque entièrement dépouillé, un médaillon se trouve à proximité, avec les mots \"Fantassin Malakai Stone\" gravés dessus.", rewards = "Vous recevrez :\n\n"},
[38] = {title = "Le ragoût de la marche de l'Ouest", objective = "Salma Saldean veut 3 morceaux de Viande filandreuse de vautour, 3 Groins de Broche-tripes, 3 Yeux de murloc et 3 Okras.", description = "Aidez-moi à faire du ragoût de la marche de l'Ouest. Ramenez les ingrédients suivants : \n\n 3 morceaux de Viande filandreuse de vautour ; \n 3 Groins de Broche-tripes ; \n 3 Yeux de murloc ; \n 3 Okras.", progress = "Rapporter les ingrédients suivants : \n\n 3 morceaux de Viande filandreuse de vautour ; \n 3 Groins de Broche-tripes ; \n 3 Yeux de murloc ; \n 3 Okras.", completion = "Cet okra va bien épaissir le bouillon ! Maintenant nous rajoutons la Viande filandreuse de vautour, quelques Yeux de murloc et ces délicieux Groins de Broche-tripes. Et voilà ! Pour votre aide, &lt;nom&gt;, j'aimerais que vous goûtiez la première portion du ragoût de la marche de l'Ouest !", rewards = "Vous recevrez :\n\nRagoût de la marche de l'OuestRecette : Ragoût de la marche de l'OuestMitaines de SalmaCouteau de cuisine"},
[39] = {title = "Remettre le rapport de Thomas", objective = "Avertir le maréchal Dughan de Goldshire.", description = "Allez annoncer au maréchal Dughan la mort de Malakai et de Rolf, et prévenez-le que les murlocs à l'est d'Elwynn ne pourront pas être contenus par les troupes présentes actuellement.\n\nJe sais que nous n’avons pas beaucoup de troupes disponibles, mais Dughan trouvera une solution.", progress = nil, completion = "Hum ! Encore des ennuis. Déjà que nos défenses sont bien minces, perdre Rolf et Malakai à cause de ces murlocs nous place dans une position encore plus délicate.\n\nSi les choses ne s'arrangent pas, il y aura des combats à Goldshire avant la fin de cette semaine !", rewards = "Vous recevrez :\n\n"},
[40] = {title = "Péril en la rivière", objective = "Remy \"Deux fois\" veut que vous parliez au maréchal Dughan à Goldshire.", description = "<nom>, il y a une nouvelle menace dans la forêt d'Elwynn ! Les murlocs remontent le cours est de l'Elwynn, effrayant les poissons et attaquant des personnes innocentes !\n\nJ'ai averti le maréchal Dughan, mais il est plus préoccupé par les gnolls et les bandits. Il n'est pas convaincu que les murlocs représentent un réel danger.\n\nS'il vous plaît, <nom>, parlez à Dughan et persuadez-le d'envoyer des renforts à l'est !", progress = nil, completion = "C'est exact, j'ai parlé avec Remy. Je le respecte en tant que marchand, cependant tous les rapports parlant de murlocs à l'est sont pour le moins incomplets.\n\nJe prends en compte vos inquiétudes, mais tant que je n'obtiens pas un rapport militaire sur l’activité des murlocs, nous ne pouvons nous permettre d'envoyer plus de troupes à l'est.", rewards = "Vous recevrez :\n\n"},
[45] = {title = "La destinée de Rolf", objective = "Fouiller le village des murlocs pour trouver Rolf ou des traces de sa mort.", description = "En fouillant un peu plus dans la zone, vous tombez sur des traces de pas palmés qui mènent vers l'est, le long de la rive du lac du Cairn. Légèrement plus loin, vous apercevez un village murloc.\n\nPeut-être que le destin de Rolf s'est arrêté ici...", progress = nil, completion = "Vous trouvez un corps, et autour de son cou un médaillon sur lequel est gravé \"Fantassin Rolf Hartford.\"", rewards = "Vous recevrez :\n\n"},
[46] = {title = "Des primes pour les murlocs", objective = "Ramener 8 Ailerons de murloc au garde Thomas au Pont est d'Elwynn.", description = "L'armée de Stormwind a mis à prix la tête des rôdeurs et des fourrageurs murlocs qui se trouvent à Elwynn. Tuez-les, découpez leurs ailerons et ramenez-les-moi, l'armée de Stormwind vous récompensera.\n\nLes murlocs ont construit un village au lac du Cairn au nord d'ici, et un autre au sud, là où la rivière se sépare.", progress = "Alors, comment s'est passée la chasse, <nom> ?", completion = "Vous avez les ailerons ? Bien ! Le maréchal Dughan s'inquiète des actions des murlocs dans l'est d'Elwynn, et je voudrais lui dire que la situation est sous contrôle maintenant.\n\nEt c'est grâce à ce que vous avez fait.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLongue baïonnetteSolide masse en métalEpée de taille\n\nVous recevrez également :\n\n"},
[47] = {title = "L'échange de poussière d'or", objective = "Rapporter 10 Poussières d'or à Remy \"Deux fois\" à Goldshire. La Poussière d'or se récupère sur les kobolds dans la forêt d'Elwynn.", description = "Par ici les kobolds transportent quelquefois de la poussière d'or sur eux. Cela peut m'être très utile : rapportez-m'en et je vous en donnerai le meilleur prix de la ville ! Le meilleur prix de la ville !\n\nVous trouverez des kobolds dans la mine de Fargodeep, au sud, et autour de la mine de Jasperlode au nord-est.", progress = "Psst ! Vous avez de la poussière d'or pour moi... pour moi ?", completion = "Merci pour l'or, &lt;nom&gt;. Voilà votre argent, et… un petit cadeau de la part de mes associés. Il pourra vous être utile... utile.", rewards = "Vous recevrez :\n\nSac de billes"},
[48] = {title = "Doux whisky", objective = "Rapporter de l'Eau de source sacrée à Grimbooze Thunderbrew.", description = "Dans la campagne du Sud, là où la vigne pousse, en rampant et se tordant\nSe cache un puits où l'eau coule profondément\nAussi pure que la Sœur sacrée de la Lumière, elle est\nApportez-moi un peu de cette eau sacrée.", progress = "Hic ! Oh ! Oh ! Je vous le répète?\n\nDans la campagne du Sud, là où la vigne pousse, en rampant et se tordant\nSe cache un puits où l'eau coule profondément\nAussi pure que la Sœur sacrée de la Lumière, elle est\nApportez-moi un peu de cette eau de source sacrée.", completion = "Hic ! Oh ! Oh !", rewards = "Vous recevrez :\n\n"},
[49] = {title = "Doux whisky", objective = "Grimbooze Thunderbrew veut un Sac d'orge, un Sac de seigle et un Sac de maïs.", description = "Le whisky, de ma vie est le plus ancien amour\nComme les étoiles qui durent pour toujours\nRapportez-moi, pour que mon amour revienne majestueux tel un aigle\nUn sac de chacune de ces céréales : orge, maïs et seigle.", progress = "Encore ? Bien sûr !\n\nLe whisky, de ma vie est le plus ancien amour\nComme les étoiles qui durent pour toujours\nRapportez-moi, pour que mon amour revienne majestueux tel un aigle\nUn sac de chacune de ces céréales : orge, maïs et seigle.", completion = "Hic ! Oh ! Oh !", rewards = "Vous recevrez :\n\n"},
[50] = {title = "Doux whisky", objective = "Grimbooze Thunderbrew veut du Vrai-argent.", description = "Je mélangerai et mélangerai, jusqu'à de la pulpe obtenir\nPour que ce soit notre petit cache sans faiblir\nEn métal solide, il faut que cela soit fait\nPour me permettre de finir cette chanson, du vrai-argent il faut me rapporter.", progress = "Encore une fois pour vous ? Mais bien sûr !\n\nJe mélangerai et mélangerai, jusqu'à de la pulpe obtenir\nPour que ce soit notre secret sans faiblir\nEn métal solide, il faut que cela soit fait\nPour me permettre de finir cette chanson, du vrai-argent il faut me rapporter.", completion = "Hic ! Oh ! Oh !", rewards = "Vous recevrez :\n\n"},
[51] = {title = "Doux whisky", objective = "Apporter une Branche de sycomore à Grimbooze Thunderbrew.", description = "Pas encore filtré, mais déjà distillé\nComme une terre inconnue attendant d'être trouvée\nPuis pour faire un tas de charbon il faut être actif\nLivrez-moi une branche de sycomore, ceci est votre objectif.", progress = "Un rappel ? Mais bien sûr, tout ce que vous voulez !\n\nPas encore filtré, mais déjà distillé\nComme une terre inconnue attendant d'être trouvée\nPuis pour faire un tas de charbon il faut être actif\nLivrez-moi une branche de sycomore, ceci est votre objectif.", completion = "Hic ! Oh ! Oh !", rewards = "Vous recevrez :\n\n"},
[52] = {title = "Protéger la frontière", objective = "Tuer 8 Rôdeurs et 5 Jeunes ours des forêts, et revenir voir le garde Thomas au pont, à l'est d’Elwynn.", description = "Salutations, <nom>. Les animaux sauvages deviennent de plus en plus agressifs à mesure que l'on s'éloigne de Goldshire, et le camp de bûcherons du Val d'est subit de perpétuelles attaques de la part de loups et d'ours !\n\nNous pourrions avoir besoin de votre aide.", progress = "Avez-vous tué ces ours et ces loups ?", completion = "Merci de votre aide, &lt;nom&gt;. Il doit y avoir quelque chose dans la forêt qui rend ces animaux si hardis.\n\nQuoi qu'il en soit, j'espère que ça va en rester là.", rewards = "Vous recevrez :\n\nPotion de soins inférieure"},
[53] = {title = "Doux whisky", objective = "Apporter un Fagot de chêne à Grimbooze Thunderbrew.", description = "Douce eau aussi translucide que des larmes d'enfant\nUne merveilleuse et profonde couleur ambre prend avec le temps\nMais avant de nous saouler\nUn fût de chêne doit être fabriqué.", progress = "Bien sûr, je la chante encore pour vous !\n\nDouce eau aussi translucide que des larmes d'enfant\nUne merveilleuse et profonde couleur ambre prend avec le temps\nMais avant de nous saouler\nUn fût de chêne doit être fabriqué.", completion = "Vieilli en fût, et par le charbon filtré\nIl passe sur vos lèvres, pour ensuite votre esprit transpercer.\nMaintenant buvons, pour vous un toast portons\nEt tant que vous êtes là, un toast pour Grimbooze Thunderbrew aussi portons !", rewards = "Vous recevrez :\n\nFlacon de botte de Thunderbrew"},
[54] = {title = "Rapport pour Goldshire", objective = "Apporter les documents du maréchal McBride au maréchal Dughan de Goldshire.", description = "<nom>, vous êtes un <classe> indubitablement impliqué dans la sûreté de Northshire. Vous avez maintenant en charge la protection de la zone entourant la forêt d'Elwynn.\n\nSi vous acceptez cette responsabilité, j'ai préparé tous les documents qui doivent être apportés au maréchal Dughan à Goldshire. Goldshire se situe le long de la route sud, au-delà de la frontière.", progress = "Vous avez des nouvelles de McBride ? Northshire est un jardin d'enfant comparé à la forêt d'Elwynn, mais je me demande de quoi le maréchal McBride veut m'informer.\n\nBien, laissez-moi jeter un coup d'œil sur ces documents...", completion = "Bien, cela dit que vous avez été promu au grade d'Adjoint des maréchaux de Stormwind. Félicitations.\n\nEt bonne chance – assurer la sécurité d'Elwynn n'est pas une partie de plaisir... Comment faire avec une armée complètement débordée, pour savoir qui fait quoi et pour quel noble !\n\nIl est difficile de garder une politique cohérente en cette sombre époque...", rewards = "Vous recevrez :\n\nBouclier du lancier"},
[55] = {title = "Morbent Fel", objective = "Utiliser le Fléau de Morbent sur Morbent Fel, tuer Morbent Fel, puis rapporter le Fléau de Morbent à Sven, dans son camp.", description = "Morbent Fel se cache dans son repaire, la maison perchée sur la colline à l'est, celle qui domine le cimetière de Colline-aux-Corbeaux. Son temps sur cette terre touche à sa fin...\n\nUtilisez le Fléau de Morbent contre lui. Il réduira à néant ses magies protectrices.\n\nTuez-le. Tuez-le et libérez-nous de sa cruauté. Soyez le bras armé de ma vengeance et <le héros/l'héroïne> du bois de la Pénombre !", progress = "Morbent Fel est-il vaincu ?", completion = "Morbent Fel a été vaincu. Les Cavaliers noirs sont toujours nombreux, mais nous avons maintenant une étincelle d'espoir.\n\nVous avez réussi l'impossible, votre acte de bravoure restera à jamais gravé dans les légendes du bois de la Pénombre.\n\nAllez, &lt;nom&gt;. Et peut-être qu'un jour, le destin nous réunira de nouveau...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon de veilleurCape de maître du guetCamail en métal étincelant\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nTorche de la sainte flamme"},
[56] = {title = "Les Veilleurs", objective = "Le commandant Althea Ebonlocke de Darkshire veut que vous tuiez 8 Guerriers squelettes et 6 Mages squelettes.", description = "En tant que commandant des Veilleurs, et de par mon serment, il est de mon devoir de protéger les citoyens de Darkshire. Stormwind a rappelé les gardes qui étaient en faction ici, nous laissant nous débrouiller par nous-mêmes.\n\nCe serait un acte noble de votre part si vous nous aidiez, car nous en avons terriblement besoin ! Aidez les Veilleurs. Aventurez-vous dans les Jardins paisibles, juste au sud de Darkshire, et tuez 8 guerriers squelettes, ainsi que 6 mages squelettes. Les morts-vivants doivent être contrecarrés !", progress = nil, completion = "Merveilleux, &lt;nom&gt;. Nous vous récompenserons pour le service que vous avez rendu au peuple de Darkshire.", rewards = "Vous recevrez :\n\n"},
[57] = {title = "Les Veilleurs", objective = "Le commandant de Darkshire, Althea Ebonlocke, veut que vous tuiez 15 Démons squelettes et 15 Squelettes infernaux.", description = "<nom>, on vient juste de me rapporter que la forêt était envahie de morts-vivants ! Si vous êtes d'accord pour le faire, voyagez jusqu'au cimetière de Colline-aux-Corbeaux et tuez 15 de ces infâmes démons squelettes et 15 squelettes infernaux. Mes informateurs me disent que des squelettes ont aussi été repérés au sud de Darkshire, autour et dans le cimetière des Jardins paisibles. Les morts-vivants doivent être repoussés hors du bois de la Pénombre !", progress = nil, completion = "Le peuple de Darkshire vous remercie, &lt;nom&gt;. Vous avez prouvé que vous étiez une personne de confiance pour les Veilleurs.", rewards = "Vous recevrez :\n\n"},
[58] = {title = "Les Veilleurs", objective = "Le commandant de Darkshire, Althea Ebonlocke, veut que vous tuiez 20 Répandeurs de peste dans le mausolée est de Colline-aux-Corbeaux.", description = "La situation reste préoccupante à Colline-aux-Corbeaux. La sûreté de Darkshire est entre vos mains, <nom>. Je n'ai pas assez de Veilleurs pour protéger la ville. Nous avons encore besoin de vous. Allez à Colline-aux-Corbeaux pour débarrasser le mausolée est de 20 répandeurs de peste !", progress = nil, completion = "Au nom du peuple de Darkshire et en tant que Chef des Veilleurs, je vous remercie, &lt;nom&gt;, pour votre courage et votre dévouement. Que la Lumière éclaire votre chemin !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBesace des VeilleursCarquois des VeilleursSacoche des Veilleurs\n\nVous recevrez également :\n\n"},
[59] = {title = "Les armures de cuir et d'étoffe", objective = "Donner le Bon pour une pièce d'armure de Stormwind à Sara Timberlain.", description = "Pour récompenser votre perspicacité et votre bravoure, j'ai ici un Bon pour une pièce d'armure de Stormwind. Allez trouver Sara Timberlain, au Camp de bûcherons du Val d'est. Donnez-lui ce bon et elle vous fabriquera une armure. Une fois que vous l'aurez, <nom>, utilisez-la pour défendre Elwynn.\n\nLe Camp de bûcherons du Val d'est est au-delà du poste de garde de Thomas, vers l'est.", progress = "L'armée de Stormwind m'a chargé de fournir ses troupes en vêtements et en armures de cuir.\n\nSi vous avez un Bon, je serais ravie de faire quelque chose pour vous.", completion = "Ah ! merci pour le Bon. Choisissez l'armure de votre choix.\n\nBonne chance, brave &lt;classe&gt;. J'espère que cette armure vous sera utile.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe de confectionPantalon raccommodé\n\nVous recevrez également :\n\n"},
[60] = {title = "Les bougies de kobolds", objective = "Rapporter 8 Grandes bougies à William Pestle de Goldshire.", description = "Bonjour, <cher monsieur/ma dame> ! Auriez-vous une seconde ?\n\nMon frère et moi sommes apothicaires à Stormwind, et je suis ici pour acheter des grandes bougies, afin d'utiliser leur cire. Pourriez-vous m'aider ?\n\nLes kobolds produisent ces grandes bougies, et j'ai entendu dire qu’ils infesteraient les mines d'Elwynn... La mine de Fargodeep au sud et la celle de Jasperlode à l'est. Je vous suggère d'aller me chercher ces bougies là où elles se trouvent.", progress = "Avez-vous déjà récupéré les bougies ?", completion = "Ça vous a occupé de chasser les kobolds, n'est-ce pas ? Merci pour les bougies, &lt;nom&gt;, voilà votre récompense...", rewards = "Vous recevrez :\n\nBâton de cire luminescent"},
[61] = {title = "Une cargaison pour Stormwind", objective = "Livrer la Cargaison de William à Morgan Pestle dans le Quartier commerçant de Stormwind.", description = "Mon frère Morgan attend ma cargaison de bougies à Stormwind. Je n'ai pas le temps de faire le voyage moi-même, mais si vous livrez la cargaison à ma place, il vous payera bien.\n\nJ'ai empaqueté les bougies, et vous pouvez trouver Morgan à notre magasin, les Apothicaires Pestle, dans le Quartier commerçant de Stormwind.", progress = "Oh ! une cargaison envoyée par mon frère. Splendide ! La chance est avec moi aujourd'hui !", completion = "Voilà votre argent... Et pendant que vous êtes là, jetez un coup d'œil ! Je suis sûr qu'il doit y avoir une petite potion ou une babiole quelconque qui vous intéressera.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRoquette explosiveHuile d'OlafElixir de force du lion\n\nVous recevrez également :\n\n"},
[62] = {title = "La mine de Fargodeep", objective = "Explorer la mine de Fargodeep, puis revenir voir le maréchal Dughan de Goldshire.", description = "Le Northshire n'est pas la seule région à avoir des problèmes avec ses mines ! J'ai des rapports disant que la mine de Fargodeep à Elwynn est aussi infestée de kobolds.\n\nAllez explorer la mine afin de confirmer ces rapports, puis revenez me voir. Elle se situe au sud de Goldshire, entre les propriétés des Stonefield et des Maclure.", progress = nil, completion = "Ce sont de mauvaises nouvelles. Quoi d'autre, des dragons ? Nous devons intensifier les patrouilles près de cette mine. Merci de vos efforts, &lt;nom&gt;. Attendez une minute... J'ai peut-être une autre mission pour vous.", rewards = "Vous recevrez :\n\n"},
[63] = {title = "L'appel de l'eau", objective = "Vaincre la Manifestation d'eau corrompue et placer les Bracelets de manifestation corrompue avec le reste d'eau pure sur le brasero d'Everfount dans la forêt des Pins argentés.", description = "Le long de la côte de la forêt des Pins argentés, à l'ouest du Sépulcre, vous trouverez un autel qui a été corrompu. Les esprits n'y parlent plus aux gens. Vous devez résoudre le problème en purifiant l'autel.\n\nPrenez ces bracelets élémentaires et la potion de Brine, placez-les sur le brasero de l’autel. Ce rituel devrait suffire à invoquer un esprit pur à qui vous pourrez parler.\n\nRamenez-moi une preuve de votre réussite, et je vous récompenserai avec un totem.", progress = "Le brasero réfléchit encore la lumière ambiante et les flammes ondulent un peu alors que vous approchez.\n\nLa corruption des collines semble gardée à distance. En dehors des éléments nécessaires, tout semble prêt pour l’accomplissement du rituel de purification et l'invocation d'une manifestation d'eau purifiée.", completion = "Vous placez les bracelets au milieu du brasero, puis versez la potion de Brine dans les flammes. Les gouttes crépitent lorsqu'elles tombent dans le feu et vous commencez à entonner les mots simples de l'incantation que vous a appris Islen.", rewards = "Vous recevrez :\n\n"},
[64] = {title = "Le cadeau oublié", objective = "Le fermier Furlbrow désire que vous retrouviez sa Montre qui se trouve dans la penderie de sa ferme près du champ de citrouilles à l'ouest.", description = "C'était horrible ! Verna m'a réveillé quand elle a entendu du grabuge dans les champs. Ils étaient envahis par des vandales. Nous nous sommes enfuis à toutes jambes, du coup j'ai oublié ma montre sur place. Le père de Verna me l'avait offerte pour notre mariage et je suis malade de savoir qu'elle est entre les mains de ces voleurs. J'ai laissé ma montre dans la penderie à la ferme. Cherchez le champ de citrouilles à l'ouest – vous ne pouvez pas le manquer. Si vous me la ramenez, je saurais être reconnaissant !", progress = "Je suppose que vous n'avez pas retrouvé ma montre ?", completion = "Ma montre ! Merci beaucoup, cher Monsieur ! \n\nNous sommes de pauvres paysans et nous avons perdu nos terres, mais acceptez quand même ceci en témoignage de notre reconnaissance.", rewards = "Vous recevrez :\n\nPain sorti du fourLait glacé"},
[65] = {title = "La Confrérie défias", objective = "Gryan Stoutmantle veut que vous parliez à Wiley à Lakeshire.", description = "La bande de misérables, responsable de la fuite des honnêtes gens de la marche de l'Ouest, se fait appeler la Confrérie défias. J'ai besoin de vous pour infiltrer ces voyous. Nous devons connaître l'identité de leur chef et où ils sont basés. À Lakeshire, il y a un voleur nommé Wiley à l'auberge qui me doit une faveur.\n\nAllez jusqu'à Lakeshire dans les Carmines, à l'est d'Elwynn, et trouvez ce que vous pouvez.", progress = nil, completion = "Alors, c'est Stoutmantle qui vous envoie ? Eh bien ! je lui dois une faveur.", rewards = "Vous recevrez :\n\n"},
[66] = {title = "La légende de Stalvan", objective = "Aller voir le Greffier Daltry à la mairie de Darkshire.", description = "La nuit dernière, j'ai eu un mauvais pressentiment concernant ma petite-fille Alyssa. Elle serait en grand danger. J'ai tiré les cartes et la lame de la Faucheuse est sortie.\n\nAprès une longue et sombre transe, j’ai obtenu un indice. Un nom est apparu : Stalvan.\n\nAllez voir un greffier de la mairie et trouvez plus de détails sur ce personnage. J'ai peur pour tout le monde…", progress = nil, completion = "Donc Madame Eva vous envoie…", rewards = "Vous recevrez :\n\n"},
[67] = {title = "La légende de Stalvan", objective = "Voyager jusqu'à l'école de Ruisselune et rapporter des informations récentes sur Stalvan au Greffier Daltry.", description = "Stalvan, hein ? Laissez-moi vérifier dans les registres de la ville.\n\nStalvan. Stalvan…Voyons voir. Ah ! nous y voilà. J'ai la trace d'un certain M. Stalvan Mistmantle. Sa dernière adresse connue est l'école de Ruisselune. Enfin, mon registre date un peu !\n\nFaites-moi une faveur, si vous allez à Ruisselune, renseignez-vous sur cette personne. Que je puisse mettre à jour mon registre.", progress = nil, completion = "La vieille caisse s'ouvre en grinçant…", rewards = "Vous recevrez :\n\n"},
[68] = {title = "La légende de Stalvan", objective = "Rapporter la lettre poussiéreuse au greffier Daltry.", description = "Vous trouvez une lettre poussiéreuse dans la vieille caisse.", progress = "Oui, je me souviens de vous. Vous êtes une des personnes qui se renseignaient sur Stalvan. Avez-vous finalement trouvé ce que vous cherchiez ?", completion = "Intéressant. Donc ce gars a passé quelque temps à Ruisselune finalement. C'est quand même bizarre que cette lettre n'ait jamais été envoyée. Quoi qu'il en soit, je peux mettre à jour mon registre.", rewards = "Vous recevrez :\n\n"},
[69] = {title = "La légende de Stalvan", objective = "Aller à l'Auberge de la Fierté du lion pour apprendre si quelqu'un a entendu parler de Stalvan.", description = "Oh non ! J'ai dû manquer ça la première fois. Dans le registre, juste en dessous de l’adresse notée pour Stalvan, il y en a une autre partiellement effacée. Il semble qu’il s’agisse de l'auberge de la Fierté du lion à Goldshire. J'aimerais vérifier cela, <nom>.", progress = nil, completion = "Stalvan ? Clair que cela me dit quelque chose.", rewards = "Vous recevrez :\n\n"},
[70] = {title = "La légende de Stalvan", objective = "Retrouver la Vieille lettre de Stalvan dans le coffre et la remettre au quartier du Canal à Stormwind.", description = "Oui, effectivement, je me rappelle de Stalvan !\n\nIl y a quelques années, lors d'une nuit d'orage, un messager est venu, à la recherche d'un abri pour la nuit. Vers minuit, l'homme a dévalé les escaliers en hurlant, le visage terrifié. Il était toujours en pyjama quand il a disparu en courant sous la pluie torrentielle.\n\nDans sa précipitation, il a oublié ses lettres dans le coffre à l'étage. Il n'est jamais revenu. Une des lettres était adressée au quartier du Canal à Stormwind. Prenez-la si vous le voulez.", progress = "Qu'est-ce que vous avez là ? Laissez-moi jeter un coup d'œil…", completion = "Vous avez du toupet d'apporter ça ici.", rewards = "Vous recevrez :\n\n"},
[71] = {title = "Faire son rapport au garde Thomas", objective = "Rapporter les Médaillons de Rolf et Malakai au garde Thomas au pont est d’Elwynn.", description = "Maintenant que vous avez les deux médaillons, apportez-les au Garde Thomas au Pont est, il saura peut-être comment ces hommes ont été assassinés.", progress = "Bonjour, <nom>. Avez-vous découvert ce qui est arrivé à Rolf et Malakai ?", completion = "Vous avez confirmé mes craintes, &lt;nom&gt;. Les murlocs sont un danger que nous ne pouvons ignorer.", rewards = "Vous recevrez :\n\n"},
[72] = {title = "La légende de Stalvan", objective = "Rechercher un indice dans le tas d'affaires.", description = "Mon père fut le gardien de cette propriété bien avant que je ne le sois. Il a dû tout nettoyer après le massacre.\n\nLes derniers fonds des Flintridge ont fondu comme neige au soleil. Le reste des affaires de la famille va partir aux enchères. La faute à ces vautours des impôts. J'imagine que vous êtes <impatient/impatiente> de voir ce qu'il y a, vous pouvez regarder dans le tas de vieilleries. Si ça se trouve, quelque chose vous intéressera.", progress = nil, completion = "Vous faites lentement basculer le couvercle de la caisse…", rewards = "Vous recevrez :\n\n"},
[74] = {title = "La légende de Stalvan", objective = "La Page de journal déchirée que vous avez découverte est votre deuxième indice.", description = "Dans la caisse vous trouvez diverses choses : quelques objets moisis, un portrait de famille, quelques trophées de chasse et de vieux livres. Dans le fond, sous un vase en céramique, vous découvrez une Page de journal déchirée.", progress = "Qu'est-ce que vous avez trouvé ? Je n'arrive pas à voir. J'ai une très mauvaise vue. Mettez-le-moi dans la main.", completion = "J'arrive à peine à distinguer ces lettres. Le style me dit cependant quelque chose, je l'ai déjà vu avant que ma vue ne baisse.", rewards = "Vous recevrez :\n\n"},
[75] = {title = "La légende de Stalvan", objective = "Le maréchal Haggard veut que vous alliez chercher la Vieille page de journal dans le coffre à l'étage.", description = "Quand j'ai emménagé ici, il y avait une liasse de lettres dans le coffre en haut. Je les ai examinées en arrivant, mais j'ai abandonné quand mes yeux ont commencé à perdre leur acuité.\n\nFaites une faveur à un vieil homme aveugle, et allez voir dans le coffre à l'étage si vous trouvez quelque chose qui puisse vous aider à en savoir plus sur cet homme, Stalvan. Je suis presque sûr qu'il y a une vieille page de journal qui peut avoir un intérêt pour vous. Ramenez-la-moi et je vous aiderai autant que possible.", progress = "Avez-vous trouvé la page dont je vous ai parlé, <nom> ?", completion = "Vous l'avez !", rewards = "Vous recevrez :\n\n"},
[76] = {title = "La mine de Jasperlode", objective = "Explorer la Mine de Jasperlode, puis faites votre rapport au maréchal Dughan de Goldshire.", description = "Merci, nous savons désormais que la mine de Fargodeep est infestée de kobolds. Nous avons besoin maintenant d'un éclaireur pour explorer la mine la plus éloignée, celle de Jasperlode.\n\nExplorez-la et confirmez la présence de kobolds. Pour parvenir à la mine, allez vers l'est le long de la route, jusqu'à la tour d'Azora. De là prenez vers le nord et vous tomberez sur la mine dans les collines.", progress = nil, completion = "Des kobolds à la mine de Jasperlode, dites-vous ? Malédiction ! La situation se dégrade de minute en minute !\n\nMerci de votre rapport, &lt;nom&gt;. Mais j'aurais préféré que vous apportiez de meilleures nouvelles.", rewards = "Vous recevrez :\n\n"},
[77] = {title = "Une situation délicate", objective = "Récupérer 10 bouteilles de Houle au miel des Hinterlands dans des caisses se trouvant aux environs de la base abandonnée de la Horde, au rocher de l'Affût.", description = "Je possède l'emballage d'origine nécessaire pour conditionner la Houle que Dran Droffers recherche. Je vais vous aider à l'emballer pour le père de Malton, à l'humeur si caustique... contre deux bouteilles de la susnommée Houle. Les bouteilles se trouvent dans une caisse, dans une base abandonnée de la Horde, près du rocher de l'Affût.\n\nLa tâche sera ardue : d'immondes gelées et même des limons infestent les ruines. On dit que ces créatures seraient commandées par une sorte de limon en chef. Quoiqu'il en soit, procurez-vous la Houle et revenez me voir ici pour la conditionner.", progress = "J'imagine que votre retour à notre camp signifie que vous venez livrer les bouteilles de Houle... Non ?", completion = "Très bon travail, &lt;nom&gt;. Je suis heureux de voir que vous avez eu la présence d'esprit de ne pas abîmer la délicatesse de la Houle. Il n'y a rien de pire que le bouquet d'une Houle qui a été trop secouée.\n\nIl va me falloir un bon moment pour que la magie œuvre sur cette précieuse cargaison. Mais non, mon gars, je plaisantais... Il n'y a aucune magie dans tout cela ; j'ai simplement des emballages vides de Houle au miel des Hinterlands. Notre tour de passe-passe va transformer ces bouteilles en un trésor de vieil alcool.\n\nAllez ! Préparons ce fameux tord-boyaux !", rewards = "Vous recevrez :\n\n"},
[78] = {title = "La légende de Stalvan", objective = "Prendre la Vieille page de journal et la montrer à Smitts l'aubergiste.", description = "Je connais quelqu’un qui peut peut-être vous aider. Quand je commandais les gardes de Stormwind, nous avions l'habitude d'aller boire des coups à la taverne du Corbeau écarlate à Darkshire. L'aubergiste, Smitts, connaît nombre d'histoires sur la région. Montrez-lui cette page et voyez ce qu'il peut vous en dire.", progress = "Le maréchal Haggard vous envoie ? Pourquoi ne pas l'avoir dit ?\n\nAh ! c'te bon vieux Haggard. Ce pov'gars, y va devenir complètement aveugle d'ici peu. Bon, enfin, faites donc voir c'que vous avez là.", completion = "Par la Lumière ! Un peu que je reconnais cette écriture.", rewards = "Vous recevrez :\n\n"},
[79] = {title = "La légende de Stalvan", objective = "Porter les pages au commandant Ebonlocke.", description = "Je m'intéresse à l'histoire de ce personnage, Stalvan, depuis des années. Le jour où ces nobles de passage furent massacrés, il y a quelques années, je suis venu avec Haggard pour enquêter. J'ai trouvé ces pages boueuses, mais je n'ai jamais pu faire le lien avec l'écriture de cet homme fou dans les bois. Ce que vous m'apportez là, prouve de toute évidence qu'il est coupable. Portez immédiatement cela au commandant Ebonlocke et racontez-lui ce que vous avez découvert !", progress = "Ça a intérêt à être important, <classe>. Faites voir ce que vous avez et racontez-moi votre histoire. Mais par la Lumière, soyez bref. La défense de Darkshire est ma priorité numéro un. Je n'ai pas de temps à perdre avec des futilités.", completion = "Vous avez prouvé que vous aviez des aptitudes de détective, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nUne page de journal maculée de sang"},
[80] = {title = "La légende de Stalvan", objective = "Montrer au Greffier Daltry la Page de journal maculée de sang.", description = "J'avais déjà l'œil sur ce sale type, Stalvan. Mais si les écritures concordent, alors cela prouve sans l'ombre d'un doute qu'il est coupable.\n\nAvec toutes ces journées à tenir le registre de la ville, le Greffier Daltry est devenu un expert dans l'identification des écritures. Montrez-lui ces pages pour vérifier si les écritures concordent avec la signature présente sur le registre.", progress = "De retour, <nom> ? Qu'est-ce que vous avez maintenant?", completion = "Mais oui ! Les écritures concordent.", rewards = "Vous recevrez :\n\n"},
[81] = {title = "La livraison de Houle", objective = "Livrer le tonneau à Dran Droffers à Orgrimmar.", description = "J'ai pris la peine de mettre à l'abri dans le tonneau, en plus de la houle emballée de Dran, les bouteilles supplémentaires qu'il veut faucher pour son propre compte. Je n'aime pas beaucoup Dran, mais il n'y a rien de pire que de la houle éventée. Ne vous donnez pas la peine de me remercier.\n\nAllez maintenant livrer le baril à Dran Droffers, à sa boutique d'Orgrimmar. Et passez le bonjour à Malton ! Dites-lui que s'il cherche d'excellentes boissons et de sympathiques compagnons de beuverie, nous serions honorés de recevoir sa visite.", progress = "Si vous n'êtes pas ici pour acheter ou pour me livrer quelque chose, alors vous me faites perdre mon temps ! Vous avez intérêt à avoir cette houle !", completion = "Bon, voyons voir ce qu'il y a dans ce tonneau !\n\nOui, oui, il semble qu'il y a tout. Voilà pour votre livraison, beau travail. Je vais gagner cinq fois cette somme en la vendant à la taverne ! Ha ha !\n\nCes bouteilles supplémentaires de Houle au miel des Hinterlands serviront pour les occasions spéciales. Je pense que je les boirai avec du champagne. Et j'appelerai ça... du champohoule.", rewards = "Vous recevrez :\n\n"},
[82] = {title = "Enquête au Repaire nuisible", objective = "Apporter cinq morceaux de Centipaars du Repaire nuisible à l'Alchimiste Pestlezugg à Gadgetzan.", description = "Très bien, maintenant ces rapports à propos des insectes... Ce que nous savons, c'est qu'ils drainent l'eau du réservoir qui se trouvait à l'emplacement du Repaire nuisible. Ce que nous ne savons PAS... Tout le reste.\n\nEssayons tout d'abord de savoir qui est notre ennemi ! Je veux que vous alliez au Repaire nuisible et rameniez des bouts de ces bestioles. Récupérez cinq morceaux de ces Centipaars et portez-les à l'alchimiste Pestlezugg pour qu'il voit de quoi il retourne. Avec lui sur l'affaire, nous le saurons vite !", progress = "Vous avez le titre de géomètre novice, <nom> ? Alors vite, nous avons un problème grave à régler ! Avez-vous les morceaux d'insectes dont m'a parlés Fizzledowser ?!", completion = "Bon travail. Je vais commencer à les analyser tout de suite ! Cependant, je peux vous dire quelque chose dès maintenant... Ce sont les insectes les plus étranges que j'aie jamais vus. C'est comme s'ils étaient contrôlés par quelque force extérieure.\n\nVous devez immédiatement aller voir Fizzledowser. Il se passe quelque chose et il a besoin de vous tout de suite ! Je n'en suis pas certain, mais je pense qu'il y a plus à l'œuvre que des insectes dans le désert de Tanaris !", rewards = "Vous recevrez :\n\n"},
[83] = {title = "Articles rouges en lin", objective = "Apporter 6 Masques rouge en lin à Sara Timberlain au Camp de bûcherons du Val d'est.", description = "Les Défias du Northshire portent de simples masques, mais ceux d'Elwynn portent des masques en lin, une belle matière avec laquelle je pourrais faire de très beaux articles.\n\nRapportez-moi des masques rouges en lin et je les utiliserai pour vous confectionner quelque chose.\n\nLes membres de la Confrérie défias ont des campements disséminés à travers tout Elwynn.", progress = "Je commence à manquer de lin, <nom>. Vous avez quelque chose pour moi ?", completion = "Ah ! ce sont de bons masques, un peu rêches peut-être…\n\nEt voilà !", rewards = "Vous recevrez :\n\nChemise rouge en linEcharpe rouge en lin"},
[84] = {title = "Revenir voir Billy", objective = "Porter la Tourte de panse de porc à Billy Maclure aux Vignes des Maclure.", description = "Voilà. Quand vous donnerez cette tourte à Billy, dites-lui de s’étouffer avec !", progress = "Ugh... Je suis affamé ! Vous m'avez apporté la tourte, <nom> ?", completion = "Mm, miam ! C'est vraiment la meilleure tourte du monde !\n\nJe pense que ma mémoire est en train de revenir...", rewards = "Vous recevrez :\n\n"},
[85] = {title = "Le collier perdu", objective = "Parler à Billy Maclure.", description = "J'ai perdu mon collier, et je pense que c'est ce garnement de Billy Maclure qui l'a pris ! Généralement il vagabonde dans les Vignes des Maclure, à l'est d'ici.\n\nRapportez-moi mon collier, et vous réchaufferez le cœur d'une pauvre veuve.", progress = nil, completion = "Qu'avez-vous perdu ? Ben, je n'ai pris aucun collier, je ne suis pas un voleur !\n\nJe sais peut-être qui l'a, mais...&lt;grand sourire&gt;... J'ai trop faim pour pouvoir m'en souvenir.", rewards = "Vous recevrez :\n\n"},
[86] = {title = "Une tourte pour Billy", objective = "Apporter 4 morceaux de Viande de sanglier à Tatie Bernice Stonefield à la ferme des Stonefield.", description = "Si je mangeais une tourte, je pourrais peut-être vous dire qui a ce collier. Vous savez, je pense que cette vieille dame du nom de Bernice, dans l'autre ferme, fait de formidables tourtes de panse de porc...\n\nSi vous lui apportiez quelques morceaux d’un des sangliers qui traînent autour de notre ferme, et si vous lui expliquiez toute l’histoire, alors elle vous préparerait une tourte.", progress = "Je ne pense pas que cela soit judicieux, ni très juste, de nourrir ce chenapan alors qu'il m'a volé mon collier. Mais si c'est la seule solution pour récupérer mon bijou... !\n\nAvez-vous de la Viande de sanglier ?", completion = "Cette viande de sanglier est un peu dure, mais si je la fais cuire longtemps, je pourrai faire une bonne tourte avec !", rewards = "Vous recevrez :\n\n"},
[87] = {title = "Dent-d'or", objective = "Rapporter le Collier de Bernice à \"Tatie\" Bernice Stonefield à la ferme des Stonefield.", description = "Je jouais près de la mine de Fargodeep, et je pense que j'ai fait tomb... Euuuuh... Je veux dire que j'ai vu le collier de la vieille dame. Ne me demandez pas comment il est arrivé là... Ce n'est pas moi qui l'ai pris !\n\nQuoi qu'il en soit, j'ai vu cet énorme kobold avec une dent en or le prendre et s'enfuir vers la mine. Allez là-bas, trouvez le kobold et vous trouverez le collier, c'est juré !", progress = "Bonjour, <nom>. Avez-vous trouvé mon collier ?", completion = "Oh ! vous l'avez retrouvé. Merci, merci beaucoup !\n\nTenez, prenez ça. Ils appartenaient à mon mari. Il prétendait qu'ils portaient chance. Si seulement il ne les avait pas oubliés lors de sa dernière campagne ! Sniff !", rewards = "Vous recevrez :\n\nGants marqués d'un lion"},
[88] = {title = "Princesse doit mourir !", objective = "Tuer Princesse, prendre son collier, puis le porter à Maman Stonefield à la ferme des Stonefield.", description = "Les Brackwell ont un cochon qui a gagné des tas de prix, Princesse. C'est une ENORME truie, que je soupçonne de dévaster mon potager !\n\nAvant qu'elle ne s’intéresse à mes champs... La bête doit mourir ! Rapportez-moi son collier pour preuve de son exécution, et je vous récompenserai pour votre travail !\n\nPrincesse dîne généralement du côté du Champ de potirons des Brackwell, à l'est, après la ferme des Maclure. Chopez-la avant qu'elle commence à avoir faim, et ne revienne ici !", progress = "Alors, vous l'avez vue ? Vous l'avez eue ?", completion = "Merci ! Cette truie devenait si grosse qu'elle aurait mangé toute la récolte ! Merci, &lt;nom&gt;.\n\nMaintenant, est-ce que l'un d'eux vous va ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes uséesBrassards cloutés de cuivreBottes de fermier\n\nVous recevrez également :\n\n"},
[89] = {title = "Le pont sur le lac", objective = "Apporter 5 Clous en fer et 5 Vis en fer au contremaître Oslow à Lakeshire.", description = "Lors de la dernière invasion des orcs, nous avons été obligés de fondre tout notre fer pour fabriquer des balles, des armures et des épées. Nous avons envoyé une demande de ravitaillement à Stormwind, mais une bande de gnolls des Carmines a détourné la caravane puis s'est enfuie dans les collines au-delà de Lakeshire.\n\nNous allons bientôt être à court de matériel pour reconstruire ce pont. Si vous pouviez me rapporter 5 clous en fer et 5 rivets en fer, <nom>, je ferais en sorte que l'on vous récompense.\n\nAllez, au travail !", progress = "Ce pont ne va pas se construire tout seul ! Où sont mes clous et mes rivets en fer ?", completion = "Beau travail, &lt;nom&gt;. Cette cargaison va beaucoup aider pour la construction du pont. Nous allons pouvoir le consolider en peu de temps maintenant.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon de SmithGants d'ouvrier du pontGants d'équitation\n\nVous recevrez également :\n\n"},
[90] = {title = "Kébab de loup assaisonné", objective = "Récupérer 10 Steaks de loup et des Herbes aromatiques de Stormwind, puis retourner voir le chef Grual à Darkshire.", description = "La spécialité de la maison est le kébab de loup assaisonné. Bien sûr, je peux vous en faire ! Mais j'ai besoin de différents ingrédients. Apportez-moi 10 Steaks de loup ainsi qu'un peu d'Herbes aromatiques de Stormwind. Il y a tellement de loups dans la forêt que cela ne devrait pas être un problème pour trouver la viande. Pour ce qui est des herbes, allez donc voir Felicia Gump, la fleuriste du quartier du canal à Stormwind.", progress = "Avez-vous été capable de récupérer les 10 Steaks de loup ? Et pour les herbes de Felicia ?", completion = "Beau travail, &lt;nom&gt; ! Appréciez la délicatesse du fameux kébab de loup assaisonné !", rewards = "Vous recevrez :\n\nKébab de loup assaisonnéRecette : Kébab de loup assaisonné"},
[91] = {title = "La loi de Solomon", objective = "Apporter 10 Pendentifs sombrepoil au Bailli Conacher à l'Hôtel de ville de Lakeshire.", description = "Un ennemi de Stormwind s'est installé dans les collines à l’est des Carmines. D’infâmes voleurs utilisent les Arcanes pour répandre la terreur et la misère sur notre ville et ses habitants. Derrière cela, il y a une personne, Morganth ; c'est lui qui dirige cette entreprise maléfique.\n\nMorganth contrôle maintenant le clan des gnolls Sombrepoil, qu’il utilise pour ses exactions. De par la loi de Lakeshire, aider un ennemi du royaume est passible de la peine de mort.\n\nCes infâmes gnolls doivent être tués !\n\nRapportez-moi 10 pendentifs sombrepoil, et vous serez <récompensé/récompensée>.", progress = "Apportez-moi 10 Pendentifs sombrepoil, et vous serez récompensé.", completion = "Le Tribunal de Lakeshire reconnaît votre engagement auprès des autorités de justice, &lt;nom&gt;. En faisant respecter la loi dans le Royaume, vous avez contribué à maintenir l'ordre dans le pays.", rewards = "Vous recevrez :\n\n"},
[92] = {title = "Goulash des Carmines", objective = "Le chef Breanna de Lakeshire veut 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée.", description = "Rien ne me ferait plus plaisir que de vous faire du goulash des Carmines. Mais il y a un petit problème. Lors la dernière attaque des orcs, j'ai dû nourrir la totalité des troupes de Stormwind. Mon garde-manger est complètement vide. Mais si vous me ramenez les ingrédients, je me ferai un plaisir de vous en préparer.\n\nIl me faut seulement 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée.", progress = "J'ai toujours besoin de 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée.", completion = "Merci, &lt;nom&gt;. De plus les ingrédients sont de bonne qualité ! Et voilà le délicieux plat connu sous le nom de goulash des Carmines !", rewards = "Vous recevrez :\n\nGoulash des CarminesRecette : Goulash des Carmines"},
[93] = {title = "Gâteaux au crabe brun", objective = "Récupérer 6 Pattes d'araignée fondantes et les porter au chef Grual de Darkshire.", description = "Je vais vous confier un petit secret : mon gâteau au \"crabe\" brun est en réalité fait de pattes d'araignée ! C'est vrai que cela semble un peu répugnant, mais leur goût est merveilleux ! Apportez-moi des Pattes d'araignées fondantes et je vous en préparerai quelques-uns.\n\nVous en trouverez sur les araignées Tisse-venin qui nichent au nord, entre les collines et la rivière.", progress = "Bonjour, <nom>. Avez-vous les Pattes d'araignée fondantes ?", completion = "Oh oui ! Quel bel assortiment de pattes vous avez là. Laissez-moi les préparer à ma manière avec mes petites épices selon ma recette secrète (ne regardez pas !) et les faire rissoler dans cette poêle...\n\nLes gâteaux au crabe brun sont ma spécialité et je ne vous donnerai pas la recette, mais je vais quand même vous donner celle d'un plat pratiquement aussi bon.", rewards = "Vous recevrez :\n\nRecette : Tourte d'araignée fondante"},
[94] = {title = "L'œil attentif", objective = "Placer le Glyphe d'Azora sur la Statue de lion près de la Tour d'Ilgalar dans les Carmines.", description = "Mon adversaire, Morganth, est un puissant mage vicieux qui vit dans la Tour d'Ilgalar dans les Carmines. J'ai élaboré un moyen pour l'espionner, l'Œil d'Azora, et je peux maintenant l'observer de loin.\n\nMais pour connaître ses pensées, j'ai besoin d'assistance.\n\nSi vous le voulez, portez mon Glyphe d'Azora à la Tour d'Ilgalar. Placez-le sur la Statue de lion près de la tour.\n\nLorsque cela sera fait, j'aurai une vision des plans futurs de Morganth.", progress = "Cette Statue de lion est là depuis des décennies, et garde un œil sur l'infâme Tour d'Ilgalar.\n\nIl y a une cavité à la base de statue, où l'on peut placer une gemme ou un glyphe...", completion = "Vous placez le Glyphe d'Azora dans la cavité. Il s'y adapte parfaitement... et vous entendez la voix désincarnée de Theocritus :\n\nVous avez toute ma gratitude, jeune &lt;nom&gt;. Vous pourrez maintenant me parler par l'intermédiaire de ce glyphe, j'aurai peut-être d'autres missions à vous donner... une fois que j'aurai sondé les pensées de mon rival.", rewards = "Vous recevrez :\n\n"},
[95] = {title = "La vengeance de Sven", objective = "Aller à la ferme de Sven et trouver ce qui a été enterré derrière la vieille souche d'arbre.", description = "Je travaillais dans une ferme, au sud-est... Des cavaliers noirs du défilé de Deuillevent sont venus dans ma ferme et ont massacré toute ma famille alors que j'étais absent !\n\nQuand je suis rentré, j'ai vu une silhouette indistincte rôder près de ma grange, en train d'enterrer quelque chose. Il s'est enfui avant que j'aie pu l'attraper, et je n'ai pas pu m'attarder, car je suis parti aussitôt à sa poursuite. Du coup, je n'ai pas vu ce qu'il avait caché.\n\nSi vous pouviez découvrir ce qu'a enterré le cavalier noir, je vous en serai reconnaissant. L'endroit exact est derrière la vieille souche d'arbre près de la grange.", progress = nil, completion = "Un monticule de déchets hâtivement empilés se trouve là, comme si quelqu’un avait eu besoin de cacher quelque chose... Sans avoir eu beaucoup de temps pour le faire.", rewards = "Vous recevrez :\n\n"},
[96] = {title = "L'appel de l'eau", objective = "Apporter l'Éclat d'eau à Islen Waterseer dans les Tarides.", description = "Prendre l'éclat. Prendre l'éclat et donner la vie.\n\nDonner la vie et comprendre. Comprendre que l'eau, c'est la vie... La corruption détruit la vie.\n\nLe pouvoir de l'eau protège et donne la vie.", progress = "Vous êtes revenu. Splendide !\n\nComment s'est passé votre voyage jusqu'aux Pins argentés ? Cela vous a-t-il pris beaucoup de temps ?\n\nJe ne sais pas si ce que vous avez fait va servir à quelque chose, il y a tellement d’endroits corrompus. La corruption submerge toutes les choses bonnes que vous avez faites. Mais les petites réussites sont parfois aussi importantes que les grandes. Le fait d'avoir purifié l'eau a été déterminant pour vous, ainsi que pour tous les chamans.", completion = "C'est la preuve que je demandais. Vous avez fait du bon travail, &lt;nom&gt;.\n\nJe vous félicite et je vous remets ceci : votre totem d'eau.\n\nUtilisez-le à bon escient, et bonne chance.\n\nVotre prochaine épreuve est pour bientôt, apprenez bien vos leçons. L'eau pure ne soigne pas uniquement les gens blessés, mais a bien d'autres effets. Je vous suggère de chercher un maître des chamans quand vous aurez le temps. Il pourra peut-être vous apprendre d'autres sorts.", rewards = "Vous apprendrez :\n\nTotem guérisseur\n\nVous allez être la cible du sort suivant :\n\nTotem guérisseur\n\nVous recevrez également :\n\nTotem d'eau"},
[97] = {title = "La légende de Stalvan", objective = "Prévenir le commandant Ebonlocke.", description = "Prévenez immédiatement le commandant Ebonlocke que les écritures concordent, <nom> ! Ses soupçons étaient fondés !", progress = nil, completion = "Je le savais ! Beau travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[98] = {title = "La légende de Stalvan", objective = "Tuer Stalvan Mistmantle et montrer son anneau familial à Madame Eva.", description = "Stalvan Mistmantle est un dépravé. De nombreuses victimes ont perdu la vie entre ses mains. Il est sans aucun doute coupable d'un nombre incalculable de crimes et de méfaits. Et maintenant ce dément menace Darkshire. Seule la Lumière sait quels actes abjects il prépare. Allez jusqu'à sa chaumière au nord de la ville, <classe>, et exécutez Stalvan.\n\nLorsque ce sera fait, allez voir Madame Eva et montrez-lui son anneau familial. Après tout, c'est elle qui a eu la prémonition qui nous a conduits jusqu'à cette terrible découverte. Mais Darkshire est désormais plus sûr grâce à elle.", progress = "Oui, <nom> ?", completion = "Je sais, &lt;nom&gt; : Stalvan est mort. J'ai senti une onde d'espoir passer sur la forêt maudite. Le bois de la Pénombre est débarrassé de sa soif de sang. Ma joie est toutefois teintée de tristesse, quand je pense à tous ces pauvres gens qui sont morts par sa faute. Néanmoins, vous êtes un brave &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache des Esprits glacésAnneau des Esprits glacés\n\nVous recevrez également :\n\n"},
[99] = {title = "La folie d'Arugal", objective = "Rapporter 6 Chaînes enchantées de Bois-du-Bûcher à Dalar Dawnweaver au Sépulcre.", description = "Mon mépris pour ce malheureux fou d'Arugal augmente à mesure que je déchiffre son enchantement. J'ai presque fini mes recherches pour y parvenir.\n\nMa compréhension sera totale quand j'aurai compris ce qui cause l'étrange comportement des habitants de Bois-du-Bûcher. Le jour, les paysans sont des gens normaux. Mais la nuit venue ils se transforment en worgens Ragelune.\n\nJe dois puiser l'énergie des chaînes qu'a enchantées Arugal. Rapportez-moi 6 Chaînes enchantées de Bois-du-Bûcher, <nom>.", progress = "Vous avez les Chaînes enchantées de Bois-du-Bûcher <nom> ?", completion = "Votre persévérance est louable. Avec les connaissances que vous m'avez permis d'acquérir, Arugal tombera et son stupide enchantement avec lui. Félicitations, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nFendeusePilon fracasseurBaguette de cendres\n\nVous allez être la cible du sort suivant :\n\nIntelligence des Arcanes\n\nVous recevrez également :\n\n"},
[100] = {title = "L'appel de l'eau", objective = "Parler à la Manifestation d'eau inférieure dans la forêt des Pins argentés.", description = "À la fin de votre incantation une explosion lumineuse se produit. Le grésillement des gouttes dans les flammes s'est arrêté, et vos sens reviennent à mesure que les Esprits corrompus autour de vous sont détruits.", progress = nil, completion = "Merci à vous. Merci aux chamans.\n\nLa corruption diminue, mais la vie continue à décliner. C'est aux chamans de protéger la vie.", rewards = nil},
[101] = {title = "Le Totem d'affliction", objective = "Apporter 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d'araignée à Madame Eva à Darkshire.", description = "À mesure que la corruption mystique rampe à travers la forêt, la nécessité d’une protection devient indispensable, <nom>. Les vents m'ont murmuré qu'un grand danger vous guette dans un avenir proche.\n\nSi vous voulez vous garder de ce danger, noble <classe>, apportez-moi 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d'araignée. J’enchanterai alors un Totem d'affliction qui blessera ceux qui tenteront de vous agresser.", progress = "Apportez-moi 10 crocs de goule, 10 doigts de Squelette et 5 fioles de venin d'araignée. J’enchanterai alors un Totem d'affliction qui blessera ceux qui tenteront de vous agresser.", completion = "C'est très sage de votre part, &lt;nom&gt;. Ce Totem d'affliction vous protégera contre le Mal qui se tapit partout, dans Azeroth et au-delà. Quand vous vous sentez menacé, brandissez ce totem et réconfortez-vous de son aura bienfaisante. Soyez courageux, brave &lt;classe&gt;. Vous aurez besoin de rassembler tout votre courage, car je pressens que votre avenir va être le théâtre de sanglants combats.", rewards = "Vous recevrez :\n\nTotem d'affliction"},
[102] = {title = "Patrouilles dans la marche de l'Ouest", objective = "Rapportez 8 Pattes de gnolls au capitaine Danuvin à la Colline des sentinelles.", description = "Stormwind nous a abandonnés. Un vent de corruption souffle sur la marche de l'Ouest. C'est ma terre natale et je n'abandonnerai pas les gens qui ont choisi de rester ici. Nous, les anciens fermiers, nous résisterons.\n\nVotre mission, si vous l'acceptez, sera de patrouiller dans les prairies de la marche. Débusquez et tuez les infâmes gnolls qui apparemment sont de connivence avec les voleurs des Mortemines. Apportez-moi 8 Pattes de gnolls et je vous récompenserai pour votre courage.", progress = "Avez-vous 8 pattes de ces traîtres de gnolls ?", completion = "Bien joué, &lt;nom&gt;. Avec une personne de votre valeur de notre côté, la marche de l'Ouest ne peut que retrouver sa tranquillité d’antan. S'il vous plaît, acceptez ceci en gage de reconnaissance.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de la milice du peupleBrassards de la milice du peuple\n\nVous recevrez également :\n\n"},
[103] = {title = "Le gardien de la flamme", objective = "Apporter 5 Flasques d'huile au capitaine Grayson, au phare de l'Ouest", description = "Je me souviens de cette terrible nuit, au cours de laquelle la famille du gardien de phare a été tuée. J'ai contemplé, impuissant, l’attaque du Vieux Troubloeil. Mais bon, ce qui est fait est fait. Ma préoccupation maintenant est la sécurité des marins et des navires qui croisent sur la Grande mer, car la zone est très dangereuse près des récifs le long de la côte. Vu qu'il n'y a plus personne pour s'occuper du phare, la tâche m'incombe à présent de surveiller sa flamme.\n\nAidez-moi à garder la flamme allumée, apportez-moi 5 Flasques d'huile provenant des monstres des moissons.", progress = "La flamme ne durera pas longtemps sans huile, <nom>.", completion = "Louée soit la Lumière, brave &lt;classe&gt; ! Les récifs de la côte de l'Ouest seront signalés aux navires, merci pour votre dur labeur. De nombreuses vies seront sauvées tant que brillera cette flamme.\n\nJe suis mort en vain sur cette côte. Je souhaite que personne ne connaisse le même sort que moi.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPotion de mana mineurePotion de soins mineure\n\nVous recevrez également :\n\nParchemin d'intelligenceParchemin d'endurance"},
[104] = {title = "Menace sur la côte", objective = "Rapporter une Ecaille du Vieux Troubloeil au capitaine Grayson au phare de l'Ouest.", description = "Quand ma vie a pris fin sur ces rochers, je ne savais pas que je pouvais espérer quelque chose après la mort. Cette nuit-là, le phare était éteint parce que le Vieux Troubloeil avait fait fuir la famille qui s'en occupait. Mais les gens sont revenus et ont rallumé la flamme. Alors le Vieux Troubloeil a contraint ces faibles d'esprit de murlocs à attaquer le phare. Cette fois-ci, la famille n'a pas eu le temps de fuir, et elle a été massacrée par ces ignobles créatures, sans que personne ne puisse intervenir.\n\nTuez le Vieux Troubloeil si vous le rencontrez le long de la plage, et rapportez-moi une de ses écailles, je vous récompenserai.", progress = "La menace que représente le Vieux Troubloeil a-t-elle été éradiquée ? On l'a repéré en train de vagabonder près du littoral de la marche de l'Ouest.\n\nRevenez quand cette immonde bête sera morte.", completion = "Donc cet ignoble barbare, Troubloeil, est enfin mort. Beau travail, &lt;nom&gt;. Vous avez pris une vie, mais en faisant cela de nombreuses autres seront épargnées. La Grande Mer, avec tous les dangers qu'elle représente, sera un petit peu plus sûre grâce à vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTorche de GraysonTarge des MersBaguette d'Illumination\n\nVous recevrez également :\n\n"},
[105] = {title = "Hélas, Andorhal", objective = "Apporter l’Eclat phylactère d'Araj au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.", description = "Hélas, le temps est venu d'attaquer Andorhal et d'en finir avec la liche qui la contrôle !\n\nAraj l'Invocateur, la liche, règne sur les ruines de la cité. Il est gardé par de nombreuses créatures du Fléau qui encerclent les restes du centre de la ville, et sa garde personnelle, qui lui est directement attachée, est redoutable. Vous aurez besoin de plusieurs alliés pour avoir la moindre chance de le vaincre.\n\nExécutez Araj, <nom>, et apportez-moi un éclat de son phylactère comme preuve !", progress = "Une tâche vous a été confiée, <nom>. Avez-vous un éclat phylactère de la liche comme preuve de votre réussite ?", completion = "Vous l'avez fait ! Araj, la liche, est finalement vaincu !\n\nVous avez rendu un service considérable à la Horde, &lt;nom&gt;. Votre bravoure et votre persévérance sont l'étoffe d'un vrai héros. Je vous en prie, acceptez ceci en récompense de ce que vous avez fait, que tout le monde sache que vous avez apporté à la Horde une victoire pour des siècles !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMarque de résolution"},
[106] = {title = "Jeunes amoureux", objective = "Donner la Lettre d'amour de Maybell à Tommy Joe Stonefield.", description = "Je suis maudite ! Mon cœur appartient à Tommy Joe Stonefield, mais nos familles sont ennemies. Du coup, je ne peux pas le voir, et pourtant je languis d’admirer son magnifique visage !\n\nS'il vous plaît, portez-lui cette lettre de ma part. Généralement, il va à la rivière à l'ouest de la ferme des Stonefield, qui se trouve à l'ouest d'ici.", progress = "Qu'est-ce que vous avez ? Maybell est le soleil de ma vie. Vite, donnez-moi cette lettre !", completion = "Ah ! Je ne supporte plus d’être séparé d’elle. Je dois absolument la voir !", rewards = "Vous recevrez :\n\n"},
[107] = {title = "Note pour William", objective = "Porter la Note de Mamie Stonefield à William Pestle.", description = "Je suis sûre que William Pestle a une potion qui permettrait de réunir ces deux amoureux !\n\nTenez, prenez cette note et portez-la à William. Il habite à l’auberge de la Fierté du lion à Goldshire.", progress = "Vous avez un mot de \"Mamie\" Stonefield, hein ? Je ne l'ai pas vue depuis des lustres ! Je me demande ce qu'elle veut...", completion = "Je suis tout retourné pour ces pauvres enfants, Maybell et Tommy Joe. Ça me rappelle quand j'étais jeune et amoureux.\n\nIl doit y avoir quelque chose à faire pour les aider ! Laissez-moi réfléchir...", rewards = "Vous recevrez :\n\n"},
[109] = {title = "Aller voir Gryan Stoutmantle", objective = "Parler à Gryan Stoutmantle. Il se trouve à la Tour de pierre sur la Colline des sentinelles, près la route au centre de la marche de l'Ouest.", description = "J'ai l'impression que vous êtes rompu au combat, <classe>. Si vous ne l'avez pas déjà fait, vous devriez aller voir Gryan Stoutmantle. Il dirige la Milice du peuple, dont le but est de défendre les fermes de la marche de l'Ouest. Je suis sûr qu'il aurait besoin de vous. Il se trouve généralement à la Tour de pierre sur la Colline des sentinelles, près de la route au centre de la marche de l'Ouest.", progress = nil, completion = "Donc, vous venez de la part de mon ami ? C'est gentil de sa part. \n\nEn fait, la monarchie de Stormwind nous a abandonnés à notre sort. Maintenant c'est à la Milice du peuple de protéger le pays. Si cela vous intéresse, vous pouvez mettre vos compétences au service de la liberté.", rewards = "Vous recevrez :\n\n"},
[110] = {title = "Analyse des morceaux d'insectes", objective = "Aller voir à Gadgetzan si l'Alchimiste Pestlezugg a terminé d'analyser les morceaux d'insectes.", description = "Je vais passer un peu de temps à examiner l'équipement d'analyse de Scrimshank... et remettre de l'ordre dans ses effets personnels. J'ai le sentiment que ces insectes vont nous faire subir bien d'autres pertes.\n\nPourriez-vous aller voir si l'Alchimiste Pestlezugg a analysé les morceaux d'insectes que nous lui avons envoyés. S'ils sont prêts, rapportez-les moi.", progress = nil, completion = "Oui, j'ai les résultats. Ils sont... pour le moins troublants.\n\nNotre première impression, que les insectes seraient contrôlés par des forces extérieures, était exacte. Et si c'est le cas, nous sommes non seulement en présence d'une puissance inconnue, mais en plus cette puissance est malveillante. Ces insectes ont été transformés pour être dévastateurs. Je n'ai jamais rien vu de pareil.", rewards = "Vous recevrez :\n\n"},
[111] = {title = "Discuter avec Mamie", objective = "Parler à Mamie Stonefield.", description = "S'il vous plaît, <nom>, allez parler à Mamie. Si quelqu’un peut trouver une solution à notre problème, c'est bien elle.\n\nElle habite dans notre ferme à l'est d'ici.", progress = nil, completion = "Tant que nos familles se disputeront, Tommy Joe et Maybell n'auront pas beaucoup d'avenir ensemble, mais... Peut-être que nous pourrions les réunir un moment.\n\nHum, comment faire...", rewards = "Vous recevrez :\n\n"},
[112] = {title = "À la recherche du varech", objective = "Apporter 4 Feuilles de Varech cristallin à William Pestle de Goldshire.", description = "Je peux préparer une potion d'invisibilité pour Maybell, qui lui permettra de s'échapper du vignoble des Maclure et de rejoindre Tommy Joe. Mais pour préparer cette potion, j'ai besoin de varech cristallin.\n\nCette plante pousse habituellement dans l'océan, mais parfois les murlocs en récoltent. Il faut aller voir si les murlocs près du lac de Cristal n'en auraient pas en ce moment. Le lac de Cristal est à l'est de Goldshire.", progress = "Avez-vous ce varech cristallin ? Je suis sûr que Maybell est impatiente de voir son galant...", completion = "Vous avez les feuilles. Bien joué ! Maintenant, juste un instant, le temps que je concocte la potion...", rewards = "Vous recevrez :\n\n"},
[113] = {title = "Analyse des morceaux d'insectes", objective = "Porter le rapport au grand géomètre Fizzledowser à Gadgetzan. Obtenir une copie de ce rapport, comme l'alchimiste Pestlezugg l'a demandé.", description = "Le grand géomètre Fizzledowser doit être informé immédiatement. En fait... toute personne sachant lire doit voir ce rapport. Nous sommes confrontés à une menace très sérieuse et très grave non seulement pour Tanaris et Gadgetzan, mais si on ne s'en occupe pas, pour tout le Sud de Kalimdor. Oups, et même pour tout Azeroth ; cette menace n'a donné aucun signe de déclin.\n\nDemandez à Fizzledowser de faire des copies du rapport pour que vous le distribuiez le plus largement possible. Tout le monde doit être informé de cette menace !", progress = "Eh bien, géomètre novice <nom>, ce bon vieux Pestlezugg a terminé son rapport ?", completion = "Merci de m'avoir apporté le rapport, géomètre novice &lt;nom&gt; ; voici pour vos services à la Compagnie des Eaux de Gadgetzan.\n\nJe ne suis généralement pas très chaud pour laisser filtrer des informations sans contrepartie, mais je connais Pestlezugg depuis des années. S'il recommande que ce rapport puisse être lu par tout le monde, alors qu'il en soit ainsi. Attendez un moment que je vous fasse une copie.", rewards = "Vous recevrez :\n\n"},
[114] = {title = "La fuite", objective = "Porter la Potion d'invisibilité à Maybell Maclure.", description = "Prenez cette potion d'invisibilité pour la jeune Maybell. Les effets devraient être suffisamment longs pour qu'elle puisse rendre visite à Tommy Joe.", progress = "Avez-vous remis ma lettre à Tommy Joe ? Qu'a-t-il dit ?", completion = "Oh mon Dieu ! Je me sens coupable de tromper ma famille, mais mes sentiments pour Tommy Joe sont trop profonds pour être ignorés.\n\nMerci, &lt;nom&gt;. Je boirai cette potion dès que possible et j'irai rejoindre l'amour de ma vie.\n\nQuant à vous... Je vous en prie, acceptez ceci.", rewards = "Vous recevrez :\n\nPotion de soins mineure"},
[115] = {title = "Magie des Ténèbres", objective = "Apporter 3 Orbes de minuit au maréchal Marris à Lakeshire.", description = "Les orcs Blackrock ont engagé des exhalombres pour les aider dans leurs attaques contre les Carmines ; ils ont emporté des orbes de minuit. Ces orbes ont infligé de graves dégâts aux défenses des Carmines et il est impératif que nous ne soyons plus confrontés à leur puissance.\n\nRetrouvez et rapportez-moi les orbes de minuit, après avoir tué les exhalombres Blackrock qui les possèdent. Je détruirai ces orbes ; le monde ne se portera que mieux sans eux !", progress = "Comment se passe votre guerre contre les exhalombres ? Avez-vous trouvé les orbes de minuit ?", completion = "Merci, &lt;nom&gt;. Je vais les faire détruire immédiatement.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[116] = {title = "Régime sec", objective = "Le tavernier Daniels de Lakeshire a besoin d'un Tonneau de Thunderbrew, d'un Tonneau de merlot, d'une Bouteille de tord-boyaux et d'une Outre de rhum doux.", description = "Je suis dans une situation désespérée, <nom>. Mes réserves sont presque à sec. La dernière cargaison de boisson aurait dû arriver il y a bien longtemps. L'invasion des orcs a été un enfer. \n\nPeut-être pouvez-vous travailler pour moi ?\n\nJ'ai besoin que vous récupériez un tonneau de Thunderbrew de chez Grimbooze Thunderbrew dans les collines de la marche de l'Ouest, un tonneau de merlot de Stormwind, une bouteille de tord-boyaux de Darkshire et une outre de rhum doux de Goldshire. Rapportez-les-moi et je ferai en sorte que vous soyez <récompensé/récompensée>.", progress = "J'ai besoin que vous récupériez un tonneau de Thunderbrew de chez Grimbooze Thunderbrew dans les collines de la marche de l'Ouest, un tonneau de merlot de Stormwind, une bouteille de tord-boyaux de Darkshire et une outre de rhum doux de Goldshire. Rapportez-les-moi et je ferai en sorte que vous soyez récompensé.", completion = "C'est du bon travail, &lt;nom&gt; ! Je connais bien la route que vous avez dû faire pour vous procurer tous ces alcools. Je vais de nouveau faire le bonheur de mes clients ! \n\nMa femme est une excellente couturière. Prenez cette cape. Elle l'a confectionnée pour vous, en échange de vos services.", rewards = "Vous recevrez :\n\nCape finement tisséeUne bourse rebondie"},
[117] = {title = "La Tonnebière", objective = "Apporter 5 Pieds de Houblon à Grimbooze Thunderbrew pour qu'il prépare son breuvage spécial.", description = "Allez-donc, <mon ami/mon amie>, sans tarder hâtez-vous !\nPour que notre breuvage, fidèle à mes dosages,\nTienne plus de la bière que d’un mauvais ragoût,\nIl me manque du houblon pour en faire le brassage.", progress = "Allez-donc, mon ami, sans tarder hâtez-vous !\nPour que notre breuvage, fidèle à mes dosages,\nTienne plus de la bière que d’un mauvais ragoût,\nIl me manque du houblon pour en faire le brassage.", completion = "Malt et levure, orge et houblon \nGoûtez-moi ça, rien ne le vaut \nNe mendiez pas juste un gallon \nCar vous aurez un plein tonneau !", rewards = "Vous recevrez :\n\nTonneau de Tonnebière"},
[118] = {title = "Le prix des fers", objective = "Porter la Note de Verner à Argus le forgeron de Goldshire.", description = "J'ai utilisé tellement de métal pour équiper les Gardes de Stormwind que je n'en ai même plus pour ferrer les chevaux !\n\nApportez cette note à Argus le forgeron de Goldshire. Elle explique mon problème et lui demande une livraison de fers à cheval.", progress = "Qu'est-ce que c'est ? Verner vous a envoyé, dites-vous ? Bon ! Donnez-moi son message. Et PARLEZ PLUS FORT !", completion = "Alors comme ça Verner a besoin de fers, c'est ça ?!", rewards = "Vous recevrez :\n\n"},
[119] = {title = "Le retour chez Verner", objective = "Retourner chez Verner Osgood dans les Carmines et lui donner la caisse de Fers à cheval.", description = "D'accord, je lui envoie 50 fers à cheval… \n\nLes voilà, tout empaquetés et prêts à emporter ! Dites à Verner que c’est un plaisir de faire affaire, et faites en sorte qu'il trouve la facture accrochée à la caisse !", progress = "Ah ! Vous êtes de retour ! Avez-vous obtenu les fers ?", completion = "Merci, cela va vraiment me dépanner. \n\nMais qu'est-ce que c'est ? Argus a envoyé une facture avec la caisse… Quoi ? Argus veut que je le PAYE ? Bah ! \n\nBon, &lt;nom&gt;, merci pour votre aide.", rewards = "Vous recevrez :\n\n"},
[120] = {title = "Un message pour Stormwind", objective = "Le magistrat Solomon vous a remis un rapport qui doit être transmis au général Marcus Jonathan de Stormwind. Il exige que vous reveniez vers lui aussitôt que vous aurez donné le message.", description = "Nous vivons un moment crucial, <classe>. Le bourg est assiégé. Sans renforts, nous allons succomber. Le rapport dont je vous charge est de la plus haute importance. Remettez-le au général Marcus Jonathan de Stormwind le plus rapidement possible. Dès que vous le lui aurez remis, revenez avec sa réponse, qu'elle soit bonne ou mauvaise. \n\nMaintenant hâtez-vous !", progress = "Qu'avez-vous là ?", completion = "Repos, &lt;classe&gt;. \n\nLe magistrat Solomon est un chef valeureux. Ses mots ont beaucoup de poids pour moi. Je vais demander son avis au roi et lui donner des précisions sur la situation. Assurez le bon juge qu'il a le soutien de l'armée de Stormwind. Nous enverrons des renforts dès que Sa Majesté en donnera l'ordre.", rewards = "Vous recevrez :\n\n"},
[121] = {title = "Un message pour Stormwind", objective = "Porter la réponse du général Marcus Jonathan au magistrat Solomon, à Lakeshire.", description = "Pendant que j'attends la réponse du roi, je veux que vous portiez cette lettre au Magistrat Solomon.\n\nRompez, <classe> !", progress = "Le général a-t-il envoyé des nouvelles ? Les renforts sont-ils en chemin ?", completion = "Merci pour votre temps, &lt;classe&gt;. Prenez cet argent en récompense des services rendus au Lakeshire et à Stormwind.\n\nCela dit, si vous voulez bien m'excuser, je trouve cette correspondance un peu étrange. Il y a quelque chose de mauvais qui rampe dans notre royaume. Je crains que nous ne soyons au début de la guerre et non à la fin...", rewards = "Vous recevrez :\n\n"},
[122] = {title = "Les écailles de dragonnet", objective = "Rassembler 6 Ecailles ventrales de dragonnet noir et les apporter à Verner Osgood dans les Carmines.", description = "J'ai besoin d'écailles ventrales de dragonnet noir pour payer les fers qu'Argus m'a envoyés de Goldshire. Si vous pouviez m'en trouver six, je réglerais ma dette... et il m'en resterait suffisamment pour vous façonner quelque chose.\n\nLes dragonnets noirs errent souvent au sud de Lakeshire, mais ils aiment aussi se balader. Vous devrez vous embusquer et les chasser quand vous les verrez.", progress = "Je sais que le cupide Argus va envoyer quelqu'un pour récolter ses écailles si je ne les lui donne pas de suite. Les avez-vous trouvées ?", completion = "Merci ! Je vais pouvoir régler mes dettes…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de dragonnet noirGants de dragonnet noir\n\nVous recevrez également :\n\n"},
[123] = {title = "Le collecteur", objective = "Aller voir le maréchal Dughan, à Goldshire, et lui donner le Plan de route du Collecteur.", description = "Cette note est un tableau des heures et des jours auxquels une personne – décrite comme le \"Collecteur\" – doit recevoir une livraison d'or en provenance des mines de la forêt d'Elwynn. \n\nD'après le tableau, il semblerait que le Collecteur habite près du Champ de potirons des Brackwell, à l'est d'Elwynn. \n\nC'est une information importante. Vous devriez en faire part au maréchal Dughan de Goldshire.", progress = "Quoi ? Nos gens ne travaillent plus dans les mines depuis des mois !\n\nMontrez-moi cette note !", completion = "Hum... J'ai entendu parler de ce \"Collecteur\", mais je ne sais pas pour qui il travaille. Merci pour le plan de route. Il va nous aider à résoudre ce mystère.", rewards = "Vous recevrez :\n\n"},
[124] = {title = "Le hurlement des gnolls", objective = "Tuer 10 Brutes des Carmines et 8 Mystiques des Carmines, puis retourner chez Verner Osgood.", description = "Comme si les attaques des orcs ne suffisaient pas ! Maintenant j'ai des brutes et des mystiques gnolls qui rôdent au nord de mon écurie et qui massacrent mes chevaux dès qu'ils s'éloignent...\n\nSi vous pouviez nous débarrasser de ces gnolls, mes chevaux et moi vous en serions très reconnaissants.", progress = nil, completion = "Merci pour toute votre aide, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[125] = {title = "Les outils perdus", objective = "Le contremaître Oslow de Lakeshire veut que vous récupériez sa Boîte d'outils au fond du lac Placide.", description = "J'apprécierais vraiment votre aide, <nom>. La ville est assiégée, l'approvisionnement devient difficile. On devait me livrer des outils par chariot depuis Goldshire, mais le pont a sauté. Nous avons alors mis les outils dans un bateau, mais les orcs l'ont touché avec une catapulte. Évidemment, ma boîte d'outils a coulé tout droit au fond du lac.\n\nRécupérez-la, <nom>, et je ferai en sorte que vous ne le regrettiez pas.", progress = "Avez-vous été capable de retrouver mes outils ?", completion = "Bravo, &lt;nom&gt; ! Je ne pensais pas revoir un jour mes outils !", rewards = "Vous recevrez :\n\nRenfort d'armure moyen"},
[126] = {title = "Les collines aux hurlements", objective = "Rapporter la patte de Couineur à Verner Osgood à Lakeshire.", description = "<nom>, les gnolls sont toujours là. Je peux entendre leurs hurlements quand ils chassent dans les collines de Lakeshire. Et l'un d'eux hurle plus fort que les autres : Couineur, leur chef.\n\nTuez Couineur et dispersez sa meute ! Rapportez-moi sa patte comme preuve.\n\nMais faites attention ! Ce gnoll n'est pas leur chef pour rien ! Ce n'est pas un bâtard !", progress = "Couineur est une créature dangereuse, <nom>. Si vous ne vous sentez pas à la hauteur, je comprendrai.", completion = "Une fois encore, merci pour votre aide. L'armée de Stormwind a tellement à faire avec les orcs qu'elle n'a pas assez de troupes pour protéger les Carmines d'une menace annexe comme celle des gnolls.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau de volonté de ferBottes en or de la milice\n\nVous recevrez également :\n\n"},
[127] = {title = "Criée aux poissons", objective = "Rapporter 10 Poissons-lunes au Chef des docks Baren à Lakeshire.", description = "Le lac Placide est connu pour son poisson-lune. C'est un poisson qui se vend bien et j'ai justement besoin d'argent !\n\nRapportez-m'en 10 ; je paierai bien. Si vous ne savez pas pêcher, peut-être pourrez-vous en voler aux murlocs !", progress = "Vous avez mes poissons-lunes ?", completion = "C'est un plaisir de travailler avec vous, camarade !", rewards = "Vous recevrez :\n\nSoupe aux ailerons de murlocRecette : Soupe aux ailerons de murlocHuile de foie de poisson"},
[128] = {title = "La prime Blackrock", objective = "Tuez 15 Champions Blackrock et le garde Howe de Lakeshire vous récompensera.", description = "Le clan Blackrock doit être démantelé. L'Ennemi a envahi nos terres. Ces montagnes sont cependant sous le règne souverain du roi de Stormwind. Nos sources nous indiquent que les chefs de chaque unité du clan sont appelés des champions. Vous les trouverez dans leur campement au nord, juste à l'ouest de la route menant aux Steppes Ardentes.\n\nLe magistrat Solomon veut que ces brutes abjectes soient tuées. Tuez 15 Champions Blackrock et revenez me voir.", progress = nil, completion = "Je vois que vous avez vaillamment combattu le clan Blackrock, &lt;classe&gt;. Le service que vous nous avez rendu est immense.", rewards = "Vous recevrez :\n\n"},
[129] = {title = "Un repas gratuit", objective = "Apporter son déjeuner au Garde Parker. Il patrouille sur la route qui mène au Darkshire.", description = "Vous pouvez me faire une faveur ? J'ai préparé un déjeuner pour le Garde Parker, mais il est en patrouille... C'est un homme grand et fort, un Garde de Stormwind, qui peut se défendre, mais pour une citadine comme moi, c'est beaucoup trop dangereux dehors.\n\nSi vous lui apportez ce repas à ma place, revenez me voir, je vous offre un déjeuner gratuit ! Parker patrouille le long de la route qui mène au bois de la Pénombre.", progress = "Darcy m'a fait parvenir un déjeuner ? Ne trouvez-vous pas qu'elle a bon cœur ? Allez, profitons-en !", completion = "Merci, ce repas tombe vraiment à pic ! Ça creuse, de protéger Lakeshire des orcs et des gnolls !", rewards = "Vous recevrez :\n\n"},
[130] = {title = "Une visite chez l'herboriste", objective = "Parler à Martie Jainrose, l'Herboriste des Carmines.", description = "Puisque vous retournez voir Darcy, pouvez-vous lui apporter des fleurs de ma part ? Vous en trouverez chez l'herboriste, quand vous serez de retour au Lakeshire, à l'extrémité ouest de la ville.\n\nMais quand vous prendrez les fleurs, ne dites pas à l'herboriste, Martie, qui les achète, ni pour qui elles sont...", progress = nil, completion = "Vous avez besoin d'un bouquet de fleurs ? Vous n'êtes pourtant pas en ville depuis longtemps… Vous avez déjà trouvé l'âme sœur ?\n\nJe ne devrais pas me montrer aussi curieuse, mais j’aime voir qu'il y a de l'amour dans l'air... Particulièrement en des temps difficiles comme ceux que nous vivons.", rewards = "Vous recevrez :\n\n"},
[131] = {title = "Bouquet de jonquilles", objective = "Donner à Darcy le bouquet de jonquilles.", description = "Voilà votre bouquet. J'ai choisi des jonquilles pour vous. Ce sont mes fleurs préférées !", progress = "Bonjour à nouveau, <nom>. Est-ce que Parker a apprécié le repas que je lui ai envoyé ?", completion = "Oh ! Qu'elles sont belles ! Il faut que je les mette tout de suite dans un vase !\n\nMais... Ce sont les fleurs préférées de Martie. Parker ne vous a pas envoyé chez cette mégère pour m’offrir ce bouquet, n'est-ce pas ? Vous ne lui avez pas dit qu’il m’était destiné, j’espère ? Si vous l'aviez fait, elle aurait sans doute empoisonné ces fleurs.\n\nMais ce n'est pas votre faute. Merci, et voilà votre repas.", rewards = "Vous recevrez :\n\nPoisson-lune sauté"},
[132] = {title = "La Confrérie défias", objective = "Apporter la Note de Wiley à Gryan Stoutmantle, dans la marche de l'Ouest", description = "Ce que je vais vous dire peut me coûter la vie. Le gang défias est en train de préparer un gros coup. Il paraît qu'ils se sont acoquinés avec des gnolls, des kobolds et même des gobelins.\n\nApportez ce message à Stoutmantle. Il donne tous les détails de ce que je sais à ce sujet.", progress = "Content de vous revoir, <nom>. Alors, qu'est-ce que Wiley avait à dire pour sa défense ?", completion = "J'aurais dû laisser pourrir cette canaille quand j'en avais l'occasion. Mais bon ! Il nous communique des informations cruciales. Bon travail.", rewards = "Vous recevrez :\n\n"},
[133] = {title = "L'épouvantail à goules", objective = "Trouver 7 Côtes de goule. Les apporter à Abercrombie dans sa cabane.", description = "Je vis tellement loin de la sûreté de la ville que c'est un miracle que les morts-vivants ne m'aient pas dévoré ! En fait, juste hier, un groupe de Mâcheurs est venu rôder près de ma maison !\n\nPour les éloigner, je voudrais faire une sorte d’\"épouvantail\" à goules. Il me faut des côtes de goules. On peut se les procurer sur les Dévoreurs, les Mâcheurs, les Mangeurs de cervelle, les Pourris et les Répandeurs de peste.\n\nTrouvez-moi des côtes et je vous donnerais une récompense.", progress = "Il me semble que j'entends une horde de goules se bousculer derrière ma maison. Il vaudrait mieux que je construise rapidement cet épouvantail ! Vous avez mes côtes de goule ?", completion = "Ah merci ! C'est parfait !", rewards = "Vous recevrez :\n\n"},
[134] = {title = "Les ogres voleurs", objective = "Rapporter sa caisse à Abercrombie.", description = "Il y a quelques semaines, je cueillais des herbes assez loin de chez moi et j'ai été attaqué par une bande d'ogres ! Je me suis enfui, en laissant derrière moi une caisse pleine d’herbes et de précieux outils.\n\nLes ogres m'ont pourchassé un moment, puis ils sont retournés à leur tertre, au sud du bois de la Pénombre. Je suis sûr que ma caisse est là-bas, pas très loin du tertre des ogres.\n\nJe vous en prie, <nom>, récupérez cette caisse pour moi. Elle me fait gravement défaut.", progress = "Vous avez ma caisse ? Si c'est le cas, donnez-la vite !", completion = "Béni soit le Néc… enfin béni soyez-vous, &lt;nom&gt; ! Vous avez largement mérité votre récompense.\n\nHa ! Heureuses ! Les nuits vont être heureuses !", rewards = "Vous recevrez :\n\n"},
[135] = {title = "La Confrérie défias", objective = "Apporter la Note de Wiley à Mathias Shaw à Stormwind.", description = "Je me demande de quoi parlait Wiley quand il a mentionné les Maçons. C'était peut-être un lapsus ? Les Défias pourraient-ils être reliés aux Maçons ? Le seul qui pourrait le savoir à coup sûr, c'est Mathias Shaw, le chef du SI:7. Montrez-lui la note de Wiley et voyez s'il a quelque chose à tirer de ce mystère qui s'épaissit. Si vous avez du mal à trouver Shaw, cherchez du côté de la caserne de la vieille ville.", progress = "Qu'est-ce que vous me voulez ? Je suis un homme très occupé !", completion = "Cette affaire est plus compliquée que ne peut l'imaginer Stoutmantle.", rewards = "Vous recevrez :\n\n"},
[136] = {title = "Le trésor caché du capitaine Sanders", objective = "Trouver le Coffre du capitaine Sanders. Le fouiller pour trouver l'indice suivant.", description = "Si vous lisez ceci, c'est que le vieux capitaine Sanders repose sous six pieds de flotte. Mon trésor est à vous. Il vous suffit de suivre le jeu de piste.\n\nD'abord, trouvez mon coffre. Il doit être à moitié enterré dans le sable, depuis le temps, sur la côte de la marche de l'Ouest, à côté de l'épave. Il y a des tas d'épaves sur la côte, mais une seule ancre rouillée. Qui trouve cette ancre trouve mon coffre ! Et avec le coffre, l'indice suivant !", progress = nil, completion = "Le coffre s'ouvre en grinçant. On dirait qu'il ne contient que de l'eau et du sable… Mais non ! Un petit crabe en sort, qui tient dans ses pinces l'indice suivant !", rewards = "Vous recevrez :\n\n"},
[138] = {title = "Le trésor caché du capitaine Sanders", objective = "Trouver le Tonneau à côté des cheminées en ruine. Le fouiller pour trouver l'indice suivant.\n\nObjet fourni : \n", description = "L'indice que vous trouvez est le suivant : « Bon travail, matelot ! Maintenant il va falloir cingler vers l'est. À l'est, vers le haut des falaises, à l'est vers la route. Cherchez les ruines des vieilles cheminées, au bord de la route. Là, vous trouverez un vieux tonneau qui contient l'indice suivant. »", progress = nil, completion = "Bon travail, chasseur de trésor !", rewards = "Vous recevrez :\n\n"},
[139] = {title = "Le trésor caché du capitaine Sanders", objective = "Chercher la Cruche vide à côté du moulin à vent pour trouver le prochain indice.\n\nObjet fourni : \n", description = "En fouillant le tonneau, vous découvrez un autre parchemin. Il y est écrit : « À partir de ce tonneau, tournez-vous vers le nord. Marchez droit comme une bande de cadets qui va au réfectoire, jusqu'à ce que vous voyiez la cruche vide, à côté du moulin à vent solitaire, sur les falaises. Si vous farfouillez autour de cette cruche, vous pourrez bien trouver ce que vous cherchez. »", progress = nil, completion = "Vous êtes sur la voie royale, chercheur de trésor !", rewards = "Vous recevrez :\n\n"},
[140] = {title = "Le trésor caché du capitaine Sanders", objective = "Localiser le Coffre au trésor du capitaine Sanders et prendre votre récompense.\n\nObjet fourni : \n", description = "Bien vu ! Il y a un autre indice au fond de la cruche. L'encre a coulé par endroits et le papier sent le whisky, mais vous arrivez à reconstituer une partie du texte. « Maintenant que vous avez trouvé la vieille cruche de whisky, vous êtes presque au trésor ! Tournez-vous vers l'ouest et descendez vers le rivage. Ne vous arrêtez pas au bord de l'eau, continuez ! Nagez vers l'ouest jusqu'à l'île où se trouve mon coffre au trésor ! »", progress = nil, completion = "Les charnières du vieux coffre sont rouillées, mais elles fonctionnent encore. Vous forcez la serrure et vous vous emparez de votre butin.\n\nFélicitations !", rewards = "Vous recevrez :\n\nBarre d'argentChemise du capitaine SanderEcharpe du capitaine SanderSac de butin du capitaine Sander"},
[141] = {title = "La Confrérie défias", objective = "Apporter le Rapport de Shaw à Gryan Stoutmantle, dans la marche de l'Ouest.", description = "La Guilde des Maçons est dirigée par un homme du nom d'Edwin VanCleef. C'est lui qui a rebâti Stormwind après sa destruction par les orcs au cours de la Première Guerre. Apparemment, VanCleef et ses équipes n'ont pas apprécié la façon dont ils ont été traités par le roi à la fin de la reconstruction. Ça pourrait expliquer une ou deux petites choses.\n\nJ'ai rédigé un rapport détaillé pour ton maître, dans la marche de l'Ouest. Apporte-le-lui tout de suite !", progress = "Est-ce que Maître Shaw avait des explications au sujet de ce phénomène ?", completion = "Edwin VanCleef… Je connais bien ce nom. De penser qu'un homme aussi talentueux et travailleur ait pu devenir un tel scélérat, cela me met en colère. Il faudra me donner des preuves pour que je croie une telle chose !", rewards = "Vous recevrez :\n\n"},
[142] = {title = "La Confrérie défias", objective = "Traquer le Messager défias dans la marche de l'Ouest et apporter les documents qu'il transporte à Stoutmantle.", description = "Nous devons débusquer les Défias de leur cache, <nom>. Mes éclaireurs ont rendu compte qu'un Messager Défias a été vu sur les routes entre Ruisselune, la carrière de la côte de l'Or et la mine de Jangolode. Je veux que vous le capturiez. S'il résiste tuez-le et apportez-moi tout ce que vous trouverez sur lui.", progress = "<nom>, avez-vous recueilli des informations ? Avez-vous localisé le Messager ?", completion = "C'est une preuve évidente que VanCleef est à la tête de tout cela. Il ne nous reste plus maintenant qu'à découvrir la cache des Défias.\n\nNous avons eu un coup de chance en votre absence : nous avons capturé un voleur qui essayait d’« emprunter » le chariot de Saldean. Il a promis de nous conduire à leur cache si nous lui laissions la vie sauve. Il va falloir protéger ce traître jusqu'à ce qu'il tienne sa promesse. Revenez me voir dès que vous aurez localisé l'endroit.", rewards = "Vous recevrez :\n\n"},
[143] = {title = "Un message pour la marche de l'Ouest", objective = "Le Magistrat Solomon veut que vous portiez sa Demande d'aide à Gryan Stoutmantle dans la marche de l'Ouest.", description = "Il y a quelque chose d'étrange dans le comportement de l'armée de Stormwind. Elle devrait se trouver là en force à l'heure qu'il est. De toute façon, le temps est un luxe que nous ne pouvons pas nous offrir. Je ne resterai pas là à regarder couler le sang du peuple de Lakeshire sans essayer de trouver de l'aide. J'ai entendu dire qu'une milice populaire s'était formée dans la marche de l'Ouest. \n\nApportez cette demande d'aide à leur chef, Gryan Stoutmantle. Ses hommes pourront peut-être nous apporter leur soutien en attendant que le roi envoie ses réserves.", progress = "Salut, <classe>. Qu'est-ce que vous voulez à la Milice du peuple ?", completion = "Valeureux messager, vous avez bien servi votre maître.", rewards = "Vous recevrez :\n\n"},
[144] = {title = "Un message pour la marche de l'Ouest", objective = "Retourner voir le Magistrat Solomon avec la Réponse de Stoutmantle.", description = "La demande du Magistrat Solomon me peine plus que je ne saurais le dire. Visiblement, il ignore que la guerre a éclaté dans la marche de l'Ouest, sinon il saurait qu'aucune aide n'est à attendre de la Milice. Si Stormwind ne nous avait pas abandonnés elle aussi, nous n'aurions pas eu besoin de la Milice.\n\nApportez cette réponse à votre maître dans les Carmines, <classe>. Et dites-lui que mon cœur est lourd à la pensée de la mort de tant de braves.", progress = "Pouvons-nous compter sur la Milice du peuple ?  Les nouvelles en provenance du Seigneur Stoutmantle sont-elles bonnes ?", completion = "Je le dis, ce n'est pas bon du tout. Je n'imaginais pas que la situation de Stoutmantle était si proche de la nôtre, ici, au Lakeshire. Quelle stratégie l'armée de Stormwind suit-elle qui l'éloigne ainsi de son peuple ? Bah ! Je ne devrais pas réfléchir à haute voix.\n\nPar ici, messager. Veuillez accepter ces pièces en échange des services que vous avez rendus à la ville. Je pourrais bien faire appel à vous de nouveau.", rewards = "Vous recevrez :\n\n"},
[145] = {title = "Un message pour Darkshire", objective = "Le magistrat Solomon veut que vous apportiez une lettre au seigneur Ebonlocke de Darkshire.", description = "Je sollicite votre aide une nouvelle fois. J'ai écrit au seigneur Ebonlocke pour lui demander de m'envoyer ses gardes les plus expérimentés, les Veilleurs, afin de renforcer les défenses de Lakeshire. Il est primordial que ce message lui soit remis rapidement. Vous devez faire preuve de la plus grande vigilance. Ebonlocke est le maire de Darkshire, au cœur du bois de la Pénombre. Ne vous écartez pas des chemins.", progress = "Vous semblez venir de loin, <classe>. Quelles affaires vous amènent à Darkshire ?", completion = "Merci d'avoir fait ce long voyage jusqu'ici. C'est en effet une information importante.", rewards = "Vous recevrez :\n\n"},
[146] = {title = "Un message pour Darkshire", objective = "Retourner voir le Magistrat Solomon avec la Lettre en réponse du Seigneur Ebonlocke.", description = "Si je ne connaissais pas personnellement le Magistrat Solomon, je penserais qu'il a perdu la tête ! Envoyer les Veilleurs au Lakeshire simplement parce que Stormwind lui refuse son aide ? Nous avons dû créer le corps des Veilleurs justement parce que Stormwind nous avait abandonnés au moment où cette horrible magie a commencé à se répandre. Si j'envoie mes Veilleurs, notre région sera la proie du Mal avant même que les soldats n’aient atteint la lisière de la forêt.\n\nPortez cette lettre en réponse à votre maître au Lakeshire.", progress = "Ah ! Il est bon de vous revoir, messager. Puis-je annoncer au maréchal que les Veilleurs sont en route pour nous aider ?", completion = "Par la Lumière ! L'armée de Stormwind s'est retirée de la marche de l'Ouest et la Garde ne protège plus Darkshire ? Cela sent la trahison. Comment peut-il en être autrement ? \n\nJ'ai oublié de vous offrir une récompense pour vos services, &lt;classe&gt;. Voici quelques pièces. Maintenant excusez-moi. Il y a quelque chose de pourri au royaume de Stormwind, et je veux en avoir le cœur net.", rewards = "Vous recevrez :\n\n"},
[147] = {title = "Chasse à l'homme", objective = "Trouver et tuer le \"Collecteur\" puis rapporter son Anneau au maréchal Dughan.", description = "Si le \"Collecteur\" prend de l'or dans nos mines, il le vole au royaume ! Traînez-le devant la justice et apportez-moi l'anneau dont parlait le Plan de route que vous m'avez donné. Cela pourrait bien donner une indication sur l'employeur du Collecteur...\n\nCe plan de route indique que le Collecteur se cache près du Champ de potirons des Brackwell. Cherchez-le vers là-bas.", progress = "Avez-vous trouvé le Collecteur ? Savez-vous pour qui il travaille ?", completion = "Vous l'avez trouvé ? Bien joué, &lt;nom&gt;. Il ne fera plus de \"collecte\" dans les mines d'Elwynn ! \n\nEt cet anneau... C'est un anneau de membre de la guilde des Maçons de Stormwind. Pourquoi un larron de bas étage porterait-il un signe d'appartenance à une confrérie d'artisans, et pourquoi les voleurs Défias se mettent-ils à \"collecter\" de l'or dans nos mines ? \n\nQuestions complexes. J'espère que nous allons trouver des réponses.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGantelets de Stormwind en maillesGarde-poignets élastiques\n\nVous recevrez également :\n\n"},
[148] = {title = "Fournitures en provenance de Darkshire", objective = "S’adresser à Madame Eva.", description = "Oh ! Comment doit faire un pauvre vieillard ? J'ai besoin d'aller chercher des fournitures à Darkshire, mais le village est si loin et je suis si vieux, si faible... Je n'y arriverai jamais. \n\nPouvez-vous aller à Darkshire et me rapporter des mèches de cheveux fantômes ? Vous les obtiendrez chez Madame Eva, qui habite la place de Darkshire.", progress = nil, completion = "Des mèches de cheveux fantômes ? C'est ça que vous voulez ? J'ai bien peur de ne pas en avoir en stock, mais je peux en fabriquer… Si vous m'apportez des cheveux de fantôme.", rewards = "Vous recevrez :\n\n"},
[149] = {title = "Mèche de cheveux fantômes", objective = "Apporter le Peigne spectral à Marie l'Aveugle.", description = "Il y a un pauvre fantôme triste, Marie l'Aveugle, qui hante une vieille ferme, dans les collines au sud de Darkshire.\n\nPrenez ce Peigne spectral et demandez-lui de peigner ses cheveux. Ensuite, rapportez-moi le peigne et j'en retirerai les cheveux nécessaires pour fabriquer la mèche.\n\nFaites attention, car des créatures des ténèbres sont terrées autour de la maison...", progress = "<Sanglot> Oh je vous en prie ! Ne me regardez pas ! Je me suis arraché les yeux de mes propres mains, mais je peux toujours sentir votre regard ! \n\nJe suis hideuse ! Horrible ! Je vous en prie, détournez votre regard !", completion = "Qu'est-ce que c'est ? Un peigne ? Il est magnifique ! Et il glisse dans mes cheveux comme s'ils n'étaient pas un tas de fils de fer emmêlés. \n\nSi seulement j'avais un miroir !", rewards = "Vous recevrez :\n\n"},
[150] = {title = "Les braconniers murlocs", objective = "Apporter 8 Ailerons de murloc au Chef des docks Baren à Lakeshire", description = "Les murlocs sont en train de devenir gênants. De plus en plus de pêcheurs jettent l'ancre au large des rives du lac Placide et remontent un problème dans leurs filets ! Nous devons nous débarrasser d'eux avant qu'ils aient dévoré jusqu'au dernier poisson du lac !\n\nPartez à la chasse aux murlocs ! Rapportez-moi huit ailerons et je vous offrirai quelque chose...", progress = "Vous avez les ailerons ? Dépêchez-vous, nous devons nous débarrasser de ces murlocs avant qu'ils ne dépeuplent complètement le lac !", completion = "Bien joué, &lt;nom&gt;. J'espère que les murlocs ne vous ont pas causé trop d'ennuis.\n\nC'est étrange qu'ils soient arrivés ici, si loin de la mer. Je me demande s'ils fuient quelque chose…", rewards = "Vous recevrez :\n\nCanne à pêche naine"},
[151] = {title = "Pauvre Vieille Blanchy !", objective = "Verna Furlbrow de la marche de l'Ouest veut que vous lui apportiez 8 Poignées d'avoine.", description = "Cette pauvre Blanchy ! Après tout ce que nous lui avons fait subir, elle est très fatiguée. Je l'ai nourrie avant que nous quittions la ferme, mais nous ne nous attendions pas à ce que le chariot nous trahisse. Si vous pouviez lui apporter quelques poignées d'avoine des champs, vous auriez ma reconnaissance.\n\nJe parie que vous pourriez en trouver un peu près des fermes de la marche de l'Ouest, si vous parvenez à éviter ces horribles machines qui ont pris possession des lieux. Vous verrez de nombreuses fermes, au sud-ouest.", progress = "La vieille Blanchy ne tient plus debout. Avez-vous réussi à lui trouver de l'avoine ?", completion = "Oh merci, merci, &lt;nom&gt; ! La vieille Blanchy va être si heureuse !", rewards = "Vous recevrez :\n\nCouverture de la Vieille BlanchySac de nourriture de la Vieille Blanchy"},
[152] = {title = "La côte n'est pas sûre", objective = "Tuer 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte, puis retourner voir le capitaine Grayson au Phare de l'Ouest.", description = "Vous avez probablement remarqué toutes les épaves le long de la côte. La Grande Mer est une maîtresse cruelle, en vérité. La côte de la marche de l'Ouest doit être nettoyée, afin de permettre aux marins de trouver leur chemin jusqu'à nos plages en toute sécurité. Les murlocs sont déjà assez dangereux !\n\nTuez 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte et vous recevrez une récompense.", progress = "Tuez 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte, et je ferai en sorte que vous soyez récompensé.", completion = "Bien joué, &lt;nom&gt;. Vous êtes plutôt doué pour le combat. Merci d'avoir assaini la côte de l'Ouest.", rewards = "Vous recevrez :\n\n"},
[153] = {title = "Les masques en cuir rouge", objective = "Apporter 15 Masques en cuir rouge à l'éclaireur Galiaan à la Colline des sentinelles.", description = "Les Défias bougent en permanence. Ça fait un moment que je suis leurs mouvements. J'ai remarqué que nombre des membres du gang portaient un masque en cuir rouge.\n\nApportez-moi 15 de ces masques et vous recevrez une récompense.", progress = "Apportez-moi 15 masques en cuir rouge et vous serez bien payé.", completion = "Joli travail, &lt;nom&gt;. Prenez l'un de ces objets en récompense de votre dur labeur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de la milice du peupleGrèves de la milice du peupleJambières de la milice du peuple\n\nVous recevrez également :\n\n"},
[154] = {title = "Rendre le peigne", objective = "Rapporter le Peigne spectral à Madame Eva à Darkshire.", description = "NON !\n\nPrenez-le, reprenez ce peigne, éloignez-le de moi !\n\nJe suis un monstre et personne ne peut me trouver le moindre charme !", progress = "Je sens que vous avez vu Marie l'Aveugle. Vous avez les cheveux fantômes ?", completion = "Je peux faire un fuseau de Mèches de cheveux fantômes avec ceci, et il restera encore quelques filaments. Voici le paiement pour ces cheveux supplémentaires.", rewards = "Vous recevrez :\n\n"},
[155] = {title = "La Confrérie défias", objective = "Escortez le Traître défias jusqu'à la cache secrète de la Confrérie défias. Lorsque vous saurez où se cachent VanCleef et ses hommes, rapportez l'information à Gryan Stoutmantle.", description = "Ainsi Stoutmantle envoie quelqu'un d'aussi famélique pour me protéger ? Il faudra bien que ça aille. Tout de même, il vaudrait mieux s'entourer de quelques alliés...\n\nVous connaissez le plan, n'est-ce pas, <nom> ? Vous surveillez mes arrières et je vous mène à la cache des Défias. Vous feriez mieux de ne pas trop vous éloigner. Les Défias veulent ma tête à présent. S'ils me voient avec vous, ils essaieront de me tuer.\n\nPrévenez-moi quand vous aurez rassemblé quelques amis et que vous serez prêts à partir.", progress = nil, completion = "Excellent, &lt;nom&gt; ! VanCleef est à nous maintenant que nous savons où il se cache !", rewards = "Vous recevrez :\n\n"},
[156] = {title = "Cueillette de Racines pourries", objective = "Rapporter 8 Racines pourries à Smitts l'aubergiste de Darkshire.", description = "Si vous m'apportez des racines pourries, je pourrai vous préparer une tournée de suc de zombie. \n\nLes racines pourries poussent dans des endroits étranges. J'ai entendu dire qu'on pouvait les trouver à l'intérieur des crânes des Démons squelettes et des Squelettes infernaux... Cela dit, je ne me suis jamais approché pour vérifier ! \n\nLe cimetière de Colline-aux-Corbeaux et celui des Jardins paisibles sont tous les deux pleins de ces squelettes. Vous pourriez nous en débarrasser tout en cherchant les racines pourries. Darkshire vous en serait infiniment reconnaissant.", progress = "Salut, <nom>. Vous avez mes racines pourries ?", completion = "Bien ! Vous avez trouvé les racines pourries. Je dirai à Althea Ebonlocke, des Veilleurs, que vous avez tué des squelettes. \n\nLa sécurité du peuple de Darkshire est un lourd fardeau pour les Veilleurs et ça leur plaira de savoir que d'autres aident à bouter les monstres loin du bois de la Pénombre.", rewards = "Vous recevrez :\n\n"},
[157] = {title = "Apporter la mèche", objective = "Apporter la Mèche de cheveux fantômes à Abercrombie, dans sa cabane, au nord du cimetière de Colline-aux-Corbeaux.", description = "Voici votre mèche, <nom>. Elle a des milliers d'usages. Elle permet d'attacher les esprits maléfiques, de redonner la vie aux objets inanimés, que sais-je encore ?", progress = "Il faut que je passe la Mèche autour de ma porte et de mes fenêtres pour tenir à distance les esprits maléfiques. Vous l'avez trouvée ?", completion = "Merveilleux ! Ça sera parfait…\n\nVoilà, noble &lt;nom&gt;, prenez ceci en paiement de votre travail.", rewards = "Vous recevrez :\n\n"},
[158] = {title = "Suc de zombie", objective = "S’adresser à Smitts l'aubergiste.", description = "J'ai besoin d'une bouteille d'une liqueur peu ordinaire : du Suc de zombie. Smitts, l'aubergiste de la taverne du Corbeau écarlate à Darkshire, doit pouvoir en fournir.\n\nEt dépêchez-vous, <nom>. Les nuits commencent à fraîchir et j'ai besoin de ce breuvage pour réchauffer le sang dans mes veines.", progress = nil, completion = "Vous voulez du Suc de zombie, c'est ça ? Hum… On ne m'en demande pas souvent… On peut dire que c'est du brutal !", rewards = "Vous recevrez :\n\n"},
[159] = {title = "Livrer le Suc", objective = "Apporter le Suc de Zombie à Abercrombie, dans sa cabane.", description = "Voici votre Suc de zombie…\n\n… Et faites attention avec ce truc. Il est assez fort pour réveiller les morts !", progress = "J'ai besoin de Suc de zombie pour me tenir chaud tout au long des longues nuits froides. Vous m'en avez trouvé ?", completion = "Mille mercis, &lt;nom&gt;. Vous réchauffez le cœur d'un vieil homme avec votre bêt… votre gentillesse !\n\nVoici, mon ami. Acceptez ceci en gage de ma gratitude.", rewards = "Vous recevrez :\n\n"},
[160] = {title = "Une lettre pour le Maire", objective = "Apporter la Lettre d'Abercrombie à Ello Ebonlocke, Maire de Darkshire.", description = "Apportez cette lettre à Ello Ebonlocke, le Maire de Darkshire.\n\nNous sommes de vieux amis… Et quand il lira ça et comprendra ce que vous avez fait pour moi, je suis sûr qu'il sera tout aussi heureux que moi ! Ha ha !", progress = "Abercrombie... ? Je ne connais personne de ce nom. Vous dites que vous avez une lettre pour moi de cet Abercrombie ?\n\nBon… Autant la lire...", completion = "&lt;Ello regarde la lettre...&gt;\n\nQu'est-ce que c'est que cette langue ? Ça paraît très ancien… Je ne suis pas capable de la lire.", rewards = "Vous recevrez :\n\n"},
[161] = {title = "Une sombre menace se dessine", objective = "L'Ingénieur en chef Hinderweir veut que vous apportiez cette étrange poudre à Stonesmirk l'Artificier à Dun Modr.", description = "Si mes soupçons sont justifiés, c'est une espèce de poudre explosive. Il faut la faire analyser par un artificier pour savoir à quoi nous avons à faire exactement. Ashlan Stonesmirk a été affecté au régiment qui garde Dun Modr et le viaduc de Thandol. Vous allez devoir faire un périlleux voyage, <nom>.\n\nTraversez la Porte d'Algaz, suivez la route jusqu'aux Paluns et trouvez Stonesmirk à Dun Modr. Et suivez mon conseil : ne vous éloignez pas de la route et ne vous arrêtez pour rien au monde !", progress = "Vous avez dit quelque chose, M'sieu ? J'entends rien du tout, j'ai encore les oreilles qui tintent. C'est quoi, ce que vous avez là ?", completion = "Ah ! Eh bien ! Le vieux Hinderweir a des raisons de se faire du souci !", rewards = "Vous recevrez :\n\n"},
[162] = {title = "L'ascension des silithides", objective = "Apporter le Rapport d'analyse des insectes à Gracina Spiritmight à Darnassus.", description = "Je vous presse d'apporter ce rapport à quelqu'un qui a les connaissances nécessaires pour l'étudier.\n\nJe connais une elfe de la nuit érudite, Gracina Spiritmight. Elle a passé beaucoup de temps à étudier les formes de vie exceptionnelles de l'écologie d'Azeroth et elle est historienne de surcroît ! Si vous cherchez quelqu'un qui pourrait comprendre la nature de cette menace, et surtout qui serait capable de trouver une solution, alors confiez-lui ce rapport. Nous aurons besoin de son aide.\n\nLa dernière fois que j'ai entendu parler d'elle, elle vivait au Temple de la Lune, à Darnassus.", progress = "Paix et tranquillité à vous, étranger. Pourquoi me cherchez-vous ?", completion = "Oui... Nous, les elfes de la nuit, connaissons cette menace. Fizzledowser a été bien avisé de vous envoyer avec ce rapport.\n\nCes créatures vont consumer le désert de Tanaris très rapidement. Elles ne sont rien de moins que l'un des plus grands dangers auxquels nous aurons jamais à faire face. Retenez ce nom, &lt;nom&gt; : les silithides. Les insectes mentionnés ici sont des silithides et ce sont les instruments d'une des plus grandes menaces que l'Alliance et la Horde affronteront jamais.\n\nSi seulement nous avions été plus perspicaces.", rewards = "Vous recevrez :\n\n"},
[163] = {title = "Colline-aux-Corbeaux", objective = "Découvrir ce qui hante Colline-aux-Corbeaux.", description = "Il y a quelque chose d'étrange à Colline-aux-Corbeaux, <nom>. Calor jure que quelqu'un (ou quelque chose) hante les bâtiments là-bas. Deux nuits de suite, il a remarqué que les ombres bougeaient et la nuit d'avant, il dit qu'il a vu de la lumière à l'une des fenêtres.\n\nSi, comme vous le prétendez, vous vous intéressez vraiment à la sécurité du bois de la Pénombre, trouvez le monstre qui hante Colline-aux-Corbeaux.", progress = nil, completion = "Non ! Je vous en prie, ne me tuez pas ! C'est seulement moi, la Tremblotte ! Ils sont partout… Je ne peux pas leur échapper ! Des monstres ? A Colline-aux-Corbeaux ? N-n-non... C'est pas possible. Y a que l'inoffensif la Tremblotte.", rewards = "Vous recevrez :\n\n"},
[164] = {title = "Livraison à Sven", objective = "Ravitailler Sven.", description = "Connaissez-vous Sven ? Voilà un homme fidèle à la Lumière ! Lui et ses fidèles vivent dans un camp à la lisière nord-ouest du bois de la Pénombre.\n\nMalheureusement, ils sont si peu nombreux qu'ils ne peuvent même pas dépêcher l'un des leurs pour aller en ville chercher du ravitaillement. Voudriez-vous lui apporter ceci ?", progress = "Vous avez l'air robuste, <classe>. Êtes-vous venu vous battre à nos côtés ?", completion = "Ces provisions seront très utiles. Nous apprécions beaucoup l'aide de la famille Carevin. Voici pour vous, en remerciement de votre aide.", rewards = "Vous recevrez :\n\n"},
[165] = {title = "L'ermite", objective = "Aller voir le vieil homme dans sa cabane près du cimetière de Colline-aux-Corbeaux.", description = "Il y avait un vieil homme qui venait régulièrement en ville faire des courses, mais cela fait un moment que je ne l'ai pas vu. Il vit dans une cabane, au-dessus du cimetière de Colline-aux-Corbeaux, si je me souviens bien. Vous devriez aller voir ce qui ne va pas.", progress = nil, completion = "Elaine Carevin ? Oh oui, bien sûr, les Carevin !\n\nNon, il n'y a pas de problème, mais j'ai du mal à me rendre en ville à présent. Les routes sont dangereuses et je ne rajeunis pas. Vous ferez peut-être une faveur à un vieil homme ?", rewards = "Vous recevrez :\n\n"},
[166] = {title = "La Confrérie défias", objective = "Tuer Edwin VanCleef et apporter sa Tête à Gryan Stoutmantle.", description = "Il vous reste une dernière mission à accomplir. Il va falloir éliminer Edwin VanCleef. Bien que cela me chagrine de condamner un homme à mort, c'est pour le bien du peuple de la marche de l'Ouest que VanCleef doit mourir. Apportez-moi sa tête lorsque l'acte sera accompli.", progress = "Alors, comment se passe cette chasse à l'homme pour Edwin VanCleef ?", completion = "&lt;nom&gt;, votre bravoure est extraordinaire. La Milice du peuple vous remercie pour les services rendus au peuple de la marche de l'Ouest. VanCleef est mort, et sa mort marque le début de la chute de la Confrérie Défias. Nous pouvons espérer maintenant qu'un jour la paix revienne sur ce beau pays !\n\nJe vous salue, Seigneur !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChausses de la marche de l'OuestTunique de la marche de l'OuestBâton de la marche de l'Ouest\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[167] = {title = "Adieu mon frère…", objective = "Apporter l'Insigne de la Ligue des Explorateurs du contremaître Crispechardon à Wilder Crispechardon à Stormwind.", description = "Nous étions au plus profond d'une mine dans la marche de l'Ouest, cachés derrière un baraquement à Ruisselune. Impossible de savoir d'où viennent ces voleurs puants... Bref, la mine s'est effondrée sur nous. Je m'en suis sorti mais les autres... Enfin... On n'en a plus entendu parler. \n\nVous aurez peut-être plus de chance. Si vous arrivez à avoir des nouvelles de mon frère, je vous en serai reconnaissant. Il portait toujours son insigne de la Ligue des Explorateurs. Si vous ne le trouvez pas, mais que vous me rapportez cet insigne, cela me rendrait un peu de paix.", progress = "Avez-vous trouvé trace de mon frère ? Puis-je encore espérer, après tout ce temps ?", completion = "Mes craintes étaient fondées… Mon pauvre frère… Eh bien, merci d'avoir apporté une réponse à mes doutes, même si j'aurais préféré une réponse moins affreuse…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPiolet vengeur"},
[168] = {title = "À la recherche de Cartes du Syndicat des Mineurs", objective = "Récupérer 4 Cartes du Syndicat des mineurs et les apporter à Wilder Crispechardon à Stormwind.", description = "Nombre de mes amis ont péri ce jour terrible de l'effondrement de la mine. Si vos pas vous conduisent dans cette partie de la mine de Ruisselune, voyez s’il existe des indices qui permettraient de les identifier. Si vous trouvez leurs Cartes du Syndicat des Mineurs, rapportez-les-moi et je préviendrai leurs familles.", progress = "Avez-vous retrouvé les Cartes du Syndicat des Mineurs de mes camarades ?", completion = "Merci de les avoir rapportées, &lt;nom&gt;. Vos efforts aideront les morts à trouver la paix après cette tragédie. Je ferai prévenir les familles.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de tunnelierGants de mine poussiéreux\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[169] = {title = "On recherche : Gath'Ilzogg", objective = "Tuer Gath'Ilzogg et apporter sa Tête au magistrat Solomon de Lakeshire pour toucher la récompense.", description = "On recherche ! Gath'Ilzogg, responsable des attaques Blackrock sur le donjon de Guet-de-pierre et des raids sur la ville de Lakeshire.\n\nGath'Ilzogg est très dangereux. On dit qu'il prépare ses prochains crimes contre les humains depuis le Donjon récemment conquis. L'invasion de ces orcs doit être stoppée à tout prix ! Une forte récompense est offerte au cœur vaillant qui apportera la tête de Gath'Ilzogg au magistrat Solomon.", progress = "Qu'avez-vous donc là, <nom> ?", completion = "Fantastique, &lt;nom&gt; ! Gath'Ilzogg a conduit ces brutes au combat, massacrant de nombreux humains innocents. Nous avons notre revanche. Pour le royaume de Stormwind, c'est le premier pas vers la reprise du Donjon !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[170] = {title = "Une nouvelle menace", objective = "Balir Frosthammer veut que vous tuiez 6 Troggs Mâcheroc et 6 Troggs Mâcheroc forcenés.", description = "J'espère que vous êtes là pour nous donner un coup de main, <classe>. Après la dernière attaque des troggs, nous avons besoin de toute l'aide possible !\n\nJe sais que ces canailles pullulent dans toutes les régions et on dirait que les Frigères ne font pas exception. On les a repérés au sud-est, partout dans les collines et à côté du lac Gelé.\n\nEt ce n'est pas tout ! Il y a à peine quelques nuits, ils ont attaqué et détruit notre camp, à l'ouest !\n\nNous sommes un peu à court de personnel, ici, <mon gars/jeune fille>, et nous avons besoin de force et de bravoure pour renvoyer les troggs d'où ils viennent.", progress = "Des petites saloperies, pas vrai ?", completion = "Si les problèmes que nous rencontrons ici sont une juste indication de ce qui se passe ailleurs dans le pays, par ma barbe, la situation n'est pas encourageante ! J'espère que le Sénat prend les mesures nécessaires !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChâle de l'oursCeinture rustiqueBottes des neiges\n\nVous recevrez également :\n\n"},
[171] = {title = "Un surveillant de l'Alliance", objective = "Ramenez votre protégé à l'orphelinat de Stormwind, en rendant le sifflet d'orphelin humain à la gouvernante de l'orphelinat, Nightingale, sur la place de la Cathédrale.", description = "Vous avez été très <gentil/gentille> avec moi, <nom>. Je n'aurais jamais pensé que je m'amuserai autant pendant la Semaine des Enfants. Merci. Je ne veux pas être triste, avec tout ce qui m'est arrivé... Mes parents me disaient toujours qu'il fallait surmonter les mauvaises choses qui nous arrivent. Vous savez, quand je serai grand, je veux être un héros... comme vous.\n\nC'est triste de devoir revenir à l'orphelinat. Rentrons à la maison, et je dirai à la gouvernante que vous êtes une personne géniale !", progress = "C'est un plaisir de vous revoir, <nom>. Avez-vous pu accomplir les tâches pour lesquelles vous vous êtes porté volontaire pendant la Semaine des Enfants ?", completion = "Que les cieux vous bénissent, &lt;nom&gt;. Vous avez plus fait pour Randis que la plupart des gens. Merci... Vous êtes une étoile au firmament de l'Alliance.\n\nJe vous en prie, si vous en avez le temps, revenez nous voir de temps en temps. Je sais que Randis en serait très heureux, et moi aussi.\n\nRandis s'est si bien amusé avec vous, &lt;nom&gt;. Il voudrait vous donner l'un de ses familiers préférés pour que vous vous souveniez de lui.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCollier de porceletCage à ratBoîte à tortueRécompense du bougon\n\nVous recevrez également :\n\n"},
[172] = {title = "La Semaine des enfants", objective = "Utiliser le sifflet d'orphelin orc pour parler à l'enfant que vous protégez durant la Semaine des enfants.\n\nObjet fourni : \n", description = "Vous voulez aider l'orphelinat ? Vous faites honneur à la Horde, mon <ami/amie>. Votre aide durant la Semaine des enfants nous sera précieuse.\n\nPrenez ce sifflet. Vous ne pourrez vous en servir que durant sept jours, en fait, pendant toute la Semaine des enfants Quand vous l'utiliserez, vous pourrez bavarder avec l'enfant que vous avez accepté de surveiller. Si vous l'utilisez une seconde fois, il renverra l'enfant.\n\nJe vous en prie, <nom>, utilisez le sifflet pour faire la connaissance de votre protégé ! Je suis sûre que l'enfant est très impatient de vous rencontrer.", progress = nil, completion = "Zog zog ! Je m'appelle Grunth. C'est vous qui vous occupez de moi ? Vous êtes un aventurier, comme l'étaient mon papa et ma maman. La gouvernante m'a dit qu'ils étaient morts dans l'honneur, au combat. C'est chouette de vous rencontrer.\n\nJ'espère qu'on va bien s'amuser tous les deux. Y'a plein de choses que j'aimerais faire, et la gouvernante m'a dit que vous seriez comme mon grand frère cette semaine. Ça va être génial.", rewards = nil},
[173] = {title = "Worgens dans les bois", objective = "Tuer 6 worgens Tisseurs d'ombre Plaie-de-nuit pour Calor de Darkshire.", description = "Les ténèbres s'étendent inexorablement sur le bois de la Pénombre. La quête de maître Carevin est l'expulsion du mal et de l'hérésie. Nos efforts protègent le peuple de Darkshire. \n\nVous sentez-vous digne de nous rejoindre ? \n\nJe pensais comme vous, autrefois. Mais la suffisance des Veilleurs était pénible et j'ai rejoint maître Carevin. Si vous voulez prouver votre valeur, les mots ne suffiront pas. \n\nTestez votre habileté contre les tisseurs d'ombre Plaie-de-nuit, des worgens qui rôdent dans le Verger pourissant et dans le bosquet de Clairbois (clair, mon oeil !).", progress = nil, completion = "Impressionnant, &lt;nom&gt;. On dirait que vous avez quelques capacités. Il faudrait peut-être vous trouver un défi un peu plus difficile à relever ?\n\nC'est bizarre : on dirait que les worgens apparaissent comme ça, en sortant de nulle part. Mais bon, avec toutes les créatures étranges qui sont apparues à nos frontières, je suppose que c'est juste un tout petit souci parmi d'autres...", rewards = "Vous recevrez :\n\n"},
[174] = {title = "Les yeux dans les étoiles", objective = "Viktori Prism'Antras de Darkshire veut que vous lui apportiez un Tube en bronze.", description = "Mon ami Cog, un gnome, a promis de m'aider à construire un outil qui permet de voir les étoiles. Il semblerait qu'il existe une vérité, au-delà de la magie, qui explique les étranges changements survenus dans la forêt. \n\nApportez-moi un tube en bronze fabriqué par un ingénieur habile. C'est la première étape, si j'en crois le plan de Cog.", progress = "Avez-vous trouvé un ingénieur habile qui sache fabriquer un tube en bronze ?", completion = "C'est parfait, &lt;nom&gt; ! La première étape est achevée.", rewards = "Vous recevrez :\n\n"},
[175] = {title = "Les yeux dans les étoiles", objective = "Trouver Marie et la persuader de prêter une surface réfléchissante pour le projet de Viktori.", description = "Selon le plan de Cog, il faut maintenant que je trouve un moyen de réfléchir la lumière. Je me souviens d'une femme du nom de Marie, bien connue par ici car elle avait l'habitude de transporter un miroir. Vous pourriez peut-être chercher Marie et voir si elle nous prêterait une surface réfléchissante pour notre entreprise ? Je crois qu'elle habitait au sud du bois de la Pénombre...", progress = nil, completion = "Oui, bien sûr, j'avais l'habitude d'utiliser un miroir.", rewards = "Vous recevrez :\n\n"},
[176] = {title = "On recherche : \"Lardeur\"", objective = "Liquider le gnoll Lardeur et apporter sa Grande griffe au maréchal Dughan.", description = "On recherche : Lardeur.\n\nUn énorme gnoll, Lardeur, rôde dans les bois en quête de proies, au sud-ouest d'Elwynn. Nul n'a réussi à le capturer.\n\nL'armée de Stormwind offre une généreuse récompense à celui qui le tuera et qui apportera une preuve de sa mort au maréchal Dughan, de Goldshire.", progress = "Oui, Lardeur est une plaie pour mes troupes. Avez-vous quelque chose à annoncer ?", completion = "Ah ! Bien joué ! Je commençais à me demander si quelqu'un serait capable de mettre ce monstre à bas !\n\nEt voilà, &lt;nom&gt;. Merci ! Ce gnoll me donnait des maux de crâne de la taille du pic Blackrock !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTunique de fantassinJambières de garde de StormwindBâton de combat équilibré\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[177] = {title = "Les yeux dans les étoiles", objective = "Prendre le miroir de Marie l'Aveugle à la Goule folle et l’apporter à Viktori de Darkshire.", description = "Le miroir était l'un de mes plus précieux trésors jusqu'à... l'accident. Après cela, je l'ai jeté derrière la grange. Il y avait une goule folle qui traînait souvent par là-bas. Elle l'a peut-être récupéré. La rumeur dit qu'elle vit dans le cimetière des Jardins paisibles.", progress = "J'ai montré à Cog les prémices de notre machine à voir les étoiles. Il était impressionné. Avez-vous trouvé un objet réfléchissant ?", completion = "Magnifique ! Ça va marcher merveilleusement bien. Merci !", rewards = "Vous recevrez :\n\n"},
[178] = {title = "Theocritus récupère son Pendentif", objective = "Apporter l'Ancien pendentif sombrepoil à Theocritus le Mage.", description = "<Vous entendez une voix désincarnée...> \n\nNe soyez pas <effrayé/effrayée>. Je suis Theocritus, grand mage de la tour d'Azora de la forêt d'Elwynn. Le pendentif que vous avez en main est un moyen de communication entre les gnolls Sombrepoil et leur maître Morganth. \n\nAprès des mois de recherches, j'ai cru que moi aussi je pourrais communiquer grâce à ces pendentifs. Si vous pouvez entendre ce message, c'est que mon sortilège est un succès. \n\nApportez-moi ce pendentif et je vous récompenserai.", progress = "Je vous ai parlé par l'intermédiaire d'un pendentif, vous dites ? Donnez-le-moi, que je puisse l'étudier.", completion = "Acceptez ma gratitude, &lt;nom&gt;. J'ai envoyé ce message par l'intermédiaire des pendentifs sombrepoils il y a des semaines et je pensais avoir échoué. On dirait que le sort a tout de même atteint certains pendentifs, avec un peu de retard ! \n\nJ'espère pouvoir apprendre à temps comment lancer une attaque par l'intermédiaire des pendentifs, afin d'immobiliser les gnolls Sombrepoil qui les portent. \n\nJ'ai bien peur d'être obligé de poursuivre mes recherches avant d'obtenir ce résultat.", rewards = "Vous recevrez :\n\nBaume de restauration"},
[179] = {title = "Tailleur chez les nains", objective = "Sten Stoutarm voudrait 8 Morceaux de Viande de loup coriace.", description = "Qu'est-ce que c'est ? On dirait que vous avez besoin de quelque chose pour tenir chaud aux mains, non ?\n\nJe vais vous dire ce qui vous serait utile : une paire de jolis gants bien chauds. Et comme je suis une âme charitable, je vous les fournirai. À une condition, cependant.\n\nJ'ai besoin de viande de loup. Arrangement équitable, n'est-ce pas ? Vous m'apportez de la viande et je m'assure qu'on ne sera pas obligé de vous amputer d’un ou deux doigts gelés. Qu'est-ce que vous en dites ?", progress = "Les loups vous donnent du fil à retordre, pas vrai ? Il faut se démener pour éviter les crocs et les griffes !", completion = "Ah ! Merveilleux. Cette viande de loup fera bien l'affaire. Ne vous inquiétez pas, &lt;nom&gt; ! Je n'ai pas oublié ma part du marché. Voilà. Ils devraient être à votre taille.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants d'éleveur de lapinsGants d'éleveur de loupsGants d'éleveur de sangliers\n\nVous recevrez également :\n\n"},
[180] = {title = "On recherche : lieutenant Fangore", objective = "Tuer le lieutenant Fangore et rapporter sa patte au magistrat Solomon de Lakeshire.", description = "On recherche : Lieutenant Fangore.\n\nConnu comme chef du clan des gnolls Sombrepoil, sous les ordres de Morganth, ennemi de la commune et du royaume. Sur mandat du magistrat Solomon, ce traître doit mourir. Apportez sa patte au magistrat comme preuve de sa mort.", progress = "Quelles nouvelles apportez-vous à la cour ?", completion = "Le lieutenant Fangore est mort ? Bon débarras ! Vous avez fait preuve de bravoure, &lt;classe&gt;. Lakeshire vous doit sa reconnaissance.", rewards = "Vous recevrez :\n\n"},
[181] = {title = "Les yeux dans les étoiles", objective = "Localiser Zzarc'Vul dans le tertre des ogres au sud du bois de la Pénombre et rapporter son Monocle à Viktori de Darkshire.", description = "Il ne manque plus qu'un seul objet pour terminer cet appareil. Le plan de Cog mentionne une lentille ou quelque chose comme ça. La seule lentille qui soit assez large pour l'appareil risque d'être très difficile à acquérir. \n\nUn ogre du nom de Zzarc'Vul habite dans la colline au sud du bois de la Pénombre. Si vous le pouvez, rapportez-moi son monocle et je l'utiliserai comme lentille !", progress = "Avez-vous pu convaincre Zzarc'Vul de nous prêter son monocle pour notre petite expérience ?", completion = "Enfin ! L'appareil à voir les étoiles est fini ! Merci, &lt;nom&gt; ! Je vais pouvoir poursuivre mes expériences !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants du zodiaqueCeinture des étoiles\n\nVous recevrez également :\n\n"},
[182] = {title = "La caverne des trolls", objective = "Grelin Whitebeard aimerait que vous tuiez 14 Jeunes trolls Frostmane.", description = "Mon frère Senir et moi avons voyagé dans tous les coins de Dun Morogh pour évaluer la menace posée par les trolls. Le Sénat est déjà débordé par les ennuis que causent les troggs, il n'a pas besoin de ce problème supplémentaire.\n\nDe ce que j'ai vu, les trolls sont bien installés dans la vallée des Frigères, principalement dans les grottes du sud. Je ne pense pas qu'il soit nécessaire de recourir à l'armée. Quelques hommes robustes devraient suffire.\n\nVous aimeriez peut-être vous joindre à cette campagne ? J'ai le pouvoir de vous dédommager pour votre aide.", progress = "D'après ce que j'ai appris, ces trolls sont du clan Frostmane. Je ne pense pas détenir d'autre information intéressante pour vous, <nom>.", completion = "Argh ! Ces abominables trolls !\n\n&lt;Il respire bruyamment puis semble se reprendre un peu...&gt;\n\nUn groupe est entré à la faveur de la nuit et a volé mon journal ! J'aurais dû me méfier au lieu de faire confiance à ce bon à rien de…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache d'AnvilmarMarteau d'AnvilmarCouteau d'AnvilmarMasse d'Anvilmar\n\nVous recevrez également :\n\nHerbe de soins"},
[183] = {title = "Chasseur de sangliers", objective = "Talin Keeneye aimerait que vous tuiez 12 Petits sangliers des rochers.", description = "Rien de tel qu'une journée de chasse au sanglier, pas vrai ?\n\nOui, eh bien ici, dans la vallée des Frigères, il y en a tellement que ça gâche tout plaisir. Pas besoin de les pousser à attaquer ! Ils sont furieux et prêts à charger sans qu'on les aide ! En fait, depuis quelque temps, il y a tellement de sangliers dans la vallée des Frigères que chasseur devient un métier à haut risque.\n\nPour faire court, si vous pouviez m'aider à tuer quelques bêtes, j'apprécierais le geste.", progress = "Alors, cette chasse ?", completion = "Excellent ! Je vais pouvoir recommencer à chasser… dans de bonnes conditions… Bon travail, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChausses naines en tissuPantalon nain en cuir\n\nVous recevrez également :\n\n"},
[184] = {title = "Titre de propriété de Furlbrow", objective = "Rapporter son titre de propriété au Fermier Furlbrow.", description = "Voici un titre de propriété concernant une ferme de la marche de l'Ouest, signé par un certain Théodore Furlbrow et par sa femme, Verna. Au dos, il y a quelques mots hâtivement écrits : \n\n\"Nous avons fait pression sur Furlbrow et avons récupéré son titre pensant que ça pourrait nous être utile au cas où nous voudrions nous installer. \n\nIls ne nous embêteront pas. La dernière fois que je les ai vus, ils étaient sur la route de la marche, avec un chariot cassé.\"\n\nLes Furlbrow aimeraient sans doute récupérer leur titre...", progress = "Vous avez le titre de propriété de ma ferme ?  C'est une merveilleuse nouvelle ! Des forbans nous l'ont volé il y a quelques jours... Je le croyais perdu pour de bon ! \n\nJe vous en prie, rendez-le-moi. Nous sommes en route pour la marche de l'Ouest et nous allons sans doute y rester un moment, mais si nous revenons par ici... Nous aurons besoin de ces papiers !", completion = "Merci, merci beaucoup, &lt;nom&gt; ! Comme je le disais, les environs ne sont plus très fréquentables pour les honnêtes gens, mais si les choses s'améliorent, ce titre de propriété nous aidera à rentrer en possession de notre bien. \n\nJe n'ai pas grand-chose à vous offrir mais, voilà... Prenez ceci.", rewards = "Vous recevrez :\n\nPastèque mûrePetite citrouille"},
[185] = {title = "Maîtrise de la chasse au tigre", objective = "Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Jeunes tigres de Strangleronce.", description = "Lorsque j'étais encore petite fille, mon père m'a tout appris de la chasse au tigre.\n\nLes jeunes félins sont des proies plus faciles. C'est pourquoi vous commencerez par eux. On peut trouver de jeunes tigres à côté du camp de l'expédition.\n\nFaites la preuve de vos capacités en traquant et en chassant quelques-unes de ces bêtes.", progress = nil, completion = "Bien joué, &lt;nom&gt;. On va pouvoir progresser.", rewards = "Vous recevrez :\n\n"},
[186] = {title = "Maîtrise de la chasse au tigre", objective = "Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Tigres de Strangleronce.", description = "Vous apprenez vite, <classe>. Passons aux choses sérieuses à présent. Tuez 10 Tigres de Strangleronce, cette fois. Des adultes !", progress = nil, completion = "Impressionnant, &lt;classe&gt;. Vous progressez vite…", rewards = "Vous recevrez :\n\n"},
[187] = {title = "Maîtrise de la chasse au tigre", objective = "Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Anciens tigres de Strangleronce.", description = "Bien... Nous allons relever la barre, et voir dans quel bois on vous a taillé. Prouvez-moi que vous êtes en mesure de tuer 10 Anciens tigres de Strangleronce. Si vous y arrivez, vous serez digne d'affronter la dernière épreuve avant d'être nommé maître-chasseur de tigres en présence de maître Nesingwary. \n\nLes Anciens tigres ne sont pas seulement les plus difficiles à débusquer, ils sont aussi les plus féroces.", progress = nil, completion = "Particulièrement impressionnant. Je pense que vous êtes au point pour le bouquet final.", rewards = "Vous recevrez :\n\n"},
[188] = {title = "Maîtrise de la chasse au tigre", objective = "Ajeck Rouack de l'Expédition Nesingwary veut que vous tuiez Sin’Dall et que vous rapportiez sa Patte.", description = "Voici votre dernier défi. Cela fait des semaines que nous traquons un tigre particulièrement malin. Nous l'appelons Sin'Dall. Essayez de réussir ce qu'aucun <race> n'a réussi avant vous : débusquer et tuer Sin'Dall. Apportez-moi sa patte comme preuve. \n\nÇa ne va pas être une tâche facile...", progress = "Alors, on en est où de la traque de Sin'Dall ?", completion = "Je ne peux que m'incliner. Vous êtes un maître-chasseur de tigres, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nGants de chasseur de tigres"},
[189] = {title = "Oreilles de Bloodscalp", objective = "Obtenir 15 Oreilles de trolls Bloodscalp et les apporter à Kebok, à Baie-du-Butin.", description = "Saletés de trolls ! Ils massacrent tous nos agents dès qu'ils mettent un pied dans la jungle ! J'ai perdu beaucoup de mes meilleurs hommes dans de simples escarmouches ! Les pertes deviennent insupportables ! Comment vais-je pouvoir expliquer cela au baron Revilgaz ? \n\nIl faut une action décisive... Pense, Kebok, réfléchis... Tu n'as pas gagné tes galons et ton poste en rêvassant... J'y suis ! Vous... <nom>, c'est ça ? Vous allez m'aider, n'est-ce pas ? Il y a de l'argent à gagner. \n\nVoilà le marché : vous me rapportez les oreilles de 15 trolls Bloodscalp et vous recevrez une récompense.", progress = "Vous avez réussi, j'espère ? Y en a partout de ces trolls. Saletés. \n\nAh oui ! J'oubliais… Parlez-en à vos amis, n'est-ce pas ? Nous avons vraiment besoin d'aide !", completion = "Oh excellent, excellent ! Ça va nous aider un peu, momentanément... \n\n&lt;Il s'éloigne en grommelant quelque chose à propos de marges bénéficiaires et de coûts...&gt; \n\nQuoi ? Vous êtes encore là ? Une récompense ? Oui, bien sûr... OK... Prenez ça, ça devrait largement suffire.", rewards = "Vous recevrez :\n\nCanne à pêche gobeline"},
[190] = {title = "Maîtrise de la chasse à la panthère", objective = "Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Jeunes panthères.", description = "Si vous voulez faire partie de la chasse avec ce groupe de cracks rassemblé par Hemet, il va falloir vous en montrer digne ! On va tester vos capacités de chasseur de panthères... En commençant par le plus facile, soyez tranquille. Voyons si vous êtes capable de tuer 10 jeunes panthères. Pour débuter. \n\nLes débusquer représente seulement la moitié de la difficulté...", progress = "Un vrai chasseur de panthère serait dehors sur le terrain, à traquer sa proie, <classe> ! Mettez-y un peu plus d'ardeur et revenez quand vous aurez accompli votre tâche !", completion = "C'est un bon début, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[191] = {title = "Maîtrise de la chasse à la panthère", objective = "Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Panthères.", description = "Bon. On va pouvoir passer au cran supérieur. Si vous voulez montrer que vous êtes digne de vous mêler aux chasseurs de grands fauves, vous devrez tuer 10 panthères.\n\nLes adultes sont plus retorses. Elles ne sont pas aussi faciles à chasser que les jeunes.", progress = nil, completion = "Absolument parfait, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[192] = {title = "Maîtrise de la chasse à la panthère", objective = "Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 panthères Ombregueule.", description = "Maintenant, passons aux choses sérieuses. Un vrai chasseur doit être capable de chasser une panthère Ombregueule, le fauve le plus dangereux de Strangleronce. Si vous voulez nous prouver votre valeur, tuez 10 d'entre elles.\n\nSi vous les trouvez difficiles à débusquer, attendez de vous trouver face-à-face avec l'une d'elles...", progress = nil, completion = "Vous avez réussi, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[193] = {title = "Maîtrise de la chasse à la panthère", objective = "Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous lui rapportiez un Croc de Bhag'thera.", description = "Vous avez presque atteint le niveau de maître-chasseur de panthères. Il y en a une, du nom de Bhag'thera qui rôde dans la jungle. Jusqu'à présent, elle a réussi à échapper à toutes nos battues. Voyons si votre habileté est suffisante pour régler son compte à Bhag'thera.\n\nApportez-moi un Croc de Bhag'thera et vous gagnerez mon respect !", progress = "Bhag'thera est difficile à traquer. Comment se passe cette chasse ?", completion = "Alors comme ça, la grande Bhag'thera est morte ! Trois bravos pour &lt;nom&gt;. Vous êtes un brave &lt;classe&gt;, en vérité !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nJambières du chasseur de panthères"},
[194] = {title = "Contrôler la population des raptors", objective = "Hemet Nesingwary veut que vous tuiez 10 Raptors de Strangleronce.", description = "Vous vous imaginez être un as parmi les chasseurs ? On peut vérifier ça ! Entrez dans cette jungle et tuez 10 raptors de Strangleronce. On verra bien...\n\nEh non, je ne vous aiderai pas à découvrir comment on les débusque ! La traque fait la moitié du défi !", progress = "Je n'ai encore jamais rencontré de chasseur qui ait gagné des trophées en restant près du feu de camp. Comptez-vous éradiquer ces raptors de Strangleronce ou espérez-vous qu'ils meurent de vieillesse ?", completion = "Bien joué, mon pote !", rewards = "Vous recevrez :\n\n"},
[195] = {title = "Contrôler la population des raptors", objective = "Hemet Nesingwary veut que vous tuiez 10 Raptors flagellants.", description = "Commençons le défi à présent et voyons si vous êtes à la hauteur. Allez dans la jungle et tuez 10 de ces maudits raptors flagellants. Montrez-moi ce dont vous êtes capable !", progress = "Tout véritable <classe> ne pense qu'à sa proie. Vous, en revanche, vous montrez plus enthousiaste lorsqu'il s'agit de papoter autour du feu de camp. À présent filez d'ici et tuez-moi 10 de ces fichus raptors flagellants, avant que je ne m'en charge moi-même et ne débarrasse la jungle entière de ces maudits reptiles en une seule chasse.", completion = "C'est comme ça qu'on ajoute un ou deux trophées au-dessus de sa cheminée ! Belle boucherie, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[196] = {title = "Contrôler la population des raptors", objective = "Hemet Nesingwary veut que vous tuiez 10 Traqueurs de la jungle.", description = "Voyons comment vous vous en sortez avec ce nouveau défi. Il existe une espèce de raptor pas loin d'ici, une race assez méfiante de nature. Nous les appelons les Traqueurs de la jungle. Ils sont largement plus coriaces à chasser et à tuer que les proies sur lesquelles vous avez tenté votre chance jusqu'à présent. Tuez 10 Traqueurs de la jungle et je vous indiquerai le meilleur terrain de chasse.", progress = "Eh bien ! Que faites-vous donc encore dans le coin, <nom> ! Tout chasseur digne de ce nom ne lâche jamais sa proie une fois son objectif fixé. Ces Traqueurs ne vont pas accourir ici pour se jeter eux-mêmes dans ces flammes. Idiot.", completion = "Eh bien ! Nous voilà en présence d'un vrai tueur de raptors. Bien joué, mon pote !", rewards = "Vous recevrez :\n\n"},
[197] = {title = "Contrôler la population des raptors", objective = "Hemet Nesingwary veut que vous tuiez Téthis, un raptor farouche et dangereux de Strangleronce.", description = "Puisque vous avez montré que vous êtes une telle terreur dans la jungle, laissez-moi vous parler d'un terrible raptor que même moi je n'ai pas réussi à vaincre. Ajeck, que vous voyez là, appelle ce raptor rusé Téthis.\n\nSi vous voulez prouver que vous maîtrisez l'art de la chasse, ramenez-moi sa griffe. C’est un exploit que personne n'a accompli jusqu’à présent.", progress = "Alors, comment ça se passe avec Téthis ? Vous avez rabattu votre proie jusqu'au camp, c'est ça ?", completion = "Maître &lt;nom&gt;, pourfendeur de raptors !\n\nÇa sonne bien, non ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTunique de chasseur de raptors"},
[198] = {title = "Les marchandises du soldat Thorsen", objective = "Remettre les marchandises des gobelins au soldat Thorsen.", description = "Hum ! Oui, il y a quelque chose que vous pourriez faire. Le lieutenant Doren et ses partisans, dans le nord, ont besoin d'être réapprovisionnés.\n\nIls n'ont encore rien reçu, et avec les attaques des trolls, j'aurais besoin de quelqu'un pour le faire. Le campement de Doren se situe au nord-ouest de la route, à l'entrée de Strangleronce depuis le bois de la Pénombre. Donnez les provisions au soldat Thorsen ; s'il n'est pas dans le campement, c'est qu'il patrouille plus au sud du camp.\n\nAttention, si vous échouez, vous devrez me rembourser.", progress = "Oui ? Que voulez-vous ? Oh, les marchandises des gobelins. C'est étrange de voir l'un des vôtres s'en occuper, <nom>. D'ordinaire, ils envoient quelqu'un de là-bas. Bon… Vous n'avez touché à rien, au moins ? Bien bien… Nous n'aimerions pas que quoi que ce soit arrive à nos mines, vraiment pas...", completion = "Ces mines nous aideront à nous défendre contre Kurzen et ses hommes. Merci de nous les avoir amenées. Si vous avez encore besoin de travail, je vous trouverai probablement quelque chose à faire. Et vous n'aurez plus à traiter avec ces gobelins, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[199] = {title = "Une sombre menace se dessine", objective = "Retourner voir l'ingénieur en chef Hinderweir et lui montrer l'indice que vous avez découvert.", description = "Vous devez prendre un échantillon de l'étrange poudre odorante.", progress = "Alors, avez-vous découvert quelque indice, <nom> ?", completion = "C'est une découverte inquiétante, c'est le moins qu'on puisse dire !", rewards = "Vous recevrez :\n\n"},
[200] = {title = "Herod la Paperasse", objective = "Trouver les registres de Herod la Paperasse.", description = "Si Kurzen connaît le secret de Thorsen, alors cela veut dire qu'il y a un espion parmi nous. Nous devons trouver comment le secret a été éventé !\n\nLe contact de Thorsen au camp de Kurzen est Herod la Paperasse. C’est l'officier en logistique de Kurzen et il sait tout ce qui se passe dans l'enceinte de Kurzen. Si vous pouvez mettre la main sur les notes et les registres de Herod, nous comprendrions peut-être comment Thorsen a été découvert.\n\nLorsque nous étions du côté de Kurzen, le bureau de la Paperasse se trouvait au dernier étage de la seule maison à étages du camp. Ses registres s'y trouvent probablement encore.", progress = nil, completion = "Voici les notes et les registres de Herod la Paperasse.\n\nParmi eux : la liste des marchandises à l'intérieur du camp, des demandes en matériel émanant du colonel Kurzen, et diverses lettres.", rewards = "Vous recevrez :\n\n"},
[201] = {title = "L'enquête au camp", objective = "Trouver le camp des chasseurs et communiquer sa position à Krazek à Baie-du-Butin.", description = "On m'a rapporté qu'un groupe de chasseurs a établi campement au bord de la rivière, au-dessus de celui de la KapitalRisk, sur le lac Nazfériti. En temps normal, je n'y prêterais pas attention. Mais, aussi improbable que cela puisse paraître, j'ai entendu dire que Hemet Nesingwary était l'un de ces chasseurs ? Il semble avoir beaucoup d'affinités, si vous voyez ce que je veux dire, et l'on n'est jamais trop prudent.\n\nPourquoi n'iriez-vous pas y faire un tour, <nom>, et voir de quoi il retourne ?", progress = nil, completion = "Ainsi, mon information était exacte, comme d'habitude. Intéressant. Bien, je ne pense pas qu'ils représentent un danger quelconque pour notre opération, mais peut-être ont-ils besoin de certains de nos excellents produits manufacturés. Hum…", rewards = "Vous recevrez :\n\n"},
[202] = {title = "Le colonel Kurzen", objective = "Tuer 6 Troupes d'élite, 4 Lieutenants et rapporter la tête de Kurzen au lieutenant Doren au camp rebelle.", description = "Vous avez montré votre valeur à maintes reprises, et vos ressources semblent même concurrencer celles de ce Kurzen en personne. Il se peut que vous représentiez le salut pour notre bande de rebelles… si vous pouvez vous mesurer à Kurzen et le vaincre !\n\nIl contrôle ses hommes depuis les profondeurs de la Réserve. Vous devez y pénétrer, déborder ses défenseurs, puis combattre Kurzen et ses officiers.\n\nAdieu, <nom>. Mes espoirs et la destinée de mes hommes sont entre vos mains.", progress = "Puis-je espérer que Kurzen et ses défenseurs sont morts, <nom> ?", completion = "Je n'osais croire les rapports, mais vous nous apportez la preuve que Kurzen et ses officiers sont battus. Vous nous avez sauvés ! \n\nCes jungles grouillent de nombreux dangers, mais aucun n'est aussi maléfique que Kurzen. Nous respirons mieux maintenant qu'il est parti.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCrache-mitraille"},
[203] = {title = "La seconde rébellion", objective = "Tuer 15 Guerriers de la jungle.\n\nRetourner voir le sergent Yohwa au camp rebelle.", description = "Nous combattons désespérément le colonel Kurzen. Non seulement c’est un habile tacticien, mais nous nous battons à 1 contre 10. Pour survivre, nous devons retourner contre lui ses propres tactiques sournoises.\n\nInvestissez son camp, à l'est, et tuez ses hommes. Le plus possible. Et ressortez avant que les renforts ne vous attrapent.", progress = "J'espère que votre chasse a été fructueuse, <nom>. Sans votre aide, nous ne tiendrons pas longtemps contre lui.", completion = "Bien joué, la mort de ces combattants ôte du poids de nos épaules.\n\nMais maintenant que vous avez une idée des forces contre lesquelles nous nous battons, voulez-vous toujours rejoindre nos rangs ?", rewards = "Vous recevrez :\n\n"},
[204] = {title = "Mauvaise médecine", objective = "Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergentYohwa au Camp rebelle.", description = "Si nous voulons avoir la moindre chance contre Kurzen, nous devons neutraliser ses services de soins. Il a rassemblé un nombre important de Guérisseurs qui soignent ses troupes avec des remèdes tropicaux et empoisonnent les nôtres avec des extraits de fougère vénéneuse.\n\nNous avons besoin de ces remèdes pour soigner nos gens, ainsi que d'un échantillon de ces extraits végétaux afin de l'étudier et d’en tirer nos propres médicaments. Fouillez la base de Kurzen et ramenez ces produits. Ses Guérisseurs auront les remèdes sur eux, quant aux extraits, ils sont probablement stockés dans une caisse d'approvisionnement quelconque.", progress = "J'attends que vous me rapportiez ces remèdes et cet extrait, <nom>.", completion = "Bravo, &lt;nom&gt;. Ces remèdes nous permettront de survivre et de rester en condition pour le combat. Quant à l'extrait, il nous permettra de fabriquer nos propres remèdes.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet en feuille de palmierFendoir de la guérilla\n\nVous recevrez également :\n\n"},
[205] = {title = "Sorcellerie troll", objective = "Apporter 4 Fétiches Skullsplitter à frère Nimetz au camp rebelle.", description = "Tandis que j'étudie ces légendes que vous avez apportées, rassemblez pour moi des instruments de la magie maléfique des trolls. Entrez dans le territoire des trolls Skullsplitter, une tribu mineure du Sud lointain, et obtenez de leurs Sorciers-docteurs et de leurs Mystiques certains Fétiches.", progress = "Avez-vous ces fétiches, <nom> ? Ils renferment peut-être le secret de la déchéance de Kurzen… Je dois savoir !", completion = "Merci. Je vais étudier ces fétiches et voir s'ils renferment le secret de la déchéance de Kurzen.", rewards = "Vous recevrez :\n\n"},
[206] = {title = "Mai'Zoth", objective = "Apporter la Vue de l'Esprit au frère Nimetz au camp rebelle.", description = "Kurzen est peut-être mort, mais… ce qui l'a conduit vers le Mal existe toujours ! Mes recherches m'ont appris ceci : un ogre mage du nom de Mai'Zoth vit dans les monts orientaux de Strangleronce. On dit qu'il utilise une magie contrôlant l'esprit, et je suis sûr qu'il a perverti Kurzen.\n\nSi l'on permet à Mai'Zoth de vivre, alors ses maléfices peuvent en influencer d'autres, et nous verrons peut-être surgir un deuxième Kurzen.\n\nTuez-le, et apportez-moi sa Vue de l'Esprit, l'artefact qu'il utilise pour corrompre les gens.", progress = "Je vous donne ma bénédiction. La force de Mai'Zoth n'a d'égale que sa malveillance.", completion = "Ha ! Vous avez réussi ! Vous êtes une force bénéfique de premier ordre, &lt;nom&gt;. Puisse votre pouvoir ne jamais faiblir !\n\nJe vais étudier la Vue de l'Esprit et décider si elle peut être utilisée au service du Bien. Si tel n'est pas le cas… alors, elle devra être détruite.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nOrbe de tranquillité"},
[207] = {title = "Le mystère de Kurzen", objective = "Trouver les 4 tablettes et rapporter ces légendes au frère Nimetz.", description = "Le colonel Kurzen était jadis un homme grand et noble. Je dois découvrir la cause de sa déchéance ! Il est peut-être sous l'emprise de la magie des trolls. Pour étayer cette hypothèse, il me faut étudier certaines de leurs légendes. \n\nQuatre tablettes sont cachées dans les ruines des trolls de Strangleronce. Je dois en prendre connaissance ! Recopiez-les et ramenez vos transcriptions.\n\nLa première tablette est dans les Ruines de Bal'lal, la deuxième dans le Récif infâme, et vous trouverez les troisième et quatrième dans les ruines de Zul'Kunda.", progress = "<nom> ! Avez-vous les légendes des trolls ? Je dois connaître leurs secrets !", completion = "Merci, &lt;nom&gt;. Je vais étudier ces légendes pour découvrir s'il existe un lien entre les trolls et le mal qui a pris possession du colonel Kurzen.", rewards = "Vous recevrez :\n\n"},
[208] = {title = "La chasse au gros gibier", objective = "Hemet Nesingwary veut que vous lui rameniez la tête du roi Bangalash, le grand tigre blanc.", description = "<nom>, vos talents à la chasse sont dignes de notre compagnie. Des champs de bataille de Lordaeron aux jungles les plus denses, j'ai rarement été témoin de prouesses telles que les vôtres. \n\nVous avez tué le féroce Sin'Dall, l'insaisissable Bag'thera et le perfide Téthis. Mais le trophée ultime reste la tête du roi Bangalash. Ce tigre blanc est la raison de ma présence ici. Il occupe mes pensées depuis longtemps déjà. Tuez le roi Bangalash et vous n'aurez personne à envier.", progress = "Je vois que vous êtes de retour, mon grand. Je suis revenu plus d'une fois au camp à genoux à cause du roi Bangalash. Continuez, ne cédez pas.", completion = "Merveilleux ! Hourra ! Bravo à vous, &lt;nom&gt; ! Vous avez réussi là où tant d'autres ont échoué.\n\nC'est pour moi un grand honneur de vous compter parmi mes camarades. Personne ne peut remettre en doute votre talent dans l'art de la chasse !\n\nBravo à vous ! Bravo !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc de maître-chasseurCarabine de maître-chasseur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[209] = {title = "Les défenses Skullsplitter", objective = "Acquérir 18 Défenses de trolls Skullsplitter et les apporter à Kebok.", description = "Il est difficile et onéreux de tuer assez de tigres pour fournir l'exportation de leurs crocs vers les îles des Mers du sud. Par chance, nous avons mis au point une technique pour fabriquer des faux indétectables.\n\nEtonnamment, la matière idéale pour créer ces faux crocs, ce sont des défenses de troll Skullsplitter.\n\nEt avant de vous mettre à râler, sachez que ce que le client ignore ne peut pas le déranger, hein ?\n\nApportez-moi beaucoup de ces défenses, afin que l'on puisse fournir la livraison mensuelle !", progress = "Des bestioles balèzes, pas vrai ? Alors, comment ça se passe ? Je suis désolé de paraître impatient, mais ce problème me préoccupe. Vous vous y attelez ?", completion = "Ah, bon travail, bon travail. Quoique… vous auriez pu faire un effort pour nettoyer le… Bon, c'est bien, c'est bien ! Merci à vous, &lt;nom&gt;, notre affaire va sans nul doute voir sa production et ses bénéfices augmenter, grâce à votre aide ! Bien, bien… À présent, d'autres tâches m'attendent...", rewards = "Vous recevrez :\n\n"},
[210] = {title = "La cuisine de Krazeck", objective = "Apporter la Cocotte ébréchée de chez Krazeck à Krazeck le gobelin.", description = "Presque toute la cuisine se fait au camp. Et c'était beaucoup de travail, jusqu'à ce que j'achète une marmite à un marchand gobelin de Baie-du-Butin. Cette marmite est une pure merveille, le temps qu'elle m'a fait gagner est inimaginable… malheureusement elle est cassée ! \n\nPourriez-vous la lui ramener afin qu'il la répare ? Son nom est Krazek.", progress = "Salut ! Vous m'avez apporté quelque chose ?", completion = "Ah, je vois, c'est la Cocotte ébréchée de Krazek. Un travail ingénieux, bien qu'un ressort puisse lâcher ou un engrenage se briser de temps à autre. Laissez-moi voir ce qui ne va pas avec celle-ci… \n\nHa, ha ! Son chargeur à vapeur est complètement rouillé, le joint de culasse est mort et il manque des dents au fobulateur. Ça m'étonne même que cette marmite puisse cuire un navet dans cet état ! \n\nSi je peux la réparer ? Bien sûr que je peux !\n\nMais ce n'est pas gratuit. Oh non, ce n'est jamais gratuit...", rewards = "Vous recevrez :\n\n"},
[211] = {title = "Hélas, Andorhal", objective = "Apporter l’Eclat phylactère d'Araj au commandant Ashlam Valorfist, au camp du Noroît, dans les Maleterres de l’ouest.", description = "Hélas, le temps est venu d'attaquer Andorhal et d'en finir avec la liche qui la contrôle !\n\nAraj l'Invocateur, la liche, règne sur les ruines de la cité. Il est gardé par de nombreuses créatures du Fléau qui encerclent les restes du centre de la ville, et sa garde du corps personnelle, qui lui est directement attachée, est redoutable. Vous aurez besoin de plusieurs alliés pour avoir la moindre chance de le vaincre.\n\nExécutez Araj, <nom>, et apportez-moi un éclat de son phylactère comme preuve !", progress = "Une tâche vous a été confiée, <nom>. Avez-vous un éclat phylactère de la liche comme preuve de votre réussite ?", completion = "Vous l'avez fait ! Araj, la liche, est finalement vaincu !\n\nVous avez rendu un service considérable à l'Alliance, &lt;nom&gt;. Votre bravoure et votre persévérance sont l'étoffe d'un vrai héros. S'il vous plaît, acceptez ceci comme récompense pour ce que vous avez fait, que tout le monde sache que vous avez apporté à l'Alliance une victoire pour des siècles !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMarque de résolution"},
[212] = {title = "Un repas servi froid", objective = "Tuer un basilic Œil-de-glace, collecter un Cuissot de basilic glacé, et le rapporter à Angus Stern, au Solitaire bleu.\n\n<Pour réussir cette quête vous devez la terminer sans libérer votre esprit.>", description = "L'un de mes plats les plus célèbres est le basilic frappé avec sa vinaigrette citronnée. Mais le problème est qu'il est impossible de garder la viande fraîche, et je dois servir ce plat ce soir à l'occasion de l'anniversaire d'un noble !\n\nAussi si vous pouviez m'apporter un cuissot provenant d'un basilic Oeil-de-glace fraîchement occis, et ce dans les plus brefs délais, alors je vous serais redevable d’un festin de roi.\n\nCes créatures vagabondent souvent dans les dunes au nord-ouest de Strangleronce, vous avez donc un long chemin à parcourir. Et faites vite !", progress = "<nom> ! Avez-vous ce cuissot ? Je vais bientôt devoir commencer à cuisiner, ou le banquet sera un fiasco !", completion = "Ah, ce sera parfait. Merci, merci beaucoup !\n\nÀ présent, si vous voulez bien m'excuser, ce cuissot a besoin d'être débité, cuisiné et dressé pour le banquet.", rewards = "Vous recevrez :\n\n"},
[213] = {title = "Une ponction musclée", objective = "Retrouver 8 Cristaux réduits et les apporter à Kebok à Baie-du-Butin.", description = "Cette fois, c'en est trop ! Ce n'était pas assez que ce Gelriz vire les nababs invités par les princes marchands, à présent il essaie de s'immiscer dans les affaires du plus célèbre des pirates !\n\nRevilgaz ne les aura pas, et il m'a demandé de régler le problème à ma manière.\n\nMa manière ? Le vol ! Les géologues de la KapitalRisk qui campent près du lac Nazfériti sont très intéressés par ces étranges cristaux bleus qu'ils ont trouvés dans les mines. Rapportez-moi des échantillons de ces cristaux. Peu m'importe comment vous les obtenez.", progress = "J'ai besoin de ces pierres, <nom>. Par n’importe quel moyen ! Apportez-les-moi, c'est tout, les détails ne m'intéressent pas !\n\nSeul le résultat compte, <nom>, ni plus ni moins !", completion = "Fascinant ! Que ces cristaux aient été réduits par ce procédé ne peut que signifier qu'ils comptent les utiliser comme carburant ou catalyseur. Je n'en sais pas beaucoup plus... Nous devons envoyer ces échantillons au chimiste en chef Gigglefont.", rewards = "Vous recevrez :\n\nGants ornementés"},
[214] = {title = "Les masques rouges en soie", objective = "L'Eclaireur Riell de la tour de la Colline des sentinelles veut que vous lui rameniez 10 masques rouges en soie.", description = "Ce n'est un secret pour personne que le signe de reconnaissance du gang des Défias est un masque rouge. Mais nous avons appris que la qualité du tissu dont est fait le masque détermine le rang de celui qui le porte au sein du gang.\n\nCela étant dit, je veux que vous éliminiez autant de Défias haut placés que possible. Vous en trouverez à coup sûr dans la cachette de VanCleef. Lorsque vous en aurez terminé, ramenez-moi 10 masques rouges en soie pour me prouver leur mort, je vous remettrai alors une récompense. Bonne chance, <nom>.", progress = "Alors, avez-vous chassé le gang défias de nos terres ? Si tel est le cas, prouvez-le en me montrant 10 masques rouges en soie.", completion = "Bien joué, &lt;nom&gt; ! Au nom de la milice du peuple, je salue vos efforts. Bientôt, avec l'aide de gens courageux tels que vous, nous rendrons cette terre au peuple.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée courte endurcieDague ScrimshawHache de perforation\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[215] = {title = "Les secrets de la jungle", objective = "Parler au lieutenant Doren au camp rebelle.", description = "Merci de m'avoir sauvé, <nom>. Je sais de quoi ça a l'air, mais… permettez-moi de m'expliquer. \n\nJ'ai été chargé par le lieutenant Doren de rejoindre les troupes de Kurzen, pour les espionner, et fournir des informations vitales aux renseignements rebelles. Vous avez vu ce que j'ai cru être ma chance de m'infiltrer dans la base de Kurzen. Je m'étais trompé et, encore une fois, merci de m'avoir sauvé.\n\nIl s'agissait d'une mission secrète, aussi n'en parlez à personne. Mais si vous en parlez à Doren, il vous expliquera.", progress = nil, completion = "Oui, ce que vous a dit Thorsen est exact. Vous devez garder l'affaire secrète. Fut un temps, où nous, les rebelles, étions totalement acquis au colonel Kurzen. Mais bientôt sa corruption devint telle que notre dévotion tourna à la rage. Si l’on apprenait que le soldat Thorsen a récemment eu des contacts avec les hommes de Kurzen, nous le retrouverions une nuit prochaine sans vie, la gorge tranchée.\n\nPour autant que je sache, seuls le sergent Yohwa, Thorsen et moi-même étions au courant de sa mission. Mais il doit y avoir quelqu'un d'autre. Un traître…", rewards = "Vous recevrez :\n\n"},
[216] = {title = "Entre un roc et un Crin-de-Chardon", objective = "Tuer 12 Vengeurs Crins-de-Chardon et 12 Chamans Crins-de-Chardon ; la plupart d’entre eux se trouvent à l’est de la grève de Zoram, dans le village des Crins-de-Chardon. Retourner voir Karang Amakkar, à l’avant-poste de Zoram'gar, à Ashenvale, une fois que vous aurez terminé.", description = "Les furbolgs Crins-de-Chardon sont devenus un danger qui menace notre expansion ! Le village des Crins-de-Chardon, à l'est, nous bloque la route menant au poste de Bois-brisé. Par ce chemin, nous pourrions contourner le village d'Astranaar. D'un autre côté, il offrirait à l'Alliance une voie d'accès supplémentaire par où poursuivre son expansion.\n\n<nom>, nous ne pouvons pas tolérer... que se forme ainsi un chemin facilitant leur campagne d'expansion !\n\nAllez au village des Crins-de-Chardon et réduisez le nombre des furbolgs. Vous recevrez une récompense en échange de ce travail ; mais surtout, vous ferez votre devoir au service de la Horde !", progress = nil, completion = "Bien joué, &lt;classe&gt;, bien joué ! Je vais continuer à envoyer des forces pour réduire le nombre de furbolgs, mais je peux enfin compter sur un chemin nettoyé de toutes forces de l'Alliance. La conquête d'Ashenvale par la Horde est maintenant proche !\n\nVous avez mérité votre salaire aujourd'hui. Je vous salue !", rewards = "Vous recevrez :\n\n"},
[217] = {title = "À la défense des terres du roi", objective = "Tuer le chef des troggs, Grawmug, et ses deux gardes, Grinceur et Bagarreur, puis rendre compte de la situation au capitaine Rugelfuss à la Tour de garde méridionale.", description = "<nom>, nos éclaireurs ont identifié le chef des troggs qui a mené la récente incursion que nous avons subie. Il semble que ces bêtes du Loch Modan répondent aux ordres d'un certain Grawmug. Celui-ci est bien protégé. Deux de ses meilleurs gardes, Grinceur et Bagarreur, ne le quittent pas une seconde.\n\nSi vous vous en sentez capable, <nom>, j'aimerais que vous acceptiez la mission visant à assassiner Gramwug et ses deux acolytes. Une fois la direction des troggs décapitée, nous aurons peut-être une chance de renvoyer ces monstres sous terre.", progress = "Grawmug et ses deux gardes, Grinceur et Bagarreur, sont toujours en vie. Votre mission ne sera achevée que lorsque vous les aurez mis à mort tous les trois. L'empire des nains compte sur vous, <nom>.", completion = "Parfait, &lt;nom&gt; ! Vous avez ramené l'espoir à Loch Modan. Maintenant que Grawmug est mort, nos chances d'éradiquer les troggs de nos terres sont multipliées.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCulotte des frontaliersDéfenseur nainPantalon de chance\n\nVous recevrez également :\n\n"},
[218] = {title = "Le journal volé", objective = "Grelin Whitebeard veut que vous tuiez Grik'nir le Froid et que vous lui rapportiez son journal.", description = "Mon journal ! Ils l'ont emporté dans la caverne. Celui qui l'a pris ? C'était une grosse brute avec d'étranges inscriptions sur la peau et le visage. Je n'ai pas pu regarder plus précisément.\n\nVous avez déjà combattu des trolls, peut-être pourriez-vous tenter de me le rapporter ?", progress = "<nom> ! Alors ?", completion = "Merveilleux, &lt;nom&gt; ! Merci mille fois pour avoir retrouvé mon journal. Bien, il semblerait que le problème posé par les trolls soit à présent sous contrôle dans la vallée des Frigères.\n\nUne fois que j'aurai apporté les dernières retouches à mon rapport, j'aurai besoin de quelqu'un pour l'amener à mon frère Senir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrand pavois nainBâton de marche lisse\n\nVous recevrez également :\n\n"},
[219] = {title = "Porté disparu", objective = "Protéger le caporal Keeshan sur le chemin des Carmines.", description = "Enfin, des amis de l'Alliance !\n\nAu secours… Je vous en prie… \n\nLa dernière chose dont je me souviens est que les orcs ont submergé nos forces. La plupart des hommes ont été tués. J'ai reçu un coup terrible à la tête et tout s'est assombri. Je suis à présent prisonnier dans cette caverne. Au secours, je suis gravement blessé !\n\nJ'aurais besoin d'aide pour revenir jusqu'à la ville... par pitié... vous êtes mon seul espoir...", progress = "Oui ?", completion = "Vous avez rendu un fier service au royaume, &lt;classe&gt;. Merci d'avoir aidé le caporal Keeshan à échapper aux terribles orcs de Blackrock. Vous recevrez une récompense pour vos actes de bravoure en ce jour.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe de SolomonLorica d'adjointCuir clouté d'os\n\nVous recevrez également :\n\n"},
[220] = {title = "L'appel de l'eau", objective = "Apporter la Fiole d'eau la plus pure à Islen Waterseer dans les Tarides.", description = "Islen aura une nouvelle tâche à vous confier avant de vous récompenser d'un totem. La fiole d'eau que je vous ai donnée est nécessaire à l'accomplissement de cette tâche.\n\nPartez à présent et trouvez-la. Nous nous reverrons dans le futur.", progress = "Bonjour, <nom>. Vous semblez en pleine forme.\n\nQu'est-ce qui vous amène ici si tôt ?", completion = "Ah, une fiole d'eau créée bénite par Brine. Et apportée par vos soins, de surcroît.\n\nLe liquide de cette fiole sera crucial pour créer votre sapta, mais également pour une autre tâche.\n\nVous devrez utiliser le sapta que je vais confectionner pour voir les esprits de l'eau, à l'autel de la forêt des Pins argentés, au sud d'Undercity. Quant aux gouttes qui resteront, je vous dirai quoi en faire si vous pensez que vous êtes prêt. \n\nAlors, êtes-vous prêt pour un nouveau voyage, &lt;nom&gt; ?", rewards = "Vous recevrez :\n\nSapta d'eau"},
[221] = {title = "Worgens dans les bois", objective = "Tuer 12 worgens Messagers Plaie-de-nuit pour Calor en Darkshire.", description = "Vous avez peut-être remarqué de grands worgens accompagnant les Tisseurs d'ombre dans les bois ? D'après ce que nous savons, ces Coureurs sombres renforcent considérablement les rangs de leurs alliés.\n\nLors de mes expéditions, j'ai également découvert qu'ils ont envahi le Verger pourrissant, au sud-ouest de la ville. Ces worgens sont plus résistants que ceux que vous avez combattus précédemment.\n\nRestez donc sur vos gardes.", progress = nil, completion = "Vous avez combattu les worgens avec talent, &lt;nom&gt;. Mais il semble que leurs rangs ne faiblissent pas. À chacune de nos victoires, d'autres surgissent pour augmenter leurs forces.\n\nQuel pouvoir diabolique les attire donc ici ? Pourquoi sont-ils venus troubler notre royaume déjà bien accablé ?\n\nJe vais m'en remettre à maître Carevin. Il trouvera sans nul doute l’origine du problème.", rewards = "Vous recevrez :\n\n"},
[222] = {title = "Worgens dans les bois", objective = "Tuer 8 Crocs noirs Plaie-de-nuit et 8 Contaminés Plaie-de-nuit pour Calor en Darkshire.", description = "Vos victoires passées m'ont convaincu que vous êtes capable de vous mesurer aux plus forts des worgens infestant les bois. \n\nParmi ceux qui se sont établis en ces contrées, les Crocs noirs et les Contaminés se sont montrés les plus dangereux. On peut les trouver près de certaines cavernes et dans la mine, au sud.\n\nVous pourrez voir de loin la lumière des feux qu'ils font avec les os de leurs victimes...", progress = nil, completion = "&lt;nom&gt;, pour être honnête, je n'aurais jamais cru que vous seriez parvenu à cet exploit, mais vous êtes clairement un &lt;classe&gt; sur lequel on peut compter. En fait, si vous souhaitez rejoindre de manière officielle la lutte de maître Carevin, ce serait avec grand plaisir que je vous fournirais une lettre de recommandation.", rewards = "Vous recevrez :\n\n"},
[223] = {title = "Worgens dans les bois", objective = "Apporter la lettre de Calor à Jonathan Carevin.", description = "Voilà, <nom>. Portez ce message à maître Carevin.\n\n<Il sort promptement un morceau de parchemin décoloré et vous le tend.>\n\nEncore d’autres comme vous, et nous pourrons vaincre les Veilleurs ! Peut-être alors serions-nous en mesure d’achever l'œuvre à laquelle si peu d'entre nous se sont attelés.", progress = "Oui, qu'est-ce que c'est ? Soyez bref, je vous prie, j'ai beaucoup à faire.", completion = "Veuillez me pardonner ce bien triste accueil, &lt;nom&gt;, mais je suis certain que vous comprenez ma position. Je suis très sollicité et occupé. Je vois que vous avez impressionné Calor – et je vous assure que ce n'est pas une mince affaire – et qu'il vous recommande. \n\nDes situations très déplaisantes nous attendent, &lt;nom&gt;, et l'aide de chacun peut être mise à profit. Nous combattons des démons, les morts-vivants, et ceux qui les soutiennent. Soyez vigilant, soyez prudent, et ne faites pas confiance à ceux qui n'apporteraient pas leur aide à notre cause. \n\nGloire à la Lumière !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de la foiBouclier de la Foi\n\nVous recevrez également :\n\nBaguette consacrée"},
[224] = {title = "À la défense des terres du roi", objective = "Le Montagnard Cobbleflint de la Tour de garde méridionale veut que vous tuiez 10 Troggs et 10 Eclaireurs Brisepierre.", description = "Nous devons protéger le Loch, <nom> ! Avec tant de soldats du roi combattant vaillamment sur des champs de bataille lointains, les forces nous manquent à l'intérieur. Les troggs nous envahissent depuis la plus petite brèche et constituent la menace principale qui pèse sur Ironforge. Ces répugnants mutants doivent être annihilés.\n\nNous avons besoin de vous, <brave aventurier/courageuse aventurière>, pour mener une expédition et amener le chaos dans leurs rangs. Tuez 10 Troggs et 10 Eclaireurs parmi les Brisepierre.", progress = "Loch Modan est en état de siège, <nom> ! Tous les hommes valides sont requis pour soutenir notre cause. Avez-vous déjà tué 10 Troggs et 10 Eclaireurs Brisepierre ?", completion = "Beau travail, &lt;nom&gt; ! Vous avez montré un incroyable courage sur le champ de bataille. C’est grâce à des efforts et des exploits tels que les vôtres que la guerre contre les troggs pourra être remportée. Vous avez servi le roi Magni avec brio.\n\nSi vous pensez être à la hauteur de ce type d'aventures, je vous suggère d'aller parler au Montagnard Gravelgaw. Le capitaine l'a assigné à une opération de patrouille particulièrement dangereuse, et je suis sûr que votre aide lui sera précieuse. Allez le voir dans la tour.", rewards = "Vous recevrez :\n\nDalaran piquant"},
[225] = {title = "La tombe effritée", objective = "Parler à Sirra Von'Indi à Darkshire.", description = "L'épitaphe, sur la tombe effritée, annonce simplement :\n\nMORGAN LADIMORE\n\n<Après un examen plus minutieux, vous remarquez que l'on a touché à la couche de terre sur la tombe, et qu'une bonne partie semble avoir été déplacée...>", progress = nil, completion = "Morgan Ladimore?\n\nAh, oui, bien sûr. C'est une histoire longue et douloureuse. Je l'ai bien connu, avant qu'il ne parte pour la guerre, et c’est la dernière fois que je l’ai vu. C'était un grand et noble seigneur, mais il a connu une fin malheureuse. \n\nAttendez, je devrais trouver quelque chose ici qui racontera cette histoire mieux que ma pauvre mémoire...", rewards = "Vous recevrez :\n\n"},
[226] = {title = "Des loups aux trousses", objective = "Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre.", description = "Sven et moi avons de difficiles journées qui nous attendent, avec ce Nécromancien à l'est et tout le reste. Et ici, isolés comme nous le sommes, nous devons chasser pour nous procurer de la nourriture. Il semble que chaque fois que je rentre au campement avec un peu de viande sur moi, des loups sauvages affamés ou enragés me poursuivent en quête d'un morceau. Cela va sans dire que vivre ici est une tâche ardue !\n\nMais si vous pouviez nous débarrasser de ces loups, vous nous rendriez les choses un peu plus simples. Ils rôdent pour la plupart au nord et à l'est d'ici, près de la rivière.", progress = "Chassez-vous toujours les loups… ?", completion = "Oh bien. Vous avez dispersé cette meute, et sans ces loups sur notre chemin, nous allons pouvoir concentrer nos forces contre Morbent Fel.\n\nTenez, prenez quelques-uns de ces Sacs de poudre noire. Ils les fabriquent en ville, et beaucoup d'entre eux on été donnés à Sven pour l'aider dans sa tâche.", rewards = "Vous recevrez :\n\nSac de poudre noire"},
[227] = {title = "Morgan Ladimore", objective = "Parler au commandant Althea Ebonlocke à Darkshire.", description = "<Il cherche quelques instants sur les étagères puis en sort un livre relié en cuir.>\n\nSi vous voulez en savoir plus, vous devriez parler à Althea, c'est elle qui s'est occupée du… problème… avec lui ces derniers temps.", progress = nil, completion = "Morgan Ladimore ? Je n'en ai jamais entendu par…\n\nOh, vous voulez dire Mor'Ladim. Je suppose que vous ne connaissez pas l'histoire ?\n\nTrès bien, je vous raconte la version courte. Un mort-vivant du nom de Mor'Ladim vagabonde dans le bois de la Pénombre. D'après ce que nous avons pu comprendre, il s'agit du corps mort-vivant de Morgan Ladimore, quelqu’un que vous connaissez manifestement. Il nous a causé toutes sortes de problèmes, attaquant des Veilleurs en patrouille, et tuant quantité de gens.\n\n&lt;Elle vous jauge du regard.&gt;\n\nVous me semblez être une personne tout à fait capable, peut-être pourriez-vous l'aider à trouver le repos éternel ?", rewards = "Vous recevrez :\n\nL'histoire de Morgan Ladimore"},
[228] = {title = "Mor'Ladim", objective = "Tuer Mor'Ladim, puis rapporter son crâne au commandant Althea Ebonlocke à Darkshire.", description = "D'après ce que m'ont rapporté mes Eclaireurs, Mor'Ladim erre du côté du bois de la Pénombre. On le voit suivre un étrange chemin sinuant à travers le cimetière. Nous l'avons enseveli après la maison sur la colline, vous voyez où c'est ?\n\nIl n'y a rien que je puisse faire pour vous venir en aide, mais je vous souhaite bonne chance.", progress = "Je ne vous blâmerai pas si vous avez du mal à le vaincre, <nom>. Certains de nos meilleurs gardiens ont malheureusement trouvé la mort en l'affrontant…", completion = "Vous l'avez tué ? Cela n'est pas une maigre réussite, &lt;nom&gt; ! Au nom du peuple de Darkshire et des Veilleurs, je vous remercie.\n\nAh... Il reste tout de même un petit problème…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[229] = {title = "La fille qui survécut", objective = "Parler au Gardien Sarah Ladimore à Darkshire.", description = "J'aurais dû vous le dire plus tôt… \n\nComment puis-je m'exprimer… \n\nIl se peut que Morgan ait cru que sa famille tout entière était morte, mais en fait sa fille Sarah est Gardien à présent. Elle a toujours été troublée par les… circonstances... entourant la mort de son père. Peut-être pourriez-vous lui donner des nouvelles.", progress = nil, completion = "Oui ? Mon père… \n\n&lt;Son regard s'assombrit.&gt;\n\nJ'aurais aimé… j'aurais pu faire quelque chose pour lui... Si seulement j'avais pu lui parler avant qu'il ne…", rewards = "Vous recevrez :\n\n"},
[230] = {title = "Le camp de Sven", objective = "Apporter à Sven le Livre de la ferme de Sven.", description = "En creusant, vous trouvez un petit livre, plein de terre.\n\nIl ne porte pas de titre, mais il contient des informations que Sven aimerait connaître.", progress = "Qu'avez-vous découvert ? S'il vous plaît, laissez-moi regarder…", completion = "&lt;Sven parcourt les pages du livre, puis le referme violemment.&gt;\n\nCette obscure silhouette que j'ai vue fut témoin de la mort de ma famille ! J'aimerais poser certaines questions à cet homme… si seulement je savais qui il est !", rewards = "Vous recevrez :\n\n"},
[231] = {title = "L'amour d'une fille", objective = "Déposer la bague de Sarah Ladimore sur la tombe de Morgan Ladimore.", description = "Voilà, prenez ceci et posez-la sur sa tombe. Peut-être… je ne sais comment… comprendra-t-il que je vais bien, et que personne ne le considère responsable de ce qui est arrivé.\n\n<Les larmes perlent à ses yeux à présent, tandis qu'elle enlève une bague de sa main droite, et la presse dans votre paume.>\n\nEt... merci, <nom>.", progress = "Laissez-moi, à présent…", completion = "&lt;Une voix sépulcrale glisse dans la brise...&gt;\n\nEst-ce... ? Sarah ? Se pourrait-il qu'elle soit toujours en vie ? Je suis libéré d'un tel poids...\n\n&lt;nom&gt;, prenez mon épée, Archeus. Maintenant que mon esprit a trouvé le repos, je n'en ai plus l'usage. Elle a été forgée pour le service du Bien, et bien que je m'en sois montré peu digne, peut-être lui ferez-vous retrouver la Lumière.\n\nLys, ma chérie...", rewards = "Vous recevrez :\n\nArcheus"},
[232] = {title = "Course pour l'Apothicaire Zinge", objective = "Apporter le bon de commande à Alessandro Luca dans Undercity.", description = "La Société royale des apothicaires a besoin de vous. Écoutez attentivement et cela sera bénéfique pour nous deux.\n\nL'apothicaire Keever dans l'autre salle risque d'être... vexé. Mais ses recherches porteraient leurs fruits si elles étaient faites par un chercheur plus intelligent. Heureusement, je suis cette chercheuse. Je veux que vous apportiez ce bon de commande à Alessandro Luca, le propriétaire du bazar de la Lune bleue. Il vous donnera une trousse d'analyse. Quand vous l'aurez, rapportez-la moi et je vous expliquerai alors le détail de la quête.", progress = "Oui, que puis-je faire pour vous ? Êtes-vous là de la part de la Société royale des apothicaires, ou vous avez simplement vu de la lumière ?", completion = "Ah, Zinge a besoin d'une trousse, n'est-ce pas ? Je suis triste qu'elle ne soit pas venue en personne.\n\nTrès bien, laissez-moi vous donner la trousse.", rewards = "Vous recevrez :\n\n"},
[233] = {title = "La distribution du courrier de la Vallée des Frigères", objective = "Apporter la pile de lettres à Talin Keeneye.", description = "Hum, je ne pense pas que vous seriez <prêt/prête> à me rendre un petit service, si ? Une pile de lettres est arrivée au tri aujourd'hui, mais je n'ai pas le temps de les distribuer.\n\nElles ont toutes pour destinataire un dénommé Talin Keeneye. Vous pouvez le trouver à l'ouest, sur la route. Il a établi son camp près du lac Gelé.\n\nQu'en dites-vous ?", progress = "Oui, avez-vous quelque chose pour moi ?", completion = "Merci, cela faisait longtemps que je guettais l'arrivée du courrier… \n\nMalheureusement, toutes ces lettres ne me sont pas destinées. Celle-ci est pour Grelin Whitebeard. Il n'habite pas très loin, si vous vouliez la lui remettre…", rewards = "Vous recevrez :\n\n"},
[234] = {title = "La distribution du courrier de la Vallée des Frigères", objective = "Remettre la lettre à Grelin Whitebeard.", description = "Si je me souviens bien, le camp de Grelin se trouve plus bas sur la route, vers le sud-est. Il ne fait aucun doute qu'il serait ravi de recevoir ce courrier.", progress = "Puis-je vous aider ?", completion = "Ah ! Merveilleux. Cela faisait longtemps que je n'avais pas reçu de nouvelles d'Ironforge.", rewards = "Vous recevrez :\n\n"},
[235] = {title = "La Chasse d'Ashenvale", objective = "Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", description = "Votre attention ! Les terres sauvages d'Ashenvale vous attendent tous !\n\nLa Horde s'est établie dans les terres au nord des Tarides. Nos deux avant-postes : le Poste de Bois-brisé et le Poste de la Grève de Zoram s'efforcent bravement d'apporter la gloire à la Horde ! Ceux et celles qui veulent faire montre de leur courage devraient y trouver conseil. De plus, Senani Thunderheart, au Poste de Bois-brisé, directement au nord des Tarides, cherche en ce moment des candidats prêts à prendre part à une grande Chasse d'Ashenvale !", progress = nil, completion = "Bienvenue à la nouvelle frontière, &lt;nom&gt;. Ashenvale est une terre d'opportunités, où un jeune &lt;classe&gt; comme vous peut avoir de nombreuses chances de prouver sa vaillance. Faites le tour de l'Avant-poste et n'oubliez pas de voyager jusqu'à la Grève de Zoram, étant donné que la Horde a aussi un autre Avant-poste, là-bas.\n\nVotre présence ici me dit que vous êtes venu pour en apprendre plus sur l'art de la chasse. Écoutez attentivement, et je partagerai volontiers avec vous le savoir qui vous manque.", rewards = "Vous recevrez :\n\n"},
[236] = {title = "Alimenter les démolisseurs", objective = "Le Maître de siège Rudemanche, à la Forteresse de Joug-d’Hiver, vous a demandé de récupérer 10 Braises éternelles sur des personnages-joueurs de la Horde, au Chaudron des flammes.", description = "<nom> ! Il était temps que vous arriviez. Cette bataille est peut-être terminée, mais nous devons nous préparer pour la prochaine. Rendez-vous au Chaudron des flammes, au sud-est de Joug-d’Hiver, et récupérez quelques braises éternelles.\n\nMélangées à du charbon, elles servent à alimenter les démolisseurs et les engins de siège.\n\nOh, et si vous voyez des membres de la Horde dans le Chaudron, n’hésitez pas à les tuer pour leur prendre leurs braises. Nous ne pouvons pas les laisser prendre l’avantage lors du prochain combat.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[237] = {title = "À la défense des terres du roi", objective = "Le Montagnard Gravelgaw de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir.", description = "Le Montagnard Cobbleflint n'a pas tari d’éloges à votre égard, <nom>. Aussi, je vais vous confier une mission de la plus haute importance. Nous devons maintenir la pression sur les forces d'invasion des troggs jusqu'à ce que les nains, nos frères, reviennent du front de l'Alliance. \n\nMettez-vous en route pour les collines méridionales et tuez 10 Brise-crâne et 10 Prophètes Brisepierre. Vos attaques nous feront gagner un temps précieux. Revenez me voir une fois votre mission menée à bien.", progress = "Nous avons besoin de plus de temps, <nom>. Vos ordres sont de tuer 10 Brise-crâne et 10 Prophètes Brisepierre. Maintenez la pression sur l'ennemi jusqu'à l’arrivée de nos renforts. L’heure n'est pas à l'immobilisme.", completion = "Vous avez accompli votre mission, &lt;nom&gt;. Le roi en personne serait fier. \n\nLes renforts promis ne sont cependant jamais arrivés. Apparemment, le front de l'Alliance est rouge du sang de nos frères. Les nouvelles sont amères et les pertes lourdes, mais nous devons faire en sorte que leur mort ne soit pas vaine. Il faut nous rassembler, en ces temps difficiles, et ramener l'Alliance sur le chemin de la gloire.\n\nAllez voir le Montagnard Wallbang, il vous donnera une nouvelle mission. Nous avons besoin de vous, maintenant plus que jamais.", rewards = "Vous recevrez :\n\nPotion de soins inférieure"},
[238] = {title = "Course pour l'Apothicaire Zinge", objective = "Apportez une Trousse d'analyse de terrain à l'Apothicaire Zinge à Undercity.", description = "La trousse est prête, <nom>. L'apothicaire Zinge souhaite sûrement l'avoir le plus vite possible. Apportez-la-lui sans tarder et dites-lui que j'ai mis cela sur le compte de la Société. Passez-lui également mes plus sincères salutations.\n\nEh bien, ne restez pas là. C'est pourtant simple d'être coursier, non ?", progress = "Oui, je trouve que Luca est inquiétant tout autant que vous. Qu'importe - donnez-moi la trousse d'analyse de terrain. Je vais faire les modifications nécessaires pour qu'elle soit adaptée aux bons matériaux.\n\nVous avez bien la trousse, non ?", completion = "Bien. Je suis heureuse de travailler avec quelqu'un qui ne perd pas de temps.\n\nAprès avoir fait les modifications sur la trousse, tout sera prêt pour que vous alliez sur le terrain. Vous irez collecter des données vitales pour la tâche en cours.\n\nCela va prendre juste un moment pour achever les modifications. Pendant que vous attendez, vous devriez commencer à penser à ce dont vous aurez besoin dans le désert.\n\nOui, j'ai bien dit le désert.", rewards = "Vous recevrez :\n\n"},
[239] = {title = "Au secours de la garnison du ruisseau de l'ouest !", objective = "Se rendre à la garnison du ruisseau de l'ouest et parler à l’Adjoint Rainer.", description = "La garnison basée sur notre frontière à l'ouest fait état d'une augmentation de l'activité des gnolls et des voleurs. Elle demande plus de soldats de Stormwind, mais nous ne pouvons nous passer d'aucun !\n\nSi vous le pouvez, votre aide sera la bienvenue. Allez voir l’Adjoint Rainer à la garnison du ruisseau de l'ouest. Il vous dira de quoi il s'agit.\n\nLa garnison se trouve le long de la route, à l'ouest. Après avoir traversé le pont au-dessus du ruisseau, ce sera sur la droite.", progress = nil, completion = "C'est le maréchal Dughan qui vous envoie, pas vrai ? Vous ne faites pas partie de l'armée, mais si vous venez de la part de Dughan, cela me suffit !\n\nLa situation ici est, c'est le moins qu'on puisse dire, tendue. J'espère que vous pouvez nous donner un coup de main.", rewards = "Vous recevrez :\n\n"},
[240] = {title = "Retour vers la Tremblotte", objective = "Retourner voir la Tremblotte avec des Gâteaux au crabe brun.", description = "Et nous y voilà. Des gâteaux au \"crabe\" façon Grual.", progress = "<nom>, vous voilà ! Avez-vous ma nourriture ?", completion = "Ah ! merci, &lt;nom&gt;. Ça fait du bien là où ça fait mal !\n\nEt attendez, laissez-moi vous payer pour ça !", rewards = "Vous recevrez :\n\n"},
[243] = {title = "Sur le terrain", objective = "Parler à l'Ingénieur en chef Bilgewhizzle à Gadgetzan afin d'obtenir une source d'énergie pour la trousse d'analyse.\n\nObjet fourni : \n", description = "Vous allez vous rendre dans le désert de Tanaris, pour tester la consistance des tissus des basilics, des scorpides et des hyènes de la région. Récupérez des échantillons de tissus et placez-les dans la trousse d'analyse ; certains ne conviendront sans doute pas. Il me faut huit échantillons corrects pour chacun des trois types de créatures.\n\nDe plus, les gobelins de Gadgetzan ont une source d'énergie utilisable avec ce genre de trousse modifiée. Allez parler à l'ingénieur en chef Bilgewhizzle et récupérez-en pour la trousse.\n\nNe revenez me voir que si vous réussissez.", progress = nil, completion = "Ah, notre source d'énergie modèle 4711-FTZ ! Nous les utilisons normalement pour les puits d'eau, mais GRACE AUX VILS NOMADES, nous en avons en abondance maintenant.\n\nPour sûr, je peux vous avoir une source d'énergie pour les horribles expériences que vous allez faire et que vous voudriez me cacher. Cependant, cela ne sera pas gratuit, &lt;nom&gt;. Rien n'est gratuit à Gadgetzan.", rewards = "Vous recevrez :\n\n"},
[244] = {title = "Des gnolls encombrants", objective = "Informer l’Adjoint Feldon.", description = "Je vous salue, <classe>. On m'a chargé de patrouiller sur ce bout de route. Bien qu'elle soit sûre pour l'heure, j'ai vu des campements de gnolls au nord et à l'est d'ici.\n\nLakeshire doit être mise au courant de ce rassemblement de forces ! Allez voir l’Adjoint Feldon et informez-le. Faites-le, et je suis sûr qu’il vous offrira la prime d'un éclaireur. \n\nD'ordinaire, Feldon inspecte les lieux au sud du pont menant à Lakeshire.", progress = nil, completion = "Des gnolls venus des Carmines se rapprochent d'Elwynn ? Ils doivent être acculés pour se risquer sur nos terres. Il se peut que bientôt, les gens de Lakeshire ne soient plus les seuls humains à être assiégés.\n\nVoici votre paie, bien que vous ameniez de terribles nouvelles. Et ça arrive au plus mauvais moment, nous ne sommes pas équipés pour régler le problème.", rewards = "Vous recevrez :\n\n"},
[245] = {title = "Les plaies à huit pattes", objective = "Tuer 15 Araignées Tisse-venin pygmées, puis rendre compte à la Sentinelle Dodds au bois de la Pénombre.", description = "Je vous salue, <classe>. Peut-être avez-vous vu ces araignées qui ont envahi la frontière ouest ? Nous n'avons pas les forces nécessaires à une attaque, et le commandant n'a pas suffisamment d'hommes pour en envoyer si loin de Darkshire.\n\nCela me gêne de vous le demander, mais il semble que vous êtes de taille à vous en occuper. Je ne peux rien vous promettre de grande valeur, mais je vous récompenserai si vous parvenez à déloger ces horribles bestioles.\n\nOh, un petit conseil : évitez leur venin...", progress = nil, completion = "Ah ! Vous êtes de retour. Et en vie, il semblerait. Bien sûr, &lt;nom&gt;, les Veilleurs vous sont reconnaissants pour votre travail, et je vous ai promis une récompense. Tenez.", rewards = "Vous recevrez :\n\nGantelets de veilleur"},
[246] = {title = "L'appréciation du danger", objective = "Tuer 10 Bâtards des Carmines et 6 Braconniers des Carmines, et aller faire un rapport à l’Adjoint Feldon à Lakeshire.", description = "Nous ne pouvons nous passer de personne, la présence de chacun est vitale ici. Pourtant, quelque chose doit être fait à propos de ces gnolls dont vous m'avez parlé.\n\nPartez à leur recherche, au sud des Carmines. Harcelez-les, tuez tous ceux que vous pouvez et revenez m'informer de leur nombre et du danger potentiel qu'ils représentent. Vous trouverez le camp des gnolls le long de la route sud des Carmines.\n\nFaites-le pour l'armée de Stormwind, <nom>, et vous serez <récompensé/récompensée>.", progress = "Pardonnez-moi, <nom>, mais il y a beaucoup à faire ici. Si vous n'avez aucune information à me donner, laissez-moi m'occuper des questions importantes.", completion = "&lt;L’adjoint Feldon écoute votre rapport...&gt;\n\nBeaucoup de gnolls se sont rassemblés là-bas, et d'après ce que vous dites, ils sont coriaces. Il n'a pas dû être facile de rassembler ces informations...\n\nTenez, &lt;nom&gt;. Nous vous sommes reconnaissants de votre aide.\n\nSi vous ne l'avez pas déjà fait, allez voir le maréchal Marris et le magistrat Solomon ici même, à Lakeshire. Notre situation ne cesse de se détériorer. Ces deux-là vous trouveront quelque chose, j'en suis sûr.", rewards = "Vous recevrez :\n\n"},
[247] = {title = "La chasse achevée", objective = "<nom>, vous avez tué les trois bêtes qui composent la Chasse d'Ashenvale. Vous m'avez apporté les preuves de leur mort ; je ne doute plus de votre force ni de votre ténacité. Le sang d'un chasseur coule dans vos veines, et je vous en félicite !\n\nS'il vous plaît, acceptez ceci pour vous récompenser de la prouesse que vous avez accomplie pour la Horde, à Ashenvale. Que vos ancêtres vous protègent !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCape de chasseur de fauves"},
[248] = {title = "En regardant plus loin", objective = "Monter au sommet de la Tour de garde intacte près du Donjon de Guet-de-pierre, puis trouver dans quoi placer le Glyphe d'Azora.", description = "J'ai observé la Tour d'Ilgalar, et ai découvert que Morganth est entré en conflit avec les orcs au donjon de Guet-de-pierre. Je n’en connais pas la raison, mais vous pourriez m'aider à lever le voile sur ce mystère.\n\nPrenez donc le Glyphe d'Azora, et rendez-vous au sommet de la Tour de garde restée intacte, près du donjon de Guet-de-Pierre.\n\nLà, trouvez un objet dans lequel placer le glyphe. Un coffre, une jarre, qu'importe, pourvu que le glyphe ne puisse pas être détecté.", progress = "Il y avait une liqueur puante dans ce pichet, mais le voilà vide et abandonné sur ces barriques.", completion = "C'est un endroit convenable pour placer le Glyphe d'Azora, et pour permettre à Théocritus de lire dans l’esprit des occupants du Donjon de Guet-de-pierre.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[249] = {title = "Morganth", objective = "Tuer Morganth, puis rapporter son Pendentif des ombres à Théocritus, à la Tour d'Azora dans la forêt d'Elwynn.", description = "Après une longue surveillance, j'ai découvert les plans de Morganth.\n\nIl recherche la faux d'Elune… et il se peut même qu'il l'ait déjà trouvée ! S'il se l'est appropriée, alors les Carmines et le royaume de Stormwind tomberont bientôt sous son joug.\n\nJe ne suis pas prêt à l’affronter, mais j'ai peur qu'il faille s'en occuper dès à présent. Vous devez donc pénétrer dans la tour d'Ilgalar, et combattre Morganth.\n\nRemportez la victoire, et apportez-moi son pendentif des ombres. Si vous réussissez, le royaume vous sera grandement redevable.", progress = "Hâtez-vous, <nom>, avant que mes craintes ne se réalisent !", completion = "Vous avez bien œuvré, &lt;nom&gt;. En battant Morganth le démoniste, vous avez mis Stormwind à l'abri d'un grave danger.\n\nJe vous remets, en toute humilité, cette récompense. Avec cela, je vous souhaiterais la paix, si ces temps troublés permettaient un tel vœu.\n\nMais je vous souhaite une bonne fortune dans vos futures épreuves, et la victoire dans les combats qui vous attendent.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMantelet rose"},
[250] = {title = "Une sombre menace se dessine", objective = "Enquêter près de la rampe est du barrage et rapporter à l'ingénieur en chef Hinderweir un indice qui permettrait de deviner les intentions des nains Sombrefer.", description = "Grâce au Ciel, quelqu'un s'inquiète pour le barrage ! D'abord la destruction du viaduc de Thandol, ensuite le pillage de Dun Modr ! Je suis sûr que le barrage est la prochaine cible des Sombrefer. La plus grande partie de mon détachement de sécurité a été dépêché sur le front de l'Alliance, y compris mon meilleur inspecteur.\n\nC'est pourquoi j'ai besoin de vous, <nom>. J'ai aperçu quelques Sapeurs Sombrefer près de la rampe est du barrage. Enquêtez sur place, et ramenez un indice.", progress = nil, completion = "Ce tonneau à l'aspect suspect contient une poudre à l’odeur étrange.", rewards = "Vous recevrez :\n\n"},
[251] = {title = "La traduction de la lettre d'Abercrombie", objective = "Apporter la lettre à Ello, à Sirra Von'Indi.", description = "Apportez la lettre que vous m'avez donnée à Sirra Von'Indi. C'est un érudit en lettres anciennes. Si quelqu’un ici peut traduire ce message, c'est lui !", progress = "Une lettre d'Abercrombie l'ermite, hein ? Je ne le connais pas, mais s'il vit au cimetière, je sais que son cerveau a pourri !", completion = "&lt;Sirra commence à traduire la lettre...&gt;", rewards = "Vous recevrez :\n\n"},
[252] = {title = "La traduction pour Ello", objective = "Remettre la lettre traduite au seigneur Ello Ebonlocke.", description = "Bon sang ! Si ce qui est écrit là est vrai, alors ce qu'a fait Abercrombie est… incroyable.\n\nVous devez la transmettre à Ello.\n\nEt faites vite, car je crains qu'un sort funeste n'avance déjà vers notre ville...", progress = "Alors, la lettre est-elle traduite ? S'il vous plaît, laissez-moi voir…", completion = "&lt;Ello prend connaissance de la lettre… et blêmit. Il se tourne alors vers vous...&gt;\n\nBien que votre soutien à Abercrombie ait certainement été dicté par de bons et nobles sentiments, vos actions ont condamné notre ville.\n\n&lt;Ello reste plongé dans ses pensées...&gt;", rewards = "Vous recevrez :\n\nLettre traduite de l'Embaumeur"},
[253] = {title = "La fiancée de l'Embaumeur", objective = "Trouver la tombe d'Eliza, retrouver le cœur de l'Embaumeur, puis retourner voir Ello Ebonlocke.", description = "Le nom de l’Embaumeur apparaît dans l'une des histoires que se racontent les enfants. C'était un alchimiste bon et généreux, rendu fou par la mort de sa femme, Eliza. Dans le but de la ressusciter, il utilisa la magie noire et plaça son propre cœur dans la poitrine de son épouse décédée.\n\nIl réussit à faire revivre Eliza... mais celle-ci était à présent désormais avide de chair humaine, et l'Embaumeur dut se résoudre à l'enterrer.\n\nSon cœur est son pouvoir. Trouvez la tombe d’Eliza, récupérez son cœur, et ramenez-le-moi pendant qu'il bat encore. Procédez ainsi et son pouvoir s'éteindra.", progress = "Avez-vous découvert la tombe d'Eliza ? Êtes-vous en possession du cœur de l'Embaumeur ?", completion = "Vous avez réussi ! La magie contenue dans ce cœur est la preuve de la malveillance de l'Embaumeur, et d'une malédiction puissante planant sur la ville de Darkshire.\n\nVous avez rendu un grand service à notre peuple, &lt;nom&gt;. Votre nom restera gravé à jamais dans notre histoire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMantelet d'honneurCimier de Darkshire"},
[254] = {title = "En creusant la terre", objective = "Vous creusez dans la saleté molle au-dessus de la tombe... et vous trouvez les restes d'un cercueil.\n\nVous sentez le cercueil vibrer sous l'effet de ce qui semble être des griffes qui raclent à l'intérieur, et vous entendez le grincement de dents en décomposition...\n\nAllez-vous ouvrir le cercueil et récupérer le cœur de l'Embaumeur ?", description = nil, progress = nil, completion = nil, rewards = nil},
[255] = {title = "Mercenaires", objective = "Le magistrat Bluntnose de Thelsamar vous a <embauché/embauchée> pour tuer 4 Ogres, 4 Brutes et 4 Massacreurs Mo'grosh.", description = "Deux mois d'attente, et pour apprendre que seule une poignée d'hommes sera dépêchée ici, et qu'il lui faudra deux autres mois pour arriver ! Je comprends que notre ville risquerait d’être sans protection, mais le site de fouilles et le barrage – le barrage ! – sont également l’objet d’attaques.\n\nJe n'ai pas le choix, je vais devoir embaucher des mercenaires.\n\nQu'en pensez-vous ? Vous semblez faire l'affaire, <classe>. Un groupe d'ogres s'est établi au nord-est du lac. Vous pourriez peut-être recruter d'autres mercenaires et nous débarrasser de la menace qui pèse sur notre ville?", progress = nil, completion = "Ah ! voilà d'excellentes nouvelles. Vos efforts sont grandement appréciés par moi-même et par le peuple de Thelsamar. Mieux encore, si nous pouvons résoudre le problème des ogres, nous pourrons nous concentrer sur ces troggs impies.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[256] = {title = "ON RECHERCHE : Chok'sul", objective = "Tuer Chok'sul et rapporter sa tête au Magistrat Bluntnose de Thelsamar.", description = "Par décret du Magistrat de Thelsamar : Chok'sul, l'ogre que l'on croit être l'instigateur et le chef des attaques menées sur la ville de Thelsamar, sur le barrage de Formepierre et sur les excavations, est recherché mort, et mort seulement.\n\nLa récompense sera donnée à celui qui apportera la preuve de sa mort au Magistrat.\n\nLa dernière fois que Chok'sul a été vu, il se trouvait au camp des ogres au nord-est de Loch Modan.", progress = "Oui ? Il y a quelque chose que je peux faire pour vous ?", completion = "Pouah ! Qu'est-ce que c'est ? Et pourquoi m'app…\n\nBon sang ! Est-ce que… Eh bien ! que la Lumière me brûle, n'est-ce pas la tête de ce maudit ogre ? Vous parlez d'un trophée ! Tenez, prenez votre récompense. Le peuple de Thelsamar et moi-même vous remercions.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpaulières en mailles solidesBottes de Kimbra\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nAnneau de canalisation mineure"},
[257] = {title = "La fanfaronnade d'un chasseur", objective = "Tuer 6 Busards des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en moins de 15 minutes.", description = "Vous croyez pouvoir vous mesurer à Daryl l'Intrépide, hein ? Si j'étais vous, je n’y croirais pas ! Bien sûr, vous êtes libre d'essayer. Voilà un défi qui devrait être au-dessus de vos capacités, alors ne culpabilisez pas trop si vous n'êtes pas à la hauteur.\n\nUn groupe de Buses s'est établi ici à Loch Modan. Pourquoi ne pas essayer d'en désabuser certaines ? Voilà le marché : si vous parvenez à accomplir le défi en quinze minutes, je vous donne mon arc ou mon fusil.\n\n<Il vous jauge dédaigneusement.>\n\nVous n'avez pas grand-chose à perdre, de toute façon...", progress = "On n'y arrive pas, hein ? Ne vous en faites pas trop, Elfmaner...\n\nTout le monde ne peut pas être moi.", completion = "Quoi ! Vous y êtes arrivé?\n\nSuivez mon conseil, Murlocfarmama, que ce succès ne vous monte pas à la tête ! N'importe quel gamin impubère équipé d'un arc aurait pu abattre de tels… oisillons. Et j'espère que vous n'aimez pas trop tâter de la Buse, hein ? Nous ne voudrions pas que cet oiseau devienne une espèce en voie de disparition.\n\nBien, euh... Il ne sera jamais dit que Daryl le Jeune ne tient pas sa parole.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc de chasse de DarylCarabine de chasse de Daryl\n\nVous recevrez également :\n\n"},
[258] = {title = "Le défi d'un chasseur", objective = "Tuer 5 Anciens sangliers des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en 12 minutes.", description = "<nom>af, c'est ça ? Je vois que vous exultez pour avoir réussi le premier test, pas vrai ? Comme je vous l'ai dit, ce n'était pas grand-chose.\n\nVous devriez vous essayer à la chasse au sanglier. Croyez-moi, cela n'a rien à voir avec la chasse au sanglier de la Vallée des Frigères, alors prenez vos précautions. Vous n'aurez que douze minutes cette fois-ci.\n\nEt ne soyez pas <déçu/déçue> en cas d’échec. Je vous donnerai ma chemise si vous réussissez !\n\nÀ propos, je vous ai déjà raconté comment j'ai reçu ma célèbre cicatrice ? Non ? C'était il y a deux ans...", progress = "C'est tout à fait naturel de se sentir lamentable lorsque l'on se tient aux côtés de quelqu'un aussi exceptionnel. N'allez pas vous évanouir, n'est-ce pas, Jackalasah ?\n\nHum ? Ai-je écorché votre nom ?", completion = "Vous avez l'air fatigué. Les sangliers vont ont posé quelques problèmes, n'est-ce pas ? Ne vous en faites pas, je ne dirai rien à personne. J'imagine que c’est déjà suffisamment difficile sans que les langues commencent à parler et les sarcasmes à fuser.\n\nOh ! Vous êtes parvenu à vaincre les sangliers ? Je... eh bien ! c'est... je veux dire, cela ne me surprend pas ! Le premier nourrisson venu aurait pu... pari ?\n\nQuel pari ?", rewards = "Vous recevrez :\n\nChemise éléganteEpée courte de Daryl"},
[260] = {title = "<INUTILISÉ>", objective = "Rassembler 5 Dents et 5 Griffes de battrodon, puis les apporter à Kelt Thomasin.", description = "Bien, cela vous convaincra sans aucun doute que je suis, comme ils disent – et ne démentez pas, je sais ce qu'ils disent – un esprit confus, obsédé par une légende improbable. Il s'agit d'un vieux conte nain, qui parle d'un monstre gigantesque vivant dans les profondeurs du loch. J'ai passé une bonne partie de ma vie à essayer de le traquer, et je n'en étais pas loin, mais hélas mon âge avance plus vite que moi à présent. Si vous voulez chasser le monstre du loch, apportez-moi des dents et des griffes de battrodon.\n\n<Il sourit mystérieusement.>", progress = nil, completion = nil, rewards = nil},
[261] = {title = "Sur le chemin écarlate", objective = "Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel.", description = "Je serai franc. Nous sommes en guerre contre le Fléau. C'est un mal qui corrompt notre peuple et pollue nos terres. Il faut l'arrêter avant qu'il ne nous prenne de vitesse et n'entraîne notre monde dans l'obscurité. Nous, la Croisade écarlate, avons juré de combattre le Fléau de toutes nos forces et de toute notre âme.\n\nSi vous êtes de notre bord, faites montre de votre courage et prouvez-nous votre allégeance en détruisant les Ravageurs morts-vivants de Désolace, dans la vallée des Ossements, plus au sud.\n\nFaites cela, et la Croisade vous portera en haute estime.", progress = "À chaque jour qui passe, le Fléau devient plus puissant. Si vous voulez vraiment arrêter sa croissance, eh bien montrez-le-moi !", completion = "Vous avez fait montre d'une grande résolution, et la Croisade écarlate vous applaudit.\n\nSi le juste massacre ne vous intimide pas, alors peut-être que votre destin est de devenir des nôtres…", rewards = "Vous recevrez :\n\n"},
[262] = {title = "L'obscure silhouette", objective = "Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Darkshire.", description = "Je dois savoir qui était ce rôdeur que j'ai vu dans les ombres, la nuit où ma famille a été tuée !\n\nJe vous en prie, <nom>, vous avez montré que vous êtes <plein/pleine> de ressources, trouvez cet individu. Je dois apprendre les secrets qu'il détient !\n\nJe n'ai aucun autre indice que vous ne connaissiez déjà, mais tenez, prenez le livre que vous avez trouvé à la ferme. Peut-être quelqu'un pourra-t-il faire un lien entre ce livre et son propriétaire.", progress = "Si vous possédez quelque chose ayant appartenu à l’obscure silhouette que vous recherchez, laissez-moi le voir. Je pourrais ressentir des choses concernant son propriétaire.", completion = "Hum… Quelqu'un a tenu ce livre récemment, quelqu'un mû par un désir de vengeance. Mais les impressions laissées sur ce livre, du moins les impressions de son premier propriétaire, sont estompées.\n\nCependant, ce dont on peut être sûr, c'est que ce premier propriétaire n'est pas originaire de Darkshire.", rewards = "Vous recevrez :\n\n"},
[263] = {title = "À la défense des terres du roi", objective = "Le Montagnard Wallbang de la Tour de garde méridionale veut que vous tuiez 10 Chamans et 10 Briseurs d'Os Brisepierre.", description = "Les Montagnards disent que vous êtes <courageux/courageuse> et <compétent/compétente>, <nom>. Nous avons besoin de gens tels que vous ici. Le problème avec les troggs ne s'arrange pas. Les réservistes ont été envoyés à la guerre et nous sommes seuls. Mais à présent que nous avons un <classe> expérimenté comme vous, <nom>, nous allons voir de quoi vous êtes capable.\n\nSortez et tuez 10 Chamans et 10 Briseurs d'Os Brisepierre. Nous allons voir si votre réputation est fondée, <tueur de/tueuse de> troggs.", progress = "De retour, déjà ! Au cas où je n'aurais pas été suffisamment explicite, vous devez tuer 10 Chamans et 10 Briseurs d'Os Brisepierre, <nom>. À présent prenez soin d'eux, tueur de troggs.", completion = "J'ai su, à la seconde même où j'ai posé les yeux sur vous, &lt;nom&gt;, qu'Ironforge serait fière de vous. Vous avez bien servi le roi Magni. Maintenant que vous avez montré votre valeur, et que vous êtes un fidèle allié du royaume, vous devriez parler au capitaine, pour voir s'il a une mission plus cruciale à vous confier. Je vous salue, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nPierre à aiguiser grossière"},
[264] = {title = "Jusqu'à ce que la mort nous sépare", objective = "Placer le pendentif de Clarice sur la tombe de Yuriv, dans la forêt des Pins argentés.", description = "Ordure abjecte ! Me laisser pour cette maudite croisade. Parce que \"la Lumière est notre bien le plus précieux contre la menace des morts-vivants.\"\n\nEt ses enfants alors ? Et MOI ? Nuit après nuit, je l'ai attendu… à toujours passer après son fichu devoir !\n\nEh bien ! Regardez ce que la \"justice\" apporte, <nom> ! Il est mort et je porte au cou ce qu'il essayait d'arrêter !\n\nPortez ce bout de ferraille sur sa tombe au Sépulcre. Je ne veux plus rien avoir à faire avec ça... et avec lui !", progress = "La pierre tombale est froide au toucher, mais elle a de toute évidence été touchée, elle est griffée d’entailles et d’estafilades. Des déchets jonchent le sol, la végétation commence à envahir le site.\n\nPersonne ne se soucie de savoir qui est enterré ici, et encore moins les victimes du Fléau.", completion = "Vous placez le pendentif sur la tombe, et l’éclat de sa gemme semble se ternir.\n\nTandis que vous vous relevez pour quitter l'endroit, vous jetez un œil au pendentif : il repose, éteint, sur le relief sculpté au-dessus de la tombe. Vos pensées sont interrompues par une brise vive et soudaine, passant sur la sépulture. Pendant quelques instants, tout est silencieux.", rewards = "Vous recevrez :\n\n"},
[265] = {title = "L'obscure recherche se poursuit", objective = "Voir si d'autres habitants ont des indices concernant l'obscure silhouette.", description = "Je vous rends votre livre, <nom>, et vous souhaite bonne chance dans vos recherches. Si vous enquêtez auprès d'autres personnes en ville, elles seront peut-être en mesure de vous fournir d’autres indices.\n\nEn attendant, en voici un : bien que l'auteur de ce livre soit étranger à Darkshire, le livre lui-même a été acheté ici.", progress = "Je vends parfois des livres vierges à des érudits, des mages, ou à quiconque souhaite tenir un journal.\n\nJe me souviens de tous ceux qui m'ont acheté un livre durant ces derniers mois.", completion = "Ah oui ! J'ai vendu ce livre, il y a un mois de cela, à quelqu'un de plutôt louche. Il ne m'a pas dit son nom, mais il était nerveux, aux aguets, toujours à regarder par-dessus son épaule.\n\nJ'espère vous avoir aidé...", rewards = "Vous recevrez :\n\n"},
[266] = {title = "Une enquête à l'auberge", objective = "Chercher à l'auberge des indices concernant l'obscure silhouette.", description = "Voici votre livre, et bonne chance dans votre quête.\n\nVous devriez aller jusqu'à l'auberge. Si celui que vous recherchez a passé quelque temps en ville, on l’a peut-être vu là-bas.", progress = "Le Corbeau écarlate ne fait plus autant d'affaires que par le passé, mais certains voyageurs s'y arrêtent encore.\n\nSi vous pouvez décrire la personne en question, peut-être que je m'en souviendrai.", completion = "Oh oui ! je me souviens de ce livre. Son propriétaire a réservé une chambre pour quelques jours, et a passé ses nuits au bar, à écrire.\n\nIl a quitté la ville précipitamment, marmonnant qu'il était chassé par… quelque chose. La dernière fois que je l'ai vu, il allait en direction de l'ouest, à la recherche d'un nouvel endroit où se terrer.\n\nLe premier endroit à l'ouest qu'il a pu trouver, c'est Colline-aux-Corbeaux...", rewards = "Vous recevrez :\n\n"},
[267] = {title = "La menace trogg", objective = "Apporter 8 Dents de pierre de troggs au capitaine Rugelfuss à la Tour de garde méridionale.", description = "<classe>, il se peut que vous ayez entendu parler de la menace que les troggs font peser sur les nains. Les réservistes ayant été appelés pour servir sur le front de l'Alliance, nous nous retrouvons avec bien peu de forces pour assurer la sécurité de nos terres. Mon régiment a pour mission de garder la porte, ici, et nous ne pouvons quitter notre poste, nous craignons trop une invasion.\n\nMais nous devons attaquer ces maudits troggs, qui se terrent dans les collines. Si vous vous en sentez capable, lancez un assaut contre eux. Ramenez-moi 8 Dents de pierre de trogg comme preuve de votre réussite.", progress = "Avez-vous ces 8 Dents de pierre à me montrer ? Si ce n'est pas le cas, il vous reste du travail à accomplir, <nom>.", completion = "Vous m'impressionnez, &lt;nom&gt;. Vous avez rendu un grand service à la race des nains en défendant nos terres. Le roi Magni Bronzebeard sera fier !", rewards = "Vous recevrez :\n\n"},
[268] = {title = "Retourner voir Sven", objective = "Retourner voir Sven avec le journal complété de la Tremblotte.", description = "Le livre que vous avez trouvé n'était écrit qu'à moitié. J'ai dû le laisser à l'exploitation de Sven lorsque je me suis enfui jusqu'ici…\n\nTenez, prenez la version complète de mon journal et donnez-la à Sven. Il décrit de manière plus exhaustive ce qu'il s'y est déroulé.\n\nCe journal a été ma seule compagnie durant ces dernières semaines, mais je vous le donne volontiers si cela m'épargne d’affronter Sven et sa colère.", progress = "Avez-vous découvert l'identité de l'obscure silhouette ?", completion = "Ce journal m'en apprend beaucoup et je sais qu'il me faut maintenant affronter les Cavaliers noirs ! J'ai vu ces maudits au bois de la Pénombre. Je les ai vus parler au sorcier Morbent Fel, à la masure lugubre.", rewards = "Vous recevrez :\n\n"},
[269] = {title = "À la recherche de la sagesse", objective = "Donner le journal complété de la Tremblotte à l'évêque Farthing à Stormwind.", description = "Rendez-vous à la cité de Stormwind et parlez à l'évêque Farthing dans la cathédrale de la Lumière. Donnez-lui le journal de la Tremblotte et dites-lui que vous voulez combattre Morbent Fel.\n\nBien que Stormwind ait abandonné Darkshire, Farthing est un homme aimable et empli de sagesse. Il pourrait vous aider dans votre quête pour nous sauver.\n\nVotre mission est périlleuse, mais hâtez-vous, <nom>. À chaque heure qui s'écoule, le bois de la Pénombre s'assombrit encore...", progress = "Reposez-vous, mon frère. Je vois que vous avez fait un long voyage, et qu'un lourd fardeau vous accable. Pouvez-vous me dire ce qui vous soucie tant ?", completion = "&lt;Après avoir lu le journal et écouté vos desseins...&gt;\n\nLe Mal s'établit encore plus dans le bois de la Pénombre, qui a déjà beaucoup souffert. Je remercie la Lumière de nous avoir envoyé un héros tel que vous pour y faire face.\n\nMais vous devez vous préparer à l'épreuve qui vous attend... Le Nécromancien Morbent Fel est infiniment puissant et il s'est protégé, grâce à la magie noire, de tout assaut physique. Si vous voulez le vaincre, vous aurez besoin d'une arme qui neutralise ses protections.", rewards = "Vous recevrez :\n\n"},
[270] = {title = "La Flotte perdue", objective = "Aller au port de Menethil, dans les Paluns, et parler à Glorin Steelbrow.", description = "Il y a des années, la IIIe flotte de Kul'Tiras a coulé le long des côtes des Paluns, une étendue marécageuse située au nord du royaume nain d'Ironforge. Un vaisseau avait à son bord un chargement de fer de sancteforge.\n\nLes objets forgés dans ce métal précieux frappent avec la force de la sainte vérité. Si vous devez combattre Morbent Fel, vous aurez besoin d'une telle arme.\n\nAllez au port de Menethil, et rencontrez mon confrère le nain Glorin Steelbrow. S'il existe une chance de retrouver ce précieux métal, il vous indiquera où le chercher.", progress = nil, completion = "Le fer de sancteforge est un métal précieux, mais votre quête paraît ardue. Vous venez de loin. Avec de la chance, vous trouverez ce que vous cherchez !\n\nEt si vous parvenez vraiment à en obtenir, je sais qui pourra en tirer une arme pour vaincre ce nécromancien du bois de la Pénombre dont vous parliez.", rewards = "Vous recevrez :\n\n"},
[271] = {title = "La vengeance de Vyrin", objective = "Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Blanc-bec au pavillon des pérégrins.", description = "Je suppose que vous ne seriez pas contre le fait de rabattre un peu le caquet de Monsieur le Brave ? Daryl a une certaine habileté, il nous le rabâche assez.\n\nIl y a un an, un grand ours était dans le collimateur du pavillon des pérégrins, mais pas un chasseur ne réussissait à le tuer. Alors Daryl s'est dit qu'il allait s'en occuper. La seule chose qu'il y a gagnée, c'est cette vilaine cicatrice à l’œil.\n\nTuez cet ours, ça clouera le bec de Daryl, pour une fois.\n\nVous trouverez cet ours, le vieux Noiraud, près de sa tanière dans les collines, au-delà de Thelsamar.", progress = "Ah; <nom> ! Déjà de retour ? Vous étiez sans doute à la chasse ? Ne vous inquiétez pas si vous rentrez bredouille, ça ira mieux demain !\n\nÇa ne peut pas être pire, de toute façon...", completion = "Euh !... Qu'est-ce que c'est ? La tête d'un ours, on dirait.\n\n&lt;Inconsciemment, il promène son doigt le long de sa cicatrice.&gt;\n\nEh bien ! C'est une prise intéressante que vous avez là. Ne serait-ce pas ce fameux ours ?... \n\n&lt;Il s'écarte puis commence à trembler de façon visible.&gt; \n\nOh emportez ça, emportez-le ! Sortez immédiatement cette chose horrible !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[272] = {title = "L'épreuve du lion de mer", objective = "Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.\n\nReformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire ceci.\n\nApporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", description = "Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L'autre moitié emprunte à l'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.\n\nAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Starblaze.", progress = "Avez-vous assemblé le pendentif pour que je puisse le vérifier, <nom> ? Si vous avez besoin d'aide pour trouver les morceaux, essayez d'interroger la population locale. Non seulement cela vous mènera à ce que vous cherchez mais cela vous donnera de surcroît un prétexte pour explorer ces magnifiques contrées sacrées.", completion = "Vous avez réussi l'épreuve du lion de mer, &lt;nom&gt;, félicitations.\n\nChacune des tâches pour acquérir le pendentif montre que l'agilité et l'endurance doivent agir en harmonie lorsque l'on se trouve sous l'eau. L'une ne peut pas exister sans l'autre, et les deux ne peuvent être sans votre détermination à comprendre les différents aspects du lion de mer.\n\nRappelez-vous bien ces leçons, et comptez sur elles une fois que vous aurez obtenu votre forme aquatique.", rewards = "Vous recevrez :\n\n"},
[273] = {title = "Approvisionnement du site de fouilles", objective = "Aller voir Huldar.", description = "Cependant, il n'est pas trop tard, votre aide est la bienvenue pour prêter main-forte à Huldar. Il ne peut pas être très loin : aussi forts qu'ils soient, Miran et Saean ne peuvent pas se déplacer très vite avec les barils dont ils sont chargés.\n\nIls ont pris la route habituelle pour aller au site, celle qui suit la courbe du lac au sud de la ville.\n\nÇa ne devrait pas poser de problème de les rattraper à moins qu'ils ne soient déjà arrivés.", progress = nil, completion = "Hum ! Il faudra davantage qu'une embuscade des Sombrefer pour empêcher la livraison !\n\nMais Saean... Je n'aurais jamais soupçonné qu'il soit l’un de leurs sympathisants. Il travaille avec nous depuis presque un an maintenant... J'ai peut-être laissé passer des signes.\n\nBon ! Je verrai ça plus tard.", rewards = "Vous recevrez :\n\n"},
[274] = {title = "Une sombre menace se dessine", objective = "Sur ordre d'Ashlan Stonesmirk, retourner voir l'Ingénieur en chef Hinderweir pour l'informer de la nouvelle découverte.", description = "Ce n'est pas un explosif ordinaire. Regardez ces petits cristaux et sentez cette odeur particulière ! C'est de la poudre d'hydroglycérine. Cette substance est sans danger quand elle n'est pas humidifiée ; autrement, elle pourrait faire sauter tout Ironforge en une fois.\n\nLa réaction en chaîne peut être enrayée en mêlant quatre composants : du venin de rôdeuse, du cristal Mo'Grosh pilé, une larme de crocilisque et ce colloïde de désamorçage. Allez prévenir Hinderweir au plus vite !", progress = "Qu'avez-vous rapporté de chez Ashlan ?", completion = "Un colloïde de désamorçage ? Pour de l'hydroglycérine ? Oh bon sang !", rewards = "Vous recevrez :\n\n"},
[275] = {title = "Fièvre sur le pays", objective = "Tuer 12 Rampants des tourbières, puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns.", description = "Je ne sais pas pourquoi, mais il y a une prolifération maligne dans les Paluns. Les Rampants des tourbières se manifestent. Ils sont malades et répandent leur fièvre partout. Pour circonscrire l’épidémie, ils doivent être dispersés et renvoyés dans les marécages.\n\nLes Rampants des tourbières divaguent dans les voies navigables des Paluns.", progress = "Les Paluns pleurent toujours, et les Rampants des tourbières continuent de sévir. Revenez me voir lorsque vous aurez accompli votre tâche.", completion = "Vous avez pacifié cette terre par vos efforts, et par cette action vous méritez une faveur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe de gardien des tourbièresCotte d'anneaux de la forêtPhytolame\n\nVous recevrez également :\n\n"},
[276] = {title = "Piétinements de pattes", objective = "Tuer 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns.", description = "Les gnolls Poils-moussus ont vécu paisiblement dans les Paluns pendant longtemps, mais aujourd’hui leur nombre augmente. Les buissons et les fleurs du marais ne leur suffisent plus, et pour alimenter leurs feux, leurs haches crasseuses coupent trop de bois.\n\nL'équilibre naturel n'est plus respecté. Pour la survie des Paluns, le nombre de gnolls doit être réduit.\n\nTuez 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus. Chassez-les au sud, près des nains de la Porte d'Algaz. Lorsque vous aurez terminé, revenez me voir.", progress = "Votre tâche n'est pas terminée, jeune <classe>.", completion = "En réduisant le nombre des gnolls, vous avez assaini les Paluns. Bien que par le passé, j'ai perdu foi en votre peuple, &lt;nom&gt;, il se peut que je la retrouve.", rewards = "Vous recevrez :\n\n"},
[277] = {title = "Feu interdit", objective = "Rapporter à Rethiel, le Gouverneur vert, 9 Silex bruts.", description = "Les Poils-moussus coupent les arbres des Paluns et les brûlent pour se chauffer. Je ne le supporte plus ! \n\nAllez leur prendre leurs silex bruts, les outils qu'ils utilisent pour faire du feu. A l'exception des simples gnolls et des bâtards, tous les Poils-moussus portent des silex.", progress = "Avez-vous les outils à faire du feu des gnolls ?", completion = "Merci. Je briserai ces silex et je les jetterai dans la mer, pour qu'ils ne puissent jamais plus être utilisés pour enflammer du bois vert.", rewards = "Vous recevrez :\n\nMorilles spongieuses"},
[278] = {title = "Une sombre menace se dessine", objective = "Collecter du Venin de rôdeuse, un Cristal Mo'grosh et une Larme de crocilisque pour l'Ingénieur en chef Hinderweir.", description = "Commencez à collecter les matériaux de désamorçage, <nom>. Le venin de rôdeuse peut être collecté sur les araignées de Loch Modan. Vous trouverez les larmes de crocilisque dans le Loch également. Mais le cristal Mo'Grosh sera plus difficile à obtenir. Les ogres dans le nord-est en exploitent dans leurs mines, mais c’est un minerai très rare.\n\nNous devons être prêts à enrayer l’attaque des Sombrefer ! Revenez quand vous aurez collecté les ingrédients requis.", progress = "Avez-vous trouvé les composants nécessaires ? Le temps presse !", completion = "Juste à temps, &lt;nom&gt; !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[279] = {title = "Griffes des profondeurs", objective = "Tuer 12 murlocs Branchies-bleues.\n\nTuer Enfourneur et prendre sa tête.\n\nL'apporter à Karl Boran au port de Menethil.", description = "Les murlocs sortent des eaux profondes et construisent leurs villages sur le littoral. Ils harcèlent nos pêcheurs et nos marchands, et il faut les arrêter.\n\nL'un de ces murlocs, Enfourneur, tend des embuscades aux marchands le long de la route, avec d'autres Branchies-bleues, et va ensuite se réfugier dans les taudis voisins. Nos marchands sont en danger et nous sommes prêts à payer pour les protéger.\n\nEnfourneur rôde le long du fleuve au nord d'ici. Trouvez-le, éliminez sa famille et apportez-moi sa tête.", progress = "Nos marchands ne seront pas en sûreté tant que nous ne serons pas débarrassés d'Enfourneur et de ces murlocs.", completion = "Ah ! Bon travail, &lt;nom&gt; !\n\nAcceptez ceci en paiement pour avoir honoré votre contrat avec la marine marchande.", rewards = "Vous recevrez :\n\n"},
[280] = {title = "Une sombre menace se dessine", objective = "Sur ordre de l'Ingénieur en chef Hinderweir, nager jusqu'à la base du barrage pour localiser le tonnelet de poudre et y verser la mixture de désamorçage pour empêcher une explosion.", description = "Tout à l'heure, j'ai découvert quelques insurgés Sombrefer qui nageaient vers le barrage avec un tonnelet. Aucun Montagnard n'était en mesure de les arrêter ! J'ai bien peur qu'ils n'aient placé de l'hydroglycérine à la base du barrage et ça pourrait exploser à tout moment ! Laissez-moi préparer une mixture de désamorçage. Allons-y.\n\nMaintenant, j'ai besoin de vous pour prendre ce produit et le mélanger au contenu du tonnelet avant que ce ne soit trop tard ! Vite !", progress = "Le couvercle du tonnelet se soulève lentement.", completion = "L’intérieur du tonnelet pétille légèrement au moment où vous versez la Mixture de désamorçage.", rewards = "Vous recevrez :\n\n"},
[281] = {title = "Récupération de marchandises", objective = "Rechercher les caisses et les barils dans les camps murlocs le long de la côte.", description = "Il y a peu de temps, un navire marchand, le \"Princesse aveugle\" a été attaqué par les murlocs. Tout ce qui n’intéressait pas les créatures a été jeté par-dessus bord, à commencer par une statuette de très grande valeur de Terenas Menethil. Nous voulons retrouver cette statuette.\n\nRecherchez des caisses, des barils et autres éléments de la cargaison perdue le long de la côte ou dans les taudis des murlocs. Retrouvez la Statuette de Menethil et rendez-la-moi.", progress = nil, completion = "Cette caisse est couverte de traces de griffes et porte la marque de dégâts causés par l'eau. Une fois forcée, elle se révèle bourrée de paille humide et pourrie, comme si elle avait contenu un objet de valeur. Vous fouillez la paille...\n\n... et vous trouvez une brassée des bouteilles rouges.", rewards = "Vous recevrez :\n\nPotion de soins"},
[282] = {title = "Les observations de Senir", objective = "Aller voir le Montagnard Thalos.", description = "Je projetais d'envoyer mon apprenti apporter mon rapport à mon frère Senir, mais je préférerais qu'il soit placé entre des mains plus... fiables. Enfin, si vous êtes d'accord, bien sûr !\n\nHum... Vous devrez prendre le tunnel pour arriver à Kharanos.\n\nAllez voir le Montagnard Thalos avant de traverser le tunnel. Il est complètement infesté de troggs maintenant.\n\nRetournez vers Anvilmar, puis continuez en prenant à l'est vers le tunnel, Thalos n'est pas loin.", progress = "Salut ! Attention, <nom>, le tunnel pour Dun Morogh n'est pas sûr, il est infesté de troggs !\n\nSi vous n'avez aucune affaire pressante à Dun Morogh, il serait plus prudent de rester à Anvilmar jusqu'à ce que le tunnel soit nettoyé.", completion = "Eh bien, si Whitebeard vous envoie à Dun Morogh pour une affaire urgente, je ne peux pas vous empêcher d'y aller, n'est-ce pas ?\n\nAu moins, laissez-moi vous donner quelques conseils et quelques indications.", rewards = "Vous recevrez :\n\n"},
[283] = {title = "Une sombre menace se dessine", objective = "La Mixture de désamorçage semble avoir fonctionné. Retourner voir l'Ingénieur en chef Hinderweir pour lui annoncer la bonne nouvelle.", description = "Le tonnelet pétille légèrement.", progress = nil, completion = "Merci, sincèrement, &lt;nom&gt; ! Vous avez sauvé le Barrage de Formepierre ! Sans votre aide, les terroristes Sombrefer se seraient sûrement emparés de ce point stratégique. Vous êtes la fierté du royaume et de l'Alliance, brave &lt;classe&gt;.\n\nLe Barrage est de nouveau en sécurité... du moins pour l'instant.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de bûcheron naineAiguillon\n\nVous recevrez également :\n\n"},
[284] = {title = "La recherche continue", objective = "Rechercher la Statuette de Menethil.", description = "Vous avez fouillé avec soin les taudis murlocs dans ce secteur et vous n'avez trouvé aucune trace de la Statuette de Menethil.\n\nIl y a peut-être davantage d'indices dans les deux taudis qui se trouvent tout près de vous au nord et au nord-est.", progress = nil, completion = "Ce baril est en grande partie intact. En forçant un peu... \n\nUne odeur de fromage vous pique le nez. Il est un peu humide, mais toujours savoureux !", rewards = "Vous recevrez :\n\nCaprice des nains"},
[285] = {title = "À la recherche d'autres taudis", objective = "Continuer à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil.", description = "L'inspection minutieuse de ces quelques taudis murlocs n'a rien donné.\n\nMais le prochain indice sera le bon.\n\nL'un des taudis qui se situent au nord doit cacher la Statuette de Menethil !", progress = nil, completion = "Ce baril est à moitié enterré dans l'herbe et la boue…", rewards = "Vous recevrez :\n\n"},
[286] = {title = "Rapporter la statuette", objective = "Apporter la Statuette de Menethil à Karl Boran.", description = "Une fois le baril sorti de la boue et ouvert, on y trouve une figurine argentée empaquetée avec soin dans la paille. Elle représente un jeune paladin aux cheveux longs, qui brandit un marteau.\n\nCe doit être la Statuette de Menethil ! Vous devez maintenant l’apporter à Karl Boran au Port de Menethil.", progress = "Avez-vous la statuette ?", completion = "Le capitaine du \"Princesse aveugle\" sera soulagé de savoir que sa précieuse cargaison a été récupérée. Vous avez bien mérité ceci en paiement pour les services rendus.\n\nHeureusement qu'il y a encore des gens sûrs dans votre genre, surtout par les temps qui courent.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâtonnet glacialBottes des marins\n\nVous recevrez également :\n\n"},
[287] = {title = "Le repaire des Frostmane", objective = "Explorer le repaire des Frostmane et tuer 5 Chasseurs de tête Frostmane pour Senir Whitebeard à Kharanos.", description = "Je suis sur mon rapport et j'ai besoin de votre aide, <nom>. Je viens juste de trouver où se cachent les trolls, mais ils sont si nombreux que j'ai peur d'y aller.\n\nVoici ce que j'attends de vous... Allez à la grotte, entrez, tuez quelques trolls et revenez ici.\n\nPrenez la route au nord de Kharanos, puis quand vous arriverez au pont, longez la rivière gelée par l'ouest jusqu'au Lac glacial. Vous trouverez le village de Brassetout sur la rive ouest. Leur repaire est au sud-ouest du village.", progress = nil, completion = "Ah, &lt;nom&gt; ! Je ne pensais pas que vous auriez du mal à trouver l'endroit, mes instructions étaient claires, voyez-vous...\n\nLaissez-moi juste terminer mon rapport.\n\n \n\nLà ! Bien ! Ha ha ! Maintenant c'est certainement plus amusant... Je suppose, &lt;nom&gt;, que ça ne vous ennuie pas de m'accorder une dernière faveur ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe d’hiver chaudeTarge en pierre\n\nVous recevrez également :\n\n"},
[288] = {title = "La IIIe flotte", objective = "Acheter une Cruche d'hydromel pour le Premier Officier Fitzsimmons.", description = "J'étais autrefois le Premier Officier du « Maîtresse de l'onde », l'un des bateaux de la IIIe flotte de Kul Tiras. La Flotte perdue. Perdue parce qu'à son dernier voyage, elle a été attaquée par des dragons rouges. Des dragons conduits par des orcs !\n\nNous n'avions aucune chance contre le feu des dragons... Notre flotte a été brûlée et envoyée par le fond. Je suis le seul survivant de ces malheureux navires...\n\n... Oh ça cogne dans ma tête ! Il me faudrait un coup à boire pour supporter cette gueule de bois et continuer mon histoire.", progress = "Oh ! J'ai tellement soif ! Vous n'achèteriez pas quelque chose à boire pour un pauvre malheureux fou ?", completion = "Ah ! Ça revigore et ça délie la langue. Merci, collègue !", rewards = "Vous recevrez :\n\n"},
[289] = {title = "L'équipage maudit", objective = "Tuer 13 Marins maudits, 5 Soldats de marine maudits et le Premier Officier Snellig. Rapporter la Tabatière de Snellig au Premier Officier Fitzsimmons au port de Menethil.", description = "<Revigoré, Fitzsimmons continue son histoire...> \n\nJe suis le seul survivant de l'infortunée IIIe flotte de Kul Tiras, détruite au large de la côte, vers le nord. Mais bien que je sois le seul membre d’équipage qui respire toujours, je ne suis pas le seul qui marche encore ! Car sur l'un de nos bateaux a été caché un trésor épouvantable, dont le pouvoir énorme maintient prisonnières les âmes de mes frères d'armes dans les épaves pourries de nos bateaux.\n\nMais si vous parveniez à libérer quelques-uns de mes frères, peut-être pourriez-vous briser la malédiction.", progress = "Dans mes cauchemars, j’entends parfois les gémissements de damnés de mes frères d'armes ! Par pitié, libérez-les de leurs liens et calmez leurs cris !", completion = "Merci, &lt;nom&gt;. Et vous avez aussi toute la gratitude de mes frères maudits.", rewards = "Vous recevrez :\n\n"},
[290] = {title = "Levée de la malédiction", objective = "Obtenir du capitaine Halyndor la Clé du coffre-fort de \"l'Intrépide\".\n\nUtiliser la clé pour ouvrir le Coffre verrouillé de l'Intrépide.", description = "Pour rompre la malédiction et libérer mes frères d'armes, la... chose... qui se trouve sur mon bateau doit être récupérée et nettoyée ! Je ne sais pas ce que c'est, mais je sais qu'elle est en lieu sûr dans le coffre-fort du bateau, dont seul le capitaine Halyndor avait la clé.\n\nMon vieux capitaine rôde toujours dans mes rêves. Je sais qu'il erre sur \"l'Intrépide\", mon bateau perdu. Obtenez de lui sa clé et utilisez-la pour ouvrir le coffre de \"l'Intrépide\".\n\nEnsuite, quand vous aurez cet objet maudit, apportez-le au prêtre Glorin Steelbrow en ville.", progress = "Ce coffre est bien fermé.", completion = "La clé est rouillée, mais elle s'adapte bien à la serrure.", rewards = "Vous recevrez :\n\n"},
[291] = {title = "Les rapports", objective = "Livrer le rapport de Senir au Sénateur Barin Redstone à Ironforge.", description = "Excellent ! Apportez mon rapport au Sénateur Barin Redstone. C'est un type plutôt aigri, alors ne vous laissez pas impressionner. Il est à Ironforge, dans la salle où se tient la cour du roi Magni.\n\nVous ne connaissez pas la route pour Ironforge ? Prenez la route au nord de Kharanos, traversez le pont, suivez ensuite la route de l'est – il y a de grandes bannières le long de la route – jusqu'en haut de la montagne.\n\nCela dit, si vous pouviez éviter de raconter que vous m'avez aidé... Je ne veux pas qu'ils pensent que je ne bosse pas assez dur ici, vous comprenez ?", progress = "Hum... On dirait que mes gardes deviennent moins stricts avec les pétitionnaires. Bien, que voulez-vous ? Faites vite.", completion = "&lt;Il parcourt rapidement le rapport.&gt;\n\nPar ordre du ROI ! Est-ce que Magni a complètement perdu la tête ? Et ce maudit Whitebeard... Qu'il s'occupe de ce qui le regarde, non ? Le Sénat n'aura pas le plaisir d'en entendre parler, pas même un mot.\n\nQuoi, vous êtes toujours là ? Partez, avant que je n'appelle les gardes !", rewards = "Vous recevrez :\n\n"},
[292] = {title = "L'Oeil de Paleth", objective = "Apporter l'Oeil maudit de Paleth à Glorin Steelbrow.", description = "En ouvrant le coffre, on trouve une sphère noircie, qui irradie une lumière à faire frémir. C'est le trésor dont Fitzsimmons a parlé : un Oeil maudit de Paleth. \n\nApportez l'Oeil maudit de Paleth au prêtre Glorin Steelbrow, un nain qui se trouve au port de Menethil. Demandez-lui comment lever la malédiction de l'Oeil.", progress = "C'est cet ivrogne de Fitzsimmons qui vous envoie ? Eh bien, vous pouvez lui dire que je n'ai pas de bière supplémentaire. Il devra aller mendier chez quelqu'un d'autre !", completion = "Un Oeil de Paleth ? Etonnant ! Hum... Il y a quelque chose qui ne va pas avec celui-ci. Vous l'avez trouvé sur une de ces épaves ? Cela explique tout ! Mais... Je ne savais pas qu'ils avaient un Oeil de cette sorte dans la IIIe flotte...\n\nPas étonnant que Fitzsimmons ait été si effrayé. Un Oeil maudit de Paleth ne donne pas envie de rire.", rewards = "Vous recevrez :\n\n"},
[293] = {title = "Purifier l'Oeil", objective = "Apporter l'Oeil maudit de Paleth à l'archevêque Benedictus, à la cathédrale de la Lumière de la ville de Stormwind.", description = "Je ne peux pas lever la malédiction de l'Oeil de Paleth. Ces Yeux ont été fabriqués par des prêtres humains, vous devez donc aller à Stormwind pour trouver quelqu'un qui pourra vous aider. Allez voir l'archevêque Benedictus, le maître de la cathédrale de la Lumière de Stormwind. Il vous aidera.\n\nJe l'espère pour vous.", progress = "Qu'est-ce que c'est que cet orbe ? On dirait qu'il est… souillé.", completion = "Un Oeil de Paleth. Mais celui-ci a vu beaucoup de souffrances... Il a dû être témoin d'une terrible tragédie.\n\nLaissez-moi le purifier, car les Yeux ont été créés pour étinceler et leurs pouvoirs peuvent devenir dangereux s'ils sont souillés comme celui-ci.", rewards = "Vous recevrez :\n\nOeil de Paleth"},
[294] = {title = "La vengeance d'Ormer", objective = "Sur ordre d'Ormer Ironbraid à l'Excavation de Whelgar, tuer 10 Hurleurs tachetés et 10 Raptors tachetés.", description = "La situation est grave, c'est certain. Les raptors ont été attirés par les ossements. Ces sales bêtes ont tué mes compagnons et nous ont coincés ici, Merrin, le pauvre Prospecteur et moi.\n\nAidez-nous à nettoyer les Paluns de ces raptors, <nom>. Il y a des raptors tachetés et des Hurleurs tachetés à l'ouest. Tuez-en 10 de chaque, si vous le pouvez.\n\nCe sera un bon début à la vengeance que je leur réserve.", progress = "Tuez 10 Raptors tachetés et 10 Hurleurs tachetés, <nom>. Mes équipiers n'ont pas mérité un tel sort. Il est temps d'égaliser le score.", completion = "Tuer est une sale affaire, mais vous avez bien fait votre travail, &lt;nom&gt;. Si je n'avais pas été obligé de rester auprès du Prospecteur et de Merrin, j'aurais été à vos côtés pour faire couler le sang.", rewards = "Vous recevrez :\n\n"},
[295] = {title = "La vengeance d'Ormer", objective = "Tuer 10 Faucheurs tachetés et 10 Tranchegueules tachetés pour Ormer Ironbraid, puis aller le voir à l'excavation de Whelgar.", description = "Il est vraiment temps de faire payer à ces raptors leur soif sanguinaire. Un peu plus bas, il y a d’innombrables Faucheurs tachetés et Tranchegueules tachetés. Tuez 10 Faucheurs et 10 Tranchegueules !", progress = nil, completion = "Vous avez fait du bon boulot en éliminant ces raptors, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[296] = {title = "La vengeance d'Ormer", objective = "Sur ordre d'Ormer Ironbraid, de l'Excavation de Whelgar, tuer Grondecroc et revenir avec l'une de ses serres une fois la tâche accomplie.", description = "Lorsque vous étiez là-bas, j'ai remarqué qu'un de ces monstres se tenait à l'écart des autres. Il était plus grand et plus menaçant. Je parie que c'est lui qui a incité les autres à venir ici interrompre les fouilles.\n\nJ'ai une dernière chose à vous demander, <nom>. Faites en sorte que Grondecroc réponde de ses crimes à la justice. Et compte tenu de la gravité de ses crimes, la justice dans ce cas, c'est la mort ! Apportez-moi une de ses serres pour preuve de sa mort.", progress = "Est-ce que Grondecroc est mort ? Avez-vous vengé la mémoire de ceux qui sont tombés ?", completion = "Merci, &lt;nom&gt;. Vos efforts ne seront pas oubliés. Beaucoup de nains innocents sont morts à cet endroit, en faisant simplement leur travail. Ces raptors diaboliques devraient réfléchir à deux fois avant d'attaquer à nouveau les sujets du roi Magni.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCarnassierArmure de la plaie des raptorsBâtonnet d'excavation\n\nVous recevrez également :\n\nRecette : Omelette au goût étrange"},
[297] = {title = "Réunir les idoles", objective = "Apporter 8 Idoles de pierre sculptée à Magmar Fellhew.", description = "Récemment, juste avant que les troggs ne débarquent sur le site, nous avons découvert un grand nombre d'étranges idoles taillées. Mais nous n'avons pas eu le temps de les étudier, car les troggs nous ont chassés des ruines juste après ! Et ces idoles ont un curieux effet sur les troggs : elles les rendent fous furieux !\n\nRapportez-moi 8 de ces idoles. Je veux les étudier et il ne faut pas qu'elles restent aux mains des troggs ! Vous pouvez trouver les idoles sur les troggs qui infestent le site.", progress = "Avez-vous ces idoles ? Nous devons les étudier et faire part de nos découvertes à Ironforge !", completion = "Vous les avez ! Bien joué, &lt;nom&gt; !\n\nEt vous n'avez pas l'air d'avoir trop peiné, même avec ces troggs fous furieux. Je vais garder un œil sur vous… Vous êtes plein de promesses.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton de flammes nainDécoupeur de troggHache de Thelsamar\n\nVous recevrez également :\n\n"},
[298] = {title = "Compte rendu d'avancement des fouilles", objective = "Apporter le Compte rendu d'avancement d'Ironband à Jern Hornhelm à Thelsamar.", description = "Je dois envoyer un compte rendu d'avancement à Thelsamar et une nouvelle demande pour avoir plus d'explosif ! Voici le rapport. Portez-le à Jern Hornhelm. C'est notre contact local à Thelsamar.\n\nCe n'est pas une tâche difficile, mais ça doit être fait.", progress = "Oh ! Un compte rendu d'avancement du site ? Très bien !", completion = "Bah ! Ironband a des problèmes avec les troggs. Je me demande s'il veut son explosif pour faciliter ses fouilles ou pour l'aider contre les troggs...\n\nBon, d'une façon ou d'une autre, ce sera de la poudre bien utilisée !\n\nMais ce qui est étrange, c'est que je lui ai envoyé de l'explosif en grande quantité il y a quelques semaines. Je me demande où il est passé...", rewards = "Vous recevrez :\n\n"},
[299] = {title = "Découverte du passé", objective = "À la demande du prospecteur Whelgar, parcourir l'Excavation à la recherche des 4 fragments de tablette : Ados, Modr, Golm et Neru.", description = "Avant l'invasion, j'ai découvert une tablette appelée la Pierre de Goaz. Elle s'est brisée en quatre morceaux. Elle parle d'un \"plan divin\" et d'une \"prophétie damnée\".\n\nJe crains que nous n'ayons pas beaucoup de temps. Je suis trop vieux pour aller affronter ces bêtes. Mais vous êtes solide.\n\nExplorez le site de fouilles et cherchez les 4 fragments : Ados, Modr, Golm et Neru. Cherchez dans les artefacts anciens, ou bien là où le sol est meuble. Apportez-les, que je puisse résoudre le mystère !", progress = "Avez-vous déjà retrouvé les quatre fragments, <nom> ? Ados, Modr, Golm et Neru...", completion = "Ah ! La Pierre de Goaz est reconstituée ! Excellent travail, &lt;nom&gt;. Excellent travail, vraiment ! Maintenant je peux continuer la délicate traduction de ces récits des Titans. Je peux déjà discerner quelques nouveaux mots ! Hum... Il est dit : \"Dieux très anciens... enchaînés sous la Terre.\" C'est le début d'une épopée.", rewards = "Vous recevrez :\n\nMantelet de Gamn en soie"},
[301] = {title = "Rapport à Ironforge", objective = "Porter le Compte rendu d'avancement d'Ironband au Prospecteur Stormpike.", description = "Nous aurons besoin d'une autorisation pour fournir à Ironband plus d'explosif. Vous devrez apporter son rapport au quartier général de la Ligue des Explorateurs à Ironforge.\n\nVoici ce rapport. Donnez-le au Prospecteur Stormpike et mettez-vous à l'abri juste après ! Stormpike est impétueux et il ne sera pas ravi d'apprendre qu'Ironband ne progresse que lentement sur le site.\n\nVous trouverez Stormpike à l'Assemblée des Explorateurs.", progress = "Nous, les Stormpike, nous n'aimons pas être dérangés pour des questions insignifiantes, <classe>. J'espère que les nouvelles que vous apportez sont dignes de mon attention.", completion = "Maudit soit cet Ironband ! Je lui ai envoyé une cargaison d'explosif il y a quelques semaines, mais il n'en fait aucune mention dans son rapport.\n\nAlors… Où cet explosif est-il passé ?", rewards = "Vous recevrez :\n\n"},
[302] = {title = "De l'explosif pour Ironband", objective = "Parler à Jern Hornhelm à Thelsamar.", description = "Si Ironband a encore besoin d'explosif, par Magni, alors il l'aura ! J'ai envoyé un messager à Thelsamar avec une autorisation pour Jern Hornhelm. Il préparera la poudre et du matériel à remettre à Ironband.\n\nEncore une chose : je veux que vous assuriez personnellement la livraison pour que l'explosif arrive à bon port. Le dernier chargement n'y est pas arrivé, alors gardez l'esprit vif et les yeux ouverts.", progress = nil, completion = "Quoi ? Stormpike veut que vous assuriez personnellement la livraison d'Ironband ?\n\nJe... suppose que c'est bien. Le seul problème, c'est que j'ai déjà envoyé Huldar avec les porteurs, Miran et Saean. Vous les avez manqués de peu, ils viennent juste de partir.", rewards = "Vous recevrez :\n\n"},
[303] = {title = "La guerre contre les Sombrefer", objective = "Sur ordre de Motley Garmason à Dun Modr, tuer 15 nains Sombrefer : 5 Tunneliers Sombrefer, 5 Saboteurs Sombrefer et 5 Démolisseurs Sombrefer.", description = "La guerre fait rage ici autant qu'à l'étranger. Tandis que nos valeureux nains donnent leur vie loin de chez eux au nom de l'Alliance, nos propres terres sont la proie des nains Sombrefer. Ils ont eu raison du viaduc de Thandol. Dun Modr est tombée peu après.\n\nNous avons besoin de vous pour reprendre des forces et repousser le front. Si vous pouvez tuer 15 nains Sombrefer, 5 Tunneliers, 5 Saboteurs et 5 Démolisseurs, nos réservistes pourront être là à temps pour conduire l'offensive.\n\nFaites vite !", progress = nil, completion = "Vous avez suivi les ordres, bien, &lt;classe&gt; ! Vous avez fait preuve de vaillance et de loyauté envers le roi Magni, et à ce titre vous avez toute ma considération ! Avec la pression que vous avez maintenue sur le camp Sombrefer, nous avons maintenant une chance de les chasser pour toujours de notre pays... Si seulement cette damnée réserve voulait bien arriver...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[304] = {title = "Une tâche sinistre", objective = "Tuer Balgaras le Crasseux et rapporter son oreille à Longbraid le Macabre à Dun Modr.", description = "Beaucoup de mes soldats sont morts à la bataille de Dun Modr. Mon propre frère a péri lors de la destruction du pont de l'ouest du viaduc de Thandol. Oui, les nains Sombrefer sont une race diabolique. D'après ce que Roggo a réussi à apprendre, le chef de la bande de nervis qui se trouve dans les Paluns est un démoniste du nom de Balgaras le Crasseux. Et c'est un véritable lâche. Il envoie ses soldats en première ligne, mais il reste invisible et il évite le danger.\n\nSi vous parvenez à trouver cette racaille, à l'exécuter et à m'apporter son oreille, je vous récompenserai, <classe>.", progress = "Est-ce que vous avez déjà pu localiser Balgaras le Crasseux, <classe> ? Cela fait quelque temps qu'il nous échappe.", completion = "Balgaras le Crasseux est enfin éliminé. Même si sa mort ne ramènera pas à la vie les nombreux nains innocents qu'il a tués, elle permettra à ceux qui ont survécu de retrouver la paix intérieure. Balgaras mort, ce qui reste des Sombrefer devrait être facile à gérer. Maintenant, nous devons les anéantir avant qu'un nouveau chef n’émerge.\n\nVous avez réussi, &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier du lion d'orAnneau tranquille\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[305] = {title = "À la recherche de l'équipe de fouilles", objective = "À la demande de Tarrel Rockweaver, aller jusqu'à l'Excavation et contacter Merrin Rockweaver.", description = "Oh bon sang ! Vous devez être l'éclaireur que Longbraid a promis d'envoyer ! Vous ne pouvez pas imaginer mon inquiétude.\n\nMa femme, Merrin, m'envoie des lettres toutes les semaines depuis le mois dernier. Elle fait partie de l'équipe de fouilles de Whelgar. Mais il s'est écoulé presque deux semaines depuis sa dernière lettre. Il y a sûrement quelque chose qui ne va pas !\n\nLongbraid a dit qu'il enverrait un éclaireur aux nouvelles si nous n'avions pas rapidement du nouveau. Je suppose que l'éclaireur, c'est vous, <nom>. Allez voir Merrin à l'Excavation, à l'est !", progress = nil, completion = "Oh, grâce au Ciel vous êtes là !", rewards = "Vous recevrez :\n\n"},
[306] = {title = "À la recherche de l'équipe de fouilles", objective = "Retourner voir Tarrel Rockweaver avec la lettre de Merrin.", description = "C'était horrible ! Nous avions découvert quelques artefacts rares et nous commencions à nous intéresser à ces grands ossements.\n\nAvant d'avoir compris ce qui se passait, ces raptors marbrés ont déboulé sur le site. Il y a eu beaucoup de morts.\n\nC'est Ormer – et avec quel courage ! – qui nous a sauvés, le Prospecteur et moi. Il nous a couverts pendant que nous courions nous mettre à l'abri. Maintenant nous sommes pris au piège. Et nous avons perdu le fruit de notre dur labeur.\n\nTenez, apportez cette lettre à mon cher Tarrel pour lui expliquer la situation.", progress = "Avez-vous trouvé Merrin ? Vous a-t-elle donné une lettre ?", completion = "Quelles terribles nouvelles ! Mais au moins trois d'entre eux ont survécu. Quand cette tuerie finira-t-elle ? J'aspire au jour où les sujets du roi Magni pourront vivre dans la sérénité.", rewards = "Vous recevrez :\n\n"},
[307] = {title = "Bas les pattes !", objective = "Aller à la Mine du Ru d'argent pour prendre 4 lots d'Equipement de mineur.\n\nRetourner voir le Montagnard Stormpike.", description = "La mine du Ru d'argent à l'est est épuisée depuis longtemps. Elle a été convertie en dépôt de stockage par la Ligue des Mineurs, mais aujourd’hui les kobolds s'y sont installés, et ils mettent leurs pattes sales sur nos bons vieux outils !\n\nNous chasserons bientôt cette vermine de là, mais avant d'envoyer des guerriers qui feront forcément un peu de casse, la Ligue veut que quelqu'un aille chercher son équipement. Ce ne sera pas facile, vous pourriez avoir besoin de l'aide d'alliés.\n\nL'équipement de mineur est stocké dans les caisses de la Ligue des Mineurs un peu partout dans la mine. Bonne chance !", progress = "Avez-vous l'équipement de mineur, <nom> ?", completion = "Avez-vous vu beaucoup de kobolds là-bas ? Je n'en peux plus d’attendre l'ordre de les déloger de la mine. La pensée de leurs pattes crasseuses touchant nos outils me donne des maux d'estomac !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCotte d'anneaux Coeur-de-ferRobe du gardienTarge doublée de fer\n\nVous recevrez également :\n\n"},
[308] = {title = "Distraire Jarven", objective = "Hum ! Toute cette boisson stockée là, et dire que j'ai l'interdiction formelle d'y toucher ! Si seulement je pouvais goûter un peu de notre Thunder Ale... Ça me donnerait un esprit plus vif, sans mentir !", description = nil, progress = "Hum ! Toute cette boisson stockée là, et dire que j'ai l'interdiction formelle d'y toucher ! Si seulement je pouvais goûter un peu de notre Thunder Ale... Ça me donnerait un esprit plus vif, sans mentir !", completion = "Pour moi ? Vous êtes le symbole de l'héroïsme, &lt;nom&gt; !", rewards = nil},
[309] = {title = "Protection de la cargaison", objective = "S'assurer que Miran et la cargaison parviennent au Site de fouilles puis en informer le Prospecteur Ironband.", description = "Prêt à y aller, <nom> ?\n\nD'abord, nous devons trouver de l'explosif pour Ironband. Je ne pourrai pas le porter seul, d'autant que ça peut être dangereux – et qui sait ce que les Sombrefer me réservent ?\n\nJe me sentirais mieux si vous m'accompagniez.", progress = "Où est mon explosif, <nom> ? J'en ai désespérément besoin.", completion = "Oh, que la Lumière soit remerciée ! Voilà enfin l'explosif. Mais vous apportez aussi des nouvelles inquiétantes. Imaginer que les Sombrefer ont des sympathisants capables de leur procurer ce type de matériel pour mener leurs plans à bien...\n\nC'est à méditer, mais une autre fois. Je dois faire bon usage de cet explosif.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de contremaîtreEcrase-boue\n\nVous recevrez également :\n\n"},
[310] = {title = "Bières rivales", objective = "Aller au sous-sol de la distillerie Thunderbrew à Kharanos et remplacer un Tonneau de Thunder Ale par un Tonneau de Barleybrew Scalder.", description = "Je dois admettre que ces Thunderbrew font quelques bonnes boissons. Mais il faut qu’ils comprennent qu'ils ne sont pas les seuls brasseurs ! Vous pouvez peut-être m'aider à faire passer le message... \n\nTenez, prenez ce tonneau de Barleybrew Scalder. Glissez-vous dans le sous-sol de la distillerie Thunderbrew, à Kharanos, et échangez-le avec un de leurs tonneaux de Thunder Ale. Nous verrons bien si leurs clients préfèrent leur recette ou la mienne !\n\nBien sûr, si les tonneaux sont gardés, il faudra peut-être distraire le garde...", progress = "La date inscrite sur ce tonneau montre qu'il sera bientôt mis en perce.", completion = "Vous placez rapidement le tonneau de Barleybrew Scalder au milieu des tonneaux des Thunderbrew.", rewards = "Vous recevrez :\n\n"},
[311] = {title = "Retour chez Marleth", objective = "Apporter le Tonneau de Thunder Ale à Marleth Barleybrew au Village de Brassetout.", description = "Après avoir mis un tonneau de chez Marleth Scalder dans la cave de la Distillerie Thunderbrew, vous emportez un Tonneau de Thunder Ale pour prouver que vous l'avez vraiment fait...", progress = "Avez-vous fait l'échange ?", completion = "Pas mal, &lt;nom&gt; ! Avez-vous eu du mal à passer malgré leur garde ?\n\nPeu importe : mille mercis ! Et si vous avez un jour besoin d'hommes vaillants et énergiques, n'oubliez pas les Barleybrew !", rewards = "Vous recevrez :\n\n"},
[312] = {title = "La réserve volée de Tundra MacGrann", objective = "Récupérer la caisse de viande séchée de Tundra MacGrann dans la Caverne du Vieux Barbeglace.", description = "J'avais un mois de réserves de viande séchée et salée que j'avais stockées pour la saison froide. C'était hors d'atteinte des ours, dans une caisse fermée ! Mais pendant que j'étais à la chasse au daim, cette bête, le Vieux Barbeglace, est venue et repartie avec ma caisse de viande. Il ne sera pas capable de défoncer le thorium de la caisse. Mais je vais mourir de faim si je ne peux pas récupérer mes réserves de viande.\n\nVous semblez plus discret que moi. Peut-être parviendrez-vous à récupérer ma caisse ? Je n'arriverai jamais à entrer et sortir assez vite de cette caverne avec ma jambe qui se traîne.", progress = "Est-ce que vous avez réussi à reprendre mes réserves de viande, <nom> ?", completion = "Quelle âme noble, &lt;nom&gt; ! Grâce à votre courage, je ne mourrai pas de faim lorsque souffleront les rafales de vent de la saison froide.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards en fer forgéMitaines en laine\n\nVous recevrez également :\n\n"},
[313] = {title = "L'antre Gris", objective = "Réunir 8 Peaux de Wendigo et les apporter au Pilote Stonegear.", description = "La conduite d'une machine de siège n'est pas à la portée de n'importe qui. Il faut une poigne de fer et des nerfs d'acier... Par chance, j'ai les deux ! Et vous ? De quel bois êtes-vous fait ? Vous voulez le prouver ?\n\nBon... Je cherche comment rendre mon engin, le \"Moissonne-trolls\", un peu plus confortable. Et si vous alliez me chercher quelques peaux de Wendigo dans l'Antre Gris, à l'ouest de Kharanos ? On pourrait en tapisser le pont intérieur de ma machine !", progress = "Salut, <nom>. Déjà de retour de l'Antre Gris ? Ces Wendigos peuvent être féroces.", completion = "Ah oui ! Ces peaux vont faire l'affaire ! Vous avez montré une grande fermeté de caractère, &lt;classe&gt;. Je parie que nous entendrons parler de vous.", rewards = "Vous recevrez :\n\n"},
[314] = {title = "Protection du troupeau", objective = "Sur demande de Rudra Amberstill, tuer Vagash et rapporter un de ses crocs à la ferme des Amberstill.", description = "Nous avons entendu des cris au milieu de la nuit. Et ce matin, il manquait deux béliers dans le troupeau. C'est cette bête poltronne connue sous le nom de Vagash qui s'en est prise à notre gagne-pain. Vu que la grande partie de l'armée du roi Magni est loin d'ici, en train de se battre avec l'Alliance, il n'y a personne pour tenir Vagash à distance.\n\nVous avez peut-être assez de courage pour poursuivre la bête et la tuer. Apportez-moi un de ses crocs et je vous récompenserai. Vagash se cache juste au-dessus du ranch, mais soyez <prudent/prudente>, il est très dangereux.", progress = "Vagash terrorise toujours le troupeau ! Je vous en prie, aidez-nous en tuant cette misérable bête.", completion = "Bien joué ! Veron sera si heureux d'entendre ces bonnes nouvelles. Tuer Vagash n'était pas facile. J'imagine qu'un jour, vous vous battrez aux côtés des hommes du roi Magni sur le front de l'Alliance.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon de RancherTunique en cuir soupleMarteau des Frigères\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[315] = {title = "La bière parfaite", objective = "Apporter 6 Brins de chatoyante à Rejold Barleybrew au village de Brassetout.", description = "Je cherche à faire la bière parfaite. Je sais que je peux le faire : le brassage, j'ai ça dans le sang. Je dois juste trouver la bonne recette...\n\nLes trolls Frostmane cultivent une plante, la chatoyante, en haut des collines à l'est. Ils l'utilisent dans les rituels de leur tribu. Nous les nains, nous ne lui avons pas trouvé d'usages, mais elle a un goût unique... Et je veux essayer !\n\nApportez-moi de la chatoyante qu'utilisent les Prophètes Frostmane, ou piquez-en dans les paniers à chatoyante des trolls.", progress = "Avez-vous ma chatoyante ? J'ai un fût de bière prête à brasser et je veux rajouter cette herbe dans mon mélange.", completion = "Génial ! Je ne vais pas attendre pour utiliser cet ingrédient dans quelques-unes de mes recettes. Il y en a une en particulier qui va être grandiose…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape en peau de chèvreBrassards de tisse-lierre\n\nVous recevrez également :\n\n"},
[317] = {title = "Ravitailler le Crache-vapeur", objective = "Réunir 4 morceaux de Viande de sanglier et 2 Fourrures d'ours épaisses et les livrer au pilote Bellowfiz au dépôt de Steelgrill.", description = "Je me prépare à entamer une mission pour la brigade des Sapeurs. C'est une longue mission et j'ai besoin de ravitailler le Crache-vapeur avec l'équivalent d'un mois de provisions. Alors pendant que Steelgrill travaille sur mon réservoir, pouvez-vous aller chasser pour moi ?\n\nJ'ai besoin de fourrure pour nos lits et de viande pour nous nourrir. Vous pouvez rapporter de la viande de sanglier et de la fourrure d'ours... Vous trouverez l'un et l'autre dans les terrains enneigés au sud de l'Antre Gris.", progress = "Les préparatifs avancent. Comment se passe votre chasse ?", completion = "Par la barbe de Magni, quelle chasse ! Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[318] = {title = "L’Evershine", objective = "Demander un tonneau d'Evershine à Rejold Barleybrew au village de Brassetout.", description = "Rejold Barleybrew fait des expériences de brassage. Certaines ont bon goût, d'autres sont mauvaises et certaines... Eh bien, certaines mettraient par terre les plus vaillants des nains !\n\nCe brasseur habite à Brassetout, à l'ouest de Kharanos, et j'ai besoin de l'une de ses boissons : l'Evershine. Ça me tiendra au chaud quand je serai sur les routes glacées.\n\nEt... ce liquide béni brûle si bien que je peux le jeter dans la chaudière du Crache-vapeur pour avoir un peu plus de puissance ! Cette petite tactique m'a servi plus d'une fois.", progress = nil, completion = "Bellowfiz a besoin d'un peu de mon Evershine ? Hum… D'accord.", rewards = "Vous recevrez :\n\n"},
[319] = {title = "Une faveur pour un tonneau d’Evershine", objective = "Tuer 6 Ours Griffeglace, 8 Anciens sangliers des rochers et 8 Léopards des neiges, puis retourner voir Rejold Barleybrew à Brassetout.", description = "J'ai un tonneau d'Evershine sous la main, mais... Pouvez-vous me faire une faveur ? Mon village aurait besoin d'un coup de main pour se débarrasser des animaux sauvages qui errent dans les neiges voisines. Parfois ils rôdent tout près.\n\nNous n'avons pas peur de ces oursons, de ces chats et de ces cochons – aucun nain digne de ce nom n'en aurait peur – mais si vous pouviez vous occuper de ces bestioles, nous aurions plus de temps pour travailler.", progress = "Avez-vous réglé leur compte à ces animaux sauvages ?", completion = "Merci, &lt;nom&gt;. Ça va être plus agréable d’exercer nos métiers sans entendre ces grondements et ces reniflements à la porte du village.", rewards = "Vous recevrez :\n\n"},
[320] = {title = "Retour vers Bellowfiz", objective = "Donner le Tonneau d'Evershine au Pilote Bellowfiz au Dépôt de Steelgrill.", description = "Voici votre tonneau d'Evershine, <nom>. Et merci encore pour la partie de chasse.", progress = "Avez-vous obtenu l'Evershine ?", completion = "Oui, ça fera parfaitement l'affaire. Je pense que je vais tout de suite l’ouvrir pour goûter…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache tranchanteBâton courtCouteau des campeurs\n\nVous recevrez également :\n\n"},
[321] = {title = "Le fer de sancteforge", objective = "Fouiller l'épave de l'Albatros, dans les Paluns.", description = "Les épaves qui se trouvent près du rivage sont les débris de la Flotte perdue de Kul Tiras, brûlée et coulée par les dragons rouges pendant la dernière Grande guerre.\n\nLa flotte venait de Lordaeron, mais il y avait aussi un destroyer elfique, \"l'Albatros\". Il transportait une cargaison de fer de sancteforge et avait rejoint la IIIe flotte pour profiter de sa protection. Ironie du sort, il a été coulé par les mêmes dragons...\n\nMais assez raconté d'histoires. L'épave de \"l'Albatros\" est au sud du port de Menethil. Si vous trouvez du fer de sancteforge là-bas, apportez-le moi.", progress = nil, completion = "Ce coffre est détrempé et sa serrure cassée. Il y a de nombreuses marques de griffes à l'intérieur et à l'extérieur... Comme si les murlocs l'avaient fouillé pour voler son précieux contenu.\n\nMais tout au fond du coffre, il reste un dernier lingot de sancteforge. Malheureusement, il en faudrait beaucoup plus pour forger une arme.", rewards = "Vous recevrez :\n\nLingot de sancteforge"},
[322] = {title = "Béni soit ce bras", objective = "Apporter la Caisse de lingots de sancteforge à Grimand Elmore, à Stormwind.", description = "Il y a un nain, fabricant d'armes dans le quartier des nains de Stormwind, qui sait travailler le fer de sancteforge. Il s'appelle Grimand Elmore.\n\nJ'ai emballé le métal que vous avez trouvé dans une caisse. Apportez-le à Grimand et racontez-lui votre histoire. Je suis sûr qu'il est prêt à aider quiconque mène une quête comme la vôtre et il vous fabriquera une arme – une arme qui donnera du fil à retordre à Morbent Fel lui-même !", progress = "Que puis-je faire pour vous, <classe> ?", completion = "C'est un véritable conte que vous me racontez là. Et du fer de sancteforge ! Cela fait des années que je n'ai pas travaillé un tel métal. Ce sera un honneur de le travailler. Et vous reviendrez me voir plus tard pour me raconter comment s'est déroulé votre affrontement avec le Nécromancien.\n\nMais n'anticipons pas. D'abord, fabriquons votre arme contre Morbent Fel...", rewards = "Vous recevrez :\n\n"},
[323] = {title = "Prouver votre valeur", objective = "Tuer 15 Ecumeurs squelettes, 3 Soigneurs squelettes et 3 Gardiens squelettes puis retourner voir Sven.", description = "Morbent Fel est un nécromancien, allié des Cavaliers noirs. Je pourrais vous envoyer combattre Morbent Fel, mais je dois d’abord tester votre force avant que vous ne luttiez contre un tel adversaire.\n\nVous avez déjà prouvé votre bravoure, mais si vous voulez vraiment affronter le nécromancien, vous devez d’abord montrer votre valeur contre ses sbires.", progress = nil, completion = "On ne peut pas mettre en doute votre habileté au combat, &lt;nom&gt;. Et grâce à votre volonté, nous pouvons en finir avec Morbent Fel !", rewards = "Vous recevrez :\n\n"},
[324] = {title = "Les lingots perdus", objective = "Collecter 5 Lingots de sancteforge puis retourner voir Glorin Steelbrow, dans les Paluns.", description = "Puisque vous n'avez trouvé qu'un seul lingot de sancteforge dans le coffre, il paraît évident que les murlocs ont volé le reste. Pourchassez les écumeurs murlocs près de l'épave de \"l'Albatros\" pour retrouver le fer de sancteforge volé.", progress = "Avez-vous trouvé le fer de sancteforge dont vous aviez besoin ?", completion = "Oh ! Vous en avez trouvé ! Et si nous le fondions pour en faire quelque chose d'utile, maintenant ?", rewards = "Vous recevrez :\n\n"},
[325] = {title = "En armes et prêt", objective = "Apporter le Fléau de Morbent à Sven, dans le bois de la Pénombre.", description = "Voici l'arme pour combattre le démon dont vous avez parlé. Vous pouvez y aller, <nom>. Je vous souhaite bonne chance et j'attends avec impatience d'entendre raconter vos exploits !", progress = "Salutations, <nom>. Vous n'êtes pas parti bien longtemps, mais je vois dans vos yeux une flamme qui n'y était pas avant.", completion = "Cela sera à l'épreuve du démon Morbent Fel ! Bien joué !\n\nVous êtes prêt. C'est la fin de Morbent Fel.", rewards = "Vous recevrez :\n\n"},
[326] = {title = "<INUTILISÉ>", objective = "x", description = "xLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[327] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[328] = {title = "La clé cachée", objective = "Utiliser la Petite Clé en cuivre pour ouvrir le Coffre-fort de Herod la Paperasse.", description = "Bien qu'il ne soit jamais fait mention du soldat Thorsen dans ces rapports, une petite clé en cuivre était cachée dans un des registres d'Herod.\n\nEt en poussant plus loin l'étude de ces notes, on trouve au milieu de divers papiers des références à un \"coffre-fort sécurisé\". Il est quelque part dans la Réserve, l'ensemble de cavernes qui se trouve derrière la Base de Kurzen.\n\nSi nous retrouvons ce coffre-fort et que la petite clé peut l'ouvrir, nous résoudrons peut-être le mystère de Thorsen.", progress = "Le coffre-fort est coulé dans le bronze, il est très lourd et très solide.", completion = "En ouvrant le coffre-fort, on voit clairement que c'est là que Herod garde ses pièces de monnaie et ses objets de valeur.", rewards = "Vous recevrez :\n\nSceptre fracassant"},
[329] = {title = "L'espion découvert !", objective = "Apporter la Note maculée de boue au lieutenant Doren, au camp rebelle.", description = "Parmi les objets précieux contenus dans le coffre-fort, il y a une note griffonnée et couverte de boue. Bien qu'elle soit à peine lisible, on dirait un itinéraire pour le soldat Thorsen. Il y a des détails sur ses itinéraires de patrouille, les gens auxquels il parle, ce qu'il fait de son temps avec les rebelles. Elle n'est signée que d'une lettre : M.\n\nMais celui ou celle qui a écrit cette note doit être proche de Thorsen. Celui ou celle qui a écrit cette note est le traître du camp rebelle.", progress = "Avez-vous découvert qui connaissait le secret de Thorsen ? Y a-t-il un traître parmi nous ?", completion = "Merci, &lt;nom&gt;. Cette note est l'indice qui nous manquait pour coincer le traître !", rewards = "Vous recevrez :\n\n"},
[330] = {title = "Composition des patrouilles", objective = "Parler au caporal Sethman.", description = "La note que vous m'avez donnée est signée d'un \" M \"... Je ne sais pas ce que ça signifie.\n\nMais... La note dit aussi que cette personne a partagé les tours de patrouille de Thorsen la semaine dernière. Le traître doit être l'un de ceux qui ont patrouillé en même temps que Thorsen !\n\nAllez voir le caporal Sethman. C'est lui qui gère la composition des patrouilles, il vous dira qui était avec Thorsen la semaine dernière.", progress = nil, completion = "Oh oui ! Je peux vérifier ça pour vous. Voyons... La semaine dernière, c'était...\n\n... C'était le soldat Merle qui était prévu avec Thorsen. Ils ont eu les mêmes heures de patrouille toute la semaine dernière.", rewards = "Vous recevrez :\n\n"},
[331] = {title = "Rapport au Lieutenant Doren", objective = "Parler au Lieutenant Doren.", description = "Le Lieutenant Doren a-t-il demandé que vous retourniez le voir avec cette information concernant les patrouilles ?", progress = nil, completion = "Je suis peiné de découvrir que c'est Merle le traître. C'est un soldat courageux et je le croyais loyal. Mais c'est un grand soulagement de l'avoir découvert : avec un espion comme lui parmi nous, nous n'aurions pas fait long feu contre le colonel Kurzen.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSandales du marcheur de la jungleEspauliers en métal glacial\n\nVous recevrez également :\n\n"},
[332] = {title = "Publicité pour la cave à vins Gallina", objective = "Aller à la Cave à vins des Gallina et apporter à Suzetta Gallina le Bon pour une bouteille de vin gratuite.", description = "Si vous parlez à qui que ce soit de vin, vous apprendrez que nous, les Gallina, nous vendons le meilleur vin de Stormwind. Et nous ne sommes pas loin, dans le Quartier commerçant, le long des superbes canaux de la ville.\n\nTenez, prenez ce bon d’échange. Apportez-le à ma sœur Suzetta dans notre magasin, et elle vous offrira une bouteille de bienvenue de notre célèbre pinot noir. Vous ne le regretterez pas !", progress = "Bonjour et bienvenue ! Avez-vous déjà goûté l'un de nos excellents vins ?", completion = "Oh ! Alors vous avez vu Renato ? Vous êtes ici chez vous. Une bouteille de notre pinot noir spécial. Vous n'en trouverez pas d'autre de cette qualité dans tout Azeroth !", rewards = "Vous recevrez :\n\nBouteille de Dalaran noir"},
[333] = {title = "Harlan a besoin d'être approvisionné", objective = "Aller à la Boutique de tailleur du canal et donner à Rema Schneider la Demande de tissu, pour Harlan Bagley.", description = "Nous avons fait pas mal d'affaires dernièrement. On dirait que tout le monde achète des armures et des vêtements résistants. Comme s'ils s'attendaient à une saison froide et dure... \n\nMais ce sont là des soucis pour plus tard. Mon souci aujourd'hui, c'est que je suis à court de vêtements tricotés à vendre. J'ai besoin d'un autre lot de mon fournisseur.\n\nSi vous pouviez en prendre livraison auprès de Rema Schneider, chez le tailleur et équipementier du canal, je vous en serais très reconnaissant.", progress = "Vous apportez un mot de M. Bagley ?", completion = "On dit ici que les affaires d'Harlan prospèrent. Ce sont de bonnes nouvelles, mais je me demande pourquoi les gens ont besoin de toutes ces armures. Je n'ai entendu parler d'aucune guerre ouverte... Les nobles nous cachent-ils quelque chose ?\n\nEh bien, merci d'avoir apporté ce dont nous avions besoin. Voici votre paiement, je veillerai à ce que Harlan soit approvisionné.", rewards = "Vous recevrez :\n\n"},
[334] = {title = "Un paquet pour Thurman", objective = "Aller chez les Couturiers Larson, dans le quartier des mages de Stormwind, pour donner à Thurman Schneider son Matériel de couture.", description = "Mon fils Thurman est apprenti chez les Couturiers Larson, dans le Quartier des mages. Il était pressé aujourd'hui et il a oublié ses ciseaux et ses aiguilles. Je sais qu'un grand <classe> comme vous a des tâches autrement plus importantes à accomplir, mais sans ses outils, Thurman ne peut pas faire son travail d'apprenti !\n\nS'il vous plaît, <nom>, pouvez-vous rapporter à mon fils son matériel de couture ? Les Couturiers Larson tiennent l'un des deux magasins de prêt-à-porter du Quartier des mages, c'est le plus éloigné, près de la Tour du mage.", progress = "Vous êtes ici pour acheter des vêtements ?", completion = "Oh zut ! Je croyais qu'en oubliant mon matériel, je serais dispensé de travailler. Maintenant je vais devoir aider les Larson avec leur sacrée couture... \n\nBon. Je devine que pour ce qui est de s'amuser, je repasserai plus tard.", rewards = "Vous recevrez :\n\n"},
[335] = {title = "Un noble brassage", objective = "Sur ordre de Zardeth de la Griffe noire, rapporter une Larme de Tilloa de Darkshire et une Racine de Musquash des Paluns.", description = "Le seigneur Wishock sème le trouble à la Maison des Nobles. Il sait pour notre petit \"établissement\" et fait pression pour qu'une enquête soit ouverte. J’ai un plan pour « occuper » Wishock, mais je vais avoir besoin de votre aide.\n\nIl y a une fleur qui pousse dans le jardin de Stalvan aux environs de Darkshire. On appelle cette petite fleur blanche la larme de Tilloa. J'aurai aussi besoin d'une racine de musquash, qu'on ne trouve qu'en bas des chutes du barrage de Formepierre dans les Paluns.", progress = "Wishock aura bientôt assez de soutien pour nous causer à tous beaucoup d'ennuis. Avez-vous réussi à trouver la larme de Tilloa et la racine de Musquash ?", completion = "Excellent ! Ce sont vraiment des échantillons parfaits !", rewards = "Vous recevrez :\n\n"},
[336] = {title = "Un noble brassage", objective = "Apporter la Bière brune de la Griffe noire au seigneur Wishock dans la Chambre du requérant.", description = "Le seigneur Wishock est comme tous les hommes, il a ses faiblesses. Il se trouve que la sienne est un penchant prononcé pour la bouteille. Quelle sidérante hypocrisie. Ce pauvre imbécile passe ses journées à essayer de faire fermer notre petite « taverne », et ses nuits à l’étage à rallonger une ardoise qu’il ne payera jamais. Et bien nous allons voir comment Wishock apprécie la cuvée spéciale que je lui ai préparée : la bière brune de la Griffe noire. C’est du brutal, <nom>.\n\nApportez-lui et voyez comment il réagit. Probable que ce vieil idiot soit en train de traîner autour de la Chambre du Requérant.", progress = "Vous ne voyez pas que je suis occupé ? Je dois être entendu ! Je suis essentiel à l'avenir de ce royaume !\n\nOh !… Qu'est-ce que vous avez là ? On dirait une boisson rafraîchissante…", completion = "Merci de m'avoir apporté cette bonne bière, serviteur. Voici une pièce pour vous. Maintenant hors de ma vue et laissez-moi savourer mon verre !", rewards = "Vous recevrez :\n\n"},
[337] = {title = "Un vieux livre d'histoire", objective = "Rendre le livre « l'Histoire de Stormwind » à la Bibliothèque de Stormwind.", description = "Bien que la couverture de ce livre soit éraflée et couverte de boue, on arrive à lire le titre \"L'Histoire de Stormwind\" sur la tranche. En l’ouvrant, on voit clairement tamponné sur la première page le cachet de la Bibliothèque de Stormwind.\n\nOn dirait que quelqu'un a emprunté ce livre et ne l'a jamais rendu...", progress = "Oh ! Quel est ce vieux livre que vous avez là ? Puis-je le voir ?", completion = "O merveille ! Ce livre avait déserté nos étagères depuis la reconstruction de Stormwind, il y a des années. Il devra être restauré bien sûr, il est en mauvais état, mais je serais honoré de l'avoir dans notre collection.\n\nMille mercis à vous ! Je vous prie d'accepter ceci pour vous remercier d'avoir rapporté ce livre !", rewards = "Vous recevrez :\n\n"},
[338] = {title = "« Les vertes collines de Strangleronce »", objective = "Rassembler les pages manquantes du manuscrit des « Vertes collines de Strangleronce ». Une fois les quatre chapitres complétés, les rendre à Barnil.", description = "Maître Nesingwary va être tellement furieux s'il découvre ça !\n\nIl m'a fait confiance pour relire le manuscrit de son roman « Les vertes collines de Strangleronce ». Tout allait bien, mais une grande rafale de vent a soufflé sur le camp et a dispersé toutes les pages !\n\nJ'ai pu en ramasser la plupart, mais certaines sont toujours perdues dans la jungle. Retrouvez les pages qui manquent pour compléter les quatre chapitres.\n\nJe vous aiderai à les remettre dans l'ordre. Rendez-moi les chapitres une fois que vous les aurez tous les quatre.", progress = "Avez-vous déjà complété les chapitres, <nom> ?", completion = "Vous m'avez certainement évité un tas d'ennuis, &lt;nom&gt; ! Je ne pourrai jamais vous remercier assez. Maintenant, nous ne devrions pas tarder à voir le roman de Maître Nesingwary dans les bibliothèques du monde entier !", rewards = "Vous recevrez :\n\nBottes de la jungleRenfort d'armure épaisPotion de soins excellente"},
[339] = {title = "Chapitre I", objective = "Rapporter les pages 1, 4, 6 et 8 des Vertes collines de Strangleronce de Nesingwary à Barnil Stonepot pour achever le Chapitre I.", description = "Le Chapitre I était vraiment fascinant ! Maître Nesingwary plante le décor de l'histoire et décrit ses compagnons de chasse, moi y compris !\n\nMais c'est un détail. Laissez-moi voir s’il manque des pages. On dirait que les pages 1, 4, 6 et 8 sont toujours quelque part dans la jungle !", progress = "Je suppose que vous n'avez pas pu récupérer les pages 1, 4, 6 et 8 ? Ce sont les seules pages qui nous manquent pour terminer le Chapitre I.", completion = "Enfin ! Le Chapitre I est complet !", rewards = "Vous recevrez :\n\nLes vertes collines de Strangleronce - Chapitre I"},
[340] = {title = "Chapitre II", objective = "Rapporter les pages 10, 11, 14 et 16 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre II.", description = "Le Chapitre II regorgeait de passionnants récits de chasse au tigre et à la panthère. Je me donnerais des coups pour avoir laissé les pages s'envoler !\n\nJ’ai récupéré toutes les pages à l'exception des pages 10, 11, 14 et 16.", progress = "Nous avons encore besoin des pages 10, 11, 14 et 16 pour compléter le Chapitre II, <nom>.", completion = "Le Chapitre II est enfin complet ! Bien joué !", rewards = "Vous recevrez :\n\nLes vertes collines de Strangleronce - Chapitre II"},
[341] = {title = "Chapitre III", objective = "Rapporter les pages 18, 20, 21 et 24 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre III.", description = "Le chapitre III est mon préféré. Il parle de la première fois où le sire Erlgadin et dame Rouack ont tué avec un fusil des nains. Et la fin du chapitre, quel suspense !\n\nJe vois qu'il nous manque encore les pages 18, 20, 21 et 24 pour clore le chapitre. Ces pages sont quelque part par là...", progress = "Toujours rien pour les pages 18, 20, 21 ou 24 ? Ce sont les seules qui nous manquent pour compléter le Chapitre III.", completion = "Oui ! Bon travail, &lt;nom&gt;. À présent, le Chapitre III est à nouveau complet !", rewards = "Vous recevrez :\n\nLes vertes collines de Strangleronce - Chapitre III"},
[342] = {title = "Chapitre IV", objective = "Rapporter les pages 25, 26 et 27 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre IV.", description = "Ah Le Chapitre IV : le grand final ! Et quel final !\n\nIl ne nous manque plus que trois pages, les 25, 26 et 27, pour compléter le Chapitre IV.", progress = "Il ne nous manque plus que trois pages pour finir le Chapitre IV, <nom>. Avez-vous déjà les pages 25, 26 et 27 ?", completion = "Magnifique ! Le Chapitre IV est maintenant prêt !", rewards = "Vous recevrez :\n\nLes vertes collines de Strangleronce - Chapitre IV"},
[343] = {title = "En parlant de fermeté", objective = "Allez à la Bibliothèque royale dans le Donjon de Stormwind pour parler à Milton Sheaf. Il trouvera le livre sur la métallurgie dont Frère Kristoff a besoin pour son discours.", description = "Je fais un discours sur la fermeté de l'Esprit et je voudrais citer des passages d'un livre sur la métallurgie : \"Les Tensions du fer\". Un exemplaire de ce livre doit se trouver à la Bibliothèque royale, dans le Donjon de Stormwind. Pouvez-vous le récupérer pour moi ? Si vous le faites, que la bénédiction de la Lumière soit sur vous !\n\nLa Bibliothèque royale est très grande, mais le responsable, Milton Sheaf, connaît chaque étagère comme sa poche. Parlez-lui, il cherchera le livre pour vous.", progress = nil, completion = "La métallurgie ? Ah oui ! Nous avons beaucoup de livres sur le sujet et nous sommes heureux de pouvoir aider Frère Kristoff à préparer son discours ! Bien... Quel livre ce bon frère recherche-t-il ?", rewards = "Vous recevrez :\n\n"},
[344] = {title = "Frère Paxton", objective = "Parler au frère Paxton, à l'Abbaye du Northshire.", description = "« Les Tensions du fer » ? Oui, je connais ce livre. Excellent ouvrage, écrit par le mineur nain Margulf Blaggon il y a quelques décennies. Il a passé l'essentiel de sa vie au cœur des montagnes de Khaz Modan, à creuser pour trouver du minerai. Chic camarade !\n\nMais où en étais-je ? Ah oui ! « les Tensions du fer » ! J'ai bien peur que le livre ait été envoyé à l'abbaye du Northshire. Le bibliothécaire de l'abbaye, le frère Paxton, voulait faire une copie de l’ouvrage pour sa propre collection.\n\nMais c'était il y a plusieurs mois. Je me demande pourquoi ça lui prend si longtemps...", progress = nil, completion = "M. Sheaf se demande où est son livre ? Eh bien, c'est un peu embarrassant. J'ai le livre, mais je n'ai pas fini ma copie et je ne suis pas encore prêt à rendre l'original !", rewards = "Vous recevrez :\n\n"},
[345] = {title = "Provisions d'encre", objective = "Aller voir le contremaître Oslow de Lakeshire et lui demander du minerai de rethban.", description = "J'avais l'intention de finir ma copie des « Tensions du fer », mais...\n\nEh bien vous voyez, je fabrique ma propre encre pour les livres que je copie. C'est une recette personnelle : elle ne coule pas, ne tache pas et sèche très rapidement, voire trop rapidement ! Mon dernier lot a séché avant la fin de mon travail de copie et je n'ai pas eu la possibilité d'en refaire !\n\nPour en fabriquer davantage, j'ai besoin de minerai de rethban qui vient des Carmines. Le contremaître Oslow de Lakeshire est mon fournisseur habituel.", progress = nil, completion = "Vous avez besoin de quoi ? Vous ne l'avez peut-être pas remarqué, mais nous sommes en train de fortifier les défenses de Lakeshire et de réparer les dégâts causés par les récentes attaques des orcs. Si vous avez besoin de rethban, débrouillez-vous pour vous le procurer !", rewards = "Vous recevrez :\n\n"},
[346] = {title = "Retourner voir Frère Kristoff", objective = "Retourner voir Frère Kristoff sur la Place de la Cathédrale. Lui donner le livre « les Tensions du fer ».", description = "Maintenant que j'ai fini ma copie des « Tensions du fer », je vous rends l'original. Merci pour votre patience et si vous voyez Milton, dites-lui que je suis désolé pour ce long retard.", progress = "Avez-vous trouvé le livre ?", completion = "C'est bien celui-là ! Merci, &lt;nom&gt;. Puisse la Lumière rayonner sur votre corps comme sur votre esprit !", rewards = "Vous recevrez :\n\nBottes d'errance"},
[347] = {title = "Minerai de rethban", objective = "Réunir 5 charges de Minerai de rethban et les apporter à Frère Paxton à la bibliothèque du Northshire.", description = "Le minerai de rethban a été découvert par Bart Rethban. Lorsqu’il est fondu, ce minerai est moins dur que le fer, mais il possède une essence que certains scribes utilisent comme encre. Il peut être trouvé dans les Cavernes de Rethban, plus au nord.\n\nNous en avons normalement en réserve, mais devant nous préparer aux attaques des orcs, nous n'avons pas eu le temps d'en collecter dernièrement. De plus, les gnolls des Carmines occupent maintenant les cavernes de Rethban et leurs manouvriers y exploitent le minerai eux-mêmes.\n\nSi vous voulez en collecter, vous devrez le faire par vos propres moyens.", progress = "Avez-vous le minerai de rethban ?", completion = "Oh, splendide ! Je vais pouvoir utiliser ce minerai pour préparer ma teinture et finir de copier « les Tensions du fer ».\n\nMerci, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[348] = {title = "La fièvre de Strangleronce", objective = "Chercher le Sorcier-docteur Unbagwa pour qu'il invoque Mokk le Sauvage. Apporter le Cœur de Mokk à Fizracket.", description = "Malade... Si... Très m-m-malade...\n\n... attrapé la fièvre de Strangleronce... V-v-virus mortel...\n\nSeul remède... est... est... manger le cœur de M-m-m-m-mokk le Sauvage... Sauvage...\n\n... Le Sorcier-docteur Unbagwa... Lui seul peut me s-s-sau...\n\n... Allez chercher Unbagwa dans la caverne cachée au sud du cap...\n\n... vite... mourant... mourant...", progress = "...Maman ?\n\n... si froid...\n\n... Entre dans le Néant distordu... T-t-t-tiens-moi, maman…", completion = "…sens mes forces revenir… \n\nOù étais-je ? A Baie-du-Butin ? Oh là là ! J'ai fait un rêve des plus étranges…\n\n... Ma faiblesse ne m'a pas complètement quitté....", rewards = "Vous recevrez :\n\nCouverture-médecine"},
[349] = {title = "La fièvre de Strangleronce", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "Sorcier-docteur Unbagwa sait comment être Mokk le Sauvage. Si si !\n\nMoi parler aux esprits pour faire venir lui, moi pouvoir.\n\nMais d'autres bêtes comme gorilles aiment parler aux esprits aussi. Toi protéger Sorcier-docteur Unbagwa et moi le faire venir ici.\n\nSorcier-docteur Unbagwa veut quelque chose d'abord. Toi apporter 10 crocs de gorille et moi commencer parler aux esprits !", completion = "Sorcier-docteur Unbagwa aimer crocs de gorille ! Pour toi, moi parler aux esprits. Faire venir Mokk le Sauvage.\n\nToi protéger Sorcier-docteur Unbagwa des gorilles ou pas Mokk pour toi !", rewards = nil},
[350] = {title = "Le point de vue d'un vieil ami", objective = "Parler à Elling Trias à Stormwind.", description = "Ce Marzon va contacter un Défias et il est lié à Lescovar...\n\nEn ayant tué VanCleef et Thredd, il va être difficile de traîner en justice Lescovar, vu que vos preuves ne valent rien sans leurs témoignages. Sans compter que Lescovar est un noble et qu'il a de nombreux appuis. Il est ainsi au-dessus des lois.\n\nVous avez besoin d'une autre aide. Je répugne à le faire, mais voici quelqu'un que je connais et qui peut nous aider. Vous trouverez Trias dans le Quartier commerçant de la cité.", progress = nil, completion = "Vous plaisantez ? Shaw veut encore que je l'aide ? Quel culot...\n\nLa confrérie Défias ? Eh bien, vous êtes sûrement porteur de nouvelles merveilleuses ? Bientôt vous allez me dire que l'Aile de mort est toujours en vie et en train d'attaquer la cité.\n\nBon, ça va, racontez-moi tout depuis le début. Et surtout n'omettez aucun détail. Je dois tout savoir.", rewards = "Vous recevrez :\n\n"},
[351] = {title = "Trouver OOX-17/TN !", objective = "Apporter la balise de détresse au robot guidé d'Oglethorpe.", description = "Vous avez découvert un étrange objet en forme d'oeuf fait de métal. En jouant avec les petit boutons présents sur le dessus, l'oeuf s'anime, à mesure qu'il s'ouvre, il se transforme en une espèce de bidule robot gnome ! Une voix sort du robot en grésillant.\n\n\"Je suis Oglethorpe Obnoticus, et mon robot guidé a disparu ! Je vous récompenserais si vous le réparez ! Apportez cette balise au robot. Excellent, j'ai programmé les coordonnées du robot pour vous ! Il s'est écrasé près du Gouffre béant à Tanaris !\"", progress = "Vous découvrez l'épave d'une sorte de... robot poulet ? La voix émerge de l'oeuf une nouvelle fois :\n\n\"Oui, excellent travail ! C'est bien mon robot guidé, mes détecteurs m'indiquent qu'il doit être relancé avant de pouvoir revenir à Baie-du-Butin pour y être réparé. Allez-y et placez la balise dans la machine. La balise s'occupera du reste !\"", completion = "Vous placez l'oeuf... la balise de détresse... dans le poulet... le robot guidé.\n\nVous entendez des bourdonnements venant de l'intérieur du robot quand il essaie de se relever. Après l'activation du robot, la voix d'Oglethorpe retentit de nouveau, mais maintenant elle vient de l'intérieur du robot :\n\n\"OOX-17/TN fonctionne finalement, mais il a besoin de grosses réparations ! Il est trop lourd pour vous... mais je pense que j'ai une idée. Voudriez-vous bien le surveiller encore un peu ?\"", rewards = "Vous recevrez :\n\n"},
[353] = {title = "Livraison pour Stormpike", objective = "Livrer le Paquet au montagnard Stormpike au Loch Modan.", description = "Les Stormpike sont un clan nain respecté et connu pour ses goûts raffinés et subtils. Ce n'est donc pas surprenant que Gringer Stormpike, un montagnard d'Ironforge, m'ait demandé de lui fabriquer une arme.\n\nL'arme est terminée, mais Gringer vit loin d'ici, près du Loch Modan. Si vous projetez de voyager vers le nord, pouvez-vous lui livrer ce paquet ?\n\nSon dernier message disait qu'il se trouvait à la Tour de garde nord du Loch Modan.", progress = "Vous venez directement de Stormwind ? J'entends dire que traverser les terres des humains devient risqué, entre les brigands et les orcs. Un endroit parfait pour les guerriers qui veulent prouver leur valeur !", completion = "Ah ! Grimand a enfin terminé ma hache ! Je ne vais pas attendre pour l'essayer contre quelques troggs ou quelques kobolds !\n\nMille mercis, &lt;nom&gt;. Vous avez fait un long voyage pour me la livrer. Voici quelques pièces pour vous remercier de vos efforts.", rewards = "Vous recevrez :\n\n"},
[354] = {title = "Morts dans la Famille", objective = "Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill.", description = "Les Agamand étaient la famille la plus prospère des Clairières de Tirisfal. Je travaillais dans leurs moulins... avant la Peste.\n\nQuand le Fléau est apparu, les Agamand ont fortifié leur maison et convaincu leurs employés de rester et de les aider à se défendre. Nous étions des imbéciles, mais au moins nous étions des imbéciles loyaux.\n\nLes Agamand, à cause de leur orgueil, nous ont condamnés. Et maintenant le Fléau a fait d'eux ses favoris !\n\nServez ceux qui ont été abandonnés en vainquant les Agamand qui sont tombés du côté de la Peste. Servez-moi en m'apportant leurs restes.", progress = "Vous avez les restes des Agamand ? Est-ce que ces bêtes maudites ont finalement été détruites ?", completion = "La revanche a un goût savoureux, vous ne trouvez pas ? Lorsque vous les avez détruits, avez-vous trouvé le plus petit indice de volonté propre en eux ? Je l'espère. J'espère qu'ils ont connu la peur avant d'être écrasés dans le néant.\n\nC'est un espoir fou, je sais. Mais un espoir qui ne me quitte pas.", rewards = "Vous recevrez :\n\n"},
[355] = {title = "Parler à Sevren", objective = "Parler au magistrat Sevren à Brill.", description = "Vous m'avez ramené les restes des Agamand et satisfait mon désir de vengeance. Mais les Moulins d'Agamand sont une menace pour tous les Réprouvés, pas seulement moi.\n\nJ'ai parlé au Magistrat Sevren de vos exploits contre les Agamand et il désire vous parler.", progress = nil, completion = "Coleman dit du bien de vous, &lt;nom&gt;, il rapporte vos succès aux Moulins d'Agamand.\n\nLes Réprouvés ont encore besoin de vos talents.", rewards = "Vous recevrez :\n\n"},
[356] = {title = "Patrouille d'arrière-garde", objective = "Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds, puis revenez voir Linnea, à son camp.", description = "Les défenseurs de la Barricade protègent Tirisfal des Maleterres et sont en alerte permanente. Mais parfois, le Fléau arrive à s'infiltrer.\n\nNotre succès à la Barricade dépend d'un front uni. Nous ne pouvons nous permettre d'être attaqués par l'arrière ou de voir les lignes d'approvisionnement des défenseurs coupées.\n\nRenforcez la Barricade. Patrouillez à l'est et détruisez toutes forces du Fléau que vous rencontrerez. Portez un effort particulier sur la ferme des Balnir. C'est devenu un havre pour les forces du Fléau qui maraudent dans le secteur.", progress = "Avez-vous rendu compte après votre patrouille ?", completion = "Très bien. Vos efforts aident beaucoup à garder le Fléau à distance. Une recommandation sera envoyée à mon supérieur, l'Exécuteur Zygand.", rewards = "Vous recevrez :\n\n"},
[357] = {title = "Le Nom de la Liche", objective = "Rapporter le livre de sorts de la Liche et le donner à Bethor Iceshard à Undercity.", description = "Une liche réside dans l'île au nord du lac Etincelant. Bien qu'elle soit une Réprouvée sauvage, elle croit que tous les autres morts-vivants sont des esclaves du Fléau et envoie ses serviteurs attaquer quiconque s'approche d'elle.\n\nMais parce que c'est une Réprouvée, la Reine la veut. Et si elle est douée dans les arts de la nécromancie, son savoir serait réellement utile à notre cause.\n\nPour connaître son identité et ses capacités, j'ai besoin d'étudier son livre de sorts. Infiltrez-vous dans son camp, prenez-le livre et ramenez le moi.", progress = "<nom>, avez-vous retrouvé le livre ?", completion = "Très bien, &lt;nom&gt;. Je vais étudier ce livre et déterminer l'identité de cette liche. Vous avez bien servi la Reine.\n\n\n\nEtonnant ! Le livre que vous avez ramené appartient à nul autre que Gunther Arcanus !\n\nGunther était un nécromancien doué durant sa vie, nous étions amis et frères d'armes, avant la Peste. Et si j'en juge d'après son livre de sort, il est devenu encore plus puissant dans la mort.\n\nSes talents seraient une bénédiction pour notre cause.", rewards = "Vous recevrez :\n\n"},
[358] = {title = "Les Profanateurs", objective = "Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides. \n\nRapporter les Ichors d'embaumement au magistrat Sevren à Brill.", description = "Dans le nord, les fosses communes, au sud-ouest de l'antre de Garren ont été construites pour accueillir les morts de Tirisfal lorsque la Peste frappa la première fois. \n\nLes corps qui s'y trouvent ont pu reposer en paix jusqu'ici mais le Fléau a envoyé des gnolls Poil-putride prendre les corps afin de les utiliser pour accroître leurs armées. Cela ne doit pas être !\n\nVotre mission comporte deux parties : tuer les Poils-putrides dans les fosses communes et dans l'Antre de Garren et récupérer sur eux l'ichor d'embaumement qui leur donne vie.", progress = "Votre tâche est-elle accomplie ? Avez-vous détruit ces choses et les avez-vous privé de leur ichor ?", completion = "Du travail d'expert, &lt;nom&gt;. Le Fléau se trompe s'il pense qu'il pourra utiliser ces corps contre nous et le fluide que vous avez récupéré sur ses esclaves Poils-putrides va être étudié dans nos laboratoires. Il contient peut-être des secrets que nous pourrions utiliser contre eux.\n\nComme je le disais, bien joué. Mais notre lutte continue et le conflit vous offrira bientôt d'autres chances de prouver que vous êtes digne des Réprouvés.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGantelets d'acier glacéBottes en peau de zombie\n\nVous recevrez également :\n\n"},
[359] = {title = "Mission des Réprouvés", objective = "Parler à la Garde noire Linnea.", description = "J'ai besoin d'un rapport récent sur notre base de la Garde noire dans l'est.\n\nJe dois savoir s'il y a encore des incursions des forces du Fléau au-delà de la Barricade et dans Tirisfal. Notre vigilance à la frontière des Maleterres doit être maintenue. Nous ne pouvons pas nous permettre que les forces du Fléau s'établissent ici ! \n\nVoyagez vers le sud en suivant la route, puis vers l'est à l'embranchement jusqu'au poste. Demandez la Garde noire Linnea. Elle a les informations dont j'ai besoin.", progress = nil, completion = "Le magistrat Sevren désire un rapport ? Très bien : les défenseurs de la Barricade contiennent le gros des forces du Fléau, mais il arrive qu'il y ait quelques incursions de temps en temps.\n\nNous avons une activité sporadique de Maraudeurs du Fléau à l'est de cette base, avec une concentration autour de la ferme des Balnir.", rewards = "Vous recevrez :\n\n"},
[360] = {title = "Retourner voir le Magistrat", objective = "Retourner voir le Magistrat Sevren à Brill.", description = "Maintenant, rapportez au Magistrat Sevren les informations que je vous ai données. Il en a besoin le plus vite possible, soyez rapide.\n\nEt si vous voyez des troupes du Fléau sur votre chemin, abattez-les. Nous ne pouvons leur permettre de parcourir nos contrées sans opposition.", progress = nil, completion = "Il est troublant d'apprendre que le Fléau puisse passer au-delà de la Barricade. Le roi-liche et ses servants lancent des assauts incessants.\n\nMais nous n'abandonnerons pas. Il ne passera pas !", rewards = "Vous recevrez :\n\n"},
[361] = {title = "Une lettre perdue", objective = "Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand.", description = "Ceci est une lettre écrite par Thurman, l'aîné des fils de Gregor Agamand. Elle est adressée à Yvette Farthing, bien qu'il semble qu'elle n'ait pas atteint sa destinatrice…", progress = "Oui ?", completion = "Oh… pauvre Thurman ! Je l'ai supplié de quitter les Moulins d'Agamand avec mon père et moi, mais sa loyauté pour sa famille était trop grande ! Je le savais ! Je le savais que ce Brand cherchait sa perte ! Oh, maudits soient la Peste et le Fléau !\n\n&lt;Le visage d'Yvette s'apaise et devient froid...&gt;\n\nMais les regrets sont pour les faibles. Et en tant que Réprouvée, j'ai de nouveaux buts et l'amour n'en fait pas partie. Je vous remercie de m'avoir apporté cette lettre puisque cela m'a permis de savoir ce qu'il était advenu d'un amour passé.\n\nMais cette vie est finie. A jamais.", rewards = "Vous recevrez :\n\n"},
[362] = {title = "Les Moulins Hantés", objective = "Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill.", description = "Devlin Agamand était le plus jeune des deux fils de la famille Agamand. Jamais frères ne furent aussi différents. Thurman était grand et aimable tandis que son plus jeune frère était faible et acerbe.\n\nLorsque les Moulins d'Agamand sont tombés suite à la Peste, je n'ai pas été surpris d'apprendre que Devlin avait rapidement succombé. Son bavardage maladif peut toujours être entendu près de la route qui mène aux Moulins d'Agamand.\n\nJe collectionne les restes des Agamand. Je veux ce pauvre Devlin. Trouvez-le, détruisez-le et rapportez-moi ses os.", progress = "Vous avez trouvé Devlin ?", completion = "Merci. Les os de Devlin feront une belle décoration sur ma cheminée.\n\nMon cœur froid peut trouver un peu de réconfort dans la certitude que les Agamand sont détruits. Ils m'ont trahi moi et ma famille lorsque la Peste arriva. Maintenant, je veux écraser leurs restes sous ma botte !", rewards = "Vous recevrez :\n\n"},
[363] = {title = "Réveil brutal", objective = "Parler au prêtre des ombres Sarvis.", description = "Il était temps de se réveiller. Nous nous apprêtions à vous jeter au feu avec les autres mais il semble que vous ayez réussi.\n\nJe suis Mordo, le fossoyeur de la crypte du Glas. Et vous n'êtes plus l'esclave du roi-liche.\n\nAllez parler au prêtre des ombres Sarvis dans la chapelle en bas de la colline, il vous en dira plus sur ce que vous devez savoir.", progress = nil, completion = "Un autre mort-vivant, hein ? Cela a dû être un choc de se réveiller dans la crypte avec juste le froid et Mordo pour vous accueillir.\n\nJe lis l'égarement sur votre visage. Laissez-moi vous expliquer notre… situation.\n\nNous avons été libérés du contrôle du roi-liche par notre nouveau chef, la dame Sylvanas. La Dame noire mène notre guerre contre ce maudit Fléau et les déchets de cette humanité qui aboient à chacune de nos actions.", rewards = "Vous recevrez :\n\n"},
[364] = {title = "Les Déchus", objective = "Le prêtre des ombres Sarvis veut que vous tuiez 8 Zombies lunatiques et 8 Zombies décharnés.", description = "Nous, les Réprouvés, sommes en guerre contre le roi-liche et les troupes du Fléau : leurs armées de morts-vivants animés par la nécromancie, des bêtes immondes venues du nord et des spectres tourmentés.\n\nLa partie nord du village a été submergée par les Déchus et ils doivent être détruits. Anéantissez-les, n'ayez aucune pitié, même s'ils étaient nos frères et soeurs par le passé. Les Déchus ne sont rien d'autre que les esclaves du roi-liche.", progress = "Vous n'irez pas loin dans cette nouvelle vie si vous n'êtes même pas capable de tuer le plus faible des zombies, <nom>. Ne revenez pas tant que vous n'avez pas au moins une victoire à votre actif.", completion = "Il est regrettable que les forces du Fléau ne puissent être lancées dans la bataille, leur large nombre aurait été utile dans les combats qui nous attendent.\n\nMais ils ne se joindront pas à nous, c'est pourquoi nous n'avons d'autre choix que de les détruire.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants en linCape endommagée\n\nVous recevrez également :\n\n"},
[365] = {title = "Les Champs du Chagrin", objective = "Volez 10 Potirons dans la ferme à l'ouest, juste au nord du Glas, et apportez-les à l'Apothicaire Johaan à Brill.", description = "Ça par exemple ! Vous ressemblez à un épouvantail <classe>. Si vous espérez faire vos preuves au service de la Dame noire, il faudra apprendre les voies des Réprouvés.\n\nÀ l'ouest, vous trouverez une ferme. Les humains infestent cette terre comme la vermine un cadavre. Et pire, la Croisade écarlate patrouille près de leur tour. Donnez-leur une leçon et volez 10 de leurs précieux Potirons.\n\nUne fois que vous les avez, apportez-les à l'Apothicaire Johann à Brill.", progress = "Le garde noir Simmer m'a dit que vous alliez me procurer les ingrédients dont j'ai tant besoin. Avez-vous pu vous procurer 10 potirons, <nom> ?", completion = "Vous avez bien réussi votre épreuve initiatique, jeune &lt;classe&gt;. Vous semblez être une recrue de valeur pour l'armée de la Dame noire.", rewards = "Vous recevrez :\n\n"},
[366] = {title = "Ramener le livre", objective = "Ramener son livre de sorts à Gunther, dans sa retraite sur son île.", description = "Il y a longtemps, Gunther et moi, ainsi que Thule Ravenclaw qui est aujourd'hui Nécromancien du Fléau, étions amis et étudiants au Kirin Tor - une société de mages de Dalaran.\n\nGunther et moi sommes tombés, tués par la Peste, mais je pensais qu'il ne s'était pas relevé ou bien qu'il avait rejoint les rangs du roi-liche. Il est agréable de le savoir libre.\n\nIl doit être des nôtres. J'ai mis un sort dans son livre qui, une fois qu'il le verra, lui montrera que je ne suis pas non plus sous la domination du roi-liche. Une fois qu'il saura cela, j'espère qu'il nous rejoindra.", progress = "Vos maîtres sont des fous pour vous avoir envoyé ici, car je ne serai jamais plus l'esclave du Fléau !", completion = "Mon livre ?!? Alors vous êtes le voleur qui l'a dérobé !\n\nMais… quel est ce nouvel enchantement… Bethor ? Il est à Lordaeron ?\n\nSi il est toujours vivant, alors peut-être qu'il a lui aussi échappé à l'emprise du roi-liche…", rewards = "Vous recevrez :\n\n"},
[367] = {title = "Une Peste nouvelle", objective = "Collecter 5 fioles de Sang de sombredogues pour l'Apothicaire Johaan de la ville de Brill.", description = "Dame Sylvanas a fait appel à la Société royale des apothicaires. La Dame noire croit que notre savoir couplé à cette nouvelle magie nous donnera la clé de la défaite d'Arthas. Elle nous a mis au défi de créer une Peste nouvelle, une Peste plus puissante que celle qui a ravagé Azeroth. Cette nouvelle infection amènera la ruine des forces du Fléau.\n\nMes études montrent que le sang de bêtes en pourrait être la clé. Rapportez-moi 5 fioles de sang de sombredogues, que je puisse tester ma théorie.", progress = "Avez-vous collecté 5 fioles de sang de sombredogues, <nom> ? Le temps s'écoule irrémédiablement !", completion = "Vous avez bien travaillé, &lt;nom&gt; et je vous remercie de vos efforts.", rewards = "Vous recevrez :\n\nPotion de sang de troll faible"},
[368] = {title = "Une Peste nouvelle", objective = "L'Apothicaire Johaan de la ville de Brill a besoin de 5 Ecailles d'Aileron noir prises sur les murlocs des Clairières de Tirisfal.", description = "Pendant que vous collectiez mes échantillons, mes expériences m'ont permis de réaliser que des ingrédients supplémentaires seraient nécessaires pour que cette nouvelle maladie se répande proprement. Empoisonner une victime sans défense est un jeu d'enfant. Infecter un monde entier est un peu plus compliqué.\n\nJ'aurais besoin de 5 écailles prélevées sur les murlocs Ailerons noirs des environs. Vous trouverez ces créatures le long de la côte du nord ou de l'ouest.", progress = "<nom>, avez-vous été capable d'obtenir ces 5 Ecailles de murlocs Ailerons noirs ?", completion = "Les écailles sont parfaites, &lt;nom&gt;. Exactement ce dont j'avais besoin pour cette décoction.", rewards = "Vous recevrez :\n\nSable de léthargie"},
[369] = {title = "Une Peste nouvelle", objective = "L'Apothicaire Johaan de la ville de Brill désire que vous lui rameniez 4 échantillons de Venin de Tisse-nuit vicieuse.", description = "Tandis que votre quête vous occupait, j'ai découvert de vieux textes dans un de mes livres qui indique qu'une ancienne peste a balayé des milliers de victimes innocentes. Il a été compris plus tard que l'agent infectieux de l'épidémie avait été préservé grâce à du venin des araignées Tisse-nuit vicieuses.\n\nRapportez-moi un peu de ce venin pour compléter mes expériences. Je veux voir si le principe conservateur de ce venin agit aussi sur mes décoctions. Les rumeurs disent que les araignées peuvent être trouvées à l'est des clairières de Tirisfal.", progress = "Avez-vous un peu de Venin de Tisse-nuit vicieuse, <nom> ? C'est le seul composant qui me manque pour commencer les essais.", completion = "Ah, ce venin est parfait, &lt;nom&gt;. Tout le reste a déjà été ajouté à ma potion et bouilli. Je suis maintenant prêt à tester ce nouvel agent mortel !", rewards = "Vous recevrez :\n\nEcharpe d'apprenti"},
[370] = {title = "En Guerre avec la Croisade écarlate", objective = "Tuer le capitaine Perrine ainsi que 3 Zélotes écarlates et 3 Missionnaires écarlates.", description = "Les documents stratégiques de l'Exécuteur Arren contiennent tous les détails dont nous avons besoin pour balayer l'infection humaine de ces terres. Selon nos informations, la Croisade écarlate a assigné le capitaine Perrine et une brigade à la tour en ruine au sud-ouest de Brill.\n\nTuez Perrine ainsi que 3 Zélotes et 3 Missionnaires et revenez me rendre compte.", progress = nil, completion = "La mort du capitaine Perrine sera très certainement appréciée par la Dame noire. Vous avez rempli votre mission honorablement, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[371] = {title = "En Guerre avec la Croisade écarlate", objective = "L'Exécuteur Zygand de Brill vous a chargé de liquider le capitaine Vachon et 5 Frères écarlates.", description = "Nous sommes toujours en guerre et la Croisade écarlate croît en puissance. Le rapport que l'Exécuteur Arren m'a envoyé indique que la Croisade lance ses raids depuis la tour en ruines au sud-est de Tirisfal, près de la ferme des Balnir. Elle est sous le commandement du capitaine Vachon.\n\nTuez Vachon et 5 Frères de la Croisade. Cela sera un coup dévastateur pour ces Croisés !", progress = nil, completion = "La mort du capitaine Vachon va ralentir l'avance de la Croisade écarlate. Mais d'autres menaces se profilent à l'horizon.", rewards = "Vous recevrez :\n\n"},
[372] = {title = "En Guerre avec la Croisade écarlate", objective = "Assassiner le capitaine Melrach et ses deux gardes du corps pour l'Exécuteur Zygand de la ville de Brill.", description = "La Croisade écarlate lance des raids depuis la tour en ruine au nord-est de Tirisfal, au-delà du Repos de Faol. Selon nos informations, elle est menée par le capitaine Melrache qui a la réputation d'être un officier impitoyable.\n\nJe vous charge cette mission, dangereuse et spéciale. Abattez Melrache et ses deux gardes du corps au nom de la Dame noire.", progress = nil, completion = "Excellent, &lt;classe&gt;. Avec des combattants impitoyables tels que vous se battant pour les Réprouvés, notre race est un pas plus proche de la défaite définitive d'Arthas. J'ai un bon pressentiment vous concernant, camarade.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCouteau de cérémonieHachette découpante\n\nVous recevrez également :\n\n"},
[373] = {title = "La lettre non envoyée", objective = "Livrer la lettre pour l'Architecte de la Cité à Baros Alexston à Stormwind.", description = "En fouillant le corps d'Edwin VanCleef, vous trouvez parmi d'autres objets une lettre non envoyée. Elle est adressée à Baros Alexston, architecte de la cité de Stormwind, Hôtel de ville, place de la cathédrale.\n\nElle a l'air récemment écrite et scellée.", progress = "Oui ? Que puis-je pour vous ?", completion = "Edwin VanCleef, vous dites ? Pourquoi pas une lettre de ma grand-mère morte… Alors vous l'avez tué ? Excusez-moi, mais je suis un peu surpris. C'était un guerrier sans égal quand il était jeune. Voyons pourquoi il a besoin de m'écrire après toutes ces années.\n\n&lt;Baros ouvre la lettre.&gt;\n\nEdwin... Je vois que tu n'as pas changé, toujours aussi idéaliste et romantique. Il ne fait pas attention aux gens qu'il blesse, &lt;nom&gt;. La vengeance l'a consumé. Mais je ne crois pas qu'il faille le blâmer pour cela.", rewards = "Vous recevrez :\n\n"},
[374] = {title = "Preuves de la mort", objective = "Apporter 10 Anneaux de la Croisade écarlate au Garde noir Burgess à Brill.", description = "L'Exécuteur Zygand m'a dit que vous exterminiez des membres de la Croisade écarlate. Les Clairières de Tirisfal en sont remplies.\n\nVarimathras, lieutenant de la Dame noire, a pris personnellement en charge la mission d'exterminer toute la vermine humaine d'Azeroth. Ici, dans les Clairières de Tirisfal, nous faisons face à un genre particulièrement ennuyeux d'humains, la Croisade écarlate.\n\nAllez de l'avant et lancez une offensive sur la Croisade, <classe>. Ramenez moi 10 Anneaux de la Croisade écarlate comme preuve de votre loyauté à Varimathras et à la Dame noire.", progress = "Avez-vous fini de collecter les 10 Anneaux de la Croisade écarlate, <classe> ?", completion = "Varimathras serait fier de vous. Vous servez bien vos chefs, &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards en peau de zombieCeinture à boucleGants toilés\n\nVous recevrez également :\n\n"},
[375] = {title = "Le Frisson de la mort", objective = "Rapporter 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier à Gretchen Dedmar à Brill.", description = "Il fait si froid maintenant. Le Fléau mort-vivant brûle dans mes veines comme un serpent de glace. Mon âme sera bientôt perdue. Mais aucun destin, aussi irrévocable soit-il, ne m'empêchera de servir la Dame noire. Lorsque l'appel est arrivé, j'ai cousu des sacs pour les morts de la puissante armée de Sylvanas.\n\nMaintenant, mes mains tremblent à cause du froid. Si vous me ramenez 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier, je pourrai me coudre une couverture. Aidez-moi, <nom>, que je puisse continuer à servir la cause.", progress = "Avez-vous déjà les 5 Peaux de chauve-souris du crépuscule et la Bobine de fil, <nom> ?", completion = "J'apprécie vos efforts, &lt;nom&gt;. Puisse Sylvanas reconnaître votre valeur un jour…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape d'adepteGants de couture\n\nVous recevrez également :\n\n"},
[376] = {title = "Les Maudits", objective = "La novice Elreth a besoin de 6 Pattes de charognard et de 6 Ailes de chauve-souris du crépuscule.", description = "Je soigne nos guerriers blessés, j'adapte leurs armures et vêtements, et j'assiste le prêtre des ombres Sarvis.\n\nApparemment, vous allez entrer à son service, vous aussi, pour chasser les Âmes Perdues. Si vous voulez rester en un morceau, ce dont je ne doute pas, je peux peut-être vous aider. Je manque de pattes et d’ailes ; si vous m’en apportez, je vous fournirai une armure. Vous trouverez de nombreux loups et chauves-souris au sud.", progress = "Faites de votre mieux pour ne pas être blessé jusqu'à ce que je vous trouve une armure.", completion = "Merci, &lt;nom&gt;. Cette armure devrait vous aider.\n\nJ'espère qu'elle vous aidera plus que son précédent propriétaire…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards en linVieille ceinture en cuir\n\nVous recevrez également :\n\n"},
[377] = {title = "Crime et Châtiments", objective = "Le conseiller Millstipe de Darkshire désire que vous lui rameniez la main de Dextren Ward.", description = "Non contente de négliger les habitants du bois de la Pénombre, la Maison des Nobles a décidé d'humilier le Conseil de Darkshire en décidant d'emprisonner Dextren Ward à Stormwind plutôt que de le décapiter ainsi que le Seigneur Ebonlocke l'avait décidé.\n\nWard a été pris en train de vendre des corps du cimetière à Morbent Fel. Ce crime est passible de la peine capitale. Mais Stormwind exige que Ward soit leur prisonnier.\n\nAssassinez Ward dans la Prison de Stormwind et ramenez-moi sa main, je vous récompenserai pour cela.", progress = "Aussi longtemps qu'un pilleur de tombes comme Dextren vivra, la justice sera bafouée. Revenez une fois que la sentence du Seigneur Ebonlocke aura été appliquée à ce fugitif. Nous devons apporter aux familles des défunts la justice qu'elles méritent et, de plus, nous enverrons un message clair à la Maison des Nobles à Stormwind.", completion = "Alors finalement Dextren Ward a payé ses crimes sans nom ? Bonne chose de s'être débarrassé de ce salaud, je vous le dis. Et toutes mes félicitations, mon ami ! Non seulement vous avez apporté aux familles des défunts la paix qu'elles méritent, mais vous avez aussi envoyé un message limpide à ces bureaucrates corrompus de la Maison des Nobles. Stormwind doit s'occuper des besoins du peuple du bois de la Pénombre ou nous nous débarrasserons de leur tyrannie.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de l'AmbassadeurJambières en mailles de Darkshire\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[378] = {title = "Fureur dans les Profondeurs", objective = "Rapportez la tête de Kam Deepfury à Motley Garmason à Dun Modr.", description = "Vous avez prouvé votre loyauté au roi Magni, <classe>. Et votre haine de la vermine Sombrefer est aussi forte que la mienne.\n\nVoici une tâche que je pourrais effectuer mais je suis obligé par une dette d'honneur de rester à Longbraid. Roggo a rassemblé un faisceau d'informations qui prouvent que Kam Deepfury était derrière l'attaque du viaduc de Thandol. Ce sont les plans de Deepfury qui ont amené la ruine de Longbraid.\n\nDeepfury est détenu pour des raisons politiques dans la Prison de Stormwind. Je veux qu'il meure, <nom>. Pour Longbraid ! Ramenez-moi sa tête !", progress = "Je ne laisserai pas la bureaucratie humaine interférer dans les affaires des nains, <nom>. Il a été prouvé que Kam Deepfury a participé à la conspiration qui a mené à l'attaque du viaduc de Thandol. Le bon peuple du roi Magni a perdu de nombreuses vies a cause de la trahison de Deepfury. Les humains se contentent peut-être de le laisser croupir dans la Prison mais je ne pourrai me reposer tant qu'il lui restera un souffle de vie.", completion = "Alors Kam Deepfury a finalement senti ce qu'il en était de recevoir la Mort ? Bien. C'est ce qu'il fallait à cette lâche ordure Sombrefer. Vous avez bien agi, &lt;classe&gt;. Les victimes de l'attaque du viaduc de Thandol n'étaient que de pauvres gens pris dans un monde déchiré par la guerre et le chaos. Leurs familles auront au moins le réconfort de savoir que Deepfury a reçu le châtiment qu'il méritait. La mort du frère de Longbraid a été vengée.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de justificationBrise-crâne\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[379] = {title = "Etancher cette soif", objective = "Rapporter 5 Outres de Bat-le-désert à l'ingénieur en chef Bilgewhizzle à Gadgetzan.", description = "Vous voulez une source d'énergie. Je peux vous aider. Savez-vous ce que je veux moi ? Je veux quelque chose à boire ! Rapportez-moi cinq outres de Bat-le-désert, et je vous donnerais le 4711-FTZ.\n\nMaintenant... Devinez où vous pouvez trouver ces outres ? Pourquoi ne pas aller voir un de ces nomades Bat-le-désert, à l'est d'ici, pour lui en demander une ? Faites-moi savoir si vous y parvenez.", progress = "Bien, est-ce que les nomades vous ont \"volontairement\" donné ces outres ?", completion = "Excellent, la source d'énergie est à vous. Maintenant, elle n'est pas exactement faite pour être utilisée avec un kit scientifique tel que celui-ci, vous aurez donc un temps limité avant que les données que vous aurez rassemblées s'effacent !\n\nQuand vous aurez rassemblé tout ce dont vous avez besoin pour ce que vous voulez faire, rapportez-le-moi pour que je le ferme correctement. Vous avez tout au plus deux heures pour faire ce que vous avez à faire.\n\nSi vous n'y arrivez pas dans le temps imparti, je peux toujours vous vendre une autre source d'énergie pour réessayer. Vous m'avez bien entendu : oui - vendre !", rewards = "Vous recevrez :\n\nSource d'énergie modèle 4711-FTZ"},
[380] = {title = "Les grottes des Tisse-nuit", objective = "L’Exécuteur Arren veut que vous tuiez 10 Jeunes Tisse-nuit et 8 Araignées Tisse-nuit.", description = "Un de nos plus gros problèmes est d'obtenir les ressources nécessaires à notre survie. L'or était déjà rare lorsque l'Alliance était au sommet de sa puissance.\n\nIl y a une mine d'or au nord-ouest qui a été envahie par les araignées. Nous avons besoin de cet or, mais nous ne pouvons l'exploiter à cause de ces créatures. Je n'ai pas beaucoup de personnels à affecter à cette tâche, alors je vais devoir le faire par étapes.\n\nAllez-y et voyez ce que vous pouvez faire, <nom>.", progress = "Attention au venin d'araignée, <nom>. Si vous sentez une brûlure, il serait sage d'y jeter un œil.", completion = "Bon, c'est un début. Cela va prendre quelques semaines ou quelques mois pour éradiquer cette invasion. Après cela, nous irons là-dessous avec des torches pour brûler le nid.\n\nVous avez brillamment accompli votre mission, &lt;nom&gt;, je suis sûr que je peux vous trouver une autre tâche.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGilet en linHaubergeon robusteJambières en peau de zombie\n\nVous recevrez également :\n\n"},
[381] = {title = "La Croisade écarlate", objective = "Apporter à l’Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates.", description = "Il vous plaira d’entendre que nous progressons dans la mine, et cela grâce à vous. Nous pouvons maintenant nous atteler à d’autres tâches.\n\nMes éclaireurs m’ont dit qu’un détachement de la Croisade écarlate avait établi un campement au sud-est. Cette Croisade écarlate est une organisation abjecte qui nous chasse et n’aura de cesse d'exterminer jusqu'au dernier mort-vivant, qu'il soit du Fléau ou non. Nous devons frapper les premiers !\n\nAttention ce sont des adversaires zélés et dangereux.", progress = "Ces fous… Ils partent joyeux rejoindre leurs tombes.", completion = "Si seulement ils étaient sensibles à la raison, hein, &lt;nom&gt; ? Peut être que nous pourrions les guider sur une voie les conduisant à leur perte… ha !\n\nCes fous aveuglés par la Lumière.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague des RéprouvésMaillet des RéprouvésEpée courte des RéprouvésBâtarde des Réprouvés\n\nVous recevrez également :\n\nEau de source"},
[382] = {title = "Le messager rouge", objective = "Tuer Meven Korgal, le messager, au camp de la Croisade, puis ramener toutes les informations trouvées à l'Exécuteur Arren.", description = "Les rapports de mes supérieurs à Brill indiquent qu'un agent de la Croisade a été détaché du Monastère écarlate et envoyé ici, au Glas. Toujours selon les rapports, ce messager possède d'importantes informations sur lui. Je n'ai pas plus de détails, mais qui que soit ce messager, nous devons l'avoir !\n\nVous êtes <le meilleur/la meilleure> que je peux trouver, <nom>. Trouvez ce messager et ramenez-moi toutes les informations que vous trouverez sur lui.", progress = "Comment avance votre mission, <nom> ?", completion = "Alors… Voyons ce que nous avons… \n\n&lt;Il commence à parcourir les documents que vous avez récupérés.&gt;\n\nDes nouvelles de leurs exploits contre nous… aucune valeur. Des rapports de reconnaissance… Nouveaux ordres, \"Continuez à construire le camp près de la cité en ruines...\" Rien que nous ne connaissions déjà... Ah, qu'est-ce que ceci ? Une carte indiquant la position de leurs chefs de guerre et de leurs agents ! Voici quelque chose qui peut nous être utile.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton du BourreauTarge de Garde noir\n\nVous recevrez également :\n\n"},
[383] = {title = "Informations décisives", objective = "Livrer les documents de la Croisade écarlate à l'Exécuteur Zygand à Brill.", description = "Ceci doit être rapporté à mon supérieur, l'Exécuteur Zygand à Brill. Avec ces informations, nous serons à même de porter un coup décisif à la Croisade écarlate. Vos services ont été utiles ici au Glas, mais j'ai besoin de quelqu'un pour porter ceci à Zygand et je pense qu'il sera à même de vous trouver une mission plus en relation avec vos capacités.\n\nPrenez la route au nord du Glas. Une fois dans Tirisfal, vous arriverez à un croisement. Prenez la route vers l'est et continuez. Vous passerez devant le manoir du Foyer froid sur votre route.", progress = "Oui, que voulez-vous ?", completion = "Oui, c'est excellent. Vous avez fait un très bon travail en retrouvant ces informations, &lt;nom&gt;. Voyons… des noms d'officiers dans les Clairières de Tirisfal… \n\nImaginez le coup que l'on peut porter à ces satanés zélotes si nous pouvions tuer leurs chefs en une seule frappe.", rewards = "Vous recevrez :\n\n"},
[384] = {title = "Côtes de sanglier à la bière", objective = "Ragnar Thunderbrew à Kharanos veut 6 Côtes de sangliers des rochers et une Chope de bière au malt Rhapsody.", description = "Il n'y a rien que mes clients apprécient plus qu'une bonne côte de sanglier à la bière ! Le seul problème est que le trappeur qui nous ravitaille s'est engagé dans l'armée du roi pour aller à la guerre sur le front de l'Alliance.\n\nPeut-être pourriez-vous m'aider ? Si vous pouvez me procurer six côtes de sangliers des rochers et une bière au malt Rhapsody de la taverne, je vous donne ma recette familiale des côtes de sanglier à la bière accompagnée bien évidemment d'un échantillon gratuit ! Le secret est dans la bière, mais je ne vous en dis pas plus !", progress = "Je vais avoir besoin de 6 Côtes de sangliers des rochers et d'une Chope de bière au malt Rhapsody, <nom>.", completion = "Le malt est fermenté, les sangliers tués.\nEt avant que tout ne soit terminé\nNous allons nous chamailler comme des frères\nPour ces délicieuses côtes de sanglier à la bière !", rewards = "Vous recevrez :\n\nCôtes de sanglier à la bièreRecette : Côtes de sanglier à la bière"},
[385] = {title = "Chasse aux crocilisques", objective = "Trouver 5 morceaux de Viande de cocilisque et 6 Peaux de crocilisque pour Marek Ironheart au pavillon des pérégrins.", description = "Beaucoup de chasseurs viennent au Loch Modan pour chasser nos fameux crocilisques. Il y a toujours des marchands qui payent pour avoir ces peaux servant à la confection de vêtements ou d’armures ; sans parler de ceux qui apprécient leur viande.\n\nLes crocilisques étant féroces et retranchés sur leur île, au milieu du Loch, nous manquons de peaux. Mais ne vous laissez pas effrayer : esquiver les mâchoires de ces bêtes est une expérience enrichissante.\n\nDu moins cette fois...", progress = "Vous ai-je déjà parlé de la fois où j'ai presque perdu ma main par un de ces crocs ? Un sacré filou celui-là, des dents comme des rasoirs. Mais j'ai eu de la chance… J'ai bloqué les mâchoires de cette brute avec mon couteau. Je dois toujours avoir ce couteau quelque part d'ailleurs...", completion = "Eh bien, ce sont de très beaux spécimens que vous m'avez rapportés, &lt;nom&gt;. Du bon argent pour de bons matériaux, c'est sûr.", rewards = "Vous recevrez :\n\nRecette : Steak de crocilisqueCape robuste"},
[386] = {title = "Ce qui se passait ailleurs…", objective = "Ramener la tête de Targorr le Terrifiant au Garde Berton à Lakeshire.", description = "Targorr le Terrifiant a servi sous les ordres de Gath'llzogg en tant qu'Exécuteur suprême. Sa méthode était impitoyable, même selon les standards orcs. Les hommes qui combattaient vaillamment étaient torturés selon ses désirs. Maintenant il est enfermé dans la Prison de Stormwind, condamné à mort. Mais quelque chose ne va pas. Un de ces nobles passionnés de procédures bureaucratiques a suspendu l'exécution. Je suis sûr qu'il y a des magouilles là-dessous.\n\nMettez fin à la carrière de Targorr le Terrifiant, <nom>. Allez jusqu'à la Prison et décapitez-le avant que toutes ces arguties finissent par le libérer.", progress = "Avez-vous déjà été à la Prison de Stormwind ? Je crains que les manœuvres qui ont permis à Targorr le Terrifiant de rester en vie ne parviennent finalement à le faire libérer. Il a été condamné à mourir, <nom>, pas à servir les desseins d'un noble.", completion = "Targorr le Terrifiant a finalement eu la fin qu'il méritait. J'avoue être particulièrement content de savoir que cette bête sait maintenant ce qu'il en est d'être pris dans l'étreinte impitoyable de la mort. Bon travail, &lt;nom&gt;. Parfois, la vraie justice ne peut être trouvée qu'en dehors des cours et au-delà des visions embrumées de la politique.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée longue LucineBâton de racine durcie\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[387] = {title = "Écraser la rébellion", objective = "Tuer 10 Prisonniers défias, 8 Détenus défias et 8 Insurgés défias dans la Prison pour le Gardien Thelwater de Stormwind.", description = "La révolte doit être étouffée ! J'ai besoin de votre aide. Si l'on apprend dehors que cette prison est en rébellion, je perds mon poste ! Mais le plus important en ce moment est de forcer les prisonniers à se soumettre, pour la sécurité de Stormwind.\n\nLa punition en cas d'émeute est la mort. Tuez quelques-uns de ces déviants ! Cela devrait ramener les choses sous contrôle.", progress = "La Prison est toujours hors de contrôle ! Ces Rats de Défias doivent comprendre que leurs actions ne seront pas tolérées. Maintenant retournez là-bas et faites preuve d'un peu d'autorité !", completion = "Votre vaillance à la Prison a été grande, &lt;nom&gt;. Mais il est clair que ce problème nous dépasse. Cela ne remet pas en cause vos efforts, dont je vous suis reconnaissant.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[388] = {title = "La couleur du Sang", objective = "Rapporter 10 foulards en laine rouge à Nikova Raskol de Stormwind.", description = "L'amertume coule dans mes veines comme un poison glacé. Mon petit-fils, Mac, était un si bon garçon. À peine 14 ans. Lorsque l'armée est partie en direction du front, Max a pris les armes pour défendre la ville. Il était garde à la Prison lorsque les Défias ont été emprisonnés. Mac a réprimandé certains prisonniers qui déchiraient leurs couvertures pour en faire des foulards, symbole de leur gang. Pour cela, ils l'ont poignardé dans le dos.\n\nJe veux qu'il soit vengé. Rapportez-moi 10 de leurs précieux foulards de laine. Ils sont de la couleur du sang.", progress = "Je vois que vous êtes de retour, <classe>. Avez-vous déjà trouvé les 10 foulards en laine rouge de ces chiens de Défias à la Prison ?", completion = "Alors c'est pour ces foulards, symbole pourris de la corruption, que Mac est mort ? Quel gâchis. Quel sacrifice tragique.\n\nMais hélas, je ne peux revenir dans le passé. Mais au moins, &lt;nom&gt;, vous avez rendu justice à notre famille.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[389] = {title = "Bazil Thredd", objective = "Parler au gardien Thelwater à la prison.", description = "VanCleef et moi étions membres de la Guilde des Maçons. Notre grand projet était de reconstruire Stormwind après la guerre.\n\nUne fois notre tâche finie, nous avons été escroqués. Les nobles ont refusé de payer. Plusieurs Contremaîtres se virent proposer des emplois dans le gouvernement, mais VanCleef refusa par loyauté envers la guilde. Il mena une émeute et quitta la cité, jurant de se venger.\n\nSon lieutenant, Bazil Thredd, doit en savoir plus sur ses plans. Il est détenu dans la prison de Stormwind.", progress = nil, completion = "Par la Lumière, que voulez-vous ? Vous ne voyez pas que nous sommes en crise ici ?\n\nBazil Thredd ! Pourquoi voulez-vous parler à ce salaud ? Qu'est-ce qui me prouve que vous n'êtes pas de mèche avec lui et que vous ne venez pas pour aider les mutins ? Si toutes ces satanées cellules n'étaient pas ouvertes, je vous y aurais bien jeté !", rewards = "Vous recevrez :\n\n"},
[391] = {title = "Les Emeutes de la Prison", objective = "Tuer Bazil Thredd et ramener sa tête au Gardien Thelwater à la Prison.", description = "Qu'une chose soit bien claire, <nom> : je n'ai pas confiance en vous. Mais la situation étant ce qu'elle est, ça ne change pas grand-chose. \n\nAlors voilà comment on va faire : descendez là-bas et parlez à Thredd. Et si vous êtes vraiment de notre côté, tuez-le et ramenez-moi sa tête. Et s'il se trouve que vous êtes de son côté, et que vous ne revenez pas... Je vous retrouve et vous périrez comme un rat. Compris ?", progress = "Ou vous m'apportez la tête de Thredd ou je prends la vôtre, compris, <nom> ?", completion = "Sans Thredd pour les mener, peut-être que les émeutes pourraient être contrôlées. Nous verrons.\n\nJe dois dire que passée la première demi-heure, je ne m'attendais pas trop à vous voir revenir, mais il semblerait que j'ai fait une erreur de jugement à votre sujet.\n\nJe pense que vous n'avez pas pu tirer de lui beaucoup d'informations utiles, hein ? Mais je connais une ou deux choses sur les activités de Thredd qui pourraient vous intéresser.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[392] = {title = "Un curieux visiteur", objective = "Apporter la description du visiteur de Thredd à Baros Alexston à Stormwind.", description = "Pendant les premières années de son emprisonnement, Thredd n'a reçu aucun visiteur. Je pensais qu'il n'était plus utile à la Confrérie Défias, alors ils l'ont abandonné.\n\nQuoi qu'il en soit, il y a quelques mois, tout a changé ; il a commencé à recevoir des visites régulières... Une à deux fois par semaine. C'était un type étrange, calme. J'avais des soupçons, mais tous ses papiers étaient en règle.\n\nLe nom sur les papiers était Maelik, voici sa description. Je ne pense pas qu'il va revenir voir Thredd.", progress = "Oui, <nom>, qu'avez-vous trouvé ?", completion = "Mhh, Maelik ? Non, cela ne me dit rien, la description non plus. Cela pourrait être n'importe qui ! Un ancien maçon, quelqu'un de la Confrérie défias… Mais s'il a autant de contacts que Thelwater le dit, peut-être que quelqu'un pourrait le reconnaître. Laissez-moi y réfléchir...", rewards = "Vous recevrez :\n\n"},
[393] = {title = "Les Ombres du Passé", objective = "Apporter la Description scellée du visiteur de Thredd au Maître Mathias Shaw à Stormwind.", description = "Je n'en ai aucune idée, <nom>. Il y a quelqu'un d'autre qui pourrait vous aider, et il se trouve qu'il me doit une faveur... bon, pas la peine de parler de ça. Vous trouverez maître Mathias Shaw, du SI:7, dans la caserne de la vieille ville. Shaw est impliqué dans la plupart des opérations louches de la cité.\n\nSi quelqu'un a des renseignements, ce sera lui.", progress = "Bonjour. Que puis-je faire pour vous, <classe> ?", completion = "Comment ? Qu'est-ce donc ? Oui, je pense savoir qui est cet homme, mais il ne s'appelle pas Maelik. Les assassins changent constamment d'identité et de déguisements, les délaissant dès qu'ils n'en ont plus besoin. Il est connu sous un autre nom, Marzon, bien que cela ne soit sûrement pas son vrai nom.\n\nEnfin, c'est un assassin et j'en connais un rayon sur lui.\n\nMarzon est en ce moment employé par le seigneur Gregor Lescovar, un noble qui a une réputation douteuse, malgré la corruption des artistocrates de Stormwind.", rewards = "Vous recevrez :\n\n"},
[394] = {title = "La tête de la bête", objective = "Parler à Mathias Shaw, à Stormwind.", description = "Retrouvez Shaw dans la vieille ville. Faites-lui savoir que la menace Lescovar a été résolue grâce à vous. Je suis sûr qu'il sera fier d'avoir un nouveau héros parmi les citoyens de Stormwind.\n\nJe pense qu'il vous enverra rencontrer le Prince ou un autre noble. Ne vous laissez pas faire, <nom>. Les nobles peuvent penser qu'ils règnent sur la ville autant qu'ils le veulent, il n'en reste pas moins que certaines choses échappent à leur contrôle.", progress = nil, completion = "Alors, il est mort ? Votre justice est rapide, &lt;nom&gt;. Je prie la Lumière de n'être jamais votre proie !\n\n\n\nCe n'est pas une critique, &lt;nom&gt;. Comment le pourrais-je, étant le maître des assassins ? En vérité, vous avez rendu un fier service au peuple de Stormwind et pour cela, je vous remercie.", rewards = "Vous recevrez :\n\n"},
[395] = {title = "La fin de la Confrérie", objective = "Parler à Baros Alexston à Stormwind.", description = "Ah, j'avais presque oublié. Alexston est passé pendant que vous n'étiez pas là, il désirait vous parler. Il est clair qu'il désirait rendre compte de l'activité de la Confrérie défias au roi.\n\nUn petit conseil, <nom>. Si quelqu'un le demandait, je donnerais tous les détails, mais sans préciser que c'est votre main qui a tué Lescovar. Croyez-moi. Je suis... habitué... à ce genre de pratiques.\n\nEn ce qui concerne Trias, he bien, ne parlez de lui à personne... jamais... Si vous le pouvez.", progress = nil, completion = "C'est un plaisir de vous revoir, &lt;nom&gt;. Il paraît que le seigneur Gregor Lescovar a été trouvé mort il y a peu.\n\nIl semble que votre mission ait réussi. Vous avez toute ma gratitude pour m'avoir sauvé, ainsi que beaucoup d'autres personnes, de la vengeance de VanCleef.", rewards = "Vous recevrez :\n\n"},
[396] = {title = "Une audience avec le roi", objective = "Apporter le rapport de Baros Alexston sur la Confrérie Défias au Roi Varian Wrynn au Donjon de Stormwind.", description = "J'ai préparé un rapport pour le roi. Je crois que vous devriez le lui remettre, en même temps qu'une explication de vos découvertes. N'ayez crainte, il vous récompensera sûrement pour vos actions.\n\nVotre audience est prévue pour bientôt, vous devriez vous hâter, il y a du chemin jusqu'au donjon de Stormwind.", progress = "<nom>, oui ? J'ai été informée par Baros Alexston que vous veniez. Je dois dire que je suis très intéressée par ce que vous avez à m'apprendre.", completion = "Vous devez être récompensé pour les services que vous avez rendus à Stormwind, &lt;nom&gt;. Si Vancleef avait réussi, il aurait sans aucun doute pu causer de grands dommages au royaume. Et cela, nous devons absolument l'éviter.\n\nPrenez ceci, &lt;classe&gt;, en gage de la gratitude du roi. Je suis seulement désolé qu'il ne puisse pas vous le remettre lui-même, mais il est parti en mission diplomatique et il ne reviendra pas avant quelque temps.", rewards = "Vous recevrez :\n\nSceau de Wrynn"},
[397] = {title = "Vous nous avez bien servi", objective = "Aller demander votre récompense en parlant à Zggi, le serviteur de Zardeth de Black Claw.", description = "J'ai entendu dire que le seigneur Wishock avait apprécié ce breuvage.\n\nVous nous avez bien servi, <nom>. Les démonistes de Stormwind seront capables de s'exercer sans être dérangés et ceci grâce à vous. Pour vos efforts, nous vous avons préparé un cadeau. Allez voir mon serviteur, Zggi et demandez-lui votre récompense.", progress = nil, completion = "Le Maître a dit de donner cadeau à &lt;nom&gt;. Zggi veut garder joli cadeau mais Zggi connaître mieux pas trahir Maître.", rewards = "Vous recevrez :\n\nChapeau de mage d’effroi"},
[398] = {title = "On recherche : Œil-de-ver", objective = "Tuer Œil-de-ver et rapporter ses griffes à l'Exécuteur Zygand pour toucher la récompense.", description = "On recherche : Œil-de-ver !\n\nBête affreuse, même d'après les critères des gnolls, Œil-de-ver a été condamné à mort pour ses crimes envers les Réprouvés. Ce criminel infâme volait les corps pour que ceux-ci soient utilisés par l'armée du roi-liche. La dernière apparition d'Œil-de-ver a eu lieu près de l'antre de Garren, au nord de Brill, lorsqu'il pillait les terres.\n\nLa ville de Brill offre une récompense à la personne capable d'exécuter la sentence. Les griffes de ce brigand doivent être rapportées à l'Exécuteur Zygand.\n\nLa pitié est pour les faibles.", progress = "Oui ?", completion = "Œil-de-ver a finalement payé pour ses actes immoraux. Peut-être que vos brillants exploits enverront un message clair à ceux qui souhaitent notre perte. Au nom de la ville de Brill, je vous remercie, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon d'écailles de cuivreGilet de laboureur\n\nVous recevrez également :\n\n"},
[399] = {title = "Débuts modestes", objective = "Aller à la maison de Baros Alexston dans la marche de l'Ouest pour chercher sa boussole et lui rapporter à la place de la Cathédrale de Stormwind.", description = "J'ai l'impression qu'une éternité s'est écoulée depuis que j'étais un jeune garçon travaillant à la ferme, dans la marche de l'Ouest. On dit que l'on ne peut jamais revenir en arrière et c'est vrai. C'est d'autant plus vrai dans mon cas que la maison de ma famille a été brûlée et détruite par des voleurs.\n\nJ'ai parlé avec mon père de ce qu'il était advenu de quelques-uns de mes biens, notamment de ma première boussole. Il n'a pas pu les sauver. Il m'a dit qu'ils devaient être cachés dans la ferme.\n\nLa ferme des Alexston se trouve à l'ouest de la Colline des sentinelles. Peut-être pourriez-vous y aller et rapporter mes biens ?", progress = "<nom> ! L'avez-vous trouvée ?", completion = "Oh, merci, &lt;nom&gt; ! Elle ne peut plus servir à mes travaux mais j'y attache une grande valeur sentimentale… Je vous remercie de me l'avoir ramenée… ce qui a dû vous coûter pas mal de désagréments, sans compter le temps pour aller et revenir de la marche de l'Ouest. Vous avez ma gratitude et je vous prie d'accepter ceci en guise de remerciement.", rewards = "Vous recevrez :\n\n"},
[400] = {title = "Des outils pour Steelgrill", objective = "Rapporter les outils de SteelGrill à Beldin Steelgrill.", description = "Beldin Steelgrill tient un magasin de mécanique. C’est notre meilleur technicien d'engins de siège ! Mais il n'est pas soigneux avec ses outils. Je vous jure qu'il casse ses clés plates aussi vite que nous les lui fournissons !\n\nNous venons juste de préparer sa dernière commande d'outils. Si vous la lui livrez, je suis sûr qu’il vous récompensera.\n\nSon magasin, le dépôt de Steelgrill, est juste au nord-est de Kharanos. Et c'est le repaire de nombreux pilotes d'engins de siège vétérans. Quand vous y serez, gardez les oreilles ouvertes, il y aura peut-être des occasions à saisir.", progress = "Hum ? Vous paraissez un peu jeune pour être un conducteur d'engins de siège. Mais qu'importe… avez-vous besoin de réparer quelque chose ?\n\nAlors prenez un numéro et mettez-vous à l'aise. Je suis en train de travailler sur quelques moteurs en ce moment et je n'aurai pas le temps de m'occuper d'un autre travail avant au moins quelques jours.\n\nOu êtes-vous ici pour quelque chose d'autre... ?", completion = "Vous avez mes outils ? Bien joué, bien joué ! Je viens de casser il y a une heure mon rochet à dents et j'en ai besoin pour finir de réparer l'engin du Pilote Stonegear. Vous avez fait du bon travail en ramenant ces outils ici, &lt;nom&gt;.\n\nVoilà, prenez ces pièces pour votre peine.", rewards = "Vous recevrez :\n\n"},
[401] = {title = "Attendre la fin des travaux de Sirra", objective = "Attendre un moment puis parler de nouveau avec Sirra Von'Indi.", description = "J'ai presque fini de traduire cette note. Si vous revenez dans un moment, j'aurai fini.", progress = nil, completion = "Nous y sommes. C'est traduit…\n\n&lt;L'air semble devenir plus dense, comme si un épais voile noir s'étendait au-dessus des terres…&gt;", rewards = "Vous recevrez :\n\n"},
[402] = {title = "Sirra est occupée", objective = "Vérifier plus tard si Serra est toujours occupé.Je suis désolé, mais avec la ville dans cet état, j'ai d'autres tâches qui m'attendent. Peut-être plus tard, si nous survivons, je pourrai finir cette traduction.", description = "Je suis désolé, mais avec la ville dans cet état, j'ai d'autres tâches qui m'attendent. Peut-être plus tard, si nous survivons, je pourrai finir cette traduction.", progress = nil, completion = nil, rewards = nil},
[403] = {title = "La garde du tonneau de Thunderbrew", objective = "Ce tonneau de bière est gardé par Jarven Thunderbrew. Tant qu'il est dans les sous-sols, aucun tonneau ne peut être bougé.", description = nil, progress = nil, completion = nil, rewards = nil},
[404] = {title = "Une tâche putride", objective = "Rapporter 7 Griffes putrides au Garde noir Dillinger à Brill.", description = "Le Fléau s'est infiltré dans les clairières de Tirisfal et a infesté l'ouest de Brill, près du vieux pont.\n\nAllez là-bas et faites reculer les morts pourrissants et les cadavres décomposés que vous trouverez. Eparpillez leurs ossements et rapportez leurs griffes putrides et les gardes noirs vous récompenseront.", progress = "Avez-vous accompli la tâche que je vous avais confiée ? Avez-vous ces griffes putrides ?", completion = "Bien joué. Je regrette de ne pas avoir été là pour vous voir écraser ces morts-vivants en pulpe immonde !", rewards = "Vous recevrez :\n\n"},
[405] = {title = "La Liche prodigue", objective = "Présenter les ordres de Sevren à Bethor Iceshard à Undercity.", description = "Bethor Iceshard, un puissant mage d'Undercity, dans le sud, m'a demandé de lui envoyer un agent efficace contre le Fléau. Vous, <nom>, serez cet agent.\n\nPrésentez ces ordres à Bethor. Il vous instruira du détail de votre mission. Je ne connais pas les détails de celle-ci mais je crois qu'il s'agit de recruter une liche. Et cela sera dangereux.\n\nAlors soyez prêt, <classe>. Vous ne devez pas échouer.\n\nVous trouverez Bethor dans le quartier des mages d'Undercity.", progress = "Salutations. Soit vous ne savez pas qui je suis, soit vous avez des affaires urgentes me concernant.\n\nParce que si ce n'était pas le cas, je suppose que vous ne seriez pas assez fou pour me déranger...", completion = "Ah, vous êtes cet agent envoyé par le magistrat Sevren. Alors oui, notre mission est cruciale.\n\nJe sais que Sevren a dû m'envoyer quelqu'un qui a les capacités requises… mais nous verrons.", rewards = "Vous recevrez :\n\n"},
[407] = {title = "Les Champs du Chagrin", objective = "Donner la citrouille enchantée au Zélote écarlate capturé qui est gardé dans le cellier de la taverne des Pendus.", description = "D'inoffensives citrouilles, n'est-ce pas ? A ce qu'il semble. Si nous voulons stopper l'avance d'Arthas du nord et l'infestation humaine venant du sud, nous devons commencer à comprendre l'étendue de notre potentiel de morts-vivants.\n\nAvec un peu d'ingéniosité une simple citrouille va devenir un agent de la Dame noire. Cette citrouille, traitée avec ma dernière formule, sera une menace sérieuse.\n\nUn autre Zélote écarlate a été capturé et est gardé prisonnier dans le cellier de la Taverne des pendus. Prenez cette citrouille et donnez-la-lui.", progress = "Reste à distance, créature impie et folle ! Que la Lumière me protège ! La Croisade écarlate va vous bannir d'Azeroth… \n\n…Attendez. Est-ce que c'est de la nourriture pour moi ? J'ai si faim…", completion = "Par la Lumière ! De la nourriture, enfin ! Délicieuse petite citrouille…", rewards = "Vous recevrez :\n\n"},
[408] = {title = "La Crypte Familiale", objective = "Tuer 8 Spectres ancestraux et 8 Ancêtres pourrissants.\n\nTuer le capitaine Dargol et ramener son crâne au magistrat Sevren à Brill.", description = "Les moulins d'Agamand sont devenus un avant-poste du Fléau. Leur point fort est la crypte de la famille Agamand où leur chef local, un squelette nommé le capitaine Dargol a son quartier général. A l'aide de la nécromancie, il a relevé les ancêtres des Agamand et veut les utiliser contre nous.\n\nCela ne doit pas être et c'est vous qui allez stopper ceci. Allez jusqu'à la crypte de la famille Agamand et battez les ancêtres Agamand.\n\nEt ramenez-moi le crâne du capitaine Dargol.", progress = "Le temps est un luxe dont nous ne disposons pas, <nom>. À chaque heure qui passe l’emprise du Fléau sur les clairières de Tirisfal s'accroît.", completion = "Vos actions ont porté un coup au Fléau. Et votre victoire ne passera pas inaperçue, ni pour les Réprouvés, ni pour nos ennemis.\n\nContinuez la lutte comme nous tous, &lt;nom&gt;, et un jour, nous repousserons le roi-liche lui-même d'Azeroth !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton de sombreboisBrise-os\n\nVous recevrez également :\n\n"},
[409] = {title = "Prouver l'allégeance", objective = "Obtenir une Bougie de signal.\n\nInvoquer Lillith Nefara et la tuer.\n\nRetourner voir Gunther sur son île.", description = "Vous dites que vous n'êtes pas <lié/liée> à la volonté du roi-liche et l'enchantement que Bethor a mis dans mon livre corrobore ceci. Mais avant que je ne vous croie, je dois avoir des preuves que vous êtes <un ennemi/une ennemie> du Fléau.\n\nIl y a un vieil et sanglant autel sur la côte sud de cette île. Il est utilisé par un puissant agent du Fléau, Lillith Nefara.\n\nPrenez une Bougie de signal dans cette boîte là-bas. Allumez-là sur l'autel et Lillith se réveillera. Détruisez-la et je saurai que vous êtes l'ennemi du Fléau.", progress = nil, completion = "Vous avez défait Lillith Nefara, prouvant que vous êtes un ennemi du Fléau. Incroyable.\n\nJe croyais être le seul mort-vivant possédant une volonté propre mais vous m'avez montré que d'autres ont brisé l'emprise du roi-liche.", rewards = "Vous recevrez :\n\n"},
[410] = {title = "L'Ombre dormante", objective = "C'est une vieille table ensanglantée.", description = nil, progress = "C'est une vieille table ensanglantée.", completion = "Vous placez la Bougie de signal sur l'autel et vous l'allumez…", rewards = nil},
[411] = {title = "Le Retour de la Liche Prodigue", objective = "Rapporter la Gemme du Néant à Bethor Iceshard à Undercity.", description = "Portez cette Gemme du néant à mon vieux compagnon Bethor. Cela nous permettra de communiquer… et j'ai tant de choses à lui dire.", progress = "Avez-vous rendu le livre de Gunther ? A-t-il répondu ?", completion = "Vous l'avez convaincu de se joindre à nous ! Vous avez accompli un exploit pour la cause des Réprouvés, &lt;nom&gt;. La Dame noire en sera informée.", rewards = "Vous recevrez :\n\nTarge en os"},
[412] = {title = "Opération Recombobulation", objective = "Porter 8 Rouages de Rééquilibrage et 8 Engrenages gyromécaniques à Razzle Sprysprocket à Kharanos.", description = "Après des analyses approfondies de la situation, il semble que non seulement nous avons échoué à éradiquer les troggs mais que nous avons changé la majorité de la race gnome en horribles gnomes lépreux.\n\nOzzie et moi voulons renverser l'effet de cette abominable lèpre grâce à notre dernière invention : le Recombobulateur. Cette machine est pratiquement complète mais nous avons un grand besoin de Rouages de Rééquilibrage et d'Engrenages gyromécaniques. Demandez-en pour nous aux gnomes lépreux devant Gnomeregan.", progress = "Le Recombobulateur sera bientôt prêt et marchera dès que nous aurons suffisamment de Rouages de Rééquilibrage et d'Engrenages gyromécaniques.", completion = "Ces Engrenages gyromécaniques et Rouages de rééquilibrage sont en parfaite adéquation avec les plans d'Ozzie pour le Recombobulateur. Une fois que j'aurai mis du lubrifiant dans les pistons de combustion internes, ajusté le crank-o-ratchet et augmenté la viscosité de l'électrogomme, cet engin gnome sera comme neuf.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de pilotageCape tachée d'huile\n\nVous recevrez également :\n\n"},
[413] = {title = "La bière Shimmer", objective = "Amener le Tonneau de Bière Shimmer au Montagnard Barleybrew.", description = "J'aimerais que mon frère Wellart essaye ma nouvelle bière Shimmer. C'est un montagnard dont la garnison est la tour de garde sud, une des deux tours au bord du Loch Modan.\n\nIl n'est peut être pas un brasseur comme le reste des Barleybrew mais il aime boire une bonne bière et je sais qu'il appréciera celle-ci.\n\nPouvez-vous lui porter ce Tonneau de Bière Shimmer pour moi ?", progress = "Bonjour, <classe> ! Qu'est-ce qui peut bien vous amener par ici ?\n\nQuelque chose d'intéressant, j'espère. Je n'ai pas eu un bon combat depuis plusieurs jours et ce Tonneau de bière est pratiquement vide….", completion = "&lt;Le Montagnard Barleybrew goûte la Bière Shimmer…&gt;\n\nOh. Wouahh ! Ce truc vous met plein d'étoiles dans les yeux. J'ai l'impression de pouvoir voir dans le noir !", rewards = "Vous recevrez :\n\n"},
[414] = {title = "Bière à Kadrell", objective = "Portez le Tonneau de Bière Shimmer au montagnard Kadrell.", description = "J'ai encore bu un peu de cette bière Shimmer faite par mon frère, c'est vraiment une sacrée bière ! J'aimerais qu'un ami montagnard la goûte. Son nom est Kadrell et il patrouille en général sur la route qui passe par Thelsamar au Loch Modan.\n\nPour aller à Thelsamar, allez au sud-ouest à travers le tunnel puis allez au nord-est quand le chemin se sépare. Suivez cette route jusqu'à Thelsamar.\n\nDonnez au montagnard Kadrell ce Tonneau de Shimmer Stout et voyez ce qu'il en pense !", progress = "Salutations, <classe>, et bienvenue à Thelsamar !", completion = "Maintenant, laissez-moi goûter…\n\nPar la barbe de Magni ! Ce truc vous fait tourner la tête ! Et vous avez les jambes légères aussi.\n\nJ'ai l'impression de pouvoir voler !", rewards = "Vous recevrez :\n\n"},
[415] = {title = "La nouvelle cuvée de Rejold", objective = "Parler à Rejold Barleybrew.", description = "Rejold Barleybrew du village de Brassetout vous demande.\n\nIl veut vous parler d'une nouvelle boisson sur laquelle il travaille… Il parle d'un coup de main que vous pourriez lui donner. Vous pourriez faire demi-tour et voir ce qu'il a à dire.\n\nIl pourrait y avoir quelques mousses gratuites pour vous...", progress = nil, completion = "&lt;nom&gt; ! Vous savez, cette herbe que vous m'avez apportée ? Eh bien je l'ai utilisée dans quelques recettes et l'une d'entre elles donne un résultat excellent !\n\nEssayez donc moi cela et dites-moi ce que vous en pensez...", rewards = "Vous recevrez :\n\nChope de Shimmer Stout"},
[416] = {title = "Chasse au rat", objective = "Apporter 12 Oreilles de Rat des tunnels au Montagnard Kadrell à Thelsamar.", description = "Nous avons vraiment un problème de vermine à l'ouest. Les rats des tunnels kobolds sont venus dans les collines, ont creusé leurs terriers et contaminé notre terre avec leur pestilence !\n\nNous voulons les éliminer. Chassez-les et ramenez-moi leurs oreilles pour la récompense.\n\nVous trouverez les tunnels des kobolds et leurs terriers à l'ouest de Thelsamar, disséminés à flanc de montagne.", progress = "Salut, <nom>. Alors, cette chasse au rat ?", completion = "Heuu ! Lorsque j'ai demandé ces oreilles, je ne réalisais pas qu'elles puaient autant !\n\nVoici votre récompense, &lt;nom&gt;. Bon travail.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards en peau brûléeBottes de cavalier\n\nVous recevrez également :\n\n"},
[417] = {title = "La revanche du pilote", objective = "Tuer Griffe galeuse.\n\nRapporter la griffe à laquelle il doit son nom et le Journal de Hildelve au pilote Hammerfoot.", description = "Hildelve écrit dans son journal qu'il a été attaqué par Griffe galeuse, un \"gigantesque ours Griffeglace\". Il a repoussé la bête mais pas avant d'avoir été gravement blessé.\n\nD'après l'état du corps de Hildevel, Griffe galeuse a dû revenir et le tuer.\n\nNéanmoins, Hildevel a écrit dans son journal sa dernière volonté :\n\nVengez-moi ! Tuez Griffe galeuse !", progress = "Bonjour, <nom>. Avez-vous des nouvelles de mon ami Hildeve ?", completion = "Ce sont d'amères nouvelles, Hildeve était un très bon ami. Et j'aurais aimé être là avec vous lorsque vous avez trouvé cette bête, Griffe galeuse !\n\nMerci, &lt;nom&gt;. Les pilotes de la brigade des sapeurs d'Ironforge se souviendront de cet exploit.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague d'artisanMarteau compact\n\nVous recevrez également :\n\n"},
[418] = {title = "Les boudins de Thelsamar", objective = "Apporter 3 morceaux de Viande d’ours, 3 Tripes de sanglier et 3 Ichors d'araignée à Vidra Hearthstove à Thelsamar.", description = "On n'a jamais manqué d'estomacs vides à Thelsamar, avec les gamins qui courent partout et les ouvriers qui reviennent de leur journée de travail après un dur labeur. Nos boudins sont réputés, vous les avez déjà essayés ?\n\nNon ? Eh bien, par ici, il faut travailler pour mériter sa pitance et ce n'est pas parce que vous êtes bien <habillé/habillée> que l'on fera une exception pour vous, <classe>.\n\nJe vais avoir besoin de viande d'ours, d'intestins de sanglier pour la cuisson et d'ichor d'araignée pour épicer le tout. Trouvez-moi cela et laissez la cuisine à Vidra !", progress = "Je suis prête à cuisiner, avez-vous les ingrédients ?", completion = "Croyez-moi, c'est bien plus dur qu'il n'y parait mais…\n\nOh, je ne savais pas que quelqu'un pouvait trouver autant d'intérêt à la fabrication de boudin. Je vais vous donner la recette au cas où. Et voilà, n'oubliez pas de les manger frais !", rewards = "Vous recevrez :\n\nBoudinRecette : Boudin"},
[419] = {title = "Le pilote perdu", objective = "Trouver le pilote Hildeve.", description = "Mon ami et camarade Mori Hildelve, qui est Sapeur, a disparu dans les collines. Nous étions en train de chercher un minerai rare qui est nécessaire pour une poudre explosive de grande qualité. Durant nos recherches, il a essayé de monter une pente avec son engin lorsque le moteur a explosé !\n\nConvaincu que le minerai était dans ces montagnes, Hildelve m'a confié la garde des engins tandis qu'il poursuivait la prospection à pied.\n\nCela fait maintenant des jours de cela et j'ai entendu les grognements de bêtes dans la montagne la nuit. Mori est dur comme l'acier mais je suis inquiet.\n\nS'il vous plaît, <nom>. Trouvez-le.", progress = nil, completion = "Ci-gît le corps d'un nain, brisé, gelé et nettoyé par les charognards des montagnes. Coincé dans sa main, il y a un livre contenant les notes fébriles prises par Mori Hildelve. Et autour de lui, toujours intacte, il y a une veste de sergent.\n\nC'est sûrement ici que le sort de ce sapeur a été scellé.", rewards = "Vous recevrez :\n\nHaubergeon de sapeur"},
[420] = {title = "Les observations de Senir", objective = "Apporter le rapport de Grelin à Senir Whitebeard à Kharanos.", description = "Les troggs qui infestent le tunnel sont extrêmement hostiles et n'hésitent pas à attaquer tout intrus. Vous avez l'air suffisamment solide, vous devriez donc vous en tirer.\n\nLa route à suivre ? Si vous voulez parler à Senir, vous le trouverez à Kharanos.\n\nPassez par le tunnel et une fois dehors à l'autre extrémité, suivez la route, elle vous conduira à Kharanos.", progress = "Comment allez-vous ? Aimeriez-vous partager une boisson avec moi ? Pas grand-chose d'autre à faire par ce froid.", completion = "Qu'est-ce que cela ? Ah, le rapport de mon frère. Hmm… \n\nJe lui ai dit d'utiliser prudemment le nom du roi mais il n'écoute pas. Pas de mal à cela je suppose, bien que cela risque de créer quelques remous au Sénat. Remous dont on pourrait bien se passer ! Ha !\n\nBon, je devine que je dois envoyer mon rapport à Ironforge également, mais je dois admettre que je suis un peu en retard. Ce satané froid...\n\nJe devrais avoir du travail pour vous un peu plus tard, si vous êtes intéressé.", rewards = "Vous recevrez :\n\n"},
[421] = {title = "Prouver votre valeur", objective = "Tuer 5 Poils-blancs Ragelune pour Dalar Dawnweaver au Sépulcre.", description = "Dame Sylvanas a chargé Varimathras de la conquête des terres humaines et naines se trouvant vers le sud.\n\nMais Arugal, ci-devant charlatan de Dalaran et aujourd'hui bête maudite du donjon d'Ombrecroc, a tristement utilisé sa magie. Il a créé le chaos dans la forêt des Pins argentés qui est d'une grande importance stratégique.\n\nJ'ai besoin de quelqu'un de doué dans les arts du combat pour rétablir l'ordre. Prouvez-moi votre valeur en tuant 5 Poils-blancs Ragelune. Ces bêtes dégénérées se trouvent généralement près de la route, en bas de la colline.", progress = nil, completion = "Vous m'avez bien servi, &lt;classe&gt;. Il est évident que vous me serez d'une aide précieuse : je me prépare à débarrasser la Forêt des Pins argentés de la malédiction d'Arugal.", rewards = "Vous allez être la cible du sort suivant :\n\nIntelligence des arcanes\n\nVous recevrez :\n\n"},
[422] = {title = "La folie d'Arugal", objective = "Retrouver le Remède d'Arugal pour Dalar Dawnweaver au Sépulcre.", description = "Comment Arugal a-t-il pu entrer au Kirin Tor ? C'est au-delà de ma compréhension. Son savoir semblait aussi léger qu'une bulle de savon.\n\nCe qui importe maintenant, c'est de savoir quelle magie Arugal a utilisée afin que je puisse la retourner contre lui et rendre la forêt des Pins argentés saine pour la Dame noire.\n\nArugal a longtemps habité dans la ferme juste au nord du pont. Retrouvez-moi le sort appelé le Remède d'Arugal dans ses livres.", progress = "Pour savoir ce qui se passe ici, <classe>, j'ai besoin d'étudier le sort appelé le Remède d'Arugal. Apportez-le-moi ou je serais obligé de me trouver un serviteur plus performant.", completion = "C'est précisément le sort que je cherchais, &lt;classe&gt;. Si votre loyauté à la cause de la Dame noire ne faiblit pas, votre futur au sein des Réprouvés s'annonce des plus brillants.", rewards = "Vous allez être la cible du sort suivant :\n\nIntelligence des arcanes\n\nVous recevrez :\n\n"},
[423] = {title = "La folie d'Arugal", objective = "Rapportez 6 Bracelets de Gloutons et 6 Bracelets de Ténébreux à Dalar Dawnweaver au Sépulcre.", description = "Après examen des travaux d'Arugal, mes pires hypothèses se sont confirmées. Le vieux fou n'était même pas bon à vider des pots de chambre à Dalaran. Alors, représenter le Kirin Tor dans ses heures les plus sombres...! Les fous !\n\nArugal a utilisé des reliques magiques pour renforcer ses faibles pouvoirs. J'ai besoin d'étudier ces objets avant toute chose. Allez au nord et tuez des Gloutons Ragelune et des Ténébreux Ragelune jusqu'à ce que vous ayez récolté suffisamment de leurs bracelets enchantés. J'en ai besoin pour mes recherches. Vous trouverez ces créatures infâmes au nord et à l'est.", progress = "J'ai besoin de 6 bracelets de Gloutons et 3 bracelets de Ténébreux pour comprendre la situation et trouver une solution contre Arugal. Maintenant accomplissez votre tâche et tuez des Gloutons et des Ténébreux Ragelune jusqu'à ce que vous puissiez me ramener ce dont j'ai besoin.", completion = "J'espère que je pourrai acquérir suffisamment d'énergie d'un aussi petit échantillon. J'aurais dû vous demander de me ramener plus de bracelets.\n\nIl faut quand même dire que vous avez récupéré ceux-ci avec maestria, &lt;classe&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nIntelligence des arcanes\n\nVous recevrez :\n\n"},
[424] = {title = "La folie d'Arugal", objective = "Tuer Grimson le Pâle et ramener sa tête à Dalar Dawnweaver au Sépulcre.", description = "Découvrir les sombres secrets des enchantements d'Arugal va me prendre plus de temps que je ne le pensais.\n\nPendant ce temps, j'aimerais que vous vous occupiez d'un problème que nos Traqueurs noirs ont découvert. Il semble qu'Arugal ait laissé sa magie s'étendre jusqu'à la mine du gouffre d'Elem dans les collines du sud-est.\n\nCette mine serait d'une aide précieuse pour Varimathras.\n\nJe veux que vous décapitiez le contremaître de cette mine, Grimson le Pâle. Avec sa mort, la mine sera nôtre.", progress = "Est-ce que Grimson le Pâle a été tué ? Varimathras ne sera pas content si nous n'exécutons pas ses volontés.", completion = "Absolument splendide. La mine va nous fournir des ressources en quantité suffisante pour nos forces tandis que nous occuperons la forêt des Pins argentés puis Azeroth.", rewards = "Vous allez être la cible du sort suivant :\n\nIntelligence des arcanes\n\nVous recevrez :\n\n"},
[425] = {title = "Ivar l'Infect", objective = "Tuer Ivar l'Infect et ramener sa tête à Rane Yorick au lopin d'Ivar.", description = "Mon frère Quinn et moi avions pour mission de reconnaître la forêt des Pins argentés et de rendre compte au Grand exécuteur Hadrec. Mais nous ne sommes pas allés loin. En passant par cette ferme, nous avons été attaqués par la goule nommée Ivar l'Infect.\n\nNous avons réussi à nous échapper mais Quinn a été grièvement blessé par Ivar. Il récupère en ce moment grâce à la potion que vous lui avez donnée mais Ivar pourrait revenir avant qu'il soit guéri.\n\nTuez Ivar de manière à donner le temps à Quinn de récupérer. Ivar se trouve généralement dans la grange, attendant que je baisse ma garde.", progress = "Avez-vous tué Ivar l'Infect ? Si vous ne le faites pas pour moi et mon frère, alors faites-le pour les Réprouvés.", completion = "Ah, merci. Je vous suis reconnaissant, &lt;nom&gt;.\n\nJe vous citerai dans mon prochain rapport à mes supérieurs.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards capitonnésCeinture défraîchie\n\nVous recevrez également :\n\n"},
[426] = {title = "La chute des moulins", objective = "Rassemblez 5 Côtes ébréchées et 3 Crânes noircis et rapportez-les au garde noir Dillinger à Brill.", description = "Les forces du Fléau essayent de construire une base aux moulins d'Agamand. Si elles réussissent, elles pourront lancer d'autres attaques sur Tirisfal.\n\nLes ordres sont clairs. Les forces du Fléau positionnées là-bas doivent être détruites.\n\nAllez aux moulins. Collectez des côtes ébréchées sur les soldats et les squelettes Cliquethorax, ainsi que des crânes noircis d'Ossomanciens Sombroeil.\n\nPour rejoindre les moulins, suivez la route ouest. Après avoir traversé le pont, prenez la route nord au premier croisement. Lorsque vous verrez les moulins, la bataille commencera.", progress = "Notre bataille contre le Fléau fait rage, <nom>. Faites votre part et rejetez ces satanés morts-vivants dans les Maleterres !", completion = "Vos exploits pendant la bataille sont célébrés parmi nous, &lt;nom&gt;. Je ne vous remercierai pas pour avoir accompli votre devoir, mais les gardes noirs de Tirisfal n'oublieront jamais votre nom.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes du marcheur des cryptesSolide pantalon en toile\n\nVous recevrez également :\n\n"},
[427] = {title = "En guerre avec la Croisade écarlate", objective = "Tuer 10 Guerriers écarlates pour l'Exécuteur Zygand.", description = "Les documents que l'Exécuteur Arren nous a apportés sont juste ce qui nous manquait pour notre bataille contre la Croisade écarlate. Nous savons maintenant où ils se trouvent dans les Clairières de Tirisfal.\n\nMais la Garde noire a d'autres soucis. L'armée du roi-liche s'accroît chaque nuit. Nous avons besoin de quelqu'un capable \"d'initiatives\" personnelles tel que vous pour s'occuper de la Croisade écarlate.\n\nProuvez-moi que vous êtes digne de servir la Dame noire ! Allez vers l'ouest jusqu'à la tour après la ferme des Solliden et tuez 10 guerriers écarlates.", progress = "Si vous désirez prouver votre valeur à la Dame noire, tuez 10 Guerriers écarlates, <classe>.", completion = "Vraiment excellent, &lt;classe&gt;. Vos talents de combattant sont indéniables.", rewards = "Vous recevrez :\n\n"},
[428] = {title = "Traqueurs noirs égarés", objective = "Trouver les Traqueurs noirs Quinn et Rane Yorick.", description = "Il y a quelques semaines, nos Traqueurs noirs, Rane et Quinn Yorick, ont été envoyés en mission de reconnaissance au nord des Pins argentés. Nul n'a plus entendu parler d'eux.\n\nIls ont peut-être été victimes du Fléau, mais si cela est vrai, j'aimerais en avoir la confirmation. Trouvez ces Traqueurs.\n\nLeur premier objectif était d'explorer les fermes au nord de la forêt. Vous devriez commencer par là.", progress = nil, completion = "Vous nous avez trouvés ! Il était temps…", rewards = "Vous recevrez :\n\n"},
[429] = {title = "Cœurs sauvages", objective = "Recueillir six Cœurs de worg et les apporter à l'Apothicaire Renferrel au Sépulcre.", description = "Mon frère Quinn a été gravement blessé par la goule Ivar l'Infect et je doute qu'il puisse guérir sans l'aide de la magie. Bien que je ne sois pas spécialiste de ces choses, je sais que nos Apothicaires savent concocter des remèdes à partir de cœurs décolorés de worgs.\n\nRecueillez quelques-uns de ces cœurs et portez-les à l'Apothicaire Renferrel au Sépulcre, au sud. Revenez ensuite avec la potion.\n\nVous trouverez des meutes de worgs entre ici et le verger de Malden, plus à l'est.", progress = "Je n'ai hélas que peu de temps, <classe>, car la Dame noire m'a chargé d'une mission de grande importance.", completion = "&lt;Renferrel s'empare des cœurs&gt;\n\nIl est troublant que nos Traqueurs noirs aient échoué dans leur mission.\n\nEspérons que ce genre d'échecs ne se reproduira plus.\n\nJe vous donnerai la potion dans un moment, mais voici déjà sa recette. Ainsi, si ces Traqueurs noirs avaient besoin d'aide à l'avenir, peut-être pourriez-vous la leur apporter vous-même.", rewards = "Vous recevrez :\n\nRecette : Potion de soins décoloréePotion de soins décolorée"},
[430] = {title = "Retour vers Quinn", objective = "Apporter le remède à Quinn Yorick au lopin d'Ivar, au nord du Sépulcre.", description = "Voici la potion qui guérira Quinn Yorick.\n\nMaintenant, si vous voulez bien m'excuser, j'ai un important travail à terminer...", progress = "Ma sœur prétend que vous êtes venu pour nous aider, est-ce vrai ?", completion = "&lt;Quinn prend la potion et la boit&gt;\n\nEn effet, je sens déjà les effets de ce breuvage. Je serai bientôt en mesure de voyager.\n\nVous m'avez rendu un immense service, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[431] = {title = "Bougies de signal", objective = "Vous vous emparez d'une bougie et la mettez dans votre sac.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBougie de signal"},
[432] = {title = "Ces satanés troggs !", objective = "Tuer 6 Brise-crânes Mâcheroc pour le contremaître Stonebrow à la carrière de Gol'Bolar.", description = "Ces satanés troggs sont en train de démolir mon lieu de travail, que la Lumière les brûle ! Regardez-moi ça : un nouveau baril de poudre qui part en fumée !\n\nOh ! Si seulement je pouvais y aller moi-même et tordre, l'un après l'autre, leurs petits cous décharnés ! J'aimerais les tuer tous !\n\nTout ce stress, cette colère... Cela n'est pas bon pour ma santé. Et qu'ont-ils laissé d'intact ? Rien !\n\nJe les massacrerais volontiers, mais je ne sais plus viser ! Allez donc dans la carrière et tuez quelques-uns de ces salopiauds ! Je vous paierai, mais faites-leur mal, détruisez-les !", progress = nil, completion = "Je me sens déjà un peu mieux...\n\nMais voilà, je ne serai soulagé que lorsqu'ils seront tous morts, absolument tous !", rewards = "Vous recevrez :\n\n"},
[433] = {title = "Le serviteur public", objective = "Tuer 10 Briseurs d'os Mâcheroc pour le sénateur Mehr Stonehallow à la carrière de Gol'Bolar.", description = "En tant que membre du Sénat et de la Ligue des Explorateurs, j'ai la charge de m'occuper des troggs qui infestent nos terres. Ils ont dévasté la carrière de Gol'Bolar, sans raison apparente. Comme nous forions profondément, ils ont jailli, détruisant notre équipement et chassant les mineurs. Nous n'avons d'autre solution que d'en exterminer un maximum, reconstruire et retourner au travail.\n\nSi vous m'aidez à nous débarrasser de ces troggs, je vous récompenserai en conséquence.", progress = "Si nous nettoyons la carrière de Gol'Bolar de ses troggs, nous aurons assurément fait un premier pas pour nous débarrasser de cette menace, mais la route sera longue.", completion = "C'est un début. Avec de la chance nous pouvons en profiter et engager quelques Montagnards pour sécuriser la zone. Ensuite nous pourrons restaurer nos infrastructures et le travail des mineurs reprendra normalement.\n\nMerci pour votre assistance, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[434] = {title = "L'attaque !", objective = "Rester dans le jardin jusqu'à ce que le seigneur Gregor Lescovar et Marzon Lame silencieuse aient eu leur conversation. Après, les tuer tous les deux puis retourner voir Elling Trias à Stormwind.", description = "Après avoir passé le déguisement à l'Espion, il entrera pour parler à Lescovar. Les gardes devraient le laisser passer sans problème.\n\nPendant que vous cherchiez le matériel pour moi, j'ai pris soin d'informer Marzon qu'il était temps de rencontrer à nouveau Lescovar. Je lui ai aussi glissé de fausses informations.\n\nLescovar congédiera ses gardes et attendra Marzon dans le jardin. Dès que vous entendrez parler des Defias, agissez. Vous devez les tuer tous les deux. C'est compris ?\n\nQuand cela sera fait, allez parler à Trias.", progress = nil, completion = "Alors, c'est fait ? Bien. Merci de votre discrétion, &lt;nom&gt;. Vous avez largement prouvé que l'on pouvait compter sur vous. Je vais garder un oeil sur vous et sur votre progression au sein de l'Alliance.\n\nN'allez rien faire de stupide.", rewards = "Vous recevrez :\n\n"},
[435] = {title = "Une escorte pour Erland", objective = "Escorter Erland jusqu'à Rane Yorick.", description = "Les loups ne partiront pas, et leurs yeux me fixent avec avidité dès que je fais un pas dehors. Ils doivent avoir une sacrée fringale pour penser que je suis comestible !\n\nJ'ai un rapport à remettre à mon équipier, le Traqueur noir Rane Yorick, mais il faudra d'abord se tailler une route à travers ces loups.\n\nEscortez-moi ! C'est une véritable meute qui attend dehors ; si vous appeliez des amis en renfort, nous doublerions nos chances de réussite...", progress = nil, completion = "Merci de votre aide, &lt;nom&gt;. Je craignais qu'Erland n'ait succombé aux dangers de la forêt. Grâce à vous, je me réjouis de voir que ce n’est pas le cas.", rewards = "Vous recevrez :\n\nEpée courte de Traqueur noir"},
[436] = {title = "Les fouilles d'Ironband", objective = "Parler à l'Explorateur Fellhew.", description = "Le Prospecteur Ironband dirige l’exploration de ruines à l'est du lac. Malgré notre approvisionnement, sa progression s'est ralentie dernièrement.\n\nIronband est un solide et honnête nain qui aime à faire du bon travail, c'est pourquoi je crains que des forces contraires soient à l'œuvre pour le ralentir.\n\nAllez aux fouilles d'Ironband et parlez à Magmar Fellhew. C'est lui qui gère le site, et il saura sûrement pourquoi le rythme de travail a décru.\n\nPour rejoindre les fouilles, contournez la pointe sud du lac, puis marchez droit vers l'est.", progress = nil, completion = "Jern aimerait savoir pourquoi l'exploitation s'est ralentie, hein ?\n\nIronband consigne dans son rapport les détails des derniers progrès, mais je peux déjà vous dire une chose :\n\nCe sont les troggs !", rewards = "Vous recevrez :\n\n"},
[437] = {title = "Le Champ des morts", objective = "Tuer des gnolls Poils-putrides au Champ des morts.\n\nDétruire Cinglenuit quand elle apparaît.\n\nRapporter son essence au Grand exécuteur Hadrec au Sépulcre.", description = "Nos premiers rapports de reconnaissance dans la forêt des Pins argentés indiquent que les Poils-putrides ont une base dans une vieille ferme, le Champ des morts. Nous les avons attaqués à plusieurs reprises, mais à chaque fois ils reçoivent l'assistance de la banshee Cinglenuit dont la magie désorganise et disperse nos forces.\n\nNous voulons la voir détruite.\n\nAllez dans le Champ des morts et attaquez les Poils-putrides. Si vous ne voyez pas la banshee, massacrez les Poils-putrides jusqu'à ce qu'elle apparaisse, puis tuez-la.\n\nSon essence même deviendra de la poussière. Rapportez-moi cette poussière comme preuve de sa destruction", progress = "Avez-vous vaincu Cinglenuit, <nom> ?  Notre victoire sur les Poils-putrides dépend de sa destruction !", completion = "La nouvelle de votre raid contre les Poils-putrides vous a précédé, &lt;nom&gt;, et cette essence est bien la preuve que Cinglenuit est morte.\n\nLe Fléau a perdu du terrain aujourd'hui. Votre valeur aux yeux des Réprouvés augmente.", rewards = "Vous recevrez :\n\nBottes de reconnaissance"},
[438] = {title = "Le bac délabré", objective = "Aller au bac délabré.\n\nChercher la raison de la présence du Fléau.", description = "<nom>, nous avons découvert une nouvelle infestation du Fléau : le bac délabré. Le bac se trouve à l'est du Sépulcre, et fourmille de patrouilles de Poils-putrides et autres morts-vivants.\n\nLe Fléau a sans doute une bonne raison pour occuper la zone. Allez au bac délabré et trouvez pourquoi le Fléau est là-bas.", progress = nil, completion = "Dans le bateau gisent des tas de corps enveloppés. En regardant à l'est, de l'autre côté du lac Lordamere, on peut apercevoir un quai sur l'île de Fenris.\n\nCes cadavres sont certainement destinés à finir sur l'île de Fenris.", rewards = "Vous recevrez :\n\n"},
[439] = {title = "Un indice vers les Poils-putrides", objective = "Rapporter la Bague de Deliah au Grand exécuteur Hadrec au Sépulcre.", description = "De la pile de corps dépasse une main de femme, marquée par la peste, mais encore relativement fraîche.\n\nUn doigt porte une bague. L'observation de cette bague révèle une inscription :\n\n\"Pour Deliah\"", progress = "<nom>. Vous êtes rentré, je suppose donc que vos investigations ont été fructueuses ?", completion = "Vous dites que cette bague était portée par une femme morte récemment ?\n\nCe corps ne peut provenir que des fosses communes de Tirisfal ! Les gnolls Poils-putrides sont certainement en train de convoyer ces corps sur l'île de Fenris !", rewards = "Vous recevrez :\n\n"},
[440] = {title = "La bague ciselée", objective = "Ramener la Bague de Deliah au Magistrat Sevren à Brill.", description = "Si vous voulez retrouver le mari ou l'amant qui a donné cette bague à Deliah, parlez au Magistrat Sevren à Brill.\n\nMais je n'entretiendrais pas d'espoir à votre place : celui qui a offert la bague est certainement mort à ce jour. Et s'il est devenu mort-vivant, il a oublié Deliah depuis longtemps.", progress = "Salut, <nom>. Quel bon vent vous ramène à Brill ?", completion = "Oui, une Deliah vivait à Brill il n'y a pas longtemps. Elle a été enterrée dans la fosse commune, mais si ce que vous dites est vrai, alors les gnolls Poils-putrides ont volé son cadavre pour le transporter aux Pins argentés.\n\nLes Poils-putrides, comme le Fléau, doivent être détruits. Je vous fais confiance pour qu'il en soit ainsi.", rewards = "Vous recevrez :\n\n"},
[441] = {title = "Raleigh et Undercity", objective = "Apporter la Bague de Deliah à Raleigh.", description = "Deliah avait un mari, Raleigh, qui maintenant habite à Undercity. Si la Deliah qui vivait à Brill est bien celle à qui appartient la bague, alors Raleigh le saura.\n\nRaleigh est dans le quartier des Marchands à Undercity.", progress = "On se connaît ?", completion = "En effet, c'est bien la bague de ma femme. Son destin a été celui des gens qui n'ont pas su supporter ces temps difficiles. Sa mort ne me peine même pas, pas plus que le vol de son cadavre.\n\nCe genre de sentiment a depuis longtemps gelé en moi. Mais un désir persiste dans mon cœur mort, &lt;nom&gt;.\n\nUn désir de vengeance.", rewards = "Vous recevrez :\n\n"},
[442] = {title = "L'attaque de l'île de Fenris", objective = "Rapporter la Tête de Thule au Grand exécuteur Hadrec au Sépulcre.", description = "Il est maintenant temps d'attaquer le bastion du Fléau dans les Pins argentés : l'île de Fenris.\n\nVous devez aller sur l'île et tuer Thule Ravenclaw. Apportez-moi sa tête !\n\nCette mission est aussi importante qu'elle est vitale, <nom>. Vous ne pouvez échouer.", progress = "Nous ne pouvons tolérer la présence du Fléau dans les Pins argentés plus longtemps, <nom>. Revenez quand vous aurez la preuve de la mort de Thule.", completion = "La mort de Thule Ravenclaw n'a pas été un événement négligeable, &lt;nom&gt;. Renferrel me dit que les énergies dégagées au moment où vous avez terrassé Thule ont été perçues jusqu'au Sépulcre. \n\nVos faits d'armes sont racontés dans les rangs des Réprouvés. Pour nous, votre valeur ne cesse de croître.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrande robe de l'adjudicateurEcorcheuse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[443] = {title = "L'ichor de Poil-putride", objective = "Rapporter 8 bouteilles d'Ichor de Poil-putride à l'apothicaire Renferrel.", description = "Avant que nous lancions notre offensive contre l'île de Fenris, nous devons déterminer qui dirige les gnolls Poils-putrides. Nos Apothicaires pensent que leur origine est liée au fluide étrange qui coule dans leurs corps.\n\nAllez sur l'île de Fenris, à l'est du Bac délabré, et collectez de lichor de Poil-putride sur les gnolls. Portez-le à l'apothicaire Renferrel, qui se trouve à l'extérieur du Sépulcre", progress = "Avez-vous de l'ichor de Poil-putride, <nom>?", completion = "Très bien. Cet ichor nous aidera à comprendre la nature profonde des Poils-putrides, et pourrait nous dévoiler leur faiblesse...\n\n… Si toutefois ils en ont une.", rewards = "Vous recevrez :\n\n"},
[444] = {title = "L'origine des Poils-putrides", objective = "Apporter l'Echantillon d'ichor à Bethor Iceshard à Undercity.", description = "J'ai réduit l'ichor que vous m'avez ramené et en ai séparé les principaux composants. Mes découvertes ne laissent aucun doute sur au moins un point : la magie des démonistes et des nécromanciens a été utilisée dans sa création.\n\nPendant que je pousserai mes recherches sur ce sujet, je veux que vous en apportiez un échantillon à Bethor Iceshard à Undercity. Bethor n'est pas un apothicaire, mais sa connaissance de la magie pourrait nous aider à comprendre le mystère des Poils-putrides.\n\nPartez ! Vous trouverez Bethor dans le Quartier de la magie d'Undercity.", progress = "Mon travail exige une grande concentration, j'espère que vous ne venez pas me déranger pour rien.", completion = "Cette substance est imprégnée de sorts puissants. Je n'ai pas vu certains depuis très longtemps...\n\nUn moment : je dois lancer un sort de divination...", rewards = "Vous recevrez :\n\n"},
[445] = {title = "Livraison dans la forêt des Pins argentés", objective = "Apporter les découvertes de l'Apothicaire Johaan à l'Apothicaire Renferrel dans la forêt des Pins argentés.", description = "Le temps n'est pas un luxe que peuvent s'offrir ceux qui travaillent pour Dame Sylvanas, mais vous le savez certainement.\n\nEn tant que membre de la Société royale des apothicaires, il est de mon devoir de partager mon savoir avec mes confrères afin que nos efforts conjoints puissent un jour offrir à la Dame noire cette Peste nouvelle qu'elle désire si ardemment.\n\nPortez ces découvertes à l'apothicaire Renferrel qui réside au Sépulcre dans la forêt des Pins argentés.", progress = "Qu'est-ce que vous voulez au juste, <classe>?", completion = "Ah, c'est une bonne chose que l'apothicaire Johaan me fasse envoyer ses découvertes. Avec tout ce qui arrive ici, j'en oublierais presque qu'on fait aussi des recherches hors de Lordaeron et des Clairières de Tirisfal. À propos, je devrai faire envoyer ces échantillons à la nécropole prochainement.\n\nMais vous devez excuser mes divagations. Restez donc quelques jours aux Pins argentés, &lt;nom&gt;. On a toujours besoin de mages compétents comme vous.", rewards = "Vous recevrez :\n\n"},
[446] = {title = "Thule Ravenclaw", objective = "Porter le parchemin de Bethor à l'Apothicaire Renferrel au Sépulcre des Pins argentés.", description = "Cet ichor a été créé par un vieux confrère : Thule Ravenclaw. C'était un jeune homme prometteur avant la Grande Guerre, mais quand le roi-liche vint au pouvoir, il trahit ses camarades en s'alliant au Fléau.\n\nJe n'avais pas réalisé qu'il était encore en vie, ni qu'il menait les Poils-putrides contre nous !\n\nJe connais beaucoup de ses sorts, et je peux aider à concocter une potion pour les contrer. Rapportez ce parchemin à l'apothicaire Renferrel. Il contient les incantations nécessaires à la potion.", progress = "Salutations, <nom>. Que raconte Bethor ?", completion = "Ce parchemin contient une magie puissante. Je n'ai encore jamais utilisé de telles forces dans une potion... Ce sera une mixture redoutable qui vous aidera lorsque vous attaquerez Thule dans son bastion de l'île de Fenris.", rewards = "Vous recevrez :\n\nPotion de Bethor"},
[447] = {title = "Une recette mortelle", objective = "Se rendre au Grouillement et y collecter 6 Cœurs de vieil ours et 6 échantillons de Sang du Grouillement, puis les apporter au maître apothicaire Faranell de la Société royale des apothicaires, à Undercity.", description = "Les troupes d'Arthas sont en nombre, mais avec une Peste nouvelle nous pourrions éradiquer à la fois l'armée du Fléau et les humains.\n\nMes études ont prouvé que du sang d'araignée associé à une toxine présente dans le cœur des vieux ours devient un élixir mortel. Collectez ces échantillons sur les araignées du Grouillement, au nord-ouest, et sur les ours qui arpentent la forêt des Pins argentés. Livrez ensuite ces ingrédients au maître apothicaire Faranell de la Société royale des apothicaires, à Undercity.", progress = "Salut, <classe>. Que voulez-vous de la Société royale des apothicaires ?", completion = "Il est bien que l'Apothicaire Renferrel vous envoie à moi, &lt;nom&gt;. Ces échantillons seront utiles à notre cause. Je vais commencer à étudier leurs propriétés toxiques sur-le-champ.", rewards = "Vous recevrez :\n\nRacine de Senggin"},
[448] = {title = "Un rapport pour Hadrec", objective = "Faire un rapport au Grand exécuteur Hadrec au Sépulcre.", description = "Avant que vous n'attaquiez l'île de Fenris, faites un rapport au Grand exécuteur Hadrec. Il aura sans doute les informations et l'équipement complémentaires dont vous aurez besoin.", progress = nil, completion = "Si Bethor dit vrai, alors Thule Ravenclaw est un problème dont il faut s'occuper le plus vite possible.\n\nIl y a dans notre arsenal deux ou trois choses qui pourraient vous aider dans cette mission...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCaillou grossierPierre à aiguiser grossière\n\nVous recevrez également :\n\nRenfort d'armure moyen"},
[449] = {title = "Le rapport des Traqueurs noirs", objective = "Apporter le rapport du Traqueur noir au Grand exécuteur Hadrec au Sépulcre.", description = "Bien que les blessures de Quinn soient en train de guérir, je veux que notre rapport parvienne au Grand exécuteur Hadrec le plus vite possible. Il contient des informations vitales pour maintenir l'occupation de la forêt des Pins argentés par les Réprouvés.", progress = "Avez-vous découvert ce qui est arrivé aux Traqueurs noirs ?", completion = "Je n'avais pas compté avec une telle présence du Fléau dans la forêt des Pins argentés, ni avec les difficultés que nos Traqueurs noirs rencontreraient lors de leurs reconnaissances.\n\nL'aide que vous avez apportée à nos Traqueurs noirs fut inestimable, &lt;nom&gt;. Vous serez justement récompensé.", rewards = "Vous recevrez :\n\n"},
[450] = {title = "Une recette mortelle", objective = "Récupérer le Journal de Berard à l’Auberge de Bois-du-Bûcher et le rapporter à l'apothicaire Renferrel au Sépulcre.", description = "Vous pouvez encore être utile à la Société royale des apothicaires, <nom>.\n\nQuand Arugal a jeté sa misérable magie sur la forêt, il a maudit l'un de nos membres les plus prometteurs, l'apothicaire Berard. Devenu un serviteur décérébré d'Arugal, Berard ne nous sert plus à rien, mais ses découvertes pourraient être utiles. Il étudiait une ancienne peste qui a décimé toute la faune aquatique du lac de Lordamere, il y a longtemps.\n\nRécupérez le Journal de Berard dans son bureau à l'auberge de Bois-du-Bûcher et rapportez-le à l'Apothicaire Renferrel.", progress = "Je vois que vous êtes rentré, <nom>.", completion = "Le journal de l'apothicaire Berard ! Vous avez été courageux, &lt;nom&gt;. Voyons où en étaient les recherches de Berard avant qu'il ne perde la raison…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[451] = {title = "Une recette mortelle", objective = "Apporter 6 Echantillons de Mousse de Rampant du lac, 6 échantillons de Mousse de Furtif du lac et une Tumeur durcie au Maître Apothicaire Faranell à Undercity.", description = "D'après le journal de Berard, la mousse de Furtifs et de Rampants du lac pourrait intervenir dans la composition d'une Peste nouvelle. Ces bêtes vivent sur les îles du lac de Lordamere, à l'est.\n\nLe journal évoque aussi une rarissime Tumeur durcie qu'il a découverte sur un murloc Aileron noir. Apparemment cette tumeur est tellement rare que Berard n'a pu en prélever qu'une.\n\nRecueillez des échantillons de mousse ainsi que de la Tumeur durcie et rapportez-les au Maître Apothicaire Faranell à Undercity.", progress = "Qu'est-ce qui vous ramène à Undercity, <nom> ?", completion = "C'est un coup dur pour la Société royale des apothicaires d'avoir perdu Berard. Mais grâce à votre excellent travail et aux recherches assidues de l'apothicaire Renferrel, les études de Berard ne sont pas perdues et serviront la cause difficile de la Dame noire.\n\nNous avons là de quoi faire quelque chose d'important, &lt;nom&gt;. Si vous n'aviez pas ce talent pour le combat, j'essaierais sans doute de faire de vous un membre de la Société..", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDécoction de lueur nocturneCape résistante à l'acide\n\nVous recevrez également :\n\nElixir de Robustesse mineurePotion de rapidité"},
[452] = {title = "Embuscade à Bois-du-Bûcher", objective = "Aider le Traqueur noir Faerleia à tuer les Membres du Conseil de Bois-du-Bûcher.", description = "Vous avez fait vite, <nom> !\n\nLes Conseillers de Bois-du-Bûcher vont revenir dans un instant. Arugal utilise les membres du Conseil comme autant de marionnettes pour garder la main mise sur le village. Mais je pense que sans le Conseil, les partisans d'Arugal se retourneraient contre leur maître.\n\nJe ne peux faire cela toute seule, j'ai besoin de votre aide. Ensemble, nous dévasterons le Conseil au nom de Dame Sylvanas.", progress = nil, completion = "Vous avez combattu tel un véritable disciple de la Dame noire, &lt;nom&gt;. Le Conseil détruit, peut-être pouvons-nous prendre le contrôle de cette ville une fois pour toutes et chasser Arugal du donjon d'Ombrecroc. Je vous salue !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier de FaerleiaPantalon en cuir étiréChâle mystique\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[453] = {title = "À la recherche de l'Obscure Silhouette", objective = "Retrouver l'Obscure Silhouette. Indices :\n\nIl n'est pas né à Darkshire.\n\nC'est un individu nerveux et craintif.\n\nIl a quitté Darkshire pour faire route vers l'ouest.", description = "Bonne chance, <nom>. J'espère que vous retrouverez le bonhomme, et vivant si possible.\n\nS'il a fui la sécurité de Darkshire, il pourrait être la proie des bêtes sauvages.", progress = "Qui êtes-vous ? Laissez-moi tranquille !", completion = "&lt;La Tremblotte soupire...&gt;\n\nOui, je suis bien l'auteur de ce livre. Vous m'avez r'trouvé, hein ?\n\nVous avez lu ce journal... mais croyez pas qu'vous savez tout !", rewards = "Vous recevrez :\n\n"},
[454] = {title = "Après l'embuscade", objective = "Parler à Miran.", description = "Avant toute cette...histoire, nous étions en train de convoyer les barils de poudre. Mais maintenant nous devons répartir les tâches, Miran prenant les barils et moi veillant sur les autres.\n\nJe n'aime pas l'idée que Miran transporte le reste de la cargaison tout seul. Pourriez-vous l'escorter quand il sera prêt à partir ?", progress = nil, completion = "Bonjour, &lt;classe&gt;.\n\nVous allez m'escorter jusqu'au site de fouilles ? C'est une bonne nouvelle... Après Saean et ses compères, qui sait quels tours les Sombrefer ont encore dans leur sac ?\n\nEnfin, laissez-moi vérifier deux trois choses. Faites-moi signe quand vous serez prêt à partir.", rewards = "Vous recevrez :\n\n"},
[455] = {title = "Le défi d'Algaz", objective = "Traverser Dun Algaz.\n\nTuer 8 Eclaireurs Dragonmaw et 6 Grunts Dragonmaw.\n\nFaites votre rapport à Valstag Ironjaw au port de Menethil.", description = "Les orcs du clan Dragonmaw ont un refuge dans les Paluns. Mais voilà : ils se répandent maintenant dans Dun Algaz ! Nous ne pouvons les laisser s'installer là, sinon le Loch Modan sera coupé du port de Menethil, notre port et bastion dans les Paluns.\n\nTraversez Dun Algaz jusqu'aux Paluns et tuez quelques orcs pour faire bonne mesure! Faites un rapport à Valstag Ironjaw au port de Menethil.\n\nPour rejoindre Menethil, passez par Dun Algaz, puis allez au nord en longeant la route, et enfin prenez à l'ouest à l'embranchement.\n\nNous comptons sur vous, <nom>. Vous ne pouvez échouer.", progress = nil, completion = "Votre rapport n'est que mauvaises nouvelles !\n\nJe constate que les Dragonmaw font mouvement vers Algaz. Normalement ils se cachent dans les collines. Pourquoi se ruent-ils sur Algaz ? C'est encore un mystère...\n\nMerci, &lt;nom&gt;. Nous aurons certainement besoin de votre aide pour traiter le problème des orcs.", rewards = "Vous recevrez :\n\n"},
[456] = {title = "L'Equilibre de la nature", objective = "Tuer 7 Jeunes sabres-de-nuit et 4 Jeunes sangliers des chardons, puis retournez voir le Conservateur Ilthalaine.", description = "Salutations, <nom>. Je suis le Conservateur Ilthalaine. Mon rôle à Sombrevallon est de m'assurer que l'équilibre naturel est maintenu.\n\nLes pluies printanières furent particulièrement abondantes cette année, et certains animaux de la forêt en ont profité pour prospérer quand d'autres ont dépéri.\n\nMalheureusement la population des sabres-de-nuit et des sangliers des chardons s'est trop accrue. Sombrevallon ne peut produire plus d'une quantité donnée de nourriture pour les animaux. En route, jeune <classe>, réduisez la population des sabres-de-nuit et des sangliers des chardons afin de garantir l'harmonie de la nature.", progress = nil, completion = "Vous avez fait du bon travail, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants d'entraînement d'archerBrassards en tiges entrelacées\n\nVous recevrez également :\n\n"},
[457] = {title = "L'Equilibre de la nature", objective = "Le Conservateur Ilthalaine voudrait que vous tuiez 7 Sabres-de-nuit galeux et 7 Sangliers des chardons.", description = "Réguler les populations d'animaux à Sombrevallon est un bon début <nom>, mais il y a encore beaucoup à faire.\n\nLes ressources forestières seront bientôt épuisées si nous ne réglons pas rapidement le problème. Tuer les créatures de la nature est parfois un mal nécessaire pour le bien de tous ceux qui partagent cette terre. Aventurez-vous dans la forêt et éliminez les sabres-de-nuit et les sangliers des chardons malades, au nom de l'équilibre naturel.", progress = nil, completion = "Vous avez prouvé votre allégeance à la Nature de belle façon, &lt;nom&gt;. Les jeunes druides comme vous ont un avenir prometteur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape drapéeCeinture en cuir noirci\n\nVous recevrez également :\n\n"},
[458] = {title = "La Protectrice sylvestre", objective = "Chercher la dryade connue sous le nom de Tarindrella.", description = "Louée soit la Nature, vous êtes là, <classe> ! D'étranges rumeurs sont parvenues jusqu'à moi par l'entremise des esprits de la forêt.\n\nLa mystérieuse Protectrice sylvestre, Tarindrella, est rentrée à Sombrevallon. Cette dryade n’est pas venue dans les forêts de Kalimdor depuis des années. Il y a sûrement quelque chose qui cloche pour motiver son retour.\n\nCherchez Tarindrella et voyez ce qui l'occupe en ce moment. Une des Sentinelles dit l'avoir vue au sud-ouest d'Aldrassil.", progress = nil, completion = "Je vois que vous m'avez trouvée, jeune &lt;nom&gt;. Melithar est un &lt;classe&gt; avisé pour vous avoir envoyé.", rewards = "Vous recevrez :\n\n"},
[459] = {title = "La Protectrice sylvestre", objective = "Collecter 8 Gangremousses et les rapporter à Tarindrella.", description = "Quelque chose de malfaisant se développe dans les forêts de Teldrassil. Allez dans les collines où les paisibles furbolgs avaient habitude de vivre. Ils ont quitté leurs foyers et se regroupent maintenant, sous le nom de tribu des Pins-tordus.\n\nSeule la contamination par les pernicieuses gangremousses a pu provoquer ce changement. Les grells et les grellides ont infesté la zone et menacent les habitants de Sombrevallon.\n\nAttaquez ces grells et ces grellides, <nom>, et voyez s'ils sont tombés sous l’influence des Mousses corrompues.", progress = "Confirmez mes soupçons, <nom>. Rapportez-moi 8 Gangremousses.", completion = "Votre aide aux créatures de Sombrevallon mérite une récompense, &lt;nom&gt;.\n\nMes craintes sont néanmoins confirmées. Si les grells ont été infestés par la gangremousse, je n'ose imaginer le sort des furbolgs Pins-tordus.\n\nSi jamais vous voyagez jusqu'à Dolanaar, digne &lt;classe&gt;, n'oubliez pas d'y chercher le sage druide Athridas Bearmantle. Il partage notre souci du bien-être des forêts.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières de la canopéeBottes de pistageGants de Viny\n\nVous recevrez également :\n\nHerbe de soins"},
[460] = {title = "Reposer en… pièces", objective = "Apporter la tête d'Alaric jusqu’à sa tombe.", description = "Vous n'avez pas l'air d'un Poil-putride. C'est déjà ça. J'avais perdu espoir...\n\nMon nom est Alaric, j'étais naguère le serviteur et garde du corps de Thule. Il a tenté d'utiliser sa magie pour me \"protéger\" du Fléau mort-vivant, mais en fait, son sort m’a donné une forme de mort-vivant. Après avoir créé les maudits Poil-putride, Thule m’a décapité et donné ma tête aux gnolls pour qu'ils jouent avec !\n\nJe vous supplie de me ramener près de mon corps. Je suis sûr que les gnolls l'ont enterré ici, au donjon de Fenris, près des étables, dans une tombe anonyme.", progress = "Cette tombe a été creusée à la va-vite.", completion = "Merci, &lt;nom&gt;. J'avais peur que les gnolls aient détruit mon corps. Je suis heureux de voir qu'ils ne l'ont pas fait.", rewards = "Vous recevrez :\n\n"},
[461] = {title = "L’alcôve secrète", objective = "Amener Alaric à l’alcôve secrète.", description = "Je connais une alcôve secrète dans le donjon, qui contient un objet cher à Thule et ses anciens confrères. Il y a également quelque chose qui pourrait vous servir. Amenez-moi sur place !\n\nL’alcôve se trouve dans la tour la plus au sud-ouest du donjon, derrière une étagère poussiéreuse.\n\nPrenez mon corps, mais laissez mes bottes. De toute façon elles ne m'allaient pas...", progress = "Nous y voilà ! Approchons-nous encore…", completion = "Voilà, c'est ouvert. Laissez-moi ici. J'ai passé mes meilleures années dans ce donjon et l'idée de reposer entre ses murs me réconforte.\n\nAssurez-vous de bien refermer l'alcôve, je ne veux pas que ces Poils-putrides me trouvent.\n\nOh, à propos, prenez ça, vous l'avez largement mérité.", rewards = "Vous recevrez :\n\n"},
[463] = {title = "Le Gouverneur vert", objective = "Trouver le Gouverneur vert.", description = "Avez-vous entendu parler du Gouverneur vert ? Vous ne le cherchez pas, n'est-ce pas ? Je dirais que vous êtes <fou/folle> si c'est le cas, mais qui suis-je pour empêcher <un illuminé/une illuminée> de courir à sa mort ?\n\nSi vous cherchez le monstre, je crois qu'il hante les marécages à l'est de la route où il y a l'embranchement pour Dun Modr. Il est tapi là-bas, parmi les crocilisques et de choses pires encore !\n\nEt puis, laissez donc votre argent ici ; il ne vous servira à rien où vous allez. Vous ne voulez pas non plus que le Verdâtre s'ébrèche les dents sur votre or quand il vous coupera en deux ?", progress = nil, completion = "Je vous ai entendue aller à travers les racines et les fougères, petite créature. Bien que j'aie beaucoup de noms, vous pouvez m'appeler Rethiel.\n\nÉcoutez attentivement : ces terres pleurent leurs blessures, et vous pourriez vous charger de les guérir.", rewards = "Vous recevrez :\n\n"},
[464] = {title = "Bannières de guerre", objective = "Rapporter 8 Bannières de guerre Dragonmaw au capitaine Stoutfist.", description = "Le clan des orcs Dragonmaw fut pratiquement anéanti à la fin de la Deuxième Guerre après qu'ils eurent perdu le contrôle de leurs dragons rouges. Les dragons n'étaient pas contents de leurs anciens maîtres et ont sauvagement traqué les Dragonmaw. Les quelques survivants ont fui de Grim Batol dans les montagnes jusqu’à l'est de l'Excavation de Whelgar.\n\nMaintenant ils ont repris des forces et campent au nord-est de Menethil.\n\nNous voulons que vous attaquiez leur campement. Vous rassemblerez et me rapporterez leurs bannières de guerre comme preuve de leur destruction.", progress = "Avez-vous attaqué le campement Dragonmaw ?", completion = "Beau combat, &lt;nom&gt;. Les Dragonmaw ne sont plus les combattants qu'ils étaient quand ils avaient les dragons avec eux, mais ils restent de redoutables adversaires.\n\nIls sont menés par Nek'rosh, fils de Nekros qui était le précédent chef du clan, il y a plusieurs années. Nekros utilisait une puissante magie pour dominer les dragons rouges, mais lorsque cette magie vint à lui échapper, les dragons se retournèrent contre lui.\n\nNekros fut tué et son fils fit serment de le venger des dragons qui l'avaient massacré..", rewards = "Vous recevrez :\n\n"},
[465] = {title = "La manœuvre de Nek'rosh", objective = "Détruire les Catapultes Dragonmaw.", description = "Pendant que vous combattiez les Dragonmaw, nous avons percé à jour certains de leurs plans.\n\nNek'rosh a fait construire des catapultes et projette d'assiéger Menethil ! Et avec les combats à Dun Algaz, nous sommes coupés des renforts !\n\nVous devez détruire ces catapultes. Elles sont au campement des Dragonmaw.\n\nVoici, prenez ce combustible. Taillez-vous une route à coups d'épée jusqu'aux catapultes, puis brûlez-les à l'aide du combustible.\n\nAprès, trouvez et tuez Nek'rosh. Rien ne nous plairait plus que d'avoir la tête de cette engeance Dragonmaw au bout d'une pique...", progress = "La première catapulte est devant vous, allez-vous la brûler ?", completion = "Vous placez le combustible sur la catapulte et produisez une étincelle.\n\nLes flammes jaillissent et gagnent rapidement !", rewards = "Vous recevrez :\n\n"},
[466] = {title = "À la recherche de l'incendicite", objective = "Apporter 6 Chargements d’Incendicite au Pilote Stonegear à Dun Morogh.", description = "J'ai appris qu'il existait un minerai rare, l'incendicite, dans les Paluns, dans une grotte au nord-ouest de la Porte d'Algaz. C’est un produit assez volatil, il explose à la moindre mauvaise manipulation ! Mais je suis sûr que correctement extrait, on pourrait l'utiliser pour donner un sacré punch aux obus de canon !\n\nApportez-moi de l'incendicite et je trouverai bien quelqu'un pour l'expérimenter.\n\nAh ! Et pour extraire ce minerai vous devez avoir la Compétence de Minage. Si vous ne l'avez pas, alors... amenez un ami qui la connaisse !", progress = "Où est ce minerai, <nom> ?!", completion = "Vous avez le minerai ! Beau travail, &lt;nom&gt; ! Je vais mettre quelqu'un à son étude de suite, en espérant qu'il ne se fasse pas sauter !", rewards = "Vous recevrez :\n\nGants tachés de bière"},
[467] = {title = "La quête de Stonegear", objective = "Parler au Pilote Stonegear.", description = "Le pilote Stonegear adore ses engins de siège, comme il se doit ! Et il est toujours avide d'informations lui permettant d'apporter des améliorations techniques à ses chars !\n\nIl a entendu parler d'un minerai rare et cherche quelqu'un pour aller en collecter pour lui. Si vous aimez marcher, allez trouver Stonegear au dépôt de Steelgrill à Dun Morogh, et voyez ce dont il a besoin.", progress = nil, completion = "Salut &lt;nom&gt;. Vous êtes candidat pour aller chercher ce dont j'ai besoin, hein ? Il est bon de voir un jeune &lt;race&gt; comme vous dont le sang bout à l'idée d'une mission !", rewards = "Vous recevrez :\n\n"},
[468] = {title = "Un rapport pour le Montagnard Rockgar", objective = "Parler au Montagnard Rockgar.", description = "Le Montagnard Rockgar cherche des volontaires pour une mission dans Dun Algaz et les Paluns.\n\nSi vous voulez mouiller vos bottes dans cette terre détrempée au nord, allez parler à Rockgar à Dun Algaz. Dun Algaz est plus au nord sur la route, après la Tour de garde.", progress = nil, completion = "Salut, &lt;classe&gt; ! Vous êtes ici pour le boulot d'éclaireur, non ? Bien !\n\nJ'espère que votre équipement est au point, parce que cette mission de \"reconnaissance\" sera tout sauf une partie de plaisir...", rewards = "Vous recevrez :\n\n"},
[469] = {title = "Livraison quotidienne", objective = "Apporter le Lot de peaux de crocilisques à James Halloran, le tanneur, au port de Menethil.", description = "Bonjour !\n\nVous n’iriez pas vers Menethil, par hasard ? Sinon, vous pouvez faire halte ici, c'est un bon endroit pour faire des achats ou prendre une pinte de bière.\n\nMais si vous allez tout de même à Menethil, vous pourriez peut-être apporter ce lot de peaux de crocilisques à James Halloran, le tanneur ?\n\nJe pourrais le faire moi-même, mais ma femme est d’une méchante humeur en ce moment, et j’aimerais autant éviter de la contrarier.", progress = "Bonjour, <classe>. N'êtes-vous pas intéressé par une paire de bottes ? Peut-être par des peaux fraîchement traitées ?", completion = "Hum ! Cela vient d'Einar, non ? Il ne m'a pas livré de peaux depuis presque une semaine. Je gage qu'il doit être retenu par sa femme !\n\nPeut-être faudrait-il que j'envoie la mienne causer avec Sidonie, un de ces jours...", rewards = "Vous recevrez :\n\n"},
[470] = {title = "En creusant dans la vase", objective = "L'un des Limons dans le Tombeau d'Ironbeard a le sac de Sidonie. Le retrouver et le lui rapporter au Port de Menethil.", description = "A l'occasion de ma visite hebdomadaire au Tombeau d'Ironbeard, j'ai été attaquée par de redoutables Limons visqueux ! Naturellement, j'ai paniqué.\n\nJ'ai jeté mon sac sur l'un d'eux, qui l'a littéralement aspiré, ce qui m'a laissé le temps de m'enfuir.\n\nLa mauvaise nouvelle, c’est que j'ai absolument besoin du contenu de mon sac !\n\nEt je ne sais pas sur quel Limon je l'ai jeté : ils se ressemblent tous ! Le Tombeau d'Ironbeard est au nord-est, près de Dun Modr. Merci mille fois !", progress = "Avez-vous retrouvé mon sac ?", completion = "Oh merci, &lt;nom&gt; ! Je craignais de l'avoir perdu pour de bon !\n\n\n\nEuh ! Je n'ai plus besoin de cela maintenant, mais si vous le laviez, vous pourriez en avoir l'usage.", rewards = "Vous recevrez :\n\nSac couvert de vase"},
[471] = {title = "Les devoirs de l'apprenti", objective = "Collecter 6 Peaux de crocilisque géant, et les apporter à James Halloran, au port de Menethil.", description = "J'ai envoyé mon apprenti dans les marécages pour chasser les fameux crocilisques géants des Paluns. Comme il ne revenait pas, je suis parti à sa recherche et l'ai retrouvé. Tout ce que je peux dire c'est que ce n'était pas... plaisant à regarder.\n\nLa rebouteuse dit qu'il va s'en sortir, mais entre-temps, j'ai toujours besoin de mes peaux !\n\n... Si vous tuiez quelques-uns de ces monstres, je n'y ferais aucune objection ; après ce qu'ils ont fait... Vous trouverez les crocos au nord de la côte, derrière les taudis des murlocs.", progress = "Mon apprenti est comme un fils pour moi. Ça va être dur pour lui de vivre avec une seule jambe.\n\nAh, <nom>, comment ça va ? Avez-vous mes peaux ?", completion = "Hum... Vous ne voudriez pas devenir mon apprenti ?\n\nAllons, je plaisantais. Vous êtes trop âgé, pour commencer. De plus, à vous voir vous semblez avoir d'autres ambitions dans la vie. Vous avez néanmoins rapporté de bien belles peaux dont je saurai faire bon usage.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières en mailles de l'apprentiPoncho de résistance\n\nVous recevrez également :\n\nRecette : Gombo de crocilisque"},
[472] = {title = "La chute de Dun Modr", objective = "Rechercher Longbraid dans les parages du village de Dun Modr.", description = "Dun Modr est tombé aux mains des nains Sombrefer !\n\nMes blessures sont sérieuses, <classe>. Mon régiment a été pratiquement décimé ! Ces brutes de Sombrefer nous ont attaqués avant que nous puissions nous regrouper après l'embuscade du viaduc de Thandol.\n\nNotre chef, Longbraid, a sonné la retraite. Comme nous quittions la ville, j’ai reçu une hache dans le dos. Un voile noir s'est abattu devant mes yeux.\n\nJe me suis réveillé ici, en sécurité à Menethil, mais j'ai peur pour mes compagnons. L'espoir ne m'a pas encore abandonné. Peut-être Longbraid est-il encore vivant ! <nom>, voyez si vous pouvez le retrouver, pas loin du village de Dun Modr !", progress = nil, completion = "Lequel de ces braves guerriers nous arrive de Menethil ? &lt;nom&gt;, c'est ainsi qu'on vous appelle ?\n\nVous apportez de l'espoir, dans une situation désespérée. Je suis vraiment heureux d'apprendre que le jeune Harlo a survécu. En fuyant, il a été gravement blessé. Nous avons juste eu le temps de le renvoyer sur le dos du dernier coursier du régiment.\n\nMais maintenant nous devons faire face à une situation périlleuse. Dun Modr est tombé et nous ne sommes plus que l'ombre du valeureux régiment que nous étions jadis.", rewards = "Vous recevrez :\n\n"},
[473] = {title = "Un rapport au capitaine Stoutfist", objective = "Parler au capitaine Stoutfist.", description = "<nom>. Le clan des orcs Dragonmaw montre sa puissance bien au-delà d'Algaz. Le capitaine Stoutfist a demandé à parler à tous ceux qui sont prêts à s'engager contre ces orcs. Il est à l'intérieur du donjon, dans la salle de guerre.", progress = nil, completion = "&lt;nom&gt;. Valstag m'a parlé de vos victoires passées sur les orcs Dragonmaw à Dun Algaz. J'ai rarement vu un &lt;race&gt; aussi valeureux !\n\nEt j'ai une mission pour vous.", rewards = "Vous recevrez :\n\n"},
[474] = {title = "Vaincre Nek'rosh", objective = "Tuer le Chef Nek'rosh\n\nRapporter la tête de Nek'rosh au capitaine Stoutfist.", description = "Maintenant que les catapultes ont été détruites, trouvez et exécutez le Chef Nek'rosh.", progress = "Avez-vous tué Nek'rosh?", completion = "Bravo, &lt;nom&gt;. Vous avez porté un coup magistral aux orcs Dragonmaw. Ils pourraient ne pas s'en relever. De plus, les catapultes brûlées, le port de Menethil n'a plus rien à redouter.\n\nVous êtes un &lt;race&gt; de grand mérite. Le royaume d'Ironforge sait récompenser ceux qui le servent loyalement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAncienne épée de guerreDésosseuse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[475] = {title = "Une brise étrange", objective = "Chercher Gaerolas Talvethren au village de Brise-stellaire.", description = "Une brise étrange souffle à travers la forêt.\n\nGaerolas Talvethren est le Grand gardien des druides de la Serre qui hibernent dans le Refuge des saisons de Ban'ethil. Son devoir en tant que protecteur des Dormants est de veiller à leur sécurité, afin que le pacte avec Ysera ne soit pas rompu.\n\nMais je n'ai toujours pas de nouvelles de Gaerolas. Allez à l'est, au village de Brise-stellaire et revenez avec des nouvelles de Gaerolas, que je puisse calmer mes craintes en apprenant que mon vieux camarade est sain et sauf.", progress = nil, completion = "Par les Esprits de la forêt, vous êtes là ! Je savais qu'Athridas sentirait qu'il y a un problème et qu'il enverrait de l'aide.", rewards = "Vous recevrez :\n\n"},
[476] = {title = "La corruption des Pins-tordus", objective = "Retourner auprès d'Athridas Bearmantle à Dolanaar.", description = "La tribu des Pins-tordus a été corrompue !\n\nLes furbolgs, jadis paisibles, se sont retournés contre les protecteurs de la forêt. Ils m'ont tendu une embuscade tandis que je partais pour le Refuge des saisons de Ban'ethil, puis ils ont pillé le village de Brise-stellaire. Ursal le Mutileur, leur chef, utilise les pouvoirs malfaisants des gangremousses pour les rendre fous.\n\nJe suis trop gravement blessé pour aller voir Athridas et lui communiquer ces graves nouvelles. Cette tâche vous incombe à présent, jeune <classe>. Nous n'avons plus qu'à espérer que les Pins-tordus ne sont pas encore arrivés jusqu'à Ban'ethil !", progress = nil, completion = "Par les étoiles ! C’est vraiment troublant !", rewards = "Vous recevrez :\n\n"},
[477] = {title = "Frontières", objective = "Récupérer le contenu de l’une des caisses des Sorciers de Dalaran. Vous trouverez Bois-du-Bûcher au sud.", description = "Comme vous devez le savoir, Moulin-de-l'Ambre reste un bastion de l'opposition humaine. La ville est soutenue par les Sorciers de Dalaran qui l’approvisionnent.\n\nJe ne connais pas leurs plans, mais s'ils portent autant d'intérêt à ce trou perdu, c'est que cela doit être de première importance.\n\nIls transportent quantité de caisses depuis Hillsbrad. Beaucoup de ces convois ont pour terminus un petit camp au nord du village de Bois-du-Bûcher. Récupérez le contenu de l'une de ces caisses et apportez-le moi.", progress = nil, completion = "&lt;En soulevant le couvercle de la caisse, vous voyez un assortiment d'objets soigneusement empaquetés. Sur le dessus, il y a de vieilles cartes jaunies qui semblent représenter la forêt des Pins argentés et d'autres régions de l'ouest de Lordaeron.\n\nSous les cartes, vous découvrez un pendentif magique d'aspect mystérieux.&gt;", rewards = "Vous recevrez :\n\n"},
[478] = {title = "Des cartes et des runes", objective = "Apporter l'étrange pendentif au prêtre des ombres Allister au Sépulcre.", description = "<Vous retirez rapidement le Pendentif de la caisse et rabattez le couvercle.>", progress = "Avez-vous appris quelque chose d'intéressant, <nom> ?", completion = "Des cartes et ce... pendentif, hum ! Intéressant.\n\nIl est évident que les Sorciers de Dalaran portent de l'intérêt à Moulin-de-l'Ambre, mais leurs objectifs restent obscurs.\n\nPeut-être Dalar pourrait-il nous en dire plus.", rewards = "Vous recevrez :\n\n"},
[479] = {title = "Enquête à Moulin-de-l'Ambre", objective = "Récupérer 8 Pendentifs de Dalaran pour le prêtre des ombres Allister du Sépulcre.", description = "Dalar essaie de localiser la source de la magie des sorciers. Pour l'heure, nous devons nous efforcer de ralentir leurs progrès...\n\nIl ne fait aucun doute que les conjurateurs, les mages et les protecteurs portent ces pendentifs. Récupérez-en.\n\nSuivez la route principale au sud, puis prenez à l'est à l'embranchement qui conduit à Moulin-de-l'Ambre.", progress = "Nous devons nous hâter de contrecarrer leurs plans avant qu'ils ne les finalisent ou nous perdrons notre emprise sur la forêt des Pins argentés.", completion = "Dalar a découvert que le tressage était déjà bien avancé, malgré le contretemps.\n\nUn Sorcier de grand pouvoir contrôle l'énergie magique. Il faut l'arrêter au plus vite.", rewards = "Vous recevrez :\n\n"},
[480] = {title = "Le Tisserand", objective = "Tuer l'archimage de Dalaran, puis récupérer son Bâton pour le prêtre des ombres Allister du Sépulcre.", description = "Un archimage de grand pouvoir supervise la réactivation du nœud d'énergie Ley. Vu les progrès qu'ils ont faits, notre seule chance de les arrêter est de tuer cet archimage. Ce sera difficile, car il est certainement protégé par d'autres mages et gardiens.\n\nVous devez partir et le neutraliser au plus vite. Quand il sera mort, récupérez son Bâton et apportez-le-moi. En avant !", progress = "Vite, <nom>, le temps nous est compté !", completion = "La magie des sorciers se dissipe et l'énergie Ley retombe. Vos efforts ont été fructueux, &lt;nom&gt;, et nous avons porté un coup rude à nos ennemis et aux sorciers dominateurs de Dalaran.\n\nNous devons néanmoins rester vigilants, sachant que la source d'énergie est toujours à portée de main... Il nous faut un plan pour des actions futures.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâtonnet de céraniumTunique camouflée\n\nVous recevrez également :\n\n"},
[481] = {title = "L'analyse de Dalar", objective = "Apporter le Pendentif marqué de runes à Dalar Dawnweaver au Sépulcre.", description = "Apporter le Pendentif à Dalar Dawnweaver. Peut-être pourra-t-il anticiper les plans des Sorciers.", progress = "Oui, <classe> ? De quoi s'agit-il ?", completion = "Intéressant, encore des machinations du Kirin Tor, à ce qu'il semble. Ceci est un artefact puissant. Il était fréquemment utilisé par les influents Sorciers du Kirin Tor pour canaliser les énergies magiques.\n\nQu'ils en livrent autant à Moulin-de-l'Ambre indique qu'ils prévoient des actions de grande envergure.\n\nJe vais voir si je peux percer à jour leurs projets..", rewards = "Vous recevrez :\n\n"},
[482] = {title = "Les intentions de Dalaran", objective = "Parler au prêtre des ombres Allister au Sépulcre.", description = "Bien sûr ! Comment ai-je pu oublier ?\n\nMoulin-de-l'Ambre était l'un des sites de prédilection pour le Kirin Tor, célèbre pour abriter des nœuds dormants d'énergie Ley. Les Sorciers doivent projeter de réactiver les nœuds et d'utiliser cette énergie pour quelque grande œuvre.\n\nNous ne pouvons laisser faire...\n\nIls vont avoir besoin de beaucoup de puissance pour activer les zones d'énergie Ley et nous pouvons enrayer le processus en volant leurs Pendentifs aux Sorciers.\n\nRapportez cette information à Allister, il décidera de la suite.", progress = nil, completion = "Ce sont de mauvaises nouvelles que vous apportez, &lt;nom&gt;. Si Dalar a raison – et je ne vois pas pourquoi il se tromperait – nous n'avons pas une seconde à perdre.\n\nJe dois m'entretenir avec lui de notre plan d'attaque, mais entre-temps il nous faut absolument ralentir leur progression.", rewards = "Vous recevrez :\n\n"},
[483] = {title = "Les Reliques d'éveil", objective = "Récupérer les Reliques d'éveil et les rapporter à Athridas Bearmantle à Dolanaar.", description = "Les Pins-tordus ont été vus ravageant le Refuge des saisons de Ban'ethil, à l'ouest.\n\nLes druides dormants vont être pris dans le Rêve d'émeraude pour l'éternité, à moins que nous n'intervenions. Leur très délicate hibernation ne peut pas être interrompue sans les quatre Reliques d'éveil.\n\nRendez-vous au Refuge et récupérez le Talisman Ravenclaw, la Plume noire, le Saphir des cieux et la Rune de nidification. Les druides les gardent dans des coffres sacrés. Apportez-les-moi afin que je prépare le rituel d'éveil.", progress = "<nom>, les druides de la Serre agressés seront à jamais prisonniers du Rêve d'émeraude si nous ne pouvons rassembler les Reliques d'éveil du Refuge des saisons de Ban'ethil, à l'ouest.\n\nChaque minute qui passe scelle un peu plus le funeste destin des druides.", completion = "Vous avez réussi, jeune &lt;classe&gt; ! Bravo ! Il était plus que temps.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières en mailles d'écorceBâton Gritroot\n\nVous recevrez également :\n\n"},
[484] = {title = "Les peaux de jeune crocilisque", objective = "Collecter 4 Peaux de jeune crocilisque, pour James Halloran, au port de Menethil.", description = "Je suis James Halloran, le tanneur. Mes peaux de crocilisque traitées sont prisées dans le monde entier.\n\nVous connaissez Einar ? C’est l’un des chasseurs qui m'approvisionne en peaux.\n\nJe suis en ce moment à court de ces peaux soyeuses qui proviennent des jeunes crocilisques.\n\nJe vous paierais grassement si vous pouviez me rapporter quelques-unes de ces peaux. Vous trouverez les jeunes crocilisques dans les marécages, à l’extérieur de la ville.", progress = "<nom>, c'est ça ? Avez-vous mes peaux ?", completion = "Beau travail, &lt;nom&gt;. La qualité de ces peaux est superbe. Il faut que je commence à les traiter le plus tôt possible. Mais avant, j'ai encore un travail à vous confier ; vous seriez tout à fait à même de le faire, à mon avis.", rewards = "Vous recevrez :\n\n"},
[485] = {title = "Trouver OOX-09/HL !", objective = "Apporter la balise de détresse jusqu'au robot guidé d'Oglethorpe en haut de la rivière dans les Hinterlands, près du rocher de l'Affût.", description = "Vous avez découvert un étrange objet en forme d'oeuf fait de métal. En jouant avec les petit boutons présents sur le dessus, l'oeuf s'anime, à mesure qu'il s'ouvre, il se transforme en une espèce de bidule robot gnomique ! Une voix sort du robot en grésillant.\n\n\"Je suis Oglethorpe Obnoticus, et mon robot guidé a disparu ! Je vous récompenserais si vous le ramenez ! Amenez cette balise au robot.\"\n\n\"J'ai programmé les coordonnées du robot pour vous. Il s'est écrasé en haut de la rivière près du rocher de l'Affût !\"", progress = "Vous découvrez l'épave d'une sorte de... robot poulet ? La voix émerge de l'oeuf une nouvelle fois :\n\n\"Oui, excellent travail ! C'est bien mon robot guidé, mes détecteurs m'indiquent qu'il doit être relancé avant de pouvoir revenir à Baie-du-Butin pour y être réparé. Allez-y et placez la balise dans la machine. La balise s'occupera du reste !\"", completion = "Vous placez l'oeuf... la balise de détresse... dans le poulet... le robot guidé.\n\nVous entendez des bourdonnements venant de l'intérieur du robot quand il essaye de se relever. Après l'activation du robot, la voix d'Oglethorpe retenti de nouveau, mais maintenant elle vient de l'intérieur du robot :\n\n\"OOX-09/HL fonctionne, mais il a besoin de grosses réparations ! Il est trop lourd pour vous... Mais je pense que j'ai une idée. Voudriez-vous bien le surveiller encore un peu ?\"", rewards = "Vous recevrez :\n\n"},
[486] = {title = "Ursal le Mutileur", objective = "Tuer Ursal le Mutileur et retourner voir Athridas Bearmantle à Dolanaar.", description = "Le temps est venu de sauver les druides de la Serre. Si nous échouons maintenant, <nom>, ils resteront à jamais captifs de leur sommeil.\n\nJe pourrais préparer les Reliques d'éveil et pratiquer le rituel, mais mon travail ne peut prendre effet tant que le responsable de cette horrible situation est en vie. Le rituel ne sera achevé que lorsqu'il aura été terrassé.\n\nC'est Ursal le Mutileur qui a perturbé notre cycle, c'est Ursal le Mutileur qui doit payer pour qu'ils puissent être libérés. Voyagez jusqu'au camp des Pins-tordus, au sud-ouest, et exécutez-le.", progress = nil, completion = "&lt;nom&gt;, Vous avez prouvé que vous comptiez parmi les plus valeureux druides. Un &lt;race&gt; qui suit le chemin de l'honneur comme vous le faites est assuré de rencontrer la gloire dans ce monde.\n\nPuissent les Esprits des forêts vous protéger où que vous portent vos pas.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de défenseurGourdin de ronceterre\n\nVous recevrez également :\n\n"},
[487] = {title = "La route de Darnassus", objective = "Tuer 6 Embusqués Pins-tordus et retourner voir la Sentinelle Amara Nightwalker à l'extérieur de Dolanaar.", description = "La route de Darnassus doit être sécurisée. Des voyageurs qui cheminaient entre Dolanaar et Darnassus y ont été témoins d'attaques de furbolgs de la tribu Pins-tordus.\n\nD'importantes informations et des convois commerciaux en provenance de Darnassus empruntent cette voie quotidiennement. Nous ne pouvons tolérer qu'une bande de brigands y terrorise les gens.\n\nAu nom de la Forêt sacrée, prenez les armes, <classe>. Leur repaire est quelque part au-delà de ce point. Tuez 6 de ces Embusqués Pins-tordus et revenez faire votre rapport.", progress = nil, completion = "Vous avez bien servi le bon peuple de Dolanaar et de Darnassus, brave &lt;classe&gt;. En tant que membre des Sentinelles de Teldrassil, je salue vos efforts.", rewards = "Vous recevrez :\n\n"},
[488] = {title = "Les commandements de Zenn", objective = "Rapporter 3 Crocs de sabre-de-nuit, 3 Plumes de Hibou Strigid et 3 Echantillons de Soie d'araignée Tissebois à Zenn Foulhoof à l'extérieur de Dolanaar.", description = "Volontaire pour des missions, à ce que je vois. Heureusement, il n'y a pas un jour sans que je n'aie besoin d'un courageux <classe> prêt et armé pour répondre à mes demandes.\n\nVoyez-vous, <nom>, je puis vous rendre riche et vous offrir ce dont vous n'osez rêver. Mais en échange vous devez me rapporter certains objets.\n\nMon travail dans la forêt requiert souvent certains... réactifs. Rapportez-moi 3 Crocs de sabre-de-nuit, 3 Plumes de hibou Strigid et 3 échantillons de Soie d'araignée Tissebois.\n\nEt que tout cela reste entre nous, <nom>.", progress = "Avez-vous bien travaillé, <nom> ? J'attendais que vous m'apportiez ce que je vous avais demandé.", completion = "Ha ha ! Très bien, très bien.\n\nQui croira que moi, Zenn Foulhoof, ai eu quelqu'un de votre race à mon service ? Certainement pas moi ! Mais c'est ainsi : notre cher monde est plein de surprises, &lt;nom&gt;.\n\nLongue vie aux naïfs et aux crédules !", rewards = "Vous recevrez :\n\nGriffe de Vaudou abîmée"},
[489] = {title = "En quête de rédemption !", objective = "Collecter 3 Gangrenoix et les offrir à Zenn Foulhoof à l'extérieur de Dolanaar.", description = "Le Conseil de la forêt a eu vent que vous aviez aidé Zenn Foulhoof. Ce satyre est un ennemi de la forêt. Un <race> devrait avoir mieux à faire que de la fragiliser en tuant ses créatures.\n\nVous devez vous racheter aux yeux du Conseil si vous désirez rester <un ami/une amie> de Teldrassil.\n\nDonnez une bonne leçon à Foulhoof et vous serez <racheté/rachetée>. Les gangrenoix sont des graines malades qui tombent des arbres. De la fumée verte en sort.\n\nApportez-en à Foulhoof. Il croira qu’il s’agit d’un inoffensif casse-croûte.", progress = "Qu'est-ce que vous avez là pour moi, <nom> ?  Quelque délicieux en-cas je présume ?", completion = "Ah ! Que c'est mignon, &lt;race&gt;. Je savais que vous arriveriez à point !", rewards = "Vous recevrez :\n\n"},
[491] = {title = "Une Baguette pour Bethor", objective = "Apporter le Bâton tressé à Bethor Iceshard dans le Quartier de la magie à Undercity.", description = "Thule m'a raconté qu'il y a longtemps, lui et deux de ses confrères créèrent une Baguette magique, la fusion des trois Baguettes que les mages possédaient alors. Cette Baguette devint le symbole de leur amitié, et bien que Thule se mit peu à peu à la mépriser il ne put se résoudre à s'en séparer ou à la laisser aux deux autres. Alors il vola la Baguette et la cacha dans le donjon de Fenris.\n\nVoilà. Apportez la Baguette à Bethor Iceshard, l'un des anciens amis de Thule. Je suis sûr qu’il appréciera.", progress = "<nom>. Avez-vous vaincu Thule Ravenclaw ?", completion = "Qu'est-ce que ça veut dire ? Thule avait notre Bâton tressé ? Je croyais qu'il avait été perdu lorsque notre amitié vola en éclats et qu'il fit alliance avec le roi-liche !\n\nIl n'a pas dû invoquer son pouvoir, sinon je l'aurais senti à coup sûr. C'est une bonne chose qu'il ne l'ait pas utilisé...\n\nVoilà une trouvaille miraculeuse, &lt;nom&gt;, et vous aurez une récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon estampilléGantelets en mailles robustesCouteau-scie\n\nVous recevrez également :\n\n"},
[492] = {title = "Une Peste nouvelle", objective = "Apporter la Boisson spéciale de Johaan au Montagnard captif.", description = "Selon le Garde noir, un autre de ces Montagnards nains insensés vient juste d'être capturé. Le Garde noir aime utiliser la cave de la taverne des Pendus comme cellule, jusqu'à ce qu'on puisse \"correctement\" s'occuper des prisonniers.\n\nPourquoi n'iriez-vous pas voir comment le captif apprécie la boisson spéciale que j'ai concocté pour lui ? Il contient un soupçon du traitement que la Dame noire a réservé au reste d'Azeroth.", progress = "Si seulement j'avais ma bonne vieille carabine, <classe>, vous seriez aussi mort qu'on peut l'être. Attendez seulement que la brigade de chars à vapeur vienne à ma rescousse !", completion = "Ah ! Enfin à boire ! Je suis sûr que ce n'est pas une bière au malt Rhapsody, mais au point où j'en suis, je prendrais n'importe quoi pour me rincer le gosier.", rewards = "Vous recevrez :\n\n"},
[493] = {title = "Voyage jusqu’aux contreforts d'Hillsbrad", objective = "Livrer les découvertes de l'Apothicaire Renferrel à l'Apothicaire Lydon à Moulin-de-Tarren dans les contreforts d'Hillsbrad.", description = "La Société royale des apothicaires est sous la constante pression de la Dame noire pour le développement de la Peste nouvelle. Nous travaillons sans relâche et avons fait de grands progrès. Nous pensons que le succès de notre entreprise serait plus rapide si nous partagions les informations au sein de la Société.\n\nPour cette raison, je veux que vous portiez mes dernières recherches à l'apothicaire Lydon à Moulin-de-Tarren, une petite ville nichée dans les contreforts d'Hillsbrad. Le voyage sera long.\n\nAllez au sud sans quitter la route. Suivez de près les panneaux !", progress = "Vous avez quelque chose pour moi ?", completion = "Ah excellent ! L'Apothicaire Renferrel mérite mon plus grand respect. J'ai hâte d'étudier son travail.", rewards = "Vous recevrez :\n\n"},
[494] = {title = "Prêts à frapper", objective = "Se rendre à Moulin-de-Tarren et délivrer le message du Traqueur noir Lesh à la Grande Exécutrice Darthalia.", description = "Taisez-vous et écoutez, <classe>.\n\nJ'ai été envoyée ici pour surveiller la ville d'Hillsbrad. C'est une mission de reconnaissance. Il est impératif que vous envoyiez immédiatement des nouvelles à la Grande Exécutrice Darthalia à Moulin-de-Tarren. Dites-lui que moi, le Traqueur noir Lesh, je lui transmets le message suivant :\n\n\"Le cri du corbeau retentit à l'ouest.\"\n\nSuivez la route vers l'est et faites bien attention aux panneaux. Allons, vite, partez pour Moulin-de-Tarren, et en toute hâte !", progress = nil, completion = "Le cri du corbeau retentit à l'ouest ?\n\nExcellente nouvelle ! Hillsbrad est sur le point d'être attaqué. Nous pouvons mettre en marche notre plan de destruction maintenant. Varimathras sera content.", rewards = "Vous recevrez :\n\n"},
[495] = {title = "La Couronne de Volonté", objective = "Faire un rapport à Melisara à Moulin-de-Tarren dans les Contreforts d'Hillsbrad.", description = "Mug'Thol et sa troupe de guerre ogre ont été envoyés à Alterac afin de récupérer la Couronne de Volonté pour dame Sylvanas. Malheureusement, au lieu de la rapporter, cet idiot a décidé de l'essayer... Je suppose que les ogres ne peuvent résister à ce qui brille.\n\nSes actes irresponsables sont de toute façon devenus un problème. La Couronne de Volonté lui a permis de résister à l'enchantement qui le liait au service de dame Sylvanas.\n\nLa Dame noire veut faire un exemple, allez à Moulin-de-Tarren à Hillsbrad et faites un rapport à Melisara, mon lieutenant.", progress = nil, completion = "Vous avez été envoyé par Sharlindra ? Très bien. Vous verrez que je n'aime pas parler pour ne rien dire.\n\nMug'Thol est une vraie source d'irritation, et nous allons nous en occuper, proprement et sans coup férir.", rewards = "Vous recevrez :\n\n"},
[496] = {title = "L'élixir de souffrance", objective = "Apporter 10 Langues d'ours gris et de l'Ichor de Rampant à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "Ah ! Un autre jour misérable à Moulin-de-Tarren ! Tout cet air pur me rend fou, <nom>.\n\nPlus vite nous répandrons l'épidémie parmi les humains, mieux ce sera. Je fais d'importantes recherches pour découvrir des agents mortels à utiliser dans mes décoctions, mais je n'ai pas eu le temps de les collecter tous.\n\nSi vous voulez vous rendre utile, trouvez-moi 10 Langues d'ours gris et du très rare Ichor de Rampant. Vous trouverez ces ingrédients juste à l'extérieur de Moulin-de-Tarren.", progress = "Je vois que vous êtes rentré. J'espère que vous avez pu rassembler les ingrédients dont j'avais besoin. Un autre jour sans mortalité me précipiterait dans la plus noire des mélancolies.", completion = "Ces spécimens sont parfaits. Bien, &lt;nom&gt;, vous avez réussi à m'apporter un soupçon de joie dans ce monde misérable. Vos efforts ont été appréciés.", rewards = "Vous recevrez :\n\n"},
[498] = {title = "Sauvetage", objective = "Selon les ordres de Krusk à Moulin-de-Tarren, libérer Drull et Tog'thar du Donjon de Durnholde.", description = "Moi et d'autres guerriers avons été envoyés par le Chef de guerre pour récupérer un objet à Durnholde et enquêter sur ce prétendu Syndicat.\n\nNous sommes allés à Durnholde pour jeter un coup d'œil, mais nous avons été surpris par un grand nombre d'humains. Nous nous sommes bravement battus, mais ils étaient plus nombreux. Ils se sont emparés de nous, mais je suis parvenu à m'échapper.\n\nDurnholde est au sud-est, de l'autre côté de la rivière. Drull et Tog'thar sont retenus là-bas, vous devez aller leur porter secours.", progress = nil, completion = "Alors comme ça les humains pensaient pouvoir faire de nos guerriers des esclaves ? Nous allons leur montrer de quoi nous sommes capables !\n\nIl semblerait qu'ils aient emmené Gol'dir, notre chef, ailleurs. Nous devons le retrouver et le libérer. Mais nous n'avons pour l'instant aucune idée de l'endroit où il peut être.\n\nQuand nous aurons une piste, vous serez le premier averti, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGilet de gruntCotte d'anneaux de guerre orque\n\nVous recevrez également :\n\nRecette : Steak de grand ours"},
[499] = {title = "L'élixir de souffrance", objective = "Donner l'Elixir de souffrance à Umpi.", description = "Cela va prendre un petit moment d'associer ces ingrédients pour mettre au point ce qui s'appellera l'élixir de souffrance.\n\nNous y voilà ! Ah ! Rien de tel pour égayer une triste journée dans ces mornes contrées que d'insuffler un peu de souffrance dans le monde.\n\nVoyons voir si notre petite potion produit l'effet désiré.\n\nDonnez à mon assistant Umpi un avant-goût de ce que la Dame noire a prévu pour les humains et ceux du Fléau.", progress = "Coâ !", completion = "Coâââk…", rewards = "Vous recevrez :\n\n"},
[500] = {title = "La prime Cassecrête", objective = "Collecter 9 Articulations sales d'ogres Cassecrête dans les montagnes d'Alterac. Les apporter au maréchal Redpath à Southshore.", description = "Les ogres Cassecrête ont installé un repaire dans les montagnes d'Alterac, près des ruines d'Alterac. Mes éclaireurs m'ont appris qu'ils occupaient également ces ruines.\n\nNous ne pouvons pas les laisser s'installer tranquillement là-bas. S'ils commencent à se sentir en sécurité là où ils sont, ils ne tarderont pas à faire mouvement dans les collines. Ils seront alors à nos portes !\n\nPartez au nord dans les montagnes d'Alterac et chassez des ogres. Rapportez-moi leurs Articulations sales, je vous en donnerai une belle prime.", progress = "<nom>, toujours en chasse ?  Avez-vous ces Articulations que je vous avais demandées ?", completion = "Parfait, &lt;nom&gt;. Vous avez dû hacher quantité d'ogres pour avoir toutes ces Articulations.\n\nCela devrait les tenir en respect, au moins pour quelque temps.", rewards = "Vous recevrez :\n\n"},
[501] = {title = "L'élixir de douleur", objective = "Apporter 10 Fioles de sang de lion des montagnes à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "Oh ! <nom>… Les fleurs s’épanouissent à Hillsbrad et l'air est si pur et vif... Comme cela est triste et regrettable. Je regarde par ma fenêtre crasseuse et je me languis de voir notre Peste nouvelle se répandre et porter la mort à ce monde qui le mérite tant.\n\nBien sûr, je resterais bien à ruminer mes pensées morbides toute la journée, mais mon devoir envers la Dame noire ne peut attendre. Vous m'aiderez, n'est-ce pas ? Mes recherches m'ont permis de conclure que la plus mortelle des préparations s'obtient à partir du sang d'un lion des montagnes. Apportez m'en et vous verrez ce que je suis capable de faire.", progress = "Je me souviens de vous, <nom>. Vous alliez m'aider à concocter mon dernier élixir. Je vais avoir besoin de ce sang avant de pouvoir porter le malheur et la désolation aux habitants d'Hillsbrad.", completion = "Superbe collecte, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de musculationBottes écrasantesBottes de marchefeu\n\nVous recevrez également :\n\nRecette : Côtelettes de lion épicées"},
[502] = {title = "L'élixir de douleur", objective = "Donner l’Elixir de douleur à Stanley.", description = "Ah ! Rien de tel que l'odeur du sang frais dans les collines !\n\nMaintenant, nous allons mélanger tout cela et commencer à nous amuser pour de bon ! Ce que j'ai créé à partir de ce sang, je l'appellerai l'élixir de douleur. Si mes calculs sont exacts, cette mixture pourrait bien être le début de la grande œuvre que je veux offrir à dame Sylvanas. Mais avant tout, nous avons besoin de faire un test.\n\nPrenez cet élixir et allez à la ferme la plus au nord dans les champs d'Hillsbrad, au sud-ouest. Et voyons comment Stanley, le petit chien du fermier Ray, apprécie cette \"douceur\".", progress = "Woof ?", completion = "Vous mettez de l'élixir dans le creux de votre main, et l'amenez à la bouche de Stanley.", rewards = "Vous recevrez :\n\n"},
[503] = {title = "Gol'dir", objective = "Libérer Gol'dir et retourner voir Krusk à Moulin-de-Tarren.", description = "D'après les documents que vous avez rapportés, Gol'dir est retenu dans une grande base du Syndicat, plus au nord, très certainement dans les monts Alterac. Il est captif depuis trop longtemps et doit être absolument libéré.", progress = "Donnez-moi la clé, <classe>, je vais ouvrir moi-même.", completion = "Merci, &lt;nom&gt;. Je dirigeais l'expédition de Durotar sous les ordres du Chef de guerre. Mais comme vous pouvez le voir, les choses ont mal tourné. Ils m'ont tenu captif dans cette ville, me forçant à travailler, à porter des fardeaux, à creuser des trous...\n\nMais ce que j'ai enduré n'est pas important. Vous devez transmettre des informations capitales à celui qui dirige maintenant notre groupe, quel qu'il soit.", rewards = "Vous recevrez :\n\n"},
[504] = {title = "Les Combattants Cassecrête", objective = "Tuer 15 Combattants Cassecrête, puis retourner voir le maréchal Redpath à Southshore.", description = "Maintenant que vous avez eu un avant-goût des ogres Cassecrête, je veux que vous leur rentriez dedans franchement...\n\nAllez dans les ruines d'Alterac et débusquez des Combattants Cassecrête. Je veux que vous en fauchiez le plus possible : c'est la seule façon de faire comprendre à ces brutes qu'il faut garder leurs distances avec le territoire de l'Alliance.", progress = nil, completion = "Très bien ! Voilà votre récompense.\n\nAu fait, lorsque vous chassiez ces Combattants, avez-vous vu à quoi ressemblait la ville d’Alterac ? Je parierais qu'elle est dans un triste état. Les ogres ne sont pas connus pour leur délicatesse.\n\nHeureusement, vos efforts les tiendront à présent éloignés de Southshore.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBranchette ardenteTarge lunaire\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[505] = {title = "Syndicat d'assassins", objective = "Tuer 12 Détrousseurs du Syndicat et 8 Larrons du Syndicat puis retourner voir le magistrat Henry Maleb à Southshore.", description = "Je suis le nouveau Magistrat de Southshore, assigné ici suite à l'assassinat du précédent Magistrat. Les tueurs n’ont jamais été retrouvés, mais nos investigations nous ont permis de conclure qu'ils avaient été engagés par le Syndicat, un groupe de voleurs commandé par les nobles du royaume déchu d'Alterac.\n\nLe Syndicat a un camp au nord de Moulin-de-Tarren, occupé par la Horde. D'après nos derniers indices les pistes convergent toutes vers ce camp. Exécutez les membres du Syndicat que vous trouverez là-bas.", progress = nil, completion = "Merci, &lt;nom&gt;. Bien qu'il doive en rester quelques-uns, nous espérons que les assassins de mon prédécesseur comptaient parmi les voleurs et les détrousseurs que vous avez exécutés. De toute façon, le Syndicat est une insulte sur ces terres et une tache qui souille la race humaine.\n\nLeur mort ne peut que profiter à Southshore.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture du CroiséGants vitaux des sages\n\nVous recevrez également :\n\n"},
[506] = {title = "L'héritage de Blackmoore", objective = "Transmettre l'information recueillie par Gol'dir à Krusk à Moulin-de-Tarren.", description = "Il y a quelques jours, j'ai reçu la visite du leader de ce Syndicat. Son nom est Aliden Perenolde et il se prend pour le seigneur de ce pays. Il m'a confié qu'il voulait utiliser les orcs qui s'insurgent contre lui comme esclaves, exactement comme le voulait son père et mentor, le méprisable Blackmoore.\n\nPlus important : il est venu en compagnie de sa maîtresse, une petite femme nommée Elysa, qui portait autour du cou le pendentif que le Chef de guerre désire tant.\n\nPartez maintenant, je me débrouillerai pour régler mes affaires.", progress = nil, completion = "Le sang-froid de ces humains dominateurs est invraisemblable ! Nous allons leur montrer que les orcs ne se plieront jamais à leur volonté !\n\nCeci sera notre mission, en plus de celle de récupérer la breloque que le Chef de guerre désire tant. Nous pourrions ainsi faire d'une pierre deux coups.", rewards = "Vous recevrez :\n\n"},
[507] = {title = "Seigneur Aliden Perenolde", objective = "Tuer le seigneur Aliden Perenolde et interroger sa maîtresse, Elysa, au sujet du pendentif de Taretha.", description = "Il est évident que Perenolde doit être tué pour que son influence néfaste disparaisse de la surface de ce monde. Son manoir se trouve au nord, sur les rives du lac Lordamere. Faites votre devoir, <nom>, et récupérez le pendentif pour le Chef de guerre.", progress = "Qu-que voulez-vous ?", completion = "Non, non, je vous en supplie, ne me tuez pas ! Je n'ai jamais voulu faire de mal à votre peuple. J'étais sous sa domination ! S'il vous plaît, épargnez-moi !", rewards = "Vous recevrez :\n\n"},
[508] = {title = "Le cadeau de Taretha", objective = "Rapporter le Pendentif de Taretha à Krusk à Moulin-de-Tarren.", description = "Le Pendentif ? Bien sûr que vous pouvez l'avoir, prenez-le ! Je ne veux garder de lui aucun souvenir… Laissez-moi tranquille, je ne vous demande rien d'autre.", progress = "Vous êtes rentré, <nom>. Avez-vous réussi ?", completion = "Il est singulier que le Chef de guerre ait dépensé autant d'énergie pour une si petite chose. Je ne prétends pas le comprendre, mais je le suivrai et obéirai, quels que soient ses ordres. Vous avez bien travaillé, &lt;nom&gt;, et il n'y a pas à douter que le Chef de guerre sera content d'apprendre votre succès.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes MantisEpauliers de brigand\n\nVous recevrez également :\n\n"},
[509] = {title = "L'élixir d'agonie", objective = "Apporter 6 Fleurs de fangemufle à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "À chaque jour son élixir. Si cela ne tenait qu'à moi, je laisserais bien ces humains pathétiques et le Fléau se combattre. Ceux-là semblent nés pour s'entre-tuer.\n\nMais la Dame noire veut accélérer le processus, alors pourquoi ne pas passer ces longues et morbides journées à répandre un peu de peste et de mort à travers le pays ?\n\nVoici le plan, <nom> : vous irez à la ferme des Nethander, au sud de Moulin-de-Tarren et à l'est de la rivière et de Southshore. Collectez 6 Fleurs de fangemufle dans les champs et rapportez-les-moi que je puisse achever mon prochain élixir.", progress = "Bonne pêche à la ferme des Nethander ?", completion = "Ah ! L'horrible puanteur des fleurs de fangemufle. Au moins ces immondes gnolls sont bons à quelque chose.", rewards = "Vous recevrez :\n\nPotion de rapiditéPotion de soins"},
[510] = {title = "Documents d'annonce d'attaque", objective = "Apporter les Documents d'annonce d'attaque au Magistrat Maleb à Southshore.", description = "Parmi ces documents se trouve une liste des marchandises commandées. Elle contient des requêtes ordinaires (nourriture, armes, vêtements), mais aussi des demandes moins conventionnelles (masques, huile, poison).\n\nMais ce qu'il y a de plus remarquable est le caractère urgent de la commande. Ces marchandises étaient nécessaires à l'exécution de ce qui est décrit dans le document comme une \"mission importante contre Southshore\", et l'on en avait besoin rapidement.", progress = "<nom>, vous paraissez anxieux. Avez-vous quelque chose à m'annoncer ?", completion = "&lt;Maleb parcourt les documents.&gt;\n\nTout cela est inquiétant, &lt;nom&gt;. D'après les informations contenues dans ces documents, et d'après les actions menées dans le passé par le Syndicat, nous devons considérer comme acquis qu'une bande de coupe-gorge a déclaré la guerre à Southshore.", rewards = "Vous recevrez :\n\n"},
[511] = {title = "Lettre codée", objective = "Apporter la Lettre codée au Maître des traditions Dibbs, à Southshore.", description = "L'une des lettres, sur la table, est codée et ne peut être déchiffrée.", progress = "Oui, Monsieur ? Que puis-je faire pour vous ?", completion = "Qu'est-ce donc ? Attendez un instant… laissez-moi y regarder de plus près.\n\n…\n\nHum ! Je n'ai jamais rencontré ce type de code auparavant, mais je n'ai pas la prétention de tout connaître dans ce domaine.", rewards = "Vous recevrez :\n\n"},
[512] = {title = "Nobles morts", objective = "Apporter 7 Chevalières d'Alterac au Magistrat Maleb à Southshore.", description = "J'ai peur que les dirigeants du Syndicat ne veuillent à tout prix la ruine de Southshore. Nous devons porter un coup décisif à ses chefs avant que leurs plans n'aboutissent.\n\nPartez pour les Ruines de Strahnbrad, dans les monts Alterac au nord. Nous pensons que le Syndicat a établi son quartier général dans cette région.\n\nNous savons que ce gang de brigands reçoit ses ordres d'anciens nobles d'Alterac. Il se peut qu'ils se camouflent parmi les agents ordinaires du Syndicat, mais vous saurez que vous avez tué un noble à la chevalière qu'il porte.\n\nApportez-moi ces chevalières.", progress = "Alors, avez-vous attaqué le Syndicat ? Avez-vous ces bagues ?", completion = "Priver le Syndicat de ses nobles lui ôtera toute capacité à décider efficacement, et le réduira à rien de plus qu'un ramassis de vulgaires voyous.\n\nVous avez servi l'Alliance avec brio, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[513] = {title = "L'élixir d'agonie", objective = "Apporter la Poudre de fangemufle au Maître Apothicaire Faranell à Undercity.", description = "Alors que je me résignais à l'idée qu'un autre jour allait s'achever exempt de toute joie, vous m'apportez ces merveilleuses fleurs de fangemufle.\n\nJe vais d'abord les réduire en une fine poudre. Nous aurons alors besoin que le Maître Apothicaire Faranell à Undercity lui applique son colloïde de virulence. Après, on devrait plutôt s'amuser, je crois... \n\nTenez, prenez cette Poudre de fangemufle et courez immédiatement voir maître Faranell, <nom>.", progress = "Ne voyez-vous pas que je suis occupé, <classe> ? La Dame noire insiste pour qu'une Peste nouvelle soit prête avant que le Fléau de Northrend ne nous submerge. Et avec les humains qui arrivent par le sud, le temps est mon bien le plus précieux. J'espère que c'est important.", completion = "L'apothicaire Lydon vous envoie ? Ah, pourquoi ne pas l'avoir dit plus tôt !\n\nMalgré son humeur un peu sombre, l'apothicaire Lydon est l'un de nos membres les plus consciencieux et les plus éminents.\n\nAinsi, notre bon ami envoie de la Poudre de fangemufle ! Je sais ce que notre compagnon d'Hillsbrad prépare en ce moment. Et j'aime la façon dont il pense. La Dame noire serait impressionnée des progrès qu'il accomplit pour concocter une Peste nouvelle.", rewards = "Vous recevrez :\n\n"},
[514] = {title = "Le maître des lettres", objective = "Apporter la Lettre ingénieusement codée au Prospecteur Stormpike à Ironforge.", description = "J'ai un collègue à Ironforge qui pourrait peut-être décoder cette lettre. Rendez-vous à la bibliothèque du Hall des Explorateurs à Ironforge et parlez au Prospecteur Stormpike. Dites-lui que je vous envoie et montrez-lui la lettre. S'il y a une personne au nord du pic Blackrock à pouvoir lire cela, c'est bien lui.", progress = "Ainsi, c'est Dibbs de Southshore qui vous envoie ! Comment se porte donc ce vieux rat de bibliothèque ?", completion = "Ah ! le codage. L'une de mes spécialités. Laissez-moi voir…", rewards = "Vous recevrez :\n\n"},
[515] = {title = "L'élixir d'agonie", objective = "Apporter le Brouet de fangemufle, une Potion de sang de troll forte, 5 Ecailles de Daguéchine et 5 Yeux d'Ailerons déchirés à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "Un composé à base de fangemufle ? Absolument merveilleux ! Pourquoi n'y ai-je pas pensé ? Laissez-moi appliquer de mon colloïde de virulence à cette diabolique mixture.\n\nAfin d'activer les agents contaminateurs de ce brouet de fangemufle, Lydon aura besoin d'une potion de sang de troll forte, d'écailles de Daguéchine et d'yeux d'Ailerons déchirés de la côte méridionale. Il saura quoi faire une fois que vous aurez réuni tous les ingrédients. Ah ! j'ai tellement hâte d'apprendre ce que l'expérience va donner.", progress = "Je suis tellement heureux de vous revoir, <nom>. Je commençais à me morfondre misérablement ici. Rien à faire d'amusant si ce n'est empoisonner Umpi et la rendre malade, puis la réanimer... encore et encore.\n\nComment s'est passé le voyage à Undercity ? Avez-vous eu la chance de massacrer quelques humains le long de la route ?", completion = "Ce projet me rend tout fou d'excitation. Vous avez été d'un tel secours, &lt;nom&gt;. Ensemble nous répandrons la mort et la maladie à travers cette terre !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de grand apothicaireEcharpe de méditation\n\nVous recevrez également :\n\n"},
[516] = {title = "Le Péril de Beren", objective = "Localiser le Péril de Beren, tuer 6 Manouvriers Ravenclaw et 6 Gardiens Ravenclaw puis retourner voir le prêtre des ombres Allister au Sépulcre.", description = "J'ai reçu des rapports indiquant qu'un groupe de morts-vivants se cache pour préparer une attaque contre nous. Armés de cette information, nous pouvons retourner la situation en les attaquant les premiers et réduire leur plan minable à un simple souvenir cocasse.\n\nMalheureusement, les informations dont nous disposons sont incomplètes, au mieux. On dit qu'ils se cachent dans un endroit appelé Péril de Beren. La localisation exacte est inconnue, mais nous savons que c'est une caverne dans les collines, près d'une enclave des sorciers de Dalaran.\n\nJ'ai confiance en vos ressources. Trouvez-les et tuez-les.", progress = nil, completion = "Si nos éclaireurs et nos agents continuent à nous procurer de si riches informations, le Fléau du roi-liche sera éradiqué de nos terres en un rien de temps.", rewards = "Vous recevrez :\n\nBaguette de putréfaction"},
[517] = {title = "L'élixir d'agonie", objective = "Apporter un baril de Bière Shindigger à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "Ce nouvel élixir est enfin prêt à être testé. Mais pourquoi gâcher une si bonne et si contagieuse peste sur une pauvre grenouille ou un chien famélique ? Amusons-nous un peu, au nom de Dame Sylvanas.\n\nDescendez à Dun Garok. Vous connaissez les casernes où ces sales petits nains s’agitent partout ? Volez un baril de leur Bière Shindigger pour moi. Une fois que j'aurai ce baril, nous pourrons commencer la fête, vous et moi, <nom>.", progress = "Parfois je m'ennuie tellement ici à Moulin-de-Tarren que j'aimerais ouvrir la jarre de formaldéhyde et laisser son délicat arôme envahir l’air. Cela rend Umpi un peu nerveuse, toutefois…\n\nAlors, avez-vous réussi à dérober un baril aux nains ? Je jure que si je dois regarder cet élixir fatal un jour de plus sans pouvoir l'utiliser sur quelqu'un, je vais me mettre à hurler.", completion = "Enfin ! Nous sommes prêts à passer à l'action.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[518] = {title = "La Couronne de Volonté", objective = "Tuer 14 Mutilateurs Cassecrête pour Melisara à Moulin-de-Tarren.", description = "Mug'Thol et ses ogres Cassecrête ont envahi les ruines d'Alterac. Il va être difficile de lui infliger une sérieuse punition sans d’abord entamer ses troupes.\n\nAprès les avoir réduites à la portion congrue, nous l’attaquerons.\n\nCompris ? Bien. Allez-y à présent.", progress = nil, completion = "La neige est rouge du sang des ogres, mais nous ne pouvons pas relâcher nos efforts tant que les forces et la volonté des ogres Cassecrête ne sont pas écrasées et enterrées loin sous la terre et sous la neige.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[519] = {title = "La Couronne de Volonté", objective = "Tuer Targ, Fouilleboue et Glommus, puis apporter leurs têtes à Melisara à Moulin-de-Tarren.", description = "Targ, Fouilleboue et Glommus sont les lieutenants de Mug'Thol. Ils lui sont loyaux, bien que personne ne sache vraiment ce qui peut amener un ogre à la loyauté.\n\nApportez-moi leurs têtes, <nom>, et alors tout ce qu'il restera à faire sera de s'occuper de celle de Mug'Thol, de sa couronne, et du reste.", progress = "Je veux leurs têtes, <nom>, pas des excuses !", completion = "…Et moi qui pensais que les ogres sentaient mauvais…\n\nQuand vous m'apporterez la tête de Mug'Thol, ces quatre-là iront sur une pique, en haut d'Alterac. Un monument parfait à la gloire de ceux qui vont à l'encontre des souhaits de la Dame noire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[520] = {title = "La Couronne de Volonté", objective = "Tuer Mug'Thol et présenter sa tête et la Couronne de Volonté à Melisara, à Moulin-de-Tarren.", description = "À présent que les lieutenants de Mug'Thol sont morts, tout ce qu'il reste à faire est de tuer Mug'Thol et de récupérer la Couronne de Volonté. Je ne crois pas qu'il veuille la donner gentiment. Et encore moins à vous, si l'on considère la façon dont ses amis sont... partis.\n\nTrouvez Mug'Thol, et présentez-moi sa tête et la Couronne. Le glas sonnera alors pour la résistance des Cassecrête.", progress = "J'ai trois têtes, il m'en faut quatre. Ce sera celle de Mug'Thol, ou bien la vôtre, <nom>. Ça, je le promets.", completion = "Vous avez accompli avec succès votre devoir, &lt;nom&gt;. La tête de Mug'Thol ornera la plus haute pique d'Alterac, et les Gardes noirs balaieront les restes de la résistance des Cassecrête.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[521] = {title = "La Couronne de Volonté", objective = "Remettre la Couronne de Volonté à Sharlindra, à Undercity.", description = "Tout ce qu'il reste à faire est de donner la Couronne de Volonté à Sharlindra, à Undercity. Elle veillera à ce que la Couronne soit remise à Dame Sylvanas. Je vous déconseille de penser à la coiffer à vos propres fins, <nom>. Le sort de Mug'Thol est assez éloquent.", progress = "Oui ? Avez-vous un rapport à me faire ?", completion = "Ainsi voilà la relique dont s'est servi l'ogre pour faire plier la volonté de la Dame noire…\n\nC'est étrange qu'un objet aussi simple d'apparence puisse détenir un pouvoir aussi grand. Et pour tomber entre des mains aussi maladroites… Parfait, &lt;nom&gt;, je vais remettre la Couronne à dame Sylvanas, et veiller à ce qu'elle ait vent de votre exploit.", rewards = "Vous recevrez :\n\nTalisman éthéré"},
[522] = {title = "Contrat de l'assassin", objective = "Apporter le Contrat de l'assassin au Magistrat Maleb à Southshore.", description = "Ceci est un contrat pour l'assassinat du Magistrat Henry Maleb. L'ordre a été scellé à la cire rouge, à l'aide d'une chevalière caractéristique.", progress = "Vous semblez à bout de souffle. Avez-vous une information à me donner ?", completion = "&lt;Maleb inspecte le contrat.&gt;\n\nCela explique la dernière attaque sur Southshore. Le Syndicat doit vouloir m'abattre, tout comme il voulait abattre le dernier magistrat.", rewards = "Vous recevrez :\n\n"},
[523] = {title = "La mort du baron Vardus", objective = "Apporter la tête du baron Vardus au Magistrat Maleb à Southshore.", description = "Le contrat que vous avez trouvé est signé par le baron Vardus, un noble de l'ancien royaume d'Alterac, réputé pour son cœur de pierre et ses pratiques barbares. Je ne suis pas surpris que quelqu'un comme le baron soit derrière tout ça.\n\nTrouvez cet homme. Trouvez-le, et amenez-le devant la justice. Il doit être avec l'élite du Syndicat. Peut-être aux Ruines de Strahnbrad, ou dans la vallée qui est au nord.", progress = "Le baron Vardus ne doit pas croire que Southshore lui permet d'envoyer impunément ses tueurs. Je veux sa tête !", completion = "Merci, &lt;nom&gt;. Ma tête repose un peu plus facilement, maintenant que ce scélérat a perdu la sienne.", rewards = "Vous recevrez :\n\n"},
[524] = {title = "L'élixir d'agonie", objective = "Placer le Baril infecté sur le tapis pour les fermiers détenus comme otages.", description = "A côté, les Gardes noirs détiennent quelques fermiers pris en otage. La Grande Exécutrice Darthalia suspectait qu'un des stratèges de Stormwind se cache parmi eux. Apparemment, le pauvre militaire a été retrouvé mort dans les Maleterres la nuit dernière. Darthalia, toujours aux petits soins pour moi, a décidé de me laisser faire ce que je voulais avec les fermiers.\n\nJe pense qu'il est temps de leur préparer une petite fête. Comme au bon vieux temps !\n\nPlacez ce baril infecté sur le tapis, dans leur pièce. Tournée générale bière pestilentielle !", progress = "Une odeur de moisi émane du tapis.", completion = "Vous placez le baril infecté sur la couverture poussiéreuse.", rewards = "Vous recevrez :\n\n"},
[525] = {title = "D'autres mystères", objective = "Apporter la Lettre décodée au Magistrat Maleb, à Southshore.", description = "J'ai déchiffré la lettre, mais je ne sais pas quoi en faire. Vous l'avez trouvée chez des voleurs dans les collines d'Alterac ? C'est étrange…\n\nVous devriez la montrer au Magistrat de Southshore. Bien que cette lettre soit sibylline, Southshore est la ville la plus proche d'Alterac. Si un danger menace, alors il doit savoir.", progress = "<nom>. Avez-vous de nouveau voyagé à travers les collines et les montagnes ? Quelles nouvelles m'apportez-vous ?", completion = "&lt;Maleb lit la lettre.&gt;\n\nC’est la traduction d'une lettre trouvée dans un camp du Syndicat ? Elle n'a pas été écrite par un voleur, ni par un noble d'Alterac.\n\nIl apparaît que le Syndicat s'est allié à un autre pouvoir, et je frémis à l'idée de ce qu'il pourrait être.", rewards = "Vous recevrez :\n\n"},
[526] = {title = "Les lingots de sancteforge", objective = "Collecter 5 Lingots de sancteforge, puis retourner voir Glorin Steelbrow, dans les Paluns.", description = "Vous avez peut-être découvert un lingot de sancteforge dans ce coffre, mais ce n'est pas suffisant pour forger quoi que ce soit de décent avec !\n\nVous devriez y retourner et en chercher davantage. Les murlocs, près de l'épave, ont peut-être des lingots sur eux.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[527] = {title = "La bataille d'Hillsbrad", objective = "Tuer 6 Garçons de ferme, 6 Fermiers, le Fermier Ray et le Fermier Getz, puis retourner voir Darthalia à Moulin-de-Tarren.", description = "Mettez-vous au garde-à-vous lorsque vous vous adressez à moi, <classe> ! Je suis sous le commandement direct de Varimathras. Nous devons neutraliser la prolifération des humains jusqu'à ce que nos apothicaires développent la Peste nouvelle.\n\nNos services de renseignements pensent que la ville d'Hillsbrad serait vulnérable à une attaque. Votre première mission consiste à perturber leur approvisionnement et le stockage de nourriture.\n\nPartez à l'ouest. Faites une incursion dans les fermes les plus au nord des Champs d'Hillsbrad. Assurez-vous que leurs propriétaires, les fermiers Ray et Getz, soient exécutés.", progress = "En tant que Haute Exécutrice de Moulin-de-Tarren, placée sous le commandement direct de Varimathras et de la Dame noire, vous devez m’obéir. \n\nPeut-être prenez-vous cette guerre contre l'Alliance à la légère ? Si tel est le cas, je vous décapiterai ici même, sur l'heure. Sinon, partez à l'ouest, vers la ville d'Hillsbrad et lancez l'assaut contre les humains, comme je vous l'ai ordonné.\n\nRompez.", completion = "Repos, &lt;classe&gt;. Je vois que vous revenez de la bataille. Mes sources indiquent que vous vous êtes bien comporté sur le front d'Hillsbrad.", rewards = "Vous recevrez :\n\n"},
[528] = {title = "La bataille d'Hillsbrad", objective = "Tuer 15 Paysans d'Hillsbrad et faire votre rapport à Darthalia à Moulin-de-Tarren.", description = "La nouvelle de l'attaque sur les fermes situées au nord a semé la panique chez les gens de la ville. Merveilleux !\n\nNos Traqueurs noirs rapportent que les paysans fuient vers les champs au sud d'Hillsbrad. Ces imbéciles pensent qu'ils peuvent s’y cacher et ainsi échapper à leur sort.\n\nMontrez-leur qu'ils ont tort, <nom>. Retournez aux Champs d'Hillsbrad et traquez les paysans qui s'y tapissent. Apportez-leur le chaos au nom de la Dame noire.\n\nRompez !", progress = nil, completion = "L'étreinte de la mort se resserre sur la ville d'Hillsbrad. La bataille se déroule bien.", rewards = "Vous recevrez :\n\n"},
[529] = {title = "La bataille d'Hillsbrad", objective = "Tuer le Forgeron Verringtan et 4 Apprentis Forgerons d'Hillsbrad.\n\nRécupérer un Chargement de fer, puis retourner voir Darthalia à Moulin-de-Tarren.", description = "Les humains d'Hillsbrad ont fait montre d'une résistance inattendue. Le problème semble être que les gens de la ville sont équipés par le forgeron local. Nous devons couper cet approvisionnement.\n\nVotre mission consiste à exécuter le forgeron Verringtan. Tuez également ses apprentis. Pendant que vous y serez, ramenez un chargement de fer prélevé dans leur stock. Cela se révélera pratique lorsque nous aurons achevé la conquête d'Hillsbrad et que nous entreprendrons de raser Southshore.", progress = "Avez-vous exécuté vos ordres, <classe> ? Nous avez-vous débarrassés de Verringtan et de ses apprentis ? Et où est ce fer ?", completion = "Mission accomplie, &lt;classe&gt;. Et avec panache, pourrais-je ajouter.", rewards = "Vous recevrez :\n\n"},
[530] = {title = "La vengeance d'un mari", objective = "Tuer Valdred Moray.\n\nApporter ses mains à Raleigh Andrean à Undercity.", description = "Valdred, autrefois un bon ami à moi, est le meurtrier de ma femme. Bien que je sois incapable de ressentir de la peine, j'aspire à la vengeance. Si vous tuez Valdred et me rapportez ses mains maudites, alors je vous récompenserai.\n\nLa dernière fois que j'ai entendu parler de lui, il se trouvait au Mur de Greymane, dans le sud des Pins argentés, essayant de fuir vers le royaume de Gilnéas.", progress = "Avez-vous ses mains, <nom> ?", completion = "Ah bien ! Ce sont ces mains qui ont tué ma femme, Deliah. Venger sa mort était ma seule préoccupation, et vous étiez mes instruments.\n\nTenez, prenez la bague que vous avez apportée il y a quelque temps. Deliah est morte depuis si longtemps que cette bague n'est plus qu'une babiole, que je ne souhaite plus garder. A la place, je conserverai ces mains comme souvenir de la traîtrise de mon ami.", rewards = "Vous recevrez :\n\nAnneau de dédain"},
[531] = {title = "La vengeance de Vyrin", objective = "Amener la tête du vieux Noiraud à Vyrin Swiftwind au pavillon des pérégrins.", description = "Par la Lumière ! N'apportez pas de choses comme ça dans le pavillon… c'est insalubre, insupportable, in… in… insalubre !\n\nSortez-moi ça de là, voulez-vous ? Personne ne veut voir votre fichu petit trophée, vraiment !", progress = "Bon travail, <nom> ! La démonstration était éloquente. Tenez, donnez-moi la tête et j'en prendrai soin.", completion = "Merci de votre soutien dans cette petite affaire, &lt;nom&gt;. Cela me démangeait depuis des mois de rendre la monnaie de sa pièce à ce garçon hautain et bêcheur, et je dirais qu'on a fait du plutôt bon boulot ! Tenez, prenez ça, vous l'avez gagné.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGiberne de chasseCarquois de chasse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[532] = {title = "La bataille d'Hillsbrad", objective = "Tuer le Magistrat Burnside et 5 Conseillers d'Hillsbrad. Détruire la Proclamation d'Hillsbrad. Voler le Registre municipal d'Hillsbrad. Rendre compte à Darthalia à Moulin-de-Tarren.", description = "La ville d'Hillsbrad est en pleine confusion et nous pensons qu'elle va bientôt tomber. Nous devons cependant persister dans notre barbarie jusqu'à ce que ces chiens d'humains soient balayés des collines pour l'éternité.\n\nMalgré leurs pertes écrasantes, les humains se rassemblent autour de leurs chefs et continuent à se battre. Nous devons éliminer leur chef, le maire Burnside, de même que le conseil municipal. Détruisez également leur très précieux document politique, la Proclamation d'Hillsbrad. Et pendant que vous y êtes, volez le Registre municipal.", progress = "Quelles nouvelles apportez-vous ?", completion = "Les nouvelles de vos exploits à Hillsbrad se sont vite propagées. Vous avez bien œuvré, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[533] = {title = "Infiltration", objective = "Rapporter des informations sur la localisation de Gol'dir pour Krusk, à Moulin-de-Tarren.", description = "Nous avons enfin des nouvelles et des rumeurs, des indices sur l'endroit où pourrait être Gol'dir. Les humains l'ont emmené à divers endroits, mais nos recherches aboutissent au grand camp du Syndicat au nord d'ici.\n\nAllez-y, <nom>, et ramenez toutes les informations sur lesquelles vous pouvez mettre la main.", progress = "Avez-vous découvert quelque chose ? J'ai peur que les espoirs de Gol'dir s'amenuisent de jour en jour.", completion = "Enfin, nous savons où est détenu Gol'dir. Le camp en question n'est pas très loin d'ici, et espérons qu’ils ne seront pas aussi préparés que lorsqu'ils nous ont capturés la première fois.", rewards = "Vous recevrez :\n\n"},
[534] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[535] = {title = "Valik", objective = "Apporter une Chope de bière de Southshore à Valik, au Camp du Syndicat.", description = "Eurrgh… Blessé et mourant, me voilà en face de l'ennemi.\n\nVous me tuerez de toute façon, mais si vous m'apportez de la bière de Southshore... Vous autres ne buvez pas, n'est-ce pas ? Je vous dirai ce que vous voulez savoir.", progress = "M'avez-vous apporté quelque chose à boire ou êtes-vous venu achever le travail ?", completion = "Compte tenu de ma mort imminente, je crois pouvoir dire sans me tromper que c'est la meilleure chose à laquelle j'ai goûtée… Tenez, prenez ça, ça ne me servira pas à grand-chose quand je serai mort.\n\nEh bien ! allez-y.", rewards = "Vous recevrez :\n\nMissive du Syndicat"},
[536] = {title = "Le long de la côte", objective = "Tuer 10 Chasse-marées et 10 Oracles Aileron déchiré pour le lieutenant Farren Orinelle à Southshore.", description = "Transféré de la garde de la cité de Stormwind à Southshore, une ville visiblement abandonnée… L'odeur du port jour et nuit.\n\nSans parler du vieux Redpath… Veut que je m'occupe des murlocs. Ha !\n\nJ'ai du mal à m'imaginer allant jusqu'à l'une des enclaves de ces grotesques poissons mutants qui grouillent le long du Rivage occidental. Si vous pouviez y aller et vous occuper d'eux, j'apprécierais.", progress = "Une autre bière, je vous en prie, la dernière semble avoir simplement disparu !\n\nLumière, combien de temps vais-je encore être coincé ici ?\n\nOh ! c'est vous, <nom>. Avez-vous déjà tué ces murlocs ?", completion = "J'espère que cela suffira à convaincre Redpath que j'ai – ha ! – exécuté ses ordres et débarrassé Southshore de la terrible menace des redoutables murlocs du lac Lordamere ! Car il n'y a pas de mal plus grand que les ravages de ces poissons mutants !", rewards = "Vous recevrez :\n\n"},
[537] = {title = "Le conseil noir", objective = "Tuer 4 Mages de l'ombre d'Argus.\n\nApporter la Tête de Nagaz au Magistrat Maleb à Southshore.", description = "La lettre que vous m'avez apportée a été écrite par un être qui se nomme lui-même Nagaz, un membre de la Veille d'Argus. Je ne sais pas ce qu'est cette Veille d'Argus, mais si elle est alliée au Syndicat, alors elle constitue une menace.\n\nJe veux que vous trouviez Nagaz et les Mages de l'ombre d'Argus mentionnés dans cette lettre. Je veux que vous les trouviez et que vous les tuiez.\n\nCherchez dans les Hauteurs, là où le Syndicat est le plus fort.\n\nAvec un peu de chance, vous y trouverez ces représentants de la Veille d'Argus.", progress = "Avez-vous découvert les représentants de la Veille d'Argus ?", completion = "Bon travail, &lt;nom&gt;. Nous ne voudrions pas d’un groupe comme la Veille d'Argus à la tête du Syndicat.\n\nEt bien que vous ayez tué leur chef, Nagaz n'était que le serviteur d'un autre. Il se peut que la Veille d'Argus soit profondément implantée sur le continent d'Azeroth.\n\nOu bien même sur le monde entier.", rewards = "Vous recevrez :\n\n"},
[538] = {title = "Southshore", objective = "Parler à l'Erudit Dibbs à Southshore.", description = "<nom>. Si un long voyage ne vous dérange pas, alors j'ai une tâche à vous confier, pour aider à nouveau Stormwind à étoffer sa bibliothèque.\n\nL'ancien royaume d'Alterac s'est effondré après la Grande Guerre. C'est malheureux que la ville soit à présent en ruine, mais il est encore plus tragique que de grands savoirs aient disparu ! Nous devons retrouver ces importantes collections de livres.\n\nSouthshore est la ville la plus proche des Ruines d'Alterac. Rendez-vous-y et parlez à l'Erudit Dibbs. Il peut vous guider vers les ruines, et tous les livres que vous pourriez trouver.", progress = nil, completion = "Ah oui ! je me souviens de Milton. Un vrai rat de bibliothèque. Qu'il soit béni !\n\nEt il a raison. Les ruines d'Alterac abritent toujours des sommes de connaissance qui risquent d'être perdues !\n\nCe sont les ogres qui vivent à présent à Alterac, et ils sont peu portés sur les études supérieures...", rewards = "Vous recevrez :\n\n"},
[539] = {title = "La bataille d'Hillsbrad", objective = "Tuer le Contremaître Bonds et 10 Mineurs d'Hillsbrad, puis rendre compte à Darthalia, à Moulin-de-Tarren.", description = "Le Registre municipal d'Hillsbrad indique que la Mine d'Azureload est sous le contrôle de l'Alliance. De plus, c’est une source importante de minerai de fer destinée aux armureries de l'Alliance.\n\nMême si nous avons porté un coup décisif à la ville d'Hillsbrad, l'Alliance soutient et protège toujours la Mine d'Azureload.\n\nElle se trouve au sud d'Hillsbrad. Allez-y et tuez le contremaître, un humain du nom de Bonds. Tuez également ses Mineurs. Cela devrait envoyer un message fort à l'Alliance.", progress = nil, completion = "La Dame noire sera ravie d'apprendre qu'elle possède une nouvelle mine avec laquelle elle pourra armer ses soldats.", rewards = "Vous recevrez :\n\n"},
[540] = {title = "L'entretien des connaissances", objective = "Apporter 5 Tomes retrouvés, ainsi que le Livre de cuir usé « Le Bras de Gri'lek » au Maître des traditions Dibbs, à Southshore.", description = "Ces ogres répugnants résident à présent dans les ruines d'Alterac, et je frémis à l'idée de ce qu'ils peuvent faire des précieux livres qui s'y trouvent.\n\nPénétrez dans les ruines d'Alterac et récupérez des tomes sur les ogres. Prenez tout ce que vous trouverez, mais cherchez également le livre suivant : « Le Bras de Gri'lek ». C’est un recueil d’anciennes légendes trolls que je dois lire. Les ruines d'Alterac sont le dernier endroit où se trouve une copie intacte de cet ouvrage.", progress = "J'aimerais moi aussi explorer les mines, mais j'ai bien peur que ma carcasse refuse d’escalader les montagnes. Et vous, <nom>, comment votre soif de savoir s'étanche-t-elle ?", completion = "Oh ! vous les avez. Splendide ! Je dois commencer immédiatement l'étude du Bras de Gri'lek !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[541] = {title = "La bataille d'Hillsbrad", objective = "Aller à Dun Garok et tuer 10 Montagnards, 8 Fusiliers, 4 Prêtres et le Capitaine Ironhill, puis rendre compte à Darthalia, à Moulin-de-Tarren.", description = "Des nains aidant des humains ? Que ces affreuses petites bêtes soient maudites.\n\nNous allons tester la force de cette prétendue Alliance. Nous verrons à quel point ces cogneurs de chevilles sont déterminés à aider les humains une fois que nous serons passés. Nous savons précisément où se trouve leur forteresse dans ce territoire.\n\nIls ont établi une caserne dans la partie sud-est d'Hillsbrad, le long du Mur de Thoradin. La mission est d'attaquer cette caserne, baptisée Dun Garok, <classe>. Le capitaine Ironhill, leur chef, doit mourir.", progress = nil, completion = "Vos actions sur le champ de bataille sont dignes des plus grands éloges.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[542] = {title = "Les livres de Milton", objective = "Apporter les Tomes d'Alterac à Milton Sheaf à Stormwind.", description = "J'ai besoin de temps pour étudier le livre « l'Arme de Gri'lek » que vous m'avez apporté, mais je suis sûr que Milton a hâte d'enrichir la collection des livres de Stormwind avec ceux que vous avez retrouvés aux Ruines d'Alterac.\n\nLes voici, empaquetés et catalogués. Amenez-les à Milton Sheaf à Stormwind et je suis certain qu'il sera reconnaissant.", progress = "<nom>, vous êtes revenu ! Comment s'est déroulée votre expédition à Alterac ? Est-ce que vous avez ramené quelque chose de là-bas ?", completion = "Ça, par exemple ! Regardez-les ! Je n'arrive pas à croire qu'ils aient survécu à la chute d'Alterac et à tous ces ogres aussi !\n\nMerci, &lt;nom&gt;. Merci mille fois ! Vous avez contribué à la préservation de la connaissance humaine, et vous ajoutez au prestige de la Bibliothèque royale de Stormwind.", rewards = "Vous recevrez :\n\n"},
[543] = {title = "La tiare de Perenolde", objective = "Apporter la Tiare de Perenolde à Remington Ridgewell, à Stormwind.", description = "La Tiare de Perenolde est un ancien héritage des \"nobles\" de Perenolde, la famille régnante d'Alterac, avant que ce royaume ne tombe en ruine. On dit qu'elle a été réalisée par des maîtres bijoutiers à Ironforge, et qu'elle est ornée des émeraudes les plus pures.\n\nQuand Alterac a été détruite, la Tiare fut perdue. Mais les rumeurs disent qu'un ogre-mage, Grel'borg l'Avare, l'a trouvée, et qu'il fouille à présent les Ruines d'Alterac à la recherche d'autres trésors.\n\nNous aimerions que vous récupériez la Tiare pour nous.", progress = "Salutations, <nom>. Essayez de ne pas marcher sur mon revers de pantalon. Le vêtement vient à peine d'être ajusté.", completion = "Ah ! voilà qui est splendide. Elle aura besoin d'un bon nettoyage, bien sûr, mais vous vous êtes vraiment surpassé, &lt;nom&gt;. Quelqu'un s'occupera de préparer la tiare et de la placer dans notre collection au plus vite.\n\nComme je suis certain que vous serez d'accord, notre gratitude est aussi grande que notre collection.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[544] = {title = "L'invasion de la prison", objective = "Trouver les traîtres et récupérer les artefacts, puis retourner voir le magus Voidglare à Moulin-de-Tarren.", description = "Je suis venu à Moulin-de-Tarren pour effectuer des recherches, mais je dois à présent résoudre une crise. Voyez-vous, quatre Réprouvés se sont enfuis d'Undercity il y a quelques mois. Ils ont trahi leurs semblables, mais pire encore : ils ont volé la Dame noire.\n\nCes voleurs ont forcé un coffre et se sont emparés de quatre artefacts, des objets dont nos apothicaires ont besoin pour leurs études. Dame Sylvanas veut récupérer ces artefacts.\n\nLes voleurs ont fui à Dalaran, et là-bas les sorciers les ont placés en quarantaine dans le Camp d'internement de Lordamere.", progress = "Avez-vous trouvé les voleurs ? Et plus important, avez-vous ramené ce qu'ils ont volé ?", completion = "Vous avez rendu un grand service aux Réprouvés, &lt;nom&gt;. Ces artefacts nous manquaient beaucoup.\n\nEt il est bon de savoir que Kegan et les autres traîtres ont rencontré la justice.", rewards = "Vous recevrez :\n\n"},
[545] = {title = "Les patrouilles de Dalaran", objective = "Tuer 6 Invocateurs de Dalaran et 12 Esclaves élémentaires, puis retourner voir le magus Voidglare à Moulin-de-Tarren.", description = "Les Sorciers de Dalaran ont construit un vaste dôme magique autour du cœur de leur cité. Certains croient qu'il s'agissait de se protéger des violences de cette époque, d'autres pensent qu'ils recherchaient simplement la solitude, pour étudier et comploter.\n\nJe ne m'intéresse pas à la raison. En revanche, ce qui m'intéresse, c’est que la périphérie de la ville en ruine, autour du dôme, puisse abriter des trésors magiques.\n\nMais les Sorciers et leurs Esclaves élémentaires patrouillent ce secteur.\n\nChassez-les donc, et revenez lorsque leur nombre sera conséquemment réduit.", progress = nil, completion = "Très bien. Ces ruines sont à présent suffisamment sécurisées pour que nous puissions commencer les recherches, si l'on est assez prudent. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[546] = {title = "Souvenirs de morts", objective = "Le Garde noir Samsa du Moulin-de-Tarren veut 30 Crânes d'humains d'Hillsbrad.", description = "J'ai entendu dire que vous étiez <recruté/recrutée> par Darthalia pour mener l'offensive contre les humains d'Hillsbrad. Je vous envie tellement…\n\nTandis que vous vous amuserez – à tuer des humains, à piller, à terroriser les innocents – je resterai coincé ici, à Moulin-de-Tarren, à monter la garde et à me morfondre.\n\nPeut-être prendrez-vous en pitié un vieux Garde noir comme moi ? Vous remarquez que je fais la collection de crânes. Et vous allez combattre des humains pendant quelque temps, je crois. Au gré de votre longue bataille, vous récolterez bien quelques crânes, apportez-moi-en 30 et je vous rendrai la pareille d'une belle façon.", progress = "Ainsi le chanceux <nom> est de retour ? Combien d'humains avez-vous massacré aujourd'hui ? Des centaines j'espère !\n\nAvez-vous quelques crânes pour moi ?", completion = "Précieux crânes. Ils sont tellement beaux ! Je vous suis redevable, &lt;nom&gt;, comme promis.", rewards = "Vous recevrez :\n\nAnneau du crâne"},
[547] = {title = "Epée d'Humbert", objective = "Retrouver l'Epée du Garde noir Humbert et la lui retourner à Moulin-de-Tarren.", description = "La Grande Exécutrice Darthalia m'a envoyé surveiller Dun Garok de loin. J'ai établi mon camp juste au-delà de leur champ de vision. Mais ce matin, pour faire bouillir de l'eau, je suis allé chercher du bois.\n\nQuand je suis revenu au camp, j'ai découvert que mon équipement avait disparu.\n\nApparamment, des éclaireurs nains de Dun Garok sont passés par là et repartis avec mon matériel. J'ai besoin de mon épée ! Si vous pouviez la retrouver et me la rendre, je serais tellement reconnaissant. Il y a tellement de nains par ici. Ça va être très difficile de retrouver le sale petit voleur qui l'a dérobée.", progress = "Avez-vous pu retrouver mon épée, <nom> ? La Grande Exécutrice Darthalia me pendra haut et court si elle découvre ma sottise.", completion = "Vous l'avez trouvée !\n\nAh ! je me sens enfin entier avec ma si précieuse épée à nouveau en main. Merci infiniment à vous !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCuirasse côteléeJambières des mercenaires\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[549] = {title = "ON RECHERCHE : Personnel du Syndicat", objective = "Tuer 10 Voleurs et 10 Gardiens du Syndicat, puis aller voir la Grande Exécutrice Darthalia à Moulin-de-Tarren pour votre récompense.", description = "Au nom de l'autorité de Dame Sylvanas, tous les membres de l'organisation connue sous le nom du Syndicat sont recherchés. Ceux conduits à la garde ou faits prisonniers seront sommairement exécutés. Nous savons qu’actuellement ils se rassemblent dans les ruines du Donjon de Durnholde, au sud-est de Moulin-de-Tarren.\n\nUne récompense est offerte à quiconque apporte la preuve de ses actions à la Grande Exécutrice Darthalia.", progress = nil, completion = "Excellent, &lt;classe&gt;. A ce rythme, on se débarrassera de cette peste de Syndicat en un rien de temps.", rewards = "Vous recevrez :\n\n"},
[550] = {title = "La bataille d'Hillsbrad", objective = "Apporter la Recommandation scellée à Varimathras à Undercity.", description = "Comme vous avez combattu avec valeur à la bataille d'Hillsbrad, j'ai écrit cette recommandation exaltant vos prouesses au combat, pour que le haut commandement les apprécie.\n\nApportez cette Recommandation scellée à Varimathras à Undercity. Allez avec fierté, <classe>.", progress = "Qu'est-ce qui peut bien conduire des druides depuis le lointain champ de bataille jusqu'à Undercity ?", completion = "Ainsi, vous êtes le célèbre &lt;classe&gt; qui a porté un coup si décisif aux forces de l'Alliance dans les contreforts d'Hillsbrad ? Les récits de vos exploits ont rapidement atteint Undercity.\n\nVous avez de l'avenir dans les rangs de la Dame noire si vous continuez à montrer une telle capacité à diriger et une telle expertise au combat.\n\nNotre principal souci reste l'armée du Fléau du roi-liche qui descend du Nord, mais le \"problème\" des humains continue à entraver nos plans de bataille. Vous avez cependant démontré qu’ils peuvent et vont tomber.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon de rituel funéraireBouclier Tête de mortNoirâtre runique\n\nVous recevrez également :\n\nAnneau d'Undercity"},
[551] = {title = "Le Parchemin ensorcelé", objective = "Apporter le Parchemin ensorcelé à l'Erudit Dibbs à Southshore.", description = "Ce parchemin est sous l’effet d’un sort qui le rend indéchiffrable. Mais un mot peut être lu, en haut du papier :\n\n\n  Nagaz\n\n", progress = "Oh ! vous avez quelque chose à me montrer ? Quelques fragments de connaissance trouvés dans la montagne, j'espère…", completion = "Encore du texte codé ? J'aimerais avoir les talents nécessaires pour déchiffrer tous les étranges petits morceaux d'écriture. Mais j'ai bien peur de ne pas avoir cette connaissance.", rewards = "Vous recevrez :\n\n"},
[552] = {title = "La vengeance d'Helcular", objective = "Reprendre le Bâtonnet d'Helcular aux yétis et la ramener au novice Thaivand à Moulin-de-Tarren.", description = "Maître Helcular avait presque achevé sa transformation en liche lorsqu'une bande d'humains furieux a découvert son repaire dans les collines et l'a tué. Pour rendre les choses encore pires, ils ont enterré son corps au cimetière de Southshore.\n\nUn tel manque de respect envers un si grand sorcier n'est pas acceptable. Etant son apprenti, je veillerai à ce que la pluie de la vengeance tombe drue sur la ville de Southshore.\n\nAvant tout, nous avons besoin du Bâtonnet d'Helcular. Les yétis ont atteint son repaire. L'une de ces bêtes l'a sans doute emporté.", progress = "Avez-vous déjà retrouvé le Bâtonnet d'Helcular ? Il y a tellement de yétis dans cette région, il va être difficile de la trouver. Mais nous devons l'obtenir pour pouvoir agir.", completion = "Vous l'avez ! Parfait, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[553] = {title = "La vengeance d'Helcular", objective = "Charger le Bâtonnet d'Helcular des pouvoirs de la Flamme d'Azel, de la Flamme de Veraz et de la Flamme d'Uzel.\n\nEnfoncez le Bâtonnet chargé dans la tombe d'Helcular à Southshore.", description = "Tenez, prenez le Bâtonnet d'Helcular. Vous en aurez besoin.\n\nHelcular a fabriqué 3 bûchers cérémoniels comme composants de son sort le plus puissant. La Flamme d'Azel et la Flamme de Veraz brûlent dans l'une des cavernes des contreforts. La Flamme d'Uzel éclaire une cave située plus haut et plus au nord dans les montagnes.\n\nUne fois le Bâtonnet d'Helcular chargé avec ces trois flammes, il faut l’enfoncer dans la tombe d'Helcular située à Southshore. La vengeance sera nôtre.", progress = "La tombe d'Helcular déborde d'une énergie mystique.", completion = "Le sol émet un grondement puissant.", rewards = "Vous recevrez :\n\n"},
[554] = {title = "Stormpike décode", objective = "Apporter le Parchemin ensorcelé au Prospecteur Stormpike à Ironforge.", description = "Le Prospecteur Stormpike est un maître du décodage. Si vous lui amenez le parchemin que vous avez trouvé, alors, avec un peu de chance, il peut en saisir la signification. Stormpike étudie en ce moment aux quartiers généraux des Prospecteurs à Ironforge.\n\nEt quand vous le verrez dites-lui que vous m'avez parlé. Je lui ai envoyé beaucoup de choses dernièrement.", progress = "Encore des interruptions ?\n\nHa, il y a sur ce parchemin un sort élaboré avec finesse et extrêmement complexe. Je peux le comprendre, évidemment, mais cela va me prendre du temps. Et le temps m'est très précieux...\n\nPeut-être puis-je tout simplement vous l'acheter ?", completion = "Une sage décision. Je ne pense pas qu'il y ait d'autres érudits qui puissent traduire ce parchemin. Et s'il contient quelque chose d'intéressant, ne vous inquiétez pas, je vous tiendrai au courant.", rewards = "Vous recevrez :\n\n"},
[555] = {title = "Bisque de tortue apaisante", objective = "Apporter 10 morceaux de Viande de tortue et des Epices apaisantes au Chef Jessen à Southshore.", description = "S'il y a une chose que vous apprendrez à propos de Southshore, c'est que nous avons l'une des meilleures cuisines au nord de Stormwind !\n\nPrenez ma recette secrète de bisque de tortue, par exemple. J'en ai connu qui ont fait le voyage depuis Darkshire juste pour en déguster une coupe. Mais il y a bien longtemps que je n’en ai pas fait. J'allais au-delà de Dalaran, jusqu'au lac de Lordamere, mais c'est trop dangereux à présent. Si vous m'apportiez de la Viande de tortue, venant du nord, et des Epices apaisantes, je vous mitonnerai un bon petit plat.", progress = "Vous avez les ingrédients ? Je vais vous dire : ce territoire n'est plus aussi paisible qu’autrefois. Ah ! si seulement ces troubles n'étaient jamais apparus…", completion = "Tout le monde va être tellement content. La Bisque apaisante de tortue du Chef Jessen est servie à nouveau.", rewards = "Vous recevrez :\n\nRecette : Bisque de tortue apaisanteBisque de tortue apaisante"},
[556] = {title = "Les Runes gravées", objective = "Apporter 10 Runes gravées au Conservateur Bel'varil à Moulin-de-Tarren.", description = "Un sérieux atout des sorciers de Dalaran est leur familiarité avec les élémentaires, ces créatures puissantes venant d'autres dimensions. Les sorciers utilisent des Runes gravées pour contrôler ces élémentaires. Le magus Voidglare aimerait étudier certaines de ces runes.\n\nPénétrez sur le territoire des sorciers de Dalaran, à l'ouest d'Hillsbrad, et trouvez-en.\n\nIl se peut que vous les trouviez sur n'importe quel citoyen de Dalaran, mais je suggère que vous vous les procuriez au camp d'internement. C'est un endroit moins dangereux que Dalaran.", progress = "Avez-vous les runes gravées, <nom> ? Le magus a hâte de connaître leurs secrets.", completion = "Ce sera parfait. Bien qu'il semble que leur magie ait disparu, il est préférable que les premières expérimentations du magus portent sur de tels échantillons. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[557] = {title = "Les Bracelets de liaison", objective = "Apporter 4 Brassards de liaison de terre au Conservateur Bel'varil à Moulin-de-Tarren.", description = "Le magus sera très occupé à étudier ces runes gravées que vous avez apportées, mais je sais que tôt ou tard il voudra des échantillons de leurs contreparties : des brassards de liaison. Ce sont des brassards qui, passés aux poignets des élémentaires, les lient au service des mages.\n\nChassez des élémentaires dans les ruines de Dalaran et récupérez leurs brassards de liaison de terre. Le magus en sera très satisfait.", progress = "Hello, <nom>. Les élémentaires sont des proies difficiles, mais je sais que vous en êtes capable. Avez-vous ces Brassards de liaison ?", completion = "Vous en avez trouvé. Je pense que les élémentaires à qui vous avez pris les brassards étaient disposés à entendre raison ?\n\nHum… La mort n'a pas seulement arrêté mon cœur, elle m'a dépouillé de tout sens de l’humour, il semblerait...\n\nBien, merci, &lt;nom&gt;. Vous êtes au service du magus, et donc de la Dame noire également.", rewards = "Vous recevrez :\n\n"},
[558] = {title = "L'autographe de Jaina", objective = "Allez à Theramore pour tenter d'obtenir un autographe de dame Jaina Proudmoore pour votre protégé.", description = "On dit que dame Jaina Proudmoore, à Theramore, est l'une des plus grands héroïnes de l'Alliance de tous les temps. Quand je serai grand, je veux aussi être un héros de l'Alliance !\n\nVous connaissez Jaina, <nom> ? Vous pouvez me faire une faveur, s'il vous plaît ? Vous pouvez m'avoir un autographe de dame Jaina ? Je sais pas comment lui demander, et c'est sans doute une personne bien trop occupée pour s'occuper de quelqu'un comme moi... Mais pas vous ! Vous êtes <un aventurier/une aventurière>, comme elle ! Je parie qu'elle vous donnerait facilement un autographe !\n\nS'il vous plaît ?", progress = "Un jour, je serai un héros comme Jaina... Enfin, elle, c'est une héroïne, moi, je serai un héros.", completion = "OUAH ! Vous avez l'autographe de dame Jaina pour moi ! Merci beaucoup ! Et... Ouah... elle m'a même écrit un message personnel... Rien que pour moi ! Je savais qu'elle était géniale, et peut-être qu'un jour je la remercierai moi-même... Quand je serai devenu un héros de l'Alliance !\n\nVous êtes le meilleur, &lt;nom&gt;. Merci d'avoir été aussi gentil avec moi.", rewards = "Vous recevrez :\n\n"},
[559] = {title = "La preuve de Farren", objective = "Collecter 10 Têtes de murlocs sur les murlocs du Rivage occidental pour le lieutenant Farren Orinelle à Southshore.", description = "Le croirez-vous, <nom> ? Redpath n'était pas satisfait, en dépit de tous les murlocs que nous avons tués. Ah ! ne soyez pas modeste, vous y avez participé. À présent il veut que je lui apporte la preuve de leur mort, en allant chercher les têtes refroidies de ces misérables murlocs, pour les soumettre à sa validation.", progress = "Avez-vous toutes vos têtes, <nom> ?", completion = "Oh ! pour l'amour de la Lumière… Elles dégoulinent.\n\nJe ne peux pas toucher ces choses moi-même. Le poisson c’est très bon, mais quand il lui pousse des pattes et qu'il commence à marcher… J'ai pas mangé de poisson depuis une semaine, et laissez-moi vous dire qu’à Southshore, ils mangent pas beaucoup ces derniers temps.", rewards = "Vous recevrez :\n\n"},
[560] = {title = "La preuve de Farren", objective = "Livrer le Sac de têtes de murlocs au maréchal Redpath à Southshore.", description = "Vous savez, <nom>, je préférerais ne pas toucher à ces têtes… Puisque vous avez déjà les mains qui sentent le poisson, cela vous dérangerait-il de les livrer à Redpath pour moi ?", progress = "Salutations, citoyen. Êtes-vous venu soutenir la sécurité de Southshore ?", completion = "Un garçon de courses de Farren, n'est-ce pas ? Si vous avez aidé Farren à se procurer ces têtes, alors merci. Southshore a besoin de personnes qui travaillent dur pour maintenir sa sécurité.", rewards = "Vous recevrez :\n\n"},
[561] = {title = "La preuve de Farren", objective = "Parler au Lieutenant Farren Orinelle à Southshore.", description = "Veuillez informer le lieutenant Orinelle que j'aimerais qu'il concentre ses efforts sur les nagas qui infestent le Rivage oriental. Quand il aura obtenu des résultats, dites-lui qu'il vienne en personne m'en rendre compte.", progress = nil, completion = "Les nagas, hein ? Redpath doit avoir reçu la même information que moi… Ah ! Il ne recueillera pas la promotion de mon labeur. Je m’explique...", rewards = "Vous recevrez :\n\n"},
[562] = {title = "Stormwind me voilà", objective = "Tuer 10 Chasseurs du Rivage et 10 Sirènes Daguéchine pour le lieutenant Farren à Southshore.", description = "Mon ancien mentor à la garde de la cité de Stormwind a envoyé un message me disant que le Haut Commandement de l'Alliance commence à s'inquiéter du problème posé par les nagas. D'après ce qu'il a entendu, il y a des chances de promotion, ou d'une bonne affectation, pour quiconque se montrera valeureux dans la résolution de ce problème.\n\nIl y a juste quelque chose qui ne va pas... Je ne peux pas m'occuper des nagas, <nom>. Oh bien sûr, je pourrais disperser une querelle d'ivrognes, ou alpaguer un clochard vindicatif, mais les nagas c’est trop pour moi. Vous devez m'aider, <nom>.", progress = "J'ai une lettre prête à partir pour le major Samuelson à Stormwind. Je n'ai besoin que de résultats.", completion = "Avec la déconfiture des nagas de Southshore, je suis à deux doigts d'obtenir une nouvelle affectation. Je vais voir Stormwind à nouveau et quitter ce port oublié de la Lumière.", rewards = "Vous recevrez :\n\nEviscératrice"},
[563] = {title = "Nouvelle affectation", objective = "Remettre le Rapport de Farren au major Samuelson au Donjon de Stormwind.", description = "Que mon rapport soit lu ne devrait pas poser de problème. Le nouveau capitaine de la Garde, le major Samuelson, était mon mentor lorsque j'étais posté à Stormwind. Cela devrait lui donner suffisamment d'arguments pour que j'y sois à nouveau transféré. Je vais avoir besoin de vous pour porter mon rapport. Cependant, je n'aimerais pas que ce cher Redpath comprenne.", progress = "Salutations, citoyen. La Garde de la cité de Stormwind pourrait-elle vous être d'une quelconque assistance ?", completion = "Qu'est-ce que c'est ? Ha ! Ainsi mon élève préféré s'est dressé personnellement contre les nagas à Southshore. Merci de m'apporter ceci, j'en tiendrai certainement compte lors des affectations, le mois prochain.", rewards = "Vous recevrez :\n\n"},
[564] = {title = "Un problème très coûteux", objective = "Darren Malvew de Southshore veut que vous tuiez 8 Lions des montagnes et 10 Lions des montagnes massifs.", description = "Y'a rien qui m'hérisse plus que d'perdre ces beaux ch'vaux, là. Et croyez-moi, on en a perdu pas mal, entre ces sales morts-vivants, c'fichu gang du Syndicat, et toutes les aut' crapules bonnes à rien qui traînent dans l'secteur.\n\nMais j'jure sur la tombe d'mon vieux grand-père qu'y a pas d'danger plus grand pour les ch'vaux que ces lions d'montagne en haut à Alterac.\n\nIls s'ramènent toujours des collines et m'rendent la vie difficile !\n\nVous croyez être <un héros/une héroïne> ? Allez-y et faites quek'chose pour y r'médier.", progress = nil, completion = "Voilà t’y pas des bonnes nouvelles. J'aurais dû y aller et m'trouver un bon vieux héros dès l'premier jour pour s'occuper d'ces bêtes. Vot' grand-père s'rait fier de vous, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinturon de bergerGants de berger\n\nVous recevrez également :\n\nRecette : Délicieux steak de lionDélicieux steak de lion"},
[565] = {title = "La cape en fourrure de yéti de Bartolo", objective = "Apporter à Bartolo Ginsetti de Southshore une Pelote de laine, une Cape d'homme des collines, du Fil fin et 10 Touffes de fourrure de yéti.", description = "Moi, le Grand Bartolo, je confectionnerai pour vous ma fameuse cape en fourrure de yéti, célèbre dans le monde entier, et qui fait la renommée de l'Alliance !\n\nJe vous mets au défi de parcourir le monde pour trouver meilleure cape. Oh ! attendez, qu'est-ce que vous dites, <petit/petite> <nom> ? \"Bartolo, il n'existe pas de meilleure cape !\" Oui, oui, je sais, j'ai entendu ça des milliers de fois déjà.\n\nBartolo demande une pelote de laine, une cape d'homme des collines confectionnée par un habile tanneur, du fil fin et bien sûr de la fourrure de yéti. Apportez-moi tout cela et vous serez <un client satisfait/une cliente satisfaite>.", progress = "Ainsi vous revenez voir le grand Bartolo. Peut-être avez-vous trouvé tous les éléments nécessaires à la confection de votre superbe cape en fourrure de yéti ? Ou peut-être aimez-vous simplement côtoyer la magnificence que je personnifie, moi, Bartolo !", completion = "À présent, il est temps pour le grand Bartolo d’endosser son habit de magicien ! Je n'ai pas besoin de bâton de sorcier, ni de bâtonnet de mage. Car moi, le Grand Bartolo, fais de la magie avec une simple aiguille et du fil.", rewards = "Vous recevrez :\n\nCape en fourrure de yéti"},
[566] = {title = "ON RECHERCHE : baron Vardus", objective = "Tuer le baron Vardus et apporter sa tête à la Grande Exécutrice Darthalia, au Moulin-de-Tarren.", description = "Par décret de la Grande Exécutrice Darthalia, l'humain connu sous le nom de baron Vardus est recherché pour crime contre les Réprouvés. Nous savons que Vardus est un membre haut placé de l'organisation dite le Syndicat.\n\nIl a été vu pour la dernière fois dans les Hauteurs des montagnes d'Alterac, au nord de Moulin-de-Tarren.\n\nIl doit être ramené mort. Apportez une preuve de son trépas à la Grande Exécutrice Darthalia pour obtenir votre récompense.", progress = "Ah ! <nom>. Peut-être êtes-vous venu chercher la prime associée à la mort du baron Vardus ?", completion = "Un travail productif que le vôtre, &lt;nom&gt;. Le baron Vardus mort, le nombre des leaders du Syndicat s'amenuise. La résistance qu'ils opposent et l'irritation qu'ils suscitent ne vont plus faire long feu.", rewards = "Vous recevrez :\n\nRobe d'Inferno"},
[567] = {title = "Dangereux !", objective = "La Grande Exécutrice Darthalia de Moulin-de-Tarren offre une prime pour la mort du Commis Horrace Whitesteed, du Citoyen Wilkes, du Mineur Hackett et de Kalaba la fermière.", description = "Dangereux !\n\nLes humains d'Hillsbrad dont les noms suivent ont été déclarés dangereux et leurs têtes sont mises à prix par la Grande Exécutrice Darthalia :\n\nCommis Horrace Whitesteed. Recherché pour le meurtre du Garde noir Toma.\n\nCitoyen Wilkes. Recherché pour le meurtre de l'Apothicaire Eli.\n\nMineur Hackett. Recherché pour le meurtre du Traqueur noir Fry.\n\nKalaba la fermière. Recherchée pour détournement de marchandises à Undercity.\n\nChacun de ces ennemis se cache et sera difficile à débusquer. Une récompense sera remise à la preuve de leur mort.", progress = nil, completion = "Vous êtes vraiment le chasseur de primes incarné, &lt;classe&gt;. Bon travail.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc des pilleursTarge de factionnaireBaguette carbonisée\n\nVous recevrez également :\n\nCapuche simple"},
[568] = {title = "La défense de Grom'gol", objective = "Le commandant Aggro'gosh du campement Grom'gol veut que vous tuiez 15 Raptors flagellants.", description = "Throm'ka, <classe> !\n\nVotre arrivée à Grom'gol tombe à point nommé. Je commande ce campement camp ici dans la jungle, au nom du Chef de guerre. Je suis tenu sur l'honneur d'assurer la sécurité de tous les membres de la Horde. Notre mission consistant à maintenir une chaîne d'approvisionnement jusqu’à Stonard est entravée par certaines espèces locales.\n\nJe vous charge de réduire la population des raptors autour de Grom'gol. Une fois que vous aurez accompli des progrès significatifs, revenez me voir pour que je vous assigne une nouvelle mission.", progress = nil, completion = "Vous avez accompli votre devoir avec honneur, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[569] = {title = "La défense de Grom'gol", objective = "Le commandant Aggro'gosh du campement Grom'gol veut que vous tuiez 10 Brutes et 5 Sorciers ogres.", description = "La première fois que nous sommes arrivés dans cette jungle, nous n'avions pas l'intention de déclarer la guerre aux tribus locales. Notre mission d’approvisionnement de Stonard est de la plus haute priorité. Mais des complications ont surgi. Un groupe d'ogres occupe les Ruines de Mizjah au sud-est de Grom'gol. Malgré nos avertissements, ils continuent à tendre des embuscades à nos caravanes.\n\nJe vous ordonne de vous occuper de ces ogres peu coopératifs. Allez vers les ruines et délogez-les de la région. Au moins, cela enverra un message fort.", progress = nil, completion = "Beau travail. Vous avez servi le Chef de guerre avec honneur.", rewards = "Vous recevrez :\n\nTarge de Grom'gol"},
[570] = {title = "Enchantement de Mok'thardin", objective = "Le prophète Mok'thardin du campement Grom'gol veut que vous trouviez 8 Griffes de panthère Ombregueule et 1 Croc de tigresse en parfait état.", description = "Le pouvoir de la magie de la jungle doit être compris et acquis par la Horde. Mes rituels se sont montrés efficaces jusque-là. Je peux lancer des enchantements très puissants. Pour vous, brave <classe>, je vais réaliser un objet très spécial.\n\nRamenez-moi quelques griffes de panthère Ombregueule et un croc de tigresse. Mais pas n'importe quel croc. Il doit être dans un état parfait.\n\nCes bêtes vivent cachées dans la jungle, mais vous en trouverez pas loin, juste de l'autre côté de la rivière, depuis les ruines de Mizjah au sud-est.", progress = "Quelles nouvelles apportez-vous ?", completion = "Vous avez une grande connaissance de la jungle, &lt;nom&gt;. Ces échantillons sont parfaits. Je vais remercier les esprits d'avoir sacrifié de si belles bêtes pour la cause de la Horde.", rewards = "Vous recevrez :\n\n"},
[571] = {title = "Enchantement de Mok'thardin", objective = "Apporter un Tendon d'Ancien gorille de Valbrume au Prophète Mok'thardin à Grom'gol.", description = "Ce dont j'ai besoin va être très difficile à obtenir. Pour tenir ensemble ces plumes, griffes et ce croc parfait, il me faut une longe magique. Seul un tendon de gorille fera l'affaire.\n\nVous ne pourrez en trouver un que sur un ancien gorille de Valbrume. On sait que ces animaux fourragent à l'est de Baie-du-Butin.\n\nLe tendon doit être parfait. Il se peut que vous deviez en tuer plus d'un pour trouver exactement ce dont j'ai besoin, mais cela en vaudra la peine.", progress = "Est-ce que la fortune vous accompagne, <nom> ? Avez-vous obtenu un tendon d'ancien gorille ?", completion = "Un tendon plus que parfait, &lt;nom&gt;. Vos efforts vont bientôt finir par payer.", rewards = "Vous recevrez :\n\n"},
[572] = {title = "Enchantement de Mok'thardin", objective = "Amener 10 Plumes de Traqueurs de la jungle au Prophète Mok'thardin au campement Grom'gol.", description = "Les matériaux que vous avez collectés sur les félins de la vallée n'étaient que les premiers ingrédients d'un puissant objet enchanté. Ces babioles de la jungle combinées à mon rituel chamanique vous fourniront un outil très puissant, au service de la Horde et du Chef de guerre.\n\nMais pour l'heure vous devez rassembler pour moi quelques plumes de Traqueurs de la jungle. Ces créatures portent des généralement des plumes sur leurs bras. Vous trouverez un groupe de raptors au sud de Grom'gol, non loin de la grande arène.", progress = "Vos efforts pour collecter certains produits ont-ils porté leurs fruits ?", completion = "Parfait. Je vais les préparer tout de suite.", rewards = "Vous recevrez :\n\n"},
[573] = {title = "Enchantement de Mok'thardin", objective = "Le Prophète Mok'thardin de Grom'gol a besoin d'Eau de source sacrée. Il veut que vous tuiez aussi 10 Explorateurs nagas.", description = "Il ne manque plus qu'un dernier réactif pour compléter l'enchantement.\n\nAu sud, vers la côte occidentale, loin au-delà des falaises, coule une source sacrée. Elle est à l'origine d'un conflit parmi les érudits mystiques et religieux. Chaque race d'Azeroth proclame que cette source a été rendue divine pour ses propres populations.\n\nLa dernière demande que je vous fais : apportez-moi de l'Eau de source sacrée. Mais attention. Les nagas ont envoyé des explorateurs qui progressent vers la source. Vous devrez également vous en occuper.", progress = "Je suis presque prêt à accomplir l'enchantement. Et vous, où en êtes-vous ?", completion = "Avec cette Eau de source sacrée, le Foulard cérémoniel est prêt à l'enchantement.\n\nPortez-le avec fierté, &lt;nom&gt;, au nom du Chef de guerre et pour la défense de la puissante Horde.", rewards = "Vous recevrez :\n\nCollier du Grand chaman"},
[574] = {title = "Forces spéciales", objective = "Tuer 10 Commandos et 6 Réducteurs de têtes de Kurzen. Rendre compte au Lieutenant Doren au Camp rebelle.", description = "Maintenant que de nombreux hommes de troupe sont morts, vous devez combattre ses forces hautement entraînées. Lorsqu'ils ne sont pas dans la nature à massacrer nos soldats rebelles, on peut les trouver au fond de la Base de Kurzen, dans un endroit qu'ils appellent la Réserve.\n\nJe connais personnellement beaucoup des hommes de Kurzen, et sais qu'ils sont entraînés, loyaux et cruels. Ce n'est pas une tâche facile que je vous confie là, <nom>.\n\nAprès les avoir battus, rendez compte au Lieutenant Doren, mon officier commandant. Il voudra votre rapport en priorité.", progress = "Yohwa me dit que vous êtes compétent et courageux, <classe>. Avez-vous un compte rendu à me faire ?", completion = "&lt;nom&gt;. Le sergent Yohwa a confiance en vos capacités, et j'ai confiance en elle. La défaite que vous avez infligée aux forces de Kurzen est plus que nous ne pouvions espérer. J'avais peur que nous autres rebelles soyons seuls, et seuls nous ne pourrions jamais avoir la moindre chance contre le génie du colonel.\n\nIl se peut qu’il existe quelques chances de survie.", rewards = "Vous recevrez :\n\n"},
[575] = {title = "L'offre et la demande", objective = "Apporter 2 Grandes peaux de crocilisque des rivières à Drizzlik, à Baie-du-Butin.", description = "“Le meilleur artisan du cuir des mers du Sud et des deux mondes, Ancien et Nouveau”. C’est comme ça qu’on m’appelle. Moi ! Drizzlik ! Le meilleur artisan… Hem. Bon.\n\nMes objets en cuir sont réputés dans le monde entier pour leur perfection – le vrai choix des connaisseurs !\n\nJe viens de recevoir une commande du directeur Riddlevox du Syndicat des Artisans. Il veut une douzaine de ses bottes préférées, le modèle Excelsior (notre meilleure vente, soit dit en passant.)\n\nPour mettre en place la forme, j’ai besoin de peaux de crocilisques. Vous trouverez les meilleurs spécimens le long des rivières, dans le nord de Strangleronce.", progress = "Mon matériel est prêt, <nom>, j'ai juste besoin de ces peaux. Nous ne voudrions pas que Riddlevox attende, pour sûr.\n\nCe ne serait bon pour personne que le principal membre du Syndicat des artisans ne soit pas satisfait.", completion = "Ces peaux feront l'affaire. Leur qualité n'est pas très importante, vu qu'elles serviront à doubler l'intérieur des bottes, mais elles doivent quand même être confortables.\n\nSi elles sont un peu trop raides, j'utiliserai du sang de tigre pour les assouplir un peu. Les p'tits trucs du métier, vous voyez ce que c'est...", rewards = "Vous recevrez :\n\n"},
[576] = {title = "Gardez un œil dehors", objective = "Dizzy le Borgne de Baie-du-Butin veut que vous récupériez son œil chez les boucaniers de la Voile sanglante.", description = "Eh, qui va là ?\n\nArgh, je ne vaux rien sans mon œil enchanté spécial. J'aurais pas dû perdre mes yeux à la guerre pour commencer ! Mais par chance, nous avons débarqué à Menethil et un sorcier de passage a enchanté un œil de verre spécial qui me permet de voir à nouveau.\n\nLa nuit dernière, je me suis retrouvé agressé par des boucaniers de la Voile sanglante alors que je rentrais. Ils ont pris mon œil, oh oui ! On dirait que ces types se sont vite adaptés à Baie-du-Butin.\n\nVous voulez aider un vieux loup de mer à récupérer son œil ?", progress = "Ahoy, mon pote ! Je ne peux pas vous voir, mais je peux vous sentir venir depuis la moitié du chemin qui mène au port.\n\nJ'aimerais vraiment récupérer mon œil. Le capitaine va me faire passer sous la quille s'il découvre que mon œil est aux mains de ces sales boucaniers de la Voile sanglante.\n\nÀ quoi sert une vigie qui ne voit rien ? Le nid de pie était ma maison... Sans mon lampion je serai déjà chanceux si je nettoie le fond de cale.", completion = "Efficace et pas cher, c'est &lt;nom&gt; que je préfère. Vous avez trouvé mon magnifique œil ! Voyons s'il tient toujours.\n\nMerci beaucoup, j'y vois bien mieux maintenant !", rewards = "Vous recevrez :\n\nCape de sombreflux"},
[577] = {title = "Un peu d'assemblage est nécessaire", objective = "Apporter 5 Peaux de Gueule d'acier à Drizzlik, à Baie-du-Butin.", description = "Bien, la forme des bottes est finalisée et elles se présentent bien, mais les peaux que vous avez amenées ne suffiront pas pour l'intérieur.\n\n\"Alors que faire, Drizzlik ?\"... La question vous brûle sûrement les lèvres, et n'est-ce pas heureux que vous parliez à Drizzlik justement, parce qu'il va vous dire ce que l'on va faire !\n\nOn ne pourra jamais vraiment voir l'intérieur, alors on va juste récupérer de la peau plus épaisse et moins onéreuse sur les crocos autour du lac Nazfériti pour ça.", progress = "Les bottes en cuir Excelsior de Drizzlik, du bel ouvrage, des bottes uniquement fabriquées à partir de peaux de crocilisque marin de la plus haute qualité. Impossible de faire mieux.\n\nOn ne peut pas battre une si brillante description, pas vrai ?\n\nA part, peut-être, si vous avez ces peaux pour moi ?", completion = "Mes bottes… elles sont comme des saucisses, &lt;nom&gt;. Elles ont l'air super, et elles ont un super goût. Je vous dis qu'elles sont remplies de rien de moins que les meilleurs ingrédients et les meilleures viandes, et si vous les mangez, vous les aimerez.\n\nC'est plus sûr, et plus agréable, de me croire sur parole, et ne demandez pas trop ce qu'il y a vraiment à l'intérieur.", rewards = "Vous recevrez :\n\n"},
[578] = {title = "La Pierre des marées", objective = "Localiser l'Ile hantée pour le baron Revilgaz de Baie-du-Butin.", description = "Si un mage gobelin et des élémentaires d'eau hantent effectivement l'île, cela peut vouloir dire que la Pierre des marées peut être mienne !\n\nJe veux que vous localisiez cette île hantée… Découvrez ce qui s'y passe. Oh ! et si vous voulez en savoir plus sur la Pierre des marées, donnez ce titre à la bibliothèque de Stormwind, ils devraient être capables de vous trouver une copie du livre dans lequel j'ai eu vent pour la première fois de cette légende.\n\nSerait-ce possible que ce Gazban ait vraiment découvert la Pierre... ?", progress = nil, completion = "Ainsi, la légende disait vrai ! Incroyable !\n\nNous devons cependant découvrir un moyen de briser la malédiction de la Pierre des marées, si nous voulons la récupérer. La malédiction étant une affaire de magie, nous allons faire appel à l'un de ces sorciers pour nous aider.", rewards = "Vous recevrez :\n\n"},
[579] = {title = "La Bibliothèque de Stormwind", objective = "Le Roi Anduin accorde une grand importance à l'éducation, et c'est pourquoi il a débloqué des fonds pour rendre accessible au public des copies de divers ouvrages et écrits. C'est très simple. Vous me donnez un titre de bibliothécaire, et je puis vous fournir la copie de l'un des livres disponibles.", description = nil, progress = "Le Roi Anduin accorde une grand importance à l'éducation, et c'est pourquoi il a débloqué des fonds pour rendre accessible au public des copies de divers ouvrages et écrits. C'est très simple. Vous me donnez un titre de bibliothécaire, et je puis vous fournir la copie de l'un des livres disponibles.", completion = "Êtes-vous intéressé par un titre en particulier, &lt;nom&gt; ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nL'histoire de Morgan LadimoreLégendes des Gurubashi, Volume 3"},
[580] = {title = "La bibine perdue de Whiskey Slim", objective = "Whiskey Slim de Baie-du-Butin veut que vous lui rameniez les bouteilles de porto Pupellyverbos qu'il a perdues.", description = "On s'hum'ctait l'gosier féroc'ment, au large des Hauts-Surplombs, c' bonnes vieilles Hinterlands dans l' lointain. Cru qu'les mers allaient tous nous bouffer.\n\nL'vieux Slim en c'nait un bout en bravoure à 40°. L'cap'tain' 'vait une caiss' de porto Pupellyverbos réquis'tionnée à un corsair' s'rendan' ta Stormwind.\n\n'Lors quand c't' orage prè' des Hinterlands s'est pointé, j'ai fait mon enquête. Une grosse vague a visité l'endroit et a invité les bouteilles à la gaude. L'capt'aine va m' faire tâter du fouet si vous m'aidez pas à les ram'ner.", progress = "Coulez-moi ! J'ai presque plus d'bibine ici. L'cap'tain' va l'ver l'ancr' et l'vieux Slim va s'ass'cher comme l'déser' d'Tanaris. Et quand ti' verra qu'l' porto est plus là… m'rd' alors…", completion = "C'pas vrai ! V'zavez l'porto du cap'tain' ! J'vous dois zun' fière bougie, monami. Dirait qu' l'orage groooonde dehor'. P't'êt' que j'vais resté' raucho vec' lune d'ces bouteilles l'tank ça s' passe.", rewards = "Vous recevrez :\n\nRhum de Rumsey"},
[581] = {title = "La chasse pour Yenniku", objective = "Amener 9 Défenses de Bloodscalp à Nimboya au campement Grom'gol.", description = "Un sort, c'est ça. Un sort lancé sur le plus jeune fils de mon chef, Yenniku. Comme la coutume l'exige chez notre peuple, on l'a laissé chez les trolls Gurubashi de Zul'Gurub, mais après que ma tribu, la tribu Darkspear, a quitté les lieux en compagnie de l'orc Thrall, nous n'avons plus revu ce pauvre Yenniku. On m'a envoyé à Strangleronce depuis la lointaine Orgrimmar, pour rechercher le fils de mon chef.\n\nEt je crois que la tribu des Bloodscalp le détient.\n\nSi vous vouliez m'aider, partez à la chasse aux Bloodscalp. Vous pouvez les trouver au nord. Prenez leurs défenses et revenez me voir.", progress = "Montrez-moi que vous avez fait de la tribu Bloodscalp votre proie, <classe>.\n\nExhibez vos trophées.", completion = "Ce sont de belles défenses, &lt;nom&gt;. Vous avez montré votre aptitude à chasser les Bloodscalp.\n\nEt c'est une bonne chose, car cette chasse n'est pas terminée.", rewards = "Vous recevrez :\n\n"},
[582] = {title = "La chasse aux têtes", objective = "Apporter 20 Têtes réduites à Nimboya au campement Grom'gol.", description = "Nous devons découvrir si Yenniku est mort.\n\nTuez les Chasseurs de têtes Bloodscalp et prenez leurs Têtes réduites. Vous devez en réunir beaucoup, énormément, pour que je puisse m'assurer que celle de Yenniku n'est pas parmi elles.\n\nEt si Yenniku a été tué par les Bloodscalp, que l'esprit de leur chef Gan'zulah soit maudit pour les 600 ans à venir !\n\nPartez, <nom>. Vous pourrez trouver de nombreux Chasseurs de têtes aux ruines de Zuuldaia et à celles de Zul'Kunda, le long de la côte au nord.", progress = "<nom>. Je crains que le pire ne soit arrivé au fils du chef. Avez-vous les Têtes réduites que je puisse vérifier ?", completion = "Merci, &lt;nom&gt;. Je vais regarder ces têtes pour m'assurer que ce pauvre Yenniku a été épargné par les haches des Chasseurs de têtes.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCrispins darkspearBrachiales darkspear\n\nVous recevrez également :\n\n"},
[583] = {title = "Bienvenue dans la jungle", objective = "Parler à Hemet Nesingwary.", description = "Bienvenue à Strangleronce !\n\nPeut-être n'êtes-vous pas au courant, mais ce nain, là, n'est autre qu'Hemet Nesingwary, le seul et l'unique, héros de guerre renommé de l'Alliance, et maître de la chasse au gros gibier. Il n'est pas homme à accueillir facilement les <étrangers/étrangères> mais vous semblez avoir vécu quelques péripéties déjà, <classe>.\n\nEtant un vétéran de bien nombreuses batailles, Maître Nesingwary a un point faible pour ses collègues.\n\nAllez lui parler. Il vous donnera peut-être quelques conseils de chasse.", progress = nil, completion = "Un plaisir de faire votre connaissance, &lt;nom&gt;. je n'ai pas vu de &lt;classe&gt; dans les environs depuis un bout de temps.\n\nJe me suis mêlé à cette expédition dans un seul but : chasser une bête énorme et insaisissable. Puisque vous êtes une sorte de héros, je vous autorise à prendre part à la chasse, mais d'abord, vous devez faire vos preuves.\n\nJe vous montrerai comment tuer les raptors. Ajeck vous apprendra la chasse au tigre. Et le sire Erlgadin est maître dans la traque à la panthère.\n\nProuvez votre valeur et nous vous accueillerons dans la grande partie de chasse.", rewards = "Vous recevrez :\n\n"},
[584] = {title = "Les têtes du clan Bloodscalp", objective = "Apporter la Tête de Gan'zulah et la Tête de Nezzliok dans le Chaudron bouillonnant au campement Grom'gol.", description = "La tête de Yenniku n’était pas parmi celles que vous avez apportées, et je remercie le Grand Serpent pour cela. Mais nous n'avons pas progressé dans nos recherches pour le retrouver.\n\nNous devons connaître la vérité, et je crains que seuls le Chef du clan Bloodscalp et son Sorcier la connaissent. Ce sont les ennemis de la tribu Darkspear et ils n'avoueront rien d'eux-mêmes, aussi nous devons extraire la vérité de leurs lèvres mortes. \n\nApportez-moi les têtes de Gan'zulah et de Nezzliok le Redoutable, et placez-les dans ce chaudron.\n\nIls sont loin dans les profondeurs de Zul'Kunda. Apportez-moi leurs têtes... nous les ferons alors parler.", progress = "Le bouillon verdâtre dans le chaudron fait des bulles.", completion = "Vous plongez les Têtes de Gan'zulah et de Nezzliok dans le chaudron.", rewards = "Vous recevrez :\n\n"},
[585] = {title = "En parlant avec Nezzliok", objective = "Apporter un Trophée de Balia'mah, un de Ziata'jai et un de Zul'Mamwe dans le Chaudron bouillonnant au campement Grom'gol.", description = "<La tête de Nezzliok parle.>\n\nC'est vrai. Je sais où l'enfant Darkspear a été emmené. Vous m'avez battu et avez capturé mon esprit, mais je ne dirai rien sans apaisement !\n\nLes Bloodscalp sont en guerre contre les Skullsplitter. Pour obtenir mes faveurs, volez aux Skullsplitter 3 de leurs crânes trophées et apportez-les ici avec nous, pour que mon esprit ait des esclaves dans le Néant. Un crâne doit provenir de la collection de trophées de Balia'mah, un autre de celle de Ziata'jai, et le dernier de celle de Zul'Mamwe.", progress = "J'attends les crânes…", completion = "Oui. Ceux-là me serviront bien. Quand mon esprit sera libéré, j'entrerai dans le Néant avec trois excellents serviteurs !\n\nVous faites honneur à votre clan, &lt;nom&gt;, et m'avez apaisé.", rewards = "Vous recevrez :\n\n"},
[586] = {title = "En parlant avec Gan'zulah", objective = "Tuer 8 Chasseurs, 6 Chasseurs de têtes, et 4 Berserkers du clan Skullsplitter.\n\nApporter l'Armure brisée d'Ana'thek au Chaudron bouillonnant au campement Grom'gol.", description = "<La tête de Gan'zulah parle.>\n\nSoyez maudit ! Et vos ancêtres aussi !\n\nSeuls le sang et la revanche peuvent calmer ma rage, alors si tel est votre souhait… faites ceci :\n\nJetez-vous au coeur des Skullsplitter à l'est. Massacrez les plus féroces d'entre eux, et si vous survivez, mesurez-vous à leur chef, Ana'thek le Cruel. Ha ! Apportez-moi son armure brisée si vous le pouvez !\n\nPuisse-t-il vous démembrer et laisser votre cadavre pourrir sur place.", progress = "Bien que ma propre chair se détache de mon crâne, je peux sentir votre peur.\n\nAh ! Vous ne parviendrez jamais à achever cette quête…", completion = "Je ne veux pas le croire, mais ne peux dénier ce que vous avez accompli. Et ma rage s'apaise, à présent qu'Ana'thek est battu.\n\nVotre puissance vous conduira à de grands exploits, &lt;nom&gt;. Mais un jour, je vous croiserai dans le Néant et nous nous affronterons à nouveau.", rewards = "Vous recevrez :\n\n"},
[587] = {title = "Faire un tabac", objective = "Deeg de Baie-du-Butin veut que vous lui apportiez 15 portions de Tabac à priser.", description = "Ah ! La vie en mer. Je ne vais pas dire que c'est la bonne vie, mais c'est ma vie.\n\nLorsque j'arrive au port, j'aime me trouver une bonne bouteille de tafia et du tabac à priser de qualité. Des habitudes dégoûtantes, mais que serait un pirate sans ses vices, pas vrai ?\n\nAlors vous pouvez imaginer mon dépit lorsque j'ai découvert que l'herboriste de la ville était parti et avait vendu sa marchandise. Dire que son chargement a été détourné par ces fichus Ecumeurs de la Voile sanglante.\n\nJe parie, <classe>, que vous pourriez les convaincre de partager, non ?", progress = "Vous avez trouvé la marchandise, mon pote ?", completion = "Belle performance, &lt;nom&gt; ! Et juste avant que je doive embarquer, en plus ! Je ne pourrai jamais vous remercier assez, mon ami.", rewards = "Vous recevrez :\n\n"},
[588] = {title = "Le sort de Yenniku", objective = "Parler à Kin'weelay.", description = "<Nezzliok parle.>\n\nVous nous avez apaisés moi et mon chef, aussi vais-je vous dire ce que vous souhaitez savoir…\n\nLe jeune Yenniku est perdu pour son clan.\n\nIl a été emmené par le sorcier-docteur, Zanzil le Paria. À présent Zanzil le contrôle, de corps et d'esprit, et seule la magie la plus puissante pourrait le libérer.\n\nUne magie dont nul <classe> ne peut disposer.\n\nPeut-être vos alliés Darkspear peuvent vous offrir un espoir de salut pour Yenniku. Mais ça, j'en doute.", progress = nil, completion = "Zanzil le Paria ?\n\nSi Yenniku est détenu par ce troll, un ignoble et puissant sorcier-docteur, alors je crains qu'il ne reste plus qu'un faible espoir. Faible. Aussi minuscule que le plus petit des insectes.\n\nMais un espoir cependant.", rewards = "Vous recevrez :\n\n"},
[589] = {title = "Les Eclats vibrants", objective = "Apporter 3 Eclats vibrants bleus à Kin'weelay au Campement Grom'gol.", description = "Les légendes parlent d'un bijou, caché loin au cœur de Strangleronce. Nous l'appelons la Vue de l'Esprit, et il détient de grands pouvoirs. Si vous trouvez ce bijou, alors, peut-être, nous pourrions ramener Yenniku des ténèbres.\n\nJe vais parler aux esprits de la jungle pour localiser la Vue de l'Esprit. Tandis que je m'en occupe, allez dans la Mine aux cristaux, au sud-est d'ici, et récupérez des éclats vibrants bleus des basilics Gueule de fer. Ces éclats sont rares, mais nous aurons besoin de leur magie pour faire plier la Vue de l'Esprit à notre volonté.", progress = "Avez-vous les éclats, <nom> ? Nous en avons besoin pour le rituel final, après avoir récupéré la Vue de l'Esprit.", completion = "Vous avez réussi, &lt;nom&gt;. Ces éclats sont bien formés. J'entends déjà leur mélopée.\n\nEt tandis que vous étiez parti, j'ai parlé avec les Esprits de la jungle. Je sais où la Vue de l'Esprit demeure…\n\n…Et qui la garde.", rewards = "Vous recevrez :\n\n"},
[590] = {title = "Un marché de voleur", objective = "Battre Calvin Montague au Glas.", description = "Quoi ?\n\nQuoi ?\n\nVous voulez de l'argent ? Je ne vous dois pas un sou.\n\nUne lettre ? Quelle lettre ? Oh ! Vous voulez vous battre, alors ? Très bien, <mon pote/ma fille>… Allons-y ! Je vous dois de l'argent…", progress = nil, completion = "Incroyable ! Quelle technique !\n\nJe croyais que vous seriez une proie facile, &lt;nom&gt;. Vous m'avez eu, et bien eu.\n\nVoici la pièce que j'ai promise… Pas autant que j'ai dit que ça serait, mais c'est parce que je vous ai menti la première fois.", rewards = "Vous recevrez :\n\n"},
[591] = {title = "La Vue de l'Esprit", objective = "Apporter la Vue de l'Esprit à Kin'weelay au Campement Grom'gol.", description = "La Vue de l'Esprit est gardée par un mage ogre, à l'est d'ici et loin au cœur du tertre des ogres Mosh'Ogg. Son nom est Mai'zoth. Je le connais de l'époque où les Darkspear vivaient à Strangleronce. Il est vicieux, et sa magie est puissante.\n\nEt s'il possède la Vue de l'Esprit, alors sa magie le sera encore plus.\n\nVous devez combattre Mai'Zoth et lui arracher la Vue de l'Esprit. C'est une tâche périlleuse, mais c'est le seul espoir que nous avons de sauver Yenniku.", progress = "Salutations, <nom>. Les Esprits chantent votre bravoure, mais ils ne me disent rien quant à votre quête contre Mai'Zoth.\n\nAvez-vous la Vue de l'Esprit ?", completion = "Vous avez retrouvé l'Oeil ! Vous avez l'étoffe d'une légende, &lt;nom&gt; !\n\nEt pour pouvoir récupérer la Vue de l'Esprit, vous devez avoir battu Mai'Zoth, et l'avoir envoyé dans le Néant. C'est pourquoi les esprits ne parlaient pas de lui auparavant.\n\nC'est une bonne chose qu'il soit parti du monde de chair et d'os, mais à présent qu'il est au royaume des Esprits... j'ai peur qu'il n’entame un nouveau règne.\n\nMais ne nous soucions pas de cela pour l'heure. À présent, je dois accomplir un rituel pour plier la Vue de l'Esprit à nos besoins...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[592] = {title = "Il faut sauver Yenniku", objective = "Apporter la Gemme d'âme remplie à Nimboya.", description = "J'ai façonné la Vue de l'Esprit dans une Gemme d'âme. Cette gemme possède deux fonctions : vous devez d'abord l'utiliser pour étourdir Yenniku et, une fois qu'il est inconscient, placer la gemme sur sa tête afin d'emprisonner son âme.\n\nPuis apportez la gemme à Nimboya.\n\nYenniku demeure en compagnie de Zanzil le Paria le long du Rivage de cristal du lointain cap Strangleronce.", progress = "<nom>. Kin'weelay m'a dit que vous partiez capturer Yenniku.\n\nEst-ce vrai ? L'avez-vous ?", completion = "Vous avez réussi ! Vous avez libéré Yenniku de la volonté de Zanzil, et accompli la mission que je pensais désespérée.\n\nNotre tribu se souviendra de votre nom, en chansons, &lt;nom&gt;, et nous graverons votre histoire dans la pierre pour qu'elle vive à jamais.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton mystique de NimboyaMédaille de courage\n\nVous recevrez également :\n\n"},
[593] = {title = "Une âme pour la Gemme", objective = "Yenniku se tient étourdi devant vous, l'esprit ailleurs…", description = nil, progress = "Yenniku se tient étourdi devant vous, l'esprit ailleurs…", completion = "Vous placez la Gemme d'âme sur son front. Il frémit tandis que son âme est aspirée, laissant son corps, telle une enveloppe vide, derrière.", rewards = "Vous recevrez :\n\nGemme d'âme capturée"},
[594] = {title = "Message dans une bouteille", objective = "Trouver la main qui a écrit ce message lancé à la mer dans une bouteille.", description = "La note dit, d'une écriture plutôt élégante :\n\nA quiconque peut m'aider,\n\nJe vous en prie, j'ai désespérément besoin d'aide. Un grand Crin-de-ciel me détient captive sur une île des mers du Sud.\n\nLes étoiles, la nuit, me sont étrangères et sont obscurcies par les arbres de la jungle. Mais les jours les plus clairs, je distingue le Rivage cruel au nord-ouest, et ce qui semble être de grands vaisseaux au sud-ouest.\n\nJe vous en supplie, mon possible sauveur, venez m'aider.", progress = nil, completion = "Êtes-vous venu me libérer ?", rewards = "Vous recevrez :\n\n"},
[595] = {title = "Les boucaniers de la Voile sanglante", objective = "Le Premier Officier Crazz veut que vous contrôliez la crique au nord de Baie-du-Butin.", description = "Vous avez l'air de vouloir travailler, <mon pote/ma belle>. J'ignore pourquoi des <classe>s viendraient offrir leur aide aux Ecumeurs des Flots noirs, mais je ne vais pas la refuser.\n\nNotre bateau vient juste d'arriver à Baie-du-Butin et on dit que nos rivaux, ces abjects boucaniers de la Voile sanglante, ont été aperçus partout au nord de Strangleronce.\n\nTous les gars sont trop occupés à boire et à courir les jupons ! J'ai besoin que quelqu'un aille voir, <nom>.\n\nAllez à la crique au nord de Baie-du-Butin, le long de la Côte sauvage et voyez ce que vous pouvez trouver.", progress = nil, completion = "Sur le tonneau, vous découvrez une carte couverte d'un texte écrit à la hâte, ainsi que plusieurs pièces.", rewards = "Vous recevrez :\n\n"},
[596] = {title = "Les Colliers d'os ensanglantés", objective = "Apporter 25 Colliers d'os ensanglantés à Kin'weelay au Campement Grom'gol.", description = "J'ai été envoyé à Grom'gol pour aider Nimboya dans sa quête, mais j'ai aussi des raisons personnelles d'être là.\n\nLa tribu des Bloodscalp est l'ennemie de la nôtre. Collecter les trophées de nos ennemis nous donne du pouvoir sur eux. Vous pouvez aider notre tribu en chassant nos ennemis.\n\nIls vivent au nord. Massacrez des trolls Bloodscalp et prenez leurs Colliers d'os ensanglantés. Trouvez-en beaucoup, et grande sera votre récompense.", progress = "Les Bloodscalp seront un jour écrasés par les Darkspear ! Avez-vous les colliers de notre ennemi condamné ?", completion = "Ah ! Très bien. Je vais les faire bouillir puis fondre, et les esprits de leurs propriétaires vont s'affaiblir à mesure que les colliers vont disparaître !\n\nTenez, &lt;nom&gt;. Cela paiera ma dette envers vous.", rewards = "Vous recevrez :\n\nAnneau de pierre de sang"},
[597] = {title = "Les boucaniers de la Voile sanglante", objective = "Rendre compte de vos découvertes au Premier Officier Crazz à Baie-du-Butin.", description = "La carte montre Baie-du-Butin avec un \"X\" rouge dessiné précisément à l'endroit où vous vous trouvez.\n\nLe texte gribouillé dit :\n\n\"Vous devez préparer un camp à cet endroit et rester tranquilles. Attendez le signal du poste de commandement du sud avant d'attaquer. Si quiconque approche, tuez-le.\"", progress = nil, completion = "Bien sûr que je me souviens de vous, &lt;classe&gt;. De retour de reconnaissance, je vois…", rewards = "Vous recevrez :\n\n"},
[598] = {title = "Collier d'os brisés", objective = "Apporter 25 Colliers d'os brisés à Kin'weelay au Campement Grom'gol.", description = "À présent que vous avez collecté les trophées des Bloodscalp, j'ai une autre tâche pour vous. La tribu des trolls Skullsplitter vit au sud-est, et nous sommes en guerre contre eux depuis des années. Bien que les Darkspear ne vivent plus à Strangleronce, nous sommes toujours en conflit avec les Skullsplitter.\n\nAussi, chassez-les. Collectez leurs Colliers d'os brisés et revenez me voir. Aidez-nous dans notre guerre, et vous gagnerez l'amitié des Darkspear.", progress = "Les Skullsplitter maudiront le jour où ils nous ont apporté la guerre. Votre tâche est-elle accomplie ?", completion = "Votre force doit être grande pour avoir obtenu ces colliers, &lt;nom&gt;. Les Skullsplitter succombent devant vous comme de jeunes pousses retournent à la terre écrasées par un basilic. Vos exploits sont notre bénédiction.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChaussures darkspearBottes darkspear\n\nVous recevrez également :\n\n"},
[599] = {title = "Les boucaniers de la Voile sanglante", objective = "Rendre compte de l'attaque que prépare la Voile sanglante à l'amiral Seahorn.", description = "Bon sang ! Ainsi les boucaniers de la Voile sanglante préparent une attaque contre Baie-du-Butin ? Eh bien ! Ces crapules ne manquent pas d'air. Mais Baie-du-Butin restera dirigée par les Ecumeurs des Flots noirs !\n\nC'est plus grave que je ne le croyais. Allez dire ce que vous avez appris à l'amiral Seahorn immédiatement ! Ce vieux loup de mer est quelque part en ville...", progress = nil, completion = "Les boucaniers de la Voile sanglante, attaquer Baie-du-Butin ? Ils pourraient tout aussi bien se jeter des Hauts-Surplombs. Néanmoins, en m'apportant cette information, vous avez rendu à ma flotte de bretteurs un grand service. Les Ecumeurs des Flots noirs vous remercient.", rewards = "Vous recevrez :\n\n"},
[600] = {title = "La mauvaise mine de la KapitalRisk", objective = "Apporter 10 Cristaux bleus chantants à Crank Fizzlebub, à Baie-du-Butin.", description = "La KapitalRisk possède un réseau d'opérateurs à travers Strangleronce qui empêche les gobelins durs à la tâche, comme moi, de faire de l'or honnête ! S'il vous plaît, vous devez m'aider !\n\nLa KapitalRisk exploite une mine près de la mine aux cristaux, au nord. Ils ne peuvent pas entrer dans la mine à cause de nombreux basilics, mais ils peuvent toujours extraire des cristaux chantants des collines environnantes.\n\nDérobez leurs cristaux, et montrez-leur que la jungle ne leur appartient pas.\n\nEt... euh... apportez-moi ces cristaux comme preuve !", progress = "Avez-vous les cristaux ? J'en ai besoin !\n\nJe veux dire… j'ai besoin de savoir que la méchante KapitalRisk perd pied à Strangleronce. Parce que, vous savez, nous autres les types honnêtes, devons gagner notre croûte.", completion = "Splendide ! Merveilleux ! Je vais me faire un paquet !\n\nLa KapitalRisk a vraiment choisi la plus mauvaise mine à exploiter de toute la jungle, pas vrai ? Nous irions tous beaucoup mieux si elle partait d'ici.\n\nMerci, &lt;nom&gt;. Vous avez accompli une bonne action aujourd'hui.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBoute-feu gobelinFatale\n\nVous recevrez également :\n\n"},
[601] = {title = "Les élémentaires d'eau", objective = "Acquérir 6 Bracelets d'élémentaires d'eau pour le baron Revilgaz à Baie-du-Butin.", description = "Les élémentaires d'eau étaient sans nul doute invoqués par Gazban, le sorcier gobelin dont la rumeur dit qu'il a découvert la Pierre des marées. Comme il se peut que vous le sachiez, cette Pierre lance une malédiction sur son porteur, le faisant apparaître et disparaître...\n\nPeut-être pouvons-nous trouver un moyen de neutraliser cette malédiction. Nous pouvons demander à un mage de Dalaran d'analyser le résidu magique des bracelets de l'un des élémentaires d'eau. J'ai besoin que vous retourniez sur l'île et que vous rapportiez quelques échantillons.", progress = "Avez-vous trouvé quelque chose, <nom> ?", completion = "Hum ! Je ne suis pas suffisamment connaisseur pour examiner ces bracelets et savoir si certains seront d'une quelconque utilité. Apportez-les à Dalaran et demandez à un mage d'y jeter un œil.\n\nAprès tout, je ne peux pas quitter Baie-du-Butin simplement pour aller papoter avec ces vieux mages ennuyeux.\n\nNon pas que je craigne que quelqu'un profite de mon absence pour essayer de devenir le nouveau baron. Personne ne contrecarre Revilgaz et survit pour en parler.", rewards = "Vous recevrez :\n\n"},
[602] = {title = "Analyse magique", objective = "Apporter les Bracelets d’élémentaire d'eau à l'archimage Ansirem Runeweaver à Dalaran.", description = "D'après ce que j'ai entendu, les mages de Dalaran sont très occupés à reconstruire leur ville détruite, mais je suis sûr que vous en dénicherez un qui donnera un peu de son temps pour regarder les bracelets. S'il y a une chose que je sais à propos des mages, c'est qu'ils ne peuvent résister à une énigme magique.\n\nPrenez le sac de bracelets d’élémentaire d'eau et voyez s'ils peuvent apporter quelque lumière sur la malédiction de la pierre des marées. Cherchez tout particulièrement à rencontrer l'archimage Ansirem Runeweaver. J'ai déjà eu affaire à lui par le passé, et grand est son savoir.", progress = "Si vous voulez bien m'excuser, je suis très occupé en ce moment.", completion = "La pierre des marées ? Très intéressant. Cela pourrait vous surprendre d’apprendre que j'ai écrit un ouvrage, il y a de nombreuses années, se rapportant aux légendes de l'empire Gurubashi. J'en sais beaucoup au sujet de la pierre.\n\nAu moins un de ces bracelets semble porter du résidu magique que je pourrai analyser.\n\nVoyons voir ce que je peux découvrir...", rewards = "Vous recevrez :\n\n"},
[603] = {title = "La Clé d'Ansirem", objective = "Parler à Catelyn à Baie-du-Butin.", description = "Le mage qui analyse la Pierre amplifie son pouvoir à travers un point focal… Un autel d'un certain genre. Vous devriez pouvoir le mettre hors d'état en le surchargeant.\n\nEt de fait, je sais ce qu'il vous faut : une dague ancienne, une relique des trolls. Il n'y a qu'un... léger problème.\n\nVous voyez, j'ai trouvé la dague tandis que j'effectuais des recherches à Strangleronce, mais je l'ai donnée à ma fille entêtée, Catelyn, qui est partie à Baie-du-Butin pour devenir pirate.", progress = nil, completion = "Ma dague ? Qu'êtes-vous, un genre de comédien ? Voulez-vous seulement que je répète comment je suis devenue, de la meilleure combattante de Baie-du-Butin, la risée de la piraterie tout entière !\n\nJ'ai perdu un combat au couteau contre l'un de ces boucaniers de la Voile sanglante – une belle bande de bâtards – et il a pris ma lame comme récompense.\n\nCe n'est pas comme si je pouvais m'en sortir en tant que combattante avec seulement des insultes et une langue bien aiguisée...", rewards = "Vous recevrez :\n\n"},
[604] = {title = "Les boucaniers de la Voile sanglante", objective = "L'amiral Seahorn à Baie-du-Butin veut que vous tuiez 10 Bretteurs de la Voile sanglante et que vous rapportiez les Cartes de la Voile sanglante et les Ordres de la Voile sanglante.", description = "Crazz parle en termes flatteurs de votre dévouement envers les Ecumeurs des Flots noirs. Je vais vous charger d'une mission très importante pour la flotte.\n\nInfiltrez le prétendu poste de commande méridional que les boucaniers de la Voile sanglante ont établi sur le Rivage cruel. Faites une incursion dans le camp. Apportez-moi leurs cartes et leurs ordres écrits. Nous verrons exactement ce que cette vermine prépare.", progress = "Ohé, <nom> ! Quelles nouvelles apportez-vous du camp de la Voile sanglante au sud ?", completion = "Parfait, &lt;nom&gt;. Maintenant que nous connaissons leur plan, ce n'est qu'une question de temps.\n\nEt dire que ces imbéciles ont jeté l'ancre tout près du cap…", rewards = "Vous recevrez :\n\n"},
[605] = {title = "Les éclats bleus chantants", objective = "Apporter 10 Eclats de cristal chantant à Crank Fizzlebub.", description = "Les cristaux chantants sont uniques à Strangleronce, et très précieux pour certains. Je peux transporter les cristaux, mais cette maudite KapitalRisk fait en sorte qu'un honnête entrepreneur comme moi ne puisse pas en collecter.\n\nJ'aimerais vous embaucher.\n\nLes basilics, à Strangleronce, mangent les cristaux. C’est ce qui durcit leur peau, et parfois, on peut récolter sur eux du cristal de bonne qualité.\n\nVous pouvez en trouver sur n'importe quel basilic, mais les moins terribles se trouvent le long du rivage, plus au nord.", progress = "Avez-vous déjà ces éclats ? Je vous donnerai une bonne part des bénéfices.", completion = "Ah ! Cela conviendra parfaitement, &lt;nom&gt;. Oui, parfaitement !\n\nVoici votre part et… ça a été un plaisir de faire des affaires avec vous.", rewards = "Vous recevrez :\n\n"},
[606] = {title = "Effrayer Philippe le Chancelant", objective = "Apporter 5 Abats de Valbrume à Phillippe le Chancelant à Baie-du-Butin.", description = "Si quelque chose m'énerve, c'est bien les gens qui ne paient pas leurs dettes de jeu. Et beaucoup me doivent de l'argent. Vous pourriez m'aider à le récupérer ?\n\nD'abord, il y a Phillippe le Chancelant, en bas, près des docks. Il me doit beaucoup depuis la semaine dernière et je veux mon dû. Mais pour ça, il va falloir l'effrayer.\n\nSortez de la ville et chassez des Anciens gorilles de Valbrume. Trouvez de bons abats, et montrez-lui. Ne dites pas qu'ils proviennent d'animaux, laissez-le s'imaginer le pire.", progress = "Hé ! Je n'aime pas la façon dont vous me regardez, monsieur.", completion = "Ah ! Où est-ce que vous avez eu ça ? Non, ne me dites pas. Je ne veux pas savoir !\n\nQui vous envoie ? Loup des Mers ?", rewards = "Vous recevrez :\n\n"},
[607] = {title = "De retour chez MacKinley", objective = "Apporter le Paiement de Philippe le Chancelant à MacKinley \"Loup des mers\".", description = "Tenez, prenez cette bourse et donnez-la à Loup des Mers. Et dites-lui que je comptais le rembourser ! Je le jure !\n\nJ'étais juste un peu saoul et je me suis perdu et… vous savez comment sont les choses. Il comprendra, vous n'avez pas besoin de devenir <brutal/brutale>.", progress = "Par ici, <nom>. Avez-vous l'argent de Philippe le Chancelant ?", completion = "Hé hé, bien joué ! Et quand vous avez montré ces abats à Philippe le Chancelant, à quel point a-t-il tremblé ?\n\nAh ! Il est si facile de lire sur son visage, quand je joue aux cartes contre lui, ça m’aide beaucoup pour gagner !\n\nMerci pour votre aide, &lt;nom&gt;. C'est votre tour à présent d'être payé.", rewards = "Vous recevrez :\n\n"},
[608] = {title = "Les boucaniers de la Voile sanglante", objective = "L'amiral Seahorn de Baie-du-Butin veut que vous tuiez le capitaine Stillwater, le capitaine Keelhaul et l'amiral Firallon.", description = "Maudit soit le toupet de Firallon ! Il ne pourrait même pas diriger une yole sur le lac de Cristal, et encore moins mener une flotte entière contre nous.\n\nLes boucaniers de la Voile sanglante vont payer leur négligence. À présent que nous connaissons leur plan d'attaque, nous pouvons les contrer avant même qu'ils ne sachent ce qui les frappe.\n\nMais pourquoi envoyer la flotte entière faire le travail d'un courageux groupe d'aventuriers ? <nom>, dirigez certains de vos meilleurs camarades au mouillage de Firallon et assassinez les dirigeants de la Voile sanglante. Leur flotte coulera peu après.", progress = nil, completion = "Ah ! Quel grand jour pour les Ecumeurs des Flots noirs ! Trois bans pour vous, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nTunique des Flots noirs"},
[609] = {title = "Gages vaudou", objective = "Apporter le Fléau de Maury, la Longue-vue dorée de Jon-Jon, et le Grand anneau de Chucky à MacKinley \"Loup des mers\" à Baie-du-Butin.", description = "Ma liste se réduit, mais certains me doivent encore de l'argent.\n\nAprès, il y a Maury \"Pied bot\" Wilkins, Jon-Jon le Corbeau et Chucky \"Dix pouces\".\n\nLes dettes de ces chiens remontent à des mois et je pensais qu'ils avaient quitté la ville pour éviter de payer ! Plus tard, j'ai appris qu'ils étaient maudits et ensorcelés. À présent, ils courent la jungle. Mais je me fiche de leur sort, je veux récupérer ce qui m'appartient !\n\nIls se trouvent dans les ruines d'Aboraz et dans les ruines de Jubuwai, au nord-est. Trouvez-les, et ramenez-moi mon dû.", progress = "<nom>, avez-vous trouvé ces trois chiens ? Avez-vous pris leurs biens ?", completion = "Parfait ! Il se peut que j'en tire un bon prix, et particulièrement de ce qui se trouve dans le pied de Maury. Merci beaucoup, &lt;nom&gt; !\n\nJ'espère que ces trois-là ont compris la leçon : ne pas parier ce que l'on ne peut pas se permettre de perdre.\n\nC’est trop tard pour eux, mais ils auraient dû faire attention aux personnes contre qui ils jouaient.", rewards = "Vous recevrez :\n\n"},
[610] = {title = "Duncan \"le Beau garçon\"", objective = "Récupérer la Dague de Catelyn auprès de Duncan le \"Beau garçon\".", description = "Mon PÈRE vous envoie ? J'aurais cru qu'il m'aurait totalement oubliée.\n\nCe n'est pas vraiment sa faute si je suis partie, il ne pouvait simplement pas imaginer que je ne voudrais pas vivre une vie ennuyeuse, à lire et relire des livres moisis et à devenir un de ces vieux mages livides aux cheveux blancs !\n\nSi ma dague vous intéresse, vous devrez la récupérer chez Duncan le \"Beau garçon\", l'un des boucaniers de la Voile sanglante. Plantez quelque chose entre ses épaules et je suis certaine qu'il y renoncera.", progress = "On ne m'avait jamais battue jusqu'à présent, vous savez, <nom> ? Bien sûr qu'il m'a eue, mais il m'a frappée sur le côté de la tête, et m'a assommée. Quand je suis revenue à moi, ma lame n'était plus là.\n\nAussi vrai que je m’appelle Catelyn la Lame, j'ai besoin d'un couteau pour me battre, et pour moi, ce doit être celui-là.", completion = "Vous avez battu Duncan ? Vous avez plus d'expérience que je ne le croyais au premier abord.\n\nCela veut dire aussi que j’éviterai de vous défier prochainement en combat !", rewards = "Vous recevrez :\n\n"},
[611] = {title = "La malédiction des marées", objective = "Détruire l’Autel des Marées avec la Lame de Catelyn, tuer Gazban et rapporter la Pierre des Marées et la Lame de Catelyn au baron Revilgaz.", description = "Ainsi vous recherchez un autel d'un certain genre ? Eh bien ! Je ne suis pas experte en ruines de trolls comme peut l'être mon père, mais j'ai entendu parler d'une cité troll engloutie près de cette île que vous cherchez. Peut-être devriez-vous essayer là-bas ?\n\nVous avez récupéré mon couteau, alors je suppose que vous pouvez l'emprunter... Mais je veux que vous me le rendiez quand vous aurez fini !", progress = "Avez-vous retrouvé la Pierre des marées pour moi, <nom> ? J'ai déjà libéré un emplacement et acheté un beau socle pour elle.", completion = "Ahurissant ! La Pierre des marées ! Elle aura une place de choix dans ma collection d'anciens artefacts trolls. Avez-vous remarqué : on dirait qu'un courant est emprisonné sous sa surface ! Magnifique !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nRobe des eaux cristallines"},
[612] = {title = "<INUTILISÉ>", objective = "Rendre sa lame à Catelyn.", description = "J’ai peu d’espoir, mais essayez de convaincre Catelyn de se séparer de sa dague ? Le cœur d'un collectionneur, vous savez ce que c'est…\n\nPeut-être que si vous dites que c'est pour moi, elle sera plus disposée à me la vendre ?Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[613] = {title = "Le pied-bot de Maury", objective = "Apporter la Clé de Maury à MacKinley \"Loup des mers\" à Baie-du-Butin.", description = "Malédiction ! Ce malade de Maury a mis un verrou sur son pied-bot, et je ne peux pas l'ouvrir ! Son butin est à l'intérieur, et c'est ce qu'il me doit !\n\nNous devons trouver la clé pour ouvrir le verrou. Maury était connu pour jouer avec les ogres de Mosh'Ogg, sur leur colline au nord-est. Et il m'a dit un jour que la dernière fois qu'il était allé là-bas, il avait été coursé après avoir trop gagné. Peut-être que ces ogres ont sa clé.\n\nMais s'ils l'ont, il se peut que vous deviez en tuer beaucoup avant de trouver celui qui la détient...", progress = "Ohé, <nom> ! Avez-vous trouvé la clé de Maury ?", completion = "Vous l'avez trouvée ! Merci mille fois, &lt;nom&gt;. Vous m'avez été d'un grand secours !\n\nTenez, prenez ça, vous l'avez bien mérité.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nLégendaire"},
[614] = {title = "Le coffre du capitaine", objective = "Apporter le Coffre au capitaine Hecklebury Smotts à Baie-du-Butin.", description = "Dans le passé, je pilotais un navire d'ici jusqu'à Ratchet, en Kalimdor. J'étais un grand capitaine avec une solide réputation.\n\nJusqu'à ce que…\n\nCes maudits géants des mers m'apportent la ruine ! Ils ont détruit mon bateau, tué mon équipage, et m’ont abandonné dans un canot. Et l'un d’eux, Gorlash, a volé mon coffre de capitaine. Il a dit qu'il le voulait pour en faire une tabatière. Quel toupet !\n\nJe sais que Gorlash sillonne la côte à l'est d'ici. Trouvez-le et récupérez mon coffre ! Faites-le, et vous gagnerez la gratitude d'un capitaine.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards de bandelettes sanglantes"},
[615] = {title = "Le sabre du capitaine Smott", objective = "Parler à Sprogger.Après que mon premier navire a été détruit par ces géants, j'en ai acheté un autre. Je l’ai baptisé le Revanche de Smotts, j’ai trouvé un nouvel équipage, j'ai rempli les cales de marchandises, puis j’ai appareillé pour retrouver ces misérables géants. Je les ai trouvés, et de nouveau ils m’ont battu. Ils ont détruit le Revanche de Smotts, tué presque tout mon équipage et jeté les rescapés dans un canot.\n\nCette fois, un autre géant, Negolash, m’a volé mon sabre.\n\nCombattez Negolash et rapportez-moi mon sabre !\n\nParlez à Sprogger. C'était mon cuistot sur le Revanche de Smotts et il a survécu à la dernière attaque. Il peut vous aider à trouver le géant.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Après que mon premier navire a été détruit par ces géants, j'en ai acheté un autre. Je l’ai baptisé le Revanche de Smotts, j’ai trouvé un nouvel équipage, j'ai rempli les cales de marchandises, puis j’ai appareillé pour retrouver ces misérables géants. Je les ai trouvés, et de nouveau ils m’ont battu. Ils ont détruit le Revanche de Smotts, tué presque tout mon équipage et jeté les rescapés dans un canot.\n\nCette fois, un autre géant, Negolash, m’a volé mon sabre.\n\nCombattez Negolash et rapportez-moi mon sabre !\n\nParlez à Sprogger. C'était mon cuistot sur le Revanche de Smotts et il a survécu à la dernière attaque. Il peut vous aider à trouver le géant.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[616] = {title = "L'île hantée", objective = "Parler au baron Revilgaz, à Baie-du-Butin.", description = "Le baron Revilgaz m'a chargé de laisser traîner une oreille sur les rumeurs concernant les événements étranges ou surnaturels qui surviennent à Baie-du-Butin et à Strangleronce. Je ne donne généralement pas beaucoup de crédit aux histoires de fantômes, mais j'ai entendu des marins à la taverne parler d'une île hantée près de la côte. Des élémentaires d'eau et un fantôme de gobelin qui divague, qu'ils disent.\n\nSi vous allez parler à Revilgaz, pourriez-vous lui faire part de cette histoire ?", progress = nil, completion = "Intéressant. Il y a quelque temps de cela, je crois me souvenir d'avoir consulté, une fois, un livre qui suggérait que…\n\nAh ! Bien sûr, c'était une légende troll. Si ce que dit Krazek est juste, peut-être pourrai-je bientôt ajouter la Pierre des marées à ma collection de reliques et d'artefacts anciens.", rewards = "Vous recevrez :\n\n"},
[617] = {title = "De derrière les fagots", objective = "Apporter 10 Tas de roseaux akiris au corsaire Bloads à Baie-du-Butin.", description = "Vous cherchez du boulot, <nom> ? J'en ai p'têt' si vous vous sentez <prêt/prête> à relever un p'tit défi.\n\nJ'ai un ami, nommé Groy, qui fait un malheur en vendant c'que les nagas appellent des roseaux akiris : c't'un genre de roseau marin qu'a d'la valeur. Je n'sais pas trop à quoi ça sert, mais on paye cher pour des lots d'ce truc.\n\nApportez-m'en dix tiges, et nous ferons des affaires. Les nagas ont été vus dernièrement le long de la plage, au nord.", progress = "Si v's avez rien pour moi, 'ben circulez, <nom>.", completion = "Bon travail, &lt;nom&gt;. 10 tiges de roseau akiris, ça n’était pas trop dur à réunir après tout, hein ? Désolé pour les nagas, mais tout le monde doit bien gagner sa vie…", rewards = "Vous recevrez :\n\nEcharpe brûlante"},
[618] = {title = "Face à Negolash", objective = "Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevine dans le Canot de sauvetage du capitaine Smotts.\n\nTuer Negolash, et apporter le Coutelas de Smotts au capitaine Smotts, à Strangleronce.", description = "Negolash est un goinfre.\n\nQuand les géants ont détruit notre navire, il est venu directement dans ma cuisine. Il n'avait pas faim d'hommes d'équipage comme les autres géants. Negolash voulait du vin et mes ailes de busard grillées au barbecue. C'est ma spécialité, et j'ai dû me rendre jusqu'aux Terres ingrates pour avoir la recette !\n\nSi vous voulez tendre un piège au géant, trouvez du vin et un monceau d'ailes de busard. Placez-les dans notre vieux canot, au sud-est, le long de la côte. Quand Negolash sentira cette bonne nourriture, il rappliquera, sans aucun doute !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBoussole de Smotts"},
[619] = {title = "Allécher Negolash", objective = "C'est un canot de survie abandonné. Le long de son flanc, on peut lire des lettres pâles et délavées qui disent :\n\n\"La Revanche de Smott\"", description = nil, progress = "C'est un canot de survie abandonné. Le long de son flanc, on peut lire des lettres pâles et délavées qui disent :\n\n\"La Revanche de Smott\"", completion = "Vous empilez la nourriture et la boisson dans le rafiot.", rewards = nil},
[620] = {title = "L'écharpe à monogramme", objective = "Rendre l'Echarpe à monogramme à son propriétaire.", description = "On peut lire les lettres \"HS\" brodées le long de l'ourlet de la belle écharpe.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[621] = {title = "Le secret de Zanzil", objective = "Apporter 12 Echantillons de Mixture de Zanzil à Crank Fizzlebub à Baie-du-Butin.", description = "Zanzil le Paria demeure avec ses partisans dans les Ruines de Jubuwai et dans celles d'Aboraz, au nord-est de Baie-du-Butin. Il a été banni de sa tribu. Pourquoi ? Eh bien !… \n\nZanzil a le pouvoir de soumettre la volonté des autres, et ses chefs ont peur de lui. Il utilise un mélange de plantes tropicales pour supprimer la volonté et endurcir le corps de ses partisans.\n\nCette préparation intéresse beaucoup ceux qui voudraient contrôler les autres.\n\nApportez-moi des échantillons de ce mélange, et je leur trouverai une utilité.", progress = "Avez-vous les échantillons de Mixture de Zanzil ?", completion = "Ah ! Très bien ! Voici votre paie.\n\nEt un petit extra… pour votre discrétion.", rewards = "Vous recevrez :\n\nCeinture de corruption"},
[622] = {title = "La cocotte du caporal Kaleb", objective = "Apporter la Cocotte réparée de Krazek au caporal Kaleb, au Camp rebelle.", description = "Pendant que vous étiez <parti/partie> j'ai réparé la cocotte que vous m'aviez apportée. J'y ai même ajouté un autre sifflet à vapeur, et regardez : il y a un hachoir au fond pour réduire les os de pattes en bouillie ! Oui ! La Cocotte ébréchée de Krazek ravira tout cuisinier à 100% ! Je suis sûr que son propriétaire en sera satisfait.", progress = "Salut, <nom> ! Êtes-vous allé jusqu'à Baie-du-Butin ? Est-ce que le gobelin Krazek a réparé ma cocotte ?", completion = "Elle est réparée ! Super, je peux préparer le dîner maintenant ! Merci mille fois, &lt;nom&gt;.\n\nJ'espère que vous n’avez pas eu de soucis à Baie-du-Butin. L'endroit peut être dangereux, et… j'ai entendu des rumeurs disant que les gobelins entraînaient parfois les marins éméchés jusqu'à leurs bateaux d'esclaves et les emmenaient on ne sait où... pour faire on ne sait quoi...", rewards = "Vous recevrez :\n\nCoiffe d'harmonie"},
[623] = {title = "De derrière les fagots", objective = "Apporter un Fagot de Roseaux akiris au corsaire Groy à Theramore.", description = "<nom>, puisque vous êtes là : j'ai reçu un message de Groy pendant que vous étiez <parti/partie>. Il dit être satisfait de la dernière livraison, mais il a un client qui en désire plus, et tout de suite.\n\nJe ne vais pas à Theramore avant une semaine, mais si vous faites le voyage, vous pourriez transporter la marchandise pour moi.\n\nUn peu d'aventure vous tente ? Vous savez où se trouve Âprefange, n'est-ce pas ? Je ferais attention quand même, Theramore peut être dangereuse si vous n’avez pas le bon profil.", progress = "Ouais ?", completion = "Quoi ? J'ai beaucoup mieux à faire que de parler à vos semblables, &lt;classe&gt;. Faites que ça en vaille la peine ou fichez-moi le camp.\n\nHein ? Bloads vous envoie ? Alors, qu'est-ce que vous avez pour moi ?\n\n\n\nPas mal, pas mal du tout. Un autre fagot rendra mon client très heureux.\n\nJe suppose que votre prochaine question porte sur l'argent, pas vrai, &lt;classe&gt; ? Bien sûr qu'elle l'est !\n\nTenez, prenez cette pièce et suivez mon conseil : filez d'ici !", rewards = "Vous recevrez :\n\n"},
[624] = {title = "Devinette de Cortello", objective = "Résoudre l'énigme.", description = "Il est un pont fleuri, beaucoup emprunté\nÀ l'est de Deuillevent et au sud des Carmines\nDessous, quelque chose vous attend\n\nCertains l'appellent allusion, d'autres indice\n\nIl reposera là pour d'éternels lendemains\n\nPrenant son temps dans le marais des Chagrins.", progress = nil, completion = "Le parchemin détrempé contient le prochain indice…", rewards = "Vous recevrez :\n\n"},
[625] = {title = "Devinette de Cortello", objective = "Résoudre l'énigme.", description = "Une terre lointaine en Kalimdor attend\nOù le péril a brisé espoirs et destinées\nÀ l'est des Tarides le temps est sévère\nTénèbres et dangers criblent le marécage d'Âprefange\nMais là est un indice pour ceux qui prennent le risque\nAttendant d'être découvert dans une caverne au sud-ouest.", progress = nil, completion = "Vous trouvez un rouleau moisi.", rewards = "Vous recevrez :\n\n"},
[626] = {title = "Devinette de Cortello", objective = "Résoudre l'énigme.", description = "A Lordaeron ! La grande terre de bouleversements\nOù le soldat courageux fait de la mort son métier\nTrouvez votre chemin à travers l'agitation\nVous trouverez le fin mot de la quête\nLe long de la côte des Hinterlands, au pied des grandes chutes\nSous l'eau, c'est là que votre trésor vous appelle !", progress = nil, completion = "Vous ouvrez le coffre pour découvrir…", rewards = "Vous recevrez :\n\nSac de l'explorateur"},
[627] = {title = "Un service pour Krazek", objective = "Apporter 4 chargements de Minerai de pierre de sang inférieur à Krazek à Baie-du-Butin.", description = "Il y a une caverne dans la montagne, dans la gorge des Sèches-moustaches, loin au nord dans les hautes-terres d'Arathi. Cette caverne abrite un minerai rare : la pierre de sang. Celle de cette caverne n'est pas de la meilleure qualité, mais elle a quand même une certaine valeur... \n\nJ'en aimerais un peu.\n\nJe vais réparer votre cocotte, mais pendant que j'y travaille, allez chercher des fragments de pierre de sang. Apportez-m'en assez, et je vous donnerai un bonus.\n\nEt si vous n'avez pas la capacité de l'extraire... trouvez quelqu'un qui le peut !", progress = "Salut, <nom>. Avez-vous trouvé des pierres de sang ?", completion = "Ah splendide ! Vous m'avez rendu un immense service.\n\nVoici votre paiement…", rewards = "Vous recevrez :\n\n"},
[628] = {title = "L’Excelsior de chez Drizzlik", objective = "Apporter une Peau d'ancien crocilisque à Drizzlik, à Baie-du-Butin.", description = "Maintenant que l'intérieur est terminé, tout ce qui reste à faire est la couche extérieure. Pour ça, je n'utilise que les meilleures peaux de vieux crocis. Elles sont plus souples et solides, avec de belles écailles ; toutes les qualités qui définissent la gamme Excelsior de Drizzlik.\n\nIl est difficile de trouver des peaux parfaites, et celles qui me conviennent le mieux proviennent des vieux crocilisques marins. Les vieux ne sortent que pour défendre les autres crocis marins, alors il faudra en occire quelques-uns avant d’attirer un vieux.", progress = "J'ai lu quelque part que les crocilisques marins étaient en voie de disparition... De sombres nouvelles pour les affaires, n'est-ce pas ?\n\nDans tous les cas, j'espère que vous avez cette Peau d'ancien crocilisque marin pour moi !", completion = "Parfait ! Grâce à votre aide, cette commande sera honorée et envoyée au directeur Riddlevox par le prochain bateau pour Undermine. En avance sur la date, même !\n\nPour votre labeur, j'ai fait un petit extra, alors prenez-en donc une paire. Aux frais de Drizzlik.\n\nEt souvenez-vous, il n'y a pas de meilleure botte qu'une botte de la gamme Excelsior de Drizzlik !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes d'Excelsior"},
[629] = {title = "Le Récif infâme", objective = "Apporter un Fragment de tablette à Kin'weelay au Campement Grom'gol.", description = "Il y a longtemps, un grand tremblement de terre engloutit une ancienne cité troll sous les eaux de la Côte sauvage au nord-ouest. Nous appelons cet endroit le Récif infâme, car ce sont les murlocs qui à présent résident dans les ruines de la cité, attaquant tous ceux qui s'en approchent.\n\nUne vieille tablette repose parmi ces ruines, racontant l’histoire du héros troll Gri'lek. Cette légende est sacrée pour la tribu Darkspear, et bien que la tablette soit trop lourde pour qu'on puisse la bouger, j'en veux un fragment pour le conserver dans notre nouvelle demeure, à Orgrimmar.", progress = "J'attends le fragment de tablette, <nom>.", completion = "Voilà qui est si agréable. Quand je retournerai à Orgrimmar, je placerai ce fragment de tablette en un lieu sacré. Il nous rappellera la puissance et l'honneur de Gri'lek.\n\nMerci, &lt;nom&gt;. Vos actions sont le départ d'une amitié grandissante avec la tribu Darkspear.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[630] = {title = "Message dans une bouteille", objective = "Tuer le roi Mukla, trouver la clé et libérer la princesse Poobah.", description = "<nom>, je remets mon sort entre vos mains et entre celles de tous ceux que vous pourrez réunir pour me libérer. Le roi Mukla, le grand Crin-de-ciel, est mon ravisseur. Il commande aux bêtes de l'île et me retient contre ma volonté. Si vous pouviez le combattre et trouver la clé qui ouvre mes chaînes, je vous serais grandement redevable.\n\nJe l'entends souvent dans la partie sud-est de l'île, mais je vous en prie, soyez <prudent/prudente>, il ne doit pas être abordé à la légère.", progress = "Je remercie mes ancêtres que quelqu'un soit venu me secourir. Avez-vous la clé qui me libérera ?", completion = "&lt;nom&gt;, vous m'avez sauvée d'un grand déshonneur. Si cela était en mon pouvoir, je vous offrirais une place d’honneur dans ma tribu. Mais pour l'heure, tout ce que je peux vous offrir est ce témoignage pour le courage et la noblesse qui sont les vôtres.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nAnneau de nez de Poobah"},
[631] = {title = "Le viaduc de Thandol", objective = "Rhag Garmason veut que vous retrouviez le vieux Rustlocke.", description = "Une explosion monstrueuse a grondé à travers les collines. C'tait horrible, j'vous l'dis !\n\nDe bons soldats sont morts en défendant le viaduc de Thandol. Longbraid dit que nous prendrons notre revanche sur les Sombrefer avant que tout cela ne soit fini.\n\nIci, il n’y a que des blessés, et je ne vois aucun renfort arriver à l'horizon. Longbraid a envoyé le vieux Rustlocke en reconnaissance au pont à l'est, pour voir si nous pouvions le sécuriser.\n\nC'était il y a plusieurs jours. Avec Dun Modr en état de siège, nous n'avons pas les ressources d’aller le chercher.\n\nPeut-être pourriez-vous le trouver...", progress = nil, completion = "Vous fouillez le corps du nain. Gravé sur le casque vous lisez clairement : Ebenezer Rustlocke.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[632] = {title = "Le viaduc de Thandol", objective = "Rendre compte à Rhag Garmason et lui montrer le parchemin que vous avez trouvé sur le corps de Rustlocke.", description = "Il semblerait que le pauvre vieux Rustlocke soit tombé dans une embuscade de Sombrefer. Vous remarquez un parchemin froissé dans son poing serré.\n\nApportez la triste nouvelle à Rhag Garmason et montrez-lui ce que vous avez trouvé.", progress = "Des nouvelles du vieux Rustlocke, <nom> ?", completion = "Oh non ! La nouvelle est grave…", rewards = "Vous recevrez :\n\n"},
[633] = {title = "Le viaduc de Thandol", objective = "Détruire la cache d'explosifs.", description = "Par le Ciel, non ! Pauvre Rustlocke ! C'est une tragédie !\n\nNous ne devons pas laisser sa mort impunie. Le parchemin qu’il tenait indique que Kam Deepfury, le cerveau derrière la première attaque, a fait entreposer des explosifs dans une cache, juste de l'autre côté du viaduc de Thandol, dans les hautes-terres d'Arathi.\n\nSi ces explosifs atteignent le pont, notre principale ligne d'approvisionnement vers le nord sera très compromise. La cache doit être détruite, <nom>. Revenez me voir lorsque votre mission sera accomplie.\n\nVous êtes notre seul espoir.", progress = nil, completion = "Le pont restant est sauvé ! Vous avez rendu un grand service au roi Magni et au peuple de Khaz Modan.\n\nÀ présent, si nous pouvions tenir suffisamment longtemps pour permettre aux renforts d'arriver...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de garde nainPantalon des marécages\n\nVous recevrez également :\n\n"},
[634] = {title = "L'appel à l'Alliance", objective = "Chercher le capitaine Nials au Refuge de l'Ornière.", description = "J'aimerais vous demander un autre petit service, <classe>. Nous attendons les troupes de réserve d'Ironforge. Cependant, Roggo connaît l'existence d'un camp de l'Alliance, au nord sur les hautes-terres d'Arathi, au Refuge de l'Ornière.\n\nAllez-y et cherchez le capitaine Nials. Demandez-lui si l'Alliance peut nous prêter quelques soldats pour nous aider à reprendre Dun Modr et le viaduc de Thandol.", progress = nil, completion = "Mes condoléances accompagnent Longbraid et ses courageux soldats. La nouvelle de la tragédie du viaduc de Thandol et de la chute de Dun Modr assombrit mon cœur.\n\nMais Stromgarde est tombée. D'où notre présence ici au Refuge de l'Ornière. Nous devons reprendre nous-mêmes notre cité.\n\nL'honneur et le devoir exigent que nous ne quittions pas les hautes-terres tant que la grande bannière du roi ne flottera pas de nouveau sur Stromgarde. Je dois envoyer un message annonçant à Longbraid qu'il est seul...", rewards = "Vous recevrez :\n\n"},
[635] = {title = "Le cristal dans les montagnes", objective = "Trouver le cristal de votre vision.\n\nObjet fourni : \n", description = "L'éclat vibre tandis que vous le tenez…\n\nVous ressentez comme un appel, comme si quelqu'un essayait de communiquer, quelqu'un qui avait désespérément besoin de votre aide.\n\nUne vision apparaît dans votre esprit. Une vision des monts Arathi, et d'un cristal brillant saillant de la terre, là-bas.\n\nVous vous sentez <attiré/attirée> par cet endroit.", progress = nil, completion = "Ce cristal vibre comme s'il renfermait une force vitale.", rewards = "Vous recevrez :\n\n"},
[637] = {title = "Lettre de Sully Balloo", objective = "Donner la Lettre de Sully Balloo à Sara Balloo.", description = "L'enveloppe imbibée d'eau et déchirée se dissout et laisse dans vos mains quelques pages d'une lettre, écrite avec soin.\n\nLa lettre est adressée à Mme Sara Balloo d'Ironforge et commence par les mots : \"Ma chère Sara…\"", progress = "Vous semblez avoir beaucoup voyagé et avoir affronté de nombreux bouleversements sur votre chemin, <classe>. Les temps que nous vivons poussent l'esprit à bout. Quelles nouvelles m'apportez-vous à présent ?", completion = "Vous dites avoir vu mon Sully piégé sous les eaux glacées ? Ça ne peut pas être vrai !\n\nLaissez-moi lire sa lettre...", rewards = "Vous recevrez :\n\n"},
[638] = {title = "Trollbane", objective = "Aller au Trépas-d'Orgrim dans les hautes-terres d'Arathi et parler à Zengu.", description = "Thoras Trollbane étant mort, et Stromgarde en ruine, Vol'jin a donné pour instructions que nous mettions tout en œuvre pour dérober l'épée légendaire Trol'kalar, qui est aux mains des humains, afin de l'utiliser dans nos futurs combats contre les trolls de Zul'Gurub.\n\nZengu, l'un de nos chasseurs aguerris, a été envoyé au Trépas-d'Orgrim, dans la partie nord-est des hautes-terres d'Arathi, pour veiller à son obtention.", progress = nil, completion = "Comment vous portez-vous, &lt;classe&gt; ? La tâche confiée par Vol'jin sera compliquée, et toute assistance que vous pourriez apporter sera appréciée et nécessaire.", rewards = "Vous recevrez :\n\n"},
[639] = {title = "Glyphe de Strom", objective = "Trouver le Glyphe de Strom pour Zengu au Trépas-d'Orgrim.", description = "Dans des temps anciens, les trolls se battaient contre l'Empire arathorien et notre plus vaillant adversaire était le seigneur Ignaeus de Strom, dit Trollbane. Il se lançait dans la bataille en brandissant Trol'kalar, ce qui dans leur langue voulait dire \"Tueuse de trolls\".\n\nMais aujourd’hui les fils de Trollbane sont affaiblis et leur forteresse en ruine.\n\nL'épée est protégée par de nombreux glyphes qui ont été répartis entre les survivants de Stromgarde, et nous devons les retrouver.\n\nLe premier a été pris par le Syndicat, l'un de leurs hommes à Stromgarde devrait l'avoir.", progress = "Avez-vous déjà localisé le premier Glyphe ? Il est très probablement porté par l'un des agents du Syndicat à Stromgarde.", completion = "Excellent, mon ami. C'est un bon départ vers la collection complète des Glyphes dont nous aurons besoin pour retirer Trol'kalar de la tombe de Trollbane.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[640] = {title = "Le Glyphe qui fut brisé", objective = "Reprendre les 11 Fragments de Glyphe aux défenseurs de Stromgarde, puis les apporter à Tor'gan au Trépas-d'Orgrim.", description = "La tombe de Thoras Trollbane est protégée par trois glyphes. Vous avez récupéré le premier auprès du Syndicat. Les deux autres seront plus difficiles à obtenir, car ils sont détenus par la milice fortement retranchée de Stromgarde.\n\nLe Glyphe de Thoradin a été brisé en onze morceaux par le fils de Thoras, Galen, et dispersé entre les défenseurs de Stromgarde. Retrouvez les morceaux et apportez-les à Tor'gan, le chaman troll, il les assemblera pour reconstituer le Glyphe complet.", progress = "Throm'ka, <classe>. Zengu m'a informé que vous aviez besoin de mon assistance ?", completion = "Ah ! Vous avez besoin que je reconstitue le Glyphe de Thoradin? Ça ne devrait pas être trop difficile. Toutes les pièces semblent réunies et la structure magique va être aisée à reformuler.\n\nVous devriez fermer les yeux !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[641] = {title = "Glyphe de Thoradin", objective = "Apporter le Glyphe de Thoradin reconstitué à Zengu, au Trépas-d'Orgrim.", description = "Le Glyphe a retrouvé son intégrité et peut désormais permettre d’ouvrir le sceau sur la tombe de Trollbane. Apportez-le à Zengu, il ne fait pas de doute qu'il a d'autres tâches à vous confier.", progress = "<nom> ! Avez-vous le deuxième Glyphe ?", completion = "Nous ne sommes pas encore capables de retirer Trol'kalar de la tombe de Trollbane. Nous ne savons pas exactement où se trouve le troisième Glyphe, car ses porteurs semblent beaucoup se déplacer en Arathi, mais j'ai foi en vos capacités pour le retrouver.", rewards = "Vous recevrez :\n\n"},
[642] = {title = "La Princesse emprisonnée", objective = "Collecter 12 Poussières de Myzrael, puis les répandre sur les Eclats iridescents, à la gorge des Sèches-moustaches.", description = "Mon nom est Myzrael. Je suis une Princesse de la terre et mes ravisseurs, les géants, m'ont emprisonnée loin sous les hautes-terres d'Arathi. Ces éclats de cristal sont le seul moyen dont je dispose pour communiquer avec le monde de la surface.\n\nPar pitié, aidez-moi. Les alliés des géants, les kobolds Sèches-moustaches, possèdent un de ces éclats à la gorge des Sèches-moustaches, à l'est. Pour l'activer, vous devez collecter des Poussières de Myzrael sur les kobolds, puis les y appliquer.\n\nJe vous en supplie, <nom>, venez à mon secours !", progress = "Cet amas d'éclats ressemble beaucoup aux Eclats de Myzrael. Mais l'impression de sécurité n'émane pas de celui-ci.", completion = "Ah ! Vous avez activé ces éclats.\n\nDéjà, je me sens plus moi-même !\n\nMais hélas je suis loin d'être libre !…", rewards = "Vous recevrez :\n\n"},
[643] = {title = "Glyphe d'Arathor", objective = "Retrouver le Glyphe d'Arathor et l'apporter à Zengu, au Trépas-d'Ogrim.", description = "Bien qu'on puisse dire qu'il contrôle tout juste Stromgarde, et certainement pas toutes les hautes-terres d'Arathi, le prince humain fait courir la campagne aux restes de sa cavalerie. Je ne comprends pas pourquoi, mais qui peut comprendre la façon dont pensent les humains, hein ?\n\nLe plus important, c’est qu’il ait donné l'un des Glyphes au lieutenant Valorcall, commandant sa cavalerie. Trouvez-le et rapportez-moi son Glyphe.", progress = "Valorcall ne sera pas facile à retrouver, <nom>. A cheval, il peut se déplacer très rapidement. Néanmoins, nous devons récupérer son Glyphe.", completion = "La perte de leur chef de cavalerie est un coup terrible porté aux défenseurs de Stromgarde. Encore mieux, cela veut dire qu'il ne nous reste plus qu'un seul Glyphe à trouver avant de pouvoir posséder Trol'kalar.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[644] = {title = "Glyphe de Trollbane", objective = "Tuer le prince Galen Trollbane et apporter le Glyphe de Trollbane à Zengu, au Trépas-d'Ogrim.", description = "Le dernier Glyphe dont nous avons besoin pour ouvrir la tombe de Thoras Trollbane est détenu par son fils en personne. Il vit loin à l'intérieur de Stromgarde, dans une chapelle des quartiers contrôlés par la milice. Le prince Galen est bien protégé et n'est pas maladroit à la guerre non plus, aussi cette tâche pourrait s'avérer très ardue.", progress = "Vous êtes revenu, <nom>. La lignée d'Ignaeus Trollbane est-elle brisée ?", completion = "C'est un grand jour, &lt;classe&gt;. La lignée de Trollbane cessera de hanter mon peuple, et les Glyphes dont nous avions besoin pour prendre possession de Trol'kalar sont entre nos mains. Bientôt, très bientôt, nous frapperons les trolls haïs de Zul'Gurub.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[645] = {title = "Trol'kalar", objective = "Retirer Trol'kalar de la tombe de Trollbane à Stromgarde.", description = "Qu'est-ce donc ? Les quatre Glyphes une fois réunis, ils se sont rassemblés pour n'en former qu'un seul : le Glyphe d'Ignaeus. Celui-ci pourra sans aucun doute désactiver la garde placée sur la tombe de Trollbane.\n\nSes restes sont ensevelis dans le Sanctuaire derrière la chapelle de Stromgarde. Rapportez Trol'kalar.", progress = "Un relief dans la pierre, sur le dessus de la tombe de Trollbane, correspond aux lignes luisantes du Glyphe d'Ignaeus…", completion = "Vous placez le Glyphe d'Ignaeus dans le relief correspondant sur la tombe de Trollbane. Aussitôt, un éclat de lumière consume le Glyphe, et l'épée légendaire Trol'kalar est libérée de l'étreinte des mains de pierre.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[646] = {title = "Trol'kalar", objective = "Apporter Trol'kalar à Zengu au Trépas-d'Orgrim.", description = "La lumière s'éteint, doucement, et l'épée Trol'kalar, reposant dans un fourreau de pierre, est libérée.", progress = "<nom> ! Avez-vous pris l'épée ?", completion = "Pendant des générations, les forces de Strom et d'Arathor ont massacré notre peuple. Maintenant leur arme la plus puissante est entre nos mains. Nos laborieux progrès dans les forêts brumeuses de Zul'Gurub vont être facilités.\n\nVotre aide a été précieuse, &lt;nom&gt;, et les trolls Darkspear vous sont redevables.\n\nJe m'assurerai que l'épée est délivrée à Nimboya à Grom'gol.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArmure souillée de sangBouclier du combattant des abîmes\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[647] = {title = "Le tord-boyaux de MacKreel", objective = "Apporter le Tord-boyaux de MacKreel au brasseur Bilger à Southshore.", description = "J'ai bu pas mal de mon bon vieux tord-boyaux la nuit dernière ! Longbraid aurait ma tête s'il savait que je me suis endormi pendant mon tour de garde.\n\nL’alcool a frappé fort. Je me sentais comme si une brigade entière de machines de siège m'était passée sur le crâne, avec tous ces grondements.\n\nBon sang, regardez l'heure ! J'ai promis au brasseur Bilger de Southshore que je lui paierai ma dette en lui envoyant du tord-boyaux.\n\nMais il ne reste que 15 minutes, après je serai en retard ! Apportez-lui ce lot, s'il vous plaît ! Et dépêchez-vous !", progress = "Puis-je vous aider, <nom> ?", completion = "Ah ! Rien de tel que le tord-boyaux de Foggy MacKreel pour vous réchauffer par une journée fraîche. Et moi qui pensais que ce parasite serait de nouveau en retard pour payer son ardoise. Merci, mon ami ! Merci infiniment !", rewards = "Vous recevrez :\n\n"},
[648] = {title = "À la rescousse de OOX-17/TN !", objective = "Escorter OOX-17/TN jusqu'à Port Gentepression, puis rendre compte à Oglethorpe Obnoticus à Baie-du-Butin.", description = "Le robot émet à nouveau la voix du gnome :\n\n\"Je dois déplacer OOX-17/TN dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage. Il est équipé d'un camouflage, mais il me faut du temps pour le rendre opérationnel de mon côté. J'ai besoin que vous l'escortiez jusqu'au... disons jusqu'à PortGentepression ! Ce serait un endroit parfait, et assez long, pour que tout puisse se mettre en route !\"\n\nEscortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Oglethorpe Obnoticus - terminé !\"", progress = nil, completion = "Oh, c'est VOUS qui avez sauvé OOX-17/TN ! Aucune formule ne pourrait exprimer l'étendue de ma reconnaissance ! Mes robots guidés ont encore besoin d'être améliorés, mais votre sauvetage m'a épargné un nombre incalculable d'heures de reconstruction, ainsi que de nombreuses pièces d'or !\n\nJe vous en prie, choisissez un objet parmi ceux que je possède. J'espère que vous en ferez bon usage. Merci encore pour votre aide généreuse, mes robots et moi-même vous sommes redevables !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDéflecteur optomatiqueMinuteur thermostatique\n\nVous recevrez également :\n\n"},
[649] = {title = "La récupération de Houle", objective = "Parler à Malton Droffers à Orgrimmar.", description = "J'ai un travail de récupération pour vous, et si vous êtes un amateur de Houle comme moi, vous l'apprécierez sûrement. La Houle !\n\nMais c'est une boisson, imbécile.\n\nIl reste une réserve de Houle au miel des Hinterlands dans un avant-poste abandonné de la Horde, qui date de l'époque où il fonctionnait encore. On ne peut plus trouver d’aussi bonne Houle, aujourd'hui. L'un des hommes de paille de Malton est au courant et connaît la musique. Alors, vous allez vous rendre là-bas et m'apporter une caisse de Houle emballée, et deux bouteilles pour ma collection. Parlez à Malton, il vous donnera tous les détails nécessaires.", progress = nil, completion = "Oh oui, c'est à propos de la Houle que veut papa ! Il veut la vendre à une taverne d'Orgrimmar, mais nous en tirerons un meilleur prix si elle se trouve dans son emballage d'origine. Je connais quelqu'un capable de faire ce genre de choses. Il est dans les Hinterlands, là où l'on trouve la Houle. Mais c'est, euh... comment dire... un haut-elfe.\n\nMais c'est un haut-elfe sympathique, car il ne fait pas partie de l'Alliance. Bon, d'accord, c'est plus un haut-elfe ivrogne qu'un haut-elfe sympathique... Il apprécie la gnôle. Et quand je dis qu'il \"l'apprécie\", c'est qu'il apprécie vraiment BEAUCOUP.", rewards = "Vous recevrez :\n\n"},
[650] = {title = "La récupération de Houle", objective = "Parler à Gilveradin Sunchaser. Son camp se situe dans les Hinterlands.", description = "L’elfe que vous devez consulter s'appelle Gilveradin Sunchaser. Il peut identifier n'importe quel vin ou cuvée, uniquement à l'odorat ! Il peut emballer la Houle dont nous avons besoin, et c'est lui que vous devrez voir. Nous avons besoin de six bouteilles pour la livraison, de deux pour papa, et d'autant de bouteilles que l'elfe en voudra... Et il en voudra, croyez-moi ! Lorsque tout sera prêt et que vous aurez deux bouteilles pour papa, revenez me voir.\n\nLe camp de Gilveradin est proche d'un gîte de hauts-elfes dans les Hinterlands, et ils ne sont pas commodes. Croyez-moi.", progress = nil, completion = "Ainsi vous connaissez Malton ? C'est un vieux compagnon de beuverie. Voyez-vous, j'ai découvert quelque chose qui transcende les limites artificielles des traités et des alliances : l'alcool. Si nous étanchions tous notre soif en nous abreuvant de ces merveilleux breuvages alcoolisés, nous vivrions dans un monde meilleur, spirituellement parlant.\n\nHélas, je soupçonne que vous n'êtes pas là pour recevoir des cours sur les vertus diplomatiques de l'alcool. N'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[651] = {title = "Les pierres de lien", objective = "Collecter la Clé ardente, la Clé armoriée et la Clé de tonnerre aux lieux suivants : la Pierre de lien occidentale, la Pierre de lien orientale et la Pierre de lien extérieure.\n\nLes apporter à la Pierre de lien intérieure.", description = "Quatre Pierres de lien sont dispersées à travers tout Arathi. Ces pierres me retiennent prisonnière sous la terre.\n\nPour me libérer vous devez ouvrir la plus puissante : la Pierre de lien intérieure. Et pour cela, vous devez rassembler les clés des trois autres.\n\nCes pierres sont sous la surveillance de gardiens, mais si vous agissez intelligemment, ou si vous avez de la chance, vous pouvez trouver un moyen de les bannir.", progress = "Ceci est la Pierre de lien intérieure. C'est la plus puissante des Pierres de lien et elle doit être ouverte pour permettre aux autres de s'ouvrir.", completion = "&lt;Myzrael parle à travers la pierre.&gt;\n\nVous l'avez fait ! Vous avez ouvert les Pierres de lien ! Je sens mes entraves se relâcher et je sais que je serai bientôt libre.\n\nVous êtes un noble &lt;classe&gt;, &lt;nom&gt;. Mon sauveur !", rewards = "Vous recevrez :\n\n"},
[652] = {title = "La Pierre cruciale", objective = "Trouver et tuer Fozruk. Apporter le Bâtonnet de l'ordre à la Pierre cruciale dans les hautes-terres d'Arathi.", description = "Ouvrir les Pierres de lien a relâché l'étreinte de mes fers, mais quelque chose me retient toujours captive. C'est la Pierre cruciale que vous voyez parmi ce cercle de pierres. Et sa clé est détenue par l'un de mes geôliers, le Gardien de pierres Fozruk.\n\nVous devez prendre cette clé, que les Gardiens de pierres appellent le Bâtonnet de l'ordre, à Fozruk, et l'utiliser pour ouvrir la Pierre cruciale.\n\n<nom>, vous avez déjà tellement fait pour me venir en aide. Encore un peu... et ma gratitude fera trembler les fondations même de la terre !", progress = "La Pierre cruciale est chargée d'une extraordinaire énergie géomagnétique.", completion = "Vous placez le Bâtonnet dans la Pierre cruciale. Et un tremblement roule sous vos pieds…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[653] = {title = "Les alliés de Myzrael", objective = "Parler à Gerrig Bonegrip, dans la caverne lugubre d’Ironforge.", description = "<Myzrael parle.>\n\nLibre ! JE SUIS LIBRE ! Je suis libre de rassembler mes forces, à l’abri du regard de mes geôliers. Si je les affrontais maintenant ils me domineraient et m'emprisonneraient de nouveau.\n\nMais au moment voulu, je combattrai les géants, et ils regretteront la tutelle qu'ils m'ont imposée !\n\nVous êtes <un noble allié/une noble alliée>, <nom>. J'aurai encore besoin de votre aide quand le temps sera venu. Bientôt, il vous faudra m'invoquer à la surface.\n\nParlez à Gerrig Bonegrip. Il se trouve à Ironforge, dans une boutique de la caverne lugubre. Il sait comment on doit m'invoquer.", progress = nil, completion = "La Dame m'a annoncé votre venue, &lt;classe&gt;. Vous êtes le bienvenu dans ma demeure, car vous, comme moi, êtes au service d'une cause supérieure.", rewards = "Vous recevrez :\n\n"},
[654] = {title = "Les échantillons du désert de Tanaris", objective = "Acquérir des spécimens acceptables pour 8 basilics, 8 hyènes et 8 scorpions. Rapporter la Trousse d'analyse de terrain à l'Ingénieur en chef Bilgewhizzle à Gadgetzan avant que la source d'énergie ne s'épuise.", description = "L'activation de la Source d'énergie fait briller et vibrer la Trousse d'analyse de terrain. Tout semble fonctionner comme prévu.\n\nD'après l'ingénieur en chef Bilgewhizzle, vos disposez à présent de deux heures pour récupérer les données dont vous avez besoin dans le Désert de Tanaris. Si vous n'y parvenez pas en deux heures, toutes les données seront perdues et vous devrez lui acheter une autre Source d'énergie.\n\nAllez le voir une fois votre tâche accomplie.", progress = "Alors, avez-vous trouvé ce dont vous aviez besoin ? Si ce n'est pas le cas et que l'énergie s'épuise, tout ce qu'il y a dedans sera ruiné et vous devrez tout recommencer.\n\nHé, n'attendez aucune sympathie de ma part, je suis pour que la Compagnie des eaux Gadgetzan fasse des profits, et si cela implique que je vous vende des Sources d'énergie jusqu'à ce que nous puissions importer de l'eau depuis les sources gelées de Dun Morogh, ça me va !", completion = "Très bien, ôter la Source d'énergie ne va me prendre que quelques instants. Après, vous pourrez en faire ce que vous voudrez sans craindre de perdre les données.", rewards = "Vous recevrez :\n\n"},
[655] = {title = "Trépas-d'Orgrim", objective = "Parler à Tor'gan au Trépas-d'Orgrim.", description = "Je m'en souviens très bien, c'est comme si c'était hier... Tellement d'années sans espoir, attaché à cet horrible endroit par du bois et par du fer. Et puis enfin, enfin ! Il y eut le Chef de guerre. Orgrim Doomhammer dans son armure étincelante, son marteau de guerre tournoyant au-dessus de la tête.\n\nCe fut... trop terrible. Que le coup d'un misérable lâche terrasse notre plus grand héros. Il a chargé, sur son cheval, par-derrière, et sa lance l'a transpercé. Je suis tombé à genoux. Quels espoirs restaient-ils ? Quels espoirs restent-ils ?", progress = nil, completion = "Vous parlez de Gor'mul ? Oui, d'après ce qu'il dit, il semble qu'il ne s'est jamais remis de la mort d'Orgrim Doomhammer.\n\nGor'mul était prisonnier ici quand Thrall et Orgrim se sont battus pour libérer le camp, mais, alors que la terre tremblait et que nos frères s'échappaient, lui fut laissé derrière. Perdu, il vagabonda pendant des années, sans but ni espoir, jusqu'à ce que nous revenions nous établir au Trépas-d'Orgrim.", rewards = "Vous recevrez :\n\n"},
[656] = {title = "L'invocation de la Princesse", objective = "Aller aux Eclats de Myzrael, l'invoquer et la battre.\n\nPrendre ses Chaînes indicibles et les attacher aux Eclats de Myzrael.", description = "Vous devez battre Myzrael avant que sa force n'augmente. Sinon, une fois qu'elle aura rassemblé suffisamment de pouvoir, elle défiera ses ravisseurs ! Certains pensent pouvoir la contrôler, mais si elle peut l'être, alors pourquoi les géants l'ont-ils enchaînée ??\n\nLogique stupide, pas vrai ?\n\nPour la défier, invoquez-la aux Eclats de Myzrael, où vous lui avez parlé la première fois. Battez-la et prenez ses Chaînes indicibles, puis attachez-les aux Eclats de Myzrael.\n\nAgissez ainsi et elle sera de nouveau prise au piège.", progress = "Les Eclats de Myzrael n'émettent plus à présent.", completion = "Au moment où les Chaînes indicibles sont placées autour des Fragments, un hurlement inhumain monte des profondeurs. Le cri est suivi d'un rugissement.\n\nLes Fragments de Myzrael n'évoquent plus les mêmes impressions de chaleur et de sécurité qu'ils engendraient autrefois. À présent ils vibrent ouvertement d'une menace... comme si la chose, sous leur faible étreinte, allait jaillir à la surface.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nFragment de cristal palpitant"},
[657] = {title = "Les indices d'une Peste nouvelle ?", objective = "Parler à Kinelory.", description = "<Quae commence à consulter le dossier.>\n\nC'est effectivement intéressant. Il semblerait que l'Apothicaire Jorell ait travaillé sur des expériences mortelles ici à Go'shek. Je ne suis pas certaine de ce que cela a à voir avec Hillsbrad, mais Phin n'apprécierait pas que nous laissions se poursuivre ces expériences.\n\nNous avons eu une altercation avec des orcs pendant que vous étiez <parti/partie>, et je ne suis pas en suffisamment bonne forme pour aider Kinelory. Si vous vous sentez d'attaque, elle va avoir besoin de protection pour aller à la ferme et voler toutes les recherches que Jorell n'aurait pas encore envoyées à Moulin-de-Tarren.", progress = nil, completion = "Si cela peut apaiser Phin, alors je tuerai chacun des Réprouvés personnellement. Il a tellement fait pour nous depuis la peste. Nous ne pensions pas retrouver ici une famille ou des amis vivants.\n\nLorsque vous serez prêt, venez me le dire. Nous démarrerons immédiatement.", rewards = nil},
[658] = {title = "Les indices d'une Peste nouvelle ?", objective = "Trouver la Messagère des Réprouvés et ramener ses documents scellés à Quae près de la Ferme des Go'shek.", description = "Ainsi, Phin vous a <envoyé/envoyée> prendre de nos nouvelles ? Ça ne m'étonne pas, il s'inquiète toujours trop.\n\nNous avons surveillé la ferme pendant plusieurs jours, et Kin prétend qu'elle a vu une messagère sortir de cette petite maison et se diriger vers le sud il y a peu.\n\nElle parle beaucoup, mais je fais toujours confiance à ses sens lorsque nous sommes dans des endroits dangereux.\n\nVous ne seriez pas <un Pisteur compétent/une Pisteuse compétente>, par hasard ? Nous pensons que la messagère se rendait à Moulin-de-Tarren. Si nous pouvions mettre la main sur les documents qu’elle emportait, cela pourrait nous renseigner sur ce qui se passe à Hillsbrad.", progress = "Nous apprécions votre aide dans la recherche de cette messagère, <nom>. Pendant que vous étiez parti, Kin a vu un apothicaire sortir de cette même maison, au sud d'ici. Je suis certaine qu'ils trament quelque chose et j’ai besoin de preuves avant d'y aller et de commettre une imprudence.\n\nProgressez-vous dans vos recherches ?", completion = "Excellent !\n\nVoyons de quoi il s'agit…", rewards = "Vous recevrez :\n\n"},
[659] = {title = "Les indices d'une Peste nouvelle ?", objective = "Trouver Quae et Kinelory près de la Ferme des Go'shek dans les hautes-terres d'Arathi.", description = "Salut et bienvenue, <nom>. Je mène un groupe d'aventuriers enquêtant sur des faits étranges se produisant dans le coin.\n\nMon cousin à Hillsbrad a récemment abattu son chien Stanley parce que l'animal avait magiquement grossi jusqu'à une taille immense et attaquait sauvagement quiconque l'approchait.\n\nJe pense que les morts-vivants sont impliqués, et nous cherchons des indices le prouvant.\n\nDeux de mes compagnes, Quae et Kinelory, sont parties en direction de la ferme des Go'shek sur les hautes-terres d'Arathi, et ne sont toujours pas revenues. Vous pourriez les trouver pour moi ? Je commence à m'inquiéter.", progress = nil, completion = "Essayez de rester aussi silencieux que possible, voyageur.\n\nLes orcs n'apprécient pas beaucoup d'êtres espionnés, et il y a beaucoup à observer dans cette ferme.", rewards = "Vous recevrez :\n\n"},
[660] = {title = "Les indices d'une Peste nouvelle ?", objective = "Protéger Kinelory jusqu'à ce qu'elle rejoigne Quae.", description = "Très bien, <nom>. Je suis prête si vous l'êtes.\n\nOn y va ?", progress = "Le temps des discours est terminé. Protégez Kinelory si le peuple d'Hillsbrad vous importe un tant soit peu.", completion = "Vous nous avez rendu un grand service, &lt;nom&gt;. Merci.\n\nKin ne vous a pas posé trop de problèmes jusqu'à présent ? Elle est très sympa, mais il vaut mieux ne pas être son ennemi.", rewards = "Vous recevrez :\n\n"},
[661] = {title = "Les indices d'une Peste nouvelle ?", objective = "Retrouver Phin Odelic à Southshore.", description = "J'ai déjà vu Kinelory dans un état pire après toute une nuit passée dans une taverne. Vous avez bien fait de la protéger.\n\nCe qu'elle rapporte de la ferme permettra à Phin de se faire une idée de ce qui se trame à Arathi. Nous allons rester un peu pour être sûr qu'il n'y aura pas de représailles suite à votre attaque. Voudriez-vous retourner à Southshore et parler à Phin ?", progress = nil, completion = "Alors ces deux trouble-fête avaient raison finalement ! Ha ha ! Je suis content de l'entendre. Merci à vous, je suis heureux de savoir où elles sont et qu'elles se portent bien. Je suis vraiment soulagé de les savoir en vie ; ce sont deux amies chères à mon cœur.\n\nEnfin... Je vais vous remercier comme il faut pour votre aide. Tenez. Prenez ceci.\n\nAvec un peu de chance, nous allons comprendre ce que les Réprouvés fabriquent, et y mettre un terme.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe Poussière-d'automneJambières du pas léger\n\nVous recevrez également :\n\n"},
[662] = {title = "Sauvetage en haute mer", objective = "Le lieutenant Nilzlix veut que vous récupériez les Cartes et les Journaux de bord de la « Folie de la vierge » et de « L'Esprit des Pins argentés ».", description = "O'Breen a conduit les bateaux dans la crique. Nous étions certains d'y trouver le trésor. Le « Noir messager » a accosté sans encombre, mais à mesure que la « Folie de la vierge » et « L'Esprit des Pins argentés » approchaient, le niveau de la mer a commencé à baisser. C'est la chose la plus étrange que j'aie jamais vue !\n\nLes deux bateaux se sont échoués sur quelque chose... Une sorte de temple dans les récifs. Puis ils ont coulé à pic ; une vraie tragédie.\n\nNous voulons récupérer leurs cartes maritimes et leurs journaux de bord avant de partir. Nous ne voulons pas que les autres puissent les récupérer !", progress = "Comment se passe la recherche, <nom> ? Il ne faut absolument pas que les journaux de bord et les cartes de la « Folie de la vierge » et de « L'Esprit des Pins argentés », tombent entre de mauvaises mains.\n\nSi nos ennemis s'emparent de ces informations, l'amiral Seahorn nous fera subir le supplice de la planche.\n\nSi tant est que l'on sorte d'ici...", completion = "Savoir ces informations en sécurité rassurera le commandement de Baie-du-Butin. Beau travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nMarteau des Flots noirs"},
[663] = {title = "Terre !", objective = "Parler au capitaine O'Breen à la Crique de Faldir.", description = "Lolo voit une minuscule personne ! Toujours Lolo faire le guet !\n\nBienvenue à la crique de Faldir, <nom>. Capitaine O'Breen a dit que nous resterions que quelques heures. Juste le temps de récupérer le trésor, puis nous revenir à Baie-du-Butin.\n\nMais Lolo pense que ça va durer plus longtemps. Notre groupe a perdu deux navires. Pauvres « Esprit des Pins argents » et « Folie de la vierge ». Au fond de la mer maintenant ils reposent !\n\nLolo propose de vous parler au capitaine O'Breen si vous voulez rester ici.", progress = nil, completion = "Ohé, mon pote.\n\nC't'une pagaille pas possible. Seahorn aura not' peau si on récupère pas c'qui a coulé.\n\nUn des trucs du professeur indiquait que le trésor perdu devait s'trouver près d'cette crique. J'ai amarré le « Noir messager » aux quais, puis j'ai dit à l' « Esprit des pins argentés » et à la « Folie de la vierge » de suivre.\n\nAlors la mer a commencé à gargouiller. Puis le niveau de l'eau a baissé brusquement et les deux bateaux se sont échoués sur le récif.\n\nMais c'était pas un récif naturel. Il y avait quelque chose d'autre en dessous...\n\nDonnez un coup de main à mon équipage, et je vous récompenserai.", rewards = "Vous recevrez :\n\n"},
[664] = {title = "Chagrin noyé", objective = "Le capitaine Steelgut de la crique de Faldir veut que vous tuiez 10 Ecumeurs Daguéchine et 3 Sorcières Daguéchine.", description = "Argh, quelle horrible vie ! Je devrais être mort sous l'eau, et pas assis ici près d'un feu, respirant de l'air frais.\n\nL'équipage a tout fait pour sauver mon merveilleux « Folie de la Vierge ». Loué soit-il !\n\nO'Breen a réussi à atteindre la rive, nous on n'a pas été aussi chanceux. La mer s'est carrément défilée sous nous, je le jure.\n\nA un instant on naviguait, l'instant d'après on était échoué sur un récif. Et ces créatures ! Elles ont tué tous les survivants. Saleté de nagas ! Je me suis évanoui, puis je me suis réveillé ici.\n\nJe veux que ces créatures meurent !", progress = nil, completion = "Bon travail, &lt;nom&gt;.\n\nCes saletés ont eu ce qu'elles méritaient. Même si ça ne ramène pas mon navire ni mon équipage, ça me réconforte un peu de savoir quelques nagas morts.", rewards = "Vous recevrez :\n\nGants de loup de mer"},
[665] = {title = "Le trésor englouti", objective = "Escorter le professeur Phizzlethorpe à la grotte et revenir.", description = "Maintenant que nous sommes des Ecumeurs des Flots noirs accomplis, il est de notre devoir d'aider M. O'Breen à localiser le trésor perdu des elfes.\n\nDans ces eaux sombres, il est presque impossible de trouver les gemmes sans aide. Le docteur a conçu des lunettes spéciales qui pourraient nous être utiles. Il a besoin de les charger avec l’énergie magique de pierres enchantées qui se trouvent dans la grotte en haut de la colline.\n\nMais cette grotte est maudite ! Quand on s'en approche, on se fait attaquer. Venez et protégez-moi, alors je pourrai transférer l'énergie des pierres vers les lunettes.", progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "Les Lunettes marchent à la perfection maintenant ! Beau travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[666] = {title = "Le trésor englouti", objective = "Le docteur Draxlegauge, à la crique de Faldir, veut que vous rapportiez 10 Gemmes elfiques et que vous rapportiez ensuite les Lunettes de chasse aux gemmes.", description = "Le trésor repose au fond de la mer depuis si longtemps que les gemmes se sont calcifiées en pierres. Mais le pouvoir contenu dans ces lunettes vous permettront de les localiser facilement.\n\nL'ingéniosité gnome permet beaucoup !\n\nAussi, empruntez les Lunettes de chasse aux gemmes, <nom>, et voyez si vous pouvez récupérer une partie du trésor perdu pour le capitaine O'Breen.\n\nJ'y plongerais bien moi-même mais... euh... des affaires scientifiques importantes nécessitent ma présence sur un sol dur et sec... euh... voilà, c'est ça.", progress = "Les lunettes ont bien fonctionné ? Tout s'est passé correctement ? Des réglages sont peut-être nécessaires.\n\nOh ! Et il faudra me les rapporter ensuite. Je suis sûr que le capitaine O'Breen en aura besoin.", completion = "Superbe, &lt;nom&gt; ! Le capitaine sera très content ! Et attendez que cela parvienne aux oreilles de Seahorn !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBaguette gnomeMarteau de guerre servomécanique\n\nVous recevrez également :\n\n"},
[667] = {title = "La mort venue d'en-bas", objective = "Protéger Shakes O'Breen lors de l'attaque.", description = "Ça ne se présente pas bien. Il semble que les Daguéchine se regroupent pour une attaque.\n\nLes nagas ont la réputation d'être impitoyables dans la bataille et ne cesseront d'attaquer tant que je n'aurai pas rencontré la mort.\n\nJe ne considère pas ma vie plus précieuse que celles des membres de mon équipage, mais vous devez aider à ma sauvegarde. L'équipage ne pourra pas revenir à Baie-du-Butin seul et sans la connaissance que je possède des mers.\n\nLes nagas viendront de la mer. Je veux que vous restiez près de moi ici en haut pour parer leur attaque. Servez-vous du canon et repoussez-les.\n\nÊtes-vous <prêt/prête>, <nom> ?", progress = nil, completion = "Nous avons survécu !\n\nNous n'aurions pas pu sans vous, &lt;nom&gt;.\n\nNous partirons dès que la marée sera montée. Si vous n'aviez pas des choses importantes à accomplir, je vous engagerais de suite sur mon bateau. Mais je peux vous dire que vous allez avoir affaire à un gros morceau.\n\nMême si vous êtes un peu chétif, &lt;nom&gt;....", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau de ColdwaterAnneau de mer de feu\n\nVous recevrez également :\n\n"},
[668] = {title = "Le trésor englouti", objective = "Apporter les Gemmes elfique au capitaine O'Breen.", description = "Ne faites pas attendre le capitaine O'Breen. Il veut voir les gemmes. Après tout, c'est quand même pour ça qu'on est là !\n\nAprès ces quelques semaines passées avec les pirates, le professeur pense que la pire des choses serait qu'ils s'aperçoivent que nous nous approprions leur trésor.\n\nVoilà, <nom>, portez ça à O'Breen.", progress = "Salut, <classe>. Qu'est-ce qui vous amène sur le pont ?", completion = "Alors comme ça les petits gnomes ont prouvé leur valeur ? Je savais que je n'attendais pas pour rien !", rewards = "Vous recevrez :\n\n"},
[669] = {title = "Le trésor englouti", objective = "Prendre l'échantillon de Gemme elfique et l'apporter à l'amiral Seahorn à Baie-du-Butin.", description = "L'amiral Seahorn voudrait voir le plus rapidement possible ce que vous avez trouvé.\n\nMais comme vous pouvez le constater, nous sommes un peu coincés ici. Primo la marée est trop basse, deuzio ces damnées créatures ne nous quittent pas des yeux.\n\nVous rendriez un immense service aux Ecumeurs des Flots noirs si vous pouviez prévenir l'amiral Seahorn à Baie-du-Butin que nous avons découvert le trésor, et que nous sommes en train de le remonter. Prenez cet échantillon en guise de preuve.", progress = "Qu'apportez-vous à Baie-du-Butin, <classe> ?", completion = "Ah, laissez ça au bon vieux Shakes O'Breen ! Je savais que c'était le capitaine qu'il nous fallait !", rewards = "Vous recevrez :\n\n"},
[670] = {title = "Le trésor englouti", objective = "Remettre la Lettre de Seahorn à Shakes O'Breen dans les hautes-terres d'Arathi.", description = "Dites, <nom>, vous semblez aimer l'aventure. Ma flotte est bloquée à Baie-du-Butin pour cause de ravitaillement.\n\nIl y a des choses qui se trament dans le coin, et j'ai besoin d'envoyer une correspondance secrète à Shakes O'Breen, qui a jeté l’ancre près des côtes d'Arathi.\n\nPuis-je vous faire confiance pour remettre en toute confidentialité cette missive ?", progress = "Alors Seahorn a été impressionné ? Je suis persuadé que son sourire s'étirait de Baie-du-Butin à Ratchet.", completion = "Merci d'avoir fait un si long et dangereux voyage. Vous avez toute la gratitude des Ecumeurs des Flots noirs.", rewards = "Vous recevrez :\n\n"},
[671] = {title = "Magies immondes", objective = "Apporter 10 Amulettes de Pierre de sang à Tor'gan au Trépas-d'Orgrim.", description = "J'ai senti quelque chose de bizarre dans l'air... une chose qui m'a fait frémir. J'ai ma petite idée sur ce que c'est. En essayant de trouver d'où me venait cette sensation, j'ai découvert dans l'ouest, au manoir de Nordclos, des traces résiduelles d'une invocation démoniaque. A mesure que j'approchais, mon sang frémissait et la rage montait en moi.\n\nSur le sol, j'ai trouvé une Amulette de Pierre de sang, qui est généralement utilisée pour les invocations démoniaques. Celle que j'ai trouvée était déchargée. Il m'en faut une autre pour l'examiner, mais je ne retournerai pas dans le manoir. Pouvez-vous m'en procurer ?", progress = "Le sang maudit continu de couler dans mes veines, <nom>. Si quelqu'un... ou quelque chose invoque des démons, il faut l'arrêter.", completion = "Il va me falloir un peu de temps pour établir avec certitude les intentions du Syndicat, mais il est évident qu'il est complice des Ténèbres, la magie démoniaque continue de me troubler. Je vous préviendrai quand j'en saurai plus.", rewards = "Vous recevrez :\n\n"},
[672] = {title = "L'éveil de l'esprit", objective = "Récupérer 10 Yeux de raptors des plateaux sur les Arpenteurs des hautes-terres et les Vandales des hautes-terres pour Tor'gan au Trépas-d'Orgrim.", description = "Nous avons essayé de l’installer confortablement, de le dérider, de lui raconter des histoires sur notre majestueuse cité d'Orgrimmar en Kalimdor, mais rien ne le fait réagir.\n\nLes histoires de notre jeune Chef de guerre Thrall, qui porte l'armure et le marteau d'Orgrim mais, peut-être... Peut-être ! Une démonstration de la nouvelle magie chamanique lui donnera de l'espoir. Ça vaut la peine d'essayer !\n\nNous pourrions peut-être lui fabriquer un petit quelque chose, oui... Amenez-moi quelques Yeux de raptor, et je vais voir ce que je peux faire.", progress = "Je créerai une amulette qui donnera un peu de la force des raptors à Gor'mul. Cela ranimera peut-être la flamme qui dort en lui...", completion = "Excellent. L'esprit du raptor contenu dans ces yeux va donner de la force au porteur.", rewards = "Vous recevrez :\n\n"},
[673] = {title = "Magies immondes", objective = "Trouver l’Orbe de Pierre de sang de Marez Cowl et l’apporter à Tor'gan au Trépas-d'Orgrim.", description = "Je n'ai plus aucun doute sur le fait qu'un puissant démoniste réside dans l'enceinte de Stromgarde. Régulièrement, en utilisant une relique de magie des arcanes, ce démoniste a invoqué un grand nombre de démons. Nous devons tarir sa source d'énergie.\n\nTrouvez le démoniste et tuez-le. Ramenez-moi sa source d'énergie, elle doit être sur lui, et je m'emploierai à la détruire. Nous verrons alors si le pouvoir de cette chose continue de souiller cette terre...", progress = "Cette brûlure dans mes veines... Elle s’intensifie de jour en jour. Le démoniste doit être arrêté.", completion = "Mes nuits sans sommeil vont se transformer en nuits douces et paisibles dès que j'aurai détruit cet orbe. Merci, &lt;nom&gt;. C'est un rappel effrayant du pouvoir terrible que les démons détenaient sur les orcs avant qu'Hellscream ne les libère de cette malédiction.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCoiffe en peau de drake blancBrassards radieux en argent\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[674] = {title = "L'éveil de l'esprit", objective = "Donner l'Amulette de griffe de raptor à Gor'mul.", description = "Tenez, donnez cette amulette à Gor'mul, et regardez si la force des raptors peut ranimer la flamme guerrière qui sommeille en lui.", progress = "Quel espoir reste-t-il quand le plus puissant des puissants peut être assassiné par un lâche ? Quel espoir, je vous le demande !", completion = "Qu'est-ce que c’est ? De l'os poli. Qu'est-ce que vous voulez que j'en fasse ? Est-ce qu'une babiole peut restaurer la gloire de la Horde ?", rewards = "Vous recevrez :\n\n"},
[675] = {title = "L'éveil de l'esprit", objective = "Parler à Tor'gan.", description = "<Gor'mul jette l'amulette au sol.>\n\nTor'gan vous envoie, c'est ça ? Peuh ! Pourquoi est-il si miséricordieux avec moi. Ma propre miséricorde m'a été enlevée le jour où je n'ai pas pu mourir avec mon Chef de guerre au combat. Un mauvais coup du sort...", progress = nil, completion = "Cela ne marche pas, je vois. Néanmoins, je pense que lui montrer la puissance de la magie des chamans peut peut-être redonner à Gor'mul sa fierté et sa confiance en l'avenir. Le pouvoir de l'amulette n'était pas assez grand pour lui montrer notre nouvelle puissance.", rewards = "Vous recevrez :\n\n"},
[676] = {title = "Menace sur le Trépas-d'Orgrim", objective = "Tuer 8 Ogres Rochepoings et 10 Massacreurs Rochepoings, puis retrouver Drum Fel à l'avant-poste du Trépas-d'Ogrim sur les hautes-terres d'Arathi.", description = "Mauviettes... Tous autant qu'ils sont. Vous, <classe>, qu'est-ce que vous regardez comme ça ? Vous pensez être quelqu'un de spécial, hein ? Pourquoi ne le prouvez-vous pas ?\n\nL'avant-poste de Trépas-d'Orgrim dans les hautes-terres d’Arathi est attaqué. À moins qu'on leur envoie des renforts rapidement, leur défaite est imminente.\n\nMais avant de vous précipiter là-bas, j'aimerais vous faire passer un test. Au nord-est de Stromgarde, dans Arathi, il y a une colline habitée par la tribu Rochepoing. Si vous pouvez vous occuper de ces ogres et de leurs massacreurs, allez ensuite faire votre rapport à Drum Fel, à l'avant-poste du Trépas-d'Orgrim.", progress = "Je n'ai déjà pas le temps d'affûter ma hache, alors quitter le poste pour traquer ces bêtes qui s'en prennent aux miens...\n\nVous ne semblez même pas avoir l'expérience d'un grunt, encore moins celle d'un vrai <classe>. Alors que voulez-vous, <nom> ?", completion = "Alors comme ça vous pensez pouvoir aider Trépas-d'Ogrim ? Ainsi soit-il !\n\nTallow pense que vous pouvez vous occuper de cette tribu tout seul, ou tout au moins que vous pourriez nous être d'une quelconque utilité. Enfin, quoi qu'il en soit vous êtes là et j'ai besoin de guerriers en ce moment.\n\nSi vous pensez rester au Trépas-d'Ogrim, prenez un peu de repos et revenez me voir quand vous serez prêt. Les combats ne manquent pas en ce moment.", rewards = "Vous recevrez :\n\n"},
[677] = {title = "L'appel du combat", objective = "Tuer 10 Lanceurs de haches Witherbark, 10 Chasseurs de tête et 8 Sorciers-docteurs, puis retourner voir Drum Fel à l'avant-poste du Trépas-d'Orgrim.", description = "Les trolls Witherbark et les ogres Rochepoings d'Arathi se sont alliés pour nous éradiquer de cette terre, mais nous ne mourrons pas de leurs mains, ni des mains de personne. Nous allons les tuer et leur montrer que nous aussi possédons notre demeure ici.\n\nLes trolls nous ont refusé leur aide et les ogres, si nous les laissions faire, se serviraient de nous comme nourriture et comme literie. Cela ne sera pas !\n\nNous commençons notre attaque sur les trolls Witherbark, au sud. Tuez-les en masse, et ne revenez que lorsque leur camp sera rempli de leur sang.", progress = nil, completion = "Vos vêtements portent des traces du combat, et votre arcade sourcilière saigne. Bien, beau travail.", rewards = "Vous recevrez :\n\n"},
[678] = {title = "L'appel du combat", objective = "Tuer 10 Brutes Rochepoings et 4 Magi Rochepoings, puis retourner voir Drum Fel à l'avant-poste du Trépas-d'Orgrim.", description = "Votre force ne fait aucun doute, <nom>. Voyons ce que vous valez contre un ennemi digne de ce nom.\n\nLes Rochepoings sont basés au sud-ouest d'ici, vers le pont des nains, et si je ne me trompe pas, les marteleurs et les magi qui s'y trouvent représenteront pour vous un grand défi.\n\nTuez-en un maximum et revenez me voir quand vous aurez fini. Et même si vous n'en revenez pas, je ferai l'éloge de vos exploits sur le champ de bataille.", progress = nil, completion = "Vous êtes aussi fort qu'un kodo, et votre soif de combat vous honore.", rewards = "Vous recevrez :\n\n"},
[679] = {title = "L'appel du combat", objective = "Tuer 15 Chamans Rochepoings et 10 Seigneurs Rochepoings et revenir voir Drum Fel à l'avant-poste du Trépas-d'Orgrim.", description = "La tête de la bête est prête à tomber... avec grand fracas, <nom>. Vous avez définitivement prouvé votre valeur au cours de cette dernière bataille. Les commanditaires de ces attaques sont installés dans les ruines de Stromgarde, symbole de la faiblesse humaine.\n\nTrouvez et tuez les seigneurs Rochepoings et leurs laquais chamans, qui essayent de nous repousser hors de nos terres.", progress = nil, completion = "Votre peuple doit être fier de vous, &lt;nom&gt;. La menace est moins pressante grâce à vous, et je suis certain que nous allons pouvoir la chasser définitivement de nos terres.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTueuse muetteTranche-tête\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[680] = {title = "La réelle menace", objective = "Tuer Or'Kalar et apporter sa Tête à Korin Fel à l'avant-poste du Trépas-d'Orgrim.", description = "Vous avez bien servi mon mari, <classe>, mais il ne connaît pas la véritable cause des attaques contre le Trépas-d'Orgrim.\n\nOr'Kalar, le valet de Mug’Thol à Stromgarde, déteste mon mari, et souhaite sa mort depuis qu'il a été vaincu par lui quelques années auparavant.\n\nJ'avais le pressentiment qu'Or'Kalar tendait un piège à mon mari. Je lui ai donc caché les indices comme quoi il était à l'origine de ces attaques.\n\nSinon mon mari aurait foncé tête baissée dans le piège… Je voudrais que vous tuiez cette créature et que vous me rameniez sa tête.", progress = "Près de la tour d'Arathor, c'est là que vous trouverez Or'Kalar. Sa mort sauvera non seulement la vie de mon mari, mais elle mettra un terme aux attaques incessantes contre le Trépas-d'Orgrim.\n\nJe vois dans vos yeux que vous désapprouvez mon silence. Un jour, vous connaîtrez un amour tel que celui que je connais. Alors vous me comprendrez.\n\nEn attendant, faites ce que je vous ai demandé, et tuez Or'Kalar.", completion = "Vous m'avez rendu un grand service, &lt;nom&gt;. La vie de mon mari est sauve et la sécurité du Trépas-d'Orgrim assurée, tout cela grâce à vous. Je vous prie de recevoir ceci en récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nKilt de MistsprayEpée de Trépas-d'Orgrim\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[681] = {title = "Le manoir de Nordclos", objective = "Tuer 10 Malandrins du Syndicat et 6 Mercenaires du Syndicat.\n\nRetourner ensuite alors le capitaine Nials au refuge de l'Ornière.", description = "Nous avons combattu pour Stromgarde, et nous avons perdu. Les ogres, le Syndicat et nous, avons divisé notre grande cité et chaque faction s'est battue contre les autres.\n\nMais nos forces s'épuisent tandis que celles de nos ennemis se renforcent.\n\nIl nous faut l'aide de la ville de Southshore, mais l'approvisionnement reste difficile, car le Syndicat contrôle le territoire entre les deux cités.\n\nAllez au camp du Syndicat situé au manoir de Nordclos et tuez les occupants. Peut-être qu'ensuite, plus de caravanes de ravitaillement arriveront à destination.", progress = "<nom>, chaque heure perdue rend notre situation plus précaire. Vous devez vous presser ou notre ville tombera.", completion = "Très bien, &lt;nom&gt;. Avec la mort de ces hommes du Syndicat, nous recevrons plus facilement l’approvisionnement en provenance de Southshore.\n\nL'espoir perdure.", rewards = "Vous recevrez :\n\n"},
[682] = {title = "Les insignes de Stromgarde", objective = "Rapporter les Insignes de Stromgarde au capitaine Nials au Refuge de l'Ornière.", description = "Le Syndicat de Stromgarde est actuellement en guerre contre la milice. Pour inciter la populace à nous affronter aussi, ils ont mis à prix la tête de nos soldats, et donnent de l'or à tous ceux qui apportent un insigne de Stromgarde pris sur un soldat mort.\n\nNous voulons récupérer ces insignes. Nous ne pouvons tolérer que ces manants gardent des trophées de nos braves soldats tombés sur le champ de bataille !\n\nAllez dans la zone contrôlée par le Syndicat et récupérez les insignes.", progress = "Avez-vous trouvé des insignes de Stromgarde, <nom> ? Le Syndicat doit comprendre qu'il ne peut pas profiter de la mort des nôtres.", completion = "Merci, &lt;nom&gt;. Nous allons informer les familles de ces soldats qu'ils sont morts au champ de bataille.\n\nCela va leur causer énormément de chagrin, mais il vaut mieux savoir que de rester dans le doute.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nJambières de cavalier de Stromgarde"},
[683] = {title = "Requête de Sara Balloo", objective = "Remettre la lettre de Sara Balloo au roi Magni Bronzebeard à Ironforge.", description = "<nom>, j'ai une petite faveur à vous demander.\n\nPrenez cette lettre et portez-la à notre grand monarque d'Ironforge, le roi Magni Bronzebeard. Ce n'est pas grand-chose pour quelqu'un comme vous qui a tant fait pour l'Alliance.\n\nMe présenter devant le roi dans l'état d'esprit qui est le mien ne servirait pas notre cause. Vous le comprendrez sûrement.", progress = "Donc vous êtes un <classe> ! Le récit de vos exploits est parvenu jusqu'à nous, <nom>, et ce que vous avez fait pour l'Alliance est connu de tous, le saviez-vous ?\n\nEt pour quelles raisons venez-vous me voir à présent ?", completion = "Cela va me prendre un peu de temps pour lire cette lettre...", rewards = "Vous recevrez :\n\n"},
[684] = {title = "On recherche : Marez Cowl", objective = "Apporter la tête de Marez au capitaine Nials, au Refuge de l'Ornière.", description = "La tête de Marez Cowl a été mise à prix. La dernière fois que cette conseillère de haut niveau du Syndicat a été aperçue, c'était dans la zone de Stromgarde contrôlée par le Syndicat.\n\nLa prime peut être réclamée au capitaine Nials.\n\nAttention: Marez est une démoniste rusée et très adroite, et il est de notoriété publique qu'elle fricote avec les démons. Débusquez-la avec une extrême prudence.", progress = "Alors, <classe>. Vous avez quelque chose ?", completion = "Avez-vous tué Marez Cowl ? Très bien, &lt;nom&gt;. Vraiment formidable !\n\nMarez était une menace pour les défenseurs de Stromgarde. Une rumeur disait même qu'elle était l'émissaire d'une autre force auprès du Syndicat. Nous sommes heureux qu'elle ne puisse plus utiliser ses pouvoirs contre nous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards runiques des arcanes"},
[685] = {title = "On recherche : Falconcrest et Otto", objective = "Apporter les Têtes de Falconcrest et d'Otto au capitaine Nials au Refuge de l'Ornière.", description = "La milice de Stromgarde a mis à prix les têtes du seigneur Falconcrest et de son garde du corps Otto. Falconcrest dirige les forces du Syndicat dans les hautes-terres d'Arathi, et sa mort sèmerait le chaos dans ces forces.\n\nSon garde du corps Otto, bien qu'il ne constitue pas une cible stratégique, est un adversaire puissant et il a déjà tué nombre de nos défenseurs.\n\nIl faut aller voir le capitaine Nials pour récolter les primes.", progress = "Bonjour. Vous avez rapporté quelque chose ?", completion = "Falconcrest et Otto ? Splendide !\n\nVoilà la récompense, &lt;nom&gt;. Et je suis heureux de la payer.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâtonnet de désolationBrassards de chevaucheur martial\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[686] = {title = "Hommage royal", objective = "Le roi Magni Bronzebeard veut que vous parliez avec le maître-maçon Marblesten.", description = "Je ne demande pas à ce que les nains comme Madame Balloo comprennent que nous faisons cette guerre pour leur bien. La perte de son mari ainsi que toutes les autres dans le combat au nom de l'Alliance pèsent lourd sur mes épaules.\n\nMême si je ne peux pas le ramener du Néant distordu, je peux lui rendre hommage.\n\nJe vais faire construire un mémorial en l'honneur de Sully Balloo, par le maître-maçon Marblesten.\n\nEnvoyez-lui un message, <classe>. C'est vous qui serez en charge de faire respecter cet ordre.", progress = nil, completion = "Donc le roi Magni Bronzebeard lui-même vous a envoyé ?\n\nEh bien ! Cela doit être important !", rewards = "Vous recevrez :\n\n"},
[687] = {title = "Theldurin l’Egaré", objective = "Trouver Theldurin l'Egaré.", description = "Theldurin l'Egaré était un membre de notre ordre, le Marteau du crépuscule. Il a perdu l'esprit et a rejeté nos enseignements. Et avant de s'enfuir il nous a volé le Parchemin de Myzrael ! Nous n'avons pas pu le rattraper, mais des rumeurs font état de sa présence dans les Terres ingrates, complètement fou et baragouinant n'importe quoi.\n\nPour ramener la Dame, vous devez absolument retrouver le parchemin. Et pour cela vous devez retrouver Theldurin.", progress = nil, completion = "Salut. Salut, salut salut salut salut SALUT !\n\nJe regrette - attendez, non je ne regrette pas ! Ne soyez pas impoli !\n\nOh non… il s'agissait de folles paroles.\n\nMais… parfois la folie est mon seul réconfort.", rewards = "Vous recevrez :\n\n"},
[688] = {title = "Les alliés de Myzrael", objective = "Parler à Zaruk au Trépas-d'Orgrim.", description = "<Myzrael parle>\n\nLibre ! JE SUIS LIBRE ! Je suis libre de rassembler mes forces, hors de portée de mes ravisseurs. Si je les rencontrais maintenant, ils seraient sûrement plus forts que moi et me captureraient à nouveau.\n\nEn temps voulu, j'affronterai les géants, et ils regretteront de m'avoir bannie !\n\nVous êtes d’une aide précieuse, <nom>. J'aurai encore besoin de vous. Quand je serai prête, j'aurai besoin de vous pour m'invoquer à la surface.\n\nParlez avec Zaruk au Trépas-d'Orgrim. Il sait comment m'invoquer.", progress = nil, completion = "Bonjour, &lt;classe&gt;. La Dame m'a informé de votre passage, et si vous voulez la faire revenir, alors nous avons des tas de choses à nous dire...", rewards = "Vous recevrez :\n\n"},
[689] = {title = "Hommage royal", objective = "Le Maître Maçon Marblesten d'Ironforge veut 5 Morceaux de Granit d'Alterac.", description = "Donc mon bon roi veut construire un monument en l'honneur du soldat Sully Balloo ? Et vous me dites que le pauvre homme est mort lors de la tragédie du viaduc de Thandol ?\n\nN'y a-t-il jamais eu la paix en Azeroth ?\n\nQuoi qu'il en soit, les ordres du roi sont prioritaires. Pour construire un monument grandiose et durable, j'ai besoin d'une pierre spéciale, d'une grande finesse. Allez sur la Colline de Darrow, dans Hillsbrad et rapportez-moi du Granit d'Alterac.", progress = "<nom>, <nom>, <nom> ! Dites-moi que vous m'avez rapporté du Granit d'Alterac afin de commencer mon chef-d'œuvre en l'honneur de Sully Balloo.", completion = "Parfait ! Encore mieux que je ne l'avais imaginé !\n\nEt pourtant, de l'imagination, j'en ai...", rewards = "Vous recevrez :\n\n"},
[690] = {title = "La demande de Malin", objective = "Trouver Skuerto au Refuge de l'Ornière dans les hautes-terres d'Arathi.", description = "Bonjour, <nom>. Vous avez l'air d'être <un aventurier/une aventurière>, et j'ai un petit travail qui doit être fait.\n\nL'archimage Trelane, mon ancien maître, a fui depuis peu Stromgarde dans les hautes-terres d'Arathi, et il m'a demandé de récupérer quelques objets qu'il n'avait pas pu emporter.\n\nLa cité assiégée est tombée, bien qu'il ait essayé de la défendre. J'ai déjà des agents sur les hautes-terres, mais ils ont besoin de renfort. Cela vous intéresse ?", progress = nil, completion = "Ainsi, Malin vous envoie ? Je me fiche de savoir si Muradin est revenu d'entre les morts et vous a envoyé ici sur un dragon. Je ne suis pas disponible. Parlez à Kryten si vous avez besoin de quelque chose.", rewards = "Vous recevrez :\n\n"},
[691] = {title = "Valoir son poids en or", objective = "Trouver 10 Défenses de Witherbark, 4 Bourses-médecine Witherbark et un Couteau de Chasseur d'ombre pour l'Apprenti Kryten au Refuge de l'Ornière.", description = "L’archimage Malin nous a envoyés, Skuerto et moi, collecter des ingrédients. Maintenant que vous êtes là, je sais que je n’aurai pas de problèmes pour trouver ces objets.\n\nJ’ai besoin des objets suivants : des défenses de Witherbark, des bourses-médecine Witherbark et un couteau de chasseur d'ombre.\n\nPourriez-vous me rapporter ces objets ? Les Witherbark vivent au sud-est d’Arathi.", progress = "Avez-vous été chanceux, <nom> ?\n\n\n\nSi mes recherches sont exactes, les défenses peuvent provenir de n'importe quel troll Witherbark. Les bourses-médecines doivent provenir des sorciers-docteurs Witherbark. Et seuls les plus robustes des Chasseurs d'ombre Witherbark portent le couteau qui m’intéresse, ils le reçoivent une fois leur rite de passage achevé. Mais il n'y a aucun moyen de savoir s’ils ont un couteau tant qu'on ne les a pas abattus.", completion = "Incroyable ! Je comprends pourquoi Malin vous a fait venir – bon boulot !\n\nA ce rythme, Skuerto et moi reviendrons à Stormwind dans très peu de temps.\n\nJe crois que mon ami nain est revenu de sa reconnaissance du Hall Rochepoing ; allez lui parler.\n\nJe pense qu'il a dû avoir une échauffourée avec quelques ogres. Mais ne lui en parlez pas, il est très susceptible quant à ses compétences d'éclaireur, il déteste les critiques à ce propos.", rewards = "Vous recevrez :\n\n"},
[692] = {title = "Les fragments perdus", objective = "Apporter le Fragment de Parchemin déchiré, le Fragment de Parchemin fripé et le Fragment de Parchemin noirci à Theldurin l'Egaré.", description = "Le Parchemin de Myzrael... Le Parchemin de Myzrael ? Vous ne voulez tout de même pas ça ! Sa puissance peut faire revenir Myzrael à la surface du monde, et si vous le faites, on sera tous en danger !\n\nOu alors... il est peut-être déjà trop tard. Peut-être qu'elle est déjà libre. Peut-être ne fait-elle qu'attendre en rassemblant ses forces avant de les abattre sur nous. Si c'est le cas, alors vous avez BESOIN du parchemin !\n\n... Quel dommage, il a été détruit. Un élémentaire enragé l'a volé et déchiré en morceaux.\n\nSi vous pouvez rassembler les fragments, je pourrai, je pense, le reconstituer...", progress = "Avez-vous retrouvé les fragments du parchemin ? Vous aurez besoin du Parchemin de Myzrael si vous voulez l'arrêter, avant qu'il ne soit trop tard !", completion = "Ah, vous les avez ! Beau travail, &lt;nom&gt; ! C'est peut-être notre seule chance contre le mal de Myzrael !\n\nLaissez-moi prendre mes outils et je vais voir ce que je peux faire...", rewards = "Vous recevrez :\n\n"},
[693] = {title = "La baguette au poing", objective = "Trouver la Baguette d'invocation de Trelane et revenir voir Skuerto au Refuge de l'Ornière.", description = "Hé <nom> ! Désolé d'avoir été un peu bref, la dernière fois j'étais pris de court... euh, non ce n'est pas un jeu de mots.\n\nJ'ai découvert où le premier objet de Trelane a échoué : c'est Kor'gresh qui l'a au Hall Rochepoing. Pendant que j'y suis : il jette des éclairs de glace sur ses troupes pour qu'elles gardent leur position, ce qui prouve qu'il n'est pas loin de maîtriser tous les pouvoirs de l'objet.\n\nVous trouverez le Hall Rochepoing au sud d'ici puis à l'est du viaduc de Thandol. Trouvez cet ogre et ramenez-moi la baguette.\n\nPendant que vous serez en chemin, je vais voir ce que je peux faire pour Stromgarde.", progress = "Notre but c'est la baguette, <nom>. Concentrez-vous uniquement sur cet objectif.", completion = "Excellent, &lt;nom&gt;. Voilà le premier objet, il n'en manque plus que trois, selon ma liste. Les trois autres se trouvent dans Stromgarde.\n\nReposez-vous pour récupérer vos forces, car la prochaine étape de mon plan risque de vous demander beaucoup plus de temps et d'efforts. Revenez me voir quand vous aurez pris un repas chaud et un peu de repos.", rewards = "Vous recevrez :\n\n"},
[694] = {title = "Les défenses de Trelane", objective = "Trouver une Agate d'azur et la porter à l'Apprenti Kryten au Refuge de l'Ornière.", description = "Alors vous êtes d'attaque ?\n\nVoici la prochaine étape : il y a des ogres tout autour de la Tour d'Arathor à Stromgarde. Nous devons activer les défenses de la tour si nous voulons avoir une chance contre eux et sauvegarder les objets. Pour cela, nous avons besoin de ces gemmes que les chamans Rochepoings apprécient particulièrement. Ils les ont récupérées à la tour, mais ils ne vont pas les garder très longtemps.\n\nRécupérez une de ces gemmes, et portez-la à Kryten : il connaît le sort pour l'enchanter afin qu'elle serve de clef.", progress = "<nom>, re-bonjour. Avez-vous trouvé une Agate d'azur ?", completion = "Vous me fascinez, &lt;nom&gt;. Vraiment bien joué !\n\nLaissez-moi un moment, le temps de jeter le sort approprié, et tout sera prêt.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[695] = {title = "Enchantement d'Apprenti", objective = "Parler à Skuerto.\n\nObjet fourni : \n", description = "Et voilà, <nom>. Il suffit d'appuyer la gemme sur un des piédestaux près de la base de la tour, et ses défenses s'activeront. Utilisez-la pour rentrer dans la tour quand vous serez <prêt/prête> et allez chercher les autres objets de Trelane. \n\nBonne chance à vous ! Je vous attendrai au camp. Oh ! Parlez à Skuerto avant de partir. Il vous donnera tous les détails nécessaires.", progress = nil, completion = "Bien, bien !\n\nSi vous n'avez pas autre chose à faire, alors commençons.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[696] = {title = "Attaque sur la tour", objective = "Trouver le Phylactère de Trelane, l'Orbe de Trelane et l'Agathe d'ambre de Trelane. Les rapporter à Skuerto au Refuge de l'Ornière.", description = "Voici ce qu'il faut récupérer : le Phylactère de Trelane, l'Orbe de Trelane et l'Agate de braise de Trelane.\n\nLes trois objets doivent se trouver dans un coffre dans la tour, vous ne devriez pas avoir de problème pour l'ouvrir ; faites juste attention aux ogres.\n\nLes défenses de la tour ne s'occuperont pas d'eux ; vous devez avoir vos armes prêtes. Quand les ogres remarqueront que vous êtes là pour les voler, ils risquent de ne pas apprécier.\n\nSoyez <prudent/prudente>, et bonne chance.", progress = "Si vous faites cela, je suis persuadé que Malin vous proposera plus que son amitié.", completion = "Malin n'aurait pu trouver personne plus compétente à nous envoyer pour nous aider, &lt;nom&gt;. Vous avez accompli un exploit !\n\nIl sera heureux de savoir que la mission est une totale réussite.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[697] = {title = "La demande de Malin", objective = "Porter la Lettre scellée à l'archimage Malin dans le quartier des mages de Stormwind.", description = "Apportez cette lettre à Stormwind et informez Malin que Kryten sera bientôt de retour. Il vous récompensera pour nous avoir aidés, <nom>, sans aucun doute.\n\nBon voyage.", progress = "Oui ? J'ai l'impression de vous connaître. Excusez-moi, on s'est déjà vu ? Je suis si occupé que j'en perds un peu la tête.", completion = "&lt;L'archimage Malin ouvre la lettre, et ses yeux s'agrandissent.&gt;\n\nPar la Lumière, vous avez réussi ! C'est un miracle ! Trelane va être si content. Je suis persuadé que Kryten et Skuerto sont aussi excités que moi de les rapporter à Stormwind.\n\nMerci, &lt;nom&gt;. S'il vous plaît, prenez ceci pour vous aider lors de vos voyages.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge de vigilanceBottes des ailés\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[698] = {title = "Petit bonus du soir", objective = "Apporter 8 Flancs de Dents-de-scie non préparés à Tok'Kar dans le marais des Chagrins.", description = "Je rassemble des provisions pour notre avant-poste près de la plage à l'est. Tok'kar fait ce qu'il peut, mais entre les tours de garde et la cuisine pour ses soldats, ses journées sont déjà bien remplies.\n\nIls aiment cuisiner de la viande de Dents-de-scie quand ils le peuvent, mais je n'ai pas le temps de leur en trouver une autre cargaison. Cela vous dérangerait de m’aider ?\n\nLes jeunes Dents-de-scie n'ont pas autant de goût que ceux plus âgés, alors laissez-les en paix un an ou deux pour qu'ils atteignent leur taille adulte.", progress = "Lok'tar, <classe>. Se risquer dans les marais ne se fait pas à la légère. Vous avez du courage pour venir ici tester vos compétences.", completion = "Ah ! Magnifique ! De la viande fraîche pour ce soir. Merci, &lt;nom&gt;.\n\nVous allez rendre notre soirée plus supportable. Nous aurons un bon feu et l'estomac plein ce soir.\n\nC'est une bonne surprise que vous nous faites là ; merci d’avoir apporté le ravitaillement. Dar n'est pas le plus attirant des orcs, quand on le regarde, mais ses petites attentions sont meilleures que son odeur.", rewards = "Vous recevrez :\n\n"},
[699] = {title = "Petit bonus du soir", objective = "Apporter 6 Griffes de Mordeurs Dents-de-scie à Tok'Kar dans le marais des Chagrins.", description = "En raison de la menace des murlocs le long des côtes, nous sommes stationnés ici pour repousser, ou au pire alerter s'ils sont trop nombreux, toutes les menaces sur Stonard. Nous n'avons pas vraiment le temps de respirer, donc si vous le souhaitez, vous pouvez rejoindre nos rangs pour nous aider.\n\nLes Griffes de Mordeurs Dents-de-scie sont un excellent matériau pour fabriquer des armes. Rapportez-m'en quelques-unes et nous vous donnerons une de nos armes, de la viande fraîche et une bonne compagnie.", progress = "De la bonne bière, un bon feu, une armée d'orcs et un stock d'armes... C'est tout ce dont nous avons besoin le long de ces côtes. Je ne me plains pas d'être ici à protéger Stonard, mais cela me plairait un jour d'avoir une petite propriété, ou tout au moins une tour…", completion = "Je suis content de voir que vous êtes en vie et entier, &lt;nom&gt;.\n\nCes griffes conviennent parfaitement. Plus nous aurons d'armes pour combattre, mieux c'est.\n\nJe vais commencer votre arme dès maintenant. Cela ne prendra pas longtemps. Je suis devenu un expert dans la fabrication de ce type d'arme.", rewards = "Vous recevrez :\n\n"},
[700] = {title = "Hommage royal", objective = "Rendre compte au Roi Magni Bronzebeard.", description = "Ah, Lordaeron fournit une si belle pierre. Il est si dommage que cette terre connaisse une telle confusion.\n\nMais la construction du Mémorial s'est très bien déroulée ! Je pense que cette nouvelle ravira le Roi.\n\nÀ présent, si vous le voulez bien, veuillez informer Sa Majesté que le Mémorial est prêt, comme il l'a ordonné.", progress = nil, completion = "Le granit ne semble être qu'un minuscule souvenir comparé à la grande vie d'un nain. Mais aucun nain ne restera sur cette planète pour l'éternité.\n\nEspérons simplement que le Mémorial constituera un rappel pour ceux qui parcourront la grande Azeroth de l'avenir, afin qu'ils n'oublient pas que c'est pour eux que de courageux guerriers tels que Sully Balloo ont si vaillamment donné leurs vies.", rewards = "Vous recevrez :\n\nAnneau mémorial d'Ironforge"},
[701] = {title = "La ruse du raptor", objective = "Récupérer 12 Cœurs de raptor provenant de Charognards des hautes-terres pour Tor'gan.", description = "Avec quelques petites choses en plus, je serai capable de créer un objet qui donnera à Gor'mul la ruse du raptor ! Avec le pouvoir du raptor en lui, Gor'mul prendra conscience de notre puissance, et le guerrier qui sommeille en lui se réveillera !\n\nJ'ai besoin de cœurs de raptors pour créer l'objet et lancer le sort.", progress = "Tout est prêt, mais il me manque les cœurs.", completion = "Oui, cela fonctionne à la perfection. Je vais transférer la puissance et l'esprit du raptor dans cet orbe, qui les communiquera ensuite à Gor'mul.", rewards = "Vous recevrez :\n\n"},
[702] = {title = "La ruse du raptor", objective = "Donner l'Orbe de Tor'gan à Gor'mul.", description = "Prenez cet orbe et utilisez sa magie pour insuffler à Gor'mul l'essence des raptors. Cela va revigorer son esprit et lui redonner goût à la vie. Lorsqu'il sera comme avant, nous lui ferons un résumé de l'activité de la Horde, et il comprendra que pour nos incessantes batailles nous avons besoin d'un grand guerrier.", progress = "De retour ? Si il y a quelque chose dont je n'ai vraiment pas besoin, c'est bien de la pitié de Tor'gan.\n\nQu'est-ce que vous avez pour moi cette fois-ci ? Un bout de ficelle colorée ? Ou peut-être une corde, que je puisse mettre fin à ma misérable vie...", completion = "Finalement, ce que vous avez apporté semble plus intéressant que je ne le pensais. Cela rayonne d'un étrange pouvoir...", rewards = "Vous recevrez :\n\n"},
[703] = {title = "Ailes de busard grillées", objective = "Apporter 4 Ailes de busard à Rigglefuzz.", description = "Oh oui ! Mes ailes de busard grillées sont les meilleures ! La sauce est savoureuse et la viande est épicée à souhait. Son odeur attirerait les gens à des kilomètres à la ronde !\n\nJ'ai tout ce qu'il faut pour en préparer. Tout... excepté des ailes de busard !\n\nDonc si vous en voulez, apportez-moi des ailes de busard. Apportez m'en assez, et je vous donnerai même la recette !", progress = "Bonjour, <nom>. M'avez-vous apporté les ailes ?", completion = "Bien, je vais préparer ces ailes dès maintenant. Je m'imagine déjà en train de les manger !\n\nTenez, voici la recette, comme ça vous pourrez les faire vous-même !", rewards = "Vous recevrez :\n\nAile de busard grilléeRecette : Aile de busard grillée"},
[704] = {title = "Le destin d'Agmond", objective = "Apporter 4 Urnes de pierre gravées au Prospecteur Ironband au Loch Modan.", description = "Le dernier rapport que j'ai reçu d'Agmond est inquiétant, d'autant plus qu'à présent il est mort ! Il dit que son équipe a découvert des \"urnes anciennes\" au site de fouilles en dehors d'Uldaman. J'ai peur que les urnes qu'il y a découvertes n'aient poussé les troggs à agir, de la même manière que lorsque j'ai découvert les idoles.\n\nJ'ai besoin que vous récupériez ces urnes afin que nous les étudions. Allez au site d'Uldaman, récupérez-les, et revenez me voir.", progress = "Avez-vous trouvé ces urnes, <nom> ? Nous devons découvrir quel est le lien entre elles et les troggs !", completion = "Bon travail ! L'assiduité, accompagnée d'un peu de chance, nous permettra de découvrir le lien, quel qu'il soit, entre les troggs et ces artefacts anciens.\n\nVous avez rendu un grand service aux Prospecteurs, &lt;nom&gt;. Vos efforts ne seront pas oubliés. Et Agmond non plus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nGants de prospecteur"},
[705] = {title = "Pêche aux perles", objective = "Apporter 9 Perles bleues à Rigglefuzz dans les Terres ingrates.", description = "Les Terres ingrates sont inhospitalières. De dangereux prédateurs et de puissants charognards y pullulent. Effrayant, surtout pour un tout petit gobelin. Pour y survivre, il faut être astucieux !\n\nJe sais comment fabriquer des bombes éclairantes. Je les utilise pour éloigner les bêtes sauvages. Mais je commence à manquer d'un des ingrédients : de la poudre de perles bleues. Apportez-en et je vous récompenserai.\n\nHé ! J'espère que vous avez de bonnes bottes. Les perles bleues proviennent de palourdes qui vivent au Récif infâme.\n\nOuaip, le Récif infâme de Strangleronce !", progress = "Avez-vous mes perles ? Je n'ai presque plus de Bombes éclairantes !", completion = "Superbe ! J'ai juste besoin de les réduire en poudre... Puis de les mélanger avec un peu de ceci, puis un peu de cela.\n\nPrenez garde, charognards ! Préparez-vous à être aveuglés !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCarabine foudroyanteBaguette éclairante\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nBombe éclairante"},
[706] = {title = "Enchantement flamboyant éclatant", objective = "Récupérer un Cœur de drake noir pour Sigrun Ironhew.", description = "En tant qu'apprenti de Feranor Steeltoe, j'ai appris à créer des armes dotées d'un enchantement flamboyant. La dernière fois que j'ai entendu parler de lui, il travaillait dans une forge à Lordaeron.\n\nJe ne peux pas vous donner beaucoup de détails quant au processus, mais je sais qu'il requiert du sang d'un cœur de drake noir qui bat encore. Je n'ai pas grand-chose à faire en attendant les ordres d'Ironforge. Si vous me rapportez un tel cœur du ravin de Lethlor, je vous montrerai mes talents !", progress = "Comment s'est passée la chasse, <classe> ?", completion = "Oh oui ! Cela conviendra parfaitement. Cela permettra à votre arme de porter des coups brûlants !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEnchantement d'éclat flamboyant"},
[707] = {title = "Ironband a besoin de vous !", objective = "Parler au Prospecteur Ironband, sur le Site de fouilles de Loch Modan.", description = "<nom>. J'ai reçu une demande du Prospecteur Ironband : il a besoin de quelqu'un pour un travail sur un de nos sites.\n\nJe n'ai pas plus de détails, mais si vous allez voir Ironband, il vous en donnera.", progress = nil, completion = "Vous venez de la part de Stormpike ? Bien.\n\nJ'ai une tâche importante pour vous...", rewards = "Vous recevrez :\n\n"},
[708] = {title = "La boîte noire", objective = "Apporter la Boîte noire corrodée au Hall des armes, à Ironforge.", description = "La surface de cette boîte noire métallique est fortement grêlée, comme si elle avait été immergée dans de l'acide. Elle a dû rester longtemps dans l'estomac du Condor géant.\n\nAlors que vous retournez la boîte, vous découvrez un symbole gravé à sa base. Sous le symbole, on peut lire :\n\n\"Moteur n°19 - Brigade des sapeurs d'Ironforge\"Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[709] = {title = "La solution à la malédiction", objective = "Rapporter la Tablette de Ryun'eh à Theldurin l'Egaré.", description = "Oh dieux ! Une malédiction approche. Écoutez-moi ! Une malédiction !\n\nNon, je ne peux pas en parler... je ne peux pas prononcer leur nom, ils pourraient entendre ! Mais si vous voulez savoir, oui si vous voulez en savoir plus sur eux... Alors vous en apprendrez peut-être assez pour les contrecarrer !\n\nPeut-être.\n\nAllez à Uldaman. Non ! Je l'ai dit ! Vous devez trouver... trouvez la tablette de... Ryun'eh. Oui, trouvez-la ! Et ne me faites plus prononcer ce nom !\n\nElle est au fond de cet endroit, dans un ancien coffre. C'est là qu'elle est cachée... dans un coffre construit bien avant n'importe quelle construction naine.", progress = "Avez-vous trouvé la tablette ? Elle doit contenir des secrets ! Ces secrets peuvent nous sauver !", completion = "Oh ! La chance est avec nous ! Merci ! Nous allons peut-être en réchapper !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nRobe d'auspice funeste"},
[710] = {title = "Étude des éléments : la roche", objective = "Trouver 10 Petits Eclats de Pierre et les porter à Lotwil Veriatus dans les Terres ingrates.", description = "Ici, dans les Terres ingrates, mes travaux sur mon dernier projet, des entraves pour élémentaires, sont bloqués.\n\nSi j’aboutis, elles permettront aux mages d'invoquer des élémentaires très puissants. Pour les finaliser, j'ai besoin de tester certains de mes nouveaux sorts offensifs sur quelques bidules que j'ai sous la main. Il me faut donc de petits éclats de pierre.\n\nCes éclats peuvent facilement être récupérés sur les élémentaires de roche inférieurs, à l'ouest d'ici. Pouvez-vous m'en apporter ?", progress = "C'est l'endroit parfait pour… Pouvez-vous tenir cela un moment ? Oui, exactement comme ça, le long du vecteur normal. Maintenant, qu'est-ce que... Ah oui ! C'est parfait pour tester mon dernier projet. De la matière première, un espace dégagé... Que pourrait demander d'autre un brillant et intelligent adepte de la magie ?", completion = "Cela devrait convenir parfaitement, &lt;nom&gt;. Merci. Hum ! Un peu plus de sable que j'avais prévu. Je dois ajuster le coefficient de friction. Non, attendez… Cela devrait devenir négligeable avec de l’Huile glaciale.", rewards = "Vous recevrez :\n\n"},
[711] = {title = "Étude des éléments : la roche", objective = "Apporter 3 Grands blocs de pierre à Lotwil Veriatus dans les Terres ingrates.", description = "<nom>, vous avez déjà montré plus de capacités que tous mes apprentis réunis.\n\nLes prochaines parties dont j'ai besoin nécessitent un peu plus de force. On trouve de larges plaques de pierre sur des élémentaires de roche, en étant prudent. Leurs corps sont plus forts et plus grands, et ainsi plus enclins à posséder des morceaux assez importants pour mes tests. Ils se trouvent encore plus à l'ouest d'ici, ou bien au sud-est le long des bords des montagnes.\n\nPrenez votre temps, j'en aurai besoin pour tester ces plus petites parties que vous m'avez apportées.", progress = "Je suis aux anges, <nom> ! Mes sorts fonctionnent exactement comme je l'avais prévu sur ces petits éclats. Si cette expérience réussit comme je le pense, alors je pourrai contrôler des élémentaires beaucoup plus puissants que tous ceux qui ont été invoqués jusqu'à présent.", completion = "&lt;nom&gt;, stupéfiant ! Je pensais qu'il me faudrait au moins une demi-douzaine de taurens pour arriver à ce résultat.", rewards = "Vous recevrez :\n\n"},
[712] = {title = "Étude des éléments : la roche", objective = "Apporter 5 Brassards de liaison de pierre à Lotwil Veriatus dans les Terres ingrates.", description = "<nom>, il y a une dernière chose dont j'ai besoin en provenance des Terres ingrates : des brassards de liaison de pierre portés par des élémentaires de roche supérieurs. Selon mes calculs, ces brassards me suffiraient pour calibrer mes propres liaisons.\n\nMes divinations pour localiser des élémentaires de roche supérieurs m'ont permis de trouver un groupe au sud-ouest d'ici, à côté d'ogres si je me souviens bien.\n\nRapportez-moi 5 de leurs brassards, comme ça j'en aurai un peu plus que nécessaire. La fameuse légende comme quoi Servo gâche un peu trop de réactifs...", progress = "Les blocs de pierre que vous avez trouvés sont parfaits, <nom>. Lucien va apporter le surplus à Kharanos quand nous en aurons fini ici. Après tout, ils peuvent encore être utiles.\n\nCes blocs conviendraient parfaitement pour construire un petit abri, quand je commencerai mes expériences sur des puissants explosifs, par exemple...", completion = "&lt;nom&gt;, avez-vous déjà pensé à devenir assistant dans la recherche ? Non ? Je ne sais pas comment je vais faire sans vos talents. L'intelligence, la curiosité et la force, le tout réuni en une seule et même personne…", rewards = "Vous recevrez :\n\n"},
[713] = {title = "La tête froide l'emporte toujours", objective = "Trouver de l'Huile glaciale et la porter à Lotwil Veriatus dans les Terres ingrates.", description = "Laissez-moi vous apprendre quelque chose sur l'Huile glaciale : elle a la meilleure capacité de refroidissement pour les embrayages et les moteurs.\n\nSes propriétés sont sans égales, et en plus elle lubrifie à merveille et durablement. Et ce n'est pas tout : elle aide à maintenir les enchantements sur les objets.\n\nJ'ai besoin d'une fiole de cette huile pour augmenter la capacité de mes entraves, afin qu'elles soient assez puissantes pour protéger l’invocateur de la créature invoquée.\n\nBro'kin, un de mes amis gobelins, peut vous apprendre à en faire. Il se trouve en Alterac.", progress = "Avez-vous trouvé l'huile dont j'ai besoin ? Cela m'aiderait vraiment si vous en trouviez.", completion = "Prodigieux ! C'est le refroidisseur parfait pour mes nouveaux bracelets. Si maintenant mon enchantement ne dure pas un siècle, je donne toutes mes possessions à Servo.\n\nTous les mages de l'Assemblée vont admirer et respecter mon travail quand ils vont voir ça, &lt;nom&gt;. Attendez et regardez.", rewards = "Vous recevrez :\n\n"},
[714] = {title = "Un Gyro... quoi ?", objective = "Apporter un Gyrochronatome à Lotwil Veriatus dans les Terres ingrates.", description = "<nom>, vous avez brillamment accompli votre travail.\n\n<Lotwil est visiblement obnubilé par son travail.>\n\nSi vous venez à Kharanos, n'hésitez pas à me rendre visite.\n\nOups ! Vite ! Rattrapez le... oui, ça là. Merci.\n\nMaintenant, j'ai juste besoin d'une dernière petite chose. C'est un petit truc, mais c'est indispensable, j'en ai peur : un Gyrochronatome.\n\nSi vous pouviez en récupérer un et me l'apporter, alors je pourrais finir ceci.", progress = "Oui, oui, oui… Une seconde !\n\n<Lotwil continue de travailler sur un truc.>", completion = "AH !\n\n&lt;Lotwil saisit le Gyrochronatome.&gt;\n\nParfait... Presque finalisé. Non, vraiment. J'ai presque fini. Ce projet est ma priorité numéro un... pour le moment. Laissez-moi placer ceci, et vous allez pouvoir admirer ce à quoi vous avez contribué. Cela ne me prendra que quelques minutes de plus... peut-être... un peu plus longtemps. Bien, peut-être même beaucoup plus longtemps. Nous verrons...", rewards = "Vous recevrez :\n\n"},
[715] = {title = "Pierre liquide", objective = "Apporter une Potion d'invisibilité inférieure et une Potion de soins à Lucien Tosselwrench dans les Terres ingrates.", description = "Je pense que les objets que vous avez récupérés pour Lotwil sont le dernier de nos soucis, <nom>. En revanche, vous avez prouvé que vous étiez <expert/experte> en sciences, et ça, c'est sacré pour Lotwil, donc comment pourriez-vous m'aider ?\n\nJ'ai besoin d'une Potion d'invisibilité et d'une Potion de soins ; elles seraient rapidement prêtes s’il daignait arrêter ce qu'il est en train de faire.\n\nEn échange, je vous donnerai la recette d’une potion que j’ai conçue quand j'étais l'élève de Lotwil. Elle est basée sur les recherches qu'il fait dans les Terres ingrates.", progress = "Il a bientôt fini. Et vous, où en êtes-vous ?", completion = "OUI !\n\nJe veux dire, merci, &lt;nom&gt;. Cela va nous être très utile pour notre voyage dans les Terres ingrates.", rewards = "Vous recevrez :\n\nRecette : Potion de Bouclier de pierre inférieurePotion de Bouclier de pierre inférieure"},
[716] = {title = "Mieux est la pierre que le tissu", objective = "Apporter des Brassards guillochés en bronze à Lucien Tosselwrench dans les Terres ingrates.", description = "Je sais à quel point Lotwil peut faire preuve de mesquinerie, <nom>, aussi laissez-moi vous confectionner quelque chose en échange de tous vos efforts. Cela vous protégera peut-être même de l'atrocité imminente qu'est la nouvelle invention de Lotwil.\n\nJ'ai travaillé avec le surplus des pierres que vous avez trouvées pour lui, et je peux faire de bons brassards que vous pourriez porter. Des brassards enchantés, bien-sûr.\n\nJ'aurais juste besoin qu'un forgeron me fasse des brassards guillochés en bronze pour les terminer.", progress = "Je ne peux pas attendre trop longtemps ces brassards, <nom>.\n\nPersonne ne sait ce que l'avenir nous réserve.", completion = "Vous êtes là, &lt;nom&gt;. Essayez-les !", rewards = "Vous recevrez :\n\nBrassards enchantés en étoffe de pierre"},
[717] = {title = "Tremblement de terre", objective = "Utiliser le Signe de la Terre pour activer les Piliers d'Améthyste, d'Opale et de Diamant, et obtenir les Pierres runiques.\n\nPlacer les Pierres runiques dans le Sceau de la Terre pour libérer Cinglenoir et Hematus.\n\nLes tuer, puis rapporter les Liens de Cinglenoir, les Entraves de Hematus et le Signe de la Terre à Garek.", description = "Il est devenu évident que nous ne pouvons plus garantir que Cinglenoir et Hematus resteront prisonniers à Lethlor. Les dragons noirs qui se sont installés là-haut, et les ogres qui projettent de voler le Signe, tout cela nécessite des mesures draconiennes.\n\nLa prison des drakes est scellée grâce à trois Pierres runiques qui ne peuvent être retrouvées que par le Signe de la Terre. Ces Pierres runiques peuvent être utilisées pour briser le sceau qui les garde enfermés.\n\n<nom>, faites en sorte qu'ils ne se réveillent jamais.", progress = "De puissants pouvoirs gardent la prison des drakes, mais nous ne pouvons prendre le risque que Cinglenoir et Hematus soient libérés.", completion = "Kirin Tor n'a plus à se soucier des prisonniers de Lethlor. Je vais aller prévenir mon maître de votre succès. Krasus va être ravi.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCuirasse des vents brûlantsHaubert en écailles prismatiquesPansière de guerreMédaillon d'explosion mentale\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[718] = {title = "Mirages", objective = "Retrouver la Caisse de fournitures pour Sigrun Ironhew.", description = "Dans notre précipitation pour quitter le site de fouilles d'Uldaman, nous avons été obligés d'abandonner de nombreux chariots et caisses de fournitures le long du chemin. Les ogres locaux du Camp Kosh se sont précipités sur notre équipement comme des vautours sur une charogne. Ils ne sentent pas meilleur d'ailleurs. Que la charogne je veux dire !\n\nEnfin bref, ils ont pris une caisse qui contenait toutes nos armes et notre... ben, c'est un peu embarrassant, nous n'avons pas pris de nourriture avec nous.\n\nNous sommes dans le pétrin maintenant, pourriez-vous nous aider ?", progress = "Le désert, c'est pas un bon endroit pour avoir faim, camarade, ça je peux vous le dire !\n\nHé ! Qu'est-ce qu'il y a là-bas...", completion = "Merci beaucoup, &lt;nom&gt;. Quand vous n'étiez pas là, je... hum... J'ai mangé du sable. C'est...\n\nEnfin bref, nous allons enfin manger ce soir. Un festin de roi !", rewards = "Vous recevrez :\n\n"},
[719] = {title = "Un nain et ses outils", objective = "Trouver le Piolet de chance de Ryedol et le rapporter au Prospecteur Ryedol au sud du site de fouilles de Hammertoe.", description = "Bonjour, <nom>. Faites attention par ici. Il y a des nains Sombrefer partout : ils ressemblaient à ceux du clan Ombreforge.\n\nIls viennent juste d'attaquer le site de fouilles où je travaillais... Ils ont tué pratiquement tout le monde, y compris mon chef, Hammertoe. J'ai réussi à m'enfuir, c’est pourquoi je suis encore en vie.\n\nLe site se trouve au nord. Je projette de récupérer nos fournitures et plus particulièrement mon piolet porte-bonheur.\n\nPouvez-vous m'aider ? L'un de ces maudits Sombrefer doit avoir mon piolet.", progress = "Je ne suis pas sûr de ce que cherchaient les Ombreforge, mais ils ont de toute évidence un but.", completion = "Vous êtes mon sauveur, &lt;classe&gt;. Je suis heureux que quelqu'un ait donné une leçon à ces Ombreforge. Merci de votre aide.", rewards = "Vous recevrez :\n\nMarteau de Ryedol"},
[720] = {title = "Un signe d'espoir", objective = "Trouver le Prospecteur Ryedol et lui dire que Hammertoe Grez est en vie.", description = "<Des mots sont grossièrement écrits à la craie sur la carte.>\n\n\"Ryedol, \nIls m'emmènent à Uldaman. Envoie de l'aide.\n-Hammertoe\"", progress = nil, completion = "Hammertoe en vie ? C'est incroyable, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[721] = {title = "Un signe d'espoir", objective = "Trouver Hammertoe Grez à Uldaman.", description = "<nom>, l'avez-vous trouvé ? Avez-vous trouvé Hammertoe à Uldaman ?\n\nSi ces sales Ombreforge le gardent pour le faire parler des anciens Titans, alors tout Ironforge court un grand danger.\n\nDepuis longtemps maintenant, les Sombrefer sont à la recherche de magies pour créer des Golems très puissants. Hammertoe faisait la même chose, mais dans le but de les contrecarrer.\n\nIls le garderont probablement en vie tant qu'ils ne lui auront pas arraché toutes ses connaissances. Nous devons nous dépêcher de le sauver !", progress = nil, completion = "Oui ? Je suis désolé... &lt;Toux&gt; Suis si faible. Approchez-vous, &lt;classe&gt;.\n\nRyedol vous envoie ? Muradin soit loué ! Ce garçon n'est pas aussi bête que je le pensais.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[722] = {title = "L'amulette des secrets", objective = "Trouver l'Amulette de Hammertoe et lui rapporter à Uldaman.", description = "Vous avez du courage… <toux>… pour venir jusqu'à Uldaman pour moi, <classe>.\n\nSi vous êtes vraiment là pour aider… le vieux Hammertoe, alors… <toux>… vous devrez me trouver… une amulette.\n\nDeepshadow l’a… Magregan Deepshadow. L'est dans l'coin... dans les ruines, c'est sûr. L'amulette les mènera... <toux>... droit aux parchemins si on n'l'arrête pas. Ça dépend de vous, <nom>. Je vous en prie... récupérez-la.\n\nLes parchemins aideront sans doute les Sombrefer à créer des Golems encore plus puissants. Je l'sais, c'est tout. Je peux le sentir dans mes os.", progress = "Le clan Ombreforge... <Toux> … est dangereux. Soyez prudent. <toux> Vous devez trouver l'amulette.", completion = "Ah ! &lt;toux toux&gt;\n\nJe savais que vous la retrouveriez, &lt;nom&gt;.\n\nVraiment bien joué, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[723] = {title = "Espérance en la foi", objective = "Porter l'Amulette de Hammertoe au Prospecteur Ryedol dans les Terres ingrates.", description = "<Hammertoe tient sa blessure et attend un moment pour reprendre son souffle avant de continuer.>\n\nTrouvez Ryedol, <nom>. Portez-lui l'amulette. <toux toux> Il... <toux> saura quoi en faire. Il sait que je recherchais l'origine de notre peuple, et il... <toux>... sait que c'était ma mission que d'arrêter le clan Ombreforge. Ils ne doivent pas s'emparer de ces parchemins... <toux>", progress = "Je l'avais dit que c'était une sale journée, mais chaque journée dans les Terres ingrates est une sale journée.", completion = "L'Amulette de Hammertoe ? Je me sentais mieux quand je le croyais mort. Maintenant que c’est une certitude, c'est pire. Cette amulette est l'œuvre de sa vie. Je ne peux pas le laisser mourir pour rien.", rewards = "Vous recevrez :\n\n"},
[724] = {title = "Espérance en la foi", objective = "Apporter l'Amulette de Hammertoe à l'historien Karnik à Ironforge.", description = "D'accord, d'accord... Qui pourrait savoir quoi en faire ?\n\nL'historien Karnik ! Bien sûr !\n\nIl est à Ironforge. Lui pourra nous aider. Lui et Hammertoe travaillaient ensemble pour retrouver des artefacts perdus à Uldaman.\n\nJe pense que le clan Ombreforge a trouvé deux d'entre elles et qu'il en sait plus qu’il n’y paraît.\n\nRacontez à Karnik ce qui est arrivé et donnez-lui l'amulette. Il vous dira quoi faire ensuite.", progress = "Ah oui ! Encore un voyageur qui veut quelques faveurs des nains.\n\nM'sieur, je suis réellement désolé, mais je n'ai pas le temps pour de futiles discussions.", completion = "Oh ! Cela change complètement les choses. Est-ce que vous vous rendez compte de l'importance de cela ?\n\nJe suis profondément touché par la mort de Hammertoe, mais s’il vous a envoyé ici avec l'amulette, alors c'est qu'il a compris son importance.\n\nNous prendrons le temps plus tard de pleurer sa mort.\n\nLaissez-moi vous montrer une des raisons de l'importance de cette amulette.", rewards = "Vous recevrez :\n\n"},
[725] = {title = "Avertir de la menace", objective = "Trouver le Conseiller Belgrum et lui donner la Note.", description = "<nom>, courrez trouver le Conseiller Belgrum aussi vite que vous le pourrez. Dites-lui ce que vous savez et demandez-lui ce que nous devons faire. Cette note lui donnera plus d’information.\n\nPendant ce temps, je vais essayer de contacter l'esprit de Hammertoe. Peut-être qu'il sait quelque chose qui pourrait nous aider à mettre un terme aux stupides activités des Ombreforge dans les Terres ingrates. Il faut le souhaiter.", progress = "Hmm? Oui, <classe>, je vous écoute...", completion = "Ah ! Un mot de l'Historien Karnik. Excellent.\n\nJ'ai toujours du temps à lui consacrer.\n\n&lt;Le Conseiller Belgrum ouvre la note et commence à la lire.&gt;", rewards = "Vous recevrez :\n\n"},
[726] = {title = "Avertir de la menace", objective = "Parler à l'Historien Karnik.", description = "<Le Conseiller Belgrum achève de lire la note, et ses yeux s'élargissent un moment.>\n\nHoula, très mauvaises nouvelles !\n\n<nom>, Retournez voir l'Historien Karnik et dites-lui qu'il agit sous l'autorité du roi, et qu'il s'occupe de cette affaire rapidement et avec fermeté. Il doit mettre un terme aux activités des Ombreforge dans les Terres ingrates.", progress = nil, completion = "Vous allez traiter cette affaire dans les meilleurs délais comme le roi le souhaite, &lt;nom&gt;.\n\nTrès bien, alors. Je sais comment abattre les Ombreforge.\n\nLeur présence à Uldaman peut être réduite si nous frappons à la base : la Forteresse d'Angor.", rewards = "Vous recevrez :\n\n"},
[727] = {title = "Aller à Ironforge chercher le « Sommaire de Yagyin »", objective = "Donner le Glyphe du Marteau à Gerrig Bonegrip, dans la caverne lugubre d’Ironforge.", description = "Les tablettes en disent long. Mais pas assez ! Vraiment pas assez !\n\nIl y a un livre, que Yagyin a écrit il y a des années. Les... gens que j'ai fuis... ils en ont toujours un exemplaire sous la main. Et ils l'étudient presque tous. Ce livre renferme un immense savoir. Un savoir qui peut nous permettre de nous protéger !\n\nAllez voir Gerrig Bonegrip. Il se trouve dans une boutique à Ironforge, dans la caverne lugubre. Montrez-lui ce glyphe et il pensera que vous êtes un des leurs. Demandez-lui le \"Sommaire de Yagyin\"... et rapportez-le-moi !", progress = "Bonjour. Bienvenue dans mon magasin, mais faites attention à ce que vous touchez.\n\nLe savoir peut être fatal…", completion = "Oh ! Salutation, frère.\n\nEt priez les habitants d'en dessous.", rewards = "Vous recevrez :\n\n"},
[728] = {title = "Pour le « Sommaire de Yagyin »", objective = "Apporter le Glyphe du Marteau au Gardien Bel'dugur à Undercity.", description = "Les tablettes en disent long. Mais pas assez ! Vraiment pas assez !\n\nIl y a un livre, que Yagyin a écrit il y a des années. Les... gens que j'ai fuis... ils en ont toujours un exemplaire sous la main. Et ils l'étudient presque tous. Il comprend un immense savoir. Un savoir qui peut nous permettre de nous protéger !\n\nAllez voir le Gardien Bel'dugur à Undercity, Lordaeron. Montrez-lui ce glyphe et il pensera que vous êtes un des leurs. Demandez-lui le « Sommaire de Yagyin »... et rapportez-le-moi !", progress = "Ah ! Nous avons un <classe> pressé, à ce que je vois. Vous venez pour apprendre ? Bien !\n\nMais faites attention : le savoir donne le pouvoir si on est capable de le maîtriser... Sinon il vous rend fou.", completion = "Soyez discret avec ce signe, &lt;classe&gt;. Il y a ceux qui ne croient pas à la vertu de notre engagement.\n\nEt ceux qui voudraient nous faire échouer s’ils avaient vent de notre existence.\n\nNous devons être prudents. Et vigilants. Et patients.", rewards = "Vous recevrez :\n\n"},
[729] = {title = "Les absences du Prospecteur", objective = "Aller vers le sud et vérifier l'état de santé du Prospecteur Remtravel.", description = "Quel honneur cela a été quand Maître Greywhisker m'a affecté aux ordres du grand Prospecteur Remtravel. À l'Académie d'Ironforge tout le monde connaît les grandes découvertes de Remtravel.\n\nMais le Prospecteur est plutôt... hum... inconscient... de son environnement.\n\nNous avons découvert les traces d’une grande société. D'horribles Golems sont sortis du sol et ont envahi le site. Remtravel n'a pas semblé s'en apercevoir. J'ai fui à Auberdine pour demander de l'aide.\n\nS'il vous plaît, allez vers le sud pour voir si le prospecteur va bien !", progress = nil, completion = "Hollee, est-ce que c'est vous ? J'ai besoin d'aide pour gratter cette pierre. Donnez-moi mon pinceau à pierre, j'ai l'impression de voir quelque chose.\n\nHé ! Vous n'êtes pas Hollee ! Je suppose que vous n'avez pas vu mon pinceau à pierre ?\n\nC'est pas bien grave ! Mais j'ai promis à la ligue d'envoyer ce mystérieux fossile. Où est parti Hollee ?\n\nIl y a tellement de travail à faire ! Et où est donc ce fossile... et mon burin... et Hollee...\n\nEt qui êtes-vous ? Ça n'a pas d'importance, du moment que vous pouvez m'aider.\n\nFaites-moi savoir quand vous serez prêt.", rewards = "Vous recevrez :\n\n"},
[730] = {title = "Des problèmes à Sombrivage ?", objective = "Aller à Auberdine et chercher des indices sur les nains de l'équipe de fouilles.", description = "Il est plaisant de voir qu'un <classe> s'intéresse à l'archéologie et aux grandes merveilles de notre monde.\n\nBien souvent, notre métier est considéré comme un simple passe-temps par nos amis de l'Alliance. Mais ce que la plupart d'entre eux ne comprennent pas, c'est que les récentes découvertes dans Khaz Modan ont prouvé que de grandes et mortelles puissances menacent tout Azeroth, de Lordaeron à Kalimdor.\n\nJe suis vraiment inquiet pour le groupe que j'ai envoyé à Sombrivage. Je suis sans nouvelles de lui depuis des semaines.\n\nAllez à Auberdine et cherchez des indices sur ce qu'il lui arrive.", progress = nil, completion = "Je suis enchanté de l’envoi du Chef archéologue Greywhisker...", rewards = "Vous recevrez :\n\n"},
[731] = {title = "Les absences du Prospecteur", objective = "Protéger le Prospecteur Remtravel pendant qu'il recherche le mystérieux fossile, puis revenir voir l'Archéologue Hollee à Auberdine.", description = "Alors, Hollee... Oh c'est vrai ! Vous n'êtes pas Hollee. Où est Hollee ?\n\nBah, ce n'est pas le problème ! Nous devons trouver ce pinceau à pierre... enfin je veux dire ce mystérieux fossile ! Nous devons le trouver. La Ligue des Explorateurs à Darnassus veut savoir sur quoi je travaille.\n\nDites-moi quand vous serez d'accord et nous partirons à la recherche de ce pinceau.... je veux dire de ce fossile ! Nous trouverons peut-être quelque chose d'intéressant à écrire à la Ligue.\n\nAlors on y va ?", progress = nil, completion = "Grâce au Ciel le Prospecteur Remtravel est sain et sauf ! Je vous avais dit qu'il avait des absences. Je ne peux pas croire qu'il ait voulu rester là-bas avec toutes ces horribles créatures qui traînent.", rewards = "Vous recevrez :\n\n"},
[732] = {title = "Tremblement de terre", objective = "Retrouver le Signe de la Terre pour Garek.", description = "Sigrun m'a expliqué que vous l'aviez beaucoup aidé. Vous pourrez peut-être aussi m'aider. Je suis envoyé par mon maître, Krasus de Kirin Tor, pour mettre fin aux problèmes dans le ravin de Lethlor.\n\nJe ne peux pas divulguer la nature exacte de ma mission, ni la tâche que je dois accomplir, mais elle est de première importance.\n\nUne bande d'ogres errants, qu'on a vu parfois près de Camp Boff, a volé un objet appelé le Signe de la Terre, que je dois récupérer. Si vous me le rapportez, je vous en dirai plus.", progress = "La bande d'ogres nomades voyage entre les camps des Terres ingrates, mais la chaleur qui monte de la terre et le vent qui tourbillonne rendent difficile le pistage dans cette contrée. J'ai entendu dire que de temps en temps ils font escale au Camp Boff. Si vous êtes perdu, vous devriez chercher de ce côté.", completion = "C'est une bonne nouvelle que vous rapportiez le Signe, &lt;nom&gt;. Le Signe de la Terre a été créé par les nains Sombrefer de la Forteresse d'Angor afin d'enfermer deux impitoyables lieutenants de l'Aile de mort, les jumeaux Cinglenoir et Hematus.", rewards = "Vous recevrez :\n\n"},
[733] = {title = "Demandes variées", objective = "Collecter 7 Morceaux de métal pour Sigrun.", description = "Cela va devenir difficile de se rendre ici si je ne peux pas me procurer du matériel pour construire des défenses et les choses nécessaires. J'ai remarqué que les ogres de la région semblaient bien équipés en morceaux de métal. Peut-être que les légendes à propos d’engins de siège dans les Terres ingrates ne sont pas si loin de la vérité finalement...\n\nQuoi qu'il en soit, le Prospecteur s'inquiète de l'état de notre petit camp, et j'aimerais commencer à y travailler dès que possible.\n\nLe camp principal des ogres est situé dans la grotte de Crache-poussière, assez loin d'ici en direction de l'ouest.", progress = "Bon, j'ai fait ce que j'ai pu, mais... ce n'est pas grand-chose. Avez-vous trouvé des fournitures supplémentaires ?", completion = "C'est un bon début, &lt;nom&gt;, et ça doit être fait avant que nous recevions des remarques de la part d'Ironforge ou de la Ligue des Explorateurs.\n\nMaintenant, si je pouvais trouver du sel pour mon baril à tremper...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier de SalbacBottes en fer armé\n\nVous recevrez également :\n\n"},
[734] = {title = "Grandes difficultés", objective = "Parler à Lucien Tosselwrench dans les Terres ingrates.", description = "Merveilleux, merveilleux.\n\n<Lotwil lève les yeux vers vous un instant avant de reprendre son travail.>\n\nAllez parler à Lucien, <nom>. J'ai besoin d'un rouage n° 5. Voulez-vous bien me l'apporter ?", progress = nil, completion = "Rouage n° 5, hein ? Ouais, ça ne conviendra pas.", rewards = nil},
[735] = {title = "L'étoile, la main et le cœur", objective = "Rapporter les Objets écrits sur le mot de Bonegrip à Gerrig Bonegrip dans Ironforge.", description = "Le \"Sommaire de Yagyin\", hein ? Vous allez établir une nouvelle branche de notre ordre, quelque part ? Laissez tomber, je n'ai pas à le demander.\n\nJe vais vous aider, j'en ai une copie en plus. On doit s'entraider, n'est-ce pas ? C'est comme cela que nous prospérons.\n\nJ'ai besoin de trois objets de puissance. Apportez-les-moi et je vous donnerai le livre.\n\nJe ne vais pas vous donner les noms de vive voix, les murs ont des oreilles, mais je vais vous les écrire.", progress = "Avez-vous les reliques ?", completion = "Vous êtes plein de ressources, &lt;classe&gt;. Si vous allez vraiment créer une branche de notre ordre, alors je suis sûr que vous allez bien la diriger.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[736] = {title = "L'étoile, la main et le cœur", objective = "Apporter les objets de la liste de Bel'dugur au Gardien Bel'dugur à Undercity.", description = "Vous avez besoin du « Sommaire de Yagyin » ? Vous projetez donc de réunir une nouvelle cellule ? Bien sûr que c'est le cas... et bien sûr que je vais vous aider, <frère/sœur>.\n\nMais vous devez m'aider aussi.\n\nJ'ai besoin de trois objets de puissance. Apportez-les-moi et je vous donnerai le livre.\n\nJe ne peux pas prononcer leurs noms, mais je peux vous les écrire.\n\nApportez-moi les objets de la liste. Si vous pouvez me les obtenir, alors vous méritez de créer une nouvelle branche de notre ordre.", progress = "Comment cela s'est-il passé, <classe> ?", completion = "Je suis impressionné ! Vous avez d'admirables qualités, ou énormément de chance, pour avoir récupéré ces reliques. Dans les deux cas vous êtes un atout pour nous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[737] = {title = "Le savoir perdu", objective = "Porter le « Sommaire de Yagyin » à Theldurin.", description = "J'ai le livre pour vous, <nom>. Je n'ai pas besoin de vous prévenir de bien y faire attention. Et de le garder hors de portée de nos ennemis. \n\nCe livre contient de nombreuses vérités...\n\n... Et la vérité peut vous consumer.", progress = "Oh ! Votre voyage a duré. Vous avez le livre ?", completion = "Vous l'avez ! Oh, l'espoir revient !\n\nVos efforts vont peut-être nous sauver, &lt;nom&gt;. Ils dresseront peut-être un monument pour vous ! Et c'est un autel qu’il faudrait ! Que votre nom soit loué durant des générations et des générations !\n\nSauf si... ILS sont libérés et reviennent à la surface. Si cela se produit vous pouvez oublier le monument et les louanges.\n\nSi ILS sont libérés, nous serons uniquement bons à nourrir les vers.", rewards = "Vous recevrez :\n\nCrâne de malédiction imminente"},
[738] = {title = "Trouver Agmond", objective = "Trouver Agmond.", description = "Le Prospecteur Agmond avait la charge de nos sites de fouilles dans les Terres ingrates, au sud-ouest. Je dis \"avait\" car… en fait, cela fait des semaines que je n'ai pas entendu parler de lui. J'ai besoin que vous le trouviez pour me ramener son rapport.\n\nAux dernières nouvelles, il se trouverait au site de fouilles le plus au sud des Terres ingrates, un minuscule site au-delà de la Forteresse d'Angor. Si j'étais vous, je commencerais mes recherches là-bas.", progress = nil, completion = "Ce squelette doit appartenir à ce malheureux Agmond. Son corps est constellé de coups et tous ses os sont brisés et nettoyés.", rewards = "Vous recevrez :\n\nCeinture de prospecteur abîméeJadeMinerai d'or"},
[739] = {title = "Murdaloc", objective = "Tuer l'assassin d'Agmond : Murdaloc.\n\nTuer 12 Briseurs d’os Cavepierre.\n\nEt revenir voir le Prospecteur Ironband au Loch Modan.", description = "Les traces d'Agmond partent de l'ouest. Les traînées de sang sur la pierre et sur le sable vous indiquent que le nain a rampé sur une certaine distance.\n\nEt il est mort ici.\n\nUn examen plus approfondi vous fait remarquer le mot \"Murdaloc\", tracé sur un tas de sable des Terres ingrates.\n\nTracé près de la main morte d'Agmond.", progress = nil, completion = "Voilà de bien tristes nouvelles, &lt;nom&gt;. Mais Agmond avait un bras puissant. Il était redoutable avec un marteau, et son crâne était aussi épais que possible. Bien qu'il ait été tué par ces maudits troggs, il est certain qu'il en a emporté de nombreux avec lui.", rewards = "Vous recevrez :\n\nDestructeur de roc"},
[740] = {title = "<INUTILISÉ>", objective = "Cette quête envoie les joueurs dans la Gorge des Vents brûlants.\n\nRestez sur vos gardes...", description = "Cette quête envoie les joueurs dans la Gorge des Vents brûlants.\n\nRestez sur vos gardes...", progress = nil, completion = nil, rewards = nil},
[741] = {title = "Les absences du Prospecteur", objective = "Apporter le Mystérieux fossile au Chef archéologue Greywhisker, à Darnassus.", description = "Alors le prospecteur veut envoyer le mystérieux fossile à la Ligue des Explorateurs à Darnassus ? Quitter Sombrivage sans lui… ce n'est pas bien.\n\nVoilà, <nom>, apportez le mystérieux fossile au Chef Archéologue Greywhisker à Darnassus.", progress = "Que puis-je faire pour vous, <nom> ?", completion = "Oh mon... ! Gloire au Prospecteur Remtravel d'avoir découvert une telle chose !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants poing-de-marteauGants du vent mordantCeinture de chasseur de reliques\n\nVous recevrez également :\n\n"},
[742] = {title = "La Chasse d'Ashenvale", objective = "Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", description = "Votre attention ! Les terres sauvages d'Ashenvale vous attendent tous !\n\nLa Horde s'est établie dans les terres au nord des Tarides. Nos deux avant-postes : le Poste de Bois-brisé et le Poste de la grève de Zoram s'efforcent bravement d'apporter la gloire à la Horde ! Ceux et celles qui veulent faire montre de leur courage devraient y trouver conseil. De plus, Senani Thunderheart, au Poste de Bois-brisé, directement au nord des Tarides, cherche en ce moment des candidats prêts à prendre part à une grande Chasse d'Ashenvale !", progress = nil, completion = "Bienvenue à la nouvelle frontière, &lt;nom&gt;. Ashenvale est une terre d'opportunités, où un jeune &lt;classe&gt; comme vous peut avoir de nombreuses chances de prouver sa vaillance. Faites le tour de l'Avant-poste et n'oubliez pas de voyager jusqu'à la Grève de Zoram, étant donné que la Horde a aussi un autre Avant-poste, là-bas.\n\nVotre présence ici me dit que vous êtes venu pour en apprendre plus sur l'art de la chasse. Écoutez attentivement, et je partagerai volontiers avec vous le savoir qui vous manque.", rewards = "Vous recevrez :\n\n"},
[743] = {title = "Le danger des Furies-des-vents", objective = "Apporter 8 Serres de Furie-des-vents à Ruul Eagletalon, au village Bloodhoof.", description = "Merci de prendre le temps de me parler, <nom>. Je suis Ruul, guerrier et professeur.\n\nVous avez atteint l'âge où il vous faut vous préparer à de dures épreuves si vous comptez vous aventurer hors de Mulgore.\n\nSi vous voulez éprouver votre force, commencez par aller chasser les harpies Furie-des-vents au sud-est. Elles nichent le long des crêtes des montagnes, loin de la route.\n\nElles sont l'un de nos ennemis naturels, ici à Mulgore. Les affronter éprouvera vos compétences.", progress = "Les harpies Furie-des-vents sont de redoutables adversaires. Leur force au combat n'a d'égal que leur désir de viande fraîche.", completion = "Bravo, &lt;nom&gt;. Vous semblez fin prêt pour voyager et aller de l'avant. Puissiez-vous cheminer sous des vents favorables.", rewards = "Vous recevrez :\n\n"},
[744] = {title = "Préparation à la cérémonie", objective = "Collecter 6 Plumes d'azur et 6 Plumes de bronze et les rapporter à Eyahn Eagletalon à Thunder Bluff.", description = "<nom>, mon frère doit bientôt se présenter devant le chef Bloodhoof et il est de mon devoir de lui faire une coiffe digne de ce nom.\n\nJe voudrais vous demander une faveur, pendant que je finis de tanner ces lanières de cuir. Je n'ai, hélas, pas eu le temps de collecter suffisamment de plumes et je me demandais si vous pouviez en rassembler quelques-unes pour moi ?\n\nVous pouvez trouver des plumes de bonne taille sur les harpies qui vivent loin au nord et au nord-ouest de Thunder Bluff. Je n'ai besoin que de 6 plumes d'azur et de 6 plumes de bronze.", progress = "Cette coiffe sera certainement un magnifique cadeau pour mon frère.", completion = "Merci de votre aide, &lt;nom&gt;.\n\nMa contribution à la cérémonie de mon frère est presque achevée. Lui remettre la coiffe et assister à cette cérémonie sont les seules obligations qui me soient imposées.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHarnais liéBouclier tribal\n\nVous recevrez également :\n\n"},
[745] = {title = "Partager la terre", objective = "Tuer 10 Tanneurs crins-pâles, 8 Ecorcheurs crins-pâles et 5 Braconniers crins-pâles, puis retourner voir Baine Bloodhoof, au village Bloodhoof.", description = "<nom>, il y a beaucoup de conflits qui ont dévasté cette terre. J'espère seulement que vous n'aurez pas à être le témoin du même nombre de batailles que je le fus, moi-même. Il y a pourtant une chose que je voudrais que vous fassiez ; cela vous montrera comment une menace, même minime, peut blesser ce pays, si elle n'est pas endiguée à temps.\n\nDes crins-pâles gnolls ont colonisé le sud de Bloodhoof et une grotte à l'ouest. Ils ne répondent pas à nos tentatives de communication et massacrent les animaux sauvages de Mulgore.\n\nAvec cette engeance, la diplomatie n'est, hélas, plus une solution satisfaisante.", progress = nil, completion = "&lt;nom&gt;, il est bon que vous ayez pris cette mission avec sérieux. Le respect du pays et de ses créatures est essentiel. La vie et la mort participent d'un cercle… d'une nécessité. L'une ne peut exister sans l'autre. Prenez le temps de méditer cela et ne l'oubliez jamais.", rewards = "Vous recevrez :\n\nBille d'éclair"},
[746] = {title = "Les fouilles des nains", objective = "Collecter 5 Piolets de prospecteur.\n\nÀ la forge, brisez les Piolets du prospecteur pour obtenir des Outils cassés.\n\nRapporter 5 Outils cassés à Baine Bloodhoof, au village Bloodhoof.", description = "Il y a des nains qui préparent des fouilles au nord-ouest. Ils pensent que la terre abrite des secrets et ils ont raison. Mais creuser et souiller le pays n'est pas un bon chemin vers la sagesse.\n\nCollectez les outils de forage des nains, fracassez-les et revenez avec les outils brisés.\n\nVous ne pourrez détruire les outils que dans une forge. Vous en trouverez une à Thunder Bluff, bien que n'importe quelle forge (même une forge dans le camp des nains) suffise à la tâche.", progress = "Bonjour, <nom>. Avez-vous les Outils cassés ? Les fouilles des nains vont mettre les kodos de Mulgore en furie. Cette profanation doit cesser !", completion = "Merci, &lt;nom&gt;. Cela calmera les bêtes de Mulgore. Peut-être, avec de la chance, les nains auront-ils compris que creuser des galeries dans la terre n'est pas le bon chemin vers la sagesse.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nManchettes fortifiéesJambières de kodo mal tannées\n\nVous recevrez également :\n\n"},
[747] = {title = "La chasse commence", objective = "Grull Hawkwind, à Camp Narache voudrait que vous lui apportiez 7 Plumes de trotteurs des plaines et 7 morceaux de Viande de trotteur des plaines.", description = "Vous avez un air prometteur, et vous allez avoir l'occasion de prouver votre valeur au sein de la tribu. Peut-être le jour est-il proche où l'on vous accueillera dans la grande ville de Thunder Bluff. Mais avant, vous devrez démontrer votre valeur à mon père, le Chef Hawkwind.\n\nIci, à la Mesa de Nuage rouge, nous sommes fiers de nos talents de chasseurs. Les taurens chassent par nécessité et par goût du sport. Notre stock de viande a diminué et nous avons besoin de plumes pour nos vêtements. Chassez les trotteurs des plaines du voisinage et faites vos preuves en réapprovisionnant le village.", progress = "Fournir de la viande et des plumes à la tribu est un premier pas pour convaincre le Chef de vos talents de chasseur.", completion = "Les taurens de Narache vous remercient, &lt;nom&gt;. Vous avez un avenir prometteur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de nomadeGants en anneaux peints\n\nVous recevrez également :\n\n"},
[748] = {title = "Eau empoisonnée", objective = "Apporter 6 Pattes de loup des prairies et 4 Serres de trotteur des plaines à Mull Thunderhorn à Bloodhoof.", description = "Des gobelins et leurs serviteurs ont pollué nos puits sacrés ! Nous ne pouvons tolérer cela.\n\nPour assainir les puits, je dois créer un totem de purification que vous devrez porter au puits, afin de pratiquer le rituel de purification.\n\nD'abord nous allons fabriquer le totem de purification pour le puits Winterhoof. Pour ce faire, le pays doit offrir son aide. Chassez des loups des prairies pour leurs pattes et des trotteurs des plaines adultes pour leurs serres. Vous les trouverez au sud-ouest.\n\nRevenez avec les pattes et les serres, <nom>.", progress = "Avez-vous les pattes et les serres, <nom> ?", completion = "Beau travail, &lt;nom&gt;. Je vais les utiliser pour confectionner le Totem de purification.", rewards = "Vous recevrez :\n\n"},
[749] = {title = "La Caravane dévastée", objective = "Examiner le contenu d'une caisse de provisions à la caravane dévastée, pour Morin Cloudstalker.", description = "Il y a quelques jours, nous avons intercepté une caravane de la KapitalRisk qui se déplaçait sous escorte sur les rives du lac Taureau-de-pierre. Nous avions déjà perdu deux des nôtres dans une bataille antérieure ; aussi avons-nous attaqué sans hésiter. La caravane fut dévastée.\n\nNous avons laissé leurs caisses de provisions sur place, pensant que nos torches détruiraient toute chose de valeur. Mais comme des sauveteurs de la KapitalRisk ont été repérés à côté des caisses brûlées, il se peut que nous nous soyons trompés.\n\nPeut-être pourriez-vous aller sur place et examiner le contenu de ces caisses.", progress = nil, completion = "Toutes les faces de la caisse sont flanquées du blason de la Division minière de la KapitalRisk. D'après une estampille imprimée sur l'une des faces, le contenu des caisses était déstiné à l'une de leurs fabriques centrales.", rewards = "Vous recevrez :\n\n"},
[750] = {title = "La chasse continue", objective = "Grull Hawkwind, à Camp Narache, voudrait que vous lui apportiez 10 Peaux de puma des montagnes.", description = "Un tauren compétent dans l'art de la chasse sait que ses proies ne sont pas de simples trophées. Les animaux des plaines nous fournissent ce dont nous avons besoin pour survivre. Vous ferez grosse impression sur les plus âgés si vous réussissez à revenir avec quelques-unes de ces précieuses Peaux de puma des montagnes. Vous pourrez trouver ces bêtes dans les collines plus au sud.\n\nNos enfants ont besoin de vêtements et nos tentes d'être raccommodées.", progress = "Si vous pouvez fournir les peaux à la tribu, je ferai connaître à mon père, le Chef Hawkwind, l'abnégation et le concours que vous nous avez portés.", completion = "Les taurens de Narache vous remercient pour toutes ces provisions, &lt;nom&gt;. Vos compétences pour la chasse sont exceptionnelles et vous vaudront la célébrité, un jour, à Thunder Bluff.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards de nomadeCeinture en anneaux peints\n\nVous recevrez également :\n\n"},
[751] = {title = "La Caravane dévastée", objective = "Rapporter les Documents de la KapitalRisk à Morin Cloudstalker, à côté du village Bloodhoof.", description = "L'ouverture de la caisse révèle un assortiment de minerais divers, soigneusement empaquetés. Ceci est une preuve supplémentaire de l'activité minière de la KapitalRisk dans Mulgore. Sur les minerais, vous récupérez des rouleaux de papier, étroitement ficelés.\n\nLa-haut, dans les collines, vous pouvez presque entendre les bruits des outils de forage qui fendent les roches et voir la fumée des gigantesques feux d'alimentation.", progress = "Salut, <nom>. Avez-vous appris quelque chose de nouveau sur les plans et opérations de la KapitalRisk dans notre patrie ?\n\nS'ils pensent pouvoir exploiter la terre, ici, comme ils l'ont fait ailleurs… les estafettes y mettront rapidement un terme.", completion = "Il semble que la KapitalRisk essaie de nous dépouiller de nos ressources naturelles. Sachant cela, nous n'avons pas le droit de les laisser faire.", rewards = "Vous recevrez :\n\n"},
[752] = {title = "Une humble contribution", objective = "Partir chercher la mère du Chef Hawkwind, près du puits, au sud-est de Camp Narache.", description = "Tous les membres de la tribu prennent part à l'harmonie naturelle de la vie. Nous vivons et travaillons tous ensemble.\n\nNotre engagement les uns pour les autres implique une grande responsabilité envers autrui. Je voudrais vous demander une humble contribution.\n\nMa mère est partie ce matin pour tirer et rapporter de l'eau d'un puits qui est au sud-est de Narache. Le temps passe et elle n'est toujours pas rentrée. Peut-être pourriez-vous aller à sa rencontre ? Je suis, hélas, retenu ici par les affaires de la tribu.", progress = nil, completion = "Vous venez de si loin, juste pour aider une vieille dame ? Eh, ne seriez-vous pas un gardien ?", rewards = "Vous recevrez :\n\n"},
[753] = {title = "Une humble contribution", objective = "Prendre une Cruche d'eau du puits.\n\nApporter la cruche au Chef Hawkwind, à Camp Narache, au nord-ouest du puits.", description = "J'en ai vu et parcouru du pays, dans ma vie. Ces jambes fatiguées n'ont plus la vigueur d'antan, mais je peux encore servir la tribu... en prenant le temps qu'il faut.\n\nVous avez l'air d'un de ces <classe>s enthousiastes. Voici de quoi tester votre jeunesse et votre vitalité : prenez une cruche d'eau et apportez-la à mon fils, le Chef, à Camp Narache.\n\nRappelez-vous que même la tâche la plus humble peut parfois vous attirer la reconnaissance des aînés.", progress = "Vous avez l'air de revenir des plaines. Avez-vous des nouvelles de Grand-mère Hawkwind ?", completion = "Vous avez rapporté cette cruche, comme vous l'avait demandé Grand-mère.\n\nVotre motivation à aider les autres et à servir les taurens de Camp Narache m'incite à penser que vous allez faire bientôt la fierté de la tribu, à Thunder Bluff.", rewards = "Vous recevrez :\n\n"},
[754] = {title = "Purification de Winterhoof", objective = "Utiliser le Totem de purification de Winterhoof au puits Winterhoof, puis retourner voir Mull Thunderhorn.", description = "J'ai réalisé le totem pour purifier le puits Winterhoof. Il vous faut maintenant l'apporter au puits et y pratiquer le Rituel de purification. Vous trouverez le puits dans le sud-est, gardé par d'infects gobelins !\n\nCe sera tout sauf une mission facile mais vous devez réussir, si nous voulons un jour pouvoir boire de nouveau l'eau précieuse de ce puits.\n\nBonne chance à vous, <nom>.", progress = nil, completion = "Les rumeurs de vos exploits vous précède. Déjà, les animaux des environs du puits s'y désaltèrent de nouveau.\n\nVotre contribution pour le pays a été énorme, &lt;nom&gt;. Vous avez grandement aidé le peuple &lt;race&gt;.", rewards = "Vous recevrez :\n\n"},
[755] = {title = "Les Rites de la Terre-mère", objective = "Aller voir le Prophète Graytongue qui vit dans les collines au sud de Camp Narache.", description = "La volonté dont vous avez fait preuve en acceptant cet humble travail pour les taurens de Narache, ainsi que votre goût pour l'apprentissage révèlent la noblesse de votre caractère, <nom>. Je suis sûr qu'un jour vous serez <connu/connue> à Thunder Bluff comme l'un des <classe>s les plus valeureux.\n\nAvant cela, vous serez mis à l'épreuve des trois Rites de la Terre-mère.\n\nLa première épreuve est le Rite de force. Allez voir le Prophète Graytongue et dites-lui que le Chef Hawkwind vous envoie.\n\nVous trouverez la demeure du Prophète directement au sud de Camp Narache.", progress = nil, completion = "C'est le Chef Hawkwind qui vous envoie ? Passer l'épreuve des Rites de la Terre-mère n'est pas une partie de plaisir, croyez-moi...", rewards = "Vous allez être la cible du sort suivant :\n\nMarque du fauve\n\nVous recevrez :\n\n"},
[756] = {title = "Le Totem de Thunderhorn", objective = "Rapporter 6 Griffes de Traqueur et 6 Griffes de puma à Mull Thunderhorn.", description = "Pour créer le Totem de purification de Thunderhorn, vous devez collecter les griffes des prédateurs qui hantent les plaines de Mugore. Chassez les traqueurs des prairies et les pumas des basses plaines pour leurs griffes, puis revenez me voir.\n\nVous trouverez les traqueurs des prairies et les pumas des basses plaines à l'est et à l'ouest.", progress = "<nom>, avez-vous les griffes que je vous avais demandées ? Chaque heure qui passe voit gagner l'infection du puits Thunderhorn !", completion = "Merci, &lt;nom&gt;. La pureté d'intention avec laquelle ces animaux chassent est essentielle pour la création du prochain totem de Purification.\n\nLes gobelins n'apprendront jamais la différence qu'il y a entre dévaster une terre et y vivre harmonieusement.", rewards = "Vous recevrez :\n\n"},
[757] = {title = "Le Rite de force", objective = "Tuer des Dos-hirsute dans le Ravin de Roncelame et apporter 12 Ceintures de Dos-hirsute au chef Hawkwind au camp Narache.", description = "Les rites de la Terre-mère sont un passage obligé pour tout jeune tauren qui se respecte, à Thunder Bluff.\n\nLa première épreuve est le rite de Force. Vous devrez y démontrer votre bravoure en tuant des ennemis de la tribu.\n\nLes Dos-hirsute du ravin de Roncelame à l'est, empiètent sur nos terres tribales. Ils nous tendent des embuscades lors de nos parties de chasse et volent dans les villages, à la nuit tombée.\n\nProuvez votre valeur en massacrant ces vauriens et retournez voir le Chef, à Camp Narache, avec leurs ceintures pour prouver que vous les avez tués.", progress = "Avez-vous achevé le rite de Force, <nom> ? Je demande à voir la preuve de votre action contre les ennemis de notre tribu, les Dos-hirsute.", completion = "Vous avez réussi la première des épreuves des Rites de la Terre-mère. La tribu sera fière de vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMasse de pierreTomahawkCouteau tailladantCanne de doyenHache du brave\n\nVous recevrez également :\n\n"},
[758] = {title = "Purification de Thunderhorn", objective = "Utilisez le Totem de purification de Thunderhorn au puits Thunderhorn, puis retournez voir Mull.", description = "Le totem est prêt, <nom>. Il vous faut encore pratiquer le Rituel de purification.\n\nAllez au puits Thunderhorn, au nord du village et utilisez le Totem de purification de Thunderhorn pour le rituel. Revenez me voir quand cela sera fait.\n\nQue les esprits soient avec vous.", progress = nil, completion = "Les ancêtres du clan Thunderhorn me sont apparus en rêve ; ils ont loué ce que vous avez fait près de leur puits.\n\nEn guise de remerciement, ils souhaitent vous donner ceci...", rewards = "Vous recevrez :\n\nCape de Thunderhorn"},
[759] = {title = "Le Totem de Wildmane", objective = "Apporter 8 Dents de loup alpha des prairies à Mull Thunderhorn, au village Bloodhoof.", description = "Il ne reste qu'un puits à purifier, appelé puits Wildmane, d'après le clan du même nom. Pour nettoyer ce puits, nous aurons besoin des dents d'un redoutable prédateur : le loup alpha des prairies. Allez chasser ces loups au nord, puis revenez me voir lorsque vous en aurez fini.\n\nLes alphas rôdent souvent autour de notre majestueuse cité de Thunder Bluff.", progress = "<nom>. Avez-vous les dents dont j'ai besoin ?", completion = "Très bien, &lt;nom&gt;. La nature nous a gratifiés d'une importante offrande ; je peux sentir le poids de son sacrifice et mon coeur en est comme gonflé de mélancolie et de fierté.", rewards = "Vous recevrez :\n\n"},
[760] = {title = "Purification de Wildmane", objective = "Utiliser le Totem de purification de Wildmane au puits Wildmane, puis retournez voir Mull Thunderhorn.", description = "Votre purification des puits Winterhoof et Thunderhorn est objet de discussion et de fierté parmi les esprits, jeune <nom>. Le totem de Wildmane est construit et le devoir vous appelle, encore une fois.\n\nLe puits Wildmane se trouve au nord de Thunder Bluff. Pratiquez-y le rituel ! Débarrassez le pays du poison des gobelins. Que l'eau claire coule de nouveau !", progress = nil, completion = "Vous avez réussi. Les puits sont purifiés et nos terres, guéries. Le village Bloodhoof vous en est reconnaissant, &lt;nom&gt;.\n\nQue les vents murmurent la geste de vos exploits pendant des siècles et que les eaux de Mulgore restent claires pour toujours.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTomahawk de cérémonieBâton du gardien des rêves\n\nVous recevrez également :\n\n"},
[761] = {title = "Chasse aux Rapaces", objective = "Apporter 8 Trophées de plumes de Rapace à Harken Windtotem, au village Bloodhoof.", description = "Le rapace est un oiseau rusé, difficile à trouver et à chasser, qui plus est. Une collection de plumes de rapace est signe d'intelligence et de détermination pour un chasseur.\n\nSi vous êtes <prêt/prête> à entreprendre ce travail, pénétrez les plaines et chassez les rapaces.\n\nRapportez-moi leurs plumes et faites honneur à votre clan.\n\nVous trouverez les rapaces partout dans Mulgore, mais vos yeux doivent être affûtés pour les localiser et vos jambes, agiles pour les attraper.", progress = "Avez-vous chassé ces Rapaces, <nom> ? Me rapportez-vous leurs plumes ?", completion = "Je sais que collecter ces plumes n'était pas une tâche facile, &lt;nom&gt;. Vous venez de prouver que vous étiez l'un des chamans les plus méritants. Nous sommes heureux, au village Bloodhoof, de vous compter parmi nous.", rewards = "Vous recevrez :\n\n"},
[762] = {title = "Un ambassadeur du mal", objective = "Tuer l'Ambassadeur Infernus, à la Forteresse d'Angor, et apporter la preuve de sa mort au Conseiller Belgrum à Ironforge.", description = "L'Ambassadeur Infernus a été envoyé à la Forteresse d'Angor par Ragnaros lui-même, pour suivre les recherches des artefacts perdus des Ombreforge à Uldaman.\n\nCela a déjà coûté d'énormes pertes à notre peuple et la situation empire encore. Je n'ose imaginer combien d'artefacts ils pourraient rassembler et utiliser contre Ironforge.\n\nNotre objectif est simple, <classe>. Retournez dans les Terres ingrates et tuez l'Ambassadeur Infernus. Une fois la menace éliminée, revenez voir le Conseiller Belgrum, avec les preuves de votre victoire.\n\nTout est entre vos mains, à présent.", progress = "Faire vite est essentiel, <nom>. Ragnaros n'attendra pas que nous soyons prêts.", completion = "&lt;nom&gt;, votre dévouement à Ironforge et au peuple nain ne peut être remis en question. Je vous remercie de votre aide.\n\nJe dois faire dire à l'Historien Karnik que vous avez réussi et aussi faire parvenir de l'aide dans les Terres ingrates, dès que possible, afin de récupérer le site d'excavation. Merci encore\n\nAvant que vous ne partiez, il y a encore une chose que je vous demanderai de faire au nom du roi Magni.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEpée du capitaine nain"},
[763] = {title = "Les Rites de la Terre-mère", objective = "Apporter le Totem de Hawkwind à Baine Bloodhoof au village Bloodhoof. Suivre la route hors du camp Narache.", description = "Il vous faut encore subir deux épreuves pour achever les Rites de la Terre-mère. Il est temps pour vous d'élargir votre expérience, <nom>.\n\nVoyagez jusqu'au Village Bloodhoof et trouvez le Chef, Baine Bloodhoof, fils de Cairne. Là, vous devrez continuer votre périple et gagner l'approbation des aînés de Thunder Bluff.\n\nPortez ce totem à Baine ; il reconnaîtra mes gravures et vous aidera dans votre quête.\n\nSuivez la route hors de Camp Narache et hâtez vous. Ne vagabondez pas de-ci de-là, vous vous perdriez.", progress = "Quels vents vous poussent jusqu'à moi, <classe> ?", completion = "Enfin, des nouvelles de mon bon ami, le Chef Hawkwind ! Ah, je vois que vous êtes quelqu'un de spécial...", rewards = "Vous recevrez :\n\n"},
[764] = {title = "La KapitalRisk", objective = "Tuer 14 Travailleurs de la KapitalRisk et 6 Superviseurs de la KapitalRisk pour Morin Cloudstalker du village Bloodhoof.", description = "Ceci explique l'accroissement des effectifs et des équipements de la KapitalRisk à Mulgore. Ces gobelins... leur nombre augmente bien trop vite. Comme on dit : quand on montre quelque chose à un gobelin, les bruits de la monnaie et du profit ne tardent pas à retentir.\n\nLes avides petites créatures... malheureusement pour eux, nous, les taurens, ne permettrons pas à leur entreprise de se développer sur nos terres. Allez à leur mine, au nord de la caravane dévastée, et portez leur un message.", progress = nil, completion = "Je ne pense pas qu'on puisse mal interpréter ou ignorer ce signal, hum ? La KapitalRisk va comprendre qu'on ne prend pas les taurens à la légère. Quelle formidable arrogance a pu leur faire croire qu'ils allaient ainsi piller nos ressources naturelles sans que nous ne réagissions ?", rewards = "Vous recevrez :\n\n"},
[765] = {title = "Superviseur Fizsprocket", objective = "Tuer le Superviseur Fizsprocket et rapporter son Ecritoire à Morin Cloudstalker, au village Bloodhoof.", description = "A en croire les documents que vous avez sauvés de la Caravane, la KapitalRisk a conçu plusieurs projets pour nous chasser de nos terres afin de pouvoir les piller et les exploiter en toute liberté.\n\nJe suis épouvanté de voir à quelles extrémités ces odieuses créatures sont prêtes à en venir pour accomplir leurs desseins. Le cerveau qui est à l'origine de leurs plans doit être tué. Son nom est Superviseur Fizsprocket et vous le trouverez à la mine de la KapitalRisk, à l'est de la Caravane dévastée. Rapportez-moi son écritoire ; peut-être nous apprendra-t-il quelque chose.", progress = "Je bous de fureur en imaginant quelles atrocités la KapitalRisk est prête à commettre contre nous, au seul nom du profit.", completion = "Ma colère est presque apaisée de savoir que l'infâme Fizsprocket est mort. Je vais fouiller ses effets personnels pour voir si je peux apprendre quelque chose sur les projets de la KapitalRisk. Merci de votre aide, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCouteau de combat compactEcraseur gobelin\n\nVous recevrez également :\n\n"},
[766] = {title = "Mazzranache", objective = "Apporter un Coeur de loup des plaines, un Fémur de puma des basses plaines, une Ecaille de trotteur des plaines et un Gésier de rapace à Maur Raincaller, au village Bloodhoof.", description = "Mon grand-père m'a conté sa bataille avec la créature nommée Mazzranache. Il m'a parlé de ses yeux rouges, démoniaques, de ses serres aiguisées comme des rasoirs et de sa morsure venimeuse.\n\nJ'ai eu la malchance de rencontrer la bête tandis que je cheminais à travers les plaines. Elle était exactement comme mon grand-père me l'avait décrite ; elle m'a attaqué et m'a profondément mordu à l'épaule. Son poison coule à présent dans mes veines et j'aurais besoin d'ingrédients rares pour réaliser un antidote : un coeur de loup, un fémur de puma, une écaille de trotteur des plaines et un gésier de rapace.\n\nHâtez-vous, le temps m'est compté.", progress = "La fièvre me consume et je sens mon esprit sombrer dans d'abominables cauchemars... j'aurais dû savoir que je ne pourrais pas résister à la créature qui avait vaincu mon grand-père.\n\nAvez-vous les ingrédients que je vous avais demandé de collecter pour le remède ? Si je tarde encore à nettoyer mon sang de cette infection, je mourrai bientôt.", completion = "Ah, mille mercis, &lt;nom&gt;. Avec les ingrédients que vous venez de m'apporter, je vais pouvoir réaliser l'antidote qui débarrassera mon corps du venin et me guérira. Je vous dois la vie.\n\nJe n'oublierai jamais le hurlement strident que poussa Mazzranache en fondant sur moi, ni sa couleur de feu tandis que son bec frappait...\n\nSoyez vigilant en marchant sur les chemins.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes du grimpeur des collinesGarde-poignets de chasseur des plaines\n\nVous recevrez également :\n\n"},
[767] = {title = "Le Rite de vision", objective = "Parler à Zarlman Deux-Lunes, au village Bloodhoof.", description = "Réussir le Rite de vision, un des rites de la Terre-mère, vous attirera le respect des aînés de Thunder Bluff.\n\nNotre peuple a compris que la terre était pourvoyeuse de ressources. Pour faire l'expérience de la vision rituelle, vous devez parler au chef spirituel du village, Zarlman Deux-Lunes.", progress = nil, completion = "J'ai pressenti que vous viendriez à moi, &lt;classe&gt;. Je reconnais toujours un candidat aux Rites de la Terre-mère.", rewards = "Vous recevrez :\n\n"},
[768] = {title = "La chasse aux peaux", objective = "Apporter 12 pièces de Cuir léger à Veren Tallstrider, à Thunder Bluff.", description = "Salut, <mon/ma> jeune <ami/amie> ! Votre oeil brille d'une flamme farouche et je vois que vous avez hâte de retourner dans les plaines pour chasser. Puissiez-vous faire l'honneur de votre clan !\n\nJe travaille les peaux de bêtes ; j'en fais des vêtements et des armures pour les gens de Thunder Bluff.\n\nSi vous alliez chassez des bêtes et m'en rapportiez les peaux, je pourrais vous confectionner quelque chose.", progress = "Ah, vous voici. La chasse fut-elle bonne ? Avez-vous les peaux ?", completion = "Ah, ces pièces sont parfaites. Elles feront de beaux articles de cuir.\n\nVoici, &lt;nom&gt;, prenez cela en guise de récompense...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture en peau d'animalGants rembourrés\n\nVous recevrez également :\n\n"},
[769] = {title = "Sac en peau de kodo", objective = "Apporter 4 pièces de Cuir léger et 4 Bobines de fil grossier à Veren Tallstrider, à Thunder Bluff.", description = "Les kodos de Mulgore sont puissants et robustes, qualités que nous respectons beaucoup. Si vous savez travailler le cuir et souhaitez apprendre à confectionner un sac en peau de kodo, apportez-moi les fournitures nécessaires.\n\nFaites cela et je partagerai mes connaissances avec vous.", progress = "Avez-vous mes fournitures, <nom> ?", completion = "Ah, merci, &lt;nom&gt;. Mon coeur est gonflé d'orgueil de voir qu'il existe encore des jeunes pour s'intéresser au travail du cuir.", rewards = "Vous recevrez :\n\nPatron : Sac en peau de kodo"},
[770] = {title = "La Cape de démon balafrée", objective = "Trouver quelqu'un qui puisse vous en apprendre davantage au sujet du Hurleur fantomatique.\n\nObjet fourni : \n", description = "Cette peau déchiquetée de Hurleur fantomatique porte toujours la terrible blessure reçue lors de la bataille des loups contre la Légion ardente.\n\nPeut-être quelqu'un au village Bloodhoof sait-il quelque chose au sujet de la malédiction du Hurleur fantomatique...", progress = nil, completion = "Je ne peux pas en croire mes yeux ! Vous avez vaincu le terrible Hurleur fantomatique ? Je vous considère avec un respect tout neuf, jeune &lt;classe&gt;. Vous êtes un chasseur extrêmement doué !\n\nLaissez-moi vous offrir quelque chose. Je ne chasse plus, mais je serais honoré si vous acceptiez l'une de mes armes, pour vos chasses.\n\nPuisse-t-elle guider votre bras et vous attirer le renom que vous méritez.\n\nEspérons aussi que ce Hurleur fantomatique a finalement trouvé la paix.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau de SkornCarabine de Skorn\n\nVous recevrez également :\n\n"},
[771] = {title = "Le Rite de vision", objective = "Collecter 2 Pierres de puits et 2 Pommes de pin et les rapporter à Zarlman Deux-Lunes, au village Bloodhoof.", description = "Pour passer le Rite de vision, vous devez collecter les ingrédients nécessaires à la réalisation de l'Eau des Prophètes.\n\nJ'aurai besoin de Pierres de puits, qui se trouvent autour des puits, à Mulgore. Je les combinerai aux pommes de pin, qui tombent des arbres majestueux de notre pays.\n\nCes ingrédients sont porteurs de grands principes magiques ; quand vous en consommerez les décoctions devant le feu tribal, leurs essences vous donneront une vision. Suivez-la et vous accéderez à l'étape suivante de votre quête sacrée.", progress = "Une fois que vous aurez collecté suffisamment de Pierres de puits, autour des puits, et de Pommes de pin, au pied des arbres, je ferai l'Eau des Prophètes pour vous.", completion = "Je vois que vous avez appris à tirer parti de notre terre sacrée, &lt;nom&gt;. Faire l'Eau des Prophètes ne me prendra qu'un moment.", rewards = "Vous recevrez :\n\n"},
[772] = {title = "Le Rite de vision", objective = "Consommer l'Eau des Prophètes devant le feu tribal, au village Bloodhoof et suivre la vision quand elle apparaîtra.\n\nObjet fourni : \n", description = "Vous allez maintenant être <confronté/confrontée> à l'Eau des Prophètes.\n\nQuand vous vous sentirez <prêt/prête>, consommez-la en face du feu tribal. Une fois bue l'eau sacrée, la vision se matérialisera rapidement devant le feu.\n\nA ce moment-là, vous serez <seul/seule> avec votre destin...", progress = nil, completion = "Ne soyez pas effrayé, &lt;nom&gt;. Vous avez réussi le passage du Rite de vision.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de pluieCape délavée\n\nVous allez être la cible du sort suivant :\n\nMarque du fauve\n\nVous recevrez également :\n\n"},
[773] = {title = "Le Rite de sagesse", objective = "Voyager aux Rochers rouges, à l'est de Thunder Bluff et parler à Esprit ancestral.", description = "Pour gagner l'approbation des aînés de Thunder Bluff, vous devez désormais réussir le Rite de sagesse.\n\nMaintenant que vous avez achevé le Rite de vision, les esprits ancestraux des Rochers rouges vous donneront la bénédiction des ancêtres. Seuls ceux qui ont bu l'Eau des Prophètes accèdent à cette bénediction.\n\nVoyagez à l'est de Thunder Bluff, jusqu'aux Rochers rouges et cherchez l'Esprit ancestral, <nom>.", progress = nil, completion = "Vous avez fait preuve de beaucoup d'assiduité et de courage dans votre passage des Rites de la Terre-mère, &lt;nom&gt;.\n\nNous, les Esprits ancestraux, sommes les taurens qui donnèrent leur vie en fondant et en défendant notre majestueuse ville de Thunder Bluff. Je vous transmets, à présent, ce devoir de protection.\n\nVous avez réussi le Rite de sagesse, jeune &lt;classe&gt;. Entrez dans Thunder Bluff avec gloire.", rewards = "Vous recevrez :\n\n"},
[775] = {title = "Voyage à Thunder Bluff", objective = "Parler à Cairne Bloodhoof à Thunder Bluff.", description = "Vous allez maintenant être <révéré/révérée> dans notre grande ville. Chaque <race> qui passe avec succès les Rites de la Terre-mère a droit à cet honneur.\n\nPour votre quête finale, trouvez notre noble chef, Cairne Bloodhoof, qui demeure au sommet de la plus haute mesa de Thunder Bluff.", progress = nil, completion = "Salut, jeune &lt;classe&gt;. Je vois que vous avez trouvé le chemin jusqu'au seuil de ma porte.", rewards = "Vous recevrez :\n\n"},
[776] = {title = "Les Rites de la Terre-mère", objective = "Apporter la Corne d'Arra'chea à Cairne Bloodhoof, à Thunder Bluff", description = "Vous avez passé les rites de la Terre-mère et avez désormais votre place parmi nous, à Thunder Bluff.\n\nMais pour maintenir un prestige si durement gagné, vous devez continuer à prouver votre valeur auprès de votre peuple.\n\nNous sommes des chasseurs, <nom>. Plus bas, à Mulgore, vit une formidable bête kodo nommée Arra'chea. Prouvez votre habileté à la chasse ; traquez la bête et rapportez-moi la Corne d'Arra'chea.", progress = "Avez-vous battu Arra'chea ?", completion = "Bravo, quelle estocade magistrale !\n\nJe vais envoyer un groupe pour dépecer et hisser la carcasse du monstre afin de profiter de la peau et de la viande.\n\nCe que vous avez fait pour votre peuple est grand, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nJambières du chasseur de kodo"},
[777] = {title = "Grandes difficultés", objective = "Apporter le Rouage N°5 à Lotwil Veriatus.", description = "Bon.\n\nJe serai là-bas... à l'abri.\n\nRejoignez-moi, si vous le souhaitez.", progress = "<Sans lever les yeux des ses Entraves, Lotwil tend une main et remue les doigts, impatiemment.>\n\nLe rouage, <nom>, le rouage !", completion = "Ah, parfait. Restez en arrière... voyez-vous, je change le cours de l'Histoire, ce n'est pas rien !\n\n&lt;Lotwil continue de travailler fiévreusement.&gt;", rewards = nil},
[778] = {title = "Ça promet d'être dur", objective = "Vaincre le Gardien Fam'retor et rapporter les entraves des élémentaires de Lotwil à Lotwil Veriatus.", description = "Haha ! c'est fait ! Les entraves sont finies !\n\nIl est temps, Lucien. Il est temps, Servo !\n\nÊtes-vous <prêt/prête> à assister à la fusion parfaite de la science alchimique et des arcanes, <nom> ?\n\nJe vais maintenant invoquer un puissant élémentaire. C'est un grand jour pour nous !", progress = "Ce n'est pas exactement l'issue à laquelle je m'attendais. Avez-vous pu récupérer mes Entraves ?", completion = "Merci, &lt;nom&gt;. C'était une dure épreuve, n'est-ce pas ?\n\nJe ne sais pas ce qui a mal tourné. Heureusement, ma magie a pu renvoyer la créature dans son plan d'origine.\n\nVoici un petit cadeau de remerciement pour votre généreuse contribution.", rewards = "Vous recevrez :\n\nChouette chronomètre"},
[779] = {title = "Sceau de la Terre", objective = "Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d'améthyste, la Pierre runique d'opale et la Pierre runique de diamant.", description = nil, progress = "Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d'améthyste, la Pierre runique d'opale et la Pierre runique de diamant.", completion = "Vous placez les Pierres runiques dans leur alcôves respectives et soudain un violent grondement fait trembler la terre tandis que le Sceau se brise.", rewards = nil},
[780] = {title = "Les sangliers de guerre apprivoisés", objective = "Grull Hawkwind, à Camp Narache, voudrait que vous tuiez des sangliers de guerre, et que vous rapportiez 8 Groins de sanglier de guerre et 8 Flancs de sanglier de guerre.", description = "Les sangliers de guerre apprivoisés du ravin de Roncelame se répandent sur nos terrains de chasse. Ils sont entraînés au combat et rendus agressifs par les hurans Dos-hirsute contre lesquels nous sommes en guerre.\n\nPartez ; massacrez ces infâmes créatures et revenez avec leurs groins et leurs flancs, que nous puissions en faire un bon ragoût pour les jeunes.", progress = "La fréquence des attaques des sangliers de guerre apprivoisés augmente. Leur avez-vous délivré un message assez clair et avez-vous tranché et rapporté quelques-uns de leurs groins et flancs ?", completion = "Parfait. Ces ingrédients feront un ragoût bien épicé. Espérons que la perte de ces sangliers donnera une bonne leçon à ces vils Dos-hirsute.", rewards = "Vous recevrez :\n\nGilet de nomadeMorceau de pain rassis"},
[781] = {title = "L'attaque du Camp Narache", objective = "Apporter les Plans d'attaque Dos-hirsute au chef Hawkwind, au camp Narache.", description = "Après une analyse attentive de la carte, vous comprenez que vous avez découvert les plans du chef de guerre Dos-hirsute pour assiéger le camp Narache.\n\nLe chef Hawkwind pourrait certainement tirer profit de ces informations !", progress = "Vous avez l'air inquiet, <nom>. Quelles nouvelles nous apportez-vous ?", completion = "C'est en effet bien inquiétant ! Mais grâce à cette information, nous pouvons appeler à l'aide nos frères du village Bloodhoof et contrecarrer ce projet d'attaque. Vous venez de sauver la vie de nombreux taurens, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nTarge en écorce épaisse"},
[782] = {title = "Alliances rompues", objective = "Tuer Boss Tho'grun et rapporter le Signe de la Terre à Gorn, à Kargath.", description = "Durant l'alliance de la Deuxième guerre entre la Horde et le dragon Aile de mort, nous avons appris que deux de ses lieutenants, Cinglenoir et Hematus, ont été emprisonnés dans le ravin de Lethlor, loin à l'est. Nous devons réduire au silence nos anciens alliés pervertis afin de restaurer l'honneur de la Horde !\n\nNous avons engagé Tho'grun et sa bande de mercenaires ogres pour obtenir le Signe de la Terre, une clé nécessaire à l'ouverture de la prison des drakes. Mais Tho'grun nous a trahis, nous a submergés et s'en est emparé. Allez au Camp Boff et récupérez-le !", progress = "La trahison de Tho'grun… Peut-on encore se demander pourquoi il n'y a plus d'ogres dans la Horde ? Je serai heureux de le voir mort, et de savoir le Signe de la Terre restitué.\n\nSi vous ne l'avez pas encore tué, alors ne perdez pas de temps et hâtez-vous vers le Camp Boff. Il se trouve au sud-est de Kargaht.", completion = "À présent que Tho'grun est mort, que son corps est désagrégé par les vents du désert et par les charognards, la confusion va régner parmi les ogres. Bien qu'il s'agisse d'une petite victoire, elle mènera à une autre bien plus importante.\n\nLe Signe de la Terre est maintenant en notre possession, et nous pouvons déverrouiller la prison des drakes noirs à Lethlor. Nous les délivrerons de leur éternel emprisonnement, bien que ce soit pour les mener à leur perte !", rewards = "Vous recevrez :\n\n"},
[783] = {title = "Menace intérieure", objective = "Parler au maréchal McBride.", description = "J'espère que vous avez le coeur bien accroché, jeune <classe>, car il y a du travail à faire à Northshire.\n\nEt ce n'est pas du travail de ferme.\n\nLes gardes de Stormwind ont beaucoup à faire afin de maintenir la paix en ces lieux, tandis que nombre d'entre nous sont en des terres lointaines et que tellement de dangers nous menacent. Aussi acceptons-nous l'aide de tous ceux qui souhaitent défendre leur demeure. Et leur alliance également.\n\nSi votre volonté est de répondre à cet appel, allez parler à mon supérieur, le maréchal McBride. Il se trouve dans l'abbaye qui est derrière moi.", progress = nil, completion = "Ah, parfait, un autre volontaire. Il y en beaucoup qui se présentent comme vous, en ce moment.\n\nJ'espère que nous serons assez nombreux.\n\nLes terres humaines sont menacées de l'extérieur et nos principales forces sont rassemblées loin d'ici. En conséquence, des bandes de hors-la-loi corrompus prospèrent maintenant dans le pays.\n\nNous aurons à combattre sur tous les fronts, &lt;nom&gt;. Préparez vous à une longue campagne.", rewards = "Vous recevrez :\n\n"},
[784] = {title = "Vaincre les traîtres", objective = "Tuer 10 Marins de Kul Tiras, 8 Soldats de marine de Kul Tiras et le Lieutenant Benedict, puis retourner voir Gar'Thok à Tranchecolline.", description = "Guidés par l'amiral Proudmoore, les humains de Kul Tiras prirent pied en Durotar, en violation du pacte signé des années auparavant entre le Chef de guerre et Jaina Proudmoore pour vaincre Archimonde.\n\nL'attaque humaine fut repoussée et le donjon de Tiragarde tomba. Mais, récemment, les troupes de réserves de l'amiral, menées par le lieutenant Benedict, ont repris le donjon et menacent nos terres, une fois de plus. Ces humains ne montrent décidément aucun respect pour la diplomatie.\n\nDémontrez votre bravoure et voyagez vers le sud, jusqu'au donjon de Tiragarde, pour éliminer ses envahisseurs humains.", progress = nil, completion = "J'ai déjà eu vent de votre bravoure, &lt;classe&gt;. La geste de votre victoire, au donjon de Tiragarde, sera chantée longtemps à Orgrimmar.", rewards = "Vous recevrez :\n\n"},
[785] = {title = "Alliance stratégique", objective = "Chercher Lar Prowltusk sur le flanc ouest du village de Sen'jin.Thrall est un chef noble et sage dont la ténacité sur le champ de bataille n'a d'égale que son habileté pour la diplomatie.\n\nLes trolls Darkspear ont prouvé qu'ils étaient d'inestimables alliés pour les orcs. Liés par la loyauté et l'honneur, nous avons signé un pacte de protection avec eux.\n\nLe Chef de guerre a donné des ordres pour s'assurer que nos amis Darkspear du village de Sen'jin ne soient pas sous le joug d'une menace directe. L'un de leurs éclaireurs les plus sûrs, Lar Prowltusk, surveille de près leur flanc ouest.\n\nCherchez Lar et assistez-le dans sa tâche.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Thrall est un chef noble et sage dont la ténacité sur le champ de bataille n'a d'égale que son habileté pour la diplomatie.\n\nLes trolls Darkspear ont prouvé qu'ils étaient d'inestimables alliés pour les orcs. Liés par la loyauté et l'honneur, nous avons signé un pacte de protection avec eux.\n\nLe Chef de guerre a donné des ordres pour s'assurer que nos amis Darkspear du village de Sen'jin ne soient pas sous le joug d'une menace directe. L'un de leurs éclaireurs les plus sûrs, Lar Prowltusk, surveille de près leur flanc ouest.\n\nCherchez Lar et assistez-le dans sa tâche.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[786] = {title = "Déjouer l'agression des Kolkar", objective = "Détruire 3 Jeux de Plans d'attaque dans la combe des Kolkar, pour Lar Prowltusk à l'extérieur du village de Sen'jin.", description = "Parlez plus doucement, <classe>. Les centaures kolkar sont juste derrière la crête, à l'ouest, dans la combe des Kolkar.\n\nLa nuit dernière, alors qu'ils étaient en manœuvres, je me suis glissé dans leur village et j'ai découvert que ces tristes créatures envisageaient une attaque massive contre les trolls et les orcs de Durotar.\n\nNous ne pouvons leur permettre de mener leurs desseins à terme. Peut-être avez-vous les capacités requises pour vous infiltrer dans la combe des Kolkar et y détruire leurs plans d'attaque ?\n\nAux dernières nouvelles, ces plans ont été répartis entre trois de leurs chefs.", progress = "Les centaures représentent une menace constante pour la Horde. Leurs vues sur notre patrie ne peuvent être tolérées plus longtemps.", completion = "La Horde l'emporterait sûrement si les centaures Kolkar attaquaient maintenant. Toutefois, en prévenant cette agression nous évitons d'envoyer nos grands guerriers à un massacre inutile.\n\nAussi vrai qu'il y a du sable dans le désert de Tanaris, le sang sera encore versé avant que ces temps difficiles ne soient révolus.\n\nVous avez dignement servi votre peuple, &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de combattant aguerriBrassards de corde épaisse\n\nVous recevrez également :\n\n"},
[787] = {title = "La nouvelle Horde", objective = "Faites un rapport à Gornek, dans l'AntreThrom'ka, <classe>. Je suis Eitrigg, chargé par Thrall de superviser l'entraînement des recrues.\n\nLa Horde n'est plus ce qu'elle était. Jadis, je la quittai, écoeuré par l'influence toujours croissante des sbires avides de la Légion ardente. Durant mon exil, je fus pris par un groupe d'humains, mais secouru ensuite par le Chef de guerre. Lorsqu'il me fit part de sa vision de la Horde, libre de toute influence démoniaque et guidée par les chamans, je réintégrai ses rangs.\n\nGornek aura d'autres instructions pour vous.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Throm'ka, <classe>. Je suis Eitrigg, chargé par Thrall de superviser l'entraînement des recrues.\n\nLa Horde n'est plus ce qu'elle était. Jadis, je la quittai, écoeuré par l'influence toujours croissante des sbires avides de la Légion ardente. Durant mon exil, je fus pris par un groupe d'humains, mais secouru ensuite par le Chef de guerre. Lorsqu'il me fit part de sa vision de la Horde, libre de toute influence démoniaque et guidée par les chamans, je réintégrai ses rangs.\n\nGornek aura d'autres instructions pour vous.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[788] = {title = "La dent tranchante", objective = "Tuer 10 Sangliers tachetés, puis retourner voir Gornek, dans l’Antre.", description = "La première chose à faire sera de tremper un peu ce corps trop tendre. Je pourrais vous envoyer dans les Tarides pour y chasser des kodos ; mais en toute honnêteté, vous nous êtes plus utile <vivant que mort/vivante que morte>.\n\nEn revanche, je pense que les sangliers tachetés seront des adversaires à votre hauteur. Vous les trouverez plus au nord.", progress = nil, completion = "Hmmm, pas mal, &lt;nom&gt;. Mais ne vous enflammez pas... vous trouverez des adversaires bien plus coriaces que des sangliers sur votre chemin.\n\nVous avez, cependant, fait montre de courage et pour votre prochaine épreuve vous serez opposé à une créature autrement plus féroce et impitoyable ; vous aurez besoin de protections supplémentaires pour aller la défier.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes souples en laineGants détériorés en cuir\n\nVous recevrez également :\n\n"},
[789] = {title = "L'aiguillon du scorpide", objective = "Apporter 10 Queues de scorpides ouvriers à Gornek, dans l’Antre.", description = "De piètres novices comme de grands guerriers ont succombé au dard venimeux des scorpides. Vous trouverez un grand nombre de ces créatures au nord-ouest. Apportez moi dix de leurs queues comme preuve que vous les avez affrontées.\n\nL'antidote à leur venin est préparé à partir de leur aiguillon. Nous conservons de grandes quantités de ce remède pour sauver de jeunes vies comme la vôtre...\n\nMais vous n'aurez certainement aucun besoin de ce contre-poison, n'est-ce pas ?", progress = "La carapace des scorpides n'est pas assez épaisse pour résister à une lame déterminée. Frappez fort, frappez juste et ils feront une proie facile.", completion = "Il y a une importante leçon à retenir d'un combat contre des scorpides : un adversaire, quel que soit sa taille, peut se révéler meurtrier dans un combat à mort où d'innombrables paramètres entrent en jeu et modifient les rapports de force.\n\nJe n'ai plus rien à vous apprendre, &lt;nom&gt;. Vous avez bravement agi et je considérerai vos progrès avec beaucoup d'intérêt.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture souple en laineCape détériorée\n\nVous recevrez également :\n\n"},
[790] = {title = "Sarkoth", objective = "Tuer Sarkoth et rapporter sa pince à Hana'zua.", description = "<classe> ! Je me voyais déjà mort ici, ignoré de tous. Alors que je chassais les scorpides de la vallée, je fus soudain confronté à un spécimen particulièrement puissant. Je parvins à lui porter un grand coup avant qu'il ne referme ses pinces autour de ma jambe.\n\nJe fus, hélas, distrait par cette attaque et en oubliai le redoutable aiguillon, qui se ficha dans ma poitrine. Je vous en prie, tuez ce scorpide pour moi ! Mon honneur doit être lavé. J'ai combattu la créature sur le plateau, plus au sud.", progress = "Ahhh, mon père disait toujours que je n'accomplirais jamais beaucoup de choses et là, alors que je repose sous un arbre et tandis que la vie s'échappe doucement de mon corps, j'ai bien peur qu'il n'ait eu raison.\n\nAu moins, je souhaite mourir en sachant que mon dernier ennemi dans la vie est mort.", completion = "Mon attaque n'avait pas la puissance pour tuer la bête ; mais la blessure que je lui fis me donne tout de même quelque fierté. Si je trépasse, au moins puis-je partir avec cet orgueil, aussi mince soit-il. Ah, que n'ai-je accompli plus de choses dans cette vie qui maintenant s'éteint...", rewards = "Vous recevrez :\n\n"},
[791] = {title = "Assumer ses responsabilités", objective = "Apporter 8 Morceaux de canevas à Furl Scornbrow, dans la la tour de guet de Tranchecolline.", description = "Mon âge me rend inapte au maniement des armes, mais j'ai appris à me rendre utile par d'autres moyens.\n\nDe ce poste d'observation, je guette les envahisseurs. Nos forces s'accroissant de jour en jour, je me trouve de moins en moins souvent à devoir donner l'alarme en soufflant dans le cor.\n\nAussi, pour passer le temps, je confectionne du matériel et aide de plus jeunes guerriers que moi à défendre leur pays.\n\nJe peux fabriquer un sac pour vos affaires. Si cela vous intéresse, apportez-moi du canevas, un matériau qu'on trouve communément chez les humains et les centaures.", progress = "J'ai fièrement combattu aux côtés du Chef de guerre, quand nous nous sommes établis sur ces terres. Les marques de bataille zèbrent ma peau.\n\nL'honneur de la Horde a été écrit avec le tranchant de ma hache et chanté par mon cri de guerre pendant la défaite d'Archimonde, quand l'Alliance contre nature avec les humains et les elfes fut conclue.\n\nMais ma situation de guetteur et de fournisseur m'a donné un nouvel emploi, une deuxième jeunesse.", completion = "Parfait, &lt;nom&gt;. Les guerriers qui se respectent savent toujours que faire d'un tel sac, sur un champ de bataille.\n\nJe salue votre force et votre engagement à mourir au nom de la Horde !", rewards = "Vous recevrez :\n\nSac en cuir fait main"},
[792] = {title = "Les vils quasits", objective = "Tuer 12 Vils quasits.\n\nRetourner voir Zureetha Fargaze, à l’extérieur de l’Antre.", description = "Je suis sûre que la Vallée des épreuves vous enseignera beaucoup, jeune <classe>.\n\nJ'ai été envoyée dans la Vallée pour vous guider, mais j'y ai découvert une menace croissante.\n\nUn groupe qui se fait appeler la Lame ardente a un convent, ici, dans la Vallée des épreuves. Ils se cachent dans une grotte, au nord-est, d'où leurs vils quasits partent se répandre sur les terres pour les ravager.\n\nComme première action contre la Lame ardente, je vous demande de vaincre ces quasits. Massacrez-les en nombre et, si vous y avez survécu, revenez me voir.", progress = nil, completion = "Vous avez bien agi, &lt;nom&gt;.\n\nLes vils quasits ne sont que des marionnettes dirigées par des puissances agissant au sein de la Lame ardente, mais votre succès en présage de plus grands à l'avenir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGourdin primitifLame de main primitiveHachette primitiveBâton de marche primitif\n\nVous recevrez également :\n\n"},
[793] = {title = "Alliances rompues", objective = "Utiliser le Signe de la Terre pour activer les Piliers de diamant, d'opale et d'améthyste, et obtenir les Pierres runiques.\n\nPlacer les Pierres runiques dans le Sceau de la Terre pour libérer Cinglenoir et Hematus.\n\nLes exécuter et rapporter les Liens de Cinglenoir, les Entraves d'Hematus et le Signe de la Terre à Gorn.", description = "Le Sceau de la Terre est retenu par trois Pierres runiques, placées dans les Piliers de diamant, d'onyx, et d’améthyste dans le Ravin de Lethlor. Avec le Signe de la Terre, vous serez capable d'enlever les Pierres runiques et de déverrouiller le Sceau de la Terre.\n\nPrudence, <nom>, les drakes noirs Cinglenoir et Hematus sont des ennemis à prendre au sérieux. Tuez-les et apportez-moi leurs liens.\n\nPour atteindre le ravin, allez dans la partie la plus à l'est des Terres ingrates. Attention, car le ravin abrite de nombreux drakes.", progress = "Il existe peu d'ennemis plus dangereux que les draconiens, et peu de dragons, en fait, se battirent aussi férocement que Cinglenoir et Hematus.", completion = "Les dragons noirs continuent de s'allier avec ces renégats d'orcs Blackrock. Les uns comme les autres doivent entendre raison ou être détruits. Avec Cinglenoir et Hematus morts, nous pouvons maintenant regarder à l'ouest, vers le pic Blackrock.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCuirasse des vents brûlantsHaubert en écailles prismatiquesPansière de guerreMédaillon d'explosion mentale\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[794] = {title = "Le médaillon de la Lame ardente", objective = "Rapporter le Médaillon de la Lame ardente à Zureetha Fargaze, à l'extérieur de l'Antre.", description = "Mes divinations me font voir qu'un objet de puissance se trouve loin à l'intérieur du convent de la Lame ardente, et qu'il est gardé par des bêtes et de la magie noire.\n\nVous devez trouver cet objet, le Médaillon de la Lame ardente et le prendre au convent.\n\nAttention, il sera probablement entre les mains d'un agent de la Lame ardente autrement plus puissant que les quasits.\n\nPartez, <nom>. Vous trouverez le Convent dans une caverne, au nord puis à l'ouest.", progress = "Avez-vous terminé votre travail, <nom> ? Le Médaillon de la Lame ardente est-il en votre possession ?", completion = "Vous l'avez ! Bravo !\n\nVotre raid sur le convent de la Lame ardente est un premier pas essentiel dans l'éradication de ce culte de la Vallée des épreuves. Je crains malheureusement qu'ils n'aient encore d'autres projets dans le pays.\n\nNous sommes loin d'en avoir fini avec eux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières poussiéreusesLorica abîméePantalon déchiré\n\nVous recevrez également :\n\nPotion de soins mineure"},
[795] = {title = "Sceau de la Terre", objective = "Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d'améthyste, la Pierre runique d'opale et la Pierre runique de diamant.", description = nil, progress = "Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d'améthyste, la Pierre runique d'opale et la Pierre runique de diamant.", completion = "Vous placez les Pierres runiques dans leur alcôves respectives et soudain un violent grondement fait trembler la terre tandis que le Sceau se brise.", rewards = nil},
[804] = {title = "Sarkoth", objective = "Informer Gornek, à l'Antre, de la situation critique dans laquelle se trouve Hana'zua.", description = "Ce que vous avez fait pour moi remplit mon cœur de courage. Je ne peux pas me laisser mourir comme ça, je dois me battre !\n\nJe ne puis, cependant, regagner l'Antre sans assistance. S'il vous plaît, <nom>, retournez à l'Antre et informez Gornek de ma situation. Peut-être saura-t-il m'aider.", progress = nil, completion = "D'après la description que vous m'en avez faite, je déduis que cette bête est Sarkoth ! Ce n'est pas étonnant que Hana'zua ait été complètement surclassée par elle. De l'aide va lui être dépêchée immédiatement, aussi ne vous inquiétez plus de sa situation.\n\nJe suis, en revanche, extrêmement impressionné de votre victoire sur Sarkoth. C'est assurément un acte dont on ne peut que s'enorgueillir, &lt;nom&gt;. Que vous ayez, de plus, combattu pour l'honneur d'un autre, alors que d'autres tâches vous appelaient ailleurs, ne fait que briller un peu plus votre réputation.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGilet souple en laineJambières détériorées en anneaux\n\nVous recevrez également :\n\n"},
[805] = {title = "Faire un rapport au Village de Sen'jin", objective = "Parler à Maître Gadrin au village de Sen'jin.", description = "Vos épreuves contre la Lame ardente sont finies… ici dans la Vallée. Mais je veux que vous rendiez compte de vos découvertes.\n\nAllez au village troll de Sen'jin et cherchez Maître Gadrin. Le village est à l'est de la vallée, puis à droite à l'embranchement.\n\nParlez-lui de la Lame ardente, dites-lui que ses membres ont atteint la Vallée des épreuves. Apprenez de lui s'ils ont déjà atteint Sen'jin.\n\nAllez, <nom>, et faites vite. J'ai peur que le mal découvert au convent de la Lame ardente ne présage un plus grand danger.", progress = nil, completion = "Hmm… votre rapport arrive à un mauvais moment. On ne voit pas la Lame ardente ici a Sen'jin, mais le mal a pris racine au-delà des côtes, sur les îles de l'Écho.\n\nLes orcs sont alliés aux trolls Darkspear. Des amis honorables. Nous voulons aider les orcs, mais... nous avons également besoin d'aide.", rewards = "Vous recevrez :\n\n"},
[806] = {title = "Noirs orages", objective = "Apporter la Griffe de Fizzle à Orgnil Soulscar à Tranchecolline.", description = "Nous ne pouvons permettre à la Lame ardente de prendre pied en Durotar ! Nous devons les détruire avant que ce mal ne suppure !\n\nJ'ai mené mes propres enquêtes et j'ai découvert qu'un démoniste de la Lame ardente, le gobelin Fizzle Darkstorm, s'est établi dans les falaises du Tonnerre au nord-ouest. Là-bas, lui et ses sectateurs répandent le chaos.\n\nTrouvez Fizzle, et éliminez-le. Apportez-moi alors sa griffe !", progress = "Avez-vous trouvé Fizzle, <nom> ? Lui et le reste de la Lame ardente doivent être éradiqués de nos terres !", completion = "Ha ! Vous l'avez eu !\n\nVous faites la fierté de votre clan, &lt;nom&gt;. Grâce à vous, Durotar est débarrassé d'un agent du mal.", rewards = "Vous recevrez :\n\nBottes en peau de tigre"},
[808] = {title = "Crâne de Minshina", objective = "Récupérer le Crâne de Minshina dans le Cercle de puissance, sur les îles de l'Écho.\n\nLe rapporter à Maître Gadrin, au village de Sen'jin.", description = "J'entends la voix de mon frère Minshina qui m'appelle dans mes rêves.\n\nIl a été enlevé par Zalazane, le démoniste des îles de l'Écho, à l'est. Et il est mort.\n\nMais la mort ne l’a pas libéré. Car Zalazane a emprisonné son esprit dans son propre crâne. Dans mes rêves, je peux le voir parmi d'autres crânes, dans un cercle de puissance situé sur la plus grande des îles de l'Écho. Tant qu'il y reste, son esprit est condamné.\n\nJe vous en prie, <nom>. Trouvez le cercle et le Crâne de Minshina. Rapportez-le.\n\nLibérez-le !", progress = "Avez-vous le crâne de mon frère, <nom> ? Est-il enfin libre ?", completion = "Merci, &lt;nom&gt;. Vous avez sauvé Minshina. Vous avez libéré l'âme de mon frère d'un éternel esclavage.", rewards = "Vous recevrez :\n\nCrâne au faible rougeoiement"},
[809] = {title = "Ak'Zeloth", objective = "Parler à Ak'Zeloth, dans les Tarides.", description = "Depuis la dernière grande guerre où la Légion ardente fut défaite, j'ai recherché les sources de corruption démoniaque dans la société des orcs. Le collier que vous m'avez apporté confirme mes craintes.\n\nIl appartient à la Lame ardente, un culte en possession d'un objet de grand pouvoir maléfique qu'on appelle la Graine démoniaque. Vous pouvez la trouver dans les Tarides, au sommet du pic de Brume-funeste. La Graine doit absolument être détruite !\n\nAllez au Poste de garde extérieur, à l'ouest sur la frontière des Tarides et parlez avec mon assistant, Ak'Zeloth. Il vous donnera les prochaines directives.", progress = nil, completion = "Neeru veut voir la Graine démoniaque détruite, n'est-ce pas ? Etrange...\n\nBien, bien ; si c'est vraiment ce qu'il veut, alors je vais vous dire comment vous devrez vous y prendre.", rewards = "Vous recevrez :\n\n"},
[811] = {title = "<INUTILISÉ>", objective = "Apporter 8 Carapaces de grand scorpide à Kor'ghan, au village de Sen'jin.Une autre caractéristique des scorpides est leur loyauté farouche les uns pour les autres. Ils protègeront infailliblement celui des leurs qui se trouve en danger - mais vous avez sûrement déjà « goûté » à cet aspect de leur comportement social, lors de votre première chasse.\n\nVous feriez bien d'adopter cette stratégie : nous sommes plus forts ensembles et solidaires que divisés.\n\nApportez-moi huit carapaces de grand scorpide que vous trouverez sur le cadavre des scorpides blindés que vous pourrez tuer. Vous apprendrez beaucoup de ce travail, et je vous en récompenserai.Vous recevrez :\n\n", description = "Une autre caractéristique des scorpides est leur loyauté farouche les uns pour les autres. Ils protègeront infailliblement celui des leurs qui se trouve en danger - mais vous avez sûrement déjà « goûté » à cet aspect de leur comportement social, lors de votre première chasse.\n\nVous feriez bien d'adopter cette stratégie : nous sommes plus forts ensembles et solidaires que divisés.\n\nApportez-moi huit carapaces de grand scorpide que vous trouverez sur le cadavre des scorpides blindés que vous pourrez tuer. Vous apprendrez beaucoup de ce travail, et je vous en récompenserai.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[812] = {title = "Besoin d'un remède", objective = "Trouver Kor'ghan à Orgrimmar et obtenir l'Antidote du Queue-venin. L'apporter ensuite à Rhinag près de la frontière nord-ouest de Durotar.", description = "<nom>... votre minutage est parfait. J'espère que je pourrai en dire autant de votre célérité.\n\nJ’ai manqué d'attention en combattant des Queues-venin aux alentours, et j'ai été piqué par l'un d'entre eux. Le poison m'affaiblit au moment même où je parle. A ce rythme, il me reste peut-être une heure à vivre. Mais je vais avoir besoin de vous...\n\nKor'ghan, à Orgrimmar, sait comment confectionner l'antidote. Trouvez-le... et faites vite, <nom>. Je ne vais pas pouvoir tenir beaucoup plus longtemps. Il devrait se trouver dans la Faille de l'ombre.", progress = "Je suis presque content de ne pas pouvoir me rendre à Sen'jin, dans l'état où je me trouve ; ma faiblesse et ma stupidité y seraient moquées.", completion = "&lt;nom&gt;, vous m'avez sauvé la vie. Merci.\n\nS'il vous plaît, acceptez cela ; vous pourriez en avoir besoin lors de vos voyages ou, au pire, en tirer quelque argent. Apparemment, je n'en aurai plus besoin pendant longtemps. Kor'ghan va me soumettre à de nouveaux rituels, pour tester mes compétences. Ah, encore des sangliers à tuer, encore des queues de scorpides à trancher...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge de chargeArmure de scorpide légère\n\nVous recevrez également :\n\n"},
[813] = {title = "La recherche de l'antidote", objective = "Apporter 4 Glandes à venin de Queue-venin à Kor'ghan à Orgrimmar.", description = "Les scorpides Queue-venin sont parmi les plus dangereux en Durotar. Rhinag a manqué de sagesse lorsqu'il a les a chassés sans emporter d'antidote, mais à présent, une remontrance est vraiment la dernière chose dont il a besoin.\n\nApportez-moi des Glandes à venin de n'importe quel Queue-venin, et je lui préparerai un antidote. Vous en trouverez près de l'entrée d'Orgrimmar.\n\nDépêchez-vous, <nom>. L'un d'entre nous a besoin de votre aide.", progress = "Rappelez-vous : quel que soit votre adversaire, vous gagnerez à en étudier le comportement et la façon de lutter. Ce genre de savoir pourrait, un jour, vous sauver la vie.", completion = "Voici l'antidote, &lt;nom&gt;. Portez-le à Rhinag aussi vite que possible. Restez prudent.", rewards = "Vous recevrez :\n\nAntidote du queue-venin"},
[815] = {title = "Des oeufs pour l'omelette", objective = "Rapporter 3 Oeufs de fouette-queue au cuisinier Torka, à Tranchecolline.", description = "Bah ! J'allais presque oublier... faut qu'je ficelle le p'tit déjeuner\n\n<nom>, bougez- vous l'train et allez m'trouver quelques oeufs de fouette-queue. M'en faut au moins trois si j'veux en avoir aussi pour le déjeuner de demain.\n\nLe fouette-queue Griffesang peut être farouche et protège ses oeufs jusqu'à la mort, ça oui. Ils les enfouissent parfois bien trop profondément pour pouvoir les déterrer ; mais, bon, si vous fouinez un peu du côté des îles de l'Écho, au sud-est du village de Sen'jin, vous en trouverez d'accessibles à foison, partout sur ces îles.", progress = "Petit déjeuner, déjeuner ou dîner ! Quelle différence, après tout, tant qu'on mâche quequ'chose ? Ça s'cuisine, tout ça, hein ? Et c'est moi qui m'y colle, en l'occurence !", completion = "Z'avez beau être un peu freluquet sur les bords, au moins, vous avez pas deux mains gauches pour ram'ner des provisions, &lt;nom&gt;.\n\nAllez, prenez ça et filez, j'ai d'la cuisine qu'attend de cuire.", rewards = "Vous recevrez :\n\nMorceau de pain rassisViande séchée coriace"},
[816] = {title = "L'égaré", objective = "Trouver un indice du sort de Kron et en informer Misha Tor'kren, à la ferme, au nord-ouest de Tranchecolline.", description = "<nom>, pouvez-vous m'aider ? Mon fils, Kron, est parti chasser il y a quelques jours et il n'est toujours pas revenu. Il est allé à l'ouest, vers les Tarides, pour traquer des crocilisques, le long du fleuve Furie-du-Sud. Je crains le pire.\n\nAussi fort soit-il, sa fierté mal placée l'a toujours conduit dans les pires situations. Lorsque je lui ai dit que les crocilisques étaient puissants et brutaux, il s'est emporté et est parti.\n\nSi vous ne le ramenez pas, découvrez au moins ce qu'il est devenu...Même si vous devez pour cela ouvrir le ventre de chaque crocilisque, le long des bancs de sable de la Furie-du-Sud.", progress = "Je prie pour que Kron me revienne sain et sauf, mais, en mon âme, l'espoir est presque tari.", completion = "Oh, mon fils, mon bel enfant...\n\nIncertaine de son sort, j'étais encore tourmentée par l'espoir de le voir reparaître. Maintenant que je sais ce qui est arrivé, au moins puis-je commencer à porter le deuil.\n\nMerci, &lt;nom&gt;. S'il vous plaît, prenez cela. Je le destinais à Kron, quand il serait rentré, victorieux. Maintenant qu'il est mort, je ne puis supporter la vue de ce cadeau. Prenez-le.", rewards = "Vous recevrez :\n\nCape cousue à la main"},
[817] = {title = "Proie nécessaire", objective = "Apporter 4 Peaux de tigres de Durotar à Vel'rin Fang, au village de Sen'jin.", description = "La plupart des peaux que nous utilisons proviennent des tigres de Durotar, <nom>. Couvertures, armures, tentes, nous avons beaucoup de raisons de chasser ces bêtes, et autant de les laisser prospérer.\n\nLe temps est venu de cueillir la récolte, pour ainsi dire. Nos rangs grandissent et les besoins de mon peuple sont supérieurs à nos provisions. Il me faut plus de peaux pour subvenir à ces besoins.\n\nApportez-moi 4 Fourrures de tigres de Durotar, et je vous récompenserai. Vous pourrez les trouver sur les îles au sud d'ici.", progress = "Je me souviens de ma première chasse au tigre, <nom>. J'avais choisi de chasser l'individu le plus massif des îles de l'Écho. J'étais resté tapi dans l'ombre des feuillages, presque toute une journée, à l'affût... guettant... attendant.\n\nMes muscles se tétanisaient tandis que mon bras ne tremblait pas, prêt à frapper. Enfin, le tigre mordit à l'appât ; quelle grande victoire ce fut.", completion = "Je suis satisfait, &lt;nom&gt;. Grâce à votre contribution, notre peuple n'aura pas froid, maintenant que la saison froide s'annonce.\n\nMerci encore.", rewards = "Vous recevrez :\n\n"},
[818] = {title = "Un esprit parfaitement éduqué", objective = "Apporter 4 Yeux de makrura intacts et 8 Fioles de mucus de clampant à maître Vornal, au village de Sen'jin.", description = "Même si mes yeux sont faibles, j'y vois encore suffisamment clair. Je me repose souvent sur mes compétences en alchimie pour les magies qui autrefois m'étaient aisées. Mais je refuse de prendre <un apprenti/une apprentie>. Aucun orc ou troll assez digne ne s'est jamais présenté.\n\nEt vous, en êtes-vous digne ? Bien sûr que vous en êtes digne... que vous croyez l'être.\n\nJ'ai besoin de certaines choses. Pouvez-vous les obtenir ?\n\nIl me faut des yeux de makruras intacts, et des fioles de mucosités de clampants. De n'importe quels makruras ou clampants en Durotar. Nous nous reparlerons bientôt.", progress = "Le temps est ce qui met véritablement à l'épreuve la force et la volonté. Si vous perdez patience ou cédez à la faiblesse, vous dévoilez votre véritable essence.", completion = "Bravo, mon jeune ami... Beau travail, en vérité.", rewards = "Vous recevrez :\n\nColle très collante"},
[819] = {title = "Tonneau vide de Chen", objective = "Trouver quelqu'un qui en sache davantage au sujet du Tonneau vide de Chen.", description = "Un petit écriteau, placé sur l'un des bouts du tonneau, dit :\n\n\"Chen Stormstout-\n\nQue laper règne sur la terre comme au ciel, et que les spiritueux soient avec votre esprit.\"", progress = "Oui ?", completion = "Eh bien, je serai… \n\nC'était l'un des tonneaux de Stormstout de Chen. Il voyageait avec Rexxar il y a longtemps de cela. Je ne l'ai pas vu ni entendu parler de lui depuis une éternité. J'apprécie que vous m'apportiez ceci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[821] = {title = "Tonneau vide de Chen", objective = "Apporter 5 Canines de lion des savanes, 5 Rognons de trotteur des plaines, et 1 Corne de lézard-tonnerre au brasseur Drohn à Ratchet.", description = "Voudriez-vous goûter à l'homonyme de Chen ? Ahhh ! La Stormstout est une puissante mixture. Chen a appris la recette à mon mentor, et mon mentor me l'a apprise. J'aurais besoin que vous me trouviez certaines choses, mais je vous assure : le choc en vaut la peine.\n\nApportez-moi 5 Canines de lion des savanes, de n’importe quel lion des savanes ; 5 Rognons de trotteur des plaines, de n'importe quel trotteur des plaines, et 1 Corne de lézard-tonnerre. Ça devrait parfaitement faire l'affaire.\n\nVous pouvez trouver ces ingrédients dans les Tarides.", progress = "Comment se déroulent les recherches ?", completion = "Ha ha ! Je n’aurais jamais cru que je préparerais ce machin à nouveau.\n\nVous faites grandement vibrer ma fibre nostalgique, &lt;nom&gt;. Du genre à me rappeler la dernière fois où j’ai brassé de la tête de Trogg. Merci. Les souvenirs réchauffent mon estomac.", rewards = "Vous recevrez :\n\nStormstout"},
[822] = {title = "Tonneau vide de Chen", objective = "Apporter 5 Glandes de corne-éclair, 1 Glande salivaire de faucon-tonnerre et 1 Foie de kodo au brasseur Drohn à Ratchet.", description = "Sacré caractère, cette Brune d’Orage, hein ?\n\nJ’ai une autre recette que j’ai apprise de Chen. Ça vous intéresse ? Ça ne sera pas long, et ça peut même vous être utile si vous comptez poursuivre vos aventures.\n\nApportez-moi cinq glandes d’éclair d’orageux, une glande salivaire de faucon-tonnerre et un foie de kodo. Vous trouverez tout ça dans les Tarides.\n\nComme je l'ai dit, ce breuvage décoiffe. C'est la tête de Trogg dont je vous ai parlé.", progress = "Alors, vous travaillez dur pour rechercher ces ingrédients, <nom> ?", completion = "Ha ha ! Je savais que vous ne résisteriez pas à l’envie de goûter ce mélange. Revenez quand vous voulez si vous en souhaitez encore, &lt;nom&gt;. Apportez-moi simplement les ingrédients nécessaires.", rewards = "Vous recevrez :\n\nTête de Trogg"},
[823] = {title = "Un rapport à Orgnil", objective = "Parler à Orgnil Soulscar à Tranchecolline.", description = "Nous autres au village de Sen'jin avons nos problèmes, et nous vous remercions pour votre aide. Mais les nouvelles que vous apportez à propos de la Lame ardente pourraient annoncer des ennuis pour tout le monde.\n\nUn orc nommé Orgnil Soulscar est posté à Tranchecolline. Il protège Durotar de maux tels que la Lame ardente. Allez lui parler et informez-le de notre demande. Donnez-lui également des nouvelles de la Vallée des épreuves. Il voudra savoir ces choses.\n\nTranchecolline est au nord.", progress = nil, completion = "Oui ? Avez-vous quelque chose à me dire ? Eh bien, j'écoute !", rewards = "Vous recevrez :\n\n"},
[824] = {title = "Je'neu du Cercle terrestre", objective = "Apporter le Globe d'eau souillée à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", description = "Le Cercle terrestre est un groupe de chamans dédié à l'étude et à la préservation des éléments. Ils en savent plus sur les dieux anciens fous, les vieilles légendes et les savoirs antiques que la plupart des savants de ce monde.\n\nHeureusement pour vous, je connais quelqu'un du Cercle terrestre, ici, à Ashenvale. Allez à l'avant-poste de Zoram'gar, sur la côte de la grève de Zoram. Montrez à Je'neu Sancrea ce que nous avons trouvé. Si quelqu'un peut découvrir quelle est la signification de ce globe, c'est bien lui.", progress = "Ha, bonjour. J'ai passé beaucoup de temps à étudier l'eau, en fait tous les éléments, tellement de temps que parfois je ne remarque même pas les gens autour de moi.\n\nQue puis-je faire pour vous ?", completion = "Ce globe... est fort troublant. Beaucoup des élémentaires les plus puissants reçoivent leurs pouvoirs de tels objets. En trouver un quasiment intact est une chose - le trouver aussi corrompu que celui-là en est une autre.\n\nJe vais m'assurer que ce globe est étudié dans le détail par le Cercle terrestre. Peut-être pouvons-nous mettre un terme à cette corruption des éléments. S'il vous plaît, acceptez ceci comme juste récompense pour avoir apporté ce globe au Cercle terrestre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture d'équilibristeBouclier de DriftmireCape du saule souple\n\nVous recevrez également :\n\n"},
[825] = {title = "Des épaves", objective = "Gar'Thok de Tranchecolline veut que vous retrouviez 3 Outils gnomes parmi les épaves près de la côte.", description = "L'un de mes éclaireurs les plus observateurs me rapporte que les épaves de la flotte de Proudmoore sont toujours près de la côte de Durotar, juste à l'est du donjon de Tiragarde.\n\nCe n'est un secret pour personne que les humains, alliés à ces petites bêtes idiotes que sont les gnomes, possèdent des connaissances avancées en mécanique. Nous devons apprendre précisément les savoirs de tous nos ennemis potentiels. Et notre peuple bénéficiera de ces nouveaux savoirs, également.\n\nNagez à travers les épaves, <nom>, et trouvez pour moi les outils de l'Alliance.", progress = "Une fois que nous aurons appris comment les humains font fonctionner leur étrange machinerie, nous aurons plus de chances de les battre lors des batailles futures.\n\nUne fois cette connaissance acquise, la Horde ne pourra que croître en puissance.", completion = "Votre mission de récupération a été un succès, &lt;classe&gt;. Je veillerai à ce que ces outils soient envoyés à Orgrimmar par la prochaine caravane.\n\nBon travail.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes empoussiéréesGarde-poignets de coureur des sablesGrand ceinturon en métal\n\nVous recevrez également :\n\n"},
[826] = {title = "Zalazane", objective = "Battre Zalazane.\n\nTuer 8 Trolls vaudou et 8 Trolls maléficiés.\n\nApporter la Tête de Zalazane à Gadrin.", description = "Le sorcier-docteur Zalazane demeure sur les îles de l'Écho, à l'est. Ce sont les îles que nous appelions autrefois « maison ».\n\nDe là, il envoie ses trolls sur le continent et déchaîne ses maléfices sur notre peuple pour placer davantage des nôtres sous son emprise.\n\nIl faut l'arrêter.\n\nBattez Zalazane et ses serviteurs, d'anciens trolls Darkspear perdus pour notre cause. Apportez-moi sa tête, et je saurai que son règne maléfique est terminé.", progress = "Avez-vous battu Zalazane, <nom> ?", completion = "Sans Zalazane, notre tribu peut de nouveau dormir en paix.\n\nMerci, &lt;nom&gt;. La tribu Darkspear vous doit beaucoup. Si vous souffrez d'une douleur, voyez mon assistant Bom'bay, derrière moi. Sa connaissance du vaudou est grande…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de légèretéPoignes voilées\n\nVous recevrez également :\n\n"},
[827] = {title = "Rocher du crâne", objective = "Prendre les Colliers brûlants des sectateurs au Rocher du crâne.\n\nLes apporter à Margoz à son camp.", description = "<nom>. La Lame ardente a infesté la caverne appelée le Rocher du crâne, à l'est d'Orgrimmar. Ils y accomplissent des rituels abominables, et brûlent leur propre chair avec des Colliers brûlants.\n\nEn portant ces colliers, je pense que les sectateurs s'harmonisent avec la puissance démoniaque. Mais pour le confirmer, je dois en posséder une collection afin de les étudier.\n\nPartez pour le Rocher du crâne et prenez les Colliers brûlants que vous trouverez sur les membres du culte. Apportez-les-moi, et je dévoilerai leurs mystères.", progress = "Êtes-vous entré dans le Rocher du crâne, <nom> ? Avez-vous des Colliers brûlants ?", completion = "Bien. Caché à l'intérieur de ces colliers, se trouve le secret de la Lame ardente. Et je vais le découvrir…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague denteléeSolide bâtardeMasse hérissée\n\nVous recevrez également :\n\n"},
[828] = {title = "Margoz", objective = "Parler à Margoz.", description = "L'un de nos chamans, Margoz, en sait plus sur la corruption de la Lame ardente. Il parle d'une caverne appelée Rocher du crâne dans les montagnes, juste à l'extérieur d'Orgrimmar, qui abrite un important groupe de sectateurs.\n\nAvant que vous ne partiez pour le Rocher du crâne, parlez à Margoz. C'est un sage et son conseil est précieux.\n\nIl campe au nord-est, entre la côte et le Ravin asséché.\n\nSuivez son avis, mais quoi qu'il dise, <nom>, je veux que vous écrasiez ce culte !", progress = nil, completion = "Bienvenue, &lt;nom&gt;. J'ai eu vent de votre venue, et de vos exploits en Durotar.\n\nVotre renom et vos compétences vont grandissants, &lt;classe&gt;.\n\nRestez sur le chemin pur, et votre avenir sera grandiose.", rewards = "Vous recevrez :\n\n"},
[829] = {title = "Neeru Fireblade", objective = "Apporter un Spécimen de collier à Neeru Fireblade à Orgrimmar.", description = "Les Colliers brûlants que vous m'avez apportés sont des instruments puissants et démoniaques. Deviner leur origine est cependant, je le crains, au-delà de mes capacités de chaman. Nous aurons besoin qu'un démoniste les étudie.\n\nApportez un Collier brûlant à Neeru Fireblade. Bien qu'il soit un redoutable démoniste, il professe qu'il utilise ses pouvoirs pour contrecarrer les démons, et proclame que ses recherches sur l'occulte sont bénignes. Que cela soit vrai ou pas, nous pouvons avoir besoin de son aide contre le culte démoniaque en Durotar. Vous trouverez Neeru à Orgrimmar, dans la Faille de l'ombre.", progress = "Mes plus humbles salutations, <classe>. Comment pourrais-je aider mon frère <nom>, aujourd'hui ?", completion = "Ah ! Et où l'avez-vous trouvé ? Ce bon Margoz de Tranchecolline vous envoie, c'est ça ?\n\nBien, laissez-moi y regarder de plus près.", rewards = "Vous recevrez :\n\n"},
[830] = {title = "Les ordres de l'amiral", objective = "Apporter les Ordres de l'amiral Proudmoore à Gar'Thok de Tranchecolline.", description = "Vous ouvrez la vieille enveloppe décolorée et découvrez un document d'apparence officielle. Vous reconnaissez le sceau de l'amiral Proudmoore.\n\nÇa a l'air important. Peut-être que Gar'Thok, le commandant de Tranchecolline, serait intéressé par cette information.", progress = "Vous paraissez bien soucieux, <classe>. Qu'avez-vous là ?", completion = "Cela ne présage rien de bon. Vous avez été bien avisé de porter cette information à mon attention.", rewards = "Vous recevrez :\n\n"},
[831] = {title = "Les ordres de l'amiral", objective = "Porter les Ordres de l'amiral Proudmoore à Nazgrel, dans les appartements de Thrall à Orgrimmar.", description = "On ne peut pas faire confiance aux humains. Nous avons combattu à leurs côtés le cœur empli de lassitude, sachant qu'ils nous trahiraient un jour.\n\nLa mort de l'amiral Proudmoore n'a pas été suffisante pour clore cette longue tradition de tromperie. Cette vermine avait bien préparé ses plans avant qu'il ne rencontre la mort.\n\nSon influence ne s'éteindra pas non plus avec Benedict. Qui sait combien de temps il reste avant que la prochaine vague d'hommes de Proudmoore ne déferle sur nos rivages ?\n\nNous devons apporter ces ordres à Nazgrel à Orgrimmar immédiatement ! On peut le trouver dans les logements de Thrall.", progress = "Ne pouvez-vous pas voir que je suis occupé ? Cela a intérêt à être urgent…", completion = "Maintes fois j'ai exhorté le Chef de guerre de ne pas faire confiance aux humains, mais la fierté personnelle n'est pas ce qui est en jeu maintenant.\n\nVous avez servi la Horde honorablement, jeune &lt;classe&gt;.\n\nÀ présent excusez-moi, je dois immédiatement m'entretenir avec Thrall à ce propos...", rewards = "Vous recevrez :\n\n"},
[832] = {title = "Ombres ardentes", objective = "Apporter cet Oeil à Neeru Fireblade.", description = "<Des mots émanent du pendentif et dans votre esprit.>\n\nGazz'uz ?\n\nGazz'uz… au rapport !\n\nOn raconte que vous avez été découvert au rocher du crâne. Vous devez vous préparer à une attaque !\n\nGazz'uz, je vous ordonne de parler ! Parlez ou je m'assurerai que Neeru Fireblade apprenne votre présence, et il vous tombera dessus comme la misère sur le monde.\n\nNe testez pas vos capacités contre Neeru...\n\n... Gazz'uz, vous êtes là ?", progress = "Il y a quelque chose de crucial dont vous voulez me parler. Je peux le sentir derrière vos yeux.", completion = "&lt;Il examine l'Oeil de l'ombre ardente.&gt;\n\nIntriguant. La voix que vous avez entendue a prononcé mon nom ? Je suis connu pour traquer les ennemis de notre Chef de guerre, mais… il est étrange que j'aie été ainsi distingué. Et encore plus étrange que les sectateurs de la Lame ardente, de qui vous avez obtenu ce pendentif, aient parmi eux quelqu’un avec un nom aussi proche du mien.\n\nJe dois étudier ce pendentif. je dois l'étudier, et réfléchir au sens de son message.\n\nMerci d'avoir porté cela à mon attention, &lt;nom&gt;. Vous avez rendu un grand service à votre peuple.", rewards = "Vous recevrez :\n\n"},
[833] = {title = "Cimetière sacré", objective = "Le Gardien du savoir Raintotem veut que vous tuiez 8 Intrus Dos-hirsute aux Rochers rouges.", description = "Seuls les plus vaillants taurens sont enterrés aux Rochers rouges, notre terre funéraire sacrée. C'est un honneur accordé aux grands guerriers qui ont aidé à construire et à défendre Thunder Bluff et à ceux qui ont donné leur vie pour le bien de leur tribu et de leurs chefs.\n\nMais il apparaît qu'un infâme danger menace notre terre sacrée. Un groupe d'Intrus Dos-hirsute ravage le cimetière et je suis trop vieux et trop faible pour les repousser.\n\nIls doivent pourtant être chassés sans pitié, <nom>.", progress = nil, completion = "Bon travail. Vous avez envoyé à ces abjects Dos-hirsute un message clair. Ils y penseront à deux fois avant de profaner à nouveau ce lieu saint.", rewards = "Vous recevrez :\n\n"},
[834] = {title = "Des vents dans le désert", objective = "Retrouver 5 Sacs de marchandises et les rendre à Rezlak près d'Orgrimmar.", description = "Je suis Rezlak, l'un des gars de Gazlowe. Le patron m'a envoyé pour donner un coup de main aux orcs, ici en Durotar. Les choses se sont bien passées, à part pour les caravanes. Je n'arrive pas à assurer leur sécurité ! Ça rend mon boulot un peu plus difficile, vous savez ?\n\nLa dernière livraison – ils ont promis que je passerais ! – a été chipée par les harpies Terrevent au... c'était où déjà... au canyon de Tranchevent ?\n\nFaut que je récupère ces marchandises ou je n'arriverai jamais à rien ! Suivez le grand canyon vers le sud, vous trouverez le ravin coupant exactement les parois à l'est et à l'ouest.", progress = "Je suis fort dans ce que je fais, ne vous méprenez pas, mais c'est ridicule ! Je suis supposé faire quoi ? Des châteaux de sable ?", completion = "Eh bien, n'est-ce pas exactement ce que nous voulions ? Vous nous avez rapporté nos marchandises. C'est merveilleux ! Je vais pouvoir retourner bosser dès que j'aurai trouvé quelqu'un pour porter ces sacs pour moi.", rewards = "Vous recevrez :\n\n"},
[835] = {title = "Des lignes sécurisées", objective = "Tuer 12 Terrevent farouches et 8 Sorcières des tempêtes Terrevent pour Rezlak près du Ravin asséché.", description = "Gazlowe m'a dit une fois \"Rezlak, il y a une chose que tu dois savoir dans la vie : si tu veux qu'une chose soit faite de manière correcte, fais-la toi-même.\"\n\nJe ne peux supporter la perte de nos caravanes, alors je vais m'occuper des choses en personne. Le Ravin asséché est quelque part dans la partie est du canyon de Tranchevent. Si nous y tuons toutes les harpies, les routes seront sûres.\n\nBien sûr, il y a autre chose que Gazlowe m'a enseigné, et c'est \"En payant bien, tout est possible.\" Alors, vous allez m'aider, <nom> ?", progress = "Vous ne penseriez pas ça d'un type comme mon patron Gazlowe, mais il semblait toujours savoir de quoi il en retournait. \"N'aie pas peur d'accomplir ce grand pas,\" qu'il disait.\n\nLes harpies ne vont pas arrêter de nous ennuyer et les caravanes ne vont pas passer sans être attaquées à moins que nous y fassions quelque chose, hein ?", completion = "Je vais mieux respirer maintenant que les harpies n'attaqueront plus nos caravanes d'approvisionnement. Et juste au bon moment, d'ailleurs. J'ai entendu que l'on m'envoyait de chouettes petits jouets par le prochain chargement !\n\nVous vous débrouillez plutôt bien dans ce que vous faites, &lt;nom&gt;. Vous devriez aller voir mon patron à Ratchet. Je parie qu'il pourrait vous trouver du travail.\n\nEt ne vous inquiétez pas, je n'oublierai pas de vous payer pour le service que vous m'avez rendu.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAile de la harpieArc en noyerBâton de bois abîmé\n\nVous recevrez également :\n\n"},
[836] = {title = "À la rescousse de OOX-09/HL !", objective = "Escorter OOX-09/HL jusqu'au littoral au-delà des Haut-Surplombs, puis rendre compte à Oglethorpe Obnoticus à Baie-du-Butin.", description = "Le robot émet à nouveau la voix du gnome :\n\n\"Je dois déplacer OOX-09/HL dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage. Il est équipé d'un camouflage, mais il me faut du temps pour le rendre opérationnel de mon côté. Il faut que vous l'escortiez jusqu'au... disons jusqu'au littoral qui s'étend au-delà des Haut-Surplombs l ! Ce serait un endroit parfait, et assez long, pour que tout puisse se mettre en route !\"\n\nEscortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Oglethorpe Obnoticus, terminé.\"", progress = nil, completion = "Oh, c'est VOUS qui avez sauvé OOX-09/HL ! Aucune formule ne pourrait exprimer l'étendue de ma reconnaissance ! Mes robots guidés ont encore besoin d'être améliorés, mais votre sauvetage m'a épargné un nombre incalculable d'heures de reconstruction, ainsi que de nombreuses pièces d'or !\n\nJe vous en prie, prenez l'un des objets que je possède. J'espère que vous en ferez bon usage. Merci encore pour votre aide généreuse, &lt;nom&gt;, mes robots et moi-même vous sommes redevables !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes d'inventeur gnomeBottes engloutissantes gnomes\n\nVous recevrez également :\n\n"},
[837] = {title = "Empiètement", objective = "Tuer 4 hurans Tranchecrin, 4 Eclaireurs Tranchecrin, 4 Lève-poussière Tranchecrin et 4 Gardes de guerre Tranchecrin pour Gar'Thok de Tranchecolline.", description = "Quand nous sommes arrivés, les hurans Tranchecrin possédaient la majeure partie de la terre, et étaient comme une épine dans notre flanc. Par des efforts constants, nous sommes parvenus à en chasser une grande partie, mais ils restent toujours bien fortifiés dans certains secteurs.\n\nCela a suffisamment duré, cependant. Pour notre propre sécurité, nous ne pouvons tolérer la présence des Tranchecrins sur notre territoire. On peut trouver leurs camps à l'ouest d'ici. Cherchez les roncières et vous les trouverez. Aujourd'hui, nous les chassons de Durotar, et demain, peut-être, de tout Kalimdor.", progress = "Bien qu'ils possèdent quelque intelligence et quelque organisation, je trouve ahurissant que les hurans aient été capables de s’approprier et de défendre un si vaste territoire en Kalimdor. Ce sont peut-être des ennemis plus aguerris que je ne l'aurais pensé.", completion = "Je transmettrai l'information disant que les hurans ont été délogés de leurs repaires, et que l'on peut mettre le feu à leurs camps. L'éradication des hurans de Durotar nous rapproche de notre but : sécuriser les frontières de notre nouvelle terre d'accueil.", rewards = "Vous recevrez :\n\n"},
[838] = {title = "Scholomance", objective = "Parler au Pharmacien Dithers à la Barricade, dans les Maleterres de l'ouest.", description = "Sur l'île de Caer Darrow se trouve Scholomance - une école servant de forteresse au Fléau. Nos ennemis y résident, à l'abri, et libres de poursuivre des recherches qui ne font qu'accroître leur pouvoir. Une porte se dresse sur le chemin, et malgré tous nos efforts, elle ne peut être franchie sans que la bonne clé ne lui soit présentée.\n\nLe Pharmacien Dithers en connaît beaucoup sur Scholomance, et a une idée quant à la façon d'obtenir cette clé. Vous m'avez prouvé que vous êtes capable d'atteindre des objectifs, aussi je vous confie cette tâche. Allez lui parler et entretenez-le à ce propos.", progress = nil, completion = "Oui, &lt;classe&gt;, le Grand exécuteur a mentionné le fait que vous puissiez être la personne adéquate dans l'affaire de la clé. J'ai consacré une bonne partie de mes dernières études à Scholomance, et je crois connaître un moyen d'en acquérir une qui vous permettra d'ouvrir la porte principale à volonté.\n\nCette tâche ne sera pas facile, mais bien peu le sont. Vous semblez être le genre de personne qui n'ignore pas ce fait.", rewards = "Vous recevrez :\n\n"},
[840] = {title = "Sous les drapeaux de la Horde", objective = "Suivre la route de l'ouest, celle qui part de Tranchecolline, et qui arrive aux Tarides par un pont.\n\nS'arrêter à l'avant-poste orc sur le pont.\n\nDonner votre lettre de recrutement à Kargal Battlescar aux Tarides.", description = "Hum ! Vous avez l'air plutôt <fort/forte>.\n\nÉcoutez, mon bon ami Kargal a besoin de nouvelles recrues pour servir dans les Tarides. Je sais que vous voulez faire ce qui est bon pour la Horde. Eh bien, voici votre chance !\n\nApportez cette lettre de recrutement à Kargal et voyez s'il la signe...", progress = "Qu'est-ce que vous voulez, morveux ? Si vous n'êtes pas là pour vous engager, je n'ai pas de temps pour vous.", completion = "Alors c'est Takrin qui vous envoie ? C'est un excellent éclaireur, je ne sais pas ce que je ferais sans lui.\n\nJe vais signer votre lettre de recrutement, mais ce dont nous avons vraiment besoin, c'est de quelqu'un à la Croisée.", rewards = "Vous recevrez :\n\n"},
[841] = {title = "Une autre Source d'énergie ?", objective = "Apporter 10 Outres de Bat-le-désert à l'ingénieur en chef Bilgewhizzle à Gadgetzan pour qu'il les échange contre une autre source d'énergie.", description = "Laissez-moi deviner… vous n’avez pas accompli l'un de vos horribles exploits à temps. Non, attendez, encore mieux, vous l'avez laissée tomber dans le sable ! Bien, qu’importe la raison, j’ai d’autres sources d'énergie que je peux vous vendre. Cette fois, cependant, ça vous coûtera dix, OUI DIX Outres de Bat-le-désert !\n\nLes temps sont durs par ici vous savez, <nom>, et les sources d'énergie ne poussent pas sur les arbres ! Hmm, mais si c'était le cas... peut-être que nous pourrions FABRIQUER un arbre à sources d'énergie...", progress = "Alors,vous avez les dix outres ?", completion = "Très bien, voici une autre source d'énergie. Je recommande vraiment que l'utilisiez correctement cette fois-ci, à moins que vous ne souhaitiez consacrer dix outres de plus pour une autre source d'eau.", rewards = "Vous recevrez :\n\nSource d'énergie modèle 4711-FTZ"},
[842] = {title = "Conscription à la Croisée", objective = "Suivre la route à l'ouest à partir du Poste de garde extérieur de Kargal.\n\nA l'intersection en T, tourner à gauche et suivre la route vers le sud.\n\nTrouver Sergra Darkthorn où les routes se croisent à l'intérieur de la Croisée.", description = "Apportez cette lettre de recrutement signée à la Croisée.\n\nSergra Darkthorn, que sa peau soit maudite, est la responsable là-bas. C'est une affreuse chaman qui vous saoulera de paroles avant de vous laisser faire quoi que ce soit d'utile. Thrall est convaincu qu'elle est spéciale, mais je n'en suis pas si sûr.\n\nVous aurez à vous faire votre propre opinion, <morveux/morveuse>...", progress = "Eh bien, eh bien, eh bien ! Qu'avons-nous là ? Kargal m'aurait-il jugée digne d'une nouvelle recrue ?", completion = "Très bien, &lt;nom&gt;. Vous voulez gagner votre vie dans la Horde ? Eh bien il y a beaucoup à faire par ici ! Alors écoutez-moi bien et faites ce que l'on vous dit.\n\nJe vois bien comment vous me regardez, ne croyez pas que je tolérerai la moindre insolence. Thrall en personne a déclaré que les femelles de la Horde devaient être sur un pied d'égalité avec vous les mâles. Manquez-moi un tant soit peu de respect et je vous ferai comprendre votre douleur.", rewards = "Vous recevrez :\n\n"},
[843] = {title = "La réclamation de Gann", objective = "Gann Stonespire veut que vous tuiez 15 Excavateurs de Bael'dun et 5 Surveillants de Bael'dun.\n\nApporter le Journal de Khazgorm à Gann Stonespire.", description = "Je foule ces chemins dans la solitude.\n\nLes nains de Bael Modan n'ont aucun respect pour ma terre. D'horribles explosions creusent profondément le sol tandis que des machines éventrent les collines. La terre qui autrefois était le foyer et la nourrice de ma tribu est aujourd'hui grouillante de ces nains destructeurs.\n\nLes tentatives diplomatiques pour arriver à un accord ont échoué. À présent l'heure de l'action radicale a sonné.\n\nRepoussez par la force les nains de Bael Modan et apportez-moi le journal de leur chef, le Prospecteur Khazgorm.", progress = "De nombreux taurens innocents ont perdu la vie ou ont été exilés du lieu sacré de leur naissance lorsque les nains de Bael Modan sont arrivés. Nous devons reprendre nos terres !", completion = "Khazgorm a rencontré le sort qu'il méritait. Je n'ai aucun remords pour cet imbécile. C'était un infidèle.\n\nPuisse sa mort servir d'avertissement à tous ceux qui menaceront notre mode de vie.\n\nÀ présent, laissez-moi prendre connaissance de ce journal.", rewards = "Vous recevrez :\n\n"},
[844] = {title = "La menace des trotteurs des plaines", objective = "Collecter 7 Becs de trotteurs des plaines et les apporter à Sergra Darkthorn à la Croisée.", description = "Votre première proie sera une proie facile.\n\nLes trotteurs des plaines, à l'est, attaquent constamment nos réserves de nourriture et sont devenus une véritable nuisance.\n\nAbattez-les et revenez me voir avec leurs becs.", progress = "Avez-vous récupéré les Becs de trotteurs des plaines ?", completion = "Parfait, &lt;nom&gt;. Maintenant que les trotteurs des plaines ne sont plus là, il nous sera plus facile de conserver en bon état notre chaîne d'approvisionnement. Et j'espère que vous avez appris quelques astuces ici dans les Tarides, car votre prochaine proie possède un peu plus de feu dans les veines que ces trotteurs...", rewards = "Vous recevrez :\n\n"},
[845] = {title = "Les zhévras", objective = "Tuer des Messagers zhévras et apporter 4 Sabots de zhévra à Sergra Darkthorn à la Croisée.", description = "Les zhévras ne sont pas les bêtes les plus redoutables des Tarides, mais ils sont un peu plus dangereux que les trotteurs des plaines. Ne vous en faites pas, nous vous enverrons combattre des proies plus conséquentes en temps utile, mais vos dents ont encore besoin d'être aiguisées.\n\nChassez les zhévras au nord et au sud, et récupérez leurs sabots. Apportez-les-moi et peut-être que la prochaine fois nous vous indiquerons quelque chose de plus coriace.", progress = "Combien de zhévras avez-vous tués ?", completion = "Pas mal, &lt;nom&gt;. Ces zhévras ont beaucoup de force. Un coup bien placé peut même renverser un tauren !\n\nMais il semble que vous ayez également de la force en vous. Êtes-vous prêt à relever un véritable défi ?", rewards = "Vous recevrez :\n\n"},
[846] = {title = "La revanche de Gann", objective = "Gann Stonespire veut que vous lui apportiez 6 Fioles de Nitroglycérine, 6 Paquets de Pulpe de bois, et 6 Echantillons de Nitrate de sodium.", description = "Il est évident que le prospecteur dépendait des explosifs et des véhicules bruyants pour déchirer le sol. Nous pouvons nous attendre à ce qu'un nouveau contremaître le remplace bientôt.\n\nJ'aimerais faire goûter aux nains leur propre médecine. D'après ces plans, si nous combinons de la nitroglycérine avec de la pulpe de bois et du nitrate de sodium, nous pouvons créer une charge explosive. Les fusiliers, les soldats et les officiers du donjon possèdent ces ingrédients.\n\nRécupérez ces objets et apportez-les-moi. Je confectionnerai une charge que les nains ne sont pas près d'oublier.", progress = "Je vois que vous êtes de retour, <nom>.\n\nBien que la mort de Khazgorm puisse retarder un peu l’éventration de mes terres ancestrales, elle n'empêchera certainement pas l'arrêt du carnage.\n\nLe donjon de Bael Modan représente une menace militaire grandissante. Construit pour défendre le site de fouilles, les forces d'invasion s'y rassemblent également.\n\nSi vous avez les ingrédients que j'ai demandés, je confectionnerai une charge qui obligera ces nains pressés à reconsidérer leurs perspectives dans les Tarides.", completion = "Je vois que vous travaillez dur, &lt;classe&gt;.\n\nIl ne fait pas de doute que nous aurons bientôt une surprise amusante pour ces nains.", rewards = "Vous recevrez :\n\n"},
[847] = {title = "La ruse du raptor", objective = "Parler à Tor'gan.", description = "Ce… Ce pouvoir… Est-ce le pouvoir des chamans que Tor'gan a essayé de me montrer ? Je dois admettre que c'est intéressant. Dites à Tor'gan qu'il a réussi à me convaincre… pour l'instant. Je vais écouter ce qu'il a à dire.", progress = nil, completion = "Lorsque l'enchantement s'éteindra, je parlerai à Gor'mul. Je vous remercie d'avoir contribué au retour de Gor'mul dans le monde des vivants. Il ne fait pas de doute qu'il vous remerciera tout autant.", rewards = "Vous recevrez :\n\nAppel du raptor"},
[848] = {title = "Spores fongiques", objective = "Apporter 4 Spores fongiques à l'Apothicaire Helbrim à la Croisée.", description = "Les oasis des Tarides abritent un mystère. L'énergie de la vie coule dans leur eau, revigorant les plantes et les bêtes qui la boivent.\n\nRevigorante et stimulante.\n\nUn champignon pousse près de ces oasis. Ses spores détiennent des propriétés que nous, les Apothicaires de Lordaeron, trouvons utiles.\n\nApportez-moi ces spores et vous obtiendrez ma gratitude.", progress = "Avez-vous les spores, <nom> ? Je dois envoyer à mon associée de Thunder Bluff une mixture qui en utilise...", completion = "Ah oui ! Voilà de beaux spécimens. Et puissants.\n\nJ’appartiens aux Réprouvés et nous tenons toujours nos promesses. Voici votre récompense, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[849] = {title = "La revanche de Gann", objective = "Détruire la Machine volante à Bael Modan et retourner voir Gann Stonespire.", description = "En suivant les plans de Khazgorm, la fabrication d’une charge explosive ne devrait pas poser de problème.\n\nAh ! Nous y voilà.\n\nÀ présent, <nom>, je vais vous confier une tâche spéciale. Prenez ce Bâton explosif et utilisez-le pour faire sauter la machine volante à Bael Modan.\n\nNon seulement cette machine est une partie cruciale de l’infrastructure du site, mais elle sert également de machine de guerre. Plus important encore, c'est un symbole de pouvoir et une insulte portée à la mémoire de ma tribu.\n\nFaites ma fierté en concluant cette quête héroïque et vous serez <récompensé/récompensée>.", progress = nil, completion = "Vous avez œuvré à merveille, &lt;nom&gt; ! Puissiez-vous être révéré à Thunder Bluff comme protecteur des terres sacrées des taurens et champion de la tribu perdue.", rewards = "Vous recevrez :\n\nAnneau de clan totémique"},
[850] = {title = "Les chefs des Kolkar", objective = "Apporter la Tête de Barak à Regthar Deathgate, à l'ouest de la Croisée.", description = "Les centaures nuisent aux taurens depuis des années. Et récemment, les centaures Kolkar des Tarides sont devenus un danger réel. D'habitude, ils étaient désorganisés, mais de nouveaux chefs ont émergé. Et les ont unis.\n\nAfin de préserver nos possessions ici, ces chefs centaures doivent être éliminés.\n\nApportez-moi la tête de Barak Kodobane. Il campe près des Bassins oubliés au nord.\n\nBattez-le, puis revenez me voir.", progress = "Salutations, <nom>. Avez-vous la Tête de Barak Kodobane pour moi ?", completion = "Bien joué, &lt;nom&gt;. Les centaures sont des créatures lentes et brutales, mais certains ont l'esprit et la vision nécessaires pour mener les autres. Et ceux-là sont les plus dangereux.\n\nBarak était un centaure de cette trempe. Il est bon qu'il soit mort…", rewards = "Vous recevrez :\n\n"},
[851] = {title = "Verog le Derviche", objective = "Apporter la Tête de Verog à Regthar Deathgate, à l'ouest de la Croisée.", description = "Le centaure Verog le Derviche rôde dans les Tarides, et il va être difficile à trouver. Mais il est basé à la tente de commandement des centaures, à l'Oasis stagnante au sud-est. Il peut être possible de l'attirer.\n\nPartez pour l'Oasis stagnante au sud-est et attaquez les centaures près de la tente de commandement. Ce sera dangereux, mais si vous tuez suffisamment de centaures, ils sonneront l'alarme. Et Verog viendra.\n\nApportez-moi sa tête et je la mettrai avec celle de Barak Kodobane.", progress = "Avez-vous trouvé Verog, <nom> ?", completion = "Très bien. Vous avez vraiment dû bousculer ces centaures : nos gardes ont noté de l'activité près de l'Oasis stagnante, c'était probablement vous.\n\nVous pouvez être fier de votre exploit, &lt;nom&gt;. Vous possédez beaucoup de courage.", rewards = "Vous recevrez :\n\n"},
[852] = {title = "Hezrul Marque-de-sang", objective = "Apporter la Tête d'Hezrul à Regthar Deathgate, à l'ouest de la Croisée.", description = "Hezrul Marque-de-sang est le chef des centaures Kolkar dans les Tarides. Il est féroce, brutal et malin. L’éliminer sèmerait la confusion et briserait l’unité des Kolkar. Le danger qu'ils représentent serait ainsi largement diminué.\n\nAussi tuez-le. Tout comme pour Barak et Verog, apportez-moi sa tête.\n\nHezrul dirige son peuple depuis l'Oasis luxuriante, au sud.", progress = "Hezrul Marque-de-sang est-il vaincu, <nom> ?", completion = "Je loue vos compétences, &lt;nom&gt;. Ces centaures sont indisciplinés et ne peuvent contrôler leur rage comme le peuvent les orcs, mais ils sont féroces malgré tout. En les battant, vous avez prouvé votre valeur.", rewards = "Vous recevrez :\n\nAnneau du chasseur de primes"},
[853] = {title = "Apothicaire Zamah", objective = "Apporter les Spores fondues à l'Apothicaire Zamah à Thunder Bluff, avant que la limite de temps ne soit dépassée.", description = "J'ai fait une émulsion avec les spores que vous m'avez apportées. Je dois à présent l'envoyer à mon associée, l'Apothicaire Zamah. Si vous pouviez la lui apporter, elle pourra vous offrir quelque chose de nos magasins d'alchimie.\n\nElle est aux Bassins de la vision, une caverne qui se trouve sous les chamans de Thunder Bluff. Le chemin menant à cette caverne est bien caché, mais vous pourrez le trouver sur la Cime des Esprits.\n\nDépêchez-vous ! Cette émulsion ne restera pas puissante longtemps. Elle doit être livrée et utilisée au plus vite.", progress = "Avez-vous quelque chose de la part de l'Apothicaire Helbrim ?", completion = "Ah ! Les spores des Tarides que Helbrim recueillait. Il a requis votre aide pour me les livrer ? Bien.\n\nEt la puissance de l'émulsion est toujours maximale. Vous n'avez pas perdu de temps pour l'apporter. Bon travail, &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nElixir de Robustesse mineureElixir d'Agilité mineurePotion de régénération mineurePotion de rapidité\n\nVous recevrez également :\n\nTouille-chaudron"},
[854] = {title = "Un voyage à la Croisée", objective = "Parler à Thork, à la Croisée des Tarides.", description = "J'avais prédit votre arrivée, jeune <classe>. Bien que peut-être vous ne soyez plus si jeune.\n\nJe crois qu'il est temps de vous aventurer plus profondément dans ces terres. Je sens que vous êtes <destiné/destinée> à de grandes choses.\n\nC'est la Croisée que vous devez chercher à présent, dans la mesure où nos vies se sont mêlées à celles des orcs et qu'ils ont besoin de notre aide. Descendez cette route vers l'est et suivez-la vers le nord en direction de la Croisée. Trouvez Thork dans ses murs, il est béni par la Terre-mère.", progress = nil, completion = "Il est bon de voir que la plupart de nos alliés sont venus nous aider, d'aussi loin que Thunder Bluff. Une fois encore, je vous remercie, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[855] = {title = "Les bracelets de centaures", objective = "Apporter 15 Bracelets de centaures à Regthar Deathgate, à l'ouest de la Croisée.", description = "Les Kolkar représentent une menace pour les ambitions de la Horde dans les Tarides ; nous devons réduire leur nombre. De fait, j'ai une mission pour vous, en échange d'une récompense.\n\nAllez sur les terres des Kolkar, tuez leurs guerriers et récupérez des bracelets de centaures. Revenez quand vous en aurez un tas ; la Horde vous récompensera largement.", progress = "Comment se passe la chasse, <nom> ?", completion = "Joli travail. Il ne fait pas de doute que vous avez semé la peur dans le cœur des centaures survivants, &lt;nom&gt;. S'ils ont un tant soit peu d'intelligence, ils vont se calmer.\n\nMais je ne crois pas qu'ils s’arrêteront, et c'est bien malheureux.\n\nMalheureux... pour eux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc de bataille orcHache à pointeMarteau en bois de fer\n\nVous recevrez également :\n\n"},
[856] = {title = "<INUTILISÉ>", objective = "Descendre la route à partir du Camp Taurajo.\n\nTourner à gauche à l'intersection en T et continuer vers le nord.\n\nSuivre le chemin jusqu'au Sage Ancestral à l’extérieur de la Croisée.Bien que vous ayez atteint les Tarides, votre voyage n'est pas terminé. Vous devez le poursuivre jusqu'à la Croisée, où l'on a beaucoup besoin de vous.\n\nSuivez la route sur laquelle vous étiez, et tournez à gauche lorsque le chemin vous laisse le choix. Continuez vers le nord jusqu'à voir les murs de la Croisée.\n\nJuste avant d'entrer, rencontrez le Sage Ancestral, il vous dispensera quelques mots de sagesse.Vous recevrez :\n\n", description = "Bien que vous ayez atteint les Tarides, votre voyage n'est pas terminé. Vous devez le poursuivre jusqu'à la Croisée, où l'on a beaucoup besoin de vous.\n\nSuivez la route sur laquelle vous étiez, et tournez à gauche lorsque le chemin vous laisse le choix. Continuez vers le nord jusqu'à voir les murs de la Croisée.\n\nJuste avant d'entrer, rencontrez le Sage Ancestral, il vous dispensera quelques mots de sagesse.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[857] = {title = "La larme des lunes", objective = "Feegly l’Exilé veut que vous retrouviez pour lui la Larme des lunes.", description = "La puissance était mienne ! Dans mes propres mains ! Et je veux la retrouver ! La retrouver, je vous dis !\n\nCes fichus Excavateurs l'ont découverte… Elle était tellement belle. Avoir trouvé la Larme des lunes, c'était la première grande découverte qu'on avait faite à Bael Modan.\n\nElle aurait dû être mienne ! Mienne je vous dis !\n\nMais le général Twinbraid devint jaloux de la puissance qu'elle me donnait. Il l'a enfermée à clé dans le donjon. L'a traitée de maudite, il l'a fait ! L'imbécile !\n\nD'autres la voulaient et ils devaient être arrêtés ! Ce bâtard de Twinbraid m'a chassé.\n\nMaintenant, je la veux à nouveau ! Je la veux je vous dis !", progress = "Où est la Larme des lunes ? J'en ai besoin ! Maintenant ! Besoin je vous dis !", completion = "Enfin, la puissance est mienne à nouveau ! Mienne je vous dis !", rewards = "Vous recevrez :\n\n"},
[858] = {title = "Contact", objective = "Récupérer la Clé de contact et l'apporter à Wizzlecrank.", description = "Ce n'est sûrement pas Sputtervalve qui vous a <envoyé/envoyée> ? Je suis coincé ici. Je suis entré sans réaliser que j'avais besoin d'une clé pour déverrouiller la colonne de mouvement du déchiqueteur. L'un des autres opérateurs m'a demandé si tout allait bien, et j'ai paniqué ! Au lieu de lui dire que je n'avais pas la clé, je lui ai dit qu'il y avait un genre de problème mécanique.\n\nNous devons sortir d'ici au plus vite ! Montez à la salle de contrôle au sommet du derrick, le superviseur devrait avoir une clé pour ce déchiqueteur.\n\nSortez-moi de là !", progress = "Vite, nous devons filer d'ici avant que quelqu'un ne suspecte quelque chose !", completion = "Ouais, ça a l'air d'être la bonne clé. Laissez-moi juste m'assurer que j'arrive à m'en servir…\n\nHmmm… contrôle de la rotation… ça régule la vitesse et la stabilité… joli contrôle du mouvement du bras. Mais regardez ça ! Je ne peux pas croire que la KapitalRisk ait pu inventer quelque chose si supérieur au nôtre. Il faut que je ramène ça à Ratchet !", rewards = "Vous recevrez :\n\n"},
[860] = {title = "Sergra Darkthorn", objective = "Parler à Sergra Darkthorn, à la Croisée.", description = "Si vous souhaitez suivre la voie du chasseur, alors votre voyage vous mène jusqu'aux Tarides. Ses créatures sont robustes et féroces. Vous y apprendrez beaucoup en les traquant, et votre volonté grandira.\n\nParlez à Sergra Darkthorn. Elle sera votre premier guide dans les Tarides.\n\nElle se trouve à la Croisée. Pour l'atteindre, allez à l'est en partant du village Bloodhoof et en vous rendant dans les Tarides, puis allez au nord lorsque le chemin se sépare. Et attention tandis que vous voyagez. Les Tarides réservent de grands dangers pour ceux qui manquent de préparation ou de prudence.", progress = nil, completion = "Vous voulez chasser dans les Tarides ?\n\nVos yeux sont avides, et jeunes. Ils n'ont pas encore le tranchant de ceux qui traquent leurs proies à travers les plaines desséchées de ces terres.\n\nMais ne vous inquiétez pas. Nous allons renforcer et votre corps et votre esprit. Et nous vous apprendrons qu'il y a plus dans la chasse que simplement trouver et tuer votre gibier.\n\nPréparez-vous. Votre voyage commence. Maintenant.", rewards = "Vous recevrez :\n\n"},
[861] = {title = "La voie du chasseur", objective = "Apporter 4 Griffes de Rôdeurs des basses plaines à Melor Stonehoof à Thunder Bluff.", description = "Vous êtes avide d'explorations, ça se voit. J’avais aussi le désir d'explorer, autrefois…\n\nD'explorer, et de chasser. Car chasser est le plus grand honneur d'un tauren.\n\nSi vous désirez suivre cette voie, Melor Stonehoof peut vous y aider. Il est à Thunder Bluff, sur la Cime des chasseurs.\n\nPour lui prouver vos compétences et votre résolution, apportez-lui les griffes de Rôdeurs des basses plaines de Mulgore. Ils sont robustes et astucieux, une proie parfaite pour de jeunes <classe>s qui suivent la voie du chasseur.", progress = "Salutations. Vous avez une allure qui en dit long. Avons-nous des affaires en cours, vous et moi ?", completion = "Skorn Whitecloud est un &lt;race&gt; sage. Il a chassé pendant des années, et bien que son corps soit à présent vieux, son esprit brûle toujours avec force. Nous sommes honorés de l'avoir avec nous.\n\nSi Skorn vous a envoyé, alors vous devez posséder l'esprit du chasseur. Et les griffes que vous avez récupérées montrent de bonnes aptitudes.\n\nPeut-être êtes-vous prêt à parcourir le chemin.", rewards = "Vous recevrez :\n\n"},
[862] = {title = "Brouet de rat", objective = "Apporter 8 Rats fouisseurs à Boustiff' à l'est de la Croisée.", description = "Les <classe>s comme vous doivent plutôt avoir faim ici dans les Tarides. Moi, je crève la dalle tout au long de la journée.\n\nJe vais vous mitonner un chouette brouet. J'ai juste besoin de quelques rats fouisseurs.\n\nIl semble que ces sales nains de Bael Modan soient submergés par le festin favori de tout un chacun. À présent descendez vers le sud, à Bael Modan, et apportez-moi quelques rats fouisseurs.\n\nVous ne pouvez pas vous prétendre <aventurier chevronné/aventurière chevronnée> si vous n'avez pas passé du temps à tuer des rats ! Ha !", progress = "Z'avez éclaté assez de rats, <nom> ?", completion = "D'ordinaire je n'aime pas manger ces rongeurs quand ils sont si… si… verts. J'aime les laisser pourrir quelques semaines pour que le fumet ressorte vraiment. Mais vous avez l'air si affamé. Laissez-moi vous faire un bon brouet de rat. Et c'est parti...\n\nTenez, voilà pour vous.", rewards = "Vous recevrez :\n\nRecette : Brouet de ratBrouet de ratGants d'apothicaire"},
[863] = {title = "La fuite", objective = "Protéger Wizzlecrank et le Déchiqueteur gobelin volé jusqu'à Sputtervalve à Ratchet.", description = "Je suppose que j'apprendrai en le faisant… Ça ne devrait pas être trop difficile. Juste quelques boutons par-ci par-là, et un levier ou deux… Alors, êtes-vous <prêt/prête> à y aller ?", progress = nil, completion = "Avec un peu de chance nous pourrons tirer quelque chose d’intéressant de ce prototype brisé de déchiqueteur… Mon temps s'épuise ! Je vais envoyer au pas de charge une équipe de sauvetage où se trouve Wizzlecrank.\n\nOh ! Laissez-moi vous donner quelque chose pour le dérangement, également.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton de visionPantalon graisseux d'artisan\n\nVous recevrez également :\n\n"},
[864] = {title = "De retour vers l'Apothicaire Zinge", objective = "Apporter la Trousse d'analyse de terrain verrouillée à l'apothicaire Zinge à Undercity.", description = "\"Et voilà, la source d'énergie est enlevée et les données sont préservées. Bien, faites attention sur la route et tout ça. J'espère que cette horrible expérience s'est bien déroulée pour vous, blablabla…\"\n\nLe gobelin se détourne pour s'occuper des demandes de la Compagnie des eaux de Gadgetzan. Vous mettez la trousse d'analyse verrouillée à l'abri en vue du voyage de retour vers Undercity. Là-bas, l'apothicaire Zinge vous attend, vous et la trousse d'analyse de terrain verrouillée.", progress = "Soyez à nouveau le bienvenu. Ou du moins, je vous souhaite la bienvenue si vous revenez avec la Trousse d'analyse de terrain verrouillée. Dans le cas contraire, je prétendrai ne pas avoir remarqué votre totale incompétence et vous épargnerai ma rage jusqu'à ce que vous fassiez ce que vous avez à faire et que vous accomplissiez la quête que je vous ai confiée.", completion = "Je vais immédiatement analyser ces données. Peut-être que la folie de Keever s'avérera être mon génie après tout.\n\nQuant à vous… vous m'êtes utile, et je récompense très bien ceux qui restent utiles. Prenez cet objet, cette pièce, et plus important encore, mes remerciements qui les accompagnent.\n\nRevenez me voir de temps en temps - je mise sur le fait que notre collaboration sur ce projet n'est pas terminée.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de manipulation habileCape de maître apothicaireEpaulières de connaissance en cuir\n\nVous recevrez également :\n\n"},
[865] = {title = "Les cornes de raptors", objective = "Collecter 5 Cornes de raptors intactes prises sur des Faucheurs solécaille, et les apporter à Mebok Mizzyrix à Ratchet.", description = "Les raptors des Tarides sont plus malins que les autres. Et je pense que cette intelligence se trouve dans leurs cornes ! Si tel est vraiment le cas, alors je pourrais réduire leurs cornes en poudre et les utiliser pour en faire une \"potion d'intelligence\". Je pourrais en tirer une fortune !!!\n\nEt vous pouvez m'aider. Trouvez-moi des Cornes de raptors intactes sur des Faucheurs solécailles. Ils parcourent les Tarides septentrionales, et le nord des Tarides près de la frontière avec la forêt d'Ashenvale.", progress = "Avez-vous ces cornes, <nom> ? Ces trucs vont me rapporter une fortune !", completion = "Parfait, vous les avez ! Maintenant je n'ai plus qu'à les écraser, puis à les mélanger à une sorte de vin, à les faire macérer, puis aussi à...", rewards = "Vous recevrez :\n\nPunch du raptorCape d'aubergiste"},
[866] = {title = "Les échantillons de racines", objective = "Apporter 8 Echantillons de Racines à Mebok Mizzyrix, à Ratchet.", description = "Les herbes qui poussent dans les Tarides ne sont pas tout à fait pareilles à celles des autres contrées. Leurs propriétés sont à peu près semblables, mais l'eau des oasis les transforme légèrement. Elles sont juste un peu différentes.\n\nJ'aimerais étudier ces différences... pour voir si nous pouvons les exploiter !\n\nSi vous êtes <un herboriste compétent/une herboriste compétente>, cueillez les herbes que vous trouvez dans les Tarides. Apportez-moi ces échantillons que je puisse les comparer aux herbes des autres régions.", progress = "Salutations, <nom>. Avez-vous ces échantillons de racines ?", completion = "Oui, oui, elles sont très bien ! Je ferai pousser des herbes à partir de ces racines, puis je les étudierai. J'espère y trouver de nouvelles propriétés. Des propriétés cachées, de grande valeur…\n\nEt ne vous inquiétez pas, si j'en découvre vous serez le premier à le savoir. Car j'aurai besoin de quelqu'un pour en trouver plus.", rewards = "Vous recevrez :\n\nTunique couverte de spores"},
[867] = {title = "Les harpies pillardes", objective = "Collecter 8 Griffes d'Ensorçaile.\n\nLes apporter à Darsok Swiftdagger à la Croisée.", description = "Ces maudites harpies massacrent nos caravanes d'approvisionnement depuis trop longtemps déjà. Il est temps que nous tranchions quelques-unes de leurs gorges et que nous réduisions leur nombre.\n\nJ'ai jeté des coups d'œil discrets à leurs nids et j’ai compris leur hiérarchie. L'attaque la plus dévastatrice devra détruire une bonne partie de leur chaîne inférieure de commandement, pour que nous puissions ensuite remonter jusqu'au sommet.\n\nNous allons commencer en douceur. Tuez des harpies et des Volplumes Ensorçaile au nord-ouest, et apportez-moi 8 Griffes d'Ensorçaile. Ce sera bien pour commencer...", progress = "Vous en avez coupé assez ? Les tranches, bien fines s'il vous plaît. Et 8 Griffes d'Ensorçaile.", completion = "Oh elles sont parfaites ! Vraiment parfaites… Bon travail, &lt;nom&gt;. J'espère que vous nous donnerez encore d'excellents résultats à l’avenir.", rewards = "Vous recevrez :\n\n"},
[868] = {title = "La chasse aux œufs", objective = "Apporter 12 Œufs de silithide et la Griffe d'excavation à Korran, à la Croisée.", description = "Hé <nom> ! On m'a fait venir à la Croisée pour surveiller la zone et noter ce qui s'y déroule, pour mes maîtres à Orgrimmar.\n\nL'un de mes sujets d'étude est cette créature, ressemblant à un insecte, et que nous avons découverte au sud dans le Champ des géants. Nous savons peu de choses sur ces bêtes, alors je me fais un point d'honneur d'en découvrir plus. Elles semblent posséder quelque intelligence, plus que la plupart des simples animaux.\n\nPrenez cette griffe d'excavation et récupérez quelques œufs dans les tertres où vivent ces bêtes. Mais attention, si elles sont alertées par quoi que ce soit, elles vous attaqueront.", progress = "Faites attention aux œufs que vous découvrirez, <nom>. S'ils sont cassés, je n'en aurai pas l'usage.", completion = "Vous me plaisez, &lt;nom&gt;. Les œufs et l'outil. Bon travail.\n\nEt pour ce qui est de la récompense…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe bigarréeBroigne violette\n\nVous recevrez également :\n\n"},
[869] = {title = "Les raptors voleurs", objective = "Apporter 12 Têtes de raptor à Gazrog, à la Croisée.", description = "Il y a peu, une cargaison d'argent a été volée à notre tour de garde. Cet argent était destiné à payer les gardes de la Croisée, et nous voulons le récupérer.\n\nLe point étrange est que… nous avons arrêté un voleur la nuit même du vol. Et il s'agissait... d'un raptor ! Incroyable !\n\nJe ne sais pas quels raptors seraient intéressés par cet argent. Mais qu’importe ! Je veux qu’ils soient tués afin qu'ils ne nous volent pas à nouveau !\n\nPartez à leur recherche dans les Tarides et récupérez leurs têtes !", progress = "Avez-vous ces têtes, <nom> ?", completion = "Vous nous avez débarrassés des raptors !\n\nMerci, &lt;nom&gt;. J'apprécie les guerriers de valeur tels que vous.", rewards = "Vous recevrez :\n\n"},
[870] = {title = "Les Bassins oubliés", objective = "Rendre compte de vos découvertes à Tonga Runetotem.", description = "Il y a longtemps de cela, les Tarides étaient un endroit luxuriant, fourmillant de vie. Mais la guerre et le chaos ont ravagé la terre, l'ont brûlée et finalement laissée telle une bogue desséchée. Ainsi se sont passées les choses, et cela chagrine mon cœur.\n\nMais ces dernières années, de nouvelles oasis se sont formées dans les Tarides, et la vie frémit à nouveau. Et loin sous le sol, nous les druides sentons une puissance se frayer un chemin vers la surface.\n\nNous devons en trouver la source. Partez pour les Bassins oubliés, au nord-ouest de la Croisée. Parcourez les eaux et cherchez la source de cette puissance, puis revenez me voir.", progress = nil, completion = "Vous avez trouvé une fissure sous les eaux, dont il sort des bulles ? Etrange. Cela peut être une réponse à nos questions, mais nous ne pouvons pas encore le considérer comme certitude.\n\nEn tout cas, c'est un indice. Et vous avez ma reconnaissance pour l'avoir découvert.", rewards = "Vous recevrez :\n\n"},
[871] = {title = "Stopper les attaques des hurans", objective = "Dans la tribu Tranchecrin, tuer 8 Sourciers, 8 Tisseuses d’épines et 3 Chasseurs, puis retourner voir Thork.", description = "Tous les hurans sont nos ennemis, <nom>. Certains ne représentent simplement qu'une nuisance plus importante que les autres.\n\nLa tribu Tranchecrin a attaqué nos lignes d'approvisionnement en provenance de Durotar, nous causant des soucis sans nombre. J'ai des éclaireurs qui recherchent le chef de ces expéditions, mais en attendant, toutes les pertes que vous pourriez leur infliger nous seraient d'une grande aide.\n\nCommencez au nord-est, en direction de Durotar. Vous pouvez toujours repérer leurs tanières grâce aux ronces géantes qui sortent de la terre. Cherchez-les. Trouvez-les. Et tuez-les.", progress = nil, completion = "Vous avez bien œuvré, &lt;nom&gt;. Ces hurans insolents apprendront finalement que la puissance de la Horde ne peut être ignorée.", rewards = "Vous recevrez :\n\n"},
[872] = {title = "La perturbation cesse", objective = "Tuer 8 Géomanciennes Tranchecrin, 8 Défenseurs Tranchecrin et Kreenig Grondegroin.\n\nPuis apporter la Défense de Kreenig Grondegroin à Thork à la Croisée.", description = "L'un de mes éclaireurs a été témoin d'une attaque sur une caravane en provenance de Durotar, <nom>. Les coupables sont effectivement des hurans de la tribu Tranchecrin. L'un d’eux en particulier dirige les attaques : Kreenig Grondegroin. On l'a vu au nord-est d'ici, juste au sud de la route venant de Durotar. Pour régler le problème, Kreenig doit mourir.\n\nPour s'assurer que les attaques cessent, je suggérerais quand même que l'on fasse un exemple.\n\nTuez Kreenig et des membres de sa tribu, puis revenez me voir lorsque vous aurez sa Défense.", progress = "Coupez la tête de leur chef, et le chaos s'ensuivra, <nom>. Retenez bien cette leçon. Cela vous sera utile à l’avenir.\n\nLes marcassins vont patauger sans direction, et nous pourrons reprendre les Tarides.", completion = "Bon travail, &lt;nom&gt;. À présent que Kreenig est mort, les attaques sur nos caravanes vont clairement réduire.\n\nVotre peuple doit être fier de vous compter parmi eux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinturon de lienCeinture sanglée\n\nVous recevrez également :\n\n"},
[873] = {title = "Isha Awak", objective = "Apporter le Cœur d'Isha Awak à Mahren Skyseer.", description = "Le grand Isha Awak est le seigneur de ces eaux. Grande est sa force et solennelle est sa fierté. Les humains de la côte le craignent, car il en a occis beaucoup parmi eux.\n\nMais il ne me fait pas peur. Je suis reconnaissante de son existence. Il est un digne défi et une proie honorable.\n\nSi vous êtes <prêt/prête> alors partez nager et cherchez Isha Awak, le Destin des profondeurs.\n\nSon esprit demeure dans son cœur, et l'entendre battre, c'est voir votre destinée.", progress = "N'ayez pas peur des eaux, <nom>.", completion = "Vous faites à présent un avec Isha Awak, &lt;nom&gt;. Son esprit vous accompagne. Il se tapit dans vos yeux…\n\nDes yeux qui, un jour, apprendront à voir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâtonnet de flétrissureBouclier des vallons\n\nVous allez être la cible du sort suivant :\n\nForce de Isha Awak\n\nVous recevrez également :\n\nCeinturon de belluaire"},
[874] = {title = "Mahren Skyseer", objective = "Parler à Mahren Skyseer.", description = "Vous avez chassé les bêtes des Tarides. Votre esprit est fort. Mais un chasseur doit toujours être prêt. Un véritable chasseur doit être capable de traquer une proie sur n'importe quelle piste. Des montagnes ou des marais ne sauraient le rebuter.\n\nEt pas même la mer.\n\nAllez trouver ma soeur, Mahren. Elle chasse les grandes bêtes maritimes le long de la côte. Ce sera votre professeur.\n\nMais soyez <prudent/prudente> tandis que vous la recherchez, car la côte des Tarides est détenue par des humains.", progress = nil, completion = "Mon frère vous a envoyé, n'est-ce pas ? Alors vous avez dû lui montrer votre valeur. Si vous avez gagné le respect de Jorn, alors vous avez le mien également.\n\nÊtes-vous prêt à poursuivre votre chemin sur la voie du chasseur ?", rewards = "Vous recevrez :\n\n"},
[875] = {title = "Lieutenants harpies", objective = "Rassembler 6 Anneaux de lieutenant harpie sur des Tueuses Ensorçaile et les apporter à Darsok Swiftdagger à la Croisée.", description = "Ha ha ha ! <nom>. Vous en voulez encore ? Bien. J'aime entendre ça.\n\nCette fois-ci je veux que vous tuiez certaines des lieutenants harpies des Collines arides. Seules les Tueuses Ensorçaile peuvent être lieutenants, et vous pouvez les reconnaître à la bague qu'elles portent. C'est une vilaine bande, qui dirige beaucoup de subalternes dans le secteur. Tuer 6 d'entre elles portera un coup décisif à leur matriarcat.\n\nFaites en sorte qu'elles meurent dans la douleur, <nom>. Nous voulons montrer à ces femelles qu'il n'est pas sage de choisir la Horde comme adversaire.", progress = "Avez-vous déjà ces 6 Anneaux de lieutenant harpie ? Nous devons faire justice pour leurs attaques violentes sur la Horde.", completion = "Excellent travail mon ami. Je pense que vous progresserez loin au sein de la Horde.", rewards = "Vous recevrez :\n\n"},
[876] = {title = "Serena Plumesang", objective = "Tuer Serena Plumesang et apporter sa tête à Darsok Swiftdagger à la Croisée.", description = "Vous vous en êtes tellement bien <sorti/sortie> avec les lieutenants et autres harpies subalternes que j'aimerais que vous fassiez une dernière chose pour moi.\n\nSerena Plumesang est la sœur d'une harpie nommée Plumesang qui a été tuée par Rexxar il y a longtemps. Apparemment, ces attaques sur les caravanes de la Horde sont une vengeance pour la mort de sa sœur.\n\nJ'ai besoin que vous lui tranchiez la gorge et que vous me rapportiez sa tête. Je la placerai sur la prochaine caravane que nous enverrons... Histoire de donner aux harpies un sujet de réflexion.", progress = "Vous n'aurez rien tant que je ne verrai pas la tête de Serena.", completion = "Ah ! Bon travail, &lt;nom&gt; ! Très bon travail… Je n'étais pas sûr que vous en seriez capable, mais vous avez montré que vous êtes un coupe-gorge remarquable. Merci encore pour nous aider à soigner l'épidémie harpie. Voici votre récompense, utilisez-la bien.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nElégante épée courteEventreur de harpiesHache de Zhovur\n\nVous recevrez également :\n\n"},
[877] = {title = "L'oasis stagnante", objective = "Retourner voir Tonga Runetotem à la Croisée, après avoir enquêté à l'Oasis stagnante.", description = "Tout comme celle que vous avez trouvée aux Bassins oubliés, il se peut qu'il y ait des fissures dans les autres oasis des Tarides. Si tel est le cas, alors peut-être que ces fissures sont la source de vie des oasis.\n\nNous devons tester cette hypothèse.\n\nTenez, prenez ces graines. Elles sont mortes et stériles, mais emportez-les à l'Oasis stagnante, au sud-est. S'il y a une fissure là-bas, alors placez-y les graines... et observez.", progress = nil, completion = "Vos découvertes sont incroyables ! Les graines que je vous ai données étaient mortes. Ce qui gît sous ces oasis crée la vie à partir de rien !\n\nNous devons étudier cela plus profondément…", rewards = "Vous recevrez :\n\n"},
[878] = {title = "Tribus en guerre", objective = "Tuer 6 Sourciers Dos-hirsute, 12 Tisseurs d’épines Dos-hirsute et 12 Géomanciennes Dos-hirsute puis retourner auprès de Mangletooth au camp Taurajo dans les Tarides.", description = "Vous devez frapper mes ennemis <grogne>. Vous devez aider Mangletooth et les Tranchecrins en affaiblissant les Dos-hirsute Les deux tribus accordent beaucoup d'importance à la spiritualité et sont très liées à la terre et à ses pouvoirs <grogne>. Cela nous apporte de la force en tout, et pour la guerre en particulier.\n\nSi vous voulez découvrir qui a causé à Thork <grogne> et à la Horde un tel supplice, alors aidez Mangletooth ! Attaquez les chefs spirituels des Dos-hirsute au nord. Affaiblissez-les afin que les Tranchecrins puissent les vaincre et régner sur les Tarides.", progress = nil, completion = "Oui, oui… Rempli de joie parce que finalement &lt;grogne&gt; les Dos-hirsute connaissent la douleur de ma tribu, &lt;nom&gt;. C'est ce que je devrais ressentir,  mais ce n'est pas le cas.\n\nVous aidez votre peuple et il vous honore. Mangletooth aide son peuple et que font-ils ? Ils lui tournent le dos. Ils l'oublient et le laissent pourrir en cage !\n\nJe les aide même enfermé derrière ces barreaux et ils n'envoient personne à mon secours !", rewards = "Vous recevrez :\n\n"},
[879] = {title = "Une trahison de l'intérieur", objective = "Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mangletooth au Camp Taurajo dans les Tarides.", description = "Trois membres de ma tribu sont venus du Kraal pour diriger les raids contre la Horde, <nom> <grogne>. Ils sont brutaux et malins, et si vous parvenez à les vaincre, alors votre Croisée et même la plus grande partie des Tarides seront en paix... <grogne>.\n\nNak, Kuz et Lok Plaie-des-orcs sont ceux que vous recherchez. Ils se trouvent loin au sud des Tarides. L'un lance des sorts, l'autre est un pisteur, et leur chef, celui qu'on nomme Plaie-des-orcs <grogne> est un guerrier. Tuez-les, <nom>, tout comme ils m'ont tué.", progress = "Comment se passe votre chasse, <nom> ? \n\nThork pense savoir qui mène les raids contre son peuple, mais il verra combien il a tort si vous réussissez.\n\nMa mort est inéluctable, mais vous avez porté de rudes coups à mes ennemis, c'est pourquoi Mangletooth ne regrette rien.", completion = "Eh bien c'est fait. Mangletooth dit, mieux vaut que cela se termine ainsi &lt;grogne&gt;. Ils auraient dû &lt;grogne&gt; s'assurer que j'étais mort quand ils ont rebroussé chemin au lieu de me laisser &lt;grogne&gt; ici dans cette cage abandonnée.\n\nIl n'y a plus qu'une tâche à achever, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[880] = {title = "Source de vie", objective = "Apporter 8 Carapaces de Gueules d'acier altérées à Tonga Runetotem à la Croisée.", description = "Vos découvertes sont incroyables, <nom>. Ces oasis détiennent des propriétés qui doivent provenir d'une source extérieure. Ou peut-être intérieure.\n\nJe veux savoir comment ces fissures affectent les bêtes qui boivent aux eaux des oasis.\n\nChassez les gueules d'acier des oasis à l'Oasis luxuriante et à l'Oasis stagnante. Apportez-moi leurs carapaces pour que je les examine.", progress = "Comment progresse votre collection ? Avez-vous les carapaces ?", completion = "Merci, &lt;nom&gt;. Étudier les bêtes d'un secteur peut nous apprendre beaucoup sur le secteur lui-même. Nous allons voir ce que ces carapaces ont à dire.\n\nVeuillez accepter ma gratitude pour votre aide… Peut-être trouverez-vous une quelconque utilité à ces pièces. Je n'en vois pas pour ma part.", rewards = "Vous recevrez :\n\n"},
[881] = {title = "Echeyakee", objective = "Apporter la Peau d'Echeyakee à Sergra Darkthorn à la Croisée.", description = "Blanchebrume, Echeyakee dans la langue des taurens, est le roi des lions des savanes. Il chasse si furtivement qu’il est comme une brume légère et blanche sur la terre. Et il tue si vite que ses proies n'ont pas le temps d'avoir peur ni de souffrir.\n\nLes taurens disent qu'il est à la fois la miséricorde et la mort.\n\nVous apprendrez si cela est vrai, car je vous lance sur la trace d'Echeyakee. Son repaire est au nord-est de la Croisée, parmi les os des kodos géants.\n\nRendez-vous à son repaire, soufflez dans cette corne, et il viendra.", progress = "Le grand félin vous appelle, <nom>.", completion = "Vous avez vaincu Echeyakee, et bien qu'il ne chasse plus… son esprit vous accompagne. Il vous montrera la force de la subtilité, et l'honneur de la miséricorde.\n\nVotre chemin est encore long, jeune &lt;classe&gt;. Espérons que vous le parcouriez bien.", rewards = "Vous allez être la cible du sort suivant :\n\nGrâce de Echeyakee\n\nVous recevrez :\n\n"},
[882] = {title = "Ishamuhale", objective = "Apporter le Croc d'Ishamuhale à Jorn au Camp Taurajo.", description = "Ishamuhale, Lancecroc, est le plus redoutable des raptors solécaille. Il ne chasse pas pour se divertir, ni pour se nourrir. Il chasse par passion. Il tue car sa nature est de tuer.\n\nEt vous allez apprendre de cette nature, <nom>, car votre voie suit à présent les traces griffues d'Ishamuhale.\n\nCommencez la chasse. Tuez sa proie favorite, un zhévra, puis emmenez sa carcasse à l'arbre mort au nord-ouest de Ratchet. Ishamuhale sera attiré par l’odeur.\n\nSoyez <prêt/prête> lorsqu'il arrivera.", progress = "<nom>, avez-vous triomphé d'Ishamuhale ?", completion = "Le croc n'est qu'un simple gage, mais ce qu'il représente est plus profond.\n\nLa force d'Ishamuhale réside en vous à présent &lt;nom&gt;. Puissiez-vous l'utiliser avec tempérance. Ceci est votre fardeau. Ceci est votre honneur.", rewards = "Vous allez être la cible du sort suivant :\n\nRage de Ishamuhale\n\nVous recevrez :\n\n"},
[883] = {title = "Lakota'mani", objective = "Apporter le Sabot de Lakota'mani à Jorn au Camp Taurajo.", description = "Le Sabot de Lakota'mani est un symbole de la force du grand kodo.", progress = "<nom>, lorsque vous vous êtes approché j'ai perçu une nouvelle puissance en vous. Dites-moi : votre esprit a-t-il rencontré le grand Lakota'mani ?", completion = "Lakota'mani est appelé le \"Trembleterre\" dans notre langue, et ses pas sont tels le tonnerre incarné. Il est avec vous à présent, son courage se mêle au vôtre. Ensemble il ne se trouve pas de conflit auquel vous ne pouvez faire face.\n\nMarchez avec grandeur, &lt;nom&gt;. Marchez avec grandeur, le Trembleterre à vos côtés.", rewards = "Vous allez être la cible du sort suivant :\n\nTonnerre de Lakota'mani\n\nVous recevrez :\n\n"},
[884] = {title = "Owatanka", objective = "Apporter l'Epine caudale d'Owatanka à Jorn au Camp Taurajo.", description = "Lorsqu'on le touche, des étincelles jaillissent de l'épine caudale d'Owatanka.", progress = "<nom>, on peut lire une puissance nouvelle dans vos yeux ! Vous avez rencontré le puissant Owatanka, n'est-ce pas ?", completion = "Le lézard-tonnerre Owatanka est appelé \"Eclair bleu\" par les taurens, car en lui réside une vitesse qui dément sa taille. On raconte que la foudre a frappé Eclair bleu il y a longtemps de cela et que, nourrie par la fureur du ciel, l'énergie de la grande bête est sans limite.\n\nPuisse cette puissance couler en vous, &lt;nom&gt;. Car vous allez à présent à l'allure d'Owatanka.", rewards = "Vous allez être la cible du sort suivant :\n\nRapidité d'Owatanka\n\nVous recevrez :\n\n"},
[885] = {title = "Washte Pawne", objective = "Apporter la Plume de Washte Pawne à Jorn Skyseer au Camp Taurajo.", description = "La Plume de Washte Pawne est douloureuse au toucher.", progress = "Il y a une nouvelle fermeté en vous, <nom>. Une fermeté née de la douleur…\n\nÊtes-vous accablé par la mort de Washte Pawne ?", completion = "Le faucon-tonnerre est rare dans les Tarides, et sa mort présage une grande fortune ou une grande malédiction.\n\nMais Washte Pawne, appelé le \"Rongeur d'esprit\" en taurahe, n'apporte rien, ou bien les deux.\n\nLa douleur que vous avez ressentie en le chassant est le remords que chacun ressent lorsqu'il gagne beaucoup en perdant beaucoup. La douleur ressentie est celle du regret.\n\nMais je vois que vous l'avez conquise. Vous avez appris que le regret devient sagesse et que la douleur rend plus fort.\n\nVous avez beaucoup appris, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nRésolution de Washte Pawne\n\nVous recevrez :\n\n"},
[886] = {title = "Les oasis des Tarides", objective = "Parler à Tonga Runetotem à la Croisée.", description = "Les druides de Thunder Bluff sentent une étrange puissance qui fuit dans les Tarides, à l'est de Mulgore.\n\nNous avons envoyé Tonga Runetotem pour enquêter sur la source de cette puissance, mais nous craignons qu'il ait besoin d’aide.\n\nVoyagez jusqu'aux Tarides et parlez à Tonga. Il sera à la Croisée. Pour atteindre cet endroit, prenez la route à l'est en sortant du village Bloodhoof. Entrez dans les Tarides, puis tournez vers le nord lorsque la route se divise. Continuez dans cette direction et vous trouverez la Croisée.\n\nEt ne quittez pas la route, <nom>, car les Tarides sont hostiles.", progress = nil, completion = "Mes frères à Thunder Bluff ont été avisés de vous envoyer, jeune &lt;classe&gt;. Car le mystère des Tarides ne peut être résolu par moi seul.\n\nAvec votre aide, espérons que nous trouverons des réponses à nos questions.", rewards = "Vous recevrez :\n\n"},
[887] = {title = "Les flibustiers des Mers du sud", objective = "Tuer 12 Brigands et 6 Canonniers des Mers du Sud pour Gazlowe de Ratchet.", description = "J'aurais vraiment souhaité que le vice-amiral Grezzlik fasse un meilleur travail pour que nos navires marchands puissent sillonner les mers en toute sécurité. Avec tout l'or que les princes marchands ont versé, voir autant de pirates attaquer mes navires et voler mes marchandises me rend malade !\n\nJ'ai entendu dire que les Flibustiers des Mers du Sud ont établi un camp juste au sud d'ici. Ils ont été une source d'irritation constante et si Grezzlik ne s'en occupe pas, alors, vous, peut-être, pourriez m'en débarrasser.", progress = nil, completion = "Bon travail, gamin. Encore un boulot comme celui-là et j'aurai un souci de moins. Espérons que cela suffise à les persuader d'établir leur base ailleurs.\n\nEntre-temps, il reste le petit problème qui est de récupérer les marchandises volées.", rewards = "Vous recevrez :\n\n"},
[888] = {title = "Course à la lentille", objective = "Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazlowe de Ratchet.", description = "J'aimerais récupérer toutes mes marchandises. Hélas, je suis sûr que ce n'est pas possible. Mais il y a des choses que je dois absolument récupérer !\n\nComme vous pouvez le constater, mon observatoire est prêt à fonctionner, mais il manque la plus petite des deux lentilles. La première est arrivée de Durotar par caravane, mais la deuxième a été envoyée par bateau, et elle ne m'est jamais parvenue ! Je n'ai pas non plus reçu mes bottes de chez Drizzlik à Baie-du-Butin !\n\nPartez pour le camp des pirates, et voyez si vous les trouvez.", progress = "Avez-vous trouvé, <nom> ?", completion = "C'est un tel soulagement de les recevoir, aussi merci pour votre aide, &lt;nom&gt;. Vous savez, je pourrais utiliser quelqu'un comme vous pour donner un coup de main à mon opération, ici. Si jamais vous cherchez du travail, &lt;nom&gt;, n'oubliez pas la façon dont Gazlowe paye bien les services rendus.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de randonnéeBottes de lamelles matelassées\n\nVous recevrez également :\n\n"},
[889] = {title = "L'esprit du vent", objective = "Apportez 10 Joyaux de sang à Mangletooth et je vous doterai d'une vitesse impressionnante. Vous courrez avec les zhévras et le vent vous jalousera.\n\nCela ne durera pas longtemps, mais cela devrait suffire à vous faire traverser les Tarides.", description = nil, progress = "Apportez 10 Joyaux de sang à Mangletooth et je vous doterai d'une vitesse impressionnante. Vous courrez avec les zhévras et le vent vous jalousera.\n\nCela ne durera pas longtemps, mais cela devrait suffire à vous faire traverser les Tarides.", completion = "Bien. Que l'esprit d'Agammagan vous guide, &lt;nom&gt;. Revenez me voir si vous désirez davantage de la magie d'Agammagan.", rewards = "Vous apprendrez :\n\nL'esprit du vent"},
[890] = {title = "La livraison perdue", objective = "Apporter le Grand Livre de Gazlowe au Maître des quais Dizzywig.", description = "J'ai attendu durant une éternité l'arrivée de mon dernier chargement de marchandises de Baie-du-Butin ! Je suis à peu près sûr qu'il a dû être volé par les Flibustiers, mais pour que je le sois complètement, pourriez-vous descendre du côté des docks et demander à Dizzwig si mes marchandises ont déjà été livrées à mon entrepôt sans que je le sache ?\n\nTenez, descendez mon Grand livre à Dizzwig et demandez-lui de vérifier à nouveau mes inventaires par rapport à ses registres.", progress = "Des marchandises à envoyer par le prochain bateau, <nom> ?", completion = "Ah ! Ainsi c'est Gazlowe qui vous envoie. Juste une minute, laissez-moi vérifier mes propres registres pour m'assurer que les biens de Gazlowe n'ont pas été envoyés au mauvais endroit.\n\nJe parie qu'il attend les bottes de chez Drizzlik...", rewards = "Vous recevrez :\n\n"},
[891] = {title = "Sous le feu de l'ennemi", objective = "Le capitaine Thalo'thas Brightsun de Ratchet veut que vous collectiez 10 Médailles de Theramore et que vous tuiez le Capitaine Fairmount, le Canonnier Whessan et le Canonnier Smythe.", description = "J'ai encore perdu un navire contre ces humains trop zélés du Fort du Nord !\n\nNous devons nous occuper de ces bâtards. Leur paranoïa les met dans un état de totale frénésie. Ces gâchettes faciles, ces rustres insouciants canardent tout ce qui passe dans leur ligne de mire.\n\nPartez vers le sud, le long de la Côte des marchands, vers le Fort, et persécutez-les. Apportez les médailles de leurs soldats comme preuve. Et pour l'amour de ma flotte marchande, tuez le capitaine Fairmount et ses canonniers trop enthousiastes.", progress = "Ma flotte est en danger tant que le capitaine Fairmount et ses fichus canonniers canardent tout ce qu'ils voient depuis le Fort du Nord. Je veux que ses soldats paient également. Remplissez mes mains des médailles de leurs morts et je saurai que mes hommes ont été vengés.", completion = "Hélas ! Les canons de la vertueuse Alliance sont réduits au silence... Vous serez récompensé pour votre aide, &lt;nom&gt;.\n\nOccupons-nous à présent de la bien triste tâche de retrouver le corps des morts...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMousquet de corsaireCulotte du loup de mer\n\nVous recevrez également :\n\n"},
[892] = {title = "La livraison perdue", objective = "Rapporter le Grand Livre de Gazlowe à Gazlowe à Ratchet.", description = "Tout a l'air correct selon mes registres, <nom>. Retournez-y et dites à Gazlowe que sa chance a tourné. Je ne serais pas surpris que les pirates aient pris ses marchandises.\n\nJe ne peux rien faire d'autre pour lui. Oh !… Vous pourriez lui dire quand même que j'ai quelque chose venant d'Undermine à son nom, s'il peut faire un saut pour le chercher.", progress = "Alors, qu'est-ce que Dizzywig a à dire ?", completion = "C'est non, hein ? Je suppose que c’est un coup des Flibustiers, alors… Dizzywig est réglo, je suis sûr qu'il ne me ferait pas d'entourloupes.\n\nAprès tout, son nom est sur la fiche de paie.\n\nIl semble que j'ai de la marchandise à récupérer, &lt;nom&gt;. Qu'en dites-vous ?", rewards = "Vous recevrez :\n\n"},
[893] = {title = "Des armes de choix", objective = "Apporter un Poignard de Tranchecrin, une Baguette Tranchecrin carbonisée et un Bouclier Tranchecrin à Tatternack Steelforge au camp Taurajo dans les Tarides.", description = "Les hurans Tranchecrin, au sud, au-delà du Champ des géants, n'ont pas de forgerons compétents, que je sache. Mais ils ont apparemment commencé à construire des armes plus solides. J'aimerais mettre la main sur différents types de ces armes pour acquérir leurs techniques, si possible.\n\nSi vous souhaitez œuvrer pour l'honneur de la Horde, apportez-moi des exemples de leurs armes. Obtenez une dague de leurs traqueurs, une baguette de leurs prophètes, et un bouclier de leurs frénétiques. Cela devrait parfaitement faire l'affaire.", progress = "J'ai, moi aussi, des doutes quant à l'éventualité de voir ces hurans pathétiques atteindre un quelconque niveau de qualification dans le domaine de la forge, mais j'obéis aux ordres du chef de guerre. J'apprendrai ce que je peux de la tribu Tranchecrin.\n\nJ'ai connu des tâches plus ingrates, et je le ferai volontiers dans l'intérêt du peuple orc.", completion = "Magnifiques, ces échantillons sont vraiment magnifiques !\n\nLes hurans sont plus évolués que je ne le pensais.\n\nTenez, &lt;classe&gt;, prenez ceci et laissez-moi seul. Je ferais mieux de regarder plus attentivement ces armes. Il se peut que nous ayons sous-estimé notre ennemi, et c'est le genre d'erreur que nous ne pouvons nous permettre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau de démolitionLanterne éternelle\n\nVous recevrez également :\n\n"},
[894] = {title = "Samophlange", objective = "Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk.\n\nObjet fourni : \n", description = "La KapitalRisk a construit un petit centre de recherches loin au nord, au sud-ouest de la Videfange. Je ne sais pas vraiment ce qu'ils y font, mais j'ai quand même réussi à découvrir qu'ils font des expériences avec quelque chose qu'ils appellent \"Samophlange\".\n\nÀ présent, que diable est le Samophlange ? Eh bien, quoi que ce soit, je veux l'examiner, et j'ai besoin que quelqu'un le prenne.\n\nJ'ai réussi à obtenir une copie de leur Manuel de la console de contrôle, vous devriez ainsi comprendre comment en désengager le Samophlange.", progress = nil, completion = "Une grande variété de boutons, de leviers et de lumières clignotantes sont placés d'une manière quelque peu fantaisiste sur le devant de la console de contrôle. Une petite jauge indique que l'appareil est en marche en ce moment, à ses niveaux optimaux, et que les valves de contrôle 1 à 3 sont ouvertes. Il y a une petite serrure située dans le coin inférieur droit du panneau de contrôle.", rewards = "Vous recevrez :\n\n"},
[895] = {title = "ON RECHERCHE : baron de Longrivage", objective = "Apporter la tête du baron de Longrivage à Gazlowe à Ratchet.", description = "ON RECHERCHE !\n\nBaron de Longrivage, capitaine de \"l'Insouciant\".\n\nLe capitaine Longrivage de Gilnéas commande des navires pour le compte des Flibustiers des Mers du sud, il est recherché pour actes de piraterie. Ses restes doivent être identifiables !\n\nGazlowe", progress = "Que se passe-t-il ? Je peux vous aider ? Des marchandises à expédier ou peut-être un travail d'ingénierie ?", completion = "Ah ! Ce genre d'affaires. Vous savez, j'ai vu une fois \"l'Insouciant\" en haute mer… Un bateau redoutable, ou est-ce un vaisseau… Ces marins sont si pointilleux !\n\nMais passons, le voir glisser sur l'eau était une vision inoubliable. Je suis heureux que son tristement célèbre capitaine ne dérange plus mes navires.", rewards = "Vous recevrez :\n\n"},
[896] = {title = "La bonne fortune d'un mineur pauvre", objective = "Prendre l'Emeraude œil-de-chat à l'un des Surveillants ou l'un des Massacreurs de la KapitalRisk pour le Maître des quais Dizzywig à Ratchet.", description = "Etant Maître des quais d'un port plein d'activité comme Ratchet, je prends toujours le pouls de l'information. Je sais tout des échanges de biens et d'argent entre ici et Baie-du-Butin.\n\nLa dernière nouvelle que j'ai entendue concerne la mine des Pierriers de la KapitalRisk, au nord-est de la Videfange. L'un des mineurs y a découvert une émeraude aussi grosse que votre poing. Je connais quelques acheteurs qui voudraient mettre la main sur un tel joyau, et je suis prêt à faire 50-50.", progress = "Si seulement nous savions quel mineur a trouvé l'émeraude, ce serait une promenade de santé.", completion = "Regardez donc la taille de cette chose, &lt;nom&gt; ! Nous allons devenir riches ! Voyons, d'après le prix des gemmes en partance pour Undermine, je devrais pouvoir calculer votre part. Cinquante pour cent, ne vous inquiétez pas !\n\nÀ présent allons-y… Je pense que cela devrait faire le compte. Un plaisir de faire des affaires avec vous, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nUn sac de pièces"},
[897] = {title = "Le Moissonneur", objective = "Apporter la Tête du Moissonneur à Jorn Skyseer.", description = "Cette étrange créature, qui ressemble à un insecte, n'a pas l'air de faire partie de l'ordre naturel, comme si elle n'appartenait simplement pas aux Tarides.", progress = "Vous avez l'air soucieux, <nom>. Comment se déroulent vos leçons dans les Tarides ? Avez-vous découvert quelque chose de préoccupant ?", completion = "Je ne peux rien dire de la nature de cette bête, car son esprit s'est enfui. Mais comme vous l'aviez supposé, elle n'appartient pas aux Tarides. Je crains que cela n’annonce un avenir bien lugubre pour notre peuple… Mais pour l'heure, préparez-vous, et espérons que le temps éclaircisse le mystère posé par l'existence de cette créature.", rewards = "Vous recevrez :\n\n"},
[898] = {title = "Hors du fort", objective = "Escorter en toute sécurité Gilthares Firebough jusqu'au capitaine Brightsun à Ratchet.", description = "Enfin ! Quelqu'un est venu me sauver !\n\nIl est incroyable que vous ayez passé les gardes. Ces fanatiques de Theramore sont devenus fous. Ils ont coulé notre navire et m'ont emprisonné. Je suis le seul survivant. Ils ont dit que j'étais leur ennemi et un danger pour l'Alliance.\n\nMoi ! Un danger pour leur parodie d'Alliance ? J'étais matelot sur un transport de gnôle entre Ratchet et Baie-du-Butin.\n\nMais assez parlé. Aidez-moi à retourner à Ratchet, voulez-vous ? Dites-moi lorsque vous serez <prêt/prête> et nous prendrons la fuite.", progress = "Oui ?", completion = "Et dire que nous pensions que Firebough était mort depuis longtemps !\n\nVos actes héroïques vous valent une place d'honneur parmi les corsaires de Thalo'dan, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes sangléesGantelets à rivets\n\nVous recevrez également :\n\n"},
[899] = {title = "Consumé par la haine", objective = "Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée.", description = "Connaissez-vous l’affliction du doute, <classe> ? Sachez seulement que je suis là toute la journée à scruter l’horizon pour repérer ces monstres. J’ai tué chaque homme-sanglier que j’ai rencontré depuis, mais ma soif de sang est loin d’être étanchée. Peut-être qu’au lieu d’aller au nord, vers la Croisée, j’aurais dû me diriger sur Taurajo.\n\nVous, <classe>, vous pourriez m’aider.\n\nTuez-en autant que vous pourrez. Apportez-moi leurs défenses et nous boirons ensemble à leur destruction.", progress = "Les hurans paieront pour cela, <nom>. Je vous le jure.", completion = "Vous avez pris au sérieux la tâche que je vous avais confiée et je vous en remercie, &lt;classe&gt;.\n\nBien que mon désir de revanche demeure, je suis satisfait de savoir que ces hurans aient souffert eux aussi.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de chasseur de sanglierEcharpe de la prairie\n\nVous recevrez également :\n\n"},
[900] = {title = "Samophlange", objective = "Fermer la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utiliser à nouveau la console de contrôle.", description = "Les trois valves de contrôle sont à présent ouvertes. Les indications sur le panneau de contrôle vous amènent à penser qu'elles doivent être fermées pour que l'appareil puisse être arrêté.", progress = "Des lumières clignotant sur la console de contrôle indiquent que les valves de contrôle principales ne sont pas fermées.", completion = "L’intensité des lumières correspondant aux trois valves de contrôle décline tandis qu'elles sont fermées. Les lumières vertes passent au jaune, et l'on peut à présent utiliser la commande contrôlant l'appareil. Les valves étant désormais fermées, il peut être éteint.", rewards = "Vous recevrez :\n\n"},
[901] = {title = "Samophlange", objective = "Obtenir la Clé de la console de l'artisan Sniggles, puis l'utiliser sur la console de contrôle.", description = "Maintenant que l'appareil est désactivé, le panneau de contrôle peut s'ouvrir et on peut sortir le Samophlange de la console. À présent que tout est en place, il reste à trouver la clé qui déverrouillera la console.", progress = "Les lumières de la console faiblissent, les jauges et les cadrans retournent à leurs positions neutres, tous les mouvements ralentissent.", completion = "Alors que vous tournez la clé dans la serrure, la console de contrôle se déverrouille. Une lumière rouge s'éteint en haut de la console, et toute énergie vide le terminal.", rewards = "Vous recevrez :\n\n"},
[902] = {title = "Samophlange", objective = "Rapporter le Samophlange à Sputtervalve à Ratchet.", description = "Ouvrir la console de contrôle révèle des entrelacs de fils, de tubes et d'autres objets mécaniques étranges, dont la plupart ne semblent avoir aucune utilité. En les écartant et en fouillant au fond le la console, vous découvrez le Samophlange. Vous le retirez d'un coup sec de son réceptacle.", progress = "Oh ! Vous êtes de retour, <nom> ! Avez-vous le Samophlange ?", completion = "C'est… euh… intéressant… Je ferai en sorte qu'il soit envoyé au quartier général du Syndicat des Artisans à Undermine. Je suis sûr qu'après une dissection prudente et beaucoup de recherches, ils parviendront à y comprendre quelque chose.\n\nMais je vais peut-être d'abord y jeter un œil moi-même...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau d'ingénieurBouclier soudé\n\nVous recevrez également :\n\n"},
[903] = {title = "Les rôdeurs des Tarides", objective = "Collecter 7 Griffes de Rôdeur des savanes pour Sergra Darkthorn à la Croisée.", description = "Il est temps à présent de courir après quelque chose qui mord vraiment. Les rôdeurs des Tarides sont une espèce résistante. Résistante, pleine de ressources, sournoise… et mortelle. Vous les trouverez parmi les herbes hautes. Ils sont nombreux au sud-ouest de la Croisée.\n\nSoyez <prudent/prudente> tandis que vous les chassez, <nom>, ou vous ne serez plus <le prédateur/la prédatrice>, mais bien la proie.", progress = "Comment se déroule votre chasse, <nom> ? Avez-vous trouvé les rôdeurs ?", completion = "Ah, je vois que vous avez été occupé à vous tapir dans les herbes pour chasser les rôdeurs. Croyez-vous alors qu'il est temps de combattre un champion parmi eux ?", rewards = "Vous recevrez :\n\n"},
[904] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[905] = {title = "Les Faucheurs furieux", objective = "Tuer des raptors solécaille et récupérer leurs plumes. Placer ces plumes dans les 3 nids de Faucheurs solécaille, puis retourner voir Sergra Darkthorn à la Croisée.", description = "À présent, <nom>, la chasse devient plus difficile. Vous devez battre votre proie, et trouver le chemin jusqu'à son repaire.\n\nChassez les raptors solécaille au sud. Tuez-les et enlevez leurs plumes. Placez les plumes dans les nids des Faucheurs au sud-ouest de l'oasis stagnante. Montrez à leurs semblables que vous ne les craignez pas !", progress = nil, completion = "Ainsi vous vous êtes rendu aux nids et vous y avez placé les plumes de vos proies. Cela a nécessité beaucoup de courage, c'est certain.\n\nVous sentez-vous un peu plus fort, &lt;nom&gt; ? Car il me semble que vous l'êtes plus que lors de votre première visite. Je crois que les Tarides accomplissent leur œuvre.", rewards = "Vous recevrez :\n\n"},
[906] = {title = "Une trahison de l'intérieur", objective = "Apporter le Crâne de Lok à Thork à la Croisée des Tarides.", description = "Apportez la tête de Lok à Thork à la Croisée, <nom> <grogne>. Il devrait savoir ce qu'il est advenu de ma tribu sans le moindre mot--ha, mais je ne m'attends pas à ce qu'il croie que Mangletooth y a <grogne> contribué. Mais il est certain qu'il vous récompensera pour vous être <occupé/occupée> de tels actes <reniflement>.\n\nJe vais continuer à vous bénir du pouvoir d'Agammagan aussi longtemps que je resterai dans cette cage, <nom>. Jusque-là, adieu.", progress = "Oui ? Qu'est-ce que c'est ?", completion = "Vous avez trouvé le chef des Tranchecrins et l'avez tué vous-même, &lt;nom&gt; ? Stupéfiant.\n\nLes mots me manquent, mais cela ne veut pas dire que je suis un ingrat. Les gens de la Croisée feraient bien de respecter votre force.\n\nJe dois l'admettre, je croyais que le chef de ces raids sur nos lignes d'approvisionnement était un autre huran. Merci encore, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTunique de nacrécorceTunique de mousse sèche\n\nVous recevrez également :\n\n"},
[907] = {title = "Les lézards-tonnerre enragés", objective = "Apporter 3 doses de Sang de lézard-tonnerre à Jorn Skyseer, à Camp Taurajo.", description = "À présent, <nom>, vous devez combattre les grands lézards-tonnerre. Ces bêtes sont si imposantes que le sol tremble lorsqu'ils parcourent les plaines. Prenez garde lorsque vous les combattez, car un faux pas peut vous jeter directement sous leurs pattes.\n\nVous trouverez les lézards-tonnerre au sud des Tarides. Ils sont connus sous les noms de Groins-tempête, Orageux et Têtes-tonnerre. Revenez me voir lorsque vous les aurez vaincus.", progress = "Avez-vous battu les lézards-tonnerre, <nom> ?", completion = "Il est bon de vous voir revenir avec la preuve de votre victoire. Et il est bon de savoir que vous y êtes parvenu sans vous briser les os.", rewards = "Vous recevrez :\n\n"},
[908] = {title = "Parmi les ruines", objective = "Apporter le Noyau de la Brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", description = "Le Marteau du crépuscule s'est déplacé dans les ruines d'Ecrin-de-Lune des Profondeurs de Brassenoire. Leur présence forcera les élémentaires à travailler contre nous. Si nous ne nous occupons pas de cette région, ils en prendront complètement le contrôle.\n\n<nom>, allez à Brassenoire et trouvez la pierre de la brasse. Elle devrait se trouver quelque part, à proximité, dans l'eau. À l'intérieur, se trouve un Noyau de la Brasse, un objet qui, s'il est utilisé correctement, offrira un historique de toute l'activité des élémentaires. Si je l'avais, je pourrais, avec l'aide du Cercle terrestre, faire quelque chose pour les arrêter !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[909] = {title = "Baron Aquanis", objective = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", description = "Sur l'élémentaire d'eau vaincu, vous trouvez un étrange globe d'eau. Vous avez la nette impression que l'objet a absorbé l'énergie de la créature. À l'intérieur du globe, vous discernez une eau aux reflets malsains. Le globe lui-même semble insensible à toute forme d'action physique.\n\nS'il y a une personne qui puisse comprendre ce qu'est cet objet, cela ne peut être que Je'neu Sancrea du Cercle terrestre. Il se trouve dans l'avant-poste de Zoram'gar de la Horde, à Ashenvale.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nSabre des hors-la-loiDoigt de la sorcière\n\nVous recevrez également :\n\n"},
[910] = {title = "Un tour sur les quais", objective = "Emmenez votre protégé sur les quais de Ratchet, dans les Tarides.", description = "J'ai entendu parler des grands bateaux qui naviguent entre Ratchet et Baie-du-Butin ! C'est génial de voyager sur l'océan et de faire de grandes batailles navales. Peut-être que je serai un puissant marin de la Horde quand je serai grand ! Ouais !\n\nVous voulez bien m'emmener voir les quais de Ratchet, s'il vous plaît ? Je vous promets que je sauterai pas dans l'eau et que je ne ferai pas de bêtise. Je veux juste voir les grands bateaux et sentir l'eau salée de la mer ! Ouais !", progress = nil, completion = "Ouah, l'océan est IMMENSE ! Il y avait beaucoup de mouettes et des tas de trucs... C'était aussi bruyant et animé que je le pensais. Et avec aussi des pirates pas loin... Trop délire !\n\nMerci de m'avoir emmené à Ratchet, &lt;nom&gt;. C'était génial !", rewards = "Vous recevrez :\n\n"},
[911] = {title = "L'accès vers la frontière", objective = "Emmenez votre protégé au Rempart de Mor'shan dans la région nord des Tarides, juste à l'entrée d'Ashenvale.", description = "Ils disent qu'Ashenvale est la nouvelle frontière, et que le Rempart de Mor'shan dans les Tarides est à sa porte. Ça doit être génial d'être un pionnier, de trouver tout ce dont on a besoin dans la nature sauvage ! Ils disent que c'est là que la Horde et l'Alliance se battront le plus dans l'avenir, et je veux y être, <nom> !\n\nVous voulez bien m'emmener au Rempart de Mor'shan pour que je puisse voir à quoi ressemble la frontière, s'il vous plaît ? Je veux voir l'endroit où la Horde chasse ces sales elfes de la nuit puants !", progress = nil, completion = "Ouah, Ashenvale, c'est là où commence la grande aventure ! Vous vous êtes déjà battu en Ashenvale, &lt;nom&gt; ? Quand je serai devenu un héros, quand je serai grand, je veux venir en Ashenvale pour me battre pour la gloire de la Horde!\n\nMerci de m'avoir emmené à la frontière, &lt;nom&gt;. Vous êtes le meilleur !", rewards = "Vous recevrez :\n\n"},
[912] = {title = "Le costume de trogg Brisepierre", objective = "Vous recevrez :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nConnaissance : déguisement de Brisepierre"},
[913] = {title = "Le cri du faucon-tonnerre", objective = "Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Skyseer, au Camp Taurajo.", description = "Le faucon-tonnerre, <nom>, est une bête féroce. Il est temps pour vous d'en affronter. Vous devez trouver où il rôde, puis m'apporter ses ailes comme preuve de votre chasse fructueuse.\n\nParvenez-y, et l'heure de notre séparation sonnera bientôt.", progress = "Alors, est-ce fait ? Avez-vous tué le faucon-tonnerre ?", completion = "Vous, tout comme le faucon-tonnerre, devriez être fier. Vous avez vaincu tous les ennemis que nous avons placés sur votre chemin, et l'avez fait avec force, courage, et honneur.\n\nMais la voie que vous avez empruntée, &lt;nom&gt;, ne s'arrête pas là. En fait, vous découvrirez que les véritables chasseurs s'efforcent de constamment poursuivre cette voie avec la même fierté que celle que vous avez montrée.\n\nIl est temps à présent de se remettre en route.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge en cobaltBâton du cavalier céleste\n\nVous recevrez également :\n\nGants de la lune"},
[914] = {title = "Les druides du Croc", objective = "Apporter les Gemmes de Cobrahn, d'Anacondra, de Pythas et de Serpentis à Nara Wildmane à Thunder Bluff.", description = "Les druides des Cavernes des lamentations, les druides du Croc, sont une aberration. Ils appartenaient à un ordre de druides nobles voulant soigner les Tarides, mais ils tentent maintenant de plier cette terre à leurs fantasmes.\n\nIls ont quatre chefs, et chacun possède une gemme de rêve. Même à présent, leurs visages me hantent ! Vous devez les tuer et m'apporter les gemmes. Ces terres pourront peut-être ainsi connaître à nouveau la paix.\n\nAllez, <nom>. Vous les trouverez, tapis, au fond des Cavernes des lamentations.", progress = "Les réminiscences de mes cauchemars me hantent, <nom>. Avez-vous battu les chefs des druides du Croc et pris possession de leurs gemmes ?", completion = "Vous avez réussi, &lt;nom&gt;. Vous avez tué les chefs des druides du Croc. Mes rêves sont à présent libérés de leurs visages malfaisants, et vous avez aidé à sauver les Tarides d'un avenir bien lugubre.\n\nJe vous remercie, &lt;nom&gt;. Je vous remercie en mon nom, celui des druides de Thunder Bluff, et au nom de la Terre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton au croissantLame ailée\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[915] = {title = "Je veux une glaaaaace !", objective = "Aller chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor.", description = "DE LA GLACE ! Oh, s’il vous plaaaaîîîîîît, je peux avoir de la glace ?! La glace à la fraise est ma glace préférée, et la meilleure glace à la fraise du monde, c’est celle d’Aguilor ! C’est ma glace préférée dans le monde entier !\n\nJ’en ai mangé il y a longtemps aux courses des Salines, mais il paraît qu’ils en vendent en ville ! S’il vous plaît ? S’il vous plaaaaîîîîîît ? Avec une deuxième boule sur le dessus ??!?!", progress = "J'aimerais bien qu'ils fassent d'autres parfums de glace que la fraise. Mais j'ai de la chance, la glace à la fraise est ma préférée !", completion = "Mmmmmmmmm ! J'adore leur glace à la fraise ! S'il y a bien une chose qu'Aguilor &amp; Dagharn savent faire, c'est la crème glacée !\n\nMerci beaucoup &lt;nom&gt;, je n 'ai jamais rien mangé d'aussi bon !", rewards = "Vous recevrez :\n\n"},
[916] = {title = "Le venin des Tissebois", objective = "Apporter 10 Glandes à venin Tissebois à Gilshalan Windwalker, à Aldrassil.", description = "Je suis venu à Sombrevallon pour observer les araignées Tissebois qui vivent dans la grotte de Sombrefil. Elles sont cousines d'une variété bien plus petite. Je pense que l'arbre-monde a eu un profond effet sur elles, et j'aimerais des spécimens à étudier pour confirmer cette hypothèse.\n\nD'abord, j'aimerais un peu de leur venin. Prélevez des glandes à venin de Tissebois sur les araignées à l'intérieur et autour de la grotte de Sombrefil, au nord. Je pourrai alors étudier les similitudes avec le venin de leurs cousines plus petites.", progress = "Avez-vous trouvé les glandes à venin, <nom> ?", completion = "Merci, &lt;nom&gt;. Lorsque je retournerai à Darnassus je comparerai le venin de ces glandes avec celui d'autres araignées. Je crois qu'il a des propriétés liées à la croissance récente de notre nouvel arbre-monde.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMaillet des chardonsDague des chardonsBâton des chardonsLame des chardons\n\nVous recevrez également :\n\n"},
[917] = {title = "L'œuf d'araignée Tissebois", objective = "Apporter un Œuf d'araignée Tissebois à Gilshalan à Aldrassil.", description = "À présent que j'ai le venin de ces araignées, j'aimerais étudier des spécimens vivants. Malheureusement, capturer une araignée géante est plus que je ne peux vous demander, jeune <classe>. Et je ne pourrais pas moi non plus maîtriser une araignée géante.\n\nSi vous pouvez trouver un œuf non encore éclos, alors il sera plus facile de posséder des spécimens, et je peux organiser les choses pour les enfermer avant que les araignées ne sortent.\n\nIl doit y avoir un nid, au plus profond de la grotte de Sombrefil. S'il vous plaît, partez chercher un œuf dans ce nid et rapportez-le-moi.", progress = "Êtes-vous allé à l'intérieur de la grotte de Sombrefil, <nom> ? Avez-vous trouvé un œuf d'araignée ?", completion = "Ah, très bien ! Je ferai en sorte que cet œuf et le venin soient transportés à Darnassus, puis j’y retournerai lorsque j'aurai achevé mes recherches. Je m'attends à découvrir beaucoup en étudiant ces spécimens, &lt;nom&gt;. Vous m'avez été d'un grand secours.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier forestierTunique forestièreRobe forestière\n\nVous recevrez également :\n\n"},
[918] = {title = "Les graines de sylvain", objective = "Apporter 8 Graines de sylvain à Denalan au lac Al'Ameth.", description = "Les sylvains de Teldrassil sont des élémentaires de la Nature. D'une certaine manière, ils reflètent l'ordre naturel des plantes et des animaux sur notre Grand Arbre.\n\nAussi est-ce inquiétant de voir les sylvains devenir furieux.\n\nJe pense que cela a quelque chose à voir avec la terre. J'ai travaillé à différentes méthodes pour alimenter les plantes et aimerais les essayer sur des graines de sylvains. S'il vous plaît, pouvez-vous collecter des graines de sylvain autour du lac Al'Ameth et me les apporter ?", progress = "Avez-vous les graines ? J'ai hâte de les planter.", completion = "Vous les avez. C'est bien !\n\nJe vais planter ces graines dans un terreau spécial que j'ai préparé à cet effet. Je pense que les graines vont produire des sylvains beaucoup plus dociles. Peut-être que vous pourrez voir les résultats plus tard !", rewards = "Vous recevrez :\n\nTête de champignon sylvestre"},
[919] = {title = "Les pousses de sylvain", objective = "Apporter 12 Pousses de sylvain à Denalan au lac Al'Ameth.", description = "De petits sylvains poussent près des eaux du lac Al'Ameth. J'ai bien peur que nous ne puissions plus rien faire pour ces jeunes sujets. Nous devons les arracher avant qu'ils ne grandissent trop et causent des problèmes.\n\nLorsque vous serez près du lac, arrachez les pousses de sylvains que vous verrez. Aidez-nous à garder une terre propre !", progress = "Salutations, <nom>. Avez-vous trouvé des pousses près des lacs ?", completion = "C'est beaucoup ! J'ai peur qu'ils ne se répandent à un rythme dangereux. J'espère pouvoir résoudre l'énigme de ce qui les infecte.\n\nMerci pour votre aide, &lt;nom&gt;. La terre est plus saine grâce à vos efforts.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de jardinageBrassards de grisepierre\n\nVous recevrez également :\n\n"},
[920] = {title = "Les appels de Tenaron", objective = "Parler à Tenaron Stormgrip au sommet d'Aldrassil à Sombrevallon.", description = "<nom>, n'est-ce pas ? J'ai entendu dire que Tenaron vous cherchait. Vous le trouverez à l'endroit le plus haut d'Aldrassil.\n\nIl se peut que nous vivions longtemps encore, mais ce serait mieux de ne pas le faire attendre trop longtemps.", progress = nil, completion = "Ah &lt;nom&gt; ! J'espérais bien que vous seriez prompt à répondre à mes appels. J'aimerais vous confier une importante tâche.", rewards = "Vous recevrez :\n\n"},
[921] = {title = "La couronne de la Terre", objective = "Remplir la Fiole de cristal et la rapporter à Tenaron Stormgrip au sommet d'Aldrassil.", description = "Il est temps pour vous de partir en quête de votre destinée, <nom>. Mais avant que vous ne soyez <prêt/prête> à vous aventurer au-delà de nos forêts enchantées, il y a beaucoup à apprendre de notre histoire récente.\n\nNotre peuple a beaucoup changé depuis la Bataille du mont Hyjal. Nordrassil n'est plus que l'ombre pâle de ce qu'il était autrefois... Son pouvoir avait battu Archimonde et repoussé la Légion ardente...\n\nIl y a une tâche que vous devez accomplir. Partez pour le Puits de lune au nord d'Aldrassil et apportez-moi une fiole de son eau.", progress = "Les Puits de lune gardent les eaux du Puits d'Eternité, l'ancienne source de magie qui a provoqué tellement d'horreurs dans notre monde.\n\nLes druides profitent de ses propriétés et les Sentinelles vénèrent les puits comme des autels à Elune, mais la sorcellerie leur est interdite à tous.", completion = "Ainsi vous avez entendu la première partie des conséquences de la Bataille du mont Hyjal. Beaucoup reste à raconter et la tâche que vous avez commencée maintenant va se prolonger durant tout votre voyage à travers Teldrassil et à Darnassus.", rewards = "Vous recevrez :\n\n"},
[922] = {title = "Rellian Greenspyre", objective = "Apporter une Graine de sylvain à Rellian Greenspyre à Darnassus.", description = "<nom>, pouvez-vous apporter l'une des graines que vous avez trouvées à mon ami, Rellian Greenspyre ? Il est druide à Darnassus, et la dernière fois que nous avons parlé il m'a révélé son intérêt concernant mes travaux sur les sylvains. Il avait quelques idées de son côté et il appréciera d'avoir une graine comme spécimen à étudier.\n\nMerci, <nom>. Vous m'avez été d'un grand secours. J'espère qu'un jour, vous verrez les fruits de mon labeur.\n\nRellian parcourt souvent les chemins de l'Enclave cénarienne à Darnassus.", progress = "Salutations…\n\nEt comment puis-je vous aider ?", completion = "Ah ! Une graine de sylvain ! Je voulais en faire pousser pour aider Denalan dans ses études.\n\nMais j'ai bien peur d'avoir découvert qu'une maladie contamine beaucoup de sylvains, et les graines de pieds malades portent à leur tour le problème. Mes talents ne suffisent pas à y remédier.\n\nDenalan est très compétent avec les choses qui poussent. Il pourrait trouver un remède pour les futurs sylvains. Il est sans doute leur dernier espoir.", rewards = "Vous recevrez :\n\n"},
[923] = {title = "Tumeurs", objective = "Apporter 5 Tumeurs moussues à Rellian Greenspyre à Darnassus.", description = "Une maladie décime les sylvains. Nous essayons d'en trouver la cause, mais tant que nous n’y parvenons pas nous devons arracher les sylvains contaminés, pour la sécurité de Teldrassil. Ceux qui poussent près du lac d'Aigue-vive, au nord de Teldrassil, sont les plus atteints. Nous devons les arracher !\n\nDétruisez les sylvains que vous trouvez, et prélevez la Tumeur moussue qui se développe sur eux. Apportez-moi les tumeurs afin qu'elles soient brûlées.", progress = "Êtes-vous allé au lac d'Aigue-vive, <nom> ? Avez-vous détruit des sylvains là-bas ?", completion = "Beau travail ! Ces tumeurs sont la cause de la maladie des sylvains. Elles sont pleines de poison que nous devons éliminer de notre nouvelle terre.\n\nJe vais détruire ces tumeurs.\n\nmerci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nSerpette"},
[924] = {title = "La Graine démoniaque", objective = "Prendre une Pierre de puissance imparfaite. L'apporter à l'autel de feu avant que le pouvoir de la pierre n'expire, puis revenir à Ak'Zeloth.", description = "La Graine démoniaque est un outil puissant au service de la Légion ardente. Elle repose dans une caverne du pic de Brume-funeste, au-dessus d'un diabolique autel de feu.\n\nJ'ai préparé des Pierres de puissance qui, lorsqu'elles seront placées près de la graine, couperont sa connexion avec la Légion.\n\nPrenez une pierre sur la table et portez-la à l'autel de feu au sommet du pic de Brume-funeste. Voyagez à l'ouest, puis au nord lorsque la route se divise. Le pic sera sur votre gauche. L'escalade la plus sûre s'effectue par la face nord.\n\nEt faites vite, le pouvoir de la pierre faiblit avec le temps.", progress = nil, completion = "Votre tâche est terminée. Vous avez détruit la Graine démoniaque, comme l'a demandé Neeru. Mais ce n'est pas encore la fin...\n\nLa destruction de la Graine démoniaque a envoyé des vagues de puissance à travers l'espace, des vagues d’une force stupéfiante. Je l'ai ressenti et je suis sûr que d'autres l'ont ressenti également. D'autres qui vont se demander pourquoi leur jouet est cassé...\n\nMais faisons fi des problèmes futurs, j'ai quelque chose pour vous. Neeru a envoyé ceci comme paiement. Et il demande à ce que je vous remercie.\n\nAussi, merci à vous.", rewards = "Vous recevrez :\n\nArmure de la Banshee"},
[925] = {title = "L'empreinte de Cairne", objective = "Allez à Thunder Bluff pour tenter d'obtenir l'empreinte de sabot de Cairne pour votre protégé.", description = "On dit que Cairne Bloodhoof est l'un des plus grands héros de la Horde de tous les temps. Quand je serai grand, je veux être un héros de la Horde, moi aussi !\n\nVous connaissez Cairne, <nom> ? Vous pouvez me faire une faveur, s'il vous plaît ? Vous pouvez avoir son empreinte de sabot pour moi ? Je sais pas comment lui demander, et c'est sans doute une personne bien trop occupée pour s'occuper de quelqu'un comme moi... Mais pas vous ! Vous êtes <un aventurier/une aventurière>, comme lui ! Je parie qu'il vous donnerait facilement son empreinte de sabot !\n\nS'il vous plaît ?", progress = "Quand les orcs étaient seuls et sans alliés, les taurens les ont accueillis sur cette terre qui leur était étrangère, sans rien leur demander en échange. C'est un honneur, <nom>.", completion = "OUAH ! Vous avez l'empreinte de sabot de Cairne pour moi ! Merci beaucoup ! Et... Ouah... il m'a même écrit un message personnel... Rien que pour moi ! Je savais qu'il était génial, j'en étais sûr ! Peut-être qu'un jour je le remercierai moi-même... Quand je serai devenu un héros de la Horde !\n\nVous êtes la meilleure, &lt;nom&gt;. Merci d'avoir été aussi gentille avec moi.", rewards = "Vous recevrez :\n\n"},
[926] = {title = "Pierre de puissance imparfaite", objective = "Ces pierres sont imprégnées d'énergie magique, mais d'une énergie affaiblie, volontairement. Elles sont très instables et une fois prises sur la table, elles se consumeront très rapidement.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPierre de puissance imparfaite"},
[927] = {title = "Le cœur moussu", objective = "Apporter le Cœur moussu à Denalan au lac Al'Ameth.", description = "Le cœur de Noiremousse le Fétide est couvert d'une mousse sombre et huileuse. En fait, ce qui permet d’identifier ce cœur, c’est sa pulsation, lente et rythmée.\n\nPeut-être que Denalan voudra voir ce cœur ?", progress = "<nom> ! Avez-vous quelque chose pour moi ?", completion = "Qu'est-ce donc ? Un cœur de sylvain ? Il est couvert d'une mousse infecte !\n\nMerci de m'apporter cela, &lt;nom&gt;. Je vais l’examiner, et si la fortune me sourit je vais déterminer la nature de cette mousse.", rewards = "Vous recevrez :\n\n"},
[928] = {title = "La couronne de la Terre", objective = "Apporter le Récipient à moitié plein à Corithras Moonrage à Dolanaar.", description = "Bien que je puisse vous entretenir encore longtemps des Puits de lune et de Teldrassil, je dois vous faire partir. Corithras Moonrage va vous attendre. J'ai versé l'eau de la fiole que vous m'avez apportée dans ce récipient que vous devez lui remettre.\n\nCherchez Corithras. Vous le trouverez au Puits de lune à Dolanaar. Suivez la route vers le sud à partir d'Aldrassil et vers Sombrevallon, et continuez à suivre les pavés ronds lorsque la route se dirige vers l'ouest.\n\nAttention, restez toujours sur la route, <nom>. Il y a de dangereuses bêtes, le soir, dans les forêts.", progress = "Salutations, <classe>. A quelle occasion dois-je le plaisir de vous rencontrer ?", completion = "Ah je vois ! Vous avez été envoyé par Tenaron. Très bien alors, il semblerait que nous ayons beaucoup à discuter, beaucoup à faire, et peu de temps pour tout cela.\n\nAlors commençons...", rewards = "Vous recevrez :\n\n"},
[929] = {title = "La couronne de la Terre", objective = "Remplir la Fiole de jade et la rapporter à Corithras Moonrage à Dolanaar.", description = "Tout d'abord, laissez-moi vous en dire plus à propos de la quête que vous devez accomplir. Les druides de Darnassus utilisent l'eau des Puits de lune de Teldrassil, et leurs Puits de lune doivent être remplis de temps en temps. En utilisant ces fioles spécialement conçues, vous pouvez collecter l'eau des Puits de lune.\n\nApportez ce récipient jusqu'au Puits de lune à l’extérieur du village de Brise-stellaire à l'est, et remplissez-le d'un peu de ses eaux. Puis revenez me voir. Lorsque vous aurez accompli votre tâche, je reprendrai l'histoire là où Tenaron s’est arrêté.", progress = "Salutations à nouveau, <nom>. Avez-vous accompli votre tâche ?", completion = "Après la Bataille du mont Hyjal, nous n'avions plus de commandement. Nordrassil fumait du feu qu'il avait déclenché, et notre immortalité – l'essence même de nos êtres – était perdue.\n\nC'est en ces temps d'épreuves que le Traître fut libéré de sa prison, et que Shan'do Stormrage disparut. Des temps sombres pour chacun.", rewards = "Vous recevrez :\n\n"},
[930] = {title = "Le fruit luminescent", objective = "Apporter le Fruit luminescent à Denalan au lac Al'Ameth.", description = "Pendu à cette plante, sous ses feuilles, se trouve un grand fruit rond.\n\nDenalan voudra étudier ce fruit, c'est certain.", progress = "<nom>, on dirait que vous voulez me dire quelque chose ? Avez-vous des nouvelles à propos des sylvains ?", completion = "Vous avez trouvé ceci sur Teldrassil ? Étrange… Ce fruit est assurément exotique. Peut-être que sa graine est venue de très loin. Peut-être même d'aussi loin qu'Azeroth ! Et il y a quelque chose à propos de ce fruit… Il semble avoir réagi très bizarrement à la terre de Teldrassil.\n\nMerci, &lt;nom&gt;. À présent si vous voulez bien m'excuser, je dois faire une étude plus poussée...", rewards = "Vous recevrez :\n\n"},
[931] = {title = "Les racines flamboyantes", objective = "Apporter les Racines flamboyantes à Denalan au lac Al'Ameth.", description = "Les feuilles de la plante flamboient dans la lumière de la forêt, lui donnant une aura pulsante et sinueuse.\n\nVous pensez que Denalan en souhaiterait un spécimen.", progress = "Vous avez quelque chose pour moi ?", completion = "Où avez-vous trouvé cela ? Je n'ai pas revu une plante pareille depuis un séjour que j'ai effectué dans les marais des Chagrins… il y a des décennies de cela ! C'est stupéfiant qu'un tel spécimen soit parvenu jusqu'en Teldrassil. Et sa taille est inhabituelle !\n\nMerci, &lt;nom&gt;. Pardonnez mon manque de loquacité, mais j'aimerais effectuer un test sur cette plante...", rewards = "Vous recevrez :\n\n"},
[932] = {title = "Haine folle", objective = "Tuer le seigneur Melenas et apporter sa tête à Tallonkai Swiftroot à Dolanaar.", description = "Je vous avertis, <nom>, cette affaire doit rester entre nous. Les satyres nous embarrassent déjà suffisamment, et celui-ci est beaucoup trop proche.\n\nIl s'appelle le seigneur Melenas. Il réside dans la caverne proche de Gangreroche où il a rassemblé de nombreux guerriers grells. Son cœur est aussi noir que la nuit, et il prépare quelque chose d'abominable.\n\nVous devez le trouver à l'intérieur de sa caverne proche juste au nord d'ici, et m'apporter sa tête.", progress = "Avez-vous déjà tué le Seigneur Melenas ? Il est vital que l'on s'occupe rapidement et discrètement de lui, <nom>. Son existence est un danger pour chacun d'entre nous.", completion = "Maintenant que le Seigneur Melenas repose enfin, je peux m'occuper des autres problèmes. Merci, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards farouchesChausses de Viny\n\nVous recevrez également :\n\n"},
[933] = {title = "La couronne de la Terre", objective = "Remplir la Fiole de tourmaline et la rapporter à Corithras Moonrage à Dolanaar.", description = "Il y a un autre Puits de lune au sud-est de l'entrée vers Darnassus, sur les rives des bassins d'Arlithrien. Les Sentinelles ont des problèmes lors de leurs patrouilles dans ce secteur. Ils sont attaqués par les furbolgs du clan Pin-tordu, de plus en plus sauvages.\n\nSoyez <prudent/prudente> quand vous chercherez le Puits, et gardez la main près de vos armes.", progress = "Au début, les rapports parlant d’attaques de furbolgs enragés ne furent pas pris au sérieux. Qui aurait pu penser que ces nounours pacifiques deviendraient de folles machines à tuer ? C'est pourtant un autre des problèmes qui nous assaillent ici à notre nouveau domicile.", completion = "Shan'do Stormrage ne revint jamais, et les druides étaient en plein désarroi. À ce jour, nous ne savons toujours pas ce qu'il est advenu de lui. Malfurion n'étant plus là, l'archidruide Fandral Staghelm prit la direction des druides, convainquant ainsi le Cercle des Anciens de Sombrivage qu'il était temps pour notre peuple de reconstruire, et temps également de retrouver l'immortalité.\n\nAvec l'approbation du Cercle, Staghelm et les plus puissants druides firent grandir Teldrassil, le nouvel Arbre Monde.", rewards = "Vous recevrez :\n\n"},
[934] = {title = "La couronne de la Terre", objective = "Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar.", description = "Cependant, tout n'était pas parfait sur Teldrassil. Les plans soigneusement conçus de Staghelm pour le nouvel Arbre Monde s'étaient déroulés comme il l'avait espéré. Mais il y eut un petit problème, un problème sans doute à l'origine des nombreuses difficultés rencontrées sur Teldrassil.\n\n. Mais je ne vais pas m'étendre maintenant sur ce sujet. Vous devez vous rendre au dernier puits de lune, au nord-ouest, dans la clairière de l'Oracle. Sous les branches de l'arbre-oracle se trouve le premier et le plus puissant de nos puits. Remplissez un flacon de son eau et revenez me voir.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[935] = {title = "La couronne de la Terre", objective = "Apporter le Récipient plein à l'archidruide Fandral Staghelm à Darnassus.", description = "Sans la bénédiction d'Alexstrasza la Lieuse de vie et celle de Nozdormu l'Éternel, la croissance de Teldrassil ne fut pas parfaite. On rapporte que des bêtes étranges sortaient de ses racines et que des furbolgs enragés attaquaient des voyageurs.\n\nJe ne peux qu'espérer que l'archidruide trouvera rapidement la solution. Je vais verser le contenu de toutes les fioles que vous m'avez amenées dans ce récipient, pour que vous l'apportiez à Darnassus.\n\nApportez-le à Fandral Staghelm, vous le trouverez dans le bosquet des druides.", progress = "Je sais que je ne vous ai pas appelé, aussi ne puis-je m'empêcher de me demander pourquoi vous êtes venu me parler.\n\nQuel que soit le sujet, faites vite, je vous prie.", completion = "Ah oui ! L'eau que j'ai demandée. Tenaron et Corithras ont mis tout ce temps pour me la faire parvenir… Je n'ai peut-être pas choisi les messagers les plus sûrs… Hmmm !\n\nMais bon, je peux enfin retourner à mon travail. Le poids des soucis de Teldrassil repose sur mes épaules. Un fardeau dont j'aimerais être débarrassé au plus tôt.\n\nPrenez cela, peut-être y trouverez-vous une quelconque utilité.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc d'AshwoodMarteau de bois\n\nVous recevrez également :\n\n"},
[936] = {title = "L'aide à l'archidruide Runetotem", objective = "Parler à l'archidruide Hamuul Runetotem à Thunder Bluff.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps, si cela est possible.\n\nLe Cercle cénarien de Thunder Bluff est très intéressé par des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans un projet crucial. Bien que je n’en connaisse pas les détails, je peux vous dire que Hamuul Runetotem lui-même mène ce projet.\n\nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la Cime des Anciens dans Thunder Bluff.", progress = nil, completion = "Salutations, &lt;classe&gt;. Je suis heureux de voir que l'idée de nous prêter main-forte vous intéresse. Il y a beaucoup à faire, et ce ne serait pas vous rendre service que de vous dire que ce travail ne comporte aucun danger. J'espère que cela ne va pas vous effrayer... Mais en vous regardant, il me semble comprendre que vous avez déjà eu à faire au danger.", rewards = "Vous recevrez :\n\n"},
[937] = {title = "La clairière enchantée", objective = "Acquérir 6 Ceintures plumesang et les apporter à la Sentinelle Arynia Cloudsbreak à la clairière de l'Oracle.", description = "On m'a envoyée ici avec un petit groupe de Sentinelles pour protéger l'arbre-oracle des harpies qui ont construit leurs nids tout autour de la clairière. Nous essayons de les repousser petit à petit.\n\nLorsque l'arbre-oracle a tenté d'envoyer un messager avec un rapport, il a été attaqué par un groupe de harpies et tué.\n\nSi vous vous sentez suffisamment <préparé/préparée> pour cette tâche, allez à leurs nids, tuez-les et rapportez-moi leurs ceintures en guise de preuves de vos exploits.", progress = "Leurs serres coupantes et leurs becs perçants peuvent présenter des difficultés, <nom>, mais j'ai foi en votre capacité à accomplir cette tâche.", completion = "Je suis impressionnée par ce que vous venez d'accomplir en un temps aussi court, &lt;nom&gt;. J'aimerais vous demander de rester ici et de m’épauler… Mais je sais dans mon cœur que de plus grandes quêtes vous attendent.\n\nJ'ai remarqué que l'arbre-oracle a laissé tomber un morceau de son écorce. Il ne fait pas de doute qu'il a une tâche qu'il aimerait vous voir accomplir. Vous devriez aller lui parler.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinturon d'entraveCape tachée de pluie\n\nVous recevrez également :\n\n"},
[938] = {title = "Brume", objective = "Escorter Brume vers la Sentinelle Arynia Cloudsbreak au puits de lune, près de l'arbre-oracle.", description = "La fourrure du tigre à dents de sabre est d'un gris particulier, tranchant avec les couleurs de la forêt environnante. Tandis qu'elle repose là, vous remarquez qu'elle est gravement blessée, de profondes lacérations déchirent son dos et son ventre.\n\nElle lève la tête et vous regarde, ses yeux bleus brillant d'intelligence. Elle a l'air de souhaiter vous suivre.", progress = "Brume… C'était ma faute ! Les sorcières m'ont surprise la garde baissée… Je n'aurais pas dû les laisser te prendre…", completion = "Oh merci &lt;nom&gt; ! J'ai eu tellement peur de ne plus jamais revoir Brume. J’ignorais quel sort était réservé à ma fidèle camarade. Je vous dois plus que vous ne pourriez imaginer, et vous avez ma reconnaissance éternelle.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards de cordeTarge des rochersCape d'éclaireur\n\nVous recevrez également :\n\n"},
[939] = {title = "Flûte de Xavaric", objective = "Apporter la Flûte de Xavaric et 5 échantillons de Lien maudit Jadefeu à Eridan Bluewind, dans le sud de Gangrebois.", description = "Vous étudiez la simple flûte de bois que vous avez récupérée après avoir vaincu Xavaric.\n\nLe bois noueux semble solide mais les spirales et les motifs de sa surface semblent se mouvoir quand vous tournez l’instrument entre vos mains. Soudain, vous êtes pris d’un sentiment d’appréhension...\n\nVous vous ébrouez, pensant que votre esprit vous joue des tours.\n\nIl est possible de trouver auprès d'autres satyres des indices relatifs à ce que vous avez trouvé. Apportez vos découvertes au druide Eridan Bluewind qui vit dans la partie sud de Gangrebois.", progress = "Qu'y a-t-il, <classe> ? Vous avez l'air préoccupé.", completion = "Je ressens la souffrance des Anciens, &lt;nom&gt;...\n\nPorter ces objets est presque insupportable...", rewards = "Vous recevrez :\n\n"},
[940] = {title = "Teldrassil", objective = "Remettre le rapport de l'arbre-oracle à l'archidruide Fandral Staghelm à Darnassus.", description = "On entend murmurer la forêt qui loue vos grandes prouesses, <nom>. Les harpies une fois délogées de leurs nids, un grand calme s'est répandu sur la forêt, ses créatures se sentant à nouveau en sécurité. J'ai eu peur d'envoyer un autre messager à l'archidruide, mais je sais que vous, vous parviendrez à lui remettre un message.\n\nApportez-lui ceci et sachez que la forêt veillera à votre sécurité le long du chemin menant à la Forêt de pierre.", progress = "Hmm… Je vois que l’esprit de la forêt vous accompagne, <classe>. Qu'est-ce qui vous amène jusqu’à l'archidruide des Kaldorei ?", completion = "Je me demandais pourquoi l'arbre-oracle ne communiquait plus avec moi depuis si longtemps… Il semble que quelques problèmes aient été résolus, alors que d'autres nous apportent des inquiétudes croissantes.\n\nJ'ai peur que mon travail sur Teldrassil ne soit jamais achevé, et que notre immortalité ne soit jamais retrouvée.\n\nCependant, vous avez accompli à merveille la tâche que vous avait confiée l'arbre-oracle, et devez être récompensé pour votre diligence.", rewards = "Vous recevrez :\n\n"},
[941] = {title = "Une belle plante", objective = "Planter le Cœur corrompu dans le Pot de Denalan.", description = "J'ai débarrassé le cœur de cette ignoble mousse, mais il reste contaminé…\n\nEssayez de placer le cœur dans ce pot. Il est rempli d’un terreau spécial qui pourrait le nettoyer et le guérir.", progress = "Le pot est rempli d'un terreau spécialement préparé par Denalan.", completion = "Vous placez le cœur à l'intérieur du pot, et il s'enfonce rapidement de lui-même.\n\nQuelques secondes plus tard, il ressurgit, propre. Il bat doucement… vous enjoignant de le prendre.", rewards = "Vous recevrez :\n\nCoeur de sylvain purifié"},
[942] = {title = "Les absences du Prospecteur", objective = "Apporter le mystérieux Fossile à l'Archéologue Flagongut au Port de Menethil.", description = "Le fossile ressemble de manière frappante à un autre que j'ai vu une fois à Ironforge. Un Archéologue du nom de Flagongut l'avait apporté à notre conférence annuelle de la Ligue des Explorateurs. Il croyait que le fossile détenait un pouvoir que l'on aurait pu réveiller d'une certaine façon.\n\nLa dernière fois que j'ai entendu parler de lui, Flagongut s'était installé à la taverne de l'Eau-profonde, au Port de Menethil, attendant une escorte pour le mener à l'Excavation de Whelgar. Recherchez-le et montrez-lui le Fossile de Remtravel. Peut-être pourra-t-il révéler les secrets du passé.\n\nLe bateau pour le Port de Menethil part d'Auberdine.", progress = "Qu'avez-vous là, mon ami ?", completion = "Oh bon sang ! Vous dites que ce fossile vient des terres lointaines de Kalimdor ?\n\nAhurissant, simplement ahurissant !", rewards = "Vous recevrez :\n\n"},
[943] = {title = "Les absences du Prospecteur", objective = "L'archéologue Flagongut au Port de Menethil veut que vous lui apportiez la Pierre de Relu et le Fossile de Flagongut.", description = "Le Prospecteur Whelgar détient à présent le fossile original, en son site des marécages. Quand j'ai découvert la Pierre de Relu, j'ai cru y voir la solution à l'énigme du fossile.\n\nAlors que je taillais la route pour aller à la rencontre de Whelgar, j'ai subi une attaque de raptors et la relique fut perdue. J'ignore laquelle des ces créatures chamarrées a bien pu l'avaler, mais si vous pouvez la retrouver, je peux libérer le pouvoir de ces artefacts.\n\nApportez-moi donc la Pierre de Relu, et le fossile original que Whelgar possède.", progress = "Une fois que je serai en possession de la Pierre de Relu je pourrai libérer les secrets cachés de mon fossile, mais également ceux du fossile de Remtravel de Sombrivage, <nom>.", completion = "Plus que parfait, &lt;nom&gt; !\n\nÀ présent voyons si je peux utiliser la pierre pour découvrir les pouvoirs des fossiles.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de reliqueBroie-crâne\n\nVous recevrez également :\n\n"},
[944] = {title = "Le Glaive du Maître", objective = "Trouver des informations, puis utiliser la Fiole de divination pour créer une Coupe de divination. Utiliser la coupe pour parler à Onu.", description = "C'est étrange que des nagas soient là, à Sombrivage. Mais... la présence du Marteau du crépuscule l'est encore plus. Ce culte vénère de très anciens seigneurs de la terre. Des seigneurs vaincus il y a longtemps de cela.\n\nLe Glaive du Maître, au sud, est un endroit où est tombé l'un de ces anciens seigneurs.\n\nAllez-y et cherchez d'autres sectateurs du Marteau du crépuscule.\n\nPrenez cette fiole de divination. Utilisez-la pour créer une coupe de divination après avoir enquêté au Glaive du Maître. Puis parlez-moi par l'intermédiaire de cette coupe.", progress = "Le Glaive du Maître, <nom>.\n\nAllez-y, puis parlez-moi à nouveau de là-bas.", completion = "Le Marteau du crépuscule se trouve au Glaive du Maître ?\n\nC'est malheureux.\n\nLe vieux seigneur, empalé sur le glaive, est mort depuis longtemps, mais cela ne veut pas dire que des bribes de son pouvoir n'ont pas subsisté.\n\nLe Marteau du crépuscule doit rechercher ce pouvoir.", rewards = "Vous recevrez :\n\n"},
[945] = {title = "L'évasion de Therylune", objective = "Aider Therylune à s'échapper, puis dire à Therysil au Sanctuaire d'Aessina que sa sœur est saine et sauve.", description = "Au secours !\n\nJe me promenais autour du Glaive du Maître, et ces infâmes sectateurs m'ont entourée. Encore heureux que je sois douée pour me cacher !\n\nPouvez-vous m'aider à m'échapper ? Et j'aurais aussi besoin de dire à ma sœur Therysil que je vais bien. Elle est à Ashenvale au sud, au sanctuaire d'Aessina.", progress = nil, completion = "Ma sœur était où ? Therylune n'a pas peur de se salir, mais quand même ! C'est loin pour une simple promenade et le Glaive du Maître est un endroit malsain…\n\nBien, merci, &lt;nom&gt;. Vous avez été très aimable de m'informer du sort de ma sœur.", rewards = "Vous recevrez :\n\n"},
[947] = {title = "La caverne aux champignons", objective = "Apporter 5 Pédoncules d'Amanite et 1 Amanite phalloïde à Barithras Moonshade à Auberdine.", description = "Je prépare une potion qui nécessite des champignons rares, des champignons qui ne poussent que dans une certaine caverne. La caverne en question se trouve au-delà des Chutes de la Bondissante, à l'est et légèrement au nord le long des montagnes.\n\nJ'irais bien moi-même, mais le Bosquet des Anciens m'a conseillé de me tenir à l'écart de cet endroit. Nos vénérables alliés pressentent que cette caverne est l'antre d'une nouvelle créature maléfique, ici à Sombrivage.\n\nS'il vous plaît, <nom>, ramassez ces champignons pour moi. Et pendant que vous y êtes, explorez la caverne pour confirmer le pressentiment des Anciens.", progress = "Avez-vous mes champignons, <nom> ? Êtes-vous allé à la caverne ?", completion = "Merci beaucoup, &lt;nom&gt;. Ces champignons sont magnifiques !\n\nEt pendant que vous étiez aux chutes de la Bondissante, avez-vous trouvé quoi que ce soit qui confirme les avertissements des Anciens ?\n\nLes Anciens sont des sages, mais j'avais espéré qu'ils se soient trompés cette fois-ci.", rewards = "Vous recevrez :\n\nCape des terres venteusesChampignon à pois rouges"},
[948] = {title = "Onu", objective = "Parler à Onu au Bosquet des Anciens.", description = "Onu, un Ancien du savoir au Bosquet des Anciens, est au courant de votre voyage vers les Chutes de la Bondissante et souhaite vous parler. Le bosquet se trouve au sud, blotti près des montagnes.\n\nLes Anciens sont patients et sages, <nom>. Mais si Onu souhaite votre conseil à propos de ce que vous avez vu aux chutes, alors j'ai peur que ce soit urgent.", progress = nil, completion = "&lt;nom&gt;. Vous voilà.\n\nBien.\n\nIl y a des choses dont… nous devons parler. Vous et moi.", rewards = "Vous recevrez :\n\n"},
[949] = {title = "Le camp du Marteau du crépuscule", objective = "Trouver un indice au Camp du Marteau du crépuscule au Glaive du Maître.", description = "Nous ne connaissons pas le but du Marteau du crépuscule au Glaive du Maître.\n\nFouillez leur camp au Glaive… Essayez de trouver quelque chose qui puisse nous indiquer leurs intentions.\n\nCar nous devons les connaître avant d'établir un plan.", progress = nil, completion = "Ce livre est manuscrit dans un ancien langage et illustré par un maître artiste.", rewards = "Vous recevrez :\n\n"},
[950] = {title = "La page qui rend fou", objective = "Apporter les Gribouillages déments à Onu.", description = "Consulter le Tome du crépuscule rend fou. Au premier regard, le texte commence à flotter et danser ; images et enluminures s'entremêlent pour créer des formes grotesques.\n\nVous arrivez tout juste à déchirer une page de ces gribouillages déments avant qu'un vertige ne vous submerge.", progress = "<nom>. Vous êtes de retour !", completion = "Une magie chaotique et primitive baigne cette page. J'y ressens le travail des très anciens.\n\nEspérons qu'elle révélera les desseins du Marteau du crépuscule à Sombrivage.", rewards = "Vous recevrez :\n\n"},
[951] = {title = "Les Reliques de Mathystra", objective = "Apporter 6 Reliques de Mathystra à Onu, au Bosquet des Anciens.", description = "Le parchemin que vous avez découvert au Glaive du Maître est la page d'un texte ancien… écrit par des elfes ! Il est souillé de la corruption du Marteau du crépuscule. Ainsi, le culte utilise l'ancienne magie des elfes pour ramener ses vieux maîtres dans notre monde.\n\nVoyagez jusqu'aux ruines de Mathystra au nord-est, et cherchez d'anciennes reliques, dans l'herbe et parmi les pierres brisées. En les étudiant, il se peut que nous comprenions comment le Marteau du crépuscule compte exploiter la magie des elfes.", progress = "<nom>. Vos recherches dans les Ruines de Mathystra ont-elles été fructueuses ?", completion = "Merci. Ces reliques datent de la grande époque de Mathystra. Cet ancien bastion de renom des elfes a aujourd'hui disparu, mais des fragments de sa magie demeurent. Espérons que nous pourrons découvrir les secrets de cet endroit avant nos ennemis...\n\nLa vigilance s'impose, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTrique de bois durEpée du bûcheron\n\nVous recevrez également :\n\n"},
[952] = {title = "Bosquet des Anciens", objective = "Livrer le message de Fandral à Onu, au bosquet des Anciens, à Sombrivage, au sud d’Auberdine.", description = "Si vous avez suffisamment de temps pour servir de <messager/messagère> pour l'arbre-oracle, je pourrais vous demander de remettre un message au bosquet des Anciens, à Sombrivage, au sud d'Auberdine.\n\nVous aurez probablement à effectuer le voyage en hippogryphe, mais j'ai foi en vos compétences. Apportez ceci à Onu, l'Ancien du savoir. Il attend un mot de ma part, tout comme j'attendais un mot de la Clairière de l'Oracle.", progress = "Ah <classe> ! Comment Onu peut vous être d'une quelconque assistance ?", completion = "Merci, &lt;nom&gt;. C'est étrange, cependant. L'archidruide semble toujours si pressé. La forêt sait que tout ce qui doit arriver arrivera en temps utile. Shan'do Stormrage a compris cela.", rewards = "Vous recevrez :\n\n"},
[953] = {title = "La chute d'Ameth'Aran", objective = "Étudier les tablettes qui parlent d'Ameth'Aran et de sa chute, puis retourner voir la Sentinelle Tysha Moonblade à Sombrivage.", description = "Vous trouverez à l'est les ruines d'Ameth'Aran. Elles sont habitées par les Esprits sans repos des Bien-nés qui vivaient autrefois dans ces murs, quand les serviteurs d'Azshara y pratiquaient librement leur puissante magie.\n\nOn m'a envoyée pour explorer les ruines et trouver deux grandes tablettes, sur lesquels sont racontées les histoires d'Ameth'Aran et de sa chute. Alors que je lisais les runes, j'ai été surprise par les Esprits, et je me suis enfuie.\n\nS'il vous plaît, si vous le pouvez, aventurez-vous dans les ruines et déchiffrez les tablettes pour moi.", progress = "Lorsque vous aurez étudié les tablettes et compris les circonstances de la chute d'Ameth'Aran, je relaierai cette connaissance jusqu'à Auberdine, et informerai le Cercle des Anciens.", completion = "Nous avons peu de registres des temps de la guerre des Anciens, et spécialement de ceux proches de la destruction du Puits d'éternité. Compte tenu des événements dramatiques et des bouleversements qui ont eu lieu, ce n'est pas une grande surprise.\n\nMerci, &lt;nom&gt;. Grâce à votre aide, j'ai terminé mon travail ici, et vais être en mesure de remettre un rapport complet au Cercle.", rewards = "Vous recevrez :\n\n"},
[954] = {title = "Bashal'Aran", objective = "Trouver la source de l’aura bleue dans les Ruines de Bashal'Aran.", description = "Les ruines de Bashal'Aran à l'est sont infestées de serviteurs démoniaques. Les fées et les satyres qui ont élu domicile dans la région se nourrissent des énergies magiques du secteur, et leurs pouvoirs augmentent avec le temps passé sur place.\n\nMais malgré cela, j'ai remarqué un sanctuaire dont ils ne s'approchent jamais. A l’ouest des ruines, au sommet d'un petit promontoire, filtre une étrange aura bleue... Il doit y avoir une explication à la répugnance des démons.\n\nJ'aimerais que vous enquêtiez à ce propos.", progress = nil, completion = "Ah !… Pour quelle raison me feriez-vous l'extraordinaire honneur de votre compagnie. En vérité, cela en révèle beaucoup sur mes compagnons actuels – sans vouloir offenser mes hôtes, les nobles grells et les grands satyres –, car votre présence pourrait être considérée comme une amélioration, &lt;nom&gt;.\n\nMais, s'il vous plaît, ne laissez point ma langue si peu civile vous faire fuir. Il y a de nombreuses années, en fait des décennies, que je n'ai eu d‘aimable compagnie.", rewards = "Vous recevrez :\n\n"},
[955] = {title = "Bashal'Aran", objective = "Acquérir 8 Boucles d'oreilles de grell pour Asterion à Bashal'Aran.", description = "Si j'avais à raconter l'histoire de ma vie, il ne fait pas de doute qu'elle dépasserait les limites de votre patience. Disons que ma vie a été longue et douloureuse, et cette forme spectrale qui est la mienne à présent est peut-être le pire de tous ces tourments.\n\nJe suis retenu ici par les pouvoirs de la magie. Bien que mes mots puissent sonner faux, je vous assure que je vous serais reconnaissant au-delà de tout si vous pouviez m’aider à identifier ce qui me retient prisonnier. Un sceau fait partie de ce dispositif, et en examinant les boucles d'oreilles des fées et des grells, je pourrais en trouver la trace.", progress = "Une fois que j'aurai les boucles d'oreilles, je lancerai le sort pour localiser approximativement le sceau qui me retient. Pendant des siècles, j'ai rêvé à la liberté que m'apporterait la destruction de ce sceau… Peut-être que ces siècles ont doucement jeté un voile sur mon esprit, que je ne pourrai jamais complètement ôter...", completion = "En fait… Les grells de Bashal'Aran ne possèdent pas ce que je recherche… Cependant ils sont récemment entrés en contact avec ce que je recherche. Récemment… je prends comme mesure votre temps, pas le mien. Récent pour moi veut dire dans les brumes du passé, presque dans un autre âge...", rewards = "Vous recevrez :\n\n"},
[956] = {title = "Bashal'Aran", objective = "Obtenir l'Ancien sceau de pierre de lune et l'apporter à Asterion à Bashal'Aran.", description = "Si les grells sont entrés en contact avec le sceau qui verrouille ma prison éternelle, je crois en connaître la cause. Il ne fait pas de doute que le sceau est en la possession du satyre qui les dirige.\n\nJe ressens fortement que cela doit être vrai, <nom>. L'un des satyres le possède à présent. Si vous pouvez l'obtenir, je serais si proche de pouvoir passer les barreaux de ma prison que les larmes me monteraient aux yeux.", progress = "Les piliers de cet Autel sont comme les barreaux d'une prison pour moi, <nom>. Aucune force qui pourrait me rester ne pourra les briser, et aucune magie que je pourrais lancer ne pourra les détruire…\n\nPendant des milliers d'années et même plus, je les ai regardés, me demandant si en vivant plus longtemps que ces pierres je parviendrais à m’échapper, ou si c’était des barreaux invisibles qui me retenaient.", completion = "C'est… C'est difficile de simplement croire que ce que je tiens est ce qui m'a tenu pendant si longtemps. Ne perdons pas de temps, &lt;nom&gt;. Lorsque le sceau sera brisé, il se peut que je puisse marcher dans les forêts de la terre, à nouveau libre.", rewards = "Vous recevrez :\n\n"},
[957] = {title = "Bashal'Aran", objective = "Détruire l'Ancien sceau de pierre de lune à la flamme antique qui se trouve dans Ameth'Aran, puis retourner voir Asterion à Bashal'Aran.", description = "C'est le savoir de l'un des plus puissants Bien-nés qui a créé le sceau fermant ma prison. À Ameth'Aran, dans les ruines au sud, jumelles de celles-ci, brûle une flamme antique, de couleur bleue. Dans cette flamme, ce sceau pourrait être détruit.\n\nSoyez <prudent/prudente> dans les ruines, <nom>.", progress = nil, completion = "Je suis libre, &lt;nom&gt; ! Je peux à présent voir de mes propres yeux les changements qui sont survenus dans notre monde… Je n'en ai connu que des fragments, des morceaux. Quand je pense que la dernière fois que j'ai marché librement, le Puits était toujours debout et que les Bien-nés étaient à la cour avec Azshara, notre reine bien-aimée...\n\nJe sens que mon geôlier, mon ancien maître, Athrikus, est toujours en vie... Déjà, mes sentiments de désespoir laissent place à des projets de vengeance.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBroigne d'explorateurJambières du vagabondBaguette elfique\n\nVous recevrez également :\n\n"},
[958] = {title = "Les outils des Bien-nés", objective = "Retrouver 7 Reliques de Bien-né pour Thundris Windweaver à Auberdine.", description = "<classe>. J'aurais quelque chose à vous demander.\n\nConnaissez-vous les ruines d'Ameth'Aran ? Si ce n'est pas le cas, vous les trouverez à l’est de la route principale, à quelque distance au sud. Alors qu'elles abritaient de nombreux Bien-nés puissants, elles ne sont plus à présent que l’image de la destruction à laquelle leurs expériences ont abouti.\n\nLes Sentinelles disent que les esprits des Bien-nés sont toujours là, et qu'ils manient toujours leurs instruments magiques. Nous devons nous emparer de ces reliques, afin de les détruire.", progress = "Si seulement les outils de leur perte avaient pu être détruits dans le cataclysme qui a détruit notre monde… Mais passons, nous devons tout faire pour s'assurer que les horreurs du passé ne se reproduisent plus à l’avenir.", completion = "Bien que ce ne soit probablement que le fruit de mon imagination, je pourrais presque sentir la marque de la magie maléfique des Bien-nés sur ces objets. Nous devons faire en sorte qu'ils soient détruits, pour que leur puissance magique latente ne se réveille jamais.", rewards = "Vous recevrez :\n\nCrispins de lierre"},
[959] = {title = "Fuite de porto aux docks", objective = "Le grutier Bigglefuzz de Ratchet veut que vous repreniez la Bouteille de porto vieille de 99 ans à Magglish le Dingue, qui se cache dans les Cavernes des lamentations.", description = "Oups !\n\nJ'ai eu une petite mésaventure, comme vous pouvez le voir ! La cargaison du matin venant de Baie-du-Butin était énorme. Enorme je dirais ! J'ai jamais vu autant de caisses. Bien, j'essayais d'expédier rapidement les choses alors j'ai commencé à décharger un peu plus que je ne pouvais soutenir. C'est à ce moment-là que tout s'est cassé la gueule.\n\nAvant que je sache ce qu'il se passait, j'ai vu cette peste de Magglish le Dingue filer avec une bouteille de porto vieille de 99 ans. Je l'ai poursuivi jusqu'aux Cavernes des lamentations. Pas question d'y rentrer, quand même.\n\nPeut-être êtes-vous suffisamment <courageux/courageuse> pour aller le retrouver ?", progress = "Le maître des docks est sur mon dos depuis que Magglish le Dingue a filé avec ce vieux porto. Je suppose que cette bouteille devait constituer un cadeau pour Gazlowe, de la part du baron Revilgaz en personne.\n\nSi vous êtes suffisamment courageux et patient pour rattraper Magglish le Dingue et rapporter le porto, je veillerai à ce que vous ayez une belle récompense.", completion = "Magnifique ! Et juste au moment où j'allais perdre mon travail en plus ! Je veillerai à ce que Gazlowe ait ce cadeau immédiatement.\n\nMerci, &lt;nom&gt;. Bon travail, je dirais !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[960] = {title = "Onu réfléchit", objective = "Je réfléchis, <nom>. Je réfléchis aux raisons de la présence du Marteau du crépuscule et des nagas.\n\nLorsque vous serez prêt utilisez la fiole de divination pour créer une coupe de divination.\n\nSi vous avez perdu votre fiole de divination, en voici un autre.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nFiole de divination"},
[961] = {title = "Onu réfléchit", objective = "La découverte de sectateurs du Marteau du crépuscule est inquiétante. Je dois réfléchir à leurs intentions…\n\nLorsque vous aurez plus d'informations, parlez-moi à travers une coupe de divination. Si vous avez besoin d'une nouvelle fiole de divination pour créer une coupe... en voici une.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nFiole de divination"},
[962] = {title = "Fleur de serpent", objective = "L'Apothicaire Zamah à Thunder Bluff veut que vous récoltiez 10 Fleurs de serpent.", description = "La Société royale des apothicaires, basée dans la grande ville d'Undercity de Lordaeron, m'a envoyée ici pour une mission très particulière, <nom>. Peut-être souhaitez-vous m'aider, et ainsi aider la Dame noire, dans nos efforts pour faire progresser les Réprouvés.\n\nJ'ai récemment étudié un spécimen rare de flore appelé Fleur de serpent. Je crois qu'en grande quantité cette herbe a un bon potentiel.\n\nMalheureusement, elle ne pousse qu’au plus profond des Cavernes des lamentations, un réseau de cavernes situé dans les Tarides.", progress = "J'ai hâte de voir si vous pouvez récolter assez de Fleurs de serpent dans les Cavernes des lamentations. J'ai envoyé beaucoup de gens dans ce but, mais personne n'est jamais revenu.", completion = "Ah, de splendides spécimens ! Vous avez agi à merveille, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nGants d'apothicaire"},
[963] = {title = "Un amour éternel", objective = "Libérer l'esprit d'Anaya Dawnrunner et rapporter son pendentif à Cerellean Whiteclaw à Auberdine.", description = "À la suite des batailles au Puits d'éternité, j'ai appris qu'Ameth'Aran avait été détruit, et son peuple tué, y compris mon bel amour Anaya.\n\nJe n'aurais jamais cru, des milliers d'années plus tard, que des souvenirs d'Anaya hanteraient toujours mes rêves. Frappé de stupeur, j'ai erré dans les bois de Sombrivage, et j’ai retrouvé les ruines d'Ameth'Aran... Là j’ai vu l'esprit hanté de ma bien-aimée.\n\nElle doit être libérée, mais je n'ai pas le cœur de faire cela. Son esprit doit être détruit.", progress = "Le cœur empli d'une immense tristesse, j'ai suivi Shan'do Stormrage jusqu'en hibernation, et j’ai emporté mes chagrins dans mes rêves, endormi pour des milliers d'années.", completion = "Merci, &lt;nom&gt;. Peut-être aurait-il été mieux que je m’en occupe moi-même. Mais même après ces milliers d'années, je n'aurais supporté de lever la main sur ma bien-aimée.\n\nJe vous en prie, laissez-moi seul avec mon chagrin…", rewards = "Vous recevrez :\n\nLarme de douleur"},
[964] = {title = "Fragments de squelette", objective = "Apporter 15 Fragments de squelette au Pharmacien Dithers à la Barricade, dans les Maleterres de l'ouest.", description = "La clé pour accéder à Scholomance s'appelle une Clé squelette. Elle doit être forgée à partir des restes d'un squelette - de plusieurs en fait - et doit être renforcée des métaux les plus robustes dans un moule particulier. Enfin, un sceau de pouvoir provenant d'une créature naturellement capable d'ouvrir le portail de Scholomance permettra à la clé d'avoir la fonction désirée.\n\nMais commençons par le commencement, <nom>. Nous allons avoir besoin de Fragments de squelette pour forger la clé. Les squelettes d'Andorhal devraient nous les fournir, mais ceux en dehors des murs devraient pouvoir faire l'affaire également.", progress = "Tuez beaucoup et tuez souvent, <classe> - il nous faudra suffisamment de fragments de squelettes pour façonner la couche externe de la clé. Elle ne s'appelle pas Clé squelette par hasard, vous savez.", completion = "Ça va marcher, &lt;nom&gt; ! À mon tour maintenant : je vais les imprégner de l'agent durcissant nécessaire à leur résistance au processus intense de forge qu'ils auront à traverser.\n\nLa prochaine étape sera de trouver un moule approprié pour la clé. Je connais un forgeron gobelin à Tanaris qui a fait, dans le passé, des moules pour des objets macabres semblables. Il travaille, à l'instar de tous les gobelins, pour celui qui paye le plus.", rewards = "Vous recevrez :\n\n"},
[965] = {title = "La Tour d'Althalaxx", objective = "Trouver Balthule Shadowstrike près de la Tour d'Althalaxx à Sombrivage.", description = "Salutations, jeune <race>. Je m'appelle Elissa Starbreeze, et il est de mon devoir de protéger Auberdine de tout mal.\n\nÀ cette fin, j'ai envoyé Balthule Shadowstrike observer les événements étranges qui se produisent près de la Tour d'Althalaxx au nord-est.\n\nIl aurait déjà dû revenir. J'ai peur qu'il ait rencontré un danger imprévu dans la forêt. J'apprécierais beaucoup si vous pouviez le trouver et vous assurer qu'il va bien.", progress = nil, completion = "Elissa vous a envoyé ? Alors ce sont de bons vents qui vous amènent. J'ai des nouvelles inquiétantes à lui transmettre, et n'avais pas de moyen de le faire.", rewards = "Vous recevrez :\n\n"},
[966] = {title = "La Tour d'Althalaxx", objective = "Collecter 4 Parchemins passés pour Balthule Shadowstrike près de la Tour d'Althalaxx.", description = "Un groupe de démonistes s'est établi autour et à l'intérieur de la tour. Je serais retourné à Auberdine pour rendre compte à Elissa plus tôt, mais j'avais peur de rater quelque chose une fois parti.\n\nDelgren suspectait qu'une telle compagnie puisse se rassembler à la tour, mais il n’en savait pas la cause.\n\nQuelques morceaux de parchemins appartenant à ces démonistes ont atterri entre mes mains, mais j'en ai besoin d'autres pour compléter le puzzle. Je vous avertis cependant de ne pas vous aventurer dans la tour, les démonistes qui s'y trouvent sont beaucoup trop puissants !", progress = "Avez-vous trouvé des parchemins ? Je serais capable de me faire une image plus précise du culte si vous en trouvez.", completion = "Merci beaucoup, &lt;nom&gt;. Cela devrait éclaircir un peu la raison du rassemblement de démonistes…\n\nHmmm… Le Culte de la Rive noire… Je n'ai jamais entendu parler de ce groupe jusqu'alors. N'ayant pas connaissance de leur histoire, il est impossible d’en déduire leurs plans.\n\nIl n'y a plus de temps à perdre. L'alerte doit être immédiatement donnée à Delgren.", rewards = "Vous recevrez :\n\n"},
[967] = {title = "La Tour d'Althalaxx", objective = "Remettre la Lettre de Balthule à Delgren le Purificateur dans la forêt d'Ashenvale.", description = "Mon maître, Delgren le Purificateur, est un paladin qui a gracieusement offert son assistance pour défendre nos forêts contre les démons et les morts-vivants. Il m'a beaucoup appris sur le Feu sacré et sur l'art de la bataille.\n\nDelgren doit être mis au courant des opérations du culte immédiatement.\n\nVous le trouverez loin au sud, au poste de Maestra dans la forêt d'Ashenvale. Faites vite, j'ai peur que la menace que représente la Rive noire n'augmente d'heure en heure.", progress = "Voulez-vous me parler d'une affaire, <classe> ?", completion = "Si cela ne vous dérange pas que je vous dise ça, vous avez l'air bien équipé pour un messager, pas vrai ? Je suppose que Balthule voulait être certain que sa lettre parvienne à bon port. Voyons ce qu'il a à dire…\n\nVoilà des nouvelles inquiétantes. Lorsque des forces démoniaques ou des morts-vivants sont découverts, j'aide les Sentinelles à les détruire.\n\nAu début, je n'étais pas accoutumé aux manières des elfes de la nuit, mais je les respecte grandement aujourd'hui en tant qu'alliés.", rewards = "Vous recevrez :\n\n"},
[968] = {title = "Les puissances d'en-bas", objective = "Apporter le Livre : Les puissances d'en bas à Gerrig Bonegrip, dans la caverne lugubre d'Ironforge.", description = "Bien qu'affreusement usé et égratigné, le titre est encore lisible sur la couverture :\n\nLes puissances d'en bas.\n\nÀ l'intérieur du livre écorné se trouve une liste de noms imprononçables affublés d'horribles titres, des méthodes de culte, des sacrifices conseillés... dont beaucoup incluent des créatures humanoïdes, vivantes.\n\nAu verso de la couverture, sont inscrits les mots suivants : \"Runes et malédictions de Bonegrip, la caverne lugubre, Ironforge. Propriétaire : Gerrig Bonegrip.\"\n\nSi Bonegrip vend de tels livres, peut-être qu'il rachètera celui-ci.", progress = "Salutations, Monsieur.\n\nPuis-je vous intéresser à l'un de mes livres ?", completion = "Ah ! Une copie des « Puissances d'en bas ». Un texte intéressant, on peut le dire. Et d'aucuns pourraient le trouver utile…\n\nMais celle-ci est dans un triste état. Et regardez ! Il y a des annotations en marge de presque toutes les pages !\n\nHum... Je connais cette copie. Je l'ai vendue à Bolgar l'année dernière. Êtes-vous... l'un de ses amis ? Oui, il me semblait bien que vous l'étiez ! Vous avez ce même feu dans le regard !\n\nBien, par définition, un ami de Bolgar est mon ami. Et l'on prend soin des siens, n'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[969] = {title = "Que la chance soit avec vous", objective = "Collecter 10 Eclats cognegivre pour le sorcier-docteur Mau'ari à Long-guet.", description = "Rien qu’à vous regarder, je vois que vous voulez un charme de chance. Mau'ari sait tout !\n\nLà-bas, dans le sud du Berceau, vous trouverez un canyon où les géants collectent des éclats de glace. Vous pouvez toujours prélever vous-mêmes des éclats sur le canyon. Ils ont une puissante qualité de réflexion.\n\nRapportez 10 Eclats cognegivre, et mon charme de chance sera à vous.", progress = "Rapportez ces éclats et je vous en dirai plus !", completion = "Ah, oui... Je vais faire ce médaillon pour vous, maintenant. Il vous suffit de patienter un peu !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[970] = {title = "La Tour d'Althalaxx", objective = "Trouver une Gemme d'âme luminescente et la rapporter à Delgren le Purificateur au poste de Maestra.", description = "La lettre de Balthule est désespérée. Ce culte de la Rive noire m'irrite au plus haut point et doit être éradiqué. J'ai eu affaire à quelques vermines de la Rive noire au nord-est d'ici à Ordil'Aran. L'un d'entre eux possède une gemme d'âme, qui je crois détient le secret de la puissance de ce culte.\n\nApportez-la-moi, et je serai capable de déchiffrer les secrets qu'elle contient.", progress = "Êtes-vous entré en possession de la gemme d'âme ?", completion = "Hmmm ! Une magie maléfique ensorcelle cette Pierre d'âme. Voyons quel piège elle recèle…", rewards = "Vous recevrez :\n\n"},
[971] = {title = "La connaissance des profondeurs", objective = "Apporter le « Manuscrit de Lorgalis » à Gerrig Bonegrip à Ironforge.", description = "Comme il se peut que vous le sachiez, je recueille le savoir. Le savoir ancien. Le savoir puissant. Le savoir qui ouvre les portes et le savoir qui réveille Ceux qui dorment.\n\nIl court des rumeurs sur une pièce de savoir, le Manuscrit de Lorgalis, loin dans les Profondeurs de Brassenoire, dans Ashenvale. Cet endroit est la demeure d'elfes depuis longtemps disparus. Des elfes qui avaient réuni de grandes connaissances avant que leur cité ne tombe en ruines.\n\nFouillez les Profondeurs de Brassenoire à la recherche du manuscrit. Faites-le, et je ne l'oublierai pas. Même pas après... les derniers jours.", progress = "La route pour Ashenvale est longue, et votre tâche n'est pas aisée. Mais si vous me procurez le manuscrit, <nom>... la récompense sera grande.", completion = "Vous avez trouvé le manuscrit ! Que ce jour est heureux ! Nous allons faire des copies et les distribuer, et le savoir ancien de Lorgalis sera enfin connu de mes frères et de mes sœurs !\n\nVous nous avez rendu un service tel que vous ne pouvez l’imaginer, &lt;nom&gt;. Mais j'espère que ce cadeau vous montrera la gratitude que nous exprimons à nos alliés.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nAnneau de soutien"},
[972] = {title = "Le sapta d'eau", objective = "Prenez le sapta d'eau et trouvez l'étendue d'eau corrompue dans la forêt des Pins argentés, <nom>. J'ai une grande confiance en vos compétences.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSapta d'eau"},
[973] = {title = "La Tour d'Althalaxx", objective = "Apporter le Tome d'Ilkrud Magthrull à Delgren le Purificateur au Poste de Maestra.", description = "Ilkrud Magthrull ? Oui, je le connais. Il s'agit d'un puissant démoniste orc qui s’est établi au Sanctuaire de Scarfeu, un endroit très maléfique dans le sud-ouest d'Ashenvale.\n\nIl n'a pas été plus qu'un simple désagrément jusqu'à présent, et je n'ai pas eu affaire à lui, mais il semble que le temps soit venu.", progress = "Vous semblez un peu secoué, <nom>. Vous allez bien ?", completion = "C'est une grande chose que vous avez accomplie aujourd'hui, &lt;nom&gt;. Vous pouvez être fier de vous pour avoir vaincu un démoniste d'une telle puissance.\n\nÀ présent, voyons ce que peuvent nous apprendre les écrits d'Ilkrud.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau du clergéBâton du purificateur\n\nVous recevrez également :\n\n"},
[974] = {title = "À la recherche de la source", objective = "Découvrir la zone la plus chaude de la crête de la Fournaise, pour Krakle, au cratère d'Un'Goro.\n\nQuand vous trouvez une zone de chaleur, cliquez avec le bouton droit de la souris sur le thermomètre afin de prendre la température. Continuez vos recherches jusqu’à avoir trouvé la zone la plus chaude.", description = "Les sources chaudes ne cesseront de m’étonner ; d’où vient cette chaleur ?\n\nVu à quel point les sources sont proches de la crête de la Fournaise, je me demande si l’influence du volcan n’est pas responsable. J’ai créé un thermomètre pour lire et enregistrer la température de différentes parties du volcan et trouver la plus chaude. La chaleur est exprimée en degrés Kraklenheit !\n\nVoici, prenez-le et faites des mesures de température sur la crête, dès que vous voyez un point chaud !", progress = "J'y serais bien allé moi-même, mais... J'ai peur des élémentaires de feu qui s'y trouvent !", completion = "Oui, finalement, je vois bien la corrélation entre la température du volcan et celle des sources chaudes. Je dois vérifier mes équations pour être le plus précis possible, mais vu la distance et la vitesse à laquelle la chaleur est transférée... Hm...", rewards = "Vous recevrez :\n\n"},
[975] = {title = "Cache de Mau'ari", objective = "Attendre un instant, puis reparler au sorcier-docteur Mau'ari pour recevoir le Charme de chance.", description = "Avant de vous donner ce charme, je vous expliquerai comment l’utiliser.\n\nSi vous le portez sur vous, vous trouverez certains objets spéciaux sur les créatures que vous combattrez. Sans le charme, pas d’objets spéciaux, vous voyez ?\n\nCes objets s’appellent des E'ko. Si vous trouvez n'importe lequel de ces objets, apportez-le à la vieille Mau'ari, qui saura vous aider.\n\nAttendez ici pendant que je prépare votre charme.", progress = nil, completion = "Voilà, &lt;nom&gt;. Souvenez-vous que vous devez le porter sur vous. Pourquoi ne pas retourner dans les terres sauvages pour voir ce que vous pouvez trouver là-bas ?", rewards = "Vous recevrez :\n\nCache de Mau'ari"},
[976] = {title = "De l’approvisionnement pour Auberdine", objective = "Parler à Delgren le Purificateur, au Poste de Maestra, après avoir escorté Feero à travers la Forêt d'Ashenvale.", description = "Delgren m'a demandé d'apporter un message et du ravitaillement à la Sentinelle Starbreeze à Auberdine, mais je déteste partir seul. La forêt regorge de dangereux adversaires et je ne veux pas prendre le risque que le ravitaillement ou des informations capitales tombent entre de mauvaises mains.\n\nSi vous et quelques autres pouvez m'accompagner en tant que gardes, je partirai tout de suite. Si vous nous protégez, aucun doute que ces marchandises arriveront à bon port.", progress = nil, completion = "Vous avez bien oeuvré aujourd'hui, &lt;classe&gt;. Les objets que nous avons envoyés pour aider Auberdine pourront être utilisés immédiatement pour contrer les sombres menaces qui infestent la forêt.\n\nAcceptez ceci en plus de mes sincères remerciements.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLanterne éternellePansière de Kor\n\nVous recevrez également :\n\n"},
[977] = {title = "Yéti ? Y es-tu ?", objective = "Collecter 2 Cornes de yéti en parfait état pour Umi Rumplesnicker, à Long-guet", description = "Maintenant que j’ai ce dont j’ai besoin pour construire les parties mécaniques mobiles, il ne me manque qu’une seule chose. Deux choses, en fait. Deux cornes !\n\nLes patriarches et matriarches Chardon de glace sont ceux qui ont les plus grandes cornes. Ces yétis se trouvent dans les grottes, au sud-est. Il y en a un grand nombre là bas, vous n’aurez pas de problèmes à les trouver.\n\nRappelez-vous que je ne veux que les plus belles cornes, sans la moindre éraflure !", progress = "Je suis sur le point de finir de travailler la fourrure, <nom>. S'il vous plaît, dépêchez-vous de me ramener les cornes !", completion = "J'ai hâte de les montrer à mes amis ! Patientez le temps que je les attache...\n\nParfait !", rewards = "Vous recevrez :\n\n"},
[978] = {title = "Les Indomptables lunaires", objective = "Collecter 10 Plumes de Chouettard lunaire, dans le Berceau-de-l'Hiver, puis retourner voir Erelas Ambersky, à Rut'theran.", description = "Les plumes d’Indomptables des Hinterlands contiennent des traces de magie. Toutefois, ces créatures ne semblent pas avoir de pouvoirs particuliers. La magie semble faire partie de leur essence.\n\nPendant mes études, j’ai entendu qu’une importante population d’Indomptables résidait dans les terres enneigées du Berceau-de-l'Hiver. Ces créatures auraient-elles les mêmes pouvoirs ? Aidez-moi à trouver les réponses à ces questions, <nom>. Allez au Berceau-de-l'Hiver et collectez des plumes qui traînent au sol, puis revenez me voir.", progress = "D'où ces pouvoirs peuvent-ils venir ? Je pense que nous sommes en bonne voie pour trouver la réponse, <nom>.", completion = "Maintenant je peux comparer les plumes... Voyons voir...", rewards = "Vous recevrez :\n\n"},
[979] = {title = "Trouver Ranshalla", objective = "Trouver Ranshalla dans l’est du Berceau-de-l'Hiver.", description = "Oui, oui, ces plumes semblent contenir le même enchantement que j'ai remarqué précédemment… Bien que je ne sache pas vraiment ce que nous pourrions découvrir, je vous conjure de continuer à chercher des réponses, <nom>.\n\nL'une de mes collègues a voyagé récemment au Berceau-de-l'Hiver afin d'y observer les Indomptables, dans leur habitat naturel. Pourquoi ne pas essayer de la retrouver et voir ce qu'elle a pu découvrir...", progress = nil, completion = "Salut ! Erelas vous a envoyé ? Formidable, je me préparais à monter dans les caves maintenant, et je ne refuserais pas un peu de compagnie.", rewards = "Vous recevrez :\n\n"},
[980] = {title = "Les nouvelles sources", objective = "Se rendre au Berceau-de-l'Hiver et parler à Donova Snowden.", description = "Il y a d’autres sources chaudes dans un endroit appelé le Berceau-de-l'Hiver, loin au nord. Ce qui est étrange, c’est qu’il n’y a pas de volcan à proximité ; intéressant n’est-ce pas ?\n\nSi vous voulez en apprendre plus, vous devriez aller au Berceau-de-l'Hiver et parler à une de mes amies. Son nom est Donova Snowden, et elle réside aux environs de ces sources.\n\nMerci de m’aider avec mon thermomètre et à plus tard !", progress = nil, completion = "Bonjour, &lt;nom&gt;. Oui, ce que Krakle vous a dit est vrai...", rewards = "Vous recevrez :\n\n"},
[981] = {title = "La Tour d'Althalaxx", objective = "Aller voir Delgren le Purificateur au Poste de Maestra.", description = "Vous méritez bien une récompense pour tout ce que vous avez accompli. Retournez voir Delgren et dites-lui qu'Athrikus Narassin gît à terre par vos soins et que le Culte de la Rive noire est vaincu et démantelé.", progress = nil, completion = "Je savais que vous seriez à la hauteur, &lt;nom&gt;.\n\nDe grandes prouesses vous attendent et vous aurez raison des maux qui pourrissent notre pays. Recevez ma bénédiction, &lt;nom&gt;, ainsi que ce cadeau.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChausses pieusesFrappe du Séraphin\n\nVous recevrez également :\n\n"},
[982] = {title = "Océan profond, mer immense", objective = "Récupérer le Coffret de l’Aube argentée et le Coffret du Voile de brume, pour Gorbold Steelhand, à Auberdine. Ces deux objets se trouvent à bord des épaves des navires respectifs, au nord du village.", description = "Au large de Sombrivage, plus au nord, il y a deux épaves de bateau : l’Aube argentée et le Voile de brume. Il y a quelque temps, ces deux bateaux sont tombés sur ces maudits murlocs, alors qu’ils faisaient voile à travers la vaste mer jusqu’à Auberdine. Ils reposent maintenant au fond des eaux, comme autant de trophées au crédit de ces démons.\n\nLes deux capitaines n’ont pas survécu et leurs journaux de bord et effets personnels sont toujours dans leurs coffrets. Je voudrais que vous les récupériez ; cela serait symboliquement très important pour tous les équipages de cette contrée.", progress = "Les capitaines de ces navires étaient des elfes de la nuit et ils méritent un meilleur destin que celui qu'ils ont connu. Nous devons nous occuper de leurs effets personnels, c'est le meilleur moyen de permettre à leurs esprits de trouver le repos.", completion = "Vous avez rendu un fier service à Auberdine, gamin. Nous veillerons à ce que l'on prenne grand soin de leurs effets.\n\nEt pour vous, veuillez accepter ceci. C'est le moins que l'on puisse faire pour remercier la personne qui a eu le courage de rétablir l'ordre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants goutte-de-puitsGantelets du collet\n\nVous recevrez également :\n\n"},
[983] = {title = "Bigobox 827", objective = "Réunir 6 Pattes de clampants et les mettre dans la bigobox 827.", description = "Hé ! J'ai besoin d'aide pour ma dernière invention, la bigobox. Elle permet de parler aux gens à distance !\n\nVous en avez peut-être déjà vu, ce sont des boîtes avec un levier dessus. Le seul problème, c'est qu'il faut une maintenance permanente.\n\nElles ont toutes un problème différent, mais j'ai eu une idée géniale. J'ai placé chacune d'elle près de la créature qui possède les éléments appropriés pour la réparer. En ce moment, la bigobox 827 est en panne. C'est juste au sud d'Auberdine, vraiment tout près. Il faut 6 pattes de clampants pour la réparer. Je vous payerai pour ça...", progress = "La bigobox 827 est posée là, dans un silence à faire frémir. Un simple clignotant indique qu'elle a besoin de 6 pattes de clampants pour fonctionner.", completion = "Alors que vous placez les pattes de clampants dans la machine, vous entendez des engrenages commencer à grincer. À en juger par les bruits de chocs qui émanent de la Bigobox, vous pensez que les pattes de clampants s'imbriquent à la place qui leur est destinée. Bientôt la machine commence à bourdonner, et vous entendez une voix minuscule qui en sort.\n\n\"Allô ? Euh... Salut ! Vous l'avez réparée ! C'est Wizbang ici ! Merci beaucoup... Hé, vous ne voudriez pas en réparer une autre, par hasard ?\"", rewards = "Vous recevrez :\n\n"},
[984] = {title = "Quelle est l'ampleur de la menace ?", objective = "Trouver un camp de furbolgs corrompus à Sombrivage et retourner voir Terenthis dans Auberdine.", description = "Certains de mes frères ont été sauvés de justesse d'un furbolg corrompu à Teldrassil, et je me suis juré d'arrêter ces atrocités avant que d'autres ne soient blessés... ou pire.\n\nJ'ai déjà vu des prémices de corruption à Sombrivage, mais il faut que je cherche d'autres signes ailleurs. Je pense qu'il serait logique de poursuivre les investigations auprès des furbolgs. Pourriez-vous trouver un de leurs camps et me dire s’il y a des signes de corruption ?", progress = nil, completion = "C'est vraiment une terrible nouvelle, &lt;nom&gt;.\n\nSi les furbolgs sont si près d'Auberdine, nous devons nous préparer à l'inévitable.\n\nMerci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[985] = {title = "Quelle est l'ampleur de la menace ?", objective = "Tuer 8 Guides et 5 Messagers du vent Noirbois puis retourner voir Terenthis à Auberdine.", description = "Vous avez déjà prouvé vos qualités dans le domaine de la reconnaissance, <nom>. Avez-vous aussi les qualités nécessaires pour affronter l'adversaire ?\n\nLes aventuriers ne préfèrent pas tous le combat direct à l'art de la ruse et de l'évasion.\n\nSi vous pensez être à la hauteur de la tâche, sachez que la plus grande menace pour notre peuple est aujourd'hui le camp furbolg au sud d'Auberdine. Vous y trouverez des furbolgs de la tribu Noirbois. Tuez 8 Guides et 5 Messagers du vent et revenez me voir.", progress = nil, completion = "Lavez le sang de vos vêtements, &lt;nom&gt; et ne pleurez pas sur ce que vous avez dû faire. Rendez grâces, plutôt. Vous avez éloigné la menace d'Auberdine, même si Sombrivage est toujours en danger par la faute des gangremousses.", rewards = "Vous recevrez :\n\n"},
[986] = {title = "Un maître perdu", objective = "Trouver 5 Belles peaux de traquelune et les apporter à Terenthis, à Auberdine.", description = "<nom>, votre habileté m'a déjà été utile. Puis-je à nouveau vous demander d'aider Griffe-sinistre et son maître Volcor ? Je vais vous fabriquer une cape magique qui vous permettra de vous déplacer librement au milieu des créatures de Sombrivage pendant que vous le chercherez.\n\nPour faire cette cape, j'ai besoin de cinq belles peaux de géniteur ou de matriarche traquelune. Vous trouverez ces tigres au sud de la Sinueuse ou beaucoup plus au sud, non loin d'Ashenvale.", progress = "En toute bonne conscience, je ne peux pas vous permettre de partir chercher Volcor avant d'avoir terminé votre cape.", completion = "Celles-ci feront l'affaire, &lt;nom&gt;. Je vais me mettre immédiatement au travail sur cette cape.\n\nDonnez-moi un peu de temps, puis revenez me voir.\n\nEncore une chose : l’utilisation de l'enchantement de la cape limite vos possibilités d'interactions avec les autres. Si possible, contentez-vous de parler. Si vous en faites plus, l'illusion disparaîtra.", rewards = "Vous recevrez :\n\n"},
[988] = {title = "<INUTILISÉ>", objective = "Parlez à Volcor.", description = "J'ai remarqué la cape que vous portez, <nom>. Si vous acceptez de la sacrifier, je peux utiliser sa magie pour m'échapper. Le problème, c'est que vous, vous resterez ici dans la caverne.\n\nPourrez-vous vous débrouiller pour sortir si nous choisissons cette solution ?\n\nJe peux vous assurer que Terenthis vous récompensera si vous faites le choix de m'aider.\n\nC'est à vous de trancher, mais j'ai vraiment besoin de votre aide.", progress = nil, completion = nil, rewards = nil},
[989] = {title = "<INUTILISÉ>", objective = "Parlez à Volcor.Si nous décidons de nous battre pour sortir, le plan est simple : nous tracerons notre route en tuant tous les furbolgs qui seront sur notre chemin... Ou tout ce qui voudrait essayer de nous arrêter.\n\nJ'espère qu'il y a un autre moyen, mais tôt ou tard il faudra affronter les furbolgs. Autant le faire nous-mêmes, nous serons sûrs que le travail a été fait.\n\nPrenez le temps de préparer vos armes ou vos enchantements, puis revenez me voir.", description = "Si nous décidons de nous battre pour sortir, le plan est simple : nous tracerons notre route en tuant tous les furbolgs qui seront sur notre chemin... Ou tout ce qui voudrait essayer de nous arrêter.\n\nJ'espère qu'il y a un autre moyen, mais tôt ou tard il faudra affronter les furbolgs. Autant le faire nous-mêmes, nous serons sûrs que le travail a été fait.\n\nPrenez le temps de préparer vos armes ou vos enchantements, puis revenez me voir.", progress = nil, completion = nil, rewards = nil},
[990] = {title = "Voyage vers Ashenvale", objective = "Trouver Raene Wolfrunner dans Ashenvale.", description = "<nom>, ma maîtresse, Raene Wolfrunner, vous attend à la cité d'Astranaar dans Ashenvale. Peut-être que grâce à vous, nous pourrons réduire la corruption qui y règne.\n\nEn partant d'ici, vous devez prendre plein sud en restant près de la route ; vous trouverez sans problème votre chemin en suivant cette direction.", progress = nil, completion = "Oh ! Un &lt;classe&gt; de Sombrivage. Selarin a bien fait de vous envoyer aussi vite, &lt;nom&gt;. J'espère que votre séjour ici ne sera pas trop stressant. Peut-être qu'avec votre aide nos affaires vont s'améliorer.\n\nJe commencerais ma visite ici en parlant aux autres citoyens d'Astranaar. Votre aide serait sûrement bienvenue chez certains.", rewards = "Vous recevrez :\n\n"},
[991] = {title = "Le nettoyage selon Raene", objective = "Trouver Teronis dans Ashenvale.", description = "<nom>, l'un de mes vieux amis est aussi venu à Ashenvale pour aider les Sentinelles, mais il est déjà reparti.\n\nIl cherchait un objet qui pourrait retarder les attaques des furbolgs contre notre peuple : un Bâtonnet créé par un sorcier diabolique, aujourd’hui mort.\n\nAvant de partir, il a dit qu'il cherchait une gemme pour ce Bâtonnet.\n\nIl pensait que la gemme était cachée dans le sanctuaire près du lac Falathim, au pied de la montagne à l'ouest. La gemme était là avant l’invasion.\n\nTrouvez mon ami, je vous en prie, <nom>.", progress = nil, completion = "Le corps de Teronis gît sur l'île. Pour une raison inconnue, les murlocs l'ont abandonné là.\n\nLes profondes entailles sur son cadavre sont signées par les armes et les griffes des murlocs.", rewards = "Vous recevrez :\n\n"},
[992] = {title = "Étude des eaux de Gadgetzan", objective = "Utiliser la Fiole de sourcier vide à la mare près du Guet de Tristesable. Une fois l'échantillon récolté, remettre la Fiole de sourcier pleine au grand géomètre Fizzledowser à Gadgetzan.", description = "Nous avons un poste temporaire vacant de géomètre novice à la Compagnie des Eaux de Gadgetzan, si ça vous intéresse !\n\nComme les nomades s'emparent de tous nos puits, nous devons exploiter tous les points d'eau libres ! Il y en a dans le désert, mais seulement pour ceux qui les étudient en premier.\n\nPrenez cette fiole de sourcier et récoltez un échantillon d'eau de la mare près du Guet de Tristesable. Juste sous le nez des trolls. Rapportez-moi la fiole pleine quand vous aurez fini !", progress = "Bienvenue, géomètre novice <nom> ! Avez-vous déjà terminé votre mission ?", completion = "Comment ? Vous avez dû combattre des bestioles rampantes ? Oh ça n'est pas bon pour la Compagnie des Eaux de Gadgetzan, je vous le dis…\n\nJ'aurais dû vous parler des rumeurs que des créatures insectoïdes semblent pomper toute l'eau dans le désert. Au début je croyais que c'était une blague. On a déjà assez de problème avec les nomades comme ça, j'ai pensé que c'était encore eux. Eh bien on est fixé maintenant !", rewards = "Vous recevrez :\n\n"},
[993] = {title = "Un maître perdu", objective = "Trouver Volcor, à Sombrivage, et lui donner la Cape enchantée de traquelune.", description = "La cape est terminée, <nom>. Nous devons trouver Volcor à présent. J'espère seulement que nous sommes encore dans les temps.\n\nLa magie de la cape, une fois invoquée, ne durera pas longtemps. Cinq minutes, peut-être. Ce sera à vous de choisir quand l'utiliser. Je suggèrerais d'attendre de trouver Griffe-sinistre.\n\nSi ce qu'il m'a dit est vrai, vous trouverez son maître dans une caverne au sud d'ici. Griffe-sinistre vous attendra le long de la route. Faites-lui un signe de la main lorsque vous le verrez et il vous indiquera la direction de son maître.", progress = nil, completion = "Merveilleux ! Terenthis a trouvé quelqu'un pour m'aider.\n\nEt regardez, une Cape de traquelune... &lt;il tousse&gt; Oh... Ça fait mal. Merci, &lt;nom&gt;.\n\nLes furbolgs m'ont blessé avant que je ne réussisse à leur échapper. Laissez-moi quelques instants et je serai en mesure de parler plus longuement.", rewards = "Vous recevrez :\n\n"},
[994] = {title = "Évasion par la force", objective = "Protéger Volcor jusqu'à la route puis aller voir Terenthis à Auberdine.", description = "Ça va, <nom>. Sortons de là. Nous nous fraierons un passage jusqu'à la route ; Griffe-sinistre devrait encore y être. Une fois là bas, nous pourrons nous séparer.\n\nTerenthis va vouloir que vous lui racontiez immédiatement ce qui s'est passé, vous irez donc à Auberdine dès que nous serons sortis vivants d'ici.", progress = nil, completion = "&lt;nom&gt; ! Je suis heureux de voir que vous avez réussi. En aidant Volcor, vous m'avez rendu la foi : nous surmonterons les défis qui nous attendent à Sombrivage et au-delà.", rewards = "Vous recevrez :\n\nCordelière inébranlable"},
[995] = {title = "Évasion par la ruse", objective = "S'échapper de la grotte des furbolgs et aller voir Terenthis à Auberdine.", description = "D’accord... si vous le voulez, nous nous échapperons d’ici.\n\nRappelez vous, une fois que vous aurez quitté ce lieu, allez à Auberdine et rencontrez Terenthis. C’est là que je vais me rendre aussi, et j’y serai probablement avant vous.", progress = nil, completion = "&lt;nom&gt; ! Je suis heureux de voir que vous avez réussi. En aidant Volcor, vous m'avez rendu la foi : nous surmonterons les défis qui nous attendent à Sombrivage et au-delà.", rewards = "Vous recevrez :\n\nPantalon du scarabée"},
[996] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[997] = {title = "La terre de Denalan", objective = "Rapporter le paquet de Terre rare à Denalan au lac Al'Ameth.", description = "Vous allez vers le sud ? Au lac Al'Ameth ? Si c'est le cas, j'ai une tâche à vous confier... \n\nMon collègue Denalan campe le long du rivage oriental du lac, où il étudie la flore de Teldrassil. Il a demandé qu'on lui envoie un paquet de Terre rare de Darnassus, mais il y a eu du retard et le paquet vient seulement d'arriver à Dolanaar.\n\nPouvez-vous le lui apporter ?", progress = "Vous avez quelque chose pour moi ?", completion = "Ah, elle est là ! J'attends cette terre rare depuis longtemps. J'espère qu'elle est encore fraîche… \n\nMerci de me l'avoir apportée, &lt;nom&gt;. Vous donnez votre temps sans compter, &lt;race&gt;.", rewards = "Vous recevrez :\n\n"},
[998] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Il commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[999] = {title = "Quand les rêves tournent aux cauchemars", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1000] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff, pour plus d'informations !", progress = nil, completion = "Salutations, &lt;classe&gt;.\n\nJe me réjouis de voir que des personnes telles que vous prennent de l'intérêt au bien-être de la nature. Vos faits d'armes sont parvenus jusqu'à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l'aide dont il avait besoin.\n\nNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.", rewards = "Vous recevrez :\n\n"},
[1001] = {title = "Bigobox 411", objective = "Rassembler 3 Yeux de batteur de Sombrivage au fond de la mer, près de la bigobox 411.", description = "Une petite voix crépite à l'intérieur de la machine.\n\n\"C'est Wizbang ! La prochaine Bigobox se trouve au nord d'Auberdine, sur la plage !\n\nCette Bigobox porte le numéro 411 et a besoin de 3 Yeux de batteur pour être réparée. Ils sont un peu au large de la côte ! Les Frappeurs de Sombrivage... *Hic*... Pardon...\n\nTout comme pour la dernière fois, quand vous donnerez les objets à la Bigobox, elle vous crachera votre récompense. *Hic*... Quoi ? Non, je vais bien !\"", progress = "L'écoutille de la machine s'est ouverte et elle semble attendre avec espoir qu'on y place 3 Yeux de batteur.", completion = "La bigobox reprend vie et commence à bourdonner dès que vous y placez les Yeux de batteur. Après un instant de silence, vous entendez une minuscule voix qui vous est familière.\n\n\" Le vin de clampant est le meilleur...\" *hic*\n\n\" Quoi ? Oh ! Vous l'avez dé-déjà réparée ? Ouah, v-v-vous êtes un ra-rapide ! Vous-vous voulez en ré-réparer une autre ?\"\n\nIl vous semble entendre un liquide versé dans un verre, suivi de forts bruits de déglutition.", rewards = "Vous recevrez :\n\n"},
[1002] = {title = "Bigobox 323", objective = "Trouver 6 Crocs de traquelune et les mettre dans la bigobox 323.", description = "La bigobox se tait un instant puis vous entendez Wizbang commencer à parler.\n\n\"La-la bigobox suivante est la numéro 323. L'est au nord d'Auberdine mais... Où est la bière ? Hein ? Oh ! C'est sur-sur la route alo-lors ça ne devrait pas-pas être dif-difficile de la trou-trouver près du pont.\"\n\nWizbang marmonne quelque chose d'incohérent puis vous entendez un bruit de déglutition sonore.\n\n\" Il f-f-faut des Crocs de traquelune... 6 cro-crocs.\"", progress = "Bien que vous n'ayez pas encore placé les 6 Crocs de traquelune à l'intérieur de la machine, vous croyez y entendre des divagations incohérentes en gnome. Quelqu'un d'autre a-t-il déjà réparé la machine ?", completion = "La bigobox se met soudain en marche et vous entendez distinctement des bruits de dents qui en sortent. \n\n\"A-Alors, c'est f-fait ? Exc-ellente nou-nouvelle... B-B-bon... On continue ? Oh ! À moins qu-que vous ne vouliez f-faire autre cho-chose !\"", rewards = "Vous recevrez :\n\n"},
[1003] = {title = "Bigobox 525", objective = "Se procurer 4 Scalps vieillis sur de Vieux ours des chardons au sud d'Auberdine et les placer dans la Bigobox 525.", description = "En plus du bruit de fond et des sons écœurants qui viennent de la machine, vous entendez la voix hésitante de Wizbang appeler.\n\n\"Au-autre au s-sud en bas de l-la route. Ne devrait pa-pas trop dur à trouver... juste au b-bord... près d'une clôture. Je p-pense que je l'ai ca-cachée dans un beu-beu... buisson. Hé hé hé !... Ouais, la bigobox 525 a be-besoin de s-scalps vieillis de vieux ou-ours des chardons. Garçon, une autre ! Vi-vieillis... Hé hé hé !...\"\n\nVous entendez déglutir tandis que la machine s'arrête. Puis soudain, elle éructe.\n\n\"4 !\"", progress = "La bigobox 525 se met à chanter – faux.\n\n\"L'vin de clampant est exchellent, la bi-bière d'batteur encore meilleure, et l'alcool d'traquelune peut faire la une. Mais ri-rien ne vaut la bi-bière d'ours des chardons, et bien-bientôt j'm'en s'rais mis plein l’bedon !\" \n\nL'écoutille baille et avale ses 4 scalps vieillis d’ours tandis que la chanson boucle sur le refrain.", completion = "Vous-vous avez mis les scalps d-dedans ? Gé-génial... Hein ? Ah oui ! Je-je su-suppose que vous-vous avez v-vu que je peux p-parler aux gens sans-sans mettre les trucs d-dans m-ma machine. Mais je disais la vé-vérité quand je d-disais qu'elles étaient ca-cassées !\n\nVous v-voyez, en plus de serv-servir à communiquer, les bigobox f-font aussi de la dis-distillation de-d'excellents s-spiritueux. Dé-désolé pour le dérangement, mais les elfes de-de la nuit n'apprécient p-pas le débit de boi-boissons que je viens d’ouvrir dans leur v-ville. Je vous ai m-mis un ca-cadeau cuvée spéciale dans ce-cette boîte pour v-vous montrer ma gra-gratitude. Appréciez, c’est du bon !", rewards = "Vous recevrez :\n\nSacoche de WizbangBière spéciale de Wizbang"},
[1004] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff, pour plus d'informations !", progress = nil, completion = "Salutations, &lt;classe&gt;.\n\nJe me réjouis de voir que des personnes telles que vous prennent de l'intérêt au bien-être de la nature. Vos faits d'armes sont parvenus jusqu'à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l'aide dont il avait besoin.\n\nNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.", rewards = "Vous recevrez :\n\n"},
[1005] = {title = "Ce qui se cache au-delà", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1006] = {title = "Ce qui est au-delà", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1007] = {title = "L'ancienne statuette", objective = "Apporter l'Ancienne Statuette à Talen, dans son camp près de la grève de Zoram.", description = "Je vais vous charger d'une mission, <nom>.\n\nJ'étais sur mon petit bateau, voguant sur les ruines englouties de Zoram, quand les nagas ont émergé des eaux et m'ont attaqué en me déchirant avec leurs griffes ! Je me suis enfui, en transportant tout ce que je pouvais pour le camp.\n\nEt lorsque j'ai atteint le rivage, je me suis mis à courir... J'ai perdu ma précieuse cargaison.\n\nJe vous en prie, <nom>, retrouvez l’endroit où je suis tombé dans cette embuscade et cherchez une ancienne statuette. C'est pour elle que j'ai bravé les dangers de la grève de Zoram.", progress = "Avez-vous trouvé la statuette, <nom> ?", completion = "Vous l'avez ! Merci, &lt;nom&gt; !\n\nLa vieille cité de Zoram renferme de nombreux secrets et cette statuette est peut-être la clé qui nous permettra de les découvrir.", rewards = "Vous recevrez :\n\n"},
[1008] = {title = "La grève de Zoram", objective = "Apporter 20 Têtes d'Irequeue à Shindrell Swiftfire, à Astranaar.", description = "Il y a un endroit sur notre côte nord-ouest, connu sous le nom de grève de Zoram.\n\nC'est là que se trouve la cité perdue de Zoram, détruite pendant le Fractionnement et submergée par les eaux. Cela fait une éternité que les elfes de la nuit l'ont perdue. Perdue et presque oubliée.\n\nAujourd’hui, les nagas y sont retournés et nous ne savons pas pourquoi. Mais la raison importe peu : nous devons tuer ces démons et les rejeter dans les profondeurs !\n\nRevenez me voir quand votre mission sera achevée.", progress = "Nous ne parvenons pas à empêcher les nagas d'envahir nos côtes, <nom>. Il est vital que vous alliez à la grève de Zoram achever votre mission.", completion = "Félicitations, &lt;nom&gt;. Ce que vous avez accompli contre les nagas sur la grève de Zoram est digne de louanges.\n\nJe sais qu'il n'était pas facile d'accomplir cet exploit, car la force et la ruse des nagas sont bien connues des elfes de la nuit. Nous les connaissons, car nous avons une longue histoire en commun.\n\nUne histoire que je n'ai pas envie de répéter.", rewards = "Vous recevrez :\n\n"},
[1009] = {title = "Ruuzel", objective = "Apporter l'Anneau de Zoram à Talen près de la grève de Zoram.", description = "J'ai peur que les secrets de l'ancienne statuette ne restent un mystère tant que vous n'aurez pas trouvé la clé qui ouvre cette vieille serrure.\n\nCette clé est un anneau, l'Anneau de Zoram. Il a appartenu aux dirigeants de cette cité avant que les ondes du Fractionnement ne l'aient noyée.\n\nL'anneau a été perdu pendant des années, mais les nagas viennent de le retrouver.\n\nLeur chef, Ruuzel, se trouve sur une île, sur le côté nord de Zoram. Je vous en prie, <nom>, trouvez-moi cet anneau !", progress = "On dit que l'Anneau de Zoram ouvre toutes les serrures de la cité. L'avez-vous trouvé, <nom> ?", completion = "Vous avez trouvé l'Anneau ! Merci, &lt;nom&gt;. Je vous en prie, acceptez ceci en paiement et sachez que ce que vous avez fait restera gravé pour toujours dans ma mémoire.", rewards = "Vous recevrez :\n\nRobe des temps anciens"},
[1010] = {title = "Les Cheveux de Bathran", objective = "Rapporter 5 Cheveux de Bathran à Orendil Broadleaf dans Ashenvale.", description = "Il y avait une plante qui poussait autrefois dans les vieilles ruines du repaire de Bathran au nord. On l'appelait Cheveux de Bathran et elle était réputée guérir les maux de l'esprit.\n\nIl y a un enfant malade dans le village et je crois qu'il s'agit d'autre chose que d'une simple maladie physique. Accepteriez-vous d'aller au repaire de Bathran pour y chercher des Cheveux de Bathran ? Il se peut que j'en ai besoin pour soigner cet enfant.\n\nLe repaire de Bathran se trouve au nord du Poste de Maestra, juste au sud de la frontière de Sombrivage.", progress = "Avez-vous cueilli les Cheveux de Bathran, <nom> ? La santé de l'enfant décline d'heure en heure…", completion = "Ah, vous avez les Cheveux ! Je vais pouvoir préparer un remède pour l'enfant en priant que mon mélange fasse effet.\n\nEt... Il y a des Réprouvés au Repaire de Bathran ? Ça m'ennuie d'entendre cela. Ça m'ennuie vraiment…", rewards = "Vous recevrez :\n\n"},
[1011] = {title = "Les maladies des Réprouvés", objective = "Apporter une Bouteille des maladies à Kayneth Stillwind au Chant des Forêts.", description = "Les Réprouvés, le bras mort-vivant de la Horde, ont rampé jusqu'en Ashenvale, et rôdent près de nos ruines et de nos refuges des saisons. Nous pensons que leur objectif est de répandre la maladie sur les terres des elfes de la nuit. Nous devons nous en assurer !\n\nLes Réprouvés ont un camp au sud d'ici, près du refuge des saisons de Dor'danil. Ils y conçoivent poisons et maladies et les placent dans des bouteilles. Frayez-vous un passage jusqu'à ce camp et volez une de ces bouteilles pleines. Revenez alors me voir. J'expérimenterai cette maladie et découvrirai à quelles fins elle a été conçue.", progress = "Avez-vous trouvé le camp, <nom> ? Avez-vous rapporté une Bouteille des maladies ?", completion = "Très bien, &lt;nom&gt;. Maintenant... Nous allons analyser le contenu de cette bouteille pour comprendre ce que voulaient faire les Réprouvés !", rewards = "Vous recevrez :\n\n"},
[1012] = {title = "Les druides fous", objective = "Tuer les druides : Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak ; puis retourner auprès de Kayneth Stillwind au Chant des Forêts.", description = "Lorsque je me battais avec les poisons des Réprouvés, j'ai eu une vision. J'ai vu les druides du Refuge des saisons de Dor'danil empoisonnés... Assassinés par les morts-vivants ! Ils sont désormais des fantômes errants, séparés de leurs corps et se conduisant comme des fous.\n\nPour que les esprits des druides puissent retrouver la paix, vous devez entrer dans le Refuge des saisons de Dor'danil et éliminer leurs grands chefs : Taneel Darkwood, Uthil Mooncall et Mavoris Cloudsbreak.\n\nFaites cela et revenez me voir.", progress = "Mes rêves sont toujours remplis d'angoisse à cause des druides de Dor'danil, <nom>. Vous devez éliminer leurs chefs !", completion = "J’ai senti mon angoisse diminuer au sujet du Refuge des saisons de Dor'danil et j'ai su que vous aviez achevé votre tâche.\n\nC’était une tâche difficile à accomplir, &lt;nom&gt;, car les esprits que vous avez détruits n'étaient que les victimes du mal des Réprouvés. Mais avec leur destruction, nous pouvons espérer que les autres esprits torturés retrouvent la paix.", rewards = "Vous recevrez :\n\nFlamme d'Emil"},
[1013] = {title = "Le Livre d'Ur", objective = "Apporter le \"Livre d'Ur\" au Gardien Bel'dugur à l'Apothicarium à Undercity.", description = "<nom>, il y a un livre dans le donjon d'Ombrecroc, le « Livre d'Ur », qui ferait très bon effet dans ma collection. Ur était un grand mage de Dalaran avant l'arrivée du Fléau, les études qu'il a faites dans certains domaines ont beaucoup de valeur aux yeux de certains... parmi les Réprouvés.\n\nPénétrez dans le donjon d'Ombrecroc et trouvez ce livre. Apportez-le-moi et je ferai part de votre action à notre Dame noire.", progress = "Vous avez trouvé le livre, <nom> ?", completion = "Très bien. Ce livre va gentiment s'ajouter à ma collection sur les travaux d'Ur. Il avait de grandes connaissances, mais sa conscience l'a empêché de détenir le véritable pouvoir. Alors quand le Fléau est venu et l'a obligé à faire usage de sa force, il a échoué.\n\nNous, les Réprouvés, nous ne pouvons pas nous permettre une telle faiblesse si nous voulons survivre...\n\n... Si nous voulons vaincre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes grisonnanteBrassards cerclés d'acier\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1014] = {title = "Arugal doit mourir", objective = "Tuer Arugal et apporter sa Tête à Dalar Dawnweaver au Sépulcre.", description = "Arugal se trouve toujours dans le Donjon d'Ombrecroc. Nous ne pouvons pas faire des Pins argentés une forteresse stratégique pour la Dame noire tant qu'Arugal est vivant.\n\nJe vais me débrouiller pour que sa magie soit annihilée, <nom>. Mais je vous laisse le soin de faire en sorte qu'Arugal rencontre la mort qu'il sert si bien.\n\nAllez au Donjon d'Ombrecroc pour mettre fin une fois pour toutes aux charmes crasseux d'Arugal. Apportez-moi la tête de ce vil sorcier !", progress = "Grâce à la mort d'Arugal, nous sommes en mesure de renforcer le pouvoir de la Dame noire sur Lordaeron.", completion = "La forêt des Pins argentés est enfin libérée du vice de cet Arugal de malheur. Vous avez rendu à la Dame noire un grand service, &lt;nom&gt;. Votre ténacité sera récompensée.", rewards = "Vous allez être la cible du sort suivant :\n\nIntelligence des Arcanes\n\nVous recevrez :\n\nSceau de Sylvanas"},
[1015] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Fandral Staghelm, dans l'Enclave cénarienne, à Darnassus. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide Fandral Staghelm, dans Darnassus, pour plus d'informations !", progress = nil, completion = "Qu'est-ce qui vous fait penser que je veux être enquiquiné par des gens de votre acabit, &lt;classe&gt; ? Allons, j'arrête mes importantes activités quotidiennes pour vous aider à localiser un truc-machin quelque part. Bien entendu, le bien de Darnassus - non, de tout Teldrassil - passe après la récupération d'un nouveau bidule pour votre collection.\n\nCes idiots de Reflet-de-Lune me font déjà perdre mon temps avec leurs demandes d'aide, et maintenant, il faut que je supporte ça ?", rewards = "Vous recevrez :\n\n"},
[1016] = {title = "Les bracelets d'élémentaire", objective = "Récolter 5 Bracelets élémentaires intacts et utiliser le Parchemin de divination sur eux. Ensuite, apporter le Parchemin de divination à la Sentinelle Velene Starstrike au Refuge de Vent-argent.", description = "Prenez ce Parchemin de divination, il pourra nous apprendre qui a créé ces élémentaires. Mais vous aurez besoin d'une chose qui leur appartienne et que l’on pourra utiliser comme réactif pour focaliser la magie du parchemin ; leurs bracelets, par exemple, devraient faire l’affaire.\n\nQuelques bracelets intacts suffiront. Les autres bracelets ne serviront pas nos desseins mais pourront être revendus auprès d’un marchand. Une fois que vous aurez les bracelets intacts, essayez d’utiliser le Parchemin. Revenez avec le résultat de l'expérience et nous verrons quelle suite donner aux événements.", progress = "Comme vous devez détruire les Bracelets pour tuer les Élémentaires, il ne sera pas facile de trouver ceux qui contiennent les informations dont le Parchemin de divination a besoin. Vous pouvez échanger les bracelets avec d'autres personnes pour obtenir ceux qu'il vous manque, à moins que vous n'ayez déjà le parchemin ?", completion = "Bon travail, &lt;nom&gt;, cela devrait nous permettre d'obtenir les informations dont nous avons besoin pour démasquer le coupable. Que pensez-vous de nous débarrasser du mage qui a infesté nos étangs avec des élémentaires corrompus ? La corruption qui afflige la région d'Ashenvale me retourne l'estomac ; savoir qu'un sorcier tente de la détruire est un véritable supplice. Nous devons le faire payer.", rewards = "Vous recevrez :\n\n"},
[1017] = {title = "Mage invocateur", objective = "Tuer Sarilus Foulborne et apporter sa Tête à la Sentinelle Velene Starstrike au Refuge de Vent-argent.", description = "Il n'y a qu'un seul mage mort-vivant dans les Tarides capable de souiller autant d'élémentaires d'eau. C'est aussi le seul suffisamment idiot pour le faire. Sarilus Foulborne est probablement assis au sommet du pic de Brume-funeste, en train de se moquer de moi.\n\n<nom>, vous devez pénétrer en territoire ennemi et éliminer ce scélérat. J'en ai assez de sa stupidité et nous devons lui montrer ce qui arrive à ceux qui s'en prennent aux Sentinelles.\n\nTuez-le et apportez-moi sa tête. Mais soyez <prudent/prudente>, il se peut que la Horde vous surveille.", progress = "C'est fait ? Sarilus Foulborne est mort ?", completion = "Son répugnant sourire est figé pour toujours sur son visage. Vous avez bien agi, &lt;nom&gt;. Prenez ceci, la Lumière d'Elune. Vous la boirez lorsque tout semblera perdu et que vous frôlerez la mort. Elle vous sauvera peut-être, par la volonté de la déesse.", rewards = "Vous recevrez :\n\nLumière d'Elune"},
[1018] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide, Hamuul Runetotem, sur la Cime des Anciens de Thunder Bluff, pour plus d'informations !", progress = nil, completion = "Salutations, &lt;classe&gt;.\n\nJe me réjouis de voir que des personnes telles que vous prennent de l'intérêt au bien-être de la nature. Vos faits d'armes sont parvenus jusqu'à mes oreilles, et je vous souhaite la bienvenue. De vous voir ainsi devant moi ne me laisse plus aucun doute : le Cercle cénarien vient de recevoir l'aide dont il avait besoin.\n\nNotre intelligence avec le Cercle cénarien de Reflet-de-Lune transcende tout conflit racial ou politique. Rappelez-vous que vous travaillez au nom du Cercle, et je ne crois pas me tromper en pensant que vous le ferez bien.", rewards = "Vous recevrez :\n\n"},
[1019] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Fandral Staghelm, dans l'Enclave cénarienne, à Darnassus. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide, Fandral Staghelm, dans Darnassus, pour plus d'informations !", progress = nil, completion = "Qu'est-ce qui vous fait penser que je veux être enquiquiné par des gens de votre acabit, &lt;classe&gt; ? Allons, j'arrête mes importantes activités quotidiennes pour vous aider à localiser un truc-machin quelque part. Bien entendu, le bien de Darnassus - non, de tout Teldrassil - passe après la récupération d'un nouveau bidule pour votre collection.\n\nCes idiots de Reflet-de-Lune me font déjà perdre mon temps avec leurs demandes d'aide, et maintenant, il faut que je supporte ça ?", rewards = "Vous recevrez :\n\n"},
[1020] = {title = "Jouvence d'Orendil", objective = "Apporter la Jouvence d'Orendil à Pelturas Whitemoon dans Astranaar.", description = "<nom>, j'ai mis au point un traitement qui, je pense, devrait guérir cette pauvre enfant. Apportez-le à Astranaar et donnez-le à son père, Pelturas Whitemoon.\n\nPour atteindre Astranaar, suivez la route par le sud puis par l'est.", progress = "Pardonnez-moi mais je n'ai pas le temps de discuter. Mon enfant, Relara, est gravement malade !", completion = "Cela vient d'Orendil ?\n\nSa réputation de médecin et d'herboriste n'est plus à faire. Ce remède me redonne de l'espoir, alors que je n'en avais plus...", rewards = "Vous recevrez :\n\n"},
[1021] = {title = "Vil satyre ! dryades en danger !", objective = "Trouver Anilia dans Xavian.", description = "Écoutez, je ne sais pas qui vous êtes, mais j'ai besoin de votre aide. Mes sœurs sont allées reprendre la branche de Cénarius au satyre. Elles ont dit qu'elles seraient vite de retour, mais il y a deux jours entiers qu'elles sont parties !\n\n<nom>, vous devez les trouver ! Elles cherchaient les ruines d'un temple des elfes de la nuit au nord-est de Xavian. Je ne sais que penser. Cherchez Anilia, c'est elle qui menait la recherche.", progress = nil, completion = "Si on en juge par la blessure béante à son côté, Anilia est sur le point de mourir.", rewards = "Vous recevrez :\n\n"},
[1022] = {title = "Le Val hurlant", objective = "Se rendre au Val hurlant et étudier le « Tome de Mel'Thandris », puis retourner voir la Sentinelle Melyria Frostshadow au Sanctuaire d'Aessina.", description = "Bien que nous ayons dépensé beaucoup d'énergie pour repousser les démons encore présents de Gangrebois jusqu'au nord, nous n'avons pas eu beaucoup de succès. Nous avons pu éviter toute présence démoniaque à Ashenvale.\n\nAu nord, près de la frontière de Gangrebois, de mystérieux hommes-loups ont investi le sanctuaire en ruine de Mel'Thandris. Leurs cris sont si terrifiants qu'on a surnommé ce secteur le Val hurlant. Le « Tome de Mel'Thandris » qui est gardé dans le sanctuaire peut faire la lumière sur la raison de la venue de ces hommes-loups.", progress = nil, completion = "Le « Tome de Mel'Thandris » fonctionne d'une étrange façon. Les événements qu'il enregistre, les événements qu'il montre... Personne ne comprend vraiment pourquoi il agit ainsi.\n\nCependant, il est clair que ce que la prêtresse Velinde Starsong a reçu, cette Faux d'Elune, mérite d'autres investigations.", rewards = "Vous recevrez :\n\n"},
[1023] = {title = "Le nettoyage selon Raene", objective = "Trouver la Gemme luminescente et retourner voir Raene Wolfrunner dans Astranaar avec le Journal de Teronis.", description = "En fouillant les affaires de Teronis, vous trouvez un journal qui est encore en bon état.\n\nVous prenez le journal et laissez le cadavre de Teronis comme il est.\n\nIl ne vous reste plus qu'à trouver la gemme que Teronis cherchait. Raene a dit qu'elle était dans le secteur. Peut-être que les murlocs l'ont prise...", progress = "Ah ! Bienvenue de nouveau, <nom>.", completion = "C'est terrible, &lt;nom&gt;. Teronis est mort !\n\nLe temps du deuil viendra, mais pour le moment nous devons concentrer nos efforts. J'enverrai quelques Sentinelles pour ramener le corps de Teronis dès que possible.\n\nVous avez le journal de Teronis et la gemme qu'il cherchait. Pensez-vous être capable d'achever sa tâche ? Je ne serai en repos qu'en sachant que sa mort n'a pas été inutile.", rewards = "Vous recevrez :\n\n"},
[1024] = {title = "Le nettoyage selon Raene", objective = "Trouver Shael'dryn, au Puits de lune, au nord-est.", description = "Vous devrez chercher par vous-même, mais d'après les notes de Teronis, il semble que la prochaine étape soit de trouver les autres morceaux du Bâtonnet que Dartol a créé. Je commencerais par me diriger vers le puits de lune à l'est du lac Iris. Suivez la route et prenez au nord lorsque vous atteindrez une petite zone de repos sur votre gauche.\n\nVotre meilleur guide sera une dryade du nom de Shael'dryn. Cherchez-la.\n\nPrenez la Gemme avec vous : Shael'dryn en aura besoin si elle doit vous aider à réparer le Bâtonnet.", progress = "Bonjour. Comment allez-vous ?", completion = "Oh ! C'est Raene qui vous envoie ? Cela doit être sérieux alors. Que puis-je faire pour vous ?", rewards = "Vous recevrez :\n\n"},
[1025] = {title = "Une défense agressive", objective = "Tuer 1 Protecteur, 2 Ursas, 10 Totemiques et 12 Guerriers de la tribu Vile-sylve, puis retourner voir Raene Wolfrunner, à Astranaar.", description = "Avant que vous n'alliez au Puits de lune, j'ai une autre tâche à vous confier pour aider les habitants d'Ashenvale, si ça vous dit de tester vos compétences.\n\nLe long de la route qui commence à l'est, avant le fleuve Falfarren, les furbolgs ont attaqué des voyageurs. Leurs esprits tordus se nourrissent de la peur qu'ils causent et seul le sang des innocents les rassasie.\n\nAidez les Sentinelles à protéger nos terres en rendant à ces monstres la monnaie de leur pièce.\n\nJe crois que leurs camps sont au sud de la route... Faites preuve de prudence.", progress = nil, completion = "Vous avez bien fait, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\nPain de maïs moelleuxJus de melon"},
[1026] = {title = "Le nettoyage selon Raene", objective = "Trouver la Clé en bois et un morceau du Bâtonnet de Dartol avant de retourner voir Shael'dryn au Puits de lune.", description = "Je regrette que vous n'ayez pas de meilleures nouvelles.\n\nRaene a raison, je sais ce qu'avait créé Dartol et je connais les tréants du secteur – du moins je les connaissais. Désormais, ils sont corrompus et leur nature a changé.\n\nVotre mission est de rapporter le morceau suivant du bâtonnet, mais vous devez d’abord trouver la clé qui ouvre le coffre qui contient le morceau.\n\nLa Clé en bois est sur l'un des tréants au nord-est, près de Gangrebois. Une fois que vous l'aurez, cherchez une petite clairière à l'ouest de la route près de la lisière de Gangrebois... Le coffre devrait être caché par là.", progress = "Je suis triste de voir que les tréants sont aujourd'hui corrompus. Je regrette de ne rien pouvoir faire pour les aider.", completion = "Je suis heureuse de vous voir de retour, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1027] = {title = "Le nettoyage selon Raene", objective = "Trouver le dernier morceau du Bâtonnet de Dartol et retourner voir Shael'dryn au puits de lune.", description = "Le dernier morceau du Bâtonnet a été donné aux druides de Dor'danil, qui en assurent la garde. Je n'ai aucune idée de l'endroit où ils l'ont caché. Je suis désolée de ne pas pouvoir mieux vous aider.\n\nTout ce que je peux vous dire, c'est de suivre la route qui mène aux Tarides. Les druides se sont réfugiés à l'est de cette route, mais ils ne vous seront pas très utiles : ils ont été tués récemment... C'est une chose à laquelle j'évite de penser.\n\nQuand vous aurez trouvé le dernier morceau, apportez-le-moi et je vous aiderai à réparer le Bâtonnet.", progress = "Avez-vous trouvé le dernier morceau du Bâtonnet, <nom> ?", completion = "Vous avez trouvé le dernier morceau ? C'est merveilleux pour vous... et pour Raene.\n\nJe pense qu'il faut maintenant réparer, n'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[1028] = {title = "Le nettoyage selon Raene", objective = "Trouver l'Autel caché et recharger le Bâtonnet de Dartol.", description = "Le Bâtonnet est terminé, <nom>. Le réparer, c'était facile... Ce qui va nous donner plus de mal, c'est d’atteindre l'Autel qui a le pouvoir de le recharger.\n\nAvec de la concentration et des efforts, cela ne devrait pas être trop dur pour quelqu'un comme vous, qui a déjà tant accompli.\n\nPartez vers le sud-est, il y a très peu de chemins, et ne perdez pas le nord de vue – et faites preuve de prudence. L'Autel est caché dans les montagnes qui entourent cette prairie.\n\nUne fois arrivé, placez le Bâtonnet sur l'Autel... Le reste relève de la magie.", progress = "Vous sentez une force subtile, mais puissante, qui émane de l'autel et des arbres qui l'entourent.\n\nVous placez le Bâtonnet sur l'Autel et un doux vrombissement s'élève autour de vous, tandis que l'Autel se met à rougeoyer...", completion = "Lorsque le rougeoiement s'arrête, le Bâtonnet repose, à nouveau enchanté, dans le bassin de l'Autel.", rewards = "Vous recevrez :\n\nBâtonnet de transformation de Dartol"},
[1029] = {title = "Le nettoyage selon Raene", objective = "Retourner voir Raene Wolfrunner à Astranaar.\n\nObjet fourni : \n", description = "Je vous suggère d'aller trouver Raene pour lui dire que le bâtonnet est terminé. Elle saura vous dire quelle est votre prochaine mission. \n\nBonne chance, <nom>.", progress = nil, completion = "Vous avez réparé le bâtonnet que cherchait Teronis ? C'est merveilleux !\n\nIl serait fier de savoir que sa quête continue, même après sa tragique disparition.", rewards = "Vous recevrez :\n\n"},
[1030] = {title = "Le nettoyage selon Raene", objective = "Trouver un furbolg non corrompu et lui parler en utilisant le pouvoir du Bâtonnet de transformation de Dartol.\n\nObjet fourni : \n", description = "Hélas, je ne sais pas ce qu'il comptait faire ensuite.\n\nSi ce qu'il a dit sur le pouvoir du bâtonnet est vrai, alors il devrait vous permettre de prendre une autre forme. Laquelle, je ne sais pas.\n\nPeut-être qu'il voulait utiliser ces pouvoirs pour approcher les furbolgs infectés, mais même les créatures non corrompues l'auraient abattu s'il avait manqué de prudence. Transformé par le bâtonnet, Dartol aurait pu parler à un furbolg ayant échappé aux effets de la gangremousse.\n\nVous devriez commencer vos recherches au sud-est du lac Mystral.", progress = nil, completion = "Oui, oui... Vous êtes de la même espèce que moi, mais toujours intègre. Toujours sain.\n\nJe ne sais comment vous avez échappé aux atrocités que les elfes de la nuit font subir à notre peuple, mais je suis heureux de savoir que je ne suis plus seul.\n\nLa corruption s'est maintenant emparée de notre famille, la corruption s'est abattue sur nous par la faute des orgueilleux elfes de la nuit. Ce sont eux les responsables... Ce sont eux que je blâme pour avoir été rejeté par ma tribu.\n\nLa nuit, je vois toujours les feux de camp brûler dans l'obscurité.", rewards = "Vous recevrez :\n\n"},
[1031] = {title = "La branche de Cénarius", objective = "Tuer Geltharis et rendre la Branche de Cénarius à Illiyana au Sanctuaire d'Aessina.", description = "Anilia pose ses mains sur vos épaules et vous attire vers elle. Haletante, elle indique l'arche au nord, avant de fermer les yeux pour toujours. \" Il l'a pris... Geltharis...\" Au fond du cœur, vous comprenez que le dernier souhait d'Anilia est de voir la branche de Cénarius à nouveau entre les mains des dryades.", progress = "Vous les avez trouvées ? Qu'a dit Anilia ? Où est-elle ?", completion = "Anilia est morte ? Non… Ce n'est pas possible ! Pas plus tard qu'hier, nous avons couru et joué ensemble dans les bois.\n\nCe temps-là vient de prendre fin…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet des féesCeinturon en écailles luisantes\n\nVous recevrez également :\n\n"},
[1032] = {title = "Mort aux satyres !", objective = "Apporter 16 Cornes de satyre à Illiyana, au Sanctuaire d'Aessina.", description = "Je n'arrive pas à croire qu'Anilia ne soit plus là. Nous avions l'habitude de jouer ensemble dans la forêt. Je me sens presque... triste.\n\nJe sais ce qui pourrait me faire me sentir mieux. Si vous pouviez massacrer les satyres qui m'ont pris Anilia ! Rapportez-moi leurs cornes comme preuve de leur mort ; si vous faites cela, vous gagnerez mon éternelle gratitude.", progress = "S'il vous plaît, aidez-moi à venger la mort d'Anilia.", completion = "Merci, cher &lt;nom&gt;. Vos efforts réjouissent l'esprit de ma sœur.", rewards = "Vous recevrez :\n\n"},
[1033] = {title = "Larme d'Elune", objective = "Apporter une Larme d'Elune à Pelturas Whitemoon à Astranaar.", description = "J'espérais que le remède d'Orendil sauverait Relara, mais je crains qu'il ne puisse que ralentir la progression de la maladie qui terrasse mon enfant. Nous devons trouver des médicaments plus efficaces ! Heureusement, Orendil m'a parlé d'un autre remède à essayer au cas où le premier échouerait.\n\nLa Larme d'Elune est une variété de pierre qu'on ne trouve qu'en un seul endroit : l'île du lac Iris, à l'est d'Astranaar. Orendil a dit que cette pierre soignerait Relara... Je vous en prie, <nom>, apportez-moi la Larme d'Elune et priez pour qu'elle guérisse mon enfant !", progress = "<nom>, avez-vous trouvé le lac Iris ? Avez-vous la Larme ?", completion = "Oh ! Vous l'avez trouvée ! Je vais la mettre dans un ragoût et prier pour que cela la guérisse.\n\nMerci ! Merci, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[1034] = {title = "Les ruines de Chimétoile", objective = "Rapporter 5 Poignées de Poussière d'étoile à Pelturas Whitemoon à Astranaar.", description = "La Larme d'Elune a un peu amélioré l'état de ma fille. Ses cauchemars ont diminué et je remercie la déesse pour sa bénédiction. Mais... la fièvre n'a pas baissé.\n\nOrendil m'a parlé d'une poussière dépolie que l'on trouve dans les Ruines de Chimétoile. Peut-être qu'elle diminuerait la fièvre de Relara. Trouvez un peu de cette poussière, et rapportez-la-moi, je vous en prie.\n\nLes Ruines de Chimétoile se trouvent au sud, <nom>. Puisse Elune vous faire revenir rapidement !", progress = "Avez-vous déjà la Poussière d'étoile, <nom> ?", completion = "Vous avez trouvé de la poussière d'étoile ! Je vais en faire un cataplasme, cela devrait faire baisser la fièvre.\n\nEncore merci, &lt;nom&gt;. Sans votre aide, mon enfant serait sûrement morte.", rewards = "Vous recevrez :\n\n"},
[1035] = {title = "Le lac Tombeciel", objective = "Reprendre une Pierre de lune tombée à l'Oracle Sombretaillis puis l'apporter à Pelturas Whitemoon à Astranaar.", description = "La fièvre de Relara est tombée, mais elle est toujours très faible. Je ne crois pas que sa force reviendra avec le temps. Il va falloir le pouvoir d'une pierre de lune.\n\nNous avions l'habitude d'en ramasser au lac Tombeciel au sud-est... jusqu'à ce que les Sombretaillis s'y installent.\n\nLeur chef, un oracle, a ramassé toutes les pierres tombées de la lune et les conserve. Vous devez maintenant lui reprendre une pierre de lune.\n\nMais pour ça, je crains que vous ne soyez dans l'obligation de le tuer.", progress = "Avez-vous affronté l'Oracle Sombretaillis, <nom> ? Si c’est le cas, je vous en prie, remettez-moi vite la pierre de lune tombée. Relara n'a presque plus la force de respirer !", completion = "Oh, &lt;nom&gt; ! Vous avez sauvé ma fille ! Je savais que le pouvoir de la pierre de lune rendrait sa force à ma fille !\n\nJe ne pourrai jamais vous remercier assez pour votre aide, mais... S'il vous plaît, acceptez ceci. En dehors de Relara, c'est mon plus cher trésor.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArmure du ruisseauManiques bestialesAmict luminescent\n\nVous recevrez également :\n\n"},
[1036] = {title = "En avant toute, jeune mariole !", objective = "Parler à l’amiral Firallon, à bord du Voile cramoisi, au large de la côte de la vallée de Strangleronce.", description = "<nom>... Oui, j'ai entendu parler de vous ; vous n'êtes pas l'<ami/amie> de Baie-du-Butin, exactement comme nous, les boucaniers de la Voile sanglante. L’amiral Firallon recherche des volontaires vigoureux et enthousiastes comme vous pour une mission spéciale.\n\nSi cela vous intéresse, trouvez le Voile cramoisi et parlez avec l'amiral, sous le pont. Le navire est ancré plus à l’est, au large de la Côte sauvage, à proximité du Courant et de La Chance de la demoiselle.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[1037] = {title = "Velinde Starsong", objective = "Parler à Thyn'tel Bladeweaver à la Terrasse des guerriers de Darnassus.", description = "Velinde Starsong m'a précédé dans la forêt d'Ashenvale. Au début, elle semblait contrôler la situation dans Gangrebois, mais peu à peu ses résultats ont faibli. Un beau jour, elle a tout simplement disparu.\n\nOn m'a envoyé ici pour continuer sa mission. Cependant, j'ai bien peur de ne rien savoir d'elle. Peut-être que Thyn'tel Bladeweaver, l'un des commandants des Sentinelles, a du nouveau sur sa disparition, des détails que j’ignorerais.\n\nElle comprendra certainement l'importance de ce genre d'informations.", progress = nil, completion = "Velinde Starsong ? Tout le monde ou presque sait que la prêtresse a disparu il y a quelque temps. Quant à fournir de nouveaux détails sur les circonstances de son départ... Il faudrait une bonne raison pour que je divulgue ces informations.", rewards = "Vous recevrez :\n\n"},
[1038] = {title = "Les effets personnels de Velinde", objective = "Fouiller le coffre de Velinde pour trouver son Journal et le rendre ensuite avec la clé à Thyn'tel Bladeweaver à Darnassus.", description = "Le « Tome de Mel'Thandris » vous a montré cela ? Je suppose qu'il n'y a pas grand mal à vous permettre d'examiner ses affaires. Cette clé ouvrira le coffre dans lequel nous avons stocké ses effets, dans le baraquement des Sentinelles. Elle a tenu un journal de sa mission, s'il y a quoi que ce soit à apprendre, ce sera là-dedans.\n\nJe dois ajouter que les Sentinelles croient qu'elle avait des raisons personnelles de partir et s'attendent à ce qu'elle revienne à tout moment. La prêtresse a fait beaucoup dans le passé pour gagner notre confiance.", progress = "Qu'avez-vous découvert ?", completion = "Il semble que la disparition de Velinde soit plus troublante qu'elle ne semblait au départ. Mais même aujourd'hui, je ne peux pas croire qu'elle soit passée du mauvais côté. Peut-être devrions-nous établir le contact avec elle.\n\n&lt;nom&gt;, vous avez montré un réel intérêt pour cette histoire, j'aimerais que vous m'accordiez votre aide.", rewards = "Vous recevrez :\n\n"},
[1039] = {title = "Le port des Tarides", objective = "Aller voir le Maître des docks Dizzywig à Ratchet.", description = "Ratchet est le seul port des Tarides. L'hypothèse la plus probable est que Velinde a trouvé à Ratchet un navire de commerce pour la conduire à la crique des Flots noirs, en Azeroth. Nous avons des relations limitées avec les gobelins qui gèrent le port, mais le Maître des docks devrait avoir des informations sur les arrivées et les départs des passagers des bateaux.\n\nSuivez la route au sud-est d'Ashenvale et vous arriverez dans les Tarides. Faites preuve de prudence, <nom>, les guerriers de la Horde patrouillent dans le secteur. Mais au port, vous serez en sûreté.", progress = nil, completion = "Un &lt;race&gt;, hein ? Faut admettre qu'il n'y en a pas beaucoup comme vous, par ici. Cherchez quelqu'un, hein ? Je suis sûr que je l'ai quelque part dans mes registres.\n\nIl y a plein de gens qui voyagent par ici, mais donnez-moi juste un instant.", rewards = "Vous recevrez :\n\n"},
[1040] = {title = "Passage à Baie-du-Butin", objective = "Prendre un bateau pour Baie-du-Butin et aller voir le Caravanier Ruzzgot.", description = "Oh oui ! Enfin trouvé. Z'auriez dû me dire qu'elle était passée il y a longtemps. Voyons.\n\nVelinde Starsong. Passage réservé à Baie-du-Butin sur le « Balbuzard noir ». Je n'ai rien d'autre là-dedans, donc je suppose qu'il est arrivé à bon port.\n\nJe ne peux pas faire grand'chose de plsu pour vous. Elle a cependant demandé comment voyager par voie de terre de l'autre côté et je lui ai indiqué Ruzzgot, un chef de caravane basé à Baie-du-Butin. Peut-être que cette Velinde a voyagé avec lui.\n\nMaintenant dégagez. Je n'ai pas toute la journée à vous consacrer.", progress = nil, completion = "Oui ? Vu que vous n'avez pas l'air d'avoir besoin de moi pour transporter des marchandises, de deux choses l’une : soit vous cherchez du travail – et il n'y a aucune place en ce moment dans ma caravane –, soit vous vous adressez au mauvais gobelin.\n\nQue voulez-vous ?", rewards = "Vous recevrez :\n\n"},
[1041] = {title = "La route de la caravane", objective = "Aller voir le greffier Daltry à Darkshire.", description = "S'avère que j'ai eu tort à propos de vous et que ça n'arrive pas tous les jours.\n\nJe viens juste de me rappeler de cette Velinde que vous cherchez. Pas tous les jours qu'une prêtresse des elfes de la nuit veut voyager dans une vieille et sale – mais parfaitement adaptée à vos transports de marchandises ! – caravane comme la mienne.\n\nNous avons pris ensemble le chemin vers le nord, elle se dirigeait vers Darkshire. L'employé là-bas tient à jour toutes sortes d'informations. Pourrait savoir quelque chose d'utile.\n\nFaites preuve de prudence dans la jungle, c'est un endroit mortel même dans les bons jours.", progress = nil, completion = "Avec tous les événements étranges de ces dernières années, j'essaie d'avoir les meilleurs rapports possibles avec les étrangers. On ne sait jamais quand ça pourrait servir... Mais c'est drôle quand c'est le cas. Ce n'est pas pour suggérer quoi que ce soit à propos de cette Velinde Starsong que vous cherchez…", rewards = "Vous recevrez :\n\n"},
[1042] = {title = "La famille Carevin", objective = "Aller voir Jonathan Carevin à Darkshire.", description = "Non, je n'ai reçu aucun rapport concernant une Velinde Starsong résidant à Darkshire... Quoique, si vous voulez mon avis, j'aie du mal à imaginer une prêtresse elfe de la nuit prenant une chambre à l'auberge, si vous voyez ce que je veux dire.\n\nPour ce qui est des hommes-loups que vous mentionnez, j'en ai entendu parler. Justement l'autre jour, Calor est rentré en ville avec une guirlande de leurs têtes. Il travaille avec la famille Carevin. Des chasseurs de démons, de morts-vivants et autres monstres. Allez voir Jonathan, c'est le chef de famille.", progress = nil, completion = "Les temps sont vraiment sombres. Chaque branche qui s'agite murmure de mauvaises nouvelles et le mal se cache sous chaque pierre.\n\nEt c'est dans de tels moments qu'un étranger entre dans ma maison et me parle des worgens... Je ne demande aucun pardon pour mes soupçons, seulement des réponses.\n\nEt des réponses, j'en aurai.", rewards = "Vous recevrez :\n\n"},
[1043] = {title = "La Faux d'Elune", objective = "Chercher les signes de la Faux d'Elune puis retourner voir Jonathan Carevin à Darkshire.", description = "Votre histoire sonne juste... Je ne comprends pas bien vos motifs, mais si vous venez dans le bois de la Pénombre pour le débarrasser de quelques worgens, je ne vais plus chercher à comprendre.\n\nIl y a une mine au sud, que les worgens ont envahie... Ils sont apparus de nulle part, mais d'après ce que nous savons, c'est là qu'on les a vus pour la première fois.\n\nFaites votre boulot, mais si vous découvrez quoi que ce soit d'important, je vous demande de m'en faire part. Nous acceptons l'aide de tout le monde dans notre guerre contre le Mal.", progress = nil, completion = "Votre histoire est intéressante, &lt;nom&gt;. Quoique l'influence de la famille Carevin ne soit pas assez grande pour que nous puissions y trouver la source de ces problèmes et en finir avec eux une fois pour toutes. Mais nous ferons ce que nous pourrons pour limiter le nombre des worgens dans le bois de la Pénombre.\n\nJ'ai déjà chargé Calor d'en faire sa priorité.", rewards = "Vous recevrez :\n\n"},
[1044] = {title = "Réponses aux questions", objective = "Retourner vers Thyn'tel Bladeweaver à Darnassus.", description = "Nous maîtriserons le problème des worgens, n'ayez aucune crainte là-dessus. Ce mal que votre amie a introduit dans nos bois sera contenu et je ne lui en veux pas pour ses actions. Des événements étranges surviennent en ce moment, <nom> et l'obscurité ne connaît aucun répit.\n\nJe ne vous retiens pas plus. Je soupçonne que d'autres ont entendu parler de ce que vous avez trouvé dans les mines du bois de la Pénombre.", progress = nil, completion = "Ainsi voilà ce qu'il est advenu de Velinde, n'est-ce pas ? La Grande prêtresse sera attristée de l'apprendre, car elles étaient amies avant sa disparition. Cependant, la Faux d'Elune lui avait sûrement été donnée en récompense par notre déesse, et cela me trouble de savoir qu'elle n'est plus aux mains de ses servantes.\n\nMais un problème à la fois. Je vous dois d'immenses remerciements pour ce que vous avez accompli.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc LunarisBaguette d'éclat lunaire\n\nVous recevrez également :\n\n"},
[1045] = {title = "Le nettoyage selon Raene", objective = "Tuer Ran Dent-rouge et 4 Gardes de Dent-rouge, puis retourner voir Krolg près du lac Mystral.", description = "Les elfes de la nuit sont aussi vieux que le temps, mais leur arrogance détruit leur monde même. Et maintenant elle détruit aussi nos vies. Mais on ne peut plus rien contrôler... \n\nJe blâme les elfes pour beaucoup de choses, mais nous sommes toujours responsables de nos actions. Même sans la corruption, nous sommes capables de mauvaises choses.\n\nRan Dent-rouge est de ce genre de créatures démoniaques. La soif de pouvoir, la luxure... La corruption n'a fait qu'aggraver les choses. Je brûle de haine pour les elfes, mais je n'appelle pas la maladie sur leurs enfants, parce que nous devons maintenir l'ordre chez les nôtres.", progress = nil, completion = "Vous avez réussi, mon ami.\n\nLa forêt est toujours infestée, mais au moins nous avons contribué à lui rendre un peu de son ancienne gloire. Si vous souhaitez me revoir, j'en serai ravi.\n\nBonne route. Peut-être qu'un jour nos tribus se rencontreront à nouveau, dans des circonstances plus paisibles.", rewards = "Vous recevrez :\n\n"},
[1046] = {title = "Le nettoyage selon Raene", objective = "Apporter le Crâne de Ran Dent-rouge et le Bâtonnet de transformation de Dartol à Raene Wolfrunner à Astranaar.", description = "Retournez dans votre tribu pour raconter votre victoire.\n\nMontrez-leur votre trophée et appréciez la gloire que vous venez de conquérir…", progress = "Les Sentinelles font ce qu'elles peuvent ici dans Ashenvale, mais c'est grâce à des gens comme vous, <race>, que nous avons gagné la terre dont nous disposons.", completion = "Ainsi, voilà le crâne du plus féroce furbolg d'Ashenvale ?\n\nC'est un grand bonheur de vous savoir aussi habile, &lt;nom&gt;. Les Sentinelles ne pourront jamais assez vous remercier. J'espère que nous pourrons à nouveau compter sur vous pour aider notre peuple.\n\nJe vais mettre ce crâne et le Bâtonnet de Dartol à la place d'honneur pour que les autres les voient.\n\nTeronis serait fier de vous. Encore une fois merci.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre glacialeEventreuse\n\nVous recevrez également :\n\nAnneau d'argent pur"},
[1047] = {title = "La nouvelle frontière", objective = "Parler à l’archidruide Fandral Staghelm, dans l'Enclave cénarienne, à Darnassus. Evoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.", description = "Votre attention !\n\nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d'honorables représentants pour agir en son nom.\n\nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l'archidruide Fandral Staghelm, dans Darnassus, pour plus d'informations !", progress = nil, completion = "Qu'est-ce qui vous fait penser que je veux être enquiquiné par des gens de votre acabit, &lt;classe&gt; ? Allons, j'arrête mes importantes activités quotidiennes pour vous aider à localiser un truc-machin quelque part. Bien entendu, le bien de Darnassus - non, de tout Teldrassil - passe après la récupération d'un nouveau bidule pour votre collection.\n\nCes idiots de Reflet-de-Lune me font déjà perdre mon temps avec leurs demandes d'aide, et maintenant, il faut que je supporte ça ?", rewards = "Vous recevrez :\n\n"},
[1048] = {title = "Au monastère écarlate", objective = "Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod et le maître-chien Loksey, et retourner faire son rapport à Varimathras à Undercity.", description = "Pendant que la Dame noire s'occupe du problème urgent posé par l'avance du roi-liche au nord, je me préoccupe de ce qui se passe par ici.\n\nAucun doute, les parasites humains qui se nomment la Croisade écarlate sont l’épine à l'intérieur même de nos terres. Les Clairières de Tirisfal grouillent littéralement de ces petites fourmis rouges.\n\nAllez au Monastère, <classe>, et faites disparaître le Grand Inquisiteur Whitemane et ses lieutenants les plus importants.", progress = nil, completion = "Vous avez bien servi la Dame noire, &lt;classe&gt;. Pas facile, ce que je vous avais demandé.\n\nJ'ai noté votre fidélité aux Réprouvés. Et je me souviendrai de votre ténacité au combat.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée de malédictionCanne du ProphèteCollier du sang de dragon\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1049] = {title = "Compendium des Déchus", objective = "Trouver le « Compendium des Déchus » au Monastère dans les Clairières de Tirisfal et retourner voir le Sage Truthseeker à Thunder Bluff.", description = "Le Cercle terrestre avait des intentions pures envers nos frères tourmentés. Mais qui connaît les motivations de ceux qui chuchotent aux oreilles du Conseil des Anciens ?\n\nLes Réprouvés auxquels nous nous sommes alliés ont un lourd passé de duperie. Notre pacte a été trop hâtif. Peut-être Cairne aurait-il été sage de tenir compte des avertissements d'Orgrimmar.\n\nLe cœur du Monastère écarlate abrite le « Compendium des Déchus », gardé par des humains fanatiques et fous furieux. Ils tirent leur méthode de leur folie, mais leurs recherches pourraient s'avérer utiles.", progress = "Cairne est un chef noble et courageux et je lui confierais ma vie. Mais il en est d'autres dont je me méfie, compte tenu du climat politique actuel.\n\nUne fois que j'aurai la possibilité d'accéder à toute la connaissance disponible, je pourrai conseiller le Chef.\n\nAvez-vous eu la chance de visiter les Clairières de Tirisfal ? Le Monastère écarlate ? Le « Compendium des Déchus » n'est qu'une partie de cette énigme compliquée...", completion = "Le « Compendium des Déchus » ! Je commençais à me demander si ce livre existait vraiment !\n\nVous avez bien servi les taurens de Thunder Bluff, &lt;nom&gt;. Votre dévouement ne sera pas oublié.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nVil ProtecteurTarge de ForcestoneOrbe Oméga\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1050] = {title = "Mythologie des Titans", objective = "Reprendre « la Mythologie des Titans » au Monastère et le rapporter au Bibliothécaire Mae Paledust à Ironforge.", description = "L'avenir est inévitable ! Nous nous lançons vers lui comme les gouttes de pluie tombent dans la Grande mer.\n\nMais peut-être qu'en étudiant le passé, nous pourrons savoir à quoi nous attendre pour mieux nous préparer.\n\nAvant que Lordaeron ne connaisse ces événements sinistres, il y avait un bastion de connaissance caché dans les Clairières de Tirisfal. La rumeur disait qu'un livre appelé « la Mythologie des Titans » avait été placé dans la bibliothèque du vieux Monastère.\n\nRetrouvez-le et peut-être qu'ensemble nous pourrons découvrir les secrets du passé !", progress = "Le monastère était un séminaire pour les paladins en cours d'entraînement. C'était autrefois une forteresse de la Lumière, mais il est tombé dans les mains des fanatiques fous de la Croisade écarlate.\n\nLa Croisade s'imagine que son but est noble : nettoyer la terre du Fléau mort-vivant. Mais la folie lui a fait perdre tout sens commun, et maintenant elle voit des ennemis partout.\n\nApportez-moi « la Mythologie des Titans » pour que je puisse l'étudier et le mettre à l'abri à Ironforge.\n\nLes halls corrompus du monastère ne sont pas un endroit pour un trésor d'une telle valeur historique.", completion = "Vous avez retrouvé le texte sacré !\n\nC'était sans conteste une tâche difficile et votre voyage a été long. Mais les nains d'Ironforge vont tirer un grand bénéfice de votre succès.\n\nMerci, &lt;nom&gt;, au nom de la Ligue des Explorateurs.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nRecommandation de la Ligue des explorateurs"},
[1051] = {title = "La vengeance de Vorrel", objective = "Rapporter l'anneau de mariage de Vorrel Sengutz à Monica Sengutz à Moulin-de-Tarren.", description = "Bien que ma volonté soit intacte, je ne peux plus servir la Dame noire. Je sens que mes jours sur Azeroth vont prendre fin. Ma force de vie vole en éclats.\n\nC'est l'œuvre de l'Interrogateur Vishas ! Il m'a torturé pendant des semaines ! Il a pris mon anneau de mariage et l'a donné à sa femme. Le bâtard !\n\nVengeance... Je veux ma vengeance !\n\nCe pompeux imbécile s'est vanté de sa précieuse femme, Nancy, qui vit le long du lac de Lordamere. Traquez cette femme, assassinez-la et rendez mon anneau de mariage à ma femme Monika, à Moulin-de-Tarren.\n\nExaucez mes dernières volontés...", progress = "Que voulez-vous, vous que je ne connais pas ?", completion = "Vorrel a mené une existence si troublée. Et quel bon camarade de travail c'était... \n\nMaudits soient ces sales humains !\n\nVorrel est mort, il ne reviendra jamais à la vie. J'ai au moins la consolation de savoir que vous l'avez vengé. Pour cela, je vous remercie.\n\nMaintenant, laissez-moi seule pour pleurer...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet de malédictionCape d'acier sinistre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nBottes de Vorrel"},
[1052] = {title = "Sur le chemin écarlate", objective = "Apporter la Lettre de recommandation du Frère Anton à Raleigh le Dévot à Southshore.", description = "Nous, les membres de la Croisade écarlate, nous revendiquons des forteresses de Hearthglen aux Clairières de Tirisfal. Nous sommes assez fiers des bastions de nettoyage que nous avons installés partout dans Lordaeron.\n\nVous avez fait vos preuves contre les morts-vivants de Désolace. Mais la vraie menace de cette peste se trouve à Lordaeron.\n\nFaites route jusqu'à la ville de Southshore, dans les Royaumes de l'est. Cherchez-y un croisé nommé Raleigh le Dévot. Remettez-lui cette lettre de recommandation portant mon cachet et il vous donnera une place d'honneur dans notre monastère.", progress = "Qui va là ? Que voulez-vous de moi ?", completion = "Le Frère Anton répand toujours la bonne parole de la Croisade écarlate ? Bon sang...", rewards = "Vous recevrez :\n\n"},
[1053] = {title = "Au nom de la Lumière", objective = "Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod de la Croisade et le maître-chien Loksey, et retourner faire un rapport à Raleigh le Dévot à Southshore.", description = "J'ai servi autrefois la Croisade écarlate avec honneur, fidélité et fierté. J'ai cru que sa cause était noble : débarrasser Azeroth des morts-vivants.\n\nMais lorsque je suis allé au Monastère, dans les Clairières de Tirisfal, je me suis rendu compte combien les frères perdaient le sens des réalités. Aujourd'hui, ils sont persuadés que tous ceux qui ne portent pas leur tabard sont des êtres tourmentés. Des hommes et des femmes innocents ont été torturés sous prétexte qu'ils étaient tourmentés.\n\nLa Croisade écarlate doit être écrasée au nom de la Lumière. C'est vous, <nom>, qui devez renverser ce régime fourvoyé.", progress = nil, completion = "Même si les disciples de la Lumière ne se délectent jamais de la perte d'une vie, nous devons parfois accepter de tels sacrifices pour le bien du royaume et la planète.\n\nPar vos actions au Monastère, vous avez épargné beaucoup de vies innocentes, &lt;nom&gt;. Je salue votre ténacité.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée de sérénitéMordosMenace noireOrbe de Lorica\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1054] = {title = "Diminution de la menace", objective = "Apporter le Crâne de Dal Griffesang à Raene Wolfrunner à Astranaar.", description = "Les furbolgs Crins-de-Chardon sont au nord d'Astranaar. Mes éclaireurs m'ont appris que leur nombre a très fortement augmenté ces derniers mois. S'ils deviennent trop nombreux, ils pourraient bien trouver le courage d'attaquer Astranaar...\n\nTuez-en autant que possible, mais surtout apportez-moi le crâne de leur chef pour me prouver que vous les avez arrêtés... Au moins pour l'instant.\n\nJe vais rester à Astranaar pour attendre de vos nouvelles. Qu'Elune soit avec vous !", progress = "La corruption des furbolgs a terni la gloire et le lustre passés d’Ashenvale.", completion = "Bien joué, &lt;nom&gt;.\n\nNous sommes sous la menace constante des furbolgs. Heureusement, ça va les tenir à distance quelque temps.", rewards = "Vous recevrez :\n\nBaume de restauration"},
[1055] = {title = "Le nettoyage selon Raene", objective = "Retourner voir Shael'dryn au puits de lune.", description = "Le Bâtonnet, maintenant achevé, repose entre vos mains. Shael'dryn va vouloir apprendre votre réussite.", progress = nil, completion = "Vous avez réussi, &lt;nom&gt; ! Bravo !", rewards = "Vous recevrez :\n\n"},
[1056] = {title = "Voyage au pic des Serres-Rocheuses", objective = "Voyager pour aller voir le Gardien Albagorm au pic des Serres-Rocheuses.", description = "Les Esprits de la forêt m'ont dit que vous aviez du courage et que vous vouliez voyager.\n\nAu sud, près du lac Mystral, il y a un tunnel nommé la Perce des Serres. Par ce tunnel, vous arriverez dans un secteur connu sous le nom de la Combe des Cisailles, dans les Serres-Rocheuses. Une fois là-bas, faites route vers le sud-ouest, devant le lac de la Combe et ensuite vers le nord, en prenant la montée jusqu'au pic des Serres-Rocheuses.\n\nLe Gardien Albagorm vous y attend. Tenez compte de ce qu'il vous proposera, <nom>.\n\nLe voyage sera périlleux.", progress = nil, completion = "Finalement, vous voilà. Je vois que Faldreas a écouté les esprits de la forêt….", rewards = "Vous recevrez :\n\n"},
[1057] = {title = "À la reconquête du Val calciné", objective = "Le Gardien Albagorm du pic des Serres-Rocheuses veut que vous tuiez 7 Harpies, 7 Embusqués, 7 Tueuses et 7 Volplumes Rougefuries.", description = "En tant que protecteur des esprits de la forêt, vous pouvez sans aucun doute deviner pourquoi je suis alarmé.\n\nVous avez voyagé à travers ces montagnes pour atteindre ce pic, et avez sûrement vu les changements terrifiants qu'a subi la terre. La cupidité a mené à la destruction de ces collines sacrées.\n\nLe Val calciné, au sud, a été consumée par une avide armée mécanique. Pire encore, les Rougefuries qui ont empiété sur ce territoire nous en interdisent l'accès et nous empêchent d’y prospérer à nouveau.\n\nChassez ces affreuses harpies, <nom> !", progress = nil, completion = "À présent que les Rougefuries ont essuyé de telles pertes, le véritable travail pour restaurer la terre peut peut-être commencer…", rewards = "Vous recevrez :\n\n"},
[1058] = {title = "Magie de la forêt de Jin'Zil", objective = "Le sorcier-docteur Jin'Zil à Malaka'jin veut 5 doses de Sève des Serres-Rocheuses, 5 Moustaches crépusculaires, 30 Yeux de coursier et une Ecaille de dragon-faë.", description = "Je suis surexcité !\n\nTrois petites cages pour trois petits elfes ! Mais qu'allons-nous faire de nos trois calinouilleurs d'arbre ? Eh bien ! Faisons-leur goûter à… comment appellent-ils cela ?… La magie de la forêt !\n\nJ'aurais besoin de pas mal de Sève des Serres-Rocheuses. Prenez également des Moustaches crépusculaires à ces affreux félins. Cela nous amène aux Yeux de coursier : on ne peut jamais en avoir trop sous la main. Et surtout n'oublions pas : une précieuse Ecaille de dragon-faë !\n\nHâtez-vous de rejoindre le pic des Serres-Rocheuses <nom>, que je puisse concocter une recette magique de la forêt.", progress = "Regardez nos pauvres petits amis elfes. Enfermés et sans forêt où s'ébattre gaiement et folâtrer !\n\nMais bon. Alors avez-vous trouvé un peu de sève ? Et les moustaches des Coureurs crépusculaires ? Je ne pense pas que vous avez cette écaille sur vous.\n\nEt les yeux ! Il m'en faut tellement ! On ne peut pas concocter une magie de la forêt efficace sans en mettre un bon paquet !", completion = "Oh ! Comme ces petites nymphes champêtres vont être ravies ! Nous allons les faire se sentir comme à la maison avec cette petite préparation.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet vaudouBrassards maléficiés\n\nVous recevrez également :\n\n"},
[1059] = {title = "À la reconquête du Val calciné", objective = "Trouver Falfindel Waywarder à la frontière entre les Mille pointes et Feralas.", description = "Les Rougefuries ont été maîtrisées. Mais elles se regrouperont bientôt si nous n'agissons pas.\n\nLoin au sud des Tarides se trouve une terre connue sous le nom de Mille pointes. Si vous voyagez à l'ouest des Mille pointes jusqu'à la lisière de la luxuriante forêt de Feralas, vous trouverez un druide nommé Falfindel Waywarder.\n\nCe grand et sage druide est capable d'invoquer de puissants esprits de la forêt qui pourraient aider à la reconquête du Val calciné.\n\nFaites-lui connaître notre requête ! Partez à sa recherche. Maintenant !", progress = nil, completion = "Le Gardien Albagorm a été bien avisé de vous envoyer si vite.\n\nVoyons si nous pouvons requérir l'aide de la Grande Forêt pour qu'elle se rende au Val calciné avant qu'il ne soit trop tard.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards trempésTarge du connétable\n\nVous recevrez également :\n\n"},
[1060] = {title = "Lettre à Jin'Zil", objective = "Remettre la lettre de Darsok à Jin'Zil dans sa caverne des Serres-Rocheuses.", description = "Vous avez tellement fait pour moi, <nom>. Vous me portez vraiment chance et j'aimerais que vous voyiez quelque chose.\n\nLes harpies ne viennent pas des environs des Tarides. Elles viennent d'un endroit appelé les Serres-Rocheuses, loin au nord-ouest d'ici. Bien qu'il s'agisse probablement d'un endroit dangereux pour vous, j'ai besoin que cette lettre soit remise à l'un de mes vieux amis qui y réside, un sorcier-docteur du nom de Jin'Zil.\n\nIl sera content d'apprendre que Serena Plumesang est morte, et je crois que vous trouverez les Serres-Rocheuses intéressantes.", progress = "Vous avez l'air louche. Avez-vous quelque chose à me montrer ?", completion = "Ah ! Une lettre de Darsok. Je n'ai pas eu de ses nouvelles depuis de nombreuses années. Ainsi la dernière des Plumesang est morte, hein ? Ce sont de bonnes nouvelles que vous m'apportez. Je me rappelle quand mon ami Rokhan est parti avec ce fou de Mok'nathal tuer la sœur aînée. Ah, être jeune à nouveau, comme vous !", rewards = "Vous recevrez :\n\n"},
[1061] = {title = "Les esprits des Serres-Rocheuses", objective = "Parler à Seereth Stonebreak dans les Serres-Rocheuses.", description = "Les esprits des Serres-Rocheuses sont courroucés, car les gobelins et leurs serviteurs pillent et brûlent cette région. Ainsi la Terre a appelé à grands cris, et ceux qui sont à son écoute, ont entendu.\n\nSeereth Stonebreak, un chaman prometteur de la Horde, a été envoyée dans les Serres-Rocheuses. Elle témoigne d’une large déforestation perpétrée par les gobelins, et elle demande de l'aide.\n\nRencontrez Seereth dans les Serres-Rocheuses. Pour la trouver, suivez la route à l'ouest de la Croisée des Tarides. Elle s'est établie près du val de Grandbois.", progress = nil, completion = "Tiens, un &lt;classe&gt;. Très bien. Nous aurons besoin de vos talents pour nous occuper de ces pillards.", rewards = "Vous recevrez :\n\n"},
[1062] = {title = "Les invasions gobelines", objective = "Tuer 15 Déboiseurs de la KapitalRisk, puis retourner auprès de Seereth Stonebreak à la frontière des Serres-Rocheuses et des Tarides.", description = "La KapitalRisk, dirigée par des gobelins, s'est installée dans les Serres-Rocheuses, où ils coupent les arbres et brûlent des secteurs entiers de la forêt. Les esprits de cette terre sont quasiment aveuglés par la douleur et par la haine. Nous devons l'arrêter !\n\nPartez pour le nord-ouest, au-delà du Val de Grandbois et dans la combe des Cisailles. Vous trouverez les gobelins et leurs serviteurs à l'oeuvre. Montrez-leur que la Horde ne permettra pas l'exploitation des Serres-Rocheuses. Prouvez-le avec les arguments qu'ils comprennent le mieux...\n\nLa violence.", progress = nil, completion = "Un acte courageux, &lt;nom&gt;. Il se peut, en fin de compte, que nous ayons besoin de la sagesse des anciens taurens pour calmer les esprits des Serres-Rocheuses, mais…\n\nLiquider le personnel de la KapitalRisk était une bonne entrée en matière pour la contrecarrer.", rewards = "Vous recevrez :\n\n"},
[1063] = {title = "L'Ancienne", objective = "Parler à Magatha à Thunder Bluff.", description = "Pour vraiment soigner les esprits des Serres-Rocheuses, nous devons consulter les anciens esprits des taurens.\n\nLe seul chef dont j’ai entendu parler est Magatha. Elle est très vieille et ses connaissances sont grandes. Si quelqu’un peut canaliser une aide spirituelle des taurens, c'est bien elle.\n\nMagatha réside à Thunder Bluff, la capitale des taurens, sur la Cime des Anciens, la cité au nord-est du promontoire. Parlez à Magatha, et racontez-lui les périls encourus par les Serres-Rocheuses.", progress = nil, completion = "Je vous souhaite la bienvenue. Êtes-vous ici pour chercher conseil ?", rewards = "Vous recevrez :\n\n"},
[1064] = {title = "L'aide des Réprouvés", objective = "Parler à l'Apothicaire Zamah aux Bassins de la vision.", description = "Les taurens ont un lien avec cette terre, et apprendre la mauvaise santé des Serres-Rocheuses me peine. Mais j'ai peur que pour soigner cette terre, nous devions d'abord éradiquer la maladie qui l’envahit.\n\nN'est-ce pas heureux, alors, que les Réprouvés soient nos alliés ? Ils en savent beaucoup à propos des maladies. Je pense qu'ils peuvent nous aider, et en nous aidant ils consolideront la confiance qui existe entre nos deux peuples.\n\nParlez à l'Apothicaire Zamah. C'est une érudite et un émissaire des Réprouvés. Vous la trouverez aux Bassins de la vision sous la Cime des Esprits.", progress = nil, completion = "Magatha m'a avertie de votre venue, &lt;nom&gt;. Bien que mon cœur ne batte plus, je ressens toujours du chagrin pour les Esprits des Serres-Rocheuses.\n\nLes Réprouvés ont le désir d'offrir toute l'aide qu'ils peuvent apporter.", rewards = "Vous recevrez :\n\n"},
[1065] = {title = "Un voyage vers Moulin-de-Tarren", objective = "Apporter la Note de Zamah à l'Apothicaire Lydon à Moulin-de-Tarren.", description = "Pour débarrasser les Serres-Rocheuses de la KapitalRisk, nous devons employer des mesures extrêmes. Extrêmes, mais sans effusion de sang.\n\nIl se peut que l'un de mes confrères ait exactement l'outil dont nous avons besoin. Il se nomme Lydon, et réside dans la ville de Moulin-de-Tarren, dans les contreforts d'Hillsbrad, dans la terre lointaine de Lordaeron.\n\nPour atteindre Hillsbrad, voyagez par zeppelin vers notre capitale, Undercity. Puis allez au nord vers les Clairières de Tirisfal, au sud-ouest vers les Pins argentés, et enfin au sud vers Hillsbrad.\n\nCherchez Lydon et donnez-lui cette note. Elle explique ce que nous attendons de lui.", progress = "Ah ! Êtes-vous ici avec mes nouveaux sujets de tests ?", completion = "Une note de Zamah ? Elle doit avoir grandement besoin de moi pour m'envoyer un mot d'aussi loin. Voyons ce qu'elle dit…\n\nAh splendide ! Je sais exactement quoi faire !", rewards = "Vous recevrez :\n\n"},
[1066] = {title = "Le sang des innocents", objective = "Apporter 5 Fioles de Sang d'innocent à l'apothicaire Lydon à Moulin-de-Tarren.", description = "Je vais créer une toxine pour annihiler la violence de la KapitalRisk, et la rendre faible et docile. Cela devrait régler le problème de la Horde dans les Serres-Rocheuses, pas vrai ?\n\nMais pour créer la toxine, je vais avoir besoin de sang d'innocent, un ingrédient difficile à trouver.\n\nHeureusement le Syndicat, un groupe de brigands humains, emploie des mages de l'ombre... Et ces mages stockent du sang d'innocent pour leurs propres desseins, peu recommandables.\n\nVous trouverez les mages de l'ombre du Syndicat au donjon de Durnholde, au sud-est.", progress = "Avez-vous trouvé les mages de l'ombre du Syndicat, et leur avez-vous pris le sang ?", completion = "Très bien ! Je pense que le Syndicat vous a posé quelques difficultés ?\n\nComme je l'ai dit, le sang d'innocent n'est pas chose facile à obtenir. Nous avons de la chance que les mages de l'ombre du Syndicat aient fait le plus difficile pour nous.\n\nÀ présent, attendez un moment le temps que je prépare le mélange...", rewards = "Vous recevrez :\n\n"},
[1067] = {title = "Le retour à Thunder Bluff", objective = "Apporter la Toxine de Lydon à l'Apothicaire Zamah à Thunder Bluff.", description = "Voici la toxine. Si vous l'utilisez contre la KapitalRisk, cela devrait produire des effets intéressants, et peut-être même contagieux. Je dois dire que c'est très excitant de voir mon travail appliqué sur le terrain !\n\nMais avant de l'utiliser, apportez-la à l'Apothicaire Zamah. Elle doit concevoir une méthode de diffusion particulière pour optimiser les effets de la toxine.", progress = "Vous voilà de retour, <nom> ! Apportez-vous une l'aide de l'Apothicaire Lydon ?", completion = "Une toxine de l'apothicaire Lydon ? Très bien. Si je le connais bien, alors cette toxine sera très efficace contre la KapitalRisk…", rewards = "Vous recevrez :\n\n"},
[1068] = {title = "Les machines à déchiqueter", objective = "Détruire les Déchiqueteurs XT4 et XT9, puis retourner voir Seereth Stonebreak à la frontière entre les Serres-Rocheuses et les Tarides.", description = "Il existe une relation entre la magie spirituelle des chamans et la magie naturelle des druides. C'est pourquoi nous, les chamans, nous pouvons entendre la complainte des esprits des Serres-Rocheuses. Beaucoup de leurs murmures m'échappent, mais un message – une vision – est clair...\n\nJ'ai eu la vision de deux machines à forme humaine, dans la Combe des cisailles, au nord-ouest du val de Grandbois, coupant les arbres à une vitesse incroyable. Ces bêtes de métal doivent être stoppées !\n\nDans ma vision, il y avait d'étranges symboles gravés sur les machines :\n\nXT4 et XT9.", progress = "Les Esprits gémissent à la perte de leurs frères, <nom>. Vous devez détruire les Déchiqueteurs XT4 et XT9, ou les Serres-Rocheuses ne pourront jamais être soignées.", completion = "La destruction des machines XT4 et XT9 a apaisé beaucoup d'esprits des Serres-Rocheuses, &lt;nom&gt;. Après cette opération, espérons que la KapitalRisk se retire d’elle-même des montagnes.\n\nCar si elle ne le fait pas, alors je crains que les atrocités commises sur cette terre ne soient rien en comparaison de ce qui pourrait arriver.", rewards = "Vous recevrez :\n\n"},
[1069] = {title = "Omelette à la mousse profonde", objective = "Apporter 15 Œufs des mousses profondes à Mebok Mizzyrix à Ratchet.", description = "L’omelette aux oeufs d'araignée est la nouvelle mode culinaire à Baie-du-Butin ! Le problème c'est qu'il n'y a pas le moindre oeuf dans toute la ville.\n\nUne possibilité se profile !\n\nÀ la combe des Cisailles et dans le canyon de Sishir, dans les Serres-Rocheuses, au nord-ouest, vit l'araignée des mousses profondes. Apportez-moi ses oeufs et je vous payerai un sacré paquet !\n\nÀ la combe des Cisailles, vous trouverez les oeufs groupés sous les arbres qui restent.\n\nEn ce qui concerne le canyon de Sishir... eh bien, si vous avez un estomac fragile, vous feriez bien de vous en tenir à la combe des Cisailles pour collecter les oeufs...", progress = "Avez-vous récupéré les oeufs, <nom> ? J'ai déjà convenu d'un arrangement avec le Maître des quais Dizzywig !", completion = "Vous les avez ! Merci !\n\nJe vais les envoyer à Dizzywig et ils partiront pour Baie-du-Butin. Je peux déjà sentir les profits !\n\nVoici votre part, &lt;nom&gt;. Je n'aurais pas pu faire cette affaire sans vous.", rewards = "Vous recevrez :\n\n"},
[1070] = {title = "De garde dans les Serres-Rocheuses", objective = "Retrouver Kaela Shadowspear qui surveille la vallée à l'entrée de la combe des Cisailles dans les Serres-Rocheuses.", description = "Salutations, <nom>.\n\nVotre apparence semble indiquer que vous avez envie de parcourir le monde. Êtes-vous <allé/allée> dans les Serres-Rocheuses ? C'est une région tourmentée par la KapitalRisk et par d'autres ennemis des elfes de la nuit.\n\nRécemment, la sentinelle Wolfrunner y a envoyé mon amie Kaela Shadowspear enquêter sur place, et je n'ai toujours pas reçu de ses nouvelles. L'inquiétude me ronge, d'autant que l'Alliance a envoyé un mage gnome avec elle... Mauvais présage, pour sûr.\n\nPourriez-vous la retrouver et revenir m'informer ?", progress = nil, completion = "Ah ! Vous êtes venu depuis Ashenvale sur la demande de Tara. Comme elle me manque... Comme ma terre natale et mes amis me manquent... Elle doit bien s'en sortir avec les Sentinelles pour pouvoir assigner des aventuriers à d'autres tâches. Je suis fière d'elle.\n\nC'est un plaisir de vous rencontrer, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1071] = {title = "Du répit pour un gnome", objective = "Tuer 10 Déboiseurs de la KapitalRisk et 10 Défricheurs de la KapitalRisk, puis retourner voir Gaxim Rustfizzle dans les Serres-Rocheuses.", description = "Vous voyez, <nom>, je suis un membre de l'Assemblée illuminée d'arcanologie, d'alchimie et de sciences d'ingénierie, et c'est mon but… non, il est de mon DEVOIR de montrer aux elfes de la nuit que l’association de magie, de mixtures et de mécanique peut aider à sauver leurs forêts.\n\nMais c'est un combat acharné, et les gobelins semblent se reproduire comme des lapins. Je n'ai même pas eu le temps de construire mes dernières inventions !\n\nJ'ai besoin de temps pour planifier et organiser. Mais vous pouvez m’aider à retenir les gobelins à quai à la combe des Cisailles, à l'est.", progress = nil, completion = "Je vous remercie tellement pour votre aide, &lt;nom&gt;. Vous revenez juste à temps, en fait. Je crois que j'ai un plan parfait… des explosifs. Non, ce n'est pas le plan ! Mais ça fait partie du plan.\n\nVous voyez, j'ai utilisé de puissants explosifs – ne vous en faites pas, ils ne sont pas aussi dangereux qu’on le dit – pour effrayer un peu les gobelins. J'arrive à les attrouper plutôt bien avec quelques détonations placées à des endroits clés le long des crêtes, mais je n'ai plus beaucoup de matériel depuis quelques jours...", rewards = "Vous recevrez :\n\n"},
[1072] = {title = "Un vieux collègue", objective = "Parler à Lomac Gearstrip à Ironforge.", description = "L'appareil auquel je pense est à ce jour ma version la plus avancée. Mais nous aurons besoin d'une potion spéciale si nous voulons que ça marche. Je pense que nous pourrons avoir la bonne dose également puisque cette mission sera votre dernière.\n\nEt pour ça, il nous faut un puissant explosif : le Nitromirglyceronium.\n\nLa seule personne qui puisse faire du NG-5 est un de mes vieux amis : Lomac Gearstrip. Cherchez-le à Brikabrok.\n\nDemandez-lui de nous faire du NG-5, je vais travailler au placement de mes appareils en attendant.", progress = nil, completion = "Ahhh ! Gaxim vous envoie, hein ? Comment puis-je savoir que vous ne me mentez pas ? Hmm ! Hmm...", rewards = "Vous recevrez :\n\n"},
[1073] = {title = "Inaptitude + Produits chimiques = Rigolo", objective = "Apporter 4 Potions de mana mineures et 2 Elixirs de Robustesse mineure à Lomac Rubangrenage à Ironforge.", description = "Ha ha ha ! Vous avez besoin de nitromirglyceronium pour empêcher les gobelins de détruire une forêt ?\n\nSavoir si vous connaissez Gaxim ou non ne m'intéresse pas… Je vais vous donner le matos juste histoire de vous voir ou de les voir exploser en petits confettis.\n\nIl y a un problème quand même : je n'en ai plus.\n\nMais je vais vous dire, vous m'apportez les bonnes potions, et je vous en fais tout de suite.\n\nLe moins que vous puissiez faire c'est de me montrer que vous avez des talents d'alchimiste avant que je vous donne un échantillon de ma grande œuvre.", progress = "Je ne peux pas faire de Nitromirglyceronium si je n'ai pas ces potions… Elles sont cruciales à sa création.", completion = "Ce sera parfait.\n\nJe ne dirai pas mieux, étranger, sûr que vous vous y connaissiez en alchimie. Bien, bien… Le monde n'est pas fait seulement d'épées et de sorcellerie, vous savez ?", rewards = "Vous recevrez :\n\n"},
[1074] = {title = "Inaptitude + Produits chimiques = Rigolo", objective = "Rapporter le Nitromirglyceronium à Gaxim Rustfizzle, dans les Serres-Rocheuses.", description = "Voilà, <étranger/étrangère>. Mais faites attention avec ça quand même… C'est volatil.\n\nSi vous êtes vraiment <un ami/une amie> de Gaxim, alors transmettez-lui mes salutations. Si vous ne l'êtes pas, alors amusez-vous bien à vous faire sauter la tronche.", progress = "Ah ! Chouette chouette vous revoilà !", completion = "Vous avez accompli votre tâche à la perfection, &lt;nom&gt;.\n\nLe NG-5 est sans aucun doute le produit parfait pour faire sauter les wagons de dynamite.\n\nQuoi ? Oui, dynamite… Des wagons entiers. C'est la diversion parfaite, je vous assure… Attendez et vous verrez.", rewards = "Vous recevrez :\n\n"},
[1075] = {title = "Un parchemin de Collin Mauren", objective = "Trouver Collin Mauren à Stormwind.", description = "OK, maintenant à propos de l’explosion à distance… Oh ! Je n'ai pas encore expliqué cette partie de mon plan ?\n\nBien, alors voici la version courte : avec un peu de magie, on peut déclencher l’explosion sans avoir besoin de vous dans les parages. Je suis en train de peaufiner un système qui vous permettra d’appuyer simplement sur un bouton pour que le NG-5 explose, à votre commandement.\n\nMais j'ai besoin du sort d'un ami à Stormwind. Il s'appelle Collin Mauren. Vous le trouverez dans le quartier des mages, là-bas. C'est un humain, alors ça sera difficile de le rater.", progress = nil, completion = "À présent, ce sort dont vous avez besoin… Un sort pour commander une explosion à distance… Hmmm…", rewards = "Vous recevrez :\n\n"},
[1076] = {title = "Des diables dans la marche de l'Ouest", objective = "Apporter des Débris de Diable de poussière à Collin Mauren à Stormwind.", description = "Ah ! Je pense que ça vient. Un sort de contrôle… Je crois que c'est l'effet qu'il recherche.\n\nJe vais devoir créer un parchemin pour y inscrire le sort. Pour cela, j’ai besoin de débris de Diable de poussière.\n\nTandis que je rassemble le reste des ingrédients, pourquoi n'iriez-vous pas dans la marche de l'Ouest me trouver une de ces ignobles créatures ? Elles sont dangereuses, mais je suis sûr que vous êtes <prêt/prête> à tout pour participer à une expérimentation de Gaxim.\n\nJe serai là quand vous reviendrez.", progress = "Salutations, <nom>. Avez-vous l'ingrédient dont j'ai besoin ?", completion = "Donnez-moi juste quelques instants et le parchemin sera prêt.", rewards = "Vous recevrez :\n\n"},
[1077] = {title = "Livraison spéciale pour Gaxim", objective = "Apporter le Parchemin de contrôle à Gaxim Rustfizzle dans les Serres-Rocheuses.", description = "Voilà, <nom>. Ça devrait faire l'affaire.\n\nAssurez Gaxim de ma considération la prochaine fois que vous le verrez. J'ai hâte d'entendre la suite de cette aventure.\n\nAdieu.", progress = "Ha ha ! Vous êtes de retour ! Vous l'avez ? Avez-vous le sort ?", completion = "C'est parfait, &lt;nom&gt; ! Beau travail.\n\nCe sort, associé au NG-5, fera le parfait explosif déclenchable à distance.\n\nNous allons pouvoir créer une diversion parfaite, le temps que vous vous introduisiez dans la place pour voler les notes et les plans d'ingénierie de la KapitalRisk.\n\nCeci ralentira sûrement leur campagne de déforestation.", rewards = "Vous recevrez :\n\n"},
[1078] = {title = "Des retrouvailles pour Mauren", objective = "Apporter 8 Ecailles de cristal à Collin Mauren à Stormwind.", description = "Les voyageurs m'interrogent toujours au sujet des Serres-Rocheuses. C’est une région populaire pour qui cherche l'aventure, qu’il s’agisse de traquer des wyverns, des élémentaires, ou du personnel de la KapitalRisk.\n\nDans le Val calciné, loin à l’intérieur des montagnes, vivait autrefois une espèce de basilic dont les écailles, une fois plantées dans la poussière, produisaient un merveilleux réactif pour certains des sorts que j'ai créés.\n\nSi ces basilics vivent toujours, j'aimerais avoir quelques-unes de leurs écailles.\n\nPrenez votre temps, ce n'est pas urgent, mais je paye bien.", progress = "Salut à nouveau, <nom>.\n\nVous êtes déjà revenu du Val calciné avec mes écailles ?", completion = "C'est parfait, &lt;nom&gt;. Merci grandement.\n\nPeut-être qu'un jour je pourrai vous aider à mon tour.", rewards = "Vous recevrez :\n\nBaguette de sortilèges"},
[1079] = {title = "Opérations secrètes – Plan A", objective = "Récupérer les Plans d'ingénierie de la KapitalRisk dans la scierie de la Combe des Cisailles.", description = "Ça y est, <nom>. Faites très attention ! Les dispositifs sont montés et prêts à fonctionner.\n\nPrenez ces explicatifs. Ils résument tout ce qu'il faut savoir sur les détonateurs et les explosifs, et indiquent également où vous devez les placer.\n\nRappelez-vous, le succès de votre mission ne dépend pas de la somme de destruction que vous provoquerez. Le succès du plan A dépend du fait que vous rapportiez les plans d'ingénierie de la KapitalRisk de l'intérieur de la scierie au sud du lac de la Combe.", progress = "Avez-vous les plans, <nom> ?", completion = "Vraiment ahurissant ! C'est un grand coup porté à la KapitalRisk.\n\nNous allons pouvoir trouver les faiblesses de leurs machines, mais aussi intégrer leurs concepts dans nos propres créations. C'est un grand jour, vraiment.", rewards = "Vous recevrez :\n\n"},
[1080] = {title = "Opérations secrètes – Plan B", objective = "Récupérer les Notes de la KapitalRisk dans la mine des Cisailles à l'extrémité est de la Combe des Cisailles.", description = "Le plan B est identique au plan A, <nom>.\n\nNous faisons diversion et nous volons leurs précieuses notes.\n\nLe plus important est d'obtenir leurs notes… Rappelez-vous de ça.\n\nLes explicatifs que je vous ai déjà fournis indiquent où placer les explosifs. Revenez simplement ici en vie et avec ces notes...", progress = "Comment ça se passe, <nom> ?", completion = "Incroyable, &lt;nom&gt; ! Kaela et les Sentinelles seront si heureuses. Avec vos compétences et mes créations, rien ne peut nous arrêter.", rewards = "Vous recevrez :\n\n"},
[1081] = {title = "Réception par Tyrande", objective = "Trouver Tyrande Whisperwind à Darnassus.", description = "<nom>, il est sûr que Tyrande Whisperwind en personne voudrait vous remercier de prendre part à cette mission.\n\nIl n’y paraît peut-être pas, mais votre aide pourrait renforcer notre position dans les Serres-Rocheuses.\n\nSi vous vous considérez comme notre <allié/alliée> face à ces atrocités, allez voir Tyrande au Temple de la Lune de Darnassus.", progress = nil, completion = "Salutations, &lt;nom&gt;. J'ai effectivement déjà entendu votre nom, et bien que vous soyez si jeune, il me ravit de voir le chemin que vous avez emprunté.\n\nVous me feriez un grand honneur en acceptant ceci en cadeau de remerciement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe efflorescenteTunique du grizzlyCotte d'anneaux forestière\n\nVous recevrez également :\n\nAnneau de grâce elfique"},
[1082] = {title = "Une mise à jour pour la Sentinelle Thenysil", objective = "Retourner voir la Sentinelle Tara Thenysil en Ashenvale.", description = "<nom>, vous avez accompli un noble geste en nous offrant votre aide.\n\nLes Sentinelles d'Ashenvale vous récompenseront si vous leur donnez des nouvelles de Gaxim et de moi. Dites-leur que nous sommes bien partis pour stopper la KapitalRisk et soigner la terre.\n\nTrouvez Tara Thenysil à Astranaar ; elle sera ravie de vous voir revenir avec de bonnes nouvelles.", progress = nil, completion = "Merci, &lt;nom&gt;. Vous avez rendu un grand service aux Sentinelles.\n\nJe suis heureuse de savoir que Kaela… et même Gaxim vont bien.\n\nNotre reconnaissance vous est acquise.", rewards = "Vous recevrez :\n\n"},
[1083] = {title = "Esprits enragés", objective = "Apporter 8 Braises ardentes provenant de n'importe quel élémentaire de feu du Val calciné à Kaela Shadowspear, dans les Serres-Rocheuses.", description = "Je ne sais pas exactement comment la KapitalRisk s’est comportée vis-à-vis de la vallée, mais une chose est sûre : elle a été submergée par des créatures locales.\n\nSes gens ont mis le feu à la forêt et utilisé leurs engins de destruction pour ravager la vallée.\n\nMais dans leur ignorance ils ont libéré des esprits ardents et des élémentaires de flamme, de roche et de rage.\n\nLa Terre n'a aucune chance de voir le sourire d'Elune tant que ces créatures la fouleront librement.\n\nApportez-moi leurs Braises ardentes pour me montrer que vous avez réduit leur nombre.", progress = "La première fois que j'ai vu le Val calciné, j'ai presque pleuré, <nom>.", completion = "Les restes de notre ennemi… Votre force nous sert bien, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\n"},
[1084] = {title = "Les Anciens blessés", objective = "Apporter un morceau de Shrapnel abîmé à Kaela Shadowspear, dans les Serres-Rocheuses.", description = "Il me semble évident que les protecteurs de la vallée, les tréants, ont quelque chose à voir avec le retrait de la KapitalRisk. Malheureusement, même ceux qui étaient autrefois de grands gardiens sont aujourd'hui corrompus.\n\nGaxim pense que leur corruption est d'une certaine manière liée aux armes utilisées par les gobelins pendant le combat.\n\nJe lui ai dit que je collecterais un résidu sur un tréant blessé pour qu’il l'étudie et découvre l’origine du mal.\n\nApportez-moi un morceau de shrapnel pour que le gnome puisse m'en dire plus...", progress = "J'ai le sentiment que Gaxim trouvera une utilisation au shrapnel, et quel que soit son précédent usage par la KapitalRisk.", completion = "Merci, &lt;nom&gt;.\n\nCeci devrait être plus que suffisant à Gaxim pour comprendre comment les tréants ont été corrompus. Je vais le lui donner tout de suite.", rewards = "Vous recevrez :\n\n"},
[1085] = {title = "De garde dans les Serres-Rocheuses", objective = "Parler à Gaxim.", description = "La situation ici dans les Serres-Rocheuses est suffisamment grave pour qu'une elfe de la nuit et un gnome travaillent ensemble.\n\nLa KapitalRisk a dévasté cette région et j'ai passé la majeure partie de mon temps à mettre un terme à cette destruction.\n\nNe jugez pas Gaxim trop vite, il comprend la nécessité de notre travail commun.\n\nSi vous souhaitez nous aider, alors commencez par parler à Gaxim.\n\nJe suis désolée de ne pas encore pouvoir vous renvoyer à Tara avec de bonnes nouvelles. Bientôt peut-être…", progress = nil, completion = "Perfide… Perfide et dangereuse, voilà ce qu'est cette région.\n\nJe suis ici pour montrer aux elfes de la nuit que les choses sont un peu plus sûres avec l'aide de cette bonne vieille ingénierie et d'une goutte de magie.\n\nVous voyez, jurer de renoncer totalement à la magie n'aidera pas les elfes de la nuit. Ils en ont besoin. Le monde en a besoin. Et avec l'ingénierie et l'alchimie en plus, on ne peut pas se tromper. Les possibilités sont infinies.", rewards = "Vous recevrez :\n\n"},
[1086] = {title = "L'aéroport de la machine volante", objective = "Apporter le Brouillard toxique à l'aéroport de la KapitalRisk, puis retourner voir l'Apothicaire Zamah.", description = "La toxine est prête. Tout ce qu'il reste à faire est de la livrer. Vous devez vous en occuper, <nom>.\n\nLa KapitalRisk doit avoir un moyen d'envoyer des messages et de petites cargaisons entre ses quartiers généraux et ses sites d'opérations dans les Serres-Rocheuses. Il s'agit probablement d'un petit aéroport, pas suffisamment important pour un zeppelin, mais assez pour une machine volante. Cherchez dans les Serres-Rocheuses les secteurs sous contrôle de la KapitalRisk et trouvez cet aéroport, s'il existe. Placez-y alors la toxine.\n\nPlacez-la, et courez !", progress = nil, completion = "Avez-vous trouvé le port ? Bon travail, &lt;nom&gt; ! Je suis sûre que les gobelins ont été très surpris par votre livraison ! Espérons que la toxine se fraye un chemin jusqu'à leurs quartiers généraux.\n\nVous avez rendu un grand service à votre peuple, et je vous conseille de ne pas ressentir de culpabilité. La KapitalRisk mérite pire que cela.\n\nEt s'il y a un atome de sagesse que les Réprouvés pourraient apprendre à leurs alliés, c'est :\n\nN'évitez pas les sombres chemins... si ces chemins vous mènent à la victoire.", rewards = "Vous recevrez :\n\n"},
[1087] = {title = "L'héritage de Cénarius", objective = "Tuer 4 Fils de Cénarius, 4 Filles de Cénarius et 4 Botanistes cénariens pour Braelyn Firehand, près de la retraite de Roche-Soleil.", description = "Vous ne pouvez pas imaginer la haine que je ressens pour cette terre misérable. Au pic, les semblables de Cénarius et les druides kaldorei emploient leurs pouvoirs minables pour étouffer le flot de magie, même jusqu'au sud de leurs possessions pathétiques... leurs forêts bien-aimées.\n\nJe voudrais retourner à Jaedenar et exulter dans le flot de magie, mais mon maître ne le permettra pas tant que mon travail ici ne sera pas achevé.\n\nIl ne fait aucun doute que vous aimez les elfes de la nuit et leurs alliés aussi peu que je les aime. Aidez-moi, et notre but commun pourra être atteint.", progress = nil, completion = "Déjà je peux le sentir… Oui… Un pouvoir si suave… Le torrent déferlant. Les Kaldorei sont idiots de refuser les présents de ce monde, de rejeter le courant de la magie tandis qu'il coule, chantant dans vos veines.\n\nQuelle pâle caricature est la vie sans son étreinte de feu...", rewards = "Vous recevrez :\n\n"},
[1088] = {title = "Ordanus", objective = "Apporter la Tête d'Ordanus à Braelyn Firehand, près de la Retraite de Roche-Soleil.", description = "Ils ont cru qu'ils pourraient arrêter le flot de magie. Ils se sont trompés. Ils ont cru pouvoir cacher Ordanus, mais j'aurai sa tête !\n\nLa magie m'accorde la vision véritable. Oui… il est là. Un croisement… Au sommet d'un grand arbre dans la forêt d'Ashenvale. Un nom... Raynewood. L'un des fils aînés du dieu de la Forêt. Ils l'ont fait disparaître du pic avant que je puisse le trouver, mais son temps est compté.\n\nApportez-le-moi et je vous offrirai un puissant cadeau.", progress = "Lorsque mon maître m'a enjoint de venir au pic des Serres-Rocheuses, je pensais que mon unique tâche consisterait à écraser les elfes de la nuit qui rampaient dans les ruines sacrées de notre ancien temple d'Azshara, souillant la sainteté du lieu... Mais Ordanus a échappé à mon étreinte.", completion = "J'ai rencontré Ordanus une fois, il y a longtemps. Il possédait l'arrogance de sa race, se considérant même supérieur aux Bien-nés.\n\nSa tête ne monte plus aussi haut, à présent, n'est-ce pas, &lt;nom&gt; ?\n\nJe vous ai promis une récompense, et vous l'aurez. Regardez.", rewards = "Vous recevrez :\n\n"},
[1089] = {title = "L'Antre", objective = "Aller dans l’Antre, sur le Pic des Serres-Rocheuses. En utilisant la Clé du gardien, obtenir les objets cachés des druides. Utiliser ces objets pour ouvrir le Trésor de l'Antre des Serres.", description = "Les druides ont construit l'Antre des Serres dans le pic des Serres-Rocheuses. Ils y conservent de nombreux objets puissants.\n\nIls ont conçu un plan compliqué pour que ces derniers ne tombent pas entre de mauvaises mains.\n\nPar chance, j'ai réussi à… extraire quelques informations de l'un d'entre eux.\n\nCachée dans une petite lanterne, à l'entrée de l'Antre, vous trouverez la Clé du gardien ; elle vous permettra d'ouvrir des cachettes autour de l'Antre. Les objets extraits de ces cachettes donnent accès au trésor, situé dans l'un des secteurs centraux.", progress = "Trois serrures sont sculptées dans la pierre.", completion = "Tandis que les trois clés sont glissées dans leur serrure respective, des objets apparaissent au milieu d'une lumière luisante.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nAnneau sacréArmure de la panthèreJambières du molosse"},
[1090] = {title = "Les ordres de Gerenzo", objective = "Obtenir le minerai mystérieux de Piznik après qu'il l’aura extrait.", description = "Vous savez, avant j'étais la seconde personne la plus importante ici sur ce site. Tout a changé quand Gerenzo est arrivé. Il a viré mon patron, Ziz Fizziks, et m'a envoyé bosser dans les mines. Ziz m'a dit de rester ici et de rassembler des renseignements. Son nouveau patron nous paiera bien si nous pouvons découvrir les plans de Gerenzo.\n\nMais bon, ce que je sais c’est que Gerenzo a ordonné que des quantités importantes de ce minerai or-vert soient extraites. Je peux vous trouver un échantillon pour que vous l'apportiez à Ziz, mais faites attention aux patrouilles le temps que j’aille en chercher.", progress = "Attention, il y a toujours des patrouilles et des ouvriers qui passent dans le secteur, et ça peut devenir mauvais si on se fait remarquer.", completion = "Merci, &lt;nom&gt;. Ça a été un petit peu risqué pendant un moment et nous avons probablement attiré l'attention.\n\nCe qui est important, c'est que nous avons l'échantillon de minerai, et nous devons l'apporter à Ziz dès que possible.", rewards = "Vous recevrez :\n\n"},
[1091] = {title = "Des nouvelles pour Kaela", objective = "Apporter les Notes de la KapitalRisk à Kaela Shadowspear.", description = "<nom>, apportez ces notes à Kaela. Il est certain qu'elle voudra en savoir plus à ce propos. Ou du moins ce sera le cas des Sentinelles.\n\nDites-lui à quel point notre victoire a été éclatante, et à quel point nous n'aurions pu y parvenir sans l'aide d'un peu de magie.", progress = "Oui, <nom> ? Que puis-je faire pour vous ?", completion = "C'est intéressant, effectivement.\n\nVous et Gaxim avaient très bien œuvré, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\n"},
[1092] = {title = "Les ordres de Gerenzo", objective = "Remettre le Minerai non identifié à Ziz Fizziks dans les Serres-Rocheuses.", description = "Je pense que je ferais mieux d’envisager de ficher le camp d'ici, aussi. Ça ne va pas prendre beaucoup de temps avant que la nouvelle de ce qui s'est passé ici se répande au-dessus, et je suis sûr qu'ils ne seraient pas ravis de me revoir.\n\nJe vais dégager d’ici et aller voir Ziz. J'espère qu'il pourra me trouver du boulot !\n\nJe vais essayer de nettoyer ce bordel, mais vous devez apporter l'échantillon de minerai à Ziz tout de suite. Il m'a dit qu'il établirait un camp quelque part du côté ouest de la Combe des Cisailles. Bonne chance.", progress = "Il y a quelque chose pour laquelle je peux vous aider ?", completion = "Ahhh ! C’était une bonne idée de demander à Piznik de rester derrière ! Il est certain que les ingénieurs de Undermine seront très intéressés de jeter un œil à cela…\n\nBien sûr j’aimerais garder un petit morceau pour moi, et ce qu'ils ne savent pas ne peut pas les gêner, hein ?", rewards = "Vous recevrez :\n\nBottes de boueux"},
[1093] = {title = "Super-Découpeur 6000", objective = "Trouver le Plan du Super-Découpeur 6000 pour Ziz Fizziks dans les Serres-Rocheuses.", description = "C'est terrible ce que la KapitalRisk a fait ici, hein ? Mais à quoi donc pensaient-ils ? Une compagnie de gobelins qui embauche un gnome !\n\nHeureusement pour moi, Sputtervalve reconnaît un génie lorsqu'il en voit un. M'a embauché juste après que je me suis fait virer !\n\nIl me dit qu'ils construisent une énorme machine pour découper le bois, et Sputt veut que je vole les plans pour lui. Malheureusement, Gerenzo – maudit gnome – veut ma peau... Peut-être que vous pourriez voler les plans pour moi ? Vous devriez les trouver sur l'un de leurs opérateurs.", progress = "Avez-vous trouvé ces plans ? J'ai envie d'impressionner le nouveau patron. J'espère qu'une fois convaincu de ma loyauté – pour autant qu'il puisse être convaincu… l'honneur d'un gobelin, vous savez… – il ne se gênera pas pour abuser de mon génie plutôt impressionnant.", completion = "Hé ! Est-ce que c'est ce que je pense que c'est ? Merveilleux !\n\nÀ présent, voyons voir. Euh… Comment suis-je supposé comprendre ce machin… Je pige rien à la façon de penser des gnomes. Je vais vous dire, je suis déjà surpris qu'ils aient pu construire le volant, alors ces machines volantes qu'ils affectionnent tellement...", rewards = "Vous recevrez :\n\n"},
[1094] = {title = "D'autres instructions", objective = "Remettre l'Enveloppe scellée à Sputtervalve dans les Tarides.", description = "Cette enveloppe contient toutes les informations que j'ai pu rassembler avant qu'ils me flanquent à la porte : des documents internes de la KapitalRisk, quelques manuels, des trucs techniques… Et bien entendu, le plan du Super-Découpeur 6000.\n\nSputtervalve a élu résidence à Ratchet dans les Tarides. Vous ne devriez pas avoir trop de mal à le trouver, c'est un type un peu vert.", progress = "Salut ! Comment puis-je vous aider ?", completion = "Fizziks, hein ? On ne peut pas dire que je lui fasse confiance, mais cette information m'a l'air valable. Qu'est-ce que je ne ferais pas pour me débarrasser de la KapitalRisk.\n\nIls font quand même de bonnes machines… Je ne peux pas nier que nous avons bénéficié de leurs progrès techniques en les utilisant sur nos propres engins...", rewards = "Vous recevrez :\n\n"},
[1095] = {title = "D'autres instructions", objective = "Apporter les nouveaux ordres à Ziz Fizziks dans les Serres-Rocheuses.", description = "L’embauche de ce gnome par la KapitalRisk a créé quelques remous à Undermine. Les princes marchands n'approuvent pas que Razdunk fasse des affaires avec ce Gerenzo.\n\nRiddlevox m'a demandé de m'occuper du problème, et il est certain qu'il a reçu, d'un ou de plusieurs princes marchands, les mêmes instructions. Bien sûr, le directeur ne me l'a pas dit. Disons que j'ai simplement une intuition.\n\nQuoi qu'il en soit, nous devons faire en sorte de supprimer Gerenzo, et ce serait le test parfait de voir Fizziks s'en occuper.", progress = nil, completion = "Eliminer Gerenzo ? C'est un projet contre lequel je ne soulève pas d'objections.\n\nLes gnomes sont déjà mauvais par nature, mais ce que j'ai appris à propos de Gerenzo est encore pire. Apparemment, c'était l'un des Ingénieurs en chef de Gnomeregan, où il travaillait sur leur projet secret. Nous n'avons jamais pu infiltrer suffisamment Dun Morogh pour connaître les détails de ce projet. Mais quoi que c'était, nos rapports disent que ça leur a littéralement explosé à la figure.", rewards = "Vous recevrez :\n\n"},
[1096] = {title = "Gerenzo Wrenchwhistle", objective = "Apporter le Bras mécanique de Gerenzo Wrenchwhistle à Ziz Fizziks dans les Serres-Rocheuses.", description = "J'ai rencontré Gerenzo une fois, mais laissez-moi vous dire qu'il n'est pas très beau à voir. On dirait que sa chair est en train de pourrir, et il s'est fait greffer du métal et des accessoires sur le corps. Il a remplacé certains membres naturels par des membres mécaniques.\n\nAu nord-est d'ici, loin au-dessus du lac de la Combe, près de la roue hydraulique, Gerenzo surveille le site entier.\n\nJe ne pourrais pas monter là-haut, je ne survivrais pas aux combats. Sans parler de me charger de Gerenzo... Mais vous semblez être capable de réussir.\n\nSi vous le tuez pour moi, je ferai en sorte que ça en vaille le coup !", progress = "Sputtervalve réclamera un genre de preuve de la mort de Gerenzo. Je pense que son bras mécanique fera l'affaire.", completion = "Regardez cette chose… Il faut bien être un gnome pour avoir une idée pareille. Je ne comprends pas l’intérêt de se couper un bras, et de le remplacer avec ça, alors que vous pourriez parfaitement garder les deux bras et en ajouter un troisième !\n\nDes gnomes, je vous dis...\n\nAu moins Gerenzo est désarmé. En espérant que cette preuve soit suffisante, et que Sputtervalve m'assigne à l'un des ateliers du Syndicat des artisans à Gadgetzan ou peut-être même à Undermine.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape d'ingénieurBottes du conscrit\n\nVous recevrez également :\n\n"},
[1097] = {title = "La quête d'Elmore", objective = "Parler à Grimand Elmore.", description = "Il y a un fabricant d'armes à Stormwind, un nain du nom de Grimand Elmore, qui nous a envoyé un mot disant qu'il avait besoin d'aide avec une livraison. Je crois qu'il veut qu'un paquet soit envoyé dans son pays d’origine, dans le nord.\n\nVous avez des jambes robustes ! Si vous êtes <intéressé/intéressée> par un peu de marche à pied, alors parlez à Grimand. Nous pourrions vous utiliser ici, mais nous devons également entretenir nos bonnes relations avec les nains.\n\nVous trouverez Grimand Elmore au magasin d'armes dans le quartier des nains de Stormwind, dans la partie nord-est de la ville.", progress = nil, completion = "Vous êtes là pour m'aider avec ma livraison ? Très bien !", rewards = "Vous recevrez :\n\n"},
[1098] = {title = "Des Traqueurs noirs à Ombrecroc", objective = "Trouver les Traqueurs noirs Adamant et Vincent.", description = "En préparation d'un assaut sur Ombrecroc, deux Traqueurs noirs ont été envoyés au donjon pour réunir des renseignements. Plusieurs jours ont passé, et ils ne sont toujours pas revenus. Nous devons cependant prendre connaissance de leur rapport si nous voulons que notre attaque ait la moindre chance de réussir !\n\nAussi voici votre tâche, <nom>. Partez pour le donjon d'Ombrecroc au sud et trouvez les Traqueurs noirs Adamant et Vincent. Trouvez-les, et s'ils ont besoin d’aide, aidez-les !\n\nCette mission est aussi dangereuse qu'elle est critique, <nom>. N'échouez pas.", progress = nil, completion = "Le corps de Vincent gît, brisé et immobile.\n\nBien que le rapport du Traqueur noir Adamant parviendra à Hadrec, les détails supplémentaires que Vincent avait réunis sont encore sur lui.\n\nSa main est crispée sur un petit colifichet.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMantelet fantomatique"},
[1099] = {title = "Les gobelins gagnent !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBoîte à surprises gobeline"},
[1100] = {title = "Journal de Lonebrow", objective = "Lire le Journal de Henrig Lonebrow.", description = "Vous ouvrez lentement le journal décoloré de Henrig Lonebrow…", progress = "D'après votre mine inquiète, je peux dire que quelque chose va mal…", completion = "Vous dites que vous avez trouvé ce journal sur un nain mort ? Donnez-moi juste un moment pour lire attentivement ces pages…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1101] = {title = "La mégère du Kraal", objective = "Apporter le Médaillon de Trancheflanc à Falfindel Waywarder à Thalanaar.", description = "Pauvre Heralath ! Et ce nain... Lonebrow. Quel esprit courageux il avait.\n\nNous ne devons pas laisser leur vaillance périr pour rien. Cette mégère… Charlga Trancheflanc… doit être arrêtée.\n\nIl ne fait pas de doute qu'infiltrer le Kraal sera périlleux. Nous n'avons pas le temps d'envoyer un mot à Darnassus. <nom>, rassemblez un groupe et tuez la mégère.\n\nApportez-moi le médaillon de Trancheflanc comme preuve de son décès.", progress = "Tant que Trancheflanc rassemble des forces au Kraal de Tranchebauge, ces régions courent un grand danger.", completion = "La mégère a été enterrée. Voilà des nouvelles fantastiques, &lt;nom&gt;.\n\nEn ces temps de danger, il est rafraîchissant de voir quelqu'un d'aussi brave que vous.\n\nPuisque les laquais de Trancheflanc ont été éliminés, nos études dans ce secteur vont pouvoir se poursuivre. Peut-être que nous pouvons à présent approfondir notre connaissance du mal qui a corrompu le lieu où Agammagan s'est éteint.\n\nJ'ai bien peur cependant que la réponse à cette question ne repose également dans la trahison...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAilettes de BeryllineCeinturon Poing-de-pierreTarge marbrée\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nTromblon \"Oeil du mage\""},
[1102] = {title = "Un destin funeste", objective = "Apporter le Cœur de Trancheflanc à Stonespire le Vieil, à Thunder Bluff.", description = "Cairne est un noble chef qui a unifié notre peuple, ici, à Thunder Bluff.\n\nMais je ne peux pas pardonner aussi facilement à ceux qui nous ont éloignés de nos terres ancestrales. Mon peuple a habité les Tarides du sud pendant des décennies. Cette terre est sacrée pour nous. Mais nous en avons été chassés par de nombreux ennemis.\n\nUn destin funeste attend la sinistre mégère, Charlga Trancheflanc, qui rameute une ignoble armée depuis le Kraal de Tranchebauge.\n\nApportez-moi le coeur de Trancheflanc et je pourrai mourir en paix, <nom>.", progress = "Une fois que je saurai que les abjectes bêtes du Kraal de Tranchebauge ont été chassées de cet immonde repaire, je pourrai reposer en paix, sachant que l'heure de la revanche a sonné. Avez-vous chassé les hurans hors du Kraal ? M'apportez-vous de grandes nouvelles sous la forme du coeur de Trancheflanc ?", completion = "Je vois que l'horrible tribu du Kraal de Tranchebauge connaît à présent la douleur de mon peuple. Que cela serve de leçon à ces ignobles bêtes.\n\nChasser quelqu'un d'une terre sacrée est un péché qui appelle la vengeance la plus impitoyable.\n\nMerci, &lt;nom&gt;, de m'avoir aidé dans mon engagement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAilettes de BeryllineCeinturon Poing-de-pierreTarge marbrée\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1103] = {title = "L'appel de l'eau", objective = "Apporter un sapta d'eau à Tiev Mordune dans la forêt des Pins argentés, si vous n'arrivez pas à parler à la Manifestation d'eau mineure.", description = "Bienvenue, <mon pote/m'dame> ! Vous êtes ici pour purifier l'eau et prouver votre compréhension de cet élément à Islen ? J'viens juste de vaincre l'esprit corrompu de l'eau, ouais, moi-même, et j'm'apprêtais à placer les bracelets et les gouttes d'eau restantes dans le brasero.\n\nQu'est-ce que c'est que ce machin ? Ahhh. Tiev comprend très bien quand quelque chose tourne mal. Eh bien, Tiev peut beaucoup vous aider si vous voulez voir de nouveau l'esprit pur de l'eau.\n\nApportez-moi un sapta d'eau d'Islen comme preuve de votre bonne préparation, et j'vous attendrai pour faire ma part du travail.", progress = nil, completion = nil, rewards = nil},
[1104] = {title = "Le venin acide des salines", objective = "Apportez 6 doses de Venin de scorpide acide à Fizzle Brassbolts, dans les Salines.", description = "J'ai tellement de modèles pour notre chariot explosif ! Tellement ! Et je dois tous les essayer !\n\nJe travaille à un nouveau type de carburant. Un qui met vraiment vraiment vraiment le feu ! Je n'ai pas encore trouvé le mélange exact, mais je pense savoir ce dont j'ai besoin... Les scorpides qui vadrouillent dans les Salines ont un venin qui contient des tas et des tas d’acides. C'est tout à fait unique ! Et c'est exactement ce qu'il me faut !\n\nApportez-moi de ce venin et croyez-moi, notre chariot va voler !", progress = "Salut salut salut ! Avez-vous ce venin ?", completion = "Très bien ! Ce venin va parfaitement faire l'affaire ! Merci, &lt;nom&gt; !\n\nMaintenant je n'ai plus qu'à le faire bouillir, lui ajouter un negacatalyste, puis… Ah ! Où sont mes notes ?", rewards = "Vous recevrez :\n\n"},
[1105] = {title = "Les carapaces durcies", objective = "Apporter 9 Carapaces de tortue durcies à Wizzle Brassbolts dans les Salines.", description = "Mon frère travaille sur un nouveau carburant pour son chariot explosif. Il est brillant, vraiment. Tellement brillant que… Je pense que ce nouveau carburant va être tellement corrosif qu’il risque de dissoudre le châssis.\n\nJe veux renforcer ses réservoirs avant que ça n'arrive.\n\nLes tortues des Salines ont une carapace très résistante. J'avais l'idée de les utiliser pour créer de nouveaux réservoirs sur notre chariot explosif. Des réservoirs capables de contenir le nouveau carburant de mon frère.\n\nVous avez l'air suffisamment responsable. Vous pourriez m'obtenir ces carapaces ?", progress = "Mon frère progresse dans la conception de son nouveau carburant, et cela m'inquiète. Je dois commencer à travailler sur des réservoirs en carapace de tortue aussi tôt que possible !\n\n<nom>, avez-vous ces carapaces ?", completion = "Vous les avez ! Merci, &lt;nom&gt; !\n\nOuah, ces carapaces sont plus dures que je ne le croyais ! Quand je les façonnerai, je vais probablement tordre une pleine boîte d'outils.", rewards = "Vous recevrez :\n\n"},
[1106] = {title = "Martek l'Exilé", objective = "Apporter la Lettre de Fizzle à Martek l'Exilé dans les Terres ingrates.", description = "Je suis en train de développer un nouveau moteur. Il rendra le chariot si rapide ! Suffisamment rapide pour voler, je le sais ! J'ai juste besoin de faire des pistons qui peuvent supporter de très très grandes pressions. Tous mes essais ont échoué, car je n'arrive pas à faire des pistons suffisamment forts !\n\nMais il y a quelqu'un qui pourrait m’aider.\n\nSon nom est Martek l'Exilé. C'est un grand forgeron et il en connaît plus sur les métaux que n'importe qui d'autre. Apportez-lui cette lettre, je sais qu'il peut m'aider !\n\nMais il est très très loin. En Azeroth, dans les Terres ingrates, dans un camp, avec un gobelin !\n\nTrouvez-le !", progress = "Bien, vous m'avez trouvé. Un bon point pour vous.\n\nÊtes-vous là pour cette hache que j'ai faite pour Gath'Ilzogg ? Ou bien est-ce pour sauver l'honneur de la duchesse Parmay ?\n\nEn fait, je me fiche de savoir pour quelle raison vous êtes là. Si vous êtes là pour vous battre, eh bien finissons-en !", completion = "Fizzle vous a envoyé ? Eh bien ça change tout ! Bien sûr que je vais vous aider. Fizzle et son frère font partie des rares personnes qui ne veulent pas ma mort.\n\nAinsi, Fizzle veut faire des pistons, hein ? Des pistons suffisamment forts pour résister aux pressions qu'il a prévues, et si je connais bien Fizzle, alors ce nouveau chariot doit être un volcan à roulettes.", rewards = "Vous recevrez :\n\n"},
[1107] = {title = "Les nageoires incrustées", objective = "Apporter 10 Nageoires incrustées à Wizzle Brassbolts dans les Salines.", description = "Notre chariot explosif est ce qu'il y a de plus rapide sur les plateaux. Tellement rapide que… j'ai peur que les frottements ne le détruisent complètement.\n\nPour empêcher cela, je dois créer un composite pour enduire les parties mobiles du chariot. Il doit être dur, mais pas friable, et pouvoir résister à la corrosion du sel, ou le temps passé dans les Salines le grignotera petit à petit.\n\nAvez-vous entendu parler du Récif infâme, <nom> ? C'est près de la côte de la vallée de Strangleronce. Des murlocs Selécaille y vivent, et leurs nageoires sont un élément crucial de mon composite.", progress = "Avez-vous les nageoires ? Si je ne peux pas protéger notre chariot de l’échauffement, alors il ne fera pas long feu dans ces courses.", completion = "Merci, &lt;nom&gt; ! Mon composite sera fin prêt après pulvérisation et mélange avec quelques autres composants. Et après ça, le chariot sera à l'abri de sa propre vitesse.\n\nA l'abri, tant qu'il ne fonce pas dans quelque chose…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1108] = {title = "Indurium", objective = "Apporter 10 Flocons d'indurium à Martek l'Exilé dans les Terres ingrates.", description = "Je ne suis pas là simplement pour rester à l’écart des gens. Il y a une fortune en métal dans les Terres ingrates, <nom>, si vous avez les tripes pour aller la chercher.\n\nLe métal s'appelle l'indurium, et une de ses qualités est sa très haute résistance à la chaleur et à la pression.\n\nÇa pourrait faire l'affaire pour le chariot de Fizzle.\n\nMais nous devons nous en assurer. Trouvez-moi des échantillons d'indurium et je testerai ses propriétés.\n\nLe véritable indurium se trouve dans les profondeurs d'Uldaman, mais les troggs Cavepierre des Terres ingrates en ont parfois des flocons sur eux. Apportez-moi ces flocons.", progress = "Avez-vous trouvé des flocons d'indurium, <nom> ? Ma forge est chaude et prête à les tester.", completion = "Ah oui, ils seront parfaits. À présent plaçons-les dans la chaleur et voyons comment ils se comportent.", rewards = "Vous recevrez :\n\n"},
[1109] = {title = "Corvée de guano", objective = "Apporter 1 tas de Guano du kraal au Maître Apothicaire Faranell à Undercity.", description = "Comme vous pouvez le constater, <nom>, nous préparons de très… intéressantes expérimentations à la Société royale des apothicaires.\n\nEn tant que Maître, mon travail est de superviser les plus ambitieuses de nos tentatives alchimiques. Tellement de travail et si peu de temps !\n\nVous avez l'air d'avoir beaucoup voyagé, <classe>. Peut-être pourriez-vous m'aider.\n\nJ'ai besoin d'une substance rare. C'est un matériau infect, qui provient d'une espèce rare de chauves-souris que l'on trouve dans la fosse connue sous le nom de Kraal de Tranchebauge. Apportez-moi du guano de chauve-souris du kraal afin que nous puissions nous mettre au travail...", progress = "Ah ! Je vois que vous êtes revenu. Avez-vous pu vous procurer du Guano du Kraal ?", completion = "Splendide ! C'est juste ce qu'il nous fallait pour commencer, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1110] = {title = "Pièces de chariot explosif", objective = "Apporter 30 Pièces de Chariot explosif à Kravel Koalbeard des Salines.", description = "Eh ! Avec toutes les courses qui ont lieu ici, il n'est pas surprenant que quelques incidents surviennent le long du chemin.\n\nSi vous regardez tout autour des Salines, vous verrez des traces d’accidents. On trouve des pièces de chariots explosifs partout !\n\nEt ces pièces valent de l'argent. Elles intéressent les gnomes et les gobelins. Ils cherchent toujours des pièces à monter sur leurs chariots.\n\nAlors allez-y et trouvez-moi des pièces. Apportez-m'en un tas et je vous paierai bien.", progress = "Alors, <nom>, êtes-vous allé sur les Plateaux ? Avez-vous apporté ce tas de pièces que je vous ai demandé ?", completion = "Ouah, regardez ça ! Il y a de bonnes pièces dans ce tas de ferraille. Je suis sûr que je peux les vendre pour une jolie somme.\n\nEt… c'est pas une oreille que je vois écrabouillée entre ces deux plaques de métal ? Aouch ! Ben j'aurais pas aimé être ce pilote !\n\nMerci, &lt;nom&gt;. Voici votre salaire. Et un conseil, gratuit...\n\nSi vous cherchez suffisamment bien, vous pouvez toujours tirer profit des tragédies des autres.", rewards = "Vous recevrez :\n\n"},
[1111] = {title = "Maître des quais Dizzywig", objective = "Apporter la Commande de Kravel au Maître des quais Dizzywig à Ratchet.", description = "Mon boulot, c'est que les gens obtiennent ce dont ils ont besoin, et les gnomes par-là ont besoin qu'une commande soit passée. Leurs pièces sont arrivées à Ratchet il y a une semaine, mais je n'ai pas pu faire le voyage.\n\nAlors, êtes-vous <prêt/prête> à marcher un peu ? Allez à Ratchet, et donnez cette commande de pièces au Maître des quais Dizzywig. Il se trouvera probablement sur les docks.\n\nFaites cela pour moi, et j'aurai plus de boulots à vous confier.\n\nDes boulots, mon <ami/amie> avec de sérieux bénéfices à la clé...", progress = "Parlez plus fort ! Dites-moi, vous déposez ou vous récupérez ?", completion = "Ah oui ! Les pièces pour Kravel. Je suis content que vous soyez là. Ces choses m'encombrent depuis plusieurs jours déjà, et j'avais peur qu'elles ne commencent à rouiller.", rewards = "Vous recevrez :\n\n"},
[1112] = {title = "Les pièces détachées de Kravel", objective = "Apporter les Pièces détachées de Kravel à Kravel Koalbeard dans les Salines.", description = "Voici le paquet de Kravel, <nom>. Et lorsque vous lui remettrez, dites-lui que s'il veut plus de commandes spéciales, alors il doit payer l'addition !", progress = "Êtes-vous allé à Ratchet et avez-vous récupéré mes pièces ?", completion = "Parfait, vous les avez ! Maintenant nous devons les apporter aux gnomes. Mais avant cela…\n\nRetirons une petite pièce…", rewards = "Vous recevrez :\n\n"},
[1113] = {title = "Des cœurs zélés", objective = "Le maître apothicaire Faranell, à Undercity, veut 20 Cœurs zélés.", description = "Vous pourriez vous demander pourquoi j'ai besoin d'un type rare de guano. Eh bien, pour cette expérience, je veux voir quels effets deux substances chimiques diamétralement opposées peuvent avoir l'une sur l'autre, et spécialement lorsqu'elles sont combinées à un agent extrêmement toxique pour assurer les résultats les plus... effrayants.\n\nDans les pics au nord-est des Clairières de Tirisfal, vous trouverez le Monastère écarlate. Là, les disciples fanatiques de la Croisade se réunissent. Tuez-les et apportez-moi leur coeurs zélés.\n\nNotre mélange sera particulièrement diabolique !", progress = "Êtes-vous revenu du Monastère écarlate ? J'ai besoin de beaucoup de cœurs pour cette merveilleuse expérience !\n\nVarimathras et la Dame noire seront ravis d'être débarrassés de cette vermine écarlate.", completion = "Mais quelle effusion de sang, &lt;nom&gt; ! Vos efforts ont été plus que récompensés !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1114] = {title = "Une livraison pour les gnomes", objective = "Apporter les Pièces de chariot fragiles à Fizzle Brassbolts dans les Salines.", description = "À présent que j'ai ce dont j'ai besoin, apportez ces pièces à Fizzle Brassbolts. Cela fait longtemps qu'il les attend. Je suis sûr que la pièce que j'ai prélevée sur sa commande ne lui manquera pas…\n\nEt ça ne vaut même pas le coup de lui dire. C'est une toute petite pièce complètement inutile, de rien du tout. Minuscule...\n\nFaites-moi confiance.", progress = "Vous avez quelque chose pour moi ? Merveilleux ! Voyons cela.", completion = "Les voilà ! Mes hydrorochets et mes boulons à répétition. Ça marchera à merveille. Merci !", rewards = "Vous recevrez :\n\n"},
[1115] = {title = "Le marchand de rumeurs", objective = "Parler à Krazek à Baie-du-Butin.", description = "Maintenant que nous avons rendu un service aux gnomes, il est temps de faire une faveur aux gobelins !\n\nJe crois savoir que le pilote de course gobelin, Nazz Steamboil, n'a pas toujours porté ce nom. Je me demande pourquoi il en a changé. Je me demande s'il s'agit d'un secret, et je me demande s'il accorde de la valeur à ce secret.\n\nSi quelqu’un connaît la vérité, alors c'est Krazek à Baie-du-Butin, sur la pointe sud de Strangleronce. Parlez à Krazek et interrogez-le sur notre pilote gobelin.\n\nSi vous parvenez à en tirer une information utile, alors nous pourrions peut-être en tirer profit...", progress = nil, completion = "Vous voulez apprendre des... choses au sujet de Nazz Steamboil ? Il est pilote de course quelque part dans les Salines, je crois.\n\nOui, c'est bien possible que je puisse en trouver certaines à son propos… Mais ça ne va pas être facile. Ni rapide.\n\nNi bon marché.", rewards = "Vous recevrez :\n\n"},
[1116] = {title = "De la Poussière de rêve dans les marécages", objective = "Apporter 10 Grains de Poussière de rêve à Krazek à Baie-du-Butin. La Poussière de rêve se récupère sur les dragonnets du marais des Chagrins.", description = "Vous obtenir des informations sur Nazz est une grande faveur que je vous fais, <nom>. Oui, une grande faveur ! Mais vous avez fait tout le chemin depuis les Salines pour en avoir… Voulez-vous voyager encore un peu ?\n\nPendant que je contacte mes sources, pourquoi ne chercheriez-vous pas quelque chose pour moi, hein ?\n\nHmm... Qu'est-ce que ce sera ?... Et que diriez-vous de Poussière de rêve ? On en trouve chez les dragonnets et les wyrmides du marais des Chagrins... Oui, j'aimerais de la Poussière de rêve pour ma blague à tabac !\n\nTrouvez-m'en, <nom>, et je vous fournirai l'information que vous recherchez.", progress = "Déjà de retour ? Avez-vous ma Poussière de rêve ?", completion = "Eh bien, voyez-vous ça ! Vous avez trouvé la Poussière de rêve !\n\nEt les marécages, c'était comment, vous avez aimé, &lt;nom&gt; ?\n\nCe n'est pas facile de trouver un repas chaud dans le coin, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[1117] = {title = "Des rumeurs pour Kravel", objective = "Apporter les Rumeurs gobelines à Kravel Koalbeard dans les Salines.", description = "J'ai dû utiliser une faveur qu’on me devait et abandonner une bouteille de vin elfique rare. J'ai même dû faire des déductions difficiles moi-même. Mais j'ai trouvé l'information que vous cherchez.\n\nTenez, j'ai écrit une lettre avec des passages très croustillants au sujet de notre ami, Nazz Steamboil. Faites-en ce que vous voulez, c'est trop dangereux pour que moi je l'utilise.\n\nMais ne dites à personne qui vous a informé !", progress = "Alors, avez-vous quelque chose sur Nazz Steamboil ? Un truc qu'il voudrait garder secret ?", completion = "Eh bien eh bien ! C'est intéressant… très intéressant. Peut-être que je devrais saluer plus bas le pilote gobelin la prochaine fois.\n\nCela a beaucoup de valeur, &lt;nom&gt;.\n\nJe suis sûr que Nazz paiera une fortune pour garder son secret… secret.", rewards = "Vous recevrez :\n\n"},
[1118] = {title = "Retour à Baie-du-Butin", objective = "Apporter le Plan de Kravel à Crank Fizzlebub à Baie-du-Butin.", description = "<nom>, vous êtes quelqu'un en qui je peux avoir confiance, pour faire le boulot, mais aussi pour la fermer tout en le faisant.\n\nJ'ai échafaudé un nouveau plan, <classe>. C'est risqué, mais si ça marche, on peut tous les deux se faire un paquet ! Et je pense que vous êtes la bonne personne pour ne pas se laisser abuser.\n\nPour commencer, vous devez retourner à Baie-du-Butin. Désolé, <cher/chère> <nom>. Je sais que ma dernière quête vous y a <amené/amenée>. Mais cette fois-ci, parlez à Crank Fizzlebub.\n\nDonnez-lui cette lettre. Et s'il demande de l'aide, faites de votre mieux pour lui apporter. Cela en vaudra la peine.", progress = "Salut salut. Et qu'est-ce qui vous amène à Baie-du-Butin, <nom> ?", completion = "Je vois. Kravel a échafaudé un plan. Il a un esprit sinistre, mais c'est ce que j'aime chez lui.\n\nAinsi vous avez besoin de quelque chose pour brouiller les esprits, hein ? Quelque chose de puissant…\n\nJe me demande si la mixture dont Zanzil nourrit ses zombies pourrait être utilisée...", rewards = "Vous recevrez :\n\n"},
[1119] = {title = "La bière du sot", objective = "Rapporter la Bière du sot à Kravel, aux Salines.", description = "J'ai trouvé comment mélanger la Mixture de Zanzil avec de la bière pour créer une boisson qui décape. Une Bière du sot. Je pense que c’est exactement ce dont Kravel a besoin, mais essayez-la et dites-moi comment ça se passe.\n\nEt <nom>, ne gardez pas trop longtemps ce truc sans l'utiliser. La Mixture de Zanzil a un effet bizarre sur les levures de la bière, elle les booste un max. Mais elle ne va pas rester fraîche éternellement.", progress = "Salutations, <nom>. Est-ce que Fizzlebub a été capable de nous aider ?", completion = "Merveilleux ! Fizzlebub y est parvenu ! Je m'en souviendrai la prochaine fois que je le verrai.\n\nMerci, &lt;nom&gt;. Vous faites un travail formidable, et il se peut que nous nous fassions pas mal d'argent avec ça…", rewards = "Vous recevrez :\n\n"},
[1120] = {title = "Saoulez les gnomes", objective = "Apporter la bière du Sot au Chef-mécanicien gnome.", description = "Nous devons essayer cette bière du Sot sur l'une des équipes de mécanos. Si vous voulez l'essayer sur l'équipe des gnomes, alors tenez, prenez la bière et donnez-la au chef des mécaniciens gnomes.\n\nEt n'attendez pas trop. Cette bière va se gâter après un temps.", progress = "Salut ! Vous avez quelque chose pour moi ?", completion = "De la bière ? Comme c'est aimable ! Merci !\n\nNous ne devrions pas boire avec la course qui se prépare, mais… mes gars peuvent en boire juste un peu. En plus, elle ne doit pas être très forte, n'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[1121] = {title = "Saoulez les gobelins", objective = "Apporter la bière du sot au Chef-mécanicien gobelin.", description = "Nous devons essayer cette bière du Sot sur l'une des équipes de mécanos. Si vous voulez l'essayer sur l'équipe des gobelins, alors tenez, prenez la bière et donnez-la au chef des mécaniciens gobelins.\n\nEt n'attendez pas trop. Cette bière va se gâter après un temps.", progress = "Qu'est-ce que vous regardez ?", completion = "Mais qu'avons-nous là ? De la bibine, hein ?\n\nBien, ça ne me dérange pas si nous en avons juste un petit peu…", rewards = "Vous recevrez :\n\n"},
[1122] = {title = "Le compte rendu à Fizzlebub", objective = "Apporter le Rapport sur la Bière du sot à Crank Fizzlebub à Baie-du-Butin.", description = "Cette Bière du sot a marché à merveille ! J'ai parié sur la course suivante… Vous pensez bien que l'équipe que vous avez éméchée a fait son numéro sur le chariot !\n\nIl n'y a plus qu'une chose à faire : apportez cette note à Crank Fizzlebub à Baie-du-Butin. Il voudra connaître les résultats du test.\n\nEt avec un peu de chance, nous aurons plus de cette Bière du sot pour les courses futures !", progress = "Salutations, <nom>. Comment ça s'est passé avec cette bière ? Elle est forte, pas vrai ?", completion = "Ça raconte que la Bière du sot a été un succès. Voilà de bonnes nouvelles !\n\nSi plus tard vous en voulez davantage, alors faites-le-moi savoir et je vous demanderai de récupérer plus de Mixtures de Zanzil.", rewards = "Vous recevrez :\n\n"},
[1123] = {title = "Rabine Saturna", objective = "Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules.", description = "Pour cette tâche, vous devrez assister et aider le majordome du Gardien Remulos, Rabine Saturna, à Reflet-de-Lune. Il vous faudra explorer les terres désolées qui se trouvent loin à l’ouest de Tanaris et d’Un'Goro. Il habite à Havrenuit, le plus grand village de Reflet-de-Lune.\n\nJe voudrais que vous compreniez à quel point votre présence y est importante. En effet, les tensions ne cessent de croître entre les elfes de la nuit de Darnassus et le Cercle cénarien de Reflet-de-Lune. Essayez de vous départir de tout préjugé racial et appelez-en à la sagesse de vos ancêtres qui savaient comment traiter avec le Cercle cénarien, <nom>. Bonne chance.", progress = nil, completion = "Je suis Rabine Saturna ; au nom du Gardien Remulos et de tous les habitants de ce lieu sacré, je vous souhaite la bienvenue.\n\nJ’apprécie votre engagement auprès du Cercle cénarien. Les taurens ont fait preuve d’une incroyable allégeance aux doctrines de Cénarius, de fait la Horde est acceptée dans ce sanctuaire. La préservation d’Azeroth est un objectif commun que tous partagent.\n\nVous êtes ici entouré d’amis, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1124] = {title = "La dévastation", objective = "Parler à Layo Starstrike, à proximité du Repos des vaillants de Silithus, et lui montrer la Lettre de Rabine.", description = "A l’ouest du cratère d’Un'Goro, par la crête du nord-ouest, se trouvent d’arides terres désolées du nom de Silithus. Peu nombreux sont ceux qui savent qu’une guerre y eut lieu, opposant les elfes de la nuit à une force extérieure maléfique. Le mal put être contenu, mais maintenant nous pensons que des forces sont à l’ouvrage pour réanimer cette inimaginable... horreur.\n\nAllez voir Layo Starstrike, l’un de nos agents dans Silithus ; vous le trouverez au cimetière du Repos des vaillants, là où reposent tous ceux qui sont tombés. Donnez-lui cette lettre, afin qu’il vous accorde sa confiance.", progress = "Ceci est une terre bien trop dangereuse pour se permettre d'être désinvolte, <classe>. Qu'est-ce qui vous amène à Silithus ?", completion = "Rabine vous envoie ? Bien, considérez donc que je vous souhaite la bienvenue… autant que l'on puisse être bienvenu sur ces terres arides et inhospitalières.\n\nJe n’étais pas de ce monde au temps des grandes tribulations qui ont eu lieu ici, mais il y a des parties de ce désert qui peuvent encore illustrer ce passé oublié. Avec votre aide, le Cercle cénarien pourra peut-être mettre un terme à une menace qui aurait dû avoir disparu voilà des générations.", rewards = "Vous recevrez :\n\n"},
[1125] = {title = "Les esprits de Sudevent", objective = "Libérer l’esprit de 8 Druides torturés et de 8 Sentinelles torturées, dans le village de Sudevent, puis revenir voir Layo Starstrike, au cimetière du Repos des Vaillants de Silithus.", description = "Au sud-ouest se trouve un endroit terrible : les ruines du village de Sudevent. C’est là que nous devons commencer à travailler, <nom>.\n\nD’après ce que j’ai appris, ce village fut jadis une base des elfes de la nuit en Silithus. Il est maintenant envahi par des ruches de silithides. Je ne peux penser sans la plus grande horreur comment le village fut jadis emporté et submergé...\n\nLes esprits torturés des druides et des Sentinelles hantent les ruines, sans but. Explorez cet endroit et libérez les âmes de ces malheureux.", progress = "Alliance ou Horde, aucune importance ; personne ne mérite d'être piégé dans ce monde sous la forme d'un esprit torturé. Il faut libérer ces âmes, <nom>.", completion = "Je me disais que la ruche tourbillonnante, près des ruines du village, avait certainement joué un rôle dans sa destruction. Il semblerait également que votre travail ait fait la preuve de cette hypothèse. La proximité de cette ruche est une véritable menace pour toute entreprise que nous pourrions conduire à cet endroit.\n\nJe vous remercie pour votre implication dans la libération des esprits de ceux qui sont tombés. Ce travail n'est jamais facile, je le sais. Si vous le souhaitiez, cependant, je serais en mesure de vous donner une tâche supplémentaire à faire...", rewards = "Vous recevrez :\n\n"},
[1126] = {title = "Une ruche dans la tour", objective = "Escalader la Tour du village de Sudevent, et trouver un moyen de mettre la ruche des silithides en activité. Toute chose inhabituelle doit être rapportée à Layo Starstrike, au cimetière du Repos des vaillants de Silithus.", description = "La ruche doit être traitée au village de Sudevent, et je pense que je sais comment les atteindre. Mon expérience m’a appris que les ruches des silithides étaient extrêmement sensibles à leur environnement. Ce qui explique leurs attaques dès qu'ils entendent les gémissements des esprits.\n\nLes silithides sont plus nombreux dans la tour ; celle qui est entourée d’un nuage de guêpes. Escaladez la tour et forcez la ruche à entrer en activité. Revenez faire votre rapport sur ce que vous avez appris, mais faites attention ! Si vous découvrez quoi que ce soit qui vous semble utile, rapportez-le-moi.", progress = "Alors, est-ce que ça a marché ? Vous êtes toujours en un seul morceau, ce qui est déjà une bonne nouvelle. Avez-vous trouvé quelque chose ?", completion = "Quoi... De quoi s'agit-il ?\n\nOn dirait bien une espèce de... boîte, peut-être ? C'est recouvert d'une croûte épaisse. Attendez, il y a une partie qui a été épargnée par cette matière... N'est-ce pas un livre qui se trouve sous cet infâme magma ?\n\nJe pense que vous avez mis la main sur quelque chose de très intéressant, &lt;nom&gt;... Enfin, je l'espère. Peut-être s'agit-il d'un journal ou d'un carnet datant d'une époque révolue et que cette gangue a préservé du temps.\n\nJe pense que je sais comment en avoir le coeur net.", rewards = "Vous recevrez :\n\n"},
[1127] = {title = "Bière du sot", objective = "Apporter 12 Mixtures de Zanzil à Crank Fizzlebub à Baie-du-Butin.", description = "Ainsi, vous voulez de la Bière du sot, hein ? Vous pensez retourner aux courses ?\n\nTrès bien, apportez-moi de la Mixture de Zanzil et je préparerai davantage de bière pour vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBière du sot"},
[1130] = {title = "Melor envoie un message", objective = "Parler à Melor Stonehoof à Thunder Bluff.", description = "<nom>, Melor Stonehoof a entendu parler de vos exploits, et vous a préparé une voie à suivre.\n\nSi vous souhaitez l'emprunter, alors partez pour Thunder Bluff et parlez à Melor. Vous le trouverez sur la Cime des chasseurs.", progress = nil, completion = "Ah ! &lt;nom&gt; ! Vous voilà ! Il est temps d'envisager un voyage par les contrées lointaines, n'est-ce pas ? \n\nSi c'est le cas, jeune &lt;classe&gt;, écoutez...", rewards = nil},
[1131] = {title = "Broie-l'acier", objective = "Apportez 1 Côte de Broie-l'acier à Melor Stonehoof à Thunder Bluff.", description = "Parfois, nous chassons pour vivre. Parfois, nous chassons pour l'honneur. Et parfois, nous chassons pour mériter le savoir de la Terre-mère. \n\nMais la chasse qui vous attend n'est pas de celles-là. Il s'agit de détruire une créature qui refuse les bénédictions de la Terre-mère. \n\nLes Mille pointes, au sud des Tarides, sont le terrain de chasse de la hyène Broie-l'acier. C'est un tyran, qui attire à lui les autres hyènes, répand la terreur et massacre les bêtes plus paisibles. \n\nTrouvez Broie-l'acier, <nom>. Trouvez-le et tuez-le.", progress = "Avez-vous détruit l'horrible Broie-l'acier, <nom> ?", completion = "En tuant cet abominable Broie-l'acier, vous avez débarrassé les Mille pointes d'un terrible fléau. \n\nEt ceci, &lt;nom&gt;, est votre leçon pour aujourd'hui.", rewards = "Vous recevrez :\n\n"},
[1132] = {title = "Fiora Longears", objective = "S'adresser à Fiora Longears à Theramore.", description = "Ah ! Pouvoir prendre la mer une fois encore ! Sentir le baiser du vent, être bercé par les vagues comme un enfant par sa mère !\n\nJ'aimerais avoir votre chance, cher <classe>, car je vois la mer dans votre avenir proche !\n\nIl est de mon devoir de raconter aux âmes vaillantes la terre de Kalimdor, la terre de toutes les possibilités ! Si vous voulez chercher fortune sur la mer, prenez ici un bateau qui vous mènera au joli port de Theramore. Adressez-vous alors à mon amie, l'elfe Fiora Longears.\n\nElle vous aidera à commencer l'aventure de Kalimdor !", progress = nil, completion = "Bonjour à vous ! C'est M. Flint, du Port de Menethil qui vous envoie ? Habituellement, M. Flint fait preuve d’un bon jugement. S'il vous envoie ici, c'est que vous appartenez à Kalimdor !", rewards = "Vous recevrez :\n\n"},
[1133] = {title = "Le voyage vers Astranaar", objective = "Parler à Shindrell Switfire à Astranaar.", description = "Si vous débarquez tout juste du bateau qui vient de Menethil, la première chose à faire est d'aller à Astranaar. Je suis sûr <qu'un/qu'une> fidèle membre de l'Alliance comme vous peut faire beaucoup de bien là-bas. Allez offrir vos services à Shindrell Switfire. \n\nInutile de mentionner le nom de la personne qui vous envoie, car Shindrell ne me connaît pas...", progress = nil, completion = "Vous êtes ici pour offrir vos services à l'Alliance, &lt;nom&gt; ? Nous les acceptons avec gratitude, car même s'il lui reste sa beauté la forêt d'Ashenvale n'est plus aussi paisible qu'autrefois.", rewards = nil},
[1134] = {title = "Les Ailes-fières des Serres-Rocheuses", objective = "Apporter 12 Glandes de venin d'Aile-fière à Shindrell Swiftfire à Astranaar.", description = "Nous ne sommes pas en guerre ouverte avec la Horde, mais la paix est fragile. Leurs agents agissent clandestinement contre nous. \n\nLeurs incursions nous ont été révélées par des sources secrètes à Theramore : il semble que des orcs collectent du venin des wyvernes Ailes-fières du lac Mirkfallon, dans le sud des Serres-Rocheuses. Un venin utilisé ensuite par leurs assassins lors de raids secrets contre l'Alliance ! \n\nS'il s'agit de la vérité, nous devons les stopper, <nom> ! Nous devons anéantir leur source d'approvisionnement en venin.", progress = "Avez-vous les glandes à venin, <nom> ? Nous ne pouvons pas permettre aux orcs d'utiliser contre nous le poison de ces bêtes !", completion = "Merci, &lt;nom&gt;. Il me peine de devoir ordonner le massacre de créatures qui n'aident pas volontairement nos ennemis, mais c'est mon devoir.\n\nVotre âme peut pleurer les Ailes-fières que vous avez tués, brave cœur, mais qu'elle s'apaise en sachant que vos alliés sont préservés du venin des Ailes-fières.", rewards = "Vous recevrez :\n\n"},
[1135] = {title = "Le venin de Haut-perchoir", objective = "Apporter 10 Glandes à venin de Haut-perchoir à Fiora Longears à Theramore.", description = "Comme vous le savez, les wyvernes sont souvent domestiquées par les orcs, qui les utilisent comme montures. Ce que l'on sait moins, c'est que, dans certains cercles, le venin de wyverne est plus recherché que la bête elle-même. Si vous n'avez pas peur de chasser la wyverne, j'ai un travail pour vous.\n\nIl existe dans la région des Mille pointes, à l'ouest, un lieu nommé Haut-perchoir. Les wyvernes qui y nichent produisent un puissant venin. Très puissant et largement monnayable.", progress = "Avez-vous trouvé Haut-perchoir, <nom> ? Rencontré quelques wyvernes ?", completion = "Ah ! Voilà des poches qui débordent presque de venin, &lt;nom&gt; ! En général, il n'y a que sur les jeunes wyvernes ou les femelles fertiles que l'on peut en trouver. Il a dû y avoir un véritable massacre, là-haut à Haut-perchoir !", rewards = "Vous recevrez :\n\nCeinture des vents"},
[1136] = {title = "Gueule-glacée", objective = "Rapporter la Crinière de Gueule-glacée à Melor Stonehoof à Thunder Bluff.", description = "<nom>, il est temps pour vous de voyager vers de lointaines contrées. Le moment est venu. \n\nVous devez partir à la poursuite de Gueule-glacée, un yéti des montagnes d'Alterac. Il est très difficile à trouver, car sa fourrure blanche se confond avec la neige de ses montagnes maternelles. \n\nJe vais vous montrer comment attirer une telle créature à découvert. Prenez ce parchemin. Il vous indiquera la manière de débusquer Gueule-glacée. \n\nAllez, maintenant, <nom>. Votre voyage sera long et plein d'embûches. Votre quête sera accomplie lorsque vous rapporterez la crinière de Gueule-glacée.", progress = "Alors, vous avez visité les montagnes d'Alterac, <nom> ? Vous avez débusqué l'insaisissable Gueule-glacée ?", completion = "Vous avez trouvé et combattu Gueule-glacée. Une telle chasse demandait à la fois de la bravoure et de l'habileté, &lt;nom&gt;. \n\nVos pas vous ont mené dans les vallées des Mille pointes et dans les hautes montagnes d'Alterac. Ils vous conduiront un jour tout au long des domaines de la Terre-mère, car tel est le destin du chasseur.", rewards = "Vous recevrez :\n\nCoiffure de chasseur d'esprit"},
[1137] = {title = "Des nouvelles pour Fizzle", objective = "Parler à Fizzle Brassbolts dans les Salines.", description = "L'Indurium est étonnamment résistant à la chaleur. Je suis certain que ce métal serait idéal pour les pistons de Fizzle. Mais il lui faudra du minerai d'Indurium naturel, pas uniquement quelques paillettes. \n\nOn ne trouve ce minerai que très profondément enfoui dans les terres d'Uldaman, en bordure septentrionale des Terres ingrates. C'est là que se trouve le véritable Indurium. \n\nEnvoyez mes amitiés à Fizzle Brassbolts et répétez-lui ce que je viens de vous dire. \n\nQue votre voyage soit paisible, <nom>. Je ne serais pas étonné que nous soyons appelés à nous rencontrer de nouveau... Dès que Fizzle recevra mon message au sujet de l'Indurium, il vous enverra certainement à Uldaman pour en chercher !", progress = nil, completion = "&lt;nom&gt;, vous êtes de retour ! Avez-vous trouvé Martek ? Qu'a-t-il dit ? Peut-il m'aider ?\n\nDites-moi, vite, vite, vite ! ! !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBoute-feu de FizzleGants de mécanicien gnome\n\nVous recevrez également :\n\n"},
[1138] = {title = "Fruit de la mer", objective = "Collecter 6 morceaux de Belle chair de crabe pour Gubber Blump, à Auberdine.", description = "J’adore le crabe, ce fruit de mer par excellence ! Vous pouvez le faire griller, l’ébouillanter, le braiser, en faire des beignets frits, des acras, le déguster en salade ou le consommer en soupe ; voilà tout ce qu’on peut faire avec.\n\nJe suis ici en train de pêcher en ce moment, et je ne peux donc pas me procurer les morceaux de belle chair de crabe dont j'ai besoin. Vous pouvez en trouver sur les clampants des récifs et sur les clampants des marées incrustés. Vous pouvez en faire plein de choses. Vous pouvez le faire griller, l’ébouillanter, le braiser...", progress = "…Crabe au citron, crabe aux navetilles et le crabe surprise d'Ironforge. C'est à peu près tout.\n\nOh, bien le bonjour, <nom>. Avez-vous la belle chair de crabe dont je vous parlais ?", completion = "J'avais justement besoin de ces morceaux de belle chair de crabe. Merci &lt;nom&gt; ! J'ai trouvé ça il y a quelques temps en pêchant et je n'en ai pas l'usage. Peut-être lui trouverez-vous une utilité. C'est inutilisable pour faire de bons plats de crabe.\n\nJe vous ai tout dit à propos des crabes, n'est-ce pas ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants d'écailleurBottes crustacéennes\n\nVous recevrez également :\n\n"},
[1139] = {title = "La tablette de volonté", objective = "Trouver la Tablette de Volonté et la rapporter au Conseiller Belgrum à Ironforge.", description = "Nous avons ralenti le clan Ombreforge en le coupant du pic Blackrock, mais la quête d'Hammertoe n'est toujours pas accomplie. Sa mort ne doit pas rester vaine. Il voulait trouver la Tablette de Volonté : un morceau de pierre que les Titans avaient gravé de caractères magiques pour les aider à donner la vie à leurs créations, leur communiquer une volonté propre. C'est ce que dit la légende en tout cas. \n\nIl nous faut retrouver cette tablette avant ceux du clan Ombreforge !\n\nRepartez pour Uldaman, trouvez la Tablette et revenez ici immédiatement.", progress = "La quête d'Hammertoe doit être reprise, <nom>. Je lui dois au moins ça. \n\nVous devez impérativement retourner à Uldaman, non seulement dans ce but, mais également dans l'intérêt de toute la race des nains. Si la Tablette tombe entre les mains des Sombrefer, qui sait le pouvoir que pourrait avoir leur armée de golems.", completion = "&lt;Le Conseiller Belgrum hoche la tête d'un air surpris lorsque vous lui tendez la pierre.&gt;\n\n&lt;nom&gt;, c'est ahurissant ! Je dois la faire porter aux mages du roi aussi vite que possible. Ils voudront l'analyser pour vérifier la véracité de la légende ! Mais c'est un autre sujet. Vous avez apporté à notre peuple une aide plus grande que tout ce que nous aurions pu espérer. Merci !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMédaille de courage"},
[1140] = {title = "La tour d'Althalaxx", objective = "Libérer les Âmes de Bien-nés captives au défilé de la Nuit et à Satyrnaar, puis retourner voir Delgren le Purificateur au poste de Maestra.", description = "L'écriture des orcs est à peine plus lisible que le gribouillage d'un enfant. J'ai essuyé bien des moqueries lorsque j'ai décidé d'apprendre leur langue, mais il est toujours utile de connaître l'ennemi. \n\nSi j'en crois les griffonnages d'Ilkrud, il semble qu'Athrikus possède toujours deux gemmes d'âme captives, au défilé de la Nuit et à Satyrnaar, des régions tenues par les satyres au nord-est d'Ashenvale. \n\nFaites attention, <nom>, les temples baignés de sang des satyres peuvent être effrayants, même pour des <classe>s aguerris !", progress = nil, completion = "Les satyres ont peut-être été autorisés à résider trop longtemps dans cette forêt. J'en parlerai à Elissa la prochaine fois que je me rendrai à Auberdine. \n\nEn tout cas, le pouvoir d'Athrikus va beaucoup diminuer avec la destruction des gemmes d'âme. Nous devons en profiter pour le détruire et pour éradiquer son culte.", rewards = "Vous recevrez :\n\n"},
[1141] = {title = "La famille à la canne à pêche", objective = "Attraper 6 Mérous de Sombrivage pour Gubber Blump, à Auberdine.", description = "J’adore pêcher. La famille Blump est connue comme une grande famille de pêcheurs. Je m’appelle Gubber Blump ; je pêche.\n\nIl y a un poisson que j’aime attraper dans le coin, le mérou de Sombrivage. J’avais l’habitude d’aller en bateau pour pêcher Ie mérou, mais les bateaux ne sortent plus depuis que ces maudits murlocs sont arrivés. Je suppose qu’ils ont aussi dévoré tous les mérous.\n\nVoulez-vous m’aider à attraper des mérous de Sombrivage ? Si vous m’aidez, je vous donnerai une authentique canne à pêche de la famille Blump ! C’est une excellente canne pour attraper le poisson.", progress = "Les mérous de Sombrivage sont à l'origine d'une quantité non négligeable de plats. Ils sont savoureux, mais c'est encore plus amusant de les attraper.\n\nVous avez déjà attrapé des mérous de Sombrivage ?", completion = "Certains de ces mérous sont vraiment très beaux, &lt;nom&gt; ! Merci de votre aide !\n\nVous êtes au moins aussi bon pêcheur que ma cousine, Graun Blump. Elle porte aussi la barbe et sent particulièrement fort, mais ça ne l'empêche pas de continuer à pêcher. J'admets que vous avez ce qu'il faut pour utiliser une canne à pêche de la famille Blump.", rewards = "Vous recevrez :\n\nCanne à pêche de la famille Blump"},
[1142] = {title = "Le déclin et la mort", objective = "Trouver et rapporter le Pendentif de Treshala à Treshala Fallowbrook à Darnassus.", description = "Il ne me reste plus beaucoup de temps... Tellement... Tellement faible... \n\nLe brave Lonebrow a été envoyé pour avertir Falfindel... \n\nMais avant que je ne m-m-meure... \n\n... Ma femme, Treshala... Son pendentif de mariage avec moi... V-v-volé... par un de ces sauv-v-vages agresseurs... \n\nTrouvez-le, j-j-je vous en prie... Et rapportez-le à Treshala, à Darnassus...\n\n... Et racontez-lui ma mort... solitaire.", progress = "Qu'est-ce qui vous amène dans ma maison, <race> ?", completion = "Non !\n\nCe n'est pas juste ! Monde cruel et intolérable !\n\nJe devrai à présent porter ce fardeau de douleur ; mais je ne laisserai pas le travail de Heralath partir avec lui.\n\nVous avez montré du courage lors de votre voyage par ces contrées si dangereuses, &lt;nom&gt;. Maintenant, laissez-moi, je vous en prie.\n\nC'est dans la solitude que je veux pleurer son départ.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChâle de deuilBottes du lancier\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1143] = {title = "La tour d'Althalaxx", objective = "Tuer Athrikus Narassin et apporter sa Tête à Balthule Shadowstrike près de la Tour d'Althalaxx.", description = "Je vois. Si ce que vous affirmez est vrai, alors c'est le moment de frapper. Je sais qu'Athrikus réside en haut de la tour. Faites attention, car il est entouré de nombreux démonistes, bien plus dangereux que ceux que vous avez déjà combattus.", progress = "Athrikus Narassin est un vieux et puissant démoniste. Nous devrions peut-être attendre l'aide de Delgren, mais il avait l'air de vous faire confiance, puisqu'il vous a envoyé seul ici.", completion = "J'espère que la mort d'Athrikus Narassin va faire reculer les forces démoniaques dans cette région ! Je sais qu'elles vont se regrouper et attaquer, mais nous serons préparés à les recevoir.", rewards = "Vous recevrez :\n\n"},
[1144] = {title = "Willix l’Importateur", objective = "Escorter Willix l'Importateur hors du Kraal de Tranchebauge.", description = "Enfin de l'aide ! \n\nVous n'avez pas idée du temps que j'ai passé prisonnier ici ! Je n'arrive plus à me rappeler quand j'ai vu le monde extérieur pour la dernière fois. \n\nVous voyez, je suis un entrepreneur. Prêt à tout en échange d'un sou, si vous voyez ce que je veux dire. J'avais entendu dire que Mizzyrix payait bien pour les Racines de Feuillerouge locales, de ce trou à rats ! Je pensais que ce serait de l'argent facile. Je me trompais et pas qu'un peu ! \n\nEnfin... Merci de m'avoir sorti de là, je vous le revaudrai...", progress = nil, completion = "Merci encore, camarade ! Je vous l'avais dit que je vous le revaudrais...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau du singeArceau du serpentAnneau du tigre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1145] = {title = "L'essaim s'agrandit", objective = "Remettre la Note scellée de Korran à Belgrom Rockmaul à Orgrimmar.", description = "Bien des voyageurs qui sont passés par la Croisée m'ont aidé à ramasser des oeufs dans le Champ des géants, et nombreux sont ceux qui ont rapporté des récits effrayants sur les créatures. J'en ai assez entendu pour considérer ces insectes comme plus dangereux que ne l'avaient cru mes maîtres de prime abord. \n\nJ'ai besoin d'un courrier pour aller à Orgrimmar trouver Belgrom Rockmaul. Cela ne sera pas simple et celui qui ira devra prendre cette tâche au sérieux. \n\nOn trouve généralement Belgrom devant la maison des guerriers.", progress = "Je vous envie, <classe>. Vous avez l'allure de quelqu'un qui n'est pas allé à Orgrimmar depuis un moment. \n\nMoi aussi je voyagerais au nom du Chef de guerre si Thrall n'avait pas besoin de mes compétences ici, dans la cité. Il nous gouverne bien et j'ai grande confiance en son jugement... Je resterai ici aussi longtemps qu'il aura besoin de moi.", completion = "Ah ! Une note de Korran. Il nous sert loyalement depuis un moment déjà. Je me demandais comment avançait sa mission à la Croisée.", rewards = "Vous recevrez :\n\n"},
[1146] = {title = "L'essaim s'agrandit", objective = "Apporter la Note scellée de Belgrom à Moktar Krin aux Mille pointes.", description = "Ainsi, Korran est arrivé aux mêmes conclusions que nous sur ces insectes... On dirait qu'il s'agit d'une menace plus grande que nous ne le pensions au départ. \n\nIl y a quelques jours, un chasseur est rentré à moitié mort des Mille pointes. Il accompagnait un groupe chargé de déloger une équipe de fouille naine hors des Salines. Une nuée de ces insectes a jailli d'une grotte pendant l'attaque et les a presque anéantis.\n\nIls étaient sous les ordres de Moktar Krin et ils se sont réfugiés à la lisière des Salines. Apportez-lui cette note.", progress = "C'est la guerre qui a conduit ma section dans les Salines, <classe>. Et vous, qu'est-ce qui vous amène ici ?", completion = "Ne vous effrayez pas des échos renvoyés par les parois de la montagne. Ce n'est pas le tonnerre. Les gobelins et les gnomes font la course dans les Salines à bord de ces atrocités issues de ce qu'ils appellent « science ». Il y a des menaces plus graves qui pèsent sur les Mille pointes, et l'une d'elles a détruit plus de la moitié de mes hommes. \n\nNous resterons ici jusqu'à ce que nous recevions des ordres de Belgrom, d'Orgrimmar. Nous tiendrons la position et resterons vigilants.", rewards = "Vous recevrez :\n\n"},
[1147] = {title = "L'essaim s'agrandit", objective = "Tuer 5 Chercheurs silithides, 5 Bourdons silithides et 5 Envahisseurs silithides, puis retourner voir Moktar Krin aux Mille pointes.", description = "Hum... On dirait que Belgrom pense que ces monstres sont une menace. Il veut que nous les repoussions jusque dans les profondeurs abjectes d'où ils sont sortis. \n\nOn dirait que tuer les nains de la Ligue des Explorateurs ne leur a pas suffi... Et maintenant il va falloir que j'envoie une section à moitié anéantie mener une nouvelle bataille. Nous ne pourrons pas réaliser cette mission par nous-mêmes. Pas tant que nous serons dans cet état. Le site de fouilles est là-bas vers le sud. Envie de manier l'épée et de nous donner un coup de main ?", progress = nil, completion = "Ah ! Cet ichor qui vous couvre vous embellit, &lt;nom&gt; ! Et cela vous donne une odeur... Une odeur... Qui empeste ! Ne vous approchez pas trop des kodos : vous provoqueriez une cavalcade ou vous les mettriez en chaleur.\n\nJe pense que mes compagnons seront d'accord pour admettre que cette odeur à elle seule est la preuve que vous avez pris part au combat contre ces insectes. Merci &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1148] = {title = "Des parties de l'essaim", objective = "Apporter 1 Coeur de silithide, 5 Serres de silithide et 3 Carapaces de silithide intactes à Korran, à la Croisée.", description = "Vous inspectez la carapace avec soin. Comme vous la tournez, vous comprenez que le placage est entrecroisé de telle manière qu'elle lui donne une dureté incroyable. Cela ne ressemble à rien que vous connaissiez. Vous inspectez le reste du corps et vous réalisez que ces créatures sont très puissantes et très évoluées. \n\nEn regardant de nouveau la carapace, vous vous dites que Korran apprécierait sûrement d'étudier ces créatures d'un peu plus près. Cela l'aiderait à découvrir ce qu'elles sont et d'où elles viennent.", progress = "Cela fait un moment que vous n'étiez venu me voir, <nom>. Que puis-je pour vous ? Vous avez la mine de quelqu'un qui s'est trouvé récemment au cœur de la bataille. Bien. Bien pour la Horde et pour vous. Plus vous remporterez de batailles et plus vous serez utile. Plus vous aurez de force.", completion = "Ah ! Vous avez vu Moktar récemment ? Il me cherche en permanence. Je suis désolé de savoir qu'il passe son temps à dorloter sa petite bande de guerriers au lieu de se porter à la bataille, mais je suis sûr qu'il prend beaucoup de plaisir à tuer les membres de la Ligue des Explorateurs. \n\nTrès malin, de m'apporter ces spécimens, &lt;nom&gt; ! Avec les œufs que nous trouverons dans le Champ des géants, cela permettra de découvrir l’origine de ces insectes et leur but.", rewards = "Vous recevrez :\n\n"},
[1149] = {title = "L'épreuve de la Foi", objective = "Si vous avez la Foi, sautez des planches qui dominent les Mille pointes.", description = "Vous me cherchiez, ou peut-être est-ce le destin qui vous mène à moi ? Aucune importance. Vous voilà et un nouveau voyage commence pour vous. \n\nIl y a différents aspects dans un être : l'esprit, le corps, l'âme. Certains peuvent être améliorés par les traditions d'une culture. Pour d'autres... Nous pouvons simplement espérer qu'elles existent en nous. Si vous êtes d'accord, je vais mettre à l'épreuve quelques-unes de vos qualités. \n\nSi vous réussissez, vous y gagnerez en force. Si vous échouez, vous comprendrez l'immensité du Néant. \n\nLa première épreuve est l'Epreuve de la Foi.", progress = "La Foi. Elle est plus importante que vous ne l'imaginez. \n\nParfois, croire est plus important que ce à quoi l'on croit.", completion = "Ce n'est que lorsque nous affrontons une adversité inconnue que nous montrons la force de notre esprit. Vous avez risqué le Saut de la Foi alors que vous n'aviez aucune garantie de survie. Votre esprit est ouvert et votre âme préparée à l'adversité. \n\nSi vous le voulez, vous allez passer l'épreuve suivante.", rewards = "Vous recevrez :\n\n"},
[1150] = {title = "L’épreuve de l’Endurance", objective = "Apporter la Griffe de Grenka au traqueur des plaines Dorn, aux Mille pointes.", description = "Il me plaît de constater que votre courage reste entier à la lumière de ce que vous avez déjà réalisé. Puisque votre foi est grande, il est temps de mettre les capacités de votre corps à l'épreuve. Allez avec des amis jusqu'à la tanière des Volplumes, à l'ouest du poste de Librevent. Plongez au cœur de leur tanière et détruisez leurs réserves de nourriture. Cela devrait provoquer leur colère, et si vous êtes capable de survivre assez longtemps à leur furie, Grenka Hurlesang elle-même s'attaquera à vous... Tuez-la et apportez-moi sa griffe en accomplissement de votre épreuve.", progress = "Vous devez vous préparer spirituellement, mentalement et physiquement pour les épreuves qui vous attendent. \n\nNous nous précipitons trop souvent vers l'aventure sans être certains d'être prêts. Je considère comme mon devoir envers les jeunes gens, quelle que soit leur tribu, de les préparer aux dangers qu'ils affronteront une fois hors du sanctuaire familial.", completion = "Grenka était puissante, même pour un &lt;race&gt;. Votre réussite d'aujourd'hui doit vous emplir de fierté. \n\nPendant l'Epreuve de la Foi, vous avez montré de la force d'âme, et vous venez de montrer de l'endurance dans la bataille en vous attaquant aux harpies Volplumes, mais le temps d'une nouvelle épreuve est venu.", rewards = "Vous recevrez :\n\n"},
[1151] = {title = "L'épreuve de la Force", objective = "Apporter des Fragments de Rok'Alim au traqueur des plaines Dorn dans les Mille pointes.", description = "Au temps des Dieux très anciens, les élémentaires peuplaient ce monde. Ils adoraient les Dieux très anciens, et le pouvoir de ces derniers maintenait les élémentaires attachés à ce monde. Lorsque les Dieux très anciens furent bannis, les élémentaires disparurent de notre monde et ils n’y reviennent que s'ils sont appelés par de puissants mages. \n\nIl y a pourtant des exceptions. Certains élémentaires étaient suffisamment puissants pour rester. L'un d'eux est Rok'Alim. \n\nPour mettre votre force à l'épreuve, trouvez Rok'Alim dans les Mille pointes et tuez-le.", progress = "Rok'Alim est aussi appelé le Marteleur par les tribus centaures des Mille pointes à cause de la façon dont ses poings martèlent les créatures assez braves... ou assez stupides pour se trouver sur son chemin.", completion = "L'Epreuve de la Force est réussie. Vous avez montré de la bravoure et de la force et vous voilà digne d'affronter la dernière épreuve pour finaliser les rites.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1152] = {title = "L'épreuve de la Connaissance", objective = "Trouver Braug Dimspirit près de l’entrée de la Perce des Serres dans les Serres-Rocheuses.", description = "Vous avez presque terminé votre apprentissage avec moi, mais l'Epreuve de la Connaissance n'est pas de mon ressort. Il y a des leçons que l'on apprend et des lieux que l'on visite pour lesquels il faut un autre guide que moi-même. \n\nSi vous vous sentez apte, cherchez Braug Dimspirit... C'est un chaman d'une grande sagesse. Il vous mettra à l'épreuve, alors prêtez attention à ses paroles, <nom>. \n\nLorsque vous vous estimerez apte, trouvez le tunnel qui relie les Serres-Rocheuses et Ashenvale : Braug habite près de là. Mais soyez <prudent/prudente>, <nom>. Les elfes de la nuit pourraient vouloir vous empêcher d'accomplir votre épreuve.", progress = nil, completion = "Les jours et les nuits refroidissent au fur et à mesure que les gobelins détruisent la terre et que les elfes de la nuit montrent du doigt les races moins anciennes. Les Réprouvés et les orcs ne sont pas les seuls à blâmer pour les malheurs de Kalimdor et de Lordaeron. Bien nombreuses sont les races intelligentes qui ont contribué aux malheurs du monde. Dorn le sait et il vous envoie vers moi, car vous avez les qualités pour comprendre cela vous aussi. \n\nMaintenant vous voilà devant Braug.", rewards = "Vous recevrez :\n\n"},
[1153] = {title = "Un nouveau minerai", objective = "Trouver un échantillon de minerai brut sur un Mineur ou un Géomètre Mufle-de-gravier et l’apporter à Tatternack Steelforge, à Camp Taurajo dans les Tarides.", description = "Vous m'avez apporté une aide précieuse par le passé, <classe>. Le Chef de guerre apprécie, au moins jusque-là, ce que j'ai accompli, et me demande de continuer avec une nouvelle détermination. Mon honneur me commande de vous envoyer au Chef de guerre avec une recommandation pour tout ce que vous avez fait, mais avant je voudrais vous demander votre aide une nouvelle fois. \n\nDes voyageurs, récemment revenus d'un endroit appelé les Mille pointes, ont tué un kobold porteur d'un échantillon d'un minerai inhabituel. Ils n'ont pas voulu le vendre. Je voudrais que vous me rapportiez un échantillon de ce minerai.", progress = "J'ai revu ces voyageurs... Ceux qui refusent de me vendre l’échantillon de minerai. Je leur ai craché dessus, car ils refusent d'aider le Chef de guerre. \n\nPuissent-ils périr en lâches dans la bataille et non en guerriers, comme il est juste pour tous les alliés de la Horde !", completion = "Un bel échantillon, &lt;nom&gt; ! Bel échantillon, en vérité !\n\nCes voyageurs ne pourront plus me regarder de haut avec leur découverte, maintenant que vous avez réussi.\n\nIl faut que je me mette au travail immédiatement. S'il est assez résistant, j'enverrai au Chef de guerre une arme forgée dans ce métal pour lui montrer notre réussite.\n\nJe n'oublierai pas votre aide, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nEpée de guerre orque"},
[1154] = {title = "L'épreuve de la Connaissance", objective = "Trouver l’Héritage des Aspects et l’apporter à Braug Dimspirit, à côté de l’entrée de la Perce des Serres, dans les Serres-Rocheuses.", description = "Vous avez réussi les épreuves de Dorn et vous cherchez à présent le défi suivant. Ce que vous avez réussi, un enfant aurait pu le réussir. Il est facile de mettre son corps à l'épreuve. Pour l'esprit, c'est tout autre chose. \n\nJe vais m'expliquer simplement : trouvez le livre dont je vais vous parler, étudiez-le et répondez à mes questions sur son contenu. \n\nQuel livre ? « L'Héritage des aspects ». On peut le trouver au pied de Dor'danil au sud d'Ashenvale, protégé par les druides morts et leurs assassins.", progress = "Apportez-moi le livre après l'avoir étudié. Je ne poserai pas de questions tant que vous ne l'aurez pas lu.", completion = "Voilà le livre que j'ai indiqué. J'espère que vous répondrez bien à mes questions... À moins que vous n'ayez négligé d'étudier son contenu.\n\nPréparez-vous avant de me parler de nouveau et je vous poserai une question.", rewards = "Vous recevrez :\n\n"},
[1159] = {title = "L'épreuve de la Connaissance", objective = "Trouver Parqual Fintallas à Undercity.", description = "Bien joué, <nom>. Vous avez passé la première partie de l'Epreuve de la Connaissance, mais il reste une question à laquelle vous devez répondre. Cette question, je ne puis la poser.\n\nCherchez Parqual Fintallas dans la cité de Lordaeron. C’était un grand historien parmi les humains, avant d'être emporté par la Peste. Il continue sa quête du savoir, mais un savoir d'une nature différente.\n\nIl exigera de vous une certaine tâche avant d’accepter de vous tester, mais vous avez superbement mené à bien les épreuves jusqu'ici... Je suis sûr que vous surmonterez cet obstacle.", progress = nil, completion = "C'est Braug qui vous envoie ? Impossible. \n\n&lt;Parqual vous détaille de la tête aux pieds&gt; \n\nVous avez bravé Dor'danil, fait le saut de la Foi, combattu et anéanti un élémentaire puissant ? Tout cela n'est sans doute qu'une escroquerie : vous avez dû entendre quelque conversation de taverne. Et maintenant vous vous croyez digne de passer mon épreuve ? Qu'il en soit ainsi, alors... &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[1160] = {title = "L'épreuve de la Connaissance", objective = "Trouver « Les commencements de la menace des morts-vivants » et le rapporter à Parqual Fintallas à Undercity.", description = "Je vous dirai ce que vous devrez chercher, et je vous poserai même ma question, mais certainement pas parce que vous cherchez à vous prouver quelque chose à vous-même. La Connaissance est bien plus importante que la force. Même si d'autres vous surpassent en habileté, votre connaissance du monde vous sera précieuse. \n\nRendez-vous au Monastère au nord des Clairières de Tirisfal. Dans la bibliothèque, vous trouverez un livre intitulé « Les commencements de la menace des morts-vivants ». Il était utilisé par les paladins, désormais corrompus, pour leur entraînement contre ceux de ma race. \n\nApportez-le-moi.", progress = "J'espère que vous avez fait souffrir les membres de la Croisade écarlate avant de leur voler le livre. \n\nMon opinion sur ce groupe n'est pas injustifiée. Peut-être qu’à une certaine époque les membres de la Croisade ont cherché la Lumière, mais aujourd’hui ils cherchent à anéantir toutes les créatures qui ne partagent pas leur point de vue. Ils sont convaincus que tous les morts-vivants, Réprouvés ou autres, doivent être détruits et que ceux qui passent sur leurs territoires sont fous ou contaminés par les pouvoirs démoniaques. Idiots. Idiots et cruels. Tous autant qu'ils sont.", completion = "C'est le livre que je vous ai envoyé chercher. \n\n&lt;Parqual contemple longuement le livre en passant sa main sur la couverture.&gt; \n\nEt maintenant vous voulez que je vous pose une question pour que vous puissiez prouver que votre esprit est aussi puissant que votre corps et votre âme. Si vous avez suffisamment étudié le livre, je vous poserai la question et vous en aurez fini avec ces épreuves.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1164] = {title = "Le voleur volé", objective = "Apporter la Tête de Kenata, Fardel et Marcel Dabyrie à Genavie Callow à Undercity.", description = "La traînée ! La truie ! Kenata vit toujours ; sa famille est riche et prospère tandis que je souffre, comme une Réprouvée que je suis !\n\nMa famille a disparu, emportée par la peste. Notre domaine a disparu, lui aussi, détruit et brûlé pendant la guerre. Et malgré cela, aidée de ses misérables enfants, elle a l'audace de voler le seul bien qui me reste.\n\nJe n'attache plus d'importance aux choses qui m'ont été volées. Ce que je veux à présent c'est leurs têtes !\n\nTuez-les pour moi ! Rendez-vous à la ferme des Dabyrie en Arathi, au nord-est du Refuge de l'Ornière.", progress = "Tuez-les et apportez-moi leurs têtes.", completion = "Vous vous tenez devant moi comme la personnification de la vengeance et je m'incline devant vous avec gratitude. \n\nAvec la mort de cette traînée, et en sachant que sa descendance ne souillera plus la terre d'Azeroth, je vais pouvoir consacrer mon énergie à une activité plus lucrative. J'espère que vous avez détruit leur ferme après les avoir tués.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEspauliers sinistresCrispins de Gallan\n\nVous recevrez également :\n\n"},
[1166] = {title = "Les soucis du Seigneur Mok'Morokk", objective = "Le seigneur Mok'Morokk de Mur-de-Fougères veut que vous retrouviez son grog, son tabac à priser et son coffre dans le marécage d'Âprefange.", description = "Inclinez-vous devant le seigneur Mok'Morokk !\n\nRexxar faire de moi le puissant chef du clan Cognepierre !\n\nMoi bon chef. Moi garder clan en sûreté.\n\nGrands dragons venir et faire le feu avec anciennes maisons. Mais moi ogre malin. Trouver nouveau foyer pour clan ici.\n\nQuitté ancienne maison trop vite. Oublié truc. Minuscule <race>, aller trouver mes trucs. Aller sud et trouver mon grog délicieux, mon tabac à priser et mon coffre. Moi apprécier vous après ça. Chercher dans Antre des flammes et dans ruines Cognepierres... Mes trucs là-bas, moi sûr !", progress = "Moi soif de grog. Moi envie de priser aussi. Où est coffre de moi ? Trouver pour seigneur Mok'Morokk. \n\nAller et trouver sud dans vieille maison. Moi trop de travail chef des ogres pour aller.", completion = "Vous parfait &lt;race&gt;. Moi languir mes choses beaucoup. Moi aimer vous maintenant.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEnormes bottes d'ogre"},
[1167] = {title = "La tour d'Althalaxx", objective = "S'entretenir avec Balthule Shadowstrike près de la Tour d'Althalaxx.", description = "Il serait sage de vous entretenir avec Balthule avant d'affronter Athrikus. Il a certainement observé la Tour avec une grande vigilance et il pourrait avoir des renseignements intéressants.", progress = nil, completion = "Ah ! Ravi de vous revoir, &lt;nom&gt; ! Il se passe des choses particulièrement étranges par ici et je suis content que vous soyez de retour !\n\nVraiment bizarre, &lt;nom&gt;. Tout avait l'air normal (enfin, pour autant que les choses puissent être normales par ici) et tout à coup un éclair aveuglant s'est échappé de la pièce la plus haute de la Tour. Puis il y a eu les cris. Des hurlements qui déchiraient l’air et des éclairs qui frappaient le sol de temps à autre. Qu'est-ce qui se passe ?", rewards = "Vous recevrez :\n\n"},
[1168] = {title = "L'armée des dragons noirs", objective = "Tharg de Mur-de-Fougères veut que vous tuiez 15 Eclaireurs Crins-de-feu, 10 Queues-cendrées Crins-de-feu et 5 Gardes Crins-de-feu.", description = "Mok'Morokk fait seigneur par Rexxar. Lui faire attention plus pouvoir que ogres. \n\nDragons noirs tuer beaucoup ogres. Tuer femme de Tharg. Mok'Morokk dire s'enfuir. Venir ici. \n\nOgres devoir combattre. Ogres pas bons pour fuite. Mok'Morokk seulement intéresse Mok'Morokk. \n\nMoi appeler maison \"ruines Cognepierres\". Moi mieux au sud. Ici pas maison. \n\nAider ogres à combattre armée des dragons noirs. Moi vouloir vengeance. Moi vouloir rentrer maison.", progress = nil, completion = "Vous tuer beaucoup armée dragons noirs. Vous brave &lt;race&gt;.\n\nVous rendre Tharg heureux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLacet de ThargBouclier de Tharg\n\nVous recevrez également :\n\n"},
[1169] = {title = "Identification de la portée", objective = "Draz'Zilb de Mur-de-Fougères souhaite que vous lui apportiez 15 Langues d'incendiaire et 15 Cœurs d'incendiaire.", description = "Voyez ce vieux fou de Mok'Morokk, qui se complaît dans son pouvoir et Tharg, qui combat les démons du désespoir et de la vengeance tout en espérant prendre la direction du clan. On dirait que je suis le seul qui cherche à connaître la source de l'agression qui a détruit notre ancien foyer.\n\nPourquoi ce regard ahuri, <nom> ? Vous vous attendiez à m'entendre parler comme un forban mal dégrossi parce que je suis un ogre ?\n\nBon ! Au travail, maintenant ! Apportez-moi des cœurs et des langues de dragonnets incendiaires et de jeunes incendiaires. Je pourrai alors chercher la source du mal.", progress = "Avec les cœurs et les langues des rejetons brûlés de l'armée des dragons noirs, je peux étudier la bête immonde qui a jeté sa progéniture contre nos maisons. Peut-être qu’en les connaissant mieux pourrons-nous trouver un moyen de les détruire une bonne fois pour toutes et rebâtir le village des Cognepierres. \n\nBien sûr, convaincre Mok'Morokk de traîner sa grosse masse léthargique hors de ce trou à rats sera en soi une quête épique...", completion = "Cette collecte de cœurs et de langues constituait une aventure périlleuse, sans aucun doute. Il me faudra plonger dans les profondeurs des arcanes pour comprendre l'origine de la menace noire qui a fondu sur notre ancien foyer.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape brûléeGants de voleur de bétail\n\nVous recevrez également :\n\n"},
[1170] = {title = "La portée d'Onyxia", objective = "Parler au seigneur Mok'Morokk au village de Mur-de-Fougères.", description = "Le village des Cognepierres a été envahi par la portée d'Onyxia. Mais pourquoi la fille d'Aile de mort, le seigneur du vol noir, est-elle descendue sur nos champs ?\n\nC'est très troublant. Onyxia a sûrement un autre but que de faire le siège d'un petit village ogre.\n\nRendez immédiatement compte à Mok'Morokk ! Il faut agir !", progress = nil, completion = "Pourquoi parler dragons à moi ? Moi pas aimer dragons. Moi aimer ici. Pas dragons ici.", rewards = "Vous recevrez :\n\n"},
[1171] = {title = "La portée d'Onyxia", objective = "Parler à Draz'Zilb à Mur-de-Fougères.", description = "Vous me laisser maintenant. Aller dire à Draz'Zilb nous rester ici. Pas de dragon noir ici.", progress = nil, completion = "Lâche et paresseux ! \n\nMok'Morokk montrait de la bravoure lorsque Rexxar était notre chef. Mais après le départ de Rexxar, il a été tenté par l’illusion du pouvoir. Plutôt que de conduire son peuple, il a exigé. Il ne sert pas, il veut être servi. \n\nIl faut faire quelque chose.", rewards = "Vous recevrez :\n\n"},
[1172] = {title = "La portée d'Onyxia", objective = "Draz’Zilb, de Mur-de-Fougères, veut que vous détruisiez 5 des Œufs d'Onyxia.", description = "L'engeance d'Onyxia s'est répandue dans tout le Cloaque aux dragons. Il est impératif d'empêcher les dragonnets d'éclore. \n\nHâtez-vous de rejoindre la tourbière du Ver, au sud du marécage d'Âprefange. Il est sûr qu'elle a laissé ses œufs là-bas. Trouvez-les tous et détruisez-les. \n\nNous ne pourrons jamais rebâtir le village des Cognepierres si les environs servent de nid aux dragons ! \n\nQuant à Mok'Morokk, j'ai d'autres plans pour lui…", progress = "Dépêchez-vous de rejoindre le Cloaque aux dragons, <nom>. Avec les œufs d'Onyxia répartis tout autour de la tourbière du Ver, nous serons vite débordés par le nombre des dragons si nous ne faisons rien. \n\nDétruisez ses œufs ! Ne laissez pas la malédiction des dragons noirs se répandre sur notre terre natale !", completion = "Magnifique ! Il faudra du temps avant qu'Onyxia ne ponde d'autres œufs.\n\nAu nom de mon peuple, merci, &lt;nom&gt;.\n\nJ'ai déjà beaucoup exigé de vous, mais peut-être pouvez-vous rendre un dernier service au clan Cognepierre ?\n\nMok'Morokk n'est pas digne de nous conduire. Tharg serait un excellent chef, mais il est diminué par ses blessures et par son âge. Débarrassez cet endroit de Mok'Morokk par la force. Alors seulement nous pourrons choisir un nouveau chef pour nous ramener jusqu'à notre terre natale dans le sud.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes EncarmineBottes de Zua'tec\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1173] = {title = "Défier le Seigneur Mok'Morokk", objective = "Défaire Mok'Morokk en combat singulier et rapporter la nouvelle à Draz’Zilb au village de Mur-de-Fougères.", description = "Toi oser défier le Seigneur Mok'Morokk ? \n\nMorbleu ! \n\nMoi écraser <race> comme un insecte ! \n\nToi me dire quand vouloir bonne raclée.", progress = nil, completion = "Ce couard de gros plein de soupe a fui comme un lapin. Vous avez rendu là un grand service à tout le monde, &lt;nom&gt;. \n\nMaintenant mon clan va pouvoir choisir un nouveau chef qui nous aidera à reconquérir notre terre natale une bonne fois pour toutes.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague démoniaqueBâton Chillnail\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1174] = {title = "Et ce sont les gnomes qui gagnent !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBoîte à surprises gnome"},
[1175] = {title = "Les cahots de la piste", objective = "Tuer 10 Basilics du sel gemme, 10 Peaux de cristal du sel gemme et 10 Contemplateurs du sel gemme pour le maître pisteur Zherin des Salines.", description = "Après le gros accrochage entre le Tonnerre rouge gobelin et un basilic, Kronkrider m'a embauché pour surveiller la piste. Je ne sais pas ce que mangent les animaux d’ici pour grossir comme ça, mais il faut réduire leur nombre si nous voulons éviter qu'ils ne se baladent sur la piste pendant une course. \n\nJe vais vous dire : si vous voulez gagner un peu d'argent sortez d'ici et faites dégager les basilics de la zone.", progress = nil, completion = "J'espère que vous n'avez pas tué les basilics sur la piste elle-même ! Les carcasses mettent un temps fou à se décomposer au soleil et j'aimerais autant ne pas avoir à sortir la pelle pour les débarrasser !", rewards = "Vous recevrez :\n\n"},
[1176] = {title = "Allégement de la structure", objective = "Se procurer 10 Os creux de vautour pour Pozzik dans les Salines.", description = "Quand on veut vraiment courir, chaque détail compte. Il faut tout prendre en compte depuis la plus petite chute de puissance jusqu'au plus léger défaut dans la tension des fils des bobines, en passant par un trop grand allégement du châssis… \n\nNous utilisons des os de vautour pour fabriquer une grande partie des structures mineures de nos voitures, qui sont des modèles d'équilibre entre légèreté et solidité. Cela pourrait être encore amélioré si nous avions plus de ces os ! Ils sont faciles à obtenir : les plateaux salés sont littéralement infestés de vautours. \n\nRapportez-moi des os de vautour et vous recevrez une récompense en échange.", progress = "Avez-vous trouvé ces os pour moi ? Je travaille à l'allégement de la structure de manœuvre, mais je ne veux pas la démonter tant que je ne dispose pas de toutes les pièces nécessaires.", completion = "Magnifique ! Je peux mettre mon équipe immédiatement sur ce projet ! Merci, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[1177] = {title = "Faim !", objective = "Pilebou Piessale, dans le nord d'Âprefange, veut 12 Têtes d'Aileron boueux.", description = "Pil'bou grand ogre.\n\nMoi faim.\n\nAller taper poisson. Apporter manger pour Pil'bou.\n\nVous nourrir Pil'bou sinon Pil'bou manger vous.", progress = "Donner nourriture ou devenir nourriture !", completion = "Moi aimer têtes de poisson !\n\nMoi pas manger vous tout de suite.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPresse-boueBottes de Durtfeet\n\nVous recevrez également :\n\n"},
[1178] = {title = "Mécénat gobelin", objective = "Parler à Gazlowe à Ratchet.", description = "Notre équipe de course est la fierté de tous les gobelins ! Vous seriez surpris si je vous disais les noms de tous ceux qui y participent, d'une manière ou d'une autre ! \n\nVous connaissez Gazlowe ? Il voyage dans le monde entier pour nous rapporter nos pièces détachées. Il a même participé une fois à la construction d'un des engins ! \n\nIl y a quelques semaines, il a dit qu'il nous enverrait un nouveau prototype de régulateur de carburant, mais il n'est pas encore arrivé. D'habitude, il est plus rapide que ça... Peut-être accepteriez-vous d'aller à Ratchet pour le lui demander ? Je sais que j'exagère un peu en vous le demandant, mais les gnomes sont en train de nous prendre de vitesse !", progress = nil, completion = "C'est Pozzik qui vous envoie ? Vous savez, Pozzik était l'un des artisans les plus respectés d'Undermine avant de partir s'occuper des voitures de course. \n\nSa première réalisation a été le développement du modèle de course à deux moteurs. Bien sûr les affaires du Syndicat des Artisans doivent souffrir de son départ, mais c'est pas grave, pas vrai ? Il n'y a rien de plus important que la course.", rewards = "Vous recevrez :\n\n"},
[1179] = {title = "Les frères Brassbolts", objective = "Apporter la caisse de casques anti-accidents à Wizzle Brassbolts, dans les Salines.", description = "Vous avez déjà entendu parler des Salines ? C'est une étendue plate et salée au-delà de Kalimdor, juste au sud du canyon des Mille pointes. C'est un endroit fabuleux pour les courses ; forcément, c'est complètement plat ! \n\nUne paire de gnomes, des frères, des amis à moi, sont là-bas pour essayer leur nouvelle voiture à réaction. D'après ce qu'on m'a dit, elle dépote ! Elle dépote tellement que les pilotes se crashent tous l'un après l'autre. Et finissent avec le crâne en miettes. \n\nAlors, évidemment, ils m'ont demandé de fabriquer des casques, mais j'ai des contraintes ici ! Je ne peux pas faire le voyage ! \n\nVous pouvez ?", progress = "Attention où vous mettez les pieds ! Attention, attention, attention ! C'est un engin délicat que vous voyez là, et il doit être en parfait état de marche si nous voulons gagner !", completion = "Ah ! Longbeard vous envoie avec un lot de casques ! Hourra ! \n\nMaintenant nous allons peut-être arriver à convaincre un pilote de monter dans notre voiture !", rewards = "Vous recevrez :\n\n"},
[1180] = {title = "Mécénat gobelin", objective = "S'adresser à Maître Lozgil à Baie-du-Butin.", description = "Bon, revenons à la raison de votre voyage. Je sais que j'ai promis à Pozzik un nouveau régulateur de carburant, mais je ne l'ai pas encore reçu. Revilgaz, à Baie-du-Butin, dit qu'il l'a envoyé par bateau, mais il s'est peut-être perdu en route. \n\nSi c'est le cas, nous ne pouvons pas faire grand-chose. Mais nous pouvons tout de même vérifier qu'il est bien parti de Baie-du-Butin. \n\nVérifiez avec Maître Lozgil, sur les quais, là-bas, il devrait être en mesure de vérifier les registres de chargement.", progress = nil, completion = "Les chargements pour Ratchet ? Laissez-moi vérifier les registres… \n\nNon… Le dernier chargement que j'ai envoyé vers Ratchet, c'était des bottes pour Drizzlik. Pas grand-chose d'autre à part du matériel de construction et des outils. En tout cas, ce qui est sûr, c'est qu'il n'y avait aucune pièce pour voiture de course.", rewards = "Vous recevrez :\n\n"},
[1181] = {title = "Mécénat gobelin", objective = "Parler au baron Revilgaz à Baie-du-Butin.", description = "Désolé, je ne vais pas être d'un grand secours, <nom> ! Si vous voulez d’autres informations, je vous suggère d'aller trouver le baron lui-même. S'il y a quelqu'un qui est en mesure de vous renseigner sur les affaires de Revilgaz, c'est Revilgaz lui-même. \n\nVous le trouverez à l’étage de la Taverne, de l'autre côté du port.", progress = nil, completion = "Oui, bien sûr ! Je vois très bien de quoi vous parlez. Non, je ne peux pas vous aider. Certains de mes hommes devaient rechercher les plans du régulateur de carburant, mais ils sont revenus les mains vides.", rewards = "Vous recevrez :\n\n"},
[1182] = {title = "Mécénat gobelin", objective = "Apporter les Plans du régulateur de fuel au baron Revilgaz à Baie-du-Butin.", description = "Vous voyez, les déchiqueteurs de la KapitalRisk du lac Nazfériti (au nord de Strangleronce) sont équipés d'un nouveau régulateur de carburant. Je pensais que Pozzik serait en mesure de l'adapter s'il avait quelques détails précis à son sujet. Malheureusement, j'ai sous-estimé l'intelligence de Cozzle, le Surveillant du chantier. \n\nPeut-être aurez-vous plus de chance dans la recherche des plans. Je sais qu'il les garde chez lui, mais ils sont certainement sous clé.", progress = "Ça me peine de l'avouer, mais cette bande de gnomes se débrouille plutôt pas mal, là-haut… Nos gars ont besoin de tous les avantages possibles, aussi minimes soient-ils !", completion = "Bon ! Laissez-moi faire une copie de ces plans pour mon propre compte et vous pouvez apporter directement cet exemplaire à Pozzik. Je ne voudrais pas lui laisser croire que l'un de ses mécènes le laisse tomber.", rewards = "Vous recevrez :\n\n"},
[1183] = {title = "Mécénat gobelin", objective = "Apporter les Plans du Régulateur de carburant à Pozzik dans les Salines.", description = "Vous devriez être sur le départ. Transmettez mes salutations à Pozzik et dites-lui que s'il a besoin de quoi que ce soit, qu’il n'hésite pas à demander. J'attends les nouvelles de sa victoire avec impatience !", progress = "<nom> ! Avez-vous réussi à trouver le régulateur de carburant ?", completion = "J'avais espéré qu'il serait déjà monté, mais ces Plans offrent tout de même une occasion unique d'améliorer cette pièce. Merci, &lt;nom&gt;. Je vais pouvoir dessiner quelques schémas, fabriquer la pièce et la monter en deux temps trois mouvements !", rewards = "Vous recevrez :\n\n"},
[1184] = {title = "Des parties de l'Essaim", objective = "Retour à Orgrimmar pour voir Belgrom Rockmaul.", description = "Retournez voir Belgrom à Orgrimmar pour lui dire que Moktar fait tout ce qu'il peut aux Mille pointes. Dites-lui aussi que mes études progressent et que je pourrai lui donner des détails assez vite. Cela devrait le satisfaire pleinement.", progress = nil, completion = "J'apprécie vos efforts, &lt;classe&gt;. Le Chef de guerre verra d'un bon oeil la ténacité dont vous avez fait preuve pour cette mission. \n\nOh ! Bien sûr ! Je mentionnerai votre nom devant lui ! Il converse souvent avec moi et accorde beaucoup de prix à mes avis. \n\nAllez, maintenant, j'ai beaucoup à faire ! Et si vous obtenez des informations complémentaires sur ces créatures en reparlant avec Korran, n'hésitez pas à venir me voir ! Elles représentent une vraie menace, que nous devons prendre au sérieux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon des feuilles sèchesCroissant sanglant\n\nVous recevrez également :\n\n"},
[1185] = {title = "Sous la chitine...", objective = "Hé, vous revoilà ! Je veux dire, bonjour <nom> ! Oui, salut à vous et à personne d’autre !\n\nLaissez-moi vous expliquer !\n\nL’objet que vous avez trouvé à Silithus se trouvait être un livre. C’est un journal écrit dans un très ancien dialecte que nous appelons le darnassien. Cela prendra un bon moment, mais je suis sur le bon chemin pour finir le travail. Je pense que vous savez déjà que ce que vous avez découvert est extrêmement précieux pour le Cercle.\n\nLa Mère de la tanière est très heureuse de cette trouvaille !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[1186] = {title = "Le dix-huitième pilote", objective = "S'adresser à Razzeric, dans les Salines.", description = "Je vais être très occupé avec l'intégration de ce nouveau Régulateur de carburant sur la structure de nos voitures de course, mais si vous voulez apporter une aide supplémentaire à l'équipe, adressez-vous à Razzeric. C'est notre pilote. En fait, c'est notre dix-huitième pilote... Et il aime bien apporter ses petites modifications personnelles à sa voiture. \n\nJe vous préviens, il est un peu à côté de ses pompes alors tâchez de ne pas manifester de surprise quand vous lui parlerez !", progress = nil, completion = "C'est vous qui avez donné un coup de main à Pozzik, c'est ça, &lt;nom&gt; ? J'ai été comme vous, moi aussi, à courir autour des ateliers, à faire tous les petits boulots que les mécaniciens voulaient bien me confier ! \n\nEt maintenant regardez-moi ! Je suis l'extraordinaire pilote de l'équipe de course des gobelins !", rewards = "Vous recevrez :\n\n"},
[1187] = {title = "Les trucs de Razzeric", objective = "Récupérer le Lance-hydroglycérine pour Razzeric dans les Salines.", description = "Pozzik est un grand mécanicien, je le sais, mais il tergiverse trop lorsqu'il s'agit de puissance et de se lancer dans l'action. Ce n'est pas mon cas.\n\nLorsque Pozzik en a fini avec une machine, je prends quelques instants pour apporter mes petites modifications. Vous savez ce que c'est, je rends la direction un peu plus souple, j'enlève des morceaux de carrosserie inutiles, et j'y mets un peu plus de patate...\n\nJ'ai commandé un lance-hydroglycérine à Shreev au Bidulium de Gadgetzan, mais apparemment le zeppelin qui le transportait s'est écrasé dans le marécage d'Âprefange ! Il faut que je le récupère, <nom> !", progress = "Et comment est-ce que je suis censé faire mon trou dans les rangs des coureurs sans un peu de pêche pour faire avancer les choses ? C'est une gageure, je vous le dis !", completion = "Regardez cette merveille ! Quinze livres de puissance d'hydroglycérine ! Une fois que j'aurai fixé ça sur les flancs de ma voiture, je serai au bout de la piste si vite que j'aurai le temps de battre les gnomes deux fois !", rewards = "Vous recevrez :\n\n"},
[1188] = {title = "La sécurité d'abord", objective = "Apporter le Lance-hydroglycérine à Shreev à Gadgetzan.", description = "Mais qu'est-ce que c'est que ça ? Shreev a laissé la sûreté enclenchée. Ça limite l'énergie que je peux en tirer à chaque fois. Je lui avais dit de l'enlever ! Ça ne va pas ! \n\nVous devez rapporter ça au Bidulium de Gadgetzan dans le désert de Tanaris, et faire enlever ce truc par Shreev.", progress = "Comme vous le savez sans doute, le Bidulium peut satisfaire tous vos besoins ! Que puis-je faire pour vous ?", completion = "Il n'y a que Razzeric pour dire que j'ai mis je ne sais quelle sûreté sur cet engin simplement après y avoir jeté un coup d'oeil. Ce lance-hydroglycérine fonctionne à l'explosion de charges d'hydroglycérine. Il est déjà modifié pour donner toute sa puissance ou presque en une seule fois, mais Razzeric n'est jamais content, il lui faut toujours plus !", rewards = "Vous recevrez :\n\n"},
[1189] = {title = "La sécurité d'abord", objective = "Rapporter le Lance-hydroglycérine modifié à Razzeric, dans les Salines.", description = "Voilà ! J'ai fait selon les recommandations de Razzeric. Dites-lui simplement d'être prudent quand il installera ce truc. À la moindre erreur, il n'avancera pas : il explosera sur place.\n\nCe serait dommage, non ? Qui sait ce que vaudra notre dix-neuvième pilote !", progress = "Pouvez-vous croire que Pozzik a mis un sac de sable dans la voiture ? Comment pourrais-je atteindre ma vitesse maximale avec un sac de sable sous le siège ?", completion = "Maintenant c'est mieux ! Je voudrais voir la tête des gnomes quand ils verront ce que je vais faire de ce petit bijou.\n\nDommage, je serai trop occupé à battre un nouveau record !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de sécurité personnalisée de RazzericGants de course de Razzeric\n\nVous recevrez également :\n\n"},
[1190] = {title = "Rester dans la course", objective = "Utiliser Zamek pour faire diversion, dérober les plans de Rizzle et les apporter à Pozzik dans les Salines.", description = "Les frères Brassbolts ont utilisé un nouveau matériau de construction, c'est la seule explication plausible. Leurs voitures avancent plus rapidement qu'avant, mais leur aspect et toutes les données que nous avons recueillies sur leurs courses restent identiques.\n\nCe que nous savons, c'est que Rizzle Brassbolts est branché à temps plein sur les plans de sa nouvelle découverte. \n\nZamek peut créer une diversion pour vous, ainsi vous pourrez dérober ces plans.", progress = nil, completion = "Griffonné à la hâte, un carnet de notes et de dessins relatifs au raffinage de matières premières.", rewards = "Vous recevrez :\n\n"},
[1191] = {title = "La diversion de Zamek", objective = "Allons-y !", description = nil, progress = nil, completion = nil, rewards = nil},
[1192] = {title = "Minerai d'indurium", objective = "J'aimerais intégrer de l'Indurium dans les différents composants de mes voitures, mais il me faut une grande quantité de ce minerai pour les fabriquer.\n\nVous trouverez de l'Indurium à Khaz Modan, dans les mines d'Uldaman, dans les Terres ingrates, de l'autre côté de la mer.\n\nLes gnomes ont désormais leur propre source d'approvisionnement. Il est donc vital que nous ayons la nôtre pour rester au même niveau qu'eux.", description = nil, progress = "J'aimerais intégrer de l'Indurium dans les différents composants de mes voitures, mais il me faut une grande quantité de ce minerai pour les fabriquer.\n\nVous trouverez de l'Indurium à Khaz Modan, dans les mines d'Uldaman, dans les Terres ingrates, de l'autre côté de la mer.\n\nLes gnomes ont désormais leur propre source d'approvisionnement. Il est donc vital que nous ayons la nôtre pour rester au même niveau qu'eux.", completion = "Excellent ! Je vais former l'équipe pour travailler tout de suite sur les composants dont nous avons besoin pour la prochaine course.", rewards = "Vous recevrez :\n\n"},
[1193] = {title = "Un piège cassé", objective = "Un grand piège cassé se trouve devant vous. On dirait que les ogres ont tenté de le réparer sans succès. Une note hâtivement griffonnée se trouve juste à côté. Curieusement, elle détaille tout ce qui est nécessaire pour le réparer : il faut un rouage en thorium et un peu d’huile glaciale. Si le piège était réparé, un ogre qui passerait à côté pourrait s’y faire prendre, et pourrait être évité.\n\nC’est vraiment une bonne chose que très peu d’ogres sachent lire.\n\nVraiment.", description = nil, progress = "Un grand piège cassé se trouve devant vous. On dirait que les ogres ont tenté de le réparer sans succès. Une note hâtivement griffonnée se trouve juste à côté. Curieusement, elle détaille tout ce qui est nécessaire pour le réparer : il faut un rouage en thorium et un peu d’huile glaciale. Si le piège était réparé, un ogre qui passerait à côté pourrait s’y faire prendre, et pourrait être évité.\n\nC’est vraiment une bonne chose que très peu d’ogres sachent lire.\n\nVraiment.", completion = "Le rouage de thorium se met en place, ce qui crée un conduit par lequel vous versez l’huile glaciale. Les dernières gouttes sont à peines tombées que le piège se met en place.\n\nMalheur au premier ogre imprudent qui passera par là !", rewards = nil},
[1194] = {title = "Les schémas de Rizzle", objective = "Apporter un Echantillon de Minerai d'Indurium à Pozzik dans les Salines.\n\nObjet fourni : \n", description = "Les schémas de Rizzle montrent le processus de raffinage de l'Indurium. D'après ses gribouillages, il apparaît que le minerai provient de la mine des nains d'Uldaman dans les Terres ingrates.\n\nLa plupart des autres notes évoquent ses propriétés de résistance à la chaleur. \n\nCe qui sert de presse-papiers pour les plans est vraisemblablement un gros morceau d'Indurium non raffiné.", progress = nil, completion = "De l'Indurium ? Intéressant... S'il est capable de résister à une telle température, ceci expliquerait l'amélioration des performances que les gnomes ont enregistrée récemment. \n\nEn outre, l’échantillon que vous m'avez apporté va m'être très précieux. Je vais être en mesure d'effectuer des tests, mais il m'en faudra plus pour qu'il nous soit d'une réelle utilité.", rewards = "Vous recevrez :\n\n"},
[1195] = {title = "La flamme sacrée", objective = "Rapporter une Fiole d'Eau forte remplie à Zangen Stonehoof à Thunder Bluff.", description = "Les centaures du clan Galak, dans les Mille pointes, protègent un artefact du temps de la création de leur espèce.\n\nNous aimerions le voir de plus près, mais il nous faut d’abord une fiole d'eau provenant d’un des puits de lune des elfes de la nuit.\n\nPour puiser l'eau, vous aurez besoin d'une des fioles que transportent les dryades près de la retraite de Raynewood, au cœur de la forêt d'Ashenvale. Il existe un puits de lune près de la rive ouest de la rivière Falfarren, au sud de la route principale. Vous pourrez y remplir la fiole.", progress = "Une fois que nous aurons la fiole remplie, nous pourrons la faire parvenir à mon associé, Rau, dans les Mille pointes. C’est lui qui a réclamé la fiole d'eau, il saura donc comment l'utiliser.", completion = "Très bien ! Cela satisfera exactement les besoins de Rau. Pouvez-vous lui remettre cela ? Vous allez adorer votre petit séjour dans les Pointes.", rewards = "Vous recevrez :\n\n"},
[1196] = {title = "La flamme sacrée", objective = "Remettre la Fiole d'Eau forte remplie à Rau Cliffrunner au Poste de Librevent.", description = "Apportez la Fiole remplie à Rau Cliffrunner au Poste de Librevent dans le sud-est des Mille pointes. Vous pouvez atteindre les Mille pointes en empruntant la Grande élévation à la limite sud des Tarides. \n\nJe ne serais pas surpris que vous puissiez nous aider davantage.", progress = "Je suppose que vous n'avez pas été envoyé par Zangen, hein ?", completion = "Hum, oui ! Cette Fiole d'eau servira parfaitement nos desseins. En raison de l'ascendance commune des dryades et des centaures, l'eau des Puits de lune nous permettra de rompre la protection de la Flamme éternelle qui entoure la relique centaure.", rewards = "Vous recevrez :\n\n"},
[1197] = {title = "La flamme sacrée", objective = "Retrouver le Sabot fendu pour Rau Cliffrunner du Poste de Librevent.", description = "En l'aspergeant avec l’eau que vous avez apportée, vous pourrez temporairement éteindre la flamme qui protège la relique des centaures. L'effet sera provisoire, vous devrez faire vite.\n\nVous trouverez la combe du Sabot fendu, la ville fortifiée des centaures, plus au nord. La flamme est gardée dans le bastion du Sabot fendu, une zone très solidement gardée.\n\nFaites attention, les centaures du clan Galak sont très nombreux à cet endroit et ils combattront férocement pour protéger une chose aussi importante à leurs yeux.", progress = "Je suis impatient de toucher le Sabot fendu. L'avez-vous déjà pris ?", completion = "Je ressens une étrange énergie émanant du Sabot... Je suis certain à présent que nous allons faire d'étonnantes découvertes sur les centaures en l'étudiant. \n\nMes remerciements, &lt;nom&gt;. Maintenant je dois commencer à déchiffrer les mystères que vous m'avez soumis.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nVisée du rôdeurEcharpe azur\n\nVous recevrez également :\n\n"},
[1198] = {title = "À la recherche de Thaelrid", objective = "Aller chercher le Garde d'argent Thaelrid dans les Profondeurs de Brassenoire.", description = "De nombreuses rumeurs circulent ces jours-ci sur l'union entre le Marteau du crépuscule et les nagas dans les Profondeurs de Brassenoire sur les côtes d'Ashenvale.\n\nMon rôle ici avec l'Aube d'argent est de collecter autant d'informations que possible, afin que nous sachions où et quand on a besoin d'aide.\n\nCela fait des semaines à présent que j'ai envoyé un éclaireur espionner les activités menées dans les Profondeurs de Brassenoire. Le Garde d’argent Thaelrid n'est toujours pas revenu.\n\nMes autres éclaireurs sont très pris par d'autres tâches pressantes.\n\nRecherchez et venez en aide à Thaelrid pour moi, <nom>.", progress = nil, completion = "Le Veilleur de l'aube Shaedlass a manifesté sa bonté en vous envoyant. Effectivement, il se trame des complots dans cet endroit corrompu.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1199] = {title = "Le crépuscule descend", objective = "Apporter 10 Pendentifs du Crépuscule au Garde d'argent Manados à Darnassus.", description = "Les membres du Marteau du crépuscule, se servant des vieux rites des chaotiques Dieux très anciens, se battent pour les ramener en ce monde et pour y répandre la mort et la terreur.\n\nNous pensons que le Marteau du crépuscule s'est allié aux nagas et se regroupe en masse dans les Profondeurs de Brassenoire sur la côte d'Ashenvale.\n\nQuels que soient les plans maléfiques qu'ils préparent dans les profondeurs du temple ancien, ils doivent être contrecarrés.\n\nLancez un assaut sur le Marteau et rapportez la preuve de vos actes. Vos efforts se verront récompensés de grandiose manière.", progress = "Les Profondeurs de Brassenoire étaient autrefois un temple des elfes de la nuit. Il abritait le plus puissant des puits de lune. Qui sait ce que le Marteau du crépuscule prépare là-bas... \n\nAvez-vous réussi à nous débarrasser de leur présence ?", completion = "Vous êtes sans aucun doute possible un brave et noble cœur, &lt;nom&gt;. L'Aube d'argent vous remercie de vos efforts contre le Mal.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes de la nimbeCeinturon de coeur du bois"},
[1200] = {title = "L'infamie de Brassenoire", objective = "Apporter la Tête du Seigneur du crépuscule Kelris au Veilleur de l'aube Selgorm, à Darnassus.", description = "Mes forces me quittent. J'ai besoin de votre aide ! \n\nIl y a longtemps, ce site était un grand temple d'Elune. Mais la malchance l'a conduit à sa ruine, quand un Dieu très ancien, en contaminant la terre, a corrompu le Puits de lune sacré. \n\nAku'Mai, serviteur du Dieu très ancien, est sorti des eaux.\n\nLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Les sectateurs, conduits par Kelris, sacrifient des innocents à Aku'Mai pour augmenter son pouvoir. \n\nTuez Kelris et apportez sa tête à Selgorm, à Darnassus, je vous en prie, <nom>.", progress = "Le temps est précieux, <classe>. \n\nMon rôle à Darnassus est de m’assurer que l'Aube d'argent ne faiblit pas et que les forces du Mal infiltrées à Kalimdor sont mises en échec. \n\nFaites rapidement ce que vous avez à faire ou bien passez votre chemin.", completion = "Cela fait longtemps que Kelris nous échappe. \n\nOn dirait qu'il a son rôle dans chaque manifestation du Mal par ici. Pendant un temps, nous l'avons cru mort ou disparu. \n\nPourtant, tout cela est cohérent. En mettant fin à son influence, vous avez épargné la vie de nombreux innocents. \n\nPar la Lumière ! Comment peut-on en arriver, par intérêt, à sacrifier une vie à un serviteur d'un Dieu très ancien ? \n\nVous avez fait une belle action, &lt;nom&gt;. Je vous salue au nom de l'Aube d'argent.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSceptre du tombeauTarge arctique\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1201] = {title = "Les espions de Theramore", objective = "Tuer 9 Infiltrateurs de Theramore, puis rendre compte à Nazeer Bloodpike à Mur-de-Fougères.", description = "La trêve entre la Horde et l'Alliance n'est pas toujours respectée. Des escarmouches et des actions secrètes sont menées par chacun des deux camps, et il est de notre devoir de nous assurer que la Horde garde l’avantage ! \n\nNous avons maintenant l'occasion de démasquer les infiltrateurs de l'Alliance. \n\nIls sont en position à l'est du village de Mur-de-Fougères. Ils nous espionnent et rapportent nos mouvements à Theramore, ce que nous ne pouvons permettre. \n\nTraquez-les et tuez-les. Envoyons un message clair à leurs chefs : nous ne supporterons pas leur présence sur notre sol !", progress = nil, completion = "Bon travail ! Leurs infiltrateurs sont habiles, mais pas assez pour échapper aux yeux attentifs de la Horde !", rewards = "Vous recevrez :\n\n"},
[1202] = {title = "Les docks de Theramore", objective = "Apporter les Documents du capitaine à Nazeer Bloodpike au village de Mur-de-Fougères.", description = "<nom>, deux de nos espions ont été envoyés pour dérober des documents sur un bateau dans les docks de Theramore. Ils ont trouvé les papiers, mais ont été découverts et ils ont dû jeter les documents à la mer. \n\nL'un des deux a réussi à s'échapper par la suite, mais il n’a pas pu récupérer le paquet. Il a rendu compte de son échec et maintenant je vous confie cette mission. \n\nLes documents sont dans un coffret, quelque part dans les eaux des docks de Theramore. Trouvez ces documents, <nom>, et apportez-les-moi.", progress = "Avez-vous trouvé les documents, <nom> ? Ils contiennent des informations vitales pour la stabilité de l'Alliance et, par là même, pour la sécurité de la Horde.", completion = "Je vous félicite, &lt;nom&gt;. Ce n'était pas une tâche facile. Mais les documents que vous avez trouvés seront très appréciés de vos supérieurs.", rewards = "Vous recevrez :\n\n"},
[1203] = {title = "Jarl a besoin d'une épée", objective = "Apporter une Epée en acier lunaire à Jarl, dans le marécage d'Âprefange.", description = "Je dois découper. Je ne peux pas vous dire quel type de découpage je vais faire, mais j'ai besoin d'une lame… Mais pas n'importe quelle lame !\n\nIl y en a qui l'appellent Epée d'acier lunaire. Moi je l'appelle Epée à double tranchant.\n\nAllez-vous m'aider ? Peut-être que vous la trouverez en ville, peut-être que vous pourrez la faire faire chez un forgeron.\n\nMais ne traînez pas. Ce que je dois découper n'attendra pas des années.", progress = "Vous avez mon épée ?", completion = "C'est une bonne épée. Elle balance bien. Merci ! Merci, merci, merci ! Maintenant il faut que je l'essaie… \n\nPlus tard, je l'essaierai plus tard.", rewards = "Vous recevrez :\n\nAnneau ReedknotPantalon de l'ouvrier"},
[1204] = {title = "Soupe de Rochefange aux insectes", objective = "Apporter 8 Langues fourchues de Rochefange à Morgan Stern, à Theramore.", description = "Je prépare un plat que je nomme \"Soupe et insectes rochefange\". Il me manque encore les ingrédients principaux… Eh bien, je pense que je ne ferais pas long feu à patauger tout seul dans le marécage d'Âprefange !\n\nAussi, <nom>, cela vous dérangerait-il de faire une petite partie de chasse pour moi ? D'abord, il me faut des langues de tortues Rochefange. Vous pouvez en trouver le long de la côte, près de la baie.\n\nMais il ne me faut pas n'importe quelles langues ! J'entends par là que certaines tortues ont la langue fourchue...\n\nIl paraît que ces langues fourchues ont un goût particulier, et je veux cet ingrédient-là dans ma recette...", progress = "Avez-vous trouvé les langues fourchues ?", completion = "C'est parfait ! Merci, &lt;nom&gt; ! \n\nMaintenant je vais essayer différentes techniques de cuisson, afin de trouver la meilleure façon de faire ressortir la saveur de ces langues. \n\nEn fin de compte je vais avoir un plat digne d'être servi au « Solitaire bleu » de Stormwind !", rewards = "Vous recevrez :\n\n"},
[1205] = {title = "Mortebourbe", objective = "Apporter la Dent de Mortebourbe à Melor à Thunder Bluff.", description = "Mortebourbe est un ancien crocilisque du marécage d'Âprefange. Son heure est arrivée. \n\nSes vieux os grincent quand il extrait son énorme corps du marais, et pourtant il évolue avec la force et la vitesse de ses jeunes années. Son corps fatigué torture le grand esprit qui l'habite, un esprit dont la flamme ne faiblit pas. \n\nPourtant, il vit maintenant marqué par une douleur cruelle et permanente. Vous devez mettre un terme à la vie de cette noble créature, <nom>. Vous devez conduire Mortebourbe à la paix.", progress = "Vous avez la dent de Mortebourbe, <nom> ? Vous avez mis un terme aux souffrances de la pauvre créature ?", completion = "Très bien, &lt;nom&gt;. \n\nJe suis sûr que cette chasse n'a pas été facile, mais je suis heureux de savoir que les souffrances de cette bête ont enfin cessé.", rewards = "Vous recevrez :\n\n"},
[1206] = {title = "Jarl a besoin d’yeux", objective = "Apporter 40 Yeux de Sombrebrume à Jarl \"Œil-des-marais\", au Manoir des Flammeroles.", description = "Le jus d’œil est bon à boire. Malheureusement la plupart des monstres n'ont que deux yeux. \n\nMais les araignées, elles, ont beaucoup d'yeux. Plus que beaucoup. Et le jus d'oeil de Sombrebrume est fameux. Doux et salé ! Des yeux d'araignée entiers... J'ai l'impression de les savourer. \n\nLes araignées Sombrebrume se trouvent à l'ouest d'ici, dans la caverne de Sombrebrume. A votre avis, c'est cette grotte qui a donné son nom aux araignées, ou l'inverse ?", progress = "Et ces yeux ?", completion = "Vous avez les yeux ! Vous avez les yeux ! Des yeux d'araignée savoureux, savoureux !\n\nCes yeux ! Quand vous les regardez, ils vous rendent votre regard. Encore un petit dernier. Ils vous tiennent compagnie… dans le marais.\n\nSalut, les petits yeux d'araignée ! Salut ! Vous avez le goût du poulet. Un poulet doux et salé.\n\nMmmmm....", rewards = "Vous recevrez :\n\n"},
[1218] = {title = "Epices apaisantes", objective = "Apporter 3 Epices apaisantes à Jarl \"Œil-des-marais\", dans le marécage d'Âprefange.", description = "J'aime la cuisine. La bonne cuisine du marais. Les cuisses de grenouille verte grillées par exemple. \n\nEt pour cuisiner j'ai besoin d'épices. Des épices apaisantes. Après je ferai un ragoût qui mijotera et qui mijotera et je le mangerai. Mais je vous en donnerai un peu aussi. \n\nVous aimez le ragoût ?", progress = "Des épices. Nous avons tous besoin d'épicer notre vie, pas vrai ?", completion = "Ah ! Ça c'est de l'épice ! Maintenant un bon ragoût du marais !", rewards = "Vous recevrez :\n\nBrouet de cuisses de grenouille"},
[1219] = {title = "Le rapport orc", objective = "Communiquer le Rapport de l'Espion à un Lieutenant de Theramore.", description = "En remuant la poussière, on trouve la main coupée d'un orc. Une main qui agrippe encore un tube en os gravé. Le tube contient un parchemin taché.\n\nLe parchemin est écrit en orc... Et ça semble important.", progress = "Avez-vous un message ?", completion = "Hum... Je ne lis pas très bien l'orc, mais cela ressemble à un rapport... Ecrit par un espion orc !", rewards = "Vous recevrez :\n\n"},
[1220] = {title = "Le capitaine Vimaire", objective = "Apporter le Rapport orc au capitaine Garran Vimaire.", description = "Le capitaine Vimaire désire voir le rapport orc que vous avez trouvé, <nom>. C’est lui qui connaît le mieux la langue des orcs. Et il doit savoir qu'il y a des espions de la Horde près de Theramore !\n\nLe capitaine est dans la Caserne, au nord-est de Theramore.", progress = "Vous avez quelque chose pour moi ?", completion = "Un rapport d'un espion orc ! Comment avez-vous trouvé ça ? Peu importe, voyons le contenu…", rewards = "Vous recevrez :\n\n"},
[1221] = {title = "Racines de Feuillebleue", objective = "Prendre une Caisse percée.\nPrendre un Bâton de commandement de Sniffetarin.\nLire le Manuel d'utilisateur de Sniffetarin.\n\nAu Kraal de Tranchebauge, utiliser la Caisse pour invoquer un Ecureuil Sniffetarin et utiliser le Bâton de commandement pour ordonner à l'Ecureuil de chercher les racines.\n\nRamener 6 Racines de Feuillebleue, le Bâton de commandement de Sniffetarin et la Caisse percée à Mebok Mizzyrix, à Ratchet.", description = "Les racines de feuillebleue sont une friandise universellement appréciée ! Mais elles sont rares, très rares. On ne peut les trouver qu'ici, dans les Tarides, profondément enterrées au kraal de Tranchebauge.\n\nEt même ici, vous ne pourriez pas les trouver à moins de savoir comment les chercher ! C'est pourquoi j'ai entraîné ces Ecureuils Sniffetarin à les trouver. Ils ont un grand nez et peuvent sentir une racine à cinquante pas.\n\nCela ne sera pas facile, mais si vous me ramenez quelques racines, je vous paierai grassement.", progress = "Avez-vous les racines, <nom> ?", completion = "Excellent, vous les avez ! Je peux les vendre un bon prix à mes clients !\n\nMerci pour la livraison, &lt;nom&gt; ! Vous êtes quelqu'un de précieux.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nUn petit coffre de gemmes"},
[1222] = {title = "Sauvetage du Puant", objective = "Escorter Ignatz \"Puant\" puis discuter avec Morgan Stern à Theramore.", description = "Génial, enfin quelque chose qui ne veut pas me dévorer !\n\nJ'ai besoin d'aide pour occuper ces monstres autour de moi et vous m'avez l'air de pouvoir le faire.\n\nLe chef cuisinier Morgan Stern travaille sur une nouvelle recette et il m'a envoyé ici pour cueillir des feuilles de haricots des marais. Je pense qu'il les trouve savoureux.\n\nQuoi qu'il en soit, pendant que je cherchais un plant de haricot, je me suis retrouvé cerné ! Pouvez-vous m'aider à sortir de là et surveiller les alentours pendant que je cherche des plants de haricots ?", progress = nil, completion = "M. Ignatz était ici il y a un instant avec les feuilles de haricots des marais, et il m'a raconté comment vous l'avez sorti d'une situation périlleuse.\n\nMerci beaucoup, &lt;nom&gt;. Je vais demander à mon oncle de vous préparer une fête de remerciement lorsque vous repasserez au « Solitaire bleu » à Stormwind.", rewards = "Vous recevrez :\n\nElixir de Robustesse"},
[1238] = {title = "Le rapport perdu", objective = "Apporter le Rapport de l'espion à Nazeer Bloodpike à Mur-de-Fougères.", description = "Au milieu de la poussière, une main d'orc, seule. Et dans cette main, un tube creusé dans de l'os. Dans le tube, un parchemin sale.\n\nCe parchemin est un rapport établi par un orc qui a passé des semaines à espionner la ville de Theramore.\n\nAprès examen du rapport, il est clair qu'il doit être apporté au Maître Espion, au village de Mur-de-Fougères.", progress = "Vous avez quelque chose pour moi ?", completion = "Beau travail, &lt;nom&gt;. Notre agent, Marg Nighteye, était stationné à l'extérieur de Theramore. Il était chargé d'espionner la ville.\n\nVoici son dernier rapport, il n’en fera sans doute jamais plus. D'après votre témoignage, je crains que Marg n'ait fini dans les marais...", rewards = "Vous recevrez :\n\n"},
[1239] = {title = "La tête coupée", objective = "Apporter la Tête d'orc défiant à Nazeer Bloodpike à Mur-de-Fougères.", description = "Une fouille approfondie permet de découvrir une tête d'orc mâle. Les lèvres sont figées dans un rictus et les yeux noirs semblent vous fixer avec défi.", progress = "Vous avez quelque chose d'autre à signaler, <nom> ?", completion = "C'est la tête de Marg Nighteye ! Comme je le craignais, il est mort.\n\nRegardez la blessure du cou ! Une arme a-t-elle pu faire de telles marques ou bien a-t-il été tué par une bête ?\n\nC'est un mystère que nous devons résoudre, &lt;nom&gt;. Nous devons savoir si la mort de Marg est du fait de l'Alliance !", rewards = "Vous recevrez :\n\n"},
[1240] = {title = "Le Sorcier-docteur troll", objective = "Apporter la Tête d'orc défiant à Kin'weelay au Campement Grom'gol dans la vallée de Strangleronce.", description = "Nous devons connaître les faits concernant la mort de Marg ! Et il n'y a qu'une seule manière de savoir, <nom>. C'est d'utiliser la sorcellerie des trolls.\n\nApportez la tête de Marg à Kin'weelay dans la vallée de Strangleronce au Campement Grom'gol.\n\nKin'weelay est le plus puissant des Sorciers-docteurs des trolls Darkspear. Si quelqu'un peut parler à l'esprit de Marg Nighteye, c'est lui.", progress = "Il y a un esprit en colère contre vous. Qu'est-ce qui vous amène chez Kin'weelay ?", completion = "Ah je vois ! L'esprit de cet orc est retenu dans notre monde, bouillant de rage de n'avoir pas accompli sa dernière tâche.\n\nEh bien discutons un peu avec cet orc irascible…", rewards = "Vous recevrez :\n\n"},
[1241] = {title = "Un diplomate a disparu", objective = "Trouver Jorgen dans la cité de Stormwind.", description = "Récemment, un diplomate a été envoyé à Theramore pour rencontrer Jaina Proudmoore. Ce diplomate n'est jamais arrivé.\n\nJe pense que les Défias sont impliqués dans ce complot, mais je ne vois pas de quelle manière. La disparition du diplomate n'a pas encore attiré l'attention du public, mais cette situation ne durera pas.\n\nDes agents du roi sont déjà en train de fouiller la ville à la recherche d'indices, mais j'aimerais consulter mes propres contacts.\n\nDans la Vallée des héros vit un vieil ami à moi qui s'appelle Jorgen. Trouvez-le, donnez-lui cette note et suivez ses instructions.", progress = "Hmmph ! Vous avez intérêt à avoir de bonnes raisons d'interrompre la pêche d'un vieil homme. Je n'apprécie pas particulièrement les marchands ambulants et encore moins les mendiants.", completion = "Mhhh ! &lt;Jorgen vous dévisage, l'air suspicieux.&gt;\n\nTrès bien, je vais aider, pas parce que je le veux, mais parce que j'y suis obligé.\n\nEt mettons d'abord quelque chose au point : vous en savez bien plus que vous ne devriez. Alors que cela reste entre nous et n'allez pas bavasser ailleurs sur ce que vous auriez trouvé. Compris ?", rewards = "Vous recevrez :\n\n"},
[1242] = {title = "Un diplomate a disparu", objective = "Apporter la Note scellée de Jorgen à Elling Trias dans la cité de Stormwind.", description = "Portez cette note à Elling Trias. Ne lui dites rien d'autre. Contentez-vous d'être <poli/polie> et attendez la réponse. Et ne vous inquiétez pas, il répondra.\n\nQue ce soit bien clair, <nom> : c'est une affaire sérieuse, alors gardez votre clapet fermé.\n\nVous trouverez Trias dans son magasin de fromages, « Aux Fromages de Trias », dans le Quartier commerçant. Bonne chance !", progress = "Bonjour, <nom>. Que puis-je faire pour vous ? Peut-être aimeriez-vous goûter un peu de notre cheddar spécial de Trias ? Ou un morceau de bleu de Darnassus ?", completion = "Je vous demande pardon, une lettre pour moi ? Ça par exemple... Ce n'est pas souvent qu'on vous livre autre chose qu'une caisse ou un baril quand vous ne faites rien d'autre que travailler. Voyons de quoi cela parle.\n\n&lt;Elling vous regarde en ouvrant la lettre.&gt;\n\nVous me semblez un peu tendu, vous allez bien, &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[1243] = {title = "Un diplomate a disparu", objective = "Donner la Note scellée au Gardien Backus, au bois de la Pénombre.", description = "Jorgen, vieux fils de… Alors c'est comme ça que ça va se passer, hein ?\n\nTrès bien, je peux m'en accommoder. J'espère qu'il trouvera le Néant distordu au plus tôt !\n\nVoilà comment nous allons procéder, <nom>. Je commence à utiliser mes contacts ici, mais comme c'est vous qui faites le plus gros du travail de terrain, je vous prête un peu d'argent.\n\nAllez à Darkshire, dans le bois de la Pénombre, et trouvez le gardien Backus. Il patrouille généralement sur la route nord juste en dehors de la ville. Dites-lui simplement que vous êtes là pour surveiller, pour moi, l'activité des Défias, et il vous aidera en vous donnant toutes les informations qu'il possède.", progress = "Pas prudent de se balader dans les bois, <nom>. Soyez sur vos gardes, et si vous voyez quoi que ce soit de louche ou de dangereux, contactez les Gardiens immédiatement. Ne tentez rien et ne faites rien vous-même. Nous ne sommes pas responsables de tout ce qui pourrait vous arriver.\n\nMais nous savons tous les deux que vous n'allez pas m'écouter et pourfendre tout ce qui sortira des ténèbres, n'est-ce pas ? Ha ! Ha ! Ouais, vous les aventuriers... tous les mêmes.", completion = "Oh ! Trias vous envoie, hein ? C'est un peu différent alors.\n\nVous êtes libre de combattre n'importe quelle monstruosité qui s'en prendrait à vous dans les ténèbres. Je suis sûr que vous n'aurez aucun mal si vous êtes le type de personne dont il aime à s'entourer.\n\nAlors de quoi mon ami a-t-il besoin par un jour aussi sombre que celui-ci ?", rewards = "Vous recevrez :\n\n"},
[1244] = {title = "Un diplomate a disparu", objective = "Trouver le Registre des Défias et le ramener au Gardien Backus au bois de la Pénombre.", description = "Les activités des Défias ? Il y a toujours de l'activité, même s'ils ne se vantent pas que nous les considérions comme une menace.\n\nMais pendant que j'y pense, il y a eu récemment quelque chose de bizarre. Cela s'est passé il y a environ deux semaines : certains de leurs agents se sont réunis près de la ferme des Addle. D'après le rapport, j'en ai déduit que quelque chose d'important était en préparation.\n\nPourquoi ne commenceriez-vous pas par vérifier cela et me rapporter tout ce que vous trouverez ?\n\nLa ferme est au sud de la route qui vient de la marche de l'Ouest, juste à l'endroit où vous rentrez dans le bois de la Pénombre.", progress = "Soyez sur vos gardes, <nom>. Je sais que c'est Trias qui vous envoie là-bas, mais cela ne veut pas dire qu'il n'y a que des choses inoffensives qui courent dans les bois… Tout particulièrement si vous enquêtez sur les Défias.", completion = "Vous êtes de retour et en bonne santé. Peut pas demander mieux, pas vrai ?\n\nMaintenant voyons un peu ce que nous avons là. Ce document semble aussi authentique que tous les autres documents Défias que j'ai vus jusqu'ici. Mais cela pourrait être un faux pour vous mettre sur une fausse piste dans l'affaire qui nous occupe.", rewards = "Vous recevrez :\n\n"},
[1245] = {title = "Un diplomate a disparu", objective = "Ramener le Registre des Défias à Elling Trias à Stormwind.", description = "Ouais ! Cela semble bien trop compliqué pour quelque chose qui serait juste destiné à vous induire en erreur. Je ne devrais même pas être en train de regarder tout ça. Portez-le à Trias. Il sera capable de comprendre tout cela. Et ne laissez PERSONNE se mettre en travers de votre chemin. Ceci est trop gros pour moi. C'est peut-être même trop gros pour lui, mais il verra.\n\nEt faites-moi une faveur, <nom>, ne dites à personne que je vous ai fourni de l'aide. Si mes supérieurs apprennent que je savais quelque chose sur cette affaire et que je ne les ai pas prévenus, ils me pendront.", progress = "Je vois que vous êtes de retour et en un seul morceau. Nous savons tous les deux que vous n'êtes pas ici pour mes fromages, alors allons droit au but. Est-ce que Backus a pu vous aider ou bien êtes-vous déjà en chemin pour le bois de la Pénombre ?", completion = "Ouais… C'est une lecture intéressante. Jorgen et DeLavey ont été bien avisés de me mettre au courant.\n\nIl semble que les Défias font tout pour que leurs plans aboutissent. Hmm, qu'est-ce que cela ? \"Fist\" ? Ce nom m’est familier.", rewards = "Vous recevrez :\n\n"},
[1246] = {title = "Un diplomate a disparu", objective = "Parler à Dashel Stonefist à Stormwind.", description = "Ouais, maintenant que j'y pense… Dashel… Dashel… quelque chose… Son nom c'était quoi déjà ? FIST ! Dashel Stonefist. Ils l'appelaient Fist dans certains milieux, probablement parce qu'il aimait se battre.\n\nVous le trouverez habituellement dans la vieille ville, pile au centre. Allez donc lui parler. Et n'hésitez pas à utiliser une épée ou quelque chose de bien lourd et contondant pour l’engager à discuter. N'y allez pas de main morte, s'il est aussi impliqué que ces papiers le laissent à penser, il n'est pas prêt à parler de son plein gré.", progress = nil, completion = "Quoi ?\n\nVous venez comme ça chez moi et me posez des questions sur des sujets strictement personnels ? Sujets qui ne vous concernent aucunement.", rewards = "Vous recevrez :\n\n"},
[1247] = {title = "Un diplomate a disparu", objective = "Parler à Elling Trias à Stormwind.", description = "Alors ouais… Hum !… Il se pourrait que je sache quelque chose à propos de cette rencontre à la ferme des Addle. Ça s'est passé il y a quelques semaines je crois. Je n'y ai pas participé. J'avais terminé ma part du travail lorsque le plan A a échoué… Maudits aventuriers !\n\nLa taupe que nous avions pour le plan B venait de Menethil, un type appelé Slim. C'est tout ce que je sais sur leur plan de rechange.", progress = nil, completion = "Content de vous voir toujours en vie, &lt;nom&gt;. Alors, ça s'est bien passé avec Dashel ?\n\nJ'étais en train de lire leurs plans : bien qu'ils ne nomment pas le diplomate qui était leur cible, ils parlent d'un plan B qu'ils ont monté après avoir raté leur première tentative d'enlèvement.\n\nCe Slim que Dashel a mentionné est le seul nom qui est écrit ici et si vous me dites qu'il est à Menethil, eh bien c'est toujours un début…", rewards = "Vous recevrez :\n\n"},
[1248] = {title = "Un diplomate a disparu", objective = "Parler à Mikhail dans les Paluns.", description = "Un de mes contacts a pris sa retraite dans les Paluns, dans le port de la cité de Menethil pour être précis. Il sera d'accord pour vous aider si vous lui dites que vous travaillez pour moi. Son nom est Mikhail. Avant de quitter Stormwind, il y a quelques années, il disait qu'il voulait s’occuper d’un bar.\n\nParlez-lui, trouvez ce Slim et trouvez tout ce qui est possible sur ce diplomate disparu. Nous avons besoin de savoir où ils l'ont emmené ou au moins qui il est. Le registre ne dit rien concernant leurs projets après sa capture.", progress = nil, completion = "Bienvenue, bienvenue, bienvenue, &lt;nom&gt; ! C'est gentil de votre part de vous joindre à nous. Peut-être une bière ? Ou du mouton ?\n\nDites-nous ce dont vous avez envie et je ferai en sorte que votre souhait se réalise.\n\nHmm ? Qu'est-ce que cela ? Trias ? Baissez la voix, je vous en prie. Il s'agit d'un sujet qui ne concerne pas le reste de la taverne.", rewards = "Vous recevrez :\n\n"},
[1249] = {title = "Un diplomate a disparu", objective = "Soumettre Tapoke Jahn avant qu'il ne s'échappe et ensuite retourner voir Mikhail à Menethil.", description = "Vous dites que c'est Elling qui vous envoie ? Eh bien l'hospitalité que je vous dois est encore plus grande. Quels que soient vos besoins, demandez. Je ferai de mon mieux pour vous aider.\n\nHmm, Slim vous dites ? Ça ne me dit rien, mais je garderai un oeil ouvert au cas où.\n\nNe vous retournez pas maintenant, <nom>, mais le gentilhomme là-bas près de la sortie regarde par ici. Il écoute notre conversation un peu trop attentivement, si vous voyez ce que je veux dire. Si j'étais vous, je l'intercepterais avant qu'il ne puisse atteindre la porte et disparaître.", progress = "Il s'est enfui ? La manière dont il nous regardait était vraiment louche.", completion = "Vous l'avez eu ? Bon pour vous ! J'ai été surpris que cela soit Slim.\n\nPour être honnête, je ne pensais pas que le frisson associé aux activités souterraines les plus tortueuses me manquerait un jour. Je crois que les vieilles habitudes ont la vie dure. Mais ne dites pas cela à Elling, il essayerait – et réussirait – à me faire revenir à Stormwind s’il savait que l'action me manque.\n\nJe suis content d'avoir pu vous être utile pendant que vous étiez à Menethil. Si vous avez besoin de quelque chose d'autre, demandez.", rewards = "Vous recevrez :\n\n"},
[1250] = {title = "Un diplomate a disparu", objective = "Parler à Mikhail dans les Paluns.", description = "Les Défias ne me payent pas suffisamment pour que je meure pour leur cause. Ils ont pris le roi. Ouais, le roi de Stormwind, pas un petit diplomate de rien du tout. Il était en route pour rencontrer Jaina Proudmoore. C'était un gros coup apparemment et un grand secret. Mais il n'y avait pas que les Défias qui y participaient. Ils travaillaient pour quelqu'un. Je pense qu'ils savaient que c'était quelque chose de trop gros pour eux.\n\nMon travail consistait à introduire l'un de leurs hommes sur le bateau du roi lorsqu'il était à quai. Le nom de ce type est Hendel. C'est tout ce que je sais. Je le jure !", progress = nil, completion = "LE ROI ?!! Vous voulez dire… le roi ? Le vrai roi ? Vous plaisantez ? Vous n'aviez pas dit que vous cherchiez les ravisseurs du roi. Je ne savais même pas qu'il avait disparu -- ce qui expliquerait que son fils soit couronné.\n\nJe vais informer Elling immédiatement. Il voudra être au courant que vous êtes sur la piste.\n\nJe n'aurais jamais imaginé que Jahn puisse vendre Stormwind contre de la menue monnaie. Même un escroc se doit d'avoir de l'honneur pour certaines choses.\n\nIl faut maintenant trouver ce Hendel. Et je crois pouvoir vous aider.", rewards = "Vous recevrez :\n\n"},
[1251] = {title = "Le bouclier noir", objective = "Rapporter le Bouclier en fer noirci à Krog, à Mur-de-Fougères.", description = "Un bouclier en fer, noirci par le feu qui a fait rage, est fixé à la cheminée branlante, une des rares structures encore debout de ce qui a été l'auberge du Repos ombragé.\n\nLe bouclier peut être détaché du mur en brique de la cheminée.", progress = "Qu'avez-vous là, <nom> ? Des indices trouvés à l'auberge du Repos ombragé ?", completion = "Je sais que les humains ont des goûts décoratifs étranges, mais placeraient-ils vraiment un bouclier en fer simple sur leur cheminée ? Ce bouclier a peut-être été placé là par ceux qui ont brûlé l'auberge.\n\nSerait-ce un avertissement ? Une menace ?", rewards = "Vous recevrez :\n\n"},
[1252] = {title = "Lieutenant Paval Reethe", objective = "Rapporter le badge de Reethe au capitaine Garran Vimaire à Theramore.", description = "Un éclat de lumière attire votre attention sur les gravats. Ecartant les débris et la poussière, vous trouvez un insigne émaillé représentant une ancre dorée sur fond blanc : le symbole de Theramore.\n\nSous l'ancre est gravé : \"Lieutenant Paval Reethe\".", progress = "Avez-vous trouvé quelque chose d'intéressant à l'auberge du Repos ombragé ?", completion = "Cela n'est jamais bon lorsque le badge d'un Garde m'est rapporté.\n\nParfois c'est un homme ou une femme tombé au combat et il ne me reste plus qu'à annoncer la nouvelle à une famille éplorée. Il y a aussi les cas où nous ne savons pas ce qui est arrivé. Et enfin, il arrive que cela soit encore pire.", rewards = "Vous recevrez :\n\n"},
[1253] = {title = "Le Bouclier noir", objective = "Rapporter le Bouclier en fer noirci au capitaine Garran Vimaire à Theramore.", description = "Un bouclier en fer, noirci par le feu qui a fait rage, est fixé à la cheminée branlante, une des rares structures encore debout de ce qui a été l'auberge du Repos ombragé.\n\nLe bouclier peut être détaché du mur en brique de la cheminée.", progress = "Avez-vous trouvé des indices sur le site de l'auberge du Repos ombragé ?", completion = "Je ne suis pas un expert en fabrication d’armes et d’armures. En leur utilisation oui, mais pas plus.\n\nCe bouclier semble ordinaire, à l'exception des dégâts subis lors de l'incendie qui a ravagé l'auberge.", rewards = "Vous recevrez :\n\n"},
[1258] = {title = "... Et des bestioles", objective = "Apporter 12 Pattes de Clampant en parfait état à Morgan Stern à Theramore.", description = "Un autre ingrédient de ma nouvelle recette est la patte de crabe géant. Et les crabes qu'ils ont à Âprefange, ceux qu'on appelle les Bourbecoques, ne conviennent pas ! J'ai bien peur que les seuls crabes valables ne vivent loin, dans le marais des Chagrins.\n\nLa carapace des pattes de crabe est un des éléments clés de la présentation de ce plat. Cela veut dire que j'ai besoin de pattes parfaites, sans trace ni éraflure. Un crabe adulte n'a généralement qu’une ou deux pattes de cette qualité et il m'en faut beaucoup pour mettre au point ce plat.\n\nAlors, <nom>... est-ce qu'un voyage vous tente ?", progress = "Mes recherches sur les langues de Rochefange progressent. J'espère que votre chasse aux crabes se passe bien ?", completion = "Ce sont des spécimens magnifiques, &lt;nom&gt; ! Les carapaces sont parfaites et les chairs sont tendres et roses. Le sang des plus grands chefs cuisiniers coule dans vos veines, j'en suis sûr !", rewards = "Vous recevrez :\n\nTablier baroque"},
[1259] = {title = "Le lieutenant Paval Reethe", objective = "Trouver plus de renseignements sur Paval Reethe auprès de l'adjudant Tesoran à Theramore.", description = "Le nom du lieutenant Paval Reethe ne me dit rien. Votre meilleure chance est de vérifier auprès de l'adjudant Tesoran. Il conserve tous les dossiers de la garde de Theramore, du personnel jusqu'à l'équipement.\n\nIl devrait être capable de vous dire qui est ce Reethe après un rapide coup d'oeil dans ses registres.", progress = nil, completion = "Bonjour, &lt;nom&gt;. Vous avez besoin de renseignements sur un membre de la garde de Theramore ? Reethe, n'est-ce pas ?\n\nAccordez-moi un moment que je trouve les bonnes archives.", rewards = "Vous recevrez :\n\n"},
[1260] = {title = "Morgan Stern", objective = "Parler à Morgan Stern à Theramore.", description = "Je suis en train de créer une nouvelle carte pour le restaurant. Elle sera composée de plats typiques sur un thème \"bayou\". Je pense que ma clientèle au Solitaire Bleu va l'adorer !\n\nJ'ai envoyé mon neveu Morgan à Theramore, une ville au bord du marécage d'Âprefange. Il collecte des recettes locales et j'ai besoin de savoir ce qu'il a déjà trouvé.\n\nLe voyage pour Theramore est long. Trop long pour moi. Mais je parie que quelqu'un d'aussi jeune que vous, <classe>, sauterait sur une occasion de voyager, non ?", progress = nil, completion = "Oh ! C'est mon oncle qui vous a envoyé, n'est-ce pas ?\n\nEh bien, je suis en train d'élaborer de nouvelles recettes et j'ai quelques pistes, mais j'ai besoin d'aide.\n\nDe l'aide de quelqu'un qui accepterait de se mouiller les pieds.", rewards = "Vous recevrez :\n\n"},
[1261] = {title = "Marg parle", objective = "Apporter le Pendentif orné à Nazeer à Mur-de-Fougères.", description = "Maudit Bourbecoque ! Tu ne peux pas tuer Marg ! Ah, mais je suis mort. Alors il doit m'avoir tué...\n\nMais ma mission ! Ma mission ! Vous, <nom>, devez achever ma mission.\n\nAlors que j'étais près de Theramore, j'ai espionné un groupe de soldats de l'Alliance qui campaient sur la plage. Un de ces soldats portait un pendentif... Un pendentif avec plus de pierres précieuses que dans les rêves d'un soldat !\n\nCette nuit-là, je me suis glissé dans leur camp et j'ai volé le pendentif, mais au retour à la base, un homme-crabe Bourbecoque m'a tué !\n\n<nom>, vous devez le retrouver et récupérer le pendentif !", progress = "<nom>, avez-vous découvert ce qui est arrivé à Marg ?", completion = "Ce pendentif était porté par un soldat de Stormwind ?\n\nMerci, &lt;nom&gt;. Vous avez découvert le secret de la mort de Marg. Mais ce pendentif est un nouveau mystère à résoudre, un mystère qui peut avoir des conséquences désastreuses pour l'Alliance et la Horde.", rewards = "Vous recevrez :\n\n"},
[1262] = {title = "Rapport à Zor", objective = "Apporter le Pendentif orné à Zor Lonetree à Orgrimmar.", description = "Il est étrange que le pendentif que Marg a volé était en possession de simples soldats. Peut-être que son propriétaire était déguisé, ou que les soldats l’avaient eux-mêmes volé !\n\nQuoi qu'il en soit, il s'agit d'un pendentif de noble et nous devons découvrir son véritable propriétaire si nous voulons percer ce mystère.\n\nApportez-le à Zor Lonetree à Orgrimmar. Il en connaît beaucoup sur les personnages politiques de l'Alliance et saura dire si ce pendentif est connu parmi les nobles de Stormwind.", progress = "Vous venez de Mur-de-Fougères en Âprefange ? Comment se porte Nazeer ? Ces efforts dans les marais portent-ils leurs fruits ?", completion = "Ce pendentif a été monté avec une grande précision, ce qui demande une compétence certaine, &lt;nom&gt;. Aucun orc ne convoiterait un tel bijou…\n\nMais beaucoup d'humains le feraient.\n\nJe vais étudier ce pendentif. Avec un peu de temps, j'espère pouvoir dévoiler ses mystères.", rewards = "Vous recevrez :\n\n"},
[1263] = {title = "L'auberge en feu <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1264] = {title = "Un diplomate a disparu", objective = "Trouver le commandant Samaul, dans le marécage d'Âprefange.", description = "Au début de chaque mois, les soldats de marine de Kul Tiras reçoivent leur paye et quittent généralement Theramore pour un autre endroit. Un grand nombre d'entre eux viennent ici pour les femmes, faire la bringue et passer un bon moment. L'un de ces groupes vient régulièrement à cette taverne et je crois que ce Hendel en fait partie.\n\nLe commandant Samaul à Theramore devrait vous aider à le trouver si Hendel est toujours par ici. Il est loyal à Proudmoore, mais si vous citez négligemment le nom de Elling, il devrait vous aider... discrètement.", progress = nil, completion = "Un plaisir de vous rencontrer, &lt;nom&gt;. Je suis le commandant Samaul. Je suis en charge de l'armée de dame Proudmoore à Theramore.\n\nBien que je sois très occupé, si vous avez des questions, n'hésitez pas à les poser. J'ai peu de temps, mais il n'y a pas de raison que je sois impoli si vous avez besoin de mon aide.\n\nSi vous prévoyez de voyager en dehors de la ville, je vous recommande la prudence. En plus des ogres, des orcs et des murlocs, la partie sud du marais héberge des dragons noirs.", rewards = "Vous recevrez :\n\n"},
[1265] = {title = "Un diplomate a disparu", objective = "Chercher le soldat Hendel à la halte de la Vigie.", description = "Hendel ? Oui, je le connais. Mais pourquoi avez-vous besoin d'un de mes soldats ?\n\nElling vous a demandé de le trouver ? Je n'aime pas cela. Elling ne vous aurait pas <envoyé/envoyée> directement à moi si cela n'était pas pour des problèmes. Je comprends que vous ne puissiez pas me dire de quoi il s'agit, mais sachez ceci : j'ai pour mission de protéger ce pays. Si vous pensez créer des problèmes, alors je vous suggère de m'en informer.\n\nJe crois que Hendel est cantonné à la première tour en dehors de Theramore.", progress = nil, completion = "L'homme que vous cherchez, celui que l'on appelle Hendel, n'est pas ici. D'autres sources ont apporté à dame Proudmoore des informations que vous connaissez déjà semble-t-il. Elle m'a demandé de vous trouver et de vous apporter de l'aide dans votre aventure. Si vous le permettez, je vais vous dire où l'on peut le trouver afin que nous puissions le traduire devant la justice.", rewards = "Vous recevrez :\n\n"},
[1266] = {title = "Un diplomate a disparu", objective = "Trouver le soldat Hendel dans le marécage d'Âprefange.", description = "Le soldat Hendel se trouve à l'ouest d'ici. Il est en ce moment de garde et protège des infiltrateurs de Theramore tandis qu'ils se reposent. Ils ont tenu à l'œil la base de la Horde, Mur-de-Fougères, et tout ce qui pourrait menacer nos frontières.\n\nVous ne devriez rencontrer aucune difficulté pour le trouver. Cherchez simplement des tentes le long de la route.\n\nUne autre affaire nécessite mon attention, mais je vous rejoindrai bientôt. Vous pourrez toujours me rencontrer dans la tour de dame Proudmoore si vous avez le moindre problème.", progress = nil, completion = "Bonjour. C'est un endroit dangereux pour se promener. Si l'on tient à la vie, il est déconseillé de s'attarder.\n\nSi vous me dites ce que vous voulez, je verrai si je peux faire quelque chose pour vous. Gardez un œil ouvert au cas où il y aurait l'un de ces satanés ogres. La rumeur dit qu'il y a une base de la Horde quelque part dans le marais. Les infiltrateurs font ce qu'ils peuvent pour la trouver, mais cela prend du temps et nous avons peu progressé.", rewards = "Vous recevrez :\n\n"},
[1267] = {title = "Un diplomate a disparu", objective = "Parler à Jaina Proudmoore au marécage d'Âprefange.", description = nil, progress = nil, completion = "Tout d'abord, permettez-moi de vous remercier pour tout ce que vous avez fait, &lt;nom&gt;. Vous êtes un don du ciel pour mon peuple et celui de Stormwind. J’aurais préféré faire votre connaissance dans d’autres circonstances.\n\nComprenez également que je ne peux reconnaître officiellement vos mérites, mais sachez que ceux-ci sont grandement appréciés.\n\nLorsque vous reviendrez à Theramore, venez me voir et je vous informerai de la situation.\n\nMerci encore, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nChevalière de Jaina"},
[1268] = {title = "Des empreintes de sabots suspectes", objective = "Faire votre rapport sur les empreintes suspectes de l'auberge du repos ombragé à Krog, au village de Mur-de-Fougères.", description = "Des lignes d'empreintes de sabots partent des ruines encore fumantes de l'auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d'autres empreintes peu marquées dans la boue du marais.", progress = nil, completion = "Des empreintes de sabots… Cela pourrait être des hurans. Ou peut-être des centaures. Leur présence dans les Tarides n'est pas anodine et je pense qu'ils sont capables de ce genre d’action.\n\nVous ai-je dit que cette affaire ne se résume pas seulement à une auberge brûlée ? La femme du propriétaire et son bébé ont été tués. Sale histoire !\n\nBon, je vais envoyer Kagoro pour voir où mènent ces traces.", rewards = "Vous recevrez :\n\n"},
[1269] = {title = "Lieutenant Paval Reethe", objective = "Rapporter le Badge de Reethe à Krog à Mur-de-Fougères.", description = "Un éclat de lumière attire votre attention sur les gravats. Ecartant les débris et la poussière, vous trouvez un insigne émaillé représentant une ancre dorée sur fond blanc : le symbole de Theramore.\n\nSous l'ancre est gravé : \"Lieutenant Paval Reethe\".", progress = "Avez-vous une hypothèse sur ce qui s'est passé à l'auberge du Repos ombragé ?", completion = "Je connais cet humain, Paval Reethe. Pathétique même pour eux ! Il a déserté et il se cache maintenant dans les bois.\n\nJ'ai envoyé Ogron pour le traquer. Certains le suspectent de voler notre ravitaillement. Je crois que j'ai vu Ogron aller vers le sud-est.", rewards = "Vous recevrez :\n\n"},
[1270] = {title = "Sauvetage du Puant", objective = "Escorter Ignatz \"Puant\" puis discuter avec Mebok Mizzyrix à Ratchet.", description = "Enfin quelque chose qui ne semble pas vouloir me manger !\n\nJ'ai besoin d'aide pour repousser ces monstres et vous me semblez convenir.\n\nUn Goblin de Ratchet, du nom de Mebok Mizzyrix, a besoin de feuilles de haricots des marais pour une potion ou je ne sais quoi... J'avoue que je me fiche complètement de la raison, son argent est bienvenu et je connais ce marais, donc me voilà.\n\nDommage que je me sois fait encercler avant d'avoir trouvé les haricots ! Pourriez-vous m'aider à sortir de là et surveiller mes arrières tandis que je cherche les plantes pour Mebok ?", progress = nil, completion = "Le Puant était là avec les herbes que je lui avais commandées et il m'a dit que vous l'aviez bien aidé. Beau travail ! Un ami du Puant est mon ami ! \n\nJuste avant de repartir vers le sud pour le marais, il m'a demandé de vous remettre cela.", rewards = "Vous recevrez :\n\nElixir de Robustesse"},
[1271] = {title = "Fête au Solitaire Bleu", objective = "Mon neveu m'a dit que vous l'aviez aidé dans ses recherches à Âprefange et que vous aviez sorti son associé d’une situation difficile. Bien, nous les Stern, nous nous serrons les coudes et nous nous souvenons de nos amis !\n\nAlors lavez-vous les mains, <nom>, parce que nous allons faire la fête en votre honneur !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChiffon à poussière"},
[1272] = {title = "Trouver Reethe <CHANGE INTO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1273] = {title = "Questionner Reethe", objective = "Aller avec Ogron pour parler à Reethe puis retourner voir Krog à Mur-de-Fougères.", description = "Cela a pris du temps, mais j'ai trouvé Reethe. Il se cache bien pour un humain.\n\nOgron se demande s’il n'est pas devenu fou après tout ce temps passé dans le marais. Vous venez avec moi pour lui tirer les vers du nez.", progress = nil, completion = "Ah ! Il est bon de savoir que Reethe ne traînera plus dans le marais, mais il est regrettable que les humains soient trop faibles pour survivre à la blessure d'une petite flèche de rien du tout.\n\nIl semble que cette piste ne nous mène nulle part. Nous devons trouver autre chose.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPique-oeilHaquebute explosive\n\nVous recevrez également :\n\n"},
[1274] = {title = "Un diplomate a disparu", objective = "Trouver l'évêque DeLavey au Donjon de Stormwind.", description = "Excusez-moi, <monsieur/madame>, l'évêque DeLavey m'a demandé de prendre contact avec des <aventuriers/aventurières> qui pourraient être capables de l'aider avec un problème délicat.\n\nSi vous pouviez vous rendre discrètement au Donjon de Stormwind pour lui parler dès que cela vous est possible, il est certain qu'il apprécierait grandement votre secours. A nouveau, soyez <discret/discrète>. Il s'agit d'une affaire d'une certaine importance.", progress = nil, completion = "Bonjour, &lt;nom&gt;. Je suis l'évêque DeLavey.\n\nIl est clair que si vous vous demandez ce que je fais dans le donjon, alors le jeune Thomas a réquisitionné la bonne personne pour aider notre royaume. Il réussit toujours à satisfaire mes requêtes.\n\nJe crains de ne pas avoir beaucoup de temps, aussi pardonnez ma brutalité... Et s'il vous plaît, évitez que notre conversation passe dans le domaine public.", rewards = "Vous recevrez :\n\n"},
[1275] = {title = "Recherches sur la corruption", objective = "Gershala Nightwhisper d'Auberdine veut 8 Souches de cerveau corrompu.", description = "Ces imbéciles d'elfes de sang peinent avec la magie démoniaque. N'ont-ils pas vu ce qui est arrivé aux nagas et aux satyres de Kalimdor ?\n\nJe crains que les elfes de sang ne rencontrent pareille déformation. Azeroth ne supporterait pas la naissance d'une autre race de monstres infects.\n\nJe souhaite étudier les Souches de cerveaux des satyres et des nagas afin d'en déduire la voie que prennent les elfes. Vous trouverez des satyres et des nagas dans les Profondeurs de Brassenoire, sur la côte d'Ashenvale.\n\nC'est un long voyage, <nom>.", progress = "Une fois que j'aurai suffisamment d'échantillons, mon travail véritable pourra commencer. En étudiant les cerveaux corrompus des satyres et des nagas des Profondeurs de Brassenoire, je pourrais trouver une corrélation entre les mutations.\n\nPeut-être qu'avec ces connaissances, je pourrai empêcher les elfes de sang de s'enfoncer plus profondément dans les difformités et les maléfices.", completion = "Vous avez voyagé loin et affronté de terribles dangers.\n\nVos actions étaient désintéressées. C'est pour le bien d'Azeroth que vous m'avez aidé dans mes recherches. Je vous remercie, &lt;nom&gt;, de tout ce que vous avez fait.\n\nMaintenant excusez-moi, j'ai beaucoup de travail à accomplir...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPinces de hannetonCape de prélat\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1276] = {title = "Le Bouclier noir", objective = "Montrer le Bouclier en fer noirci à Mosarn à Thunder Bluff.", description = "Je me souviens ! Mosarn est un forgeron respecté de Thunder Bluff. Je savais que j'avais entendu son nom quelque part !\n\nEn remerciement, le Cercle terrestre m'a offert un équipement complet forgé par Mosarn. Du très beau travail !\n\nPeut-être pourrait-il vous en dire plus sur ce bouclier qu'il a forgé.\n\nCe n'est pas une grosse piste, mais c’est la seule et c’est Reethe qui l’a donnée.", progress = "Bienvenue, <classe>. Y a-t-il quelque chose que je puisse faire pour vous ?", completion = "Oui, vous avez raison. C'est un bouclier que j'ai forgé.\n\nMais je crains de ne pouvoir vous en dire plus, &lt;nom&gt;. J'ai fabriqué tant de boucliers et tant d'armures, je ne peux pas me souvenir de tout.", rewards = "Vous recevrez :\n\n"},
[1281] = {title = "La chanson de Jim <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1282] = {title = "Ils l'appellent Jim le Souriant", objective = "Discuter avec le capitaine Garran Vimaire à Theramore.", description = "Je ne peux pas aider tant que je m'apitoierai sur le vieux Jim là-bas. Il n'a pas toujours été comme cela. Il a tenu une auberge en dehors des marais pendant un moment, un endroit superbe.\n\nÉcoutez, je ne veux pas vraiment en parler. Allez voir le capitaine Vimaire si vous avez besoin de quelque chose.", progress = nil, completion = "James Hyal est son vrai nom. Il avait une auberge près des Tarides. Il voulait en faire un endroit accueillant pour les voyageurs qui passeraient…\n\nPeut-être a-t-il vu trop grand, mais l'auberge a bien marché au début. Puis nous avons perdu le contrôle des routes dans les marais et les ogres sont arrivés.\n\nJames était trop têtu pour abandonner son rêve et rejoindre la sécurité de nos murs, et l'auberge du Repos ombragé a été incendiée. Nous enquêtons, mais nous n'avons toujours rien trouvé. Si vous voulez aider, allez voir si vous trouvez quelque chose dans les ruines.", rewards = "Vous recevrez :\n\n"},
[1283] = {title = "L'incendie de l’auberge du Repos ombragé <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1284] = {title = "Des empreintes de sabots suspectes", objective = "Rapporter la présence des empreintes suspectes à l’auberge du Repos ombragé au capitaine Vimaire à Theramore.", description = "Des lignes d'empreintes de sabots partent des ruines encore fumantes de l'auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d'autres empreintes peu marquées dans la boue du marais.", progress = nil, completion = "Des empreintes de sabots, hein ? Ce qui est sûr, c'est que les centaures sont très actifs près du marécage d'Âprefange. Lors d'une brève incursion dans les Tarides, nous avons trouvé leur camp et leurs fermes.\n\nJe vais envoyer Falgran Hastil, un de nos meilleurs pisteurs, pour voir où mènent ces traces.", rewards = "Vous recevrez :\n\n"},
[1285] = {title = "Les hommes de Daelin", objective = "Ramener l'information concernant Reethe au capitaine Vimaire à Theramore.", description = "Reddon… Redpath… Ah voilà ! Lieutenant Paval Reethe.\n\nA rejoint la garde de Theramore en même temps que la plupart des recrues ayant fait la traversée avec dame Proudmoore. Engagé dans les soldats de marine de Kul Tiras à seize ans. Etats de service brillants, promu... \n\nPorté disparu.", progress = nil, completion = "Porté disparu ? Cela serait la manière pour Tesoran de dire traître.\n\nIl est évident qu'il est l’un de ces idiots si aveuglement loyaux à l'amiral Daelin qu'il a trahi. N'est-ce pas délicieusement ironique ? Les déserteurs nous accusent de trahir l'Alliance.", rewards = "Vous recevrez :\n\n"},
[1286] = {title = "Les déserteurs", objective = "Rapporter l'information de Balos Jacken sur Reethe et les déserteurs dans le marécage d'Âprefange.", description = "Nous avons lutté pour maintenir notre présence dans les marais, et grâce à notre détermination, nous avons pu conserver plusieurs tours de garde défensives dans le secteur.\n\nLes dernières informations et rapports d'éclaireurs que j'ai reçus indiquent qu'un groupe de déserteurs squatte une tour abandonnée à la Halte perdue, au sud-est de l'auberge.\n\nLeur chef se nomme Jacken. Voyez si vous pouvez lui soutirer des informations.\n\nSoyez sur vos gardes, <nom>. Il risque d'être réticent à collaborer.", progress = nil, completion = "C'est Vimaire qui vous envoie ? Il ne peut pas faire le sale boulot lui-même, hein ?", rewards = "Vous recevrez :\n\n"},
[1287] = {title = "Les déserteurs", objective = "Discuter avec le capitaine Garran Vimaire à Theramore à propos de Reethe.", description = "Reethe ? Ce lâche ?\n\nNous l'avons éjecté du camp, car il insistait pour aller piller le ravitaillement des ogres de Mur-de-Fougères. Nous ne sommes pas suffisamment nombreux pour faire face à ces brutes sans cervelle.\n\nIl a franchi trop de fois les limites, alors nous l'avons envoyé paître.\n\nBon je vous ai aidé... Alors aidez-moi à votre tour en oubliant que vous nous avez trouvés !", progress = nil, completion = "Je vais envoyer le lieutenant Caldwell s'occuper des déserteurs de la Halte perdue. De plus, je vais lui donner ordre de trouver Reethe. Les marais ne sont pas si grands et il devrait être capable de le retrouver.", rewards = "Vous recevrez :\n\n"},
[1288] = {title = "Le rapport de Vimaire", objective = "Donner le Rapport de Vimaire à Dame Proudmoore à Theramore.", description = "Vous avez fait du bon travail, <nom>, le meilleur que j'ai vu de la part de quelqu'un qui n'est pas de chez nous.\n\nDame Proudmoore a demandé que je la tienne informée de cette situation délicate et je ne lui ai pas parlé depuis longtemps.\n\nJe m'apprêtais à lui envoyer mon rapport, mais il me semble plus approprié que cela soit vous qui lui parliez. Vous répondrez mieux à ses questions que moi.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[1301] = {title = "James Hyal", objective = "Discuter avec Vincent Hyal au Port de Menethil.", description = "Avant de travailler ici, au Solitaire bleu, j'ai été formé par le meilleur chef cuisinier et gérant d'auberge que je connaisse. Son nom était James Hyal. Tout ce que j'ai et tout ce que j'ai appris, je le lui dois.\n\nJe me demande ce qu'il devient. Son frère Vincent et lui sont allés travailler dans une auberge du Port de Menethil, mais je suis sans nouvelles depuis longtemps.\n\nSi vous passez dans le coin, donnez-lui le bonjour de ma part, d'accord ?", progress = nil, completion = "James ? Eh bien, il est parti il y a quelque temps.\n\nIl a entendu le deuxième appel des trompes du patriotisme, je suppose. Pas dur de deviner pourquoi. Avec toutes ces saletés à Lordaeron, nombreux sont ceux qui ont rejoint Jaina Proudmoore lorsqu'elle est partie.", rewards = "Vous recevrez :\n\n"},
[1302] = {title = "James Hyal", objective = "Parler au greffier Lendry à Theramore.", description = "Mon frère James a accompagné Dame Proudmoore lorsqu'elle a traversé les océans. Les dernières nouvelles disaient que le calme était revenu là-bas et que James avait monté une auberge quelque part sur le continent. Où qu'il soit, je suis sûr qu'il fait de bonnes affaires. C'est un excellent chef cuisinier !\n\nJe suis sans nouvelles de lui depuis un bon moment. Trop de travail avec son auberge, je suppose. Mais le greffier à Theramore a peut-être plus de renseignements.", progress = nil, completion = "James Hyal, James Hyal… Pourquoi ce nom me paraît-il familier ?\n\nBien sûr ! L'incident à l'auberge du Repos ombragé. Si vous avez la moindre information à ce sujet, je vous demande instamment d'aller en parler immédiatement au capitaine Vimaire. Il est en charge de l'enquête.", rewards = "Vous recevrez :\n\n"},
[1318] = {title = "Affaires inachevées chez les Gordok", objective = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.\n\nSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.", description = "Maintenant qu’z’êtes le roi, p’têt' qu’vous pourrez récupérez l’objet précieux des Gordok que le sale elfe qui se dit Prince nous a pris. L’roi avant vous a pas réussi, et celui d’avant non plus, et aucun roi depuis que Tortheldrin – c’est le sale elfe – l’a volé à un vieux roi gordok d’il y a longtemps !\n\nC’est le Gantelet de puissance Gordok. Les vieux, ils disent que seul le vrai roi des Gordok pourra le ramener. Et puis, les vieux, ils disent aussi que le sale elfe est toujours là – si vous le trouvez, vous pourrez porter le gantelet de puissance pour toujours ! Ouais ! Je vais vous montrer !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGarde-mains gordoksGantelets gordoksGants gordoksProtège-mains gordoks\n\nVous recevrez également :\n\n"},
[1319] = {title = "Le Bouclier noir", objective = "Montrer le Bouclier en fer noirci à Caz Twosprocket à Theramore.", description = "Je suis désolé de ne pouvoir vous en dire plus, <nom>, mais je sais qui peut vous aider. Caz Twosprocket, un de nos meilleurs forgerons. Portez-lui le bouclier et voyez ce qu'il peut vous dire.", progress = "Quelque chose que je dois examiner ?", completion = "Hmm… Pièce intéressante que vous avez là. Il est clair qu'elle n'a pas été faite par les forgerons que je connais de ce côté de l'océan et ce n'est certainement pas mon travail.", rewards = "Vous recevrez :\n\n"},
[1320] = {title = "Le Bouclier noir", objective = "Discuter avec le capitaine Garran Vimaire à Theramore.", description = "Ah ! J'ai failli manquer ceci… Cette lanière de cuir au dos aurait dû brûler, et elle a été faite pour un grand gabarit. Je dirais même un tauren.\n\nC'est tout ce que je peux dire. Dites au capitaine Vimaire que je suis désolé de n'avoir pas pu l’aider plus.", progress = nil, completion = "Ce n'est pas une grosse information, mais gardons-la à l'esprit. Heureusement, certaines pièces du puzzle commencent à se mettre en place et permettent d'avoir une meilleure compréhension de ce qui s'est passé.", rewards = "Vous recevrez :\n\n"},
[1321] = {title = "Le Bouclier noir", objective = "Montrer le Bouclier en fer noirci à Do'gol au village de Mur-de-Fougères.", description = "Hmmm… Je ne vois rien qui sorte de l'ordinaire à propos de ce bouclier. Demandons à Do'gol, le forgeron, de l'examiner, puis écoutons ce qu'il peut nous dire, mais n'espérons pas trop…", progress = "Quelque chose pour moi, <classe> ?", completion = "C'est un très bon bouclier. Très robuste, lourd, bon. Mais Do'gol n'a pas besoin de bouclier. Je fais des boucliers, je ne les achète pas, &lt;nom&gt;.\n\nVous devriez le savoir.", rewards = "Vous recevrez :\n\n"},
[1322] = {title = "Le Bouclier noir", objective = "Trouver 6 Sacs de Venin acide pour Do'gol de Mur-de-Fougères.", description = "Hmmm ! Il y a quelque chose d'écrit sur le bord du bouclier, c'est dur à lire avec toutes ces traces de suie.\n\nJ'ai besoin d'acide pour le faire apparaître. Du venin d'araignée Sombrecroc des marais serait parfait. Rapportez-moi quelques glandes et je vous nettoie cela.", progress = "Avez-vous pu ramener les sacs de venin ?", completion = "Je n'aime pas les araignées qui sont tellement grosses qu’on ne peut pas s'asseoir dessus pour les écraser.\n\nMerci de les avoir rapportés, &lt;nom&gt;. Maintenant j’ouvre ces sacs de venin et j’en répands le contenu sur le bouclier…", rewards = "Vous recevrez :\n\n"},
[1323] = {title = "Le Bouclier noir", objective = "Parler à Krog au village de Mur-de-Fougères.", description = "Oh ! Je crois que j'ai mis trop d'acide sur le bouclier. Frottons un peu pour voir…\n\nHmm, difficile à lire, mais il me semble qu'il s'agit d'un nom : Mosarn. Jamais entendu parler de lui. Peut-être Krog le sait. Krog connaît tellement de monde.", progress = nil, completion = "Mosarn ? Cela sonne familier… Je n'arrive pas à me souvenir. Cela me reviendra.\n\nCela ne doit pas être important. Un bouclier peut venir de n'importe où et ne rien vouloir dire…", rewards = "Vous recevrez :\n\n"},
[1324] = {title = "Un diplomate a disparu", objective = "Battre le soldat Hendel dans le marécage d'Âprefange.", description = "Quoi ? Vous venez m'accuser d'être allié aux Défias et vous pensez que je vais rester là tranquillement alors que vous êtes en train de m'insulter ? Quelque chose me dit que vous pensez à cela depuis longtemps.", progress = nil, completion = "Je vous assure que nous sommes tous perturbés par les événement en cours, mais permettez-nous de le ramener à Theramore pour l'interroger, et nous nous occuperons de retrouver le roi.\n\nJe suis certain que dame Proudmoore voudrait vous remercier pour votre aide. Parlez-lui quand vous aurez un moment.", rewards = "Vous recevrez :\n\n"},
[1338] = {title = "La mission de Stormpike", objective = "Porter la commande de Stormpike à Furen Longbeard à Stormwind.", description = "Il y a un forgeron nain dont j'admire beaucoup le travail. Il s'appelle Furen Longbeard et ses compétences sont inégalables. J'ai besoin d'un nouveau bouclier et je veux l'un des siens !\n\nLe problème… Furen est loin dans le sud, dans le quartier des nains de Stormwind. Chez les humains ! Je ne comprends pas pourquoi il vit là-bas, si loin d'Ironforge. Les humains doivent lui faire un pont d’or pour qu'il accepte de rester !\n\nSi vous avez envie de voyager, et ne pensez pas à demander une récompense, alors pourquoi ne porteriez-vous pas ma commande de bouclier à Furen ?", progress = "Une lettre en provenance du pays ? Je me demande qui peut bien m'écrire de si loin dans le nord…\n\nExcusez-moi, je dois lire ce courrier.", completion = "Ah ! Une requête d'un des Stormpike. C'est un fier clan, plein des qualités appréciées par les nains. Riches aussi.\n\nMerci, &lt;nom&gt;. Je dois me mettre au travail sur le bouclier du Montagnard Stormpike avant la fin du jour.", rewards = "Vous recevrez :\n\n"},
[1339] = {title = "La mission du Montagnard Stormpike", objective = "Parler au Montagnard Stormpike.", description = "J'ai entendu dire que le montagnard Stormpike a besoin d'un coursier. Quelqu'un pour voyager à sa place. Qu'en pensez-vous, <nom> ? Êtes-vous capable de ce travail ?\n\nSi c'est le cas, vous trouverez Stormpike au sommet de la tour de garde la plus au nord.", progress = nil, completion = "C'est exact. J'ai une mission que je ne peux accomplir, car je suis de garde. En fait, cela vous conduira loin du Loch Modan.\n\nVotre meilleure chance pour une aventure !", rewards = "Vous recevrez :\n\n"},
[1358] = {title = "Un échantillon pour Helbrim", objective = "Apporter l'échantillon de coeur de loup à l'Apothicaire Helbrim dans les Tarides.", description = "Un collègue de Kalimdor, l'apothicaire Helbrim, étudie les effets des toxines de Lordaeron sur les animaux de Kalimdor. Il serait très intéressé par un échantillon de coeurs de loups que Renferrel m'a envoyés.\n\nHelbrim se trouve dans les Tarides, dans un village connu sous le nom de la Croisée. Pour le rejoindre, vous voyagerez par zeppelin jusqu'à Orgrimmar, la capitale des orcs, puis à pied vers le sud en Durotar. Allez à l'ouest, dans les Tarides, et vous trouverez rapidement la Croisée.", progress = "Avez-vous un paquet pour moi ?", completion = "Ah, très bien. Si les rapports initiaux sont corrects, la toxicité de ces coeurs pourrait faire avancer notre connaissance des poisons.\n\nC'est une livraison qui tombe bien, &lt;nom&gt;. Vous avez mérité une récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de brasseurLongue cape drapée\n\nVous recevrez également :\n\n"},
[1359] = {title = "Une livraison pour Zinge", objective = "Apporter les Echantillons de coeurs de loups à l'apothicaire Zinge à Undercity.", description = "Les Coeurs de loups que vous avez là possèdent une qualité inouïe pour ces spécimens. Ils possèdent une toxicité telle qu'elle tuerait net les loups vivants !\n\nC'est fascinant, il faut approfondir l'étude. J'ai gardé quelques échantillons de ces coeurs. Apportez-les à ma collègue, l'Apothicaire Zinge. Vous la trouverez dans notre quartier général à Undercity.", progress = "Vous avez quelque chose pour moi ?", completion = "Ah oui, les échantillons de coeurs dont Renferrel m'a parlé. J'ai hâte de les étudier…La Société royale des apothicaires est toujours intéressée par de nouvelles formes de toxines.", rewards = "Vous recevrez :\n\n"},
[1360] = {title = "Des Trésors à recouvrer", objective = "Récupérer les biens de Krom Stoutarm dans son coffre dans le hall commun nord d'Uldaman et les lui rapporter à Ironforge.", description = "J'avais un bon travail de terrassier à l'excavation d'Uldaman dans les Terres ingrates… jusqu'à ce que ces sacrés troggs arrivent. J'ai à peine réussi à sauver ma peau, rien d'autre. Dans la panique, j'ai laissé mon plus précieux bien. C'est dans mon coffre donc à l'abris des troggs, mais au beau milieu d'eux.\n\nVous auriez toute ma gratitude, en honneur et en or, si vous pouviez me le ramener. Il y a un coffre portant mon nom au bout du hall commun nord. C'est là qu'il faut aller.", progress = "Alors, vous avez réussi à éviter ces troggs assez longtemps pour atteindre mon coffre et récupérer mon trésor ?", completion = "Ah, je suis de nouveau moi-même : merci mille fois.\n\nCertains nains adorent l'éclat du métal, d'autres celui des pierres précieuses… mais un Stoutarm n'est rien sans sa chope chérie !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1361] = {title = "Regthar Deathgate", objective = "Discuter avec Regthar Deathgate.", description = "Un guerrier de la Horde, Regthar Deathgate, recrute des agents pour une mission dans les terres de Désolace. Allez lui parler si vous souhaitez vous porter volontaire. Il se trouve dans les Tarides, dans une série de fortins situés à l'ouest de la Croisée.\n\nEt aiguisez vos armes. Désolace est ravagée par la guerre.", progress = nil, completion = "Oui, je recrute ! Cette mission nous conduira dans Désolace, contre les centaures. Je serai bref afin que vous puissiez commencer le plus tôt possible.", rewards = "Vous recevrez :\n\n"},
[1362] = {title = "Les Kolkar de Désolace", objective = "Discuter avec Felgur Twocuts au poste de Rôdeur-fantôme en Désolace.", description = "Les centaures Kolkar vivent en Désolace et leurs forces sont disséminées dans toutes les Tarides. Il est de notoriété publique que des agents de la Horde s'occupent d'eux.\n\nMais tant que les centaures seront puissants en Désolace, ils resteront une menace. Il est temps de nous en débarrasser.\n\nParlez à Felgur Twocuts au Poste de Rôdeur-fantôme en Désolace. Il y a été envoyé pour réunir des informations sur les centaures. Il saura comment faire au mieux avec les Kolkar de Désolace.", progress = nil, completion = "Vous venez sur l'ordre de Regthar ? Alors vous êtes ici pour vous occuper des centaures. Bien.\n\nJ'espère que vous êtes bien reposé. Je ne sais pas comment notre campagne contre les centaures va se terminer, mais je sais que la lutte va être longue.\n\nPrenez un siège et écoutez-moi.", rewards = "Vous recevrez :\n\n"},
[1363] = {title = "Les ordres de Mazen", objective = "Parler à l'acolyte Dellis à Stormwind.", description = "En tant que conservateur de la bibliothèque de l'Académie des arts et sciences des arcanes, il est de ma responsabilité de m'assurer que tous les livres magiques et les parchemins sont bien présents. Qui sait quelle folie pourrait survenir si l'un de ces textes enchantés tombait entre de mauvaises mains ?\n\nCela me fait penser : mon assistant, Dellis, a fait une terrible erreur la semaine dernière. Il est parfaitement à l'aise dans la bibliothèque, mais parfaitement incompétent dès qu'il franchit les portes de Stormwind. Soyez un exemple de ce temps et allez aider le vieux Dellis, voulez-vous ?", progress = nil, completion = "Ce n'était pas ma faute ! Ce n'était vraiment pas ma faute…", rewards = "Vous recevrez :\n\n"},
[1364] = {title = "Les ordres de Mazen", objective = "Retrouver les Essais de Khadgar sur la convergence dimensionnelle et les porter au Gardien Mahar Ba au Rempart-du-Néant.", description = "Les ordres de maître Mazen sont très clairs : porter d'importants essais au Gardien Mahar Ba au Rempart-du-Néant.\n\nMais je n'ai jamais été dans les Terres foudroyées avant ! C’est terrifiant !\n\nDans le marais des Chagrins, j'ai pris un mauvais chemin et j'ai fini cerné par d'horribles créatures à moitié végétales. Elles bougeaient comme si elles voulaient m'attaquer, alors j'ai fui. Mais dans ma hâte, j'ai laissé tomber les papiers. Un des monstres les a pris, j'en suis sûr.\n\nPourriez-vous les retrouver s'il vous plaît et les porter à Mahar Ba ?", progress = "Qu'est-ce qui vous amène au Rempart-du-Néant, <nom> ?", completion = "Ah, fabuleux !\n\nPendant un temps, j'ai eu peur que ma requête concernant les essais de Khadgar sur la convergence dimensionnelle ne retienne pas l’attention de Maître Mazen de l'Académie des arts et sciences des arcanes.\n\nIl doit être noyé sous les requêtes, au vu de toutes les choses étranges qui ont lieu.\n\nMaintenant, si vous voulez bien m'excuser, je dois commencer mes recherches sur-le-champ. Découvrir la pensée de quelqu'un d'aussi impressionnant que Khadgar est quelque chose auquel je ne puis résister…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe de professeurBottes des errants\n\nVous recevrez également :\n\n"},
[1365] = {title = "Khan Dez'hepah", objective = "Rapporter la Tête du khan Dez'hepah à Felgur Twocuts en Désolace.", description = "Les Kolkar ne sont pas les seuls centaures de Désolace. De nombreux clans parcourent ces plaines sèches, combattant et mourant. Il est heureux qu’ils se battent entre eux, car ils sont forts et brutaux. Si les centaures s'unissaient contre nous, ils seraient un adversaire redoutable.\n\nNous devons nous occuper d'eux avant qu'ils ne s'allient.\n\nVotre première mission est de désorganiser le clan Kolkar. Vous y parviendrez en tuant son chef, le khan Dez'hepah.\n\nLe village des Kolkar est au nord-est. Allez et que les dieux soient avec vous !", progress = "<nom>, avez-vous défait le khan Dez'hepah ?", completion = "Bien joué ! Cette frappe rapide contre les Kolkar est une démonstration impressionnante de force, et la force est ce que les centaures comprennent le mieux.\n\nLa mort du chef des Kolkar ne perturbera pas seulement ce clan, mais arrêtera aussi les autres.", rewards = "Vous recevrez :\n\n"},
[1366] = {title = "La prime aux centaures", objective = "Apporter 15 Oreilles de centaure à Felgur Twocuts, en Désolace.", description = "Maintenant que vous avez terrifié les clans centaures, il est temps de les saigner. Lorsque vous voyagerez à travers Désolace, chassez-les. Je me moque de savoir à quel clan ils appartiennent. Vous devez juste collectionner les oreilles. Je veux un monceau d'oreilles !\n\nEn diminuant leur nombre vous porterez un coup à leur résolution et sonnerez le glas de leurs envies d'expansion.\n\nBonne chasse, <nom>.", progress = "Comment se porte votre collection d'oreilles, <nom> ? Est-elle déjà impressionnante ?", completion = "Maintenant les centaures connaissent votre nom. Je suis sûr qu'ils le connaissent et qu’ils le craignent. Et comme ils vous connaissent, ils savent sous quelle bannière vous vous battez.\n\nLa bannière de la Horde !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe lilasGarde-mains à fermoir\n\nVous recevrez également :\n\n"},
[1367] = {title = "L'alliance avec les Magram", objective = "Faire en sorte que les Magram soient Amicaux envers vous, puis aller parler à Warug.", description = "Pour battre les centaures, nous allons utiliser leur haine contre eux. Nous allons nous allier à l'un des clans, et par ce biais nous apprendrons comment battre les autres clans.\n\nSi vous décidez de vous allier aux Magram, alors tuez leurs ennemis, les Gelkis. Vous gagnerez ainsi le respect des Magram. Lorsque cela sera fait, alors allez rencontrer Warug, le porte-parole des Magram, dans les faubourgs du village des Magram au sud-est de Désolace.", progress = nil, completion = "Les Gelkis pleurent lorsqu'ils entendent votre nom, &lt;nom&gt;. Ils vous craignent et vous haïssent. Ils vous haïssent autant qu'ils haïssent les Magram !\n\nPeut-être êtes-vous aussi fort qu’un Magram ? Nous verrons…", rewards = "Vous recevrez :\n\n"},
[1368] = {title = "L'alliance avec les Gelkis", objective = "Faire en sorte que les Gelkis deviennent Amicaux envers vous, puis aller parler à Uthek la Sage.", description = "Pour battre les centaures, nous allons utiliser contre eux leur haine fratricide. Nous allons nous allier à l'un des clans, et par ce biais, nous apprendrons comment vaincre les autres clans.\n\nSi vous décidez de vous allier aux Gelkis, alors tuez leurs pires ennemis, les Magram. Après avoir gagné le respect des Gelkis, allez rencontrer le chaman Uthek la Sage dans les environs du village des Gelkis, au sud-ouest de Désolace.", progress = nil, completion = "La terre me parle. Et elle dit que vous avez tué de nombreux Magram. Cela est bien !\n\nSi vous êtes proche des Gelkis, alors écoutez. J'ai d'autres choses à vous faire faire.", rewards = "Vous recevrez :\n\n"},
[1369] = {title = "Larmes brisées", objective = "Maintenir votre réputation auprès des Magram et ramener 3 Larmes brisées à Warug au village des Magram.", description = "Les Gelkis pensent que Theradras, la mère des centaures, nous protège. Ils sont idiots. Personne ne protège les centaures. Les centaures n'ont pas besoin de protection ! Les Magram n'ont pas besoin de protection ! Nous sommes les plus forts !\n\nMontrez aux Gelkis qu'ils sont stupides. Allez dans la caverne de leur village. Ils y possèdent des cristaux, les Larmes de Theradras. Détruisez ces cristaux et rapportez-moi les morceaux.", progress = "Si vous n'êtes pas notre ennemi alors vous ferez ce que je dis !", completion = "Vous avez les larmes ! Maintenant les Gelkis vont savoir que Theradras ne les aidera pas. Elle ne pleurera pas lorsque nous allons les écraser ! Les Magram régneront !\n\nVous êtes intelligent de nous aider, &lt;nom&gt;. Nous sommes les plus forts.", rewards = "Vous recevrez :\n\n"},
[1370] = {title = "Voleur de viande", objective = "Rapporter 6 Sacs de viande grossièrement séchée à Uthek la Sage au village des Gelkis.", description = "Lorsque nous ne sommes pas en guerre, nous chassons pour trouver de la viande. La viande nous donne la force et des ventres remplis se battent mieux que des ventres vides.\n\nC'est la même chose chez les Magram. Ils gardent la viande en trop afin de se battre plus longtemps entre leurs chasses. Si vous attaquez leur village par l'est et prenez leurs réserves de viande, leur force va diminuer.", progress = "Revenez après avoir prouvé votre valeur aux Gelkis !", completion = "Bien ! Je peux entendre geindre les ventres des Magram depuis leur village, loin d'ici !\n\nJe vais donner cette viande aux Gelkis. Et nous allons nous battre pendant de longs jours sans repos.\n\nCe que vous avez fait est bon pour les Gelkis, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEtoile d'argentFlèche à plumesBalle explosive\n\nVous recevrez également :\n\n"},
[1371] = {title = "Un Bidule pour Warug", objective = "Maintenir votre réputation auprès des Magram et rapporter un Leurre perfectionné à Warug au village des Magram en Désolace.", description = "Il y a longtemps, un petit gnome est venu en Désolace. Il avait des chevaux et une carriole qui contenait des choses étranges. De drôles de choses. Des choses qui brûlaient de différentes couleurs. Des choses qui bougeaient, mais n'étaient pas vivantes. J'ai tué le petit gnome mais avant cela... Il m'a fait rire.\n\nJ'ai gardé ma chose préférée de sa carriole. C'était un humain en bois qui me faisait signe jusqu'à ce que je le tape et que je le casse.\n\nJ'en veux un nouveau !", progress = "Si vous n'êtes pas notre ennemi alors vous ferez ce que je dis !", completion = "Oui, c'est ça que j'avais ! Je vais le faire bouger. Ça me fait tellement rire !", rewards = "Vous recevrez :\n\n"},
[1372] = {title = "La vérité, rien que la vérité", objective = "Parler à l’Apothicaire Faustin, au Repaire des mendiants.", description = "Notre force expéditionnaire a été envoyée sur les ordres de Varimathras pour surveiller le bas-Azeroth.\n\nPendant une reconnaissance, j'ai remarqué un infiltrateur humain qui espionnait le Repaire des mendiants. Avant que je ne puisse l'attraper, certains de nos... frères orcs l'ont capturé et emmené à Stonard, leur forteresse dans le marais des Chagrins.\n\nJe veux… aider… nos alliés, les orcs. Ils n'ont pas vu notre camp, mais malgré cela, je veux les aider.\n\nTravaillez avec Faustin pour développer… un sérum de vérité pour notre ami, à Stonard.", progress = nil, completion = "Zraedus était juste en train de me raconter cette histoire d'infiltrateur avant que vous n'arriviez.\n\nUn sacré problème. La dernière chose dont nous ayons besoin est que l'on fouine autour du Repaire des mendiants.\n\nJe suis sûr que ces orcs de Stonard seraient très intéressés par ce que notre ami a à dire. Sachant que ce sont... hum... nos alliés, nous devons les aider à obtenir toutes les informations possibles de cet humain.\n\nTravaillez avec moi, &lt;nom&gt;, pour porter un sérum de vérité à Stonard.\n\nPour la Horde !\n\n... Je l'ai bien dit comme il fallait ?", rewards = "Vous recevrez :\n\n"},
[1373] = {title = "Ongeku", objective = "Maintenir votre réputation auprès des Gelkis et rapporter un Eclat de draenéthyste à Uthek la Sage au village des Gelkis, en Désolace.", description = "Vous avez encore à prouver des choses et votre prochaine mission vous emmènera loin, car maintenant les Gelkis vont combattre les Magram sans vous.\n\nLa terre chuchote bien des secrets à ceux qui savent écouter. Un des secrets que j'ai appris est qu'il existe un cristal rouge appelé draenéthyste, nouvellement arrivé sur notre terre. Il vient d'un endroit où les montagnes volent et où les démons règnent.\n\nApportez-moi un éclat de draenéthyste et ma magie grandira ! Le cristal se cache dans un endroit appelé le marais des Chagrins, et appartient à un Perdu, Ongeku.", progress = "Montrez-moi que vous êtes un ami des Gelkis, <nom>.", completion = "Oui, c'est le cristal dont la terre parlait ! Je peux sentir une puissante magie en lui ! Je vais utiliser cette magie contre les ennemis des Gelkis.\n\nVous avez encore accompli une mission pour nous, &lt;nom&gt;. Peut-être que bientôt nous vous appellerons ami.", rewards = "Vous recevrez :\n\n"},
[1374] = {title = "Khan Jehn", objective = "Rapporter la Tête du khan Jehn à Uthek la Sage au village des Gelkis, en Désolace.", description = "La terre me parle et me dit que les Magram sont de plus en plus faibles. Il est maintenant temps de tuer leur khan !\n\nRapportez-moi la tête de Jehn, le khan des Magram !", progress = "Montrez-moi que vous êtes un ami des Gelkis, <nom>.", completion = "Le khan Jehn était fort, mais stupide. Il pensait que sa force était grande. Il n'a pas vu que la magie de la terre était plus forte. Sans leur chef, les centaures Magram vont maintenant tomber, et les Gelkis vont régner !", rewards = "Vous recevrez :\n\n"},
[1375] = {title = "Khan Shaka", objective = "Maintenir votre réputation parmi les Magram et rapporter la Tête du khan Shaka à Warug au village des Magram en Désolace.", description = "Vous avez aidé les Magram et je vous apprécie. Maintenant tuez le khan des Gelkis ! Il s'appelle Shaka et je veux sa tête ! Je veux la regarder et me moquer d'elle !", progress = "Servez les Magram et je vous aiderai.", completion = "Le khan Shaka est mort ! Je vais placer sa tête sur une pique et la garder avec moi afin que Shaka puisse voir la puissance des Magram !", rewards = "Vous recevrez :\n\n"},
[1380] = {title = "Khan Hratha", objective = "Maintenir votre réputation auprès des Gelkis, et apporter le Fragment de clé des Maraudine à Uthek la Sage au village des Gelkis.", description = "Vous nous avez aidés contre les Magram, <nom>. À présent, aidez-nous à battre le clan des Maraudine ! Tuez leur chef, le khan Hratha !\n\nPour le combattre, soufflez dans la corne de guerre maraudine. Elle se trouve au sommet d'un grand promontoire, dans la Vallée des lances.\n\nMais pour souffler dans la corne, vous devez d’abord obtenir une embouchure de corne de guerre. Elles sont rares, et portées uniquement par des Maraudine de confiance.\n\nQuand vous aurez soufflé dans la corne, des centaures arriveront. Tuez-en jusqu'à ce que Hratha apparaisse.\n\nLe khan Hratha porte un fragment de... clé. Apportez-le-moi...", progress = "Le khan Hratha est-il mort ? Avez-vous le fragment de clé ?", completion = "Il est mort ! Le khan Hratha est mort ! Et maintenant, le clan Maraudine va tomber ! Quand les Gelkis seront maîtres de cette terre, &lt;nom&gt;, nous nous souviendrons de vous. Et les esprits de la terre chanteront votre nom à jamais.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCotte d'anneaux de maraudeur gelkisDoigt d'Uthek\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1381] = {title = "Khan Hratha", objective = "Maintenir votre réputation auprès des Magram, et apporter le Fragment de clé des Maraudine à Warug au village des Magram en Désolace.", description = "Le khan des Gelkis est mort, et à présent le clan Maraudine va tomber ! Tuez le khan des Maraudine, Hratha.\n\nPour le combattre, soufflez dans la Corne sur le grand promontoire de la Vallée des lances. Mais pour y souffler, vous aurez besoin d'une Embouchure. Pour l'obtenir, tuez des centaures Maraudine. Tuez jusqu'à ce que vous la trouviez. Puis soufflez dans la corne.\n\nAgissez ainsi et les centaures Maraudine viendront à la tour. Tuez-en jusqu'à ce que le khan Hratha apparaisse. Il détient un fragment de clé. Apportez-moi ce fragment...", progress = "Faites ce que je demande. Prouvez-moi que vous êtes l'allié des Magram !", completion = "Le khan Hratha est mort ! À présent, les Magram sont les plus forts des centaures ! Nous écraserons les autres et règnerons sur Désolace !\n\nNous nous souviendrons de vous, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de chasseur de MagramCouverture de cérémonie centaure\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1382] = {title = "Une étrange alliance", objective = "Obtenir que les Gelkis se montrent Amicaux, puis parler à Uthek la Sage.", description = "Nous avons de la chance que les clans de centaures se battent entre eux, car s'ils unissaient leurs forces, rien ne pourrait les arrêter. Oui, nous sommes chanceux, et nous devrions mettre à profit cet avantage.\n\nL'un des clans de centaures, le clan Gelkis, mène une guerre acharnée au clan Magram. Si nous attaquons ce second clan, alors nous pourrions peut-être conclure une alliance avec les Gelkis.\n\nAllez parler à Uthek la Sage, aux approches des campements gelkis, au sud-ouest de Désolace. Grâce à elle, vous pourrez peut-être conclure une alliance avec le clan Gelkis.", progress = nil, completion = "On murmure votre nom parmi les Gelkis. Vos mains sont trempées du sang des Magram. C'est bien.\n\nPeut-être est-ce bien aussi que nous parlions. Dites-moi ce que vous pouvez faire pour les Gelkis, et ce que les Gelkis peuvent faire pour vous.", rewards = "Vous recevrez :\n\n"},
[1383] = {title = "La vérité, rien que la vérité", objective = "L'apothicaire Faustin, du repaire des mendiants, a besoin de 5 Cœurs de panthère des ombres, d'un Champignon de Boueux et d'une Tumeur d'Arpentefonds.", description = "J'ai tout simplement en tête le bon sérum. Il s'occupera de la vérité exactement comme il convient. Pour cette préparation, je vais avoir besoin de beaucoup de cœurs de panthères des ombres, en provenance du marais. J'aurai également besoin d'un champignon de boueux enchanté, de la réserve personnelle du seigneur du bourbier local. Il est certain que quelqu'un d'aussi talentueux que vous, <nom>, peut le persuader de s'en séparer.\n\nLe plus difficile sera de trouver une tumeur d'Arpentefonds dans la lointaine Désolace. Il est très rare que les géants de là-bas tombent malades et forment des tumeurs.\n\nAllez-y à présent !", progress = "Cet infiltrateur à Stonard va sûrement… s'épandre… quand il aura bu mon sérum spécial.\n\nLes ingrédients nécessaires à sa préparation sont tout sauf aisés à trouver. Les panthères des ombres sont assez répandues dans les marais, mais réunir cette quantité de cœurs peut prendre un moment. Et il arrive que le Seigneur du bourbier soit particulièrement tatillon.\n\nEn ce qui concerne la tumeur d'Arpentefonds, elle est horriblement difficile à trouver, mais la réaction chimique que je peux tirer de ce mélange est sans équivalent.", completion = "Splendide, &lt;nom&gt; ! Et juste à temps, en plus. D'après ce que me dit Zraedus, l'infiltrateur s'est remis de ses blessures et est prêt à être interrogé par les orcs.\n\nDonnez-moi simplement un moment pour que je prépare le pois… je veux dire, le sérum de vérité.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape du chancreMaillet de Cragwood\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1384] = {title = "Raid sur les Kolkar", objective = "Maintenir votre réputation auprès des Gelkis, et apporter 10 Charmes bruts à Uthek la Sage dans le village des Gelkis, en Désolace.", description = "Les Kolkar estiment que leur magie est puissante. Ils ne connaissent rien à la magie ! Ils ne reconnaîtraient même pas la magie si elle les frappait !\n\nVous allez leur montrer que leur magie est faible. Allez chez les centaures Kolkar au nord-est, et tuez-les. Détruisez leurs camps. Apportez-moi leurs charmes, que je les jette au feu et que je rie !", progress = "Avez-vous les charmes ? Avez-vous montré leur faiblesse aux Kolkar ?", completion = "Vous rendez un grand service aux Gelkis. Les Kolkar sont faibles et vont mourir. Leur magie pathétique ne les sauvera pas. Vous le leur avez montré, et leur peur va les affaiblir encore plus !\n\nEt ici, celui qui est faible meurt rapidement.", rewards = "Vous recevrez :\n\n"},
[1385] = {title = "Une violente politique", objective = "Faire en sorte que les Magram soient Amicaux à votre égard, puis aller parler à Warug.", description = "Désolace est une terre en guerre. Les centaures se font la guerre les uns les autres. Nous pensons que les vainqueurs vont surgir et menacer nos forteresses, ce que nous ne pouvons permettre.\n\nNous devons apprendre comment battre les centaures, et pour cela nous devons nous allier à l'un des clans. Les centaures Magram sont en guerre contre les Gelkis. Si vous combattez les centaures Gelkis, alors les Magram pourraient envisager une alliance.\n\nGagnez les faveurs des Magram, puis parlez à Warug, au village des Magram, au sud-est de Désolace.", progress = nil, completion = "Beaucoup de Gelkis sont tombés devant vous. J'aime ça. Peut-être pouvez-vous faire plus de choses que j'aime. Peut-être que vous et les centaures Magram peuvent être amis.", rewards = "Vous recevrez :\n\n"},
[1386] = {title = "Assaut sur les Kolkar", objective = "Maintenir votre réputation auprès des Magram, tuer 12 Centaures kolkar, 12 Eclaireurs kolkar, 6 Marteleurs kolkar, puis retourner voir Warug, dans le village des Magram, en Désolace.", description = "Les centaures Kolkar pensent qu'ils sont forts, mais nous rions de leur force ! Nous rions d'eux et nous les tuons ! Vous les tuez aussi. Montrez-moi que vous pouvez tuer des centaures Kolkar comme nous les tuons. Allez vers le nord et massacrez-les tous !", progress = nil, completion = "Les centaures Kolkar ont peur de vous maintenant. J'espère que vous avez ri en les tuant. C'est meilleur de rire en tuant, car l'ennemi voit qu'il est faible.", rewards = "Vous recevrez :\n\n"},
[1387] = {title = "La prime aux centaures", objective = "Apporter 15 Oreilles de centaures au caporal Melkins, à la combe de Nijel, en Désolace.", description = "Le peuple des centaures est divisé en nombreux clans. Chaque clan a son chef et ses propres buts, mais ils ont tous une « qualité » en commun : la cruauté.\n\nSi nous voulons avoir une chance de construire la paix, alors les centaures doivent être éradiqués. C'est exactement la tâche que je vous confie.\n\nPendant que vous serez en Désolace, chassez des centaures et prenez leurs oreilles. Apportez-moi de nombreuses, très nombreuses oreilles.\n\nŒuvrez au service de l'Alliance, <nom>, et nous nous rapprocherons de la fin de la guerre.", progress = "Avez-vous un rapport à me faire, <nom> ?", completion = "Ah, les oreilles ! Beau travail !\n\nLa qualité de vos services à l'Alliance ne peut être mise en cause, &lt;nom&gt;. Le sang que vous avez fait couler en Désolace épargnera, il est certain, un nombre incalculable d’autres vies.", rewards = "Vous recevrez :\n\nAnneau de calme"},
[1388] = {title = "La vérité, rien que la vérité", objective = "Remettre le Sérum de vérité de Faustin au traqueur noir Zraedus au Repaire des mendiants.", description = "Tout se déroule selon le plan, <nom>. Je veux que vous remettiez ce sérum de vérité au traqueur noir Zraedus et il vous montrera comment l'administrer… proprement.\n\nHa ! Ha !", progress = "J'espère que vous vous êtes montré utile à notre cher ami, l'apothicaire Faustin.", completion = "Je savais que le vieux Faustin arriverait à quelque chose de bon ! Vous avez été d'une aide extraordinaire, c'est certain.\n\nÀ présent parlons affaires, voulez-vous ?", rewards = "Vous recevrez :\n\n"},
[1389] = {title = "Les cristaux de draenéthyste", objective = "Apporter 6 Cristaux de draenéthyste à Magtoor au Havre boueux du marais des Chagrins.", description = "Les Perdus qui vivent dans le Sanctuaire des friches nous ressemblent physiquement, mais ce sont des monstres… rendus fous par les rigueurs de notre voyage vers Azeroth. Nos anciens frères attrapent et tuent quiconque s’approche du Sanctuaire des friches, à l'est.\n\nEt ils nous ont volé quelque chose de sacré à nos yeux : des cristaux de draenéthyste.\n\nNous n'avons pas la force suffisante pour pénétrer dans le Sanctuaire des friches et reprendre nos draenéthystes volées dans leurs huttes et près des feux de camp. Mais sans ces cristaux... nous pourrions également perdre la voie, tout comme eux.", progress = "Avez-vous les cristaux ?", completion = "Merci, &lt;nom&gt;. Nous vous sommes redevables.", rewards = "Vous recevrez :\n\n"},
[1391] = {title = "La vérité, rien que la vérité", objective = "Apporter la Bière de Zraedus à l'Infiltrateur Marksen à Stonard.", description = "Nous devons procéder avec une certaine discrétion. Après tout, ce n'est pas comme si vous alliez danser la valse là-bas et convaincre un imbécile de boire la préparation de Faustin, pas vrai ?\n\nMais il y a une chose à laquelle les humains ne savent pas dire non, c'est l'alcool. Je prendrai le sérum de Faustin et le verserai dans de la bière. Je peux garantir que le pauvre type n’hésitera pas à la siffler d'un trait.\n\nHâtez-vous vers Stonard, dans le marais des Chagrins, <nom>.\n\nEt faites en sorte que notre petite mission reste secrète et sans accroc...", progress = "Ayez pitié de moi ! Je possède des informations qui dépassent le cadre de la seule l'Alliance. Bien que je ne sois pas un sympathisant de la Horde, je suis au courant de trahisons qui doivent être révélées !", completion = "Une boisson, pour moi ? Comme c'est aimable. Cela fait des jours qu'ils ne m'ont pas permis de me désaltérer. Laissez-moi boire ça, et alors je vous dirai ce que j'ai appris…", rewards = "Vous recevrez :\n\n"},
[1392] = {title = "Noboru le Gourdin", objective = "Apporter le Gourdin de Noboru au Chef du Havre boueux dans le marais des Chagrins.", description = "Noboru a harcelé les draeneï du Havre boueux pendant des mois, et son gourdin est le symbole de la brutalité qu’ils ont subi de la part de ceux qu'ils ont perdus.", progress = "Salutations. Et bienvenue au Havre boueux !", completion = "Vous avez obtenu l'arme du redouté Noboru ? Est-il mort ?\n\nC'est un jour heureux pour le Havre boueux. Noboru et sa bande nous terrorisaient, à errer dans les marais et à massacrer tout draeneï croisant leur chemin. Il était un danger direct pour notre simple survie, et nous n'avions pas la force de le combattre.\n\nNous avons de la chance de vous avoir pour ami, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1393] = {title = "L'évasion de Galen", objective = "Escorter Galen jusqu'à ce qu'il soit hors de danger, puis trouver son camp dans le marais des Chagrins et ouvrir son coffre.", description = "Au secours ! Ces créatures vont me manger !\n\nSortez-moi de là, et je vous donnerai un grand trésor ! Il est dans mon camp, dans le marais au nord de Stonard, mais il est enfermé dans un coffre qui ne peut être ouvert que grâce à un truc que moi seul connais.\n\nSi vous m'aidez à m'en sortir, alors je vous l’enseignerai.", progress = nil, completion = "La serrure de ce coffre est bourrée de résine noire. Il est impossible de l'ouvrir.\n\nMais Galen vous a parlé d'un loquet secret sur le fond du coffre…\n\nAprès une rapide recherche, vous trouvez le loquet, le tournez, et le coffre s'ouvre…", rewards = "Vous recevrez :\n\nTarge du visionnaire"},
[1394] = {title = "Le dernier voyage", objective = "Parler au traqueur des plaines Dorn aux Mille pointes.", description = "Vous avez bien œuvré, <nom>. Vous avez réussi mon test, et les tests d’avant. Retournez voir Dom aux Mille pointes. Il ressentira le changement qui s'est opéré en vous, et constatera que votre cerveau, votre corps et votre esprit sont suffisamment forts pour que vous soyez <récompensé/récompensée> de vos efforts.\n\nRestez fidèle à l'équilibre que vous avez montré durant ces épreuves, <nom>. Dorn vous testera à nouveau dans l'avenir si vous le faites.", progress = nil, completion = "Ah, &lt;nom&gt;. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.\n\nAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau de WindstormFlamme dansante\n\nVous recevrez également :\n\n"},
[1395] = {title = "Fournitures pour Rempart-du-Néant", objective = "Apporter la Caisse de Pierres de puissance à l'Intendant Lungertz, avant que le pouvoir des pierres n'expire.", description = "Cette caisse de pierres de puissance doit être livrée au Rempart-du-Néant, dans les Terres foudroyées. Elles ne vont pas conserver leur pouvoir longtemps, aussi nous ne pouvons pas les envoyer par la prochaine caravane.\n\nVous devez les emporter, et vous devez les emporter rapidement.\n\nApportez-les à l'intendant Lungertz au Rempart-du-Néant. Pour atteindre le donjon, vous devez voyager vers l'est, à travers le défilé de Deuillevent, puis à l'est à travers le marais des Chagrins, et enfin vers le sud à travers les Terres foudroyées.\n\nFaites attention, <nom>. Vous allez traverser des endroits dangereux, mais vous n'avez pas le droit d'échouer.", progress = "Salut ! Ne faites pas attention à tout ce tapage, c'est juste les affaires courantes du Rempart-du-Néant.\n\nVous avez quelque chose pour moi ?", completion = "Ah, les Pierres de puissance ! Les mages seront heureux de les avoir !\n\nMerci beaucoup, &lt;nom&gt;. Je sais que votre voyage depuis Darkshire n'a pas été facile.", rewards = "Vous recevrez :\n\n"},
[1396] = {title = "Des créatures sauvages rôdent", objective = "Tuer 8 Jeunes crocilisques Dents-de-scie, 10 Tisseuses des pleurs et 10 Jaguars du marécage, puis retourner voir le Gardien Biggs, dans le marais des Chagrins.", description = "Ma caravane avait pour destination la côte est. Mais nous ne l'avons pas atteinte. Les Perdus nous ont attaqués, tuant les gardes et volant des marchandises.\n\nMoi seul ai survécu à l'assaut. J'ai juré de protéger les marchandises restantes, mais des créatures sauvages rôdent dans les alentours. Je vous en prie, aidez-moi à défendre mon campement contre ces bêtes !", progress = "Les créatures des marais se rapprochent, <nom>. Je vous en prie, défendez le camp !", completion = "Les bruits des animaux sont à présent plus discrets, plus lointains. Merci, &lt;nom&gt;. Maintenant, espérons qu'ils ne reviendront pas !", rewards = "Vous recevrez :\n\n"},
[1398] = {title = "Bois flotté", objective = "Apporter 8 Morceaux de Bois séché au soleil au Gardien Biggs dans le marais des Chagrins.", description = "Je vous dois beaucoup, <nom>. Un cœur noble bat en vous. J'ai à présent une autre tâche pour laquelle je demanderai humblement votre aide.\n\nSi je veux avoir la moindre chance d'atteindre Rempart-du-Néant, alors je dois réparer mon chariot. Et pour cela, j'ai besoin de bois. Du bois fort, du bois sec, pas de ce bois spongieux et noueux des arbres du marais.\n\n<nom>, partez à l'est pour la côte et cherchez du bois qui a séché au soleil. Et apportez-le-moi.", progress = "Avez-vous trouvé ce bois, <nom> ?", completion = "Ce bois est léger, mais robuste. Merci, &lt;nom&gt;. Il fera parfaitement l'affaire.", rewards = "Vous recevrez :\n\n"},
[1418] = {title = "Neeka Bloodscar", objective = "Parler à Neeka Bloodscar.", description = "Les Terres ingrates sont une région difficile, en bordure du Loch Modan, un territoire aux mains de l'Alliance. Aussi, la liaison entre Stonard et Kargath, l'avant-poste des Terres ingrates, est-elle souvent interrompue.\n\nMontrez votre valeur, <nom>. Partez pour les Terres ingrates et parlez à Neeka Bloodscar, Eclaireur principal de l'avant-poste de Kargath. Parlez-lui, puis envoyez-moi son rapport.", progress = nil, completion = "Helgrum veut un compte rendu, hein ? J'ai envoyé une estafette à Stonard il n'y a pas trois jours. A-t-il échoué dans sa mission ? Si Stonard n'a pas reçu mon rapport, alors il semblerait que oui.\n\nEspérons que le prochain messager que j'enverrai sera meilleur, ou qu'il aura plus de chance.", rewards = "Vous recevrez :\n\n"},
[1419] = {title = "Les coyotes voleurs", objective = "Apporter 30 Mâchoires de coyotes à Neeka Bloodmark à Kargath.", description = "Avez-vous passé beaucoup de temps dans les Terres ingrates, <classe> ? Avez-vous ressenti la chaleur ? Avez-vous affronté les bêtes qui rôdent dans les plaines poussiéreuses ? Il est temps que vous le fassiez.\n\nLes coyotes des rochers sont une espèce robuste. Robuste, et suffisamment intrépide pour s'aventurer jusqu'à Kargath et chaparder de la nourriture. Aidez-nous à débarrasser l'avant-poste de ces pique-assiette !\n\nChassez les coyotes des rochers, <nom>. Chassez-les et apportez-moi leurs mâchoires. Apportez-en assez, et peut-être que je vous croirai lorsque vous dites que vous connaissez les Terres ingrates.", progress = "Avez-vous les mâchoires ?", completion = "Voilà une belle collection de mâchoires, &lt;nom&gt;. À présent, les coyotes ne vont plus s’attaquer à nos provisions.\n\nBon travail ! Les coyotes des Terres ingrates ne sont pas des proies faciles. Vos actions me disent que vous avez peut-être une chance de survivre ici.", rewards = "Vous recevrez :\n\n"},
[1420] = {title = "Le rapport à Helgrum", objective = "Apporter le Rapport de Neeka à Helgrum l'Agile à Stonard.", description = "J'ai écrit un rapport tout frais pour Helgrum à Stonard. Remettez-le-lui.\n\nEt si vous vous considérez comme une bonne estafette, alors ne vous perdez pas. Et ne tombez pas aux mains de l’ennemi.", progress = "Vous voilà de retour. Vous avez un rapport ?", completion = "Merci, &lt;nom&gt;. D'après le rapport de Neeka, je vois que l'Alliance a ses propres problèmes. Et il se peut que nous découvrions que nous avons certains ennemis en commun.", rewards = "Vous recevrez :\n\n"},
[1421] = {title = "Le chariot perdu", objective = "Trouver le Coffre de la Caravane, dans le Sanctuaire des friches, obtenir les Composants pour les sorciers, et les apporter au Gardien Biggs.", description = "J'ai perdu connaissance durant l'attaque des Perdus, mais avant que tout ne s'obscurcisse, j'ai vu l'un de nos chariots en train d'être traîné vers le Sanctuaire des friches, le village des Perdus, au nord.\n\nUn coffre plein d'ingrédients de valeur se trouvait dans ce chariot. Ces ingrédients sont d'un intérêt scientifique vital pour les sorciers du Rempart-du-Néant. Retrouvez ce coffre et mettez la main sur ces ingrédients, <nom>. Une fois que vous les aurez en votre possession, rapportez-les-moi.", progress = "Avez-vous les composants pour les sorciers, <nom> ?", completion = "Ah, vous les avez trouvés ! Avec ça, les sorciers de Rempart-du-Néant vont pouvoir continuer leur travail. Je ne sais pas vraiment ce qu'ils font, mais ça a un rapport avec la Porte des ténèbres dans les Terres foudroyées, et c'est vital pour la sécurité de l'Alliance.", rewards = "Vous recevrez :\n\n"},
[1422] = {title = "Le danger venu des flots", objective = "Parler à Katar, dans le marais des Chagrin.", description = "Pendant que je commence à travailler sur votre arme, pourquoi n'iriez-vous pas parler à Katar ? Il a mentionné qu'il aurait besoin d'aide pour patrouiller le long de la plage, et je vous imagine mieux gardant vos esprits et vos armes en alerte que vous saoulant en compagnie des autres poux avec qui je partage ce camp.", progress = nil, completion = "Restez silencieux un moment, &lt;classe&gt;. Même le grondement régulier de la mer n’arrive pas à couvrir les gargouillements dégoûtants de ces hommes-poissons.", rewards = nil},
[1423] = {title = "Les marchandises perdues", objective = "Apporter les Marchandises perdues à l'Intendant Lungertz.", description = "Ce tonneau, bien que petit, est robuste. Il est scellé avec une cire jaune à l’odeur âcre. On peut lire, tamponné au cul du tonneau :\n\nINTENDANT LUNGERTZ\n\nREMPART-DU-NEANT.", progress = "Vous avez quelque chose pour moi ?", completion = "Ah merci, &lt;nom&gt; ! Il y a tellement de marchandises qui se perdent entre Darkshire et ici. Il est rassurant de constater qu'on en retrouve certaines.", rewards = "Vous recevrez :\n\nBoîte de fournitures"},
[1424] = {title = "Le bassin des larmes", objective = "Fel’zerul à Stonard veut que vous rassembliez 10 Artefacts atal'ai.", description = "Le chef de guerre nous a envoyés enquêter sur des événements étranges survenus au temple d'Atal'Hakkar.\n\nLes trolls Atal'ai sont une tribu d'ensorceleurs noirs connus pour utiliser des magies interdites. Vous pouvez imaginer notre étonnement lorsque nous sommes arrivés pour découvrir que le temple avait été englouti.\n\nÀ présent, les dragons verts gardent le site, et ils se disent protecteurs d'Azeroth.\n\nNous devons découvrir ce qui s'est passé. Explorez les lieux autour du Bassin des larmes et rassemblez des artefacts atal'ai. Ils me permettront de reconstituer une partie du puzzle.", progress = "Personne ne sait quelles pratiques maléfiques ont eu cours au sein du temple d'Atal'Hakkar. Mais nous savons que de grandes et puissantes forces magiques y ont été utilisées.\n\nNous devons apprendre autant que possible d'une telle magie. Peut-être que les sorts atal'ai se révéleront utiles à la Horde.\n\nUne fois que vous aurez ramassé suffisamment d'artefacts atal'ai autour du Bassin des larmes, je pourrai commencer à comprendre ce que les trolls espéraient accomplir et ce qui s'est produit.", completion = "Votre assiduité pour collecter les artefacts atal'ai est digne de louanges, &lt;classe&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1425] = {title = "La remise du chargement", objective = "Apporter la Cargaison pour Rempart-du-Néant à l'Intendant Lungertz au Rempart-du-Néant.", description = "Pendant que je répare ce chariot, <nom>, j'ai une dernière tâche à vous confier.\n\nJ'ai empaqueté les marchandises les plus importantes rescapées des attaques des ogres. Apportez-les au Rempart-du-Néant. Le donjon est blotti dans les collines au nord des Terres foudroyées, pour surveiller la Porte des ténèbres.\n\nPour atteindre Rempart-du-Néant, suivez la route est. A l'embranchement, allez vers le sud dans les Terres foudroyées, puis tournez à gauche au second. Continuez à suivre la route, <nom>, et soyez <prudent/prudente>.", progress = "Vous avez des affaires pour moi ?", completion = "Quoi ? Un paquet de la caravane de Biggs ? Nous pensions que ces marchandises étaient perdues, tout comme lui.\n\nMerci, &lt;nom&gt;. Avec un peu de chance, ces paquets contiennent les composants dont nous avons besoin, les Cristaux d'Azoran. Notre stock s'épuise...", rewards = "Vous recevrez :\n\n"},
[1426] = {title = "Le danger venu des flots", objective = "Tuer 10 Murlocs des marais, 10 Cracheurs des marais, 10 Dévoreurs des marais, puis retourner voir Katar dans le marais des Chagrins.", description = "Je n'ai aucun amour pour la mer, ni pour aucune des créatures que j'ai vu sortir de ses profondeurs. C'est une maîtresse puissante, mais aveugle. Insensible et brutale. Cela m'apporterait un grand plaisir de massacrer les hommes-poissons par centaines si c'était en mon pouvoir. Mais je ressens également du plaisir à les regarder mourir de la main de quiconque obéit à la volonté de la Horde.\n\nCe qui nous amène à vous, <classe>. Combien pouvez-vous en massacrer ? Voudriez-vous vous mesurer à leur plus puissante espèce ?", progress = "Je suis patient. Patient et inusable telle une vieille pierre kank de Draenor. Tant que je suis debout, les hommes-poissons ne franchiront pas nos frontières. Si nous avions une armée à notre disposition, je nettoierais ce monde et tous les autres de leur infecte présence. Le simple fait de parler d'eux fait bouillonner ma haine.", completion = "La mer semble vaste et impitoyable, mais vous l'avez tachée du sang qu'elle a elle-même enfanté. Les hommes-poissons connaissent la douleur. Leur stupidité les amènera à fortifier à nouveau leurs rangs après le carnage que vous avez causé, et cela est bien.\n\nQu'on laisse leurs gargouillements éclipser le grondement de la mer loin dans la nuit. Je sourirai chaque fois que j'entendrai l'une de ces plaintes s'éteindre.\n\nRevenez me voir si vous souhaitez massacrer plus d'hommes-poissons. Ce sera avec plaisir que je vous récompenserai.", rewards = "Vous recevrez :\n\n"},
[1427] = {title = "Le danger venu des flots", objective = "Parler à Tok'Kar dans le marais des Chagrins.", description = "Avant que vous ne vous reposiez, parlez à nouveau à Tok'Kar. Pendant que vous étiez <parti/partie>, il a terminé quelques armes. Pour récompenser l'aide que vous nous avez apportée, il devrait vous en offrir une. Vous devriez tester sa force contre les hommes-poissons quand vous vous sentirez <prêt/prête>... mais seulement pour me faire plaisir.", progress = nil, completion = "Ah, &lt;nom&gt;, vous voilà de retour ! Bien. J'ai terminé de concevoir plus d'armes pour notre lutte contre les murlocs. Je vous offre l'une d'elles, pour nous avoir apporté de la viande fraîche de Dents-de-scie, et pour avoir amené un petit sourire sur le visage de Katar.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPerforeuse de Tok'karCastagneur de Tok'karDécoupeur de Tok'kar\n\nVous recevrez également :\n\n"},
[1428] = {title = "Le danger permanent", objective = "Tuer 10 Cracheurs des marais, 10 Dévoreurs des marais, 10 Oracles des marais, puis retourner voir Katar dans le marais des Chagrins.", description = "Il me plaît de voir que votre haine pour les hommes-poissons grandit en même temps que la mienne.\n\nTrouvez-en d'autres, le long de la plage, et lorsque vous serez <fatigué/fatiguée> de vous battre, revenez me voir. Nous parlerons alors d'une récompense pour vos efforts assidus.", progress = "Je ne serai pas heureux tant que la mer et ses enfants ne seront pas réduits au silence… Et spécialement ces hommes-poissons dégoûtants.", completion = "Bon travail, &lt;classe&gt;. Je souhaite qu'encore plus de leur sang soit versé. Que tous les hommes-poissons périssent !", rewards = "Vous recevrez :\n\n"},
[1429] = {title = "L'Exilé atal'ai", objective = "Apporter les Artefacts atal'ai à l'Exilé atal'ai dans les Hinterlands.", description = "Tandis que vous braviez les dangers du Bassin des larmes, l'un de mes éclaireurs a trouvé un vélin en peau séché, avec un texte écrit avec du sang. Cela semble être une sentence prononcée à l’encontre d’un prêtre de la tribu Atal'ai.\n\nLe prêtre a été condamné à un sort pire que la mort, pour un Atal'ai.\n\nIl a été exilé, obligé de vivre loin au nord, dans les Hinterlands, avec les trolls Witherbark.\n\nJe vais faire un paquet de ces artefacts. Vous allez trouver l'exilé et lui demander d’identifier ces objets. Revenez me voir lorsque vous aurez achevé votre voyage.", progress = "Vous êtes courageux pour venir jusqu'ici. Courageux ou fou.", completion = "Vous m'apportez les artefacts d'invocation atal'ai ?\n\nJe vois que Jammal'an le Prophète mène les disciples de la Chambre de sang vers le destin qu'ils ont choisi. Je me demande si Hakkar est retourné au temple ? Ont-ils rencontré leur destin ?", rewards = "Vous recevrez :\n\n"},
[1430] = {title = "Viande fraîche", objective = "Apporter 10 Pattes de clampants monstrueux à Dar dans le marais des Chagrins.", description = "Le goût succulent de la chair de clampant est très prisé parmi mes clients. Et particulièrement celui des clampants monstrueux.\n\nSi vous comptez vous rendre sur la côte prochainement, je peux rentabiliser votre voyage : rapportez-moi quelques-unes de leurs pattes et je les expédierai à Orgrimmar.\n\nLa côte se trouve à l'est, et vous y trouverez facilement ces créatures, détalant de-ci de-là le long des plages et dans la mer.", progress = "J'ai un tonneau de vin qui n'attend que votre réussite, <nom>. Il est normal que je goûte à la nourriture avant de l'envoyer à mes clients.", completion = "Ah ! Ceci devrait être parfait. J'ai hâte d'y goûter après qu'elles ont été bien préparées au-dessus d'un feu ouvert. Vous devriez en prendre une portion pour vos voyages. C'est réellement délicieux.", rewards = "Vous recevrez :\n\nPattes de roi clampant grilléesCeinture du cuistot en cuir"},
[1431] = {title = "Les relations de l'Alliance", objective = "Parler à Keldran à Orgrimmar.", description = "Tenez-vous tranquille, <classe>, et permettez-moi de partager avec vous quelque chose d'important pour notre peuple, mais loin d'être évident.\n\nNous sommes une race fière, et la guerre contre les humains a mis à rude épreuve même la grande patience de Thrall. Vous voyez, notre Chef de guerre est sage et prudent, et il continue à placer son peuple en premier. Il est, en fin de compte, un diplomate, et le temps qu'il a passé avec les humains lui a appris leur façon d'être.\n\nSi l'histoire que je viens de commencer éveille votre intérêt, alors trouvez Keldran près de la sortie ouest de la ville. Sa masure s'y trouve.", progress = nil, completion = "Putanni, noble &lt;classe&gt;. Je suis Keldran, étudiant en magie… et autres arts mystiques.\n\nL'affaire pour laquelle Craven vous envoie me parler exige une subtilité que vous n’avez pas eu l’occasion de montrer jusqu'alors, mais cela ne veut pas dire que vous ne pouvez plus soutenir notre cause.\n\nJe vous en prie, mettez-vous à l'aise, et je vais vous dire pourquoi le Chef de guerre a besoin de mon aide... et de la vôtre.\n\nCela commence par des apparences, &lt;nom&gt;. La façon dont la Horde se considère elle-même. Comment nos alliés nous considèrent. Et, encore plus important, comment nos ennemis nous considèrent.", rewards = "Vous recevrez :\n\n"},
[1432] = {title = "Les relations de l'Alliance", objective = "Parler à Takata Steelblade en Désolace.", description = "Tandis que l'Alliance progresse plus profondément en Kalimdor, des conclusions hâtives pourraient être faites à propos d'hypothétiques accords entre la Horde et la Légion ardente. Le Chef de guerre ne peut le permettre. Et avec sa bénédiction, je prends le contrôle pour superviser leur anéantissement.\n\nJ'ai des agents dans le secteur de Désolace, au Poste de Rôdeur-fantôme, au nord du grand Cimetière des kodos. Allez au sud du Val Calciné, dans les Serres-Rocheuses, vous devriez tomber dessus. Une fois sur place, cherchez Takata Steelblade.", progress = nil, completion = "Salutations, &lt;classe&gt;. Vous apportez des nouvelles d'Orgrimmar, c'est bien.\n\nL'infestation démoniaque nous submerge dans ce secteur, plus encore que l'odeur de bouse de centaure. Les hommes-chevaux réclament cette terre comme leur appartenant, mais il se trouve clairement des influences qu'ils ne maîtrisent pas et qui finiront par les écraser s'ils ne se ressaisissent pas.\n\nIl ne me sied pas que nous aidions, même indirectement, les centaures, mais c'est pour le bien de la Horde. Aussi j'accomplis mon devoir pour le Chef de guerre, même si cela veut dire venir en aide aux démonistes à l'intérieur de la Horde.", rewards = "Vous recevrez :\n\n"},
[1433] = {title = "Les relations de l'Alliance", objective = "Parler à Maurin Bonesplitter en Désolace.", description = "Les sectateurs de la Lame ardente élaborent de nombreux plans, mais sachez qu'ils sont foncièrement maléfiques, que leur esprit est corrompu, et que la destruction est le seul moyen de mettre un terme à leurs objectifs.\n\nKeldran a envoyé Maurin avec moi car il connaît la Lame et les méthodes des démonistes.\n\nIl supervise nos actions contre la Lame, tandis que je m'occupe des autres dangers démoniaques ici en Désolace.\n\nParlez-lui, et il vous expliquera ses projets.", progress = nil, completion = "Ah oui. L'aide de la part de ceux loyaux au Chef de Guerre est toujours appréciée.\n\nJe m'appelle Maurin. Je suis ici à la demande expresse de Keldran et du jeune chef Thrall. Je désire aider le jeune chef contre les maux qui menacent sa souveraineté.\n\nApprochez, &lt;classe&gt;. Je vous expliquerai mon plan pour supprimer la lèpre qu'est la Lame ardente.", rewards = "Vous recevrez :\n\n"},
[1434] = {title = "Souillé par les satyres", objective = "Massacrer 7 Voleurs Fielfurie, 7 Liges de la corruption Fielfurie, 7 Traîtres Fielfurie et 7 Implorateurs de l’enfer Fielfurie, puis retourner voir Takata Steelblade en Désolace.", description = "Une infestation démoniaque n'arrive pas sans une aide extérieure. Quelque chose permet au Mal de prendre pied.\n\nCela peut être un esprit affaibli, tenaillé par un désir vain de pouvoir. Peut-être est-ce une soif de vengeance, ou l'appel de la justice finale. Lorsque nous sommes assaillis par la douleur, le démon devient plus fort que nous. Un démon tel que les satyres.\n\nDes liens ont été établis entre les satyres et la Lame ardente, et Thrall souhaiterait les voir massacrés. Cherchez-les au nord-est d'ici, et revenez me voir lorsque vous les aurez vaincus.", progress = nil, completion = "Vous avez bien œuvré, &lt;classe&gt;. Vous avez démontré votre honneur et votre engagement.\n\nLorsque notre campagne en Désolace sera terminée, le Chef de guerre saura que vous nous avez aidés dans nos actions ici, et que vous avez aidé sa volonté à se réaliser.\n\nJe vous remercie.", rewards = "Vous recevrez :\n\n"},
[1435] = {title = "Esprits consumés", objective = "Apporter une Gemme ardente et 15 Gemmes ardente canalisées à Maurin Bonesplitter en Désolace.", description = "La mort est très désirable pour ces dégoûtantes créatures qui quittent les ordres de leur seigneur pour des raisons si égoïstes. Mais la mort n'est pas suffisante quand on a affaire à ceux qui se sont donnés aux ténèbres.\n\nPrenez cette gemme. Lorsque un membre de la Lame ardente approchera de la mort, activez sa magie. Le sort attirera l'esprit corrompu de sa victime, laisssant une gemme ardente canalisée.\n\nApportez-moi ces gemmes ardentes, que je m'en occupe comme il convient.\n\nPartez à présent, et puissiez-vous échapper à la mort.", progress = "J'ai essayé de faire en sorte que la magie soit aussi simple que possible. Attirer l'esprit de votre victime hors de sa forme blessée devrait être un jeu d'enfant. Ne comptez pas sur le pouvoir des gemmes pour tuer vos ennemis. Vous ne devez activer la gemme que lorsqu'ils sont proches de la mort.", completion = "Ah ! Vous êtes de retour et vous avez réussi. C'est bien. Donnez-moi les gemmes et je les placerai dans un endroit sûr…\n\nJe n'ai pas d'autre tâche pour vous, &lt;classe&gt;. Parlez à Takata une fois que vous aurez pris du repos. Il se peut qu'il en ait d'autres pour vous, ou il aura peut-être besoin que vous retourniez à Orgrimmar pour informer Keldran de nos progrès ici en Désolace.", rewards = "Vous recevrez :\n\n"},
[1436] = {title = "Les relations de l'Alliance", objective = "Parler à Keldran à Orgrimmar.", description = "La lutte se déroule bien, <nom>. Peut-être que le Chef de guerre nous permettra de rentrer dans nos foyers avant la fin de la saison si nous continuons à frapper de si grands coups dans notre bataille contre les démons et leurs servants.\n\nRetournez voir Keldran et faites-lui savoir ce que nous avons accompli. Il est certain qu'il récompensera vos efforts ici. Sa cause est importante à ses yeux, et il sera fier de savoir que le Chef de guerre la respecte.", progress = nil, completion = "Vous êtes revenu de Désolace plus que victorieux, &lt;nom&gt;. Merci.\n\nMerci pour vos efforts, votre temps et la compréhension de ma requête.\n\nThrall peut envisager et désirer la paix entre la Horde et l'Alliance. Et en prenant des mesures pour nous assurer que notre apparence est acceptable, nous ne provoquerons pas d’éclats de violence inutile.\n\nJe vous suis redevable.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de KapelanCape de vélocité\n\nVous recevrez également :\n\n"},
[1437] = {title = "La recherche de Vahlarriel", objective = "Rechercher le chariot de Tyranis et de Dalinda Malem en Désolace.", description = "Je me nomme Vahlarriel, <nom>. Je suis ici pour retrouver deux nobles disparus, issus d'une famille marchande de Darnassus : la famille Malem. Le père craint le pire, et je dois tout tenter pour retrouver ses enfants disparus. J'ai commencé mes recherches pour retrouver Tyranis ou Dalinda, mais j'ai bon espoir que je ne serai pas ici longtemps.\n\nAux dernières nouvelles, ils passaient par les Serres-Rocheuses il y a quelques semaines.\n\nSi vous trouvez leur chariot, s'il vous plaît, veuillez revenir ici pour m'en informer.", progress = nil, completion = "La fouille des restes du chariot révèle qu'il a été attaqué par des armes conventionnelles et des sorts. L’attaque a été rapide et unilatérale. Il n'y a ni traces de sang ni cadavres.\n\nQuel qu'ait été l'attaquant, il a été rapide et efficace.", rewards = "Vous recevrez :\n\n"},
[1438] = {title = "La recherche de Vahlarriel", objective = "Trouver Dalinda Malem en Désolace.", description = "Trouvez Dalinda et Tyranis si vous le pouvez, et revenez m'informer de vos progrès. Commencez vos recherches dans cette forteresse. Je vais immédiatement contacter mes supérieurs à Darnassus et les informer de la situation.\n\n<nom>, il y a quelque chose que je souhaite vous dire. Mes supérieurs ont montré quelque inquiétude à propos de Tyranis Malem et de ses raisons de venir ici. Le plus important pour eux est que Dalinda Malem soit retrouvée et ramenée en bonne santé. Nous devons... jauger Tyranis avant qu'il ne rentre chez lui.", progress = nil, completion = "Qu'Elune soit remerciée, quelqu'un est enfin venu à mon aide. S'il vous plaît, &lt;classe&gt;, j'ai besoin de vous. Mon frère Tyranis et moi avons été capturés et amenés ici par la Lame ardente. Je pense qu'ils comptent me sacrifier à leurs maîtres démoniaques !\n\nJe savais que venir à Désolace était une erreur, mais Tyranis a commencé depuis peu à se passionner pour tout ce qui concerne les arcanes - même contre la volonté de notre peuple. Il a décidé d'entreprendre ce périple bien qu'il ait entendu parler des démons qui infestent cette région.\n\nJe crains le pire pour lui.", rewards = "Vous recevrez :\n\n"},
[1439] = {title = "À la recherche de Tyranis", objective = "Trouver Tyranis Malem en Désolace.", description = "Nous avons été emmenés ici après le massacre de nos gardes et de nos serviteurs par les orcs. Oh ! Ils leur ont fait des choses si horribles ! J'ai cru qu'ils allaient également nous tuer, sur place, mais ils avaient visiblement d'autres plans.\n\nTyranis a essayé de leur parler. Je pense qu'il voulait les impressionner par sa connaissance des arcanes... Je ne suis pas sûre de savoir pourquoi.\n\nJe vous en prie, je ne peux pas quitter les lieux tant que j'ignore ce qu'il est advenu de mon frère. Retrouvez-le, et venez me dire quel a été son sort.", progress = "Je crains que Tyranis n'essaie d'apprendre les secrets de la Lame ardente et de rejoindre leurs rangs s'ils y consentent - il a toujours adoré le pouvoir que donne la magie à ceux qu'elle séduit.\n\nJe ne suis pas certain de vouloir retourner parmi les miens avec la nouvelle que l'esprit de Tyranis fraye avec de tels dangers. C'est déjà un délit épouvantable pour ceux de mon espèce de se consacrer à de telles pratiques, mais devenir la chose dont nous essayons de nous protéger, ma foi, c'est criminel.", completion = "C'est terrible ! Mais je suppose que c'était nécessaire. Si cela n'avait pas été de votre main, alors c’est l'une de mon peuple qui aurait frappé. Je pense que je devrais vous remercier – veuillez me pardonner si cela n'a pas l'air sincère. Mon but n'est pas de vous offenser.\n\nMaintenant que je sais que mon frère a rencontré son destin, il semble que le temps de mon évasion soit venu. Si vous le souhaitez toujours, j'accepte volontiers votre aide pour m’échapper de cet horrible endroit.\n\nLorsque vous serez prêt, nous partirons pour un lieu sûr.", rewards = "Vous recevrez :\n\n"},
[1440] = {title = "Le retour vers Vahlarriel", objective = "Escorter Dalinda Malem depuis la forteresse de Hache-Tonnerre et retourner voir Vahlarriel Demonslayer, en Désolace.", description = "Ainsi, le temps est venu ? J'apprécie vos efforts, et si la situation ne se résout pas, alors permettez-moi de vous remercier dès à présent pour tout ce que vous avez fait pour moi et ma famille. Si vous êtes <prêt/prête>, rien ne me retient ici. Nous pouvons partir quand vous estimerez le bon moment arrivé.", progress = nil, completion = "Merci, &lt;nom&gt;. Dalinda est revenue saine et sauve à la Combe de Nijel, et dans une bien meilleure condition que je n'aurais pu l'espérer. Le fait qu'elle y soit parvenue par ses propres moyens est bon signe. J'espère que vous allez bien ?\n\nCela me peine de savoir que Tyranis et Dalinda ne sont pas revenus ensemble, mais c'est à elle qu'incombe l'embarras des décisions de Tyranis. Elle devra vivre avec lorsqu'elle retournera à Darnassus.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de lutteurGants de clairvoyanceCape de la garnisonAmict lunaires\n\nVous recevrez également :\n\n"},
[1442] = {title = "À la recherche de la gemme de Kor", objective = "Apporter une Gemme de Kor à Thundris Windweaver à Sombrivage.", description = "Salutations, <nom>. Que puis-je faire pour quelqu'un qui suit la voie sacrée ?\n\nAh oui ! Stilwell, le forgeron… d'il y a longtemps. Je me souviens bien de lui, mais cela fait quelque temps que je n'ai pas entendu parler de lui.\n\nIl ne m'a jamais paru impudent, aussi je ne peux que supposer que son désir d'une gemme de Kor est noble.\n\nSi vous souhaitez réellement l'une de ces gemmes, alors vous devez vous diriger vers le nord-ouest d'Ashenvale. Vous y trouverez les Profondeurs de Brassenoire à l'intérieur de ruines anciennes. Les nagas qui utilisent toujours ces gemmes se trouvent en bas. Ne partez pas <seul/seule>, <classe>.", progress = "Si quelqu'un venait s'informer sur la Gemme de Kor en dehors du chemin sacré, je serai soupçonneux. Mais j'ai plus confiance en votre race qu'en certains membres de ma propre famille. Je ne juge pas tout votre ordre à l’aune de ceux qui sont déchus.", completion = "C'est effectivement la gemme que Stilwell désire, mais avant que j’autorise son départ, elle doit être purifiée de toute corruption. Les jeunes femelles nagas imprègnent les gemmes de puissance, ceci est certain, mais de nature maléfique.\n\nFaites savoir à Stilwell que cette puissance est intacte, et qu'elle devrait fonctionner pour n'importe quel rituel qu’il voudrait mettre en place.\n\nJ'espère que vous savez ce que vous faites, &lt;classe&gt;, ce n'est pas un objet anodin que vous possédez là.", rewards = "Vous recevrez :\n\nGemme de Kor purifiée"},
[1444] = {title = "De retour vers Fel’Zerul", objective = "Retourner voir Fel’Zerul à Stonard.", description = "Jammal'an le Prophète m'a condamné à être exilé du temple d'Atal'Hakkar. Je considérais autrefois que le grand prêtre était un chef digne.\n\nSa foi inflexible dans sa prophétie apportera la destruction aux Atal'ai. Si ce n'est pas déjà fait.\n\nLorsque j'ai exprimé des réserves, j'ai été traité d’infidèle et évincé du temple.\n\nLes artefacts que vous avez apportés sont inoffensifs. Mais si Jammal'an a découvert le bon fétiche d'enchantement pour le rituel d'invocation, alors le monde court un grand péril...", progress = nil, completion = "Cela fait longtemps que nous avons parlé, &lt;classe&gt;. J'espère que votre voyage s'est révélé un succès.\n\nQuelle connaissance avez-vous acquise de l'Exilé atal'ai dans les Hinterlands ?", rewards = "Vous recevrez :\n\n"},
[1445] = {title = "Le temple d'Atal'Hakkar", objective = "Rassembler 20 Fétiches d'Hakkar et les apporter à Fel’Zerul à Stonard.", description = "Ainsi il a parlé de la prophétie de Jammal'an ?\n\nLe chef spirituel des Atal'ai croit qu'une fois Hakkar revenu du Néant pour Azeroth, le dieu accordera l'immortalité à sa tribu.\n\nUne excuse idiote pour provoquer une fin du monde prématurée, si vous voulez mon avis.\n\nMais vous dites que l'Exilé a parlé de fétiches enchantés ? Cela m'inquiète profondément. S'ils constituent la clé du rituel atal'ai et qu'ils sont à l'origine de ce chaos, nous devons comprendre leurs pouvoirs intrinsèques.\n\nAventurez-vous dans le temple, et emparez-vous des fétiches.", progress = "Si les fétiches atal'ai détiennent le pouvoir d'invoquer Hakkar et de remplir la prophétie de Jammal'an, alors nous devons nous en emparer. De tels pouvoirs doivent être assimilés par la Horde !", completion = "Vous êtes courageux. Vous nous avez montré que vous êtes un grand champion de la Horde.\n\nÀ présent nous devons nous occuper de cette collection de fétiches d'Hakkar, &lt;classe&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTalisman de gardien"},
[1446] = {title = "Jammal'an le Prophète", objective = "L'Exilé atal'ai des Hinterlands veut la Tête de Jammal'an.", description = "Mes compagnons Witherbark n'apprécient pas beaucoup les étrangers qui rôdent près de chez eux.\n\nMoi ? Je n'ai plus de maison. J'ai été exilé par mon peuple, la grande tribu Atal'ai du marais des Chagrins.\n\nNotre chef spirituel, Jammal'an, avait ce qu'il appelait une prophétie. Il pense que l'invocation du dieu Hakkar apportera l'immortalité à la tribu Atal'ai.\n\nMais j'ai prôné la prudence. Et si cette prophétie n'était rien d'autre que de la manipulation ?\n\nJe veux une revanche pour mon exil. Apportez-moi la tête de Jammal'an. Peut-être qu’ensuite mon peuple retrouvera son libre arbitre.", progress = "Une fois Jammal'an éliminé, j'aurai une chance de retourner chez moi.\n\nTant que Jammal'an reste à leur tête, la tribu Atal'ai court à la destruction.", completion = "La confiance aveugle de Jammal'an en des visions erronées a précipité mon peuple dans une malédiction éternelle.\n\nJe vous remercie, &lt;classe&gt;, pour avoir vengé mon exil. Je pleure cependant mon peuple. Et je n'ai plus de maison vers laquelle retourner.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières de cavalier de la pluieHeaume d'exil\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1447] = {title = "Un diplomate a disparu", objective = "Battre Dashel Stonefist à Stormwind.", description = "Ouais ! De toute évidence, vous n'êtes pas le <classe> le plus malin à venir à Stormwind, mais vous êtes sur le point d'être l'un des plus stupides à n'en jamais repartir.\n\nJe vous ai présenté mes amis ?", progress = nil, completion = "Bien, vous êtes venu me voir pour une raison. De quoi avez-vous besoin ?", rewards = "Vous recevrez :\n\n"},
[1448] = {title = "À la recherche du temple", objective = "Brohann Caskbelly à Stormwind veut que vous recherchiez le temple d'Atal'Hakkar.", description = "Fut un temps, j'étais jeune et plein de vigueur comme vous, <classe>.\n\nMais à présent je suis vieux et incapable d'explorer le monde comme je le faisais autrefois. Ah, les choses que j'ai vues !\n\nMais il reste un mystère qui m'a toujours échappé. Pour ma dernière quête, la Ligue des Explorateurs m'a envoyé chercher le temple d'Atal'Hakkar. La rumeur veut qu'il se trouve dans le marais des Chagrins.\n\nEn raison de mon état fragile, j'ai parcouru les cieux à dos de gryphon, mais je ne l'ai jamais trouvé.\n\nPourriez-vous venir en aide à un vieux nain ? Peut-être aurez-vous plus de chance à pied.", progress = "J'ai parcouru le monde, des jungles d'Azeroth aux pics enneigés de Khaz Modan.\n\nJe n'ai jamais demandé d'aide aux cours de mes aventures. Mais mes vieux os sont fatigués.\n\nRien ne me satisferait davantage que de savoir que j'ai accompli ma dernière quête pour la Ligue des Explorateurs.\n\nSi vous aviez l'extrême amabilité de m'aider dans mes recherches du temple d'Atal'Hakkar, <classe>, j'apprécierais grandement.\n\nParcourez le marais des Chagrins et revenez me voir une fois que vous aurez découvert quelque chose.", completion = "Le temple d'Atal'Hakkar a été englouti sous la surface du Bassin des larmes ? Et il est cerné de rejetons du Vol vert ?\n\nVoilà une découverte ahurissante, &lt;classe&gt; ! Mais de toute évidence, quelque chose s'est extrêmement mal déroulé.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1449] = {title = "Vers les Hinterlands", objective = "Parler au haut-thane Falstad Wildhammer, au Nid-de-l'Aigle des Hinterlands.", description = "Comme j'en ai déjà parlé plus tôt, j'ai moi-même tenté une reconnaissance du temple depuis les airs. Mais en fait, je n'étais pas exactement seul.\n\nJ'ai voyagé sur un gryphon de la fameuse volière du Nid-de-l'Aigle dans les Hinterlands. Là, j’avais acheté les services d’un de leurs meilleurs pilotes. Mais il est tombé de sa monture, et directement dans le marais...\n\nMon vieil âge m'empêche de me souvenir du nom de ce pauvre type. Le maître de la volière devrait s'en souvenir, très certainement.\n\nPartez-y et cherchez Falstad Wildhammer.\n\nNous devons découvrir ce qui est arrivé à ce pilote.", progress = nil, completion = "Que voulez-vous, fiston ? Vous ne voyez pas qu'il y a des problèmes qui requièrent mon attention ici ? Qui a le temps de rester à jacasser avec un &lt;race&gt; ?\n\nIl y a des trolls qui sortent d'un peu partout. Magnez-vous !", rewards = "Vous recevrez :\n\n"},
[1450] = {title = "Le Maître des gryphons Talonaxe", objective = "Parler au Maître des gryphons Talonaxe dans la Volière de Nid-de-l'Aigle", description = "Ainsi, vous êtes un des fameux coursiers au service des vieux schnocks de la Ligue des Explorateurs, hein ?\n\nBien, écoutez-moi, <classe>. Je ne sais pas avec qui votre vieux pote faisait des ronds dans le ciel d’Azeroth. Est-ce que j'ai la tête du Maître des gryphons Talonaxe ? Hein ?\n\nSi vous êtes tellement <intéressé/intéressée> par les aléas du trafic aérien pourquoi n'allez-vous pas lui parler directement ? Si je vous prends à glandouiller dans le coin un peu plus longtemps, je vais vraiment vous faire transpirer.\n\nÀ présent, bougez de là !", progress = nil, completion = "Ah oui ! Bien sûr que je me souviens avoir envoyé l'un de mes chevaucheurs de gryphons donner un coup de main à Brohann Caskbelly.\n\nJ'ai toujours eu une petite faiblesse pour la Ligue des Explorateurs. En fait, mon père faisait partie de la première équipe de fouilles qui a découvert Uldaman.\n\nJ'ai envoyé avec Brohann mon meilleur chevaucheur de gryphons. C'était un type du nom de Rhapsody Shindigger.\n\nEt c'était vraiment un as ! En fait jusqu'à...", rewards = "Vous recevrez :\n\n"},
[1451] = {title = "Rhapsody Shindigger", objective = "Chercher Rhapsody Shindigger dans les Hinterlands.", description = "Rhapsody commençait vraiment à apprécier le goulot. Mais ne vous méprenez pas : tous les nains ici à la volière savent apprécier une bonne bière quand le bon moment arrive.\n\nMais le vieux Shindigger s'est habitué à la boisson comme le jour s'est habitué à la nuit. Quel dommage ! Personne ne savait voler comme lui.\n\nLes premiers signes du problème sont apparus quand il est revenu en titubant de cette mission avec votre pote, Brohann. Tout s'est écroulé peu de temps après. Nous avons dû le laisser partir.\n\nLa dernière fois que j'ai entendu parler de lui, il avait monté un camp de brassage à l'est d'ici...", progress = nil, completion = "Hic ! Je vous regarde en face, mais vous arrêtez pas de danser de haut en bas. Ça me donne le vertige. Ho ho !\n\nHic !\n\nOuah ! Z'avez senti ça ? Le sol b-bouge, mon ami. J'ai besoin d'un verre.\n\nHic !", rewards = "Vous recevrez :\n\n"},
[1452] = {title = "Le Kocktail Kalimdor de Rhapsody", objective = "Rhapsody Shindigger dans les Hinterlands veut que vous lui rameniez 3 Gésiers de roc, 3 Foies de Groddoc et 3 Foies de Ferpoil.", description = "Hic !\n\nAlors c'est ce vieux fou de Brohann qui vous envoie ? Bon sang ! On a eu une de ces aventures… Hic !\n\nSi vous voulez que je vous raconte ce qui s'est passé au marais, je vais avoir besoin de quelque chose de costaud à boire. C'était pas beau à voir, vous comprenez ? Hic !\n\nJe vais vous dire... Apportez-moi de quoi concocter un Kocktail Kalimdor et je vous en parlerai.\n\nJe vais avoir besoin de gésiers de Roc de Tanaris... et voyons... de foies de Groddoc et de Ferpoil de Feralas...\n\nUn bon Kocktail Kalimdor bien costaud... ça m'f'ra causer !", progress = "Vous connaissez la bière au malt Rhapsody ? L'une de mes meilleures bières, si je peux me permettre moi-même de le dire personnellement. Hic !\n\nMais si je dois revivre les horreurs de ce vol fatidique au-dessus du… hic… marais, alors je vais avoir besoin de quelque chose d'un tout petit peu plus fort. Hic !\n\nJe présume que vous n'avez pas trouvé ces gésiers et ces foies dont j'ai besoin pour ajouter ce petit plus à mon Kocktail Kalimdor ?\n\nHic !", completion = "Je vois que vous n'avez pas eu de problèmes pour me dénicher ce dont j'avais besoin ! Vous parlez d'une besogne que vous avez dû faire dans la lointaine Kalimdor.\n\nÇa va me prendre du temps pour extraire la substantifique moelle de ces gésiers et de ces foies.\n\nAlors je pourrai me servir une bonne vieille boisson qui arrache et vous dire enfin c'que vous voulez savoir.\n\nHic !\n\nÇa m'fait trembler rien qu'de repenser à c'vieux marais.\n\nLaissez-moi préparer le bébé en vitesse.", rewards = "Vous recevrez :\n\n"},
[1453] = {title = "Les affaires de Récupérateurs SA en Désolace", objective = "Parler à Kreldig Ungor en Désolace.", description = "Il y a beaucoup de travail à faire en Désolace, <nom>. C'est un endroit atroce, souillé par les centaures et autres monstruosités. Mais si vous voulez un bon petit travail honnête à la semaine, alors allez-y, parlez à Kreldig Ungor, et dites-lui que je vous envoie.\n\nVous le trouverez planqué à la Combe de Nijel, un petit camp plutôt douillet niché dans les montagnes dans la partie nord de Désolace. Allez simplement à l'est si vous venez des Serres-Rocheuses. C'est facile à rater, alors faites attention.", progress = nil, completion = "C'est un plaisir de voir que Récupérateurs SA ne manque pas de travail, ou d'aventuriers voulant aider.\n\nJe me nomme Kreldig, &lt;nom&gt;. Vous avez fait le bon choix en donnant un coup de main à notre entreprise. Tout le monde a besoin d’aide ces jours-ci : untel a perdu un héritage familial, tel autre un objet magique ou un être cher. On ne peut jamais prédire. Mais avec la Récupérateurs SA, chacun devrait pouvoir retrouver ce qu'il a perdu... à condition d'y mettre le prix.", rewards = "Vous recevrez :\n\n"},
[1454] = {title = "L'épave de Karnitol", objective = "Retrouver le Coffre de Karnitol en Désolace.", description = "Ma première commande concerne le mage Karnitol, une sorte de noble de Stormwind. Il semblerait que son bateau ait été attaqué par des géants des mers tandis qu'il naviguait au large de la côte, dans le nord-ouest de Désolace. Ses serviteurs ont essayé de ramener sur la rive l'un de ses coffres les plus précieux, mais lorsque les géants ont attaqué en masse, il a préféré abandonner le coffre et se téléporter, avec ses serviteurs, en sécurité.\n\nIl veut que nous retrouvions le coffre et son contenu, et que nous le lui rapportions à Stormwind.", progress = nil, completion = "Vous remarquez que le coffre ne semble pas avoir subi de dégâts dus à l’eau de mer.\n\nLa deuxième chose que vous notez est que le couvercle du coffre a été forcé et qu'il est ouvert. Quelle que soit la protection magique qui était censée le protéger, elle s'est déclenchée depuis longtemps. Les marques de brûlure sur ses bords en disent long à ce propos.", rewards = "Vous recevrez :\n\n"},
[1455] = {title = "L'épave de Karnitol", objective = "Retourner voir Kreldig Ungor en Désolace.", description = "Vous prenez un moment pour comprendre comment le coffre a été ouvert, et vous remarquez, sur les côtés et le dessus du coffre, de longues et profondes entailles. Elles révèlent que quelque chose d'autre qu'un humain ou qu'un géant s'y est intéressé. Les marques ne semblent être celles d'une épée ou d'une dague.\n\nAprès avoir fouillé le coffre, vous constatez qu'il est complètement vide.\n\nN'ayant plus rien d'autre à faire, vous refermez le coffre et vous préparez à partir. Kredlig va être déçu.", progress = nil, completion = "Soyez de nouveau le bienvenu à la Combe de Nijel, &lt;nom&gt;. Alors, dites-moi ce que vous avez découvert.\n\nQuoi ? Rien ? Ce n'est pas un coffre vide qui va nous payer, j'en ai bien peur. Dites-m'en plus sur les marques que vous avez vues… ces entailles.", rewards = "Vous recevrez :\n\n"},
[1456] = {title = "L'épave de Karnitol", objective = "Retrouver la Sacoche de Karnitol et la rapporter à Kreldig Ungor en Désolace.", description = "Intriguant.\n\nBien, il se peut que tout espoir ne soit pas perdu.\n\nLe long de cette même côte, mais plus au nord, près de l'île de Ranazjar, se trouvent des ruines sous-marines datant des elfes de la nuit. Une tribu de nagas, les Ondulame, s'y est établie ! Je pense que c'est ce notre meilleure chance.\n\nSi un groupe de leurs éclaireurs a été envoyé aussi loin au sud, alors cette tribu doit être puissante. Pour retrouver les possessions de Karnitol, je m’attaquerais en priorité aux nagas les plus forts : les chasse-marées et les sorcières des mers.", progress = "Sans vouloir offenser Nijel, qui qu'il soit, ce camp n'est pas l'endroit le plus confortable pour passer la nuit, si vous voyez ce que je veux dire, <nom>.", completion = "C'est parfait, &lt;nom&gt; ! Vous avez trouvé les possessions de Karnitol !\n\nCes fichus nagas, toujours à créer des problèmes. Je préférerais passer ma vie à faire la guerre à la Horde plutôt que d'avoir à combattre leur race. Vous avez rendu un grand service aux Récupérateurs.", rewards = "Vous recevrez :\n\n"},
[1457] = {title = "L'épave de Karnitol", objective = "Apporter la Sacoche de Karnitol à Roetten Stonehammer à Ironforge.", description = "Rapportez les biens de Karnitol à Roetten à Ironforge, et il vous paiera pour ce travail bien accompli.\n\nHa ! Ha ! Si vous ne faites pas attention, il sera tellement satisfait de vous qu'il vous demandera de nous rejoindre à plein temps.\n\nMais à nouveau, bon travail, <nom>.\n\nSoyez <prudent/prudente> sur le chemin du retour, et ne prenez pas tout votre temps ; Karnitol n'est pas le plus patient des hommes, mais il reste très généreux néanmoins.", progress = "Les affaires sont florissantes, <nom>, et je n'ai pas beaucoup de temps pour les questions. Si vous avez à faire avec Récupérateurs SA, alors parlez. Sinon, adressez-vous à l'un de mes subordonnés. Ils sont suffisamment compétents pour s'occuper des choses ici.", completion = "Ah ! Les petites affaires de Karnitol en Désolace. Excellent !\n\nAinsi, le coffre a été détruit, mais les objets sont tous là, hein ? Bien, je le laisserai juger de cela. L'un des bons aspects de mon travail, c’est que je peux envoyer les clients balader s'ils ne sont pas satisfaits ! Notre boulot, c’est de retrouver leurs trucs perdus, pas de nettoyer ou vérifier le bon état de ce qu’on leur rend.\n\nBon travail, &lt;nom&gt;. On va maintenant songer à ce que vous soyez payé.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes d'HellionEspauliers sanguins\n\nVous recevrez également :\n\n"},
[1458] = {title = "Des réactifs pour les Récupérateurs", objective = "Apporter 10 Griffes de Fielfurie et 10 Cornes de Fielfurie à Kreldig Ungor en Désolace.", description = "L'une de mes tâches ici consiste à collecter des réactifs pour Leftwitch, un mage gnome de Kharanos. Roetten semble penser que c'est de l'argent facilement gagné puisque nous sommes déjà sur place. Il se soucie peu du fait que nous sommes si démunis.\n\nLes premiers objets de sa liste devraient être assez faciles à trouver, et ce sera de l'argent gagné pour quiconque m'aidera.\n\nJ'ai besoin de cornes et de griffes des satyres Fielfurie qui vivent à l'est d'ici. Rapportez-m'en et nous poursuivrons la liste.", progress = "Des créatures immondes, ces satyres. On dit qu'ils sont liés d'une certaine manière aux elfes de la nuit, mais je n’en suis pas certain.\n\nJe pense qu’eux y croient depuis que cet elfe les a menés au combat il y a quelques années. Le monde n'a jamais été le même depuis. Beaucoup plus dangereux, et beaucoup plus effrayant.", completion = "Bien, bien, &lt;nom&gt;. Je ne suis pas vraiment sûr qu'elles soient d'une quelconque qualité, mais si Leftwitch en voulait d'un type particulier, il aurait dû le spécifier avant d'envoyer Récupérateurs SA par ici.\n\nQue diriez-vous de continuer avec notre liste ?", rewards = "Vous recevrez :\n\n"},
[1459] = {title = "Des réactifs pour les Récupérateurs", objective = "Apporter 7 Fioles de venin de scorpashi et 3 Peaux de vieux kodo à Kreldig Ungor, en Désolace.", description = "Ensuite, sur la liste de Leftwitch, on trouve… on trouve… Oh !\n\nRelativement facile, mais il faut décrypter ses directives. Il a besoin de venin de scorpashi et de peau de kodo. Mais il est précisé que le venin doit provenir de n'importe quel scorpashi, et que la peau doit être celle d'un vieux kodo, pas d'un kodo mourant ou d'un ancien kodo.\n\nLes mages, je vous dis pas, les trucs qu'ils veulent parfois... c'est tout simplement bizarre.", progress = "Cela me désole de ne pas avoir pu vous dire où trouver de kodos ou de scorpashis. Ce secteur ne m'est guère familier, et je n'ai pas trouvé le temps de l'explorer.", completion = "Votre soutien ici est une bénédiction, &lt;nom&gt;. Vous divisez au moins par deux le temps que j’ai à passer en Désolace. Avec votre aide, je serai de retour à Ironforge en un rien de temps et je pourrai enfin y réchauffer mes pieds.\n\nUne fois que nous nous serons occupés de cette liste, et que je serai rentré, venez me voir, je vous paierai une bonne bière, ça sera la moindre des choses.\n\nMais en attendant, occupons-nous du reste de ces réactifs.", rewards = "Vous recevrez :\n\n"},
[1462] = {title = "Le sapta de terre", objective = "Parler à la Prophétesse Ravenfeather pour obtenir un autre Sapta de terre.", description = nil, progress = nil, completion = "Prenez ceci et n'oubliez pas qu'un sapta est sacré !", rewards = "Vous recevrez :\n\nSapta de terre"},
[1463] = {title = "Le sapta de terre", objective = "Parler à Canaga Earthcaller pour obtenir un autre Sapta de terre.", description = nil, progress = nil, completion = "Je vous en donne un de bonne foi. Vous avez déjà prouvé votre valeur une fois, mais je pense que vous devriez être plus soigneux à l’avenir.", rewards = "Vous recevrez :\n\nSapta de terre"},
[1464] = {title = "Le sapta de feu", objective = "Parler à Telf Joolam pour obtenir un autre Sapta de feu.", description = nil, progress = nil, completion = "Que le feu brûle dans votre cœur, &lt;nom&gt; !\n\nLes éléments vous attendent.", rewards = "Vous recevrez :\n\nSapta de feu"},
[1465] = {title = "La recherche de Vahlarriel", objective = "Rapporter le Pendentif de Malem à Vahlarriel Demonslayer en Désolace.", description = "Tandis que vous continuez à fouiller le chariot, vous découvrez non seulement un pendentif mais également des traces de pas qui se dirigent vers le sud. Au loin, vous distinguez de la fumée s'élevant d'une grande forteresse. La fumée provient d'un feu entretenu, il ne s'agit pas de bâtiments qui brûlent, et votre instinct vous dit que les Malem, si tant est qu'ils soient toujours en vie, ont été emmenés dans cette direction.\n\nVous estimez que Vahlarriel, à la Combe de Nijel, devrait voir le pendentif et savoir qu'il se trouve des signes de vie au sud.", progress = nil, completion = "Exaspérant ! Fiasco total !\n\nIls savaient tous les deux que c'était dangereux de venir ici. À présent ils ont disparu… ou pire.\n\nVous dites que vous avez vu des empreintes de pas qui se dirigeaient vers un fort proche ? Il se peut que ce soit la meilleure supposition à faire.\n\nD'après les gens du coin, cette forteresse est un repaire de la Lame ardente, des orcs qui s’occupent d’affaires démoniaques. Ils ne sont peut-être pas représentatifs des croyances de la Horde, mais ils sont maléfiques et ils vous tueront s'ils vous prennent à espionner.", rewards = "Vous recevrez :\n\n"},
[1466] = {title = "Des réactifs pour les Récupérateurs", objective = "Apporter 10 Cervelles de gangrechiens, 10 Ailes du Néant et 10 Fioles de Sang de garde funeste à Kreldig Ungor, en Désolace.", description = "Ce sont les derniers objets à rassembler. Cela vous prendra aussi un peu plus de temps que pour les précédents.\n\nBien, assez parlé, commençons. Leftwitch dit qu'il a besoin de : dix cervelles de mange-mana, de chasseur de mage ou de chasseur ley ; dix ailes du néant prélevées sur une vierge du néant, une soeur du néant ou une ensorceleuse du néant. Et... dix fioles de sang de garde funeste provenant d'un capitaine ou seigneur de la garde funeste.\n\nC'est assez simple, non ? Non, sérieusement, si vous laissez tomber cette quête, je comprendrai.", progress = "Je n'ai même pas remarqué que ces choses démoniaques se trouvaient en Désolace. Aux dernières nouvelles, les centaures possédaient plus ou moins la terre après que les elfes de la nuit aient vidé les lieux, il y a des années.\n\nJe me demande pourquoi ils ont pris possession des lieux, et comment.", completion = "Honnêtement ? Je ne l'aurais pas cru possible. Vous êtes incroyable, &lt;nom&gt; ! Combattre des démons pour une simple expérience de mage, et revenir en un seul morceau, c'est un beau début ! Bon travail !\n\nJe vais personnellement vous recommander à Roetten lorsque je rentrerai à Ironforge.", rewards = "Vous recevrez :\n\n"},
[1467] = {title = "Des réactifs pour Récupérateurs SA", objective = "Rapporter la Caisse de Leftwitch à Roetten Stonehammer à Ironforge.", description = "Pour être <payé/payée>, vous devez retourner à Ironforge et parler à Roetten en personne. Il aimera être débarrassé de la caisse de Leftwitch, de toute façon. Remettez-lui simplement ceci et ça devrait suffire pour avoir votre récompense.\n\nEt ne vous en faites pas, je ferai passer un mot positif à votre sujet lorsque je reviendrai. Je ne devrais plus rester longtemps en Désolace.", progress = "Bienvenue, <nom>. Les affaires prospèrent, le son des enclumes frappées résonne dans tout Ironforge, les soufflets nourrissent un feu ardent, et ma femme me prépare une tourte pour le dessert de ce soir. La vie pourrait-elle être plus belle ?", completion = "Ah ! La caisse pour Leftwitch, de Désolace. Excellent. J'apprécie le travail, et votre à-propos, &lt;classe&gt;. Heureux de vous avoir à bord pour au moins ce petit travail.\n\nJ'ai votre paie juste ici. Que Récupérateurs SA reste réputée pour bien payer une bonne semaine de travail !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards d'AuricGantelets flamme-tempête\n\nVous recevrez également :\n\n"},
[1468] = {title = "La Semaine des enfants", objective = "Utilisez le Sifflet d'orphelin humain pour parler à l'enfant que vous protégerez pendant la Semaine des enfants.\n\nObjet fourni : \n", description = "Vous voulez aider l'orphelinat ? Soyez <béni, mon ami/bénie> mon amie;. Votre aide durant la Semaine des enfants sera inestimable.\n\nPrenez ce sifflet. Vous ne pourrez vous en servir que durant sept jours, en fait, pendant toute la Semaine des enfants. Quand vous l'utiliserez, vous pourrez bavarder avec l'enfant que vous avez accepté de surveiller. Si vous l'utilisez une seconde fois, il renverra l'enfant.\n\nJe vous en prie, <nom>, utilisez le sifflet pour faire la connaissance de votre protégé ! Je suis sûre que l'enfant est très impatient de vous rencontrer.", progress = nil, completion = "Euh... salut. Je m'appelle Randis. C'est vous qui vous occupez de moi ? Vous êtes un aventurier, comme l'étaient mon papa et ma maman. C'est chouette de vous rencontrer.\n\nJ'espère qu'on va bien s'amuser tous les deux. Y'a plein de choses que j'aimerais faire, et la gouvernante m'a dit que vous seriez comme mon grand frère cette semaine. C'est super, m'sieu.", rewards = nil},
[1469] = {title = "L'histoire de Rhapsody", objective = "Apporter le Fragment de tablette atal'ai à Brohann Caskbelly à Stormwind.", description = "Avant le vol, je me suis bu un plein tonneau de bière. Hic !\n\nEt ça a été un de ces vols ! Volé de-ci de-là avec Brohann qui me suivait. Mais pas vu de temple en tout cas. Hic !\n\nJe veux dire, j'ai pas vu de temple, jusqu'à ce que je sois trop parti et que je tombe de ma monture. J'ai plongé directement dans la flotte et j’ai été aspiré. Me suis trouvé entouré par un tas de trolls à la mine patibulaire. Vous pensez bien que j'ai nagé très vite pour partir ! J'ai quand même ramassé un souvenir troll. Tenez, apportez ça à Brohann et dites-lui que son temple est là-bas, en bas, de fait. Hic !", progress = "Enfin vous voilà de retour, <nom>. Cela fait longtemps que nous nous sommes parlé. Je pensais que vous aviez oublié ma quête ?\n\nÊtes-vous parvenu à localiser ce chevaucheur de gryphons ? Avait-il quelque chose à dire ?", completion = "Rhapsody Shindigger ! C'est ça… Comment j’ai pu oublier un tel nom ?\n\nAlors il était au courant depuis tout ce temps pour le temple englouti ? Eh bien, cela aurait pu vous épargner de la marche à pied.\n\nMais cet artefact atal'ai ! Quelle trouvaille !", rewards = "Vous recevrez :\n\n"},
[1470] = {title = "Lever le voile", objective = "Apporter 3 Crânes de Cliquethorax à Venya Marthand.", description = "Salutations, enfant. Je peux voir que vous êtes encore novice dans les arts du démoniste, le pouvoir échappant toujours à votre contrôle. Je peux aussi sentir votre désir d'apprendre.\n\nEt vous apprendrez.\n\nLa force ne réside pas dans l'ignorance. La connaissance est notre pouvoir le plus puissant. Par l'application du savoir, nous pouvons contrôler les magies et les êtres chaotiques du vide, et les soumettre à notre volonté.\n\nJe peux vous montrer comment soumettre un servant, mais d'abord vous devez m'apporter trois crânes pris sur les squelettes Cliquethorax qui rôdent près de la forge abandonnée.", progress = "Votre pouvoir n'est guère important aujourd’hui, mais je suspecte déjà que vous imaginez ses possibilités.\n\nMême les morts peuvent se sentir vivants grâce au pouvoir qui coule en nous.", completion = "Bien qu'il vous reste beaucoup à prouver, et beaucoup à apprendre, vous avez montré que vous possédez les compétences nécessaires pour maîtriser l'invocation et la soumission d'un diablotin. Même si ce dernier n'a guère de puissance physique, il possède des pouvoirs et une intelligence qui vous seront bien utiles.\n\nÉcoutez-moi attentivement, &lt;nom&gt;, car je ne répéterai pas cette leçon, et je vous laisserai le soin de la maîtriser.", rewards = "Vous apprendrez :\n\nInvocation d'un diablotin\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un diablotin\n\nVous recevrez également :\n\n"},
[1471] = {title = "Le lien", objective = "Utiliser les Runes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Runes d’invocation à Carendin Halgar, au Temple des Damnés.", description = "Vous avez sûrement vu le cercle d'invocation en dessous. C'est le seul endroit d’où vous pourrez tirer un marcheur du Vide libre.\n\nEn utilisant ces runes, vous pourrez l'attirer ici. Vous devrez alors le dominer par la force des armes et de la magie. Lorsqu'il sera assujetti, il sera lié à vous. Venez alors me voir, et je vous expliquerai le sort d'invocation, pour que vous puissiez vous en servir, pour quelque objectif que ce soit.", progress = "Je m'attends à avoir des échos de votre réussite, <nom>. Ne pas réussir à combler ces attentes serait le dernier de vos soucis si vous échouiez.", completion = "Vous avez bien agi, &lt;nom&gt;. À présent, je vais vous transmettre le sort utilisé pour l'invocation d'un marcheur du Vide.\n\nLa puissance que vous pouvez libérer est à présent sous votre contrôle. Utilisez-la avec sagesse.", rewards = "Vous apprendrez :\n\nInvocation d'un marcheur du Vide\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un marcheur du Vide\n\nVous recevrez également :\n\n"},
[1472] = {title = "La dévoreuse d'âmes", objective = "Parler à Godrick Farsan au Temple des damnés.", description = "Les Sayaads dévorent les âmes, dominent les esprits et séduisent sans distinction. Ce sont des créatures machiavéliques à l’esprit très singulier.\n\nLes légendes, qu’il s’agisse de contes de fées ou de récits cauchemardesques, les désignent toutes par le même nom : succubes pour les femmes, incubes pour les hommes.\n\nCes démons ne viennent dans notre monde qu’en y étant attirés. Face à des cœurs d’êtres bons, purs et aimants, les Sayaads sont incapables de résister. Vous pourrez alors les soumettre et les contrôler à loisir.\n\nParlez à mon assistant, Godrick Farsan, dans le temple. Il vous aidera à trouver un appât.", progress = nil, completion = "Vous avez été envoyé par Carendin, hein ? &lt;nom&gt;, ainsi… Ne croyez pas que la lumière m'a quitté car ma vue est éteinte. À présent, je vois les choses qui se trouvent dans mon dos, avec une clarté que je n'avais jamais connue. Ce que je croyais être une malédiction est tout le contraire.", rewards = "Vous recevrez :\n\n"},
[1473] = {title = "La créature du Vide", objective = "Retrouver le Grimoire d'Egalin et l'apporter à Carendin Halgar au Temple des damnés.", description = "Il semble acquis que vous êtes <prêt/prête> à apprendre à invoquer un marcheur du Vide.\n\nUn être créé par le chaos qui l'entoure. Si vous en invoquez un, mais que vous ne pouvez pas le contrôler, vous serez <annihilé/annihilée>.\n\nLe premier marcheur du Vide a été invoqué par Egalin, et le procédé est expliqué dans son grimoire.\n\nMalheureusement, il nous a été volé par un agent de la Croisade écarlate, qui l'a caché dans sa base, dans une tour de l'ouest. Rapportez-le-moi, et je vous transmettrai cette connaissance.", progress = "Egalin est le maître qui m'a instruit. D'un simple regard fugace, il était capable de commander le marcheur du Vide qu'il avait invoqué.\n\nLorsque ce fut mon tour d'essayer, j'avais trop confiance en moi. Ne badinez pas avec les puissances que vous maniez, <nom>, elles peuvent consumer même le plus vigilant.", completion = "Ah ! Ceci est parfait ! Ce n'était pas le cas pour Perrine. Il était ignorant du pouvoir du livre moisi qu'il nous avait volé.\n\nIl ne quittera plus jamais nos mains. Regardez, &lt;nom&gt;, la structure du sort, la manière dont votre énergie doit être canalisée.", rewards = "Vous recevrez :\n\n"},
[1474] = {title = "Le lien", objective = "Utiliser les Coeurs purs pour invoquer et soumettre une succube, puis rapporter les Coeurs purs à Carendin Halgar, au Temple des Damnés.", description = "Lancez un sort avec ces cœurs au cercle d'invocation. Vous ouvrirez ainsi le chemin à une succube. Vous avez de grands pouvoirs à présent, et vous en aurez besoin pour la soumettre.\n\nAttention à ses charmes, <nom>, beaucoup d'esprits forts ont cédé devant eux. Une fois qu'elle sera battue, la succube retournera au Néant, et je vous apprendrai le sort pour l'invoquer à volonté.", progress = "Parmi les puissances d'au-delà du Néant, la succube est l'une des plus dangereuses, car elle plie à sa volonté le faible.\n\nRappelez-vous-en aujourd’hui, et demain...", completion = "A nouveau, vous avez accompli votre quête, &lt;nom&gt;. Cela fait longtemps que je n'ai vu un si jeune &lt;classe&gt; doué d'un tel potentiel. Soyez certain que je suivrai votre progression. Je continuerai également à vous préparer et à vous aider dans vos épreuves futures.\n\nMais pour l'heure, laissez-moi vous montrer un nouveau sort d'invocation pour votre toute nouvelle succube dominée.", rewards = "Vous apprendrez :\n\nInvocation d'une succube\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'une succube\n\nVous recevrez également :\n\nPetite bourse d'âme"},
[1475] = {title = "Dans le temple d'Atal'Hakkar", objective = "Rassembler 10 Tablettes atal'ai pour Brohann Caskbelly à Stormwind.", description = "D'après la légende, le temple d'Atal'Hakkar est un lieu saint dédié au dieu ancien, Hakkar l'Ecorcheur d'âmes. Habité par une ignoble tribu de trolls, les Atal'ai, on dit qu'il est impossible d'y entrer.\n\nCe temple est à présent sous les eaux du Bassin des larmes, et récupérer les artefacts sera d'autant plus difficile. Mais c'est pourtant ce que j'ai besoin que vous fassiez, <nom>.\n\nAidez-moi, en récupérant les Tablettes atal'ai intactes. Apportez-les-moi, et je deviendrai un héros aux yeux de la Ligue des Explorateurs. Nous partagerons ensemble cette gloire.", progress = "Alors que le crépuscule tombe doucement sur ma carrière, je me tourne vers vous, <nom>, pour m'aider dans ma dernière quête au service de la Ligue des Explorateurs. Si mes vieux os pouvaient rassembler la résistance nécessaire pour braver le marais des Chagrins et le temple englouti, je me battrais à vos côtés.\n\nLa fierté fait qu'il m'est difficile de vous demander de l'aide pour récupérer les tablettes atal'ai. Mais mon grand âge rend cette demande nécessaire cependant.\n\nS'il vous plaît, aidez-moi, <nom>. Je veux me retirer de la Ligue des Explorateurs en ayant accompli sa dernière demande.", completion = "Les tablettes atal'ai ! Merci, &lt;nom&gt; ! \n\nUne fois que je les aurai remises à la Ligue des Explorateurs, nos noms seront gravés côte à côte dans l'histoire. Vous avez aidé un vieux nain à remplir son dernier devoir dans la vie. Je vous en suis éternellement reconnaissant.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTalisman de gardien"},
[1476] = {title = "Des cœurs purs", objective = "Apportez les Cœurs de Dalin Forgewright et de Corma Villard à Carendin Halgar dans le Temple des Damnés.", description = "Forcer une succube à apparaître nécessite des cœurs purs. Mais existent-ils seulement ?\n\nGrâce à quelques fragments d’histoires entendues par-ci par-là, je suis parvenu à trouver deux êtres humains qui devraient faire l’affaire.\n\nLe premier se nomme Dalin Forgewright. Il a consacré sa vie aux réfugiés de Lordaeron, ceux qui sont rejetés par leurs pairs au mur de Greymane.\n\nL’autre s’appelle Corma Villard, une femme restée fidèle à son premier amour et qui arpente les Paluns à sa recherche.\n\nRemettez leurs cœurs à Carendin. Mais auparavant, laissez-moi vous montrer votre cible.", progress = "J'ai été jusqu'à présent agréablement surpris par la vitesse de vos progrès, <nom>. Apportez-moi les cœurs et vous me surprendrez une fois encore.", completion = "Le cœur d'un homme bon ressemble au cœur de n'importe quel homme, lorsque vous le voyez ainsi, vous ne trouvez pas ?\n\nPeut-être avons-nous une… vision légèrement… différente sur le sujet.\n\nÇa fera l'affaire. Je suis certain qu'une succube sera attirée par leur pureté.", rewards = "Vous recevrez :\n\n"},
[1477] = {title = "Fournitures vitales", objective = "Parler au Maître de guet Sorigal.", description = "Les mages conduisent des recherches au Rempart-du-Néant dans les Terres foudroyées, des recherches vitales à notre compréhension des Portes des ténèbres. Ils ont besoin presque constamment de marchandises, mais notre ligne d'approvisionnement vers Rempart-du-Néant est fragile.\n\nVous devez vous assurer que les provisions parviennent bien au Rempart-du-Néant. Allez voir le maître de guet Sorigal à Darkshire, et faites ce qu'il demande. Cette quête vous conduira dans des terres hostiles, <nom>. Soyez <prêt/prête>.", progress = nil, completion = "Andromath vous a envoyé ? Très bien. J'ai une quête importante à vous confier.", rewards = "Vous recevrez :\n\n"},
[1478] = {title = "Les invocations de Halgar", objective = "Parler à Carendin Halgar à Undercity.", description = "Ah, <nom> ! Je viens juste de recevoir un mot de Carendin Halgar disant qu'il voulait vous voir pour continuer l'entraînement.\n\nVous devriez être <fier/fière> de vous, <nom>. Ce n'est pas tous les jours que Maître Halgar daigne instruire personnellement un jeune démoniste.\n\nVous le trouverez dans le Quartier de la magie à Undercity, près du Temple des damnés.", progress = nil, completion = "Bien, je vois qu'Ageron a réussi à vous trouver, &lt;nom&gt;. Ne perdons pas un temps précieux en politesses futiles et en propos sans intérêt. Concentrons-nous sur votre entraînement. Vous avez encore beaucoup à apprendre.", rewards = "Vous recevrez :\n\n"},
[1479] = {title = "Le Rameau des Éternels", objective = "Conduire l'orphelin à la banque de Darnassus. La banque est creusée dans le tronc d'un arbre connu sous le nom du Rameau des Éternels.", description = "J'ai entendu parler d'histoire sur les elfes de la nuit, qui ont leur banque dans un arbre, mais qui ressemble à un ours ! C'est génial ! C'est chouette, il paraît que les elfes de la nuit aiment la nature et ce genre de choses. Et les ours, c'est trop terrible !\n\nVous voulez bien m'emmener voir l'arbre-ours à Darnassus, s'il-vous-plaît ? Y'a un bateau qui peut nous amener juste à côté, ça ne devrait pas prendre trop de temps. S'il vous plaaaaaaaaaaaît !", progress = nil, completion = "Ouah, c'était encore plus terrible que je l'avais imaginé, le Rameau des Éternels ! Je ne pensais pas qu'il était si gros que ça ! Vous avez vu l'oiseau tout en haut ? Je me demande comment ils font pour que les branches soient aussi jolies !\n\nMerci de m'avoir emmené à Darnassus, &lt;nom&gt;. Vous êtes géniale !", rewards = "Vous recevrez :\n\n"},
[1480] = {title = "Le corrupteur", objective = "Apporter une Peau de démon écorché à Maurin Bonesplitter en Désolace.", description = "La peau déchirée sent le pourri. Malgré son aspect sec et fragile, elle est remarquablement souple.\n\nEn la déroulant, vous voyez clairement une sorte de langage écrit en rouge sur l'un des côtés. Un symbole est apposé en évidence en bas de la peau ; vous supposez qu’il s’agit d’une signature.\n\nPeut-être Maurin pourrait-il vous en dire plus ?", progress = "Les membres de la Lame ardente commencent à réaliser à quel point ils sont faibles. Leurs magies sont pathétiques et leurs forces frêles.\n\nLeur seule puissance vient de ceux qu'ils servent et non de la possession de quelque pouvoir ou connaissance.", completion = "Hmmm, ces runes composent effectivement un langage, &lt;nom&gt;, un vieux langage. Elles me font penser à celui d'Eredun, mais avec des différences importantes. Si je ne m'abuse, il s'agit là d'une sorte de contrat… Oui, regardez, ce symbole est la signature du démon, un certain \"seigneur Azrethoc\".", rewards = "Vous recevrez :\n\n"},
[1481] = {title = "Le corrupteur", objective = "Apporter un Scalp de Traqueur des ténèbres à Maurin Bonesplitter en Désolace.", description = "Je pense pouvoir trouver ce démon si j'ai les réactifs adéquats.\n\nS'il est effectivement aussi puissant que je le suspecte, je vais avoir besoin de certains objets disponibles sur des créatures mortelles. Mais vous agissez au nom du Chef de guerre, aussi je suis certain que vous accepterez ma quête.\n\nD'abord, je vais devoir briser toutes les protections qu'il aurait contre les visions. Pour cela, j'aurais besoin d'un scalp de satyre. Mais pas de n'importe quel satyre. Il doit provenir d'un Traqueur des ténèbres Fielfurie.\n\nCherchez cette tribu dans les ruines anciennes au nord-est de Désolace.", progress = "Ne m'apportez pas n'importe quel scalp, <classe>. Utiliser les mauvais réactifs pourrait causer notre mort. Le seigneur démon pourrait être protégé par des sorts de secours qui tuent quiconque essaie de le scruter.\n\nLe destin m'a déjà infligé suffisamment de douleur.", completion = "Les Traqueurs des ténèbres n’ont pas réussi à vous tuer, &lt;classe&gt;. Impressionnant… très impressionnant.\n\nCe scalp fera parfaitement l'affaire pour mon sort. Pendant que vous étiez parti, j'ai pu réunir d’autres réactifs nécessaires au sort.\n\nJe suis presque prêt. J'ai juste besoin d'un focalisateur pour ce sort, quelque chose dans lequel projeter une image du démon et de l'endroit où il se trouve.", rewards = "Vous recevrez :\n\n"},
[1482] = {title = "Le corrupteur", objective = "Apporter un Cristal d'oracle à Maurin Bonesplitter, en Désolace.", description = "Un cristal d'oracle ferait parfaitement l'affaire. Ils sont conçus par les nagas et utilisés par leurs oracles.\n\nAu nord-ouest d'ici, le long de la côte, se trouve un vaste récif de corail que les nagas considèrent comme leur demeure, lorsqu'ils viennent près du rivage. Vous trouverez leurs oracles là-bas. Les Ondulames sont dangereux et ne réagiront pas amicalement à votre intrusion : soyez <prudent/prudente> et hâtez-vous.\n\nQuand vous reviendrez, nous verrons à localiser le seigneur-démon Azrethoc.", progress = "Je suis prêt à recevoir ce cristal d'oracle, <classe>. Débusquer et tuer ce seigneur Azrethoc nous permettrait à tous les deux de gagner la faveur du chef de guerre. Nous ferions bien de travailler ensemble, et de travailler vite, pour prétendre à de plus hauts buts, et pour obtenir ses faveurs.", completion = "Ah, l'un de ces précieux cristaux d'oracle… parfait… merveilleux.\n\nNous allons commencer immédiatement. Trouver ce seigneur démon devrait être notre principal souci, et son élimination nécessite toute notre attention.\n\nReculez, &lt;classe&gt;... Voyons la nature de ce démon, et l'endroit où il se terre.", rewards = "Vous recevrez :\n\n"},
[1483] = {title = "Ziz Fizziks", objective = "Parler à Ziz Fizziks dans la Combe des Cisailles.", description = "La KapitalRisk a détourné un grand nombre de savants gobelins, mais de temps en temps, nous avons l’occasion de les leur reprendre.\n\nIl y a quelque temps, l'équipe de la KapitalRisk des Serres-Rocheuses a embauché Gerenzo Wrenchwhistle. Un gnome ! Leur autre ingénieur, Ziz Fizziks, en a été tellement dégoûté qu'il a essayé de trouver un nouveau travail auprès du Syndicat des Artisans. Je lui ai confié quelques travaux à faire, mais il a peut-être besoin de renfort.\n\nPeut-être que vous pourriez voir ça pour moi ? On peut le trouver à la lisière ouest de la combe des Cisailles.", progress = nil, completion = "Et moi qui pensais que les gradés de la KapitalRisk étaient des esclavagistes ! Mais là j'ai rencontré Sputtervalve, le plus cruel de tous !\n\nHa ! Mais c'est mieux que de se retrouver sans travail, je suppose… ou même pire, que de travailler avec ce Gerenzo. Si vous êtes là pour donner un coup de main, j'ai quelque chose pour vous.", rewards = "Vous recevrez :\n\n"},
[1484] = {title = "Le corrupteur", objective = "Parler à Takata Steelblade en Désolace.", description = "Cette créature est beaucoup plus dangereuse que je ne l'avais cru. Il est certain que Takata remet en cause mes capacités à battre une telle créature, et ce serait insulter son honneur que de ne pas l'informer de ce qui vient juste de se passer.\n\nParlez à l'homme d'épée, dites-lui que vous voulez tuer le démon s'il l’autorise, mais n'insistez pas trop. Ce serait mieux qu'il croit que c'est son idée.", progress = nil, completion = "J'ai été témoin de ce qui s'est passé entre Maurin et le seigneur-démon. Cette créature, même en tant que simple apparition, semble avoir plus de pouvoir que mon compagnon démoniste. Je me demande s'il est vraiment à la hauteur pour battre ce monstre… Il serait mieux, pour le Chef de guerre, que je m'en occupe en personne. Mais avec toutes mes responsabilités ici, cela risquerait de disgracier mon clan si je tournais le dos à mes devoirs pour aller me couvrir d'honneurs personnels en combattant ce démon.", rewards = "Vous recevrez :\n\n"},
[1485] = {title = "Les vils quasits", objective = "Apporter 6 Têtes de vils quasits à Ruzan.", description = "Ces démonistes qui sont passés avant nous ont engendré la méfiance parmi la Horde, et bien que nous soyons tolérés, nous ne sommes pas aimés.\n\nCela n'a pas poussé les démonistes à s’unir pour autant, et beaucoup choisissent de vivre reclus, marinant seuls dans leur magie. Je ne vais pas tenter de vous faire choisir un chemin ou l'autre, mais seulement vous aider pendant votre progression.\n\nAvant que je vous apprenne l'art de l'Invocation, apportez-moi six têtes de vils quasits. Vous en trouverez dans la grotte au nord-est.", progress = "Il est important que vous puissiez contrôler les êtres que vous invoquez par la magie. Les étudiants intéressés par les techniques des démonistes sont si rares que je ne risquerai pas votre vie en vous apprenant quoi que ce soit avant que vous ne soyez prêt.", completion = "Tout au long de votre apprentissage de &lt;classe&gt;, vous apprendrez à invoquer des êtres de toutes sortes. Bien que certains ne paraissent pas utiles, tous peuvent se révéler précieux.\n\nNe vous laissez pas abuser par la petite taille du diablotin. Comme vous l'avez sans aucun doute constaté, il reste un adversaire formidable.", rewards = "Vous apprendrez :\n\nInvocation d'un diablotin\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un diablotin\n\nVous recevrez également :\n\n"},
[1486] = {title = "Les peaux communes", objective = "Napalk dans les Cavernes des lamentations veut 20 Peaux communes.", description = "Tandis que Naralex s'enfonçait toujours plus profondément dans son cauchemar, des bêtes étranges émergèrent de sous les Tarides, jusqu'aux Cavernes des lamentations.\n\nCes créatures perverties possèdent des propriétés étranges, comme venues d'un autre monde. Bien qu'elles soient maléfiques de nature, je pense qu’il y a des avantages à tirer de leur présence ici. Leur peau peut certainement être travaillée.\n\nSi vous vous considérez à la hauteur, partez dans les cavernes, en dessous, et trouvez des écailles communes.", progress = "Je suis très intéressé à l'idée d'examiner la peau des créatures perverties qui ont envahi ces cavernes. Avez-vous eu la chance d'en trouver, <classe> ?", completion = "Nous apprécions vos efforts pour avoir rassemblé ces peaux, &lt;nom&gt;.\n\nMerci pour votre engagement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières luisantes de déviantSac en peau de déviant\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1487] = {title = "L'éradication des Déviants", objective = "Ebru, des Cavernes des lamentations, veut que vous tuiez 7 Ravageurs Déviant, 7 Vipères Déviant, 7 Glacials Déviant et 7 Crocs-d'effroi Déviant.", description = "Naralex poursuivait un noble but.\n\nNotre grand chef aspirait à entrer dans le Rêve d'émeraude pour faire reverdir ces terres arides, qui étaient autrefois une forêt luxuriante. Mais quelque chose s'est mal passé.\n\nLe rêve de Naralex s'est transformé en cauchemar et des créatures perverties ont commencé à envahir les cavernes.\n\nDes Disciples de Naralex tentent de le réveiller, mais mon souci est de débarrasser les cavernes de ces bêtes maléfiques.\n\nBravez les cavernes, <nom>, et éradiquez cette vermine étrangère.", progress = nil, completion = "En tant que Disciple de Naralex, je fais l'éloge de votre courage, &lt;nom&gt;.\n\nLe nettoyage de ces cavernes est un premier pas dans notre long combat pour voir revivre les Tarides.\n\nMerci et puissiez-vous prospérer !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPatron : Ceinture en écailles de déviantBâton ardentGantelets de Dagmire\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1488] = {title = "Le corrupteur", objective = "Tuer le seigneur Azrethoc et Jugkar Grim'rod puis retourner voir Takata Steelblade en Désolace.", description = "Bien que je ne sache rien de ce seigneur Azrethoc, je suis d'accord avec Maurin. Il faut l'arrêter, surtout s'il tente de gagner du pouvoir au sein de la Lame ardente pour faire avancer ses objectifs.\n\nVous nous avez déjà exprimé votre souhait d’aider le Chef de guerre, et j'aimerais vous charger de réunir un groupe pour aller tuer ce seigneur-démon et son serviteur démoniste.\n\nLorsque vous serez <prêt/prête>, partez pour le sud, et revenez me voir lorsque ce danger sera éliminé.", progress = nil, completion = "Voilà une grande victoire pour chacun d'entre nous, &lt;nom&gt;. Réjouissons-nous de votre réussite. Je crois qu'à présent, notre avenir ici n'est pas aussi morne que prévu.\n\nLes démons seront massacrés, la Lame ardente échouera dans ses tentatives, et nous aurons un jour un endroit que nous pourrons à nouveau appeler « foyer ».", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTarge de basalteEspauliers de massacreur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1489] = {title = "Hamuul Runetotem", objective = "Parler à Hamuul Runetotem.", description = "Les carapaces que vous m'avez apportées portent une souillure que je n'ai jamais vue auparavant. Je pense que l'eau des oasis en est la cause, et je peux ressentir le désordre qu'ils causent à cette terre. C'est comme si la terre rêvait et ne pouvait s'éveiller.\n\nLes Cavernes des lamentations doivent être à l’origine de cette souillure. Mais avant de vous y rendre, allez parler à Hamuul Runetotem, le druide ancien. Je lui ai envoyé un message décrivant les événements dans les Tarides. C'est un sage, et il peut vous donner de bons conseils.\n\nVous le trouverez à Thunder Bluff, sur la Cime des Anciens.", progress = nil, completion = "Vous avez mes salutations, &lt;nom&gt;. Vous êtes le bienvenu ici, et je suggère que vous rassembliez vos forces. Car la tâche que nous plaçons devant vous… est terriblement difficile.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1490] = {title = "Nara Wildmane", objective = "Parler à Nara Wildmane.", description = "J'ai pénétré sur la terre des rêves et j’ai vu un groupe de druides dans les Cavernes des lamentations. J'ai vu qu’autrefois leurs buts étaient nobles, mais qu'ils ont perdu le chemin depuis. Ils sont à présent serviteurs de la souillure qui sourd dans les Tarides.\n\nJe ne suis plus jeune et les forces me manquent. Je ne pourrai pas rester plus longtemps sur cette terre des rêves pour en apprendre davantage sur ces druides souillés. Mais Nara est jeune et son esprit est féroce. Elle est restée à rêver tandis que je me retirais.\n\nParlez-lui. Elle est dans la tente, là-bas.", progress = nil, completion = "Oui, c'est vrai ! J'ai connaissance de ces druides dans les Cavernes des lamentations. J'ai vu leurs visages tordus et écailleux. Je connais leurs crimes et je connais leurs plans.\n\nVous devez les arrêter, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1491] = {title = "Les potions d'intelligence", objective = "Apporter 6 doses d'Essence de lamentation à Mebok Mizzyrix, à Ratchet.", description = "Ainsi les cornes de raptors n'ont pas si bien marché que cela ! Mais ce n'est pas grave, personne ne devient riche au premier essai ! Et de plus, je pense avoir trouvé encore mieux pour mes potions d'intelligence !\n\nIl existe une substance appelée essence de lamentation, qui est sûrement responsable de l’état de certaines plantes et bêtes des Tarides. Trouvez-en, et je l'essaierai dans mes boissons !\n\nJ'ai entendu dire que cette essence apparaît sur des créatures à l'état d'ectoplasme vivant dans les Cavernes des lamentations, à l'ouest. Chassez ces créatures et récupérez l'essence.", progress = "Où est mon Essence de lamentation ?", completion = "Parfait, vous l'avez ! Je suis très impatient de la tester. Elle va faire de moi un homme riche, j'en suis sûr !\n\nMerci, &lt;nom&gt;. Prenez ceci, et quand je serai riche, je vous en enverrai encore plus, je vous le promets.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1492] = {title = "Maître des quais Dizzywig", objective = "Apporter la Caisse sûre au Maître des quais Dizzywig à Ratchet.", description = "J'ai besoin d'envoyer une caisse de potions, de réactifs et d’objets divers à mes associés dans l'Ancien Monde. J'ai en fait assez peu de temps et je ne peux pas vérifier moi-même qu'elle est bien embarquée aux docks de Ratchet. De plus, la dernière caravane est déjà partie.\n\nSi vous pouvez, apportez-la au Maître des quais Dizzywig. Il veillera à ce qu'elle soit chargée sur le prochain bateau en partance pour la crique des Flots noirs.", progress = "Vous voulez prendre place sur le prochain bateau ou y placer quelque chose à envoyer ?", completion = "Une caisse assez petite. Oui, je devrais trouver un peu de place à bord pour l'embarquer. Elle part à la prochaine marée, je suppose que c'est suffisamment tôt ? Parfait. Laissez-moi juste l’inscrire dans mes registres.\n\nVoilà ! Je vous souhaite le bonjour, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[1498] = {title = "La voie de la défense", objective = "Apporter 5 Ecailles roussies à Uzzek au Poste de garde extérieur dans les Tarides.", description = "En tant que guerrier, l'une de nos tâches les plus cruciales est… la protection. Nous sommes le bouclier de la Horde, et nous gardons nos semblables les plus faibles à l'arrière. Si vous voulez rejoindre nos rangs, alors vous devez me prouver votre ardeur.\n\nPartez pour les falaises du Tonnerre en Durotar, où vivent les foudroyants et les lézards-tonnerre. Chassez ces bêtes ! Montrez-moi que vous êtes plus <fort/forte> qu'eux ! Affrontez leurs assauts et apportez-moi un tas d'écailles roussies comme preuve.\n\nFaites cela, et alors je deviendrai votre maître.", progress = "Avez-vous ces écailles, <nom> ? Si vous ne pouvez pas supporter les attaques des lézards-tonnerre, vous ne bénéficierez pas de mon instruction.", completion = "Ah ! Je vois que vous avez battu les lézards-tonnerre, ce qui prouve que vous êtes robuste. À présent je vais vous montrer comment une peau résistante et d'habiles mouvements peuvent se combiner pour former un mur de défense impénétrable.\n\nApprenez bien votre leçon, &lt;nom&gt;, et tenez-vous prêt pour d'autres.", rewards = "Vous allez être la cible du sort suivant :\n\nVoie de Protecteur\n\nVous recevrez :\n\n"},
[1499] = {title = "Les vils quasits", objective = "Parler à Zureetha Fargaze.", description = "Zureetha envoie des novices comme vous réduire le nombre des créatures de la caverne près de laquelle vous avez combattu les vils quasits.\n\nJe pense qu'il serait bon pour vous de l'aider et ainsi de gagner de l'expérience. Dites-lui également que vous avez participé à la résolution du problème posé par ces diablotins, elle aura probablement une récompense pour vous.", progress = nil, completion = "Vous avez bien agi, &lt;nom&gt;.\n\nLes vils quasits ne sont que des marionnettes dirigées par des puissances agissant au sein de la Lame ardente, mais votre succès en présage de plus grands à l'avenir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de main primitiveBâton de marche primitif\n\nVous recevrez également :\n\n"},
[1500] = {title = "Le réveil de Naralex", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1501] = {title = "La créature du Vide", objective = "Récupérer la Tablette de Verga pour Gan'rul Bloodeye à Orgrimmar.", description = "Il reste si peu de démonistes… Nous risquons beaucoup, mais cela en vaut la peine. Vous devez rapidement atteindre la pleine possession de vos capacités pour être utile à la Horde et au Chef de guerre.\n\nIl est temps pour vous d'apprendre un nouveau sort d'invocation.\n\nD'abord, vous devez récupérer la Tablette de Verga, qui a été volée par des démonistes de la Lame ardente et qui est à présent détenue dans leur antre du Rocher du crâne à l'est de la ville. Une fois que j'aurai la tablette, je vous montrerai les runes nécessaires à l'invocation d'un marcheur du Vide.", progress = "Avez-vous la Tablette de Verga, <nom> ? Sinon, je ne souhaite plus vous parler jusqu'à ce que vous l'ayez.", completion = "Bien ! J'espère que vous avez infligé des pertes à la Lame ardente quand vous êtes allé la récupérer.\n\nIls sont une source de grands problèmes pour le Chef de guerre et une véritable plaie pour tous les démonistes.", rewards = "Vous recevrez :\n\n"},
[1502] = {title = "Thun'grim Firegaze", objective = "Parler à Thun'grim Firegaze dans les Tarides.", description = "Il est vital que l'arme d'un guerrier soit de qualité. Et s'il y a bien un orc capable de concevoir des armes de qualité, c’est Thun'grim Firegaze. C'est un ermite qui vit au sommet des collines à l'est de la Croisée.\n\nSi vous cherchez une arme, <guerrier/guerrière>, alors cherchez Thun'grim. Pour le trouver, voyagez d'abord vers la Croisée, vers l'ouest. Puis tirez droit à l'est, dans les collines. Son camp est au sommet d'une d'entre elles.", progress = nil, completion = "Mes yeux se sont depuis longtemps desséchés à force de fixer les flammes de la forge, mais il y a certaines choses que je peux encore voir.\n\nEt si vous avez trouvé votre chemin jusqu'ici, je peux deviner la nature de votre demande.", rewards = "Vous recevrez :\n\n"},
[1503] = {title = "Acier forgé", objective = "Apporter les Barres d'Acier forgé à Thun'grim Firegaze dans les Tarides.", description = "Je vais vous donner une arme, <nom>, mais d'abord vous devez me venir en aide. Les Tranchecrins du nord-ouest sont venus dans mon camp il y a plusieurs nuits. Ils ne venaient pas m’affronter, mais ils savaient que ma vue est mauvaise. Quelques-uns m'ont distrait, en grognant, tandis que les autres me dévalisaient ! Les lâches !\n\nIls ont emporté un coffre de fer contenant des barres d'acier forgé. Si vous pouvez les récupérer, alors je vous donnerai l'arme idéale.\n\nTrouvez le coffre en fer dans le camp des hurans et rapportez-moi les barres d'acier forgé.", progress = "Avez-vous mes barres d'acier ?", completion = "Vous les avez trouvées ! Et elles sont toutes là, ce qui ne me surprend pas. Je pensais bien que les Tranchecrins ne sauraient pas quoi en faire.\n\nMerci, &lt;nom&gt;. Voici votre récompense. Puisse-t-elle bien vous servir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de Thun'grimMasse de Thun'grimDague de Thun'grimEpée de Thun'grim\n\nVous recevrez également :\n\n"},
[1504] = {title = "Le lien", objective = "Utiliser les Glyphes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Glyphes d'invocation à Gan'rul Bloodeye, à Orgrimmar.", description = "À présent, observez la Tablette de Verga, car elle contient les glyphes nécessaires à l'invocation. Apportez-les au cercle sous la tente de Neeru Fireblade de l'autre côté de la grotte. Vous serez alors capable d'invoquer un marcheur du Vide.\n\nVous devez le battre en utilisant tous les moyens physiques et magiques que vous avez à votre disposition. Une fois qu'il sera battu, revenez me voir avec les glyphes d'invocation et je vous apprendrai comment soumettre la créature.", progress = "Le marcheur du Vide est une puissante créature. Je me souviens du temps où j'étais à votre place, <nom>. Les années passant, mon propre marcheur du Vide a commencé à être moins ardent dans ses combats contre moi. Mais je soupçonne que c'est simplement parce qu'il espère ainsi que je baisserai ma garde.\n\nN’oubliez jamais cela, <nom>.", completion = "Vous avez réussi, &lt;nom&gt;. Je vais maintenant vous montrer comment invoquer un marcheur du Vide semblable à celui que vous venez de battre.\n\nVous savez certainement que nous nourrissons de grandes espérances vous concernant, et pour l'instant, vous ne nous avez pas déçus. Ne laissez pas cela vous monter à la tête non plus, sachant que les tâches qui vous restent à accomplir feront passer celle que vous venez de remplir pour une promenade de santé.", rewards = "Vous apprendrez :\n\nInvocation d'un marcheur du Vide\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un marcheur du Vide\n\nVous recevrez également :\n\n"},
[1505] = {title = "Le vétéran Uzzek", objective = "Parler à Uzzek au Poste de garde extérieur.", description = "La Horde honore ses guerriers, car leur force n'est pas remise en question. Mais les grands guerriers sont également de grands étudiants.\n\nCherchez Uzzek. C'est le vétéran de maintes batailles et il enseigne à présent l'art du combat à de jeunes guerriers. Vous le trouverez au sud du Poste de garde extérieur, la garnison orc à la frontière entre les Tarides et Durotar à l'est.", progress = nil, completion = "Salutations, jeune homme. Vous êtes ici pour quelques cours, c'est ça ?", rewards = "Vous recevrez :\n\n"},
[1506] = {title = "Les invocations de Gan'rul", objective = "Parler à Gan'rul Bloodeye à Orgrimmar.", description = "Vous là ! <nom>, c'est ça ?\n\nJ'espère que votre programme n'est pas trop chargé, car Gan'rul veut vous voir tout de suite. Vous le trouverez avec les démonistes seniors à la Faille de l'ombre.\n\nD'après mes souvenirs de Gan'rul, le fait qu'il vous appelle est soit une très bonne chose, soit une très mauvaise.", progress = nil, completion = "Bien. J'ai eu peur qu'Ophek ne vous trouve pas.\n\nIl est temps que j'approfondisse votre apprentissage de &lt;classe&gt;. Quelles que soient les affaires que vous avez en cours, elles attendront.\n\nJe suppose que ça ne pose pas de problème ?", rewards = "Vous recevrez :\n\n"},
[1507] = {title = "La dévoreuse d'âmes", objective = "Parlez à Cazul à la Faille de l'ombre.", description = "Il est temps pour vous d’en apprendre plus sur la magie d’invocation. Vous allez apprendre à invoquer un Sayaad, une créature dotée de pouvoirs mentaux incroyables. Ce démon peut apaiser les esprits faibles jusqu’à ce qu’ils tombent en son pouvoir. Mais ne craignez rien ! Je sais que vous êtes capable de relever le défi.\n\nLes Sayaads peuvent être invoqués à la condition de les appâter avec un objet représentant l’amour et la dévotion.\n\nUne suggestion ? Parlez à Cazul… Il semble qu’il n’y ait pas grand-chose que le vieux démoniste ignore.", progress = nil, completion = "Hmmm… &lt;nom&gt;. Vous êtes encore novice, mais je ressens de très grandes possibilités en vous.\n\nVous êtes né avec de nombreux talents, &lt;nom&gt;. Veillez à ne pas les gâcher.", rewards = "Vous recevrez :\n\n"},
[1508] = {title = "Cazul l'aveugle", objective = "Parler à Zankaja à Orgrimmar.", description = "Si Gan’rul vous envoie, ce doit être parce que vous devez invoquer une succube, une femelle de l’espèce des Sayaads, et qu’il vous faut de quoi la séduire.\n\nHmm… si vous acceptez de faire confiance à un aveugle, <nom>, alors écoutez-moi. Zankaja vit à l’ouest de la tour des Cavaliers célestes, dans les hauteurs d’Orgrimmar. Elle attend le retour de son compagnon.\n\nAllez la voir.", progress = nil, completion = "Êtes-vous venu m'apporter des nouvelles de Dogran ? Il était censé revenir il y a plusieurs jours, mais je n'ai pas de nouvelles…", rewards = "Vous recevrez :\n\n"},
[1509] = {title = "Des nouvelles de Dogran", objective = "Parler à Gazrog à la Croisée.", description = "Mon compagnon, Dogran, a été récemment envoyé à la Croisée pour y accomplir son devoir. Il avait obtenu une promotion, et il était très fier.\n\nMoi, j'étais triste, mais je n'en ai rien laissé paraître. Et j'étais inquiète, aussi. Les Tarides sont une région bien plus dangereuse qu'Orgrimmar, et je craignais le pire.\n\nÀ présent, cela fait une semaine qu'il aurait dû renter, et je n'ai toujours reçu aucune nouvelle...\n\nPeut-être pourriez-vous vous rendre à la Croisée et voir s'ils ont des nouvelles de lui ? Il travaillait avec Gazrog, qui devrait toujours y être assigné.", progress = nil, completion = "Zankaja ? La compagne de ce Dogran, c'est ça ?\n\nOui, j'ai entendu parler de lui, mais ce ne sont pas de bonnes nouvelles…\n\nNon, il n'est pas mort. Mais il est blessé et prisonnier des hurans.", rewards = "Vous recevrez :\n\n"},
[1510] = {title = "Des nouvelles de Dogran", objective = "Parler à Ken'zigla, au village de Malaka'jin.", description = "Il était en poste au Camp Taurajo, où nous essayions de nous débarrasser des hurans. Il a dirigé quelques grunts sur l'un de leurs campements, mais il a été alors grièvement blessé. Les autres sont revenus et ont essayé de lui porter secours. Mais il allait très mal, ses blessures saignaient et ils hésitaient à le déplacer avant de le panser correctement.\n\nIls ont envoyé un message ici, demandant un breuvage de soin des trolls de Malaka'jin, au pied des Serres-Rocheuses. Nous avons envoyé quelqu'un pour le chercher, mais personne n'est encore revenu.", progress = nil, completion = "Un autre &lt;race&gt;, hein ? J'espère que vous n'êtes pas venu pour l'autre. Il n'y est pas arrivé. Ces gobelins ne l'ont pas raté.\n\nIl a dit avoir besoin d'un breuvage de guérison, mais il n'a pas ajouté grand-chose.", rewards = "Vous recevrez :\n\n"},
[1511] = {title = "Breuvage de Ken'zigla", objective = "Apporter le Breuvage de Ken'zigla au grunt Logmar, à Camp Taurajo.", description = "Je pensais bien que quelqu'un d'autre viendrait prendre le breuvage, alors je l'ai préparé à toutes fins utiles.\n\nTenez, prenez, <nom>. N’oubliez pas : ne lui donnez que la moitié ! Cela lui donnera suffisamment de force pour qu'il puisse bouger sans perdre tout son sang. Laissez passer une nuit, puis donnez-lui l'autre moitié.\n\nVoilà, vous feriez bien de l'apporter à Logmar au Camp Taurajo. D'après ce que m'a dit l'autre qui est passé avant, il devrait avoir une idée de l'endroit où Dogran se trouve.", progress = "Oui ? Qu'est-ce que c'est ?", completion = "Eh bien, il serait temps ! Dogran est en train de crever ici, en attendant ce breuvage.\n\nNous devons lui apporter cela immédiatement, mais la plupart des grunts d'ici sont sortis pour ravitailler le camp.", rewards = "Vous recevrez :\n\n"},
[1512] = {title = "Le cadeau de l'amour", objective = "Rapporter le Pendentif de poussière à Gan'rul Bloodeye à Orgrimmar.", description = "Zankaja est jeune et belle. Etre enchaînée à un invalide… Je ne permettrai pas qu'elle souffre de cette injustice.\n\nLaissez-moi, <nom>. Et merci. Je peux ainsi terminer ma vie dans une glorieuse bataille, et non comme un légume.\n\nEt je vous en prie, je souhaiterais que vous ne disiez rien à ma compagne... Je ne veux pas quelle se sente coupable.", progress = "Vous voilà de retour. Êtes-vous prêt à combattre une succube ?", completion = "Si vous me dites que cela suffira, alors je vous fais confiance, &lt;nom&gt;. Permettez-moi de le laver quand même. Virginal et brillant, il attirera encore mieux la succube.", rewards = "Vous recevrez :\n\n"},
[1513] = {title = "Le lien", objective = "Utiliser le Pendentif de Dogran pour invoquer et soumettre une succube, puis rapporter le Pendentif de Dogran à Gan'rul Bloodeye, à Orgrimmar.", description = "Apportez cela au cercle d'invocation dans la tente de Neeru, <nom>. Invoquez une ignoble succube, et dominez-la. Comme toujours cependant, soyez <prudent/prudente>, car la fierté et une trop grande confiance en soi ont terrassé de nombreux démonistes prometteurs.\n\nUne fois que vous l'aurez vaincue, venez me rendre le pendentif, pour que je puisse donner des nouvelles à Zankaja.", progress = "Lorsque mon regard se pose sur une succube, mon cœur commence à s'élancer… Mais en même temps, je sens mon esprit reculer et refluer comme la marée.\n\nSoyez prudent, mon ami.", completion = "Succès ! Soyez certain que c’est bien ce que j’attendais de mon meilleur élève.\n\nVous avez démontré votre valeur, et c'est avec plaisir que je vais vous montrer comment invoquer votre succube dominée. Partez à présent, vous avez beaucoup à apprendre, et la prochaine fois que je vous verrai, je m'attends à ce que vous maîtrisiez totalement votre succube.\n\nLaissez le chagrin de Dogran et de Zankaja à ceux qui ont de nombreuses années à vivre, mais conservez ce souvenir comme une protection contre les ruses des sombres pouvoirs que vous avez appris à invoquer aujourd'hui.", rewards = "Vous apprendrez :\n\nInvocation d'une succube\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'une succube\n\nVous recevrez également :\n\nPetite bourse d'âme"},
[1514] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[1515] = {title = "La captivité de Dogran", objective = "Apporter le Breuvage de Ken'zigla à Dogran dans les Tarides.", description = "Vous êtes <arrivé/arrivée> jusque-là, alors si vous voulez voir la fin, je ne vais pas vous arrêter. Cependant, je ne peux pas vous fournir de forces supplémentaires, vous êtes <seul/seule>.\n\nDogran est prisonnier dans un camp de hurans au nord d'ici. Cherchez une paire de huttes. Il sera surveillé de près... À condition qu’ils ne l'aient pas encore tué et qu’il n’ait pas succombé à ses blessures.\n\nBonne chance.", progress = "Arrrghhhh…", completion = "Breuvage dégoûtant…\n\nJe peux sentir la force en moi à présent, en tout cas suffisamment pour aller boiter un peu plus loin… Mais ma jambe, je l'aurais perdue pour le restant de ma vie. Et mon bras, aussi…", rewards = "Vous recevrez :\n\n"},
[1516] = {title = "L'appel de la terre", objective = "Apporter 2 Sabots de traqueur corrompu à Canaga Earthcaller dans la Vallée des épreuves.", description = "Le temps est venu, jeune <classe>. Vous êtes <devenu plus fort/devenue plus forte> et votre esprit est aussi endurant que la terre. Votre choix de suivre la voie du chaman montre votre sagesse, avant même de devoir faire vos preuves.\n\nL'élément de la terre guidera votre destinée, et fera partie intégrante de votre être, si vous y êtes <prêt/prête>. Mais vous devez vous présenter devant la terre elle-même. Si vous êtes <prêt/prête>, vous verrez des choses dont seuls les chamans ont connaissance.\n\nCherchez les traqueurs corrompus au nord, et prenez-leur deux de leurs sabots. Revenez alors me voir, et nous parlerons de votre avenir.", progress = "La patience est la plus grande vertu de la terre. La terre est témoin du cycle de l'univers : les montagnes deviennent des déserts, les rivières deviennent des canyons. La terre est le plus opiniâtre et le plus sage des éléments, et ne tolère pas l'impatience.\n\nLa terre vous fait signe à présent, car une période de conflit se prépare. Lorsque vous reviendrez victorieux,  vous vous serez beaucoup rapproché de l’état de plénitude.\n\nLes autres envieront votre sagesse et vous haïront pour leur ignorance.", completion = "Excellent. Votre réussite prouve que vous êtes prêt.\n\nDe tous les éléments, la terre représente la fondation de toute chose. C'est votre force, votre endurance et votre patience. La terre vous protégera, mais seulement si vous lui témoignez le respect qui lui est dû. Comme les autres éléments, la terre peut être capricieuse. La terre est la base de la vie, et en observant ses lois, vous gagnerez en sagesse. N'oubliez jamais les secrets que la terre partage avec vous.\n\nJe vais préparer votre sapta à présent. En l'acceptant, une nouvelle voie s'ouvrira devant vous.", rewards = "Vous recevrez :\n\n"},
[1517] = {title = "L'appel de la terre", objective = "Trouver le Rocher des esprits et boire le Sapta de terre.\n\nObjet fourni : \n", description = "Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits forts de percevoir les éléments comme nul autre ne le peut. Votre esprit contactera l'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.\n\nIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs, ne l’oubliez pas.\n\nCherchez le rocher des esprits au sud-ouest d'ici, au bout du chemin secret. Buvez-y votre sapta et... et vous verrez.", progress = nil, completion = "Ah ! &lt;nom&gt;… La terre apprécie grandement votre présence en ce lieu.\n\nLié à elle par le corps et l'esprit, vous irez de l'avant en sachant que les montagnes sont votre force, les plaines votre patience et le monde lui-même votre essence.\n\nIl vous suffit de vous tenir devant la terre avec humilité pour réussir ce rite. Mais les autres ne sont pas aussi passifs. Ils peuvent être chaotiques et souvent violents, mais telle est la nature des éléments. Des natures différentes s'opposant l'une à l'autre. Vous devez parvenir à connaître ces choses intimement...", rewards = "Vous recevrez :\n\n"},
[1518] = {title = "L'appel de la terre", objective = "Apporter le Quartz brut à Canaga Earthcaller dans la Vallée des épreuves.", description = "Prenez ce quartz brut et apportez-le à Canaga Earthcaller. Il attestera de notre rencontre. Il créera un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre à bien d'autres.\n\nSoyez <patient/patiente>, <nom>. Restez <fort/forte>. Et recherchez la sagesse. C'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu'un avec elle. Respectez-la comme elle vous respecte.", progress = "Je souhaite être le premier à vous souhaiter la bienvenue sur la première des quatre voies qui, pour toujours, guideront votre destinée. Si vous avez la pierre que la terre vous a donnée, je vous donnerai le totem qu'elle vous a promis.\n\nSi tel n'est pas le cas, alors partez, et ne revenez pas tant que vous n'avez pas trouvé votre voie.", completion = "Excellent !\n\nLe totem que je vais créer pour vous est mieux qu'un simple symbole de votre statut parmi les chamans. Il possède certaines capacités. L'une d’elles permet de focaliser les sorts liés à la Terre. Plus votre sagesse grandira, plus les pouvoirs de la terre vous deviendront accessibles.\n\nVos maîtres sauront quand vous serez prêt à recevoir une plus grande connaissance, et vous le feront savoir.\n\nMais pour l'heure, prenez ce totem de terre...", rewards = "Vous apprendrez :\n\nTotem de Peau de pierre\n\nVous allez être la cible du sort suivant :\n\nTotem de Peau de pierre\n\nVous recevrez également :\n\nTotem de terre"},
[1519] = {title = "L'appel de la terre", objective = "Apporter 2 Applications de Baume rituel au Prophète Ravenfeather au Camp Narache.", description = "Il est temps à présent, jeune <classe>. Votre corps s’est aguerri et votre esprit est aussi endurant que la terre. Je le vois, vous possédez déjà la sagesse.\n\nLa terre guide notre peuple, et nous parle, de la même manière qu'elle vous parlera lorsque le temps sera venu. Mais vous devez être <mis à l'épreuve/mise à l'épreuve>. Si vous êtes <prêt/prête>, alors vous verrez des choses que nous seuls connaissons.\n\nPartez à la recherche des chamans Dos-hirsute dans leur ravin à l'est, et procurez-vous le baume qu'ils utilisent lors de leurs rituels. Ne revenez me voir que lorsque vous en aurez suffisamment pour votre propre potion.", progress = "La terre est patiente et attendra que vous soyez prêt car elle sait qu'avec le temps tout s'érode et tout renaît. C'est le cycle des choses. Les montagnes deviennent des déserts. Les rivières deviennent des canyons. La Terre est le plus opiniâtre et le plus sage des éléments.\n\nVous devez apprendre la patience et l'endurance par-dessus tout. La terre vous appelle à présent, car elle pense que vous êtes prêt. Si vous réussissez, considérez ce rite comme une renaissance. Après, vous ne pourrez plus jamais retourner à l'ignorance.", completion = "Bien, &lt;nom&gt;. Le fait que vous soyez revenu signifie que vous êtes préparé pour la prochaine étape.\n\nDe tous les éléments, la terre représente la fondation de toute chose. C'est votre force, votre endurance et votre patience. La Terre-mère vous protégera, mais seulement si vous lui témoignez le respect qui lui est dû. Elle est la base de la vie, et en observant ses lois, vous gagnerez en sagesse. N'oubliez jamais les secrets qu'elle partage avec vous.\n\nJe vais préparer votre sapta à présent. En l'acceptant, une nouvelle voie s'ouvrira devant vous.", rewards = "Vous recevrez :\n\n"},
[1520] = {title = "L'appel de la terre", objective = "Trouver le Rocher des kodos et boire le Sapta de terre.\n\nObjet fourni : \n", description = "Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits ouverts de voir les éléments comme personne d’autre ne peut les voir. Votre esprit sera lié à jamais à l'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.\n\nIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs.\n\nCherchez l'autel du chaman à l'est d'ici et buvez-y le sapta.", progress = nil, completion = "Ah ! &lt;nom&gt;… La terre apprécie grandement votre présence en ce lieu.\n\nLié à elle par le corps et l'esprit, vous irez de l'avant en sachant que les montagnes sont votre force, les plaines votre patience et le monde lui-même votre essence.\n\nIl vous suffit de vous tenir devant la terre avec humilité pour réussir ce rite. Mais les autres ne sont pas aussi passifs. Ils peuvent être chaotiques et souvent violents, mais telle est la nature des éléments. Des natures différentes s'opposant l'une à l'autre. Vous devez parvenir à connaître ces choses intimement...", rewards = "Vous recevrez :\n\n"},
[1521] = {title = "L'appel de la terre", objective = "Apporter le Quartz brut à la prophétesse Ravenfeather au Camp Narache.", description = "Prenez ce quartz brut et apportez-le à la prophétesse Ravenfeather. Il attestera de notre rencontre. Elle concevra un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre aux montagnes.\n\nSoyez <patient/patiente>, <nom>. Restez <fort/forte>. Et recherchez la sagesse. C'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu'un avec elle. Respectez-la comme elle vous respecte.", progress = "Salutations, <nom>. Vous ne seriez pas revenu si vous n'aviez pas accompli votre quête. Laissez-moi être la première à vous accueillir sur la première des quatre voies qui guideront à jamais vos voyages.\n\nSi vous avez la pierre que la terre vous a donnée, je vous donnerai le totem qu'elle vous a promis. Sinon,  je vous plains. Car on éprouve une grande fierté à se consacrer pleinement aux éléments.", completion = "Splendide !\n\nLe totem que je vais créer pour vous est mieux qu'un symbole : il possède certaines capacités. L'une d'elles est de focaliser les sorts liés à la terre. Plus votre sagesse grandira, plus les pouvoirs de la terre vous deviendront accessibles.\n\nVos maîtres, que vous pourrez trouver dans tout Kalimdor, sauront lorsque vous serez prêt à recevoir une plus grande connaissance, et vous le feront savoir.\n\nMais pour l'heure, prenez ce totem de terre...", rewards = "Vous apprendrez :\n\nTotem de Peau de pierre\n\nVous allez être la cible du sort suivant :\n\nTotem de Peau de pierre\n\nVous recevrez également :\n\nTotem de terre"},
[1522] = {title = "L'appel du feu", objective = "Trouver Kranal Fiss dans les Tarides.", description = "Qu'le feu soit avec vous, <m'sieur/m'dame>. Je vois que vous êtes balèze déjà dans les arts de la terre, et j'pense que vous êtes <prêt/prête> à parler à Kranal.\n\nIl vit au nord de la Croisée des Tarides. Il s'y connaît dans les éléments et peut vous apprendre les méthodes du feu... si vous pensez être <prêt/prête>.\n\nL'est facile à trouver, n'allez pas trop loin, c'est tout, sinon vous vous retrouvez direct chez les elfes de la nuit.", progress = nil, completion = "Hmmm, Searn vous envoie, c'est cela ?\n\nTrès bien, on peut toujours faire confiance à Searn. Cela veut dire que vous êtes prêt à approcher le prochain sapta, le sapta de feu.\n\nJe lis déjà dans vos yeux la flamme, le désir. Vous avez goûté au pouvoir, et maintenant vous en voulez plus. Patience, &lt;nom&gt;. Souvenez-vous de ce que la terre vous a appris. La puissance et la destruction viendront facilement, mais vous devez toujours savoir retenir votre main.", rewards = "Vous recevrez :\n\n"},
[1523] = {title = "L'appel du feu", objective = "Trouver Kranal Fiss dans les Tarides.", description = "Cela fait longtemps que vous n'avez pas été <mis à l'épreuve/mise à l'épreuve>, <nom>. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu d'apprendre la destruction et le chaos. L'élément du feu peut vous appartenir, si vous êtes <prêt/prête> à en payer le prix.\n\nRecherchez Kranal Fiss dans les Tarides. Il vit dans une petite demeure au nord de la Croisée, mais prenez garde. Si vous atteignez les terres des elfes de la nuit, c'est que vous êtes <allé/allée> trop loin.", progress = nil, completion = "Hmmm, Xanis vous envoie, c'est cela ?\n\nTrès bien, on peut toujours faire confiance à Xanis. Cela veut dire que vous êtes prête à approcher le prochain sapta, le sapta de feu.\n\nJe lis déjà dans vos yeux la flamme, le désir. Vous avez goûté au pouvoir, et maintenant vous en voulez plus. Patience, &lt;nom&gt;. Souvenez-vous de ce que la terre vous a appris. La puissance et la destruction viendront facilement, mais vous devez toujours savoir retenir votre main.", rewards = "Vous recevrez :\n\n"},
[1524] = {title = "L'appel du feu", objective = "Apporter la Torche de la flamme dormante à Telf Joolam en Durotar.", description = "Vous êtes suffisamment <puissant/puissante> pour manier le totem de feu, mais cela ne signifie pas que vous êtes <prêt/prête>.\n\nLe long de la Furie-du-Sud en Durotar, avant la Grande Mer, se trouve un sentier caché menant aux hauteurs les plus élevées de cette terre. Trouvez le chemin menant au sommet et vous découvrirez l'un de nos autels sacrés, surveillé par Telf Joolam : l'Autel de la flamme dormante.\n\nApportez-lui cette torche, cela voudra dire que vous tentez d'apprivoiser le feu. Rapportez-la-moi lorsqu'elle sera enflammée au brasero de l’autel et je veillerai à ce que le totem de feu vous soit remis.", progress = "Salutations, <nom>. Vous vous trouvez à l'Autel de la flamme dormante. Seuls ceux qui connaissent suffisamment les arts du <classe> peuvent apprendre les secrets de cet endroit et le pouvoir qu'il renferme. Je suis désolé que vous ayez fait tout ce chemin pour être éconduit à l'arrivée. Le voyage pour venir jusqu’ici est loin d'être sûr, mais je suis le gardien de l'autel et je ne permets pas à n'importe qui de s'en approcher.", completion = "Ah, je me suis trompé, &lt;nom&gt; ! Toutes mes excuses. Je n'avais pas remarqué que vous aviez la Torche. Je suis ravi de faire votre connaissance.\n\nBeaucoup d'aventuriers arrivent ici à la recherche d’un trésor perdu ou de créatures mystiques à tuer, et s’en retournent à la vue d’un autel apparemment vide. Mais nous savons que ce n'est pas le cas, n'est-ce pas, &lt;nom&gt; ?\n\nCet autel cache son grand secret aux simples membres de la Horde. Pour nous, il est sacré.", rewards = "Vous recevrez :\n\n"},
[1525] = {title = "L'appel du feu", objective = "Apporter 1 Goudron de feu et 1 Bourse de réactifs à Telf Joolam en Durotar.", description = "Mais vous n'êtes pas là pour recevoir un cours d'histoire, n'est-ce pas ? Vous êtes <venu/venue> pour la flamme éternelle et le totem de feu.\n\nLa première étape consiste à créer un sapta et à vous lier à la flamme.\n\nJe peux m'en occuper si vous m'apportez deux choses. La première est du goudron de feu, un objet simple à se procurer et généralement porté par les lanceurs de sorts Tranchecrin dans les Tarides de l'est.\n\nIl sera plus dangereux de se procurer la seconde : une bourse de réactifs que vous trouverez sur l'un des sectateurs de la Lame ardente. Ils sont dans une caverne au-dessus des ravins, au nord-est de Tranchecolline.", progress = "J'aurai suffisamment d'ingrédients pour confectionner un sapta de feu si vous m'apportez une bourse de réactifs et du goudron de feu. Les fanatiques de la Lame ardente utilisent de bons ingrédients, qu’ils portent généralement dans une bourse. Une bourse contient suffisamment de réactifs pour ce que nous avons à faire.\n\nLes saptas sont toujours composés d'ingrédients associés à leurs éléments respectifs. Cela facilitera notre travail, car les démonistes ont de nombreuses affinités avec le feu.", completion = "Cela fera parfaitement l'affaire, &lt;nom&gt;.\n\nLe feu représente bien plus de choses que le simple chaos ou la destruction. Vous feriez bien de vous en souvenir... Il est également lié à la vie et à la création. Tout est ainsi lié. Les forces s'opposent les unes aux autres, mais l'une ne peut pas exister sans l'autre. Chacune éteint l'autre, mais lui donne également un nouveau sens. N’oubliez jamais cela.\n\nAssocier différents types de magie ne témoigne pas simplement d'une grande compétence, mais essentiellement d'une grande sagesse.", rewards = "Vous recevrez :\n\nSapta de feu"},
[1526] = {title = "L'appel du feu", objective = "Vaincre la Manifestation de feu mineure, et placer sa Braise rougeoyante dans le brasero, en haut de l'Autel de la flamme éternelle.", description = "Le sapta de feu est terminé. Il est temps pour vous de vous confronter à la flamme. Utilisez le sapta à l'autel et rendez-vous au sommet de la montagne pour affronter la manifestation. Elle n'attaquera pas tant que vous ne serez pas <prêt/prête>, mais elle sait que vous pouvez la voir.\n\nFrappez bien, et frappez vite, <nom>, car sa puissance grandira si vous tardez à la tuer. Quand vous l'aurez vaincue, placez ses braises dans le brasero et allumez la torche.", progress = "Le brasero mesure à peu près un tiers de votre hauteur, et semble normal, si ce n'est les inscriptions le long de ses parois métalliques lisses. Le métal ne montre aucun signe d'usure dû au temps, et la coupe semble fraîche au toucher.", completion = "Alors que vous placez la braise dans la coupe, une flamme blanche et chaude s'embrase. Vous sentez les effets magiques du sapta parcourir vos veines, et le feu danse rythmiquement devant vous.\n\nVous placez l’extrémité de la torche à l'intérieur de la coupe, et elle s’embrase immédiatement.", rewards = "Vous recevrez :\n\nTorche de la flamme éternelle"},
[1527] = {title = "L'appel du feu", objective = "Apporter la Torche de la flamme éternelle à Kranal Fiss dans les Tarides.", description = "Tenant fermement la torche, vous vous détournez du brasero et embrassez Durotar du regard. Vous sentez la fièvre battre dans votre esprit tandis que le vent avive les flammes qui dansent furieusement.\n\nVous prenez le chemin du retour vers les Tarides, pour trouver Kranal Fiss.", progress = "Oui, <nom> ? Qu'avez-vous là ?", completion = "Votre esprit brûle avec plus d'ardeur que toutes les torches qu'il m'a été donné de voir, &lt;nom&gt;, et vous pouvez en être fier. Si vous continuez dans cette voie, vous pourrez commander à tous les éléments, et nos semblables, en quête d'un guide ou de sagesse, vous consulteront. Laissez-moi être le premier à vous féliciter et à vous présenter votre nouveau totem.", rewards = "Vous apprendrez :\n\nTotem incendiaire\n\nVous allez être la cible du sort suivant :\n\nTotem incendiaire\n\nVous recevrez également :\n\nTotem de feu"},
[1528] = {title = "L'appel de l'eau", objective = "Trouver Islen Waterseer dans les Tarides.", description = "L'eau est dans votre avenir, <mon pote/m'dame>. Je vois qu'vous vous en sortez déjà bien avec les arts du feu, et je pense que vous êtes <prêt/prête> à parler à Islen.\n\nElle vit le long de la côte des Tarides. Si vous suivez le fleuve Furie-du-Sud en direction du sud, vous pouvez pas la rater – cherchez l'grand requin ! Elle maîtrise les arts des éléments et peut vous apprendre ceux de l'eau... si vous pensez être <prêt/prête>.\n\nElle est facile à trouver, n’allez pas trop loin, c'est tout. Elle se trouve juste après Ratchet.", progress = nil, completion = "Le vent venu de l'horizon vous rejoint vite. La terre est ferme sous vos pieds. Votre esprit est réchauffé par le feu. Je pense qu'il est temps pour vous d'apprendre la pureté de l'eau.\n\nVotre chemin vous a déjà mené loin, et votre esprit vous donnera la force de continuer. Mais il vous appartient d'effectuer le dernier pas.", rewards = "Vous recevrez :\n\n"},
[1529] = {title = "L'appel de l'eau", objective = "Trouver Islen Waterseer dans les Tarides.", description = "Cela fait longtemps que vous n'avez pas été <mis à l'épreuve/mise à l'épreuve>, <nom>. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent veu pour vous d'apprendre la pureté de l'eau.\n\nCherchez Islen Waterseer dans les Tarides. Elle se trouve le long de la côte est, au sud du fleuve Furie-du-Sud et de Ratchet. Vous la trouverez dans une hutte de pêcheur. Bonne chance à vous, <nom>.", progress = nil, completion = "Le vent venu de l'horizon vous rejoint vite. La terre est ferme sous vos pieds. Votre esprit est réchauffé par le feu. Je pense qu'il est temps pour vous d'apprendre la pureté de l'eau.\n\nVotre chemin vous a déjà mené loin, et votre esprit vous donnera la force de continuer. Mais il vous appartient d'effectuer le dernier pas.", rewards = "Vous recevrez :\n\n"},
[1530] = {title = "L'appel de l'eau", objective = "Trouver Brine dans les Tarides du sud.", description = "S'il y a une leçon à apprendre de l'eau, la voici : l'eau est la renaissance.\n\nSon pouvoir coule, érode et rend propre toute chose. Ses propriétés de guérison et de ressourcement sont incomparables, mais seulement lorsqu'elle est pure.\n\nLorsque vous comprendrez que l'eau, quand elle est polluée, peut dévaster tout ce qu'elle touche, vous apprécierez à quel point cette ressource est vitale.\n\nSi vous souhaitez le sapta de l’eau, trouvez Brine loin dans les Tarides du sud. Sa maison est constamment la cible des hurans.", progress = nil, completion = "Oui ?\n\nMmm ! Je crois savoir ce que vous allez me demander : pourquoi une personne vit-elle au plus profond des Tarides, sans protection, avec des hurans la menaçant de toutes parts ? Eh bien, nous avons tous nos raisons pour justifier nos actes ! La véritable question est : qu'est-ce qui vous amène au fin fond des Tarides pour parler à une femme qui n'a visiblement aucune inquiétude quant à sa propre sécurité ?\n\nJe parie que nous connaissons tous deux la réponse, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1531] = {title = "L'appel de l'air", objective = "Trouver Prate Cloudseer aux Mille pointes.", description = "Y faut que vous y alliez, là. Préparez-vous à montrer qu'vous êtes digne de r'cevoir vot' totem d'air. Mais déjà, vous d'vez trouver Prate Cloudseer aux Mille pointes. Elle vous dira comment obtenir vot' totem d'air.\n\nPassez au sud par les Tarides, puis aux Mille pointes, à l'est. Vous la trouverez cachée dans un trou, avec son p'tit copain. Haha, ne lui dites pas qu'je la salue pas, elle aimerait pas trop.", progress = nil, completion = "Pour le moment, je vais vous donner de quoi focaliser vos sorts et appeler les esprits de l'air. Prenez ce totem, et quand vous serez prêt revenez me voir pour approfondir votre enseignement.", rewards = "Vous allez être la cible du sort suivant :\n\nVent léger\n\nVous recevrez :\n\nTotem d'air"},
[1532] = {title = "L'appel de l'air", objective = "Trouver Prate Cloudseer aux Mille pointes.", description = "Les vents de Kalimdor se hâtent pour vous rencontrer et vous serez bientôt <compté/comptée> parmi nos plus puissants frères et sœurs. La fierté m'emplit de vous voir arriver à ce stade, et de savoir votre avenir si prometteur.\n\nL'air est difficile à contrôler, mais j'ai foi en vos capacités à surmonter tous les obstacles.\n\nPartez pour l'extrême sud des Tarides et entrez aux Mille pointes. C'est là, loin à l'est, que vous trouverez Prate Windseer. Elle vous enseignera.", progress = nil, completion = "Pour le moment, je vais vous donner de quoi focaliser vos sorts et appeler les esprits de l'air. Prenez ce totem, et quand vous serez prêt revenez me voir pour approfondir votre enseignement.", rewards = "Vous allez être la cible du sort suivant :\n\nVent léger\n\nVous recevrez :\n\nTotem d'air"},
[1534] = {title = "L'appel de l'eau", objective = "Remplir l'Outre bleue vide aux Ruines de Chimétoile à Ashenvale et la rapporter à Brine dans les Tarides.", description = "Prenez cette outre et enfoncez-vous au cœur de la forêt luxuriante que les elfes de la nuit appellent Ashenvale. C'est à l'extrême nord des Tarides.\n\nUne fois dans la forêt, allez à l'ouest. Le long des montagnes qui séparent les Serres-Rocheuses d'Ashenvale, au-delà du lac Mystral, vous trouverez un lieu sacré : les ruines de Chimétoile. Une petite fontaine jaillit au centre du lac.\n\nApportez-moi un échantillon de l'eau de cette fontaine. Ce sera le dernier ingrédient que vous devez obtenir avant que je ne vous renvoie à Islen.", progress = "Avez-vous trouvé l'eau, <nom> ? La légende dit que les ruines étaient protégées par d'imposantes créatures qui se souciaient peu des visiteurs, mais il s'agit peut-être de fables destinées à effrayer les ennemis des elfes de la nuit.\n\nCependant, faites attention.", completion = "Merveilleux, &lt;nom&gt;. À présent que les trois échantillons sont rassemblés, je peux créer une fiole de l'eau la plus pure. Elle sera nécessaire aux prochaines étapes de votre rite de passage.\n\nIl me plaît de vous voir parmi nous, &lt;nom&gt;. Tous les chamans sont fiers de vous, et j’espère entendre bientôt parler de vos futurs exploits.", rewards = "Vous recevrez :\n\n"},
[1535] = {title = "L'appel de l'eau", objective = "Remplir l'Outre marron vide au trou d’eau, derrière la hutte de Brine, puis rapportez-lui la, dans les Tarides.", description = "Pour trouver la compréhension et obtenir le sapta, vous devez trouver les eaux les plus pures. Tandis que vous rassemblerez les échantillons pour moi, observez les lieux qui vous entourent. Soyez <attentif/attentive> aux créatures qui ont besoin d'eau, et qui la protègent. Voyez comment elle affecte les forêts et les déserts. Soyez témoin de la manière dont la substance même qui maintient la vie force les créatures à ôter la vie.\n\nNous commencerons par une tâche simple : en bas de ma hutte, vous trouverez un bassin de ce précieux liquide. Remplissez-en cette outre et revenez me voir.", progress = "Je suis presque prête à vous envoyer accomplir vos autres quêtes. Avez-vous rempli l'outre ?\n\nJe sais à quel point les hurans ont une attitude protectrice à l’excès ! Même un humble ruisseau est une immense source de prospérité pour eux. Ils font la fête dès que la moindre averse tombe sur les Tarides. L'eau est sacrée à leurs yeux, car elle est très rare. Comprenez-vous ?", completion = "Je pensais bien que votre tentative de prendre de l'eau du bassin allait provoquer quelques effusions de sang. Il est bien dommage que les hurans ne comprennent pas que toutes les choses vivantes sont liées, que leur avidité ne fait qu’engendrer douleur et souffrance pour leur peuple. Que ne pourraient-ils accomplir s'ils mettaient de côté leurs différences pour unir leurs clans ?\n\nOui, c'est dommage... Mais c'est très certainement une bénédiction pour les autres races des Tarides.", rewards = "Vous recevrez :\n\n"},
[1536] = {title = "L'appel de l'eau", objective = "Remplir l'Outre rouge vide au puits de Moulin-de-Tarren et retourner voir Brine dans les Tarides.", description = "Il y a longtemps, j'ai suivi quelques compagnons jusqu'aux contreforts d'Hillsbrad. Nous nous sommes défendus contre des humains tenaces qui s'y sont établis et nous nous sommes retrouvés dans une petite ville occupée par les Réprouvés : Moulin-de-Tarren.\n\nC'est là que j'ai découvert une chose des plus étranges : en pleine ville, un petit puits offrait une belle eau fraîche. Je ne crois même pas que ces pestiférés comprennent sa valeur. C'est une goutte de pureté au cœur d’une mer de malédiction.\n\nRemplissez cette outre avec cette eau et rapportez-la-moi.", progress = "La pureté intacte de ce puits, en pleine ville, me rappelle des histoires que l'on m'a racontées lorsque j'étais jeune, <nom>. Même dans les temps de douleur et de chagrin, on trouve toujours une lueur d'espoir, un petit symbole auquel se raccrocher. Le peuple des orcs considère Thrall de cette façon. Il a survécu contre vents et marées et s'est élevé pour diriger notre peuple, pour l’aider à trouver sa force et à suivre son exemple.\n\nJe suis sûr que tous les orcs ont souffert autant qu'il a souffert, mais il est le plus fort de tous les orcs.", completion = "C'est bien, &lt;nom&gt;. Vous êtes dévouée à votre tâche et savez trouver ce qui est nécessaire.\n\nje n'ai besoin que d'un autre échantillon pour créer le réactif nécessaire à votre sapta. Cela plaira également à Islen.", rewards = "Vous recevrez :\n\n"},
[1558] = {title = "Le barrage de Formepierre", objective = "Conduire l'orphelin au barrage de Formepierre au Loch Modan. Vous devez le conduire au milieu du barrage pour qu'il puisse voir par-dessus l'immense chute d'eau.", description = "Ironforge, c'est là où vivent tous les nains et les gnomes. Pas loin, il y a un endroit qui s'appelle le Loch Modan. Les nains y ont construit un ÉNORME barrage. Ils disent que c'est l'une des choses les plus grandes jamais construites. Ouah !\n\nVous pouvez m'emmener au Loch Modan pour voir le barrage, s'il vous plaît ? Je crois que c'est le barrage de Forme... de Formepierre. Il est énorme, c'est sûr. J'aimerais bien regarder par-dessus la grande chute d'eau. Je promets que je ne me pencherai pas trop au-dessus de la rambarde !", progress = nil, completion = "Ouah, le barrage était encore plus GRAND que je l'imaginais ! Je m'entendais presque pas parler à cause du bruit de toute l'eau qui tombait ! Hé, vous croyez qu'un jour il tombera en panne d'eau ? Et qu'est-ce qui se passerait si un jour le barrage cassait ? OUAH, ce serait terrible !\n\nMerci de m'avoir emmené voir le barrage. C'était très gentil. Je vous avais bien dit que je ne me pencherais pas trop sur la rambarde !", rewards = "Vous recevrez :\n\n"},
[1559] = {title = "La recette de la bombe éclairante", objective = "Alors vous êtes l'ingénieur, hein ? Bien, en contrepartie de votre aide pour ces perles, voici la recette de la bombe éclairante.\n\nBonne chance et tâchez de ne pas vous aveugler !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : Bombe éclairante"},
[1560] = {title = "La quête de Tooga", objective = "Montrer à Tooga le chemin du retour vers sa femme, Torta.", description = "Je suis complètement perdu !\n\nMa femme, Torta, m'a envoyé chercher le dîner et j'ai dû prendre le mauvais chemin quelque part.\n\nAuriez-vous l'amabilité de me guider vers Torta ? Elle m'attend au sud de Port Gentepression.", progress = nil, completion = "Ainsi il ne trouvait pas le chemin du retour tout seul ? Les routes…\n\nBien, je suppose que vous méritez un petit quelque chose pour le dérangement…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCrispins chéloniensAnneau de la grande tortue\n\nVous recevrez également :\n\n"},
[1578] = {title = "Rééquiper le front", objective = "Apporter 6 Haches en cuivre et 6 Ceintures en anneaux de cuivre à Thorvald dans la Tour de garde méridionale du Loch Modan.", description = "Les montagnards de Loch Modan combattent les troggs, et cela les occupe beaucoup. Ils ont constamment besoin d'être approvisionnés en armures et en nouvelles armes.\n\nC'est pourquoi mon collègue Thorvald est ici, pour maintenir l'équipement des montagnards en bon état. Aussi, si vous pouviez fabriquer des haches en cuivre et des ceintures en anneaux de cuivre, puis les apporter à Thorvald, il vous en serait reconnaissant. Il se peut même qu'il partage une partie de son savoir avec vous.\n\nThorvald est basé dans la tour de garde méridionale de Loch Modan.", progress = "Je n'ai pas le temps pour la parlotte. Vous avez quelque chose à me dire ?", completion = "Ah ! Toutes mes excuses ! Je ne savais pas que vous étiez là pour nous aider à équiper nos troupes. Ce que vous avez fait nous sera d'un grand secours !\n\nVoici les plans pour un type d'armure. J'espère qu'ils vous seront utiles.", rewards = "Vous recevrez :\n\nPlans : Lorica en cuivre"},
[1579] = {title = "Rouages électriques", objective = "Apporter 8 Rouages électriques à Wizbang Cranktoggle à Auberdine.", description = "Je suis venu à Auberdine parce que c'est calme. Je veux créer dans le calme. Ironforge est décidément trop bruyante après une nuit passée à boire !\n\nAlors j'ai pris un bateau pour Auberdine et j’ai bu un petit peu trop pendant le voyage. J'ai laissé tomber ma boîte de rouages électriques par-dessus bord ! J'en ai besoin !\n\nJe ne sais pas exactement où je l’ai laissée tomber, mais si vous pêchez quelque part dans l'océan, il se peut que vous ayez de la chance...", progress = "Avez-vous trouvé mes Rouages électriques, <nom> ? Sans eux je ne peux tout simplement pas mettre au point mes chevilles ouvrières !", completion = "Je ne peux pas croire que vous les avez trouvés ! Vous devez être la personne la plus chanceuse en Kalimdor, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[1580] = {title = "Pêche aux Electropellers", objective = "Apporter 12 Electropellers à Wizbang Cranktoggle à Auberdine.", description = "Nous savons que vous êtes <chanceux/chanceuse>, mais à quel point l'êtes-vous vraiment, <nom> ?\n\nUne nuit, je marchais sur les routes de Sombrivage. J'essayais de trouver une bonne rivière ou un bon lac pour tester mon nouvel appeau à canard explosif et à propulsion automatique, et je pense que j'étais un peu... parti. Je me suis endormi et je me suis réveillé des heures plus tard à Auberdine. Mes cheveux étaient roussis et je ne trouvais plus mon sac d'Electropellers ! J'avais dû le laisser tomber dans l'eau !\n\nIl me faut ces Electropellers ! Peut-être pourriez-vous les pêcher quelque part dans un lac ou dans un cours d'eau quelconque à Sombrivage...", progress = "Avez-vous trouvé des Electropellers ? Je vais en avoir besoin si je veux continuer mes recherches sur mes appeaux à canard.", completion = "Je ne peux pas le croire ! Vous les avez trouvés ! Vous êtes le meilleur pêcheur que je connaisse !\n\nMerci, &lt;nom&gt;. Et tenez, prenez ça. Vous êtes déjà tellement bon à la pêche que vous n'en aurez probablement pas besoin, mais avec ça vous pêcherez encore mieux.", rewards = "Vous recevrez :\n\nOeil de poisson aquadynamique"},
[1581] = {title = "Les élixirs pour les Bladeleaf", objective = "Apporter 6 Elixirs de force du lion et 2 Elixirs de défense mineure à Syral Bladeleaf à Dolanaar.", description = "Notre magasin d'herbes et d'alchimie est un succès, mais mon mari passe tellement de temps à préparer ses potions qu'il ne nous en reste plus pour nous deux.\n\nPouvez-vous nous aider ?\n\nSi vous m'apportiez une provision d'élixirs déjà faits, alors je serais heureuse de commercer avec vous. J'ai ici quelques herbes rares qui pourraient vous intéresser.", progress = "Salutations, <nom>. Avez-vous ces élixirs pour moi ?", completion = "Ils sont parfaitement préparés. Vous prenez grand soin de votre affaire, &lt;nom&gt;, et c'est très important pour un alchimiste.\n\nVoici vos herbes, fraîchement récoltées. Puissent-elles vous être d'une grande utilité.", rewards = "Vous recevrez :\n\nTerrestrineMage royal"},
[1582] = {title = "Veste de Moonglow", objective = "Apporter 1 Gant en cuir estampé, 5 Bottes en cuir estampé et 5 Capes en cuir estampé à Lotherias à Darnassus.", description = "Nous autres à Darnassus sommes très occupés, et tout particulièrement les artisans. Les jeunes aventuriers souhaitant affronter les dangers de la nature ont constamment besoin d'équipement.\n\nSi vous pouviez m'aider à honorer mes commandes de cuir, alors je pourrais peut-être vous apprendre une technique avancée d'artisanat du cuir.", progress = "Salutations, <nom> !", completion = "Oui, ce sont de belles pièces ! Vous avez la main sûre et l’oeil attentif. Votre avenir en tant qu'artisan du cuir est prometteur.\n\nParfait, &lt;nom&gt;. Laissez-moi vous montrer le motif de la Veste de Moonglow.", rewards = "Vous recevrez :\n\nPatron : Gilet Lueur-de-lune"},
[1598] = {title = "Le Tome dérobé", objective = "Retrouver la Puissance du Vide pour Drusilla La Salle.", description = "Vous ici ! <nom>, c'est ça ?\n\nÊtes-vous <sûr/sûre> de votre vocation de démoniste, car si vous ne pouvez pas maîtriser ce que vous invoquez, vous finirez <aspiré/aspirée> dans le Néant.\n\nJe dois vous enseigner les arts du démoniste, mais je dois d'abord m'assurer que vous êtes suffisamment <fort/forte>.\n\nUn novice qui étudiait à l'abbaye s'est enfui pour rejoindre la Confrérie défias. Pourquoi est-ce que cela m'intéresse ? Eh bien, il a volé certains livres importants.\n\nL'un d'entre eux se trouve être un livre que je voulais pour mon usage personnel : « la Puissance du Vide ». Volez-le pour moi, il est caché dans sa tente dans les vignes.", progress = "Cela n’aurait pas été judicieux de voler le livre moi-même. Quelle chance qu’un pigeon ait fait le sale boulot à ma place !", completion = "Excellent… Je n'ai jamais pu accéder à ce texte. Il était conservé dans une aile protégée de la bibliothèque, et il n’aurait pas été discret d’aller rôder dans ce secteur.\n\nBien, vous avez fait du bon travail en le récupérant, et je suis convaincu que vous pouvez maîtriser votre propre diablotin. Alors il n'y a aucune raison que je ne vous montre pas comment en invoquer un…", rewards = "Vous apprendrez :\n\nInvocation d'un diablotin\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un diablotin\n\nVous recevrez également :\n\n"},
[1599] = {title = "Les débuts", objective = "Apporter 3 Charmes de plume à Alamar Grimm à Anvilmar.", description = "Vous devez être <le nouveau/la nouvelle> démoniste dont tout le monde parle. Quelqu'un doit vous apprécier pour qu’on m'arrache à mes recherches et me demande de vous enseigner.\n\nNe vous inquiétez pas, je vais vous consacrer du temps.\n\nLe plus simple des sorts d'invocation est celui du diablotin. Mais avant que je vous le livre, vous devez prouver que vous avez les capacités physiques et mentales nécessaires.\n\nApportez-moi trois Charmes de plume que portent les novices Frostmane de la caverne au sud-ouest.", progress = "Ces charmes de plume portés par les novices sont liés à une sorte de pouvoir magique. Ce sera intéressant de les étudier. Je ne me serais pas attendu à cela de la part des trolls.", completion = "Très bien, très bien ! Bon travail, &lt;nom&gt; ! Peut-être que l'intérêt que certains vous portent est mérité après tout.\n\nCe sera aux autres de décider, si tant est que votre diablotin ne vous surpasse pas et ne brise pas votre carrière dans l'œuf. Jusque-là, je pense que vous serez capable de survivre à vos premiers mois en tant que &lt;classe&gt;.\n\nUn mot à propos du diablotin, &lt;nom&gt;. Comme tout &lt;race&gt; le sait, ne vous laissez pas tromper par sa taille, sa magie peut être très dangereuse.", rewards = "Vous apprendrez :\n\nInvocation d'un diablotin\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un diablotin\n\nVous recevrez également :\n\n"},
[1618] = {title = "Le rééquipement des Carmines", objective = "Tormus Deepforge veut que vous apportiez 4 Ceintures runiques en cuivre et 4 Grands maillets en cuivre à Verner Osgood, dans les Carmines.", description = "Nous les nains ne sommes pas les seuls à nous battre. Nos alliés humains sont très occupés également.\n\nLes Carmines subissent régulièrement des attaques des orcs Blackrock, et leur réserve d'équipement est constamment très basse. Si vous vouliez leur venir en aide, je suis sûr que leur forgeron permanent, Verner Osgood, vous apprendrait un ou deux trucs.", progress = "J'espère que vous apportez des bonnes nouvelles d'Ironforge. Car je ne sais plus quoi faire !", completion = "Merci, &lt;nom&gt; ! Ceci va énormément m'aider. Avec les orcs de Blackrock qui attaquent le donjon de Guet-de-pierre et les gnolls des Carmines qui guettent dans les collines au nord, je suis toujours en train de réparer des armures et de fabriquer des armes.\n\nLe stock que vous m'avez apporté va me donner un moment de répit. Je vais avoir suffisamment de temps pour vous apprendre quelque chose...", rewards = "Vous recevrez :\n\nPlans : Cuirasse d'Ironforge"},
[1638] = {title = "L'entraînement du guerrier", objective = "Parler à Harry Burlguard.", description = "Vous avez montré que vous êtes <un guerrier/une guerrière> capable, <nom>. Mais vous êtes encore jeune et avez beaucoup à apprendre.\n\nParlez à Harry Burlguard, il est généralement à la taverne du « Cochon siffleur », dans la vieille ville de Stormwind. Harry est un vétéran et un excellent Maître. Il pourrait vous montrer quelques passes d’armes qui vous aideraient à vivre plus vieux.", progress = nil, completion = "Ho ho ! Prenez un verre avec moi, mon pote. Vous avez l'air robuste de l'extérieur, mais voyons si vos tripes peuvent supporter quelques chopes de ce que le « Cochon siffleur » a de plus fort !\n\nOu… veniez-vous pour une leçon ?", rewards = "Vous recevrez :\n\n"},
[1639] = {title = "Bartleby le poivrot", objective = "Parler à Bartleby.", description = "Ouais, je peux vous enseigner ! Mais d'abord je veux voir ce que vous savez déjà.\n\nVous voyez ce poivrot là-bas au bout du bar ? Bartleby ? Je veux que vous lui preniez sa chope.\n\nHa ! Et si vous connaissez Bartleby, alors vous savez qu'il ne vous la donnera pas gentiment.", progress = nil, completion = "Salut, beau gosse ! Qu'est-ce qu'un mignon comme vous fait au « Cochon siffleur » ? Faites attention, vous pourriez vous casser un ongle...", rewards = "Vous recevrez :\n\n"},
[1640] = {title = "Battre Bartleby", objective = "Battre Bartleby, puis lui parler.", description = "Vous voulez quoi ? Vous êtes <fou/folle> !\n\nLa seule façon pour vous d'obtenir cette chope serait de la prendre entre mes doigts froids et morts…", progress = "La seule façon pour vous d'obtenir cette chope serait de la prendre entre mes doigts froids et morts…", completion = "Vous êtes beaucoup plus costaud que vous n'en avez l'air !", rewards = "Vous recevrez :\n\n"},
[1641] = {title = "Le Tome de divinité", objective = "A Stormwind, je suis chargé de guider les paladins sur le chemin de la vertu quand ils se consacrent à la Lumière et à la défense d’Azeroth contre le Fléau et autres menaces.\n\nLe temps est venu pour vous de faire vos premiers pas vers la véritable vertu. Si vous l'acceptez, je vous donnerai un livre de divinité. En l'étudiant, vous en apprendrez plus sur la Lumière, et sur ce qu'on attend de vous. Si vous le comprenez, et en avez l’étoffe, vous réussirez à atteindre de plus hautes compétences.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTome de divinité"},
[1642] = {title = "Le Tome de divinité", objective = "Parler à Duthorian Rall à Stormwind.", description = "En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.\n\nBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c'est en aidant les autres que vous vous démarquerez véritablement des citoyens d'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.\n\nPrenez-en conscience, et ne l'oubliez pas.", progress = nil, completion = "Soyez à nouveau le bienvenu &lt;nom&gt;. Comment se déroulent vos études du « Tome de la divinité » ?\n\nVous devriez être prêt pour le test. Il y a toujours à faire dans notre ville ou sur nos terres. Des actes de compassion ou des actes de compréhension. Des gens à aider. Des créatures à massacrer.\n\nEn montrant que vous avez la patience de venir en aide aux autres, et particulièrement aux moins fortunés, vous prouvez que vous êtes un serviteur de la Lumière et un esprit sain.", rewards = "Vous recevrez :\n\n"},
[1643] = {title = "Le Tome de divinité", objective = "Chercher Stephanie Turner dans le Quartier commerçant de Stormwind.", description = "Votre tâche, à présent, <nom>, est de trouver quelqu'un ici, à Stormwind, qui a besoin de votre aide. Quelqu'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu'un ayant besoin d'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.\n\nAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière.", progress = nil, completion = "Oh ! Salut ! Comment se passent vos aventures ? Je suis heureuse de constater que vous vous portez bien.\n\nOh, moi ? Merci de demander. Je vais bien, dans l'ensemble.\n\nL'augmentation des fournisseurs a mis un frein à la quantité de cuir que les gens veulent bien donner en ce moment, alors ça a été plus dur d'habiller les enfants de l'orphelinat. Mais nous nous en sortirons. Je veux dire mon mari et moi. Il est parti pour Ironforge pour essayer d'obtenir de l'aide.", rewards = "Vous recevrez :\n\n"},
[1644] = {title = "Le Tome de divinité", objective = "Apporter 10 morceaux d'étoffe de lin à Stephanie Turner à Stormwind.", description = "Qu’ils soient bénis. La plupart ont perdu leur famille dans les attaques du Fléau, ces dernières années.\n\nMon mari, John, collecte des matériaux qui me servent à confectionner des chemises et des pantalons pour les enfants, ce que je n’ai malheureusement pas eu le temps de faire dernièrement.\n\nMais peut-être voudriez-vous m'aider ? Oh, merci mille fois, <nom>.\n\nSi vous pouviez m’apporter de l’étoffe de lin pour que je puisse en faire des vêtements pour les enfants, je vous en serai reconnaissante.", progress = "J'espère que mon John a plus de chance à Ironforge. Il déteste tellement ces voyages là-bas, car il nous laisse seuls, les enfants et moi. Mais il sait qu'il doit le faire. Il est d'une telle gentillesse.\n\nCertaines années ont été meilleures que d'autres, mais celle-ci est de loin la plus dure. C'est presque comme si quelque chose dans l'air annonçait un grand bouleversement. Mais qui peut savoir ?", completion = "Merci, &lt;nom&gt;, merci mille fois !\n\nLes enfants seront ravis, et vous m'avez fait gagner tellement de temps. Je vais à présent pouvoir me consacrer aux autres besoins des enfants. Et John va pouvoir rentrer à la maison plus tôt que prévu.\n\nMerci à nouveau, &lt;nom&gt;. je savais que la charité n’était pas un vain mot. Que la Lumière soit avec vous !", rewards = "Vous recevrez :\n\n"},
[1645] = {title = "Le Tome de divinité", objective = "Un plaisir de vous rencontrer, <nom>. Je suis chargée de guider les paladins sur le chemin d'une plus grande vertu quand ils se consacrent à la Lumière et à la défense d’Azeroth.\n\nLe temps est venu pour vous de faire vos premiers pas vers la véritable vertu. Si vous acceptez cet engagement, je vous donnerai un livre de divinité. En l'étudiant, vous en apprendrez plus sur la Lumière, et sur ce que l'on attend de vous. Si vous le comprenez, et si vous en avez l’étoffe, alors vous réussirez à atteindre de plus hautes compétences.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTome de divinité"},
[1646] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge à Ironforge.", description = "En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.\n\nBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c'est en aidant les autres que vous vous démarquerez véritablement des citoyens d'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.\n\nPrenez-en conscience, et ne l'oubliez pas.", progress = nil, completion = "Soyez à nouveau le bienvenu, &lt;nom&gt;. Vous avez consacré du temps à l’étude du livre, j'espère ?\n\nAlors vous êtes prêt pour le test. Il y a toujours à faire dans notre ville ou sur nos terres. Des actes de compassion ou des actes de compréhension. Des gens à aider. Des créatures à massacrer.\n\nEn montrant que vous avez la patience de venir en aide aux autres, et particulièrement aux moins fortunés, vous prouvez que vous êtes un serviteur de la Lumière et un esprit sain.", rewards = "Vous recevrez :\n\n"},
[1647] = {title = "Le Tome de divinité", objective = "Chercher John Turner à la périphérie d'Ironforge.", description = "Votre tâche, <nom>, consiste à trouver quelqu'un ici à Ironforge qui ait besoin d'aide. Quelqu'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu'un ayant besoin d'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.\n\nAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière. Je resterai ici, au temple, dans l'attente de votre retour. D'autres paladins auront besoin que je les guide, également.", progress = nil, completion = "L'ORPHELINAT DE STOR… Oh pardon ! Je ne voulais pas vous crier dessus, Monsieur.\n\nJe me nomme John Turner. Comment allez-vous ?\n\nBien, bien, je suis heureux d'entendre que les choses se passent bien pour vous. J'ai déjà eu une longue journée de travail, et ma famille me manque terriblement, mais c'est le prix à payer lorsque vous avez tant de bouches à nourrir et de dos à vêtir.", rewards = "Vous recevrez :\n\n"},
[1648] = {title = "Le Tome de divinité", objective = "Apporter 10 morceaux d'étoffe de lin à John Turner à Ironforge.", description = "Ma femme et moi nous nous occupons d'un orphelinat à Stormwind, principalement pour des enfants qui ont perdu leurs parents au cours des attaques du Fléau cette dernière décennie. Je passe à Ironforge à peu près tous les mois afin de collecter des vivres offerts par des citoyens d’ici, et j’essaie de convaincre certaines associations de soutenir notre action vis-à-vis des enfants.\n\nCe voyage a été horriblement lent, et pas très productif.\n\nSi je pouvais simplement trouver des pièces de lin pour que ma femme puisse coudre quelques vêtements, je pourrais enfin envoyer quelque chose à la maison.", progress = "Pourquoi, avec ce flot de marchands dans le coin et partout dans Azeroth, ne trouve-t-on pas de quoi fabriquer des vêtements pour les enfants de notre orphelinat ? Cela serait noble de votre part si vous m'aidiez à trouver des pièces de lin afin que ma femme puisse confectionner des habits pour ces enfants. Merci, <nom> !\n\nAvec un peu de chance, je serai rapidement de retour à la maison.", completion = "C'est si gentil à vous, &lt;nom&gt;. Merci encore !\n\nVotre âme est noble, pour avoir agi ainsi. Cela ne m'étonne pas que vous suiviez le chemin de la Lumière. J'espère un jour pouvoir m'acquitter de ma dette envers vous... Comment ? C'est le moins que vous pouviez faire ? Vous voyez ? C'est ce que je disais, &lt;nom&gt;, noble jusqu'au bout !\n\nBonne chance, et que la Lumière vous protège.", rewards = "Vous recevrez :\n\n"},
[1649] = {title = "Le Tome de la bravoure", objective = "Parler à Duthorian Rall à Stormwind.", description = "La bravoure et toutes les vertus qui vont avec sont comme les minerais rares : pour leur valeur vous devez les chérir, mais vous devez aussi prendre le temps de les entretenir, de les polir. Quand vous les associez judicieusement, vous obtenez un alliage résistant, qui peut résister même aux coups les plus violents.\n\nCette force, votre foi, votre bravoure doivent être éprouvées. Vous devez apprendre à ne jamais perdre la foi et comprendre qu'avec le pouvoir de la Lumière à vos côtés, vous pourrez surmonter plus d’obstacles que la plupart des gens.", progress = nil, completion = "Ah ! Vous me demandez de tester votre valeur ? Splendide.\n\nIl y a de nombreuses tâches à accomplir, ici et autour de cette cité, qui représentent de grands défis pour quelqu'un d’aussi talentueux que vous.\n\nCe test ne doit pas être pris à la légère, &lt;nom&gt;. Comme à de nombreuses occasions le long de notre chemin, il peut nous coûter la vie. L'Eglise doit maintenir son statut, mais elle comprend les sacrifices que les paladins font en son nom.\n\nVous êtes prêt ?", rewards = "Vous recevrez :\n\n"},
[1650] = {title = "Le Tome de la bravoure", objective = "Trouver Daphne Stilwell dans la marche de l'Ouest", description = "Bien ! Votre engouement est le signe que vous êtes <prêt/prête> et montre votre enthousiasme à commencer le test. Ainsi soit-il ! \n\nA l'extrémité de Longrivage, dans la marche de l'Ouest, une petite maison donne sur l'océan. C’est la demeure du couple Stilwell. Jordan, un très bon forgeron, est parti à Ironforge voir les nains. Mais il a laissé Daphne, sa femme, seule et sans protection.\n\nDes rapports disent que les Défias ont envahi cette zone : Daphne aura peut-être besoin de protection. Allez là-bas.", progress = nil, completion = "Bonjour, &lt;nom&gt;. A voir votre armure et vos armes, j'en déduis soit que vous avez l’intention de voler mes terres, soit que l'Eglise m'a enfin envoyé quelqu'un pour me protéger pendant l'absence de Jordan.\n\nBien, laissez-moi me présenter : je suis Daphne Stilwell. C'est un plaisir.\n\nEh bien, vous n'êtes pas trop en retard... J'ai seulement occis une demi-douzaine de cette racaille depuis ce matin. Ils ont fait un détour pour venir ici, ce qui les a ralentis, mais maintenant qu'ils vous ont vu arriver, ils vont rappliquer ici dans quelques minutes.", rewards = "Vous recevrez :\n\n"},
[1651] = {title = "Le Tome de la bravoure", objective = "Défendez Daphne Stilwell contre les attaques des Défias.\n\nAucun de vous deux ne doit mourir, si vous voulez réussir la quête.\n\nQuand vous aurez réussi, reparlez à Daphne Stilwell.", description = "Je suis sûre qu'ils seront là dans peu de temps maintenant, préparez-vous.\n\nJ'ai une arme à la maison. Je vais la chercher et je reviens vous donner un coup de main, mais vous allez devoir faire le plus gros du travail j'en ai peur.\n\nJe n'ai aucune idée de leur nombre, mais pour sûr ils seront plus nombreux que la dernière fois.\n\nPriez la Lumière de vous accorder ses faveurs parce que... Vous avez entendu ça ? Je pense qu'ils arrivent.\n\nNous allons nous replier près de la maison !", progress = "Nous prendrons position à côté de la maison !", completion = "Nous avons réussi, &lt;nom&gt; ! Merci de votre aide. Vous avez été vraiment incroyable. Je n'aurais jamais cru qu'un &lt;classe&gt; puisse contenir autant d'ennemis à la fois.\n\nVous avez montré votre bravoure face à cette force écrasante.", rewards = "Vous recevrez :\n\n"},
[1652] = {title = "Le Tome de la bravoure", objective = "Parler à Duthorian Rall à Stormwind.", description = "S'il vous plaît, retournez voir Duthorian et dites-lui que je suis saine et sauve. Et c'est grâce à vous et à l'Eglise.\n\nJe vais envoyer un mot à Jordan à Ironforge pour lui dire de ne pas s'inquiéter. Oh qu'il me manque ! J'ai hâte qu'il revienne.", progress = nil, completion = "Alors, nous nous rencontrons à nouveau, &lt;nom&gt;, et vous êtes en grande forme, à ce que je vois.\n\nLa maison des Stilwell est hors de danger pour l'instant, et d'après votre rapport le danger n'était pas des moindres. Félicitations !\n\nDaphne et Jordan ont beaucoup aidé l'Eglise, et protéger leur ferme (et leur vie) était le moins que l'on puisse faire.\n\nVotre bravoure sera récompensée.", rewards = "Vous apprendrez :\n\nDétection des morts-vivants\n\nVous allez être la cible du sort suivant :\n\nDétection des morts-vivants\n\nVous recevrez également :\n\nBastion de Stormwind"},
[1653] = {title = "Le test de droiture", objective = "Parler à Jordan Stilwell à Ironforge", description = "Je pense que Jordan voudra vous remercier lui-même, et comme j'ai besoin de quelqu'un pour lui porter le message disant que sa femme est en sécurité, ce serait bien que vous le lui apportiez.\n\nJordan a été un paladin de la Lumière avant que son dévouement au métier de son père le fasse changer de voie. Il connaît nos coutumes et il est considéré parmi nos meilleurs fidèles.\n\nIl doit être encore à Ironforge. Dans la journée, il aime travailler hors de l'enceinte de la ville, sans doute pour profiter du grand air de la montagne.", progress = nil, completion = "Bonjour, &lt;nom&gt;. La Lumière est avec vous, n'est-ce pas ?\n\nQu'est-ce donc ? Duthorian vous envoie ? Ma femme, comment va-t-elle ? Je savais qu'il y aurait des problèmes si je partais. Dites-moi qu'elle... Que la Lumière soit louée ! Je suis si content qu'elle soit saine et sauve. Les Défias étaient une menace bien avant ces attaques, maintenant les conseillers du roi ne peuvent plus le nier.\n\nQu'est-ce que Duthorian voulait me dire d'autre ?\n\nC'est vous qui avez protégé ma femme ? Alors je vous remercie deux fois plus, &lt;nom&gt;. On ne peut avoir de meilleur test de bravoure.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1654] = {title = "Le test de droiture", objective = "Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Ironforge.", description = "J'aimerais vous récompenser, si vous voulez bien l'accepter ? Ne vous y trompez pas, ma générosité sera tributaire de votre contribution, mais je sens que cette association sera bénéfique pour nous deux.\n\nJe vous fabriquerai une arme à la hauteur de vos actions, un symbole des paladins et de la Lumière, mais vous devez me procurer les composants dont j'ai besoin pour la forger. J'ai déjà fait la liste de ce qui est nécessaire, il manquait juste une personne de qualité comme vous pour me les procurer. Qu'en pensez-vous, <classe> ?", progress = "Les objets de la liste sont très difficiles à se procurer, mais je vous assure que l'arme que je vais vous fabriquer en vaut la peine.\n\nCela sera mon chef-d'œuvre, mais ce sera bien peu de chose en comparaison de ce que vous, vous avez fait pour moi.", completion = "C'est formidable ! Vous avez récupéré tout ce dont j'ai besoin.\n\nJe ne vais pas avoir de mal à vous forger une merveilleuse arme. J'avais l'intention d’en faire une un jour, mais je n'avais jamais réussi à réunir tous les composants. Merci, &lt;nom&gt;.\n\nÇa fait du bien d'avoir à nouveau le marteau de mon père... Et une Gemme de Kor, je n'avais jamais pensé en voir une un jour.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1655] = {title = "Cargaison de minerai de Bailor", objective = "Apporter la Cargaison de minerai de Jordan à Bailor Stonehand au Loch Modan.", description = "Ach, vous m'avez fait peur <homme/femme> ! Vous ne pouviez pas remarquer que j'étais perdu dans mes pensées ?\n\nQu'est-ce que c'est ? La cargaison de Jordan... pour Ironforge. Ahhh, ouais, j'vois de quoi vous parlez ! Les ogres Mo'grosh... z'ont volé la cargaison de minerai d'mon vieil ami. La caravane venant des Paluns a été attaquée. Le garde qui avait survécu est mort il y a quelques jours : le soigneur n'est pas arrivé à temps.\n\nSi vous voulez la cargaison, faut que vous alliez au nord-est à travers le Loch. Elle est quelque part par là.", progress = "Alors, z'avez eu de la chance ? Ha ha ! Sont pas commodes ces ogres, hein ?", completion = "Hé hé, le voilà ! Ah ! Si j'avais su que vous alliez dehors combattre ces ogres, j'vous aurais donné une petite liste de choses dont j'ai besoin. Mais bon, vous n'êtes pas là pour faire des affaires avec moi, hein ?.\n\nUn marché est un marché ; Jordan voulait un chargement de mon alliage et il va l'avoir.\n\nDites-lui bonjour de ma part, et faites attention à vous, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nCargaison de minerai raffiné de Jordan"},
[1656] = {title = "Une tâche inachevée", objective = "Livrer le Ballot de fourrures à l'aubergiste Kauth au village Bloodhoof.", description = "<nom>, s'il vous plaît, je vous en supplie, pouvez-vous m'aider ? Je n'ai pas fini ce que j'ai à faire ici sur le Plateau – je suis au milieu de mon rite de force – et mon père veut que je livre ces fourrures à l'auberge de Bloodhoof.\n\nJe ne suis pas suffisamment reposée pour finir mon rite et faire ce que mon père m'a demandé. Cela vous embêterait-il d'y aller pour moi ?\n\nL'auberge est agréable et c'est l'endroit parfait pour se reposer après un long voyage. Vous en conviendrez lorsque vous l'aurez vue.", progress = "Oui ? Qu'est-ce que Kauth peut faire pour vous ?\n\nLe voyage depuis le Plateau peut être épouvantable pour certains, et réchauffer le cœur des autres. Ce qui est votre cas j'espère ?", completion = "Ah ! Les fourrures que j'attendais. Merci.\n\nElles sont arrivées plus tôt que prévu. Cela va faire de bonnes couvertures pour tous ceux qui voudront dormir ici.\n\nRestez autant que vous le voulez. Mon auberge est toujours ouverte, et tout le monde y est bienvenu. Ne sous-estimez pas une bonne nuit de sommeil, elle peut faire la différence quand vous devez voyager.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMorceau de pain rassisEau de source\n\nVous recevrez également :\n\n"},
[1657] = {title = "Empuantir Southshore", objective = "Lancer trois Boules puantes des Réprouvés au milieu de Southshore en Hillsbrad, puis revenez voir la sombre imploratrice Yanka à la Fête de l’homme d’osier, aux Clairières de Tirisfal.", description = "Nous allons célébrer la Sanssaint en grande pompe… en en faisant voir de toutes les couleurs à nos ennemis de Southshore !\n\nPrenez l’une de ces boules puantes conçues spécialement pour l’occasion. Elle est remplie d’une substance nauséabonde dont aucun humain - ou aucune bête à l’esprit simple, d’ailleurs - ne peut supporter l’odeur. Il faut la jeter au beau milieu de Southshore pour qu’elle agisse correctement, donc attendez-vous à combattre l’Alliance !\n\nQuand vous aurez accompli cette tâche… cet hommage à notre libération, revenez me voir !", progress = nil, completion = "Ah, bien joué ! J’espère que l’Alliance s’étranglera sur le cadeau puant que nous lui avons envoyé, comme nous avons été étranglés par le joug de l’esclavage du Fléau !\n\nVous avez bien célébré l’esprit de la Sanssaint, &lt;nom&gt;, et je vous en remercie. En petit bonus, laissez-moi vous offrir ces quelques bonbons de la Sanssaint. Je pense que vous les trouverez très amusants !", rewards = "Vous recevrez :\n\nBonbon à la citrouille de la Sanssaint"},
[1658] = {title = "Un intrus à la Fête de l'homme d'osier", objective = "Allez voir la Fête de l'homme d'osier des Réprouvés dans les clairières de Tirisfal. Revenez voir le sergent Hartman à Southshore quand ce sera fait.", description = "J’ai besoin de personnes courageuses pour se rendre aux clairières de Tirisfal, et voir comment se déroule la Fête de l’homme d’osier. Je ne vais pas vous mentir, aller là-bas sera dangereux : les gardes de faction lors de la fête seront exceptionnellement brutaux. Cependant, nous devons absolument connaître l’ampleur des festivités, et la gravité des problèmes que les Réprouvés nous causeront durant la Sanssaint.\n\nSi vous vous sentez d’attaque, dirigez-vous vers Tirisfal et espionnez les Réprouvés. Revenez me voir avec des informations, et je m’assurerai que vous recevrez une compensation convenable.", progress = nil, completion = "Bien joué, &lt;nom&gt;. La Fête de l’homme d’osier continuera à nous poser des problèmes tant que l’on laissera ces abominables Réprouvés hanter les ruines de Lordaeron. Ce n’est PAS un hommage convenable pour cette terre qui fut autrefois un fier royaume, je peux vous le dire…\n\nVoici quelques pièces pour payer les réparations dont vous pourrez avoir besoin, et pour rester dans l’esprit de la Sanssaint, j’y ai ajouté quelques friandises que vous apprécierez peut-être. Joyeuse Sanssaint… et essayons de la rendre la plus sûre possible à Southshore.", rewards = "Vous recevrez :\n\nBonbon à la citrouille de la Sanssaint"},
[1661] = {title = "Le Tome de noblesse", objective = "Parler à Duthorian Rall, à Stormwind.", description = "Encore bonjour, <nom>. Je suis encore plus fier de vous appeler <frère/soeur> qu’avant ; votre dévouement est une bénédiction pour nous tous.\n\nLe temps est venu de vous accorder une grande récompense. Sachez que je vous donne cela gratuitement, mais que plus tard, les défis qu’auront à accomplir les paladins qui voudront réaliser mes quêtes seront autrement plus exigeants.\n\nReparlez-moi plus tard et je vous accorderai une grande faveur.", progress = nil, completion = "Félicitations ! Que la Lumière vous protège.", rewards = "Vous apprendrez :\n\nInvocation d'un cheval de guerre\n\nVous allez être la cible du sort suivant :\n\nInvocation d'un cheval de guerre"},
[1665] = {title = "Tasse de Bartleby", objective = "Apporter la Tasse de Bartleby à Burlguard.", description = "Ok, voilà ma tasse. Attendez ! Laissez-moi finir avant... Ok, allez-y !", progress = "J'ai vu votre combat contre Bartleby. Bien joué ! Avez-vous eu sa tasse ?", completion = "Et voilà ! Je suis sûr qu'il ne voulait pas s'en séparer, mais vous avez été persuasif. Bien joué.\n\nMaintenant pour votre leçon...", rewards = "Vous allez être la cible du sort suivant :\n\nVoie de Protecteur\n\nVous recevrez :\n\n"},
[1666] = {title = "Le maréchal Haggard", objective = "Parler au maréchal Haggard.", description = "Vous avez appris quelques passes d'armes, mais il faudrait utiliser une arme décente. Je parie que si vous parliez au maréchal Haggard il pourrait vous aider.\n\nLe maréchal Haggard habite dans un manoir dans la forêt d'Elwynn, au Camp de bûcherons du Val d'est. Il est à la retraite, mais il a accumulé beaucoup d'équipements quand il était en activité.\n\nDites-lui que vous venez de ma part, et avec un peu de chance il aura une arme en trop à vous offrir.", progress = nil, completion = "Qui est là ? Burlguard, c'est vous ? Rapprochez-vous un peu. Mes yeux ne sont plus aussi bons qu'avant. A marcher comme ça, je vous avais pris pour un gnoll !", rewards = "Vous recevrez :\n\n"},
[1667] = {title = "Jack Dent-Morte", objective = "Retrouver la Plaque du maréchal Haggard au Camp de Jack Dent-Morte, et la rapporter au maréchal Haggard.", description = "Burlguard vous a dit de passer ? Oui, j'ai des armes en trop ici, mais avant vous devez faire quelque chose pour moi...\n\nIl y a quelque temps un scélérat défias appelé Jack Dent-Morte m'a escroqué. Il faisait sombre et il portait un tabard de Stormwind, j'ai cru que c'était le maréchal Dughan. Il m'a dit qu'il avait besoin de mon ancienne plaque de Maréchal de Stormwind et je lui ai donnée... Alors il a éclaté de rire et s'est enfui avant que je puisse l'attraper !\n\nRapportez-moi ma plaque ! Jack Dent-Morte a probablement un camp secret dans le sud.", progress = "Avez-vous ma plaque ? Je ne veux pas penser aux mauvais coups que Jack Dent-Morte pourrait faire avec.", completion = "Bien, vous l'avez trouvée ! J'avais peur de ne jamais la revoir, et qu’un Défias l’utilise pour se faire passer pour un officiel de Stormwind. Enfin cela ne se produira pas, merci à vous.\n\nVoici quelques armes que j'ai utilisées quand j'étais maréchal. Je les ai gardées en bon état. Servez-vous !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de HaggardMarteau d'HaggardDague de HaggardEpée de Haggard\n\nVous recevrez également :\n\n"},
[1678] = {title = "Vejrek", objective = "Apporter la Tête de Vejrek à Muren Stormpike à Ironforge.", description = "Si vous voulez rejoindre les rangs des guerriers, vous avez intérêt à être robuste. Je peux vous apprendre de nouvelles passes d'armes, mais avant prouvez-moi que vous pouvez vous débrouiller contre des adversaires réels.\n\nVejrek est le plus coriace des trolls du coin ; c'est lui que vous devez affronter. Il a une hutte dans les collines au sud du repaire des Frostmane\n\nRapportez-moi sa tête et je saurai que vous avez du courage.", progress = "Vous avez trouvé la hutte de Vejrek, <nom> ? Est-ce que c'est cette puanteur de troll que je sens ?", completion = "Vejrek était vraiment laid, hein ? Beau travail, &lt;nom&gt; ! Vous avez ce qu'il faut, maintenant commençons la leçon...\n\nVous ne le savez peut-être pas, mais il est très important pour un &lt;classe&gt; d'avoir une bonne défense. Cela lui permet de résister contre les ennemis quand les autres sont tombés, c'est ce dont un allié a besoin.", rewards = "Vous allez être la cible du sort suivant :\n\nVoie de Protecteur\n\nVous recevrez :\n\n"},
[1679] = {title = "Muren Stormpike", objective = "Parler à Muren Stormpike.", description = "Bonjour guerrier ! Vous êtes <voué/vouée> à un grand avenir, mais il vous reste quelques petits trucs à apprendre et Muren Stormpike est le nain qu'il vous faut pour vous les enseigner.\n\nVous trouverez Muren dans le Hall des Armes à la Garde militaire d'Ironforge. Parlez-lui quand vous serez <prêt/prête> à apprendre ce qu'est un vrai guerrier.", progress = nil, completion = "Ah, &lt;nom&gt; ! J'ai entendu des guerriers de Dun Morogh parler de vous. J'espère que vous n'avez pas passé vos journées à traîner dans les brasseries !", rewards = "Vous recevrez :\n\n"},
[1680] = {title = "Tormus Deepforge", objective = "Parler à Tormus Deepforge.", description = "Maintenant que vous avez appris de nouvelles passes, il est temps pour vous d'avoir une arme digne de ce nom. Parlez à Tormus Deepforge. Il peut vous fabriquer une arme dont vous me donnerez des nouvelles.\n\nVous trouverez Tormus ici, à Ironforge, à la Grande Forge.", progress = nil, completion = "Muren vous a dit de passer n'est-ce pas ? Oui, je fabrique de bonnes armes... Mais avant cela, j'ai une faveur à vous demander.\n\nNe vous inquiétez pas. C'est dangereux et ça peut vous coûter la vie : exactement le genre de boulot qu'un &lt;classe&gt; attend.", rewards = "Vous recevrez :\n\n"},
[1681] = {title = "Base d'Ironband", objective = "Rapporter du Minerai d'Umbral à Tormus Deepforge à Ironforge.", description = "Mon mentor, Sturgy Ironband, a une base au sud du lac du Lit d'Helm, à l'est de Dun Morogh. Il est maître forgeron, et c'est le meilleur.\n\nMais un jour, un de ses apprentis lui a apporté un étrange minerai. Le maître Ironband l'a baptisé \"minerai d'Umbral\" et s'est empressé de le travailler. Mais au moment où il était sur le point d’aboutir, une bande de nains Sombrefer a attaqué sa base. Ils ont tué tout le monde !\n\nAllez à la Base d’Ironband, <nom>, vengez la mort du maître, et rapportez-moi une cargaison de minerai d'Umbral.", progress = "Avez-vous trouvé la Base d'Ironband ? Avez-vous le Minerai d'Umbral ?", completion = "Vous l'avez trouvé ! Bien joué !\n\nJ'espère que vous avez tué des tas de nains Sombrefer. Il y en a sûrement ailleurs qu’à la Base d'Ironband...\n\nMais merci pour le minerai, &lt;nom&gt;. Je vais étudier ses propriétés et essayer de le travailler.", rewards = "Vous recevrez :\n\n"},
[1682] = {title = "Armes en fer gris", objective = "Voici quelques armes, tout juste sorties de la forge. Elles sont faites avec le Minerai d'Umbral que vous m'avez apporté !\n\nS'il vous plaît, <nom>, servez-vous !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache d'UmbralMasse d'UmbralDague d'UmbralEpée d'Umbral\n\nVous recevrez également :\n\n"},
[1683] = {title = "Vorlus Vilehoof", objective = "Rapporter la Corne de Vorlus Vilehoof à Elanaria à Darnassus.", description = "Avant de vous apprendre quoi que ce soit, vous devez me prouver votre résolution.\n\nLe satyre Vorlus Vilehoof a découvert un de nos lointains Puits de lune, au sud-est du Refuge des saisons de Ban'ethil. Il est en train d’y barboter, souillant l'eau pure avec sa crasse.\n\nTrouvez Vorlus au Puits de lune et détruisez-le. Ramenez-moi sa corne comme preuve, et je vous entraînerais.\n\nLe chemin vers le Puits de lune est bien caché, <nom>, restez <concentré/concentrée> et alerte, et vous le trouverez.", progress = "Avez-vous la corne, <nom> ? Est-ce que notre Puits de lune est débarrassé de Vorlus ?", completion = "Beau travail, &lt;nom&gt;. Il est bon de savoir que Vorlus est mort et que notre Puits de lune a retrouvé sa quiétude ; il est bon de savoir que les jeunes guerriers s'empressent de garder notre cher Teldrassil à l’abri de la corruption.\n\nMaintenant commençons votre entraînement...", rewards = "Vous allez être la cible du sort suivant :\n\nVoie de Protecteur\n\nVous recevrez :\n\n"},
[1684] = {title = "Elanaria", objective = "Parler à Elanaria.", description = "Bonjour, <guerrier/guerrière> ! Vos compétences progressent, mais il y a plus à savoir sur votre métier que vous ne le pensez. Pour continuer à progresser il vous faudra bientôt trouver un Maître.\n\nLa guerrière Elanaria réside à Darnassus, à la Terrasse des guerriers. Elle peut vous former.", progress = nil, completion = "Bonjour, &lt;nom&gt;. Votre nom est connu à Darnassus en tant qu'élément prometteur. Mais nous allons bientôt savoir si vous avez la volonté de suivre le chemin du &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[1685] = {title = "Convocation de Gakin", objective = "Aller voir Gakin le Tisse-noir dans le quartier des mages de Stormwind.", description = "N'est-ce pas toujours ainsi ? Je vous ai <cherché/cherchée> partout aujourd'hui et je n'ai pas pu vous trouver, et maintenant que je n'ai plus besoin de vous, vous venez me voir. !\n\nJ'ai perdu assez de temps à vous chercher, je ne vais donc pas vous faire attendre plus longtemps. Maître Gakin vous convoque pour une autre leçon. Il me semble que vous devriez y aller immédiatement.\n\nVous le trouverez au sous-sol de « l'Agneau assassiné ». Au fait, pas un mot : je préférerai que l’endroit reste tranquille.", progress = nil, completion = "Enfin vous vous montrez ! J'aurais peut-être dû envoyer quelqu'un de plus compétent que Remen pour vous trouver.\n\nCe n'est pas grave.\n\nCela fait trop longtemps que vous n'avez pas eu d'entraînement, et un &lt;classe&gt; sans entraînement ne garde pas la tête sur ses épaules très longtemps.", rewards = "Vous recevrez :\n\n"},
[1686] = {title = "L'Ombre d'Elura", objective = "Apporter 8 Caisses de Minerai d'Elunite et le Médaillon d'Elura à Elanaria à Darnassus.", description = "Vous avez appris beaucoup, <nom>. Maintenant nous allons vous fabriquer une arme. Une arme de <guerrier/guerrière>.\n\nPour cela, vous devez aller à Sombrivage.\n\nIl y a bien longtemps, un bateau s'est brisé sur les rochers près du phare d'Auberdine, éparpillant ses caisses de minerai d'Elunite au fond de l'océan.\n\nTout d'abord, vous devez vaincre la gardienne de l'Elunite : l'Ombre d'Elura. C'était le capitaine du bateau, elle s'est condamnée elle-même à errer au fond de l'océan pour protéger la cargaison à jamais. Combattez-la, récupérez son médaillon, et remonter toutes les caisses de minerai.", progress = "Avez-vous battu l'Ombre d'Elura, <nom> ? Avez-vous le minerai perdu ?", completion = "Très bien, &lt;nom&gt; !\n\nL'Ombre d'Elura repose en paix grâce à vous, et nous allons utiliser l'Elunite pour fabriquer votre arme.", rewards = "Vous recevrez :\n\n"},
[1687] = {title = "Le phare hanté", objective = "Emmenez l'orphelin voir le phare sur la côte de la marche de l'Ouest.", description = "Des fois, tard le soir, les gouvernantes de l'orphelinat nous racontent des histoires qui font peur. C'est GENIAL ! Il y en a une à propos d'un fantôme qui hante un phare dans la marche de l'Ouest. C'était un pirate à qui d'autres pirates ont pris son bateau. Waou !\n\nVous pourriez m'emmener au phare de la marche de l'Ouest ? Je veux voir le fantôme du capitaine ! Je resterai près de vous, c'est promis, je ne m'enfuirai pas ni rien...", progress = nil, completion = "OUAH, c'était un fantôme pour de vrai ! C'était terrible ! Vivement qu'on rentre à l'orphelinat pour que je l'raconte à tout le monde. Le capitaine Grayson... Même qu'il ressemblait à un vrai pirate ! Quand je serai grand, moi aussi je veux devenir un pirate fantôme !\n\nMerci de m'avoir emmené à la marche de l'Ouest, &lt;nom&gt;. Je sais qu'il y a des trucs effrayants dans ce coin, et j'espère que je ne vous ai pas trop embêté. Vous êtes génial !", rewards = "Vous recevrez :\n\n"},
[1688] = {title = "Surena Caledon", objective = "Retrouver l’Écharpe de Surena pour Gakin le Tisse-noir à Stormwind.", description = "J'ai eu une étudiante du nom de Surena Caledon. Elle était là où vous êtes en ce moment, enthousiaste à apprendre la magie des démonistes, et talentueuse. En plus, elle était jeune et belle. Quand j'y repense, quelle traînée !\n\nCette voleuse s'est enfuie avec un Defias, Erlan Drudgemoor. Sa perte est négligeable, mais je lui avais offert une Echarpe de Pierre de sang que je veux absolument récupérer.\n\nSa vie m'importe peu maintenant. Vous la trouverez au Champ de Potirons des Brackwell. Rapportez-moi ce qui m'appartient.", progress = "Même le plus âgé et le plus sage peut être déstabilisé par la jeunesse et la beauté, <nom>. C'est une chose dont vous devez vous souvenir tout au long de votre vie.", completion = "Surena était talentueuse, mais pas assez pour acquérir la maîtrise de la magie des démonistes par elle-même. Quel dommage de devoir gâcher ce talent ! Mais c'est parfois nécessaire.\n\nJ'espère qu'avec vous ce sera différent…", rewards = "Vous recevrez :\n\n"},
[1689] = {title = "Le lien", objective = "Utiliser l’Echarpe de Pierre de sang pour invoquer et soumettre un marcheur du Vide, puis la rapporter à Gakin le Tisse-noir, à Stormwind.", description = "En retrouvant mon écharpe et en éliminant Surena, vous avez prouvé que vous étiez au moins aussi <talentueux/talentueuse> qu'elle.\n\nCela dit, vous avez terriblement besoin d'entraînement. Vous pouvez manier les flux magiques, bien sûr, mais être démoniste, c'est bien plus que cela.\n\nJe vais vous montrer comment contrôler un marcheur du Vide, mais avant, vous devez en invoquer un dans le cercle d'invocation et le maîtriser avec les armes – physiques et magiques – dont vous disposez. Utilisez la magie que contient l'écharpe sur le cercle d'invocation en bas.", progress = "Je ne peux pas vous montrer comment contrôler un marcheur du Vide si vous n'en avez pas invoqué et maîtrisé un d’abord.", completion = "Vous avez fait mieux que ce à quoi je m’attendais, &lt;nom&gt;, mais aussi bien que je l'espérais. Maintenant, vous pouvez apprendre comment contrôler un marcheur du Vide, c'est un allié précieux pour traverser les épreuves.\n\nJe n'ai plus rien à vous apprendre aujourd’hui, mais je n'en ai pas fini avec vous, &lt;nom&gt;.", rewards = "Vous apprendrez :\n\nInvocation d'un marcheur du Vide\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un marcheur du Vide\n\nVous recevrez également :\n\n"},
[1690] = {title = "Châtier les Bat-le-désert", objective = "Abattre 10 Bandits et 10 Larrons Bat-le-désert à l'est de Gadgetzan, puis revenir au rapport auprès de l'ingénieur en chef Bilgewhizzle.", description = "Vous là-bas ! Il est temps d'aider la Compagnie des Eaux de Gadgetzan.\n\nLes nomades Bat-le-désert de Tanaris se sont emparés de presque tous les puits ! Si nous ne pouvons pas y avoir accès, notre réserve d'eau va s'assécher en un clin d'oeil. Si vous voulez vous faire bien voir, aidez-nous à faire la loi contre ces nomades !\n\nAllez à l'est d'ici et abattez dix bandits et dix larrons Bat-le-désert, puis revenez immédiatement me faire votre rapport. La justice n'attend pour aucun homme... gobelin... bon, enfin bref, allez-y !", progress = nil, completion = "C'est ce que j'appelle être efficace ! Vous avez suffisament décimé les nomades pour que nous puissions essayer de nous réapproprier ces puits.\n\nLa Compagnie des Eaux de Gadgetzan vous remercie de votre aide, mais vous n'avez pas fini avec ces maudits nomades. Écoutez bien : voici ce qu'il faut faire maintenant...", rewards = "Vous recevrez :\n\n"},
[1691] = {title = "Continuer à châtier les Bat-le-désert", objective = "Tuer 10 Mages de l'ombre Bat-le-désert, 8 Voleurs Bat-le-désert et 6 Assassins Bat-le-désert pour l'ingénieur en chef Bilgewhizzle à Gadgetzan.", description = "Nous voulons que vous attaquiez les rangs les plus forts des nomades Bat-le-désert. Vous avez fait du bon travail jusque-là, mais pour reprendre ces puits, il faut affronter le moins possible de ces nomades !\n\nCette fois, il faut que vous éliminiez des voleurs, des assassins et des mages de l'ombre. Ils se trouvent à l'est et au sud-est d'ici.\n\nJe ne vais pas vous mentir, ils sont coriaces. Faites cela pour nous, et nous pourrons bientôt reprendre ce qui est nôtre.", progress = nil, completion = "Joli travail, &lt;nom&gt;… Joli ! Vous avez réduit le nombre des nomades à un point qui nous permet de les affronter !\n\nParlez à l'Opérateur du robinet Luglunket ici ; il donne une récompense pour chaque outre de Bat-le-désert prise lors de votre combat contre les nomades !", rewards = "Vous recevrez :\n\n"},
[1692] = {title = "Forgeron Mathiel", objective = "Apporter la Caisse d'Elunite au Forgeron Mathiel.", description = "J'ai mis l'Elunite que vous avez récupérée dans une caisse. Portez-la au Forgeron Mathiel, il fabriquera votre arme avec.\n\nMathiel est au sud, de l'autre côté de ce bâtiment.", progress = "Bonjour, <classe>. Comment puis-je vous servir ?", completion = "Ah ! Du minerai d'Elunite. C'est un métal délicat à travailler, il est béni par la déesse Elune elle-même. Cela va être un honneur d'en faire des armes.\n\nAttendez le temps que je travaille...", rewards = "Vous recevrez :\n\n"},
[1693] = {title = "Armes en Elunite", objective = "<nom>, j'ai fabriqué ces armes avec l'Elunite que vous m’avez apportée. Prenez celle qui vous convient.\n\nEt je dois vous remercier. Car travailler l'Elunite est un honneur et un plaisir.", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache d'EluniteMarteau d'EluniteDague d'EluniteEpée d'Elunite\n\nVous recevrez également :\n\n"},
[1698] = {title = "Yorus Barleybrew", objective = "Parler à Yorus Barleybrew.", description = "Yorus Barleybrew a lancé un défi à tous les guerriers de l'Alliance. Il attend à l'Auberge de Lakeshire, dans les Carmines, et promet une grande récompense à celui qui passera l'épreuve.", progress = nil, completion = "Ah ! Vous avez entendu parler de mon défi, n'est-ce pas ?\n\nBien. Asseyez-vous, prenez un verre et savourez-le... Car c'est peut-être le dernier.", rewards = "Vous recevrez :\n\n"},
[1699] = {title = "Le défi de Rethban", objective = "Entrer dans les Cavernes de Rethban jusqu'à la première fourche, et revenir voir Barleybrew dans le temps imparti.\n\nVous ne devez pas mourir.", description = "J'ai appelé cette épreuve le \"défi de Rethban\". Pour passer l'épreuve, tout ce que vous avez à faire c'est d'entrer dans les Cavernes de Rethban, jusqu'à la première fourche. Facile ! Sauf qu'il y a certaines conditions...\n\nVous devez être de retour dans moins d'une heure.\n\nEt il y a un tas de gnolls des Carmines sur le chemin.\n\nAvant de commencer, il faut que vous preniez une lampée de ma boisson personnelle : du Barleybrew Scalder !\n\nAlors qu'en dites-vous ? Les Cavernes de Rethban sont dans les collines, au nord de Lakeshire. Êtes-vous <prêt/prête> à relever le défi de Rethban ?", progress = "L'heure tourne, <nom>. Si j'étais vous, je partirais...", completion = "Vous l'avez fait ! Bien joué ! Hourra pour &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[1700] = {title = "Grimand Elmore", objective = "Porter les Notes de Furen à Grimand Elmore.", description = "J'ai pris des notes sur les techniques que j'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie à Grimand Elmore. Il est ici dans le quartier des nains, au Magasin d'armes.\n\nEt attention quand vous lui donnerez mes notes. Il est extrêmement fier de ses compétences, et il n'aimera pas l'idée que je puisse lui apprendre quelque chose...", progress = "Bonjour et bienvenue. Que puis-je faire pour vous ?", completion = "Furen a écrit ça ? Comment ose-t-il ? C’est moi qui lui ai tout appris ! Penser qu'il puisse m'apprendre quelque chose est scandaleux ! Scandaleux !\n\nHum... Mais il y a quelque chose dans ses notes que j'aimerais tenter...", rewards = "Vous recevrez :\n\n"},
[1701] = {title = "Une cotte de mailles en acier trempé", objective = "Réunir les matériaux dont Furen Longbeard a besoin et lui apporter à Stormwind.", description = "Alors je vous ai donné un bon bouclier, mais on ne va pas s'arrêter là. Je connais le secret pour fabriquer une Cotte de mailles extrêmement résistante. C'est difficile à faire et demande des matériaux très rares, mais si vous voulez faire le travail sur le terrain, alors je vous en fabriquerais une.\n\nQu’en dites-vous, <nom> ? Vous relevez le défi ? Je vais donc vous donner la liste des éléments dont j'ai besoin et où les trouver.", progress = "Comment se passe la chasse aux charognards, <nom> ? Avez-vous les matériaux dont j'ai besoin ?", completion = "Vous avez tout ? Incroyable ! J'avais peur que ces chimères ne vous mangent !\n\nTrès bien, commençons cette armure...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1702] = {title = "Fabricant de bouclier", objective = "Apporter le Tonneau de Scalder à Furen Longbeard.", description = "Vous avez montré vos talents en relevant le défi de Rethban, <nom>. Et je respecterai ma parole. Je vais vous donner votre récompense...\n\nSauf qu'elle est à Stormwind.\n\nParlez à mon ami, Furen Longbeard, dans le quartier des nains de Stormwind. C'est le meilleur fabriquant de boucliers que vous rencontrerez, et il me doit une faveur.\n\nTenez, apportez-lui ce tonneau de Barleybrew Scalder et demandez-lui un bouclier. Il vous en donnera un bon.", progress = "Bonjour ! Temps sec, ne trouvez-vous pas ?", completion = "Ah ! De la Barleybrew Scalder. Quelle aubaine ! C'est que vous avez vu Yorus, hein ?\n\nJe peux vous avoir un bouclier, ouaip m’sieur ! Vous ne pourrez pas en trouver de mieux, sans blague !", rewards = "Vous recevrez :\n\nFaveur de Furen"},
[1703] = {title = "Mathiel", objective = "Apporter les Notes de Furen à Mathiel.", description = "J'ai pris des notes sur les techniques que j'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie au Forgeron Mathiel. Il vit à Darnassus, assez loin d'ici, mais je suis sûr qu'il sera reconnaissant de pouvoir apprendre ce que j'ai appris.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[1704] = {title = "Klockmort Spannerspan", objective = "Apporter les Notes de Furen à Klockmort Spannerspan.", description = "J'ai pris des notes sur les techniques que j'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie à Klockmort Spannerspan. C'est un Forgeron gnome d’Ironforge et quand il lira mes découvertes, je parie qu'il s'arrachera la barbe.", progress = "Bonjour, ou bonsoir. Je ne sais même plus qu'elle heure il est. Vous avez quelque chose pour moi ?", completion = "Oh D... ! Ces notes sont étonnantes ! Et même plus... elles sont incroyables, stupéfiantes, mes jambes en tremblent !\n\nFuren a fait une découverte ! Une réelle découverte ! Je ne peux pas attendre pour l'essayer !", rewards = "Vous recevrez :\n\n"},
[1705] = {title = "Le sang ardent", objective = "Rapporter 20 Fioles de sang ardent et 1 Roc ardent à Grimand Elmore à Stormwind.", description = "Je déteste l'admettre, mais Furen a fait une découverte impressionnante. Mais pour être sûr je dois l'essayer moi-même sur une armure. Si vous me procurez le matériel, <nom>, alors vous pourrez en avoir une.\n\nPour faire cette armure, il me faut des échantillons de sang ardent et du roc ardent.\n\nLe seul endroit où je sais en trouver est le bois de la Pénombre. Les worgens Plaie-de-nuit basés dans la mine du Destin de Roland ont du sang ardent, et leur chef, Videssac, devrait avoir le Roc.\n\nQue la chance soit avec vous, <nom> !", progress = "<nom>, avez-vous le Sang et le Roc ardents ? J'en ai besoin pour terminer l'armure.", completion = "Beau travail ! Maintenant veuillez m'excuser, je dois aller travailler...", rewards = "Vous recevrez :\n\n"},
[1706] = {title = "L'armure de Grimand", objective = "Je peux à peine le croire ! La technique de Furen fonctionne, et cette armure peut résister à des coups incroyables.\n\nVoilà pour vous, <nom>. Et merci. Je n'y aurais pas cru si vous ne m'aviez pas apporté les éléments nécessaires pour le tester moi-même.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCamail en acier trempé"},
[1707] = {title = "Prime de la poche à eau", objective = "Apporter 5 Outres de Bat-le-désert à l'Opérateur de robinet Luglunket à Gadgetzan.", description = "Salutations, <nom>. Mon nom est Luglunket, et nous avons un travail important à vous confier si vous vous sentez d'attaque ! Houzza !\n\nIl n'y a rien qui me ferait plus plaisir, en tant qu'Opérateur du robinet expérimenté, que de récupérer les outres de Bat-le-désert que vous trouverez dans le désert. C'est notre eau de toute façon : les nomades l'ont juste volée ! La Compagnie des Eaux de Gadgetzan vous offre un paquet pour cinq outres que vous ramenez. Encore plus important : venir en aide à Gadgetzan, c'est l'aider à se venir en aide !", progress = "Vous avez les cinq outres de Bat-le-désert qu'il nous faut ? Si oui, le paquet modèle 103-XB de la Compagnie des Eaux de Gadgetzan, vous appartient !", completion = "Excellent : plus nous récupérons d'outres, moins nous risquons le désastre ! Apportez-en encore, et je vous récompenserai pour chaque lot de cinq outres que vous rapporterez.", rewards = "Vous recevrez :\n\nPaquet de la Co. des eaux Gadgetzan"},
[1708] = {title = "Le corail de fer", objective = "Apporter 20 Coraux torrides à Klockmort Spannerspan à Ironforge.", description = "Je veux essayer la nouvelle technique de Furen Longbeard sur une de mes pièces d'armure. Et parce que vous avez aidé Furen et qu'il m'a aidé, je vous offrirai l'armure que j’aurai fabriquée !\n\nPour faire la pièce, j'ai besoin d'un corail spécial, du corail torride. Il pousse à un seul endroit : le long des côtes au sud du port de Menethil dans les Paluns.\n\nApportez-moi suffisamment de corail torride et je pourrai fabriquer l'armure. Et dépêchez-vous, <nom>. Je suis impatient de commencer !", progress = "Bonjour, bonjour, <nom> ! Avez-vous le corail torride ? Je n'en peux plus d'attendre !", completion = "Voilà c'est ça ! Bien joué ! Maintenant, laissez-moi travailler et appliquer les méthodes de Furen et nous verrons le résultat !\n\nOh ! Ça alors ! Par exemple ! Je sais juste que l'armure sera très très très, TRÈS résistante !", rewards = "Vous recevrez :\n\n"},
[1709] = {title = "La création de Klockmort", objective = "Voilà votre armure, <nom>. Le procédé de Furen fonctionne à la perfection ! À la perfection ! Merveilleux, vraiment !\n\nVous pourriez rouler sur cette armure avec un engin de siège, elle reprendrait sa forme en un instant !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGantelets en acier trempé"},
[1710] = {title = "Coquilles desséchées au soleil", objective = "Apporter 20 Coquilles desséchées au soleil à Mathiel à Darnassus.", description = "Mon collègue, Furen Longbeard, a fait une découverte que je suis impatient d'essayer. Je veux la tester sur une de mes nouvelles armures, car je pense que les techniques de Furen me permettraient d’améliorer la qualité de mes produits.\n\nVoulez-vous m'aider ? Si vous me ramenez de quoi fabriquer l'armure, alors j'en ferai une pour vous.\n\nJ'ai besoin de coquilles d'œuf desséchées au soleil des wyvernes Aile-fière qui résident au Haut-perchoir, dans les Mille pointes. Cherchez les coquilles au pied de leurs nids, et revenez quand vous en aurez assez.", progress = "Avez-vous les coquilles, <nom> ? Elles sont très résistantes et peuvent être transformées en laque que j'appliquerai sur les mailles de ma nouvelle cotte.", completion = "Ah merci ! Cela fonctionne parfaitement !\n\nJe vais faire l'armure immédiatement...", rewards = "Vous recevrez :\n\n"},
[1711] = {title = "L'armure de Mathiel", objective = "J'ai fini votre armure, et j'en suis satisfait. Les techniques de Furen cadrent parfaitement avec les miennes et je suis sûr que cette armure est extrêmement résistante.\n\nMerci, <nom>. Et qu'elle vous serve pour vos combats futurs !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières en acier trempé"},
[1712] = {title = "Cyclonien", objective = "Apporter les objets du Parchemin de Bath'rah à Bath'rah la Vigie des vents à Alterac.", description = "J'ai passé un temps considérable à observer ce site. J'observe… Je verrai peut-être tomber le Grand Cyclonien ! Mais je n'ai toujours pas trouvé un champion pour combattre le Seigneur des vents.\n\nPeut-être est-ce vous ?\n\nProuvez-le moi. Rassemblez les éléments dont j'ai besoin pour invoquer un Cyclonien, et je saurai que vous êtes <un grand guerrier/une grande guerrière>. Peut-être pouvez-vous le battre et récupérer son cœur de tourbillon.\n\nSi c'est le cas, alors je transmettrai le pouvoir du cœur dans une arme que je vous donnerai.\n\nVoilà le parchemin qui liste les objets dont j'ai besoin.", progress = "Avez-vous les objets, <nom> ? Les apporter prouvera que vous avez la force de combattre un Cyclonien.", completion = "Vous avez rassemblé les composants pour mon sort, et vous avez montré votre force et votre adresse. Mais la prochaine partie de notre quête est bien plus périlleuse.\n\nEspérons que votre force ne faiblira pas.", rewards = "Vous recevrez :\n\n"},
[1713] = {title = "L'invocation", objective = "Rapporter le Cœur de tourbillon à Bath'rah la Vigie des vents.", description = "Je suis prêt à faire mon rituel pour invoquer un Cyclonien. Quand il apparaîtra, vous devez l'abattre et lui prendre son Cœur de tourbillon. Je l'utiliserai pour faire une arme qui possédera les pouvoirs du Cyclonien.\n\n<nom>, êtes-vous <prêt/prête> à affronter le Maître des vents ?", progress = "<nom>, je dois avoir le Cœur de tourbillon !", completion = "Vous avez réussi ! Vous avez vaincu le Cyclonien et récupéré son Cœur de tourbillon !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1714] = {title = "Essence d'exil", objective = "Le chaudron bouillonne. Ces vapeurs attirent...", description = nil, progress = "Le chaudron bouillonne. Ces vapeurs attirent...", completion = "Le charme s'enfonce lentement dans le chaudron...\n\nUne grosse bulle se forme à la surface du liquide et éclate...\n\n... Et un morceau de roche en fusion apparaît.", rewards = "Vous recevrez :\n\nEssence d'exil"},
[1715] = {title = "L'Agneau assassiné", objective = "Aller voir Gakin le Tisse-noir dans le quartier des mages de Stormwind.", description = "Hum ! Dans le temps, tous les démonistes de Khaz Modan étaient entraînés par les maîtres de Gnomeregan, mais maintenant que nous avons été forcés de nous réfugier dans ce trou à rats qu'est Ironforge, et que Magni a décidé de nous surveiller, nous sommes forcés d'envoyer les novices étudier à Stormwind.\n\nHeureusement, Gakin n'est pas un empoté, vous pourrez donc continuer à recevoir un enseignement, mais cela m'exaspère !\n\nEnfin, vous trouverez Gakin au sous-sol de « l'Agneau assassiné » à Stormwind.", progress = nil, completion = "Blackwrench vous envoie ? Il faut mettre les choses au point avec ces fichus démonistes d'Ironforge. Il y a tellement de Maîtres à Stormwind ! Avec tout ce trafic, on est sûr d'attirer l'attention un jour ou l'autre.", rewards = "Vous recevrez :\n\n"},
[1716] = {title = "La dévoreuse d'âmes", objective = "Parler à Takar le Prophète dans les Tarides.", description = "Les Sayaad dévorent les âmes, dominent les esprits et séduisent sans distinction. Ils ne connaissent rien d’autre que le Mal.\n\nLa littérature grivoise les désigne par leur nom populaire, à savoir succubes pour les démons femelles et incubes pour les mâles.\n\nPour attirer une telle créature, vous allez devoir l’appâter à l’aide d’un symbole d’amour. Ensuite, vous n’aurez plus qu’à la maîtriser avant d’en faire votre esclave.\n\nIl va toutefois être difficile de vous procurer un objet de cette nature. Vous devriez parler à Takar le Prophète. Vous le trouverez dans les Tarides de Kalimdor, près du camp Taurajo.", progress = nil, completion = "Votre traversée a-t-elle été difficile, &lt;nom&gt; ? Vous avez fait un long voyage pour venir me parler. Ne vous inquiétez pas, je sais pourquoi Gakin vous a envoyé, et c'est sage de sa part, car je peux vous aider dans vos recherches.", rewards = "Vous recevrez :\n\n"},
[1717] = {title = "Convocation de Gakin", objective = "Aller voir Gakin le Tisse-noir dans le quartier des mages de Stormwind.", description = "<nom> ! Je ne pensais pas vous trouver ici, mais on m'a demandé de vous chercher.\n\nIl est temps pour vous de reprendre l'entraînement, vous devez aller voir Gakin la prochaine fois que vous passerez à Stormwind. Il vous attend.", progress = nil, completion = "Je suis ravi que quelqu'un ait pris soin de vous, &lt;nom&gt;. Je commençais à m'inquiéter. Cela aurait été une honte de vous perdre, après tout le temps que j'ai investi en vous.\n\nMais nous parlerons plus tard. Votre entraînement est la seule chose importante en ce moment.", rewards = "Vous recevrez :\n\n"},
[1718] = {title = "L'île mortelle", objective = "Parler à Klannoc Macleod.", description = "Votre renommée en tant que <guerrier/guerrière> s'accroît, <nom>. Il est temps de vous mesurer à l'un de vos pairs.\n\nIl existe une île près des côtes des Tarides, au sud de Ratchet : l'île de la Dispute. Les guerriers s’y retrouvent.\n\nS’y retrouvent et s’affrontent.\n\nParlez au chef des guerriers de l'île, Klannoc Macleod. S’il pense que vous le méritez, alors il vous guidera plus avant sur la voie du guerrier.\n\nPour atteindre l'île de la Dispute, cherchez des bancs de sable à faible profondeur le long de la Côte des marchands.", progress = nil, completion = "Salut, &lt;classe&gt; ! C'est bon de voir que vous avez atteint l'île de la Dispute. J'espère que vous allez recevoir une bonne raclée...", rewards = "Vous recevrez :\n\n"},
[1719] = {title = "La Dispute", objective = "Tuer le Grand Will et parler à Klannoc Macleod sur l'île de la Dispute.", description = "Si vous voulez que je sois votre Maître, vous devez d'abord passer la Dispute. C'est une épreuve que nous, sur l'île de la Dispute, aimons faire passer aux guerriers qui pensent être forts, et si vous réussissez ce test alors nous saurons que vous l'êtes.\n\nPour commencer, marchez à travers cette foule là-bas, et allez jusqu'à l'âtre. Dites à Twiggy Flathead que vous êtes <prêt/prête>, il vous enverra des partenaires de combat.\n\nBattez-les tous, et il appellera le Grand Will. Tuez le Grand Will, et revenez me voir.", progress = "Avez-vous réussi l’épreuve ?", completion = "Bien joué, &lt;nom&gt;. Vous avez passé la Dispute !\n\nVous êtes un vaillant &lt;classe&gt;, et c'est un honneur d'être votre Maître...", rewards = "Vous allez être la cible du sort suivant :\n\nVoie du berserker\n\nVous recevrez :\n\n"},
[1738] = {title = "Le cœur du bois", objective = "Trouver le Cœur du bois en Ashenvale et le porter à Gakin le Tisse-noir dans le quartier des mages de Stormwind.", description = "En prévision de votre arrivée, j'ai utilisé ma vision pour regarder à travers le monde et à travers le temps. J'ai trouvé ce que vous cherchez.\n\nLors de la guerre des Anciens, deux amoureux sont tombés ensemble lors d'une bataille. Là où ils sont morts, un arbre connu sous le nom de cœur du bois poussa, symbole de leur amour éternel.\n\nCe sera assez pour attirer une succube. Vous le trouverez dans les ruines d'Ordil'Aran, dans la partie nord-ouest de la forêt d'Ashenvale.", progress = "Avez-vous réussi, <nom> ?", completion = "Oui, cela conviendra parfaitement. Laissez-moi le travailler juste un peu...\n\nTakar est quelqu'un d'utile à connaître, n'est-ce pas ? Si seulement vous pouviez le persuader de revenir à la civilisation…", rewards = "Vous recevrez :\n\n"},
[1739] = {title = "Le lien", objective = "Utiliser le Noyau du cœur du bois pour invoquer et soumettre une succube, puis rapporter le Noyau de cœur du bois à Gakin le Tisse-noir, à l'Agneau assassiné.", description = "En utilisant le noyau du cœur du bois, vous serez en mesure de jeter le sort dans le cercle d'invocation qui se trouve dans la crypte en bas afin d'ouvrir un portail d'où la succube arrivera.\n\nAttention, <nom>, les succubes arrivent à contrôler les esprits les plus forts.\n\nUne fois que vous l'aurez vaincue et renvoyée dans le néant, revenez me voir pour que je vous apprenne comment l'appeler et la contrôler.", progress = "Parfois je me demande si Surena n'était pas une succube déguisée, envoyée pour pervertir et fausser mon esprit... Ha ! Je la surestime, sans doute.", completion = "Bien joué, &lt;nom&gt;. Je vois que j'ai eu raison de vous entraîner. Vos résultats ne me décevront pas.\n\nJe n'ai aucune appréhension à vous montrer comment contrôler votre succube. Observez attentivement.", rewards = "Vous apprendrez :\n\nInvocation d'une succube\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'une succube\n\nVous recevrez également :\n\nPetite bourse d'âme"},
[1740] = {title = "L'Orbe de Soran'ruk", objective = "Trouver 3 Fragments de Soran'ruk et 1 Grand Fragment de Soran'ruk et les rapporter à Doan Karhan dans les Tarides.", description = "Quand les démons de la Légion sont tombés, leurs esprits furent emprisonnés dans des orbes et distribués à leurs mages et leurs démonistes.\n\nBeaucoup furent apportés en Azeroth par leurs serviteurs. Même fragmentés, ils gardent les pouvoirs du démon emprisonné à l'intérieur.\n\nL'orbe de Soran'ruk a été brisé en deux morceaux, l'un a été fragmenté pour être utilisé par les acolytes du Marteau du crépuscule dans les Profondeurs de Brassenoire. L'autre, le plus gros morceau, est en possession d'un sorcier dans le donjon d'Ombrecroc. Retrouvez les fragments et je pourrai réparer l'orbe.", progress = "Cela m'a pris des années pour réunir les morceaux de l'orbe de Zargain, mais cela m'a été très utile, je suis certain que l'orbe de Soran'ruk vous servira aussi.", completion = "Oui... L'orbe n'est pas trop fragmenté et les morceaux sont presque tous réunis. Cela va être assez simple de le reconstituer pour rendre son intégrité à Soran'ruk.\n\nJ'ai consacré ma vie à étudier les orbes de la Légion ardente. Vous m'avez rendu service en récupérant ces morceaux pour me permettre de les étudier. Je vais vous les rendre, rassemblés sous la forme de votre choix.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe de Soran'rukBâton de Soran'ruk\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[1758] = {title = "Tome de la Cabale", objective = "Parler à Krom Stoutarm à Ironforge.", description = "Il faudra plus qu'un simple cercle d'invocation pour attirer un chasseur corrompu et le défier.\n\nMes trois acolytes et moi-même allons vous aider à créer les cercles magiques. Vous aurez besoin d'un exemplaire du Tome de la Cabale, qui a été perdu depuis bien des années. L’ouvrage a été écrit par le premier groupe de démonistes pour invoquer seul un chasseur corrompu.\n\nKrom Stoutarm peut peut-être vous aider. Ce démoniste nomade passe son temps à accumuler des textes anciens et traîne parfois dans la bibliothèque à Ironforge.", progress = nil, completion = "Le Tome de la Cabale ? Hmm... Ça me dit quelque chose. Je ne l'ai jamais vu ici, et croyez-moi, je me souviens de tous les livres que j'ai lus.\n\nHmm...\n\nAh oui ! J'ai vu des références à ce livre dans le catalogue de la bibliothèque.", rewards = "Vous recevrez :\n\n"},
[1778] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge à Ironforge.", description = "Je vais devoir rentrer chez moi le plus rapidement possible. Heureusement, Stephanie fait de même pour rentrer à Stormwind. J'ai hâte de la revoir. A bientôt, <classe>.", progress = nil, completion = "Alors, vous revenez bien vite, hein ? Et qu'avez-vous accompli pendant ce temps ?\n\nAvez-vous participé à de nobles causes ? Vous avez peut-être appris la valeur de la charité ou compris votre devoir envers les citoyens d'Azeroth. Racontez-moi, qui avez-vous aidé et comment.... Impressionnant, &lt;nom&gt;, ce sont là, assurément, les actes d'une personne qui suit le chemin de la Lumière.\n\nCe genre de sacrifice est toujours récompensé un jour ou l'autre.", rewards = "Vous recevrez :\n\n"},
[1779] = {title = "Le Tome de divinité", objective = "Prendre le Symbole de vie et parler à Muiredon Battleforge à Ironforge.\n\nObjet fourni : \n", description = "Je veux que vous preniez ceci, <nom>. Cela s'appelle le Symbole de vie.\n\nVous avez montré que vous étiez charitable et <patient/patiente>, maintenant je veux que vous me montriez votre pouvoir et vos talents au combat en tant qu'adepte.\n\nMuiredon, mon mari, a rencontré récemment des nains Sombrefer, et il s'en est sorti de justesse. Il est à Ironforge, aux bons soins d’un de nos prêtres.\n\nPrenez le Symbole et parlez-lui. Si vous pouvez l'aider, alors nous nous reparlerons bientôt. Que la Lumière soit avec vous !", progress = nil, completion = "*Toux*\n\nBonjour à vous, &lt;classe&gt;. Ne vous inquiétez pas pour mes blessures, ce bon prêtre ici s'en est occupé à temps. Je n'aurai pas besoin de ce Symbole de vie que vous avez apporté, pas encore.\n\nAlors ma femme vous a demandé de venir me parler ? Très bien. Je vais prendre le temps de vous parler : je vais vous raconter ce qui est arrivé à Muiredon et à son meilleur ami Narm, un &lt;classe&gt; comme vous.", rewards = nil},
[1780] = {title = "Le Tome de divinité", objective = "Parler à Duthorian Rall à Stormwind.", description = "J'amènerai ça aux enfants dès aujourd'hui. Merci beaucoup, <classe>. Il est rare de nos jours qu'<un homme/une femme> de votre trempe se montre dans cette ville, mais vous avez prouvé que les paladins à Stormwind ne tourneront jamais le dos à ceux qui sont dans le besoin.\n\nAdieu.", progress = nil, completion = "Alors, vous revenez bien vite, &lt;nom&gt; ! Et qu'avez-vous accompli pendant votre absence de la Cathédrale ?\n\nAvez-vous participé à une noble cause ? Vous avez peut-être appris la valeur de la charité ou compris votre devoir envers les citoyens d'Azeroth. Racontez-moi, qui avez-vous aidé et comment.... Impressionnant, &lt;nom&gt;, ce sont là, pour sûr, les actes d'une personne qui suit le chemin de la Lumière.\n\nCe genre de sacrifice est toujours récompensé un jour ou l'autre.", rewards = "Vous recevrez :\n\n"},
[1781] = {title = "Le Tome de divinité", objective = "Porter le Symbole de vie à Gazin Tenorm à Stormwind.\n\nObjet fourni : \n", description = "Je veux que vous preniez ceci, <nom>. Cela s'appelle un Symbole de vie.\n\nVous avez montré que vous étiez charitable et <patient/patiente>, et maintenant il est temps de savoir si vous avez la puissance nécessaire pour contrôler un des plus grands dons de la Lumière.\n\nMon ami Gazin a croisé récemment des Défias à Elwynn près de la Veillée des héros – il s'en est sorti de justesse. Il est près de l'autel en train de se faire soigner par un de nos prêtres.\n\nPrenez le Symbole et parlez-lui. Si vous pouvez l'aider, alors nous nous reparlerons bientôt. Que votre chemin soit éclairé par la Lumière !", progress = nil, completion = "*toux*\n\nRavi de vous rencontrer, &lt;classe&gt;. Ne vous inquiétez pas pour mes blessures, ce bon prêtre s'en est occupé à temps. Je n'aurai pas besoin de ce Symbole de vie que vous avez apporté, pas encore.\n\nAlors, Duthorian vous a demandé de venir me parler, hein ? Gentil de sa part. Je vous raconterai ce qui nous est arrivé à moi et à mon ami Henze. Avec de la chance, et vos compétences, vous pourrez peut-être nous aider.", rewards = nil},
[1782] = {title = "L'armure de Furen", objective = "Voici votre armure, <nom>. Elle résistera au plus dur des coups ou je ne m'appelle pas Furen Longbeard !\n\nEt je dois vous remercier. J'ai beaucoup appris en travaillant les matériaux que vous m'avez apportés. Je pense que je ferai une autre découverte capitale un de ces jours !\n\nJe vais transmettre ce que j'ai appris aux autres forgerons de l'Alliance.\n\nJe leur dirai que vous m'avez été d'une grande aide, et peut-être qu'ils vous récompenseront.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nHaubert en acier trempé"},
[1783] = {title = "Le Tome de divinité", objective = "Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh.", description = "J'espionnais des nains Sombrefer qui se terrent au sud du lac du Lit d'Helm. Nous savions qu'ils n'étaient pas là pour rien, alors Narm et moi nous nous sommes rapprochés – assez près pour voir leur chef donner des ordres à ses hommes.\n\nNarm et moi nous avons tenté d'en tuer quelques-uns, mais ils se sont révélés plus résistants que nous le pensions, et beaucoup plus nombreux. Narm m'a dit de partir et de ramener du renfort, donc voilà pourquoi je suis là.\n\nNarm a besoin d'aide, et je ne me reposerai pas tant qu'il n'en n'aura pas trouvé.\n\nAllez-vous m'aider, <nom> ?", progress = nil, completion = "Je ne sais pas comment vous remercier, frère.\n\nParce que vous avez le Symbole de vie, je suppose que c'est Tiza et Muiredon qui vous ont envoyé. \n\nC'est vrai, je suis tombé sur les Sombrefer alors que j'essayais de parvenir à un de leurs scripts. J'ai réussi à tenir assez longtemps pour permettre à Muiredon de s'échapper, mais la Lumière m'avait accueilli depuis longtemps quand vous êtes arrivé. Le fait que vous ayez été assez puissant pour utiliser le Symbole signifie de bonnes choses pour vous, mais nous aurons le temps d'en parler plus tard.", rewards = "Vous recevrez :\n\n"},
[1784] = {title = "Le Tome de divinité", objective = "Récupérer un Script des nains Sombrefer près du lac du Lit d'Helm et le rapporter à Muiredon Battleforge à Ironforge.", description = "Avant de tomber, Muiredon et moi avions presque vaincu un des espions Sombrefer près de cette petite maison. Nous avons vu le capitaine leur passer des ordres, et nous avons cherché à le tuer pour récupérer ces ordres.\n\nCertaines personnes au conseil d'Ironforge ne croient pas à la présence des Sombrefer à Dun Morogh. En récupérant un de ces scripts, nous aurions non seulement la preuve de leur présence ici, mais nous aurions aussi une idée de ce qu'ils trament.\n\nRécupérez un de ces scripts et rapportez-le à Muiredon, <nom>.", progress = "Vous êtes de retour ! Je suis content de vous voir, <nom>. Mes blessures sont guéries et je suis prêt à repartir pour le lac du Lit d'Helm dès que j'aurai convaincu ma femme que je vais bien.", completion = "Ha ha ! Vous l'avez fait ! Vous avez sauvé Narm, et vous avez la preuve dont ma femme a besoin d'apporter au conseil. Vous êtes le meilleur représentant de la Lumière que j’ai jamais rencontré... sans compter ma femme bien sûr.\n\nMerci encore, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1785] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge à Ironforge.", description = "J'peux déjà voir l'visage d'ma femme s'illuminer de fierté. Vous devriez bouger vot'postérieur tout de suite et aller la voir. J'pense qu'elle aura des choses à vous dire.\n\nLa Lumière soit avec vous, <classe> ! Je vous reverrai sur l'champ de bataille contre le Fléau et ces damnés Sombrefer quand le temps viendra.", progress = nil, completion = "Vous avez rendu un grand service à Ironforge aujourd'hui, &lt;nom&gt;. Je suis fière de vous compter parmi nous et si vous vous sentez prêt, je vous remets ce parchemin. Le Symbole de vie a fonctionné parce qu’il était entre les mains d’un &lt;classe&gt; prêt à recevoir un des plus grands dons de la Lumière : le pouvoir de ramener un mort à la vie.\n\nJe vous enseignerai comment ressusciter vos compagnons. Utilisez-le sagement, &lt;nom&gt;, et merci, en mon nom, celui de mon mari et celui d'Ironforge.", rewards = "Vous apprendrez :\n\nRédemption\n\nVous allez être la cible du sort suivant :\n\nRédemption\n\nVous recevrez également :\n\n"},
[1786] = {title = "Le Tome de divinité", objective = "Apporter le Symbole de vie et ressusciter Henze Faulk à Elwynn.", description = "Henze et moi sommes allés à la Veillée des héros, une île au milieu du lac du Cairn au nord-est d'Elwynn. Nous avions entendu dire que des Défias avaient infiltré nos frontières et nous voulions le prouver aux conseillers du roi.\n\nNous en avons surpris en possession de documents, et nous les avons attaqués. Malheureusement, nous avons été rapidement submergés par des mages.\n\nHenze les a retenus pendant que je m'enfuyais... C’était cinglé de sa part, mais il était brave.\n\nIl est mort à présent. Pourriez-vous nous aider, <nom> ?", progress = nil, completion = "Merci, frère.\n\nPuisque vous détenez ce Symbole de vie, je suppose que vous êtes envoyé par Duthorian ou Gazin ?\n\nJe suis tombé sous les coups des mages défias tandis que Gazin et moi essayions de leur voler des documents. J'ai pu tenir assez longtemps pour permettre à Gazin de s'échapper, mais finalement leur magie a eu raison de moi.\n\nMais vous m’avez ramené ! Maîtriser le Symbole n'est pas donné à tout le monde, &lt;nom&gt;. Cela présage bien pour vous d'avoir pu l'activer grâce à votre foi.", rewards = "Vous recevrez :\n\n"},
[1787] = {title = "Le Tome de divinité", objective = "Retrouver un Script Défias sur les Sorciers-voleurs défias d'Elwynn et le rapporter à Gazin Tenorm à Stormwind.", description = "Nous aurons le temps de parler du Symbole plus tard. Ce qui importe c'est de récupérer les papiers que les Défias avaient sur eux. Si nous pouvons mettre la main dessus, nous serons en mesure de prouver que la Confrérie a infiltré Elwynn et nous aurons une idée de ce qu'elle trame.\n\nJe ne suis pas assez remis pour combattre maintenant, <nom>. Pensez-vous pouvoir récupérer <seul/seule> ces papiers dans l'île ?\n\nSi vous pouvez les récupérer, apportez-les à Gazin et dites-lui que je vais bien.", progress = "Est-ce que Henze est sauf, <nom> ? Avez-vous réussi ?\n\nEntre vos talents au combat et le pouvoir de la Lumière, j'imagine que la Veillée des héros est débarrassée de la menace des Défias, mais ça, c'est au roi et à ses conseillers qu’il faut le dire.", completion = "Merveilleux ! Vous l'avez fait, et vous avez sauvé Henze. La Lumière est assurément avec vous, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[1788] = {title = "Le Tome de divinité", objective = "Parler à Duthorian Rall à Stormwind.", description = "Je vais porter le Script aux conseillers du roi après que Duthorian y aura jeté un coup d'oeil, ensuite allez parler à Duthorian. Il voudra sûrement vous féliciter !\n\nMerci encore, <nom>. J'espère que l'on se reverra. Je suis fier de vous avoir comme <allié/alliée>... et comme <ami/amie>.", progress = nil, completion = "Vous avez fait du bon travail aujourd'hui, &lt;nom&gt;. Vous devez être fier de ce que vous avez accompli.\n\nEt même plus, vous devez être fier de vos compétences. Il n'est pas donné à tout le monde de pouvoir utiliser le Symbole de vie. Implorer la Lumière pour ramener quelqu'un d'entre les morts signifie que vous êtes prêt à recevoir l'un des plus grands honneurs qu'un &lt;classe&gt; puisse connaître : le pouvoir de résurrection.\n\nVous avez le pouvoir de ramener à la vie vos compagnons tombés au combat, comme vous l'avez fait pour Henze.\n\nPartez en paix, &lt;nom&gt;. Que la Lumière brille sur vous et recevez-la en votre sein.", rewards = "Vous apprendrez :\n\nRédemption\n\nVous allez être la cible du sort suivant :\n\nRédemption\n\nVous recevrez également :\n\n"},
[1789] = {title = "Le Symbole de vie", objective = "Si vous n'arrivez pas à aider Narm en utilisant le Symbole de vie, <nom>, alors revenez me voir et je vous en procurerai un autre.\n\nIl est important pour mon mari et moi que vous y arriviez. S'il vous plaît, hâtez-vous.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSymbole de vie"},
[1790] = {title = "Le Symbole de vie", objective = "Hâtez-vous, <nom>, de nombreuses vies seront en danger si vous échouez.\n\nSi pour une raison quelconque vous n'arrivez pas à aider Gazin et Henze, revenez me voir et je vous donnerai un autre Symbole de vie pour cette entreprise.\n\nNe prenez pas cela pour de la charité : vous devez prouver que vous êtes un <classe> aussi brave que les autres, et des échecs répétés auraient des répercussions plus tard.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSymbole de vie"},
[1791] = {title = "La Vigie des vents", objective = "Parler à Bath'rah la Vigie des vents.", description = "À présent que vous avez appris la posture berserker, vous aurez besoin d'une belle arme avec laquelle l'utiliser.\n\nAllez parler à Bath'rah la Vigie des vents, un troll ermite qui vit entre les montagnes d'Alterac et les Maleterres de l'est. C'est un fabricant d'armes très versé dans son métier et un puissant chaman.\n\nPour le trouver, allez à la rivière qui coule le long du côté est de Moulin-de-Tarren. Remontez-la vers le nord. Bath'rah campe près des ruines jonchant la rive est de la rivière.", progress = nil, completion = "Vous avez voyagé bien loin, jeune &lt;classe&gt;. Je lis la fougue dans vos yeux. Vous cherchez une arme puissante, non ?\n\nJe peux vous aider dans votre quête. Et vous, pouvez-vous m'aider dans la mienne.", rewards = "Vous recevrez :\n\n"},
[1792] = {title = "Arme Tourbillon", objective = "J'ai le Cœur de tourbillon, et je suis prêt à le placer dans le réceptacle de votre choix.\n\nChoisissez l'arme, <nom>, et sachez que ce pouvoir est le pouvoir du Cyclonien.", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de tourbillonEpée de tourbillonMarteau de tourbillon\n\nVous recevrez également :\n\n"},
[1793] = {title = "Le Tome de la bravoure", objective = "Il a été prouvé que la Lumière était avec vous, <nom>, mais en ces temps de grands dangers, il est primordial de savoir quelles sont vos forces. Parce que des démons, des dragons et toutes sortes de créatures malfaisantes convoitent nos terres, votre courage sera mis à l'épreuve. Serez-vous assez fort ?\n\nLa bravoure, quelle que soit la situation, est une part importante de la voie du <classe>, au même titre que la Lumière, votre armure et votre arme. Quand vous étudiez dans la cathédrale de la Lumière, les deux leçons que vous devez apprendre sont : protéger les faibles et ne jamais perdre la foi.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTome de valeur"},
[1794] = {title = "Le Tome de la bravoure", objective = "Il a été prouvé que la Lumière était avec vous, <nom>, mais en ces temps de grands dangers, il est primordial de savoir quelles sont vos forces. Parce que des démons, des dragons et toutes sortes de créatures malfaisantes convoitent nos terres, votre courage sera mis à l'épreuve. Serez-vous assez fort ?\n\nLa bravoure, quelle que soit la situation, est une part importante de la voie du <classe>, au même titre que la Lumière, votre armure et votre arme. Quand vous étudiez dans la cathédrale de la Lumière, les deux leçons que vous devez apprendre sont : protéger les faibles et ne jamais perdre la foi.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTome de valeur"},
[1795] = {title = "Le lien", objective = "Utiliser le Tome de la Cabale pour invoquer et soumettre un Chasseur corrompu, puis rapporter le Tome de la Cabale à Strahad Farsan, à Ratchet.", description = "Si vous êtes suffisamment <préparé/préparée>, alors nous pouvons commencer. Laissez-moi vous expliquer la procédure.\n\nJe vais commencer par créer un simple cercle d'invocation. Quand j'aurai fini, mes acolytes vont utiliser leurs bâtonnets de canalisation pour créer un cercle majeur.\n\nLisez alors l'incantation du Tome de la Cabale, et le chasseur corrompu apparaîtra. Faites attention, <nom>. Un chasseur corrompu est un ennemi puissant, et j'aimerais que vous gardiez la tête sur les épaules.", progress = "Chaque <classe> devrait avoir un chasseur corrompu à ses ordres. Bien qu'il soit difficile d'en soumettre un, les pouvoirs qu’il confère à son maître en valent largement la peine.", completion = "Je dois dire que je suis impressionné, &lt;nom&gt;. Quand j'ai affronté mon chasseur corrompu, j'en ai tout juste réchappé. Je sens que vous avez le potentiel pour devenir un des plus puissants démonistes de notre époque.", rewards = "Vous apprendrez :\n\nInvocation d'un chasseur corrompu\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un chasseur corrompu\n\nVous recevrez également :\n\nBoîte d'âmes"},
[1796] = {title = "Les composants de la robe sanglante dorée enchantée", objective = "Apporter des Robes d’Arcana à Menara Voidrender dans les Tarides.", description = "Le premier objet que je vais vous aider à confectionner est une Robe. Vous rassemblerez ses composants pour moi, et nous les assemblerons ensemble. Après quoi, si tant est que vous aurez réussi, vous aurez les premiers des nombreux objets qui vous aideront dans vos luttes.\n\nMais pour commencer, vous devez avoir des Robes d'Arcana confectionnées. Un tailleur peut vous les faire, ou peut-être que vous pourriez en acheter à quelqu'un d'autre, mais cela m'impressionnerait que vous les confectionniez vous même. Quelle que soit la manière dont vous vous les procurerez, apportez-moi les robes, et nous commencerons.", progress = "Où en êtes-vous dans votre recherche de robes, <nom> ? Vous les avez créées vous-même ? Ces touches personnelles rendent l'imprégnation de la magie beaucoup plus douce, je trouve. Cela vous donne un grand sens de la prouesse. Mais je sais que si vous choisissez la méthode la plus rapide et que vous la faites faire - il faut louer une telle... ambition.", completion = "Cela sera parfait, &lt;nom&gt;.\n\nTous les objets magiques doivent être créés à partir d'un objet de haute qualité. Plus un objet est confectionné avec soin et habileté, plus il peut recéler de magie.Les composants les plus rares et les plus chers conservent mieux la magie. Vous ne regretterez pas de faire transformer ces robes comme nous le ferons pour vous plus tard.", rewards = "Vous recevrez :\n\n"},
[1798] = {title = "À la recherche de Strahad", objective = "Parler à Strahad Farsan dans les Tarides.", description = "Il est temps pour vous d'apprendre à invoquer un chasseur corrompu, <nom>. Je n'ai pas ni composants ni les objets nécessaires ici pour vous l'enseigner, donc adressez-vous à Strahad Farsan, un membre de notre communauté.\n\nIl réside dans le port gobelin de Ratchet. Je vais lui envoyer un message pour lui annoncer votre venue.", progress = nil, completion = "&lt;nom&gt; ? Ah, bien sûr ! Le petit prodige ! Mais la réalité n'est pas à la hauteur de la légende, j'en ai bien peur.\n\nLaissez tomber, vous êtes venu pour apprendre, pas pour écouter mes blagues…", rewards = "Vous recevrez :\n\n"},
[1799] = {title = "Fragments de l'Orbe d'Orahil", objective = "Parler aux acolytes de Menara dans la tour qui domine Ratchet et choisir de suivre l’une de leurs voies.\n\nEnsuite, apporter un Orbe infernal à Tabetha, dans le marécage d'Âprefange.", description = "Bien, alors commençons.\n\nAllez d'abord parler à mes acolytes à l’intérieur et choisissez l’une des voies qu’ils vous proposeront de suivre... Ils vous en diront davantage eux-mêmes.\n\nEnsuite, vous devrez voyager en Désolace et prendre un Orbe infernal sur l'un des démonistes du convent de Mannoroc. C’est cet orbe que vous purifierez avec l’aide d’un mage du nom de Tabetha, au sud du marécage d'Âprefange. Elle vous aidera en souvenir de notre histoire commune.\n\nNe revenez pas avant d’avoir accompli les deux tâches que j’ai requises auprès de vous.", progress = "De toute évidence, vous n'êtes pas un mage, je me demande si je peux vous faire confiance. Je peux sentir le pouvoir des Arcanes en vous, mais vous avez l'air d'avoir éliminé l'odeur infecte de la corruption qui accompagne généralement les membres de votre espèce.\n\nOui, un  <classe>... un <classe> est venu requérir mon aide.\n\nBien, que puis-je faire pour vous, <nom> ?", completion = "Ainsi, c'est Menara qui vous envoie. Gentil de sa part... Je suppose que vous êtes maintenant mon invité. Enfin, j'imagine qu'une mission urgente vous appelle. Seriez-vous à la recherche de pouvoirs perdus ? Peut-être la corruption est-elle plus proche de vous qu'il n'y paraît.", rewards = "Vous recevrez :\n\n"},
[1800] = {title = "La salle du trône de Lordaeron", objective = "Emmenez votre protégé à la vieille salle du trône de Lordaeron, qui se trouve juste avant l'endroit où il faut descendre pour aller à Undercity.", description = "La gouvernante de l'orphelinat, à la maison, nous raconte de grandes histoires de bataille et de sagesse, si nous sommes gentils et que nous avons fait nos corvées. Une histoire raconte la chute de Lordaeron, et comment le maléfique Arthas a assassiné son père pour devenir le chef.\n\nIl n'avait pas d'honneur, <nom> ! Quand je serai grand, je serai un puissant guerrier de la Horde, et ma lame sera guidée par l'honneur - jamais par le mal !\n\nVous voulez bien m'emmener voir la salle du trône, s'il vous plaît ? C'est juste avant l'endroit où il faut descendre pour aller à Undercity.", progress = nil, completion = "La salle du trône était terrible, &lt;nom&gt; ! Même si je savais qu'elle était vide, j'avais l'impression qu'un grand malheur avait eu lieu, là-bas. Je me suis senti fou de rage... mais triste, aussi. Je comprends pourquoi la gouvernante nous raconte toutes ces histoires. Je ne trahirai jamais mon peuple comme ça !\n\nMerci de m'avoir emmené à la salle du trône, &lt;nom&gt;. J'ai beaucoup appris.", rewards = "Vous recevrez :\n\n"},
[1801] = {title = "Tome de la Cabale", objective = "Parler à Jorah Annison à Undercity.", description = "Il va falloir plus qu'un simple cercle d'invocation pour appeler le chasseur corrompu que vous allez affronter.\n\nMes trois acolytes et moi allons vous assister pour créer les cercles magiques. Vous avez besoin d’un exemplaire du Tome de la Cabale, qui a été perdu depuis bien des années. Il a été écrit par le premier groupe de démonistes pour invoquer seul un chasseur corrompu.\n\nPeut-être que Jorah Annison peut vous aider. En ce moment, il est employé comme cartographe à Undercity, mais il en connaît plus que quiconque sur les textes anciens.", progress = nil, completion = "Faire des cartes ! Des illustrations, des estimations de la réalité. Cela ne me plaît pas du tout.\n\nDans les livres, les récits, les descriptions, c’est là que se trouve la vérité. J'échangerais toutes les cartes de ce magasin contre un seul livre sur l'ascension de la nécromancie, ou l'histoire du triomphe de la Dame noire.", rewards = "Vous recevrez :\n\n"},
[1802] = {title = "Tome de la Cabale", objective = "Retrouver le Tome moisi et le Manuscrit en lambeaux pour Krom Stoutarm à Ironforge.", description = "Il a été perdu, mais j'ai une petite idée d’où il se trouve.\n\nIl n’en existe qu’un seul exemplaire, en très mauvais état : déchiré à plusieurs endroits et en grande partie arraché de la reliure. La rumeur dit que cette partie serait entre les mains des centaures des Mille pointes.\n\nL’autre partie a été perdue sur la côte ouest de Southshore, alors qu’elle était envoyée par bateau au port de Menethil. Elle n'est jamais arrivée à destination.\n\nEn échange de ces informations, tout ce que je demande c'est que vous le trouviez, et que vous me l'apportiez afin de le voir.", progress = "Est-ce que les rumeurs étaient vraies, <nom> ?", completion = "Fantastique ! Je vais rejoindre les rangs des privilégiés qui ont eu la chance de le lire.\n\nJe suis vraiment impatient. C’est un grand jour, &lt;nom&gt; ! J’aimerais y jeter un coup d'oeil avant que vous ne partiez. Je suis sûr que Strahad m’en fera envoyer une copie.", rewards = "Vous recevrez :\n\n"},
[1803] = {title = "Tome de la Cabale", objective = "Retrouver le Tome moisi et le Manuscrit en lambeaux pour Jorah Annison à Undercity.", description = "Ah ! Je vois que vous avez les mêmes goûts de démoniste que moi. Vraiment, vouloir récupérer le Tome de la Cabale est une noble intention. Saviez-vous qu'il était autrefois à Lordaeron ? Mais il a été abîmé, presque la moitié des pages ont été arrachées. Qui a pu faire une chose pareille ?\n\nUne rumeur circule à propos de cette moitié perdue : on dit qu’elle serait entre les mains des centaures des Mille pointes.\n\nLe reste a été envoyé à Ironforge, mais a été perdu lors de son transport sur la côte ouest de Southshore.", progress = "Vous allez peut-être poursuivre des chimères, <nom>, mais il y a toujours une part de vérité dans les rumeurs.", completion = "Bien bien bien ! Qu'est-ce que nous avons là ?\n\nC'est impressionnant, &lt;nom&gt;. Je ne pensais pas que cela serait possible, mais il est vraiment là dans mes mains, le Tome de la Cabale en intégralité.\n\nPermettez-moi d’y jeter un coup d'oeil avant que vous ne l'emportiez.", rewards = "Vous recevrez :\n\n"},
[1804] = {title = "Tome de la Cabale", objective = "Apporter le Tome recomposé et 3 Bâtonnet de canalisation à Strahad Farsan à Ratchet.", description = "Ah ! C'est difficile de le laisser partir. Mais vous l'avez trouvé et vous avez des choses importantes à faire avec. S’il vous plaît, dites bien à Strahad que j'en veux une copie !\n\nPendant que vous étiez <parti/partie>, il vous a envoyé un message. Les acolytes qui vont participer à l'invocation ont besoin de trois Bâtonnets de canalisation, vous devez les trouver.\n\nIl ne sait peut-être pas où les chercher, mais moi si ! Les derniers à en avoir utilisé étaient des orcs du clan Dragonmaw dans les Paluns, leurs magiciens doivent en posséder…", progress = "Ça fait longtemps que vous êtes parti. Avez-vous trouvé le tome et les bâtonnets ?", completion = "Bien joué ! Le Tome de la Cabale et trois bâtonnets de canalisation en parfait état – enfin légèrement rayés.\n\nVoilà qui va être intéressant. Cela fait longtemps qu'un jeune &lt;classe&gt; n'a pas fait sien un chasseur corrompu.", rewards = "Vous recevrez :\n\n"},
[1805] = {title = "Tome de la Cabale", objective = "Apporter le Tome recomposé et 3 Bâtonnets de canalisation à Strahad Farsan à Ratchet.", description = "C'est l'un des textes les plus intéressants que j'ai parcouru au cours de ces dernières années. Ici, il n'y a pas grand-chose, à part des livres de géographie, que j'ai déjà tous lus... Strahad m'en enverra peut-être une copie, quand il le pourra... \n\nÀ propos, il vous fait dire que pour remplir votre mission, il vous faudra trois bâtonnets de canalisation. \n\nPour vous remercier de m'avoir laissé regarder ce texte, laissez-moi vous confier un secret : vous trouverez ces bâtonnets sur les orcs du clan Dragonmaw dans les Paluns.", progress = "Oui, <nom> ? En quoi puis-je vous être utile ?", completion = "Bien joué ! Le Tome de la Cabale et trois bâtonnets de canalisation en parfait état – enfin légèrement rayés.\n\nVoilà qui va être intéressant. Cela fait longtemps qu'un jeune &lt;classe&gt; n'a pas fait sien un chasseur corrompu.", rewards = "Vous recevrez :\n\n"},
[1806] = {title = "Le test de droiture", objective = "Attendre que Jordan Stilwell finisse de forger votre arme.", description = "Pourquoi n'irions-nous pas à la forge pour commencer ? J'ai préparé votre arrivée depuis quelque temps déjà et tout devrait être prêt.\n\nAprès cela, vous serez mieux <préparé/préparée> que jamais pour défendre la Lumière, je vous le promets.\n\nJe dois vous avouer, <nom>, que je suis un peu envieux de votre réussite. Mais sachez que de pouvoir participer à ma manière à cette réussite me remplit d'aise.", progress = nil, completion = "Et voilà, &lt;nom&gt;. Une arme que mérite un serviteur de la Lumière tel que vous. Je l'ai baptisée en mémoire d'un ami, un célèbre &lt;classe&gt; nain. Il s'appelait Verigan... Bosch Verigan. Prenez-la en mon nom et celui de ma femme, nous vous devons tant. Le monde va devenir plus sûr maintenant que vous êtes là…", rewards = "Vous recevrez :\n\nPoing de Verigan"},
[1818] = {title = "Parler à Dillinger", objective = "Parler au Garde noir Dillinger à Brill.", description = "J'ai entendu dire que Dillinger le Garde noir avait un travail pour quelqu'un comme vous. Si vous voulez prouver votre valeur aux forces de la Dame noire, alors présentez-vous devant Dillinger immédiatement.\n\nLe poste de Dillinger le Garde noir est à la frontière ouest de Brill, près du cimetière.", progress = nil, completion = "Vous êtes ici pour une mission ? Bien. J'en ai une importante, une qui testera votre habileté au combat... Et votre résolution à défendre les Réprouvés.", rewards = "Vous recevrez :\n\n"},
[1819] = {title = "Ulag le Fendeur", objective = "Tuer Ulag le Fendeur, puis parler au Garde noire Dillinger.", description = "Lorsque le Fléau s'est abattu sur les Clairières de Tirisfal, nous avons capturé l'un de ses serviteurs pour l'étudier. C'était un esprit libre, qui se nommait Ulag le Fendeur. Pourtant, malgré sa libre conscience, le roi-liche avait gardé son emprise sur lui.\n\nNous espérions trouver un moyen de le délivrer de cette influence, mais nous avons échoué. Il est temps de le libérer, maintenant... \n\nLibérez-le et tuez-le.\n\nEn actionnant le déclencheur de la Pierre du Crâne devant le Mausolée qui se trouve au nord, vous briserez le sceau magique qui le lie.\n\nAprès... Il faudra frapper vite et fort, <nom> !", progress = nil, completion = "Bien joué, &lt;nom&gt;. Ulag n'était pas une piétaille du Fléau. Vous avez montré aux Gardes noirs, et donc à la Dame noire, que vous êtes un &lt;classe&gt; compétent et résolu, et digne de remplir d'autres missions.", rewards = "Vous allez être la cible du sort suivant :\n\nVoie de Protecteur\n\nVous recevrez :\n\n"},
[1820] = {title = "Parler à Coleman", objective = "Parler à Coleman Farthing.", description = "Vous avez prouvé votre valeur à la Dame noire, à présent vous pourrez peut-être la prouver à l'un de ses sujets.\n\nColeman Farthing cherche un guerrier pour être son bras vengeur contre les ennemis des Réprouvés.\n\nVous le trouverez à « la Taverne des Pendus » dans l'est de Brill.", progress = nil, completion = "Oui, c'est vrai ! J'ai besoin des talents d’un &lt;classe&gt;. J'ai des moyens modestes, mais la tâche à accomplir m'aidera autant qu'elle aidera la cause des Réprouvés. Faites-le, et votre récompense sera double.", rewards = "Vous recevrez :\n\n"},
[1821] = {title = "L'héritage des Agamand", objective = "Rapporter à Coleman Farthing la Hache de la famille Agamand, l'Epée de la famille Agamand, la Masse de la famille Agamand et la Dague de la famille Agamand.", description = "J'ai servi la famille Agamand tout le long de ma vie et ils ont été la cause de ma mort ! S'ils sont maintenant les esclaves du roi-liche, ce n'est que justice ! \n\nÀ présent, je dois m'approprier les derniers vestiges de leur honneur perdu. Dans leur crypte, je veux que vous voliez leur héritage familial : une épée, une hache, une dague et une masse, et que vous me les apportiez. \n\nLa Crypte de la famille Agamand se trouve à la lisière nord des Moulins d'Agamand, sous la protection d'un Fléau errant et des Agamands morts.", progress = "Avez-vous l'héritage, <nom> ?", completion = "Ah ! Vous les avez trouvées ! Maintenant le peu d'honneur et de mémoire qu'il restait est sorti des terres maudites des Agamand. Cette famille n'est plus rien à présent !", rewards = "Vous recevrez :\n\n"},
[1822] = {title = "Une arme en héritage", objective = "Je garderai trois de ces armes en souvenir de ce que j'ai perdu et souffert. Je voudrais que vous choisissiez celle que vous préférez pour vous-même, <nom>. \n\nPuisse-t-elle vous servir à de plus nobles actions que celles de son précédent propriétaire, ce maudit !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de l'héritierMarteau de l'héritierDague de l'héritierEpée de l'héritier\n\nVous recevrez également :\n\n"},
[1823] = {title = "Parler à Ruga", objective = "Parler à Ruga Ragetotem.", description = "Vous êtes un guerrier compétant à la renommée croissante. Peut-être êtes-vous <prêt/prête> pour l'épreuve de Ruga Ragetotem ? Si c'est le cas, alors allez trouver Ruga au Camp Taurajo dans les Tarides.\n\nIl cherche des guerriers qui accepteraient de passer son épreuve.", progress = nil, completion = "Êtes-vous ici pour mon épreuve, &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[1824] = {title = "L'épreuve du Champ des géants", objective = "Apporter 5 Antennes mobiles à Ruga Ragetotem au Camp Taurajo.", description = "Pour passer l'épreuve, vous devez voyager vers le sud jusqu'au Champ des géants. Là-bas, vous trouverez un grand nombre d'insectes rampants. Ils sont récemment arrivés dans les Tarides et je pense que cela ne présage rien de bon.\n\nApportez-moi leurs antennes mobiles, et ne perdez pas de temps, <nom>. Ces antennes ne remuent pas longtemps. Apportez-les-moi dans le temps alloué, et vous aurez passé l'épreuve.", progress = "Vous avez les antennes ? Si oui, donnez-les-moi vite, parce que les antennes mobiles ne le restent pas éternellement…", completion = "Bien joué, &lt;nom&gt; ! En passant l'épreuve du Champ des géants, vous avez fait un pas de plus sur le chemin des guerriers.", rewards = "Vous recevrez :\n\nBouclier de Ruga"},
[1825] = {title = "Parler à Thun'grim", objective = "Parler à Thun'grim Firegaze dans les Tarides.", description = "Thun'grim Firegaze, un forgeron orc de grande renommée, a entendu parler de vos exploits au service de la Horde. Il voudrait vous confectionner un équipement d'armure et vous propose d'aller en discuter immédiatement avec lui.\n\nThun'grim campe à l'est de la Croisée dans les Tarides.", progress = nil, completion = "Oui, vous êtes là ! C'est bien, nous avons beaucoup à nous dire, vous et moi.", rewards = "Vous recevrez :\n\n"},
[1838] = {title = "Armure de brutalité", objective = "Apporter à Thun'grim Firegaze 15 Lingots de Fer cendré, 10 Azurites en poudre, 10 Barres de Fer et une Fiole de Phlogiston.", description = "J'ai entendu parler de votre force et de votre courage, et je voudrais faire pour vous une armure complète qui vous aidera à mesure que vos exploits passeront à la postérité.\n\nMais faire une armure est une véritable quête en soi <nom>, et je vais avoir besoin de votre aide et de celle d'autres forgerons de la Horde.\n\nTenez, prenez ce parchemin. J'ai passé de nombreuses nuits à lutter avec mes yeux presque aveugles pour écrire tout ce dont j'ai besoin pour l'armure. Apportez-moi ce qui est noté sur ce parchemin et je créerai pour vous la première pièce de l’ensemble.", progress = "Avez-vous les articles notés sur mon rouleau, <nom> ?", completion = "Vous avez apporté tout ce que j'avais demandé. Maintenant, à moi de jouer…", rewards = "Vous recevrez :\n\n"},
[1839] = {title = "Ula'elek et les Gantelets de brutalité", objective = "Parler à Ula'elek en Durotar.", description = "Ula'elek, le forgeron troll, va façonner pour vous les gantelets de brutalité. Il demeure en Durotar, au Village de Sen'jin, avec ses frères Darkspear, et il attend votre arrivée.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[1840] = {title = "Orm Stonehoof et le Camail de brutalité", objective = "Parler à Orm Stonehoof à Thunder Bluff.", description = "Orm Stonehoof est très respecté pour son habileté. Il va fabriquer pour vous le Camail de brutalité.\n\nCherchez-le à Thunder Bluff, près du bassin du grand totem central de la cité.", progress = nil, completion = "Salut à vous ! Je suis Orm et Thun'grim m'a dit que vous souhaitiez avoir un casque ?", rewards = "Vous recevrez :\n\n"},
[1841] = {title = "Velora Nitely et les Jambières de brutalité", objective = "Parler à Velora Nitely à Undercity.", description = "On dit qu'avant de mourir, Velora Nitely était l'un des plus grands forgerons d'armures de Lordaeron. La mort, semble-t-il, n'a pas affecté ses talents. Allez voir Velora : elle fabriquera vos Jambières de brutalité.\n\nVelora officie à Undercity de Lordaeron, dans le quartier des Marchands.", progress = nil, completion = "Vous venez pour les jambières de l'armure ? Parfait !\n\nHum... Vais-je faire cette armure pour vous, ou allez-vous la faire pour moi ?\n\nC'était une plaisanterie ! Est-ce qu'elle était drôle ? Je ne peux pas le dire... J'ai perdu mon sens de l'humour en même temps que mon odorat. Et en même temps que j'ai arrêté de respirer…", rewards = "Vous recevrez :\n\n"},
[1842] = {title = "Les sabots de satyre", objective = "Rapporter 7 Sabots fendus de satyre à Ula'elek au village de Sen'jin en Durotar.", description = "Je peux vous faire une paire de gantelets de brutalité, et ils seront porteurs d'une grande magie, mais pour cela, vous devez d'abord m'apporter cette magie. \n\nLes satyres parcourent le nord-est d'Ashenvale à cause du pouvoir de la forêt. Ils se nourrissent de sa pureté, ils aspirent son innocence comme des sangsues et la corrompent. Ceux d'entre eux ont des sabots fendus et abîmés. Ils ont volé plus de magie à la forêt que les autres. \n\nCes sabots détiennent un grand pouvoir. J'en aurai besoin pour façonner vos gantelets.", progress = "Avez-vous les sabots, <nom> ? Leur magie est forte.", completion = "Ah, vous les avez ! Maintenant, de la même façon que les satyres sucent la force d'Ashenvale, je vais sucer le pouvoir de ces sabots et l'utiliser pour mon ouvrage…", rewards = "Vous recevrez :\n\n"},
[1843] = {title = "Gantelets de brutalité", objective = "Merci, <nom>. Ces Gantelets sont ma plus belle réussite. Prenez-les. En les portant, vous nous honorerez, moi et mes ancêtres.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGantelets de brutalité"},
[1844] = {title = "La corne de chimère", objective = "Apporter une Corne galvanisée à Orm Stonehoof à Thunder Bluff.", description = "Je veux bien vous faire un casque, mais vous devez d'abord me montrer que vous en êtes digne.\n\nBlottie sur les flancs nord-ouest des Serres-Rocheuses se trouve le Val calciné. C'était autrefois un endroit verdoyant, mais il est désormais souillé et étouffé sous la cendre. Les créatures qui y vivent encore en sont folles de douleur et de désespoir.\n\nC'est là que je vous envoie, <nom>.\n\nVous devez aller au Val calciné et trouver une matriarche chimère. Tuez-la, libérez-la de sa misère. Apportez-moi sa corne galvanisée comme preuve et je vous ferai votre casque.", progress = "Avez-vous la corne ? La matriarche est-elle libérée de sa peine ?", completion = "Vous avez achevé votre tâche, &lt;nom&gt;, et vous m'avez montré votre valeur et votre résolution. Vous aurez votre casque...", rewards = "Vous recevrez :\n\n"},
[1845] = {title = "Camail de brutalité", objective = "Je vous donne ce casque.\n\nCe sont vos actes héroïques qui vous ont conduit jusqu'à moi, <nom>, et la volonté de notre Mère la Terre... Des actes encore plus héroïques vous attendent.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCamail de brutalité"},
[1846] = {title = "Les tibias de Dragonmaw", objective = "Apporter 8 Solides tibias de Dragonmaw à Velora Nitely, dans Undercity.", description = "Pour faire les Jambières de brutalité, j'ai besoin de quelques solides tibias. Les orcs Dragonmaw des Paluns ont de jolis tibias bien épais. Je vais en avoir besoin.\n\nMais ils doivent être vraiment solides. Prenez soin de tester les tibias que vous ramasserez. Si vous pouvez les casser à mains nues, c'est qu'ils ne sont pas assez solides pour que je puisse travailler avec.", progress = "J'attends ces tibias, <nom>. Cela fera une belle structure pour vos jambières.", completion = "Bravo ! Ils ont l'air costauds. Je pense qu'ils feront tout à fait l'affaire. Comment ces orcs ont-ils pris le fait que vous leur empruntiez leurs tibias, &lt;nom&gt; ? Ils ont beaucoup protesté ?\n\nC'était une autre plaisanterie. Vous ne riez pas ?\n\nJe ne suis pas très drôle ces jours-ci...", rewards = "Vous recevrez :\n\n"},
[1847] = {title = "Jambières de brutalité", objective = "Voici vos jambières, <nom>. Dites-moi si cela vous convient ou si vous avez besoin de modifications. J'essaie toujours de satisfaire mon client ! Du moins j'essayais.\n\nEn ce moment, je ne me soucie pas beaucoup de mon métier. Mais ça met hors jeu d'être un stupide pion du Fléau ! \n\nJe suppose…", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières de brutalité"},
[1848] = {title = "Le haubert de brutalité", objective = "Je sais que vous avez enduré beaucoup de privations et versé beaucoup de sang à mon service, <nom>. Voici le fruit de votre dur labeur.\n\nPuissiez-vous bien le porter et revenir ici un jour pour me conter les services qu'il vous aura rendus.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nHaubert de brutalité"},
[1858] = {title = "La Main brisée", objective = "Voler la Clé de Tazan puis l'utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l'ombre à Orgrimmar.", description = "Je vous le laisse pour ouvrir la sacoche de Tazan et me rapporter son contenu. Le mécanisme de verrouillage est complexe, ce serait sans doute plus facile si vous trouviez la clé.\n\nComme elle n'était pas sur le corps de Tazan, je ne peux que supposer qu'il a confié la clé à quelqu'un... Oh oui ! C'est ça ! Il avait un aide nommé Gamon. Un ivrogne, vous le trouverez probablement à la taverne. Peut-être que vous pourrez lui prendre la clé en douceur.", progress = "Cela ne vous agace pas d'avoir ce que vous désirez à portée de la main, mais de n'avoir aucun moyen de l'obtenir ?", completion = "Voilà qui est intéressant. Vous avez plus que prouvé votre valeur, &lt;nom&gt;. Impressionnant. Considérez-vous à présent comme le plus jeune membre de la Main brisée. Et prenez ceci, je crois que cela vous sera d'une grande aide pour l'avenir.", rewards = "Vous recevrez :\n\nLame de malice"},
[1859] = {title = "Therzok", objective = "Aller voir Therzok dans la Faille de l'ombre à Orgrimmar.", description = "Parlez moins fort, <nom> ! Ouais, je sais qui vous êtes ! On m'a fait un topo.\n\nD'après ce qu'on entend dire de vous, vous vous débrouillez au combat et vous employez la ruse à l'occasion.\n\nJ'ai raison ?\n\nDe toute façon, vous devriez aller voir Therzok à Orgrimmar. Il a quelque chose à vous proposer.", progress = nil, completion = "Très bien ! Je constate avec plaisir que Kaplak a réussi à vous faire venir.\n\nNous avons à parler d'un certain nombre de choses, dont votre avenir au sein de la Main.", rewards = "Vous recevrez :\n\n"},
[1860] = {title = "Parler à Jennea", objective = "Parler à Jennea Cannon à Stormwind.", description = "Nous, les mages, avons une tâche à accomplir. Une tâche essentielle pour la sécurité de Stormwind et de la forêt.\n\nJennea Cannon vous donnera plus de détails. Elle étudie dans le Sanctuaire du Sorcier, dans le quartier des mages de Stormwind. Hâtez-vous d'aller la voir.", progress = nil, completion = "On vous envoie pour m'aider dans ma tâche, &lt;nom&gt; ? Bon. C'est encourageant de voir de jeunes mages s'investir dans la cause...\n\nQuelle cause, demandez-vous ? En temps voulu, jeune &lt;classe&gt;. Vous saurez… En temps voulu.", rewards = "Vous recevrez :\n\n"},
[1861] = {title = "Le lac Miroir", objective = "Apporter un Echantillon d'Eau du lac Miroir à Jennea Cannon à Stormwind.", description = "Les importantes luttes mystiques que le monde a vécues ont fait déborder les courants magiques de leurs canaux autrefois stables. Nous essayons de déterminer quels effets ces changements ont provoqué et certains d'entre nous craignent le pire !\n\nMais je vous en dirai davantage plus tard. Pour l'instant, nous avons besoin de vous pour recueillir des informations.\n\nTenez, prenez cette fiole. Allez au bas de la chute d'eau du lac Miroir, au sud-ouest des portes de Stormwind, et prélevez un échantillon de cette eau. Apportez-le-moi pour que je puisse vérifier si l'eau est contaminée par la magie.", progress = "Avez-vous l'échantillon, <nom> ? Le flux de magie dans Stormwind et Elwynn a été modifié et je dois savoir s'il suinte dans l'eau.", completion = "Merci, &lt;nom&gt;. Je vais rechercher des traces de magie dans cette eau, en espérant qu'elle n'en révèle pas... Ou alors cela voudrait dire que ceux qui boivent depuis longtemps l'eau du lac Miroir ne pourront être guéris. \n\nVoici pour vous, &lt;nom&gt;. Prenez cet orbe ou ce bâton en récompense. Puisse-t-il bien vous servir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe de LeyBâton de Ley\n\nVous recevrez également :\n\n"},
[1878] = {title = "Prime de la poche à eau", objective = "Vous revoici, <nom> ? Si vous avez cinq outres de Bat-le-désert de plus, alors j'ai un paquet qui porte votre nom !", description = nil, progress = "Vous revoici, <nom> ? Si vous avez cinq outres de Bat-le-désert de plus, alors j'ai un paquet qui porte votre nom !", completion = "Excellent : plus nous récupérons d'outres, moins nous risquons le désastre ! Rapportez-en encore, et je vous récompenserai pour chaque lot de cinq outres que vous rapporterez.", rewards = "Vous recevrez :\n\nPaquet de la Co. des eaux Gadgetzan"},
[1879] = {title = "Parler à Bink", objective = "Parler à Bink à Ironforge.", description = "<nom> ! Bink, ma collègue d'Ironforge, vous salue. Elle a une mission qu'elle ne veut confier qu'à un mage ! Avez-vous cette qualification, <nom> ?\n\nDans ce cas, adressez-vous à elle. Elle passe son temps dans le Hall des Mystères de la Garde mystique d'Ironforge.", progress = nil, completion = "Oh, je vois que vous tenez vos promesses ! Mais il faut plus que des promesses tenues pour faire un bon &lt;classe&gt;. Et si vous n'êtes pas un bon &lt;classe&gt;, alors vous êtes un mauvais &lt;classe&gt;. Et les mauvais mages compliquent le problème, eh oui !\n\nOups, je prends de l'avance sur les événements. Commençons par le début !", rewards = "Vous recevrez :\n\n"},
[1880] = {title = "Le Bidulotron de youplala", objective = "Rapporter à Bink son Bidulotron de Youplala.", description = "Nous, les mages, nous faisons plus qu'agiter les doigts et faire quelques jolies étincelles ! Nous contrôlons la magie, le tissu de base de notre monde ! Et cela nécessite beaucoup de soin et de résolution. Et de connaissances... tant de connaissances !\n\nL'une de mes inventions, le Bidulotron de Youplala, permet de rassembler et de stocker d'énormes quantités d'informations. Mais je l'ai perdu ! Quand nous nous sommes enfuis de notre maison de Gnomeregan, je l'ai oublié dans un coffre d'une de nos huttes, à l'extérieur de la ville, et maintenant, la place est envahie par des gnomes lépreux !\n\nJe vous en prie, <nom>, récupérez mon Bidulotron !", progress = "Avez-vous trouvé mon Bidulotron ? Je dois le récupérer avant que sa provision d'énergie ne soit déchargée !", completion = "Quelle belle journée ! Lorsque j'ai fabriqué le Bidulotron, je ne me doutais pas que j'en deviendrais dépendante ! Et maintenant je peux reprendre mes études... \n\nMerci, &lt;nom&gt;. Tenez, ce sont mes premiers outils de &lt;classe&gt;. Ils sont un peu abîmés, mais ils fonctionnent parfaitement. Prenez-en un. Je suis sûr que n'importe lequel d'entre eux vous sera utile !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe des arcanesBâton des arcanes\n\nVous recevrez également :\n\n"},
[1881] = {title = "Parler à Anastasia", objective = "Aller voir Anastasia Hartwell.", description = "<nom>, Anastasia Hartwell a une tâche à proposer à quelqu'un de votre valeur. Allez la voir dans le Quartier de la magie d'Undercity et préparez-vous à accomplir votre première tâche pour les mages des Réprouvés.", progress = nil, completion = "Je vous salue, &lt;nom&gt;. Vous avez été sage de répondre à mon appel et vous seriez plus sage encore de tenir compte de ce que je vais vous dire…", rewards = "Vous recevrez :\n\n"},
[1882] = {title = "La ferme des Balnir", objective = "Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier de la magie d'Undercity.", description = "Les Maleterres de l'est sont une aberration. Engendrées par le roi-liche, elles étendent leur magie dans le sol, corrompant et tuant tout ce qui vit. Bien que les forces destructrices de la corruption aient un certain charme, nous, les mages des Réprouvés, pensons que cette façon de faire est chaotique et doit être arrêtée.\n\nMais d'abord, nous devons mesurer leur étendue dans Tirisfal. Allez à la ferme des Balnir, à l'est de Tirisfal. Il y a des fleurs qui poussent dans le jardin, des gueules-de-loup. Cueillez-les et revenez me voir.", progress = "Avez-vous les gueules-de-loup ? Cette variété de fleurs est très sensible aux énergies magiques. L'étude des gueules-de-loup poussant près des Maleterres pourra nous indiquer si la peste est entrée dans les Clairières de Tirisfal.", completion = "Ah ! Quel beau spécimen ! Je vais l'envoyer à nos apothicaires pour étudier l'étendue de la contamination des Maleterres.\n\nEn remerciement, &lt;nom&gt;, vous pouvez choisir un orbe ou un bâton. L'un ou l'autre vous sera utile.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe des arcanesBâton des arcanes\n\nVous recevrez également :\n\n"},
[1883] = {title = "Parler à Un'thuwa", objective = "Aller voir Un'thuwa.", description = "Un'thuwa, le mage tribal du village de Sen'jin, a détecté une perturbation dans les courants magiques de Durotar et demande de l'aide. Allez voir Un'thuwa et faites ce que vous pouvez pour l'aider.\n\nEn retour, de nouveaux secrets vous seront révélés.", progress = nil, completion = "Salut, &lt;nom&gt; ! Mon appel à l'aide a donc été entendu. Espérons que vous serez à la hauteur...", rewards = "Vous recevrez :\n\n"},
[1884] = {title = "Les Tas de Ju-Ju", objective = "Détruire 4 Tas de Ju-Ju, puis retourner voir Un'thuwa au village de Sen'jin.", description = "Le démoniste Zalazane des îles de l'Écho a perturbé le flux magique en Durotar. Il l'a fait par l’intermédiaire de fétiches infectés, des tas de Ju-ju, qu'il a placés dans ses huttes sur l'île principale d'Écho.\n\nCes tas perturbent la faune et la flore et accroissent le pouvoir des sorciers et des créatures infernales qui se cachent dans les coins sombres du pays.\n\nVous devez détruire les tas de Ju-ju, <nom>, avant que le flux de magie ne soit altéré pour toujours.", progress = nil, completion = "Je sens que les tas de Ju-ju de Zalazane ont été détruits. Avec du temps et de la chance, le flux de magie reprendra son cours normal en Durotar.\n\nC'est une grande chose que vous avez accomplie pour notre peuple, &lt;nom&gt;. Et vous nous avez montré votre valeur, à nous mages de la Horde.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe de LeyBâton de Ley\n\nVous recevrez également :\n\n"},
[1885] = {title = "Mennet Carkad", objective = "Aller voir Mennet Carkad dans le Quartier des voleurs d'Undercity.", description = "<nom> ? Pas vraiment ce à quoi je m'attendais, compte tenu de l'intérêt que Carkad lui-même manifeste pour vous ! Comme quoi les apparences sont parfois trompeuses, non ?\n\nPeu importe, vous devez aller le voir dès que possible. Autant que vous ne sachiez pas ce qui est arrivé au dernier qui a ignoré ses sommations.", progress = nil, completion = "Hum ! Vous avez accouru dès mon premier appel, n'est-ce pas ? Bien sûr. Je n'en attendais pas moins d'un éventuel futur Traqueur noir.", rewards = "Vous recevrez :\n\n"},
[1886] = {title = "Les Traqueurs noirs", objective = "Trouver la Lettre de recommandation d'Astor et l'apporter à Mennet Carkad dans le Quartier des voleurs.", description = "Si vous voulez rejoindre les Traqueurs noirs, la garde d'élite du Seigneur Varimathras, vous devez prouver votre valeur.\n\nJe ne vais pas vous mentir, <nom>, cette tâche pourrait bien signifier votre mort.\n\nIl y a certaines choses auxquelles il faut prêter attention. J'ai besoin des effets personnels d'Astor Hadren, un messager qui voyage entre les Pins argentés et Undercity. Je vous laisse le choix de la méthode.\n\nMoins vous en saurez, mieux ça vaudra pour vous. Réussissez et je vous en dirai plus.", progress = "Un succès à m'annoncer ?", completion = "Bien joué, &lt;nom&gt;. Vous avez passé la première partie de ce test. Espérons qu'Andron n'aura pas eu vent de vos activités et que nous serons capables de le convaincre que vous êtes, en fait, le messager qu'il attendait.", rewards = "Vous recevrez :\n\n"},
[1898] = {title = "Les Traqueurs noirs", objective = "Aller voir Andron Gant à Undercity.", description = "La lettre de recommandation devrait être suffisante pour convaincre Andron que vous êtes le messager qu'il attendait. J'ai déjà rencontré Andron, il n'est pas assez intelligent pour être soupçonneux.\n\nLe Seigneur Varimathras suspecte Andron d'avoir fourni de l'aide à un autre groupe. Il exige de savoir lequel et en veut la preuve.\n\nJe veux que vous alliez voir Andron pour obtenir cette information. Vous le trouverez à son magasin près de l'Apothicarium.", progress = "Salut. Quelque chose que je peux faire pour vous ?", completion = "Oh oui ! Je vous attendais. Je suppose que nos connaissances mutuelles sont satisfaites des informations que j'ai fournies jusqu'ici ?\n\nJe me doute que ce n'est pas à vous qu'il faut demander ça, ça m'étonnerait qu'ils vous mettent au courant. Pourquoi faire autant confiance à un simple messager, hein ?", rewards = "Vous recevrez :\n\n"},
[1899] = {title = "Les Traqueurs noirs", objective = "Apporter le Grand Livre d'Astor à Mennet Carkad dans le Quartier des voleurs d'Undercity.", description = "Vous trouverez les informations qui intéressent vos employeurs dans le grand livre sur l'étagère derrière moi. Apportez-leur avec mes respects et dites-leur que je préférerais que ce soit vous qu'ils envoient, si ce qu'ils trouvent leur semble avoir assez de valeur, pour continuer notre petit accord.", progress = "Vous avez réussi, <nom> ?", completion = "Bien, il y a certainement plus d'informations que je n'en attendais d'Andron. Donnez-moi un moment pour le lire attentivement, avant que je ne vous envoie accomplir la mission suivante.", rewards = "Vous recevrez :\n\n"},
[1918] = {title = "Les éléments souillés", objective = "Apporter le Globe d'eau souillée à Mastok Wrilehiss, au Poste de Bois-brisé, à Ashenvale.", description = "Sur l'élémentaire vaincu, vous trouvez un globe d'eau, formidablement lumineux, dont le contenu semble proprement répugnant. Apparemment, l'essence qui a souillé les eaux du lac Mystral est également présente dans les eaux du globe. \n\nCe genre de découverte n'est pas en mesure d'intéresser le commun des mortels, et sans doute la personne qui vous a demandé de vous rendre au lac, Mastok Wrilehiss, au poste de Bois-brisé, pourrait bien avoir une idée plus précise à ce sujet.", progress = "Ouais, qu'est-ce que vous voulez ?", completion = "Vous trouvez une boule d'eau sale et décidez de me l'amener ? Vous me prenez pour qui, le Cercle terrestre, ou quoi ?\n\nEn fait, ça me donne une idée... peut-être que vous aurez besoin du Cercle terrestre pour ça. Je veux dire, si ça peut aider à éclaircir la situation au lac pour de bon, je suis à fond pour.\n\nVous savez qui sont les gens du Cercle terrestre, &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[1919] = {title = "Rendre compte à Jennea", objective = "Parler à Jennea Cannon à Stormwind.", description = "Vous connaissez de mieux en mieux le métier, jeune <nom>. Vous vous sentez d'attaque pour commencer vos vraies leçons maintenant ? Pour prendre part à la guerre secrète que nous menons ?\n\nSi oui, allez voir Jennea Cannon au Sanctuaire du Sorcier, dans le quartier des mages de Stormwind. Elle vous confiera une tâche qui sera votre première fenêtre sur le monde invisible.", progress = nil, completion = "&lt;nom&gt;, j'ai une mission pour vous, dans le quartier des mages. Écoutez attentivement parce qu'il n'y a pas de temps à perdre.", rewards = "Vous recevrez :\n\n"},
[1920] = {title = "Trouver le Solitaire bleu", objective = "Obtenir une Incantation de manifestation et une Caisse de coffres de retenue placée derrière Jennea Cannon. Apporter 3 Coffres de retenue remplis à Jennea Cannon au Sanctuaire du sorcier.", description = "On nous a rapporté un incident qui est survenu à la taverne du « Solitaire bleu » dans le quartier des mages. Des créatures étranges et invisibles rôdent dans la taverne et je crains qu'une faille de mana ne se soit formée là-bas.\n\nIl faut que vous y alliez pour neutraliser ces créatures. Sur place, utilisez l'incantation de manifestation pour les rendre visibles, puis capturez-les avec un coffre de retenue. Quand vous en aurez suffisamment, revenez me voir avec les coffres remplis, les coffres vides et l'incantation.", progress = "Avez-vous capturé les créatures, <nom> ? Elles doivent être étudiées pour déterminer la cause de leur présence.", completion = "Excellent ! Je vais étudier ces créatures avec application et, avec de la chance, je saurai comment elles se sont glissées dans notre monde.\n\nVotre valeur grandit aux yeux de la société de mages, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1921] = {title = "Rassembler les matériaux", objective = "Apporter 10 unités de Lin et 6 Gemmes chargées de la faille à Wynne Larson à Stormwind.", description = "Vous avez bien servi les mages, et il est temps de vous attribuer votre robe de sorcier. Wynne Larson peut la réaliser pour vous, mais il faudra lui fournir les matériaux nécessaires. \n\nLa robe sera faite de lin, ce qui ne sera pas difficile à trouver, mais vous devrez aussi fournir des gemmes chargées de la faille. On ne peut les trouver que dans la mine du Ru d'argent à Loch Modan, dans les caisses laissés par la Ligue des mineurs nains. \n\nRassemblez le lin et les gemmes et apportez-les à Wynne Larson, chez les couturiers Larson, dans le quartier des mages.", progress = "Bonjour, <nom>. Jennea m'a dit que vous viendriez. Avez-vous quelque chose pour moi ?", completion = "Oui, ce sont de belles pièces de lin. Je peux en faire une robe superbe. Lorsque j'aurai ajouté les gemmes de la faille, cela fera un habit parfait pour un &lt;classe&gt; !", rewards = "Vous recevrez :\n\n"},
[1938] = {title = "Traité d'Ur sur la Magie des Ombres", objective = "Apporter le « Traité d'Ur sur la magie de l'Ombre » au Grand Sorcier Andromath à Stormwind.", description = "Autrefois, trois mages étudiaient dans cette tour, jusqu'à ce que l'un d'entre eux tombe dans les travers de la magie noire. On l'a pressé de se détacher de ses travaux maléfiques, mais il n'a pas pu résister. Il fut alors banni. \n\nLe mage renégat a élu domicile dans la tour d'Ilgalar, dans les Carmines, et il a emporté avec lui un livre très puissant : le \"Traité d'Ur sur la Magie de l'Ombre\". \n\nNous, mages de Stormwind, voulons récupérer ce livre. Volez-le dans la tour d'Ilgalar et rapportez-le.", progress = "Avez-vous le livre, <nom> ? Ses secrets ne sont pas à la portée des non-initiés et tenter d'en sonder les profondeurs peut mener à la perte et à la ruine.", completion = "J'ai eu peur que Morganth n'ait caché le livre ailleurs, ou qu'il n’ait trouvé un moyen de l'ouvrir et de le lire.\n\nC'est rassurant de constater qu'il ne l'a pas fait et que les scellés que nous avions posés sur l’ouvrage ne sont pas brisés.", rewards = "Vous recevrez :\n\n"},
[1939] = {title = "Grand sorcier Andromath", objective = "Aller voir le Grand Sorcier Andromath.", description = "Le Grand Sorcier Andromath souhaite vous parler, <nom>. Il est en haut du Sanctuaire du Sorcier, dans le quartier des mages de Stormwind.\n\nIl serait sage d'aller le voir, car Andromath est l'un des mages les plus puissants de Dalaran. Avec lui, le Conseil est en effet un Haut Conseil.", progress = nil, completion = "Je vous salue, &lt;nom&gt;. Je suis heureux de vous voir et j'espère que vous aurez le temps d'écouter la parole d'un vieil homme...", rewards = "Vous recevrez :\n\n"},
[1940] = {title = "Soie d'araignée en parfait état", objective = "Apporter 8 Soies d'araignée en parfait état à Wynne Larson à Stormwind.", description = "Vous avez servi sans faille, <nom>. Je pense qu'il est temps pour vous de revêtir un vêtement plus adapté à votre statut. Si vous allez chercher les matériaux nécessaires, nous ferons faire la robe qui convient.\n\nVous devez entrer dans le bois de la Pénombre et chasser les araignées qui s'y cachent. Prélevez leur soie, mais uniquement la plus fine et la plus pure. Quand vous en aurez suffisamment, apportez-la à Wynne Larson, des Couturiers Larson, dans le quartier des mages. Elle fera votre robe.", progress = "Ah ! Oui ! Les mages du Sanctuaire du Sorcier m'ont dit que vous viendriez. Avez-vous apporté la soie ?", completion = "Belle qualité ! Je vais me mettre au travail tout de suite !", rewards = "Vous recevrez :\n\n"},
[1941] = {title = "La robe de tisse-mana", objective = "Voici votre robe. C'est l’une des plus belles que j'ai confectionnées ! Portez-la avec fierté. Et si les gens vous interrogent, dites-leur qu'elle sort de l’atelier des couturiers Larson !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe en tisse-mana"},
[1942] = {title = "L'Habit du noeud astral", objective = "Votre habit est prêt. Cette soie que vous avez apportée était si belle... Ça ne vous fait rien si je l'ai cousu un peu court pour pouvoir en conserver un morceau ? \n\nMais non, je plaisante ! Il vous ira comme un gant, au plus fort de l'aventure comme dans les occasions plus mondaines ! Profitez-en bien !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe du noeud astralChemisette du noeud astral\n\nVous recevrez également :\n\n"},
[1943] = {title = "Parler à Deino", objective = "Aller voir Deino.", description = "La mage troll Deino a besoin de votre aide, <nom>. Elle réside à Orgrimmar, au pavillon de Buissombre.", progress = nil, completion = "Bon, vous êtes là ! Ma tâche n'est pas facile, mais elle est essentielle à la société des mages. Si vous m'aidez, je suis sûre que vous comprendrez son importance.", rewards = "Vous recevrez :\n\n"},
[1944] = {title = "Les Eaux de Xavian", objective = "Apporter l'Echantillon d'Eau de Xavian à Deino à Orgrimmar.", description = "La ville légendaire de Xavian est enfouie au plus profond des terres orientales d'Ashenvale et les initiés connaissent bien son histoire. Il est dit que les eaux de Xavian ont des pouvoirs magiques énormes.\n\nJe voudrais un échantillon de ces eaux, pris à la source.\n\nPrenez cette fiole et allez à Xavian. Recueillez de l'eau en bas de la chute la plus haute et rapportez-la-moi. Et prenez garde en vous déplaçant dans la cité ancienne : les satyres se sont installés dans les ruines et ils n'aiment pas que les mages viennent fourrer leur nez dans leurs affaires.", progress = "Quel plaisir de vous voir de retour en bonne santé, <nom> ! Vous avez mon échantillon d'eau ? J'ai hâte d'étudier ses propriétés.", completion = "Ah très bien ! Je crois que les satyres de Xavian vous ont causé quelques soucis ?\n\nMerci, &lt;nom&gt;. Je vais immédiatement étudier cet échantillon d'eau de Xavian.", rewards = "Vous recevrez :\n\n"},
[1945] = {title = "Les sœurs rieuses", objective = "Apporter 12 Cheveux de sœurs rieuses à Kil'hala à la Croisée.", description = "En remerciement de vos services, j'ai pris des dispositions pour vous faire confectionner de nouvelles robes, à condition que vous alliez chercher les matériaux nécessaires... \n\nPour ces robes, vous devez vous rendre à Ashenvale et prélever des boucles de cheveux sur les sœurs rieuses, les dryades qui se réunissent près de la retraite de Raynewood.\n\nUne fois en possession de leurs cheveux, apportez-les à Kil'hala, un tailleur troll qui se trouve à la Croisée, dans les Tarides. Il vous attend et coudra vos robes.", progress = "Bonjour, <nom>. Deino m'a dit que vous viendriez et que vous m'apporteriez des cheveux des sœurs rieuses. Les avez-vous ?", completion = "Ah ! Ces cheveux vont donner une robe superbe, &lt;nom&gt;. C'est dommage qu'il faille tuer les dryades pour obtenir cette superbe matière première, mais je ne crois pas qu'elles l’auraient donnée de bon cœur.\n\nJ'ai pitié, mais juste un peu…", rewards = "Vous recevrez :\n\n"},
[1946] = {title = "L'Habit du néant", objective = "Voici votre robe du Néant, <nom>. À la fois confortable et solide, elle contient la magie des cheveux des sœurs rieuses. \n\nSi elle vous plaît, parlez-en à Deino. C'est un <classe> d'une telle puissance que je préfère être de son côté !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe du NéantTunique du Néant\n\nVous recevrez également :\n\n"},
[1947] = {title = "Voyager vers le Marais", objective = "Aller voir Tabetha.", description = "Maintenant est venu le temps d'obtenir votre Baguette de mage. Tout d'abord, allez voir Tabetha, l'ermite humaine du marécage d'Âprefange. Sa cabane se trouve au fin fond du marais, à l'ouest de Theramore.\n\nAdressez-vous à elle, car son savoir est immense. Vous trouverez sa cabane à l'ouest de Theramore, et juste au nord des ruines Cognepierres.", progress = nil, completion = "Doucement ! L'instant est délicat et il ne faut pas me déranger ! \n\nUn instant...", rewards = "Vous recevrez :\n\n"},
[1948] = {title = "Les Objets de Puissance", objective = "Apporter un Jade et le Roncier de foudre à Tabetha, dans le marécage d'Âprefange.", description = "La fabrication d'une Baguette de mage n'est pas aisée. Il faut des substances rares et il faut fabriquer un récipient pour recueillir de grandes quantités d'énergie magique. Vous devez me rapporter tout ça.\n\nJ'ai écrit sur ce parchemin ce dont vous aurez besoin et des instructions sur la façon de les obtenir. Apportez-moi exactement ce qui est sur cette liste et suivez mes instructions à la lettre, sinon ça pourrait mal tourner au moment de la fabrication de votre Baguette magique.", progress = "Bonjour, <nom> ! Avez-vous ce que je vous ai demandé ?", completion = "Ah ! Vous avez trouvé le Jade et le Roncier de foudre ! Excellent !\n\nEst-ce que c'est de la fumée que je vois sortir de vos oreilles ? Vous étiez sans doute trop près quand la foudre a frappé les bâtons de totem. Mais ne vous inquiétez pas : être frappé par la foudre porte chance !", rewards = "Vous recevrez :\n\n"},
[1949] = {title = "Des secrets cachés", objective = "Parler au magus Tirth dans les Salines.", description = "Pour faire votre baguette magique, je dois lire des passages d'un certain livre. Ce livre, intitulé « les Rituels du pouvoir », a été écrit par le magus Tirth.\n\nJe n'ai pas d’exemplaire de ce livre et aucune des grandes bibliothèques de ce monde n'en possède un. Vous devez donc aller voir Tirth et l’obtenir de lui.\n\nBonne chance ! Tirth était un grand mage et un grand savant, mais maintenant il passe tout son temps aux courses des gnomes et des gobelins des Salines, à boire et à parier.", progress = nil, completion = "Quoi ? Parlez plus fort ! Ces vieilles oreilles ne marchent plus aussi bien qu'avant.\n\nBon, j'espère que vous êtes ici avec une chope de bière fraîche ou quelques tuyaux sur la prochaine course ! Sinon vous feriez mieux de passer votre chemin... Parce que j'ai une baguette magique de métamorphose avec votre nom écrit dessus !", rewards = "Vous recevrez :\n\n"},
[1950] = {title = "Trouver le Scoop", objective = "Trouver l'Incantation pour ouvrir le coffre-fort de Tirth puis retourner voir Tirth.", description = "Je peux vous aider pour le livre, mais d'abord vous devez m'aider !\n\nL’ouvrage que vous cherchez est dans mon coffre-fort, fermé magiquement. Pour l'ouvrir, il faut prononcer une incantation spéciale et je ne me souviens plus de l'incantation ! D’habitude mon assistant m'aide à me rappeler de ces choses, mais je ne le trouve nulle part.\n\nSi vous voulez mon livre, trouvez d'abord mon apprenti ! Demandez aux gens le long de la piste. Avec un peu de chance, quelqu'un l'aura vu. Ramenez-le ici, ou au moins qu'il vous donne l'incantation pour ouvrir le coffre !", progress = "What are you waiting for?  I need my magic phrase!", completion = "Oh ! Maintenant je me souviens...\n\nJ'avais oublié que j'avais jeté cette petite malédiction à Johnson. Je ne me souviens pas pourquoi j'ai fait ça, mais il est certain qu'il le méritait, ce petit ingrat !", rewards = "Vous recevrez :\n\n"},
[1951] = {title = "Rituels du Pouvoir", objective = "Apporter le livre des « Rituels du pouvoir » à Tabetha dans le marécage d'Âprefange.", description = "Hum... Maintenant que j'y pense, je n'ai plus ce livre ! Vous voyez, j'avais quelques dettes de jeu et pour les régler, j'ai vendu ma dernière copie des « Rituels du pouvoir » à un membre du clergé...\n\nUn membre de la Croisade écarlate. Il a dû le mettre dans la bibliothèque du Monastère écarlate dans les Clairières de Tirisfal !\n\nSi vous voulez ce livre, il va falloir que vous alliez le chercher au monastère. Et désolé pour tout ce tracas. Je ne suis plus moi-même ces derniers temps...", progress = "Je vous salue, <nom>. Avez-vous trouvé le livre « Les Rituels du pouvoir » ?", completion = "Voilà ! C'est exactement ce dont j'avais besoin pour préparer le rituel de création de votre baguette magique ! J'espère que vous n'avez pas eu trop de mal à le trouver…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1952] = {title = "La baguette du mage", objective = "Aller voir Tabetha après son rituel.", description = "Je vais aller fabriquer les Baguettes magiques maintenant.", progress = nil, completion = "Voici les baguettes que j'ai fabriquées. Choisissez !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBaguette d'IcefuryBaguette de force du NéantBaguette de Ragefire\n\nVous recevrez également :\n\n"},
[1953] = {title = "Retourner dans le Marais", objective = "Aller voir Tabetha.", description = "Il est temps pour vous de parler à l'ermite Tabetha, <nom>. Elle vous donnera des indications sur la fabrication de l'un des objets les plus importants pour les mages. \n\nLa cabane de Tabetha est loin dans le marécage d'Âprefange à l'ouest de Theramore.", progress = nil, completion = "Ah, oui. Vous voulez un orbe ou un bâton, &lt;nom&gt; ? Très bien. Je vous aiderai. \n\nMais je dois d'abord vous prévenir : le processus est dangereux et pourrait provoquer votre mort ! \n\nOu la mienne. La mort de quelqu'un en tout cas... \n\nEspérons que ce soit celle de quelqu'un d'autre, vous ne croyez pas ?", rewards = "Vous recevrez :\n\n"},
[1954] = {title = "L'orbe infernal", objective = "Apporter un Orbe infernal à Tabetha dans le marécage d'Âprefange.", description = "D'abord, il faut acquérir un orbe puissant. Les démonistes de la Lame ardente ont des orbes splendides, de qualité... Dommage qu'ils soient liés à des démons ! Mais ça peut s'arranger. \n\nRendez-vous en Désolace et prenez un orbe infernal à un Invocateur démoniste. Ils se retrouvent au convent de Mannoroc. \n\nLorsque vous aurez cet orbe, rapportez-le.", progress = "Avez-vous trouvé un orbe infernal, <nom> ?", completion = "Oh ! Il est chouette ! Non, enfin, pas \"chouette\" comme un bon verre de quelque chose de frais un jour de canicule ! \n\nEn fait, il n'est pas CHOUETTE du tout, maintenant que j'y repense ! Pas le bon verre, l'orbe ! \n\nEssayez de suivre, &lt;nom&gt; ! Concentrez-vous, si vous voulez terminer cette tâche un jour !", rewards = "Vous recevrez :\n\n"},
[1955] = {title = "L'Exorcisme", objective = "Tuer le démon de l'Orbe puis parler à Tabetha.", description = "Maintenant que nous avons l'Orbe de l'Invocateur, nous devons exorciser le démon qu'elle contient. Je peux y arriver. C'est même la partie facile.\n\nVous, vous allez avoir à faire le plus dur : tuer le démon quand il va sortir.\n\nEt il va falloir faire vite, sans ça il se réfugiera dans l'Orbe et il faudra tout recommencer !\n\nPréparez-vous. Apportez vos sorts les plus puissants et gardez vos potions à portée de la main. Et amenez un ami, si vous en avez un. Parce que ça ne va pas être joli...", progress = nil, completion = "Bien joué, &lt;nom&gt; ! Vous avez donné à ce démon une leçon qu'il n'oubliera pas de sitôt.\n\nIl réfléchira à deux fois avant de repasser sa sale tête dans ce monde, pour chercher le stupide mortel qui l'a battu. Probablement avec des amis cette fois. De grands amis écailleux qui ne demanderaient pas mieux que de vous déchirer en tout petits morceaux |2 mort-vivant.\n\nJe ne vous ai pas fait peur, n'est-ce pas... &lt;nom&gt; ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1956] = {title = "L'Energie d'Uldaman", objective = "Récupérer une Source d'énergie en obsidienne et la rapporter à Tabetha dans le marécage d'Âprefange.", description = "Le démon a été enlevé, et maintenant il nous faut une source d'énergie. Malheureusement, les plus puissantes sont les plus anciennes et les plus difficiles à acquérir ! Le destin n'est pas tendre avec nous, hein ? \n\nIl va falloir que vous alliez à Uldaman pour y vaincre la sentinelle d'obsidienne. Il est grand, il est fort, et sa source d'énergie est pleine... d'énergie ! \n\nJe vous souhaite beaucoup de chance, <nom>. Et si vous n'avez pas cette chance, et bien... C'était un plaisir d'avoir pu faire votre connaissance.", progress = "Vous revenez d'Uldaman, <nom> ? Vous avez vaincu la Sentinelle d'obsidienne ?", completion = "Vous avez réussi ? Bien joué !\n\nJe bavardais avec des collègues à moi et lorsque j'ai mentionné votre nom, ils ont dit : \"C'est sûr, &lt;nom&gt; travaille remarquablement sous la pression !\" \n\nMais quand j'ai mentionné que je vous avais dit d'aller combattre la Sentinelle d'obsidienne, ils m'ont traitée de folle ! Ils ont dit : \"Tabetha, tu es folle ! Comment veux-tu que &lt;nom&gt; vienne à bout de cette Sentinelle ?\"\n\nEt j'ai dit : \"On verra !\" Et ils ont répondu : \"C'est ça, on verra...\" \n\nEh ben ils vont voir, pas vrai ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[1957] = {title = "Les éruptions de mana", objective = "Tuer 12 Eruptions de mana dans la limite de temps imposée.", description = "Nous avons presque fini, mais la dernière étape est la plus périlleuse, <nom>.\n\nJ'ai l'orbe d'invocateur vide, prêt à être ensorcelé. Nous le ferons en canalisant l'énergie d'une faille de mana. Je jetterai un sort qui va en ouvrir une pour un court moment. Des créatures issues du mana en surgiront. Vous devrez combattre ces éruptions de mana pour extraire leur puissance, dont je m’emparerai.\n\nTuez suffisamment d'éruptions de mana avant que la faille ne se referme et je canaliserai toute leur énergie dans votre orbe.", progress = nil, completion = "Vous l'avez fait ! Je n'ai pas douté de vous une seconde ! D'accord, peut-être juste une seconde, ou deux... Mais globalement je n'ai pas beaucoup douté.\n\nFranchement.", rewards = "Vous recevrez :\n\n"},
[1958] = {title = "L'Energie céleste", objective = "Vous pouvez ressentir de la fierté, <nom>. Bien des mages auraient échoué face aux créatures que vous avez affrontées !\n\nL'Orbe céleste est prêt. Je peux aussi le fixer sur un bâton, c'est à vous de choisir. Moi, je choisirais l'Orbe, mais qui suis-je pour avoir un avis ?", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe célesteBâton céleste\n\nVous recevrez également :\n\n"},
[1959] = {title = "Rendre compte à Anastasia", objective = "Aller voir Anastasia Hartwell.", description = "Les mages d'Undercity ont noté une perturbation magique dans la ville et ont demandé à tous les mages de la Horde d’enquêter.\n\nAnastasia Hartwell vous en dira plus. Allez la voir dans le quartier des mages de Undercity.", progress = nil, completion = "C'est vrai. Nous avons détecté une perturbation magique dans notre ville. Nous ne sommes pas encore sûrs de son origine, et nous ne savons pas si elle est bénigne ou maligne. Nous devons d'abord recueillir plus d'informations...\n\nEt ce sera votre tâche, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[1960] = {title = "Enquêter dans le magasin de l'Alchimiste", objective = "Obtenir une Incantation de Manifestation et une Caisse de Coffres de retenue placée derrière Anastasia Hartwell. Apporter 3 Coffres de retenue remplis, la Caisse de Coffres de retenue et l'Incantation de Manifestation à Anastasia Hartwell à Undercity.", description = "L'échoppe d'alchimiste d'Algernon, à l'Apothicarium, est l'objet de curieux troubles. Des créatures magiques, faites seulement de magie, la parcourent. Il doit bien y avoir une raison, et nous devons la découvrir !\n\nEnquêtez à ce propos et capturez ces créatures. Prenez des coffres de stockage et un parchemin, derrière moi. Utilisez-le à l'échoppe pour rendre les créatures visibles, assujettissez-les à l'aide de vos sorts, puis capturez-les dans les coffres. Rapportez les coffres pleins, ceux qui sont vides et l'incantation.", progress = "Avez-vous fait votre enquête sur la perturbation, <nom> ? Avez-vous capturé les créatures ?", completion = "Très bien, &lt;nom&gt;. Les créatures qui sont dans ces Coffres de retenue seront étudiées par les meilleurs d'entre nous et nous déterminerons la raison de leur présence à Undercity.\n\nSi leur apparition est due à une faille dans le flux naturel de magie, alors nous devons déterminer si son origine est fortuite. Si le hasard n’est pas en cause, nous devons nous attendre à des perturbations futures beaucoup plus sérieuses.", rewards = "Vous recevrez :\n\n"},
[1961] = {title = "Rassembler les matériaux", objective = "Apporter 10 pièces de lin et 6 Gemmes de mana de Dalaran à Josef Gregorian.", description = "Il est temps pour vous de porter vos premières robes de mage, <nom>. Elles sont le signe de votre statut et un témoignage de votre valeur.\n\nPour gagner ces robes, il vous faudra aller dans la forêt des Pins argentés et prendre des gemmes de mana aux mages de Dalaran. Leurs croyances sont semblables aux nôtres, il est donc assez désagréable de les assassiner, mais s'ils ne sont pas assez forts pour résister, alors ils ne méritent pas de vivre.\n\nApportez les gemmes et une longueur de lin à Josef Gregorian, à sa boutique de tailleur, dans le Quartier de la magie.", progress = "Anastasia m'avait dit que vous viendriez me voir et je suis prêt à confectionner vos robes. Avez-vous les gemmes et le lin ?", completion = "C'est du très bon matériel, et bien que je sois incapable de mesurer la qualité de ces gemmes de mana, nous saurons bientôt si elles possèdent le pouvoir nécessaire pour créer des robes du feu-sorcier...", rewards = "Vous recevrez :\n\n"},
[1962] = {title = "Robe du feu-sorcier", objective = "Voici votre robe, <nom>. Portez-la bien.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe du feu-sorcier mineur"},
[1963] = {title = "La Main brisée", objective = "Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l'ombre à Orgrimmar.", description = "Le Chef de guerre utilise des méthodes trop subtiles. Par prudence, il veut éviter de déchaîner le pouvoir de la Horde. Pourtant, nous avons été plus forts, nous avons été de fiers conquérants ! Nous devons retrouver notre gloire passée et la Main brisée va la reconquérir.\n\nNous tirons notre force de l'ombre et frappons nos ennemis en secret. Une tâche que vous devez accomplir pour prouver votre valeur.\n\nLe troll Tazan est en affaires avec les pirates près de Ratchet. Il détient des informations dont j'ai besoin. Tuez-le et apportez-moi sa sacoche.", progress = "C'est un imbécile qui croit qu'une charge à la hache est plus efficace qu'un couteau dans la nuit.", completion = "Hum, même si je suis heureux de savoir que Tazan n'est plus parmi nous, une sacoche fermée à clé ne nous est pas d'une très grande utilité. Nous avons besoin de ce qu'elle contient.\n\nÇa pourrait bien devenir un deuxième défi digne de celui ou celle qui voudrait rejoindre la Main brisée.", rewards = "Vous recevrez :\n\n"},
[1978] = {title = "Les Traqueurs noirs", objective = "Livrer le Grand Livre d'Andron à Varimathras au Hall de la Dame noire à Undercity.", description = "Le Syndicat ? Je ne m'en serais jamais douté. Il semble que ces messieurs d'Alterac soient tombés bien bas depuis leur trahison.\n\nLe Seigneur Varimathras aura plaisir à apprendre ça et comme vous avez contribué à cette découverte, il convient que ce soit vous qui la lui annonciez.\n\nAh comment pouvais-je oublier !\n\nBienvenue chez les Traqueurs noirs…", progress = "Oui ?", completion = "Hum, c'est intéressant… Les Traqueurs noirs ont admirablement fait leur travail en furetant ainsi.\n\nD'après ce que j'ai compris, vous méritez également notre gratitude pour votre performance. J'espère que cela deviendra quelque chose de routinier pour vous, &lt;nom&gt;, mes Traqueurs noirs ont toujours besoin de gens de valeur parmi eux.", rewards = "Vous recevrez :\n\nLame de malice"},
[1998] = {title = "Fenwick Thatros", objective = "Tuer Fenwick Thatros et rapporter sa Tête à Mennet Carkad dans le Quartier des voleurs d'Undercity.", description = "Le Seigneur Varimathras vient juste de m'envoyer une missive au sujet d'une menace concernant les Réprouvés, menace qui doit être immédiatement supprimée. Son nom est Fenwick Thatros, et le Seigneur Varimathras pense que c'est l'un des chefs morts-vivants qui ont pris pied dans la forêt des Pins argentés.\n\nJ'ai immédiatement pensé à vous, <nom>. J'ai assez confiance dans vos capacités pour penser que vous réussirez cette mission.\n\nLes derniers rapports des Traqueurs noirs dans la forêt indiquent que Thatros doit se trouver près du vieux port abandonné sur Lordamere.", progress = "Je vous fais parfaitement confiance pour rendre ce service au Seigneur Varimathras.", completion = "Vous avez réussi, &lt;nom&gt;. Je constate que vous avez rendu beaucoup de services aux Traqueurs noirs, en prouvant votre valeur et il est peut-être temps que nous commencions votre initiation aux Arts de l'ombre.", rewards = "Vous recevrez :\n\n"},
[1999] = {title = "Les outils du métier", objective = "Trouver le Rapport de situation de Dalaran et le remettre à Mennet Carkad dans le Quartier des voleurs d'Undercity.", description = "Les magiciens de Kirin Tor à Moulin-de-l'Ambre ont stocké d'importants documents se rapportant à l'état actuel de Dalaran. Nous tenons cela d'un de nos prisonniers. Le Seigneur Varimathras a ordonné de remettre ces documents aux Traqueurs noirs.\n\nCette tâche vous incombe, <nom>. Cependant, vous aurez besoin de certains équipements, et de la maîtrise de la technique du Crochetage. Allez voir Estelle Gendry, notre spécialiste, et demandez-lui un jeu d'outils avant de partir.", progress = "Avez-vous localisé les documents, <nom> ?", completion = "Parfait, &lt;nom&gt; ! Vous avez bien appris l'art subtil du crochetage, et plus rapidement que je m'y attendais.\n\nJe vois que j'avais raison de vous faire confiance. Croyez-moi, jeune homme, je vous prédis un grand avenir dans ce métier.", rewards = "Vous recevrez :\n\n"},
[2018] = {title = "L'épreuve de Rokar", objective = "Tuer le Surveillant Glibby et apporter son Sifflet à Rokar Ombrelame en Durotar.", description = "Ah ! Maintenant Therzok m'envoie ses étudiants boutonneux ! Eh bien, je suppose que je peux vous apprendre une ou deux choses. Ce n'est pas que je me soucie beaucoup de vos affaires, mais je ne voudrais pas avoir votre mort sur la conscience.\n\nMais vous devez d'abord me prouver que vous êtes digne de mon enseignement.\n\nJe vais vous dire, <nom>. Je n'aime pas beaucoup cette KapitalRisk. Cette région me rappelle Draenor et ça me dérange de voir les gobelins la dévaster. Peut-être qu'ils cesseraient leur travail si le surveillant de leur Videfange disparaissait...Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2019] = {title = "Les outils du métier", objective = "Retourner voir Therzok à la Faille de l'Ombre à Orgrimmar.\n\nObjet fourni : \n", description = "Vous voilà, <nom>. Ceci devrait bien vous servir. Fabrication personnelle, je vous jure que vous ne trouverez pas mieux.\n\nNe prenez pas la peine de m'expliquer ce que vous voulez en faire, cependant. Je ne m'intéresse pas aux arrangements de Therzok, je veux seulement vivre tranquillement ma retraite.\n\nSi jamais vous aviez besoin d'un autre jeu d'outils, revenez me voir et je vous en fournirai un. Mais prenez-en soin !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2020] = {title = "<INUTILISÉ>", objective = nil, description = "Maintenant voilà la serrure fermée.", progress = nil, completion = nil, rewards = nil},
[2038] = {title = "Les fournitures perdues de Bingles", objective = "Trouver et rapporter à Bingles son matériel :\n\nLa Clé de Bingles, le Tournevis de Bingles, le Marteau de Bingles et le Capsuleur soufflant de Bingles.", description = "Comme si le crash dans le Loch n'avait pas suffi, des troggs de l'île voisine m'ont attaqué et ont volé mes outils et mes capsuleurs soufflants Blastenheimer spéciaux ! Sans gyrocoptère et sans explosifs, le mouvement n'a aucune chance ! \n\nRapportez-moi mes outils et mes capsuleurs soufflants, <nom>. Pour Gnomeregan !", progress = "<nom> ! Où sont mes petites affaires ?", completion = "Vous nous avez rendu un grand service, &lt;nom&gt;. Les troggs et les gnomes lépreux qui infestent Gnomeregan vont bientôt avoir droit à un assaut aérien des gnomes !", rewards = "Vous recevrez :\n\nGants de vol de Bingles"},
[2039] = {title = "Trouvez Bingles", objective = "Trouver Bingles Blastenheimer, au Loch Modan.", description = "Nous avons perdu contact avec Bingles ! On l'a envoyé en mission de reconnaissance sur Gnomeregan et ça fait une semaine qu'il n'a pas envoyé de rapport. Je sais juste qu'il est parti et s'est envolé.\n\nLa dernière fois qu'on a vu son gyrocoptère, c'était au-dessus du Loch. Peut-être que vous pourriez enquêter, <nom>.", progress = nil, completion = "Ainsi Gnoarn n'a pas confiance dans mes capacités d'Eclaireur ? Je me demande pourquoi...\n\nMais aucune importance, j'ai besoin de votre aide ! Non ! Le Mouvement a besoin de votre aide !", rewards = "Vous recevrez :\n\n"},
[2040] = {title = "Assaut souterrain", objective = "Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Stormwind.", description = "Gnomeregan est tombé sous les contrôle de ces troggs maudits ! La situation est grave, mais vous pouvez peut-être nous aider, <nom>. \n\nAu plus profond des mortemines, il y a un Déchiqueteur gobelin en état de fonctionnement. Trouvez-le et rapportez sa source d'énergie intacte. Elle permettra à nos Excavateurs gyrodrilmatiques de percer les murailles pour l'assaut !", progress = "Avez-vous trouvé l'Indicateur Gnoam, <nom> ?", completion = "Excellent, &lt;nom&gt;. Grâce à vous, Gnomeregan a fait un pas de plus vers sa libération !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGantelets polairesBaguette en martre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2041] = {title = "Allez voir Shoni", objective = "Aller voir Shoni la Silencieuse à Stormwind.", description = "Peut-être... Peut-être que vous pouvez nous aider dans la bataille de Gnomeregan.\n\nVous trouverez à Stormwind le commandant de notre équipe d'assaut souterraine, Shoni la Silencieuse. Shoni a besoin d'aide pour ses excavateurs gyrodrilmatiques.\n\nVous la trouverez probablement parmi les nains de Stormwind.\n\nBonne chance, <nom>.", progress = nil, completion = "Apportez-vous un message du commandement central ?", rewards = "Vous recevrez :\n\n"},
[2058] = {title = "<INUTILISÉ>", objective = nil, description = "Vous allez tuer un type, un membre de la Ligue des assassins. Il a tué le vieux chef des nécrotraqueurs.", progress = nil, completion = nil, rewards = nil},
[2059] = {title = "<INUTILISÉ>", objective = nil, description = "Bien supposé, vous nous intéressez.", progress = nil, completion = nil, rewards = nil},
[2078] = {title = "La vengeance de Gyromast", objective = "Trouver le Premier Officier de Gelkak, le Destructomembreur 4100, et le ramener à Gelkak.", description = "Bouseux de terrien ! Tu dois me dégoter mon Premier Officier.\n\nPrends c'te clé, mets-y dans le bon trou, et ramèn' le ici pour servir le cap'taine.\n\nCes murlocs et leur chef vont pas beaucoup aimer quand mon Premier Officier va leur mettre l'grappin dessus !", progress = "Où est mon Premier Officier, <nom> ? T'auras droit aux fers et aux requins si tu t’dépêches pas !", completion = "Rrr... Va falloir q'tu montres que t'es plus qu'un chien de mer gueulard, bouseux de terrien !\n\nLe cap'taine pourrait bien t'filer une promotion serpillière sur le pont de poupe si t'accélères pas l'mouvement...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nElixir de Respiration aquatique"},
[2098] = {title = "La recherche de Gyromast", objective = "Trouver et rapporter les 3 Morceaux de la clé de Gelkak à Gelkak Gyromast.", description = "La vie d'un pirate n'est pas facile, bouseux de terrien. C'est pas pillage et tafia à volonté ! Hélas ! Mon navire est à la baille, tout près du bord, à cause de ces saletés de battrodons.\n\nJ'ai b'soin que mon Premier Officier rapplique en ordre de marche !\n\nQuand j'me suis ramassé sur le rivage, la clé de contact de mon Premier Officier est tombée sur les rochers et a été chapardée par des bestioles du cru. Du coin de l'oeil, j'ai vu des clampants enragés, des trotteurs des forêts géants et des murlocs fouiller l'épave...", progress = "T'as r'trouvé ma clé cassée, bouseux de terrien ?", completion = "Bougre de scorbut de chien de mer ! T'as réussi ! Mon Premier Officier va remarcher bientôt et ces saletés d'bestioles sauront même pas qui les a frappées ! \n\nHum, t'as trouvé le Premier Officier ?", rewards = "Vous recevrez :\n\n"},
[2118] = {title = "Terres malades", objective = "Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun.", description = "Il y a une maladie qui s'étend à travers tout Sombrivage, contaminant les esprits et les organismes qu'elle touche.\n\nCe sont les ours des chardons qui ont été les plus touchés. Ces animaux, autrefois si nobles, sont devenus des instruments de destruction, enragés et frénétiques. J'ai peut-être trouvé un remède contre ce mal.\n\nApportez ce piège dans la forêt et placez-le au sol. N'importe quel ours des chardons enragé qui traversera cette lumière deviendra docile pour un court moment. Une fois que l'ours sera docile, il vous suivra. Ramenez-le ici, <nom>.", progress = nil, completion = "Notre travail vient seulement de commencer, &lt;nom&gt;. Vous sentez-vous prêt pour la tâche suivante ?", rewards = "Vous recevrez :\n\n"},
[2138] = {title = "Nettoyage de l'infection", objective = "Débarrasser la forêt de 20 Ours des chardons enragés et retourner voir Tharnariun Treetender, à Sombrivage.", description = "Comme je le craignais, le remède ne marche pas.\n\nCela m'attriste énormément de devoir ordonner la mort de certaines créatures de la nature, mais les ours des chardons malades et infectés doivent être éliminés.\n\nRetournez dans la forêt et détruisez 20 ours des chardons enragés, <nom>. Cela ne suffira sans doute pas à éradiquer la contamination, mais ça permettra de limiter pendant quelque temps les dégâts que ces animaux causent à notre forêt et à ses habitants.", progress = nil, completion = "Vous avez rendu à Auberdine un grand service, &lt;nom&gt;, mais votre tâche n'est pas encore terminée.\n\nRevenez me voir lorsque vous aurez pris un peu de repos.\n\nEt… &lt;nom&gt;, préparez votre esprit et votre âme à d'autres bains de sang.", rewards = "Vous recevrez :\n\n"},
[2139] = {title = "Espoir de Tharnariun", objective = "Trouver et tuer la Mère de la tanière.", description = "La survie de notre peuple et de nos terres a exigé des sacrifices, <nom>.\n\nHélas, vous avez dû verser le sang des serviteurs de la nature et bien des animaux sont tombés sous vos coups. Le peuple d'Auberdine vous doit beaucoup, et la souffrance de la forêt est apaisée, au moins pour le moment.\n\nJ'ai une dernière tâche à vous confier mais sachez qu'il vous faudra tuer de nouveau. J'espère de tout coeur que ce sera la dernière fois, <nom>.\n\nÀ côté de Bashal'Aran, dans une caverne au nord-est d'ici, habite la Mère de la tanière. Faites-la disparaître.", progress = nil, completion = "Vous avez combattu pour Auberdine avec courage et honneur, &lt;nom&gt;. Dans nos terres déchirées par la guerre, la mort et le désespoir sont familiers. Beaucoup choisiront de ne pas se lever pour affronter le défi de la vie dans ce nouveau territoire, préférant se terrer chez eux ou s'enfuir vers des pays mieux fortifiés de l'Alliance.\n\nMerci &lt;nom&gt; ! Le jour est peut-être proche où nous nous battrons côte à côte, comme des amis, contre un autre adversaire.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants vert sapinCape de bûcheron\n\nVous recevrez également :\n\n"},
[2158] = {title = "Repos et détente", objective = "Parler à l'aubergiste Farley, à l'auberge de la Fierté du lion.", description = "Tous les aventuriers doivent prendre du repos s'ils veulent éviter l'épuisement... Et pour cela, le meilleur endroit, c'est bien l'Auberge de la Fierté du lion ! \n\nMon meilleur ami, l'aubergiste Farley, tient cette auberge. Si vous venez de ma part, il vous fera sûrement des réductions sur le prix de la nourriture et de la boisson ! \n\nSuivez cette route vers le sud, vous ne pouvez pas la rater !", progress = nil, completion = "Le repos et la détente pour ceux qui sont fatigués et qui ont froid – c'est notre devise ! Je vous en prie, prenez place près du feu et reposez-vous.\n\nVoudriez-vous goûter quelques-uns de nos plus excellents mets et boissons ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPetite citrouilleEau de source\n\nVous recevrez également :\n\n"},
[2159] = {title = "Livraison à Dolanaar", objective = "Apporter la Livraison de Dolanaar à l'aubergiste Keldamyr.", description = "Salutations, jeune <classe>. Pouvez-vous m'aider ? Je dois livrer ce paquet d'herbes dans la ville de Dolanaar, mais ne puis partir d'ici car j'ai une tâche à terminer avec les druides de Sombrevallon.\n\nPouvez-vous livrer ce paquet pour moi ? Il doit être remis à l'aubergiste Keldamyr, à l'auberge de Dolanaar. Elle se trouve sur cette route, au sud.", progress = "En quoi puis-je vous être utile ? Voulez-vous prendre du repos à l'auberge ? Désirez-vous une place près du foyer ?", completion = "Ah oui ! La livraison d'herbes de Sombrevallon. Il est regrettable que Porthannius ne l'ait pas apportée lui-même, car nous avons beaucoup à nous dire, lui et moi. Mais je suis cependant heureux d'avoir ces herbes et de vous voir ici.\n\nPuisque vous êtes là, je vous en prie, reposez-vous. Les héros doivent garder leur force et leur esprit en forme, et pour cela, ils doivent profiter du moindre moment de repos et de consolation. Négliger la paix du corps et de l'âme conduit de façon certaine à l'échec.\n\nAlors... repos.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBleu de DarnassusEau de source\n\nVous recevrez également :\n\n"},
[2160] = {title = "Des provisions pour Tannok", objective = "Livrer la Caisse de ravitaillement à l'auberge de Tannok Frosthammer à Kharanos.", description = "Hé ! Vous avez l'air d'être un cœur généreux. Si vous projetez de prendre le Passage, pourriez-vous apporter un paquet à l'auberge de Kharanos ?\n\nVous vouliez vous arrêter à l'auberge, non ? Si vous prenez le Passage, vous aurez certainement envie de vous y reposer.\n\nQuoi qu'il en soit, apportez ceci à Tannok Frosthammer, l'assistant de l'aubergiste. Je ne peux pas passer le Passage moi-même et il faudra des jours avant qu'une escorte de Montagnards ne passe par ici !", progress = "Hé là ! Entrez, prenez place près du feu et réchauffez-vous avec une chope de bière.", completion = "Ah ! Enfin, les provisions de Hands ! Je commençais à m'inquiéter, nous n'avons que de rares nouvelles d'Anvilmar depuis que les troggs ont envahi le passage.\n\nMerci de me les avoir apportées, &lt;nom&gt;. Je vous en prie, installez-vous confortablement. Vous devez ressentir la fatigue du voyage.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nViande séchée coriaceEau de source\n\nVous recevrez également :\n\n"},
[2161] = {title = "Un Fardeau de Péon", objective = "Apporter le Fardeau d'Ukor à l'aubergiste Grosk à Tranchecolline.", description = "Excusez-moi... Pouvez-vous m'aider ? \n\nVous voyez ce chargement ? J'ai suivi la route, j'ai bravé les scorpides, les araignées, que sais-je encore, tout ça pour apporter ces vivres à la vallée des Epreuves. Je pensais qu'ils en auraient besoin... Mais non, ils n'en ont pas voulu ! Maintenant, il ne me reste plus qu'à rapporter tout ça à Tranchecolline et ça me terrorise, à cause des bêtes... \n\nVous pourriez vous en charger pour moi ? Je ne suis qu'un malheureux péon mais vous... Vous n'avez peur de rien, vous avez l'habitude d'être héroïque ! \n\nRapportez ce paquet à l'aubergiste Grosk à l'auberge de Tranchecolline. Merci !", progress = "Bienvenue à Tranchecolline !", completion = "Ah... C'est la nourriture qu'Ukor avait emportée à la Vallée des Epreuves. Ils n'en avaient pas besoin ? Je suppose qu'ils affament les héros pendant la formation, non ? Ce qui ne tue pas rend plus fort, ou quelque chose comme ça... \n\nBon, je vais remettre tout ça sur les étagères... Mais laissez-moi d'abord vous offrir un rafraîchissement ! \n\nEt n'oubliez pas de vous reposer un peu ici, à l'Auberge. Bien sûr, vous êtes très brave, &lt;classe&gt;, et vous voulez parcourir le monde. Mais sans un peu de repos, votre énergie s'épuisera et vous ne ferez pas grand-chose de bon pour la Horde !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMorceau de pain rassisEau de source\n\nVous recevrez également :\n\n"},
[2178] = {title = "Brouet de trotteur", objective = "Apporter 5 morceaux de Viande de trotteur à Alanndarian Nightsong, à Auberdine.", description = "Sentez-vous cet arôme délicieux ? C'est ma recette secrète, <nom> : le brouet de trotteur frais. Délicieux !\n\nLa recette vous intéresse peut-être ?\n\nAvant de vous l'apprendre, je veux voir comment vous vous débrouillez avec les bêtes.\n\nJe ne m'attends pas à ce que vous sortiez en dompter un, mais si vous pouvez en abattre quelques-uns et rapporter leur succulente viande, ça suffira à me convaincre que je peux vous montrer comment cuisiner mon brouet de trotteur.", progress = "Le pot est vide et j'ai faim ! Pourquoi est-ce si long ?", completion = "Fantastique ! Essayez ça et dites-moi ce que vous en pensez, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nRecette : Brouet de trotteurBrouet de trotteur"},
[2198] = {title = "Le Collier brisé", objective = "Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle.", description = "Vous avez trouvé un Collier terni mais sur lequel on devine encore des entrelacs compliqués et des signes magiques. Il a été brisé et on voit qu'il manque trois Gemmes. Sous le collier, on peut reconnaître le sceau de la ville d'Ironforge et, sous le sceau, trois toutes petites lettres : \"TdK\". \n\nS'il y a quelque chose à tirer de ce Collier, il va falloir revenir à ses origines. Le sceau et les initiales sont déjà un début...", progress = "Vous ne parlez pas au bon gnome ! Je n'y suis jamais allé ! Vous ne pouvez rien prouver ! \n\nEt d'abord, qui êtes-vous ? Et où... Bon sang ! D'où vient ce collier ?", completion = "Oui... C'est moi qui ai fabriqué ce collier. Et je ne suis pas du genre à donner gratuitement des informations, mon ami. Si vous voulez que je vous aide, vous devez d'abord m'aider MOI.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2199] = {title = "Le Prix de la Connaissance", objective = "Apporter 5 Barres d'Argent à Talvash del Kissel, à Ironforge.", description = "Je suis un joaillier de renom, ici, à Ironforge. Enfin, je l'étais... Je suis la victime d'un concurrent déloyal ! Dans ce métier, c'est la réputation qui fait tout... Et résultat, je me retrouve sans un sous, uniquement propriétaire d'un nom traîné dans la boue ! \n\nJe veux que vous me rapportiez cinq Barres d'argent pour terminer une commande qui m'a été faite - la première commande depuis des lustres ! \n\nVous me rapportez ces barres d'argent et je répondrai à vos questions au sujet du Collier.", progress = "Vous avez mes Barres d'argent ? Je vous raconterai en détail l'histoire du Collier... Quand j'aurai ces Barres ! Vous allez bien donner un coup de main à un gnome, non ?", completion = "Vous êtes quelqu'un de bien. Je me fiche de ce que peuvent dire les autres... C'est une blague ! Non, sérieusement, merci. \n\nCe Collier que vous avez trouvé est l'une de mes plus belles réussites, mais il lui manque les trois Gemmes pour retrouver son pouvoir magique. Je l'avais fait pour un paladin, il y a quelque temps. Il s'était fixé comme mission de nettoyer la \"contamination maléfique\" d'un site d'excavation nommé Uldaman, dans les Terres ingrates. \n\nEh bien, ce paladin est mort là-bas, et mes ennuis ont commencé comme ça.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2200] = {title = "Retour à Uldaman", objective = "Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté.\n\nObjet fourni : \n", description = "Un de mes concurrents a fait courir la rumeur que le collier avait maudit le paladin. Inutile de dire que personne ne vient acheter des bijoux maudits à un joaillier !\n\n<nom>, je vous propose un marché : trouvez les gemmes et je réparerai le collier, à condition que vous affirmiez partout que je ne fabrique PAS de bijoux maudits !\n\nCherchez des indices à Uldaman ; voyez si le corps du paladin est là-bas ; après tout c'est lui qui en était le dernier propriétaire ! Quand vous aurez les gemmes, utilisez ceci pour me contacter, ici à Ironforge.", progress = nil, completion = "En lisant le journal, vous apprenez qu'après bien des efforts, le paladin avait localisé les gemmes manquantes :\n\nLes nains Ombreforge ont caché le rubis dans leur fortin, pendant qu'ils combattaient les troggs à Uldaman. \n\nLes troggs ont caché la topaze dans une urne qui se trouve près du lieu de résidence d'habitants assez inhabituels à Uldaman : les nains de l'Alliance ! \n\nQuant au saphir, c'est l'Ancien trogg qui l'a gardé.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2201] = {title = "Trouver les Gemmes", objective = "Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.\n* Le saphir est en possession du chef trogg, Grimlok.", description = "Le journal du paladin est sans doute le seul indice dans Uldaman qui puisse vous conduire aux gemmes. Si ce qu'il prétend est vrai, il va falloir traiter avec les nains Ombreforge et les troggs qui combattent pour le contrôle de l'excavation. \n\nLa traque des gemmes doit commencer immédiatement. Lorsqu'elles seront récupérées, il faudra prendre les instructions de Talvash à Ironforge en utilisant la Fiole de Divination.", progress = "L'image de Talvash apparaît dans l'eau de la coupe de divination. \n\n\"Et bien, vous êtes encore en vie ! Vous les avez ? Vous avez sauvé ma réputation ? Ne me dites pas que vous avez gâché une charge de la fiole simplement pour bavarder ! Ce n'est pas donné, et je suis déjà plus que fauché !\"", completion = "Oui... Ce sont les Gemmes. Joli travail ! Malheureusement, ce n'est pas tout. \n\nNon, je ne cherche pas à enquiquiner le monde, stupide &lt;classe&gt; ! Il s'agit de forger de la magie, ici ! De la joaillerie magique estampillée Talvash del Kissel ! Vous avez besoin d'une forte Source d'énergie pour donner à ce Collier un peu de pep's. Car ce collier ne dégage plus de pep's...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2202] = {title = "Rechercher les composants à Uldaman", objective = "Apporter 12 Champignons magenta à Jarkal Mossmeld à Kargath.", description = "On a découvert récemment une nouvelle plante : le champignon magenta. Ils poussent en grappes, au plus profond des excavations d'Uldaman ; il en existe peut-être ailleurs, mais je ne connais que cet endroit. Je veux étudier leur utilité éventuelle en alchimie, et c'est là que vous entrez en scène.\n\nTrouvez les champignons magenta et rapportez-m'en une douzaine. Attention, les grappes peuvent projeter des spores vénéneux quand on les manipule !\n\nRendez-moi ce service et je sortirai pour vous un petit élixir revigorant de derrière les fagots.", progress = "Vous avez les Champignons magenta dont j'ai besoin pour mes travaux ? Pas de Champignons, pas de récompense !", completion = "Bravo, &lt;nom&gt;, vous avez prouvé votre valeur, une fois de plus ! L'étude de ces plantes sera passionnante ! \n\nEt maintenant, comme promis, je vous offre un aperçu de l'une de mes préparations les plus revigorantes... \n\nSi vous êtes un alchimiste qualifié, nous pourrons peut-être continuer de travailler ensemble. De toute façon, merci pour votre aide !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPotion de restauration"},
[2203] = {title = "Les réactifs des Terres ingrates II", objective = "Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Mossmeld à Kargath.", description = "Votre aide m'a été précieuse, merci, <classe>. Je vous récompenserai en vous donnant la recette de l'Elixir que vous avez testé un peu plus tôt... mais je vais d'abord vous confier une mission dangereuse. Écoutez bien. \n\nCe coffret contient trois Récipients thaumaturgiques vides. Ils sont entourés d'une Aura d'harmonie qui attire le Sang de Gardien dragon brûlé. Attention ! Si vous n'en utilisez qu'un, la bête deviendra enragée. Lorsque vous aurez rempli les trois, rapportez-les-moi. \n\nVous aurez la recette de mon Elixir en échange.", progress = "Avez-vous utilisé les Récipients thaumaturgiques pour pomper le sang de dragon gardien des terres brûlées dont j'ai besoin ? Oui, je sais que c'est une opération dangereuse... Mais l’élaboration de mon breuvage fortifiant dépend de votre succès. Risque et récompense, mon ami. Risque et récompense...", completion = "Je vous salue, et c'est le salut d'un Alchimiste à un autre Alchimiste. Voilà, prenez cette recette et prenez-en connaissance. Vous connaîtrez peut-être grâce à elle le succès et la récompense qu'elle m'a apportés au cours des ans.", rewards = "Vous allez être la cible du sort suivant :\n\nPotion de Restauration\n\nVous recevrez :\n\n"},
[2204] = {title = "Réparer le Collier", objective = "Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Ironforge.", description = "Vous allez avoir besoin de \"pep's\" pour le collier, et l'endroit idéal pour en trouver, c'est Uldaman... Je suppose qu'il y a des tas de constructions qui se baladent par là-bas, non ? Il suffit de choisir la plus vile et la plus grande et de lui piquer sa Source d'énergie. Je suis presque sûr de pouvoir m'en servir pour le collier !\n\nSans source d'énergie, de toute façon, la réparation est impossible. Revenez-me voir à Ironforge quand vous l'aurez, et on verra ce qu'on peut faire !", progress = "Vous n'avez même pas fait un brin de toilette avant de rentrer, hein ? Vous arrivez directement, en traînant avec vous les odeurs fétides d'Uldaman... Espérons au moins que votre visite n'est pas seulement odoriférante... \n\nVous avez la Source d'énergie pour le Collier ?", completion = "Ben ça... Je suis ravi de vous voir en un seul morceau, cette Source d'énergie et vous ! Il va me falloir un moment pour fusionner le Collier et sa Source d'énergie par la magie, maintenant que les Gemmes ont retrouvé leur place... Et puis il sera à vous ! \n\nPas d'impatience ! Vous frétillez de nervosité ! Bon... Où ai-je donc rangé ce sort...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2205] = {title = "Chercher le SI:7", objective = "Remettre le colis de Keryn Sylvius à maître Mathias Shaw à la Caserne de Stormwind.", description = "L'insigne ? Rien... Rien qui soit pour vous... Si j'en juge par votre apparence, j'ai peur que Mathias vous prenne pour le livreur de fromage, mon enfant, au lieu du malandrin attendu. Enfin, on m'a donné un travail et j'ai promis de livrer ce travail. \n\nTiens, à propos, vous apporterez ce paquet à Mathias, et peut-être qu'il vous donnera un ou deux petits boulots à accomplir. \n\nAllez, du vent.", progress = "Comment puis-je vous être utile, <classe> ?", completion = "Vous m'avez trouvé et à vous regarder, je dirais que ce fut long et difficile, car vous me paraissez, physiquement et psychiquement, bien diminué.\n\nVoudriez-vous que Renzik vous accompagne à une auberge ou êtes-vous prêt dès à présent pour une mission ?", rewards = "Vous recevrez :\n\n"},
[2206] = {title = "Effraction", objective = "Trouver l'Intendant des docks défias et récupérer le programme d'embarquement, pour le compte de maître Mathias Shaw.", description = "Nos espions sur le terrain rapportent que les Défias sont très actifs dans le sud de Goldshire. Il semble qu'ils aient pris le Débarcadère de Jerod et qu'ils l'utilisent pour passer en contrebande de grandes quantités de produits entre les Carmines et la marche de l'Ouest.\n\nIl faut que vous vous introduisiez dans les docks et que vous me rapportiez le programme d'embarquement des navires, <nom>. Vous le trouverez probablement au profond des poches de l'Intendant des docks.\n\n... Et <nom>, si vous étiez découvert, sachez que le SI:7 nierait vous avoir jamais <connu/connue>.", progress = "Les dangers augmentent à mesure que vous perdez du temps à traîner dans la caserne, <classe>.", completion = "Je suis étonné... Etonné que Kerin ait enfin trouvé une recrue qui puisse faire un malandrin potable. Prenez cette lame, &lt;nom&gt;. Un jour viendra où on vous demandera encore de servir le SI:7. Préparez-vous, gardez les yeux ouverts et cette lame affûtée. \n\nVous ne nous verrez pas arriver, mais vous saurez vite quand nous serons là...", rewards = "Vous recevrez :\n\nLame de malice"},
[2218] = {title = "La voie du salut", objective = "Parler à Hulfdan Blackbeard à Ironforge.", description = "Une autre âme perdue en quête de conseil, hein ?Je suppose que vous cherchez une voie, votre voie. J'ai déjà vu ça mille fois, encore un héros désœuvré qui cherche du travail.\n\nEh bien, c'est aujourd'hui votre jour de chance, mon <ami/amie>. Hogral connaît la solution à votre tourment.\n\nVoici ce qu'il vous faut faire : prenez cette route jusqu'à Ironforge et cherchez-y la caverne lugubre. Une fois sur place, localisez la guilde des voleurs et demandez entretien à Hulfdan Blackbeard. Il vous guidera vers votre salut.", progress = nil, completion = "Alors, vous croyez êt' une vraie crapule ? Un qu'est destiné à êt' parmi les rares choisis de Blackbeard, un officier du Cercle secret ?\n\nY'a qu'un bon à rien, un impertinent pour êt' aussi imbu de lui-même.\n\nMais c'est exactement c'qu'on recherche! Alors bienvenue, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[2238] = {title = "Simple subterfuge", objective = "Trouver Onin MacHammar à Gnomeregan.", description = "Vous voyez, le roi a épuisé les carrières en extrayant le minerai de fer et les gemmes. Cela fait plus de richesses que n'en pourrait amasser un nain en vivant dix vies.\n\nLe Cercle secret a des valeurs, <nom>. Nous accordons de la valeur a ce qui a de la valeur. Vous comprenez ?\n\nNous pensons que le roi doit partager ce butin, mais nous ne voulons pas que \"Barbe-puante\" sache qu'il est en train de partager, pigé ?\n\nAdressez-vous à Onin MacHammar à Gnomeregan et rendez moi compte. Il est habile, il se cache parmi les lépreux. Faites attention.", progress = nil, completion = "Chut ! Moins de bruit, idiot. Ils vont nous entendre.", rewards = "Vous recevrez :\n\n"},
[2239] = {title = "Rapport d'Onin", objective = "Porter le rapport d'Onin à Hulfdan à Ironforge.", description = "La carrière ? Ouaip, je vois ces monstrueux chars à vapeur qui passent près de là, presque tous les jours.\n\nMes contacts, à l'est, me disent que le char quitte Ironforge, charge sa cargaison à la carrière de Gol'Bolar, se ravitaille à Kharanos et après, pour une raison bizarre, emprunte le long chemin qui contourne Gnomeregan avant d'atteindre Ironforge où il décharge.\n\nTout est dans le rapport, <nom>. Portez-le à Hulfdan, qu'il puisse réfléchir à la suite du plan.", progress = "Z'avez bien aimé la puanteur du gnome lépreux ? J'demande ça parce que z'avez comme un sourire un peu bizarre.\n\nQuelles nouvelles vous nous rapportez d'Onin ?", completion = "Longue marche ? Par ma barbe !\n\nZ'avez réussi, &lt;nom&gt;. Prenez cette dague et disparaissez. Le Cercle vous rappellera quand la troisième étape sera sur le point d'commencer.\n\nC'est quoi la troisième étape ? C'est celle qui vient après la deuxième, et j'peux aussi vous botter l'train.\n\nÇa vous dit ?", rewards = "Vous recevrez :\n\nLame de malice"},
[2240] = {title = "La Chambre secrète", objective = "Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Stormpike.", description = "Bon... Pour la tâche en cours...\n\nIl va falloir explorer une chambre secrète, la Chambre de Khaz'mul. Le problème, c'est qu'elle se trouve derrière une lourde porte fermée ! Il est heureux que je sache comment l'ouvrir ! \n\nJ'ai tout écrit dans ce journal, là, sur la table. Pour l'instant nous sommes coincés ici. Trouvez la Chambre de Khaz'mul pour nous, <nom> !\n\nLisez mon journal, explorez la Chambre, puis rendez compte au Prospecteur Stormpike de la Ligue des Explorateurs à Ironforge.", progress = nil, completion = "Vous avez vu la Chambre de Khaz'mul ? Fascinant ! Baelog affirmait son existence, mais j'avais des doutes... \n\nMerci, &lt;nom&gt;. Avec un peu de chance, cette découverte incitera nos chefs à renouveler leurs efforts pour reprendre Uldaman. Et si nous en reprenons le contrôle, les secrets de la Chambre de Khaz'mul serons nôtres !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPourfendeuse naineLanterne de la Ligue des Explorateurs\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2241] = {title = "Pomme d'amour", objective = "Porter la fleur de Jannok à Syurna à Darnassus.", description = "Ils disent que je suis fleur bleue... quoi que cela puisse vouloir dire.\n\nC'est vrai qu'à tout instant je pense à Syurna. C'est vrai, ma maison est tapissée de peintures et de dessins de Syurna. C'est vrai, je peux passer des jours sans manger, boire ou dormir en me languissant de l'amour que nous aurions pu connaître. Mais est-ce mal ?\n\nDésormais, elle ne me verra plus ! MOI ! J'ai essayé de lui envoyer des messages, mais elle ne parlera même pas à quelqu’un qui n’est pas un voleur.\n\nPourriez-vous lui porter cette fleur ? Et n'oubliez pas de dire que c'est de la part de Jannok.", progress = "Oh, n'est-ce pas merveilleux ? Vous avez apporté des fleurs pour vos propres funérailles.", completion = "Si j'avais conservé chaque fleur que ce balourd de Jannok m'a envoyée, j'aurais eu de quoi ouvrir un magasin de fleurs. Mais bon, il semble toutefois que le dernier courrier de Jannok puisse être utile.\n\nSeriez-vous intéressé par un travail, &lt;classe&gt;?", rewards = "Vous recevrez :\n\n"},
[2242] = {title = "L'appel du destin", objective = "Trouver Sethir l’Ancien et rapporter tout indice découvert à Syurna.", description = "Nous pensons qu'il existe un être qui pourrait nous aider à comprendre ce qui arrive aux forêts de Teldrassil. Malheureusement, toutes les tentatives pour amener la créature à coopérer se sont soldées par un désastre.\n\nIl se cache sur une branche, sur le rebord de la clairière de l'Oracle. À ce jour, tous ceux qui ont approché le satyre, par la force ou la diplomatie, ont été anéantis. Le camouflage est peut-être la solution, <nom>.\n\nTrouvez ce que Sethir l'Ancien cache dans ses poches et faites-moi un rapport.", progress = "Avez-vous pu obtenir des informations de Sethir l'Ancien, <nom> ?", completion = "Voilà de bien sombres nouvelles, &lt;nom&gt;. Il semblerait que la pestilence qui s’est emparée des forêts et des rivières de Sombrivage ait commencé à infecter notre pays.\n\nVous nous avez loyalement servi, mais il n'y a rien que vous puissiez encore faire ici. Prenez cette épée en guise de récompense.", rewards = "Vous recevrez :\n\nLame de malice"},
[2258] = {title = "Les réactifs des Terres ingrates", objective = "Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates.", description = "<nom>, je pourrais avoir l'usage de vos capacités. Je suis un alchimiste de quelque renom et j'ai besoin de votre aide pour acquérir des composants que l'on ne peut trouver que dans les Terres ingrates. \n\nJ'ai besoin des objets suivants pour réapprovisionner mon stock : cinq Gésiers de busards, dix Crocs de coyote des rochers et cinq Fragments d'élémentaire de roche. A prendre sur les bêtes elles-mêmes, bien entendu... Si vous n'êtes pas du genre batailleur, trouvez quelqu'un qui le soit ! \n\nTrouvez-moi ces objets, et vous aurez quelques pièces en échange, ça vous va ?", progress = "Avez-vous ce que je vous ai demandé ? Vous ne serez payé que lorsque vous m'aurez rapporté ces ingrédients.", completion = "Ah ! Bien joué ! Ça devrait me permettre de tenir un petit moment. Voici votre paye, comme promis.\n\nSi ça vous dit, j'ai également besoin de composants qu'on ne trouve que dans les profondeurs d'Uldaman. Ils ne seront pas facile à obtenir, mais je ferai en sorte que la récompense soit à la hauteur des efforts fournis.\n\nPeut-être autre chose que quelques pièces brillantes, hein ?", rewards = "Vous recevrez :\n\n"},
[2259] = {title = "Erion Shadewhisper", objective = "Contacter Erion Shadewhisper à Darnassus.", description = "Ne vous inquiétez pas, <nom>, je ne vous envoie pas voir Syurna. Erion veut que vous le rejoigniez dans l'Enclave de Cenarion. Faites vite !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2260] = {title = "L'ordre d'Erion", objective = "Voyager vers Stormwind pour y rencontrer Renzik \"le Kriss\".", description = "Le Service de Renseignement de Stormwind (SI:7) a entendu parler de vos exploits, <nom>, et il veut vous recruter. \n\nLe voyage est coûteux et périlleux, mais on ne rejette pas l'opportunité de s'entraîner pour le SI:7 !\n\nUn nouveau monde s'ouvre à vous, <nom>. Rendez-vous dans la vieille ville de Stormwind et adressez-vous à Renzik \"le Kriss\" \" au QG du SI:7.", progress = nil, completion = "Vous avez répondu à l'appel du SI:7, &lt;nom&gt;, et avez fait longue route pour rejoindre nos rangs ; il vous reste néanmoins encore beaucoup à apprendre.", rewards = "Vous recevrez :\n\n"},
[2278] = {title = "Les Disques de platine", objective = "Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon.", description = "Les pièces centrales de cette chambre au trésor sont quatre larges disques de platine ornés de sceaux d'origine inconnue. Lorsque vous les touchez, vous sentez un frémissement. Le visage d'un grand Gardien des pierres apparaît alors. \n\n\"Salut à vous. Je suis le Gardien du Savoir. La synthèse des Créateurs de la Terre a été gravée et conservée dans les Disques de Norgannon.\"\n\nVous avez découvert une manne de savoir inconnu du monde entier !", progress = "La voix du Gardien paraît résonner au plus profond de vous-même. \n\n\"Vous devez d'abord passer une épreuve d'assimilation des données des Disques de Norgannon ; ensuite, il vous sera permis d'en emporter une version portable. Commencez donc par lire attentivement les informations qui se trouvent dans ce reposoir.\"", completion = "Maintenant que vous connaissez l'histoire des troggs, des nains et de la terre, vous suivez les instructions du Gardien des pierres et revenez vers les Disques de Norgannon. Vous entendez un faible bourdonnement, assez bref. Puis le Gardien parle de nouveau : \n\n\"les Disques de Norgannon ont été compressés. Touchez-les de nouveau pour obtenir votre copie personnelle.\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2279] = {title = "Les Disques de platine", objective = "Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Ironforge.", description = "Votre main vibre de nouveau au contact des Disques de Norgannon. Cette fois, pourtant, c'est un étrange grincement qui se fait entendre. \n\nSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des Disques ! \n\nVoilà qui sera utile à tous ceux qui s'intéressent à l'histoire ancienne d'Azeroth. La Ligue des Explorateurs d'Ironforge est connue dans toute l'Alliance pour ses recherches sur le sujet ; ils devraient pouvoir faire bon usage de tout ceci.", progress = "Puis-je vous aider ? Je suis très occupé mais si cela peut avoir un intérêt pour la Ligue des Explorateurs, j'écoute.", completion = "Qu'avez-vous là... Oh ! D'où ça vient ? \n\nNon, c'est vrai ? \n\nVous en avez parlé à quelqu'un ? \n\nNON ? \n\nJeune &lt;classe&gt;, c'est la découverte archéologique de l'année ! Par les Dieux, qu'est-ce que je dis : du siècle ! Si ces Disques sont bien ce que je crois, c'est la clé que nous cherchions ! Cela pourrait bien être la preuve indubitable de la légitimité de l'origine magique des nains !", rewards = "Vous recevrez :\n\n"},
[2280] = {title = "Les Disques de platine", objective = "Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff.", description = "Votre main vibre de nouveau au contact des Disques de Norgannon. Cette fois, pourtant, c'est un étrange grincement qui émane des disques. \n\nSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des Disques ! \n\nVoilà qui sera utile à tous ceux qui s'intéressent à l'histoire ancienne d'Azeroth. Les Sages de Thunderbluff sont connus dans toute la Horde pour leurs recherches sur le sujet ; ils devraient pouvoir faire bon usage de tout ceci.", progress = "Je lis la fougue et la jeunesse dans le pas déterminé qui vous amène sous ma tente... Que cherchez-vous ? Un conseil sur un sujet vital pour la Horde ? La révélation des secrets de l'Univers ?", completion = "Qu'est-ce donc ? \n\nImpressionnant ! Je sens dans ces Disques des secrets que la Terre avait longtemps protégés. Vous avez fait preuve d'une grande sagesse en me les apportant.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2281] = {title = "Le Rendez-vous des Carmines", objective = "S'aventurer vers Lakeshire dans les Carmines et parler à Lucius.", description = "Vous jeter maintenant sur le champ de bataille serait pur suicide. Renzik ne veut pas d'un autre cadavre de voleur dans son équipe. Mais pas d'inquiétude, <nom> : Renzik vous mettra à niveau.\n\nDirigez-vous vers les Carmines et discutez avec Lucius, un associé du SI:7. Vous le trouverez facilement, il traîne généralement autour des docks de Lakeshire avec d'autres bons à rien.", progress = nil, completion = "Ah, z'êtes un peu maladroit d'vos dix doigts, hein ? Bah, pas grave, &lt;nom&gt;, j'en ai transformé des plus mauvais que vous en vrais voleurs accomplis.", rewards = "Vous recevrez :\n\n"},
[2282] = {title = "La scierie d'Alther", objective = "Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Lakeshire.", description = "J'entraîne des voleurs depuis des années ! Après tout, c'est pas n'importe quel vaurien qu'est né avec la grâce et la finesse du vieux Lucius.\n\nUn peu plus loin, z'allez trouver la scierie d'Alther. J'y ai un coffre fermé qui contient que'q' chose d'important. Allez le récupérer pour moi. Ramenez-moi ce qui s'y trouve, et vous recevrez vot' Certificat de voleur !", progress = "Au fait, avais-je oublié de mentionner les orcs ?\n\nJ'ai cru comprendre qu'il y en avait qui traînaient près de la scierie.", completion = "Vous l'avez forcé ? Joli travail, &lt;nom&gt;. \n\nSi vous mourez maintenant nous saurons que c'est par stupidité, pas par inexpérience !", rewards = "Vous recevrez :\n\nCertificat des voleurs"},
[2283] = {title = "Réparer le Collier", objective = "Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé.", description = "Nous avons du travail pour vous, si vous avez du cran...\n\nAu plus profond de l'excavation d'Uldaman, dans les Terres ingrates, il paraît qu'il y a les restes d'un crétin de paladin qui est mort par là il y a pas longtemps. Ça nous intéresse pas, sauf qu'il avait un collier de prix avec lui. On dit qu'il y avait trois Gemmes dessus : un Rubis, un Saphir et une Topaze.\n\nBon alors voilà : on le paiera très cher. Il est peut-être abîmé mais on s'en moque. On le réparera.", progress = "Vous avez le Collier ? Vous n'aurez pas un sous si vous ne nous le rapportez pas !", completion = "Ouiiiii... Je sens le Collier d'ici... Voyons ce joyau... \n\nMais qu'est-ce que vous croyez ? Il manque les Gemmes ! Vous imaginiez qu'on ne s'en apercevrait pas ? Même Malton verrait qu'elles sont pas d'ssus ! \n\nBon, OK, p'têt que vous les avez pas volées... Mais, de toute façon, ce collier n'vaut rien sans les Gemmes ! Le boulot est loin d'êt' terminé !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2284] = {title = "Réparer le Collier, deuxième prise", objective = "Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes.", description = "Aussi vrai que Malton est un crétin, ces gemmes sont encore quêk part dans Uldaman. Va falloir y r'tourner. \n\nComme j'l'ai d'jà dit, si les informations que nous avons sont justes, il y a un rubis, un saphir et une topaze. \n\nOù elles sont, comment je l'saurais ? Si vous avez du bol et qu'vous trouvez l'corps du paladin, et qu'il a pas encore été nettoyé, elles s'ront p'têt encore là.", progress = nil, completion = "On dirait que vous avez trouvé les restes du paladin dont parlait Dran. En fouillant le corps, vous trouvez ce qui semble être son journal. Le livre est en mauvais état et du sang séché recouvre de grands pans de texte. Ce que vous pouvez lire ressemble à du charabia ; il est écrit dans la langue native des humains, pour autant que vous sachiez.\n\nVous devez faire traduire ce livre pour en extraire les informations.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2298] = {title = "Kingly Shakedown", objective = "Aller à Stormwind et chercher Renzik \"le Kriss\".", description = "Alors on était là, en train de comploter pour la phase III quand d'un coup, deux crétins de Magni se pointent en parlant de je ne sais quel coup, et d'arrêter ceux du Cercle secret.\n\nPersonne ne porte la main sur le vieux Blackbeard ! La discussion s'envenime, blabla, paf, et soudain on prononce vot' nom !\n\nV'voulez un conseil ? Prenez le premier Griffon pour Stormwind. Une fois là-bas, allez voir Renzik \"le Kriss\" dans la vieille ville. C'est un vieil ami à moi.", progress = nil, completion = "Il est toujours bon d'avoir dans ses rangs un des voleurs de Hulfdan !", rewards = "Vous recevrez :\n\n"},
[2299] = {title = "Cap sur Hulfdan !", objective = "Se rendre à Ironforge et parler à Hulfdan Blackbeard.", description = "Où donc étiez-vous, <nom> ? Hulfdan vous cherche partout. On craignait que le roi ne vous ait fait mettre aux fers.\n\nAllez à Ironforge dès que possible et parlez à Hulfdan !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2300] = {title = "SI:7", objective = "Aller à Stormwind et chercher Renzik \"le Kriss\".", description = "Renzik vous cherchait, l'ami.\n\nJe ne ferais pas attendre le bras droit de Mathias à votre place.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2318] = {title = "La Traduction du Journal", objective = "Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates.\n\nObjet fourni : \n", description = "Vous êtes dans l'impasse si vous n'arrivez pas à faire traduire le journal dans une langue que vous comprenez. Il doit bien y avoir des gens qui en sont capables, non ? L'endroit le plus proche où vous pourriez trouver un traducteur, c'est l'avant-poste de Kargath dans les Terres ingrates. C'est le mieux pour commencer !", progress = nil, completion = "&lt;classe&gt;, Je sais quelle aventure vous amène ici, dans les Terres ingrates. C'est ma connaissance des langues qui vous intéresse ? Je sais que vous êtes à la recherche des morceaux du collier que vous avez trouvés dans Uldaman.\n\nEt oui, c'est mon rôle de tout savoir. Mais discutons plutôt de ce que vous êtes prêt à faire pour traduire ce journal. Croyez-moi, je suis le seul qui puisse le faire.\n\nLaissez-moi vous faire une meilleure offre que Dran Droffers, ce qui ne vous empêchera pas de conclure vos affaires avec eux. Intéressé maintenant ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2338] = {title = "La Traduction du Journal", objective = "Laisser Jarkal emprunter le Collier en échange de la traduction du Journal.", description = "Ceux de la Récupération Droffers et fils sont trop bêtes pour restaurer la magie du Collier. Moi, je peux le faire. Je veux l'étudier pour apprendre à le confectionner moi-même. Pour ce faire, j'aurai besoin de votre collier. Laissez-le-moi et en échange je vous traduirai le journal. Le temps que vous trouviez les Gemmes, j'aurai le loisir d'apprendre ce qui m'intéresse. \n\nUn marché simple et sans duperie... Alors, qu'en pensez-vous ?", progress = "Vous y avez réfléchi, n'est-ce pas ? Vous seriez une personne avisée si vous acceptiez ce marché, <classe>... Chacun obtiendra ce qu'il veut, même la société de Récupération Droffers et fils, alors qu'ils ne savent pas bien ce qu'ils cherchent...", completion = "Vous savez repérer une bonne affaire quand elle se présente ; je savais que je pouvais compter sur vous.\n\nPatientez un moment, le temps que je lance le sort qui traduira la langue humaine en un langage que vous comprendrez. Je suis un troll de parole ; renseignez-vous auprès de quiconque dans la Horde au sujet de Jarkal Mossmeld. Maintenant, commençons...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2339] = {title = "Trouver les Gemmes et la Source d'énergie", objective = "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.\n* Le saphir est possession du chef trogg, Grimlok.", description = "Voici la traduction du journal, pour que vous puissiez le lire de votre côté.\n\nIl est crucial de savoir que ce sont les nains qui ont caché le rubis, les troggs la topaze et que c'est un trogg nommé Grimlok qui a le saphir.\n\nBon. Ensuite, vous aurez besoin d'une source d'énergie pour que le Collier fonctionne de nouveau. Et ça, Dran Droffers ne le sait pas. Pour en trouver une, moi, j'irais au plus profond d'Uldaman et je détruirais les machines les plus puissantes. Elles doivent en disposer !\n\nQuand vous aurez tout ça, revenez me voir.", progress = "Il va falloir retourner dans les profondeurs d'Uldaman si vous n'avez pas les Gemmes et la Source d'énergie nécessaires pour permettre la canalisation magique dans le Collier. \n\nVous pourrez récupérer les Gemmes pour les livrer aux triples crétins d'Orgrimmar mais la Source d'énergie sera pour moi, puisque c'est ça qui permet au Collier de fonctionner..", completion = "Bien joué, &lt;classe&gt;. Nous allons tirer les fruits de cet effort. J'en ai fini avec le Collier lui-même et je sais que je pourrai le dupliquer.\n\nJe vais rapidement analyser ces gemmes avec une incantation avant que vous les rapportiez à Orgrimmar avec le Collier. Ce ne sera pas long.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2340] = {title = "Livrer les Gemmes", objective = "Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar.", description = "Un collier et des gemmes ordinaires marcheront aussi bien, du moment qu'ils sont faits du même matériau. Cette Source d'énergie, en revanche, c'est elle qui va donner sa magie au Collier... Enfin j'espère ! \n\nJe fournirai volontiers les gemmes nécessaires pour la confection de votre version du Collier, si toutefois cette Source d'énergie fonctionne. \n\nRetournez à Orgrimmar, et terminez votre marché avec Droffers et Fils. Ne leur dites rien de notre rencontre et lorsque vous reviendrez, je pourrais bien avoir un cadeau pour vous.", progress = "Tiens, mais qui voilà ! Ça vous aura pris un moment pour revenir... Je ne vous paierai que lorsque le lot sera complet ! Et faites-moi confiance, on vérifiera tout ! On vérifiera deux fois, et trois fois s'il le faut !", completion = "C'est bon. On peut garder le sac, aussi ? Merci... J'apprécie. \n\nCe collier est notre meilleure prise ! Pleurez pas, y vous irait pas de toute façon. Ah ! Ah ! \n\nBon, un marché, c'est un marché. Voici votre part. On aura peut-être encore du boulot pour vous plus tard, mais en attendant, du vent !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2341] = {title = "Réparer le collier, troisième prise", objective = "Rendre visite à Jarkal Mossmeld à Kargath pour constater (ou non) son succès.", description = "Pendant que Dran et Malton Droffers se disputent la prise, la moitié de l'affaire est maintenant close. Il vous reste à retourner dans les Terres ingrates pour finir tout ça. Jarkal Mossmeld, à Kargath, pourrait avoir une récompense spéciale à vous donner.", progress = nil, completion = "Votre Source d'énergie a dépassé toutes mes espérances. J'ai réussi à fabriquer un Collier pour moi et un pour vous... Et je pourrais encore en faire trois de plus... Un marché équitable, non ? Et les dupes sont les Droffers... \n\nEh bien, camarade... Félicitations pour le travail d'exception que vous avez réalisé... Et voici quelque chose de spécial pour vous récompenser de vos efforts...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCollier d'amélioration de Jarkal"},
[2342] = {title = "Des Trésors à recouvrer", objective = "Rapporter à Patrick Garrett, à Undercity, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman.", description = "Balayer les enclos à chauve-souris avec ce balai, ce n'est pas digne d'un Garrett ! J'ai fait quelques économies avec ce boulot maudit, et je suis prêt à les dépenser pour améliorer mes conditions de travail. \n\nL'arme familiale des Garrett est restée enfermée dans notre Coffre, dans le Hall commun sud d'Uldaman, où nous avons trimé comme mineurs. Sans elle, je suis coincé ici pour toujours, à balayer derrière ces immondes chauve-souris ! \n\nRapportez-moi ce trésor de famille ! Aidez-moi à retrouver ma dignité !", progress = "Je n'en finis plus de balayer ! Ces chauves-souris se jouent de moi ! Vous avez récupéré mon Trésor ? Je vous ai offert mon argent ! Que voulez-vous de plus ?", completion = "Enfin ! Un balai digne d'un Garrett ! Vous valez bien les pièces d'argent que je vous donne ! \n\nVous avez entendu, les chauves-souris ? J'ai l'arme de prédilection des Garrett ! Tremblez, les chauves-souris, tremblez !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2358] = {title = "Cornes de Nez'ra", objective = "Rapporter les Cornes de Nez'ra à l'Ombre d'Arantir, à Lakeshire.", description = "Il y a bien des lustres, les Cornes de Nez'ra ont été volées au manoir de Ravenholdt. Je les ai cherchées par le monde entier, sur terre comme sur mer. Et tout ce temps, ce sont ces bêtes immondes les avaient !\n\nExterminez tous les orcs Blackrock que vous croiserez jusqu'à ce que vous retrouviez les Cornes de Nez'ra.\n\nFaites ceci pour moi, <nom>, et votre renommée atteindra Ravenholdt.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nThé de chardon"},
[2359] = {title = "La Tour de Klaven", objective = "Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Stormwind. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.", description = "Je suis là, à surveiller cette tour depuis des semaines, <nom>. Récemment, un chargement important est arrivé du bois de la Pénombre, protégé par ces gardes. \n\nQue sont-ils ? Aucune idée. La seule chose que je puisse affirmer, c'est qu'ils ne sont pas humains. \n\nQuoiqu'il en soit, dans cette cargaison repose un coffre, et je suppose que ces abominations sont commises à sa garde. Le gros avec les piques, là, possède une clé dont nous aurons besoin.\n\nRécupérez cette clé, entrez dans la Tour et découvrez ce que contient ce coffre. Rapportez à Mathias le produit de votre recherche.", progress = "Des nouvelles de l'Agent Kearnen ?", completion = "Ça expliquerait les pantins défias que Kearnen et vous avez vus hors de la tour, &lt;nom&gt;. Et l'implication de la KapitalRisk avec les Défias, ou encore l'étrange cargaison venue du bois de la Pénombre... \n\nSi j'en crois ce livre, les trolls Zanzil de Strangleronce ont découvert une potion pour réveiller les morts... Ou, pour être plus clair, un poison. \n\nVous ne serez d'aucune aide au SI:7 sans une bonne connaissance des poisons, &lt;nom&gt;... Surtout avec la recette de fabrication des morts-vivants à portée de la main.", rewards = "Vous allez être la cible du sort suivant :\n\nPoisons\n\nVous recevrez :\n\nRecette : Thé de chardon"},
[2360] = {title = "Mathias et les Défias", objective = "Se rendre dans la marche de l'Ouest et trouver l'Agent Kearnen pour un débriefing.", description = "Pas trop tôt, <nom>. Les éléments de reconnaissance du SI:7 nous apprennent les Défias sont inhabituellement actifs dans la marche de l'Ouest.\n\nOn dirait qu'ils ont pris une ancienne Tour de guet de l'Alliance abandonnée au sud-est de la Colline des sentinelles, et qu'ils s'en servent comme base d'opérations pour leurs trafics à partir de la route d'approvisionnement des Carmines.\n\nAllez dans la marche et contactez l'Agent Kearnen. Elle est cachée à proximité de la tour. \n\n... Oh, <nom>, si vous veniez à être <capturé/capturée>, le SI:7 nierait avoir eu connaissance, etc.", progress = nil, completion = "Mathias s'est enfin décidé à m'envoyer du renfort ! J'espère qu'il est prêt à entendre des mauvaises nouvelles !", rewards = "Vous recevrez :\n\n"},
[2361] = {title = "Réparer le Collier", objective = "C'est avec joie que je vous donne ce collier, <classe>. Vous m'avez rendu un service inestimable. Portez-le avec fierté et n'hésitez pas à citer fréquemment et à voix haute le nom du fabriquant ! \n\nEt si vous pouviez préciser au passage qu'il n'est pas maudit, ce serait parfait.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCollier d'amélioration de Talvash"},
[2378] = {title = "Trouver la Main brisée", objective = "Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l'ombre.", description = "Vous avez bien servi les Traqueurs de ténèbres, <nom>, mais il est temps d'étendre votre expérience. Vous avez montré vos capacités en matière de ruse et de traîtrise, mais votre entraînement n'est pas terminé. \n\nLes Traqueurs de ténèbres ont des alliés au sein de la Main brisée. Cherchez ceux qui viennent à notre aide : trouvez Shenthul à Orgrimmar.", progress = nil, completion = "C'est donc vous que nos puissants alliés expédient à Shenthul ? Pas très engageant...", rewards = "Vous recevrez :\n\n"},
[2379] = {title = "Zando'zan", objective = "Parler à Zando'zan à la Faille de l'ombre.", description = "Votre seule détermination ne suffira pas pour affronter les obstacles qui nous attendent. \n\nAdressez-vous à Zando'zan pour commencer votre entraînement comme opérationnel de la Main brisée. \n\nLorsque vous maîtriserez le noble art du vol et de la tricherie vous pourrez faire un pas de plus vers votre destinée.", progress = nil, completion = "Zando'zan avait peut-être tort. Zando'zan présente des excuses.", rewards = nil},
[2380] = {title = "Cap sur Orgrimmar !", objective = "S'adresser à Shenthul à la Faille de l'ombre à Orgrimmar.", description = "Spécialiste de la forfaiture et de la tricherie, vous ne l'êtes pas, mais ça peut changer. Il semble que vous ayez impressionné les chefs avec vos maigres talents, puisque le grand Shenthul lui-même vous réclame. \n\nPrenez la route vers le nord jusqu'à Orgrimmar et adressez-vous à Shenthul à la Faille de l'ombre.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2381] = {title = "Piller les Pilleurs", objective = "Rapporter le Trésor des Mers du sud à Wrenix le Misérable à Ratchet. Ne pas oublier d’obtenir un B.G.A.C. et des Outils de voleur de l’Appareil bidulotronique de Wreni. Ces deux éléments sont nécessaires pour accomplir la mission.\n\nEn cas d’attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C.!", description = "Sans vouloir vous effrayer, <nom>, les cinq derniers qui ont essayé de voler le trésor des Mers du sud ont été mis en pièces.\n\nLe long de la côte, au sud, vous trouverez le \"Tranche-les-vagues\", le navire des Flibustiers des Mers du sud. Le trésor se trouve dans la cale. Au deuxième niveau se trouve la salle des pirates, une salle d'entraînement pour leurs voleurs.\n\nMontez à bord, volez le trésor, et rapportez-le-moi. Utilisez la salle des pirates si vous voulez vous entraîner, mais attention : prudence !", progress = "Enfin, au moins, vous avez conservé tous vos membres...Et le trésor ?", completion = "Incroyable ! Impossible ! Etonnant... Vous avez du talent, &lt;nom&gt;. Ou alors vous avez une veine de... Bref... \n\nVoici votre part du butin. Ce truc vous fera sûrement plus d'usage qu'à moi.", rewards = "Vous recevrez :\n\nThé de chardon"},
[2382] = {title = "Wrenix de Ratchet", objective = "Aller jusqu'à Ratchet pour voir Wrenix le Misérable.", description = "Zando'zan l'a vu ! Oui, le jour vient ! La mort de l'esclave... Le poignard dans le dos, le poison suintant de chaque veine... Zando'zan en a trop dit.\n\n<nom> ! Zando'zan a une tâche pour <nom> ! <nom> doit aller à Ratchet, à l'est de la Croisée, pour rencontrer Wrenix le Misérable. Allez !", progress = nil, completion = "Encore un ? Les cinq derniers que ces trolls inconscients m'ont envoyés ont fini dans l’estomac des requins. Espérons que vous valez un peu mieux, hein ?", rewards = "Vous recevrez :\n\n"},
[2383] = {title = "Parchemin simple", objective = "Lire le Simple parchemin, et parler à Frang, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l’extérieur de l’Antre, dissimulé dans l’ombre.", progress = "Qu'est-ce que vous avez là ? Un parchemin ? Vous n'êtes pas un savant, j'espère ?", completion = "Oh ! C'est mon parchemin… On m'avait dit que vous viendriez à la vallée, &lt;nom&gt;. Je suis heureux de voir que vous l'avez fait. Espérons que vous survivrez à vos prochains défis. Comme je disais, venez me voir au cours de votre progression, je ferai mon possible pour vous enseigner la voie du &lt;classe&gt;.\n\nBonne chance, &lt;nom&gt; et revenez me voir quand vous vous sentirez prêt.", rewards = "Vous recevrez :\n\n"},
[2398] = {title = "Les nains perdus", objective = "Trouver Baelog dans Uldaman.", description = "Le site de fouilles d'Uldaman n'a pas toujours été mal fréquenté. Nous, les nains d'Ironforge, contrôlions le secteur... jusqu’à la venue des troggs. Ils sont arrivés si vite et si nombreux que même des nains n'ont pas pu les arrêter !\n\nLeur attaque a été si soudaine que je crains que certains des nôtres soient pris au piège derrière les lignes ennemies.\n\nMon ami Baelog a conduit une petite troupe assez loin dans le site avant d'être repéré. S'ils sont vivants, je veux que vous les trouviez.", progress = nil, completion = "Il était grand temps que vous vous montriez ! J'ai failli perdre mon pari avec Olaf !\n\nIl a parié que sa barbe descendrait jusqu’à ses genoux avant de voir un autre &lt;race&gt; vivant. Eh bien, vous voilà et comme vous pouvez le constater, il manque quelques pouces à la barbe d'Olaf pour gagner son pari.\n\nMerci, &lt;nom&gt;. Je partagerai les gains avec vous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2399] = {title = "Les racines ont poussé", objective = "Les racines que Denalan a plantées dans son jardin ont poussé et grandi. Elles tremblent, désireuses d'être choisies...", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRacine éclose"},
[2418] = {title = "Les pierres de puissance", objective = "Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates.", description = "Je viens d'avoir un problème avec les nains Ombreforge. Ils m'ont amené à la forteresse d'Angor pour étudier deux sortes de pierres étranges venant d'Uldaman. J'ai découvert que ces pierres, à condition d’être bien utilisées, étaient des sources d'énergie stables. C'est étonnant tout ce qu'on peut trouver sur ce vieux site !\n\nBref, après leur avoir appris le secret des pierres, ils m'ont chassé de la forteresse et ont commencé les fouilles.\n\nJe veux ces pierres ! Apportez-moi ces deux sortes de pierres et je vous paierai bien !", progress = "Avez-vous les Pierres de puissance, <nom> ? Mon robot-rongeur a besoin d'une alimentation électrique...", completion = "Bravo, vous les avez trouvées ! Merci beaucoup, &lt;nom&gt;. Je n'ai pas rencontré |2 &lt;race&gt; plus fiable ! \n\nJe vais les essayer sans attendre sur quelques dispositifs de mon invention. Je parie que, dans les conditions adéquates, les dispositifs alimentés par ces pierres vont fonctionner encore et encore...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCercle de pierres alimentéBrassards de DuracinBottes perdurantes\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2438] = {title = "Le Capturêve d'émeraude", objective = "Apporter le Capturêve d'émeraude à Tallonkai Swiftroot à Dolanaar.", description = "Un jour, Gaerolas Talvethren, le Gardien des druides du Refuge des saisons de Ban'ethil, m'a donné un Capturêve d’émeraude. Cette puissante amulette est capable d'aspirer l'énergie du Rêve d'émeraude pour donner de la chance à ceux qui la portent.\n\nHélas, je n'ai pas pu la récupérer dans ma commode au village de Brise-stellaire... Autrefois, Brise-stellaire était un endroit tranquille, mais il a succombé à la corruption des furbolgs qui y résident.\n\nVoudriez-vous récupérer mon Capturêve, <classe> ?", progress = "Faites vite, je vous en prie ! Je ne peux qu'espérer que mon Capturêve d'émeraude n'a pas été abîmé par les furbolgs.\n\nL'avez-vous retrouvé, <nom> ?", completion = "Mon Capturêve d'émeraude compte beaucoup pour moi. C'est un cadeau offert à peu de personnes. Merci de me le rapporter, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2439] = {title = "Les Disques de platine", objective = "Apporter le Bon de récompense à Dinita Stonemantle à la Chambre forte d'Ironforge.", description = "Cet objet est incroyable. Si ce qu'il dit est vrai, les anciens Titans, ou les Créateurs comme ces disques les nomment, sont le lien avec notre création enchantée ! Nous devons investir autant de temps que possible dans cette recherche.\n\nPour vous, héroïque <classe>, apportez ce bon à Dinita Stonemantle à la Banque. Il vous donnera une récompense à la hauteur de cette magnifique trouvaille !\n\nRevenez directement me voir quand vous serez <prêt/prête>, il y a encore beaucoup à faire pour la Ligue !", progress = "Bienvenue à la Chambre forte d'Ironforge, <nom>. Que puis-je faire pour vous ?", completion = "Ah oui ! Un bon de la Ligue des Explorateurs... et d’un joli montant, qui plus est.\n\nJ'ai l'autorisation de vous offrir une rémunération débitée sur les comptes de la Ligue. Vous devez recevoir ceci et vous pouvez choisir pour récompense soit 5 Potions de guérison supérieures soit 5 Potions de mana supérieures.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPotion de soins excellentePotion de mana supérieure\n\nVous recevrez également :\n\nSac spirituel"},
[2440] = {title = "Les Disques de platine", objective = "Apporter le Bon de récompense à Bena Winterhoof à Thunder Bluff.", description = "Je vais concentrer mes travaux sur ces disques ; ils me révéleront bientôt leur raison d’être.\n\n<nom>, je vais vous récompenser pour la diligence avec laquelle vous m'avez apporté ceci. Portez ce bon à Bena Winterhoof, le maître des Alchimistes de Thunder Bluff. Elle vous offrira un objet spécial que vous apprécierez sûrement et elle vous proposera un choix de breuvages magiques de ma réserve personnelle.\n\nRevenez vite me voir, car je sens qu'il y a du pain sur la planche pour étudier cette trouvaille.", progress = "Bonjour, <classe> ! Vous venez ici pour suivre une formation d'alchimiste ou pour autre chose ?", completion = "Eh bien &lt;nom&gt;, vous avez dû plaire au Sage Truthseeker pour qu'il vous donne cela ! Il vous offre aussi un échantillon de ses potions : vous pouvez choisir entre 5 Potions de guérison supérieures ou 5 Potions de mana supérieures.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPotion de soins excellentePotion de mana supérieure\n\nVous recevrez également :\n\nSac spirituel"},
[2458] = {title = "Sous le couvert de la nuit", objective = "Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule.\n\nUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).\n\nRespecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier.\n\nObjet fourni : \n", description = "La KapitalRisk... Vous avez entendu parler d'eux ?\n\nDepuis un an, nous essayons d'y introduire un de nos agents. Nous avons travaillé dur, mais prudemment, et nous avons réussi.\n\nNous venons d'apprendre que la KapitalRisk projette une opération de grande envergure. Allez au nord de la Videfange, à la tour de la KapitalRisk, et contactez notre agent, le sous-chef Fizzule.\n\nUne fois sur place, utilisez ce lance-fusées, approchez Fizzule et faites-lui le salut de la Main brisée.", progress = nil, completion = "Ça fait plaisir de voir un autre agent de la Main brisée par ici, mais les fusées, c'était peut-être un peu trop !\n\nLa prochaine fois que vous voudrez me parler, soufflez deux fois dans ce sifflet et je saurai que vous faites partie des alliés.", rewards = "Vous recevrez :\n\nSifflet de Fizzule"},
[2459] = {title = "Ferocitas le Mangeur de rêves", objective = "Sur ordre de Tallonkai Swiftroot de Dolanaar, tuer 7 Mystiques Pins-tordus et retrouver le Bijou disparu.", description = "L'émeraude... Elle a disparu ! Mon capturêve a été endommagé !\n\nUne bande de Mystiques Pins-tordus rôde au nord de Brise-stellaire. J'ai entendu dire que leur chef, Ferocitas le Mangeur de rêves, porte un collier qui émet des lueurs vertes pendant la nuit. Vu l'état de mon capturêve, il est certain qu'il a volé mon émeraude... Il ne comprendra jamais que sa puissance lui est inutile.\n\nTrouvez mon bijou disparu, <nom>. Et tant que vous y êtes, profitez-en pour nous débarrasser de quelques Mystiques corrompus.", progress = "Ferocitas et les Mystiques Pins-tordus doivent me rendre ce qui m'appartient. Je vous en prie, retrouvez l'émeraude pour que je puisse réparer mon capturêve d'émeraude.", completion = "Maintenant je peux réparer mon capturêve. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2460] = {title = "Le Salut brisé", objective = "Faire le Salut brisé à Shenthul.", description = "En tant que voleur de la Main brisée, il est impératif que vous appreniez le Salut brisé. C'est la seule façon d'identifier un autre membre de la Main.\n\nRegardez, apprenez, répétez.", progress = "Passez à la pratique !", completion = "Bien joué, &lt;nom&gt;. Vous pouvez maintenant y aller.", rewards = "Vous recevrez :\n\n"},
[2478] = {title = "Mission : possible mais non probable", objective = "Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.\n\nAssassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.", description = "Vous devez voler la clé de la tour au contremaître Silixiz, <nom>. Une fois la clé en votre possession, gardez-la soigneusement, je pourrais en avoir besoin plus tard.\n\nProfitez de l'état d'affaiblissement des habitants empoisonnés, et laissez donc votre tendance au chaos et à la destruction s'exprimer librement. Tuez-les tous ! Ne montrez aucune pitié !\n\nLorsque tous baigneront dans leur sang, ouvrez le coffre de Gallywix et volez la Mixture de Zanzil. Apportez la tête de Gallywix ainsi que la Mixture à Shenthul à Orgrimmar.", progress = "Qu'avez-vous à m'annoncer, <nom> ?", completion = "Pauvre Fizzule ! C'était un bon agent, l'un des meilleurs. Hélas, c'est le prix à payer, &lt;nom&gt; ! Être un agent de la Main brisée est dangereux.\n\nVous avez fait et bien fait votre devoir, &lt;classe&gt;. Cela aurait été dommage que vous ne surviviez pas.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nRecette : Thé de chardon"},
[2479] = {title = "L'aide d'Hinott", objective = "Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.\n\nPour rejoindre Moulin-de-Tarren, prenez le zeppelin à Undercity et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !", description = "Apportez un échantillon du mélange à Serge Hinott à Moulin-de-Tarren.\n\nSi quelqu'un peut vous guérir, c'est bien Serge. Si vous vivez suffisamment longtemps, il vous montrera comment créer un poison et comment l'utiliser.", progress = "Qu'est-ce que c'est que ça ?", completion = "Vous semblez délicieusement pâle, &lt;classe&gt;. Et quel est cet arôme écœurant que vous dégagez ? Je dois le savoir !", rewards = "Vous recevrez :\n\n"},
[2480] = {title = "L'aide d'Hinott", objective = "Attendre Serge Hinott pour achever le remède.", description = "Je n'ai jamais vu d’aussi merveilleux résultats pour un poison ! Zanzil, vous dites ? Jamais entendu parler de lui, mais je m'incline devant le mélange qu'il a créé.\n\nBon, vous voulez que je vous guérisse et que je vous apprenne ensuite à utiliser le poison ?\n\nLaissez-moi un peu de temps pour examiner la toxine, <nom>.", progress = nil, completion = "Le remède est prêt ! Buvez cette antitoxine et cette folie rampante s'arrêtera, mais je ne suis pas capable de faire quoi que ce soit pour l'odeur.", rewards = "Vous allez être la cible du sort suivant :\n\nPoisons\n\nVous recevrez :\n\nHuile d'Hinott"},
[2498] = {title = "Retour vers Denalan", objective = "Sur ordre de Rellian Greenspyre, aller voir Denalan au lac Al'Ameth.", description = "Je viens de recevoir un mot de Denalan au lac Al'Ameth, disant qu'il a peut-être découvert la cause les tumeurs chez les sylvains. Allez le voir et dites-lui que je vous envoie.\n\nFaites vite, <nom>, il a besoin de nous.", progress = nil, completion = "Ainsi, Rellian vous envoie pour m'aider ! Je suis heureux que vous soyez déjà là.\n\nJ'ai découvert quelque chose de tout à fait inquiétant !", rewards = "Vous recevrez :\n\n"},
[2499] = {title = "Froncechêne", objective = "Sur ordre de Denalan du lac Al'Ameth, ôter la Tumeur gargantuesque de Froncechêne.", description = "Dans une caverne le long de la rive sud du lac, un sylvain nommé Froncechêne propage la corruption parmi les créatures qui vivent au lac Al'Ameth.\n\nJe n'ai pas osé m'approcher, mais c’est visible à distance : il est parasité par la plus grande tumeur que j'ai jamais vue... On pourrait même dire gargantuesque.\n\n<nom>, vous m’avez déjà été d'un grand secours, mais je vous demande encore cela : pourchassez-le et débarrassez-le de sa tumeur, éliminez cette source de contamination de chez moi.", progress = "Avez-vous déjà localisé Froncechêne, <race> ?", completion = "Je savais que vous étiez capable de débarrasser le lac de cette horrible chose.\n\nC'est un choix difficile : Froncechêne était autrefois un grand chef parmi les siens... Mais la corruption ne fait pas de distinction entre l’humble et le noble.\n\nLa taille de cette tumeur est tout à fait inquiétante, mais je dois l'étudier pour en apprendre plus sur cette maladie.\n\nMerci, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture de terreboisGantelets couverts de mousse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2500] = {title = "Les réactifs des Terres ingrates", objective = "Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar.", description = "<classe>, vos services vont m’être utiles. Je suis alchimiste et j'ai besoin de votre aide pour trouver certains réactifs dans les Terres ingrates.\n\nJ'ai besoin de ceci pour ma réserve : 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche. Évidemment, vous pouvez trouver les réactifs sur les créatures elles-mêmes. Si vous n'êtes pas du genre battant, trouvez donc des amis qui le soient.\n\nApportez-moi tout ça et je vous récompenserai.\n\nQu'en dites-vous ?", progress = "Avez-vous ce que je vous ai demandé ? Vous ne serez payé que lorsque vous m'aurez rapporté ces ingrédients.", completion = "Ah ! Bien joué, &lt;nom&gt; ! Ça devrait me permettre de tenir un petit moment. Voici votre paye, comme promis.\n\nSi ça vous dit, j'ai également besoin de composants qu'on ne trouve que dans les profondeurs d'Uldaman. Ils ne seront pas facile à obtenir, mais je ferai en sorte que la récompense soit à la hauteur des efforts fournis.\n\nPeut-être autre chose que quelques pièces brillantes, hein ?", rewards = "Vous recevrez :\n\n"},
[2501] = {title = "Les réactifs des Terres ingrates II", objective = "Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Healtouch à Thelsamar.", description = "Vous m'avez été des plus utiles, <nom>. Votre récompense sera la recette de la boisson que vous avez goûtée tout à l'heure... Mais j'ai une tâche très dangereuse pour vous.\n\nCette boîte fermée contient trois Récipients vides ; ils sont imprégnés d'un fluide magique qui drainera le sang d'un dragon gardien des terres brûlées. Je vous préviens : le fait de les utiliser irrite beaucoup les bêtes. Une fois que vous aurez rempli les trois, apportez-les-moi.\n\nEnsuite la recette sera à vous !", progress = "Avez-vous utilisé les récipients thaumaturgiques pour pomper le sang de dragon gardien des terres brûlées dont j'ai besoin ? Oui, je sais que c'est une opération dangereuse... Mais l’élaboration de mon breuvage fortifiant dépend de votre succès. Risque et récompense, mon ami. Risque et récompense...", completion = "Je vous salue, et c'est le salut d'un Alchimiste à un autre Alchimiste. Voilà, prenez connaissance de cette recette. Vous connaîtrez peut-être grâce à elle le succès et les récompenses qu'elle m'a apportés au cours des ans.", rewards = "Vous allez être la cible du sort suivant :\n\nPotion de Restauration\n\nVous recevrez :\n\n"},
[2518] = {title = "Les larmes de la Lune", objective = "Apporter les Filières d'argent de dame Sathrah à la prêtresse A'moora, au temple de la Lune, à Darnassus.", description = "Autrefois, dame Sathrah était aimée d'Elune. Gracieuse et pure, l'araignée tissait ses toiles d'argent au clair de lune pour recueillir la brume du soir. La rosée argentée avait de grands pouvoirs de guérison et on la conservait au temple.\n\nMais récemment, dame Sathrah a plongé dans la folie. Sa descendance à venir est également menacée.\n\nTrouvez dame Sathrah, <nom>, et mettez fin à ses souffrances. Elle demeure le long des frontières, au nord de Teldrassil, près du lac d'Aigue-vive. Prenez ses filières d'argent et apportez-les-moi.", progress = "Je regrette d'avoir dû vous demander d'accomplir cette tâche, mais il n'y a plus d'espoir pour dame Sathrah aujourd'hui.\n\nNotre seul recours est de remettre les Filières en offrande à Elune. A travers ce sacrifice, Elune bénira Sathrah pour qu'elle puisse être réincarnée et retrouver la paix.", completion = "La forêt pleure dame Sathrah, mais cela devait être fait.\n\nMerci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2519] = {title = "Le Temple de la Lune", objective = "Sœur Aquinne veut que vous parliez à la prêtresse A'moora, au temple de la Lune.", description = "Une créature de la forêt, autrefois l'une des plus grandes, a besoin de votre aide, <nom>.\n\nC'est une tâche difficile, mais qui doit être accomplie.\n\nS'il vous plaît, allez voir la prêtresse A'moora, elle vous expliquera de quoi il s'agit. Elle est au sud-est, dans le Temple de la Lune.", progress = nil, completion = "Ainsi, c'est Sœur Aquinne qui vous envoie ?", rewards = "Vous recevrez :\n\n"},
[2520] = {title = "Sacrifice de Sathrah", objective = "Sur ordre de la prêtresse A'moora, placer les Filières d'argent de dame Sathrah dans la fontaine du Temple, puis retourner la voir.", description = "Maintenant vous devez finir la tâche qui vous a été confiée. Prenez les Filières d'argent et offrez le sacrifice de dame Sathrah à Elune. Permettez à la Grande araignée de trouver le repos.\n\nDans le temple, trouvez la fontaine centrale. C'est là que vous déposerez le sacrifice. Les eaux saintes vont nettoyer et purifier la corruption qui a conduit Sathrah à la folie.\n\nQuand vous aurez fini, revenez me voir.", progress = "Avez-vous déposé le sacrifice dans la fontaine, <nom> ?", completion = "La perte de Dame Sathrah est triste, mais c'est seulement ainsi qu'elle pourra être réincarnée avec un esprit régénéré.\n\nPuisse Elune accepter le sacrifice que vous lui avez offert.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChausses lacéesBottes fourrées\n\nVous recevrez également :\n\n"},
[2521] = {title = "Au service de Kum'isha", objective = "Si vous trouvez une sphère de draenéthyste sans défaut au hasard des voyages dans les Terres foudroyées, apportez-la à Kum'isha le Collecteur.\n\nCette gemme, l'une des plus rares de tout Azeroth, peut être détenue par n'importe qui dans le pays.\n\nUne récompense sera donnée pour chaque sphère de draenéthyste sans défaut trouvée et rapportée.", description = "<nom>, votre cerveau étriqué peut-il comprendre la rareté d'une sphère de draenéthyste sans défaut ? Les draeneï ont consacré des vies entières à chercher un seul de ces cristaux et ils n'ont rencontré que des destins horribles.\n\nEt vous voilà devant Kum'isha, sachant ce qu'il veut et souhaitant toujours l'aider ? Très bien, <nom>... Si en parcourant ces terres, vous trouvez une sphère de draenéthyste sans défaut, apportez-la-moi et je vous récompenserai au-delà de vos rêves les plus fous.", progress = "J'ai consacré ma vie à la recherche de sphères de draenéthyste sans défaut. Le travail de toute une vie, <nom> !", completion = "Mes yeux me trompent-ils ? Impossible ! Où avez-vous ?... Comment ?...\n\nMaintenant, peut-être qu’une faille va pouvoir s’ouvrir afin que nous retournions chez nous.", rewards = "Vous recevrez :\n\nCoffre incrusté d'émeraudes"},
[2522] = {title = "Les efforts de Kum'isha", objective = "Trouver une Sphère de draenéthyste sans défaut et l'apporter à Kum'isha le Collecteur", description = "Bien que l'invocation de portail ait échoué, j'ai bon espoir que la prochaine tentative sera la bonne.\n\nL'espoir des draeneï est aussi fort que votre soif de bibelots, <nom>. Retournez dans ces terres maudites et trouvez une autre sphère de draenéthyste sans défaut.\n\nBien sûr, vous êtes libre d'accepter ou non cette tâche *grand sourire*.", progress = "Avez-vous trouvé une autre sphère de draenéthyste sans défaut ?", completion = "Tout simplement stupéfiant ! Je doutais que vous puissiez trouver une autre sphère, et pourtant elle est là et elle bat dans ma main.\n\nBien joué, &lt;nom&gt; !\n\nSi vous en trouvez une autre – et je crois que c'est presque impossible – rapportez-la-moi et je vous récompenserai de nouveau.", rewards = "Vous recevrez :\n\nCoffre incrusté d'émeraudes"},
[2523] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[2541] = {title = "Le druide dormant", objective = "Rapporter un Charme vaudou de chaman à Oben Grifferage dans le Refuge des saisons de Ban'ethil.", description = "Les chamans Pins-tordus qui habitent cet endroit ont découvert comment séparer l'esprit d'un druide dormant de son corps physique. Les furbolgs ont ranimé ma forme physique et l'utilisent pour attaquer ceux qui essaient d'explorer le Refuge des saisons de Ban'ethil. Je suis impuissant, pris au piège dans le Rêve d'émeraude.\n\nVous devez m'aider. Les chamans Pins-tordus portent un charme étrange qu'ils utilisent pour exécuter ce rituel et je voudrais l'examiner. Je vous en prie, <nom>, il m’en faut un.", progress = "Si je peux examiner le charme, je pourrais peut-être comprendre comment briser l'enchantement. En avez-vous trouvé un ?", completion = "Merci, &lt;nom&gt;.\n\nQuel drôle d'objet... Je peux sentir la vile aura qui en émane. C'est un enchantement très puissant.", rewards = "Vous recevrez :\n\n"},
[2561] = {title = "Le druide de la Griffe", objective = "Sur ordre d'Oben Grifferage, tuer son Corps privé d'âme et utiliser ensuite le Charme vaudou.", description = "J'ai examiné ce charme, <nom>, et je vois maintenant ce qu'il faut faire. Prenez-le et suivez mes instructions.\n\nVous devez explorer les zones les plus reculées du Refuge des saisons de Ban'ethil pour trouver mon corps sans âme... Je regrette de devoir en arriver à cette extrémité, mais je ne vois pas d'autre moyen de me libérer du contrôle des Pins-tordus.\n\nVous devez tuer ma forme physique. Ensuite, utilisez le Charme vaudou sur mon corps. Lorsque vous aurez accompli cette tâche,revenez me voir.", progress = "<nom>, faites preuve de prudence en vous approchant de ma forme physique : l'enchantement qui la contrôle est très puissant.", completion = "Je suis enfin libéré du contrôle des Pins-tordus. Merci, &lt;nom&gt;.\n\nMon esprit peut maintenant reposer paisiblement et pour toujours dans le Rêve d'émeraude.\n\nUn jour peut-être, nous nous reverrons, jeune &lt;classe&gt;. Mais pour le moment, acceptez cette récompense en signe de ma gratitude.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe du dormeurLame des broussailles\n\nVous recevrez également :\n\n"},
[2581] = {title = "Joues de Raillecroc", objective = "Apporter 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial.", description = "Tout le monde sait que la mâchoire des hyènes possède une force énorme, mais jusqu’à quel point ? Au point de mordre dans trois pouces d'acier au thorium ? Impossible ! Improbable ! Et pourtant je l'ai vu de mes propres yeux.\n\nAllez dans les Terres foudroyées et apportez-moi trois joues de Raillecroc. En cherchant les Raillecroc, trouvez aussi les sangliers et les scorpoks : la préparation initiale exige deux Poumons de sanglier éclatés et une Pince de scorpok.", progress = "Vous sentez mauvais, <nom>. Avez-vous traîné dans les champs de soufre ? Et où sont mes ingrédients ?", completion = "Comment allez-vous, &lt;nom&gt; ? Vous irradiez la force comme une Raillecroc – une force inégalée parmi les mortels !\n\nMalheureusement, avec ce que vous m'avez apporté, j'ai juste de quoi faire une tablette. Si vous en voulez plus, j'ai besoin de davantage de matière.", rewards = "Vous allez être la cible du sort suivant :\n\nLa colère des âges\n\nVous recevrez :\n\nR.O.I.D.S."},
[2582] = {title = "La colère des âges", objective = "Apporter 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial.", description = "Oh <nom> ! Bienvenue. On dirait que vous avez apprécié l'effet de ce mélange tiré des Raillecroc. Prenez garde, si l'effet immédiat est un fantastique regain de force, à long terme les effets pourraient être dangereux pour votre esprit et votre intelligence.\n\nSachant cela, en voulez-vous encore ? Dans ce cas, apportez-moi trois autres joues de Raillecroc, deux poumons de sanglier éclatés et une pince de scorpok.", progress = "Avez-vous les organes de ces bêtes ?", completion = "Voilà pour vous ! Rappelez-vous : à utiliser avec modération. Si vous en voulez encore, revenez me voir après avoir fini celui-ci.", rewards = "Vous recevrez :\n\nR.O.I.D.S."},
[2583] = {title = "La vitalité du sanglier", objective = "Apporter 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial.", description = "Sur ces terres désolées vivent deux espèces de sanglier : le sanglier cendré et le sanglier infernal.\n\nL'endurance de ces bêtes les rend presque invulnérables, et même les autres prédateurs les évitent.\n\nNous devons faire de nouvelles analyses, <nom>. Si vous m'apportez trois Poumons de sanglier éclatés, deux Pinces de scorpok et un Cerveau de basilic, je créerai un élixir divin. Vous serez mon premier cobaye !", progress = "Où sont les organes, <nom> ?", completion = "L'esprit du Sanglier vous illumine, &lt;nom&gt; ! Je me demande si vous vous sentez aussi invulnérable que ces bêtes ?", rewards = "Vous allez être la cible du sort suivant :\n\nEsprit du sanglier\n\nVous recevrez :\n\nCocktail de jus de poumon"},
[2584] = {title = "L'esprit du sanglier", objective = "Apporter 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial.", description = "Quand je vous ai administré l'élixir, <nom>, je savais qu'une ou deux applications ne rassasieraient pas votre appétit. Et maintenant, je peux voir la faim dans vos yeux. Le mélange provoque une dépendance, à laquelle même les plus forts ne résistent pas.\n\nQu'il en soit ainsi ! Si vous voulez plus de Jus de poumon, retournez dans le désert et trouvez-moi trois poumons de sanglier éclatés, deux pinces de scorpok et un cerveau de basilic.", progress = "Où sont les organes, <nom> ?", completion = "Je dois vous avertir, &lt;nom&gt;, il ne sert à rien de mélanger entre elles les formules que j'ai créées. Les propriétés de la dernière formule que vous avalerez auront toujours priorité sur les enchantements plus anciens, ce qui aura pour effet de les annuler.", rewards = "Vous recevrez :\n\nCocktail de jus de poumon"},
[2585] = {title = "Le coup décisif", objective = "Apporter 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial.", description = "Avez-vous observé les scorpoks au combat, <nom> ? Avez-vous vu la grâce et l'agilité avec lesquelles ils se déplacent ?\n\nSi seulement nous pouvions isoler cette agilité et l'encapsuler, nous serions riches au-delà de... je veux dire... ce serait bien pour la communauté scientifique.\n\nAidez-moi, <nom> et je vous permettrai d'essayer le résultat.\n\nPour faire un échantillon stable, j'ai besoin de trois Pinces de scorpok, de deux Gésiers de vautour et d'un Poumon de sanglier éclaté.", progress = "Où sont les organes, <nom> ?", completion = "Fascinant. Cette préparation a été la plus difficile à élaborer.\n\nPrenez une pincée de ce sel résiduel et placez-la sous votre langue. Vous devriez éprouver un léger sentiment d'euphorie suivi d'un accroissement d'agilité et de rapidité sans précédent.", rewards = "Vous allez être la cible du sort suivant :\n\nFrappe du scorpok\n\nVous recevrez :\n\nPoudre de scorpok terrestre"},
[2586] = {title = "Le sel de scorpok", objective = "Apporter 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial.", description = "Vous êtes en vie ! C'est une bonne nouvelle, vraiment. Je suppose que vous revenez pour avoir plus de préparation de scorpok ?\n\nTrès bien, <nom>, retournez dans le désert et ne revenez pas avant d'avoir prélevé trois pinces de scorpok, deux gésiers de vautour et un poumon de sanglier éclaté.", progress = "Où sont les organes, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Voici un échantillon de la préparation pour vous ; j'utiliserai le reste pour mes recherches.\n\nChaque fois que vous voudrez plus de préparation de scorpok, revenez me voir et nous conclurons un accord.", rewards = "Vous recevrez :\n\nPoudre de scorpok terrestre"},
[2601] = {title = "La morsure du basilic", objective = "Apporter 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore.", description = "Ces terres désolées sont envahies par les basilics Rougepierre, <nom>. Ils se sont adaptés et multipliés plus que n'importe quelle autre espèce.\n\nJ'ai observé leur technique de chasse et leur comportement : leur processus de pensée est plus complexe que celui de certains humanoïdes.\n\nJe veux étudier leur intelligence !\n\nRapportez-moi dix cerveaux, <nom>. Cependant, le composé ne sera pas complet sans deux gésiers de vautour pour former la base de la solution.", progress = "Est-ce que vous revenez avec les organes demandés ?", completion = "C'est merveilleux, &lt;nom&gt; ! Je vous offre un aperçu de mes travaux sur les basilics Rougepierre.\n\nJ'espère que la préparation va vous plaire. Il est toujours possible d'en faire davantage… en payant le prix.", rewards = "Vous allez être la cible du sort suivant :\n\nUn esprit infaillible\n\nVous recevrez :\n\nPotion de cortex cérébral"},
[2602] = {title = "Un esprit infaillible", objective = "Apporter 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore.", description = "Votre concentration est déjà retombée ? Il faut faire d'autres recherches !\n\nOh oui ! Le prix est le même, <nom>. Retournez dans les Terres foudroyées et revenez me voir avec dix cerveaux de basilic Rougepierre et deux gésiers de vautour.", progress = "Est-ce que vous revenez avec les organes demandés ?", completion = "Oui, oui, donnez-moi un moment et j'aurai davantage de produit à vous proposer, &lt;nom&gt;.\n\nPrenez cela... Et, &lt;nom&gt;, ne tentez pas d’ingurgiter ces mélanges expérimentaux les uns derrière les autres. Les résultats pourraient être désastreux.", rewards = "Vous recevrez :\n\nPotion de cortex cérébral"},
[2603] = {title = "La vigueur du vautour", objective = "Apporter 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore.", description = "La mort a réellement des ailes dans les Terres foudroyées, <race>. J'ai vu les Pourfendeurs noirs et les Racleur-d'os festoyer sur de nombreux cadavres d'explorateurs et déchiqueter même les carcasses les plus atteintes par la maladie. Je me demande comment leur système neutralise la peste qui sévit sur ces terres.\n\nAidez-moi dans mes études, <nom> ! J'ai besoin de gésiers ! Egalement de deux joues de Raillecroc pour la base du mélange.\n\nLa récompense de vos efforts sera double.", progress = "Ne me faites pas perdre mon temps, <nom>. Nous n'avons rien à nous dire, à moins que vous n'ayez récupéré ce que je vous ai demandé.", completion = "Magnifique ! Je me mets tout de suite au travail. Peut-être que je vais trouver un remède pour soulager les maux du monde !\n\nAh oui ! Votre récompense. Si vous voulez plus de gomme, revenez me voir et je vous donnerai une autre tâche.", rewards = "Vous allez être la cible du sort suivant :\n\nDomination spirituelle\n\nVous recevrez :\n\nGomme de gésier"},
[2604] = {title = "Domination spirituelle", objective = "Apporter 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore.", description = "Je vois que votre feu intérieur a diminué. Cela voudrait-il dire que l'euphorie n'a duré qu'une heure ?\n\nSi vous voulez plus de Gomme de gésier, alors j'ai besoin de plus de gésiers. Retournez dans le désert, <nom>. Et ne revenez pas avant d'avoir récupéré dix gésiers et deux joues.", progress = "Ne me faites pas perdre mon temps, <nom>. Nous n'avons rien à nous dire, à moins que vous n'ayez récupéré ce que je vous ai demandé.", completion = "J'arriverai peut-être un jour à isoler les enzymes actives de cette préparation, et ainsi renforcer son efficacité. Malheureusement, vous devez vous contenter de ce que je suis capable de produire aujourd'hui. Revenez me voir si vous voulez plus de Gomme de gésier.", rewards = "Vous recevrez :\n\nGomme de gésier"},
[2605] = {title = "Le gobelin assoiffé", objective = "Trouver une Glande de rosée remplie et l'apporter à Marin Noggenfogger à Gadgetzan.", description = "J'ai une idée… J'ai entendu parler de créatures étranges appelées collecteurs de rosée, vivant au sud-ouest... Elles sont capables de stocker de l'eau dans des glandes spéciales.\n\nJe pense que si je pouvais me procurer l'une de ces glandes, je pourrais mettre au point une boisson qui étancherait ma terrible soif ! Pensez-vous que vous pourriez m'aider, <nom> ?\n\nAllez au jardin des cactus, <nom>, c'est là que vous trouverez les collecteurs de rosée.", progress = "Par pitié, dites-moi que vous avez trouvé les collecteurs de rosée !", completion = "Oh, magnifique ! Posez ça ici et laissez-moi boire !", rewards = "Vous recevrez :\n\n"},
[2606] = {title = "De bon goût", objective = "Sur ordre de Marin Noggenfogger, aller voir Sprinkle à Gadgetzan.", description = "Beurk ! Cette substance a un goût épouvantable ! Trop pour mon idée... \n\nAttendez, qu'est-ce que c'est que ça ? Oh, je sais ! Vous pensez que je dois continuer de croire en cette substance. Bon alors...\n\nJ'ai une idée brillante ! Apportez cette rosée à mon amie Sprinkle, c'est un excellent chef. Dites-lui où nous en sommes et ce que nous voulons faire.\n\nJe veux dire, si c'est aussi mauvais, il y a sûrement quelque chose à en faire... C'est juste que moi, je ne le sens pas...", progress = "Ainsi le vieux Marin s'y remet, hein ? De quoi ce mélange est-il fait ?", completion = "Marin est un bon gars, je ne peux pas dire le contraire. Juste un peu... excentrique.\n\nEt bien sûr, il a besoin de mon aide, encore une fois.", rewards = "Vous recevrez :\n\n"},
[2607] = {title = "Le toucher de Zanzil", objective = "Aller voir le docteur Mixilpixil dans la Cave de la caserne.", description = "On dirait que vous avez rapporté plus d'informations que je n'en attendais. Les événements prennent une tournure étrange, <nom>.\n\nUn remède ? Hum... Rendez-vous à la Cave et allez voir le docteur Mixilpixil, il pourra peut-être vous aider.", progress = nil, completion = "Il est grand temps ! Mettez simplement le fromage sur la table et barrez-vous. Osborne vous payera en sortant.", rewards = nil},
[2608] = {title = "Le toucher de Zanzil", objective = "S'allonger (/coucher) pour être <examiné/examinée> par le docteur Mixilpixil. Comment peut-il trouver le remède s'il ne peut pas trouver la cause ?", description = "Oh Ciel ! Vous ressemblez à la mort. Je corrige : j'ai vu la mort, vous semblez en pire état. Vous ressemblez à ce que serait la mort à son dernier instant.\n\nAh ! Vous entendez ce Noarm ? Notez-le !\n\n*soupir* Hum ! Oui, pour vous aider, je dois prendre un peu de votre sang. Ne vous inquiétez pas, ça ne fait mal que les… cinquante premières fois. Allongez-vous (/coucher) quand vous serez <prêt/prête> pour le traitement, <nom>.", progress = nil, completion = "Donnez-moi un moment pour discuter avec mes confrères, &lt;nom&gt;. Docteur Montgomery, M. Noarm, réunissons-nous !", rewards = "Vous recevrez :\n\n"},
[2609] = {title = "Le toucher de Zanzil", objective = "Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul.", description = "Le diagnostic est unanime, <nom>. Vous êtes <atteint/atteinte> de “itis”. \n\nHeureusement, j'ai un remède.\n\nVoilà ce dont j'ai besoin : une brassée de fleurs sauvages simples, une fiole plombée, un tube en bronze et une bobine de fil de soie chartreuse. La vieille Emma en a laissé pour moi au \"Fil le plus fin”. Le magasin se trouve le long des canaux.\n\nDépêchez-vous <nom>, et ne touchez personne jusqu'à votre guérison. Oh ! Montgomery dit que vous devriez prendre une douche – c'est lui qui le dit, pas moi.", progress = "Si vous voulez guérir de votre itis, vous allez devoir essayer avec plus d'ardeur, <nom>. Où sont les réactifs pour le remède ?", completion = "Ce que je fais ? Qu'est-ce que j'ai l'air de faire ? Je mets au point un remède pour soigner votre itis ! Ne jouez pas les indignés avec moi maintenant, &lt;nom&gt; !\n\nPlus que quelques secondes. Là ! Pulvérisez juste un peu de ce médicament fantastique sur vous et vous retrouverez la pêche.", rewards = "Vous recevrez :\n\nEau de Mixilpixil"},
[2621] = {title = "Le déshonoré", objective = "Aller voir le commandant d'ordonnance Ruag dans Stonard.", description = "Désolé. C'est tout ce que j'ai pour l'instant. Une mauvaise décision aux conséquences horribles. Si seulement j'avais attendu ces ordres. Peut-être détaillaient-ils les horreurs qui nous attendaient ! Peut-être devaient-ils nous guider autrement ? En fin de compte, c'est ma faute. Tout cela est ma faute.\n\nJe suis là et j'attends les ordres. Je dois savoir. Je dois avoir ces ordres.\n\nLe commandant d'ordonnance Ruag réside à Stonard. Trouvez-le et découvrez ce qui est arrivé aux ordres.", progress = nil, completion = "Les prétoriens de Thrall... Cette histoire est toujours fraîche dans mon esprit.\n\n&lt; Le commandant Ruag secoue la tête &gt;\n\nC'est terrible, ce qui est arrivé à ce régiment. La Horde a perdu certains de ses meilleurs soldats lors de la destruction de ce bataillon.", rewards = "Vous recevrez :\n\n"},
[2622] = {title = "Les ordres disparus", objective = "Aller voir Bengor.", description = "Les ordres ? Que voulez-vous faire avec ?\n\nPourquoi vous impliquez-vous, <nom> ? Bien sûr que j'ai relayé ces ordres ! Les soldats auxquels j'ai envoyé ces ordres ont été pris en embuscade par les murlocs. Un seul s'en est sorti, si on peut dire. Il peut à peine parler, ne peut pas marcher et on l'alimente par un tube. Si vous voulez savoir où sont ces ordres, allez voir Bengor. Il est quelque part par là... et, <nom>, méfiez-vous des endroits où vous fourrez votre nez : il pourrait bien être mordu.", progress = nil, completion = "Pa… Parleur des ma… marécages...", rewards = "Vous recevrez :\n\n"},
[2623] = {title = "Le Parleur des marécages", objective = "Retrouver les Ordres du Chef de guerre et les rendre au Héros déchu de la Horde.", description = "Le commandant d'ordonnance a donné des ordres. Nous avons pris... pris des ordres. Sur le chemin des Terres foudroyées, pris en embuscade.\n\nLes murlocs... Beaucoup de murlocs... Un qui s'appelle le Parleur des marécages. À pris les ordres de mes mains avant de me frapper le crâne avec sa lance. À l'est... la caverne...\n\n<Bengor trépasse.>", progress = "J'attends les ordres.", completion = "C'est pire que ce que j'imaginais. On aurait pu épargner cette fin tragique à dix-neuf de mes hommes. Si seulement je n'avais pas réagi de façon aussi irrationnelle.\n\nVous devez les aider, &lt;nom&gt; ! Moi, je suis impuissant…", rewards = "Vous recevrez :\n\n"},
[2641] = {title = "L'ingrédient secret de Sprinkle", objective = "Collecter un Tragan violet et l'apporter à Sprinkle, à Gadgetzan.", description = "Quand j'étais gosse, ma sœur faisait à manger. C'était horrible ! Mon estomac ne supportait pas sa cuisine, jusqu'à ce que je trouve ce que j'aime à appeler mon ingrédient \"secret\" ! Ajoutez-le à n'importe quoi et... ouah ! le goût devient génial !\n\nDe quoi je parle ? D'un champignon, le tragan violet. Si vous voulez que je vous aide à rendre buvable ce breuvage écœurant, allez aux Hinterlands et cherchez un petit lac.\n\nLe tragan violet ne vit que sous l'eau.", progress = "Sous les eaux de ce lac, c'est là et nulle part ailleurs que vit le tragan violet. J'espère que vous avez du souffle !", completion = "Voilà la substance, &lt;nom&gt; !\n\nÇa semble si bon, je pourrais juste... Ha ha !", rewards = "Vous recevrez :\n\n"},
[2661] = {title = "Livraison pour Marin", objective = "Sur ordre de Sprinkle, apporter la Poudre violette à Marin Noggenfogger à Gadgetzan.", description = "Voilà la Poudre violette, <nom>. Portez-la à Marin et dites-lui qu'il me doit une faveur !", progress = "Oh, <nom> ! Vous voilà enfin de retour. Qu'avez-vous apporté ?", completion = "De la Poudre violette, hein ? Faisons un essai. De toute façon, ça ne pourra pas le rendre plus mauvais !", rewards = "Vous recevrez :\n\n"},
[2662] = {title = "Elixir Noggenfogger", objective = "Retourner voir Marin Noggenfogger une fois qu'il aura créé son élixir.", description = "Maintenant, il faut mélanger cette poudre avec la rosée.\n\nPartez et revenez me voir un peu plus tard... Quand j'aurai perfectionné le fabuleux Élixir Noggenfogger !", progress = nil, completion = "Buvez cela ! C'est absolument merveilleux !\n\nJe savais que j’y arriverais... Oh ! Merci beaucoup pour votre aide, &lt;nom&gt;, mais s'il vous plaît, poussez-vous un peu, voulez-vous ? Et laissez-moi travailler ! Je vais gagner des millions avec ce fabuleux Élixir Noggenfogger, des millions !\n\nQuoi ? Sprinkle dit que je lui dois une faveur ? Oh, Sprinkle, quelle farceuse, celle-là !", rewards = "Vous recevrez :\n\nElixir Noggenfogger"},
[2681] = {title = "Les pierres qui nous lient", objective = "Libérer 9 Serviteurs de Razelikh, 3 Serviteurs de Sevine, 3 Serviteurs d'Allistarj et 3 Serviteurs de Grol. Retourner voir le Héros déchu une fois la tâche terminée. Il faut rester à proximité des pierres ou le processus échouera.", description = "Vous ne pourrez pas à vous <seul/seule> affronter les forces de Razelikh et de ses subordonnés.\n\nRassemblez un groupe d'aventuriers pour libérer mes hommes de leur torture éternelle ! Vous devez briser dix-huit pierres.\n\nBattez-vous durement et mourez avec honneur, <nom>.", progress = "Ce n'est pas une tâche facile, <nom>. Ne renoncez pas !", completion = "Vous avez réussi, &lt;nom&gt; ! Leurs pauvres âmes torturées peuvent enfin reposer en paix.\n\nNotre travail n'est pas encore fini, &lt;nom&gt;. Nous avons beaucoup à dire et encore plus à accomplir.", rewards = "Vous recevrez :\n\n"},
[2701] = {title = "Les héros des Anciens", objective = "Ouvrir le coffre et prendre la récompense.", description = "Je vous en prie, prenez cette Relique des Anciens. Nous n'en avons plus besoin.\n\nPuisse-t-elle bien vous servir dans votre combat contre la Légion.", progress = nil, completion = "La lueur et les miroitements vous aveuglent temporairement.", rewards = "Vous recevrez :\n\nÉclat des Sabots-Fendus"},
[2702] = {title = "Les héros des Anciens", objective = "Aller voir le caporal Thund Splithoof.", description = "Votre noblesse et votre héroïsme m'ont honoré, <nom>.\n\nVous les avez honorés aussi…", progress = nil, completion = "En vérité, vous nous avez tous honorés. Nos remerciements ne sont pas suffisants.", rewards = "Vous recevrez :\n\n"},
[2721] = {title = "Kirith", objective = "Découvrir ce qui est arrivé au Lieutenant Kirith.", description = "Un chapitre de vos aventures se termine, un autre commence, <nom>.\n\nL'un de mes hommes manque toujours à l'appel, il est perdu quelque part dans ces terres. Je parle du lieutenant Kirith, bien sûr.\n\nComme je l'ai déjà dit, nous avons été tous deux capturés et torturés par Allistarj mais, pauvre Kirith, sa force a vacillé. Depuis ma cage, je pouvais entendre ce qu’il subissait, ses cris résonnaient dans toute la caverne. Je ne l’ai plus vu depuis.", progress = nil, completion = "Trebor ? C'est Trebor qui vous envoie ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2741] = {title = "Le Super-Oeuf-O-Matic", objective = "Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C'est une machinerie très impressionnante.\n\nLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.", description = nil, progress = "Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C'est une machinerie très impressionnante.\n\nLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.", completion = "Vous placez l'œuf d'hippogryphe dans la machine. Des signaux sonores s'enchaînent, sur un fond de bruits mécaniques.\n\nEt le Calibre-œuf a pesé, mesuré et empaqueté votre œuf. Ça c'est du service rapide !", rewards = "Vous recevrez :\n\nCaisse d'oeufs"},
[2742] = {title = "Rin'ji est pris au piège !", objective = "Escorter Rin'ji hors du Gîte de Quel'Danil, puis découvrir son secret caché sur les Hauts-Surplombs, à l’est.", description = "Hé <race> !\n\nS'il plaît à vous, aidez Rin'ji à s'évader. Moi sais que <race> pas aimer race de Rin'ji, mais Rin'ji demande pitié ! Rin'ji doit sortir ici !\n\nCadeau agréable pour <race> si <il/elle> aider Rin'ji à sortir...\n\nRin'ji cache quelque chose de secret sur les Hauts-Surplombs.", progress = nil, completion = "Cette tablette troll doit être \"le secret\" dont parlait Rin'ji.\n\nElle est couverte d'inscriptions étranges que vous ne pouvez pas déchiffrer.", rewards = "Vous recevrez :\n\n"},
[2743] = {title = "Le couvert de l'obscurité", objective = "Retourner voir le Héros déchu de la Horde avec ces découvertes.", description = "Faisons vite, <nom>, mon temps ici est compté.\n\nIl faut détruire la triade de pouvoir qui protège le seigneur-démon Razelikh. Ce ne sera pas aussi facile que de libérer une âme damnée.\n\n<Kirith sourit.>\n\nVous voyez, chacun des trois subalternes de Razelikh porte autour du cou le tiers d'une amulette créée par Razelikh. L'amulette dont vous aurez besoin pour appeler le démon.\n\nRetournez voir Trebor et dites-lui comment appeler Razelikh. Il pourra vous aider à aller plus loin.", progress = nil, completion = "Le Seigneur démon est presque aussi rusé qu'il est brutal, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2744] = {title = "Le chasseur de démons", objective = "Aller voir Loramus Thalipedes à Azshara.", description = "La triade est protégée par Razelikh.\n\nEn échange de leur servitude, Razelikh a accordé à chacun d'eux un pouvoir presque illimité dans les Terres foudroyées, ainsi qu'une amulette leur conférant l'immortalité. Tant qu'ils restent dans leurs terres, ils ne peuvent pas être tués.\n\nQuelqu'un peut vous aider à poursuivre, <nom>. Allez à Azshara et trouvez le chasseur de démons, Loramus Thalipedes. Cherchez-le dans les îles.", progress = "Que faites-vous là ?", completion = "Je vous aiderai. Cependant, je ne pense pas que vous compreniez vraiment ce que vous affrontez.", rewards = "Vous recevrez :\n\n"},
[2745] = {title = "En infiltrant le Château", objective = "Aller voir Tyrion au Château de Stormwind.", description = "Hum ! Une histoire intéressante à ne pas prendre à la légère. Ouais, je peux vous aider, mais ce que vous devez faire n'est pas vraiment une justice... légale, si vous allez jusqu'au bout.\n\nOn doit d’abord s'occuper de Lescovar et de Marzon, et vite. Pensez-vous en être capable ?\n\nA vous de décider. Si oui, rendez-vous rapidement au château pour y rencontrer un vieil ami à moi, un gnome nommé Tyrion. Il observe Lescovar depuis maintenant quelques semaines. Il devrait pouvoir vous aider à en finir.", progress = nil, completion = "Qu'est-ce que... ? Ne vous faufilez pas près de moi comme ça ! Et parlez moins fort ! Au nom de l'Ombre, qu'est-ce que vous me voulez ? Vous ne voyez pas que je suis occupé, imbécile ?\n\nComment ça, qu'est-ce que je fais là ? J'attends la prochaine ouverture de la Porte des ténèbres, que diable pensez-vous que je fais ? Parlez et dégagez... avant que les gardes ne remarquent que nous sommes là, planques dans les buissons. J'ai une réputation à tenir.", rewards = "Vous recevrez :\n\n"},
[2746] = {title = "Des objets d’une certaine importance", objective = "Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Stormwind.", description = "Trias veut accélérer les choses, hein ? Bien, nous pouvons le faire, mais je ne suis pas prêt. Je vais faire la partie difficile du boulot, mais c'est vous qui allez vous salir les mains, d’accord ? Bon.\n\nIl faut que vous m'obteniez certaines choses pour mettre mon plan à exécution. J'ai le déguisement parfait pour que l'Espion passe ces gardes.\n\nApportez-moi de la soie et deux pommes. Pour la soie, débrouillez-vous, mais vous trouverez des pommes parfaites à la petite ferme de Clara à l'extérieur de la ville.", progress = "J'observe Lescovar depuis plusieurs semaines maintenant. Trias n'a jamais eu confiance en lui, mais nous ne le soupçonnions pas d'être impliqué avec la Confrérie Défias. Nous le pensions plutôt lié au Marteau du crépuscule. Quoi qu'il en soit, il est devenu trop dangereux pour cette ville et il faut en finir.\n\nApportez-moi ces objets et nous pourrons mettre mon plan à exécution.", completion = "Ça fera l'affaire, &lt;nom&gt;. Bon boulot.\n\nLe reste du mécanisme dont j'ai besoin est dans mon sac... Que la Lumière soit remerciée, j'ai justement fait réaliser par un tailleur de mes amis ce sac en soie. Je n'arrivais plus à trimbaler toutes mes affaires.\n\nAvant que l'Espion n'y aille, revoyons en détail ce que vous avez à faire.", rewards = "Vous recevrez :\n\n"},
[2747] = {title = "Un œuf extraordinaire", objective = "J'ai rarement vu des œufs récupérés en Feralas dans un état satisfaisant. Ces œufs comptent parmi les plus rares…", description = nil, progress = "J'ai rarement vu des œufs récupérés en Feralas dans un état satisfaisant. Ces œufs comptent parmi les plus rares…", completion = "Eh bien maintenant, vous avez un… Stupéfiant !\n\nJ'espère que vous vous souviendrez toute votre vie du bien que vous avez fait aujourd'hui.", rewards = "Vous recevrez :\n\nBoîte de fournitures"},
[2748] = {title = "Un œuf de premier choix", objective = "Un œuf de premier choix est un œuf qui, dans des conditions idéales, va éclore libre des effets néfastes des incantations des ogres Gordunni.", description = nil, progress = "Un œuf de premier choix est un œuf qui, dans des conditions idéales, va éclore libre des effets néfastes des incantations des ogres Gordunni.", completion = "Excellent, &lt;nom&gt;. J'enverrai cet œuf à Darnassus où j'espère qu'il va bientôt éclore !\n\nAcceptez ceci en signe de ma gratitude.", rewards = "Vous recevrez :\n\nBoîte de sorts"},
[2749] = {title = "Un œuf ordinaire", objective = "Les œufs ordinaires d'hippogryphes éclosent une fois sur deux. Nous faisons de notre mieux pour les élever et avec une petite chance, ils écloront.", description = nil, progress = "Les œufs ordinaires d'hippogryphes éclosent une fois sur deux. Nous faisons de notre mieux pour les élever et avec une petite chance, ils écloront.", completion = "Donc vous avez trouvé un œuf ordinaire, &lt;nom&gt; ? Donnez-le-moi s'il vous plaît... Nous allons espérer le meilleur pour lui.\n\nJe n'ai pas grand-chose, mais veuillez accepter cette récompense. Si vous retournez en Feralas, sachez que je serai toujours là pour recueillir les œufs que vous trouverez.", rewards = "Vous recevrez :\n\nBoîte de rations"},
[2750] = {title = "Un mauvais œuf", objective = "Ces œufs-là ne peuvent pas être sauvés : ils n'écloront jamais.", description = nil, progress = "Ces œufs-là ne peuvent pas être sauvés : ils n'écloront jamais.", completion = "J'ai peur d'avoir de mauvaises nouvelles, &lt;nom&gt;. Cet œuf est à un stade trop avancé. Je peux le prendre pour nous en débarrasser proprement.\n\nMais ne vous découragez pas, nous ne pouvons pas tous les sauver. Si vous retournez en Feralas, retentez votre chance. Apportez un autre œuf pour le Super-Oeuf-O-Matic !", rewards = "Vous recevrez :\n\n"},
[2751] = {title = "Remparts barbares", objective = "Apporter 2 Brassards guillochés en bronze, 2 Glaives en bronze et 2 Griffes aiguisées à Orokk Omosh à Orgrimmar.", description = "Vingt générations d'Omosh ont tenu ce marteau, <nom>. Nous avons façonné cent mille tonnes de métal. Tragiquement, tout prend fin avec Orokk, l'échec des Omosh : sans famille et sans héritier.\n\nJe ne peux pas laisser les savoir-faire secrets des Omosh mourir avec moi ! Quelqu'un doit recueillir cet héritage, qu’il soit ou non un Omosh !\n\nProuvez à Orokk que vous êtes celui-là, <nom>. Apportez deux brassards guillochés en bronze, deux glaives en bronze et deux griffes aiguisées. Apportez-les à Orokk et nous pourrons continuer.", progress = "Du bronze, <nom> ! Plus de bronze !", completion = "La lignée s’achève, mais la légende des Omosh va survivre !\n\nVous avez prouvé que vous avez l’âme d’un Forgeron, &lt;nom&gt;. La récompense du Forgeron, c'est la satisfaction de voir ses armes et ses armures couvertes du sang de l’ennemi !\n\nPuissent les plastrons que vous forgerez pour les générations futures ruisseler du sang de vos ennemis !", rewards = "Vous recevrez :\n\nPlans : Cuirasse barbare en fer"},
[2752] = {title = "Épaulettes en fer", objective = "Apporter 4 Haches de guerre en bronze et 4 Marteaux de guerre en bronze à Orokk Omosh à Orgrimmar.", description = "Orokk voit l'ardeur dans vos yeux, <nom>. Comme une éponge, vous absorbez la sagesse des leçons des Omosh.\n\nTrois leçons encore !\n\nRetournez à l'enclume, absorbez-vous dans la chaleur de la forge, créez pour Orokk quatre marteaux de guerre en bronze et quatre haches de guerre en bronze. Ensuite seulement vous apprendrez le secret des Epaulettes en fer.", progress = "Montrez-moi votre dévouement, <nom>.", completion = "Vous faites la fierté d'Orokk, &lt;nom&gt;. Lisez, apprenez le secret des Épaulières en fer !", rewards = "Vous recevrez :\n\nPlans : Epaulières barbares en fer"},
[2753] = {title = "Piétinés", objective = "Apporter 4 Heaumes en fer émeraude, 4 Bracelets en fer émeraude et 2 Jambières en fer émeraude à Orokk Omosh à Orgrimmar.", description = "Deux leçons encore vous enseignera Orokk, <nom>. Vos muscles font mal, je sais, mais continuez pour les Omosh !\n\nApportez à Orokk quatre heaumes en fer émeraude, quatre bracelets en fer émeraude et deux jambières en fer émeraude – pour votre apprentissage et la souffrance de vos ennemis !", progress = "Leurs crânes vont craquer sous la pression de vos bottes !", completion = "Vous rappelez à Orokk son grand-père, le chef des Omosh, Gorokk ! Lisez, apprenez le secret des bottes en fer.", rewards = "Vous recevrez :\n\nPlans : Bottes barbares en fer"},
[2754] = {title = "Les cornes de Frénésie", objective = "Apporter 2 Solides maillets en fer, 2 Bottes en bronze argenté et 2 Gantelets en bronze argenté à Orokk Omosh à Orgrimmar.", description = "Voici la dernière leçon d'Orokk, <nom>. A l'enclume sacrée et à la forge, vous devez retourner ! Apportez à Orokk deux solides maillets en fer, deux bottes en bronze argenté et deux gantelets en bronze argenté.\n\nRegardez la crainte grandir dans leurs yeux à votre approche !", progress = "Montrez-moi le fer que vous travaillez, <nom> !", completion = "Étonnant ! Vous avez appris les secrets des Omosh, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nPlans : Casque barbare en fer"},
[2755] = {title = "Les joies des Omosh", objective = "Regarder et apprendre la Danse de joie des Omosh.", description = "Orokk ne pleure pas, <nom>. Il a une poussière dans l'œil.\n\n<Orokk essuie une larme.>\n\nIl y a un dernier secret de famille Omosh qu'Orokk va transmettre. Orokk mourra heureux, grâce à <nom>.\n\nApprenez la danse de joie des Omosh et vous apprendrez ensuite le secret des Poings de fer !", progress = nil, completion = "&lt; Orokk halète.&gt;\n\nIl y a bien longtemps qu'Orokk n'a pas fait la Danse de joie des Omosh. Apprenez maintenant, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nPlans : Gants barbares en fer"},
[2756] = {title = "Les vieilles voies", objective = "Apporter 4 Cuirasses en acier et 4 Heaumes en plaques d'acier à Aturk l'Enclume à Orgrimmar.", description = "Aux temps légendaires, Aturk aurait écrasé les crânes de ses ennemis et réduit leurs os en poudre comme combustible de lampe. Ces jours sont loin, <nom>. Le chef de guerre appelle à la paix parmi les clans. Les vieux ennemis ne sont plus observés que par des yeux fatigués ! \n\nC'est incroyable, je sais, mais telle est la volonté de Thrall.\n\nAssez ! Vous êtes ici pour apprendre et vous allez apprendre ! Apportez-moi quatre cuirasses en acier et quatre heaumes en plaques d'acier et vous aurez un avant-goût de la guerre !", progress = "Aturk, comme le temps, n'attend personne ! Dépêchez-vous !", completion = "Encore un sous-fifre complaisant du chef de guerre ! Quelle déception, &lt;nom&gt;...\n\nMoi qui rêvais d'une mort glorieuse au champ de bataille, je suis cantonné ici, par ordre de Thrall, à transmettre mon art aux enfants en bas âge ! Regardez et apprenez, gamin !", rewards = "Vous allez être la cible du sort suivant :\n\nApprendre Jambières de guerre orques\n\nVous recevrez :\n\n"},
[2757] = {title = "Baie-du-Butin ou la mort !", objective = "Aller voir McGavan à Baie-du-Butin.", description = "Écoutez, <gamin/gamine> : vous n'apprendrez plus rien ici.\n\nJe connais un type qui connaît un autre type. Il tourne autour de la forge à Baie-du-Butin. Montrez-lui cet insigne, il vous dira tout du mithril.\n\nAlors, qu'en dites-vous ? Laissez cette matière aux bébés dans leurs langes, <nom>. Il est temps de progresser.\n\nSi ça vous intéresse, ce gars s'appelle McGavan. Montrez-lui ce bibelot et il reconnaîtra votre engagement.", progress = "Vous êtes d'une race rare, l'ami. Laissez-moi voir cet insigne.", completion = "Par la barbe de Blackhoof ! Enfin quelqu'un digne de l’Ordre du Mithril !", rewards = "Vous recevrez :\n\n"},
[2758] = {title = "Les origines de la forge", objective = "Apporter 6 Brassards en écailles dorées à Hank le Marteau à Stormwind.", description = "Quand j'avais votre âge, un nain du nom de Galvan m'a pris sous son aile et m'a tout appris du métier de Forgeron d'armures. Avant de partir pour Baie-du-Butin, il m'a fait promettre de former tous ceux qui auraient le désir et la détermination de devenir forgerons.\n\nBien, il est temps pour vous d'apprendre quelque chose. Faites-moi six brassards en écailles dorées et vous comprendrez comment on devient forgeron, <nom>.", progress = "Serez-vous le prochain protégé de Galvan ?", completion = "Très bien, &lt;nom&gt; ! Écoutez et apprenez.\n\nL'art de la forge ne vient jamais d'ici ! \n\nL'art de la forge ne vient jamais d'ici ! \n\nL'art de la forge ne peut venir que d'ici ! \n\nMaintenant vous connaissez l'origine de l'art de la forge.", rewards = "Vous recevrez :\n\nPlans : Gantelets en écailles dorées"},
[2759] = {title = "À la recherche de Galvan", objective = "Aller voir McGavan à Baie-du-Butin.", description = "Galvan a quitté Baie-du-Butin depuis longtemps, mais les membres de l'ordre sont restés en ville, espérant trouver un jour une autre personne digne de la tutelle de Galvan.\n\nPortez cet insigne à McGavan à Baie-du-Butin.\n\nSi vous avez réussi à aller aussi loin, il saura que vous êtes digne de lui. J'ai foi en vous, <nom> !", progress = "Vous êtes d'une race rare, l'ami. Laissez-moi voir cet insigne.", completion = "Par les poils de Sabot-noir ! ! Enfin quelqu'un digne de l’Ordre du mithril !", rewards = "Vous recevrez :\n\n"},
[2760] = {title = "L'Ordre du mithril", objective = "Aller voir Galvan l'Ancien dans la vallée de Strangleronce.", description = "La plupart de nos recrues ne vont jamais jusqu'à Baie-du-Butin, <nom>. L'éclat de l'insigne est suffisant pour déclencher la convoitise, même chez le plus loyal des forgerons. Les imbéciles ! Cet insigne est une goutte d'eau en comparaison de l'océan des richesses que vous verrez !\n\nAllez trouver Galvan l'Ancien et montrez-lui cette épingle. Il habite loin au nord, entre Zul Gurub et le tertre des ogres Mosh'Ogg.", progress = "Salut ! Approchez-vous, montrez à Galvan ce que vous avez.", completion = "Ah ! Beaucoup d'années se sont écoulées sans que personne ne soit digne d’être initié à l’Ordre du mithril. Nous allons commencer tout de suite !", rewards = "Vous recevrez :\n\n"},
[2761] = {title = "Ça fond, ça ne fond pas", objective = "Apporter 40 Barres de mithril et 40 Barres de fer à Galvan l'Ancien à Strangleronce.", description = "Beaucoup de forgerons pensent qu'extraire le minerai et le travailler sont des tâches séparées, indépendantes, mais qui peut être forgeron sans être mineur ? C'est impossible ! Un forgeron accompli doit aussi être un mineur accompli.\n\nMontrez donc à Galvan ce dont vous êtes capable, <nom>. Apportez-moi quarante barres de fer et quarante barres de mithril. En échange, Galvan vous apprendra comment réaliser des jambières ornées en mithril !", progress = "Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !", completion = "Votre éthique de travail est excellente, &lt;nom&gt; ! Vous commencez à comprendre les voies de la minéralogie de Galvan ! Prenez ceci et apprenez-en le plus de choses possible.", rewards = "Vous recevrez :\n\nPlans : Jambières ornées en mithril"},
[2762] = {title = "Le vif-argent n’est pas de l'argent", objective = "Apporter 40 Barres de mithril et 5 Barres de vrai-argent à Galvan l'Ancien à Strangleronce.", description = "On dit que le vrai-argent est plus solide et plus résistant que le mithril. Galvan n'est pas contre les comparaisons, mais contrairement à ce que son nom laisse croire, le vrai-argent n'est pas de l'argent ! Le mithril est un minerai beaucoup plus noble ! Il faut comprendre cela par soi-même, <nom>.\n\nApportez-moi quarante barres de mithril et cinq barres de vrai-argent. En échange, vous saurez le secret des Gants ornés en mithril et mieux, vous comprendrez que le vrai-argent ne tient pas ses promesses !", progress = "Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !", completion = "C'est une maîtresse cruelle, n'est-ce pas, &lt;nom&gt; ? Je parle du vrai-argent, naturellement. Eh oui ! Il a fallu à Galvan une décennie passée dans les montagnes d'Alterac pour apprendre cette leçon. Prenez ceci et apprenez-en autant que vous pourrez !", rewards = "Vous recevrez :\n\nPlans : Gants ornés en mithril"},
[2763] = {title = "L'art de l'imprégnation", objective = "Apporter 40 Barres de mithril et 4 Citrines à Galvan l'Ancien à Strangleronce.", description = "Les pierres précieuses sont de la plus grande importance pour notre art, <nom>. Peu de gemmes sont plus précieuses que la citrine. Elle amplifie les propriétés magiques que nous insufflons à nos produits.\n\nPour cette leçon, nous allons renforcer quarante barres de mithril avec quatre citrines. Cela vous permettra de mieux comprendre la gemmologie magique et comment créer des Epaulières ornées en mithril.", progress = "Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !", completion = "On ne peut que difficilement détacher ses yeux d'une telle splendeur, &lt;nom&gt;. Oui, la citrine est réellement une gemme précieuse entre toutes.\n\nRegardez bien et retenez la leçon.", rewards = "Vous recevrez :\n\nPlans : Epaulières ornées en mithril"},
[2764] = {title = "Le meilleur disciple de Galvan", objective = "Parler à Trenton Lighthammer à Gadgetzan.", description = "Si vous êtes sur le point de terminer votre formation avec Galvan, vous devez aller à Gadgetzan.\n\nLà, vous trouverez mon meilleur élève : Trenton Lighthammer. Il a beaucoup à vous apprendre sur le mithril orné. Sinon restez ici et apprenez !\n\nOh bien sûr Gadgetzan est à Tanaris !", progress = nil, completion = "Galvan l'Ancien vous envoie ?\n\n&lt;Trenton s'incline.&gt;\n\nC'est un grand honneur de rencontrer un autre des élèves du Maître.", rewards = "Vous recevrez :\n\n"},
[2765] = {title = "Maître Forgeron !", objective = "Réclamez votre récompense à Galvan l'Ancien !", description = "J'ai su, dès que je vous ai vu, que vous deviendriez un de mes meilleurs disciples ! Vous n’avez pas hésité à donner une relique à McGavan. Dans le seul but de le rencontrer. Une telle foi et une telle dévotion pour l'art doivent être récompensées.\n\nVous avez obtenu une expertise dans l'art de la forge, <nom>. Cueillez le fruit de vos efforts !", progress = nil, completion = "Il est juste que vous receviez une relique de plus grande valeur que celle que vous avez sacrifiée pour venir ici. Utilisez-la avec soin, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nChevalière d'expertise"},
[2766] = {title = "Trouvez OOX-22/FE !", objective = "Placer la balise de détresse dans le robot d'Oglethorpe qui se trouve dans une caverne près du val des Griffes farouches.", description = "Vous découvrez une sorte d'engin métallique en forme d'œuf. Il revient à la vie lorsque vous tripotez l'un de ses boutons, apparaissant comme un machin robotique gnome ! Une voix grésille.\n\n\"Mon nom est Oglethorpe Obnoticus, et mon robot guidé s'est perdu ! Je vous récompenserai si vous le retrouvez. S'il vous plaît allez placer cette balise dans le robot.\"\n\n\"J'ai calculé la position de mon robot égaré : il est dans une caverne près du val des Griffes farouches !\"", progress = "Vous découvrez l'épave d'une sorte de... robot poulet ? La voix émerge de l'oeuf une nouvelle fois :\n\n\"Oui, excellent travail ! C'est bien mon robot guidé, mes détecteurs m'indiquent qu'il doit être relancé avant de pouvoir revenir à Baie-du-Butin pour y être réparé. Allez-y et placez la balise dans la machine. La balise s'occupera du reste !\"", completion = "Vous placez l'oeuf... la balise de détresse... dans le poulet... le robot guidé.\n\nVous entendez des bourdonnements venant de l'intérieur du robot quand il essaie de se relever. Après l'activation du robot, la voix d'Oglethorpe retentit de nouveau, mais maintenant elle vient de l'intérieur du robot :\n\n\"OOX-22/FE fonctionne finalement, mais il a besoin de grosses réparations ! Il est trop lourd pour vous... mais je pense que j'ai une idée. Voudriez-vous bien le surveiller encore un peu ?\"", rewards = "Vous recevrez :\n\n"},
[2767] = {title = "Sauvez OOX-22/FE !", objective = "Escorter OOX-22/FE au dock le long de la Côte oubliée, puis faire votre rapport à Oglethorpe Obnoticus à Baie-du-Butin.", description = "Le robot émet à nouveau la voix du gnome :\n\n\"Je dois déplacer OOX-22/FE dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage. Il est équipé d'un camouflage, mais il me faut du temps pour le rendre opérationnel. J'ai besoin que vous escortiez le robot jusqu'à... disons la Côte oubliée ! Ce serait un endroit parfait et assez vaste pour que tout puisse se mettre en route !\"\n\nEscortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Oglethorpe Obnoticus - terminé !\"", progress = nil, completion = "Alors c’est VOUS le sauveur de OOX-22/FE ! Je ne sais même pas comment vous remercier pour votre aide ! Ma série de robots guidés a encore besoin d'être améliorée, mais votre intervention m'a permis de gagner de nombreuses heures de travail, ainsi qu'une somme significative en matières premières !\n\nS'il vous plaît, faites votre choix parmi ces objets. Merci encore pour votre assistance généreuse, &lt;nom&gt;, mes robots et moi sommes vos débiteurs !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nExpérience de vol ratéeServiette en cotte de mailles\n\nVous recevrez également :\n\n"},
[2768] = {title = "Le bâtonnet divino-matic", objective = "Rapporter le Bâtonnet divino-matic à l'Ingénieur en chef Bilgewhizzle, à Gadgetzan.", description = "Le sergent Bly m'a volé ! Il a dit qu'il ne faisait que l'emprunter, mais il a volé mon bâtonnet divino-matic ! Sans lui, comment savoir où creuser de nouveaux puits ?\n\nTrouvez Bly et reprenez mon bâtonnet ! J'ai entendu qu'il emmenait une bande d'aventuriers mal famés chasser les trésors à l'ouest, à Zul'Farrak. Je parie que vous le trouverez là-bas.\n\nEspérons que les trolls se seront déjà occupés de lui, car si vous devez l’affronter pour reprendre le bâtonnet, le combat sera difficile.", progress = "Avez-vous trouvé le sergent Bly ? Avez-vous récupéré mon bâtonnet divino-matic ?", completion = "Vous l'avez trouvée ! Bien joué, &lt;nom&gt; ! Avez-vous eu besoin de vous battre avec Bly pour l'avoir ? J'espère que vous l'avez battu une bonne fois pour toutes, lui et sa bande !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau de la fraternité des maçonsCouvre-chef de la guilde des ingénieurs\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2769] = {title = "Les frères Brassbolts", objective = "Parler à Wizzle Brassbolts dans les Salines.", description = "Avez-vous rencontré les frères Brassbolt ? Ils sont dans les Salines en Kalimdor. Ils font des courses de voitures à fusée contre les gobelins. Ils gagnent régulièrement. Il faut dire que les voitures des gobelins explosent si souvent qu'elles passent rarement la ligne d'arrivée !\n\nMalgré cela, les frères Brassbolt cherchent toujours à avoir une voiture plus rapide. Wizzle m'a dit qu'il cherchait un composant très rare pour sa nouvelle expérience.\n\nIl a besoin d'aide pour trouver ce composant. Allez l'aider.", progress = nil, completion = "Ah ! Vous avez besoin de mon aide ? Excellent !\n\nJ’ai besoin d’une pièce pour une expérience sur laquelle je travaille, et j'ai besoin de l'aide de quelqu'un comme vous, &lt;classe&gt;, pour m'aider à l'obtenir !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2770] = {title = "Gahz'rilla", objective = "Rapporter les Ecailles électrifiées de Gahz'rilla à Wizzle Brassbolts dans les Salines.", description = "Au coeur de Zul'Farrak, la cité des trolls des sables à Tanaris, il y a un bassin sacré. De ce bassin, les trolls invoquent une bête énorme ! Gahz'rilla ! Elle est tellement puissante que même ses écailles crépitent d'énergie. C'est cette énergie que je convoite pour ma voiture !\n\nRapportez-moi les écailles électrifiées de Gahz'rilla !\n\nMais l'invocation de Gahz'rilla est l’un des secrets les mieux gardés des trolls. Avant d’affronter le monstre, vous devez apprendre le secret des trolls.", progress = "Avez-vous les écailles ? Je suis impatient d'essayer de trouver des moyens de mettre cette énergie à profit.", completion = "Bon sang, vous avez les écailles ! Merci, &lt;nom&gt;. J'étais impatient de travailler dessus !\n\nAlors, vous avez vu Gahz'rilla ? Cette créature était-elle vraiment aussi grande que le disait la rumeur.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCarotte et bâton"},
[2771] = {title = "Une tête bien faite sur les épaules", objective = "Rapporter deux Camails en mithril et une paire d'Epaulières ornées en mithril à Trenton Lighthammer.", description = "Il semble que le maître ait planifié tout cela depuis le début. Je n'ai pas appris à créer le genre d'objet que vous savez créer, de même que vous ne savez pas créer ce que je sais faire.\n\nLe maître est sage, <nom>. Chacun de nous doit apprendre de l'autre !\n\nMontrez-moi comment faire un camail en mithril et des épaulières ornées en mithril et je vous montrerai comment faire un heaume orné en mithril.", progress = "Avez-vous terminé de fabriquer les objets, <nom> ?", completion = "Excellent ! Un très bon échange ! Regardez et apprenez, &lt;nom&gt; !", rewards = "Vous allez être la cible du sort suivant :\n\nApprendre Heaume orné en mithril\n\nVous recevrez :\n\n"},
[2772] = {title = "Le monde à vos pieds", objective = "Rapporter deux paires de Bottes en mithril lourd et des Jambières ornées en mithril à Trenton Lighthammer.", description = "Au dernier championnat intervallée des forgerons, tous les spectateurs ont vu un de ces chiens de la mine de la KapitalRisk m'attaquer la jambe. Mais ils ne savent pas ce qui m'a permis de continuer et de gagner ce championnat. Eh oui ! Des bottes ornées en mithril !\n\nJe vais avoir besoin d'apprendre à faire des jambières ornées en mithril cette année, car la KapitalRisk participe encore au championnat ! Apprenez-moi comment faire les jambières et je vous apprendrai à faire les bottes !", progress = "Avez-vous terminé de fabriquer les objets, <nom> ?", completion = "Le monde sera à vos pieds, &lt;nom&gt; ! Soyez fier, car plus personne ne pourra vous faire tomber à la renverse !", rewards = "Vous allez être la cible du sort suivant :\n\nApprendre Bottes ornées en mithril\n\nVous recevrez :\n\n"},
[2773] = {title = "Le gars du mithril", objective = "Rapporter deux Cuirasses lourdes en mithril et une paire de Gants ornés en mithril à Trenton Lighthammer.", description = "Dans cette région, on m'appelle le gars du mithril. Je fournis des équipements ornés en mithril aux aventuriers du monde entier.\n\n<Trenton chuchote.>\n\nPeu savent que je ne connais pas la technique des gants ornés en mithril. Mais chut ! Cela sera notre petit secret.\n\nEnseignez-moi cette technique, <nom>, et en échange je vous montre le point culminant de mon apprentissage chez Galvan : la cuirasse ornée en mithril.", progress = "Avez-vous terminé de fabriquer les objets, <nom> ?", completion = "Merci pour tout ce que vous m'avez appris, &lt;nom&gt;. Vous maîtriserez bientôt tout l'équipement orné en mithril.\n\nRegardez !", rewards = "Vous allez être la cible du sort suivant :\n\nApprendre Cuirasse ornée en mithril\n\nVous recevrez :\n\n"},
[2781] = {title = "ON RECHERCHE : Caliph Dard-de-scorpide", objective = "Apporter la tête de Caliph Dard-de-scorpide à l'Ingénieur en chef Bilgewizzle à Gadgetzan.", description = "ON RECHERCHE : Caliph Dard-de-scorpide !\n\nLa Compagnie des Eaux de Gadgetzan de Tanaris paiera une forte récompense pour la tête de Caliph Dard-de-scorpide, chef des hors-la-loi Bat-le-désert. Ses crimes sont :\n\n1) Assassinat d'employés de la Compagnie des Eaux de Gadgetzan ;\n2) Vol des ressources de la Compagnie des Eaux de Gadgetzan ;\n3) Vol des biens de la Compagnie des Eaux de Gadgetzan.\nRapportez les preuves de la mort de Caliph Dard-de-scorpide à l'ingénieur en chef Bilgewizzle pour toucher immédiatement votre récompense.", progress = "Oui, <classe>, je suis l'un des cadres de la Compagnie des Eaux de Gadgetzan. Que puis-je pour vous ?", completion = "Justice est enfin rendue ! Vous avez donné une bonne leçon à ces maudits nomades. La mort de Dard-de-scorpide repoussera ces pillards loin des puits de la Compagnie des Eaux de Gadgetzan !\n\nPar l'autorité que me confère la Compagnie des Eaux de Gadgetzan, je vous remets cette prime. Vous avez rendu un fier service à la communauté.", rewards = "Vous recevrez :\n\n"},
[2782] = {title = "Secret de Rin'ji", objective = "Oran Snakewrithe, une érudite réputée pour sa connaissance des us et coutumes des trolls Witherbark, pourrait peut-être déchiffrer la tablette. Elle habite le Quartier de la magie à Undercity.", description = "La tablette est couverte de lettres gravées par des trolls Witherbark. Le secret de Rin'ji est réellement un mystère…\n\nIl est possible que vous ayez quelque chose de réellement précieux entre les mains. Mais l'inverse est également possible. Un troll Witherbark en détresse ferait probablement n'importe quoi pour s'en sortir...", progress = "Bien, maintenant, qu'est-ce que ceci ?", completion = "Cette tablette… Plutôt inhabituelle… Où l'avez-vous trouvée, &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[2783] = {title = "Querelles mesquines", objective = "Parler au Héros déchu de la Horde à la frontière des Terres foudroyées et du marais.", description = "Nous avons combattu le mauvais ennemi, <nom>.\n\nLa vraie puissance de cette région continue de croître alors que nous nous chamaillons avec les orcs sur cette terre aride.\n\nDevons-nous continuer à nous battre contre la Horde, pour finir écrasés un jour par les armées de la Légion ardente ? C'est futile.\n\nMettez vos différences de côté, <nom>, parlez au Héros déchu de la Horde. Il sait ce qui se passe dans les Terres foudroyées.", progress = nil, completion = "L'Alliance veut nous aider !\n\nJe croyais ne jamais revoir ce jour. Un jour où l'Alliance combattrait aux côtés de la Horde contre un ennemi commun.\n\nQu’il en soit ainsi… Nous serons unis.", rewards = "Vous recevrez :\n\n"},
[2784] = {title = "Perte d'honneur", objective = "Écouter le Héros déchu de la Horde raconter son histoire.", description = "Écoutez mon histoire, <nom>.", progress = "Écoutez ce que j'ai à dire.", completion = "En tant qu'esprit, je suis impuissant, &lt;nom&gt;. Aidez-moi. Permettez-moi de regagner mon honneur.", rewards = "Vous recevrez :\n\n"},
[2801] = {title = "Une histoire de chagrin", objective = "Écouter le Héros déchu de la Horde raconter son histoire.", description = "Avant que nous continuions, vous devez écouter mon histoire.", progress = "Écoutez ce que j'ai à dire, <nom>.", completion = "Maintenant, il est temps d'agir, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2821] = {title = "La marque de la qualité", objective = "Rapporter 10 Peaux de yéti épaisses à Pratt McGrubben au bastion de Feathermoon.", description = "Ma philosophie, concernant le travail du cuir, c’est que mon travail doit être le meilleur possible : pas de compromis. Quelqu’un disant que la qualité ne compte pas essaye de vous escroquer !\n\nDans ma recherche de matières premières de qualité, rien ne vaut la peau de yéti épaisse. Elle provient des yétis de Feralas, et il y en a beaucoup au val des Griffes farouches. J'en ai besoin et j’échangerai l'un de mes objets en cuir contre un ballot de dix peaux. Si cela vous semble équitable, le marché est conclu.", progress = "Un ballot de dix peaux de yéti épaisses vous permettra de choisir l'un des objets que j'ai confectionnés. Parce que je suis soucieux de la qualité, je vous fournirai un objet de valeur !\n\nSi vous ne trouvez pas de yétis, je peux vous dire où il y en a. Essayez donc à l'intérieur des terres proches de la Côte oubliée, au val des Griffes farouches.", completion = "Avez-vous pris le temps d’examiner ces peaux ? Traitées de la bonne façon, elles seront plus résistantes que le fer. Peu de gens connaissent ces peaux. Je sais qu'en utilisant les bons produits, je vais pouvoir confectionner des objets d'une grande qualité... Merci à vous, bien sûr !\n\nEt maintenant, choisissez parmi mes meilleures réalisations, pour services rendus !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes artisanales de PrattGants artisanaux de Pratt\n\nVous recevrez également :\n\n"},
[2822] = {title = "La marque de la qualité", objective = "Apporter 10 Peaux de yéti épaisses à Jangdor Swiftstrider au Camp Mojache.", description = "Je suis fier de mon travail et je sais que cela se voit : la qualité ne doit jamais être dévalorisée. Quiconque dit que la qualité n’est pas primordiale ferait également croire que les abysses sont lumineux.\n\nDans ma recherche de matières premières de qualité, rien ne vaut la peau de yéti épaisse. Elle provient des yétis de Feralas, et il y en a beaucoup au val des Griffes farouches, à l'ouest d'ici. Je vous laisserai choisir un objet parmi mes créations contre un ballot de dix peaux. Si cela vous convient, nous faisons affaire !", progress = "Avez-vous mes dix peaux de yéti épaisses ? Mes créations sont de belle qualité et je vous en procurerai un exemplaire si vous pouviez me fournir ces peaux.\n\nSi vous ne parvenez pas à trouver de yétis, je peux vous dire où il y en a. Essayez donc à l'ouest d'ici, à l'intérieur des terres proches de la Côte oubliée, au val des Griffes farouches.", completion = "Ah, excellent ! Avec un traitement spécial, ces peaux seront plus résistantes que du fer, je vous le dis ! Il faudra plusieurs essais avant de trouver la bonne formule, mais je suis certain que je vais pouvoir accroître la qualité de mes produits.\n\nQuant à vous, &lt;nom&gt;, votre assistance s'est avérée précieuse. Je vous en prie, choisissez parmi mes créations.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes artisanales de JangdorGants artisanaux de Jangdor\n\nVous recevrez également :\n\n"},
[2841] = {title = "Guerre des plates-formes", objective = "Obtenir la Combinaison du coffre de Thermaplugg, prendre les Plans de la plate-forme et les apporter à Nogg à Orgrimmar.", description = "Technologie gnome… Ce terme était autrefois brandi comme un slogan. Les temps ont changé. Ils ont désormais une nouvelle plate-forme, supérieure à tous nos modèles de Déchiqueteurs combinés. J'ai besoin des plans de cette plateforme, <nom> !\n\nMalheureusement ceux-ci sont enfermés dans le coffre du mekgénieur Thermaplugg. Et pour compliquer les choses, la combinaison du coffre n'est connue que de lui seul.\n\nFaites ce qu’il faut pour obtenir cette combinaison, <nom>. Puis ouvrez le coffre et ramenez-moi ces plans !", progress = "Je ne vois aucun plan. Les avez-vous cachés quelque part sur vous ou bien êtes-vous juste là pour m'énerver ?", completion = "Je savais que vous pouviez y arriver, &lt;nom&gt; ! Sovik, lui, avait des doutes.\n\n\n\nMaintenant que nous avons les plans en notre possession, c'est juste une question de temps avant que nous n’assimilions les innovations des gnomes et que nous les intégrions à nos propres Déchiqueteurs.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe civinadeChausses du coureurJambières à double renfort\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2842] = {title = "L'ingénieur en chef Scooty", objective = "Parler à Scooty à Baie-du-Butin.", description = "Dès que nous aurons des nouvelles de Kernobee à propos de la nouvelle plate-forme des gnomes, Scooty et moi commencerons à travailler sur le Transpolyporteur 6000 : le moyen le plus rapide et le plus sûr d’aller à Gnomeregan.\n\nIl est enfin prêt à recevoir des passagers, <nom>. Si vous désirez l'essayer, allez à Baie-du-Butin et parlez avec Scooty au perchoir des Cavaliers célestes. Pour aller à Baie-du-Butin, prenez le bateau depuis Ratchet.\n\nVous pouvez aussi traverser les montagnes de Dun Morogh, mais elles sont infestées de nains…", progress = nil, completion = "Il est beau n'est-ce pas ? Le summum de la technologie de transport des gobelins, à peine une douzaine d'explosions.\n\nNe vous en faites pas, &lt;nom&gt;, j’ai fait la révision moi-même. Il n'explosera pas. Et si cela arrivait, ce serait rapide et sans douleur.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2843] = {title = "Gnomer-paaarti !", objective = "Attendre que Scooty calibre le transpondeur des gobelins.", description = "Aussi longtemps que vous êtes en possession du transpondeur des gobelins, tout ce que vous avez à faire est de traverser le portail et vous vous retrouverez à Gnomeregan.\n\nIl y aura peut-être des effets secondaires bizarres, mais aucun ne devrait être permanent... plus maintenant.\n\nJ'oubliais de parler du plus important : le retour. Lorsque vous serez <prêt/prête> à revenir, allez au portail de multitéléportation de Gnomeregan !\n\nBon, il faut maintenant régler le transpondeur selon votre poids et votre taille.", progress = nil, completion = "Fini ! Lorsque vous le désirez, traversez le portail.", rewards = "Vous recevrez :\n\nTranspondeur gobelin"},
[2844] = {title = "Le garde géant", objective = "Retrouver la jeune elfe de la nuit perdue.", description = "Je suis vraiment bon à rien, <nom>. J'étais supposé surveiller mon amie Shay, et je l’ai perdue. Je ne suis pas sûr de ce qui s'est passé, mais la dernière fois que je l'ai vue, nous étions en train de marcher dans les ruines au nord d'ici.\n\nTout allait bien, mais lorsque je me suis retourné vers elle... elle avait disparu.\n\nMaintenant je ne sais plus quoi faire. Vous avez une idée, <nom> ? Je suis affreusement inquiet.\n\nEt si vous alliez la chercher ? Vos jambes vous permettent d'aller plus vite que moi.", progress = nil, completion = "Oh ! Je suis si heureuse que vous m'ayez retrouvée ! Je dois admettre que je me suis un peu perdue… Mais n'est-ce pas un endroit admirable ?", rewards = "Vous recevrez :\n\n"},
[2845] = {title = "Shay l'égarée", objective = "Prendre la Cloche de Shay dans le coffre.\n\nEscorter Shay Leafrunner au Camp de Croque-roc.", description = "Pouvez-vous m'aider à retrouver mon chemin jusqu'à mon ami, Croque-roc ? Il était supposé me surveiller… Mais j'ai tendance à folâtrer de-ci de-là. Il y a tant de choses à voir et je me laisse facilement distraire.\n\nIl y a toutefois une chose qui me ramène toujours.\n\nDans ce coffre, vous trouverez une cloche qui m'est précieuse. J'adore sa sonorité. Si je m'égare, vous n'avez qu'à la faire sonner, je reviendrai immédiatement.", progress = "J'commençais à me faire du mouron pour toi ! Merci bien de l'avoir ramenée à la maison, <nom>.", completion = "Quoi ? Vous dites que cette cloche ramène Shay lorsqu’elle disparaît ? C'a l'air bien pratique !\n\nComme vous m'avez rendu service, v'là pour vous, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoignes de granitCordelière de la charmille\n\nVous recevrez également :\n\n"},
[2846] = {title = "La tiare des abysses", objective = "Rapporter la Tiare des abysses à Tabetha au marécage d'Âprefange.", description = "Il y a longtemps, je possédais une splendide pièce de joaillerie, la tiare des abysses. Elle n'était pas seulement belle, elle détenait un grand pouvoir, pour ceux qui savaient l'utiliser.\n\nQuand l'hydromancienne Velratha apprit son existence, elle l’a convoitée. Elle a envoyé des agents chez moi pour la voler pendant mon absence. Voleurs !\n\nJe veux ma tiare ! Allez à Zul'Farrak, la cité des trolls à Tanaris, trouvez Velratha et reprenez-lui la tiare. Rapportez-la et vous gagnerez mes faveurs.", progress = "Avez-vous la tiare, <nom> ? Est-ce que Velratha a compris ce qu'il en coûtait de s'en prendre à moi ?", completion = "Merveilleux ! Vous l'avez trouvée ! Et plus important encore, Velratha ne l'a plus ! Merci, &lt;nom&gt;. Je suis à jamais votre débitrice !\n\nEt si je vous ai semblé un peu… agressive au début, n'y prêtez pas attention. Je suis plus plaisante avec ceux qui ne me volent pas.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBâtonnet d'altérationEspauliers de schiste précieux"},
[2847] = {title = "L'armure en cuir sauvage", objective = "Rapporter 10 Cuirs épais à Pratt McGrubben au bastion de Feathermoon.", description = "<nom>, vous avez acquis une bonne connaissance du travail du cuir ! Mais je sais des choses qui pourraient vous intéresser… L'armure en cuir sauvage ! L’intérêt du cuir sauvage tient aux propriétés chaotiques des sauvageonnes et de quelques autres créatures d'ici. L'armure que vous réaliserez sera ce qu’un artisan de votre compétence peut fabriquer de mieux.\n\nJe vous apprendrai à la réaliser si vous acceptez de travailler pour moi pendant un moment. Le coût initial est juste de dix pièces de cuir épais. Après nous parlerons technique.", progress = "Comme je vous le disais, vous allez travailler pour moi pendant que je vous apprendrai à réaliser l'armure en cuir sauvage. Parce que les sauvageonnes sont puissantes et chaotiques, l’armure bénéficie d’une amélioration puissante, mais aléatoire. Ce savoir, toutefois, n'est pas facile à acquérir.\n\nLe coût initial est de dix pièces de cuir épais.\n\nUne fois cette première étape réglée, nous verrons comment obtenir les patrons.", completion = "Eh bien, &lt;nom&gt;, je suis heureux de vous avoir à mes côtés ! Vous avez pris une bonne décision en tant que tanneur, ceux qui portent des armures en cuir loueront votre nom et votre art lorsque vous aurez appris à confectionner des armures en cuir sauvage.\n\nAu travail ! Par où désirez-vous commencer ?", rewards = "Vous recevrez :\n\n"},
[2848] = {title = "Les épaulières en cuir sauvage", objective = "Apporter 6 Renforts d'armure épais et 1 Sauvageonne à Pratt McGrubben au bastion de Feathermoon.", description = "Les épaulières en cuir sauvage protègent efficacement le haut des bras et les épaules. Comme l'ensemble des pièces d'armure en cuir sauvage, elles bénéficient d'une qualité supplémentaire, mais aléatoire, en raison de l'utilisation des sauvageonnes.\n\nPour ce patron, j’ai besoin de six renforts d'armure épais et d’une sauvageonne. Cela ne devrait pas vous poser de problèmes.", progress = "Avez-vous les six renforts d'armure épais et la sauvageonne que je réclame ?\n\nLa confection des renforts d'armure n’est pas un travail fastidieux. Considérez-le comme un exercice de perfectionnement avant d’attaquer la création plus difficile d'une armure en cuir sauvage.\n\nVous voyez, il y a une raison si je vous demande de faire cela pour moi...", completion = "Ces kits d’armure sont d'une bonne qualité, &lt;nom&gt;. S’il y a bien une chose sur laquelle j’insiste, c’est la qualité.\n\nVous avez bien travaillé pour gagner le patron de ce modèle. J'espère qu'il vous apportera toute la satisfaction qu'il m'a donnée.", rewards = "Vous recevrez :\n\nPatron : Epaulières en cuir sauvage"},
[2849] = {title = "Le gilet en cuir sauvage", objective = "Rapporter 2 Cuirasses en écailles de tortue, 2 paires de Gants en écailles de tortue et 1 Sauvageonne à Pratt McGrubben au bastion de Feathermoon.", description = "Le gilet en cuir sauvage est la pièce maîtresse de toute armure en cuir sauvage. Il procure une protection maximale du torse tout en permettant à la puissante magie des sauvageonnes de se diffuser dans l’armure.\n\nPour ce modèle, je demande deux paires de gants en écailles de tortue, deux cuirasses en écailles de tortue et une sauvageonne. C'est une grosse commande, mais vous ne devriez pas avoir de problème à me la fournir.", progress = "Avez-vous les deux cuirasses et les gants en écailles de tortue que je vous ai demandés ? Et n'oubliez pas la sauvageonne !\n\nNous savons que les formes les plus simples servent de base à la réalisation d’objets plus complexes. Bien que différents, les cuirasses en écailles de tortue vous préparent à la confection d'un gilet en cuir sauvage.\n\nLes gants ? Ils sont pour mon usage personnel. N'oubliez pas : vous travaillez pour moi !", completion = "Ce sont de très jolies pièces, &lt;nom&gt;. Le soin apporté à leur réalisation rapportera beaucoup plus de pièces d'argent que le modèle ordinaire.\n\nVous avez rempli toutes mes conditions, alors recevez votre dû. La connaissance de la fabrication d'un gilet en cuir sauvage est vôtre à présent !", rewards = "Vous recevrez :\n\nPatron : Gilet en cuir sauvage"},
[2850] = {title = "Le casque en cuir sauvage", objective = "Rapporter 2 Tuniques de la nuit, 2 Bandeaux de la nuit et 1 Sauvageonne à Pratt McGrubben au bastion de Feathermoon.", description = "Un casque en cuir sauvage offre une protection optimale sans sacrifier au confort. Comme pour l'armure en cuir sauvage, les sauvageonnes lui apportent une amélioration puissante, mais aléatoire. Les porteurs d'armures de cuir raffolent de cet article !\n\nPour ce modèle, j'ai besoin de deux tuniques de la nuit, deux bandeaux de la nuit et d'une sauvageonne. Complétez cette commande et le patron est à vous !", progress = "J'ai besoin de ces tuniques et bandeaux ainsi que de la sauvageonne avant de partager avec vous mes connaissances sur le casque en cuir sauvage.\n\nLes couvre-chefs sont appréciés des aventuriers, que cela soit un simple bandeau ou un casque fermé. Les bases de la création sont les mêmes, quelle que soit l'apparence du casque.", completion = "L'équipement de la nuit que vous m'avez fourni correspond parfaitement à ma commande, &lt;nom&gt;. Je n'en attendais pas moins d'un ouvrier du cuir tel que vous.\n\nVous avez bien gagné ce patron. Je vous le donne en espérant que vous en tirerez profit.", rewards = "Vous recevrez :\n\nPatron : Casque en cuir sauvage"},
[2851] = {title = "Les bottes en cuir sauvage", objective = "Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Pratt McGrubben au bastion de Feathermoon.", description = "Vous avez déjà beaucoup appris, <nom>. Mais ce n’est pas fini. Après viennent les bottes en cuir sauvage, la pierre angulaire de tout l'équipement.\n\nCes bottes protègent bien les pieds tout en étant très confortables. Les semelles souples sont une bénédiction pour ceux qui se déplacent discrètement.\n\nPour ces bottes, j'ai besoin de deux pantalons de la nuit, de deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, faites-le-moi savoir.", progress = "La commande de pantalons, de bottes et de sauvageonnes doit m'être livrée avant que vous ne receviez le patron, <nom>. Avez-vous terminé ?\n\nDès la première paire que nous confectionnons, nous comprenons que les bottes parfaites sont un savant équilibre entre fonction et confort. Nous pouvons créer des bottes qui permettent au porteur d'ignorer la fatigue lorsqu'il les porte, contrairement à des bottes de moins bonne qualité.", completion = "Une fois de plus, vous avez traité une commande difficile avec l'habileté d'un professionnel. Vous avez bien mérité ce patron, ainsi que mes remerciements.", rewards = "Vous recevrez :\n\nPatron : Bottes en cuir sauvage"},
[2852] = {title = "Les jambières en cuir sauvage", objective = "Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Pratt McGrubben au bastion de Feathermoon.", description = "Vous pouvez maintenant apprendre des techniques plus complexes, <nom>. Les jambières en cuir sauvage sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l'utiliseront apprécieront grandement cette protection combinant l'amélioration apportée par la sauvageonne.\n\nPour ce modèle, j'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.", progress = "Avez-vous fini les brassards et les casques en écailles de tortue ? Et n'oubliez pas les sauvageonnes !\n\nPour le moment, vous commencez à peine à réaliser la puissance potentielle des armures en cuir sauvage. Une telle qualité est inestimable. La seule limite est la quantité de matières premières disponibles, et non la qualité du produit fini !", completion = "Une fois de plus vous avez rapporté la commande sans faillir. Peut-être qu'un jour je viendrai apprendre auprès de VOUS &lt;nom&gt; !\n\nVoici les patrons des jambières, avec mes remerciements. Ajoutez ce savoir à vos talents déjà impressionnants !", rewards = "Vous recevrez :\n\nPatron : Jambières en cuir sauvage"},
[2853] = {title = "Maître du cuir sauvage", objective = "Donner la Lettre de Pratt à Telonis, le Maître tanneur de Darnassus.", description = "Eh bien, <nom> ! Vous êtes un modèle de rapidité. Vous connaissez tous les patrons de l'armure en cuir sauvage, sauf un. Je ne vous demanderai rien pour celui-là, vous le méritez… mais je ne peux pas vous l’apprendre moi-même. Mon maître est le seul qui puisse vous transmettre ce savoir.\n\nPortez cette lettre à Telonis, il enseigne le travail du cuir à Darnassus. Montrez-lui la lettre et laissez-le vous reconnaître comme son égal, ainsi que je l'ai fait.", progress = "Salutations, <nom>… Je vois que vous travaillez le cuir comme je le fais. Venez-vous apprendre ou avez-vous besoin d'autre chose ?", completion = "Ah oui ! Pratt vous envoie. Bien qu'il soit humain, il me semble parfois être un &lt;race&gt;. Sa passion et ses talents pour le cuir sont impressionnants. Qu'il fasse des compliments de vous dans cette lettre est un signe dont je tiens compte.\n\nIl vous a enseigné l'art du cuir sauvage. Laissez-moi compléter votre formation. Et faites-en bon usage, car bien peu connaissent le secret de la cape en cuir sauvage.", rewards = "Vous recevrez :\n\nPatron : Cape en cuir sauvage"},
[2854] = {title = "L'armure en cuir sauvage", objective = "Rapporter 10 Cuirs épais à Jangdor Swiftstrider au Camp Mojache.", description = "<nom>, la renommée de vos talents vous précède. Je connais quelque chose qui pourrait vous intéresser... l'armure en cuir sauvage ! Le cuir sauvage tire ses propriétés des sauvageonnes que l'on trouve dans la végétation luxuriante et sur quelques créatures. Cela ne devrait pas être compliqué pour quelqu'un de votre niveau.\n\nJe vous enseignerai, mais en échange vous travaillerez pour moi pendant un moment. La première chose consiste à me rapporter dix pièces de cuir épais. Après nous discuterons technique.", progress = "Que cela soit bien clair, pendant que vous apprenez l'art de l'armure en cuir sauvage, vous êtes mon élève. Parce que les sauvageonnes sont puissantes et chaotiques, elles confèrent une amélioration puissante, mais aléatoire, aux armures résistantes que vous fabriquez.\n\nLe coût initial de la formation est de dix peaux épaisses.\n\nRapportez-les et nous verrons ce qu’il faut pour obtenir les patrons.", completion = "Eh bien, &lt;nom&gt; ! Je suis heureux de vous avoir dans mon équipe. Vous avez pris une décision sage. Les porteurs d'armures en cuir se précipiteront quand ils sauront que vous maîtrisez l’art du cuir sauvage.\n\nAu travail, par où désirez-vous commencer ?", rewards = "Vous recevrez :\n\n"},
[2855] = {title = "Les épaulières en cuir sauvage", objective = "Apporter 6 Renforts d'armure épais et 1 Sauvageonne à Jangdor Swiftstrider au Camp Mojache.", description = "Les épaulières en cuir sauvage protègent efficacement le haut des bras et les épaules. Comme toutes les pièces d'armure en cuir sauvage, elles bénéficient d'une amélioration puissante, mais aléatoire, grâce aux sauvageonnes.\n\nPour ce modèle, je demande six renforts d'armure épais et une sauvageonne. Cela ne devrait pas vous poser trop de problèmes.", progress = "Avez-vous les six renforts d'armure épais et la sauvageonne dont j'ai besoin ?\n\nLa confection des renforts d'armure est une leçon d'endurance et de précision. Cet apprentissage développe des talents qui seront utiles lors de la confection d'armures en cuir sauvage.\n\nChaque leçon a une raison d’être, <nom>. Il est important de les étudier une à une.", completion = "Ces renforts d'armure sont de bonne qualité, &lt;nom&gt;. S’il y a bien une chose sur laquelle j’insiste, c'est la qualité.\n\nVous avez gagné ce patron. J'espère qu'il vous conduira jusqu’où il m’a mené.", rewards = "Vous recevrez :\n\nPatron : Epaulières en cuir sauvage"},
[2856] = {title = "Le gilet en cuir sauvage", objective = "Rapporter 2 Cuirasses en écailles de tortue, 2 paires de Gants en écailles de tortue et une Sauvageonne à Jangdor Swiftstrider au Camp Mojache.", description = "Le gilet en cuir sauvage est la pièce maîtresse de toute armure en cuir sauvage. Il procure une protection maximale du torse tout en permettant à la puissante magie des sauvageonnes de se diffuser dans l’armure.\n\nPour ce patron, il me faut deux cuirasses et deux paires de gants en écailles de tortue, et une sauvageonne. Ce n'est pas une leçon facile, mais vous disposez clairement des talents pour la mener à bien.", progress = "Avez-vous les deux cuirasses et les gants en écailles de tortue ? Et n'oubliez pas la sauvageonne !\n\nNous savons que les formes les plus simples servent de base à la réalisation d’objets plus complexes. Bien que différents, les cuirasses en écailles de tortue préparent à la confection d'un gilet en cuir sauvage.\n\nAu fur et à mesure que vous progresserez, les techniques que je vous enseignerai se transformeront en art.", completion = "Ce sont de très jolies pièces, &lt;nom&gt;. La minutie et la précision que vous avez mises dans leur confection prouvent que vous êtes digne de ce métier.\n\nVous avez rempli mes conditions, voilà donc votre récompense. Le savoir permettant de confectionner un gilet en cuir sauvage est à vous !", rewards = "Vous recevrez :\n\nPatron : Gilet en cuir sauvage"},
[2857] = {title = "Le casque en cuir sauvage", objective = "Rapporter 2 Tuniques de la nuit, 2 Bandeaux de la nuit et 1 Sauvageonne à Jangdor Swiftstrider au Camp Mojache.", description = "Un casque en cuir sauvage offre au porteur une protection optimale sur les parties vitales sans sacrifier au confort. Comme pour l'armure en cuir sauvage, les sauvageonnes lui confèrent une amélioration puissante et aléatoire. Les porteurs d'armure en cuir sauvage souhaiteront avoir cette pièce d'équipement !\n\nPour ce modèle, j'ai besoin de deux tuniques de la nuit, deux bandeaux de la nuit et d'une sauvageonne. Rapportez-les et le patron est à vous !", progress = "J'ai besoin de ces tuniques et bandeaux ainsi que de la sauvageonne avant de partager avec vous mes connaissances sur le casque en cuir sauvage.\n\nLes couvre-chefs sont appréciés des aventuriers, que cela soit un simple bandeau ou un casque fermé. Les bases de la création sont les mêmes, quelle que soit l'apparence du casque.", completion = "L'équipement de la nuit que vous m'avez fourni respecte parfaitement les critères que je vous avais donnés, &lt;nom&gt;. Je n'en attendais pas moins d'un artisan du cuir tel que vous.\n\nVous avez bien gagné le patron du casque en cuir sauvage. Je vous le donne en espérant que vous en tirerez de bons profits.", rewards = "Vous recevrez :\n\nPatron : Casque en cuir sauvage"},
[2858] = {title = "Les bottes en cuir sauvage", objective = "Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Jangdor Swiftstrider au Camp Mojache.", description = "Vous avez déjà beaucoup appris, <nom>. Mais ce n’est pas tout. L'étape suivante concerne les bottes en cuir sauvage.\n\nElles protègent bien les pieds tout en restant confortables. Les semelles souples sont une bénédiction pour ceux qui aiment se déplacer discrètement.\n\nPour ces bottes, j'ai besoin de deux pantalons de la nuit et deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, nous continuerons.", progress = "Les pantalons, les bottes et les sauvageonnes doivent m'être livrés avant d’apprendre le patron, <nom>. Avez-vous terminé ce que je vous ai demandé ?\n\nDepuis la première paire que nous avons confectionnée, nous avons compris que des bottes parfaites étaient un savant équilibre entre fonction et confort. Nous pouvons créer des bottes qui, contrairement à d'autres de moins bonne qualité, permettent au porteur d'ignorer la fatigue lorsqu'il les porte.", completion = "Une fois de plus, vous avez produit ces objets avec le talent d'un vrai professionnel. Vous avez gagné ce patron, ainsi que mes félicitations.", rewards = "Vous recevrez :\n\nPatron : Bottes en cuir sauvage"},
[2859] = {title = "Les jambières en cuir sauvage", objective = "Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Jangdor Swiftstrider au Camp Mojache.", description = "Vous pouvez maintenant apprendre des techniques plus complexes, <nom>. Les jambières en cuir sauvage sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l'utiliseront apprécieront grandement cette protection combinant l'amélioration apportée par la sauvageonne.\n\nPour ce modèle, j'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.", progress = "Vous avez déjà fini les brassards et les casques en écailles de tortue ? N'oubliez pas les sauvageonnes dont j'ai besoin.\n\nVous commencez maintenant à réaliser la puissance potentielle de l'armure en cuir sauvage. Une telle qualité est inestimable. La seule limite est la quantité de matières premières disponibles, et non la qualité du produit fini !", completion = "Une fois de plus vous avez accompli votre mission sans faillir. Peut-être qu'un jour c’est moi qui viendrai apprendre auprès de VOUS, &lt;nom&gt; !\n\nVoici les patrons pour les jambières, avec mes remerciements. Ajoutez ce savoir à vos talents et réalisez des œuvres dignes de vous !", rewards = "Vous recevrez :\n\nPatron : Jambières en cuir sauvage"},
[2860] = {title = "Maître du cuir sauvage", objective = "Donner la Lettre de Jangdor à Una, le Maître tanneur de Thunder Bluff.", description = "<nom>, vous avez appris tout ce que je pouvais vous enseigner. Il reste néanmoins un dernier élément de l’armure en cuir sauvage à apprendre. Je ne vous demanderai rien pour celui-là, vous l'avez mérité. Mais je ne peux vous le donner.\n\nMon maître est la seule personne à pouvoir vous l’enseigner. Donnez cette lettre à Una, elle enseigne le travail du cuir à Thunder Bluff. Montrez-lui la lettre et laissez-la vous reconnaître comme son égal, ainsi que je l'ai fait.", progress = "Salutations, mort-vivant… Je vois que vous travaillez le cuir comme je le fais. Venez-vous apprendre ou avez-vous besoin d'autre chose ?", completion = "Ah ! Jangdor vous envoie. Je suis contente de constater que l'un de mes meilleurs élèves enseigne à son tour.\n\nSa passion et son talent pour le travail du cuir sont impressionnants. Je respecte d'autant plus son avis vous concernant.\n\nJe sais qu'il vous a enseigné l'art du cuir sauvage. Permettez-moi de terminer votre formation. Faites-en bon usage, car rares sont ceux qui connaissent le secret de la cape en cuir sauvage.", rewards = "Vous recevrez :\n\nPatron : Cape en cuir sauvage"},
[2861] = {title = "La mission de Tabetha", objective = "Parler à Tabetha dans le marécage d'Âprefange.", description = "La rumeur dit que Tabetha, une collègue mage qui vit loin dans le marécage d'Âprefange, a un compte à régler avec un certain troll des sables à Zul'Farrak. Si vous parlez à Tabetha, elle pourra vous en dire davantage.\n\nEt invitez quelques amis, <nom>. Si Tabetha vous envoie à Zul'Farrak, il ne faut pas y aller <tout seul/toute seule>.\n\nVous trouverez le cottage de Tabetha à l'ouest de Theramore, juste au nord des ruines Cognepierres.", progress = nil, completion = "C'est vrai, j'ai un problème avec un troll. Et j’aimerais éliminer le problème et le troll avec.\n\nPourriez-vous m'aider ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2862] = {title = "La guerre avec les Griffebois", objective = "Rapporter 10 Crinières de gnolls Griffebois à Hadoken Swiftstrider au Camp Mojache.", description = "Les gnolls… Ils sont plus qu'une nuisance. Ils sont une menace constante pour ce campement ! Qu'ils soient natifs de Feralas ou non n'a aucune importance, si nous ne prenons pas bientôt des mesures appropriées contre eux, nous serons balayés de la région.\n\nLes attaques contre le camp sont de pire en pire. Nous avons besoin de votre aide pour réduire leur nombre. Ramenez-moi dix crinières et je vous récompenserai de vos efforts.\n\nAllez !", progress = "Nous les avons repoussés et ils continuent d'attaquer ! Il doit y avoir quelque chose ou quelqu'un qui les rend fous… Vous êtes là, <nom> ? Avez-vous les crinières ?", completion = "C'est un bon début, &lt;nom&gt;. Vos talents de soldat sont admirables.\n\nJ'ai déjà donné cette mission à d'autres. Beaucoup l'ont remplie et cela permettait de repousser les gnolls. Mais récemment, leurs attaques contre nos positions au nord se sont faites plus nombreuses, plus sauvages... comme désespérées.\n\nJ'ai un plan, &lt;nom&gt;, qui permettrait de résoudre ce problème une bonne fois pour toutes.", rewards = "Vous recevrez :\n\n"},
[2863] = {title = "Frappe sur les Alphas", objective = "Tuer 5 Alphas Griffebois et retourner voir Hadoken Swiftstrider en moins d'une heure.", description = "Le plan concerne divers chefs gnolls - les Alphas pour reprendre leur propre appellation - et leur élimination successive en un minimum de temps. Si nous pouvions exécuter ce genre d'éradication rapide et précise contre eux, cela amènerait le chaos dans leurs rangs. Et peut-être que le message passerait même à l'intérieur de leurs têtes épaisses et infestées de puces que nous pouvons et allons les détruire !\n\nJe veux que vous soyez <le messager/la messagère> de ma volonté. Eliminez cinq de leurs Alphas en une heure pour cette mission, <nom>, ou nous resterons dans l'impasse.", progress = nil, completion = "Vous avez rempli la mission. Je salue votre réussite et vous prie d'accepter cette modeste récompense comme prix de vos efforts, &lt;nom&gt;.\n\nAvec leurs effectifs réduits et leurs chefs tués, les gnolls vont réfléchir à deux fois avant d'attaquer. Mais cela ne résout pas le problème...\n\nIl doit y avoir une raison qui les a conduits à se comporter ainsi. Avant qu'ils ne puissent se réorganiser, je veux que vous trouviez ce qui les pousse à agir ainsi.", rewards = "Vous recevrez :\n\n"},
[2864] = {title = "Tran'rek", objective = "Parler à Tran'rek à Gadgetzan.", description = "Mon cousin Tran'rek me pose un problème. Il m'a promis une cargaison de carapaces de Scarabées il y a quelques semaines, et je n'ai toujours rien reçu. C’est mon cousin, je n'aimerais donc pas le rappeler méchamment à l’ordre.\n\nPouvez-vous lui parler avant que je ne commette un acte regrettable ? Dites-lui que j'ai vraiment besoin de cette cargaison.\n\nGadgetzan est dans le nord de Tanaris, en Kalimdor.", progress = nil, completion = "Bonjour ! Avez-vous parlé avec mon cousin Krazek ? Comment va-t-il ? J'espère qu'il se plaît à Baie-du-Butin…\n\nDes carapaces de Scarabées, vous dites ? Bien… Permettez-moi de vous raconter quelque chose…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2865] = {title = "Les carapaces de Scarabées", objective = "Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan.", description = "Les scarabées de Tanaris ont une carapace très dure ! Si dure qu’elle est utilisée dans de nombreux domaines.\n\nEn fait ces carapaces sont si utiles que les scarabées ont presque disparu !\n\nJe sais où trouver des scarabées, mais vous devez me promettre de ramener leurs carapaces. Promis ?\n\nOK, les scarabées ont une colonie à Zul'Farrak. Je pense que les trolls ne les chassent pas pour leurs carapaces.\n\nMais vous si ! Allez à Zul'Farrak et trouvez-moi ces carapaces intactes !", progress = "Vous avez les carapaces ? Mon cousin de Baie-du-Butin les attend et il s'impatiente !", completion = "Fabuleux ! Vous les avez !\n\nMerci, &lt;nom&gt;. Vous me sauvez la vie !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2866] = {title = "Les ruines de Solarsal", objective = "Explorer les ruines de Solarsal et enquêter sur la présence des nagas dans le secteur.", description = "Au sud se trouvent les ruines de Solarsal, un site bien antérieur à l'ère moderne. Nous avons exploré ces ruines et rien trouvé, aussi les avons-nous délaissées.\n\nTrès récemment, les nagas Hainecrête se sont installés en nombre dans les ruines. Au début, nous pensions à une attaque. Bien que cela soit toujours possible, nous croyons qu'il s'agit d'autre chose.\n\nAllez là-bas, explorez les ruines et rendez compte de tout ce qui vous paraîtra inhabituel. Bonne chance, <nom>.", progress = nil, completion = "L'examen du belvédère révèle des choses intéressantes et inhabituelles par rapport aux autres ruines.\n\nD'abord, la construction est beaucoup plus récente que le reste du site. Ensuite, ses côtés sont gravés d’une petite série de glyphes. La séquence des glyphes est répétitive, leur signification et leur origine inconnues. Troisièmement, la pierre du belvédère est chaude au toucher.\n\nCela le distingue clairement des autres ruines !", rewards = "Vous recevrez :\n\n"},
[2867] = {title = "Retourner au bastion de Feathermoon", objective = "Retourner voir Shandris Feathermoon au bastion de Feathermoon et lui rendre compte de vos découvertes.", description = "Après la découverte du belvédère étrange au cœur des ruines de Solarsal, il est temps de retourner au bastion de Feathermoon et faire votre rapport au général Shandris Feathermoon.", progress = nil, completion = "Soyez de nouveau le bienvenu, &lt;nom&gt;. Votre rapport concernant ce belvédère est très… dérangeant. Il semblerait, même si les nagas qui s'y trouvent ne préparaient pas une attaque, que leur présence soit de mauvais augure pour notre progression dans Feralas. En tout cas, voici une compensation pour votre enquête.\n\nJ'ai bien peur que le bastion de Feathermoon ait grand besoin d'une aide supplémentaire à propos des nagas Hainecrête. J'aimerais que vous vous en chargiez, si vous le voulez bien. Il y a beaucoup à faire.", rewards = "Vous recevrez :\n\n"},
[2869] = {title = "Contre les Hainecrête", objective = "Rapporter 10 Ecailles de naga Hainecrête à Latronicus Moonspear au bastion de Feathermoon.", description = "La meilleure approche est de penser, indépendamment du projet réel des nagas, qu'ils tentent de prendre possession de l'île. Nous devons réagir énergiquement avant qu'il ne soit trop tard.\n\nRapportez-moi dix écailles de Hainecrête en bon état ; pas besoin de vous expliquer comment vous les procurer. Vous diminuerez leur puissance et affaiblirez leur présence sur l'île de Sardor, ce qui joue en notre faveur.", progress = "<nom>, si vous êtes ici pour confirmer la mission que je vous ai confiée, très bien : j'ai besoin de dix écailles de Hainecrête. Si vous êtes ici pour discuter, je n'ai pas le temps.\n\nApprenez ceci : les elfes de la nuit ne sont pas des foudres de guerre. Notre race est vouée à la préservation, à la paix et à l'harmonie. Mais cela ne veut pas dire que nous ne défendons pas activement nos intérêts. C'est mon devoir vis-à-vis du général Feathermoon et du Bastion.", completion = "Oui, oui, ces écailles sont plus que satisfaisantes ! Je pense même les envoyer à Pratt afin qu'il les examine. Peut-être qu'il peut en faire quelque chose d'utile.\n\nJ'ai une autre mission à vous confier. Mais d'abord voici votre récompense pour les écailles. Votre engagement auprès du général et du bastion de Feathermoon en général est une bénédiction en ces temps troublés.", rewards = "Vous recevrez :\n\n"},
[2870] = {title = "Contre le Seigneur Shalzaru", objective = "Eliminer le seigneur Shalzaru et rapporter la mystérieuse relique qu'il a découverte à Latronicus Moonspear au bastion de Feathermoon.", description = "<nom>, de nouveaux rapports nous donnent une bonne idée de la chaîne de commandement des nagas. Parmi le tout-venant se trouve des individus de sang royal, et ce sont eux qui prennent toutes les décisions.\n\nNous avons identifié l'un de ces nobles, le seigneur Shalzaru. Nos agents disent qu'il a découvert une relique étrange au cours de fouilles récentes qu’il a menées dans une caverne au sud des ruines principales, sur l'île de l'Effroi.\n\nArrêtez les autres en neutralisant Shalzaru et rapportez-moi sa relique afin que nous puissions l'étudier.", progress = "L'élimination du Seigneur Shalzaru retardera certainement leurs plans de plusieurs semaines, voire plusieurs mois. De plus, la relique qu'il a découverte nous intéresse fortement.\n\nAvez-vous accompli votre mission, <nom> ?", completion = "Bien joué, &lt;nom&gt; ! La disparition du seigneur Shalzaru va perturber les nagas pendant quelque temps, si ce n'est définitivement. Grâce à vous, la menace qu'ils représentent est désormais sous contrôle.\n\nVoilà une autre récompense venant du trésor de la Forteresse. Vous et les vôtres serez toujours les bienvenus à la Forteresse.\n\nUne dernière chose avant que vous ne partiez, &lt;nom&gt;... si vous pouviez...", rewards = "Vous recevrez :\n\n"},
[2871] = {title = "Livraison de la relique", objective = "Porter la Relique mystérieuse à Vestia Moonspear au bastion de Feathermoon.", description = "Si vous étiez assez aimable de porter la relique à ma femme Vestia, je vous en serai très reconnaissant. Elle n'est pas seulement une excellente prêtresse, elle fait également partie des meilleurs érudits que vous puissiez trouver. Je n'arrive pas à comprendre l’usage de cet objet. Si quelqu'un peut le savoir, c'est ma femme... et nous avons besoin de savoir de quoi il s'agit !\n\nElle est juste derrière le virage, sûrement en train d'étudier. Merci, <nom>.", progress = "Oui, puis-je vous aider ?\n\nUne minute, <classe>, c'est vous qui avez aidé le général Feathermoon et Latro à nous débarrasser de la menace naga ? Je suis Vestia, la femme de Latro, euh… excusez-moi, de Latronicus. C'est un plaisir de vous rencontrer. Auriez-vous quelque chose pour moi par hasard ?", completion = "Intéressant… Vous dites que cela vient des ruines de Solarsal ? Eh bien, Latro a raison de dire que je dois y jeter un œil ! Au premier abord, cela ne semble pas appartenir aux ruines. Mais il ne s'agit pas de l'œuvre des nagas… C'est beaucoup trop étrange pour cela.\n\nJe vais avoir besoin de temps pour l'étudier. Une fois que j'aurai terminé, j'aurai peut-être besoin de vos talents, si vous êtes dans les environs.\n\nTenez, prenez l'un de ces objets. J'espère que vous en trouverez l'utilité.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPlastron du cavalier de l'aubeCasque de sentinelle\n\nVous recevrez également :\n\n"},
[2872] = {title = "Les dettes de Stoley", objective = "Parler à Stoley, à Port Gentepression.", description = "Mon vieux copain Stoley me doit une bouteille d’un rhum très spécial. Il tient un bar à Port Gentepression. C'est dans Tanaris, en Kalimdor. Il soutient que ce rhum est plus fort que tout ce que l'on peut trouver à Baie-du-Butin. Il y croit dur comme fer. À tel point que si je ne suis pas de son avis après avoir goûté cet alcool, je double ce qu'il me doit !\n\nJe pense que depuis la dernière fois, il a perdu confiance, car il ne m’a toujours pas envoyé son fameux rhum à goûter. Un pari est un pari, je ne reviendrai pas dessus. Pourquoi n'iriez-vous pas lui parler un peu ?", progress = nil, completion = "Vous avez causé à MacKinley, c'est ça ?\n\nCe n'est pas ce qu'il pense ! Je n'ai pas peur de lui envoyer du rhum de cale Gentepression…\n\nC'est juste que je n'en ai plus !", rewards = "Vous recevrez :\n\n"},
[2873] = {title = "Chargement de Stoley", objective = "Apporter le Chargement de Stoley à Port Gentepression et remettez-le à Stoley.", description = "Je dois du rhum à MacKinley \"Loup des mers\" pour payer une dette de jeu, mais je n'en ai plus ! Le capitaine Cuergo a volé ma dernière caisse et il l'a entreposée dans cette ville de pirates fortifiée, au sud.\n\nSi vous pouviez rapatrier ma cargaison de rhum, alors je pourrais prouver à MacKinley que la gnôle de Kalimdor est autrement plus musclée que le petit-lait qu'ils boivent à Baie-du-Butin.", progress = "Avez-vous retrouvé mon rhum, <nom> ?", completion = "Excellent, merci pour la livraison ! Maintenant MacKinley et moi allons enfin pouvoir en finir avec ce pari.", rewards = "Vous recevrez :\n\n"},
[2874] = {title = "Livraison à MacKinley", objective = "Porter la Bouteille de Stoley à MacKinley \"Loup des mers\" à Baie-du-Butin.", description = "Merci de votre aide, <nom>. Voici une bouteille de rhum de cale Gentepression. Portez-la à MacKinley et il pourra remballer ses préjugés à propos des alcools de Baie-du-Butin.", progress = "Est-ce que Stoley a ma gnôle ?", completion = "Voyons cela…\n\nArgh… J'y crois pas ! Ce truc est… fantastique ! Fabuleux !\n\nStoley peut garder l'argent qu'il me doit. Il a dit vrai à propos du rhum de cale Gentepression. Ce truc est aussi épais que du gravier et brûle comme de la lave !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe de bretteurBottes Shinkicker\n\nVous recevrez également :\n\n"},
[2875] = {title = "ON RECHERCHE : André Barbe-en-feu", objective = "Rapporter la tête d'André au Chef de la sécurité Bilgewhizzle à Port Gentepression.", description = "Le vil pirate André Barbe-en-feu est recherché pour crimes contre Gentepression et Gadgetzan.\n\nPar décret du conseil gouvernemental, quiconque lit ceci est autorisé à utiliser la force, et à tuer si nécessaire, pour procéder à l'arrestation de André et de ses complices.\n\nPar un autre décret, si André était décédé ou indisposé pendant son interrogatoire, sa tête servirait de preuve et la présentation de ladite tête au Chef de la sécurité Bilgewizzle constitue un contrat valable et inaliénable.", progress = "Vous avez l'air bizarre. Vous lisez nos publications légales ?", completion = "Ah, la tête d'André ! Je vois qu'il est finalement passé en jugement !\n\nJ'apprécie, &lt;nom&gt;. Maintenant, signez ici que je puisse vous payer pour services rendus.\n\nNe vous inquiétez pas des petits caractères. Ils sont sans signification et… Non, je ne pense pas qu'il y ait de loupe assez puissante pour les lire.", rewards = "Vous recevrez :\n\n"},
[2876] = {title = "Horaires des bateaux", objective = "Rapporter le Planning des expéditions aux autorités de Port Gentepression.", description = "Ce parchemin répertorie les cargaisons envoyées entre Port Gentepression et Baie-du-Butin. La liste contient le nom des navires et des dates, passées ou à venir. Certaines lignes sont cochées d’un grand X. D'autres sont annotées avec \"Bon butin\" ou \"Dur combat\".\n\nQuelqu'un à Port Gentepression apprécierait certainement de voir ce document.", progress = "Reprenez votre souffle. Vous avez quelque chose à me dire ?", completion = "Oh mon d... ! C’est une liste des départs et arrivées des bateaux, avec des dates et des horaires précis ! Si un capitaine pirate mettait la main dessus, il aurait gagné sa journée !\n\nVous dites avoir pris cela à un pirate ? C'est inquiétant...\n\nMerci, &lt;nom&gt;. Je suis heureux que vous le lui ayez repris, et je me réjouis encore plus de savoir qu'il sympathise avec les asticots, en ce moment !", rewards = "Vous recevrez :\n\n"},
[2877] = {title = "Nettoyer le rocher de l'Affût", objective = "Tuer 10 Limaces vertes et 10 Limons de jade puis faire votre rapport à Fraggar Thundermantle au Nid-de-l'Aigle", description = "Nous, les Wildhammer, nous souvenons du passé, mieux que nos frères d'Ironforge. Si vous désirez vous faire des amis, alors travaillez pour nous !\n\nLa Horde a abandonné ses positions dans les Hinterlands, autour du rocher de l'Affût qui est maintenant envahi par des Limaces et des Limons. Nous avons des plans pour ce secteur, mais nous avons besoin de quelqu'un pour faire du nettoyage.\n\nC'est là que vous intervenez ! Allez là-bas et liquidez dix Limaces vertes et dix Limons de jade puis revenez me faire votre rapport ici. Exécution !", progress = nil, completion = "Regardez ça, vous aidez les Wildhammer, &lt;classe&gt; ! Vous aimez l'action et nous respectons l'action par-dessus tout.\n\nVotre petit nettoyage est bien plus important que vous ne le pensez. Avec moins de Limaces et de Limons, nous allons tout de suite pouvoir augmenter notre sphère d'influence. Voici un petit quelque chose, en plus du fait d'avoir de nouveaux amis ici, au Nid-de-l'Aigle !", rewards = "Vous recevrez :\n\n"},
[2878] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[2879] = {title = "Le Bâton d'Equinex", objective = "Dynamiser le Bâton de Troyas et trouver le Monolithe d'Equinex.", description = "Il semble que ce bâton soit le Bâton d'Equinex. C'est une clé qui permet d'ouvrir le Monolithe d'Equinex qui est érigé dans les ruines de Vent-du-Corbeau, sur le continent, à l'ouest du Bosquet du rêve.\n\nLocalisez les quatre flammes qui brûlent toujours dans les ruines: Samha, Imbel, Byltan et Lahassa. Là, retrouvez leur essence et pendant que vous êtes près du Monolithe, utilisez cette essence pour dynamiser le Bâton d'Equinex. Vous pourrez alors ouvrir le Monolithe et prendre l'artefact sacré qui s'y trouve.", progress = "Le Monolithe d'Equinex se dresse silencieusement au milieu des ruines. Que peut-il abriter ?", completion = "Tenir le bâton dynamisé est pratiquement impossible. Sa puissance résonne à travers votre corps.\n\nVous atteignez la surface froide du Monolithe…\n\nUne petite porte s'ouvre, vous permettant d'entrer et de prendre l'artefact qui se trouve à l'intérieur.\n\nDes rayons lumineux baignent le Monolithe d'Equinex.", rewards = "Vous recevrez :\n\nUne Pierre étincelante"},
[2880] = {title = "Chasse au collier troll", objective = "Rapporter 5 Colliers tribaux trolls à Fraggar Thundermantle au Nid-de-l'Aigle", description = "Comprenez bien ceci, <nom>. Nous ne faisons PAS partie de l'Alliance ! Les Wildhammer sont indépendants, ils prouvent leur valeur par l'action et leurs actes et non en bavardant, contrairement à ceux qui parlent afin de camoufler leur passivité !\n\nSi vous cherchez des amis par ici, commencez par prouver votre valeur ! Ces idiots de trolls qui remplissent les Hinterlands portent parfois des colliers tribaux. Rapportez-en cinq et nous considérerons que vous avez fait un pas dans la bonne direction.", progress = "Je veux cinq de ces colliers tribaux que les trolls portent sur eux. Au cas où vous ne l'auriez pas compris, tuer un troll vous permettra sûrement d'en obtenir un !\n\nMontrez votre valeur aux Wildhammer !", completion = "Voilà ce dont je parlais ! Ces colliers prouvent que vous voulez travailler pour nous. Nous, les Wildhammers, respectons nos alliés.\n\nContinuez ainsi et vous entrerez dans nos bonnes grâces.", rewards = "Vous recevrez :\n\n"},
[2881] = {title = "Chasse aux colliers trolls", objective = "Vous l'avez déjà fait, mais nous continuerons d'accepter tous les Colliers tribaux que vous trouverez. En me les donnant, vous continuerez d'accroître votre prestige parmi les Wildhammer ; si vous désirez vous battre pour nous, nous pourrons nous battre pour vous !\n\nJ'ai besoin de cinq colliers tribaux trolls, <nom>.", description = nil, progress = "Vous l'avez déjà fait, mais nous continuerons d'accepter tous les Colliers tribaux que vous trouverez. En me les donnant, vous continuerez d'accroître votre prestige parmi les Wildhammer ; si vous désirez vous battre pour nous, nous pourrons nous battre pour vous !\n\nJ'ai besoin de cinq colliers tribaux trolls, <nom>.", completion = "Une autre série de colliers veut dire qu'il y a moins de trolls pour nous inquiéter dans les Hinterlands ! Vous avez bien travaillé, &lt;nom&gt;. Continuez dans cette voie !", rewards = nil},
[2882] = {title = "L'or de Cuergo", objective = "Trouvez l'or de Cuergo !", description = "Cette carte montre une plage orientée au sud. Sous la carte, des mots élégamment tracés…\n\nAu sud de Gentepression, avec raison\n\nAu sud de la maison\nTrouvez un drapeau, un mât et des os\nCreusez ici, si vous l'osez\nCreusez et gagnez l'or de Cuergo !\nUne clé il faut et une clé vous verrez\nLes hommes d'en face il faudra tuer.", progress = "Ce coffre est fermé à clé !", completion = "Le trésor caché du capitaine Cuergo attend !", rewards = "Vous recevrez :\n\nTrésor caché de Cuergo"},
[2902] = {title = "Enquête chez les Griffebois", objective = "Trouver les Plans de bataille des gnolls dans les camps gnolls du sud du Camp Mojache.", description = "Les gnolls ne sont pas des lumières, mais ils ont certainement des documents concernant leurs récents agissements. Si nous trouvions des plans, alors nous aurions une meilleure idée de ce qui les motive.\n\nJe veux que vous retourniez chez les Griffebois et que vous rapportiez tout ce qui ressemble à un plan de bataille. Ils doivent avoir quelque chose, leurs attaques sont trop coordonnées. Trouvez les plans de bataille et rapportez-les-moi.", progress = nil, completion = "Un examen de la carte révèle qu'il s'agit des plans de bataille que cherche Hadoken Swiftstrider. De nombreuses flèches représentant probablement des mouvements de troupes sont dessinées, la plupart pointent vers le sud alors que le Camp Mojache est au nord.\n\nSur une autre page, un croquis représente ce qui vous paraît être un gros insecte, annoté de chiffres. Il vous semble qu'il s'agit des pertes des gnolls face aux mystérieux insectes....", rewards = "Vous recevrez :\n\n"},
[2903] = {title = "Les plans de bataille", objective = "Rapporter les Plans de bataille des Griffebois à Hadoken Swiftstrider au Camp Mojache.", description = "Une fois trouvés les plans des gnolls, il reste à les porter à Hadoken Swiftstrider au Camp Mojache. Peut-être comprendra-t-il les projets des gnolls…", progress = "Bon retour parmi nous, <nom>, avez-vous trouvé des preuves tangibles des plans des gnolls ?", completion = "C'est exactement ce dont nous avions besoin ! Bien que je n'aie pas les connaissances pour comprendre la signification de ces dessins, j'ai vu suffisamment de plans de bataille dans ma vie pour comprendre de quoi il s’agit. Il semble que les gnolls mènent actuellement une guerre sur deux fronts. Le premier, c'est nous... Mais leur front principal est contre un ennemi au sud.\n\nIl y a encore des choses à éclaircir. Nous devons en savoir plus sur leur ennemi.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBarrière naturelleBottes Rushridge\n\nVous recevrez également :\n\n"},
[2904] = {title = "Une jolie pagaille", objective = "Escorter Kernobee jusqu’à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin.", description = "<Kernobee grogne>Qu… Que s'est-il passé ?\n\nLa dernière chose dont je me souviens est d'avoir été capturé par un groupe de nains Sombrefer, d'avoir été battu comme plâtre et jeté ici avec ces troggs crasseux.\n\nSortez-moi de là, <nom> !\n\nVoici le plan : vous me conduisez à la sortie, si nous survivons, vous allez à Baie-du-Butin prévenir Scooty que je suis allé à Ratchet pour informer Tinkerwiz de l'implication des Sombrefer dans la conception de cette super plate-forme.\n\nAllons-y !", progress = nil, completion = "Je suppose que vous devriez recevoir une récompense pour nous avoir ramené Kernobee en un seul morceau, &lt;nom&gt;. Si vous repassez par Gnomeregan, ceci vous permettra de prendre l'ascendant nécessaire pour battre ce traître de bon à rien de mekgénieur Thermaplugg.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards soudésMantelet Aile-de-fée\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2922] = {title = "Sauver le cerveau de Techbot !", objective = "Rapporter la Mémoire principale de Techbot au maître-artisan Overspark à Ironforge.", description = "Lorsque notre cité bien-aimée de Gnomeregan est tombée, une étincelle a fait disjoncter ma pauvre création, le Techbot. Il nous aidait bien, moi et mes associés, avec ses nombreux gadgets et ses banques d'informations illimitées, mais son cerveau positronique a été polarisé. Techbot est maintenant négatronique et son comportement s'est inversé. Il erre, enragé, dans Gnomeregan !\n\nMais peut-être peut-il être sauvé. Si vous retrouviez sa mémoire principale et me la rapportiez, je pourrais découvrir la cause de la polarisation et réparer mon pauvre Techbot.\n\n", progress = "Avez-vous trouvé Techbot ? Avez-vous pu récupérer sa mémoire principale ?", completion = "C'est merveilleux ! Merci, &lt;nom&gt; ! Je me mets au travail immédiatement !\n\nPauvre, pauvre Techbot… Tout ira bien, tu seras bientôt réparé.\n\nOù ai-je mis cette prise pour ma clé à molette hydraulique ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2923] = {title = "Maître-artisan Overspark", objective = "Parler au maître-artisan Overspark à Ironforge.", description = "Le maître-artisan Overspark est très contrarié par la perte de sa création mécanique, le Techbot. Je me souviens du Techbot comme d’une machine gentille et serviable, très utile aux gnomes, mais Overspark dit qu'il a eu des problèmes de fonctionnement.\n\nVraiment dommage, mais avec de la chance, cela pourrait être réparé !\n\nParlez avec maître Overspark, à Brikabrok, le quartier gnome d'Ironforge. Votre aide sera la bienvenue.", progress = nil, completion = "Oui, c'est exact. Techbot est devenu fou ! S'il vous plaît, pouvez-vous m'aider ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2924] = {title = "Les cerveaux mécaniques", objective = "Rapporter 12 Cerveaux mécaniques à Klockmort Spannerspan à Ironforge.", description = "Un composant pratiquement universel, le cerveau mécanique, est d'une grande utilité pour les artisans et les forgerons de Gnomeregan. Mais durant notre exode, personne n'a pensé à en emporter ! Et j'en ai besoin d'un grand nombre pour le travail que je vais bientôt accomplir.\n\nS'il vous plaît, allez à Gnomeregan et rapportez-en. Vous les trouverez dans les profondeurs de notre cité, dans des conteneurs appelés des extrapolateurs artificiels.\n\nMerci, <nom> et dépêchez-vous !", progress = "Vous avez les cerveaux mécaniques ?", completion = "Vous les avez ! Maintenant je peux commencer mes nouvelles expérimentations !\n\nComment puis-je vous remercier, &lt;nom&gt; ? Votre courage a permis à la recherche gnome de faire un grand bond en avant !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2925] = {title = "Les cerveaux mécaniques de Klockmort", objective = "Parler à Klockmort Spannerspan à Ironforge.", description = "Un ami gnome, Klockmort Spannerspan m'a écrit depuis Ironforge. Il me dit qu'il a besoin d'aide pour une mission dangereuse, mais vitale à Gnomeregan, l'ancienne et puissante cité gnome, aujourd’hui contaminée et envahie de gnomes fous et de leurs inventions.\n\nJe dois rester ici, mais je dois aider mon ami. Si vous pouviez y aller à ma place, je serais votre débiteur.\n\nVous pouvez trouver Klockmort à Brikabrok, le quartier gnome d'Ironforge.", progress = nil, completion = "Oui ! J'ai besoin d'aide pour une mission dans Gnomeregan. Et vous m'avez l'air d'être la personne qu'il me faut, &lt;classe&gt; !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2926] = {title = "Gnogaine", objective = "Utiliser la Fiole de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Togglevolt à Kharanos.", description = "Depuis l'accident, Gnoarn discute et palabre sur le fait de nettoyer Gnomeregan de l'infestation des troggs et de trouver un remède à la maladie, <nom>.\n\nPar chance, Razzle et moi sommes près de trouver quelque chose, un remède ou une recette de rhum particulièrement corsée, nous ne sommes pas sûrs… Nous le saurons après les tests ! Nous avons bien évidemment besoin de quelques ingrédients pour tester notre produit, notamment des retombées radioactives collectées sur des troggs irradiés de Gnomeregan. Remplissez cette fiole avec la Lueur verte et rapportez-la.", progress = "Vous ne voyez pas que nous essayons de guérir la race gnome toute entière ? Nous avons besoin de plus de Lueur verte !", completion = "Très bon travail ! Il est temps de tester notre nouvelle formule. Si cela marche, non seulement ce gnome lépreux sera guéri, mais j'aurai de nouveaux cheveux ! Reculez !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2927] = {title = "Le jour d'après", objective = "Parler à Ozzie Togglevolt à Kharanos.", description = "Vous ne pensiez quand même pas que j’aie toujours été chauve ? Non <m’sieur/ma'am> ! C'est la fuite radioactive à Gnomeregan qui a causé cette tragique perte de cheveux. Avant cela, j'avais la seule coiffure afrognome de tout Azeroth.\n\n<Gnoarn brandit le poing vers le ciel>\n\nMaudits soient ces troggs crasseux, qu'ils soient tous maudits !\n\nPeut-être qu'il n'est pas trop tard, <nom>. Nous pouvons peut-être encore la sauver, je parle de la ville ! Allez voir Ozzie Togglevolt à Kharanos. Lui et Razzle, son partenaire, travaillent à résoudre ce problème.", progress = nil, completion = "Je pensais que la perte de sa chevelure spectaculaire signerait sa fin prochaine, mais il a survécu !\n\nJe me tenais près de lui lorsqu'il a été touché par le faisceau de radiation. Ses belles boucles sont tombées par poignées ! Le summum de l'horreur a été atteint lorsque Gnoarn a paniqué ! Oui, j'ai bien dit paniqué ! Il a passé la main sur son crâne chauve, les yeux remplis de haine, &lt;nom&gt; ! Puis il a tourné sa colère contre les troggs !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2928] = {title = "Excavateurs gyrodrilmatiques", objective = "Rapporter 24 Entrailles mécaniques de robot à Shoni à Stormwind.", description = "C'est affreux, <nom>. Nous n'avons pas suffisamment de pièces détachées pour notre flotte d'excavateurs gyrodrilmatiques à Dun Morogh.\n\nNous avons besoin de ces pièces, <nom>. Le meilleur endroit pour en trouver est Gnomeregan, mais j'ai entendu dire que les bots et les mechs grouillaient là-bas, comme les puces sur le dos d'un chien.\n\nVous devez aller à Gnomeregan et mettre en pièces quelques robots. Ramenez-moi des entrailles mécaniques. Deux douzaines devraient suffire.", progress = "S’il y avait eu une course, vous auriez perdu…", completion = "Ça ira parfaitement, &lt;nom&gt;. Un Excavateur gyrodrilmatique réparé, plus que 398.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOutil de désarmement de ShoniMitaines de Shilly\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2929] = {title = "La grande trahison", objective = "Aller à Gnomeregan et tuer le mekgénieur Thermaplugg. Puis retourner voir le Grand Bricoleur Mekkatorque.", description = "J'avais confiance en Thermaplugg, <nom>. Je ne pensais pas qu'il me trahirait, moi et tout le peuple gnome. Et pourquoi ? La puissance ? L'argent ? Toute chose qu'il aurait eu de toute façon. Maintenant nous avons été jetés hors de notre pays et ce malade est à sa tête. Le roi du vide...\n\nNous reprendrons Gnomeregan, <nom>. Nous n'arrêterons pas tant que la ville ne sera pas nôtre à nouveau. Si vous désirez vous joindre à nous, j'ai une mission simple à vous confier : tuer le traître. Détruisez le mekgénieur Thermaplugg.", progress = nil, completion = "J'aime à penser que la dernière chose qui lui a traversé l'esprit pendant qu'il s'écroulait sur le sol était votre pied, &lt;nom&gt;. Thermaplugg mort, nos plans de reconquête de Gnomeregan sont un pas plus proche de leur réalisation.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe civinadeChausses du coureurJambières à double renfort\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2930] = {title = "Sauvetage de données", objective = "Apporter une Carte perforée prismatique au Maître mécanicien Castpipe, à Ironforge.", description = "Quand nous avons fui Gnomeregan, nous avons dû abandonner tant de données importantes !\n\nJ'ai besoin des données de la carte perforée prismatique d'une Matrice d'encodage 3005-D, dans Gnomeregan. C'est votre destination ; mais pour cela, vous devez d'abord accéder aux terminaux de modèles -A, -B et -C. Et ceci n'est possible qu'avec les cartes prismatiques, en commençant par les blanches... Et nous avons laissé toutes nos cartes dans la ville.\n\nPouvez-vous nous aider ?", progress = "Avez-vous la carte perforée prismatique ?", completion = "Bravo ! Vous avez récupéré la carte et les données perdues qui sont, à vrai dire, d'une importance vitale pour nous !\n\nVotre engagement auprès des gnomes fera date, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCape de réparateurMarteau du mécanicien"},
[2931] = {title = "Du travail pour Castpipe", objective = "Parler au Maître mécanicien Castpipe, à Ironforge.", description = "Le maître-mécanicien Castpipe à Ironforge a besoin d'aventuriers ! Il organise des groupes pour pénétrer à nouveau dans Gnomeregan afin d'effectuer une mission de récupération de première importance.\n\nIl se peut que Castpipe ne soit pas membre des grandes Assemblées d'arcanologie, d'alchimie ou de sciences d'ingénieries comme je le suis, mais il reste un gnome intelligent. S'il considère que c'est important, alors mes calculs indiquent qu'il y a quatre-vingt pour cent de chance que ce soit véritablement important !\n\nIl s'agit là des probabilités les plus optimistes en ce qui nous concerne !", progress = nil, completion = "J'organise une opération de récupération de données à Gnomeregan. Si vous êtes venu pour ça, écoutez bien !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2932] = {title = "Sinistre message", objective = "Collecter les Crânes de Witherbark, et les mettre en place sur la Pique de Nimboyae. Placer la Pique de Nimboya préparée dans l’un des Villages Witherbark, dans les Hinterlands, puis retourner voir Nimboya, à Strangleronce.", description = "Les trolls Witherbark étaient jadis des alliés de la Horde, mais ils ont trahi Thrall... ce qui ne peut être toléré !\n\nVoici, prenez ma pique et allez dans les Hinterlands, loin au nord. Vous trouverez l'endroit en question au nord-est du Moulin-de-Tarren, un village tenu par nos alliés, les Réprouvés.\n\nQuand vous entrerez sur les terres des Hinterlands, chassez les trolls Witherbark. Collectez leurs crânes, puis plantez ma pique dans le sol de l'un de leurs petits villages, Hiri'watha ou Zun'watha.\n\nMontrez-leur que tout se paie en ce bas monde !", progress = nil, completion = "On parle beaucoup de votre fait, ici. Une action sinistre mais nécessaire. Espérons que les Witherbark auront compris votre message...", rewards = "Vous recevrez :\n\n"},
[2933] = {title = "Bouteilles de venin", objective = "Apporter une Bouteille de venin à un apothicaire, au Moulin-de-Tarren.", description = "Ces bouteilles contiennent un terrible venin.\n\nVu le nombre de bouteilles dans ce village, les Witherbark doivent projeter quelque chose d'important avec elles ; peut-être qu'un apothicaire, près du Moulin-de-Tarren, serait interéssé par l'étude d'un échantillon.", progress = "Salut, noble <classe>. Voilà longtemps que je n'ai pas réussi quelque expérience probante... J'espère que vous apportez de bonnes nouvelles.", completion = "Ah, qu'est-ce que c'est que ça ? On dirait le venin... d'une espèce d'araignée. Où avez-vous eu cela ?", rewards = "Vous recevrez :\n\n"},
[2934] = {title = "Glande à venin intacte", objective = "Rapporter une Glande à venin intacte à l'Apothicaire Lydon, au Moulin-de-Tarren.", description = "Il me faut un échantillon frais du venin que vous m'avez apporté. Les araignées dont il provient hantent les Hinterlands. Chassez-les jusqu'à ce que vous trouviez une glande à venin intacte, puis rapportez-la-moi. Vous trouverez beaucoup d'araignées près de la ville des trolls de Shadra'Alor.\n\nNe tardez pas, <nom>, la glande à venin doit être fraîche lorsque vous l'apporterez.", progress = "Avez-vous la glande à venin, <nom> ? J'ai hâte d'effectuer les expérimentations avec ce venin frais. J'ai une foule d'adorables petits cobayes qui attendent mes injections !", completion = "Oh merci, ce venin est parfaitement frais et sans doute extrêmement toxique. Merci !", rewards = "Vous recevrez :\n\n"},
[2935] = {title = "Consulter Maître Gadrin", objective = "Parler à Maître Gadrin au Village de Sen'jin.", description = "Le venin des gardes du clan n'était pas le même que celui que vous m'avez rapporté. Ils proviennent sans doute d'araignées différentes.\n\nJe veux un échantillon de venin frais. Pour savoir où en trouver, vous devez consulter un troll qui connaît bien les Witherbark : maître Gadrin, au village de Sen'jin. Allez en Durotar et parlez à Gadrin. Avec un peu de chance, il saura de quelle araignée les Witherbark tirent leur venin.", progress = nil, completion = "Ah, alors comme ça vous voulez du venin frais des araignées de Witherbarks, hein ? Asseyez-vous... Vous n'allez pas aimer ce que je vais vous dire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2936] = {title = "Le dieu-araignée", objective = "Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Witherbark, puis retourner voir Maître Gadrin.", description = "Les Witherbark adorent un dieu-araignée dont ils obtiennent ce venin extrêmement toxique. Ainsi, si vous voulez en collecter un peu, il vous faudra invoquer leur dieu !\n\nPour réussir l'invocation, vous devez connaître le vrai nom de cette divinité. Il est écrit sur une tablette, enterrée à Tanaris, dans la cité troll de Zul'Farrak. Dans une tombe gardée par Theka le Martyr, pour être plus exact.\n\nTuez Theka, trouvez et lisez la tablette pour connaître le véritable nom du dieu-araignée, puis revenez me voir.", progress = nil, completion = "Ah, Elortha no Shadra... Ne murmurez ce nom qu'avec crainte et défiance ; même dans le monde des esprits, il impose le respect.\n\nJe vais l'incorporer à un sort d'invocation que je laisserai sur parchemin...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2937] = {title = "L'invocation de Shadra", objective = "Terrasser Shadra, à l'autel de Shadra'Alor, puis rapporter son venin à l'Apothicaire Lydon, au Moulin-de-Tarren.", description = "Prenez ce parchemin et lisez-le devant l'autel de Shadra'Alor, loin à l'intérieur des terres des Witherbark, dans les Hinterlands. Shadra, le dieu-araignée sera invoqué et paraîtra.", progress = "Avez-vous le venin ?", completion = "Bravo, vous l'avez !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2938] = {title = "Du venin pour Undercity", objective = "Apporter le Colis de Faranell au maître apothicaire Faranell, à Undercity.", description = "Le venin que vous avez récupéré sur le dieu araignée des Witherbark est une grande découverte ! J'ai pu tuer près de deux douzaines de lapins avec une seule goutte. Il est juste que certains de ces lapins étaient très jeunes et suffisamment petits pour tenir dans la paume de la main. Leur résistance aux toxines devait être très basse. Néanmoins, il s'agit là d'un puissant poison !\n\nJ'aimerais en envoyer un échantillon à mon supérieur, l'apothicaire Faranell à l'Apothicarium d'Undercity. Il ne fait aucun doute qu'il aimerait conduire ses propres expériences.", progress = "On m'a prévenu de votre arrivée, <nom>. Vous avez un colis pour moi, n'est-ce pas ?", completion = "Très bien. Lydon m'a averti que le venin contenu dans ce colis était le plus toxique qu'il eût jamais testé et qu'il espérait en tirer d'intéressantes applications.\n\nAvec de la chance, il trouvera de quoi employer ce poison.\n\nMerci, &lt;nom&gt;. Votre contribution à la Société royale des apothicaires ne sera pas oubliée.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHabit de faveur royalePlastron de la garde d'honneurEgide de guerre\n\nVous recevrez également :\n\n"},
[2939] = {title = "En savoir plus", objective = "Parler à Daryn Lightwind, au village de Rut'theran.", description = "Bien que les Ruines de Feralas puissent être très dangereuses, elles ont beaucoup à raconter sur ce qui s'est passé ici.\n\nIl y a quelques jours, tandis que je fouillais les décombres, j'ai découvert ce qui semble être une douve classique. Je ne peux cependant pas me défaire de l'idée que cela cache quelque chose... Angelas et moi avons fait des recherches dans nos livres, mais nous n’avons rien découvert la concernant.\n\nJe connais une collègue à Darnassus qui pourrait peut-être nous dire de quoi il s'agit, <nom>. Pourquoi n'iriez-vous pas lui parler et voir si elle peut nous aider ?", progress = nil, completion = "Ainsi, c'est Troyas Moonbreeze qui vous envoie ?\n\n&lt;Marmonnements&gt;… n'arrête pas de me harceler, comme quoi il aurait découvert quelque chose d'important…\n\nÉcoutez, &lt;nom&gt;, je vais être franche. Troyas croit toujours avoir découvert quelque chose d'important dans ces ruines. Mais tout ce qui avait une véritable valeur a été ravagé depuis longtemps par les ogres et les harpies qui y vivent à présent.\n\nVous pouvez faire toutes les recherches que vous voulez ici, mais je doute que vous trouverez un livre pouvant vous en apprendre davantage.", rewards = "Vous recevrez :\n\n"},
[2940] = {title = "Feralas : une histoire", objective = "Demander à Daryn Lightwind si vous pouvez emprunter son livre.", description = "Ce livre à l'air de ne pas avoir été ouvert depuis des années. Sa couverture est passée et ses pages jaunies ; mais en l'examinant de plus près, vous remarquez que c'est exactement ce que Troyas devait rechercher.\n\nVous le prenez, puis réalisez que vous devriez d'abord demander la permission avant de l'emprunter.", progress = nil, completion = "Ainsi vous aimeriez emprunter \"Histoire de Feralas\" ?\n\nVoyons...\n\nJe vous prêterai ce livre, &lt;nom&gt;, mais seulement si vous faites un petit travail pour moi.", rewards = "Vous recevrez :\n\n"},
[2941] = {title = "Le prêt", objective = "Apporter la lettre à Curgle Cranklehop, à Tanaris.", description = "J'ai étudié beaucoup de thèmes et de sujets, et ma dernière étude porte sur la créature appelée Gueule d'acier qui vit sur les plages, dans les Hinterlands. Il y a en particulier un spécimen que j'aimerais voir, nommé Gammerita. Mes recherches me retiennent ici, hélas. Je pense qu'une image de la bête suffirait à son étude.\n\nPortez cette lettre à Curgle Cranklehop, à Tanaris. Elle a inventé une machine qui prend des images. Elle appelle cela : \"photographie\", je crois...", progress = "Une lettre... pour moi ?", completion = "Vous êtes un des internes de Daryn ? C'est une historienne très capable, &lt;nom&gt;. Vous devriez éprouver de la gratitude d'étudier sous sa direction.\n\nMaintenant, jetez un coup d'oeil sur le Preneur d'images FX. Vous allez adorer !", rewards = "Vous recevrez :\n\n"},
[2942] = {title = "La Pierre du matin", objective = "Rapporter la Pierre étincelante et le Bâton d'Equinex à Troyas Moonbreeze, dans le bastion de Feathermoon.", description = "Lorsque vous retirez l'artefact du Monolithe, vous sentez que l'énergie du Bâton d'Equinex commence à décliner.", progress = "Je suis bien aise de vous voir rentré, <nom>. J'ai hâte d'apprendre ce que vous avez trouvé.", completion = "J'ai étudié des livres pendant votre absence, &lt;nom&gt;. La pierre que vous avez trouvée s'appelle la Pierre du matin. Je ne sais pas encore exactement à quoi elle sert ; sachez cependant qu'un objet caché dans le Monolithe d'Equinex ne peut avoir qu'une énorme importance.\n\nJe vais poursuivre mes études, en espérant pouvoir compter sur vous dans l'avenir, &lt;nom&gt;. Merci de votre aide.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton de flamboyanceAnneau de concentration\n\nVous recevrez également :\n\n"},
[2943] = {title = "Troyas", objective = "Apporter le livre à Troyas Moonbreeze, dans le bastion de Feathermoon.", description = "Voilà, <nom>. Je vous en prie, prenez soin de mon livre.\n\nPartez, à présent. Je suis sûre que Troyas attend votre retour avec impatience.", progress = "Salut, <nom>. Avez-vous été à Darnassus ?", completion = "Vous avez rapporté un livre. Excellent !", rewards = "Vous recevrez :\n\n"},
[2944] = {title = "Le Preneur d'images FX", objective = "Utiliser le Preneur d'images FX pour prendre un cliché de Gammerita, puis retourner voir Daryn Lightwind à Rut'theran.", description = "Regardez ma dernière invention, <nom>. Tout ce que vous avez à faire est de viser puis d'appuyer sur ce bouton.\n\nQuelle était la créature des Hinterlands que vous avez mentionnée ? Gammerita ? Eh bien, bonne chance. Je suis sûre que Daryn sera contente du cliché que vous lui en ferez.\n\nVoici le Preneur d'images FX, faites-en bon usage et amusez-vous bien !", progress = "Vous êtes enfin de retour, <nom>. Et vous m'avez apporté ce que Curgle a construit pour moi. Parfait.", completion = "Bien ! L'invention de Curgle répond à nos attentes.\n\nNe vous emballez pas, mais sachez tout de même que je pense du bien de votre travail, &lt;nom&gt;.\n\nVoyons, où ai-je laissé ce livre...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2945] = {title = "Anneau sali", objective = "Trouver un moyen de nettoyer l'Anneau sali.", description = "Vous avez découvert, sur le corps d'un des nains Sombrefer, ce qui semble être un anneau. La crasse le recouvre entièrement, rendant difficile son identification et impossible son port. Il vous semble pouvoir discerner, sous les résidus, comme le chatoiement d'un métal précieux et l'éclat d'une gemme.\n\nSi vous voulez utiliser cet anneau, il vous faudra trouver un moyen de nettoyer la saleté qui le souille.", progress = "Le bidule gnomique porte une étiquette : \"Décapeur 5200\". La fonction de la machine, d'après ce que vous en lisez, est de nettoyer la crasse et la saleté recouvrant les objets. Elle comprend une fente, dans laquelle il faut jeter trois pièces d'argent pour déclencher le processus nettoyant l'objet qu'on a placé à l'intérieur.\n\nOn dirait que l'anneau que vous avez trouvé un peu plus tôt est le genre d'objet à soumettre à cette machine !", completion = "Vous placez l'anneau dans le Décapeur 5200 et jetez une pièce dans la fente.\n\nD'étranges grincements montent de la machine, qui commence à vibrer. Il est difficile d'imaginer le sort de l'objet, pris dans les entrailles du Décapeur...\n\nD'un coup, le processus s'arrête, annonçant la fin du travail d'un simple \"Ding !\". La trappe s'ouvre et révèle une petite boîte, lacée d'un petit noeud rouge. Il semblerait, qu'en plus de les nettoyer, le Décapeur emballe les objets qui lui sont confiés !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience"},
[2946] = {title = "Questions sans réponses", objective = "Porter les Disques de platine miniatures aux Portes d'Uldum, à Tanaris et chercher les indices de la connexion qui existe entre eux.", description = "Nous voulons que vous portiez les disques que vous avez trouvés, aux portes scellées d'Uldum. Nous... ne sommes pas sûrs de ce qui va se passer quand vous ferez cela.\n\nCela pourrait être risqué, aussi bien que parfaitement inefficace. Vous devrez utiliser les disques, d'une manière ou d'une autre... Peut-être les portes s'ouvriront-elles toutes seules à l'approche des disques... allez savoir. Essayez ce qui vous semblera bon et attendez-vous à tout.\n\nRevenez ensuite à Ironforge. Du travail nous attend !", progress = "Le socle, d'apparence familière, se dresse sur le sable brûlant. Sa présence ici ne peut être fortuite...", completion = "Comme vous touchez le socle, les disques miniatures se mettent à bourdonner et à rougeoyer dans votre sac à dos. Un picotement que vous connaissez parcourt vos mains tandis que l'image d'un deuxième Gardien des pierres se matérialise devant les Portes d'Uldum.\n\n\"Salutations ! Je garde l'entrée, il manque aux disques que vous avez utilisés les Plaques d'Uldum. Veuillez incorporer ces plaques dans la structure des disques et répéter la séquence d'accès. Merci.\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2947] = {title = "Le retour de l'anneau", objective = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres.", description = "En ouvrant la boîte, vous trouvez ce à quoi vous vous attendiez : un anneau scintillant, comme flambant neuf ! Dès que vous l'enfilez, vous sentez une vague de puissance magique traverser votre corps.\n\nDans la face intérieure de l'anneau, vous voyez le poinçon d'Ironforge, accompagné de trois petites initiales gravées : \"TdK\". Ce peuvent être celles du précédent propriétaire de l'anneau ou celles de son artisan. Garder l'anneau... ou le rendre à qui il appartient. Difficiles décisions, en vérité...", progress = "Hé ! Du calme, l'ami. Je suis un homme d'affaire très en vue ! Le courrier avec le loyer aura eu du retard, voilà tout... attendez... vous n'êtes pas mon propriétaire.\n\nBien sûr que vous n'êtes pas le propriétaire, idiot que je suis ! Vous venez trouver le meilleur joaillier d'Ironforge ; un qui ne fait PAS des bijoux MAUDITS !\n\nBon, vous cherchez quoi au juste ?", completion = "Un anneau, dites-vous ? Mince alors ! C'est bien moi qui ai fabriqué cet anneau, en effet !\n\nAvant que la vie ne devienne si chère ici, j'avais une petite boutique. C'est sans doute un des anneaux que j'ai laissés ici, lorsque je suis parti me réfugier dans les collines. Peut-être est-ce l'anneau porté par une personne qui ne s'en est pas tirée.\n\nVous avez trouvé cela sur un nain Sombrefer ? Hum, une nouvelle odeur de conspiration flotte dans l'air. Peut-être les autorités aimeraient être au courant de tout cela ; allez donc les trouver car moi je n'y comprends rien.\n\nRevenons à cet anneau...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2948] = {title = "Amélioration gnomique", objective = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Talvash del Kissel, à Ironforge.", description = "Écoutez, <nom>, cet anneau vous appartient mais je peux l'améliorer. Sa forme est très simple et j'ai beaucoup progressé depuis. Pour la modique somme de trente pièces d'argent, je lui donnerai de nouveaux atours... bon, un peu plus de trente pièces, car je suis un peu gêné financièrement, en ce moment.\n\nTous mes stocks de matériaux sont épuisés ; si vous m'apportez une barre d'argent et une agate mousse, je pourrai ajouter un treillis de perles et d'argent qui donnera à cet anneau un sacré coup de fouet !\n\nFaites-moi confiance !", progress = "Avez-vous les matériaux dont j'ai besoin ? Je ne vous les demanderais pas si je ne manquais pas si cruellement de ressources.", completion = "Ah, exactement ce dont j'avais besoin ! Un jour, quand je sortirai de cette injuste affliction, je fabriquerai pour vous, pour TOUT LE MONDE, les plus belles babioles d'Azeroth ! En tous cas, merci pour les ingrédients. Je demande normalement dix fois ce prix pour un anneau de cette qualité...\n\nD'ailleurs, à propos d'anneau, voici le vôtre !", rewards = "Vous recevrez :\n\nAnneau d'or de Talvash"},
[2949] = {title = "Le retour de l'anneau", objective = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres.", description = "En ouvrant la boîte produite par le Décapeur 5200, vous découvrez un anneau scintillant. Quand vous le passez à votre doigt, vous sentez une incroyable vague de puissance magique traverser votre corps.\n\nDans la face intérieure de l'anneau, vous pouvez voir le petit poinçon d'Orgrimmar à côté duquel les trois premières lettres gravées d'un mot sont visibles : \"NOG...\"\n\nCe sont peut-être les initiales de l'ancien propriétaire de l'anneau ou de son fabricant. Garder l'anneau... ou retrouver \"NOG\" - difficile décision, en vérité...", progress = "Vous pensiez que nous trouverions un moyen de l'emporter sur ces sales petits gnomes ? Je suis sûr qu'ils l'ont volé, cet anneau, pour commencer ! Enfin, ces affreux petits... hem, oui ? Il vous fallait quelque chose ?", completion = "Un anneau de Gnomeregan ? Voyons... non ce n'est pas le mien, mais c'est intéressant.\n\nCette histoire n'aurait pas pu arriver à de plus parfaits crétins. Quels imbéciles ! Ils sont la risée de tous, depuis des années, et soudain, voilà qu'ils feraient de meilleurs anneaux que nous ?\n\nLes nains Sombrefer avaient l'anneau ? Voilà qui est plus intéressant ! Peut-être les gnomes ont-ils volé les plans de leurs golems et les ont-ils modifiés. Ces Sombrefer, ils veulent vraiment s'attirer tous les bénéfices. Il faut tirer cela au clair.\n\nQuant à cet anneau...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2950] = {title = "Nogg améliore l'anneau", objective = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Nogg, à Orgrimmar.", description = "Non, non, non, je ne suis pas en train de dire que cet anneau est à moi. Cependant, votre information sur les Sombrefer fut très utile. J'améliorerai cet anneau pour vous, bien mieux que ne le pourrait celui qui a forgé cette pauvre petite chose... sans doute un gnome, d'ailleurs...\n\nSi vous m'apportez une barre d'argent, une agate mousse et trente pièces d'argent, je pourrai ajouter un treillis de perles et d'argent qui donnera une ampleur toute nouvelle à la magie contenue dans cet anneau. Cela vous intéresse ?", progress = "Avez-vous les matériaux que j'ai demandés ? Je ne peux améliorer cet anneau sans eux.", completion = "Voici votre anneau, il est bien plus puissant qu'auparavant. Merci encore pour l'information sur les nains Sombrefer. On dirait que ces gnomes ont soudain été frappés d'une inspiration digne des gobelins.", rewards = "Vous recevrez :\n\nAnneau d'or de Nogg"},
[2951] = {title = "Le Décapeur 5200 !", objective = "Insérer un Objet sali dans le Décapeur 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine.", description = "L'étrange objet est là, au milieu des gnomes. Une petite plaque sur la machine indique : \"Décapeur 5200\", suivit d'un texte :\n\n\"La crasse et les résidus ruinent vos objets ? Le Décapeur 5200 est l'outil qu'il vous faut pour restaurer toute la brillance et l'éclat qu'ils méritent. Veuillez placer l'objet à décaper dans la machine, ainsi que trois pièces d'argent dans la fente prévue à cet effet et attendez un petit moment : vos objets de valeur en sortiront comme neufs\"", progress = "Il semble que la machine ne fonctionne que lorsqu'on y a déposé un objet à nettoyer et inséré trois pièces d'argent dans la fente prévue à cet effet. Si ces deux conditions sont réunies, le Décapeur 5200 devrait fonctionner.", completion = "Vous placez l'objet à nettoyer dans l'appareil et jetez trois pièces d'argent dans la fente. Le Décapeur 5200 se met à trembler et à trépider avec une inquiétante violence, tout à son oeuvre de décapage. Des grincements inquiétants, des battements sourds montent des entrailles de la machine tandis qu'elle vacille de tous côtés...", rewards = nil},
[2952] = {title = "Le Décapeur 5200 !", objective = "D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.\n\nBon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non...", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPaquet-cadeau du Décapeur"},
[2953] = {title = "Le Décapeur décape encore", objective = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer.", description = nil, progress = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer.", completion = "Le Décapeur 5200 se met en action, vrombissant et crachotant tandis qu'à l'intérieur, sur l'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !\n\nLe Décapeur 5200 s'arrête et émet un \"ding !\" pour indiquer qu'il a terminé son travail. La trappe s'ouvre, dévoilant une petite boîte, ornée d'un joli noeud.", rewards = "Vous recevrez :\n\nPaquet-cadeau du Décapeur"},
[2954] = {title = "Le Gardien des pierres", objective = "Apprendre le but du Gardien des pierres de Norgannon, puis interagir avec le Socle d'Uldum, dans le désert de Tanaris.", description = "Bonjour, je garde l’entrée. Si vous n’avez pas les Plaques d'Uldum intégrées à votre jeu de disques je ne vous laisserai pas entrer dans le complexe d’Uldum.\n\nL’apparition du Gardien des pierres de Norgannon est la réaction qui était espérée en vous envoyant dans le Désert de Tanaris avec les disques de platine. Vous devez maintenant découvrir l’histoire du Gardien des pierres avant de continuer.", progress = "Le but du Gardien des pierres doit être connu avant de continuer...", completion = "La voix du Gardien des pierres résonne avec puissance et autorité :\n\n\"Vos disques vous seront rendus lorsque vous accéderez au Socle. Quand vous aurez obtenu les Plaques d'Uldum et les aurez incorporées à votre jeu de disques, vous pourrez entrer dans le complexe\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2962] = {title = "Encore plus de Lueur verte !", objective = "Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.\n\nAprès le travail, conserver la Flasque plombée lourde, pour Ozzie.", description = "Votre échantillon n'était pas seulement insuffisant, mais impur.\n\nNous avons besoin de plus de Lueur verte. Les troggs ne sont apparemment pas encore assez irradiés. Vous devrez aller à Gnomeregan et rapporter de la matière radioactive, prélevée à la source. Je parle bien sûr de toutes ces gelées, rôdeurs et autres horreurs irradiées qui errent là-bas. Attention, la collecte et le conditionnement de telles matières est difficile ; il vous faudra faire plusieurs tentatives avant qu'un échantillon valable soit prélevé.", progress = "Hum, vous ne luisez pas ; c'est un bon signe.", completion = "&lt;Ozzie vous examine.&gt; Impressionnant, vous avez encore tous vos membres. Voyons maintenant les capacités de cette matière !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2963] = {title = "Prodiges d'Uldum", objective = "Parler à l'Historien Karnik dans le Hall des explorateurs, à Ironforge.", description = "Ah, <nom> ! La nouvelle de votre découverte dans Uldaman a mis en joie la Ligue des explorateurs. La Ligue a beaucoup travaillé pour découvrir le secret des petits disques de platine que vous avez trouvés. Je puis vous dire que nous sommes au seuil de quelque chose d'important !\n\nL'Historien Karnik a quelques hypothèses très intéressantes sur l'origine de la vallée des Guetteurs dans le désert de Tanaris. Il voudrait vous parler dès que possible.", progress = nil, completion = "Je suis content de voir que vous gardez du goût pour l'exploration, &lt;nom&gt; ! Vos talents peuvent nous servir à lever bien des mystères et des secrets !\n\nLes Disques de Norgannon étaient dépositaires d'importantes informations ; vous n'avez pu accéder qu'aux informations superficielles stockées là. Les Créateurs auraient laissé d'autres stocks d'informations partout dans Azeroth. Ce qui nous amène à Uldum...", rewards = "Vous recevrez :\n\n"},
[2964] = {title = "Travail imminent", objective = "Parler au Grand Explorateur Magellas, à Ironforge.", description = "Bien, <nom>... Il semblerait que nous soyons dans l'impasse. Nous avons besoin des Plaques d'Uldum, mais nous ne savons pas où elles se trouvent. Nous devons réfléchir avant d'avoir un plan pertinent. J'ai bien quelques petites idées et j'espère que nous vous enverrons bientôt pour les récupérer.\n\nLe Grand Explorateur doit être informé de tout cela, <nom> ; il est à parier qu'il veut aussi vous remercier pour l'aide que vous avez apportée à la Ligue.", progress = nil, completion = "Nous sommes tous d'accord : la meilleure chose à faire pour l'instant est de ne rien faire, jusqu'à ce que l'on puisse circonscrire le champ de recherche des Plaques. J'espère que vous serez là le jour où il faudra partir les récupérer dans Uldum, &lt;nom&gt;.\n\nVoici, en attendant, ces honoraires pour couvrir les dépenses que vous avez faites en nous prêtant assistance, ainsi qu'un petit quelque chose en plus. Restez en contact avec nous... Uldum attend !", rewards = "Vous recevrez :\n\n"},
[2965] = {title = "Prodiges d'Uldum", objective = "Aller à la Cime des Anciens, dans Thunder Bluff et parler à Nara Wildmane.", description = "Ah, <nom>, vous voilà de nouveau. Vos révélations quant au site de fouilles d'Uldaman ont motivé bien des discussions parmi nous. J'en parlais justement avec mon ami, le druide Nara Wildmane et il m'apparut que son expérience passée pouvait orienter la suite de notre action.\n\nAllez la voir et écoutez l'histoire de ses voyages dans la vallée des Guetteurs du désert de Tanaris. Elle vous attend à la Cime des Anciens.", progress = nil, completion = "Il existe un lieu, loin dans le désert de Tanaris, appelé la vallée des Guetteurs. Nous avons traduit les hiéroglyphes des disques que vous avez découverts ; ils mentionnent un endroit appelé Uldum. Beaucoup estiment que ce n'est qu'un mythe.\n\nPour ma part, je sais qu'Uldum existe. J'y suis même allée... enfin je suis restée à l'extérieur.\n\nNous sommes sûrs qu'il existe une connexion étroite entre les disques et Uldum, &lt;nom&gt;, et nous voulons que vous vous y rendiez.", rewards = "Vous recevrez :\n\n"},
[2966] = {title = "Questions sans réponses", objective = "Porter les Disques de platine miniatures aux Portes d'Uldum, à Tanaris et chercher les indices de la connexion qui existe entre eux.", description = "Le Sage Truthseeker et moi-même voulons que vous portiez les disques que vous avez découverts jusqu'aux portes scellées d'Uldum. Nous... ne sommes pas sûrs de ce qui va arriver quand vous serez là-bas.\n\nCela pourrait être risqué, aussi bien que parfaitement inefficace. Vous devrez utiliser les disques, d'une manière ou d'une autre... peut-être les portes s'ouvriront-elles toutes seules à l'approche des disques... allez savoir. Essayez ce qui vous semblera bon et attendez-vous à tout.\n\nApprenez ce que vous pourrez, puis revenez me voir ; nous aurons beaucoup à nous dire.", progress = "Le socle, d'apparence familière, se dresse sur le sable brûlant. Sa présence ici ne peut être fortuite...", completion = "Comme vous touchez le socle, les Disques miniatures se mettent à bourdonner et à rougeoyer dans votre sac à dos. Un picotement que vous connaissez parcourt vos mains tandis que l'image d'un deuxième Gardien des pierres se matérialise devant les Portes d'Uldum.\n\n\"Salutations ! Je garde l'entrée, il manque aux disques que vous avez utilisés les Plaques d'Uldum. Veuillez incorporer ces Plaques dans la structure des disques et répéter la séquence d'accès. Merci.\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2967] = {title = "Le retour à Thunder Bluff", objective = "Parler à Nara Wildmane, dans Thunder Bluff.", description = "Vous accédez au socle, à nouveau ; les disques de platine réapparaissent une nouvelle fois dans votre sac à dos.\n\nAvec ce que vous avez appris du Gardien des pierres et les disques en votre possession, vous pouvez à présent retourner à Thunder Bluff et informer Nara Wildmane de votre découverte.", progress = "Alors, <nom>, avez-vous pu utiliser les disques ou revenez-vous bredouille ?", completion = "Il vous a manqué certains disques ? Ainsi les disques de Norgannon ne sont-ils qu'une partie du jeu complet, comme des clés sur un trousseau.\n\nSi nous pouvions trouver les Plaques d'Uldum, nous pourrions accéder au complexe d'Uldum lui-même. Je ne sais pas si je dois m'en réjouir ou en être terrifiée.\n\nNous devons faire tout ce qui est en notre pouvoir pour nous assurer que les secrets que la terre couve et qui pourraient tous nous détruire, restent... secrets.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2968] = {title = "Travail imminent", objective = "Parler au Sage Truthseeker, à Thunder Bluff.", description = "Bien, <nom>... Il semble que nous soyons dans l'impasse. Nous avons besoin des Plaques d'Uldum, mais nous ne savons pas où elles se trouvent. Nous devons faire des recherches à ce sujet. J'ai bien quelques petites idées et j'espère que vous irez bientôt les récupérer. Nous vous demanderons bientôt de vous joindre à nous pour découvrir la vérité.\n\nLe Sage Truthseeker doit être informé de cela, <nom> ; il voudra aussi vous remercier d'avoir, une fois de plus, répondu à l'appel.", progress = nil, completion = "Nous sommes tous d'accord : le mieux, pour l'instant, est d'attendre que nous puissions circonscrire suffisamment les zones où pourraient se trouver ces plaques. J'espère que vous serez celui qui retournera bientôt à Uldum pour en découvrir les secrets, &lt;nom&gt;.\n\nVoici déjà quelques honoraires pour couvrir les dépenses que vous avez faites en nous portant assistance, ainsi qu'un petit quelque chose en plus. Restez en contact avec nous. Uldum nous attend.", rewards = "Vous recevrez :\n\n"},
[2969] = {title = "Liberté pour toutes les créatures", objective = "A l’aide de la Clé de la cage en bambou, libérer les Fées fléchetteuses de l’enclos dans le Camp du Totem sinistre. Au moins 6 Fées fléchetteuses et Kindal Moonweaver doivent survivre.\n\nVous avez 6 minutes avant que Kindal décide qu’il est temps de battre en retraite et que vous échouiez dans votre quête.", description = "L'odieux clan du Totem sinistre capture des créatures féeriques, <nom>. Jer'kai et moi ne savons pas quels desseins ils poursuivent en faisant cela, mais ce n'est certainement rien de bon.\n\nNous ne sommes pas assez puissants pour combattre le Totem sinistre dans son camp et libérer les créatures, mais peut-être qu'avec votre aide...\n\nSi vous êtes d'accord et avez quelques amis robustes qui voudraient se joindre à vous, allez libérer les créatures de leurs cages grâce à cette clé et assurez-vous qu'elles restent en vie. Je serai à vos côtés tout le temps ; Jer'kai, pour sa part, restera ici, au cas où...", progress = nil, completion = "Elune soit louée, &lt;nom&gt; ! Vous êtes une bénédiction pour nous et les Fées fléchetteuses que vous avez sauvées. Jer'kai et moi, nous n'avons jamais été capables d'aider les dragons. Nous n'oublierons jamais votre intervention dans les affaires du Totem sinistre.\n\nParlez à Jer'kai... Je dois préparer notre vengeance. Ce n'est pas parce que les dragons féeriques sont libres qu'ils le resteront. Jer'kai et moi-même devons passer à l'offensive.", rewards = "Vous recevrez :\n\n"},
[2970] = {title = "Justice de châtiment", objective = "Tuer 12 Naturalistes du Totem sinistre, 10 Ecumeurs du Totem sinistre et 6 Chamans du Totem sinistre avant de retourner voir Jer'kai Moonweaver, en Feralas.", description = "Comme vous l'a déjà dit Kindal, nous allons désormais combattre le clan du Totem sinistre. Ensemble, nous devrions pouvoir affronter quelques taurens, mais nous apprécierions votre aide, si vous êtes d'accord.\n\nVous avez vu l'un des camps, en aval ; il y en a encore d'autres à l'est. Faites selon vos compétences et techniques mais infligez autant de dégâts possibles aux taurens. Quand ils auront goûté à la piqûre des flèches de Kindal et à vos propres armes, nous nous retrouverons tous ici, pour faire le point.", progress = "Kindal a besoin de temps pour se préparer, mais nos victimes se comptent maintenant par douzaines. Le clan du Totem sinistre est conscient de notre présence et nous recherche sans relâche...\n\nIls feraient n'importe quoi pour brandir nos têtes au bout d'une pique. Faites attention, après ce que vous avez fait, ils ne vous feront pas de cadeaux non plus.", completion = "Kindal avait raison à votre sujet, &lt;nom&gt;. Vous avez un don pour ça. Vous êtes l'aventurier le plus aguerri de nous tous et nous vous en remercions.\n\nLe clan du Totem sinistre est plus hostile que la plupart des clans taurens... Je me demande même si leurs semblables ne désapprouvent pas leurs actions. Comme vous l'avez certainement remarqué, beaucoup de races à Azeroth comptent des individus vicieux et peu fréquentables.\n\nMais nous discuterons un autre jour.", rewards = "Vous recevrez :\n\n"},
[2972] = {title = "Justice de châtiment", objective = "Apporter la Chevalière de Jer'kai's à la Grande prêtresse Tyrande Whisperwind, à Darnassus.", description = "Ici, dans les terres sauvages, Kindal et moi n’avons pas grand-chose à vous offrir, mais nous voulons récompenser votre aide. Prenez ma chevalière. Si un jour vous êtes dans les environs de Teldrassil, allez au Temple de la Lune au cœur de Darnassus. Là, vous trouverez ma Haute prêtresse Tyrande Whisperwind. L'anneau lui dira que nous allons bien et que votre histoire est vraie.\n\nNous vous remercions tous les deux, <nom>.", progress = "Bonjour mon enfant, il est agréable de voir de nouveaux aventuriers, ici dans le Temple. Si vous aviez le temps, peut-être pourriez vous conter quelques-unes de vos épopées aux aventuriers plus jeunes ; je suis sûre qu'ils sauront profiter de votre sagesse.\n\nMais je manque à tous mes devoirs : vous arrivez au Temple pour obtenir de l'aide et c'est moi qui vous sollicite. Veuillez m'excuser. Dites-moi plutôt ce que les serviteurs de la Lumière peuvent faire pour vous.", completion = "C'est une histoire incroyable, &lt;nom&gt;. Nous sommes heureux de voir que vous n'avez pas hésité à aider les draconiens et l'une de nos propres prêtresses. Jer'kai a eu raison de vous envoyer ici. J'ai envoyé des éclaireurs dans la région de Feralas, je m'assurerai qu'ils lui rapportent sa chevalière.\n\nMerci encore. Vous êtes ici chez vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nProtège-poignets du saule épineuxCeinturon de la nuit\n\nVous recevrez également :\n\n"},
[2973] = {title = "Une nouvelle cape", objective = "Rapporter 10 Ailes iridescentes de Fées fléchetteuses à Krueg Skullsplitter à Camp Mojache.", description = "Ah, vous voici, <classe>. Lors d'une mission pour nos maîtres d'Orgrimmar, j'ai voyagé loin en direction de Feralas.\n\nMon amie Korrin adore les vêtements, j'ai donc l'intention de lui confectionner une nouvelle cape ornée des ailes légères des créatures féériques. M'aiderez-vous ? Les Fées fléchetteuses aux ailes sublimes se trouvent à l'ouest de Camp Mojache.", progress = "Quand elles sont provoquées, les Fées fléchetteuses peuvent être de dangereuses bestioles ; faites très attention et ne vous fiez pas à leur apparence, <classe>. Soyez encore plus vigilant quant aux elfes de la nuit qui peuplent l'endroit. Ces infects individus rôdent souvent dans les forêts.\n\nRevenez me voir quand vous aurez collecté suffisamment d'ailes et je vous récompenserai largement !", completion = "Merveilleux, &lt;classe&gt; ! Ils feront l'affaire. Il y en a assez pour faire une cape pour Korrin, peut-être plus ! Merci.\n\nJ'espère que le voyage n'a pas été trop dangereux. La région de Feralas n'est pas réputée pour être paisible. Mais vous avez réussi.\n\nMerci encore, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[2974] = {title = "Une découverte sinistre", objective = "Apporter 20 Cornes de Totem sinistre à Krueg Skullsplitter à Camp Mojache.", description = "Quoi ! Vous avez rencontré des taurens dans le secteur ? Vous plaisantez ! A quoi ressemblaient-ils !?\n\nLe clan Totem sinistre ! Vous en avez vus ? Belgrom, l'un de nos maîtres, s'intéresse à eux… Il offre même une prime à leur égard.\n\nVous devez repartir, <classe>. Retournez-y et apportez-moi leurs cornes. Des montagnes si vous pouvez. Ils ne doivent pas être traités à la légère ou sous-estimés. Retournez-y et massacrez-les. Que les rivières de Feralas rougissent de leur sombre sang.", progress = "Prêtez-moi toute votre attention, <classe>, le clan du Totem sinistre est maléfique. Si vous les avez localisés, il ne dépend que de vous d'y retourner et de frapper le premier coup contre leur clan… avant qu'ils ne viennent sur nos propres terres pour raser nos villages ou piller nos terres.", completion = "Ce sont de bien belles cornes, &lt;classe&gt;. Félicitations ! Je les prends et vous assure d'informer Belgrom dès que nous serons de retour à Orgrimmar. Vous m'avez aidé deux fois et avez gagné mon plus grand respect. Peut-être, dans l'avenir, pourrais-je vous aider à mon tour ! Bonne chance à vous.", rewards = "Vous recevrez :\n\n"},
[2975] = {title = "Les ogres de Feralas", objective = "Tuer 10 Ogres gordunni, 10 Ogre-magi gordunni et 5 Brutes gordunni pour Rok Orhan, à Camp Mojache.", description = "La tribu des ogres Gordunni ne peut pas passer inaperçue, dans cette région ; regardez autour de vous : le pays est comme blessé par leur simple présence, <nom>. Nous devons les repousser avant qu'ils ne se répandent plus avant dans Feralas.\n\nSuivez la rivière au nord, vous tomberez sur leur avant-poste. Portez la mort et la désolation parmi eux, <nom>. Nous devons leur montrer à quel point nous les trouvons indésirables.", progress = nil, completion = "Excellent, &lt;nom&gt;. Avec le temps, le pays guérira. Nous devons tenir bon.", rewards = "Vous recevrez :\n\n"},
[2976] = {title = "Une découverte sinistre", objective = "Apporter la Caisse de Cornes de Totem sinistre à Belgrom Rockmaul, Orgrimmar.", description = "Comment ?\n\nAh, j'ai parlé d'une récompense, n'est-ce pas ? Bon... ça m'apprendra à ouvrir la bouche !\n\nVous avez fait le travail et je suppose que je vous dois ce que je vous avais promis. Prenez les cornes, je les ai mises dans une caisse pour vous et portez-les à Belgrom Rockmaul, dans la Vallée de l'honneur. Il souhaite entendre votre rapport et vous récompenser.\n\nQue les vents vous portent, <classe>, et merci encore pour tout.", progress = "Que voulez-vous, <classe> ? J'ai beaucoup à faire aujourd'hui.", completion = "Le Totem sinistre ? Voilà qui est intéressant. Vous dites que vous les avez rencontrés en chassant dans Feralas ? Vraiment ?\n\nMes compagnons voudront entendre ce que vous avez à dire, &lt;classe&gt;. Racontez-m'en plus pendant que je vous prépare une récompense.\n\nEt avant que vous ne partiez, je me dois de vous remercier pour toutes ces informations.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de briscardOrbe de jadelune\n\nVous recevrez également :\n\n"},
[2977] = {title = "Retour à Ironforge", objective = "Parler à l'Historien Karnik, à Ironforge.", description = "Comme vous accédez de nouveau au socle, les disques de platine apparaissent une fois de plus dans votre sac à dos.\n\nAvec ce que vous avez appris du Gardien des pierres et les disques de nouveau en votre possession, vous pouvez maintenant retourner à Ironforge et informer la Ligue des explorateurs de votre découverte.", progress = "Bienvenue, <nom>. Avez-vous su utiliser les disques ou revenez-vous bredouille ?", completion = "Il vous manque certains disques ? Les Disques de Norgannon ne seraient donc qu'une partie du jeu de disques, comme des clés sur un trousseau ?\n\nSi nous pouvions mettre la main sur les Plaques d'Uldum, nous pourrions accéder au complexe d'Uldum lui-même ! Imaginez, l'exploration de l'endroit où les Créateurs travaillèrent tout en finesse, sans pelles ni foreuses !\n\nN'allez pas croire que je n'aime pas les pelles... ou les foreuses...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2978] = {title = "Le parchemin Gordunni", objective = "Apporter le Parchemin Gordunni à Rok Orhan, à Camp Mojache.", description = "En ramassant les parchemins salis, vous remarquez qu'ils représentent quelque cérémonie ou rassemblement. Rok Orhan aimerait sûrement jeter un oeil sur ce parchemin et savoir quel est son rapport avec les Gordunni.", progress = "Qu'est-ce que c'est que ça ?", completion = "Ce parchemin... vous l'avez trouvé dans l'avant-poste des Gordunni ?", rewards = "Vous recevrez :\n\n"},
[2979] = {title = "Sombre cérémonie", objective = "Rapporter un Orbe Gordunni à Rok Orhan, à Camp Mojache.", description = "On dirait bien des plans pour quelque sombre cérémonie, <nom>. D'après ce que je vois, cette assemblée est tenue par les seigneurs-mages Gordunni.\n\nTrouvez l'un de ces seigneurs-mages et prenez-lui un orbe.\n\nL'orbe d'un mage contient beaucoup de pouvoirs et nous aidera à en savoir plus sur cette cérémonie secrète des Gordunni.", progress = "Nous devons en apprendre plus à propos de la présence des Gordunni ici, <nom>.", completion = "Cet orbe nous fournira des informations supplémentaires à propos des Gordunni... informations que nous utiliserons pour les détruire, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2980] = {title = "Les ogres de Feralas", objective = "Tuer 10 Chamans Gordunni, 10 Démonistes Gordunni et 5 Marteleurs Gordunni pour Rok Orhan, à Camp Mojache.", description = "Vous avez prouvé que vous saviez vous battre et je sais que vous avez le courage de continuer la mission.\n\nAllez dans les Plateaux sauvages, au sud-ouest. Vous y verrez des structures détruites et abandonnées sur les terres qui, jadis, appartenaient aux elfes de la nuit. Dirigez-vous sur ces ruines et quand vous traverserez des terres profanées aux arbres flétris, vous trouverez les Gordunni. Repoussez-les.\n\nCes ogres sont beaucoup plus forts et dangereux que ceux que vous avez précédemment combattus, <nom>. Soyez <prudent/prudente>.", progress = nil, completion = "Vous avez prouvé que l'on pouvait vous faire confiance, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2981] = {title = "Menace sur Feralas", objective = "Comme le veut Belgrom Rockmaul, aller parler à Rok Orhan, à Camp Mojache.", description = "Feralas est un lieu parfait pour faire ses preuves, <classe>. Une tribu d'ogres appelées les Gordunni domine militairement l'endroit et leur nombre, sans cesse, s'accroît. Ils doivent être arrêtés avant de devenir une véritable menace pour Feralas.\n\nJe connais une certaine Rok Orhan qui habite à Camp Mojache, dans Feralas ; allez la trouver, elle vous en dira plus sur la situation.", progress = nil, completion = "Ainsi c'est Belgrom qui vous envoie, &lt;nom&gt; ?\n\nVoici la situation, si vous vous sentez capable d'en affronter le danger... Mais si Belgrom vous envoie, c'est que vous ne manquez pas de courage.", rewards = "Vous recevrez :\n\n"},
[2982] = {title = "Les Plateaux sauvages", objective = "Tuer 8 Démonistes Gordunni, 8 Chamans Gordunni et 8 Brutes Gordunni pour Angelas Moonbreeze.", description = "Bien que ce soit risqué, Troyas et moi avons visité les ruines dans les forêts de Feralas.\n\nCes derniers temps, Troyas à pris l'habitude de se rendre seul sur les Plateaux sauvages, et je m'inquiète pour lui. Les ogres Gordunni contrôlent la zone et ils ne traitent pas avec douceur ceux qui s'aventurent dans leur domaine.\n\nAccepteriez-vous d'aller dans les ruines, au sud-est, et de tuer quelques ogres afin de rendre la zone un peu plus sûre pour Troyas. Je vous en remercie par avance.", progress = nil, completion = "Je vous remercie beaucoup pour ce que vous avez fait pour moi.\n\nMais, s'il vous plaît, n'en dites rien à Troyas...", rewards = "Vous recevrez :\n\n"},
[2983] = {title = "L'appel du feu", objective = "Trouver Kranal Fiss dans les Tarides.", description = "Cela fait quelque temps que vous n'avez pas été <mis à l'épreuve/mise à l'épreuve>, <nom>. Vous avez fait preuve de patience dans vos études jusque-là, mais il est temps pour vous d'apprendre de plus grands pouvoirs… il est temps d'apprendre le réel pouvoir. L'élément de feu vous appartient si vous êtes <prêt/prête> à payer pour cela.\n\nRecherchez Kranal Fiss dans les Tarides. Il réside dans une petite demeure au nord de la Croisée, mais faites attention ; si vous atteignez les terres de ces maudits elfes, c'est que vous êtes <allé/allée> trop loin.", progress = nil, completion = "Hum, Swart vous envoie, n'est-ce pas ?\n\nOn peut lui faire confiance, cela signifie que vous avez l'expérience requise pour le prochain sapta, le Sapta de feu.\n\nJe vois votre désir d'apprendre brûler dans vos pupilles. Vous avez de grands pouvoirs et l'envie d'en connaître de plus grands encore. Patience, &lt;nom&gt;. Rappelez-vous : force et pouvoir de destruction viendront facilement, le tout est de savoir se retenir à bon escient.", rewards = "Vous recevrez :\n\n"},
[2984] = {title = "L'appel du feu", objective = "Trouver Kranal Fiss dans les Tarides.", description = "Cela fait longtemps que vous n'avez pas été <mis à l'épreuve/mise à l'épreuve>, <nom>. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent arrivé d'apprendre la destruction et le chaos. L'élément Feu peut vous appartenir, si vous êtes <prêt/prête> à en payer le prix.\n\nRecherchez Kranal Fiss dans les Tarides. Il vit dans une petite demeure au nord de la Croisée, mais faites attention, si vous atteignez les terres des elfes de la nuit, c'est que vous êtes <allé/allée> trop loin.", progress = nil, completion = "Hum, Narm vous envoie, n'est-ce pas ?\n\nOn peut lui faire confiance, cela signifie que vous avez l'expérience requise pour le prochain sapta, le Sapta de feu.\n\nJe vois votre désir d'apprendre brûler dans vos pupilles. Vous avez de grands pouvoirs et l'envie d'en connaître de plus grands encore. Patience, &lt;nom&gt;. Rappelez-vous : force et pouvoir de destruction viendront facilement, le tout est de ne pas se précipiter.", rewards = "Vous recevrez :\n\n"},
[2985] = {title = "L'appel de l'eau", objective = "Trouver Islen Waterseer dans les Tarides.", description = "Vous êtes capable d'affronter la prochaine épreuve, <nom>. Vous avez su monter de la patience et avez progressé dans vos études, mais il est maintenant temps d'apprendre plus encore et de connaître la pureté de l'eau.\n\nCherchez Islen Waterseer, dans les Tarides. Elle vit le long de la côte est, au sud du fleuve Furie-du-Sud et de Ratchet. Vous la trouverez dans sa cabane de pêcheur. Bonne chance, <nom>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2986] = {title = "L'appel de l'eau", objective = "Trouver Islen Waterseer dans les Tarides.", description = "Cela fait longtemps que vous n'avez pas été <mis à l'épreuve/mise à l'épreuve>, <nom>. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent arrivé pour vous d'apprendre la pureté de l'Eau.\n\nCherchez Islen Waterseer dans les Tarides. Elle se trouve le long de la côte est, au sud du fleuve Furie-du-Sud et de Ratchet. Vous la trouverez dans une hutte de pêcheur. Bonne chance à vous, <nom>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[2987] = {title = "Cobalt Gordunni", objective = "Collecter 12 échantillons de Cobalt Gordunni pour Orwin Gizzmick, à Camp Mojache.", description = "Je viens juste d'arriver dans Feralas et j'ai appris que les ogres Gordunni qui y résident gardent d'intéressants minéraux. Impossible de savoir ce qu'ils projettent, mais ils protègent leurs stocks farouchement et les enterrent pour empêcher qu'un fou comme moi ne mette la main dessus.\n\nSi vous êtes d'accord, voici ma pelle : allez dans l'avant-poste des Gordunni, plus au nord, et extrayez-moi un peu de cobalt Gordunni. Cherchez la lueur bleue, puis commencez à creuser !", progress = "Venez ici et commencez à creuser !\n\nJ'ai des personnes à voir et des choses à faire ; le temps c'est de l'argent !", completion = "Parfait ! Je vais prendre ça avec moi en voyageant, &lt;nom&gt;. Je sais que certains paieraient cher pour avoir un peu de ce cobalt.\n\nVoici pour vous, en guise de remerciement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes des MaharishiCape d'astronome\n\nVous recevrez également :\n\n"},
[2988] = {title = "Les cages Witherbark", objective = "Inspecter les cages dans les deux villages Witherbark, puis retourner auprès du Maître des gryphons Talonaxe.", description = "Le fils de notre plus puissant gryphon est parti ! L'héritier d'Aile-vive, Bec-tranchant, a été perdu tandis qu'il chassait avec ses parents il y a quelques jours, et nous pensons que ce sont les trolls qui l'ont enlevé.\n\nVous devez nous aider. Passez en revue les cages dans les deux villages de trolls Witherbark pour savoir si Bec-tranchant s'y trouve.", progress = nil, completion = "Bec-tranchant n'était pas au village ? Hm… mauvaise nouvelle. Ce gryphon est destiné à conduire la nouvelle génération de gryphons. S'il est perdu, la force et l'esprit de notre groupe en pâtira grandement.", rewards = "Vous recevrez :\n\n"},
[2989] = {title = "L'autel de Zul", objective = "Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des gryphons Talonaxe.", description = "Bec-tranchant ne se trouvait pas avec les trolls Witherbark. Peut-être les trolls du clan Vilebranch l'ont-ils enlevé ? Partez pour l'autel de Zul sur le bord ouest du territoire Vilebranch et cherchez le jeune gryphon.", progress = "Vite, <nom> ! Si les trolls Vilebranch retiennent Bec-tranchant, qui sait ce qu'ils lui feront subir !", completion = "Bec-tranchant n'était pas là ? C'est une mauvaise nouvelle, mais c'est aussi une bonne nouvelle…\n\nC'est bien qu'il ne se soit pas trouvé à l'autel de Zul, car les trolls Vilebranch y font des sacrifices.\n\nMerci pour toute votre aide, mais je crains que la tâche suivante ne soit encore plus difficile.", rewards = "Vous recevrez :\n\n"},
[2990] = {title = "Thadius Grimshade", objective = "Apporter la Plume de Bec-tranchant à Thadius Grimshade, dans les Terres foudroyées.", description = "Apportez cette plume à Thadius Grimshade, le devin. Il a quitté le Nid-de-l'Aigle il y a des années pour engranger un savoir plus sombre, mais dans son cœur il reste un Wildhammer !\n\nPeut-être que ses talents peuvent nous aider à retrouver Bec-tranchant.\n\nCette plume provient du nid où dormait le jeune gryphon. Donnez-la à Thadius qui, avec un peu de chance, pourra utiliser ses talents divinatoires pour localiser Bec-tranchant.\n\nBonne chance, <nom>. Vous trouverez Thadius dans les Terres foudroyées, dans la tour des mages du Rempart-du-Néant.", progress = "<nom>, m'apportez-vous quelque offrande ?", completion = "Ah, oui. Cette plume appartient à un honorable gryphon. Un être destiné à de grandes choses... s'il arrive à survivre jusqu'à l'âge adulte.\n\nVous souhaitez le retrouver, n'est-ce pas ? Alors écoutez-moi attentivement, brave &lt;classe&gt;...", rewards = "Vous recevrez :\n\n"},
[2991] = {title = "Médaillon de Nekrum", objective = "Apporter le Médaillon de Nekrum à Thadius Grimshade, dans les Terres foudroyées.", description = "Si vous voulez que je localise votre gryphon, vous devrez faire quelque chose pour moi. Il y a un troll dans Zul'Farrak, Nekrum Mâchetripes, qui possède un médaillon que j'aimerais beaucoup étudier. Apportez-le-moi et j'utiliserai mes pouvoirs pour retrouver Bec-tranchant.\n\nZul'Farrak est de l'autre côté de l'océan, à l'est, dans le désert de Tanaris.", progress = "Avez-vous le Médaillon de Nekrum, <nom> ? Il contient des pouvoirs que je suis avide de mettre à l'épreuve.", completion = "Ah, le Médaillon de Nekrum. On dit qu'il a donné aux trolls une vie inhabituellement longue, mais à un prix élevé. Je souhaite découvrir un moyen de profiter de la puissance du Médaillon tout en évitant ses effets les plus déplaisants.\n\nVous m'avez rendu service, &lt;nom&gt;. Je vais remplir ma part du marché.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2992] = {title = "La Divination", objective = "Attendre que Grimshade ait fini de pratiquer son rituel de divination.", description = "Laissez-moi un peu de place pour me permettre de pratiquer le rituel de divination. Je vais connecter la plume à son propriétaire, ce qui me donnera accès à Bec-tranchant lui-même.\n\nSi tout se déroule comme prévu, évidemment... Sinon, hé bien, vous feriez mieux de ne pas regarder.", progress = nil, completion = "J'ai réussi. Je sais où se trouve Bec-tranchant et comment vous pouvez le rejoindre.", rewards = "Vous recevrez :\n\n"},
[2993] = {title = "Retour dans les Hinterlands", objective = "Parler au Maître des gryphons Talonaxe.", description = "Bec-tranchant est enfermé dans une cage, placée haute sur une falaise au sommet de Jintha'Alor dans les Hinterlands. La clé de cette cage est en possession de la grande prêtresse des trolls du clan Vilebranch, la vile prêtresse maléfique Maléficia.\n\nVoilà, j'ai fait ma part. Je vous souhaite bonne chance dans votre quête, <nom>.", progress = nil, completion = "Vous avez parlé à Grimshade ? Qu'a-t-il dit ?\n\n…Quoi ? Les trolls Vilebranch ont Bec-tranchant ? C'est intolérable ! Il faut que nous nous organisions pour le sauver !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[2994] = {title = "Sauver Bec-tranchant", objective = "Combattre jusqu’au sommet de Jintha'Alor, tuer la vile prêtresse Maléficia pour obtenir la clé de la cage de Bec-tranchant, et sauver Bec-tranchant.", description = "Bec-tranchant doit être secouru !\n\nFrayez-vous un chemin, à coups d'épée s'il le faut, jusqu'au sommet de Jinth'Alor, au coeur du territoire des Vilebranch et arrachez la clé de la cage à la vile prêtresse maléfique Maléficia. Enfin, retrouvez et libérez Bec-tranchant !", progress = nil, completion = "Aile-vive et Griffe-perçante sont revenus avec leur enfant, il y quelques moments et le gâtent comme de jeunes parents. Les voir réunis est un spectacle qui arrive encore à faire briller mes yeux fatigués...\n\nNous ne pourrons jamais vous récompenser à la hauteur de ce que vous avez fait pour nous, &lt;nom&gt;. Les gryphons du Nid-de-l'Aigle et leurs cavaliers chanteront longtemps vos exploits.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau-tempête des chevaucheurs de gryphonJambières des chevaucheurs de gryphon\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[2995] = {title = "Lignes de communication", objective = "Voyager dans les Hinterlands et brûler les Registres du Haut-val, le Rapport du Haut-val et les Notes du Haut-val, pour Oran Snakewrithe, à Undercity", description = "Le gîte de Quel'Danil est un centre de communication pour les elfes des Hinterlands. Leurs ambassadeurs essaient d'entrer en contact avec les races partageant leur connaissance des trolls Witherbark, qui habitent dans le sud des Hinterlands. Tous les documents concernant les communications sont gardés dans le gîte.\n\nNous ne voulons pas que les gens du Haut-val tissent des alliances, <nom>.\n\nDétruisez les documents du Haut-val. Nous devons brûler leurs lignes de communication... au sens propre comme au sens figuré.", progress = nil, completion = "Parfait, &lt;nom&gt;. Pendant que les elfes du Haut-val tentent de recouvrer les informations perdues, nous pourrons condamner leurs lignes de communication, voire plus...", rewards = "Vous recevrez :\n\n"},
[2996] = {title = "À la recherche de Strahad", objective = "Parler à Strahad Farsan, à Ratchet.", description = "Je vous ai beaucoup appris et maintenant je dois passer la main à un autre professeur. Il s'appelle Strahad et habite à Ratchet. C'est un humain, mais que cela ne vous incline pas à croire qu'il est faible. Il est de petite taille, c'est vrai, mais très puissant et pourra vous apprendre des invocations beaucoup plus importantes. Allez le voir, maintenant, vous le trouverez à Ratchet... A côté de la tour qui surplombe le port.", progress = nil, completion = "Un jour comme les autres à Ratchet, n'est-ce pas ? J'adore contempler l'activité d'une ville portuaire. Tant d'aventures et de mystères... et d'ignorance également.\n\nEst-ce de la haine que je vois dans vos yeux, &lt;nom&gt; ? Très bien, nous l'utiliserons à notre avantage.", rewards = "Vous recevrez :\n\n"},
[2997] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge à Ironforge.", description = "Bonjour, <nom>. Je sais que vous êtes très <occupé/occupée> à aider les gens de Dun Morogh, mais si vous avez le temps, allez jusqu'à Ironforge pour parler à la vénérable Tiza Battleforge. Les plus jeunes de nos paladins vont la voir lorsqu'ils veulent en apprendre plus sur la Lumière et sur ce que l'on attend d'eux.\n\nVous la trouverez à l'étage du Hall des Mystères qui se trouve dans la Garde mystique. Bonne chance, <nom>.", progress = nil, completion = "Salut, &lt;nom&gt;. J'espère que la Lumière est de votre côté et qu'elle vous protège du mal.", rewards = "Vous recevrez :\n\n"},
[2998] = {title = "Le Tome de divinité", objective = "Parler à Duthorian Rall à Stormwind.", description = "Salutations ! Duthorian Rall, l'un de nos paladins les plus influents, parlait de vous récemment. Je l'ai entendu dire qu'il était temps que vous soyez <mis/mise> à l'épreuve... Ainsi que des compliments vous concernant.\n\nJe vous conseille de vous rendre à Stormwind et de lui parler. Je pense que vous le trouverez dans la cathédrale de la Lumière, où il passe le plus clair de son temps.", progress = nil, completion = "Stormwind est belle, n'est-ce pas ?\n\nVous venez à point, si j'ose dire, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[2999] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge, à Ironforge.", description = "Bonjour, <nom>. Je sais que vous êtes très <occupé/occupée> à aider les gens de Dun Morogh, mais si vous avez le temps, allez jusqu'à Ironforge pour parler à la vénérable Tiza Battleforge. Les plus jeunes de nos paladins vont la voir lorsqu'ils veulent en apprendre plus sur la Lumière et sur leurs obligations.", progress = nil, completion = "Salut, &lt;nom&gt;. J'espère que la Lumière est de votre côté et qu'elle vous protège du mal.", rewards = "Vous recevrez :\n\n"},
[3000] = {title = "Le Tome de divinité", objective = "Parler à Tiza Battleforge à Ironforge.", description = "Bonjour, <nom>. Je sais que vous êtes très <occupé/occupée> à aider les gens d'Azeroth, mais si vous avez le temps, retournez à Ironforge et parlez à l'une de nos paladins les plus respectés, Tiza Battleforge. Nos jeunes paladins nains vont la consulter quand ils veulent en apprendre plus au sujet de la Lumière et sur ce que l'on attend d'eux.\n\nVous la trouverez à l'étage du Hall des Mystères qui se trouve dans la Garde mystique.", progress = nil, completion = "Je vous salue et vous souhaite la bienvenue, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[3001] = {title = "À la recherche de Strahad", objective = "Trouver Strahad Farsan, à Ratchet.", description = "Je vous ai appris des sorts, mais l'heure est venue pour d'autres leçons que je ne puis plus prodiguer. Votre nouveau professeur habite à Ratchet ; il s'appelle Strahad. C'est un humain, mais ne vous fiez pas à cela : il n'est ni faible ni hostile et ses pouvoirs sont grands. Il pourra vous enseigner les grandes invocations que vous avez maintenant les moyens d'apprendre.\n\nVous le trouverez à Ratchet... à côté de la tour qui surplombe le port.", progress = nil, completion = "Un jour comme les autres à Ratchet, n'est-ce pas ? J'adore contempler l'activité d'une ville portuaire. Tant d'aventures et de mystères... et d'ignorance également.\n\nEst-ce de la haine que je vois dans vos yeux, &lt;nom&gt; ? Très bien, nous l'utiliserons à notre avantage.", rewards = "Vous recevrez :\n\n"},
[3002] = {title = "L'Orbe Gordunni", objective = "Apporter l'Orbe Gordunni à Uthel'nay, au pavillon de Buissombre, à Orgrimmar.", description = "Je connais bien mon ennemi, <nom>, mais je ne suis qu'un guerrier. Je ne peux pas vous dire à quoi peut servir cet orbe.\n\nMais je connais un mage à Orgrimmar qui saura nous en dire plus à ce sujet. Montrez-lui l'objet.", progress = "Que m'apportez-vous là, <nom> ?", completion = "Fascinant, &lt;nom&gt;...\n\nCet orbe est aussi puissant que dangereux.", rewards = "Vous recevrez :\n\n"},
[3022] = {title = "À manipuler avec soin", objective = "Apporter la Caisse soigneusement empaquetée à Erelas Ambersky, au village de Rut'theran.", description = "<nom>, je vois que vous aspirez à embrasser ma louable cause. Bien entendu, vous pouvez faire quelque chose pour moi !\n\nApportez cette caisse d'oeufs à Erelas Ambersky. Ce druide les met en couveuse puis entraîne les jeunes hippogryphes. Vous le trouverez dans Teldrassil, dans un petit village appelé Rut'theran.", progress = "Un autre colis de Curgle, je présume ?", completion = "Merci, &lt;nom&gt;. Les hippogryphes ne pourraient prospérer si nous n'étions pas là. Mais je suppose que vous ne le savez que trop bien, vous qui avez voyagé en Feralas et avez vu comment les Gordunni dévastent l'endroit.\n\nComme vous le voyez, j'ai du travail ; vous feriez mieux de partir.\n\nMerci encore, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[3042] = {title = "Agent durcissant troll", objective = "Apporter 20 Fioles d'agent durcissant troll à Trenton Lighthammer, dans Gadgetzan.", description = "Les trolls Sandfury de Zul'Farrak fabriquent un agent durcissant à partir du grès, que j'utilise aussi pour tremper mes créations. Cette matière est très prisée, et si vous m'en rapportez une bonne quantité, vous serez largement <rétribué/rétribuée>.\n\nZul'Farrak est au nord-ouest de Gadgetzan. Bonne chance.", progress = "Avez-vous l'agent, <nom> ?", completion = "Ah, c'est parfait ! Et en grande quantité, qui plus est ; de quoi travailler pour plusieurs jours !\n\nMerci, &lt;nom&gt;. Acceptez ceci en guise de récompense.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3062] = {title = "Coeur noir", objective = "Rapporter le Coeur noir d'Edana Serrehaine à Talo Thornhoof, à Camp Mojache.", description = "Edana Serrehaine est la reine des harpies Ruissenord, qui vivent dans les ruines, à l'ouest. Cette créature est le mal à l'état brut ; il paraît que son coeur est de cristal froid, vide de toute émotion sauf de haine pure. Je vous demande de me rapporter le coeur d'Edana, après l'avoir tuée.\n\nUn cor est en possession des harpies ; et s'il est utilisé au lieu-dit des Pierres de Serrehaine, dans la partie nord des ruines, la reine est invoquée.\n\nImaginez sa surprise quand elle se rendra compte que ce n'est pas sa chère famille, mais sa mort qui l'a appelée.", progress = "La haine qu'Edana répand sur le pays doit être endiguée.", completion = "Maintenant je sais qu'Edana est vraiment morte. Je vais garder ce coeur en souvenir de ce que vous avez fait pour moi, &lt;nom&gt;. Merci.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants du cimier ailéCeinturon Forte-corne\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3063] = {title = "Se venger des Ruissenord", objective = "Tuer 4 Harpies Ruissenord, 4 Volplumes Ruissenord, 4 Imploratrices célestes Ruissenord et 4 Pourfendeuses Ruissenord pour Talo Thornhoof.", description = "Jadis, j'étais un chasseur de renom et ne craignais aucune espèce de créature. Jusqu'à ce que...\n\nUn jour que j'aiguisais mon épée dans la forêt, après une rude bataille, des harpies m'ont encerclé et attaqué. Je ne sais comment je réussis à en sortir vivant.\n\nEncore maintenant, je peux entendre leurs affreux cris de crécelle...\n\nDepuis cette embuscade, je ne suis plus le même tauren ; j'ai peur et mon âme est emplie de haine.\n\nLes harpies Ruissenord vivent à l'ouest. <nom>, soyez le bras armé de ma colère, vengez-moi !", progress = nil, completion = "Merci, &lt;nom&gt;. Vous avez apaisé un vieux tauren.", rewards = "Vous recevrez :\n\n"},
[3065] = {title = "Tablette simple", objective = "Lire la Tablette simple, et parler à Frang, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l’extérieur de l’Antre, dissimulé dans l’ombre.", progress = "Encore du renfort ! Cela me convient.\n\nVous aurez sûrement du mal à soulever une bonne arme comme une hache, mais une lance c'est déjà mieux que rien.\n\nBienvenue dans la Vallée des épreuves, <nom>.", completion = "Vous vous plairez ici, à mesure que vous vous y entraînerez. Si vous avez des questions, demandez conseil autour de vous et lorsque vous vous sentirez prêt, revenez me voir. J'ai été le maître d'armes de chaque &lt;classe&gt; de la vallée et je peux vous former... Cependant, mes leçons ont un prix.", rewards = "Vous recevrez :\n\n"},
[3082] = {title = "Tablette gravée", objective = "Parler à Jen'shan dans la Vallée des épreuves", description = "Ah, pendant votre absence, on a apporté une tablette pour vous, <nom>.\n\nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chasseurs, Jen'shan. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", progress = "Jen'shan voit un puissant <classe> devant elle et les esprits s'en réjouissent.\n\nChasser est notre plus ancienne coutume. La Horde s'est tournée vers nous quand elle se battait pour survivre dans Azeroth, implorant que nous leur apprenions nos secrets. Ceux de la Horde étaient déjà puissants ; puissants dans l'art des chamans comme dans celui des guerriers. Mais chasser, ça ils ne savaient pas encore le faire...", completion = "Maintenant, nous leur apprenons toutes ces choses et en échange, ils nous en apprennent d'autres. Nos races se sont presque unies et nous sommes des alliés de longue date. Aidez-les et Jen'shan vous aidera.\n\nJen'shan vous enseignera la voie du &lt;classe&gt;. La tribu est éternellement reconnaissante à ses chasseurs, vous verrez. Vous avez un rôle à jouer dans l'avenir, ne l'oubliez pas.\n\nAllez voir Jen'shan, elle vous apprendra tout ce qu'elle sait quand elle sentira que vous êtes prêt.", rewards = "Vous recevrez :\n\n"},
[3083] = {title = "Tablette codée", objective = "Lire la Tablette codée, et parler à Rwag, dans la Vallée des épreuves.", description = "Ah, pendant votre absence, on a apporté une tablette pour vous, <nom>.\n\nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des voleurs, Rwag. Il souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", progress = "Bienvenue dans la Vallée des épreuves, <nom>. Vous ne seriez pas ici si vous n'aviez eu ma tablette, je serai donc direct :\n\nJe suis Rwag, responsable de l'entraînement des bandits, voleurs et détrousseurs, ici dans la vallée. La Main surveillera de près vos progrès et m'a chargé de les superviser. Vous aurez une certaine liberté, mais je vous conseille de travailler dur et d'être prêt lorsqu'ils auront besoin de vos talents.", completion = "Jusqu'à nouvel ordre, vous serez sous ma tutelle. Je vais vous montrer les ficelles du métier, comme on dit. Dès que vous vous sentez apte, venez me retrouver pour poursuivre l'entraînement. Pour l'instant pratiquez ce que vous avez déjà appris, jusqu'à la maîtrise. La moindre petite compétence peut parfois sauver la vie, dans certaines situations.", rewards = "Vous recevrez :\n\n"},
[3084] = {title = "Tablette runique", objective = "Parler à Shikrik dans la Vallée des épreuves.", description = "Ah, pendant votre absence, on a apporté une tablette pour vous, <nom>.\n\nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chamans, Shikrik. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", progress = "Ah, bienvenue, <nom>. C'est un plaisir de vous voir. Les jours se faisaient longs malgré mes nombreux étudiants, mais la venue de gens tels que vous me donne beaucoup de fierté. Je me souviens de l'époque où je recevais les enseignements de vos chamans.", completion = "Comme vous le savez, c'est des éléments que nous tirons notre pouvoir. Le feu, la terre, l'eau et l'air : voilà nos outils.\n\nNotre force vient des esprits de nos ancêtres. Nous guidons notre peuple. Nous devons être pour les villes et villages où nous allons ce que Thrall est à la Horde. Ils attendent de nous protection et sagesse. Pour vous préparer, il vous faudra vous entraîner souvent. Revenez me voir avec plus de puissance et je vous enseignerai ce que je sais.", rewards = "Vous recevrez :\n\n"},
[3085] = {title = "Tablette bénie", objective = "Lire la Tablette bénie, et parler à Ken'jai, à l’extérieur de l’Antre, dans la Vallée des épreuves.", description = "Ah, pendant votre absence, on a apporté une tablette pour vous, <nom>.\n\nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des prêtres, Ken'jai. Il souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", progress = "Vous êtes ici... bravo, c'est chouette ! Les esprits m'ont dit que vous passeriez voir Ken'jai tôt ou tard. Bienvenue dans la Vallée des épreuves. Vous n'y resterez pas longtemps, mais tant que vous y êtes, profitez-en un maximum.", completion = "Vous verrez que progressivement vous contrôlerez de mieux en mieux les esprits : vous les invoquerez pour des trucs de plus en plus forts... C'est là que le bon vieux Ken'jai intervient. Venez voir le vieux Ken'jai quand vous vous sentirez prêt. Si les esprits sont d'accord, alors p'têt' qu'on vous apprendra des trucs plus puissants... Mais seulement si y sont d'accord.\n\nFilez, causez aux autres dans la Vallée. Revenez me voir plus tard.", rewards = "Vous recevrez :\n\n"},
[3086] = {title = "Tablette glyphée", objective = "Lire la Tablette glyphée, et parler à Mai'ah, près de l’entrée de l’Antre, dans la Vallée des épreuves.", description = "Ah, pendant votre absence, on a apporté une tablette pour vous, <nom>.\n\nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des mages, Mai'ah. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", progress = "On veut déjà faire plaisir à Mai'ah, <nom>. C'est bien. Si vous respectez Mai'ah, Mai'ah vous le rendra. Mais parlons peu, parlons bien, vous êtes là pour apprendre la magie, pas pour m'entendre radoter.\n\nY a qu'un truc que Mai'ah peut pas vous apprendre sur la magie, <nom>, c'est comment stopper la corruption.", completion = "Z'êtes parmi les êtres les plus puissants sur cette planète, &lt;nom&gt;... Pas de doute. Et tout le monde le sait... Faut que vous le sachiez !\n\nMais ça doit être lassant ! Car y a pas un orc, un elfe ou un nain qui vous fait peur... Mais gaffe aux trucs que vous pouvez pas voir. La magie est puissante, elle peut vous jouer des tours... Vous faire croire plus puissant que vous l'êtes. Un peu de patience et de réflexion ne sont pas du luxe.\n\nQuand vous le sentirez, revenez voir Mai'ah pour l'entraînement. Elle vous apprendra les trucs que vous devrez savoir, pas de problème.", rewards = "Vous recevrez :\n\n"},
[3087] = {title = "Parchemin gravé", objective = "Lire le Parchemin gravé, et parler à Jen'shan, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chasseurs, Jen'shan. Elle souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", progress = "Ah, vous voilà enfin. Parfait. Jen'shan vous attendait.\n\nBeaucoup pensent que c'est une voie facile, mais Jen'shan vous dit que non. Maîtriser les bêtes de Durotar et au-delà demande autant de talent que de maîtriser les arcanes ou de parler aux ancêtres.\n\nTirer à l'arc ou au fusil n'est p'têt' pas aussi périlleux pour vous que de lancer un sort, mais c'est pour sûr aussi efficace contre votre ennemi.", completion = "Quand on aura fini de causer, allez parler aux autres citoyens de la Vallée. Ils vous demanderont de faire des trucs pour eux... ça mettra vos talents à l'épreuve et vous montrera les dangers de cette contrée.\n\nQuand vous aurez gagné en expérience et en sagesse, vous aurez besoin que Jen'shan vous montre de nouvelles techniques. Revenez souvent voir Jen'shan. Je vous ferai savoir ce que je peux vous apprendre.", rewards = "Vous recevrez :\n\n"},
[3088] = {title = "Parchemin codé", objective = "Lire le Parchemin codé, et parler à Rwag, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des voleurs, Rwag. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", progress = "Chut, pas si fort. Je ne fais pas confiance à Nartok, là-bas. Ceux qui se cachent encore plus profond que moi dans une grotte ne doivent pas être pris à la légère.\n\nVous n'avez pas eu trop de problèmes pour me trouver ?", completion = "Maintenant que vous savez ou je demeure, je peux vous le dire : la Main brisée m'a demandé de m'occuper de vous. Ils veulent que je vous entraîne et que je vous informe de tout ce dont ils pourraient avoir besoin. Même si les aider ne vous intéresse pas encore (ce qui serait idiot de votre part), je ferai ce que je peux pour vous entraîner... Pour une somme modique. Revenez quand vous voulez et nous verrons ce que vous êtes capable d'apprendre.", rewards = "Vous recevrez :\n\n"},
[3089] = {title = "Parchemin runique", objective = "Lire le Parchemin runique, et parler à Shikrik, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chamans, Shikrik. Elle souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", progress = "Donc, vous voici. Je commençais à me demander quand vous daigneriez vous présenter. J'ai envoyé le parchemin il y a longtemps déjà. Je n'étais pas sûre qu'il vous soit arrivé.\n\nMais trêve de bavardage... Si vous êtes ici, c'est que vous êtes destiné à guider la vie spirituelle de notre peuple.", completion = "Ce sera par votre intermédiaire que nos ancêtres vont communiquer. Vous aurez le pouvoir des éléments à votre entière disposition. Mettre en pièce vos ennemis sera pour vous un jeu d'enfant et guérir vos alliés, aussi facile que respirer. Gardez cela à l'esprit quand vous affronterez de nouveaux défis et revenez aussi souvent qu'il vous plaira. Je serai toujours ici pour vous enseigner de nouveaux sorts et vous mettre sur le droit chemin quand vous y consentirez.", rewards = "Vous recevrez :\n\n"},
[3090] = {title = "Parchemin contaminé", objective = "Lire le Parchemin contaminé, et parler à Nartok, à l’intérieur de l’Antre, dans la Vallée des épreuves.", description = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, <nom>.\n\nJ'évite normalement de traiter avec des démonistes, si c'est possible, mais je pense que vous devriez le lire, quand vous en aurez le temps. Si je ne me trompe pas, il provient du maître qui vous a été récemment assigné, Nartok. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", progress = "Enfin, vous voilà... Et discrètement en plus. Bien.\n\nNotre monde est plein de fous, <nom>. Même le puissant Thrall n'est pas sans faille. Il néglige les moyens qui nous seraient nécessaires pour faire cette terre nôtre ! Nous ne sommes plus de ceux qui se laissaient manipuler et utiliser par les créatures du Néant. Nous sommes un peuple à part. Nous sommes fiers.... Et nous sommes forts.", completion = "Maintenant, vous aussi avez rejoint nos rangs. Ne vous méprenez pas, &lt;nom&gt;. Que vous ayez accès à un pouvoir que nombreux vous envieront ne vous fera pas accepter plus facilement. Thrall nous accepte dans Orgrimmar car nous sommes encore de la famille. Il ne peut pas se détourner de nous, ou il deviendrait aussi pitoyable que les humains qui l'ont enchaîné. Bref... Prudence. Qu'importe votre puissance, si vous agissez stupidement votre mort est certaine.\n\nSi vous souhaitez apprendre de nouveaux sort, revenez me voir.", rewards = "Vous recevrez :\n\n"},
[3091] = {title = "Note simple", objective = "Lire la Note simple, et parler à Harutt Thunderhorn, à Camp Narache.", description = "Il y a quelques instants, une messagère était à votre recherche, <nom>. Je crois qu'elle était envoyée par le Maître des guerriers, Harutt. Si ce message est bien de Harutt, je ne tarderais pas à le lire, à votre place.", progress = "Vous voici enfin, <classe>. Je n'ai pas menti dans ma lettre, <nom>. Nous sommes une race à part, un peu comme les druides ou les chamans de notre tribu. Votre importance est tout aussi grande. Nous sommes ceux sur qui l'on compte pour défendre nos frontières, chasser le centaure et partir à la guerre.", completion = "Chacun son rôle dans notre tribu. Chacun doit aussi passer par les mêmes rites. Ne laissez jamais votre orgueil vous dire le contraire.\n\nJe reste ici pour former de nouveaux guerriers qui recherchent la gloire des combats et qui suivent la voie de nos plus vénérables ancêtres. Revenez me voir après un peu d'entraînement et je ferai ce que je peux pour parfaire votre formation. Allez avec la bénédiction de la tribu, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[3092] = {title = "Note gravée", objective = "Lire la Note gravée, et parler à Lanka Farshot, sur la Mesa de Nuage rouge.", description = "Il y a quelques instants, une messagère était à votre recherche, <nom>. Je crois qu'elle était envoyée par le Maître des chasseurs, Lanka. Si ce message est bien de Lanka, je ne tarderais pas à le lire, à votre place.", progress = "Bienvenue au Camp Narache, <nom>. J'ai entendu beaucoup de bien à votre propos. Votre lignée est puissante et de nombreux anciens pensent que vos dons sont remarquables. Mais de cela nous allons nous assurer.\n\nVous aller passer un peu de temps dans les plaines de Mulgore : vous devrez en connaître les moindres recoins. Plus tard vous voyagerez en des terres inconnues pour apprendre de nouvelles techniques. Vous devez vous y préparer.", completion = "Et c'est mon rôle que de m'assurer de votre préparation en vous enseignant les bases de notre profession : comment dresser votre familier, vous servir de votre fusil et plein d'autres techniques qui vous seront nécessaires.\n\nLes chasseurs ont une part importante dans nos traditions et notre histoire, &lt;nom&gt;. N'oubliez jamais votre importance aux yeux de la tribu. Vous serez respecté et récompensé si vous servez bien notre peuple.", rewards = "Vous recevrez :\n\n"},
[3093] = {title = "Note runique", objective = "Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache.", description = "Il y a quelques instants, une messagère était à votre recherche, <nom>. Je crois qu'elle était envoyée par le Maître des chamans, Meela. Si ce message est bien de Meela, je ne tarderais pas à le lire, à votre place.", progress = "Aussi vite que l'éclair, vous voici devant moi. Votre hâte me réjouit. Car elle signifie que vous saisissez l'importance de notre rencontre et de votre venue. Je ne suis pas un guide, mais je connais les éléments et je peux parler aux esprits de notre peuple. Je vous apprendrai à faire de même.", completion = "Nous allons nous voir souvent dans les jours à venir. Vous repartirez à chaque fois avec plus de puissance... Et de préparation. Tel la Flamme éternelle, votre esprit brillera de mille feux.\n\nEn route, &lt;nom&gt;. Mettez-vous à l'épreuve. Je serai là quand vous en aurez besoin.", rewards = "Vous recevrez :\n\n"},
[3094] = {title = "Note verdoyante", objective = "Lire la Note verdoyante, et parler à Gart Mistrunner, à Camp Narache.", description = "Il y a quelques instants, une messagère était à votre recherche, <nom>. Je crois qu'elle était envoyée par le Maître des druides, Gart. Si ce message est bien de Gart, je ne tarderais pas à le lire, à votre place.", progress = "Vous êtes ici. C'est bien. Les esprits de nos ancêtres s'agitent à travers Mulgore et au-delà, mais je ne sais pas pourquoi. Ce sera désormais votre devoir que d'apprendre à écouter les esprits de la nature et d'être leur médiateur. Retenez bien cela.", completion = "Bien que nous soyons liés, ne vous attendez pas à beaucoup de sympathie de la part des elfes de la nuit. Leur orgueil les aveugle, mais cela ne nous regarde pas. Les enseignements de notre Terre-Mère sont tout ce dont vous devrez vous occuper et je vous apprendrai ce que je sais à mesure que votre sagesse grandira.\n\nRevenez souvent me voir, &lt;nom&gt;. Vous découvrirez que la Terre-Mère accorde des dons incroyables aux plus dévoués.", rewards = "Vous recevrez :\n\n"},
[3095] = {title = "Parchemin simple", objective = "Lire le Parchemin simple, et parler à Dannal Stern, au Glas.", description = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des guerriers, Dannal. À votre place, je prendrais le temps de le lire avant de repartir.", progress = "Ah, vous voici. Bien. On m'a informé que quelques autres étaient parvenus à échapper à la \"mort\" et devaient arriver en ville. Peut-être que tant de résistance servira à l'avenir.\n\nVous pouvez remercier Dame Sylvanas pour votre liberté... Liberté de corps et d'esprit. La Peste et ses effets vous torturent encore, mais vous pouvez aller et venir librement, selon vos désirs.", completion = "Je serai là pour vous aider à mesure que vous gagnerez de l'expérience... Venez me trouver aussi souvent que vous le souhaitez. Mes honoraires sont peut-être bas, mais tout ce que je vous apprendrai vous sera de la plus grande utilité.\n\nPartez, mettez à l'épreuve votre technique. Vous connaîtrez bien d'autres choses avec l'expérience, même certaines choses dont je ne peux vous parler ici. Sachez juste que Sylvanas aura besoin de guerriers dans votre genre dans le futur. Vous serez le fondement de notre salut. Ne l'oubliez pas.", rewards = "Vous recevrez :\n\n"},
[3096] = {title = "Parchemin codé", objective = "Lire le Parchemin codé, et parler à David Trias, au Glas.", description = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des voleurs, David Trias. À votre place, je prendrais le temps de le lire avant de repartir.", progress = "Alors vous avez réussi ? Bien. Avec le temps, nous allons avoir besoin de beaucoup d'autres voleurs. Les Traqueurs des ténèbres finiront sûrement par vous trouver au moment qu'ils trouveront opportun, donc évitez les gaffes ou les choses que vous pourriez regretter. Ils ont besoin d'agents doués... Pas de pickpockets et d'idiots.", completion = "Je passe le plus clair de mon temps ici à l'auberge, à garder un oeil sur les têtes nouvelles et sur les projets prometteurs. Restez en dehors des mauvais coups et je vous apprendrai quelques trucs. Revenez me voir quand vous le voulez, nous verrons bien si vous pouvez acquérir une technique ou deux.", rewards = "Vous recevrez :\n\n"},
[3097] = {title = "Parchemin béni", objective = "Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l’église du Glas.", description = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des prêtres, Duesten. À votre place, je prendrais le temps de le lire avant de repartir.", progress = "Ah, donc malgré le feu, la peste, les émeutes et même pire, mes \"fidèles\" se présentent toujours plus nombreux à ma porte. Eh bien, je vous souhaite la bienvenue, <classe>. Accordez-moi un moment pour vous expliquer une chose ou deux avant que vous ne choisissiez votre voie : le Feu Sacré ne vous concerne plus, les esprits de vos ascendants ne sont que des fables et les créatures du Néant ne vous veulent pas.\n\nJusqu'ici vous suivez ?", completion = "Il y a une chose que vous devez savoir : nous avons survécu grâce à notre seule volonté. C'est notre foi en nous-même qui nous distingue des autres. Et avec nos pouvoirs, nous allons bouleverser la totalité d'Azeroth. Le faible cherchera votre protection. Les lépreux vous appelleront Prince. Et l'ignorant cherchera vos conseils. C'est mon devoir que de m'assurer que vous disposiez de tous les outils nécessaires quand le temps viendra. A mesure que vous gagnerez en expérience, venez me voir. Je vous donnerai de plus puissants pouvoirs.", rewards = "Vous recevrez :\n\n"},
[3098] = {title = "Parchemin glyphé", objective = "Lire le Parchemin glyphé, et parler à Isabella, dans l’église du Glas.", description = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des mages, Isabella. À votre place, je prendrais le temps de le lire avant de repartir.", progress = "Je savais que vous viendriez à moi, <nom>. Non parce que vous manquez de volonté pour suivre votre propre chemin, mais parce que nous sommes des esprits semblables. Nous avons tous deux ressenti la douleur. Nous avons souffert. Et désormais nous réclamons ce qui nous revient de droit : cette terre, nos vies, nos destinées. Mais il vous reste encore beaucoup à apprendre.", completion = "Revenez souvent me voir si vous souhaitez avoir la puissance suffisante pour écraser nos opposants. Les règles de la magie s'appliquent aussi à vous, &lt;nom&gt;. Vous sentirez toujours la corruption vous suivre comme une meute de loups affamés dans la nuit. Sa caresse ne sera pas sans créer une certaine dépendance, un vieux compagnon qui voudrait toujours être à vos côtés. Mais il y a moyen de contrer ces effets. Ces choses ne vous contrôlent que si vous les laissez faire.\n\nPartez maintenant, revenez vers moi quand vous aurez gagné en puissance.", rewards = "Vous recevrez :\n\n"},
[3099] = {title = "Rouleau contaminé", objective = "Lire le Rouleau contaminé, et parler à Maximillion, au Glas.", description = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des démonistes, Maximillion. À votre place, je prendrais le temps de le lire avant de repartir.", progress = "Soyez le bienvenu, mon frère. Je savais que vous viendriez. Ce n'était qu'une question de temps.\n\nCe que je vous ai dit vous a intéressé, n'est-ce pas ? J'ai touché une corde sensible... Quelque chose en vous savait que je parlais vrai. Bien.\n\nRetenez ceci cependant : je ne suis pas un traître à Sylvanas. Quoi qu'il en soit, elle comprendrait mes paroles sachant que ce sont ses propres idées qui ont mis les Réprouvés là où ils sont maintenant.", completion = "J'ai dit qu'un esclave restait un esclave, quel que soit le maître. Vous vous souvenez ? Nous savons tous les deux que c'est ce genre de contrôle - ce genre de pouvoir - qui nous motive maintenant. Nous cherchons à asservir des créatures. Nous savons que nous sommes plus puissants et méritons plus de respect que nous n'en recevons... Et maintenant, nous voulons conquérir ce respect.\n\nJe serai votre allié dans ce combat - le combat pour notre propre liberté. Liberté de trouver nos propres allégeances. Quand vous serez prêt, revenez me voir et je vous apprendrai tout ce que je sais.", rewards = "Vous recevrez :\n\n"},
[3100] = {title = "Lettre simple", objective = "Lire la Lettre simple et parler à Llane Beshere, à l’Abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de Llane, notre Maître des guerriers local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", progress = "Ah, vous avez eu ma lettre, <nom>... Bien.\n\nIl y a une grande affluence de guerriers à Elwynn ces temps-ci : ce qui est bon pour Stormwind, mais mauvais pour les kobolds et les Défias de la région", completion = "Renseignez-vous, repérez la topographie du terrain et revenez me voir quand vous aurez besoin d'entraînement. Je serai là de jour comme de nuit.\n\nLes chevaliers de la Main d'Argent ont rendu cet endroit très sûr, mais à mesure que vous rencontrerez d'autres citoyens, vous verrez qu'ils ont de petits problèmes qui ne sauraient être résolus sans l'aide d'un &lt;classe&gt;. Bonne chance.", rewards = "Vous recevrez :\n\n"},
[3101] = {title = "Lettre consacrée", objective = "Lire la Lettre consacrée, et parler à Frère Sammuel, à l’Abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de frère Sammuel, notre Maître des paladins local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'abbaye.", progress = "Enfin ! Nous nous rencontrons, de frère à frère. Bienvenue à Northshire. Vous y séjournerez le temps d'apprendre nos techniques, mais sachez que Stormwind n'est pas très loin et que tôt ou tard vos pas vous y mèneront. En attendant, usez de patience... Chevalier de la Main d'Argent.", completion = "Par ailleurs, une ou deux choses à savoir. Pour beaucoup sur cette terre vous êtes un modèle : agissez en conséquence. Le Feu Sacré brille à travers vous et cela sera visible autant pour vos alliés que vos ennemis.\n\nAussi, à mesure que vous gagnerez en sagesse et en puissance, vous aurez besoin de vous former à de nouvelles techniques. C'est là que j'interviens. Quand vous sentirez que vous aurez gagné en expérience ici à Northshire, revenez me voir et je vous enseignerai ce que vous pourrez apprendre. Bonne chance... &lt;classe&gt; !", rewards = "Vous recevrez :\n\n"},
[3102] = {title = "Lettre codée", objective = "Lire la Lettre codée, et parler à Jorik Kerridan, dans l’écurie, derrière l’Abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de Jorik, l'un de nos Maîtres locaux. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", progress = "Vous voici, en un seul morceau et sans vous faire remarquer. Parfait. Je n'aime pas trop me faire remarquer dans le coin... Je suis plutôt discret. Vous comprenez.\n\nDéjà eu quelques ennuis ? Jamais ? c'est parfait. Cela changera bien assez tôt.", completion = "Vous découvrirez que de nombreux groupes convoitent nos talents, &lt;nom&gt;. Des aventuriers, le SI:7... même la Confrérie défias voudrait bien placer un espion ou deux au sein de Stormwind. Mais n'oubliez jamais que vous n'appartenez qu'à vous. Ne laissez jamais qui que ce soit vous embarquer dans une affaire dont vous ne voulez pas ! De plus, nous avons tous les atouts en main... du moins avant que les jeux ne soient faits. Vous voyez ce que je veux dire ?\n\nBon, je voulais juste me présenter et vous dire que j'étais là si vous aviez besoin d'un entraînement. Passez quand vous voulez.", rewards = "Vous recevrez :\n\n"},
[3103] = {title = "Lettre bénie", objective = "Lire la Lettre bénie, et parler à la prêtresse Anetta, à l’abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de la prêtresse Anetta, notre Maître des prêtres local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'abbaye.", progress = "Ah, vous voici enfin. Je savais que vous trouveriez votre chemin jusqu'à moi. Le Feu Sacré brille au-dessus de vous et la voie que vous avez choisie. Les temps sont durs : la Légion ardente est toujours bien présente sur Azeroth, Kalimdor cherche de nouvelles façons de se défendre contre ses propres tribulations et c'est à vous qu'il revient d'aider autant de monde que possible.", completion = "A mesure que vous prendrez de l'expérience, revenez me voir et je ferai ce que je peux pour vous faire profiter de mon savoir. En attendant, partez le coeur rempli de compassion et laissez la sagesse vous guider. Souvenez-vous que le monde ne devient meilleur que si vous contribuez à le rendre ainsi.", rewards = "Vous recevrez :\n\n"},
[3104] = {title = "Lettre glyphée", objective = "Lire la Lettre glyphée, et parler à Kheldon Bremen, à l’intérieur de l’Abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de Kheldon, notre Maître des mages local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", progress = "Bonjour, <nom>. Je suis Kheldon. Que puis-je faire pour vous ?", completion = "Ha ha, je savais bien que mes mises en garde ne seraient d'aucun effet. Donc vous n'avez pas peur ? Pas peur d'accepter votre destin ? Pas peur de défier les dieux et toutes les autres forces qui se dresseront entre vous et la poursuite du savoir et du pouvoir ?\n\nJe ne vous mens pas, &lt;nom&gt;, vous inspirerez autant de crainte que de respect. Mais sachez aussi que je serai là si vous avez besoin d'entraînement. Venez me trouver pour gagner en puissance.", rewards = "Vous recevrez :\n\n"},
[3105] = {title = "Lettre contaminée", objective = "Lire la Lettre contaminée, et parler à Drusilla La Salle, à proximité de l’Abbaye de Northshire.", description = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, <nom>. Il s'agit d'une lettre portant le sceau de Druisilla, l'un de nos Maîtres locaux. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", progress = "Ah, vous voici, <nom>. J'ai failli attendre. Quelques gardes étaient ici il y a peu de temps et m'observaient curieusement… Quels pitoyables idiots.", completion = "Plus vous gagnerez en puissance, plus vous serez tenté. Vous devez toujours veiller à vous contrôler. Je ne vous mentirai pas, la corruption s'en prend à tous les étudiants des arcanes ; surtout ceux qui affrontent les créatures du Néant distordu. Patience et prudence... Mais ne refoulez pas vos ambitions.\n\nQuand vous aurez plus de puissance, revenez me voir et je vous en apprendrai plus sur notre art.", rewards = "Vous recevrez :\n\n"},
[3106] = {title = "Rune simple", objective = "Lire la Rune simple, et parler à Thran Khorman, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des guerriers, Thran. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Fait sacrément froid, pas vrai ? C'est comme si la neige elle partait jamais, <nom>.\n\nZ'avez déjà remarqué, mais y a plus de gnomes chez nous. C'est parce qu'il sont partis et ont fait sauter leurs maisons. Ne le dites pas à tout le monde, mais on ne peut pas trop leur en vouloir : je pense que moi aussi j'en serais venu aux explosifs si Ironforge était infestée de Sombrefer ou autres.", completion = "Deux ou trois autres chose que vous verrez aussi, juste pour vous prévenir : des nains qui s'battent avec de la magie au lieu d'un fusil. Ou encore certains d'entre nous qui vénèrent le Feu Sacré comme le font certains humains et enfin, des troggs. Vous en saurez un peu plus sur eux plus tard, mais sachez que je suis là pour vous aider.\n\nJe vous apprendrai comment devenir un vrai &lt;classe&gt;. Si vous pensez avoir besoin d'entraînement, passez me voir et je verrai ce que je peux faire.", rewards = "Vous recevrez :\n\n"},
[3107] = {title = "Rune consacrée", objective = "Lire la Rune consacrée, et parler à Bromos Grummner, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des paladins, Bromos. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Donc vous voici ! Pile au bon moment. Il y a beaucoup à faire dans la Vallée des Frigères et au-delà. Je vais avoir besoin de votre aide au moins autant que vous aurez besoin de la mienne !\n\nVous êtes un chevalier de la Main d'Argent désormais, préparez-vous à jouer votre rôle.", completion = "Les humains nous ont appris des tas de choses sur le Feu Sacré et à quel point cet ordre était important pour eux... et pour la protection d'Azeroth. Nous avons beaucoup de respect pour cette tradition bien ancrée. D'une seule action, d'un seul sacrifice peut dépendre la douleur ou le salut.\n\nNous allons travailler ensemble pour un petit moment. Revenez me voir quand vous voudrez vous entraîner. Il ne faudrait pas partir à l'inconnu sans préparation, n'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[3108] = {title = "Rune gravée", objective = "Lire la Rune gravée, et parler à Thorgas Grimson, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des chasseurs, Thorgas. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Vous voici enfin ! Heureux de vous voir ! Je parie que vous n'avez pas eu trop de peine à me trouver. Ha ha!\n\nNotre profession est très ancrée dans les traditions, <nom>. Connaître la nature du terrain. Apprendre à traquer un ours dans les montagnes. Même simplement survivre seul grâce à sa seule intelligence demande beaucoup de courage et d'effort. Vous pensez en être capable ?", completion = "Souvenez-vous toujours qu'il vous faut respecter le monde dans lequel vous vivez. Les bêtes qui se battent à vos côtés ; l'éclat de vos armes ; le poids de vos munitions ; la morsure amère du vent ; tous ces détails doivent vous être familiers.\n\nJe ferai ce que je peux pour vous aider mais ce sera à vous de faire le gros du travail. Repassez me parler quand vous voudrez. Je vous entraînerai quand je pourrai.", rewards = "Vous recevrez :\n\n"},
[3109] = {title = "Rune codée", objective = "Lire la Rune codée, et parler à Solm Hargrin, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des voleurs, Solm. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Vous voilà ! Génial !\n\nNotre activité marche bien en ce moment alors je suis content de pouvoir compter un autre membre du clan Ironforge dans nos rangs. Trop d'entre nous à mon goût se tournent vers l'arcane et le divin. J'ai rien contre eux ou leurs croyances, mais y a rien de tel qu'une lame froide entre vos mains ou qu'un coin d'ombre où se dissimuler, voyez c'que j'veux dire ?", completion = "De toute façon, lorsque vous commencerez à explorer les Frigères, vous aurez sans doute besoin de formation à un moment ou à un autre. Revenez me voir à chaque fois que vous en ressentirez le besoin et je vous enseignerai ce que je sais. Une astuce, une manoeuvre... Vous savez, le genre de truc qui vous garde en vie et vous permet de gagner quelques piécettes.\n\nGardez l'oeil sur vos amis gnomes également... Ils sont bien esseulés depuis la destruction de Gnomeregan et ils auront besoin de notre aide pour se sentir chez eux ici.", rewards = "Vous recevrez :\n\n"},
[3110] = {title = "Rune bénie", objective = "Lire la Rune bénie, et parler à Branstock Khalder, à Anvilmar.", description = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des prêtres, Branstock. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Ah ! Vous êtes ici, <nom> ! Formidable !\n\nJe désespérais de votre arrivée, j'avais presque perdu foi en vous... Ha ha, perdre la foi ? C'est une blague... Bah, c'est pas grave. Vous n'êtes pas venu pour entendre mes mauvaises blagues.", completion = "Je suis celui qui pourra vous entraîner à mesure que vous connaîtrez un peu mieux la vallée des Frigères. Revenez me voir quand vous vous sentirez d'attaque et je verrai les nouveaux sorts que je pourrai vous apprendre pour faire déguerpir ces maudits troggs de notre vallée.\n\nLa Lumière est avec vous, et avec tout Ironforge, &lt;nom&gt;... On ne vous forcera pas à devenir quoi que soit de particulier.", rewards = "Vous recevrez :\n\n"},
[3111] = {title = "<INUTILISÉ> [PÉRIMÉ]", objective = "Parler à Marrek Stromnur à Courbenclume.", description = "Il y a bien longtemps, les hauts-elfes nous ont appris les secrets de la magie ainsi qu’à nos alliés humains. Ils nous ont mis en garde sur les règles à suivre et contre la folie qu’elle peut provoquer ! Mais n’y croyez pas. Nous sommes différents des elfes ; nous n’avons pas les mêmes faiblesses. Restez sur le droit chemin et vous verrez que la magie est aussi puissante en tant qu’outil qu’en tant qu’arme.\n\nVenez me chercher à Courbenclume. Je vous y attendrai !\n\n- Marrek Stromnur, Maître des magesLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[3112] = {title = "Note de service simple", objective = "Lire la Note de service simple, et parler à Thran Khorman, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des guerriers, Thran. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Ah, tiens, un autre mémorandum de la part d'un <race> en mission... Comme c'est singulier.\n\nNon, non, je ne suis pas en train de vous taquiner. Je respecte votre ténacité, vous pouvez en être sûr. Je serais certainement aussi en rogne si Ironforge était assailli par des nains Sombrefer, donc n'allez pas penser que je ne partage pas vos préoccupations...", completion = "Bon, comme c'est votre premier ordre de mission, j'ai reçu l'ordre de tout faire pour vous préparer à reprendre votre terre... Et c'est ce que je m'apprête à faire.\n\nC'est quand vous voulez. Revenez voir le bon vieux Thran et je serai ravi de vous faire partager mon savoir. Ce ne sera pas gratuit, mais ce ne sera pas cher non plus. Bonne chance.", rewards = "Vous recevrez :\n\n"},
[3113] = {title = "Note de service codée", objective = "Lire la Note de service codée, et parler à Solm Hargrin, dans la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des voleurs, Solm. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Ravi de voir que vous avez reçu ma note et que vous êtes ici. Désolé pour l'imposture avec la note de vos supérieurs... N'y voyez aucun mal. Les gens comme nous doivent être solidaires avec les nôtres.\n\nBeaucoup pensent que ce n'est pas une bonne chose que d'avoir nos deux espèces dans la même ville, mais je pense que ça peut marcher. Pas vrai ?", completion = "J'essaie de bien me tenir par ici pour éviter que ça se retourne contre nous quand des choses disparaissent, mais si vous avez besoin de quoi que ce soit, d'entraînement ou autre, revenez me voir quand vous voulez.\n\nOn se comprend. On sait bien qu'on peut toujours compter sur la famille... Et c'est ce qui se passe en ce moment, non ? Que nous importe que Gnomeregan soit... envahi, ou que quoi que ce soit d'autre n'advienne, on peut compter sur les autres. Pas vrai ?", rewards = "Vous recevrez :\n\n"},
[3114] = {title = "Note de service glyphée", objective = "Lire la Note de service glyphée, et parler à Marryk Nurribit, dans Anvilmar, au-dessus de la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des mages, Marryk. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.", progress = "Ouais, qu'est-ce qui y a ? Plus fort, si ça vous gêne pas, <nom>. J'entends plus très bien après quelques bières.", completion = "Oh, oui ! Les arts des arcanes… bien sûr.\n\nVoici ce qu'il vous faut savoir, &lt;nom&gt; : pas la peine de trop en faire. Gardez quelques pièces pour me payer une bière… ou un sort quelconque dont vous auriez envie. Et n'approchez pas de Gnomeregan. À part ça, bonne journée ! Je serai là si vous avez besoin de moi ou d'une leçon... ou de quoi que ce soit.", rewards = "Vous recevrez :\n\n"},
[3115] = {title = "Note de service contaminée", objective = "Lire la Note de service contaminée, et parler à Alamar Grimm, dans Anvilmar, au-dessus de la Vallée des Frigères.", description = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des démonistes, Alamar. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur d'Anvilmar, quand vous en aurez le temps.\n\nEt faites attention, <nom>, on n'apprécie pas trop votre espèce, sur ces terres.", progress = "Formidable ! Vous avez bien reçu mon mémorandum.\n\nIgnorez les idiots qui vous entourent, <nom>. Le Feu Sacré ?! L'épée et le bouclier ?! Ce ne sont pas des voies pour des gens ouverts d'esprit tels que nous. Regardez ce que la magie \"normale\" a fait de notre patrie. Et à cause de ces maudits bricoleurs, notre race a bien failli s'éteindre. Nous devons désormais compter sur les nains : or, ceux-là préfèrent passer leur temps à s'allier aux humains plutôt qu'à nous aider à reconstruire notre maison. Nous sommes des citoyens de seconde zone. Avez-vous seulement vu comment ils nous regardent ?", completion = "Mais peu importe. Ce qui compte c'est que vous ayez vu votre propre Feu Sacré ! Vous connaissez la véritable origine du pouvoir. Vous comprenez qu'avoir nos propres alliés est bien plus... prudent. Des alliés particuliers. Des alliés qui, quelle que soit la mission, l'accompliront jusqu'au bout.\n\nEt c'est là que j'interviens, &lt;nom&gt;. Je peux vous apprendre les rudiments de ces pouvoirs spéciaux. Venez souvent me chercher et je vous apprendrai de nouveaux sorts.", rewards = "Vous recevrez :\n\n"},
[3116] = {title = "Sceau simple", objective = "Lire le Sceau simple, et parler à Alyissia, à Sombrevallon.", description = "Ce sceau m'a été donné par un messager de notre Maître des guerriers, Alyissia. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", progress = "Vous êtes ici. Bravo.\n\nBeaucoup de choses se sont passées au cours de ses dernières années, <nom> : la création de Teldrassil, la corruption de nombreuse créatures de la forêt ici et ailleurs, la découverte de terres que nous pensions perdues comme Feralas... Tellement de choses, en si peu de temps. Mais ce ne sont qu'une partie des raisons qui nous amènent ici, la raison principale étant de protéger notre espèce contre les périls à venir.", completion = "Bientôt vous verrez d'autres gens, de races différentes, dans les branches de notre maison. Que cela ne vous chagrine pas : ils sont les bienvenus. Ils nous aideront quand ils pourront. Ils ne seront pas tous aussi altruistes, mais ils méritent tout de même notre confiance.\n\nMais cela n'a pas vraiment d'importance. Maintenant parlons de vous et de la façon dont vous aiderez notre peuple. C'est pour ça que je suis ici. Je vous apprendrai la voie du &lt;classe&gt; à mesure que vous gagnerez en force. Revenez me voir quand vous le souhaiterez et je ferai ce que je peux pour vous aider.", rewards = "Vous recevrez :\n\n"},
[3117] = {title = "Sceau gravé", objective = "Lire le Sceau gravé, et parler à Ayanna Everstride, au sommet d'Aldrassil, dans Sombrevallon.", description = "Ce sceau m'a été donné par un messager de notre Maître des chasseurs, Ayanna. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", progress = "Vous voici et pile au bon moment, <nom>. Bienvenue à Sombrevallon.\n\nJe constate que vous avez eu mon message.\n\nComme je vous l'ai déjà dit, je suis là pour former à la voie du <classe> ; à dresser les bêtes qui vous aideront dans la bataille ; à tirer à l'arc avec précision ; à respecter nos terres et celles alentours.", completion = "A mesure que vous comprendrez ce que Sombrevallon peut vous apporter, venez me trouver. Je vous montrerai quel est le rôle d'un &lt;classe&gt; et ce dont vous êtes capable.\n\nLes temps sont dangereux, &lt;nom&gt;, ne vous fiez pas trop aux talents de vos familiers : certaines choses en ce monde sont bien plus dangereuses que vous ne le pensez. Qu'Elune soit avec vous et revenez bientôt.", rewards = "Vous recevrez :\n\n"},
[3118] = {title = "Sceau codé", objective = "Lire le Sceau codé et parler à Frahun Shadewhisper, à Sombrevallon.", description = "Ce sceau m'a été donné par un messager de notre Maître des voleurs, Frahun. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", progress = "Bonjour, <nom>. Vous m'avez trouvé, c'est bien. Je pensais que vous aviez pu vous perdre.\n\nPas grand-chose de neuf dans Sombrevallon depuis mon dernier message, mais ce sera à vous de collecter les nouvelles. Si vous le voulez, vous pouvez parler aux autres gens autour d'Aldrassil.", completion = "D'ici là, sachez que nous sommes très demandés en ces temps troublés. La paix avec les autres races peut se briser à tout moment et on parle beaucoup de membres de la Horde qui chercheraient à semer les graines de la discorde. N'oubliez pas ça.\n\nRepassez me voir quand vous aurez acquis plus de puissance et d'entraînement. Je veillerai à vous entraîner d'avantage. Il est vital que vous sachiez bien manier votre arme de prédilection, entre autres choses.", rewards = "Vous recevrez :\n\n"},
[3119] = {title = "Sceau béni", objective = "Lire le Sceau béni, et parler à Shanda, à Aldrassil.", description = "Ce sceau m'a été donné par un messager de notre maître des prêtres, Shanda. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", progress = "C'est bien, vous avez fait vite, <nom>. Bienvenue.\n\nComme vous avez dû l'entendre, tout Teldrassil ne vit que par les voyageurs qui y passent. Même des membres de l'Alliance ont été admis dans les branches de Teldrassil afin d'y rencontrer d'autres Kaldorei qui se préparent à de nouvelles aventures.", completion = "Ne vous préoccupez pas trop du monde qui s'étend sous Teldrassil pour le moment. Chaque chose en son temps. Allez parler aux autres gens de Sombrevallon : ils vous en diront plus sur ce qui s'y est passé. Aidez de la façon dont vous pourrez et si vous sentez le besoin de plus d'entraînement, passez me voir et je vous apprendrai ce que je peux.", rewards = "Vous recevrez :\n\n"},
[3120] = {title = "Sceau verdoyant", objective = "Lire le Sceau verdoyant, et parler à Mardant Strongoak, dans l'arbre Aldrassil de Sombrevallon.", description = "Ce sceau m'a été donné par un messager de notre maître des druides, Mardant. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", progress = "Ah, jeune <classe>. Je vois que vous souhaitez poursuivre vos études. C'est bien.\n\nJe me demandais si vous aviez déjà passé beaucoup de temps dans le Rêve d'émeraude ? Peut-être manquez-vous encore un peu d'expérience pour cela... Vous y viendrez, j'en suis sûr.\n\nMais en attendant nous devons parler d'autres choses.", completion = "Je serai votre mentor et guide pour un certain temps. C'est mon devoir que de vous enseigner comment interpréter non seulement ce que les esprits nous communiquent, mais aussi la complexité et les secrets du Rêve d'émeraude.\n\nEn gagnant de l'expérience et de la puissance, vous en saurez plus sur notre transe des dormants. Mais d'ici là, revenez me voir aussi souvent que vous le voudrez et je vous enseignerai la voie qui est la nôtre.", rewards = "Vous recevrez :\n\n"},
[3121] = {title = "Une Requête étrange", objective = "Porter la tête réduite à Neeru Fireblade à Orgrimmar.", description = "Neeru Fireblade à Orgrimmar a ce qu'il me faut pour travailler ici ! Il a préparé un mélange dont j'ai besoin pour... Enfin vous verrez.\n\nMettez-vous en chemin pour Orgrimmar. Tenez, prenez ceci. C'est une tête réduite que j'ai promise à Neeru en échange des herbes. C'est la tête d'un pauvre nain qui a croisé ma route dans la forêt. Je suis certain que Neeru appréciera.\n\nVous trouverez Neeru dans la Faille de l'ombre.", progress = "Oui ?", completion = "J'attendais qu'Uzer'i m'apporte ceci...\n\nJe vais vous donner le mélange d'herbes que j'ai préparé pour son... Enfin, pour ses expériences...", rewards = "Vous recevrez :\n\n"},
[3122] = {title = "Retourner voir le sorcier-docteur Uzer'i", objective = "Livrer une Poche d'herbes de Neeru au Sorcier docteur Uzer'i, en Feralas.", description = "Voici les herbes, <nom>. Portez-les au sorcier-docteur Uzer'i.\n\nDites-lui que je suis très content de la tête réduite.", progress = "Avez-vous parlé à Neeru ?", completion = "C'est exactement ce dont j'avais besoin pour préparer le vaisseau miniature, &lt;nom&gt;. On verra bientôt si mes dernières incantations sont aussi puissantes que prévu.\n\nUn instant, s'il vous plaît. Je dois célébrer le rituel et utiliser les herbes.", rewards = "Vous recevrez :\n\n"},
[3123] = {title = "Test du récipient", objective = "Partez pour les Hinterlands et localisez les Indomptables. Tuez-en 10, puis utilisez le Récipient de muisek pour faire rétrécir et capturer les Indomptables vaincus.\n\nRamenez 10 Indomptables miniaturisés et le Récipient d'Indomptables miniaturisés au sorcier-docteur Uzer'i, en Feralas.", description = "Il va s'agir d'un test, qui mettra à l'épreuve le rituel que j'ai accompli comme vos capacités. Prenez ce récipient, <nom>. Avec cela, vous pourrez réduire la taille des créatures et les y capturer.\n\nPartez pour les Hinterlands et cherchez des bêtes connues sous le nom d'Indomptables. C’étaient autrefois les animaux de compagnie de la déesse des elfes de la nuit, Elune. Vos cibles sont les Chouettards, des Indomptables vicieux, primitifs et sauvages, <nom>. Tuez-en 10, puis utilisez le Récipient de muisek pour les faire rétrécir et les capturer avant que leurs esprits ne s'échappent.", progress = "Avez-vous pu capturer un Indomptable ?\n\nSi vous avez réussi, nous pourrons réduire et capturer les créatures de Feralas.", completion = "Après une mort violente, il se peut que le muisek d'une créature s'échappe et cherche à se venger. Rétrécir les créatures, comme vous l'avez fait, &lt;nom&gt;, empêche le muisek de s'échapper. Maintenant, nous pouvons en faire ce que nous voulons.", rewards = "Vous recevrez :\n\n"},
[3124] = {title = "Hippogryphe miniaturisé", objective = "Tuer 10 Hippogryphes Aigreplume de n'importe quel type, puis utiliser le Vaisseau de muisek pour les faire rétrécir et les capturer.", description = "Puisque vous avez montré que vous êtes à la fois digne de confiance et <doué/douée> pour utiliser le Vaisseau de muisek, je souhaite à présent que vous capturiez une autre créature.\n\nLes hippogryphes ont été les compagnons loyaux des elfes de la nuit durant plusieurs années. Leur esprit est résolu et ferme.\n\nVotre tâche consiste à tuer 10 hippogryphes Aigreplume et de rapidement les faire rétrécir et les capturer avec le vaisseau, afin que leur muisek soit préservé. Vous trouverez les hippogryphes dans les Plateaux sauvages au sud d'ici.", progress = "Avez-vous pu capturer des hippogryphes ?", completion = "Une fois l'animal tué, si nous laissons sa version miniature s'échapper, il risque de prendre l'apparence d'un créature plus grande encore. Nous ne serions plus jamais à l'abri de sa vengeance.\n\nC'était une mission dangereuse, &lt;nom&gt;. Une fois de plus, vous l'avez bien accomplie.", rewards = "Vous recevrez :\n\n"},
[3125] = {title = "Dragon féérique miniaturisé", objective = "Tuer 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Vaisseau de muisek pour faire rétrécir et capturer les dragons féeriques vaincus.", description = "À présent, <nom>, je souhaite que vous capturiez une créature fragile en apparence, mais dont l'esprit puissant nous intéresse. Je veux parler des dragons féeriques. Ils ont été les alliés des elfes de la nuit. Nous devons en capturer afin que la Horde puisse également bénéficier de cette force spirituelle.\n\nVoici le Vaisseau, <nom>. Tuez 8 Fées fléchetteuses ou Petits dragons féeriques, et capturez leur muisek. On peut en trouver à l'ouest d'ici.", progress = "Avez-vous pu capturer le muisek des dragons féeriques ?", completion = "Merci, &lt;nom&gt;. Le pouvoir spirituel du dragon féerique nous sera désormais disponible.\n\nJ'espère que cela ne vous gêne pas d'accomplir une autre mission pour moi.", rewards = "Vous recevrez :\n\n"},
[3126] = {title = "Tréant miniaturisé", objective = "Tuer 3 Marcheurs des bois errants. Utiliser le Vaisseau de muisek pour faire rétrécir et pour capturer les tréants vaincus.", description = "Les marcheurs des bois errants que l'on peut voir vagabonder sous les arbres sont nos prochains objectifs, <nom>. Pour combattre la Horde, les elfes de la nuit ont enrôlé des tréants comme alliés. Ils ont beau être lents, leur rôle de protecteurs n'est pas négligeable.\n\nNous pourrons bientôt utiliser cette puissance à notre profit.\n\nTrouvez trois Marcheurs des bois errants. Tuez-les, puis utilisez le Vaisseau de muisek pour les réduire et les capturer.", progress = "Avez-vous réussi à capturer les Marcheurs des bois errants ?", completion = "Merci, &lt;nom&gt;. Notre collection de miniatures est presque complète.", rewards = "Vous recevrez :\n\n"},
[3127] = {title = "Géant des montagnes miniaturisé", objective = "Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient de muisek pour faire rétrécir et pour capturer les Géants des montagnes.", description = "La dernière chose que je vous demande est de partir vers le nord-ouest pour trouver l'ennemi final.\n\nLes géants des montagnes ont quitté leurs montagnes pour aider les elfes de la nuit quand la Légion ardente est apparue. Vous les reconnaîtrez à leur stature massive ainsi qu’aux vibrations du sol à mesure que vous avancerez dans leur contrée rocailleuse.\n\nJ'ai à cœur de maîtriser une puissance d'une telle taille. Tuez 7 géants des montagnes puis utilisez le Récipient pour capturer leur puissant muisek.", progress = "Avez-vous pu capturer des géants des montagnes ?", completion = "Imaginez les possibilités offertes par ce que nous possédons désormais, &lt;nom&gt;. Grâce à ce que vous avez collecté, je suis désormais capable de placer la version miniature de ces créatures dans tout ce que je désire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3128] = {title = "Matériaux Naturels", objective = "Apporter 2 Bûches fendues, 6 Minerais incrustés, 20 Morceaux de tendons résistants et 40 Fragments métalliques au sorcier-docteur Uzer'i au Camp Mojache.", description = "Je vais avoir besoin d'autres choses pour finir ce que j'ai commencé... Vous devrez me rendre ce service avec d'autres choses que je vous donnerai à faire.\n\nJ'aurai besoin de bûches fendues de tréant de Feralas. Du minerai incrusté, que l'on peut trouver sur les géants des montagnes ou les dragons féeriques, à l'ouest. Aussi, trouvez-moi des tendons résistants des chouettards des Hinterlands ou des hippogryphes de Feralas. Enfin, il me faudrait une grande quantité de fragments métalliques de chacune des créatures mentionnées.", progress = "Avez-vous réussi à collecter les éléments dont j'ai besoin ?", completion = "Excellent ! Ces matériaux, couplés aux miniatures, devraient donner les résultats attendus.", rewards = "Vous recevrez :\n\n"},
[3129] = {title = "Armes de l'Esprit", objective = "Le sorcier-docteur Uzer'i veut que vous patientez tandis qu'il prépare les armes.", description = "Imprégner les armes de l'esprit des miniatures est un processus difficile. Maintenant que nous avons les matériaux nécessaires et les miniatures des créatures que vous avez capturées, je peux commencer. Attendez ; je reviens dans un moment.", progress = nil, completion = "Comme promis, vous avez le choix, &lt;nom&gt;. Les miniatures de ces créatures ont été scellées à jamais dans le pouvoir de ces armes.\n\nVous pourrez désormais manier leur énergie comme si c'était la vôtre. Usez-en à bon escient.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nForce de l'hippogrypheEsprit du dragon féériqueForce du tréantVolonté du géant des montagnes\n\nVous recevrez également :\n\n"},
[3130] = {title = "Contre les Hainecrête", objective = "Se présenter devant Latronicus Moonspear au bastion de Feathermoon.", description = "À présent, je vais vous diriger vers mon second, Latronicus. Il a gardé un oeil attentif sur les forces des nagas jusqu'alors. J'estimerai la situation générale ici selon les nagas. Non pas que je veuille envoyer une force compacte les combattre, laissant ainsi la forteresse ouverte à une attaque directe de la Horde, ou pire...\n\nMais passons, Latronicus attend. Vous avez fait du bon travail jusque là, <nom>. Continuez comme ça.\n\nVous pouvez disposer.", progress = nil, completion = "Excellent, &lt;nom&gt;. J'apprécie une attitude \"volontaire\" chez ceux avec qui je travaille.\n\nLe général Feathermoon m'a choisi pour m'occuper des nagas de façon directe. Mon plan se déroulera en deux parties : un, nous les affaiblissons tant en nombre qu'en commandement. Deux, nous verrons de quoi elles auront l'air au milieu d'un tas de ruine. Avec votre aide, nous contrerons la présence naga sans pour autant sacrifier la sécurité générale du bastion.", rewards = "Vous recevrez :\n\n"},
[3141] = {title = "Loramus", objective = "Écouter l'histoire de Loramus Thalipedes.", description = "Donc vous souhaitez vous battre contre des démons ? Vous feriez bien d'écouter mon histoire.", progress = "Ne m'interrompez pas, <race>.", completion = "Qu'il en soit ainsi...", rewards = "Vous recevrez :\n\n"},
[3161] = {title = "Gahz'ridian", objective = "Marvon Rivetseeker à Tanaris veut que vous collectiez 30 Ornements Gahz'ridian.", description = "<nom>, je suis un scientifique mais au fond de moi je suis aussi un chasseur de trésor !\n\nIl y a longtemps, quand les trolls occupaient ces terres, ils ont créé de nombreux ornements à l'image de Gahz'rilla, une hydre qu'ils adorent comme divinité. Ces ornements sont sculptés à partir d'une matière que j'appelle \"Gahz'ridian,\" d'après le nom du dieu hydre.\n\nJ'ai en déjà trouvé un peu moi-même, mais j'aimerais en avoir plus à étudier ; peut-être pourrez-vous m'en trouver ?\n\nJ'ai même inventé un détecteur qui rend la recherche de Gahz'ridian un jeu d'enfant ! Il vous suffit de le porter et la recherche peut commencer !", progress = "Avez-vous un problème ?\n\nVous pouvez trouver du Gahz'ridian presque partout dans Tanaris, <nom>, alors cherchez encore !", completion = "Excellent ; ces ornements sont parfaits pour mes recherches. Merci beaucoup pour votre aide, &lt;nom&gt;.\n\nOh, pouvez-vous me rendre mon casque ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTunique de géomètreBâton du savoir\n\nVous recevrez également :\n\n"},
[3181] = {title = "La corne de la bête", objective = "Porter la Corne Gigantesque de Margol à la Montagnarde Pebblebitty.", description = "La corne gigantesque est couverte d'égratignures et de fissures. Un objet de métal inhabituel s'est logé sous la surface dure.\n\nAprès de plus amples observations, vous remarquez qu'il s'agit d'une lame de hache brisée. Sur le métal sont gravés les mots suivants :\n\nPropriété de la Montagnarde Pebblebitty.\n\nQuand vous essayez de déloger la lame, elle s'effrite en mille morceaux.\n\nOups !", progress = "Non, je n'ouvrirai pas le portail.", completion = "Qu'avez-vous là ? C'est un faux, de toute évidence !\n\nJ'ai été face à face avec Margol et je peux vous assurer que sa corne est au moins huit fois plus grande que celle que vous avez en mains, &lt;nom&gt;. Elle vient probablement d'un groin-tempête dans les Tarides. Ah Monsieur, on ne peut pas abuser Pebblebitty !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3182] = {title = "Titre de propriété", objective = "Porter la Corne gigantesque de Margol au conservateur en chef Thorius à Ironforge.", description = "Et vous pensez que je vais avaler une histoire pareille ? Le fer de ma hache se serait brisé et serait coincé dans la véritable corne, s'il s'agissait bien d'elle.\n\nÉcoutez, apportez ce faux grossier au conservateur en chef Thorius à Ironforge. S'il est capable de valider vos dires, vous recevrez un certificat de haut fait. Rapportez-moi cette preuve et je vous remettrai la clé de la gorge des Vents brûlants.\n\nAllez-y !", progress = "Bonjour jeune homme. Vous venez pour faire le tour du musée ?", completion = "Qu'est-ce que c'est ?\n\nOh, je ne peux pas le croire ! Vous savez ce que vous avez là, &lt;nom&gt; ? C'est la Corne de Margol l'Enragée ! Margol ! Le fléau de tout archéologue qui ait jamais pénétré dans la Gorge des Vents brûlants.\n\nPuis-je la garder ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3201] = {title = "Enfin !", objective = "Apporter le document de preuve à la Montagnarde Pebblebitty.", description = "Je n'arrive pas à croire que Pebblebitty ait pu douter de l'authenticité de la corne. Entre vous et moi, je pense qu'elle est seulement jalouse. Je sais qu'elle tenait vraiment à tuer elle-même cette bête, à cause de \"l'incident\" et tout.\n\nDonc vous avez besoin d'un document comme preuve ? Après la contribution que vous venez de faire au musée, ce ne sera pas un problème.\n\n<Le conservateur en chef Thorius commence à remplir un grand document>\n\nEt voilà ! Vous pouvez présenter ceci à Pebblebitty.", progress = "Je n'y crois pas.", completion = "Je ne vois pas comment quelqu'un d'aussi faible a pu surmonter Margol, mais ce qui est dit est dit. Voici la clef.\n\nS'il vous arrive malheur là-bas, vous serez le seul à blâmer.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nClé de la gorge des Vents brûlants"},
[3221] = {title = "Parler à Renferrel", objective = "Parler à l'apothicaire Renferrel au Sépulcre.", description = "Tandis que vous étiez en train d'aider nos Traqueurs noirs, l'apothicaire Renferrel vous a fait appeler. Il n'a rien précisé mais a dit qu'il voulait vous parler à propos des coeurs de loup que vous lui aviez donnés.", progress = nil, completion = "Ah, très bien. Il y a un problème dont il faudrait que vous vous occupiez avec les coeurs de loup que vous m'avez apportés un peu plus tôt.", rewards = "Vous recevrez :\n\n"},
[3261] = {title = "Jorn Skyseer", objective = "Parler à Jorn Skyseer, à Camp Taurajo.", description = "Nos routes se séparent, <nom>. Pour en apprendre plus, vous devrez aller au Camp Taurajo, vers le sud et parler à Jorn Skyseer. Il continuera de vous guider.", progress = nil, completion = "Bienvenue. Vous êtes ici pour avancer dans la voie du chasseur ?\n\nTrès bien. Commençons.", rewards = "Vous recevrez :\n\n"},
[3281] = {title = "Argent volé", objective = "Rapportez l'Argent volé à Gazrog à la Croisée.", description = "Vous avez peut-être tué les raptors, mais l'argent qu'ils ont volé doit être récupéré ! Des rapports indiquent que les raptors ont un important site de nidification au sud de Ratchet. Cet endroit est connu sous le nom de Terres des raptors. Il est probable qu'ils y aient apporté notre argent volé.\n\nAllez dans ce repaire de raptors et cherchez-le. Quand vous l'aurez trouvé, rapportez-le-moi.", progress = "Avez-vous l'argent ?", completion = "Ah ah ! Donc les raptors avaient bien caché l'argent dans leur repaire. Il est incroyable que ces bêtes puissent convoiter de l'argent. Peut-être ces histoires qu'on raconte sur leur intelligence ne sont pas si fausses après tout !\n\nMerci, &lt;nom&gt;. Prenez ceci en récompense et sachez que les gardes de la Croisée vous doivent leur prochain mois de salaire.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de randonnéeJambières de colon\n\nVous recevrez également :\n\n"},
[3301] = {title = "Mura Runetotem", objective = "Parler à Mura Runetotem au Sépulcre.", description = "Ma camarade de clan, Mura Runetotem, est partie pour les Pins argentés afin d'aider nos alliés morts-vivants. C'est une forêt qui dépérit doucement, et elle avait l'espoir d'y insuffler la vie à nouveau. Peut-être que la vie insolite que nous trouvons ici dans les Tarides l'aiderait à réaliser ses souhaits pour les Pins argentés ?\n\nPrenez avec vous une des carapaces que vous avez apportées, et donnez-la à Mura Runetotem aux Pins argentés. Elle séjourne au Sépulcre. Avec un peu de chance, l'étude de cette carapace l’aidera à trouver une solution pour guérir cette forêt à l'agonie.", progress = "Je peux sentir sur vous l'odeur de la poussière des Tarides, <classe>. Vous avez fait un long voyage.", completion = "Ah, qu'est-ce donc ? Cette carapace possède un éclat intérieur, comme si la vie palpitait toujours en son sein. Stupéfiant ! Je dois étudier ceci de plus près.\n\nMerci, &lt;nom&gt;. Avec un peu de chance, cette carapace livrera un secret que je pourrai mettre à profit pour venir en aide aux terres de la forêt des Pins argentés.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture JackseedCape de semeur\n\nVous recevrez également :\n\n"},
[3321] = {title = "Est-ce que ceci est à vous ?", objective = "Attendre que Trenton ait terminé son travail.", description = "Vous avez beaucoup fait pour l'Ordre, <nom>. Le total dévouement nécessaire pour parvenir jusqu'ici aurait rebuté toute personne ordinaire. Il ne fait aucun doute dans mon esprit, ni dans celui de Galvan, que vous faites partie des nôtres.\n\nC'est la raison pour laquelle j'estime que vous méritez une petite récompense. Ce n'est pas grand chose en fait, un simple colifichet. Il se peut que vous soyez <familier/familière> avec ses propriétés, car je crois que c'est ce qui vous a <amené/amenée> à nous en premier lieu.", progress = "Nous finalisons aujourd'hui la célébration de votre engagement envers l'Ordre.", completion = "Elevez-vous et soyez reconnu, &lt;nom&gt;, Forgeron de l'Ordre du Mithril.", rewards = "Vous recevrez :\n\nInsigne rougeoyant en mithril"},
[3341] = {title = "L'anéantissement", objective = "Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne.", description = "Il se trouve dans les Tarides un horrible fouillis de ronces entremêlées, les Souilles de Tranchebauge. Bien que nos premières observations à cet endroit n'aient révélé que peu de dangers, nos découvertes récentes sont beaucoup plus alarmantes…\n\nLes hurans des Souilles de Tranchebauge se sont alliés au Fléau. Une liche du nom de Amnennar, dite le Porte-froid, les contrôle à présent et utilise le pouvoir de son imposante connaissance pour diriger chacun de leurs mouvements.\n\nAmnennar est liée à Ner'zhul par la télépathie ; nous devons trancher ce lien, <nom>. Il faut éliminer le Porte-froid.", progress = "Il s'agit d'un problème de la plus haute importance, <nom>. Nous devons empêcher toute tentative du Fléau de soutenir leurs rangs.", completion = "La loyauté d'une Liche est inébranlable, &lt;nom&gt;. Faisons-leur comprendre qu'une telle loyauté ne leur apportera qu'anéantissement.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEpée du triompheTalisman de luisambre"},
[3361] = {title = "Les malheurs d'un réfugié", objective = "Apporter la Boîte de Felix, le Coffre de Felix et le Seau de boulons de Felix à Felix Whindlebolt, à Anvilmar.", description = "Nous avons chassé les troggs de Gnomeregan, mais c'est devenu catastrophique depuis ! Maintenant notre maison est complètement irradiée et nous, les gnomes, nous avons été dispersés dans tout Dun Morogh.\n\nDans ma hâte de fuir les radiations, j'ai perdu toutes mes affaires personnelles et mes outils. Ce sont les trolls qui les ont pris. Ils ont volé mon coffre, ma boîte et mon seau de boulons ! Ils les ont emportés dans leur camp au sud-ouest d'Anvilmar.\n\nJe ne suis pas un aventurier… Pourriez-vous retrouver mes affaires et me les rapporter ici, s'il vous plaît ?", progress = "Oh, par tous les dieux, <nom>, cette ville ne convient pas du tout à mes semblables. Il y a autant d'horribles créatures ici qu'il y en avait à Gnomeregan avant l'accident !\n\nAvez-vous retrouvé mes affaires ? Si vous ne les avez pas retrouvées, alors qui sait ce que les trolls en ont fait à l'heure qu'il est...", completion = "Hourra, vous les avez trouvés ! Vous êtes mon sauveur, la bonté incarnée ! Tenez, ce n'est pas grand-chose, c'est un humble dédommagement pour les efforts que vous avez faits ! Merci !", rewards = "Vous recevrez :\n\n"},
[3362] = {title = "La vallée des Chardonniers", objective = "Tran'rek, à Gadgetzan, voudrait que vous tuiez 8 Chardonniers noueux et 8 Chardonniers taille-racines.", description = "Avez-vous déjà vu la vallée des Chardonniers ? C’est un endroit dangereux, <nom>.\n\nIl y a d’étranges bêtes là-bas, imprévisibles ! Je crois qu’on les appelle les Chardonniers noueux et les Chardonniers taille-racine...\n\nJe veux accéder à la vallée, mais avec tous ces Chardonniers dans les parages c’est bien trop risqué. Si vous vouliez bien aller en tuer quelques-uns, je pourrais envisager d’y retourner. Qu’en pensez-vous, <nom> ? M’aiderez-vous ?", progress = nil, completion = "Ils sont aussi gros ? Il va peut-être falloir que je modifie mon plan...\n\nMais vous avez respecté votre part du marché ; voici ce que je vous avais promis.", rewards = "Vous recevrez :\n\n"},
[3363] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[3364] = {title = "Une livraison de thé brûlant", objective = "Apporter un Thé brûlant à Durnan Furcutter, dans Anvilmar, dans les cinq minutes imparties avant qu'il ne refroidisse !", description = "Ah ! Je devais apporter un Thé brûlant à Durnan Furcutter, à Anvilmar, mais je dois d’abord en porter un à Grelin. Je n'arriverai jamais à Anvilmar avant qu'il ne refroidisse !\n\nVous m’avez l'air rapide. Vous pouvez le faire. Cette boisson ne restera chaude que 5 minutes et Durnan n'a pas commandé un Thé \"glacé\", alors partez tout de suite. Anvilmar est un village dans la montagne, au nord-est.\n\nMerci, <nom>, et n'oubliez pas de me rapporter ma tasse !", progress = "Oui ? Je suis Durnan Furcutter. Vous avez quelque chose pour moi ?", completion = "Ah, bien, voilà exactement ce qu'il me fallait. Permettez-moi de prendre une petite pause et de déguster ce Thé brûlant !", rewards = "Vous recevrez :\n\n"},
[3365] = {title = "Rapporter la Tasse", objective = "Apporter la Chope de Nori à Nori Pridedrift.", description = "Ah ! Vous êtes <arrivé/arrivée> à point nommé ! Rien de tel qu'un bon thé chaud, non, BRULANT, par une froide journée d'hiver pour réchauffer les méandres de votre esprit.\n\nTenez, <nom>, soyez assez aimable pour rapporter cette tasse vide à Nori pour moi, voulez-vous ?", progress = "Je pense que vous êtes parvenu à livrer le thé brûlant à Durnan dans les temps, n'est-ce pas ? Avez-vous pensé à me rapporter ma tasse ?", completion = "Parfait, &lt;nom&gt; ! Vous seriez surpris du nombre de livreurs que je rencontre qui oublient une chose aussi simple que de rapporter la tasse. Les tasses ne poussent pas sur les arbres, ou bien c'est une nouveauté que je ne connais pas !\n\nVoici un petit quelque chose pour vos efforts. Merci encore pour votre aide.", rewards = "Vous recevrez :\n\n"},
[3366] = {title = "L'Eclat luminescent", objective = "Aller à Ratchet pour trouver la raison d’être de l’Eclat de cauchemar.", description = "L'éclat est d'un vert brillant, et bien que compact, ce qui ressemble à de la fumée tourbillonne juste au-dessous de sa surface. Vous ne pouvez vous empêcher de contempler les profondeurs du cristal, bien qu'en même temps, vous sentiez qu'il y réside quelque chose de très inquiétant.\n\nPeut-être devriez-vous voir si quelqu'un à Ratchet pourrait vous en apprendre plus à propos de cet étrange éclat...Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[3367] = {title = "Les pierres de Suntara", objective = "Aider Dorius à retourner à Ironforge.", description = "<Dorius gémit.>\n\nJe suis grièvement blessé, <nom>. Je me sens… la tête toute légère… tout… tournoie… je saigne… à l'intérieur.\n\nJe dois retourner à Ironforge. Aidez-moi, <nom>.", progress = "Je… je ne vais pas y arriver…", completion = "Dorius avait cette lettre sur lui quand il a été abattu.", rewards = "Vous recevrez :\n\n"},
[3368] = {title = "Les pierres de Suntara", objective = "Apporter la Lettre roussie à Thorius à Ironforge. Il se trouve dans le Hall des Explorateurs.", description = "Mon frère,\n\nSi vous lisez cette lettre, c'est que je n'existe plus. Comment vous est-elle parvenue, je l'ignore. Mais remerciez et récompensez ceux qui ont fait en sorte que vous l'ayez reçue.\n\nÀ propos des pierres : elles existent, les Sombrefer les ont en leur possession. Leur chef, Lathoric le Noir, utilise le pouvoir de ces pierres pour asservir mon équipe d'archéologues. Ils ont été emmenés au Chaudron. Leurs esprits sont à présent asservis et ils travaillent nuit et jour pour achever une chose qui répond au nom d'Obsidion.\n\nSecourez-les. Il s'agit là de la dernière volonté d'un homme mort.\n\n-Dorius", progress = "<Thorius sanglote.>", completion = "&lt;Thorius s'essuie le visage.&gt;\n\nAu nom de la Lumière, son voeu sera exaucé. Je le jure.", rewards = "Vous recevrez :\n\n"},
[3369] = {title = "Au coeur des cauchemars", objective = "Apporter l'Eclat de cauchemar à Hamuul Runetotem à la Cime des Anciens.", description = "Cet éclat détient de grands secrets. Il s'agit de l'essence pure du Rêve d'émeraude. Ce que je vois dans cet éclat n'a rien d'un rêve cependant. On pourrait même appeler cela une vision de cauchemar.\n\nMon but n'est pas de vous alarmer, <nom>, mais je crois qu'il serait mieux pour vous de remettre cet éclat à un grand druide, et ce le plus tôt possible.\n\nLa personne que vous devriez rencontrer à la Cime des Anciens se nomme Hamuul Runetotem. Partez pour Thunder Bluff. Je ne peux pas vous en dire plus.", progress = "Je peux vous aider ?", completion = "Ainsi, c'est Falla qui vous envoie ? Bien, voyons à présent cet éclat au sujet duquel elle a été tellement hésitante à vous parler…\n\n&lt;Hamuul observe l'intérieur de l'éclat.&gt;\n\nOh… je n'ai pas… Bien.\n\n&lt;nom&gt;, je vous remercie de me l'avoir apporté. Il ne serait pas sage de parler de choses telles que celle-ci mais il semble normal que je vous informe. Il s'agit de sujets auxquels vous ne devriez pas vous intéresser.\n\nDisons simplement que ce qui se passe dans le Rêve d'émeraude n'est pas exactement ce à quoi nous pensions...\n\nIl se peut que nos chemins se croisent à nouveau dans le futur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet de TalbarBottines Quagmire\n\nVous recevrez également :\n\n"},
[3370] = {title = "Au coeur des cauchemars", objective = "Apporter l'Eclat de cauchemar à Mathrengyl Bearwalker à Darnassus.", description = "Cet éclat détient de grands secrets. Il s'agit de l'essence pure du Rêve d'émeraude. Ce que je vois dans cet éclat n'a rien d'un rêve cependant. On pourrait même appeler ce genre de vision un cauchemar.\n\nMon souhait n'est pas de vous alarmer, <nom>, mais je crois qu'il serait mieux pour vous de remettre cet éclat aux mains d'un grand druide, et ce dès que vous le pouvez.\n\nLa personne que vous devez trouver au Cercle cénarien se nomme Mathrengyl Bearwalker. Partez pour Darnassus. Je ne peux vous en dire plus.", progress = "Je peux vous aider ?", completion = "Ainsi, c'est Falla qui vous envoie ? Bien, voyons à présent cet éclat à propos duquel elle a été tellement hésitante à vous parler…\n\n&lt;Mathrengyl observe l'intérieur de l'éclat.&gt;\n\nOh… je n'ai pas… Bien.\n\n&lt;nom&gt;, je vous remercie de me l'avoir apporté. Il ne serait pas sage de parler de choses telles que celle-ci cependant, je vous en informe. Il s'agit de sujets sur lesquels seuls les druides cénariens devraient se pencher.\n\nDisons simplement que ce qui se passe dans le Rêve d'émeraude n'est pas exactement ce à quoi nous pensions...\n\nIl se peut que nos chemins se croisent à nouveau dans le futur.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet de TalbarBottines Quagmire\n\nVous recevrez également :\n\n"},
[3371] = {title = "La justice des nains", objective = "Retourner à la Gorge des Vents brûlants et trouver l'Equipe d'archéologues de Dorius.", description = "Il y a, à présent, un creux vide de sens, là où se trouvait autrefois mon coeur, <nom>. Je ne me remettrai pas de la perte de Dorius. Je dois faire en sorte que sa dernière volonté soit accomplie. Justice doit être rendue contre ceux qui ont commis ce meurtre de sang-froid.\n\nRetournez à la Gorge des Vents brûlants et respectez sa dernière volonté : libérez ses hommes.", progress = nil, completion = "Oubliez-moi, aidez les autres.", rewards = "Vous recevrez :\n\n"},
[3372] = {title = "La libération", objective = "Trouver l'Artefact mystérieux gardé par le Marteau du crépuscule au nord.", description = "Libérez-les, <nom>. Leurs corps sont morts, mais la puissance de Suntara les oblige à achever leur travail.\n\nL'Autel de Suntara est la clé pour les libérer. Allez au nord, dans les collines au-dessus de la caverne… Le Marteau du crépuscule y garde une relique. Emparez-vous-en et placez-la sur l'Autel de Suntara.\n\n<L'archéologue mourant s'effondre.>", progress = "L'autel est vide.", completion = "Vous placez l'artefact mystérieux sur l'Autel de Suntara.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3373] = {title = "L'Essence d'Eranikus", objective = "Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti.", description = "Alors que vous touchez la gemme, une voix grave résonne dans votre esprit.\n\n\"<Mortel/Mortelle>, considérez ma requête. Je suis Eranikus des dragons verts, gardien de ce temple maudit. J'avais pour charge de m'assurer que les trolls n'amènent plus en ces lieux leurs dieux abominables. Mais j'ai échoué. Alors que j'imprègne cette gemme d'une partie de mon essence, je sens que mon étreinte sur le Rêve s'évanouit vers le néant. Je vous en prie, placez cette gemme dans le Réceptacle d'essence de mon antre, et que notre magie en ces lieux purge l'infection de mon esprit et me permette de reposer.\"", progress = "Alors que vous vous approchez du réceptacle d'essence dont vous a parlé Eranikus, sa voix caresse à nouveau votre esprit.\n\n\"Oui, mortel, ce réceptacle d'essence sauvera ce qu'il reste d'éléments non souillés de mon esprit imprégnés à cette gemme. Placez la gemme à l'intérieur du réceptacle, et laissons la magie des dragons verts nettoyer la corruption et l'infection de mon être. Alors seulement je connaîtrai la libération et les dragons verts seront en mesure de réaffirmer leur tutelle sur les Atal'ai.\"", completion = "Vous placez la gemme à l'intérieur du Réceptacle d'essence.\n\n\"Merci, mortel, vous avez - non… ce, ce n'est pas possible ! Non ! La corruption de ce dieu maudit souille même la sainteté du Réceptacle d'essence des dragons verts ! Non je vous en prie, je sens ma propre essence se déchirer de moi-même ! LA DOULEUR ! L'étreinte d'un éternel cauchemar se referme sur moi...\"\n\n\"Mortel, je vous implore ! Trouvez quelqu'un des dragons verts pour y mettre un terme... au secours... je suis enchaîné aux ténèbres... à l'agonie pour toujours... Pitié, ne torturez...\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEssence d'Eranikus enchaînée"},
[3374] = {title = "L'Essence d'Eranikus", objective = "Apporter la Pierre de voeu des dragons d'Ysera et l'Essence d'Eranikus enchaînée à Itharius au marais des Chagrins. C'est là que vous choisirez d'aider ou non les dragons d'Ysera.", description = "Vous activez la Pierre de vœu et Itharius parle directement à votre esprit à travers elle.\n\n\"En acceptant la charge contenue dans cette Pierre de vœu, vous vous engagez à soutenir ma cause et celle des dragons d'Ysera, qui est de racheter l'esprit corrompu d'Eranikus. Le premier sacrifice, parmi les nombreux que vous et moi ferons sans aucun doute, va être de m'abandonner la gemme qui a enchaîné ce qu'il reste de volonté dans l'esprit d'Eranikus.\"\n\n\"Faites-le, <nom>, et nous œuvrerons de concert au rachat d'une âme digne de rédemption.\"", progress = "Nous y voilà, <nom>. À une autre croisée de chemins. Le temps est à présent venu de faire un nouveau choix. Quel est-il, mortel ?", completion = "Vous avez fait votre choix. Jusqu'à présent, vous avez fait des choix qui m'ont semblé justes. Dorénavant, vos actes et vos faits détermineront si cela doit rester le cas.", rewards = "Vous recevrez :\n\n"},
[3375] = {title = "La fiole de remplacement", objective = "Apporter une Potion de mana, du Charbon, et du Nectar sucré à Talvash del Kissel à Ironforge pour remplacer la Fiole de divination de Talvash.", description = "Hum, vous avez besoin d'une autre Fiole de divination ? C'est une plaisanterie, n'est ce pas ? Qu'avez-vous fait de la première ?! Beaucoup de travail nous attend, <nom>. Ces fioles ne poussent pas sur les arbres. En fait, j'aimerais bien que ce soit le cas, car je m'y rendrais tout simplement et en cueillerais une, puisqu'il ne m'en reste plus !!\n\nPour que je puisse vous la préparer, j'ai besoin des choses suivantes : une Potion de mana, un morceau de Charbon, et du Nectar sucré. Ne me demandez pas pourquoi, amenez-moi simplement tout ceci et je vous en ferai une autre.", progress = "Pour faire une autre Fiole de divination, j'ai besoin d'une potion de mana, d'un morceau de charbon, et d'un peu de nectar sucré.\n\nEt de beaucoup, beaucoup de patience apparemment.", completion = "Le puissant aventurier arrive enfin avec la cargaison. Hourra !! Oh, à propos, j'ai menti… j'avais une autre fiole. Prenez-la, allez.\n\nEt alors, vous vous attendiez à quoi ?! \"Oh, mais je vous en prie, prenez donc ! Je ne suis qu'un rigolo qui n'a rien d'autre à faire que de distribuer des outils magiques de communication à tous les aventuriers qui passent dans le secteur !\" Dormez tranquille, quand même, ce que vous m'avez apporté suffira à l'élaboration d'une autre fiole quand vous aurez égaré celle-là aussi.\n\nPar pitié, ne me donnez pas raison, et ne perdez pas celle que je viens de vous donner, d'accord ?", rewards = "Vous recevrez :\n\nFiole de divination de Talvash"},
[3376] = {title = "La fin de Brochaigu !", objective = "Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge.", description = "<nom>, j'ai entendu parler de vous. Peut-être saurez-vous nous venir en aide là où d'autres ont échoué.\n\nNous, taurens, avons fait de cette terre notre foyer. Mais cela n'a pas été sans pertes. Les hurans Dos-hirsute, du ravin de Roncelame, menés par leur chef Brochaigu Mantépine, nous accablent sans cesse. Je vous demande de me rapporter la tête de leur chef !\n\nVous pourrez le trouver dans le ravin, à l'est, dans leur village de fortune.", progress = "Brochaigu ne nous posera plus de problèmes une fois que vous m'aurez apporté la preuve de sa mort. Je veux sa tête, <nom>.\n\nLes taurens vivent pour la chasse et il n'y a pas de plus grand honneur que de chasser un autre prédateur. Si vous venez à bout de cette mission, vous comprendrez de quoi je parle.", completion = "La justice s'est exprimée en ce jour par vos actes efficaces, &lt;nom&gt;. Que ceci serve d'avertissement à tous ceux qui menaceraient notre foyer.\n\nVous avez gagné avec mérite cette récompense. Puisse t-elle vous aider durant votre séjour, jeune &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières en anneaux peintsGants de nomade\n\nVous recevrez également :\n\n"},
[3377] = {title = "Prière à Elune", objective = "Écouter le récit de Zamael.", description = "Me viendrez-vous en aide, <mortel/mortelle> ? Écoutez mon récit.", progress = "Permettez-moi de terminer mon histoire.", completion = "Je me suis résigné à mon sort ici dans cette cage, mais la prière doit être retrouvée.", rewards = "Vous recevrez :\n\n"},
[3378] = {title = "Prière à Elune", objective = "Trouver la Prière à Elune et l'apporter à Astarii Starseeker à Darnassus.", description = "Me viendrez-vous en aide, <mortel/mortelle> ? Trouverez-vous la Prière à Elune ?\n\nComme je l'ai dit, cette prière a été gravée sur une tablette en or. Elle doit se trouver sur l'une de ces crapules vénérant des idoles.\n\nSi vous parvenez à retrouver ma prière, apportez-la à Astarii Starseeker à Darnassus. Il importe peu que ma foi ait été ravivée après les innombrables actions malveillantes que j'ai infligées à ce monde et à ses habitants, mais ma prière doit être entendue. La dernière chose que je demande est l'absolution.", progress = "Qu'est-ce qui vous amène au Temple de la Lune, <nom> ?", completion = "Elune vous sourit en cette soirée, &lt;nom&gt;. Vous lui avez ramené un esprit égaré. Veuillez accepter ceci comme gage de notre reconnaissance.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpaulières KaylariProtège-bras d'acier runique\n\nVous recevrez également :\n\n"},
[3379] = {title = "Les tisseuses d'ombre", objective = "Tuer le groupe de braconniers Ombresoie qui rôde dans la gorge des Vents brûlants. Nilith a de bonnes raisons de croire qu'ils doivent être exterminés tous les cinq. Retourner voir Nilith dans la gorge des Vents brûlants lorsque vous aurez terminé.", description = "Les araignées de la gorge des Vents brûlants sont une source inestimable de Soie des ténèbres. Comme vous le savez, la Soie des ténèbres est très recherchée par les artisans de notre métier.\n\nMalheureusement, un groupe de braconniers a récemment empiété sur ces terres, et massacre en masse les araignées sans se soucier des effets à long terme de leurs actions. Aussi, la première chose que je vous demanderai sera assez simple : trouvez-les, et... tuez-les.\n\nCommencez vos recherches au nord.\n\nSi vous avez besoin d'assistance, parlez avec Raze.", progress = nil, completion = "Excellent travail, &lt;nom&gt;.\n\nJe crois ne pas me tromper en disant que ceci est une pièce de tisse-ombre que vous n'avez encore jamais vue.", rewards = "Vous recevrez :\n\nBrassards des ténèbres"},
[3380] = {title = "Le Temple englouti", objective = "Trouver Marvon Rivetseeker à Tanaris.", description = "Il existe en ce monde des esprits qui ne connaissent pas le repos, <nom>. Il existe des esprits viciés par leur solitude, liés à un mal antique…\n\nJ'ai entendu parler d'un endroit se trouvant profondément sous la surface de la terre, banni en ce lieu par des puissances plus grandes que je n'aie jamais rencontrées.\n\nSi vous souhaitez en apprendre davantage sur cet endroit, le Temple englouti, partez à la recherche d'un gobelin nommé Marvon Rivetseeker. Il a étudié de nombreuses parties du monde, et aux dernières nouvelles, il a quitté sa demeure à Ratchet pour étudier les ruines des trolls à Tanaris.", progress = nil, completion = "Oui, le Temple englouti, je peux dire que je l'ai vu de mes propres yeux. Peut-être souhaiteriez-vous en entendre davantage à son propos ?\n\nVous m'avez l'air d'être du genre aventurier… Je connais des choses qui pourraient vous intéresser...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3381] = {title = "Une rencontre avec le maître", objective = "Apporter 2 Plumes d'hippogryphe sans défaut à Sanath Lim-yo à Azshara, si vous souhaitez parler à son maître.", description = "Ah ! <Un/Une> jeune vient parler à Sanath. Quelle journée merveilleuse ! Quel plaisir que vous m'honoriez de la grâce de votre présence. Merci, <nom> !\n\nS'il vous plaît, n'ayez pas l'arrogance de considérer mon sarcasme comme un compliment. Que les choses soient claires : je ne vous apprécie pas ! Mais cette petite conversation n'a strictement rien à voir avec nous. Elle a à voir avec mon maître.\n\nApportez-moi une paire de plumes d'hippogryphe pour mes flèches et je vous octroierai l’autorisation d'aller le voir. Il a expressément demandé que je ne lui envoie <d'aventuriers que s'ils/d'aventurières que si elles> s'en montrent suffisamment dignes.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTéléporte à la Tour d'Azshara\n\nVous recevrez :\n\n"},
[3382] = {title = "Un équipage sous le feu ennemi", objective = "Défendre la capitaine Vanessa Beltis, son équipage et les passagers de “l’Horizon” contre l'attaque des nagas. La capitaine Vanessa Beltis doit survivre.", description = "Nous étions près de la côte et cherchions un endroit sûr où jeter l'ancre. Le soleil ne s'était pas couché depuis plus d'une heure lorsqu'ils ont attaqué… Ces maudits nagas !\n\nJe ne sais pas ce qu'ils cherchaient, mais il est clair qu'ils ne l'ont pas trouvé. Ils sont déjà revenus une fois. Deux de mes éclaireurs sont de garde à l'entrée de la vallée pour nous avertir lorsque la prochaine attaque aura lieu.\n\nCela me désole que vous arriviez à ce moment, <nom>, mais je n'y peux rien.\n\nÊtes-vous <prêt/prête> pour le combat de votre vie ?", progress = "Ça va être une bataille difficile...", completion = "Vous avez réussi ! Merci ! C'est certainement l'une des batailles les plus violentes auxquelles j'ai pris part. Je ne pourrai jamais vous remercier assez.\n\nJ'aurais tellement voulu qu'une plus grande partie de mon équipage survive.\n\nJ'aimerais que vous parliez à tous les passagers survivants de “l’Horizon”. Certains avaient à faire dans le secteur, et il se peut qu'ils aient à vous demander un ou deux services, si vous le souhaitez. Je vous remercie à nouveau pour toute votre aide.", rewards = nil},
[3385] = {title = "Le Sous-marché", objective = "Tuer le Maître d'artisanat Kovic et son agent Clonk. Récupérer sur son corps la Sacoche du marchand et l'apporter à Nilith.", description = "Ils se sont donnés le nom de Sous-marché : des commerçants sans vergogne qui vendront, intimideront, commerceront, ou feront à peu près n'importe quoi contre la bonne somme d'argent.\n\nMais les choses empirent, <nom>. Ils ont établi une base d'opérations ici dans la gorge des Vents brûlants. Kovic dirige les opérations et entretient des liens étroits avec les nains Sombrefer dans la région.\n\nNous devons frapper fort et envoyer un message clair à leurs dirigeants. Tuez Kovic, ainsi que son agent Clonk. Apportez-moi sa Sacoche du marchand lorsque vous en aurez terminé.\n\nPartez pour le Chaudron à présent !", progress = "Le Maître d'artisanat est toujours en vie ?", completion = "Vous avez porté un coup décisif au Sous-marché. Leurs chefs y réfléchiront à deux fois avant d'envoyer de nouveaux hommes dans le gouffre.\n\nOh, et je n'ai également rien trouvé qui m'intéresse dans la sacoche du marchand. Vous pouvez garder tout ce que vous y trouverez.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture des ténèbresSacoche de marchand de Kovic"},
[3402] = {title = "Le Sous-marché", objective = "Parler à Vizzklick à Gadgetzan.", description = "Je veux que vous informiez personnellement Vizzklick à Gadgetzan de la défaite de Kovic. Il sera si heureux d'apprendre sa mort qu'il vous remettra sûrement une récompense.", progress = nil, completion = "Kovic est mort ??! C'est un grand jour, &lt;nom&gt; ! Durant des années, cette crapule a organisé des commerces louches et véreux, à vendre moins cher que les honnêtes commerçants.\n\nVous méritez une belle récompense pour cette réussite ! Et vous l'aurez !", rewards = "Vous recevrez :\n\nPatron : Masque en tisse-ombre"},
[3421] = {title = "Le voyage de retour", objective = "Je vais vous renvoyer au camp de Sanath à présent.\n\nNe faites pas attention à ses mauvaises manières. Il est brusque envers tout le monde, sauf envers le maître. Peut-être apprendra-t-il la leçon un jour ?", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTéléportation à partir de la Tour d'Azshara"},
[3441] = {title = "Châtiment divin", objective = "Écouter le récit de Velarok Lamevent.", description = "Écoutez mon récit, <aventurier/aventurière>.", progress = "Permettez-moi de finir, mo… <race>.", completion = "Alors, en avez-vous entendu suffisamment ? Êtes-vous prêt à agir ?", rewards = "Vous recevrez :\n\n"},
[3442] = {title = "La flamme parfaite", objective = "Réunir 4 Cœurs des flammes et 4 globes d’Huile de golem puis rapporter ces objets à Velarok Lamevent.", description = "Vous avez pris la bonne décision, <nom>.\n\nNous devons frapper à l'endroit où nous ferons le plus de mal : aux quatre tours de garde.\n\nLorsque les quatre tours seront en feu, nous pourrons lancer notre offensive avant même qu'ils aient le temps de réagir.\n\nVous allez avoir besoin du bon outil pour incendier les tours. Et pour cet outil, nous devons trouver quelques ingrédients.\n\nApportez-moi quatre Cœurs des flammes, et quatre globes d'Huile de golem, et je ferai naître la torche de flamme parfaite.\n\nVous devriez prendre tout d'abord pour cibles les golems et les élémentaires de ces terres.", progress = "Avez-vous réuni les ingrédients ?", completion = "Bien joué, &lt;nom&gt;. Nous sommes presque prêts.", rewards = "Vous recevrez :\n\n"},
[3443] = {title = "Forger le manche", objective = "Apporter 8 Dagues plaquées en thorium à Velarok Lamevent.", description = "Pour porter la flamme parfaite, nous aurons besoin d’un manche et d’une enveloppe. Vous devez tout d’abord trouver un manche convenable.\n\nLes sous-chefs et les esclavagistes Sombrefer du Chaudron se servent d’armes en thorium enchanté, un alliage extrêmement solide. Si vous m’apportez huit dagues plaquées en thorium, je pourrai les fondre et utiliser le métal pour fabriquer le manche.", progress = "Huit, <nom>. Il m'en faut huit !", completion = "Vous êtes un travailleur remarquable, &lt;nom&gt;. Avez-vous déjà pensé à changer de métier ? Détective, peut-être ? Collecteur de bric-à-brac ? Oh, j'ai trouvé, le même métier que ces gnomes stupides qui parcourent les plages avec leur machinerie pour détecter les métaux. Oui, ce travail vous irait comme un gant.", rewards = "Vous recevrez :\n\n"},
[3444] = {title = "Le Cercle de pierres", objective = "Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet.", description = "J'ai pénétré une fois dans les premières salles du Temple englouti. Le mal de ces lieux oppresse quiconque y entre. Je n'ai réussi à trouver la sortie qu'à grand-peine, ne progressant que difficilement à travers le limon qui recouvre à présent le sol. Je ne me souviens que d'avoir trébuché dans une grande pièce circulaire, remplie de statues de serpents...\n\nJ'ai récemment découvert une pierre ronde qui portait le même symbole de serpent gravé sur sa face. Je l'ai faite envelopper et envoyer à mon atelier à Ratchet. Récupérez-la, et il se peut que je puisse vous en dire davantage.", progress = "Ratchet n'est pas très loin, <nom>. Le voyage ne devrait pas vous prendre trop longtemps.", completion = "Oui… il s'agit bien de cette pierre.\n\nTout me revient à présent, &lt;nom&gt;…", rewards = "Vous recevrez :\n\n"},
[3445] = {title = "Le Temple englouti", objective = "Trouver Marvon Rivetseeker à Tanaris.", description = "J'ai entendu parler d'un endroit se trouvant profondément sous la surface de la terre, banni en ce lieu par de plus grandes puissances que je n'aie jamais rencontrées.\n\nSi vous souhaitez en apprendre davantage sur cet endroit, le Temple englouti, partez à la recherche d'un gobelin nommé Marvon Rivetseeker. Il a étudié de nombreuses régions du monde, et aux dernières nouvelles, a quitté sa demeure à Ratchet pour étudier les ruines des trolls à Tanaris.\n\nJe vous souhaite bonne chance dans vos recherches, cela fait longtemps que personne ne l'a vu.", progress = nil, completion = "Oui, le Temple englouti, je peux dire que je l'ai vu de mes propres yeux. Peut-être souhaiteriez-vous en entendre davantage à son propos ?\n\nVous m'avez l'air d'être du genre aventurier… Je connais des choses qui pourraient vous intéresser...", rewards = "Vous recevrez :\n\n"},
[3446] = {title = "Dans les profondeurs", objective = "Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins.", description = "J'ai trouvé à l'intérieur du temple une pièce circulaire avec six stèles, chacune étant une statue de serpent. La curiosité m’amena à pousser l'une d'entre elles, simplement pour voir ce qui allait se passer. C'était un piège, et l'explosion m'a presque emmené jusqu’aux portes de la mort. Alors que je reposais là, sur le bord, je regardais en bas pour m’apercevoir qu'il y avait une autre statue dans la partie inférieure de la pièce : un autel si l'on peut dire... Hakkar, je crois qu'il s'appelait comme ça.\n\nJe pense que cet autel est la clé du mystère : vous devez apporter ce symbole à cet autel du Temple englouti.", progress = "En examinant la statue, vous remarquez la présence d'un creux sur son côté, dont la taille est identique à celle du symbole que vous a donné Marvon.", completion = "Vous poussez le Cercle de pierres dans l'ouverture, et vous l'entendez s'enclencher à sa place.\n\nÀ présent que l'objet est en place, vous pouvez continuer… Mais qu'avez-vous à faire ?\n\nPeut-être devriez-vous examiner plus attentivement cet autel…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3447] = {title = "Le secret du cercle", objective = "Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues.", description = "Ma mémoire est brumeuse, mais je vais vous raconter ce dont je me souviens. Je crois que le cercle de statues situé dans le Temple englouti détient, malgré les dangers qui s'y cachent, un secret permettant de découvrir un trésor encore plus important.\n\nJe pouvais activer une série de lumières depuis l'autel principal. Il est possible que si vous parveniez à comprendre la signification de ces lumières, vous puissiez découvrir les mystères de cette pièce.\n\nJe vous mets quand même en garde, <nom>. De puissants maléfices protègent ces lieux. Il est probable que quoi que ce soit qui ait de la valeur soit gardé avec ferveur.", progress = nil, completion = "L'œil de l'idole scintille d'un vif éclat malgré la pénombre qui règne dans le temple. Sa transparence vous révèle quelque chose qui brille derrière. Glissant l'œil sur le côté, vous tendez la main et vous vous emparez de ce qui était caché dans la statue.\n\nLe trésor atal'ai est désormais en votre possession.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nUrne hakkari"},
[3448] = {title = "La transmission du fardeau", objective = "Parler au mage Tymor à Ironforge.", description = "On m'a récemment donné la responsabilité d'étudier Azshara, un endroit autrefois magnifique que les elfes considéraient comme leur demeure. C'était à l'époque où ils pratiquaient la magie. Cet endroit est à présent plus dangereux que beau, mais cela ne nous empêche pas de retourner chaque pierre qui s'y trouve pour découvrir des réponses sur notre passé.\n\nUn de mes compagnons du nom de Tymor m'a proposé son aide pour étudier ce lieu, car il s'intéresse particulièrement à de tels sujets.\n\nIl possède une petite demeure en ville, à droite du Hall des mystères.", progress = nil, completion = "Ah, ainsi c'est Karnik qui vous envoie. Je m'attendais à entendre parler de lui sous peu. J'ai découvert de telles merveilles sur Azshara. Je sais que la durée de vie des elfes de la nuit est considérable, mais tout un chacun oublie parfois les événements les plus... malheureux de sa vie. Ceci n'est pas un reproche, remarquez, juste une simple observation.\n\nIl y a longtemps de cela, existaient des cités créées par les elfes, emplies de connaissance sur la magie et d'autres arts oubliés. Alors que j'étudiais de telles choses, j'ai commencé mon enquête. Et ce que j'ai découvert est sensationnel.", rewards = "Vous recevrez :\n\n"},
[3449] = {title = "Les runes des arcanes", objective = "À l'aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth'Amara, de la Rune de Jin'yael, de la Rune de Markri, de la Rune de Sael'hai, puis se diriger vers la petite île près de la Péninsule méridionale d'Azshara et signaler au Pilote Xiggs Fuselighter de venir les prendre.", description = "Certains elfes vénéraient autrefois la magie tout autant qu'Elune. Des mages, parmi les plus puissants, conçurent des runes et des tablettes citant les règles des arcanes et des aperçus de leurs découvertes. Ils les laissèrent dans des lieux publics pour que chacun puisse les méditer.\n\nJ'aimerais beaucoup obtenir des reproductions de ces runes des ruines d'Eldarath. J'ai ici pour vous une trousse qui vous permettra d'effectuer ces reproductions, mais il vous appartiendra de trouver ces runes. Faites attention quand même, la Ligue des Explorateurs n'est pas la seule à s'intéresser à Eldarath.", progress = "Bien bien bien, je suis heureux de voir que vous êtes parvenu jusque-là, <nom>. Avez-vous les reproductions pour Tymor ?\n\nBien que cet endroit soit dangereux, il n'y a pas vraiment eu d'action le long de la côte. C'est peut-être à cause des nagas qui nagent sous l'eau, mais ce n'est pas vraiment mon problème de toute façon. Je patrouille dans les airs.", completion = "Un plaisir de vous voir sain et sauf, &lt;nom&gt;. J'espère que les choses n'ont pas été trop compliquées pour vous.\n\nJe vais les apporter tout de suite à Tymor. Ça lui fera grand plaisir d'en prendre connaissance.\n\nAllez-y, jetez le lance-fusée, ne vous gênez pas... Vous n'en aurez probablement plus l'utilité à présent, et j'en ai déjà un nouveau.", rewards = "Vous recevrez :\n\n"},
[3450] = {title = "Une collecte facile", objective = "Parler à Xiggs Fuselighter à Ironforge.", description = "Je veux que les reproductions soient apportées à ma tour, mais il n'est pas nécessaire que vous fassiez tout le chemin jusque là-bas. Je vais simplement les faire transporter par les airs depuis Azshara.\n\nXiggs Fuselighter me doit un service ou deux et je serai bientôt dans le coin. On l'a embauché pour surveiller la côte. Allez lui parler avant de partir. Il pourra vous donner un lance-fusée pour que vous puissiez lui envoyer un signal. Lorsque vous serez en possession des reproductions, dirigez-vous vers l'endroit qu'il vous indiquera et donnez-les lui pour qu'il puisse les emmener en toute sécurité jusqu'à ma tour. Il devrait être au hangar du Quartier militaire.", progress = nil, completion = "Que puis-je faire pour vous, &lt;nom&gt; ? Je suis plutôt occupé en ce moment. Je prépare mon appareil pour un long voyage. Je passais juste pour voir les conducteurs de chars, j'ai besoin de quelques crinières de Wendigos pour embellir mon cockpit et ils en ont toujours en trop d'ordinaire.\n\nJe peux vous accorder une minute si vous faites vite... l'un des gars vient de décoller pour le Dépôt de Steelgrill pour voir s'il n'y a pas de crinières en trop que je pourrais prendre.", rewards = "Vous recevrez :\n\n"},
[3451] = {title = "Signal de la récupération", objective = "Parler à Xiggs Fuselighter à Ironforge et en obtenir un Lance-fusée standard.", description = "Ah, ainsi Tymor vous envoie, hein ? Oui, je lui dois un service ou deux. Qu'est-ce que c'est ? Eh bien, quel diable est-ce là... Oui, je peux lui donner un coup de main avec ça. Vous aurez besoin d'un lance-fusée et d'un lieu de rendez-vous… c'est simple.\n\nNous avons construit un site d'atterrissage sur une petite île au large de la péninsule au sud d'Azshara. Prenez ce lance-fusée, et utilisez-le là-bas. Je verrai votre signal et viendrai récupérer la marchandise... quoi que ce soit.", progress = nil, completion = "Voici mon lance-fusée standard, et soyez patient après avoir tiré. Ceux-là ne contiennent qu'une paire de charges, et il me faudra une minute ou deux pour vous atteindre, selon que je serai loin en mer ou pas. Surveillez simplement la mer une fois que vous aurez tiré la fusée.", rewards = "Vous recevrez :\n\nLance-fusée standard"},
[3452] = {title = "L'enveloppe de la flamme", objective = "Trouver et apporter un Symbole de Ragnaros à Velarok Lamevent.", description = "Nous avons besoin d'une dernière pièce pour former la torche.\n\nVous trouverez un grand campement du Marteau du crépuscule dans les montagnes au nord-ouest. La rumeur dit qu'ils portent des symboles et des idoles afin de rendre hommage à leur dieu. Il se peut que ces symboles et ces idoles portent en eux suffisamment d'enchantement pour former une enveloppe magique. Apportez un seul Symbole de Ragnaros et je tenterai d'en extraire la magie pour créer l'enveloppe de la flamme.", progress = "La Torche de vindicte ne pourra être achevée sans une source adéquate d'énergie magique.", completion = "Il émane de ce symbole une infecte magie. Cela convient parfaitement au dessein auquel nous le destinons.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3453] = {title = "La Torche de vindicte", objective = "Attendre que Velarok Lamevent termine la Torche de vindicte.", description = "Laissez-moi un moment afin que je combine les différentes parties et que j’y applique les enchantements nécessaires.", progress = nil, completion = "Il vous reste une dernière tâche à accomplir.", rewards = "Vous recevrez :\n\n"},
[3454] = {title = "La Torche de vindicte", objective = "Prendre la Torche de vindicte.", description = "La torche doit à présent être liée à <son/sa> propriétaire. Prenez-la, <nom> !", progress = nil, completion = "Vous prenez la torche des deux mains. Des vagues de colère et de haine vous submergent.", rewards = "Vous recevrez :\n\nTorche de vindicte"},
[3461] = {title = "Le retour vers Tymor", objective = "Rapporter la Trousse de dessin du mage Tymor au mage Tymor, à Ironforge.", description = "Tymor ne m'a rien donné avec lequel je puisse vous payer, aussi je suggère que vous abordiez le sujet directement avec lui lorsque vous retournerez à Ironforge. Il est certain qu'il occupe toujours la même place dans la Garde mystique. Frappez simplement à sa porte et assurez-vous qu'il vous rétribue correctement. Cela n'aura rien d'un pique-nique... c'est sûr...\n\nMerci encore pour l'aide que vous lui avez apportée cependant, et bonne chance.\n\nÀ propos, je n'ai plus besoin de la trousse de dessin. Pourquoi ne la rapporteriez-vous pas à Tymor lorsque vous irez le voir ?", progress = "Vous êtes de retour ! Merveilleux. Avez-vous également apporté ma Trousse de dessin ?", completion = "Fantastique ! Cela m'enchante de l'apprendre.\n\nJe suis si enthousiaste à l'idée de me rendre à ma tour et d'examiner ces reproductions. Je vous envie tellement… aller à un endroit tel qu'Azshara. C'est le rêve de tout étudiant des arcanes, je suppose.\n\nMais passons. Nous n'avons jamais parlé d'une récompense quelconque dans la mesure où vous travailliez pour la Ligue des Explorateurs. Mais vous méritez quelque chose.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes des forgeursOrbe Crânesort\n\nVous recevrez également :\n\n"},
[3462] = {title = "L'écuyer Maltrake", objective = "Parler à l'écuyer Maltrake.", description = "Adressez-vous à mon représentant, l'écuyer Maltrake. Il vous en apprendra davantage sur l'utilisation de la Torche de vindicte.", progress = nil, completion = "Êtes-vous prêt à frapper ?", rewards = "Vous recevrez :\n\n"},
[3463] = {title = "Allumer le feu !", objective = "Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour.", description = "Écoutez bien, <nom>. Bien que les quatre tours ne pourront jamais être détruites, vous pouvez vous servir de la Torche de châtiment afin d'y mettre le feu pour une longue période. Un incendie qu'aucun élément ou qu'aucune force ne pourra éteindre.\n\nTant qu'elles seront en flammes, aucun Garde ou aucune Sentinelle ne pourra y résider. Ainsi, leur première ligne de défense n'existera simplement plus.\n\nVous devez pénétrer dans chaque tour et utiliser la Torche de vindicte à l'intérieur des fortifications. Méfiez-vous des Sentinelles d'élite Sombrefer, <nom>.", progress = "Alors, <nom>, êtes-vous perdu ?", completion = "Formidable ! N'est-ce pas que c'est glorieux, maître ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières des dragonsProtège-front drakefeuHache du drake d'ébène\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3481] = {title = "Bibelots...", objective = "Ouvrir le coffre.", description = "Le coffre a l'air fermé.", progress = nil, completion = "Le coffre s'ouvre à votre contact. Quelle quantité de fromage peut-il bien y avoir là-dedans ? Il n'y a qu'un seul moyen de le savoir.", rewards = "Vous recevrez :\n\nTrésor du Vol noir"},
[3483] = {title = "Signal de la récupération", objective = "Oh, un autre lance-fusées, hein ? Je peux le faire.\n\nN'oubliez pas, la pointe sud d'Azshara. C'est une toute petite île transformée en piste d'atterrissage. Vous ne pouvez pas la manquer si vous êtes au bon endroit.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nLance-fusée standard"},
[3501] = {title = "Tout se compte en grandes quantités", objective = "Apporter des Fragments imparfaits de draenéthyste à Kum'isha et toucher une récompense pour chaque fragment rapporté.", description = "Même si vous ne pourrez jamais trouver une sphère de draenéthyste sans défaut, vous découvrirez sans doute divers fragments imparfaits de draenéthyste en explorant ces terres.\n\nJe doute que Kum'isha puisse les utiliser pour rentrer à la maison mais ils peuvent avoir une autre utilité pour les draeneï.\n\nApportez tous les fragments imparfaits de draenéthyste que vous pourrez et je vous récompenserai.", progress = "Avez-vous eu de la chance dans votre exploration ?", completion = "Vous me dégoûtez vraiment, &lt;nom&gt;. Une personne comme vous bavant sur une pile d'affaires bonnes pour le rebut ? Pitoyable ! Prenez votre récompense et sortez de ma vue.", rewards = "Vous recevrez :\n\nCamelote de Kum'isha"},
[3502] = {title = "Au rebut pour les draeneï", objective = "Apporter des Fragments imparfaits de draenéthyste à Kum'isha. N'importe quel monstres des Terres foudroyées peut détenir un fragment.", description = "Eh bien, après cette démonstration d'avidité vorace, j'ai la nausée.\n\nCela dit, je ne vais pas m'étendre trop longtemps sur votre penchant.\n\nPour chaque fragment imparfait de draenéthyste que vous m'apporterez, je vous récompenserai avec le même genre d'affaires bonnes pour le rebut. Mon tas d'affaires va diminuer tandis que le vôtre va devenir de plus en plus lourd. Sur Draenor, nous appelons cela une \"victoire sur toute la ligne\".", progress = "Et bien ? Les draenéthystes ? Vous vous rappelez ?\n\n< Kum'isha serre le poing et vous tape sur la tête >\n\nIl y a quelqu'un là-dedans ?", completion = "Vous me dégoûtez vraiment, &lt;nom&gt;. Une personne comme vous bavant sur une pile d'affaires bonnes pour le rebut ? Pitoyable ! Prenez votre récompense et sortez de ma vue.\n\nCe discours vous est familier ? Il devrait, parce que je le dis mille fois par jour.\n\nOh, comme je déteste ce monde.", rewards = "Vous recevrez :\n\nCamelote de Kum'isha"},
[3503] = {title = "Réunion avec le Maître", objective = "Autrefois, je pouvais demander tout ce que je voulais à ceux qui souhaitaient voir mon maître. À présent, vous n'avez qu'à demander et je vous enverrai à lui.\n\nCela me chagrine mais je ne discute pas ses ordres. Le seul plaisir qu'il me reste est de me moquer des vêtements ridicules que vous portez et de votre mine pitoyable. Même cela m'ennuie...\n\nMêmes ces bavardages m'ennuient ! Souhaitez-vous voir mon maître ou non ?", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTéléporte à la Tour d'Azshara"},
[3504] = {title = "Trahison", objective = "Apporter la Lettre Scellée à Ag'tor Bloodfist dans Azshara.", description = "Une traîtresse, une voleuse ! C'est ce qu'elle sera toujours !\n\nJ'ai fait une terrible erreur, <nom>. J'ai fait confiance à une elfe de sang !\n\nElle prétendait qu'Azshara renfermait de grandes richesses… Je n'avais qu'à envoyer quelques guerriers avec elle pour la protéger et j'en serais récompensé. Elle les a tous tués !\n\nJe réclame vengeance, <nom>, mais je ne peux pas envoyer quelqu'un d'autre. Allez voir Ag'tor à Valormok, au nord du campement des Haldarr. Il vous en dira plus.", progress = "Ah, Belgrom s'est dégonflé et a finalement envoyé quelqu'un d'autre pour nous aider, n'est-ce pas ?\n\nIl y avait dans ce camp une douzaine de bons guerriers, <nom>, mais maintenant ils sont tous morts. Ce mage, Rimtori, les a tous tués. Elle s'est moquée de Belgrom... Elle l'a même séduit. Ce n'est pas mon affaire, mais entre vous et moi, c'est une véritable tentatrice. C'est probablement pourquoi je suis toujours ici pour aider Belgrom : j'aurais probablement fait la même chose que lui.", completion = "Nous avons envoyé tout ce que nous pouvions face à elle et à ses ouvriers, mais ils sont forts au combat. Personne ne s'est donné la peine de revenir. Je suppose que certains sont morts, mais je suis sûr que d'autres ont simplement fui... comme des lâches.\n\nMais maintenant que les renforts sont arrivés, nous pouvons peut-être faire quelque chose. Nous pouvons peut-être la punir d'avoir menti à Belgrom et de l'avoir trahi ?\n\nQu'en dites-vous, vous acceptez ?", rewards = "Vous recevrez :\n\n"},
[3505] = {title = "Trahison", objective = "Tuer 10 Vengeurs elfes de sang et 10 Géomètres elfes de sang avant de rechercher le campement du magus Rimtori. Une fois le camp trouvé, chercher quelque chose d'important pour elle et qui peut être utilisé pour l'obliger à se battre.", description = "J'ai réfléchi.\n\nNous commençons notre croisade contre ses ouvriers au sud des falaises de la péninsule du nord d'Azshara. Tuez-les avec une colère sanglante, qu'ils sachent le prix de la trahison.\n\nNe vous occupez pas d'elle pour l'instant : elle passe son temps dans Azshara avec ses gardes du corps. Une fois ses ouvriers morts, il faudra trouver son campement personnel et faire une reconnaissance du terrain avant de l'attaquer. Nous trouverons peut-être quelque chose à utiliser pour la provoquer.", progress = "Le titre du livre est gravé en lettres d'or sur la couverture en cuir noir : \"Livre d'Invocation kaldorei\". En l'ouvrant, vous constatez que c'est un très vieux livre mais qu'il est en parfait état.\n\nVous supposez qu'il est écrit dans une langue ancienne... peut-être du Kaldorei ?\n\nVotre instinct vous dicte de revenir ici une fois que vous aurez fini de châtier les elfes de sang pour leur trahison.", completion = "Vous commencez à feuilleter les pages jusqu'à tomber sur une page marquée d'une mince bande de soie noire.\n\nEn essayant de la déchiffrer, vous voyez un diagramme en bas d'une des pages. Un rapide regard sur ce qui vous entoure et vous vous rendez compte que les cristaux, le cercle et même certains des autres composants du lieu où vous êtes sont disposés comme sur le diagramme du livre.", rewards = "Vous recevrez :\n\n"},
[3506] = {title = "Trahison", objective = "Détruire le Cristal de focalisation des arcanes lié au magus Rimtori et l'assassiner ensuite. Puis apporter la tête du magus Rimtori à Ag'tor Bloodfist dans Azshara.", description = "Quelques minutes de réflexion vous donnent des idées, dont l'une vous fait sourire : le fait de détruire les cristaux suffirait-il à provoquer l'elfe de sang responsable du meurtre de tant d'orcs et de la trahison de Belgrom ?\n\nVous continuez à déchiffrer le texte et les images du livre et vous vous rendez compte que l'un des cristaux est lié au créateur du cercle ; les autres sont liés à quelque chose de beaucoup plus sinistre.\n\nVous fermez le livre et commencez à chercher quel cristal détruire.", progress = "Comment avance l'élimination des traîtres elfes de sang, <nom> ? Avez-vous progressé ?\n\nJ'espère que vous avez la force de lui faire plier les genoux ! Elle ne mérite rien d'autre qu'une mort douloureuse pour tout ce qu'elle a fait !", completion = "Ah ! Incroyable !\n\nVous avez réussi ! Belgrom sera heureux ! L'esprit de douzaines de nos guerriers va enfin retrouver la paix. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[3507] = {title = "Trahison", objective = "Aller voir Belgrom Rockmaul dans Orgrimmar.", description = "Retournez voir Belgrom dans Orgrimmar. Il voudra voir sa tête de ses yeux ! Nous reviendrons bientôt.\n\nAh, c'est en effet une bonne journée. Merci pour votre aide, <nom>.", progress = "Je vous rappelle, <classe>, que je vous ai demandé d'aller à Azshara assassiner cette jeune femme qui m'a trahi ! Il me semble que c'était il y a des lunes. Ne me dites pas qu'Ag'tor et les autres sont morts aussi !", completion = "Ha ha ! Regarde-toi maintenant, misérable ! Je crache sur tes restes !\n\nMerci, &lt;nom&gt;. Merci du fond du cœur ! C'est un grand jour !\n\nJe vous donnerais un royaume si cétait en mon pouvoir ! Mais peut-être ceci vous conviendra-t-il.\n\n\n\nHa ha ! Stupide elfe de sang, regarde-toi maintenant... dans ton sac d'emballage et sans corps ! Tu n'aurais jamais dû trahir Belgrom !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe funéraireMarteau de Belgrom\n\nVous recevrez également :\n\n"},
[3508] = {title = "Briser l'Amulette", objective = "Attendre que Loramus ait achevé le rituel de Lumière.", description = "Vous êtes téméraire, <nom>. C'est une qualité admirable de votre espèce, le fait de foncer aveuglément dans la bataille alors qu'il n'y a aucune chance de succès, ou si peu. Je vous aiderai, ne serait-ce que pour voir tomber un seul des sbires de Razelikh.\n\nBriser la tutelle de Razelikh sur ses subalternes va prendre du temps et nécessitera l’utilisation d'artefacts rares.\n\nNe bougez plus, je dois commencer le rituel de Lumière. L'information que j'en tirerai m'aidera à façonner des armes de grand pouvoir.", progress = nil, completion = "Il faut trouver le nom de la bête.", rewards = "Vous recevrez :\n\n"},
[3509] = {title = "Le nom de la bête", objective = "Aller voir le seigneur Arkkoroc dans Azshara. Commencer la recherche au bord de l'eau pour trouver le temple d'Arkkoran.", description = "Il n'y a qu'une façon de nuire au Seigneur démon et à ses sbires. Il faut forger une arme qui portera son véritable nom.\n\nSi nous parvenons à forger une telle arme, le démon et toute sa clique seront vulnérables.\n\nIl y a dans Azshara un autre seigneur, le seigneur Arkkoroc. Vous devez le rechercher, mais attention, ses sbires n'hésiteront pas à vous éliminer s'ils vous découvrent.\n\nVous aurez certainement un prix à payer pour cette information.", progress = nil, completion = "Un seigneur-démon ?\n\n&lt;Le seigneur Arkkoroc se met à rire.&gt;\n\nIl se peut que l'élu puisse vous aider à obtenir ce renseignement. Mais d'abord, vous devez aider l'élu.", rewards = "Vous recevrez :\n\n"},
[3510] = {title = "Le nom de la bête", objective = "Assassiner Hetaera et apporter la Tête ensanglantée d'Hetaera, la Tête battue d'Hetaera et la Tête meurtrie d'Hetaera au seigneur Arkkoroc.", description = "Elle tue mes enfants, <mortel/mortelle>. Celle qui se proclame souveraine de ces océans. Une fausse déesse, rien de plus. Écrasez-la et apportez-moi chacune de ses têtes.\n\nEn échange, vous obtiendrez le nom que vous cherchez et autre chose, d'importance égale.\n\nElle rôde sur la couvée... Elle se nomme Hetaera.\n\n<Le seigneur Arkkoroc désigne le sud-ouest.>\n\nAllez-y !", progress = "<Le seigneur Arkkoroc se penche pour vous examiner.>\n\nOù sont-elles ?", completion = "Enfin une personne digne de la sagesse d'Arkkoroc !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3511] = {title = "Le nom de la bête", objective = "Rapporter le durcisseur à Loramus Thalipedes.", description = "Comme promis, je vais vous révéler le nom du seigneur-démon : Razelikh le Souilleur. Mais tout d'abord, je dois préparer quelque chose de la plus grande importance pour votre voyage.\n\nL'arme que vous cherchez à confectionner nécessite une trempe particulière. Laissez-moi quelques instants pour vider le sang de ces têtes.\n\n<Le seigneur Arkkoroc presse les têtes entre ses gigantesques poings, exprimant ainsi tout le sang.>\n\nApportez la trempe à Loramus, ainsi que le nom de la bête : Rakh'likh.", progress = "Vous êtes là ! Etonnant, <nom>. Avez-vous découvert le véritable nom ?", completion = "Le durcisseur ajoutera ce qui nous manquait pour créer ces armes. Il n'y a plus qu'une étape dans leur création.", rewards = "Vous recevrez :\n\n"},
[3512] = {title = "Par les mots d'Eranikus", objective = "Se rendre dans la partie orientale du Berceau-de-l'Hiver et aller voir Umbranse l'implorateur d'esprit.", description = "<nom>, nous devons d'abord inventer une méthode pour parler à Eranikus par l'intermédiaire de la gemme. Il se trouve entre le sommeil et la mort, dans un enfer de cauchemars. Même si l'essence que vous m'avez donnée est infectée, nous avons une chance de l'atteindre.\n\nVous devez aller jusqu'aux terres glacées de l'est du Berceau-de-l'Hiver et chercher un de nos alliés mortels, l'implorateur d'esprits Umbranse. Il parle aux morts. Quoiqu'Eranikus ne soit pas vraiment mort, il pourra peut-être nous aider.", progress = nil, completion = "Itharius a été sage de vous envoyer à moi. Même s'il n'est pas mort au sens où vous l'entendez, Eranikus nous parlera bientôt lui-même. Pour le moment cependant, je ne peux pas directement vous aider... pas encore.\n\nJe me mets à votre disposition mais d'abord j'ai besoin de l'aide de quelqu'un qui (à la différence de moi) n'est pas limité par la vieillesse. Mon instrument d'augure le plus puissant m'a été pris et à moins de le récupérer, nous n'arriverons pas à aider Eranikus.", rewards = "Vous recevrez :\n\n"},
[3513] = {title = "Le Parchemin runique", objective = "Apporter le Parchemin runique à la tour de garde Nord dans les Tarides.", description = "Ce parchemin à l'air très officiel est fermement entouré d'un ruban argenté. Vous pensez que ça intéresserait sûrement quelqu'un de le voir, mais qui ?\n\nIl y a un avant-poste au nord de la frontière d'Ashenvale et si l'information sur ce rouleau concerne les elfes de la nuit, c'est le bon endroit pour l'apporter.", progress = "Qu'est-ce que vous avez ?", completion = "Ma foi... Où l'avez-vous trouvé ?", rewards = "Vous recevrez :\n\n"},
[3514] = {title = "Présence de la Horde", objective = "Tuer le chef de l'Antre des Serres, Rynthariel le Maître des clés.", description = "Ce parchemin vient de la dryade rusée nommée Rynthariel, Maître des clés de l'antre des Serres, au pic des Serres-Rocheuses.\n\nElle ne pourra plus contacter la personne sur qui vous l'avez pris, hein ? Mais nous devons renforcer notre position. La Horde ne tolérera pas qu’on lui dispute ces lieux.\n\n<nom>, partez pour l'antre des Serres. Tuez Rynthariel, et placez un symbole que tous pourront voir et comprendre. Prenez le drapeau de la Horde, <nom>. Hissez-le dans l'antre des Serres, qu'ils n'aient pas la témérité d'envoyer un autre messager.", progress = nil, completion = "Vous faites partie des durs ! Aller à l'Antre de Rynthariel est une étape majeure, &lt;nom&gt;. Ils tarderont à se regrouper et nous pouvons compter sur le fait qu'il y aura moins de membres de l'Alliance dans les Tarides. Ils réfléchiront avant d'envoyer quelqu'un d'autre.\n\nMerci.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes TrailblazerGants en jute tressée\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3516] = {title = "<INUTILISÉ>", objective = "Vous recevrez :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[3517] = {title = "L'art du vol", objective = "Trouver la Tablette de Beth'Amara, la Tablette de Jin'yael, la Tablette de Markri et la Tablette de Sael'hai puis retourner voir Jediga dans Azshara.", description = "J'admets avoir profité de ma situation dans Azshara, <nom>. La punition de Belgrom a eu de bons côtés.\n\nJ'y ai fait des recherches et vous seriez <étonné/étonnée> de voir combien il y a d'objets de valeur ici.\n\nJe vous en dirai plus sur mes affaires et vous ferai participer aux profits, si vous m'aidez à les récupérer.\n\nJ'ai besoin de tablettes disposées partout dans les ruines d'Eldarath, à l'est d'ici. Les quatre portent le nom de sorciers bien-nés. Trouvez-les pour moi et nous discuterons.", progress = "Les tablettes que je vous ai demandé de trouver vont nous rapporter pas mal d'argent si on les propose aux bonnes personnes. Je vous dirai à qui les livrer quand vous les aurez trouvées. Mais je ne suis pas idiote... vous n'aurez votre part que lorsque j'aurai eu la preuve qu'elles ont été livrées.\n\nAllons-y : nous n'avons pas toute la journée. Je dois trouver quelqu'un d'autre pour m'aider.", completion = "Parfait, &lt;nom&gt; et en plus, en bon état. Nous en obtiendrons un bon prix de leurs acquéreurs.\n\nNe traînons pas plus longtemps par ici. Il y a de l'argent à se faire.", rewards = "Vous recevrez :\n\n"},
[3518] = {title = "Livraison à Magatha", objective = "Apporter la Tablette de Beth'Amara à Magatha dans Thunder Bluff.", description = "La première tablette va à un tauren femelle... Elle s'appelle Magatha. Elle se trouve parmi les anciens dans Thunder Bluff et elle est l'un des partisans de l'alliance entre les taurens et les Réprouvés. Plus que n'importe lequel des anciens, elle sent que les taurens et leurs connaissances peuvent aider les Réprouvés à redevenir des hommes.\n\nApportez-lui la Tablette de Beth'Amara. La tablette est peut être le lien dont elle a besoin pour aider les Réprouvés... ou du moins c'est ce qu'elle dit.", progress = "Oui, <nom>. Qu'est-ce que je peux faire pour vous ? J'ai beaucoup de choses à faire, s'il vous plaît, faites vite.", completion = "Ah, enfin, la Tablette de Beth'Amara. Je me demandais si mon association avec Jediga avait échoué ou si cette pauvre orc avait trouvé la mort dans Azshara. Je vois avec plaisir qu'elle a réussi.\n\nBeth'Amara était l'un des alchimistes bien-né les plus influents. On a dit d'elle qu'elle avait réussi à transmuter des métaux en d'autres choses.", rewards = "Vous recevrez :\n\n"},
[3519] = {title = "Un ami dans le besoin", objective = "Parler à Dirania Silvershine, à Sombrevallon.", description = "Ahhh... J'ai été mordu par une araignée nommée Githyiss la Vile en explorant sa caverne, tout près d'ici. Une grande quantité de poison m'a été injectée ; vous devez m'aider.\n\nPrévenez Dirania Silvershine. Elle sera capable de me secourir.\n\nVite... J'ai des vertiges de plus en plus alarmants...", progress = nil, completion = "Oh par les dieux ; je me demandais pourquoi je n'avais pas encore vu Iverron aujourd'hui. Et moi qui le mettais toujours en garde contre ces araignées...", rewards = "Vous recevrez :\n\n"},
[3520] = {title = "Esprits de Hurleurs", objective = "Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression.", description = "Je cherche les esprits des hurleurs des vallées de Feralas. Ils sont cousins d'un dieu fort ancien et leurs esprits lui sont liés.\n\nPrenez ce roncier magique et allez en Feralas pour y trouver les hurleurs des vallées, au sud et au centre. Tuez-les, puis agitez ma baguette au-dessus d'eux. Cela exhortera leur esprit à se révéler. Touchez les esprits et prenez leur essence.\n\nRevenez me voir avec ma baguette et les esprits et je vous en dirai plus de ce dieu ancien dont je vous ai parlé.", progress = "Avez-vous trouvé l'Essence d'Esprits de Hurleurs, <nom> ?", completion = "Vous avez réussi, &lt;nom&gt;. Il est temps maintenant de vous en révéler davantage... \n\nIl y a une ancienne prophétie chez les trolls, qui raconte qu'un jour leur dieu mort, Hakkar l'Ecorcheur d'âmes, reviendra sur cette terre. Certains disent que son arrivée apportera la joie et la gloire aux trolls, d'autres croient que sa résurrection marquera la fin de tout.\n\nJe ne crois pas à ce mythe, mais je reconnais que l'Essence d'Hakkar possède un grand pouvoir, lequel doit être tenu à l'écart de ceux qui voudraient en abuser...", rewards = "Vous recevrez :\n\n"},
[3521] = {title = "Antidote d'Iverron", objective = "Trouver 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d'araignée Tissebois pour Dirania Silveshine dans Sombrevallon.", description = "Nous allons pouvoir aider Iverron, je connais un antidote qui devrait combattre le poison. Il me faut cependant quelques ingrédients.\n\nJe vais avoir besoin de Champignons jacinthe. Vous pouvez en trouver sous les arbres, ou chez les grells au sud ; ils ont l'air de les aimer. J'aurai aussi besoin de Lys pétales de lune, qui ne poussent qu'autour des points d'eau.\n\nLe dernier ingrédient sera plus difficile à trouver. Il me faut de l'ichor de ces mêmes araignées sylvestres qui ont empoisonné Iverron.", progress = "Je vous en prie, rassemblez les ingrédients, <nom>. Iverron a besoin de notre aide.", completion = "Remerciez Elune d'avoir trouvé ces ingrédients si vite !\n\nDans un petit moment, j'aurai préparé l'antidote.", rewards = "Vous recevrez :\n\n"},
[3522] = {title = "Antidote d'Iverron", objective = "Apporter l’Antidote d'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord.", description = "L'antidote est prêt, <nom>. Faites en sorte qu'Iverron le boive.\n\nVous devez savoir une chose : l'antidote ne reste efficace que pendant 5 minutes. Vous devez le lui apporter à temps.\n\nQue la vitesse soit avec vous, <nom>.", progress = "Oh... <nom>, je suis si heureux que vous soyez de retour.", completion = "Qu'est-ce que c'est, &lt;nom&gt; ?\n\nOh, je savais que Dirania pourrait m'aider !\n\n\n\nJe m'attire toujours des ennuis et Dirania réussit toujours à m'en sortir.\n\nJe me sens beaucoup mieux mais je pense que je vais rester assis ici un peu plus longtemps, jusqu'à ce que je me sente vraiment rétabli. Et aussi le temps que vous... comment dire, j'espérais que vous pourriez me frayer un passage au milieu de ces vicieuses araignées Tissebois...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChausses en jonc tresséHaubergeon d'écorce\n\nVous recevrez également :\n\n"},
[3523] = {title = "Le Fléau des Souilles", objective = "Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée.", description = "Remarquable ! Mon nom est Belnistrasz et je vous remercie de m'avoir secouru. Je me voyais déjà mort... ou pire, transformé en repas pour cette vermine infestée par le Fléau. Oui, j'ai dit le Fléau à dessein : ici, ils ont négocié une sorte d'accord avec les hurans et ce cauchemar en est le résultat.\n\nÉcoutez, plutôt que de fuir, voulez-vous m'aider à en finir ? C'est probablement dangereux, mais vous semblez être du genre à ne pas vous inquiéter pour si peu.", progress = "Je ne fais pas de politique, peu m'importe que vous soyez affilié à la Horde ou à l'Alliance. Je préfère m'occuper des menaces qui concernent toutes les races... Et nous en avons une de taille à affronter.\n\nSi vous souhaitez devenir un héros pour tous les peuples, donnez-moi la Pierre de voeu que je vous ai remise comme preuve d'engagement. Je ne suis pas d'ici ; la Pierre de voeu est une garantie de confiance pour les gens de mon espèce.", completion = "Fantastique, je pensais que vous vouliez devenir un héros ! Il reste encore du travail, &lt;nom&gt;, je ne vous mentirai pas. Si nous restons concentrés et travaillons dur, nous serons à même de nous en sortir.\n\nMaintenant, laissez-moi vous expliquer ce qui se prépare...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3524] = {title = "Echouage", objective = "Récupérer des Os de créature marine sur la créature échouée, au sud d’Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine.", description = "De majestueuses créatures marines se jettent sur le littoral de Sombrivage, où elles restent échouées jusqu’à leur mort. Dernièrement, le nombre de ces bêtes n’a cessé d’augmenter. C’est le temple de la Lune qui m’envoie pour enquêter, mais la présence des murlocs, sur le littoral, a freiné mes recherches.\n\nIl y a une créature géante échouée au sud d’Auberdine, et beaucoup de ces maudits murlocs Grisebrume aux alentours. Pourriez-vous aller récupérer des os sur la carcasse de cette créature ? Ils nous serviront pour nos études.", progress = "Ce n'est que récemment que ces créatures ont commencé à venir s'échouer en nombre alarmant sur les côtes de Sombrivage. Je ne peux vous aider, mais je pense que c'est un mauvais présage. Allez au sud, récupérez un échantillon des os de cette créature. Cela nous permettra de mener des recherches à Darnassus et de comprendre ce qu'il se passe !", completion = "J'espère que les murlocs ne vous ont pas posé trop de problèmes lorsque vous avez récupéré ceci pour nous ! Je ne manquerai pas de confier cela au prochain hippogryphe pour Darnassus. Le temple de la Lune m'a donné quelques fonds pour dénicher de l'aide. Prenez-en votre part, avec tous nos remerciements.\n\nVotre succès me donne envie de vous offrir une nouvelle chance d'aider le temple de la Lune une fois de plus, si ça vous chante...", rewards = "Vous recevrez :\n\n"},
[3525] = {title = "L'extinction de l'idole", objective = "Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.\n\nProtéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole.", description = "Près de l’entrée, il y a une idole qui sert de four aux hurans, ces bêtes... ils consument ceux qu’ils enlèvent dans les Tarides. Je peux faire en sorte qu’ils ne puissent plus jamais s’en servir, mais j’ai besoin de votre aide. Voici mon plan : escortez-moi jusqu’à l’idole, quand nous arriverons, je commencerai le rituel. Pendant ce temps, je ne pourrai pas communiquer avec vous et encore moins me défendre. Protégez-moi pendant que je détruis l’idole. S’il parviennent à m’abattre, tout est fini.\n\nÊtes-vous avec moi ?", progress = nil, completion = "Belnistrasz disparaît soudain derrière un brasero enflammé. Alors que vous regardez fixement les flammes, l'image d'un dragon rouge à grandes ailes vous vient à l'esprit. La voix de Belnistrasz, plus aigrelette que d'habitude, vous parle.\n\n\" \"Vraiment, mortels, vous êtes les héros que j'espérais. Grâce à vous, la boucherie perpétrée par ces bêtes a pris fin. Ma foi dans les mortels comme vous est renouvelée. Prenez ceci, la récompense des héros.\"", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nAnneau Dragonclaw"},
[3526] = {title = "Ingénierie des gobelins", objective = "Pour en apprendre davantage sur l'Ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring dans Gadgetzan.", description = "La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. L'Ingénierie des gobelins est clairement le choix de tous les ingénieurs brillants. Apprendre à vaincre le monde par l'utilisation judicieuse d'explosifs et d'incroyables mécanismes !\n\n<nom>, lisez ce manuel. Si vous voulez en apprendre plus, apportez-le à Nixx Sprocketspring à Gadgetzan. Mais attention : l’adhésion à cette discipline est définitive et exclusive, alors soyez <sûr/sûre> de faire le bon choix !", progress = "Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l'art de l'explosion ?", completion = "Bien &lt;nom&gt;, vous avez été avisé de choisir mon enseignement ! N'importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d'Ingénierie des gobelins.\n\nOuvrez vos oreilles, &lt;nom&gt;, et vous pourrez apprendre beaucoup.", rewards = "Vous recevrez :\n\n"},
[3527] = {title = "La prophétie de Mosh'aru", objective = "Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris.", description = "La prophétie ancienne de Mosh'aru explique comment contenir l'essence du dieu Hakkar. Elle a été écrite sur deux tablettes, apportées à la cité troll de Zul'Farrak, à l'ouest de Gadgetzan.\n\nApportez-moi les Tablettes Mosh'aru !\n\nLa première tablette est détenue par le troll Theka le Martyr, mort depuis longtemps. On raconte que ses bourreaux ont été changés en scarabées et qu'ils parcourent à présent son autel.\n\nLa seconde tablette est détenue par l'Hydromancienne Velratha, près du bassin sacré de Gahz'rilla.\n\nUne fois que vous aurez les tablettes, apportez-les-moi.", progress = "Avez-vous les tablettes de la Prophétie de Mosh'aru, <nom> ?\n\nQuand j'aurai ces tablettes, je pourrai les étudier et apprendre comment retenir l'Essence d'Hakkar !", completion = "Ah, c'est bon. Je peux assembler ces tablettes anciennes pour étudier les secrets qu'elles contiennent.\n\nMa dette envers vous ne cesse de croître, &lt;nom&gt;. Et ce n'est pas terminé.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3528] = {title = "Le dieu Hakkar", objective = "Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris.", description = "Maintenant il faut capturer l'essence de l'avatar d'Hakkar.\n\nApportez l'Oeuf d'Hakkar au Sanctuaire du dieu déchu dans le Temple englouti d'Azeroth. Invoquez le pouvoir de l'œuf pour réveiller le dieu mort.\n\nIl enverra ses sbires contre vous. Combattez-les et prenez leur sang Hakkari, puis versez-le sur les flammes éternelles qui retiennent l'esprit d'Hakkar. Une fois les flammes éteintes, l'avatar d'Hakkar entrera dans notre monde.\n\nCombattez-le et placez son essence dans l'œuf d'Hakkar.", progress = "Avez-vous vaincu l'avatar d'Hakkar, <nom> ? Son essence a-t-elle redonné pouvoir à l'œuf que je vous ai donné ?", completion = "L'essence d'Hakkar a été trouvée ! Et même, l'œuf revient maintenant à la vie ! Les mythes d'Hakkar pourraient-ils être vrais ?\n\nCe n'est pas possible, ou alors, j'ai peur de ce que pourrait faire Hakkar s'il naissait de nouveau. Je vais enfermer l'œuf dans ce coffre-fort pour qu'il ne tombe pas dans de mauvaises mains.\n\nVotre travail pour moi est terminé, &lt;nom&gt;. Vous entrez dans la légende et vos actions changeront peut-être un jour la face de notre monde.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHeaume de l'Avant-gardeMiséricorde de force vitaleDiadème suprême\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3530] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[3531] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[3541] = {title = "Livraison pour Jes'rimon", objective = "Apporter la Tablette de Jin'yael à Jes'rimon dans Orgrimmar.", description = "J'ai un copain dans Orgrimmar. Il réside dans la rue principale. Il est difficile à trouver si vous ne savez pas où regarder, mais allez voir dans les bâtiments les plus hauts et vous devriez sans peine tomber sur lui.\n\nFaites-moi une faveur : n'allez pas répéter à tout Kalimdor qu'il est là : ce serait mauvais pour lui comme pour moi.\n\nIl nous donnera un prix plus qu'honnête pour la Tablette de Jin'yael. Je ne sais pas pourquoi, mais vous auriez dû voir comme il était excité quand je lui en ai parlé.", progress = "Ouais, voulez quoi ? J'ai des trucs à faire, jourd'hui, et z'en faites pas partie. Mais si vous me gonflez trop, j'vous garantis que j'm'occupe de vous.", completion = "Ah, Jediga m'envoie son paquet d'Azshara. Bien. C'est c'que j'attendais.\n\nJediga, c'est une femme bien... Et une mortelle aussi. Que d'mander de plus ?\n\nVoyons... La tablette est en très bon état. Vous faites l'affaire comme messager, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[3542] = {title = "Livraison à Andron Gant", objective = "Apporter la Tablette de Markri à Andron Gant dans Undercity.", description = "Andron Gant est mon contact suivant. Il se terre habituellement dans Undercity, tout près de l'Apothicarium.\n\nQuand il est venu me voir, il était plus loquace qu'à l'ordinaire et il m'a dit pourquoi il voulait la Tablette. Apparemment, des mages d'Undercity veulent étudier certains des charmes mystérieux que les Bien-nés utilisaient. Ils pensent que cette tablette les y aidera. Markri était expert en invocation de créatures, surtout des élémentaires.\n\nApportez la Tablette de Markri et revenez me voir pour votre récompense.", progress = "Eh bien... <hic>... Quelle surprise ? Quelqu'un qui cherche l'aventure... <hic> !\n\nQue puis-je pour vous... <hic> ?", completion = "Prenez quelques pièces de monnaie... Servez-vous... &lt;hic&gt;... Une nouvelle armure ou quelque chose du genre...\n\nVa apporter un peu d'or... &lt;hic&gt; aux bonnes personnes.", rewards = "Vous recevrez :\n\n"},
[3561] = {title = "Livraison à l'archimage Xylem", objective = "Apporter la Tablette de Sael'hai à l'archimage Xylem dans Azshara.", description = "Cette dernière tablette est destinée à quelqu'un de très dangereux, <nom>. Croyez-moi, je lui fais encore moins confiance qu'aux autres.\n\nL'archimage Xylem habite une tour en haut des collines qui entourent Azshara. Il est humain, mais il n'agit comme aucun autre humain. La puissance se dégage de tout son être et je n'ose lui demander ce qu'il veut faire de la tablette.\n\nSon garde du corps Sanath doit m'aider à parvenir à la tour lorsque je serai prêt à le rencontrer. Allez chercher Sanath, au nord.", progress = "Comment puis-je vous aider, <nom> ?", completion = "Ah, la Tablette de Sael'hai... Il y a longtemps que j'ai envie de l'étudier.\n\nMerci, &lt;nom&gt;. Vous pouvez dire à Jediga qu'elle a réussi. Le paiement qu'elle a demandé est mérité.", rewards = "Vous recevrez :\n\n"},
[3562] = {title = "Le Paiement de Magatha à Jediga", objective = "Apporter la Note de Magatha à Jediga dans Azshara.", description = "Portez cette note à Jediga. Dites-lui que son paiement l'attendra à son retour. Et dites-lui que son travail est satisfaisant.\n\nFaites vite, <nom>. Dites à votre Maître que je l'attendrai ici.", progress = "Alors, qu'a dit Magatha ? La vieille bique... Je parie qu'elle a été moins que polie.", completion = "Ah, bon. Elle a été beaucoup plus raisonnable que je ne m'y attendais... du moins vis-à-vis de vous. Je pensais qu'elle vous punirait pour mon insolence, le fait d'avoir envoyé quelqu'un à ma place. Elle doit vraiment vouloir cette tablette. Intéressant.\n\nC'est à retenir pour une autre fois.", rewards = "Vous recevrez :\n\n"},
[3563] = {title = "Le Paiement de Jes'rimon à Jediga", objective = "Apporter la Note de Jes'rimon à Jediga dans Azshara.", description = "Portez cette lettre à Jediga. Faites-lui savoir que notre accord a été rentable et que son travail me satisfait.\n\nDites-lui de revenir vite à Orgrimmar et que Jes'rimon prendra bien soin d'elle.\n\nDites-lui tout cela et j'aurai peut-être besoin de vos services dans le futur, <nom>.", progress = "Avez-vous déjà vu Jes'rimon ?\n\nIl est comme un sanglier parmi les trolls, mais ses informations sont précises et ses emplois bien payés.\n\nSi vous pouvez supporter son attitude, il y a de l'argent à se faire en participant à ses affaires.", completion = "Je vois qu'il était très satisfait... Un peu trop sans doute.\n\nJe m'occuperai de lui faire savoir un jour combien j'apprécie ses avances. Voilà au moins une bonne raison de passer plus de temps à Azshara.\n\nVoici votre part du paiement.", rewards = "Vous recevrez :\n\n"},
[3564] = {title = "Le Paiement d'Andron à Jediga", objective = "Apporter la Note d'Andron à Jediga dans Azshara.", description = "Ici... Portez... <hic> cela à Jediga. Bonne chance !", progress = "Avez-vous déjà vu Andron ? Il quitte rarement Undercity, alors je ne pense pas qu'il sera très dur de le trouver.", completion = "Parfait... Attendez un instant.\n\nHa ha ! Que lui avez-vous dit quand vous avez livré la tablette, &lt;nom&gt; ? Il nous a plus que surpayés ! ce n'est pas que je me plaigne. Lui avez-vous dit que l'accord avait changé ? Ou avait-il encore bu ?\n\nAucune importance... Prenez une part supplémentaire vous aussi.", rewards = "Vous recevrez :\n\n"},
[3565] = {title = "Le Paiement de Xylem à Jediga", objective = "Apporter la Note de Xylem à Jediga dans Azshara.", description = "Qu'est-ce que c'est ? Oh oui, votre paiement, bien sûr !\n\nPrenez cela et repartez. Je suis sûr que Jediga attend avec une grande, grande patience votre retour.", progress = "Ah, qu'est-ce que Xylem a à me dire ? Il ne vous a rien fait, n'est-ce pas ? Il vous a jeté un sort ? Pour vous faire travailler pour lui ?", completion = "Aucun problème ? Vraiment aucun ? Bien, c'est bon à savoir... je m'attendais à ce qu'il montre une sorte de répugnance ou qu'il trahisse notre accord. Hum, on peut peut-être lui faire confiance après tout.\n\nBien, aucun intérêt de toute façon. Voici votre part. Merci pour votre aide.", rewards = "Vous recevrez :\n\n"},
[3566] = {title = "Debout, Obsidion !", objective = "Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Ironforge, avec la Tête de Lathoric le Noir et le Coeur d'Obsidion.", description = "C'était... C'était... C'était un piège.\n\nOubliez... moi.\n\nTuez ce bâtard… Tuez-le pour nous… pour Thorius.", progress = "Je ne vous crois pas ! Prouvez-le-moi !", completion = "&lt;Thorius devient livide.&gt;\n\nNon... Cela est impossible. Mon propre frère ? Il a fait cela ?\n\n&lt;Le visage de Thorius se crispe de colère&gt;\n\nIl m'a trahi, il a trahi Ironforge ! Il semble que l'influence des Dieux très anciens soit toujours forte sur ces terres. À voir mon frère (autrefois un homme noble et honorable) si facilement soumis à la volonté de Ragnaros, je crains que personne ne soit en sûreté.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCuissards de centurionCasque de LordrecAnneau de robustesse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3567] = {title = "Au sommet", objective = "Souhaitez-vous admirer la vue depuis le sommet de l'un des Colosses jumeaux ? Je peux vous y envoyer, <race>.\n\nRéfléchissez quand même à la façon de redescendre. C'est un voyage que l'on ne peut faire que dans un seul sens.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTéléportation des Colosses jumeaux"},
[3568] = {title = "Corruption Suintante", objective = "Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides aux étangs des marées, le long de la côte des Ruines d'Eldarath, à Azshara.", description = "Regardez cette taurène derrière moi, celle qui a l'air de se trouver mal. Elle était dans Azshara récemment. Elle prétend avoir été blessée par des nagas en traversant les ruines d'Eldarath.\n\nAprès les avoir repoussés, elle s'est reposée sur la plage et a bu dans l'un des étangs de marée. Maintenant elle est malade.\n\nJe veux découvrir ce qu'elle a bu. Prenez cette boîte, avec quelques fioles vides que j'ai étiquetées. Remplissez chacune d'elle dans un étang différent et revenez me voir.", progress = "Vous savez où cela va nous mener, n'est-ce pas, <nom> ? Elle ne peut pas survivre...  Regardez-la. Le mieux pour elle maintenant, c'est de nous aider à trouver un remède pour combattre la peste. Cette eau qu'elle a bue pourrait nous donner des indices. Elle va mourir de toute façon : autant que sa mort serve noblement ceux de notre peuple. Vous n'êtes pas d'accord ?", completion = "Merveilleux. Vous êtes de retour avant qu'elle ne soit morte. Bon, bon.\n\nCommençons, alors.\n\nIl y a un moment que j'étudie ses symptômes maintenant et c'est vraiment laid. Je suis étonné qu'elle soit toujours debout. Elle a vomi partout trois ou quatre fois... une odeur vraiment plaisante.\n\nDonnez-moi juste une minute pour préparer un remède à tester sur notre... amie.", rewards = "Vous recevrez :\n\n"},
[3569] = {title = "Corruption Suintante", objective = "Donner l’élixir de Cuely à Thersa Windsong, à Undercity.", description = "Donnez-le à Thersa. Peut-être que ça va guérir sa... Ou peut-être pas. Nous ne le saurons que lorsqu'elle aura bu.", progress = "Je suis venu à Undercity parce que j'ai entendu dire que leurs alchimistes avaient étudié longtemps la façon de trouver un remède à leur propre maladie. On m'a dit qu'ils pourraient peut-être m'aider moi aussi.\n\nBien que cet endroit ne soit pas vraiment accueillant, je n'avais pas le choix : la maladie que j'ai attrapée me détruit de l'intérieur et j'ai besoin de leur aide tout de suite.", completion = "Le chimiste Cuely a été très conciliant... C'est un peu inquiétant d'ailleurs. Mais s'il affirme que cela m'aidera, je n'ai pas d'autre choix. Je n'ai pas le temps de trouver une autre solution. J'ai déjà parlé avec les prêtres et les chamans, et ils ne peuvent rien pour moi.\n\nEspérons que la Terre-mère veille sur mon esprit.", rewards = "Vous recevrez :\n\n"},
[3570] = {title = "Corruption Suintante", objective = "Je n'aurais jamais rêvé que l'élixir puisse prendre forme aussi rapidement. Merci, <nom>. Je vais travailler sur le reste de ces échantillons tout de suite. Je suis sûr qu'ils seront bientôt utilisables par Dame Sylvanas et les Réprouvés.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[3581] = {title = "<INUTILISÉ>", objective = "Retourner voir Saern Cours-avec-fierté pour apprendre la compétence de Course dans les plaines.Imaginez-vous en train de courir dans les plaines, les forêts et les montagnes, le visage dans le vent... De voyager en terres inconnues ; l'étonnement de la découverte de la route, votre destin lié au seul horizon.\n\nDites-vous que sur un sabot, on peut réaliser beaucoup de choses ; en tant que tauren, vous bénéficierez de la rapidité de la Course dans les plaines. Il n'y a aucune limite aux distances que vous pourrez parcourir.", description = "Imaginez-vous en train de courir dans les plaines, les forêts et les montagnes, le visage dans le vent... De voyager en terres inconnues ; l'étonnement de la découverte de la route, votre destin lié au seul horizon.\n\nDites-vous que sur un sabot, on peut réaliser beaucoup de choses ; en tant que tauren, vous bénéficierez de la rapidité de la Course dans les plaines. Il n'y a aucune limite aux distances que vous pourrez parcourir.", progress = nil, completion = nil, rewards = nil},
[3601] = {title = "Kim'jael évidemment !", objective = "Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim'Jael, puis les lui rapporter à Azshara.", description = "Kim'jael, effectivement ! Savez-vous ce que Kim'jael signifie chez les elfes de sang, <nom> ? Petit rat... ou quelque chose comme ça. Quels imbéciles !\n\nIls m'ont embauché pour aider à reconnaître le secteur et pour chercher des genres de trésors perdus. Je me suis évidemment précipité lorsque j'ai entendu le mot \"trésor\" et le montant qu'ils allaient me payer, mais ils m'ont bien entendu trahi et ont essayé de me tuer... MOI !\n\nC'est pour vous dire, on ne peut jamais faire confiance à un elfe de sang.\n\nMaintenant, le problème, c'est qu'ils sont en possession de mon équipement et que je ne peux pas le récupérer. Vous voulez m'aider ?", progress = "Ces fichus elfes de sang ! Je vous le dis, si j'étais aussi fort que vous, j'irais là-bas et je leur dirais deux mots moi-même ! Mais il faudra que je me contente de vous payer pour faire le travail à ma place.", completion = "Ha ha ! Vous les avez eus, n'est-ce pas ?!\n\nC'est formidable ! Cela apprendra à ces elfes de sang à trahir leurs partenaires… particulièrement quelqu'un d'aussi loyal qu'un marchand gobelin ! Bah, les elfes de sang… !\n\nBon, le moins que je puisse faire est de vous dédommager pour votre temps... comme je l'avais dit.\n\nVoilà pour vous... Cela devrait vous être utile.", rewards = "Vous recevrez :\n\nGrenade à fragmentation M73"},
[3602] = {title = "Azsharite", objective = "Trouver 20 Azsharites cristallisées au sud d'Azshara. Utiliser éventuellement le gangrechien pour ‘renifler’ l'emplacement où sont intelligemment cachés les dépôts.\n\nRetourner voir Loramus une fois votre tâche accomplie.", description = "Les anciens géants des falaises de la région du sud d'Azshara se nourrissent de la roche et des constructions locales. Leurs excréments forment un cristal très malléable et extrêmement solide appelé azsharite.\n\nOn le trouve dans le Cercle du sud, mais on en récupère peu en raison du tempérament extrêmement violent des géants.\n\nVous devez aller au sud et récupérer suffisamment d'azsharite pour créer le corps de l'arme. Mes gangrechiens vous aideront à trouver le cristal.", progress = "Le mal ne dort jamais, imbécile. Vous aurez le temps de vous reposer quand vous serez mort. Maintenant, apportez-moi ces cristaux.", completion = "Votre tâche à Azshara est terminée. Je dois maintenant forger ce qui va vous être nécessaire pour poursuivre vos aventures.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3621] = {title = "La Formation de Felbane", objective = "Apporter la cargaison à Galvan l'Ancien dans la vallée de Strangleronce.", description = "Les armes sont prêtes à être forgées. Vous devez apporter l'azsharite à quelqu'un qui saura en exploiter l'énergie.\n\nIl y a un forgeron dans la Vallée de Strangleronce. Galvan l'Ancien, le chef de l'Ordre du Mithril, pourra fabriquer ces armes. Vous trouverez son campement entre Zul'Gurub et le tertre des ogres Mosh'Ogg.\n\nPuissent votre détermination et votre foi vous porter dans cette épreuve. Si vous échouez, sachez que votre dieu vous regarde en souriant, <mortel/mortelle>.", progress = "Loramus, hein ? Il y a bien des années que je n'avais pas entendu ce nom.", completion = "Bon sang ! Je ne peux qu'imaginer ce que vous avez dû subir pour obtenir cela. Peu nombreux sont ceux qui vont à Azshara et reviennent en vie ; sans parler des affrontements avec ces demi-dieux et ces géants !", rewards = "Vous recevrez :\n\n"},
[3623] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[3624] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[3625] = {title = "Armes Fel en Azsharite enchantée", objective = "Attendre que Galvan ait fini de forger les armes.", description = "<nom>, la création de chaque arme va prendre un peu de temps.\n\nDe plus, vous ne pourrez utiliser le pouvoir du sort Corruption qu'une fois toutes les trois minutes. Ses propriétés d'affaiblissement contre Razelikh le Souilleur et ses sbires peuvent varier dans la durée. C'est pourquoi vous devez utiliser le sort Corruption seulement au moment judicieux !\n\nDonnez-moi une minute pour terminer votre arme, <nom>.", progress = "Interrompre le processus de fabrication pourrait aboutir à une arme imparfaite. Patience, <nom>.", completion = "&lt;Galvan essuie la sueur de son front.&gt;\n\nIl n'y a jamais eu de meilleur tueur de démons, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague Felbane en azsharite enchantéBâton Felbane en azsharite enchantéEpée Felbane en azsharite enchanté\n\nVous recevrez également :\n\n"},
[3626] = {title = "Retour aux Terres foudroyées", objective = "Retourner voir le Héros déchu de la Horde.", description = "L'heure de la rédemption est proche, <nom>. Vous devez retourner aux Terres foudroyées avec votre nouvel équipement et parler au Héros déchu de la Horde pour recevoir votre objectif final.", progress = nil, completion = "Vous semblez vous battre durement, &lt;nom&gt;. Êtes-vous préparé à faire face à Razelikh et à ses sbires ?", rewards = "Vous recevrez :\n\n"},
[3627] = {title = "Réunir les morceaux de l'Amulette brisée.", objective = "Assassiner Grol le Destructeur, dame Sevine et l'archimage Allistarj. Prendre sur leurs cadavres l'Amulette de Grol, l'Amulette de Sevine et l'Amulette d'Allistarj.\n\nUTILISER les armes Fel en Azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais les utiliser sagement...", description = "Pour atteindre le Souilleur, vous devez d'abord détruire la triade de pouvoir et récupérer les morceaux d'amulette. Quand vous aurez récupéré les trois morceaux, revenez me voir et je vous donnerai de nouvelles instructions.\n\nAllez, <nom> ! Aux Terres foudroyées ! Sevine, Allistarj et Grol doivent mourir !", progress = "Les trois ne formeront plus qu'une, qui éclairera la voie.", completion = "L'amulette de Razelikh le Souilleur est de nouveau entière, mais il a senti la rupture dans sa chaîne de commandement. Il sait que vous venez pour lui...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3628] = {title = "Vous êtes Rakh'likh, démon", objective = "Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros déchu de la Horde. Rendre aussi l'Amulette du Souilleur au Héros Déchu pour qu'il puisse la détruire, afin de l'empêcher de tomber dans de mauvaises mains.", description = "Razelikh se terre sur la plus haute montagne des Terres foudroyées. Le seul moyen d'y accéder est d'utiliser les Runes de téléportation près de la montagne. Tant que vous tenez l'amulette, vous pouvez vous y transporter. Une fois là-bas, vous devez neutraliser la bête. L'amulette est votre atout, <nom>. Utilisez-la sur l'Autel du Souilleur.\n\nSi vous arrivez à le vaincre, prenez sa corne. Elle sera signe d'espoir pour ceux qui la verront, la preuve que les héros existent dans ce monde déchiré par la guerre.", progress = "Il n'y a plus rien à craindre.", completion = "Le jour d'aujourd'hui sera fêté jusqu'à la fin des temps. Le démoniaque chef suprême des Terres foudroyées est enfin tombé !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCollier de sanctuaireSang de démonSac en peau de démon"},
[3629] = {title = "Ingénierie des gobelins", objective = "Pour en apprendre davantage sur l'Ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring dans Gadgetzan.", description = "L'ingénierie pratiquée au niveau d'expert connaît deux disciplines : celle des gnomes et celle des gobelins. Je ne mentionne l'Ingénierie des gobelins que parce que je suis un Maître juste. Ils aiment faire des choses qui explosent et se soucient rarement des conséquences.\n\n<nom>, lisez ce manuel. Si vous voulez apprendre comment vous faire sauter, apportez-le à Nixx Sprocketspring dans Gadgetzan. Mais le choix de cette discipline est définitif et exclut l'autre, alors soyez <sûr/sûre> de votre choix !", progress = "Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l'art de l'explosion ?", completion = "Bien &lt;nom&gt;, vous avez été avisée de choisir mon enseignement ! N'importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d'Ingénierie des gobelins.\n\nOuvrez vos oreilles, &lt;nom&gt;, et vous pourrez apprendre beaucoup.", rewards = "Vous recevrez :\n\n"},
[3630] = {title = "Ingénierie des gnomes", objective = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Ironforge.", description = "L'ingénierie pratiquée à un niveau d'expert connaît deux disciplines : celle des gnomes et celle des gobelins. L'Ingénierie gnome est de loin supérieure ! Elle consiste à construire de merveilleux dispositifs qui rendent la vie meilleure !\n\n<nom>, lisez ce manuel. Si vous voulez en apprendre plus sur l'Ingénierie gnome, apportez ce manuel au maître-artisan Overspark dans Ironforge. Mais le choix de cette discipline est définitif et exclut l'autre, alors soyez <sûr/sûre> de votre choix !", progress = "Oui, oui, que puis-je faire pour vous aujourd'hui ? J'ai vraiment du temps libre maintenant que ma seule activité est de regarder notre ville bien-aimée se noyer dans un nuage de mort.", completion = "Oh, un jeune ingénieur qui veut poursuivre l'étude de la seule, la vraie discipline d'ingénierie ! Pardonnez ce ton mélodramatique, mon amie. Alors que notre situation devient de plus en plus difficile, c'est toujours une joie de voir qu'un autre ingénieur répond à l'appel de clairon de la véritable ingénierie !", rewards = "Vous recevrez :\n\n"},
[3631] = {title = "Invoquer un Palefroi corrompu", objective = "Parler à Strahad Farsan, dans les Tarides.", description = "Hum. À mon avis, vous n’avez ni la force ni les compétences requises, mais cela ne me regarde pas puisque Strahad pense autrement, et que c’est lui qui décide... cette fois.\n\nIl voudrait vous parler le plus vite possible. Vous le trouverez, avec ses acolytes, dans la petite tour qui domine Ratchet, dans les Tarides.\n\nNe traînez pas.", progress = nil, completion = "Encore une fois, vous m'honorez de votre présence. Comme c'est aimable de votre part.\n\nMes acolytes m'avaient dit que vous ne viendriez jamais. Je leur ai répondu que je n'en doutais pas. Lorsqu'il s'agit de puissance, vous ressemblez à un papillon attiré par les flammes.", rewards = "Vous recevrez :\n\n"},
[3632] = {title = "Ingénierie des gnomes", objective = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Ironforge.", description = "L'ingénierie pratiquée à un niveau d'expert connaît deux disciplines : celle des gnomes et celle des gobelins. L'Ingénierie gnome est de loin supérieure ! Elle consiste à construire de merveilleux dispositifs qui rendent la vie meilleure !\n\n<nom>, lisez ce manuel. Si vous voulez en apprendre plus sur l'Ingénierie gnome, apportez ce manuel au maître-artisan Overspark dans Ironforge. Mais le choix de cette discipline est définitif et exclut l'autre, alors soyez <sûr/sûre> de votre choix !", progress = "Oui, oui, que puis-je faire pour vous aujourd'hui ? J'ai vraiment du temps libre maintenant que ma seule activité est de regarder notre ville bien-aimée se noyer dans un nuage de mort.", completion = "Oh, un jeune ingénieur qui veut poursuivre l'étude de la seule, la vraie discipline d'ingénierie ! Pardonnez ce ton mélodramatique, mon ami. Alors que notre situation devient de plus en plus difficile, c'est toujours une joie de voir qu'un autre ingénieur répond à l'appel de clairon de la véritable ingénierie !", rewards = "Vous recevrez :\n\n"},
[3633] = {title = "Ingénierie des gobelins", objective = "Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring, à Gadgetzan.", description = "La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. L'Ingénierie des gobelins est clairement le choix de tous les ingénieurs brillants. Apprendre à vaincre le monde par l'utilisation judicieuse d'explosifs et d'incroyables mécanismes !\n\n<nom>, lisez ce manuel. Si vous voulez en apprendre plus, apportez-le à Nixx Sprocketspring à Gadgetzan. Mais attention : l’adhésion à cette discipline est définitive et exclusive, alors soyez <sûr/sûre> de faire le bon choix !", progress = "Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l'art de l'explosion ?", completion = "Bien &lt;nom&gt;, vous avez été avisé de choisir mon enseignement ! N'importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d'Ingénierie des gobelins.\n\nOuvrez vos oreilles, &lt;nom&gt;, et vous pourrez apprendre beaucoup.", rewards = "Vous recevrez :\n\n"},
[3634] = {title = "Ingénierie des gnomes", objective = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Ironforge.", description = "L'ingénierie au niveau d'expert connaît deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez vous spécialiser dans celle des gnomes. Ils fabriquent des objets et des gadgets pour soit-disant changer le monde, mais ça fonctionne rarement.\n\n<nom>, lisez ce manuel. Si ça vous intéresse, apportez-le au maître-artisan Overspark dans Ironforge. Mais le choix de cette discipline est définitif et exclut l'autre, alors soyez <sûr/sûre> de votre choix !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[3635] = {title = "Ingénierie des gnomes", objective = "Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin.", description = "L'ingénierie au niveau d'expert enseigne deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez connaître celle des gnomes. Ils fabriquent des objets et des gadgets pour prétendument changer le monde, mais ils fonctionnent rarement.\n\n<nom>, lisez ce manuel. Si ça vous intéresse, apportez-le à Oglethorpe Obnoticus à Baie-du-Butin. Mais attention : l’adhésion à cette discipline est définitive et exclusive, alors soyez <sûr/sûre> de faire le bon choix !", progress = "Salut à vous ! Si c'est parce que l'un de nos robots guidés a démoli un mur de votre domicile que vous venez, je vous envoie tout de suite mon avocat. Sinon, que puis-je faire pour vous ?", completion = "Vous venez pour apprendre l'ingénierie gnome, alors ? Bien, vous vous adressez au bon gnome. Même si la faction dirigeante de Gnomeregan utilise la politique pour frapper d'ostracisme ceux qu'ils perçoivent comme une menace intellectuelle, ils savent qu'ils ne peuvent pas contrôler la connaissance.\n\nIls savent comme moi que si je quitte Gnomeregan, ils perdront un de leurs plus grands ingénieurs gnomes vivants aujourd'hui. Si vous vous montrez capable, je vous apprendrai ce que je sais.", rewards = "Vous recevrez :\n\n"},
[3636] = {title = "Apportez la Lumière", objective = "Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus.", description = "Le Fléau est une menace persistante pour l'Alliance, vous le savez fort bien. Récemment, nous avons découvert quelque chose, <nom>.\n\nDans les Tarides, il y a un amas de ronces, les Souilles de Tranchebauge. C'était autrefois la demeure de hurans normaux, mais maintenant un pacte y a été fait avec le Fléau, pour créer des créatures beaucoup plus mauvaises... Elles sont gouvernés par la liche Amnennar, dite le Porte-froid.\n\nSoyez le porte-parole de la Lumière, <nom> ; mettez fin à cette mauvaise union.", progress = nil, completion = "Merci, &lt;nom&gt;. Le Fléau réfléchira maintenant à deux fois avant d'essayer à nouveau de faire croître ses rangs.\n\nQue la Lumière vous bénisse.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEpée du triompheTalisman de luisambre"},
[3637] = {title = "Ingénierie des gnomes", objective = "Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin.", description = "L'ingénierie au niveau d'expert enseigne deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez connaître celle des gnomes. Ils fabriquent des objets et des gadgets pour prétendument changer le monde, mais ils fonctionnent rarement.\n\n<nom>, lisez ce manuel. Si ça vous intéresse, apportez-le à Oglethorpe Obnoticus à Baie-du-Butin. Mais attention : l’adhésion à cette discipline est définitive et exclusive, alors soyez <sûr/sûre> de faire le bon choix !", progress = "Salut à vous ! Si c'est parce que l'un de nos robots guidés a démoli un mur de votre domicile que vous venez, je vous envoie tout de suite mon avocat. Sinon, que puis-je faire pour vous ?", completion = "Vous venez pour apprendre l'ingénierie gnome, alors ? Bien, vous vous adressez au bon gnome. Même si la faction dirigeante de Gnomeregan utilise la politique pour frapper d'ostracisme ceux qu'ils perçoivent comme une menace intellectuelle, ils savent qu'ils ne peuvent pas contrôler la connaissance.\n\nIls savent comme moi que si je quitte Gnomeregan, ils perdront un de leurs plus grands ingénieurs gnomes vivants aujourd'hui. Si vous vous montrez capable, je vous apprendrai ce que je sais.", rewards = "Vous recevrez :\n\n"},
[3638] = {title = "Le Vœu du secret", objective = "Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Sprocketspring dans Gadgetzan.", description = "L'ingénierie des gobelins traite de l'utilisation pratique des explosifs ! Nos schémas nous permettent de faire des bombes et des armes puissantes ; c’est le thème du manuel que vous lisez.\n\nDepuis toujours, ce manuel est lié par un Vœu du secret couvrant tous nos schémas. Une fois que vous serez Ingénieur gobelin, vous ne pourrez plus accéder à l'Ingénierie des gnomes. Si vous voulez toujours devenir Ingénieur gobelin, signez ce document vous engageant au secret et revenez me voir. Réfléchissez soigneusement, <nom>.", progress = "Si vous avez signé le document et que vous êtes d'attaque, il n'y a rien à faire de plus. C'est un chemin que l'on ne peut faire que dans un seul sens. Si vous êtes prêt, sautez donc à bord !", completion = "Bienvenue à bord, Ingénieur gobelin &lt;nom&gt; ! Vous aurez bientôt l'accès aux schémas de l'Ingénierie la plus puissante d'Azeroth.\n\nMaintenant que vous avez décidé de poursuivre cet apprentissage, il est temps d'examiner votre travail d'Ingénieur gobelin. Ensuite, nous vous aiderons à construire un plan pour maximiser vos talents d'Ingénieur gobelin !", rewards = "Vous recevrez :\n\n"},
[3639] = {title = "Montrez votre travail", objective = "Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Sprocketspring dans Gadgetzan.", description = "En tant que mentor, je veux quelques échantillons de votre travail. Vous êtes un ingénieur habile ; la question n'est pas là, <nom>. Je veux analyser votre travail pour orienter vos efforts futurs. J'ai besoin des échantillons suivants : 20 grandes bombes en fer, 20 bâtons de dynamite solide et 5 moutons explosifs.\n\nSoumettez-moi vos réalisations et je vous ferai votre Carte de membre des Ingénieurs gobelins ; elle est exigée pour accéder à toutes les techniques des maîtres des ingénieurs gobelins !", progress = "Une fois que j'aurai reçu ce que vous devez fabriquer pour ma revue, je vous remettrai une véritable Carte de membre des Ingénieurs gobelins ! Tant que la carte sera valable, vous aurez un accès illimité à n'importe laquelle des formations de Maître Ingénieur gobelin partout dans le monde.", completion = "Voici votre première Carte de membre des ingénieurs gobelins !\n\nLa cotisation est payable d’avance, pour quatorze jours. Toutes les cartes expirent après deux semaines d'activité. Lorsqu'elle expire, donnez le montant des cotisations versées à n'importe quel Maître des Ingénieurs gobelin afin d'obtenir une nouvelle carte. Sans carte, votre adhésion sera temporairement caduque et vous ne pourrez pas accéder à de nouveaux schémas.\n\nCependant, cela n'affecte en rien les connaissances déjà acquises. Lorsqu'on est Ingénieur gobelin, c'est pour la vie.", rewards = "Vous allez être la cible du sort suivant :\n\nIngénierie gobeline\n\nVous recevrez :\n\nCarte de membre des ingénieurs gobelins"},
[3640] = {title = "Le Vœu du secret", objective = "Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Overspark, à Ironforge.", description = "L'ingénierie des gnomes consiste à mettre en forme la théorie de l'ingénierie pour servir nos besoins ! Nos schémas nous permettent de construire des appareils contrôlant le monde qui nous entoure. Le manuel que vous avez lu traite de ce sujet.\n\nIl traite également du Vœu du secret qui recouvre nos schémas. Lorsque vous adhérez à l'Ingénierie des gnomes, vous ne pouvez plus revenir en arrière. Vous ne pourrez jamais plus accéder à l'Ingénierie des gobelins.\n\nSi vous souhaitez toujours devenir Ingénieur gnome, signez ce document qui vous engage à garder le secret à vie et revenez me parler. Prenez votre décision après mûre réflexion, <nom>.", progress = "Si vous avez signé le document et que vous êtes prêt à me le remettre, alors nous y sommes.\n\nLes secrets que je partagerai avec vous sont d'une telle importance que signer le Vœu du secret est capital. J'en ai signé un, comme l'ont fait mon frère et ma sœur, tous deux Ingénieurs gnomes. Vous rejoignez une bien belle famille, Ingénieur <nom> !", completion = "Bienvenue à bord, &lt;nom&gt; ! Vous aurez bientôt accès aux schémas de l'ingénierie la plus avancée de tout Azeroth.\n\nPuisque vous avez décidé de poursuivre dans cette voie, il est temps d'examiner votre technique de travail d'ingénierie &lt;race&gt;. Ensuite, nous vous aiderons à maximiser vos talents !", rewards = "Vous recevrez :\n\n"},
[3641] = {title = "Montrez votre travail", objective = "Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Overspark à Ironforge.", description = "En tant que votre mentor, je veux avoir des exemplaires de votre travail. Vous êtes <compétent/compétente> en tant qu'Ingénieur, je ne le remets pas en question, <nom>. Cependant, je souhaite analyser votre travail pour savoir comment introduire les techniques gnomes dans vos travaux futurs. J'ai besoin des objets suivants : six tubes de mithril, une lunette de précision et deux leurres perfectionnés.\n\nSoumettez-moi ces objets et je vous remettrai votre propre Carte de membre des ingénieurs gnomes. Elle vous sera demandée pour aborder tous les Entraîneurs des Ingénieurs gnomes !", progress = "Une fois que j'aurai reçu ce que vous devez fabriquer pour ma revue, je vous remettrai une véritable Carte de membre des Ingénieurs gnomes ! Tant que la carte sera valable, vous aurez un accès illimité à n'importe laquelle des formations des Entraîneurs des Ingénieurs gnomes partout dans le monde.", completion = "Voici votre première Carte de membre des ingénieurs gnomes !\n\nLa cotisation est payable d’avance, pour quatorze jours. Toutes les cartes expirent après deux semaines d'activité. Lorsqu'elle expire, donnez le montant des cotisations versées à n'importe quel Maître des Ingénieurs gnome afin d'obtenir une nouvelle carte. Sans carte, votre adhésion sera temporairement caduque et vous ne pourrez pas accéder à de nouveaux schémas.\n\nCependant, cela n'affecte en rien les connaissances déjà acquises. Lorsqu'on est Ingénieur gnome, c'est pour la vie.", rewards = "Vous allez être la cible du sort suivant :\n\nIngénierie gnome\n\nVous recevrez :\n\nCarte de membre des ingénieurs gnomes"},
[3642] = {title = "Le Vœu du secret", objective = "Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Obnoticus à Baie-du-Butin.", description = "L'ingénierie des gnomes consiste à mettre en forme la théorie de l'ingénierie pour servir nos besoins ! Nos schémas nous permettent de construire des appareils contrôlant le monde qui nous entoure. Le manuel que vous avez lu traite de ce sujet.\n\nIl traite également du Vœu du secret qui recouvre nos schémas. Lorsque vous adhérez à l'Ingénierie des gnomes, vous ne pouvez plus revenir en arrière. Vous ne pourrez jamais plus accéder à l'ingénierie des gobelins.\n\nSi vous souhaitez toujours devenir Ingénieur gnome, signez ce document qui vous engage à garder le secret à vie et revenez me parler. Prenez votre décision après mûre réflexion, <nom>.", progress = "Si vous avez signé le document et que vous êtes disponible, c'est le moment.\n\nMême si je suis violemment en désaccord à propos de Gnomeregan, particulièrement avec ce fou de maître-artisan Overspark, le Voeu de secret dépasse tout le reste ! Vous devez consentir à emprunter un chemin que l'on ne peut suivre que dans un seul sens et rester sur ce chemin toute votre vie.", completion = "Bienvenue à bord, &lt;nom&gt; ! Vous aurez bientôt accès aux schémas de l'ingénierie la plus avancée de tout Azeroth.\n\nPuisque vous avez décidé de poursuivre dans cette voie, il est temps d'examiner votre technique de travail d'Ingénierie Gnome. Ensuite, nous vous aiderons à maximiser vos talents !", rewards = "Vous recevrez :\n\n"},
[3643] = {title = "Montrez votre travail", objective = "Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Cibles avancées à Oglethorpe Obnoticus à Baie-du-Butin.", description = "En tant que votre mentor, je veux avoir des exemplaires de votre travail. Vous êtes <compétent/compétente> en tant qu'ingénieur, je ne le remets pas en question, <nom>. Cependant, je souhaite analyser votre travail pour savoir comment introduire les techniques gnomes dans vos travaux futurs. J'ai besoin des objets suivants : six tubes de mithril, une lunette de précision et deux cibles avancées.\n\nSoumettez-moi ces objets et je vous remettrai votre propre Carte de membre des ingénieurs gnomes. Elle vous sera demandée pour aborder tous les entraîneurs des ingénieurs gnomes !", progress = "Une fois que j'aurai reçu ce que vous devez fabriquer pour ma revue, je vous remettrai une véritable Carte de membre des Ingénieurs gnomes ! Tant que la carte sera valable, vous aurez un accès illimité à n'importe laquelle des formations des Entraîneurs des Ingénieurs gnomes partout dans le monde.", completion = "Voici votre première Carte de membre des ingénieurs gnomes !\n\nLa cotisation est payable d’avance, pour quatorze jours. Toutes les cartes expirent après deux semaines d'activité. Lorsqu'elle expire, donnez le montant des cotisations versées à n'importe quel Maître des Ingénieurs gnome afin d'obtenir une nouvelle carte. Sans carte, votre adhésion sera temporairement caduque et vous ne pourrez pas accéder à de nouveaux schémas.\n\nCependant, cela n'affecte en rien les connaissances déjà acquises. Lorsqu'on est Ingénieur gnome, c'est pour la vie.", rewards = "Vous allez être la cible du sort suivant :\n\nIngénierie gnome\n\nVous recevrez :\n\nCarte de membre des ingénieurs gnomes"},
[3644] = {title = "Le renouvellement de la Carte de membre", objective = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", description = nil, progress = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", completion = "Puisque vous pratiquez l'Ingénierie des gobelins depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d'or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d'obtenir des schémas d'Ingénierie des gobelins chez les Entraîneurs concernés.\n\nLe délai de validité de cette carte sera de deux semaines d'activité, à l'issue desquelles les frais d'adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.", rewards = "Vous recevrez :\n\nCarte de membre des ingénieurs gobelins"},
[3645] = {title = "Le renouvellement de la Carte de membre", objective = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", description = nil, progress = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", completion = "Puisque vous pratiquez l'Ingénierie des gnomes depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d'or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d'obtenir des schémas d'Ingénierie des gnomes chez les Entraîneurs concernés.\n\nLa validité de cette carte est de deux semaines, à l'issue desquelles vos frais d'adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.", rewards = "Vous recevrez :\n\nCarte de membre des ingénieurs gnomes"},
[3646] = {title = "Le renouvellement de la Carte de membre", objective = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", description = "[\n]", progress = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", completion = "Puisque vous pratiquez l'Ingénierie des gobelins depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d'or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d'obtenir des schémas d'Ingénierie des gobelins chez les Entraîneurs concernés.\n\nLe délai de validité de cette carte sera de deux semaines d'activité, à l'issue desquelles les frais d'adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.", rewards = "Vous recevrez :\n\nCarte de membre des ingénieurs gobelins"},
[3647] = {title = "Le renouvellement de la Carte de membre", objective = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", description = nil, progress = "Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or.", completion = "Puisque vous pratiquez l'Ingénierie des gnomes depuis un certain temps, je peux renouveler votre Carte de membre expirée contre un paiement de deux pièces d'or. Une fois ces frais de renouvellement acquittés, on vous remettra une nouvelle Carte de membre. Cela vous permettra d'obtenir des schémas d'Ingénierie des gnomes chez les Entraîneurs concernés.\n\nLa validité de cette carte est de deux semaines, à l'issue desquelles vos frais d'adhésion devront à nouveau être payés. Si vous voulez accéder aux schémas, vous devrez apporter cette somme, mais pas les arriérés.", rewards = "Vous recevrez :\n\nCarte de membre des ingénieurs gnomes"},
[3661] = {title = "Dans les faveurs d'Elune ?", objective = "Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambersky au village de Rut'theran.", description = "Les Indomptables sont des créatures tout à fait imprévisibles, <nom>. Capables d'une douceur incroyable, elles sont féroces si on menace ce qui est important à leurs yeux.\n\nOn dit que ces bêtes auraient été créées par Elune, et j’aimerais savoir si c’est vraiment le cas.\n\nJ’ai récemment entendu parler d’une population d’Indomptables vivant dans les Hinterlands ; des Chouettards vicieux, des Chouettards primitifs et des Chouettards sauvages. Ils hantent les terres sauvages, là-bas. Pourriez-vous aller collecter quelques-unes de leurs plumes pour moi ?", progress = "Essayez de les éviter si vous pouvez, <nom>. Les Indomptables peuvent interpéter votre intérêt comme une intention de leur faire du mal...", completion = "Merci d'avoir apporté ceci, &lt;nom&gt;.\n\nQu'avez-vous appris des Indomptables ?\n\nPeut-être ces plumes nous en apprendront-elles plus. Des monstres féroces ou des familiers égarés ? Un jour je souhaiterai connaître la vérité...\n\nJe vais poursuivre mes recherches ; revenez me voir dans un moment.", rewards = "Vous recevrez :\n\n"},
[3681] = {title = "Le Tome de divinité", objective = "Parler à Duthorian Rall à Stormwind.", description = "Il me navre d'interrompre vos voyages, <nom>, mais je pense que vous serez <intéressé/intéressée> d'apprendre que Stormwind a récemment envoyé un message disant que tous les paladins devaient s'y rendre pour y être entraînés.\n\nSi je n'en savais pas plus, je dirais que vous êtes sur le point d'atteindre un certain stade et qu'il est temps pour vous de commencer l'étude des Tomes.\n\nCherchez Duthorian Rall à Stormwind. D'habitude, il enseigne aux paladins dans la cathédrale de la Lumière.", progress = nil, completion = "Bienvenue dans la cathédrale de la Lumière, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[3701] = {title = "Les ruines fumantes de Thaurissan", objective = "Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus.", description = "Rendez-vous dans les ruines fumantes de Thaurissan, dans les Steppes ardentes, et réunissez autant de renseignements que possible.\n\nOn raconte que de mystérieuses reliques jonchent les ruines. Peut-être devriez-vous commencer vos recherches par elles, <nom>. Attention aux gardiens de Thaurissan. Ces assassins veillent à ce que les secrets qui y sont enfouis ne s'échappent pas.", progress = nil, completion = "Oh ! Ces renseignements expliquent beaucoup de choses à propos de Thaurissan.\n\nIl y a beaucoup plus à apprendre !", rewards = "Vous recevrez :\n\nAnneau aristocratique"},
[3702] = {title = "Les ruines fumantes de Thaurissan", objective = "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan.", description = "Est-ce que vous aimeriez entendre une petite histoire sur les nains Sombrefer ?", progress = "Permettez-moi de finir l'histoire de Thaurissan.", completion = "Commençons-nous ?", rewards = "Vous recevrez :\n\n"},
[3721] = {title = "Un OOX rien que pour vous", objective = "Vous avez récupéré trois de mes robots guidés OOX ! Vous avez fait bien plus que le nécessaire, aussi vais-je vous donner quelque chose de spécial pour vous remercier. C'est une version miniature du robot qu'à présent vous devez connaître et aimer : l'OOX !\n\nNormalement, je ne laisserais à personne un appareil aux capacités si dangereuses, mais vous m'avez été d'un réel secours. De plus, les mécanismes de combat et le système de guidage ont été mis hors service.\n\nMais il n'en reste pas moins qu'il s'agit bien là d'un OOX, bon sang !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPoulet mécanique"},
[3741] = {title = "Le collier d'Hilary", objective = "Trouver le Collier d'Hilary et le rapporter à Hilary au Lakeshire.", description = "Mon amie Hilary a perdu son collier, et nous ne parvenons pas à le retrouver. Nous avons pêché toute la journée ici, et nous avons déjà cherché aux alentours. Je crois qu'il est tombé dans le lac. Nos parents ne veulent pas que nous y nagions... Ma maman dit qu'il y a des choses méchantes sous l'eau. Mais vous n'avez pas l'air d'avoir peur des choses méchantes.\n\nVous pouvez retrouver son collier, s'il vous plaît ?", progress = "Salut. J'ai perdu mon collier. C'est papa qui me l'a donné. Papa dit qu'il y a des monstres dans le lac. Vous avez déjà tabassé des monstres ?", completion = "Merci d'avoir retrouvé mon collier, m'sieur &lt;classe&gt;… C'est très gentil ! Mon chaton aussi vous remercie. Pas vrai, Effsee ?", rewards = "Vous recevrez :\n\n"},
[3761] = {title = "La terre d'Un'Goro", objective = "Apporter 20 Echantillons d'Humus d'Un'Goro à Ghede, à Thunder Bluff.", description = "Il paraît que la terre du Cratère d'Un'Goro est naturellement riche en propriétés magiques puissantes. Le Cercle cénarien souhaite étudier cette terre. Rendez-vous au Cratère d'Un'Goro et prélevez suffisamment de terre pour que nous puissions travailler un bon moment.\n\nCette terre riche s’agglomère parfois, et certaines bêtes peuvent en porter sur elles des fragments utilisables. Apportez-les tous à Ghede. Cherchez simplement des monticules de terre et des taurens en train de beugler des ordres et vous le trouverez. C'est un bon gars, mais ne l'énervez pas.", progress = "Repos, soldat. Si vous êtes là pour décharger de la terre d'Un'Goro, alors c'est parfait ! Sinon, disparaissez.", completion = "Mais bien sûr, soldat &lt;nom&gt;, ne m'aidez surtout pas à décharger cette terre sur les monticules ! Si les Grands Esprits avaient voulu qu'un tel résultat soit atteint, ils auraient accompli un miracle pour que ça se fasse tout seul, suis-je bête !\n\nL'archidruide Runetotem veut vous rencontrer à nouveau, mais pour la nouvelle tâche qu'il va vous confier, une connaissance conséquente en herboristerie serait la bienvenue. Si vous n'en avez pas, allez tout de même le voir, il vous trouvera une utilité quelconque.", rewards = "Vous recevrez :\n\n"},
[3762] = {title = "L'aide à l'archidruide Runetotem", objective = "Parler à l'archidruide Hamuul Runetotem à Thunder Bluff.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps, si cela est possible.\n\nLe Cercle cénarien de Thunder Bluff est très intéressé par des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans un projet crucial. Bien que je n’en connaisse pas les détails, je peux vous dire que Hamuul Runetotem lui-même mène ce projet.\n\nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la Cime des Anciens dans Thunder Bluff.", progress = nil, completion = "Salutations, &lt;classe&gt;. Je suis heureux de voir que vous êtes intéressé pour nous prêter main-forte. Il y a beaucoup à faire, et ce ne serait pas vous rendre service que de vous dire que ce travail ne comporte aucun danger. J'espère que cela ne va pas vous effrayer... Mais en vous regardant, il me semble comprendre que vous avez déjà eu à faire au danger.", rewards = "Vous recevrez :\n\n"},
[3763] = {title = "L'aide à l'archidruide Staghelm", objective = "Parler à l'archidruide Fandral Staghelm à Darnassus.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps si la chose est possible.\n\nLe Cercle cénarien à Darnassus recherche des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l'archidruide Fandral Staghelm en personne mène ces recherches.\n\nSi cela vous intéresse, allez directement lui parler à l'Enclave cénarienne à Darnassus.", progress = nil, completion = "Bien, &lt;classe&gt;… Puisque vous avez été informé que je dirigeais en personne ces recherches, vous êtes évidemment venu aussi vite que possible.\n\nMaintenant que vous êtes là, écoutez attentivement. J'ai horreur de me répéter.", rewards = "Vous recevrez :\n\n"},
[3764] = {title = "La terre d'Un'Goro", objective = "Apporter 20 Echantillons d'Humus d'Un'Goro à Jenal, à Darnassus.", description = "On raconte que l'humus du Cratère d'Un'Goro est enrichi de propriétés magiques puissantes. Je veux séparer le vrai de la rumeur ; partez pour les terres sauvages du Cratère d'Un'Goro et récupérez suffisamment d'échantillons de qualité de son sol afin que nous puissions l'étudier sans discontinuer.\n\nVous pourriez considérer que cette simple tâche de récupération est indigne de vous, mais ce genre de considération ne vous ferait apprécier ni de moi ni du Cercle cénarien. Apportez les échantillons à Jenal, qui doit sans aucun doute perdre son temps dehors derrière cet arbre. Cherchez simplement le tas de terre. C'est lui qui s'occupera de la logistique, pas moi.", progress = "Ah oui, la terre ! L'archidruide en veut vingt prélèvements par aventurier, et il en aura vingt. Que ceux qui conspirent contre nous tombent le long de la route !", completion = "Déchargez ici votre précieuse cargaison, noble &lt;classe&gt;. Cela a dû être un fardeau très lourd… Tout comme celui que je porte en tant que visionnaire. Voici vos honoraires pour votre travail, comme le demande l'archidruide en personne.\n\nL'archidruide Staghelm veut vous parler à nouveau, &lt;nom&gt;. Mais pour la nouvelle tâche qu'il veut vous confier, il serait bon d’avoir une bonne connaissance en herboristerie. Si tel n'est pas le cas, allez tout de même le voir. Vous pourrez toujours aider le Cercle !", rewards = "Vous recevrez :\n\n"},
[3765] = {title = "La dépravation au loin", objective = "Aller voir Gershala Nightwhisper à Auberdine.", description = "Stormwind. Tellement bouillonnant d'activité !\n\nJe viens de loin pour chercher de l'aide. On dit que de courageux aventuriers foulent les rues de cette cité.\n\nMon frère, Gershala, a besoin d'aide a Sombrivage. Il demeure dans la ville côtière d'Auberdine.\n\nLe voyage est long et périlleux. C'est pourquoi je demande l'aide de <classe>s expérimentés.", progress = nil, completion = "Ainsi mon frère Argos vous envoie ? Il se peut que vous soyez fatigué de votre voyage. Mais il y a beaucoup à discuter.", rewards = "Vous recevrez :\n\n"},
[3781] = {title = "La recherche sur la Fibre d'aurore", objective = "Apporter le Bon pour des graines de l'archidruide à Mathrengyl Bearwalker dans l'enclave cénarienne à Darnassus.", description = "Nous avons planté des graines de Tharlendris dans de la terre du Cratère d'Un'Goro, avec ce que nous appelons une Sacoche de printemps. Ces graines ont germé et donné un grand nombre d'herbes fortes et variées. Parmi elles, il y a de la Fibre d'aurore, une herbe dont on sait peu de chose. J'ai l’intention de percer ses mystères.\n\nApportez ceci à Mathrengyl, en bas, et il vous remettra quelques graines afin que vous puissiez commencer. Si vous veniez à en manquer, vous devrez lui en acheter.", progress = "Que la paix et la sérénité soient avec vous, mon ami ! Vous venez de la part de l'archidruide, n'est-ce pas ?", completion = "Oui, ce bon vous donne droit à vingt paquets de graines. Si vous veniez à en manquer, nous pourrions vous en procurer davantage. Malheureusement, la production de graines de Tharlendris est coûteuse. C'est pourquoi le Cercle cénarien demande à ceux qui nous aident de supporter une partie de ce coût. Ceux qui reviennent avec de la Fibre d'aurore considèrent que la récompense offerte par l'archidruide constitue un bon dédommagement.", rewards = "Vous recevrez :\n\nPochette de graines de Tharlendis"},
[3782] = {title = "La recherche sur la Fibre d'aurore", objective = "Apporter le Bon pour des graines à Bashana Runetotem à Thunder Bluff.", description = "Nous avons planté des graines de Tharlendris dans de la terre du Cratère d'Un'Goro, avec ce que nous appelons une Sacoche de printemps. Ces graines ont germé et donné un grand nombre d'herbes fortes et variées. Parmi elles, il y a de la Fibre d'aurore, une herbe dont on sait peu de chose. J'espère pouvoir percer ses mystères, pour le Cercle.\n\nApportez ce bon à ma soeur Bashana et elle vous remettra quelques graines afin que vous puissiez nous aider. Si vous veniez à en manquer, vous devrez lui en acheter.", progress = "Que la paix soit avec vous, mon ami ! Vous venez de la part de l'archidruide, n'est-ce pas ?", completion = "Oui, ce bon donne droit à vingt paquets de graines. Si vous veniez à en manquer, je pourrais vous vendre celles de ma réserve.\n\nMalheureusement, &lt;nom&gt;, il est coûteux de produire des graines de Tharlendris en quantité. C'est pourquoi le Cercle cénarien demande à ceux qui nous aident de supporter une partie de ce coût. Ceux qui reviennent avec de la Fibre d'aurore considèrent que la récompense offerte par l'archidruide constitue un bon dédommagement.", rewards = "Vous recevrez :\n\nPochette de graines de Tharlendis"},
[3783] = {title = "Yéti ? Y es-tu ?", objective = "Collecter 10 Fourrures épaisses de yéti pour Umi Rumplesnicker, à Long-guet.", description = "Mes amis ne cessent d'avoir de grandes idées. Et je n'aurais jamais cru être capable de les concurrencer… jusqu'à ce jour ! Je viens juste de dessiner les plans de quelque chose de vraiment merveilleux ! Si vous me promettez de ne pas le répéter, je vais vous dire mon secret...\n\nJe vais construire un yéti mécanique ! Non seulement mes amis ne vont pas le croire quand ils le verront, mais une fois qu'ils se seront remis de leur surprise, je sais qu'ils seront vraiment impressionnés !\n\nPour commencer, j'aurais besoin de plusieurs fourrures épaisses de yétis, prélevées sur des yétis Chardon de glace. Voudriez-vous m'aider ? Vous en trouverez au sud-est.", progress = "J'ai beaucoup à faire ici. Apportez-moi ces fourrures rapidement, s'il vous plaît !", completion = "Ces fourrures sont parfaites, &lt;nom&gt;. Ça commence très bien !", rewards = "Vous recevrez :\n\n"},
[3784] = {title = "L'aide à l'archidruide Runetotem", objective = "Parler à l'archidruide Hamuul Runetotem à Thunder Bluff.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps, si cela est possible.\n\nLe Cercle cénarien de Thunder Bluff est très intéressé par des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans un projet crucial. Bien que je n’en connaisse pas les détails, je peux vous dire que Hamuul Runetotem lui-même mène ce projet.\n\nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la Cime des Anciens dans Thunder Bluff.", progress = nil, completion = "Salutations, &lt;classe&gt;. Je suis heureux de voir que vous souhaitez nous prêter main-forte. Il y a beaucoup à faire, et ce ne serait pas vous rendre service que de vous dire que ce travail ne comporte aucun danger. J'espère que cela ne va pas vous effrayer... Mais en vous regardant, il me semble comprendre que vous avez déjà eu à faire au danger.", rewards = "Vous recevrez :\n\n"},
[3785] = {title = "Recherches sur la Fibre d'aurore", objective = "Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.\n\nApporter 10 Fibres d'aurore à Mathrengyl Bearwalker à Darnassus.", description = "Voici la Sacoche de printemps dont vous aurez besoin pour utiliser les graines de Tharlendis. Vous devrez avoir également des échantillons d'Humus d'Un'Goro sous la main comme fertiliseur pour les graines. Servez-vous juste de la sacoche lorsque vous serez en possession de tout ce qui est nécessaire. Elle s'occupera du reste.\n\nLorsque vous aurez suffisamment de Fibres d'aurore, apportez-le-moi ici à l'Enclave. Veuillez ne pas déranger l'archidruide. C'est un homme très occupé, et il ne s'agit pas de le déranger à chaque fois que quelqu'un arrive avec un nouveau sac de Fibres d'aurore.", progress = "Oui, <nom> ? Avez-vous cultivé de la Fibre d'aurore pour les recherches capitales de l'archidruide ? Les travaux qu'il effectue pour le Cercle cénarien sont primordiaux, et votre participation ne sera pas oubliée !", completion = "Bon travail, &lt;nom&gt;. Je la remettrai à l'archidruide en personne lorsqu'il en aura besoin. En attendant, veuillez accepter ceci comme gage de gratitude du Cercle cénarien.\n\nNous avons toujours besoin de Fibres d'aurore. Si vous souhaitez continuer à nous en fournir, revenez lorsque vous aurez cultivé des Fibres d'aurore supplémentaires.", rewards = "Vous recevrez :\n\nCache du Cercle cénarien"},
[3786] = {title = "Recherches sur la Fibre d'aurore", objective = "Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.\n\nApporter 10 Fibres d'aurore à Bashana Runetotem à Thunder Bluff.", description = "Voici la Sacoche de printemps dont vous aurez besoin pour utiliser les graines de Tharlendis. Vous devrez avoir également des échantillons d'Humus d'Un'Goro sous la main comme fertilisant pour les graines. Servez-vous juste de la sacoche lorsque vous serez en possession de tout ce qui est nécessaire. Elle s'occupera du reste.\n\nLorsque vous aurez suffisamment de Fibres d'aurore, apportez-le-moi ici sur la Cime des Anciens. Veuillez ne pas déranger l'archidruide. Ses recherches l'occuperont beaucoup, de même que ses nombreux soucis le préoccuperont bien assez.", progress = "Oui, <nom> ? Avez-vous cultivé des Fibres d'aurore pour les recherches capitales de l'archidruide ? Les mystérieuses propriétés du cratère d'Un'Goro s'éclaircissent de jour en jour, grâce à votre aide.", completion = "Bon travail, &lt;nom&gt;. Je les remettrai à l'archidruide en personne lorsqu'il en aura besoin. En attendant, veuillez accepter ceci comme gage de gratitude du Cercle cénarien.\n\nNous avons pour l'heure un besoin constant de Fibres d'aurore. Si vous souhaitez continuer à nous en fournir, revenez lorsque vous en aurez cultivé plus.", rewards = "Vous recevrez :\n\nCache du Cercle cénarien"},
[3787] = {title = "La requête de Jonespyre", objective = "Parler à Quintis Jonespyre dans le bastion de Feathermoon.", description = "Excusez-moi, mon <ami/amie>…\n\nL'un de mes collègues voudrait vous entretenir à propos des recherches que vous effectuez conjointement avec le Cercle cénarien. Il est druide et se nomme Quintis Jonespyre. Il demeure au bastion de Feathermoon, en Feralas, et voudrait vous parler de la Fibre d'aurore. Il insiste pour que notre conversation n'atteigne en aucun cas les oreilles de l'archidruide…\n\nSi cela vous intéresse, allez lui parler. Il ne fait aucun doute que tout vous sera révélé si vous allez le voir.", progress = nil, completion = "Je vous remercie d'être venu, las voyageur ! Permettez-moi de me présenter. Je me nomme Quintis Jonespyre et suis druide et humble serviteur de Malfurion et du Cercle cénarien. Mes collègues (le général Shandris Feathermoon et le Protectorat, vous avez peut-être entendu parler d'eux !) et moi-même souhaitions vous entretenir à propos des travaux que vous effectuez pour Fandral Staghelm à Darnassus.\n\nAvant de poursuivre, j'aimerais vous demander de garder secrète cette conversation. Si cela ne vous pose pas de problèmes, alors nous pouvons commencer.", rewards = "Vous recevrez :\n\n"},
[3788] = {title = "La requête de Jonespyre", objective = "Parler à Quintis Jonespyre dans le bastion de Feathermoon.", description = "Excusez-moi, mon <ami/amie>…\n\nL'un de mes collègues voudrait vous entretenir à propos des recherches que vous effectuez conjointement avec le Cercle cénarien. Il est druide et se nomme Quintis Jonespyre. Il demeure ici au bastion de Feathermoon et voudrait vous parler de la Fibre d'aurore. Il insiste pour que notre conversation n'atteigne en aucun cas les oreilles de l'archidruide.\n\nSi cela vous intéresse, allez lui parler. Il ne fait aucun doute que tout vous sera révélé si vous allez le voir.", progress = nil, completion = "Je vous remercie d'être venu, las voyageur ! Permettez-moi de me présenter. Je me nomme Quintis Jonespyre et suis druide et humble serviteur de Malfurion et du Cercle cénarien. Mes collègues (le général Shandris Feathermoon et le Protectorat, vous avez peut-être entendu parler d'eux !) et moi-même souhaitions vous entretenir à propos des travaux que vous effectuez pour Fandral Staghelm à Darnassus.\n\nAvant de poursuivre, j'aimerais vous demander de garder secrète cette conversation. Si cela ne vous pose pas de problèmes, alors nous pouvons commencer.", rewards = "Vous recevrez :\n\n"},
[3789] = {title = "Assister l'archidruide Staghelm", objective = "Parler à l'archidruide Fandral Staghelm à Darnassus.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps si la chose est possible.\n\nLe Cercle cénarien à Darnassus recherche des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l'archidruide Fandral Staghelm en personne mène ces recherches.\n\nSi cela vous intéresse, allez directement lui parler à l'enclave cénarienne à Darnassus.", progress = nil, completion = "Bien, &lt;classe&gt;… Puisque vous avez été informé que je dirigeais en personne ces recherches, vous êtes évidemment venu aussi vite que possible.\n\nMaintenant que vous êtes là, écoutez attentivement. J'ai horreur de me répéter.", rewards = "Vous recevrez :\n\n"},
[3790] = {title = "Assister l'archidruide Staghelm", objective = "Parler à l'archidruide Fandral Staghelm à Darnassus.", description = "Pardonnez-moi, <classe>, mais j'aimerais prendre quelques instants de votre temps si la chose est possible.\n\nLe Cercle cénarien à Darnassus recherche des <aventuriers aguerris tels/aventurières aguerries telles> que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l'archidruide Fandral Staghelm en personne mène ces recherches.\n\nSi cela vous intéresse, allez directement lui parler à l'enclave cénarienne à Darnassus.", progress = nil, completion = "Bien, &lt;classe&gt;… Puisque vous avez été informé que je dirigeais en personne ces recherches, vous êtes évidemment venu aussi vite que possible.\n\nMaintenant que vous êtes là, écoutez attentivement. J'ai horreur de me répéter.", rewards = "Vous recevrez :\n\n"},
[3791] = {title = "Le Mystère des Fibres d'aurore", objective = "Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon.", description = "Je vais être franc avec vous, <nom>. Cela m'intéresse – non, cela m'inquiète ! – de savoir pourquoi l'archidruide de Darnassus utilise le couvert du Cercle cénarien, tout autant que ses ressources, pour se procurer d’aussi grandes quantités de Fibre d'aurore. Je suis chercheur et mon domaine concerne les malédictions. J'ai entendu dire que la Fibre d'aurore, placée dans certaines conditions, développe des propriétés similaires à celles d'autres herbes utilisées dans des malédictions primitives.\n\nJe veux en savoir davantage, et je sollicite votre aide. Apportez-moi dix Fibres d'aurore et je m’occuperai de vous.", progress = "De la Fibre d'aurore. Il m'en faut dix. Cela devrait suffire pour commencer mes recherches. J'en utiliserai probablement beaucoup pour n'arriver qu'à des impasses, mais telle est la nature des recherches.", completion = "Eurgh, cette Fibre d'aurore me fait un drôle d’effet. Par Elune, que prépare donc Staghelm avec cette chose ?\n\nMais passons, je vous remercie encore pour votre aide. Voici un petit quelque chose… Mes recherches sur la Fibre d'aurore vont nécessiter un certain temps, et il ne fait aucun doute qu'il m'en faudra encore plus. Pendant que j'y suis, je devrais prendre le temps de voir si la Fibre d'aurore a des applications alchimiques potentielles. Mais la proximité de cette plante me met mal à l'aise...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de recherche de QuintisEspauliers en écorce de fer\n\nVous recevrez également :\n\n"},
[3792] = {title = "De la Fibre d'aurore au bastion de Feathermoon", objective = "Je vous salue à nouveau, <nom>. Mes recherches progressent plutôt bien, mais si vous aviez cinq Fibres d'aurore supplémentaires, je serais heureux de vous en débarrasser. Mais “heureux” n'est qu'une figure de style. Plus j'en ai autour de moi, et plus je me sens mal à l'aise. Mes recherches nécessitent cependant que je me hâte et que j'en finisse.", description = nil, progress = "Je vous salue à nouveau, <nom>. Mes recherches progressent plutôt bien, mais si vous aviez cinq Fibres d'aurore supplémentaires, je serais heureux de vous en débarrasser. Mais “heureux” n'est qu'une figure de style. Plus j'en ai autour de moi, et plus je me sens mal à l'aise. Mes recherches nécessitent cependant que je me hâte et que j'en finisse.", completion = "Merci, &lt;nom&gt;. Je vais juste la mettre de côté pour l'instant. Bien que ce ne soit pas moi le responsable des ressources de Staghelm, je peux vous donner un petit quelque chose pour le dérangement. De toute façon, qui sait ce qu'il va arriver si Staghelm continue à s’approvisionner en Fibre d'aurore. Il y a quelque chose de louche derrière tout ça, croyez-moi.\n\nRappelez-vous que j'accepte toujours de la Fibre d'aurore. Je la prends par brassée de cinq.", rewards = "Vous recevrez :\n\nPochette de graines de Tharlendis"},
[3801] = {title = "Héritage Sombrefer", objective = "Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse.Salutations, <nom>. Je me nomme Franclorn Forgewright. Oui, le Franclorn Forgewright inventeur des méthodes d'approche architectonique de la roche. Vous êtes sans aucun doute déjà <passé/passée> près de l'une de mes créations lors de vos aventures dans notre monde ravagé par la guerre. Vous y êtes peut-être même <entré/entrée>.\n\nVous vous demandez probablement ce que je fais ici et ce que j'attends de vous. Deux excellentes questions.\n\nJ'ai besoin de votre aide, bien sûr. En échange, je vous remettrai la clé des profondeurs de ma cité maudite.", description = "Salutations, <nom>. Je me nomme Franclorn Forgewright. Oui, le Franclorn Forgewright inventeur des méthodes d'approche architectonique de la roche. Vous êtes sans aucun doute déjà <passé/passée> près de l'une de mes créations lors de vos aventures dans notre monde ravagé par la guerre. Vous y êtes peut-être même <entré/entrée>.\n\nVous vous demandez probablement ce que je fais ici et ce que j'attends de vous. Deux excellentes questions.\n\nJ'ai besoin de votre aide, bien sûr. En échange, je vous remettrai la clé des profondeurs de ma cité maudite.", progress = nil, completion = "Que ce soit l'appât du gain ou un acte de dévotion désintéressé qui vous ait conduit ici, ce que vous êtes sur le point d'accomplir profitera à tous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3802] = {title = "Héritage Sombrefer", objective = "Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright.", description = "Vous trouverez Fineous Darkvire au-delà du Cercle de Loi, dans la Chambre de l'artisanat. Tuez ce misérable chien et récupérez Souillefer.\n\nApportez Souillefer au sanctuaire de Thaurissan et placez le marteau à la place qui est la sienne : dans les mains de la statue érigée en mon honneur.\n\nAlors le compartiment dans lequel j'ai placé la Clé maîtresse s'ouvrira. Plus important encore, Souillefer restera entre mes mains pour l'éternité. S'ils tentent de l'enlever, la statue et le marteau se briseront, à jamais perdus.", progress = "La statue se dresse, sinistre, au-dessus de vous.", completion = "Le marteau glisse fermement en place entre les mains du gigantesque monument Sombrefer. Un minuscule compartiment s'ouvre à la base de la statue. À l'intérieur, vous découvrez…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nClé ombreforge"},
[3803] = {title = "Des Fibres d'aurore pour Darnassus", objective = "L'archidruide cherche davantage de Fibres d'aurore pour que le Cercle cénarien puisse poursuivre ses recherches. Nous les prenons par lot de dix. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.", description = nil, progress = "L'archidruide cherche davantage de Fibres d'aurore pour que le Cercle cénarien puisse poursuivre ses recherches. Nous les prenons par lot de dix. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.", completion = "Parfait ! Cette Fibre d'aurore satisfera sans aucun doute l'archidruide. Je dois cependant admettre que d’être si proche de cette plante me met un peu mal à l'aise. Je ne peux qu'imaginer à quel point il doit être difficile pour l'archidruide d'en supporter de si grandes quantités !\n\nVoilà pour vous, &lt;nom&gt;. Le Cercle cénarien vous remercie pour votre aide soutenue.", rewards = "Vous recevrez :\n\nCache du Cercle cénarien"},
[3804] = {title = "Des Fibres d'aurore pour Thunder Bluff", objective = "L'archidruide cherche davantage de Fibre d'aurores pour que le Cercle cénarien puisse poursuivre ses recherches sur le cratère d'Un'Goro. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.", description = nil, progress = "L'archidruide cherche davantage de Fibre d'aurores pour que le Cercle cénarien puisse poursuivre ses recherches sur le cratère d'Un'Goro. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.", completion = "Parfait ! Cette Fibre d'aurore nous sera d'un grand secours le temps venu. Nous savons que les elfes de la nuit conduisent des recherches similaires avec ces herbes, bien que nous ne sachions pas dans quel but. L'archidruide estime que nous aurons besoin de Fibre d'aurore jusqu'à ce que nous comprenions ses mystères.\n\nVoilà pour vous, &lt;nom&gt;. Le Cercle cénarien vous remercie pour votre aide soutenue.", rewards = "Vous recevrez :\n\nCache du Cercle cénarien"},
[3821] = {title = "Le Rocher des Cognepeurs", objective = "S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk.", description = "Sha'ni a été envoyée dans les Steppes ardentes pour enquêter sur les rites étranges des ogres Brûlentrailles. C'était il y a plus de trois semaines.\n\nGoretooth dit qu'il n'a plus de nouvelle de son régiment et que je ferais mieux de l'oublier et de me concentrer sur ce que j'ai à faire. Incroyable, non ? C'est ma femme !\n\nJe suis dans l'impossibilité de quitter mon poste, <nom>, mais je dois savoir ce qu'il lui est arrivé. Partez pour les Steppes ardentes et cherchez-la, je vous en prie.", progress = nil, completion = "Mon pauvre Thal'trak.\n\nNous comptions déménager chez mes parents dans les Hinterlands après en avoir terminé ici. À présent ces projets sont ruinés.", rewards = "Vous recevrez :\n\n"},
[3822] = {title = "Krom'Grul", objective = "Récupérer l’Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs.", description = "Tout mon régiment a été capturé, <nom>. Tous ont été tués, sauf moi.\n\nLeur chef, Krom'Grul, voulait me réserver pour un genre de rituel.\n\nJ'ai été enchaînée à cet autel et battue à mort par ce monstre. J’ai rendu l’âme après une heure de cette torture. Alors, il a arraché mon anneau de nez de mariage et l'a passé à son doigt. Je n'ai jamais vu une telle sauvagerie !\n\nTrouvez Krom'Grul et tuez-le ! Rapportez mon anneau à Thal'trak.\n\n<nom>, dites-lui que nous nous rencontrerons à nouveau... dans une autre vie.", progress = "Avez-vous trouvé Sha'ni ? Va-t-elle bien ?", completion = "&lt;Thal'trak s'écroule.&gt;\n\nNous allions partir pour les Hinterlands. Elle vous l'a dit ? Il s'agissait de sa dernière mission.\n\n&lt;Thal'trak sanglote.&gt;\n\nJe n'en veux pas, &lt;nom&gt;. Gardez-le. Ou débarrassez-vous-en, je m'en fiche ! Cet anneau n'est plus rien pour moi à présent. Pas sans elle...", rewards = "Vous recevrez :\n\nAnneau de Sha'ni"},
[3823] = {title = "Exterminer les Brûlentrailles", objective = "Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius.", description = "Nous devons frapper nos ennemis avant qu'ils ne nous frappent !\n\nJe serai bref, soldat.\n\nLes ogres Brûlentrailles des Steppes ardentes sont les alliés des orcs Blackrock. Ils collaborent étroitement avec ces maudits orcs, gardant le rocher des Cognepeurs, riche en minerais, et veillant à la sécurité des lignes d'approvisionnement.\n\nLaissez votre signature, <nom>. Bousculez leurs rangs et revenez me voir quand vous aurez accompli votre travail.\n\n<Oralius serre ses poings en l'air et simule une suffocation.>\n\nJE VAIS TE TUER, WINKY !", progress = "Il n'y a pas assez de sang sur votre uniforme, soldat, loin de là !", completion = "Merveilleux, soldat ! Ce coup va faire vaciller les orcs et les ogres pendant plusieurs minutes, voire plusieurs heures !", rewards = "Vous recevrez :\n\n"},
[3824] = {title = "Le seigneur-brute Gor'tesh", objective = "Trouver Gor'tesh, quelque part à l’ouest du rocher des Cognepeurs. Le tuer et rapporter la Tête coupée de Gor'tesh à Oralius, dans les Steppes ardentes.", description = "Ils faiblissent, je vous assure ! Nous devons à présent porter un coup décisif.\n\nLe seigneur-brute Gor'tesh doit être tué. Plus important encore, vous devez me rapporter sa tête afin que je puisse préparer la troisième partie de notre attaque sur les ogres Brûlentrailles.\n\nAttention, soldat : Gor'tesh n'est pas établi au rocher des Cognepeurs lui-même, mais dans un bâtiment des orcs Blackrock, à l'ouest du rocher des Cognepeurs.\n\nVos ordres sont simples : trouvez Gor'tesh et décapitez-le. Revenez me voir une fois votre travail accompli.\n\nSILENCE, WINKY !", progress = "Loué soit ce jour ! Êtes-vous revenu avec sa tête ?", completion = "Regardez ça, soldat. Dé-goû-tant ! Lorsque les ogres Brûlentrailles verront ce gros nigaud planté sur une pique au sommet de leur montagne, il va s'ensuivre une hystérie collective !\n\n&lt;Oralius glousse grassement.&gt;", rewards = "Vous recevrez :\n\n"},
[3825] = {title = "Une tête d'ogre au bout d'une pique = une fête", objective = "Prendre la Tête coupée de Gor'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique.", description = "Il vous reste une dernière chose à faire, soldat.\n\nJ'ai pris la liberté de planter la tête de Gor'tesh sur une pique. À présent, tout ce que vous avez à faire, c'est d'apporter cette pique au sommet du rocher des Cognepeurs et de la ficher dans le sol. Après cela, vous pourrez admirer ces lâches d'ogres courir pour sauver leur vie ! Après vous être <amusé/amusée> un peu, revenez et je vous récompenserai pour votre dur labeur.\n\n<Oralius semble perdre contact avec la réalité.>", progress = "Alors, avez-vous dépeint la situation ?", completion = "Un travail extraordinaire, soldat ! Impressionnant ! Je vais obtenir la médaille du courage pour ça, euh… Je veux dire que vous allez recevoir une récompense exceptionnelle pour votre exploit !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGantelets exaspérantsAnneau d'apnée\n\nVous recevrez également :\n\n"},
[3841] = {title = "Un orphelin à la recherche d'un foyer", objective = "Parler à Quentin aux Mille pointes.", description = "Oh, salut <nom> ! Cela me fait plaisir de vous revoir. Comment s'est passé votre voyage à Darnassus ?\n\nJe crois que vous serez <heureux/heureuse> d'apprendre que nous avons fait pas mal de progrès pendant que vous étiez <parti/partie>. Nous avons même sauvé un nid plein d'œufs. Malheureusement, la mère est morte avant que nous puissions l'atteindre.\n\nDites-moi, en voudriez-vous un pour en faire un animal de compagnie ? Ils semblent bientôt prêts à éclore et ont besoin <d'un père attentif/d'une mère attentive>. Qu'en dites-vous ?\n\nSi cela vous intéresse, apportez l'un de ces œufs à Quentin. Il se trouve à la piste de course des Salines. Il pourra vous en apprendre davantage.", progress = "Salutations, <classe>.\n\nSurtout ne pensez pas que je me trouve ici pour les courses… bien qu'elles soient très divertissantes.\n\nEn fait, je suis ici aux Mille pointes pour découvrir comment cette terre peut être sauvée. C'est en quelque sorte ma croisade : revitaliser et réapprovisionner le secteur avec une terre riche et fertile. Je vais peut-être découvrir une source d'eau par ici...\n\nAvez-vous remarqué combien la transition entre Feralas et les Mille pointes est étrange. Une magie bizarre était à l'œuvre lorsque cela s'est produit.", completion = "Ah, un œuf de Fée fléchetteuse ! Et un œuf sur le point d'éclore, si je ne m'abuse. Il est remarquable que vous soyez parvenu à en trouver un, d'autant plus qu'il est en bonne condition. Ils sont rares en Feralas ces temps-ci. J'ai cru comprendre que des braconniers tentaient d'en capturer et d'en détruire pour diverses raisons. Dommage, vraiment... Ce sont de si belles créatures lorsqu'elles atteignent la maturité.\n\nComment avez-vous fait une telle découverte ?", rewards = "Vous recevrez :\n\n"},
[3842] = {title = "Une courte incubation", objective = "Apporter 2 Elixirs de Robustesse à Quentin, aux Mille pointes.", description = "Les Moonweaver, hein ? Fascinant. J'aimerais que les Fées fléchetteuses comprennent ce que cela veut dire d'avoir ces deux-là veillant sur elles.\n\nLes Moonweaver sont tout à fait compétents.\n\nAinsi, ce sont eux qui vous ont offert l'œuf. Dans ce cas, vous allez en être responsable aussi longtemps que vous le souhaitez. Il semble qu'il sera bientôt prêt à éclore, mais nous devons nous assurer qu'il va bien et qu'il n'a subi aucun dommage.\n\nJ'ai simplement besoin de deux Elixirs de Robustesse pour lancer un petit sort afin de renforcer sa santé. J’ai ici le reste des ingrédients.", progress = "Plus je reste ici et plus la tentation est forte de participer à ces courses, <nom>. Vraiment ahurissant…\n\nAvez-vous trouvé les élixirs ? Une fois que je pourrai dire si l'œuf va bien ou non, je vous le rendrai pour qu'il s'attache à vous jusqu'à ce qu'il soit prêt à éclore.\n\nFaites-le-moi savoir.", completion = "Merveilleux. Ils feront parfaitement l'affaire. Donnez-moi quelques instants pour que je puisse mélanger les ingrédients et nous verrons comment cet œuf va se porter.", rewards = "Vous recevrez :\n\n"},
[3843] = {title = "Un tout nouveau membre dans la famille", objective = "Emmenez votre Oeuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Beastamer. Dépêchez-vous, vous n’avez qu’une heure pour le trouver avant que le petit ne meure dans l’oeuf.", description = "Un spécimen magnifique, <nom>. Si cette créature arrive à terme, ce sera un animal plein de santé !\n\nSi vous avez l'intention de garder cette créature, permettez-moi de vous suggérer une dernière chose. Rendez-vous au Nid-de-l'Aigle dans les Hinterlands. Allez parler au nain Agnar Beastamer, c'est un dresseur d'animaux renommé et il vous conseillera pour mener à bien les dernières étapes de la gestation.\n\nMais dépêchez-vous, <nom>, cet oeuf est fragile et nécessite des soins appropriés.", progress = "Salut, <nom>. En quoi puis-je vous être utile ?", completion = "Fichtre, fichtre, fichtre… Je n'ai pas vu de tels oeufs depuis une éternité. Du dragon féerique, si je ne m'abuse… on dirait qu'il s'agit de la variété Fée fléchetteuse. Excellent, vraiment excellent.\n\nEh bien si l'on veut que cette petite demoiselle éclose et vive une vie de Fée fléchetteuse épanouie, nous devrions lui apporter de la nourriture.", rewards = "Vous recevrez :\n\n"},
[3844] = {title = "C'est un Secret pour tout le monde", objective = "Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé.", description = "Un radeau brisé repose le long du rivage. Vu qu'il ne s'agit que d'un petit étang, on peut se demander comment ce radeau a échoué ici. Les traces sur les arbres aux alentours indiquent cependant que le niveau de l'eau pourrait varier.\n\nExplorer ce secteur pourrait révéler des indices supplémentaires...", progress = nil, completion = "Un paquet imprégné d'eau repose au fond de l'étang.", rewards = "Vous recevrez :\n\n"},
[3845] = {title = "C'est un secret pour tout le monde", objective = "Examiner les objets du paquet et les apporter à leur propriétaire.", description = "Après vous être <emparé/emparée> du paquet, vous l'apportez jusqu'au rivage. Peut-être que si vous examinez les objets qui l'emplissent, vous pourrez en découvrir davantage sur l'identité de son propriétaire.\n\nQuelques voyageurs égarés se trouvent au refuge des Marshal. Il se peut que vous en appreniez plus en ces lieux.", progress = "Salut. Je vous ai déjà rencontré par le passé… non ?", completion = "Ah… Oui, ces choses me semblent familières… vaguement…", rewards = "Vous recevrez :\n\n"},
[3861] = {title = "COT-COT-CODEC !", objective = "Trouver de la Nourriture spéciale pour poulet et l'apporter à la poule que vous voulez aider. Lorsque vous l'aurez trouvée, encouragez-la (/acclame) avant d'essayer de lui donner la Nourriture spéciale pour poulet.", description = "Cot... cot... cot... CODEEEC !\n\nCot... cot... cot.\n\nLa poule vous regarde puis commence à griffer la terre. On dirait qu’elle est en train d’écrire un mot sur le sol. Est-ce que cela pourrait être... S-A-L-D-E-A-N ? Avant que vous ne puissez demander quoi que ce soit, la poule s’ébroue et retourne vaquer à ses occupations.", progress = "La poule vous toise d'un regard froid et ténébreux. Elle attend la nourriture avec impatience.\n\n\"CODEEEC !\n\nCot... Cot... Cot.\"", completion = "CODEEEEC !!!\n\nLa poule commence à gober avec avidité la nourriture que vous placez devant elle.\n\nAprès un moment, elle regarde autour d'elle, l'air surpris. De plus en plus mal à l'aise, elle remue d'avant en arrière. Cette poule serait-elle enceinte ? Vous estimez que vous devriez vérifier.", rewards = "Vous allez être la cible du sort suivant :\n\nInvocation d'un oeuf de poule"},
[3881] = {title = "Le sauvetage de l'expédition", objective = "Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro.", description = "Je ne sais pas comment vous êtes <parvenu/parvenue> jusqu'ici, mais votre arrivée me réjouit ! Je me nomme Williden Marshal et je mène une expédition neutre. Notre dernière tentative s'est soldée par d'innombrables désastres. Nous avons sous-estimé le danger représenté par le Cratère d'Un'Goro.\n\nAlors que nous fuyions nos campements, dans le sud-ouest et le nord-est du cratère, nous avons laissé derrière nous des fournitures d’une importance vitale. Vous avez l’air valeureux, pouvez-vous nous aider à les récupérer ?", progress = "Si nous voulons avoir la moindre chance de nous en sortir vivants, nous avons besoin de notre grande caisse de nourriture. De même, pouvoir récupérer une partie de notre équipement de recherche serait un réconfort dans une vallée de larmes.", completion = "Vous nous rapportez nos rations ET notre équipement de recherche ! Vous avez non seulement sauvé nos recherches, mais aussi nos vies. Le reste de l'équipe et moi-même ne pourrons jamais vous en remercier assez ; nous pourrons nous installer ici pour quelques temps, grâce à vous.\n\nBien que nous n'ayons pas grand-chose, je ne vous laisserai pas ici sèchement après l'aide inestimable que vous nous avez apportée. Merci, &lt;nom&gt;, comptez sur un nouvel ami dans les Expéditions Marshal !", rewards = "Vous recevrez :\n\n"},
[3882] = {title = "Faites rouler les os", objective = "Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro.", description = "On pourrait penser qu'être chef terrassier pour les Expéditions Marshal signifie que j'aime creuser. Il y a des choses bien plus désagréable à faire en ce monde… mais aucune ne me vient à l'esprit.\n\nNous étions supposés creuser dans les Coteaux de la terreur - quel nom FANTASTIQUE, soit dit en passant - à la recherche de stégodons et de dimeurtrodons morts ! Eh bien, figurez-vous qu'il en reste aussi beaucoup de vivants ! Wil et Hol essaient toujours de se sortir de ce piège, alors nous devons ramener ces os de dinosaures. Entre vous et moi, qu'il s'agisse d'os provenant de créatures vivantes fera l'affaire.", progress = "Pensez ce que vous voulez ; entre les os qui proviennent d'anciens stégodons et dimeurtrodons et ceux de la créature qui vient d'essayer de nous dévorer, ils ne feront pas la différence. La seule chose qui m'importe, c'est que nous sortions d'ici vivants...", completion = "Parfait, ils devraient faire l'affaire. Et maintenant, si vous voulez bien…\n\nMERCI D'AVOIR EFFECTUÉ DES FOUILLES POUR RASSEMBLER TOUS CES OS POUR NOUS SANS AVOIR PERTURBÉ LA FAUNE LOCALE DE QUELQUE MANIÈRE QUE CE SOIT.\n\nCe qui s'est réellement passé, je ne veux pas le savoir. Gardons ça entre nous, d'accord ? Tenez, j'espère que cela suffira pour que vous taisiez toute l'histoire. Tant qu'on s'en sort vivants...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de fouilles de l'ArchéologueCeinture d'outils d'excavateur\n\nVous recevrez également :\n\n"},
[3883] = {title = "Ecologie étrangère", objective = "Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues.\n\nApporter l’Echantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro.", description = "On ne va pas arrêter les recherches à cause d'un échec ! Avant d'arriver ici, nous faisions des études sur les insectes Gorishi dans la partie sud du cratère. Leur présence est une nouveauté dans l'écologie d'Un'Goro et nous voulons savoir pourquoi.\n\nDans leur ruche, il doit exister une écloserie pour les larves. Vous pouvez identifier ces lieux parce que des larves sont suspendues. Utilisez cette fiole pour prélever un échantillon de la paroi de la ruche près de l'une des écloseries. Rapportez-la-moi pour que je l'étudie !", progress = "Avez-vous un échantillon de ruche Gorishi afin que je puisse l'examiner, <nom> ?", completion = "Oui, cela sera parfait. Vous nous avez été d'un grand secours… j'aimerais mieux vous récompenser, mais se tenir au milieu d'une terre sauvage ne me permet pas d'exaucer ce souhait. Soyez tranquille, cependant. Les recherches que nous menons ici n'auraient pas été possibles sans votre aide.", rewards = "Vous recevrez :\n\n"},
[3884] = {title = "Le journal de Williden", objective = "Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro.", description = "Vous avez découvert un journal en piteux état. On peut encore en déchiffrer certaines parties, cependant. Notamment le nom de son propriétaire, inscrit à l'intérieur : Williden Marshal. Si le journal dit vrai, alors Williden devrait se trouver quelque part dans la partie nord du cratère. D'après ce que raconte le journal, lui et ses hommes sont partis pour des terres plus élevées et à l'abri des bêtes sauvages lorsque leurs camps de base se sont vus submergés.", progress = "Salut ! Moi et mes compagnons sommes heureux de rencontrer une créature vivante qui ne soit pas une bête sauvage géante ! Qu'est-ce qui vous amène dans le Cratère d'Un'Goro ?", completion = "Eh bien regardez ça ! Mon journal ! J'ai cru qu'il était perdu, à peu près comme tout ce que nous avons pu apporter au Cratère d'Un'Goro. Je vous remercie du fond du cœur de me l'avoir rapporté !", rewards = "Vous recevrez :\n\n"},
[3901] = {title = "Faites cliqueter les thorax !", objective = "Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas.", description = "Vous avez montré vos capacités aux Réprouvés, dans des conditions normales, <nom>. À présent, voyons ce que vous pouvez faire lorsque vous êtes sous pression.\n\nLes squelettes Cliquethorax, d'autres sbires décérébrés du roi-liche, sont un peu plus résistants que les zombies auxquels vous avez fait face jusqu'alors. Réduisez leur nombre et démontrez votre appartenance aux Réprouvés. Quand vous aurez fini, ne vous attardez pas, revenez me voir.", progress = nil, completion = "J'en ai terminé avec vous, &lt;nom&gt;. Vous vous êtes montré digne de la liberté qui vous est accordée. Nombreux sont ceux qui s'opposeront à vous pour ce que vous êtes devenu, mais sachez que quoi qu'ils tentent contre nous, nous sommes libres et ne serons plus jamais enchaînés.\n\nPrenez cela et commencez votre route. Vous avez beaucoup à accomplir, &lt;classe&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes en linTunique de charognardJambières du vagabond\n\nVous recevrez également :\n\n"},
[3902] = {title = "La chasse aux trésors", objective = "Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain.", description = "Vous, là ! Si vous cherchez à vous rendre utile, écoutez bien !\n\nNous avons besoin de recrues fraîchement déterrées pour se rendre au Glas et rechercher tout équipement utile. Il est sûrement remisé dans des piles de boîtes. Nous attendons de nouvelles recrues mais, à moins que nous ne voulions les voir déambuler tout nus, nous ferions mieux de commencer à faire de la récupération !\n\nAllez-y, au travail, misérable sac d'os ! Et je ne récompenserai pas ceux qui n'y mettent pas d'ardeur.", progress = "Alors, avez-vous réussi à trouver des objets utiles ? Ceux que nous avons déjà jetés nous-mêmes ne comptent pas. Personne ne va nous aider. Nous autres, Réprouvés, devons nous débrouiller seuls.", completion = "Bon travail, &lt;nom&gt;, je savais que vous n'étiez pas inutile. Tenez, prenez l'un des meilleurs objets que j'ai trouvés parmi ceux que l'on a récupérés jusque-là.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCeinture en linBrassards rouillésCape courte de chauve-souris du crépuscule\n\nVous recevrez également :\n\n"},
[3903] = {title = "Milly Osworth", objective = "Parler à Milly Osworth.", description = "Votre fiabilité est démontrée, <classe>. Vous n'avez pas peur de vous salir les mains, hein ?\n\nJ'ai une amie du nom de Milly Osworth, elle a un gros problème. Elle et son chariot se trouvent de l'autre côté de l'abbaye, près de l'étable. Je suis sûr que vos deux bras devraient lui être utiles, <nom>.", progress = nil, completion = "Oh ! L'Adjoint Willem vous envoie me parler ? C'est un homme brave, toujours prêt à aider, mais son devoir l'oblige à rester à l'Abbaye du Northshire et j'ai bien peur que le problème que j'ai aujourd'hui ne le dépasse.\n\nPeut-être pourriez-vous m'aider ?", rewards = "Vous recevrez :\n\n"},
[3904] = {title = "Les vendanges de Milly", objective = "Apporter 8 seaux de la récolte de Milly à Milly Osworth à l'Abbaye de Northshire.", description = "Un gang de brigands, les Défias, s'est introduit dans les vignes de Northshire alors que je faisais les récoltes ! Je l'ai signalé aux gardes du Northshire et ils m'ont assuré qu'ils faisaient le nécessaire, mais je crains le pire pour ma récolte de raisin ! Si les Défias ne la volent pas, les gardes pourraient l'écraser en poursuivant les voyous.\n\nAidez-moi, je vous en prie ! J'ai ramassé pratiquement tout mon raisin dans des seaux mais je les ai laissés dans les vignes au sud est.\n\nRamenez-moi ces seaux ! Sauvez ma récolte !", progress = "Avez-vous mes vendanges, <nom> ?", completion = "Oh merci, &lt;nom&gt; ! Vous avez sauvé mes vendanges ! Et j'espère que vous avez appris une bonne leçon à ces Défias afin qu'ils ne remettent plus les pieds par ici.\n\nIl se peut que nous manquions de gardes, mais nous avons la chance d'avoir des héros tels que vous pour nous protéger !", rewards = "Vous recevrez :\n\n"},
[3905] = {title = "Manifeste des vendanges", objective = "Apporter le Manifeste des vendanges à Frère Neals dans l'Abbaye de Northshire.", description = "À présent que mes vendanges sont sauvées, apportez ce Manifeste des vendanges à Frère Neals. Il s'occupe du magasin de nourriture et de boisson de Northshire, et il est certain qu'il sera ravi d'apprendre que nous avons du raisin frais.\n\nVous trouverez Frère Neals dans la tour de l'abbaye. C'est là qu'il aime déguster son vin.", progress = "Vous semblez être dans de bonnes dispositions ! Venez ! Asseyez-vous et prenez un verre !", completion = "Voyons voir…\n\nOh, par exemple ! Les vendanges de Milly sont saines et sauves ! Lorsqu'elle m'a appris que des brigands avaient pris possession de ses vignes, j'étais au bord du désespoir, mais ma foi en la Lumière n'a en rien vacillé !\n\nEt grâce à votre courage, nous avons davantage de raisin pour faire davantage de vin ! Puisse la Lumière vous bénir, &lt;nom&gt;, et veiller sur vous !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape tachée de vinCeinture à loquet\n\nVous recevrez également :\n\n"},
[3906] = {title = "Discordance des flammes", objective = "Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie.", description = "Les anciens ont ressenti une perturbation parmi les éléments. Les nains Sombrefer ont invoqué en notre monde un esprit vil qui menace de recouvrir nos terres d'un froid éternel. Nous devons enquêter sur cette dissonance de la flamme.\n\nPartez pour le mont Blackrock. Passez par l'Abîme de flamme et rendez-vous dans la carrière. C'est là que vous trouverez le Seigneur du feu : le Grand maître Pyron.\n\nRétablissez l'harmonie et revenez me voir.", progress = "Une dissonance perturbe toujours les éléments, <nom>.", completion = "Cela ne peut être… cela ne doit pas être ! La mort de Pyron a simplement levé un voile. Il se trouve à présent dans les Profondeurs de Blackrock une source de corruption mille fois plus insidieuse.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3907] = {title = "Discordance des flammes", objective = "Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.", description = "Je peux goûter au vice de l'air qui vous entoure, <nom>. Il y en a un autre, caché dans les Profondeurs de Blackrock. C'est lui qui contrôle ce vice.\n\nLe vent et la terre pleurent son nom : Seigneur Incendius… mais quelqu'un… quelque chose… commande cet être. Il n'est qu'un émissaire.\n\nTrouvez-le et découvrez où se cache son maître. Revenez me voir lorsque vous aurez obtenu cette information.", progress = "Les flammes vont bientôt ravager ces terres. Hâtez-vous, <nom> !", completion = "&lt;Thunderheart s'empare de la Tablette de Kurniya.&gt;\n\nRagnaros... là...\n\nLes anciens avaient raison de craindre la corruption émanant du mont Blackrock. Un général des Dieux très anciens ! DANS NOTRE MONDE ! Nous devons réexaminer notre position ici à Kargath. Nous devons décider si nous restons pour nous battre ou si nous fuyons de crainte d’une nouvelle Fracture.\n\nSoyez particulièrement prudent si vous explorez à nouveau le mont Blackrock, &lt;nom&gt;. Un mal plus puissant que tout ce qui réside en ce monde demeure en ses profondeurs ardentes.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de l'hélionauteGants crépusculairesBrassards de démon des cryptesEtreinte loyale\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[3908] = {title = "C'est un Secret pour tout le monde", objective = "Apporter l’Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver.", description = "Vous comprenez, j'ignore comment j'ai échoué ici. Et personne ne peut me le dire. C'est un mystère pour tout le monde ! Il semble que je ne puisse me souvenir de rien…\n\nCes objets que vous m'avez apportés… ils me rappellent quelque chose, quand même.\n\nMon épée... j'étais supposé la renforcer de quelque manière, mais je ne sais pas vraiment pourquoi. Cela me navre de ne pas pouvoir m'en souvenir et d'être incapable de vous en dire plus, je suis désolé !\n\nMais ce que je peux vous dire, c'est à qui l'apporter : Donova Snowden, au Berceau-de-l'Hiver. Vous la trouverez près des sources chaudes. Elle peut y tremper l'épée.", progress = "Je ne peux y croire… Ainsi Linken est enfin parvenu à m'envoyer cette épée.", completion = "Mais bien sûr que je peux tremper cette épée. Mais pourquoi a-t-il eu besoin de tellement de temps pour me la faire parvenir ? Ce n'est pas le genre d'homme à oublier les choses…", rewards = "Vous recevrez :\n\n"},
[3909] = {title = "L'élixir de Videre", objective = "Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver.", description = "Non, ce n'est pas vrai ! Linken ? Il a OUBLIÉ ?\n\nAh, je vois… il a perdu la mémoire…\n\nBien, voici son épée. Elle n'est pas terminée, cependant. Je connais celui qui pourrait l'achever, mais… parvenir à lui parler pourrait s'avérer difficile.\n\nÉcoutez, je sais qui peut vous aider. Ce serait trop long à expliquer en détails, mais vous devez obtenir de l'élixir de Videre. La seule personne qui peut vous aider à le trouver se nomme Gregan Brewspewer. Il est difficile de le localiser, mais aux dernières nouvelles, il campait dans les terres sauvages de Feralas.", progress = "Vous êtes déjà de retour ?", completion = "Je vais avoir besoin d'une fiole pour m'assurer qu'il s'agit bien de l'élixir… Oui… C'est bien cela.", rewards = "Vous recevrez :\n\n"},
[3911] = {title = "Le dernier élément", objective = "Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires.", description = "Il y a du travail pour ceux qui s'aventurent dans les Profondeurs, <nom>.\n\nLes Sombrefers peuvent créer des golems extrêmement puissants.\n\nLes premiers rapports de nos espions indiquent que les nains se servent d'une unique source de puissance pour donner à leurs créations une puissance de destruction incomparable.\n\nImaginez simplement ce que nous pourrions faire de nos abominations si nous mettions la main sur cette Essence des éléments ! Fouillez les moindres recoins de cette cité si cela est nécessaire, mais ne revenez pas tant que vous n'avez pas découvert cette essence ! Votre récompense sera à la mesure du risque encouru.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSceau de Lagrave"},
[3912] = {title = "Rendez-vous à la tombe", objective = "Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.\n\nObjet fourni : \n", description = "Cet élixir va vous permettre de vous entretenir avec quelqu'un que vous ne pourriez même pas voir en temps normal…\n\nApportez l'élixir de Videre et l'épée de Linken jusqu'au cimetière au-dehors de Gadgetzan, à Tanaris. Une fois <arrivé/arrivée>, buvez la potion. Les conséquences pourraient vous surprendre, mais en aucun cas n'ayez crainte.\n\nUne fois que vous aurez votre \"nouvelle\" forme, dirigez-vous vers le nord jusqu'à ce que vous atteigniez les montagnes. Vous trouverez la personne à qui vous devez parler dans l'une des lézardes rocheuses. Il se nomme Gaeriyan.\n\nSouvenez-vous ! Il ne vous parlera que si vous avez adopté cette forme...", progress = nil, completion = "Cela fait longtemps que quelqu'un n'est pas venu me parler…", rewards = "Vous recevrez :\n\n"},
[3913] = {title = "Une situation grave", objective = "Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver.", description = "Si vous retournez au cimetière dont vous venez, <nom>, vous y trouverez une pierre tombale particulière. Celle-ci se démarquera des autres. Elle renferme des secrets.\n\nPoussez la pierre, et vous les apprendrez…", progress = "Il doit s'agir de la pierre tombale dont parlait Gaeriyan…", completion = "Vous poussez fermement la pierre, et elle glisse pour révéler un creux.\n\nVous y placez l'Epée de Linken et vous réalisez qu'elle s'y adapte parfaitement.", rewards = "Vous recevrez :\n\n"},
[3914] = {title = "L'épée de Linken", objective = "Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro.", description = "Après un grand flash, vous pouvez à nouveau vous saisir de l'épée. Elle s'est transformée !", progress = "Oh ! Je me souviens de vous ! Vous êtes… Non, ne m'aidez pas !", completion = "Mon épée… elle est achevée !\n\nSi seulement je pouvais me rappeler pourquoi j'en avais besoin…\n\nTenez, permettez-moi au moins de vous payer pour vos efforts.", rewards = "Vous recevrez :\n\n"},
[3921] = {title = "Wenikee Boltbucket", objective = "Apporter le Samophlange cassé à Wenikee Boltbucket.", description = "Il se peut que j'aie cassé le Samophlange. Et ce n'est pas bon, car j'en avais déjà parlé à des collègues à Undermine et ils s'y intéressaient beaucoup. Nous devons trouver un moyen de le réparer !\n\nApportez le Samophlange à Wenikee Boltbucket, à l'avant-poste de la Horde entre les Tarides et Ashenvale. Elle est très intelligente et très curieuse. Si vous lui montrez le Samophlange, je suis sûr qu'elle sera enthousiaste à l'idée de le réparer.", progress = "Mon travail m'accapare beaucoup, <classe>. À moins que vous n'ayez quelque chose pour moi, je préférerais que vous passiez votre chemin…", completion = "Oh, qu'est-ce que c'est ? Un Samophlange, vous dites ? C'est quoi un Samophlange ?\n\nAh… mais regardez la façon dont il bouge lorsque vous le tenez. Et on entend à l'intérieur le son d'un mécanisme complexe. Oh je vous en prie ! Je veux le réparer et voir ce que ça fait ! Pas vous ?", rewards = "Vous recevrez :\n\n"},
[3922] = {title = "Les Petites pièces", objective = "Apporter 15 Rondelles de métal à Wenikee Boltbucket dans les Tarides.", description = "Je veux réparer ce Samophlange, mais pour ce faire je vais avoir besoin de certaines choses. Je n'ai plus de rondelles de dix-sept cinq et je vais en avoir besoin d'un sacré paquet pour le travail qui nous attend.\n\nL'endroit le plus proche où l'on peut s'en procurer est la Videfange, à l'est. La KapitalRisk en conserve généralement dans ses seaux d'outils. Partez pour la Videfange et cherchez les seaux d'outils qui s'y trouvent. Revenez me voir lorsque vous aurez récupéré suffisamment de Rondelles de métal", progress = "Avez-vous les Rondelles de métal, <nom> ? J'ai examiné le Samophlange et ne peux plus attendre de le tripatouiller.", completion = "Parfait, vous les avez ! À présent je peux commencer à travailler…", rewards = "Vous recevrez :\n\n"},
[3923] = {title = "Rilli Greasygob", objective = "Apporter le Samophlange cassé à Rilli Greasygob à Orgrimmar.", description = "Hmm, ça n'a pas marché. J'ai placé des jauges supplémentaires sur le Samophlange pour en mesurer l'intégrité structurelle, et elles donnent comme résultat une intégrité constante proche de zéro. Je pourrais ajouter d'autres cadrans et peut-être un ou deux leviers pour essayer de le réparer, mais... je crains que ça ne fasse qu'empirer les choses.\n\nVous devriez apporter le Samophlange à Rilli Greasygob. Il travaillait autrefois pour la KapitalRisk. Si quelqu'un est capable de le réparer, c'est bien Rilli.\n\nVous pourrez le trouver à l'Atelier de Nogg à Orgrimmar, dans la Vallée de l'Honneur.", progress = "Attention à votre tête ! Je n'aimerais pas qu'elle se mette en travers de mon travail !", completion = "Qu'est-ce que c'est ? Ça alors, c'est un Samophlange ! Où vous l'êtes-vous procuré ? Avez-vous fureté près des possessions de la KapitalRisk dans les Tarides ?\n\nVous devez être très courageux. Ou très bête.", rewards = "Vous recevrez :\n\n"},
[3924] = {title = "Manuel du Samophlange", objective = "Apporter le Manuel du Samophlange à Rilli Greasygob à Orgrimmar.", description = "Je pense pouvoir réparer le Samophlange, mais je vais avoir besoin du manuel d'utilisation tout d'abord. Lorsque je travaillais pour la KapitalRisk, j'avais un rival du nom de Chef Copperplug, qui connaissait des tas de secrets sur le Samophlange, et qui donnait quelques rares informations sur l'appareil à ceux envers qui il avait confiance. Je ne faisais pas partie des rares élus...\n\nLe Chef Copperplug était généralement à la mine des Pierriers dans la partie nord-est des Tarides. Parvenez à en obtenir le manuel, et s'il en a distribué des pages à quiconque, vous devrez également les récupérer.", progress = "Avez-vous le manuel ?", completion = "Vous avez le manuel ! Je ne peux plus attendre de le lire et de trouver comment réparer le Samophlange. J'ai parlé à Sputtervalve à Ratchet. Il voulait vous remercier pour votre aide, et vous récompenser pour vos efforts.\n\nJ'aimerais également vous remercier, et si je parviens un jour à réparer ce truc, je vous le ferai savoir...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nClé de TorkTournevis Samophlange\n\nVous recevrez également :\n\n"},
[3941] = {title = "Un gnome dans le besoin", objective = "Trouver J.D. Collie dans la caverne du refuge des Marshal.", description = "Réfléchir… réfléchir… je sais que je suis venu ici pour quelque chose d'important…\n\nJ'ai une idée, <nom>. Dans la caverne proche se trouve une gnome du nom de J.D. Elle a été très aimable envers moi lorsque je suis arrivé ici. Peut-être que désorienté comme je l'étais, je lui ai dit quelque chose dont elle pourrait se souvenir ?\n\nPourquoi n'iriez vous pas la voir et lui demander ? Oh, mais attention ! Elle joue toujours avec ces cristaux brillants que j'ai vus dans le cratère. Je ne sais pas vraiment ce qu'elle prépare là-bas !", progress = nil, completion = "Restez où vous êtes et ne bougez plus… j'expérimente une nouvelle combinaison de cristaux…", rewards = "Vous recevrez :\n\n"},
[3942] = {title = "Les souvenirs de Linken", objective = "Trouver Eridan Bluewind dans le sud de Gangrebois.", description = "Oh… Linken ? Oui, c'est un drôle de type. La première fois qu'il est venu ici, il marmonnait des propos incohérents. Il a dû recevoir un sacré coup sur la tête, si vous voulez mon avis.\n\nMais je ne peux pas m'empêcher de me souvenir de quelque chose qu'il disait, tout de même. Comme quoi il construisait un genre de totem. Il disait qu'il devait parler à quelqu'un du nom d'Eridan Bluewind... dans un endroit appelé Gangrebois... je crois ?\n\nJe ne pense pas qu'il puisse lui-même vous en dire plus. Si vous voulez en apprendre davantage, peut-être devriez-vous chercher en personne Eridan ?", progress = nil, completion = "Salutations, &lt;classe&gt;. En quoi puis-je vous aider ?", rewards = "Vous recevrez :\n\n"},
[3961] = {title = "L'aventure de Linken", objective = "Apporter le Totem d'argent d'Aquementas à Linken au refuge des Marshal.", description = "Et dire que pendant tout ce temps la raison pour laquelle Linken est venu ici était de nous débarrasser de Blazerunner… Il semble être une personne ordinaire, mais j'ai remarqué qu'il ne s'intéressait pas le moins du monde à mes expériences et à mes gadgets, qui passionnent d'ordinaire les gnomes. Il doit être un grand guerrier.\n\nApportez-lui le totem. Voyez si cela l'aide à se remémorer la raison pour laquelle il est venu ici.", progress = "Salut, <nom>.", completion = "Est-ce que J.D. a pu vous être d'une quelconque utilité ?", rewards = "Vous recevrez :\n\n"},
[3962] = {title = "C'est dangereux d'y aller seul", objective = "Partir pour la crête de la Fournaise, au sud du refuge des Marshal.\n\nTrouver Blazerunner et utiliser le Totem pour dissiper son aura protectrice. Une fois Blazerunner vaincu, se procurer la Flamme dorée.", description = "<nom>, je m'en souviens enfin… Je suis venu ici pour combattre Blazerunner. J'ai fait un long voyage, et il s'agissait de la dernière étape.\n\nMais ce n'est plus moi le héros… c'est vous. Avec tout ce que vous avez déjà accompli, c'est à vous d'en finir, pas à moi.\n\nConfrontez-vous à Blazerunner, et battez-le. Il garde un artefact appelé la Flamme dorée. Il procure une puissance plus vaste que tout ce que j'ai pu connaître, et il est plus que dangereux entre les mains de quelqu'un au cœur maléfique.\n\nNe partez pas <seul/seule>, ce serait trop dangereux.", progress = "Blazerunner est presque invincible à l'abri de l'aura qu'il a créée avec la Flamme dorée. Vous seul avez le pouvoir de la dissiper à l'aide de votre Totem d'argent d'Aquementas.", completion = "Merci, &lt;nom&gt;.\n\nLa Flamme dorée va à présent retourner dans ma patrie, où elle sera protégée et à l'abri de desseins maléfiques futurs. \n\nSans vous, je n'aurais toujours aucune idée de mon identité. Puisque vous avez tant fait pour moi, j'aimerais vous payer de retour... \n\nPrenez celle que vous voulez !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée de maîtrise de LinkenEsprit d'Aquamentas\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nBoomerang de Linken"},
[3981] = {title = "Le commandant Gor'shak", objective = "Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.\n\nLe dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison.", description = "Pauvre Gargal… il ne l'a même pas vue venir. SCHLACK ! La flèche est entrée exactement au centre du sommet de sa tête. Déjà que ce n'était pas une lumière avant alors maintenant…\n\n<Galamav grimace.>\n\nLorsque nous avons délogé la flèche, nous avons trouvé un message qui y était enroulé.\n\nOn y voyait vulgairement dessiné un orc derrière des barreaux et la signature du commandant Gor'shak.\n\nS'il est toujours en vie dans les Profondeurs, vous allez devoir le retrouver.\n\nIl s'agit d'un piège, vous croyez ? Peut-être... c'est pourquoi c'est VOUS qui y allez.", progress = nil, completion = "Nous n'avons pas beaucoup de temps. Écoutez-moi bien, &lt;nom&gt;. Ce que j'ai à vous dire est secret et doit rester entre nous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[3982] = {title = "Que se passe-t-il ?", objective = "Défendre Gor'shak.", description = "Je suis venu sous les auspices de Thrall. Pensiez-vous réellement que ces bouffons auraient pu me capturer ? Je me suis arrangé pour être fait prisonnier et pour pouvoir trouver des informations.\n\n<Gor'shak chuchote.>\n\nLa princesse d'Ironforge a été enlevée par l'Empereur Thaurissan. La Princesse Bronzebeard est dans cette cité même ! Je parie que le cœur du vieux Magni s'est presque arrêté de battre lorsqu'il a appris la nouvelle.\n\n<Gor'shak rit.>\n\nChuuut ! Vous entendez ? Des gardes arrivent ! DEFENDEZ-VOUS !", progress = "Défendez-vous, imbécile !", completion = "Il s'en est fallu de peu. Il savent que vous êtes ici… D'autres vont sûrement surgir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4001] = {title = "Que se passe-t-il ?", objective = "Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar.\n\nGor'shak a dit que Kharan était détenu dans une cellule proche.", description = "Jusqu'à présent, mes entretiens avec le nain, Kharan, dans la cellule de l'autre côté du mur, ont été plus que limités. J'ai tout de même réussi à le convaincre que je (ou plutôt que nous) ne lui voulions aucun mal.\n\nAllez lui parler et obtenez autant d'informations que possible sur la princesse et sur ses ravisseurs. Puis allez raconter au Chef de guerre ce que vous avez appris.\n\nThrall ne veut pas qu'il soit fait le moindre mal à la princesse. Bien au contraire, il a prévu un plan pour qu'elle retourne en toute sécurité à Ironforge. Kharan sait déjà tout cela... Allez-y !", progress = nil, completion = "Il s'agit d'une opportunité pour la Horde de changer le climat politique de notre monde en sempiternelle guerre. Écoutez attentivement, &lt;nom&gt;.\n\nDans cette mission, l'échec n'est pas une option.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4002] = {title = "Les Royaumes de l'est", objective = "Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue.", description = "Vous apportez d'excellents renseignements, <nom>.\n\nEn tant que Chef de guerre, il est de mon devoir d'accomplir ce qu'il y a de mieux pour la Horde. De m'assurer que les générations qui nous suivent ne soient pas astreintes à une existence sans espoir.\n\nLa possibilité de construire nos alliances futures nous échoit à tous. Un geste d'aide envers les nains pourrait fortement renforcer nos liens avec les Royaumes de l'est. Voici la raison pour laquelle vous ne devez pas échouer !\n\nÊtes-vous <prêt/prête> ?", progress = nil, completion = "Vous ne pouvez à présent plus vous rétracter, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4003] = {title = "Un sauvetage royal", objective = "Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique.", description = "Ce coup porté aux nains Sombrefer pourrait créer une onde de choc perceptible dans tout leur royaume.\n\nLa princesse Bronzebeard est sous le contrôle de l'Empereur Thaurissan. Vous devez tuer l'Empereur afin de la libérer. Mais attention, votre quête est dangereuse à plus d'un titre, car la princesse elle-même vous attaquera sans retenue tant qu'elle sera sous le contrôle de l'Empereur. NE LUI FAITES PAS DE MAL !", progress = nil, completion = "Qu'avez-vous fait !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4004] = {title = "La Princesse sauvée ?", objective = "Retourner voir Thrall !", description = "Vous avez assassiné mon mari, <nom> ! Mon enfant naîtra et grandira dans ce monde sans avoir de père.\n\n<Princesse Moira vous montre du doigt.>\n\nJe vous jure pourtant que cet enfant sera le prochain souverain du royaume d’Ironforge. Vous et ceux de votre espèce seront chassés et abattus comme des chiens, sans répit et sans merci.\n\n<Vous pensez que la Princesse Moira souffre peut-être des effets résiduels du sort de Thaurissan.>\n\nLaissez-moi, <nom>. Je pense que votre Chef de guerre est avide de connaître le résultat de son ingérence.", progress = nil, completion = "&lt;Thrall est interloqué par les informations que vous venez de lui apporter.&gt;\n\nUne nouvelle menace se profile à l'horizon. Avec la fin du règne de Magni, rien ne s'opposera à ce que ce nouveau Sombrefer devienne le maître d'Ironforge.\n\nVous avez accompli ce que je vous avais demandé et je vais vous récompenser.\n\nMaintenant laissez-moi, &lt;nom&gt; ! Je dois m'entretenir avec Sylvanas et Cairne.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRésolution de ThrallOeil d'Orgrimmar\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4005] = {title = "Aquementas", objective = "Apporter le Livre d'Aquor, les Griffes argentées et le Coeur d'Arbrefer à Tanaris.\n\nUtiliser le Livre d'Aquor pour invoquer Aquementas.\n\nAprès avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal.", description = "Apportez le sac de fournitures à Tanaris. Rendez-vous à la crique des Gréements, et cherchez un cercle de pierres.\n\nLa péninsule la plus à l'est, là est le secret…\n\nLisez le Livre d'Aquor une fois que vous serez dans ce cercle. Invoquez la seule créature qui soit capable de transformer vos objets en un Totem pour combattre Blazerunner.\n\nAquementas n'aimera pas être ainsi éveillé, mais souvenez-vous que vous devez rester dans le cercle pour qu'il transforme les objets.", progress = "Alors vous êtes de retour, hein ? Hmm… Laissez-moi regarder cela de plus près, <nom>.", completion = "Blazerunner, vous dites…\n\nOui, je sais qu'un puissant élémentaire réside au centre carbonisé du cratère. Nous gardons simplement nos distances. Personne n'a jamais été capable de pénétrer la puissante aura qui l'entoure. Beaucoup ont été repoussés des chemins rocailleux et ont atterri en contrebas en tentant de le battre.", rewards = "Vous recevrez :\n\n"},
[4021] = {title = "La contre-attaque !", objective = "Apporter un Morceau de la bannière de Krom'zar à Regthar Deathgate, à l'ouest de la Croisée.", description = "La Horde loue vos victoires contre les Kolkar, mais ils sont à présent fous furieux. On me rapporte qu'un contingent, épris de vengeance, a quitté leur patrie en Désolace pour arriver dans les Tarides. Aux dernières nouvelles, ils prennent d'assaut les fortins depuis l'ouest !\n\nCombattez les envahisseurs, et mettez un terme à la menace qu'ils représentent pour les Tarides. Tuez-en jusqu'à ce que leur chef de guerre, Krom'zar, apparaisse. Battez-le et apportez-moi un morceau de sa bannière comme preuve de votre exploit.\n\nNous comptons sur vous, <nom>.", progress = "Avez-vous la bannière ?", completion = "Vous avez réussi ! Vous avez vaincu les Kolkar !\n\nJe m'assurerai que Thrall ait vent de vos exploits en ce jour, &lt;nom&gt;.\n\nTenez vous fièrement. Vous avez recouvert d'honneur et la Horde et vous-même.", rewards = "Vous recevrez :\n\n"},
[4022] = {title = "Un goût de flammes", objective = "Montrer à Cyrus Therepentous le Cuir de dragon noir que vous avez reçu de Velarok Lamevent.", description = "Les dragons sont au courant de vos œuvres dans la gorge des Vents brûlants.\n\nMontrez-la-moi, <nom>. L'écaille, imbécile.", progress = "<Les yeux de Cyrus forment deux sphères embrasées.>", completion = "&lt;Cyrus examine l'Ecaille.&gt;\n\nVous avez prouvé que vous n'étiez pas complètement inutile, mortel.", rewards = "Vous recevrez :\n\n"},
[4023] = {title = "Un goût de flammes", objective = "Montrer à Cyrus Therepentous une preuve de votre valeur.\n\nVous avez le sentiment que Cyrus sait déjà que vous êtes indigne.", description = "Vous recherchez les dragons ? Présentez-moi la preuve de votre valeur, <mortel/mortelle>.", progress = "<Les yeux de Cyrus forment deux sphères embrasées.>", completion = "&lt;Cyrus examine l'Ecaille.&gt;\n\nVous avez prouvé que vous n'étiez pas complètement inutile, mortel.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4024] = {title = "Un goût de flammes", objective = "Partir pour les Profondeurs de Blackrock et tuer Bael'Gar.\n\nVous savez seulement que le géant demeure à l'intérieur des Profondeurs de Blackrock. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.\n\nApporter l'Essence ardente recouverte à Cyrus Therepentous.", description = "Je souhaite goûter aux flammes ardentes de la montagne de feu. Laisser la lave fondue cascader tout le long de mon être. Cette essence, cette chaleur fulgurante, c'est cela dont j'ai soif.\n\nBael'Gar demeure dans les Profondeurs de Blackrock : un être fait de flammes pures, né des feux de Ragnaros. Tuez Bael'Gar et extrayez de ses restes brûlants son feu intérieur.\n\nServez-vous de l'écaille pour arracher sans danger le feu intérieur à sa dépouille.\n\nSi vous réussissez à me le rapporter, vous serez <récompensé/récompensée>.", progress = "Le géant a-t-il été abattu ?", completion = "&lt;Cyrus vous arrache l'Essence ardente des mains.&gt;\n\nOUI !\n\nPrenez votre prix et partez. Sortez de ma vue immédiatement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape peau-de-schisteSpallières en peau de wyrmEcharpe valconienne\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4041] = {title = "L'élixir de Videre", objective = "Apportez-moi de l'Evoroot, et je vous ferai de l'élixir de Videre sans problème.\n\nJe connais toutes sortes de choses à propos des herbes et de l'alchimie… Tenez, par exemple, laissez-moi vous raconter la fois où j'ai transformé le fromage que j'étais sur le point de manger au déjeuner en or... Hé... Où allez-vous ?", description = nil, progress = "Apportez-moi de l'Evoroot, et je vous ferai de l'élixir de Videre sans problème.\n\nJe connais toutes sortes de choses à propos des herbes et de l'alchimie… Tenez, par exemple, laissez-moi vous raconter la fois où j'ai transformé le fromage que j'étais sur le point de manger au déjeuner en or... Hé... Où allez-vous ?", completion = "Alors, vous en avez mis une au vieux Miblon, hein ?", rewards = "Vous recevrez :\n\nElixir de Videre"},
[4061] = {title = "La révolte des machines", objective = "S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.\n\nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments.", description = "Nous avons découvert les machines lors de nos premières incursions dans la Gorge des Vents brûlants. Après une enquête plus minutieuse nous avons découvert qu'elles étaient importées des Steppes ardentes, et peut-être des Profondeurs de Blackrock. C'est pour cela que nous avons besoin de vous, <nom>.\n\nVotre première mission sera de pénétrer dans les Steppes ardentes et de récupérer des Fragments d'élémentaires sur des automates de roc et sur des réalisations en roc moindres de la région. Lorsque vous en aurez suffisamment, revenez me voir et je déterminerai leur origine.", progress = "Ne prenez pas cette tâche à la légère, <nom> !", completion = "&lt;Theodora pose les fragments devant elle.&gt;\n\n&lt;Elle les examine avec attention à l'aide d'un énorme monocle.&gt;\n\nIntéressant. On peut lire gravées à la base de chacun de ces fragments… des initiales.", rewards = "Vous recevrez :\n\n"},
[4062] = {title = "La révolte des machines", objective = "Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.\n\nTheodora vous a dit qu'il se trouvait au camp à l'est.", description = "G.L.A.\n\nVoici les 'initiales' gravées sur les Fragments d'élémentaires. Au-dessous, on peut lire un genre de rang. Les machines que vous avez détruites dans les Steppes ardentes étaient de 'Rang IV'. Je présume qu'il s'agit d'un rang peu élevé.\n\nApportez cet Echantillon de fragment à Lotwil Veriatus dans le camp à l'est. Il est un érudit et a un certain renom dans les sciences sur les élémentaires. Il se peut qu'il puisse nous venir en aide dans notre quête.", progress = "Qu'avez-vous donc là, <nom> ?", completion = "&lt;Le visage de Lotwil devient livide.&gt;\n\nJe… je reconnais ces marques.", rewards = "Vous recevrez :\n\n"},
[4063] = {title = "La révolte des machines", objective = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.", description = "Argelmach ? Impossible ! Argelmach a été tué il y a dix ans. Je le sais, c'est moi qui l'ai tué.\n\nIl s'agissait d'un nain abject, obsédé par l'idée de ruiner le travail de ma vie afin d'atteindre ses diaboliques desseins. Il semble qu'il soit toujours parvenu à échapper à la justice.\n\nS'il s'agit de l'oeuvre d'Argelmach, et ça l'est assurément, alors il doit être détruit. Je vais avoir besoin de spécimens de ses dernières créations. Si l'on me donne les bons, il se peut que je parvienne à mettre un terme à ce soulèvement. Les créations gardent Argelmach, dans les Profondeurs de Blackrock.", progress = "Etait-ce bien lui ? Etait-il vraiment en vie ?", completion = "Qu'est-ce que c'est ?! Cette tête n'est pas faite de chair. C'est un genre de création Sombrefer. Une ombre d'Argelmach. UNE AUTRE machine ! Je suspecte que votre exploit soit de courte durée, car un autre Argelmach va bientôt se lever et prendre 'sa' place.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmict de lune azurDrapé de pluviomancienBroigne basaltiqueGantelets volcaniques\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4081] = {title = "TUER A VUE : nains Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !\n\nLe chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.", description = "Par ordre du chef de guerre Goretooth, commandant du corps expéditionnaire de Kargath :\n\nTous les membres des forces du général Forgehargne présents dans les Profondeurs de Blackrock doivent être annihilés.\n\nLes hommes de Forgehargne sont des tueurs de sang-froid, responsables du massacre de masse de la 109e division du corps expéditionnaire de Kargath. Les héros doivent exercer avec une prudence extrême lorsqu'ils combattent ces brutes.\n\nQuiconque détruira la première ligne des forces du général Forgehargne dans les Profondeurs de Blackrock recevra un tribut.", progress = nil, completion = "Ce premier coup devrait agacer Forgehargne. À présent, circulez, soldat. J'ai du travail à accomplir, des batailles à planifier, et des ennemis à écraser !\n\nAllez voir les avis de recherche si vous cherchez du travail supplémentaire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4082] = {title = "TUER A VUE : Officiers de haut rang Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !\n\nLe Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie.", description = "Par ordre du chef de guerre Goretooth, commandant du Corps expéditionnaire de Kargath :\n\nLe chef du service de renseignement du C.E.F., le Grand maître Lexlort, et revenu avec des informations concernant l'endroit approximatif où se trouveraient les officiels de haut rang Sombrefer. Derrière une porte verrouillée et près du cœur de la cité, ils entraînent leurs forces pour faire périr nos hommes. Partez pour les Profondeurs de Blackrock et tuez-les !\n\nLa réussite de cette mission vous vaudra un tribut.", progress = nil, completion = "Forgehargne doit être à présent… en colère. Revenez me voir lorsque vous recevrez un troisième tribut et nous commencerons l'Opération Mort à Forgehargne. Je ne peux pas encore vous en dévoiler les détails, mais dormez tranquille : Il contient une partie sanglante.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4083] = {title = "Le Calice spectral", objective = "Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant.", description = nil, progress = "Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant.", completion = "Les gemmes ne font aucun bruit tandis qu'elles plongent dans les profondeurs du Calice...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4084] = {title = "Coeur d'argent", objective = "Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Bluewind à Gangrebois.", description = "Je ne connais pas la personne dont vous parlez, <nom>.\n\nMais ne vous inquiétez pas ; si votre ami était en voyage pour venir me trouver, je sais ce qu'il recherchait.\n\nAu cœur du cratère d'Un'Goro demeure un mal sous sa forme la plus pure. Ce mal prend la forme d'un élémentaire du nom de Blazerunner... Il est protégé par une aura que personne ne peut dissiper.\n\nPersonne... à part ceux qui ont suffisamment de pouvoir pour y parvenir. Je peux vous apprendre ce pouvoir, <nom>.\n\nD'abord, faites ce que je vous demande. Trouvez 11 Griffes d'argent et 1 Cœur d'Arbrefer sur les créatures de Gangrebois, puis revenez.", progress = "Je pourrais vous en apprendre davantage sur le pouvoir dont vous aurez besoin pour défaire Blazerunner, mais vous devez tout d'abord trouver ce que je vous ai demandé.", completion = "Très bien, &lt;nom&gt;. Je vois que vous êtes sérieux lorsque vous dites vouloir aider votre ami.", rewards = "Vous recevrez :\n\n"},
[4101] = {title = "Purifie Gangrebois", objective = "Apporter 15 Ambres de sang à Arathandris Silversky à Gangrebois.", description = "Les plantes procurent de la vie à Gangrebois, mais elles-mêmes souffrent des souillures de la corruption. Je connais les moyens de les en débarrasser, mais je ne peux enseigner une telle connaissance qu'à ceux en qui j'ai une entière confiance. Prouvez-moi que vous soutiendrez véritablement la cause du Cercle cénarien !\n\nVous trouverez au nord les cavernes d'Arbrefer. Les élémentaires de Crochebois qui s'y trouvent ne peuvent plus à présent être purifiés. Je vous demande de m'apporter leur essence (l'Ambre de sang) afin que je l'étudie dans l'espoir de sauver les autres formes de vie ici.", progress = "Je sais que Gangrebois souffre, <nom> - et je souffre aussi ! Il faut que ma conviction demeure inébranlable : si mon savoir tombait dans de mauvaises mains, un désastre s'abattrait sur Gangrebois.\n\nApportez-moi l'ambre de sang tiré des élémentaires Crochebois que vous avez tué, et je vous accorderai suffisamment de confiance pour m'aider à mettre en œuvre le moyen de combattre la corruption.", completion = "Cet ambre de sang va servir à découvrir un moyen de battre la souillure qui recouvre Gangrebois. Vous m'avez prouvé que vous étiez prêt à tout pour le Cercle cénarien. Je vous fais à présent confiance, mon ami.\n\nIl peut vous sembler étrange que tuer des élémentaires me prouve votre valeur, mais la fin, qui est de sauver d'innombrables êtres doués de sensation, justifie les moyens que nous prenons. Vous et moi pouvons nous concentrer sur la préservation de la vie à travers le baume que je peux préparer.\n\n&lt;nom&gt;, il est temps de purifier Gangrebois.", rewards = "Vous recevrez :\n\n"},
[4102] = {title = "Purifie Gangrebois", objective = "Apporter 15 Ambres de sang à Maybess Riverbreeze à Gangrebois.", description = "Les plantes procurent de la vie à Gangrebois, mais elles-mêmes souffrent des souillures de la corruption. Je connais les moyens de les en débarrasser, mais je ne peux enseigner une telle connaissance qu'à ceux en qui j'ai une entière confiance. Prouvez-moi que vous soutiendrez véritablement la cause du Cercle cénarien !\n\nVous trouverez au nord les cavernes d'Arbrefer. Les élémentaires de Crochebois qui s'y trouvent ne peuvent plus à présent être purifiés. Je vous demande de m'apporter leur essence (l'Ambre de sang) afin que je l'étudie dans l'espoir de sauver les autres formes de vie ici.", progress = "Je sais que Gangrebois souffre, <nom> - et je souffre aussi ! Il faut que ma conviction demeure inébranlable : si mon savoir tombait dans de mauvaises mains, un désastre s'abattrait sur Gangrebois.\n\nApportez-moi l'ambre de sang tiré des élémentaires Crochebois que vous avez tué, et je vous accorderai suffisamment de confiance pour m'aider à mettre en œuvre le moyen de combattre la corruption.", completion = "Cet ambre de sang va servir à découvrir un moyen de battre la souillure qui recouvre Gangrebois. Vous m'avez prouvé que vous étiez prêt à tout pour le Cercle cénarien. Je vous fais à présent confiance, mon ami.\n\nIl peut vous sembler étrange que tuer des élémentaires me prouve votre valeur, mais la fin, qui est de sauver d'innombrables êtres doués de sensation, justifie les moyens que nous prenons. Vous et moi pouvons nous concentrer sur la préservation de la vie à travers le baume que je peux préparer.\n\n&lt;nom&gt;, il est temps de purifier Gangrebois.", rewards = "Vous recevrez :\n\n"},
[4103] = {title = "Du baume en chassant", objective = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", completion = "Très bien donc, voici vos doses de Baume cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, &lt;nom&gt; ! Où qu'elles soient, utilisez le Baume que je vous ai donné pour les purifier.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4104] = {title = "Du baume par la pioche", objective = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", completion = "Très bien. Voici des doses de baume cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux confectionner de baume.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4105] = {title = "Du baume contre une récolte", objective = "Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé.", description = nil, progress = "Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé.", completion = "Excellent travail, &lt;nom&gt;. Chacune d'elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4106] = {title = "Du baume contre des peaux", objective = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", description = nil, progress = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", completion = "C'est exactement ce dont j'ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et servez-vous-en pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4107] = {title = "Du baume contre des désenchantements", objective = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", description = nil, progress = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", completion = "Voilà quelques doses de Baume végétal cénarien ; il ne manque plus qu'une Essence du néant inférieure, &lt;nom&gt;. Cette essence est de loin l'objet le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4108] = {title = "Du baume en chassant", objective = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", completion = "Très bien donc, voici vos doses de Baume cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, &lt;nom&gt; ! Où qu'elles soient, utilisez le Baume que je vous ai donné pour les purifier.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4109] = {title = "Du baume par la pioche", objective = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", completion = "Très bien. Voici quelques doses de Baume cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux confectionner de baume.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4110] = {title = "Du baume contre une récolte", objective = "Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé.", description = nil, progress = "Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé.", completion = "Excellent travail, &lt;nom&gt;. Chacune d'elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4111] = {title = "Du baume contre des peaux", objective = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", description = nil, progress = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", completion = "C'est exactement ce dont j'ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et servez-vous-en pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4112] = {title = "Du baume contre des désenchantements", objective = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", description = nil, progress = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", completion = "Voilà quelques doses de Baume végétal cénarien ; il ne manque plus qu'une Essence du néant inférieure, &lt;nom&gt;. Cette essence est de loin l'objet le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[4113] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4114] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4115] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4116] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4117] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4118] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4119] = {title = "Dragon nocrturne corrompu", objective = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", description = nil, progress = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", completion = "Vous appliquez quatre doses de Baume cénarien sur le dragon nocturne. La plante commence immédiatement à être purifiée de la corruption qui la ronge, et refleurit jusqu'à devenir une plante vibrante de santé.", rewards = nil},
[4120] = {title = "La force de la corruption", objective = "Talo Thornhoof, à Camp Mojache, dans Feralas, voudrait que vous tuiez 12 Grizzlis de la griffe colérique et 12 Ravageurs Gangrepatte, à Gangrebois.", description = "Etant un chasseur, je m’efforce de bien connaître les forces de mes adversaires. Il est possible de changer le cours d’un combat, juste en connaissant bien son ennemi, <nom>.\n\nDans un lieu nommé Gangrebois, au nord d’Ashenvale, les animaux ont été corrompus par une substance appelée Corruption. Les ours et les loups en sont devenus fous, mais je soupçonne qu’ils ont aussi gagné en force.\n\nAllez, <nom>, voyagez jusqu'à Gangrebois et affrontez ces animaux, voyez par vous-même s’ils sont devenus aussi forts que je le pense.", progress = nil, completion = "A vous entendre, les créatures font preuve d'une férocité peu commune...\n\nRestez sur vos gardes, &lt;nom&gt;. Il est de notre intérêt d'en apprendre plus sur cette corruption. Veillez à toujours connaître votre ennemi.", rewards = "Vous recevrez :\n\n"},
[4121] = {title = "Situation précaire", objective = "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Blackrock, jusqu'à la gorge des Vents brûlants.\n\nRappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.\n\nOn vous demandera également de remettre vos chaînes en thorium à Lexlort.", description = "Croyez-vous réellement que vous parviendrez à rejoindre le point de rendez-vous alors que vous me retenez captif ? Vous pensiez pouvoir pénétrer la Forteresse de Blackrock et y capturer quelqu'un qui a une grande valeur à leurs yeux sans que rien ni personne ne le sache ?\n\nVous allez être <tué/tuée>.", progress = "Je vais m'occuper de ce traître véreux, <nom>.", completion = "Vos actes héroïques ne seront pas oubliés, &lt;nom&gt;. Vous avez gagné ce tribut. Le Chef de guerre va vous parler à présent de la dernière mission.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4122] = {title = "Grark Lorkrub", objective = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock.\n\nUne fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde.\n\nObjet fourni : \n", description = "Je l'ai traqué à travers la gorge des Vents brûlants jusqu'aux Steppes ardentes. Ce traître a été pris la main dans le sac tandis qu'il donnait des informations vitales sur nos opérations au jour le jour. Je parle de Grark Lorkrub.\n\nIl réside à présent dans les Steppes ardentes et vit en toute tranquillité sous leur protection. Ou c'est en tous les cas ce qu'il croit.\n\nPrenez ces chaînes, <nom>. Trouvez Grark, enchaînez-le et ramenez-le par le mont Blackrock. Accomplissez cet exploit et un tribut vous sera remis.", progress = nil, completion = "Ne pouvez-vous pas comprendre le pouvoir que l'on gagne à rejoindre la légion de Blackrock ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4123] = {title = "Le Coeur de la montagne", objective = "Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes.", description = "Je recherche depuis des années une certaine gemme. Elle est appelée le Coeur de la montagne, et elle fait la taille de votre poing. Les nains Sombrefer l'ont enfermée dans leur coffre et j'ai tenté à maintes reprises, sans succès, de la leur acheter.\n\nAussi dois-je recourir à la force.\n\nBattez-vous jusqu'à parvenir à la salle des coffres inférieure des Profondeurs de Blackrock, forcez le coffre secret et emparez-vous du Coeur. Pour ce faire, vous devez tuer la Sentinelle Doomgrip qui n'apparaîtra que lorsque vous aurez ouvert chaque coffret de relique, dans la salle des coffres !\n\nBonne chance.", progress = "Avez-vous le Cœur de la montagne ? Il n'a pas de prix pour moi !", completion = "Vous avez le Cœur ! Incroyable ! Il est encore plus beau que je ne l'imaginais !\n\nJe vous en prie, &lt;nom&gt;, prenez ceci comme paiement.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4124] = {title = "Le messager disparu", objective = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.", description = "L'un de mes associés, Ginro Hearthkindle, cherche à ce qu'on l'assiste dans ses recherches pour retrouver un messager et les paquets qu'il transportait. Cela fait à peu près une semaine que le messager a disparu. Nos propres recherches n'ont abouti à rien et nous sommes à présent dans l'impasse. J'ai malheureusement dû déclarer le messager disparu.\n\nSi vous avez et du temps et des ressources à nous consacrer, veuillez aller parler à Ginro. Il devrait être ici dans la Forteresse. Probablement dans ses quartiers.", progress = nil, completion = "Latro vous envoie, je présume. Bien que je pense qu'il s'agisse d'une cause perdue à présent, j'accepterai toute l'aide que vous voudrez bien apporter. Je dois admettre que je serai heureux de ne plus me préoccuper de cette affaire. Chaque jour je pars pour les terres sauvages de Feralas à la recherche d'indices quant à l'endroit où se trouve Raschal, et chaque soir je reviens les mains presque vides, si ce n'est avec des dents éparses de gnolls et beaucoup de déception.", rewards = "Vous recevrez :\n\n"},
[4125] = {title = "Le messager disparu", objective = "Localiser le bateau du messager quelque part le long de la côte de Feralas.", description = "Cela fait une semaine environ que Raschal, le messager, est parti pour Thalanaar. Il connaît bien Feralas. Il est des nôtres depuis que le général Feathermoon dirige les forces expéditionnaires ici. Je sais qu'il avait prévu de prendre un canot pour descendre la côte et pour tenter de traverser la partie sud de Feralas en évitant les camps de la Horde.\n\nJe n'ai pas pu retrouver son canot, mais peut-être que vous pourriez y parvenir. Peut-être est-il caché. Peut-être a-t-il coulé. Mais en tous les cas, il se peut qu'il contienne des indices quant à l'endroit où se trouve Raschal. Si vous découvrez quoi que ce soit, veuillez m'en faire part.", progress = nil, completion = "Vous avez découvert ce qui s'avère être un canot coulé. A travers les eaux légèrement boueuses, vous apercevez des trous béants à bâbord. Le canot y est presque réduit à sa charpente de bois. Quoi que ce soit qui ait détruit ce canot, on a tenté de le couper en deux. On peut voir les armoiries du bastion de Feathermoon peintes à tribord.\n\nUne lueur métallique dans la vase près du bateau attire votre regard.", rewards = "Vous recevrez :\n\n"},
[4126] = {title = "Hurley Blackbreath", objective = "Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos.", description = "Les nains Sombrefer, dirigés par l'infâme Hurley Blackbreath, ont volé l'une des meilleures compositions des Thunderbrew, la bière Thunderbrew. Les monstres ! Ils ne méritent pas de savourer une telle bière !\n\n<nom>, la tâche que je vais vous confier est ardue. Partez pour les Profondeurs de Blackrock dans les Steppes ardentes et éventrez tous les tonneaux de Thunderbrew que vous trouverez, puis rapportez-moi notre recette !\n\nJe vous en prie, ramenez-la-moi, même si pour cela vous devez mettre à sac les Profondeurs de Blackrock !", progress = "Avez-vous la recette, <nom> ? Je ne peux pas supporter l'idée de savoir les nains Sombrefer sirotant la boisson de ma famille !", completion = "Vous l'avez retrouvée ! Beau travail ! Et j'espère que vous avez mis une bonne trempe à ces nains Sombrefer et à ce Hurley Blackbreath !\n\nLes Thunderbrew sont à votre service, &lt;nom&gt;. Vous êtes le héros des héros.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMasse de frappe rapideTranche-tailleuse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nBière brune naine"},
[4127] = {title = "Débris de bateau", objective = "Retourner au bastion de Feathermoon et montrer à Ginro Hearthkindle le Couteau perdu que vous avez découvert.", description = "Tandis que vous fouillez la vase, vos doigts butent sur le manche d'un couteau. Il semble qu'on en ait pris soin, et il est logique de croire que celui qui était sur le canot l'a perdu. Peut-être que le gros morceau de canot qui manque a quelque chose à voir avec cette perte.\n\nVous récupérez le couteau, vous souvenant que Ginro Hearthkindle vous a demandé de lui ramener au bastion de Feathermoon tous les indices que vous trouveriez. Vous avez l'étrange sentiment cependant que vous n'êtes pas <seul/seule> dans l'eau...", progress = "Ah, soyez de nouveau le bienvenu, <nom>. J'espère que vous avez pu découvrir quelque indice quant à la destinée de Raschal, aussi tragique pourrait-elle être.", completion = "Intéressant… Je pense qu'il s'agit du couteau de Raschal. Vous dites l'avoir découvert au fond de l'eau, près de son bateau ? Hmm, la seule découverte de ce couteau pourrait ne pas suffire à comprendre la raison de la disparition de Raschal. Il nous reste une possibilité peu conventionnelle cependant pour essayer d'en comprendre davantage.\n\nSavez-vous ce qu'est la psychométrie ?", rewards = "Vous recevrez :\n\n"},
[4128] = {title = "Ragnar Thunderbrew", objective = "Parler à Ragnar Thunderbrew.", description = "Hé, <nom>. J'ai entendu dire que Ragnar Thunderbrew était fou furieux parce que quelqu'un lui avait volé sa bière. Il recherche des aventuriers vigoureux, et il est prêt à débourser beaucoup d'argent.\n\nAllez parler à Ragnar si cela vous intéresse. Il se trouve dans la Distillerie Thunderbrew, à Kharanos, dans Dun Morogh.", progress = nil, completion = "Vous pensez que je deviens fou ! On m'a volé ! De l'une des recettes de ma famille ! Comment osent-ils ! Comme si je n'avais pas suffisamment de raisons de détester les nains Sombrefer ! Maintenant, oh… maintenant c'en est assez !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4129] = {title = "Le couteau révélé", objective = "Apporter le Couteau perdu à Quintis Jonespyre au bastion de Feathermoon.", description = "Le druide du Bastion, Quintis Jonespyre, possède des pouvoirs… particuliers. L'un de ces pouvoirs est la psychométrie. C'est à dire qu'il peut révéler l'histoire d'un objet en le touchant. Ne me demandez pas comment il s'y prend. Je le mets sur le compte de magies que je ne connais pas et que je ne veux pas connaître. Il y a deux choses que je sais, par contre. Premièrement, je l'ai vu à l'œuvre et ça marche. Deuxièmement, ce clochard me doit de l'argent.\n\nApportez ce couteau à Quintis là-haut dans sa charmante petite maison, et dites-lui que sa dette de 'L'arnaque' à Kalimdor sera remboursée s'il parvient à tirer quelque chose de ce couteau.", progress = "C'est Giro qui vous envoie, hein ? Mes divinations psychométriques vident l'esprit… mais mes pertes à \"L'arnaque\" de Kalimdor également. Ils me surnomment \"Le Roi de la Guigne\" ici dans la Forteresse. Malheureux au jeu… heureux dans l'art de maîtriser les secrets de la nature, je suppose...\n\nMais passons. Bien entendu que je vais le faire. Nous découvrirons peut-être quelque chose qui nous permettra de comprendre ce qu'il est advenu de Raschal. Si vous voulez bien me donner le couteau, nous allons commencer.", completion = "Merci, &lt;nom&gt;.\n\nBien que la psychométrie soit loin d'être un art exact, je m'en suis servi par le passé pour discerner un peu mieux les situations que d'autres avaient renoncé à comprendre. Je crois qu'utiliser la psychométrie sur le couteau que vous avez découvert pourrait nous fournir un aperçu de ce qui est arrivé à Raschal.\n\nCela ne va prendre qu'un moment, mais ce n'est pas ce que j'appellerais une tâche facile. Supportez ce qui va se dérouler, tout comme moi.", rewards = "Vous recevrez :\n\n"},
[4130] = {title = "La lecture psychométrique", objective = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.", description = "Je me sens encore un peu flageolant, excusez-moi. Mais j'ai reçu quelques visions utilisables.\n\nRaschal sort de son canot deux grands sacs à dos en cuir et pénètre dans les terres ; mais il retourne bientôt au canot cependant. Je vois des cuirs chevelus de gnolls... il a rencontré des gnolls. Je crois que ce sont ceux que l'on appelle Griffebois. Quelque chose l'inquiète, le terrifie presque ! C'est à un point tel qu'il ne remarque pas les élémentaires d'eau qui se forment derrière lui... Les images... s'arrêtent ici.\n\nJ'ai besoin de repos, <nom>. Désolé. Dites à Gin ce que j'ai vu. Il doit savoir.", progress = nil, completion = "Merci de m'informer des visions de Quint, &lt;nom&gt;. J'essaierai de m'en souvenir et de ne pas être trop dur avec lui la prochaine fois que nous jouerons aux cartes.\n\nRaschal se débrouille bien au combat, et ce ne sont pas des gnolls qui l'inquiéteraient, non, le terrifieraient. Mais vous et les vôtres pourriez agir selon ces renseignements et découvrir ce dont nous avons tellement besoin.", rewards = "Vous recevrez :\n\n"},
[4131] = {title = "Les gnolls Griffebois", objective = "Fouiller les Camps des gnolls Griffebois dans la partie sud de Feralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même.", description = "Il se peut que nos \"amis\" les Griffebois aient fini par avoir Raschal après tout, mais quelque chose me dit que ce n'est pas ce qui s'est passé. Ils constituent cependant la première piste à remonter.\n\nJ'aimerais en savoir plus afin de prendre la meilleure décision concernant notre prochaine action, mais tout ce dont je dispose pour l'heure est \"Fouillez les camps de Griffebois - allez-y\". Ce que je sais, c'est que les Griffebois gardent tout ce qu'ils trouvent et se battent entre eux pour les posséder. Ils ont peut-être trouvé les sacs à dos dont parlait Quint. Je n'ai pour l'instant pas pris le risque d'une attaque de front durant les recherches passées, mais avec la vision de Quint à ce propos, je dirais : 'Forcez leurs rangs'.", progress = nil, completion = "Deux grands sacs à dos en cuir sont tenus en place par un arbre proche. Chacun porte sur le devant une petite insigne du bastion de Feathermoon.", rewards = "Vous recevrez :\n\n"},
[4132] = {title = "Opération : Mort à Forgehargne", objective = "Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.", description = "Vous avez accompli un travail exemplaire, <nom>. Il est à présent temps de vous envoyer vers votre dernière mission.\n\nLe général Forgehargne, le responsable Sombrefer qui a coordonné les attaques de la 109e division du C.E.K. et le massacre de masse de nos forces, doit être amené devant la justice.\n\nIl va sans aucun doute s'agir de la mission la plus éprouvante que vous aurez à accomplir, mais si vous la menez à bien, vous serez richement <récompensé/récompensée>.", progress = nil, completion = "Enfin ! Justice a été rendue ! Vous êtes quelqu'un de remarquable, &lt;nom&gt;. Portez ce médaillon comme symbole de votre dévouement inconditionnel envers la Horde et le C.E.K.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMédaillon du Conquérant"},
[4133] = {title = "Vivian Lagrave", objective = "Parler à la maîtresse des ombres Vivian Lagrave à Kargath.", description = "La maîtresse des ombres Vivian Lagrave a besoin de vos services. Elle se trouve dans les Terres ingrates, à l'avant-poste orc de Kargath, et collecte les rumeurs courant sur une bière faite par les nains Sombrefer des Profondeurs de Blackrock.\n\nAllez lui parler. Elle vous attend.", progress = nil, completion = "Je vous remercie d'être venu, &lt;nom&gt;. L'austérité de cet endroit dégage un certain charme, mais les aménagements de l'Apothicarium lui font toutefois défaut.\n\nMais assez de politesses. Parlons devoir, d'accord ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4134] = {title = "La recette perdue de Thunderbrew", objective = "Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath.", description = "On raconte que le nain Hurley Blackbreath des Sombrefer a dérobé une recette de bière. Cette bière, la Thunderbrew, insufflerait un grand courage et une grande force à celui qui la boit. Nous souhaitons étudier cette boisson. Nous trouverons peut-être d'autres usages à ses vertus... Des usages plus en phase avec les objectifs des Réprouvés.\n\nAllez fouiller dans les Profondeurs de Blackrock, trouvez Hurley, arrachez-lui la recette de la bière Thunderbrew et rapportez-la moi.\n\nPour le retrouver, il vous faudra sans doute aller jusqu’à menacer sa précieuse bière.", progress = "Avez-vous la recette de la Thunderbrew, <nom> ?", completion = "Très bien. Je vais envoyer cette recette chez l'Apothicaire afin qu'elle y soit étudiée. Et nous percerons ses mystères un jour. Il se peut que dans le futur, les nains de l'Alliance voient les vertus de cette boisson se retourner contre eux !\n\nJe trouve cela terriblement amusant. Peut-être que la mort influence le sens de l'humour de chacun... Qu'en pensez-vous ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMasse de frappe rapideTranche-tailleuse\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nPotion de soins excellentePotion de mana supérieure"},
[4135] = {title = "Le Gouffre grouillant", objective = "À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois.\n\nObjet fourni : \n", description = "À l'intérieur des sacs à dos se trouvent deux objets : le premier est un paquet qui était destiné à Thalanaar, et le second est un message écrit à la hâte et dont le destinataire reste inconnu.\n\nLe message raconte la découverte de créatures insidieuses et ressemblant à des insectes au sud des camps des gnolls Griffebois, dans un endroit appelé le Gouffre grouillant. L'auteur a jugé bon d'y aller en personne, comme s'il s'agissait d'un réel danger pour tout Feralas. Le message est signé \"Raschal de Feathermoon\".\n\nIl semblerait que vous ayez découvert la dernière destination de Raschal.", progress = nil, completion = "Vous avez découvert une grande alvéole de nature étrangère. La texture de cette alvéole est muqueuse, bien que de dures saillies en surgissent çà et là. L'alvéole est d'une taille telle qu'elle pourrait aisément contenir un humain… et d'après les formes qui se dessinent à travers sa surface, vous présumez que c'est précisément ce qu'elle renferme...", rewards = "Vous recevrez :\n\n"},
[4136] = {title = "Ribbly Screwspigot", objective = "Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes.", description = "Mon frère Ribbly a toujours été une sangsue pour ma famille, en prenant son argent et en le gâchant dans des projets tous plus stériles les uns que les autres.\n\nEn tous les cas, je pense que son dernier projet est le pire d'entre eux, car le baron Revilgaz de Baie-du-Butin a mis à prix la tête de notre pauvre Ribbly. Il m'est impossible de vous dire à quel point cela ravit les Screwspigot ! Notre petit Ribbly vaut finalement quelque chose !\n\nMais maintenant il se cache, quelque part dans les Profondeurs de Blackrock. Je vous en prie, trouvez-le et apportez-le-moi.\n\nOu, s'il n'est pas enclin à vous suivre, ce n'est pas bien grave. Je saurai me contenter de sa tête.", progress = "Avez-vous Ribbly ? Ou du moins l'un de ses morceaux ?", completion = "Ha ! Vous l'avez trouvé ! Et… il semblerait que mon petit frère n'ait pas voulu vous suivre gentiment. Quel dommage ! J'aurais aimé voir son regard lorsque je lui aurais dit que nous comptions le remettre à Revilgaz.\n\nMerci, &lt;nom&gt;. Vous faites la joie de ma famille. Et Ribbly n'a jamais eu l'air aussi serein.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de rancuneSpallières de pénitenceArmure d'acier éclissé\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4141] = {title = "Muigin et Larion", objective = "Récolter 15 Pétales-de-sang et retourner voir Muigin.", description = "Vous voyez Larion là-bas ? C'est SA faute si nous en sommes là !\n\nJe lui avais bien dit que nous nous trompions de chemin, mais il n’a rien voulu entendre. Et me croiriez-vous si je vous disais que c'est lui qui ne veut plus m'adresser la parole ? Mais passons, et amusons-nous un peu avec lui le temps qu'il change d'avis.\n\nAvez-vous remarqué les étranges créatures en forme de plantes dans les environs ? Ce sont des nuisances, mais je pense qu'après un entraînement approprié, je pourrais les faire obéir à des ordres.\n\nMais avant toute chose, j'aurais besoin d'étudier des spécimens. Pensez-vous pouvoir en prélever quelques-uns ?", progress = "Larion va recevoir de la visite dans pas longtemps, ça c'est sûr !", completion = "J'espère qu'elles ne vous ont pas trop posé de problèmes, &lt;nom&gt;. Pour ma part, j’essaie de les éviter – elles sont sauvages !\n\nJ'ai tenté de sauter par-dessus l'une d'elles… et elle a attaqué ! Ce n’est pas un comportement normal pour des plantes !", rewards = "Vous recevrez :\n\n"},
[4142] = {title = "Visite à Gregan", objective = "Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas.", description = "Je ne sais vraiment pas quoi en faire, <nom>. Il semblerait que ces plantes aient un soupçon d'intelligence.\n\nJe manque de connaissances dans ce domaine, mais je connais un expert !\n\nAllez au nord de Feralas et cherchez l'un de mes amis, Gregan Brewspewer. C'est un maître en la matière.\n\nJe suis sûr qu’il peut nous aider. Vous le trouverez dans les régions sauvages... Il n'est pas du genre à habiter une grande ville.", progress = "Je vis ici, dans la forêt… C'est tellement paisible.\n\nDu moins je croyais que ça le serait. J’ai reçu plus de visiteurs depuis que je vis ici que du temps où j’habitais Ironforge !", completion = "Une Pétale-de-sang, hein ? Hmm… Bien, expliquez-moi simplement vos projets et je vous dirai si je peux ou non vous aider.", rewards = "Vous recevrez :\n\n"},
[4143] = {title = "Brouillard maléfique", objective = "Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro.", description = "Pour tout vous dire, <nom>, je n'ai jamais vu de plantes pareilles au cours de mes voyages. Peut-être devrais-je aller visiter ce cratère…\n\nQuoiqu'il en soit, je pense savoir exactement ce que cherche Muigin : de la brume atal'ai. C'est tout à fait immonde, et difficile à récolter, mais c'est juste ce dont il a besoin pour contrôler les petits monstres.\n\nIl vous faudra aller au temple d'Atal'Hakkar dans le marais des Chagrins. Vous pourrez trouver de la brume atal'ai auprès de rôdeurs des abysses, de vers des boues ou de limons qui résident en ces lieux. Bonne chance, <nom> !", progress = "Larion ne veut toujours pas me parler ! Il sait comment cultiver la rancune…", completion = "J’ai quelque hésitation à toucher cette chose, &lt;nom&gt; ! Mais si Gregan affirme que ça va marcher, je veux bien essayer !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4144] = {title = "Les pousses de Pétales-de-sang", objective = "Voici ce que nous allons faire, <nom>. Procurez-vous des pousses de Pétales-de-sang. De jeunes plantes, pas encore parvenues au stade adulte, vous comprenez ? Puis apportez-les ici. Alors je verrai ce dont la brume atal'ai est capable.\n\nVous pourriez penser que c'est le désir de vengeance qui me guide, mais… vous auriez raison…\n\nEn vérité, je connais le chemin pour nous sortir d'ici, mais tant que Larion n'admet pas que j'ai raison, je ne bouge pas !\n\nC'est assez : partez et trouvez des pousses de Pétales-de-sang afin que nous nous amusions un peu !", description = nil, progress = "Voici ce que nous allons faire, <nom>. Procurez-vous des pousses de Pétales-de-sang. De jeunes plantes, pas encore parvenues au stade adulte, vous comprenez ? Puis apportez-les ici. Alors je verrai ce dont la brume atal'ai est capable.\n\nVous pourriez penser que c'est le désir de vengeance qui me guide, mais… vous auriez raison…\n\nEn vérité, je connais le chemin pour nous sortir d'ici, mais tant que Larion n'admet pas que j'ai raison, je ne bouge pas !\n\nC'est assez : partez et trouvez des pousses de Pétales-de-sang afin que nous nous amusions un peu !", completion = "Et voilà, &lt;nom&gt; ! Cela va occuper Larion !", rewards = "Vous recevrez :\n\n"},
[4145] = {title = "Larion et Muigin", objective = "Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal.", description = "Vous voyez Muigin ? C’est de SA faute si nous sommes perdus !\n\nJe connaissais le chemin, cet idiot a insisté pour nous montrer son raccourci et nous voilà ici !\n\nPour ne rien arranger, il a envoyé ses parasites qui m’importunent. Je suis dans un tel état de fureur qu’il risque de se passer du temps avant que je ne lui adresse de nouveau la parole, mais il faut trouver une solution à ces parasites qui sont insupportables.\n\nEssayons d’en réduire le nombre : allez donc chasser quelques Pétales-de-sang, puis revenez me voir.", progress = nil, completion = "Merci pour votre aide, &lt;nom&gt;, mais j'ai bien peur d’avoir de mauvaises nouvelles…", rewards = "Vous recevrez :\n\n"},
[4146] = {title = "Carburant de baguette", objective = "Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal.", description = "C'est votre jour de chance, <nom> ! J'étais justement en train de travailler à quelques-unes de mes inventions pendant que Marvon est absent, et l'une d'entre elles est une baguette à bestioles. Avec quelques ajustements, elle devrait faire l'affaire pour vous débarrasser de ces parasites Pétales-de-sang.\n\nJe veux bien vous prêter l'un de mes prototypes de baguette, mais il faut encore que vous vous procuriez son combustible. Vous trouverez la brume atal'ai nécessaire pour que la baguette fonctionne dans le temple d'Atal'Hakkar. Vous devrez la récolter auprès de rôdeurs des abysses, de vers des boues ou de limons.", progress = "C'est épuisant, <nom>. Ces choses ne me laisseront jamais en paix !", completion = "Ainsi Marvon n'était pas dans les parages ? Bien, montrez-moi quand même ce que vous avez.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4147] = {title = "Atelier de Marvon", objective = "Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet.", description = "J’ai espionné les faits et gestes de Muigin, et j'ai découvert qu'il cultivait ces horreurs !\n\nJe crois que la seule chose à faire est… Non, pas d'aller lui parler… où avez-vous donc la tête ? Non, la seule solution est la riposte !\n\nNous allons demander l’aide d’un de mes amis, Marvon, qui a un atelier à Ratchet. Je suis sûr qu'il pourra concevoir une sorte de gadget pour nous tirer de ce mauvais pas.", progress = nil, completion = "Marvon est parti depuis longtemps déjà, &lt;nom&gt;. Il s'est rendu en Tanaris pour étudier d’anciennes ruines trolls.\n\nMais de quoi avez-vous besoin ?", rewards = "Vous recevrez :\n\n"},
[4148] = {title = "La baguette Pétale-de-sang", objective = "Pour faire fonctionner la baguette, nous avons besoin d'un spécimen de ses futures victimes. Rendez-vous dans le cratère et rapportez une pousse de Pétale-de-sang. Je pourrai alors régler l’appareil pour qu'il prenne soin des petits camarades de Muigin…\n\nS'il n'était pas si obstiné, nous serions déjà sur le chemin du retour… En attendant, je ne peux que lui montrer que ses gamineries ne me perturbent aucunement…", description = nil, progress = "Pour faire fonctionner la baguette, nous avons besoin d'un spécimen de ses futures victimes. Rendez-vous dans le cratère et rapportez une pousse de Pétale-de-sang. Je pourrai alors régler l’appareil pour qu'il prenne soin des petits camarades de Muigin…\n\nS'il n'était pas si obstiné, nous serions déjà sur le chemin du retour… En attendant, je ne peux que lui montrer que ses gamineries ne me perturbent aucunement…", completion = "Il semble que cela va fonctionner, &lt;nom&gt;. À présent, rappelez-vous de ceci : si vous voyez la moindre de ces pestes aux alentours, n'hésitez pas à utiliser cette baguette !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBaguette Pétale-de-sang"},
[4161] = {title = "Une recette kaldorei", objective = "Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar.", description = "Autrefois, les elfes de la nuit s’appelaient les kaldorei, ce qui veut dire \"les enfants des étoiles\". La connaissance du passé est une étape importante de votre cheminement de <classe>, <nom>, aussi écoutez attentivement ce que je vais vous dire.\n\nLes kaldorei ont toujours été très fiers de la relation harmonieuse qu'ils entretiennent avec la nature. Cela implique que nous ne prélevons chez elle que le nécessaire et que nous le restituons toujours. Cet équilibre nous est très bénéfique, <nom>.\n\nÀ présent sortez et prélevez sept petites pattes d'araignées – pas plus – puis revenez me voir.", progress = "Rappelez-vous l'équilibre, <nom>. Je souhaiterais que vous développiez une compréhension et une grande empathie pour les forêts.", completion = "N’oubliez jamais ce que je vous ai appris en ce jour, &lt;nom&gt;. Vous-même faites partie de cet équilibre que les elfes de la nuit s’évertuent à préserver, même durant les époques troublées.", rewards = "Vous recevrez :\n\nRecette : Kébab d'araignée kaldoreiKébab d'araignée kaldorei"},
[4181] = {title = "Ingénierie des gobelins", objective = "Apporter le Manuel d'ingénierie à Nixx Sprocketspring à Gadgetzan si vous souhaitez en apprendre davantage sur l'ingénierie gobeline.", description = "La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. Je ne mentionne l'ingénierie gobeline que par souci d’objectivité. Ces gens-là aiment concevoir des choses qui explosent, en se souciant rarement de ce qui se trouve alentour, et même pas d'eux.\n\nLisez ce manuel, <nom>. Si vous voulez apprendre à vous faire sauter le caisson, alors apportez-le à Nixx Sprocketspring à Gadgetzan. Et n’oubliez pas : l'adhésion à l'une de ces disciplines est irrévocable. Choisir telle discipline aujourd’hui interdit de changer d’avis par la suite. Aussi réfléchissez bien avant d'accomplir cette tâche.", progress = "Je peux sentir les recrues potentielles comme je le fais d’une poudre explosive de première qualité : à des kilomètres ! Êtes-vous venu pour étudier les arcanes de l'explosion ?", completion = "Bien &lt;nom&gt;, vous avez été avisé de choisir mon enseignement ! N'importe quel balourd peut devenir expert en ingénierie : les gnomes et leurs maisons irradiées de Gnomeregan en sont la preuve. Mais il faut un esprit fort et une main stable (accent sur STABLE) pour maîtriser la discipline d'ingénierie des gobelins.\n\nOuvrez vos oreilles, &lt;nom&gt;, et vous pourrez apprendre beaucoup.", rewards = "Vous recevrez :\n\n"},
[4182] = {title = "La menace des draconiens", objective = "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie.", description = "La vie, dans les Steppes ardentes, est émaillée de conflits.\n\nRegardez cet endroit ! Nous ne savons que très peu de choses à propos de ce qui est arrivé à ces bâtiments, mais ce que nous savons, c'est qu’avant la grande explosion, cet endroit faisait partie de la chaîne des Carmines.\n\nMais point de lamentations ! Nous avons un problème, <nom>. Il se peut que vous ayez remarqué les draconiens sous la crête. Nous avons besoin d’aide pour les repousser. Tuez-en autant que vous pourrez puis revenez me voir. Réussissez cette mission et nous pourrons parler d'autres sujets.", progress = nil, completion = "Magnifique boucherie, &lt;nom&gt;. Maintenant que nous vous savons capable d’agir convenablement face aux draconiens, nous pouvons parler de sujets plus urgents.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4183] = {title = "Les véritables maîtres", objective = "Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon.", description = "Nous avons toujours cru que le caractère des orcs Blackrock était la conséquence de leur éducation brutale. Mais ce que nous avons découvert dans leur terre natale raconte une tout autre histoire.\n\nEffectivement, la soif du sang et des conflits les domine, mais ce sont les dragons noirs qui contrôlent les orcs Blackrock. Nous soupçonnons que ce sont eux qui les abreuvent de colère et d'agressivité.\n\nApportez cette lettre au Magistrat Solomon. Il saura quoi faire.\n\n<Helendis vous remet une lettre scellée.>", progress = "Salutations, <nom>. Nous sommes-nous déjà rencontrés ? J'ai l'impression de vous connaître.", completion = "&lt;Le Magistrat Solomon ouvre la lettre scellée de Helendis et commence à la lire.&gt;", rewards = "Vous recevrez :\n\n"},
[4184] = {title = "Les véritables maîtres", objective = "Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.\n\nBolvar demeure dans le Donjon de Stormwind.", description = "Voilà de bien sombres nouvelles, <nom>. Découvrir que nos ennemis mortels ne sont que des pions entre les mains d'une menace plus importante encore est décourageant. Je ne vois pas comment Lakeshire pourrait survivre à une attaque menée à la fois par les orcs Blackrock et par les dragons noirs ? Si Lakeshire devait succomber à ce danger, Darkshire le suivrait de près. Et ensuite ? Goldshire ? Stormwind elle-même ?\n\nVous devez immédiatement mettre au courant de la situation le généralissime Bolvar Fordragon, à Stormwind ! Si cela ne mérite pas l'intervention de Stormwind, rien ne le fera et tout sera perdu.", progress = "Qu'est-ce qui vous amène au Donjon de Stormwind ?", completion = "Des dragons ? Impossible !", rewards = "Vous recevrez :\n\n"},
[4185] = {title = "Les véritables maîtres", objective = "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor.", description = "Solomon dépeint une situation bien lugubre. Cependant nous ne pouvons pas nous permettre d'envoyer nos maigres troupes aider Lakeshire sur la base d'une simple spéculation. J'ai besoin de preuves avant de pouvoir agir.\n\nParlez à dame Prestor, <nom>. C'est une érudite qui en connaît beaucoup sur les dragons et les draconiens. Il est possible qu'elle soit en mesure d'apporter quelque lumière sur cette situation.", progress = "<Bolvar vous regarde avec une vive attention.>", completion = "&lt;Bolvar plonge sa tête entre ses mains, comme s'il réfléchissait profondément.&gt;\n\nBien que je respecte la position de dame Prestor, je crois qu’il y a une solution à ce dilemme qui pourrait dissiper toutes nos inquiétudes.", rewards = "Vous recevrez :\n\n"},
[4186] = {title = "Les véritables maîtres", objective = "Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire.", description = "<nom>, je vais vous nommer <Adjoint suppléant/Adjointe suppléante> de Stormwind.\n\nRetournez voir le Magistrat Solomon au Lakeshire et remettez-lui ce décret.", progress = "Des nouvelles de Bolvar ?", completion = "Cela aurait pu être pire, je suppose…\n\n&lt;Le magistrat Solomon vous regarde attentivement.&gt;\n\nIl semblerait que le sort de Lakeshire repose entièrement sur vos épaules.\n\n&lt;Vous remarquez que le magistrat Solomon cligne rapidement des yeux. Il a l'air de pleurer.&gt;", rewards = "Vous recevrez :\n\n"},
[4201] = {title = "Le philtre d'amour", objective = "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock.", description = "Ah, les affres de l'amour ! Le soldat Rocknot, insensible à mes charmes, m'a éconduite ! J'en suis folle !\n\nVous devez m'aider ! Nous autres succubes en savons beaucoup sur l'amour, et je peux concocter une potion qui abattra les murs de fer autour du cœur de Rocknot. Pour cela, j'ai besoin des ingrédients suivants : de la gromsang, des veines d'argent de géant des falaises et de l'eau provenant des sources de Golakka dans le cratère d'Un'Goro. Ce flacon vous servira à recueillir l'eau.\n\nJe vous en prie, <nom>, venez en aide à une pauvre âme dans sa quête de félicité !", progress = "Avez-vous les ingrédients ? La brèche de mon cœur menace de m'engloutir tout entière !", completion = "Oh, vous avez réussi ! À présent je peux préparer ma potion et m'en servir sur Rocknot. Il va enfin succomber à mes charmes !\n\nMerci, &lt;nom&gt;. Vous êtes un champion de l'amour !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBracelets de prisonnierCeinture de Nagmara\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4221] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4222] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4223] = {title = "Les véritables maîtres", objective = "Parler au maréchal Maxwell dans les Steppes ardentes.", description = "< Le Magistrat Solomon soupire. > \n\nVous devez retourner dans les Steppes ardentes, <nom>. En tant qu’Adjoint de Stormwind, votre présence est exigée pour faire votre rapport au maréchal Maxwell. Bonne chance !", progress = nil, completion = "&lt;Le maréchal Maxwell éclate de rire.&gt;", rewards = "Vous recevrez :\n\n"},
[4224] = {title = "Les véritables maîtres", objective = "Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.\n\nVous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord.", description = "Quoi ? Vous pensiez être <le premier/la première> ? Combien devons-nous perdre de soldats pour que Stormwind agisse ?\n\nNous avions accumulé beaucoup d’informations concernant la menace Blackrock avant de perdre notre officier commandant, le maréchal Windsor. En même temps que lui, nous avons perdu tous ces précieux renseignements.\n\nNous avons besoin de ces informations. Parlez à John le Loqueteux, <nom>. Il se trouvait avec Windsor lorsqu'ils ont été attaqués par un groupe de Blackrock. On l'a vu pour la dernière fois dans une grotte, au nord.", progress = "Avez-vous parlé à John ?", completion = "J'aurais pu vous prévenir, mais cela n'aurait pas été amusant, n'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[4241] = {title = "Maréchal Windsor", objective = "Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor.\n\nVous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison.", description = "Ainsi ce bon à rien de lâche dit que Windsor est vivant, hein ?\n\nPréparez-vous, <Adjoint/Adjointe>, vous allez le chercher. Si Windsor est en vie, vous devez me l'amener. S'il est mort, j'en veux la preuve.\n\n<Maxwell se met à rire.>\n\nJe suppose que vous commencez à en avoir assez d'entendre cela, n'est-ce pas ?", progress = nil, completion = "Où est-il ? Je vais le massacrer !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4242] = {title = "Espoir abandonné", objective = "Donner les mauvaises nouvelles au maréchal Maxwell.", description = "Bolvar est un imbécile. J'étais en train de collecter la \"preuve\" à laquelle il tenait tant, pour pouvoir lui fourrer au fin fond de la gorge.\n\nCe n'est qu'un bouffon aveugle. La preuve est sous ses propres yeux et il ne la voit pas.\n\nQuant à mes renseignements, ils sont perdus. Partis. Impossible de les récupérer.\n\nSi j’arrive à trouver Hostefer et si je parviens à sortir de son labyrinthe, mon premier geste sera de planter mon marteau entre les yeux de ce reptile.\n\nLaissez-moi à présent, <nom> !", progress = nil, completion = "Apparemment, il est devenu fou.\n\n&lt;Maxwell baisse la tête en signe de chagrin.&gt;\n\nIl est malheureux qu'un guerrier autrefois noble et fier soit devenu un tel crétin. Je SUPPOSE que nous sommes à présent dans l'impasse…\n\nJe dois vous récompenser pour vos efforts, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHeaume de conservateurBottillons renforcésJambières de Windshear\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4243] = {title = "À la poursuite d'A-mi 01", objective = "Trouver A-mi 01 dans le Cratère d'Un'Goro.", description = "Il est malheureusement arrivé quelque chose à l'une de mes plus grandes inventions. Vous avez déjà vu des écureuils mécaniques, pas vrai ? Eh bien, afin de m'approcher des singes du cratère d’Un'Goro et de me mêler à eux, j'ai créé un singe mécanique. Elle se nomme A-mi 01.\n\nElle a des gemmes de divination à la place des yeux, ainsi je peux voir tout ce qu'elle voit. Elle est parvenue jusqu'au Rocher fongique, le repaire des singes, un peu à l'est d'ici, et c'est là que j'ai perdu le contact. La dernière chose que j'ai vue est l'un des mâles alpha se ruer vers elle pour lui dire bonjour !\n\nPouvez-vous m'aider à la retrouver ?", progress = nil, completion = "Tandis que vous observez A-mi 01, vous remarquez deux énormes bosses qui enlaidissent ce que Karna considère évidemment comme une pièce majeure d'ingénierie. La première déforme l'épaule de A-mi 01, et l'autre défigure sa tête.\n\nUn examen plus poussé vous informe qu'aucune énergie ne parcourt ses composants.", rewards = "Vous recevrez :\n\n"},
[4244] = {title = "À la poursuite d'A-mi 01", objective = "Trouver une Caisse en mithril et retourner près de A-mi 01 dans le Cratère d'Un'Goro.", description = "Une recherche plus poussée dévoile un panneau coulissant. On peut lire, clairement écrit au-dessus d'un groupe de fils : \"Remplacer la Caisse de mithril et mettre le contact sur Off puis sur On.\"\n\nTandis que vous faites coulisser le panneau pour le refermer, vous vous demandez s'il sera aussi simple de réparer A-mi 01 et de la ramener à Karna Remtravel près du refuge des Marshal.\n\nSeule une tentative vous le dira.", progress = "Le panneau sous lequel placer la Caisse en mithril est toujours fermé. A-mi 01 est toujours inerte.", completion = "Vous faites à nouveau coulisser le panneau de A-mi 01 et vous ôtez délicatement l'ancienne caisse en mithril qui semble déchargée. La nouvelle trouve facilement sa place. La seule chose à faire à présent, si tant est que le problème vienne bien de la caisse en mithril, est de placer l'interrupteur sur la position Off, puis de le basculer sur la position On.", rewards = "Vous recevrez :\n\n"},
[4245] = {title = "À la poursuite d'A-mi 01", objective = "Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Remtravel dans le Cratère d'Un'Goro.", description = "Tout en vérifiant que vous pourrez bien ramener A-mi à Karna Remtravel, vous placez l'interrupteur en position Off. Tandis que vous scrutez les alentours pour vous assurer qu'aucun gorille ne survient, vous vous préparez à voir le résultat du passage de l'interrupteur sur la position On.\n\nC'est votre dernière chance… Êtes-vous <sûr/sûre> que c'est bien ce que vous voulez faire ?", progress = nil, completion = "Oh ! Vous avez réussi ! Merveilleux ! Merci, &lt;nom&gt;.\n\nOh non ! Regardez-moi ces bosses. On va la réparer et la remettre en parfait état de marche en deux temps trois mouvements.\n\nMerci encore, &lt;nom&gt;. J'apprécie réellement ce que vous avez fait.", rewards = "Vous recevrez :\n\n"},
[4261] = {title = "Esprit d'un ancien", objective = "Escorter Arei jusqu’à un lieu sûr, puis parler à Kayneth Stillwind au Chant des forêts, dans l’est d'Ashenvale.", description = "Gangrebois était autrefois une terre paisible et sereine… jusqu'à l’arrivée de la Légion. Les infernaux, la destruction, le chaos…\n\nLe crâne de Gul'dan s'est assuré que personne ne soit épargné, ici. Tous succombèrent à la corruption.\n\nMême à présent, en tant qu'esprit, je me sens emprisonné, et j'ai le sentiment de porter toute la souffrance de cette terre. Aidez-moi à rentrer chez moi. Je vous en prie, <nom>, dites-moi que vous mènerez un esprit ancien hors de cet endroit, pour que je puisse enfin trouver le repos.\n\nQuand je serai libre, cherchez un druide du nom de Kayneth Stillwind, qui réside au Chant des forêts, à l'est.", progress = nil, completion = "Oui, &lt;nom&gt;. Gangrebois a connu bien des épreuves. Merci pour ce que vous avez fait.\n\nUn jour, peut-être, nous serons capables de reconquérir Gangrebois. Chaque action généreuse nous est d'un grand secours.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape des brumes éthéréesMantelet des nuages\n\nVous recevrez également :\n\n"},
[4262] = {title = "Grand seigneur Pyron", objective = "Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig.\n\nJalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?", description = "Les cinq derniers mages qui sont allés fureter près du mont Blackrock sont revenus rôtis à point ou dans un état pire.\n\n<Jalinda ramasse des cendres sur le sol et les lance en l'air.>\n\nL'un de ces monstres en particulier, le Grand seigneur Pyron, nous pose pas mal de problèmes. Nous devons éradiquer cet élémentaire pour que notre groupe puisse se rendre dans les Profondeurs de Blackrock.\n\nIl garde l'entrée de la carrière de Blackrock.", progress = nil, completion = "Incendius ? Oh non !…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4263] = {title = "Incendius !", objective = "Trouver le Seigneur Incendius dans les Profondeurs de Blackrock et le détruire !", description = "Êtes-vous <certain/certaine> que Pyron a prononcé “Incendius“ avant de mourir ?\n\n<La gorge de Jalinda se serre.>\n\nLe Seigneur Incendius est un envoyé de Ragnaros ! Oh non, non ! Qu'allons-nous faire ?\n\nPensez-vous pouvoir mener à bien une autre mission ? Je n'ai personne d'autre à envoyer, <nom> !\n\nNous ne parviendrons jamais à y placer une équipe si Incendius continue à faire renaître Pyron de ses cendres.\n\nVous devez trouver le Seigneur Incendius et le détruire !", progress = nil, completion = "Non ! Êtes-vous sûr qu'Incendius a dit “Ragnaros“ ?\n\n&lt;Jalinda vous remet quelque chose et flatte votre poignet de la main tandis qu'elle plonge profondément dans ses pensées.&gt;", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape de l'hélionauteGants crépusculairesBrassards de démon des cryptesEtreinte loyale\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4264] = {title = "Une Note chiffonnée", objective = "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…", description = "Toute la note est couverte de taches. Le texte est difficile à lire, mais vous parvenez à en déchiffrer certaines parties :\n\n… douce ironie…\n\n… la chute de l'Alliance brisée…\n\n… sans l'aide assidue du général Forgehargne, nous n’aurions peut-être jamais découvert la structure du code…\n\n… Argelmach en a presque terminé avec le décodage des notes de Windsor.\n\nNotre Seigneur s'élèvera des profondeurs et écrasera quiconque subsistera…\n\nEmpereur Dagran Thaurissan.", progress = "<Le maréchal Windsor regarde la note que vous tenez à la main.>\n\nMais qu'avez-vous donc là, <nom> ?", completion = "&lt;Le maréchal Windsor attrape la note et commence à la lire.&gt;", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4265] = {title = "L'évasion de la ruche", objective = "Libérer Raschal de la ruche de Zukk'ash.\n\nRevenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf.", description = "L'alvéole, alors que vous la touchez, s'entrouvre et révèle un elfe de la nuit - en vie, ce qui est étonnant. Il semble en bonne santé, bien qu'il soit inconscient. Tandis que vous essayez de le dégager de l'alvéole, il revient à lui.\n\n\"Qu'Elune soit louée, vous m'avez sauvé, mon <ami/amie> ! Je… je suis Raschal, et je me suis réveillé dans cette alvéole après avoir été capturé par ces insectes. Ce sont les gens du bastion qui vous envoient ?\"\n\nOn dirait que vous avez retrouvé le messager disparu !", progress = nil, completion = "Soyez le bienvenu chez vous, &lt;nom&gt;. Raschal est arrivé il y a quelques instants et m'a tout raconté.\n\nJe… non, toute la Forteresse vous exprime sa gratitude et ses remerciements pour votre action exceptionnelle. Sans vous, Raschal serait mort, et vous lui avez porté assistance sans contrepartie. Vous avez l'étoffe d'un authentique héros. Sachez que vous avez trouvé un ami en Ginro Hearthkindle.", rewards = "Vous recevrez :\n\n"},
[4266] = {title = "Accueil d'un héros", objective = "Parler à Shandris Feathermoon dans le bastion de Feathermoon.", description = "<nom>, le général Shandris Feathermoon voudrait vous parler en personne. Elle veut vous remercier pour les services rendus au bastion, mais je crois savoir qu'elle souhaite également vous entretenir des créatures insectoïdes que vous et Raschal avez combattues dans le sud de Feralas. Ce que nous avons entendu de ces insectes Zukk'ash est… effrayant, c'est le moins que l'on puisse dire.\n\nLe général Feathermoon vous attend dans la base principale.", progress = nil, completion = "&lt;nom&gt;, je vous remercie chaleureusement pour l'aide que vous nous avez apportée. Votre bravoure face à des forces insurmontables vous vaudrait une récompense d'une valeur mille fois supérieure, mais j'espère néanmoins que vous accepterez ceci, offert au nom de toute la Forteresse.\n\nÀ présent, si je puis me permettre, j'aimerais solliciter votre aide une fois encore. À la lumière de la découverte de la ruche de Zukk'ash ici en Feralas, je crois que vous êtes la bonne personne pour cette mission.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de cérémonie elfiqueBâtonnet sanctifié\n\nVous recevrez également :\n\n"},
[4267] = {title = "L'ascension des silithides", objective = "Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus.", description = "Je vous confie une copie du rapport de Raschal concernant l'infestation du sud de Feralas. Bien que le rapport original soit envoyé à Darnassus, je veux que vous remettiez cette copie à une associée du Protectorat. Elle se nomme Gracina Spiritmight. C'est une prêtresse qui réside au temple de la Lune à Darnassus. Elle possède une vaste connaissance de ce genre de créatures, et lui confier ce rapport profitera à tous.\n\nVous pouvez partir. Bonne chance, <nom>. Puisse Elune veiller sur nous tous.", progress = "Soyez le bienvenu en ce temple béni, mon ami. J'avais prédit que vous viendriez du bastion de Feathermoon. Avez-vous le rapport que Shandris Feathermoon vous a demandé d'apporter ?", completion = "Nous autres elfes de la nuit connaissons la terreur décrite dans ce rapport. La sagesse a guidé Shandris dans sa décision de m'envoyer ce rapport et vous-même.\n\nCes créatures vont rapidement consumer Feralas. Elles sont le plus grand danger auquel nous ferons jamais face. Ces insectes sont connus sous le nom de silithides. Ce ne sont que les instruments d’une des plus grandes menaces que l'Alliance et la Horde réunies combattront jamais.\n\nJe prie pour que nous ayons assez de résolution pour les battre avant qu'ils ne nous détruisent.", rewards = "Vous recevrez :\n\n"},
[4281] = {title = "La livraison à Thalanaar", objective = "Apporter le Vieux colis à Falfindel Waywarder, à Thalanaar.", description = "Le colis que vous avez trouvé au camp des gnolls Griffebois devait être livré au petit poste de Thalanaar, dans la région sud-est de Feralas. Malgré la disparition du messager, le colis doit être livré.\n\nEn l’examinant de près, on peut lire sur le côté, écrit à la main : \"Falfindel Waywarder\". Peut-être s'agit-il du destinataire ?", progress = "Bienvenue à Thalanaar, <classe>. En quoi puis-je vous aider ?", completion = "Elune soit louée, la livraison du bastion de Feathermoon est enfin arrivée !\n\nVotre présence ici signifie qu'il est peut-être arrivé malheur à Raschal, notre messager habituel. J'espère que tout finira bien. Je sais que, récemment, quelque chose situé au sud des Griffebois les a profondément perturbés. Peut-être les bêtes sauvages ont-elles eu raison de lui ? À votre place, je serais prudent, mon ami.\n\nMais passons, je vous remercie encore. Voici votre paiement pour avoir livré ce colis.", rewards = "Vous recevrez :\n\n"},
[4282] = {title = "Un espoir en lambeaux", objective = "Rapporter les Renseignements perdus du maréchal Windsor.\n\nLe maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne.", description = "<Le maréchal Windsor agite la note avec enthousiasme.>\n\nEst-ce que vous réalisez ce que cela veut dire, <nom> ?\n\nPeut-être que tout n'est pas perdu ! D'après ce que je peux comprendre, les renseignements sont en ce moment même détenus par deux nains Sombrefer : le général Forgehargne et le Seigneur des golem Argelmach. Je ne crois pas qu'ils nous les donneront même si on leur demande poliment.\n\nJ'espère que vous êtes <prêt/prête> à combattre.\n\nAllez-y, trouvez ces deux scélérats et rapportez-moi ces renseignements.", progress = "Ce grand subterfuge sera bientôt terminé.", completion = "&lt;Le maréchal Windsor vous arrache les deux tablettes des mains.&gt;\n\nNous devons partir d'ici !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4283] = {title = "CINQUANTE ! OUI !", objective = "Oralius veut 50 Médaillons de Blackrock. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes.", description = "Je vais vous confier un petit secret, soldat. Approchez-vous un peu.\n\nJE SUIS LE SEUL QUI NE SOIT PAS FOU ICI !\n\nRegardez ces gens ! Croiriez-vous qu'ils sont tous fous ? Eh bien ils le sont ! DINGUES ! BARGES !\n\n<Oralius chuchote à présent.>\n\nQue ceci reste entre vous, moi et mon pote le capitaine Winky, n'est-ce pas ?\n\n<Oralius saisit l'air et presse son poing.>\n\nMais brèèèèèè-èè-èè-feuuuu ! Je fais la collection de médaillons pour aller avec celle d'oreilles d'ogre que j'ai déjà. L'orc est le parfum du jour. Cinquante. ALLEZ-Y !\n\n<Oralius souffle dans une corne.>\n\nEXPEDIEZ-LE !", progress = "<Oralius parle dans une grande oreille d'ogre coupée.>\n\nSteppes ardentes à contrôle, répondez contrôle.", completion = "Vous avez réussi ! Votre récompense est celle-ci : FROTTEZ MON VENTRE ! ALLEZ-Y ! FRICTIONNEZ-LE !", rewards = "Vous recevrez :\n\n"},
[4284] = {title = "Cristaux de puissance", objective = "Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal.", description = "Je crois que vous les avez remarqués, <nom>. Ils sont partout !\n\nDe quoi suis-je en train de parler ? Eh bien des cristaux bien sûr !\n\nLes cristaux… On en trouve partout dans le cratère. Les gens, pour la plupart, n'y prêtent pas attention, mais j'ai le sentiment qu'ils détiennent une certaine puissance. Depuis un moment, je fais des expériences sur eux, mais je n'arrive à rien. Pour l'instant, en tout cas.\n\nDites-moi, je commence à en manquer, vous pourriez m'en rapporter quelques-uns ?", progress = "Je sens que je vais trouver quelque chose, <nom> !", completion = "À présent je vais pouvoir continuer mes expériences ! Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4285] = {title = "Le Pylône nord", objective = "Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro.", description = "A quoi peuvent-ils bien servir ? Je ne peux pas m'empêcher d'y penser !\n\nÇa me rend dingue de savoir que les rumeurs que j'ai entendues à propos des pylônes de cristal pourraient être vraies. Taxez-moi de crédulité, mais je crois d'ordinaire tout ce que les gens me racontent.\n\nMais passons, j'ai entendu dire qu'un des pylônes de cristal est tout proche. Quelque part au nord… S'il vous plaît, trouvez-le, <nom>. Je sais simplement qu'ils existent.", progress = nil, completion = "Je sais que ces histoires disent vrai, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4286] = {title = "Du beau matériel", objective = "Se rendre dans les Profondeurs de Blackrock et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Blackrock.", description = "Le capitaine Winky me dit que les Sombrefer ont pris tout ce qu'il y avait d’intéressant dans les Profondeurs. Pas vrai, Winky ?\n\n<Oralius imite un pirate.>\n\nAARRRR MAT'LOT, TOUT JUSTE !\n\nVous voyez ? Vous devez y entrer et me rapporter tout ce que vous trouverez d’intéressant.\n\nAllez-y et magnez-vous le train !", progress = "Veuillez ne pas me déranger, <nom>. Moi et Winky devons aller à une réunion.", completion = "&lt;Oralius commence à farfouiller dans les immenses piles de sacoches.&gt;\n\nOH ! MERVEILLEUX !\n\n&lt;Oralius plonge le nez dans la pile et inspire profondément.&gt;\n\nDELICIEUX ! Regardez-moi tout ça !\n\nPrenez-en une pour vous, &lt;nom&gt;. Il y en a plein ici.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nUne sacoche surprise"},
[4287] = {title = "Le Pylône est", objective = "Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro.", description = "Durant mon séjour ici j'ai entendu d'étranges rumeurs sur l'existence de pylônes mystérieux dans les terres sauvages du cratère, <nom>. Je suppose qu'ils sont très grands, et que les cristaux garnissent l’intérieur.\n\nBien que je n'en aie jamais vu, je ne peux m'empêcher de croire que ces rumeurs disent vrai, et que les pylônes ont quelque chose à voir avec les cristaux que nous avons trouvés.\n\nNe voudriez-vous pas m'aider à satisfaire ma curiosité ? On dit qu'il existe un pylône dans la partie est du cratère. Pensez-vous pouvoir le trouver ?", progress = nil, completion = "Un'Goro est un endroit tellement étrange, &lt;nom&gt;. Lorsque vous entrez dans le cratère, c'est comme si vous pénétriez dans un monde totalement différent.", rewards = "Vous recevrez :\n\n"},
[4288] = {title = "Le Pylône ouest", objective = "Découvrir l'emplacement du Pylône de cristal ouest.", description = "Pour l'heure, mes expériences n'ont débouché sur aucun résultat positif, <nom>. Je ne peux qu'espérer que vous découvrirez l'un des pylônes dont j'ai entendu parler.\n\nPeut-être que si nous combinons différentes couleurs… mais je m'avance trop. Avant toute chose, trouvez-les !\n\n<nom>, cherchez dans la partie ouest du cratère, on dit qu’un pylône s'y trouve.", progress = nil, completion = "Il existe beaucoup de voies dérobées sur les bords du cratère. Essayez les chemins tortueux si vous ne savez plus où chercher, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4289] = {title = "Les gorilles d'Un'Goro", objective = "Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro.", description = "Ce cratère abrite de nombreuses créatures étranges. Elles semblent être des versions plus nobles de celles de ma terre natale et d'au-delà. Je ne peux m'expliquer ce fait, mais la Terre-mère affleure à cet endroit. Je lui rends hommage chaque fois que je poursuis l'une de ses belles créatures à travers son bassin.\n\nSi vous souhaitez ressentir l’allégresse que suscite une telle prouesse, alors dirigez-vous vers le nord. Vous y trouverez de grands singes, parfaits pour tester n'importe quel mortel. Apportez-moi leurs peaux… Montrez-moi votre force !", progress = "Eh bien ! Les créatures indigènes vous ont-elles déjà vaincu, <nom> ?\n\nN’abandonnez pas si facilement. Chasser et abattre les singes d'Un'Goro n'est pas tâche aisée, même pour un grand chasseur.", completion = "Vous vous êtes montré suffisamment fort pour affronter les grands singes d'Un'Goro. C'est bien. Ce défi était peu de chose comparé à celui que représente une confrontation avec Lar'korwi, mais je ne dévalorise en rien une telle victoire.\n\nCes peaux feront de merveilleux vêtements pour ma tribu. Vous m'êtes venu en aide et vous vous êtes montré digne.\n\nAvant que vous ne partiez accomplir un nouvel exploit, louons la Terre-mère et remercions les esprits de ces singes que vous avez tués. Ils doivent savoir que leur mort n'a pas été vaine.", rewards = "Vous recevrez :\n\n"},
[4290] = {title = "La nourriture de Lar'korwi", objective = "Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro.", description = "Il y a longtemps, l'un de mes frères préleva un peu de viande sur l'une des victimes de Lar'korwi. Lar'korwi le vit et le suivit pendant plusieurs jours, détruisant tout ce qu'il touchait. Mon frère, pris de terreur, décida de s'enfuir au loin.\n\nLar'korwi le tua près de cet endroit.\n\nSi vous voulez provoquer Lar'korwi, trouvez une de ses récentes victimes et volez de la viande.\n\nRevenez me voir après.", progress = "Ne prenez pas à la légère ce que je vais vous dire, <nom>. Si vous souhaitez combattre cette créature, alors vous devez être extrêmement prudent… et malin. Beaucoup de force et de perspicacité seront nécessaires pour attirer Lar'korwi et le battre.", completion = "Ce sera parfait, &lt;nom&gt;. On dirait que Lar'korwi se nourrit correctement ces jours-ci. Je me demande quand même où il a pu dénicher un battrodon par ici.\n\nMais passons, je vais garder cette carcasse jusqu'à ce que vous soyez prêt à affronter cette créature. Ne vous inquiétez pas pour moi. Vous l'avez mis suffisamment en colère pour qu'il ne s'en prenne pas à moi avant d'avoir goûté à votre chair.", rewards = "Vous recevrez :\n\n"},
[4291] = {title = "Un parfum pour Lar'korwi", objective = "Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", description = "Cela me surprend qu'il ne soit pas encore venu s'occuper de vous, <nom>. Mais tout va bien, car j'ai une dernière idée pour attirer le monstre.\n\nEn tant que mâle dominant, il a le droit de s'accoupler avec n'importe quelle femelle. Et il en choisit beaucoup. Vous trouverez de nombreux œufs de ravasaure à l'ouest d'ici. Approchez-vous-en et vous provoquerez l’attaque de ses compagnes. Les femelles possèdent dans la tête une glande qui secrète une affreuse odeur. Elle sert à avertir les mâles quand la reproduction est possible. Apportez-moi l'une de ces glandes.", progress = "Soyez prudent, <nom>. S'approcher des nids provoquera sûrement la colère des mères… Même si vous avez déjà pris une glande. Lorsqu'elles protègent leur progéniture, les mères peuvent être aussi acharnées et dangereuses que Lar'korwi lui-même. Mais si vous réussissez, alors nous posséderons le moyen absolu de faire sortir Lar'korwi de sa cachette.", completion = "Ah, ce sont de beaux spécimens, &lt;nom&gt;. Les deux morceaux que vous avez trouvés seront parfaits pour attirer Lar'korwi dans l'ouverture. Je suis impatient d'assister à votre combat avec le monstre. Il est énorme, puissant et ses griffes sont acérées comme les meilleures lames. Vous allez plonger dans son regard et vous connaîtrez la mort.", rewards = "Vous recevrez :\n\n"},
[4292] = {title = "Un appât pour Lar'korwi", objective = "En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.", description = "C’est la partie la plus délicate, car le plan comprend une difficulté. Dans les montagnes, au nord d'ici, vous trouverez un petit sentier. C'est là que j'ai vu Lar'korwi pour la dernière fois. Vous saurez que vous êtes au bon endroit lorsque vous trouverez des ossements de grandes créatures qui autrefois parcouraient ces lieux. Posez là le morceau de viande que vous avez récupéré sur une carcasse récente. Puis frottez la viande avec la glande. Si la combinaison de ces deux appâts ne parvient pas à attirer Lar'korwi, alors rien d'autre ne le pourra.", progress = "Ne laissez pas la peur vous submerger, <nom>. La peur est la pire des traîtresses… Vous devez rester fort !\n\nPrenez la viande, portez-la dans la petite vallée et frottez la glande dessus. Alors seulement la mort viendra vous chercher.", completion = "Que la Terre-mère soit louée ! Vous avez réussi ! Brillant, &lt;nom&gt;. Vous avez prouvé que vous faisiez partie des meilleurs chasseurs. Votre esprit est fort. Votre courage n'a pas d'égal. Et votre force s'est accrue. Je m'incline devant vos talents.\n\nSeuls les plus grands de mes ancêtres auraient pu accomplir un fait aussi incroyable. Félicitations.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTunique de rôdeur des plainesJambières de voltigeur\n\nVous recevrez également :\n\n"},
[4293] = {title = "Un échantillon de Limon...", objective = "Ramasser des Echantillons de Gelée de Gangrebois sur les gelées de Gangrebois. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Undercity, déceler l'échantillon le plus corrompu. Apporter 5 Echantillons corrompus de Gangrebois au Chimiste Fuely.", description = "Gangrebois est une forêt, loin au nord des Tarides, au-delà d’Ashenvale. Des Gelées s’y regroupent autour des mares touchées par la Corruption. Le Fléau a décimé la zone avec des attaques d’Infernaux et de la magie démoniaque. Les Gelées ont, semble-t-il, profité de ces attaques pour remonter à la surface.\n\nCollectez des échantillons de Gelée de Gangrebois et nous utiliserons l'équipement d'analyse, à côté de moi, pour les confronter aux autres échantillons que vous avez prélevés.", progress = "J'aurai besoin d'au moins cinq échantillons corrompus pour notre groupe de surveillance, <nom>. Continuez à rassembler des échantillons de gelée de Gangrebois jusqu'à ce que vous en ayez suffisamment. C'est Dame Sylvanas qui l'a décrété...", completion = "Ah, excellent. Ces échantillons feront l'affaire. Je vous remercie pour votre aide.\n\nUne fois que nous aurons rassemblé tous les échantillons de limons, nous serons à même d'en savoir plus. Je commence à me dire que l'intuition de Dame Sylvanas n'était pas simplement correcte, mais bien plus perspicace qu'elle ne l'aurait pensé. Ces échantillons sont très intéressants. A voir comment ils ont réagi à mes composés... Hm, oui, nous devons en savoir plus.", rewards = "Vous recevrez :\n\n"},
[4294] = {title = "... et un échantillon de Limon", objective = "Ramasser des Echantillons de Gelée d'Un'Goro sur les gelées du Cratère d'Un'Goro. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Undercity, déceler l'échantillon le plus pur. Apporter 5 Echantillons purs d'Un'Goro au Chimiste Fuely.", description = "Avez-vous entendu parler du Cratère d'Un'Goro, <nom> ? Il n’est pas loin du désert de Tanaris et c’est un endroit magnifique : luxuriant, animé,avec une faune et une flore exceptionnelles.\n\nC’est là que vous devez aller. J’ai entendu dire que ce lieu avait conservé toute son intégrité et sa pureté ; les explorateurs n'en découvrent les secrets que depuis peu.\n\nJ’aimerais examiner les Gelées et les Limons qui y vivent et comprendre comment ils sont parvenus à se garder de la corruption. Je voudrais voir comment ces créatures ont évolué.", progress = "Oui, <nom> ? Comment se déroule votre quête ?", completion = "Vraiment ahurissant, &lt;nom&gt;. Ce cratère d'Un'Goro renferme bien plus de secrets que je ne l'espérais. Je me demande ce que nous allons découvrir en nous enfonçant plus avant.\n\nC'est vraiment incroyable... Regardez comme ces échantillons sont purs. Hm, Je me demande ce que ça signifie. Ils semblent être de nature élémentaire, mais... ce n'est pas tout. Ils me rappellent... les Dieux très anciens. Nous avons trouvé des preuves de leur existence un peu partout dans Azeroth, et je me demande si ces créatures n'ont pas quelque chose à voir avec eux.\n\nNous verrons ça plus tard.", rewards = "Vous recevrez :\n\n"},
[4295] = {title = "La bière de Rocknot", objective = "Oh, de la bière ! Je tuerais pour une bonne bière de Sombrefer, <nom> ! Vite, je deviens sobre ! Je le sais car la sobriété trouble ma vision… et cela vous fait ressembler à celui que j'ai massacré la semaine dernière !", description = nil, progress = "Oh, de la bière ! Je tuerais pour une bonne bière de Sombrefer, <nom> ! Vite, je deviens sobre ! Je le sais car la sobriété trouble ma vision… et cela vous fait ressembler à celui que j'ai massacré la semaine dernière !", completion = "Qu'est-ce que c'est ? Ah ! Ça sent comme de la bière de Sombrefer ! La boisson a troublé ma vision, mais je peux dire que vous, monsieur, êtes un véritable ami.", rewards = nil},
[4296] = {title = "Tablette des Sept", objective = "Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes.", description = "Je suis venu dans les Steppes ardentes à la suite de la légende des Sept. Il s'agissait de nains puissants et érudits ; et si l'on possède ces deux qualités, la richesse ne tarde pas à suivre.\n\nC'est exactement ce que je veux. La richesse !\n\nSi nous pouvons en apprendre davantage à propos des Sept, peut-être pourrions-nous devenir riches tous les deux ? On dit que les Ruines de Thaurissan abritent la Tablette des Sept qui contient tout le savoir des anciens nains. Trouvez cette tablette, recopiez-la et apportez-moi la copie. Découvrons ensemble ses secrets…", progress = "Avez-vous trouvé les écritures des Sept, <nom> ? Avez-vous percé les mystères de leur tablette ?", completion = "Ah, vous avez trouvé la tablette ! Et votre transcription est superbe ! Vous êtes sûr d'être un &lt;classe&gt;, et non un scribe ?\n\nTenez, &lt;nom&gt;. Voici la récompense promise.", rewards = "Vous recevrez :\n\n"},
[4297] = {title = "Nourriture pour bébé", objective = "Apporter 5 Flancs de Traqueur Crins-d'argent à Angar Beastamer dans les Hinterlands.", description = "Les Fées fléchetteuses sont omnivores. Cela veut dire qu'elles mangent de tout. Si l'œuf que vous avez là se décide à éclore, nous ferions mieux d'être prêts. Croyez-le ou non, ces demoiselles apprécient la viande, sous forme de flancs crus et bien saignants. Je n'ai jamais su pourquoi, mais cela a à voir avec les projets d'Elune concernant les elfes… Peut-être auraient-ils dû être les protecteurs de quelque chose, je n'en sais trop rien.\n\nDésormais je vais m'occuper de l'œuf. Pourquoi n'iriez-vous pas chercher de bons flancs de Traqueur Crins-d'argent le temps qu'il éclose.", progress = "Avez-vous trouvé la viande, <nom> ? Votre petit œuf est sur le point d'éclore, vous savez ? S'il ne mange pas de la bonne viande à son premier repas, il peut ne pas passer la semaine, et je n'aimerais pas du tout que cela arrive.\n\nJe ne peux pas vous mentir plus longtemps, <nom>. La jalousie m'étreint du fait que vous ayez trouvé cet œuf. Ne me faites pas regretter de vous aider ainsi.", completion = "Ils feront parfaitement l'affaire, et si je ne m'abuse, votre petit œuf va éclore très bientôt. Alors, quel effet ça fait ? Vous allez bientôt être papa, vous savez ? Ha ! Ha ! Vous n'auriez pas cru avoir tant de responsabilités, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[4298] = {title = "L'amour d'un parent", objective = "Parler à Agnar Beastamer dans les Hinterlands.", description = "Ouah, c'était bien plus prêt que je ne le pensais...", progress = nil, completion = "Prenez l'œuf. Mieux vaut que vous le teniez comme ça : il s'attachera à vous et vous considérera comme son papa.\n\nFélicitations, &lt;nom&gt;. Vous êtes père à présent… ou presque.", rewards = "Vous recevrez :\n\nOeuf de Fée fléchetteuse"},
[4300] = {title = "Les armes aux lames d'os", objective = "Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar.", description = "Hmm… Maintenant que j'y pense, il y a peut-être quelque chose que vous pourriez faire pour la Main. Oui, vous pourriez aider Jes'rimon, c'est sûr.\n\nIl existe des raptors armés de griffes mortelles dans le Cratère d'Un'Goro. Certains de ces raptors ont des griffes blanches au lieu de noires comme la mort. La Main a des… clients… qui apprécient les armes fabriquées à partir de ces griffes. Apportez-moi quelques-unes de ces griffes blanches, et je vous paierai bien. Agissez vite, et je vous aiderai peut-être d’autres manières.", progress = "Mes clients ne sont pas réputés pour leur patience, <nom>. Vous êtes-vous déjà procuré ces griffes ?", completion = "Ah, celles-ci conviendront à merveille ! Merci, &lt;nom&gt;. Et vous êtes revenu bien avant que j’aie une demande pour ces armes. C'est bien.\n\nNous avons peut-être en réserve une arme faite de griffes… pour vous. Qu'en dites-vous ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau d'os blancGriffes d'os blancLance d'os blanc\n\nVous recevrez également :\n\n"},
[4301] = {title = "Le puissant U'cha", objective = "Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro.", description = "Pendant que vous exploriez Un'Goro, j'ai vu certaines choses <qu’un maître/qu’une maîtresse> de la chasse apprécierait grandement. J'ai vu un singe immense parmi les autres gorilles, au nord. Vous êtes déjà <allé/allée> à cette caverne, mais cette fois, je me demande si vous survivrez à cette rencontre. La question se pose si vous acceptez la tâche que je veux vous confier.\n\nJe l'appelle U'cha, et c'est l'un des plus grands fils de la terre-mère. Tuez U'cha et apportez-moi sa peau. Réussissez, et je défendrai moi-même votre droit à vous appeler <un grand chasseur/une grande chasseresse>.", progress = "U'cha… La bête était magnifique. Immense et rouge, les dents de la taille de dagues. Les bras aussi larges que trois troncs, et aussi rapide que le plus rapide des lions des montagnes que j'ai vus. Vous avez de la chance de pouvoir ainsi tester votre courage. Plusieurs générations pourraient passer sur mon peuple avant qu'il ne rencontre une telle créature.", completion = "Bien joué, &lt;nom&gt;. Je suis enchanté. Vous avez accompli un grand exploit en ce jour et en ce lieu.\n\nU'cha était l'un des plus grands singes que j'aie jamais rencontrés. Que vous ayez surpassé sa force en dit long sur la vôtre… et sur votre courage.\n\nCe n'est que justice si je vous remets ceci en signe de respect. Vous l'avez mérité.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nFracasse-bêtesTranche-bêtes\n\nVous recevrez également :\n\n"},
[4321] = {title = "Ceci explique cela", objective = "Parler à J.D. Collie dans un moment.", description = "L’information que vous m’avez transmise à propos des pylônes est très intéressante...\n\nLaissez-moi réfléchir à certaines choses, <nom>. Revenez me voir dans un moment, je devrais pouvoir vous donner les réponses que vous cherchez.", progress = nil, completion = "Très bien, &lt;nom&gt;. C'est fascinant... J'espère que mes diagrammes sont exacts ! J'ai tout compilé dans ce manuel, que vous pouvez prendre.\n\nJe pense pouvoir répondre à toutes vos questions concernant les cristaux, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nManuel d'utilisateur de Pylône de cristal"},
[4322] = {title = "Evasion !", objective = "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell.", description = "Nous devons sortir d'ici, <nom>. Aidez-moi à récupérer mon équipement dans la zone d'approvisionnement et à libérer mes amis. Si nous nous en sortons, vous devrez vous rendre à la Veille de Morgan et parler au maréchal Maxwell. Il vous donnera d'autres instructions.", progress = nil, completion = "Incroyable, &lt;nom&gt; ! Simplement incroyable ! Windsor a débarqué ici il n'y a pas 5 minutes. Il lance des accusations et prétend avoir des preuves. Il est maintenant en route pour Stormwind, pour affronter Bolvar et... Dame Prestor.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de rétorsionDague de maîtrise\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nGardien des éléments"},
[4324] = {title = "Yuka Screwspigot", objective = "Parler à Yuka Screwspigot dans les Steppes ardentes.", description = "Bien que mon petit frère, Ribbly, soit un bon à rien, je crois qu'il ne s'est pas montré complètement incompétent cette fois ! Mais… il se peut que nous ayons besoin de votre aide pour exploiter sa récente découverte.\n\nMa soeur, Yuka, l'a cherché durant des semaines, et ses recherches l'ont conduite jusqu'aux Steppes ardentes. Elle m'a envoyé un message, demandant de l’aide afin de poursuivre ses recherches.\n\nAlors, qu'en dites-vous ? Voulez-vous nous aider ? Si oui, allez parler à ma soeur. Vous la trouverez cachée dans la corniche des flammes, une caverne au nord-ouest du rocher des Cognepeurs.", progress = nil, completion = "Oui, je recherche mon frère. Nous devons le trouver et le récupérer, ce pauvre innocent.\n\nMais si nous ne pouvons le rapporter en entier… alors sa tête suffira.", rewards = nil},
[4341] = {title = "Kharan Mighthammer", objective = "Aller dans les Profondeurs de Blackrock et trouver Kharan Mighthammer.\n\nLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison.", description = "Avez-vous été dans les ruines fumantes de Thaurissan ? Avez-vous rencontré un pitoyable voyou nommé Kharan Mighthammer ? Ce nain qui était censé veiller sur ma petite fille !\n\n<Le roi sanglote.>\n\nEt maintenant elle est partie, <nom> !\n\nMes hommes ont fouillé les Steppes buisson par buisson. Le seul indice qu’ils ont trouvé semble révéler que ma fille se trouve quelque part dans les Profondeurs. Elle pourrait tout aussi bien être morte !\n\nKharan serait prisonnier là-bas... Trouvez-le, je veux des réponses !", progress = nil, completion = "S'il vous plaît, laissez-moi expliquer.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4342] = {title = "Légende de Kharan", objective = "Écouter Kharan Mighthammer raconter son histoire.", description = "Écoutez-moi attentivement avant d'émettre un jugement !", progress = "Permettez-moi de terminer mon histoire.", completion = "Comme vous pouvez le voir, je ne pouvais rien faire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4343] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4361] = {title = "Le porteur des mauvaises nouvelles", objective = "Retourner à Ironforge et apporter la mauvaise nouvelle au Roi Magni Bronzebeard.", description = "Vous devez délivrer cette information au Roi Magni, <nom>. Il saura quoi faire !", progress = nil, completion = "&lt;Le roi Magni abat son poing avec colère.&gt;", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4362] = {title = "Le destin du Royaume", objective = "Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan.", description = "On dirait que mon vieil adversaire, Dagran Thaurissan, me tient, moi et le royaume d’Ironforge, à sa merci.\n\nVous pourriez bien être ma dernière chance, <nom>. Vous devez secourir ma chère enfant, Moira !\n\nIl n’y a qu’une seule manière de s’assurer que le sort que Thaurissan a jeté sur Moira soit rompu : le tuer !\n\nEt surtout, <nom>, ne la blessez pas ! N’oubliez pas qu’elle est contrôlée par Thaurissan ! Tout ce qu’elle peut dire ou faire est sous l’emprise du sort maléfique de Thaurissan.", progress = nil, completion = "&lt;La Princesse Bronzebeard pleure la perte de l'Empereur Dagran Thaurissan.&gt;\n\nPourquoi ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4363] = {title = "La surprise de la Princesse", objective = "Retourner à Ironforge et parler au roi Magni Bronzebeard.", description = "Thaurissan était un nain valeureux et honorable. Vous avez détruit ma vie et celle de l’enfant que je porte !\n\n<Vous estimez que la princesse Bronzebeard souffre toujours des effets résiduels du sort de l’Empereur.>\n\nRetournez à Ironforge et dites à mon père que l’héritier du trône d’Ironforge sera un nain Sombrefer.\n\nQue cela lui plaise ou pas, il en sera ainsi.", progress = nil, completion = "&lt;Le roi Magni Bronzebeard est visiblement contrarié.&gt;\n\nIl semble que même mort, Thaurissan ait gagné.\n\nVous pouvez disposer, &lt;nom&gt;. Avant que vous partiez, vous pouvez choisir une récompense dans le trésor royal.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nVolonté de MagniPierre chantante d'Ironforge\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4381] = {title = "Cristal de restauration", objective = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à vous soigner, vous et vos alliés.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à vous soigner, vous et vos alliés.", completion = "Tandis que vous arrangez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense mêle les cristaux entre eux.\n\nLe résultat vous appartient.", rewards = "Vous recevrez :\n\nCristal de restauration"},
[4382] = {title = "Cristal de concentration", objective = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les bleus.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à augmenter l'Esprit.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les bleus.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à augmenter l'Esprit.", completion = "Tandis que vous disposez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense assemble les cristaux entre eux.\n\nLe résultat est à vous.", rewards = "Vous recevrez :\n\nCristal de concentration"},
[4383] = {title = "Cristal de protection", objective = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les rouges.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à augmenter la protection contre les dégâts physiques.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance verts avec les rouges.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à augmenter la protection contre les dégâts physiques.", completion = "Tandis que vous arrangez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense mêle les cristaux entre eux.\n\nLe résultat vous appartient.", rewards = "Vous recevrez :\n\nCristal de protection"},
[4384] = {title = "Cristal de réduction", objective = "Le Pilon vous permet de combiner les cristaux de puissance rouges avec les bleus.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à réduire la Défense de l'adversaire.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance rouges avec les bleus.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à réduire la Défense de l'adversaire.", completion = "Tandis que vous disposez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense assemble les cristaux entre eux.\n\nLe résultat est à vous.", rewards = "Vous recevrez :\n\nCristal de réduction"},
[4385] = {title = "Cristal d'explosion", objective = "Le Pilon vous permet de combiner les cristaux de puissance rouges avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison peut être utilisée pour créer une grande explosion qui inflige des dégâts à vos ennemis.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance rouges avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison peut être utilisée pour créer une grande explosion qui inflige des dégâts à vos ennemis.", completion = "Tandis que vous disposez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense assemble les cristaux entre eux.\n\nLe résultat est à vous.", rewards = "Vous recevrez :\n\nCristal d'explosion"},
[4386] = {title = "Cristal de rétribution", objective = "Le Pilon vous permet de combiner les cristaux de puissance bleus avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à créer un bouclier qui inflige des dégâts aux ennemis.", description = nil, progress = "Le Pilon vous permet de combiner les cristaux de puissance bleus avec les jaunes.\n\nSi on se réfère au manuel de J.D., cette combinaison sert à créer un bouclier qui inflige des dégâts aux ennemis.", completion = "Tandis que vous disposez les cristaux sur la table, vous alignez précautionneusement les couleurs. Lorsque vous placez le dernier, une explosion de lumière intense assemble les cristaux entre eux.\n\nLe résultat est à vous.", rewards = "Vous recevrez :\n\nCristal de rétribution"},
[4401] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4402] = {title = "Surprise aux pommes de cactus de Galgar", objective = "Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus.", description = "La situation est, en effet, assez tendue dans la Vallée des épreuves.\n\n<Galgar s’éponge le front.>\n\nSi seulement j'avais quelques pommes de cactus, je pourrais faire ma fameuse surprise aux pommes de cactus ! Rien ne vous rafraîchit aussi vite qu’une part de ce délice.\n\nJe vais vous dire, <nom>, si vous me rapportez 10 pommes de cactus, je vous donnerai quelques parts de surprise aux pommes de cactus en guise de provisions pour vos aventures. Si cela vous intéresse, vous trouverez des pommes de cactus à côté des cactus, tout autour d’ici.", progress = "Avez-vous terminé de collecter des Pommes de cactus ?", completion = "Merveilleux, &lt;nom&gt; ! Comme promis, voici votre surprise aux pommes de cactus plus un petit quelque chose.", rewards = "Vous recevrez :\n\nSurprise aux pommes de cactus"},
[4403] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4421] = {title = "La corruption des Jadefeu", objective = "Tuer 11 Liges de la corruption Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Bluewind, à Gangrebois, quand la mission est terminée.", description = "Rares sont ceux qui viennent par ici... la corruption de Gangrebois est maintenant étendue et indiscriminée.\n\nEn tant que membre du Cercle d'émeraude, j'aspire à guérir cette terre ; mais certains, au contraire, ne souhaitent que la voir pourrir et se décomposer.\n\nJe parle des satyres Jadefeu qui vivent au sud-ouest, dans les ruines de Constellas. Conduits par un satyre particulièrement cruel, du nom de Xavathras, ils continuent de répandre la maladie, et contaminent toutes les créatures qui ont le malheur de croiser leur route.\n\nJe vous en prie, aidez-nous à défendre cette terre qui était autrefois nôtre. Détruisez Xavathras et ses sbires.", progress = nil, completion = "Débarrasser Gangrebois de Xavathras est seulement la première étape. Réparer les dégâts sera, en revanche, une tâche plus laborieuse.\n\nJe pressens que quelque chose de plus important que de simples satyres est à l'oeuvre ici, mais seul le temps nous le dira...", rewards = "Vous recevrez :\n\n"},
[4441] = {title = "Anciens corrompus", objective = "Aller à Darnassus et utiliser la Fiole d'Eridan dans le Temple de la Lune, pour obtenir une Fiole d'eau bénite. Retourner voir Eridan avec la Fiole pleine.", description = "La flûte que vous avez trouvée a été arrachée à un Ancien Protecteur, un tréant fidèle qui avait juré protection aux elfes de la nuit.\n\nLes satyres ont réussi a corrompre tout ce qui est entré en contact avec eux, même les Anciens qui ont fait de Gangrebois leur domaine. La corruption a lié et torturé l’esprit de l’Ancien qui n’a jamais vraiment guéri de cette infection. La corruption dont vous avez été témoin est sans nul doute liée à cela.\n\nNous devons essayer de purifier la flûte, <nom>. Apportez-moi de l’eau bénite du Temple de la Lune, à Darnassus.", progress = "L'eau libérera l'Esprit d'un ancien et lui permettra de retrouver la paix.", completion = "Merci, &lt;nom&gt;. Maintenant, prions pour que nous puissions réparer les dégâts qui ont été causés...", rewards = "Vous recevrez :\n\n"},
[4442] = {title = "Purifié !", objective = "Attendre un moment avant de reparler à Eridan.", description = "Avec l’eau d’Elune, je vais essayer de purifier la flûte. Nous devons mettre un terme à cette souffrance...\n\nQu’Elune guide mes mains et mon coeur.\n\nReparlez-moi dans un moment.", progress = nil, completion = "Avec l'eau bénite, j'ai été capable de briser le lien qui existait entre la flûte et l'esprit de l'ancien. Je crois que si vous utilisez cette flûte dans un lieu sacré, vous serez à même d'invoquer l'esprit d'un ancien.\n\nPeut-être devriez-vous aller dans les ruines qui se trouvent dans la partie sud du bois d'Arbrefer. De nombreux tréants corrompus ont habité cette zone, jadis, et il est possible qu'ils y résident encore, sous la forme d'esprits.", rewards = "Vous recevrez :\n\nFlûte des anciens"},
[4443] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4444] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4445] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4446] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4447] = {title = "Dragon nocturne corrompu", objective = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", description = nil, progress = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", completion = "Vous appliquez quatre doses de Baume végétal cénarien sur le dragon nocturne. La plante commence immédiatement à se débarrasser de sa forme corrompue et refleurit pour devenir une plante vibrante de santé.", rewards = nil},
[4448] = {title = "Dragon nocturne corrompu", objective = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", description = nil, progress = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", completion = "Vous appliquez quatre doses de Baume végétal cénarien sur le dragon nocturne. La plante commence immédiatement à se débarrasser de sa forme corrompue et refleurit pour devenir une plante vibrante de santé.", rewards = nil},
[4449] = {title = "Piégé !", objective = "Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d’Etoffe de soie à la personne enfermée de les toilettes de la gorge des Vents brûlants.", description = "Hé vous ! Oui, vous ! Venez donc ici !\n\nVous allez m’aider. J’étais poursuivi par les nains Sombrefer, et je me suis planqué ici, hors de vue. Ces maudits géologues et leur magie ! Ils ont dû me repérer quand même, parce qu’ils ont verrouillé la porte avant que je ne puisse réagir. Je suis coincé à l’intérieur.\n\nDonnez-leur une bonne leçon ! oh… et puis si vous pouviez récupérer de l’étoffe de soie pour... euh… pour rien, ce serait parfait.", progress = "Je n'ai pas toute la journée ! Apportez-moi ces morceaux de soie ! Je veux dire ces géologues. Attrapez ces géologues ! Ils vont connaître ma, euh... votre colère.", completion = "Oh, fantastique ! C’est doux !\n\nQuoi ? Oh, oui... Les géologues. Vous les avez eus, n'est-ce pas ? Je ne sais pas comment vous remercier, &lt;nom&gt;. Ça va me laisser le temps de finir ici... Merci encore, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4450] = {title = "Grand livre de Tanaris", objective = "Prendre la copie du Livre de Goodsteel, puis collecter les objets qui y sont listés avant d’aller voir Krinkle Goodsteel, à Tanaris.", description = "Oh, maintenant que j’y pense...\n\nComme je suis bloqué ici, vous pourriez peut-être finir un petit travail que j’avais commencé quand j’étais à Tanaris. C’est facile, enfin vu de l’extérieur ça paraît facile.\n\nKrinkle Goodsteel à Gadgetzan recherchait du matériel que l’on peut trouver ici, dans la Gorge des Vents brûlants et dans quelques autres lieux. Vous pourriez peut-être jeter un coup d’oeil à cette liste et lui apporter ce qu’il veut ?\n\nJe vais glisser son Livre sous la porte si cela vous intéresse. Rapportez-le-lui ainsi que les choses qu’il désire, après les avoir collectées.", progress = "Oui, oui ? Que puis-je faire pour vous, <nom> ? Je suis très occupé et j'ai beaucoup de commandes en cours. Dépêchez-vous. Je suis désolé de précipiter les choses mais si je veux terminer mon travail, je n'ai pas le choix.", completion = "Oh, vous avez été capable de faire une partie du travail que je vous avais demandé. Excellent. Je suppose que vous allez me demander de vous fabriquer quelque chose.\n\nC'est parfait... Et tout est là. Merci, &lt;classe&gt;.\n\nCe n'est pas grave si je vous récompense avec... Hm, que voulez-vous ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâtonnet d'éclair chargéCeinturon de représailles\n\nVous recevrez également :\n\n"},
[4451] = {title = "La Clé de la liberté", objective = "Aller dans la gorge des Vents brûlants et trouver une utilisation à la Clé des toilettes de Grimesilt que vous avez trouvée.", description = "La petite clé en cuivre a l’air assez simple. La seule chose qui la distingue d’une clé banale sont les mots gravés sur sa tête :\n\n\"Toilettes Sombrefer – Ne pas dupliquer.\"\n\nVous ne savez pas à quoi cela sert ni à quoi cela va mener.", progress = "*tousse*\n\nQui est-ce ? Vous ne voyez pas que je suis occupé ?", completion = "Ça par exemple ! Damnation ! Vous avez trouvé la clé ! Je savais que ces enquiquineurs de Sombrefer l'avaient cachée après m'avoir enfermé ici ! Merci beaucoup, &lt;nom&gt;. Vous êtes le meilleur ! Utilisez la clé pour laisser sortir le vieux Locheed !", rewards = "Vous recevrez :\n\n"},
[4461] = {title = "La navetille corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s'épanouit en une plante vibrante de santé.", rewards = nil},
[4462] = {title = "Dragon nocturne corrompue", objective = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", description = nil, progress = "Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.", completion = "Vous appliquez quatre doses de Baume végétal cénarien sur le dragon nocturne. La plante commence immédiatement à se débarrasser de sa forme corrompue et refleurit pour devenir une plante vibrante de santé.", rewards = nil},
[4463] = {title = "Libram de rumination", objective = "Présentez les composants, mortel.\n\nJ'exige également trente pièces d'or en paiement de cette création.", description = nil, progress = "Présentez les composants, mortel.\n\nJ'exige également trente pièces d'or en paiement de cette création.", completion = "Prenez votre babiole, imbécile. Et laissez-moi poursuivre mes recherches !", rewards = "Vous recevrez :\n\nArcanum inférieur de rumination"},
[4464] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4465] = {title = "La fleur-de-chant corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.", rewards = nil},
[4466] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4467] = {title = "La fleur-de-vent corrompue", objective = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", description = nil, progress = "Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.", completion = "Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s'épanouir en une plante vibrante de santé.", rewards = nil},
[4481] = {title = "Libram de constitution", objective = "Chaque chose a son prix en ce monde. Le prix de l'article précis que vous cherchez est de trente pièces d'or.\n\nNaturellement, je garderai la majorité des composants que vous avez ramassés. Mais pas d'inquiétude, vous aurez votre bijou.", description = nil, progress = "Chaque chose a son prix en ce monde. Le prix de l'article précis que vous cherchez est de trente pièces d'or.\n\nNaturellement, je garderai la majorité des composants que vous avez ramassés. Mais pas d'inquiétude, vous aurez votre bijou.", completion = "C'est une insulte à sa mémoire... Un simple mortel comme vous, terminant l'oeuvre de sa vie.\n\nPrenez votre cristal et partez !", rewards = "Vous recevrez :\n\nArcanum inférieur de constitution"},
[4482] = {title = "Libram de ténacité", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nArcanum inférieur de ténacité"},
[4483] = {title = "Libram de résistance", objective = "Si c'est de la résistance que vous désirez, c'est trente pièces d'or que je demande.", description = nil, progress = "Si c'est de la résistance que vous désirez, c'est trente pièces d'or que je demande.", completion = "Les autres libram ont été égarés de part le monde, dans des endroits où vous ne souhaiteriez jamais mettre les pieds.\n\nJe vais puiser dans l'énergie de ces composants. Je vous donnerai les restes...", rewards = "Vous recevrez :\n\nArcanum inférieur de résistance"},
[4484] = {title = "Libram de voracité", objective = "Ne me faites pas perdre mon temps, <nom>. Donnez-moi ce que je demande. Trente pièces d'or et les composants.", description = nil, progress = "Ne me faites pas perdre mon temps, <nom>. Donnez-moi ce que je demande. Trente pièces d'or et les composants.", completion = "Ma tête vibre... toutes ces énergies qui façonnent notre univers... ARGH !\n\n&lt;Mathredis a l'air peiné.&gt;\n\nPrenez ce que vous voulez et partez !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArcanum inférieur de voracitéArcanum inférieur de voracitéArcanum inférieur de voracitéArcanum inférieur de voracitéArcanum inférieur de voracité"},
[4485] = {title = "Le Tome de noblesse", objective = "Parler à Duthorian Rall, à Stormwind.", description = "Salut, <nom>. Je vois que votre dévouement et votre foi restent forts.\n\nIl faut maintenant que vous parliez à Duthorian Rall, à Stormwind. Vous ne connaissez pas tout et je sens que le temps est venu pour un nouvel apprentissage.\n\nVous le trouverez dans la Cathédrale de la Lumière. Prenez ces leçons très au sérieux, <nom>. Vous avez atteint votre niveau actuel grâce à votre humilité et votre travail acharné, ne nous décevez pas en devenant arrogant.\n\nBonne chance.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[4486] = {title = "Le Tome de noblesse", objective = "Parler à Duthorian Rall, à Stormwind.", description = "Bien, bien, bien, regardez-moi ce paladin, toute cette prestance.\n\n<nom>, je ne pensais pas à mal... je ressens juste l’aiguillon de la jalousie de temps en temps quand je vois quels exploits vous avez accomplis. Tiza me dit que telle est ma faiblesse et m’a fait promettre de travailler sur moi ; ce qui est dur, voyez-vous ?\n\nMais je voulais surtout vous parler parce que Duthorian Rall, à Stormwind, a demandé que vous le rejoigniez dans la cathédrale de la Lumière. Cela semblait important et urgent.", progress = nil, completion = "Ah, vous êtes de retour à la Cathédrale, &lt;nom&gt;. Bien. Je pourrais avoir besoin de votre aide si vous avez assez de courage.\n\nNous sommes confrontés à de nombreux ennemis. J'ai besoin de vous pour les arrêter.", rewards = "Vous recevrez :\n\n"},
[4487] = {title = "Invoquer un Palefroi corrompu", objective = "Parler à Strahad Farsan, à Ratchet.", description = "Ah, vous voilà. J’ai envoyé <une succube/un infernal> à votre recherche, mais apparemment vous avez décidé de venir ici de vous-même. Pas grave.\n\nIl y a eu des discussions, dernièrement, concernant votre force croissante ; ce qui est bon pour vous, mais mauvais pour d’autres. Enfin, vous avez fait preuve de votre vaillance et méritez une... hé hé... sorte de bénédiction.\n\nAu-dessus de Ratchet, dans les Tarides, vous trouverez un homme appelé Strahad. Je pense que vous l’avez déjà rencontré.", progress = nil, completion = "Encore une fois, vous m'honorez de votre présence. Comme c'est aimable de votre part.\n\nMes acolytes m'avaient dit que vous ne viendriez jamais. Je leur ai répondu que je n'en doutais pas. Lorsqu'il s'agit de puissance, vous ressemblez à un papillon attiré par les flammes.", rewards = "Vous recevrez :\n\n"},
[4488] = {title = "Invoquer un Palefroi corrompu", objective = "Parler à Strahad Farsan, à Ratchet.", description = "Ah, <nom>, nous sommes honorés de votre présence !\n\nJ'espère, toutefois, que vous ne pensez pas que nous allons être à votre botte. Vos forces augmentent rapidement, mais vous restez néanmoins un novice quand il s’agit de connaissance véritable. Si vous ne faites pas attention, la corruption se saisira de votre corps et de votre esprit affaibli.\n\nEnfin, voici de quoi il s’agit : Strahad veut vous parler. Il réside toujours dans la tour qui domine Ratchet, dans les Tarides. Ne tardez pas.", progress = nil, completion = "Encore une fois, vous m'honorez de votre présence. Comme c'est aimable de votre part.\n\nMes acolytes m'avaient dit que vous ne viendriez jamais. Je leur ai répondu que je n'en doutais pas. Lorsqu'il s'agit de puissance, vous ressemblez à un papillon attiré par les flammes.", rewards = "Vous recevrez :\n\n"},
[4489] = {title = "Invoquer un Palefroi corrompu", objective = "Parler à Strahad Farsan, à Ratchet.", description = "Vous, <nom> ! Venez ici !\n\nVous êtes bien la personne qu’on appelle <nom>, non ?\n\nParlons peu, parlons bien : vos forces augmentent et cela se sait. Le temps est venu que vous récoltiez le fruit de vos efforts.\n\nAllez dans les Tarides, dans la Tour qui domine Ratchet, et trouvez Strahad Farsan ; peut-être vous souvenez-vous de lui ? Il aurait à vous parler. Ne traînez pas.", progress = nil, completion = "Encore une fois, vous m'honorez de votre présence. Comme c'est aimable de votre part.\n\nMes acolytes m'avaient dit que vous ne viendriez jamais. Je leur ai répondu que je n'en doutais pas. Lorsqu'il s'agit de puissance, vous ressemblez à un papillon attiré par les flammes.", rewards = "Vous recevrez :\n\n"},
[4490] = {title = "Invoquer un Palefroi corrompu", objective = "Parler à Strahad Farsan, à Ratchet pour apprendre à invoquer un Palefroi corrompu.", description = "Je vous récompenserais bien de tous vos efforts et de votre patience. Mais sachez que la capacité d’invoquer un Palefroi corrompu ne sera plus une partie de plaisir dans le futur. Il vous faudra la gagner... et cela ne sera pas facile.\n\nPour l’instant, utilisez le pouvoir d’invoquer une telle créature quand vous le jugerez nécessaire.", progress = nil, completion = "Bonne chance, &lt;nom&gt;. J'attends avec impatience votre retour.", rewards = "Vous apprendrez :\n\nInvocation d'un palefroi corrompu\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un Palefroi corrompu\n\nVous recevrez également :\n\n"},
[4491] = {title = "Un peu d'aide de mes amis", objective = "Conduire Ringo à Spraggle Frock, au refuge des Marshal.\n\nSi Ringo s’évanouit, utiliser la Gourde de Spraggle pour le réanimer.", description = "Wouf… c'est tellement chaud…\n\nJ'explorais le secteur lorsque soudain, la chaleur est devenue insupportable. Je dois souffrir d'insolation.\n\nJe vous en prie, aidez-moi à retourner à mon ami Spraggle au refuge des Marshal. Je pense que je vais encore suffisamment bien pour être capable de vous suivre jusque là-bas.\n\nJe ne me sens pas vraiment là, cependant, alors si je devais m'évanouir à nouveau, renversez-moi de l'eau de la gourde de Spraggle dessus. Ça devrait marcher, j'espère...", progress = nil, completion = "Ringo n'est pas en grande forme, &lt;nom&gt;, mais au moins, il est en un seul morceau !\n\nMerci de l'avoir retrouvé.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières enchâsséesJambières de la canopéeCasque de Clayridge\n\nVous recevrez également :\n\n"},
[4492] = {title = "Perdu !", objective = "Trouver Ringo sur la crête de la Fournaise.", description = "Vous devez m’aider, <nom> ! Mon ami, Ringo, est parti pour explorer le volcan, plus au sud, et il n’est toujours pas rentré. Je commence vraiment à m’inquiéter.\n\nPourriez-vous essayer de le retrouver ? Prenez ma gourde avec vous, si vous retrouvez Ringo, il en aura sans doute besoin !", progress = "Qu.. Quoi ?", completion = "Oh... Quelle joie que quelqu'un m'ait trouvé...", rewards = "Vous recevrez :\n\n"},
[4493] = {title = "La marche des silithides", objective = "Parler à l’alchimiste Pestlezugg à Gadgetzan.", description = "Il semblerait que l'objectif des silithides soit de dévorer tout ce qui n'est pas lié à leur écosystème. Leur présence représente une grave menace pour la vie dans Azeroth.\n\nApparemment nous n'en sommes qu’aux premiers stades de leur invasion, et je suspecte leurs effectifs de provenir de régions reculées de Kalimdor, du cratère d'Un'Goro, plus exactement. Allez à Gadgetzan, dans le désert de Tanaris et parlez avec l’alchimiste Pestlezugg. Parlez-lui de ma théorie ; il nous aidera dans notre lutte contre les silithides.", progress = nil, completion = "Oui, j'ai conclu que c'est Gracina qui vous envoie. Votre expérience du combat contre ces créatures est inestimable ; personne à ma connaissance n'a jamais affronté cette espèce auparavant. Puisque Gracina pense que le cratère d'Un'Goro est leur berceau... Ça doit être le cas. Un'Goro est une jungle mystérieuse et dangereuse qui se trouve à l'ouest. Peut-être sommes-nous en train de faire un pas supplémentaire vers la résolution du mystère des silithides.", rewards = "Vous recevrez :\n\n"},
[4494] = {title = "La marche des silithides", objective = "Parler à l’alchimiste Pestlezugg à Gadgetzan.", description = "Il semblerait que l'objectif des silithides soit de dévorer tout ce qui n'est pas lié à leur écosystème. Leur présence représente une grave menace pour la vie dans Azeroth.\n\nApparemment nous n'en sommes qu’aux premiers stades de leur invasion, et je suspecte leurs effectifs de provenir de régions reculées de Kalimdor, du cratère d'Un'Goro, plus exactement. Allez à Gadgetzan, dans le désert de Tanaris et parlez avec l’alchimiste Pestlezugg. Parlez-lui de ma théorie ; il nous aidera dans notre lutte contre les silithides.", progress = nil, completion = "Oui, j'ai bien compris que c'est Zilzibin qui vous envoie. Votre expérience du combat contre ces créatures est inestimable ; personne à ma connaissance n'a jamais affronté cette espèce auparavant. Puisque Zil pense que le cratère d'Un'Goro est leur berceau... ça doit être le cas. Un'Goro est une jungle mystérieuse et dangereuse qui se trouve à l'ouest. Peut-être sommes-nous en train de faire un pas supplémentaire vers la résolution du mystère des silithides.", rewards = "Vous recevrez :\n\n"},
[4495] = {title = "Un bon ami", objective = "Trouver Iverron près de la grotte au nord.", description = "L'un de mes amis, nommé Iverron, me rend visite tous les jours à la même heure. Mais, chose étrange, il n'est pas encore venu aujourd'hui. En fait, il a plusieurs heures de retard.\n\nJe dois admettre que cela m'inquiète, <nom>. Iverron passe beaucoup de temps du côté de la grotte qui se trouve au nord. Vous savez certainement que c'est dangereux là-bas...des araignées, partout !\n\nSi jamais vous alliez dans cette direction, pourriez-vous jetez un oeil ?", progress = nil, completion = "Je suis si content que vous m'ayez trouvé, &lt;nom&gt;. Comment avez-vous su que j'étais ici ?", rewards = "Vous recevrez :\n\n"},
[4496] = {title = "Fiasco dans la jungle", objective = "Apporter une Glande olfactive Gorishi et 5 Echantillons d'Humus d'Un'Goro à l’alchimiste Pestlezugg, à Gadgetzan.", description = "Mes recherches ont révélé que les silithides étaient comme des abeilles : détruisez la reine et vous jeterez la confusion dans l'essaim. Je vais concocter un appât pour attirer la reine ; une fois qu’elle se présentera, vous l’abattrez.\n\nD’abord, nous avons besoin de certains ingrédients... Vous ne devez pas aller dans la jungle sans préparation. Allez à l’ouest pour trouver la ruche silithide, dans le Cratère d'Un'Goro, et collectez une glande olfactive Gorishi sur l'un de ces insectes. J’ai également besoin de quelques échantillons d'Humus d'Un'Goro.", progress = "Trouver la Glande olfactive adéquate peut être long ; elle doit être en parfait état, ce qui n'est pas souvent le cas lorsqu'on a dû tailler en pièces la créature qui l'abrite. Quant à l'Humus, il ne devrait pas être trop dur à trouver.\n\nMais, avez-vous les objets dont j'ai besoin pour faire l'appât ?", completion = "La glande olfactive, ah oui. La membrane semble intacte, excellent. La terre, oui, cela devrait parfaitement fonctionner. Avec mon savoir-faire, je devrais pouvoir la broyer et en faire un appât parfait.\n\nDonnez-moi un moment pour le préparer, &lt;nom&gt;. Une fois qu'il sera prêt, nous pourrons passer à la prochaine étape, qui avec un peu de chance empêchera les silithides d'envahir Gadgetzan... Et tout le reste de Kalimdor.", rewards = "Vous recevrez :\n\n"},
[4501] = {title = "Attention aux pterreurdactyles", objective = "Tuer 10 Pterreurdactyles et 15 Pterreurdactyles frénétiques, puis parler à Spraggle Frock, au refuge des Marshal.", description = "On recherche : un guerrier compétent et talentueux pour se porter contre la menace des pterreurdactyles qui hantent le cratère d'Un'Goro. Leur nombre va croissant et ils sont en train de devenir un danger pour les voyageurs qui passent dans les environs.\n\nRéduisez leur population en tuant 10 pterreurdactyles et 15 pterreurdactyles frénétiques.\n\nParlez avec Spraggle Frock après avoir terminé votre mission pour recevoir une récompense.", progress = "A dire vrai, je n'étais pas inquiété par ces créatures étranges... Jusqu'à ce que je croise une inscription sur une pierre.\n\nATTENTION AUX PTERREURDACTYLES\n\nQui a bien pu l'écrire ? En tous cas, c'est bien trop effrayant pour ne pas y prendre garde !", completion = "Je suis complètement terrifié par les pterreurdactyles ! Merci d'avoir réduit leur population, &lt;nom&gt;. Je me sentirai peut-être suffisamment en confiance pour m'aventurer à l'extérieur du refuge des Marshal.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de GrotslabBottes de Cragplate\n\nVous recevrez également :\n\n"},
[4502] = {title = "Activité volcanique", objective = "Collecter 9 Echantillons de cendre Un'Goro sur les Elémentaires de brûlure qui se trouvent autour du volcan, dans le Cratère d'Un'Goro, puis les apporter à Liv Rizzlefix, à Ratchet.", description = "Etant un apprenti de Marvon Rivetseeker, j’ai beaucoup appris. Mais il est parti depuis tellement longtemps que je vais devoir travailler à quelques expérimentations de mon propre chef.\n\nJ'ai lu des informations concernant le cratère d'Un'Goro et l’étrange activité volcanique qui règne en son milieu. Nous en apprendrions plus si vous pouviez aller sur place et collecter de la cendre sur les élémentaires.\n\nCela vous dérangerait-il de m’en rapporter quelques-unes, si jamais vous passez par là-bas ?", progress = "On raconte que le volcan dans Un'Goro est en activité ? Je suis certain que je pourrais en apprendre plus en étudiant des échantillons de cendres du volcan, <nom>.", completion = "Ces échantillons seront parfaits pour mes recherches ! Merci, &lt;nom&gt; ! Je vous promets de vous tenir au courant en premier de mes découvertes.", rewards = "Vous recevrez :\n\n"},
[4503] = {title = "La machine volante de Shizzle", objective = "Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal.", description = "Je fabrique une machine volante !\n\nJe suis coincé ici et je n’ai aucun sens de l’orientation. Je pourrais prendre un gryphon ou un cavalier céleste pour rentrer à Gadgetzan, mais j’ai une peur bleue de ces bestioles.\n\nAlors, vous m’aiderez ? Il ne me reste qu’à construire les ailes et je me disais que des Ecailles étoilées de pterreurdactyles et de dimeurtrodon feraient parfaitement l’affaire. Pour ma part, je suis incapable de les affronter, mais vous semblez pouvoir le faire. Voulez-vous essayer ?", progress = "Tout véhicule mérite un nom... Je pense que je vais l'appeler... Humiliation !", completion = "Oui, ces écailles sont parfaites. Je devrais pouvoir faire décoller cette machine avec ces écailles, j'en suis sûr !\n\nMerci !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier de ShizzleCulasse de ShizzleChiffon à tuyères de Shizzle\n\nVous recevrez également :\n\n"},
[4504] = {title = "Ultra collant", objective = "Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan.", description = "Je cherche à gagner de l’argent rapidement, <nom>. Si vous m’aidez à mettre au point ma dernière idée, je vous laisserai profiter un peu des bénéfices. Qu’en pensez-vous ?\n\nJe le savais !\n\nAllez vers les Fosses à goudron, au nord du Cratère d'Un'Goro et collectez du Goudron pour moi. Mais pas n’importe quel goudron, il me faut celui que vous trouverez sur les créatures qui vivent à proximité des Fosses. Le goudron de base habituel n’est tout simplement pas assez collant.\n\nLes créatures semblables à des plantes contiennent de la chlorophylle qui, mélangée au goudron, donne une substance ultra collante !", progress = "Tran'rek a encore réussi ; cette colle ultra forte va faire fureur !", completion = "Oui, ce goudron fait l'affaire...\n\nHé, attendez une minute, mes mains... Je ne peux plus les décoller...\n\nPeut-être que ce n'était pas une si bonne idée. Oh, mais attends ! Un diluant pour Goudron ultra collant ! Exactement ce qu'il nous faut !", rewards = "Vous recevrez :\n\n"},
[4505] = {title = "Puits de la corruption", objective = "Collecter un échantillon d’eau corrompue dans le Puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse.", description = "Certains prétendent que je suis exceptionnellement cruelle... Mais voir la Horde prendre l’avantage sur l’Alliance, par tous les moyens possibles, n’est simplement qu’un souhait ardent.\n\nJe m’intéresse en ce moment à un Puits de lune qui se trouve dans les ruines de Constellas, plus au sud, gardé par les satyres Jadefeu. Le Puits de lune, jadis un symbole de renouveau pour ces insupportables elfes de la nuit, est maintenant corrompu et utilisé pour produire encore plus de satyres.\n\nJ’ai une idée, <nom> : j’aimerais un échantillon de cette eau... pour tous mes petits félins.", progress = "C'est de la plus haute importance. Hâtez-vous, maintenant.", completion = "Très bien. Nous devons trouver un moyen d'utiliser cette corruption contre nos ennemis...", rewards = "Vous recevrez :\n\n"},
[4506] = {title = "Sabres corrompus", objective = "Amener le chaton de Winna au Puits de lune corrompu, le relâcher, puis le rapporter à Winna.\n\nUne fois de retour auprès de Winna, cliquer sur le chat pour le lui rendre.", description = "Cette eau corrompue peut être utilisée à notre avantage, <nom>. Avec une petite quantité de cette eau, mon chaton double en taille et en force... Ces chats pourraient être très utiles...\n\nVoilà, <nom>. Prenez ce panier à chat, et lâchez le chaton à proximité du Puits de lune dans les ruines de Constellas. Hé, hé !... Je crois que les résultats vous plairont !\n\nRamenez-moi le chat et je vous récompenserai largement.", progress = "Ne me dites pas que vous ne pouvez pas y retourner ! Allez !", completion = "Excellent !\n\nLes Réprouvés utiliseront tous les moyens pour briser l'Alliance ! L'eau corrompue sera sûrement utile pour nos futurs projets…", rewards = "Vous recevrez :\n\n"},
[4507] = {title = "Le pion prend la reine", objective = "Invoquer la Reine gorishi et la vaincre.\n\nApporter le Cerveau de reine gorishi à l’alchimiste Pestlezugg, à Gadgetzan.", description = "Voici l’appât. Dans le réseau de la ruche, il doit y avoir une sorte de cristal. Nous pensons que les silithides l’utilisent comme un outil de cohésion. Où se trouve ce cristal ? Sans doute dans les couvoirs de la ruche.\n\nUtiliser l’appât sur le cristal devrait faire sortir la reine ; mais attention, elle viendra sans doute escortée de quelques gardes. Tuez la reine et arrachez-lui son cerveau. Aussi dégoûtant que cela paraisse, nous en avons un ardent besoin. Bonne chance, <nom> !", progress = "Il est impératif de récupérer le cerveau de la reine pour l'étudier. D'après ce que nous savons, il est fort possible que ces silithides soient contrôlés par une intelligence maléfique. Je tremble en pensant à la chose qui peut contrôler des créatures aussi sournoises que les silithides, <nom>.", completion = "Fantastique, &lt;nom&gt; ! Nous avons remporté une victoire aujourd'hui. Cela nous prendra un moment pour comprendre vraiment ce que nous avons ici ; nous l'utiliserons à bon escient, ne vous inquiétez pas pour ça.\n\nComme pour les silithides, je doute que nous ayons exterminé toute trace de leur présence. Je dois bien admettre que c'était un vœu pieux.", rewards = "Vous recevrez :\n\n"},
[4508] = {title = "Le calme avant la tempête", objective = "Apporter le Rapport de Pestlezugg sur Un'Goro à Gracina Spiritmight, à Darnassus.", description = "Il faut faire parvenir mes recherches récentes et nos découvertes à ceux qui sauront en tirer bénéfice. Nous autres, ici à Gadgetzan, ne pouvons faire cela tout seuls.\n\nPortez mon dernier rapport à Gracina Spiritmight, dans Darnassus ; elle est toujours au Temple de la Lune, n’est-ce pas ? Elle a des amis qui sont des huiles de l’Alliance et si nous pouvions les impliquer dans cette affaire, <nom>, cela pourrait nous sauver la mise.", progress = "Ils sont fous, <nom> ! Ils sont incapables de comprendre qu'ils sont confrontés à un danger encore plus grand. La haine féroce qu'ils entretiennent à l'égard de la Horde provoquera notre perte à tous. Je ne sais pas quoi faire de plus pour leur faire prendre conscience de l'imminence de la menace silithide. Il faudrait qu'ils la constatent par eux-mêmes !\n\nJe suis désolée, vous m'apportiez des nouvelles ?", completion = "Bien que je sois réellement satisfaite, je ne suis pas certaine du bien que ça nous fera. L'Alliance ignore toutes les menaces qui ne sont pas relatives à la Horde et nos chefs eux-mêmes, à Darnassus, ne peuvent s'accorder sur la nature de cette menace. Les imbéciles comme Fandral Staghelm pensent que les silithides ne sont pas la menace surgie du passé que je pense. Son ignorance n'a d'égale que son arrogance.\n\nVous avez été confronté à la menace, &lt;nom&gt;. Nous devons rester mobilisés pour vaincre les silithides !", rewards = "Vous recevrez :\n\n"},
[4509] = {title = "Le calme avant la tempête", objective = "Apporter le Rapport de Pestlezugg sur Un'Goro à Zilzibin Drumlore, à Orgrimmar.", description = "Il faut faire parvenir mes recherches récentes et nos découvertes à ceux qui sauront en tirer bénéfice. Nous autres, ici à Gadgetzan, ne pouvons faire cela tout seuls.\n\nPortez mon dernier rapport à Zilzibin Drumlore, à Orgrimmar ; il est toujours chez lui, dans la partie supérieure du Drag, n’est-ce pas ? Il a des amis qui ont un rang prestigieux dans la Horde, et si nous pouvions les impliquer dans cette affaire <nom>, cela pourrait nous sauver la mise.", progress = "Ils sont fous, <nom> ! Ils sont incapables de comprendre qu'ils sont confrontés à un danger encore plus grand. La haine féroce qu'ils entretiennent à l'égard de l'Alliance, provoquera notre perte à tous. Je ne sais pas quoi faire de plus pour leur faire prendre conscience de l'imminence de la menace silithide. Il faudrait qu'ils le constatent par eux-mêmes !\n\nJe suis désolé, vous m'apportiez des nouvelles ?", completion = "Bien que je sois réellement satisfait, je ne suis pas certain du bien que ça nous fera. La Horde ignore toutes les menaces qui ne sont pas relatives à l'Alliance. Bien que Thrall lui-même puisse décider d'agir lorsque les faits se présentent à lui, il est assailli d'avis contradictoires. Ils nous auraient fait faire n'importe quoi, s'ils pensaient que ça pouvait nous permettre de prendre par surprise l'Alliance !\n\nVous avez pu constater la menace vous-même, &lt;nom&gt;. Nous devons rester attentifs pour vaincre les silithides !", rewards = "Vous recevrez :\n\n"},
[4510] = {title = "Le calme avant la tempête", objective = "Apporter le Reçu bancaire à Idriana, à la banque de Darnassus.", description = "<nom>, votre contribution a été incommensurable. Le jour viendra où je ferai de nouveau appel à vous pour lutter contre les silithides. Nous devons réfléchir sur ce que nous avons appris à Un'Goro. Je crains que mon hypothèse, selon laquelle les silithides viendraient d'Un'Goro, ne soit erronée... et qu’en fait il y ait une présence bien plus massive de ces créatures, autre part.\n\nApportez cette note à Idriana, à la banque. Elle prendra quelque chose dans mon coffre-fort que vous pourrez considérer comme un don, exprimant ma gratitude. Merci de votre assistance, brave <classe>.", progress = "Elune'adore, <classe>. Que puis-je faire pour vous aujourd'hui ?", completion = "Ce reçu bancaire m'autorise à retirer un objet du compte que Gracina Spiritmight possède chez nous et à vous le remettre. Des félicitations sont de rigueur !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe d'oubliSpallières de SnarkshawBottes d'Eschewal\n\nVous recevrez également :\n\n"},
[4511] = {title = "Le calme avant la tempête", objective = "Apporter le Reçu bancaire à Karus, à la banque d'Orgrimmar.", description = "<nom>, nous n'aurions pas été loin sans vous. Le jour viendra où je ferai de nouveau appel à vous pour lutter contre les silithides. Nous devons analyser ce que nous avons appris à Un'Goro. Je crains que mes hypothèses selon lesquelles les silithides prenaient leur origine dans Un'Goro ne soient fondées... et qu’en fait il y a une présence bien plus massive de ces créatures, autre part.\n\nApportez cette note à Karus, à la banque. Il vous donnera quelque chose de mon coffre-fort que vous pouvez considérer comme un don, exprimant ma gratitude. Merci de votre assistance, noble <classe>.", progress = "Zog zog ! Que puis-je faire pour vous aider aujourd'hui, <classe> ?", completion = "Ce reçu bancaire m'autorise à retirer un objet du compte que Zilzibin Drumlore possède chez nous et à vous le remettre. Des félicitations sont de rigueur !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe d'oubliSpallières de SnarkshawBottes d'Eschewal\n\nVous recevrez également :\n\n"},
[4512] = {title = "Un grand périple pour une petite gelée", objective = "Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Geardawdle, à Ironforge.", description = "J’ai beaucoup étudié les limons. Cela peut sembler bizarre, mais ils sont partout !\n\nJ’ai aidé une femme, à Menethil, à retrouver son sac, qui avait été dévoré par des limons. J’ai vu des membres de la Société royale des apothicaires d’Undercity qui en collectaient des échantillons, et je veux savoir pourquoi ! D’où est-ce que cela vient ?\n\nIl paraît qu’il y en a plus encore à Gangrebois. J’ai justement besoin de ces échantillons pour pouvoir continuer mes recherches. Je vais vous donner des pots que vous utiliserez pour collecter des échantillons sur les créatures mortes.", progress = "Certaines des expériences que j'ai menées sont fascinantes. Avec un peu plus de temps, je comprendrais la nature de ces créatures et quelle est leur influence sur le développement de la vie sur Azeroth... S'il y a un rapport quelconque.\n\nUne de mes théories, peu appréciée, implique que les Gelées et les Limons soient liés à la création de ce monde... Un peu comme s'ils étaient secrétés par lui.\n\nMais je ne pourrais le confirmer ou l'infirmer qu'en étudiant d'autres échantillons.", completion = "Des résultats impressionnants, &lt;nom&gt; ! Vous vous êtes suffisamment approché pour récupérer un échantillon de ces choses corrompues sans y laisser des plumes ! Merci. Oh, ces échantillons conviendront parfaitement. Je suis impatient de commencer les tests dessus.\n\nSi j'ai raison, je pourrais bien être l'un des plus grands scientifiques de la Ligue des explorateurs !\n\nCela prouvera aux nains que ce n'était pas une erreur de nous accueillir dans Ironforge après les incidents de Gnomeregan.", rewards = "Vous recevrez :\n\n"},
[4513] = {title = "Un grand périple pour une petite Gelée", objective = "Apporter 10 Pots remplis d'échantillon pur à Laris Geardawdle, à Ironforge.\n\nSi vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d’indices.", description = "Je vais avoir besoin de plus d’échantillons, <nom>. Mais ces échantillons doivent être purs. Je sais, je sais, \"Qu’est-ce que ça veut dire ‘purs’, Laris ?\". Je sais que ceux-ci sont corrompus... comme à Gangrebois. C’est ce qui rend ma réalisation tellement importante. Les Limons semblent s’adapter... se fondre dans l’endroit où ils vivent. J’ai besoin d’échantillons qui n’aient pas été souillés. Mais où ? Où ?\n\nBah ! <nom>, prenez ces pots, juste au cas où vous en trouveriez.", progress = "Tant de choses à prendre en compte. Mais qu'est-ce que ça signifie ? Et comment cela affecte-t-il la vie des peuples d'Azeroth ?", completion = "Vous en avez trouvé ? &lt;nom&gt;, vous êtes un véritable don des dieux. Je ne pourrai jamais vous remercier suffisamment pour votre dévouement.\n\nS'il vous plaît, acceptez ceci pour vous remercier. Du travail m'attend, mais si vous revenez plus tard j'aurai sûrement besoin de vos services à nouveau.\n\nMerci. Merci beaucoup.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de la brumeGantelets en laiton\n\nVous recevrez également :\n\n"},
[4521] = {title = "Gardiens sauvages", objective = "Trull Failbane de Gangrebois veut que vous tuiez 15 Chouettards enragés et 15 Chouettards éreintés.", description = "Le Berceau-de-l'Hiver se trouve juste après Grumegueule, au nord-est de Gangrebois. Vous connaissez ?\n\nJ’ai entendu dire que la région est peuplée de créatures appelées des Indomptables. On dit que ces bêtes gardent des secrets ; les secrets des elfes de la nuit.\n\nIl faut que nous découvrions ce qu’il se cache dans le Berceau-de-l'Hiver.\n\nIl paraît que les Chouettards éreintés se trouvent juste au sud de la route, et que d’autres appelés Chouettards enragés se trouvent au centre du Berceau-de-l'Hiver. Supprimez-les et accédez à cette terre.", progress = nil, completion = "C'est une excellente nouvelle, &lt;nom&gt;. Maintenant que ces créatures sont parties, nous pouvons nous aventurer plus loin dans le Berceau-de-l'Hiver. Vous êtes prêt pour un peu plus d'action ?", rewards = "Vous recevrez :\n\n"},
[4542] = {title = "Un message pour le poste de Librevent", objective = "Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent.", description = "<Courageux voyageur/Courageuse voyageuse>, les centaures ont intensifié leurs attaques dans les parages. Le Poste de Librevent doit être mis au courant de ces nouveaux assauts immédiatement ! Trouvez le garde-falaise Longhorn au Poste de Librevent, au sud-est, et faites-lui part de ce message urgent.\n\nSoyez sur vos gardes, évitez les membres du Totem sinistre qui se trouvent non loin d’ici... ils se comportent de façon étrange avec nous ces temps-ci.", progress = "Que voulez-vous, <classe> ? Un message urgent - pour moi ?", completion = "Encore des mauvaises nouvelles ! Ces centaures vont trop loin ! Ils ont attaqué un de mes convois de ravitaillement et ont tué tout le groupe. C'est un outrage, et il ne restera pas impuni !", rewards = "Vous recevrez :\n\n"},
[4561] = {title = "Test pour impuretés, le Cratère d'Un'Goro", objective = "Vous prenez un échantillon de gelée du Cratère d'Un'Goro et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de Pétri, vos échantillons de Gelée d'Un'Goro purifiés et d'autres restes.", description = nil, progress = "Vous prenez un échantillon de gelée du Cratère d'Un'Goro et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de Pétri, vos échantillons de Gelée d'Un'Goro purifiés et d'autres restes.", completion = "Vous ramassez la boîte de pétri qui contient l'échantillon de Limon. Le seul moyen de s'assurer de la pureté de l'échantillon est de l'ouvrir et de l'examiner vous-même. Idéalement, vous trouverez un échantillon qui remplit les critères énoncés par le Chimiste Fuely.", rewards = "Vous recevrez :\n\nEchantillon testé d'Un'Goro"},
[4581] = {title = "Kayneth Stillwind", objective = "Apporter la Note de Shindrell à Kayneth Stillwind au Chant des Forêts.", description = "Le druide Kayneth Stillwind m'a envoyé un message. Il veut savoir ce qui se passe sur notre côte et dans les forêts entourant Astranaar. Il craint que la corruption ne traverse Ashenvale… et il a raison.\n\nAllez, apportez-lui mon rapport. Vous le trouverez au sanctuaire de Chant des forêts, dans les Bois de Chantenuit à l'est.", progress = "Vous avez quelque chose pour moi ?", completion = "Ah, le rapport de Shindrell ! Merci beaucoup, &lt;nom&gt;. Shindrell est une bonne sentinelle, brave et volontaire. Je dois le lire pour comprendre pourquoi cette horreur se trace un chemin à travers Ashenvale.", rewards = "Vous recevrez :\n\n"},
[4601] = {title = "Le Décapeur 5200 !", objective = "Insérer un Objet sali dans le Décapeur 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine.", description = "L'étrange machine est là, au milieu des gnomes. Une petite plaque apposée indique : \"Décapeur 5200\", suivi d'un texte :\n\n\"La crasse et les résidus ruinent vos objets ? Le Décapeur 5200 est l'outil qu'il vous faut pour restaurer toute la brillance et l'éclat qu'ils méritent. Veuillez placer l'objet à décaper dans la machine, ainsi que trois pièces d'argent dans la fente prévue à cet effet et attendez un petit moment : vos objets de valeur en sortiront comme neufs\"", progress = "Il semble que la machine ne fonctionne que lorsqu'on y a déposé un objet à nettoyer et inséré trois pièces d'argent dans la fente prévue à cet effet. Si ces deux conditions sont réunies, le Décapeur 5200 devrait fonctionner...", completion = "Vous placez l'objet à nettoyer dans l'appareil et jetez trois pièces d'argent dans la fente. Le Décapeur 5200 se met à trembler et à trépider avec une violence inquiétante, tout à son oeuvre de décapage. Des grincements étranges, des battements sourds montent des entrailles de la machine tandis qu'elle vacille sur ses pieds...", rewards = nil},
[4602] = {title = "Le Décapeur 5200 !", objective = "Insérer un Objet sali dans le Décapeur 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine.", description = "L'étrange machine est là, au milieu des gnomes. Une petite plaque apposée indique : \"Décapeur 5200\", suivi d'un texte :\n\n\"La crasse et les résidus ruinent vos objets ? Le Décapeur 5200 est l'outil qu'il vous faut pour restaurer toute la brillance et l'éclat qu'ils méritent. Veuillez placer l'objet à décaper dans la machine, ainsi que trois pièces d'argent dans la fente prévue à cet effet et attendez un petit moment : vos objets de valeur en sortiront comme neufs\"", progress = "Il semble que la machine ne fonctionne que lorsqu'on y a déposé un objet à nettoyer et inséré trois pièces d'argent dans la fente prévue à cet effet. Si ces deux conditions sont réunies, le Décapeur 5200 devrait fonctionner...", completion = "Vous placez l'objet à nettoyer dans l'appareil et jetez trois pièces d'argent dans la fente. Le Décapeur 5200 se met à trembler et à trépider avec une inquiétante violence, tout à son oeuvre de décapage. Des grincements inquiétants, des battements sourds montent des entrailles de la machine tandis qu'elle vacille de tous côtés...", rewards = nil},
[4603] = {title = "Le Décapeur décape encore", objective = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !", description = nil, progress = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !", completion = "Le Décapeur 5200 se met en action, vrombissant et crachotant tandis qu'à l'intérieur, sur l'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !\n\nLe Décapeur 5200 s'arrête et émet un \"ding !\" pour indiquer qu'il a terminé son travail. La trappe s'ouvre, dévoilant une petite boîte, ornée d'un joli noeud.", rewards = "Vous recevrez :\n\nPaquet-cadeau du Décapeur"},
[4604] = {title = "Le Décapeur décape encore", objective = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !", description = nil, progress = "Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !", completion = "Le Décapeur 5200 se met en action, vrombissant et crachotant tandis qu'à l'intérieur, sur l'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !\n\nLe Décapeur 5200 s'arrête et émet un \"ding !\" pour indiquer qu'il a terminé son travail. La trappe s'ouvre, dévoilant une petite boîte, ornée d'un joli noeud.", rewards = "Vous recevrez :\n\nPaquet-cadeau du Décapeur"},
[4605] = {title = "Le Décapeur 5200 !", objective = "D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.\n\nBon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non...", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPaquet-cadeau du Décapeur"},
[4606] = {title = "Le Décapeur 5200 !", objective = "D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.\n\nBon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non...", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPaquet-cadeau du Décapeur"},
[4621] = {title = "En avant toute, amiral !", objective = "Tuer l'amiral Seahorn et le baron Revilgaz de Baie-du-Butin, puis retrouver l'amiral Firallon à bord du Voile cramoisi, au large des côtes de la vallée de Strangleronce.", description = "Écoutez bien... à cause de la puissance de Baie-du-Butin, nous aut’ de la Voile sanglante, nous ne pouvons pas naviguer où bon nous semble et piller c’qu’on veut. Si vous pouviez mettre un couteau dans l'dos de l’amiral Seahorn, on s'attirerait plus les foudres des navires de Baie-du-Butin. Et si vous pouviez faire de même avec le baron Revilgaz, on aurait plus à plier devant leurs lois.\n\nSi vous voulez devenir un d’nos amiraux, ouaip, un AMIRAL, allez tuer ces deux là, comme j’vous l’ai dit. Allez, et ne revenez que quand ça sera faitVous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBicorne d'amiral de la Voile sanglante"},
[4641] = {title = "Votre place en ce monde", objective = "Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest.", description = "Vous avez maintenant l’âge de vous battre au nom de la Horde, <nom>, et de faire des conquêtes pour le Chef de guerre.\n\nOui...\n\n<Kaltunk vous considère.>\n\nVous vous en sortirez très bien.\n\nJe ne doute pas que vous aspiriez à trouver un grand dragon ou un démon et de les étrangler à mains nues, mais il serait plus sage de commencer par quelque chose de moins redoutable....\n\n<Kaltunk rit.>\n\nAllez voir Gornek, il sera en mesure de vous assigner une mission plus adaptée à quelqu’un de votre âge, <classe>. Vous trouverez Gornek dans l’Antre, plus à l’ouest.", progress = nil, completion = "Encore une autre des recrues de Kaltunk, hein ?\n\nLa Horde doit être dans un bien piteux état si c'est là tout ce qu'elle peut produire. Enfin... nous pensons que vous êtes prêt à quitter la vallée et à devenir un fier guerrier de la Horde.", rewards = "Vous recevrez :\n\n"},
[4642] = {title = "Trafic d'influences", objective = "Apporter un Echantillon de Limon mélangé au chimiste Fuely à Undercity.", description = "Voici un peu de Limon créé à partir des échantillons récupérés à Gangrebois. Portez cette caisse au Cratère d'Un'Goro et trouvez du Limon pur... la variété primitive fera parfaitement l’affaire. Quand vous serez assez près, libérez le Limon qui est dans la caisse, et voyez comment les deux variétés interagissent.\n\nQuand l’expérimentation sera terminée, rapportez-moi un échantillon de ce qui reste, quoi que cela soit. Je vous attendrai chez l'Apothicaire.", progress = "Comment se passe l'expérience, <nom> ? Je vais continuer à étudier les échantillons que vous m'avez rapportés ; je commence à comprendre pourquoi ces créatures intéressent Dame Sylvanas. Si elles sont issues des Dieux très anciens, qui sait quels bénéfices on pourrait en retirer.", completion = "Oh, parfait, &lt;nom&gt;. C'est merveilleux.\n\nQuelle histoire. Qui aurait cru que ces deux-là interagiraient de cette manière... Il faut que je passe plus de temps à observer les retombées environnementales qui ont provoqué les mutations de ces créatures.\n\nJe vais continuer mes recherches. Peut-être en reparlerons-nous bientôt. Jusque là je vous souhaite bonne chance.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau des chimistesBlouse de chimiste\n\nVous recevrez également :\n\n"},
[4661] = {title = "Test de corruption, Gangrebois", objective = "Vous prenez un échantillon de gelée de Gangrebois et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de pétri, vos échantillons de Gelée de Gangrebois altérés et d'autres restes.", description = nil, progress = "Vous prenez un échantillon de gelée de Gangrebois et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de pétri, vos échantillons de Gelée de Gangrebois altérés et d'autres restes.", completion = "Vous ramassez la boîte de pétri qui contient l'échantillon de Limon. Le seul moyen de s'assurer de la pureté de l'échantillon est de l'ouvrir et de l'examiner vous-même. Idéalement, vous trouverez un échantillon qui remplit les critères énoncés par le Chimiste Fuely.", rewards = "Vous recevrez :\n\nEchantillon testé corrompu"},
[4681] = {title = "Échouage", objective = "Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l’ouest d’Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine.", description = "Cette créature échouée n’est pas un incident isolé, ici à Sombrivage. Il y en a plus le long de la côte et même dans l’eau. Je voudrais que vous alliez étudier un autre de ces cas dans les eaux à l’ouest d’Auberdine, non loin d’un navire englouti. Revenez avec tout ce que vous aurez pu récupérer qui nous aiderait dans nos recherches.\n\nDe même, pendant vos voyages, vous pourriez tomber sur d’autres créatures. Bien sûr, si vous deviez découvrir quoi que ce soit, vous n’oublieriez pas de nous en faire part !", progress = "Une fois que vous aurez inspecté les restes de la créature qui se trouve dans l'eau à l'ouest, je pourrai faire mon rapport au Temple de la Lune à Darnassus. Nous comprendrons peut-être mieux pourquoi ces créatures décident de mettre fin à leur vie en venant s'échouer sur les rivages de Sombrivage.", completion = "Vous avez été d'une aide inestimable aujourd'hui ; désormais nous avons une chance non négligeable d'élucider le mystère de ces créatures qui ont choisi de venir s'échouer sur la côte de Sombrivage. L'idée qu'elles essaient peut-être de fuir les rivages de Teldrassil est inquiétante. Si vous en rencontrez d'autres dans vos voyages, informez-m'en. Nos recherches n'en sont qu'au début.\n\nVeuillez accepter ceci, de la part du temple de la Lune, pour vous remercier de vos efforts. Merci, &lt;nom&gt; !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes des mareyeursCeinture d'herbe-sècheBrassards de coquillage\n\nVous recevrez également :\n\n"},
[4701] = {title = "Abattez-la", objective = "Allez au Pic Blackrock et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs.", description = "Vous avez certainement vu les worgs que les orcs Blackrock commandent.\n\nEt c'est curieux : peu importe combien nous en tuons, leur nombre ne diminue jamais. Mes éclaireurs m'ont rapporté que les worgs sont élevés, entraînés au pic Blackrock, la capitale des orcs Blackrock, et finalement exportés. Allez jusqu'au pic Blackrock et découvrez la source de cette menace. Cherchez... et détruisez.\n\nBonne chance, <nom>. Que Cénarius vous protège...", progress = nil, completion = "Ne pensez plus à sa souffrance, &lt;nom&gt;. La bête était corrompue ; c'était un produit de la magie noire. Vous avez rendu un grand service à l'Alliance et vous serez récompensé.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe d'AstoriaPourpoint bec-de-corbinCuirasse d'écailles de jade\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4721] = {title = "Les gardiens sauvages", objective = "Trull Failbane à Gangrebois veut que vous chassiez 10 Chouettards berserk au Berceau-de-l'Hiver.", description = "Des messagers sont revenus du Berceau-de-l'Hiver, reportant qu’il y a une série de petites grottes au sud de la région. Il semble qu’il y ait des Indomptables dans les environs de ces grottes. S’ils sont employés à garder une chose de valeur, je suppose que c’est là que nous trouverons ce que nous cherchons.\n\nCeux-là seront plus coriaces que les précédents, <nom>. Il semble que ces créatures aient été rendues folles par ce qu’elles sont justement censées garder.", progress = nil, completion = "J'ai beaucoup de respect pour le travail bien fait, &lt;nom&gt;. Maintenant, nous pouvons nous mettre en route, avec nos plans, pour le Berceau-de-l'Hiver.", rewards = "Vous recevrez :\n\n"},
[4722] = {title = "La tortue de mer échouée", objective = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", description = "Vous trouvez le cadavre d’une tortue de mer qui s’est échouée sur la côte de Sombrivage, il y a quelque temps. les murlocs ont établi un campement autour de la créature et ont mis la main sur ses restes. Il apparaît cependant qu’il subsiste quelques échantillons valables à prélever sur la dépouille ; et Gwennyth Bly'Leggonde, à Auberdine, pourrait en avoir l’usage.", progress = "Bonjour <nom>. Vous avez découvert de nouvelles créatures échouées sur le rivage ?", completion = "Une nouvelle découverte à étudier, très bien, &lt;nom&gt; ! Ces restes seront examinés en détails une fois à Darnassus. Veuillez accepter ceci en échange des échantillons que vous nous avez fournis pour nos études.", rewards = "Vous recevrez :\n\n"},
[4723] = {title = "La créature marine échouée", objective = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", description = "Les restes d’un batteur gigantesque, bien plus grand que ceux qu'on s'attendrait à trouver à Sombrivage, gisent, échoués sur la côte de la Lisière des brumes. La présence de cette créature à cet endroit est un mystère ; les murlocs qui festoient sur la carcasse semblent bien trop faibles pour avoir chassé et abattu la bête tout seuls.\n\nIl reste suffisamment à prélever sur la dépouille pour en rapporter un échantillon que Gwennyth Bly'Leggonde, à Auberdine, pourrait étudier.", progress = "Peut-être un jour, trouverons-nous le moyen d'empêcher ces pauvres créatures de venir s'échouer sur les côtes de Sombrivage. En attendant, nous devons continuer nos recherches !\n\nSalutations <nom> ; quelles nouvelles apportez-vous ?", completion = "Une autre découverte ; bravo &lt;nom&gt; ! Ces restes seront étudiés dès qu'ils arriveront à Darnassus. Veuillez accepter cette récompense en échange de ce que vous nous avez fourni.", rewards = "Vous recevrez :\n\n"},
[4724] = {title = "La maîtresse de meute", objective = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe.", description = "Certains disent que les worgs contrôlés par les orcs Blackrock ont été créés par une force surnaturelle. D’autres prétendent qu’ils ne sont pas de vrais worgs mais une espèce de chien démon, offert aux orcs par un Seigneur des abîmes.\n\nLa vérité est encore moins romantique que ça, mais tout aussi effrayante. Les worgs Blackrock viennent de Halycon et son compagnon. Halycon est la gigantesque mère des worgs. Son compagnon ? Personne n’est jamais revenu pour raconter l’histoire de celui-là.\n\nFrappez au coeur des worgs. Détruisez Halycon... et, <nom>, surveillez vos arrières.", progress = nil, completion = "De jeunes bêtes enragées ? Gizrul l'esclavagiste ? Et vous êtes encore là pour le raconter ? Incroyable ! Une récompense bien méritée !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe d'AstoriaPourpoint bec-de-corbinCuirasse d'écailles de jade\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4725] = {title = "La tortue de mer échouée", objective = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.", description = "D’autres restes de tortue gisent, échoués le long de la côte. Cette dépouille a une espèce de chariot attaché à sa carapace. Il semble que la créature ait été conduite sur le littoral et qu’elle ne se soit pas échouée, à la différence des autres. Les murlocs Grisebrume habitent maintenant les restes de cette créature, se régalant sur la carcasse.\n\nDans le chariot, vous trouvez une boîte avec d’étranges inscriptions ; peut-être Gwennyth Bly'Leggonde, à Auberdine, pourrait comprendre de quoi il s'agit.", progress = "Quel plaisir de vous revoir, <nom>. Nous nous efforçons de percer le mystère des majestueuses créatures marines qui s'échouent sur les rivages de Sombrivage, mais chaque fois qu'une question est résolue, deux autres apparaissent.\n\nÊtes-vous ici pour nous aider dans nos recherches ?", completion = "J'ai entendu parler de tels chariots attachés au dos de tortues. Ils sont utilisés par les nagas pour le combat et pour transporter les provisions sur terre. Les marques que vous avez trouvées sur la boîte sont celles des nagas ; cela explique leur présence aussi loin au nord de Sombrivage.\n\nJe vais envoyer cette boîte à Darnassus avec le reste de vos découvertes. Tenez, ceci est pour vous. Merci pour votre aide.", rewards = "Vous recevrez :\n\n"},
[4726] = {title = "L'essence de rejeton", objective = "Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes.", description = "J'étudie les draconiens des Steppes ardentes depuis des semaines et je pense que j’ai finalement fait une découverte capitale ! J’ai créé un outil que j’ai appelé le Draco Incarcinatrix 900 et qui peut capturer l’essence des rejetons de jeunes dragons !\n\nEnfin, je crois...\n\nVoici, prenez l’outil et utilisez-le sur les Rejetons des Steppes ardentes. Pendant qu’ils sont sous l’effet de l’outil, tuez les Rejetons et leur essence devrait être capturée.\n\nSi cela fonctionne, c’est formidable ! Rapportez-moi les échantillons que je puisse les étudier !", progress = "Vous avez l'Essence de Rejeton, <nom> ? Je suis impatient de l'étudier.\n\nEn plus... mon client n'est pas le type de personne que l'on contrarie.", completion = "Ça a fonctionné ! Vous avez l'essence ! Très bien, &lt;nom&gt; ! Très bien !\n\nCette essence est inestimable pour mes recherches. J'espère qu'un jour j'apprendrai à capturer des dragonnets vivants ou peut-être leurs œufs. Si je trouve un moyen d'y arriver, je serais enviée par toutes les personnes qui étudient les dragons !\n\nMon patron sera heureux aussi, et comme je l'ai dit plus tôt, c'est quelqu'un qu'il faut ménager...", rewards = "Vous recevrez :\n\n"},
[4727] = {title = "La tortue de mer échouée", objective = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", description = "Les restes d’une tortue de mer gisent sur le sable des plages du nord de Sombrivage. Les murlocs Grisebrume n'ont peut-être pas encore repéré cette carcasse ; ou alors, ils l'ont rejetée pour quelque étrange raison. Il subsiste néanmoins de quoi prélever un échantillon et le rapporter à Gwennyth Bly'Leggonde, à Auberdine, afin que ceux du temple de la Lune puissent l’étudier.", progress = "Re-bonjour, <nom>. Avez-vous trouvé d'autres créatures échouées dont l’existence devrait être communiquée au Temple de la lune ?", completion = "C'est intéressant que les murlocs n'aient pas été présents sur ce site. Nous nous en souviendrons lorsque nous étudierons les restes de la créature ! Merci pour vos efforts, &lt;nom&gt; ; le temple de la Lune souhaite que je vous remette ça pour récompenser vos efforts.", rewards = "Vous recevrez :\n\n"},
[4728] = {title = "La créature marine échouée", objective = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", description = "La dépouille de ce qui semble être un immense mammifère marin gît, éviscérée, sur la plage. Une brouette et divers outils traînent, abandonnés, à côté de cette énorme bête échouée, comme si quelqu’un avait tenté d’en faire l’autopsie. Bien que les murlocs aient dépouillé la créature, il reste possible de prélever sur elle les échantillons qui intéressent Gwennyth Bly'Leggonde, à Auberdine.", progress = "Salutations à nouveau, <nom> ! Qu'est-ce qui vous amène à Auberdine ? Vous venez nous faire part d'une nouvelle découverte ?", completion = "Ah, je crois que vous en avez découvert un qui était étudié, à l'origine, par la Ligue des Explorateurs. Ils sont implantés à Sombrivage et ils ont raconté qu'ils étudiaient une des créatures échouées lorsqu'ils ont été chassés par les murlocs. Il semble que vous ayez réussi là où nous avons échoué. Veuillez accepter cette récompense de la part du temple de la Lune.", rewards = "Vous recevrez :\n\n"},
[4729] = {title = "Les animaux exotiques de Kibler", objective = "Aller au Pic Blackrock et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler.", description = "Vous vous demandez certainement ce que je fais là. Regardez ces cages ! Est-ce que ce n’est pas évident ?\n\nJ’adore les animaux et… le commerce. Je traque les animaux exotiques et je les revends, domestiqués et doux comme des petits chats, aux gens riches.\n\nVous vous demandez certainement, \"Que puis-je faire pour vous, Kibler ?\" La réponse est simple : prenez cette cage et trouvez des jeunes worgs. En récompense j'en domestiquerai un pour vous !", progress = "<Kibler est occupé, il discute avec Opus.>", completion = "Vous les avez eus au bon moment, &lt;nom&gt;. Plus tard, nous n'aurions rien pu en faire ! Donnez-moi une minute et je prépare le petit gars pour que vous le rameniez chez vous.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCaisse de worg"},
[4730] = {title = "La créature marine échouée", objective = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", description = "La carcasse à moitié dévorée de ce qui a été un mammifère géant gît sur la plage. Une bande de murlocs, plus forts que ceux qui étaient près d’Auberdine, vivent auprès des restes de la créature. Il subsiste cependant de quoi prélever sur les os de la créature des échantillons qui pourraient être apportés à Gwennyth Bly'Leggonde, à Auberdine.", progress = "Bonjour à nouveau, <nom> ! Vous venez nous faire part d'une nouvelle découverte ?", completion = "Les ossements que vous avez découverts proviennent des mammifères marins qui peuplent les eaux qui entourent la base de Teldrassil. Ils ne sont pas réputés pour venir s'échouer sur les plages comme nous avons pu le constater avec les batteurs. Je me demande pourquoi ces créatures agissent de la sorte ? Peut-être que l'étude de ces restes nous apportera des éléments de réponse.\n\nEncore une fois, merci pour votre aide. Veuillez accepter cette modeste récompense de la part du Temple de la lune.", rewards = "Vous recevrez :\n\n"},
[4731] = {title = "La tortue de mer échouée", objective = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.", description = "Un autre tas de restes de tortue de mer gît, échoué, sur le littoral. Un chariot est attaché à la carapace de la tortue. Peut-être cette créature a-t-elle été conduite sur le littoral par quelqu’un et ne s'est-elle pas échouée, à la différence des autres. Les puissants murlocs Grisebrume ont fait de la carcasse leur habitation.\n\nDans le chariot, vous trouvez une boîte avec d’étranges inscriptions ; peut-être Gwennyth Bly'Leggonde, à Auberdine, pourra-t-elle les déchiffrer.", progress = "Salut à nouveau, <nom>. Le travail que vous avez accompli au service du Temple de la Lune est incroyable. Aurons-nous la chance de pouvoir compter sur vous encore un peu ?", completion = "J'ai entendu parler de ce chariot attaché au dos de cette tortue. C'est un chariot de naga, utilisé pour le combat et pour transporter les provisions sur terre. Les marques que vous avez trouvées sont celles des nagas ; peut-être que la créature que vous avez dénichée a été tuée, pendant qu'elle se rendait plus loin au sud... à Ashenvale, qui sait ?\n\nJe vais m'assurer d'envoyer cette boîte à Darnassus avec le reste de vos découvertes. Tenez, ceci est pour vous. Merci pour votre aide.", rewards = "Vous recevrez :\n\n"},
[4732] = {title = "La tortue de mer échouée", objective = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", description = "Vous trouvez le cadavre d’une tortue de mer qui s’est échouée sur la côte de Sombrivage, il y a quelque temps. Les murlocs Grisebrume ont nettoyé la carcasse et campent maintenant autour des restes de la créature. Il apparaît cependant qu’il subsiste quelques échantillons valables à prélever sur la dépouille. Gwennyth Bly'Leggonde, à Auberdine, pourrait en avoir l’usage.", progress = "Salutations à nouveau <nom> ; avez-vous découvert d'autres choses dont vous souhaiteriez parler au Temple de la Lune ?", completion = "Vous avez trouvé d'autres créatures échouées, &lt;nom&gt; ? On pouvait trouver les tortues de mer le long de la base de Nordrassil, elles avaient pour habitude de s'y accoupler, avant sa destruction. Depuis la naissance de Teldrassil, nous avons constaté que le nombre de ces créatures diminuait. Certaines d'entre elles, que nous avons découvertes, venaient finir leur vie à cet endroit pour une raison inconnue.\n\nPeut-être pourrez-vous nous aider à élucider ce mystère. Veuillez accepter ceci en échange des restes que vous nous avez rapportés pour nos recherches.", rewards = "Vous recevrez :\n\n"},
[4733] = {title = "La créature marine échouée", objective = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", description = "Les restes de ce qui semble être un batteur géant ont échoué dans la crique rocheuse du Rivage du Crépuscule. Ce Frappeur est bien plus grand que la plupart des Frappeurs de la région. D'où qu'elle vienne, cette créature ne semble pas être native de Sombrivage.\n\nBien qu'il ne reste que des morceaux de la créature, il y a suffisamment de matière pour obtenir un échantillon correct pour Gwennyth Bly'Leggonde d'Auberdine.", progress = "Elune soit louée ; Je suis heureux de vous revoir à nouveau, <nom>. Le Temple de la Lune enquête sur un étrange phénomène qui frappe les côtes de Sombrivage. Peut-être en savez-vous plus ?", completion = "Les dimensions du batteur que vous mentionnez sont surprenantes. Les plus vieux batteurs de cette région n'atteignent pas un dixième de cette taille. Vous pouvez en trouver de plus grands près de Teldrassil. Ils ont presque disparu. Je ne peux pas m'empêcher de me demander si le fait que ces créatures viennent s'échouer sur ces plages n'a pas un rapport.\n\nEn attendant que nous ayons analysé les os que vous avez rapportés, veuillez accepter ceci de la part du Temple de la lune. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4734] = {title = "Un oeuf congelé", objective = "Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie.", description = "<nom>, je travaille sur un nouvel appareil : l’Oeufilloscope ! Il est destiné à projeter une salve d’énergie réfrigérante sur l’oeuf d’un dragon noir... ce qui le congèle instantanément ! Pourriez-vous le tester pour moi ?\n\nJ'ai entendu que très haut sur le pic Blackrock, il y a une colonie de dragons où ils couvent leurs oeufs. C’est là que vous devrez aller tester l’Oeufilloscope. Vous reviendrez ensuite me dire comment il a fonctionné !\n\nEt ne vous inquiétez pas, les oeufs de dragons congelés sont tout à fait inoffensifs ; ce sont ceux qui ne seront pas congelés qui seront le véritable souci !", progress = "<nom>, avez-vous testé l'Oeufilloscope ?", completion = "Ça a marché ? Splendide ! Je savais que ça serait le cas !\n\nPendant que vous étiez parti j'ai travaillé sur une nouvelle version de l'Oeufilloscope. Celui-ci a une portée plus longue.\n\nVoilà, vous pouvez vous en procurer un au cas où vous retourneriez au pic Blackrock.", rewards = "Vous recevrez :\n\nOeufilloscope"},
[4735] = {title = "La collecte d'oeufs", objective = "Apporter 8 Oeufs de dragon collectés et le Module collectronique à Tinkee Steamboil à la Corniche des flammes dans les Steppes Ardentes.", description = "<nom>, je suis disponible pour les oeufs de dragon ! Tenez, prenez ce Module collectronique. Il est destiné à l’extraction et au transport des oeufs de dragon. Retournez à la Colonie et utilisez le Module pour collecter les oeufs.\n\nN’oubliez pas de les congeler avant ou ils risquent d’éclore avant que vous ne puissez avoir fini de les collecter !\n\nQuand vous aurez assez d’oeufs, rapportez-les-moi !", progress = "Avez-vous les oeufs, <nom> ? Mon client a entendu dire que vous les collectiez pour moi et il est impatient de pouvoir les tenir dans ses mains !", completion = "Wow, vous les avez ! Le Module collectronique a fonctionné ! Je suis un génie !\n\nMerci, &lt;nom&gt;. Mon client sera très content de récupérer ces oeufs...", rewards = "Vous recevrez :\n\n"},
[4736] = {title = "À la recherche de Menara Voidrender", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Bonjour, <nom>. Vos progrès sont rapides, si rapides que je pense que vous méritez une récompense ; de plus, vous avez su résister à la corruption des arcanes, pour l’instant.\n\nSi cela vous intéresse, allez voir Menara Voidrender, à Ratchet. Elle réside en ce moment dans la tour de Strahad Farsan, au-dessus de Ratchet.\n\nElle n’est pas très amicale, <nom>, n’en espérez ni accueil ni éloges. Mais si vous travaillez dur, elle saura s’occuper de vous.", progress = nil, completion = "Ah, c'est Briarthorn qui vous envoie. Bien. Ma parole a été répandue suffisamment loin pour attirer de futurs étudiants. Cela me réjouit.\n\nC'est typique des gens comme nous, &lt;nom&gt;, de faire front ensemble sans tenir compte de la race. C'est particulièrement important, parce que ceux à qui nous avons à faire ne ferons pas de discrimination si nous n'arrivons pas à les apaiser ou les contrôler.\n\nJ'ai l'impression que vous avez beaucoup appris, et si vous le souhaitez, je vous aiderai à créer des outils pour améliorer vos compétences.", rewards = "Vous recevrez :\n\n"},
[4737] = {title = "À la recherche de Menara Voidrender", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Hum, vous vous efforcez encore d'augmenter votre puissance. Mais ce n’est qu’une question de temps avant que la corruption ne vous soumette et que ne vous deveniez l’esclave de ce que vous combattez.\n\nPfah ! Quelle folie ! Le temps me donnera raison.\n\nIl semble pourtant que tous ne soient pas d’accord avec Zevrost et que Menara veuille créer des objets pour augmenter et exploiter votre force. Si cela vous intéresse, allez à Ratchet, dans les Tarides. Elle est là-bas, dans la tour qui domine la ville.", progress = nil, completion = "Ah, c'est Zevrost qui vous envoie. Bien. Ma parole a été répandue suffisamment loin pour attirer de futurs étudiants. Cela me réjouit.\n\nC'est typique des gens de votre espèce, &lt;nom&gt;, de grouper ensemble sans tenir compte de la race. C'est particulièrement important, parce que ceux à qui nous avons à faire ne ferons pas de discrimination si nous n'arrivons pas à les apaiser ou les contrôler.\n\nJ'ai l'impression que vous avez beaucoup appris, et si vous le souhaitez, je vous aiderai à créer des outils pour améliorer vos compétences.", rewards = "Vous recevrez :\n\n"},
[4738] = {title = "À la recherche de Menara Voidrender", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Que les choses soient bien claires, <nom> : je ne crois pas que vous ayez les moyens d’assumer de telles responsabilités. Je ne crois pas qu’un novice doive être impliqué dans la fabrication d’un objet de grande puissance, surtout un novice aussi peu entraîné.\n\nMais cela ne relève pas de ma décision. Ce sont ceux qui ont décidé de vous octroyer la puissance d’un tel objet qui sont seuls juges.\n\nSi vous voulez en apprendre plus, je vous suggère d’aller voir Menara Voidrender, à Ratchet. Elle réside dans la tour qui domine la ville.", progress = nil, completion = "Ah, c'est Demisette qui vous envoie. Bien. Ma parole a été répandue suffisamment loin pour attirer de futurs étudiants. Cela me réjouit.\n\nC'est typique des gens de votre espèce, &lt;nom&gt;, de grouper ensemble sans tenir compte de la race. C'est particulièrement important, parce que ceux à qui nous avons à faire ne ferons pas de discrimination si nous n'arrivons pas à les apaiser ou les contrôler.\n\nJ'ai l'impression que vous avez beaucoup appris, et si vous le souhaitez, je vous aiderai à créer des outils pour améliorer vos compétences.", rewards = "Vous recevrez :\n\n"},
[4739] = {title = "À la recherche de Menara Voidrender", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Vous ! Oui, vous, le <classe> !\n\nVous n’avez pas l’équipement complet, mais il est évident que vous êtes au point ; en témoigne l’aplomb qui émane de votre présence.\n\nMenara Voidrender pourrait vous apprendre deux trois choses, si vous le voulez. Elle passe son temps à enseigner à de jeunes apprentis l’art des arcanes. Elle fait même des cadeaux à ceux qui réussissent ses tests.\n\nAllez à Ratchet dans les Tarides, si cela vous intéresse. Elle réside dans la tour de Strahad, au-dessus de la ville.", progress = nil, completion = "Ah, Kaal vous envoie. Bien. Ma parole a été répandue suffisamment loin pour attirer de futurs étudiants. Cela me réjouit.\n\nC'est typique des gens de votre espèce, &lt;nom&gt;, de grouper ensemble sans tenir compte de la race. C'est particulièrement important, parce que ceux à qui nous avons à faire ne ferons pas de discrimination si nous n'arrivons pas à les apaiser ou les contrôler.\n\nJ'ai l'impression que vous avez beaucoup appris, et si vous le souhaitez, je vous aiderai à créer des outils pour améliorer vos compétences.", rewards = "Vous recevrez :\n\n"},
[4740] = {title = "On recherche : Fondeboue !", objective = "Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.\n\nAnnoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine.", description = "Votre attention !\n\nUne récompense est offerte pour la mort du murloc \"Fondeboue\". Cette bête immonde est au moins responsable de la mort d'une Sentinelle et du sabordage de deux navires de fret, dans les eaux de Sombrivage !\n\nFondeboue a été aperçu en dernier dans un camp murloc au sud d’Auberdine, et l’on pense qu’il est là pour protéger ce camp. Tous ceux qui veulent réclamer la récompense doivent le faire auprès de la Sentinelle Glynda Nal'Shea, à Auberdine.\n\nLe conseil d'Auberdine", progress = nil, completion = "Bien, il semble que vous ne soyez pas là que pour vous renseigner ! Les citoyens seront heureux d'apprendre que ce soir ils pourront dormir en sécurité.\n\nAujourd'hui, vous avez été le bras justicier du peuple d'Auberdine, &lt;nom&gt;. C'est pour cela que je compte vous offrir une récompense digne... du véritable héros d'Auberdine.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGarde-bras de bûcheronBrassards de la dorsaleCeinturon des brisants\n\nVous recevrez également :\n\n"},
[4741] = {title = "Les gardiens sauvages", objective = "Trull Failbane à Gangrebois veut que vous chassiez 13 Chouettards lunaires.", description = "Dans la partie nord du Berceau-de-l'Hiver, les Indomptables sont encore plus féroces. Nous devons continuer nos mesures là-bas.\n\nChassez les Chouettards lunaires du Berceau-de-l'Hiver, et explorez la zone où ils vivent.\n\nC’est un terrain dangereux, mais je sais que vous êtes à la hauteur de la tâche. Revenez me voir après avoir tué 13 Indomptables.", progress = nil, completion = "J'ai l'impression que vous aimez votre travail. Et je crois que l'on a découvert quelque chose ici.", rewards = "Vous recevrez :\n\n"},
[4742] = {title = "Le sceau de l'ascension", objective = "Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.\n\nLes généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe.", description = "Vous remarquez que le Sceau d'ascension non décoré comprend trois logements vides. Chacun de ces logements doit être occupé par une gemme de commandement. Enfin, le seigneur Wyrmthalak, maître de la citadelle inférieure, forgera le sceau dans les flammes des dragons noirs.\n\nComprenez cela, mortelle créature : les chances pour que les trois généraux de la citadelle inférieure portent une gemme sur eux sont extrêmement minces. Vous devrez être <vigilant/vigilante> lors de votre quête. Que votre volonté ne fléchisse point !", progress = "Courage et patience avant tout, mortel !", completion = "&lt;La silhouette de Vaelan s'estompe pendant un moment.&gt;\n\n&lt;Les morceaux que vous avez récupérés ont disparu.&gt;\n\nLe Sceau d'ascension brut est prêt. Il est temps de passer à la dernière étape.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4743] = {title = "Le sceau de l'ascension", objective = "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.\n\nA cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !", description = "En dehors de ceux de la citadelle supérieure, rares sont les draconiens noirs qui soient capables de forger le sceau avec les flammes de leur souffle. Wyrmthalak est l’un d'eux, mais sa volonté est inébranlable.\n\nVous devez voyager dans la tourbière du Ver, dans le marécage d'Âprefange. Vous y rencontrerez un ancien drake appelé Brandeguerre. Vous devrez briser sa volonté, <nom>, puis utiliser cet orbe sur lui, alors qu'il est affaibli. Vous n’aurez que quelques secondes pour contrôler son esprit et attiser les flammes qui forgeront le sceau.", progress = "Ne perdez pas de temps, mortel. Nefarian travaille sans relâche pour libérer ce mal sur notre monde.", completion = "Ne bougez pas pendant que je termine cette incantation de protection.\n\n&lt;Les yeux de Vaelan se fixent sur les deux orbes de flammes.&gt;\n\nLe Sceau d'ascension est terminé...\n\nSachez que j'ai imprégné cet artefact de quelques vertus protectrices puissantes. Quand vous serez au coeur des ténèbres et que tout vous semblera perdu, vous pourrez compter sur le pouvoir des dragons rouges.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau d'ascension"},
[4761] = {title = "Thundris Windweaver", objective = "Parler à Thundris Windweaver, à Auberdine.", description = "Thundris Windweaver doit être averti du résultat de votre reconnaissance au camp furbolg. C’est l'un des anciens d’Auberdine qui aide à régler les affaires courantes du village. Allez lui faire part de vos découvertes sur la situation des furbolgs.\n\nIl sait certainement pourquoi ils ont été corrompus. Peut-être pourriez-vous travailler avec lui au rétablissement de l'équilibre naturel à cet endroit !", progress = nil, completion = "Bien joué, &lt;classe&gt;. Les informations que vous rapportez à propos des furbolgs tombent à point pour les gens d'Auberdine. Depuis quelques temps, en plus des créatures devenues hostiles, nous devons faire face à la corruption de la forêt elle-même. Heureusement, vous avez l'air de pouvoir venir en aide à Auberdine en ces temps troublés.", rewards = "Vous recevrez :\n\n"},
[4762] = {title = "La Bondissante", objective = "Aller au nord d’Auberdine, à la première chute d’eau, le long de la Bondissante et prélever un échantillon de l’eau de l’étang.\n\nRetourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante.", description = "La Bondissante est en train de se corrompre. Ce fleuve se déverse dans la Lisière des brumes, et je crains qu’il ne contamine bientôt Auberdine. Je soupçonne les furbolgs Noirbois, qui se trouvent plus haut sur le fleuve, d’être la cause de de cette infection ; bien que je ne pense pas qu’ils en soient les vrais responsables.\n\nPrenez ce tube de prélèvement et allez à l'embouchure de la rivière, au nord. Marchez jusqu’à la première cascade et faites un prélèvement d'eau sur place. Vous verrez un pont au-dessus de vous. Une fois le prélèvement effectué, revenez me voir à Auberdine.", progress = "La pollution de la Bondissante annonce une catastrophe à Sombrivage. L'échantillon que vous avez va nous aider à mettre en place un plan... un plan d'attaque, qui commence à se préciser.", completion = "Il n'est pas surprenant que cette eau soit corrompue, regardez comme elle est croupie ! Il semble qu'il soit plus que temps d'agir, n'est-ce pas, &lt;nom&gt; ?\n\nÀ l'est, il y a Gangrebois ; c'est là-bas qu'à l'époque j'ai vu ce qui doit être à l'origine de cette corruption. Je pense que cet échantillon le confirmera. Nous devrions pouvoir préparer un remède, mais il nous faudra de l'aide. Quand le moment sera venu, &lt;nom&gt;, j'espère que vous répondrez à notre appel.", rewards = "Vous recevrez :\n\n"},
[4763] = {title = "La corruption des Noirbois", objective = "Remplir le Bol de purification vide au Puits de lune d’Auberdine.\n\nCollecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.\n\nMélanger les échantillons de nourriture à l’eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.\n\nPrendre son Talisman de corruption et l'apporter à Thundris Windweaver, à Auberdine.", description = "Les satyres sont une des sources de la corruption des furbolgs. Leur joug est assuré par des talismans qui leur servent à canaliser de la magie. Pour sauver les furbolgs, nous devons arracher son talisman au satyre corrupteur !\n\nRemplissez ce bol avec de l'eau puisée dans notre Puits de lune et collectez des échantillons de nourriture furbolg, dans leur camp, au nord. Mélangez-les à l’eau du puits et placez-les près du feu, à la rivière ; tous les furbolgs qui en mangeront seront désinfectés assez longtemps pour attirer le satyre hors de sa retraite ; et vous pourrez le tuer !", progress = "Le Talisman de corruption est un objet sinistre dont le seul but est de pervertir l'équilibre de la nature. Retrouvez cet objet sur l'un des satyres qui tourmentent les furbolgs et rapportez-le-moi. Alors, nous aurons remporté une grande victoire !", completion = "Nous sommes entrés en guerre contre les forces corruptrices pour reprendre notre forêt et aujourd'hui nous avons remporté une bataille ! &lt;nom&gt;, les citoyens d'Auberdine vous doivent une fière chandelle et il ne sera pas simple de s'acquitter de cette dette. Acceptez ceci en plus de nos remerciements. Un jour peut-être, ce que nous avons appris permettra de délivrer nos amis furbolgs des entraves qui les tourmentent sans cesse.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBaguette en pierre de luneJambières de gardien de fauvesJambières de Guststorm\n\nVous recevrez également :\n\n"},
[4764] = {title = "Le fermoir de Doomrigger", objective = "Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes.", description = "Il y a une salle, tout en haut du pic Blackrock, que l’on appelait le Hall de la chance. C’est là que les nains Sombrefer gardaient leurs reliques, trophées et autres objets d’art.\n\nIl paraît que le hall s’est effondré et qu’il sert maintenant à des objectifs moins raffinés. Je crois cependant que quelques-unes des reliques peuvent encore y être retrouvées.\n\nL’une d’entre elles est le Fermoir de Doomrigger, dont la surface était tant couverte de gemmes rares qu’aucun nain ne pouvait la regarder sans verser une larme.\n\nCe Fermoir, <nom>, est notre objectif.", progress = "Avez-vous le fermoir, <nom> ? Mon client vous paiera généreusement pour l'avoir.", completion = "Vous l'avez trouvé ! Les rumeurs étaient donc vraies !\n\nMerci, &lt;nom&gt;. Mon client, le comte Remington Ridgewell, sera content de voir cette pièce rejoindre sa collection.", rewards = "Vous recevrez :\n\n"},
[4765] = {title = "La livraison à Ridgewell", objective = "Apporter la Caisse de Ridgewell à Remington Ridgewell, à Stormwind.", description = "J’ai empaqueté le Fermoir de Doomrigger dans une caisse, pour faciliter son convoyage vers Stormwind. <nom>, votre aide fut précieuse ; mais puis-je vous demander un dernier service ?\n\nLivrez la caisse au comte Remington Ridgewell. Vous le trouverez dans le donjon de Stormwind. Il sera content de recevoir ce colis.", progress = "On m'a dit qu'un messager viendrait et qu'il aurait un cadeau du pic Blackrock.\n\nEst-ce que c'est vous ?", completion = "Ah, c'est donc vous ! Je vous remercie, &lt;nom&gt;. Et... si vous ne le saviez pas déjà... La gratitude d'un noble de la maison de Ridgewell équivaut presque à une récompense royale.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de SwiftfootGarde-bras de frappe aveugle\n\nVous recevrez également :\n\n"},
[4766] = {title = "Mayara Brightwing", objective = "Parler à Mayara Brightwing, dans les Steppes Ardentes.", description = "Un de mes agents, Mayara Brightwing, a été envoyée dans les Steppes ardentes pour une reconnaissance de la ville en ruines de Thaurissan. Cette cité détruite des nains Sombrefer pourrait cacher des objets de grande valeur... qui auraient leur place dans notre musée familial.\n\nMayara a prévenu qu’elle avait trouvé quelque chose et qu’elle avait besoin d’aide pour le récupérer ; pourtant, cela ne se trouve pas à Thaurissan. Il faudra faire un raid sur le pic Blackrock.\n\nJe ne connais pas les détails de cette affaire, mais si cela vous intéresse, parlez à Mayara, dans les Steppes ardentes.", progress = nil, completion = "Vous arrivez de Stormwind ? Merveilleux ; je connais une oeuvre d'art pour laquelle Remington serait prêt à tuer. Mais la récupérer ne va pas être chose facile.\n\nC'est là que vous intervenez.", rewards = "Vous recevrez :\n\n"},
[4767] = {title = "Le cavalier céleste", objective = "Apporter 10 Oeufs de wyverne de Haut-perchoir à Elu au poste de Librevent.", description = "On m’a chargé de recruter davantage de wyvernes pour les Maîtres des Cavaliers célestes. Leur nombre grossit et j’espère moi-même un jour devenir un Cavalier céleste. Cependant, nous n’arrivons pas à dresser assez de wyvernes pour faire face à la demande. Peut-être pouvez-vous m’aider, <nom>.\n\nJ’aurais besoin que vous vous rendiez à Haut-perchoir pour ramasser d’autres oeufs de wyverne. En partant d’ici, dirigez-vous vers le nord-ouest le long des murs du canyon vers une épaule qui vous mènera jusqu’à Haut-perchoir. Prenez garde, les wyvernes protègent farouchement leurs oeufs et ne font pas de quartier aux intrus.", progress = "<nom>, avez-vous les œufs de wyverne que je cherche ? J'ai vraiment hâte de commencer mon entraînement de Cavalier Céleste !", completion = "Parfait ! Avec ces œufs, j'espère me rapprocher de mon rêve de devenir un Cavalier céleste. Voici un gage de ma reconnaissance ; que vos chasses soient toujours fructueuses, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nRenfort d'armure lourd"},
[4768] = {title = "La tablette de Darkstone", objective = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.", description = "La tablette de Darkstone contient les écrits du nain Urheld Darkstone, un alchimiste de grand pouvoir qui était considéré comme fou par ses contemporains. De fait, il ne partagea aucune de ses recherches.\n\nIl les grava toutefois sur des tablettes, et l’une d’elle se trouve sûrement au pic Blackrock, dans une pièce nommée le Hall de la chance. Je ne sais pas comment on l’appelle maintenant, parce que fort peu sont revenus de Blackrock.\n\nMais si vous vous sentez apte à braver ces dangers et revenez avec la tablette, votre récompense sera immense.", progress = "Avez-vous trouvé la tablette, <nom> ? Je suis impatiente de me plonger dans ses secrets.", completion = "Excellent. La formule gravée sur cette tablette demandera plusieurs jours d'études pour la comprendre, mais ça en vaut la peine, j'en suis sûre.\n\nMerci, &lt;nom&gt;. Vous avez été d'une aide inestimable.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de SwiftfootGarde-bras de frappe aveugle\n\nVous recevrez également :\n\n"},
[4769] = {title = "Vivian Lagrave et la tablette de Darkstone", objective = "Parler à l'ombremage Vivian Lagrave.", description = "Vivian Lagrave de Kargath, dans les Terres ingrates, m'a fait savoir qu'il existait un ancien texte dans le pic Blackrock qui nous serait très utile. Elle a besoin d’un volontaire pour aller récupérer ce texte. C'est une mission difficile.\n\nSi cela vous intéresse, parlez à Vivian, dans Kargath.", progress = nil, completion = "C'est vrai. Je crois qu'une tablette est conservée au pic Blackrock ; dessus sont inscrites de vieilles recettes d'alchimie. Je suis contente que vous soyez là, j'ai besoin de vos services pour la récupérer.\n\nInstallez-vous confortablement, que je vous explique cela en détail.", rewards = "Vous recevrez :\n\n"},
[4770] = {title = "Vers le pays natal", objective = "Escorter Pao'ka Swiftmountain à partir de Haut-perchoir, puis parler à Motega Firemane au poste de Blanc-relais.", description = "Je vous en prie, aidez-moi, <classe> ! Cela fait un moment déjà que je me cache dans Haut-perchoir et je n’ai pas vu d’êtres amicaux depuis des jours. Je suis venu ici pour étudier les wyvernes et je crois que je me suis approché d’un peu trop près. Après avoir été chassé d’un des nids, je me suis perdu.\n\nIl faut que je retourne au poste de Blanc-relais ! Motega ne sais pas que je suis parti et sera furieux d’apprendre que je me suis aventuré seul dans Haut-perchoir.\n\nLe poste de Blanc-relais est juste à l’est d’ici... je vous en prie, ramenez-moi là-bas !", progress = nil, completion = "Quoi ? Si j'avais su que Pao'ka Swiftmountain allait fouiner autour de Haut-perchoir, je l'aurais ficelé à un totem ! Son père était peu enclin à me laisser l'emmener aux Mille pointes. Nous sommes ici pour étudier les créatures qui peuplent ces terres magnifiques.\n\nMerci de l'aide que vous lui avez apportée. J'espère que cela vous dédommagera des désagréments qu'il vous a causés.", rewards = "Vous recevrez :\n\n"},
[4771] = {title = "Le gambit de l'aube", objective = "Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink.", description = "J’ai placé le Gambit de l’aube dans le conteneur que vous nous avez apporté, celui qui contenait les œufs de dragon. Vous êtes <chargé/chargée> de l’apporter loin à l’intérieur des terres de Scholomance.\n\nLe mage mort-vivant Vectus y dirige une équipe de Sages du Fléau... Placez le Gambit de l’aube dans leur salle, appelée la \"Chambre des visions\". Il rentrera alors en contact avec les morts-vivants de l’endroit et, avec un peu de chance, les détruira !\n\nAprès ça, vaincre Vectus ne devrait pas poser de problème. Pas vrai ?", progress = nil, completion = "Vous avez réussi ! Vectus est défait ! Et le Gambit de l'aube… a-t-il fonctionné ?\n\nHm… Peut-être que ma machine n'a pas été à la hauteur de mes espoirs, mais vous avez réussi tout de même. Bien joué, &lt;nom&gt; !\n\nL'Aube d'argent et le bon peuple d'Azeroth vous sont redevables.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArracheventBâton des esprits dansants\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4781] = {title = "Les composants de la robe sanglante dorée enchantée", objective = "Apporter une Barre d'or à Xizk Goodstitch dans la vallée de Strangleronce.", description = "Votre nouvelle tâche est aussi simple que la première, mais il vous faudra chercher de l'aide.\n\nJ'ai besoin de fil d'or pour la broderie de la cape, mais il n'est pas facile de s'en procurer, et très peu sont ceux qui savent comment le fabriquer. Heureusement, un individu loyal à notre cause connaît le secret et est prêt à aider ceux qui montent dans nos rangs.\n\nApportez une barre d'or à Xizk Goodstitch à Baie-du-Butin. Il est maître tailleur et filera le fil pour vous de bon coeur. Ce sont les mineurs chevronnés qui fondent les barres d'or. Demandez à un mineur de vous aider.", progress = "Des barres d'or, oui... Oui. Apportez-m'en une et je verrai si je peux vous préparer un fil. Pendant ce temps, je vous suggère de vous entraîner pour progresser. Votre épreuve la plus difficile est encore devant vous. Et croyez-moi... Vous regretterez de ne pas vous être entraîné plus que ça.", completion = "Parfait, &lt;nom&gt;. Heureux que vous ayez trouvé un mineur qui puisse vous aider si vite. Ou avez-vous fait le travail vous-même ? Dans tous les cas, bravo. C'est parfait pour le filon.\n\nCela prendra du temps pour créer les choses, vous devrez revenir. En fait, je l'envoie à une princesse que nous retenons captive dans une tour et dont la seule activité est de filer du fil d'or... non, sérieusement, c'est vrai... enfin presque.", rewards = "Vous recevrez :\n\n"},
[4782] = {title = "Les composants de la robe sanglante dorée enchantée", objective = "Retourner voir Menara Voidrender dans les Tarides.", description = "Retournez voir Menara, dites-lui que cela prendra du temps mais que je le ferai, pour elle... et pour vous. Finissez de rassembler le reste des composants, j’aurai terminé le fil d’ici là. Revenez alors le chercher.\n\nBonne chance, <nom>. Oh, et saluez Strahad de ma part, pendant que vous y êtes. Ce vieux chnoque... avoir une tour tout près de Ratchet... quelle folie.", progress = nil, completion = "Bien, vous êtes de retour, &lt;nom&gt;. Où se trouve la menace ?\n\nAh, je comprends. C'est acceptable. Le gobelin et ses frères ne nous ont pas trahis encore ; je suppose que c'est dû au fait qu'ils ne s'y étaient pas préparés. Qu'il en soit ainsi alors... Nous avons d'autres chats à fouetter entre temps.\n\nÊtes-vous prêt pour la prochaine étape ?", rewards = "Vous recevrez :\n\n"},
[4783] = {title = "Les composants de la robe sanglante dorée enchantée", objective = "Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Voidrender dans les Tarides.", description = "Les derniers composants se trouvent en Désolace, loin à l’ouest des Tarides et même au-delà des Serres-Rocheuses.\n\nLe chaos règne toujours là-bas, après le Fractionnement. Votre force et votre intelligence y seront mises à l’épreuve : vous devrez combattre des créatures écumantes de rage ainsi que celles de la Légion ardente.\n\nRapportez-moi du sang des satyres Fielfurie que vous trouverez dans le nord-est. Rapportez-moi aussi une Pierre d’Infernal mineur que vous trouverez sur les Infernaux mineurs, au convent de Mannoroc.\n\nCes deux composants serviront à la confection de votre robe.", progress = "Désolace n'est pas une région tranquille : des nagas, des géants, des satyres, la Légion ardente... Toutes ces créatures et le conflit qui oppose les différents clans de centaures rendent cette région peu sûre, si vous ne faites pas attention.\n\nComme je l'ai déjà dit, cette épreuve ne testera pas que votre force et votre ruse, mais aussi votre patience. Soyez prudent, <nom>.", completion = "Excellent, &lt;nom&gt;. Ceci fera l'affaire. Je vais les préparer pendant que vous partez à la recherche des deux derniers composants. Êtes-vous prêt ?", rewards = "Vous recevrez :\n\n"},
[4784] = {title = "Les composants de la robe sanglante dorée enchantée", objective = "Apporter du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Voidrender dans les Tarides.", description = "Je n’ai plus besoin que de trois choses, <nom>, puis nous pourrons terminer votre robe.\n\nD'abord, il nous faut le fil d’or délicat que Xizk fabrique pour vous. Retournez à Baie-du-Butin et allez le chercher.\n\nEnsuite, vous m'apporterez deux Charbons ardents que vous trouverez sur les élémentaires de feu dans les hautes-terres d'Arathi. Si mes souvenirs sont bons, ils sont à l’ouest, près du Mur de Thoradin.\n\nFinalement, un Fragment d'âme créé par vous.\n\nUne fois que vous aurez tous ces éléments, revenez me voir et je terminerai la robe.", progress = "Bientôt, <nom>. Je vous le promets. Cette robe vous ira à merveille et vous confèrera un avantage certain sur vos adversaires.", completion = "Excellent, &lt;nom&gt; ! Nous avons rassemblé les composants et nous sommes prêts.\n\nJe pense que vous apprécierez.", rewards = "Vous recevrez :\n\n"},
[4785] = {title = "Fil d'or fin", objective = "Voilà, <nom>. Et s'il vous plaît, dites à Menara que nous la saluons.\n\nNous espérons beaucoup de vous. Peut-être que, lorsque la Légion sera à genoux, votre nom et votre puissance seront loués haut et fort. Je suis impatient !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nFil d'or fin"},
[4786] = {title = "La Robe terminée", objective = "Attendre que Menara Voidrender ait terminé votre robe puis lui parler de nouveau.", description = "Je vais maintenant confectionner la robe pour vous. Ne vous éloignez pas, je n'en ai pas pour longtemps.", progress = nil, completion = "C'est fait, &lt;nom&gt;. Voilà pour vous. Portez-la avec fierté.\n\nVous avez travaillé dur et je vous prédis un avenir glorieux. Souvenez-vous que combattre la corruption qui se dresse sur votre chemin demande beaucoup de volonté et de résistance. Tant que vous resterez maître de vos émotions, vous aurez la victoire.", rewards = "Vous recevrez :\n\nRobe sanglante dorée enchantée"},
[4787] = {title = "L'oeuf antique", objective = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris.", description = "La prophétie de Mosh'aru parle d'un oeuf antique, vestige du temps où les trolls régnaient sur de vastes empires, et qui a le pouvoir de renfermer l'essence d'Hakkar. C'est peut-être le seul moyen de protéger notre monde de ce mal.\n\nApportez-moi cet oeuf antique, <nom>. On dit qu'il est enfoui à Jintha'Alor dans les Hinterlands, dans une grotte derrière l'amphithéâtre au sommet de la cité.", progress = "Avez-vous l'oeuf antique ? Je sens de grandes forces qui s'agitent et je crains que le temps manque.", completion = "Ah, vous avez l'oeuf ! Je m'incline devant vous, &lt;nom&gt;. On se souviendra pendant longtemps de votre force et de votre courage.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4788] = {title = "Les dernières tablettes", objective = "Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris.", description = "Pendant que je consulte la troisième et la quatrième tablette Mosh'aru, il faut que vous trouviez la cinquième et la sixième ! Cela ne sera pas facile, car elles se trouvent entre les mains des trolls Smolderthorn, au pic Blackrock.Ce pic est une sombre montagne de feu située entre les Steppes ardentes et la gorge des Vents brûlants.\n\nBonne chance, <nom>. Le pic Blackrock est un endroit malfamé...", progress = "Avez-vous été au pic, <nom> ? Avez-vous les cinquième et sixième tablettes ?", completion = "Incroyable ! Vous les avez trouvées ! Vous êtes un vrai héros, &lt;nom&gt; !\n\nD'ailleurs, c'est une bonne chose, car d'après ce que j'ai déchiffré des tablettes que vous m'aviez apportées… Il nous faudra un vrai héros pour arrêter ce qui arrive...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4801] = {title = "L'E'ko des sabres-de-givre", objective = "Au Berceau-de-l'Hiver, vous combattrez de grands félins appelés \"sabres-de-givre\". Ces bêtes sont incroyablement rapides et vicieuses. Si vous voulez gagner la vitesse des sabres-de-givre, apportez-moi l'Eko que vous trouverez sur eux.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous combattrez de grands félins appelés \"sabres-de-givre\". Ces bêtes sont incroyablement rapides et vicieuses. Si vous voulez gagner la vitesse des sabres-de-givre, apportez-moi l'Eko que vous trouverez sur eux.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nRafale de Juju"},
[4802] = {title = "L'E'ko des Tombe-hiver", objective = "Au Berceau-de-l'Hiver, vous combattrez des créatures perdues connues sous le nom de furbolgs Tombe-hiver. Sous l'égide de leur maître, ils ont gagné une force incroyable. Si vous voulez acquérir la puissance des Tombe-hiver, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous combattrez des créatures perdues connues sous le nom de furbolgs Tombe-hiver. Sous l'égide de leur maître, ils ont gagné une force incroyable. Si vous voulez acquérir la puissance des Tombe-hiver, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nPouvoir de Juju"},
[4803] = {title = "L'E'ko des Crocs acérés", objective = "Au Berceau-de-l'Hiver, vous trouverez de grands ours à la peau très épaisse. Ces ours aux crocs acérés sont bien protégés et peuvent supporter beaucoup. Si vous souhaitez gagner la résistance au feu, apportez-moi l'E'ko que vous trouverez auprès des Crocs acérés.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous trouverez de grands ours à la peau très épaisse. Ces ours aux crocs acérés sont bien protégés et peuvent supporter beaucoup. Si vous souhaitez gagner la résistance au feu, apportez-moi l'E'ko que vous trouverez auprès des Crocs acérés.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nBraise de Juju"},
[4804] = {title = "L'E'ko de Noroît", objective = "Au Berceau-de-l'Hiver, vous combattrez de grandes créatures ailées nommées des Noroît. Ces bêtes peuvent se servir de la magie de glace. Si vous voulez devenir résistant à la glace, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous combattrez de grandes créatures ailées nommées des Noroît. Ces bêtes peuvent se servir de la magie de glace. Si vous voulez devenir résistant à la glace, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nFrisson de Juju"},
[4805] = {title = "L'E'ko des Chardon de Glace", objective = "Au Berceau-de-l'Hiver, vous combattrez de grandes créatures nommées yétis Chardon de glace. Ces bêtes sont lentes mais capables d'éviter de nombreux coups grace à l'épaisseur de leur fourrure. Si vous voulez gagner le pouvoir d'esquiver les attaques, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous combattrez de grandes créatures nommées yétis Chardon de glace. Ces bêtes sont lentes mais capables d'éviter de nombreux coups grace à l'épaisseur de leur fourrure. Si vous voulez gagner le pouvoir d'esquiver les attaques, apportez-moi l'E'ko que vous leur prendrez.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nFuite de Juju"},
[4806] = {title = "L'E'ko de Cognegivre", objective = "Au Berceau-de-l'Hiver, vous affronterez des grands géants des glaces, les Cognegivre. Ils sont la force et la puissance incarnées. Si vous voulez vous imprégner de la force des Cognegivre, rapportez-moi les E'kos que vous trouverez sur eux.\n\nSouvenez-vous, le charme de Mau'ari doit être dans votre inventaire pour chasser les E'kos.", description = nil, progress = "Au Berceau-de-l'Hiver, vous affronterez des grands géants des glaces, les Cognegivre. Ils sont la force et la puissance incarnées. Si vous voulez vous imprégner de la force des Cognegivre, rapportez-moi les E'kos que vous trouverez sur eux.\n\nSouvenez-vous, le charme de Mau'ari doit être dans votre inventaire pour chasser les E'kos.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nPuissance de Juju"},
[4807] = {title = "L'E'ko des Indomptables", objective = "Au Berceau-de-l'Hiver, vous combattrez des créatures qui semblent posséder des pouvoirs magiques innés. Ces Indomptables sont dotés de grands pouvoirs magiques. Si vous voulez voir votre intelligence augmenter, apportez-moi l'E'ko que vous trouverez sur l'un de ces chouettards.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", description = nil, progress = "Au Berceau-de-l'Hiver, vous combattrez des créatures qui semblent posséder des pouvoirs magiques innés. Ces Indomptables sont dotés de grands pouvoirs magiques. Si vous voulez voir votre intelligence augmenter, apportez-moi l'E'ko que vous trouverez sur l'un de ces chouettards.\n\nSouvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko.", completion = "Mau'ari peut utiliser ce juju pour &lt;nom&gt;... Utiliser la Cache de Mau'ari pour la lancer sur vous ou l'un de vos alliés.", rewards = "Vous recevrez :\n\nFourberie de Juju"},
[4808] = {title = "Felnok Steelspring", objective = "Donner la Lettre de Tinkee à Felnok Steelspring.", description = "J’ai une autre faveur à vous demander.\n\nMon étude de l’essence que vous avez collectée montre une possibilité de congeler des œufs de jeunes dragons et de les préserver ! Je veux mettre en pratique ma théorie, mais j’ai besoin de certains composants d'ingénierie. Mon collègue, Felnok Steelspring, peut les fabriquer.\n\nVoilà, apportez-lui cette lettre, c’est la liste de ce dont j’ai besoin. Vous trouverez Felnok au Berceau-de-l'Hiver, dans la ville de Long-guet.", progress = "Il fait froid ici ! J'espère que vous m'avez amené une couverture !", completion = "Ce n'est pas une couverture ! Mais qu'avons-nous ici ? Une lettre de Tinkee ? Je me demande ce qu'elle a à dire...\n\nAh, elle mène des recherches dans les Steppes ardentes. C'est censé ; c'est un bon endroit pour trouver des draconiens. Oh, attendez ! Elle raconte qu'elle a besoin de certains éléments pour une machine qu'elle veut construire. Je suppose que c'est là que j'interviens, hein ?", rewards = "Vous recevrez :\n\n"},
[4809] = {title = "Cornes de Noroît", objective = "Apporter 8 Cornes intactes de Noroît à Felnok Steelspring.", description = "J’ai presque tout ce dont Tinkee a besoin, mais il me manque un composant important, des cornes de Noroît. Les cornes des chimères Noroît de Berceau-de-l'Hiver sont une formidable source de froid. Encore faut-il qu'elles soient d’origine et absolument intactes ! Il me faut une cargaison complète de ces cornes pour satisfaire les besoins de Tinkee.\n\nApportez-moi des Cornes intactes de Noroît, et je préparerai le colis pour Tinkee.", progress = "Avez-vous les cornes de Noroît, <nom> ?", completion = "Ce sont de beaux spécimens. Ils sont bien glacés ! Laissez-moi mettre des gants et les ranger avec les autres choses dont Tinkee a besoin...", rewards = "Vous recevrez :\n\n"},
[4810] = {title = "Retourner voir Tinkee", objective = "Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes.", description = "Bien tout est prêt, empaqueté et paré au transport. Bonne chance dans votre voyage, et n'oubliez pas de rappeler mon dévouement et ma loyauté à Tinkee !", progress = "<nom> ! Avez-vous parlé à Felnok ? Vous avez les composants dont j'ai besoin ?", completion = "Vous avez tout rapporté ! Merveilleux ! Je vais me mettre au travail tout de suite ! Merci beaucoup, &lt;nom&gt; !\n\nVous m'avez rendu un grand service, je pourrais avoir besoin de vous plus tard pour remplir des tâches plus importantes...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nFoudroyanteSceptre des tombes\n\nVous recevrez également :\n\n"},
[4811] = {title = "Le cristal rouge", objective = "Voyager en direction de l’est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.", description = "Des séléniens hostiles se massent toujours en plus grand nombre à l'est. Nous croyions autrefois qu'il s'agissait de créatures inoffensives, et presque mystiques. Bien que certains continuent à leur porter révérence, la sécurité d'Auberdine me force à considérer les choses de manière plus réaliste.\n\nJ'ai reçu divers rapports m'informant que les séléniens étaient attirés par un grand cristal rouge le long de la chaîne de montagnes à l'est de Sombrivage. Personne ne sait ce qu'est ce cristal, ou même s'il existe vraiment. Je veux que vous le localisiez et que vous me rapportiez vos découvertes.", progress = nil, completion = "Alors le cristal existe, &lt;nom&gt; ? Fascinant… Quoi qu'il en soit, vous avez parfaitement exécuté votre tâche ; bon travail !\n\nQu'est-ce que ce cristal exactement ? Ce n'est qu'une simple question dans un océan d'interrogations. Une autre question qui vient à l'esprit, est pourquoi les séléniens sont-ils attirés par cet objet ? Le cristal est-il bon de nature, ou renferme-t-il un secret plus sombre ?\n\nJ'ai beaucoup d'autres questions, mais il va nous falloir examiner ce cristal de près pour trouver des réponses.", rewards = "Vous recevrez :\n\n"},
[4812] = {title = "Comme l'eau tombe en cascade", objective = "Remplir le Tube d'eau vide au Puits de lune d’Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l’est de Sombrivage.", description = "Servez-vous de cette fiole vide et remplissez-la à l'un des Puits de Lune ici, à Auberdine. Une magie si puissante devrait fournir un indice quant à la composition du cristal. Pour ce faire, vous verserez le liquide dessus. Il devrait s'occuper du reste.\n\nBien que je ne pense pas que quoi que ce soit de mauvais puisse vous arriver, je souhaite tout de même que vous agissiez avec prudence. Au-dessus de nous, à l'est, se trouve Gangrebois. Si ce cristal est lié à cet endroit comme je le suspecte, alors il pourrait être très dangereux.", progress = "Le cristal semble étranger sur le paysage boisé de Sombrivage. Vous croyez entendre un très léger bourdonnement qui s'élève de ses profondeurs.", completion = "Vous atteignez une fois de plus le cristal. Vous ôtez le bouchon du Tube d'eau du Puits de lune et versez avec précaution son contenu sur le sommet du cristal. Alors que l'eau tombe en cascade le long des facettes du cristal, vous voyez que perdant sa teinte opaque, sa surface devient transparente...", rewards = "Vous recevrez :\n\n"},
[4813] = {title = "Les fragments à l'intérieur", objective = "Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.", description = "L'eau du Puits de Lune a révélé que quelques petits fragments d'os ainsi que la moitié d'un maxillaire sont incrustés à l'intérieur du cristal. Le maxillaire semble appartenir à un humanoïde, mais il est impossible de s'en assurer sans briser le cristal, un exploit que même la plus puissante des magies considèrerait comme quasiment impossible.\n\nCette tâche accomplie, tout ce qu'il reste à faire est de retourner informer la Sentinelle Glynda Nal'Shea à Auberdine.", progress = nil, completion = "Bien, il semblerait que bien que nous en sachions plus sur ce cristal, d'autres questions sans réponses apparaissent !\n\nJe ferai part des informations que vous avez découvertes au conseil d'Auberdine. Peut-être sauront-ils quelle action entreprendre pour ce cristal. Bon, s'il faut en entreprendre une ; pour l'heure, la menace demeure suffisamment à l'est pour que nous soyons hors de danger.\n\nEn ce qui vous concerne, prenez ceci, s'il vous plaît. Considérez ceci comme la récompense d'un travail bien fait, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée courte de BriarsteelDague de CurvewoodBâton d'Oakthrush\n\nVous recevrez également :\n\n"},
[4821] = {title = "L'oeuf étrange", objective = "Rapporter l'Oeuf étrange à Hagar Lightninghoof au Poste de Librevent.", description = "Il y a une rumeur qui circule à propos d'un oeuf étrange ici aux Mille pointes. Ceux qui disent avoir vu cet oeuf n'ont pas réussi à s'en rapprocher assez pour pouvoir l'examiner minutieusement. Des serpents le gardent comme si c'était le leur.\n\nJe veux que vous recherchiez cet oeuf étrange et que vous me le rapportiez afin que je puisse l'examiner. Certains disent que l’oeuf se trouve dans un nid de serpents, mais il y en a plusieurs le long du bas des falaises au sud et au nord-ouest du Poste de Librevent.", progress = "Je dois en savoir davantage sur cet oeuf mystérieux, qui sait ce qu'il va en sortir.", completion = "Oui, finalement…l'oeuf mystérieux m'a été livré. Maintenant regardons mieux ce… Quoi..! Qu'est-ce que c'est… ?", rewards = "Vous recevrez :\n\n"},
[4822] = {title = "Je veux une glaaaaace !", objective = "Aller chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor.", description = "DE LA GLACE ! Oh, s’il vous plaaaaîîîîîît, je peux avoir de la glace ?! La glace à la fraise est ma glace préférée, et la meilleure glace à la fraise du monde, c’est celle d’Aguilor ! C’est ma glace préférée dans le monde entier !\n\nJ’en ai mangé il y a longtemps aux courses des Salines, mais il paraît qu’ils en vendent en ville ! S’il vous plaît ? S’il vous plaaaaîîîîîît ? Avec une deuxième boule sur le dessus ??!?!", progress = "J'aimerais bien qu'ils fassent d'autres parfums de glace que la fraise. Mais j'ai de la chance, la glace à la fraise est ma préférée !", completion = "Mmmmmmmmm ! J'adore leur glace à la fraise ! S'il y a bien une chose qu'Aguilor &amp; Dagharn savent faire, c'est la crème glacée !\n\nMerci beaucoup &lt;nom&gt;, je n'ai jamais rien mangé d'aussi bon !", rewards = "Vous recevrez :\n\n"},
[4841] = {title = "Pacifier les centaures", objective = "Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longhorn au Poste de Librevent.", description = "<nom>, je vous en supplie, chassez ces centaures. Ils vont sentir la force de notre revanche. Attaquez le camp de centaures au nord du Poste de Librevent ! Laissez la colère guider votre main !", progress = "Allons, <nom>, je sais que vous n'avez pas tué votre part encore. Pourchassez-les, et je vous récompenserai à la mesure de ma gratitude.", completion = "En gage de ma gratitude, ceci est pour vous, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[4842] = {title = "Sources étranges", objective = "Suivre les instructions de Donova Snowden, puis faire un rapport.", description = "Pour vous dire la vérité, bien qu'il n'y ait pas de volcan ici au Berceau-de-l'Hiver, je pense que ces sources chaudes représentent bien plus de menaces…\n\nEnfin, je pense que vous voulez voir ça par vous-même. Vous devez traverser le Berceau-de-l'Hiver et vous diriger vers le sud. Lorsque l'air deviendra lourd et moite, que le ciel s'assombrira, vous aurez trouvé ce que je crois être l'origine des sources chaudes.\n\nRegardez bien. Je suis sûr que vous aurez beaucoup de questions à votre retour.", progress = "L'eau des fontaines semble posséder d'anciennes vertus... Je ne sais pas exactement de quoi il s'agit...", completion = "Oui. Les démons de la gorge du Sombre murmure ; je pense que c'est leur présence qui affecte le pays de la sorte. Je vais continuer à observer les sources d'eau chaude et voir si je peux en apprendre plus.\n\nSi vous comptiez vous enfoncer dans la gorge du Sombre murmure, j'attendrais d'être un peu plus fort à votre place.", rewards = "Vous recevrez :\n\nCape du fleuve profond"},
[4861] = {title = "Les Indomptables enragés", objective = "Localiser le camp démoli et les fournitures de Jaron Stoneshaper, au sud du Berceau-de-l'Hiver.", description = "Eh, ici, <mon garçon/jeune fille> ! J'ai été chassé de mon camp au sud du Berceau-de-l'Hiver par quelques Indomptables sanguinaires ! J'imagine que j'ai dû m'approcher d'un peu trop près de quelque chose qu'ils gardaient.\n\nJ'ai bien failli ne pas m'en sortir ; j'ai peur que l'un de mes amis n'ait pas eu cette chance. Accepteriez-vous d'affronter les Indomptables et de revenir au camp ? J'ai vraiment besoin de mes provisions et je voudrais aussi récupérer l'amulette que j'ai déterrée hier sur le site.", progress = nil, completion = "Une caisse très endommagée se dresse au milieu des débris du camp...", rewards = "Vous recevrez :\n\n"},
[4862] = {title = "Mauvais", objective = "Aller au Pic Blackrock et ramasser 15 Oeuf d'araignée du pic pour Kibler.\n\nCes oeufs peuvent être trouvés à proximité des araignées.", description = "Croyez-moi, il y a des gens qui sont prêts à payer pour s’offrir la moindre bête domestiquée !\n\nJ’aurais bien envoyé Bijou dans le Pic pour qu’elle collecte quelques-uns de ces oeufs d’araignées mais je n’ai pas de nouvelles d’elle depuis des semaines. Peut-être pourriez-vous m’aider ?\n\nJe vais vous dire, <nom>, allez au pic Blackrock et collectez des Oeufs d’araignée du pic. Si vous m’en rapportez, je vous donnerai non seulement un peu d’argent mais j’en domestiquerai une pour vous !", progress = "Ce sont les oeufs d'araignée ou êtes-vous simplement heureux de me voir ?", completion = "Quel chargement ! Sans blague, regardez-moi tous ces oeufs ! Cela devrait rapporter un peu d'or.\n\nComme promis, voilà votre petite créature personnelle. Attention à ne pas vous faire mordre !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCaisse de Couveuse"},
[4863] = {title = "Les Indomptables enragés", objective = "Trouver le chariot saccagé de Jaron Stoneshaper.", description = "Regardant autour de vous, vous vous demandez ce que Jaron pouvait bien vouloir ici. Vous remarquez cependant que la caisse que vous avez trouvée a été ouverte violemment, comme si c'était cela que les Indomptables cherchaient...\n\nEn regardant à l’est, vous discernez un chariot abandonné. Peut-être les effets de Jaron s’y trouvent-ils. Cela vaut certainement la peine d’aller jeter un coup oeil.", progress = nil, completion = "En approchant du chariot, vous ne remarquez rien pour Jaron. Mais en regardant au sol, vous apercevez plusieurs caisses intactes, bien qu'elles soient à moitié recouvertes de neige.", rewards = "Vous recevrez :\n\n"},
[4864] = {title = "Les Indomptables enragés", objective = "Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé.\n\nRapporter les Fournitures de Jaron et l'Amulette de la plume bleue à Jaron Stoneshaper au pavillon, dans le Berceau-de-l'Hiver.", description = "Après avoir inspecté le contenu de la boîte, vous estimez que Jaron pourrait avoir usage des outils et des objets qu’elle renferme. Il n’y a cependant aucun signe de l’amulette.\n\nIl s’avère que les Indomptables hantent les terres au nord et à l’est ; vous décidez par conséquent d’affronter les créatures et de leur arracher l’amulette.", progress = "Oui... Racontez-moi les nouvelles.", completion = "Ma foi, je m'attendais à entendre ça, gamin. Je pensais que ces bêtes avaient détruit toutes mes affaires...\n\nMais vous avez retrouvé mes outils et surtout l'amulette ! Je me demande pourquoi Ies indomptables ont protégé à tout prix cet objet... Dans tous les cas, j'y penserai à deux fois avant de retourner là-bas !", rewards = "Vous recevrez :\n\n"},
[4865] = {title = "Serpent sauvage", objective = "Faire un rapport de vos trouvailles à Motega Firemane.", description = "Si je n'avais pas vu ça de mes propres yeux, je ne l'aurais jamais cru. La vengeance s'abat sur les Mille pointes !\n\n<Hagar essuie son front.>\n\n<nom>, Vous devez agir vite ! Partez maintenant et cherchez Motega Firemane, il est au Poste de Blanc-relais, au nord-ouest du Poste de Librevent. Il saura quoi faire !", progress = nil, completion = "Vengeance ! Ainsi la légende d'Arikara est vraie. Il faut régler ce problème au plus tôt.", rewards = "Vous recevrez :\n\n"},
[4866] = {title = "Le lait matriarcal", objective = "Vous trouverez la Matriarche Couveuse au coeur du pic Blackrock. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon.", description = "C’est sans doute l’un des poisons les plus violents du monde, <nom> !\n\nJ’ai entendu les Blackrock parler de sa toxicité lors de ma virée au pic. Ils l’appellent “le lait matriarcal”, en référence à la Matriarche couveuse, la grande araignée de la grotte de Toile-grouillante.\n\nVoici ce que j’aimerais que vous m’apportiez : un échantillon actif de ce lait, coulant dans VOS PROPRES veines. En effet, la glande à venin ne sera pas suffisante. Il faut que vous la poussiez à vous piquer et que vous reveniez me voir !\n\nPuis... je vous trairai comme une vache !\n\n<Il se frotte les mains avec délectation.>", progress = "<John le Loqueteux vous pince.>", completion = "Ça donnera la meilleure bière jamais vue !\n\nEh, qu'est-ce que vous croyez que j'allais en faire ? Du poison ou autre chose ?\n\nSatanés gamins...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nChope sans fin de John le Loqueteux"},
[4867] = {title = "Urok Hurleruine", objective = "Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh.", description = "Ahhh ! C'est si dur de parler !\n\nPrenez cette note ! Allez me chercher mon mojo !", progress = "Ah ! Vous avez mon mojo ?", completion = "Aha ! Je sens déjà mes pouvoirs me revenir. Et mon esprit n'est plus brisé par la malédiction d'Urok.\n\nMerci, &lt;nom&gt; ! Je suis fier, mais je dois reconnaître votre aide précieuse.\n\nEt je vous souhaite chance et prospérité pour votre voyage par le pic Blackrock. Vous êtes fou de penser pouvoir en atteindre le sommet, mais je rends grâce à votre courage.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCharme prismatique"},
[4881] = {title = "Complot d'assassinat", objective = "Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace.", description = "Le tauren Kanati Greycloud est audacieux pour oser installer un camp de chasse aux Mille pointes. Nous devons le tuer pour nous débarrasser de ce camp et de tous ceux qui le suivraient. Allons vers le petit poste au sud ouest de la Grande élévation.", progress = nil, completion = "Ils sont venus pour me tuer ? Je vais leur montrer de quel bois se chauffe un tauren !", rewards = "Vous recevrez :\n\n"},
[4882] = {title = "Secrets gardés", objective = "Apporter le Collier de plumes bleues à Trull Failbane au Poste de la Vénéneuse.", description = "Vous voudriez en savoir plus sur le collier qui est tombé du cou de l'Indomptable que vous avez tué. Il brille fortement mais son éclat varie.\n\nTrull Failbane devrait être capable de vous en dire plus, puisque c'est un spécialiste des Indomptables. N'hésitez pas à le consulter.", progress = "Au rapport pour une nouvelle mission ?", completion = "Une découverte importante ?", rewards = "Vous recevrez :\n\n"},
[4883] = {title = "Secrets gardés", objective = "Apporter le Collier de plumes bleues à Nara Wildmane.", description = "J'ai beau posséder de solides connaissances sur les Chouettards que vous avez vaincus au Berceau-de-l'Hiver, je ne sais pas grand-chose de la magie qu'ils utilisent. Mais je pense savoir qui pourra examiner ce collier et vous dire de quoi il s'agit.\n\nNara Wildmane à Thunder Bluff est experte en la matière. Allez la voir. Bonne chance, <nom>.", progress = "Comment puis-je vous aider, <nom> ?", completion = "L'énergie de ce collier, &lt;nom&gt;. Je crois qu'il n'a qu'une source.\n\n\n\nLes Indomptables, aujourd'hui mal guidés et confus, n'ont pas toujours été ainsi. Ils avaient autrefois un but, et étaient guidés pour servir. La déesse des elfes de la nuit, Elune, a créé ces créatures pour garder ses lieux les plus sacrés.\n\nBien qu'apparemment de peu d'importance, je vous incite à creuser ce fait plus avant.\n\nVous apprendrez, en temps voulu. Merci de me l'avoir rapporté, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards d'écumePlates de bras scintillantes\n\nVous recevrez également :\n\n"},
[4901] = {title = "Les gardiens de l'autel", objective = "Protéger Ranshalla pendant qu’elle s’efforce de réactiver l’Autel d’Elune. Faire un rapport de vos découvertes à Erelas Ambersky, au village de Rut'theran.", description = "Au sommet de l'arête se trouve ce que je crois être un autel de la déesse Elune. De ce que je peux dire, il faut allumer les cinq torches dans chaque caverne pour accéder à l'autel.\n\nJ'ai retranscrit quelques incantations taillées dans la pierre, dans les ruines antiques de Kel'Theril ; je crois qu'elles sont la clé pour ouvrir l'autel. J'aurai besoin de votre aide pour allumer les torches pendant que je réciterai le charme.\n\nSi notre entreprise est couronnée de succès, vous pourrez annoncer nos découvertes à Erelas !", progress = nil, completion = "Avez-vous eu votre entretien avec Ranshalla ?", rewards = "Vous recevrez :\n\n"},
[4902] = {title = "Les Indomptables d'Elune", objective = "Parler à l’archidruide Fandral Staghelm, à Darnassus.", description = "C'est fascinant !\n\nJ'ai toujours voulu savoir la vérité... Bon, vous devez faire entendre cette vérité ! Allez tout de suite chez l'archidruide Fandral Staghelm, vous le trouverez à Darnassus, au Cercle cénarien. Expliquez-lui ce qui est arrivé, comme vous me l'avez expliqué. Je suis sûr qu'il sera très intéressé !\n\nCette information est importante, <nom> !", progress = nil, completion = "N'hésitez pas, donnez-moi la raison de votre présence ici.\n\nOh oui ? Hmm… Bien.\n\nMerci d’avoir couru me prévenir. Il faut toujours aller directement au plus haut... Mais... Oui. Les druides du Cercle cénarien ont souvent entendu parler des Indomptables. Ce sont les familiers d'Elune, et ils ont été choisis pour garder les lieux les plus sacrés.\n\nDonc ce que vous dites n'est pas neuf, mais je vous félicite pour vos efforts. Tenez, prenez ceci, un petit quelque chose pour vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nThornflingerMédaillon d'opaline\n\nVous recevrez également :\n\n"},
[4903] = {title = "Ordre du chef de guerre", objective = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.", description = "Sur ordre du chef de guerre Goretooth, les résidents suivants du pic Blackrock doivent être détruits :\n\nLe généralissime Omokk, nuisance obèse.\n\nLe maître de guerre Voone, troll cruel et impitoyable.\n\nLe seigneur Wyrmthalak, maître de la cité basse.\n\nVous devrez aussi rapporter tous les documents que vous pourriez trouver.\n\nSi vous réussissez, les honneurs vous reviendront.\n\nÉchouez, et votre nom tombera dans l’oubli.", progress = "<Le chef de guerre Goretooth salue.>", completion = "&lt;La peau verte du chef de guerre Goretooth vire au blanc terreux pendant un bref moment.&gt;", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMenottes de WyrmthalakCorset d'OmokkMuselière d'HalyconBande de Vosh'gajinPoignes de fer de Voone\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4904] = {title = "Libre, enfin !", objective = "Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent.", description = "Arnak pense que nous allons nous marier… Mais après mon refus, il est revenu pendant la nuit et m'a kidnappée. Mon frère a essayé de l'arrêter, mais Arnak était trop fort. Il… il a tué mon frère puis m'a ramenée ici. Mon pauvre frère…\n\n<nom>, pourriez-vous me faire sortir de la cime de Noir-nuage ? Je vous supplie... Je dois retourner auprès de Thalia ! Elle doit se faire un sang d'encre à mon sujet.", progress = nil, completion = "Merci, &lt;nom&gt;. Au plus profond de moi je savais qu'elle me retrouverait. Elle m'a raconté votre bravoure et comment vous l'avez aidée à s'échapper. Ces objets appartenaient à son frère. Je sais qu'elle aurait voulu que vous les ayez.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCordelière WindsongDrapé chantevent\n\nVous recevrez également :\n\n"},
[4906] = {title = "Plus de corruption", objective = "Eridan Bluewind de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu, et Xavaric. Revenir auprès d’Eridan quand la tâche est accomplie.", description = "Un second campement de satyres menace Gangrebois, au nord. Menés par le cruel Xavaric, ces maudits traîtres se servent de la corruption qui afflige les créatures locales de Gangrebois.\n\nXavathras et ses sbires ne représentaient qu’une partie d’un plan beaucoup plus vaste : la mise en place d’un Puits de lune corrompu, puis l’acheminement des butins à Xavaric.\n\nMaintenant que Xavathras n’est plus de la partie, finissez cette mission, <nom>. Marchez vers le nord et tuez Xavaric.", progress = nil, completion = "Merci pour tout ce que vous avez fait, &lt;nom&gt;. Qu'Elune vous protège et vous guide sur le chemin qui se dresse devant vous.", rewards = "Vous recevrez :\n\nBrassards de la brise"},
[4907] = {title = "Tinkee Steamboil", objective = "Parler à Tinkee Steamboil.", description = "Salut, <nom>. Vous vous rappelez de Tinkee Steamboil ? Elle, elle se souvient de vous ! Elle me fait vous dire qu’elle a encore besoin de votre aide. Je pense que c’est en rapport avec ses études sur les dragons.\n\nAllez lui parler dans les Steppes ardentes, à la Corniche des flammes.", progress = nil, completion = "Felnok avait raison ! J'ai besoin de votre aide à nouveau, et cette fois... Ça sera vraiment dangereux.\n\nÊtes-vous prêt ?", rewards = "Vous recevrez :\n\n"},
[4921] = {title = "Disparition au combat", objective = "Trouver la femme de Mankrik puis retourner le voir à la Croisée.", description = "Nous combattions dans un petit camp tauren lorsque nous fûmes séparés. A elle seule, elle arrivait à tenir à distance trois des Dos-hirsute, mais leur nombre allait croissant et ils nous débordèrent. J’avais beau en repousser, je la voyais assaillie et mise à mal par les nouveaux venus. Dans ma rage, je me jetai contre mes ennemis, mais ils me maîtrisèrent grâce à la supériorité de leurs effectifs.\n\nLorsque je m’éveillai, un druide tauren soignait mes blessures. Il m'avait trouvé inanimé sur la Route de l'or.\n\nJe vous en prie, <classe>, retrouvez la piste de ma femme et apprenez ce qu’elle est devenue.", progress = nil, completion = "Je comprends. Merci, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[4941] = {title = "Sagesse d'Eitrigg", objective = "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.\n\nVous avez déjà vu Eitrigg dans les Appartements de Thrall.", description = "Rend est vivant ?\n\nImpossible !\n\nRend était supposé avoir été tué voilà des années.\n\nAllez demander conseil à Eitrigg, <nom>. Personne ne connaît mieux les Blackrock que lui et si tout ceci est vrai, Eitrigg doit en être informé. Chacun a un droit à la vengeance.\n\nVous le trouverez à Orgrimmar.\n\nUne fois que vous aurez parlé avec Eitrigg, entretenez-vous avec le Chef de guerre pour voir ce qu’il souhaite faire à propos de ce problème.", progress = "Vous ne voyez pas qu'il ne faut pas m'interrompre ?", completion = "&lt;Thrall a l'air consterné par les nouvelles que vous venez d'apporter.&gt;", rewards = "Vous recevrez :\n\n"},
[4961] = {title = "Purifie l'Orbe d'Orahil", objective = "Tuer le Démon de l’Orbe, puis parler à Tabetha.", description = "Ah, un orbe d’Invocateur, c’est donc de là que l’infection doit provenir. Nous devons exorciser le démon qui y est enfermé, si vous voulez pouvoir l’utiliser. Je peux faire cela.\n\nC’est vous qui aurez le travail ingrat à faire. Vous devrez en effet tuer le démon quand je l’aurai libéré.\n\nIl faudra agir prestement, sans quoi il réintégrera l’orbe et il nous faudra tout reprendre !\n\nPréparez-vous, <nom>, ainsi que vos sorts les plus puissants, et gardez vos potions sous la main. Vous pouvez aussi faire appel à un ami pour vous assister si vous en connaissez un. La mission ne va pas être reposante !", progress = nil, completion = "Bien joué, &lt;nom&gt; ! Vous avez donné une leçon à ce démon ; il n'est pas prêt de l'oublier. Vous avez fait preuve de bravoure et de puissance. Je suppose qu'il est temps que vous retourniez voir Menara, avec l'orbe purifié, pour l'utiliser à bon escient.\n\nBonne chance, &lt;classe&gt;. Peut-être que nos chemins se croiseront à nouveau.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nOrbe infernal purifié"},
[4962] = {title = "Un éclat de gangrechien", objective = "Prendre le Rubis de Felhas et l’utiliser sur l’un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l’Esprit de gangrechien emprisonné à Menara Voidrender, dans les Tarides.", description = "Alors vous avez décidé de capturer l’âme d’un gangrechien. Très bien.\n\nPrenez ce rubis, il vous permettra de capturer l’âme de la créature. Cela fonctionne comme les sorts que vous connaissez déjà : quand la créature est sur le point de mourir, utilisez la gemme qui fera le reste du travail pour vous.\n\nJe suggère que vous vous rendiez en Désolace et que vous essayiez avec n’importe quel gangrechien qui se trouve là-bas ; ils feront parfaitement l’affaire.\n\nUne fois que vous aurez réussi, rapportez l’âme capturée et le rubis à Menara.", progress = "Oui, <nom> ? Vous avez choisi ? Infernal ou gangrechien ?\n\nCe choix est personnel et doit refléter vos forces et vos faiblesses. On voit trop souvent des démonistes se spécialiser toujours plus au lieu de pallier leurs faiblesses. Il est vrai que, parfois, terrasser un adversaire rapidement est une tactique aussi efficace que celle qui consiste à opter pour un développement plus équilibré.", completion = "Ah, l'esprit d'un gangrechien. Très bien, &lt;nom&gt;.\n\nLorsque j'aurai l'esprit et l'orbe purifié, je les assemblerai pour vous, mais pas avant.", rewards = "Vous recevrez :\n\n"},
[4963] = {title = "Eclat d'Infernal", objective = "Prendre l’Emeraude d'Infus et l’utiliser sur les Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l’Emeraude d'Infus et l’Esprit d'Infernal emprisonné à Menara Voidrender, dans les Tarides.", description = "Ainsi, vous avez choisi de capturer l'esprit d'un Infernal. Très bien.\n\nPrenez cette émeraude. Avec elle, vous serez en mesure de capturer l'esprit de la créature. Cela fonctionne de la même manière que les sorts que vous connaissez déjà. Lorsque la créature est proche de la mort, servez-vous de cette gemme et elle devrait s'occuper du reste pour vous.\n\nJe suggèrerais de vous rendre en Désolace et de vous faire la main sur les Infernaux qui s'y trouvent. Ils devraient parfaitement faire l'affaire.\n\nUne fois que vous aurez réussi, apportez et l'esprit capturé et votre émeraude à Merana.", progress = "Oui, <nom> ? Vous avez choisi ? Infernal ou gangrechien ?\n\nCe choix est personnel et doit refléter vos forces et vos faiblesses. On voit trop souvent des démonistes se spécialiser toujours plus au lieu de palier à leurs faiblesses. Il est vrai que, parfois, terrasser un adversaire rapidement est une tactique aussi efficace que celle qui consiste à opter pour un développement plus équilibré.", completion = "Ah, l'esprit d'un infernal. Très bien, &lt;nom&gt;.\n\nLorsque j'aurai l'esprit et l'orbe purifié, je les assemblerai pour vous, mais pas avant.", rewards = "Vous recevrez :\n\n"},
[4964] = {title = "L'Orbe complet de Dar'Orahil", objective = "Attendre que Menara Voidrender termine l’Orbe de Dar'Orahil, puis lui reparler.", description = "Je vais de ce pas commencer à confectionner votre orbe et insuffler votre nouveau démon en lui. Quand cela sera fait, vous pourrez choisir de l’avoir sous la forme d’un orbe ou d’un bâton. J’ai toujours pensé qu’il était important de bien s’occuper de l’arme choisie par un démoniste et je ne vois pas pourquoi je ne continuerais pas à penser de la sorte.", progress = nil, completion = "C'est fait, &lt;nom&gt;. Il vous suffit de me dire ce que vous préférez. Un bâton que vous utiliserez à deux mains, ou un orbe que vous pourrez utiliser avec une dague ou une épée.\n\nSe mesurer au gangrechien était un haut fait. Je pense que votre objet vous sera utile à l'avenir. Continuez à vous entraîner pour maîtriser les arts, &lt;nom&gt;. J'attends des nouvelles de vos exploits.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe de Dar'OrahilBâton de Dar'Orahil\n\nVous recevrez également :\n\n"},
[4965] = {title = "Connaissance de l'Orbe d'Orahil", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Bien, bien, bien... c’est un plaisir de voir que vous gagnez en puissance, <nom>. Je parie que vous pourriez maintenant parler à Menara Voidrender, dans les Tarides. Si vous ne lui avez pas déjà parlé, alors laissez-moi vous dire que je n’ai jamais vu un autre expert en création d’objets magiques, d'orbes en particulier, qui puisse aussi facilement lier un démon au service de notre cause.\n\nSi vous y trouvez de l’intérêt, elle habite dans la Tour de Strahad qui domine Ratchet, dans les Tarides.", progress = nil, completion = "Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.\n\nC'est une bonne chose de voir quelqu'un de votre trempe rechercher la puissance autrement qu'à travers la connaissance.\n\nAlors, pensez-vous être prêt &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[4966] = {title = "Protéger Kanati Greycloud", objective = "Protéger Kanati Greycloud contre l’attaque centaure.", description = "Mais il se peut qu'il y ait plus de centaures que je ne le croyais. Je vous le demande, <nom>, battez-vous à mes côtés contre ces vils assassins.", progress = nil, completion = "Merci pour votre aide, &lt;nom&gt;. Je n'aurais pas pu m'en débarrasser sans vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes du pas rapideBrassards du terreauGants du trotteur solitaire\n\nVous recevrez également :\n\n"},
[4967] = {title = "Connaissance de l'Orbe d'Orahil", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Alors, toujours dans les affaires des mortels ? Oui, je me suis adressé à vous avec arrogance. Je vous vois devant moi, et je ris : vous êtes pathétique !\n\nMais ce que je pense n’a pas d’importance, seul importe ce que pensent ceux qui veulent traiter avec vous de quelque façon que ce soit ! Ainsi, et contre mon avis personnel, ceux qui ont quelque pouvoir estiment que vous méritez plus encore.\n\nParlez avec Menara Voidrender, dans la tour qui domine Ratchet. Je crois savoir que vous l’avez déjà rencontrée il y a quelque temps.", progress = nil, completion = "Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.\n\nC'est une bonne chose de voir quelqu'un de votre trempe rechercher la puissance autrement qu'à travers la connaissance.\n\nAlors, pensez-vous être prêt &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[4968] = {title = "Connaissance de l'Orbe d'Orahil", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Vous avez réussi à arriver jusqu’ici, c’est vraiment étonnant. Je croyais que la corruption émise par la canalisation des arcanes infiltrerait votre âme et vous rendrait fou. Pourquoi ne pas aller plus loin, dans ce cas ?\n\nSi vous voulez mettre à l’épreuve vos compétences, allez voir Menara Voidrender dans la Tour de Strahad qui domine Ratchet. Elle vous guidera.", progress = nil, completion = "Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.\n\nC'est une bonne chose de voir quelqu'un de votre trempe rechercher la puissance autrement qu'à travers la connaissance.\n\nAlors, pensez-vous être prêt &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[4969] = {title = "Connaissance de l'Orbe d'Orahil", objective = "Parler à Menara Voidrender dans les Tarides.", description = "Ha ha ! Vous êtes <ambitieux/ambitieuse>, jeune <classe>.\n\nEn temps voulu, les Infernaux et les Seigneurs de l'effroi s’inclineront devant vous !\n\nMais pour l’instant, vous ne devrez compter que sur des armes forgées par les races mortelles.\n\nUne autre de ces créations est disponible pour vous. Si vous le voulez, Menara Voidrender pourrait vous parler ! Elle se trouve près de la Tour de Strahad qui domine la ville portuaire de Ratchet. Partez quand vous jugerez le moment venu.", progress = nil, completion = "Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.\n\nC'est une bonne chose de voir quelqu'un de votre trempe rechercher la puissance autrement qu'à travers la connaissance.\n\nAlors, pensez-vous être prêt &lt;nom&gt; ?", rewards = "Vous recevrez :\n\n"},
[4970] = {title = "Provisions de sabres-de-givre", objective = "Récolter 5 Viandes de Croc acéré et 5 Viandes de Noroît pour Rivern Frostwind du Berceau-de-l'Hiver.", description = "Si vous souhaitez montrer votre valeur, vous devriez d'abord effectuer une tâche très simple, mais très importante cependant.\n\nRécupérez de la viande des chimères et d'ours Crocs acérés dans le secteur. Apportez-la-moi afin que je nourrisse les sabres-de-givre qui reçoivent un entraînement.", progress = "Vos objectifs sont discipline et détermination. Je peux vous demander d'effectuer une simple tâche à de nombreuses reprises ; il vous faut l'exécuter chaque fois au mieux de vos possibilités.", completion = "Merci de votre aide, &lt;nom&gt;. Mon respect pour vous croît avec le temps.", rewards = nil},
[4971] = {title = "Une question de temps", objective = "Utiliser le Déplaceur temporel à côté de l’un des silos d’Andorhal pour révéler des Parasites temporels.\n\nTuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l’auberge d’Andorhal, dans les Maleterres de l’ouest.", description = "Une altération du passage du temps par une force sinistre, la Horde très probablement, est survenue à Andorhal ! Je peux tenter de conserver le passage du temps intact ici et réparer ce qui a été endommagé, mais je vais avoir besoin de votre aide pour que je le fasse de manière ininterrompue.\n\nDes Parasites temporels infestent à présent les silos d'Andorhal. Une pulsation bleue est le seul signe visible que nous ayons d'eux. Ils ralentissent mes augures. S'il vous plaît, <nom>, aidez-moi en vous servant de ce Déplaceur temporel afin de déloger ces parasites.", progress = "Les parasites temporels sont une maladie courante que l'on rencontre là où le cours du temps a été altéré. Je sens qu'ils sont nombreux et c'est préoccupant.\n\nCapturez ceux que vous rencontrerez ; en les étudiant je pourrais analyser la gravité de la situation et savoir quand cela s'est produit.", completion = "Le Temps semble plus facile a rétablir, merci &lt;nom&gt;. Bien que vous ne saisissiez pas forcément tout ce qu'implique une trame temporelle brisée, j'apprécie votre empressement à vouloir contrer au plus vite ce qui semble être un nouveau plan machiavélique fomenté par le Fléau.\n\nJe ne vois aucun mal à vous récompenser pour votre aide, mortel. Vos plus hauts faits restent à venir et le don que je m'apprête à vous faire ne risque pas d'altérer votre destinée. Les dragons et moi-même apprécierons toujours votre aide...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmict de l'orchidéeCeinture tressée d'or\n\nVous recevrez également :\n\n"},
[4972] = {title = "Arrêt du temps", objective = "Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest.", description = "J’ai besoin que vous passiez dans le monde qui se trouve derrière cette pièce, <nom>. Je vais être plus clair.\n\nVous avez remarqué que cette pièce était différente des autres parties d’Andorhal. Mon vol de dragons agit dans différents plans et différents flux temporels. Pour réparer les dégâts d'Andorhal, j’agis à partir d’autres flux temporels, évitant ainsi toute contamination de ce plan. Pour pouvoir continuer, j’ai besoin des bijoux temporels qui ont été pris dans le cours du temps lorsque le mal se déclara. Vous les trouverez dans des coffrets qui traînent parmi les ruines de cette ville, jadis majestueuse.", progress = "Les babioles temporelles que vous recherchez sont des mécanismes simples. Ce sont des horloges pour la plupart, et leurs aiguilles sont restées figées lorsque la Peste a ravagé Andorhal.\n\nLe temps est sans fin et les horloges que vous m'apportez, lorsqu'elles seront placées où elles doivent être, arrêteront le temps... en fait, aussi longtemps que les distortions continueront à se produire.", completion = "Exactement ce dont j'avais besoin, &lt;nom&gt;. Merci.\n\nPermettez-moi de vous récompenser en vous offrant ceci. Vous ne voyez peut-être pas l'utilité d'un tel mécanisme. Vous ne saurez peut-être même jamais ce que c'est réellement. Je ne peux pas vous dire quand est-ce que vous en aurez besoin, mais sachez que dans un avenir proche, il vous servira et vous apprécierez son utilité. Si vous arrivez à patienter jusque là... Cette décision vous appartient.", rewards = "Vous recevrez :\n\nAtténuateur en phase"},
[4973] = {title = "Arrêt du temps", objective = "Trouver 5 Montres d'Andorhal parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest.", description = "Si vous voulez encore aider, nous pourrions avoir de nouveau besoin de votre assistance. J'accepterais volontiers les horloges supplémentaires que vous pourriez trouver dans les ruines d'Andorhal. Elles me serviraient pour maintenir l'équilibre du flux temporel, malgré les forces hostiles qui sont en train de s'y incorporer, ici.\n\nEn échange de ces horloges, je vous remettrai un autre objet qui vous sera certainement utile dans le futur.", progress = "Les horloges d'Andorhal, comme la grande horloge des ruines de l'hôtel de ville, sont restées figées sur la troisième heure. Ça date de l'époque où les premiers effets de la Peste se sont fait ressentir sur la ville, supprimant toute vie.\n\nBien que nous regrettions tous ce qui est arrivé ce jour là, le cours du temps tel que vous le concevez, vous les mortels, a été interrompu. Les dragons de bronze doivent persévérer et protéger le cours du temps !", completion = "Une fois de plus, je vous remercie pour votre aide. Veuillez accepter ce présent. Bien que vous ne sachiez pas encore comment utiliser cet objet, peut-être un jour le temps vous en révélera-t-il les véritables desseins, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nAtténuateur en phase"},
[4974] = {title = "Pour la Horde !", objective = "Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar.", description = "Rend ose prononcer de telles revendications parce qu’il sait qu’il est sous la protection des dragons noirs.\n\nVous, <nom>, trouverez un moyen de traverser les Halls de l’Ascension. Après vous trouverez le ‘Chef de guerre' Rend Blackhand et vous le détruirez - AU NOM DE LA HORDE !\n\n<Thrall abat son poing sur le trône.>\n\nLa prochaine fois que vous viendrez dans mon domaine, vous porterez sa tête, comme trophée, et la présenterez à votre Chef de guerre. Faites cela et soyez <honoré/honorée> comme <héros/héroïne> de la Horde.", progress = "<Thrall grogne.>", completion = "Vous avez porté un coup fatal aux forces de Blackrock, &lt;nom&gt;. Leur Chef de guerre mort, la légion Blackrock est une fois de plus plongée dans le chaos.\n\nPour honorer vos efforts héroïques, le peuple de Kalimdor sera récompensé !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarque de tyrannieOeil de la BêtePlaque de Blackhand\n\nVous recevrez également :\n\n"},
[4975] = {title = "L'Orbe complet de Noh'Orahil", objective = "Attendre que Menara Voidrender ait terminé l’Orbe de Noh'Orahil, puis lui reparler.", description = "Je vais de ce pas commencer à confectionner votre orbe et insuffler votre nouveau démon en lui. Quand cela sera fait, vous pourrez choisir de l’avoir sous la forme d’un orbe ou d’un bâton. J’ai toujours pensé qu’il était important de bien s’occuper de l’arme choisie par un démoniste et je ne vois pas pourquoi je ne continuerais pas à penser de la sorte.", progress = nil, completion = "C'est fait, &lt;nom&gt;. Il vous suffit de me dire ce que vous préférez. Un bâton que vous utiliserez à deux mains, ou un orbe que vous pourrez utiliser avec une dague ou une épée.\n\nSe mesurer à l'Infernal était un haut fait et vous méritez cette récompense. Je vous souhaite de nombreux succès dans la maîtrise des arts, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nOrbe de Noh'OrahilBâton de Noh'Orahil\n\nVous recevrez également :\n\n"},
[4976] = {title = "Rapporter l'Orbe purifié", objective = "Rapporter l’Orbe infernal purifié à Menara Voidrender, dans les Tarides.", description = "Rapportez l’orbe purifié à Menara, dans Ratchet, <nom>. Faites-lui mes amitiés ; j’espère que vous saurez résister à la tentation et à la corruption que vous rencontrerez sûrement sur votre chemin.\n\nBonne chance.", progress = "Comment avancent vos recherches sur Tabetha et l'orbe, <nom> ?\n\nTabetha fut très utile lorsque survinrent les problèmes des arcanes. Je suis certain qu'elle n'aura aucun problème pour vous aider, si vous la trouvez.", completion = "Bien joué, &lt;nom&gt;. Cela fera l'affaire.\n\nLa seule chose qui vous reste à faire, c'est de m'indiquer quel démon vous voulez que j'emprisonne avec l'orbe purifié. Après ça, vous aurez un nouvel objet magnifique à porter.", rewards = "Vous recevrez :\n\n"},
[4981] = {title = "Agent Bijou", objective = "Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou.", description = "Et voilà ce qui arrive quand on fait confiance à un gobelin <nom>.\n\nElle s’appelle Bijou ; l’un de nos agents les plus insaisissables. J’ai trouvé qu’elle travaillait pour quelque louche et exotique vendeur de familiers, à l’extérieur des Steppes ardentes, répondant au nom de Kibler. Ce qui est encore pire, c’est qu’elle utilisait les fonds de la Horde pour financer ses opérations.\n\nJe veux qu’elle soit amenée ici, vivante.\n\nLa dernière fois qu’on l’a vue, elle était au pic Blackrock. Retrouvez-la et ramenez-la.\n\nEt, <nom>, ne lui donnez pas l’opportunité de vous chanter de douces paroles.", progress = nil, completion = "Je ne vous mentirai pas, &lt;nom&gt;. J'avais besoin d'argent ! Kibler paie très, très bien ; bien mieux que le K.E.F. ne le pourra jamais.\n\nMais ne doutez pas de ma loyauté ! Pourquoi pensez-vous que je suis ici ? Pour fournir à ce gobelin délirant des oeufs d'animaux exotiques ou quelque chose du genre ? Non, seul un fou viendrait au pic Blackrock pour collecter des familiers. Oui, mais je ne pense pas que les personnes de ce genre soient nombreuses en ce bas monde.\n\n\n\nLa dernière chose dont nous avons besoin, c'est bien d'eux.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4982] = {title = "Les effets de Bijou", objective = "Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville.", description = "La nuit, quand la garde de cet endroit se relâche, je rôde autour de la ville, prenant des notes et écrivant toute observation qui pourrait avoir un intérêt stratégique pour le K.E.F.\n\nCependant, la nuit dernière, les choses ont très mal tourné. J’ai trébuché sur le fil d’un système d’alarme et ai déclenché l’alerte. J’ai dissimulé mon équipement de reconnaissance et ai trouvé une cachette ! Malheureusement, je ne puis retourner récupérer cet équipement. Ils ont triplé la fréquence des patrouilles ! Toutes ces informations sont perdues.\n\nRapportez-moi mes affaires que je puisse retourner au K.E.F., l’âme en paix.", progress = "Alors ?", completion = "Vous avez réussi ! Une fois que Lexlort aura ces plans, Il oubliera toutes les vilaines choses qu'il voulait m'infliger.\n\n&lt;nom&gt;, vous êtes mon héros !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[4983] = {title = "Rapport de reconnaissance de Bijou", objective = "Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath.", description = "Portez ce rapport à Lexlort. Cela rachètera mes erreurs et donnera des informations stratégiques au K.E.F., lesquelles les avantageront dans leur lutte contre les orcs.\n\nVenir avec vous ? J’ai beaucoup trop de travail à faire. Partez, ils ont besoin de ce rapport aussi vite que possible !", progress = "Où est le gobelin ?", completion = "Je dois le lui donner ; elle a réussi à se sortir d'une autre situation délicate ! Ces rapports vont s'avérer inestimables dans notre affrontement avec les orcs de Blackrock.\n\nBien sûr, vous serez récompensé pour ce travail.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de LibreventCeinturon de l'escale\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[4984] = {title = "La faune et la flore souffrent aussi", objective = "Détruire 8 Loups malades, puis retourner voir Mulgris Deepriver, au Repaire putride dans les Maleterres de l’ouest.", description = "Seul, je ne peux pas faire grand-chose pour contrecarrer le Fléau, mais je suis néanmoins venu sur ces terres pour tenter de guérir les blessures subies par la nature. Les animaux souffrent de la peste qui plane encore sur ces terres, sans espoir de retrouver l'équilibre et la paix. Je vous demande de continuer ce que je n'ai pu achever ici.\n\nIl n'y a pas de plus doux remède pour ces animaux qui souffrent qu'une fin douce et miséricordieuse. Recherchez des loups malades aux alentours et mettez fin à leur misère.\n\nJe vous en prie, <nom>, mettez un terme à leur souffrance. Ainsi la mienne diminuera peut-être.", progress = "Les loups pestiférés doivent être éliminés, <nom>. La maladie qu'ils ont contractée n'a pas de remède. J'ai essayé... J'ai essayé jusqu'à ce que je succombe à la peste.", completion = "Je... je sens que les âmes de ces loups sont enfin libérées. Ils vous remercient de cette délivrance, et je vous en remercie aussi.\n\nLes loups n'étaient pas les seuls à souffrir de cet endroit maléfique, &lt;nom&gt;. S'il vous plaît, j'ai encore besoin de vous.", rewards = "Vous recevrez :\n\n"},
[4985] = {title = "La faune et la flore en souffrent aussi", objective = "Détruire 8 Grizzlis malades, puis retourner voir Mulgris Deepriver au Repaire putride, dans les Maleterres de l’ouest.", description = "A l’est, non loin de l’endroit où commencent les Maleterres de l'est, de fiers et majestueux grizzlis parcouraient la campagne. La peste lâchée par le Fléau a frappé ces superbes bêtes. Ils errent maintenant sur la lande, tourmentés par la tétanie de leurs muscles et le pourrissement de leur fourrure et de leurs chairs.\n\nDélivrez-les de leurs souffrances. La seule médecine à une telle affliction est une mort rapide, et c’est cette médecine qu’il vous faudra appliquer.", progress = "Je vous ai entendu approcher, <nom>. J'ai perdu la vue, mais je suis encore capable de sentir les choses qui m'entourent. Avez-vous mis fin aux souffrances des grizzlys malades ?", completion = "Je sais que les grizzlis ont été terrassés, leur tourment est terminé. Je... J'ai encore quelque chose pour vous. Je l'ai écrit sur... cette branche, sentant que mes heures dans ce royaume étaient comptées.\n\nD'ailleurs... Je me sens faiblir. Merci encore mon ami... Les créatures de cette terre maudite peuvent reposer... et moi aussi.\n\nC'est avec un regard lourd que le druide émet un dernier râle. Son corps repose sans vie sur le sol de la chaumière.", rewards = "Vous recevrez :\n\n"},
[4986] = {title = "La branche de chêne à glyphes", objective = "D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l’assistance de l’un des druides, là-bas.", description = "La main sans vie du druide tauren est agrippée à une branche de chêne d’aspect étonnamment sain. En examinant la branche, vous découvrez des inscriptions de nature druidique gravées dans l’écorce.\n\nComme vous la prenez en main, vous remarquez qu’une curieuse tiédeur en émane. L’image de l’Arbre-monde de Teldrassil s'impose dans votre esprit, Darnassus, pour être plus précis, ainsi que les mots : \"Cercle cénarien\". C’est comme si le lieu où emporter la branche était compris en elle.", progress = "Au nom du Cercle cénarien, je vous souhaite la bienvenue dans cette enclave, <classe>. Qu'est-ce qui vous amène ?", completion = "C'est... C'est très étrange. Ce druide tauren vous a divulgué de précieuses informations concernant la propagation du Fléau. Je suis surpris qu'un tauren ait révélé de telles informations à quelqu'un de votre espèce et sans rien demander en retour de surcroît. Nous en ferons bon usage, je vous le promets, &lt;nom&gt;. Peut-être que les taurens ne se sont pas autant écartés de Cénarius que Fandral le croit...\n\nMais, de toute façon, acceptez ceci en guise de récompense de la part du Cercle cénarien.", rewards = "Vous recevrez :\n\nDrapé cerise"},
[4987] = {title = "La branche de chêne à glyphes", objective = "D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Thunder Bluff. Aller solliciter l’assistance de l’un des druides, là-bas.", description = "La main sans vie du druide tauren est agrippée à une branche de chêne d’aspect étonnamment sain. En examinant la branche vous découvrez des inscriptions de nature druidique gravées dans l’écorce.\n\nComme vous la prenez en main, vous remarquez qu’une curieuse tiédeur en émane. L’image de Thunder Bluff, à Mulgore, s'impose dans votre esprit, la Cime des Anciens, pour être plus précis, ainsi que les mots : \"Cercle cénarien\". C’est comme si le lieu où emporter la branche était compris en elle.", progress = "Au nom du Cercle cénarien, je vous souhaite la bienvenue dans cette enclave, <classe>. Qu'est-ce qui vous amène ?", completion = "Cela vient de Mulgris, dites-vous ? Nous avions entendu dire qu'il cherchait à secourir les créatures souffrantes dans les Maleterres, mais ceci est tout à fait inattendu… et très triste. Mulgris est… était un ami. Je pleurerai sincèrement sa mort.\n\nSes efforts n'ont pas été vains, grâce à votre diligence. A ce sujet, il renferme de nombreux récits sur la peste que le Fléau propage sur les terres. Nous l'étudierons avec soin. En ce qui vous concerne, je vous prie d'accepter ceci. C'est le moins que nous puissions faire pour vous remercier de vos nobles efforts.", rewards = "Vous recevrez :\n\nDrapé cerise"},
[5001] = {title = "Les effets de Bijou", objective = "Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !", description = "D’ordinaire, je ne traite pas avec les gens de votre race, <race>, mais il semble que je sois acculé à cette extrémité. Ma mission, voyez-vous, est de la plus haute importance pour la Horde. L’information que j’ai découverte peut intéresser cependant également l’Alliance. Pourtant, croyez-moi, je ne suis pas un partisan de l’Alliance. La menace Blackrock est cependant autrement plus grave que celle d'une simple bande d’orcs.\n\nAidez-moi à retrouver mes affaires et je vous donnerai des informations qui pourront vous servir, ainsi qu’à ceux de votre espèce.\n\nÇa vous va ?", progress = "Alors ?", completion = "Bien, j'en suis ! Où sont-ils ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5002] = {title = "Message à Maxwell", objective = "Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell.", description = "Je suis un gobelin de parole, <nom>. À présent, écoutez attentivement :\n\nCes orcs sont avant tout utilisés comme bêtes de somme et comme chair à canon par les dragons noirs !\n\nLeur véritable chef n'est autre que Nefarian, rejeton de l'Aile de mort. J'ai également découvert la localisation des subordonnés de Nefarian dans cette partie de la citadelle.\n\nApportez cette carte au maréchal Maxwell dans les Steppes ardentes. J'y ai marqué la localisation de ces monstres afin qu'on puisse les trouver facilement.", progress = "Ah, <nom>. Ça faisait longtemps.", completion = "Cela coïncide dans les grandes lignes avec ce que nous savions déjà. Toutefois, c'est une information intéressante et assez négative.\n\nLes indications sur cette carte nous seront utiles pour réduire la menace Blackrock.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5021] = {title = "Mieux vaut tard que jamais", objective = "Le discours incohérent de la femme fantomatique indique qu’elle a besoin qu’on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu’il s’agit de préciser où se trouve son cheval ou l’endroit où le paquet doit être livré.", description = "Le colis doit être remis… remis avant que je ne sois emprisonnée ici !\"\n\nLes pleurs d'une femme prise de panique semblent presque comme un murmure flottant dans la maison. L'apparition recroquevillée d'une femme se trouve dans le coin à l'étage. Elle ne semble pas être complètement consciente de ce qui l'entoure, et ne perçoit votre présence que très faiblement.\n\n\"Êtes-vous là pour me remettre mon colis ? Vite, avant que ça n'empire ! J'allais partir d'ici à cheval. Ce devrait toujours être mon cheval... ou est-ce trop tard ?", progress = nil, completion = "Un paquet dans la grange qui, sinon, vous aurait échappé, se détache dans le délabrement et la ruine. Peut-être est-ce là l'objet des vociférations du fantôme de Janice Felstone…", rewards = "Vous recevrez :\n\n"},
[5022] = {title = "Mieux vaut tard que jamais", objective = "Rendre visite aux Facteurs royaux de Stormwind pour apprendre l’adresse d’une certaine Emma Felstone. En général, il y a un officier du recensement à l’Hôtel de ville.", description = "Vous ramassez le colis et époussetez la petite couche de poussière qui s'y était déposée. Il est adressé, d'une main hâtive, à une certaine Emma Felstone, à Stormwind. La remise du paquet date de plus de quatre ans.\n\nBien qu'il ne soit même pas certain qu'Emma Felstone soit toujours en vie, il est de notoriété publique que la mairie de Stormwind garde sur ses registres la population de la ville. Les responsables royaux du recensement de Stormwind s'en occupent.", progress = "Bienvenue au bureau de l'agent recenseur de Stormwind. Si vous avez besoin d'informations sur notre peuple, je puis vous aider.", completion = "Un paquet pour une Emma Felstone, dites-vous ? La dernière adresse connue est à Stormwind, il y a quatre ans ? Eh bien voyons voir…\n\nD'après ce que nous savons, il y avait bien une Emma Felstone dans la cité il y a quatre ans environ. Hum, je dirais que c'est possible... Le recensement auquel je me réfère date de cinq ans, et je n'ai pas de trace indiquant son départ de la cité. Toutefois, cela ne signifie pas qu'elle soit toujours là.\n\nAttendez une seconde... Ce paquet ne serait pas pour la vieille Emma, par hasard ?", rewards = "Vous recevrez :\n\n"},
[5023] = {title = "Mieux vaut tard que jamais", objective = "Se renseigner auprès des Surveillants royaux d’Undercity pour apprendre l’adresse d’un certain Jeremiah Felstone. En général, il y a un officier du recensement près du bureau d’inscription des guildes et tabards.", description = "Vous ramassez le colis et époussetez la petite couche de poussière qui s'y était déposée. Il est adressé, d'une main hâtive, à un certain Jeremiah Felstone, à Lordaeron. La remise du paquet date de plus de quatre ans.\n\nBien qu'il ne soit même pas certain que Jeremiah Felstone soit toujours en vie, il est de notoriété publique qu'Undercity, anciennement connue sous le nom de Lordaeron, garde sur ses registres la population de la ville. Les surveillants royaux du recensement d'Undercity s'en occupent.", progress = "Vous êtes ici pour chercher de l'aide auprès de l'agent recenseur d'Undercity ou juste pour me demander si quelqu'un que vous connaissiez est mort ? On me pose souvent cette question.", completion = "Un paquet pour un Jeremiah Felstone, avec une dernière adresse à Lordaeron… Je devrais pouvoir vous aider.\n\nJeremiah Felstone était dans la cité avant la peste. En fait, je devrais dire l'ex-Jeremiah Felstone - certains des Réprouvés ont modifié leur nom pour se débarrasser de leur passé. Ce cas ne fait pas exception, l'ex-Jeremiah Felstone est maintenant connu sous le nom de Jeremiah Payson.\n\nAttendez une minute... ce ne serait pas le vendeur de cafards ?", rewards = "Vous recevrez :\n\n"},
[5041] = {title = "Ravitaillement pour la Croisée", objective = "Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides.", description = "La caravane attaquée contenait des provisions dont nous avons désespérément besoin.\n\nVous avez été suffisamment <courageux/courageuse> pour en découdre avec la tribu Tranchecrin jusqu'alors, mais cette fois-ci, je me demande si je pourrais vous demander de chercher certaines de nos provisions volées. Vous les trouverez probablement un peu partout dans leurs campements, les hurans devant s'engraisser de leurs actes méprisables.\n\nLes habitants de la Croisée vous en seraient reconnaissants.", progress = "Comment se passe votre recherche de fournitures, <nom> ? Je suis sûr que vous avez maîtrisé les hurans facilement.", completion = "Ha ha ! Merci, &lt;nom&gt; ! Cela nous est d'une grande aide. Vous êtes une bénédiction pour la Croisée et la Horde. Si je puis faire quelque chose pour vous, je vous en prie, dites-le-moi.", rewards = "Vous recevrez :\n\n"},
[5042] = {title = "La force d’Agammagan", objective = "J'aurai besoin de quatre Joyaux de sang si vous voulez la force d'Agammagan, <nom>.\n\nVos ennemis s'enfuiront devant votre pouvoir si vous avez cette bénédiction. \n\nLes plus grands guerriers Tranchecrin sont d'une telle puissance !", description = nil, progress = "J'aurai besoin de quatre Joyaux de sang si vous voulez la force d'Agammagan, <nom>.\n\nVos ennemis s'enfuiront devant votre pouvoir si vous avez cette bénédiction. \n\nLes plus grands guerriers Tranchecrin sont d'une telle puissance !", completion = "Si seulement Mangletooth était libre pour vous voir décimer ceux qui l'ont trahi ! &lt;grogne&gt;\n\nMerci d'avoir détruit plus de Dos-hirsute en ramassant ces joyaux. S'il vous plaît, continuez ainsi, et je continuerai à vous aider.&lt;grogne&gt;", rewards = "Vous apprendrez :\n\nLa force d’Agammagan"},
[5043] = {title = "L'agilité d'Agammagan", objective = "Les meilleurs éclaireurs de ma tribu ont la réputation d'être d'une précision sans rivale, et nul ne peut égaler leur rapidité au combat.\n\nApportez-moi 4 Joyaux de sang et je vous rendrai plus agile que n'importe quel huran.", description = nil, progress = "Les meilleurs éclaireurs de ma tribu ont la réputation d'être d'une précision sans rivale, et nul ne peut égaler leur rapidité au combat.\n\nApportez-moi 4 Joyaux de sang et je vous rendrai plus agile que n'importe quel huran.", completion = "Que votre visée soit infaillible et votre arme précise, &lt;nom&gt;.\n\nL'esprit d'Agammagan est avec vous. Revenez  me voir si vous le souhaitez. Mangletooth vous bénira de nouveau si le grand dieu sanglier m'estime digne de confiance.", rewards = "Vous apprendrez :\n\nL'agilité d'Agammagan"},
[5044] = {title = "La sagesse d'Agammagan", objective = "Les chamans et les géomanciens des tribus huranes <grogne> invoquent la force d'Agammagan pour les aider au combat et dans leurs rituels, <nom>.\n\nSi vous voulez la bénédiction d'un surcroît de pouvoir d'Agammagan dans vos sorts, apportez-moi 4 Joyaux de sang et Mangletooth vous aidera.", description = nil, progress = "Les chamans et les géomanciens des tribus huranes <grogne> invoquent la force d'Agammagan pour les aider au combat et dans leurs rituels, <nom>.\n\nSi vous voulez la bénédiction d'un surcroît de pouvoir d'Agammagan dans vos sorts, apportez-moi 4 Joyaux de sang et Mangletooth vous aidera.", completion = "Vos ennemis devraient redoubler de crainte devant vous, &lt;nom&gt;. \n\nDites à Mangletooth la ruse dont vous faites preuve dans les combats pour notre prochaine rencontre, dans cette vie ou une autre.", rewards = "Vous apprendrez :\n\nLa sagesse d'Agammagan"},
[5045] = {title = "L'essor de l'esprit", objective = "Tous les guerriers, quels qu'ils soient, <grogne> ont besoin d'un esprit fort. Il vous conduit à l'exploit quand tout espoir est perdu. Ceci n'est pas ignoré <grogne> des Tranchecrins. Nous sommes une tribu spirituelle - nous sommes plus fiers de notre lien à Agammagan que de nos prouesses <grogne> au combat.\n\nApportez-moi quatre Joyaux de sang et je bénirai votre esprit de lutte.<grogne>", description = nil, progress = "Tous les guerriers, quels qu'ils soient, <grogne> ont besoin d'un esprit fort. Il vous conduit à l'exploit quand tout espoir est perdu. Ceci n'est pas ignoré <grogne> des Tranchecrins. Nous sommes une tribu spirituelle - nous sommes plus fiers de notre lien à Agammagan que de nos prouesses <grogne> au combat.\n\nApportez-moi quatre Joyaux de sang et je bénirai votre esprit de lutte.<grogne>", completion = "Nos plus braves guerriers et nos plus braves &lt;grogne&gt; chamans envieraient votre volonté, &lt;nom&gt;.\n\nBattez plus de Dos-hirsute maintenant que nous savons qu'il ne peuvent plus vous stopper !", rewards = "Vous apprendrez :\n\nL'essor de l'esprit"},
[5046] = {title = "Peau tranchante", objective = "Tous ceux qui <grogne> se battent ont besoin de protection. Leurs os doivent être solides. Leur peau résistante.<grogne> Ma tribu le sait bien, et pour renforcer les protections naturelles de nos plumes et de nos dards <grogne> nous faisons appel à la protection d'Agammagan avant de partir pour la guerre.\n\nApportez-moi 4 Joyaux de sang <grogne> et je vous obtiendrai cette même protection.", description = nil, progress = "Tous ceux qui <grogne> se battent ont besoin de protection. Leurs os doivent être solides. Leur peau résistante.<grogne> Ma tribu le sait bien, et pour renforcer les protections naturelles de nos plumes et de nos dards <grogne> nous faisons appel à la protection d'Agammagan avant de partir pour la guerre.\n\nApportez-moi 4 Joyaux de sang <grogne> et je vous obtiendrai cette même protection.", completion = "Partez à la guerre, &lt;nom&gt;.", rewards = "Vous apprendrez :\n\nPeau tranchante"},
[5047] = {title = "Pépin Preste-Jugeote, à votre service !", objective = "Parler à Malyfous Darkhammer à Long-guet.", description = "Vous trouverez Malyfous Darkhammer à Long-guet, <classe>. Dites-lui que « Pépin est très content » et que la tenue marche parfaitement.\n\nPuis donnez-lui ceci :\n\n<Pépin vous tend un morceau de chair rouge.>\n\nC’est un bout d’entrailles que j’ai arraché à une bête pendant mes « vacances».\n\nJe parie que Malyfous pourrait vous donner une idée précise de ce qu’il pourrait faire avec un morceau de bête comme celle-là !\n\nOh, mais vous ne savez peut-être pas où est Long-guet ? Direction le Berceau-de-l’Hiver, <mon bon monsieur/ma bonne dame> !", progress = "Ouais ?", completion = "Vivant ? Et la tenue a fonctionné ? Et qu'avons-nous là ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5048] = {title = "Emma la bonne pâte", objective = "Trouver la vieille Emma à Stormwind, et découvrir si elle est en fait Emma Felstone. Si c’est le cas, elle appréciera peut-être le colis que Janice Felstone lui a préparé.", description = "Elle est un peu revêche, et perd certainement la tête... mais les archives indiquent qu'Emma correspond au signalement d'Emma Felstone.\n\nVous avez peut-être vu la vieille Emma errer dans la ville ? Elle parle toute seule, et la plupart du temps, c'est du charabia. Elle ne fait de mal à personne, alors les gens la laissent tranquille.\n\nTout bien considéré, je dirais qu'effectivement la vieille Emma doit être Emma Felstone. Essayez de lui demander si son nom de famille est bien Felstone.", progress = "Je vous dirais bien de déguerpir de mon gazon, mais vous voyez, je n'en ai pas.", completion = "Mon nom est bien Emma Felstone... Mais on ne m'a pas appelée ainsi depuis des années. Qui… Qui êtes-vous ?\n\nVous disiez connaître... ma sœur ? Est-elle toujours vivante ? Non, bien sûr que non. Lorsque l'épidémie s'est répandue dans Lordaeron, j'ai redouté le pire. Tant de mes parents ont péri... ou pire. Et me voici, la vieille Emma, toute seule. Qui êtes-vous ? Une espèce de pilleur de sépulture ? À la recherche d'une nouvelle tombe à saccager ?\n\nPardon ? Vous avez un paquet pour moi venant de ma soeur ?", rewards = "Vous recevrez :\n\n"},
[5049] = {title = "Le blues de Jeremiah", objective = "Trouver Jeremiah Payson dans Undercity et découvrir s’il est en fait Jeremiah Felstone. Si c’est le cas, il appréciera peut-être le colis que Janice Felstone lui a préparé.", description = "Au vu des preuves que j'ai pu rassembler, la personne que vous cherchez, à savoir le bénéficiaire du terrain, est Jeremiah Payson, le Vendeur de cafards d'Undercity.\n\nJ'ai toujours pensé qu'il fallait avoir une vocation pour vendre...des cafards. Nul doute que votre quête est des plus épiques, puissant <classe>. Je vais vous laisser à vos prouesses de sauveur du monde. Permettez-moi cependant, de jouer un rôle dans votre magnus opus en vous disant qu'il est situé près de la rive, certainement en train de farfouiller sous les trottoirs.", progress = "Chaque fois qu'on écrase un cafard, je pleure. S'il vous plaît, ne me faites pas pleurer.", completion = "Je ne porte plus ce nom depuis des années... mais oui, autrefois -avant cette vie misérable- c'était bien mon nom.\n\nVous affirmez avoir connu ma soeur… ou plutôt lui avoir parlé récemment.\n\nMais elle est morte.\n\nDepuis quatre ans.\n\nVous savez, si mes os n'étaient pas déjà si fragiles, je serais tenté de me briser le pied sur votre postérieur... Vous êtes un vrai vautour, n'est-ce pas ?\n\nQuoi... Vous avez un paquet pour moi venant de ma soeur ?", rewards = "Vous recevrez :\n\n"},
[5050] = {title = "Charme porte-bonheur", objective = "Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l’ouest.", description = "Il semblerait que j'ai eu tort à votre propos, <nom>, et pour cela je vous dois des excuses. Ma soeur m'a envoyé une quantité d'effets personnels, y compris, assez ironiquement, le titre de propriété de la ferme de Felstone. Je pense que j'éviterai de la réclamer pour l'instant.\n\nSi l'esprit de ma soeur reste attaché à la ferme et qu'elle ne trouve pas le repos, s'il vous plaît, pourriez-vous... lui retourner ceci ? C'est une moitié du charme porte-bonheur qu'elle possédait, son mari ayant l'autre moitié.\n\nPeut-être que si elle savait que j'ai ces choses, son esprit trouverait le repos.", progress = "John, chéri… Est-ce vous ? J'ai si froid tout d'un coup…", completion = "Vous tendez la moitié du charme à l'apparition. Elle le regarde puis tourne un regard plein d'attentes vers vous.\n\n\"Bien-aimé, où est votre moitié du charme ? Nous ne pourrons nous retrouver sans les deux moitiés. Chéri… pouvez-vous me voir ?\"", rewards = "Vous recevrez :\n\n"},
[5051] = {title = "Deux moitiés deviennent Une", objective = "Trouver l’autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Felstone dans les Maleterres de l’ouest et le recoller.\n\nDonner le Charme porte-bonheur à Janice Felstone à la Ferme Felstone, dans les Maleterres de l’ouest.", description = "Les divagations de ce pauvre fantôme continuent : \n\n\"J'ai si froid, John. Apportez-moi votre charme et nous serons réunis à nouveau ! Vite John, avant que la peste ne nous transforme en créatures hideuses ! Je n'arrive pas à vous voir John…mais je sais que vous êtes proche. Je sens votre présence.\"\n\nPeut-être qu'en trouvant la deuxième moitié du charme et en le réassemblant, cela constituerait ce que l'esprit de Janice Felstone recherche.\"", progress = "John, ne te laisse pas attraper par les goules… Ne les laisse pas m'attraper… Affreuses goules… Notre charme nous protègera.", completion = "Vous donnez le charme porte-bonheur reconstitué au fantôme de Janice Felstone. Dès qu'elle s'en saisit, vous voyez un changement presque immédiat en elle. Sa forme éthérée vacille, et elle vous regarde de ses yeux clairs et tristes.\n\n\"Vous m'avez libérée... Je n'aurai plus besoin de ce charme. Gardez-le, il vous apportera peut-être le réconfort qu'il m'a donné.\"", rewards = "Vous recevrez :\n\nPorte-bonheur de Felstone"},
[5052] = {title = "Joyaux de sang d'Agammagan", objective = "Apporter un Joyau de sang à Mangletooth, à Camp Taurajo, dans les Tarides.\n\nCollectez plus de Joyaux de sang, si vous souhaitez qu’il vous gratifie de la puissance d’Agamaggan.", description = "A l’instar des ronces, le sang a modifié <grogne> certains aspects de la terre : les pierres rouge sang se sont mélangées à d'autres minéraux. Les Dos-hirsute déterrent ces pierres pointues et les portent comme des totems <grogne> représentant la force au combat et comme symbole de leurs pouvoirs. <grogne>\n\nJe connais les secrets de cette magie.\n\nRamenez à Mangletooth l'une de ces pointes rouge sang et montrez ainsi que vous avez compris. Ramenez-en plusieurs et il vous offrira la magie des hurans, la magie d'Agammagan ! <grogne>", progress = "Nos tribus se rassemblent dans les zones épineuses des Tarides <grogne> car ce sont des endroits sacrés, mais nul n'est aussi sacré que Tranchebauge. Le corps d'Agammagan couvre l'intégralité de Tranchebauge,<grogne> mais les Souilles sont tout particulièrement protégées car sa large gueule en est l'entrée ! <grogne> Il avalera ceux qui lui sont déloyaux et recrachera leur corps après les avoir mâchés ! <grogne>\n\nAgammagan nous a laissé son corps pour nous protéger et nous donne son esprit pour que nous puissions le protéger.<grogne>", completion = "Ah ! vous comprenez. &lt;grogne&gt; Mes mots ne sont pas perdus pour vous, &lt;nom&gt;. Mangletooth est peut-être enfermé, mais aucune cage ne peut arrêter la puissance d’Agammagan ! \n\nLe contact du joyau, la sensation… cela faisait longtemps, &lt;nom&gt;.\n\nVous savez ce qu'on ressent ? Quand on vous prive de votre pouvoir ?\n\nMais je vous le raconterai une prochaine fois. Je vous ai promis des informations. Je vous ai promis le pouvoir d'Agammagan. Mon peuple a tourné le dos à Mangletooth. Maintenant, je vous lâche sur eux.", rewards = "Vous recevrez :\n\n"},
[5054] = {title = "Ursius des Crocs acérés", objective = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius.", description = "Dans les montagnes neigeuses du Berceau-de-l'Hiver, au nord-ouest, un chasseur traque sa proie… Je parle d'Ursius, des ours Crocs acérés, une bête agile et rusée.\n\nJe vous envoie le combattre. Il erre sur les collines au nord-ouest de Long-guet. Trouvez-le et tuez-le avant qu'il ne s'aperçoive que vous êtes sur ses traces.\n\nTout ce qui s'est dressé contre Ursius est rapidement devenu la proie, et lui le chasseur. Restez sur vos gardes.", progress = nil, completion = "Ce n'était pas chose facile, pourtant vous avez excellé. Mais ne pensez pas trop vite que vous m'avez impressionné, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5055] = {title = "Brumeran des Noroît", objective = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Brumeran.", description = "Rapide et rusée, Brumeran parcourt silencieusement les terres enneigées du sud du Berceau-de-l'Hiver. Ne laissez pas sa beauté vous persuader qu'elle est inoffensive. Tous ceux qui ont croisé son chemin l'ont payé cher, parfois de leur vie.\n\nTrouvez Brumeran parmi les chimères Noroît. Tuez-la puis revenez me voir.", progress = nil, completion = "Oui. Vous êtes de retour. Je pense maintenant que vous avez une vraie nature de chasseur. Vous avez affronté les créatures les plus féroces et êtes de retour, surpassant mes espoirs.\n\nVous êtes maintenant prêt pour ma dernière requête.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5056] = {title = "Shy-Rotam", objective = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous triomphiez de Shy-Rotam.", description = "Au nord du Berceau-de-l'Hiver, de grands félins se rassemblent à un endroit appelé le roc des Sabres-de-Givre. Leur chef est connu sous le nom de Shy-Rotam. Vaincre la matriarche des sabres-de-givre vous apporterait le respect des autres <race>.\n\nRetournez dans les rudes terres sauvages et prenez de la viande sacrée sur les sabres-de-givre. Trouvez la pierre de Shy-Rotam et placez la viande dessus. En faisant cela, vous invoquez Shy-Rotam.\n\nPréparez-vous à affronter sa colère, et tuez-la.", progress = nil, completion = "Vous avez prouvé tant votre force que votre détermination. De nombreuses autres épreuves vous attendent, mais je vous ai déjà montré tout ce que je pouvais.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague du chasseur de bêteLame de bestiaire\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5057] = {title = "Essais passés", objective = "Apporter le Marqueur de Storm Shadowhoof à Melor Stonehoof à Thunder Bluff.", description = "Avant que vous ne me parliez, <nom>, j'avais eu vent de vos prouesses…que vous aviez un désir inextinguible de faire vos preuves, que vous étiez admirable, et je sais maintenant que ces choses sont vraies, <classe>.\n\nCeux qui excellent comme vous valent d'être reconnus. Apportez ce bon à l'un de mes amis à Thunder Bluff nommé Melor Stonehoof. Je suis sûr qu'il se souviendra de vous, et de ce que vous avez accompli il y a si longtemps. Parlez-lui de vos récentes victoires et n'oubliez jamais ce que vous avez accompli aujourd'hui.", progress = nil, completion = "Nous apprenons de nos expériences, &lt;nom&gt;. Vous n'avez pu que grandir en force et en sagesse grâce aux vôtres. Vous avez bien mûri depuis notre dernière entrevue.\n\nPrenez ceci en souvenir des tâches difficiles que vous avez accomplies en tant que &lt;classe&gt; &lt;race&gt;, et sachez que vous aurez toujours droit à mon respect et à mon admiration.", rewards = "Vous recevrez :\n\nMédaille des chasseurs"},
[5058] = {title = "Journal de Mme Dalson", objective = "Un journal aux pages jaunies est ouvert à sa dernière page :\n\n\"Je ne sais pas ce qui va se passer maintenant que Harold a changé. J'ai dû faire de gros efforts pour le mettre dans le seul endroit où je savais qu'il serait enfermé pour de bon. J'ai la clé sur moi, et je prie que ça marche...\n\nJ'espère pouvoir sortir d'ici, mais j'ai besoin d'argent pour ça... Nos affaires sont dans le cabinet, je pense... Et maintenant que j'y pense, Harold en a la clé sur lui ?\n\nJe vais me reposer, je suis morte de fatigue...\"", description = nil, progress = nil, completion = nil, rewards = nil},
[5059] = {title = "Enfermé", objective = "La porte des toilettes a commencé à se briser dans son pourtour comme si on avait essayé encore et encore de la forcer. Actuellement, elle est solidement verrouillée de l'extérieur.\n\nQuand vous secouez la porte, vous entendez un gémissement guttural ! La créature qui est à l'intérieur, quelle qu'elle soit, n'a pas l'air amicale.", description = nil, progress = "La porte des toilettes a commencé à se briser dans son pourtour comme si on avait essayé encore et encore de la forcer. Actuellement, elle est solidement verrouillée de l'extérieur.\n\nQuand vous secouez la porte, vous entendez un gémissement guttural ! La créature qui est à l'intérieur, quelle qu'elle soit, n'a pas l'air amicale.", completion = "En utilisant la clé trouvée sur le corps de feue Mme Dalson, vous ouvrez la porte des toilettes. Une goule assoiffée de sang en jaillit, enfermée ici on ne sait depuis combien de temps.\n\nLe hurlement à glacer le sang lancé par la goule ne laisse aucun doute, l'ancien fermier Dalson est au-delà de tout espoir de guérison.", rewards = nil},
[5060] = {title = "Enfermé", objective = "Un meuble très solide est en face de vous, hermétiquement clos par une serrure intégrée. Le devant du meuble est très rayé et abîmé. Cela pourrait venir de nombreuses et violentes tentatives pour percer les secrets que le meuble dissimule.\n\nSi vous voulez ouvrir ce meuble, il vous faudra trouver la clé.", description = nil, progress = "Un meuble très solide est en face de vous, hermétiquement clos par une serrure intégrée. Le devant du meuble est très rayé et abîmé. Cela pourrait venir de nombreuses et violentes tentatives pour percer les secrets que le meuble dissimule.\n\nSi vous voulez ouvrir ce meuble, il vous faudra trouver la clé.", completion = "La clé prise sur le cadavre de la goule du fermier Dalson glisse parfaitement dans la serrure. Les portes de la commode s'ouvrent, révélant plusieurs objets intacts et de grande valeur.", rewards = "Vous recevrez :\n\nFusil du fermier DalsonAlliance de la famille Dalson"},
[5061] = {title = "Forme aquatique", objective = "Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Bearwalker.", description = "Vous avez terminé l'apprentissage suivi par tous les jeunes druides qui veulent adopter un Aspect aquatique. Maintenant retournez voir votre maître, Mathrengyl Bearwalker, à Darnassus. Affichez votre pendentif et prouvez-lui que vous êtes apte à recueillir son savoir. Il achèvera votre formation, pour vous permettre de communiquer avec l’eau.\n\nAu revoir, jeune druide. Nous nous reparlerons.", progress = "Votre retour à Darnassus m'a été annoncé, cependant je vais avoir besoin d'une preuve comme quoi vous avez étudié à Reflet-de-Lune avant de pouvoir vous enseigner votre forme aquatique.\n\nAvez-vous le Pendentif du lion de mer ?", completion = "Très impressionnant, &lt;nom&gt;. Vous pouvez désormais acquérir votre forme aquatique, et cela sera un plaisir pour moi de vous l'enseigner.\n\nDe plus, pour récompenser votre performance lors des deux dernières épreuves, je vous donne cet objet. J'espère qu'il vous sera utile dans votre rôle de protecteur de la nature et de gardien de l'équilibre.", rewards = "Vous allez être la cible du sort suivant :\n\nForme aquatique\n\nVous recevrez :\n\nCeinture du Verseau"},
[5062] = {title = "Feu sacré", objective = "Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Grimtotem sur la Cime des Anciens dans Thunderbluff.", description = "Arikara est une créature implacable avec laquelle on doit agir avec prudence. Vous allez devoir allumer le feu sacré de la vie afin de la traquer. Cela aura pour effet d'invoquer Arikara.\n\nPartez dès à présent et récoltez le rare agave d'Incendia. Une fois que vous en aurez récolté suffisamment, cherchez conseil auprès de Magatha Grimtotem sur la Cime des Anciens à Thunder Bluff. C'est une chaman très puissante qui peut enchanter l'agave pour créer une poudre nécessaire à la combustion de la flamme.\n\nVoyagez au nord-est, jusqu'au Bassin bouillonnant et trouvez de l'Agave d'Incendia.", progress = "Ainsi, Motega Firemain envoie des nouvelles d'Arikara… et des nouvelles graves.\n\n<Magatha regarde alentour.>\n\nArikara est une créature maléfique qui n'existe que dans le but de se venger de ceux qui ont commis des actes de haine.\n\n<Magatha sourit.>", completion = "Bon, vous avez ramassé la quantité indispensable d'agave d'Incendia. Cette herbe rare que l'on trouve seulement aux Mille pointes nous aidera à rallumer le feu sacré de la vie.\n\n&lt;Magatha commence à enchanter l'agave d'Incendia.&gt;", rewards = "Vous recevrez :\n\n"},
[5063] = {title = "La coiffe du savant écarlate", objective = "Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.\n\nIl faudra aussi payer 50 pièces d’or pour le travail de fabrication.", description = "Vous ne verrez jamais plus belle coiffe. Nos artisans experts créeront, à partir de la peau parfaite de la bête, le chapeau le plus phénoménal qu'un prestidigitateur pourrait jamais rêver de faire !\n\nIl suffit de cinquante pièces d'or et des objets sur la liste et votre tête aura les honneurs de la Coiffe du savant écarlate :\n\n*La peau de la Bête en parfait état.\n\n*Des Coutures d'Abomination effilochées.\n\n*Des Cristaux des arcanes.\n\nDu Fil écarlate enchanté.\n\nVOILÀ !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCoiffe du savant écarlate"},
[5064] = {title = "Espionner le Totem sinistre", objective = "Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage.", description = "<nom>, vous nous avez bien servi par le passé, je peux donc vous confier une importante mission. Le Clan du Totem sinistre prépare quelque chose en secret. Trois agents d'origine inconnue ont été vus chez eux ces dernières semaines. Nous avons découvert que ces messages sont conservés dans plusieurs coffres de la cime de Noir-nuage. \n\n<nom>, si vous réussissez cette dangereuse mission, je vous récompenserai.", progress = "Avez-vous découvert ce que trame le clan du Totem sinistre ?", completion = "Par les grands totems ! C'est une affreuse nouvelle en effet. Je dois me préparer à toute éventualité.\n\n&lt;nom&gt;, comme promis, voici la récompense pour votre courageux service.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpaulières du désertBottes de la toundraGarde-poignets de dur-labeur\n\nVous recevrez également :\n\n"},
[5065] = {title = "Les tablettes perdues de Mosh'aru", objective = "Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris.", description = "Le troll avec qui vous venez de parler vous a menti. Les deux tablettes que vous lui avez ramenées contiendraient l'essence d'Hakkar, une légende qui a plus d'un tenant. J'ai fait beaucoup de recherches et j'ai découvert qu'il y a six Tablettes de Mosh'aru et pas seulement deux ! Six !\n\nEt j'ai peur que les secrets que contiennent les autres ne soient pas réjouissants.\n\nTrouvez les troisième et quatrième tablettes de Mosh'aru. Elles sont dans les Maleterres de l'est, entre les mains des trolls Mossflayer. Trouvez-les et ramenez-les-moi.", progress = "Avez-vous les tablettes ? Je crains que leurs textes ne révèlent une lourde menace pour notre monde.", completion = "Vous les avez trouvés ! Fantastique !\n\nMerci, &lt;nom&gt;. Je vais me pencher sur ces textes et déchiffrer leur signification.\n\nVous avez, vous, une autre tâche…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5066] = {title = "Un appel aux armes : les Maleterres", objective = "Trouver le commandant Ashlam Valorfist. Son camp de base est situé au camp du Noroît, au nord des montagnes d'Alterac.", description = "Oyez ! Oyez ! Héros, écoutez bien ce message !\n\nLe royaume de Stormwind appelle à prendre les armes ! Tous les individus en état de se battre sont sommés de prendre les armes contre les armées du Fléau dans les terres du nord des Royaumes de l'est ! La menace viendrait des ruines des Maleterres !\n\nHéros du royaume, allez trouver le commandant Ashlam Valorfist qui a établi son campement au camp du Noroît, au nord des Montagnes d'Alterac !", progress = nil, completion = "Bienvenue dans les Maleterres, héros. C'est l'une des frontières les plus dangereuses d'Azeroth, particulièrement avec la menace rampante du Fléau, au nord et nord-est. Quel bonheur de voir que l'appel du devoir et le service du bien ne sont pas tombés dans les oreilles d'un sourd en ce qui vous concerne !\n\nSi vous voulez mettre la main à la pâte, alors il y a aux confins des Maleterres de quoi faire pour de nombreux héros volontaires et capables.", rewards = "Vous recevrez :\n\n"},
[5067] = {title = "Jambières d'Arcana", objective = "Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Fluides d'embaumement de Murmegivre.\n\nIl faudra également payer 50 pièces d’or pour le travail de fabrication.", description = "Bien que la réalisation d'un tel objet n'ait jamais été accomplie, il semble que cela soit possible, sous certaines conditions.\n\nLe chercheur d'arcanum qui désire attribuer d'immenses pouvoirs à des jambières doit trouver les objets suivants :\n\n*La peau de la Bête en parfait état.\n\n*Couture d'Abomination effilochée.\n\n*Barres d'arcanite.\n\n*Fluide d'embaumement de Murmegivre.\n\nEt voilà !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières d'Arcana"},
[5068] = {title = "La cuirasse carnassière", objective = "Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres.\n\nIl faudra également payer 50 pièces d’or pour le travail de fabrication.", description = "Il paraît qu'un seul exemplaire de la cuirasse carnassière a été créé et qu'elle fut confectionnée pour le légendaire assassin Garona. Il est peu probable qu'on en voit jamais une autre en ce monde.\n\nMais peu importe ! Nos maîtres fabricants peuvent reproduire l'objet s'ils disposent des composants requis :\n\n*La peau de la Bête en parfait état.\n\n*Couture d'Abomination effilochée.\n\n*Barres d'arcanite.\n\n*Peau des ombres.\n\n*Admirez !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuirasse carnassière"},
[5081] = {title = "Mission de Maxwell", objective = "Se rendre au Pic Blackrock et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie.", description = "Cette information complète ce que nous savons déjà du pic Blackrock.\n\nL'attaque doit être décisive, <nom>.\n\nTout d'abord, leur maître de guerre, le troll Voone, doit être anéanti. Sans ses plans de bataille, le chaos règnera dans les rangs des orcs Blackrock.\n\nVous devez ensuite éliminer le généralissime ogre Omokk. Les ogres de Blackrock deviennent lâches sans leur chef.\n\nEnfin, le Seigneur de la citadelle, Wyrmthalak ! Une fois Wyrmthalak mort, leur unité centrale de commandement n'a plus de leader.", progress = nil, completion = "Excellent travail, &lt;nom&gt; ! Au minimum, vous nous avez gagné du temps supplémentaire - un temps très, très précieux.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMenottes de WyrmthalakCorset d'OmokkMuselière d'HalyconBande de Vosh'gajinPoignes de fer de Voone\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5082] = {title = "La menace des Tombe-hiver", objective = "Donova Snowden du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver.", description = "Je suis venue au Berceau-de-l'Hiver pour étudier les sources chaudes de Givrefeu. J'ai remarqué que l'eau semble avoir des propriétés étranges. Je n'ai pas encore pu découvrir la source, et pour vous dire la vérité, j'ai eu du fil à retordre à cause des furbolgs Tombe-hiver.\n\nIls semblent attirés par les sources, tout comme moi. Ils protègent les abords de l'eau et ne me laissent pas approcher des deux plus grosses sources au nord d'ici.\n\nJ'aimerais continuer mes observations. Vous voulez bien m'aider ?", progress = "J'apprécie votre aide !", completion = "Grand merci, &lt;nom&gt; ! Je peux me remettre enfin au travail.\n\nAvez-vous trouvé quelque chose d'intéressant au camp des Tombe-hiver ?", rewards = "Vous recevrez :\n\n"},
[5083] = {title = "L'eau de feu de Tombe-hiver", objective = "Apporter le Flacon d'eau de feu vide à Donova Snowden du Berceau-de-l'Hiver.", description = "La fiole que vous avez ramassée près du furbolg Tombe-hiver est vide. Il reste cependant quelques gouttes d'un étrange liquide vert, presque lumineux.\n\nEst-ce quelque chose d'important ? Donova Snowden serait certainement capable de vous en dire plus puisqu'elle campe à côté des sources chaudes du Berceau-de-l'Hiver depuis quelque temps maintenant.", progress = "Qu'avez-vous trouvé ?", completion = "Cela vient des Tombe-hiver ?", rewards = "Vous recevrez :\n\n"},
[5084] = {title = "Corrompu", objective = "Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois.", description = "Ce liquide verdâtre… cela me rappelle cette boue que j'ai vue lorsque je traversais Gangrebois. Et j'ai vu quelques messagers Tombe-hiver traverser le territoire des Grumegueules… Tout cela a peut-être un rapport avec la bouteille que vous avez trouvée, <nom>.\n\nIl y a un groupe important de furbolgs juste après le repaire des Grumegueules, à Gangrebois. Appelés les Mort-bois, la corruption les a rendus fous. Pourquoi ne pas chercher dans le coin des preuves qui montreraient les relations entre les Tombe-hiver et les Mort-bois ?", progress = nil, completion = "Dans le chaudron bouillonne une substance putrescente à l'odeur insoutenable...", rewards = "Vous recevrez :\n\n"},
[5085] = {title = "Gelée mystère", objective = "Aller faire un rapport de vos trouvailles à Donova Snowden.", description = "La substance verdâtre dans le chaudron semble être similaire à ce que vous avez trouvé dans la fiole. Cette étrange matière gluante pourrait être aussi malsaine que le furbolg qui l'a créée…\n\nSi les furbolg Tombe-hiver l'utilisent, cela signifie-t-il qu'ils vont bientôt être aussi corrompus que la tribu Mort-bois ?\n\nIl serait mieux de faire votre rapport à Donova et de ramener un échantillon du liquide trouvé dans le chaudron.", progress = "J'espère que vous avez trouvé quelque chose, <nom>. Les Tombe-hiver deviennent de plus en plus aggressifs.", completion = "Vous êtes plein de ressources, &lt;nom&gt;.Pensez-vous que les furbolgs Tombe-hiver sont allés au camp des Mort-bois ?", rewards = "Vous recevrez :\n\n"},
[5086] = {title = "Horreurs toxiques", objective = "Récolter 3 Gouttelettes d'Horreur toxique pour Donova Snowden au Berceau-de-l'Hiver.", description = "J'ai étudié l'échantillon que vous avez ramené, et je n'en suis pas sûr mais je pense qu'il y a des traces d'éléments toxiques. Cependant, la seule façon d'en être certain est d'avoir des éléments de comparaison.\n\nJ'ai l'impression que les furbolgs Mort-bois sont en train de rassembler ces éléments à partir d'autres créatures corrompues à Gangrebois. En particulier, je pense aux élémentaires vivant dans le bois d'Arbrefer, appelés Horreurs toxiques.\n\nPrélevez quelques échantillons pour moi mais attention à vous !", progress = "Je crois que nous commençons à découvrir ce qu'il se passe ici, <nom>.", completion = "Il faut que je compare ceci à la substance que vous avez trouvée dans le chaudron, nous en saurons plus alors.", rewards = "Vous recevrez :\n\n"},
[5087] = {title = "Les messagers des Tombe-hiver", objective = "Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver.", description = "Très intéressant, <nom>… \n\nLorsque cette substance toxique est mélangée à l'eau des sources chaudes, elle perd sa toxicité, mais reste dangereuse temporairement pour ceux qui l'ingèrent. Voilà donc pourquoi les Tombe-hiver protègent les sources chaudes aussi ardemment : ils en ont besoin pour purifier leur eau de feu.\n\nNous devons arrêter ça. Coupez le contact entre les Tombe-hiver et les Noir-bois. Un groupe de messagers fait le chemin entre leur village et Gangrebois. Trouvez-les et éliminez-les en vous appropriant ce qu'ils transportaient.", progress = "Nous verrons ce qui arrive quand les Tombe-hiver sont privés d'eau de feu !", completion = "&lt;Donova examine le contenu de la caisse&gt;\n\nJe me demande si le fait de consommer cette substance ne rend pas les furbolgs plus agressif. Ils paraissent vraiment plus gros…", rewards = "Vous recevrez :\n\n"},
[5088] = {title = "Arikara", objective = "Tuer Arikara. Rapporter sa dépouille et de la poudre d’incendia à Motega Firemane au Poste de Blanc-relais comme preuve de votre acte.", description = "Apportez cette Poudre d'incendia raffinée et purifiée aux Mille pointes et versez-la sur le feu sacré de la vie. Il se trouve sur la Cime de Noir-nuage, sur une pointe isolée où ils enterrent leurs morts.\n\nL'enchantement que j'ai joint dans la Poudre d'incendia invoquera Arikara, <nom>.\n\nJe crains qu'elle ne traque Cairne Bloodhoof ; trop des coutumes tauren ont changé et j'ai bien peur que cela n'ait mis Arikara en colère. Agissez rapidement avant que tout ne soit perdu, <classe> !", progress = "Avez-vous tué ce serpent vicieux d'Arikara, <nom> ?", completion = "Cela n'a aucun sens. Pourquoi Arikara serait-il à la poursuite de Cairne Bloodhoof ? Magatha ne peut se tromper, c’est la plus puissante de nos chamans.\n\n&lt;Motega secoue la tête&gt;\n\nQuoi qu'il en soit, votre action en faveur de la Horde ne sera pas oubliée. S'il vous plaît, choisissez votre récompense parmi ces objets.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarteau brutalBaguette du dardBouclier résonnant\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5089] = {title = "Ordres du général Drakkisath", objective = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes.", description = "Vous découvrez sur le corps du serpent vaincu ce qui se révèle une note de quelque importance : une lettre de son supérieur, le général Drakkisath, à propos du protocole.\n\nVotre instinct vous conseille de l'apporter au maréchal Maxwell.", progress = "Qu'avez-vous là, <nom> ?", completion = "Le mystère s'épaissit…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5090] = {title = "Un appel aux armes : les Maleterres", objective = "Trouver le commandant Ashlam Valorfist. Son camp de base est le Camp du Noroît, au nord des montagnes d'Alterac.", description = "Oyez ! Oyez ! Héros, écoutez bien ce message !\n\nLe royaume de Stormwind appelle à prendre les armes ! Tous les individus en état de se battre sont sommés de prendre les armes contre les armées du Fléau dans les terres du nord des Royaumes de l'est ! La menace viendrait des ruines des Maleterres !\n\nHéros du royaume, allez trouver le commandant Ashlam Valorfist qui s'est établi au Camp du Noroît, au nord des Montagnes d'Alterac !", progress = nil, completion = "Bienvenue dans les Maleterres, héros. C'est l'une des frontières les plus dangereuses d'Azeroth, particulièrement avec la menace rampante du Fléau, au nord et nord-est. Quel bonheur de voir que l'appel du devoir et le service du bien ne sont pas tombés dans les oreilles d'un sourd en ce qui vous concerne !\n\nSi vous voulez mettre la main à la pâte, alors il y a aux confins des Maleterres de quoi faire pour de nombreux héros volontaires et capables.", rewards = "Vous recevrez :\n\n"},
[5091] = {title = "Un appel aux armes : les Maleterres", objective = "Trouver le commandant Ashlam Valorfist. Il s'est établi au Camp du Noroît, au nord des montagnes d'Alterac.", description = "Oyez ! Oyez ! Héros, écoutez bien ce message !\n\nLe royaume de Stormwind appelle à prendre les armes ! Tous les individus en état de se battre sont sommés de prendre les armes contre les armées du Fléau dans les terres du nord des Royaumes de l'est ! La menace viendrait des ruines des Maleterres !\n\nHéros du royaume, allez trouver le commandant Ashlam Valorfist qui s'est établi au camp du Noroît, au nord des Montagnes d'Alterac !", progress = nil, completion = "Bienvenue dans les Maleterres, héros. C'est l'une des frontières les plus dangereuses d'Azeroth, particulièrement avec la menace rampante du Fléau, au nord et nord-est. Quel bonheur de voir que l'appel du devoir et le service du bien ne sont pas tombés dans les oreilles d'un sourd en ce qui vous concerne !\n\nSi vous voulez mettre la main à la pâte, alors il y a aux confins des Maleterres de quoi faire pour de nombreux héros volontaires et capables.", rewards = "Vous recevrez :\n\n"},
[5092] = {title = "Nettoyer le passage", objective = "Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins.\n\nRetourner auprès du commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.", description = "Les routes ouest et nord d'Andorhal étant bien surveillées, je cherche un accès par l'est moins bien défendu afin d'attaquer la ville. Le Fléau s'appuie sur les morts-vivants qui infestent la Colline des Chagrins pour former la première ligne de défense. Si nous devons avancer sur Andorhal, il faut franchir cette colline.\n\nVotre première mission sera de sécuriser la route de la Colline des chagrins. Eliminez les squelettes et les goules qui hantent la zone et venez me faire votre rapport lorsque vous avez fini !", progress = nil, completion = "Mission accomplie, &lt;nom&gt; ! Bien joué, bien joué.\n\nPermettez-moi de récompenser votre travail par quelques pièces des coffres de Stormwind. Je vous recommande de le dépenser en prévision de votre prochaine mission… qui vous conduira aux ruines d'Andorhal elles-mêmes.\n\nSoyez prêt ! Soyez vigilant !", rewards = "Vous recevrez :\n\n"},
[5093] = {title = "Un appel aux armes : les Maleterres", objective = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity.", description = "Héros du royaume, écoutez-moi ! La Horde vous somme d'agir vite !\n\nLe royaume appelle tous les individus valides à prendre les armes contre le Fléau ! Des rumeurs annoncent de nouvelles menaces venant des ruines des royaumes de l'est. L'ennemi serait à l'est d'Undercity, dans les marches septentrionales de la région maintenant appeléee les Maleterres !\n\nHéros du royaume, cherchez le Grand exécuteur Derrington, qui a installé son camp de base à la Barricade, à l'est des Clairières de Tirisfal !", progress = nil, completion = "Bienvenue aux Maleterres, héros. C'est la plus dangereuse des frontières d'Azeroth, avec l'ombre menaçante du Fléau à l'est, et plus à l'est encore. Je suis heureux de constater que l'appel au sens du devoir de la Horde n'a pas trouvé sourde oreille en vous !\n\nSi vous êtes prêts à vous salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.", rewards = "Vous recevrez :\n\n"},
[5094] = {title = "Un appel aux armes : les Maleterres", objective = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity.", description = "Héros du royaume, écoutez-moi ! La Horde vous somme d'agir vite !\n\nLe royaume appelle tous les individus valides à prendre les armes contre le Fléau ! Des rumeurs annoncent de nouvelles menaces venant des ruines des royaumes de l'est. L'ennemi serait à l'est d'Undercity, dans les marches septentrionales de la région maintenant appeléee les Maleterres !\n\nHéros du royaume, cherchez le Grand exécuteur Derrington, qui a installé son camp de base à la Barricade, à l'est des Clairières de Tirisfal !", progress = nil, completion = "Bienvenue aux Maleterres, héros. C'est la plus dangereuse des frontières d'Azeroth, avec l'ombre menaçante du Fléau à l'est, et plus à l'est encore. Je suis heureux de constater que l'appel au sens du devoir de la Horde n'a pas trouvé sourde oreille en vous !\n\nSi on est prêt à se salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.", rewards = "Vous recevrez :\n\n"},
[5095] = {title = "Un appel aux armes : les Maleterres", objective = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity.", description = "Héros du royaume, écoutez-moi ! La Horde vous somme d'agir vite !\n\nLe royaume appelle tous les individus valides à prendre les armes contre le Fléau ! Des rumeurs annoncent de nouvelles menaces venant des ruines des royaumes de l'est. L'ennemi serait à l'est d'Undercity, dans les marches septentrionales de la région maintenant appeléee les Maleterres !\n\nHéros du royaume, cherchez le Grand exécuteur Derrington, qui a installé son camp de base à la Barricade, à l'est des Clairières de Tirisfal !", progress = nil, completion = "Bienvenue aux Maleterres, héros. C'est la plus dangereuse des frontières d'Azeroth, avec l'ombre menaçante du Fléau à l'est, et plus à l'est encore. Je suis heureux de constater que l'appel au sens du devoir de la Horde n'a pas trouvé sourde oreille en vous !\n\nSi vous êtes prêt à vous salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.", rewards = "Vous recevrez :\n\n"},
[5096] = {title = "Diversions écarlates", objective = "Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major.\n\nPlacer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.", description = "Avant Andorhal, nous devons faire face à la menace de la Croisade écarlate venant de Hearthglen. Ils ont établi leur camp entre le Champ de Felstone et les Larmes de Dalson. Nous risquons maintenant d'entrer en conflit avec le Fléau et la Croisade en même temps.\n\nMon plan est de les monter l'un contre l'autre en vous envoyant détruire leur tente de commandement. Utilisez quelques Flammes en bouteille disposées dans cette boîte. Une fois détruite, plantez cette bannière du Fléau à côté. Avec un peu de chance, ils nous ignoreront et concentreront leur vengeance sur le Fléau.", progress = "Une attaque surprise sur la modeste position avancée de la Croisade écarlate nous donnera le laps de temps nécessaire pour marcher sur Andorhal. Je crois vraiment que le succès nous y attend !\n\nUne fois ceci accompli, il nous faudra travailler avec diligence et rapidité. Nous n'avons ni l'équipement ni les troupes pour combattre de front le Fléau et la Croisade écarlate s'ils ne tombent pas dans notre petit piège.", completion = "Finement joué, &lt;nom&gt;. Votre attaque contre la Croisade écarlate nous fait gagner du temps. J'ai envoyé un de mes meilleurs éclaireurs pour surveiller leur camps afin d'être sûr que leurs renforts mordront à l'hameçon.\n\nAvec une pression moindre, nous pouvons nous risquer sur une mission à Andorhal elle-même, et non des moindres. Je serai ravi que vous vous en chargiez, au vu de vos récents exploits.", rewards = "Vous recevrez :\n\n"},
[5097] = {title = "Tout au long des tours de guet", objective = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.\n\nQuand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.", description = "En utilisant l'objet magique connu sous le nom de torche-balise, nous pouvons marquer les cibles sur lesquelles interviendront nos troupes. À cette fin, nous pensons que le Fléau utilise les tours de guet d'Andorhal pour diriger les mouvements de leurs troupes.\n\nVotre mission : déjouer les défenses d'Andorhal pour poser des balises sur les quatre tours de guet. Vous devez être sur le pas de la porte pour poser la balise, ce qui assurera le marquage de la tour. Attention, la torche-balise ne contient que cinq charges. Utilisez-les à bon escient !", progress = "Une fois les tours repérées, elles deviendront nos cibles prioritaires dans l'attaque d'Andorhal. Je suppose que lorsque nous aurons neutralisé les tours, la menace principale d'Andorhal émergera. À ce moment, nous déclencherons une attaque directe pour contrôler la cité !\n\nVous revenez victorieux, n'est-ce pas ? N'oubliez pas la torche-balise : il faut maintenir notre matériel sous contrôle.", completion = "Mes prêtres m'informent que nos traqueurs de balises détectent des signaux très forts sur les quatre tours ! J'ose à peine le dire, mais je crois que vous avez effectué une nouvelle mission avec un succès complet et total ! Bien joué à nouveau, &lt;nom&gt; !\n\nUne fois les tours marquées, nos préparatifs pour l'attaque sont désormais en place. Le temps est venu d'engager le combat contre le Fléau !", rewards = "Vous recevrez :\n\n"},
[5098] = {title = "Tout au long des tours de guet", objective = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.\n\nQuand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.", description = "En utilisant l'objet magique connu sous le nom de torche-balise, nous pouvons marquer les cibles sur lesquelles interviendront nos troupes. À cette fin, nous pensons que le Fléau utilise les tours de guet d'Andorhal pour diriger les mouvements de leurs troupes.\n\nVotre mission : déjouer les défenses d'Andorhal pour poser des balises sur les quatre tours de guet. Vous devez être sur le pas de la porte pour poser la balise, ce qui assurera le marquage de la tour. Attention, la torche-balise ne contient que cinq charges. Utilisez-les à bon escient !", progress = nil, completion = "Mes démonistes m'informent que nos traqueurs de balises détectent des signaux très forts sur les quatre tours ! Vous avez exécuté mes ordres avec l'habileté et la précision d'un vétéran aguerri. Vos services sous la bannière de la Horde sont remarqués une fois encore, &lt;nom&gt; !\n\nUne fois les tours marquées, nos préparatifs pour l'attaque sont désormais en place. Le temps est venu d'engager le combat contre le Fléau !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5101] = {title = "Lee's Ultimate Test Quest... of Doom!", objective = "Kill 6 sheep for Benny and then run like hell!\n\n\n\n\nJust kidding... about the running part.", description = "Bah! What do think this is, some kind of Test Quest? I be there even be typos in it!\n\nIf ya be thinkin' my quest is goin' ta be easy, then ya got another thing coming!\n\nKill me ten sheep (1933) and don't come back until you do!Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nEpée longue des chevaliers"},
[5102] = {title = "La reddition du général Drakkisath", objective = "Rendez-vous au Pic Blackrock et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell.", description = "Nous nous battons contre ces créatures sur deux fronts : de notre capitale, Stormwind, nous les pourchassons et sur les Steppes ardentes, nous frappons sur leur territoire. Nous devons rester vigilants, <nom>. Aucun d'eux ne sera épargné, tout comme ils furent sans pitié à l'égard de nos familles.\n\nTrouvez ce général Drakkisath et tuez-le !\n\nCette tâche n'a rien de facile mais la récompense sera à la hauteur.", progress = nil, completion = "A coup sûr, notre prochaine cible sera leurs seigneurs-dragons. Bravo, brave soldat de l'Alliance ! Bien joué, vraiment.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarque de tyrannieOeil de la BêtePlaque de Blackhand\n\nVous recevrez également :\n\n"},
[5103] = {title = "Mort brûlante", objective = "Quelqu’un dans ce monde doit bien savoir à quoi servent ces gantelets. Bonne chance !", description = "La seule chose qu'il reste de cet humain est un tas d'os carbonisés. Il semble être mort près de ce qu'il voulait saisir : des gantelets en plaques inachevés.\n\nVous devriez peut-être attraper les gantelets et sortir du feu ?", progress = nil, completion = "Que…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5121] = {title = "Le grand chef Tombe-hiver", objective = "Donova Snowden du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver.", description = "Bien que nous ne sachions pas vraiment pourquoi les furbolgs ont ingéré cette étrange substance, je pense qu'il vaudrait mieux y mettre un terme avant que ça ne dégénère.\n\nLes furbolgs Tombe-hiver ne sont en général pas agressifs et ce changement de comportement me laisse à penser qu'ils suivent les ordres de leur chef. Nous ne pouvons pas revenir sur le mal qui a été fait mais je pense que si leur chef est anéanti, la situation ne peut empirer.\n\nAllez vers l'est au village des Tombe-hiver.", progress = nil, completion = "Merci beaucoup, &lt;nom&gt;. J'espère revenir à mes chères études sans souci d'être prise en embuscade. Acceptez ceci comme récompense, je vous prie.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMantelet de la brise cristallinePourpoint de veine-fougèreHaubert du saule\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5122] = {title = "Le médaillon de foi", objective = "Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.\n\nS'il vous plaît, <nom>, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme.", description = nil, progress = "Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.\n\nS'il vous plaît, <nom>, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme.", completion = "Vous avez retrouvé le médaillon ! Je vais enfin pouvoir quitter la chapelle et faire mon devoir.\n\nMon devoir est de tuer la bête qui a participé à ma corruption, moi et tant d'autres de mes frères et sœurs, le baron Rivendare !", rewards = nil},
[5123] = {title = "Le dernier morceau", objective = "Apporter le Journal mal écrit à Donova Snowden au Berceau-de-l'Hiver.", description = "Le journal que vous avez trouvé sur le grand chef paraît fourni, mais après avoir feuilleté quelques pages, vous vous rendez compte que vous ne pouvez pas lire le texte. Les signes sont si rudimentaires et informes que vous n'êtes même pas sûr que quelqu'un pourra les lire.\n\nDonova pourra peut-être vous en dire plus...", progress = "Et alors, qu'est-ce que c'est, <nom> ?", completion = "Je me demande ce que tout cela veut dire… je n'y comprends rien…", rewards = "Vous recevrez :\n\n"},
[5124] = {title = "Gantelets en plaque de feu", objective = "Apporter à Malyfous Darkhammer 6 Barres de thorium enchanté, 2 Essences de feu, et 4 Rubis stellaires. Lui remettre également vos Gantelets en plaques inachevés.", description = "Par la barbe de Thaurissan !\n\nOù les avez-vous trouvés ?\n\nEt plus important encore, voudriez-vous vous en séparer ? Naturellement, je paierais pour un geste si noble.\n\nJe vais vous dire, <nom>… si vous me donnez ces Gantelets inachevés, je vous enseignerai comment en faire par vous-même. Tout ce dont vous avez besoin est de me trouver les parties nécessaires afin que je puisse trouver par élimination la recette exacte.\n\nSommes-nous d'accord ??\n\nVoici la liste des choses dont j'ai besoin. Je préparerai moi-même le thorium non enchanté puisque vous fournissez les Gantelets.", progress = "Le temps, c'est de l'argent, <nom>, et j'ai très peu de l'un comme de l'autre.", completion = "Comme promis, &lt;nom&gt;, voici votre recette ! Je vais aussi rajouter un petit quelque chose pour votre rude travail et votre dévouement. Que pourrais-je en faire, de toute façon ???", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Gantelets en plaques de feuGantelets en plaques de feu"},
[5125] = {title = "L'estimation d'Aurius", objective = "<nom>, je me meurs… mais mon âme est sauve, et pour cela je vous dois plus que les mots peuvent exprimer. Je vous en prie, prenez ceci… et continuez le combat, brave <classe> !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nVolonté du MartyrSang du Martyr\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5126] = {title = "L'histoire de Lorax", objective = "Parler à Lorax. Écouter ce qu’il a à dire.", description = "Le satyre fait les cent pas et parle tout seul. Voulez-vous le questionner ?", progress = nil, completion = "&lt;Lorax rit.&gt;", rewards = "Vous recevrez :\n\n"},
[5127] = {title = "La forge démoniaque", objective = "Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.\n\nTrouver aussi la Cuirasse couverte de runes inachevée.\n\nRapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver.", description = "Lorax conclut des accords, il ne les accepte pas de <mortels insignifiants/mortelles insignifiantes>.\n\nMais je vais tout de même conclure un accord avec vous… Prenez cette pique, elle est imprégnée de puissantes énergies corrompues. Lorsque vous trouverez Goraluk Anvilcrack, tuez-le et transpercez son coeur agonisant avec cette pique. Il a marchandé son âme, et c'est son âme que j'aurai. Rapportez-moi la pique et la cuirasse que ce voleur m'a dérobé et je vous enseignerai ce qu'il était supposé apprendre.", progress = "Ne tentez pas…", completion = "Notre pacte, vous n'avez pas brisé. L'âme, je l'ai prise. La récompense, je la donnerai.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Cuirasse démoniaqueElixir de Tueur de démonsSac embrassé par un démon"},
[5128] = {title = "Paroles du Grand Chef", objective = "Rapporter le Journal mal écrit à Kelek Skykeeper dans le sud de Gangrebois.", description = "Les Tombe-hiver ne représentent plus le moindre danger pour moi, mais si vous désirez toujours découvrir ce qui a poussé les furbolgs à créer et a utiliser cette étrange eau de feu, je pense que vous devriez rechercher Kelek Skykeeper.\n\nIl fait partie d'un groupe connu sous le nom du Cercle d'émeraude. Il s'agit de druides dévoués à leur travail dans Gangrebois et guérissant la terre de la corruption.\n\nKelek a beaucoup d'expérience avec les furbolgs de Gangrebois, et il se peut qu'il puisse vous en apprendre davantage à propos du journal.\n\nJe vous remercie encore, <nom>.", progress = "Le Cercle d'émeraude est bénéfique pour tous, <nom>. Que puis-je faire pour vous ?", completion = "Oui, si vous me laissez examiner ceci un moment, je pourrais être en mesure de vous le traduire.\n\n&lt;Kelek feuillette les pages.&gt;\n\nQuand je l'aurai étudié en entier, je vous en informerai.\n\nMerci de partager ceci avec moi, &lt;nom&gt;. On ne sait pas grand-chose des furbolgs Tombe-hiver.", rewards = "Vous recevrez :\n\n"},
[5141] = {title = "Travail du cuir de dragon", objective = "Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Peter Galen, à Azshara.\n\nTerminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.\n\nTerminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.", description = "Le travail des écailles de dragons n'est pas chose aisée, mais les récompenses qu'on en retire sont nombreuses. Je vous enseignerai comment fabriquer cette belle cotte de mailles, mais cela seulement si vous acceptez certaines conditions.\n\nTout d'abord, en choisissant cette voie, vous vous engagez à ne jamais apprendre le travail du cuir élémentaire ou le travail du cuir tribal. Vous ne pouvez parvenir à l'excellence que dans un seul domaine. De plus, j'aurai besoin d'échantillons de vos meilleurs ouvrages d'armure de scorpide. Enfin, vous devez me prouver votre capacité à acquérir la matière première de cet art : des écailles de draconiens.", progress = "Si vous êtes prêt à prendre la décision définitive de devenir un Artisan du cuir d'écaille de dragon, je peux vous prendre comme apprenti. Apportez-moi juste les choses que je vous ai demandées, et je commencerai votre éducation.", completion = "Je vous le dis - il faut une volonté forte pour prendre une décision irréversible comme vous venez de le faire. Je vous assure, le travail du cuir d'écaille de dragon sera pour vous une voie profitable.\n\nPour apprendre cet art dans le futur, parlez-moi simplement et je vous dispenserai toutes les connaissances qu'il vous faut encore acquérir.", rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir d'écailles de dragon\n\nVous recevrez :\n\n"},
[5142] = {title = "La petite Pamela", objective = "Retrouver Pamela Redpath.", description = "Tellement d'entre nous sont morts à la bataille de Darrowshire. Tellement sont morts… et même pire encore.\n\nLorsque la bataille a commencé j'ai caché ma nièce Pamela et je ne sais pas ce qu'il est advenu d'elle. Je ne suis qu'un esprit errant, mais mon coeur désire toujours connaître le sort de Pamela.\n\nJe vous en prie, noble <classe>. Pourriez-vous partir pour Darrowshire et la rechercher ? C'est à l'est, derrière la Flétrissure de Gahrron.", progress = nil, completion = "Bonjour. Je m'appelle Pamela, et vous ?", rewards = "Vous recevrez :\n\n"},
[5143] = {title = "Travail du cuir tribal", objective = "Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Caryssia Moonhunter en Feralas.\n\nL’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Apprendre le travail du cuir tribal nécessite une réelle compréhension de ce qu'est la véritable nature primale. Je sais que vous maîtrisez déjà l'art de la confection d'armures en cuir sauvage, et je souhaite poursuivre votre entraînement.\n\nSachez ceci, <classe> : en choisissant de suivre cette voie, vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir élémentaire. Vous ne pouvez vraiment maîtriser qu'une seule des trois disciplines. De plus, apportez-moi les meilleurs exemplaires de vos armures en cuir sauvage. À partir de là, nous pourrons poursuivre votre apprentissage.", progress = "La nature est une force qu'il faut apaiser avant d'espérer apprendre comment modeler sa volonté pour la faire entrer dans vos habits de cuir. Apportez-moi une offrande pour cette force, et je ferai en sorte qu'on vous entende.", completion = "Vous avez donné vos meilleures offrandes, et la nature se pliera bientôt à votre volonté. Lorsque vous quitterez ma tutelle, votre travail sera lui-même une force de la nature.\n\nPour apprendre cet art à l'avenir, il vous suffit de venir me parler. Je vous dispenserai toutes les connaissances qu'il vous faut encore acquérir.", rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir tribal\n\nVous recevrez :\n\n"},
[5144] = {title = "Travail du cuir élémentaire", objective = "Apporter 2 Coeurs de feu, 2 Globes d’eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.\n\nL’accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Le travail du cuir élémentaire est mon domaine, et si vous voulez ouvrir votre esprit aux plus grands pouvoirs de l'art, je partagerai avec vous tout ce qu'il y a à savoir.\n\nSachez ceci, <classe> : en prenant cette voie vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir tribal. Vous ne pouvez atteindre l'excellence que dans un seul de ces trois domaines. De plus, j'aurai besoin de la preuve que vous êtes en relation avec les éléments de la nature. Pour ce faire, apportez-moi les essences les plus pures de feu, d'eau, de terre et de vent.", progress = "La confection de ce genre d'armure de cuir requiert de la patience et de l'engagement. Une fois que vous avez décidé de partager la destinée des élémentaires, il n'y a pas un moyen de revenir en arrière et de leur tourner le dos. Montrez-moi que vous êtes digne de notre cause, et commençons sans tarder.", completion = "Vous avez choisi votre lot, et les éléments vous acceptent. Lorsque vous quitterez ma tutelle, vous aurez le pouvoir de fabriquer les costumes de cuir les plus raffinés.\n\nPour apprendre cet art dans le futur, parlez-moi simplement et je vous dispenserai toutes les connaissances qu'il vous faut encore acquérir.", rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir élémentaire\n\nVous recevrez :\n\n"},
[5145] = {title = "Travail du cuir de dragon", objective = "Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Dragoneye, dans les Terres ingrates.\n\nTerminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.\n\nTerminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.", description = "Le travail des écailles de dragons n'est pas chose aisée, mais les récompenses qu'on en retire sont nombreuses. Je vous enseignerai comment fabriquer cette belle cotte de mailles, mais cela seulement si vous acceptez certaines conditions.\n\nTout d'abord, en choisissant cette voie, vous vous engagez à ne jamais apprendre le travail du cuir élémentaire ou le travail du cuir tribal. Vous ne pouvez parvenir à l'excellence que dans un seul domaine. De plus, j'aurai besoin d'échantillons de vos meilleurs ouvrages d'armure de scorpide. Enfin, vous devez me prouver votre capacité à acquérir la matière première de cet art : des écailles de draconiens.", progress = "Si vous êtes prêt à prendre la décision définitive de devenir un Artisan du cuir d'écaille de dragon, je peux vous prendre comme apprenti. Apportez-moi juste les choses que je vous ai demandées, et je commencerai votre éducation.", completion = "Je vous le dis - il faut une volonté forte pour prendre une décision irréversible comme vous venez de le faire. Je vous assure, le travail du cuir d'écaille de dragon sera pour vous une voie profitable.\n\nPour apprendre cet art dans le futur, parlez-moi simplement et je vous dispenserai toutes les connaissances qu'il vous faut encore acquérir.", rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir d'écailles de dragon\n\nVous recevrez :\n\n"},
[5146] = {title = "Travail du cuir élémentaire", objective = "Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Winterhoof dans les montagnes d’Arathi.\n\nL’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Le travail du cuir élémentaire est mon domaine, et si vous voulez ouvrir votre esprit aux plus grands pouvoirs de l'art, je partagerai avec vous tout ce qu'il y a à savoir.\n\nSachez ceci, <classe> : en prenant cette voie vous vous engagez à ne jamais apprendre le tavail des écailles de dragon ou le travail du cuir tribal. Vous ne pouvez atteindre l'excellence que dans un seul de ces trois domaines. De plus, j'aurai besoin de la preuve que vous êtes en relation avec les éléments de la nature. Pour ce faire, apportez-moi les essences les plus pures de feu, d'eau, de terre et de vent.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir élémentaire\n\nVous recevrez :\n\n"},
[5147] = {title = "On recherche : Arnak Grimtotem", objective = "Tuer Arnak Grimtotem et apporter une preuve de votre acte au garde-falaise Longhorn au Poste de Librevent.", description = "On recherche : Arnak Grimtotem\n\nArnak le paria est recherché pour meurtres et enlèvements. Une forte récompense sera remise à ceux qui oseront lui faire sentir le poids de la justice.\n\nArnak a été aperçu pour la dernière fois dans les falaises proches de la Cime de Noir-nuage. Pour obtenir la prime, apportez la preuve de votre exploit au garde-falaise Longhorn au Poste de Librevent.", progress = "Avez-vous des nouvelles de ce meurtrier d'Arnak Grimtotem ?", completion = "Ah ! Voilà d'excellentes nouvelles ! Je commençais à craindre qu'il n'échappe toujours à la justice !\n\nVoici pour vous, &lt;nom&gt;... et merci ! Ce que j'apprends sur les agissements stupides d'Arnak me fait bouillir le sang.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArmure de peau coriaceJambières du Garde des plaines\n\nVous recevrez également :\n\n"},
[5148] = {title = "Travail du cuir tribal", objective = "Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Se'Jib dans la vallée de Strangleronce.\n\nL’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Apprendre le travail du cuir tribal nécessite une réelle compréhension de ce qu'est la véritable nature primale. Je sais que vous maîtrisez déjà l'art de la confection d'armures en cuir sauvage, et je souhaite poursuivre votre entraînement.\n\nSachez ceci, <classe> : en choisissant de suivre cette voie, vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir élémentaire. Vous ne pouvez vraiment maîtriser qu'une seule des trois disciplines. De plus, apportez-moi les meilleurs exemplaires de vos armures en cuir sauvage. À partir de là, nous pourrons poursuivre votre apprentissage.", progress = "La nature est une force qu'il faut apaiser avant d'espérer apprendre comment modeler sa volonté pour la faire entrer dans vos habits de cuir. Apportez-moi une offrande pour cette force, et je ferai en sorte qu'on vous entende.", completion = "Vous avez donné vos meilleures offrandes, et la nature se pliera bientôt à votre volonté. Lorsque vous quitterez ma tutelle, votre travail sera lui-même une force de la nature.\n\nPour apprendre cet art à l'avenir, il vous suffit de venir me parler. Je vous dispenserai toutes les connaissances qu'il vous faut encore acquérir.", rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir tribal\n\nVous recevrez :\n\n"},
[5149] = {title = "Poupée de Pamela", objective = "Trouver la poupée de Pamela.", description = "Ma tante Marlene m'a dit de rester ici dans notre maison car mon père devait partir pour se battre. Mon père est l'homme le plus courageux du monde !\n\nMais je suis là depuis longtemps, et il n'est pas venu me chercher. Parfois des gens méchants viennent et chuchotent et je veux que mon père les chasse, mais il n'est pas là !\n\nEt parfois quand il fait sombre je veux jouer avec ma poupée mais je ne peux pas parce que je l'ai laissée en ville.\n\nVous voulez bien chercher ma poupée ?", progress = "Vous avez trouvé ma poupée ?", completion = "Vous l'avez trouvée ! Vous avez trouvé ma poupée ! Oh, merci !", rewards = "Vous recevrez :\n\n"},
[5150] = {title = "Dadanga a faim !", objective = "Dadanga vous regarde alors que vous l'approchez. Elle semble espérer quelque chose…\n\nElle a probablement faim !\n\nIl y a certainement quelque chose qui pousse dans le cratère et qui ferait un parfait en-cas pour un herbivore de grande taille. Dadanga est une grande fille : quoi que vous lui apportiez, il faudra que ce soit en grosse quantité !", description = nil, progress = "Dadanga vous regarde alors que vous l'approchez. Elle semble espérer quelque chose…\n\nElle a probablement faim !\n\nIl y a certainement quelque chose qui pousse dans le cratère et qui ferait un parfait en-cas pour un herbivore de grande taille. Dadanga est une grande fille : quoi que vous lui apportiez, il faudra que ce soit en grosse quantité !", completion = "Les pousses posées devant elle, Dadanga semble satisfaite.\n\nElle pousse un petit paquet enveloppé de brun vers vous, en échange du petit cadeau !", rewards = "Vous recevrez :\n\nPetit paquet marron emballé"},
[5151] = {title = "Hypercapaciteur bidulotron", objective = "Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthèse à Wizlo Bearingshiner.", description = "Je suis le seul survivant de l'attaque de notre caravane par les centaures ! Une panthère rare mais puissante garde mon meilleur bidule autour du cou ! Ha ! Même les centaures tremblent en présence de cette bête féroce !\n\nVoici la clé de la cage. Ils ont tout emporté, mais l'ont laissée seule. Tuez cette bête et rapportez-moi mon hypercapaciteur. Vous serez alors <récompensé/récompensée>.\n\nLes restes de la caravane se trouvent juste au nord d'ici.", progress = "Vous avez mon hypercapaciteur ?", completion = "Mon hypercapaciteur ! Cela va m'occuper un petit moment, jusqu'à ce que je comprenne ses fonctions…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nAnneau de la Ligue des Inventeurs"},
[5152] = {title = "Tante Marlene", objective = "Parler à Marlene, au sud des ruines d'Andorhal.", description = "Oh, je suis si seule ! Où est ma famille ? Tante Marlene m'a dit de rester ici, mais alors elle est partie et n'est jamais revenue ! Et papa… vous l'avez vu ?\n\nPeut-être que Tante Marlene sait où il est. Elle vit près d'Andorhal, dans une maison au sud. Je crois que c'était sur une colline... elle a dit que c'était sur une colline.\n\nS'il vous plaît, <nom>. Vous êtes <mon nouvel ami/ma nouvelle amie> ! Vous voulez parler à ma Tante pour moi ?", progress = nil, completion = "Vous avez vu Pamela ? Comment va-t-elle ? Elle est vivante ?? Oh non ! Pauvre Pamela ! Elle était si jeune, et c'était une enfant si joyeuse…\n\nElle ignore ce qui est arrivé à son père, n'est-ce pas ? Mon frère, Joseph ?\n\nNon… Elle ne pourrait pas comprendre ce qui est arrivé à Joseph. Et même si elle le pouvait, je n'ai pas le coeur de lui dire...", rewards = "Vous recevrez :\n\n"},
[5153] = {title = "Un étrange historien", objective = "Apporter l’Alliance de Joseph à Chromie.", description = "Si seulement Joseph pouvait de nouveau être avec sa fille, mais cela est impossible. Son âme a été corrompue par le Fléau et il est devenu un monstre. Oh, il n'y a plus d'espoir !\n\nMais nous pouvons peut-être changer le cours du destin. Cherchez la tombe de Joseph dans le cimetière. Son corps n'y est pas enterré car il fut piétiné et détruit il y a des années, mais sous la pierre tombale, vous trouverez son alliance. Amenez cet anneau à Chromie... une gnome étrange possédant des pouvoirs plus étranges encore.\n\nChromie est installée dans l'auberge en ruines dans le nord-ouest d'Andorhal.", progress = "Votre visite tombe à point nommé. Vous ne venez pas du futur, n'est-ce pas ?", completion = "Qu'est-ce ? Une alliance ? Montrez-la moi…\n\nAh ! Cette bague était au doigt d'un grand homme, mais je vois de grands drames dans son passé.\n\nVenez-vous afin de lui porter secours ? C'est déjà bien trop tard désormais… mais nous pouvons peut-être l'aider dans le passé !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5154] = {title = "Les annales de Darrowshire", objective = "Apporter les Annales de Darrowshire à Chromie, à Andorhal.", description = "Pour sauver Joseph Redpath, nous devons d'abord découvrir son passé. Nous pouvons l'apprendre des Annales de Darrowshire, un livre se trouvant à la mairie d'Andorhal.\n\nApportez-moi ce livre. Nous pourrons alors découvrir le destin de Joseph, et avec un peu de chance... nous pourrons le changer !", progress = "Avez-vous trouvé le livre, <nom> ?", completion = "Parfait, vous l'avez trouvé !\n\nVous l'avez lu ? Y parle-t-on de Joseph Redpath ? Si c'est le cas, peut-être pouvons-nous le sauver !\n\nAh. Les annales de Darrowshire racontent une histoire étrange. Il est dit que pendant la bataille, Joseph Redpath fut corrompu et rejoignit les rangs du Fléau ! Il a ensuite trahi les défenseurs de Darrowshire.\n\nQuel destin malheureux. Si nous le pouvons, nous devrions essayer de changer cela, vous ne trouvez pas ?", rewards = "Vous recevrez :\n\n"},
[5155] = {title = "Les forces de Jaedenar", objective = "Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois.", description = "Si vous voulez que je vous fasse confiance, il va d'abord falloir faire vos preuves.\n\nJe dois être sûr que vous êtes un ennemi du Conseil des ombres, responsable de tant d'abominations ici et ailleurs.\n\nEnfoncez-vous dans Gangrebois. À l'ouest, vous apercevrez un chemin menant à Jaedenar. C'est ici que le Conseil complote avec la Légion Ardente.\n\nPénétrez au coeur de l'un des Refuges des Saisons qu'ils habitent et éliminez-les. Revenez me voir une fois votre mission terminée. Je saurai alors que vous cherchez vraiment à nous aider.", progress = nil, completion = "Bien, &lt;nom&gt; ! Leur nombre s'amenuisant, nous pouvons davantage faire pression sur eux.\n\nQuelle a été votre première impression de leur pouvoir ? Etaient-ils aussi forts que vous le pensiez ? Plus forts ? Ou peut-être n'ont-ils constitués aucun défi pour vous. Ça ne serait pas quelque chose, ça ?\n\nNous discuterons plus tard des détails de vos exploits. Il y a d'autres choses qui demandent notre attention maintenant.", rewards = "Vous recevrez :\n\n"},
[5156] = {title = "Enquête sur la corruption", objective = "Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d’eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois.", description = "En allant vers le nord, à l'est de la route qui traverse le Val Grêlé, se trouve un lieu où les Infernaux se rassemblèrent durant la dernière grande guerre : des cratères défigurent le paysage, ainsi que les Infernaux eux-mêmes.\n\nDeux choses m'intriguent : premièrement, y a-t-il toujours des élémentaires d'entropie qui errent sur la zone ? Deuxièmement : les cratères sont-ils toujours remplis d'eau fétide et corrompue, piégée là depuis des années ? M'aiderez-vous, <nom> ? Attention, les Infernaux détruisent tout sur leur passage.", progress = nil, completion = "C'est bien que vous soyez toujours en vie, &lt;nom&gt;. Dommage que l'eau existe toujours. J'espérais trouver au moins une source d'eau pure ici à Gangrebois. On dirait que ma quête a échoué. Le processus de guérison de la terre aurait été grandement amélioré si elle avait existé.\n\nJe vais devoir me consacrer au sauvetage des créatures de la forêt encore sauvables, tout en détruisant celles qui ont été tant corrompues qu'elles se mettent elles-mêmes en danger, comme elles mettent en danger les voyageurs qui traversent cette forêt autrefois puissante.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5157] = {title = "Recueillir de l'eau souillée", objective = "Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois.", description = "Au cœur de Jaedenar se dresse le Fort des ombres, une forteresse clé où se concentrent corruption et forces du mal.\n\nLe Conseil des ombres a lancé des sorts de protection autour de son antre sous la forme de braseros. Si je dois obtenir plus d'informations sur notre ennemi par la divination, ces braseros doivent être éteints. Ainsi, je pourrai espionner le Conseil et découvrir qui est leur chef.\n\nSi vous le pouvez, prenez cette gourde et remplissez-la dans le puits de Lune situé au centre de Jaedenar. Ensuite, revenez me voir.", progress = "Une fois que nous aurons les eaux du puits de lune, nous les purifierons et les utiliserons pour éteindre les braseros de protection du Fort des ombres. Cela devrait me donner assez de temps pour explorer les pièces plus en profondeur et déterminer qui est à la tête de ce... culte.\n\nJe prie pour que la Terre-mère soit avec nous.", completion = "Cela ira parfaitement, &lt;nom&gt;.\n\nMaintenant, tout ce que nous avons à faire, à part d'en asperger les braseros, c'est de faire purifier cette l'eau. Cela ne devrait pas être trop difficile et ne demander qu'un peu de déplacement.\n\nEspérons que nous pourrons voyager rapidement.", rewards = "Vous recevrez :\n\n"},
[5158] = {title = "À la recherche de soutien spirituel", objective = "Apporter l’Eau de Puits de lune corrompue à Islen Waterseer dans les Tarides.", description = "Portez l'eau corrompue jusqu'aux Tarides, <nom>. Au sud de Ratchet, dissimulée sur le rivage, se trouve une de mes vieilles amies, c'est une chaman nommée Islen Waterseer. Elle est puissante et nous aidera. Les liens qu'elle entretient avec les esprits de l'eau ont toujours été très forts. Notre tâche étant noble, cela devrait la convaincre de nous aider ainsi que les esprits.\n\nVous devriez la trouver dans un petit campement au bord de l'eau. Et, <nom>, ignorez les pirates, ils sont gênants mais ne représentent aucune menace.", progress = "J'ai l'impression que vous n'êtes pas un simple voyageur qui cherche le chemin de Ratchet. Venez, asseyez-vous et reposez-vous dans notre camp. Vous me parlerez quand vous serez prêt.", completion = "Ah, vous devrez purifier l'eau tirée du Puits de Lune. Vouloir arrêter les forces malignes de Gangrebois semble être une cause suffisamment noble, mais il ne m'appartient pas de décider si cette eau doit ou non être sanctifiée. Je vais interroger les esprits de l'eau, eux seuls pourront déterminer si votre motif est juste.\n\nLaissez-moi le temps de leur soumettre votre demande. J'espère qu’ils vous seront aussi favorables que moi.", rewards = "Vous recevrez :\n\n"},
[5159] = {title = "L'eau purifiée retourne à Gangrebois", objective = "Apporter l’Eau de Puits de lune purifiée à Greta Mosshoof dans Gangrebois.", description = "Remerciez les esprits, <nom>. Ce sont eux qui vous ont apporté de l'aide, pas moi.\n\nJe vous remets cette eau purifiée. Faites mes amitiés à Greta. Elle est sur la piste de quelque chose de plus important que nos petites personnes…et je pense qu'elle arrivera bientôt à ses fins.\n\nLe Conseil des ombres n'est pas une force que l'on peut traiter à la légère, <nom>.Souvenez-vous-en.\n\nPartez maintenant. Prenez l'eau et retournez-voir Greta.", progress = "Ah, je vois que vous êtes de retour, <nom>. Bien. Avez-vous trouvé Islen dans les Tarides ? Ou devons-nous trouver un autre moyen d'atteindre nos objectifs ?", completion = "Cela devrait être plus qu'assez d'eau pour nos projets.\n\nJe suis content qu'Islen ait pu nous aider. Elle a toujours été très forte avec les esprits de l'eau. Elle est sage aussi, et rares sont les esprits qui ne s'accordent à ses desseins. Qu'ils aient tous béni notre tâche me donne confiance en la justesse de notre voie.", rewards = "Vous recevrez :\n\n"},
[5160] = {title = "Le Protectorat de la matrone", objective = "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee.", description = "Allez jusqu'à Kalimdor, <race>. Notre vol vous fera oublier que nous allons survoler les paysages désolés du Berceau-de-l'Hiver. Lorsque vous aurez atteint le Berceau-de-l'Hiver, trouvez les grottes de Mazthoril.\n\nSur le sol glacé de Mazthoril, vous trouverez des runes de cobalt. Prenez l'une de mes écailles et tenez-vous sur une rune pour être transporté auprès d'Haleh, notre grande protectrice.\n\nDonnez-lui l'écaille afin qu'elle puisse, par des moyens divinatoires, voir et ressentir ce que j'ai pu vivre dans cet endroit maudit.", progress = "C'est bon de vous voir, <nom>.", completion = "Les Aspects insistent pour que nous n'intervenions pas dans les affaires des mortels. Dans ce monde pourtant cela n'est pas toujours le cas, spécialement lorsque l'un des nôtres méprise de telles règles.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5161] = {title = "La colère du vol bleu", objective = "Si vous souhaitez continuer, parlez à Haleh.", description = "Nous avons eu connaissance des plans de l'engeance maudite de l'Aile de mort, et nous ne pouvons pas les laisser faire.\n\nÀ cause de la protection que le mont Blackrock offre à Nefarian, il est devenu très difficile pour nous d'intervenir.\n\nCependant, nous pouvons vous donner des pouvoirs, si vous le désirez.\n\nLe chemin qui s'ouvre devant vous est périlleux. Acceptez-vous notre aide ? Réfléchissez bien et revenez me voir quand vous aurez pris une décision.", progress = nil, completion = "Qu'il en soit ainsi…", rewards = "Vous recevrez :\n\n"},
[5162] = {title = "La colère du vol bleu", objective = "Parler à Jeziba dans les Maleterres. Il vit à Andorhal.", description = "C'est l'arcane que je contrôle et qui vous mènera à votre prochaine destination.\n\nDès que vous êtes <prêt/prête>, le voyage pourra commencer. Vous allez dans les Maleterres et c'est à Jeziba que vous devez parler.\n\nC'est un mortel aussi sage que les anciens et aussi patient que la terre immuable. Trouvez-le en Andorhal.", progress = nil, completion = "Je suis Jeziba, que l'on connaît surtout sous le nom de Sculpteur. Ce que je sculpte cependant, ce ne sont pas des statues, mais des héros.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5163] = {title = "Yéti ? Y es-tu ?", objective = "Prendre le yéti mécanique d'Umi et effrayer ses amis avec :\n\nLegacki, à Long-guet (Berceau-de-l'Hiver)\nSprinkle, à Gadgetzan (Tanaris)\nQuixxil, au refuge des Marshal (Cratère d'Un'Goro)\n\nQuand vous aurez terminé, rapporter le yéti mécanique à Umi.", description = "Tout est prêt, <nom> !\n\nJ'envoie un courrier à mes amis, leur disant que j'ai une surprise pour eux. C'est là que vous intervenez !\n\nJe vais vous confier mon yéti mécanique. Vous allez rendre visite à chacun de mes amis, activer le yéti et l’envoyer vers eux.\n\nLorsque vous serez <passé/passée> voir Legacki à Long-guet, Sprinkle à Gadgetzan et Quixxil au refuge des Marshal, revenez et racontez-moi tout en détail !\n\nEt rapportez-moi mon yéti…", progress = "J'ai hâte de voir comment mes amis vont réagir !\n\nIls ne s'attendent pas à ça !", completion = "Ha ! Il y réfléchiront à deux fois avant de rire à nouveau de mes idées !\n\nMerci de votre aide, &lt;nom&gt;. Je ne me serais pas autant amusée sans vous !", rewards = "Vous recevrez :\n\nYéti mécanique"},
[5164] = {title = "Guide de l'Indocile", objective = "Lire le Guide de l'Indocile.", description = "Haleh n'aurait pas pu choisir un meilleur instrument de justice. Instruisez-vous en lisant le Guide de l'Indocile et que votre esprit s'illumine.\n\nPersistez...Faites ce qui vous est demandé...Si vous survivez…<un héros/une héroïne> vous deviendrez.", progress = nil, completion = "Des centaines et des centaines de pages de gribouillis ésotériques composent l'essentiel de ce livre.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5165] = {title = "En calmant les flammes de protection", objective = "Avec de l’Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l’intérieur du Fort des ombres dans Gangrebois.", description = "Maintenant, nous devons retourner à Jaedenar. Les braseros sont allumés tout autour du Fort des ombres. Éteignez-les et les protections que le Conseil a mis en place tomberont pendant une courte période. J'attendrai cet instant et lorsque ce sera le moment, je fouillerai du regard le Fort et essaierai de découvrir quelle créature est à la tête du mouvement. Alors seulement nous penserons à les attaquer directement.", progress = nil, completion = "Je pouvais vous voir avec mes sorts comme les flammes du dernier brasero mourraient. Bien joué, &lt;nom&gt;.\n\nJ'ai pu apprendre deux ou trois choses avant que le Conseil des ombres ne puisse relancer leurs sorts. J'espère que cela sera suffisant.\n\nPour l'instant, reposez-vous. Je vous parlerai dans un moment de ce que j'ai pu apprendre.", rewards = "Vous recevrez :\n\n"},
[5166] = {title = "La cuirasse du vol chromatique", objective = "Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :\n\n1 Carapace chromatique.\n\n10 Ecailles chromatiques brillantes.\n\n10 Sangs de héros.\n\n10 Coutures d'Abomination effilochées.", description = "La fabrication d'une puissante cuirasse qui formerait une protection contre les attaques incessantes des dragons chromatiques est une idée assez drôle.\n\nLes écailles des créatures que nous combattons doivent être cousues sur une carapace de drake ou de dragon chromatique en parfait état. Leur existence n'est pas reconnue à ce jour et nous espérons qu'elle ne le sera jamais.\n\nPour finir, peut-être le composant le plus improbable : du sang de héros.\n\nEnfin, le Sculpteur doit forger l'objet.", progress = "C'est un choix très sage, <nom>.", completion = "Ne comprenez-vous toujours pas ? Le voyage était la destination. Pouvez-vous ignorer les cicatrices des combats ? La peine que vous avez eue ?\n\nDu fait d'avoir survécu à cette épreuve, vous en êtes sorti grandi. Cette cuirasse n'est qu'un pâle reflet de vos propres dons.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCuirasse du vol chromatique"},
[5167] = {title = "Cuissardes des duellistes chromatiques", objective = "Pour forger les Cuissardes des duellistes chromatiques, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :\n\n1 Carapace chromatique.\n\n10 Ecailles chromatiques brillantes.\n\n10 Sangs de héros.\n\n5 Peaux des ombres.", description = "La carapace d'un drake chromatique adulte est nécessaire pour obtenir la forme des jambières. Des écailles chromatiques brillantes sont alors posées sur la structure renforcée et enchantées dans du sang de héros. Enfin, il faut appliquer la peau des ombres à l'intérieur des bottes.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières des duellistes chromatiquesCuissardes des duellistes chromatiques\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5168] = {title = "Héros du Darrowshire", objective = "Apporter le Libram de Davil et le Bouclier Redpath à Carlin Redpath.", description = "Les héros du Darrowshire ont une place dans mon cœur. Le livre que vous m'avez apporté, “les Annales du Darrowshire”, raconte leurs aventures.\n\nIl parle du paladin Davil Lightfire et explique comment la Croisade a ramené son libram à l'hôtel de ville de Hearthglen.\n\nDes passages parlent également de mon frère, le capitaine Redpath. Après sa trahison, son bouclier a été brisé et abandonné dans un endroit improbable, près de la ferme de la Flétrissure de Gahrron.\n\nRassemblez ces reliques, <nom>. Elles sont marquées par le destin.", progress = "Avez-vous les reliques, <nom> ?", completion = "Vous avez le grimoire et le bouclier !\n\nLeur histoire est intimement liée à celle de Darrowshire ; et je sais que, d'une façon ou d'une autre, le destin les rassemblera.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5181] = {title = "Vilains de Darrowshire", objective = "Rapporter le Crâne d'Horgus et l’Epée brisée de Marduk à Carlin Redpath à la chapelle de l'Espoir de Lumière.", description = "Les annales du Darrowshire parlent du camp des mauvais. Elles racontent comment le seigneur goule Horgus le Ravageur a été tué par les forces de l'Alliance pendant la bataille. Son corps a été jeté dans un lac, au nord-ouest de la Croisée de Corin. Son crâne est toujours là-bas.\n\nMarduk le Noir n'a jamais été vaincu, mais son épée fabuleuse a été brisée et perdue. Elle gît au fond de la gorge, à l'ouest de la Passe de Corin.\n\nRetrouvez ces objets, <nom>. Je ne sais pas pourquoi, mais je suis certain que leur destin est lié au vôtre.", progress = "Avez-vous trouvé le crâne et l'épée, <nom> ?", completion = "Vous les avez trouvées ! Bravo, &lt;nom&gt; ! Ces reliques possèdent un pouvoir que je ne comprends pas tout à fait, un pouvoir que vous maîtriserez un jour !\n\nElles me rappellent aussi de tristes souvenirs de mort et de trahison, et de la dernière nuit de Darrowshire...", rewards = "Vous recevrez :\n\n"},
[5201] = {title = "L'incursion des Tombe-hiver", objective = "Rivern Frostwind veut que vous tuiez 5 Chamans Tombe-hiver et 5 Ursas Tombe-hiver.", description = "Ma présence reste inaperçue de la plupart, <nom>. Cependant, un problème semble perdurer au Berceau-de-l'Hiver : les furbolgs Tombe-hiver.\n\nBien que je n'ai jamais attaqué de front les furbolgs, ils semblent avoir perdu la raison, et craignent tout ce qui croise leur chemin. Je les ai vus massacrer un grand nombre de créatures qui avaient la malchance d'être là, tout simplement.\n\nJe suis fatigué de leur agressivité. Aidez-moi à les combattre. Tuez les furbolgs et maintenez-les à distance du Roc des Sabres-de-givre.", progress = nil, completion = "Je suis soulagé de savoir qu'au moins un temps, nous n'avons pas d'incursion à redouter des Tombe-hiver.\n\nVous commencez à montrer de la persévérance, &lt;nom&gt;.", rewards = nil},
[5202] = {title = "Une étrange clé rouge", objective = "Chercher dans Jaedenar à quoi sert la Clé rouge sang.", description = "La petite clé rouge semble faite d'une espèce d'os. Elle est lourde mais semble fragile. Pourquoi un membre du Conseil des ombres posséderait-il une telle chose ? Il doit y avoir quelque chose que cette étrange clé ouvre à Jaedenar.", progress = "Je commence à me demander si je m'échapperai un jour de cette cage.\n\nCe n'est qu'une question de temps avant qu'ils ne m'immolent au démon quelconque qu'ils vénèrent. Les monstres !", completion = "La clé, vous l'avez trouvée ! Par pitié, donnez-la-moi que je puisse enfin m'enfuir !", rewards = "Vous recevrez :\n\n"},
[5203] = {title = "Sauvetage à Jaedenar", objective = "Escorter Arko'narin à l’endroit où Lightforge et son équipement sont détenus, puis la protéger lors de l’évasion du Fort des ombres. Ensuite, aller trouver Jessir Moonbow dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis.", description = "Bien que cela me peine énormément, il y a une chose que je dois faire d'abord : trouver l'épée de Trey Lightforge et m'échapper du Fort des ombres afin de prévenir mes supérieurs de ce qui se passe ici. Pouvez-vous m'aider, <nom> ?\n\nNotre équipement n'est pas très loin, et vous avez déjà prouvé que vous pouvez survivre au chemin qui mène tout là haut.\n\nUne fois que nous nous serons échappés, j'irai à Darnassus, mais il faudra encore trouver mon amie Jessir près de la frontière d'Ashenvale. Elle devait nous retrouver au camp du Cercle d'émeraude près d'ici.\n\nQu'en dites-vous, <nom> ? Acceptez-vous de m'aider encore ?", progress = nil, completion = "Vous êtes celui qui a aidé Arko à s'échapper ? Je suis si contente que vous m'ayez trouvée ! Elle est passée par ici il y a peu, en route vers Darnassus. Elle traînait Lightforge et ne se serait pas même arrêtée pour demander des soins aux druides. Elle a dit qu'elle était bien trop pressée.\n\nMais elle m'a parlé de votre rencontre avec l'esprit de Trey. Quelle triste fin pour un chevalier de la Main d'Argent. Elle ne l'a pas montré, mais je sais que son coeur pleure toujours l'un de ses plus proches amis.", rewards = "Vous recevrez :\n\n"},
[5204] = {title = "Le châtiment de la Lumière", objective = "Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Lightforge.", description = "Elle veut faire croire qu'elle va bien. Elle aimerait que je la crois suffisamment forte pour faire face toute seule, mais je ne suis pas aveugle. La mort de Trey et la façon dont il a été torturé vont la hanter longtemps. Il n'y a rien que l'on peut faire pour soulager sa peine. Mais nous pouvons lui apporter un peu de paix !\n\n<nom>, retournez au Fort des ombres, tuez le tortionnaire de Trey et retrouvez ses restes. Pourquoi ne pas mettre fin à cela pendant qu'Arko'narin pleure en silence ?", progress = "Vous observez le corps, et le doute n'est pas permis, il s'agit là de la dépouille du chevalier de la Main d'Argent, Trey Lightforge. Pendant un instant, vous pensez à Arko'narin et vous vous demandez si quelqu'un a eu plus d'importance pour vous qu'il n'en a eu pour l'elfe de la nuit prisonnière que vous avez récemment aidée à s'échapper du Fort des ombres.\n\nAprès un moment passé à rassembler vos pensées, vous vous rendez compte que vous ne pouvez ramener les restes du paladin à Jessir sans avoir tué d'abord son tortionnaire.", completion = "Vous rassemblez les restes du paladin avec autant de soins que possible, gardant à l'esprit qu'au moins son esprit a été libéré des peines et des tourments qu'on lui a infligés.", rewards = "Vous recevrez :\n\nCadavre de Trey Lightforge"},
[5206] = {title = "Les maraudeurs du Darrowshire", objective = "Apporter 5 Crânes résonants et le Cristal mystique à Carlin Redpath, dans les Maleterres de l’est.", description = "Chromie a dit que les reliques que vous avez ramassées sont des réactifs pour un charme puissant, mais il en manque encore un : des crânes appartenant aux troupes du Fléau qui ont participé à la bataille du Darrowshire.\n\nPrenez ce cristal et chassez les champions du Fléau pour prendre leurs crânes. Le cristal est enchanté : lorsque vous le passerez sur le crâne d'un champion, il résonnera si celui-çi a participé à la bataille. Apportez-moi les crânes qui résonnent.\n\nAllez, <nom>. Vous trouverez les champions du Fléau dans la Clairière nocive au nord et dans la vallée des Fongus à l'ouest.", progress = "Avez-vous les crânes ? Chromie a dit qu'ils étaient indispensables pour son sort, et ce sort nous donnera une chance de sauver le Darrowshire.", completion = "Vous les avez trouvés ! Merveilleux !\n\nBien que je ne comprenne pas exactement comment ils peuvent nous aider, je ressens leur pouvoir et je sens au fond de moi qu'ils sont liés avec mon village natal du Darrowshire.", rewards = "Vous recevrez :\n\n"},
[5210] = {title = "Frère Carlin", objective = "Apporter les Annales complètes de Darrowshire à Carlin Redpath dans les Maleterres de l’est.", description = "Les Annales de Darrowshire, grâce à ma magie, ont gagné des pages et vont maintenant au-delà de la bataille. L'un des passages supplémentaires parle d'un autre Redpath, Carlin, qui a survécu à la trahison de Joseph. Carlin est maintenant dans les Maleterres de l'est, dans la chapelle de l'Espoir de Lumière.\n\nPrenez le livre et parlez-lui.", progress = "Vous venez de l'ouest ? Comment s'en tire le reste de Lordaeron ? Je sais qu'Andorhal est perdu, mais le Fléau a-t-il déjà atteint la belle Tirisfal ?", completion = "Qu'est-ce que ce tome ? Les annales de Darrowshire ? C'était ma patrie avant la guerre… avant la bataille qui l'a détruite ! Pourquoi m'avez-vous apporté ce livre ?\n\nMais regardez ici ! Tout à la fin on parle des jours d'après la guerre ! Là, un passage sur moi ! Et un sur mon frère Joseph ! Est-ce que ce livre dit vrai ?\n\nNous devons découvrir la vérité !", rewards = "Vous recevrez :\n\n"},
[5211] = {title = "Défenseurs de Darrowshire", objective = "Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath.", description = "De nombreux défenseurs sont tombés lors de la bataille du Darrowshire. Et beaucoup errent désormais sous la forme terrible des serviteurs du Fléau ! Trouvez ces pauvres âmes et mettez fin à leur malheur !\n\nChassez les goules cannibales, les goules bredouillantes et les écorcheurs maladifs. Beaucoup de ces créatures étaient de bons citoyens du Darrowshire. Détruire leur enveloppe charnelle libérera leur esprit.\n\nVous les trouverez dans Pestebois, à la Croisée de Corin au nord-ouest et dans d'autres forteresses du Fléau dans les Maleterres de l'Est.", progress = nil, completion = "C'est bon de savoir que vous avez pu trouver et libérer les âmes torturées de mes frères. Mon cœur saigne moins, sachant qu'au moins quelques défenseurs de Darrowshire ne se vautrent plus dans la perversion du Fléau.", rewards = "Vous recevrez :\n\n"},
[5212] = {title = "La chair ne ment pas", objective = "Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair.", description = "Les apothicaires Réprouvés ne sont pas les seuls êtres au monde versés dans les sciences.\n\nJ'ai étudié la peste pendant des années, <nom>. Nous pensions que sa puissance vacillait, mais ce que j'ai découvert ici dans les Maleterres est consternant. La peste semble gagner en force !\n\nJe dois effectuer davantage de tests ! La source la plus puissante de la peste est celle de la chair souillée de ceux les plus récemment infectés. Partez pour Stratholme et rapportez-moi des échantillons, <nom>.", progress = "Certains disent que je me fais trop de soucis - je leur répond \"Vous ne vous en faites pas assez !\"", completion = "Quelque chose a changé dans la structure chimique des agents actifs de la peste. Davantage de données sont nécessaires.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5213] = {title = "L'agent actif", objective = "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink.", description = "Vous devez fouiller plus profond dans Stratholme, <nom>.\n\nAu-delà des premières portes, vous trouverez les ziggourats. Nous savons que le Fléau tire beaucoup d'énergie de ces structures. Trouvez les ziggourats et revenez avec toutes les informations que vous pouvez réunir.", progress = "Nous sommes sur le point de découvrir ce que peut être ce nouveau composant de la peste !", completion = "Stupéfiant ! Cela va prendre des mois pour le disséquer et l'analyser. L'Aube d'argent vous remercie pour vos efforts, &lt;nom&gt;.\n\nChoisissez votre récompense entre ce Sceau ou cette Rune de l’Aube, avec notre bénédiction. Tous deux peuvent vous servir de Brevet de l’Aube d’argent pour rassembler des Pierres du Fléau en notre nom. Si vous le perdez, revenez me voir, et je vous le remplacerai.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSceau de l'AubeRune de l'Aube\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5214] = {title = "Le grand Ezra Grimm", objective = "Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.", description = "C’est terrible… ce qui est arrivé à Ezra. La ville était aux mains des pillards, mais il ne voulait pas abandonner sa précieuse marchandise. Je me souviens qu’il disait : « Je brûlerai tout jusqu’à la dernière feuille plutôt qu’ils mettent leurs sales mains dessus ! »\n\nJe donnerais presque n’importe quoi pour une bonne pipe, mais il y a des limites ! J’ai quitté Ezra et son magasin ce jour-là. J’imagine que tout a brûlé, mais s’il y avait ne serait-ce qu’une chance qu’une boîte de son délicieux tabac soit encore intacte…\n\nQu’en dites-vous, <nom> ? Vous iriez en chercher une boîte pour ce vieux Smokey ?", progress = "Je n'en peux plus, <nom> ! Il faut que vous m'aidiez ! Je meurs !", completion = "Oh, comme vous m'avez manqué...", rewards = "Vous recevrez :\n\nBriquet de Smokey"},
[5215] = {title = "Les chaudrons du Fléau", objective = "Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l’ouest.", description = "Sur les terres de l'ancienne Lordaeron se trouvent huit chaudrons : quatre ici à l'ouest et quatre plus à l'est. Ces chaudrons diffusent du poison dans l'air, propageant la peste sur tout le territoire, servant ainsi le Fléau.\n\nLa puissance nécromantique de Kel'Thuzad est trop grande pour réussir à complètement fermer ces chaudrons. Nous pensons qu'il y a peut-être moyen d'en tirer parti. La grande prêtresse MacDonnell, qui me seconde, sera votre référent pour cette mission. C'est elle qui vous donnera les instructions dorénavant.", progress = nil, completion = "Puisse le pouvoir de la Lumière vous accompagner dans ces moments sombres, &lt;classe&gt;. Je suis heureuse d'être votre coordinatrice dans notre mission de sabotage des chaudrons du Fléau. \n\nNotre objectif sera de modifier ces chaudrons pour qu'ils répandent une pestilence dont les effets néfastes n'affecteront que ceux du Fléau. Pour cela, il faudra que vous sécurisiez chacun des accès menant aux quatre chaudrons présents dans les Maleterres de l'ouest.\n\nTenez-vous prêt, héros, car une bataille glorieuse contre le vil Fléau vous attend !", rewards = "Vous recevrez :\n\n"},
[5216] = {title = "Cible : le Champ de Felstone", objective = "Se rendre au Champ de Felstone dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.", description = "Des quatre chaudrons situés à l'ouest, celui du Champ de Felstone est peut-être le plus facile d'accès. Le Fléau a des troupes moins aguerries ici, à ne pas sous-estimer cependant.\n\nAllez au Champ de Felstone, au nord-ouest d'Andorhal, et attaquez le Seigneur du chaudron. Nous pensons qu'il a une clé qui donnera accès au chaudron. Une fois déverrouillé, utilisez cette bouteille pour obtenir un échantillon des poisons contenus dans le chaudron ; nous en aurons besoin pour développer un antidote.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé dérobée au seigneur du chaudron Bilegueule s'insère parfaitement et débloque le panneau d'accès. Une odeur nauséabonde s'en répand alors qu'un mélange inconnu de substances concentrées se dilue dans le chaudron.\n\nIl y a au-dessous une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la grande prêtresse MacDonnell, à la pointe du Noroît.", rewards = "Vous recevrez :\n\n"},
[5217] = {title = "Retour au camp du Noroît", objective = "Apporter une Bouteille du Champ de Felstone remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.", description = "Vous remplissez la bouteille avec suffisamment de décoction empoisonnée pour être étudiée.\n\nUne fois le poison en bouteille, retournez auprès de la grande prêtresse MacDonnell au camp du Noroît et votre mission sera terminée.", progress = "Bienvenue dans la sécurité relative du camp du Noroît, <nom>. Où en êtes-vous avec les chaudrons ?", completion = "Bien joué &lt;nom&gt; - l'alchimiste Arbington devrait sous peu analyser ceci et dresser la liste des composant inverses à ajouter au contenu du chaudron. Si nous pouvons en répandre suffisamment dans l'air, nous pourrions affaiblir le Fléau dans la région.\n\nCela ne va pas être facile, car nous devrons régulièrement frapper ces chaudrons pour introduire ce mélange. Si nous y parvenons, nous aurons un énorme avantage sur le Fléau au moment de l'affronter !", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5218] = {title = "Le Chaudron du champ de Felstone", objective = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", description = nil, progress = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", completion = "L'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s'en échappent. Les créatures du Fléau même éloignées du chaudron semblent reculer au fur et à mesure que les nouveaux composants se répandent.", rewards = nil},
[5219] = {title = "Cible : les Larmes de Dalson", objective = "Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.", description = "L'un des chaudrons de peste est situé dans le champ d'une ancienne ferme maintenant appelée les Larmes de Dalson. Pas question de verser de larmes alors que nous allons contrecarrer le Fléau et les étouffer avec leurs propres vapeurs pestiférées !\n\nAllez jusqu'aux Larmes de Dalson, normalement au nord d'Andorhal, et éliminez le Seigneur du chaudron. Il doit avoir une clé, comme le précédent Seigneur, vous permettant d'accéder au chaudron. Utilisez cette bouteille pour prélever un échantillon dans le chaudron ; chaque chaudron a sa propre mixture toxique.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé macabre trouvée sur le seigneur du chaudron glisse facilement dans la serrure puis disparaît, vous y laissant un accès permanent. Des substances abjectes parcourent les méandres des tubes courant sous les chaudrons.\n\nIl y a au-dessous une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la grande prêtresse MacDonnell, à la pointe du Noroît.", rewards = "Vous recevrez :\n\n"},
[5220] = {title = "Retour au camp du Noroît", objective = "Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.", description = "Vous remplissez la bouteille avec suffisamment de liquide pour représenter un échantillon intéressant.\n\nVous voilà en possession du poison et <prêt/prête> à retourner auprès de la grande prêtresse MacDonnell au camp du Noroît.", progress = "Nous savons que chaque chaudron emploie un mélange de composants différent pour produire sa toxine pestilentielle ; c'est pourquoi il nous faut créer un réactif différent pour chaque chaudron. Votre échantillon de Larmes de Dalson nous servira à déterminer le composant spécifique de ce chaudron.", completion = "Ah, il y a matière à analyse ici. Bien joué, &lt;nom&gt; !\n\nA nous de jouer maintenant. Nous devrons dresser la liste des composants qui, combinés au contenu du chaudron, en inverseront les effets.\n\nLe seul moyen sera de mélanger ces composants dans le chaudron même. L'alchimiste Arbington en saura plus, parlez-lui au plus tôt.", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5221] = {title = "Chaudron des Larmes de Dalson", objective = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", description = nil, progress = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", completion = "L'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s'en échappent. Les créatures du Fléau même éloignées du chaudron semblent reculer au fur et à mesure que les nouveaux composants se répandent.", rewards = nil},
[5222] = {title = "Cible : le Repaire putride", objective = "Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.", description = "Deux chaudrons ont été ouverts ce qui vous laisse le champ libre. Nous voulons cependant ouvrir les deux restants. Cela nous donnera plus de chances pour introduire l'antidote !\n\nCette fois-ci vous allez vous attaquer au chaudron du Repaire putride. Il est situé à l'est d'Andorhal, relativement près des murs en ruines de la ville. Eliminez le Seigneur du Chaudron et emparez-vous de sa clé. Prenez cette bouteille pour prélever un échantillon.\n\nBonne chasse, <nom> !", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé du seigneur du chaudron ouvre le panneau d'accès puis disparaît, comme celles des deux chaudrons dont vous vous êtes déjà occupé. Une substance d'une puanteur abominable gicle violemment du dessous de la plate-forme du chaudron.\n\nIl y a une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la grande prêtresse MacDonnell, à la pointe du Noroît.", rewards = "Vous recevrez :\n\n"},
[5223] = {title = "Retour au camp du Noroît", objective = "Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.", description = "Vous débouchez délicatement la bouteille. Un échantillon de la substance fétide qui bouillonne sous la plate-forme du chaudron est maintenant prisonnière du fragile récipient de verre.\n\nVous voilà en possession du poison et <prêt/prête> à retourner auprès de la grande prêtresse MacDonnell au camp du Noroît.", progress = "Une fois que nous aurons analysé l'échantillon prélevé dans le chaudron du Repaire putride, nous aurons une troisième occasion de lancer un contre-agent dévastateur à la face du Fléau.", completion = "Une nouvelle mission réussie, &lt;nom&gt; ! Cela fait trois chaudrons que nous pourrons retourner contre le Fléau. Si la domination nécromancienne de Kel’Thuzad sur ces terres n'était pas si grande, je vous dirais de les détruire complètement !\n\nL'alchimiste Arbington a une liste des composants nécessaires pour ce chaudron (ainsi que pour les autres) afin d'inverser ses effets. Grâce à cela, le temps est venu d'amener le dernier chaudron de l'ouest sous notre influence !", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5224] = {title = "Le Chaudron du Repaire putride", objective = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", description = nil, progress = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", completion = "L'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s'en échappent. Les créatures du Fléau, même éloignées du chaudron, semblent reculer au fur et à mesure que les nouveaux composants se répandent.", rewards = nil},
[5225] = {title = "Cible : la Flétrissure de Gahrron", objective = "Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.", description = "Le dernier chaudron est situé dans une ferme que l'on appele maintenant la Flétrissure de Gahrron. Il est gardé par les sbires les plus coriaces du Fléau, en particulier des âmes en peine et des fantômes. Ils ne faut pas les prendre à la légère, <nom>.\n\nLa Flétrissure de Gahrron se trouve au nord-est de notre position, là où les Maleterres commencent. A nouveau, éliminez le Seigneur du Chaudron et emparez-vous de sa clé. Voici votre bouteille et rapportez-la-moi remplie. Que la Lumière vous protège tout au long de cette dangereuse mission, <classe>.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé du seigneur du chaudron Irâme disparaît lorsqu'elle touche le panneau d'accès à la base de la plate-forme du chaudron. Un léger déclic se fait entendre, et le panneau s'ouvre pour mieux révéler les toxines funestes animant l'entrelacs de tubes. Une substance d'une puanteur abominable gicle violemment du dessous de la plate-forme du chaudron.\n\nIl y a une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la grande prêtresse MacDonnell, à la pointe du Noroît.", rewards = "Vous recevrez :\n\n"},
[5226] = {title = "Retour au camp du Noroît", objective = "Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.", description = "Vous fermez avec précaution le robinet sur le panneau de contrôle tout en regardant le liquide putride du chaudron couler dans la bouteille vide.\n\nVous voilà en possession du poison et <prêt/prête> à retourner auprès de la grande prêtresse MacDonnell au camp du Noroît.", progress = "Le dernier chaudron qu'il nous faut trouver ici dans l'ouest se trouve à la Flétrissure de Gahrron. Quand nous aurons un échantillon de la peste contenue dans ce chaudron, nous pourrons introduire nos réactifs dans les environs par quatre éléments différents. Le Fléau aura du mal à nous en empêcher, même avec le soutien de Kel'thuzad.", completion = "Félicitations &lt;nom&gt;, vous nous avez ouvert l'accès au dernier chaudron ! L'alchimiste Arbington saura vite ce qu'il faudra comme composants pour le mélange.\n\nSinon, je suis certaine que le commandant Valorfist désire vous remercier personnellement de l'aide que vous nous avez apportée. Sans vous, notre combat contre le Fléau aurait été presque insurmontable. Merci, héros !", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5227] = {title = "Chaudron de la Flétrissure de Gahrron", objective = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", description = nil, progress = "Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.\n\nPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.", completion = "L'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s'en échappent. Les créatures du Fléau même éloignées du chaudron semblent reculer au fur et à mesure que les nouveaux composants se répandent.", rewards = nil},
[5228] = {title = "Les chaudrons du Fléau", objective = "Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.", description = "Dans les terres de l'ancienne Lordaeron, il y a huit chaudrons : quatre à l'ouest et quatre plus à l'est. Ces chaudrons vomissent leur poison dans l'air, propageant la peste au service du Fléau.\n\nLa puissance nécromantique de Kel'Thuzad est trop importante pour sceller ces chaudrons, mais nous pensons qu'il y a peut-être moyen d'en tirer parti. La prêtresse des ombres Vandis, qui me seconde, sera votre référent pour cette mission. C'est elle qui vous donnera les instructions dorénavant.", progress = nil, completion = "Des ombres, frère &lt;nom&gt;, je vous salue. Je dois vous servir de coordinatrice pour notre projet de sabotage des chaudrons du Fléau.\n\nNotre objectif est d'altérer la pestilence que ces chaudrons répandent pour en faire une dont les effets néfastes n'affecteront que le Fléau. Pour cela, il faudra que vous sécurisiez chacun des accès menant aux quatre chaudrons présents ici dans les Maleterres de l'ouest.\n\nIl vous appartient, héros, de conduire la charge contre l'abject Fléau.", rewards = "Vous recevrez :\n\n"},
[5229] = {title = "Cible : le Champ de Felstone", objective = "Se rendre au Champ de Felstone, dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.", description = "Des quatre chaudrons situés dans les Maleterres de l'ouest, celui du Champ de Felstone est peut-être le plus facile d'accès. Le Fléau a des troupes moins aguerries ici, à ne pas sous-estimer cependant.\n\nAllez au Champ de Felstone, au nord ouest d'Andorhal, et attaquez le Seigneur du chaudron. Nous pensons qu'il a une clé qui donnera accès au chaudron. Une fois déverrouillé, utilisez cette bouteille pour obtenir un échantillon des poisons contenus dans le chaudron ; nous en aurons besoin pour développer un antidote.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé prise au seigneur du chaudron Bilegueule s'introduit facilement pour ouvrir le panneau d'accès. Bien qu'elle disparaisse aussitôt, vous savez que vous pourrez le rouvrir sans elle désormais. Une odeur nauséabonde s'en répand alors qu'un mélange inconnu de substances concentrées se dilue dans le chaudron.\n\nIl y a une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la prêtresse des Ombres Vandis, à la Muraille.", rewards = "Vous recevrez :\n\n"},
[5230] = {title = "Retour à la Barricade", objective = "Apporter la Bouteille du Champ de Felstone remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.", description = "Vous remplissez la bouteille avec suffisamment de décoction empoisonnée pour être étudiée.\n\nUne fois le poison en bouteille, retournez auprès de la prêtresse des ombres Vandis à la Barricade et votre mission sera terminée.", progress = "Bienvenue dans la sécurité relative de la Barricade, <nom>. Où en êtes-vous avec les chaudrons ?", completion = "Bien joué &lt;nom&gt; - le Pharmacien Dithers devrait sous peu analyser ceci et dresser la liste des composant inverses à ajouter au contenu du chaudron. Si nous pouvons en répandre suffisamment dans l'air, nous pourrions affaiblir le Fléau dans la région.\n\nCela ne va pas être facile, car nous devrons régulièrement frapper ces chaudrons pour introduire ce mélange. Si nous y parvenons, nous aurons un énorme avantage sur le Fléau au moment de l'affronter !", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5231] = {title = "Cible : les Larmes de Dalson", objective = "Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.", description = "L'un des chaudrons de peste est situé dans le champ d'une vieille ferme maintenant appelée les Larmes de Dalson. Aucune larme ne sera versée aujourd'hui, <classe> ; nous devons attaquer ce chaudron et y accéder !\n\nAllez jusqu'aux Larmes de Dalson, au nord d'Andorhal, et éliminez le Seigneur du chaudron. Il doit avoir une clé, comme le précédent Seigneur, vous permettant d'accéder au chaudron. Utilisez cette bouteille pour prélever un échantillon dans le chaudron ; chaque chaudron a sa propre mixture toxique.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé squelette trouvée sur le seigneur du chaudron glisse facilement dans la serrure puis disparaît, vous y laissant un accès permanent. Des substances abjectes parcourent les méandres des tubes courant sous les chaudrons.\n\nIl y a une sorte de fausset auquel la bouteille s'ajuste bien, vous permettant d'en tirer un échantillon pour la prêtresse des Ombres Vandis, à la Muraille.", rewards = "Vous recevrez :\n\n"},
[5232] = {title = "Retour à la Barricade", objective = "Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.", description = "Vous remplissez avec précaution la bouteille d'assez d'essence du chaudron pour que vous considériez l'échantillon suffisant.\n\nÀ présent que vous êtes en possession du poison, il est temps de retourner voir la prêtresse des ombres Vandis à la Barricade afin d'achever la mission.", progress = "Nous savons que chaque chaudron emploie un mélange de composants différent pour produire sa toxine pestilentielle ; c'est pourquoi il nous faut créer un réactif différent pour chaque chaudron. Votre échantillon de Larmes de Dalson nous servira à déterminer le composant spécifique de ce chaudron.", completion = "Ah, il y a plein de choses à étudier, là dedans. Bravo, &lt;nom&gt; !\n\nLa suite est entre vos mains. Il nous faudra faire une liste des réactifs qui, mélangés au contenu actuel du chaudron, produiront son effet contraire.\n\nLa seule façon d'introduire cela est de placer les réactifs directement dans le chaudron. L'Apothicaire Dithers aura davantage d'informations à ce sujet, parlez-lui donc le plus vite possible.", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5233] = {title = "Cible : le Repaire putride", objective = "Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.", description = "Deux chaudrons ont été ouverts avec succès, et bien que vous pourrez y accéder indéfiniment, nous voulons toujours ouvrir les deux qui restent. Cela nous fournira à tous davantage d'options pour introduire l'agent !\n\nCette fois-ci, vous allez frapper le Chaudron du Repaire putride. Il se trouve presque exactement à l'est d'Andorhal, assez près des murs de la cité en ruines. Eliminez-y le Seigneur du Chaudron qui s'y trouve pour obtenir sa clé. Servez-vous de cette bouteille pour recueillir l'échantillon du chaudron.\n\nBonne chasse, <nom> !", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé du seigneur du chaudron ouvre un panneau d'accès au chaudron, puis disparaît, comme les autres clés lors des précédentes opérations. Une substance à l'odeur putride bouillonne sauvagement sous la plate-forme du chaudron.\n\nLa bouteille entre très bien sous un petit robinet, vous permettant de prélever un échantillon pour la prêtresse des ombres Vandis, à votre retour à la Barricade.", rewards = "Vous recevrez :\n\n"},
[5234] = {title = "Retour à la Barricade", objective = "Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.", description = "Vous débouchez délicatement la bouteille. Un échantillon de la substance fétide qui bouillonne sous la plate-forme du chaudron est maintenant prisonnière du fragile récipient de verre.\n\nVous voilà en possession du poison et prêt à retourner auprès de la prêtresse des ombres Vandis à la Barricade pour que la mission soit finie.", progress = "Une fois que nous aurons analysé l'échantillon prélevé dans le chaudron du Repaire putride, nous aurons une troisième occasion de lancer un contre-agent dévastateur à la face du Fléau.", completion = "Une nouvelle mission réussie, &lt;nom&gt; ! Cela fait trois chaudrons que nous pourrons retourner contre le Fléau. Si la domination nécromancienne de Kel’Thuzad sur ces terres n'était pas si grande, je vous dirais de les détruire complètement !\n\nL'alchimiste Arbington a une liste des composants nécessaires pour ce chaudron (ainsi que pour les autres) afin d'inverser ses effets. Avec cela, le temps sera venu d'amener le dernier chaudron à l'ouest sous notre influence !", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5235] = {title = "Cible : la Flétrissure de Gahrron", objective = "Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.", description = "Le dernier chaudron se trouve sur une ferme que l'on appelle maintenant la Flétrissure de Gahrron, gardée par certains des plus terribles serviteurs du Fléau, et plus précisément des âmes en peine et des fantômes. Ils doivent être pris très au sérieux, <nom>.\n\nLa Flétrissure de Gahrron se trouve loin à l'est de la Barricade, près de l'endroit où commencent les Maleterres de l'est. Là aussi, éliminez le seigneur du chaudron et récupérez sa clé. Voici votre bouteille vide. Veuillez me la rapporter pleine. Puissent les ombres vous dissimuler dans cette dangereuse mission, <classe>.", progress = "Un panneau d'accès au chaudron reste solidement fermé. Pour l'ouvrir, il vous faudra trouver la clé.", completion = "La clé du seigneur du chaudron Irâme disparaît en touchant la serrure du panneau d'accès à la base de la plate-forme du chaudron. Un léger cliquetis se fait entendre à l'intérieur et le panneau s'ouvre sur de nouvelles toxines maléfiques dans la structure du chaudron.\n\nLa bouteille entre très bien sous un petit robinet, vous permettant de prélever un échantillon pour la prêtresse des ombres Vandis, à votre retour à la Barricade.", rewards = "Vous recevrez :\n\n"},
[5236] = {title = "Retour à la Barricade", objective = "Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.", description = "Vous fermez avec précaution le robinet du panneau de contrôle, en regardant l'essence putride goûter dans la bouteille vide.\n\nÀ présent que vous avez le poison, il est temps de retourner voir la prêtresse des ombres Vandis à la Barricade afin d'achever la mission.", progress = "Le dernier chaudron qu'il nous faut trouver ici dans l'ouest se trouve dans la Flétrissure de Gahrron. Quand nous aurons un échantillon de la peste contenue dans ce chaudron, nous pourrons introduire nos réactifs dans les environs par quatre éléments différents ! Le Fléau aura du mal à nous en empêcher, même soutenu par le pouvoir de Kel'Thuzad.", completion = "Félicitations, &lt;nom&gt;, vous avez ouvert le dernier chaudron pour nous. L'Apothicaire Dithers saura bientôt ce dont ce chaudron a besoin en matière de réactifs pour le mélange.\n\nEn ce qui vous concerne, soyez certain que le Haut Exécuteur Derrington voudra vous remercier personnellement pour l'aide que vous nous avez apportée. Sans vous, notre combat contre le Fléau aurait été pratiquement insurmontable. Je vous remercie, puissant &lt;classe&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nMot de pouvoir : Robustesse\n\nVous recevrez :\n\n"},
[5237] = {title = "Mission accomplie !", objective = "<nom>, votre travail couronné de succès sur les chaudrons est une immense victoire pour nous !\n\n\n\nQue tout le monde le sache : pour services rendus au Royaume de Stormwind et à l'Alliance et pour avoir fait bien plus que son devoir, face à un danger incroyable et contre tout espoir, je remets ceci à <nom> en même temps que je l'assure de notre gratitude. Félicitations !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée courte vaillanteEpée courte intrépide\n\nVous recevrez également :\n\nMédaille de valeur héroïque"},
[5238] = {title = "Mission accomplie !", objective = "<nom>, votre travail couronné de succès sur les chaudrons est une immense victoire pour nous !\n\n\n\nQue tout le monde le sache : pour services rendus aux Réprouvés et à la Horde et pour avoir fait bien plus que son devoir, face à un danger incroyable et contre tout espoir, je remets ceci à <nom> en même temps que je l'assure de notre gratitude. Félicitations !", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée courte vaillanteEpée courte intrépide\n\nVous recevrez également :\n\nMédaille de valeur héroïque"},
[5241] = {title = "Oncle Carlin", objective = "Trouver Carlin Redpath.", description = "Parfois, la nuit, je peux entendre mon oncle pleurer. On dirait qu'il est loin, à l'est.\n\nJ'espère ne pas être la cause de ses pleurs ! <nom>, pourriez-vous trouver mon oncle et lui dire que je vais bien ?\n\nSi vous le voyez, dites-lui que je l'attends, et que j'aimerais entendre à nouveau cette histoire qu'il racontait... celle des lapins et de la confiture de baies ! Elle est si amusante !", progress = nil, completion = "Avez-vous vu Pamela ? Elle est vivante ?\n\nElle est morte ? Non ! Oh, Pamela ! Pourquoi ton esprit souffre-t-il encore dans ce monde. Pourquoi es-tu morte, alors que le destin me garde en vie ? Je changerais volontiers de place avec toi pour errer, mort, dans Darrowshire, un fantôme solitaire !\n\nAh, mais cette nouvelle ne peut changer la destinée. Merci &lt;nom&gt;. Maintenant mon devoir, mon devoir de vengeance, brûle plus fort que jamais.", rewards = "Vous recevrez :\n\n"},
[5242] = {title = "Un coup final", objective = "Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Fel'dan à Greta Mosshoof dans Gangrebois.", description = "La seule solution pour arrêter la menace qui pèse sur Gangrebois est malheureusement une attaque frontale. Il n'y a pas d'autre façon d'accéder au Fort des ombres, et je n'ai pas la possibilité de vous téléporter à l'intérieur. Le chemin qui descend est le seul accès... et je sais également qui vous devez éliminer. Son nom est Fel'dan... Le Seigneur des ténèbres Fel'dan. C'est lui qui règne en maître... c'est la tête du serpent. Tuez-le ainsi que ses deux servantes succubes et revenez me voir. Fel'dan conclut des pactes avec la Légion. Il faut l'arrêter.", progress = "Avec un peu de chance, sans Fel'dan, le Conseil des ombres perdra son efficacité et cessera le combat. Ils se battront les uns contre les autres pour le pouvoir et commenceront à ourdir des plans pour l'avenir. Une occasion parfaite de les attaquer, eux et leurs esclaves démons.", completion = "La Terre-mère soit louée ! Merci &lt;nom&gt; ! C'est un grand jour, pour sûr !\n\nLe Conseil des ombres aura du mal à retrouver le niveau de puissance qu'il avait autrefois avec ce coup porté à sa hiérarchie. Vous avez accompli un haut fait aujourd'hui !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe de BrantwoodGants en cuir chancreuxCeinturon de Gearforge\n\nVous recevrez également :\n\n"},
[5243] = {title = "Les demeures du Sacré", objective = "Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.", description = "Je considère ma nature cadavérique comme une maladie, <nom>. Un problème de santé qui nécessite des soins. C'est également une bénédiction pour l'Aube d'argent. Quel meilleur moyen de frapper les païens du Fléau que les morts-vivants ?\n\nMes collègues me vénèrent à cause des sacrifices que j'ai faits mais leurs courbettes me laissent indifférent.\n\nSi vous souhaitez aider l'Aube d'argent, alors j'ai un travail pour vous.\n\nAllez à Stratholme et récupérez notre surplus d'eau sacrée. Fouillez les caisses de ravitaillement.", progress = "Prudence, toutes les caisses de fournitures n'auront pas survécu à la destruction de la cité. Le Fléau n'ose pas toucher à l'eau, mais il est certain que l'eau sacrée n'empêchera pas la propagation de la vermine.", completion = "Bien joué, &lt;nom&gt;. Bien que vous ayez fait preuve de tolérance envers les autres, vous ne céderez à rien pour détruire les serviteurs de Kel’Thulzad.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCouronne du pénitentAnneau du pénitent\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nPotion de soins excellentePotion de mana supérieure"},
[5244] = {title = "Les ruines de Kel'Theril", objective = "Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles", description = "L'histoire qui suit Kel'Theril est celle d'une race maudite, liée à l'endroit où s'est déroulé un malheureux rituel…\n\nLe Bien-né que vous trouverez là a jadis volé un artefact sacré, croyant qu'il pouvait absorber sa puissance, pour la transmettre aux siens. Lors du rituel, la relique fut détruite à la suite d'une explosion qui éparpilla les morceaux sous la glace du lac...\n\nParlez avec Jaron Stoneshaper pour en savoir plus. Il a récemment parcouru la zone et connaît le coin.", progress = nil, completion = "Évidemment que je peux vous en dire plus sur Kel'Theril. Bien que je ne sois pas un historien, je puis vous raconter ce que j'y ai vu…", rewards = "Vous recevrez :\n\n"},
[5245] = {title = "Les Esprits troublés de Kel'Theril", objective = "Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est.", description = "Les esprits des Bien-nés sont de misérables créatures, c'est certain. Ils sont toujours à la recherche des morceaux de l'objet qui les a maudits et liés à Kel'Theril pour toujours : la Relique volée.\n\nSi cela vous intéresse, prenez ma pioche et allez au sud du lac. Voyez si vous pouvez réunir les morceaux pris sous la glace.\n\nJe ne peux pas vous renseigner sur ce que vous avez trouvé, mais je connais quelqu'un qui en saura plus... Aurora Skycaller, elle vit à la tour du Col du nord, dans les Maleterres de l'Est.", progress = "Pourquoi êtes-vous venu ici ?", completion = "Nous ne désirons pas évoquer le passé des hauts-elfes, &lt;nom&gt;. S'il vous plaît, il me peine de repenser à tout ce qui est arrivé… Et qu'il n'y ait rien à faire pour redresser les choses.", rewards = "Vous recevrez :\n\n"},
[5246] = {title = "Fragments du passé", objective = "Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est.", description = "Je ne m'étais pas rendu compte… Excusez-moi, <classe>.\n\nJe n'aime pas m'étendre sur les erreurs de mes ancêtres, mais si votre demande est honnête, je vous aiderai.\n\n<Aurora examine les fragments.>\n\nOn dirait le cristal de Zin-Malor, une relique qui peut contenir et contrôler des forces liées aux arcanes très puissantes. Il aurait pu être utilisé à de bonnes fins, mais les mauvaises intentions de ceux qui l'ont volé ont fini par le briser.\n\nAllez au temple de Zin-Malor en Azshara. J'espère que le livre y sera toujours.", progress = "C'est seulement en lisant les pages de nos textes sacrés que je serai en mesure de discerner si oui ou non je peux vous aider...", completion = "Les pages sont restées intouchées pendant de très longues années…", rewards = "Vous recevrez :\n\n"},
[5247] = {title = "Fragments du passé", objective = "Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est.", description = "Je pourrai vous aider, si vous voulez vraiment recréer l'artefact.\n\nPour réunir les pièces, j'aurai besoin d'objets de grande qualité magique : une barre de thorium enchantée et cinq cristaux de restauration... Vous devrez aussi aller chercher de l'eau à un endroit qui peut sembler inadéquat... Trouvez le bassin redoutable. Il se trouve le long de l'allée d'Eldreth à Hache-Tripes, en Feralas, et remplissez cette fiole.\n\nPendant votre absence, j'essaierai de glaner dans ces pages des informations sur la façon dont je peux réparer les dégâts causés à la relique.", progress = "La relique doit être remise entre les mains du plus digne de confiance. Elle ne doit pas être dérobée à nouveau…", completion = "En utilisant ces composants, j'espère pouvoir souder les différents fragments… afin d'en faire ce qu'ils étaient autrefois.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5248] = {title = "Tourmentée par le passé", objective = "Amener le Cristal de Zin-Malor au lac Kel'Theril dans le Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler.", description = "<nom>, je pleure à cause du passé. Comme ce cristal, les elfes, en tant que race, ont été brisés. Je ne sais pas si les morceaux seront jamais recollés mais ma peine a été allégée grâce à l'aide que j'ai pu vous apporter dans cette tâche.\n\nNous ne devons pas oublier le passé, <nom>...\n\nS'il vous plaît, allez remettre le cristal de Zin-Malor dans le lac Kel'Theril. Vous devez trouver un esprit Bien-né qui ait réalisé l'erreur commise il y a si longtemps. Montrez à l'esprit que les choses sont rentrées dans l'ordre.", progress = "Mauuudit… Pour tooouuuujours…", completion = "Par pitié…laissez moi….", rewards = "Vous recevrez :\n\n"},
[5249] = {title = "Au Berceau-de-l'Hiver", objective = "Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver, et parler à Wynd Nightchaser.", description = "Le Berceau-de-l'Hiver, au nord d'ici, est jonché ruines elfes. C'est une terre dure, mais elle détient beaucoup de secrets et d'endroits à explorer.\n\nAvec tout mon travail ici à Gangrebois, je n'ai pas eu l'opportunité d'aller jusqu'au Berceau-de-l'Hiver. Mais il en est autrement pour vous !\n\nPendant que vous y êtes, allez voir Wynd Nightchaser. Il passe la plupart de son temps au village de Pluie-d'Etoiles et il sait beaucoup de choses sur cet endroit.", progress = nil, completion = "Un ami d'Ivy Leafrunner ? Heureux de vous rencontrer, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[5250] = {title = "Pluie-d'Etoiles", objective = "Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver et parler à Wynd Nightchaser.", description = "Le Berceau-de-l'Hiver, au nord de Gangrebois, est jonché de ruines elfes. C'est une terre hostile, mais elle détient beaucoup de secrets et d'endroits à explorer.\n\nMes études ici m'accaparent et je n'ai pas eu l'opportunité d'aller jusqu'au Berceau-de-l'Hiver. Mais il n'y a aucune raison pour que vous ne puissiez pas y aller et étudier les ruines.\n\nLorsque vous serez là-bas, cherchez Wynd Nightchaser. Il passe la plupart de son temps au village de Pluie-d'Etoiles et il connaît bien la région.\n\nDites-lui que vous êtes l'un de mes étudiants.", progress = nil, completion = "Un étudiant de Daryn Lightwind ? Enchanté, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[5251] = {title = "L'archiviste", objective = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates.", description = "Tout ce qui est extrême est dangereux pour notre monde, <nom>. Prenez par exemple la Croisade écarlate. Croyez-vous vraiment que leurs zélotes servent un bien supérieur ? Combien d'innocents ont-ils tués au nom de la Lumière ?\n\nDes blasphémateurs, tous autant qu'ils sont !\n\nL'un d'eux m'intéresse particulièrement, tout de même : l'archiviste Galford de Stratholme, un homme qui veille sur les documents les plus précieux de la Croisade. Tuez-le et brûlez ses archives ! Si vous réussissez, revenez me voir et vous serez <récompensé/récompensée>.", progress = nil, completion = "Extraordinaire, &lt;nom&gt; ! Des années d'espionnage perdues ! La Croisade écarlate ressentira certainement ce coup dans les semaines qui viennent.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5252] = {title = "Une Bien-née pleine de remords", objective = "Parler à Wynd Nightchaser au village de Pluie-d'Etoiles et lui demander quel est le bon endroit pour le Cristal de Zin-Malor.", description = "Le…Le cristal…\n\nIci, les Bien-nés sont aveuglés par leur propre souffrance…\n\nJe suis trrriste mais je me rends compte de l'erreur commise il y a si longtemps. Bien qu'on ne puiiisse pas changer le passé, je suis maintenant en paix, sachant que vous avez découvert le cristal de Zin-Malor...\n\nVouuus devez le rendre...\n\nIl doiiiit être rrrendu.", progress = "Voilà longtemps que vous êtes parti, <nom>. Comment cela s'est-il passé ?", completion = "Est-ce… ce à quoi je pense ?", rewards = "Vous recevrez :\n\n"},
[5253] = {title = "Le Cristal de Zin-Malor", objective = "Apporter le Cristal de Zin-Malor à l’archidruide Fandral Staghelm à Darnassus.", description = "Impressionnant, <nom>.\n\nLe cristal de Zin-Malor ne pourra jamais être replacé dans le temple qui, vous le savez, est maintenant en ruine. Mais j’estime que vos efforts pour réparer les méfaits du passé ne doivent pas rester sans récompense.\n\nTrouvez l'archidruide Fandral Staghelm à Darnassus et apportez-lui le cristal, <nom>. Il doit être remis entre les mains de ceux qui n'abuseront pas de son pouvoir. Apparemment, seule une poignée d’utilisateurs de magie, parmi les plus puissants, sont capables de contrôler une telle force.", progress = "Oui, <nom> ?", completion = "J'ai entendu parler du cristal de Zin-Malor. Celui qui le détient devient le maître d'une puissance des arcanes incroyable, mais seulement s'il le mérite. Je suis impressionné que vous l'ayez retrouvé et encore plus que, connaissant vos limites, vous ne l'ayez pas utilisé.\n\nMerci de me l'avoir apporté, &lt;nom&gt;. Nous le garderons en sûreté, et puissent les âmes damnées qui le gardaient autrefois trouver enfin le repos.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe turquoiseSpallières du laboureurGantelets de la brume émeraude\n\nVous recevrez également :\n\n"},
[5261] = {title = "Eagan le tanneur", objective = "Parler à Eagan Peltskinner.", description = "Eagan Peltskinner cherche quelqu'un qui chasserait le loup pour lui. C'est une bonne nouvelle, car il y a de plus en plus de loups ces temps-ci dans la Vallée de Northshire.\n\nSi cela vous intéresse, allez parler à Eagan. Vous le trouverez en contournant l'abbaye sur la gauche.", progress = nil, completion = "C'est vrai. Je recherche quelqu'un qui pourrait chasser des loups pour moi ! Êtes-vous cette personne ?", rewards = "Vous recevrez :\n\n"},
[5262] = {title = "La vérité vient du ciel", objective = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est.", description = "Vous essayez de rassembler vos pensées alors que la poussière retombe dans la chambre. Vous revenez sur les événements et vous ne comprenez toujours pas la gravité de la situation.\n\nLe grand croisé de la Croisade écarlate, un démon ? Et pas n'importe quel démon, mais le frère de Varimathras, le seigneur d'Undercity ?\n\nVous remettez avec précaution la tête tranchée du seigneur de l'effroi dans votre sac. Personne ne voudra jamais croire votre histoire sans preuve.\n\nLe duc Nicholas Zverenhoff doit être informé immédiatement !", progress = "Qu'avez-vous là, <nom> ?", completion = "Qu'est-ce que cela signifie pour la Croisade ? Se peut-il qu’ils aient été sous l'influence de ce démon ? Servant sans s'en douter un mal bien plus grand encore ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5263] = {title = "Au-dessus et au-delà", objective = "S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff.", description = "Vous avez une aptitude naturelle à la destruction et vous suivez les ordres. Il est rare de voir les deux coexister. Je commence à croire que vous pouvez faire un excellent porte-parole de la justice divine.\n\n<Zverenhoff joint ses mains devant son visage.>\n\nLe laquais de Kel'Thuzad règne sur Stratholme. Prouvez-moi que vous êtes un champion, mon champion. Détruisez le baron Rivendare et revenez avec sa tête.", progress = "Le baron a sans doute massacré plus de personnes que vous n'en avez vu tout le long de votre vie.", completion = "Il y a belle lurette que nous n'avons pas reçu de héros dans nos rangs. Vous êtes le premier à être reçu par le seigneur Maxwell depuis des années.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5264] = {title = "Seigneur Maxwell Tyrosus", objective = "Parler au seigneur Maxwell Tyrosus. Il est à l’intérieur de l’église.", description = "Je suis sur le point de vous faire un grand honneur, <nom>.\n\nLe seigneur Maxwell souhaite vous récompenser pour vos états de service à l'Aube d'argent !\n\nCela faisait des années que Maxwell n'avait pas donné audience à des étrangers.", progress = nil, completion = "Vous êtes un allié précieux, &lt;nom&gt;. Vous recevrez la récompense pour votre dévouement sans faille.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5265] = {title = "Siège de l’Aube d'argent", objective = "Ouvrir le Coffre prendre votre récompense.", description = "Durant toutes ces années, le Fort Argent est resté fermé. Personne ne s'est montré assez valeureux pour atteindre son coeur et s'y emparer de la puissance de l'Aube d'argent, jusqu'à aujourd'hui.\n\nLe Fort Argent vous est maintenant ouvert, <nom>.", progress = nil, completion = "Ouah…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nVengeresse d'argentDéfenseur de l'Aube d'argentCroisé d'argent\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5281] = {title = "Âmes tourmentées", objective = "Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme.", description = "Il y a ceux qui sont morts tragiquement dans la chute de Stratholme. Nombreux furent ceux qui mirent un terme à leur propre vie et optèrent de se précipiter dans les myriades de flammes de la cité fumante plutôt que de devenir simple marionnette du Fléau.\n\nIls parcourent à présent les rues de Stratholme sous forme d'esprits ne pouvant trouver le repos.\n\nNous devons leur venir en aide, <nom> !\n\nJ'ai un associé du nom d'Egan qui a obtenu des résultats miraculeux sur des fantômes et sur des esprits. Partez à sa recherche. Il se trouve dans les Maleterres de l'est, près de Stratholme, où il teste ses innovations.", progress = nil, completion = "Alen a fini par trouver quelqu'un d'assez brave, hein ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5282] = {title = "Âmes tourmentées", objective = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !\n\nLibérer 15 Esprits sans repos puis retourner auprès d’Egan.", description = "Je tire mon pouvoir - ma volonté de continuer à vivre et à respirer - de la haine absolue que j'ai envers le Fléau et envers ce qu'ils ont fait. Je ne suis pas cependant un zélote. Il y a ceux, comme la Croisade écarlate, qui préfèreraient détruire d'innocents morts-vivants plutôt que de leur accorder ne serait-ce qu'une once de compassion.\n\nCe qui m'amène à cela : mon Libérateur. Il libérera les esprits torturés de Stratholme.\n\nServez-vous-en sur les fantômes qui hantent les rues saccagées. Apaisez leurs esprits.", progress = "La compassion est ce qui nous différencie de l'animal, <nom>. Ne l'oubliez pas…", completion = "&lt;Egan essuie une larme.&gt;\n\nAvez-vous vu ma mère, &lt;nom&gt; ? L'avez-vous libérée ?\n\nVous êtes un brillant exemple d'honnêteté. Pour vous dédommager...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTestament d'espoir"},
[5283] = {title = "L'art de l'armurier", objective = "Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants et les rapporter à Grumnus : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril.", description = "Ainsi vous avez pris la bonne décision.\n\nOn ne s'apprécie guère ici, moi et ce vieux Ironus. Ce bon à rien de fabricant de jouets sait parfaitement qui sont les véritables artisans de valeur en ces contrées.\n\nLes guerres véritablement grandes sont gagnées avec une bonne défense. Quand c'est l'heure d'y aller, aucune arme ne vous fera de cadeau dans la bataille.\n\nMais passons, et mettons-nous au travail. Tout ce que vous avez à faire est de me montrer que vous avez le talent de base nécessaire. Après, j'aplatirai vos imperfections et vous mettrai dans le moule de la fabrique d'armures. Vous savez comment faire du mithril orné, pas vrai ?", progress = "Ah, rien de tel qu'un bon bronzage de forge. Vous voyez les meilleurs bronzage aux marques du tablier.", completion = "Qu'il en soit ainsi, &lt;nom&gt;. Après ceci, plus moyen de reculer. Il n'est pas trop tard pour devenir un fabricant de jouets, ou, un fabricant d'armes.\n\nJe suis certain que vous prendrez la bonne décision", rewards = "Vous allez être la cible du sort suivant :\n\nArtisan armurier\n\nVous recevrez :\n\n"},
[5284] = {title = "La voie du Forgeron d'armes", objective = "Pour devenir un Fabricant d'armes, il faut fabriquer les éléments suivants et les rapporter à Ironus : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires.", description = "En tant que <fabricant/fabricante> d'armes, vous verrez à maintes reprises que les héros et les aventuriers viendront vous voir pour obtenir un bon équipement. Bien que la charge de travail puisse être parfois insoutenable, les richesses que l'on en retire font oublier le mal de dos et les poumons pris.\n\nOui, <nom>, les Fabricants d'armes sont ceux qui ont tout l'or !\n\nSi vous souhaitez rejoindre nos rangs, vous allez devoir me montrer que vous pouvez m'apporter quelques pièces... je veux dire me faire quelques pièces et que vous serez <l'homme/la femme> de la situation lorsqu'il s'agira de forger des armes de qualité supérieure. Au travail !", progress = "<Ironus est en train de mettre des pièces d'or en petites piles bien nettes.>", completion = "Il était temps ! J'ai des clients qui attendent.\n\nDonnez-les-moi et faites bien attention, vous allez prendre votre première leçon dans votre carrière d'Armurier.", rewards = "Vous allez être la cible du sort suivant :\n\nArtisan forgeur d'armes\n\nVous recevrez :\n\n"},
[5301] = {title = "L'art de l'armurier", objective = "Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants puis les apporter à Okothos : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril.", description = "La satisfaction. C'est ce que je retire du marteau et de l'enclume. Voir un fier guerrier de la Horde protégé par mon acier me rappelle ce que signifie être vivant. C'est un besoin dont j'espère ne jamais avoir à me passer, <nom>.\n\nJe ne peux pas vous octroyer cette satisfaction, mais simplement vous placer sur son chemin. Comme toute tentative dans la vie, le chemin de la fabrique d'armures est un voyage.\n\nSi vous voulez faire partie des rares élus, vous n'avez besoin que de demander et je vous entraînerai. Mais tout d'abord, vous devez accomplir une certaine tâche.", progress = "Je frapperai l'acier jusqu'à mon tout dernier souffle.", completion = "C'est la dernière phase avant de commencer votre carrière de fabricant d'armures, &lt;nom&gt;. Si vous choisissiez d'abandonner, ce serait maintenant votre dernière chance. Sinon, préparez-vous à une vie de gloire.", rewards = "Vous allez être la cible du sort suivant :\n\nArtisan armurier\n\nVous recevrez :\n\n"},
[5302] = {title = "La voie du Forgeron d'armes", objective = "Pour devenir un Fabricant d'armes, vous devez fabriquer les éléments suivants et les rapporter à Borgosh : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires.", description = "Un jour, je créerai un marteau légendaire. Un marteau digne d'un chef de guerre !\n\nC'est le travail de toute une vie, <nom>. Ma passion. Je reconnais que vous avez le potentiel pour faire partie des nôtres, les fabricants d'armes. Je suis celui qui peut vous aider à exploiter ce potentiel.\n\nTout ce que vous avez à faire est de mener à bien une tâche simple. Plutôt facile pour quelqu'un qui a vos talents.", progress = "À la gloire de la Horde !", completion = "Ceci est l'ultime étape avant de commencer votre nouvelle carrière de fabricant d'armes, &lt;nom&gt;. Voudriez-vous y renoncer que cela serait votre dernière chance. Sinon, préparez-vous à être consumé par le savoir !", rewards = "Vous allez être la cible du sort suivant :\n\nArtisan forgeur d'armes\n\nVous recevrez :\n\n"},
[5303] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[5304] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[5305] = {title = "Douce sérénité", objective = "Aller jusqu’à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le ramener à Lilith.", description = "Dans les confins du Bastion écarlate se trouve la douce Sérénité. Le Forgeur de marteaux cramoisi garde ce secret de sa vie. Battez-le et apportez-moi son tablier. En échange, je vous enseignerai comment forger des marteaux.\n\nMais sachez bien ceci : une fois que vous aurez choisi de suivre cette voie, les arts de la forge d'épées ou de haches vous seront à jamais fermées.", progress = "Son tablier ! Où est-il ?", completion = "Vous êtes sûre que c'est ce que vous voulez ? Devenir un fabricant de marteaux ? Rappelez-vous, les portes des carrières de fabricant d'épées et de haches vous seront définitivement fermées.", rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant de marteaux\n\nVous recevrez :\n\nPlans : Marteau de guerre enchanté"},
[5306] = {title = "Pierre du serpent de la chasseresse des ombres", objective = "Aller jusqu’au Pic Blackrock et abattre la chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la ramener à Kilram.", description = "Ne laissez pas sa beauté vous duper, <classe>. La chasseresse des ombres, Vosh'gajin, est implacable et son esprit est dérangé.\n\n<Kilram désigne la cicatrice qu'il porte au visage.>\n\nOui, c'est elle qui m'en a fait cadeau. Une marque d'amour, pour employer ses termes.\n\nL'heure de la vengeance a enfin sonné.\n\nVous pouvez trouver Vosh'gajin au pic Blackrock. Tuez-la et rapportez-moi sa pierre du serpent. Accomplissez cet exploit et je vous enseignerai l'art de la fabrication des haches.", progress = "La légende dit que celui qui utilise la pierre du serpent de Vosh'gajin gardera sa hache affûtée comme un rasoir pendant mille ans !", completion = "Vous êtes sûr que c'est ce que vous voulez ? Devenir un fabricant de haches ? Rappelez-vous, les portes des carrières de fabricant d'épées ou de marteaux vous seront définitivement fermées.", rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant de haches\n\nVous recevrez :\n\nPlans : Courroux de l'aube"},
[5307] = {title = "Corruption", objective = "Trouver le Fabricant d'épées de la Garde noire à Stratholme et le tuer. Récupérer l’Insigne de la Garde noire et retourner auprès de Seril Scourgebane.", description = "Si je ne m'étends pas avec vous, j'ai une bonne raison. Les plans pour la création de la grande lame, Corruption, ont été volés par la Garde noire : des unités squelettes d'élite du baron Rivendare.\n\nOui, le baron Rivendare de Stratholme.\n\nLe fabricant d'épées de la Garde noire est maintenant en possession des plans avec sa... non-vie.\n\nTuez-le et rapportez-moi la preuve de votre exploit. Je vous enseignerai alors l'art de la fabrique d'épées.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant d’épées\n\nVous recevrez :\n\nPlans : Rapière flamboyante"},
[5321] = {title = "Le dormeur s'est éveillé", objective = "Escorter Kerlonian Evershade jusqu’à Liladris Moonriver au Poste de Maestra à Ashenvale.", description = "J'étais parti en direction du Poste de Maestra pour rencontrer Liladris Moonriver lorsque je décidai de m'arrêter et de me reposer un peu. Depuis que je me suis extirpé du Rêve d'émeraude, j'ai tout le temps sommeil…\n\n<bâille>\n\nAuriez-vous l'obligeance de me montrer le chemin ? Je crois que le Poste de Maestra est au sud, près de la route d'Ashenvale. Cela peut-être dangereux, j'espère que vous avez des amis pour nous accompagner.\n\nIl se peut que je m'endorme, alors pour me réveiller, utilisez ma corne, qui est dans ce coffre.", progress = "Kerlonian est-il arrivé ?", completion = "Oh je suis si heureux que Kelonian ait réussi ! Et je suis sûr de le trouver assoupi quelque part par ici, non ?\n\nMerci de lui avoir montré le chemin, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCarabine œil-de-chouetteBâton JadefingerBouclier de renforcement\n\nVous recevrez également :\n\n"},
[5341] = {title = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie.", description = "À l'intérieur de Scholomance réside la fortune de la famille Barov. Moi, Alexi Barov, suis l'un des deux derniers héritiers de la maison Barov. Mon frère, Weldon, est l'autre héritier.\n\nWeldon, ce misérable lâche, s'est enfui durant la guerre et est ainsi parvenu à maintenir son existence totalement inutile en tant qu'humain.\n\nIl recherche à présent les titres de propriété afin de récupérer la fortune pour lui tout seul. Retrouvez ces documents avant que mon frère n'y parvienne et je vous rendrai plus riche que vous n'avez jamais osé en rêver.", progress = "Inclinez-vous en ma présence, <nom>. Je suis noble, après tout, et vous n'êtes qu'un paysan impécunieux.", completion = "Excellent travail, &lt;nom&gt;. Maintenant, pour assurer ma succession…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5342] = {title = "Le dernier Barov", objective = "Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.\n\nAttention : Weldon sera probablement bien protégé par la racaille de l’Alliance.", description = "Évidemment, tant que mon frère est en vie, il se peut qu'il y ait quelques contentieux quant à l'identité du premier bénéficiaire de la fortune familiale. Cela n'est pas acceptable.\n\n<Un gamin/Une gamine> des rues de basse extraction <tel/telle> que vous ne devrait pas rechigner à l'idée d'effectuer un petit meurtre de sang-froid, n'est-ce pas ?\n\nIl s'agit là d'une tâche assez simple et j'entends bien que vous la réussissiez. Enfin, si vous souhaitez obtenir votre récompense...\n\nWeldon est sous la protection de l'Alliance à la pointe du Noroît, à l'est. Tuez-le, et apportez-moi sa tête.\n\n<Alexi bâille.>\n\nAllons, allons, pressons à présent.", progress = "Protégez ma fortune et partagez les profits.", completion = "Merveilleux ! Maintenant je détiens seul le pouvoir et la fortune de la maison Barov !\n\n&lt;Alexi vous jette un grand sac.&gt;\n\nEt gardez la monnaie, répugnant animal.", rewards = "Vous recevrez :\n\nCloche des Barov"},
[5343] = {title = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie.", description = "Mon cher frère Alexi. Quel idiot j'ai été de lui laisser la vie. J'ai vu le visage de l'ennemi, un mort-vivant, et je l'ai laissé vivre.\n\n<Weldon crache.>\n\nIl veut maintenant MON héritage. Cela ne se peut.\n\nTrouvez les titres de propriété de ma famille avant que cette ordure ne mette ses mains squelettiques dessus. Je vous récompenserai largement. Vous les trouverez dans les ruines de Scholomance. Faites vite !", progress = "Assurez mon avenir et j'assurerai le vôtre.", completion = "J'aurais encore une tâche à vous confier, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5344] = {title = "Le dernier Barov", objective = "Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.\n\nAttention : Alexi sera probablement bien protégé par les vandales de la Horde.", description = "À présent que j'ai les documents, il ne reste plus qu'une chose à faire. Alexi doit être tué. Une fois qu'il sera mort, je n'aurai plus à m'inquiéter qu'un gang de mercenaires véreux s'en prennent à moi. Alexi se cache sous la protection de la Horde, à la Barricade.\n\nNon, je ne m'attends pas à ce que vous y alliez simplement et que vous le tuiez... je veux sa tête, et comment vous l'obtiendrez... eh bien, c'est à vous de voir. Ma noble éducation m'empêche de m'attarder sur de si basses considérations.", progress = "Vous voulez être payé, n'est-ce pas ?", completion = "Quel jour de gloire ! Enfin, la vérole de la maison Barov est éradiquée et ma fortune en sécurité !\n\nPrenez ceci et hors de ma vue, paysan.", rewards = "Vous recevrez :\n\nCloche des Barov"},
[5361] = {title = "Arbre familial", objective = "Apporter le Rapport du garde-falaise Longhorn à Nataka Longhorn au poste de Rôdeur-fantôme en Désolace.", description = "Mon frère Nataka se trouve au poste de Rôdeur-fantôme, en Désolace. J'aimerais vous demander… Pourriez-vous lui remettre ce rapport pour moi ? Une année s'est écoulée depuis la dernière fois que j'ai écrit, et depuis, l'activité des centaures s'est beaucoup accrue. Il doit en être informé.\n\nVoyagez vers les Serres-Rocheuses, au nord de la Croisée, puis dirigez-vous vers l'ouest pour atteindre le Val Calciné. À partir de là, allez au sud vers Désolace. Vous trouverez alors une route vers le sud et vers le poste de Rôdeur-fantôme.", progress = "Quelles nouvelles apportez-vous, <classe> !  Ah, un message de mon frère, dites-vous ? Eh bien, donnez-moi ce rapport !", completion = "J'ignore ce qui vous lie à mon frère, mais il semble qu'il ait confiance en vous, &lt;classe&gt;.\n\nJe suis Nataka Longhorn et je voudrais vous souhaiter la bienvenue au poste de Rôdeur-fantôme, nous avons grand besoin de quelqu'un comme vous, &lt;classe&gt; ! Parlez avec les autres, il y a certainement quelqu'un ici qui a besoin de votre aide.", rewards = "Vous recevrez :\n\n"},
[5381] = {title = "La Main d'Iruxos", objective = "Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Wisemane, à Proie-de-l'Ombre.", description = "La Lame ardente possède la Boîte démoniaque qui renferme la puissante Main d'Iruxos. Il l'utilise pour ouvrir des portails démoniaques du convent de Mannoroc. Nous devons arrêter la vague de démons qui déferle sur notre monde, <nom> !\n\nUtilisez cette Pioche démoniaque sur le cristal rouge dans la forteresse de Hache-Tonnerre pour obtenir l'accès à la Boîte démoniaque.", progress = "<nom>, avez-vous la Boîte démoniaque ?", completion = "Ah la Boîte démoniaque ! Donnez-la-moi, &lt;classe&gt;, je l'ouvrirai... et je vous montrerai la Main d'Iruxos.", rewards = "Vous recevrez :\n\n"},
[5382] = {title = "Docteur Theolen Krastinov, le boucher", objective = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie.", description = "Krastinov est responsable de la mort de milliers d'innocents. Il doit être puni, justice doit être faite.\n\nTrouvez-le et faites-lui subir toutes les souffrances qu'il a lui-même infligées à ces innocents. Lorsque vous l'aurez détruit, brûlez nos restes. Qu'il n'en reste que des cendres, <nom>.", progress = "Le Boucher doit être arrêté !", completion = "Je sens mon esprit se régénérer, &lt;nom&gt;. Vous nous avez rendu un fier service à mon mari et à moi, mais je suis certaine qu'il y a plus à faire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5383] = {title = "Sac des horreurs de Krastinov", objective = "Apportez le Sac des horreurs à Eva Sarkhoff, à Caer Darrow.\n\nObjet fourni : \n", description = "Vous ouvrez le sac et découvrez divers instruments de torture. Au milieu de cet attirail, un objet insolite attire votre regard : une fiole de sang, encore chaude au toucher.\n\nVous pensez que les Sarkhoff pourraient être intéressés par votre découverte.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5384] = {title = "Kirtonos le héraut", objective = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.\n\nCombattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.", description = "Et voilà, <nom>.\n\n<Eva montre la fiole dans le sac.>\n\nLe sang d'innocents. Le sang le plus pur, utilisé pour apaiser le maître de Krastinov.\n\nC'est avec ce sang que Kirtonos peut être invoqué. C'est donc avec ce sang que Kirtonos doit être détruit.\n\nAllez sous le porche et placez le sang sur le brasero. Kirtonos viendra ; il ne peut résister. Lorsqu'il apparaîtra, déchaînez la furie et la colère de milliers d'innocents, morts à cause de lui.\n\nSi vous réussissez, vous gagnerez plus que notre simple gratitude.", progress = "Soyez prudent, Kirtonos est un combattant aguerri.", completion = "Avec la mort de Kirtonos, un chapitre de la macabre histoire de Scholomance arrive à son terme. Il y a cependant encore beaucoup à accomplir. D'autres ont eu vent de vos actes héroïques. Prenez ceci, &lt;nom&gt;. C'est une parcelle de notre propre essence. Elle vous permettra de communiquer avec les autres âmes égarées de Caer Darrow.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRose de PénélopeChanson de Mirah\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nEssence spectrale"},
[5385] = {title = "Les restes de Trey Lightforge", objective = "Rapporter le Cadavre de Trey Lightforge à Jessir Moonbow dans Gangrebois.", description = "Vous ramassez le sac avec précaution et vous vous apprêtez à reprendre votre chemin pour rejoindre Jessir Moonbow, à la frontière de Gangrebois et Ashenvale. Heureusement, le paladin recevra les honneurs qui lui sont dus une fois que vous aurez confié ses restes à ses amis.", progress = "Comment cela s'est-il passé à Jaedenar, <nom> ?", completion = "Vous avez réussi ! Gloire à Elune et à tout ce que vous pouvez vénérer, &lt;nom&gt;. Vous avez accompli un acte noble et honorable ce jour. Je suis sûr que Arko'narin sera ravie que vous ne l'ayez pas seulement sauvée, mais qu'aussi vous ayez tué la créature qui a torturé un de ses meilleurs amis.\n\nJ'aimerais pouvoir faire plus pour vous, mais, s'il vous plaît, prenez ceci.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nDague de poursuiteEpée Tidecrest\n\nVous recevrez également :\n\n"},
[5386] = {title = "La prise du jour", objective = "Parler à Jinar'Zillen à Proie-de-l'Ombre, puis amener 2 poissons Ventre-rouge à Nataka Longhorn.", description = "Cela fait longtemps qu’on n’a pas senti l’odeur du poisson cuit ici au poste de Rôdeur-fantôme. Les trolls de Proie-de-l'Ombre sont les meilleurs pêcheurs... Mais malheureusement, avec tous ces centaures, je n'ai plus le temps d'aller voir les trolls. Hum...\n\nRendez-moi service et allez à Proie-de-l'Ombre. Parlez au pêcheur Jinar'Zillen et rapportez-moi mon poisson favori, du Ventre-rouge. La route au sud d’ici vous mènera à l’ouest jusqu’au village des trolls.", progress = "Mon sabot me démange et j'ai l'eau à la bouche quand je pense à du Ventre-Rouge frit… Vous en avez sur vous ?", completion = "Vous êtes mon sauveur, &lt;nom&gt; ! Ces poissons Ventre-rouges semblent assez bon pour être mangés crus.\n\n\n\nVoici : prenez l'un de ces objets en paiement pour ces poissons.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMinerai de mithrilCuir épaisEtoffe de tisse-mage\n\nVous recevrez également :\n\n"},
[5401] = {title = "Brevet de l'Aube d'argent", objective = "Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.\n\nLorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.\n\nAccomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrevet de l'Aube d'argent"},
[5402] = {title = "Pierres du Fléau des serviteurs", objective = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureuse d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", description = nil, progress = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureuse d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", completion = "Félicitations, &lt;nom&gt; - Je suis heureuse de vous remettre cette marque de valeur de l'Aube d'argent !\n\nCes marques ont deux usages. Un - elles peuvent être utilisées pour augmenter votre statut au sein de l'Aube d'argent ; elles vous octroient des choix et des récompenses réservés à nos alliés honorés et révérés. Deux - elles peuvent être échangées auprès de nos intendants, avec des pièces, pour obtenir des articles de l'Aube d'argent de grande valeur.\n\nQuoi que vous décidiez, sachez que votre brevet est bien mérité. Bravo !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5403] = {title = "Pierres du Fléau des envahisseurs", objective = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", description = nil, progress = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", completion = "Félicitations, &lt;nom&gt; - je suis heureux de vous donner une marque de valeur de l'Aube d'argent !\n\nChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l'Aube d'argent sera assurément en bonne position quand le temps sera venu de porter l'attaque ultime contre le Fléau. J'espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5404] = {title = "Pierres du Fléau des corrupteurs", objective = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", description = nil, progress = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", completion = "Félicitations, &lt;nom&gt;. Je suis heureux de vous attribuer une marque de valeur de l'Aube d'argent !\n\nRecevoir une marque de valeur de telle manière prouve que vous êtes un véritable héros au service du bien. Nous apprécions tous les efforts fournis dans la lutte contre le Fléau, mais abattre l'un de ses chefs est vraiment leur infliger une terrible défaite !\n\nPour l'Aube d'argent, mon frère !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5405] = {title = "Brevet de l'Aube d'argent", objective = "Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.\n\nLorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.\n\nAccomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrevet de l'Aube d'argent"},
[5406] = {title = "Pierres du Fléau des corrupteurs", objective = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", description = nil, progress = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", completion = "Félicitations, &lt;nom&gt;. Je suis heureux de vous attribuer une marque de valeur de l'Aube d'argent !\n\nRecevoir une marque de valeur de telle manière prouve que vous êtes un véritable héros au service du bien. Nous apprécions tous les efforts fournis dans la lutte contre le Fléau, mais abattre l'un de ses chefs est vraiment leur infliger une terrible défaite !\n\nPour l'Aube d'argent, mon frère !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5407] = {title = "Pierres du Fléau des envahisseurs", objective = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", description = nil, progress = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", completion = "Félicitations, &lt;nom&gt; - je suis heureux de vous donner une marque de valeur de l'Aube d'argent !\n\nChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l'Aube d'argent sera assurément en bonne position quand le temps sera venu de porter l'attaque ultime contre le Fléau. J'espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5408] = {title = "Pierres du Fléau des serviteurs", objective = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", description = nil, progress = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", completion = "Félicitations, &lt;nom&gt; - Je suis heureux de vous remettre cette marque de valeur de l'Aube d'argent !\n\nCes marques ont deux usages. Un - elles peuvent être utilisées pour augmenter votre statut au sein de l'Aube d'argent ; elles vous octroient des choix et des récompenses réservés à nos alliés honorés et révérés. Deux - elles peuvent être échangées auprès de nos intendants, avec des pièces, pour obtenir des articles de l'Aube d'argent de grande valeur.\n\nQuoi que vous décidiez, sachez que votre brevet est bien mérité. Bravo !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5421] = {title = "Poisson dans un seau", objective = "Je récompense ceux qui me facilitent la vie… J'aime en faire le moins possible, mon ami !\n\nSous les quais de Proie-de-l'Ombre, j'ai placé de nombreux casiers à crustacés. Si vous avez la gentillesse de faire mon travail à ma place et de relever les casiers, je vous récompenserai en vous donnant quelque chose que vous voulez... Voyez où je veux en venir, l'ami ? Je vous donnerai un beau Ventre-Rouge pour 5 crustacés rapportés !", description = nil, progress = "Je récompense ceux qui me facilitent la vie… J'aime en faire le moins possible, mon ami !\n\nSous les quais de Proie-de-l'Ombre, j'ai placé de nombreux casiers à crustacés. Si vous avez la gentillesse de faire mon travail à ma place et de relever les casiers, je vous récompenserai en vous donnant quelque chose que vous voulez... Voyez où je veux en venir, l'ami ? Je vous donnerai un beau Ventre-Rouge pour 5 crustacés rapportés !", completion = "Ah… Rien ne vaut le travail bien fait, surtout lorsqu'il est fait par un autre…hein ?", rewards = "Vous recevrez :\n\nVentre-rouge"},
[5441] = {title = "Les péons paresseux", objective = "Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu’ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.", description = "Maudits péons ! Ils disent qu'ils travaillent dur pour ramasser du bois de charpente dans la vallée, mais ils font sans arrêt la sieste ! J'ai besoin de quelqu'un pour les remettre sur le droit chemin.\n\nVous me semblez être la bonne personne pour cette tâche, <race>. Prenez cette matraque et utilisez-la sur les péons paresseux que vous trouverez en train de dormir sur leur lieu de travail. Ça leur redonnera le goût de l'effort ! Rendez-moi la matraque quand vous aurez fini.\n\nPéons flemmards et glandeurs...", progress = "Paresseux… bons à rien...\n\nHein ? Vous avez ma masse ? Vous avez surpris des péons en train de dormir au lieu de travailler ?!", completion = "Bien, bien… Peut-être qu'ils y réfléchiront à deux fois la prochaine fois ! Merci de votre aide !", rewards = "Vous recevrez :\n\n"},
[5461] = {title = "L'humain, Ras Murmegivre", objective = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke.", description = "Les morts-vivants craignent la vie tout autant que les vivants craignent la mort. Il n'est pas inhabituel qu'un mort-vivant conscient détruise tous les restes de sa vie précédente une fois qu'il est dans son nouvel état.\n\nMalheureusement, afin de créer un artefact capable de rendre à Ras Murmegivre sa vie antérieure, vous devez être en possession d'un souvenir de ses années passées parmi les vivants.\n\nVous devez vous aventurer dans la cité en ruines de Stromgarde, la demeure de Murmegivre, et rechercher un tel objet. Puisse la chance vous accompagner, <nom>.", progress = "Un souvenir de mémoire est une prise rare, <nom>.", completion = "Je doutais de l'existence d'un tel objet. Cela ouvre sans doute d'incroyables opportunités - de celles qu'on ne peut gaspiller.\n\nPréparez-vous, &lt;nom&gt;, car ce que je vais vous demander va vous projeter dans les entrailles de l'enfer.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5462] = {title = "Le moribond, Ras Murmegivre", objective = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert.", description = "Le souvenir doit être harmonisé sur un sol corrompu.\n\nOn raconte que Stratholme est l'endroit où Murmegivre a succombé au roi-liche. Il a offert sa vie, librement et de son gré, pour devenir un mort-vivant sur cette terre ensanglantée.\n\nC'est cette terre que l'on doit retrouver.\n\nIl se trouverait quelqu'un... un dissident mort-vivant du Fléau, libéré par la reine-banshee mais loyal à la cause de l'Aube d'Argent. Trouvez-le. Il se nomme Leonid Barthalomew le Révéré, et il se peut qu'il en sache davantage. Recherchez l'Espoir de lumière, <nom>.", progress = "Ne posez pas de questions si vous ne voulez pas de réponses.", completion = "&lt;Leonid observe le souvenir de mémoire.&gt;\n\nVotre dilemme me rappelle des souvenirs que j'espérais ne voir jamais ressurgir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5463] = {title = "Le cadeau de Menethil", objective = "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie.", description = "J'ai vu l'humain, Ras Murmegivre, faire don de son âme éternelle au roi-liche. Il plaça sa propre dague sur sa gorge et, le sourire à la bouche, la trancha d'une oreille à l'autre. Son corps s'effondra dans le pentagramme. Le roi-liche se tint au-dessus de son corps et d'un simple geste, Ras Murmegivre la Liche naquit.\n\n<Le regard de Leonig s'égare sur le sol, puis revient à vous.>\n\nOui, <nom>, je m'en souviens. Ce que vous recherchez a un nom. Le Cadeau de Menethil. Le sol béni par le roi-liche. Un sol sacré pour le Fléau.", progress = "La région qui entoure le Don de Menethil est exceptionnellement froide.", completion = "Vous placez le souvenir de mémoire sur le sol maculé.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5464] = {title = "Le cadeau de Menethil", objective = "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est.", description = "L'esprit de celui qui est tombé se raccroche à ce qui représente son ancienne vie et transforme l'objet en un Souvenir lié. Vous récupérez l'objet et le placez dans votre sac.", progress = "<Leonid frissonne.>", completion = "Tout comme l'âme s'est attachée au souvenir de mémoire, elle s'attachera à la forme charnelle de Ras Murmegivre.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5465] = {title = "Souvenir lié", objective = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié.", description = "Retournez voir Marduke avec le Souvenir lié, <nom>. Il vous dira comment vous en servir.", progress = "Avez-vous fait l'impossible ?", completion = "J'étais certain que vous me rejoindriez comme un autre de ces esprits infortunés.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5466] = {title = "La Liche, Ras Murmegivre", objective = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.", description = "Il ne reste qu'une tâche à accomplir, <nom>. Affrontez la Liche, Ras Murmegivre, dans son antre.\n\nServez-vous du pouvoir du souvenir contre la bête. Soyez implacable dans vos actes ! Quels que soient les coups que la bête ne manquera pas de vous porter. Ne vous laissez pas arrêter par la douleur !\n\nUne fois le rituel achevé, Ras sera de nouveau mortel. Et c'est à ce moment qu'il devra être tué. Frappez-le et emparez-vous de sa tête humaine.", progress = "Vous portez le poids de dix mille âmes torturées, <nom>.", completion = "Dix mille âmes hurlent à l'unisson, &lt;nom&gt; ! Vous avez porté un coup fatal au Fléau et à ses maîtres.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de guerre de Caer DarrowCouronne de Caer DarrowDarrowspike\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nProtecteur du Darrowshire"},
[5481] = {title = "La tâche de Gordo", objective = "Récolter 3 herbes des ténèbres et les apporter à l’Apprenti Apothicaire Holland au cimetière de Brill.", description = "Maître veut herbes. Nous avoir grosses mains et pas bons à ramasser. Vous aider et nous pas vous faire mal. Nous avoir besoin d'herbe des ténèbres. Beaucoup alentours et près de route.\n\nQuand vous avoir beaucoup apporter à Maître Holland dans Cimetière de Brill.", progress = "Où est cette vaine abomination ? Soit vous avez ce dont j'ai besoin, soit vous feriez mieux de sortir et de la trouver.", completion = "Qu'est-ce que c'est ? De l'herbe des ténèbres ?! Je n'ai aucun besoin d'herbe des ténèbres ! Cette masse de chair écervelée est là dehors en train de cueillir des pâquerettes et de convaincre je ne sais combien de dupes dans votre genre de faire de même. Sans vous offenser.\n\nTrès bien, vous êtes là maintenant et c'est ce qui compte. Comme je ne prendrai pas la peine d'expliquer quoi que ce soit à cette abomination, je vous suggère de m'apporter ce dont j'ai vraiment besoin... de l'herbe maléfique !", rewards = "Vous recevrez :\n\n"},
[5482] = {title = "Herbe maléfique", objective = "Récolter 10 Herbes maléfiques et les apporter à l’apprenti apothicaire Holland.", description = "Ainsi vous comprenez la situation délicate dans laquelle je me trouve, <nom>. Cette chose est quelque part dehors en train de collecter les mauvaises herbes ! Si vous récupérez ce dont j'ai besoin, cela en vaudra la peine. Apportez-moi suffisamment d'herbes maléfiques et je vous remettrai une récompense conséquente.\n\nJe crois savoir qu'elles aiment dévaster la flore près des tombes au nord du cimetière de Brill. Hâtez-vous, et faites attention aux gnolls qui parcourent l'endroit.", progress = "Ça a intérêt à en valoir la peine. Je suppose que vous avez toutes les herbes damnées que j'ai demandées ?", completion = "Ah, mon herbe maléfique. Excellent !\n\n&lt;L'apprenti apothicaire Holland se frotte les mains avec satisfaction.&gt;\n\nElle va se révéler très utile. Vous m'avez... euh, vous avez rendu un fier service à la Dame, aujourd'hui, &lt;nom&gt;. Comme promis, voici la récompense que vous méritez.", rewards = "Vous recevrez :\n\n"},
[5501] = {title = "Collectionneur d'os", objective = "Apporter à Bibbly F'utzbuckle à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos.", description = "Nous sommes assis sur une mine d'or ici, je vous le dis ! Une mine d'or ! Les os de kodos changeront la face du monde pour toujours… J'ai des clients qui en font des meubles, des instruments de musique, et même des poudres explosives.\n\nUne caravane passe, ramasse les os et les vend à Proie-de-l'Ombre. Si vous pouvez voyager jusqu'au Cimetière des kodos au sud et m'apporter dix os de kodos, je vous donnerai quelque chose en contrepartie. C'est d'accord ?", progress = "Avez-vous les os ? La caravane sera là d'un instant à l'autre. Il me faut juste dix os de kodo supplémentaires pour atteindre un sommet dans ma carrière. Un sommet, je vous dis !", completion = "Ah, superbe ! Mes os !\n\nJe frémis d'impatience à l'idée que les gars de chez nous vont voir mon visage en première page de \"Valeurs gobelines\". Je serai le gobelin le plus riche du monde… et mon professeur d'éducation physique qui pensait que je n'arriverais jamais à rien.", rewards = "Vous recevrez :\n\nCollier en os de kodo"},
[5502] = {title = "Un surveillant de la Horde", objective = "Ramenez votre protégé à l'orphelinat d'Orgrimmar, en rendant le sifflet d'orphelin orc à la gouvernante de l'orphelinat, Battlewail, dans la Vallée de l'Honneur.", description = "Vous avez été très <gentil/gentille> avec moi, <nom>. Je n'aurais jamais pensé que je m'amuserais autant pendant la Semaine des Enfants. Merci. Je veux pas être triste, avec tout ce qui m'est arrivé... Mes parents me disaient toujours qu'il fallait surmonter les mauvaises choses qui nous arrivent. Je serai un héros, plus tard... comme vous.\n\nC'est triste de devoir revenir à l'orphelinat. Rentrons à la maison, et je dirai à la gouvernante que vous êtes une personne géniale !", progress = "C'est un plaisir de vous revoir, <nom>. Avez-vous pu accomplir les tâches pour lesquelles vous vous êtes porté volontaire pendant la Semaine des Enfants ?", completion = "Que les esprits vous bénissent, &lt;nom&gt;. Vous avez plus fait pour Grunth que la plupart des gens. Merci... Vous êtes le héros de la Horde par excellence.\n\nJe vous en prie, si vous en avez le temps, revenez nous voir de temps en temps. Je sais que Grunth en serait très heureux, et moi aussi.\n\nGrunth s'est si bien amusé avec vous, &lt;nom&gt;. Il voudrait vous donner l'un de ses familiers préférés pour que vous vous souveniez de lui.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCollier de porceletCage à ratBoîte à tortueRécompense du bougon\n\nVous recevrez également :\n\n"},
[5503] = {title = "Brevet de l'Aube d'argent", objective = "Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.\n\nLorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.\n\nAccomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrevet de l'Aube d'argent"},
[5504] = {title = "Les mantelets de l'aube", objective = "Apporter 10 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest", description = "Vos services envers l'Aube d'argent méritent d'être salués, <nom>. Vous êtes vraiment <révéré/révérée> parmi nous. J'ai été autorisé à vous laisser acheter l'un des objets les plus précieux de l'Aube d'argent - nos mantelets de résistance à la magie.\n\nPoser l'un de ces mantelets sur une pièce d'épaule existante améliore l'une de vos cinq résistances à la magie. En signe de votre dévotion à notre cause, je vous demande de me ramener dix Marques de valeur. En échange, vous aurez le mantelet.", progress = "Ah, noble <classe> ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, vous pourrez acheter l’un de nos mantelets.", completion = "Remarquable – ce tribut à l’Aube d'argent est dûment noté, &lt;nom&gt;. Maintenant que c’est chose faite, je suis enchanté de vous proposer nos mantelets. Tant que vous conserverez votre statut parmi nous, ces mantelets peuvent être achetés auprès de tout quartier-maître de l’Aube d'argent.\n\nPour l’Aube, mon frère !", rewards = "Vous recevrez :\n\n"},
[5505] = {title = "La clé de Scholomance", objective = "Et bien voilà, <nom> - la Clé squelette terminée. Je suis aussi certain que possible que cette clé vous permettra d'entrer dans les confins de Scholomance. Toutefois il n'y a qu'un moyen de vérifier son efficacité. Ne perdez pas de temps et essayez-la, c'est ce que je dis.\n\nBonne chance, puissant héros. Puissiez-vous continuer à apporter la lumière dans les ténèbres !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nClé squelette"},
[5507] = {title = "Les mantelets de l'aube", objective = "Apporter 10 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest.", description = "Vos services envers l'Aube d'argent méritent d'être salués, <nom>. Vous êtes vraiment <révéré/révérée> parmi nous. J'ai été autorisé à vous laisser acheter l'un des objets les plus précieux de l'Aube d'argent - nos mantelets de résistance à la magie.\n\nPoser l'un de ces mantelets sur une pièce d'épaule existante améliore l'une de vos cinq résistances à la magie. En signe de votre dévotion à notre cause, je vous demande de me ramener dix Marques de valeur. En échange, vous aurez le mantelet.", progress = "Ah, noble <classe> ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, vous pourrez acheter l’un de nos mantelets.", completion = "Remarquable – ce tribut à l’Aube d'argent est dûment noté, &lt;nom&gt;. Maintenant que c’est chose faite, je suis enchanté de vous proposer nos mantelets. Tant que vous conserverez votre statut parmi nous, ces mantelets peuvent être achetés auprès de tout quartier-maître de l’Aube d'argent.\n\nPour l’Aube, mon frère !", rewards = "Vous recevrez :\n\n"},
[5508] = {title = "Pierres du Fléau des corrupteurs", objective = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", description = nil, progress = "Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !\n\nAu nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance.", completion = "Félicitations, &lt;nom&gt;. Je suis heureux de vous attribuer une marque de valeur de l'Aube d'argent !\n\nRecevoir une marque de valeur de telle manière prouve que vous êtes un véritable héros au service du bien. Nous apprécions tous les efforts fournis dans la lutte contre le Fléau, mais abattre l'un de ses chefs est vraiment leur infliger une terrible défaite !\n\nPour l'Aube d'argent, mon frère !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5509] = {title = "Pierres du Fléau des envahisseurs", objective = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", description = nil, progress = "Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.\n\nL'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.", completion = "Félicitations, &lt;nom&gt; - je suis heureux de vous donner une marque de valeur de l'Aube d'argent !\n\nChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l'Aube d'argent sera assurément en bonne position quand le temps sera venu de porter l'attaque ultime contre le Fléau. J'espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5510] = {title = "Pierres du Fléau des serviteurs", objective = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur le plus faible de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", description = nil, progress = "Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur le plus faible de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.\n\nL'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau.", completion = "Félicitations, &lt;nom&gt; - Je suis heureux de vous remettre cette marque de valeur de l'Aube d'argent !\n\nCes marques ont deux usages. Un - elles peuvent être utilisées pour augmenter votre statut au sein de l'Aube d'argent ; elles vous octroient des choix et des récompenses réservés à nos alliés honorés et révérés. Deux - elles peuvent être échangées auprès de nos intendants, avec des pièces, pour obtenir des articles de l'Aube d'argent de grande valeur.\n\nQuoi que vous décidiez, sachez que votre brevet est bien mérité. Bravo !", rewards = "Vous recevrez :\n\nMarque de valeur de l'Aube d'argent"},
[5511] = {title = "La clé de Scholomance", objective = "Eh bien voilà, <nom> - la Clé squelette terminée. Je suis aussi certain que possible que cette clé vous permettra d'entrer dans les confins de Scholomance. Toutefois il n'y a qu'un moyen de vérifier son efficacité. Ne perdez pas de temps et essayez-la, c'est ce que je dis.\n\nBonne chance, puissant héros. Puissent vos victoires continuer de vous apporter gloire et pouvoir alors que vous semez la désolation à Scholomance !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nClé squelette"},
[5513] = {title = "Les mantelets de l'aube", objective = "Apporter 10 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est.", description = "Vos services envers l'Aube d'argent méritent d'être salués, <nom>. Vous êtes vraiment <révéré/révérée> parmi nous. J'ai été autorisée à vous laisser acheter l'un des objets les plus précieux de l'Aube d'argent - nos mantelets de résistance à la magie.\n\nPoser l'un de ces mantelets sur une pièce d'épaule existante améliore l'une de vos cinq résistances à la magie. En signe de votre dévotion à notre cause, je vous demande de me ramener dix Marques de valeur. En échange, vous aurez le mantelet.", progress = "Ah, noble <classe> ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, vous pourrez acheter l’un de nos mantelets.", completion = "Remarquable – ce tribut à l’Aube d'argent est dûment noté, &lt;nom&gt;. Maintenant que c’est chose faite, je suis enchantée de vous proposer nos mantelets. Tant que vous conserverez votre statut parmi nous, ces mantelets peuvent être achetés auprès de tout quartier-maître de l’Aube d'argent.\n\nPour l’Aube, mon frère !", rewards = "Vous recevrez :\n\n"},
[5514] = {title = "Moisissure rime avec…", objective = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.", description = "Le gobelin que vous devez aller voir s'appelle Krinkle Goodsteel. Dans le désert de Tanaris il a la réputation d’être dur en affaires. Il est probablement le seul qui puisse produire le moule dont nous avons besoin, et ses services ne seront pas donnés. Nous vous demandons de tout faire pour obtenir ce moule, quel qu’en soit le prix.\n\nJe suis alchimiste, pas banquier. Si je pouvais me rouler dans l'or, je ne serais certainement pas ici.\n\nJe sens que j'ai encore perdu mon calme. Oups...\n\nGadgetzan vous attend ! Bonne chance !", progress = "Oui, je sais qui vous êtes et pourquoi vous êtes ici. Dithers m'a prévenu avant que vous n'arriviez. Venons-en à l'affaire qui nous préoccupe, voulez-vous ?\n\nJ'ai un moule que vous pouvez utiliser pour la Clé squelette, mais il vous coûtera quinze pièces d'or, d'avance, non négociable. J'emballerai les fragments de squelette dans le moule pour vous, et je vous montrerai également comment forger la tige de la clé sans rien savoir de l'art de la forge... Et tout cela gratuitement, rien de moins.\n\nQui a dit que les mercenaires ne proposent pas de bonnes affaires ?", completion = "Dithers avait dit que vous livreriez les biens, et vous les avez bien livrés en effet ! Un marché est un marché ; laissez-moi envelopper les fragments dans la moisissure pour vous.\n\nDithers les a-t-il déjà imprégnés ? Excellent… cela aurait été un long chemin de retourner à la Muraille sinon.", rewards = nil},
[5515] = {title = "Sac des horreurs de Krastinov", objective = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff.", description = "Un grand poids a été ôté de nos coeurs, <nom>, mais votre travail n'est pas encore terminé. Le maître de Krastinov, Kirtonos, est toujours en vie.\n\nAvant que vous ne puissiez l'affronter, cependant, vous devez trouver une méthode pour l'invoquer.\n\nOn raconte que Jandice Barov apporte le sang d'innocents de Krastinov à Kirtonos.\n\nTrouvez-la dans les catacombes englouties de Scholomance et tuez-la. Rapportez tous les indices que vous pourriez trouver.", progress = "<Eva devient nette, puis floue.>", completion = "Le sac d'horreurs !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5517] = {title = "Le mantelet de l'aube Chromatique", objective = "Apporter 25 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est.", description = "<Frère/Soeur> <nom> – les services que vous avez rendu à l’Aube d'argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq marques de valeur de l’Aube d'argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.", progress = "Salutations, puissant <classe> ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, je vous donnerai votre Mantelet de l’aube Chromatique.", completion = "Très impressionnant, &lt;nom&gt; – le mantelet de l’Aube chromatique est à vous !\n\nTant que vous conserverez votre statut exalté au sein de l’Aube d'argent, vous pourrez acheter d’autres mantelets chromatiques. Ils sont disponibles à partir de maintenant auprès de tout quartier-maître de l’Aube d'argent.", rewards = "Vous recevrez :\n\nMantelet de l'Aube chromatique"},
[5518] = {title = "La tenue d'ogre gordok", objective = "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes.", description = "Si vous devez combattre le roi de cette décharge – et je pense que vous n’avez pas le choix – vous devrez vous occuper du capitaine Kromcrush. Oh, vous pouvez vous en « occuper » en le tuant, bien sûr. Mais vous pouvez aussi le laisser en vie.\n\nComment ? Eh bien, depuis le temps que je moisis ici, je pense que je saurais préparer un déguisement d’ogre qui durerait juste assez longtemps pour tromper ces clowns. Le seul problème est la stabilité. Il ne durera pas plus de dix minutes. Amenez-moi ce qu’il me faut, et je vous en ferai un. Je ne vais nulle part, de toute façon…", progress = "De tous les ingrédients dont j’ai besoin, le Tanin ogre est sans doute ce qu’il y a de plus dur à trouver. Je crois qu’ils en ont en haut. C’est difficile à dire, parce que ce boulet limite quelque peu mes mouvements…\n\nEn tout cas, dès que vous m’aurez apporté tout ce qu’il me faut, je vous fabriquerai une tenue qui convaincra le capitaine Kromcrush que vous êtes l’un de ses hommes. Enfin, l’un de ses ogres.", completion = "Oui, ça fera l’affaire. Un peu ici, une touche là… hé hé, ça ira très bien !&lt;Un grand sourire apparaît sur le visage du gobelin enchaîné.&gt;\n\nEt voilà, c’est prêt. Souvenez-vous quand même que ce n’est pas très solide. Vous avez dix minutes avant qu’il ne parte en morceaux. Après ça, vous ne tromperez plus personne ! Essayez de vous en servir juste avant de l’approcher, et souvenez-vous… il VOUS prendra pour un allié, mais ça ne s’applique pas à vos camarades !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTenue d'ogre gordok"},
[5519] = {title = "La tenue d'ogre gordok", objective = "Besoin d’une autre tenue, hein ? Bon, je ne vais nulle part, de toute façon. Amenez-moi les mêmes éléments que l’autre fois, et je vous en ferai une autre.", description = nil, progress = "Besoin d’une autre tenue, hein ? Bon, je ne vais nulle part, de toute façon. Amenez-moi les mêmes éléments que l’autre fois, et je vous en ferai une autre.", completion = "Voilà qui est fait, &lt;nom&gt;. Mettez ce truc, et vous aurez dix minutes pour faire ce que vous voulez. Bonne chance.\n\nOh, si par hasard vous tombez sur la clé qui me permettra de sortir d’ici, N’HESITEZ SURTOUT PAS A ME LE FAIRE SAVOIR !", rewards = "Vous recevrez :\n\nTenue d'ogre gordok"},
[5521] = {title = "Le mantelet de l'Aube chromatique", objective = "Apporter 25 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest.", description = "<Frère/Soeur> <nom> – les services que vous avez rendu à l’Aube d'argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq Marques de valeur de l’Aube d'argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet de l'Aube chromatique"},
[5522] = {title = "Leonid Barthalomew", objective = "Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est.", description = "J'ai reçu un message de mon maître, Vectus. En fait, le message n'était pas vraiment de Vectus… mais de quelqu'un nommé Leonid Barthalomew. J'ignore qui est Leonid, mais il connaissait mon maître et cela n'est possible que si ce dernier l'a bien voulu.\n\nLeonid dit que Vectus veut les oeufs de dragon. Il veut que vous les lui apportiez à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est.\n\nJe suis peinée ! Pourquoi vous ? Vectus n'a pas confiance en moi ? Allez, oublions cela, prenez les oeufs et dites à Leonid que j'ai fait ce que notre maître demandait.", progress = "Vous êtes celui qui sème le trouble au pic Blackrock, n'est-ce pas ? Avez-vous ce que je vous ai demandé ?", completion = "Ah, très bien ! Vous ne connaissez pas la puissance maléfique pour laquelle vous avez oeuvré, mais vous allez désormais savoir la vérité. N'ayez crainte, je ne suis pas un serviteur de ce maître. Je suis Leonid Barthalomew, connu comme \"le Révéré\" par les miens et au sein de l'Aube d'argent.\n\nJ'ai trompé Tinkee en lui faisant vous envoyer à moi avec ces oeufs de dragon. Il est heureux que ma ruse ait fonctionné, car si ces oeufs avaient atteint leur destination prévue, une grande puissance serait tombée aux mains de l'ennemi.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5524] = {title = "Le mantelet de l'Aube chromatique", objective = "Apporter 25 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest.", description = "<Frère/Soeur> <nom> – les services que vous avez rendu à l’Aube d'argent sont trop nombreux pour être résumés facilement. En récompense, je vais me séparer de l’un de nos mantelets de l’Aube chromatique – une version qui protège le porteur de toutes les formes de magie auxquelles il est possible de résister. Les mantelets chromatiques ne sont octroyés qu’aux plus grands héros de notre organisation ! Ramenez-moi vingt-cinq Marques de valeur de l’Aube d'argent en signe de tribut et je vous donnerai le meilleur de nos mantelets.", progress = "Salutations, puissant <classe> ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, je vous donnerai votre mantelet de l’Aube chromatique.", completion = "Très impressionnant, &lt;nom&gt; – le mantelet de l’Aube chromatique est à vous !\n\nTant que vous conserverez votre statut exalté au sein de l’Aube d'argent, vous pourrez acheter d’autres mantelets chromatiques. Ils sont disponibles à partir de maintenant auprès de tout suartier-maître de l’Aube d'argent.", rewards = "Vous recevrez :\n\nMantelet de l'Aube chromatique"},
[5525] = {title = "Libérez Knot !", objective = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…\n\nMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?", description = nil, progress = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…\n\nMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?", completion = "Vous – vous êtes numéro un. Tous les autres sont numéro deux – ou moins. Merci de m’avoir libéré !\n\nJe savais que j’avais autre chose à faire de ma vie que de servir d’apéritif à un ogre !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5526] = {title = "Fragment de la Gangrevigne", objective = "Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit.", description = "Votre connaissance d’Eldre’Thalas en Feralas – Hache-tripes – va nous servir, <nom>. Dans la partie orientale de cette ville en ruine, Alzzin le Modeleur s’est créé un domaine de corruption. Allez-y et affrontez les menaces qui vous y attendent.\n\nLe Fruit de Fertilité, devenu la Gangrevigne, doit se trouver à proximité d’Alzzin. Après sa défaite, capturez l’essence de la Gangrevigne, dans la mesure du possible. Enfermez-la dans ce Reliquaire et ramenez-la moi.\n\nBonne chance, et puisse Cénarius veiller sur vous !", progress = "Maitenant que le Reliquaire de Pureté Scellé est en votre possession, il est non seulement possible de neutraliser un facteur de corruption, mais aussi de l’étudier, avec toute la prudence requise. Peut-être parviendrons-nous à découvrir de nouveaux moyens de combattre la corruption qui menace sans cesse Azeroth.\n\nJe sais c’est ce qu’aurait voulu Milli…", completion = "C’est fait, brave &lt;classe&gt;, et le Cercle cénarien a une dette envers vous. La guerre est loin d’être terminée, mais nous avons remporté une grande victoire contre ceux qui nous conduiraient à notre perte.\n\nS’il vous plaît, acceptez ceci en signe de gratitude. Sachez aussi que vous serez toujours le bienvenu ici, et que pour cette action, vous serez considéré comme un héros du Cercle cénarien, &lt;nom&gt;. Merci.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBouclier de MilliLexique de Milli\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5527] = {title = "Un reliquaire de pureté", objective = "Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune.", description = "La première étape consiste à trouver un récipient capable de contenir une substance extrêmement corrompue sans que son porteur souffre d’effets secondaires. Les seuls objets qui, à ma connaissance, puissent retenir quelque chose d’aussi vil que la gangrevigne sont les reliquaires de pureté.\n\nTrès loin dans les terres désertées de Silithus se trouvent les vestiges d’un village d’elfes de la nuit nommé Sudevent. Je sais qu’un reliquaire s’y trouvait, il y bien des années. Si nous devons réussir, j’ai besoin que vous exploriez ces ruines dans l’espoir de le retrouver.", progress = "Un Reliquaire de Pureté est lui-même un objet puissant. Fort peu ont été fabriqués, et avec le temps, ils ont presque tous disparu.\n\nJe connais l’existence de celui de Sudevent depuis quelque temps déjà. Honnêtement, avec tout ce qui se passe en Silithus, je pensais garder le secret plus longtemps. Aller fouiller là-bas risque d’attiser les soupçons de nos ennemis.\n\nHélas, la situation à Eldre’Thalas étant ce qu’elle est, le temps de la complaisance est révolu.", completion = "En vérité, vous êtes plein de ressources ! Le Cercle cénarien est béni de vous compter parmi ses agents.\n\nMaintenant que le Reliquaire est entre mes mains, mon esprit est en repos. Je me sens plus à l’aise pour vous demander de faire face à un démon malfaisant tout en me ramenant un objet dangereux.", rewards = "Vous recevrez :\n\n"},
[5528] = {title = "La dégustation gordok", objective = "V’z’êtes le grand patron maintenant, alors z’avez le droit de goûter mes alcools. Ils rendent fort ET font tourner la tête ! C’est d’la bonne, chef… essayez, vous pourrez l’dire à Kreeg !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGrog vert gordokBière-massue de Kreeg"},
[5529] = {title = "Portée contaminée", objective = "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière.", description = "L'Aube d'argent a récemment appris que le Fléau est en train de concevoir sa propre unité de dragons ! Nous devons les arrêter. Si le Fléau parvient à maîtriser la force des dragons, Azeroth se verra submergée sans que rien ne puisse les retenir !\n\nLeurs nécromanciens en font l'élevage à la Scholomance, au milieu du lac Darrowmere.\n\nAllez-y et réduisez autant que possible la couvée, avant qu'ils ne grandissent !", progress = nil, completion = "Beau travail, &lt;nom&gt; ! Ils mettront du temps avant de produire une nouvelle couvée de dragons. \n\n… Du moins je l'espère !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5531] = {title = "Betina Bigglezink", objective = "Apporter les Oeufs congelés à Betina Bigglezink.", description = "Les oeufs que vous avez apportés devaient faire l'objet de recherches par le Fléau pour créer des dragons pestiférés. Ces oeufs gelés de dragons noirs auraient été d'une grande valeur pour leurs études et leur auraient fait gagner du temps.\n\nIl est temps de mettre fin à leurs recherches.\n\nPrenez les oeufs gelés à Betina Bigglezink. C'est une spécialiste en sciences et alchimie. Elle a fabriqué une arme que nous pouvons utiliser contre le Fléau. Grâce à votre aide, nous pouvons leur porter un coup sévère.", progress = "Salut, <nom> ! J'ai appris que vous aviez des oeufs de dragon ? Eh bien, voyons cela !", completion = "Les voici ! Et dans une si belle enveloppe. La taille parfaite !\n\nNous garderons ces oeufs dans un endroit sûr en attendant de pouvoir les étudier, mais nous avons dans l'immédiat besoin de cette chose dans laquelle vous les avez portés.\n\nJ'ai créé un appareil dont l'usage est très spécifique : détruire les sages morts-vivants de Scholomance. Ils étudient les dragons afin de créer un escadron contaminé, et nous devons les en empêcher.\n\nJ'ai nommé l'objet le Gambit de l'Aube car... je ne sais pas s'il fonctionne !\n\nLe découvrirez-vous pour nous ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5533] = {title = "Scholomance", objective = "Parler à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.", description = "Sur l'île de Caer Darrow, se trouve Scholomance, un centre de nécromancie et de maléfismes du Fléau. Notre ennemi y est installé, perpétuant des actes infâmes sur des victimes innocentes… du moins, c'est ce que nous croyons. Une porte barre le chemin, et malgré tous nos efforts, si nous n'avons pas la bonne clé, nous ne pourrons pas entrer.\n\nArbington l'alchimiste connaît bien Scholomance et il sait comment obtenir une clé. Puisque vous avez fait vos preuves, je vous confie cette mission. Parlez-lui de cette affaire.", progress = nil, completion = "Enchanté, &lt;classe&gt;. J'ai consacré une bonne partie de mes récentes études à Scholomance, et je crois avoir découvert un moyen pour vous d'obtenir une clé… Une clé qui vous fera franchir la première porte.\n\nJe ne puis qu'imaginer les visions d'horreur que l'intérieur recèle, &lt;nom&gt;. Je me demande parfois comment vous faites, vous, les héros...", rewards = "Vous recevrez :\n\n"},
[5534] = {title = "L'équipement \"manquant\" de Kim'jael", objective = "Trouver \"une rune\" détenue par les nagas dans les ruines d’Eldarath et la rapporter à Kim'jael à Azshara.", description = "Quoi ?! Quoi !\n\nCe n'était pas assez bien pour vous ? Vous savez combien coûtent ces explosifs ? A peu près… oh, et puis laissez tomber. Bon, vous voulez vraiment vous faire de l'argent ? Parce que c'est comme ça que ça  marche : vous faites vos preuves et vous êtes récompensé de manière adéquate.\n\nSi vous êtes vraiment un employé \"inestimable\", allez dans les ruines d'Eldarath et trouvez-moi une rune que recherchent ces satanés elfes. Les nagas l'ont apparemment en leur possession.", progress = "Eh bien, <nom> ? Où est la rune ? Vous êtes un bon employé, n'est-ce-pas ? Vous êtes là pour aider ?\n\nNe me laissez pas douter de l'opportunité de vous payer ce dont nous étions convenus. Comment ? Oh, nous n'avions aucun accord ? Oh, parfait… alors prenez votre temps. Sachez simplement que la somme sera plus légère si vous prenez beaucoup de temps.", completion = "Ha ha ! Merveilleux !\n\nJe suis sûr de trouver à quoi cela sert et pourquoi la magus Rimtori (c'est la punaise qui m'a embauché) courait derrière. Ha ! Je vous tiens maintenant, sales elfes de sang ! Kim'jael ! Ha ! Je leur apprendrai qui sont les rats !\n\nVous avez bien fait, &lt;nom&gt;. Merci beaucoup. Voici, prenez cette pièce et laissez-moi, j'ai à réfléchir.", rewards = "Vous recevrez :\n\n"},
[5535] = {title = "Agitation spirituelle", objective = "Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu à Azshara.", description = "Il y a longtemps, les Bien-nés étaient les plus doués des elfes de la nuit dans le domaine des arcanes. La corruption qui accompagne ces études causa beaucoup de tort à la société des elfes de la nuit et affecta grandement tout Azeroth...  Mais vous le savez certainement déjà.\n\nJ'ai promis aux Sentinelles que je libérerai les esprits de leurs attaches mortelles dès que je les trouverai. Si vous pouviez faire de même, alors je vous récompenserai.\n\nLes esprits hantent le sanctuaire de Shadowsong au nord-est d'ici.", progress = nil, completion = "Bien joué, &lt;classe&gt;. Merci de votre aide. Les esprits sont apaisés, et leur désir pour l'attrait de l'arcane est retombé.\n\nJe suis certain que les deux opposants dans ce conflit pour Azeroth verront que vous êtes au-dessus de cela.", rewards = "Vous recevrez :\n\n"},
[5536] = {title = "Un pays plein de haine", objective = "Tuer 6 satyres Haldarr, 2 Entourloupeurs Haldarr, 2 Lige de la corruption Haldarr puis revenir auprès de Loh'atu à la frontière d’Ashenvale.", description = "Les satyres, êtres difformes et maléfiques issus des elfes de la nuit, souillent désormais les terres sacrées où Cénarius se promenait jadis. Je ne peux parler à la place des elfes de la nuit de toutes les atrocités que ces créatures démoniaques ont pu commettre, mais j'ai fait le serment à la Terre-mère d'aider les elfes à se débarrasser des satyres.\n\nMontrez-moi ce dont vous êtes capable en m'aidant à les éliminer.\n\nAu nord-est d'ici, vous trouverez le clan Haldarr. Revenez me voir lorsque vous aurez éprouvé votre pouvoir contre eux.", progress = "Comment se déroule votre combat contre les satyres, <classe> ?\n\nSont-ils aussi forts que vous le pensiez ? Plus forts ? Ou peut-être ne sont-ils pas à la mesure de votre propre force.", completion = "Bien joué, &lt;classe&gt;. Je vois que votre adresse se double de subtilité. Battre de telles créatures est la preuve de votre loyauté à la Terre-mère, même si vous ne la reconnaissez pas comme votre déesse. Elle est dans toutes choses sur cette planète et au-delà. Ses yeux, un sombre et un clair, voyagent parmis les nuages, toujours attentifs à nos actes.\n\nS'il vous plaît, acceptez ces quelques pièces en récompense pour ce que vous avez fait.", rewards = "Vous recevrez :\n\n"},
[5537] = {title = "Fragments de squelette", objective = "Apporter 15 Fragments de squelette à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.", description = "La clé pour accéder à Scholomance s'appelle une Clé squelette. Elle doit être forgée à partir des restes d'un squelette - de plusieurs en fait - et doit être renforcée des métaux les plus robustes dans un moule particulier. Enfin, un sceau de pouvoir provenant d'une créature naturellement capable d'ouvrir le portail de Scholomance permettra à la clé d'avoir la fonction désirée.\n\nMais commençons par le commencement, <nom>. Nous allons avoir besoin de Fragments de squelette pour forger la clé. Les squelettes d'Andorhal devraient nous les fournir, mais ceux en dehors des murs devraient pouvoir faire l'affaire également.", progress = "Aussi morbide que cela paraisse, il nous faudra un stock suffisant de fragments de squelettes pour faire la couche extérieure de la clé. Ils n'appellent pas ça Clé squelette pour rien, vous savez.", completion = "Ça va marcher, &lt;nom&gt; ! À mon tour maintenant : je vais les imprégner d'un agent durcissant qui leur permettra de résister au processus intense de forge qu'ils auront à subir.\n\nLa prochaine étape sera de trouver un moule approprié pour la clé. Je connais un forgeron gobelin à Tanaris qui a fait, dans le passé, des moules pour des objets macabres semblables. Il travaille, à l'instar de tous les gobelins, pour celui qui paye le plus.", rewards = "Vous recevrez :\n\n"},
[5538] = {title = "Moisissure rime avec…", objective = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.", description = "Le gobelin que vous devez aller voir s'appelle Krinkle Goodsteel. Dans le désert de Tanaris il a la réputation d’être dur en affaires. Il est probablement le seul qui puisse produire le moule dont nous avons besoin, et ses services ne seront pas donnés. Nous vous demandons de tout faire pour obtenir ce moule, quel qu’en soit le prix.\n\nJe suis alchimiste, pas banquier. Si je pouvais me rouler dans l'or, je ne serais certainement pas ici.\n\nJe sens que j'ai encore perdu mon calme. Oups...\n\nGadgetzan vous attend ! Bonne chance !", progress = "Oui, je sais qui vous êtes et pourquoi vous êtes ici. Arbington m'a prévenu avant que vous n'arriviez. Venons-en à l'affaire qui nous préoccupe, voulez-vous ?\n\nJ'ai un moule que vous pouvez utiliser pour la Clé squelette, mais il vous coûtera quinze pièces d'or, d'avance, non négociable. J'emballerai les fragments de squelette dans le moule pour vous, et je vous montrerai également comment forger la tige de la clé sans rien savoir de l'art de la forge... Et tout cela gratuitement, rien de moins.\n\nQui a dit que les mercenaires ne proposent pas de bonnes affaires ?", completion = "Arbington avait dit que vous livreriez les biens, et vous les avez bien livrés en effet ! Un marché est un marché ; laissez-moi envelopper les fragments dans le moule pour vous.\n\nDithers les a-t-il déjà imprégnés ? Excellent… cela aurait été un long chemin de retourner à la pointe du Noroît sinon.", rewards = nil},
[5541] = {title = "Munitions pour Rumbleshot", objective = "Apporter les Munitions de Rumbleshot à Hegnar Rumbleshot à Dun Morogh.", description = "Hegnar Rumbleshot vend des armes à feu sur la route d'Anvilmar. Les fusiliers et les équipes de mortier passent beaucoup de temps à s'entraîner près de son magasin et il a toujours besoin de munitions fraîches.\n\nMais... D'après mon messager, la dernière caisse de munitions que je lui ai envoyée s'est perdue quand il a été chassé de son camp, près de l'antre Gris par les Wendigos... L'imbécile a laissé les munitions de Rumbleshot derrière lui !\n\n<nom>, pouvez-vous les retrouver et les apporter à Rumbleshot ? Il les attend et je suis sûr que ses stocks seront bientôt épuisés.", progress = "J'espère que vous n'êtes pas là pour avoir des munitions, parce que nous en sommes presque à court !", completion = "Parfait, plus de munitions ! La cargaison du vieux Loslor est finalement passée ! Les munitions peuvent avoir du retard, mais comme disait mon grand-père : mieux vaut tard que jamais !\n\nMerci beaucoup, &lt;nom&gt;. J'ai déjà des acheteurs pour cette cargaison !", rewards = "Vous recevrez :\n\n"},
[5542] = {title = "Chiens-démons", objective = "Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée.", description = "Si vous allez rester ici, je demande seulement à ce que fassiez quelque chose en échange. Nous avons beaucoup de trouble-fête qui auraient besoin d'un peu de \"discipline\".\n\nVous pouvez commencer avec les Chiens pestiférés et leurs petits.\n\nJe n'ai pas grand-chose à vous offrir, seulement un repas chaud et un peu de conversation si vous réussissez.", progress = nil, completion = "Bon travail, &lt;nom&gt;. Venez. Reposez-vous. Mangeons en évoquant le passé !", rewards = "Vous recevrez :\n\n"},
[5543] = {title = "Ciel couleur de sang", objective = "Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring.", description = "Malheur à ceux qui errent dans les Maleterres. La folie habite ces bois, qu'il s'agisse des fanatiques de la Croisade écarlate qui tuent tous ceux qui ne portent pas la marque de la Croisade, ou des créatures sanguinaires du Fléau qui n'ont qu'un but : accroître leurs rangs avec plus de morts-vivants.\n\nMême les créatures sauvages sont devenues des bêtes cruelles, mangeuses d'hommes. Je vous demande de détruire celles qui pourraient attaquer par le ciel : les chauve-souris pestiférées.", progress = nil, completion = "Vous êtes un exemple éclatant d'honnêteté, &lt;race&gt; ! Il y a bien longtemps que je n'avais senti le sang des héros battre dans mes veines. Vos actes de bravoure nous transportent !", rewards = "Vous recevrez :\n\n"},
[5544] = {title = "Larve putride", objective = "Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées.", description = "Mes réserves de nourriture s'amenuisent, <nom>. J'ai honte d'avouer que je pourrais ne pas avoir assez de nourriture pour partager avec vous.\n\nPourriez-vous m'aider ? Dans les parages, les seules créatures non affectées par les ravages de la Peste sont les Vers putrides. Bien que fade, cette viande se garde pendant des mois. J'en aurais besoin de quelques centaines de kilos afin de refaire mes stocks pour l'hiver approchant !", progress = "Vous finirez par vous habituer au goût, <nom>.", completion = "Puisse la Lumière vous guider ! Soyez béni, jeune homme.", rewards = "Vous recevrez :\n\n"},
[5545] = {title = "Un sac d'embrouilles", objective = "Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est.", description = "J'ai un vrai problème sur les bras. J'ai une commande de bois à livrer mais je n'ai plus assez de temps pour l'assurer. Les loups et les ours au nord ont éloigné mes travailleurs des tas de bois qu'ils avaient déjà coupés.\n\nJ'ai déjà dit à l'Adjoint Rainer qu'il fallait nous débarrasser de ces animaux, en attendant j'ai besoin de quelqu'un pour ramasser le bois. Si vous pouviez ramener huit fagots de bois, je tiendrais ainsi mes engagements.", progress = "La date limite ne sera pas reculée, <classe>. Dépêchez-vous et ramassez ces fagots de bois.", completion = "Excellent ! Grâce à vous, je pourrai terminer la commande à temps. En signe de ma gratitude, acceptez en compensation de vos efforts ces quelques pièces.\n\nMerci et bonne route.", rewards = "Vous recevrez :\n\n"},
[5561] = {title = "Le rassemblement des kodos", objective = "Ramener cinq Kodos domptés et le Kombobulateur kodo à Smeed Scrabblescrew au camp de Scrabblescrew.", description = "Bibbly pense être le seul gobelin de Désolace à savoir comment faire de l'argent. Peuh… Moi, je suis responsable de la seule caravane suffisamment courageuse pour voyager dans ces contrées. Depuis que j'ai appris à rajeunir et à contrôler les kodos âgés et mourants avec mon Kombobulateur kodo, les propriétaires de la caravane, Cork, Rigger et moi, nous nous sommes associés.\n\nPrenez le Kombobulateur et utilisez-le sur des kodos âgés ou mourants. Cela secouera la bête et la rendra docile, prête à vous suivre. Une fois que vous aurez un kodo docile, ramenez-le-moi.", progress = "La caravane sera là d'ici peu ; avez-vous les cinq nouveaux kodos apprivoisés que je vous ai demandés ?", completion = "&lt;Smeed Scrabblescrew commence à compter.&gt;\n\nTrois, quatre et cinq… Excellent, je demande cinq kodos apprivoisés et j'en reçois cinq apprivoisés… Je vais être riche... Oui, très riche ! J'aimerais voir la tête de Bibbly lorsqu'il aura connaissance de ma réussite !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de voleur de kodoSpallières de renforcement\n\nVous recevrez également :\n\n"},
[5581] = {title = "Les portails de la Légion", objective = "Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Wisemane, à Proie-de-l'Ombre.", description = "Regardez, la Main d'Iruxos ! C'est vraiment une vision horrible.\n\nVous devez l'avoir en votre possession pour pouvoir fermer les portails démoniaques du convent de Mannoroc... C'est ce que je vous demande maintenant de faire. La menace démoniaque augmente et nous devons fermer ces portails pour arrêter cette vague de démons. Bonne chance, <nom>... et méfiez-vous des gardiens du portail.", progress = "Avez-vous banni les portails démoniaques au convent de Mannoroc ?", completion = "Je fais votre éloge, &lt;nom&gt;. Votre action a grandement aidé à combattre la menace démoniaque, tout Azeroth est maintenant plus sûr.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGarde-poignets poigne-d'acierGants en fourrure tressée\n\nVous recevrez également :\n\n"},
[5582] = {title = "L'écaille de dragon luisante", objective = "Apporter l’Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Il s'agit d'une écaille perdue par un jeune dragon pestiféré. Mais à l'encontre des autres écailles crevassées et purulentes du monstrueux nourrisson, cette écaille est rare car saine et intacte.\n\nBetina Bigglezink désirera sûrement en avoir un échantillon à étudier.", progress = "<nom>, vous avez quelque chose à me montrer ?", completion = "Excellent ! Cela sera inestimable pour l'avancement de mes recherches sur les machinations du Fléau. Merci, &lt;nom&gt;, et si vous trouvez plus de ces écailles, ramenez-les-moi s'il vous plaît !", rewards = nil},
[5601] = {title = "Pamela, ma sœur", objective = "Trouver Pamela Redpath dans le Darrowshire.", description = "J'ai fui Lordaeron pendant la Grande Guerre et j’ai pu m'échapper avant que le Fléau ne s'abatte sur ma nation et ne la transforme en un cauchemar ambulant ! J'ai eu de la chance, mais pas ma famille. J'ai peur qu'ils n’aient tous été tués au cours de la bataille de Darrowshire.\n\nDarrowshire est un village des Royaumes de l'Est, niché dans les collines du sud de ce qui est maintenant les Maleterres de l'Est. Vous rendrez-vous là-bas à la recherche de ma famille ? Ils me manquent tellement, particulièrement ma petite sœur Pamela.\n\nJe vous en prie, trouvez-la !", progress = nil, completion = "Où est ma sœur Jessica ? Elle est partie il y a si longtemps, alors que j'étais toute petite. Elle pleurait tellement quand elle est partie. Je ne sais pas pourquoi elle pleurait ! Peut-être qu'elle était tombée et s'était fait mal au pied.\n\nQuand Jessica était ici, on jouait ensemble, on dansait et on cueillait de jolies fleurs autour de la maison. Et parfois on se cachait quand papa rentrait à la maison, et on lui sautait dessus par surprise !\n\nReviens, Jessica ! Si tu reviens, papa reviendra peut-être aussi et on pourra de nouveau jouer tous les trois...", rewards = "Vous recevrez :\n\n"},
[5621] = {title = "Vêtements de la lune", objective = "Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Morninglight, à Dolanaar.", description = "J'ai besoin de votre aide, <nom>. Je dois rester ici pour former les autres étudiants, mais vous, vous pouvez aller porter secours à l'une de nos Sentinelles, juste au sud de Dolanaar. Elle a été blessée en patrouillant dans la ville et a besoin de notre aide. Son nom est Shaya.\n\nQuand vous l'aurez trouvée, guérissez ses blessures et fortifiez-la avec vos sorts. Cela la protégera un peu si elle a d'autres ennuis. Revenez me voir lorsque vous aurez accompli votre devoir pour Elune.", progress = nil, completion = "Vous avez bien agi et servi Elune. Pour cela, je vous remercie.\n\nS'il vous plaît, prenez cette robe en guise de remerciement. Elle signifie que vous avez gagné le droit de faire partie de notre ordre. Vous pouvez ou non la porter, mais quoi qu'il en soit nous vous considérerons toujours comme étant l’un des nôtres.\n\nQu'Elune soit avec vous, &lt;nom&gt;, et merci !", rewards = "Vous recevrez :\n\nRobe lunaire d'Elune"},
[5622] = {title = "Au service d'Elune", objective = "Parler à Laurna Morninglight à Teldrassil.", description = "<nom>, vous devrez partir pour Dolanaar lorsque vous en aurez terminé ici à Sombrevallon. Vous y trouverez Laurna Morninglight. Elle vous en apprendra davantage sur les voies d'Elune, et c'est avec elle que vous obtiendrez votre premier vêtement dénotant votre nature de <prêtre/prêtresse> d'Elune.\n\nPrenez garde, et puissiez-vous être <protégé/protégée> durant vos voyages.", progress = nil, completion = "Je suis heureux de voir que Shanda vous a envoyée vers moi, &lt;nom&gt;. Enseigner aux jeunes prêtresses les lois d'Elune me donne une grande satisfaction.", rewards = "Vous recevrez :\n\n"},
[5623] = {title = "Au service de la Lumière", objective = "Parler à la prêtresse Josetta dans la Forêt d’Elwynn.", description = "Salutations à nouveau, jeune <prêtre/prêtresse>. Il est à présent temps pour vous d'en apprendre davantage sur notre religion. Une fois que vous aurez terminé ce que vous avez à faire ici à Northshire, veuillez aller voir la prêtresse Josetta à Goldshire. Elle a beaucoup à vous apprendre et a vent de vos grands progrès dans la voie de la Lumière. Elle est impatiente de vous enseigner plus en avant.", progress = nil, completion = "Je suis content de vous voir, &lt;nom&gt;. Nous devons discuter de votre avenir et de votre cheminement dans la Lumière.", rewards = "Vous recevrez :\n\n"},
[5624] = {title = "Vêtements de la Lumière", objective = "Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Goldshire.", description = "Normalement je propose un petit défi aux disciples de la Lumière, pour tester leur compétence. Je veux savoir s'ils sont dignes de porter leurs premières robes, ce symbole de l’approbation et du soutien de l’Eglise à ses prêtres et prêtresses.\n\nMais la situation est un peu différente ici. Un des citoyens de Goldshire a vu un garde blessé près du lac, à l'est d'ici. Son nom est Roberts. Trouvez-le, guérissez-le, fortifiez son corps et revenez ici. Si vous faites cela pour moi, je considérerai que votre examen est terminé.", progress = nil, completion = "Excellent, &lt;nom&gt;. Avec un garde de plus à l'extérieur pour aider la ville, nous serons plus en sécurité. Je suis ravie de voir que vous avez appris à utiliser vos techniques judicieusement. Quand vous voudrez continuer votre entraînement, revenez me voir. Mais pour l'instant, prenez cette robe. Cela indiquera que vous faites partie de notre ordre. Mais vous pouvez ne pas la porter, elle n'est pas nécessaire pour les prochaines épreuves.", rewards = "Vous recevrez :\n\nRobe de moine de la lumière"},
[5625] = {title = "Vêtements de la Lumière", objective = "Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos.", description = "Il est de coutume de tester l'un de vos pouvoirs pour savoir si vous êtes digne de porter les robes qui symbolisent votre place dans l'Eglise. Mais il y a plus urgent. Le citoyen de Kharanos qui vient d'entrer m'a parlé d'un montagnard blessé à l'extérieur de la ville, au sud.\n\nGuérissez ce Dolf, restaurez sa fortitude et je considérerai que vous avez fait vos preuves. Cela vous convient-il ?", progress = nil, completion = "Bien joué, &lt;nom&gt; ! La Lumière est en vous, pour sûr.\n\nVoilà, prenez cette robe. Elle indiquera votre place dans l'Eglise et permettra aux gens de reconnaître en vous un &lt;classe&gt;, portez-la si vous le souhaitez.\n\nPlus tard vous passerez d'autres tests. Faites de votre mieux pour maîtriser vos techniques et apprendre. Faites-vous la main avec quelques combats, et réessayez avec d'autres voyageurs.\n\nMais sachez garder mesure.", rewards = "Vous recevrez :\n\nRobe de moine de la lumière"},
[5626] = {title = "Au service de la Lumière", objective = "Parler à Maxan Anvol à Dun Morogh.", description = "Eh ! <nom> ! Vous avez une minute ? !\n\nVous avez suivi la Lumière suffisamment longtemps pour trouver la route qui mène à Maxan Anvol à Kharanos. Il vous enseignera de nombreuses choses et si vous vous avérez courageux, il vous donnera votre première robe, pour vous démarquer en tant que <prêtre/prêtresse>.\n\nAllez, continuez votre chemin ! Dès que vous en avez fini ici, passez par le tunnel, il vous attendra.", progress = nil, completion = "Oh, ainsi c'est Bransock qui vous envoie hein ? Bien, bien ! Il voit juste, il est temps pour vous de faire un plus grand pas vers la Lumière. Cela vous donnera plus de caractère et vous rendra plus fort… et vous en aurez besoin, d’endurance... et de volonté.", rewards = "Vous recevrez :\n\n"},
[5627] = {title = "Etoiles d'Elune", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires"},
[5628] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Bonjour, <nom>. Quel bonheur que vous me parliez pendant quelques instants. Vous êtes bien loin de chez vous et vous êtes si jeune. J'admire les ambitieux. Ah si j'avais eu le courage de voyager lorsque j'étais plus jeune...\n\nIl y avait une prêtresse de votre ordre ici, il n'y a pas longtemps. Elle a dit qu'il était important que vous reveniez au temple de la Lune à Darnassus et que vous parliez à la prêtresse Alathea. Cela concerne votre entraînement. Je ne traînerai pas trop si j'étais vous.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5629] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Encore bonjour, <nom>. Je sais que votre temps a été bien rempli à aider les gens, mais vous devez prendre du temps pour vous. La prêtresse Alathea a envoyé quelqu'un ici pour vous chercher. Il semble que vous ayez attiré l'attention de nos aînés et ils pensent que vous pouvez accomplir de grandes choses. Allez au temple de la Lune et cherchez Alathea. Elle vous y attendra. Bonne chance et qu'Elune soit avec vous.", progress = nil, completion = "Merveilleux, vous êtes revenue, &lt;nom&gt;. Cela nous plaît toujours, à Tyrande et à moi, que nos élèves partent vers le monde et en reviennent saufs. Comment cela s'est-il passé ? Elune bénit-elle toujours vos voyages ? Peut-être qu'après nous être entretenus des affaires courantes, vous m'en parlerez ?", rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5630] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Bien le bonjour <mon garçon/ma fille>. Ça fait plaisir de vous voir, vous qui venez de si loin. Sans vouloir vous offenser, la plupart de vos compatriotes ne supportent pas trop ces climats froids. Vous avez l'air plus à l'aise.\n\nIl n'y a pas longtemps, l'une de vos prêtresses vous cherchait. Elle a dit quelque chose à propos de trouver une prêtresse Alathea dans le temple de la Lune à Darnassus. Elle a dit que c'était important et que vous devriez retourner là-bas très vite.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5631] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Une prêtresse est récemment venue nous voir et elle vous cherchait, <nom>. Elle a dit qu'elle avait pour mission de vous trouver et que vous deviez retourner au temple de la Lune à Darnassus dès que possible. Une fois sur place, cherchez la prêtresse Alathea. Elle vous en dira plus.\n\nQue la Lumière soit avec vous, <nom>.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5632] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Ah, oui, bien sûr. Bonjour, <nom>. Un messager de notre ordre était ici il y a peu. Elle vous cherchait et a parlé d'événements importants ayant eu lieu à Darnassus et que vous deviez retourner au temple de la Lune dès que vous pouviez. Lorsque vous y serez, parlez à la prêtresse Alathea. Je pense que cela a quelque chose à voir avec les progrès que vous faites concernant nos us et coutumes.\n\nN'oubliez pas, retournez à Darnassus dès que possible.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5633] = {title = "Retour à la maison", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Bien le bonjour <mon garçon/jeune fille>. Ça fait plaisir de vous voir ici. Soyez bénis, vous et les vôtres.\n\nPendant que vous étiez en voyage, une prêtresse de votre temple est venue à votre recherche. Elle a dit que vous deviez revenir au temple de la Lune dès que possible. Désolé de ne pouvoir vous en dire plus, mais cela avait l'air important. Lorsque vous serez au temple, parlez à la prêtresse Alathea.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nEclats stellaires\n\nVous allez être la cible du sort suivant :\n\nEclats stellaires\n\nVous recevrez également :\n\n"},
[5634] = {title = "Prière du désespoir", objective = "Vous avez rendu un grand service à la Lumière en devenant un exemple remarquable pour ceux qui voyagent dans et au-delà de ces contrées dangereuses. S'il vous plaît, veuillez accepter cette leçon en remerciement de tout ce que vous avez fait.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir"},
[5635] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Vous avez attiré l'attention de nos supérieurs, <nom>. Ils ont demandé à ce que vous rejoignez la cathédrale de la Lumière à Stormwind dès que possible. Apparemment ils pensent que vous avez fait vos preuves et vont vous proposer un entraînement. Lorsque vous serez la-bas, trouvez la grande prêtresse Laurena. Elle vous guidera plus avant. Bonne chance et que la Lumière soit avec vous.", progress = nil, completion = "Content de vous voir, &lt;nom&gt;. Nous devons parler de nombreuses choses, mais le plus important est votre entraînement dans les voies de la Lumière.\n\nIl y a des leçons que tous les serviteurs de la Lumière doivent connaître. Si vous le voulez, nous allons les aborder.", rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir\n\nVous recevrez également :\n\n"},
[5636] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Qu'Elune vous bénisse, <nom>. J'espère que votre Lumière vous protègera bien aujourd'hui.\n\nL'un de vos prêtres était là il y a peu. Il vous cherchait. Il souhaitait que vous retourniez à la cathédrale de la Lumière dès que possible pour parler à la grande prêtresse Laurena. Il semble que vous avez fait bonne impression. Je ne resterais pas ici si j'étais vous. Votre peuple a besoin de vous.", progress = nil, completion = "Content de vous voir, &lt;nom&gt;. Nous devons parler de nombreuses choses, mais le plus important est votre entraînement dans les voies de la Lumière.\n\nIl y a des leçons que tous les serviteurs de la Lumière doivent connaître. Si vous le voulez, nous allons les aborder.", rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir\n\nVous recevrez également :\n\n"},
[5637] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Il est temps pour vous de retourner à Stormwind, <nom>. La grande prêtresse Laurena, à la cathédrale de la Lumière, veut vous parler. Il doit s'agir de quelque chose de vraiment positif ou alors négatif pour que la grande prêtresse veuille vous voir personnellement. Mais j'imagine que vous n'avez fait que le bien autour de vous et qu'elle vous en récompensera.\n\nMais ne perdez pas de temps, partez au plus tôt.", progress = nil, completion = "Content de vous voir, &lt;nom&gt;. Nous devons parler de nombreuses choses, mais le plus important est votre entraînement dans les voies de la Lumière.\n\nIl y a des leçons que tous les serviteurs de la Lumière doivent connaître. Si vous le voulez, nous allons les aborder.", rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir\n\nVous recevrez également :\n\n"},
[5638] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Il y a peu de temps, l'un de vos prêtres était ici et vous cherchait, <nom>. Il m'a dit que si je vous voyais je devais vous diriger vers la cathédrale de la Lumière. Il a dit que c'était très important, mais je ne m'inquiéterais pas si j'étais vous. Son attitude était positive...comme s'il avait de bonnes nouvelles à vous annoncer. Je ne traînerais pas si j'étais vous.\n\nQu'Elune vous accompagne, cher <nom>.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir\n\nVous recevrez également :\n\n"},
[5639] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "On vous attend à Stormwind, <nom>. La grande prêtresse Laurena pense qu'il est temps de prouver que vous êtes digne de suivre un nouvel entraînement. Ne perdez pas de temps à chercher votre chemin. Vous la trouverez à la cathédrale de la Lumière au centre de la ville. Faites-lui toutes mes amitiés et montrez que vous êtes digne d'un tel honneur. Que la Lumière soit avec vous, <nom> !", progress = nil, completion = "Content de vous voir, &lt;nom&gt;. Nous devons parler de nombreuses choses, mais le plus important est votre entraînement dans les voies de la Lumière.\n\nIl y a des leçons que tous les serviteurs de la Lumière doivent connaître. Si vous le voulez, nous allons les aborder.", rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir"},
[5640] = {title = "Prière du désespoir", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Gloire à Elune et à votre Lumière, <nom> !\n\nEn ce moment, des membres de notre ordre acquièrent des compétences reflétant leur foi en Elune. Si la connaissance m'est indispensable, j'imagine qu'il en est de même pour votre ordre.\n\nLorsque vos affaires à Darnassus seront terminées, cherchez une grande prêtresse pour reprendre votre entraînement.", progress = nil, completion = "Content de vous voir, &lt;nom&gt;. Nous devons parler de nombreuses choses, mais le plus important est votre entraînement dans les voies de la Lumière.\n\nIl y a des leçons que tous les serviteurs de la Lumière doivent connaître. Si vous le voulez, nous allons les aborder.", rewards = "Vous apprendrez :\n\nPrière du désespoir\n\nVous allez être la cible du sort suivant :\n\nPrière du désespoir\n\nVous recevrez également :\n\n"},
[5641] = {title = "Un manque de peur", objective = "Vous avez tout ce qui fait un grand <classe>, <nom>. Continuez à faire du bon travail !\n\nVous avez montré que vous pouviez partir au combat. Peut-être est-t-il temps de vous apprendre un petit quelque chose de plus.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGardien de peur\n\nVous allez être la cible du sort suivant :\n\nGardien de peur"},
[5642] = {title = "Garde des ténèbres", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Il se passe quelque chose d'important à Orgrimmar, <nom>.\n\nLes messagers qui passent par ici à la recherche de prêtres trolls sont d'habitude tranquilles. Cette fois-ci, ils semblent plutôt pressés. Ne flânez pas trop à Thunder Bluff. Retournez dès que possible dans la Vallée des Esprits.", progress = nil, completion = "Le temps est venu pour accomplir l'un des plus importants rites de passage pour les prêtres de notre confession, &lt;nom&gt;. Je vais vous l'expliquer - vous êtes prêt.", rewards = "Vous apprendrez :\n\nGarde de l'ombre\n\nVous allez être la cible du sort suivant :\n\nGarde de l'ombre\n\nVous recevrez également :\n\n"},
[5643] = {title = "Garde des ténèbres", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Comme c'est le cas pour nos prêtres, votre tribu vous met à l'épreuve. Ces rites de passage permettent aux prêtres d'apprendre des compétences spéciales qui sont vitales pour leur survie. Je sens que le temps est venu pour vous alors même que nous parlons. Retournez dans la Vallée des Esprits à Orgrimmar et parlez à Ur'kyo. Ce qu'il vous enseignera est très important pour votre avenir.", progress = nil, completion = "Le temps est venu pour accomplir l'un des plus importants rites de passage pour les prêtres de notre confession, &lt;nom&gt;. Je vais vous l'expliquer - vous êtes prête.", rewards = "Vous apprendrez :\n\nGarde de l'ombre\n\nVous allez être la cible du sort suivant :\n\nGarde de l'ombre\n\nVous recevrez également :\n\n"},
[5644] = {title = "Peste dévorante", objective = "Parler à Aelthalyste à Undercity.", description = "Ah, quel beau jour pour vous, <nom>. Je vois que les leçons ont été profitables mais qu'il est temps de vous renvoyer à Aelthalyste. Il y a des choses qu'elle seule peut vous apprendre, et si vous en valez la peine.\n\nJe ne vais pas vous gâcher la surprise mais je me souviens quand j'étais un jeune prêtre, étudiant le vrai pouvoir...le pouvoir divin. Et oui, des sacrés souvenirs.\n\nRetournez voir Aelthalyste dans Undercity, <nom>. Elle vous attendra dans le Quartier des guerriers.", progress = nil, completion = "Bien, vous êtes revenue, et à point. Nous avons à discuter de sujets importants, &lt;nom&gt;. Vos capacités croissent, et nous devons nous assurer que vous êtes prête.", rewards = "Vous apprendrez :\n\nPeste dévorante\n\nVous allez être la cible du sort suivant :\n\nPeste dévorante\n\nVous recevrez également :\n\n"},
[5645] = {title = "Un manque de peur", objective = "Parler au grand prêtre Rohan à Ironforge.", description = "<nom>, votre grand prêtre Rohan souhaite s'entretenir avec vous à Ironforge. Faites vite, mon ami, car votre prochaine mise à l'épreuve approche. Bien que j'aimerais être témoin des rites de votre race, ma place est ici. Mais que la Lumière vous accompagne dans vos voyages. Rohan sera à la Garde mystique une fois que vous aurez atteint la ville. Il vous attendra.", progress = nil, completion = "Il est bon que vous soyez venu, &lt;nom&gt;. Notre espèce est fière et forte et il est temps que vous appreniez à ne pas seulement l'être, mais aussi à inspirer de telles qualités chez les autres. Prêt, mon garçon ?", rewards = "Vous apprendrez :\n\nGardien de peur\n\nVous allez être la cible du sort suivant :\n\nGardien de peur\n\nVous recevrez également :\n\n"},
[5646] = {title = "Peste dévorante", objective = "Parler à Aelthalyste à Undercity.", description = "Aelthalyste est très respectueuse de notre peuple. Je fais de même pour sa tribu.\n\nVous devez retourner à Undercity, <nom>. Là, dans le Quartier des guerriers, elle est disponible pour vous en apprendre plus sur votre peuple et leurs coutumes. Allez-y, n'attendez pas…", progress = nil, completion = "Bien, vous êtes revenu, et à point. Nous avons à discuter de sujets importants, &lt;nom&gt;. Vos capacités croissent, et nous devons nous assurer que vous êtes prêt.", rewards = "Vous apprendrez :\n\nPeste dévorante\n\nVous allez être la cible du sort suivant :\n\nPeste dévorante\n\nVous recevrez également :\n\n"},
[5647] = {title = "Un manque de peur", objective = "Parler au grand prêtre Rohan à Ironforge.", description = "Votre race est puissante, <nom>. Nous sommes fiers d'être vos alliés. Et à chaque fois qu'un nouveau jour se lève, vous et votre peuple êtes plus prêts de la vérité. Non seulement vous réussirez à trouver vos origines mais vous découvrirez que vous êtes sur le bon chemin pour bien d'autres choses. Ce sentiment doit vous remplir de joie.\n\nUn message vient d'arriver d'Ironforge. Il faut que vous retourniez là-bas à la Garde mystique et que vous parliez au grand prêtre Rohan. Ne le faites pas attendre et qu'Elune vous guide.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGardien de peur\n\nVous allez être la cible du sort suivant :\n\nGardien de peur\n\nVous recevrez également :\n\n"},
[5648] = {title = "Vêtements de la spiritualité", objective = "Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.", description = "V'là votre premier test, <nom>. Au sud de Tranchecolline, juste à l'extérieur de la ville, un d'nos fantassins a été blessé en s'battant contre les troupes de Proudmoore. Elle s'trouve pas trop bien, et faudrait qu'un d'nous aille l'aider. Trouvez-la – son nom c'est Kor'ja – soignez ses blessures et donnez-lui la bénédiction d'nos ancêtres.\n\nQuand vous aurez fait ça, ce s'ra la meilleure preuve que vous pouvez commencer à suivre notre trace.", progress = nil, completion = "Bien. Alors Kor'ja est en vie et elle part défendre nos villes de ces maudits humains… J'aime souvent repenser aux vieux jours de bataille ; où le pouvoir est réservé au sage et non au fort.\n\nVous m'avez aidé, &lt;nom&gt;. Prenez cette robe. Elle peut vous aider, vous n'en avez peut-être pas besoin, mais vous la méritez, et je suis fier de vous appeler frère.", rewards = "Vous recevrez :\n\nRobe juju maléfique"},
[5649] = {title = "Au service de la spiritualité", objective = "Parler à Tai'jin en Durotar.", description = "Salut à toi. Notre peuple a rejoint la Horde parce qu'ils sont bons pour nous. Eux loyaux et eux enseignent des trucs sur l'honneur. Mais nos traditions ont la vie dure. Ce n'est pas parce que les orcs n'approuvent pas toutes nos coutumes qu'il ne faut pas continuer à en pratiquer quelques-unes en secret.\n\nVous savez ça, c'est pourquoi je vous envoie à Tai'jin, qui vit à Tranchecolline. Elle vous apprendra les pratiques de notre tribu. Allez la voir quand vous le voudrez.", progress = nil, completion = "Ahh…Ainsi vous venez finalement à Tai'jin. Bon bon.\n\nVous savez que nous ne sommes plus la même tribu qui a rejoint autrefois la Horde. Nous sommes plus forts maintenant. Plus forts car nous nous adaptons, comme la Horde nous l'a appris. Nous ne battons plus nos ennemis pour gagner en force, mais gagnons en force puis vainquons nos ennemis\n\nLa différence est subtile, mais vous apprendrez. Vous verrez. La tribu compte sur vous pour apprendre cela.", rewards = "Vous recevrez :\n\n"},
[5650] = {title = "Vêtements des ténèbres", objective = "Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.", description = "Notre pouvoir vient des ténèbres et de l'ombre, <nom>, mais ce n'est pas tout. Vous avez reconnu qu'il était intéressant de connaître les arts de la guérison. C'est sage. Aussi, avant de pouvoir connaître les ténèbres, vous devez connaître la lumière. Et pour cela, je vais vous faire passer un test.\n\nAu nord du cimetière, il y a un garde blessé : le Garde noir Kel. Il nous a protégés des gnolls pendant quelque temps et il a besoin de soins. Mais vous devrez aussi fortifier son corps avant qu'il ne puisse retourner faire son devoir. Remplissez ces deux missions avec des charmes, puis revenez me voir.", progress = "Nos pouvoirs nous rendent très utiles dans de nombreuses situations, <nom>. Vous verrez, notre capacité à panser les blessures et à augmenter la capacité de nos compagnons à recevoir des coups sont les talents les plus appréciés auxquels nous avons accès. Que cela ne vous dissuade pas de poursuivre votre apprentissage vers d'autres voies <classe>, vous pouvez avoir du talent dans de nombreuses disciplines. Mais... si vous voulez détruire vos ennemis grâce à la magie, alors peut-être que les Arcanes vous intéresseront.", completion = "Vous avez passé mon examen avec aisance. Bien.\n\nVous pourrez bientôt avoir plus de responsabilités et cela vous mènera vers les pouvoirs sombres, des pouvoirs auxquels aucun &lt;classe&gt; des autres races n’a accès.\n\nPrenez cette robe, elle représente votre statut. Vous l'avez bien gagnée. Si vous ne voulez pas la porter maintenant, cela n'a pas d'importance. Moi et mes semblables vous serons à jamais reconnaissants pour ce que vous avez accompli.", rewards = "Vous recevrez :\n\nRobe sacrificielle d'acolyte"},
[5651] = {title = "Au service des ténèbres", objective = "Parler au sombre clerc Beryl dans les Clairières de Tirisfal.", description = "Les Réprouvés ont appris beaucoup de choses au fil du temps, des choses que certaines races commencent seulement à entrevoir. Et bien que nos chemins restent dans les ténèbres, vous constaterez que beaucoup de choses s'appuient sur la lumière et sur l'obscurité. Vos leçons vous apprendront à utiliser les deux... et avec discrétion. Mais retenez bien ce que je vais vous dire : nous sommes nés dans la corruption et nous sommes faits de chair pourrissante. L'obscurité est notre mère.\n\nLorsque vous voudrez en savoir plus, cherchez le sombre clerc Beryl à Brill.", progress = nil, completion = "Enfin, vous êtes là. Votre foi seule ne vous permettra pas de passer les épreuves qui vous attendent. Il vous faudra aussi le sens des priorités et de l'ambition vous aidera aussi.", rewards = "Vous recevrez :\n\n"},
[5652] = {title = "Le maléfice de faiblesse", objective = "Vous feriez bien de tenir compte de cette leçon. Le maléfice de faiblesse vous servira grandement lors de combats. Plus tard, j'aurai d'autres épreuves à vous faire passer qui vous serviront et permettront de prouver votre valeur à la tribu.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nMaléfice de faiblesse\n\nVous allez être la cible du sort suivant :\n\nMaléfice de faiblesse"},
[5654] = {title = "Le maléfice de faiblesse", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Il est temps pour vous de rencontrer Ur'kyo, <nom>. Il est dans la Vallée des esprits, dans la ville des orcs. Allez-y et parlez-lui. Il est temps que vous en sachiez plus sur les vieilles coutumes de notre peuple. Il est temps que vous entriez dans le cercle et que vous deveniez un vrai prêtre de notre tribu.", progress = nil, completion = "Ah, bien, vous êtes là. Nous pouvons commencer votre entraînement à l'ancienne méthode.", rewards = "Vous apprendrez :\n\nMaléfice de faiblesse\n\nVous allez être la cible du sort suivant :\n\nMaléfice de faiblesse\n\nVous recevrez également :\n\n"},
[5655] = {title = "Le maléfice de faiblesse", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Je suis ici pour être sûr que vous n'errez pas trop loin de votre patrie, <nom>. Ils m'ont envoyé pour que vous reveniez au pays car Ur'kyo, le plus grand de nos prêtres, souhaite vous parler. Vous devez aller dans la Vallée des esprits, dans la ville des orcs, et parlez à Ur'kyo. Il vous attend.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nMaléfice de faiblesse\n\nVous allez être la cible du sort suivant :\n\nMaléfice de faiblesse\n\nVous recevrez également :\n\n"},
[5656] = {title = "Le maléfice de faiblesse", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Quel bonheur de voir des prêtres de toutes cultures parcourir le monde. Savoir qu'une puissance existe, qu'elle n'est pas seulement faite d'arcane et qu'elle est à portée de la main ! C'est un honneur de vous accompagner jusque chez vous, <nom>.\n\nUr'kyo, à Orgrimmar, a demandé à vous voir. Vous le trouverez dans la Vallée des Esprits.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nMaléfice de faiblesse\n\nVous allez être la cible du sort suivant :\n\nMaléfice de faiblesse\n\nVous recevrez également :\n\n"},
[5657] = {title = "Le maléfice de faiblesse", objective = "Parler à Ur'kyo à Orgrimmar.", description = "Chez vous, revenir chez vous, <nom>.\n\nVotre chef spirituel Ur'kyo vous supplie de revenir et de lui parler des chemins que vous avez pris.\n\nAllez dans la Vallée des Esprits dans la grande cité d'Orgrimmar. Vous le trouverez ici.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nMaléfice de faiblesse\n\nVous allez être la cible du sort suivant :\n\nMaléfice de faiblesse\n\nVous recevrez également :\n\n"},
[5658] = {title = "Toucher de faiblesse", objective = "Ah jeune <classe> ! Je suis ravie de vous revoir. Je vais vous enseigner quelque chose que vous n'êtes pas près d'oublier. D'accord ?", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nToucher de faiblesse\n\nVous allez être la cible du sort suivant :\n\nToucher de faiblesse"},
[5660] = {title = "Toucher de faiblesse", objective = "Parler à Aelthalyste à Undercity.", description = "Vous êtes loin de chez vous, <classe>. On vous demande dans votre ville souterraine. Votre maîtresse, celle que vous appelez Aelthalyste, a besoin de vous. C'est comme pour ma tribu, il y a des choses qu'elle seule peut vous enseigner. Ne restez pas là trop longtemps. Mettez-vous en route pour le Quartier des guerriers aussi vite qu'un zeppelin pourra vous y emmener.", progress = nil, completion = "Ah, bien, un autre est arrivé. Le temps m'importe peu, mais il est essentiel pour vous. Vous avez beaucoup à apprendre et je souhaite vous en apprendre beaucoup. Vous devez simplement le mériter. Faites-le, et vous serez grandement récompensé.", rewards = "Vous apprendrez :\n\nToucher de faiblesse\n\nVous allez être la cible du sort suivant :\n\nToucher de faiblesse\n\nVous recevrez également :\n\n"},
[5661] = {title = "Toucher de faiblesse", objective = "Parler à Aelthalyste à Undercity.", description = "Vous êtes loin de chez vous, <nom>, ici au village Bloodhoof. Moi, je dois trouver des prêtres de ma tribu pour qu'ils aillent parler à nos chefs, mais ça ne veut pas dire que je ne peux pas vous aider.\n\nJ'ai entendu dire que l'esprit de votre grande prêtresse demandait aux Réprouvés de venir à lui : il y a des choses que vous devez apprendre.\n\nAllez voir Aelthalyste dans le Quartier des guerriers de votre ville.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nToucher de faiblesse\n\nVous allez être la cible du sort suivant :\n\nToucher de faiblesse\n\nVous recevrez également :\n\n"},
[5662] = {title = "Toucher de faiblesse", objective = "Parler à Aelthalyste à Undercity.", description = "Tous mes respects, <nom>. En général, je n'enseigne qu'aux gens de ma tribu. Vos connaissances vous viennent d'Aelthalyste qui vit dans une ville appelée autrefois Lordaeron.\n\nRetournez la voir si vous voulez apprendre les compétences qui vous distingueront des autres croyants.\n\nAllez au Quartier des guerriers d'Undercity, vous y trouverez votre Maîtresse.", progress = nil, completion = "Ah, bien, un autre qui arrive. Le temps m'importe peu, mais il est essentiel pour vous. Vous avez beaucoup à apprendre et je souhaite vous en enseigner le plus possible. Vous devez simplement le mériter. Faites-le, et vous serez grandement récompensé.", rewards = "Vous apprendrez :\n\nToucher de faiblesse\n\nVous allez être la cible du sort suivant :\n\nToucher de faiblesse\n\nVous recevrez également :\n\n"},
[5663] = {title = "Toucher de faiblesse", objective = "Parler à Aelthalyste à Undercity.", description = "Aelthalyste a envoyé un message à tous ses prêtres. Nous devons envoyer les plus jeunes de notre ordre à Undercity pour un entraînement. Si vous avez les mêmes croyances que nous, alors retournez là-bas.\n\nVous trouverez Aelthalyste dans le Quartier des guerriers d'Undercity.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nToucher de faiblesse\n\nVous allez être la cible du sort suivant :\n\nToucher de faiblesse\n\nVous recevrez également :\n\n"},
[5664] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[5665] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.Un message est arrivé ici de Darnassus, <nom>. Il semble qu'une de vos prêtresses veut que vous retourniez chez vous. Parlez à la prêtresse Alathea au temple de la Lune dès que possible. Elle paraît être satisfaite de vos progrès. Elle est certainement très fière de voir un des serviteurs d'Élune s'avancer à si grands pas dans la foi.\n\nQue la Lumière soit avec vous.Vous recevrez :\n\n", description = "Un message est arrivé ici de Darnassus, <nom>. Il semble qu'une de vos prêtresses veut que vous retourniez chez vous. Parlez à la prêtresse Alathea au temple de la Lune dès que possible. Elle paraît être satisfaite de vos progrès. Elle est certainement très fière de voir un des serviteurs d'Élune s'avancer à si grands pas dans la foi.\n\nQue la Lumière soit avec vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5666] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.Oh, <nom>, par bonheur je vous trouve ! J'ai entendu dire que vous étiez <prêt/prête> pour votre prochaine épreuve au temple de la Lune. La prêtresse Alathea en personne désire s'entretenir avec vous. À votre place, je retournerais à Darnassus aussi vite que possible. Finissez ce que vous avez à faire ici et puis filez.Vous recevrez :\n\n", description = "Oh, <nom>, par bonheur je vous trouve ! J'ai entendu dire que vous étiez <prêt/prête> pour votre prochaine épreuve au temple de la Lune. La prêtresse Alathea en personne désire s'entretenir avec vous. À votre place, je retournerais à Darnassus aussi vite que possible. Finissez ce que vous avez à faire ici et puis filez.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5667] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.Ah, je vois que vous vous débrouillez très bien dans votre formation, jeune <prêtre/prêtresse>. L'un des vôtres était là il y a peu, il vous cherchait. Il semble que l'on vous requiert à Darnassus. Quelque chose à propos de la prêtresse Alathea et du temple de la Lune. Cela semblait important. Vous devriez y aller rapidement.Vous recevrez :\n\n", description = "Ah, je vois que vous vous débrouillez très bien dans votre formation, jeune <prêtre/prêtresse>. L'un des vôtres était là il y a peu, il vous cherchait. Il semble que l'on vous requiert à Darnassus. Quelque chose à propos de la prêtresse Alathea et du temple de la Lune. Cela semblait important. Vous devriez y aller rapidement.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5672] = {title = "Grâce d'Elune", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGrâce d'Elune\n\nVous allez être la cible du sort suivant :\n\nGrâce d'Elune"},
[5673] = {title = "Grâce d'Elune", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Vous savez que vous avez accès à n'importe lequel de nos Maîtres, <nom> mais il y a des choses que nous ne pourrons pas vous enseigner et que seule votre déesse Elune est en mesure de faire. Elle donne des compétences spéciales à ses croyants et je pense d'ailleurs qu'il est temps pour vous de retourner au temple de la Lune pour subir un test.\n\nRendez-vous la-bas dès que possible et parlez à la prêtresse Alathea.", progress = nil, completion = "Qu'Elune soit bénie pour votre prompt retour parmi nous. C'est un moment important de votre formation, que chacun dans notre ordre prend très au sérieux. Quand vous aurez récupéré de votre voyage, dites-le-moi. Nous pourrons alors discuter de cette prochaine étape et de là où elle vous emmènera.", rewards = "Vous apprendrez :\n\nGrâce d'Elune\n\nVous allez être la cible du sort suivant :\n\nGrâce d'Elune\n\nVous recevrez également :\n\n"},
[5674] = {title = "Grâce d'Elune", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "C'est l'aube d'un jour merveilleux, <nom>. Vous avez atteint l'âge auquel nos <prêtres/prêtresses> sont <initiés/initiées> à des talents que seuls les elfes de la nuit connaissent. Mais ce n'est pas à moi de vous les enseigner. Vous devez retourner au Temple de la Lune et vous entretenir avec la prêtresse Alathea dès que vous aurez conclu vos affaires ici. Elle vous testera pour s'assurer de votre préparation, et alors seulement, elle vousenseignera la Grâce d'Elune.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGrâce d'Elune\n\nVous allez être la cible du sort suivant :\n\nGrâce d'Elune\n\nVous recevrez également :\n\n"},
[5675] = {title = "Grâce d'Elune", objective = "Parler à la prêtresse Alathea à Darnassus.", description = "Pas de temps à perdre, <petit/petite>. Il est temps que vous retourniez à Darnassus. La prêtresse Alathea a envoyé un message pour que vous alliez là-bas vous entraîner. Elle pense sûrement qu'il est temps de vous mettre à l'épreuve, comme tous ceux qui servent la Lumière. Mettez-vous en chemin dès que possible. Dans son message, Alathea dit qu'elle vous attend dans le temple de la Lune. Bonne chance !Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGrâce d'Elune\n\nVous allez être la cible du sort suivant :\n\nGrâce d'Elune\n\nVous recevrez également :\n\n"},
[5676] = {title = "Retour d'information de l'Arcane", objective = "Nous avons été obligés d'apprendre un peu de magie pour nous protéger de ce que nous appelons communément notre plus grand ennemi : l'Arcane.\n\nJe vous enseignerai un sort qui vous aidera à vous protéger, vous et vos compagnons, contre ceux qui détiennent ce genre de pouvoir.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nRéaction\n\nVous allez être la cible du sort suivant :\n\nRéaction"},
[5677] = {title = "Retour d'information de l'Arcane", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "J'aimerais vous faire profiter de nos propres enseignements spéciaux de la Lumière, mais ça n'est pas notre rôle. Votre place est à Stormwind parmi ceux de votre espèce, <nom>… pour le moment. Croyez-moi, je ne veux pas vous offenser. Quand vous rejoindrez la grande prêtresse Laurena dans la cathédrale de la Lumière, vous comprendrez de quoi je parle. Le temps est venu pour votre race de vous préparer pour l'avenir ; de vous séparer des autres qui suivent un chemin similaire.", progress = nil, completion = "Ah, vous tombez merveilleusement bien, &lt;nom&gt;. Je me demandais si mes messagers avaient tous échoué. Je suis heureux de voir que non, sinon il y a fort à parier que vous seriez toujours par monts et par vaux à la recherche d'informations sur les menaces pesant sur notre peuple.\n\nQu'en pensez-vous ? D'un nouvel entraînement, j’entends. Votre puissance s'accroît plus rapidement, et je sens que vous êtes capable d'en apprendre plus sur notre foi.", rewards = "Vous apprendrez :\n\nRéaction\n\nVous allez être la cible du sort suivant :\n\nRéaction\n\nVous recevrez également :\n\n"},
[5678] = {title = "Retour d'information de l'Arcane", objective = "Parler à la grande prêtresse Laurena à Stormwind.", description = "Il est temps pour vous de retourner à Stormwind, mon <ami/amie>. Vos supérieurs là-bas vous rappellent pour suivre un entraînement. Et bien que cela me chagrine, votre race et la mienne sont des alliées et je ne peux trahir cela.\n\nJe ne cherche pas à jouer les effarouchés mais ma méfiance à l'égard du maniement des arcanes, qu'elles soient d'inspiration divine ou non, est toujours présente.\n\nVous saurez de quoi je parle lorsque vous reviendrez de la cathédrale de la Lumière. Parlez à la grande prêtresse Laurena lorsque vous y serez.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nRéaction\n\nVous allez être la cible du sort suivant :\n\nRéaction\n\nVous recevrez également :\n\n"},
[5679] = {title = "Peste dévorante", objective = "Si vous le désirez, je peux vous apprendre la Peste dévorante, <nom>. Un sort puissant, utile dans vos prochains combats. Entraînez-vous, vous serez mis à l'épreuve plus tard.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nPeste dévorante\n\nVous allez être la cible du sort suivant :\n\nPeste dévorante"},
[5680] = {title = "Garde des ténèbres", objective = "Vos rites arriveront bien assez tôt. Pour l'instant je vais vous enseigner un sort qui vous sera très utile pendant les combats.", description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGarde de l'ombre\n\nVous allez être la cible du sort suivant :\n\nGarde de l'ombre"},
[5681] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[5682] = {title = "<INUTILISÉ>", objective = "Parler à la grande prêtresse Alathea à Darnassus.Le temps est venu pour vous de retourner à Darnassus, <nom>. Allez parler à la grande prêtresse Alathea au temple de la Lune. Elle vous dira ce que vous devez savoir.\n\nSi je ne me trompe pas, il s'agit de nouveaux vêtements symbolisant votre nouveau rang au sein de votre ordre. Que la Lumière soit avec vous.Vous recevrez :\n\n", description = "Le temps est venu pour vous de retourner à Darnassus, <nom>. Allez parler à la grande prêtresse Alathea au temple de la Lune. Elle vous dira ce que vous devez savoir.\n\nSi je ne me trompe pas, il s'agit de nouveaux vêtements symbolisant votre nouveau rang au sein de votre ordre. Que la Lumière soit avec vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5683] = {title = "<INUTILISÉ>", objective = "Parler à la grande prêtresse Alathea à Darnassus.Oh, <mon frère/ma sœur>, quelle chance ! Il est temps pour vous de retourner à Darnassus et de parler à la grande prêtresse Alathea une fois de plus. Son messager était presque sûr qu’il s’agit de vous remettre vos nouveaux habits de notre ordre.\n\nQuand vous le pourrez, retournez chez vous et transmettez mes meilleures salutations à notre ordre.\n\nQu'Élune soit avec vous.Vous recevrez :\n\n", description = "Oh, <mon frère/ma sœur>, quelle chance ! Il est temps pour vous de retourner à Darnassus et de parler à la grande prêtresse Alathea une fois de plus. Son messager était presque sûr qu’il s’agit de vous remettre vos nouveaux habits de notre ordre.\n\nQuand vous le pourrez, retournez chez vous et transmettez mes meilleures salutations à notre ordre.\n\nQu'Élune soit avec vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5684] = {title = "<INUTILISÉ>", objective = "Parler à la grande prêtresse Alathea à Darnassus.Hmph, on se débrouille pas mal à ce que je vois, <prêtre/prêtresse>. Je parierais que vous vous demandez quand on vous rappellera chez vous à Darnassus pour célébrer votre grandeur, hein ? Eh bien, pas aujourd’hui... enfin, pas pour faire la fête en tout cas.\n\nLa grande prêtresse Alathea m’a fait savoir par message que je devais vous dire d’aller la voir si je vous rencontrais. Vous pouvez encore aller la voir au temple de la Lune… au cas où vous auriez oublié… Haha.Vous recevrez :\n\n", description = "Hmph, on se débrouille pas mal à ce que je vois, <prêtre/prêtresse>. Je parierais que vous vous demandez quand on vous rappellera chez vous à Darnassus pour célébrer votre grandeur, hein ? Eh bien, pas aujourd’hui... enfin, pas pour faire la fête en tout cas.\n\nLa grande prêtresse Alathea m’a fait savoir par message que je devais vous dire d’aller la voir si je vous rencontrais. Vous pouvez encore aller la voir au temple de la Lune… au cas où vous auriez oublié… Haha.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5694] = {title = "<INUTILISÉ>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[5695] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.Votre temple réclame votre présence à Darnassus, <nom>. Retournez au temple de la Lune et parlez à la prêtresse Alathea. Elle vous attendra là.\n\nLe temps est venu pour vous de gagner une robe de niveau supérieur.Vous recevrez :\n\n", description = "Votre temple réclame votre présence à Darnassus, <nom>. Retournez au temple de la Lune et parlez à la prêtresse Alathea. Elle vous attendra là.\n\nLe temps est venu pour vous de gagner une robe de niveau supérieur.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5696] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.C'est toujours une joie quand j'ai pour mission de renvoyer l'un des nôtres au pays pour qu'il reçoive une nouvelle robe.\n\nLa prêtresse Alathea est dans le temple de la Lune et souhaite vous parler. Dès que possible, retournez à Darnassus pour y passer votre épreuve. Qu'Élune vous accompagne, <nom>.Vous recevrez :\n\n", description = "C'est toujours une joie quand j'ai pour mission de renvoyer l'un des nôtres au pays pour qu'il reçoive une nouvelle robe.\n\nLa prêtresse Alathea est dans le temple de la Lune et souhaite vous parler. Dès que possible, retournez à Darnassus pour y passer votre épreuve. Qu'Élune vous accompagne, <nom>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5697] = {title = "<INUTILISÉ>", objective = "Parler à la prêtresse Alathea à Darnassus.Si vous continuez à y arriver aussi bien que ça, vous allez me rendre jaloux et me faire penser qu'on a pas assez de jeunes <prêtres/prêtresses> comme vous ici à Forgefer, <nom>. Vous êtes la fierté de votre peuple.\n\nLa prêtresse Alathea voudrait vous parler de nouveau si vous avez le temps. Elle est dans le temple de la Lune à Darnassus. Allez là-bas, et que la Lumière soit avec vous.Vous recevrez :\n\n", description = "Si vous continuez à y arriver aussi bien que ça, vous allez me rendre jaloux et me faire penser qu'on a pas assez de jeunes <prêtres/prêtresses> comme vous ici à Forgefer, <nom>. Vous êtes la fierté de votre peuple.\n\nLa prêtresse Alathea voudrait vous parler de nouveau si vous avez le temps. Elle est dans le temple de la Lune à Darnassus. Allez là-bas, et que la Lumière soit avec vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5713] = {title = "Un tir. Un tué", objective = "Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale.", description = "J’étais en route pour Auberdine chargé d’un message important quand le furbolg Marosh et ses traqueurs m’ont attaqué. Au cours du combat, j’ai été empoisonné et je peux maintenant à peine me tenir debout. Je peux préparer un antidote, mais cela va prendre du temps avant qu’il ne soit prêt.\n\nJ’aimerais vous demander de me defendre jusqu’à ce que je puisse m’administrer l’antidote. Je vous aiderai avec mon arc du mieux que je peux.\n\nSi nous survivons, je pourrai porter mon message à Auberdine, pendant que vous parlerez avec Onaeya au poste de Maestra pour l’informer de cet incident.", progress = nil, completion = "Vous apportez des nouvelles bienvenues, &lt;classe&gt;. Content d'entendre qu'Aynasha est en vie, grâce à vous. J'espère bien que vous accepterez une récompense pour votre valeur. Qu'Elune éclaire votre chemin et guide vos pas.", rewards = "Vous recevrez :\n\n"},
[5721] = {title = "La bataille du Darrowshire", objective = "Placer la Liasse de reliques sur la place centrale de Darrowshire.\n\nEmpêcher la mort de Davil Lightfire, jusqu’à la mort de Horgus.\n\nEmpêcher la mort du capitaine Redpath, jusqu’à ce que Redpath le Corrompu apparaisse.\n\nVaincre Redpath le Corrompu.\n\nParler à l’esprit de Joseph Redpath, quand il apparaît sur la place centrale, puis parler à Pamela, dans sa maison.", description = "Maintenant, <nom>, vous allez participer à la bataille de Darrowshire, et vous allez sauver Joseph Redpath.\n\nPlacez cette Liasse de reliques sur la place centrale de Darrowshire ; alors les esprits de Darrowshire apparaîtront. Assurez-vous alors que les deux choses suivantes adviennent : Davil doit survivre à Horgus, et Redpath doit survivre pour être corrompu, puis être vaincu.\n\nQuand vous aurez vaincu Redpath, après qu’il a été corrompu, son esprit sera sauvé. Parlez-lui, puis retournez voir sa fille Pamela.", progress = nil, completion = "Le combat est terminé ! J'ai entendu mon père me murmurer quelque chose. Il a fait fuir tous les fantômes et il dit qu'il revient à la maison ! Je suis si heureuse !\n\nIl m'a aussi dit qu'il vous accueillera si vous passez à la maison, alors je vais vous faire du thé !\n\nJ'espère que vous l'aimez bien sucré !", rewards = "Vous recevrez :\n\nThé sucré"},
[5722] = {title = "À la recherche de la sacoche perdue", objective = "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant.", description = "Les troggs ne sont pas la seule chose qui intéresse Magatha dans le Gouffre de Ragefeu. Elle a entendu dire que l’un de ses serviteurs, un certain Maur Grimtotem, a trouvé quelque chose d’étrange dans le Gouffre, mais il n’a jamais pu en sortir pour le lui montrer. Elle aimerait qu’on retrouve le corps de Maur, s’il existe encore, ainsi que tout signe de ce qu’il avait trouvé quand il a essayé de parler aux troggs.\n\nRapportez tout élément intéressant à Magatha, et je suis sûr qu’elle vous récompensera généreusement.\n\nEncore une fois, cherchez le Gouffre dans les endroits les plus sombres d’Orgrimmar.", progress = nil, completion = "Le corps semble avoir été durement roué de coups de poing ou de bâton, mais la plupart de ses vêtements et son équipement sont toujours là. On dirait que les troggs ne se soucient pas beaucoup des biens matériels.\n\nVous fouillez le cadavre à la recherche de tout ce qui pourrait aider Magatha.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5723] = {title = "Tester la force de l'ennemi", objective = "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff.", description = "Sous la cité d’Orgrimmar, des créatures solidement bâties appelées des \"troggs\" ont commencé à faire surface, provenant d’endroits bien plus profonds que les tunnels de lave. Dans sa grande bienveillance, Magatha a cherché à faire la paix avec ces créatures, mais elles se sont retournées contre ses diplomates et les ont tués. Elle ne tolère pas que le peuple tauren soit traité ainsi et considère maintenant ces créatures comme une menace envers la Horde entière.\n\nElle demande que vous mettiez fin à cette menace trogg avant qu’elle ne submerge la Horde par en-bas. Trouvez le Gouffre de Ragefeu et détruisez-les tous.", progress = nil, completion = "Je suis heureux de vous voir prendre au sérieux la tâche de Magatha. Merci, &lt;nom&gt;. Je suis sûr que les troggs auront du mal à refaire surface après une telle diminution d'effectifs.\n\nPeut-être un jour pourrons-nous comprendre d'où ils viennent et ce qu'ils veulent vraiment.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5724] = {title = "Rapporter la sacoche perdue", objective = "Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff.", description = "Vous trouvez une sacoche sous le corps du tauren. Il la tient encore serrée entre ses bras comme s’il essayait de la protéger pendant l’attaque des troggs.\n\nVous libérez la sacoche qu’il étreint, vous la placez dans votre propre équipement et vous vous préparez à quitter les tunnels et à retourner auprès de Rahauro à Thunder Bluff.", progress = "Avez-vous pu trouver quelque chose, <nom> ? Pourquoi l'un des membres de son clan devait-il mourir sans raison apparente ? Un indice serait utile.", completion = "Excellent, &lt;nom&gt;. Merci.\n\nMagatha m'a dit de vous donner ceci au cas où vous retrouveriez le membre de son clan. Prenez-le, en remerciement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards de plumes perléesBrassards de la savane\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5725] = {title = "Le pouvoir de détruire...", objective = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Undercity.", description = "Beaucoup de membres de la Légion offrent des cadeaux à leurs disciples, comme vous le savez peut-être. La Dame noire estime que certains de ces cadeaux seraient mieux placés entre ses mains plutôt qu’entres celles de ceux doués de… moins de vision.\n\nUne secte du Conseil des ombres, cachée dans les grottes sous Orgrimmar et appelée la Lame brûlante, en est un bon exemple. La Dame me dit que des membres de la Lame brûlante possèdent deux livres de magie puissants ; elle aimerait leur \"emprunter\" ces livres. Vous vous les procurerez pour elle.", progress = "Des centaines d'autres tâches m'attendent, <classe>. Avez-vous les livres ?", completion = "Bien, &lt;classe&gt;. Vous avez bien œuvré pour la Dame noire. Votre persévérance et votre ambition sont d'une grande utilité aux sujets de notre dame. Revenez me voir une autre fois. Peut-être aurai-je d’autres tâches à vous confier afin de l'aider dans ses tentatives pour renverser le roi-liche et de libérer ainsi le Fléau.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPantalon fantomatiqueJambières des vasièresJambières des Gargouilles\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5726] = {title = "Ennemis cachés", objective = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar.", description = "Je ne tolérerai pas qu’il y ait des traîtres parmi nous, <nom>. Mais cela serait idiot de dévoiler mon jeu si tôt : cela ne débarrasserait pas suffisamment nos terres de la corruption et ne ferait qu’empirer cette infection.\n\nMais vous, jeune <aventurier/aventurière>, vous pourriez vous rendre là où mes agents ne peuvent pas... vous pourriez apprendre la vérité... vous pourriez identifier la vraie tête de la bête.\n\nSi vous avez assez de courage, allez au Rocher du crâne à l’est d’Orgrimmar, trouvez un insigne de lieutenant auprès de l’un des membres de la Lame ardente qui s’y trouvent, et revenez me voir.", progress = "Avez-vous l'insigne, <nom> ? \n\nCe serait un outil vital pour que vous infiltriez ce que je crois être la plus grande menace contre la Horde, et pour que nous trouvions enfin la paix sur notre nouvelle terre.\n\nVous découvrirez combien la toile tissée par les orcs et les hommes peut être complexe quand ils sont motivés par la cupidité et le pouvoir. Les complots, la corruption, tout cela vous apparaîtra clairement. Vous vous trouverez au coeur d'une guerre dont vous ne soupçonniez pas même l'existence.", completion = "Bien, &lt;nom&gt;. Loués soient les esprits, vous serez peut-être celui qui mettra fin à mes plus grandes craintes ! Qui aurait pu penser qu'une personne si jeune et si brave deviendrait le champion de notre cause ? Vous me rappelez moi, à votre âge. Je m'assurerai que vous soyez dûment récompensé de vos efforts si nous survivons tous deux à l'orage qui s'annonce.\n\nMais les félicitations peuvent attendre. Vous n'avez encore rien accompli en comparaison de ce qui vous attend... mais c'est un bon début.", rewards = "Vous recevrez :\n\n"},
[5727] = {title = "Ennemis cachés", objective = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.", description = "Maintenant voyons voir si cet Insigne que vous avez trouvé en valait la peine.\n\nIl y a un démoniste dans la cité qui pense avoir ma confiance. Il ne sait pas que j'ai compris qu’il était loyal à d’autres. En fait, c’est lui le chef de la Lame ardente. Mais ne vous précipitez pas à sa poursuite ; il peut nous servir contre nos ennemis.\n\nApportez-lui cet insigne dans la Faille de l'ombre ici à Orgrimmar, parlez-lui et voyez s’il croit que vous êtes l’un des leurs, puis revenez me voir.", progress = nil, completion = "Excellent ! Simplement excellent, &lt;classe&gt; !\n\nTout ce que vous avez récemment accompli ne sont que les fondations d'un dessein plus grand, sur lesquelles nous construirons la destruction définitive du Conseil des ombres.\n\nDites-moi tout ce qu'il a dit…et n'omettez pas le moindre mot, il pourrait être plus important que vous ne le croyez.", rewards = "Vous recevrez :\n\n"},
[5728] = {title = "Ennemis cachés", objective = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar.", description = "Hmm, des chefs de la Lame brûlante... cela m’inquiète beaucoup. S’ils sont utiles à Neeru, alors ce sont eux qu’il faut viser en premier. Ce satyre... Bazzalan, et l’autre que Neeru a mentionné - qu’est-il, un démoniste ? - doivent être tués.\n\nRetournez à la Faille de l'ombre et pénétrez dans le gouffre de Ragefeu, <nom>. Trouvez ces deux chefs de la Lame brûlante et tuez-les. Mais faites attention à ce que Neeru ne sache pas que c’est vous le responsable. Il faut que vous conserviez votre identité en tant que <frère/sœur> de combat.", progress = nil, completion = "Je suis content de vous voir de retour, &lt;nom&gt;. Certains de mes fidèles m'ont immédiatement rapporté le chaos régnant dans les cavernes d'Orgrimmar maintenant que leur chef a été occis. On m'a même rapporté que Neeru était plus qu'agité. On dirait que nous avons ébréché son armure. Je ne peux pas me dire insatisfait... même si c'était une victoire mineure.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5729] = {title = "Ennemis cachés", objective = "Parler à Neeru Fireblade à Orgrimmar.", description = "Je pense que la prochaine étape devrait être de vous placer près de Neeru. S'il est aussi agité que le suggèrent les rapports, nous pourrions accomplir deux choses. D'abord, vous pourriez en apprendre davantage sur le Conseil ou au moins sur la Lame ardente. Ensuite, il se peut qu'il vous fasse suffisamment confiance pour qu'il vous demande de lui venir en aide. Il pourrait vous considérer comme quelqu'un capable d'occuper une place vacante à présent que sa direction connaît un grand bouleversement.\n\nRetournez à la Faille et parlez-lui à nouveau, mais dissimulez bien votre jeu.", progress = nil, completion = "Qu'est-ce que c'est ?! Oh, vous, &lt;classe&gt;… Mes excuses. Ma colère est celle d'un kodo enragé… mais peut-être est-ce de ma faute. En envoyant des voyageurs au gouffre de Ragefeu, j'aurais pu prévoir que des difficultés surviendraient. Il semble que Bazzalan et Jergosh aient été pris par surprise et massacrés par des sbires de Thrall. Tout à fait importun, mais il n'y a rien à faire à cela pour le moment.", rewards = "Vous recevrez :\n\n"},
[5730] = {title = "Ennemis cachés", objective = "Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris.", description = "Vous êtes l’un de mes lieutenants ! Préparez-vous, <classe>. Je ferai bientôt appel à vous.\n\nLe temps que j’ai passé sur la Lame brûlante est peut-être du temps perdu maintenant, mais cela ne veut pas dire que les plans du Conseil des ombres ailleurs doivent en pâtir. Je vais faire mon possible pour limiter les dégâts ici dans le Gouffre de Ragefeu. Pendant ce temps, mes agents dans les Tarides et Ashenvale vont commencer à travailler à nos nouveaux plans. Revenez vite me voir.", progress = nil, completion = "Ashenvale ? Hm, Je n'ai pas entendu parler de la présence du conseil ou de la Lame ardente à Ashenvale. Mes espions vont enquêter, &lt;nom&gt;. Vous avez bien agi.\n\nPour l'instant, reposez-vous et occupez-vous. Je vous appellerai bientôt.\n\nLok-Tar Ogar !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nKris d'OrgrimmarMarteau d'OrgrimmarHache d'OrgrimmarBâton d'Orgrimmar\n\nVous recevrez également :\n\n"},
[5741] = {title = "Sceptre de lumière", objective = "Prendre le Sceptre de lumière et le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor.", description = "D'après ce qu'on dit, les sectateurs de la Lame ardente, dans la forteresse de Hache-Tonnerre, à l'est, aurait réussi à obtenir le Sceptre de lumière des nagas. La légende dit que ce sceptre est capable d'engloutir des villes entières sous la mer. On ne doit pas permettre à la Lame ardente de posséder une telle puissance.\n\nC'est pour cela que vous devez récupérer le sceptre ! Il est détenu par le Prophète de la Lame ardente, qui l’étudie sous la protection des gardiens de la tour de Hache-Tonnerre.", progress = "Avez-vous le Sceptre de Lumière ?", completion = "L'insaisissable Sceptre de lumière ! De l'avoir récupéré permet d'écarter une grande menace de la face du monde. Bien joué, &lt;classe&gt;, bien joué.", rewards = "Vous recevrez :\n\n"},
[5742] = {title = "Rédemption", objective = "Écouter ce que Tirion Fordring a à dire.", description = "Vous avez travaillé dur, mon <ami/amie>. Reposez vos os fatigués et permettez-moi de me présenter correctement.", progress = "Je vous en prie, asseyez-vous et écoutez mon histoire.", completion = "La rédemption de Fordring sera une tâche difficile. Êtes-vous prêt ?", rewards = "Vous recevrez :\n\n"},
[5761] = {title = "Tuer la bête", objective = "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar.", description = "La tâche première qui m’a été assignée par notre grand chef de guerre est d’éliminer les créatures responsables de l’infection de la grande cité de notre seigneur par des influences démoniaques. La Lame ardente est une menace, mais il y en a d’autres ; la Lame brûlante par exemple, qui est basée dans le gouffre de Ragefeu, essaie de subvertir en secret des membres innocents de la Horde.\n\nPour les arrêter, il faut tuer leur chef, un gangregarde appelé Taragaman l'Affameur.\n\nTuez-le, et son cœur apaisera Thrall, j’en suis sûr.", progress = "Avez-vous tué la bête ? C'est certainement le chef de la Lame brûlante dans le gouffre de Ragefeu.", completion = "Ah ! Vous avez réussi ! Thrall va être ravi.\n\nJe vais m'assurer que l'on prendra soin de ce cœur convenablement.\n\nPour l'instant, vous devez célébrer votre victoire. Je vais informer Thrall de votre réussite.\n\nMerci pour votre aide, &lt;classe&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5762] = {title = "Hemet Nesingwary", objective = "Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce.", description = "J’ai un colis pour un vieux client. C’est un nain qui répond au nom de Hemet Nesingwary. Le colis a mis deux semaines à arriver, et Hemet est déjà reparti depuis longtemps. Il a dit qu’il allait à Strangleronce pour y chasser ; il a toutefois pris soin de laisser un peu d’argent pour que je lui fasse livrer son colis, dès que celui-ci arriverait. \n\nHemet est un nain fortuné ; il est bon de le garder comme un client fidèle. Vous voyez ce que je veux dire, n’est-ce pas ? Bon, acceptez-vous de lui livrer son colis pour moi ?\n\nJ’ai entendu dire que Hemet possède un camp à Strangleronce, au nord de Grom'gol.", progress = "Est-ce là de la poussière du désert sur votre col ?\n\nHm… Si mon nez ne me trompe pas, je dirais que ce n'est pas de la poussière du désert, mais du sel du désert ! Vous êtes allé dans les Salines, n'est-ce pas ?", completion = "Grandiose, mon paquet de Koalbeard ! Merci &lt;nom&gt;. Cette caisse contient des munitions d'un calibre spécial, elles nous seront utiles dans la jungle !\n\nVoici votre paie, et dites-moi, comment va le vieux Kravel ces jours-ci ? Toujours râleur, je parie...", rewards = "Vous recevrez :\n\n"},
[5763] = {title = "Chasse à Strangleronce", objective = "Apporter la Corne de kodo de Roon à Hemet Nesingwary à Strangleronce.", description = "Il y a longtemps de cela, un nain arriva dans cette contrée. Il s’appelait Hemet et voulait chasser des créatures puissantes. Son maniement du fusil était excellent, et nous passâmes plusieurs jours à chasser ensemble. Même l’animosité entre nos deux peuples avait été oubliée.\n\nQuand il partit de Désolace pour Strangleronce, j’ai juré qu’un jour je l’accueillerais de nouveau et que nous chasserions encore une fois ensemble. Le temps est venu.\n\nApportez cette corne de kodo à Hemet. Il saura que c’est de ma part. Vous le trouverez en Strangleronce, au nord du Campement Grom'gol.", progress = "Asseyez-vous, <classe>. Vous retournerez dans la jungle bien assez tôt.", completion = "Ah, cette corne appartient à un tauren, Roon Wildmane. Nous avons eu plaisir à chasser ensemble les bêtes de Désolace. Alors Roon me rend l'invitation, c'est ça ?\n\nNous sommes dans la jungle jusqu'au cou, mais merci &lt;nom&gt;. Peut-être que ma prochaine expédition m'emmènera vers Désolace, le pays des centaures.", rewards = "Vous recevrez :\n\n"},
[5781] = {title = "Aux mémoires perdues", objective = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission.", description = "Pour aider Taelan à récupérer ce qu’il a perdu, vous devez rassembler des éléments de son passé.\n\nLe premier objet est un jouet que je lui avais offert pour son 7e anniversaire. C’était son trésor : un marteau de guerre miniature, une copie exacte du mien.\n\nAprès que j’ai été banni pour trahison, sa mère lui a dit que j’étais mort. On l’a emmené sur ma fausse tombe dans le caveau de Zaeldarr, où il a enterré le marteau ainsi que mon souvenir – pour toujours.\n\nVous devez vous aventurer dans le caveau et récupérer le marteau de Taelan.", progress = "Il doit être sauvé.", completion = "&lt;Tirion cligne des yeux afin de retenir ses larmes.&gt;\n\nLe destin a voulu notre rencontre, &lt;nom&gt;. Vous m'avez béni par votre bonté.", rewards = "Vous recevrez :\n\n"},
[5801] = {title = "Forgée dans la Fournaise", objective = "Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un'Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée.\n\nApporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.", description = "Vous avez besoin de deux barres de thorium et d’une source de chaleur intense pour forger la tige de la clé. Pour le thorium, il faudra vous débrouiller <tout seul/toute seule>, mais je peux vous aider pour la chaleur.\n\nA l’ouest d’ici, dans le cratère d'Un'Goro, se trouve la crête de la Fournaise – un volcan bouillonnant. Le lac de lave à son sommet est assez chaud pour fondre le thorium et les os ensemble. Votre or vous a permis d’acheter un moule que vous n’avez qu’à tremper dans le lac du sommet ; la lave se chargera du reste.\n\nC’est tout ce que je peux vous dire. Pour finir votre clé, il faudra retourner parler à Arbington.", progress = "Avez-vous terminé la tige de la Clé squelette ? Je suis désolé que vous ayez dû supporter le coût du moule, mais nous devons tous faire notre part dans la lutte contre le Fléau. Quand vous m'aurez donné la clé inachevée, vous serez prêt pour le dernier élément nécessaire à sa finalisation.\n\nÇa ne sera pas facile du tout, mais le travail que vous avez accompli jusqu'à présent pour préparer l'assaut sur Andorhal va commencer à payer maintenant. Vous verrez.", completion = "On a bien la coûteuse Clé squelette ici, non, &lt;nom&gt; ? Enfin, elle est presque finie ; le temps est venu de nous pencher sur la suite. Pour cela, vous allez affronter l'adversaire le plus terrible que nous ayons cherché à rencontrer à Andorhal... Cet être funeste mène la danse derrière les murs de la cité en ruines.\n\nJe veux parler d'Araj l'invocateur - une Liche, et une des plus puissantes entités que le Fléau revendique comme sienne.", rewards = "Vous recevrez :\n\n"},
[5802] = {title = "Forgée dans la Fournaise", objective = "Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.\n\nApporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, Maleterres de l'Ouest.", description = "Vous avez besoin de deux barres de thorium et d’une source de chaleur intense pour forger la tige de la clé. Pour le thorium, il faudra vous débrouiller <tout seul/toute seule>, mais je peux vous aider pour la chaleur.\n\nA l’ouest d’ici, dans le cratère d'Un'Goro, se trouve la crête de la Fournaise – un volcan bouillonnant. Le lac de lave à son sommet est assez chaud pour fondre le thorium et les os ensemble. Votre or vous a permis d’acheter un moule que vous n’avez qu’à tremper dans le lac du sommet ; la lave se chargera du reste.\n\nC’est tout ce que je peux vous dire. Pour finir votre clé, il faudra retourner parler à Dithers.", progress = "Avez-vous terminé la tige de la Clé squelette ? Je suis désolé que vous ayez dû supporter le coût du moule, mais nous devons tous faire notre part dans la lutte contre le Fléau. Quand vous m'aurez donné la clé inachevée, vous serez prêt pour le dernier élément nécessaire à sa finalisation.\n\nÇa ne sera pas facile du tout, mais le travail que vous avez accompli jusqu'à présent pour préparer l'assaut sur Andorhal va commencer à payer maintenant. Vous verrez.", completion = "On a bien la coûteuse Clé squelette ici, non &lt;nom&gt; ? Enfin, elle est presque finie ; le temps est venu de nous pencher sur la suite. Pour cela, vous allez faire face à l'adversaire le plus terrible que nous ayons cherché à rencontrer à Andorhal... cet être funeste mène la danse à l'intérieur des murs de la cité en ruines.\n\nJe veux parler d'Araj l'invocateur - une Liche, et une des plus puissantes entités que le Fléau revendique comme sienne.", rewards = "Vous recevrez :\n\n"},
[5803] = {title = "Le Scarabée d'Araj", objective = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.", description = "Araj l’Invocateur règne sur Andorhal depuis le cœur de la cité en ruines. Nous savons qu’il était l’ancien chef de Scholomance avant de s'approprier la cité. Pour finir la clé, nous avons besoin de sa chevalière – appelée Scarabée – pour en faire la tête de la clé.\n\nIntroduisez-vous au cœur d'Andorhal, et brisez l’emprise d’Araj sur la cité, maintenant qu'il a été amené à se découvrir. Quand vous l'aurez détruit, emparez-vous de son scarabée contenu dans le petit sac qu’il aura laissé tomber !\n\nLa clé de la Scholomance vous attend, <nom> !", progress = "Vous avez parcouru tant de route, <nom>... Mais seule la destruction de la forme physique d'Araj l'invocateur nous permettra de terminer la clé. Emparez-vous du Scarabée d'Araj par tous les moyens en votre pouvoir et apportez-le-moi. Je le fondrai au sommet de la clé.", completion = "Oui, c'est ça ! Je… une fois encore, je suis ébloui par votre héroïsme. Penser aux extrémités auxquelles vous pouvez aller pour atteindre la victoire sur les forces des ténèbres est simplement étourdissant.\n\nPermettez-moi de jouer mon petit rôle dans tout cela. J'ai préparé un solvant spécial qui devrait me permettre de fixer solidement le scarabée au sommet de la clé, lui donnant ainsi le pouvoir de forcer les portes closes de Scholomance.\n\nTrois fois rien...", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5804] = {title = "Le Scarabée d'Araj", objective = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’apothicaire Dithers à la Barricade, dans les Maleterres de l’ouest.", description = "Araj l’Invocateur règne sur Andorhal depuis le cœur de la cité en ruines. Nous savons qu’il était l’ancien chef de Scholomance avant de s'approprier la cité. Pour finir la clé, nous avons besoin de sa chevalière – appelée Scarabée – pour en faire la tête de la clé.\n\nIntroduisez-vous au cœur d’Andorhal, et brisez l’emprise d’Araj sur la cité, maintenant qu’il a été amené à se découvrir. Quand vous l’aurez détruit, emparez-vous de son scarabée contenu dans le petit sac qu’il aura laissé tomber !\n\nLa clé de la Scholomance vous attend, <nom> !", progress = "Vous avez parcouru tant de route, <nom>... Mais seule la destruction de la forme physique d'Araj l'invocateur nous permettra de terminer la clé. Emparez-vous du Scarabée d'Araj par tous les moyens en votre pouvoir et apportez-le-moi. Je le fondrai au sommet de la clé.", completion = "Oui, c'est ça ! Je… une fois encore, je suis ébloui par votre ruse et votre bravoure. Penser aux extrémités auxquelles vous êtes prêt à aller pour atteindre la victoire est simplement étourdissant.\n\nPermettez-moi de jouer mon petit rôle dans tout cela. J'ai préparé un solvant spécial qui devrai me permettre de fixer solidement le scarabée au sommet de la clé, lui donnant ainsi le pouvoir de forcer les portes closes de Scholomance.\n\nCela ne devrait prendre qu'un instant....", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5805] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Northshire) à Merissa Stilwell.", description = "Bienvenue dans World of Warcraft !\n\nEn gage de remerciement spécial pour avoir acheté World of Warcraft Collector's Edition, apportez ce bon à Merissa dans la Vallée de Northshire. On vous remettra alors un cadeau : un petit compagnon pour se joindre à vous dans votre quête d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !", progress = "Salutations ! C'est un plaisir de vous rencontrer !\n\nJe vois que vous avez un bon spécial. Donnez-le-moi et je vous offrirai quelque chose en échange.", completion = "Vous êtes un héros d'exception, &lt;nom&gt;. Bienvenue dans le monde d'Azeroth, nous vous offrons l'un de ces présents uniques !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5821] = {title = "Garde du corps à recruter", objective = "Escorter la Caravane de Gizelton et l’aider à passer le village des centaures Kolkar. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense.", description = "En temps normal, Rigger et moi conduirions nos kodos à travers le territoire des centaures Kolkar. Mais depuis quelque temps, nous entendons résonner les tambours de guerre des centaures. Comme il n’est jamais bon pour les affaires d’être mort, nous préférons ne pas nous aventurer plus avant sur leurs terres !\n\nSi vous acceptiez de nous protéger, <classe>, et nous aidiez à passer au-delà du village des Kolkar, nous vous récompenserions en conséquence.\n\nCela ne représente pas une si grande distance ; vous devrez simplement sécuriser la caravane, puis vous pourrez toucher votre dû des mains de Smeed Scrabblescrew, qui est un peu plus bas sur la route. Nous faisons souvent des affaires ensemble.", progress = nil, completion = "Vous savez, ça ne paraît pas très intéressant de payer quelqu'un comme vous pour escorter la caravane de Gizelton. &lt;classe&gt;, si j'étais plus grand, je pourrais aussi m'installer sur mon kodo avec le plus gros fusil que ma main puisse tenir, et j'apprendrais à ces satanés centaures qui est le maître.", rewards = "Vous recevrez :\n\nAnneau des marchands"},
[5841] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Vallée des Frigères) à Yori Crackhelm.", description = "Bienvenue dans le monde de World of Warcraft !\n\nPour vous remercier d'avoir acheté l'édition collector de World of Warcraft, allez voir Yori Crackhelm dans la Vallée des Frigères avec ce bon. Il vous offrira un petit compagnon qui vous accompagnera dans vos quêtes d'aventure et de gloire.\n\nMerci encore et profitez bien de votre séjour dans World of Warcraft !", progress = "Bonjour ! Quel plaisir de vous rencontrer !\n\nJe vois que vous avez un bon spécial. Donnez-le-moi et je vous donnerai quelque chose en échange.", completion = "Vous êtes un héros d'exception, &lt;nom&gt;. Bienvenue dans le monde d'Azeroth, nous vous offrons l'un de ces présents uniques !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5842] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Sombrevallon) à Orenthil Whisperwind.", description = "Bienvenue dans World of Warcraft !\n\nEn gage de remerciement spécial pour avoir acheté World of Warcraft Collector's Edition, apportez ce bon à Orenthil Whisperwind dans Sombrevallon. On vous remettra alors un cadeau : un petit compagnon pour se joindre à vous dans votre quête d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5843] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Vallée des Epreuves) à Magga.", description = "Bienvenue dans World of Warcraft !\n\nEn gage de remerciement spécial pour avoir acheté World of Warcraft Collector's Edition, apportez ce bon à Magga dans la Vallée des épreuves. On vous remettra alors un cadeau : un petit compagnon pour se joindre à vous dans votre quête d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5844] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Camp Narache) à Vorn Skyseer.", description = "Bienvenue dans World of Warcraft !\n\nEn gage de remerciement spécial pour avoir acheté World of Warcraft Collector's Edition, apportez ce bon à Vorn Skyseer au Camp Narache. On vous remettra alors un cadeau : un petit compagnon pour se joindre à vous dans votre quête d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5845] = {title = "De l'honneur perdu", objective = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.", description = "L’ordre de la Main d'argent fut complètement décimé quand Uther fut tué.\n\nLe garçon tint bon aussi longtemps qu’il put. Repoussé jusqu’au hameau de Valnord ravagé par la guerre, il y livra son ultime combat.\n\nRestait-il encore des survivants de l’ordre, pensa-t-il, et cela avait-il encore de l'importance ?\n\nC'est en pensant cela que Taelan jeta à terre l’étendard de l’ordre et renia tout ce qu’il avait jamais connu. Son honneur abandonné sur le sol gorgé de sang de Valnord.\n\nIl faut vous rendre à Valnord pour récupérer ce symbole d’honneur perdu.", progress = "Ma foi vous guidera, <nom>. La Lumière ne connaît pas de frontières.", completion = "Il est aussi glorieux -malgré son piteux état- qu'au jour où j'ai formé mon vœu d'allégeance en le regardant.\n\nSa rédemption arrive et peut-être la mienne avec…", rewards = "Vous recevrez :\n\n"},
[5846] = {title = "L'amour et la famille", objective = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau.", description = "Quand Taelan était enfant, nous allions souvent à Caer Darrow pour une promenade en famille. Au cours de notre dernière visite, une artiste nommée Renfray peignit un portrait de nous sur la plage. C’est mon souvenir le plus cher de Taelan et Karandra. Car c’est à ce moment, avec ma femme et mon fils dans mes bras, que je sentis un lien d’amour et familial que je n’ai jamais plus connu depuis.\n\nSi ce tableau existe encore, il faut que vous le trouviez.\n\nRendez vous jusqu’à l’île délabrée de Caer Darrow et voyez si le tableau ou l’artiste s’y trouvent encore.", progress = nil, completion = "Comment pourrais-je oublier ? De nombreux esprits de cette île sont condamnés à revivre leur dernier souvenir heureux avant leur fin tragique.\n\nJe suis maudite moi aussi, mais pas comme eux - je suis l'un de ceux qui se souviennent de tout.\n\nPeut-être que cette chose que vous me demandez est la raison pour laquelle je hante ces ruines. Peut-être que ce que je suis en train de vous dire est ce qui va me libérer.", rewards = "Vous recevrez :\n\n"},
[5847] = {title = "Bienvenue !", objective = "Apporter le Bon-cadeau (Le Glas) à Claire Willower, au Glas.", description = "Bienvenue dans World of Warcraft !\n\nEn gage de remerciement spécial pour avoir acheté World of Warcraft Collector's Edition, apportez ce bon à Claire Willower au Glas. On vous remettra alors un cadeau : un petit compagnon pour se joindre à vous dans votre quête d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !", progress = "Salutations ! C'est un plaisir de vous rencontrer !\n\nJe vois que vous avez un bon spécial. Donnez-le-moi et je vous offrirai quelque chose en échange.", completion = "Vous êtes un héros d'exception, &lt;nom&gt;. Bienvenue dans le monde d'Azeroth, nous vous offrons l'un de ces présents uniques !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre de DiabloCollier de pandaLaisse de zergling"},
[5848] = {title = "De l'amour et de la famille", objective = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\n\nRapporter le tableau à Tirion Fordring.", description = "Le tableau… Il a été accroché au mur de mon atelier - dans la caserne de l'Ordre - pendant des années.\n\nAprès le procès de Tirion, je savais que je ne pouvais pas le laisser là, à la vue de tout le monde. Je l'ai caché dans un endroit où personne ne pensera aller chercher.\n\nAllez à Stratholme, enfoncez-vous profondément dans ce qu'on nomme maintenant le Bastion écarlate et cherchez un tableau représentant nos lunes jumelles. Grattez la peinture pour révéler mon chef-d’oeuvre, De l'amour et de la famille.\n\nQue la Lumière guide vos actions.", progress = "La peinture, <nom>. Avez-vous la peinture ?", completion = "&lt;Tirion manque de s'effondrer lorsqu'il aperçoit la peinture.&gt;\n\n&lt;Il commence à sangloter de façon frénétique.&gt;", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5861] = {title = "Trouver Myranda", objective = "Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion.", description = "<nom>, vous avez accompli tout ce que je vous ai demandé de faire jusqu'à présent. Il n'y a plus qu'une dernière étape à franchir dans votre quête de rédemption.\n\nVous devez amener les éléments que vous avez récoltés à Taelan. Malheureusement, Taelan et ses croisés écarlates vous attaqueront en vous voyant.\n\nIl n'y a qu'une façon de remettre mon message, sous couvert d'une supercherie.\n\nAu sud, vous trouverez le tombeau d'Uther. Une vieille amie en qui j'ai toute confiance, Myranda, vit là-bas – allez la trouver. Montrez-lui vos objets et elle vous aidera.", progress = "Je savais que ce jour arriverait.", completion = "J'étais la plus proche conseillère de Tirion alors qu'il était le seigneur de Mardenholde. J'ai ouvertement contesté le verdict rendu par l'ordre de la Main d'Argent, et je fus bannie pour mon insolence.\n\nIl a connu trop de tragédies de déceptions, &lt;nom&gt;. Êtes-vous prêt à réparer les torts faits aux Fordring ?", rewards = "Vous recevrez :\n\n"},
[5862] = {title = "Le subterfuge écarlate", objective = "Parler à Myranda pour obtenir l’Illusion écarlate. Aller à Hearthglen pendant que vous êtes sous l’effet de l’Illusion écarlate, et apporter le Don de Tirion au généralissime Taelan Fordring.\n\nHearthglen se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde.", description = "Je suis ce qu'on peut appeler une illusionniste. Bien que je puisse créer une illusion vous permettant de pénétrer dans Hearthglen, sachez que mes pouvoirs ont leurs limites.\n\nSi vous vous éloignez trop d'ici, les effets de l'illusion prendront fin. Le sort en lui-même requiert beaucoup de concentration et de puissance de ma part, c'est pourquoi je ne peux établir l'illusion que pour une courte période.\n\nParlez-moi de nouveau quand vous serez <prêt/prête>.", progress = "Êtes-vous les renforts de la Main de Tyr ?", completion = "Quoi, soldat ?\n\n&lt;Taelan ouvre la boîte et examine son contenu.&gt;\n\nCe…ne peut être vrai. Mais tout ce que vous m'avez montré…\n\n&lt;Taelan tombe sur un genou, son pouls s'accélère. La furie du temps est prête à engloutir cette ville.&gt;", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[5863] = {title = "La base des Cognedunes", objective = "Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur.", description = "Encore récemment, une grande bande d'ogres nomades est arrivée à Tanaris. Au sud d'ici ; ils se sont arrogés une importante zone du désert et ont formé une base. Plusieurs autres bandes plus petites vagabondent actuellement dans le désert, et certaines d'entre elles ont envahi les vieilles ruines trolls.\n\nLa base des Cognedunes doit être détruite ! Nous ne pouvons pas laisser ces ogres se renforcer.\n\nLe meneur de cette bande est appelé Gor'marok le Ravageur ; je pense que mettre fin à son règne serait le début de la fin pour les ogres.", progress = nil, completion = "Je suis si heureuse que vous ayez pu faire cela pour moi, &lt;nom&gt; ! Merci de votre aide !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de sèchegraineMantelet en bois d'acacia\n\nVous recevrez également :\n\n"},
[5881] = {title = "Puiser dans les réserves", objective = "Maggran voudrait que vous apportiez une lettre à Grish Longrunner, à la Grande élévation, dans les Tarides.", description = "La Horde a bien fait de garder nos troupes fraîches... Depuis la Grande Guerre, nous avons prospéré ici, à Kalimdor.\n\nJe voudrais que vous me fassiez une faveur : j'ai un gars du nom de Grish Longrunner qui protège la Grande élévation dans les Tarides du Sud. Donnez-lui cette lettre. Elle lui fait savoir que j'envoie un guerrier pour le remplacer, afin qu'il puisse aller voir sa famille. Il m'a demandé à être relevé il y a quelque temps et il sera heureux d'apprendre cette nouvelle.", progress = "Avez-vous des nouvelles de Maggran Earthbinder ?", completion = "C'est une grande nouvelle ! Je suis resté trop longtemps assis ici à garder ce morceau de bois. Maintenant je peux passer du temps avec ma famille... Youpii !", rewards = "Vous recevrez :\n\n"},
[5882] = {title = "Du baume en chassant", objective = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume que j'ai déjà préparé.", description = nil, progress = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume que j'ai déjà préparé.", completion = "Très bien donc, voici du Baume végétal cénarien. Fouillez Gangrebois pour trouver ces plantes corrompues, &lt;nom&gt; ! Utilisez ce Baume pour purifier toutes celles que vous trouverez.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5883] = {title = "Du baume par la pioche", objective = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", completion = "Très bien. Voici plusieurs doses de Baume végétal cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux préparer de baume.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5884] = {title = "Du baume contre une récolte", objective = "Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé.", description = nil, progress = "Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé.", completion = "Excellent travail, &lt;nom&gt;. Chacune d'elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5885] = {title = "Du baume contre des peaux", objective = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", description = nil, progress = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", completion = "C'est exactement ce dont j'ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et utilisez-les pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5886] = {title = "Du baume contre des désenchantements", objective = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", description = nil, progress = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", completion = "Voilà quelques doses de Baume végétal cénarien. Il ne manque plus qu'une Essence du néant inférieure, &lt;nom&gt;. Cette essence est de loin l’ingrédient le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5887] = {title = "Du baume en chassant", objective = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.\n\nEn échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé.", completion = "Très bien, voici des doses de Baume végétal cénarien. Fouillez Gangrebois à la recherche de toutes les plantes corrompues, &lt;nom&gt; ! Où qu'elles soient, utilisez le Baume pour les purifier.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5888] = {title = "Du baume par la pioche", objective = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", description = nil, progress = "Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.\n\nSi vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé.", completion = "Très bien. Voici plusieurs doses de Baume végétal cénarien. Si vous trouvez plus de vitriol en minant dans Gangrebois, gardez-le-moi ! Plus vous en trouvez, plus je peux préparer de baume.", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5889] = {title = "Du baume contre une récolte", objective = "Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé.", description = nil, progress = "Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.\n\nLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé.", completion = "Excellent travail, &lt;nom&gt;. Chacune d'elles, une fois purifiée, nous aidera à sauver Gangrebois. Tenez, prenez quelques doses de Baume végétal cénarien et rendez-vous dans la forêt. La reconquête de cette terre est une priorité, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5890] = {title = "Du baume contre des peaux", objective = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", description = nil, progress = "Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !\n\nLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve.", completion = "C'est exactement ce dont j'ai besoin. Tenez, prenez ces deux doses de baume végétal cénarien et utilisez-les pour guérir les plantes de Gangrebois de la corruption. Nous devons persévérer, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5891] = {title = "Du baume contre des désenchantements", objective = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", description = nil, progress = "Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.\n\nJe n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !", completion = "Voilà quelques doses de baume végétal cénarien. Il ne manque plus qu'une essence du néant inférieure, &lt;nom&gt;. Cette essence est de loin l’ingrédient le plus puissant que je puisse utiliser pour transformer les épées en socs de charrue. Si vous avez besoin de plus de baume, revenez me voir !", rewards = "Vous recevrez :\n\nBaume végétal cénarien"},
[5892] = {title = "Fournitures de Gouffrefer", objective = "Apporter 10 Fournitures de Gouffrefer à l’Intendant de l'Alliance de Dun Baldar.", description = "Avant que les combats ne commencent, nous avons stocké du matériel pour Dun Baldar dans la mine de Gouffrefer. Les troggs qui ont débarqué ne représentaient pas un grand problème tant que nous disposions de troupes pour surveiller la mine, mais maintenant que nous nous battons contre la Horde, nous ne pouvons plus en garder le contrôle.\n\nNous avons besoin du matériel qui se trouve à Gouffrefer, <nom>. Entrez dans la mine et rapportez-m'en un chargement.", progress = "Avez-vous les fournitures, <nom> ? Nous n'en aurons jamais trop !", completion = "Bien joué ! J'en ferai bon usage. Merci, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[5893] = {title = "Fournitures de Froide-dent", objective = "Apporter 10 Fournitures de Froide-dent à l’intendant de la Horde, au donjon Frostwolf.", description = "La mine de Froide-dent au nord était autrefois l'endroit idéal pour stocker des réserves de matériel, mais maintenant que les combats contre les Stormpike deviennent de plus en plus violents, nous n'avons pas toujours assez de guerriers pour en stationner à la mine pour la protéger. Le contrôle de la mine passe donc souvent à l'Alliance ou à ses habitants souterrrains...\n\nMais nous avons grand besoin de nos fournitures, <nom> ! Allez à la mine de Froide-dent et rapportez-m'en un chargement. Et prenez garde aux ennemis en chemin. L'équilibre des forces en présence peut changer très vite là-bas...", progress = "Êtes-vous allé dans la mine de Froide-dent, <nom> ? Avez-vous les fournitures que je vous ai demandées ?", completion = "Ah, vous les avez. Bon travail, &lt;nom&gt; ! Ces fournitures sont un peu moisies d'avoir été stockées dans cette sombre mine si longtemps, mais elles nous seront bien utiles.\n\nMerci, &lt;nom&gt;. Vos efforts sont d'une importance vitale pour le ravitaillement de nos troupes.", rewards = "Vous recevrez :\n\n"},
[5901] = {title = "Une Plaie sur la Croisade", objective = "Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l’est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal.", description = "Ainsi, afin que la Croisade écarlate connaisse la douleur et la lutte, je veux lui prendre sa précieuse scierie. Je suis sûr que la perte d'une telle ressource va rendre beaucoup plus difficiles la défense et la reconstruction de la ville. Allez-vous m'aider, <nom> ? \n\nCommencez par vous rendre à Pestebois dans les Maleterres de l'Est. Remplissez cette fiole avec les termites que vous trouverez dans leurs monticules disséminés dans les bois. Revenez quand vous en aurez assez.", progress = "Avez-vous les Termites, <nom> ? Je suis certain que ce n'est pas un problème pour une personne aussi intelligente que vous.\n\nUne fois que nous en aurons assez, <classe>, nous nous assurerons que plus personne ne pourra utiliser cette scierie !", completion = "Cela conviendra parfaitement, &lt;nom&gt;. Merci.\n\nSi vous le désirez, nous pouvons passer à l'étape suivante.", rewards = "Vous recevrez :\n\n"},
[5902] = {title = "Une Plaie sur la Croisade", objective = "Trouver un endroit judicieux, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.\n\nObjet fourni : \n", description = "Maintenant que nous avons suffisamment de termites, portez ce tonneau cerclé d'acier à la scierie de la Crête du nord, au sud de Hearthglen. Vous la trouverez à l'ouest de la route qui mène jusqu'en ville.\n\nQuand vous y serez, placez le tonneau au cœur de la scierie, en hauteur, sur une caisse par exemple, et ouvrez-le.\n\nLe reste se fera tout seul. Revenez me voir et je vous récompenserai pour votre aide.", progress = nil, completion = "Quand vous placez le tonneau sur la caisse, les termites commencent à s'agiter.", rewards = "Vous recevrez :\n\n"},
[5903] = {title = "Une Plaie sur la Croisade", objective = "Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l’est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l’ouest.", description = "J'ai plusieurs fois essayé d'employer la force pour barrer la route à la Croisade écarlate, mais en vain. Alors j'ai décidé de lui pourrir la vie.\n\nSi vous voulez m'aider, nous allons introduire dans cette scierie les plus terribles des termites.\n\nDans Pestebois, près de Stratholme, autrefois si grande, prospère une espèce de termites qui a survécu à la fois à la peste et au Fléau. Trouvez leurs termitières et remplissez cette fiole. Nous allons les lâcher sur la Croisade...", progress = "Avez-vous trouvé des termitières, <nom> ? On m'a dit qu'elles étaient présentes dans tout Pestebois.", completion = "Cela conviendra parfaitement, &lt;nom&gt;. Merci. Regardez-les... Quel triste spectacle. J'ai presque de la pitié pour la Croisade, mais bon, ce n'était pas leur scierie, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[5904] = {title = "Une Plaie sur la Croisade", objective = "Trouver un endroit propice, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.\n\nObjet fourni : \n", description = "Maintenant que nous avons les termites, prenez ce Tonneau renforcé, et apportez-le à la scierie de la Crête du nord, au sud de Hearthglen. Vous la trouverez à l’ouest de la route qui mène à la ville.\n\nUne fois sur place, placez le Tonneau au centre de la scierie. Trouvez un endroit approprié, comme une caisse, posez-le dessus, puis ouvrez-le. Les termites feront leur travail, rongeront le bois des poutres, et rendront la scierie inutilisable pour la Croisade.", progress = nil, completion = "Quand vous placez le tonneau sur la caisse, les termites commencent à s'agiter.", rewards = "Vous recevrez :\n\n"},
[5921] = {title = "Reflet-de-Lune", objective = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", description = "Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, indépendamment des relations actuelles tendues entre l'archidruide Staghelm et le gardien Remulos – le gardien de Reflet-de-Lune. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.\n\nPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Starblaze, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.", progress = nil, completion = "C'est ainsi que cela commence, Père Cénarius.\"\n\nDendrite fait un rapide petit geste invisible au-dessus de lui. Une légère aura de pouvoir se déverse sur lui.\n\n\"La première façon de voir la nature à laquelle vous devez vous habituer est celle de l'ours. Je vais vous placer sur la voie afin que vous compreniez cet aspect de la vie d'un &lt;classe&gt;, mais c'est vous qui devez l'embrasser et la propager, aujourd'hui et à jamais !", rewards = "Vous recevrez :\n\n"},
[5922] = {title = "Reflet-de-Lune", objective = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", description = "Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, taurens ou elfes de la nuit. Le gardien Remulos – le gardien de Reflet-de-Lune – surveille de près tous les druides qui hivernent ici. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.\n\nPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Starblaze, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.", progress = nil, completion = "C'est ainsi que cela commence, Père Cénarius.\"\n\nDendrite fait un rapide petit geste invisible au-dessus de lui. Une légère aura de pouvoir se déverse sur lui.\n\n\"La première façon de voir la nature à laquelle vous devez vous habituer est celle de l'ours. Je vais vous placer sur la voie afin que vous compreniez cet aspect de la vie d'un &lt;classe&gt;, mais c'est vous qui devez l'embrasser et la propager, aujourd'hui et à jamais !", rewards = "Vous recevrez :\n\n"},
[5923] = {title = "Écouter l'appel", objective = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", description = "Excusez-moi, vous...\n\nJ'ai cru comprendre que Mathrengyl Bearwalker souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu'il veuille vous former personnellement. Mathrengyl est l'assistant direct de l'archidruide lui-même et l'un des druides les plus sages et les plus reconnus de Teldrassil.\n\nIl se trouve dans l'Enclave cénarienne à Darnassus, au deuxième étage de l'arbre de Fandral Staghelm.", progress = nil, completion = "Je suis heureux que vous ayez trouvé votre chemin aujourd'hui, jeune &lt;classe&gt;. Le temps est venu pour vous de passer à des choses plus sérieuses.\n\nL'appel pour servir la nature est en chacun des enfants de Cénarius. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l'équilibre par égard pour eux autant que pour nous. La première chose que vous devez faire dans ce monde est d'apprendre les voies de l'ours, et d'acquérir la force du corps et du cœur.\n\nPréparez vous !", rewards = "Vous recevrez :\n\n"},
[5924] = {title = "Écouter l'appel", objective = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", description = "Excusez-moi, vous...\n\nJ'ai cru comprendre que Mathrengyl Bearwalker souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu'il veuille vous former personnellement. Mathrengyl est l'assistant direct de l'archidruide lui-même et l'un des druides les plus sages et les plus reconnus de Teldrassil.\n\nIl se trouve dans l'Enclave cénarienne à Darnassus, au deuxième étage de l'arbre de Fandral Staghelm.", progress = nil, completion = "Je suis heureux que vous ayez trouvé votre chemin aujourd'hui, jeune &lt;classe&gt;. Le temps est venu pour vous de passer à des choses plus sérieuses.\n\nL'appel pour servir la nature est en chacun des enfants de Cénarius. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l'équilibre par égard pour eux autant que pour nous. La première chose que vous devez faire dans ce monde est d'apprendre les voies de l'ours, et d'acquérir la force du corps et du cœur.\n\nPréparez vous !", rewards = "Vous recevrez :\n\n"},
[5925] = {title = "Écouter l'appel", objective = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", description = "Excusez-moi, mon <ami/amie>...\n\nJ'ai cru comprendre que Mathrengyl Bearwalker souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu'il veuille vous former personnellement. Mathrengyl est l'assistant direct de l'archidruide lui-même et l'un des druides les plus sages et les plus reconnus de Teldrassil.\n\nIl se trouve dans l'Enclave cénarienne à Darnassus, au deuxième étage de l'arbre de Fandral Staghelm.", progress = nil, completion = "Je suis heureux que vous ayez trouvé votre chemin aujourd'hui, jeune &lt;classe&gt;. Le temps est venu pour vous de passer à des choses plus sérieuses.\n\nL'appel pour servir la nature est en chacun des enfants de Cénarius. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l'équilibre par égard pour eux autant que pour nous. La première chose que vous devez faire dans ce monde est d'apprendre les voies de l'ours, et d'acquérir la force du corps et du cœur.\n\nPréparez vous !", rewards = "Vous recevrez :\n\n"},
[5926] = {title = "Écouter l'appel", objective = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", description = "Excusez-moi...\n\nJ'ai entendu dire que Turak Runetotem voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu'il veuille vous former personnellement. Turak est l'un des assistants des archidruides ; il a la réputation d’être sage et patient et il devrait bien vous former.\n\nIl est à Thunder Bluff, dans la tente principale du Cercle cénarien sur la Cime des Anciens.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5927] = {title = "Écouter l'appel", objective = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", description = "Excusez-moi...\n\nJ'ai entendu dire que Turak Runetotem voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu'il veuille vous former personnellement. Turak est l'un des assistants des archidruides ; il a la réputation d’être sage et patient et il devrait bien vous former.\n\nIl est à Thunder Bluff, dans la tente principale du Cercle cénarien sur la Cime des Anciens.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[5928] = {title = "Écouter l'appel", objective = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", description = "Excusez-moi...\n\nJ'ai entendu dire que Turak Runetotem voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu'il veuille vous former personnellement. Turak est l'un des assistants des archidruides ; il a la réputation d’être sage et patient et il devrait bien vous former.\n\nIl est à Thunder Bluff, dans la tente principale du Cercle cénarien sur la Cime des Anciens.", progress = nil, completion = "Je suis heureux que vous ayez trouvé votre voie aujourd'hui, jeune &lt;classe&gt;. Le temps est venu pour vous de passer à des choses plus sérieuses.\n\nChacun des enfants de Cénarius se sent appelé à servir la nature. Les animaux et les plantes sont nos amis et nous devons nous en occuper. Nous avons choisi de consacrer notre vie à préserver l'équilibre autant par égard pour eux que pour nous. La première chose à faire dans ce monde est d'apprendre les voies de l'ours, et d'acquérir la force du corps et du cœur.\n\nPréparez-vous !", rewards = "Vous recevrez :\n\n"},
[5929] = {title = "L'esprit du Grand ours", objective = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", description = "Au nord-ouest de Reflet-de-Lune se trouve la demeure d'un être sage et noble que nous appelons l'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l'ours. A un moment, tous les druides cherchent la sagesse de l'esprit et vous ne ferez pas exception.\n\nAllez voir l'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.", progress = nil, completion = "Dendrite fait un autre petit geste rapide et invisible au-dessus de lui lorsque vous vous approchez. Une autre aura de pouvoir se déverse sur lui, et il sourit presque imperceptiblement.\n\n\"Je sens de la sagesse en vous, elle n'était pas présente lors de notre première rencontre. Vous me regardez avec force et détermination, mais cette détermination n'est pas encore complètement maîtrisée. Vous allez maintenant apprendre comment concentrer votre force et utiliser la nature de l'ours dans vos actions.\"", rewards = "Vous recevrez :\n\n"},
[5930] = {title = "Esprit du Grand ours", objective = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", description = "Au nord-ouest de Reflet-de-Lune se trouve la maison d'un être sage et noble que nous appelons l'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l'ours. A un moment, tous les druides cherchent la sagesse de l'esprit et vous ne ferez pas exception.\n\nAllez voir l'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.", progress = nil, completion = "Dendrite fait un autre petit geste rapide et invisible au-dessus de lui lorsque vous vous approchez. Une autre aura de pouvoir se déverse sur lui, et il sourit presque imperceptiblement.\n\n\"Je sens de la sagesse en vous, elle n'était pas présente lors de notre première rencontre. Vous me regardez avec force et détermination, mais cette détermination n'est pas encore complètement maîtrisée. Vous allez maintenant apprendre comment concentrer votre force et utiliser la nature de l'ours dans vos actions.\"", rewards = "Vous recevrez :\n\n"},
[5931] = {title = "Retour à Darnassus", objective = "Retourner à Darnassus et parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne.", description = "Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Mathrengyl Bearwalker vit en complète harmonie avec l’équilibre naturel, bien que résidant à proximité de l’endroit où cet équilibre a vacillé. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l’équilibre naturel.\n\nPartez maintenant. Nous nous reverrons bientôt.", progress = nil, completion = "Soyez à nouveau le bienvenu, &lt;nom&gt;. J'ai le sentiment que votre première rencontre avec l'esprit du Grand ours a été semblable à celle de tous les druides débutant sur la voie de la Griffe... C'est un peu déroutant, mais très intense. Cela a été le cas pour moi.\n\nL'esprit du Grand ours a été une partie d'Azeroth quand Azeroth existait dans les cieux. Nous sommes ici pour transmettre sa sagesse et son pouvoir. Le temps de la première épreuve pour atteindre votre but est à présent venu. Écoutez-moi attentivement...", rewards = "Vous recevrez :\n\n"},
[5932] = {title = "Retour vers Thunder Bluff", objective = "Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens.", description = "Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Bien que les taurens passent pour novices dans les voies de Cénarius, Turak Runetotem est en totale harmonie avec la nature. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l’équilibre naturel.\n\nPartez maintenant. Nous nous reverrons bientôt.", progress = nil, completion = "Soyez à nouveau le bienvenu, &lt;nom&gt;. J'ai le sentiment que votre première rencontre avec l'esprit du Grand ours a été semblable à celle de tous les druides débutant sur la voie de la Griffe... C'est un peu déroutant, mais très intense. Cela a été le cas pour moi.\n\nL'esprit du Grand ours a été une partie d'Azeroth quand Azeroth existait dans les cieux. Nous les taurens écoutons attentivement ce genre d'esprit et nous prospérons grâce à cela. Maintenant, le temps de la première épreuve pour atteindre votre but est venu. Écoutez-moi attentivement...", rewards = "Vous recevrez :\n\n"},
[5941] = {title = "Retourner voir Chromie", objective = "Apporter la Liasse de reliques à Chromie, à Andorhal.", description = "Vous avez collecté maintes reliques de la bataille de Darrowshire. À chaque fois que vous en avez rapporté davantage, mon coeur se languissait un peu plus de mon village, et je brûlais de le protéger de son destin.\n\nJe sais que cela ne se peut, mais Chromie, cette étrange gnome à Andorhal, m’a dit que c'était possible. Elle dit que vous avez le pouvoir de sauver le Darrowshire !\n\nElle m’a demandé de rassembler les reliques et de vous les donner pour que vous les lui apportiez. Elle a dit qu’elle vous attendait dans l’auberge en ruines d’Andorhal.", progress = "J'ai été en contact avec votre ami Carlin. Il est très attristé par la malédiction qui s'est abattu sur son village, mais il m'a parlé de vous en bien et il sait que vous pouvez arranger cela.\n\nHo, mais je m'éloigne du sujet... <nom>, avez-vous les reliques que je vous ai demandées ?", completion = "Ah oui, les voilà ! Ensemble ils forment un sort puissant, un sort qui permet d'appeler les esprits du Darrowshire.\n\nAvec ce sort, il y a une petite chance que nous sauvions Joseph Redpath !", rewards = "Vous recevrez :\n\n"},
[5942] = {title = "Trésors cachés", objective = "Utiliser la Clé de Joseph sur le Coffre de Joseph.", description = "Papa m’a dit de vous donner cette clé. Il prétend qu’elle ouvre un coffre, derrière la maison.\n\nIl voulait aussi que je vous remercie. Vous l'avez aidé ? Vous lui avez dit que vous aviez retrouvé ma poupée ?\n\nEnfin, voici la clé. Et merci, <nom>. Merci ! Vous êtes <un très gentil monsieur/une très gentille dame> !", progress = "Ce coffre est vieux et couvert de saletés.", completion = "La clé correspond à la serrure, et le coffre s'ouvre...", rewards = "Vous recevrez :\n\nAnneau de protectionTalisman de grande lumièreBaguette de résistance magique"},
[5943] = {title = "La caravane de Gizelton", objective = "Escorter la caravane de Gizelton à travers le convent de Mannoroc. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense.", description = "Vous semblez compétent, <race>. Peut-être voudriez-vous gagner un peu d’argent ? Cork et moi avons monté cette caravane pour faire fortune, mais nous ignorions les dangers que recélait cette entreprise !\n\nDevant nous se trouve le convent de Mannoroc… En temps normal, les démons nous ignorent mais quelque chose a effrayé les kodos, ce coup-ci. Je vous paierai pour protéger la caravane lorsque nous passons près du convent de Mannoroc. Quand nous aurons traversé ce coin, vous pourrez aller chercher votre récompense auprès de notre associé, Smeed, au camp de Scrabblescrew.", progress = nil, completion = "Il n'est pas certain que cela soit une bonne proposition d'être payé autant pour protéger la caravane de Gizelton. Cork et Rigger ne gagnent qu'une pièce d'or par semaine, mais du moment qu'ils payent pour mes kodos je ne m'occupe pas de la façon dont ils gèrent leurs affaires.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPétoire de flanqueurMarqueur de kodoBouclier riveté\n\nVous recevrez également :\n\n"},
[5944] = {title = "En rêves", objective = "Escortez Taelan Fordring jusqu'à la sortie des Hearthglen.", description = "Depuis longtemps, je ne suis qu’une marionnette du Grand croisé. Quelle raison y avait-il de lutter contre ce que la Croisade écarlate était devenue ? Après toutes ces années, c’est seulement grâce à la mémoire de mon père que je dois d’être encore en vie, aujourd’hui.\n\nJe fais des rêves, et mon père y est à mes côtés. Il se tient fièrement à ma droite, tandis que l'on m'intronise dans l’Ordre. Ensemble, nous abattons des légions entières de soldats du Fléau, et faisons étinceler l’honneur de l’Alliance et de Lordaeron.\n\nJ’en ai assez de ces rêves.\n\nAmenez-moi auprès de lui.", progress = "<Tirion reprend son calme.>", completion = "Le meurtre de mon fils par ces monstres ne restera pas sans conséquences. Que cette nouvelle vous apporte quelque consolation : l'Ordre renaît.\n\nJe prends aujourd’hui ma place de généralissime du nouvel Ordre de la Main d'argent.\n\nEn guise de remerciement, prenez mes anciennes possessions. Elles m'ont été très utiles pendant des années.\n\nNous nous rencontrerons peut-être encore, en des circonstances plus agréables j’espère, et nous nous souviendrons des jours passés... des batailles... des rêves que nous avions.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMarque de FordringCuirasse ornée en adamantiumMarteau en platine chatoyantVoile de l'exilSceau de Fordring\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[5961] = {title = "Le champion de la reine banshee", objective = "Parler à Nathanos le Flétrisseur, dans les Maleterres de l’est. Il se trouve actuellement à la ferme des Marris.", description = "Ça me fait plaisir de voir les plus valeureux se joindre à nous. Nos effectifs enflent et se renforcent de jour en jour. Peut-être êtes-vous en mesure de tester votre courage et votre force, <classe> ?\n\nNathanos figurait parmi les premiers de mes champions ; il est connu maintenant sous le nom de Flétrisseur. Très peu ont autant d'engagement et de vigueur que lui, dans nos rangs.\n\nAllez à sa rencontre, dans les Maleterres de l'est. Il vit dans la ferme des Marris. De temps en temps, il parcourt les terres et massacre tous les membres du Fléau et de l'Alliance qu'il croise sur sa route.", progress = nil, completion = "La Dame noire doit certainement penser que vous n'êtes pas digne d'affronter son champion. Vous êtes là pour nourrir mes chiens, non ? Il ne saurait y avoir d'autre raison à cette interruption.", rewards = "Vous recevrez :\n\n"},
[5981] = {title = "Géants déchaînés", objective = "Rivern Frostwind voudrait que vous tuiez 4 Géants Cognegivre et 4 Protecteurs Cognegivre.", description = "Il y a environ quatre mille ans, Tyrande Whisperwind a sauvé la reine des sabres-de-givre, aux prises avec des géants déchaînés. Depuis, les sabres-de-givre sont les alliés des elfes de la nuit.\n\nCes géants, qui étaient autrefois un danger pour les sabres-de-givre, existent toujours. Ce sont les géants Cognegivre et ils sont installés dans la grande vallée au sud, pas très loin d'ici.\n\nProuvez votre fidélité aux sabres-de-givre : tuez-en au nom de leur reine, Shy-Rotam !", progress = nil, completion = "Excellent, &lt;nom&gt;. Votre détermination a été dûment prise en compte.", rewards = nil},
[6001] = {title = "Corps et cœur", objective = "Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.\n\nQuand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.", description = "A l’est d’Auberdine se trouvent plusieurs grottes de séléniens. Celle qui est la plus proche d’Auberdine contient une pierre des séléniens. Lunegriffe, le défenseur de la pierre, ne vous affrontera que si la poussière de lune cénarienne est appliquée sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme doivent le faire tous les druides de la Griffe.\n\nVous avez gagné le droit d’utiliser cette poussière de lune cénarienne, <nom>... Maintenant, montrez-moi que vous avez aussi gagné celui d'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !", progress = nil, completion = "Le temps est venu pour vous de passer à des choses plus sérieuses, &lt;nom&gt;. Je sens l'enseignement du Grand ours en vous et je sens aussi que vous avez reçu la force de Lunegriffe.\n\nIl n'y a plus d'obstacle sur votre voie... Laissez-moi vous enseigner à être un &lt;classe&gt; de la Griffe !", rewards = "Vous allez être la cible du sort suivant :\n\nForme d’ours\n\nVous recevrez :\n\n"},
[6002] = {title = "Corps et cœur", objective = "Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.\n\nQuand cela est fait, parler à Turak Runetotem, à Thunder Bluff.", description = "À l’ouest de Taurajo, dans les Tarides, juste avant Mulgore, se trouve une pierre des séléniens. Les séléniens sont des créatures spéciales qui ne sont pas originaires de ce pays. Lunegriffe, le défenseur de la pierre, vous affrontera lorsque vous appliquerez la poussière lunaire cénarienne sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme tous les druides de la Griffe.\n\nVous avez gagné le droit d’utiliser cette poussière lunaire cénarienne, <nom>... Maintenant montrez-moi que vous avez aussi gagné celui d'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !", progress = nil, completion = "Le temps est venu pour vous de passer à des choses plus sérieuses, &lt;nom&gt;. Je sens l'enseignement du Grand ours en vous et je sens aussi que vous avez reçu la force de Lunegriffe.\n\nIl n'y a plus d'obstacle sur votre voie... Laissez-moi vous enseigner à être un &lt;classe&gt; de la Griffe !", rewards = "Vous allez être la cible du sort suivant :\n\nForme d’ours\n\nVous recevrez :\n\n"},
[6004] = {title = "Un travail inachevé", objective = "Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Deepshadow dans les Maleterres de l'ouest.", description = "On m’a envoyée en reconnaissance, pour affaiblir et juger les défenses de Hearthglen. Certaines personnes, dans l’Alliance, pensent que l’importance de la petite ville n’est pas seulement d’ordre historique. Je ne suis pas là pour poser des questions quant à ce qui fait l’importance de cette ville ; je suis de toute façon bien trop épuisée pour l’instant pour pouvoir continuer. Je dois me reposer.\n\nSi vous le voulez, je vous paierai largement en échange de votre aide. Commencez au sud, par l’un de leurs camps, près de petit rempart qu’ils ont érigé. Si vous faites vos preuves, je vous emploierai pour m’aider dans ma mission principale.", progress = nil, completion = "Bien joué, &lt;nom&gt;. Je suis impressionnée que vous ayez pu faire affaire avec eux si rapidement. Merci.\n\nJe dois rencontrer tous ceux qui approuvent les méthodes de la Croisade écarlate. Je crois en la Lumière, autant que les gens de Stormwind, mais ils ont montré qu'ils tuaient tous ceux qui ne suivaient pas leur mouvement... même les innocents.", rewards = "Vous recevrez :\n\n"},
[6021] = {title = "Zaeldarr le Banni", objective = "Apporter la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l'Espoir de Lumière.", description = "Pouvez-vous croire qu'après tous les ennuis que nous avons dans les Maleterres, il faille maintenant se préoccuper également des voleurs ? Et pas des voleurs normaux, des voleurs trolls.\n\nEt pas seulement des voleurs trolls normaux, des voleurs trolls morts-vivants !\n\nIls sont dirigés par un troll mort-vivant qui répond au nom de Zaeldarr le Banni, et ils viennent ici la nuit pour voler des corps dans la fosse, plus bas, puis ils les ramènent dans leur cache de trolls morts-vivants : le caveau de Zaeldarr, à l'ouest.\n\nAllez là-bas et tuez Zaeldarr, <nom>. Je ne peux plus supporter sa méchanceté !", progress = "Avez-vous trouvé la cache, <nom> ? Avez-vous résolu le problème Zaeldarr ?", completion = "Formidable, vous l'avez eu ! Et j'espère que vous avez donné une bonne leçon à son gang par la même occasion !", rewards = "Vous recevrez :\n\n"},
[6022] = {title = "Tuer utile", objective = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée.", description = "Tant que vous travaillerez pour moi, vous tuerez sur commande.\n\nVotre première tâche consiste à nourrir mes chiens.\n\nPrenez ce mortier et ce pilon, et allez à la Croisée de Corin. Une fois sur place, vous trouverez une belle brochette de membres du Fléau à tuer. Sur leurs carcasses encore tièdes, collectez de la Pourriture vivante ; vous la pulvériserez ensuite dans le mortier, puis laisserez le tout coaguler. Rapportez-moi la Pourriture coagulée.\n\nEt puis, imbécile, rappelez-vous que la Pourriture vivante, prélevée sur des morts-vivants, ne reste pas vivante bien longtemps ; aussi, faites vite !", progress = "Vous pleurez ? Si c'est trop 'fastidieux' pour vous, 'héros,' je vous conseille de retourner voir la Dame noire et de lui dire de quel horrible traitement vous faites l'objet à ma ferme.\n\nMaintenant hors de ma vue !", completion = "Décevant. J'espérais que vous seriez le repas de mes chiens.\n\n&lt;Nathanos soupire.&gt;\n\nBah, ils auront quand même quelque chose à manger.", rewards = "Vous recevrez :\n\n"},
[6023] = {title = "Un travail inachevé", objective = "Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.", description = "Ma véritable mission était d'affaiblir les forces extérieures de la Croisade écarlate, puis d'infiltrer Hearthglen pour faire une estimation de leur nombre. Je ne suis toujours pas en mesure de le faire moi-même, aussi pourriez-vous peut-être m'aider, une fois encore, <nom> ? D'après les informations que j'ai collectées avant d'être découverte, la Croisade comprend deux membres, lesquels constituent l'épine dorsale de leurs forces à l'extérieur de la ville : le veneur Radley et le cavalier Durgen. Les tuer représentera déjà un progrès. Ils devraient se trouver le long de la Passe de Hearthglen, à l'extérieur de la ville.", progress = nil, completion = "Merci, &lt;nom&gt;. Vous nous avez apporté plus d'aide que je n'aurais jamais pu en espérer. L'atmosphère ici a l'air de pomper littéralement ma volonté. Je me sens fatiguée, et plus je reste, moins ça s'arrange.\n\nJe ne sais pas encore vraiment comment je vais infiltrer Hearthglen et faire mon rapport sur l'activité de la Croisade écarlate.\n\nMais c'est un autre problème. Avant que vous ne partiez, prenez ceci... comme récompense pour votre aide. Merci encore.", rewards = "Vous recevrez :\n\n"},
[6024] = {title = "L'appel d'Hameya", objective = "Tuer l’Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr.", description = "Tuez-moi. Avant qu'il ne soit trop tard.\n\nJe suis Hameya. Tandis que je voyageais vers Zul'Mashar, mes frères et moi avons mangé de la viande corrompue... et nous avons changé. Nous sommes infectés.\n\nJ'entends les mots de la liche, maintenant, qui me pressent de me rendre à Zul'Mashar pour y infecter encore plus de monde. Je ne peux y résister ; ainsi, j'ai écrit ce parchemin, avant que toutes mes forces et ma volonté ne me quittent définitivement.\n\nJ'ai enterré un coffre dans la terre, à proximité d'un chariot, derrière cette crypte. Seule ma clé pourra l'ouvrir, et cette clé est en ma possession. Si vous voulez mon trésor, vous devrez me trouver.\n\nTuez-moi, avant qu'il ne soit trop tard.", progress = "Les coffres enterrés ici sont solidement verrouillés.", completion = "Le coffre d'Hameya est ouvert !", rewards = "Vous recevrez :\n\nPourfendeuse d'HameyaCape d'Hameya"},
[6025] = {title = "Un travail inachevé", objective = "Aller dans Hearthglen, et trouver un poste d’observation élevé d’où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.", description = "Quoi ? Vraiment ? Vous voulez en savoir plus ? Mais vous avez déjà fait tant pour moi, <nom>. Je ne peux quand même pas vous demander d'entrer dans Hearthglen pour me défendre.\n\nC'est sûr, <nom> ? Hearthglen est beaucoup plus dangereux que le Passage, et je ne peux vous fournir ni protection ni même d'informations sur les risques que vous prenez.\n\nEh bien ! Si vous désirez vraiment m'aider, pénétrez dans la ville et cherchez un endroit en hauteur, pour dominer toute la ville. De là vous pourrez voir combien ils sont et revenir me l'annoncer. Mais faites preuve de prudence...", progress = nil, completion = "Vous l'avez fait, &lt;nom&gt; ! Merci !\n\nJe vais retourner voir Elling… je veux dire aller à Stormwind, aussitôt que je le pourrai. Tenez, prenez cette pièce, c'est le moins que je puisse faire pour vous. Vous faites l'honneur de votre peuple, &lt;nom&gt;. Merci et bonne chance.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6026] = {title = "Cela demande beaucoup", objective = "Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables.\n\nVous devrez trouver un forgeron et un ingénieur pour obtenir ces objets.", description = "Ces agents de l’Aube d'argent ont chargé le vieux Smokey de réaliser un petit travail de démolition. La maman du vieux Smokey n’a pas élevé un simplet : dès que des écus tintent, Smokey est disponible et prêt à rendre service. C’est mon mot d’ordre !\n\nJe serais maintenant disposé à partager la commission avec vous, si vous êtiez d’accord pour exécuter un petit travail sur le terrain. Voici l’idée : je vais me diriger vers Pestebois et marquer tous les bâtiments qui sont destinés à être détruits. Pendant ce temps, vous collecterez les composants qui sont nécessaires à la confection des bombes. Qu’en dites-vous ?", progress = "Croyez-en le vieux Smokey, <nom>. La récompense en vaudra la peine. Ces gens de l'Aube d'argent ne lambinent pas quand c'est le moment de payer.", completion = "Je peux vous payer la moitié tout de suite et l'autre moitié quand le travail sera fait.", rewards = "Vous recevrez :\n\n"},
[6027] = {title = "Le Livre des Anciens", objective = "Obtenir le Livre des Anciens, puis le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor.", description = "<nom>, je vous confie la Gemme du serpent. Placez cette gemme dans la main de la Statue du serpent qui se trouve sur l'île de Ranazjar, une petite île au nord-ouest d'ici. En même temps, vous appellerez celui qui protège le Livre des Anciens. Ce livre contient les secrets des nagas, des secrets qui ont été gardés pendant des siècles. Apportez-moi ce livre et nous en apprendrons beaucoup sur nos adversaires !", progress = "Ha, <nom> ! C'est bon de vous revoir. Avez-vous le Livre des Anciens ?", completion = "Le Livre des anciens, perdu depuis si longtemps ! Je vais faire en sorte que ce livre soit apporté au haut conseil. Vous avez fait du bon travail aujourd'hui, et pour cela je vous remercie... comme tous les héros devraient être remerciés !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCrispins flot-de-soieEpaulières d'Arcmetal\n\nVous recevrez également :\n\n"},
[6028] = {title = "Le rapport de Long-guet", objective = "Apportez le Rapport de Long-guet à l'officier de l'Aube d'argent Pureheart au Camp du Noroît, dans les Maleterres de l'ouest.", description = "Je suis à la recherche d’une personne sérieuse qui voudrait m’aider pour une petite affaire qui n’est pas sans importance. Je suis ici en tant que représentant de l’Aube d'argent, auprès des dirigeants de Long-guet. J’ai besoin d’obtenir un rapport et de le transmettre à l’officier de l'Aube d'argent, Pureheart, au camp du Noroît. L’endroit se trouve le long de la lisière sud des Maleterres de l’ouest.\n\nL’occasion serait trop belle de vous présenter à ma supérieure, et peut-être d’en obtenir du travail !", progress = "Salutations, <classe>. Au nom de l'Aube d'argent, je vous offre la protection et un abri tant que vous serez au Camp du Noroît. J'aurai peut-être du travail pour vous...", completion = "Gregor est plein de ressources pour un humain. Il traite avec le Cartel Gentepression depuis quelque temps maintenant et est devenu une sorte d'expert dans l'\"art\" de la négociation gobeline. On sait que la loyauté des gobelins va à la plus grosse bourse, mais qu’ils connaissent et respectent aussi la vertu de la diplomatie. Au pire, ça leur attire des clients...\n\nL'Aube d'argent vous est très reconnaissante pour vos efforts. S'il vous plaît, prenez ceci et acceptez mes remerciements.", rewards = "Vous recevrez :\n\n"},
[6029] = {title = "Le rapport de Long-guet", objective = "Livrer le Rapport de Long-guet à l’officier Garush de l'Aube d'argent, à la Barricade, dans les Maleterres de l’ouest.", description = "Je cherche une personne sérieuse pour m’aider dans une petite affaire, qui n’en est pas moins importante. Je représente les intérêts de l’Aube d'argent devant l’autorité locale de Long-guet. J’ai besoin de fournir un rapport à l’officier de l'Aube d'argent, Garush, à la Barricade ; cela se trouve à quelque distance d’ici, le long de la lisière ouest des Maleterres de l'ouest, à l’est des Clairières de Tirisfal.\n\nCela serait l’occasion de vous présenter à mon supérieur, et peut-être d’obtenir du travail, sous son commandement !", progress = "Salutations, <classe>. Au nom de l'Aube d'argent, je vous offre la protection et un abri tant que vous serez à la Barricade. Je vous donnerai peut-être une chance de combattre pour une noble cause !", completion = "Gregor est plein de ressources pour un humain. Il traite avec le Cartel Gentepression depuis quelque temps maintenant et est devenu une sorte d'expert dans l'\"art\" de la négociation gobeline. On sait que la loyauté des gobelins va à la plus grosse bourse, mais qu’ils connaissent et respectent aussi la vertu de la diplomatie. Au pire, ça leur attire des clients...\n\nL'Aube d'argent vous est très reconnaissante pour vos efforts. S'il vous plaît, prenez ceci et acceptez mes remerciements.", rewards = "Vous recevrez :\n\n"},
[6030] = {title = "Le duc Nicholas Zverenhoff", objective = "Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est.", description = "Umbranse, une médium qui vit en recluse dans la région, a offert à l’Aube d'argent un chef-d’œuvre de littérature... un de ceux qui comprennent une quantité indécente de blabla en prose.\n\nL'un des chefs les plus respectés de l'Aube, le duc Nicholas Zverenhoff, est aussi un brillant linguiste. Pourriez-vous lui apporter cela de ma part, contre une récompense ? La chapelle de l'Espoir de Lumière, c’est là qu’il réside en ce moment. L’endroit se trouve loin à l’est, à l'intérieur des Maleterres de l’est.", progress = "Que la Lumière vous guide en ces temps troublés, <classe>. Qu'est-ce qui vous amène dans ce lieu d'espoir au beau milieu des ténèbres et du désespoir ?", completion = "Ceci... ce que vous m'avez apporté est un livre très spécial. Je précise que \"spécial\" dans ce cas signifie \"unique et instructif\", enfin cela reste à vérifier.\n\n\"Ooooooo?\" Qui de normalement constitué pourrait avoir ce genre d'idée ?\n\nBon, maintenant j'ai entendu parler de cette Umbranse que Gregor avait mentionnée, ce n'est donc pas sans mérite. Je ferai de mon mieux pour le déchiffrer. Et pour vous... acceptez ceci en récompense. Pendant que vous êtes là, vous pourriez peut-être nous aider…", rewards = "Vous recevrez :\n\n"},
[6031] = {title = "L'étoffe runique", objective = "Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules.", description = "À Grumegueules, nous sommes satisfaits d'être entre nous. Nous n’aimons pas les étrangers, ce qui n’arrange malheureusement pas le commerce.\n\nIl n’y a pas longtemps, une de nos rares amis elfe de la nuit est arrivée à Grumegueules, portant une cape en étoffe runique. L’étoffe runique est un textile que l’on ne voit pas souvent par ici, et mes frères ont été séduits par sa perfection. Ils désirent que je leur procure des vêtements taillés dans cette étoffe.\n\nVoudriez-vous m’apporter de l’étoffe runique ? Si vous m’en apportez suffisamment, je vous donnerai quelque chose en échange.", progress = "Avez-vous mon étoffe runique ? Mon peuple est impatient d'avoir des objets façonnés dans cette matière !", completion = "Ah, vous avez apporté les étoffes. Quelle belle finition !\n\nMerci, &lt;nom&gt;. Vous êtes vraiment un ami. Acceptez ceci en échange, s'il vous plaît.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSpallières en peau d'ombreGantelets brique-d'acier\n\nVous recevrez également :\n\n"},
[6032] = {title = "Le vêtement sacré", objective = "Apporter 2 pièces d’Etoffe lunaire à Meilosh, au Repaire des Grumegueules.", description = "Bien que le peuple des Grumegueules sache enchanter les étoffes runiques, elles ne sont pas sacrées pour nous. Mais l'étoffe lunaire, elle, est sacrée.\n\nApportez-m'en un petit morceau et je vous apprendrai un secret de fabrication.", progress = "Avez-vous apporté l'étoffe lunaire, <nom> ?", completion = "Ah, très bien ! Cette étoffe lunaire servira à confectionner les vêtements sacrés de notre peuple. Merci, &lt;nom&gt;. Maintenant je vais vous entraîner.", rewards = "Vous apprendrez :\n\nBottes en étoffe lunaire\n\nVous allez être la cible du sort suivant :\n\nBottes en étoffe lunaire\n\nVous recevrez également :\n\n"},
[6041] = {title = "Quand Smokey chante, je deviens violent", objective = "Aller à Pestebois, au nord-ouest de la chapelle de l'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.\n\nUne fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.\n\nGarder en tête que le Mélange spécial de Smokey est très... instable.", description = "Pendant que vous collectiez les provisions, quelques-uns de mes agents ont pu marquer les bâtiments du Fléau que nous devons démolir.\n\nVoici le plan : je m'en vais vous donner dix bâtons de mon mélange spécial. Vous les porterez à Pestebois et les placerez dans les bâtiments du Fléau qui ont été marqués et sont destinés à sauter.\n\n<Smokey claque des doigts.>\n\nBing ! C'est pas plus compliqué que ça.", progress = nil, completion = "Vous êtes beaucoup plus sombre que ce dont je me souvenais. Et vous avez ce regard qui vous trahit ; ce regard qui dit 'je me suis fait carboniser par une bombe.'\n\n&lt;Rires fumeux.&gt;\n\nQuoi qu'il en soit, voilà votre part du butin. J'ai rajouté un petit extra pour adoucir les brûlures.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLanceur explosif de SmokeyTire-flammes de Smokey\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nChiffon à poussièreDrapé de Smokey"},
[6042] = {title = "Les petits soucis de la non-vie", objective = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait.", description = "On ne peut pas faire deux pas hors de cette ferme sans se heurter à une de ces chauves-souris si désagréables. Je veux pouvoir poursuivre ces canailles et combattre le Fléau sans me faire agresser sans arrêt par ces damnées chauves-souris. Mais bon, j'ai mieux à faire que de passer mon temps à tuer stupidement des chauves-souris, jour après jour. Par contre, vous non !\n\nQuoi ? Votre formation ? Mais la voilà, votre formation ! Maintenant sortez de ma vue et ne revenez pas avant d'avoir tué un nombre respectable de ces démons ailés. Ne me décevez pas.", progress = "Cela aurait pu être pire. J'aurais pu vous envoyer ramasser du guano de chauve-souris.\n\n<Nathanos vous fixe.>\n\nHem... Hé ! Attendez une minute. Où allez-vous ?", completion = "C'est incroyable ce que l'on peut accomplir sous le coup de la rage et de la colère.", rewards = "Vous recevrez :\n\n"},
[6061] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof.", description = "En tant que taurens, il est important que nous suivions les traditions de nos ancêtres en affrontant des créatures puissantes. En battant ces créatures, nous pouvons nous nourrir de leur esprit, ce qui nous rapproche de mère Nature.\n\nDe même, apprivoiser une bête pour qu'elle combatte à nos côtés nous aide à ne faire qu'un avec la nature qui nous entoure. Vous finirez par apprendre à apprivoiser une bête. Mais tout art demande de la pratique et vous avez beaucoup à apprendre. Commencez en prenant ce Bâtonnet de domptage et allez apprivoiser un trotteur des plaines adulte.", progress = "Exercez vos compétences, <nom>. Domptez un trotteur des plaines adulte.", completion = "La Terre-mère m’a envoyé les signes. Bravo !", rewards = "Vous recevrez :\n\n"},
[6062] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.", description = "C'est une excellente compétence que de savoir commander à la nature. En tant que chasseur, vous devez vous efforcer d'utiliser la force et le pouvoir de n'importe quelle créature.\n\nPrendre le contrôle d'un animal n'est pas facile, c'est une tâche que vous devez entreprendre avec beaucoup de détermination.\n\nPour commencer, prenez ce Bâtonnet de domptage et utilisez-le pour apprivoiser un sanglier tacheté redoutable. Vous en trouverez près de Tranchecolline. Entraînez-vous à combattre avec le sanglier à vos côtés, puis revenez me voir.", progress = "Bonne chance, jeune <classe>.", completion = "Bravo &lt;nom&gt; ! Vous pouvez passer à la tâche suivante.", rewards = "Vous recevrez :\n\n"},
[6063] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", description = "En tant que chasseur, vous devez prendre conscience de vos responsabilités. On ne peut pas plier la nature à ses désirs, elle doit être respectée et reconnue comme bien plus forte que votre propre existence.\n\n<nom>, vous devez prouver que vous avez compris cela avant de gagner la capacité d'apprivoiser un animal pour en faire votre compagnon.\n\nLa première chose à faire est de prendre ce Bâtonnet de domptage. Il vous permettra d'apprivoiser une rôdeuse Tissebois. Apprivoisez-la et entraînez-vous à chasser ensemble.", progress = "Vous apprendrez, <nom>, et deviendrez un jour un grand <classe>.", completion = "Excellent &lt;nom&gt; ! Vous apprenez vite.", rewards = "Vous recevrez :\n\n"},
[6064] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos.", description = "Hé là ! Vous voulez savoir comment obtenir un animal de compagnie ?\n\nEh bien commençons ! Il n'y a rien de plus important qu'un bon équipement pour aller à la chasse, mais nous discuterons de mon nouveau crache-mitraille une autre fois. Pour le moment, concentrons-nous sur quelque chose qui vous intéresse, j'en suis sûr : un animal de compagnie !\n\nLa meilleure façon d'apprendre est d'essayer avec plusieurs créatures différentes pour voir ce que ça donne. Commencez par trouver un grand sanglier des rochers, utilisez ensuite le bâtonnet de domptage pour l'apprivoiser.", progress = "Ne vous inquiétez pas, jeune homme ! Vous devez en essayer quelques-uns avant d'arrêter votre choix sur l'un d'eux.", completion = "Je sais, je sais, vous vous demandez ce qu'il va se passer par la suite. N'est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[6065] = {title = "La voie du chasseur", objective = "Parler à Yaw Sharpmane, au village Bloodhoof.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Yaw Sharpmane dans le Village Bloodhoof. Il vous guidera pour que vous trouviez votre animal de compagnie.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6066] = {title = "La voie du chasseur", objective = "Parler à Yaw Sharpmane, au village Bloodhoof.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Yaw Sharpmane dans le Village Bloodhoof. Il vous guidera pour que vous trouviez votre animal de compagnie.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6067] = {title = "La voie du chasseur", objective = "Parler à Yaw Sharpmane, au village Bloodhoof.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Yaw Sharpmane dans le Village Bloodhoof. Il vous guidera pour que vous trouviez votre animal de compagnie.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6068] = {title = "La voie du chasseur", objective = "Parler à Thotar, à Tranchecolline.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Thotar à Tranchecolline. Il vous guidera pour que vous trouviez votre animal de compagnie.", progress = nil, completion = "Oui, je pense que vous pouvez le faire aussi...", rewards = "Vous recevrez :\n\n"},
[6069] = {title = "La voie du chasseur", objective = "Parler à Thotar, à Tranchecolline.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Thotar à Tranchecolline. Il vous guidera pour que vous trouviez votre animal de compagnie.", progress = nil, completion = "Oui, je pense qu'il est temps de vous entraîner...", rewards = "Vous recevrez :\n\n"},
[6070] = {title = "La voie du chasseur", objective = "Parler à Thotar, à Tranchecolline.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Thotar à Tranchecolline. Il vous guidera pour que vous trouviez votre animal de compagnie.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6071] = {title = "La voie du chasseur", objective = "Parler à Dazalar, à Dolanaar.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Dazalar, à Dolanaar. Il vous mettra sur la voie, et vous montrera comment avoir votre propre familier.", progress = nil, completion = "Oui, il est temps, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[6072] = {title = "La voie du chasseur", objective = "Parler à Dazalar, à Dolanaar.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Dazalar, à Dolanaar. Il vous mettra sur la voie, et vous montrera comment avoir votre propre familier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6073] = {title = "La voie du chasseur", objective = "Parler à Dazalar, à Dolanaar.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Dazalar, à Dolanaar. Il vous mettra sur la voie, et vous montrera comment avoir votre propre familier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6074] = {title = "La voie du chasseur", objective = "Parler à Grif Wildheart, à Kharanos.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez voir Grif Wildheart, à Kharanos. Il vous guidera sur la voie du domptage et vous montrera comment avoir votre propre familier.", progress = nil, completion = "Oui, je pense qu'il est temps...", rewards = "Vous recevrez :\n\n"},
[6075] = {title = "La voie du chasseur", objective = "Parler à Grif Wildheart, à Kharanos.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez voir Grif Wildheart, à Kharanos. Il vous guidera sur la voie du domptage et vous montrera comment avoir votre propre familier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6076] = {title = "La voie du chasseur", objective = "Parler à Grif Wildheart, à Kharanos.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez voir Grif Wildheart, à Kharanos. Il vous guidera sur la voie du domptage et vous montrera comment avoir votre propre familier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6081] = {title = "Entraîner la bête", objective = "Adressez-vous à Orkmar Grimshot à Orgrimmar.", description = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez aussi acquérir celles qui sont nécessaires à son apprivoisement.\n\nVous devez parler à l’un de nos chasseurs les plus respectés, Ormak Grimshot. Il vous apprendra les techniques d’apprivoisement de votre nouveau familier. Vous le trouverez à proximité du Hall des braves.\n\nBonne chance, <nom>.", progress = nil, completion = "Un jeune &lt;classe&gt; je vois. Oui, je peux vous apprendre les compétences dont vous avez besoin pour entraîner et guider votre familier. Vous serez non seulement capable de lui enseigner de nouvelles techniques, mais aussi de le nourrir et de le ressusciter s’il tombe lors d'un combat.\n\nMaintenant, allez. Que la Terre-mère guide vos pas. Nous en reparlerons plus tard.", rewards = "Vous apprendrez :\n\nCours de dressage\n\nVous allez être la cible du sort suivant :\n\nDressage des bêtes\n\nVous recevrez également :\n\n"},
[6082] = {title = "Dompter la bête", objective = "Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.", description = "La dernière créature qu’il vous faut dompter est l’une de celles que vous devriez vous efforcer d’imiter : le scorpide blindé. Il frappe rapidement et avec une grande assurance ; le contrôle d’une force telle que celle-ci fait partie de votre destin de chasseur.\n\nQuand vous reviendrez, je vous offrirai les compétences qui vous permettront de dompter l’animal de votre choix. Cette créature sera à vos côtés et sous votre commandement. Elle gagnera de l’expérience de concert avec vous. Je vous montrerai également comment l'appeler et la renvoyer à volonté.", progress = "Avez-vous été capable de dompter le scorpide ?", completion = "Vous avez appris tout ce que je pouvais vous enseigner, &lt;nom&gt;. Il est temps pour vous d'utiliser ce que vous avez appris et de choisir vous-même votre familier.\n\nEt voilà, &lt;nom&gt;. Je vais maintenant vous donner le pouvoir d'apprivoiser une bête, ainsi que celui de l'appeler et de la renvoyer à volonté. Utilisez vos nouvelles compétences avec fierté ; vous les avez méritées.", rewards = "Vous apprendrez :\n\nCours d'apprivoisement\n\nVous allez être la cible du sort suivant :\n\nApprivoise une bête\n\nVous recevrez également :\n\n"},
[6083] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.", description = "L’avantage que peut vous offrir un familier en combat est certain, <nom>. Quand vous prenez le contrôle d'une créature, sa force vient s’ajouter à la vôtre. Votre familier doit véritablement devenir une extension de vous-même.\n\nLa mission suivante exige que vous tourniez le dos à la terre ferme ; vous trouverez la prochaine créature au large de la côte. De l’autre côté du village de Sen'jin, près des îles de l'Écho. Cherchez les crabes fougueux que l'on appelle les clampants de l'écume. Utilisez le Bâtonnet de domptage pour en dompter un, puis entraînez-vous à combattre à ses côtés.", progress = "Vous devez vous entraîner pour acquérir les compétences nécessaires pour contrôler votre familier efficacement. Avez-vous dompté un clampant de l'écume ?", completion = "Vous apprenez vite, &lt;nom&gt;. Vous travaillez bien.", rewards = "Vous recevrez :\n\n"},
[6084] = {title = "Dompter la bête", objective = "Domptez un Léopard des neiges à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.", description = "Ces sangliers des rochers sont assez massifs ; peut-être préféreriez-vous quelque chose de plus raffiné ? Bon d’accord, je sais maintenant… Au sud et à l’ouest, vous verrez de grands félins blancs qu’on appelle des léopards des neiges. A l’instar d’une arme ouvragée, ils sont élégants et mortels. Vous les trouverez bien plus agiles que le sanglier que vous avez dompté.\n\nPrenez ce Bâtonnet de domptage, et allez voir si vous ne préférez pas les félins.", progress = "Que diriez-vous d'un léopard des neiges, <nom> ?", completion = "Quand j'aurai le sentiment que vous avez tout appris, je vous accorderai la possibilité de choisir vous-même votre familier.", rewards = "Vous recevrez :\n\n"},
[6085] = {title = "Dompter la bête", objective = "Domptez un ours Griffeglace à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.", description = "Peut-être préférez-vous une créature qui possède une véritable force brute ? Les ours Griffeglace font d'excellents familiers pour le chasseur débutant. Ces animaux redoutables vivent à l’est de Kharanos. Voici le Bâtonnet de domptage ; essayez cet animal comme familier, pour voir s’il vous convient !\n\nQuand vous reviendrez, je vous montrerai comment dompter un animal de votre choix. Cette créature affrontera les dangers à vos côtés et gagnera de l’expérience en même temps que vous. Je vous montrerai aussi comment l'appeler et la renvoyer à volonté.", progress = "Avez-vous dompté un ours Griffeglace ?", completion = "Nous y voici, &lt;nom&gt;. Je vais maintenant vous donner le pouvoir d'apprivoiser une bête, ainsi que celui de l'appeler et de la renvoyer à volonté.\n\nTrouvez-vous un familier loyal et efficace et profitez de la chasse !", rewards = "Vous apprendrez :\n\nCours d'apprivoisement\n\nVous allez être la cible du sort suivant :\n\nApprivoise une bête\n\nVous recevrez également :\n\n"},
[6086] = {title = "Entraîner la bête", objective = "Adressez-vous à Belia Thundergranite à Ironforge.", description = "<nom>, vous avez maintenant les compétences pour dompter un animal, mais je dois également vous enseigner celles qui sont nécessaires à son apprivoisement.\n\nAllez à Ironforge et trouvez le Hall des armes. Là-bas, adressez-vous à l’une de nos dresseuses d’animaux les plus respectées, Belia Thundergranite. Elle vous montrera comment apprivoiser votre Familier. Qu’attendez-vous ?\n\nBelia est amicale et avenante, vous n’aurez pas de problèmes à lui être sympathique. Bonne chance, <nom>.", progress = nil, completion = "Une nouvelle recrue, hein ? Je vois que vous êtes sur la bonne voie pour devenir un grand &lt;classe&gt;.\n\nOui, je peux vous aider à entraîner et guider votre familier. Pas seulement à lui apprendre de nouvelles techniques, mais vous apprendre à le nourrir et le ressusciter s’il tombe lors d'un combat.\n\nN’oubliez jamais que pour obtenir le meilleur de votre familier, il faut le respecter et bien le traiter. En retour, il sera votre ami le plus loyal.", rewards = "Vous apprendrez :\n\nCours de dressage\n\nVous allez être la cible du sort suivant :\n\nDressage des bêtes\n\nVous recevrez également :\n\n"},
[6087] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof.", description = "Vous avez un esprit fougueux, impatient de se confronter à la prochaine épreuve.\n\nVotre nouvelle mission est de dompter un loup connu sous le nom de Traqueur des prairies. Cette créature est rapide et ne craint personne ; si vous la prenez comme familier, vous devrez prouver que vous avez les mêmes qualités.\n\nPendant la bataille, vous apprendrez à former une équipe de combat avec votre familier. Au terme de votre entraînement, vous aurez appris à ne faire qu'un avec lui ; un seul corps, utilisant les mêmes muscles, les mêmes idées.\n\nVoici un Bâtonnet de domptage, <nom>. Domptez un Traqueur des prairies et entraînez-vous à lutter en synergie avec lui.", progress = "Avez-vous trouvé un traqueur des prairies ?", completion = "Oui... La Terre-mère pense que vous pouvez passer à la leçon suivante.", rewards = "Vous recevrez :\n\n"},
[6088] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof.", description = "Votre tâche finale sera d'apprivoiser une créature céleste. Le rapace est un adversaire difficile, mais comme allié, vous bénéficierez de ses attaques éclair et de sa présence menaçante.\n\nPar la volonté de mère Nature, quand vous reviendrez, je vous accorderai les compétences qui vous permettront d'apprivoiser un animal de votre choix pour en faire votre compagnon. Cette créature fera face aux mêmes défis que vous et acquerra de l'expérience à vos côtés. Je vous montrerai aussi comment l'appeler et la renvoyer à votre guise.", progress = "Vous allez bientôt être prêt, <nom>.", completion = "Vous avez appris tout ce que je pouvais vous enseigner, &lt;nom&gt;. Que la Terre-mère vous bénisse et vous guide dans le choix de votre familier.\n\nVoilà, &lt;nom&gt;. Je vais maintenant vous donner le pouvoir d'apprivoiser une bête, ainsi que celui de l'appeler ou de la renvoyer à volonté. Utilisez vos nouvelles compétences avec fierté et pour l'honneur de la Terre-mère.", rewards = "Vous apprendrez :\n\nCours d'apprivoisement\n\nVous allez être la cible du sort suivant :\n\nApprivoise une bête\n\nVous recevrez également :\n\n"},
[6089] = {title = "Entraîner la bête", objective = "Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.", description = "Vous avez maintenant le pouvoir d'apprivoiser un familier, mais vous devez aussi apprendre à l'entraîner.\n\nAllez jusqu'à Thunder Bluff. Là vous irez parler à l'un de nos chasseurs les plus admirés, Holt Thunderhorn. S'il vous en juge digne, il vous apprendra à former votre nouveau familier.\n\nHolt a dressé les bêtes les plus puissantes et les plus craintes d'Azeroth et commande lui-même à de nombreuses créatures puissantes. Ses liens à la mère Nature sont forts et vous pouvez apprendre beaucoup de lui. Bonne chance, <nom> !", progress = nil, completion = "Un jeune &lt;classe&gt; je vois. Oui, je peux vous apprendre les compétences dont vous avez besoin pour entraîner et guider votre familier. Vous serez non seulement capable de lui enseigner de nouvelles techniques, mais aussi de le nourrir et de le ressusciter s’il tombe lors d'un combat.\n\nMaintenant, allez. Que la Terre-mère guide vos pas. Nous en reparlerons plus tard.", rewards = "Vous apprendrez :\n\nCours de dressage\n\nVous allez être la cible du sort suivant :\n\nDressage des bêtes\n\nVous recevrez également :\n\n"},
[6101] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", description = "Il faut tenir compte des variations de la nature, <nom>. La seule chose qui est prévisible chez elle, c'est qu'elle n'est jamais la même, elle change toujours.\n\nLes tâches que je vous donnerai à accomplir vous aideront à comprendre et à apprécier les différences qu'il y a entre les créatures que vous pouvez choisir comme compagnes.\n\nPrenez ce Bâtonnet de domptage et utilisez-le pour apprivoiser un Rôdeur sabre-de-nuit, que vous trouverez dans le sud. Exercez-vous à chasser. Alors vous commencerez à comprendre les ressemblances et les différences qui forgent la nature.", progress = "Être en accord avec la nature est la façon de vivre de tous les elfes de la nuit.", completion = "Je constate votre engagement et note que vous avez compris tout ce que je vous ai enseigné, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6102] = {title = "Dompter la bête", objective = "Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", description = "Vous avez dompté deux créatures qui vivent dans le pays, et maintenant vous devez en dompter une qui soit capable de filer dans les airs. Utilisez le Bâtonnet de domptage pour dompter un Hurleur Strigid que vous pourrez trouver plus à l’ouest. Entraînez-vous au combat avec ce grand hibou à vos côtés.\n\nQuand vous reviendrez, je vous laisserai dompter la créature de votre choix qui deviendra votre familier. Ce compagnon combattra, sans peur, à vos côtés, quels que soient les dangers et les adversaires que vous affronterez. Le familier engrangera de l’expérience en même temps que vous. Je vous apprendrai comment l'appeler et le renvoyer à volonté.", progress = "Je suis fier de votre talent, <nom>. Avez-vous achevé la dernière tâche que je vous ai confiée ?", completion = "Vous avez appris tout ce que je pouvais vous enseigner, &lt;nom&gt;. Puis-je vous donner un dernier conseil ? Choisissez avec soin votre premier familier. Allez-vous choisir une créature de la terre, de l'eau ou du ciel ? Quel que soit votre choix elle restera sans doute longtemps à vos côtés.\n\nEt voilà, &lt;nom&gt;. Je vais maintenant vous donner le pouvoir d'apprivoiser une bête, ainsi que celui de l'appeler et de la renvoyer à volonté. Utilisez vos nouvelles compétences avec fierté ; vous les avez bien méritées.", rewards = "Vous apprendrez :\n\nCours d'apprivoisement\n\nVous allez être la cible du sort suivant :\n\nApprivoise une bête\n\nVous recevrez également :\n\n"},
[6103] = {title = "Entraîner la bête", objective = "Parler à Jocaste, à l'enclave cénarienne de Darnassus.", description = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez également acquérir celles qui vous permettront de l'apprivoiser.\n\nAllez à Darnassus. Quand vous serez là-bas, parlez à l'un de nos meilleurs chasseurs, Jocaste. Elle vous apprendra à apprivoiser votre nouveau familier. Ne tardez pas.\n\nJocaste peut avoir l'air sévère, mais elle est toujours contente de voir un nouveau chasseur se perfectionner. Traitez-la avec respect, elle vous le rendra. Bonne chance, <nom>.", progress = nil, completion = "Un &lt;classe&gt; novice, je vois. Oui, je peux vous insuffler les talents dont vous avez besoin pour entraîner et guider votre familier. En plus d'être capable de lui apprendre de nouvelles techniques, vous serez capable de le nourrir, aussi bien que de le ressusciter, s'il venait à périr au combat.\n\nSouvenez-vous, &lt;nom&gt;, de toujours rester respectueux de l'équilibre et de la vie que la nature abrite, et restez humble en face d'elle. Maintenant, poursuivez votre chemin, nous nous reparlerons à une date ultérieure.", rewards = "Vous apprendrez :\n\nCours de dressage\n\nVous allez être la cible du sort suivant :\n\nDressage des bêtes\n\nVous recevrez également :\n\n"},
[6121] = {title = "Nouvelles leçons", objective = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.", description = "Vous êtes maintenant en mesure de faire l’apprentissage des poisons et de la maîtrise que nous, les druides, en avons, <nom>. Cénarius nous a gratifiés de la technique et du savoir qui nous permettent de purger tout poison d'un corps, grâce à une simple incantation. Ce don ne doit pas être pris à la légère… et pour que vous appreniez cette leçon capitale, vous travaillerez à traiter les affections du poison comme un véritable étudiant.\n\nAllez à Reflet-de-Lune et parlez à Dendrite Starblaze ; il vous attend pour commencer la leçon.", progress = nil, completion = "Ravi de vous voir jeune &lt;classe&gt;, et de constater que vous avez soif d'apprendre à neutraliser les poisons.\n\nPar le passé, les druides suivaient un entraînement spécifique dans ce domaine, mais vous n'allez pas l'apprendre de cette manière. Une épidémie sévit parmi les animaux d’Auberdine, et personne là-bas n’arrive à l’enrayer. On a demandé l'aide de Reflet-de-Lune et nous vous envoyons dans ce but. Ce n'est pas un entraînement, des vies dépendent de vous. Gardez cela en tête.", rewards = "Vous recevrez :\n\n"},
[6122] = {title = "Le principe originel", objective = "Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes.\n\nApporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage.", description = "Les chutes de la Bondissante, à Sombrivage, alimentent en eau potable toute la région. Je pense qu’elles sont la source de l’empoisonnement de la faune locale. Les daims, en particulier, sont très affectés par le mal. Utilisez cette Fiole d’échantillon pour collecter de l’eau, à l’entrée de la grotte. Faites attention, des nagas se sont installés dans une grotte, non loin de là.\n\nUne fois que la Fiole sera remplie, apportez-la à Alanndarian Nightsong, à Auberdine. Elle est l’un de ceux qui ont requis notre aide, et vous travaillerez avec elle pour traiter ce mal.", progress = "Vous êtes la personne envoyée par le Cercle cénarien de Reflet-de-Lune ? C'est merveilleux ! Nous avons un problème avec ces pauvres daims, et nous acceptons toute l'aide possible.\n\nAvez-vous un échantillon de l'eau dont Dendrite Starblaze m'a parlé ? Il m'a dit que vous en aviez récupérée et que nous pourrions travailler ensemble sur un remède...", completion = "Par Elune, cette eau est infecte ! Ce n'est pas étonnant que les daims soient malades.\n\nQuelque chose pollue l'eau, et du coup corrompt toutes celles de Sombrivage. Les daims malades ont été vus dans toutes cette zone, pas seulement près de la rivière. Même si l'eau semble être la cause de cette épidémie, il y a quelque chose d'autre qui se passe ici.\n\nCurieusement, c’est cette eau qui va nous permettre d'élaborer un remède. Pendant que je fais mes recherches, allez me chercher quelques objets pour préparer le remède...", rewards = "Vous recevrez :\n\n"},
[6123] = {title = "Rassembler les ingrédients du remède", objective = "Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède.", description = "L’eau servira de base au remède que je vais préparer pour guérir les daims. Pour que ses propriétés curatives se révèlent, il me faut encore de la terrestrine. Les herboristes savent où la trouver et comment la collecter. De fait, si vous n’êtes pas vous-même herboriste, il vous faudra trouver quelqu’un qui le soit et qui puisse nous aider.\n\nEnfin, pour donner au remède toutes ses vertus, j’aurai besoin de quelques champignons lunaires. Les trouver n’est pas difficile, ils poussent dans les grottes, un peu plus à l’est. Soyez toutefois sur vos gardes lorsque vous serez dans ces grottes, car des séléniens y résident qui sont particulièrement hostiles quand ils surprennent des intrus.", progress = "Avez-vous les réactifs dont j'ai besoin pour préparer le remède ? Les daims ne vont pas se rétablir par eux-mêmes, vous devez vous dépêcher si nous voulons les sauver !", completion = "C'est bien, &lt;nom&gt;, il y en a suffisamment pour faire assez de doses de baume – tout au moins assez pour que son effet soit visible.\n\nContrer un poison peut être difficile car chacun réagit à un antidote spécifique. Comment imaginer neutraliser un poison sans se soucier des ingrédients nécessaires pour élaborer l'antidote ?\n\nMaintenant, laissez-moi travailler !", rewards = "Vous recevrez :\n\n"},
[6124] = {title = "Soigner la maladie", objective = "Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d’abord entre le sud de la rivière Bondissante et le nord d’Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d’Ashenvale.", description = "La quantité de remède constituée à partir des ingrédients que vous m’avez apportés suffit tout juste pour dix doses, <nom>. Pendant que je travaille de concert avec ceux du village pour essayer d’en produire plus, je voudrais vous demander de nous aider à gagner du temps. Tout autour de Sombrivage vivent des daims malades ; utilisez le remède sur eux et guérissez-les de leur affection.\n\nDendrite Starblaze, à Reflet-de-Lune, voudra vous parler, quand vous en aurez fini. Veuillez également transmettre les remerciements d’Auberdine au Cercle cénarien... et laissez-moi vous remercier en personne pour l’aide que vous avez fournie !", progress = nil, completion = "Vous vous êtes bien acquitté de votre tâche : soigner les daims malades de Sombrivage. Ils sont les innocentes victimes de la corruption qui se répand sur le pays. À Darnassus, certains ont conscience du péril… et d'autres ont choisi d'ignorer les signes. J'espère que vous ne serez pas de ceux qui se mettent des oeillères pour éviter de voir les faits tels qu'ils sont, &lt;nom&gt;.\n\nQuoiqu'il en soit, vous avez fait vos preuves comme ami de la nature et du Cercle - ceci en sera le symbole.", rewards = "Vous recevrez :\n\nSac médecine de voile-poussière"},
[6125] = {title = "Pouvoir contre le poison", objective = "Retourner voir Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", description = "Vous avez appris ce que signifie guérir un empoisonnement sans en appeler à des moyens spirituels. Rappelez-vous ce que les autres doivent endurer en combattant les afflictions de l'empoisonnement, quand vous aurez définitivement acquis votre pouvoir de guérison du poison.\n\nVous devriez retourner voir Mathrengyl Bearwalker, à Darnassus, <nom>. Il a, à n’en pas douter, un sort de première importance à vous apprendre, maintenant que vous avez appréhendé les leçons qui vous ont été données.\n\nAdieu, jeune druide. Nous nous reparlerons un jour.", progress = nil, completion = "Bon retour parmi nous ! J'ai suivi vos progrès depuis votre départ, et je dois admettre que j'ai été surpris en apprenant la situation à Auberdine. Elle mérite une investigation plus approfondie, car l’introduction de tels poisons dans l’environnement est un facteur de déséquillibre.\n\nJe constate que vous gardez votre sang-froid dans les situations critiques. Pour cela, je vous récompense en vous donnant un pouvoir permanent sur le poison. Utilisez-le à bon escient, &lt;nom&gt;... à bon escient.", rewards = "Vous allez être la cible du sort suivant :\n\nGuérison du poison\n\nVous recevrez :\n\n"},
[6126] = {title = "Nouvelles leçons", objective = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.", description = "Vous êtes maintenant en mesure de faire l’apprentissage des poisons et de la maîtrise que nous, les druides, en avons, <nom>. Cénarius nous a gratifiés de la technique et du savoir qui nous permettent de purger tout poison d'un corps, grâce à une simple incantation. Ce don ne doit pas être pris à la légère… et pour que vous appreniez cette leçon capitale, vous travaillerez à traiter les affections du poison comme un véritable étudiant.\n\nAllez à Reflet-de-Lune et parlez à Dendrite Starblaze ; il vous attend pour commencer la leçon.", progress = nil, completion = "Ravi de vous voir, jeune &lt;classe&gt;, et de constater que vous avez soif d'apprendre à neutraliser les poisons.\n\nPar le passé, les druides suivaient un entraînement spécifique dans ce domaine, mais vous n'allez pas l'apprendre de cette manière. Une épidémie sévit parmi les animaux de la Croisée des Tarides, et personne là-bas n’arrive à l’enrayer. On a demandé l'aide de Reflet-de-Lune et nous vous envoyons dans ce but. Ce n'est pas un entraînement, des vies dépendent de vous. Gardez cela en tête.", rewards = "Vous recevrez :\n\n"},
[6127] = {title = "Le principe originel", objective = "Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l’eau d’un bassin, au sommet du Pic de Brume-funeste.\n\nApporter ensuite la Fiole d'échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides.", description = "Le pic de Brume-funeste, au nord-ouest de la Croisée, est sans doute la source d'où le poison se répand. Sur ces pics se trouvent des bassins qui influencent le climat. Je suspecte que l'eau a été contaminée par les membres du culte démoniaque de la Lame ardente.\n\nUtilisez cette Fiole d'échantillon pour collecter de l'eau dans le bassin qui se trouve tout en haut du pic. Une fois remplie, apportez-la à Tonga Runetotem, à la Croisée. Il est l'un de ceux qui ont requis notre aide, et vous travaillerez avec lui pour trouver un remède à ce mal.", progress = "Vous êtes la personne envoyée par le Cercle cénarien de Reflet-de-Lune, non ? C'est une chance pour nous ! Nous sommes dans l'impasse avec les gazelles malades qui se trouvent dans les Tarides du nord ; nous acceptons toute l'aide possible.\n\nAvez-vous l'échantillon d'eau dont Dendrite Starblaze a parlé ? Il m'a dit que vous en aviez récupéré un et que nous pourrions travailler ensemble sur un remède...", completion = "Par mes ancêtres, cette eau est répugnante ! Pas étonnant que les gazelles soient malades.\n\nQuelque chose pollue l'eau, et commence à ravager l'écosystème des Tarides du nord. Des gazelles malades ont été aperçues sur tout le nord de la route qui traverse le secteur d'est en ouest. Cette eau est sûrement une source primaire de la maladie, mais il y a également autre chose en oeuvre ici.\n\nCette eau, que vous le croyiez ou non, nous aidera à fabriquer un remède. Pendant que je vais l'analyser, allez donc me chercher les quelques ingrédients dont j'ai besoin pour la fabrication du remède...", rewards = "Vous recevrez :\n\n"},
[6128] = {title = "Rassembler les ingrédients du remède", objective = "Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Runetotem, à la Croisée, pour qu'il puisse préparer un baume curatif.", description = "L’eau sera l'ingrédient de base du baume curatif que je vais faire pour les gazelles. Pour y adjoindre des propriétés proprement curatives, j’aurai besoin de Terrestrine. Les herboristes savent où et comment trouver ce composant ; aussi, si vous n’êtes pas vous-même herboriste, vous faudra-t-il trouver quelqu’un qui le soit et qui veuille bien nous aider.\n\nEnfin, pour que le remède révèle toutes ses vertus, il faudra intégrer à sa préparation des cornes de kodos. De simples fragments de corne ne suffiront pas. Des kodos à votre portée hantent le nord des Tarides. Sacrifiez-en quelques-uns, <nom>, et rapportez-moi leurs cornes.", progress = "Avez-vous les réactifs dont j'ai besoin pour faire le baume ? Les gazelles ne vont pas se rétablir par elles-même, vous devez faire plus d'efforts pour les sauver !", completion = "C'est bien, &lt;nom&gt;, il y en a suffisamment pour un grand nombre de doses de baume – tout du moins assez pour commencer à changer les choses.\n\nPréparer un remède à un poison peut être bien difficile car chacun réagit à un antidote spécifique. Comment imaginer neutraliser un poison sans se soucier des ingrédients nécessaires pour élaborer l'antidote ?\n\nMaintenant, laissez-moi travailler !", rewards = "Vous recevrez :\n\n"},
[6129] = {title = "Soigner la maladie", objective = "Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.", description = "J’ai pu faire dix doses de ce remède, <nom>. Pendant que je commence à travailler avec les autorités locales pour la fabrication de doses supplémentaires, je voudrais que vous nous aidiez à prendre les choses en main. Tout autour des Tarides du nord vivent des gazelles malades ; utilisez le remède sur elles et guérissez-les de leur affection.\n\nDendrite Starblaze, à Reflet-de-Lune, voudra vous parler une fois que cela sera fait. Vous n’oublierez pas de remercier ceux du Cercle cénarien... et j’en profite également pour vous adresser mes plus sincères remerciements pour ce que vous avez fait !", progress = nil, completion = "Vous avez bien fait de vous occuper des gazelles malades des Tarides, ce sont des victimes de la pollution et de la corruption qui se répandent à travers le pays. Vous, les taurens, êtes ceux qui peuvent le mieux comprendre les voies de Cénarius. Comme vos aînés à Thunder Bluff, vous prouvez que la nécessité de l’équilibre transcende la barrière entre les races.\n\n&lt;nom&gt;, vous avez prouvé votre valeur en tant qu'ami de la nature et du Cercle, prenez ce symbole de cette relation.", rewards = "Vous recevrez :\n\nSac médecine de voile-poussière"},
[6130] = {title = "Pouvoir contre le poison", objective = "Retourner voir Turak Runetotem, sur la Cime des Anciens, à Thunder Bluff.", description = "Vous avez appris ce que signifie guérir un empoisonnement sans en appeler à des moyens spirituels. Rappelez-vous ce que les autres doivent endurer en combattant les afflictions de l'empoisonnement, quand vous aurez définitivement acquis votre pouvoir de guérison du poison.\n\nVous devriez retourner voir Turak Runetotem, à Thunder Bluff, <nom>. Il a, à n’en pas douter, un sort de première importance à vous apprendre, maintenant que vous avez appréhendé les leçons qui vous ont été données.\n\nAdieu, jeune druide. Nous nous reparlerons un jour.", progress = nil, completion = "Bon retour parmi nous ! J'ai suivi vos progrès depuis votre départ, et je dois admettre que j'ai été surpris en apprenant la situation à la Croisée. Elle mérite une investigation plus approfondie, car l’introduction de tels poisons dans l’environnement est un facteur de déséquillibre.\n\nJe constate que vous gardez votre sang-froid dans les situations critiques. Pour cela, je vous récompense en vous donnant un pouvoir permanent sur le poison. Utilisez-le à bon escient, &lt;nom&gt;... à bon escient.", rewards = "Vous allez être la cible du sort suivant :\n\nGuérison du poison\n\nVous recevrez :\n\n"},
[6131] = {title = "Allié des Grumegueules", objective = "Grifleur veut que vous prouviez votre valeur en tuant 5 Guerriers Mort-bois, 5 Guides Mort-bois et 5 Jardiniers Mort-bois.", description = "Les Grumegueules sont les seuls furbolgs à avoir résisté à la corruption. Pourtant, de nombreuses races exécutent maintenant tous les furbolgs, sans distinction, sans même prendre le temps de s'assure qu'ils sont amis ou des ennemis. Pour cette raison, les Grumegueules sont devenus farouches et ne font plus confiance à personne.\n\nVoulez-vous faire vos preuves et faire montre de courage ? Si vous forcez la tribu corrompue des Mort-bois à battre en retraite, nous vous considérerons peut-être comme un être digne de confiance. Vous trouverez les guerriers, les guides et les jardiniers Mort-bois plus bas vers le sud.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[6132] = {title = "Faites-moi sortir de là !", objective = "Escorter Melizza Brimbuzzle, puis parler à Hornizz Brimbuzzle au cimetière des Kodos en Désolace.", description = "Sortez-moi d'ici !\n\nJ'ai voyagé jusqu'à la Vallée des Lances pour parler aux Maraudine. Je croyais que je pourrais faire des affaires avec eux... mais ils ne veulent rien entendre. Je crois que la seule chose qui les intéresse est de me dévorer !\n\nSortez-moi d'ici, mon frère Hornizz vous paiera largement pour cela ! Il se trouve dans notre camp, à côté du Cimetière des kodos, à l'est.\n\nFaites vite, <nom>. Il n'y a pas deux minutes, j'ai entendu certains centaures envisager de collecter du bois pour chauffer leur marmite...", progress = nil, completion = "Ma soeur Melizza a dit que vous alliez venir. Grand merci pour l'avoir sortie du pétrin dans lequel elle était ; malheureusement, elle s'est probablement déjà fourrée dans un autre depuis !", rewards = "Vous recevrez :\n\n"},
[6133] = {title = "L'ordre du seigneur forestier", objective = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.\n\nTuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons.", description = "Les hauts-elfes du gîte de Quel'Lithien possèdent quelque chose qui m'appartient, <classe> : un document détaillant ma vie de mortel.\n\nAvant que vous ne posiez la question, je vous réponds : non, vous n'avez pas à être dans le secret de telles informations. Faites seulement ce qu'on vous dit, vermisseau : récupérez le registre, point final.\n\nEt, imbécile, veillez bien à dispenser autant de discorde et de chagrin que possible, sur votre passage. Semez autant de souffrances que vos compétences vous le permettent...", progress = "Ne me faites pas attendre, <classe>.", completion = "Je suis sûr que vous n'avez pas lu le registre. Pas même vous ne feriez quelque chose d'aussi stupide.", rewards = "Vous recevrez :\n\n"},
[6134] = {title = "Chasse à l'ectoplasme", objective = "Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace.", description = "Il y a une vallée au sud-est, la vallée des Ossements, qui est hantée par les fantômes magram. Effrayant, n'est-ce pas ? Et si ça l'est pour nous, imaginez ce que les Magram en pensent ! Si nous capturons l'énergie ectoplasmique de cet endroit, je parie que ça vaudra une fortune chez les centaures.\n\nPrenez cette caisse d'aimants fantômes. Si vous en placez un entre les deux grands squelettes de la vallée, les Goliaths morts, les fantômes se matérialiseront et s'y rendront. Attaquez ces fantômes et prenez leur Fantôm-o-plasme, nous le revendrons aux Magram.", progress = "Où est mon Fantôm-o-plasme, <nom> ?", completion = "Le voilà ! On dirait que vous en avez un peu sur vos habits aussi. Gluant, n'est-ce pas ?\n\nBien, merci beaucoup pour tous les problèmes endurés, &lt;nom&gt;. Ce matériel va valoir une fortune... Si je peux convaincre les centaures de ce que c'est !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards du condorTarge d'Anchorhold\n\nVous recevrez également :\n\n"},
[6135] = {title = "Crépuscaile, oh comme je te hais !", objective = "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur.\n\nIl paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris.", description = "Vous avez, pour l’instant, réussi toutes les missions que je vous ai confiées ; même si vous ne l’avez pas fait de la manière la plus opportune qui soit.\n\nJe suppose que vous vous sentez en mesure d’affronter de nouveaux défis. Oui, oui, imbécile, peut-être que vous avez en effet les moyens de réussir une nouvelle série d’épreuves.\n\nLa chauve-souris démoniaque albinos, Crépuscaile, ravage la contrée, plus au nord. Traquez-la et exécutez-la. Revenez me voir ensuite avec une touffe de sa fourrure blanche. Vous recevrez une récompense en cas de réussite.", progress = "Je ne vous conseille pas d'accepter ce défi sans aide, <classe>.", completion = "Excellent travail, imbécile ! Je vais pouvoir travailler cette fourrure pour en faire quelque chose dont vous pourrez vous servir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de CrépuscaileMantelet de Crépuscaile\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6136] = {title = "Le corpulent", objective = "Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée.", description = "Devant le campement de l'Aube d'argent appellé Espoir de Lumière, à l'ouest de Valnord, vous trouverez une énorme larve, Creusechair.\n\nJ'ai perdu des régiments entiers contre ce monstre. Sa taille ne connaît aucune limite ! Plus il mange, plus il grossit...\n\nÇa ne m'empêcherait pas de dormir si la bête vous dévorait, mais je préférerais que vous soyez vainqueur. Je vous recommande d’engager quelques personnes pour vous aider dans cette mission. Creusechair est connu pour avoir dévoré de petits bataillons assez idiots pour l'attaquer.", progress = nil, completion = "Continuez comme ça et je pourrais avoir à vous promouvoir de 'simple imbécile' à 'déficient mental', première classe.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCracheur d'ichorMarteau de SkullstoneGuide de Sarah\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6141] = {title = "Frère Anton", objective = "Adressez-vous au frère Anton, en Désolace.", description = "Mon frère d’armes, le frère Anton, a entendu parler d’une infestation de morts-vivants, sur les terres lointaines de Kalimdor, dans un pays connu sous le nom de Désolace. Anton a immédiatement décidé de se rendre sur place pour anéantir la menace représentée par ces morts-vivants !\n\nIl cherche à enrôler des volontaires courageux, prêts à l’aider dans cette entreprise. Si votre âme est pure, allez voir Anton. Il se trouve en Désolace, dans la ville de l’Alliance appelée la Combe de Nijel.", progress = nil, completion = "J'ai reçu un message disant que nous allions recevoir de l'aide venant de l'Est. Est-ce que c'est vous ? Vous venez aider les Frères écarlates dans leur croisade ?\n\nSi c'est le cas, écoutez attentivement...", rewards = "Vous recevrez :\n\n"},
[6142] = {title = "Des praires comme appât", objective = "Trouver 10 morceaux de Chair de praire et les apporter à Mai'Lahii, à Proie-de-l'Ombre.", description = "Vous avez tout l'air d'un pêcheur, <classe> ! J'adore pêcher, et j'ai pratiqué cette activité pendant toute ma vie. Le meilleur appât qui existe est sans aucun doute la chair de praire ; les poissons n'y résistent pas, si vous voyez ce que je veux dire.\n\nPlus au nord, vous verrez un navire échoué, au large de la côte. Les praires en question jonchent la zone. Si vous me rapportez 10 morceaux de chair de praire, je vous donnerai quelque chose en échange.", progress = "Je suis impatient d'aller pêcher avec un peu de chair de praire fraîche. M'avez-vous apporté les 10 morceaux dont j'ai besoin ?", completion = "Parfait, c'est juste ce que le Sorcier docteur m'a dit de faire pour ma migraine. Il a dit : \"Mai'Lahii - allez à la pêche. Vous vous sentirez mieux\"\n\nEffectivement, je me sens déjà mieux, merci !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoignes de PardocCeinturon de RingtailCeinture d'acier armé\n\nVous recevrez également :\n\n"},
[6143] = {title = "D'autres poissons à frire", objective = "Tuer 7 Myrmidons Ondulame, 7 Nagas Ondulame et 5 Sorcières Ondulame, puis parler à Drulzegar, à Proie-de-l'Ombre, en Désolace.", description = "Peut-être en avez-vous entendu parler, peut-être pas... Mon équipage et moi-même étions en train de pêcher près de l'île de Ranazjar, au nord du bateau détruit qui se trouve au large de la côte nord. Nous avons toujours pêché là… Maintenant je ne cherche plus qu'à venger mes camarades tués.\n\nLes nagas nous ont attaqués un matin, ils ont tué tout le monde sauf moi.\n\nJe me sens coupable d'avoir survécu. J'ai besoin d'un <classe> qui exterminerait les nagas pour moi. Je ferai en sorte que vous ne regrettiez pas vos efforts. Vous pensez pouvoir m'aider ?", progress = nil, completion = "Il est doux d’apprendre que les nagas ont été vaincus, mais mon cœur souffre toujours d'un vide immense. Je vais consacrer ma vie à leur destruction.\n\nVoilà la récompense promise, l’ami . C'est vraiment peu de chose comparé à la satisfaction de savoir que les nagas ont souffert pour ce qu’ils ont fait à mon équipage.", rewards = "Vous recevrez :\n\n"},
[6144] = {title = "L'appel du commandement", objective = "Aller à Undercity et parler à Varimathras.", description = "L'ordre vient d'arriver, <classe>. Varimathras lui-même demande que j’envoie mes agents les plus “capables” à Undercity pour une opération tactique très délicate.\n\nMalheureusement, mes agents les plus “capables” ont été tués il y a plus de trois ans. Ce qui me reste, c'est un ramassis de racailles décérébrées.\n\n<Nathanos vous regarde fixement et froidement.>\n\nAllez à Undercity immédiatement et présentez-vous à Varimathras. Ne me mettez pas dans l'embarras, <classe> !", progress = nil, completion = "Le Grand Croisé est bien en sécurité dans le Bastion écarlate pendant que ses forces affluent sur vos terres, souillant vos édifices et vos monuments, assassinant vos gens.\n\nLa Dame noire a ordonné que je m'occupe de cet insecte une fois pour toutes. Vous allez devenir l'instrument de la vengeance des Réprouvés.", rewards = "Vous recevrez :\n\n"},
[6145] = {title = "Le messager cramoisi", objective = "Retourner dans les Maleterres de l’est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand Croisé.\n\nApporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires.", description = "De même que le corps ne peut pas survivre sans la tête, la tête ne peut pas survivre sans le corps. Les défenses du commandement de la Croisade écarlate, à Stratholme, sont presque impénétrables. Plutôt que d'essayer de les enfoncer, nous allons séparer le corps de la tête.\n\nMes Traqueurs noirs ont rassemblé des données sur les activités de la Croisade à l'extérieur de Stratholme. Chaque jour, un rapport est envoyé de leur commandement central à la Main de Tyr. Ce rapport est la clé, <race> ! Trouvez le Messager cramoisi et récupérez ce rapport. Rapportez-le à Nathanos.", progress = "Si vous réussissez maintenant, alors vous aurez presque gagné mon respect, <classe>.", completion = "&lt;Nathanos rit.&gt;\n\nExcellent ! Enfin ! Une occasion de détruire l'Oracle écarlate !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6146] = {title = "La ruse de Nathanos", objective = "Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d’avoir revêtu l’apparence d’un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar.", description = "J'ai fait quelques ajustements à cette commande. Si notre petite ruse fonctionne, ils exposeront l'Oracle écarlate et nous frapperons !\n\nMaintenant, prêtez-moi attention, <classe>. Vous devez livrer cette commande au Seigneur croisé Valdelmar.\n\nComment ? Vous allez le lui remettre, imbécile !\n\nApportez la commande et cette pomme pourrie à la Main de Tyr. Quand vous traverserez la ville, mangez la pomme. Vous vous transformerez en quelque chose de plus... acceptable pour les gens. Prenez la commande et remettez-la au Seigneur croisé Valdelmar.", progress = "C'est inacceptable, soldat !", completion = "Où étiez-vous ? Nous vous pensions entre les mains du Fléau.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6147] = {title = "Retourner voir Nathanos", objective = "Retourner voir Nathanos le Flétrisseur avec la nouvelle information.", description = "Le Grand Croisé fait une demande peu commune. Cependant... Ce qu'il demande sera fait. Retournez au Bastion écarlate et dites-lui que l'Oracle prendra bientôt la route.\n\nNous prendrons toutes les précautions pour assurer sa protection jusqu'à Stratholme.", progress = nil, completion = "Les imbéciles ! Ma ruse est passée inaperçue ! Préparez-vous, &lt;classe&gt;. Nous devons frapper avec habileté !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6148] = {title = "L'Oracle écarlate, Demetria", objective = "La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholm, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur.", description = "Demetria est la Conseillère en chef du Grand Croisé. On l'appelle l'Oracle en raison de ses sens un peu \"irréels\". Elle a aidé efficacement la Croisade à remporter plusieurs victoires contre le Fléau.\n\nMême si la ruse qui consiste à l'exposer est couronnée de succès, vu ses pouvoirs psychiques, elle s'attendra sans doute à avoir des ennuis. C'est vous qui allez provoquer ces ennuis. \n\nPoursuivez l'Oracle et tuez-la. Ils doivent être en train de quitter la Main de Tyr pendant que nous parlons. Faites ma fierté, petit ver.", progress = nil, completion = "Ce coup va les faire chanceler pendant des années ! Bien joué, &lt;nom&gt; ! Vous avez non seulement gagné mon respect mais aussi cette récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc GorewoodTempétueuseProtecteur sacré\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6161] = {title = "Revendiquer le trésor de Rackmore !", objective = "Trouver la Clé d'argent de Rackmore. Trouver la Clé d'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore.", description = "Le journal de Rackmore explique comment son bateau a été attaqué par des créatures marines alors qu'il naviguait vers le bastion de Feathermoon. Pour empêcher son trésor de tomber dans des mains ennemies, il a caché son coffre sur l'île de Ranazjar.\n\nPour l'ouvrir, il faut deux clés, une en argent et une en or. Elles ont été perdues, mais un trésor attend celui qui retrouvera les clés et le coffre !", progress = "Ce coffre est bien fermé.", completion = "Le coffre ouvert révèle le trésor de Rackmore !", rewards = "Vous recevrez :\n\nRoue du capitaine RackmoreBarre du capitaine Rackmore"},
[6162] = {title = "La dernière bataille d'un mari", objective = "Tuer le Seigneur Ror et apporter sa Griffe à Dreka'Sur, au Poste de la Vénéneuse, en Gangrebois.", description = "Mon mari a traversé Gangrebois pour l'honneur de notre clan, en se battant contre le Conseil des ombres et d'autres atrocités corrompues ! Il a échappé à la mort de nombreuses fois.\n\nEnsuite, j'ai reçu une lettre de lui disant qu'un druide avait requis son aide pour lutter contre un puissant furbolg infecté nommé le seigneur Ror. Depuis, je n'ai plus de nouvelles ni de l'un ni de l'autre.\n\nJe veux la main griffue de ce Ror, <nom>. Je veux qu'il paye pour avoir fait de moi une veuve ! Je crois que la créature est au sud... près de la frontière d'Ashenvale.", progress = "Avez-vous la tête de la bête, <nom> ? Elle payera pour ses crimes. Que cela soit dû à la corruption ou à la colère de vivre dans cette forêt lugubre, cela ne m'intéresse pas. Aucun furbolg ne vivra longtemps s'il commet ce genre de crime contre ma famille !", completion = "Vos nouvelles m'apportent fierté et honneur. Mon mari est mort au combat, il aurait été fier de cela. Mais mon esprit ne sera jamais en paix tant que je saurai que la créature qui m'a forcée à vivre seule n'a pas payé pour ce qu'elle a fait.\n\nEncore merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6163] = {title = "Ramstein", objective = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos.", description = "J'ai été dépassé. Sur cette terre même, je suis resté debout... J'ai cherché à défendre Lordaeron. La ferme et tout ce qu'il y avait dessus ont été balayés par une immense onde du Fléau.\n\nSaleté. Il a plané au-dessus de moi, les entrailles sortant de l’abdomen.\n\nQuand je me suis réveillé, je faisais partie du Fléau. Je suis resté impuissant pendant si longtemps. Mon esprit était lié à celui du roi-liche.\n\nElle est venue pour moi... Quelque part, d'une façon ou d'une autre, je savais qu'elle le ferait. Libre.\n\nEt maintenant, je dois avoir ma vengeance – ma vengeance qui est ma seule raison de vivre. Détruisez-le.", progress = "Après avoir été libéré par Sylvanas, j'ai chassé cette bête en vain pendant des mois. Elle a fui et s'est réfugiée à Stratholme. Saleté...", completion = "Je me demande... A-t-il imploré grâce ? Savait-il seulement ce que c'est ?\n\n&lt;Nathanos crache.&gt;\n\nJe vais accrocher cette tête sur mon mur.\n\nVous avez gagné votre place parmi mes champions, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSceau royal d'AlexisCercle élémentaire\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6164] = {title = "Le livre de compte d'Augustus", objective = "Apporter le Livre de compte d'Augustus à Augustus le Touché à Val-Terreur.", description = "Je suis prêt à faire affaire ! Qu'est-ce que vous voulez ?\n\nOh attendez !... Je ne peux pas ouvrir le magasin sans mon livre de compte. Comment puis-je suivre les transactions sans mon livre de compte ?\n\nJ'ai dû le laisser en ville. J'avais une chambre à l'auberge... Le livre doit y être.\n\nRapportez-moi mon livre. Je vous en prie, rapportez-le-moi ! Apportez-moi mon livre et vous verrez ! J'ouvrirai le magasin et vous verrez que mes prix sont FOUS !", progress = "Avez-vous mon livre de compte ? Je suis pressé de reprendre le travail !", completion = "Et voilà ! Ma parole ! J'avais oublié qu'il était aussi plein !\n\nC'est un jour glorieux, &lt;nom&gt; ! Prodigieux ! Un incroyablement bon jour, je vous le dis !", rewards = "Vous recevrez :\n\n"},
[6181] = {title = "Un message rapide", objective = "Apporter la Note de Lewis à Thor, le Maître des gryphons.", description = "Bien que Stormwind ne nous aide pas beaucoup directement, j'ai quand même un contact dans la ville qui nous permet de nous procurer des armures. Son nom est Osric Strang. Son magasin, “ Immunité limitée ”, est dans la vieille ville de Stormwind.\n\nNotre réserve d'armures diminue et je dois entrer en contact avec Osric pour en obtenir. Pouvez-vous lui porter cette note ?\n\nLa façon la plus rapide d'aller à Stormwind est de demander à Thor, notre Maître des gryphons. Il est juste en bas de la colline, apportez-lui ma note et prenez ensuite un gryphon pour Stormwind.", progress = "Vous avez l'air d'être une personne pressée. Bien, vous êtes au bon endroit !", completion = "Vous devez apporter cette note à Stormwind ? Ce n'est pas un problème, vous pouvez prendre un de mes gryphons !", rewards = "Vous recevrez :\n\n"},
[6182] = {title = "Le premier et le dernier", objective = "Parler à Mathias Shaw, dans la vieille ville de Stormwind. Il se trouve dans la caserne.", description = "Nathanos Marris était le premier et le dernier des seigneurs forestiers humains. Un disciple de Sylvanas Windrunner, qui est maintenant la reine banshee des Réprouvés.\n\nNous pensions que Nathanos avait été tué en défendant Lordaeron il y a cinq ans. Bien que son cadavre n'ait jamais été retrouvé, nous supposions qu'il n'était pas ressorti des Maleterres de l'Est.\n\nMathias Shaw a enquêté sur cette disparition et a peut-être de nouvelles informations. Retournez le voir immédiatement. Il réside dans la caserne de la vieille ville.", progress = nil, completion = "Après avoir reçu des rapports concernant une activité inhabituelle des Réprouvés dans les Maleterres de l'Est, les agents du SI:7 ont été dépêchés sur place. Le résultat de leur enquête est assez troublant.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6183] = {title = "Honorer la mort", objective = "Reparlez à Mathias Shaw, quand vous aurez décidé d’accepter son travail.", description = "Cinq de mes meilleurs agents sur le terrain ont été affectés au cas Marris. Un seul est revenu, pour mourir dans son sommeil trois jours plus tard.\n\nLe peu d'information que nous avons réussi à obtenir de lui était du charabia. Nous n’avons compris que deux mots : \"Nathanos\" et \"Flétrisseur\".\n\nJe n'ai personne de disponible pour continuer cette enquête et Ravenholdt ne nous aidera pas. Nous devons aller jusqu'au bout, ne serait-ce que par respect pour les familles de ceux qui sont morts. M'aiderez-vous ?", progress = nil, completion = "&lt;Mathias hoche la tête.&gt;\n\nJe m'attendais à ce que Bolvar m'envoie des hommes et des femmes d'honneur – les soldats les plus dévoués de l'Alliance.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6184] = {title = "Flint Shadowmore", objective = "Allez au camp du Noroît, dans les Maleterres de l’ouest, et rencontrez votre contact, Flint Shadowmore.", description = "La seule information dont nous disposons aujourd'hui est que Nathanos Marris a peut-être été tué par ce Flétrisseur. Nous supposons que le Flétrisseur est aussi le démon qui s'est occupé de mes agents.\n\nUn autre SI:7 opérationnel, Flint Shadowmore, se trouve au campement de l'Alliance à la Pointe du Noroît, dans les Maleterres de l'Ouest. Trouvez-le, il vous fera un compte rendu sur la situation dans les Maleterres et vous donnera des ordres.\n\nBonne chance, <nom> !", progress = nil, completion = "La première mission va être simple, &lt;nom&gt;. Vous entrez, vous sortez. Voilà !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6185] = {title = "Les Maleterres de l'Est", objective = "Fouillez les Maleterres de l’est pour trouver des indices relatifs au \"Flétrisseur\" et aux agents du SI:7 portés disparus. Si vous trouvez un quelconque Insigne du SI:7, rapportez-le à Flint Shadowmore, au camp du Noroît.", description = "Comme je vous l'ai dit, votre première mission est une mission de reconnaissance. Rien d'extraordinaire, <nom>. Vous devez vous rendre dans les Maleterres de l'Est et chercher des informations sur ce Flétrisseur.\n\nCherchez aussi des informations sur nos agents secrets disparus. Nous supposons qu'ils sont morts et si c'est le cas, il doit bien y avoir leurs cadavres... quelque part.\n\n<Flint avale durement.>\n\nTous les agents SI:7 portent cet insigne.\n\n<Flint vous montre son insigne SI:7.>\n\nRapportez-moi tous ceux que vous pourrez trouver.", progress = "Est-ce que par hasard...?", completion = "Rutger. Fredo. Turyen. Tous... morts...\n\n&lt;Flint serre les insignes.&gt;\n\nOù étaient-ils ? Avez-vous découvert quelque chose sur ce salaud, le Flétrisseur ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6186] = {title = "La venue du Flétrisseur", objective = "Retourner à Stormwind et informer le généralissime Bolvar Fordragon du destin de Nathanos Marris.", description = "<Le visage de Flint est livide.>\n\nNa... Nathanos a fait cela ? Nathanos est le Flétrisseur ?\n\nPourquoi ? Il était... si noble, un seigneur forestier respecté de tous. Le seul humain jamais autorisé à recevoir la formation des hauts-elfes. Désormais il est un agent impitoyable des Réprouvés ?\n\nJe... Je suis désolé de vous demander cela, <nom>, mais le généralissime Fordragon doit être informé immédiatement de la tournure des événements. S'il vous plaît, retournez à Stormwind pour lui annoncer la nouvelle.", progress = nil, completion = "Non. C'est... NON ! Comment ? Un agent des Réprouvés ? Le CHAMPION de la reine banshee ?\n\n&lt;Le généralissime Bolvar Fordragon s'effondre.&gt;", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6187] = {title = "L'ordre doit être rétabli", objective = "Montez une armée et portez-vous vers les Maleterres de l’est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre.\n\nGardez votre présence d’esprit, <nom> : la Horde le défendra jusqu’à la mort.", description = "Savez-vous combien il existe de seigneur forestiers dans ce monde ? Combien il y a eu de seigneur forestiers humains ?\n\nCe que Nathanos a accompli était sans précédent. C'était un génie tactique, à qui l'Alliance doit toutes ses victoires pendant dix ans de conflit.\n\nEt maintenant... il est devenu le champion des Réprouvés.\n\nNon ! Cela ne peut pas rester ainsi. L'ordre doit être rétabli.\n\nLevez une armée, <nom>. Retournez vers les infestés avec votre armée et détruisez le Flétrisseur.\n\nJe vous souhaite bonne chance, <nom>. Vous en aurez vraiment besoin pour cette bataille.", progress = nil, completion = "C'est une tragédie. Je pense... je crois que notre espèce est maudite, &lt;nom&gt;. Nous sommes destinés à perdre tous nos plus grands guerriers, nos plus nobles héros, nos sages les plus avisés.\n\nNous avons une dette envers vous et je vous le promets, &lt;nom&gt;, où que soit Nathanos Marris maintenant, son sourire est sur vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc GorewoodTempétueuseProtecteur sacré\n\nVous recevrez également :\n\n"},
[6202] = {title = "<INUTILISÉ> Le bien et le mal", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPorte-cendres"},
[6241] = {title = "Les Tombe-hiver s'agitent", objective = "Salfa voudrait que vous tuiez 6 Totémiques, 6 Gardes et 6 Guides de la tribu Tombe-hiver.", description = "Les Grumegueules ont tendance à rester entre eux, <nom>. Bien que nous laissions passer ceux en qui nous avons toute confiance, nous essayons d'éviter les autres tribus de furbolgs, si cela est possible.\n\nDernièrement, j'ai remarqué que la tribu Tombe-hiver montrait des signes d'hostilité à notre égard. Ils semblent être dans un étrange état de rage, rendus furieux par tout ce qui les effraie et qu'il ne comprennent pas.\n\nSi vous pouviez en réduire le nombre, cela nous aiderait grandement, <nom>.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[6261] = {title = "Dungar Longdrink", objective = "Apportez la Caisse d'Osric à Dungar Longdrink, le Maître des gryphons.", description = "<nom>, j’ai mis dans cette caisse tout ce dont Lewis avait fait la demande. Pouvez-vous la lui apporter ?\n\nSi vous avez déjà parlé à Thor, dans la marche de l'Ouest, alors vous pouvez prendre un gryphon pour y retourner. Dungar Longdrink est notre Maître des gryphons, dans le Quartier commerçant.\n\nAllez voir Dungar, puis apportez cette caisse à Lewis, aussi vite que possible. Nous ne pouvons pas nous permettre de laisser nos frères qui combattent dans la marche sans ravitaillement !", progress = "Serait-ce de la sueur que je vois sur votre front, garçon ? Vous avez trop couru. Prenez un gryphon la prochaine fois !", completion = "Une caisse pour la marche de l'Ouest, hein ? Vous avez déjà pu vous rendre là-bas ? Si c'est le cas, pas de problème. J'ai des tas de gryphons entraînés à suivre cette route.", rewards = "Vous recevrez :\n\n"},
[6281] = {title = "Continuer vers Stormwind", objective = "Achetez un voyage en gryphon à Thor, Maître des gryphons, puis apportez la Note de Lewis à Osric Strang au magasin “Immunité limitée”, dans la vieille ville de Stormwind.", description = "Contre un modeste paiement, vous pouvez prendre un gryphon pour Stormwind, et livrer la note de Lewis à Osric. Il n’y a pas de moyen plus rapide pour se rendre sur place.\n\nSi cela vous convient, revenez me voir quand vous souhaiterez faire le voyage. Cela vous en coûtera quelque peu, mais, croyez-moi, cela le vaut bien !", progress = "Vous avez voyagé n'est-ce pas ? Avez-vous vu des endroits intéressants ?", completion = "Une note de l'Intendant Lewis ? Je ne suis pas surpris, il a besoin d'équipement. La Colline des sentinelles se trouve très loin, dans une terre que Stormwind a presque oubliée.\n\nBien, merci à vous, &lt;nom&gt;. Voici quelque argent pour vos frais.", rewards = "Vous recevrez :\n\n"},
[6282] = {title = "La menace des harpies", objective = "Maggran Earthbinder de la retraite de Roche-Soleil veut que vous anéantissiez sept Harpies, sept Embusquées, sept Tueuses et sept Volplumes Rougefuries.", description = "Les taurens se font un honneur de défendre ces terres. Vous pouvez comprendre mon inquiétude quant au nombre de harpies qui hantent les Serres-Rocheuses.\n\nLes Rougefuries sont la source de générations de harpies, toujours plus nombreuses dans Kalimdor ; elles empiètent sur toute forme de vie, gagnent du terrain, envahissent et empêchent quiconque de quitter les terres qu’elles dominent.\n\nJe veux que vous éliminiez les harpies, <nom> !", progress = nil, completion = "C'est la meilleure des nouvelles ! Racontez-moi encore comment vous avez effrayé ces viles harpies. Ces Rougefuries ont reçu un méchant coup !", rewards = "Vous recevrez :\n\n"},
[6283] = {title = "La lignée Rougefurie", objective = "Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit.", description = "Tailler dans les rangs des Rougefuries ne sera pas suffisant en soi. Le seul véritable remède à cette infestation serait d’exécuter leur chef, la créature appelée la Déchiqueteuse Rougefurie !\n\nElle est pratiquement une reine pour ces créatures hideuses. Tuez-la, et leur nombre s’effondrera assurément.\n\nRetournez dans le Val calciné, vous la trouverez dans les collines, à l’ouest. Elle ne sera pas facile à vaincre, mais la récompense pour sa mort est à la hauteur du danger.", progress = "La Déchiqueteuse Rougefurie est une dangereuse créature ! Vous pourrez la trouver le long de la colline ouest dans le Val calciné.\n\nLes Rougefuries seront sans défense sans elle... nous pourrons alors certainement les vaincre une fois pour toutes !", completion = "Je sens la colère refluer. Qu'est-ce que je vais faire de mon temps ? Savoir que le mal était tout près maintenait mon esprit en alerte, et maintenant tout est silencieux. C'est peut-être une bonne chose... Je vais pouvoir me concentrer sur le bien, comme tous les taurens devraient le faire.\n\nAcceptez, s'il vous plaît, cette récompense en échange de votre peine.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape des féesCeinture d'hurleur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6284] = {title = "Arachnophobie", objective = "Tuer Besseleth, et apporter le Croc de Besseleth à Maggran, dans la Retraite de Roche-Soleil.", description = "Attention : si vous pénétrez dans le Canyon de Sishir, à l’ouest, vous le faites à vos risques et périls.\n\nBesseleth et ses enfants arachnéens de la forêt ont pris possession du territoire, et en ont fait leur repaire et leur nid.\n\nMaggran Earthbinder, dans la Retraite de Roche-Soleil, a mis la tête de Besseleth à prix. Tuez-la et apportez une preuve de sa mort à Maggran ; vous recevrez une récompense pour avoir fait disparaître cette menace à huit pattes.", progress = "Besseleth est un prédateur sans pitié... Je m'inquiète pour ceux qui voyagent sur le sentier des Tisseuses pendant la nuit. C'est là qu'elle et ses enfants s'attaquent aux innocents voyageurs. Je suis tombé moi-même sur ses crocs qui mesurent plus de cinquante centimètres, mais heureusement j'ai réussi à la repousser et à me mettre à l'abri. Je donnerais n'importe quoi pour que ce monstre soit abattu.", completion = "Bonne chasse, &lt;nom&gt; ! Besseleth était un vieux prédateur par ici... Elle ne me manquera pas. En tant que champion de la forêt, recevez ceci en récompense.\n\n\n\nPeut-être qu'à présent plus de gens viendront à la Retraite de Roche-Soleil, sans plus avoir peur de ce qui est tapi dans le noir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEpée courte de ClaystoneBâtonnet en cristal transparent\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6285] = {title = "Aller voir Lewis", objective = "Achetez un voyage en gryphon pour la Colline des sentinelles à Dungar Longdrink, Maître des gryphons, puis apportez la Caisse d'Olric à Lewis à la Colline des sentinelles.", description = "Le Maître des gryphons de la marche de l'Ouest s’appelle Thor. Si vous lui avez déjà parlé auparavant, vous pouvez prendre l’un de mes gryphons pour y retourner.\n\nC’est une bonne chose à retenir : les gryphons sont entraînés à voler vers leur capitale, mais ils ne vous porteront vers un Maître des gryphons éloigné que si vous l'avez déjà visité auparavant.\n\nVous avez déjà parlé à Thor, vous n’avez donc qu’à revenir me voir dès que vous souhaiterez prendre un gryphon pour la marche de l'Ouest. Une fois que vous serez à destination, livrez la Caisse d'Osric à l’Intendant Lewis.", progress = "Vous revenez de Stormwind ? Est-ce qu'Osric a envoyé les armures ?", completion = "Bien, vous avez apporté les armures ! Nous allons les partager entre ceux qui en ont besoin.\n\nMerci, &lt;nom&gt;. Vous nous avez été d'une grande aide. Et maintenant que vous n'êtes plus un étranger pour les gryphons, j'espère que vous reviendrez et apporterez encore souvent votre aide à la Colline des sentinelles !", rewards = "Vous recevrez :\n\n"},
[6301] = {title = "Cycle de la renaissance", objective = "Tammra Windfield, de la retraite de Roche-Soleil, vous demande de rassembler 10 Graines de Gaea.", description = "L'avidité des industries et la guerre permanente ont détruit les Serres-Rocheuses. Seule la bénédiction de la Terre-mère peut soigner une pareille blessure.\n\n<nom>, j'ai besoin que vous récoltiez des graines spéciales, aussi nommées Graines de Gaea. On ne les trouve que dans les Serres-Rocheuses, au nord de la Retraite de Roche-Soleil, au bord du Lac Mirkfallon.\n\nUne fois que vous m'aurez rapporté les graines, je les enchanterai grâce à mes pouvoirs chamaniques, pour accélérer leur croissance.", progress = "La destruction perpétuelle que cause la guerre, et ceux qui cherchent leurs intérêts dans ce massacre, m'endolorissent profondément. Pour aider le cycle de la vie à redonner une nouvelle jeunesse aux terres, j'ai besoin de Graines de Gaea. En avez-vous, <classe> ?", completion = "Ah, &lt;nom&gt;, vous avez les graines de Gaea. Regardez, et vous verrez comme la bénédiction de la Terre-mère peut pousser ces petits grains de vie à bourgeonner et fleurir.", rewards = "Vous recevrez :\n\n"},
[6321] = {title = "Approvisionner le Sépulcre", objective = "Apporter l’Ordre de Podrig à Karos Razok.", description = "L'Exécuteur Hadrec m'a demandé de faire le point sur les réserves du Sépulcre. Avec le Fléau qui se cache dans les bois, et pire encore, il ne veut pas que les Gardes noirs manquent de matériel.\n\nJ'ai constaté que nous étions, généralement, bien approvisionnés, mais nous avons besoin de davantage d'armes pour remplacer celles perdues sur le champ de bataille.\n\nVoici un ordre de réquisition pour ce qui nous manque, destiné au marchand d'armes Gordon Wendham à Undercity. Portez l'ordre à notre Maître des chauve-souris, Karos Razok, et voyez avec lui comment vous rendre à Undercity.", progress = "Vous paraissez être en service officiel...", completion = "Ah, une commande de fournitures ! Vous voulez sans doute apporter cela à Undercity ? Et rapidement, pour que le Sépulcre ne se retrouve pas à cours de stock ?", rewards = "Vous recevrez :\n\n"},
[6322] = {title = "Michael Garret", objective = "Apporter la Caisse de Gordon à Michael Garret.", description = "J'ai placé l’approvisionnement pour le Sépulcre dans cette caisse. Si vous avez déjà visité le Sépulcre et parlé avec leur Maître des chauve-souris, vous pouvez chevaucher une chauve-souris pour y retourner.\n\nAllez voir le Maître des chauve-souris d'Undercity, Michel Garret. Il pourra vous fournir une monture pour aller au Sépulcre.", progress = "Si vous devez faire un long voyage, utiliser une chauve-souris reste la meilleure solution.", completion = "Cette caisse doit être apportée au Sépulcre, dans la forêt des Pins argentés ? C'est facile, nos chauve-souris y vont tous les jours.", rewards = "Vous recevrez :\n\n"},
[6323] = {title = "Voyage vers Undercity", objective = "Acheter un voyage en chauve-souris pour Undercity, auprès du Maître des chauves-souris, Karos Razok, puis apporter l’Ordre de Podrig à Gordon Wendham, à Undercity.", description = "Une de mes chauves-souris peut vous conduire à Undercity, pour un prix modique. Revenez me voir quand vous serez <prêt/prête> pour que nous arrangions votre transport.\n\nVous trouverez Gordon Wendham dans le Quartier marchand d'Undercity. C'est dans ce quartier que ma chauve-souris se posera.", progress = "Je garde toujours mes armes en bon état. Elles sont entretenues et prêtes à servir.", completion = "Une commande du Sépulcre ? Très bien. C'est un honneur de servir ceux qui servent la Dame noire.", rewards = "Vous recevrez :\n\n"},
[6324] = {title = "Retour vers Podrig", objective = "Acheter un voyage en chauve-souris pour le Sépulcre, auprès du Maître des chauves-souris Michael Garret, puis apporter la Caisse de Gordon au Garde noir Podrig, au Sépulcre.", description = "Le Maître des chauve-souris du Sépulcre est Karos Razok. Si vous l'avez déjà rencontré, je peux vous donner une chauve-souris pour voler jusqu'à lui.\n\nNos chauves-souris savent toutes voler vers Undercity, mais pour aller plus loin, leurs cavaliers doivent avoir d'abord visité la destination et en parler au Maître des chauves-souris.\n\nVous avez déjà rencontré Karos au Sépulcre, donc vous pouvez voler jusque-là. Quand vous serez sur le point de partir, revenez me voir.", progress = "<nom>, de retour. Avez-vous nos fournitures provenant d'Undercity ?", completion = "Beau travail, &lt;nom&gt;. Ces armes vont permettre à nos Gardes noirs de ne pas être pris au dépourvu.\n\nVous avez rendu un fier service à la Dame noire.", rewards = "Vous recevrez :\n\n"},
[6341] = {title = "Le don de Teldrassil", objective = "Apporter la Collection de Nessa à Vesprystus.", description = "Les pêcheurs du village de Rut'theran savent très bien y faire ; de plus, le poisson, là-bas, y est extrêmement abondant et on y pêche des spécimens d’une taille étonnante. Je voudrais juste comparer la manne de cet endroit avec celle du continent.\n\nJe possède une importante collection d’os et d’écailles de poisson que je souhaiterais faire porter à l'un de mes collègues, à Sombrivage. Il s’appelle Laird, il vend des poissons au village d’Auberdine.\n\nApportez ma collection à notre Maître des hippogryphes, Vesprystus, et discutez avec lui des conditions d’un voyage vers Auberdine.", progress = "Comment puis-je vous aider ? Avez-vous besoin d'un transport ?", completion = "Ah, vous voulez aller à Auberdine ? Très bien...", rewards = "Vous recevrez :\n\n"},
[6342] = {title = "Vol vers Auberdine", objective = "Prenez un hippogryphe vers Auberdine chez le maître des hippogryphes Vesprystus, puis apportez la Collection de Nessa à Laird.", description = "À partir de Rut'theran, il existe deux moyens pour se rendre à Auberdine : par le bac ou par hippogryphe. Les deux sont rapides et sûrs, mais si vous n’avez pas encore voyagé vers Auberdine à dos d’hippogryphe, je vous suggère d’essayer.\n\nLorsqu'il y a un Maîtres des hippogryphes dans une ville, il est très profitable de lui parler. Une fois que vous avez parlé à un Maître, vous pouvez revenir dans la ville où il se trouve, à partir des autres villes.\n\nVoici la Collection de Nessa. Revenez me voir quand vous voudrez vous envoler pour Auberdine, et livrer la Collection de Nessa à Laird.", progress = "Venez-vous de Teldrassil ? Dites-moi, comment est la pêche là-bas ?", completion = "Un paquet provenant de Nessa ? Merci, &lt;nom&gt; ! Elle m'avait dit qu'elle m'enverrait un spécimen de cette espèce de poisson capturée près du village Rut'theran. Elle pense qu'elle est différente de celle attrapée ici...\n\nOh ! Sa mâchoire est effectivement deux fois plus grande et ses écailles aussi grosses qu'un poing ! Incroyable !", rewards = "Vous recevrez :\n\n"},
[6343] = {title = "Retourner à Nessa", objective = "Réponse de Laird à Nessa Shadowsong.", description = "Je dois faire parvenir une réponse à Nessa. Elle sera très intéressée de savoir à quel point les poissons ici sont différents de ceux que l’on trouve le long de la côte de Teldrassil. Nous ne pouvons que spéculer sur les raisons de ces différences, mais je pense que la présence de l’Arbre Monde affecte la faune et la flore autour de lui !\n\nS’il vous plaît, faites parvenir cette réponse à Nessa. Si vous souhaitez prendre un hippogryphe pour aller à Rut'theran, adressez-vous au Maître des hippogryphes, Caylais Moonfeather. Si vous souhaitez plutôt prendre le navire, il y en un qui part régulièrement à partir du quai, au nord-ouest.", progress = "<nom>, vous revenez d'Auberdine ? Avez-vous parlé avec Laird ?", completion = "C'est très intéressant. Les poissons sont gros ici, mais je ne pensais pas que les différences étaient telles entre les prises d'ici et celles du continent. Il doit y avoir une raison à cela...\n\nBien, merci &lt;nom&gt;. Je discuterai avec les villageois des nouvelles que vous m'avez apportées. Peut-être qu'un jour nous trouverons les raisons de cette bizarrerie. Mais en attendant, nous devons en profiter !", rewards = "Vous recevrez :\n\n"},
[6344] = {title = "Nessa Shadowsong", objective = "Parler à Nessa Shadowsong.", description = "Une de mes amies, Nessa Shadowsong, est une marchande de poissons, dans le village de Rut'theran. Elle a besoin qu'un colis soit apporté à Sombrivage, et cherche quelqu'un qui serait d'accord pour l'aider.\n\nSi cela vous intéresse et que vous souhaitez rencontrer Nessa, il vous faut prendre le portail qui relie Darnassus et Rut'theran. Vous le trouverez à l'ouest des jardins du temple.", progress = nil, completion = "Oui, j'ai besoin d'un porteur de courrier qui puisse apporter un paquet à Sombrivage. Voulez-vous m'aider ?", rewards = "Vous recevrez :\n\n"},
[6361] = {title = "Un Tas de peaux", objective = "Apporter le Tas de peaux au Maître des Cavaliers célestes, Devrak, à la Croisée.", description = "J'ai un tas de peaux d'animaux des Tarides et je dois les apporter à Thunder Bluff. Là-bas, un collègue, Ahanu, va les utiliser pour fabriquer des produits en cuir.\n\nPourriez-vous lui apporter ces peaux ?\n\nLa façon la plus rapide de rejoindre Thunder Bluff est de chevaucher un Cavalier céleste. Apportez ces peaux à Devrak, notre Maître des Cavaliers célestes, à la Croisée, et dites-lui qu'il faut les transporter à Thunder Bluff.", progress = "Êtes-vous ici pour un cavalier céleste ? Vous avez quelque chose à transporter ?", completion = "Si vous devez apporter ces peaux à Thunder Bluff, alors vous vous adressez au bon orc !", rewards = "Vous recevrez :\n\n"},
[6362] = {title = "Voyage vers Thunder Bluff", objective = "Acheter un voyage pour Thunder Bluff, auprès du Maître des Cavaliers célestes, Devrak, puis apporter le Tas de peaux à Ahanu, à Thunder Bluff.", description = "Contre un modeste paiement, je vous donnerai un Cavalier céleste pour Thunder Bluff. Il n’existe pas de moyen plus rapide pour se rendre sur place !\n\nSi cela vous convient, revenez me voir quand vous souhaiterez partir.\n\nSi vous voulez apporter ces peaux à Ahanu, vous le trouverez à l’Armurerie de Hewa, à la base de la tour des Cavaliers célestes, dans Thunder Bluff. C’est exactement là que vous atterrirez !", progress = "La poussière sur vous épaules semble provenir des Tarides. Avez-vous discuté avec mon ami Jahan ?", completion = "Ah, un tas de peaux ! Je vais les travailler immédiatement !\n\nMerci, frère. Vous m'avez rendu un grand service. Tenez, voici quelques pièces pour votre peine.", rewards = "Vous recevrez :\n\n"},
[6363] = {title = "Tal le Maître des Cavaliers célestes", objective = "Apporter les Marchandises en cuir d'Ahanu à Tal, à Thunder Bluff.", description = "J’ai préparé des marchandises en cuir pour Jahan, destinées à être vendues à la Croisée. Voulez-vous les lui apporter ?\n\nSi vous avez déjà été à la Croisée et si vous avez parlé au Maître des Cavaliers célestes, vous pouvez monter l’un de nos Cavaliers célestes de Thunder Bluff pour retourner le voir.\n\nApportez les marchandises en cuir à Tal, le Maître des Cavaliers célestes de Thunder Bluff, et parlez-lui d'un voyage vers la Croisée.", progress = "Bienvenue, <classe>. Que puis-je faire pour vous ?", completion = "Vous devez apporter cela à la Croisée, hein ? Il n'y a pas de problème. Si ce n'est pas la première fois que vous y allez et que vous connaissez Devrak, alors vous pouvez lui rapporter un de mes Cavaliers célestes.", rewards = "Vous recevrez :\n\n"},
[6364] = {title = "Retourner vers Jahan", objective = "Acheter un voyage pour la Croisée auprès du Maître des Cavaliers célestes Tal, puis apporter les Marchandises en cuir d’Ahanu à Jahan Hawkwing.", description = "Pour vous rendre dans une ville, par la voie des airs, vous devez déjà avoir visité cette ville et avoir parlé avec le Maître des Cavaliers célestes local. Vous avez déjà été à la Croisée et parlé avec le Maître des Cavaliers célestes, Devrak ; par conséquent, vous pouvez prendre un Cavalier céleste, ici, pour vous y rendre, moyennant un modeste paiement.\n\nRevenez me voir, lorsque vous souhaiterez partir. Une fois à la Croisée, vous pourrez livrer les Marchandises en cuir à Jahan Hawkwing.", progress = "<nom>, vous revenez de Thunder Bluff ? Avez-vous livré les peaux à Ahanu ?", completion = "Ahanu m'envoie ses produits finis ? Très bien. Il y a de nombreux chasseurs et de nombreux aventuriers à la Croisée actuellement, et les affaires marchent bien. Je suis persuadé que je vendrai très vite ces marchandises.\n\nMerci pour tout, &lt;nom&gt;. Je vous dois une faveur.", rewards = "Vous recevrez :\n\n"},
[6365] = {title = "Viandes vers Orgrimmar", objective = "Apporter la Chair de Zargh à Devrak, à la Croisée.", description = "J'ai quelques morceaux de viande de choix que je veux envoyer à une amie. Son nom est Gryshka, elle est aubergiste à Orgrimmar. Voulez-vous livrer cette viande pour moi ?\n\nLa façon la plus rapide d'aller à Orgrimmar, c'est le Cavalier céleste. Portez la viande à Devrak, le Maître des Cavaliers célestes de la Croisée, et voyez avec lui comment la transporter à Orgrimmar.", progress = "Vous avez besoin d'aller quelque part rapidement ? Alors vous parlez au bon <race> !", completion = "Vous devez livrer cette viande à Orgrimmar ? Aucun problème. Pour un prix modeste, mon Cavalier céleste peut vous transporter là-bas.", rewards = "Vous recevrez :\n\n"},
[6381] = {title = "Nouvelle vie", objective = "Planter 10 Graines de Gaea sur les Monticules de Gaea, puis parler à Tammra, à la Retraite de Roche-Soleil.", description = "Comme vous avez pu le constater, <classe>, le cycle de la vie demeure une instance puissante, même quand la terre souffre. Vous devez aller planter ces graines au coeur de la destruction, à l'ouest, dans le Val calciné. Sur votre chemin, prenez garde aux harpies et aux élémentaires de feu enragés, fléaux vivants qui sévissent sur cette terre scarifiée.\n\n<nom>, prenez ces Graines de Gaea enchantées, et allez les planter dans des monticules de sol fertile. Le cycle de la vie doit se perpétuer !", progress = "Ces graines que vous plantez sont puissantes, résistantes à la corruption, et elles font un solide point de départ pour le renouveau de la vie. Elles grandiront, et grandiront, prévenant tout d'abord la corruption, tout en soignant la terre écorchée, et un jour, elles feront à nouveau des Serres-Rocheuses une forêt luxuriante.\n\nAvez-vous planté toutes les Graines de Gaea ?", completion = "Que voilà une grande victoire pour nos gens. En temps et en heure, d'autres problèmes passeront d'eux-mêmes : la KapitalRisk rangera ses haches et ses outils, les esprits du feu enragés se calmeront, et les harpies seront chassées de cette terre.\n\nAlors seulement, &lt;nom&gt;, les Serres-Rocheuses connaîtront vraiment la paix.\n\nVous avez bien agi, &lt;classe&gt; ; prenez un de ces objets en guise de remerciement.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de ChercheventGants du Pic de sable\n\nVous recevrez également :\n\n"},
[6382] = {title = "La Chasse d'Ashenvale", objective = "Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", description = "Votre force n'a de cesse de m’impressionner, <classe>. Votre volonté de chasser est telle que j’ai toute confiance en vous pour passer à des défis et des épreuves plus ardus.\n\nLes forêts d’Ashenvale couvrent de vastes étendues sauvages sur lesquelles la Horde cherche à étendre sa domination politique et spirituelle. Si vous voulez vraiment faire vos preuves, cherchez conseil auprès de Senani Thunderheart, au Poste de Bois-brisé. L’Avant-poste se trouve au nord du chemin qui mène hors des Tarides.", progress = nil, completion = "Bienvenue à la nouvelle frontière, &lt;nom&gt;. Ashenvale est une terre d'opportunités, où de jeunes gens comme vous peuvent avoir de nombreuses chances de prouver leur vaillance. Faites le tour de l'Avant-poste et n'oubliez pas de voyager jusqu'à la grève de Zoram, étant donné que la Horde a aussi un autre avant-poste, là-bas.\n\nVotre présence ici me dit que vous êtes venu pour en apprendre plus sur l'art de la chasse. Écoutez attentivement, &lt;classe&gt;, et je partagerai volontiers avec vous le savoir qui vous manque.", rewards = "Vous recevrez :\n\n"},
[6383] = {title = "La Chasse d'Ashenvale", objective = "Pour clore la Chasse d’Ashenvale, vous devrez affronter trois créatures légendaires. Vous allez devoir les rechercher et vous mesurer à leur malice et leur force. En accomplissant cela, vous apprendrez des choses sur vous. Ces créatures sont : l'ours Ursangous, le sabre-de-nuit Shadumbra et l'hippogryphe Serres-tranchantes.\n\nLes créatures de la Chasse d'Ashenvale sont puissantes, et vous aurez peut-être besoin d'aide pour les vaincre. Si vous les battez, apportez-en-moi la preuve.", description = nil, progress = nil, completion = nil, rewards = nil},
[6384] = {title = "Trajet vers Orgrimmar", objective = "Acheter un voyage pour Orgrimmar, auprès du Maître des Cavaliers célestes, Devrak, puis apporter la Chair de Zargh à Gryshka, à Orgrimmar.", description = "Pour quelques menues pièces, je vous fournirai un Cavalier céleste qui vous portera à travers les nuages, jusqu’à Orgrimmar. Quand vous y serez, vous pourrez livrer la chair de Zargh à Gryshka. Son auberge se trouve dans la Vallée de la force, non loin de la Tour des cieux, où mon Cavalier céleste vous déposera.\n\nRevenez me voir quand vous souhaiterez faire le voyage.", progress = "Quelque chose sent bon ! Avez-vous de la viande crue sur vous ?", completion = "Oh, merveilleux ! Quels morceaux superbes ! Ils viennent de chez Zargh, n'est-ce pas ? Cet &lt;race&gt; sait comment faire plaisir à une dame...\n\nJe suis impatient de les préparer. Mais pas trop ! La viande doit être servie saignante, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[6385] = {title = "Doras le Maître des Cavaliers célestes", objective = "Apporter la Lettre de Gryshka à Doras, à Orgrimmar.", description = "J’ai écrit une lettre pour remercier Zargh. Voudriez-vous la livrer pour moi ? Si vous avez déjà visité la Croisée et que vous y avez parlé avec le Maître des Cavaliers célestes, vous pouvez monter un Cavalier céleste pour vous y rendre.\n\nPortez ma lettre à Doras, le Maître des Cavaliers célestes d’Orgrimmar, et entretenez-le d’un voyage vers la Croisée.", progress = "Avez-vous besoin d'un de mes Cavaliers Célestes ?", completion = "Vous devez apporter ceci à la Croisée des Tarides ? Oui, je peux vous y amener...", rewards = "Vous recevrez :\n\n"},
[6386] = {title = "Retour à la Croisée", objective = "Acheter un voyage pour la Croisée auprès du Maître des Cavalier célestes, Doras, puis apporter la Lettre de Gryshka à Zargh, à la Croisée.", description = "Mes Cavaliers célestes sont entraînés pour se rendre à maints endroits différents, à la seule condition que vous ayez déjà visité l’endroit de destination, au moins une fois, et que vous ayez parlé avec le Maître des Cavaliers célestes local.\n\nVous avez déjà visité la Croisée et parlé avec son Maître des Cavaliers, Devrak ; vous pouvez donc y voler directement, à partir d’ici. Un fois à la Croisée, vous donnerez la lettre de Gryshka à Zargh.\n\nRevenez me voir dès que vous voudrez partir.", progress = "Revenez-vous d'Orgrimmar ? Est-ce que Gyshka a aimé la viande que je lui ai envoyée ?", completion = "Ah ! Je pensais bien qu'elle allait l'aimer ! Rien ne rend plus rouges les joues d'une dame qu'un steak juteux et épais !\n\nMerci, &lt;nom&gt;. Vous m'avez rendu un grand service. Voici un peu d'argent pour votre peine, et si je vous invite à mon mariage ne soyez pas surpris !", rewards = "Vous recevrez :\n\n"},
[6387] = {title = "L'honneur des étudiants", objective = "Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar.", description = "Je vois maints jeunes nains à ma porte, avides d’apprendre l’art du minage. Et si un mineur a besoin de quelque chose, c’est bien d’une pioche !\n\nJ’ai une liste d’étudiants qui ont travaillé dur pendant leur apprentissage, et ont gagné une pioche d'honneur en échange de leurs efforts. Apportez ma liste à Golnir Bouldertoe, à Ironforge. Il aura préparé les pioches.\n\nLe moyen le plus rapide pour se rendre sur place est d’utiliser un gryphon. Apportez d’abord la liste à notre Maître des gryphons, Thorgrum Borrelson, et discutez avec lui de la possibilité d’un voyage vers Ironforge.", progress = "Est-ce que vous avez fini ce que vous aviez à faire à Thelsamar ? Voulez-vous partir maintenant vers une autre ville ?", completion = "Vous devez porter cela à Ironforge, hein ? Pour une somme modique, je peux vous mettre sur le dos d'un de mes gryphons et il vous y amènera. Cela vous convient-il ?", rewards = "Vous recevrez :\n\n"},
[6388] = {title = "Gryth Thurden", objective = "Apportez les Pioches d'honneur à Gryth Thurden à Ironforge.", description = "Voici les pioches d'honneur pour les étudiants de Brock. Si vous avez déjà visité Thelsamar, vous devriez prendre un gryphon pour y retourner !\n\nPrenez les pioches et apportez-les à notre Maître des gryphons, Gryth Thurden ; parlez-lui du voyage vers Thelsamar.", progress = "J'ai l'impression que vous voulez aller quelque part. Avez-vous besoin d'un de mes gryphons ?", completion = "Vous devez apporter cela à Thelsamar, hein ? Ce ne sera pas un problème. Si vous y êtes déjà allé et que vous avez rencontré Thorgrum Borrelson, alors vous pouvez utiliser un de mes gryphons pour y retourner.", rewards = "Vous recevrez :\n\n"},
[6389] = {title = "Une Plaie sur la Croisade", objective = "Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest, avec le Tonneau de Termites des Maleterres.", description = "Vous cherchez autour de la Scierie, pour voir si vous ne pourriez pas trouver quelque chose permettant d’ouvrir le tonneau. Vous apercevez un Pied-de-biche qui semble pouvoir faire l’affaire.\n\nVous vous préparez, tout en priant pour que les Termites vous laissent le temps de sortir de la Scierie, indemne.", progress = "L'avez-vous fait, <nom> ? Avez-vous lâché les Termites ? La Lumière nous vienne en aide si la Croisade écarlate est capable de tenir la scierie et Hearthglen. Ils n'auront aucun des deux. Ils basent leur propagande sur les morts de la dernière guerre. Il faut les éliminer comme des rats enragés.", completion = "Ah ! Merci, &lt;nom&gt; ! Vous l'avez fait ! L'esprit de mon père est désormais en paix.\n\nMerci encore. S'il y a quoi que ce soit que je peux faire pour vous, je vous en prie, n'hésitez pas.", rewards = "Vous recevrez :\n\n"},
[6390] = {title = "Une Plaie sur la Croisade", objective = "Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres.", description = "Vous cherchez autour de la Scierie, pour voir si vous ne pourriez pas trouver quelque chose permettant d’ouvrir le tonneau. Vous apercevez un Pied-de-biche qui semble pouvoir faire l’affaire.\n\nVous vous préparez, tout en priant pour que les Termites vous laissent le temps de sortir de la Scierie, indemne.", progress = "L'avez-vous fait, <nom> ? Avez-vous lâché les termites dans la scierie ?\n\nIl était déjà assez éprouvant que les membres de ma famille perdent leur travail et leur vie, mais voir l'endroit où j'ai grandi tomber aux mains de ces prétendus dévots... Beurk !", completion = "Merci, &lt;nom&gt;. Tenez, prenez cette pièce. Ce n'est pas grand-chose, mais réjouissez-vous d'avoir aidé à annihiler les efforts de la Croisade écarlate !", rewards = "Vous recevrez :\n\n"},
[6391] = {title = "Voyage vers Ironforge", objective = "Acheter un billet de gryphon pour Ironforge, auprès du Maître des gryphons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Bouldertoe, à Ironforge.", description = "Pour quelques menues pièces de monnaie, l'un de mes gryphons vous conduira à Ironforge. Là, vous donnerez la liste de Brock à Golnir Bouldertoe. Vous le trouverez à la Guilde des mineurs de la montagne profonde. C'est dans le quartier de la Grande Forge d'Ironforge, mon gryphon vous déposera en plein dedans !\n\nRevenez me voir quand vous serez sur le point de partir.", progress = "Que puis-je faire pour vous, Monseigneur ?", completion = "Ah, la dernière liste des meilleurs élèves de Brock. J'ai tout un tas de pioches d'honneur à offrir. Va juste falloir que je grave le nom des élèves...", rewards = "Vous recevrez :\n\n"},
[6392] = {title = "Retourner vers Brock", objective = "Acheter un billet de gryphon pour Thelsamar, auprès du Maître des gyphons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Stoneseeker, à Thelsamar.", description = "Vous pouvez vous payer un vol de gryphon jusqu'à Thelsamar pour pas grand-chose... à condition d'y être déjà <allé/allée>. Les gryphons ne volent que vers des lieux que vous avez déjà visités, alors demandez bien à chaque Maître des gryphons si vous pourrez voler vers lui plus tard.\n\nVous avez déjà rencontré Thorgrum, le Maître des gryphons de Thelsamar, alors vous pouvez retourner le voir. Et une fois dans Thelsamar, vous pouvez livrer les pioches à Brock Stoneseeker.\n\nVenez me voir quand vous serez sur le point de partir.", progress = "Ha, <nom>. Revenez-vous d'Ironforge ?", completion = "Vous avez rapporté les piolets. Bien ! Je vais les apporter à mes étudiants. Je suis sûr qu'ils sont impatients de les utiliser sur le minerai de Loch Modan.\n\nMerci de votre aide, &lt;nom&gt;. Je suis votre débiteur, j'espère que cet argent permettra de couvrir vos frais.", rewards = "Vous recevrez :\n\n"},
[6393] = {title = "Guerre élémentaire", objective = "Apporter 10 Incendrites à Tsunaman, dans la Retraite de Roche-Soleil.", description = "Le Tribunal des marées m'a envoyé pour faire la guerre aux élémentaires de feu des Serres-Rocheuses. Neptulon le Chasseur des vagues, Seigneur de tous les élémentaires d'eau, a particulièrement intérêt à voir éteints nos ardents cousins.\n\n<nom>, vous pouvez m'aider à gagner les faveurs du Tribunal en détruisant les élémentaires de feu dans le Val calciné. Une fois détruits, les élémentaires de feu rejettent des Incendrites. Rapportez-les-moi pour toucher votre récompense.", progress = "Le Tribunal des marées s'impatiente. Ils cherchent à en finir avec cette guerre qui fait rage à travers toutes les dimensions depuis une éternité. Mes frères sont impatients d'avoir le récit de la glorieuse victoire contre les haïssables élémentaires de feu. Avez-vous les Incendrites que je vous ai demandées ?", completion = "Les esprits de l'eau en moi bouillonnent d'excitation. &lt;nom&gt;, je vais avoir l'insigne honneur de faire le rapport de votre victoire auprès du Tribunal des marées.", rewards = "Vous recevrez :\n\n"},
[6394] = {title = "La pioche de Thazz'ril", objective = "Apportez la Pioche de Thazz'rill au contremaître Thazz'rill.", description = "<nom>, vous êtes quelqu'un de fiable. Puis-je compter sur vous pour une autre tâche ?\n\nIl y a quelque temps, je prospectais une grotte, dans le nord, à la recherche de minéraux, et j’y ai perdu ma pioche favorite. Quand j’y suis retourné plus tard pour tenter de la retrouver, j’ai vu que la grotte était pleine de bêtes hostiles ! Pourriez-vous aller dans cette grotte, le convent de la Lame ardente, <nom>, et récupérer ma pioche ?\n\nJe l’ai oubliée dans la salle des chutes d’eau. Ma pioche est enchantée et vous la verrez dans l’obscurité, elle ne devrait pas être difficile à trouver... le problème c’est plutôt ce qui est chargé de la garder !", progress = "Avez-vous pénétré dans le convent de la Lame ardente, <nom> ? Avez-vous trouvé ma pioche ?", completion = "Vous l'avez, bien ! Merci beaucoup, &lt;nom&gt;. C'est ma pioche préférée ! Maintenant si mes péons arrivent enfin à déboiser la région, peut-être trouverons-nous une bonne grotte à miner !", rewards = "Vous recevrez :\n\n"},
[6395] = {title = "La dernière volonté de Marla", objective = "Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth.", description = "Avant la peste, mon amie Marla Fipps et son mari Samuel vivaient heureux. Mais quand la peste est survenue, Samuel a succombé et a rejoint les rangs du Fléau.\n\nMarla n'a échappé à l’épidémie que pour mourir des mains de son mari, privé de raison. Pourtant, son amour était si fort que sa dernière volonté fut que son bien-aimé Samuel soit enterré avec elle.\n\nSamuel Fipps erre dans un camp en ruine le long de la route au nord-est du Glas. Tuez-le et accomplissez la volonté de Marla : enterrez-le dans sa tombe, dans la première rangée de notre cimetière.", progress = nil, completion = "Vous avez fait du beau travail aujourd'hui, &lt;nom&gt;. Avec un peu de chance, Marla et Samuel ont trouvé le repos là où ils se trouvent maintenant. Mais notre combat contre le Fléau continue.", rewards = "Vous recevrez :\n\n"},
[6401] = {title = "Kaya est en vie", objective = "Apprendre la bonne nouvelle à Tammra Windfield, dans la Retraite de Roche-Soleil.", description = "Allez apporter cette bonne nouvelle à Tammra Windfield, la tante de Kaya, qui se trouve à la Retraite de Roche-Soleil ! Kaya est vivante ! Nous la croyions perdue après l'attaque de notre village. Suivez la route de l'ouest pour arriver à la Retraite de Roche-Soleil.", progress = nil, completion = "Mon dieu, ma nièce Kaya est en vie ! C'est vraiment une bonne nouvelle. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6402] = {title = "Le rendez-vous à Stormwind", objective = "Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée.", description = "Vous devez rencontrer Windsor aux portes de Stormwind.\n\nCe que Windsor est sur le point de dévoiler va ébranler les fondations mêmes du royaume !\n\nNe vous y aventurez pas sans aide, <nom>. Vous devez réunir une armée ! Rassemblez vos compatriotes. Aux armes !", progress = nil, completion = "Avant de commencer, je vous demande de rassembler une armée. Nous affrontons un dragon tout de même !", rewards = "Vous recevrez :\n\n"},
[6403] = {title = "La grande mascarade", objective = "Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !", description = "Ce fut une sacrée aventure. J'ai vraiment une dette envers vous. Peut-être, quand tout sera dit et accompli...\n\nComme vous l'avez sans doute vérifié à ce jour, dame Prestor est Onyxia, rejeton de l'Aile de mort et jumelle de Nefarian, le tyran du Pic.\n\nPendant trop longtemps elle a captivé notre royaume de son regard hypnotique. Même le généralissime est prisonnier de sa duperie – une véritable marionnette. Cela prendra fin aujourd'hui... Le charme sera rompu.\n\nNe craignez rien, ensemble, nous serons victorieux !\n\nVous êtes d'attaque ?", progress = "J'étais... j'étais impuissant.", completion = "&lt;Bolvar tient le médaillon brisé.&gt;\n\nLa magie qui s'y trouve doit être éveillée. L'oeil du dragon doit être mis en phase.\n\nLe sacrifice de Windsor a libéré notre royaume, mais la menace d'Onyxia et des siens se dessine toujours.\n\nCe médaillon est ce qui retient captifs mon esprit et mon corps. C'est également ce qui me donne accès à l'esprit d'Onyxia, à ses secrets. Les visions sont plus floues à présent, mais il est des choses dont je me souviens tout de même.", rewards = "Vous recevrez :\n\n"},
[6421] = {title = "Le ravin des Eboulis", objective = "Explorer la grotte du ravin des Eboulis, et apporter 10 Cristaux de résonite à Mor'rogal, dans la Retraite de Roche-Soleil.", description = "Quelque chose ne va pas dans les Serres-Rocheuses. Vous sentez cette tension dans l'air, <nom> ?\n\nAu sud-est d'ici, dans le Ravin des éboulis, se trouve une profonde caverne. Les kobolds sont là-bas et passent tout leur temps à extraire un cristal rare, la résonite. J'ai besoin de vous pour m’en rapporter quelques échantillons afin de comprendre ce qui se passe dans cette caverne. J'ai aussi besoin de connaître sa profondeur.\n\nAllez, jeune <classe>, il est impératif que je sache quel mal se cache sous ces montagnes.", progress = "Qu'avez-vous découvert au ravin des Eboulis ? Je me rappelle de certaines légendes parlant de résonite... je n'arrive pas à m'en souvenir. Peut-être qu'en découvrant ce qu'il y a au fond de cette grotte, nous devinerons leurs sournoises intentions.", completion = "Ah... Oui ! C'est ça : les cristaux de résonite contiennent des traces de magie terrestre. Les kobolds ont dû creuser très profond pour tomber sur un Terrestre.\n\nLa légende veut que les Terrestres aient été créés par les Titans. Ils s'en sont servis pour créer la terre sur laquelle nous marchons aujourd'hui. C'est une menace à prendre définitivement au sérieux.\n\n&lt;Mor'rogal secoue la tête.&gt;\n\nJe peux peut-être enchanter ces échantillons de minerai pour les utiliser contre ce complot kobold.", rewards = "Vous recevrez :\n\n"},
[6441] = {title = "Cornes de satyre", objective = "Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé.", description = "Salut ! J'ai voyagé dans tout Ashenvale, en me dirigeant vers Ratchet et j'ai décidé de faire un arrêt ici à Bois-brisé. Je suis toujours à la recherche d'une opportunité et on dirait bien que les cornes de satyre sont très demandées ces jours-ci à Ratchet.\n\nJe me suis renseignée, il semble que les satyres du défilé de la Nuit, de Satyrnaar et de Xavian ont tous le type de cornes que je cherche. Je ne suis pas de taille face à ces satyres... mais vous en revanche, on dirait bien que oui!\n\nJe vais vous dire, ramassez ces cornes pour moi et vous ne regretterez pas le temps que vous y aurez passé.", progress = "J'espère que vous allez récupérer rapidement ces cornes, <nom>. Je repars à Ratchet bientôt !", completion = "C'est parfait, &lt;nom&gt; ! Merci de votre aide !\n\nOh, et ceci est pour le temps que vous m'avez consacré...", rewards = "Vous recevrez :\n\n"},
[6442] = {title = "Des nagas sur la grève de Zoram", objective = "Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram.", description = "Le mal se cache le long de cette côte, <race>.\n\nC'est ce qui reste de la ville condamnée de Zoram, détruite il y a longtemps et engloutie sous les eaux. Perdue et presque oubliée.\n\nAujourd’hui les nagas y sont retournés, pour une raison que nous ne connaissons pas. Mais la raison importe peu, nous devons défendre la terre que nous avons travaillée si durement.\n\nRevenez me voir avec 20 de leurs têtes ! Rejetez les nagas dans les profondeurs !", progress = "Les nagas sont de plus en plus nombreux, <nom>. Accomplissez la tâche que je vous ai donnée s'il vous plaît.", completion = "Nous pourrions utiliser plus de gens comme vous ici, &lt;nom&gt;. Merci de votre aide.", rewards = "Vous recevrez :\n\n"},
[6461] = {title = "Suceurs de sang", objective = "Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes.", description = "Nous, les trolls de Malaka'Jin, nous avons prospéré sur cette terre. Les Serres-Rocheuses nous permettent de chasser pour vivre.\n\nDernièrement, nous avons eu la visite de pique-assiette... À la nuit, les araignées des montagnes ont fait un raid sur nos camps pour voler le fruit de notre chasse.\n\nSi vous nous aidez à éliminer ces bêtes horribles, les trolls de Malaka'Jin vous en seront reconnaissants à jamais. Les araignées vivent partout dans les Serres-Rocheuses. Dirigez-vous simplement vers le nord et vous pourrez le constater.", progress = nil, completion = "Excellent ! Bonnes nouvelles ! Peut-être aurons-nous moins d'invités indésirables ce soir.\n\nMerci beaucoup, &lt;nom&gt;. Nous vous sommes éternellement redevables.", rewards = "Vous recevrez :\n\n"},
[6462] = {title = "Charme troll", objective = "Apporter 8 Charmes trolls à Mitsuwa, à l’Avant-poste de Zoram'gar.", description = "Mes parents voyageaient ici avec plusieurs charmes trolls sacrés, mais les furbolgs Crins-de-Chardon les ont attaqués et tués avant qu'ils n'aient atteint Zoram'gar ! Ces misérables furbolgs !\n\nMes frères et sœurs qui ont été tués me manquent, mais nous serons de nouveau réunis dans l'au-delà. Cependant, ces charmes trolls ont beaucoup de valeur dans ce monde. C'est une hérésie qu'ils soient aux mains des furbolgs !\n\n<nom>, vous devez récupérer ces charmes ! Ils se trouvent dans des coffres dans le repaire des Crins-de-Chardon, une caverne au bout du village des Crins-de-Chardon, au nord d'Astranaar.", progress = "Avez-vous trouvé les charmes, <nom> ? Tant que ces furbolgs les détiennent, mon sang bouillonne de rage !", completion = "Vous les avez trouvés ! Merci ! Merci, &lt;nom&gt; ! Vous ne pouvez pas savoir quel service vous m'avez rendu.\n\nUn troll sans son charme est comme un orc sans cicatrices de combat...\n\nBon à rien.", rewards = "Vous recevrez :\n\n"},
[6481] = {title = "Un Terrestre se lève", objective = "Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté.", description = "Vous avez découvert une sombre menace pour cette terre, <classe>. La gangue de résonite que vous avez trouvée dans cette caverne abrite un Terrestre dormant du nom de Goggeroc.\n\nGrâce à mes pouvoirs chamaniques, j'ai modifié le mélange des cristaux de résonite que vous avez ramassés. Prenez ce cristal de résonite enchanté et servez-vous-en pour ouvrir la gangue de résonite qui abrite le Terrestre.\n\nQuand il sera réveillé, Goggeroc sera affaibli... Abattez-le, <nom> !", progress = nil, completion = "Vous apportez de grandes nouvelles, &lt;classe&gt; ! Je frémis à l’idée de ce qu’un terrestre aurait pu faire subir à Kalimdor.\n\nTuer Goggeroc, voilà un acte digne d’un héros ! Vous avez bien fait, les Serres-Rocheuses et Kalimdor vous sont reconnaissants, noble &lt;classe&gt;.\n\nAcceptez ceci en récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards de Barbe-huanteGarde-poignets en crinière de loup\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6482] = {title = "Liberté pour Ruul", objective = "Escorter Ruul, puis parler à Yama Snowhoof, au Poste de Bois-brisé.", description = "Hein ? Qui êtes-vous ?\n\n<nom> ? Vous n’êtes pas un furbolg. Ils sont maudits ! Ils m’ont pris pour un ours et m’ont capturé, et maintenant ils m’affament et mes forces sont en train de m’abandonner...\n\nAidez-moi à m’échapper, puis allez parler à ma soeur, Yama, au poste de Bois-brisé, à l’est.\n\n<nom> ! Je dois m’échapper !", progress = nil, completion = "Vous avez trouvé mon frère ! Il avait été capturé par les Crins-de-Chardon ? C'est terrible, car bien que la plupart des furbolgs soient de nobles créatures, les Crins-de-Chardon, eux, sont corrompus.\n\nMerci d'avoir sauvé mon frère, &lt;nom&gt;. Je ne veux même pas imaginer ce qu'ils ont fait endurer à ce pauvre Ruul. Il va certainement dormir pendant longtemps après cette rude épreuve...", rewards = "Vous recevrez :\n\n"},
[6501] = {title = "L'Œil de dragon", objective = "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe.", description = "Tout ce que je peux vous offrir, c'est un fragment du médaillon brisé.\n\nVous devez encore trouver du sang de dragon pour fabriquer une nouvelle clé. Une fois que vous aurez sécurisé cette clé, vous devrez voyager vers la tourbière du Ver, dans le marécage d'Âprefange. C'est là que vous trouverez sa tanière, <nom>.\n\nOù trouver d'autres vols qui accepteraient de vous aider ? Malheureusement, je ne sais pas... On dit qu'il y en a. Certains peuvent même travailler et vivre parmi nous, déguisés pour faire croire qu'ils font partie de l'une des races humanoïdes. Je vous souhaite bonne chance.", progress = "Je sens une aura mauvaise émaner de vous, <nom>. Que transportez-vous qui puisse émettre une telle aura ?", completion = "J'aurais dû le savoir… un morceau du dragon noir, la Mère des couvées, Onyxia. C'est révoltant...", rewards = "Vous recevrez :\n\n"},
[6502] = {title = "Amulette drakefeu", objective = "Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock.", description = "Ceci est une partie du dragon, une écaille, enchantée et transformée. Intacte, elle aurait pu permettre l’accès au repaire de la bête. Brisée, elle est inutile.\n\nIl est possible de la réparer, mais cette opération nécessite le sang d’un Champion des dragons noirs. Il y en a un… Il est connu sous le nom de général Drakkisath, chef des armées draconides de Nefarian. Peut-être avez-vous entendu parler de lui ?\n\nRevenez avec son sang, <nom>, et j’enchanterai le fragment en un objet qui offrira l’accès au repaire d'Onyxia.", progress = "Le flux du temps ne s'arrête pas et ne ralentit pas, <nom>. Alors que ma vie est éternelle, la vôtre ne l'est pas. Ne gâchez pas le temps qui vous est imparti...", completion = "Cette amulette vous fournira l'accès que vous cherchiez. Le repaire d'Onyxia se trouve dans la baie d'Âprefange. Tant que vous tenez l'amulette ses gardiens ne peuvent pas vous empêcher d’entrer.\n\nLe Vol bleu vous souhaite bonne chance, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nAmulette drakefeu"},
[6503] = {title = "Les estafettes d'Ashenvale", objective = "Tuer 9 Estafettes d'Ashenvale, puis retourner voir Kuray'bin, à l’avant-poste de Bois-brisé.", description = "Nous avons reçu des rapports selon lesquels des estafettes ont quitté l’Avant-poste d'Aile-argent il n’y a pas longtemps. Elles seraient en train de rôder à proximité de nos territoires forestiers. Nous ne voulons pas qu'elles puissent collecter des renseignements concernant nos défenses !\n\nPartez et voyagez à travers les forêts, au sud de notre position et à l’est d'Aile-argent, l'avant-poste de l’Alliance. Trouvez et massacrez ces estafettes, puis revenez me voir.", progress = nil, completion = "Très bien, &lt;nom&gt;. Vos compétences de chasseur sont impressionnantes...\n\nAvec la perte de ces estafettes, l'Alliance aura moins de renseignements et donc devrait lancer moins d'attaques.", rewards = "Vous recevrez :\n\n"},
[6504] = {title = "Les pages perdues", objective = "Trouver les 12 pages manquantes du Manuel d'utilisation du Déchiqueteur, puis les rassembler pour constituer les Chapitres 1, 2, et 3. Ramener les pages à Gurda Ragescar près du poste de Bois-brisé.", description = "Je viens de trouver ce déchiqueteur à Ratchet. J’allais retourner au Camp de bûcherons Warsong, où mon travail m’attend. On m’a donné un manuel d’utilisation expliquant comment se servir d’un déchiqueteur, mais sur le chemin du retour, une grande rafale de vent l’a arraché de mes mains. Les pages se sont envolées, et il n’en est resté que la pauvre couverture.\n\nLes pages en question pourraient être un peu partout, maintenant… et je ne sais pas comment utiliser le déchiqueteur sans elles. Êtes-vous d’accord pour m’aider ?", progress = "J'espère que vous trouverez les pages rapidement, <nom> ! Il faut vraiment que je me remette au travail !", completion = "La lecture n'est pas mon fort... Mais maintenant je vais pouvoir me remettre au travail ! Merci, &lt;nom&gt; !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de manipulation du DéchiqueteurProtège-mains huilés\n\nVous recevrez également :\n\n"},
[6521] = {title = "Une alliance impie", objective = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Undercity.", description = "Malcin prétend qu’il se trouve à l’extérieur des Souilles de Tranchebauge. Cet ambassadeur doit être tué ; sa mission est un échec aux yeux du roi-liche.\n\nSa présence là-bas en dit long sur ce que nous avons découvert dans la région. La force et la sauvagerie de certains hurans ont crû de manière débridée, tandis qu’ils présentaient des signes indéniables de la Peste. C’est certainement le signe d’un arrangement qu’ils ont dû contracter avec quelqu’un.\n\nRetrouvez Malcin et exécutez-le, <nom>. Revenez me voir une fois que cela sera fait.", progress = "Avez-vous trouvé l'Ambassadeur, <nom> ? Est-il mort ?\n\nNous ne pouvons pas permettre au Fléau de prendre pied dans Kalimdor. Il y a assez de menaces comme cela à nos frontières sans devoir en plus les combattre sur deux fronts en même temps.\n\nLa seule chose positive qui ressort de ce que vous m'avez dit, c'est qu'il semble que la vieille bique n'a pas l'air d'avoir été corrompue. Elle doit savoir que le Fléau peut procurer de grands pouvoirs, mais que les Tarides ne lui auraient jamais vraiment appartenu si elle avait accepté le marché avec le Fléau.", completion = "Bien. Bien joué, &lt;classe&gt; !\n\nMaintenant que Malcin est mort, nous savons que l'avancée du Fléau sera stoppée. La Dame noire vous remercie pour vos efforts et souhaite vous récompenser.\n\nBien que nous ne connaissions pas l'étendue de l'influence du Fléau dans les Souilles, je suis certain que nous découvrirons leurs plans à temps.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCasse-têteCrache-clousRobe de zélote\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6522] = {title = "Une alliance impie", objective = "Apporter le Petit parchemin à Varimathras, à Undercity.", description = "Madame,\n\nVous savez exactement ce que nous sommes en train d’offrir. L’opportunité de prendre les Tarides et les terres au-delà n’est pas à négliger. Nous ne demandons que votre aide en retour. Nous ne vous demandons que votre aval pour mener nos actions dans la zone, en toute liberté.\n\nS’il vous plaît, donnez-nous l’occasion de pouvoir en discuter plus avant. Nous possédons une grande puissance, et nous sommes prêts à la partager avec ceux qui auront la sagesse de nous rejoindre. Je resterai à l’extérieur des Souilles de Tranchebauge, pour le moment.\n\nJe vous salue respectueusement,\nAmbassadeur Malcin", progress = "De quoi voulez-vous discuter, <nom> ? Vous devez penser que c'est important pour me harceler de la sorte.", completion = "Je reconnais l'insigne sur ce parchemin, &lt;nom&gt;. Vous l'avez trouvé sur cette vieille peau qui règne sur le Kraal de Tranchebauge ? Intéressant.\n\nLe Fléau n'est pas aussi satisfait qu’il semble l'être. Cet ambassadeur Malcin – celui qui a écrit cette note – est l’un des serviteurs maudits du Fléau, un diplomate humain du royaume de Lordaeron avant que les choses ne... changent.\n\nSi le Fléau essaye de prendre pied à Kalimdor, alors il est de notre devoir d'agir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6523] = {title = "Protéger Kaya", objective = "Escorter Kaya Flathoof au Camp Aparaje, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres-Rocheuses.", description = "Merci de me venir en aide ! Nous devons partir avant qu’ils ne découvrent que je suis libre. Pourriez-vous m’escorter jusqu’à Camp Aparaje. Je connais la route.\n\nMon père, Makaba Flathoof, se languit de savoir comment je vais.", progress = nil, completion = "Kaya est en vie ! Merci de l'avoir secourue, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6541] = {title = "Rapport à Kadrak", objective = "Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides.", description = "Avez-vous déjà été à Ashenvale, au nord ? La Horde a récemment établi un Avant-poste sur la grève de Zoram. Nous nous réjouissons toujours d’accueillir de nouvelles recrues pour nous aider à livrer bataille.\n\nSi vous avez confiance en vous et que vous voulez nous aider, allez voir Kadrak, dans le nord des Tarides, à la tour de guet. C’est lui qui dirige la campagne d’Ashenvale ; c’est lui aussi qui vous dira quoi faire.", progress = nil, completion = "Ashenvale est un pays divisé, mais nos récents efforts ont été couronnés de succès. Non seulement nous avons un avant-poste sur la grève de Zoram, mais aussi un autre au nord d'ici, appelé Bois-brisé.", rewards = "Vous recevrez :\n\n"},
[6542] = {title = "Rapport à Kadrak", objective = "Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides.", description = "Avez-vous déjà été à Ashenvale, au nord ? La Horde a récemment établi un Avant-poste sur la grève de Zoram ; nous nous réjouissons toujours d’accueillir de nouvelles recrues pour nous aider à livrer bataille.\n\nSi vous avez confiance en vous et que vous voulez nous aider, allez voir Kadrak, dans le nord des Tarides, à la tour de guet. C’est lui qui dirige la campagne d’Ashenvale ; c’est lui également qui vous dira quoi faire.", progress = nil, completion = "Ashenvale est un pays divisé, mais nos récents efforts ont été couronnés de succès. Non seulement nous avons un avant-poste sur la grève de Zoram, mais aussi un autre au nord d'ici, appelé Bois-brisé.", rewards = "Vous recevrez :\n\n"},
[6543] = {title = "Les rapports Warsong", objective = "Apporter les Rapports du clan Warsong à l’Eclaireur Warsong, au Messager Warsong et au Voltigeur Warsong. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides.", description = "J’ai récemment diligenté quelques éclaireurs dans Ashenvale, et j’ai besoin de quelqu’un pour leur faire parvenir les nouvelles directives et pour rapporter ce qu’ils ont pu observer sur place.\n\nAllez d’abord à l’avant-poste de Zoram'gar, le long de la côte, à l’ouest sur la grève de Zoram, pour localiser le premier d'entre eux. Vous devrez aussi passer par le poste de Bois-brisé, au nord et le long de la route vers l’est, dans Azshara. Vous trouverez un éclaireur et un voltigeur, là-bas.\n\nRemettez-leur à chacun un rapport, puis prenez note des dernières découvertes qu’ils ont faites.", progress = "Vite, <nom>. Ils doivent recevoir leur rapport ; c'est urgent.", completion = "Je constate que l'on peut compter sur vous. Ces nouvelles informations sont cruciales pour la planification du renforcement de notre présence dans Ashenvale. Nous pouvons dès maintenant préparer notre prochain déplacement.", rewards = "Vous recevrez :\n\n"},
[6544] = {title = "L'assaut de Torek", objective = "Escorter Torek lors de son attaque contre l’Avant-poste d'Aile-argent et Duriel Moonfire, puis faire un rapport à Ertog Ragetusk, au Poste de Bois-brisé.", description = "Hé ! <classe> ! Venez par ici !\n\nMes soldats et moi sommes sur le point d’attaquer l’avant-poste d'Aile-argent, plus à l’ouest. Notre cible, cette fois, est leur chef, Duriel Moonfire. Des éclaireurs ont rapporté que l’avant-poste était lourdement défendu par des sentinelles et des guerriers. La bataille sera splendide !\n\nQue diriez-vous de participer, à nos côtés, et de vous couvrir de gloire, <nom> ? Si vous venez avec nous, vous pourrez par la suite faire état de notre victoire auprès de mon supérieur, Ertog Ragetusk, à Bois-brisé.\n\nAlors, qu’en dites-vous, êtes-vous de notre côté ?", progress = nil, completion = "Alors l'attaque de Torek a réussi ! Bien joué, &lt;nom&gt;. Les elfes de la nuit sont de féroces adversaires. Un peu frêles, mais forts et féroces ! Je suis persuadé que la bataille valait le coup d’y assister...\n\nEt j'espère que vous y avez gagné une cicatrice ou deux !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton de marche poliCoutelas de Slatemetal\n\nVous recevrez également :\n\n"},
[6545] = {title = "Mise à jour du Messager Warsong", objective = "Donc vous êtes ici avec mes ordres ? C'est toujours un plaisir de voir une nouvelle recrue avec une nature exubérante et qui persévère.\n\nVous devez apprendre vite si vous voulez rester ici. La menace que représentent les nagas grandit, <nom>. Je me suis occupé de la défense lors de plusieurs attaques contre cet avant-poste depuis que je suis ici.\n\nMais si vous voulez vous y atteler, parlez à quelqu'un d'autre à l'avant-poste.", description = nil, progress = "Donc vous êtes ici avec mes ordres ? C'est toujours un plaisir de voir une nouvelle recrue avec une nature exubérante et qui persévère.\n\nVous devez apprendre vite si vous voulez rester ici. La menace que représentent les nagas grandit, <nom>. Je me suis occupé de la défense lors de plusieurs attaques contre cet avant-poste depuis que je suis ici.\n\nMais si vous voulez vous y atteler, parlez à quelqu'un d'autre à l'avant-poste.", completion = "Eh bien, ces mises à jour vont tout expliquer à Kadrak ! Vous devez retourner le voir et lui apporter ceci le plus rapidement possible.", rewards = "Vous recevrez :\n\nMise à jour du Messager Warsong"},
[6546] = {title = "Mise à jour du voltigeur Warsong", objective = "Il y a beaucoup de dangers sur ce chemin, <nom>. Vous avez intérêt à ne pas l'oublier quand vous traverserez ces terres. La menace que représente l'Alliance est très proche.\n\nNous avons des ennemis sur tous les fronts. Les satyres sont une force redoutable et très répandue dans l'est d'Ashenvale. De plus, j'ai découvert que les nagas ont envahi une grande partie des terres d'Azshara.\n\nIl est réconfortant de voir que nos effectifs augmentent. Il faut se préparer à ce qui nous attend, <nom>.", description = nil, progress = "Il y a beaucoup de dangers sur ce chemin, <nom>. Vous avez intérêt à ne pas l'oublier quand vous traverserez ces terres. La menace que représente l'Alliance est très proche.\n\nNous avons des ennemis sur tous les fronts. Les satyres sont une force redoutable et très répandue dans l'est d'Ashenvale. De plus, j'ai découvert que les nagas ont envahi une grande partie des terres d'Azshara.\n\nIl est réconfortant de voir que nos effectifs augmentent. Il faut se préparer à ce qui nous attend, <nom>.", completion = "Apportez mes mises à jour à Kadrak. Rapidement, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nMise à jour du Voltigeur Warsong"},
[6547] = {title = "Mise à jour de l'Eclaireur Warsong", objective = "Gardez l'oeil ouvert, <nom>. Les elfes se cachent souvent dans les ombres...\n\nNous devons toujours être à l'affût. Nous avons travaillé dur pour gagner cette terre, et les elfes cherchent à nous la voler.\n\nJ'imagine que vous m'avez apporté mes prochains ordres provenant de Kadrak ?", description = nil, progress = "Gardez l'oeil ouvert, <nom>. Les elfes se cachent souvent dans les ombres...\n\nNous devons toujours être à l'affût. Nous avons travaillé dur pour gagner cette terre, et les elfes cherchent à nous la voler.\n\nJ'imagine que vous m'avez apporté mes prochains ordres provenant de Kadrak ?", completion = "Faisons savoir à Kadrak que nous avons réussi à repousser les elfes de la nuit. Nos plans se déroulent bien.", rewards = "Vous recevrez :\n\nMise à jour de l'Eclaireur Warsong"},
[6548] = {title = "Vengez mon village !", objective = "Tuez 8 Forbans du Totem sinistre et 6 Mercenaires du Totem sinistre, puis retournez voir Makaba Flathoof, près de la lisière sud-est des Serres-Rocheuses.", description = "Le clan du Totem sinistre a fait un raid sur mon village et y a tué presque tout le monde ; j’ai lutté autant que j’ai pu, abattant autant d’ennemis que possible, mais j’ai dû battre en retraite et ai pu m’échapper de justesse.\n\n<nom>, je n’aspire qu’à la vengeance et à en voir toujours plus mourir sous mon épée. Aidez-moi à les massacrer, vous les trouverez un peu plus à l’ouest.", progress = "Les avez-vous tués ?", completion = "&lt;nom&gt;, merci... mais je n'oublierai jamais ce que le Totem sinistre a fait à mon village.", rewards = "Vous recevrez :\n\n"},
[6561] = {title = "L'infamie de Brassenoire", objective = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff.", description = "Ma force m'a abandonné. Votre aide m'est nécessaire !\n\nIl y a longtemps, cet endroit était un grand temple d'Elune. Mais il a été conduit à la ruine quand la corruption d'un Dieu très ancien a suinté de la terre et souillé le Puits de lune sacré.\n\nAku'Mai, le serviteur du Dieu très ancien, est sorti des eaux.\n\nLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Ces sectateurs, menés par Kelris, sacrifient des innocents à Aku'Mai afin d’obtenir sa puissance.\n\nS'il vous plaît, <nom>, tuez Kelris et apportez sa tête à Bashana, à Thunder Bluff.", progress = "Que la Terre-mère soit avec vous, <nom>.\n\nMaintenir la paix entre la terre et les gens qu'elle porte doit être notre but. Elle a un grand projet pour la nature, et nous y avons tous un rôle à jouer.", completion = "Kelris a échappé à l'Aube d'argent pour un moment.\n\nPendant un temps ils l'ont considéré comme mort ou disparu.\n\nEn mettant fin à son règne vous avez sauvé un grand nombre de vies innocentes, &lt;nom&gt;.\n\nQue la Terre-mère soit louée ! Sacrifier quelqu’un à un serviteur d'un Dieu très ancien pour un profit personnel est plus que répugnant !\n\nVous avez fait une bonne chose aujourd'hui. Kelris était une créature du mal qui cherchait à ramener le monde au temps du chaos, en vouant un culte à ces Dieux très anciens. Merci, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSceptre du tombeauTarge arctique\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6562] = {title = "Problèmes dans les profondeurs", objective = "Parler à Je'neu Sancrea, à Ashenvale.", description = "Je'neu Sancrea a besoin d'aide. Il est à l'avant-poste de Zoram'gar dans Ashenvale. La forêt des elfes de la nuit est au nord des Serres-Rocheuses. Vous pouvez le rejoindre en voyageant par la combe des Cisailles ou en vous dirigeant vers le nord à travers les Tarides. La grève de Zoram est à l'ouest de la forêt, assez loin. Faites preuve de prudence, <nom>. Il y a des forces là-bas qui ne verront pas votre présence d'un bon œil.", progress = nil, completion = "Tsunaman vous envoie ? Excellent. Nous avons des choses à nous dire.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6563] = {title = "L'Essence d'Aku'Mai", objective = "Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale.", description = "Dans les premiers tunnels des Profondeurs de Brassenoire, on trouve de grosses grappes de saphirs le long des murs. Récemment, on a constaté que les nagas ramassaient les cristaux. Jusqu'à ce qu'on sache pourquoi, il vaudrait mieux empêcher les nagas de continuer. Les cristaux ont un grand pouvoir élémentaire et s'ils sont mal utilisés, ils peuvent entrer dans la composition d'un arcane puissant.\n\nVoulez-vous m'aider, <nom> ? Les Profondeurs de Brassenoire se trouvent le long de la grève de Zoram au nord de notre avant-poste.", progress = "Comment se passe votre recherche des cristaux, <nom> ? Avez-vous la preuve que les nagas les moissonnent ? J'espère que nous connaîtrons un jour la raison pour laquelle ils récupèrent ces choses.", completion = "Bien joué, &lt;nom&gt;. Ce sont les cristaux dont je parlais. Intéressant...\n\nJe sens la puissance à l'intérieur. Les esprits de l'eau s'y accrochent. J'ignore pourquoi les nagas veulent s'en servir... Réjouissons-nous qu'ils ne soient plus entre leurs mains.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6564] = {title = "Allégeance aux Dieux très anciens", objective = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale.", description = "Quelques mots sont griffonnés en haut de la note chiffonnée :\n\n\"Oui, dites à toutes les prêtresses de m'apporter les cristaux. L'esprit des élémentaires d'eau y est fort et ils aideront énormément nos aquamanciens dans leurs prédictions.\n\nEn contrôlant le pouvoir des cristaux, nous apaiserons Aku'Mai. Un jour, nous aurons assez de pouvoir pour ramener Aku'Mai et le monde connaîtra à nouveau une ère de gloire ! Une ère régie par les Dieux très anciens ! \"", progress = "Oui, <nom> ? De quoi avez-vous besoin ? J'ai encore tellement à apprendre sur les cristaux que les nagas collectent.", completion = "C'est très intéressant, en effet. Je suis content que vous ayez attiré mon attention sur cela.\n\nMaintenant, nous pouvons mettre un nom sur nos problèmes… Lorgus Jett.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6565] = {title = "Allégeance aux Dieux très anciens", objective = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale.", description = "On ne peut pas permettre au disciple du Marteau du crépuscule d'achever son plan. Le Marteau du crépuscule ne comprend pas l'esprit de la nature. Il croit aux Dieux très anciens, des créatures de chaos et de destruction qui ont été battues il y a bien longtemps. On ne peut pas permettre à ce Lorgus de réussir. Vous devez l'arrêter, <nom>. Je ne peux pas le faire moi-même – je suis trop faible.\n\nAllez dans les Profondeurs de Brassenoire, trouvez-le et tuez-le. Revenez me voir ici à Zoram'gar quand ce sera fait.", progress = "L'avez-vous trouvé, <nom> ? Lorgus doit être arrêté !", completion = "Très bien ! Merci, &lt;nom&gt;. Nous n'avons peut-être pas complètement arrêté le Marteau du crépuscule, mais au moins, vous avez saboté un autre de leurs plans pour ramener les Dieux très anciens au pouvoir.\n\nQui pourrait dire quels autres plans ils sont en train de mettre au point ? Quoi qu'il en soit nous pouvons souffler un peu, pour le moment.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau du poingMantelet noisette\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6566] = {title = "Ce que le vent apporte", objective = "Écouter Thrall.", description = "Cela fait plaisir de vous revoir, <nom>. Le vent transporte avec lui des nouvelles des Royaumes de l'Est.\n\nAsseyez-vous, écoutez.", progress = "Patience, <nom>. Écoutez-moi !", completion = "Êtes-vous prêt pour cette tâche ?", rewards = "Vous recevrez :\n\n"},
[6567] = {title = "Le Champion de la Horde", objective = "Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas.", description = "L'un de mes champions m'a envoyé un mot pour dire qu'il existait peut-être un chemin dans la tanière du dragon. Vous devez le rejoindre.\n\nRexxar se trouve sur la terre déserte de Désolace, entre les Serres-Rocheuses et Feralas. Il attend votre venue.", progress = nil, completion = "Il n'existe qu'un chemin pour entrer dans l'antre du dragon, &lt;nom&gt;.\n\nVoyez-vous, seuls les dragons noirs les plus puissants sont autorisés à entrer dans l'antre de la Mère des couvées. De nombreuses épreuves doivent être passées, et la clé doit être rituellement enchantée par le général Drakkisath en personne !\n\nÉtant donné que vous n'êtes pas un draconien noir, vous allez certainement rencontrer des difficultés pour obtenir le droit de passage.", rewards = "Vous recevrez :\n\n"},
[6568] = {title = "Le testament de Rexxar", objective = "Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest.", description = "Que connaissez-vous des illusions, <nom> ? Parce que c'est une illusion que vous devez créer pour circonvenir les défenses du Vol noir.\n\nJe connais une personne qui acceptera de vous aider dans votre recherche de l'art de la tromperie. Elle a aidé les nôtres dans le passé, quand elle jugeait que la cause en était digne.\n\nDans les Maleterres de l'ouest, vous trouverez Myranda la Sorcière, un Maître Illusionniste, exilée de l'Alliance de Lordaeron. Allez là-bas et prenez avec vous ce message.", progress = "Il n'est pas fréquent de voir une personne de la Horde dans cette partie de Lordaeron. Qu'avez-vous pour Myranda ?", completion = "&lt;Myranda tient la note, fait une pause et sourit.&gt;\n\nComment va-t-il ? Je veux dire Rexxar. Oh, détendez-vous, ne soyez pas si confus. Cette lettre a intentionnellement été laissée blanche. Elle portait avec elle les intentions et les pensées de son créateur. À en juger par son contenu, pas la peine de se demander pourquoi Rexxar l'a laissée comme ça. Imaginez ce qui se serait passé, si par la capture ou dans la mort, ces informations vous avaient échappé !\n\nOh, aucune importance ! Myranda vous aidera, &lt;nom&gt;. Je dois au Chef de guerre une faveur ou deux.", rewards = "Vous recevrez :\n\n"},
[6569] = {title = "Illusions d'Occulus", objective = "Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée.", description = "Ainsi le <race> souhaite devenir membre du Vol noir, hein ?\n\nLa création de l'illusion que vous exigez est insignifiante, mais les composants requis pour la divination sont très difficiles à obtenir. Rexxar et le Chef de guerre vous ont confié cette mission, donc Myranda doit penser que vous en êtes capable.\n\nAllez à la citadelle supérieure du Pic Blackrock et tuez assez de draconides noirs pour remplir l'un de vos sacs de leurs yeux.\n\nRetournez voir Myranda quand vous aurez ramassé suffisamment de réactifs.", progress = "Les yeux de ce que nous voulons imiter est la partie le plus important de toute illusion, <nom>.", completion = "Laissez Myranda jeter un œil, &lt;nom&gt;.\n\nOh oui, ceux-ci feront parfaitement l'affaire.\n\nAvec ces réactifs, Myranda va créer pour vous un médaillon qui vous fournira une illusion capable de tromper le portier des dragons noirs.", rewards = "Vous recevrez :\n\n"},
[6570] = {title = "Brandeguerre", objective = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre.\n\nObjet fourni : \n", description = "J'ai chargé ce médaillon avec suffisamment de magie pour créer et entretenir une illusion à l'intérieur de la tanière de Brandeguerre.\n\nC'est un ancien drake, le vieux gardien de la porte de Nefarian, chargé de tester la valeur des draconides qui veulent rejoindre la garde d'élite d’Onyxia.\n\nAllez à la tourbière du Ver du marécage d'Âprefange et pénétrez dans sa tanière. Une fois là, placez l'amulette et allez là où votre destin vous mènera !", progress = nil, completion = "Les effectifs de nos troupes sont-ils tombés si bas que Nefarian m'envoie des chiots ? Vous ne passerez jamais mes épreuves, avorton.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6571] = {title = "Fournitures Warsong", objective = "Collecter les Fournitures Warsong : Lames du clan Warsong, Huile Warsong, et la Cargaison de Haches Warsong ayant pour destinataire Locke Okarr, au Poste de Bois-brisé.", description = "Il nous manque quelques fournitures au Camp de bûcherons Warsong !\n\nPixel a notre cargaison de Lames, au Poste de Bois-brisé. Il faudra prendre le temps d'aller à Baie-du-Butin pour prendre une caisse de haches chez Maître Lozgil.\n\nMalheureusement, les choses seront moins évidentes pour notre cargaison d'huile et de corde : les furbolgs Crins-de-Chardon et Vile-sylve ont volé les cordes et les satyres ont intercepté la livraison d'huile. Ils l'utilisent maintenant pour leurs détestables rituels, dans le Défilé de la nuit et à Satyrnaar !\n\nJ'aurai des problèmes si je ne livre pas ces produits… Pouvez-vous m'aider ?", progress = "J'espère que vous arrivez avec les fournitures !", completion = "Excellent, &lt;nom&gt;. Vous m'avez épargné beaucoup de travail !\n\nMais ne pensez pas que je sois ingrat !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEcharpe warsongBottes WarsongGantelets Warsong\n\nVous recevrez également :\n\n"},
[6581] = {title = "Lames du clan Warsong", objective = "En provenance directe de Ratchet, des lames du clan Warsong ! Ouais, je les ai ici.\n\nMais qu'avez-vous en contrepartie pour moi ? Vous ne pouvez pas les emporter comme ça, vous savez ! Mon temps coûte cher !\n\nCe dont j'ai besoin, c'est d'une bonne arme à feu pour mes voyages. Une fille doit se protéger savez-vous ? Il y en a une que j'aime particulièrement, et je suis sûre qu'un ingénieur n'aura aucun problème à la fabriquer.\n\nVoilà, si vous m'apportez un Tromblon mortel, je vous donnerai la cargaison de lames. Alors, marché conclu ?", description = nil, progress = "En provenance directe de Ratchet, des lames du clan Warsong ! Ouais, je les ai ici.\n\nMais qu'avez-vous en contrepartie pour moi ? Vous ne pouvez pas les emporter comme ça, vous savez ! Mon temps coûte cher !\n\nCe dont j'ai besoin, c'est d'une bonne arme à feu pour mes voyages. Une fille doit se protéger savez-vous ? Il y en a une que j'aime particulièrement, et je suis sûre qu'un ingénieur n'aura aucun problème à la fabriquer.\n\nVoilà, si vous m'apportez un Tromblon mortel, je vous donnerai la cargaison de lames. Alors, marché conclu ?", completion = "C'est parfait, c'est exactement ce que je voulais ! Eh bien, voilà la cargaison.", rewards = "Vous recevrez :\n\nLames du clan Warsong"},
[6582] = {title = "L'épreuve des crânes, Clairvoyant", objective = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.\n\nClairvoyant se trouve au Berceau-de-l'Hiver.", description = "Nous sommes les enfants de l'Aile de mort. Notre domination sur les Aspects moindres doit être absolue.\n\nSi vous êtes vraiment digne de l'Ascension, les dragons de moindre niveau fuiront votre présence.\n\nTrouvez leurs champions et causez leur perte au nom de notre Père !\n\nAllez au Berceau-de-l'Hiver et traquez le puissant drake bleu, Clairvoyant. Écrasez-le, ainsi que tous ceux du Vol bleu qui se trouveront sur votre chemin. Arrachez son crâne et rapportez-le-moi.", progress = "<Brandeguerre siffle.>", completion = "Vous avez passssé la première épreuve. Une autre commence…", rewards = "Vous recevrez :\n\n"},
[6583] = {title = "L'épreuve des crânes, Somnus", objective = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.", description = "De même que notre Père écrase les Aspects eux-mêmes, nous devons nous efforcer d'apporter le chaos et la destruction à leurs enfants.\n\nVous devez tester votre talent au combat contre les rêveurs sans sommeil : les enfants du Vol vert.\n\nAllez au marais des Chagrins et traquez Somnus, le champion drake du Vol vert. Laissez agir votre haine ; dominez l'insecte... Revenez me voir avec son crâne...", progress = "Ne revenez pas avant d'avoir baigné dans le sang de nos ennemis et bu leurs souffrances.", completion = "Deux de complets, il en reste deux...", rewards = "Vous recevrez :\n\n"},
[6584] = {title = "L'épreuve des crânes, Chronalis", objective = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.", description = "Les Gardiens du temps, les fils de Nozdormu le Seigneur des sssiècles...\n\nIl y en a trois qui gardent les Grottes du temps, mais sssseul l'un d'eux a retenu l'attention du Vol noir : le Passeur du temps, Chronalissss, le favori de Nozdormu.\n\nTuez ce champion et vous aurez porté un coup qui tirera des larmes au plus sssstoïque des sssables du temps. Revenez me voir avec son crâne.", progress = "Ironiquement, le temps nous est compté.", completion = "Il ressste le plus détesssté...", rewards = "Vous recevrez :\n\n"},
[6585] = {title = "L'épreuve des crânes, Axtroz", objective = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre.", description = "C'est sur les montagnes de Grim Batol que notre Père a déchaîné sa colère contre les Aspects. L’acte lâche du traître, Alexstrazsa, a donné aux autres Aspects assez de temps pour échapper à la colère de Père.\n\nQuel acte misérable...\n\nLe Vol rouge garde désormais Grim Batol. Son lieutenant, Axtroz, doit être détruit. Rapportez-moi le crâne d'Axtroz. Pour Père !", progress = "Changements... Je les sens se produire en vous. Passez ce test et alors il ne restera plus que la cérémonie.", completion = "J'ai douté de votre dévouement, petit. Vous avez persévéré, dominant nos ennemis et attirant l'honneur dans notre sillage.\n\nJe dois préparer maintenant les crânes pour votre ascension.", rewards = "Vous recevrez :\n\n"},
[6601] = {title = "Ascension...", objective = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.", description = "Un médaillon a été façonné à partir des crânes de nos ennemis. Vous connaissez ce médaillon, n'est-ce pas ? Vous l'avez sûrement vu porté par vos aînés.\n\nPrenez cela. Retournez au Pic et présentez-le au général Drakkisath. Il y placera l'enchantement final pour mettre ce bibelot en phase avec votre esprit.\n\nVous porterez ce médaillon avec honneur, en signe de votre accession à l'un de nos rangs les plus fermés : Gardien de la mère des couvées.\n\nAllez !", progress = "Ne paniquez pas, <nom> !", completion = "C’est comme quand les dragons parlent, &lt;nom&gt;, il y a plus d'air chaud que d'informations intéressantes. On ne peut que s'attendre à un comportement pompeux et agressif de leur part.", rewards = "Vous recevrez :\n\n"},
[6602] = {title = "Le sang du champion des dragons noirs", objective = "Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar.", description = "Vous irez rendre visite au général, mais pas en tant que dragon noir.\n\nVous voyez, une cérémonie n'est qu'un autre terme pour permettre de verser du sang au Vol noir.\n\nL'amulette inachevée a simplement besoin du sang du général pour s’activer. Un de leurs mécanismes à sûreté intégrée.\n\nRetournez au pic Blackrock et détruisez Drakkisath. Rapportez son sang ici et j'activerai la clé du repaire d'Onyxia.", progress = "On ne doit pas traiter à la légère Drakkisath, <nom>. Il est responsable de la mort de milliers de personnes.", completion = "&lt;Rexxar a un rictus.&gt;\n\nLe récit de vos exploits sera conté pendant les années à venir, &lt;nom&gt;. Cette Amulette drakefeu est la clé du repaire d'Onyxia. Rassemblez vos forces et partez en campagne au nom de la Horde !", rewards = "Vous recevrez :\n\nAmulette drakefeu"},
[6603] = {title = "Troubles au Berceau-de-l'Hiver", objective = "Trouver Donova Snowden, à côté des sources chaudes du Berceau-de-l'Hiver.", description = "Il y a du grabuge au Berceau-de-l'Hiver !\n\nSûr, je passe du temps dans les étendues sauvages et je connais des choses... Je suis toujours très fière de le dire. Je considère que les heures que je passe là-bas dans les collines sont comme de l'or. Elles aident à avoir des réflexes rapides, une tête fraîche et un œil aiguisé... \n\nIl faut du jugement, de l'intelligence et de la maturité pour apprécier la solitude de ces chemins.\n\nBon, de quoi j'étais en train de parler ? \n\nAh oui, du grabuge ! Allez voir Donova Snowden aux sources chaudes, elle vous en dira plus.", progress = nil, completion = "Hé, salut ! Alors Meggi vous a parlé du problème que j'ai découvert ici ?", rewards = "Vous recevrez :\n\n"},
[6604] = {title = "Les Indomptables enragés", objective = "Parler à Jaron Stoneshaper, au village de Pluie-d'Etoiles.", description = "Avez-vous remarqué le camp abandonné au sud d'ici ? Il semble que les Indomptables soient devenus fous et qu’ils aient tout détruit sur leur passage !\n\nIl paraît qu'un des survivants de l'attaque est resté au village de Pluie-d'Etoiles, à l'ouest. Je suis curieux de savoir ce qui s'est passé... Pas vous ?", progress = nil, completion = "Salut, qu'est-ce que je peux faire pour vous ?", rewards = "Vous recevrez :\n\n"},
[6605] = {title = "Une étrange personne", objective = "Parler à Winna Hazzard, à Gangrebois.", description = "Je reviens tout juste de Gangrebois, <nom>. Sur le chemin, je me suis arrêté au Poste de la Vénéneuse et j'ai rencontré une personne très étrange... Elle semblait absorbée par quelque chose. Je pourrais vous dire de quoi il s'agit, mais je pense qu'elle préférerait vous l'expliquer elle-même.\n\nSi cela vous intéresse, allez au Poste de la Vénéneuse, à l'ouest de Gangrebois, et demandez Winna Hazzard.\n\nQui sait, elle pourrait avoir besoin de votre aide...", progress = nil, completion = "Ah, &lt;classe&gt;. Je vois qu'il y a de l'espoir maintenant. Êtes-vous ici pour me porter assistance ?", rewards = "Vous recevrez :\n\n"},
[6606] = {title = "Un peu de chance", objective = "Parler à la Mau'ari, à Long-guet.Nous pouvons toujours bénéficier d'un petit peu de chance, hein ? Un petit avantage, c'est tout ce qu'il faut pour que les choses tournent en votre faveur...\n\nIl y a quelque temps, j'ai eu l'occasion de faire la connaissance d'une érudite plutôt excentrique qui suit la voie des sorciers-docteurs. Elle m'a fait un charme de chance... pour un prix certain. Mais croyez-moi, il le vaut bien !\n\nÇa vous intéresserait peut-être d'avoir le vôtre ? Allez voir Mau'ari à Long-guet. Je garde le mien !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Nous pouvons toujours bénéficier d'un petit peu de chance, hein ? Un petit avantage, c'est tout ce qu'il faut pour que les choses tournent en votre faveur...\n\nIl y a quelque temps, j'ai eu l'occasion de faire la connaissance d'une érudite plutôt excentrique qui suit la voie des sorciers-docteurs. Elle m'a fait un charme de chance... pour un prix certain. Mais croyez-moi, il le vaut bien !\n\nÇa vous intéresserait peut-être d'avoir le vôtre ? Allez voir Mau'ari à Long-guet. Je garde le mien !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6607] = {title = "Nat Pagle, pêcheur de l'extrême", objective = "Nat Pagle voudrait que vous attrapiez les poissons suivants :\n\nLe Mahi Mahi de Brumejonc, de la grève de Brumejonc, dans le marais des Chagrins.\n\nUn Frappeur Sar'theris, de la grève de Sar'theris en Désolace.\n\nL'Ahi de Feralas, de la rivière Verdantis de Feralas.\n\nLe Sailfin bleu de la Côte sauvage, de la Côte sauvage de la vallée de Strangleronce.\n\nRetournez voir Nat Pagle quand la collecte sera terminée.", description = "On peut pas dire que j'aime vraiment beaucoup pêcher. Figurez-vous que ça fait vingt ou trente bonnes années que je fais ça.\n\nJ'estime que les gens ont leurs raisons de faire ce qu'ils font.\n\nMaintenant, ça veut pas dire que vous devez pêcher pendant trente ans ou attraper tous les poissons de la mer pour devenir un Maître Pêcheur. J'estime que vous devez juste être volontaire – assez volontaire pour vous asseoir pendant des heures, à rien faire\n\nJe vais vous dire, attrapez-moi quelques poissons rares et je vous apprendrai une chose ou deux. Voici la liste :", progress = "Ça mord aujourd'hui ?", completion = "Que voilà une belle prise !\n\nVenez par ici, laissez-moi vous montrer comment poser quelques lignes.", rewards = "Vous apprendrez :\n\nPêche\n\nVous allez être la cible du sort suivant :\n\nArtisan pêcheur\n\nVous recevrez également :\n\n"},
[6608] = {title = "Vous êtes trop bon", objective = "Vous pensez que Lumak essaie de vous dire qu’il ne peut plus vous aider à améliorer votre compétence de pêche. Vous devriez essayer de vous adresser maintenant à son ami, Nat Pagle, un pêcheur humain des îles au sud de Theramore (c’est du moins ce que vous croyez comprendre du discours de Lumak).", description = "Lumak ne peut plus enseigner à <nom>. Vous trop bon ! Vous trouver ami de Lumak, Nat Pagle. Est humain, mais pas manger ! Est ami de Lumak ! Nat apprend vous à mieux pêcher.\n\nTrouver Nat dans le marécage d'Âprefange, au sud de ville de Humie, Thermoroquelquechosecommeça. Nat sûrement en train de pêcher. Partir maintenant !", progress = nil, completion = "Bien sûr, vous devez être une amie de Lumak.\n\nLa pêche ? Je peux tout vous raconter sur la pêche.", rewards = "Vous recevrez :\n\n"},
[6609] = {title = "Il ne me reste rien !", objective = "Aller à Kalimdor, dans la ville côtière de Theramore. À partir de là, chercher une île au sud de la ville principale. Nat Pagle vous attend !", description = "Bon sang, je suis un nain ! Je n'ai pas été conçu pour pêcher ! Je veux dire, regardez-moi ! Je suis pratiquement fait en pierres.\n\nJe n'ai rien laissé, je vous ai tout transmis. Je vous ai appris tout ce que je sais, flip flop !\n\nVous avez tout ? Oh, excellent ! J'ai un vieil ami sur Kalimdor qui peut vous aider. Il s'appelle Nat Pagle, un garçon très bien. Trouvez-le sur les îles au sud de Theramore. Allez !", progress = nil, completion = "J'ai toujours de la place sur mon île pour les visiteurs… Je crois…", rewards = "Vous recevrez :\n\n"},
[6610] = {title = "Surprise de palourdes", objective = "Dirge Quikcleave voudrait que vous lui apportiez les objets suivants :\n\n12 Oeufs géants. Vous les trouverez sur les Rocs qui hantent Tanaris ou sur toute autre espèce de grand oiseau.\n\n10 morceaux de Chair de palourde piquante. Vous pouvez trouver la chair de palourde sur... les palourdes, naturellement !\n\n20 Emmentals d'Alterac. Vous les trouverez dans une fromagerie !\n\nCollectez tous ces objets, puis retournez voir Dirge.", description = "Déjà entendu parler de l’omelette aux palourdes ? Bien sûr que non ! C'est mon dernier et plus grand chef-d'œuvre culinaire. Oh, <nom>, je salive rien que d'y penser !\n\nMalheureusement, je manque des ingrédients nécessaires pour cuisiner ! Faisons un marché : vous allez chercher les produits dont j'ai besoin pour faire mon plat et en échange je vous apprends les subtilités de la cuisine exotique. Je préparerai même quelques palourdes pour démarrer ! D'accord ?\n\nVoici ce dont j'ai besoin :", progress = "Mes besoins vont avoir raison de moi ! Vite, <nom> ; avant que je n'entame mes propres réserves.", completion = "Vous allez vous régaler, &lt;nom&gt;. Regardez et apprenez !", rewards = "Vous apprendrez :\n\nCuisine\n\nVous allez être la cible du sort suivant :\n\nArtisan cuisinier\n\nVous recevrez également :\n\nSurprise de palourdes"},
[6611] = {title = "Vers Gadgetzan vous allez !", objective = "Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave.", description = "Pourquoi vous croire que Zamja peut apprendre autre chose ? Vous tout savoir de cuisine mojo de Zamja et quand même vouloir savoir plus !\n\nZamja peut pas. Gros <race> aller à Gadgetzan. Trouver là-bas petit gobelin Dirge. Lui peut aider.\n\nQuand vous faire grande cuisine, vous revenir et apprendre à Zamja, d’accord ? Allez maintenant !", progress = nil, completion = "&lt;Dirge crache des bouts de sandale en cuir.&gt;\n\nPfftou...\n\n&lt;Dirge tousse bruyamment.&gt;\n\nQuoi ? Je dois vous dire que ce cuir est étonnamment riche en protéines et ne contient presque pas d'hydrates de carbone.", rewards = "Vous recevrez :\n\n"},
[6612] = {title = "Je connais un gars...", objective = "Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave.", description = "Par ma meilleure cuillère, j'peux dire que vous savez cuisiner. Là, j'peux rien vous apprendre.\n\n'Reusement pour vous, je connais un type. C'est un gobelin, même qu'il est le meilleur cuisinier de Kalimdor.\n\nOuais, ça, c'est la mauvaise nouvelle ! Va falloir que vous alliez à Kalimdor. Puis à Gadgetzan pour chercher Dirge Quikcleave. Il vous donnera ses recettes.", progress = nil, completion = "&lt;Dirge crache du cuir.&gt;\n\nPfftou...\n\n&lt;Dirge tousse bruyamment.&gt;\n\nQuoi ? Je dois vous dire que ce cuir est étonnamment riche en protéines et ne contient presque pas de glucides, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6621] = {title = "Le roi des Vile-sylve", objective = "Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram'gar.", description = "<nom>, une autre tribu de furbolgs, les Vile-sylve, vit au sud-est d'Astranaar. Ils sont moins nombreux que les Crins-de-Chardon, mais leur férocité représente une menace latente. Avec les moyens adéquats, nous pouvons éradiquer cette menace.\n\nPrenez cette bannière et allez au village des Vile-sylve, puis placez-la sur leur Monticule du totems. Ils essaieront de détruire la bannière, mais vous devrez contenir leurs assauts et les en empêcher jusqu'à ce que leur chef, Murgut, apparaisse pour sauver l'honneur de la tribu. Tuez-le et rapportez-moi le totem qu'il porte.\n\nNe partez pas sans avoir levé une équipe d'alliés ou d'amis pour vous aider dans cette mission hautement périlleuse, <nom>. Cette quête ne peut se réussir en solitaire, <classe>.", progress = "Avez-vous vaincu le Chef Murgut, <nom> ? Avez-vous récupéré son totem Vile-sylve ?", completion = "Bon travail, &lt;nom&gt;. Défaire les Vile-sylve et leur chef au combat envoie un message clair :\n\nOn ne plaisante pas avec la Horde.\n\nJe ne pense pas que cette tribu nous fera à nouveau des problèmes avant longtemps.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTunique de rustreJambières en cobalt\n\nVous recevrez également :\n\n"},
[6622] = {title = "Triage", objective = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.\n\nRappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.", description = "Bonjour, docteur. Cet après-midi, nous allons tester votre capacité à trier les patients en fonction de l'urgence de leur état. Si vous réussissez votre examen, vous rejoindrez les rangs prestigieux de la Horde Trauma.\n\nBien, maintenant, attention ! Le blessé le plus critique doit être soigné d'abord. Ensuite, ceux qui sont gravement blessés. Les blessés légers passent en dernier. Vous devez sauver 15 patients pour réussir cet examen. Vous échouez si 6 d’entre eux meurent pendant le tri.\n\nIl vous sera fourni des bandages de triage.\n\nBonne chance, docteur.", progress = nil, completion = "Docteur &lt;nom&gt;, bienvenue parmi les médecins de la Horde.", rewards = "Vous apprendrez :\n\nPremiers soins\n\nVous allez être la cible du sort suivant :\n\nArtisan secouriste\n\nVous recevrez également :\n\n"},
[6623] = {title = "Service de traumatologie de la Horde", objective = "Aller au Trépas-d'Orgrim, dans les hautes-terres d'Arathi, et évoquer avec le docteur Gregory Victor la possibilité de rejoindre les rangs des médecins de la Horde.", description = "Docteur <nom>, je suppose. C'est un plaisir de vous revoir.\n\nJ'ai de merveilleuses nouvelles pour vous : le docteur Gregory Victor, médecin-chef de la Horde, veut que vous alliez le retrouver au Trépas-d'Orgrim. Ceci pourrait bien être une occasion unique ! Je donnerais n'importe quoi pour avoir la chance d'étudier avec le grand docteur Gregory Victor ! Ne gâchez pas cette occasion, elle ne se représentera peut-être plus jamais !", progress = nil, completion = "Merveilleux. préparez-vous, nous devons commencer immédiatement !", rewards = "Vous recevrez :\n\n"},
[6624] = {title = "Triage", objective = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.\n\nRappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.", description = "Bonjour, docteur. Vous subirez un test quant à votre compétence de diagnostic et de triage des patients, cet après-midi. Si vous réussissez cette épreuve, vous rejoindrez les rangs des médecins de l'Alliance.\n\nMaintenant, faites bien attention : ceux qui agonisent doivent être soignés en premier. Ensuite, viennent ceux qui ont été grièvement blessés. Les blessés seront, quant à eux, les derniers à recevoir des soins. Vous devez sauver 15 patients pour réussir l'examen. Si plus de 5 patients meurent pendant le triage, vous aurez échoué votre examen.\n\nBonne chance, docteur.", progress = nil, completion = "Docteur &lt;nom&gt;, bienvenue dans les rangs des médecins de l'Alliance.", rewards = "Vous apprendrez :\n\nPremiers soins\n\nVous allez être la cible du sort suivant :\n\nArtisan secouriste\n\nVous recevrez également :\n\n"},
[6625] = {title = "Service de traumatologie de l'Alliance", objective = "Aller à Theramore, dans le marécage d'Âprefange, et parler au docteur Gustaf VanHowzen de la possibilité de rejoindre les rangs des médecins de l’Alliance.", description = "Docteur <nom>, je suppose. C'est un plaisir de vous revoir.\n\nJ'ai de merveilleuses nouvelles pour vous : Gustaf VanHowzen, médecin-chef de l'Alliance, veut que vous alliez le retrouver à Theramore. Ceci pourrait bien être une occasion unique ! Je donnerais n'importe quoi pour avoir la chance d'étudier sous l'enseignement du grand docteur Gustaf VanHowzen ! Ne gâchez pas cette occasion, elle ne se représentera peut-être plus jamais !", progress = nil, completion = "Merveilleux. préparez-vous, nous devons commencer immédiatement !", rewards = "Vous recevrez :\n\n"},
[6626] = {title = "L'hôte du mal", objective = "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge.", description = "Les Réprouvés ne meurent pas de leur... maladie... d'après ce que j'ai pu voir. Ce diplomate semble offrir la non-vie à ses disciples potentiels. Je commence à penser qu'il fait partie du Fléau.\n\nPour l'instant, ce n'est pas lui qui me préoccupe, mais les effectifs qui enflent dans son sillage. Ils sortent des ombres, chaque jour plus nombreux à lui demander plus de force et de puissance.\n\nJe n'ai pas les compétences nécessaires pour les combattre sans assistance, <nom>. Qu'en dites-vous, vous sentez-vous disponible pour partir en chasse ?", progress = nil, completion = "Merci, &lt;nom&gt; ! Le travail que vous avez fait nous sera d'une grande utilité, je le sais.\n\nJe vais continuer mon étude de ce diplomate et des restes des hurans, ici. Si vous cherchez une aventure plus pimentée, trouvez-vous quelques amis et dirigez-vous vers la grotte qui ressemble à une grande gueule de sanglier, par là-bas. Je suis sûr que vous trouverez à l'intérieur des épreuves plus corsées sur lesquelles vous faire les dents.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6627] = {title = "L'épreuve de la Connaissance", objective = "Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses.", description = "Vous m'avez apporté le livre, et maintenant l'heure de la question est venue. Êtes-vous <prêt/prête> ?\n\nLe temps n'est pas un problème, <classe>, inutile de vous presser à répondre.", progress = "La vie est pleine d'interrogations, <classe>. Vous ne pourrez jamais trouver des réponses à toutes, mais avec un peu de temps et de travail, vous gagnerez un peu en connaissances.", completion = "Bien joué, &lt;classe&gt;. Vous avez compulsé le texte que je vous avais demandé d'étudier, et maintenant vous avez passé un autre de nos tests.", rewards = "Vous recevrez :\n\n"},
[6628] = {title = "L'épreuve de la Connaissance", objective = "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Undercity.", description = "Le temps est venu. Vous qui étudiez les savoirs, vous avez fait preuve d'une grande ténacité en menant à bien la mission que je vous avais confiée.\n\nEt maintenant, c'est l'heure de la question. Quand vous sentirez que c'est le bon moment, revenez me parler, et surtout, prenez tout le temps dont vous avez besoin, <nom> : vous n'avez pas à répondre sur-le-champ.", progress = "Je pense qu'il n'y a qu'une seule règle que vous ayez à connaître si vous voulez survivre dans ce monde : plus vous en saurez, plus vous en verrez.\n\nSi vous étudiez, si vous observez, alors vous allez commencer à voir des choses qu'aucun autre ne verra, <nom>.", completion = "Bien joué, &lt;nom&gt;. Vous avez compulsé le texte que je vous avais demandé d'étudier, et maintenant vous avez passé un autre de nos tests.", rewards = "Vous recevrez :\n\n"},
[6629] = {title = "Tuer Grundig Darkcloud", objective = "Tuer Grundig Darkcloud et 6 Brutes du Totem sinistre, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres Rocheuses.", description = "<nom>, vous avez fait un travail magnifique en tuant les membres du Totem sinistre. Grundig Darkcloud et sa bande de brutes personnelles sont de loin les pires de tous. Il était celui qui mena l'attaque sanglante contre mon village.\n\nVous le trouverez au Poste du Totem sinistre, un peu plus haut sur le chemin qui conduit vers l'ouest. Tuez-le et je vous en serai reconnaissant pour toujours.", progress = "Avez-vous tué Grundig Darkcloud et sa troupe de brutes personnelles ?", completion = "Grundig Darkcloud est mort ! &lt;nom&gt;, je vous serais éternellement reconnaissant de ce que vous avez fait aujourd'hui.", rewards = "Vous recevrez :\n\n"},
[6641] = {title = "Vorsha la Flagellante", objective = "Garantir la sécurité de Muglash tandis qu’il voyage vers le brasero. L’aider à éteindre le brasero, puis le protéger, en combattant les nagas.\n\nEn cas de réussite, retourner à l’avant-poste de Zoram'gar et informer le messager Warsong de la mort de Vorsha la Flagellante.", description = "Vorsha la Flagellante... L'hydre diabolique qui erre dans les mers...\n\nElle a attaqué plusieurs fois notre avant-poste, chaque fois de façon délibérée, pour dévaster tout ce qui était sur son chemin.\n\nMais je suis prêt, <nom>. Je me suis préparé à terrasser l'hydre et à mettre fin à ses attaques sur Zoram'gar.\n\nLes nagas honorent cette mauvaise bête en laissant brûler un brasero sur une île au large de la côte. Je crois que si nous l'éteignons, la colère la fera apparaître.\n\nNous aurons besoin d'aide, faites en sorte de ramener des associés puissants.", progress = nil, completion = "J'ai été témoin de nombreuses attaques de nagas, depuis que je suis ici. Ça me tranquillise de savoir que Vorsha ne se promènera plus libre dans les parages.\n\nNous vous sommes redevables, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nAnneau de la corne"},
[6642] = {title = "Faveur auprès de la Confrérie, Minerai de sombre fer", objective = "Le sombre fer, bien qu'il soit répandu dans les Profondeurs, est toujours considéré comme un produit de valeur pour la Confrérie. Les armes sacrées de Ragnaros nécessitent du sombre fer.\n\nPour chaque 10 morceaux de Minerai de sombre fer que vous offrirez, une faveur vous gagnerez.", description = nil, progress = "Le sombre fer, bien qu'il soit répandu dans les Profondeurs, est toujours considéré comme un produit de valeur pour la Confrérie. Les armes sacrées de Ragnaros nécessitent du sombre fer.\n\nPour chaque 10 morceaux de Minerai de sombre fer que vous offrirez, une faveur vous gagnerez.", completion = "Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l'accès aux commerces anciens.", rewards = nil},
[6643] = {title = "Faveur auprès de la Confrérie, Noyau de feu", objective = "Malheur à ceux qui défient le destin au Cœur du Magma ! La mort frappe rapidement ! Le châtiment est sans pitié.\n\nDe nombreux membres de la Confrérie ont disparu en recherchant des Noyaux de feu.\n\nDonnez 1 Noyau de feu et vous obtiendrez une faveur de la part de la Confrérie.", description = nil, progress = "Malheur à ceux qui défient le destin au Cœur du Magma ! La mort frappe rapidement ! Le châtiment est sans pitié.\n\nDe nombreux membres de la Confrérie ont disparu en recherchant des Noyaux de feu.\n\nDonnez 1 Noyau de feu et vous obtiendrez une faveur de la part de la Confrérie.", completion = "Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l'accès aux commerces anciens.", rewards = nil},
[6644] = {title = "Faveur auprès de la Confrérie, Noyau de lave", objective = "La Confrérie du Thorium comprend vos difficultés, <nom>. C'est pour cela que Lokthos a reçu les pleins pouvoirs pour négocier.\n\nDonnez 1 Noyau de lave et vous recevrez une faveur de la part de la Confrérie.", description = nil, progress = "La Confrérie du Thorium comprend vos difficultés, <nom>. C'est pour cela que Lokthos a reçu les pleins pouvoirs pour négocier.\n\nDonnez 1 Noyau de lave", completion = "Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l'accès aux commerces anciens.", rewards = nil},
[6645] = {title = "Faveur auprès de la Confrérie, Cuir du Magma", objective = "Beaucoup de recettes sacrées exigent du cuir des familiers personnels de Ragnaros.\n\nDonnez 2 Cuirs du Magma, provenant du corps des Chiens du Magma, et vous recevrez une faveur de la Confrérie.", description = nil, progress = "Beaucoup de recettes sacrées exigent du cuir des familiers personnels de Ragnaros.\n\n", completion = "Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l'accès aux commerces anciens.", rewards = nil},
[6646] = {title = "Faveur auprès de la Confrérie, Sang de la montagne", objective = "Les larmes du Seigneur du feu sont vraiment très rares.\n\nOffrez 1 Sang de la montagne et une faveur vous sera accordée par la Confrérie.", description = nil, progress = "Les larmes du Seigneur du feu sont vraiment très rares.\n\nOffrez 1 Sang de la montagne et une faveur vous sera accordée par la Confrérie.", completion = "Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l'accès aux commerces anciens.", rewards = nil},
[6661] = {title = "Chasse au rat dans les profondeurs", objective = "Capturer 5 Rats des profondeurs en utilisant le Pipeau du dératiseur. Conduire les Rats vers Monty. N’oubliez pas de rendre le Pipeau quand vous aurez terminé.", description = "Graine de chenapan. Arrrr... Vous nous regardez bosser ? Nous avons un sérieux problème de rats ici et pas assez de mains sur le pont.\n\nVous dites quoi ? Y a qu'à attraper les rats en jouant d'la flûte autour de cette vermine et ils vous suivront au bout du monde !\n\nAttrapez-en juste 5 petits et rapportez-les ici. On en a besoin vivants.\n\nArrrrr...", progress = "Yarrr... Mousse, qu'est-ce qui vous a retardé ?", completion = "Cela convient parfaitement. Mon frère les veut tout gigotants, sans quoi ils ne sont pas bons. On ne peut pas se permettre ça...", rewards = "Vous recevrez :\n\n"},
[6662] = {title = "Mon frère, Nipsy", objective = "Apporter le Carton de viande mystère à Nipsy, au Dépôt du Tram des profondeurs de Stormwind.", description = "Mon frère Nipsy, y gère la fabrication de kébabs de rat à l'aut' bout de la ligne. Faut lui apporter cette caisse de rats avant qu'y se sentent mal. Ça vous dit d'aller, pas vrai !\n\nZ'avez déjà pris le tram avant, oui ? C'est facile. Faut juste sauter dedans quand il arrive, puis apprécier le voyage. Ouais, et oubliez pas garder vos bras et vos pieds à l'intérieur pendant le trajet, si vous voulez pas les perdre.", progress = "<Nipsy enfonce son index dans un des trous d'aération du carton.>\n\nEn vie et en pleine forme... et juste à temps !", completion = "Pauvre Monty. Depuis l'incident de Gnomeregan, il n'est plus le même. Ce garçon n'a jamais vu un océan de sa vie, et c'est encore moins un pirate.\n\n&lt;Nipsy soupire&gt;\n\nAu moins, il continue de nous approvisionner en bestioles grouillantes.", rewards = "Vous recevrez :\n\nKébab de Rat des profondeurs"},
[6681] = {title = "Ravenholdt, le manoir", objective = "Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines d'Hillsbrad.\n\nVotre sagacité sera mise à l’épreuve tout au long de la route. Préparez-vous.", description = "\n\n<nom>, Ravenholdt porte un certain intérêt à vos capacités de jeune <voleur/voleuse>. Nous avons observé : votre style est un peu maladroit, mais rien d'irréparable.\n\nSi vous souhaitez vous engager dans une carrière de disciple de maître Ravenholdt et de membre de la Ligue des Assassins, vous n'avez qu'à apporter le Cachet de Ravenholdt (attaché à cette lettre) au manoir de Ravenholdt.\n\nVotre première tâche est de localiser le manoir, caché dans les collines d'Hillsbrad, afin de démontrer votre ruse.\n\nMes respects, \n\nFahrad.", progress = "Avez-vous rencontré Milton ?\n\n<Fahrad rit.>", completion = "Excellent, jeune larron.\n\nVous avez l'air d'avoir souffert un peu, mais ce n'est pas terminé.\n\nUn long voyage vous attend – long et enrichissant. Voulez-vous enfin saisir votre chance avec les maîtres de Ravenholdt ?\n\nAdressez-vous aux gardes dehors. Ils vous diront quoi faire.", rewards = "Vous recevrez :\n\n"},
[6701] = {title = "Emblèmes du Syndicat", objective = "Nous sommes en guerre avec le Syndicat depuis des années. Ils compensent par leur nombre leur manque de compétences. Nous n'arrivons pas à les tuer assez rapidement pour que cela ait un impact notable sur leur population !\n\nNous avons découvert que le meilleur moyen de gérer leur nombre est de voler leurs Emblèmes. Chaque membre qui la perd est 'puni' en interne.\n\nDétroussez-les et rapportez les Emblèmes à moi ou aux autres Gardes.\n\nCommencez à Durnholde, au sud d'ici.", description = nil, progress = "Nous sommes en guerre avec le Syndicat depuis des années. Ils compensent par leur nombre leur manque de compétences. Nous n'arrivons pas à les tuer assez rapidement pour que cela ait un impact notable sur leur population !\n\nNous avons découvert que le meilleur moyen de gérer leur nombre est de voler leurs Emblèmes. Chaque membre qui la perd est 'puni' en interne.\n\nDétroussez-les et rapportez les Emblèmes à moi ou aux autres Gardes.\n\nCommencez à Durnholde, au sud d'ici.", completion = "Eh ! beau travail. Continuez et les autres voleurs arrêteront peut-être de vous cracher dessus.", rewards = nil},
[6721] = {title = "La voie du chasseur", objective = "Parler à Dazalar, à Dolanaar.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Dazalar, à Dolanaar. Il vous mettra sur la voie, et vous montrera comment avoir votre propre familier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[6722] = {title = "La voie du chasseur", objective = "Parler à Dazalar, à Dolanaar.", description = "Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.\n\nVous devez aller voir Dazalar, à Dolanaar. Il vous mettra sur la voie, et vous montrera comment avoir votre propre familier.", progress = nil, completion = "Oui, il est temps de vous entraîner...", rewards = "Vous recevrez :\n\n"},
[6741] = {title = "Plus de butin !", objective = "J'ai besoin de plus de Morceaux d'armure, <nom> ! Vous en avez ?", description = nil, progress = "J'ai besoin de plus de Morceaux d'armure, <nom> ! Vous en avez ?", completion = "Merci encore, &lt;nom&gt;. La Horde est fière de vous…", rewards = "Vous allez être la cible du sort suivant :\n\nArmure polie"},
[6761] = {title = "La nouvelle frontière", objective = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne de Darnassus.", description = "J’ai fait envoyer mon second, Mathrengyl Bearwalker, pour répondre à l’appel à l’aide de Reflet-de-Lune. C’est à lui que vous devez vous adresser en ce qui concerne cette affaire, PAS à moi.\n\nLaissez-moi vous donner un conseil... amical. C’est moi qui nous ai sortis des ténèbres, PAS le Cercle cénarien de Reflet-de-Lune, et cela alors que tout espoir était perdu pour notre race. Teldrassil nous donne une nouvelle vie ! Ils voudraient que vous pensiez autrement, que vous vous mettiez à croire à leur propagande.\n\nJe vous laisse réfléchir et décider si vous possédez bien toute votre raison.", progress = nil, completion = "Merci de nous avoir rejoint, &lt;classe&gt;. Je suis navré pour ce malentendu... L'air est lourd de la méfiance que se portent l'archidruide et Remulos à Reflet-de-Lune. Chacun suspecte l'autre de tricher et le fait que l'étrange corruption de Teldrassil se perpétue est toujours ici un problème. Cela n'aide pas à apaiser la querelle.\n\nCela dit, nos devoirs envers le Cercle cénarien continuent. Même si les dirigeants ne se font pas confiance.", rewards = "Vous recevrez :\n\n"},
[6762] = {title = "Rabine Saturna", objective = "Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules.", description = "Pour cette tâche, vous devrez assister le majordome du Gardien Remulos, Rabine Saturna, à Reflet-de-Lune. Il a besoin d'aide pour explorer les terres désolées qui se trouvent loin à l’ouest de Tanaris... et encore plus loin, à l'ouest d’Un'Goro. Vous le trouverez à Havrenuit, le village principal de Reflet-de-Lune.\n\nVotre travail, sur place, sera sans aucun doute extraordinairement bénéfique pour nous tous, mais je vous recommande néanmoins d'agir précautionneusement. On a rapporté des tensions entre Darnassus et Reflet-de-Lune... Le genre de tension qui enfle et s'aggrave au fil du temps.", progress = nil, completion = "Je suis Rabine Saturna, et au nom de Remulos et de tous les habitants de ce lieu sacré je vous souhaite la bienvenue.\n\nJ'apprécie votre intérêt envers le Cercle cénarien. Je sais également que l'archidruide de Darnassus est très fâché que vous nous proposiez votre aide. Ce que vous faites est juste et nous vous protégerons contre toutes les répercussions malintentionnées dont vous pourriez être la victime.\n\nVous êtes ici parmi des amis, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[6781] = {title = "Plus de morceaux d'armure !", objective = "<nom>, nous avons besoin de davantage de Morceaux d’armure pour équiper nos troupes !", description = nil, progress = "<nom>, nous avons besoin de davantage de Morceaux d’armure pour équiper nos troupes !", completion = "Ce sont de jolis éléments, &lt;nom&gt;. Je peux les utiliser pour fabriquer de nouveaux équipements pour nos troupes.\n\nSi mes fournitures atteignent un niveau suffisant, peut-être nos troupes aguerries pourront-elles entrer sur le champ de bataille.", rewards = "Vous allez être la cible du sort suivant :\n\nArmure polie"},
[6801] = {title = "Lokholar le Seigneur des Glaces", objective = "Je viens de Thunder Bluff, <nom>. Cairne en personne m’a diligenté afin que j’assiste le clan Frostwolf en ces temps difficiles.\n\nMais ne perdons pas plus de temps. Vous devez abattre nos ennemis et me rapporter un peu de leur sang. Une fois que le sang aura été collecté, le rituel d’invocation pourra commencer.\n\nLa victoire sera certaine lorsque le Seigneur élémentaire sera lâché sur l’armée des Stormpike.", description = nil, progress = "Je viens de Thunder Bluff, <nom>. Cairne en personne m’a diligenté afin que j’assiste le clan Frostwolf en ces temps difficiles.\n\nMais ne perdons pas plus de temps. Vous devez abattre nos ennemis et me rapporter un peu de leur sang. Une fois que le sang aura été collecté, le rituel d’invocation pourra commencer.\n\nLa victoire sera certaine lorsque le Seigneur élémentaire sera lâché sur l’armée des Stormpike.", completion = "Le sang de nos ennemis a été versé. Je vais le mélanger avec celui qui a déjà été récolté. Une fois l’offrande complète, le Seigneur de glace montrera à ces chiens de Stormpike ce qu’est la colère du clan Frostwolf !", rewards = nil},
[6804] = {title = "Eau empoisonnée", objective = "Utiliser l’Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l’est. Apporter 12 Bracelets discordants et l’Aspect de Neptulon au duc Hydraxis, en Azshara.", description = "Une force composée d’éclaireurs élémentaires a été envoyée dans les Maleterres de l’est de Lordaeron, mais la maladie qui a cours là-bas les a contaminés. Les Seigneurs des eaux ne peuvent pas tolérer un tel affront à notre pureté !\n\nPrenez cette fiole. Elle contient l’essence de l’un des aspects de Neptulon. Si elle est utilisée sur les élémentaires pestiférés, son contenu annulera le poison qui les ronge et les guérira ! Mais le conflit intérieur qui les dévore risque de les précipiter dans une folie incontrôlable.\n\nTriomphez des vagues discordantes et rapportez-moi leurs bracelets de liaison.", progress = "Avez-vous les Bracelets ?", completion = "Vous avez bien fait, &lt;classe&gt;. Les élémentaires corrompus que vous avez soignés étaient une insulte à tous les êtres d'eau. Notre pureté est notre force et si nous voulons gagner la guerre, nous devons rester forts.", rewards = "Vous recevrez :\n\n"},
[6805] = {title = "Tempêtes", objective = "Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara.", description = "Nous, les élémentaires d’eau, nous partons en guerre contre les éléments inférieurs et leurs élémentaires. Si vous êtes vraiment de notre côté, faites preuve de votre engagement !\n\nLoin au sud, dans le désert de Silithus, les servants de l’air et de la terre se terrent dans un endroit appelé la vallée des cristaux. Ils protègent des objets puissants de l’appétit des mortels, et bien que j’ignore pourquoi ils font cela, je n’aspire qu’à contrecarrer leurs efforts.\n\nAllez dans la vallée des cristaux, en Silithus, et abattez nos ennemis. Revenez me voir quand cela sera fait.", progress = "La lâcheté n'est pas un sentiment et une attitude que nous apprécions, <classe>. Allez en Silithus et montrez-nous votre bravoure.", completion = "Vous avez prouvé votre valeur et montré que vous étiez digne de notre intérêt. Peut-être pourrai-je vous confier d'autres tâches, plus dignes d'un allié de votre trempe.", rewards = "Vous recevrez :\n\n"},
[6821] = {title = "Oeil du Prophète ardent", objective = "Apporter l’Oeil du Prophète ardent au duc Hydraxis, en Azshara.", description = "Vous m’avez montré que vous pouviez vaincre nos ennemis et réaliser des missions, pour servir la cause des Seigneurs des eaux. Mais jusqu’à maintenant, vous n’avez fait face qu’à des ennemis de second ordre... Comment réagiriez-vous contre des adversaires réellement puissants ?\n\nVoici quelle sera votre prochaine tâche.\n\nDans les hauteurs du pic Blackrock, les orcs ont capturé un servant du feu, le Pyrogarde Prophète ardent. Trouvez l’endroit où il est enfermé, tuez ses gardiens, puis exécutez le Prophète ardent. Rapportez-moi son Oeil ; si vous réussissez, vous m’aurez convaincu de votre valeur.", progress = "Avez-vous l'Œil, <classe> ? Avez-vous la force et le courage pour entrer dans le pic Blackrock ?", completion = "Ah, ainsi vous avez la force requise. Et vous avez aussi la ruse voulue. Car le pic Blackrock demande bien plus que de la force brute.\n\nEn vérité, &lt;nom&gt;, vous pourriez être un allié appréciable...", rewards = "Vous recevrez :\n\n"},
[6822] = {title = "Le Cœur du Magma", objective = "Tuer 1 Seigneur du feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retourner voir le duc Hydraxis, à Azshara.", description = "<nom>, peut-être est-il temps maintenant de vous affronter à une véritable épreuve ; si toutefois vous vous en sentez capable.\n\nAu plus profond des Profondeurs de Blackrock se trouve un passage vers le Cœur du Magma. C’est un bastion utilisé par notre ennemi et tenu par les plus puissants servants du feu qui existent en ce monde.\n\nAllez au Cœur du Magma, <nom>. Montrez-moi que vous avez la force et la volonté de tuer quoi qui puisse se trouver là-bas.\n\nEt si vous avez des alliés ou des amis, n’hésitez pas à les enrôler dans votre périple.Pour survivre à ce qui vous attend dans les abysses du Cœur du Magma, une armée ne sera pas de trop.", progress = nil, completion = "Vous avez fait ce que beaucoup pensaient impossible à réaliser. Vous avez affronté les êtres qui hantaient le Cœur du Magma, et vous les avez vaincus !\n\nPour une si petite créature, vous avez démontré que vous aviez des ressources insoupçonnables.\n\nPeut-être qu'un jour nous ferons de ceux de votre espèce les véritables alliés des Seigneur des eaux.", rewards = "Vous recevrez :\n\n"},
[6823] = {title = "Agent de Hydraxis", objective = "Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara.", description = "Si vous souhaitez réellement nous faire preuve de votre allégeance, je vous invite à partir en guerre contre nos ennemis, les servants de l'air, de la terre et du feu. Chaque défaite que vous leur infligerez réduira l'étreinte qu'ils imposent à ce pays, et chacune de vos victoires nous convaincra un peu plus que vous êtes digne de notre cause.\n\nLa campagne sera longue, mais si vous persévérez, la gloire et l'honneur seront vôtres.", progress = nil, completion = "Vos exploits contre nos ennemis ont retenti dans les chambres des Seigneurs des eaux, &lt;nom&gt;. Certains disent que votre forme est trop petite et fragile pour combattre dans notre guerre, mais vous avez beaucoup gagné. Vous avez gagné notre respect. C'est incroyable.", rewards = "Vous recevrez :\n\n"},
[6824] = {title = "Les mains de l'ennemi", objective = "Apporter les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara.", description = "<nom>, votre service est d'une grande valeur pour nous, et c'est la raison pour laquelle nous sommes quelque peu réticents à vous envoyer sur cette dernière mission. Nous ne voulons pas risquer la vie d'un agent tel que vous.\n\nCependant, le succès de cette mission nous garantirait un avantage significatif dans cette guerre, et nous pensons qu'il est nécessaire que vous risquiez votre vie pour sa réussite.\n\nNous voulons que les capitaines du Cœur du Magma soient exécutés : Lucifron, Sulfuron, Gehennas et Shazzrah. Tuez-les et rapportez-moi leurs Mains !\n\nCette quête est d'une exigence telle qu'elle mobilisera toutes vos ressources, <nom>. Mais si vous réussissez, les Seigneurs du feu auront subi un terrible revers.", progress = "Avez-vous vaincu Lucifron et les autres, <nom> ? Avez-vous récupéré les Mains de nos ennemis ?", completion = "Vous avez les mains ! Les capitaines du feu battus ! Je ne l'aurais pas cru possible, si je n'avais pas su de quoi vous êtes capable.\n\n&lt;nom&gt;, vos exploits sont innombrables, mais cette nouvelle victoire va retentir jusqu'au coeur des Seigneurs des eaux. Votre nom sera un jour une légende pour nous.\n\nRevenez me voir, &lt;nom&gt;. J'aurai peut-être une autre tâche à vous confier...", rewards = "Vous recevrez :\n\n"},
[6825] = {title = "L'appel des airs - l'escadrille de Guse", objective = "Nous devons préparer la nouvelle flotte des Chevaucheurs de guerre, <nom> ! Mes Chevaucheurs sont prêts pour combattre au centre du champ de bataille, mais d’abord nous devons les mettre en appétit et les préparer à l’assaut.\n\nIl me faut suffisamment de chair de soldats Stormpike pour nourrir la flotte ! Des centaines de kilos de viande ! Je suis sûr que vous pouvez vous occuper de ça, n’est-ce pas ?", description = nil, progress = "Nous devons préparer la nouvelle flotte des Chevaucheurs de guerre, <nom> ! Mes Chevaucheurs sont prêts pour combattre au centre du champ de bataille, mais d’abord nous devons les mettre en appétit et les préparer à l’assaut.\n\nIl me faut suffisamment de chair de soldats Stormpike pour nourrir la flotte ! Des centaines de kilos de viande ! Je suis sûr que vous pouvez vous occuper de ça, n’est-ce pas ?", completion = "La flotte se nourrit de leur chair. Cela consume l'ennemi.\n\nLe vol est imminent !", rewards = nil},
[6826] = {title = "L'appel des airs - l'escadrille de Jeztor", objective = "Vous avez bien travaillé, <nom>, mais nous ne faisons que commencer !\n\nMes Chevaucheurs de guerre doivent goûter à la chair de leurs cibles. Cela permettra d’obtenir comme qui dirait une frappe chirurgicale contre nos ennemis !\n\nMa flotte est la seconde plus puissante de toute notre force aérienne. Ce sont eux qui frapperont les plus puissants de nos adversaires. Pour cela, je le répète, il nous faut de la chair des Lieutenants de l'Alliances.\n\nFaites vite !", description = nil, progress = "Vous avez bien travaillé, <nom>, mais nous ne faisons que commencer !\n\nMes Chevaucheurs de guerre doivent goûter à la chair de leurs cibles. Cela permettra d’obtenir comme qui dirait une frappe chirurgicale contre nos ennemis !\n\nMa flotte est la seconde plus puissante de toute notre force aérienne. Ce sont eux qui frapperont les plus puissants de nos adversaires. Pour cela, je le répète, il nous faut de la chair des Lieutenants de l'Alliances.\n\nFaites vite !", completion = "Encore ! Encore ! Il en faut plus car ils seront bientôt prêts !", rewards = nil},
[6827] = {title = "L'appel des airs - l'escadrille de Mulverick", objective = "J’ai subi un emprisonnement inhumain dans ce trou à rats. Vous pouvez me croire quand je vous dis que je n’aspire qu’à la vengeance !\n\nNous devons agir avec prudence, néanmoins.\n\nD’abord, mes Chevaucheurs de guerre ont besoin de cibles, de cibles prioritaires. Je me dois de les nourrir avec la chair des commandants de l'Alliance. Malheureusement, ces petits couards sont retranchés loin derrière leurs lignes. Vous avez du pain sur la planche, on peut le dire !", description = nil, progress = "J’ai subi un emprisonnement inhumain dans ce trou à rats. Vous pouvez me croire quand je vous dis que je n’aspire qu’à la vengeance !\n\nNous devons agir avec prudence, néanmoins.\n\nD’abord, mes Chevaucheurs de guerre ont besoin de cibles, de cibles prioritaires. Je me dois de les nourrir avec la chair des commandants de l'Alliance. Malheureusement, ces petits couards sont retranchés loin derrière leurs lignes. Vous avez du pain sur la planche, on peut le dire !", completion = "Insuffisant ! Ce genre de travail est correct pour un initié, mais vous, &lt;nom&gt; ? En avant, soldat, il faut encore de la chair !", rewards = nil},
[6843] = {title = "Da Foo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6844] = {title = "Umber, Archiviste", objective = "Apporter l’Objet silithide incrusté à Umber, l’archiviste du Cercle cénarien, au village de Havrenuit, à Reflet-de-Lune.", description = "Il reste encore beaucoup à faire ici, mais je pense que la clé est de récupérer ceci afin que le Cercle puisse l’analyser. Croyez-moi, il y aura encore de nombreuses choses à faire une fois que cela sera fait. Si c’est bien un journal sous cette chitine collante, alors le Cercle pourrait s'en servir comme d'une fenêtre vers le passé !\n\nApportez ceci à l’Archiviste du Cercle, à Havrenuit. Son nom est Umber, une personne brillante. Il est un peu dérangé, certes, mais brillant néanmoins. Umber a pu sauver des tomes qui se trouvaient dans un état bien pire que ne l’est celui-là. Si une personne peut faire quelque chose, c’est bien lui.", progress = "Salutations ! Hmm...\n\nLaissez-moi faire preuve d’honnêteté à votre égard… Vous sentez un peu le renfermé, si vous voyez ce que je veux dire. A parler franchement, vous puez comme un rat. Non que je vous en veuille personnellement, mais je vous conseille seulement de vous rincer un peu sous l’eau fraîche d’une cascade la prochaine fois que vous reviendrez du travail. Cela donnera une tournure plus agréable aux moments passés en votre compagnie !\n\nBon, trêve de bavardages, que puis-je faire pour vous ?", completion = "Hé bien ! Qu’est-ce que vous avez là ? On dirait que cela a la forme d'un livre... Je vais essayer de gratter cette croûte pour accéder à l'objet.\n\nLayo vous a fait venir jusqu’à moi depuis Silithus ? Je n’ai entendu que des rumeurs sourdes quant aux horreurs qui ont cours là-bas. A y réfléchir, elles n'étaient pas si sourdes que ça... Ajoutez à tout cela mon aversion pour tout ce qui ressemble de près ou de loin à un insecte, et vous comprendrez que je reste ici, entouré de mes livres !", rewards = "Vous recevrez :\n\n"},
[6845] = {title = "Les secrets du passé", objective = "Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune.", description = "De toute façon, vous aurez à revenir me voir bien assez tôt… si vous voulez savoir ce qui se trouvait là. Dès que j’aurai trouvé de quoi il en retourne et s’il s’agit bien d’un livre, je n’hésiterai pas à partager cette information avec vous.\n\nPendant ce temps-là, à votre place, j’irais voir Rabine qui s’occupe d’un petit campement d’ours. A n’en pas douter, Rabine voudra savoir quelles antiquités incroyables vous avez découvertes. Ne laissez jamais Rabine s’impatienter, <nom>... à moins bien sûr que vous ne vouliez vous retrouver dans une marmite de miel.\n\nC’est déjà arrivé, croyez-moi.", progress = nil, completion = "Ah, &lt;nom&gt;, j'espérais que vous viendriez. J'ai plaisir à vous voir en si bonne forme.\n\nJ'avais entendu dire que vous viendriez et je voulais vous remercier personnellement au nom du Cercle cénarien pour l'aide que vous nous avez apportée jusqu'ici. Il y a sûrement d'autres secrets à découvrir auprès de Silithus ; ce que vous apportez à Umber devrait se monter des plus intéressants. Veuillez accepter ceci en gage de notre reconnaissance.\n\nMerci, généreux &lt;classe&gt; !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau de pierre vivanteAnneau de cristal luminescent\n\nVous recevrez également :\n\n"},
[6846] = {title = "Que l'attaque commence !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6847] = {title = "L'Œil qui voit tout de maître Ryson", objective = "Récupérer l’Oeil-qui-voit-tout de Maître Ryson dans les Grottes Winterax, puis le rapporter à Maître Ryson.\n\nSachez que l’on dit de l’Oeil-qui-voit-tout de Maître Ryson qu’il contient une terrible malédiction !", description = "Votre guerre dans le cœur d’Alterac ne signifie rien pour le Syndicat, <classe>. Nous ferons comme nous avons toujours fait : attendre jusqu’à ce qu’une opportunité claire de victoire émerge des cendres et des décombres, puis frapper.\n\nCe n’est pas pour cela, cependant, que nous sommes là aujourd’hui. L’Oeil-qui-voit-tout a été volé par les trolls Winterax de la région.\n\nRécupérez l’Oeil et nous nous mettrons à votre service.\n\nRevenez me voir, une fois que l’Oeil est en votre possession, et puis je réfléchirai à la question.\n\n<Maître Ryson sourit.>Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[6848] = {title = "L'Œil qui voit tout de maître Ryson", objective = "Récupérer l’Oeil-qui-voit-tout de Maître Ryson dans les Grottes Winterax, puis le rapporter à Maître Ryson.\n\nSachez que l’on dit de l’Oeil-qui-voit-tout de Maître Ryson qu’il contient une terrible malédiction !", description = "Votre guerre dans le cœur d’Alterac ne signifie rien pour le Syndicat, <classe>. Nous ferons comme nous avons toujours fait : attendre jusqu’à ce qu’une opportunité claire de victoire émerge des cendres et des décombres, puis frapper.\n\nCe n’est pas pour cela, cependant, que nous sommes là aujourd’hui. L’Oeil-qui-voit-tout a été volé par les trolls Winterax de la région.\n\nRécupérez l’Oeil et nous nous mettrons à votre service.\n\nRevenez me voir, une fois que l’Oeil est en votre possession, et puis je réfléchirai à la question.\n\n<Maître Ryson sourit.>Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[6861] = {title = "Le Déchiqueteur portable de Zinfizzlex", objective = "Le Maître Ingénieur Zinfizzlex veut que vous lui apportiez les matériaux suivants :\n\n*30 Barres de thorium.\n\n*50 Barres de Mithril.\n\n*75 Barres de fer.\n\n*1 Scie mécanique.", description = "J’ai hâte de faire l’essai de mon Déchiqueteur portable, <nom>, mais avant que je ne puisse fabriquer le kit, j’ai besoin de beaucoup de matériel !\n\nPour être précis, il me faut une montagne de thorium, de mithril et de fer. J’aurai également besoin d’une Scie mécanique par unité. Vous les trouverez à la scierie.\n\nAlors que je traînais dans les environs (avant ma capture) j’ai remarqué une pile de Scies mécaniques, au Camp de bûcherons des Stormpike.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nDéchiqueteur portable de Zinfizzlex"},
[6862] = {title = "Le Déchiqueteur portable de Zinfizzlex", objective = "Le Maître Ingénieur Zinfizzlex veut que vous lui apportiez les matériaux suivants :\n\n*30 Barres de thorium.\n\n*50 Barres de Mithril.\n\n*75 Barres de fer.\n\n*1 Scie mécanique.", description = "J’ai hâte de faire l’essai de mon Déchiqueteur portable, <nom>, mais avant que je ne puisse fabriquer le kit, j’ai besoin de beaucoup de matériel !\n\nPour être précis, il me faut une montagne de thorium, de mithril et de fer. J’aurai également besoin d’une Scie mécanique par unité. Vous les trouverez à la scierie.\n\nAlors que je traînais dans les environs (avant ma capture), j’ai remarqué une pile de Scies mécaniques au Camp de bûcherons de Frostwolf.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nDéchiqueteur portatif de Zinfizzlex"},
[6881] = {title = "Ivus le Seigneur des forêts", objective = "Le clan Frostwolf est protégé par un poison constitué d'énergie élémentaire. Leurs chamans ont développé des pouvoirs qui nous détruiront jusqu'au dernier, si on laisse les choses suivre leur cours.\n\nLa menace est maintenant trop importante pour le Cercle. Ivus doit être appelé à l'aide.\n\nLes soldats Frostwolf portent des charmes élémentaires, appelés Cristaux de tempête. Nous pouvons utiliser ces charmes pour invoquer Ivus. Partez maintenant et récupérez ces cristaux, <nom> !", description = nil, progress = "Le clan Frostwolf est protégé par un poison constitué d'énergie élémentaire. Leurs chamans ont développé des pouvoirs qui nous détruiront jusqu'au dernier, si on laisse les choses suivre leur cours.\n\nLa menace est maintenant trop importante pour le Cercle. Ivus doit être appelé à l'aide.\n\nLes soldats Frostwolf portent des charmes élémentaires, appelés Cristaux de tempête. Nous pouvons utiliser ces charmes pour invoquer Ivus. Partez maintenant et récupérez ces cristaux, <nom> !", completion = "Bien joué, &lt;nom&gt;. Je vais me servir du pouvoir de ce charme pour augmenter la magie qui a déjà été collectée. Lorsque nous aurons assez de puissance, je focaliserai les énergies et j’appellerai le Seigneur des forêts pour aider notre cause.", rewards = nil},
[6901] = {title = "Lancez l'attaque !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6921] = {title = "Parmi les ruines", objective = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", description = "Le Marteau du crépuscule s'est déplacé dans les ruines d'Ecrin-de-Lune des Profondeurs de Brassenoire. Leur présence forcera les élémentaires à travailler contre nous. Si nous ne nous occupons pas de cette région, ils en prendront complètement le contrôle.\n\n<nom>, allez à Brassenoire et trouvez la pierre de la brasse. Elle devrait se trouver quelque part, à proximité, dans l'eau. À l'intérieur, se trouve un Noyau de la Brasse, un objet qui, s'il est utilisé correctement, offrira un historique de toute l'activité des élémentaires. Si je l'avais, je pourrais, avec l'aide du Cercle terrestre, faire quelque chose pour les arrêter !", progress = "Avez- vous réussi à localiser le Noyau de la Brasse ? Sans lui nous n'aurons aucune idée de l'emplacement précis du Marteau du crépuscule.", completion = "C'est exactement ce dont j'avais besoin ! C'est une incroyable source d'informations dont nous tirerons beaucoup de bien. Quel que soit le maléfice secret du Marteau du crépuscule, croyez-moi, mes camarades et moi saurons bientôt tout !\n\nVous avez bien agi, et le Cercle terrestre souhaite vraiment que vous nous aidiez ! Vous avez également aidé la Horde toute entière et vous avez toutes les raisons d'éprouver de la fierté.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6922] = {title = "Baron Aquanis", objective = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", description = "Sur l'élémentaire d'eau vaincu, vous trouvez un étrange globe d'eau. Vous avez la nette impression que l'objet a absorbé l'énergie de la créature. À l'intérieur du globe, vous discernez une eau aux reflets malsains. Le globe lui-même semble insensible à toute forme d'action physique.\n\nS'il y a une personne qui puisse comprendre ce qu'est cet objet, cela ne peut être que Je'neu Sancrea du Cercle terrestre. Il se trouve dans l'avant-poste de Zoram'gar de la Horde, à Ashenvale.", progress = "Ah, bonjour, <nom>. Je contemplais les vagues dans l'eau, comme j'ai l'habitude de le faire. Qu'est-ce qui vous amène à l'avant-poste ?", completion = "C'est... C'est une sacrée trouvaille, &lt;nom&gt;.\n\nVous avez acquis ceci auprès du baron Aquanis, à Brassenoire, dites-vous ? Le baron Aquanis a longtemps été considéré comme un élémentaire corrompu, ce globe montrera exactement ce qui l'a souillé. Ce ne sera pas une surprise si l'on découvre que c'est le Marteau du crépuscule, mais nous découvrirons également comment cela s'est passé.\n\nVous avez bien fait de m'apporter ceci. Veuillez prendre ça, ainsi que la gratitude sincère du Cercle terrestre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSabre des hors-la-loiDoigt de la sorcière\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[6941] = {title = "L'appel des airs - l'escadrille de Vipore", objective = "Les troupes d'élite de la Horde en faction sur la ligne de front doivent être engagées ! Je vous demande de tailler dans cette bande de sauvages et d'en faire chuter les effectifs. Revenez me voir avec les Médailles de leurs Lieutenants et de leurs Légionnaires. Lorsque un nombre suffisant de cette racaille aura étouffé dans son propre sang, je ferai déployer la force aérienne.", description = nil, progress = "Les troupes d'élite de la Horde en faction sur la ligne de front doivent être engagées ! Je vous demande de tailler dans cette bande de sauvages et d'en faire chuter les effectifs. Revenez me voir avec les Médailles de leurs Lieutenants et de leurs Légionnaires. Lorsque un nombre suffisant de cette racaille aura étouffé dans son propre sang, je ferai déployer la force aérienne.", completion = "Le vol sera bientôt prêt. Continuez vos efforts !", rewards = nil},
[6942] = {title = "L'appel des airs - l'escadrille de Slidore", objective = "Mes gryphons sont en place pour donner l'assaut frontal, mais ils ne peuvent pas le faire tant que les rangs ennemis n'auront pas été réduits préalablement.\n\nLes guerriers de la Horde chargés de tenir la ligne de front portent des Médailles qu'ils arborent fièrement sur leurs poitrines. Arrachez ces Médailles à leurs cadavres et rapportez-les-moi.\n\nUne fois que les effectifs ennemis de la ligne de front auront été suffisamment réduits, je ferai donner la force aérienne !", description = nil, progress = "Mes gryphons sont en place pour donner l'assaut frontal, mais ils ne peuvent pas le faire tant que les rangs ennemis n'auront pas été réduits préalablement.\n\nLes guerriers de la Horde chargés de tenir la ligne de front portent des Médailles qu'ils arborent fièrement sur leurs poitrines. Arrachez ces Médailles à leurs cadavres et rapportez-les-moi.\n\nUne fois que les effectifs ennemis de la ligne de front auront été suffisamment réduits, je ferai donner la force aérienne !", completion = "Il faut que ça entre, soldat ! Les gryphons du Nid-de-l'Aigle seront prêts à frapper en un rien de temps !", rewards = nil},
[6943] = {title = "L'appel des airs - l'escadrille d'Ichman", objective = "Leur moral est au plus bas. Depuis l'échec cuisant de notre dernière attaque aérienne contre la Horde, ils refusent de voler ! C'est à vous maintenant de remonter leur moral.\n\nRetournez sur le champ de bataille et frappez le coeur du commandement de la Horde. Abattez leurs commandants et leurs gardiens. Revenez me voir quand vous aurez récupéré autant de Médailles que peut en contenir votre sac ! Je vous promets que lorsque mes gryphons verront ce butin et qu'ils sentiront l'odeur de leur sang sur les Médailles, ils seront prêts à reprendre le combat. Partez maintenant !", description = nil, progress = "Leur moral est au plus bas. Depuis l'échec cuisant de notre dernière attaque aérienne contre la Horde, ils refusent de voler ! C'est à vous maintenant de remonter leur moral.\n\nRetournez sur le champ de bataille et frappez le coeur du commandement de la Horde. Abattez leurs commandants et leurs gardiens. Revenez me voir quand vous aurez récupéré autant de Médailles que peut en contenir votre sac ! Je vous promets que lorsque mes gryphons verront ce butin et qu'ils sentiront l'odeur de leur sang sur les Médailles, ils seront prêts à reprendre le combat. Partez maintenant !", completion = "Vous ne voyez pas ? Regardez, soldat ! Ils approchent ! Bientôt, l'escadrille d'Ichman frappera de nouveau au coeur de la vallée ! Les Stormpike régneront dans les cieux !", rewards = nil},
[6961] = {title = "Grand-père Hiver est ici !", objective = "Parler à Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar.", description = "Joyeuse fête du Voile d'hiver, <l'ami/l'amie> ! Assurez-vous d'aller passer le bonjour au Grand-père Hiver ! Si vous avez été sage cette année, vous recevrez de merveilleuses friandises le jour de la fête du Voile d'hiver. N'oubliez pas de dire au Grand-père Hiver ce que vous espérez recevoir cette année !\n\nN'oubliez pas non plus de faire des réserves de friandises à distribuer, à tous ceux qui ont été méritants cette année. Nous avons une grande sélection de douceurs dans laquelle choisir. Tout frais de notre ferme, directement dans votre assiette. C'est bon, c'est sain, ce sont les Gourmandises Fumebois !", progress = nil, completion = "Ho ho, bien le bonjour. Je suis Grand-père Hiver, et je voudrais, avec l'appui de tout le personnel des Gourmandises Fumebois, \"Tout frais de notre ferme, droit dans votre assiette, voilà tous les plaisirs sains des Gourmandises Fumebois\", vous souhaiter une fantastique fête du Voile d'hiver.\n\nSi vous avez été sage cette année, vous recevrez certainement des Gourmandises Fumebois en guise de cadeau de Voile d'hiver. Hourrah.", rewards = "Vous recevrez :\n\n"},
[6962] = {title = "Des friandises pour Grand-père Hiver", objective = "Apporter 5 Biscuits au pain d'épices et un Verre de lait glacé au Grand-père Hiver, à Orgrimmar.", description = "Hé, <jeune homme/jeune fille>, pourriez-vous rendre au Grand-père Hiver un petit service ? Ce n'est pas que je me complaise à parler de moi à la troisième personne, mais le Grand-père Hiver a été sur le métier toute la journée, et s'octroierait lui-même volontiers une de ces friandises. Quelques Biscuits au pain d'épices et un Verre de lait glacé pour faire descendre le tout seraient les bienvenus. Pourriez-vous être <un ami/une amie> pour le Grand-père, et me trouver tout ça ?", progress = "Toutes ces discussions sur les friandises m'ont quelque peu ouvert l'appétit. Mmmmm…des Biscuits au pain d'épices et du lait…", completion = "Vous avez été d'une aide précieuse au vieux Grand-père Hiver, ici présent, &lt;nom&gt;. Joyeuse fête du Voile d'hiver à vous.\n\nVoilà un petit quelque chose…vous savez, pour l'effort.", rewards = "Vous recevrez :\n\nPaquet-cadeau de Gourmandises Fumebois"},
[6963] = {title = "Friandises volées de la fête du Voile d'hiver", objective = "Trouver l'enquêteur des Gourmandises Fumebois qui est porté disparu dans les montagnes d'Alterac.", description = "Écoutez... ce n'est pas que je prenne du plaisir à ruiner la magie du moment, mais les Gourmandises Fumebois pourraient bien avoir besoin d'aide ; le genre d'aide que vous, les gens aux caractère aventureux, avez la réputation d'apporter volontiers aux nécessiteux.\n\nUn important chargement de friandises que nous nous apprêtions à stocker pour la saison a été signalé manquant, et maintenant, l'agent que nous avions dépêché sur le terrain pour mener l'enquête est lui aussi porté disparu ! Je vous en prie ; le chargement a été aperçu pour la dernière fois dans les montagnes d'Alterac, et c'est là que notre homme s'est rendu pour le trouver.\n\nVoyez si tous deux se trouvent là-bas, et en bonne forme !", progress = nil, completion = "V-v-vous pouvez m'ent-t-tendre ! La providence soit louée !\n\nJe n-ne suis pas vraiment un b-b-bonhomme de neige - mon n-n-nom est Sacks et je travaille pour la b-b-branche d'Orgrimmar des Gourmandises Fumebois…On m-m-m'a envoyé ici pour récupérer un paquet manquant, q-q-quand j'ai été attaqué p-p-par une c-c-créature que je n'avais jamais vue jusqu'ici !\n\nJ'ai t-t-tellement f-froid...", rewards = "Vous recevrez :\n\n"},
[6964] = {title = "L'esprit de cette fête", objective = "Parler à Sagorne Crestrider, dans la Vallée de la Sagesse d'Orgrimmar, au sujet de la fête du Voile d'hiver.", description = "Des cadeaux, des friandises, des présents...pouah ! Voilà tout ce que j'ai à en dire !\n\nCes gobelins pourrissent le sens véritable de cette saison ; la fête du Voile d'hiver. C'est une période de renouveau, pendant laquelle la terre sommeille paisiblement, sous un épais manteau blanc, déposé là par Grand-père Hiver. Ce dernier ne saurait être en AUCUN cas le crétin rabâcheur, là-bas, dans son costume rouge !\n\nSi vous désirez connaître le sens véritable de cette fête, questionnez donc Sagorne Crestsrider. Je suis sûr qu'il sera surpris que quelqu'un se soucie plus de cette histoire que de recevoir des cadeaux.", progress = nil, completion = "La fête du Voile d'hiver, dites-vous ? Ah, par le passé, cette fête avait un sens beaucoup plus profond pour nous, le peuple tauren. De nos jours, il semble que certaines personnes aient trouvé une occasion de transformer la légende de cette saison de renouveau en fonds de commerce.\n\nQu'un tel changement rende Furmund amer ne me surprend pas le moins du monde. Les taurens de son genre font de notre passé leur cheval de bataille. Je pense cependant qu'une petite célébration est bonne ; il est important de se remémorer les origines de cette fête.", rewards = "Vous recevrez :\n\n"},
[6981] = {title = "L'Eclat luminescent", objective = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.\n\nPuis livrez l'Eclat, selon les instructions.", description = "L'éclat est d'un vert brillant, et bien que compact, ce qui ressemble à de la fumée tourbillonne juste au-dessous de sa surface. Vous ne pouvez vous empêcher de contempler les profondeurs du cristal, bien qu'en même temps, vous sentiez qu'il y réside quelque chose de très inquiétant.\n\nPeut-être devriez-vous voir si quelqu'un à Ratchet pourrait vous en apprendre plus à propos de cet étrange éclat...", progress = "Bonjour, <nom>. Que puis-je faire pour vous ?", completion = "Oh... Je n'avais jamais rien vu de tel...", rewards = "Vous recevrez :\n\n"},
[6982] = {title = "Fournitures de Froide-dent", objective = "Apporter 10 Fournitures de Froide-dent à l'intendant de l’Alliance, à Dun Baldar.", description = "La mine de Froide-dent est un dépôt de stockage de la Horde. Je ne supporte pas la nourriture qu'ils donnent à leurs troupes, et leurs armes et armures sont dans un état atroce ! Mais... dans des temps pareils, quand les fournitures sont d'une importance capitale, tout cela peut quand même nous être utile.\n\nEntrez dans la mine de Froide-dent et rapportez-moi leur matériel. Cela aidera l'Alliance à rester à même de se battre, et privera les guerriers de la Horde d'équipement dont ils auraient bien besoin.\n\nBonne chance, <nom>. La mine est au sud, loin dans le territoire de la Horde.", progress = "Êtes-vous entré dans la mine de Froide-dent dans le territoire de la Horde, <nom> ?  Avez-vous pillé leurs fournitures ?", completion = "Vous les avez ! Bien joué, &lt;nom&gt; ! Je vais examiner ces fournitures et les préparer pour nos propres troupes !", rewards = "Vous recevrez :\n\n"},
[6983] = {title = "La méchanceté vous habite...", objective = "Localiser les friandises, et les ramener à Kaymard Copperpinch, à Orgrimmar. C'est l'abominable Grinche, vivant quelque part dans les régions enneigées des montagnes d'Alterac, qui les détiendrait.", description = "Une c-c-créature que l'on appelle \"l'abominable Grinche\" sévit par ici, c'est lui qui nous a dérobé notre cargaison de f-f-friandises, <nom>. Restez sur vos g-g-gardes ! C'est aussi lui qui m'a transformé en ce brouillon de bonhomme de neige !\n\nV-v-vous allez avoir besoin d-d-d'aide pour lui tenir front. Je l'ai vu se p-p-promener un peu partout où on trouve des yétis. I-i-il est certainement quelque part dans les environs ! T-t-trouvez les friandises, <nom>, r-r-ramenez-les aux Gourmandises Fumebois d'Orgrimmar, et dites-leur q-q-que j'ai besoin qu'on vienne me d-d-dégeler !", progress = "<nom>, notre fête du Voile d'hiver va être une catastrophe sans ces friandises ! Graccu lui-même ne pourra pas partager ses succulentes tourtes à la viande avec les gens qui les ont méritées, cette année…", completion = "Vous avez trouvé le chargement ! Vous avez sauvé la fête du Voile d'hiver des Gourmandises Fumebois !\n\nPauvre Sacks… Nous allons faire en sorte de le dégeler. Il sera certainement de retour à temps pour le jour de la fête ; cependant, il aura du travail en retard à rattraper. Une fois encore, rien de tout cela ne serait possible sans votre aide !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[6984] = {title = "Un grand merci des Gourmandises Fumebois !", objective = "Parler à Grand-père Hiver à Orgrimmar.", description = "Les Gourmandises Fumebois apprécient sincèrement que vous ayez retrouvé les friandises volées, <nom>. En signe de notre gratitude, nous aimerions vous offrir quelque chose de spécial... un présent remis par le Grand-père Hiver en personne !\n\nS'il vous plaît, allez parler à Grand-père Hiver, il vous donnera de notre part un cadeau de fête du Voile d'hiver. De notre ferme droit dans votre assiette, c'est bon, c'est sain, ce sont les Gourmandises Fumebois...Oh ! Et un grand merci à vous, bien sûr !", progress = nil, completion = "Ho ho, bien le bonjour, aventurier !\n\nLes gobelins m'ont dit que vous aviez gagné un cadeau spécial, en cette heureuse saison, et je suis enchanté de vous le remettre personnellement. Voilà ; je vous souhaite une merveilleuse fête du Voile d'hiver, pour cette année et toutes les années à venir.", rewards = "Vous recevrez :\n\nCadeau spécial des Gourmandises Fumebois"},
[6985] = {title = "Fournitures de Gouffrefer", objective = "Apporter 5 Fournitures de Gouffrefer à l'Intendant de la Horde, au donjon Frostwolf.", description = "Les nains Stormpike se servent de la mine de Gouffrefer pour stocker leurs réserves. Pillez-la, rapporter-moi leurs fournitures. Cela ralentira leurs efforts dans la vallée d’Alterac, et nous donnera l’équipement dont nous avons besoin !\n\nFaites attention, <nom>. La mine de Gouffrefer se trouve loin dans le territoire de l’Alliance, et elle a changé de mains maintes et maintes fois.", progress = "Êtes-vous entré dans la mine de Gouffrefer, <nom>?  Avez-vous pillé les fournitures ?", completion = "Vous les avez ! Bien joué, &lt;nom&gt; ! J'espère que vous avez vu quelques nains pendant votre raid et que vous avez versé leur sang pour les Frostwolf !", rewards = "Vous recevrez :\n\n"},
[7001] = {title = "Ecuries vides", objective = "Trouvez un Loup des glaces dans la vallée d’Alterac. Servez-vous de la Muselière de loup des glaces pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu’au Maître des écuries Frostwolf. Parlez au Maître des écuries Frostwolf pour être crédité de cette capture.", description = "La guerre dans la vallée a coûté cher à nos soldats. Nous devons stimuler nos forces !\n\nSi nous pouvons remplir les écuries, nos Chevaucheurs de loups pourront se joindre à nouveau à la bataille.\n\nPrenez cette muselière et traquez les loups des glaces qui vivent dans la forêt voisine. Lorsque vous en trouverez un, servez-vous de la muselière pour le dompter.\n\nLorsqu’il y aura assez de loups dans l’écurie, les Chevaucheurs de loups recommenceront à patrouiller sur nos lignes.", progress = "Sans votre aide, les chevaucheurs de loups Frostwolf n'auraient pas de montures à chevaucher. Vous nous avez rendu un grand service !", completion = "J’espère que ceux qui doivent récolter les peaux de bélier sont aussi déterminés que vous, &lt;nom&gt;.\n\nA ce rythme, les écuries seront pleines dans quelques heures !", rewards = nil},
[7002] = {title = "Harnais en cuir de bélier", objective = "Certains de nos soldats sont occupés à capturer des loups pour le maître des écuries. D’autres doivent nous fournir les accessoires nécessaires à la monte. Je parle des harnais, bien sûr.\n\nVous devez vous procurer les matières premières sur les béliers de la région. Oui, ceux-là même que les Stormpike utilisent comme montures !\n\nTuez-les et ramenez-moi leurs peaux. Lorsque vous en aurez assez, nous fabriquerons des harnais, et les Chevaucheurs de loups Frostwolf entreront dans la bataille !", description = nil, progress = "Certains de nos soldats sont occupés à capturer des loups pour le maître des écuries. D’autres doivent nous fournir les accessoires nécessaires à la monte. Je parle des harnais, bien sûr.\n\nVous devez vous procurer les matières premières sur les béliers de la région. Oui, ceux-là même que les Stormpike utilisent comme montures !\n\nTuez-les et ramenez-moi leurs peaux. Lorsque vous en aurez assez, nous fabriquerons des harnais, et les Chevaucheurs de loups Frostwolf entreront dans la bataille !", completion = "Bon travail, soldat. Je vous dirai quand nous aurons assez de ces peaux.\n\nContinuez !", rewards = nil},
[7003] = {title = "Géants rétrécis", objective = "Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 15 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas.", description = "Il va falloir que je fasse quelque chose pour ces géants si je reste ici ! Ils ne sont vraiment pas bons pour les affaires !\n\nJ'ai travaillé sur une variante de rayon rétrécissant gnome, mais j'ai utilisé les avancées technologiques supérieures des GOBELINS pour sa construction ! Afin de m'éviter de possibles désagréments tels que la mort, j'aimerais que vous alliez l'essayer sur n'importe lequel des géants en Feralas. Vous devriez trouver des résidus de miniaturisation sur eux après les avoir rétrécis. Rapportez-m'en !", progress = "Les résidus de miniaturisation, je vous l'assure, sont très utiles aux ingénieurs ! Ils me permettent de m'assurer que la baguette ne va pas donner des résultats décevants, comme exploser au nez de l'utilisateur.\n\nOh, mais je voulais parler des baguettes autres que celle que je vous ai donnée. Absolument !", completion = "Ébouristouflant ! Je suis très heureux de vous voir revenir non seulement avec les résidus, mais aussi avec tous vos membres ! Euh... mais non, il n'y a jamais eu aucun danger à se servir de l'Ultra-réducteur, évidemment !\n\nJe vous suis très reconnaissant, &lt;nom&gt;. Vous êtes l'ami de tous les gobelins. Acceptez ceci en gage de ma gratitude !", rewards = "Vous recevrez :\n\nMéga-trancheur de Zorbin"},
[7021] = {title = "Grand-père Hiver est ici !", objective = "Parler à Grand-père Hiver ; il se trouve près des Gourmandises Fumebois, à Orgrimmar.", description = "Joyeuse fête du Voile d'hiver, <l'ami/l'amie> ! Assurez-vous d'aller passer le bonjour au Grand-père Hiver, qui se trouve actuellement à Orgrimmar ! Si vous avez été sage cette année, vous recevrez de merveilleuses friandises le jour de la fête du voile d'hiver. N'oubliez pas de dire au Grand-père Hiver ce que vous espérez recevoir cette année !\n\nN'oubliez pas non plus de faire des réserves de friandises à distribuer à tous ceux qui ont été méritants cette année. Nous avons une grande sélection de douceurs dans laquelle choisir. Tout frais de la ferme, directement dans votre assiette. C'est bon, c'est sain, ce sont les Gourmandises Fumebois !", progress = nil, completion = "Ho ho, bien le bonjour. Je suis Grand-père Hiver, et je voudrais, avec l'appui de tout le personnel des Gourmandises Fumebois, \"Tout frais sorti de notre ferme, droit dans votre assiette, voilà tous les plaisirs sains des Gourmandises Fumebois\", vous souhaiter une fantastique fête du Voile d'hiver.\n\nSi vous avez été sage cette année, vous recevrez certainement des Gourmandises Fumebois en guise de cadeau de fête du Voile d'hiver. Hourra.", rewards = "Vous recevrez :\n\n"},
[7022] = {title = "Grandpère Hiver est ici !", objective = "Parler à Grandpère Hiver ; il se trouve près des Gourmandises Fumebois, à Ironforge.", description = "Joyeuse fête du Voile d'hiver, <l'ami/l'amie> ! Assurez-vous d'aller passer le bonjour au Grandpère Hiver ! Si vous avez été sage cette année, vous recevrez de merveilleuses friandises le jour de la fête du Voile d'hiver. N'oubliez pas de dire au Grandpère Hiver ce que vous espérez recevoir cette année !\n\nN'oubliez pas non plus de faire des réserves de friandises à distribuer à tous ceux qui ont été méritants cette année. Nous avons une grande sélection de douceurs dans laquelle choisir. Tout frais de la ferme, directement dans votre assiette. C'est bon, c'est sain, ce sont les Gourmandises Fumebois !", progress = nil, completion = "Ho ho, bien le bonjour. Je suis Grandpère Hiver et je voudrais, avec l'appui de tout le personnel des Gourmandises Fumebois, \"Tout frais de notre ferme, droit dans votre assiette, ce sont les Gourmandises Fumebois\", vous souhaiter une fantastique fête du Voile d'hiver.\n\nSi vous avez été sage cette année, vous recevrez certainement des Gourmandises Fumebois en guise de cadeau de fête du Voile d'hiver. Houra.", rewards = "Vous recevrez :\n\n"},
[7023] = {title = "Grandpère Hiver est ici !", objective = "Parler à Grandpère Hiver ; il se trouve près des Gourmandises Fumebois, à Ironforge.", description = "Joyeuse fête du Voile d'hiver, <l'ami/l'amie> ! Assurez-vous d'aller passer le bonjour au Grandpère Hiver, qui se trouve actuellement à Ironforge ! Si vous avez été sage cette année, vous recevrez de merveilleuses friandises le jour de la fête du Voile d'hiver. N'oubliez pas de dire au Grandpère Hiver ce que vous espérez recevoir cette année !\n\nN'oubliez pas non plus de faire des réserves de friandises à distribuer à tous ceux qui ont été méritants cette année. Nous avons une grande sélection de douceurs dans laquelle choisir. Toutes fraîches de la ferme, directement dans votre assiette. C'est bon, c'est sain, ce sont les Gourmandises Fumebois !", progress = nil, completion = "Ho ho, bien le bonjour. Je suis Grandpère Hiver et je voudrais, avec l'appui de tout le personnel des Gourmandises Fumebois \"Tout frais de notre ferme, droit dans votre assiette, voilà tous les plaisirs sains des Gourmandises Fumebois\", vous souhaiter une fantastique fête du Voile d'hiver.\n\nSi vous avez été sage cette année, vous recevrez certainement des Gourmandises Fumebois en guise de cadeau de fête du Voile d'hiver. Hourra.", rewards = "Vous recevrez :\n\n"},
[7024] = {title = "Grand-père Hiver est ici !", objective = "Parler à Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar.", description = "Joyeuse fête du Voile d'hiver, <l'ami/l'amie> ! Assurez-vous d'aller passer le bonjour au Grand-père Hiver, qui se trouve actuellement à Orgrimmar ! Si vous avez été sage cette année, vous recevrez de merveilleuses friandises, le jour de la fête du Voile d'hiver. N'oubliez pas de dire au Grand-père Hiver ce que vous espérez recevoir cette année !\n\nN'oubliez pas non plus de faire des réserves de friandises à distribuer à tous ceux qui ont été méritants cette année. Nous avons une grande sélection de douceurs dans laquelle choisir. Tout frais de la ferme, directement dans votre assiette. C'est bon, c'est sain, ce sont les Gourmandises Fumebois !", progress = nil, completion = "Ho ho, bien le bonjour. Je suis Grand-père Hiver et je voudrais, avec l'appui de tout le personnel des Gourmandises Fumebois, \"Tout frais de notre ferme, droit dans votre assiette, c'est tout le plaisir sain des Gourmandises Fumebois\", vous souhaiter une fantastique fête du Voile d'hiver.\n\nSi vous avez été sage cette année, vous recevrez certainement des Gourmandises Fumebois en guise de cadeau de fête du Voile d'hiver. Hourra.", rewards = "Vous recevrez :\n\n"},
[7025] = {title = "Des friandises pour Grandpère Hiver", objective = "Apporter 5 Biscuits au pain d'épices et un verre de Lait glacé au Grandpère Hiver à Ironforge.", description = "Hé, <jeune homme/jeune fille>, pourriez-vous rendre au Grandpère Hiver un petit service ? Ce n'est pas que je me complaise à parler de moi à la troisième personne, mais le Grandpère Hiver a été sur le métier toute la journée, et s'octroierait lui-même volontiers une de ces friandises. Quelques biscuits au pain d'épices et un verre de lait glacé pour faire descendre le tout seraient les bienvenus. Pourriez-vous être <un ami/une amie> pour le Grandpère et me trouver tout ça ?", progress = "Toutes ces discussions sur les friandises m'ont quelque peu ouvert l'appétit. Mmmmm…des biscuits au pain d'épices et du lait…", completion = "Vous avez été d'une grande aide pour le vieux Grandpère Hiver ici présent, &lt;nom&gt;. Je vous souhaite une merveilleuse fête du Voile d'hiver.\n\nVoici un petit quelque chose... vous savez, pour vous récompenser de vos efforts.", rewards = "Vous recevrez :\n\nPaquet-cadeau de Gourmandises Fumebois"},
[7026] = {title = "Harnais pour béliers", objective = "La brigade Stormpike ne peut pas charger à cru ! Il nous faut des harnais pour nos montures. Après tout, nous ne sommes pas des sauvages.\n\nNous pourrions tuer les béliers qui s'aventurent près de notre base pour fabriquer ces harnais, mais ce serait idiot : nous en avons besoin comme montures.\n\nVous devez attaquer la base ennemie, tuer leurs loups de monte et prendre leur peaux. Ramenez-les-moi, et nous en ferons des harnais pour la cavalerie. Allez !", description = nil, progress = "La brigade Stormpike ne peut pas charger à cru ! Il nous faut des harnais pour nos montures. Après tout, nous ne sommes pas des sauvages.\n\nNous pourrions tuer les béliers qui s'aventurent près de notre base pour fabriquer ces harnais, mais ce serait idiot : nous en avons besoin comme montures.\n\nVous devez attaquer la base ennemie, tuer leurs loups de monte et prendre leur peaux. Ramenez-les-moi, et nous en ferons des harnais pour la cavalerie. Allez !", completion = "Bon travail, soldat. Je vous dirai quand nous aurons assez de ces peaux.\n\nContinuez !", rewards = nil},
[7027] = {title = "Écuries vides", objective = "Trouvez un Bélier d'Alterac dans la vallée d'Alterac. Lorsque vous serez à proximité, servez-vous du Collier d'entraînement Stormpike pour le \"dompter\". Une fois dompté, le Bélier d'Alterac vous suivra jusqu'au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture.", description = "Regardez les écuries, <nom> ! Vides ! La brigade de Stormpike n’a plus de béliers à monter. Notre cavalerie n’existe plus.\n\nVous devez nous aider, soldat. Prenez ce collier d’entraînement et aventurez-vous dans la partie sauvage de la vallée. Trouvez les béliers d’Alterac qui y vagabondent et servez-vous du collier pour en capturer un. Lorsque vous l’aurez, amenez-le ici et je le mettrai à l’écurie.\n\nLorsque nous aurons assez de béliers, j’en informerai l’officier responsable. Avec votre aide, la cavalerie va ressusciter !", progress = "Sans votre aide, les monteurs de béliers Stormpike n'auraient pas de montures à chevaucher. Vous nous avez rendu un grand service !", completion = "Les écuries seront pleines en un rien de temps. Continuez à bien travailler !", rewards = nil},
[7028] = {title = "Forces maléfiques retorses", objective = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace.", description = "Les Cavernes de cristal de Terramok se situent à l'ouest, dans les profondeurs de Maraudon…C'est un endroit ancien doté d'une longue histoire. Il se trouve que je cherche à mettre la main sur une partie de tout cela, <classe>. Des reliques des dieux très anciens gisent toujours derrière les portes géantes.\n\nJ'aurais les moyens de récompenser grandement le temps que vous passeriez à affronter les forces maléfiques et retorses qui errent en ces lieux. Collectez pour moi les ciselures de Cristaux Théradriques, et faites-les-moi parvenir.\n\nUne fois les ciselures en ma possession, je serai à même de les... étudier. Ces pouvoirs sommeillent depuis trop longtemps...", progress = "Ne posez pas de questions !\n\nVoilà ma demande.", completion = "Ha ha ha ! Je savais que vous reviendriez.\n\n&lt;Saule marmonne&gt;\n\n…tellement simple à convaincre.\n\n…feraient n'importe quoi pour un bon prix. Hé hé hé...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe de sagacitéCasque de Vif-anneauCotte d'anneaux implacableEspauliers du colosse de pierre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7029] = {title = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.\n\nEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre.", description = "Un satyre connu sous le nom de Vylelangue a corrompu les cavernes de Maraudon, mettant en péril la croissance de nombre de plantes, à l'intérieur.\n\nPrenez cette fiole, <nom>. Remplissez-la au Bassin de cristal orange que vous pouvez trouver dans les cavernes ; le revêtement intérieur de cette fiole agira comme un contre-poison, et transformera cette eau en substance curative.\n\nTrouvez les vignes de Vylevrille dans les cavernes oranges, et faites sur elles usage du liquide purifié. La corruption sera purgée de la plante, mais gardez à l'esprit que Vylelangue en aura toujours le contrôle. Il pourrait s'en servir contre vous...", progress = "Si vous êtes capable de soigner la plante, elle sera de nouveau à même de grandir. Nous devons faire notre possible en ce sens, <nom>…", completion = "Merci de m'avoir rapporté ceci, &lt;nom&gt;. Avec ce qui reste du liquide, je vais pouvoir continuer mes études.\n\nQuoiqu'il reste encore beaucoup à faire, vous m'avez grandement aidé à guérir la corruption que Vylelangue a semée dans Maraudon. Veuillez accepter ceci comme témoignage de ma gratitude.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau WoodseedCeinturon d'armoiseGantelets griffebranche\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7041] = {title = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.\n\nEn faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel.", description = "Un satyre connu sous le nom de Vylelangue a corrompu les cavernes de Maraudon, mettant en péril la croissance de nombre de plantes, à l'intérieur.\n\nPrenez cette fiole, <nom>. Remplissez-la au Bassin de cristal orange que vous pouvez trouver dans les cavernes ; le revêtement intérieur de la fiole agira comme un contre-poison, et transformera cette eau en substance curative.\n\nTrouvez les vignes de Vylevrille, dans les cavernes oranges, et faites sur elles usage du liquide purifié. La corruption sera purgée de la plante, mais gardez à l'esprit que Vylelangue en aura toujours le contrôle. Il pourrait s'en servir contre vous...", progress = "Si vous êtes capable de soigner la plante, elle sera de nouveau à même de grandir. Nous devons faire notre possible en ce sens, <nom>…", completion = "Merci de m'avoir rapporté ceci, &lt;nom&gt;. Avec ce qui reste du liquide, je vais pouvoir continuer mes études.\n\nQuoiqu'il reste encore beaucoup à faire, vous m'avez grandement aidé à guérir la corruption que Vylelangue a semée dans Maraudon. Veuillez accepter ceci comme témoignage de ma gratitude.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau WoodseedCeinturon d'armoiseGantelets griffebranche\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7042] = {title = "Friandises volées de la fête du Voile d'hiver", objective = "Localiser l'enquêteur des Gourmandises Fumebois qui a été porté disparu dans les montagnes d'Alterac.", description = "Écoutez... ce n'est pas que je prenne du plaisir à ruiner la magie du moment, mais les Gourmandises Fumebois pourraient bien avoir besoin d'aide ; le genre d'aide que vous, les gens aux caractère aventureux, avez la réputation d'apporter volontiers aux nécessiteux.\n\nUn important chargement de friandises que nous nous apprêtions à stocker pour la saison a été signalé manquant, et maintenant, l'agent que nous avions dépêché sur le terrain pour mener l'enquête est lui aussi porté disparu ! Je vous en prie ; le chargement a été aperçu pour la dernière fois dans les montagnes d'Alterac, et c'est là que notre homme s'est rendu pour le trouver.\n\nVoyez si tous deux se trouvent là-bas, et en bonne forme !", progress = nil, completion = "V-v-vous pouvez m'entendre ! la providence soit louée !\n\nJe ne suis p-p-pas un vrai b-b-bonhomme de neige ; mon nom est S-s-sacks, je travaille pour la branche d'Ironforge des Gourmandises Fumebois. J'ai été envoyé i-i-ici pour en-q-q-quêter sur la disparition d'un chargement, q-q-quand j'ai été attaqué par une c-c-créature que je n'avais jamais vue jusqu'ici !\n\nJ'ai t-t-tellement f-froid...", rewards = "Vous recevrez :\n\n"},
[7043] = {title = "La méchanceté vous habite…", objective = "Trouver les Friandises volées, et les ramener à Wumort Jinglepocket, à Ironforge. C'est l'Abominable Grinche qui aurait le chargement en sa possession, il résiderait dans les régions neigeuses des montagnes d'Alterac.", description = "Une c-c-créature que l'on appelle \"l'abominable Grinche\" sévit par ici, c'est lui qui nous a dérobé notre cargaison de f-f-friandises, <nom>. Faites tout de même attention ! C'est aussi lui qui m'a transformé en brouillon de bonhomme de neige !\n\nV-v-vous allez avoir besoin d-d-d'aide pour lui tenir front. Je l'ai vu se p-p-promener un peu partout où on trouve des yétis. I-i-il est certainement quelque part dans les environs ! T-t-trouvez les friandises, <nom>, r-r-ramenez-les aux Gourmandises Fumebois d'Ironforge, et dites-leur q-q-que j'ai besoin qu'on vienne me d-d-dégeler !", progress = "<nom>, notre fête du Voile d'hiver va être une catastrophe sans ces friandises ! Graccu lui-même ne pourra pas partager ses succulentes tourtes à la viande avec les gens qui les ont méritées, cette année…", completion = "Vous avez trouvé le chargement ! Vous avez sauvé la fête du Voile d'hiver des Gourmandises Fumebois !\n\nPauvre Sacks… Nous allons faire en sorte de le dégeler. Il sera certainement de retour à temps pour le jour de la fête ; cependant, il aura du travail en retard à rattraper. Une fois encore, rien de tout cela ne serait possible sans votre aide !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7044] = {title = "Légendes de Maraudon", objective = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.\n\nTrouvez un moyen de parler à Celebras.", description = "Un satyre sombre connu sous le nom de seigneur Vylelangue répand le mal qui l'habite à travers cet enchevêtrement de cavernes, empoisonnant l'esprit de tout ce qui vit à l'intérieur. Il réside toujours au-delà des Cristaux pourpres.\n\nVylelangue s'est aussi créé un emblême vivant de sa corruption prénommé Noxxion qui demeure par-delà les Cristaux oranges. Ensemble, ils ont volé le sceptre de mon frère. Celebras, mon frère... il se promène à l'aveuglette dans les grottes, affecté lui aussi par la corruption.\n\nVous devez lui venir en aide ! Trouvez les pièces du sceptre, et d'une manière ou d'une autre, trouvez le moyen de parler à mon frère.", progress = "Voilà que je me réveille d'un cauchemar qui semblait ne jamais devoir finir…", completion = "Maintenant que vous avez récupéré les deux parties de mon sceptre, je peux me permettre d'espérer que les cavernes de Maraudon soient un jour purgées de cette vile corruption.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7045] = {title = "Un grand merci des Gourmandises Fumebois !", objective = "Parler à Grandpère Hiver à Ironforge.", description = "Les Gourmandises Fumebois apprécient sincèrement que vous ayez retrouvé les friandises volées, <nom>. En signe de notre gratitude, nous aimerions vous offrir quelque chose de spécial…remis par le Grandpère Hiver en personne !\n\nS'il vous plaît, allez parler à Grandpère Hiver, il vous donnera de notre part un cadeau de fête du Voile d'hiver. De notre ferme droit dans votre assiette, c'est bon, c'est sain, ce sont les Gourmandises Fumebois... Oh ! Et un grand merci à vous, bien sûr !", progress = nil, completion = "Ho ho ho, bien le bonjour, aventurier !\n\nLes gobelins m'ont dit que vous aviez gagné un cadeau spécial en cette heureuse saison, et je suis enchanté de vous le remettre personnellement. Voilà ; je vous souhaite une merveilleuse fête du Voile d'hiver, pour cette année et toutes les années à venir.", rewards = "Vous recevrez :\n\nCadeau spécial des Gourmandises Fumebois"},
[7046] = {title = "Le sceptre de Celebras", objective = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.\n\nParlez-lui après la réussite du rituel.", description = "Mon sceptre était autrefois une source d'espoir pour moi. Son pouvoir me permettait de me déplacer rapidement et librement dans ces cavernes. J'espérais pouvoir aider l'esprit de mon oncle à reposer en paix… C'est maintenant une tâche que je vous transmets.\n\nPour pouvoir sceller les deux moitiés du sceptre et lui rendre son intégrité, je vais avoir besoin de votre aide pour accomplir le rituel. S'il vous plaît, suivez-moi et prêtez attention à mes instructions, pendant que je canalise l'énergie nécessaire à réunir le bâtonnet et le diamant.\n\nEnsemble, nous allons recréer le Sceptre de Celebras.", progress = nil, completion = "Veuillez accepter ceci, et sachez que le pouvoir qui vous a été conféré doit être utilisé pour le bien de tous. Continuez votre exploration des cavernes, et avec un peu de chance vous trouverez les restes de mon oncle. De nombreux dangers vous guettent, &lt;nom&gt;.\n\nRevenez me parler, si le besoin s'en fait sentir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceptre de Celebras"},
[7061] = {title = "La fête du Voile d'hiver", objective = "Prenez le temps de lire ce livre, \"La fête du Voile d'hiver\", pour en apprendre plus sur cette période de fête. Quand vous en aurez fini avec le livre, apportez-le à Cairne Bloodhoof, dans la ville de Thunder Bluff.", description = "Voilà ; si en apprendre plus au sujet de la fête du Voile d'hiver vous concerne, lisez ce livre. Bien que je pense que notre version de la légende soit la plus appropriée, je suis suffisamment féru d'étude des légendes pour apprécier la collecte de toutes les informations dans un ouvrage unique.\n\nQuand vous aurez fini de le compulser, apportez donc ce livre à Cairne Bloodhoof, à Thunder Bluff. Je sais qu'il sera certainement intéressé d'apprendre que d'autres personnes se sont intéressées à la tradition de notre peuple.", progress = "Je vous souhaite la bienvenue à Mulgore et dans notre humble communauté de Thunder Bluff, ami. Je prends toujours le temps de m'intéresser à ceux qui se sentent concernés par le royaume, son peuple et ses traditions. Est-ce pour cette raison que vous venez me voir ?", completion = "Les légendes et traditions authentiques qui entouraient la fête du Voile d'hiver ont disparu des mentalités, au fil des ans. Oui, je sais que les gobelins sont en train d'en détourner l'esprit à des fins mercantiles, mais le fait que notre peuple réagisse et réfléchisse autour de cela aide la tradition à rester vivante.\n\nVotre volonté de vous détacher des choses matérielles et d'en apprendre plus sur notre passé est un trait de caractère admirable, jeune &lt;classe&gt;. Je salue votre sagesse.", rewards = "Vous recevrez :\n\n"},
[7062] = {title = "L'esprit de cette fête", objective = "Parlez à l'historien Karnik de la fête du Voile d'hiver, en vous rendant à la Ligue des Explorateurs d'Ironforge.", description = "Des cadeaux, des friandises, des présents... pouah ! Voilà tout ce que j'ai à en dire !\n\nCes gobelins pourrissent le sens véritable de cette période ; la fête du Voile d'hiver. C'est une période de renouveau, pendant laquelle la terre sommeille paisiblement sous un épais manteau blanc, déposé là par Grandpère Hiver. Ce dernier ne saurait être en AUCUN cas le crétin rabâcheur, là-bas, dans son costume rouge !\n\nSi vous désirez connaître le sens véritable de cette fête, questionnez donc l'historien Karnik, à la Ligue des Explorateurs. Je suis sûr qu'il sera surpris d'apprendre que quelqu'un se soucie plus de cette histoire que de recevoir des cadeaux.", progress = nil, completion = "La fête du Voile d'hiver dites-vous ? Ha, par le passé, cette fête avait un sens beaucoup plus profond pour nous, les nains. De nos jours, il semblerait que certaines personnes aient trouvé une occasion de transformer la légende du Grandpère Hiver de cette saison de renouveau en fonds de commerce.\n\nQu'un tel changement rende Goli amer ne me surprend pas le moins du monde. Les nains de son genre font de notre passé leur cheval de bataille. Je pense cependant qu'une petite célébration est bonne, il est important de se remémorer les origines de cette fête.", rewards = "Vous recevrez :\n\n"},
[7063] = {title = "La fête du Voile d'hiver", objective = "Prenez le temps de lire le livre \"La fête du Voile d'hiver\" pour en apprendre plus sur cette période sainte. Quand vous en aurez fini avec le livre, apportez-le au roi Magni Bronzebeard, à Ironforge.", description = "Voilà ; si en apprendre plus au sujet de la fête du Voile d'hiver vous intéresse, lisez ce livre. Bien que je pense que notre version de la légende soit la plus appropriée, je suis d'une nature suffisamment scolastique pour apprécier la collecte de toutes les informations dans un ouvrage unique.\n\nQuand vous aurez fini de le compulser, apportez donc ce livre au roi Magni Bronzebeard. Je sais qu'il sera certainement intéressé d'apprendre que d'autres personnes se sentent concernées par les légendes anciennes.", progress = "Je vous souhaite la bienvenue dans le royaume d'Ironforge, ami. Je prends toujours le temps de m'intéresser à ceux qui se sentent concernés par le royaume, son peuple et ses traditions. Est-ce pour cette raison que vous venez me voir ?", completion = "Les légendes et traditions qui entourent la fête du Voile d'hiver ont disparu des mentalités, au fil des ans. Bien que je reconnaisse que les gobelins aident à faire revivre l'esprit de cette période à des fins mercantiles, le fait est que les citoyens repensent au moins d'une certaine façon à cette fête, et que cela est bon pour la survie de la tradition.\n\nVotre désir d'aller au-delà des valeurs matérielles et d'en apprendre plus sur notre passé est un trait de caractère admirable, jeune &lt;classe&gt;. Je salue votre nature érudite.", rewards = "Vous recevrez :\n\n"},
[7064] = {title = "Corruption de la terre et de la graine", objective = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace.", description = "Profondément enfouie dans Maraudon, vit une malfaisante créature du chaos. La princesse Theradras est une force élémentaire de la Terre, liée aux Dieux très anciens. Il y a de cela une éternité, Zaetar, premier-né de Cénarius, et elle eurent une liaison. La progéniture qui naquit durant le temps où ils vécurent ensemble est connue par les gens de Kalimdor sous le nom de centaures. Dotés d'un sens très personnel de la gratitude, les centaures tuèrent Zaetar et conservent désormais ses restes. Ma quête consiste à trouver des braves suffisamment puissants pour éliminer Theradras, de manière à ce que nous puissions retrouver les restes de Zaemar, avant de retourner dans les Serres-Rocheuses.", progress = nil, completion = "Que voilà de bonnes nouvelles, &lt;nom&gt; ! Merci !\n\nJe vais parler à Marandis et solliciter son avis éclairé concernant les restes de Zaetar, mais au moins, vous avez fait la plus dure partie du travail.\n\nOn m'a dit que si nous étions victorieux, j'aurais la permission de récompenser ceux qui nous ont apporté leur aide. On m'a remis ces objets à offrir en présents, en gage de reconnaissance de notre peuple ; vous pouvez en choisir un.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de ThrashBâtonnet de résurgenceVisée des Gardiens verdoyants\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7065] = {title = "Corruption de la terre et de la Graine", objective = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace.", description = "Profondément enfouie dans Maraudon, vit une malfaisante créature du chaos, <nom>. La princesse Theradras est une force élémentaire de la Terre, liée aux Dieux très anciens. Il y a de cela une éternité, elle tomba sous le charme de Zaetar, premier-né de Cénarius. La progéniture qui naquit de leur union est connue par les habitants de Kalimdor sous le nom de centaures. Faisant preuve d'un sens très personnel de la gratitude, les centaures tuèrent Zaetar. Ses restes sont désormais sous la garde de Theradras. Ma quête consiste à trouver des braves suffisamment puissants pour éliminer Theradras, pour que nous puissions rechercher les restes de Zaemar, avant de retourner dans les Serres-Rocheuses.", progress = nil, completion = "Que voilà de bonnes nouvelles, &lt;nom&gt; ! Grand merci !\n\nBien que vous n'ayez pas été à même de me ramener les restes de Zaetar, ce qui m'attriste, je ne peux pas me plaindre. Qui serais-je pour remettre en question les décisions du premier-né de Cénarius ? Peut-être que la soif de sang des centaures va désormais se calmer ; nous ne pouvons qu'espérer.\n\nOn m'a remis ces objets, en m'autorisant à en faire don à tout parti nous ayant apporté de l'aide. Vous pouvez en prendre un, en gage de notre gratitude.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de ThrashBâtonnet de résurgenceVisée des Gardiens verdoyants\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7066] = {title = "Graine de vie", objective = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie.", description = "Ces centaures sans honneur, mes fils et mes filles, ont besoin de leur père.\n\nRegardez autour de vous…cet endroit résonne de tout l'espoir et de toutes les valeurs en faveur desquelles prêche mon père, Cénarius. Tout cela est né de moi ! Et je ne peux les priver de tout cela…pas même en guise de punition pour le crime qu'ils ont perpétré à l'encontre de ma personne.\n\nIl y a cependant une chose que je peux vous demander de faire pour apaiser l'esprit de mon frère. Prenez ceci... c'est la première graine engendrée par la vie qui s'est nourrie de mes restes. Dites-lui que mon esprit demeure ici, et que je vis dans tout cela. Je suis certain qu'il comprendra.", progress = "Vous sentez la corruption à plein nez, <nom>…Comme beaucoup d'aventuriers ces temps derniers. Mais quelque chose diffère en vous. Êtes-vous ici pour me parler de quelque chose en particulier ? Votre aura a quelque chose de familier, sans que je puisse dire précisément quoi.\n\nJe vous en conjure, dites-moi pourquoi vous avez sollicité une audience avec moi.", completion = "Alors mon frère a enfin trouvé la paix ? Je suis fier d'avoir vécu suffisamment longtemps pour voir ce jour. Toute la colère et l'arrogance qui émanaient de lui m'avaient laissé à penser qu'il était perdu pour nous, mais ceci... ce symbole de son sacrifice prouve qu'il a atteint la rédemption. Il n'est pas vraiment mort, il a juste repris corps dans une autre existence. Il fait ce que son devoir lui ordonne.\n\nMerci, &lt;nom&gt;. En m'amenant ceci, vous m'avez rendu l'espoir que je croyais avoir perdu. Cette graine jouera un jour un rôle important pour les gens de cette terre ravagée par la guerre... Je peux le sentir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7067] = {title = "Les instructions du paria", objective = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace.", description = "Malgré mon exil pour hérésie, mes convictions portent toujours le sceau de la vérité, c'est cela seul qui continue de me guider. Mais pour que mon destin soit accompli, j'ai besoin de l'aide d'un individu étranger, n'appartenant à aucune tribu de centaures.\n\nCette tâche requiert que quelqu'un entre dans les murs saints de Maraudon, un temple que mon peuple protège et dans lequel seuls les plus dévots peuvent entrer.\n\nSi vous acceptez de m'aider, alors hochez la tête. Je vais vous donner un parchemin portant mes instructions. Lisez-le et méditez mes paroles.", progress = "Qu'avez-vous décidé, <nom> ? Pouvez-vous m'aider ? Oserez-vous mettre le pied sur le sol sacré, pour m'aider à fonder une grande tribu de centaures ?", completion = "Ça y est, &lt;nom&gt; ! Ça y est ! Maintenant, je peux me lancer dans la noble tâche consistant à unir les tribus. Merci.\n\nPrenez ceci pour le service rendu, s'il vous plaît. J'espère que notre prochaine rencontre aura lieu sous des auspices plus favorables.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMarque de l'Elu"},
[7068] = {title = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar.", description = "On trouve des magies puissantes sur la terre sainte des centaures… le sol sacré de Maraudon. Les tribus de centaures de Désolace protègent cet endroit, au prix du sang, mais il ne peuvent pas nous empêcher de nous servir.\n\nPrenez la direction de Maraudon et trouvez les créatures composées d'Ombréclat. Vous me ramenez les Cristaux pourpres, et Uthel'nay s'arrangera pour récompenser l'effort.\n\nL'endroit est dangereux, peut-être que vous feriez bien d'y aller en bonne compagnie.", progress = "Avez-vous déjà trouvé les cristaux ? Rituels de pouvoir, sorts de grande force ; ces ombréclats peuvent s'avérer très utiles dans tous les types de magies des arcanes.", completion = "Ah, voilà qui est parfait pour ma magie. Tenez, prenez un de ces bijoux et reprenez votre route...J'ai de nombreuses études à avancer.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPendentif Ombréclat zéléPendentif Ombréclat prodigieux\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7070] = {title = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange.", description = "J'ai dernièrement commencé à tester différents cristaux et leurs propriétés arcaniques. Dame Proudmoore m'a laissé pour consigne de demander aux voyageurs faisant route vers Désolace de rechercher un endroit appelé Maraudon. À l'intérieur du temple en ruine, vivent de grands élémentaires composés des ces pierres rougeâtres que j'ai appelé \"Ombréclats\".\n\nSi vous décidiez de prendre cette direction et de trouver ces cristaux, je saurais vous montrer ma reconnaissance. Je pourrais même vous élaborer un bijou à partir de l'un d'entre eux, si vous le désiriez.", progress = "Avez-vous déjà effectué le voyage ? Je réalise que cela doit être relativement dangereux, mais si réussissiez, le jeu en vaudrait la chandelle.", completion = "C'est parfait, &lt;nom&gt;. En fait, d'autres aventuriers m'aidaient aussi à la tâche, et avec ce qu'ils m'ont ramené, j'ai été capable de fabriquer ces objets... Veuillez accepter l'un d'entre eux en récompense du travail accompli. Et merci encore pour ces échantillons supplémentaires à étudier.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPendentif Ombréclat zéléPendentif Ombréclat prodigieux\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7081] = {title = "Les cimetières de la vallée d'Alterac", objective = "Attaquez un cimetière, puis présentez-vous au caporal Noreg Stormpike à Dun Baldar.", description = "Les cimetières de la vallée d’Alterac sont des territoires de choix. La Horde et l’Alliance se battent sauvagement pour conserver le contrôle de ces terres consacrées. Êtes-vous <prêt/prête> à vous joindre à ce combat, <nom> ?\n\nJe veux que vous attaquiez un cimetière ennemi. Trouvez un cimetière sur lequel flotte la bannière de la Horde et arrachez-la ! Si vous y parvenez, la tâche que je vous ai fixé sera achevée…\n\nMais si vous le tenez pour quelques minutes supplémentaires, nos troupes viendront vous relever.", progress = nil, completion = "Bien joué ! Les cimetières sont vitaux pour notre contrôle de la vallée d’Alterac. Lorsque vous en prenez un, vous aidez l’Alliance a y assurer sa souveraineté.\n\nAllez maintenant, &lt;nom&gt;. Entrez dans la bataille, et si vous trouvez un cimetière sous le contrôle de la Horde, vous savez quoi faire !", rewards = "Vous recevrez :\n\n"},
[7082] = {title = "Les cimetières d'Alterac", objective = "Attaquez un cimetière, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.", description = "Dans cette vallée, la ligne de front fluctue sans cesse. Les territoires avancent et reculent au gré des affrontements avec nos adversaires. Il se trouve que les cimetières sont l’endroit où le conflit est le plus intense, <nom>.\n\nPrenez un cimetière à l’Alliance ! Trouvez un cimetière avec une bannière de l’Alliance plantée en son centre et arrachez-la !\n\nSi vous y parvenez, la tâche que je vous ai fixé sera achevée, mais si vous tenez le cimetière pendant quelques minutes supplémentaires, il nous appartiendra et nos troupes viendront vous relever.", progress = nil, completion = "Bien joué, &lt;nom&gt; ! Avec ce cimetière sous notre contrôle, les esprits de nos ennemis vont errer, perdus et impuissants…", rewards = "Vous recevrez :\n\n"},
[7101] = {title = "Tours et fortins", objective = "Prenez une tour ennemie, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.", description = "Les tours et les fortins sont des positions défensives de très grande valeur, et nous devons tous les prendre. Je veux que vous attaquiez un fortin ou une tour détenu par l’ennemi.\n\nPour cela, entrez dans une tour ou un fortin sur lequel flotte la bannière de l’Alliance. A l’intérieur, vous trouverez une autre bannière ennemie. Prenez-la, et la bannière blanche de la Horde apparaîtra à sa place. Bien joué !\n\nA ce stade, votre mission sera achevée, mais si vous tenez assez longtemps et si l’Alliance ne contre-attaque pas, la zone tombera entre nos mains !", progress = nil, completion = "J’entendu dire que vous aviez réussi. Cela me plaît…\n\nNos troupes vont bientôt charger les troupes de l’Alliance en toute impunité, et leur montrer que la vallée d’Alterac ne leur appartient pas !", rewards = "Vous recevrez :\n\n"},
[7102] = {title = "Tours et fortins", objective = "Détruisez la bannière d'une tour ou d'un fortin ennemi, puis présentez-vous au sergent Durgen Stormpike à Dun Baldar.", description = "Les tours et les fortins sont des positions défensives de très grande valeur, et nous devons en tenir autant que possible. Je veux que vous attaquiez un fortin ou une tour détenue par l’ennemi.\n\nPour cela, entrez dans une tour ou un fortin sur lequel flotte la bannière de la Horde. A l’intérieur, vous trouverez une autre bannière ennemie. Prenez-la, et la bannière blanche de l’Alliance apparaîtra à sa place. Bien joué !\n\nA ce stade, votre mission sera achevée, mais si vous tenez assez longtemps et si la Horde ne contre-attaque pas, la zone tombera entre nos mains !", progress = nil, completion = "J'ai reçu un rapport signalant que vous aviez aidé à saisir une bannière ennemie. Bien joué, &lt;nom&gt; ! Comme leurs tireurs ne sont plus en position, nous pourrons tenir la zone contre les prochaines attaques de la Horde !", rewards = "Vous recevrez :\n\n"},
[7121] = {title = "L'intendant", objective = "Parlez à l’Intendant Stormpike.", description = "<nom>, notre indendant m’a demandé de lui envoyer les nouvelles recrues. Il a besoin du matériel conservé dans les caches dissimulées dans les mines d’Alterac, et il va sans doute vous envoyer le récupérer.\n\nSuivez la route. Vous trouverez l’indendant à l’ouest.", progress = nil, completion = "C’est bon de voir des troupes fraîches ici, &lt;nom&gt;, mais avec un peu de chance il y aura bientôt de l’action et vous ne serez plus si frais !\n\nÉcoutez, j''ai des tâches à vous proposer…", rewards = "Vous recevrez :\n\n"},
[7122] = {title = "Prendre une mine", objective = "Prenez une mine que les Stormpike ne contrôlent pas, puis présentez-vous à l’intendant Stormpike à Dun Baldar.", description = "Les mines de la vallée d’Alterac renferment bien davantage que du minerai. Les Frostwolf et les Stormpike ont dissimulé du matériel dans les mines de Gouffrefer et de Froide-dent… ce ne serait pas une mauvaise idée, si seulement nous pouvions en garder le contrôle !\n\nPrenez une mine, puis revenez me voir. Pour prendre une mine, entrez dans une de celles que nous ne contrôlons pas et tuez son chef. Lorsque ce sera fait, la mine sera à nous et nous enverrons des troupes pour la protéger !", progress = nil, completion = "Vous l’avez fait ! Bravo, &lt;nom&gt; !\n\nLorsque nous contrôlons une mine et que nous y stationnons des troupes, il est beaucoup plus facile d’y récolter du minerai et du matériel.", rewards = "Vous recevrez :\n\n"},
[7123] = {title = "Parlez à notre Intendant", objective = "Parlez à l’Intendant Frostwolf.", description = "<nom>, l'Intendant des Frostwolf cherche des recrues pour accomplir des tâches qui les conduiront dans les mines de la vallée d'Alterac. Allez lui parler, il vous en dira davantage.\n\nSuivez la route vers l'ouest jusqu'au fortin, puis prenez la sortie ouest et vous trouverez notre intendant.", progress = nil, completion = "Salut, &lt;nom&gt; ! Cela fait du bien de voir un &lt;classe&gt; comme vous, enthousiaste à l'idée de faire sa part pour la Horde. Écoutez-moi bien, car j'ai des tâches d'une importance capitale à vous confier…", rewards = "Vous recevrez :\n\n"},
[7124] = {title = "Prendre une mine", objective = "Prenez une mine, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.", description = "La bataille fait rage dans la vallée d’Alterac, mais aussi dans les mines de Froide-dent et de Gouffrefer. Ces deux exploitations sont riches en minerais, et sont toutes deux utilisées pour y stocker du matériel ; ce n’est pas étonnant qu’elles soient autant appréciées !\n\nContribuez à notre effort de guerre, <nom> ! Capturez une mine pour la Horde ! Pour y parvenir, entrez dans une mine que nous ne contrôlons pas et tuez son chef. La mine sera alors à nous, et nous enverrons des troupes pour la protéger !", progress = nil, completion = "Vous avez pris une mine ! Maintenant que nos propres guerriers la protègent, il sera bien plus simple d'extraire du minerai de ses profondeurs, ou de rassembler les fournitures qui y ont été stockées.\n\nBien joué, &lt;nom&gt;. L'acte que vous avez accompli est un véritable bienfait pour notre effort de guerre.", rewards = "Vous recevrez :\n\n"},
[7141] = {title = "La bataille d'Alterac", objective = "Entrez dans la vallée d'Alterac, tuez Drek'thar, le général de la Horde, puis retournez voir la Prospectrice Stonehewer dans les montagnes d'Alterac.", description = "La Ligue des Explorateurs soupçonne la présence d’artefacts dans la vallée d’Alterac, mais les orcs Frostwolf nous empêchent de l’explorer. Nous ne pouvons pas laisser la Horde faire obstacle à la poursuite du savoir ! Abattez Drek’Thar, leur général. Sans lui, les Frostwolf perdront leur mordant.\n\nDrek’Thar est au donjon Frostwolf, au sud de la vallée d'Alterac. Tuez-le et revenez me voir.", progress = nil, completion = "Bien joué, &lt;nom&gt; ! Maintenant que le général de la Horde est mort, nous aurons un peu plus de temps pour nos explorations.", rewards = "Vous recevrez :\n\n"},
[7142] = {title = "La bataille pour Alterac", objective = "Entrez dans la vallée d'Alterac, tuez Vanndar Stormpike, le général nain, puis retournez voir Voggah Deathgrip dans les montagnes d'Alterac", description = "Les nains Stormpike et leurs alliés ont envahi la vallée d'Alterac, et nous devons les chasser !\n\nPour cela, nous devons vaincre leur général, Vanndar Stormpike.\n\nVous trouverez Vanndar à Dun Baldar, au nord de la vallée d'Alterac. Tuez-le, <nom>, et revenez me voir.", progress = nil, completion = "Bien joué, &lt;nom&gt;. Cette stupide invasion est condamnée.\n\nBah ! Tout ce qu'ils ont réussi à obtenir, c'est un général mort !", rewards = "Vous recevrez :\n\n"},
[7161] = {title = "Montrer sa valeur", objective = "Rendez-vous dans les cavernes des Follepattes, au sud-est de la base principale, et récupérez la Bannière Frostwolf qui s’y trouve. Ramenez-la au Maître de guerre Laggrond.", description = "Salutations, <classe>. Il y a bien longtemps que nous n’avons pas eu la chance de répondre à l’appel de la bataille. La vieille envie est lente à monter, mais lorsqu’elle s’éveille, le sang court plus vite dans nos veines. La rage de la bataille revient…\n\nTous les nouveaux venus dans la vallée doivent accomplir le rite de la bataille.\n\nDans les profondeurs de la caverne des gnolls Follepattes se trouve une bannière Frostwolf. Allez-y et récupérez-la. Ramenez-la moi et je vous donnerai l’insigne d’initié des Frostwolf.", progress = "Allez, <nom>, on se réveille ! Ce n’est pas un rêve. Vous êtes vraiment au beau milieu d’une bataille !", completion = "Vous ressentez comme une brûlure, pas vrai ? C’est votre âme qui s’éveille. Votre esprit a accepté l’appel de la bataille.\n\nVous êtes maintenant un Frostwolf, &lt;nom&gt;. Félicitations.\n\nPortez cet insigne avec vous en toutes circonstances. Au fur et à mesure de votre montée en grade, je le remplacerai par d’autres insignes, plus puissants.\n\nEt qui sait ? Un jour peut-être, vous serez Exalté parmi le clan Frostwolf. Si ce jour arrive, vous recevrez l’Œil du Commandement.", rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 1Peler l'oignon"},
[7162] = {title = "Montrer sa valeur", objective = "Rendez-vous dans les cavernes de l'Aile de glace, au sud-ouest de la base principale, et récupérez la Bannière Stormpike qui s’y trouve. Ramenez-la au lieutenant Haggerdin.", description = "Vous arrivez juste à temps, <classe>. Ces sauvages de Frostwolf refusent d’abandonner ! Nous devons leur montrer la puissance des Stormpike. Ils doivent s’incliner devant notre supériorité.\n\nAvant de vous risquer sur le champ de bataille, vous devrez rejoindre les rangs des Stormpike.\n\nLes cavernes de l'Aile de glace se trouvent au sud-ouest. Dans leurs tréfonds, vous trouverez une bannière Stormpike. Allez-y et récupérez-la. Ramenez-la moi et vous aurez bien mérité un insigne d’initié Stormpike.", progress = "Faites attention aux harpies, <classe>. Elles n’hésiteront pas une seconde à vous égorger !", completion = "Prenez cet insigne et portez-le avec fierté, &lt;nom&gt;. Il évoluera au fur et à mesure de votre montée en grade parmi les Stormpike. Revenez me voir lorsque vous gagnerez de l’honneur et je remplacerai votre insigne par un autre, plus puissant.\n\nPeut-être deviendrez-vous un jour une légende sur ce champ de bataille. Si ce jour arrive, vous recevrez l’Œil du Commandement.", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 1L'artichaut Frostwolf"},
[7163] = {title = "Ascension et reconnaissance", objective = "<Le Maître de guerre Laggrond vous salue.>\n\nVotre heure a sonné, <nom>. Vous avez rendu service au clan Frostwolf. Ce faisant, vous avez mérité une place parmi nous, non seulement comme soldat, mais aussi comme ami.\n\nBien joué ! Présentez votre insigne d’initié.", description = nil, progress = "<Le Maître de guerre Laggrond vous salue.>\n\nVotre heure a sonné, <nom>. Vous avez rendu service au clan Frostwolf. Ce faisant, vous avez mérité une place parmi nous, non seulement comme soldat, mais aussi comme ami.\n\nBien joué ! Présentez votre insigne d’initié.", completion = "Ce nouvel insigne reflète votre grade parmi les Frostwolf. Gardez-le sur vous en permanence.\n\nEt &lt;classe&gt;… Tâchez de mourir avec honneur !", rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 2"},
[7164] = {title = "Honoré au sein du clan", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 3"},
[7165] = {title = "Montée en grade", objective = "Tant de morts. Un champ saturé de sang. Mais vous êtes en vie. Vous avez persévéré. Vous avez mené nos armées à la victoire. Et pour cela, soldat, vous avez mérité de monter en grade.\n\nPrésentez votre insigne.", description = nil, progress = "Tant de morts. Un champ saturé de sang. Mais vous êtes en vie. Vous avez persévéré. Vous avez mené nos armées à la victoire. Et pour cela, soldat, vous avez mérité de monter en grade.\n\nPrésentez votre insigne.", completion = "&lt;Le maître de guerre Laggrond rugit.&gt;\n\nIls commencent à raconter vos exploits, soldats. Les Stormpike tremblent de peur lorsqu’ils entendent votre nom. Continuez !", rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 4"},
[7166] = {title = "Héros de légende", objective = "Puissance et autorité émanent de vous, <classe>. Vous êtes exalté aux yeux des Frostwolf – l’ennemi se cache à la seule mention de votre nom.\n\nDebout, Héros des Frostwolf. Debout et soyez honoré !\n\nPrésentez votre insigne.", description = nil, progress = "Puissance et autorité émanent de vous, <classe>. Vous êtes exalté aux yeux des Frostwolf – l’ennemi se cache à la seule mention de votre nom.\n\nDebout, Héros des Frostwolf. Debout et soyez honoré !\n\nPrésentez votre insigne.", completion = "Bientôt, tout le champ de bataille sera sous vos yeux vigilants. Vous aurez le commandement de la Vallée et de ses troupes.", rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 5"},
[7167] = {title = "L'Œil du commandement", objective = "Drek’Thar chante vos louanges. Kalimdor résonne du bruit de vos exploits. Le chef de guerre sourit – votre héroïque défense de notre clan l’a grandement satisfait.\n\nVous avez mérité l’Œil du Commandement.\n\nPrésentez votre insigne, commandant <nom>.", description = nil, progress = "Drek’Thar chante vos louanges. Kalimdor résonne du bruit de vos exploits. Le chef de guerre sourit – votre héroïque défense de notre clan l’a grandement satisfait.\n\nVous avez mérité l’Œil du Commandement.\n\nPrésentez votre insigne, commandant <nom>.", completion = "Canalisez le pouvoir de l’insigne. Laissez l’ennemi entendre vos paroles. La puissance de la Horde est incontestable !", rewards = "Vous recevrez :\n\nInsigne Frostwolf grade 6"},
[7168] = {title = "Ascension et reconnaissance", objective = "La plupart des gens ne vivent pas assez longtemps pour s’élever au-dessus de leur propre médiocrité. Vous avez montré que vous êtes un soldat exemplaire, <classe>. L’heure est venue.\n\nPrésentez votre insigne.", description = nil, progress = "La plupart des gens ne vivent pas assez longtemps pour s’élever au-dessus de leur propre médiocrité. Vous avez montré que vous êtes un soldat exemplaire, <classe>. L’heure est venue.\n\nPrésentez votre insigne.", completion = "Que nos ennemis voient qu’un soldat d’élite les a tués ! Battez-vous ! Battez-vous pour la gloire des Stormpike !", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 2"},
[7169] = {title = "Honoré au sein de la Garde", objective = "Toute la base parle de vos exploits sur le Champ sanglant ! Vous avez porté des coups sévères à l’ennemi – et à son moral ! Pour cela, vous avez mérité de progresser au sein des Stormpike.\n\nPrésentez votre insigne.", description = nil, progress = "Toute la base parle de vos exploits sur le Champ sanglant ! Vous avez porté des coups sévères à l’ennemi – et à son moral ! Pour cela, vous avez mérité de progresser au sein des Stormpike.\n\nPrésentez votre insigne.", completion = "Le roi a été informé de vos exploits sur le champ de bataille, &lt;classe&gt;. Continuez votre vaillante défense de la Garde Stormpike !", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 3"},
[7170] = {title = "Montée en grade", objective = "Je m’interroge, <nom>. Lorsque vous regardez dans les yeux de l’ennemi, y voyez-vous la peur ? Se cachent-ils plutôt que de vous faire face ? Ils doivent bien se rendre compte qu’ils sont vaincus !\n\nVous avez mérité que la Garde vous traite avec révérence. Présentez votre insigne !", description = nil, progress = "Je m’interroge, <nom>. Lorsque vous regardez dans les yeux de l’ennemi, y voyez-vous la peur ? Se cachent-ils plutôt que de vous faire face ? Ils doivent bien se rendre compte qu’ils sont vaincus !\n\nVous avez mérité que la Garde vous traite avec révérence. Présentez votre insigne !", completion = "A notre première rencontre, je ne me serais jamais douté que vous étiez un héros en herbe. Continuez, soldat !", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 4"},
[7171] = {title = "Héros de légende", objective = "Devant moi se tient un héros de l’Alliance.\n\n<Le Lieutenant Haggerdin salue.>\n\nRares sont ceux qui ont obtenu un tel grade parmi les Stormpike. J’ai vu l’ennemi tomber devant vous. J’ai vu leur résolution s’effondrer devant votre présence. Lorsque vous entrez dans la mêlée, vous devenez un point de ralliement pour nos forces !\n\nPrésentez votre insigne.", description = nil, progress = "Devant moi se tient un héros de l’Alliance.\n\n<Le Lieutenant Haggerdin salue.>\n\nRares sont ceux qui ont obtenu un tel grade parmi les Stormpike. J’ai vu l’ennemi tomber devant vous. J’ai vu leur résolution s’effondrer devant votre présence. Lorsque vous entrez dans la mêlée, vous devenez un point de ralliement pour nos forces !\n\nPrésentez votre insigne.", completion = "C’est sûrement vous qui porterez l’Oeil du Commandement !", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 5"},
[7172] = {title = "L'Œil du commandement", objective = "Laissez-les entendre votre voix, commandant <nom> ! Ils connaîtront la peur. Montrez-leur le pouvoir des Stormpike !\n\nPrésentez votre insigne.", description = nil, progress = "Laissez-les entendre votre voix, commandant <nom> ! Ils connaîtront la peur. Montrez-leur le pouvoir des Stormpike !\n\nPrésentez votre insigne.", completion = "C’est vous qui devez mener nos troupes à la victoire, commandant ! Les soldats sont à vos ordres. Ils vous obéiront. Conduisez-les, et écrasez les Frostwolf !", rewards = "Vous recevrez :\n\nInsigne Stormpike grade 6"},
[7181] = {title = "La légende de Korrak", objective = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.\n\nRendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Maître de guerre Laggrond.", description = "Les envahisseurs Stormpike ne sont pas la seule menace dans la région, soldat. La guerre dans la Vallée se livre sur deux fronts. Les trolls cannibales des Winterax ont leurs propres ambitions.\n\nIls sont dirigés par Korrak le Ragesang, une bête cruelle et rusée.\n\nLa mort de Korrak serait un grand coup porté aux Winterax. Tuez cet animal, et vous serez récompensé !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nSanguinaireLance de glace barbeléeBaguette du froid mordant\n\nVous recevrez également :\n\nRune de rappel"},
[7201] = {title = "Le dernier élément", objective = "Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires.", description = "Il y a du travail pour ceux qui s'aventurent dans les Profondeurs, <nom>.\n\nLes Sombrefer peuvent créer des golems extrêmement puissants.\n\nLes premiers rapports de nos espions indiquent que les nains se servent d'une source d'énergie unique pour fournir à leurs créations une capacité de tuerie incomparable.\n\nImaginez simplement ce que nous pourrions faire de nos abominations si nous mettions la main sur cette Essence des éléments ! Fouillez les moindres recoins de cette cité si cela est nécessaire, mais ne revenez pas tant que vous n'avez pas découvert cette essence ! Votre récompense sera à la mesure du risque encouru.", progress = "<Elle se frotte les mains.>\n\nMontrez-les-moi !", completion = "Merveilleux ! Je vais immédiatement ordonner à un messager de les envoyer à Undercity !\n\nQuant à vous, voici votre récompense, comme promis. Gardez la monnaie, ignoble bête !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau de Lagrave"},
[7202] = {title = "Korrak le Ragesang", objective = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.\n\nRendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Lieutenant Haggerdin.", description = "Les indigènes de la région, les trolls Winterax, sont des sauvages cruels qui rêvent d’ajouter nos os à leurs infâmes ragoûts.\n\nNous devons leur montrer notre force !\n\nNous avons récupéré dans leurs cavernes des livres qui détaillent leur hiérarchie. Ils indiquent que leur chef, Korrak le Ragesang, a tendance à rester caché jusqu’à ce qu’il ait une raison de faire connaître sa présence.\n\nLa mort de Korrak signerait la mort du clan Winterax ! Tuez-le et revenez.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nSanguinaireLance de glace barbeléeBaguette du froid mordant\n\nVous recevrez également :\n\nRune de rappel"},
[7221] = {title = "Discuter avec la prospectrice Stonehewer", objective = "Discutez avec la Prospectrice Stonehewer à la Garnison de Dun Baldar.Ah, <nom>, <prêt/prête> à prendre votre service ? Très bien, les Stormpike ont besoin de tous les bras disponibles !\n\nDiscutez avec la prospectrice Stonehewer à Dun Baldar. Elle cherche des volontaires pour une mission très importante en territoire ennemi. Vous la trouverez dans les profondeurs de la garnison de Dun Baldar.\n\nEt gardez l’œil ouvert quand vous traverserez Dun Baldar. Il y a beaucoup à faire pour un <classe> travailleur et qui n’a pas peur de se salir les mains.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Ah, <nom>, <prêt/prête> à prendre votre service ? Très bien, les Stormpike ont besoin de tous les bras disponibles !\n\nDiscutez avec la prospectrice Stonehewer à Dun Baldar. Elle cherche des volontaires pour une mission très importante en territoire ennemi. Vous la trouverez dans les profondeurs de la garnison de Dun Baldar.\n\nEt gardez l’œil ouvert quand vous traverserez Dun Baldar. Il y a beaucoup à faire pour un <classe> travailleur et qui n’a pas peur de se salir les mains.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7222] = {title = "Discuter avec Voggah Deathgrip", objective = "Parlez à Voggah au donjon Frostwolf.Un <classe> ? Bien ! Nous sommes contents de vous avoir à Alterac, <nom>. Des nains fouineurs et leurs alliés sont en train d’envahir notre vallée, et nous accueillons au sein de la Horde tous ceux qui veulent se joindre à nous pour la bataille.\n\nParlez à Voggah Deathgrip. Il cherche des agents pour une mission importante au cœur de la forteresse de l’Alliance.\n\nVous le trouverez au donjon Frostwolf.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Un <classe> ? Bien ! Nous sommes contents de vous avoir à Alterac, <nom>. Des nains fouineurs et leurs alliés sont en train d’envahir notre vallée, et nous accueillons au sein de la Horde tous ceux qui veulent se joindre à nous pour la bataille.\n\nParlez à Voggah Deathgrip. Il cherche des agents pour une mission importante au cœur de la forteresse de l’Alliance.\n\nVous le trouverez au donjon Frostwolf.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7223] = {title = "Morceaux d'armures", objective = "Apportez 20 Morceaux d’armure à Murgot Deepforge à Dun Baldar.", description = "Les combats font sans cesse rage dans la vallée d’Aterac, et le matériel que nous recevons d’Ironforge est insuffisant pour équiper nos troupes.\n\nSi vous trouvez des morceaux d’armure sur le champ de bataille, contribuez à l’effort de guerre et ramenez-les-moi !", progress = "M’apportez-vous des morceaux d’armure, <nom> ?", completion = "Ce sont de bonnes pièces, &lt;nom&gt;. Je peux m’en servir pour fabriquer de l’équipement pour nos troupes.\n\nSi nous avons assez de matériel, nous pourrons peut-être déployer des troupes endurcies !", rewards = "Vous allez être la cible du sort suivant :\n\nArmure polie\n\nVous recevrez :\n\n"},
[7224] = {title = "Pris à l'ennemi", objective = "Apportez 20 Morceaux d’armure au forgeron Regzar au village Frostwolf.", description = "Lorsque vous combattez l’ennemi, ramassez les morceaux de leurs armures et amenez-les-moi. Je m’en servirai pour fabriquer des armures pour nos propres troupes !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nArmure polie\n\nVous recevrez :\n\n"},
[7241] = {title = "La défense des Frostwolf", objective = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Trouvez le maître de guerre Laggrond, parlez-lui et commencez votre carrière comme soldat Frostwolf.", description = "Les tambours de guerre résonnent dans des terres lointaines, <classe>. Le clan favori de votre Chef de guerre est attaqué par l'infâme garde Stormpike d'Ironforge. \n\nA vous voir, je pense que vous êtes endurci et prêt à vous battre pour la cause du clan Frostwolf.\n\nC'est vous qui devez faire ce nouveau pas dans votre évolution.\n\nVous trouverez l'entrée de la vallée d'Alterac dans les contreforts d'Hillsbrad. Entrez-y et allez trouver le maître de guerre Laggrond. Faites vites, <classe>, la bataille est commencée !", progress = nil, completion = "Pour devenir un soldat Frostwolf, il faut être mis à l'épreuve…", rewards = "Vous recevrez :\n\n"},
[7261] = {title = "L'impératif souverain", objective = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Présentez-vous au lieutenant Haggerdin.\n\nPour la gloire de Bronzebeard !", description = "Nous livrons une dure bataille dans les vallées d'Alterac. Les trolls cannibales du clan Winterax nous attaquent d'un côté, le féroce clan Frostwolf de l'autre. Tous deux doivent être exterminés au nom du roi Magni Bronzebeard ! Cette terre doit être prise et nettoyée. C'est un impératif territorial souverain pour le royaume d'Ironforge !\n\nHélas, les soldats ne poussent pas sur les arbres ! Présentez-vous au lieutenant Haggerdin dans la vallée d'Alterac pour commencer votre carrière de soldat des Stormpike.", progress = nil, completion = "Au travail !", rewards = "Vous recevrez :\n\n"},
[7281] = {title = "Amour fraternel", objective = "Pénétrez en territoire Stormpike et tuez le commandant Karl Philips. Lorsque ce sera fait, présentez-vous au commandant Louis Philips.", description = "Tragique… Mon frère et moi sommes dans des camps opposés : il est commandant chez les Stormpike.\n\nDes quatre commandants des Stormpike, il est incontestablement le plus dangereux. Peut-être que s’il était tué, la reine banshee pourrait lui montrer son erreur, comme elle l’a fait avec moi…\n\nVous trouverez mon frère loin en territoire ennemi. Tuez-le et ramenez-le-moi. Je vous fais confiance pour remplir cette mission, soldat.\n\nOh… et ne partez pas seul.", progress = nil, completion = "Vos exploits ne passent pas inaperçus, &lt;nom&gt;.\n\nJe ne dois pas perdre de temps s’il faut le sauver. Sylvanas doit être contactée !", rewards = "Vous recevrez :\n\n"},
[7282] = {title = "Amour fraternel", objective = "Pénétrez en territoire Frostwolf et tuez le commandant Louis Philips. Lorsque ce sera fait, présentez-vous au commandant Karl Philips.", description = "Il faut mettre un terme à ses souffrances, soldat. Il ne sait pas ce qu’il fait. Il est devenu un serviteur décérébré de la terrible reine banshee.\n\nTraversez le Champ sanglant et pénétrez dans les profondeurs du territoire Frostwolf. Trouvez mon frère et détruisez-le. Son tourment doit s’achever.", progress = nil, completion = "Vous avez bien brûlé le cadavre, n’est-ce pas ?", rewards = "Vous recevrez :\n\n"},
[7301] = {title = "Les ailes brisées", objective = "Enfoncez-vous en territoire Frostwolf à la recherche des chefs d’escadrille Slidor, Vipore et Ichman. Si vous les retrouvez, présentez-vous au commandant Duffy.", description = "Nous les tenons, <race>. Je parle de leurs chefs d’escadrille. La bataille aérienne a été violente, mais ils ont fini par tomber. Malheureusement, nos meilleurs pilotes ont été abattus dans une contre-attaque contre le donjon Frostwolf. Vous devez découvrir ce qui leur est arrivé.\n\nAllez voir à la Tour de la halte ouest et au donjon Frostwolf, ce sont leurs dernières positions connues. Fouillez soigneusement les environs.", progress = nil, completion = "Incroyable ! Vous les avez libérés, n’est-ce pas ? N’est-ce pas ? Bon, au moins, nous savons où ils étaient détenus.", rewards = "Vous recevrez :\n\n"},
[7302] = {title = "Les ailes brisées", objective = "Découvrez ce qui est arrivé aux chefs d’escadrille Guse, Jetzor et Mulverick. Lorsque vous les aurez retrouvés, présentez-vous au commandant Mulfort.", description = "Notre soutien aérien n’existe plus, <nom>. Nos chefs d’escadrille ont été abattus au-dessus du territoire ennemi. Vous devez découvrir ce qui leur est arrivé, afin que nous puissions mener une expédition de secours ! Guse a été vu pour la dernière fois au-dessus du fortin de l'Aile de glace. Le Chevaucheur de guerre de Jeztor a été vu près de la scierie Stormpike. Quant à Mulverick… on a vu ce crétin téméraire s’écraser près du fortin nord de Dun Baldar.\n\nJe n’ai pas d’autres informations. Allez-y et passez la région au peigne fin !", progress = nil, completion = "Très bien ! Ces informations seront très utiles à notre cause.", rewards = "Vous recevrez :\n\n"},
[7321] = {title = "Bisque de tortue apaisante", objective = "Apporter 10 morceaux de Viande de tortue et des Epices apaisantes à Christoph Jeffcoat au Moulin-de-Tarren.", description = "Qui prétend que les morts-vivants n’y connaissent rien en cuisine ? Tenez, par exemple, prenez ma recette secrète de Bisque de tortue apaisante, par exemple. Je connais des gens qui sont revenus d’entre les morts rien que pour en déguster un bol ! Hé hé…\n\nA ce propos, je n’ai pas eu l’occasion d’en préparer dernièrement. Autrefois, j’allais jusqu'au lac de Lordamere pour chasser les gueules d’acier – ces sales bêtes – mais à présent, j’ai trop de travail.\n\nSi vous m'apportiez de la Viande de tortue venant des gueules d'acier et des Epices apaisantes, je vous mitonnerai un bon petit plat.", progress = "Alors, vous avez mes ingrédients ? Je vais vous dire, ces infects vers de l’Alliance sont trop nombreux dans la région. À mon avis, ils sont aussi beaucoup trop près.", completion = "Ma bisque de tortue apaisante vous tiendra chaud par les nuits d'hiver… si vous aimez ce genre de choses.", rewards = "Vous recevrez :\n\nRecette : Bisque de tortue apaisanteBisque de tortue apaisante"},
[7341] = {title = "Un marché honnête", objective = "Bonjour, <race>. Je suis Kolark, <classe> de primes de Thunderbluff. J’ai beaucoup voyagé de par le monde et j’ai beaucoup vu.\n\nAu cours de mes voyages dans les mers du Sud, j’ai découvert ces merveilleuses flèches à pointes de thorium. Hélas, j’ai des flèches à ne plus savoir quoi en faire, mais j’ai épuisé ma provision d’obus. Aucun tauren qui se respecte ne se ferait prendre à se servir d’un arc – trop fragile. Ces flèches ne me servent à rien !\n\nJe vous propose un marché : vous m’apportez des obus en thorium, et je vous donne un nombre égal de flèches à pointes de thorium. Entendu ?", description = nil, progress = "Bonjour, <race>. Je suis Kolark, <classe> de primes de Thunderbluff. J’ai beaucoup voyagé de par le monde et j’ai beaucoup vu.\n\nAu cours de mes voyages dans les mers du Sud, j’ai découvert ces merveilleuses flèches à pointes de thorium. Hélas, j’ai des flèches à ne plus savoir quoi en faire, mais j’ai épuisé ma provision d’obus. Aucun tauren qui se respecte ne se ferait prendre à se servir d’un arc – trop fragile. Ces flèches ne me servent à rien !\n\nJe vous propose un marché : vous m’apportez des obus en thorium, et je vous donne un nombre égal de flèches à pointes de thorium. Entendu ?", completion = "Excellent ! Je suis un tauren de parole, &lt;race&gt;. Les flèches sont à vous.", rewards = "Vous recevrez :\n\nFlèches à pointe de thorium"},
[7342] = {title = "Les flèches, c'est pour les mauviettes", objective = "Vous y croyez, vous ? Les gars qui ont fait le dernier chargement de munitions de Kharanos ont cochonné le boulot ! Tout ce que nous avons comme munitions, ce sont ces saletés de flèches bonnes à rien ! Qu’est-ce que je suis censé faire avec 500 000 flèches à pointes de thorium, vous pouvez me le dire ?\n\nJe vais vous dire. Si vous pouvez m’amener des obus en thorium, je vous file ces flèches à pointe de thorium, et tout de suite ! Entendu ?", description = nil, progress = "Vous y croyez, vous ? Les gars qui ont fait le dernier chargement de munitions de Kharanos ont cochonné le boulot ! Tout ce que nous avons comme munitions, ce sont ces saletés de flèches bonnes à rien ! Qu’est-ce que je suis censé faire avec 500 000 flèches à pointes de thorium, vous pouvez me le dire ?\n\nJe vais vous dire. Si vous pouvez m’amener des obus en thorium, je vous file ces flèches à pointe de thorium, et tout de suite ! Entendu ?", completion = "Marché conclu, et cochon qui s’en dédit ! Les flèches sont à vous.", rewards = "Vous recevrez :\n\nFlèches à pointe de thorium"},
[7361] = {title = "En faveur auprès des Sombrelances", objective = "Vous avez été <chargé/chargée> de tuer les personnages Elfes de la nuit présents dans la vallée d’Alterac.\n\nTuez un Elfe de la nuit et présentez-vous à Najak Maléficas avec une Tête coupée d’Elfe de la nuit.", description = "<Najak grogne.>\n\nAvant les Elfes de la nuit, il y avait les Trolls. Les Elfes de la nuit viennent des Trolls.\n\nLeurs attaques indisciplinées contre mon peuple ne sont pas tolérables. Forteramure cherche à nous éradiquer, à effacer toute trace de ceux qui lui ont donné naissance, à lui et aux siens. Cela ne sera pas !\n\nPour chaque Elfe de la nuit que vous tuez et que vous décapitez, Najak vous accordera une faveur parmi les Sombrelances. Le récit de vos exploits se répandra dans tout Kalimdor et dans les Royaumes de l’est. Allez et servez les Sombrelances !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7362] = {title = "Allié des Taurens", objective = "Vous avez été <chargé/chargée> de tuer les personnages gnomes présents dans la vallée d’Alterac.\n\nTuez un Gnome et présentez-vous à Ravak Totem-Sinistre au donjon Loup-de-givre avec une Touffe de cheveux de Gnome.", description = "L’Ancienne m’envoie dans cette zone de guerre pour étudier les autres peuples. Je suis là pour ramasser des échantillons de Gnomes. Magatha s’intéresse à leur potentiel de survie. En vérité, les Gnomes sont minuscules et ridiculement faibles, mais ils font preuve d’une résistance considérable, en combat ou autrement.\n\nHeureusement pour vous, je suis à la recherche de forbans pour accomplir la volonté de Magatha. Rapportez-moi des touffes de cheveux de Gnome, et les Taurens vous considèreront comme <un allié/une alliée>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7363] = {title = "La condition humaine", objective = "Vous avez été <chargé/chargée> de tuer les personnages humains présents dans la vallée d’Alterac.\n\nTuez un Humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain.\n\nUn remède à la condition humaine est à portée de main !", description = "Les Humains sont détestables.\n\n<Le commandant Philips grimace.>\n\nJe suis un soldat des Loups-de-givre, mais je reste un serviteur de Sylvanas.\n\nJe profite de mon service ici pour rendre service aux sombres apothicaires de Fossoyeuse.\n\nJ’ai commencé à rassembler des bouts d’os qui pourraient servir à soigner la condition humaine.\n\nJe suis autorisé à sous-traiter cette tâche à mes subordonnés.\n\nTrouvez-les. Tuez-les. Rapportez-moi des bouts d’os.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7364] = {title = "Au service de Gnomeregan", objective = "Vous avez été <chargé/chargée> de tuer les personnages taurens présents dans la vallée d’Alterac.\n\nTuez un Tauren et présentez-vous à Dirk Lembrouille à Dun Baldar avec un Sabot de Tauren.", description = "Le Grand Bricoleur lui-même m’envoie sur ce champ de bataille pour défendre mes frères et sœurs gnomes. Nous avons entendu dire que les Taurens s’en prennent aux Gnomes, et pire que tout, ils arrachent des poignées de cheveux aux corps de ceux qui sont tombés. Il faut mettre un terme à ces atrocités. Nous allons répliquer !\n\nSoulagez-les de leurs sabots, <classe>. Apportez-moi leurs sabots ! Montrez que vous êtes <un allié/une alliée> des Gnomes.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7365] = {title = "Le requiem de Forteramure", objective = "Vous avez été <chargé/chargée> de tuer les personnages trolls présents dans la vallée d’Alterac.\n\nTuez un Troll et présentez-vous à Athramanis à Dun Baldar avec un Mojo de Troll sombrelance.", description = "Forteramure a donné l’ordre. Tous les Trolls sur le champ de bataille doivent être exterminés. Leur ridicule prétention à avoir donné naissance aux Elfes de la nuit ne doit recevoir qu’une seule réponse : la force.\n\nTuez-les et rapportez-moi leur mojo. Je répète : je veux que vous voliez leur mojo.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7366] = {title = "La pitié de l'archevêque", objective = "Vous avez été <chargé/chargée> de tuer les personnages Réprouvés présents dans la vallée d’Alterac.\n\nTuez un Réprouvé et présentez-vous au commandant Karl Philips (qui fait la navette entre le scierie et la mine) avec un Cœur de Réprouvé.", description = "L’archevêque est aussi bon que sage. Il faut être quelqu’un d’exceptionnel pour avoir pitié de tels misérables…\n\n<Le commandant Philips hoche la tête, incrédule.>\n\nIl est trop bon… trop bon.\n\nL’archevêque insiste pour que nous prenions les Morts-vivants en pitié. Nous devons leur octroyer une mort rapide et miséricordieuse. Pour cela, il nous faut leurs cœurs noirs et malades.\n\nRapportez-moi le cœur des Réprouvés pour que nous puissions les incinérer à la cathédrale de la Lumière en grande cérémonie. Hâtez-vous, <nom> !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7367] = {title = "Désarmer les mines", objective = "Trouvez l’Expert en explosifs Frostwolf et tuez-le. Lorsque ce sera fait, présentez-vous à l’Expert en explosifs Stormpike.", description = "Les Frostwolf ont piégé leurs lignes et leurs bases, <classe>. Lorsque vous entrez dans leur territoire, vous devez faire attention où vous mettez les pieds.\n\nSi vous lancez une frappe massive contre eux, vous devez détruire leur source de munitions antipersonnel – je parle de leur spécialiste en explosifs. Si vous le tuez, vous pourrez désamorcer les mines sans danger. Tant qu’il est à terre, les mines sont inoffensives.\n\nVous le trouverez probablement dans une tour près de la garnison de Glace-sang. Bonne chance !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7368] = {title = "Désarmer les mines", objective = "Trouvez l’Expert en explosifs Stormpike et tuez-le. Lorsque ce sera fait, présentez-vous à l’Expert en explosifs Frostwolf.", description = "Je sais tout sur les mines. C’est moi qui les pose sur les lignes de front, après tout.\n\nSi vous voulez neutraliser les champs de mine des Stormpike, tout ce que vous avez à faire, c'est tuer leur expert en explosifs. Ce pleutre de nain se cache sans doute dans la première tour du Champ sanglant. Débarrassez-vous-en et ces mines ne reviendront pas après avoir été désarmées.\n\nSi vous arrivez à le tuer, revenez ici et faites-le-moi savoir. Après tout, il faut savoir récompenser les bonnes actions.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7381] = {title = "Le retour de Korrak", objective = "Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le.\n\nApportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande.", description = "Korrak a été tué, certes, mais une question demeure : restera-t-il mort ? Les Trolls sont réputés pour leurs étranges sorcelleries tribales. Je ne serais pas surpris que leur chef défunt ne se relève d’entre les morts pour reprendre les rênes de son clan.\n\nVous savez quoi faire si cela se produit.\n\n<Le maître de guerre Laggrond passe son index sur son cou, un geste très éloquent.>\n\nEt cette fois, je veux sa tête. Gardez les yeux ouverts, soldat.\n\nVous pouvez disposer !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRune de rappel"},
[7382] = {title = "Korrak l'Indestructible", objective = "Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le.\n\nApportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande.", description = "Quelque chose cloche dans cette affaire… Est-ce que quelqu’un a pensé à brûler le corps de Korrak ? Ces Trolls sont prêts à tout pour ressusciter leur chef. C’est une pratique courante chez ces païens semi-humains à la peau bleue.\n\nGardez les yeux ouverts, <nom>. Ne paniquez pas si Korrak réapparaît. Si cela se produit, je veux qu'on l'exécute et qu'on le réduise en cendres.\n\nEt pour faire bonne mesure, avant d’allumer le feu, coupez-lui la tête et rapportez-la-moi.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRune de rappel"},
[7383] = {title = "La couronne de la Terre", objective = "Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar.", description = "Cependant, tout ne se passait pas parfaitement avec Teldrassil. Au début, les plans soigneusement conçus par Staghelm se déroulèrent comme il l'avait espéré, mais il y eut un petit problème, un problème auquel beaucoup des difficultés avec Teldrassil pouvaient être attribuées.\n\nJe ne vais pas m'engager dans ce propos maintenant, cependant. Vous devez aller au dernier puits de lune, au nord-ouest, dans la clairière de l'Oracle. Sous les branches de l'arbre-oracle se trouve le premier et le plus puissant de nos puits. Remplissez un flacon de son eau et revenez me voir.", progress = "En plus des druides, l'arbre-oracle et l'archidruide ont surveillé avec attention la croissance de Teldrassil. Mais bien que nous possédions une nouvelle demeure, nos vies immortelles n'étaient pas restaurées.", completion = "Être en présence de l'arbre-oracle… c'est presque voir la sagesse prendre forme. Laissez-moi continuer mon histoire…\n\nTeldrassil grandissant, l'archidruide approcha les dragons pour recevoir leur bénédiction, de la même façon que les dragons avaient béni Nordrassil dans les temps anciens. Mais Nozdormu, le Seigneur du Temps, refusa de lui donner sa bénédiction. En accord avec Nozdormu, Alexstrasza la lui refusa également, et sans leurs bénédictions, la croissance de Teldrassil fut imparfaite et imprévisible.", rewards = "Vous recevrez :\n\n"},
[7385] = {title = "Quelques litres de sang", objective = "Vous avez la possibilité d’offrir des quantités de sang prises à l’ennemi plus importantes. Je serais content d’accepter des offrandes de quelques litres, <nom>.", description = nil, progress = "Vous avez la possibilité d’offrir des quantités de sang prises à l’ennemi plus importantes. Je serais content d’accepter des offrandes de quelques litres, <nom>.", completion = "Le sang de nos ennemis a été versé. Je vais le mélanger avec celui qui a déjà été récolté. Une fois l’offrande complète, le Seigneur de glace montrera à ces chiens de Stormpike ce qu’est la colère du clan Frostwolf !", rewards = nil},
[7386] = {title = "Grappes de cristaux", objective = "Parfois, vous serez bloqué dans la bataille pendant des jours ou des semaines. Profitez de ces longues périodes d’activité pour ramasser des grappes de cristaux de tempête Frostwolf.\n\nLe Cercle accepte de telles offrandes, <nom>.", description = nil, progress = "Parfois, vous serez bloqué dans la bataille pendant des jours ou des semaines. Profitez de ces longues périodes d’activité pour ramasser des grappes de cristaux de tempête Frostwolf.\n\nLe Cercle accepte de telles offrandes, <nom>.", completion = "Bien joué, &lt;nom&gt;. Je vais me servir du pouvoir de ce charme pour augmenter la magie qui a déjà été collectée. Lorsque nous aurons assez de puissance, je focaliserai les énergies et j’appellerai le Seigneur des forêts pour aider notre cause.", rewards = nil},
[7401] = {title = "ON RECHERCHE : des Nains !", objective = "Vous avez été <chargé/chargée> de tuer les personnages nains présents dans la vallée d’Alterac.\n\nTuez des Nains et arrachez-leur la colonne vertébrale. Apportez les Colonnes vertébrales de Nains au sergent Yazra Gronde-Sang au donjon Loup-de-givre.", description = "Par ordre du sergent Yazra Gronde-Sang, tous les nains rencontrés sur le champ de bataille doivent être abattus à vue.\n\nSi vous en tuez un, arrachez sa colonne vertébrale et laissez pourrir le reste – ce tas de déchets mous servira d’avertissement à tous ceux qui oseraient s’opposer à la puissance des Loups-de-givre.\n\nAllez voir le sergent Yazra Gronde-Sang avec la preuve de vos exploits.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7402] = {title = "ON RECHERCHE : des Orcs !", objective = "Vous avez été chargé de tuer les personnages orcs présents dans la Vallée d’Alterac.\n\nTuez un Orc et remettez les Dents d’Orc au caporal Noreg Foudrepique à Dun Baldar.", description = "Par ordre du caporal Noreg Foudrepique, tous les soldats valides doivent abattre sans faire de quartier tous les Orcs qu’ils rencontrent sur le champ de bataille.\n\nLes soldats doivent prélever une défense ou une dent sur la mâchoire de leurs victimes et présenter ladite dent comme preuve de leur exploit.\n\nIl est recommandé de porter des gants épais.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7421] = {title = "La défense des Sombrelances", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7422] = {title = "Pour une poignée de cheveux", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7423] = {title = "Toujours plus de bouts d'os !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7424] = {title = "Chasse aux sabots !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7425] = {title = "La collection de mojos de Forteramure", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7426] = {title = "L'amour d'un homme", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7427] = {title = "On recherche : PLUS DE NAINS !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7428] = {title = "On recherche : PLUS D'ORCS !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7429] = {title = "Libérez Knot !", objective = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…\n\nMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?", description = nil, progress = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…\n\nMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?", completion = "Oh, merci de m'avoir libéré ! Vous – vous êtes numéro un. Tous les autres sont numéro deux – ou moins. Merci de m’avoir libéré !\n\nJe savais que j’avais autre chose à faire de ma vie que de servir d’apéritif à un ogre !", rewards = nil},
[7441] = {title = "Pusillin et l'Ancien Azj'Tordin", objective = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.\n\nSi vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas.", description = "J’ai baissé ma garde pendant un moment, <étranger/étrangère>. Dans ma hâte d’échapper aux griffes du prince déchu, j’ai été volé. Un très abject démon, le diablotin Pusillin, s’est emparé de mon livre d’incantations et de la clé qui ouvre les grandes salles d’Eldre’Thalas.\n\nLa clé ne m’intéresse plus, car j’ai échangé l’immortalité contre la liberté, mais j’ai désespérement besoin de mon livre d’incantations.\n\nTrouvez le diablotin, Pusillin, et retrouvez mon livre.\n\nFouillez le quartier de Crochebois de Hache-tripes pour trouver Pusillin.", progress = "Je ne regrette rien, étranger. La reine n’est plus depuis longtemps. Les œuvres des Shen’Dralar ont été défigurées par la folie du prince Tortheldrin. Je ne cherche que la liberté. Un moyen de fuir…", completion = "Vous l’avez trouvé ! Que ce misérable diablotin soit maudit. Hélas, mes biens matériels sont peu nombreux, mais vous pouvez choisir parmi ce que j’ai à offrir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBottes de vivacitéEpée du coureur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7461] = {title = "Folie intérieure", objective = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.\n\nEntrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.\n\nLorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour.", description = "En avez-vous entendu assez ? Êtes-vous <un homme/une femme> d’action ?\n\nCette folie doit s’achever. L’âge des immortels est révolu depuis longtemps. Détruisez les gardiens qui entourent les pylônes pour abattre le champ de force. Lorsque ce sera fait, détruisez Immol’thar. Le pouvoir du prince sera très diminué. Attaquez-le et mettez un terme à son existence. Il est temps que les esprits de cette ville trouvent le repos.", progress = "Prenez garde, aventurier. Le prince est… persuasif.", completion = "Nous vous remercions, héros.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7462] = {title = "Le trésor des Shen'dralar", objective = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !Dans l’Athenaeum, la bibliothèque, vous trouverez un vieux coffre caché sous l’escalier. Prenez-y ce que vous voulez.Vous pourrez choisir une de ces récompenses :\n\n", description = "Dans l’Athenaeum, la bibliothèque, vous trouverez un vieux coffre caché sous l’escalier. Prenez-y ce que vous voulez.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBroie-les-osCasque des taillisBottes de carex\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7463] = {title = "Rafraîchissement arcanique", objective = "Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos.", description = "Un <race> mage ! C’est merveilleux ! Je n’avais vu personne de votre espèce depuis… attendez, laissez-moi réfléchir… cinq cents ans !\n\nJ’ai quelque chose qui pourrait apaiser votre soif, mais vous devrez d’abord me rendre un service.\n\n<Lydros ricane.>\n\nUne anomalie hante Eldre’Thalas. Un élémentaire d’eau s’est installé dans l’aile est. Sa présence doit être cataloguée !\n\nRendez-vous dans le quartier de Crochebois et emparez-vous d’une partie de l’essence élémentaire de l’Hydrogénos. Revenez me voir ensuite et je vous apprendrai un sort utile.", progress = "Oui ? Je vous connais ?", completion = "Merveilleux ! Qui êtes-vous, déjà ? Oh, aucune importance. Qu’étais-je censé vous donner ? Hmm… ah oui, vous êtes un &lt;classe&gt;, cela vous sera peut-être utile.", rewards = "Vous apprendrez :\n\nInvocation d'eau\n\nVous allez être la cible du sort suivant :\n\nInvocation d'eau\n\nVous recevrez également :\n\n"},
[7481] = {title = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.", description = "Il y a plusieurs années, un maître elfe solitaire du nom de Telmius Cherche-Rêve a fui la destruction de sa terre natale avec plusieurs objets magiques elfiques antiques.\n\nNos recherches nous ont conduits aux ruines de Quel’Thalas, de l’autre côté des Steppes ardentes, à travers l’océan, jusqu’en Feralas.\n\nNous pensons que cet elfe a trouvé refuge dans les salles d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes.\n\nVous devez le trouver, <aventurier/aventurière>. Qu’il soit mort ou vif, il nous faut les connaissances qu’il détenait !", progress = nil, completion = "Une honte… une tragédie. Les objets sont perdus, selon vous ? Vous n’avez retrouvé aucune trace ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7482] = {title = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon.", description = "Il y a plusieurs années, un maître elfe solitaire du nom de Telmius Cherche-Rêve a fui la destruction de sa terre natale avec plusieurs objets magiques elfiques antiques.\n\nNos recherches nous ont conduits aux ruines de Quel’Thalas, de l’autre côté des Steppes ardentes, à travers l’océan, jusqu’en Feralas.\n\nNous pensons que cet elfe a trouvé refuge dans les salles d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes.\n\nVous devez le trouver, <aventurier/aventurière>. Qu’il soit mort ou vif, il nous faut les connaissances qu’il détenait !", progress = nil, completion = "Une honte… une tragédie. Les objets sont perdus, selon vous ? Vous n’avez retrouvé aucune trace ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7483] = {title = "Libram de Rapidité", objective = "Apportez un Libram de rapidité, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de rapidité.", description = "Maître Cherche-Rêve a perdu le Libram de Rapidité dans l’aile est. Le Libram permet de placer un sorcelet de rapidité mineur sur votre équipement. À peine mieux qu’un tour de passe-passe, en vérité…\n\nMais s’il vous intéresse, vous pourrez m’apporter le Libram avec quelques composants de base.\n\nJe crois qu’il faut aussi du sang de héros, un diamant noir sans défauts et de grands éclats brillants. Mais je peux me tromper.\n\n<Lydros hausse les épaules.>", progress = "Qu'est-ce que c'est ? J'ai énormément de classement à faire !", completion = "&lt;Lydros bâille.&gt;\n\nComme promis, voici votre arcanum de rapidité. Ne le gaspillez pas.\n\n&lt;Lydros ricane.&gt;", rewards = "Vous recevrez :\n\nArcanum de rapidité"},
[7484] = {title = "Libram de focalisation", objective = "Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-tripes pour recevoir un arcanum de focalisation.", description = "Le libram a presque intéressé l’un des plus jeunes familiers du Gardien du savoir. Pauvre petite chose, elle n’avait que quelques semaines.\n\nCeux d’entre vous qui ont un penchant pour la magie pourraient trouver cet objet intéressant.\n\nLe Libram de focalisation a été perdu dans cette aile. Je suppose que l’un des esprits bien-nés l’a en sa possession.\n\nSi vous m’apportez le Libram avec quelques grands éclats brillants, des peaux des ombres et un diamant noir parfait, je pourrai conjurer l'arcanum.", progress = "Encore vous ? Que voulez-vous, cette fois ?", completion = "Ne vous blessez pas en appliquant l’enchantement, &lt;race&gt;.", rewards = "Vous recevrez :\n\nArcanum de focalisation"},
[7485] = {title = "Libram de Protection", objective = "Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de protection.", description = "Il a pleuré comme un enfant lorsqu’il a perdu ce libram. De vous à moi, il m’est arrivé de pleurer sur des textes disparus, car il n’est pas de plus grande perte que celle du savoir et de l’histoire, mais verser des larmes sur ce méli-mélo d’incantations quasiment inutilisables ? Grotesque ! Cela m’a convaincu que le prince lui a fait une faveur le jour où il a séparé sa chair de ses os.\n\nApportez-moi le libram avec un diamant noir en parfait état, de grands éclats brillants et une couture d'abomination effilochée et je recréerai l'arcanum.\n\nOh, il doit être dans l’aile nord.", progress = "Ma patience vous évite de souffrir.", completion = "Oui oui, calmez-vous. Voilà votre arcanum, comme promis.", rewards = "Vous recevrez :\n\nArcanum de protection"},
[7486] = {title = "La récompense du héros", objective = "Allez chercher votre récompense dans le Coffre d’Hydraxis.", description = "<nom>, les services que vous avez rendus aux Seigneurs de la guerre surpassent tout ce que nous attendions des habitants de ce monde.\n\nNous ne comprenons pas la notion de gratitude, ou de récompense pour des bonnes actions, mais dans ce cas… une prime semble être à l’ordre du jour.\n\nSous les flots à la base sud de cette île vous trouverez un coffre. Il contient votre… récompense.\n\nAllez, <nom>. Allez récupérer votre récompense.", progress = nil, completion = "La voix d’Hydraxis descend depuis la surface….\n\n« Choisissez ce qui vous convient, &lt;nom&gt;. Puisse ce don vous protéger des ennemis des Seigneurs des Eaux. »", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrise de l'océanAnneau des flots\n\nVous recevrez également :\n\n"},
[7487] = {title = "Harmonisation avec le Cœur du Magma", objective = "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock.", description = "La faille s’agite, s’élargit et s’effondre tout autour de nous, <race>. À deux pas de l’endroit où je me tiens, une déchirure conduit dans les profondeurs du mont Blackrock, droit dans la gueule du seigneur du Feu.\n\nCela vous étonne ? Quelle tristesse… les races mortelles sont incapables de comprendre ce qu’elles ne peuvent ni toucher, ni voir, ni sentir.\n\nJe vous assure que le portail existe et qu’il est possible de le traverser.\n\nJ’ai piqué votre intérêt ? La procédure est simple. Pénétrez dans les profondeurs de Blackrock et récupérez un fragment du Magma. Ramenez-le-moi, et j’harmoniserai votre essence avec le portail.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nHarmonisation avec le Cœur du magma\n\nVous recevrez :\n\n"},
[7488] = {title = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas.", description = "La magicienne Lethtendris, une elfe de sang vicieuse dont la brutalité n’a d’égale que la dépendance à l’égard de la magie, a fui vers Hache-tripes. Elle a créé un objet, un filet qui lui permet de capturer les énergies magiques de l’endroit. Nous craignons qu’elle n’inflige des dommages irréparables à notre monde, s’il n’y est pas mis bon ordre.\n\nArrêtez-là, <nom>. Trouvez-la et récupérez son filet. Elle se trouve probablement non loin des satyres dans le quartier de Crochebois, à Hache-tripes. Ramenez-moi son filet, afin que sa puissance soit dispersée dans la nature…", progress = "Avez-vous le filet, <nom> ? Cette concentration d’énergie magique doit être dissipée !", completion = "Vous avez récupéré le filet ! Bien joué, &lt;nom&gt; ! Leththendris, comme beaucoup d’elfes de son espèce, était aveugle aux dangers que l’excès de magie fait courir à notre monde. Ils croient maîtriser la magie, sans réaliser qu’ils sont esclaves de leur propre dépendance. Sa mort m’attriste, mais elle était nécessaire.\n\nMerci, &lt;nom&gt;. Je vais faire en sorte que les énergies contenues dans le filet soient dispersées dans une zone assez vaste pour qu’il n’y ait pas de danger, puis je le détruirai pour éviter de nouveaux abus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTisse-savoir"},
[7489] = {title = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas.", description = "L’elfe de sang Lethtendris est allée trop loin. Elle était si désireuse d’amasser de la puissance magique qu’elle a défié ses frères, créant un objet sinistre et insidieux, un filet conçu pour siphonner les énergies magiques corrompues de Hache-tripes. En ce moment même, elle les rassemble et se prépare à les libérer sur ses ennemis.\n\nLethtendris doit être arrêtée. Elle se trouve dans le quartier de Crochebois, à Hache-tripes. Une fois que vous l’aurez vaincue, ramenez-moi son filet, afin que je puisse le confier à des elfes de sang plus raisonnables qui l’étudieront à loisir.", progress = "<nom>, avez-vous le filet de Lethtendris ?", completion = "Vous vous en êtes bien tiré, &lt;nom&gt;. Ce filet renferme d’immenses quantités de la magie de Hache-tripes, et je ne sais pas quels dégâts il aurait pu causer entre des mains aussi irresponsables que celles de Lethtendris. Sa mort m’attriste, mais je sais que vivante, elle ne se serait jamais séparée de son filet.\n\nMerci, &lt;nom&gt;. Je transmettrai le filet à des chercheurs plus responsables que Lethtendris. Ils deviendront les gardiens de son pouvoir.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nTisse-savoir"},
[7490] = {title = "Victoire pour la Horde !", objective = "Apportez la Tête d’Onyxia à Thrall à Orgrimmar.", description = "Vous avez accompli l’impossible. La mère de tous les dragons noirs gît morte à vos pieds. Prenez sa tête et apportez-la à votre Chef de guerre.", progress = "<Le masque impassible de Thrall glisse pendant une seconde lorsqu’il voit l’énorme tête d’Onyxia. Ses doigts se crispent sur le manche de Doomhammer.>", completion = "C’est une grande victoire pour la Horde, &lt;nom&gt;. Vous avez grandement honoré votre Chef de guerre. Il est temps que votre Chef de guerre vous honore.", rewards = "Vous recevrez :\n\n"},
[7491] = {title = "Pour que tous voient", objective = "Allez voir le seigneur Runthak dans la vallée de la Force.", description = "Le seigneur Runthak attend votre arrivée dans la vallée de la Force.\n\n<Thrall vous salue.>\n\nNe faites pas attendre votre public, héros.", progress = nil, completion = "Choisissez votre récompense et nous commencerons à célébrer votre glorieuse victoire !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTalisman de sang d'OnyxiaChevalière du tueur de dragonPendentif en dent d'Onyxia\n\nVous recevrez également :\n\n"},
[7492] = {title = "Camp Mojache", objective = "Parlez à Talo Thornhoof au Camp Mojache, en Feralas.", description = "Talo Thornhoof, un Ancien tauren de Feralas, a besoin d’aide. Il n’a pas donné beaucoup de détails, mais il a besoin d’agents pour une affaire à la fois délicate… et redoutable.\n\nServez la Horde, <nom>. Rendez-vous à Camp Mojache, en Feralas, et parlez à Talo.", progress = nil, completion = "Ah, il est bon de voir un &lt;classe&gt; répondre à mon appel. J’ai besoin de vos services, &lt;nom&gt;, et je crains qu’ils ne vous conduisent sur une route dangereuse…\n\nLa route de Hache-tripes.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7493] = {title = "Le voyage commence à peine", objective = "Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.\n\nJe vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.\n\nServez-vous des écailles de leur mère pou créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nPatron : Cape en écailles d'Onyxia"},
[7494] = {title = "Le bastion de Feathermoon", objective = "Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas.", description = "<nom>, nous avons besoin de votre aide en Feralas !\n\nUne magicienne renégate, Lethtendris, se cache dans les anciennes ruines elfiques d’Eldre’Thalas, que l’on appelle aujourd’hui Hache-tripes. On suppose qu’elle a avec elle un objet qui concentre de dangereuses énergies magiques. Il doit être récupéré.\n\nLatronicus Moonspear a besoin d’agents pour entrer dans Hache-tripes et prendre cet objet à Lethtendris.\n\nServez l’Alliance ! Allez voir Latronicus au bastion de Feathermoon, en Feralas.", progress = nil, completion = "Salutations, &lt;nom&gt;. Je suis content de vous voir, même si je déplore que cette rencontre ne se déroule pas dans des conditions plus plaisantes.\n\nÉcoutez-moi attentivement, car j’ai une tâche très importante pour vous…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7495] = {title = "Victoire pour l'Alliance !", objective = "Apportez la Tête d’Onyxia au généralissime Bolvar Fordragon à Stormwind.", description = "Vous avez accompli l’impossible. La mère de tous les dragons noirs gît morte à vos pieds. Prenez sa tête et apportez-la au généralissime.", progress = "Par la barbe d’Uther !", completion = "Pendant de trop longues années, j’ai été captif de son regard. Enfin, justice est faite ! L’honneur de Stormwind est restauré ! Aujourd’hui, nous célébrons une victoire glorieuse !", rewards = "Vous recevrez :\n\n"},
[7496] = {title = "Célébrer le triomphe", objective = "Allez voir le major Mattingly dans la vallée des Héros.", description = "Allez voir le major Mattingly dans la vallée des Héros, <nom>. Il vous attend.", progress = nil, completion = "Peu de gens ont l’honneur d’une telle cérémonie, &lt;nom&gt;. Choisissez votre récompense, et nous pourrons commencer la célébration.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTalisman de sang d'OnyxiaChevalière du tueur de dragonPendentif en dent d'Onyxia\n\nVous recevrez également :\n\n"},
[7497] = {title = "Le voyage commence à peine", objective = "Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.\n\nJe vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.\n\nServez-vous des écailles de leur mère pour créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nPatron : Cape en écailles d'Onyxia"},
[7498] = {title = "Garona : une étude en discrétion et en trahison", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7499] = {title = "Le codex de défense", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7500] = {title = "Les recettes de l’arcaniste", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7501] = {title = "La lumière et comment l'altérer", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7502] = {title = "Contrôler les ombres", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, mort-vivant. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7503] = {title = "La plus grande race de chasseurs", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7504] = {title = "Sainte Bolognaise : Ce que la lumière ne vous dit pas", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7505] = {title = "Le Horion de givre et vous", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7506] = {title = "Le Rêve d'Emeraude…", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, &lt;race&gt;. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.\n\nAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d'Eldre'Thalas"},
[7507] = {title = "Le guide de Dagharn", objective = "Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum.", description = "Vous avez découvert quelque chose de très important. Ce livre ne ressemble à rien de ce que vous avez déjà vu.\n\nIl semble que quelque chose ou quelqu’un soit parvenu à briser le sceau de l’Athenaeum. A l’intérieur, le texte est à peine lisible.", progress = "Ah, une de nos plus grandes compilations. Celle-ci manquait depuis une éternité.", completion = "Au marché noir, ce livre vous aurait rapporté par mal d’argent, &lt;nom&gt;. Surtout parce que son sceau protecteur était brisé, exhibant les secrets de la mise à mort des dragons à toutes les personnes assez intelligentes pour assimiler les connaissances contenues dans ces pages sacrées.\n\nUne grande récompense est à l’ordre du jour… Ou plus exactement, une récompense qui va exiger de vous un effort immense.", rewards = "Vous recevrez :\n\n"},
[7508] = {title = "Forger Quel'Serrar", objective = "Donnez la Lame elfique inachevée au Gardien du savoir Lydros.", description = "Si vous voulez vous charger de cette tâche, présentez la lame inachevée à Lydros.", progress = "Excellent, commençons tout de suite…", completion = "Si vous parvenez à entrer dans le repaire du dragon, à chauffer la lame à son souffle brûlant et à la tremper dans son sang, je la lierai à vous.", rewards = nil},
[7509] = {title = "Forger Quel'Serrar", objective = "Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.\n\nAvant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.\n\nSi vous y parvenez, Quel’Serrar sera à vous.", description = "Apportez la lame ancienne brute dans le repaire d’Onyxia et combattez-la.\n\nPour chauffer la lame, faites preuve de ruse. Au cours du combat, elle cherchera certainement à vous incinérer à l’aide de son souffle brûlant. Vous devez placer la lame ancienne brute à proximité, et espérer que son souffle chauffera la lame. Si vous survivez, prenez la lame chauffée et achevez le dragon.\n\nPlongez la lame chauffée dans son cadavre incandescent pour créer la lame ancienne trempée.", progress = "Peut-être qu’un jour, un autre portera la lame prismatique.", completion = "&lt;Lydros murmure quelque chose d’inintelligible.&gt;\n\nComme promis, &lt;classe&gt;, voici la lame de Quel’Serrar.", rewards = "Vous recevrez :\n\nQuel'Serrar"},
[7521] = {title = "Tonneraan le Cherchevent", objective = "Pour libérer Tonneraan le Cherchevent de sa prison, vous devez présenter au généralissime Demitrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du seigneur du Feu.", description = "Je vous ai dit tout ce que je sais, <nom>. C'est à vous de trouver l'élémentium. C'est à vous de détruire la forme physique du seigneur du Feu.\n\nSi vous y parvenez, vous recevrez la bénédiction de Tonneraan.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7522] = {title = "Examiner le Calice", objective = "Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian.", description = "Examinez le Calice de la renaissance, <mortel/mortelle>. C'est grâce à lui que le Cherchevent reviendra !", progress = nil, completion = nil, rewards = nil},
[7541] = {title = "Un service pour la Horde", objective = "Il faudra du temps pour que nos savants étudient le pendentif que vous nous avez rapporté. J'aimerais vous offrir un petit témoignage de notre reconnaissance, pour le service que vous avez rendu à la Horde.\n\nMerci, <nom>. Vos actions vous font honneur.", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau d'allégeanceAnneau de Lonetree\n\nVous recevrez également :\n\n"},
[7561] = {title = "Éveille-toi, Lame-tonnerre !", objective = "Présenter la Lame du baiser du vent dormante au généralissime Demitrian.", description = "Vous avez vaincu le Cherchevent. Prenez la lame endormie et obligez cet immonde menteur, Demitrian, à utiliser les matériaux que vous lui avez fourni pour sa trahison. Obligez-le à éveiller Lame-tonnerre.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nThunderfury, Blessed Blade of the Windseeker DEPRECATED"},
[7562] = {title = "Mor'zul Bloodbringer", objective = "Parler à Mor'zul Bloodbringer dans les Steppes ardentes.", description = "<nom>, vous avez approfondi les arts ténébreux. Votre maîtrise des habitants d’outremonde est impressionnante… Vous êtes peut-être prêt à lier l’un des redoutables destriers de l’effroi.\n\nLe rituel qui permet d’appeler la bête consomme énormément de puissance et de ressources, mais si vous désirez dominer cette monture épique, allez voir Mor'zul Bloodbringer. Il campe près de l’Autel des tempêtes dans les Steppes ardentes.\n\nAllez, <nom>. Cette quête sera périlleuse, mais un démoniste de votre puissance ne recule pas devant le danger !", progress = nil, completion = "Salutations, &lt;nom&gt;, et bienvenue. Êtes-vous venu étudier près de l’Autel des tempêtes, peut-être pour utiliser son énergie dans un but caché…\n\nÀ moins que… vous ne veniez me parler ? Oui, ce doit être ça.\n\nVous voulez maîtriser un destrier de l’effroi ? Ce n’est pas une tâche facile. Cela va vous coûter cher en sang, en sueur… et en or, bien entendu. Mais les destriers de l’effroi de Xoroth méritent bien que l’on paye un tel prix. Écoutez…", rewards = "Vous recevrez :\n\n"},
[7563] = {title = "Rage de sang", objective = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes.", description = "Les destriers de l’effroi vivent sur un autre monde, sur les plaines enflammées de Xoroth. Pour lier l’une de ces bêtes, vous devez invoquer des glyphes d’une grande puissance. Je peux vous les noter sur un parchemin, mais pour cela, il me faudra une encre spéciale.\n\nDans le lointain Berceau-de-l'Hiver vit une race de créatures-chouettes. Jadis, elles étaient pures, mais elles ont été rendues folles par les émanations démoniaques de la gorge du Sombre murmure. Elles errent dans la neige, frénétiques.\n\nJ’ai besoin de leur sang pour écrire sur votre parchemin.", progress = "Avez-vous vu les êtres-chouettes enragés, <nom> ? La magie de ces créatures est puissante, et elle se concentre dans le sang qui court dans leurs veines torturées.", completion = "Ah, très bien. Je vais le distiller pour en faire de l’encre, et l’utiliser pour rédiger le parchemin que je vous ai promis. Je m’en garderai peut-être un peu pour moi, car à ce que j’ai entendu dire, c’est un euphorisant…", rewards = "Vous recevrez :\n\n"},
[7564] = {title = "Gorzeeki Wildeyes", objective = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes.", description = "Mon serviteur, Gorzeeki, est un alchimiste de quelque talent. Il pourra préparer l’encre dont vous avez besoin pour votre parchemin. J’ai préparé le sang que vous avez récupéré. Portez-le à Gorzeeki et il se mettra au travail.", progress = "Vous avez quelque chose pour moi ? Ce n’est pas une grosse araignée bien juteuse, par hasard ? Ou peut-être un cafard ? J’espère qu’il est encore vivant… J’aime bien les mâcher quand ils sont encore vivants…", completion = "Oh, du sang. Ça doit venir de maître Mor’zul. Il adore ce truc, surtout quand il est répandu. Moi, je le préfère dans les veines d’un petit rongeur. Comme ça, il reste chaud… jusqu’à ce que vous en ayez envie.\n\nC’est un sang puissant. Mor’zul doit être en train de préparer un autre parchemin pour invoquer un destrier de l’effroi ! Comme c’est excitant !\n\nMais si c’est ça, c’est vous qui allez accomplir le rituel… Il va vous falloir bien d’autres choses que du sang, mon ami.", rewards = "Vous recevrez :\n\n"},
[7581] = {title = "Les ancrages de la prison", objective = "Rendez-vous à Hache-tripes en Feralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.", description = "Vous devez récupérer les ancrages de la prison du garde funeste sur des démons secondaires.\n\nLe sang des satyres Follengeance qui occupent Hache-tripes conviendra parfaitement. Leur sang coagulé liera les fragments des Hederine et alimentera la prison de cristal.", progress = "Il faut impérativement utiliser le sang des satyres Follengeance.", completion = "Ah, excellent travail. Ce sang annulera les défenses magiques du garde funeste.", rewards = "Vous recevrez :\n\n"},
[7582] = {title = "Les parois de la prison", objective = "Rendez-vous à la gorge du Sombre murmure, dans le Berceau-de-l'Hiver, et récupérez 5 Larmes de l’Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.", description = "Les démons Hederine qui occupent les contreforts du mont Hyjal produisent de puissants poisons corrompus. Si on les laisse mûrir, ils durcissent et deviennent des cristaux d’antimagie denses, connus sous le nom de Larmes de l’Hederine.\n\nMême la puissance immense d’un garde funeste ne suffira pas à briser les parois d’une prison construite dans cette substance. Allez à la gorge du Sombre murmure, au Berceau-de-l'Hiver, et récupérez des Larmes.", progress = "Les Hederine ne vous donneront pas volontairement leurs précieuses gemmes, <nom>.", completion = "Je n’ai plus qu’à combiner le sang des Follengeance avec ces cristaux et la prison sera prête à l’emploi.", rewards = "Vous recevrez :\n\n"},
[7583] = {title = "Suppression", objective = "Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste.\n\nServez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l’impossible pour éviter d’être capturé.\n\nSi vous réussissez, amenez le garde funeste emprisonné à Levadre à la Balafre impure.", description = "La prison est prête, mais le plus difficile reste à faire.\n\nVous devez trouver un Commandant de la garde funeste dans la Balafre impure, puis le capturer grâce à cette prison de cristal.\n\nPrenez garde ! Les gardes funestes sont des adversaires aussi dangereux que rusés. Votre gibier tentera de vous détruire dès que vous aurez commencé le rituel d’emprisonnement. Il se débattra et fera tout pour éviter la captivité.\n\nIl se concentrera sur vous et sur vous <seul/seule>, <nom>. Pour cette raison, je vous conseille de partir avec des compagnons capables de vous garder en vie !", progress = "Hrm ? Hé bien ?", completion = "Vous avez accompli mes volontés. Vous êtes prête à apprendre à invoquer et à contrôler la bête.", rewards = "Vous apprendrez :\n\nRituel de malédiction\n\nVous allez être la cible du sort suivant :\n\nRituel de malédiction\n\nVous recevrez également :\n\nTome du Sacrifice"},
[7601] = {title = "Les Commandements de Niby", objective = "Parlez à Démonet à Gangrebois.", description = "Si vous voulez que je vous apprenne les secrets de l’invocation d’un serviteur infernal, vous devez détruire Kroshius et me rapporter le noyau infernal pris dans ses restes ardents. Ce n’est pas aussi simple qu’il y paraît. Kroshius est pratiquement éteint. Vous devez rallumer son cadavre et le relever de ses propres décombres. Pour cela, il vous faudra récupérer des éléments sur d’autres entités démoniaques.\n\nDémonet vous donnera les détails.", progress = nil, completion = "Oh, la barbe... Ça recommence…", rewards = nil},
[7602] = {title = "La gangressence parfaite", objective = "Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.\n\nLes satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.\n\nRécupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois.", description = "Si vous devez ranimer Kroshius, vous aurez besoin de Gangrefeu. Je peux en fabriquer, mais j'ai besoin de quelques composants alchimiques.\n\nVous devez me rapporter des gangressences parfaites de trois régions du monde distinctes.\n\nLes satyres Legashi d'Azshara possèdent le premier type d'essence ; les légionnaires de Jaedenar le second, et les gangregardes sentinelles des Terres foudroyées le troisième.\n\nRapportez-moi chacune de ces essences et je créerai le Gangrefeu qui vous permettra de ranimer Kroshius.", progress = "Ne le dites à personne, mais Niby est un peu simplet.", completion = "Laissez-moi une minute, et je combinerai les essences pour en faire du Gangrefeu.", rewards = "Vous recevrez :\n\n"},
[7603] = {title = "Le noyau infernal de Kroshius", objective = "Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.\n\nRapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois.", description = "L'Infernal Kroshius gît en tas au nord-est, dans le Val Grêlé. Prenez ce Gangrefeu et utilisez-le sur ses restes. Cela devrait le ranimer.\n\nA ce stade, je pense qu'il vous tuera, ainsi que toutes les personnes présentes. D'ailleurs, n'oubliez pas de vous faire accompagner de quelques amis, car ils vous seront bien utiles...\n\nSi par miracle vous parvenez à tuer Kroshius, prenez son noyau infernal et rapportez-le à Niby.", progress = "Vous vous êtes perdu ?", completion = "Un marché est un marché ! Vite, prenez ça et écrivez-le. Moi, je n'ai pas le temps ! Ma plus grande invocation est en cours !", rewards = "Vous apprendrez :\n\nInferno\n\nVous allez être la cible du sort suivant :\n\nInferno\n\nVous recevrez également :\n\nEclat de la Flamme verte"},
[7604] = {title = "Un contrat contraignant", objective = "Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron.", description = "Le soussigné déclare par la présente que le lingot de sulfuron qu'il livre à la Confrérie du Thorium (CT SARL) est authentique et n'est pas une imitation. Le soussigné reconnaît de même que tous les dommages qu'<il/elle> pourrait subir en tentant de modeler, forger, trouver, créer, vendre ou manger du sulfuras n'est pas de la responsabilité ou une faute de CT SARL.\n\nEn signant ce contrat, vous en acceptez tous les termes.\n\n_________________\n\nSignatureVous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPlans : Marteau en sulfuron"},
[7621] = {title = "Un avertissement", objective = "<classe> vous allez subir une série d’épreuves au cours desquelles tous vos talents seront poussés à leurs limites.\n\nÉcoutez attentivement mon histoire.\n\nAttention, vous devrez achever cette tâche seul. Je conseille à vos alliés de rester à distance. Toute intervention extérieure entraînera un châtiment sévère.\n\nLe Destin vous a conduit ici, vous et vous seul. Battez-vous avec honneur. Que la Lumière vous protège !", description = nil, progress = nil, completion = nil, rewards = nil},
[7622] = {title = "L’équilibre de la Lumière et de l’Ombre", objective = "Sauvez 50 Paysans avant que 15 d'entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havenfire.\n\nConsultez le Panneau des morts pour voir combien de paysans ont été tués.", description = "Vous devez accomplir ce que je n’ai pas pu faire : sauver les paysans qui ont été tués alors qu’ils fuyaient Stratholme.\n\nIls marcheront vers la lumière, et vous devez veiller à ce qu’ils survivent. S’ils sont trop nombreux à tomber, vous échouerez et notre existence maudite continuera.\n\nToutes les prières, toutes les capacités, tous les sorts que vous connaissez seront mis à l’épreuve. Puisse la Lumière vous protéger, <nom>.", progress = nil, completion = "Votre ténacité et votre courage sont extraordinaire, &lt;classe&gt;. Vous avez mérité de porter l'Eclat de Nordrassil. Il ne vous reste plus qu'une tâche à accomplir : retrouver l'Œil de l'ombre. Parcourez le monde.", rewards = "Vous recevrez :\n\nEclat de Nordrassil"},
[7623] = {title = "Le seigneur Banehollow", objective = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.\n\nServez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow.", description = "Mor’zul me dit que vous voulez ouvrir un portail vers Xoroth. Pour cela, vous aurez besoin de Poussière d’étoiles xorothienne. Ce n’est pas simple à trouver sur Azeroth !\n\nMais une créature pourrait pour aider : le seigneur Banehollow, à Jaedenar, le siège du Conseil des ombres. Allez lui parler, et il se séparera peut-être d’un peu de poussière.\n\nMais si vous allez à Jaedenar, vous aurez sans doute besoin de porter sur vous le parfum maléfique du Conseil des ombres. Pour cela, je vous propose mes potions des ténèbres, mais elles ne sont pas bon marché…", progress = nil, completion = "Ma patience couvre des millénaires, &lt;classe&gt;. Mais ne vous imaginez pas que cela vous donne droit à plus d’une seconde de mon temps…", rewards = "Vous recevrez :\n\n"},
[7624] = {title = "Ulathek le traître", objective = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar.", description = "Vous voulez entrer dans mes bonnes grâces ? Tuez pour moi.\n\nMon serviteur, Ulathek, ne cesse de ramper devant moi, tout en complotant avec le seigneur Hel’nurath sur Xoroth. Hel’nurath compte usurper mon pouvoir ici, et Ulathek est son espion…\n\nProuvez que vous êtes à mon service et pas à celui de mes rivaux. Allez trouvez Ulathek dans ses quartiers du Fort des Ombres, à l’ouest d’ici. Dites-lui que je connais son secret et regardez la terreur l’envahir. Ensuite, apportez-moi son cœur !", progress = "Le goût du coeur d’Ulathek est déjà sur mes lèvres. La chair d’un traître est si douce…", completion = "Ah, magnifique ! Après avoir pourri pendant une semaine, ce cœur sera un mets de choix ! J’enverrai peut-être chercher la tête d’Ulathek pour qu’il puisse me regarder manger…\n\nVous m’avez rendu un service, &lt;classe&gt;. Je tolérerai votre présence. Pendant un moment...", rewards = "Vous recevrez :\n\n"},
[7625] = {title = "Poussière d'étoile xorothienne", objective = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes.", description = "Vous cherchez de la poussière d’étoiles xorothienne ? Vous voulez ouvrir un portail vers Xoroth, le domaine de mon rival, Hel’nurath ? Seriez-vous en train de vous préparer à voler l’un de ses précieux destriers de l’effroi ?\n\nTrès bien. Mon serviteur, Ur’dan, a une réserve de poussière d’étoile xorothienne. Vous pouvez en disposer… Si vous en payez le prix.", progress = "Avez-vous été à Jaedenar, <nom> ? Le seigneur Banehollow vous a-t-il donné de la Poussière d’étoiles ?", completion = "C’est bien ça ! J’ai du mal à croire que vous l’ayez obtenu ! Vous devez avoir passé un marché épouvantable avec le Seigneur de l’effroi, payé une fortune, ou les deux !\n\nMorzul aura son encre très bientôt et il pourra enfin faire le parchemin orné de glyphes. Ensuite, vous pourrez ouvrir un portail vers Xoroth et vous emparer de l’un de ces fameux destriers de l’effroi !", rewards = "Vous recevrez :\n\n"},
[7626] = {title = "La Cloche de Dethmoora", objective = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes.", description = "Une Cloche de Dethmoora, qui tire son nom du défunt démoniste Dethmoora Darkeyes, est l’un des trois outils indispensables à la création d’un Cercle de lien supérieur. Lorsqu’elle est en harmonie avec la Roue et la Chandelle, ces trois objets concentrent d’immenses quantités d’énergie magique.\n\nGorzeeki, mon serviteur, peut fondre une telle cloche, mais pour cela, il a besoin de nombreux élixirs de puissance de l'ombre. Procurez-vous ces élixirs auprès d’un alchimiste et apportez-les à Gorzeeki.", progress = "Vous avez ces élixirs, <nom> ? Mor’zul m’a dit que vous aviez besoin d’une Cloche de Dethmoora, et il faut beaucoup de puissance de l'ombre pour en fabriquer !", completion = "Très bien ! J’espère que vous n’avez pas eu trop de mal à vous procurer ces élixirs. Parfois, les alchimistes se montrent ridiculement attachés à leurs créations.\n\nJe vais fabriquer la cloche et la garder jusqu’à ce que vous soyez prêt pour le rituel.", rewards = "Vous recevrez :\n\n"},
[7627] = {title = "La Roue de la Marche noire", objective = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes.", description = "Une Roue de la Marche noire confine et dirige l’énergie que nécessite le Cercle de lien supérieur. Pour que Gorzeeki construise une telle roue, il aura besoin de grands éclats brillants fournis par un enchanteur et de minerai de sombre fer fournis par un maître mineur.\n\nIl ne vous reste plus qu’à vous les procurer et à les apporter à mon serviteur.", progress = "La Roue de la Marche noire n’est pas facile à fabriquer, et nécessite beaucoup de matériel. Avez-vous tout ce qu’il me faut ?", completion = "Nous y voilà ! J’ai entendu dire que l’on ne trouvait ce minerai que dans les profondeurs de Blackrock, et je suis sûr que les éclats n’ont pas été faciles à obtenir non plus. La détermination dont font preuve les démonistes ne cesse jamais de m’impressionner. Si vous consacriez autant d’énergie à attraper des cafards, nous pourrions faire un festin magnifique !\n\nPardon, je digresse. Je vais fabriquer la roue, et je la conserverai jusqu’à ce que vous soyez prêt pour le rituel.", rewards = "Vous recevrez :\n\n"},
[7628] = {title = "La Chandelle de l'apocalypse", objective = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes.", description = "Une Chandelle de l’apocalypse conserve du feu et le dirige contre ceux qui voudraient interrompre le rituel. Lorsque vous créerez votre Cercle de lien supérieur, si votre chandelle est allumée, tous les démons vagabonds seront brûlés par ses flammes !\n\nContenir le feu n’est pas simple, et nécessite l’essence que recèlent les écailles d’un dragon noir. Récupérez de telles écailles et apportez-les à Gorzeeki.", progress = "Avez-vous ces écailles de dragon, <nom> ? Je ne commencerai à travailler sur la chandelle que lorsque je les aurai… Sans cela, je risque de faire sauter tout le camp !", completion = "Ah, très bien. J’en ai besoin pour contenir le feu de la chandelle. Maintenant que je les ai, je peux la fabriquer. Je la garderai jusqu’à ce que vous soyez prêt à commencer le rituel.", rewards = "Vous recevrez :\n\n"},
[7629] = {title = "Livraison de diablotin", objective = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes.", description = "Il reste une étape pour réaliser le parchemin de Mor’zul. J’ai besoin de papier imprégné de Poussière d’étoiles xorothienne. Et… j’ai peur de ne pas pouvoir la fabriquer ici. Je n’ai pas l’équipement nécessaire !\n\nMais il existe un laboratoire d’alchimie qui contient tout ce qu’il nous faut. C’est à la Scholomance, sur l’île de Caer Darrow dans les Maleterres.\n\nJe ne peux pas faire le voyage, mais tenez, prenez cette bouteille. Elle contient un diablotin très intelligent. Libérez-le dans le laboratoire d’alchimie et il préparera le papier.", progress = "Avez-vous été à la Scholomance, <nom> ? Le diablotin a-t-il imprégné le parchemin avec la Poussière d’étoiles ?", completion = "Ah, bien. J’eevee a preparé le parchemin. Comment était la Scholomance ? Un endroit charmant, n’est-ce pas ? Et les cafards y sont particulièrement délicieux.\n\nBien joué, &lt;nom&gt;, et merci de m’avoir ramené ma bouteille. Je l’ai depuis longtemps… et elle n’est pas à vendre !", rewards = "Vous recevrez :\n\n"},
[7630] = {title = "L'arcanite", objective = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes.", description = "À présent que la Cloche, la Roue et la Chandelle sont prêtes, vous avez besoin de quelqu’un pour les préparer au rituel. J’ai un diablotin qui connaît les procédures… Il vous faudra juste un récipient pour le transporter sur place.\n\nJe peux vous en vendre un, mais pour le fabriquer, il me faut de l’arcanite. En avez-vous ? Sinon, vous devriez trouver un alchimiste pour vous en faire.\n\nRevenez me voir quand vous aurez l’arcanite, et je vous vendrai le diablotin en bocal !", progress = "Avez-vous l’arcanite, <nom> ? Dès que je l’aurai, je fabriquerai un nouveau bocal pour le diablotin J’eevee.", completion = "Vous l’avez ! Bon travail ! Maintenant, je peux créer la magnétite. Quand vous serez prêt à lancer le Cercle d'invocation supérieure, vous aurez besoin de magnétite pour que le rituel ne fasse pas long feu.", rewards = "Vous recevrez :\n\n"},
[7631] = {title = "Le destrier de l'effroi de Xoroth", objective = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit.\n\nObjet fourni : \n", description = "Tous les préparatifs sont terminés. À présent, vous devez accomplir le rituel qui créera un Cercle de lien supérieur, puis utiliser le Parchemin de Xoroth pour ouvrir un portail vers Xoroth.\n\nToutes les instructions figurent sur ce document. Étudiez-le attentivement, car vous ne devez en dévier sous aucun prétexte si vous voulez réussir.\n\nJe vous souhaite bonne fortune, <nom>. Et puisse l’âme de vos ennemis trouver le chemin de votre bourse !", progress = nil, completion = "Vous avez triomphé de l'esprit du destrier de l'effroi. Ses flancs spectraux irradient la rage, mais vous savez que l'âme de la bête vous appartient.\n\nIl murmure de sombres connaissances dans votre esprit, et vous instille le moyen d'invoquer un destrier de l'effroi.", rewards = "Vous apprendrez :\n\nInvocation d'un destrier de l'effroi\n\nVous allez être la cible du sort suivant :\n\nApprendre Invocation d'un Destrier de l'effroi\n\nVous recevrez également :\n\n"},
[7632] = {title = "La feuille ancienne", objective = "Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, <nom>, le monde est vaste.", description = "La surface de la feuille brille d’un vert vif. Sa surface est extrêmement rugueuse, avec de nombreuses rides et nervures.\n\nVous estimez qu’elle vient de quelque chose d’ancien et de puissant.\n\nVous devriez peut-être trouver son premier propriétaire ?", progress = "<Vartus grogne.>", completion = "Bien sûr que je reconnais mes propres feuilles. Regardez-la ! Elle est toujours impeccable ! C’est très gentil de me la rendre, &lt;classe&gt;.\n\nPeut-être pourrons-nous nous rendre mutuellement service.", rewards = "Vous recevrez :\n\n"},
[7633] = {title = "Une rencontre", objective = "Votre dilligence et votre intégrité ont été notées, <classe>.\n\nNous sommes les Anciens, les protecteurs de cette forêt qui fut grande, autrefois. Nos formes physiques ont été détruites il y a dix mille ans lorsqu’Archimonde et la Légion ardente ont marché sur le mont Hyjal. Malgré tout, nos esprits demeurent intacts.\n\nNous avons des tâches à vous proposer. Des tâches qui vous donneront accès à nos secrets, si vous les accomplissez.\n\nSi vous y parvenez, revenez à ce rocher et nous répondrons à votre appel.", description = nil, progress = nil, completion = nil, rewards = nil},
[7634] = {title = "Feuille d'Ancien cousue de tendons", objective = "L'Ancien Hasat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois", description = "Salutations, <classe>. Je suis Hastat, Ancien du Savoir. Je conserve des connaissances perdues il y a des millénaires.\n\nConvenablement liée, une de mes feuilles peut servir de carquois pour un arc tel que nul n’en a fabriqué depuis dix mille ans. Accompagné d’un arc des Anciens, il peut donner des pouvoirs inimaginables.\n\nRevenez ici avec un tendon pris sur un dragon bleu adulte et ce carquois sera vôtre.", progress = "Bienvenue, jeune <classe>.", completion = "Que ces feuilles protégent vos flèches de tout mal. Que vos flèches touchent juste. Que les ennemis de notre monde soient écrasés.", rewards = "Vous recevrez :\n\nFeuille d'Ancien cousue de tendons"},
[7635] = {title = "La bonne corde", objective = "L’Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois.", description = "Vartus vous offre le bâton nécessaire pour créer un Arc des anciens ? Très bien, mais je suis le seul à pouvoir enchanter la corde indispensable pour l'achever.\n\nC’est une tâche simple, petit être. Tuez un dragon noir adulte et prenez l'un de ses tendons. Ramenez-le-moi, et je l’enchanterai de manière à en faire une corde d’arc presque indestructible.", progress = "Je suis certain que vous n’aurez guère de mal à trouver et à tuer un dragon noir, <nom>. Ne me faites pas perdre mon temps en vains bavardages.", completion = "Ce dragon était réellement abominable. Ce tendon empeste le mal.\n\nDonnez-moi un moment pour le purifier et appliquer les enchantements idoines.", rewards = "Vous recevrez :\n\nTendon de dragon noir enchanté"},
[7636] = {title = "Le bâton des Anciens", objective = "Vous devez trouver et tuer quatre corrupteurs démoniaques :\n\nSimona la Séductrice.\n\nKlinfran l’Enragé.\n\nSolenor le Tueur.\n\nArtorius le Néfaste.\n\nDétruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois.\n\nVous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire.\n\nVous DEVEZ agir seul.", description = "Les agents de la Légion ardente sont toujours actifs dans notre monde, <classe>. Ils corrompent tout ce qu’ils touchent. En leur présence, la nature se flétrit et pleure.\n\nVous devez traquer ces corrupteurs démoniaques et les détruire, <nom>. Mais attention, vous devez agir seul. Ils fuiront s’ils voient un groupe. En revanche, si vous êtes seul, ils tenteront leur chance et essayeront de vous tuer. Vous devez les frapper, changer leur arrogance en souffrance.\n\nJe vous donne un morceau de mon écorce, les inscriptions qui s’y trouvent vous conduiront à vos cibles.", progress = "Ne vous laissez pas tromper par leurs déguisements !", completion = "Vous nous avez bien servi, &lt;nom&gt; ! Prenez ce bâton et combinez-le à la corde d'arc que sait fabriquer Stoma. Ensemble, ils formeront une arme très redoutable.", rewards = "Vous recevrez :\n\nBâton runique gravé des Anciens"},
[7637] = {title = "L'accent sur le sacrifice", objective = "Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or.", description = "Pour vous préparer à cette tâche, vous devez vous faire preuve de jugeote et d'esprit de sacrifice… en mettant l’accent sur ce dernier aspect.\n\nVous devez vous procurer l’Encensoir d’exorcisme du grand prêtre Rohan. Bien sûr, il ne vous servira que pour de bonnes et justes raisons, mais vous devrez néanmoins verser une compensation à son propriétaire.\n\nRendez-vous à Ironforge et parlez au grand prêtre. Le convaincre de le séparer de son encensoir vous coûtera une forte somme, mais cela montrera votre esprit de sacrifice.\n\nAllez maintenant, <nom>, le temps presse.", progress = "Je vous salue, noble <classe> ! J’ai garni mon encensoir de l’encens le plus frais et je l’ai béni par trois fois. Votre donation nous permettra non seulement de fabriquer un nouvel encensoir, mais aussi de compléter nos réserves de nourriture pour les nécessiteux d’Ironforge.", completion = "Soyez béni, ami &lt;classe&gt;. Votre don est largement supérieur à ce qui était nécessaire. Votre sacrifice nous aidera à récupérer ce que nous avons perdu, mais aussi à soulager les misères des pauvres gens d’Ironforge.\n\nÀ présent, laissez-moi m’assurer que j’ai préparé cet encensoir de manière à ce qu’il réponde à vos besoins…", rewards = nil},
[7638] = {title = "Le seigneur Grayson Shadowbreaker", objective = "Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.", description = "<nom>, le temps est venu d’apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis un moment… votre destrier !\n\nAllez parler au seigneur Grayson Shadowbreaker, ici même, dans le Quartier de la cathédrale, à Stormwind. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.\n\nJ’espère que votre épreuve se passera bien. Pour la Lumière, noble <frère/sœur> !", progress = nil, completion = "Je suis content de vous voir, &lt;nom&gt;. Je sais que vous attendiez depuis longtemps que je vous explique comment vous procurer votre destrier, et le moment est venu.\n\nVous allez affronter de nombreuses épreuves, mais l'essentiel est que vous ayez la volonté de surmonter les obstacles qui vous attendent. Ce n’est pas un exercice – vous avez progressé bien au-delà des simples tests qui ont ponctué votre éducation. Vous devrez arracher votre futur compagnon aux griffes même du mal que vous avez passé votre vie à combattre\n\nÉcoutez bien, car votre heure a sonné !", rewards = "Vous recevrez :\n\n"},
[7639] = {title = "Des preuves de jugement", objective = "Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind.", description = "Prenez cet encensoir, avec ma bénédiction. Je l’ai utilisé lors de plusieurs exorcismes, et il vous rendra de grands services dans les tâches ardues qui vous attendent.\n\nRetournez voir le seigneur Grayson Shadowbreaker à Stormwind, <nom>. Votre quête continue avec lui.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7640] = {title = "Exorciser Val-Terreur", objective = "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.", description = "J’ai ajouté dans l’encensoir une pincée de la terre du sol corrompu de Val-Terreur, dans les Maleterres de l’est. Vous vous en servirez pour repérer les régions qui montrent des signes de troubles et de perturbations spirituelles. Cherchez les auras vertes qui imprègnent le sol là où le monde physique ploie sous les souffrances du monde des esprits. Puis servez-vous de l’encensoir pour chasser les esprits mauvais.\n\nLorsque vous aurez jugé assez d’esprits, nous serons prêts à continuer.", progress = "C’est bon de vous revoir, <nom>. Votre tâche à Val-Terreur est-elle accomplie ?", completion = "Très bien, &lt;nom&gt;. Passer le jugement de la Lumière sur ceux qui vivent dans les ténèbres est une tâche que nous devons accomplir avec zèle et énergie. Votre sacrifice à Ironforge et le jugement des esprits de Val-Terreur correspondent à cet idéal.\n\nPour votre prochaine étape, vous aurez besoin des deux. Vous allez devoir récupérer l’esprit d’un destrier mort qui, pour l’heure, sert le chevalier de la mort Ravassombre.", rewards = "Vous recevrez :\n\n"},
[7641] = {title = "L'œuvre de Grimand Elmore", objective = "Parlez à Grimand Elmore dans le Quartier des nains de Stormwind.", description = "Sans un caparaçon correct, un destrier de paladin n’est qu’un animal de bât. Pour créer un caparaçon, il faut les matériaux les plus précieux possibles. Le processus impose qu’il soit également harmonisé avec le monde des esprits.\n\nPour commencer, <nom>, nous allons nous occuper de sa fabrication. L’un des plus grands artisans vivants habite dans le Quartier des nains de Stormwind. Il s’appelle Grimand Elmore. Son travail n’est pas bon marché, mais il est à la hauteur de cette tâche. Allez lui parler.", progress = nil, completion = "Bien le bonjour, mon gars. Le seigneur Shadowbreaker m’a prévenu que vous alliez me rendre une petite visite. Je suis tout disposé à fabriquer votre caparaçon, mais autant vous le dire tout de suite, ce ne sera ni facile, ni bon marché.\n\nToutefois, je le dis tout net, et Grayson ne me contredira pas, vous ne trouverez pas de meilleurs caparaçons que les miens dans tout Azeroth.", rewards = "Vous recevrez :\n\n"},
[7642] = {title = "Une ribambelle d'objets", objective = "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind.", description = "Vous aurez besoin de quatre choses pour le caparaçon : de l’étoffe runique pour la doublure, des barres d’arcanite pour l’armure, des larmes d’Arthas pour l’accord spirituel et de l’eau sacrée de Stratholme pour l’imprégnation spirituelle. Ah, non, en fait, cinq choses… Et de l’or pour me payer. Il couvrira les dépenses pour mon travail, une selle et des étriers faits main.\n\nQuand vous aurez tout cela, je pourrai finir le caparaçon. En attendant, voilà quelques petites choses que je peux faire en attendant, pendant que vous vous chargez de récupérer le matériel.", progress = "Ah, <nom>. Je ne peux pas finir votre caparaçon sans toutes les choses que j’ai mentionnées. Avez-vous trouvé tout ce qui nous manque ?", completion = "Bien… c’est exactement ce qu’il me faut. Vous êtes un &lt;classe&gt; plein de ressources, pas vrai ?\n\nParfait, allons finir ce caparaçon !", rewards = nil},
[7643] = {title = "L'ancien esprit équin", objective = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer.\n\nEnsuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse.", description = "Votre caparaçon aura besoin d’une bénédiction particulière, prononcée par un esprit approprié. Hache-tripes abrite une telle entité, un Ancien esprit équin. Malheureusement, il est entre les mains d’un tréant corrompu, Tendris Crochebois. Jugez cet être infâme, <nom>.\n\nEt sachez que la liberté ne suffira pas à l’esprit équin. Vous devrez l’apaiser, avant de recevoir sa bénédiction. Pour cela, vous aurez besoin d’une nourriture très particulière. Allez à Southshore et parlez-en à Merideth Carlson… et préparez-vous à d’autres sacrifices.", progress = "L’Ancien esprit équin vous regarde. Il a l’air interrogateur, comme s’il attendait quelque chose de vous.", completion = "L’Ancien esprit équin accepte votre offrande de Fourrage enrichi en manne. Il donne des coups de museau au picotin et dévore l’avoine et le grain. Après avoir mangé un peu, il regarde votre caparaçon et se place comme s’il voulait que le mettiez sur son dos…", rewards = "Vous recevrez :\n\n"},
[7644] = {title = "Le caparaçon en arcanite béni", objective = "Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker.", description = "Une fois posé sur le dos de l’Ancien esprit équin, le caparaçon se met à luire faiblement. L’air se charge de puissance pendant un bref instant, puis le caparaçon se téléporte, en toute sécurité, dans votre sac.\n\nIl semble qu’il ait été béni. Il ne vous reste plus qu’à suivre les instructions du seigneur Shadowbreaker : retourner le voir à Stormwind.", progress = "<nom>, vous êtes de retour ! Vous avez pu vous dépêtrer de Merideth Carlson et de Tendris Crochebois ? Honnêtement, il y a des moments où je ne sais pas trop lequel des deux est le pire…", completion = "Vous avez fait du chemin, mon ami. Votre caparaçon est maintenant prêt pour la dernière étape.\n\nVous l’utiliserez sur votre destrier une fois que sa rédemption sera complète. Auparavant, vous risquez de devoir livrer une lutte très dure. Mais le moment approche – hourra !\n\nIl ne reste plus qu’un objet à façonner avant que nous ne commencions, &lt;nom&gt;. Espérons que vous êtes toujours aussi plein de ressources que lorsque vous avez fait fabriquer ce caparaçon…", rewards = "Vous recevrez :\n\n"},
[7645] = {title = "Fourrage enrichi en manne", objective = "Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits.\n\nVous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité.", description = "À la Main d’argent, ils ont dit que j’étais FOLLE lorsque j’ai dit que je pouvais préparer un fourrage qui pourrait nourrir des esprits de chevaux. Ils ont TOUS pensé que j’avais perdu la tête !\n\nMais maintenant, je tiens ma revanche !\n\nJe ferais ce que vous me demandez, PALADIN… soi-disant CHAMPION… mais cela va vous coûter cher. J’ai besoin de biscuit spéciaux… Des Biscuits enrichis en manne qui ne sont vendus que par l’Aube d’argent. Et pour cette fois, j’exige – parfaitement, j’EXIGE de l’or en compensation des souffrances que j’ai endurées !\n\nVous n’arrêtez pas de vous gargariser de votre sens du sacrifice, PALADIN ? Il est temps maintenant de le mettre en pratique !", progress = "J’ai prouvé que vous aviez tort, n’est-ce pas ? J’ai prouvé que vous aviez tous tort ! J’AVAIS RAISON DEPUIS LE DEBUT !", completion = "OUI, MAINTENANT QUE… attendez… vous me donnez aussi de l’or ? Mais ce n’est pas vous qui m’avez traitée de folle… de cinglée complètement tordue, en fait… Mais vous êtes quand même prêt à vous sacrifier pour des actes que vous n’avez pas commis ?\n\nJe vous avais mal jugé, &lt;nom&gt;. Si vous avez encore besoin de fourrage, venez me voir. Je vous l’offrirai. Merci… noble &lt;classe&gt;.\n\nMais je garde quand même l’argent – je ne suis pas cinglée au point de refuser une fortune.", rewards = "Vous recevrez :\n\nFourrage enrichi en manne"},
[7646] = {title = "Le Clairvoyant", objective = "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.", description = "L’épreuve qui vous permettra de sauver le destrier déchu commence par l’assemblage d’un Clairvoyant. En fait, le vôtre est pratiquement prêt. L’Encensoir d’exorcisme que vous avez utilisé à Val-Terrreur en sera le catalyseur, et je vais lui fabriquer un réceptacle.\n\nIl nous faut néanmoins nous procurer deux composants : deux diamants. Ils doivent tous deux être d’une eau bien précise – un diamant d’Azeroth et un diamant noir en parfait état. Tous deux formeront le phare grâce auquel le Clairvoyant percera les ombres !", progress = "Vous êtes presque au bout de la route, <nom>. Il ne vous reste plus qu’à sacrifier ces derniers biens matériels, et vous serez à l’aube de grandes choses. Je le sens dans toutes les fibres de mon être !", completion = "Ils sont parfaits, &lt;nom&gt; – les dernières pièces sont en place. Votre temps est enfin venu !\n\nDans les profondeurs du Grand ossuaire de la Scholomance se trouvent les restes de maintes créatures. Parmi elles, un destrier qui, autrefois, fut d’une grande noblesse. Son âme ravagée sert à présent de monture au chevalier de la mort Ravassombre. C’est lui que nous devons affronter, et c’est sa monture que vous allez juger. Vous êtes le seul à pouvoir racheter son âme et la libérer de sa servitude, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[7647] = {title = "Jugement et rédemption", objective = "Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.\n\nEnsuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre.", description = "Prenez ce paquet, il contient tous les objets dont vous aurez besoin.\n\nServez-vous du Clairvoyant au centre des fondations du Grand ossuaire, afin d’attirer les esprits maudits qui doivent être jugés. Utilisez vos jugements avec sagesse au cours de cette épreuve, car les esprits risquent d’être plus puissants que vous ne le croyez. Lorsque ce sera terminé, le chevalier de la mort apparaîtra. Tuez-le et récupérez l’âme de son destrier. Lorsque ce sera fait, vous pourrez la purifier et placer votre caparaçon sur votre nouveau destrier.\n\nBonne chance, <nom> !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nInvocation de destrier\n\nVous recevrez :\n\n"},
[7648] = {title = "Le chef d'œuvre de Grimand", objective = "Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection.", description = "<Grimand s’essuie le front. Il irradie la satisfaction.>\n\nNous y voilà, <mon ami/mon amie>. C’est une pièce particulièrement réussie, aussi bonne que le caparaçon que j’ai fait pour le seigneur Shadowbreaker lorsqu’il est parti en quête de son destrier. Je vous remercie de m’avoir honoré de votre confiance.\n\nGrayson voudra certainement le voir par lui-même. Portez-lui ce caparaçon, et transmettez-lui mes remerciements pour la tâche honorable qu’il accomplit.", progress = "Vous progressez bien, <nom>. Une fois que vous aurez achevé votre caparaçon, nous vous confierons de nouvelles tâches.", completion = "Très impressionnant. On dirait que plus Grimand vieillit, plus sa main devient sûre. C’est d’autant plus remarquable que lorsqu'il a fabriqué mon propre caparaçon, il était déjà l’un des meilleurs artisans du monde.\n\nCe caparaçon serait déjà excellent sur n’importe quel cheval normal, mais nous ne contenterons pas d’un animal ordinaire. De plus, pour que ce caparaçon soit digne de reposer sur le destrier d’un &lt;classe&gt;, il doit aussi être béni. Je le garderai pour vous en attendant.", rewards = "Vous recevrez :\n\n"},
[7649] = {title = "Les plates en thorium enchanté - Volume I", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, mon petit.\n\n&lt;Le Gardien du savoir Lydros arrache une page du livre.&gt;\n\nCette recette pourra certainement vous être utile.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Cuirasse en thorium enchanté"},
[7650] = {title = "Les plates en thorium enchanté - Volume II", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, mon petit.\n\n&lt;Le Gardien du savoir Lydros arrache une page du livre.&gt;\n\nCette recette pourra certainement vous être utile.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Jambières en thorium enchanté"},
[7651] = {title = "Les plates en thorium enchanté - Volume III", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.", progress = "Vous avez récupéré un livre !", completion = "Très bon travail, mon petit.\n\n&lt;Le Gardien du savoir Lydros arrache une page du livre.&gt;\n\nCette recette pourra certainement vous être utile.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Heaume en thorium enchanté"},
[7652] = {title = "Une affaire en thorium", objective = "Voilà, messire, j’ai une superbe affaire à vous proposer.\n\nJe veux me débarrasser d’un certain nombre de plans pour des pièces d’armure impériales en plaques. Je cherche quelqu’un qui voudrait les prendre. En échange, tout ce qu’il me faut, ce sont quelques barres de thorium. Cela vous tente ?", description = nil, progress = nil, completion = nil, rewards = nil},
[7653] = {title = "La ceinture impériale en plaques", objective = "Les plans de la ceinture vont vous coûter 20 barres de thorium.", description = nil, progress = "Les plans de la ceinture vont vous coûter 20 barres de thorium.", completion = "Un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Ceinture impériale en plaques"},
[7654] = {title = "Les bottes impériales en plaques", objective = "Pour le plan des bottes, mon prix est de 40 barres de thorium. Ouais, 40. Vous n’allez pas pleurer, quand même ? Vous voulez un mouchoir ?\n\n<Derotain ricane.>", description = nil, progress = "Pour le plan des bottes, mon prix est de 40 barres de thorium. Ouais, 40. Vous n’allez pas pleurer, quand même ? Vous voulez un mouchoir ?\n\n<Derotain ricane.>", completion = "Un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Bottes impériales en plaques"},
[7655] = {title = "Les bracelets impériaux en plaques", objective = "Pour les plans des bracelets, il me faudra 20 Barres de thorium..\n\nVous vous sentez bien, mon gars? Vous êtes tout rouge.", description = nil, progress = "Pour les plans des bracelets, il me faudra 20 Barres de thorium..\n\nVous vous sentez bien, mon gars? Vous êtes tout rouge.", completion = "Un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Bracelets impériaux en plaques"},
[7656] = {title = "La pansière impériale", objective = "Pour les plans de la pansière, il va me falloir 60 barres de thorium.\n\nOh bon, c’est reparti. Vous allez courir voir vos vieux dieux bleus et leur demander pourquoi ils vous ont rejeté ? Allez, haut les cœurs ! Personne n’a dit que la vie était juste !", description = nil, progress = "Pour les plans de la pansière, il va me falloir 60 barres de thorium.\n\nOh bon, c’est reparti. Vous allez courir voir vos vieux dieux bleus et leur demander pourquoi ils vous ont rejeté ? Allez, haut les cœurs ! Personne n’a dit que la vie était juste !", completion = "Toujours un plaisir de faire affaire avec vous.\n\nEt &lt;nom&gt;, cette expression dégoûtée ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Pansière impériale"},
[7657] = {title = "Le heaume impérial en plaques", objective = "Vous n'avez qu'à aligner 50 barres de thorium et les plans du heaume sont à vous.", description = nil, progress = "Vous n'avez qu'à aligner 50 barres de thorium et les plans du heaume sont à vous.", completion = "Un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Heaume impérial en plaques"},
[7658] = {title = "Les jambières impériales en plaques", objective = "Pour les plans des protège-pattes, c’est 60 barres de thorium.\n\nOui, je sais, c’est horrible, je vous ruine et tout et tout. On me l’a déjà faite, alors gardez vos histoires pour vous, d’accord ?", description = nil, progress = "Pour les plans des protège-pattes, c’est 60 barres de thorium.\n\nOui, je sais, c’est horrible, je vous ruine et tout et tout. On me l’a déjà faite, alors gardez vos histoires pour vous, d’accord ?", completion = "Un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Jambières impériales en plaques"},
[7659] = {title = "Les épaulières impériales en plaques", objective = "Pour le plan des épaulières, ça ira chercher dans les 20 barres de thorium.", description = nil, progress = "Pour le plan des épaulières, ça ira chercher dans les 20 barres de thorium.", completion = "C'est toujours un plaisir de faire des affaires avec vous.\n\nEt &lt;nom&gt;, cet air dégoûté ne vous va pas.", rewards = "Vous recevrez :\n\nPlans : Epaulières impériales en plaques"},
[7660] = {title = "Echange de loup arctique", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nCor du loup brun rapideCor du loup gris rapideCor du loup des bois rapide"},
[7661] = {title = "Echange de loup - Loup rouge", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nCor du loup brun rapideCor du loup gris rapideCor du loup des bois rapide"},
[7662] = {title = "Un nouveau kodo bleu", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrand kodo brunGrand kodo grisGrand kodo blanc"},
[7663] = {title = "Un nouveau kodo vert", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrand kodo brunGrand kodo grisGrand kodo blanc"},
[7664] = {title = "Remplacement de raptor ivoire", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRaptor bleu rapideRaptor vert olive rapideRaptor orange rapide"},
[7665] = {title = "Remplacement de raptor rouge", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRaptor bleu rapideRaptor vert olive rapideRaptor orange rapide"},
[7666] = {title = "Retour au Grand ossuaire", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nClairvoyant"},
[7667] = {title = "Assistance matérielle", objective = "Si vous voulez aider Sagorne Crestrider de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état.", description = "<nom>, j’espère que vous pourrez m’aider dans une affaire urgente… à la fois matériellement et spirituellement. Laissez-moi vous expliquer.\n\nDans les profondeurs de la Scholomance, en Lordaeron, se trouve une chambre appelée le Grand ossuaire. Je suis en train de terminer un objet qui permettra de percer les ombres de cet horrible endroit. Pour le terminer, j’ai besoin de deux diamants : un diamant d’Azeroth et un diamant noir en parfait état. Je sais que cela ne se trouve pas facilement, et je n’ai pas les moyens de les acheter.\n\nPourriez-vous me les procurer ?", progress = "Vous demander une aide matérielle me met mal à l’aise, mais mon Clairvoyant, l’objet que j’espère parvenir à terminer, ne peut pas fonctionner sans diamants. Je ne vous en voudrais pas si vous refusiez de m’aider.", completion = "Votre générosité est sans pareille, &lt;nom&gt;. Je vous remercie mille fois pour votre bonté.\n\nJe vais pouvoir terminer mon Clairvoyant maintenant, et je pourrais même en fabriquer d’autres sans avoir besoin de nouveaux diamants…. Accepteriez-vous de m’aider à l’utiliser ? C’est pour une affaire importante, je vous l’assure… Une de celles qui, si personne ne fait rien, risque de déclencher une catastrophe épouvantable dans le monde des esprits !", rewards = "Vous recevrez :\n\n"},
[7668] = {title = "La menace de Ravassombre", objective = "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.\n\nRamenez la Tête de Ravassombre à Sagorne Crestrider de la vallée de la Sagesse, à Orgrimmar.", description = "Le chevalier de la mort Ravassombre règne sur le Grand ossuaire de la Scholomance. Il se prépare à altérer le monde des esprits pour accomplir ses ténébreuses volontés. Il faut l’arrêter ! Ce sera le rôle du Clairvoyant que vous m’avez aidé à préparer.\n\nUtilisez-le au centre du sous-sol du Grand ossuaire pour appeler les esprits qui servent Ravassombre. Lorsque vous les aurez vaincus, le chevalier de la mort apparaîtra en personne. Ramenez-moi sa tête, <nom> ! Sa mort est la seule chose qui puisse annuler les ravages qu’il a commis dans le monde des esprits !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCasque du pouvoir latent"},
[7669] = {title = "Retour au Grand ossuaire", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nClairvoyant"},
[7670] = {title = "Le seigneur Grayson Shadowbreaker", objective = "Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.", description = "<nom>, le temps est venu d’apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis longtemps… votre destrier !\n\nAllez parler au seigneur Grayson Shadowbreaker, dans le Quartier de la cathédrale, à Stormwind. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.\n\nJ’espère que votre épreuve se passera bien. Pour la Lumière, noble <frère/sœur> !", progress = nil, completion = "Je suis content de vous voir, &lt;nom&gt;. Je sais que vous attendiez depuis longtemps que je vous explique comment vous procurer votre destrier, et le moment est venu.\n\nVous allez traverser de nombreuses épreuves, mais l'essentiel est que vous ayez la volonté de surmonter les obstacles qui vous attendent. Ce n’est pas un exercice – vous avez progressé bien au-delà des simples tests qui ont ponctué votre éducation. Vous devrez arracher votre futur compagnon aux griffes même du mal que vous avez passé votre vie à combattre\n\nÉcoutez bien, car votre heure a sonné !", rewards = "Vous recevrez :\n\n"},
[7671] = {title = "Un nouveau sabre-de-givre", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRênes de sabre-tempête rapideRênes de sabre-de-givre rapideRênes de sabre-de-brume rapide"},
[7672] = {title = "Remplacement de sabre-de-nuit", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nRênes de sabre-tempête rapideRênes de sabre-de-givre rapideRênes de sabre-de-brume rapide"},
[7673] = {title = "Echange de bélier de givre", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBélier brun rapideBélier gris rapideBélier blanc rapide"},
[7674] = {title = "Echange de bélier noir", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBélier brun rapideBélier gris rapideBélier blanc rapide"},
[7675] = {title = "Remplacement de mécanotrotteur bleu clair", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nMécanotrotteur vert rapideMécanotrotteur blanc rapideMécanotrotteur jaune rapide"},
[7676] = {title = "Remplacement de mécanotrotteur blanc", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nMécanotrotteur vert rapideMécanotrotteur blanc rapideMécanotrotteur jaune rapide"},
[7677] = {title = "Echange d'étalon blanc", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nPalefroi bai rapidePalomino rapidePalefroi blanc rapide"},
[7678] = {title = "Echange de palomino", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nPalefroi bai rapidePalomino rapidePalefroi blanc rapide"},
[7681] = {title = "Hunter test quest", objective = "Feed your pet, then talk to your questgiver.Cast feed pet on your pet.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Cast feed pet on your pet.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7682] = {title = "Hunter test quest2", objective = "Feed your pet, then talk to your questgiver.Cast feed pet on your pet.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Cast feed pet on your pet.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7701] = {title = "ON RECHERCHE : Surveillant Maltorius", objective = "Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius.\n\nTuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Longstriker dans la Gorge des Vents brûlants pour la récompense.", description = "Par ordre de Son Éminence, le surveillant Oilfist, l’agent renégat de la Confrérie du thorium et nouveau chef d'équipe des Sombrefer de la Fosse aux scories du Chaudron, le surveillant Maltorius, doit être tué et sa tête rapportée comme preuve.\n\nAllez voir le capitaine de guet Lolo Longstriker pour la récompense.", progress = "Vous voyez donc pas qu’j’suis occupé ? Qu’est-ce que vous *hips* voulez ?", completion = "J’pensais pas qu'je r'verrais sa sale tronche !\n\nElle a l’air mieux sans le reste du bonhomme dessous, en fait.\n\nV’la votre réponcense… récompense, &lt;race&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHaubergeon calcinéTunique carbonisée en cuir\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7702] = {title = "Privez-les de sommeil", objective = "Loin dans les profondeurs de la fosse aux Scories, dans le Chaudron, vous trouverez le dortoir des nains Sombrefer.\n\nAllez dans leur dortoir et volez 20 Oreillers Sombrefer. Revenez voir Evonice Fumesuie dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.", description = "Si nous voulons faire baisser la productivité des forces des Sombrefers qui travaillent dans la fosse aux Scories, il faut frapper là où ça va faire le plus mal.\n\nICe fait est peu connu, mais les nains, et tout particulièrement les Sombrefers, ont besoin de repos ! De beaucoup de repos !\n\nJe vous le demande : comment pourraient-ils dormir sans oreillers ? Exactement, <nom>, ils ne pourraient pas. Voilà pourquoi il faut que vous vous glissiez dans la Fosse aux scories et que vous voliez leurs oreillers.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe brasillante"},
[7703] = {title = "Affaires inachevées chez les Gordok", objective = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.\n\nSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.", description = "Maintenant qu’z’êtes le roi, p’têt qu’vous pourrez récupérez l’objet précieux des Gordok que le sale elfe qui se dit Prince nous a pris. L’roi avant vous a pas réussi, et celui d’avant non plus, et aucun roi depuis que Tortheldrin – c’est le sale elfe – l’a volé à un vieux roi gordok d’il y a longtemps !\n\nC’est le Gantelet de puissance Gordok. Les vieux, ils disent que seul le vrai roi des Gordok pourra le ramener. Et puis, les vieux, ils disent aussi que le sale elfe est toujours là – si vous le trouvez, vous pourrez porter le gantelet de puissance pour toujours ! Ouais ! Je vais vous montrer !", progress = "Ha, vous l’avez pas trouvé, patron ? Peut-être que les histoires des vieux, c’est des menteries… c’est dur de croire qu’un vilain elfe peut voler des trucs au roi des Gordok !", completion = "Waou… vous êtes vraiment l’vrai roi ! J’pensais pas qu’je verrai le gantelet d’mon vivant ! On dirait qu’il n’a plus de mojo. P’têt que le vilain elfe a essayé d’s’en servir et l’a cassé. Eh ben je lui dis HAR HAR HAR !\n\nRegardez ! Cette marque sur l'gantelet, c’est une très très vieille marque, plus vieille que les Gordok, y paraît. Les capitaines des Gordok, ils apprennent tous quequ’chose – comment faire vivre la marque pour rendre son pouvoir au gantelet !\n\nJ’vais l’faire pour vous, roi ! Là, prenez le gantelet et régnez POUR TOUJOURS !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGarde-mains gordoksGantelets gordoksGants gordoksProtège-mains gordoks\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7704] = {title = "Regardez un peu la taille !", objective = "Apportez l'Oreiller de la Femme de chambre Pillaclencher à Evonice Sootsmoker dans la Gorge des Vents brûlants.", description = "Tiens, tiens, tiens... Quelle surprise. La Femme de chambre avait un oreiller brodé géant et il est maintenant en votre possession. Evonice Sootsmoker va sûrement vouloir mettre ses petites mains poisseuses dessus. Apportez-le-lui et voyez si elle a quelque chose à vous offrir pour votre peine.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nOreiller d'atterrissage d'Evonice"},
[7721] = {title = "Du carburant pour la zappette", objective = "Récupérez 10 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Feralas, et rapportez-les à Zorbin Fandazzle, près du quai là-bas.", description = "Si je dois rester ici à gérer cette boutique en pleine Côte oubliée, j’aurais besoin que l’on s’occupe de ces fichus élémentaires. La puissance déchaînée des éléments, quelle plaie !\n\nHeureusement pour moi, et aussi pour vous, mon cher et nouvel agent provocateur, les élémentaires représentent une source d’énergie idéale pour mon Ultra-réducteur perfectionné ! Donnez-leur ce qu’ils méritent ! Sans oublier de me garder leurs noyaux élémentaires, bien sûr !", progress = "Au lieu de vous ennuyer avec des détails techniques concernant l'utilité des noyaux élémentaires, je vais vous inciter à achever cette importante mission en vous offrant de l'argent et des objets de valeur en récompense.  En vérité, avez-vous terminé ?", completion = "Fabulerveilleux ! Ces noyaux vont m'occuper quelque temps. En plus, il y a maintenant moins d'élémentaires le long de la côte, et je n'aurai peut-être plus à pleurer toutes les larmes de mon corps de m'être établi dans le pire endroit imaginable !\n\nMerci, &lt;nom&gt;, de vous être donné cette peine pour moi. Bien que je n'en aie pas trop les moyens, permettez-moi de vous montrer ma gratitude par un moyen que vous devriez apprécier... Voici du butin !", rewards = "Vous recevrez :\n\nChapeau imperméable de Zorbin"},
[7722] = {title = "Le Flux embrasé", objective = "Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Burninate dans la gorge des Vents brûlants.", description = "Quand ce bâtard de Maltorius a quitté notre clan, il a emporté avec lui quelque chose de plus précieux qu'un cristal des arcanes en parfait état : notre recette du Flux embrasé ! Je mettrais ma main à couper que la recette faisait partie de son marché avec les Sombrefer pour sa promotion.\n\nJe veux que vous nous rapportiez nos plans secrets, <nom>. Je suis certain qu'ils se trouvent près de Maltorius, loin dans les profondeurs de la Fosse aux scories.", progress = "Avez-vous trouvé les plans ?", completion = "J'espère que vous lui avez aussi défoncé la mâchoire, &lt;nom&gt;. Ragnaros sait qu'il le méritait.\n\nMaintenant nous pouvons passer aux affaires.", rewards = "Vous recevrez :\n\n"},
[7723] = {title = "Maudits gros doigts", objective = "Hansel Heavyhands veut que vous tuiez 20 Golems de guerre lourds.\n\nLes golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants.", description = "Malheureusement, je ne peux plus tabasser les bêtes comme avant, à cause de mon problème de gros doigts. Vous voyez, le climat d'ici en plus de la basse pression fait se dilater mes doigts. On dirait des boudins de Thelsamar...\n\nVa falloir que vous fassiez mon travail.\n\nPour commencer : flanquez une raclée aux golems de guerre lourds d'la Gorge. Et qu'ça saute.", progress = nil, completion = "Vous êtes vraiment un bon gars. J'ai un petit cadeau pour vous remercier.", rewards = "Vous recevrez :\n\nGantelets de plaques mâchefer"},
[7724] = {title = "Une menace incandescente", objective = "Hansel Heavyhands veut que vous tuiez 20 Grandes araignées de lave dans la gorge des Vents brûlants. Vous pouvez trouver les Grandes araignées de lave dans les plateaux et les mares de lave de la gorge des Vents brûlants.\n\nRevenez voir Hansel dans la gorge des Vents brûlants quand vous aurez tué assez de Grandes araignées de lave.", description = "J'vous dis pas, chaque fois que le vieil Hansel veut se reposer un moment et réfléchir au sens de la vie, les puissances supérieures lui donnent un nouveau travail.\n\nAlors je me dis, franchement ! Vous voyez ce que je veux dire ? Franchement.\n\nIl y a ces grandes araignées de lave qui font du grabuge. Oilfist dit qu'elles ont du feu qui leur sort du derrière et qu'ce genre de choses fait peur aux enfants.\n\nJ'pense donc qu'y faut les tuer. Ou plutôt qu'vous devez les tuer.", progress = nil, completion = "&lt;Hansel éternue.&gt;\n\nJ'crois qu'je suis en train d'attraper un rhume. Marre de ce climat glacial !", rewards = "Vous recevrez :\n\nCeinturon de mailles calcinées"},
[7725] = {title = "Le retour des géants rétrécis", objective = "Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 10 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas.", description = "Je sais que vous avez déjà ramassé des résidus pour moi... mais si vous aviez envie de recommencer cette activité fort amusante, j'aurais toujours besoin de résidus.\n\nJe ne serai plus en mesure de vous offrir la même compensation, mais je serais plus qu'heureux de parler de vous à tous mes amis gobelins dotés d'oreilles.\n\nEt croyez-moi <Monsieur/Madame> quand je vous dis que ces gobelins ont de grandes oreilles.", progress = "Ah, les fruits de la recherche sous la forme de ce si délicieux résidu ! Euh, je veux dire, je n'en mange pas ou quoi que ce soit quand je l'étudie.\n\nOu pas beaucoup.", completion = "Absolument fantastique, &lt;nom&gt; ! Vous avez encore réussi, et je vous en remercie.\n\nMerci !\n\nPeut-être que cette pièce vaut moins que ce à quoi vous êtes habitué, mais soyez assuré que les échos de vos grands exploits pour la gobelinité résonnent aux plus hauts niveaux du Cartel Gentepression. Si vous cherchez quelque chose d'autre à faire, surtout venez me parler !", rewards = "Vous recevrez :\n\n"},
[7726] = {title = "Encore du carburant pour la zappette", objective = "Récupérez 6 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Feralas, et rapportez-les à Zorbin Fandazzle, près du quai.", description = "Encore du travail, vous dites ? Cette héroïque mission que je vous avais confiée de ramasser des machins gluants dans des êtres élémentaires n'a donc pas apaisé votre soif d'aventure ?  Peut-être qu'il serait vain de tenter d'assouvir votre désir insatiable de quêtes par davantage des mêmes tâches...\n\nD'accord, assez de mélodrame, j'ai en fait vraiment besoin de plus de noyaux d'élémentaires d'eau. J'essaye désespérément de gérer ma boutique ici, la récompense ne sera donc plus aussi belle... mais je vous promets que je raconterai à tout le monde combien vous m'avez aidé. Vous pouvez me faire confiance là-dessus. Je connais des membres du Cartel !", progress = "Avez-vous réussi à trouver les noyaux élémentaires dont j'ai besoin ?", completion = "Formidable, &lt;nom&gt;, formidable ! Peut-être que vous recevez d'habitude plus que cette pièce que je vous donne pour un tel travail, mais soyez assuré que mes camarades du Cartel Gentepression entendront parler de vos efforts !\n\nSi vous cherchez du travail, venez donc me voir. J'aurai toujours besoin de plus de noyaux élémentaires et de ce genre de choses.", rewards = "Vous recevrez :\n\n"},
[7727] = {title = "Incendosaures ? N'importosaures, plutôt", objective = "Hansel Heavyhands veut que vous tuiez 20 Incendosaures.\n\nOn peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants.\n\nRetournez voir Hansel Heavyhands dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d’Incendosaures.", description = "Les oignons, <mon gars/ma fille>. J'ai des oignons qui m'font vivre un vrai martyre, pour sûr. Comment j'pourrais tuer ces machins avec les pieds dans c't'état ? Faudrait qu'vous m'aidiez, ça, c'est sûr.\n\nScrange et Burninate m'ont d'mandé d'tuer ces bidules pour envoyer des équipes d'exploration dans les mares d'lave, tout au fond d'la Fosse aux scories. Y paraît qu'c'est des incendosaures ou une idiotie de c'genre, qui causent ben des soucis, là, en-bas. Bougez-vous maintenant, et ne rev'nez pas avant qu'la race des incendosaures soit éteinte.", progress = nil, completion = "Oh mes pauvres petons.\n\nMais bon, puisque vous z’avez pas d'chiffon…", rewards = "Vous recevrez :\n\nChiffon"},
[7728] = {title = "OBJETS VOLES : Tuyère et longue-vue", objective = "Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants.\n\nLes seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs.", description = "Les objets suivants ont été volés :\n\n*Une tuyère en sombre fer.\n\n*Une longue-vue de guetteur.\n\nUne récompense sera offerte aux individus qui trouveront et rapporteront ces objets dérobés.\n\nLa Confrérie du thorium est certaine que ces objets ont été volés par des nains Sombrefer jaloux et sans scrupule qui habitent la gorge des Vents brûlants.\n\nLa longue-vue en question était un excellent outil pour les guetteurs et la tuyère était un outil de forgeron irremplaçable.\n\nSi vous trouviez ces objets, rapportez-les à Scrange.", progress = "Si vous êtes ici pour la récompense, il va falloir que vous me donniez les objets volés.", completion = "Excellent travail ! Voilà pour votre récompense.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières de plaques mâcheferProtège-mains calorifères\n\nVous recevrez également :\n\n"},
[7729] = {title = "OFFRE D'EMPLOI : Réduire la concurrence", objective = "Tuez 15 Sous-chefs Sombrefer et 15 Esclavagistes Sombrefer. Revenez voir le sous-chef Scrange dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.", description = "Le sous-chef Scrange recherche quelques hommes et femmes de valeur pour l'aider à \"réduire la concurrence\" dans la gorge des Vents brûlants.\n\nSi ce poste vous intéresse, allez dans la gorge des Vents brûlants et tuez tous les sous-chefs Sombrefer et les esclavagistes Sombrefer que vous verrez.\n\nRevenez voir le sous-chef Scrange quand vos vêtements seront assez couverts de sang.\n\nVous saurez déjà quand il y aura assez de sang, ne demandez pas.", progress = "Nous devons vous peser avec et sans vêtements pour être sûrs.", completion = "7,2 kilos ! Voilà qui pourrait bien être un nouveau record de sang et de boyaux sur des vêtements ! Félicitations, &lt;classe&gt; !", rewards = "Vous recevrez :\n\n"},
[7730] = {title = "Infestation de Zukk'ash", objective = "Rapportez 20 Carapaces de Zukk'ash à Hadoken Swiftstrider au Camp Mojache en Feralas.", description = "D'après les informations que nous avons pu réunir, l'ennemi se trouvant au sud des gnolls est une race insectoïde. Franchement, cela nous est égal s'il s'agit de créatures sensibles ou non.  Si elles excitent à ce point les gnolls contre nous, elles représentent une menace tout aussi grave qu'eux, voire pire encore.\n\nPartez loin jusqu'à la demeure de ces insectes Zukk'ash : on l'appelle le Gouffre grouillant. Réduisez leur nombre et faites-moi un rapport sur la situation. Rapportez leurs carapaces pour prouver votre travail.", progress = "Comment se passe votre chasse, <nom>?  Êtes-vous ici pour me faire part de votre succès ?", completion = "Bien joué, &lt;classe&gt;. Bien qu'on ne puisse lutter contre l'étendue de la présence des Zukk'ash que par une invasion à grande échelle, vous nous offrez du temps pour mettre en place une véritable stratégie.\n\nJe vais faire analyser ces carapaces : nous devons tout apprendre à leur sujet avant de nous occuper de ce problème qui s'avère bien plus délicat que prévu.", rewards = "Vous recevrez :\n\n"},
[7731] = {title = "Fouet-cuisant", objective = "Battez Fouet-cuisant dans le Gouffre grouillant et rapportez ses glandes à Hadoken Swiftstrider au Camp Mojache en Feralas.", description = "Alors qu'il surveillait le Gouffre grouillant, un de nos éclaireurs nous a signalé avoir vu un insecte géant, bien plus grand que les autres insectes, qui errait dans cet endroit tortueux. Il est non seulement plus grand, mais il semble aussi sécréter une sorte d'aura que les autres insectes n'ont pas. Nous lui avons donné  un nom : Fouet-cuisant.\n\nIl nous serait très précieux de pouvoir étudier les entrailles de cette bête afin de déterminer le meilleur moyen de lutter contre cette nouvelle menace. Coupez ses glandes de sécrétion et rapportez-les-moi immédiatement !", progress = "Avez-vous réussi à abattre Fouet-cuisant ?", completion = "Impressionnant, &lt;classe&gt;... très impressionnant ! Si Fouet-cuisant est effectivement une de leurs créatures les plus puissantes, l'étude de cette bête nous sera fort utile. C'est maintenant mon rôle de faire en sorte que nous nous défendions assez longtemps pour pouvoir se servir de ces connaissances.\n\nVeuillez accepter ces pièces en guise de remerciement de la part de tout le camp, &lt;nom&gt;. Bien joué.", rewards = "Vous recevrez :\n\n"},
[7732] = {title = "Le rapport sur les Zukk'ash", objective = "Apportez le rapport sur les Zukk'ash du Camp Mojache à Zilzibin Drumlore. Il réside à la Herse d'Orgrimmar", description = "Vous avez doublement bien fait de vous occuper de la menace que les insectes Zukk'ash représentent pour le Camp Mojache.  Cette menace est loin d'avoir disparu, et j'aimerais vous demander une dernière tâche pour la Horde.\n\nVoici un document contenant toutes les informations que nous avons obtenues au sujet de ces insectes Zukk'ash. Je veux que vous l'apportiez à Zilzibin Drumlore à la Herse d'Orgrimmar. C'est un expert concernant ce genre de créatures. J'espère qu'il pourra faire quelque chose à l'aide des connaissances que nous avons réunies.", progress = "Salutations, ami… On dirait que vous êtes pressé. Y a-t-il quelque chose que je puisse faire pour vous aider ?", completion = "Ah, je m'y attendais. Ces créatures que vous avez affrontées... elles sont une menace ancienne que la Horde persiste à ignorer. Hadoken a été fort sage de m'avoir fait parvenir ceci - et de vous avoir envoyé.\n\nLes Zukk'ash ne sont rien de plus que des créatures appelées silithides. On pourrait croire qu'elles ne représentent qu'un petit désagrément, mais je vous l'assure : il s'agit d'une menace bien pire que tout ce que l'Alliance pourrait réunir.\n\nSi vous vous portez volontaire, vous pourriez m'être bien utile pour révéler cette menace au grand jour.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau de subtilitéSpallières du pic d'Emeraude\n\nVous recevrez également :\n\n"},
[7733] = {title = "Qualité améliorée", objective = "Fournir 10 Peaux de yéti Griffe Féroce à Pratt McGrubben au bastion de Feathermoon, en Feralas.", description = "J’ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ? Au nord de Feralas, loin dans le repaire des Griffes féroces, vit un autre groupe de yétis. Ils sont beaucoup plus coriaces que ceux que vous avez déjà combattus. Si vous aimez les défis, celui-là devrait vous combler !\n\nJe vous récompenserai généreusement pour dix de leurs peaux. Apportez-les ici, et nous ferons affaire.", progress = "Si la qualité des peaux de ces yétis Griffe Féroce approche celle de leurs congénères de la Griffe farouche, elles pourraient bien être aussi résistantes que du thorium !\n\nVous vous rendez compte ?", completion = "Excellent, excellent ! Tout se passe parfaitement bien. Une fois qu’elles seront préparées, je peux vous dire qu’elles seront beaucoup plus dures.\n\nMerci encore pour votre aide, &lt;nom&gt;. Ah, tenez, prenez l’une de mes dernières créations.", rewards = "Vous recevrez :\n\nTunique artisanale de Pratt"},
[7734] = {title = "Qualité améliorée", objective = "Fournir 10 Peaux de yéti Griffe Féroce à Jangdor Swiftstrider au Camp Mojache, en Feralas.", description = "J’ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ? Au nord de Feralas, loin dans le repaire des Griffes féroces, vit un autre groupe de yétis. Ils sont beaucoup plus coriaces que ceux que vous avez déjà combattus. Si vous aimez les défis, celui-là devrait être à la hauteur de vos attentes !\n\nJe vous récompenserai généreusement pour dix de leurs peaux. Amenez-les ici, et nous ferons affaire.", progress = "Si la qualité des peaux de ces yétis Griffe Féroce approche celle de leurs congénères de la Griffe farouche, elles pourraient bien être aussi résistantes que du thorium !\n\nVous vous rendez compte ?", completion = "Excellent, excellent ! Tout se passe parfaitement bien. Une fois qu’elles seront préparées, je peux vous dire qu’elles seront beaucoup plus dures.\n\nMerci encore pour votre aide, &lt;nom&gt;. Ah, tenez, prenez l’une de mes dernières créations.", rewards = "Vous recevrez :\n\nTunique artisanale de Jangdor"},
[7735] = {title = "Une peau de yéti en parfait état", objective = "Apporter la Peau de yéti en parfait état à Pratt McGrubben au bastion de Feathermoon, en Feralas.", description = "Vous avez trouvé une peau de yéti en parfait état, exceptionnellement épaisse et résistante, plus que celles que vous avez prélevées sur les yétis Griffes féroces.\n\nVous savez que Pratt McGrubben du bastion de Feathermoon fait commerce de peaux de yétis. Ce spécimen devrait beaucoup l’intéresser.", progress = "Qu’y a-t-il, <nom> ? Vous avez quelque chose de spécial pour moi ?", completion = "Incroyable ! Vous avez trouvé LA peau de yéti !\n\nJe suis prêt à la payer au prix fort. Normalement, pour une seule peau, je ne donne pas autant, mais je suis sûr que je pourrai faire quelque chose d’extraordinaire avec celle-là. Merci d’avoir pensé à moi, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7736] = {title = "Réapprovisionnement en flux embrasé (Sang-royal)", objective = "Assez perdu de temps à bavarder, <race>. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s'amenuisent.\n\nVoici ce que je veux que vous me rapportiez :\n\n*Ecailles d'incendosaure.\n\n*Sang-royal.\n\n*Charbon.\n\nJe prendrai tout ce que vous me donnerez !\n\nEt vous le ferez vite si vous voulez bien vous entendre avec la Confrérie.", description = nil, progress = "Assez perdu de temps à bavarder, <race>. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s'amenuisent.\n\nVoici ce que je veux que vous me rapportiez :\n\n*Ecailles d'incendosaure.\n\n*Sang-royal.\n\n*Charbon.\n\nJe prendrai tout ce que vous me donnerez !\n\nEt vous le ferez vite si vous voulez bien vous entendre avec la Confrérie.", completion = "Il y a toujours de la place pour plus de flux embrasé, junior. Continuez comme ça... Jusqu'à ce que je vous dise d'arrêter.", rewards = nil},
[7737] = {title = "Se faire accepter", objective = "Vous avez monté les barreaux de l'échelle de la Confrérie, <race>. Nous commençons à avoir de vous une opinion favorable. Voilà un bel exploit !\n\nSi vous souhaitez gagner davantage encore de notre respect, écoutez bien.\n\nNous pouvons raffiner le flux embrasé en ajoutant simplement un résidu de sombre fer au mélange. On peut trouver les résidus de sombre fer dans les Profondeurs de Blackrock.\n\nApportez-moi tous les résidus de sombre fer que vous trouverez !", description = nil, progress = "Vous avez monté les barreaux de l'échelle de la Confrérie, <race>. Nous commençons à avoir de vous une opinion favorable. Voilà un bel exploit !\n\nSi vous souhaitez gagner davantage encore de notre respect, écoutez bien.\n\nNous pouvons raffiner le flux embrasé en ajoutant simplement un résidu de sombre fer au mélange. On peut trouver les résidus de sombre fer dans les Profondeurs de Blackrock.\n\nApportez-moi tous les résidus de sombre fer que vous trouverez !", completion = "Continuez à apporter du résidu !", rewards = nil},
[7738] = {title = "Une peau de yéti parfaite", objective = "Apporter la Peau de yéti parfaite à Jangdor Swiftstrider au Camp Mojache, en Feralas.", description = "Vous avez trouvé ce qui pourrait bien être une peau de yéti parfaite. Vous remarquez sans peine qu’elle est exceptionnellement épaisse et résistante, plus que celles que vous avez prélevées sur les yétis Griffes féroces.\n\nVous savez que Jangdor Swiftstrider du Camp Mojache fait commerce de peaux de yétis. Ce spécimen devrait beaucoup l’intéresser.", progress = "Qu’y a-t-il, <nom> ? Vous avez quelque chose de spécial pour moi ?", completion = "C’est une trouvaille incroyable ! Je crois bien que c’est la plus belle peau de yéti que j’aie jamais vu !\n\nCela mérite une récompense de choix. Normalement, pour une seule peau, je ne donne pas autant, mais je suis sûr que je pourrai faire quelque chose d’extraordinaire avec celle-là. Merci d’avoir pensé à moi, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7761] = {title = "Les ordres de Blackhand", objective = "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement.\n\nD’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter.", description = "Imbécile,\n\nJe n’ai aucune confiance dans votre capacité à empêcher les intrus de pénétrer dans le repaire du maître. Dans l’éventualité très probable de votre décès, cet orbe comporte une sécurité incorporée, destinée à empêcher les intrus de se téléporter directement dans le repaire de l'Aile noire.\n\nSeuls ceux qui portent dans leur chair la Marque de Drakkisath peuvent s’en servir. Et heureusement, Drakkisath n’est pas aussi incompétent que vous. Il garde la marque lui-même !\n\nChef de guerre Rend Blackhand.\n\nP.S. : Détruisez cette lettre, idiot.", progress = nil, completion = "Le fer incandescent est pressé contre votre chair, mais vous ne cillez même pas. Vous êtes coriace !\n\nVous êtes à présent porteur de la Marque de Drakkistah. Amusez-vous bien à piller le château.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7781] = {title = "Le seigneur de Blackrock", objective = "Apporter la Tête de Nefarian au généralissime Bolvar Fordragon à Stormwind.", description = "La vieille sensation vous revient. Vous êtes <inondé/inondée> par un sentiment de victoire fort bienvenu. Devant vous se trouve la tête colossale de Nefarian, toute couturée de cicatrices. Ramenez-là à votre généralissime, champion.", progress = "Inconcevable !", completion = "Il est inutile de vous expliquer la signification de cette action, &lt;nom&gt;. Ce jour vivra dans l’Histoire. Voici des années que l’Alliance n’avait pas remporté une victoire de cette ampleur – en supposant que cela lui soit jamais arrivé !", rewards = "Vous recevrez :\n\n"},
[7782] = {title = "Le seigneur de Blackrock", objective = "Aller dans la Vallée des Héros de Stormwind et parler au Grand maréchal Pont-de-Pierre.", description = "Aller dans la Vallée des Héros et parler au Grand maréchal Pont-de-Pierre.", progress = nil, completion = "&lt;Le grand maréchal Afrasiabi s’incline.&gt;\n\nChoisissez votre récompense, et que les réjouissances commencent !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMédaillon du Maître-tueur de dragonOrbe du Maître-tueur de dragonBague du Maître-tueur de dragon\n\nVous recevrez également :\n\n"},
[7783] = {title = "Le seigneur de Blackrock", objective = "Apportez la Tête de Nefarian à Thrall à Orgrimmar.", description = "La vieille sensation vous revient. Vous êtes <inondé/inondée> par un sentiment de victoire fort bienvenu. Devant vous se trouve la tête colossale de Nefarian, toute couturée de cicatrices. Ramenez-là à votre Chef de guerre, champion.", progress = "J’aurais voulu être là pour voir son expression lorsque vous avez placé le coup mortel, <nom>.", completion = "Vous faites une fois encore honneur à la Horde, &lt;nom&gt;. Le fils de l'Aile de mort gît à vos pieds. Le très maléfique doit probablement s’agiter.", rewards = "Vous recevrez :\n\n"},
[7784] = {title = "Le seigneur de Blackrock", objective = "Parlez au Haut seigneur Saurfang à Orgrimmar. Il vous attend dans la vallée de la Force.", description = "Allez voir le Haut seigneur Saurfang dans la vallée de la Force.", progress = nil, completion = "Choisissez votre récompense afin que je puisse exhiber cette tête aux yeux de tous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMédaillon du Maître-tueur de dragonOrbe du Maître-tueur de dragonBague du Maître-tueur de dragon\n\nVous recevrez également :\n\n"},
[7785] = {title = "Examiner le Calice", objective = "Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian.", description = "Examinez le Calice de la renaissance, <mortel/mortelle>. C'est grâce à lui que le Cherchevent reviendra !", progress = "Le libérerez-vous de sa prison éternelle ?", completion = "Puissiez-vous être protégé durant votre croisade. Puisse le maître bénir vos efforts.", rewards = nil},
[7786] = {title = "Thunderaan le Cherchevent", objective = "Pour libérer Thunderaan le Cherchevent de sa prison, vous devez présenter au généralissime Demetrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du Seigneur du feu.", description = "Je vous ai dit tout ce que je sais, <nom>. C'est à vous de trouver l'élémentium. C'est à vous de détruire la forme physique du Seigneur du feu.\n\nSi vous y parvenez, vous recevrez la bénédiction de Thunderaan.", progress = "S'il le faut, mettez le monde à genou !", completion = "Même dans mes rêves les plus fous, je n'avais osé espérer ce jour.\n\nRegarde, mortel.\n\nCONTEMPLE CELUI QUI EST PLUS VIEUX QUE LA VIE ELLE-MÊME !\n\nCONTEMPLE CELUI QUI A AFFRONTÉ LES TITANS ET LES DIEUX !\n\nLÈVE-TOI, MAÎTRE ! LIBÈRE-TOI DE TES CHAÎNES !", rewards = "Vous recevrez :\n\n"},
[7787] = {title = "Éveille-toi, Lame-tonnerre !", objective = "Présenter la Lame du baiser du vent dormante au généralissime Demitrian.", description = "Vous avez vaincu le Cherchevent. Prenez la lame endormie et obligez cet immonde menteur, Demitrian, à utiliser les matériaux que vous lui avez fourni pour sa trahison. Obligez-le à éveiller Lame-tonnerre.", progress = "<Demitrian tremble en votre présence.>", completion = "Je vous en supplie, ne me frappez pas ! Prenez-la ! Prenez la lame ! Laissez Demitrian refaire sa pitoyable vie !", rewards = "Vous recevrez :\n\nLame-tonnerre, épée bénie du Cherchevent"},
[7788] = {title = "Triomphez des envahisseurs !", objective = "Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent.", description = "Au-delà de ce tunnel, vous trouvez un lieu d'affrontement et de chaos, jeune <classe>. La Horde continue à massacrer notre forêt sacrée, abattant les conifères pour alimenter leurs engins de guerre.\n\nEntrez dans le goulet des Warsong, et défendez le fort d'Aile-argent. Repoussez les envahisseurs de la Horde.\n\nSi vous y parvenez, vous gagnerez un talisman de vaillance. Apportez-moi l'un de ces talismans, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7789] = {title = "Écrasez les usurpateurs d'Aile-argent", objective = "Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan.", description = "La sauvagerie de la forêt d'Ashenvale succombera devant la puissance de la Horde, <race>. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !\n\nQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d'Aile-argent, et vous gagnerez une marque d'honneur Warsong. Revenez me voir avec l'une de ces marques, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7790] = {title = "REUSE", objective = nil, description = "Defeat the Warsong Mill, then return to me.", progress = nil, completion = nil, rewards = nil},
[7791] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Stormwind pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Stormwind pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7792] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Darnassus pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Darnassus pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7793] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7794] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Stormwind !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Stormwind !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7795] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7796] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Stormwind soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Stormwind soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour Stormwind. Merci de tous vos efforts !", rewards = nil},
[7798] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7799] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Darnassus !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Darnassus !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7800] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7801] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Darnassus soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Darnassus soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour Darnassus. Merci de tous vos efforts !", rewards = nil},
[7802] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Ironforge pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Ironforge pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7803] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7804] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Ironforge !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Ironforge !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7805] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7806] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Ironforge soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Ironforge soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour Ironforge. Merci de tous vos efforts !", rewards = nil},
[7807] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tous les exilés de Gnomeregan pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tous les exilés de Gnomeregan pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7808] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7809] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue parmi les exilés de Gnomeregan !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue parmi les exilés de Gnomeregan !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7810] = {title = "Le maître de l'arène", objective = "Parler à Short John Mithril dans l’arène de Strangleronce.\n\nObjet fourni : \n", description = "Être le maître d’une arène, ça ne doit pas se limiter à ça ! Le pirate qui anime celle des Gurubashi aura peut-être des conseils à me donner.", progress = nil, completion = "Salut mes trésors ! Récupérer un Bijou, c’est pas assez pour être maître de l’arène ! Allez, voilà l’occasion de prouver ce que vous valez vraiment", rewards = "Vous recevrez :\n\n"},
[7811] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7812] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur des exilés de Gnomeregan soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur des exilés de Gnomeregan soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour nous les gnomes. Merci de tous vos efforts !", rewards = nil},
[7813] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Undercity pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Undercity pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7814] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7815] = {title = "Les Gueules d'acier, l'ami !", objective = "Katoom le pêcheur, du village des Revantusk des Hinterlands, veut que vous tuiez 15 tortues Gueules d’acier des mers. Retournez le voir lorsque vous aurez terminé.", description = "Faut pas se laisser prendre à leurs grands yeux, v’savez ? Ces gueules d’acier des mers, c’est la plaie des plaies ! Je peux pas pêcher cinq minutes sans qu’un de ces gros aspirateurs à poissons me vole mes appâts.\n\nRendez-nous service, à moi et tous les gens du village des Revantusk, tuez-les.\n\nTuez-les, tous autant qu’ils sont !", progress = nil, completion = "Oh, mon pote ! Je n’vous remercierai jamais assez ! J’espère que c’te canne à pêche que v’la sera une récompense suffisante.", rewards = "Vous recevrez :\n\nFC-5000 de Nat Pagle, pêcheur de l'extrême"},
[7816] = {title = "Gammerita, l'ami !", objective = "Katoom le pêcheur, du village des Revantusk dans les Hinterlands, veut que vous tuiez Gammerita et que vous récupériez le Meilleur appât de Katoom sur son cadavre.\n\nKatoom a mentionné que Gammerita rôdait sur la côte, avec d’autres tortues.", description = "Yo ! Y a une tortue qu’est pas comme les autres. Elle, c’est la Gammerita, la patronne des gueules d’aciers des mers – un sale reptile voleur.\n\nLà, elle s’est sauvée avec mon meilleur appât. L’a tranché la ligne, comme ça, net ! Et depuis, les poissons, y mordent plus pareil.\n\nTrouvez Gammerita et récupérez mon appât. Oui, dans son estomac.", progress = "Alors, vous l’avez ?", completion = "Mon POTE ! C’est fantastique ! Avec mon meilleur appât et moins de gueules d’acier, le poisson va mordre comme jamais.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7817] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Undercity !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prête à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Undercity !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prête à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
