[7819] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Undercity soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Undercity soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour les Réprouvés. Merci pour tous vos efforts !", rewards = nil},
[7820] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Thunder Bluff pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Thunder Bluff pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7821] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7822] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Thunder Bluff !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prête à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Thunder Bluff !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prête à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7823] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7824] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7825] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Thunder Bluff soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Thunder Bluff soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour Thunder Bluff. Merci de tous vos efforts !", rewards = nil},
[7826] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Orgrimmar pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Orgrimmar pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7827] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7828] = {title = "Traquer les traqueurs", objective = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous tuiez 15 Traqueurs Crins-d'argent et 15 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé.\n\nD’après Makhor, les loups se cachent dans les régions sauvages des Hinterlands.", description = "Les Hinterlands sont un endroit dur, <race>. On y a perdu beaucoup de braves trolls. Les loups Crins-d'argent sont l’une des pires menaces qu’affrontent nos chasseurs. Ces animaux se cachent dans les buissons et les fourrés, attendant l’occasion de bondir.\n\nCette férocité ne doit pas rester impunie !\n\nVous devez penser comme les Crins-d'argent. Traquez les Traqueurs ! Tuez-les tous !", progress = nil, completion = "Beau travail, &lt;race&gt;. Les Revantusk vous remercient de votre contribution.", rewards = "Vous recevrez :\n\n"},
[7829] = {title = "Chasser les sauvages", objective = "Le veneur Markhor du village des Revantusk des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé.\n\nMarkhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands.", description = "De toutes les bêtes féroces qui peuplent les Hinterlands, les chouettards sont parmi les plus vicieuses. Les becs et les griffes de ces monstres nous ont coûté de nombreux bons guerriers.\n\nTuez tous les chouettards que vous rencontrerez, <race>. Ne revenez me voir que lorsque vous serez écoeuré par tout le sang versé. Votre contribution sera alors pesée, mesurée et jugée.", progress = nil, completion = "Vous avez prouvé que vous êtes un digne allié des Revantusk, &lt;nom&gt;. Beau travail.", rewards = "Vous recevrez :\n\n"},
[7830] = {title = "Venger les victimes", objective = "Le veneur Markhor, du village des Revantusk des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche.\n\nD’après Makhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands.", description = "Ces infects Wildhammer dressent des gryphons pour tuer des trolls. C’est horrible, je sais, mais ne vous faites pas de souci, justice sera faite.\n\nPour le moment, je veux que vous vous concentriez sur l’éradication des vieux gryphons de la région. On les appelle des Seigneurs du ciel.\n\nTuez-en un et ramenez-moi une plume.", progress = "Les Seigneurs du ciel Bec-rasoir sont une variété rare de gryphons, mais c’est une variété qui se reproduit et dont la progéniture nous tue.", completion = "&lt;Markhor examine la plume.&gt;\n\nJe me demande combien de nos chasseurs cette bête a dévoré avant que vous ne lui fassiez connaître notre justice.", rewards = "Vous recevrez :\n\n"},
[7831] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Orgrimmar !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Orgrimmar !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7832] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Orgrimmar soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Orgrimmar soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour Orgrimmar. Merci de tous vos efforts !", rewards = nil},
[7833] = {title = "Un don de laine", objective = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tous les trolls Darkspear pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", description = nil, progress = "Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tous les trolls Darkspear pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.\n\nSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7834] = {title = "Un don de soie", objective = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", description = nil, progress = "Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.\n\nJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7835] = {title = "Un don de tisse-mage", objective = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue auprès des trolls Darkspear !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", description = nil, progress = "Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue auprès des trolls Darkspear !\n\nSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.", completion = "Merveilleux ! Nous vous remercions pour ce don très généreux, &lt;nom&gt; !", rewards = "Vous recevrez :\n\n"},
[7836] = {title = "Un don d'étoffe runique", objective = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", description = nil, progress = "<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?\n\nSi vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.", completion = "Fantastique – je vous assure que tout ce tissu sera bientôt utilisé. Merci encore pour votre aide ! Sans vous, nous n’y serions sûrement pas arrivés.\n\nComme vous avez déjà contribué, je traiterai en priorité tous les dons d'étoffe runique que vous pourriez faire à l’avenir. N’hésitez pas à revenir me voir, et je veillerai personnellement à ce que vos bonnes actions soient reconnues !", rewards = "Vous recevrez :\n\n"},
[7837] = {title = "Encore de l'étoffe runique", objective = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur des trolls Darkspear soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", description = nil, progress = "Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur des trolls Darkspear soient reconnus à leur juste valeur.\n\nLorsque vous serez prêt à me les remettre, je les accepterai volontiers.", completion = "&lt;nom&gt;, l’avenir serait compromis sans des héros comme vous qui œuvrent pour les trolls Darkspear. Merci pour tous vos efforts !", rewards = nil},
[7838] = {title = "Grand maître de l'arène", objective = "Salut, l’terrien ! Ramenez-moi 12 bijoux du Maître de l’arène et vous serez le Roi de l’arène des Gurubashi ! Arrrr !", description = nil, progress = "Salut, l’terrien ! Ramenez-moi 12 bijoux du Maître de l’arène et vous serez le Roi de l’arène des Gurubashi ! Arrrr !", completion = "Le sol de l'arène est rouge du sang que vous avez versé. Je suis fier de vous nommer Roi de l'arène !", rewards = "Vous recevrez :\n\nGrand maître de l'arène"},
[7839] = {title = "Les voyous Vilebranch", objective = "Le forgeron Slagtree du village des Revantusk, dans les Hinterlands, vous demande de retrouver les Outils perdus de Slagtree. Retournez le voir lorsque vous les aurez.\n\nIl a laissé entendre qu’ils pourraient se trouver dans l’un des temples des Vilebranch, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d’œil au rocher de l’Affût.", description = "Ces vermines de Vilebranch ont envahi notre village et volé mes outils ! J’ai des outils de rechange, mais ceux qu’ils m’ont volé m’avaient été offerts par un bon gnome, qui m’a sauvé la vie dans ma jeunesse.\n\nJe veux les récupérer, <nom>. J’y tiens énormément.\n\nMarkhor m’a dit qu’ils avaient été vus près des temples d’Agol’watha et de Shaol’watha.\n\nCes temples sont au nord-est des Hinterlands.\n\nRetrouvez mes outils !", progress = "Prenez garde aux trolls Vilebranch, <nom>. Ce sont des brutes cruelles.", completion = "Mes outils ! Vous les avez trouvés ! Oh, jour glorieux ! Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[7840] = {title = "Lard a perdu son déjeuner !", objective = "Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.\n\nD’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux trolls Vilebranch !", description = "Lard était dans son endroit secret spécial pour pique-nique quand vilains Vilebranch affreux sont venus et ont tapé sur la tête de Lard avec le gros bâton. Lard a couru jusqu’à village Revantusk, mais Lard a oublié son déjeuner. Lard a faim. Vous pouvoir aller dans endroit secret spécial et prendre déjeuner de Lard ? Lard a peur. C’est au nord ! L’endroit secret special être île au nord.", progress = "<Lard frotte mélancoliquement son énorme bedaine.>\n\nLard a très faim.", completion = "&lt;Lard vous arrache un énorme morceau de viande des mains et se l’enfourne dans la bouche.&gt;\n\nÇa fait du bieeeen ! Merci, tout-petit.\n\nVous avez aidé Lard, alors Lard va vous faire panier de pique-nique spécial.", rewards = "Vous recevrez :\n\nPanier de pique-nique spécial de Lard"},
[7841] = {title = "Un message pour les Wildhammer", objective = "Otho Moji'ko du village des Revantusk dans les Hinterlands veut que vous massacriez 15 Estafettes du Haut-val, 15 Eclaireurs du Haut-val, 15 Tireurs d'élite du Haut-val et 15 Forestiers du Haut-val. Revenez le voir lorsque vous aurez terminé.\n\nVous pouvez trouver les elfes du Haut-val au Gîte de Quel’Danil, au nord-ouest des Hinterlands.", description = "Les Wildhammer sont en train de passer des marchés avec nos ennemis, de forger de nouvelles alliances. Cette fois, ils travaillent avec les hauts elfes !\n\n<Otho crache.>\n\nIl faut qu’on leur envoie un message, à ces nains. Un message écrit avec le sang de nos ennemis. Tuez tous les hauts elfes du Haut-val que vous pourrez trouver, et exposez leurs cadavres en guise d'avertissement.\n\nOn ne joue pas avec les trolls !", progress = nil, completion = "On dirait bien que les Revantusk aussi se trouvent de nouveaux alliés, pas vrai ? Beau boulot.", rewards = "Vous recevrez :\n\n"},
[7842] = {title = "Encore un message pour les Wildhammer", objective = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de lui ramener 10 Longues plumes élégantes prélevées sur les gryphons qui vivent dans les Hinterlands. Retournez le voir lorsque vous les aurez.\n\nOn trouve des gryphons dans tous les Hinterlands.", description = "On dit que les Wildhammer et leurs gryphons sont aussi proches les uns des autres que trolls et trollesses. Ouais, c’est dégoûtant, mais on peut en profiter. On va leur envoyer un autre message.\n\nTuez tous les gryphons que vous trouverez dans les Hinterlands et récupérez leurs plumes. On s’en servira pour préparer le dernier message.", progress = "Le dernier message va leur faire salement peur. Ou alors, il va les mettre très, très en colère.", completion = "Oh, ça va être bien ! Plus qu’une étape, et les Wildhammer verront qu’on ne plaisante pas avec les trolls !", rewards = "Vous recevrez :\n\n"},
[7843] = {title = "Le message final pour les Wildhammer", objective = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de vous rendre au Nid-de-l’Aigle, à l’ouest des Hinterlands. Vous devez placer le Message final pour les Wildhammer près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche.\n\nFaites attention aux nains Wildhammer, qui risquent de mal le prendre, et aux autres membres de l’Alliance.", description = "<Otho vous tend une longue lance tachée de sang, ornée de plusieurs plumes de gryphon.>\n\nVous prenez ça, mon pote. Vous l’amenez au Nid-de-l’Aigle, pile au centre de la ville, près du puits. Et là, vous le plantez ! En plein dans le sol ! Faut montrer à ces nains que les trolls ne plaisantent pas ! Revenez quand vous l’aurez fait. Vivant, si possible.", progress = nil, completion = "J’aurais bien aimé être là pour voir leurs têtes, v’savez. Ils font leurs bagages, ou pas encore ?\n\nC’est du bon travail, &lt;nom&gt;. Très bon. Otho va vous donner un sacré mojo en récompense.", rewards = "Vous recevrez :\n\nGants en cuir de chouettard"},
[7844] = {title = "Les cousins cannibales", objective = "Yayo’jin la Mystique, du village des Revantusk des Hinterlands, veut que tuiez 30 Scalpeurs Vilebranch et 15 Devins Vilebranch. Retournez la voir lorsque vous aurez terminé.\n\nD’après Yayo’jin, ces trolls se trouvent près des temples de Shaol'watha et d’Agol'watha, au nord-nord-est des Hinterlands.", description = "Trois tribus de trolls habitent les Hinterlands, <nom>. En vérité, cela résume tout ce qui nous rassemble : nous sommes des trolls et nous vivons dans les Hinterlands.\n\nLes bien nommés Vilebranch sont des dégénérés qui n’hésitent pas à manger d’autres trolls et d’autres humanoïdes.\n\nSi Zul’jin était là, il les détruirait tous d’un revers de main, mais hélas, Zul’jin n’est pas revenu, et nous sommes livrés à nous-mêmes.\n\nIl vous revient d’anéantir ces nuisibles !", progress = nil, completion = "Beau travail, &lt;classe&gt;. Zul’jin en personne n’aurait pas fait mieux !", rewards = "Vous recevrez :\n\n"},
[7845] = {title = "L’Ancien Torntusk a été enlevé !", objective = "L’Aînée Torntusk du village des Raventusk des Hinterlands vous demande de libérer son compagnon, l’Ancien Torntusk, de Jintha’alor.\n\nVous savez qu’il est prisonnier au sommet de Jintha’alor, la capitale des Vilebranch, qui se trouve au sud des Hinterlands.", description = "Mon compagnon a été capturé par les sauvages Vilebranch au cours d’un raid nocturne sur notre village. Nos espions m’ont informé qu’il était encore en vie. Ils le gardent prisonnier au sommet de Jintha’alor. Il semble que la vile prêtresse Maléficia soit en train de le préparer pour le sacrifier à un dieu sanglant et sans visage.\n\nVous devez le sauver, <nom> ! Notre village ne supporterait pas de le perdre.", progress = nil, completion = "Vous devez agir rapidement, &lt;nom&gt;. Les gardes sont sûrement au courant de votre présence, à présent.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7846] = {title = "Récupérez la clé !", objective = "L’Ancien Torntusk, à Jintha’alor, veut que vous tuiez Hitah’ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l’Ancien Torntusk.", description = "La clé de mes menottes est aux mains d’Hitah’ya la Gardienne. Elle est dans la caverne d’à côté. Prenez garde, <classe>, car elle est bien protégée.\n\nTuez-la et ramenez-moi la clé qui ouvre ces chaînes. Lorsque je serai libre, je pourrai rentrer chez moi.", progress = "Hâtez-vous !", completion = "Enfin libre ! Merci, &lt;nom&gt;. Les Revantusk se souviendront de vos actions.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[7847] = {title = "Retourner voir l’Aînée Torntusk", objective = "L’Ancien Torntusk, à Jintha’alor, veut que vous retourniez voir l’Aînée Torntusk du village des Revantusk et que vous lui appreniez qu’il est sauvé.", description = "Retournez voir ma compagne, l’Aînée Torntusk du village des Revantusk. Dites-lui que je serai bientôt de retour ! Elle ne manquera pas de vous récompenser.", progress = nil, completion = "Vous avez rendu un grand service aux Revantusk, &lt;nom&gt; ! Nous avons une dette envers vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nArc des Hautes-terresFlacon de mojo sylvestre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7848] = {title = "Harmonisation avec le Cœur du Magma", objective = "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock.", description = "La faille s’agite, s’élargit et s’effondre tout autour de nous, <race>. À deux pas de l’endroit où je me tiens, une déchirure conduit dans les profondeurs du mont Blackrock, droit dans la gueule du seigneur du Feu.\n\nCela vous étonne ? Quelle tristesse… les races mortelles sont incapables de comprendre ce qu’elles ne peuvent ni toucher, ni voir, ni sentir.\n\nJe vous assure que le portail existe et qu’il est possible de le traverser.\n\nJ’ai piqué votre intérêt ? La procédure est simple. Pénétrez dans les profondeurs de Blackrock et récupérez un fragment du Magma. Ramenez-le-moi, et j’harmoniserai votre essence avec le portail.", progress = "Vous devez mettre votre âme en harmonie avec le Cœur du Magma avant de pouvoir entrer.", completion = "Je peux maintenant vous transporter au Coeur du Magma. Demandez et vous serez exaucé.", rewards = "Vous allez être la cible du sort suivant :\n\nHarmonisation avec le Cœur du magma\n\nVous recevrez :\n\n"},
[7849] = {title = "L’angoisse de la séparation", objective = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor.\n\nMarkhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranch. Il a également mentionné l’existence d’une décharge remplie de limons à Jintha’alor, ainsi que celle d’un enclos à loups. Tous deux se trouvent près du sommet du temple.", description = "Comme bien des gens dans notre village, j’ai perdu un être cher. Malkhor, mon frère jumeau, a été pris dans le même raid des Vilebranch que le compagnon de Torntusk.\n\nHélas, il n’était pas destiné à vivre. Ils l’ont tué vite, et ils ont abandonné son cadavre aux limons et aux loups des Vilebranch.\n\nIl est trop tard pour sauver son corps, mais il est encore temps de sauver son âme. Récupérez ses restes, <nom>.", progress = "Lorsque j’aurai ses restes, je les apporterai à Yayo’jin et je veillerai à ce qu’ils soient préparés pour l’enterrement.", completion = "Mon frère bien-aimé, tu me manques…\n\nMerci de votre aide, &lt;nom&gt;. Pour moi, vous êtes un véritable héros.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCuissards de plaques de bois laquéesProtège-mains vertefeuille\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7850] = {title = "Les calices ténébreux", objective = "L’Aînée Torntusk du village des Revantusk, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha’alor. Retournez voir l’Aînée Torntusk lorsque vous aurez terminé.", description = "À cause de la magie impure de la vile prêtresse Maléficia, les Vilebranch font preuve d’une férocité surnaturelle.\n\nDans tout Jintha’alor, vous trouverez des calices ténébreux, pleins de sang corrompu. Ils irradient la magie abjecte de leur dieu sans visage, donnant de la force aux Vilebranch tout en les rendant fous.\n\nVolez ces calices et ramenez-les-moi, afin que je les purifie. Si j’en ai suffisamment, je pourrai desserrer l’étreinte de leur dieu sanglant.", progress = "Prenez garde lorsque vous combattrez les Vilebranch, <nom>. Leurs esprits sont embrumés – ils se battront jusqu’à la mort.", completion = "L’énergie ténébreuse qui poussait les Vilebranch a été dispersée… pour l’instant. Nous devrons toujours rester vigilants dans notre bataille contre le mal, car même si la Vile prêtresse était tuée, une autre prendrait bientôt sa place.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSouffle de la Nature"},
[7861] = {title = "On recherche : la vile prêtresse Maléficia et ses sbires", objective = "Vous avez reçu l’ordre de tuer la vile prêtresse Maléficia et 20 Gardes Ama’zasi Vilebranch. Lorsque vous aurez terminé, allez voir l’Aînée Torntusk au village des Revantusk, dans les Hinterlands.\n\nLa vile prêtresse Maléficia et la garde Aman’zasi ont leurs quartiers au sommet de Jintha’alor, dans les Hinterlands.", description = "Par ordre de l’Aînée Torntusk, la vile prêtresse Maléficia et ses sbires doivent être mis à mort !\n\nUne forte récompense est offerte à tous ceux qui parviendront à tuer la vile prêtresse Maléficia et la totalité de sa garde d’élite Aman'zasi.", progress = nil, completion = "En vérité, c’est un dur coup porté aux Vilebranch. Vous serez richement récompensé, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCollier de lierre tresséCape des bois profonds\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7862] = {title = "Offre d’emploi : capitaine de la garde du village des Revantusk", objective = "Vous avez été <chargé/chargée> de liquider 20 Berserkers Vilebranch, 20 Chasseurs des ombres Vilebranch, 20 Sanguinaires Vilebranch et 20 Mangeurs d’âmes Vilebranch.\n\nLorsque vous aurez terminé, allez parler à l’Aînée Torntusk, du village de Revantusk dans les Hinterlands.", description = "Suite à la mort du capitaine Malkhor, le poste de capitaine de la garde de Revantusk est à pourvoir. Si vous désirez devenir capitaine de la garde de Revantusk, accomplissez les tâches suivantes avant de présenter votre candidature à l’Aînée Tornstusk :\n\nExterminer des Berserkers Vilebranch.\n\nExterminer des Chasseurs des ombres Vilebranch.\n\nExterminer des Sanguinaires Vilebranch.\n\nExterminer des Mangeurs d’âmes Vilebranch.", progress = nil, completion = "En vérité, vous êtes digne de ce poste, &lt;nom&gt;. Acceptez cette babiole en signe de notre appréciation pour votre travail. J’examinerai toutes les candidatures l’année prochaine.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nRune de capitaine de la garde"},
[7863] = {title = "Paquetage de base de Sentinelle", objective = "Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.\n\nSi vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage de base de sentinelle"},
[7864] = {title = "Paquetage ordinaire de Sentinelle", objective = "Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.\n\nSi vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage ordinaire de sentinelle"},
[7865] = {title = "Paquetage amélioré de Sentinelle", objective = "Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.\n\nSi vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage amélioré de sentinelle"},
[7866] = {title = "Paquetage de base de Voltigeur", objective = "Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.\n\nSi vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage de base de voltigeur"},
[7867] = {title = "Paquetage ordinaire de Voltigeur", objective = "Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.\n\nSi vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage ordinaire de voltigeur"},
[7868] = {title = "Paquetage amélioré de Voltigeur", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPaquetage amélioré de voltigeur"},
[7869] = {title = "test quest - do not use", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7870] = {title = "test quest2 - do not use", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7871] = {title = "Triomphez des envahisseurs !", objective = "Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent.", description = "Au-delà de ce tunnel, vous trouvez un lieu d'affrontement et de chaos, jeune <classe>. La Horde continue à massacrer notre forêt sacrée, abattant les conifères pour alimenter leurs engins de guerre.\n\nEntrez dans le goulet des Warsong, et défendez le fort d'Aile-argent. Repoussez les envahisseurs de la Horde !\n\nSi vous y parvenez, vous gagnerez un talisman de vaillance. Apportez-moi l'un de ces talismans, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7872] = {title = "Triomphez des envahisseurs !", objective = "Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent.", description = "Au-delà de ce tunnel, vous trouvez un lieu d'affrontement et de chaos, jeune <classe>. La Horde continue à massacrer notre forêt sacrée, abattant les conifères pour alimenter leurs engins de guerre.\n\nEntrez dans le goulet des Warsong, et défendez le Fort Aile-argent. Repoussez les envahisseurs de la Horde !\n\nSi vous y parvenez, vous gagnerez un talisman de vaillance. Apportez-moi l'un de ces talismans, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7873] = {title = "Triomphez des envahisseurs !", objective = "Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent.", description = "Au-delà de ce tunnel, vous trouvez un lieu d'affrontement et de chaos, jeune <classe>. La Horde continue à massacrer notre forêt sacrée, abattant les conifères pour alimenter leurs engins de guerre.\n\nEntrez dans le goulet des Warsong, et défendez le fort d'Aile-argent. Repoussez les envahisseurs de la Horde !\n\nSi vous y parvenez, vous gagnerez un talisman de vaillance. Apportez-moi l'un de ces talismans, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7874] = {title = "Écrasez les usurpateurs d'Aile-argent", objective = "Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan.", description = "La sauvagerie de la forêt d'Ashenvale succombera devant la puissance de la Horde, <race>. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !\n\nQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d'Aile-argent, et vous gagnerez une marque d'honneur Warsong. Revenez me voir avec l'une de ces marques, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7875] = {title = "Écrasez les usurpateurs d'Aile-argent", objective = "Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan.", description = "La sauvagerie de la forêt d'Ashenvale succombera devant la puissance de la Horde, <race>. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit ! \n\nQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d'Aile-argent, et vous gagnerez une marque d'honneur Warsong. Revenez me voir avec l'une de ces marques, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7876] = {title = "Écrasez les usurpateurs d'Aile-argent", objective = "Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan.", description = "La sauvagerie de la forêt d'Ashenvale succombera devant la puissance de la Horde, <race>. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit ! \n\nQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d'Aile-argent, et vous gagnerez une marque d'honneur Warsong. Revenez me voir avec l'une de ces marques, <nom>, et je vous récompenserai.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7877] = {title = "Le trésor des Shen'dralar", objective = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !", description = "Dans l’Athenaeum, la bibliothèque, vous trouverez un vieux coffre caché sous l’escalier. Prenez-y ce que vous voulez.", progress = nil, completion = "Vous ouvrez le coffre pour trouver…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBroie-les-osCasque des taillisBottes de carex\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[7881] = {title = "Des bottes pour les forains", objective = "Nous autres forains de la foire de Sombrelune marchons beaucoup.  Nous marchons d'un site à l'autre... en fait, vous ne nous verrez jamais assis !  Pas étonnant que nous usions autant de bottes !  Nous avons besoin de bottes qui soient à la fois robustes et élégantes, et les bottes en cuir estampé correspondent bien à cette description.\n\nVous !  Vous êtes un artisan du cuir : faites-moi des bottes en cuir estampé et je vous donnerai un bon de la foire de Sombrelune pour votre peine.", description = nil, progress = "Nous autres forains de la foire de Sombrelune marchons beaucoup.  Nous marchons d'un site à l'autre... en fait, vous ne nous verrez jamais assis !  Pas étonnant que nous usions autant de bottes !  Nous avons besoin de bottes qui soient à la fois robustes et élégantes, et les bottes en cuir estampé correspondent bien à cette description.\n\nVous !  Vous êtes un artisan du cuir : faites-moi des bottes en cuir estampé et je vous donnerai un bon de la foire de Sombrelune pour votre peine.", completion = "Merci, &lt;nom&gt;. Elles sont de très belle facture. Vous êtes un artisan de grand talent ! Voici un bon de la foire de Sombrelune... Pour vous, ma dame.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7882] = {title = "Des tuniques pour les forains", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7883] = {title = "Le gnome le plus grand du monde !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7884] = {title = "L'enfant crocilisque et le murloc barbu", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7885] = {title = "Renforts d'armure", objective = "Vous ne le savez peut-être pas, mais faire fonctionner une foire ambulante est très coûteux !  Tout s'use si vite que c'est un miracle si nous faisons des bénéfices.\n\nEn raison de tous ces coûts cachés, nous sommes toujours à la recherche de moyens d'entretenir notre matériel à moindres frais.  Nos tentes, par exemple, se déchirent souvent, mais les renforts d'armure en cuir sont parfaits pour les raccommoder.  Pouvez-vous m'apporter des renforts d'armure ?  Cela nous ferait faire de sacrées économies !  Si vous pouvez faire ça pour moi, je vous donnerai une poignée de bons de la foire de Sombrelune...", description = nil, progress = "Vous ne le savez peut-être pas, mais faire fonctionner une foire ambulante est très coûteux !  Tout s'use si vite que c'est un miracle si nous faisons des bénéfices.\n\nEn raison de tous ces coûts cachés, nous sommes toujours à la recherche de moyens d'entretenir notre matériel à moindres frais.  Nos tentes, par exemple, se déchirent souvent, mais les renforts d'armure en cuir sont parfaits pour les raccommoder.  Pouvez-vous m'apporter des renforts d'armure ?  Cela nous ferait faire de sacrées économies !  Si vous pouvez faire ça pour moi, je vous donnerai une poignée de bons de la foire de Sombrelune...", completion = "Formidable ! Voilà qui ira très bien ! Je viens juste de remarquer une déchirure dans une tente là-bas, et c'est exactement ce qu'il me faut pour la raccommoder !\n\nMerci beaucoup, &lt;nom&gt;.  Ces renforts d'armure vont nous épargner de grosses dépenses. Voici vos bons, vous les avez bien mérités !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7886] = {title = "Talismans de vaillance", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7887] = {title = "Talismans de vaillance", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7888] = {title = "Talismans de vaillance", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7889] = {title = "Le caillou grossier", objective = "Être la femme la plus forte du monde demande beaucoup de travail ! Mon ensemble de poids commence à être trop léger et pour rester en forme il m'en faut plus !\n\nCroyez-vous que vous pourriez me procurer des cailloux ? Si oui, je vous donnerai un bon de la foire de Sombrelune.", description = nil, progress = "Être la femme la plus forte du monde demande beaucoup de travail ! Mon ensemble de poids commence à être trop léger et pour rester en forme il m'en faut plus !\n\nCroyez-vous que vous pourriez me procurer des cailloux ? Si oui, je vous donnerai un bon de la foire de Sombrelune.", completion = "Super ! Ils conviendront à merveille ! Ils ne sont ni trop lourds, ni trop légers. Parfaits pour développer de la masse musculaire !\n\nMerci beaucoup, &lt;nom&gt;. Voici votre bon de la foire de Sombrelune !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7890] = {title = "Silex à aiguiser lourd", objective = "Pour mon entraînement, j'aime fixer un bâton entre des silex à aiguiser lourds puis soulever le bâton au-dessus de ma tête. Ce n'est pas facile, mais on ne devient pas la femme la plus forte du monde en restant assise !\n\nPouvez-vous m'aider ? Il me faut plus de silex à aiguiser, apportez-m'en et je vous donnerai des bons de la foire de Sombrelune.", description = nil, progress = "Pour mon entraînement, j'aime fixer un bâton entre des silex à aiguiser lourds puis soulever le bâton au-dessus de ma tête. Ce n'est pas facile, mais on ne devient pas la femme la plus forte du monde en restant assise !\n\nPouvez-vous m'aider ? Il me faut plus de silex à aiguiser, apportez-m'en et je vous donnerai des bons de la foire de Sombrelune.", completion = "Vous avez apporté les pierres ! Elles sont lourdes ! Je sens déjà mes muscles grossir. Merci, &lt;nom&gt; !\n\nTenez, prenez ces bons, et prenez garde à ne pas manger trop de bonbons à la foire. Un grand et fort &lt;classe&gt; comme vous doit rester en forme !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7891] = {title = "Bracelets en fer émeraude", objective = "Je travaille à un nouveau costume pour quand j'aurai mon propre stand de femme la plus forte du monde !  En ce moment, je cherche des bracelets.  Ils ne doivent pas être trop grands parce que les gens veulent voir mes muscles, mais je veux quand même qu'il y ait de la couleur, vous comprenez ?\n\nPourquoi pas des bracelets en fer émeraude, <nom> ? Pouvez-vous me faire des bracelets en fer émeraude ?  Si oui, j'aurai un beau paquet de bons de la foire de Sombrelune pour vous.", description = nil, progress = "Je travaille à un nouveau costume pour quand j'aurai mon propre stand de femme la plus forte du monde !  En ce moment, je cherche des bracelets.  Ils ne doivent pas être trop grands parce que les gens veulent voir mes muscles, mais je veux quand même qu'il y ait de la couleur, vous comprenez ?\n\nPourquoi pas des bracelets en fer émeraude, <nom> ? Pouvez-vous me faire des bracelets en fer émeraude ?  Si oui, j'aurai un beau paquet de bons de la foire de Sombrelune pour vous.", completion = "Oui !  C'est exactement ce qu'il me faut !  Ils sont d'une si belle couleur, et ils découvrent assez mes bras pourqu'on voie comme ils sont forts !  Parfait !\n\nTenez, &lt;nom&gt;.  Voici vos bons, amusez-vous bien !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7892] = {title = "Grande masse noire", objective = "Pour mon numéro de femme la plus forte du monde, j'ai prévu de demander des objets au public et de les écraser avec une grande masse noire !\n\nPouvez-vous me faire une grande masse noire, <nom> ?", description = nil, progress = "Pour mon numéro de femme la plus forte du monde, j'ai prévu de demander des objets au public et de les écraser avec une grande masse noire !\n\nPouvez-vous me faire une grande masse noire, <nom> ?", completion = "Ah, parfait !  Cette masse a une tête bien grosse et lourde.  Je parie que je pourrais écraser n'importe quoi avec.  J'espère seulement qu'elle ne cassera pas aussi !\n\nVoici vos bons, &lt;nom&gt;.  Amusez-vous bien à la foire !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7893] = {title = "Rituels de force", objective = "<nom>, dans ma quête pour devenir la femme la plus forte du monde, j'ai parcouru le monde et appris les secrets de musculation de lointains maîtres des poids, de gourous de la force et de manuels anciens.  Je connais maintenant des exercices interdits qui tueraient les faibles et estropieraient les non-initiés !\n\nCes prouesses de force et de conditionnement requièrent un entraînement à l'aide des pierres à aiguiser les plus denses.  <nom>, pouvez-vous trouver ou fabriquer ces pierres et me les apporter ? Je vous donnerai des bons en échange…", description = nil, progress = "<nom>, dans ma quête pour devenir la femme la plus forte du monde, j'ai parcouru le monde et appris les secrets de musculation de lointains maîtres des poids, de gourous de la force et de manuels anciens.  Je connais maintenant des exercices interdits qui tueraient les faibles et estropieraient les non-initiés !\n\nCes prouesses de force et de conditionnement requièrent un entraînement à l'aide des pierres à aiguiser les plus denses.  <nom>, pouvez-vous trouver ou fabriquer ces pierres et me les apporter ? Je vous donnerai des bons en échange…", completion = "Merci, &lt;nom&gt;.  J'utiliserai ces pierres pour un rituel de gain de force que j'ai appris d'une tablette ancienne au plus profond des jungles de Strangleronce.\n\nOn dit que celle qui accomplira correctement ce rite sacré aura la force et l'endurance de dix taurens !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7894] = {title = "Modulateurs de cuivre", objective = "Yebb travaille à une nouvelle attraction pour l'Etonnante Ménagerie qui stupéfiera et ravira les visiteurs !  Mais cela demandera beaucoup de travail et beaucoup de matériel...\n\nY compris des Modulateurs de cuivre.  Il nous faut beaucoup de modulateurs pour les parties mécaniques de l'attraction.  Apportez-moi des Modulateurs de cuivre et je vous donnerai un bon de la foire de Sombrelune en échange.", description = nil, progress = "Yebb travaille à une nouvelle attraction pour l'Etonnante Ménagerie qui stupéfiera et ravira les visiteurs !  Mais cela demandera beaucoup de travail et beaucoup de matériel...\n\nY compris des Modulateurs de cuivre.  Il nous faut beaucoup de modulateurs pour les parties mécaniques de l'attraction.  Apportez-moi des Modulateurs de cuivre et je vous donnerai un bon de la foire de Sombrelune en échange.", completion = "Aha ! Les modulateurs ! Splendide !\n\nJe ne peux vous dire exactement ce que nous construisons, mais voilà qui nous sera très utile. Je suis votre obligé, &lt;nom&gt;, mais veuillez prendre ce bon de la foire de Sombrelune en signe de ma gratitude.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7895] = {title = "Bidules bourdonnants en bronze", objective = "Mon nouveau stand sera quelque chose à ne pas manquer, oui monsieur !  Et pour quelques chanceux, quelque chose à toucher aussi !\n\nJ'entends déjà les Bidules bourdonnants en bronze entonnant un chant d'extase mécanique quand les clients entreront dans mon stand pour tester leur habileté !\n\nAh... maintenant il me faut les bidules pour que mon rêve devienne réalité. S'il vous plaît, <nom>, apportez-moi des Bidules bourdonnants en bronze... et des bons de la foire de Sombrelune vous attendront !", description = nil, progress = "Mon nouveau stand sera quelque chose à ne pas manquer, oui monsieur !  Et pour quelques chanceux, quelque chose à toucher aussi !\n\nJ'entends déjà les Bidules bourdonnants en bronze entonnant un chant d'extase mécanique quand les clients entreront dans mon stand pour tester leur habileté !\n\nAh... maintenant il me faut les bidules pour que mon rêve devienne réalité. S'il vous plaît, <nom>, apportez-moi des Bidules bourdonnants en bronze... et des bons de la foire de Sombrelune vous attendront !", completion = "Vous avez apporté les bidules !  Merveilleux !  Je les entends déjà bourdonner en chœur !  Oh, quand ce stand sera prêt, ce sera l'une des merveilles du monde, croyez-moi !\n\nVoici vos bons, &lt;nom&gt;.  Et profitez bien de votre visite à la foire !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7896] = {title = "Feux d'artifice vert", objective = "Quand j'aurai enfin mon stand, je voudrai m'offrir de la publicité !  Quel meilleur moyen y aurait-il pour cela que des feux d'artifice ?\n\nOui, certains pensent sûrement que l'odeur d'un chaudron bouillonnant rempli des têtse de vos ennemis serait une meilleure idée pour attirer les foules, mais... nous ne sommes pas seuls ici.  Il faudra donc que ce soit des feux d'artifice !\n\nApportez-moi des feux d'artifice verts, <nom>, et j'aurai plein de bons de la foire de Sombrelune pour vous.", description = nil, progress = "Quand j'aurai enfin mon stand, je voudrai m'offrir de la publicité !  Quel meilleur moyen y aurait-il pour cela que des feux d'artifice ?\n\nOui, certains pensent sûrement que l'odeur d'un chaudron bouillonnant rempli des têtse de vos ennemis serait une meilleure idée pour attirer les foules, mais... nous ne sommes pas seuls ici.  Il faudra donc que ce soit des feux d'artifice !\n\nApportez-moi des feux d'artifice verts, <nom>, et j'aurai plein de bons de la foire de Sombrelune pour vous.", completion = "Vous avez apporté les feux d'artifice.  Excellent travail, &lt;nom&gt; !  Comme je me réjouis pour les allumer et informer le monde que mon stand est prêt !  Il faudra hélas encore attendre un bon bout de temps, mais...  ce sera prêt quand ce sera prêt, n'est-ce pas ?\n\nVoici vos bons, &lt;nom&gt;.  Amusez-vous bien !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7897] = {title = "Trousses de réparation mécanique", objective = "La principale raison pour laquelle je ne peux pas ouvrir mon stand, c'est que... rien n'est en état de marche !  Il me faut des trousses de réparation mécanique pour réparer tout ça !\n\nPouvez-vous m'apporter ces trousses, <nom> ?  En échange, je vous donnerai... des trousses de bons de la foire de Sombrelune.  Qu'en dites-vous ?", description = nil, progress = "La principale raison pour laquelle je ne peux pas ouvrir mon stand, c'est que... rien n'est en état de marche !  Il me faut des trousses de réparation mécanique pour réparer tout ça !\n\nPouvez-vous m'apporter ces trousses, <nom> ?  En échange, je vous donnerai... des trousses de bons de la foire de Sombrelune.  Qu'en dites-vous ?", completion = "Merci ! Maintenant je peux commencer à tout réparer.\n\nIl va falloir beaucoup de trousses de réparation et de nuits blanches pour que tout soit en état de marche.  Parfois, je me dis que je ferais mieux de revenir à mes racines et reprendre ma carrière de chasseur de tête, mais... la foire a été très bonne pour moi.\n\nPrenez ces bons, &lt;nom&gt;, et amusez-vous !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7898] = {title = "Rouages en thorium", objective = "Yebb Nebblegear, comme moi, travaille à une nouvelle attraction. D'après Nebb, elle est tellement stupéfiante qu'elle attirera des gens du monde entier... et elle nous rendra tous très, très riches !\n\nIl dit qu'il lui faut des rouages en thorium pour sa construction et il veut que je me les procure pour lui. Qu'en pensez-vous, <nom> ? Savez-vous où je pourrais en trouver ? Si vous êtes ingénieur, pourriez-vous en fabriquer ? Voulez-vous en échanger contre des bons de la foire de Sombrelune ?", description = nil, progress = "Yebb Nebblegear, comme moi, travaille à une nouvelle attraction. D'après Nebb, elle est tellement stupéfiante qu'elle attirera des gens du monde entier... et elle nous rendra tous très, très riches !\n\nIl dit qu'il lui faut des rouages en thorium pour sa construction et il veut que je me les procure pour lui. Qu'en pensez-vous, <nom> ? Savez-vous où je pourrais en trouver ? Si vous êtes ingénieur, pourriez-vous en fabriquer ? Voulez-vous en échanger contre des bons de la foire de Sombrelune ?", completion = "Ah, merci, &lt;nom&gt; !  Yebb sera enchanté par ces rouages.  Je ne sais pas ce qu'il va faire avec, mais Yebb est un petit &lt;race&gt; très malin.  Il est malin, et peut-être un peu sournois....\n\nSi seulement il aimait le goût de la chair humanoïde... il serait un très bon troll !\n\nTenez, &lt;nom&gt;.  Une promesse est une promesse, et ces bons vous appartiennent.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7899] = {title = "Petites pattes en fourrure", objective = "Pour attirer beaucoup de monde, il faut avant tout appâter les gens avec des gadgets et des bibelots ! Pouvez-vous m'aider ?\n\nJ'ai besoin de petites pattes en fourrure pour en faire des lots.  Vous pouvez les trouver sur les félins des Tarides ou de Sombrivage....\n\nApportez-moi des pattes et je vous les échangerai contre un bon de la foire de Sombrelune.", description = nil, progress = "Pour attirer beaucoup de monde, il faut avant tout appâter les gens avec des gadgets et des bibelots ! Pouvez-vous m'aider ?\n\nJ'ai besoin de petites pattes en fourrure pour en faire des lots.  Vous pouvez les trouver sur les félins des Tarides ou de Sombrivage....\n\nApportez-moi des pattes et je vous les échangerai contre un bon de la foire de Sombrelune.", completion = "Formidable, vous les avez !  Nous allons en faire des jouets et des babioles, et cela va attirer encore plus de monde à la foire !\n\nVoici votre bon, &lt;nom&gt;.  Vous l'avez bien mérité !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7900] = {title = "Peaux d'ours déchirées", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7901] = {title = "Queues fournies soyeuses", objective = "C'est vraiment incroyable, ce à quoi les gens peuvent trouver de la valeur !  Prenez par exemple un bâton en bois avec une Queue fournie soyeuse attachée après.  Vous et moi savons qu'une choses pareille n'a pas grande valeur... mais si vous donnez à cette camelote un chouette nom du genre de \"Queue sauvage\" et la mettez dans une belle boîte, les gens croiront que ça a de la valeur.  La pacotille devient un trésor !\n\nCherchez pour moi des Queues fournies soyeuses sur les loups de Désolace et des Terres ingrates, et je vous donnerai des bons de la foire de Sombrelune.", description = nil, progress = "C'est vraiment incroyable, ce à quoi les gens peuvent trouver de la valeur !  Prenez par exemple un bâton en bois avec une Queue fournie soyeuse attachée après.  Vous et moi savons qu'une choses pareille n'a pas grande valeur... mais si vous donnez à cette camelote un chouette nom du genre de \"Queue sauvage\" et la mettez dans une belle boîte, les gens croiront que ça a de la valeur.  La pacotille devient un trésor !\n\nCherchez pour moi des Queues fournies soyeuses sur les loups de Désolace et des Terres ingrates, et je vous donnerai des bons de la foire de Sombrelune.", completion = "Bien joué, &lt;nom&gt; !  Ces queues feront de magnifiques lots pour nos visiteurs, ce qui veut dire qu'ils seront contents... et qu'ils parleront de la foire à leurs amis, et nous aurons donc plus de visiteurs !\n\nVoici vos bons !  Amusez-vous bien à la foire de Sombrelune... et n'oubliez pas de parler de nous à vos amis !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7902] = {title = "Plumes vibrantes", objective = "L'imagination est une chose incroyable. Grâce à elle, la moindre colline peut sembler être la plus haute montagne.  L'ombre la plus inoffensive peut paraître sortie d'une terrible cauchemar !\n\nIci, à la foire de Sombrelune, nous laissons libre court à l'imagination de nos visiteurs !  Mais pour les aider à laisser s'épanouir leur imagination... nous devons parfois faire preuve de ruse.\n\nIl me faut des plumes vibrantes pour une de mes attractions.  Vous pouvez les prendre sur les oiseaux des régions les plus dangereuses d'Azeroth.  Apportez-moi les plumes et vous recevrez beaucoup de bons !", description = nil, progress = "L'imagination est une chose incroyable. Grâce à elle, la moindre colline peut sembler être la plus haute montagne.  L'ombre la plus inoffensive peut paraître sortie d'une terrible cauchemar !\n\nIci, à la foire de Sombrelune, nous laissons libre court à l'imagination de nos visiteurs !  Mais pour les aider à laisser s'épanouir leur imagination... nous devons parfois faire preuve de ruse.\n\n", completion = "Ah, les plumes !  Elles sont magnifiques, vous ne trouvez pas !  Ce serait facile d'enflammer les imaginations avec de telles merveilles !\n\nVous êtes si généreux, &lt;nom&gt;.  Le sourire sur le visage de nos visiteurs quand ils verront le spectacle est en soi une grande récompense, mais veuillez également prendre ces bons.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7903] = {title = "Yeux de chauve-souris maléfique", objective = "Vous arrive-t-il parfois d'errer dans une grotte, tard la nuit, à la recherche d'aventures ?  Oui ?  Vraiment ?  Alors vous avez sûrement vu les yeux menaçants des chauves-souris qui vous fixent d'en haut, attendant que vous baissiez votre garde pour sucer votre sang !\n\nC'est effrayant, vous ne trouvez pas ?  Bien sûr !  Évidemment les yeux des chauves-souris sont effrayants !\n\nVoulez-vous me rapporter des yeux de chauve-souris maléfique, <nom>?  Il me les faut pour... quelque chose que je suis en train de mettre au point.  Quelque chose d'effrayant.\n\nVous pouvez les trouver sur les chauves-souris des Maleterres de l'est.", description = nil, progress = "Vous arrive-t-il parfois d'errer dans une grotte, tard la nuit, à la recherche d'aventures ?  Oui ?  Vraiment ?  Alors vous avez sûrement vu les yeux menaçants des chauves-souris qui vous fixent d'en haut, attendant que vous baissiez votre garde pour sucer votre sang !\n\nC'est effrayant, vous ne trouvez pas ?  Bien sûr !  Évidemment les yeux des chauves-souris sont effrayants !\n\nVoulez-vous me rapporter des yeux de chauve-souris maléfique, <nom>?  Il me les faut pour... quelque chose que je suis en train de mettre au point.  Quelque chose d'effrayant.\n\nVous pouvez les trouver sur les chauves-souris des Maleterres de l'est.", completion = "Formidable !  Vous avez les yeux !  J'espère que vous avez trouvé effrayant de chasser ces chauves-souris, parce que si ça a fait peur à un &lt;classe&gt; courageux comme vous, ces yeux vont certainement terrifier les visiteurs de la foire.\n\nPrenez ces bons, &lt;nom&gt;, et merci de m'avoir rendu ce service.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7905] = {title = "La foire de Sombrelune", objective = "Donnez le Coupon pour des bons gratuits à Gelvas Grimgate, qui se trouve dans la foire de Sombrelune.", description = "La foire de Sombrelune arrive ! Ne manquez pas d’admirer ses merveilles lorsqu’elle sera en ville !\n\nMieux, si vous le prenez maintenant, vous pourrez échanger ce coupon contre des bons gratuits ! Il vous suffira de le donner à Gelvas Grimgate, à l’intérieur de la foire !\n\nLa foire est juste à côté de Goldshire, c’est une occasion exceptionnelle, à saisir dès aujourd’hui !", progress = "Oui messire, puis-je vous aider ? Auriez-vous un coupon à échanger ?", completion = "Bienvenue à la foire de Sombrelune ! Ce coupon vous donne droit à CINQ, oui, CINQ bons gratuits !\n\nAccumulez des bons gratuits puis revenez me voir, je les échangerai contre des lots de valeur. Plus vous aurez de bons, plus vous pourrez récuperer de lots. Hourra !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7906] = {title = "Cartes de Sombrelune - Fauves", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7907] = {title = "Suite de Fauves de Sombrelune", objective = "Rapporter la suite de Fauves à la foire de Sombrelune quand elle reviendra en ville.", description = "Maintenant que vous avez rassemblé toutes les cartes de la suite de Fauves, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l’inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s’arrête à Mulgore et Goldshire tous les quelques mois. Vous devez donc attendre qu’elle revienne s’y installer.", progress = "Je vois que vous avez réussi à réunir une suite de Fauves ! Félicitations !", completion = "Ainsi donc, vous avez rassemblé une suite de Fauves.  En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.", rewards = "Vous recevrez :\n\nCarte de Sombrelune : Dragon bleu"},
[7908] = {title = "Le maître de l'arène", objective = "Parler à Short John Mithril dans l’arène de Strangleronce.\n\nObjet fourni : \n", description = "Être le maître d’une arène, ça ne doit pas se limiter à ça ! Le pirate qui anime celle des Gurubashi aura peut-être des conseils à me donner.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[7921] = {title = "Talismans de vaillance", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7922] = {title = "Marque d'honneur", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7923] = {title = "Marque d'honneur", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7924] = {title = "Marque d'honneur", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7925] = {title = "Marque d'honneur", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7926] = {title = "La foire de Sombrelune", objective = "Donnez le Coupon pour des bons gratuits à Gelvas Grimgate, qui se trouve dans la foire de Sombrelune.", description = "La foire de Sombrelune arrive ! Ne manquez pas d’admirer ses merveilles lorsqu’elle sera en ville !\n\nMieux, si vous le prenez maintenant, vous pourrez échanger ce coupon contre des bons gratuits ! Il vous suffira de le donner à Gelvas Grimgate, à l’intérieur de la foire !\n\nLa foire est juste à côté de Thunder Bluff, c’est une occasion exceptionnelle, à saisir dès aujourd’hui !", progress = "Oui messire, puis-je vous aider ? Auriez-vous un coupon à échanger ?", completion = "Bienvenue à la foire de Sombrelune ! Ce coupon vous donne droit à CINQ, oui, à CINQ bons gratuits !\n\nAccumulez des bons gratuits puis revenez me voir, je les échangerai contre des lots de valeur. Plus vous aurez de bons, plus vous pourrez récuperer de lots. Hourra !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7927] = {title = "Suite de Portails de Sombrelune", objective = "Rapporter la suite de Portails à la foire de Sombrelune quand elle reviendra en ville.", description = "Maintenant que vous avez rassemblé toutes les cartes de la suite de Portails, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l’inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s’arrête à Mulgore et Goldshire tous les quelques mois. Vous devez donc attendre qu’elle revienne s’y installer.", progress = "Je vois que vous avez réussi à réunir une suite de Portails ! Félicitations !", completion = "Ainsi donc, vous avez rassemblé une suite de Portails...  En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.", rewards = "Vous recevrez :\n\nCarte de Sombrelune : Néant distordu"},
[7928] = {title = "Suite de Seigneurs de guerre de Sombrelune", objective = "Rapporter la suite de Seigneurs de guerre à la foire de Sombrelune quand elle reviendra en ville.", description = "Maintenant que vous avez rassemblé toutes les cartes de la suite de Seigneurs de guerre, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l’inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s’arrête à Mulgore et Goldshire tous les quelques mois. Vous devez donc attendre qu’elle revienne s’y installer.", progress = "Je vois que vous avez réussi à réunir une suite de Seigneurs de guerre ! Félicitations !", completion = "Ainsi donc, vous avez rassemblé une suite de Seigneurs de guerre.  En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.", rewards = "Vous recevrez :\n\nCarte de Sombrelune : Héroïsme"},
[7929] = {title = "Suite d'Elémentaires de Sombrelune", objective = "Rapporter la suite d'Elémentaires à la foire de Sombrelune quand elle reviendra en ville.", description = "Maintenant que vous avez rassemblé toutes les cartes de la suite d'Elémentaires, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l’inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s’arrête à Mulgore et Goldshire tous les quelques mois. Vous devez donc attendre qu’elle revienne s’y installer.", progress = "Je vois que vous avez réussi à réunir une suite d'Elémentaires ! Félicitations !", completion = "Ainsi donc, vous avez rassemblé une suite d'Elémentaires.  En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.", rewards = "Vous recevrez :\n\nCarte de Sombrelune : Maelström"},
[7930] = {title = "5 bons - Fleur de Sombrelune", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nFleur de Sombrelune"},
[7931] = {title = "5 bons - Lot de Sombrelune (mineur)", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nLot de Sombrelune (mineur)"},
