[7934] = {title = "50 bons - Boîte de rangement de Sombrelune", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nBoîte de rangement de Sombrelune"},
[7935] = {title = "10 bons - Mouton du mois dernier", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nMouton du mois dernier"},
[7936] = {title = "50 bons - Mouton de l'an dernier", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMouton de l'an dernier"},
[7937] = {title = "Une surprise vous attend...", objective = "Allez dans le Camp de bûcherons du Val d'est dans la Forêt d'Elwynn pour trouver la surprise qui vous attend.", description = "Une surprise vous attend au Val d'est.\n\nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher.  Alors que vous la serrez dans votre main, vous avez une vision du Camp de bûcherons du Val d'est dans la Forêt d'Elwynn.  En vous concentrant sur cette image, vous voyez une meule de foin à côté d'une écurie.", progress = "Cette meule de foin ressemble à celle de votre vision.", completion = "Une fouille rapide de la meule de foin révèle un coffret à l'intérieur ! On dirait que vous avez trouvé votre surprise !", rewards = "Vous recevrez :\n\nCoffre mystérieux"},
[7938] = {title = "Une surprise vous attend...", objective = "Allez dans les Mortemines dans la marche de l'Ouest pour trouver la surprise qui vous attend.", description = "Une surprise vous attend à l'intérieur des Mortemines.\n\nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher.  Alors que vous la serrez dans votre main, vous avez une vision des Mortemines, situées dans le hameau en ruine de Ruisselune, dans la marche de l'Ouest.  En vous concentrant sur cette image, vous vous voyez emprunter des passages tortueux jusqu'à ce que vous atteigniez un portail étincelant... qui conduit au cœur même des mines.  Lorsque vous le traversez, un étrange coffre apparaît de nulle part.", progress = "Ce coffre ressemble à celui de votre vision.", completion = "Une fouille rapide du coffre révèle un coffret à l'intérieur ! On dirait que vous avez trouvé votre surprise !", rewards = "Vous recevrez :\n\nCoffre mystérieux"},
[7939] = {title = "Plus de silex à aiguiser denses", objective = "<nom>, je vous remercie de toute l’aide que vous m’avez apporté. Sincèrement, je ne vous remercierai jamais assez.\n\nEt même si j’en ai moins besoin maintenant, si vous me fournissez d’autres pierres à aiguiser denses, il se pourrait que je vous donne d’autres bons de la foire de Sombrelune.", description = nil, progress = "<nom>, je vous remercie de toute l’aide que vous m’avez apporté. Sincèrement, je ne vous remercierai jamais assez.\n\nEt même si j’en ai moins besoin maintenant, si vous me fournissez d’autres pierres à aiguiser denses, il se pourrait que je vous donne d’autres bons de la foire de Sombrelune.", completion = "Encore merci, &lt;nom&gt;. Profitez bien de vos bons, et parlez à vos amis de la foire de Sombrelune !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7940] = {title = "1200 bons - Orbe de la Sombrelune", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance ! !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance ! !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nOrbe de Sombrelune"},
[7941] = {title = "Plus de renforts d’armure", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7942] = {title = "Plus de rouages en thorium", objective = "<nom>, vous m’avez bien rendu service en m’amenant tout cela sans jamais vous lasser. Vous avez toute ma gratitude.\n\nNous avons moins besoin de rouages en thorium qu’à une certaine époque, mais si vous m’en amenez d’autres, je vous les échangerai contre des bons de la foire de Sombrelune.", description = nil, progress = "<nom>, vous m’avez bien rendu service en m’amenant tout cela sans jamais vous lasser. Vous avez toute ma gratitude.\n\nNous avons moins besoin de rouages en thorium qu’à une certaine époque, mais si vous m’en amenez d’autres, je vous les échangerai contre des bons de la foire de Sombrelune.", completion = "Et voilà, &lt;nom&gt;. Des bons de la foire de Sombrelune rien que pour vous. Comme on dit, ne faites pas d’excès !", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7943] = {title = "Plus d’yeux de chauve-souris", objective = "<nom>, l’attraction que je suis en train de créer sera la chose la plus effrayante qu’on ait vue depuis la chute de Gnomeregan ! Et c’est largement grâce à tout ce que vous m’avez apporté. Merci, merci mille fois !\n\nJe n’ai plus besoin de grand-chose mais… si vous m’apportez encore des yeux de chauve-souris maléfiques pris sur les chauve-souris des Maleterres de l’est… je pourrais avoir d’autres bons de la foire de Sombrelune pour vous.", description = nil, progress = "<nom>, l’attraction que je suis en train de créer sera la chose la plus effrayante qu’on ait vue depuis la chute de Gnomeregan ! Et c’est largement grâce à tout ce que vous m’avez apporté. Merci, merci mille fois !\n\nJe n’ai plus besoin de grand-chose mais… si vous m’apportez encore des yeux de chauve-souris maléfiques pris sur les chauve-souris des Maleterres de l’est… je pourrais avoir d’autres bons de la foire de Sombrelune pour vous.", completion = "Merci encore, &lt;nom&gt;. Voilà vos bons.", rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[7944] = {title = "Une surprise vous attend...", objective = "Allez dans les Cavernes des lamentations dans les Tarides pour trouver la surprise qui vous attend.", description = "Une surprise vous attend dans les Cavernes des lamentations.\n\nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher.  Alors que vous la serrez dans votre main, vous avez une vision d'une caverne située au sud-ouest de la Croisée, dans les Tarides.  En vous concentrant sur cette image, vous vous voyez emprunter des passages tortueux jusqu'à ce que vous atteigniez un portail étincelant... qui conduit au cœur même de la caverne.  Lorsque vous le traversez, un étrange coffre apparaît de nulle part.", progress = "Ce coffre ressemble à celui de votre vision.", completion = "Une fouille rapide du coffre révèle un coffret à l'intérieur ! On dirait que vous avez trouvé votre surprise !", rewards = "Vous recevrez :\n\nCoffre mystérieux"},
[7945] = {title = "Une surprise vous attend...", objective = "Allez à la Caverne des crins-pâles pour trouver la surprise qui vous attend.", description = "Une surprise vous attend devant la caverne des crins-pâles.\n\nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher.  Alors que vous la serrez dans votre main, vous avez une vision de la caverne des crins-pâles à Mulgore.  En vous concentrant sur cette image, vous voyez une souche juste à côté de l'entrée de la caverne.", progress = "Cette sourche ressemble à celle de votre vision.", completion = "Une fouille rapide de la souche révèle un coffret à l'intérieur ! On dirait que vous avez trouvé votre surprise !", rewards = "Vous recevrez :\n\nCoffre mystérieux"},
[7946] = {title = "Le rejeton de Jubjub", objective = "Je suis si content que Jubjub ait été retrouvée. Elle aime tellement la bière Sombrefer que lorsque je n’en ai plus… elle s’enfuit pour en chercher !\n\nMaintenant que Jubjub est revenue, je veux stocker toute la bière que je peux trouver ! Je ne veux pas que Jubjub s’enfuie à nouveau !\n\nVous avez de la bière Sombrefer ? Si c’est le cas, je vous l’échange l’un des œufs de ma grenouille Jubjub contre une chope.", description = nil, progress = "Je suis si content que Jubjub ait été retrouvée. Elle aime tellement la bière Sombrefer que lorsque je n’en ai plus… elle s’enfuit pour en chercher !\n\nMaintenant que Jubjub est revenue, je veux stocker toute la bière que je peux trouver ! Je ne veux pas que Jubjub s’enfuie à nouveau !\n\nVous avez de la bière Sombrefer ? Si c’est le cas, je vous l’échange l’un des œufs de ma grenouille Jubjub contre une chope.", completion = "Merci, &lt;nom&gt;.  Voici votre œuf ! Il n’est pas encore tout à fait prêt à éclore, mais quand il le fera, vous aurez un familier fantastique !", rewards = "Vous allez être la cible du sort suivant :\n\nRecharge de jubelin\n\nVous recevrez :\n\nOeuf de jubelin"},
[7961] = {title = "Waskily Wabbits!", objective = "Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us <nom>, you're our only hope.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPatte de lapinCaisse de lapin (patte-blanche)"},
[7962] = {title = "Peaux de lapins", objective = "Apportez 3 peaux de lapins LeCrafty à Jon LeCraft.", description = "Je veux des peaux de lapins LeCrafty. Allez m'en chercher.\n\nC'est très important !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMarque du fauve\n\nVous recevrez :\n\nHomard de 22 livres"},
[7981] = {title = "1200 bons - Amulette de la Sombrelune", objective = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", description = nil, progress = "Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !", completion = "Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !\n\nSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.", rewards = "Vous recevrez :\n\nAmulette de la Sombrelune"},
[8021] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8022] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8023] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8024] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8025] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8026] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nŒuf de murloc blanc"},
[8041] = {title = "La force du mont Mugamba", objective = "Salut, <classe>. je suis Jin’rokh le Briseur, un troll de Mugamba. La tribu de Zandalar reconnaît la valuer de vos exploits. Nous saluons votre ténacité la et la force de votre volonté.\n\nPortez ce talisman autour de votre cou, <classe>. Laissez la force du Mont Mugamba s’écouler dans votre être. Que sa force vous aider à frapper nos ennemis !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nForce de Mugamba"},
[8042] = {title = "La force du mont Mugamba", objective = "C’est bon de vous voir en bonne santé, <nom>. Les combats glorieux que vous avez menés affectent tous les êtres vivants de cette planète. Hakkar doit rester à jamais dans les confins de Zul’Gurub, sinon le monde succomberait sous les assauts de son insatiable faim.\n\nDonnez-moi votre talisman, et j’amplifierai sa force. Utilisez la Force de Mugamba pour punir nos ennemis !", description = nil, progress = "C’est bon de vous voir en bonne santé, <nom>. Les combats glorieux que vous avez menés affectent tous les êtres vivants de cette planète. Hakkar doit rester à jamais dans les confins de Zul’Gurub, sinon le monde succomberait sous les assauts de son insatiable faim.\n\nDonnez-moi votre talisman, et j’amplifierai sa force. Utilisez la Force de Mugamba pour punir nos ennemis !", completion = "Nos routes se croisent à nouveau, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nForce de Mugamba"},
[8043] = {title = "La force du mont Mugamba", objective = "Maître <nom>, vous êtes revenu ! Molthor a transmis au roi le récit de vos exploits. Votre nom est désormais connu jusqu’aux Mers du sud. Peut-être qu’un jour vous deviendrez un héros légendaire - et que votre histoire qui traversera les siècles.\n\nDonnez-moi votre talisman pour que je puisse une fois encore augmenter son pouvoir.", description = nil, progress = "Maître <nom>, vous êtes revenu ! Molthor a transmis au roi le récit de vos exploits. Votre nom est désormais connu jusqu’aux Mers du sud. Peut-être qu’un jour vous deviendrez un héros légendaire - et que votre histoire qui traversera les siècles.\n\nDonnez-moi votre talisman pour que je puisse une fois encore augmenter son pouvoir.", completion = "Utilisez votre force nouvelle pour détruire les Gurubashi !", rewards = "Vous recevrez :\n\nForce de Mugamba"},
[8044] = {title = "La rage de Mugamba", objective = "Le roi Rastakhan vous transmet ses meilleures salutations, maître <nom>. Un tel honneur n’a encore jamais été accordé à une personne n’appartenant pas à la tribu Zandalar.\n\n\n\nDonnez-moi votre talisman pour que je puisse l’améliorer une nouvelle fois. Sachez que la Rage de Mugamba est maintenant intrinsèquement liée à votre âme.", description = nil, progress = "Le roi Rastakhan vous transmet ses meilleures salutations, maître <nom>. Un tel honneur n’a encore jamais été accordé à une personne n’appartenant pas à la tribu Zandalar.\n\n\n\nDonnez-moi votre talisman pour que je puisse l’améliorer une nouvelle fois. Sachez que la Rage de Mugamba est maintenant intrinsèquement liée à votre âme.", completion = "Zul’jin envierait vos exploits, &lt;classe&gt;. Partez au combat, conquérant !", rewards = "Vous recevrez :\n\nRage de Mugamba"},
[8045] = {title = "La marque du païen", objective = "Sachez ceci, incroyant. Si une catastrophe nous a réunis, vos manières impies ne sont ni comprises ni appréciées de Zandalar. Mais nous sommes un peuple juste. Portez cette marque autour du cou. Elle servira à la fois d’avertissement à nos ennemis et de symbole de l’amitié de Zandalar.\n\nSi vous continuez à servir notre peuple, j’augmenterai la puissance de la marque.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque du païen"},
[8046] = {title = "La marque du païen", objective = "J’ai peut-être été trop hâtif dans mon jugement, <classe>. Il semblerait que votre foi aveugle dans cette Lumière ait un peu de mérite, après tout.\n\nDonnez-moi votre marque et j’amplifierai son pouvoir.", description = nil, progress = "J’ai peut-être été trop hâtif dans mon jugement, <classe>. Il semblerait que votre foi aveugle dans cette Lumière ait un peu de mérite, après tout.\n\nDonnez-moi votre marque et j’amplifierai son pouvoir.", completion = "Faites ce que vous avez à faire pour vaincre nos ennemis, &lt;classe&gt;. Même si vous devez pour cela utiliser la Lumière.", rewards = "Vous recevrez :\n\nMarque du païen"},
[8047] = {title = "La marque du païen", objective = "Je dois avouer que je ne croyais pas que vous auriez la détermination pour mener cette cause à bien, <classe>. Zandalar vous considère maintenant comme un allié de valeur. Bien joué,\n\nDonnez-moi votre marque et j’amplifierai une nouvelle fois  son pouvoir.", description = nil, progress = "Je dois avouer que je ne croyais pas que vous auriez la détermination pour mener cette cause à bien, <classe>. Zandalar vous considère maintenant comme un allié de valeur. Bien joué,\n\nDonnez-moi votre marque et j’amplifierai une nouvelle fois  son pouvoir.", completion = "Nos croyances diffèrent, mais notre cause est juste. Abattez nos ennemis, noble &lt;classe&gt;.", rewards = "Vous recevrez :\n\nMarque du païen"},
[8048] = {title = "La marque du héros", objective = "Le roi a reconnu votre existence, <classe>. Vous êtes le premier étranger à être accepté par Rastakhan comme un  véritable allié  de Zandalar.\n\nVous serez grandement récompensé  de vos efforts. Présentez votre marque et je lui apporterai l’amplification finale.", description = nil, progress = "Le roi a reconnu votre existence, <classe>. Vous êtes le premier étranger à être accepté par Rastakhan comme un  véritable allié  de Zandalar.\n\nVous serez grandement récompensé  de vos efforts. Présentez votre marque et je lui apporterai l’amplification finale.", completion = "Vigilance, honneur, loyauté, bravoure… Vous incarnez toutes ces qualités, tout comme le fera votre marque.", rewards = "Vous recevrez :\n\nMarque de héros"},
[8049] = {title = "L'œil de Zuldazar", objective = "Acceptez ce talisman en témoignage de notre gratitude, <classe>.\n\nL’Œil de Zuldazar grandira en pouvoir en même temps que grandira votre lien avec les trolls de Zandalar. Revenez me voir de temps en temps, pour que j’imprègne le joyau.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nL'Oeil de Zuldazar"},
[8050] = {title = "L'œil de Zuldazar", objective = "Bienvenue, <classe>. L’énergie pulse dans l’Œil de Zuldazar. Vous êtes prêt pour la prochaine étape. Confiez-moi le talisman et je réaliserai l’imprégnation.", description = nil, progress = "Bienvenue, <classe>. L’énergie pulse dans l’Œil de Zuldazar. Vous êtes prêt pour la prochaine étape. Confiez-moi le talisman et je réaliserai l’imprégnation.", completion = "Continuez votre combat contre l’Écorcheur et ses séides, &lt;nom&gt;. Il ne doit jamais quitter les confins de Zul’Gurub.", rewards = "Vous recevrez :\n\nL'Oeil de Zuldazar"},
[8051] = {title = "L'œil de Zuldazar", objective = "Les vents murmurent le récit de vos combats contre les Gurubashi, prêtresse . Même la cour royale commence à entendre parler de vos exploits. D’après la rumeur, le roi Rastakhan lui-même a mentionné votre nom.\n\nLe temps est venu d’imprégner l’Œil. Confiez-moi le talisman et je m’en occuperai.", description = nil, progress = "Les vents murmurent le récit de vos combats contre les Gurubashi, prêtresse . Même la cour royale commence à entendre parler de vos exploits. D’après la rumeur, le roi Rastakhan lui-même a mentionné votre nom.\n\nLe temps est venu d’imprégner l’Œil. Confiez-moi le talisman et je m’en occuperai.", completion = "Ne perdez jamais votre résolution, &lt;nom&gt;. Sinon l’Écorcheur d’âmes tentera d’aspirer votre volonté de vivre.", rewards = "Vous recevrez :\n\nL'Oeil de Zuldazar"},
[8052] = {title = "L'Oeil omnivoyant de Zuldazar", objective = "Si seulement nous avions dix mille personnes comme vous, <nom>. Les armées d’Hakkar seraient dispersées aux quatre vents en un clin d’œil.\n\n\n\nHélas, l’Œil est prêt à atteindre son plein potentiel.", description = nil, progress = "Si seulement nous avions dix mille personnes comme vous, <nom>. Les armées d’Hakkar seraient dispersées aux quatre vents en un clin d’œil.\n\n\n\nHélas, l’Œil est prêt à atteindre son plein potentiel.", completion = "Tuez-les tous et Hakkar reconnaîtra les siens…", rewards = "Vous recevrez :\n\nL'Oeil omnivoyant de Zuldazar"},
[8053] = {title = "Parangons de puissance : les garde-bras de libre-penseur", objective = "Ramenez des Manchettes primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nJin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Vous êtes <un incroyant/une incroyante>. Les incroyants ont une place au sein de la tribu. Les incroyants sont les libres-penseurs des Zandalar. Les libres-penseurs ne craignent pas l’oppression. Les libres-penseurs meurent pour leurs opinions. Nous savons que vous êtes <prêt/prête> à mourir pour vos opinions. Pour cela, nous vous saluons. Pour cela, nous vous donnons une chance de faire vos preuves.\n\nIl nous faut les Parangons de puissance. Allez à Zul’Gurub. Tuez les séides d’Hakkar. Revenez lorsque vous aurez ce que je recherche. Par vos actes, vous receverez la première pièce d’armure d’un libre-penseur zandalar.\n\nAllez.", progress = "Vous êtes de retour ? Avez-vous le Parangon de puissance ou êtes-vous en train de me faire perdre mon temps ?\n\nJ’espère que ce n’est pas le cas, incroyant.", completion = "Vous avez beaucoup fait pour nous honorer. Vos mains sont rouges du sang des séides d’Hakkar, et cela montre que vous êtes un ami de la tribu.\n\nPortez ces brassards. Ce sont des garde-bras de libre-penseur. Le vrai pouvoir est là.", rewards = "Vous recevrez :\n\nGarde-bras de libre-penseur zandalar"},
[8054] = {title = "Parangons de puissance : la ceinture de libre-penseur", objective = "Ramenez un Châle primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Vos croyances nous sont étrangères, <païen/païenne>. Autrefois, des Zandalar furent qualifiés d’hérétiques, au temps de la puissance de l’empire Gurubashi. Ces incroyants osèrent défier les prêtres d’Hakkar. Ils furent traqués et exterminés comme de la vermine. Mais ils n’ont jamais faibli, ni renoncé à se battre contre le Dieu sanglant. Nous honorons le prix qu’ils ont payé. Ils étaient les libres-penseurs.\n\nDétruisez les séides d’Hakkar à Zul’Gurub. Ramenez-moi le Parangon de puissance que je recherche. Votre succès sera généreusement récompensé.\n\nAllez.", progress = "Votre présence signifie-t-elle la victoire ? Avez-vous le Parangon ? Êtes-vous inondé du sang de vos ennemis ?", completion = "Votre honneur au sein de la tribu est assuré. Vous avez beaucoup tué à Zul’Gurub. Les ennemis succombent face à vos convictions. Les ennemis succombent devant votre puissance.\n\nVoici la ceinture de libre-penseur. C’est une marque d’honneur. C’est un mojo puissant. Elle est à vous.", rewards = "Vous recevrez :\n\nCeinture de libre-penseur zandalar"},
[8055] = {title = "Parangons de puissance : la cuirasse de libre-penseur", objective = "Ramenez un Tabard primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nJin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les armes et les armures donnent du pouvoir au sein de la tribu. Les libres-penseurs sont honorés pour cela. Ce sont des zélotes. Ils imprègnent leurs cuirasses d’un mojo puissant. Si leur foi leur manque face à l’ennemi, leur cuirasse leur reste.\n\nVous devez être <révéré/révérée> parmi nous pour posséder une telle cuirasse. Allez à Zul’Gurub. Prenez le Parangon de puissance dont j’ai besoin, sans oublier de faire souffrir son imbécile de propriétaire. Ramenez-le-moi. Prouvez votre valeur comme libre-penseur, une fois pour toutes.", progress = "Avez-vous le Parangon ? Il contient du mojo. Il nous le faut. Vous nous aiderez.", completion = "Bien peu de gens ont accompli ce que vous avez réussi. Vous avez mis les séides d’Hakkar à genoux. Vous leur avez montré ce que pouvait faire un libre-penseur. Vous nous avez montré qu’un hérétique pouvait être révéré dans la tribu. La puissance n’est pas vôtre, vous ÊTES la puissance.\n\nPrenez cette cuirasse, libre-penseur. Écrasez vos adversaires.", rewards = "Vous recevrez :\n\nCuirasse de libre-penseur zandalar"},
[8056] = {title = "Parangons de puissance : les brassards d'augure", objective = "Ramenez des Brachiales primordiales hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les augures de notre tribu sont révérés pour leur don de seconde vue. Ce ne sont pas des sorciers-docteurs qui passent leur temps à lancer des os ou à lire des feuilles pour comprendre le monde – et ils ne lancent pas de maléfices à tort et à travers, eux. Vous êtes chaman, vous connaissez déjà une partie des pouvoirs de l’augure. Nous autres Zandalar, nous attachons un grand prix à la sagesse que les augures apportent à la tribu.\n\nFaites-moi offrande d'un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai des brassards que nos augures apprécient par-dessus tout !", progress = "Avez-vous le Parangon de puissance de Zul’Gurub dont j’ai besoin ? Ces brassards méritent que vous vous donniez un peu mal, vous savez !", completion = "On dirait bien que vous avez un petit quelque chose d’un augure zandalar. Nous savons tout ce que vous avez accompli à Zul’Gurub en notre nom. Ce Parangon de puissance fera beaucoup pour la tribu Zandalar, une tribu qui compte désormais parmi vos amis. Prenez ces brassards, &lt;nom&gt;, vous les avez bien mérités !", rewards = "Vous recevrez :\n\nBrassards d'augure zandalar"},
[8057] = {title = "Parangons de puissance : les brassards d'haruspice", objective = "Ramenez un Etançon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "L’haruspice est un membre très important de notre tribu, vous avez tout intérêt à écouter ses divinations. Par sa communion avec les animaux, et en les sacrifiant aux esprits lorsque c'est nécessaire, il nous fait profiter des conseils des dieux. Au temps jadis, la sagesse des haruspices nous a donné l’avantage dans la lutte sauvage que nous avons dû soutenir contre les tribus divisées des Gurubashi.\n\nPour prouver votre valeur à nos yeux, amenez-moi en offrande un Parangon de puissance qui se trouve dans Zul’Gurub. Si vous y parvenez, je vous donnerai des brassards qui feraient l’envie d’un haruspice des Zandalar.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrassards d'haruspice zandalar"},
[8058] = {title = "Parangons de puissance : les garde-bras de redresseur de torts", objective = "Ramenez des Brachiales primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nJin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "La vengeance est une force. Les redresseurs de torts zandalar utilisent cette force. La tribu a beaucoup d’ennemis. Le redresseur de torts les châtie. Aucun crime commis contre nous ne reste impuni, car ils veillent au châtiment. Nos ennemis craignent notre vengeance. Ils ont raison. Ils la craindront à jamais.\n\nDevenez l’un de nos redresseurs de torts. Cherchez un Parangon de puissance à l’intérieur de Zul’Gurub. Tuez les séides d’Hakkar et exercez la vengeance au nom de la tribu. Vous serez <récompensé/récompensée>.", progress = "Avez-vous ramené le Parangon de puissance ? Avez-vous exercé la vengeance au nom des Zandalar ?", completion = "Vous avez accompli une belle et bonne vengeance aujourd’hui. Vous avez pris le visage du redresseur de torts. Vous avez mis à genoux les séides du Dieu sanglant.\n\nPrenez ceci. Désormais, ils alimenteront votre vengeance. Vous êtes un ami des Zandalar, à présent.", rewards = "Vous recevrez :\n\nGarde-bras de redresseur de torts zandalar"},
[8059] = {title = "Parangons de puissance : les couvre-bras de démoniaque", objective = "Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Lorsqu’ils négocient avec les démons, les démonistes s’aventurent sur un terrain dangereux, mais nos démoniaques poussent le processus encore plus loin. Grâce à un ancien rituel des arcanes, ils permettent à un démon d’entrer dans leurs corps. Mais ils ne sont pas posssédés : ils réduisent le démon en esclave de l’intérieur, absorbant le pouvoir de la bête pour leurs propres fins. C’est un exploit que bien peu sont capables d’accomplir.\n\nSi vous voulez apprendre le pouvoir des démoniaques, il me faut un Parangon de puissance de Zul’Gurub. Allez-y, et ramenez-moi ce que je cherche.", progress = "Revenez-vous avec le Parangon de puissance ? En triomphant des séides diaboliques d’Hakkar, vous ferez vos preuves à nos yeux et vous montrerez votre volonté d’apprendre les voies des démoniaques.", completion = "Bien… J’espère qu’ils ont énormément souffert avant de renoncer au Parangon de puissance. Prenez ceci, les couvre-bras de démoniaque. Ils sont formés du puissant mojo qui a servi à invoquer la proie du démoniaque, et ce sera un outil précieux dans votre course à la puissance.", rewards = "Vous recevrez :\n\nCouvre-bras de démoniaque zandalar"},
[8060] = {title = "Parangons de puissance : les couvre-bras d’illusionniste", objective = "Ramenez des Manchettes primordiales hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Dans notre tribu, les mages sont appelés “illusionnistes”. Leurs incantations emploient des mojos puissants, semant la confusion et le trouble parmi les ennemis de la tribu.\n\n<Al'tabim éclate d’un rire mauvais.>\n\nQuel beau spectacle que celui d’un illusionniste au travail, mettant ses ennemis à genoux en les engloutissant sous leur propre folie !\n\nPour apprendre la voie de l’illusionniste, rendez-vous à Zul’Gurub et ramenez-moi un Parangon de puissance. Si vous y parvenez, je vous donnerai les couvre-bras dont nos illusionnistes se servent pour tisser leurs sorts.", progress = "<nom>, vous êtes déjà de retour ? Avez-vous récupéré le Parangon de puissance dont j’ai besoin ?", completion = "Impressionnant… vous sentez le mojo qu’il renferme ? À l’époque où les Gurubashi gouvernaient ces terres, les Parangons de puissance servaient plus ou moins de monnaie. Nous, les Zandalar, nous emploierons leur mojo latent pour empêcher le second règne d’Hakkar.\n\nVous avez bien agi aujourd’hui. Désormais, les Zandalar sont vos amis. Et pour sceller cette amitié, prenez les couvre-bras d’illusionniste promis !", rewards = "Vous recevrez :\n\nCouvre-bras d'illusionniste zandalar"},
[8061] = {title = "Parangons de puissance : les couvre-bras de confesseur", objective = "Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Nous autres Zandalar donnons du pouvoir à ceux dont la voix résonne de l’autorité des dieux. Nos prêtres ne sont pas seulement des guérisseurs, ce sont aussi des confesseurs. Le mal rôde à l’extérieur, comme le montre la menace d’Hakkar, mais il vient aussi de l’intérieur. Nos confesseurs sont nos juges, chargés de nous préserver du mal qui a dévoré les Gurubashi de l’intérieur.\n\nRendez-vous à Zul’Gurub et ramenez-en un Parangon de puissance des Gurubashi. Apprenez ce que cela signifie d’être le confesseur, et protégez-nous du mal.", progress = "De retour de Zul’Gurub, pas vrai ? Avez-vous repris le Parangon de puissance aux séides d’Hakkar ?", completion = "Excellent, &lt;nom&gt; ! Me le ramener était un exploit en soi. Je ne doute pas que vous ayez agi comme le confesseur de la tribu aujourd’hui, en nous préservant de la menace d’Hakkar. Ces couvre-bras iront à merveille à l’ami de la tribu que vous êtes devenu !", rewards = "Vous recevrez :\n\nCouvre-bras de confesseur zandalar"},
[8062] = {title = "Parangons de puissance : les brassards de prédateur", objective = "Ramenez des Manchettes primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Dans les jours sombres qui ont suivi la chute de l’empire Gurubashi, les prédateurs zandalar ont utilisé leurs pouvoirs pour nourrir la tribu. Les chasseurs prétendent qu’ils ressemblent à nos prédateurs – et il est vrai que la chasse est ce qui définit l’essence des prédateurs. Votre chasse dans Zul’Gurub nous montrera si vous figurez vraiment parmi les plus grands prédateurs.\n\nRamenez-moi un Parangon de puissance de Zul’Gurub. Si vous y parvenez, vous ferez vos premiers pas sur la route qui fera de vous un redoutable prédateur.", progress = "Traquez les habitants de Zul’Gurub qui possèdent des Parangons de puissance, <nom>. Ils sont votre proie. Ils possèdent quelque chose dont nous avons tous les deux besoin.", completion = "Oui… Je n’ai pas besoin d’yeux pour sentir la présence d'un Parangon de puissance. Vos succès à Zul’Gurub ont impressionné bien des membres de la tribu. Non seulement nous vous considérons comme un ami des Zandalar, mais nous vous jugeons digne de porter les brassards de prédateur. Ce sont des objets puissants et le symbole de la fonction de prédateur. Bon travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBrassards de prédateur zandalar"},
[8063] = {title = "Parangons de puissance : les brassards d'insensé", objective = "Ramenez des Brachiales primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Nos insensés ressemblent aux voleurs, mais avant toutes choses, ils savourent la folie… le chaos… l’imprévisibilité de l’existence. Sur le champ de bataille, ils sont terrifiants. Aux temps sauvages, lorsque les tribus se sont divisées, ils ont semé les graines de la confusion et de la démence parmi nos ennemis. Sans eux, nous ne serions pas là aujourd’hui.\n\nRamenez-moi le Parangon de puissance de Zul’Gurub que je recherche, et je vous remettrai la première pièce d’une précieuse armure d’insensé. Plongez dans la folie !", progress = "Cherchez la folie à l’intérieur de Zul’Gurub et noyez-la sous la vôtre, <nom> ! Si vous y arrivez, vous réussirez, et la réussite entraîne une récompense ! Empêchez le Dieu sanglant de triompher à nouveau !", completion = "Bien joué, &lt;nom&gt;… grâce à vos exploits à Zul’Gurub, vous avez gagné le droit de considérer les Zandalar comme des amis. Je veillerai à ce que le Parangon soit bien utilisé. Quant à vous, acceptez cette récompense !", rewards = "Vous recevrez :\n\nBrassards d'insensé zandalar"},
[8064] = {title = "Parangons de puissance : la ceinture d'haruspice", objective = "Ramenez une Echarpe primordiale hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Honorer (au minimum).", description = "Nous autres Zandalar, nous ignorons les voies des druides. La nature doit se plier à nos besoins, pas le contraire. Malgré tout, l’haruspice est sans doute celui de nous qui est le plus proche des voies de la nature, et pour d’excellentes raisons. Offrir le fantôme d'une bête, c'est aussi se mettre dans sa peau... Tel est le pouvoir de la nature.\n\nPour prouver votre valeur à nos yeux, amenez-moi en offrande un Parangon de puissance de Zul’Gurub. Si vous y parvenez, je vous donnerai un objet de grand pouvoir, une ceinture comme celles que portent beaucoup de nos haruspices. Beaucoup de mojo, oh oui !", progress = "Avez-vous le Parangon de puissance de Zul’Gurub dont j’ai besoin ? Si vous l'avez, je vous donnerai la ceinture de l’haruspice.", completion = "Merci bien. L’énergie latente contenue dans cet objet suffit à en faire un trésor. Non seulement vous avez rempli votre part du marché, mais vous avez prouvé que vous étiez honorable à nos yeux. Comme promis, voici votre récompense !", rewards = "Vous recevrez :\n\nCeinture d'haruspice zandalar"},
[8065] = {title = "Parangons de puissance : la tunique d'haruspice", objective = "Ramenez un Tabard primordial hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Révérer (au minimum).", description = "L’ultime symbole de la puissance d’un haruspice réside dans sa vêture, <nom>. Sa tunique symbolise le lien entre sa personne et la sagesse divine qu’il recherche. Il y ajoute souvent des morceaux d’animaux qu’il a sacrifié, en souvenir du lien qu’il a entretenu avec leurs dons.\n\nPour prouver votre valeur à nos yeux, amenez-moi en offrande un Parangon de puissance qui se trouve dans Zul’Gurub. Si vous y parvenez, une tunique forte de la véritable puissance des haruspices sera vôtre.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique d'haruspice zandalar"},
[8066] = {title = "Parangons de puissance : la ceinture de prédateur", objective = "Ramenez un Châle primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Un prédateur sait traquer ses proies, mais un prédateur avisé sait aussi comment les frapper alors même qu’elles sont rassemblées. Vous devez maîtriser ces deux arts si vous voulez réussir à Zul’Gurub… et si vous voulez ressembler aux prédateurs des Zandalar.\n\nRamenez-moi un Parangon de puissance de Zul’Gurub. Ma récompense sera la puissance contenue dans cet objet, et la vôtre sera une ceinture de prédateur zandalar. Croyez-moi, c’est un marché équitable.", progress = "Frappez les séides déments d’Hakkar à Zul’Gurub, <nom>. Ce sont eux qui ont les Parangons de puissance. Montrez-leur – montrez-nous – que vous ferez un excellent prédateur.", completion = "J’ai senti votre arrivée il y a un moment, &lt;nom&gt;, mais cela n’a pas été facile. Vous avez été trahi par le Parangon de puissance que vous portez. Je peux sentir son pouvoir sans avoir besoin de le voir. Son mojo latent – sa magie brute, si vous préférez – alimentera nos efforts pour déjouer les plans démoniaque du Dieu sanglant, Hakkar.\n\nVous méritez d’être reconnu et récompensé pour vos efforts. Vous serez honoré au sein de la tribu, et vous êtes digne de porter la ceinture du prédateur.", rewards = "Vous recevrez :\n\nCeinture de prédateur zandalar"},
[8067] = {title = "Parangons de puissance : le mantelet de prédateur", objective = "Ramenez une Egide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Chez les Zandalar, les tenues sont le symbole des succès remportés. Malgré cela, vous n’avez pas besoin de voir ce que porte une personne pour sentir le pouvoir qui émane d’elle – le pouvoir transcende la vision. Les vêtements de nos prédateurs sont ainsi, et le plus apprécié est leur mantelet. Il aide à les dissimuler… et à les rendre visibles lorsqu’ils le souhaitent.\n\nLes Parangons de puissance attendent d’être sauvés de Zul’Gurub. Ramenez-moi ce que je cherche, et le mantelet de prédateur sera vôtre.", progress = "Vos opérations dans Zul’Gurub ont-elles été couronnées de succès, <nom> ? Ce n’est que lorsque vous m’aurez apporté ce que je cherche – et que vous aurez fait vos preuves aux yeux de la tribu – que vous receverez un mantelet sans équivalent parmi les Zandalar.", completion = "Le succès… vous serez révéré au sein de la tribu, &lt;nom&gt;. Acquérir le Parangon de puissance nécessaire pour obtenir le mantelet n’est pas un mince exploit, mais vous vous en êtes sorti avec l’élégance des plus meurtriers de nos prédateurs. Vous avez mérité votre place parmi nous, et vous avez certainement gagné le droit de porter ce mantelet.", rewards = "Vous recevrez :\n\nMantelet de prédateur zandalar"},
[8068] = {title = "Parangons de puissance : le mantelet d’illusionniste", objective = "Ramenez un Châle primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "La magie est une force brute, primitive, que seuls les plus forts peuvent modeler. Le mojo est une extension de notre pouvoir, et l’un de ses emplois les plus puissants est l’illusion. Comment peut-on espérer vaincre un ennemi qui n’est pas réellement là ? Nous, les Zandalar, nous apprécions ce pouvoir, et les illlusionnistes ont une place d’honneur au sein de la tribu.\n\nPrenez le Parangon de puissance dont nous avons besoin à Zul’Gurub. Si vous y parvenez, vous serez <honoré/honorée> par la tribu, et nous vous remettrons un mantelet puissant, utilisé par nos meilleurs illusionnistes !", progress = "Comment s’est passée votre expédition à Zul’Gurub ? Avez-vous rendu fous vos ennemis grâce à la puissance de l’illusion ? Illusion ou pas, leur mort – et la confiscation de leurs Parangons de puissance – nous aidera à contrecarrer l’ascension d’Hakkar.", completion = "Un succès ! Désormais, la tribu vous honorera, &lt;nom&gt;. Aujourd’hui, Zul’Gurub a goûté à la puissance des Zandalar, grâce à vous.\n\nPrenez ce mantelet d’illusionniste zandalar, avec la bénédiction de la tribu. Puisse-t-il bien vous servir !", rewards = "Vous recevrez :\n\nMantelet d'illusionniste zandalar"},
[8069] = {title = "Parangons de puissance : la robe d’illusionniste", objective = "Ramenez une Casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Notre puissance et notre rang au sein de la tribu sont indiqués par ce que nous portons. Nos tenues sont faites à partir des matériaux les plus fins, et imprégnés du mojo dont nous nous servons pour devenir puissants. Les illusionnistes ne font pas exception. À ce que l’on dit, leurs robes matérialisent l’essence de l’illusion. D’après les légendes, les robes les plus anciennes n’ont jamais deux fois la même apparence.\n\nJe vous donnerai une robe d’illusionniste, <nom>… mais vous devez d’abord mériter que la tribu vous révère ! Ramenez-moi un Parangon de puissance de Zul’Gurub !", progress = "Apportez-vous le Parangon de puissance dont nous avons besoin ? Je sais que ce ne sera pas facile… Mais il y a bien longtemps, j’ai prophétisé qu’un étranger viendrait nous aider dans notre combat contre Hakkar. Faites en sorte que ce soit vous !", completion = "Enfin, quelqu'un digne de porter la robe d'illusionniste ! Votre succès à Zul'Gurub vous assure d'être révéré par la tribu pendant des siècles et des siècles.  Portez-la avec fierté, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nRobe d'illusionniste zandalar"},
[8070] = {title = "Parangons de puissance : le cordon de confesseur", objective = "Ramenez une Echarpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Peu après la chute des Gurubashi, nous autres Zandalar avons failli succomber, dévorés de l’intérieur par le mal. L’ascension des confesseurs date de ce temps-là. Ils ont préservé la tribu en chassant ceux qui étaient prêts à détruire leurs propres frères. Non seulement ils préservent notre lien avec les esprits, mais ils sauvent notre chair.\n\nAllez à Zul’Gurub. Soyez témoin de la dépravation d’Hakkar et des Gurubashi. Arrachez-leur le Parangon de puissance dont nous avons besoin. Comme de juste, vous serez <récompensé/récompensée>.", progress = "Le Parangon de puissance… l'avez-vous ? Lorsque vous nous l'aurez ramené, nous pourrons nous servir de la puissance latente qu’il contient. Il sera doux de faire enfin payer les sbires du Dieu sanglant…", completion = "Un succès ! Il jouera un grand rôle dans la reconstruction de notre puissance face aux menées d’Hakkar. Avec votre aide, nous avons fait un pas supplémentaire, un pas qui nous évitera peut-être d’être détruits par le Dieu sanglant.\n\nEn ce jour, la tribu vous honore, &lt;nom&gt;. Prenez ce cordon de confesseur comme symbole de notre gratitude.", rewards = "Vous recevrez :\n\nCordon de confesseur zandalar"},
[8071] = {title = "Parangons de puissance : le mantelet de confesseur", objective = "Ramenez une Egide primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les confesseurs des Zandalar portent tous un mantelet caractéristique, qui indique qu’ils préservent la tribu. Ils sont tissés de puissant mojo qui les aide à juger ceux qui risquent de la menacer. En tant que prêtre, vous devez aussi consacrer du temps à séparer les dignes des indignes. Un tel mantelet vous serait certainement utile.\n\nSi vous combattez les séides d’Hakkar à Zul’Gurub et que vous me ramenez le Parangon de puissance dont j’ai besoin, je vous remettrai un mantelet digne de nos meilleurs confesseurs.", progress = "Avez-vous le Parangon de puissance de Zul’Gurub ?", completion = "Bien joué, &lt;nom&gt;. Aujourd’hui, grâce à vous, les sbires d’Hakkar ont senti la vengeance des Zandalar. Vos actions vous assurent une place bien particulière au sein de la tribu. Nous vous révérerons désormais. Prenez ce mantelet de confesseur, il est à vous.", rewards = "Vous recevrez :\n\nMantelet de confesseur zandalar"},
[8072] = {title = "Parangons de puissance : le mantelet d'insensé", objective = "Ramenez un Ceinturon primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Khar’vaxal le Fêlé fut l’un des insensés les plus fameux qu’aient comptés les Zandalar. D’après la légende, lorsqu’il a affronté les ennemis de la tribu pour la première fois, Khar'vaxal s’est servi d’un mantelet tissé dans « l’étoffe de la folie ». Celui-ci dissimulait sa forme, mais aussi l’éclat de ses dagues jumelles. Les insensés d’aujourd’hui chérissent leurs mantelets comme signe de leur place dans la tribu.\n\nRamenez-moi le Parangon de puissance que je recherche, et vous aurez l’un de ces mantelets. Ainsi, vous pourrez tisser la démence de vos ennemis.", progress = "Vous êtes de retour. Avez-vous le Parangon de puissance dont j’ai besoin ?\n\nLa légende de Khar'vaxal le Fêlé nous rappelle qu’aucun ennemi, si puissant soit-il, n’est invincible. Le chaos finit par mettre tout le monde à genoux, c’est une certitude… et peut-être est-ce aussi le cas des éléments les moins chaotiques du chaos.", completion = "La victoire est à nous, grâce à la folie que vous avez semée parmi nos ennemis mutuels ! Vous serez honoré parmi les Zandalar, et il n’existe pas de meilleur moyen de vous montrer notre gratitude que de vous offrir le mantelet de l’insensé !", rewards = "Vous recevrez :\n\nMantelet d'insensé zandalar"},
[8073] = {title = "Parangons de puissance : la tunique d'insensé", objective = "Ramenez une Egide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Mes yeux m’ont abandonné il y a bien longtemps, mais je ne les regrette pas. Même dans une tribu comme la nôtre, où les vêtements symbolisent le rang et la vocation, les tenues les plus puissantes irradient un pouvoir que l’œil nu ne peut pas voir. La précieuse tunique des insensés zandalar ne fait pas exception, car il en émane la puissance brute du chaos et de la démence qu’ils sont capables de contrôler.\n\nLe Parangon de puissance dont j’ai besoin se trouve à Zul’Gurub. Ramenez-le-moi, et je vous donnerai l’une de ces tuniques légendaires, dignes d’un artisan de la folie.", progress = "Bon retour sur l’île, <nom>… revenez-vous triomphante avec le Parangon de puissance ?", completion = "Impressionnant… ce que vous avez accompli aujourd’hui, peu de gens le croyaient possible. Votre vie durant, vous serez révérée au sein de la tribu, &lt;nom&gt;. Vous avez conquis de haute lutte le droit de porter la tunique de l’insensé, avec notre bénédiction.", rewards = "Vous recevrez :\n\nTunique d'insensé zandalar"},
[8074] = {title = "Parangons de puissance : la ceinture d'augure", objective = "Ramenez un Ceinturon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les augures connaissent le mojo des éléments. Ils s’en servent pour guider la tribu vers la gloire. Dans les jours sombres qui ont suivi l’éclatement de l’empire Gurubashi, nos augures nous ont conduits à l’abri dans les mers du Sud. Et puis ils nous ont ramenés ici, dans la vallée, tout près du mal qui grandit au cœur de Zul’Gurub.\n\nFaites-moi offrande d'un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai une ceinture d’augure contenant un puissant mojo !", progress = "Il me faut le Parangon de puissance. Nous le viderons de leur pouvoir et nous nous en servirons pour combattre le mal qui vient de Zul’Gurub. Alors, vous l'avez ?", completion = "Je sens sur votre peau l’odeur d’un mal défait, &lt;nom&gt;. Douce odeur… et je pense que vous la connaissez bien.\n\nJe sais à quel point il était difficile d’obtenir le Parangon de puissance nécessaire pour la ceinture. Par vos actions, vous avez honoré la tribu, et vous vous êtes honoré vous-même. Prenez la ceinture d’augure et portez-la, vous en êtes digne !", rewards = "Vous recevrez :\n\nCeinture d'augure zandalar"},
[8075] = {title = "Parangons de puissance : le haubert d'augure", objective = "Ramenez un Tabard primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Tous les augures des Zandalar portent une pièce d’amure caractéristique, un haubert. Il est orné des plus belles soieries imaginables, mais il est fait de solides chaînes. C’est un symbole de leur contact avec le divin… et de leur autorité. Il n’est jamais sage de contrarier ceux qui ont voué leur vie au contact avec les esprits…\n\nRamenez-moi en offrande un Parangon de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai l’un de nos plus beaux hauberts, digne des plus grands augures !", progress = "Les Parangons de puissance sont une source capitale de pouvoir magique, le même genre de pouvoir qui permet de fabriquer le haubert d’augure. Ramenez-moi ce dont j’ai besoin, et je pourrai vous remettre un vêtement que tout augure de Zandalar serait fier de posséder.", completion = "Je sais ce que vous avez dû traverser pour me ramener ce Parangon de puissance, &lt;nom&gt;. Vaincre le mal qui suinte de Zul’Gurub comme le pus d’une blessure infectée n’a pas été facile, mais maintenant que tout est fait et dit, vous serez révéré parmi les Zandalar pendant des siècles et des siècles !\n\nPrenez ce haubert d’augure, et portez-le avec fierté !", rewards = "Vous recevrez :\n\nHaubert d'augure zandalar"},
[8076] = {title = "Parangons de puissance : le mantelet de démoniaque", objective = "Ramenez une Echarpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le démoniaque cherche à incarner la puissance, et pas seulement à la posséder. Nombre d’entre eux finissent par être vaincus par un démon. Menacés comme nous le sommes par nos ennemis – surtout à Zul’Gurub – la puissance qu’un démoniaque est capable de déchaîner compense largement leur sacrifice. Si nous voulons survivre, nous devons écraser ceux qui veulent nous détruire. C’est la grande leçon que nous a apprise la chute de l’empire des Gurubashi.\n\nRendez-vous à Zul’Gurub et récupérez le Parangon de puissance qu’il nous faut. Si vous y parvenez, nous vous donnerons un outil de grande valeur appartenant à un démoniaque.", progress = "Avez-vous récupéré le Parangon de puissance de Zul’Gurub ? Nous prendrons la force latente de ces objets et nous la ferons nôtre. Quant à vous, si vous réussissez, vous aurez votre propre don de puissance…", completion = "Beau travail, &lt;nom&gt;. Les Parangons de puissance de Zul’Gurub sont un témoignage d’un tel gâchis… À leur apogée, les Gurubashi étaient forts, mais ils ont laissé leur force les dévorer. Le démoniaque joue une partie similaire, mais la puissance qu’il libère est souvent indispensable à sa survie.\n\nPortez ce mantelet, allié honoré des Zandalar… Il vous servira bien.", rewards = "Vous recevrez :\n\nMantelet de démoniaque zandalar"},
[8077] = {title = "Parangons de puissance : la robe de démoniaque", objective = "Ramenez une Casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le principal symbole du pouvoir au sein de la tribu reste la tenue que nous portons au combat. Les robes d’un démoniaque entremêlent de l’étoffe runique et un mojo d’une puissance dévastatrice. Le visage qui les orne est censé instiller la peur dans l’esprit de ceux qui les contemplent… et surtout des démons que le démoniaque doit mater.\n\nVous devez me ramener un Parangon de puissance très particulier de Zul’Gurub. Ce sera difficile… mais si vous réussissez, vous aurez l’une de ces robes.", progress = "Le Parangon de puissance… êtres-vous revenu avec lui ? Nous ne vous donnerons l’ultime symbole de la puissance des démoniaques que lorsque vous nous l'aurez livré, <nom>.", completion = "Impressionnant. Votre victoire à Zul’Gurub nous montre – non, montre au monde entier – qu’Hakkar ne triomphera pas. Le temps viendra sans doute pour vous d’affronter directement le Dieu sanglant. Sachez qu’en prévision de ce jour, la tribu Zandalar vous révère déjà.\n\nOh, et puis, cette robe toute simple pourrait bien vous aider.\n\n&lt;Al’tabim vous fait un clin d’œil complice.&gt;", rewards = "Vous recevrez :\n\nRobe de démoniaque zandalar"},
[8078] = {title = "Parangons de puissance : la ceinture de redresseur de torts", objective = "Ramenez un Ceinturon primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "L’ultime vengeance attend à l’intérieur de Zul’Gurub. Hakkar ne doit pas revenir. Hakkar a détruit l’empire Gurubashi de l’intérieur. Aucun sacrifice n’était suffisant. Les trolls ne sont plus que l’ombre de leur ancienne gloire. Je sais que c’est la faute d’Hakkar.\n\nVotre destin est de redresser les torts. Accomplissez-le. Détruisez les séides des ténèbres. Zul’Gurub doit goûter à la vengeance des Zandalar. Ramenez-moi une preuve de vos actions, un Parangon de puissance. En échange, vous recevrez la ceinture de redresseur de torts. Vous receverez la vraie puissance.\n\nAllez.", progress = "Avez-vous le Parangon de puissance ? Avez-vous terrassé les ennemis de la tribu ? Hakkar doit connaître la colère du redresseur de torts !", completion = "Désormais, vous connaissez la voie du redresseur de torts. Vous avez honoré la tribu. Vous vous êtes honoré vous-même. Vous avez fait souffrir nos ennemis.\n\nLa ceinture de redresseur de torts est à vous. Bientôt, vous ne ferez plus qu’un avec la voie de la vengeance.", rewards = "Vous recevrez :\n\nCeinture de redresseur de torts zandalar"},
[8079] = {title = "Parangons de puissance : la cuirasse de redresseur de torts", objective = "Ramenez une Casaque primordiale hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le symbole de la puissance du redresseur de torts est sa cuirasse, forgée d’un puissant mojo. Elle n’est remise qu’à ceux que nous révérons. C’est le symbole de la vengeance des Zandalar.\n\nDevenir un redresseur de torts, c’est ne plus faire qu’un avec la vengeance. Prenez le Parangon de puissance dont nous avons besoin à Zul’Gurub. Ramenez-le-nous. Nous reprendrons le mojo qui nous a été dérobé. Nous ferons payer les séides d’Hakkar. Et nous vous récompenserons avec la cuirasse de redresseur de torts.\n\nAllez. Soyez notre vengeance, <nom>.", progress = "Votre présence signifie-t-elle la victoire ? Avez-vous le Parangon de puissance ? Parlez-moi de la justice que vous avez rendue en ce jour !", completion = "Vous serez révéré pour vos exploits. La tribu récompense ses héros. Zul’Gurub a goûté à la vengeance des Zandalar comme jamais auparavant.\n\nVos actions montrent la voie. D’autres viendront. Ils vous verront, vous, l’incarnation de la vengeance, comme le signe d’un véritable pouvoir !", rewards = "Vous recevrez :\n\nCuirasse de redresseur de torts zandalar"},
[8080] = {title = "Les ressources du bassin d'Arathi", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière.", description = "Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !\n\nC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !\n\nVoici ce que je veux que vous fassiez, <nom>. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8081] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8101] = {title = "Le caillou de Kajaro", objective = "<nom>, le caillou enchâssé dans la monture de ce talisman provient du mont Kajaro, dans les Mers du sud. Le mont Kajaro souffre d’une grande instabilité, car il est secoué par des éruptions volcaniques fréquentes, et souvent magiques.\n\nQuand votre lien avec les trolls de Zandalar grandira, la puissance de ce caillou fera de même. Utilisez son pouvoir pour frapper nos ennemis. Soyez comme la montagne : vif, explosif, mortel…", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCaillou de Kajaro"},
[8102] = {title = "Le caillou de Kajaro", objective = "Bienvenue de nouveau, <classe>. Je vois que le caillou a beaucoup servi. Un grand nombre de nos ennemis a succombé devant vos capacités surnaturelles. Leurs souffrances ont été grandes. Il est temps que j’augmente la puissance du caillou. Donnez-le-moi.", description = nil, progress = "Bienvenue de nouveau, <classe>. Je vois que le caillou a beaucoup servi. Un grand nombre de nos ennemis a succombé devant vos capacités surnaturelles. Leurs souffrances ont été grandes. Il est temps que j’augmente la puissance du caillou. Donnez-le-moi.", completion = "Soyez inéluctable, comme les fleuves de lave du Kajaro.", rewards = "Vous recevrez :\n\nCaillou de Kajaro"},
[8103] = {title = "Le caillou de Kajaro", objective = "Les Hakkari vous craignent, <nom>. Ils parlent d’horreurs qu’ils croyaient n’être l’apanage que de leur dieu sans visage. Vous les avez brûlés grâce à la force de Kajaro. Ils connaissent maintenant la peur en deux endroits.\n\nIl est temps maintenant de renforcer le caillou. Donnez-moi le talisman.", description = nil, progress = "Les Hakkari vous craignent, <nom>. Ils parlent d’horreurs qu’ils croyaient n’être l’apanage que de leur dieu sans visage. Vous les avez brûlés grâce à la force de Kajaro. Ils connaissent maintenant la peur en deux endroits.\n\nIl est temps maintenant de renforcer le caillou. Donnez-moi le talisman.", completion = "Continuez le massacre des trolls de Zul’Gurub. Hakkar doit comprendre que le monde ne se soumettra pas à sa volonté indomptable.", rewards = "Vous recevrez :\n\nCaillou de Kajaro"},
[8104] = {title = "Le joyau de Kajaro", objective = "Donnez-moi le talisman, <nom>. Je dois vous montrer quelque chose.", description = nil, progress = "Donnez-moi le talisman, <nom>. Je dois vous montrer quelque chose.", completion = "&lt;Al’tabim brise le caillou grâce à une force puissante et invisible.&gt;\n\nVous voyez ? Ce caillou est en fait une géode. Des cristaux puissants se cachent à l’intérieur, des cristaux qui absorbent peu à peu les énergies latentes de notre monde. En le brisant en deux, j’ai enfin permis à son plein potentiel de se réaliser. Utilisez-le pour détruire nos ennemis.", rewards = "Vous recevrez :\n\nJoyau de Kajaro"},
[8105] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, <nom>. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.\n\nAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !\n\nQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8106] = {title = "La souillure de Kezan", objective = "Acceptez ce talisman, <classe>. Acceptez-le et utilisez son pouvoir pour abattre nos ennemis communs.\n\nSachez que vous portez autour du cou un morceau d’histoire. Kezan était autrefois un immense territoire de l’empire Zandalar. Hélas, la souillure des princes marchands gobelins a fini par chasser mes fiers frères et sœurs de cette région.\n\nKezan est maintenant le site de la capitale gobeline d’Undermine ; mais sachez qu’avant d’être souillée, elle abritait la grandeur. Même aujourd’hui, Kezan est considérée comme une terre sacrée par mon peuple.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSouillure de Kezan"},
[8107] = {title = "La souillure de Kezan", objective = "L’honneur se mérite chez les trolls de Zandalar, <nom>. Avec l’honneur viennent les récompenses : l’amitié, les alliances… \n\nDonnez-moi le talisman pour que je puisse renforcer son pouvoir.", description = nil, progress = "L’honneur se mérite chez les trolls de Zandalar, <nom>. Avec l’honneur viennent les récompenses : l’amitié, les alliances… \n\nDonnez-moi le talisman pour que je puisse renforcer son pouvoir.", completion = "Utilisez les ténèbres, &lt;classe&gt;. Étreignez les ombres. Laissez la souillure de Kezan améliorer vos sombres agissements.", rewards = "Vous recevrez :\n\nSouillure de Kezan"},
[8108] = {title = "La souillure de Kezan", objective = "Je suis prêt, <classe>. Je vais une nouvelle fois améliorer votre talisman. Je vous demande seulement de continuer votre destruction d’Hakkar et de ses séides.\n\nDonnez-moi le talisman.", description = nil, progress = "Je suis prêt, <classe>. Je vais une nouvelle fois améliorer votre talisman. Je vous demande seulement de continuer votre destruction d’Hakkar et de ses séides.\n\nDonnez-moi le talisman.", completion = "Ce n’est qu’en combinant nos efforts que nous parviendrons à arrêter l’Écorcheur d’âmes.", rewards = "Vous recevrez :\n\nSouillure de Kezan"},
[8109] = {title = "La souillure irrésistible de Kezan", objective = "Appelez vos démons, <classe>. Qu’ils se baignent dans l’énergie de la Souillure de Kezan. Commandez-les sur le champ de bataille ! Décimez nos ennemis !\n\nOui… Le temps est venu d’apporter l’amélioration finale à la Souillure de Kezan. Donnez-moi le talisman.", description = nil, progress = "Appelez vos démons, <classe>. Qu’ils se baignent dans l’énergie de la Souillure de Kezan. Commandez-les sur le champ de bataille ! Décimez nos ennemis !\n\nOui… Le temps est venu d’apporter l’amélioration finale à la Souillure de Kezan. Donnez-moi le talisman.", completion = "Écorchez leurs cadavres… Regardez comme les ombres consument les Hakkari. Tirez du pouvoir de leurs peurs, &lt;classe&gt;. Que la Souillure de Kezan augmente cette puissance…", rewards = "Vous recevrez :\n\nSouillure irrésistible de Kezan"},
[8110] = {title = "Le varech enchanté des Mers du sud", objective = "Vous voyez cette algue ? Elle vient des Mers du sud. Nous lui ajoutons juste un peu de mojo et de magie, et elle gagne les propriétés qui sont les plus utiles à son porteur.\n\nVous êtes un <classe>, alors ce sera facile. Enroulez-la simplement autour de votre cou, et pensez à la nature, aux écureuils, ou à n’importe quelle chose qu’aiment les gens de votre peuple.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nVarech enchanté des Mers du sud"},
[8111] = {title = "Le varech enchanté des Mers du sud", objective = "Salut ! C’est bien sympathique de revenir nous voir. Toute la tribu raconte comment vous avez tué les Hakkari et tout ça. Molthor m’a fait passer le mot, et m'a demandé de rajouter plus de mojo dans votre talisman. Donnez-le-moi, et Maywiki l’améliorera.", description = nil, progress = "Salut ! C’est bien sympathique de revenir nous voir. Toute la tribu raconte comment vous avez tué les Hakkari et tout ça. Molthor m’a fait passer le mot, et m'a demandé de rajouter plus de mojo dans votre talisman. Donnez-le-moi, et Maywiki l’améliorera.", completion = "Le collier ne se fume pas, gamin ! On s’en sert pour combattre le mal.", rewards = "Vous recevrez :\n\nVarech enchanté des Mers du sud"},
[8112] = {title = "Le varech enchanté des Mers du sud", objective = "Comment va votre talisman ? On dirait que c’est l’heure d’ajouter un petit peu plus de magie et de mojo à ses feuilles. Il a besoin d’une petite fleur dans son desséchement. Donnez-le-moi et Maywiki le réparera.", description = nil, progress = "Comment va votre talisman ? On dirait que c’est l’heure d’ajouter un petit peu plus de magie et de mojo à ses feuilles. Il a besoin d’une petite fleur dans son desséchement. Donnez-le-moi et Maywiki le réparera.", completion = "Maintenant, allez attaquer les trolls maléfiques de Zul’Gurub, et montrez-leur de quoi sont capables les pouvoirs de la nature !", rewards = "Vous recevrez :\n\nVarech enchanté des Mers du sud"},
[8113] = {title = "Le varech enchanté des Mers du sud en parfait état", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nVarech enchanté des Mers du sud en parfait état"},
[8114] = {title = "Contrôler quatre bases", objective = "Entrez dans le bassin d'Arathi, capturez et contrôlez quatre bases simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "<nom>, vous avez pris part à la bataille du bassin d'Arathi contre nos ennemis, et acquis un grand honneur sur ce champ de bataille. Vous nous avez démontré que vous êtes un <classe> de grande valeur, et nos adversaires ont bien compris que vous ne vous soumettrez pas à leur félonie !\n\nPuisque vous êtes si <doué/douée>, je vais vous confier une tâche difficile. Je veux que vous preniez et teniez au moins quatre des bases du bassin d'Arathi. Si vous y parvenez, non seulement nous nous assurerons de la possession de ressources vitales, mais nous montrerons notre puissance à la Horde !\n\nAllez, <nom>, bonne chance.", progress = nil, completion = "Très bon travail, &lt;nom&gt; ! Un éclaireur enthousiaste est venu me rapporter vos exploits. La Ligue d’Arathor est enchantée !\n\nVous êtes en train de devenir une légende chez les soldats de la Ligue, et vos actions d’aujourd’hui sont une nouvelle fois à la hauteur de votre excellente réputation.", rewards = "Vous recevrez :\n\n"},
[8115] = {title = "Prendre cinq bases", objective = "Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "Se battre pour s'approprier les ressources du bassin d'Arathi est une entreprise sanglante, <nom>. Le service que vous rendez à la Ligue d'Arathor est aussi nécessaire qu'apprécié.\n\nEt nous avons une tâche supplémentaire à vous confier.\n\nLa Ligue souhaite lancer une puissante offensive contre l'occupation du bassin d'Arathi par les Profanateurs. Nous voulons les chasser de tous les points stratégiques du champ de bataille !\n\nCe ne sera pas facile, mais si quelqu'un peut y parvenir, c'est bien vous.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTabard de bataille d'Arathor"},
[8116] = {title = "Vision de Voodress", objective = "Vous et Maywiki avez quelque chose en commun, gamin. Nous sommes des chamans ! Mais bon, Maywiki est plutôt une mystique, et vous un second couteau. Enfin, nous savons tous deux ce qu’apportent les grands esprits.\n\nJe vous offre cet orbe, pour que vous le portiez en collier. Regardez à l’intérieur, et vous verrez le village de Voodress dans les Mers du sud ! Qu’il élève vos esprits !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nVision de Voodress"},
[8117] = {title = "Vision de Voodress", objective = "Cha-lut ! Maywiki a fait une blague !\n\n<Maywiki rit.>\n\nEh bien, vous avez utilisé les esprits et les éléments contre nos ennemis à Zul’Gurub, hein ? Loués soient les esprits !\n\nMaywiki va faire briller votre orbe. Donnez-le-moi, <nom>.", description = nil, progress = "Cha-lut ! Maywiki a fait une blague !\n\n<Maywiki rit.>\n\nEh bien, vous avez utilisé les esprits et les éléments contre nos ennemis à Zul’Gurub, hein ? Loués soient les esprits !\n\nMaywiki va faire briller votre orbe. Donnez-le-moi, <nom>.", completion = "Regardez-le maintenant, &lt;nom&gt;. Voodress est encore plus visible, non ? Laissez le pouvoir primordial s’écouler en vous…", rewards = "Vous recevrez :\n\nVision de Voodress"},
[8118] = {title = "Vision de Voodress", objective = "Bonnes nouvelles, <nom>. Molthor a chanté vos louanges, récemment. Il raconte comment vous êtes en train de devenir un grand héros de Zandalar.\n\nIl a aussi demandé à Maywiki d’améliorer une nouvelle fois votre orbe ! Donnez-le-moi pour que Maywiki puisse éclairer la vision.", description = nil, progress = "Bonnes nouvelles, <nom>. Molthor a chanté vos louanges, récemment. Il raconte comment vous êtes en train de devenir un grand héros de Zandalar.\n\nIl a aussi demandé à Maywiki d’améliorer une nouvelle fois votre orbe ! Donnez-le-moi pour que Maywiki puisse éclairer la vision.", completion = "Prenez gardes aux mauvais esprits hakkari. Je vous jure qu’ils font froid dans le dos.", rewards = "Vous recevrez :\n\nVision de Voodress"},
[8119] = {title = "La vision limpide de Voodress", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nVision limpide de Voodress"},
[8120] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !\n\nAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.\n\nAllez, <nom>. Revenez me voir quand vous aurez accompli votre tâche.", progress = nil, completion = "Un éclaireur des Profanateurs m’a rapporté la nouvelle de votre succès, &lt;nom&gt;. Bien joué.\n\nComme vous l’apprendrez bientôt, pour gagner la bataille d’Arathi, nous devons rester vigilants et écraser toutes les tentatives d’expansion de l’Alliance. Si nous y parvenons, notre victoire est assurée.", rewards = "Vous recevrez :\n\n"},
[8121] = {title = "Prendre quatre bases", objective = "Contrôlez quatre bases du bassin d'Arathi simultanément, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Alors que les combats pour le bassin d’Arathi font rage, le récit de vos exploits est parvenu à de nombreuses oreilles, <nom>. Vous êtes très bien <considéré /considérée > dans nos rangs, et je suis certain que vous réussirez la mission que je vais vous confier.\n\nIl est temps d’envoyer un message à la Ligue d’Arathor. Nous devons leur démontrer que leurs installations dans le bassin d’Arathi sont précaires, et qu’ils peuvent les perdre rapidement. Et nous allons le faire en prenant le contrôle, d’un coup, de quatre points stratégiques du bassin d’Arathi.\n\nSi vous réussissez cette mission, <nom>, vous acquerrez un grand respect chez les Profanateurs.", progress = nil, completion = "Bon travail, &lt;nom&gt; ! Vos derniers engagements dans le bassin d’Arathi étaient assez difficiles, et votre réussite est digne d’éloge. La Ligue d’Arathor semble reculer après les récentes escarmouches, et doit être en train de panser ses blessures. Espérons qu’elle réexaminera sa décision de combattre dans cette région.", rewards = "Vous recevrez :\n\n"},
[8122] = {title = "Prendre cinq bases", objective = "Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Il est difficile de se rendre compte de la situation, tant le conflit est intense. Mais nos espions nous ont signalé un certain affaiblissement de la détermination de la Ligue d’Arathor. Nous devons profiter de cette opportunité et lancer une attaque brutale ! Retournez dans le bassin d’Arathi et chargez nos ennemis. Maudissez-les, tuez-les, et contrôlez les cinq bases stratégiques ! Que sous vos coups leurs soldats ensanglantés s’enfuient du front en hurlant, pour répandre partout l’histoire de votre cruauté.\n\nAllez, et remportez une grande victoire pour les Profanateurs !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTabard de bataille des Profanateurs"},
[8123] = {title = "Couper les voies de ravitaillement d'Arathor", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au Traqueur noir Mortis au Trépas-d'Orgrim.", description = "La Ligue d’Arathor n’épargne aucune dépense dans sa tentative de reprise du bassin d’Arathi. Avec l’aide de tous les peuples de l’Alliance, qui se rendent maintenant en masse vers cette région lointaine, elle a l’intention d’étendre son emprise depuis le refuge de l’Ornière. Nous devons les arrêter, et le meilleur moyen d’y parvenir est de nous emparer de leurs réserves.\n\nVous pouvez nous aider, <nom>. Entrez dans le bassin d’Arathi, connu pour ses mines productives, ses terres fertiles et ses artisans habiles. Capturez et contrôlez un maximum de bases, remportez la bataille, et revenez me voir avec les ressources dont vous vous serez <emparé/emparée>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8124] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8141] = {title = "Le talisman d'ombre zandalarien", objective = "Vous progressez rapidement, jeune <classe>. Il est sans doute temps de vous initier pour vous faire entrer dans le Shera Ali’kh -  la Main de la Mort, en zandalari. Pendant des milliers d’années, nous avons été les assassins de l’empire Zandalar. Mais nous sommes restés oisifs pendant trop longtemps, permettant aux Hakkari d’accroître leurs forces. Aujourd’hui, nous devons à nouveau affronter Hakkar, mais cette fois sans le soutien d’une nation troll unifiée. Ce sont vous et vos alliés qui devez nous aider à vaincre le Dieu du Sang et ses séides !\n\nPortez ce talisman, qui vous aidera dans vos pérégrinations.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTalisman de l'ombre zandalarien"},
[8142] = {title = "Talisman d'ombre zandalarien", objective = "J’ai le sentiment que vous avez infligé d’innombrables pertes aux Hakkari, <nom>. Vous portez sur vous la puanteur de leur mojo.\n\nJe suppose que le talisman d’ombre a bien participé au massacre… Donnez-le-moi et permettez-moi d’augmenter son pouvoir.", description = nil, progress = "J’ai le sentiment que vous avez infligé d’innombrables pertes aux Hakkari, <nom>. Vous portez sur vous la puanteur de leur mojo.\n\nJe suppose que le talisman d’ombre a bien participé au massacre… Donnez-le-moi et permettez-moi d’augmenter son pouvoir.", completion = "Il vaut mieux rester à l’écart d’un assassin de votre calibre. Vos ennemis doivent apprendre le respect ! Et vous l’obtiendriez quand vos adversaires verront la lueur de la Main de la Mort… trop tard…", rewards = "Vous recevrez :\n\nTalisman de l'ombre zandalarien"},
[8143] = {title = "Le Talisman d'ombre zandalarien", objective = "Impressionnant, <nom>. Vous avez un don pour le meurtre que je n’ai pas ressenti chez quelqu’un depuis de longues années. Même Molthor est conscient du travail que vous avez effectué pour Zandalar. Il est temps d’améliorer une nouvelle fois votre talisman. Donnez-le-moi.", description = nil, progress = "Impressionnant, <nom>. Vous avez un don pour le meurtre que je n’ai pas ressenti chez quelqu’un depuis de longues années. Même Molthor est conscient du travail que vous avez effectué pour Zandalar. Il est temps d’améliorer une nouvelle fois votre talisman. Donnez-le-moi.", completion = "Il ne reste plus qu’une seule amélioration à placer sur le talisman, &lt;classe&gt;. Quand le temps sera venu, je l’appliquerai.", rewards = "Vous recevrez :\n\nTalisman de l'ombre zandalarien"},
[8144] = {title = "Le talisman de maîtrise de l'ombre zandalarien", objective = "Le talisman brûle d’envie de grandir, <nom>. Il a absorbé tout ce que vous avez accompli. Les milliers de cadavres de trolls qui jonchent Zul’Gurub ont alimenté son pouvoir. Donnez-le-moi, et j’accomplirai l’amélioration finale.", description = nil, progress = "Le talisman brûle d’envie de grandir, <nom>. Il a absorbé tout ce que vous avez accompli. Les milliers de cadavres de trolls qui jonchent Zul’Gurub ont alimenté son pouvoir. Donnez-le-moi, et j’accomplirai l’amélioration finale.", completion = "C’est la dernière fois que nous parlons sous les auspices du Shera Ali’kh. Vous avez appris tout ce que vous devez savoir. Prenez le talisman et continuez les assassinats. Hakkar ne doit jamais quitter Zul’Gurub.", rewards = "Vous recevrez :\n\nTalisman de maîtrise de l'ombre zandalarien"},
[8145] = {title = "Les Vrilles du maelström", objective = "Chez les Zandalariens, la profession de <classe> est tenue en très haute estime. Nos plus grands chasseurs voyagent jusqu’au bord du Maelström pour prouver leur résolution.\n\nIls tirent des entrailles de la mer des rubans de varech, que l’on nomme les Vrilles du Maelström. Le varech est tressé pour confectionner un talisman qui, une fois enchanté, augmente la précision et la puissance de leurs attaques.\n\nJe vous offre aujourd’hui cette simple tresse de Vrilles du Maelström. Quand votre lien avec Zandalar aura grandi, je tisserai plus de puissance dans le talisman.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nVrille du maelström"},
[8146] = {title = "Les Vrilles du maelström", objective = "Ah, <nom>, c’est bon de sentir votre odeur à nouveau.\n\n\n\nVous devez me pardonner mon sens de l’humour. Il peut être assez noir, par moment.\n\nJ’ai cru comprendre que vous avez infligé de terribles angoisses à nos ennemis. Les troupes d’Hakkar, folles de colère, maudissent votre nom. C’est excellent.\n\nVous avez gagné un nouvel enchantement de votre talisman. Donnez-le-moi.", description = nil, progress = "Ah, <nom>, c’est bon de sentir votre odeur à nouveau.\n\n\n\nVous devez me pardonner mon sens de l’humour. Il peut être assez noir, par moment.\n\nJ’ai cru comprendre que vous avez infligé de terribles angoisses à nos ennemis. Les troupes d’Hakkar, folles de colère, maudissent votre nom. C’est excellent.\n\nVous avez gagné un nouvel enchantement de votre talisman. Donnez-le-moi.", completion = "Qu’ils trouvent donc l’expiation à la pointe de vos armes.", rewards = "Vous recevrez :\n\nVrille du maelström"},
[8147] = {title = "Les Vrilles du maelström", objective = "J’entends d’ici le bruit de nos volées de flèches qui dévastent les rangs de nos ennemis. Leurs cris d’agonie y font écho.\n\nVous vous êtes fait un nom chez les trolls de Zandalar, <nom>. Nous vous sommes reconnaissant de tout ce que vous avez fait.\n\nDonnez-moi votre talisman pour que je puisse y ajouter un nouvel enchantement.", description = nil, progress = "J’entends d’ici le bruit de nos volées de flèches qui dévastent les rangs de nos ennemis. Leurs cris d’agonie y font écho.\n\nVous vous êtes fait un nom chez les trolls de Zandalar, <nom>. Nous vous sommes reconnaissant de tout ce que vous avez fait.\n\nDonnez-moi votre talisman pour que je puisse y ajouter un nouvel enchantement.", completion = "Je ne peux plus ajouter qu’un seul tissage à votre talisman, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nVrille du maelström"},
[8148] = {title = "Le courroux du maelström", objective = "Molthor nous a transmis la parole du roi Rastakhan, <nom>.  La cour royale est très impressionnée par votre décimation des forces hakkari. Je dois vous récompenser par l’enchantement final de votre talisman. Donnez-le-moi.", description = nil, progress = "Molthor nous a transmis la parole du roi Rastakhan, <nom>.  La cour royale est très impressionnée par votre décimation des forces hakkari. Je dois vous récompenser par l’enchantement final de votre talisman. Donnez-le-moi.", completion = "Votre voyage ne fait que commencer, jeune &lt;classe&gt;. Peut-être qu’un jour vous visiterez le Maelström et que vous regarderez le cœur du monde.\n\nJe vous souhaite force et courage !", rewards = "Vous recevrez :\n\nCourroux du maelström"},
[8149] = {title = "En l'honneur d'un héros", objective = "Rendez-vous au tombeau d’Uther dans les Maleterres de l’ouest, puis utilisez Offrande à Uther sur sa statue, avant de retourner voir Wagner Hammerstrike à l’extérieur d’Ironforge, avant la fin de la Fête des moissons.\n\nObjet fourni : \n", description = "Au cours de la Fête des moissons d’Azeroth, nous rendons grâces aux héros pour les sacrifices accomplis pour nous – y compris, dans certains cas, celui de leur vie. L’Alliance se souvient de nombreux héros, mais aucune histoire n’est plus tragique que celle d’Uther le Porteur de Lumière.\n\nAidez-nous à rendre hommage à Uther en allant déposer cette offrande sur sa tombe, dans les Maleterres de l’ouest. Placez-la aux pieds de sa statue, puis revenez me voir. Je ne serai là que jusqu’à la fin de la fête, alors ne perdez pas de temps pour rendre hommage à Uther !", progress = "Vous êtes-vous rendu au tombeau d’Uther pour y déposer une offrande ?\n\nC’est un endroit dangereux pour les aventuriers inexpérimentés. Le chemin le plus sûr, même si c’est une sécurité très relative, reste de remonter le fleuve qui traverse Hillsbrad. Il part des Maleterres, et plus précisément d’un lac qui touche la colline des Chagrins. Lorsque vous y serez, vous n’avez plus qu’à partir à l’ouest, en évitant l’autre tombeau, celui qui est aux mains du Fléau.", completion = "Uther… un héros parmi les héros. Je n’ose même pas imaginer la souffrance qu’il a ressenti lorsqu’il a vu Arthas, le meilleur de ses disciples, celui qu’il aimait comme un fils, trahir toute l’humanité. Mais il s’est dressé contre Arthas. Il a tenté de l’arrêter. Pour cela, nous nous souviendrons de lui à tout jamais comme d’un authentique paladin. Il s’est battu jusqu’au bout, ne pensant qu’à ceux qu’il pouvait sauver.\n\nMerci, &lt;nom&gt;. Vous avez rendu hommage à un grand héros. Vous avez fait honneur à son esprit, et à l’esprit de la Fête des moissons.", rewards = "Vous recevrez :\n\nPour la Lumière !"},
[8150] = {title = "En l'honneur d'un héros", objective = "Rendez-vous au monument de Grom dans le canyon de la Malechute en Ashenvale, puis utilisez Offrande à Grom à la base du monument. Ensuite, retournez voir Javnir Nashak à l’extérieur d’Orgrimmar, avant la fin de la Fête des moissons.\n\nObjet fourni : \n", description = "Au cours de la Fête des moissons d’Azeroth, nous rendons grâces aux héros pour les sacrifices accomplis pour nous – y compris, dans certains cas, celui de leur vie. La Horde se souvient de nombreux héros, mais c’est Grom Hellscream qui personnifie le mieux la force et le sacrifice.\n\nS’il vous plaît, aidez-nous à honorer Grom en allant déposer cette offrande au pied de son monument, dans le canyon de la Malechute, en Ashenvale. Lorsque ce sera fait, revenez me voir. Je ne serai là que jusqu’à la fin de la fête, alors ne perdez pas de temps pour rendre hommage à Grom !", progress = nil, completion = "Le nom complet de Grom était Grommash, “Coeur de géant”. Il en était digne, car il s’est tenu, seul, face à Mannoroth. Je crois que le Chef de guerre a su trouver les mots justes quand il a dit que la malédiction des orcs avait commencé et s’était achevée avec Grom. Son sacrifice, et peut-être sa rédemption, sont devenus la source d’où est sortie notre Horde.\n\nMerci, &lt;nom&gt;. Vous avez rendu hommage à un grand héros. Vous avez fait honneur à son esprit, et à l’esprit de la Fête des moissons.", rewards = "Vous recevrez :\n\nLe Cri de la Horde"},
[8151] = {title = "Le charme du chasseur", objective = "Parlez à Ogtinc en Azshara.", description = "Ogtinc, d'Azshara, recherche des chasseurs aguerris comme vous. C'est un chasseur furbolg qui a quitté sa tribu pour aider le Cercle cénarien. Il enseigne sa sagesse à ceux qui partagent son art, et les guide dans les voies de l'équilibre. Vous devriez lui parler.\n\nOgtinc réside au sommet des falaises d'Azshara, au nord-est des ruines d’Eldarath.", progress = nil, completion = "Mon rôle n'est plus de chasser, mais d'apprendre aux chasseurs.  Tel est le destin qui m'a été offert.\n\nConfectionnez avec moi un charme du &lt;classe&gt; : un ensemble de trophées pris sur vos proies qui vous rappellera vos épreuves et triomphes passés.  Je garderai le charme, mais je vous récompenserai avec autre chose.", rewards = "Vous recevrez :\n\n"},
[8152] = {title = "REUSE", objective = "Parlez à Ogtinc en Azshara.<nom>, quand vous vous sentirez <prêt/prête>, un vieux chasseur furbolg du nom d'Ogtinc demeure en Azshara. Il pourrait poursuivre votre enseignement et vous montrer la voie.\n\nOgtinc se trouve au sommet des falaises au nord-est des ruines d'Eldarath en Azshara.Lors de l'achèvement de cette quête vous gagnerez :\n\n", description = "<nom>, quand vous vous sentirez <prêt/prête>, un vieux chasseur furbolg du nom d'Ogtinc demeure en Azshara. Il pourrait poursuivre votre enseignement et vous montrer la voie.\n\nOgtinc se trouve au sommet des falaises au nord-est des ruines d'Eldarath en Azshara.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[8153] = {title = "La ramure de coursier", objective = "Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath.", description = "Les coursiers portent les ramures les plus imposantes que l’on connaisse. Elles leurs servent à se défendre, mais ils abîment souvent leurs pointes en éventrant leurs attaquants. Une ramure parfaite indique un esprit animal très sûr de lui.\n\nDétenir de telles ramures vous octroierait la même confiance en vous.\n\nChassez les coursiers Sabots-de-mousse, trouvez des ramures parfaites et apportez-les-moi.", progress = "Avez-vous trouvé les ramures ?", completion = "Vous devez avoir une vue aiguisée et une patience à toute épreuve pour avoir récupéré ces ramures. Beau travail.", rewards = "Vous recevrez :\n\n"},
[8154] = {title = "Les ressources du bassin d'Arathi", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière.", description = "Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !\n\nC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !\n\nVoici ce que je veux que vous fassiez, <nom>. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8155] = {title = "Les ressources du bassin d'Arathi", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière.", description = "Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !\n\nC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !\n\nVoici ce que je veux que vous fassiez, <nom>. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8156] = {title = "Les ressources du bassin d'Arathi", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière.", description = "Une guerre se fait avec des soldats - tous les soldats pourront vous le confirmer. Ils vous diront aussi que livrer bataille l’estomac vide, avec un mauvais équipement, est une garantie de défaite !\n\nC’est pour cette raison que le bassin d’Arathi est si important. Certains endroits clés de cette région contiennent des ressources essentielles. Des métaux, des armes, de la nourriture, du bois… Tout ce dont nous avons besoin se trouve là-bas !\n\nVoici ce que je veux que vous fassiez, <nom>. Entrez dans le bassin d’Arathi, remportez la bataille en contrôlant plus de bases que l’ennemi, et revenez me voir avec une caisse de ressources.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8157] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8158] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8159] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8160] = {title = "Couper les voies de ravitaillement d'Arathor", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au Traqueur noir Mortis au Trépas-d'Orgrim.", description = "La Ligue d’Arathor n’épargne aucune dépense dans sa tentative de reprise du bassin d’Arathi. Avec l’aide de toutes les races de l’Alliance, qui se rendent maintenant en masse vers cette région lointaine, elle a l’intention d’étendre son emprise depuis le Refuge de l’Ornière. Nous devons les arrêter, et le meilleur moyen d’y parvenir est de nous emparer de leurs réserves.\n\nVous pouvez nous aider, <nom>. Entrez dans le bassin d’Arathi, connu pour ses mines productives, ses terres fertiles et ses artisans habiles. Capturez et contrôlez un maximum de bases, remportez la bataille, et revenez me voir avec les ressources dont vous vous serez emparé.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8161] = {title = "Couper les voies de ravitaillement d'Arathor", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au Traqueur noir Mortis au Trépas-d'Orgrim.", description = "La Ligue d’Arathor n’épargne aucune dépense dans sa tentative de reprise du bassin d’Arathi. Avec l’aide de toutes les races de l’Alliance, qui se rendent maintenant en masse vers cette région lointaine, elle a l’intention d’étendre son emprise depuis le Refuge de l’Ornière. Nous devons les arrêter, et le meilleur moyen d’y parvenir est de nous emparer de leurs réserves.\n\nVous pouvez nous aider, <nom>. Entrez dans le bassin d’Arathi, connu pour ses mines productives, ses terres fertiles et ses artisans habiles. Capturez et contrôlez un maximum de bases, remportez la bataille, et revenez me voir avec les ressources dont vous vous serez emparé.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8162] = {title = "Couper les voies de ravitaillement d'Arathor", objective = "Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au Traqueur noir Mortis au Trépas-d'Orgrim.", description = "La Ligue d’Arathor n’épargne aucune dépense dans sa tentative de reprise du bassin d’Arathi. Avec l’aide de toutes les races de l’Alliance, qui se rendent maintenant en masse vers cette région lointaine, elle a l’intention d’étendre son emprise depuis le Refuge de l’Ornière. Nous devons les arrêter, et le meilleur moyen d’y parvenir est de nous emparer de leurs réserves.\n\nVous pouvez nous aider, <nom>. Entrez dans le bassin d’Arathi, connu pour ses mines productives, ses terres fertiles et ses artisans habiles. Capturez et contrôlez un maximum de bases, remportez la bataille, et revenez me voir avec les ressources dont vous vous serez emparé.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
