[8165] = {title = "Plus de caisses de ressources", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8166] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, <nom>. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.\n\nAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !\n\nQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.", progress = nil, completion = "J’ai reçu des rapports sur vos exploits dans le bassin d’Arathi, &lt;nom&gt;. Bien joué ! Avec l’aide d’autres personnes comme vous, qui ont elles aussi rejoint notre lutte, je suis sûr que nous reprendrons un jour notre patrie.", rewards = "Vous recevrez :\n\n"},
[8167] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, <nom>. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.\n\nAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !\n\nQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8168] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.", description = "La bataille pour le bassin d’Arathi est un combat pour les ressources et les terres, <nom>. Les points clés de la région doivent être protégés et maintenus en état de fonctionner pour qu’ils continuent à fournir à nos troupes les matériaux bruts et les approvisionnements qui leur sont si nécessaires Je vous charge d’attaquer les points les plus éloignés de notre base du bassin d’Arathi.\n\nAttaquez la ferme, la mine, la scierie et la forge quand elles sont contrôlées par l’ennemi. Trouvez la bannière de l’adversaire et arrachez-là de son mât !\n\nQuand vous aurez réussi ces objectifs pour ces quatre points clés, revenez me voir.", progress = nil, completion = "J’ai reçu des rapports sur vos exploits dans le bassin d’Arathi, &lt;nom&gt;. Bien joué ! Avec l’aide d’autres personnes comme vous, qui ont elles aussi rejoint notre lutte, je sais que nous reprendrons un jour notre patrie.", rewards = "Vous recevrez :\n\n"},
[8169] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !\n\nAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.\n\nAllez, <nom>. Revenez me voir quand vous aurez accompli votre tâche.", progress = nil, completion = "Un éclaireur des Profanateurs m’a rapporté la nouvelle de votre succès, &lt;nom&gt;. Bien joué.\n\nComme vous l’apprendrez bientôt, pour gagner la bataille d’Arathi, nous devons rester vigilants et écraser toutes les tentatives d’expansion de l’Alliance. Si nous y parvenons, notre victoire est assurée.", rewards = "Vous recevrez :\n\n"},
[8170] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !\n\nAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.\n\nAllez, <nom>. Revenez me voir quand vous aurez accompli votre tâche.", progress = nil, completion = "Un éclaireur des Profanateurs m’a rapporté la nouvelle de votre succès, &lt;nom&gt;. Bien joué.\n\nComme vous l’apprendrez bientôt, pour gagner la bataille d’Arathi, nous devons rester vigilants et écraser toutes les tentatives d’expansion de l’Alliance. Si nous y parvenons, notre victoire est assurée.", rewards = "Vous recevrez :\n\n"},
[8171] = {title = "La bataille pour le bassin d'Arathi !", objective = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.", description = "Comme vous l’avez sûrement entendu, la Ligue d’Arathor envoie un grand nombre de troupes dans le bassin d’Arathi. Avides de nourriture et de matières premières, ces fous de l’Alliance ont l’intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu’Arathi ne sera plus jamais le foyer de pitoyables humains !\n\nAllez dans le bassin d’Arathi et attaquez la mine, la scierie, la forge et l’écurie. Mettez à bas la bannière de l’ennemi, et emparez-vous de ces territoires pour la Horde.\n\nAllez, <nom>. Revenez me voir quand vous aurez accompli votre tâche.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8181] = {title = "La confrontation avec Yeh'kinya", objective = "Parlez à Yeh'kinya.", description = "Les tablettes Mosh’aru contiennent de mauvaises nouvelles, <nom>. La véritable forme d’Hakkar, le dieu lui-même, peut renaître par l’intermédiaire de l’œuf dans lequel vous l’avez enfermé. Yeh’kinya vous avait dit que c’était pour contenir sa malfaisance, mais c’était pour la recréer ! Le troll s’est trompé – ou nous a trompés !\n\nRetournez voir Yeh’kinya et demandez-lui l’œuf. Espérons qu’il n’est pas trop tard pour empêcher Hakkar de revenir !", progress = nil, completion = "Alors, vous avez parlé avec ce vieux nain, Ironboot, et découvert les tablettes perdues de Mosh’aru ? Ce fouinard de prospecteur...\n\nMais ce n’est pas la question. Il est trop tard pour sauver le monde. Hakkar est né à nouveau, et son pouvoir ne cesse de croître, loin à l’intérieur de l’antique royaume troll de Zul’Gurub ! Il est venu, et il règnera par le sang et la terreur !\n\nMerci, &lt;nom&gt;. Grâce à votre aide, son règne arrivera plus vite !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCape hakkari terneCape hakkari rapiécée\n\nVous recevrez également :\n\n"},
[8182] = {title = "La main de Rastakhan", objective = "Parlez à Molthor à Strangleronce.", description = "<nom>, nos pires craintes se réalisent. Les légendes racontent que l’Écorcheur d’âmes régnait naguère sur les trolls par le mal et la terreur, et il exerçait un pouvoir sans partage. Si nous ne l’arrêtons pas maintenant, son royaume risque de s’étendre à tout Azeroth !\n\nLes envoyés des trolls zandalariens nous aideront peut-être à interrompre la montée des ténèbres. Ils se sont installés sur l'île de Yojamba, sur la côte de Strangleronce, à l’ouest des ruines de Zul’Kunda. Parlez à leur chef, Molthor, et prions pour qu’il sache comment vaincre Hakkar.", progress = nil, completion = "C’est le prospecteur Ironboot qui vous envoie ? Son peuple est sage, et il est plus sage encore, car les trolls zandalariens et moi-même connaissons peut-être un moyen de vaincre l’Ecorcheur d’Âmes.\n\nParlez avec les trolls de l’île, écoutez leurs paroles… et préparez-vous, &lt;nom&gt;, car la tâche qui vous attend sera sanglante, en vérité.", rewards = "Vous recevrez :\n\n"},
[8183] = {title = "Le cœur d'Hakkar", objective = "Donnez le Cœur d'Hakkar à Molthor sur l'île de Yojamba.", description = "Le cœur d’Hakkar brûle de l’intérieur. En dépit de la défaite de l’Ecorcheur d’âmes, l’essence de sa puissance repose encore dans cet organe maudit.", progress = "La puanteur d’une âme maléfique vous accompagne, <nom>. Avez-vous été maudit par l’Ecorcheur d’âmes ?", completion = "Ah, le cœur d’Hakkar. Ainsi, l’Ecorcheur d’âmes a été tué ! Notre monde est sauvé !\n\n&lt;nom&gt;, vous nous avez rendu un immense service. En vérité, vous êtes parmi les plus grands héros qui aient jamais vécu !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nInsigne de héros zandalarienCharme de héros zandalarienMédaillon de héros zandalarien\n\nVous recevrez également :\n\n"},
[8184] = {title = "La présence de la puissance", objective = "Zanza peut créer les anciens enchantements des trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants Hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRamenez-moi ces choses et je vous façonnerai un enchantement puissant !", description = nil, progress = "Zanza peut créer les anciens enchantements des trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants Hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRamenez-moi ces choses et je vous façonnerai un enchantement puissant !", completion = "Utilisez-le à bon escient, &lt;classe&gt;. Ne faites preuve d’aucun pitié envers les Hakkari !", rewards = "Vous recevrez :\n\nPrésence de la puissance"},
[8185] = {title = "Le signe du syncrétiste", objective = "Zanza peut créer les anciens enchantements des trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRamenez-moi ces choses et je vous façonnerai un enchantement puissant !", description = nil, progress = "Zanza peut créer les anciens enchantements des trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRamenez-moi ces choses et je vous façonnerai un enchantement puissant !", completion = "Utilisez-le à bon escient, &lt;classe&gt;. Ne faites preuve d’aucun pitié envers les Hakkari !", rewards = "Vous recevrez :\n\nSigne du syncrétiste"},
