[8408] = {title = "La lutte pour le goulet des Warsong", objective = "N'oubliez pas que la bataille pour le goulet des Warsong représente bien plus que la protection de quelques arbres.  Il s'agit de conserver une frontière naturelle entre Ashenvale et les Tarrides.  Vous avez des nouvelles du champ de bataille, <nom> ?", description = nil, progress = "N'oubliez pas que la bataille pour le goulet des Warsong représente bien plus que la protection de quelques arbres.  Il s'agit de conserver une frontière naturelle entre Ashenvale et les Tarrides.  Vous avez des nouvelles du champ de bataille, <nom> ?", completion = "Bon travail, &lt;nom&gt;. Grâce à vous, nos défenses naturelles de l’Ashenvale resteront encore intactes pour un jour…", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +398"},
[8409] = {title = "Des tonneaux gâtés", objective = "Retournez voir la sombre imploratrice Yanka à la Fête de l'homme d'osier dans les clairières de Tirisfal.", description = "Les œufs ont été placés à l’intérieur du tonneau. Les prochaines cuvées de bière de l’auberge de Southshore seront de toute évidence gâtées !\n\nVous devriez maintenant retourner voir la sombre imploratrice Yanka à la Fête de l’homme d’osier, et lui annoncer votre succès.", progress = nil, completion = "Ah, vous avez réussi !  Vous avez fait preuve d’un véritable esprit de la Sanssaint - d’un esprit des RÉPROUVÉS, devrais-je dire !\n\n&lt;La sombre imploratrice Yanka ricane et se frotte les mains.&gt;\n\nSavoir que Southshore doit festoyer avec un cuvée gâtée, ou se passer de bière, me réjouit le cœur !  Quant à vous, prenez ces bonbons.  Je crois que vous en ferez bon usage !", rewards = "Vous recevrez :\n\nBonbon à la citrouille de la Sanssaint"},
[8410] = {title = "La maîtrise des éléments", objective = "Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents.", description = "Bath’rah la Vigie des Vents a demandé qu’un chaman aussi sage que vous vienne le voir.  Il demande que vous lui apportiez un échantillon de chacun des éléments, pour lui montrer que vous êtes <prêt/prête>.\n\nPour trouver Bath’rah, allez jusqu’à la rivière à l’est de Moulin-de-Tarren.  Suivez la rivière vers le nord, jusqu’à ce que vous arriviez aux ruines où vit Bath’rah.", progress = "Qu'avez-vous pour moi, <classe> ?", completion = "Excellent, l'ami.  Parlons maintenant.", rewards = "Vous recevrez :\n\n"},
[8411] = {title = "Maîtriser les éléments", objective = "Apportez les éléments terre, air, feu et eau à Bath'rah la Vigie des vents.", description = "Bienvenue, l'<ami/amie>.  Apportez-moi les éléments et ensuite on causera.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8412] = {title = "Le totem des esprits", objective = "Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents.", description = "Les esprits élémentaires de cet endroit ne m’aiment plus.\n\nVous savez ce qu’il en est des totems mieux qu'aucun autre et j’ai besoin d’un totem des esprits pour me protéger. Nous avons déjà les éléments, il nous faut à présent des choses plus en rapport avec la nature. Plus primitives.\n\nDans les Maleterres de l’ouest, tuez des ours pour prendre leurs griffes et des araignées pour leurs yeux.  Les charognards mangent de tout, ils pourraient avoir l'un ou l'autre.", progress = "Les esprits savent ce que nous préparons et ils essayent de me tuer ! J’espère que vous avez tous les morceaux.", completion = "Génial, l’ami ! Voyons ce que cela donne…", rewards = "Vous recevrez :\n\n"},
[8413] = {title = "Vaudou !", objective = "Apporter les Plumes vaudou à Bath'rah la Vigie des vents.", description = "Le totem des esprits ne suffit pas. Nous allons avoir besoin de magie vaudou pour qu’il fonctionne correctement.\n\nLes trolls du temple englouti possèdent des plumes fortement imprégnées de magie vaudou. Allez là-bas et tuez Balafreur, Mijan, Zolo, Hukku, Zul'lor et Loro. Nous aurons alors assez de magie pour un vrai totem des esprits.", progress = "Où sont les plumes, l'ami ?", completion = "Il était temps. J'mérite une bonne nuit de sommeil ! Le totem des esprits me protègera.\n\nJe collectionne des trucs et des machins d'puis longtemps. Vous voulez quelque chose pour vot' peine ?", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoings en azuriteEsprit de l'eau amoureuxBâton sauvage\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8414] = {title = "La dissipation du mal", objective = "Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest.", description = "Salutations, <classe>.  Des croisés comme vous sont les bienvenus dans ces étendues désolées.\n\nVotre force sacrée est nécessaire pour nous aider à combattre les morts-vivants innombrables qui hantent cette région.  Nous avons besoin de vous pour rassembler un grand nombre de pierres du Fléau et les apporter au grand prêtre Thel'danis.  Le grand prêtre garde la tombe d’Uther à la colline des Chagrins, non loin d’ici.\n\nSeule une personne détentrice d’un brevet de l’Aube d’argent peut espérer trouver des pierres du Fléau, il vaudrait donc mieux vous entretenir avec l’officier Pureheart, si vous ne l’avez pas déjà fait.", progress = "Quel maléfice m'avez-vous apporté ?", completion = "Chasser le mal d'une pierre du Fléau est une entreprise risquée, car cela attire l'attention des morts-vivants sur des lieues et des lieues.  Mais la Lumière est forte en vous, &lt;nom&gt;, et je n'ai aucune peur pour vous...", rewards = "Vous recevrez :\n\n"},
[8415] = {title = "La pointe du Noroît", objective = "Parler au commandant Ashlam Valorfist à la pointe du Noroît.", description = "Le commandant Ashlam Valorfist a demandé qu’un paladin de votre pureté et de votre valeur vienne le voir, <nom>. Vous pourrez le trouver à la pointe du Noroît, dans la partie méridionale des Maleterres de l’ouest. Cherchez-le et aidez-le, au nom de la Lumière !", progress = nil, completion = "Très bien, &lt;classe&gt; ! Voyons ce que vous valez.", rewards = "Vous recevrez :\n\n"},
[8416] = {title = "Pierres du Fléau inertes", objective = "Apporter la Pierre du Fléau inerte au commandant Ashlam Valorfist à la pointe du Noroît.", description = "Le mal a été purgé des pierres, <nom>.\n\nJe connais les plans du commandant Ashlam, et il n’a besoin que d’une seule pierre inerte. Apportez-la lui pour que nous puissions plonger le Fléau dans le feu justicier.", progress = "Thal'danis a-t-il pu purifier les pierres du Fléau ?", completion = "Vous avez fait tout ce que j’ai demandé sans poser la moindre question, &lt;nom&gt;.\n\nUne relation de confiance s’est apparemment instaurée entre nous.  Peut-être que je pourrais vous révéler quelques détails supplémentaires sur notre projet.", rewards = "Vous recevrez :\n\n"},
[8417] = {title = "Un esprit troublé", objective = "Parler au Héros déchu de la Horde à l'entrée des Terres foudroyées.", description = "Dans les Terres foudroyées se trouve un esprit troublé qui fut autrefois un grand héros de la Horde. L'honneur d'un guerrier ne meurt pas avec son corps. Vous feriez bien d'aller lui parler.", progress = nil, completion = "Ainsi vous êtes venu pour soulager ma douleur. J'aimerais qu'il vous suffise de m'abattre, mais ce n'est hélas pas si simple...", rewards = "Vous recevrez :\n\n"},
[8418] = {title = "Forger la pierre de pouvoir", objective = "Apporter les plumes vaudou à Ashlam Valorfist.", description = "Nous devons à présent combiner les pierres du Fléau inertes et créer une arme capable de briser les rangs des morts-vivants. Ce ne sera guère une tâche facile, <nom>. Seuls les trolls du temple englouti détiennent la magie rare qui permet de retourner le mal contenu en une chose contre le mal lui-même.\n\nÀ l'intérieur du temple, les trolls sont connus sous les noms de Balafreur, Mijan, Zolo, Hukku, Zul'lor et Loro. N'éprouvez pas de remords envers leurs âmes corrompues... Ce sont des êtres malfaisants.", progress = "Avez-vous tué ces misérables trolls ?", completion = "Voilà qui est excellent, &lt;nom&gt;.  Je suis quelque peu surpris, mais il ne faisait pour moi aucun doute que vous ne nous laisseriez pas tomber.\n\nJ'ai l'honneur de vous faire don de l'une des pierres de pouvoir sacrées.  Faites-en bon usage.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nLame de SancteforgeOrbe sanctifiéChevalière chevaleresque\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\nPierre de pouvoir sacrée"},
[8419] = {title = "La demande d'un diablotin", objective = "Apportez un morceau de Gangrétoffe à Démonet à Gangrebois.", description = "<nom>, un diablotin de Gangrebois nommé Démonet a exigé votre présence. Sa requête est assez spéciale, car il a demandé que vous lui apportiez un morceau de gangrétoffe en gage de « bonne volonté ». Vous êtes un démoniste déjà très puissant et je suppose que vous savez que les satyres de Gangrebois portent de cette étoffe.\n\nVous pourrez trouver Démonet juste au nord des chutes de la Vénéneuse qui, d’après ce que j’ai entendu dire, sont assez belles en cette période de l’année.", progress = "Avez-vous ma gangrétoffe ?", completion = "Quel splendide &lt;classe&gt; vous faites !\n\n\n\nOh, j’adore cette sensation, comme ça brûle la peau et tisse des pensées maléfiques dans l'esprit…", rewards = "Vous recevrez :\n\n"},
[8420] = {title = "Chaud et piquant", objective = "Apportez un morceau de gangrétoffe à Démonet à Gangrebois.", description = "Peut-être que cela vous semblera bizarre, venant d’un diablotin, mais j’aimerais bien avoir un familier rien qu’à moi. Vraiment. Ce n’est pas juste… Niby m’a moi, et moi, je n’ai personne !\n\nEn fait, il n’est même pas nécessaire qu’il soit vivant. Pour commencer à en fabriquer un, il me faudrait quelque chose comme de la gangrétoffe. Les satyres ici à Gangrebois en ont parfois, il suffirait donc que vous en tuiez assez jusqu'à ce que vous en trouviez. Voilà qui ne devrait pas vous donner trop de mal...", progress = "Vous avez ma gangrétoffe ?", completion = "Chouette ! C'est trop gentil.  Surtout de la part d'un &lt;classe&gt; !\n\n\n\nOh, j’adore cette sensation, comme ça brûle la peau et tisse des pensées maléfiques dans l'esprit…", rewards = "Vous recevrez :\n\n"},
[8421] = {title = "L'anti-étoffe des héros", objective = "Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois.", description = "Maintenant que j’ai la gangrétoffe, je peux enfin commencer à fabriquer *mon* familier.\n\nMais… je crois que je vais avoir besoin d’yeux. Peut-être que vous pourriez arracher un peu de bois pourri aux gens d’Arbrefer, pour que je puisse lui sculpter des yeux adorables. Ils sont au nord, dans le bois d'Arbrefer.\n\nJ’aurai aussi besoin d’essence de Vénéneuse pour lui donner cette nouvelle odeur démoniaque. Les limons corrompus en possèdent, et on en trouve juste à côté, près de Niby et moi.", progress = "Vous avez les matériaux ?", completion = "Ça ira très bien.", rewards = "Vous recevrez :\n\n"},
[8422] = {title = "Les trolls d'un même plumage…", objective = "Apporter 6 Plumes vaudou des trolls du Temple englouti.", description = "Mon familier est pratiquement terminé.  Il ne me manque plus que quelque chose pour le rembourrer.\n\nSeules les plumes vaudous des trolls du Temple englouti conviendront.  Ces trolls s’appellent Balafreur, Mijan, Zolo, Hukku, Zul'lor, et Loro.  Tuez-les tous.\n\nJe sais que ce n’est pas une tâche facile, <nom>,  alors je vous récompenserai en vous donnant un petit quelque chose de Niby… Il n’en a probablement plus besoin, maintenant.", progress = "Vous apportez les plumes ? Ma poupée a besoin d’être rembourrée ?", completion = "Fantastique, maintenant, mon familier est terminé !\n\n&lt;Impsy rembourre rapidement la poupée et la serre dans ses bras d’une façon démoniaque.&gt;\n\nOh, mais ces plumes vaudous ont un étrange effet secondaire…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nMoissonneuse d'âmesEclat abyssalRobe de servitude\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8423] = {title = "Fraternité entre guerriers", objective = "Tuer 7 Sangliers infernaux dans les Terres foudroyées et revenir voir le Héros déchu de la Horde.", description = "<Le Héros vous examine.>\n\nVous êtes un <classe>, cela ne fait pas de doute.  J'aimerais vous confier une tâche honorable, mais je dois d'abord éprouver votre force.\n\nOn dit que Rexxar mesurait le tranchant de ses lames en tuant un sanglier infernal d'un seul coup rapide.  Je vais à présent mesurer votre force en vous demandant d'en tuer.", progress = nil, completion = "Je n'ai pas besoin de preuve pour savoir ce que vous avez accompli, &lt;classe&gt;.  Je vois la détermination gravée sur votre visage.", rewards = "Vous recevrez :\n\n"},
[8424] = {title = "La guerre contre les liges d'ombre", objective = "Tuez les Liges d'ombre dans les Terres foudroyées et revenez voir le Héros déchu de la Horde.", description = "La présence continuelle des liges d’ombre dans les Terres foudroyées est pour moi une terrible source de souffrance.  Leurs rituels et leurs sorts m'infligent des tourments pires que tout ce que j'ai pu connaître de mon vivant.\n\nÀ travers vous, je peux envoyer un message de douleur.  Allez et faites-leur sentir mon courroux.", progress = nil, completion = "Vous avez déjà calmé ma douleur et vous m'avez honoré. Je vous remercie, &lt;classe&gt;.", rewards = "Vous recevrez :\n\n"},
[8425] = {title = "Plumes vaudou", objective = "Apportez les Plumes vaudou des trolls du Temple englouti au Héros déchu de la Horde.", description = "Votre honneur m’a apporté un peu de paix.  Il est juste que je vous offre quelque chose en échange.\n\nMes armes et mon armure étaient splendides quand j’étais en vie, mais elles ne me sont d’aucune utilité aujourd’hui.  Elles seraient bien mieux placées entre vos mains.\n\nRendez-vous au temple englouti et détruisez les trolls gardiens Balafreur, Mijan, Zolo, Hukku, Zul'lor, et Loro.  Ils possèdent des plumes magiques qui peuvent rematérialiser mon corps physique suffisamment longtemps pour que je vous accorde votre récompense.", progress = "Vous êtes déjà de retour ?  Je ne ressens plus le temps de la même façon, peut-être qu'en fait ce fut un long voyage pour vous...", completion = "Enfin je sens à nouveau le froid de l'acier, même si ce n'est que pour un instant.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nVisière de fureurFlacon de diamantEpaulières d'acier-rasoir\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8426] = {title = "La bataille du goulet des Warsong", objective = "Apportez 3 Marques d’honneur du goulet des Warsong à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "La bataille dans le goulet des Warsong contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.\n\nNe la laissez pas faire, <nom> !  Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !", progress = "M’apportez-vous des nouvelles du goulet des Warsong, <nom> ?", completion = "Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l’honneur que vous avez gagné se répande sur toutes nos terres.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +82\n\nVous recevrez :\n\n"},
[8427] = {title = "La bataille du goulet des Warsong", objective = "Apportez 3 Marques d’honneur du goulet des Warsong à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "La bataille dans le goulet des Warsong contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.\n\nNe la laissez pas faire, <nom> !  Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !", progress = "M’apportez-vous des nouvelles du goulet des Warsong, <nom> ?", completion = "Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l’honneur que vous avez gagné se répande sur toutes nos terres.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +138\n\nVous recevrez :\n\n"},
[8428] = {title = "La bataille du goulet des Warsong", objective = "Apportez 3 Marques d’honneur du goulet des Warsong à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "La bataille dans le goulet des Warsong contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.\n\nNe la laissez pas faire, <nom> !  Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !", progress = "Apportez 3 Marques d'honneur du goulet des Warsong à un gerroyeur de la Horde devant les champs de bataille.", completion = "Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l’honneur que vous avez gagné se répande sur toutes nos terres.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +228\n\nVous recevrez :\n\n"},
