[8431] = {title = "La bataille du goulet des Warsong", objective = "La bataille continue de faire rage dans le goulet des Warsong, <nom>.  Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !", description = nil, progress = "La bataille continue de faire rage dans le goulet des Warsong, <nom>.  Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !", completion = "Bien joué, &lt;classe&gt; ! Vous nous avez bien aidés à assurer l’emprise de la Horde sur le goulet des Warsong !", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +82"},
