[8436] = {title = "La conquête du bassin d'Arathi", objective = "Apportez 3 Marques d’honneur du bassin d’Arathi à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "Notre conflit contre l’Alliance est devenu une véritable guerre.  Plus personne n’a besoin de faux prétextes pour aller au combat, ni l’Alliance, ni la Horde.\n\nLa bataille pour le bassin d’Arathi est une guerre économique, ni plus ni moins. Soit l’Alliance obtient ces ressources et les utilise contre nous, soit nous nous en emparons pour soutenir notre effort de guerre.  Aidez les Profanateurs à assurer notre approvisionnement, <nom> !", progress = "Vous êtes revenu avec des nouvelles d’Arathi, <classe> ?", completion = "Protéger nos ressources en Arathi est une tâche importante !  Vous vous êtes bien débrouillé, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +138\n\nVous recevrez :\n\n"},
[8437] = {title = "La conquête du bassin d'Arathi", objective = "Apportez 3 Marques d’honneur du bassin d’Arathi à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "Notre conflit contre l’Alliance est devenu une véritable guerre.  Plus personne n’a besoin de faux prétextes pour aller au combat, ni l’Alliance, ni la Horde.\n\nLa bataille pour le bassin d’Arathi est une guerre économique, ni plus ni moins. Soit l’Alliance obtient ces ressources et les utilise contre nous, soit nous nous en emparons pour soutenir notre effort de guerre.  Aidez les Profanateurs à assurer notre approvisionnement, <nom> !", progress = "Vous êtes revenu avec des nouvelles d’Arathi, <classe> ?", completion = "Protéger nos ressources en Arathi est une tâche importante !  Vous vous êtes bien débrouillé, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +228\n\nVous recevrez :\n\n"},
