[8439] = {title = "La conquête du bassin d'Arathi", objective = "Apportez 3 Marques d’honneur du bassin d’Arathi à l’un des porteguerres de la Horde, devant les champs de bataille.", description = "Notre conflit contre l’Alliance est devenu une véritable guerre.  Plus personne n’a besoin de faux prétextes pour aller au combat, ni l’Alliance, ni la Horde.\n\nLa bataille pour le bassin d’Arathi est une guerre économique, ni plus ni moins. Soit l’Alliance obtient ces ressources et les utilise contre nous, soit nous nous en emparons pour soutenir notre effort de guerre.  Aidez les Profanateurs à assurer notre approvisionnement, <nom> !", progress = "Vous êtes revenu avec des nouvelles d’Arathi, <classe> ?", completion = "Protéger nos ressources en Arathi est une tâche importante !  Vous vous êtes bien débrouillé, &lt;nom&gt;.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +398\n\nVous recevrez :\n\n"},
[8440] = {title = "La conquête du bassin d'Arathi", objective = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", description = nil, progress = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", completion = "Excellent travail, &lt;nom&gt; ! Tant que le bassin d’Arathi reste sous notre contrôle, nos réserves seront bien approvisionnées.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +138"},
[8441] = {title = "La conquête du bassin d'Arathi", objective = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", description = nil, progress = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", completion = "Excellent travail, &lt;nom&gt; ! Tant que le bassin d’Arathi reste sous notre contrôle, nos réserves seront bien approvisionnées.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +228"},
[8442] = {title = "La conquête du bassin d'Arathi", objective = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", description = nil, progress = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", completion = "Excellent travail, &lt;nom&gt; ! Tant que le bassin d’Arathi reste sous notre contrôle, nos réserves seront bien approvisionnées.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +378"},
[8443] = {title = "La conquête du bassin d'Arathi", objective = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", description = nil, progress = "La guerre contre la racaille de l'Alliance exige des ressources, <nom> ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !", completion = "Excellent travail, &lt;nom&gt; ! Tant que le bassin d’Arathi reste sous notre contrôle, nos réserves seront bien approvisionnées.", rewards = "Vous allez être la cible du sort suivant :\n\nPoints d'honneur +398"},
[8446] = {title = "Voilé par le cauchemar", objective = "Trouver quelqu’un capable de comprendre la signification de l’Objet noyé dans les cauchemars.\n\nPeut-être qu’un druide de grande puissance pourra vous aider.", description = "La corruption suinte de cet objet.\n\nIl doit exister un lien entre lui et les dragons qui ont surgi du Rêve. Vous devez trouver quelqu’un qui pourra comprendre la signification de cet objet.  Peut-être que les druides de Reflet-de-Lune ou du Fort cénarien pourront vous aider plus avant.", progress = "Oui, <race> ?", completion = "Je dois ôter la souillure de cet objet.  Cela pourra peut-être m’éclairer sur mes récents échecs pour approfondir ce qui se passe dans le Rêve. Donnez-le-moi.", rewards = "Vous recevrez :\n\n"},
[8447] = {title = "L'éveil des légendes", objective = "Attendre que le gardien Remulos de Reflet-de-Lune ait purifié l’Objet noyé dans les cauchemars.", description = "Les eaux du lac Elune'ara devraient dissoudre les cauchemars qui noient cet objet.  Laissez-moi un moment pour effectuer la purification, <nom>.", progress = nil, completion = "Prenez cet anneau, &lt;nom&gt;. Il a bien servi Malfurion. Il aura maintenant pour vous une autre utilité…", rewards = "Vous recevrez :\n\nChevalière de Malfurion"},
[8458] = {title = "<INUTILISÉ>", objective = "Apporter un Scalp de traqueur des ombres à Maurin Craquossement en Désolace.", description = "Je pense pouvoir trouver ce démon si j'ai les réactifs adéquats.\n\nS'il est effectivement aussi puissant que je le suspecte, je vais avoir besoin de certains objets disponibles sur des créatures mortelles. Mais vous agissez au nom du Chef de guerre, aussi je suis certain que vous accepterez ma quête.\n\nD'abord, je vais devoir briser toutes les protections qu'il aurait contre les visions. Pour cela, j'aurais besoin d'un scalp de satyre. Mais pas de n'importe quel satyre. Il doit provenir d'un traqueur des ombres Fielfurie.\n\nCherchez cette tribu dans les ruines anciennes au nord-est de Désolace.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[8460] = {title = "Allié des Grumegueules", objective = "Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois. Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude.", description = "Les Grumegueules sont les seuls furbolgs à avoir résisté à la corruption. Pourtant, de nombreuses races exécutent maintenant tous les furbolgs, sans distinction, sans même prendre le temps de s'assure qu'ils sont amis ou des ennemis. Pour cette raison, les Grumegueules sont devenus farouches et ne font plus confiance à personne.\n\nVoulez-vous faire vos preuves et faire montre de courage ? Si vous forcez la tribu corrompue des Mort-bois à battre en retraite, nous vous considérerons peut-être comme un être digne de confiance. Vous trouverez les guerriers, les guides et les jardiniers Mort-bois plus bas vers le sud.", progress = nil, completion = "Nous avions beaucoup souffert ces derniers temps. Merci de nous avoir aidé à protéger les Grumegueules. En signe d'amitié, acceptez cet humble cadeau.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGilet de gardien de la terreCeinture du protecteur\n\nVous recevrez également :\n\n"},
[8461] = {title = "Les Mort-bois du nord", objective = "Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules.", description = "Au sud-ouest se trouve un camp de furbolgs Mort-bois. Il empeste la corruption, et je veux que ce soit résolu avant de devenir un problème.\n\nLa tribu Mort-bois est maléfique, mais c’est parce que la corruption a souillé leurs esprits. Leur hostilité n’est pas innée, mais ils ne peuvent plus être aidés. Pour cette raison, j’ai l’immense tristesse de devoir combattre mes propres frères.\n\nS’il vous plaît, <nom>, faites ce qui doit être fait. Epargnez-moi les détails, ils évoquent des images qui me mettent trop mal à l'aise.", progress = "Une fois encore vous avez gagné la confiance des Grumegueules. Je suis sûr que nous pouvons faire quelque chose pour vous en échange de votre loyauté.  Les Grumegueules n'oublient pas leurs alliés, surtout dans des temps aussi difficiles que ceux que nous vivons.", completion = "Je sens que vous avez vaincu. La victoire… un mot creux, quand on pense à ce que vous avez dû faire. Mais quoi qu’il en soit, vous avez fait la preuve de votre utilité, et vous êtes digne de notre confiance.\n\nIl faudra sans doute encore un peu de temps pour que les Grumegueules vous accueillent sans hostilité dans leur repaire. Mais à force de persévérance, leurs soupçons finiront par s’estomper. Tant que vous ne nous trahissez pas, tant que vous ne prenez pas les armes contre nous, nous aurons un terrain d’entente.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières de l'ursaCasque du guide\n\nVous recevrez également :\n\n"},
[8462] = {title = "Parler à Nafien", objective = "Suivre la route principale de Gangrebois vers le nord et parler à Nafien le furbolg. Il monte la garde à côté de l’entrée du repaire des Grumegueules.", description = "Nous autres Grumegueules faisons face à une menace encore plus redoutable. Peut-être serez-vous capable de l’affronter. Vous avez certainement fait la preuve de vos capacités…\n\nUn autre membre de mon espèce monte la garde à l’extérieur de l’entrée du repaire des Grumegueules, assez loin au nord sur cette route. Il s’appelle Nafien. Bien qu’il ait l’air d’un animal farouche et déplaisant, vous n’avez aucune raison de le craindre. Il cherche seulement de l’aide contre les forces maléfiques qui menacent notre foyer.", progress = nil, completion = "Ah… Le vent m’a parlé de ceux et celles qui, sans appartenir à la tribu, cherchent l’alliance des furbolgs Grumegueules. Je vous souhaite la bienvenue, mais je vous avertis : ma tribu réagit mal à la présence d’étrangers.\n\nC’est un temps d’épreuves, et nous ne pouvons accorder notre confiance qu’à ceux qui décident de combattre la corruption à nos côtés… et qui, ensuite, montrent qu’ils ne se payent pas que de mots. Ceux qui en sont incapables devront faire face à notre hostilité s’ils tentent de pénétrer dans notre repaire.", rewards = "Vous recevrez :\n\n"},
[8463] = {title = "Les cristaux de mana instables", objective = "Rapportez 6 Cristaux de mana instables à Aeldon Signesol, sur la Place de l'Épervier.", description = "Un groupe de Déshérités s’est emparé récemment d’une réserve de cristaux de mana instables dans l’un de nos sanctum des arcanes. S’ils ne sont pas manipulés correctement, ces cristaux peuvent exploser avec assez de violence pour faire un trou dans les murs de la ville.\n\nEn soi, le fait qu’ils se fassent tous vaporiser en essayant de ponctionner des sources arcaniques instables ne me dérange pas, <nom>, mais un tel incident serait mauvais pour l’image de mes hommes.\n\nRamenez-moi tous les cristaux volés que vous trouverez, ils seront peut-être encore dans leurs caisses.", progress = "Avez-vous déjà retrouvé les cristaux volés ?", completion = "Excellent travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[8464] = {title = "Les Tombe-hiver s'agitent", objective = "Salfa voudrait que vous tuiez 8 Chamans Tombe-hiver, 8 Protecteurs Tombe-hiver et 8 Ursas Tombe-hiver. Salfa se trouve juste à l'extérieur de l'entrée du repaire des Grumegueules, au Berceau-de-l'hiver.", description = "Les Grumegueules ont tendance à rester entre eux, <nom>. Nous laissons passer ceux en qui nous avons toute confiance, mais nous essayons d'éviter les autres tribus de furbolgs, si cela est possible.\n\nDernièrement, j'ai remarqué que la tribu Tombe-hiver montrait des signes d'hostilité à notre égard. Ils semblent être dans un étrange état de rage, rendus furieux par tout ce qui les effraie et qu'ils ne comprennent pas.\n\nJe me vois dans l’obligation de vous demander d’assurer notre sécurité en réduisant leur nombre. Vous les trouverez au village des Tombe-hiver, loin à l’est d’ici.", progress = nil, completion = "Merci pour ce que vous avez fait, même si c'était une triste tâche. Acceptez cette babiole en gage de notre reconnaissance.\n\nS'il vous plaît, continuez à nous aider, &lt;nom&gt;. Nous n'avons que peu d'alliés auxquels demander de l'aide et sans vous, nous ne parviendrons pas à venir à bout de tout ce qui nous menace.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de gardien de la terreGants du guideHaubergeon du protecteurEtreinte d'ursa\n\nVous recevrez également :\n\n"},
[8465] = {title = "Parler à Salfa", objective = "Traverser le repaire des Grumegueules et sortir au Berceau-de-l’Hiver. Parlez à Salfa, qui monte la garde à l’extérieur du repaire des Grumegueules.", description = "Le risque de corruption ne vient pas seulement des furbolgs Mort-bois au sud, mais aussi de l’est et des furbolgs Tombe-Hiver du Berceau-de-l’Hiver. Si vous voulez continuer à nous aider, parlez à Salfa de l’autre côté du repaire, près de l’entrée de Berceau-de-l’Hiver. Pour y arriver, suivez le sentier de gauche.\n\nFaites attention, si les miens vous considèrent comme hostile, ou pire s’ils vous détestent, ils vous attaqueront. Allez aussi vite que possible et évitez les conflits. Tuer un Grumegueule, même si c’est juste pour défendre, ne ferait qu’empirer les choses.", progress = nil, completion = "Salutations, &lt;classe&gt;. Je me tiens ici à la fois pour défendre les Grumegueules et pour leur servir de porte-parole.\n\nNos cousins Tombe-hiver qui vivent dans ces terres glacées sont victimes de la même influence corruptrice que les furbolgs de Gangrebois. Si vous venez en ces lieux pour proposer votre aide aux Grumegueules, nous sommes prêts à l’accepter.", rewards = "Vous recevrez :\n\n"},
[8466] = {title = "Des plumes pour Grifleur", objective = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", description = nil, progress = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", completion = "Bien joué, &lt;nom&gt; !  Je ferai en sorte que vos actions soient connues par mon peuple.\n\nN'oubliez pas de m'apporter toutes les plumes que vous trouverez.  Je continuerai à en accepter aussi longtemps que nécessaire.", rewards = nil},
[8467] = {title = "Des plumes pour Nafien", objective = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", description = nil, progress = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", completion = "Bien joué, &lt;nom&gt; !  Je ferai en sorte que vos actions soient connues par mon peuple.\n\nN'oubliez pas de m'apporter toutes les plumes que vous trouverez.  Je continuerai à en accepter aussi longtemps que nécessaire.", rewards = nil},
[8468] = {title = "ON RECHERCHE : Thaelis l’Affameur", objective = "Apportez la Tête de Thaelis au Sergent Kan’ren sur la Place de l'Épervier, dans le Bois des chants éternels.", description = "La cité de Lune-d’Argent offre par la présente une récompense pour la tête de Thaelis l’Affameur, le fameux chef de bande des Déshérités. Il s’est rendu coupable d’une multitude de crimes contre la population, dont le meurtre de deux gardes de la cité.\n\nPour toucher la récompense, présentez-vous au sergent Kan’ren.", progress = "Avez-vous quelque chose pour moi ?", completion = "Son destin a enfin rattrapé cette vermine de Thaelis. Bon travail, &lt;nom&gt;. Les Déshérités devraient nous laisser tranquilles pour un moment.", rewards = "Vous recevrez :\n\n"},
[8469] = {title = "Des perles pour Salfa", objective = "Vous avez certainement gagné ma confiance, <nom>, mais vous devez continuer à faire vos preuves devant ma tribu, fort soupçonneuse. Voici ce que vous pouvez faire pour qu’ils vous considèrent plus favorablement.\n\nLes Tombe-hiver sont célèbres pour les perles qu’ils portent pour se protéger des mauvais esprits. De toute évidence, elles n’ont pas joué leur rôle, car les Tombe-hiver sont eux-mêmes devenus des agents de la corruption.  Apportez-moi les perles d’esprit que vous aurez prises sur les furbolgs Tombe-hiver que vous aurez vaincus. Pour chaque série de cinq perles que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules", description = nil, progress = "Vous avez certainement gagné ma confiance, <nom>, mais vous devez continuer à faire vos preuves devant ma tribu, fort soupçonneuse. Voici ce que vous pouvez faire pour qu’ils vous considèrent plus favorablement.\n\nLes Tombe-hiver sont célèbres pour les perles qu’ils portent pour se protéger des mauvais esprits. De toute évidence, elles n’ont pas joué leur rôle, car les Tombe-hiver sont eux-mêmes devenus des agents de la corruption.  Apportez-moi les perles d’esprit que vous aurez prises sur les furbolgs Tombe-hiver que vous aurez vaincus. Pour chaque série de cinq perles que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules", completion = "Vous faites une fois encore la preuve de votre honneur! Je veillerai à ce que vos exploits soient connus parmi les miens.\n\nSi vous trouvez d’autres perles Tombe-hiver, n’oubliez pas de me les ramener. À chaque fois que vous m’en procurerez une série, je parlerai de vous à la tribu.", rewards = nil},
[8470] = {title = "Le totem rituel des Mort-bois", objective = "Amener le Totem rituel mort-bois à l’intérieur du repaire des Grumegueules et voir si l’un des furbolgs qui s’y trouvent est capable d’en faire quelque chose. Les Grumegueules ne vous adresseront pas la parole s’ils ne sont pas Neutres à votre égard, au minimum.", description = "Vous avez trouvé l’un des totems rituels des Mort-bois. Il semble assez banal à première vue, mais une impression de désespoir presque palpable en émane. Si un seul objet suffisait à résumer la corruption dont souffrent les Mort-bois, ce serait lui.\n\nL’un des furbolgs du repaire des Grumegueules pourrait lui trouver une utilité… à condition qu’ils vous fassent assez confiance pour vous parler.", progress = "Oui <classe>, que pouvons-nous faire pour vous ? Vous marchez parmi nous en paix, mais quelque chose ne va pas. Je sens quelque chose… quelque chose de troublant.", completion = "Ce totem… c’est l’un de ceux des Mort-bois, mais il empeste la pourriture. J’ignore ce qui a poussé nos frères à se retourner contre nous, mais c’est certainement présent dans cet objet.\n\nVous avez eu raison de nous l’amener, &lt;nom&gt;. Peut-être, à force d’études et rituels, pourrons-nous découvrir ce qui pollue l’esprit de nos frères. Merci, mon ami. Acceptez ces dons en échange de votre trouvaille.", rewards = "Vous recevrez :\n\nPotion de soins majeurePotion de mana majeure"},
[8471] = {title = "Le totem rituel des Tombe-hiver", objective = "Emportez le totem rituel Tombe-hiver au Repaire des Grumegueules et voyez si l’un des furbolgs lui trouve une utilisation. Les Grumegueules ne vous parleront pas si vous n’avez pas à leur égard une réputation Neutre au minimum.", description = "Vous avez trouvé l’un des totems rituels des furbolgs Tombe-hiver. Le totem lui-même n’a pas une construction bien définie, mais il semble émaner de lui un sentiment de terreur et de désespoir presque tangible. Si un grand nombre de furbolgs Tombe-hiver en porte, cela explique beaucoup de choses sur leur condition actuelle.\n\nL’un des furbolgs du Repaire des Grumegueules pourrait se servir d’un tel objet… Enfin, si vous avez suffisamment gagné leur confiance pour qu’ils acceptent de vous parler.", progress = "<classe>, vous venez vers nous d’une manière pacifique, mais je sens que vous êtes ici pour un sujet grave et important… Autant pour votre peuple, <race>, que pour les furbolgs.  Que venez-vous nous dire ?", completion = "Cette chose… Elle a la forme d’un totem rituel Tombe-hiver, mais elle a été corrompue par des forces que je ne parviens même pas à comprendre. La souillure qui a tourné les Tombe-hiver contre nous est sûrement présente dans cet objet.\n\nLa sagesse divine vous a conduit tous deux ici, &lt;nom&gt;. Nous allons étudier cet objet très attentivement ; peut-être qu’un jour, les Tombe-hiver perdront leur rage à notre égard.\n\nMerci, mon ami. Acceptez ces offrandes en remerciement de votre bienveillance.", rewards = "Vous recevrez :\n\nPotion de soins majeurePotion de mana majeure"},
[8472] = {title = "Un mauvais fonctionnement", objective = "Récupérez 6 Noyaux arcaniques sur les Patrouilleurs des arcanes qui circulent dans les ruines de Lune-d’Argent et rapportez-les au magistère Jaronis, sur la Place de l'Épervier dans le bois des Chants éternels.", description = "Les patrouilleurs des arcanes fabriqués par nos ancêtres pour protéger la ville sont devenus dangereux à cause du manque d’entretien. Ils ne nous reconnaissent plus comme leurs maîtres et nous attaquent à vue !\n\nBien qu’ils aient été créés il y a de nombreuses années, les noyaux arcaniques qui les alimentent sont encore très utiles et précieux. Je veux que vous alliez récupérer ces noyaux et que vous me les rameniez, afin que je puisse les recycler là où ils nous serviront. Vous trouverez les patrouilleurs dans les quartiers en ruine de Lune-d’Argent, au nord-ouest.", progress = "Êtes-vous déjà parvenu à récupérer les noyaux arcaniques, <nom> ?", completion = "Vous avez fait du bon travail, &lt;nom&gt;. Tant que nos sanctum des arcanes ne fonctionnent pas à plein régime, ces batteries nous apporteront un soutien bienvenu.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23367Objet #24241Objet #27552Objet #131237\n\nVous recevrez également :\n\n"},
[8473] = {title = "Une triste tâche", objective = "Tuez 10 Gardes verts flétris au Bosquet incendié, puis revenez voir Larianna Ruissevent à l'intérieur de la tour, juste au nord-ouest du Bosquet Incendié dans le Bois des Chants éternels.", description = "Ces temps sont difficiles, <nom>. Décider de mettre le feu aux bois qui longent les terres Fantômes pour éviter que le Fléau ne s’étende a été très pénible.\n\nLes tréants, qui ont été nos amis pendant des années, tentent de faire repousser la forêt le long du Bosquet incendié.\n\nNous ne sommes pas parvenus à convaincre nos anciens alliés d’interrompre leurs efforts. C’est une tâche particulièrement douloureuse, <classe>, mais il va falloir que vous les arrêtiez par la force. C’est le seul moyen qui nous reste.", progress = nil, completion = "C’est donc fait. Maudits soient ces temps qui nous poussent à prendre de pareilles mesures… et maudit soit notre ennemi, le Fléau !\n\nRetenez bien ceci, &lt;nom&gt;. Nos terres doivent être protégées quel qu’en soit le prix. Nous triompherons !", rewards = "Vous recevrez :\n\n"},
[8474] = {title = "Le pendentif du vieux Blanchécorce", objective = "Trouvez la personne qui a fabriqué le Pendentif du vieux Blanchécorce. Elle pourra peut-être vous parler de cet objet.", description = "Les initiales L.R. sont gravées sur le pendentif. Ces lettres pourront peut-être vous aider à trouver la personne qui l’a fabriqué.", progress = "Avez-vous quelque chose à me montrer ?", completion = "Ce… ce pendentif. Je l’ai donné au vieux Blanchécorce lorsque son peuple nous a aidés à rebâtir notre village.\n\nJe suppose que cela veut dire qu’il…\n\n&lt;L’elfe de sang se racle la gorge et essaye de retrouver son sang-froid.&gt;\n\nMerci de me l’avoir apporté, &lt;nom&gt;. J'ai quelque chose à vous demander.", rewards = "Vous recevrez :\n\n"},
[8475] = {title = "La Malebrèche", objective = "Tuez 8 Pilleurs Ossepeste, puis présentez-vous au forestier Jaela à la Malebrèche dans le bois des Chants éternels.", description = "La bande de sol souillé qui coupe les Chants éternels en deux est un rappel permanent du jour où Arthas a conduit le Fléau jusqu’à notre ville bien-aimée.\n\nCette horreur ne se contente pas de défigurer le paysage. Aujourd’hui encore, elle attire le Fléau des terres Fantômes à Lune-d’Argent.\n\nAllez prêter main-forte à mes hommes, <nom>. Tuez les Morts-vivants décérébrés qui arpentent la Malebrèche.", progress = "Vous voilà de retour, <nom>. Avez-vous eu le temps de combattre les Morts-vivants le long de la Malebrèche ?", completion = "Nous ne nous attendons pas à ce que le Fléau renonce à ses attaques dans un avenir proche, mais nous savons apprécier toute aide que nous recevons pour la défense de la brèche.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23375Objet #23376Objet #23377Objet #131238\n\nVous recevrez également :\n\n"},
[8476] = {title = "L'empiètement des Amani", objective = "Le lieutenant Coursaurore de la retraite des Pérégrins du bois des Chants éternels veut que vous tuiez 5 Berserkers amani et 5 Lanceurs de haches amani.", description = "Notre domaine n’est pas aussi étendu que les vastes royaumes des Orcs et des Humains. Vous pouvez embrasser d’un seul coup d’œil tout ce qui reste de nos terres en Azeroth, <nom>.\n\nEn attendant que nous puissions atteindre l’Outreterre et trouver un nouveau foyer, nous devons défendre à tout prix ce maigre territoire.\n\nHélas, nos voisins primitifs du sud-est, les Trolls Amani, s’imaginent qu’ils en sont propriétaires. Nous ne pouvons plus tolérer leurs raids quotidiens. Rendez-vous à Zeb’Watha et Tor'Watha, leurs villages, et donnez-leur une leçon.", progress = nil, completion = "C’est du bon travail, &lt;nom&gt;. Avec plus de gens comme vous, nous rendrons bientôt leur gloire passée à nos terres.", rewards = "Vous recevrez :\n\n"},
[8477] = {title = "Le marteau du Taille-épieux", objective = "Fouillez Tor'Watha au sud-est de la retraite des Pérégrins à la recherche du Taille-épieux Otembe, puis apportez le Marteau d’Otembe à Arathel Solforge, à la retraite des Pérégrins du bois des Chants éternels.", description = "Les Amani et les sin’dorei ont derrière eux une longue histoire faite d’aversion et d’hostilités, <nom>, mais cela ne m’empêche pas d’apprécier le travail d’un autre artisan.\n\nJ’ai eu l’occasion de voir les armes des Amani, et je dois admettre que le métal a été expertement travaillé. On prétend que le taille-épieux Otembe possède un marteau magique si léger et si bien équilibré qu’il lui permet de travailler très vite et très efficacement.\n\nSi vous me l’apportez, je m’en servirai pour vous fabriquer une arme.", progress = "M’avez-vous rapporté le marteau d’Otembe, <nom> ?", completion = "Les rumeurs disaient vrai, &lt;nom&gt;. Ce marteau est à la fois léger et puissant. Il me permettra d’achever plusieurs projets. Et bien sûr, vous serez le premier à choisir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #22958Objet #22959Objet #22963\n\nVous recevrez également :\n\n"},
[8478] = {title = "Le choix des armes", objective = "Vous recevrez :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8479] = {title = "Zul'Marosh", objective = "Ven'jashi, le prisonnier troll de Tor'Watha, veut que vous lui remettiez la Tête du chef Zul’Marosh. Le chef Zul'Marosh se trouve à Zeb'Watha, de l'autre côté du lac Elrendar.", description = "Approchez, ayez pas peur, Ven’jashi, il ne va pas vous faire de mal.\n\nNous les Sombrelances, on est comme vous, ennemis mortels des Amani. Leur chef Zul’Marosh, mauvais Troll. Il me poisonne et me laissé dans cette cage pour mourir.\n\nJ’ai pas peur de mourir, <mon gars/ma p’tite>. Je regarde la mort dans les yeux, elle me fait rire.\n\nMais je ne vais pas mourir en paix, <mon gars/ma p’tite>. Pas si Zul’Marosh, il est pas mort aussi. Cherchez-le de l'aut' côté du lac à Zeb'Watha. Je retiens le poison tant que vous m’apportez pas sa sale tête. Après, je meurs en paix.", progress = "Vous apporter à moi tête de Zul’Marosh ?", completion = "Ouais, l’ami. Zul’Marosh, il l’a cherché. Il a brûlé le village de Ven'jashi. Je tue beaucoup d’Amani avant qu’ils me mettent en cage. Je cache quelque chose dans le sable. Ça mon cadeau pour vous.\n\nAh… ah, le poison… lui s'étendre. Se r'poser maintenant...", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #22969Objet #22971\n\nVous recevrez également :\n\n"},
[8480] = {title = "Les armes perdues", objective = "Rapporter 8 Armes sin’dorei à Velendris Blancmatin, dans le bois des Chants éternels.", description = "Les Déshérités se font de plus en plus audacieux, <nom>. Ils ont réussi à se coordonner assez pour attaquer le mouillage des Voiles du soleil.\n\nC’est d’autant plus embarrassant que lorsqu’ils ont attaqué, nous avons laissé la plupart de nos armes derrière nous. Récupérez nos armes, que nous puissions montrer à cette racaille qui est le patron.", progress = "Avez-vous récupéré les armes perdues ?", completion = "Excellent travail, &lt;nom&gt;. Nous allons montrer aux Déshérités de quel bois nous sommes faits !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #22956Objet #22957Objet #133696\n\nVous recevrez également :\n\n"},
[8481] = {title = "La racine du mal", objective = "Plantez la Torche d'invocation de démon à l’entrée de la caverne du grand chef Tombe-hiver, dans le village des furbolgs Tombe-hiver. Triomphez du démon et récupérez l’Essence de Xandivious pour Gorn le Borgne du Repaire des Grumegueules.", description = "Grâce à vous, <nom>, nous avons imaginé un moyen de forcer le démon corrupteur qui se trouve à la racine de la corruption des Tombe-hiver à se montrer.\n\nPrenez cette torche et amenez-la à l’entrée de la caverne personnelle du grand chef Tombe-hiver, puis plantez-la dans le sol. Cela forcera le démon à venir enquêter. A ce moment-là, vous pourrez le détruire avec l’aide de vos alliés. A l’aide de l’essence du démon mort, nous pourrons entamer la lente guérison de la tribu Tombe-hiver… et sauver le repaire des Grumegueules.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nDéfenseur des Grumegueules"},
[8482] = {title = "Les documents compromettants", objective = "Remettez les Documents compromettants à Aeldon Signesol sur la Place de l'Épervier, dans le bois des Chants éternels.", description = "Les documents contiennent des plans détaillés de différents bâtiments stratégiques du bois des Chants éternels. On y trouve également un croquis assez détaillé d’un sanctum des arcanes. Les abondantes notes qui les accompagnent sont dans une langue que vous ne reconnaissez pas.\n\nTout cela appartenait à un espion darnassien. Tout remettre au capitaine de la garde, Aeldon Signesol, vous semble une bonne idée.", progress = "Vous avez quelque chose pour moi ? Voyons cela.", completion = "Vous avez vraiment trouvé cela sur un elfe de la nuit ? Pourtant, c’est écrit dans la langue des nains…\n\nD’après ce que j’arrive à en comprendre, la personne qui a écrit ça n’a pas causé la défaillance, mais a été envoyée pour espionner ses conséquences. Ils disent que nos tentatives sont imprudentes et dangereuses... mais qui ?\n\nBien sûr ! Cet envoyé de Forgefer ! Quelle folie d’avoir fait confiance à quelqu’un de l’Alliance !", rewards = "Vous recevrez :\n\n"},
[8483] = {title = "L'espion des nains", objective = "Aeldon Signesol, sur la Place de l'Épervier du Bois des Chants éternels, veut la Tête du prospecteur Garde-enclume.", description = "Écoutez, <nom>. La situation est très délicate. Même si nous avons identifié l’espion, nous ne pouvons pas le tuer ouvertement. Impossible également de le capturer, le risque d’évasion est trop grand.\n\nAllez au sanctum septentrional, trouvez le prospecteur Garde-enclume et tuez-le. Procédez discrètement. Nous avons accueilli un espion en notre sein, mais il n’est pas question que cela se sache.\n\nRamenez-moi sa tête comme preuve. Forgefer devra apprendre à ne pas se mêler des affaires des sin’dorei.", progress = "Avez-vous réglé le sort de l’intrus ?", completion = "Ainsi donc, c’est fait. Excellent travail !\n\nL’information a été transmise au général des forestiers et croyez-moi, les nains vont payer fort cher leur trahison.\n\nVous avez rendu aujourd’hui un grand service à votre peuple, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23372Objet #23373Objet #133695\n\nVous recevrez également :\n\n"},
[8484] = {title = "Négocier la paix", objective = "Apporter l’Offrande de paix grumegueule au roi Magni Bronzebeard, à Ironforge.", description = "Vos exploits sont plus qu’héroïques, <nom>. Si le reste de votre peuple est à votre image, alors, nous sommes prêts à faire la paix avec lui, même si cela nous impose des efforts.\n\nS’il vous plaît, portez cette offre au roi nain qui vit dans une montagne de fer – dans une ville qui, je crois, s’appelle Ironforge. Autrefois, il a tenté de nous contacter au nom de son Alliance. Reconnaître votre rôle-clé dans la négociation de cette paix est la moindre des choses.", progress = "Vous êtes le bienvenu dans mon domaine, <classe>. Pour les héros de votre trempe, Ironforge sera toujours un foyer. Bien. Que voulez-vous me dire ?", completion = "Voilà un événement aussi heureux qu’important. Si nous pouvions négocier une paix durable avec ces créatures, cela nous donnerait l’avantage dans les affaires de Kalimdor… un avantage que les elfes de la nuit n’ont pas su obtenir. Je vais avertir immédiatement les autres dirigeants de l’Alliance, et nous dépêcherons d’autres diplomates.\n\nQuant à vous, &lt;nom&gt;… Vous avez fait preuve de courage, à la fois dans la diplomatie et dans l’action. Je vous remercie, au nom de toute l’Alliance.", rewards = "Vous allez être la cible du sort suivant :\n\nRéputation auprès de l'Alliance\n\nVous recevrez :\n\n"},
[8485] = {title = "Négocier la paix", objective = "Apporter l’Offrande de paix grumegueule à Thrall, à Orgrimmar.", description = "Vos exploits sont plus qu’héroïques, <nom>. Si le reste de votre peuple est à votre image, alors, nous sommes prêts à faire la paix avec lui, même si cela nous impose des efforts.\n\nS’il vous plaît, portez cette offre au chef de guerre orc qui vit au pays de Durotar – je crois que vous appelez sa ville Orgrimmar. Autrefois, il a tenté de nous contacter au nom de la Horde. Reconnaître votre rôle-clé dans la négociation de cette paix est la moindre des choses.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nRéputation auprès de la Horde\n\nVous recevrez :\n\n"},
[8486] = {title = "L'instabilité arcanique", objective = "La telluriste Velania veut que vous tuiez 5 Âmes en peine de mana et 5 Traqueurs de mana.", description = "Il était temps que cet idiot borné de Caidanis nous envoie quelqu’un.\n\nJ’avais dit qu’il ne fallait surtout pas augmenter la charge du sanctum occidental ! Maintenant, l’un de nos convertisseurs d’énergie est détruit, et un flot d’âmes en peine arcaniques sort du sanctum ! Avant que nous puissions réparer, il va falloir s’occuper de ces créatures. Faites vite !", progress = nil, completion = "Merci, &lt;nom&gt;. Maintenant que les âmes en peine sont sous contrôle, nous pouvons envoyer quelqu’un évaluer les dégâts. Espérons que ce n’est rien de permanent.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23370Objet #23371\n\nVous recevrez également :\n\n"},
[8487] = {title = "Le sol contaminé", objective = "L'apprentie Mirveda au Sanctum oriental dans le bois des Chants éternels veut que vous récupériez 8 Échantillons de terre contaminée.", description = "Ceci était un sanctum des arcanes entièrement fonctionnel avant qu'Arthas et son armée d'abominations du Fléau ne décident de le dévaster en se dirigeant vers Lune-d’Argent.\n\nIl nous est à présent aussi peu utile que n'importe quel endroit de la Malebrèche. La terre est contaminée, elle attire les Morts-vivants et l'énergie des lignes telluriques est complètement perturbée.\n\nCe que je veux savoir, <nom>, c'est si la contamination est réversible ou pas. Je veux que vous collectiez des échantillons de terre de cette zone afin que je puisse les étudier. Peut-être qu'avec le temps, nous pourrons ramener les choses à la normale.", progress = "Avez-vous fini de recueillir les échantillons que j'ai demandés, <nom> ?", completion = "Excellent. Je vais lancer un enchantement d'accroissement sur les échantillons afin de pouvoir analyser plus précisément la contamination du sol.", rewards = "Vous recevrez :\n\n"},
[8488] = {title = "Des résultats inattendus", objective = "Parlez à l’Apprentie Mirveda, puis protégez-la de l’embuscade du Fléau.", description = "Quelque chose ne va pas, <nom>. Je sens la présence du Fléau. Préparez-vous à l'affronter !", progress = "C'est terminé ? Est-ce qu'ils sont tous partis ?", completion = "Mes tentatives sont sans espoir, &lt;nom&gt;. La nature même du sol a été altérée... la contamination est irréversible. Merci pour votre aide. J'ai besoin de vous demander un dernier service.", rewards = "Vous recevrez :\n\n"},
[8489] = {title = "Un convertisseur intact", objective = "Apportez le Convertisseur arcanique intact à la telluriste Velania.Cet objet semble être l'un des convertisseurs arcaniques dont la telluriste Velania a parlé. Il n'a pas été endommagé par le feu, peut-être qu'il pourrait lui être utile.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Cet objet semble être l'un des convertisseurs arcaniques dont la telluriste Velania a parlé. Il n'a pas été endommagé par le feu, peut-être qu'il pourrait lui être utile.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8490] = {title = "Renforcer nos défenses", objective = "Placez le Cristal infusé contre la Pierre runique de l'est et protégez-le du Fléau pendant 1 minute. Rapportez le Cristal infusé au garderune Deryan dans le bois des Chants éternels pour recevoir votre récompense.", description = "D’antiques pierres runiques activaient autrefois une barrière protectrice le long de la frontière des Chants éternels. Nombre d’entre elles ont été détruites durant l’attaque d’Arthas ; d’autres ont été dérobées.\n\nSur les trois qui restent, celle-ci est la seule à avoir conservé ses pouvoirs. La pierre runique située à l’est est cependant peut-être récupérable.\n\nPrenez ce cristal et transférez son énergie à la pierre runique de l’est. Le transfert ne devrait pas prendre plus d’une minute. Restez tout de même sur vos gardes, car cela va attirer les créatures du Fléau aux alentours. Ne les laissez pas le détruire !", progress = "Avez-vous réussi à activer la pierre runique, <nom> ?", completion = "Excellent. Les défenses devraient contenir le Fléau un peu plus longtemps. Merci pour votre aide, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[8491] = {title = "Récupérer des fourrures", objective = "Velan Brillechêne à Brise-Clémente dans le bois des Chants éternels veut que vous lui apportiez 6 Fourrures de Preste-patte.", description = "Les Preste-pattes qui peuplent la région sont renommés pour la qualité de leur fourrure. Nous avons même vu des racailles d'Elfes de la nuit voyager jusqu'ici rien que pour braconner !\n\nNos escarmouches avec les Amani pèsent sur nos réserves d'équipement et nos forestiers n'ont pas beaucoup de temps pour chasser. Si vous vouliez bien nous aider à collecter des fourrures de preste-pattes, j'aurais le plaisir de vous récompenser avec une pièce d'armure artisanale. Au nord d’ici, les bois regorgent de traqueurs Preste-pattes.", progress = "Vous êtes de retour. Avez-vous les fourrures ?", completion = "Elles feront parfaitement l'affaire, &lt;nom&gt;. Prenez cette pièce d'armure en récompense. Je pourrai en faire plus avec les fourrures que vous m'avez apportées.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #22951Objet #22952Objet #22953Objet #131239\n\nVous recevrez également :\n\n"},
[8492] = {title = "L'Alliance a besoin de barres de cuivre !", objective = "Ramener 20 barres de cuivre au sergent Stonebrow dans la Garde militaire d'Ironforge.", description = "Holà, <classe>, vous semblez assez costaud pour contribuer à l’effort de guerre ! Nous avons besoin de toute l’aide disponible pour rassembler les matériaux dont nous aurons besoin lors de la guerre d’Ahn’Qiraj, et c’est votre jour de chance !\n\nJe rassemble des barres de cuivre par piles de vingt. C’est pour la bonne cause, vous ne pensez pas ? Pensez-vous que vous pourrez aider l’Alliance ?", progress = "Avez-vous déjà réuni les vingt barres de cuivre, soldat ?", completion = "Vous avez réussi, mon gars ! Nous allons mettre ces barres de cuivre sur notre pile et en faire bon usage pour la confection de notre matériel de guerre sans plus attendre. Ce sont les efforts de gens comme vous qui me rendent fier de servir l'Alliance. Bon travail, soldat !\n\nEt si par hasard, vous trouvez d’autres barres de cuivre sur votre chemin, faites-les-moi parvenir.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8493] = {title = "L'Alliance a besoin de plus de barres de cuivre !", objective = "Ramener 20 barres de cuivre au sergent Stonebrow à l’aérodrome de Dun Morogh.", description = "Encore vous, <classe> ? Remarquable ! Nous avons besoin d’encore plus de barres de cuivre  si nous voulons alimenter correctement l’effort de guerre d'Ahn'Qiraj. Voulez-vous nous aider ?", progress = "Déjà de retour, <classe> ? Extraordinaire ! Vos barres de cuivre nous rendront de grands services dans nos préparatifs. Je sais, par exemple, que le cuivre servira dans la fabrication des chars à vapeur et, si nous avons le temps, dans celle d’une nouvelle flottille de gyrocoptères.\n\nQuoi que vous puissiez penser en voyant ces piles de barres de cuivre, il nous en faudrait davantage, si vous pouviez en fournir pour l’effort de guerre d’Ahn’Qiraj. Acceptez-vous de nous aider ?", completion = "Très bon travail ! Vous procurer tout ce cuivre a dû être une véritable aventure. Sauf si vous l’avez acheté à l’hôtel des ventes, bien sûr. Moi, cela m’indiffère. De toute façon, vous serez félicitée  pour votre contribution à l’effort de guerre, &lt;classe&gt;. Et si vous avez d’autres barres de cuivre, vous savez où me trouver.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8494] = {title = "L'Alliance a besoin de barres de fer !", objective = "Ramener 20 barres de fer au caporal Carnes dans la Garde militaire d'Ironforge.", description = "Salut, <l’endimanché/l’endimanchée>. Dites donc, vous en mettez plein les yeux ! Bon, au cas où, à force de courir l’aventure, vous ne l’auriez pas entendu dire, je vous signale que l’Alliance se prépare à une guerre à Ahn’Qiraj. Il lui faut des barres de fer. Des montagnes de barres de fer. Ramenez-les-moi par paquets de vingt. Nous pouvons compter sur vous, <classe> ?", progress = "Si vous avez les vingt barres de fer, je ne veux pas savoir où vous les avez cachées !", completion = "Mais mais mais… c’est &lt;nom&gt; ! Vous vous en êtes $gsorti sortie;, on dirait. Faudra que je vous garde à l’œil. Ça me fait mal de le dire, mais merci pour vos efforts. L’Alliance ne les oubliera pas. Moi non plus, du reste. Bon, et maintenant, bougez-vous de là et allez voir ce que vous pouvez récolter d’autre.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8495] = {title = "L'Alliance a besoin de plus de barres de fer !", objective = "Ramener 20 barres de fer au caporal Carnes à l’aérodrome de Dun Morogh.", description = "Déjà de retour ? Mais arrêtez donc de m’obliger à revoir ma mauvaise opinion de vous, <classe>, j’ai l’impression de devenir un grand sentimental. Donc, comme vous pouvez le voir, nous n’avons pas encore assez de barres de fer pour les armes, les armures, les chars à vapeur et tous les machins que nous devons fabriquer pour la chasse aux cafards. Vous pensez que vous avez assez de tripes pour me rapporter vingt autres barres de fer entre deux voyages à Zul’Gurub, ou quel que soit l’endroit où les gamins comme vous traînent leurs guêtres, ces temps-ci ?", progress = "Déjà de retour ? Mais arrêtez donc de m’obliger à revoir ma mauvaise opinion de vous, <classe>, j’ai l’impression de devenir un grand sentimental. Donc, comme vous pouvez le voir, nous n’avons pas encore assez de barres de fer pour les armes, les armures, les chars à vapeur et tous les machins que nous devons fabriquer pour la chasse aux cafards. Vous pensez que vous avez assez de tripes pour me rapporter vingt autres barres de fer entre deux voyages à Zul’Gurub, ou quel que soit l’endroit où les gamins comme vous traînent leurs guêtres, ces temps-ci ?", completion = "Il doit faire froid, aujourd’hui, dans les Steppes ardentes. Hé, regardez, c’est &lt;nom&gt;, et il m’a apporté un cadeau. Vingt barres de fer ! J’en rêvais depuis si longtemps.\n\nBon, trêve de plaisanteries, merci, &lt;nom&gt;. Vous faites honneur à votre nom et à l’Alliance. Maintenant, retournez là-bas et rapportez-moi d’autres matériaux pour l’effort de guerre.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8496] = {title = "Des bandages pour la campagne", objective = "Apportez 30 Bandages épais en étoffe runique, 30 Bandages épais en soie et 30 Bandages épais en tisse-mage à l’imploratrice céleste Proudhorn. Vous devez aussi apporter le Briefing logistique X pour terminer cette quête.", description = "Après les dernières escarmouches, notre réserve de bandages est dangereusement basse. Procurez-vous le nécessaire et livrez-le à l’imploratrice céleste Proudhorn au Fort cénarien.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Juste à temps. Ces bandages sauveront des vies, &lt;nom&gt;. J’apprécie votre travail. Voici votre prochaine mission…", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8497] = {title = "Survivre dans le désert", objective = "Ramener 4 Globes d’eau, 4 Anti-venins puissants et 4 Boulettes fumées du désert à Calandrath, à l’auberge du Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique I pour terminer cette quête.", description = "L’afflux de nouvelles recrues au Fort cénarien nous pose un problème. Comment les garder en vie dans le désert ? Les volontaires inexpérimentés risquent la déshydratation et l’empoisonnement – le sable grouille de créatures venimeuses. Rassemblez les matériaux nécessaires à la constitution de paquetages de survie dans le désert, et remettez-les à Calandrath au Fort cénarien.", progress = "Avez-vous quelque chose pour moi ?", completion = "Excellent ! Nous en avions besoin, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8498] = {title = "Les ordres de batailles du Crépuscule", objective = "Vous procurer les Ordres de bataille du Crépuscule et les ramener au commandant Mar’alith, au Fort cénarien de Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique X.", description = "D’après nos éclaireurs, les chefs du Marteau du crépuscule envoient de nouveaux ordres de bataille. Ils sont distribués par des Prophètes du crépuscule accompagnés d’une forte escorte. Interceptez ces ordres et ramenez-les au commandant Mar’alith.", progress = "Vous avez quelque chose pour moi ?", completion = "Excellent. Nous devons être en mesure d’anticiper le prochain mouvement de l’ennemi. Grâce à cette information, nous pourrons prévoir les attaques du Marteau du crépuscule.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique"},
[8499] = {title = "L'Alliance a besoin de barres de thorium !", objective = "Ramener 20 Barres de thorium à dame Twinbraid dans la Garde militaire d'Ironforge.", description = "C’est très sympathique de votre part de vous enquérir des besoins de l’Alliance. En plus de toutes les collectes qui ont déjà lieu, nous avons besoin d’une grande quantité de barres de thorium, et j’ai été chargée de les rassembler. Le thorium servira à la création de nombreuses choses pour la guerre, et avant tout à la création d’un bataillon de chars à vapeur qui sera convoyé en Silithus par voie aérienne. Pouvez-vous nous apporter votre aide, <classe> ?", progress = "J’espère vraiment que vous avez réussi à rassembler les barres de thorium dont nous avons parlé plus tôt.", completion = "Oh, merci, &lt;classe&gt; ! Merci ! Voilà qui en fait vingt de moins, et plus que… qu’un nombre incalculable. Vous avez mérité la gratitude de l'Alliance, et vos efforts ne resteront pas sans récompense. Revenez me voir si vous trouvez d’autres barres de thorium.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8500] = {title = "L'Alliance a besoin de plus de barres de thorium !", objective = "Apportez 20 Barres de thorium à Dame Twinbraid à l'aérodrome de Dun Morogh.", description = "C’est très agréable de vous revoir, <nom>. J’espère que vous allez bien. Il est vrai que nous avons encore besoin de barres de thorium. Si vous en avez quelques-unes en trop, j’en rassemble pour l’effort de guerre d’Ahn'Qiraj.", progress = "Ça fait plaisir de vous revoir, <nom>. J'espère que vous vous portez bien. Nous avons effectivement encore besoin de barres de thorium. Si vous en avez dont vous pouvez vous passer, je les collecte pour l'effort de guerre d'Ahn'Qiraj.", completion = "Excellent, &lt;classe&gt; ! Du bon boulot. Je vais veiller à ce que ces barres soient correctement empilées, puis remises aux forgerons et aux ingénieurs qui préparent le matériel de l’armée. Encore merci, et si vous récupérez d’autres barres de thorium, vous savez où me trouver.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8501] = {title = "Objectif : les aiguillonneurs de la Ruche'Ashi", objective = "Tuez 30 Aiguillonneurs de la Ruche’Ashi, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat XII.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Ashi. Vos cibles prioritaires seront aériennes : les aiguillonneurs de la Ruche’Ashi.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous voulez me dire quelque chose, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Ashi a été remarqué.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8502] = {title = "Objectif : les ouvrières de la Ruche'Ashi", objective = "Tuez 30 Ouvrières de la Ruche’Ashi, et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat III pour terminer cette quête.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Ashi. Vos cibles prioritaires seront les ouvrières de la Ruche’Ashi.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Excellent travail, &lt;nom&gt;. Sans ouvrières, les silithides vont avoir du mal à réparer les dégâts infligés à la structures de leur ruche.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8503] = {title = "L'Alliance a besoin d'étouffante !", objective = "Ramener 20 Etouffantes au soldat Draxlegauge dans la Garde militaire d'Ironforge.", description = "Dites, <classe>, est-ce que je vous ai déjà parlé de tout ce qu’on peut faire de fabuleux avec de l’étouffante ? Oui ? Ah bon… en tout cas, il nous en faut beaucoup, et quand je dis beaucoup, je veux dire BEAUCOUP ! Pensez-vous pouvoir nous aider ? Je sais que cela vous privera de toutes les choses merveilleuses que vous auriez pu fabriquer avec, mais c’est pour une bonne cause !", progress = "Ce n’est pas vrai ! Je n’ai jamais piqué d’étouffante dans les sacs ! Je comprends qu’on soit tenté, notez bien, vu que c’est une vraie panacée qui sert pratiquement à tout. *tousse* Vous n’auriez pas ramené l’étouffante dont nous avons parlé un peu plus tôt ?", completion = "Bravo ! Et en voici vingt de plus. Vous êtes le meilleur . Je pense que je vais les empaqueter tout de suite avant qu’elles ne se fanent. Ah, j’ai tellement d’étouffante, et si peu de temps !\n\nMerci encore, &lt;classe&gt; !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8504] = {title = "L'Alliance a besoin de plus d'étouffante !", objective = "Ramener 20 étouffantes au soldat Draxlegauge à l’aérodrome de Dun Morogh.", description = "Tiens, bien le bonjour une fois encore ! Vous vous appellez… ah oui, ça me revient, <nom> ! Vous venez voir si j’ai encore besoin d’étouffante, pas vrai ? C’est votre jour de chance : la réponse à cette question est un OUI franc et massif ! Vous pourriez m’en ramener vingt de plus ?", progress = "Tiens, bien le bonjour une fois encore ! Vous vous appellez… ah oui, ça me revient, <nom> ! Vous venez voir si j’ai encore besoin d’étouffante, pas vrai ? C’est votre jour de chance : la réponse à cette question est un OUI franc et massif ! Vous pourriez m’en ramener vingt de plus ?", completion = "Eh bien, on peut dire que vous avez plein d’étouffante. Vite, mettons-la dans une boîte pour qu’elle reste fraîche. Vous m’avez… je veux dire vous nous avez… vous avez rendu à l’Alliance… un grand service en amenant ce paquet ici. Je veillerai à ce que tout le monde sache que c’est vous, l’illustre &lt;nom&gt;, qui avez fait pencher la balance de l’effort de guerre pour Ahn’Qiraj, grâce à votre récolte d’étouffante !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8505] = {title = "L'Alliance a besoin de lotus pourpre !", objective = "Ramener 20 lotus pourpres à maître Nightsong, dans la Garde militaire d'Ironforge.", description = "<classe>, le lotus pourpre est une fleur qui a de multiples usages. Je suis ici à la demande de l’Alliance en tant qu’autorité en ce domaine, pour préserver les herbes cueillies et m’assurer que nous en aurons assez pour soutenir notre effort de guerre, et ce dans toutes leurs fonctions.\n\nJe voudrais que vous parcouriez le vaste monde pour trouver ces fleurs et m’en rapporter. Pouvez-vous vous en charger ?", progress = "Avez-vous les lotus pourpres que j'ai demandés ?", completion = "Nous apprécions beaucoup votre contribution, &lt;classe&gt;. Nous ne pourrons briser l’impitoyable progression des silithides – et la force qui les pousse à nous attaquer – que grâce aux efforts combinés de tous. Même la Horde fait provision de lotus pourpre.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8506] = {title = "L'Alliance a besoin de plus de lotus pourpre !", objective = "Ramener 20 lotus pourpres à maître Nightsong, à l’aérodrome de Dun Morogh.", description = "Bienvenue une nouvelle fois, <classe> ! Notre réserve grandit, mais même ainsi, il nous faut encore du lotus pourpre. Si vous en avez la possibilité, j’apprécierais que vous preniez le temps d’en récolter encore et de me ramener votre cueillette ici.", progress = "Bienvenue une nouvelle fois, <classe> ! Notre réserve grandit, mais même ainsi, il nous faut encore du lotus pourpre. Si vous en avez la possibilité, j’apprécierai que vous preniez le temps d’en récolter encore et de me ramener votre cueillette ici.", completion = "Je suis heureux d’accepter votre contribution au nom de l’Alliance, &lt;nom&gt;. Grâce à vos efforts, nous pourrons créer des huiles et des potions pour les combattants qui se trouvent sur le front. Merci. Si vous vous en procurez davantage, pensez à moi.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8507] = {title = "Votre affectation", objective = "Présentez-vous au poste de la brigade d’Ironforge devant la Ruche’Zora. Préparez votre Ordre de mission et obtenez un Ordre de mission signé du capitaine Blackanvil. Ensuite, retournez voir l'Implorateur céleste Kaldon au Fort cénarien, en Silithus.\n\nNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la brigade d’Ironforge vous infligera un marqueur JcJ.", description = "Salutations, <nom>. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne. \n\nVous trouverez les forces de la brigade d’Ironforge commandée par le capitaine Blackanvil devant la Ruche’Zora. \n\nAllez vous présenter à lui ou à  son lieutenant, Janela Stouthammer, et revenez me voir. Je vous aurai alors préparé des missions plus délicates.\n\nOh, et faites-nous une faveur. Ne restez pas à côté de la légion d’Orgrimmar. Nous avons été obligés de bien séparer les deux armées à cause de l’animosité mutuelle qu’elles se vouent…", progress = "Les forces du capitaine Blackanvil sont cantonnées devant la Ruche’Zora.  Parlez à son lieutenant, Janela Stouthammer, si vous ne pouvez pas le trouver.", completion = "Très bien, &lt;nom&gt;. J’ai préparé une série de tâches qui conviennent parfaitement à vos compétences.\n\nAvec tous les efforts que vous et des personnes comme vous avez fournis, notre ennemi sera bientôt vaincu une bonne fois pour toutes !\n\nSi vous avez besoin d’un nouveau briefing, retournez voir le capitaine Blackanvil.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAffectation de combatAffectation logistiqueAffectation tactique"},
[8508] = {title = "La liste des affectations", objective = "Je suppose que vous voulez que ces papiers soient signés, jeune homme ?", description = nil, progress = "Je suppose que vous voulez que ces papiers soient signés, jeune homme ?", completion = "Oui, je suppose que de nos jours, cette petite escarmouche peut passer pour une véritable opération de guerre.  Rapportez ces papiers au Fort cénarien. Je suis certain qu’ils auront une mission pépère à vous confier. \n\nAllez, au boulot !", rewards = "Vous recevrez :\n\nOrdre de mission signé"},
[8509] = {title = "L'Alliance a besoin de larmes d'Arthas !", objective = "Ramener 20 larmes d’Arthas au sergent-major Germaine dans la Garde militaire d'Ironforge.", description = "Je vais rester simple et directe, <classe>. L’Alliance a besoin de récolter une grande quantité de larmes d’Arthas pour l’effort de guerre d’Ahn’Qiraj. Ne me demandez pas pourquoi, moi, j’obéis juste aux ordres. Mais j’aimerais que vous rassembliez autant d’herbes que vous pourrez en trouver, et que vous me les apportiez ici. Vous voulez bien ?", progress = "Qu'y a-t-il ? Parlez plus fort, <classe> ! Avez-vous la cargaison de larmes d'Arthas que j'ai demandée ?", completion = "Bon travail, &lt;classe&gt;. Je dois dire que c’est une bonne surprise. Vous n’imaginez pas le nombre de gens qui se présentent, proposent leur aide… et ne reviennent jamais. Laissez-moi le temps de mettre votre contribution dans une caisse et de noter votre nom sur l’inventaire. Ensuite, nous verrons si j’ai encore besoin de plantes.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8510] = {title = "L'Alliance a besoin de plus de larmes d'Arthas !", objective = "Ramener 20 larmes d’Arthas au sergent-major Germain à l’aérodrome de Dun Morogh.", description = "Bon, on dirait bien qu’il me faut encore des larmes d’Arthas. Je suppose que vous pourrez en trouver dans le coin où vous en avez récolté la dernière fois. Plus vite vous les aurez, plus vite nous pourrons lancer l’offensive contre les troupes ennemies à Ahn’Qiraj.\n\nVous n’allez pas nous laisser tomber, <classe> ?", progress = "Bon, on dirait bien qu’il me faut encore des larmes d’Arthas, <classe>. Je suppose que vous pourrez en trouver dans le coin où vous en avez récolté la dernière fois. L’effort de guerre progresse bien, mais plus vite vous les aurez, plus vite nous pourrons lancer l’offensive contre les troupes ennemies à Ahn’Qiraj.\n\nVous n’allez pas nous laisser tomber, <nom> ?", completion = "Remarquable, &lt;nom&gt; ! Vous faites honneur à l’Alliance. Je vais mettre ces herbes à l’abri en attendant que quelqu’un vienne s’en servir pour fabriquer des fournitures militaires. N’hésitez pas à repasser me voir, surtout si vous avez d’autres larmes d’Arthas.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8511] = {title = "L'Alliance a besoin de cuir léger !", objective = "Ramenez 10 Cuirs légers à Bonnie Stoneflayer dans la Garde militaire d'Ironforge.", description = "Nous autres, les Stoneflayers, nous avons un long passé de dépeceurs, <classe>. Pour cette raison, l’Alliance a demandé à ma famille de s’occuper de la collecte de cuir léger pour l’effort de guerre d’Ahn’Qiraj. Je suis là pour m’assurer que le cuir est tanné de manière à pouvoir être utilisé plus tard. Mais nous avons besoin de votre aide.\n\nJe ne peux pas être en deux endroits à la fois. Comme je suis coincée ici, j’ai besoin que vous vous chargiez de la récolte des peaux. Ramenez-les-moi. Qu’en dites-vous, <mon gars/ma fille> ? Ça vous tente ?", progress = "J’espère que c’est le cuir léger que vous m’aviez promis, <classe>.", completion = "J’ai dans l’idée que l’Alliance va être très satisfaite de ces peaux, &lt;classe&gt;. Je veillerai à ce qu’aucune ne soit gâchée. Merci. Revenez me voir lorsque je les aurai comptées, nous verrons s’il m’en faut d’autres.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8512] = {title = "L'Alliance a besoin de plus de cuir léger !", objective = "Apportez 10 Cuirs légers à Bonnie Stoneflayer à l'aérodrome de Dun Morogh.", description = "Je suis heureuse de vous revoir, <nom>. Il semblerait que nous ayons besoin de plus de cuir léger pour fabriquer tout l’équipement de guerre dont nous avons besoin. Si vous pouviez me rapporter une pile de dix cuirs légers, ce serait parfait.", progress = "Je suis heureuse de vous revoir, <nom>. Il semblerait que nous ayons besoin de plus de cuir léger pour fabriquer toutes les fournitures militaires dont nous avons besoin. Si vous pouviez me rapporter une pile de dix cuirs légers, ce serait parfait.", completion = "Merci de ce don généreux, &lt;nom&gt;. Pour l’instant, je vais les mettre sur la pile, mais il ne faudra pas longtemps pour qu’ils deviennent des armures, des renforts de cuir ou un autre objet indispensable à nos préparatifs. Je crois bien qu’on a toujours besoin de cuir léger. Revenez me voir bientôt !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8513] = {title = "L'Alliance a besoin de cuir moyen !", objective = "Ramener 10 cuirs moyens au soldat Porter dans la Garde militaire d'Ironforge.", description = "Oui <messire/madame> j’ai été chargé de collecter et d’enregistrer tout le cuir moyen récolté pour l’effort de guerre. Si vous êtes motivés pour aller chercher du cuir moyen, par quelque moyen que ce soit, ramenez-le moi. J’apprécierai certainement un coup de main, si vous avez un peu de temps à y consacrer.", progress = "Oui messire je me souviens de vous. Vous avez une livraison de cuir moyen pour moi ?", completion = "Waouh ! J’ai l’impression que ça ne fait pas cinq minutes que vous vous êtes porté volontaire. Merci beaucoup pour ce don. Je vais empaqueter et compter tout ça. Pour sûr, vous avez ensoleillé ma journée.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8514] = {title = "L'Alliance a besoin de plus de cuir moyen !", objective = "Ramener 10 cuirs moyens au soldat Porter, à l’aérodrome de Dun Morogh.", description = "Nous avons collecté $2063w morceaux de cuir moyen à ce jour, <messire/madame>. Je sais que vous en demande beaucoup, mais si vous êtes toujours <partant/partante>, j’aimerais bien que vous me donniez un coup de main pour le reste de mon quota.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8515] = {title = "L'Alliance a besoin de cuir épais !", objective = "Ramener 10 Cuirs épais à Marta Finespindle dans la Garde militaire d'Ironforge.", description = "Ça va être génial ! Vous savez, <classe>, l’effort de guerre pour Ahn’Qiraj prend de l’ampleur, et j’ai été chargée de m’occuper de tout le cuir épais qui arrive. Nous nous en servons pour fabriquer des tonnes de choses, mais d’abord, hé bien, il nous en faut des tonnes. Oui, vraiment des tonnes ! Et c’est là que vous intervenez.\n\nVous pensez que vous pourriez me ramener un bon gros paquet de cuir épais ? Hein ? Dites ?", progress = "C’est du cuir épais que vous avez dans votre sac, <classe> ? Allez, dites-moi que c’en est ! Donnez-le, je meurs d’impatience ! Tout le monde va être content de nous, n’est-ce pas ?", completion = "Oh, je savais que vous pourriez le faire, &lt;classe&gt;. Je le savais ! Je transmettrai tout ça à qui de droit dès que possible. Et maintenant, voyons… Hmm, on dirait que notre collecte progresse bien. Revenez me voir dans un moment. J’aurai terminé mes comptes, et je pourrai vous dire s’il nous en faut plus. Parce que si c’est le cas, c’est à vous que je veux confier le travail !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8516] = {title = "L'Alliance a besoin de plus de cuir épais !", objective = "Ramener 10 cuirs légers à Marta Finespindle à l’aérodrome de Dun Morogh.", description = "La pile n’est pas encore assez haute, <nom>. Nous n’avons toujours pas atteint notre objectif de $2071w cuirs épais. Pensez à ce que nous pourrons fabriquer avec tout ce cuir ! Des armures. Des armes. Des trucs et des machins pour l’intérieur des chars à vapeur. Des lunettes de visée. Des lunettes d’ingénieur. Et s’il nous en reste, nous pourrons toujours filer le reste à la Horde pour leurs zeppelins !\n\nAlors, allez-vous me ramener encore plus de cuir épais ?", progress = "La pile n’est pas encore assez haute, <nom>. Nous n’avons toujours pas atteint notre objectif pour le cuir épais. Pensez à ce que nous pourrons fabriquer avec tout ce cuir ! Des armures. Des armes. Des trucs et des machins pour l’intérieur des chars à vapeur. Des lunettes de visée. Des lunettes d’ingénieur, c’est toujours rigolo.\n\nAlors, allez-vous me ramener encore plus de cuir épais ?", completion = "Vous êtes de retour ! C’est merveilleux de vous voir partir, récolter tout ça, revenir et me le donner. Je vais vous dire, quand les gens sauront à quel point vous nous avez aidé, vous ne pourrez plus mettre le nez dehors, tellement on vous demandera d’autographes.\n\nMerci encore pour don très généreux de cuir épais, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8517] = {title = "L'Alliance a besoin de bandages en lin !", objective = "Ramener 20 bandages en lin à la Sentinelle Silversky, dans la Garde militaire d'Ironforge.", description = "La guerre d’Ahn’Qiraj s’annonce longue et sanglante. L’Alliance se montre sage en vous recrutant, vous et les autres, pour accumuler le matériel indispensable avant que les hostilités n’éclatent.\n\nJ’ai été chargée de collecter les bandages en lin pour la guerre, et j’espère que vous pourrez m’aider à en accumuler autant que nécessaire. C’est important, mais les bandages en lin ont l’avantage d’être faciles à fabriquer. Alors, êtes-vous avec nous, <classe> ?", progress = "Avez-vous les vingt bandages en lin dont j’ai besoin, <classe> ?", completion = "De nombreux soldats profiteront de votre contribution de ce jour, &lt;classe&gt;. Je veillerai personnellement à ce que l’Alliance soit informée de vos efforts. Laissez-moi un instant pour ranger ces bandages correctement et pour remettre mon décompte à jour, puis revenez voir si j’ai encore besoin de quelque chose.\n\nQu’Elune vous illumine, &lt;race&gt; !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8518] = {title = "L'Alliance a besoin de plus de bandages en lin !", objective = "Apportez 20 Bandages en lin à la Sentinelle Silversky à l'aérodrome de Dun Morogh.", description = "Je suis toujours étonnée par l’altruisme dont font preuve certains, alors que tant de gens se réfugient dans l’égoïsme. <classe>, j’ai toujours besoin d’un grand nombre de bandages en lin avant que mon objectif ne soit rempli. M’aiderez-vous une fois encore à réunir ces bandages ?", progress = "Je suis toujours étonnée par l’altruisme dont font preuve certains, alors que tant de gens se réfugient dans l’égoïsme. <classe>, j’ai toujours besoin d’un grand nombre de bandages en lin avant que mon objectif ne soit rempli. M’aiderez-vous une fois encore à réunir ces bandages ?", completion = "Vous méritez des félicitations, &lt;nom&gt;. Nous sommes en train de nous mettre sur le pied de guerre. Dans de telles circonstances, la cupidité en pousse certains à se remplir les poches. Vous avez prouvé, encore et encore, que votre dévouement envers l’Alliance – et envers tout Azeroth – passait en premier.\n\nPuisse Elune vous bénir toujours !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8519] = {title = "Un pion sur l'Echiquier éternel", objective = "Apprenez tout ce que vous pouvez au sujet du passé, puis parlez à Anachronos dans les Grottes du temps à Tanaris.", description = "Alors que vous retrouvez votre calme, vous remarquez que quelque chose s’agite à l’intérieur du cristal. En le regardant de plus près, vous comprenez que vous observez le passé… un souvenir… oublié depuis fort longtemps.", progress = nil, completion = "Après la trahison de Staghelm, j’ai rassemblé les fragments du Sceptre des Sables changeants et je les ai ramenés ici. Je comptais bien protéger le sceptre de ceux qui rêvaient de l’utiliser pour nuire à notre monde. C’est ainsi qu’est né le fardeau des Vols draconiques.\n\nJe pensais naïvement qu’un sceptre divisé entre les quatre puissants Aspects serait presque impossible à reconstituer pour ceux qui aspiraient au chaos. J’étais stupide, bien entendu. Encore aujourd’hui, le Vol maudit me traque.", rewards = "Vous recevrez :\n\n"},
[8520] = {title = "L'Alliance a besoin de bandages en soie !", objective = "Ramener 20 bandages en soie à l’infirmière Stonefield, dans la Garde militaire d'Ironforge.", description = "La guerre d’Ahn’Qiraj approche, et nous devons faire tout notre possible pour veiller à ce que nos soldats aient tout ce dont ils ont besoin. C’est exactement ce que nous faisons à présent. On m’a demandé de veiller à ce que nous collections assez de bandages en soie.\n\nPensez-vous pouvoir m’aider, <classe> ?", progress = "Salutations <classe>, avez-vous déjà réussi à vous procurer vingt bandages en soie ?", completion = "Vous y êtes $garrivé arrivée; ! Grâce à vous, &lt;classe&gt;, nous avons fait un pas de plus vers notre quota de bandages en soie. Je vais les ranger. Ensuite, si vous le désirez, nous pourrons parler.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8521] = {title = "L'Alliance a besoin de plus de bandages en soie !", objective = "Apportez 20 Bandages en soie à l'infirmière Stonefield à l'aérodrome de Dun Morogh.", description = "C’est très sympathique de votre part de revenir m’aider, <classe> Il semblerait que nous ayons déjà rassemblé $2082w bandages en soie, mais cela n’est pas suffisant.", progress = "C’est très sympathique de votre part de revenir m’aider, <classe> Il semblerait que nous ayons déjà rassemblé une bonne partie des bandages en soie qui m’ont été demandés, mais ce n’est pas suffisant. Dites <nom>, est-ce que vous auriez le temps de m’en préparer un autre paquet ? L’Alliance vous en serait très reconnaissante… et moi donc !", completion = "Vous êtes plein d’abnégation. Merci infiniment de votre contribution à l’effort de guerre. Ce sont des gens comme vous qui feront la différence entre victoire et défaite à Ahn’Qiraj. J’espère que cela suffira.\n\nEncore merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8522] = {title = "L'Alliance a besoin de bandages en étoffe runique !", objective = "Ramener 20 Bandages en étoffe runique au Gardien Moonshade dans la Garde militaire d'Ironforge.", description = "Débattez des mérites de cette guerre si vous le voulez, <classe>, mais elle a déjà été déclenchée. Regardez autour de vous, votre famille, vos amis, et demandez-vous si vous pouvez faire quelque chose pour leur assurer tous les avantages possibles pour survivre, s’ils se trouvaient plongés dans la tourmente.\n\nC’est pour cette raison que je rassemble tous les bandages en étoffe runique que je peux trouver. Voudriez-vous faire une donation ?", progress = "Les jours se succèdent, et nous continuons nos efforts, encore et encore. <classe>, avez-vous ces bandages en étoffe runique ?", completion = "Votre persévérance est digne d’éloges, &lt;classe&gt;. Je vais ranger votre contribution, et ensuite j’aimerais que nous discutions d’une nouvelle collecte de bandages en étoffe runique.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8523] = {title = "L'Alliance a besoin de plus de bandages en étoffe runique !", objective = "Ramener 20 bandages en étoffe runique au gardien Moonshade à l’aérodrome de Dun Morogh.", description = "Nous nous retrouvons une fois de plus pour discuter d’une affaire urgente, <classe>. Je vous remercie encore pour vos précédents efforts. Peu de gens se seraient montrés aussi généreux et altruistes. Mais il reste beaucoup à faire.\n\n<nom>, acceptez-vous de récolter de nouveaux bandages en étoffe runique et de me les ramener ?", progress = "Nous nous retrouvons une fois de plus pour discuter d’une affaire urgente, <classe>. Je vous remercie encore pour vos précédents efforts. Peu de gens se seraient montrés aussi généreux et altruistes. Mais il reste beaucoup à faire.\n\n<nom>, acceptez-vous de récolter de nouveaux bandages en étoffe runique et de me les ramener ?", completion = "Nous marchons de concert sur une route plaisante, &lt;nom&gt;. Vous faites un excellent collègue. Une fois de plus, je vous remercie de tous vos efforts, et par ma voix, c’est l’Alliance toute entière qui vous remercie. Revenez me voir bientôt !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8524] = {title = "L'Alliance a besoin de thon arc-en-ciel !", objective = "Ramener 20 Thons arc-en-ciel à Khirry le Gastronome dans la Garde militaire d'Ironforge.", description = "Par ici, <l’ami/l’amie> ! Si je vous dis, « Vous ne croyez pas que les soldats ont besoin de manger, comme tout le monde ? », vous allez me répondre « Si, bien sûr ». Eh bien, nous sommes d’accord à 110 % ! Et j’en suis très heureux. Tout ce dont j’ai besoin, c’est que vous alliez me pêcher une bonne petite série de thons arc-en-ciel, que vous les cuisiniez et que vous me les rapportiez. Mmm, mmm, j’en ai déjà l’eau à la bouche…", progress = "Je suis prêt à parier que vous êtes revenu avec le thon arc-en-ciel dont nous avons parlé plus tôt, <classe>. J’ai pas raison ?", completion = "Deux pour l’Alliance, un pour moi, deux pour l’Alliance, un pour moi… Hé bien, mon petit poissonnier  c’est du bon travail. Je vois que vous allez vraiment faire honneur au club. Mais j’ai bien l’impression qu’on aura besoin d’encore plus de thon. Et si vous y retourniez et que vous en pêchiez un peu plus ? J’entends déjà mon estomac qui gargouille…", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8525] = {title = "L'Alliance a besoin de plus de thon arc-en-ciel !", objective = "Ramenez 20 thons arc-en-ciel à Khirry le Gastronome à l’aéroport de Dun Morogh.", description = "Quoi ! Encore vous ? Que je sois changé en grenouille… enfin non, je suis un gnome. Khirry le Gastronome, pour être précis ! Alors, vous revenez m’aider, hein ? Bon, je ne vous en veux pas. Je comprends que vous aimiez cette odeur de nourriture. <Il se met à saliver.>\n\nBon, assez perdu de temps. Filez, et ramenez-moi plus de thon arc-en-ciel !", progress = "Quoi ! Encore vous ? Que je sois changé en grenouille… enfin non, je suis un gnome. Khirry le Gastronome, pour être précis ! Alors, vous revenez m’aider, hein ? Bon, je ne vous en veux pas. Je comprends que vous aimiez cette odeur de nourriture. <Il se met à saliver.>\n\nBon, assez perdu de temps. Filez, et ramenez-moi plus de thon arc-en-ciel !", completion = "Je savais que vous y arriverez, mon petit. Vous avez l’air d’une personne qui sait ce qu’elle aime. Et dans ce cas, vous aimez me faire plaisir, à moi et à mes supérieurs. Je vous assure que vous y arrivez très bien.\n\nHa ha ha ! Bon, allez, je vais ranger ces poissons, puis nous aurons une petite conversation, vous et moi, sur vos vingt prochains thons.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8526] = {title = "L'Alliance a besoin de rôtis de raptor !", objective = "Ramener 20 Rôtis de raptor à Sarah Sadwhistle dans la Garde militaire d'Ironforge.", description = "Oh, comment va, <classe> ? Vous avez l’air de quelqu’un que l’idée de collecter de la nourriture pour la future guerre d’Ahn’Qiraj pourrait intéresser. Papa s’est dit que ce serait formateur pour moi si je me portais volontaire. Grosse erreur. Je n’aime même pas la viande.\n\nBref, si ça vous dit, j’ai besoin de rôtis de raptor. Beaucoup. Apparemment, les soldats vont être « volontaires » pour les manger.", progress = "Alors, vous avez tous les rôtis de raptor ?", completion = "Oh, c’est super ! Merci de me ramener toute cette chair animale brûlée, &lt;classe&gt;. Je vais la mettre sur la pile là-bas. Je suis sûre que quelqu’un s’en occupera. Si vous avez un peu de temps à tuer, je suppose que vous pourriez m’en procurer d’autres ?", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8527] = {title = "L'Alliance a besoin de plus de rôti de raptor !", objective = "Apportez 20 Rôtis de raptor à Sarah Sadwhistle à l’aérodrome de Dun Morogh.", description = "Re-bonjour <classe>. Je vois bien que vous êtes <passionné/passionnée> par tout ça. Donc je suppose que vous voulez m’apporter vingt autres rôtis de raptor. Parfait. Faites donc. Je vous reverrai quand vous reviendrez avec la marchandise.", progress = "Re-bonjour <classe>. Je vois bien que vous êtes passionnée par tout ça. Donc je suppose que vous voulez m’apporter vingt autres rôtis de raptor. Parfait. Faites donc. Je vous reverrai quand vous reviendrez avec la marchandise.", completion = "Waouh, quel enthousiasme. Rien de vous regarder, je me sens fatiguée. En tout cas, l’Alliance vous dit merci, tout ça. Je vais m’assurer que toute cette viande morte soit bien emballée. Je suppose que si vous y tenez, vous pourrez toujours revenir voir s’il m’en faut encore. Mais entre nous, cet endroit commence à sentir.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8528] = {title = "L'Alliance a besoin de jaune-queue tacheté !", objective = "Ramener 20 jaunes-queues tachetés à la chasseresse Swiftriver dans la Garde militaire d'Ironforge.", description = "Il est vrai que rassembler du poisson cuisiné ne paraît pas très héroïque, mais ne sous-estimez pas la valeur de la préparation, jeune <classe>. Les soldats ont besoin de manger comme tout le monde, et nous sommes là pour nous assurer qu’ils auront tout le nécessaire lorsque la guerre d’Ahn’Qiraj commencera.\n\nC’est pour cette raison que je fais des stocks de jaunes-queues tachetés, une source de nourriture que l’on peut préparer selon de nombreuses recettes et qui se conserve bien. Et cette espèce n’a pas une odeur aussi forte que certains poissons d’eau de mer. Acceptez-vous de me prêter votre aide ?", progress = "Je suis sûre que vous reviendrez très bientôt avec les jaunes-queues tachetés dont nous avons parlé.", completion = "Merci de ce don, &lt;classe&gt;, il tombe à point. Nos soldats ne mourront pas de faim. Laissez-moi le temps de stocker ces poissons comme il convient et, si cela vous tente, nous discuterons d’une nouvelle fournée.", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8529] = {title = "L'Alliance a besoin de plus de jaune-queue tacheté !", objective = "Ramener 20 jaunes-queues tachetés à la chasseresse Swiftriver à l’aérodrome de Dun Morogh.", description = "Si vous êtes toujours volontaire, j’aimerai  vous renvoyer là-bas pour me rapporter de nouvelles prises de jaunes-queues tachetés, <nom>. J’imagine qu’avec l’expertise que vous avez gagné la première fois, cette pêche devrait être plus rapide et plus facile. Cela vous dit ?", progress = "Si vous êtes toujours volontaire, j’aimerai  vous renvoyer là-bas pour me rapporter de nouvelles prises de jaunes-queues tachetés, <nom>. J’imagine qu’avec l’expertise que vous avez gagné la première fois, cette pêche devrait être plus rapide et plus facile. Cela vous dit ?", completion = "Vous êtes un véritable membre de l’Alliance, &lt;nom&gt;. Vos efforts ne sont pas passés inaperçus, croyez-moi. Et merci d’avoir fait cuire les poissons. Je vais veiller à ce qu’ils soient conservés correctement, et ensuite, je mettrai mon décompte à jour. Chaque nouvelle prise nous rapproche de notre objectif !", rewards = "Vous recevrez :\n\nChevalière de mérite de l'AllianceFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8530] = {title = "L'Alliance a besoin de pierres du Magma roussies !", objective = "Ramener 50 Pierres du Magma roussie au commandant Stronghammer à l'aérodrome de Dun Morogh.", description = "<classe>, j’ai besoin de votre aide. Dans le Cœur du Magma, il existe des pierres, des pierres du Magna roussies pour être plus précis, que nous devons récolter pour notre effort de guerre d'Ahn'Qiraj. Il paraît que nos forgerons et nos ingénieurs peuvent en faire bon usage, et c’est là que vous intervenez. J’ai besoin que vous alliez dans le Cœur du Magma et que vous ramassiez autant de ces pierres du magma roussies que vous pourrez. Bien sûr, vous voudrez peut-être vous faire accompagner de trente-neuf de vos amis proches.", progress = nil, completion = nil, rewards = nil},
[8531] = {title = "L'Alliance a besoin de plus de pierres du Magma roussies !", objective = "Rapportez 50 Pierres du Magma roussies au commandant Fortmartel, à l’aérodrome de Dun Morogh.", description = "Merci de revenir me voir, <nom>. Si vous en avez le courage, vous et vos amis, j’ai besoin que vous retourniez au Cœur du Magma pour récupérer d’autres pierres du magma roussies. Qu’en pensez-vous ?", progress = nil, completion = nil, rewards = nil},
[8532] = {title = "La Horde a besoin de barres de cuivre !", objective = "Ramener 20 barres de cuivre au mineur Cromwell dans la Vallée des esprits d'Orgrimmar.", description = "C’est bien que vous ayez décidé d’aider. Tout le monde ne le fait pas, loin de là. Je dois veiller à ce que vous compreniez bien ce dont j’ai besoin. Il me faut des barres de cuivre, pas du minerai. Nous n’avons ni le temps, ni le personnel pour procéder à la fonte. Si vous avez la bonté de vous en charger vous-même, vos efforts seront dûment notés. Vous pouvez vous en tirer, <classe> ?", progress = "J’espère que votre sac contient bien vingt barres de cuivre, <classe>.", completion = "Ces barres feront l’affaire. Merci de ne pas les avoir polies. Pas besoin qu’elles soient jolies, elles vont être utilisées pour fabriquer des fournitures militaires. Je vais les mettre en piles, et je veillerai à ce qu’elles soient bien employées. Revenez me voir si vous voulez m’en fournir une autre vingtaine.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8533] = {title = "La Horde a besoin de plus de barres de cuivre !", objective = "Apportez 20 Barres de cuivre au Mineur Cromwell à Durotar.", description = "Déjà de retour? On fera de vous un vrai mineur en un rien de temps, <classe>. Bon, vous connaissez l’exercice ; j’ai besoin que vous vous baladiez, que vous miniez un bon filon de cuivre, que vous le fondiez en barres et que vous me les rapportiez ici. Je sais parfaitement que vous en êtes capable. La véritable question est, est-ce que vous portez volontaire ?", progress = "Déjà de retour? On fera de vous un vrai mineur en un rien de temps, <classe>. Bon, vous connaissez l’exercice ; j’ai besoin que vous vous baladiez, que vous miniez un bon filon de cuivre, que vous le fondiez en barres et que vous me les rapportiez ici. Je sais parfaitement que vous en êtes capable. La véritable question est, est-ce que vous portez volontaire ?", completion = "Vous m’avez prouvé votre valeur une fois encore, &lt;classe&gt;. Je veillerai à ce que toutes ces barres de cuivre soient utilisées en temps et heure. Pour l’instant, je vais les placer sur la palette et les comptabiliser. Si cela vous dit, vous pourriez peut-être nous aider à en rassembler encore plus.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8534] = {title = "Rapport de reconnaissance de la Ruche'Zora", objective = "Trouver l’Eclaireur cénarien Azenel dans la Ruche’Zora et ramener le Rapport de reconnaissance de la Ruche’Zora à l’Imploratrice céleste Proudhorn, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique VI.", description = "Nous avons déployé nos meilleurs éclaireurs dans les ruches silithides. L’éclaireur Azenel épie les mouvements des silithides de la Ruche’Zora depuis plusieurs jours. Trouvez-la et demandez-lui un rapport écrit. Nous avons besoin de ces informations dès que possible, <nom>.", progress = "L’éclaireur Azenel se trouve dans la Ruche’Zora. Hâtez-vous, <nom> ! Le temps presse.", completion = "Vos efforts sont dignes d’éloges, &lt;nom&gt;. Je vais lire ces rapports tout de suite. Pendant ce temps-là, vous avez certainement d’autres missions à remplir.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique complémentaire"},
[8535] = {title = "Le templier chenu", objective = "Invoquez et tuez un Templier chenu, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique IV.", description = "Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.\n\nTrouvez un moyen d’invoquer et de détruire un Templier chenu, puis allez faire votre rapport à Bor Wildmane.", progress = "Avez-vous rempli votre mission, <nom> ?", completion = "Excellent travail, &lt;nom&gt;.  Voici votre prochaine mission.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique"},
[8536] = {title = "Le templier terrestre", objective = "Invoquez et tuez un Templier terrestre, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique III.", description = "Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.\n\nTrouvez un moyen d’invoquer et de détruire un Templier terrestre, puis allez faire votre rapport à Bor Wildmane.", progress = "Avez-vous rempli votre mission, <nom> ?", completion = "Excellent travail, &lt;nom&gt;.  Voici votre prochaine mission.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique complémentaire"},
[8537] = {title = "Le templier cramoisi", objective = "Invoquez et tuez un Templier cramoisi, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique II.", description = "Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.\n\nTrouvez un moyen d’invoquer et de détruire un Templier cramoisi, puis allez faire votre rapport à Bor Wildmane.", progress = "Avez-vous rempli votre mission, <nom> ?", completion = "Excellent travail, &lt;nom&gt;.  Voici votre prochaine mission.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique"},
[8538] = {title = "Les quatre ducs", objective = "Trouver un moyen d’invoquer et de tuer les duc des Cendres, le duc des Profondeurs, le duc des Zéphyrs et le duc des Éclats, puis revenir voir le commandant Mar'alith au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique V.", description = "Les liens entre le Marteau du crépuscule et le Conseil abyssal s’avèrent plus étroits que nous le pensions.\n\nNous soupçonnons des nobles élémentaires connus sous le nom de « ducs abyssaux » d’être l’une des forces qui organisent les sectateurs du Marteau du crépuscule. Trouvez un moyen de les attirer sur notre plan d’existence et détruisez-les.\n\nVotre détermination et vos exploits passés nous ont conduits à vous sélectionner pour cette mission. Nous sommes certains que vous réussirez.", progress = "Avez-vous rempli votre mission, <nom> ?", completion = "Vous avez rendu un service exceptionnel à notre cause aujourd’hui, &lt;nom&gt;. Vous avez vaincu certains de nos ennemis les plus redoutables. Je vous félicite du fond du coeur.", rewards = "Vous recevrez :\n\nMarque de Cénarius"},
[8539] = {title = "Objectif : les sœurs de Ruche'Zora", objective = "Tuez 30 Soeurs de la Ruche’Zora et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat V pour terminer cette quête.", description = "Nous avons demandé à ce que des renforts rejoignent l’assaut sur la Ruche’Zora. Vos cibles prioritaires seront les sœurs de la Ruche’Zora. À la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Très bon travail, &lt;nom&gt;. Vous êtes un allié de valeur.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8540] = {title = "Des bottes pour la Garde", objective = "Remettre 3 Bottes ornées en mithril à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique II pour terminer cette quête.", description = "La division de cavalerie de la garde du Fort cénarien manque de bottes ornées en mithril. Procurez-vous en un stock et livrez-le immédiatement au capitaine Vish Kozus au Fort cénarien.", progress = "Vous avez quelque chose pour moi ?", completion = "Excellent. Nous en avions besoin. Bon boulot, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8541] = {title = "Des silex à aiguiser pour la Garde", objective = "Apporter 10 Silex à aiguiser denses, 10 Silex à aiguiser solides et 10 Silex à aiguiser lourds à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique III pour terminer cette quête.", description = "La garde du Fort cénarien est presque à court de silex à aiguisez. Apportez-en un assortiment au capitaine Vish Kozus, du Fort cénarien.", progress = "Vous avez quelque chose pour moi ?", completion = "Excellent, nous avions bien besoin, &lt;nom&gt;. Bon travail.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8542] = {title = "La Horde a besoin de barres d'étain !", objective = "Apportez 20 Barres d'étain au grunt Maug dans la Vallée des esprits d'Orgrimmar.", description = "Lok’tar, <race>. Je suis sûr que vous connaissez la nouvelle : nous allons marcher contre les insectes d’Ahn’Qiraj. Le chef de guerre a décidé que nous allions faire avant une « préparation ». Je pensais que ça voulait dire aiguiser les armes et forger les armures, mais bon, je suis fier d’avoir été choisi pour collecter des barres d’étain. Hélas, je ne peux rien faire sans votre aide.\n\nJ’ai besoin que vous alliez me chercher des barres d’étain. Ramenez-les-moi ici. Il m’en faut plus que je ne pourrais en compter.", progress = "Combien de barres d’étain avez-vous, <classe> ? Après la guerre, il faudra que je trouve quelqu’un pour m’apprendre à compter.", completion = "Eh bien, on dirait que vous avez le bon nombre de barres d'étain. Attention, n'essayez pas de me rouler, &lt;classe&gt; ! Compter me fait mal à la tête. Voilà ce qu’on va faire. Moi, je vais les ranger avec les autres. Vous, vous repartez et vous m’en rapportez autant.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8543] = {title = "La Horde a besoin de plus de barres d'étain !", objective = "Ramener 20 barres d’étain au grunt Maug en Durotar.", description = "Très bien, je vois que vous prenez cette guerre au sérieux. Attendre que les combats commencent me tape toujours un peu sur les nerfs. Du coup, si vous n’allez pas plus vite, je vais m’énerver. Ça me fera du bien de me défouler sur vous.\n\nArf ! Et peut-être pas, parce qu’à ce moment-là, je n’aurai plus personne pour me ramener mes barres d’étain, pas vrai ?", progress = "Très bien, je vois que vous prenez cette guerre au sérieux. Attendre que les combats commencent me tape toujours un peu sur les nerfs – je pense que vous comprenez ça, <classe>. Mais quand ça va commencer… La Horde chargeant dans les sables de Silithus, armes brandies, et se ruant dans les insectes agglutinés ! Ce sera une belle journée, avec beaucoup d’honneur à gagner !\n\nMais en attendant, il nous faut plus de barres d’étain. C’est drôle qu’un objet si petit fasse une telle différence, pas vrai ?", completion = "Throm'ka &lt;nom&gt;. Ces barres d’étain m’honorent et honorent la Horde. Je vais les placer sur la pile. Ensuite, les autres viendront et s’en serviront pour fabriquer des choses. Et quand tout sera terminé, ce sera la guerre et nous montreront à ces mauviettes de l’Alliance comment on écrase les cafards.\n\nAlors maintenant, vous allez me ramener plus de barres d’étain !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8544] = {title = "Les spallières du Conquérant", objective = "Ramener des Manchettes de commandement qiraji, 2 Idoles de la nuit, 5 Scarabées de pierre et 5 Scarabées d’argile à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, la Progéniture de Nozdormu doit au moins être Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !", progress = "Vous êtes-vous procuré les composants dont j’ai besoin ?", completion = "Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !", rewards = "Vous recevrez :\n\nSpallières du Conquérant"},
[8545] = {title = "La Horde a besoin de barres de mithril !", objective = "Ramener 20 barres de mithril au sergent-chef T’kelah dans la Vallée des esprits d'Orgrimmar.", description = "La guerre approche, <classe>. Tout ce qu’on peut faire, c’est de s’y préparer. Et c’est là qu’on peut s’aider mutuellement, <mon pote/ma jolie>. V’voyez, j’ai été chargé de récolter toutes les barres de mithril dont on va avoir besoin pour fabriquer… ben, tous les trucs dont on va avoir besoin. Et il m’en faut encore plein !\n\nAlors voilà, j’espérais que vous pourriez aller me déterrer un peu de mithril et le fondre pour en faire des barres. C’est dans vos cordes ?", progress = "Pour sûr, ça serait bien qu’on ait toutes les barres de mithril dont on a besoin pour l’effort de guerre d’Ahn’Qiraj. C’est pour ça que vous rev’nez ? Pour mes barres ?", completion = "Ça démarre bien, entre vous et moi, &lt;classe&gt;. Ça fait vingt barres de mithril que je peux mettre sur la pile et rayer d’ma liste. On en f’ra bon usage – des fournitures pour la guerre.\n\nN’hésitez pas à rev’nir me voir, passqu’on dirait qu’on n’a pas fini d’avoir besoin d’barres de mithril.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8546] = {title = "La Horde a besoin de plus de barres de mithril !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8547] = {title = "Bienvenue !", objective = "Apportez le bon-cadeau de la place de l’Épervier à Marsilla Aubétoile, place de l’Épervier.", description = "Bienvenue dans le monde de World of Warcraft !\n\nPour vous remercier d’avoir acheté l’édition Collector de World of Warcraft, allez voir Marsilla Aubétoile sur la place de l'Épervier, et présentez-lui ce bon. Elle vous offrira un petit compagnon qui vous accompagnera dans vos quêtes d’aventure et de gloire.\n\nMerci encore, et bon séjour dans World of Warcraft !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nLaisse de zerglingCollier de pandaPierre de Diablo"},
[8548] = {title = "L'équipement de guerre des volontaires", objective = "Ramener 5 Badges cénariens de combat, 3 Badges cénariens de logistique et 7 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Pour terminer cette quête, il faut aussi que le Cercle cénarien soit au moins Amical à votre égard.", description = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte du Fort cénarien ne sont pas seulement destinés à faire joli, <nom>.\n\nConservez-les soigneusement. Au fur et à mesure que vous ferez la preuve de votre loyauté envers notre organisation, vous pourrez les échanger contre le matériel que nous réservons à nos alliés les plus proches.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de puissance terrestreAnneau du courroux terrestreCape en tisse-terre"},
[8549] = {title = "La Horde a besoin de pacifique !", objective = "Ramener 20 pacifiques à l’herboriste Proudfeather dans la Vallée des esprits d'Orgrimmar.", description = "A ce que l’on dit, chaque génération doit affronter une épreuve qui la définit. Je crains que la guerre d’Ahn’Qiraj ne soit le creuset dans lequel notre valeur sera révélée. Nous nous préparons, et ce faisant, nous découvrons de quoi nous sommes faits.\n\nJe me suis proposée pour aider la Horde à récolter autant de pacifique que possible, afin qu’elle soit convertie en potions pour la guerre. J’espère que vous êtes ici pour me prêter assistance. Si c'est bien le cas, je vous demande de m'apporter une grande quantité de cette plante. M’aiderez-vous, <classe> ?", progress = "Déjà de retour avec la pacifique, <classe> ?", completion = "Et ainsi, tous nos gestes nous rapprochent de la guerre. Merci pour tous les efforts que vous avez dû consentir pour récolter cette pacifique, &lt;classe&gt;. Je vous assure qu’elle sera utilisée à bon escient, et que votre contribution n’est pas passée inaperçue, &lt;nom&gt;. Si vous le souhaitez, vous pourrez toujours me ramener d’autres fleurs. En attendant, que la Terre-mère vous guide !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8550] = {title = "La Horde a besoin de plus de pacifique !", objective = "Bonjour à nouveau, <nom>.  Je suis contente que vous souhaitiez me parler une nouvelle fois de nos besoins incessants en pacifique.  L’effort de guerre continue, et avec lui notre production de potions et d’élixirs pour les batailles à venir.\n\nVoulez-vous nous aider encore, <classe> ? J’ai besoin d’autant de pacifique que la première fois, et si vous pouvez en récolter et me la rapporter ici, je vous en serai très reconnaissante. Bien sûr, si vous l’avez déjà sur vous, je serai plus qu’heureuse de l’accepter.", description = nil, progress = "Bonjour à nouveau, <nom>.  Je suis contente que vous souhaitiez me parler une nouvelle fois de nos besoins incessants en pacifique.  L’effort de guerre continue, et avec lui notre production de potions et d’élixirs pour les batailles à venir.\n\nVoulez-vous nous aider encore, <classe> ? J’ai besoin d’autant de pacifique que la première fois, et si vous pouvez en récolter et me la rapporter ici, je vous en serai très reconnaissante. Bien sûr, si vous l’avez déjà sur vous, je serai plus qu’heureuse de l’accepter.", completion = "Merci de ces nouveaux efforts, &lt;nom&gt;. Ces dons généreux vous font honneur, à vous et à vos ancêtres, et ils seront connus de tous ! Je vais préparer ces herbes de manière à ce qu’elles restent fraîches jusqu’à ce que nous en ayons besoin. Une fois de plus, vous avez fait preuve du véritable esprit de la Horde, mariant la lutte pour triompher et le travail en commun pour y parvenir.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8551] = {title = "Le coffre du capitaine", objective = "Apporter le coffre au capitaine Hecklebury Smotts à Baie-du-Butin.", description = "Dans le passé, je pilotais un navire d'ici jusqu'à Ratchet, en Kalimdor. J'étais un grand capitaine avec une solide réputation.\n\nJusqu'à ce que…\n\nCes maudits géants des mers m'apportent la ruine ! Ils ont détruit mon bateau, tué mon équipage, et m’ont abandonné dans un canot. Et l'un d’eux, Gorlash, a volé mon coffre de capitaine. Il a dit qu'il le voulait pour en faire une tabatière. Quel toupet !\n\nJe sais que Gorlash sillonne la côte à l'est d'ici. Trouvez-le et récupérez mon coffre ! Faites-le, et vous gagnerez la gratitude d'un capitaine.", progress = "Ohé, <nom> ! Avez-vous trouvé Gorlash ? Ce coffre était mon préféré, et il contient un compartiment secret où sont cachés mes plus grands trésors !", completion = "Vous l'avez trouvé ! Oh, quelle belle journée ! Merci, &lt;nom&gt;. Retrouver mon coffre m'apaise quelque peu.\n\nMais ma revanche n'est pas complète…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards de bandelettes sanglantes"},
[8552] = {title = "L'écharpe à monogramme", objective = "Rendre l'Echarpe à monogramme à son propriétaire.", description = "On peut lire les lettres \"HS\" brodées le long de l'ourlet de la belle écharpe.", progress = "Hello ! Puis-je vous être utile ?", completion = "Vous avez retrouvé mon écharpe ? Alors… vous devez avoir tué Mok'rash le géant des mers ! Hourra !\n\nJe suis si heureux que cette misérable racaille soit morte. Mok'rash était l'un des trois géants des mers qui ont détruit mes navires et tué mes équipages.\n\nTrois fois.\n\nVous êtes un &lt;classe&gt; de valeur, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[8553] = {title = "Le sabre du capitaine Smott", objective = "Parler à Sprogger.", description = "Après que mon premier navire a été détruit par ces géants, j'en ai acheté un autre. Je l’ai baptisé le Revanche de Smotts, j’ai trouvé un nouvel équipage, j'ai rempli les cales de marchandises, puis j’ai appareillé pour retrouver ces misérables géants. Je les ai trouvés, et de nouveau ils m’ont battu. Ils ont détruit le Revanche de Smotts, tué presque tout mon équipage et jeté les rescapés dans un canot.\n\nCette fois, un autre géant, Negolash, m’a volé mon sabre.\n\nCombattez Negolash et rapportez-moi mon sabre !\n\nParlez à Sprogger. C'était mon cuistot sur le Revanche de Smotts et il a survécu à la dernière attaque. Il peut vous aider à trouver le géant.", progress = nil, completion = "Hello, hello, &lt;nom&gt; ! Le capitaine m'a dit que vous courriez après Negolash, pas vrai ?", rewards = "Vous recevrez :\n\n"},
[8554] = {title = "Face à Negolash", objective = "Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevine dans le Canot de sauvetage du capitaine Smott.\n\nTuer Negolash, et apporter le Coutelas de Smotts au capitaine Smotts, à Strangleronce.", description = "Negolash est un goinfre.\n\nQuand les géants ont détruit notre navire, il est venu directement dans ma cuisine. Il n'avait pas faim d'hommes d'équipage comme les autres géants. Negolash voulait du vin et mes ailes de busard grillées au barbecue. C'est ma spécialité, et j'ai dû me rendre jusqu'aux Terres ingrates pour avoir la recette !\n\nSi vous voulez tendre un piège au géant, trouvez du vin et un monceau d'ailes de busard. Placez-les dans notre vieux canot, au sud-est, le long de la côte. Quand Negolash sentira cette bonne nourriture, il rappliquera, sans aucun doute !", progress = "Avez-vous mon sabre, <nom> ?", completion = "Vous avez repris mon sabre à Negolash ! Je ne peux croire ma bonne fortune, &lt;nom&gt; ! Vous rencontrer a fait tourner ma chance du bon côté, c'est certain !\n\nMerci ! Et si d'aventure j'ai un nouveau navire et que vous cherchez à sillonner les mers, vous serez mon invité d'honneur.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBoussole de Smotts"},
[8555] = {title = "Le fardeau des Vols draconiques", objective = "Eranikus, Vaelastrasz, et Azuregos... Vous avez certainement entendu parler de ces dragons, mortel. Ce n’est pas une simple coïncidence si chacun d’eux a joué un grand rôle comme gardien de ce monde.\n\nMalheureusement, et ma propre naïveté en est en partie responsable, ces gardiens ont tous succombé à de terribles tragédies, si terribles qu’elles ont alimenté ma méfiance à l’égard de votre espèce.\n\nCherchez-les… Et préparez-vous au pire, <race>.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8556] = {title = "Chevalière de force inflexible", objective = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.", description = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques.  Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.\n\nLes pierres précieuses qui ornent les idoles qiraji conviendraient assez bien, car elles sont d’une qualité supérieure.\n\nApportez-moi un anneau et des idoles, et je vous créerai un anneau puissant, <classe>.", progress = "Vous m'avez apporté l'anneau et les matériaux, <nom> ?", completion = "Je vais changer la pierre qui est sertie sur l’anneau, pour que vous puissiez vous en servir. Vous verrez que ses effets seront bien plus… agréables.", rewards = "Vous recevrez :\n\nChevalière de force inflexible"},
[8557] = {title = "Drapé de force inflexible", objective = "Apporter 1 Drapé martial qiraji, 2 Idoles d'onyx, 5 Scarabées d'argent et 5 Scarabées d'os à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <nom>. J’aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <classe>.\n\nJ’ai besoin pour cela d’un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J’ai aussi besoin d’idoles et de scarabées dont je me servirai pour fabriquer le fermoir.\n\nJe vous promets que vous ne serez pas <déçu/déçue>.", progress = "Vous avez apporté les matériaux pour la cape, <nom> ?", completion = "Ah, oui… Ce drapé est impeccable.\n\nPrenez cette cape, &lt;nom&gt;.  Je suis certain que vous la trouverez très utile contre les viles magies des Qiraji.", rewards = "Vous recevrez :\n\nDrapé de force inflexible"},
[8558] = {title = "La faucille de force inflexible", objective = "Apporter 1 Manche à pointes qiraji, 2 Idoles d'albâtre, 5 Scarabées de cristal et 5 Scarabées de pierre au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.", progress = "M'avez-vous apporté les composants dont j'ai besoin, <nom> ?", completion = "Vous vous êtes bien débrouillé, &lt;classe&gt;. Ce manche est un véritable chef-d’œuvre… L’équilibrage est parfait.\n\nPrenez votre arme, &lt;nom&gt;. Maniez-la avec assurance et triomphez de nos ennemis !", rewards = "Vous recevrez :\n\nFaucille de force inflexible"},
[8559] = {title = "Les grèves du Conquérant", objective = "Ramener des Manchettes de commandement qiraji, 2 Idoles de la guerre, 5 Scarabées d’ivoire et 5 Scarabées d’or à Kandrostrasz, à Ahn'Qiraj. Il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de commandement qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.", progress = "Vous êtes-vous procuré les articles que j'ai demandés, <nom> ?", completion = "C’est bien, &lt;nom&gt;. Vous avez prouvé que vous n’êtes pas un mortel ordinaire.\n\nJe vous remets ce don avec la certitude qu’il vous aidera à écraser ces vils Qiraji.", rewards = "Vous recevrez :\n\nGrèves du Conquérant"},
[8560] = {title = "Les cuissards du Conquérant", objective = "Ramener la Peau intacte d’Ouro, 2 Idoles de la mort, 5 Scarabées en bronze et 5 Scarabées d’ivoire à Kandrostrasz, à l’intérieur d’Ahn'Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuissards du Conquérant"},
[8561] = {title = "La couronne du Conquérant", objective = "Ramener le Diadème de Vek’Nilash, 2 Idoles du soleil, 5 Scarabées de pierre et 5 Scarabées de cristal à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.", progress = "M’avez-vous ramené les composants demandés, <nom> ?", completion = "Vous avez réussi ! Les murmures des Empereurs jumeaux ont cessé.\n\nPrenez cette récompense. Sa seule vue sèmera l’épouvante au cœur des Qiraji… Elle leur rappellera leurs défunts chefs et lemortel qui les a tués.", rewards = "Vous recevrez :\n\nCouronne du Conquérant"},
[8562] = {title = "La cuirasse du Conquérant", objective = "Ramener la Carapace du Dieu très ancien, 2 Idoles de la guerre, 5 Scarabées d'argent et 5 Scarabées d'os à Vethsera, à l’intérieur d’Ahn’Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivants. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !", progress = "Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.", completion = "Je ne m’attendais pas à vous voir revenir, &lt;nom&gt;.\n\nVous avez une destinée supérieure à celle de la plupart des immortels.\n\nEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.\n\nAcceptez cette cuirasse comme symbole de la gloire et du fardeau qu’engendrent vos actes.\n\nPuisse son pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !", rewards = "Vous recevrez :\n\nCuirasse du Conquérant"},
[8563] = {title = "La formation de démoniste", objective = "Parlez à l’invocateur Teli’Larien, le maître des démonistes, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes démonistes de l’île de Haut-Soleil sont formés par l’invocateur Teli’Larien. Parlez-lui et voyez ce qu’il peut vous apprendre. Tout ce qu’il enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.\n\nComme tous les maîtres de l’île de Haut-Soleil, Teli’Larien se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.Lors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes démonistes de l’île de Haut-Soleil sont formés par l’invocateur Teli’Larien. Parlez-lui et voyez ce qu’il peut vous apprendre. Tout ce qu’il enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.\n\nComme tous les maîtres de l’île de Haut-Soleil, Teli’Larien se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[8564] = {title = "La formation de prêtre", objective = "Parlez à la matrone Arène, le maître des prêtres, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes prêtres de l’île de Haut-Soleil sont formés par la matrone Arène. Parlez-lui et voyez ce qu’elle peut vous apprendre. Tout ce qu’elle enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.\n\nComme tous les maîtres de l’île de Haut-Soleil, la matrone Arène se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.Lors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes prêtres de l’île de Haut-Soleil sont formés par la matrone Arène. Parlez-lui et voyez ce qu’elle peut vous apprendre. Tout ce qu’elle enseigne a un coût, n’oubliez donc pas d’emporter un peu d’argent.\n\nComme tous les maîtres de l’île de Haut-Soleil, la matrone Arène se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[8565] = {title = "Victoires passées en Arathi", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du bassin d'Arathi"},
[8566] = {title = "Victoires passées en Arathi", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du bassin d'Arathi"},
[8567] = {title = "Victoires passées dans le goulet des Warsong", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du goulet des Warsong"},
[8568] = {title = "Victoires passées dans le goulet des Warsong", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du goulet des Warsong"},
[8569] = {title = "Efforts passés dans le goulet des Warsong", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du goulet des Warsong"},
[8570] = {title = "Efforts passés dans le goulet des Warsong", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque d'honneur du goulet des Warsong"},
[8571] = {title = "<INUTILISÉ> Renforts d'armure", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBon de la foire de Sombrelune"},
[8572] = {title = "La tenue de combat de vétéran", objective = "Ramener 7 Badges cénariens de combat, 4 Badges cénariens de logistique et 4 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.", description = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte du Fort cénarien ne sont pas seulement destinés à faire joli, <nom>.\n\nConservez-les soigneusement. Au fur et à mesure que vous ferez la preuve de votre loyauté envers notre organisation, vous pourrez les échanger contre le matériel que nous réservons à nos alliés les plus proches.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGrâce de la TerreAnneau de puissance terrestreGilet de puissance de la terre"},
[8573] = {title = "Equipement de guerre de champion", objective = "Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 20 Badges cénariens de tactique et 1 Marque de Cénarius à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte du Fort cénarien ne sont pas seulement destinés à faire joli, <nom>.\n\nConservez-les soigneusement. Au fur et à mesure que vous ferez la preuve de votre loyauté envers notre organisation, vous pourrez les échanger contre le matériel que nous réservons à nos alliés les plus proches.", progress = "Dans notre propre intérêt, nos alliés les plus loyaux doivent être bien équipés, <nom>.", completion = "Un travail remarquable, &lt;nom&gt;. Au nom du Cercle cénarien, acceptez ceci. Vous l’avez bien mérité, mon ami !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoing de CénariusCourroux de CénariusChoc de terre\n\nVous recevrez également :\n\n"},
[8574] = {title = "Equipement de guerre de fidèle", objective = "Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 17 Badges cénariens de tactique et 1 Marque de Remulos à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte de l’Imploratrice céleste Proudhorn ne sont pas seulement destinés à faire joli, <nom>.\n\nConservez-les soigneusement. Au fur et à mesure que vous ferez la preuve de votre loyauté envers notre organisation, vous pourrez les échanger contre le matériel que nous réservons à nos alliés les plus proches.", progress = "Dans notre propre intérêt, nos alliés les plus loyaux doivent être bien équipés, <nom>.", completion = "Un travail remarquable, &lt;nom&gt;. Au nom du Cercle cénarien, acceptez ceci. Vous l’avez bien mérité, mon ami !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrassards de FonderocOrbe calme-terreBrassards Furie-du-rocPuissance de Cénarius"},
[8575] = {title = "Le grand livre magique d'Azuregos", objective = "Apporter le Grand livre magique d'Azuregos à Narain Soothfancy, en Tanaris.", description = "Vous ne comprenez pas le moindre mot de ce qui est écrit dans ce livre. Vous ne savez même pas dans quelle langue il est rédigé !", progress = "Ooooh ! Un machin magique qui vibre. C'est pour moi ?", completion = "&lt;Narain examine le document avec enthousiasme.&gt;\n\nExtraordinaire, &lt;race&gt; ! Qu'est-ce que c'est ? Je ne sais pas du tout lire le draconique.", rewards = "Vous recevrez :\n\n"},
[8576] = {title = "La traduction du grand livre", objective = "Chaque chose en son temps, <nom> ! Nous devons d’abord comprendre ce qu’Azuregos a écrit dans ce livre.\n\nVous soutenez qu’il vous a dit de fabriquer une bouée d’arcanite, et que ceci est le schéma qui permet de la faire ? C’est étrange qu’il l’ait écrit en draconique. Ce vieux bouc sait parfaitement que je ne sais pas lire ce charabia.\n\nSi on veut que cela marche, je vais avoir besoin de mes lunettes de divination, d’un poulet de cinq cents livres et du volume II du « Draconique pour les nuls ». Pas forcément dans cet ordre.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8577] = {title = "Stewvul, ex-M.A.P.V.", objective = "Narain Soothfancy veut que vous retrouviez son ex-meilleur ami pour la vie (M.A.P.V.), Stewvul, et que vous repreniez les lunettes de divination que Stewvul lui a volé.", description = "Si je dois traduire ces textes, je vais avoir besoin de mes lunettes de divination.  Malheureusement, elles m’ont été volées il y a quelque temps par mon ex-meilleur ami pour la vie, Stewyul. Il m’a brisé le cœur en cinq morceaux et il m’a abandonné ici.\n\nÀ l’aide de ma fidèle boule de cristal, j’ai réussi à à peu près le localiser. Il se trouve soit au mur de Greymane dans la forêt des Pins argentés, soit de ce qui ressemble à un monde portail en Outreterre, actuellement envahi par la Légion ardente. Vous allez devoir retrouver sa trace et me rapporter mes lunettes, <nom> !", progress = nil, completion = "Je n’y crois pas, il a fini par me retrouver ! J’étais sûr qu’il avait perdu ma trace quand j’étais en Outreterre. Je ne retournerai pas là-bas, &lt;race&gt;, ah, ça non ! J’en ai assez d’être son meilleur ami pour la vie à mi-temps, et son esclave à plein temps.", rewards = "Vous recevrez :\n\n"},
[8578] = {title = "Des lunettes d'observation ? Aucun problème !", objective = "Retrouver les Lunettes de divination de Narain et les rapporter à Narain Soothfancy en Tanaris.", description = "<Vous entendez un soupir de soulagement s’échapper de la caisse.>\n\nVous voulez juste ses lunettes de divination ? Génial ! Y’a pas de problème… Laissez-moi juste une minute pour… Hé ! Où le… Cornegidouille !\n\nBon, ben… J’ai une mauvaise nouvelle… et une très mauvaise nouvelle. La mauvaise nouvelle est que j’ai perdu les lunettes. La très mauvaise est que je les ai perdues quand je me suis promené dans le Cœur du Magma le mois dernier. Ouais, le Cœur du Magma… J’suppose qu’on a fini de faire affaire, maintenant ! Salut !", progress = "Le Cœur du Magma, hein ? J'espère que mes lunettes sont encore en un seul morceau !", completion = "Extraordinaire ! Bon, où est-ce que j'ai mis ce poulet de 500 livres et le volume II du « Draconique pour les nuls » ??? Oh, et voilà un petit quelque chose pour tout le mal que vous vous êtes donné !", rewards = "Vous recevrez :\n\nPotion de régénération majeure"},
[8579] = {title = "Champions mortels", objective = "Nous sentons la présence de nos frères asservis loin dans les profondeurs d’Ahn’Qiraj, mais une armée de dragons ne suffirait pas à les sauver, <race>.\n\nSi nous nous rapprochons d’eux, le sort qui les lie nous jetterait également dans les griffes de C’Thun.\n\nLe Dieu très ancien a prévu notre venue. Tout espoir est perdu. Qu'est-ce qu'un simple mortel comme vous pourrait bien y changer ?", description = nil, progress = "Nous sentons la présence de nos frères asservis loin dans les profondeurs d’Ahn’Qiraj, mais une armée de dragons ne suffirait pas à les sauver, <race>.\n\nSi nous nous rapprochons d’eux, le sort qui les lie nous jetterait également dans les griffes de C’Thun.\n\nLe Dieu très ancien a prévu notre venue. Tout espoir est perdu. Qu'est-ce qu'un simple mortel comme vous pourrait bien y changer ?", completion = "Je vois que vous n’êtes pas un mortel ordinaire, &lt;nom&gt;. Vous avez une chance de triompher du Dieu très ancien. Elle est infime, soit, mais pour l’heure, elle est meilleure que les nôtres. Il s’attend à voir arriver des dragons. Il ne vous attend pas.\n\nIl y a mille ans, Nozdormu et Staghelm ont vaincu les Qiraji grâce à une alliance entre les dragons et les peuples mortels. Nous allons passer un pacte similaire. Gagnez la confiance du Vol de bronze et vous gagnerez notre confiance. Alors, nous ferons de vous un véritable champion.", rewards = "Vous allez être la cible du sort suivant :\n\nRéputation - Boss Temple Ahn'Qiraj\n\nVous recevrez :\n\n"},
[8580] = {title = "La Horde a besoin de fleur de feu !", objective = "Ramener 20 fleurs de feu au chevaucheur de chauve-souris Pele’keiki dans la Vallée des esprits d'Orgrimmar.", description = "Hep, le <classe> ! Oui, vous ! Dites donc voir, la Horde a très beaucoup besoin d’un gros tas de fleur de feu pour cet effort de guerre d’Ahn’Qiraj. Pour les mettre dans des jolies choses qui font boum, p’têt bien. Ou p’têt pour filer aux chars à vapeurs de l’Alliance ? Qui sait ? Pas Pele’keiki, pour sûr !\n\nMais Pele’keiki sait un autre truc… que vous allez l’aider et lui ramener plein de fleurs de feu. Pas vrai ?Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8581] = {title = "La Horde a besoin de plus de fleur de feu !", objective = "Pele’keiki savait que vous reviendriez aider. Ramener encore plus plein de fleurs de feu et lui faire très plaisir. Pele’keiki sait faire de grosses bombes avec fleurs de feu. Alors, quand la guerre commencera, Pele’keiki prendra sa chauve-souris, s’envolera très haut et lâchera les bombes sur les insectes. Mais avant, <classe>, Pele’keiki a besoin de plus de fleurs de feu !\n\nVous ramenez des fleurs de feu à Pele’keiki encore plus fissa. Au moins autant que la dernière fois, et Pele’keiki sera très content.", description = nil, progress = "Pele’keiki savait que vous reviendriez aider. Ramener encore plus plein de fleurs de feu et lui faire très plaisir. Pele’keiki sait faire de grosses bombes avec fleurs de feu. Alors, quand la guerre commencera, Pele’keiki prendra sa chauve-souris, s’envolera très haut et lâchera les bombes sur les insectes. Mais avant, <classe>, Pele’keiki a besoin de plus de fleurs de feu !\n\nVous ramenez des fleurs de feu à Pele’keiki encore plus fissa. Au moins autant que la dernière fois, et Pele’keiki sera très content.", completion = "C’est pas pour rire, &lt;classe&gt; ? Vous avez ramené ses fleurs de feu à Pele’keiki si vite que ça ? Pele’keiki va les compter tout de suite ! Pele’keiki est si content qu’il va dire à tout le monde que &lt;nom&gt; est le meilleur récolteur de fleurs de feu de tous les récolteurs de fleurs de feu. Pele’keiki a très envie que la guerre commence. On mettra le feu au ciel de Silithus, pas vrai, frangin  ?", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8582] = {title = "La Horde a besoin de lotus pourpre !", objective = "Ramener 20 lotus pourpres à l’apothicaire Jezel dans la Vallée des esprits d'Orgrimmar.", description = "Le lotus pourpre sert dans très nombreuses potions, élixirs et huiles, <classe>. Certaines nous seront utiles à Ahn’Qiraj, et nous allons en fabriquer des quantités gigantesques pour l’effort de guerre. Je compte aussi procéder à des expériences pour trouver de nouveaux usages à cette plante. Pour cela, il m’en faut de grandes quantités.\n\nC’est là que vous intervenez. Allez sur le terrain, et ramassez tout le lotus pourpre que vous pourrez. Cette proposition vous convient-elle ?", progress = "Seriez-vous déjà de retour avec le lotus pourpre que je vous avais demandé, <classe> ? Il est très important que vous soyez aussi rapide que possible, sans quoi tout ce que nous avons entrepris ici risque d’échouer.", completion = "Un effort digne d’éloges, &lt;classe&gt;. Je vais analyser ces spécimens pour déterminer leur utilisation optimale, et j’évaluerai votre contribution en fonction. Le lotus pourpre dont nous avons besoin doit être conservé au mieux jusqu’à ce que je sois prête à travailler dessus. Quant à vous, si vous avez encore un peu de temps à me consacrer, je pense qu’il m’en faudra encore. Revenez me voir dans un moment.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8583] = {title = "La Horde a besoin de plus de lotus pourpre !", objective = "Il semble que nous ayons effectivement besoin de davantage de lotus pourpre, <classe>. Mes propres recherches n’ont pas encore porté leurs fruits, mais nous pouvons toujours nous rabattre sur des techniques connues et éprouvées.\n\nJ’ai besoin que vous retourniez sur le terrain et que vous récoltiez au moins vingt échantillons de lotus pourpre. Je vous attends ici.", description = nil, progress = "Il semble que nous ayons effectivement besoin de davantage de lotus pourpre, <classe>. Mes propres recherches n’ont pas encore porté leurs fruits, mais nous pouvons toujours nous rabattre sur des techniques connues et éprouvées.\n\nJ’ai besoin que vous retourniez sur le terrain et que vous récoltiez au moins vingt échantillons de lotus pourpre. Je vous attends ici.", completion = "Un travail à la fois précis et excellent, &lt;nom&gt;. Votre promptitude et votre motivation sont dignes d’éloges. Je veillerai à ce que ce lotus pourpre ne soit pas gaspillé.\n\nMerci encore. Si vous vous procurez d’autres plants de lotus pourpre, n’hésitez pas à venir me trouver aussi vite que possible.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8584] = {title = "On ne parle jamais de mon boulot", objective = "Narain Soothfancy de Tanaris veut que vous parliez à Dirge Quickcleave à Gadgetzan.", description = "Vous devez savoir quelque chose de très important à mon sujet : on ne parle JAMAIS boulot avec moi ! Je m’occupe de choses que vous êtes tout bonnement incapable de comprendre. Du genre : savez-vous ce qu’est un dégobulloneur pyschotronique ? Non, hein ? C’est pour ça que je m’occupe de tracer des plans, et que vous faites les courses.\n\nBon, comme je le disais, pour que ça marche, il nous faut un poulet de 500 livres.\n\nAllez à Gadgetzan et parlez à Dirge Quickcleave, il vous mettra sur la piste d’un spécimen convenable.", progress = nil, completion = "&lt;Dirge se gratte la tête.&gt;\n\nUn poulet de 500 livres ? Ça n’existe pas. Enfin, plus. J’ai entendu parler d’un tel poulet… le poulet noir de la mort…B\n\n&lt;Dirge baisse la voix, puis reprend :&gt;\n\nMais bon, personne n’a jamais vu ce poulet. Personne de vivant, en tout cas. Mais j’ai une autre idée qui pourrait nous être profitable à tous les deux, mon gars.", rewards = "Vous recevrez :\n\n"},
[8585] = {title = "L'île de l'effroi !", objective = "Récupérer la Carcasse de Lakmaeran et 20 Filets de chimaerok pour Dirge Quickcleave, en Tanaris.", description = "D’après les légendes, les chimaeroks de l’île de l’effroi, en Feralas, ont la chair la plus succulente qui soit au monde ! Or, il se trouve que leur papa, convenablement préparé, pourrait bien ressembler à un poulet de 500 livres – ou pas.\n\nAllez sur l’île de l’effroi, tuez le seigneur Lakmaeran et ramenez-moi sa carcasse. Ça, c’est pour le gnome. Quant à moi, je veux quelques filets de chimaeroks.\n\nQuand vous aurez fini, vous aurez un poulet de 500 livres et un petit extra.", progress = "Mmmmm… Des chimaeroks…", completion = "Regardez les nuances de la chair de ces filets ! C’est fantastique !\n\nBon, maintenant, pour ce poulet… Hmm, attendez voir. Il va me falloir quelques minutes pour préparer la recette.", rewards = "Vous recevrez :\n\n"},
[8586] = {title = "Pyro-côtelettes de chimaerok à la Dirge", objective = "Dirge Quickcleave, de Gadgetzan, veut que vous lui rameniez 20 doses de Carburant de fusée des gobelins et 20 doses de Sel de Fonderoc.", description = "Ma recette est au point ! Je m’occupe des épices, et vous m’avez déjà fourni la viande. J’ai juste besoin de carburant pour fusée et de sel de Fonderoc.\n\nLorsque vous m’aurez ramené tout ça, le poulet sera prêt pour Narain.", progress = "Allez, allez, on se dépêche. Faudrait pas que cette viande faisande.", completion = "C’est prêt ! Je vous présente la plus grande de mes créations : les pyro-côtelettes de chimaerok à la Dirge !", rewards = "Vous recevrez :\n\nRecette : Pyro-côtelettes de chimaerok à la DirgePyro-côtelettes de chimaerok à la Dirge"},
[8587] = {title = "Retour vers Narain", objective = "Remettre le Poulet de 500 livres à Narain Soothfancy à Tanaris.", description = "Je suis un gobelin de parole, <mon petit/ma petite>. Voilà votre poulet de 500 livres.\n\nQuant à ce qu’un gnome veut faire d’un poulet de 500 livres, je suppose que je ne le saurai jamais…\n\n<Dirge bougonne quelque chose d’inintelligible…>\n\nDormir dedans, sans doute… Gnomes dégoûtants…", progress = "Quelle est cette odeur bouleversante ?", completion = "&lt;Narain plonge les deux mains dans le poulet géant et commence à se goinfrer du délicieux plat de Dirge.&gt;\n\nMmmmmm…. C’est incroyable ! Jamais mangé de meilleur poulet !", rewards = "Vous recevrez :\n\n"},
[8588] = {title = "La Horde a besoin de cuir lourd !", objective = "Ramener 10 cuirs lourds à l’Ecorcheuse Jamani dans la Vallée des esprits d'Orgrimmar.", description = "Tant qu’à se préparer pour la guerre, mieux vaut avoir tout ce qu’il faut avant, n’est-ce pas <l’ami/ma grande> ? Le cuir lourd est l’une des choses dont nous allons avoir le plus besoin pendant nos préparatifs. Nous allons l’utiliser dans une foule de domaines, pour fabriquer des armures, pour les renforcer… et tout bêtement pour en faire des bâches.\n\nAutant dire qu’il nous en faut beaucoup. Et ça, ce sera votre job, <classe>. Aiguisez votre couteau et ramenez-m’en un paquet. Nous continuerons cette discussion après.", progress = "Si vous êtes juste là pour papoter, vous feriez mieux de dégager, <classe>. J’ai encore des piles et des piles de cuir épais à nettoyer. Revenez me voir lorsque vous en aurez au moins dix morceaux à me donner.", completion = "Oh, alors vous avez le cuir lourd dont j’ai besoin ? Et ce sont d’excellentes peaux, &lt;classe&gt;, votre lame est bien aiguisée ! Bon, maintenant que nous sommes partis du bon pied, vous et moi, je veillerai à ce que votre contribution à la cause soit bien employée. Et si vous tombez sur d’autres morceaux de cuir lourd, revenez me voir.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8589] = {title = "La Horde a besoin de plus de cuir lourd !", objective = "Effectivement, <classe>, il me faut encore du cuir lourd. Les requêtes des généraux et des intendants s’accumulent à toute vitesse. Et ils sont modestes par rapport à ce que demandent les maîtres des zeppelins !\n\nJ’ai besoin que mon quota soit collecté très vite. <nom>, ramenez-moi de nouvelles piles de cuir épais aussi vite que possible !", description = nil, progress = "Effectivement, <classe>, il me faut encore du cuir lourd. Les requêtes des généraux et des intendants s’accumulent à toute vitesse. Et ils sont modestes par rapport à ce que demandent les maîtres des zeppelins !\n\nJ’ai besoin que mon quota soit collecté très vite. <nom>, ramenez-moi de nouvelles piles de cuir épais aussi vite que possible !", completion = "Oh merci l’ami ! Merci infiniment pour tout ce cuir lourd ! Chaque petit morceau nous rapproche du quota. Je vais les mettre sur la pile, pour que les artisans du cuir puissent commencer à travailler dessus.\n\nMerci encore, &lt;nom&gt;. Et si vous trouvez d’autres piles de cuir épais, vous savez où me trouver.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8590] = {title = "La Horde a besoin de cuir épais !", objective = "Ramener 10 morceaux de cuir épais au sergent Umala dans la Vallée des esprits d'Orgrimmar.", description = "Je suis contente que vous ayez décidé de venir me voir, <classe>. On dirait bien que les préparatifs de la Horde pour la guerre d’Ahn’Qiraj atteignent leur point culminant. Mais nous devons encore jouer notre rôle, vous et moi.\n\nJ’ai été chargée de collecter un grand nombre de morceaux de cuir épais, qui servira à fabriquer du matériel. J’ai besoin que vous alliez m’en ramasser. Vous y gagnerez de l’honneur et la gratitude de la Horde. Je compte sur vous ?", progress = "Alors, <classe>, vous êtes déjà de retour ? Avez-vous le cuir épais dont nous avions parlé ?", completion = "Bon travail, &lt;classe&gt;. Je suis sûre que ces morceaux de cuir épais seront précieux pour renforcer les zeppelins et fabriquer toutes sortes d’armes et d’armures. Vous avez mes remerciements et ceux de la Horde. Revenez me voir si, au cours de vos voyages, vous trouvez davantage de cuir épais. Que la chance vous accompagne !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8591] = {title = "La Horde a besoin de plus de cuir épais !", objective = "Comme vous pouvez le voir, il nous davantage de cuir épais, <classe>. Je vous demande votre aide une fois encore. Je vous promets que si vous venez à bout de cette tâche, vos efforts seront reconnus.\n\nLe temps presse ! Revenez vite me voir avec du cuir épais ! Plus tôt vous reviendrez, plus tôt nos préparatifs seront terminés, et plus tôt nous pourrons partir en guerre, héros !", description = nil, progress = "Comme vous pouvez le voir, il nous davantage de cuir épais, <classe>. Je vous demande votre aide une fois encore. Je vous promets que si vous venez à bout de cette tâche, vos efforts seront reconnus.\n\nLe temps presse ! Revenez vite me voir avec du cuir épais ! Plus tôt vous reviendrez, plus tôt nos préparatifs seront terminés, et plus tôt nous pourrons partir en guerre, héros !", completion = "Vous y êtes arrivé &lt;nom&gt; ! Je le savais. Une fois encore, je vous remercie au nom de toute la Horde. Vos efforts ont été notés et grandement appréciés. Si par hasard, vous vous retrouvez avec un excédent de cuir épais, n’hésitez pas revenir me voir. \n\nLok'tar Ogar, &lt;classe&gt; !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8592] = {title = "La tiare de l'Oracle", objective = "Ramener le Diadème de Vek’Nilash, 2 Idoles du sage, 5 Scarabées d'argent et 5 Scarabées d'os à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTiare de l'oracle"},
[8593] = {title = "Le pantalon de l'Oracle", objective = "Ramener la Peau du grand ver des sables, 2 Idoles de la renaissance, 5 Scarabées d'or et 5 Scarabées d'argile à Kandrostrasz, à  l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPantalon de l'oracle"},
[8594] = {title = "Le mantelet de l'Oracle", objective = "Ramener des Manchettes de commandement qiraji, 2 Idoles de la renaissance, 5 Scarabées d'argent et 5 Scarabées d'ivoire à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet de l'oracle"},
[8595] = {title = "Champions mortels", objective = "Tuer un seigneur qiraji représente un succès notable pour un mortel, <nom>. Hélas, ils sont nombreux et puissants. Continuez à les vaincre pour prouver votre valeur en tant que champion.", description = nil, progress = "Tuer un seigneur qiraji représente un succès notable pour un mortel, <nom>. Hélas, ils sont nombreux et puissants. Continuez à les vaincre pour prouver votre valeur en tant que champion.", completion = "Vous continuez à bien nous servir, &lt;nom&gt;. Notre pacte est maintenu.", rewards = "Vous allez être la cible du sort suivant :\n\nRéputation - Boss Temple Ahn'Qiraj"},
[8596] = {title = "Les bottines de l'Oracle", objective = "Ramener des Manchettes de commandement qiraji, 2 Idoles de la mort, 5 Scarabées en bronze et 5 Scarabées d’or à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de commandement qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBottines de l'oracle"},
[8597] = {title = "Le draconique pour les nuls", objective = "Retrouver le livre de Narain Soothfancy, enfoui sur une île des mers du Sud.", description = "Je savais bien que ce livre finirait par me servir ! Heureusement, je suis prévoyant, et j’ai eu le bon sens de le ranger dans un endroit sûr.\n\nNe vous en faites pas, là où il est, personne ne risque de le trouver ! La première fois, il m’a fallu un gyrocoptère pour y aller. Malheureusement, au retour, je me suis écrasé sur la plage. C’est grâce à cet accident que j’ai gagné mes super-pouvoirs pyschiques gnomes !\n\nAllez à la plage du Bout-du-Monde, cherchez l’épave de mon gyrocoptère, et nagez vers le sud ! Vous ne pouvez rater l’endroit !", progress = nil, completion = "Le livre a disparu ! En revanche, il y a une lettre sur la terre fraîchement remuée.", rewards = "Vous recevrez :\n\n"},
[8598] = {title = "rANçOn !", objective = "Ramener la Demande de rançon a Narain Soothfancy, en Tanaris.", description = "<Ce texte est composé de caractères d’imprimerie collés sur un parchemin.>\n\nNous tenons ton livre bien-aimé, gnome. Si tu veux le revoir, tu vas faire tout ce que nous demandons.<\n\nSuivent trois pages d’instructions détaillées.>\n\nAmène l’argent et viens seul !", progress = "Eh bien, que se passe-t-il ?", completion = "&lt;Narain devient écarlate.&gt;\n\nAlors comme ça, ils ont fauché mon livre, hein ? Je vais leur apprendre qu’on ne marche pas sur les pieds d’un gnome doté de pouvoirs psychiques !", rewards = "Vous recevrez :\n\n"},
[8599] = {title = "Une chanson d'amour pour Narain", objective = "Transmettre la Lettre d’amour de Meredith à Narain Soothfancy, en Tanaris.", description = "J’ai très rarement des visiteurs. En fait, je n’avais vu personne depuis la fois où j’ai sauvé ce cher, cher gnome de l’épave de sa machine volante.\n\n<Meredith se plonge dans ses souvenirs, et son regard se perd dans le lointain.>\n\nLe connaissez-vous ? Narain ? Narain Soothfancy ? J’aimerai beaucoup que quelqu’un lui porte un message. Il faut qu’il sache ce que je ressens pour lui ! C’est de l’amour ! J’en suis sûre !\n\nPourriez-vous me servir de messager ? Je vous en serai éternellement reconnaissante !", progress = "Vous sentez le poisson !", completion = "Quoi ?\n\n\n&lt;Narain se met à pianoter.&gt;\n\nEh bien, euh… Qu’est-ce que vous voulez que je fasse ? C’est un poisson ! Un POISSON ! Et je suis un gnome. C’est sans espoir.", rewards = "Vous recevrez :\n\n"},
[8600] = {title = "La Horde a besoin de cuir robuste !", objective = "Ramener 10 morceaux de cuir robuste au docteur Serratus dans la Vallée des esprits d'Orgrimmar.", description = "A mon avis, la manière dont vous tenez le couteau est plus importante que son tranchant. Même très émoussée, une lame peut toujours couper si vous appuyez suffisamment. Mais nous n’avons pas ce problème, vous et moi, car nous connaissons la valeur d’une lame aiguisée, n’est-ce pas, <classe> ?\n\nOh, aucune importance. J’ai du travail pour vous. Pour servir la Horde, et pour jouer votre rôle dans l’effort de guerre d’Ahn’Qiraj, j’ai besoin que vous me rameniez un certain nombre de morceaux de cuir robuste. Est-ce dans vos cordes ?", progress = "Découper ces dix morceaux de cuir robuste pour moi ne devrait pas vous prendre aussi longtemps ! Vous devriez peut-être aiguiser votre couteau à dépecer ? À moins que je ne me trompe et que vous les ayez sur vous ?", completion = "Très bien. C’est un travail passable, même si certaines de ces peaux sont un peu déchiquetées sur les bords. Mais bon, vous avez terminé votre tâche, et vous avez mérité votre récompense. Si vous vous procurez une autre pile de morceaux de cuir robuste, hâtez-vous de me la ramener.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8601] = {title = "La Horde a besoin de plus de cuir robuste !", objective = "Nos préparatifs pour la future guerre d’Ahn’Qiraj se poursuivent, <classe>. Toutefois, afin que nous ne prenions pas de retard, ou au moins pour faire en sorte que le retard ne vienne pas de moi, j’aimerai que vous me rameniez une autre pile de morceaux de cuir robuste. Votre promptitude sera dûment appréciée, <nom>", description = nil, progress = "Nos préparatifs pour la future guerre d’Ahn’Qiraj se poursuivent, <classe>. Toutefois, afin que nous ne prenions pas de retard, ou au moins pour faire en sorte que le retard ne vienne pas de moi, j’aimerai que vous me rameniez une autre pile de morceaux de cuir robuste. Votre promptitude sera dûment appréciée, <nom>", completion = "De l’entraînement, encore de l’entraînement, toujours de l’entraînement. Un couteau bien aiguisé et l’art de s’en servir vous aideront à faire votre chemin dans le monde, &lt;nom&gt;. Les bords de ces morceaux de cuir semblent bien plus réguliers que ceux de votre précédente livraison. Auriez-vous changé de couteau ?\n\nPeu importe. Merci pour vos efforts. Votre don a été enregistré, et je vous promets que nous en ferons bon usage. Si vous entrez en possession d’autres morceaux de cuir robuste, n’hésitez pas à revenir me parler, j’en aurai sans doute encore besoin.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8602] = {title = "Les espauliers de l'implorateur des tempêtes", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles de la vie, 5 Scarabées d'or et 5 Scarabées de cristal à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !", progress = "Vous êtes-vous procuré les composants dont j’ai besoin ?", completion = "Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !", rewards = "Vous recevrez :\n\nEspauliers d'implorateur de tempête"},
[8603] = {title = "Les habits de l'Oracle", objective = "Ramemer la Carcasse du Dieu très ancien, 2 Idoles de la mort, 5 Scarabées de pierre et 5 Scarabées de cristal à Vethsera, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !", progress = "Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.", completion = "Je ne m’attendais pas à vous voir revenir, &lt;nom&gt;.\n\nVous avez une destinée supérieure à celle de la plupart des immortels.\n\nEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.\n\nAcceptez ces habits comme symbole de la gloire et du fardeau qu’engendrent vos actes.\n\nPuisse leur pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !", rewards = "Vous recevrez :\n\nHabit de l'oracle"},
[8604] = {title = "La Horde a besoin de bandages en laine !", objective = "Ramenez 20 bandages en laine au guérisseur Longrunner dans la Vallée des esprits d'Orgrimmar.", description = "Je vous salue, <classe>. Je coordonne les efforts de la Horde pour collecter des bandages en laine, en préparation de la toute prochaine guerre à Ahn’Qiraj. Une fois sur le terrain, nos soldats n’ont pas toujours le luxe d’attendre l’intervention d’un guérisseur pour rester en vie. Croyez-moi, je sais de quoi je parle. Nous leur préparons donc  toutes ces trousses de premiers soins.\n\nSi vous avez le temps, sachez que j’ai besoin de nombreux bandages en laine. Si vous m’en ramenez, je veillerai à ce que vous soyez <récompensé/récompensée>.", progress = "Ah, <classe>. Seriez-vous déjà de retour avec les bandages en laine ?", completion = "Je vous présente mes remerciements, &lt;classe&gt;, et la gratitude la Horde. Si vous souhaitez continuer à contribuer à l’effort de guerre, et si vous vous procurez d’autres bandages en laine, revenez me voir. D’ici là, que vous ancêtres vous gardent !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8605] = {title = "La Horde a besoin de plus de bandages en laine !", objective = "C’est bon de vous revoir, <classe>. Nous continuons à préparer l’effort de guerre, et j’ai toujours besoin de l’assistance que vous pourriez m’apporter dans la collecte de bandages en laine. Toute aide, même minime, sera grandement appréciée. J’espère que nos efforts seront suffisants. J’ai déjà vu trop d’âmes nobles disparaître sur les champs de bataille. Je ferai l’impossible pour que cela ne se produise plus.", description = nil, progress = "C’est bon de vous revoir, <classe>. Nous continuons à préparer l’effort de guerre, et j’ai toujours besoin de l’assistance que vous pourriez m’apporter dans la collecte de bandages en laine. Toute aide, même minime, sera grandement appréciée. J’espère que nos efforts seront suffisants. J’ai déjà vu trop d’âmes nobles disparaître sur les champs de bataille. Je ferai l’impossible pour que cela ne se produise plus.", completion = "Vous êtes un &lt;classe&gt; honorable ! Je veillerai à ce que ces bandages parviennent à bon port. Je vous remercie, pour moi comme pour la Horde.\n\nAllez en paix, &lt;nom&gt;, et ne manquez pas de revenir me voir si vous avez des surplus de bandages en laine. Nous avons vraiment besoin d’aide.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8606] = {title = "Un leurre !", objective = "Narain Soothfancy, en Tanaris, veut que vous vous rendiez au Berceau-de-l’hiver et que vous posiez le Sac d'or à l’endroit indiqué par les voleurs de livres.", description = "Eurêka ! Je sais ce que nous allons faire. Je vais remplir un sac de pierres, et vous allez vous charger de le remettre. Je sais que je suis censé le faire moi-même… et bien c’est ce qui va se passer. En quelque sorte.\n\n<Narain vous examine des pieds à la tête.>\n\nBon bon bon, ça ira. Prenez cette robe, ce turban et ce sac de cailloux, et filez au lieu du rendez-vous, au Berceau-de-l’hiver.\n\nJ’ai mis tout ce dont vous avez besoin dans cette panoplie spéciale. Lorsqu’ils se montreront pour récupérer l’argent… crac, vous leur tombez dessus ! Ça leur apprendra à s’en prendre à Narain !", progress = nil, completion = "J’ai peur que nous n’ayons sous-estimé ces voleurs de livres.", rewards = "Vous recevrez :\n\n"},
[8607] = {title = "La Horde a besoin de bandages en tisse-mage !", objective = "Ramenez 20 bandages en tisse-mage à dame Callow dans la Vallée des esprits d'Orgrimmar.", description = "J’imagine que si vous venez me voir, c’est parce que vous comptez m’aider dans ma collecte ? Très bien. Il faut que vous me rameniez un grand nombre de bandages en tisse-mage. Utilisez tous les moyens, je dis bien tous les moyens, pour vous les procurer. Il serait préférable qu’ils soient frais, mais ce n’est pas indispensable. Ramenez-les-moi ici, <classe>, et je veillerai à ce que vous soyez <récompensé/récompensée> comme il convient.", progress = "N’échouez pas, <classe>, ce serait désastreux pour mon image ! Revenez me voir aussi rapidement que possible avec les bandages en tisse-mage que je vous ai demandés.", completion = "Ils sont acceptables – étonnant. Peut-être avais-je sous-estimé vos ‘capacités’, &lt;classe&gt;. Peut-être. Vous avez accompli une tâche fort simple, pour laquelle vous allez recevoir une récompense disproportionnée. Mais que cela ne vous monte pas à la tête. Si vous voulez vraiment faire vos preuves, vous devriez repartir et me ramener un autre paquet de bandages en tisse-mage.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8608] = {title = "La Horde a besoin de plus de bandages en tisse-mage !", objective = "Vous revoilà ? Intéressant. Comme vous pouvez le voir, je travaille toujours à ma collecte pour “l’effort de guerre” à Ahn’Qiraj. Autrement dit, j’ai besoin que vous alliez me chercher un autre paquet de bandages en tisse-mage. J’attendrai votre retour avec impatience, <classe>.", description = nil, progress = "Vous revoilà ? Intéressant. Comme vous pouvez le voir, je travaille toujours à ma collecte pour “l’effort de guerre” à Ahn’Qiraj. Autrement dit, j’ai besoin que vous alliez me chercher un autre paquet de bandages en tisse-mage. J’attendrai votre retour avec impatience, <classe>.", completion = "Vous y êtes arrivé une nouvelle fois, &lt;classe&gt;. Voilà qui est stupéfiant. Bah, on dit que je sais bien choisir mes serviteurs… Très bien, je noterai votre nom à côté de votre contribution et vous recevrez la considération qui vous est due. Si vous voulez vraiment prouver votre valeur, je vous conseille de repartir et de vous procurer un autre paquet de bandages en tisse-mage.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8609] = {title = "La Horde a besoin de bandages en étoffe runique !", objective = "Ramener 20 bandages en étoffe runique à la Garde de pierre Clayhoof dans la Vallée des esprits d'Orgrimmar.", description = "On pourrait croire que la Horde et l’Alliance se préparent à s’étriper pour Ahn’Qiraj. Mais en réalité, l’affrontement ne les opposera pas. Elles ont des ennemis communs, les silithides... et la force qui les contrôle. Les deux camps font de leur mieux pour récolter les ressources nécessaires à une guerre victorieuse.\n\nJe collecte des bandages en étoffe runique pour les distribuer aux soldats. Mais sans aide - sans votre aide, je n’y arriverai pas. Seriez-vous prêt à m’aider, <classe> ?", progress = "La guerre approche, <classe>. Je vous remercie de consacrer du temps et des efforts à nos collectes. Vous êtes-vous procuré les bandages en étoffe runique dont nous avons parlé ?", completion = "Vous faites honneur à la Horde, &lt;classe&gt;. Merci pour vos efforts, ils sont appréciés ! Je vais empaqueter ces bandages frais et mettre mes comptes à jour, pour voir combien il nous en reste à trouver avant d’atteindre notre objectif. Si vous souhaitez récolter plus de bandages en étoffe runique, n’hésitez pas, je ne bougerai pas.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8610] = {title = "La Horde a besoin de plus de bandages en étoffe runique !", objective = "Chaque instant qui passe nous rapproche d’un embrasement généralisé à Ahn’Qiraj, <classe>. Mais auparavant, nous devons rassembler nos forces et nous préparer afin de survivre à l’offensive des insectes et de leurs maîtres.\n\nSi vous repassez dans la région dans un tout proche avenir, n’hésitez pas à contribuer à nouveau à l’effort de guerre en m’apportant des bandages en étoffe runique.", description = nil, progress = "Chaque instant qui passe nous rapproche d’un embrasement généralisé à Ahn’Qiraj, <classe>. Mais auparavant, nous devons rassembler nos forces et nous préparer afin de survivre à l’offensive des insectes et de leurs maîtres.\n\nSi vous repassez dans la région dans un tout proche avenir, n’hésitez pas à contribuer à nouveau à l’effort de guerre en m’apportant des bandages en étoffe runique.", completion = "C’est un don d’un grand altruisme, &lt;nom&gt;. Ce geste sauvera certainement la vie de nombreux combattants à Ahn’Qiraj. Merci. Sachez que la Horde apprécie ce don. Si vous créez ou si vous vous procurez d’autres bandages en étoffe runique, n’hésitez pas à me les apporter.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8611] = {title = "La Horde a besoin de steaks de loup !", objective = "Ramener 20 steaks de loup à la garde de sang Rawtar dans la Vallée des esprits d'Orgrimmar.", description = "Je n’suis pas là pour bronzer, <classe>. Nous avons une guerre à préparer ! Si nous voulons écraser ces insectes à Ahn’Qiraj, nous devons être prêts, nourriture comprise !\n\nIls m’ont demandé de collecter et de saler des steaks de loup pour les soldats. Mais comme j’suis pas mal occupée ici, j’vous demande de partir, de m’tuer des loups, d’faire cuire leur viande et de m’ramener les steaks. Compris ?", progress = "Déjà de retour avec mes steaks de loup, <classe> ? J’me fiche qu’ils soient brûlés ou tartares, tant qu’ils sont mangeables et que j’les ai vite !", completion = "D’acc, ce tas de viande de loup me va. J’vais saler tout ça et l’empaqueter. Espérons qu’il sera encore mangeable le moment venu. \n\nMerci pour la livraison, &lt;classe&gt;. Ça vous dirait de m’en ramener une autre plâtrée ?", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8612] = {title = "La Horde a besoin de plus de steaks de loup !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8613] = {title = "La Horde a besoin de jaunes-queues tachetés !", objective = "Ramener 20 jaunes-queues tachetés au pêcheur Lin’do dans la Vallée des esprits d'Orgrimmar.", description = "Ça va être une sacrée bonne journée pour pêcher, s’pas $gl’ami:ma grande ? Et c’est une sacrée bonne chose, passqu’on dirait ben que j’vais avoir besoin de plein de poiscaille ! La Horde, elle m’a demandé d’me charger de la collecte de tonnes et de tonnes de jaunes-queues tachetés ! Y paraît qu’elle va en avoir besoin pour la guerre qu’elle prépare à Ahn’Qiraj. Moi, j’y ai dit qu’j’aillais faire d’mon mieux. Mais j’vais avoir besoin d’aide. Vous allez m’aider, <classe> ?", progress = "Z’êtes déjà d’retour avec les jaunes-queues tachetés, <classe> ? Vous z’avez pas oublié de les cuire, au moins ? Passqu’on va pas servir du poisson cru aux soldats, pas en plein désert avec tout ce soleil, mon gars.", completion = "Oh oué, c’est du bon ! J’vais l’empaqueter bien-bien, comme ça y s’gâchera pas. Merci d’m’avoir aidé. Pour moi, pas de doute, avec tous ces jaunes-queues tachetés, vous êtes un super-pêcheur de choc. Et si vous en pêchez et qu’vous en faites cuire d’autres, amenez toujours, je veillerai à c’que tout le monde le sache.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8614] = {title = "La Horde a besoin de plus de jaunes-queues tachetés !", objective = "Comme vous voyez, y nous faut encore plein de poiscaille. Les gars qui s’battront à Ahn’Qiraj, il va leur falloir beaucoup à manger, alors faut qu’j’aie tous les jaunes-queues tachetés que j’peux. Vous les prenez, vous les cuisez, vous m’les ram’nez, et moi, j’vous dis « merci », pour moi et pour la Horde.", description = nil, progress = "Comme vous voyez, y nous faut encore plein de poiscaille. Les gars qui s’battront à Ahn’Qiraj, il va leur falloir beaucoup à manger, alors faut qu’j’aie tous les jaunes-queues tachetés que j’peux. Vous les prenez, vous les cuisez, vous m’les ram’nez, et moi, j’vous dis « merci », pour moi et pour la Horde.", completion = "Vos plus belles prises, &lt;nom&gt; ! Du bon, du beau boulot, pour sûr. Et pas d’arêtes, en plus. Merci d’avoir pris la peine de pêcher tous ces jaunes-queues tachetés, ma grande. Si vous en cuisez d’autres, revenez m’voir !", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8615] = {title = "La Horde a besoin de pains de saumon !", objective = "Ramener 20 pains de saumon au chef Sharpclaw dans la Vallée des esprits d'Orgrimmar.", description = "L’effort de guerre pour Ahn’Qiraj est une entreprise colossale, <classe>. Tout ce qui est collecté ici est de la plus haute importance, qu’il s’agisse de métal pour les armes ou de nourriture. Car lorsque vous n’avez pas mangé depuis plusieurs jours et que vous êtes faible comme un nouveau-né, votre hache ne vous sert plus à grand-chose.\n\nEt donc, nous collectons autant de nourriture que possible. Je m’occupe du pain de saumon, un plat à la fois nourrissant et facile à conserver. M’aiderez-vous dans cette tâche, <classe> ?", progress = "M’avez-vous ramené ces pains de saumon, <classe> ? Souvenez-vous, ils doivent être cuits, car malheureusement, je ne pourrai pas me charger de saumons crus.", completion = "Merci d’avoir participé à l’effort de guerre, &lt;classe&gt;. Bien des gens auraient choisi d’ignorer nos besoins, optant à la place pour le profit. Mais contrairement à vous, ceux-là ne bénéficieront pas de la gratitude de la Horde. Leurs cœurs sont vides, alors que le vôtre doit être empli de la satisfaction qui naît d’un don vraiment altruiste.\n\nUne fois encore, merci. Si vous trouvez le temps de nous aider une nouvelle fois avant que nos préparatifs soient achevés, vous me trouverez ici.", rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8616] = {title = "La Horde a besoin de plus de pains de saumon !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière de mérite de la HordeFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8617] = {title = "La Horde a besoin de pierres de Magma !", objective = "Ramener 50 Pierres de Magma roussies au général Zog, en Durotar.", description = "Il est temps que vous contribuiez à l’effort de guerre d’Ahn’Qiraj, <classe>. L’époque où vous pouviez vous tourner les pouces et profiter de vos loisirs est terminée. Maintenant, vous allez servir la Horde et me servir. Je vous assure que je suis beaucoup moins tolérant que le Chef de guerre.\n\nVous allez rassembler vos forces, votre guilde si vous en avez une, et vous allez envahir le Cœur du Magma. Les créatures qui y vivent détiennent des pierres de Magma roussies. Vous allez m’en ramener, et beaucoup.", progress = nil, completion = nil, rewards = nil},
[8618] = {title = "La Horde a besoin de plus de pierres du Magma roussies !", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8619] = {title = "L'Ancien Morndeep", objective = "Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, <nom>, et vous offre ce gage de mon estime…", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8620] = {title = "Le seul remède", objective = "Retrouver les 8 chapitres perdus du \"Draconique pour les nuls\" et les combiner avec la Reliure magique, puis ramener l’exemplaire réparé du \"Draconique pour les nuls, volume II\" à Narain Soothfancy, en Tanaris.", description = "J’aurais dû m’en douter ! Mon ennemi juré, le docteur Weavil, a récidivé ! Et maintenant, à cause de votre échec au Berceau-de-l’hiver, le docteur Weavil a détruit mon livre ! Comment allez-vous sauver le monde, maintenant ?\n\nD’après le message que j’ai reçu, l’unique exemplaire connu du \"Draconique pour les nuls, volume II\" a été divisé en huit morceaux et dispersé aux quatre vents ! Si par miracle vous parvenez à les récupérer, utilisez cette reliure magique pour les réunir et ramenez-les-moi.", progress = "Vous savez, je mets mon pantalon exactement comme vous, une jambe à la fois. Mais quand j’ai mon pantalon, je fabrique des bouées d’arcanite. Des bouées d’arcanites, mon gars !", completion = "Fantastique ! Je n’arrive pas à croire que vous vous soyez donné tout ce mal ! Vous êtes quoi, une sorte de machine ? À votre place, j’aurais laissé le monde imploser.\n\nJe vous tire mon turban, messire ! Et toute bonne action mérite une récompense.", rewards = "Vous recevrez :\n\nTurban gnome de puissance psychique"},
[8621] = {title = "Les bottes d'implorateur de tempête", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles du sage, 5 Scarabées en bronze et 5 Scarabées d'argile à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de domination qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBottes d'implorateur de tempête"},
[8622] = {title = "Le haubert d'implorateur de tempête", objective = "Apporter la Carapace du Dieu très ancien, 2 Idoles du sage, 5 Scarabées d'argent et 5 Scarabées d'os à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nHaubert d'implorateur de tempête"},
[8623] = {title = "Le diadème d'implorateur de tempête", objective = "Apporter le Diadème de Vek'lor, 2 Idoles de la renaissance, 5 Scarabées de pierre et 5 Scarabées de cristal à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nDiadème d'implorateur de tempête"},
[8624] = {title = "Les jambières d'implorateur de tempête", objective = "Rapporter la Peau du Grand ver des sables, 2 Idoles de la lutte, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières d'implorateur de tempête"},
[8625] = {title = "Les protège-épaules de l'énigme", objective = "Rapporter des Manchettes de commandement qiraji, 2 Idoles de la renaissance, 5 Scarabées d'argent et 5 Scarabées d’ivoire à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !", progress = "Vous êtes-vous procuré les composants dont j’ai besoin ?", completion = "Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !", rewards = "Vous recevrez :\n\nProtège-épaules de l'énigme"},
[8626] = {title = "Les bottes du Frappeur", objective = "Rapporter des Manchettes de commandement qiraji, 2 Idoles de la vie, 5 Scarabées de pierre et 5 Scarabées d’os à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon.\n\nSi vous me ramenez des manchettes de commandement qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.", progress = "Vous êtes-vous procuré les articles que j'ai demandés, <nom> ?", completion = "C’est bien, &lt;nom&gt;. Vous avez prouvé que vous n’êtes pas une mortelle ordinaire.\n\nJe vous remets ce don avec la certitude qu’il vous aidera à écraser ces vils Qiraji.", rewards = "Vous recevrez :\n\nBottes du Frappeur"},
[8627] = {title = "La cuirasse du Vengeur", objective = "Apporter la Carapace du Dieu très ancien, 2 Idoles du sage, 5 Scarabées d'argent et 5 Scarabées d'os à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuirasse du Vengeur"},
[8628] = {title = "La couronne du Vengeur", objective = "Apporter le Diadème de Vek'lor, 2 Idoles de la renaissance, 5 Scarabées de pierre et 5 Scarabées de cristal à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouronne du Vengeur"},
[8629] = {title = "Les cuissards du Vengeur", objective = "Rapporter la Peau du Grand ver des sables, 2 Idoles de la lutte, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuissards du Vengeur"},
[8630] = {title = "Les espauliers du Vengeur", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles de la vie, 5 Scarabées de cristal et 5 Scarabées d'or à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nEspauliers du Vengeur"},
[8631] = {title = "Les jambières de l'énigme", objective = "Rapporter la Peau intacte d'Ouro, 2 Idoles du sage, 5 Scarabées d'argent et 5 Scarabées d'os à Kandrostrasz, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières de l'énigme"},
[8632] = {title = "Le diadème de l'énigme", objective = "Apporter le Diadème de Vek'nilash, 2 Idoles de la nuit, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.", progress = "M’avez-vous ramené les composants demandés, <nom> ?", completion = "Vous avez réussi ! Les murmures des Empereurs jumeaux ont cessé.\n\nPrenez cette récompense. Sa seule vue sèmera l’épouvante au cœur des Qiraji… Elle leur rappellera leurs défunts chefs et lemortel qui les a tués.", rewards = "Vous recevrez :\n\nDiadème de l'énigme"},
[8633] = {title = "La robe de l'énigme", objective = "Apporter la Carcasse du Dieu très ancien, 2 Idoles du soleil, 5 Scarabées d'or et 5 Scarabées d'argile à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !", progress = "Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.", completion = "Je ne m’attendais pas à vous voir revenir, &lt;nom&gt;.\n\nVous avez une destinée supérieure à celle de la plupart des immortels.\n\nEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.\n\nAcceptez cette robe comme symbole de la gloire et du fardeau qu’engendrent vos actes.\n\nPuisse son pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !", rewards = "Vous recevrez :\n\nRobe de l'énigme"},
[8634] = {title = "Les bottes de l'énigme", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles du soleil, 5 Scarabées d'argent et 5 Scarabées de cristal à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de domination qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.", progress = "Vous êtes-vous procuré les articles que j'ai demandés, <nom> ?", completion = "C’est bien, &lt;nom&gt;. Vous avez prouvé que vous n’êtes pas un mortel ordinaire.\n\nJe vous remets ce don avec la certitude qu’il vous aidera à écraser ces vils Qiraji.", rewards = "Vous recevrez :\n\nBottes de l'énigme"},
[8635] = {title = "L'Ancien Splitrock", objective = "Les batailles des âges anciens sont les graines des légendes du présent. Vous vivez en un temps de héros, mon enfant. Puisse votre légende s’enraciner et prospérer !\n\nJe vous souhaite bonne chance, <nom>, et vous offre ce gage de mon estime…", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8636] = {title = "L'Ancien Rumblerock", objective = "La substance de la vie est condamnée à mourir et à retourner à la terre, mais la substance de l’esprit est éternelle. Je vous souhaite bonne chance, <nom>, et vous offre ce gage de mon estime….", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8637] = {title = "Les bottes du dispensateur de mort", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles de la lutte, 5 Scarabées de cristal et 5 Scarabées d'os à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon.\n\nSi vous me ramenez des manchettes de commandement qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.", progress = "Vous êtes-vous procuré les articles que j'ai demandés, <nom> ?", completion = "C’est bien, &lt;nom&gt;. Vous avez prouvé que vous n’êtes pas un mortel ordinaire.\n\nJe vous remets ce don avec la certitude qu’il vous aidera à écraser ces vils Qiraji.", rewards = "Vous recevrez :\n\nBottes de dispensateur de mort"},
[8638] = {title = "Le gilet du dispensateur de mort", objective = "Apporter la Carapace du Dieu très ancien, 2 Idoles de la lutte, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !", progress = "Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.", completion = "Je ne m’attendais pas à vous voir revenir, &lt;nom&gt;.\n\nVous avez une destinée supérieure à celle de la plupart des immortels.\n\nEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.\n\nAcceptez ce plastron comme symbole de la gloire et du fardeau qu’engendrent vos actes.\n\nPuisse son pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !", rewards = "Vous recevrez :\n\nGilet de dispensateur de mort"},
[8639] = {title = "Le casque du dispensateur de mort", objective = "Apporter le Diadème de Vek'lor, 2 Idoles de la guerre, 5 Scarabées d'or et 5 Scarabées d'argile à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.", progress = "M’avez-vous ramené les composants demandés, <nom> ?", completion = "Vous avez réussi ! Les murmures des Empereurs jumeaux ont cessé.\n\nPrenez cette récompense. Sa seule vue sèmera l’épouvante au cœur des Qiraji… Elle leur rappellera leurs défunts chefs et lemortel qui les a tués.", rewards = "Vous recevrez :\n\nCasque de dispensateur de mort"},
