[8654] = {title = "L'Ancien Primestone", objective = "Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, <nom>, et vous offre ce gage de mon estime…", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8655] = {title = "Les grèves du Vengeur", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles du sage, 5 Scarabées en bronze et 5 Scarabées d'argile à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de domination qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGrèves du Vengeur"},
[8656] = {title = "Le haubert du Frappeur", objective = "Apporter la Carapace du Dieu très ancien, 2 Idoles de la vie, 5 Scarabées d'or et 5 Scarabées d'argile à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nHaubert du Frappeur"},
[8657] = {title = "Le diadème du Frappeur", objective = "Apporter le Diadème de Vek'lor, 2 Idoles de la lutte, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.", progress = "M’avez-vous ramené les composants demandés, <nom> ?", completion = "Vous avez réussi ! Les murmures des Empereurs jumeaux ont cessé.\n\nPrenez cette récompense. Sa seule vue sèmera l’épouvante au cœur des Qiraji… Elle leur rappellera leurs défunts chefs et la mortelle qui les a tués.", rewards = "Vous recevrez :\n\nDiadème du Frappeur"},
[8658] = {title = "Les jambières du Frappeur", objective = "Rapporter la Peau du Grand ver des sables, 2 Idoles du soleil, 5 Scarabées d'argent et 5 Scarabées d'os à Kandrostrasz, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nJambières du Frappeur"},
[8659] = {title = "Les espauliers du Frappeur", objective = "Rapporter des Manchettes de commandement qiraji, 2 Idoles de la guerre, 5 Scarabées de cristal et 5 Scarabées d'ivoire à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nEspauliers du Frappeur"},
[8660] = {title = "Les bottines d'implorateur funeste", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles de la nuit, 5 Scarabées d'argile et 5 Scarabées d'ivoire à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu’ils feraient hésiter un dragon. Si vous me ramenez des manchettes de domination qiraji et quelques autres composants mineurs, je vous fabriquerai des bottes exceptionnelles.\n\nVous les trouverez utiles pour affronter l’ennemi.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBottines d'implorateur funeste"},
[8661] = {title = "La robe d'implorateur funeste", objective = "Apporter la Carcasse du Dieu très ancien, 2 Idoles de la nuit, 5 Scarabées de pierre et 5 Scarabées de cristal à Vethsera à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu.", description = "L’indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn’Qiraj. Le destin atroce qui attend Azeroth peut s’abattre sur nous dans des jours, ou des années, car le temps n’a pas vraiment de sens pour lui.\n\nMais lorsque les étoiles seront propices, il se déchaînera, et son effroyable courroux s’abattra sur toutes les créatures vivantes. Trouvez-le avant qu’il ne soit trop tard, et mettez un terme à son existence, d’une manière ou d’une autre.\n\nSi vous y parvenez, ramenez-moi un morceau de sa carcasse, et je vous en ferai une armure qui n’a encore jamais été portée par aucun mortel… une armure digne <d’un tueur/d’une tueuse> de dieu !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe d'implorateur funeste"},
[8662] = {title = "Le diadème d'implorateur funeste", objective = "Apporter le Diadème de Vek'nilash, 2 Idoles de la mort, 5 Scarabées d'argent et 5 Scarabées d'os à Andorgos à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.\n\nDans mes visions, leurs visages monstrueux sont surmontés d’impressionnantes couronnes. Mais j’aurai ma revanche… Je transformerai ces symboles de la puissance des Qiraji en quelque chose de plus adapté à notre lutte.\n\nRamenez-moi les composants dont j’ai besoin, <nom>, et je vous donnerai une coiffure sans égale.", progress = "M’avez-vous ramené les composants demandés, <nom> ?", completion = "Vous avez réussi ! Les murmures des Empereurs jumeaux ont cessé.\n\nPrenez cette récompense. Sa seule vue sèmera l’épouvante au cœur des Qiraji… Elle leur rappellera leurs défunts chefs et lemortel qui les a tués.", rewards = "Vous recevrez :\n\nDiadème d'implorateur funeste"},
[8663] = {title = "Le pantalon d'implorateur funeste", objective = "Rapporter la Peau du Grand ver des sables, 2 Idoles de la renaissance, 5 Scarabées d'or et 5 Scarabées d'argile à Kandrostrasz, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.", description = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement.\n\nIl existe un très ancien ver des sables d’une puissance légendaire, nommé Ouro. On dit qu’il a été créé par les Dieux très anciens eux-mêmes pour parodier la vie.\n\nSa peau n’a rien de naturel… épaisse et presque impossible à transpercer, mais souple et lui permettant de se déplacer aussi vite et gracieusement que des créatures beaucoup plus petites.\n\nRamenez-moi un échantillon de cette peau et quelques autres composants mineurs, et je vous fabriquerai des jambières d’un grand pouvoir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPantalon d'implorateur funeste"},
[8664] = {title = "Le mantelet d'implorateur funeste", objective = "Rapporter des Manchettes de domination qiraji, 2 Idoles du sage, 5 Scarabées en bronze et 5 Scarabées d'os à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard.", description = "Nous pensons qu’à l’origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.\n\nRamenez-moi les manchettes portées par les plus hauts dignitaires qiraji, et je les façonnerai pour en faire des espauliers plus redoutables que les ailes de Nefarian lui-même !", progress = "Vous êtes-vous procuré les composants dont j’ai besoin ?", completion = "Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !", rewards = "Vous recevrez :\n\nMantelet d'implorateur funeste"},
