[8687] = {title = "Objectif : les tunnelières de la Ruche'Zora", objective = "Tuez 30 Tunnelières de la Ruche’Zora puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat VII.", description = "Nous avons demandé à ce que des renforts rejoignent l’assaut sur la Ruche’Zora. Vous avez été <choisi/choisie> pour affronter les tunnelières de la Ruche'Zora. À la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Excellent travail, &lt;nom&gt;. Sans leurs tunnelières, les silithides vont avoir du mal à réparer les dégâts infligés à la structures de leur ruche. Je suppose que vous voulez une nouvelle tâche ?", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8688] = {title = "L'Ancien Windrun", objective = "Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, <nom>. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8689] = {title = "Le voile de sagesse infinie", objective = "Apporter 1 Drapé martial qiraji, 2 Idoles de jaspe, 5 Scarabées d'or et 5 Scarabées d'argile à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <nom>. J’aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <classe>.\n\nJ’ai besoin pour cela d’un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J’ai aussi besoin d’idoles et de scarabées dont je me servirai pour fabriquer le fermoir.\n\nJe vous promets que vous ne serez pas <déçu/déçue>.", progress = "Vous avez apporté les matériaux pour la cape, <nom> ?", completion = "Ah, oui… Ce drapé est impeccable.\n\nPrenez cette cape, &lt;nom&gt;.  Je suis certain que vous la trouverez très utile contre les viles magies des Qiraji.", rewards = "Vous recevrez :\n\nVoile de sagesse infinie"},
[8690] = {title = "La cape de la tempête imminente", objective = "Apporter 1 Drapé royal qiraji, 2 Idoles d’obsidienne, 5 Scarabées d'argile et 5 Scarabées d'or à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <nom>. J’aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <classe>.\n\nJ’ai besoin pour cela d’un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J’ai aussi besoin d’idoles et de scarabées dont je me servirai pour fabriquer le fermoir.\n\nJe vous promets que vous ne serez pas <déçu/déçue>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCape de la tempête imminente"},
[8691] = {title = "Le drapé des secrets scellés", objective = "Apporter 1 Drapé martial qiraji, 2 Idoles d'albâtre, 5 Scarabées de pierre et 5 Scarabées de cristal à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <nom>. J’aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <classe>.\n\nJ’ai besoin pour cela d’un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J’ai aussi besoin d’idoles et de scarabées dont je me servirai pour fabriquer le fermoir.\n\nJe vous promets que vous ne serez pas <déçu/déçue>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nDrapé des secrets scellés"},
