[8696] = {title = "La cape du sentier invisible", objective = "Apporter 1 Drapé royal qiraji, 2 Idoles brillantes, 5 Scarabées de pierre et 5 Scarabées de cristal à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.", description = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <nom>. J’aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <classe>.\n\nJ’ai besoin pour cela d’un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J’ai aussi besoin d’idoles et de scarabées dont je me servirai pour fabriquer le fermoir.\n\nJe vous promets que vous ne serez pas <déçu/déçue>.", progress = "Vous avez apporté les matériaux pour la cape, <nom> ?", completion = "Ah, oui… Ce drapé est impeccable.\n\nPrenez cette cape, &lt;nom&gt;.  Je suis certain que vous la trouverez très utile contre les viles magies des Qiraji.", rewards = "Vous recevrez :\n\nCape du sentier invisible"},
[8697] = {title = "L' anneau de sagesse infinie", objective = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d’obsidienne, 5 Scarabées d’argent et 5 Scarabées d’os à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.", description = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques.  Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.\n\nLes pierres précieuses qui ornent les idoles qiraji conviendraient assez bien, car elles sont d’une qualité supérieure.\n\nApportez-moi un anneau et des idoles, et je vous créerai un anneau puissant, <classe>.", progress = "Vous m'avez apporté l'anneau et les matériaux, <nom> ?", completion = "Je vais changer la pierre qui est sertie sur l’anneau, pour que vous puissiez vous en servir. Vous verrez que ses effets seront bien plus… agréables.", rewards = "Vous recevrez :\n\nAnneau de sagesse infinie"},
[8698] = {title = "L'anneau de la tempête imminente", objective = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles vermillon, 5 Scarabées d’argent et 5 Scarabées d'os à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.", description = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques.  Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.\n\nLes pierres précieuses qui ornent les idoles qiraji conviendraient assez bien, car elles sont d’une qualité supérieure.\n\nApportez-moi un anneau et des idoles, et je vous créerai un anneau puissant, <classe>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAnneau de la tempête imminente"},
