[8704] = {title = "La chevalière du sentier invisible", objective = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d’ambre, 5 Scarabées d’or et 5 Scarabées d'argile à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.", description = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques.  Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.\n\nLes pierres précieuses qui ornent les idoles qiraji conviendraient assez bien, car elles sont d’une qualité supérieure.\n\nApportez-moi un anneau et des idoles, et je vous créerai un anneau puissant, <classe>.", progress = "Vous m'avez apporté l'anneau et les matériaux, <nom> ?", completion = "Je vais changer la pierre qui est sertie sur l’anneau, pour que vous puissiez vous en servir. Vous verrez que ses effets seront bien plus… agréables.", rewards = "Vous recevrez :\n\nChevalière du sentier invisible"},
[8705] = {title = "Le marteau de sagesse infinie", objective = "Apporter 1 Manche orné qiraji, 2  Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.", progress = "M'avez-vous apporté les composants dont j'ai besoin, <nom> ?", completion = "Vous vous êtes bien débrouillé, &lt;classe&gt;. Ce manche est un véritable chef-d’œuvre… L’équilibrage est parfait.\n\nPrenez votre arme, &lt;nom&gt;. Maniez-la avec assurance et triomphez de nos ennemis !", rewards = "Vous recevrez :\n\nMarteau de sagesse infinie"},
[8706] = {title = "Le marteau de la tempête imminente", objective = "Apporter 1 Manche à pointes qiraji, 2  Idoles d’ambre, 5 Scarabées d’ivoire et 5 Scarabées en bronze au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarteau de la tempête imminente"},
