[8709] = {title = "La dague des ombres voilées", objective = "Apporter 1 Manche à pointes qiraji, 2  Idoles vermillon, 5 Scarabées d’or et 5 Scarabées d’argile au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.", progress = "M'avez-vous apporté les composants dont j'ai besoin, <nom> ?", completion = "Vous vous êtes bien débrouillé, &lt;classe&gt;. Ce manche est un véritable chef-d’œuvre… L’équilibrage est parfait.\n\nPrenez votre arme, &lt;nom&gt;. Maniez-la avec assurance et triomphez de nos ennemis !", rewards = "Vous recevrez :\n\nDague des ombres voilées"},
[8710] = {title = "Le kriss des noms inexprimés", objective = "Apporter 1 Manche orné qiraji, 2 Idoles d'onyx, 5 Scarabées d’or et 5 Scarabées d’argile au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.", progress = "M'avez-vous apporté les composants dont j'ai besoin, <nom> ?", completion = "Vous vous êtes bien débrouillé, &lt;classe&gt;. Ce manche est un véritable chef-d’œuvre… L’équilibrage est parfait.\n\nPrenez votre arme, &lt;nom&gt;. Maniez-la avec assurance et triomphez de nos ennemis !", rewards = "Vous recevrez :\n\nKriss des noms inexprimés"},
[8711] = {title = "La lame de justice éternelle", objective = "Apporter 1 Manche à pointes qiraji, 2  Idoles d'ambre, 5 Scarabées en bronze et 5 Scarabées d'ivoire au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nLame de justice éternelle"},
[8712] = {title = "La faux du sentier invisible", objective = "Apporter 1 Manche à pointes qiraji, 2 Idoles azur, 5 Scarabées d’argent et 5 Scarabées d’os au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.", description = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.\n\nLa simple vue d'artefacts qiraji me donne une envie folle de pratiquer mon art en utilisant leurs pièces brisées ou fondues. Si vous prouvez votre allégeance au Cercle, <nom>, je vous fabriquerai une arme puissante dans les matériaux qiraji les plus fins.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nFaux du sentier invisible"},
[8713] = {title = "L'Ancienne Starsong", objective = "Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, <nom>. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8714] = {title = "L'Ancienne Moonstrike", objective = "Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, <nom>. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.Vous allez être la cible du sort suivant :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
