[8727] = {title = "L'Ancien Farwhisper", objective = "Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, <nom>. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8728] = {title = "La bonne nouvelle et la mauvaise nouvelle", objective = "Narain Soothfancy, en Tanaris, veut que vous lui apportiez 20 Barres d’arcanite, 10 Minerais d’élémentium, 10 Diamants d’Azeorth et 10 Saphirs bleus", description = "Eh bien, cela a pris un peu plus de temps que je ne le croyais. Voyons voir maintenant ce que dit ce livre.\n\n<Narain lit silencieusement le grimoire, marmonnant de temps en temps dans sa barbe.>\n\nLa bonne nouvelle est que je suis certain à 99% d’être en mesure de créer une bouée d’arcanite qui fonctionnera selon vos spécifications. Cela dépend, bien sûr, complètement de la mauvaise nouvelle. La mauvaise nouvelle est que je vais avoir besoin de beaucoup de minerai d’arcanite et d’élémentium, et de pierres précieuses rares.\n\nApportez-moi tout ce dont j’ai besoin et je fabriquerai votre bouée.", progress = "Les bouées d’arcanite ne se fabriquent pas toutes seules, <nom>. Et NON, vous ne pouvez pas m’emprunter de l’argent.", completion = "Un marché est un marché. J’espère simplement que vous savez dans quoi vous vous engagez, &lt;nom&gt;. C’est vraiment se donner beaucoup de mal pour une simple partie de pêche.", rewards = "Vous recevrez :\n\n"},
[8729] = {title = "Le courroux de Neptulon", objective = "Utilisez la Bouée d’arcanite au Maelström tourbillonnant dans la Baie des tempêtes en Azshara.", description = "Je ne vous ai pas encore dit qu’elle était la mauvaise nouvelle ? Elle s’appelle Crocs-de-la-mer : trente mètres de mort et de destruction. J’avais peut-être oublié de mentionner ce point de détail.\n\nD’après mon extraordinaire clairvoyance psycho-psionique, le meilleur endroit pour lancer cette bouée est la côte d’Azshara, dans la Baie des tempêtes.\n\nCherchez un maelström tourbillonnant, qui sera probablement encombré de débris.\n\nau fait, j’espère que vous avez de bons amis.\n\nBon, si par miracle vous réussissez, apportez le fragment de sceptre à Anachronos.", progress = "Le temps presse, champion.", completion = "Bien joué, &lt;nom&gt;. Je serai bientôt capable de refaçonner le sceptre des Sables changeants.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAnneau des profondeurs glacéesRobe des eaux sombres\n\nVous recevrez également :\n\n"},
[8730] = {title = "La corruption de Nefarius", objective = "Tuez Nefarian pour récupérer le Fragment de sceptre rouge. Rapportez le Fragment de sceptre rouge à Anachronos aux Grottes du temps en Tanaris. Vous avez 5 heures pour accomplir cette tâche.", description = "Champion, est-ce bien vous ? Un millier d’années se sont écoulées depuis que le fragment m’a été confié, et c’est à mon heure la plus sombre que quelqu’un se présente pour me le réclamer… Mais que serait une tragédie sans cruauté ?\n\n< Vaelastrasz tousse faiblement.>\n\nNe… Nefarius détient aujourd’hui le fragment du sceptre.\n\nLe temps presse.  Nefarius a l’intention de détruire le fragment. Vous devez vous hâter !", progress = "Un autre de nos héros succombe sous les griffes du rejeton de l'Aile de mort. Cette douleur nous affligera-t-elle à jamais… ?", completion = "L’âme de Vaelastrasz repose en paix, champion. Tous les Aspects observent vos progrès avec un grand intérêt. Sachez que vous avez de puissants alliés.\n\nJ’ai reçu l’ordre de vous offrir quelque chose pour vous aider dans votre lutte. Faites-en bon usage…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières enchâssées d'onyxAmulette de bouclier contre l'ombre\n\nVous recevrez également :\n\n"},
[8731] = {title = "Votre affectation", objective = "Allez vous présenter à Krug Skullsplit, au poste de la légion d’Orgrimmar devant la Ruche’Regal. Préparez votre Ordre de mission, obtenez un Ordre de mission signé et apportez-le à l’Implorateur céleste Kaldon au Fort cénarien\n\nNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la légion d’Orgrimmar vous infligera un marqueur JcJ.", description = "Salutations, <nom>. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne. \n\nVous trouverez la légion d’Orgrimmar, commandée par le capitaine Skullsplit, à l’extérieur de Ruche’Regal.\n\nAllez vous présenter à lui et revenez me voir avec une preuve de votre engagement.  Je vous aurai alors préparé des missions plus délicates.\n\nOh, et ne restez pas à côté de la brigade d’Ironforge.  Les tensions entre les volontaires de l’Alliance et de la Horde sont fortes.", progress = "Vous avez déjà terminé votre mission, <nom> ? Vous pourrez trouver le capitaine Skullsplit devant la Ruche’Regal.", completion = "Je vois que Krug ne se soucie pas vraiment de la paperasse. Il a signé avec du sang de silithide !\n\nTrès bien, &lt;nom&gt;. J’ai préparé une série de tâches qui conviennent parfaitement à vos compétences de &lt;classe&gt;.\n\nAvec tous les efforts que vous et des personnes de votre trempe êtes en train de fournir, notre ennemi sera bientôt écrasé !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAffectation de combatAffectation logistiqueAffectation tactique"},
[8732] = {title = "La liste des affectations", objective = "Une liste d’affectations ? Qu’est-ce que c’est que cette bêtise, <nom> ?", description = nil, progress = "Une liste d’affectations ? Qu’est-ce que c’est que cette bêtise, <nom> ?", completion = "Dans l’ancien temps, je vous aurais marqué le front avec le sang de nos ennemis vaincus pour symboliser vos exploits. Thrall insiste pour que nous accédions aux demandes des druides.\n\nRetournez au Fort cénarien. Ils auront certainement une tâche à vous confier.", rewards = "Vous recevrez :\n\nOrdre de mission signé"},
[8733] = {title = "Eranikus, le tyran du Rêve", objective = "Rendez-vous sur Teldrassil et trouvez l’agent de Malfurion à l’extérieur des remparts de Darnassus.", description = "C’est un voyage de rédemption, <héros/héroïne>. Si seulement j’avais succombé aujourd’hui, j’aurais péri pour une cause juste et bonne. Vous devez retrouver le fragment de sceptre vert. Vous devez purifier Eranikus de la souillure que les Dieux très anciens ont placée sur lui.\n\nRendez-vous à Darnassus. Juste devant les remparts de la ville, vous rencontrerez l’un de mes agents. Cet agent lancera l’opération et informera Tyrande de nos plans sans alerter Staghelm.\n\n<Malfurion soupire.>\n\nUne déchéance qui a mis un millénaire à s’accomplir…", progress = nil, completion = "Le feu follet n’émet qu’un faible bourdonnement. Bizarrement, il semble capable de communiquer avec vous par la pensée.", rewards = "Vous recevrez :\n\n"},
[8734] = {title = "Tyrande et Remulos", objective = "Rendez-vous à Reflet-de-Lune et parlez au gardien Remulos.", description = "Tyrande sera avertie, <mortel/mortelle>. Shan'do Stormrage m’a préparé pour cette éventualité.\n\nVous devez maintenant vous aventurer à Reflet-de-Lune et parler à Remulos. Il vous donnera de nouvelles instructions pour l’invocation d’Eranikus.\n\nNous vous souhaitons tous bonne chance.", progress = nil, completion = "Il serait impossible d’attirer Eranikus hors du Rêve s’il refusait de le quitter. Ses desseins, cependant, l’obligent à entrer dans notre monde. Il cherche à détruire la manifestation vivante de Malfurion. S’il y parvenait, cela signifierait la fin de l’un des plus puissants alliés du Rêve. Le Cauchemar consumerait tout ce qui resterait si Malfurion tombait…", rewards = "Vous recevrez :\n\n"},
[8735] = {title = "La corruption du Cauchemar", objective = "Rendez-vous aux quatre portails qui ouvrent sur le Rêve d’Emeraude et récupérez un Fragment de la corruption du Cauchemar auprès de chacun d’eux. Lorsque vous aurez terminé, retournez voir le Gardien Remulos à Reflet-de-Lune.", description = "Vous devez vous rendre aux quatre portails du Rêve qui se trouvent sur Azeroth. Prélevez un morceau de la corruption du Cauchemar auprès de chacun d’eux. Les draconiens qui vivent aux alentours en détiendront. Revenez me voir lorsque vous aurez récupéré ces fragments.", progress = "<Remulos est perdu dans ses pensées.>", completion = "Êtes-vous prêt ? Ce monde est-il prêt pour ce que vous êtes sur le point d’invoquer. Je l’ignore… mais mon devoir me lie à Malfurion. Le devoir et l’honneur…", rewards = "Vous recevrez :\n\n"},
[8736] = {title = "Le Cauchemar se manifeste", objective = "Défendre Havrenuit d’Eranikus. Le Gardien Remulos ne doit pas mourir. Eranikus non plus. Défendez-vous. Attendez Tyrande.", description = "Il faudra faire preuve de maîtrise avec Eranikus. Nous sommes là pour veiller à sa rédemption, pas à sa destruction.\n\nTyrande est déjà en route pour nous aider dans cette tâche. Nous devons encaisser les coups du dragon et sauver Havrenuit d’une destruction certaine. Vous et vos alliés êtes notre seul espoir.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nCollier en dents de drakeBottes de manœuvre\n\nVous recevrez également :\n\n"},
[8737] = {title = "Le templier d'azur", objective = "Invoquez et tuez un Templier d'azur, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique I.", description = "Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.\n\nTrouvez un moyen d’invoquer et de détruire un Templier d’azur, puis allez faire votre rapport à Bor Wildmane.", progress = "Avez-vous rempli votre mission, <nom> ?", completion = "Excellent travail, &lt;nom&gt;.  Voici votre prochaine mission.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique complémentaire"},
[8738] = {title = "Rapport de reconnaissance de la Ruche'Regal", objective = "Trouver l’Eclaireur cénarien Landion dans la Ruche’Regal et ramener le Rapport de reconnaissance de la Ruche’Regal à l’Imploratrice céleste Proudhorn, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique VII.", description = "Nous avons déployé nos meilleurs éclaireurs dans les ruches silithides. L’éclaireur Landion épie les mouvements des silithides de la Ruche’Regal depuis plusieurs jours. Trouvez-le et demandez-lui un rapport écrit. Nous avons besoin de ces informations dès que possible, <nom>.", progress = "L’éclaireur Landion se trouve dans la Ruche’Regal. Hâtez-vous, <nom> ! Le temps presse.", completion = "Vos efforts sont dignes d’éloges, &lt;nom&gt;. Je vais lire ces rapports tout de suite. Pendant ce temps-là, vous avez certainement d’autres missions à remplir.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique complémentaire"},
[8739] = {title = "Rapport de reconnaissance de la Ruche'Ashi", objective = "Trouver l’Eclaireur cénarien Jalia dans la Ruche’Ashi et ramener le Rapport de reconnaissance de la Ruche’Ashi à l’Imploratrice céleste Proudhorn, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique VIII.", description = "Nous avons déployé nos meilleurs éclaireurs dans les ruches silithides. L’éclaireur Jalia épie les mouvements des silithides de la Ruche’Ashi depuis plusieurs jours. Trouvez-la et demandez-lui un rapport écrit. Nous avons besoin de ces informations dès que possible, <nom>.", progress = "L’éclaireur Jalia se trouve dans la Ruche’Ashi. Hâtez-vous, <nom> ! Le temps presse.", completion = "Vos efforts sont dignes d’éloges, &lt;nom&gt;. Je vais lire ces rapports tout de suite. Pendant ce temps-là, vous avez certainement d’autres missions à remplir.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique"},
[8740] = {title = "Les maraudeurs du crépuscule", objective = "Tuez la Maraudeuse du crépuscule Morna et 5 Maraudeurs du crépuscule. Lorsque ce sera fait, allez faire votre rapport à l’Imploratrice céleste Proudhorn. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique IX.", description = "Les sectateurs du Marteau du crépuscule disposent de troupes de cavalerie. Elles chevauchent hors de portée des forces basées au Fort cénarien, attaquent nos caravanes et s’en prennent aux plus faibles de nos patrouilles.\n\nTrouvez et tuez ces maraudeurs du crépuscule, en particulier leur chef, une redoutable guerrière du nom de Morna. Lorsque vous aurez terminé, allez faire votre rapport à l’Imploratrice céleste Proudhorn.", progress = "Avez-vous terminé votre tâche, <nom> ?", completion = "Très bien, &lt;nom&gt;. Les maraudeurs du crépuscule infligeaient des pertes inacceptables à nos patrouilles. Voici votre prochaine mission.", rewards = "Vous recevrez :\n\nBadge cénarien de tactiqueAffectation tactique complémentaire"},
[8741] = {title = "Le retour du champion", objective = "Apporter le Fragment de sceptre vert à Anachronos dans les Grottes du Temps de Tanaris.", description = "Le gardien attend votre retour, <nom>. Apportez le fragment de sceptre vert à Anarchronos, dans les Grottes du temps.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8742] = {title = "La puissance de Kalimdor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8743] = {title = "Faites résonner le gong !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCristal de résonance qiraji noir"},
[8744] = {title = "Un cadeau soigneusement emballé", objective = "Une petite carte sur ce cadeau dit :\n\nPour <nom>\n\nPuissiez-vous passer une joyeuse fête de Grand-Hiver !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau soigneusement emballé"},
[8745] = {title = "Le trésor de l'Intemporel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nCroc de KorialstraszDouleur de ShadowsongEpée runique du RougeHéritage de Ravencrest\n\nVous recevrez également :\n\n"},
[8746] = {title = "Metzen le renne", objective = "Trouvez Metzen le renne. Utilisez les notes qui vous ont été fournies comme indices pour découvrir son lieu de détention.\n\nQuand vous aurez trouvé Metzen, saupoudrez sur lui la Bourse de poudre de renne qui vous a été remise. Cela devrait mettre fin à sa captivité.\n\nRapportez la Bourse de poudre de renne à Kaymard Copperpinch à Orgrimmar quand Metzen aura été libéré.", description = "C’est un DÉSASTRE ! Metzen le renne a été kidnappé !\n\nMetzen est l’un des huit rennes du Grand-père Hiver  - et il appartient aux Gourmandises Fumebois.  Nous n’avons pas reçu une, mais DEUX demandes de rançon de groupes qui prétendent détenir Metzen.  Comme la saison des fêtes bat son plein, nous sommes enchaînés à la caisse enregistreuse ! Je vous en prie, trouvez Metzen et ramenez-le nous !\n\nLisez attentivement les lettres de rançon pour trouver des indices, et saupoudrez cette poudre de renne sur lui : elle le libéra de toutes ses entraves !\n\nJe vous en supplie, faites vite !", progress = "<nom> ! Vous l’avez trouvé ? Les notes contenues dans la sacoche que je vous ai donnée vous ont-elles permis de localiser Metzen ?  Quand je pense aux horreurs que ces cruels bandits pourraient lui faire subir… Hélas, nous n’avons pas les moyens de payer une rançon aussi exorbitante !", completion = "Vous avez réussi ! Hourra !\n\nMetzen s’est envolé et a rejoint les écuries du Grand-père Hiver. Oui, oui, Metzen sait voler… C’est ce qu’il vient de faire !  La poudre a fonctionné à merveille, j’en étais sûr. Vous avez sauvé la fête du Voile d’hiver  et le Gourmandises Fumebois du désastre.  Merci, &lt;nom&gt;.\n\nÉcoutez… Pour vous remercier pour ce que vous avez fait, je voudrais vous donner ceci. C’est quelque chose de TRÈS spécial. Si vous utilisez une monture, je pense que cela vous plaira beaucoup.  Joyeux Voile d’hiver !", rewards = "Vous recevrez :\n\nHoux préservé"},
[8747] = {title = "La voie du Protecteur", objective = "Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.\n\nLa chevalière du défenseur vous protègera des forces du mal.\n\nMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8748] = {title = "La voie du Protecteur", objective = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", description = nil, progress = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du protecteur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8749] = {title = "La voie du Protecteur", objective = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", description = nil, progress = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du protecteur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8750] = {title = "La voie du Protecteur", objective = "Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", description = nil, progress = "Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du protecteur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8751] = {title = "Le Protecteur de Kalimdor", objective = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", description = nil, progress = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", completion = "Levez-vous, Protecteur de Kalimdor ! Levez-vous et que tous reconnaissent votre valeur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8752] = {title = "La voie du Conquérant", objective = "Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.\n\nLa chevalière du conquérant rendra vos attaques physiques beaucoup plus meurtrières.\n\nMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8753] = {title = "La voie du Conquérant", objective = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", description = nil, progress = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du conquérant !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8754] = {title = "La voie du Conquérant", objective = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", description = nil, progress = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du conquérant !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8755] = {title = "La voie du Conquérant", objective = "Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", description = nil, progress = "Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie du conquérant !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8756] = {title = "Le conquérant qiraji", objective = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", description = nil, progress = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", completion = "Levez-vous, Conquérant des Qiraji ! Levez-vous et que tous reconnaissent votre valeur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8757] = {title = "La voie de l'Invocateur", objective = "Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.\n\nLa chevalière de l'invocateur améliorera considérablement vos capacités naturelles et magiques.\n\nMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8758] = {title = "La voie de l'Invocateur", objective = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", description = nil, progress = "Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie de l’invocateur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8759] = {title = "La voie de l'Invocateur", objective = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", description = nil, progress = "Vous nous faites honneur, <nom>. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !\n\nVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie de l’invocateur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8760] = {title = "La voie de l'Invocateur", objective = "Une telle dévotion à une cause est une rareté. Vous avez fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", description = nil, progress = "Une telle dévotion à une cause est une rareté. Vous avez fait preuve d’une volonté de fer, <nom>. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.\n\nDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.", completion = "Vos progrès au sein de la Progéniture sont très impressionnants, &lt;nom&gt;. Puissez-vous ne jamais quitter la voie de l’invocateur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8761] = {title = "Le Grand Invocateur", objective = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", description = nil, progress = "Je n’ai jamais vu une telle ténacité ! À la demande expresse de l’Intemporel, le Vol de bronze vous accorde un nouvel enchantement !\n\nDonnez-moi votre chevalière, que je procède aux ajustements nécessaires.", completion = "Levez-vous, Grand Invocateur ! Levez-vous et que tous reconnaissent votre valeur !", rewards = "Vous recevrez :\n\nChevalière du Vol de bronze"},
[8762] = {title = "Metzen le renne", objective = "Trouvez Metzen le renne. Utilisez les notes qui vous ont été fournies comme indices pour découvrir son lieu de détention.\n\nQuand vous aurez trouvé Metzen, saupoudrez sur lui la Bourse de poudre de renne qui vous a été remise. Cela devrait mettre fin à sa captivité.\n\nRapportez la Bourse de poudre de renne à Wulmort Jinglepocket à Ironforge quand Metzen aura été libéré.", description = "C’est un DÉSASTRE ! Metzen le renne a été kidnappé !\n\nMetzen est l’un des huit rennes du Grandpère Hiver  - et il appartient aux Gourmandises Fumebois. Nous n’avons pas reçu une, mais DEUX demandes de rançon de groupes qui prétendent détenir Metzen. Comme la saison des fêtes bat son plein, nous sommes enchaînés à la caisse enregistreuse ! Je vous en prie, trouvez Metzen et ramenez-le nous !\n\nLisez attentivement les lettres de rançon pour trouver des indices, et saupoudrez cette poudre de renne sur lui : elle le libéra de toutes ses entraves !\n\nJe vous en supplie, faites vite !", progress = "<nom> ! Vous l’avez trouvé ? Les notes contenues dans la sacoche que je vous ai donnée vous ont-elles permis de localiser Metzen ?  Quand je pense aux horreurs que ces cruels bandits pourraient lui faire subir… Hélas, nous n’avons pas les moyens de payer une rançon aussi exorbitante !", completion = "Vous avez réussi ! Hourra !\n\nMetzen s’est envolé et a rejoint les écuries du Grandpère Hiver. Oui, oui, Metzen sait voler… C’est ce qu’il vient de faire ! La poudre a fonctionné à merveille, j’en étais sûr. Vous avez sauvé la fête du Voile d’hiver  et le Gourmandises Fumebois du désastre.  Merci, &lt;nom&gt;.\n\nÉcoutez… Pour vous remercier pour ce que vous avez fait, je voudrais vous donner ceci. C’est quelque chose de TRÈS spécial. Si vous utilisez une monture, je pense que cela vous plaira beaucoup. Joyeux Voile d’hiver !", rewards = "Vous recevrez :\n\nHoux préservé"},
[8763] = {title = "Le héros du jour", objective = "Placer 1 Sel de Fonderoc et 5 pièces d’or dans un Préservateur de houx, et vous recevrez 5 Houx préservés.", description = "Écoutez… Je ne suis pas vraiment censé vous dire cela, mais comme vous êtes le héros du jour et tout ça…\n\nIl y a du houx frais partout à cette époque de l’année, mais il ne dure jamais bien longtemps.  Nous avons une machine qui préserve le houx - il ne se fane jamais ! Nous l’utilisons pour pimenter les fêtes… et faire de bons profits durant l’été !\n\nJe vous laisserai utiliser le préservateur, mais seulement si vous êtes un maître cuisinier. Vous aurez besoin d’un peu de sel de Fonderoc et de deux, trois, allez, disons cinq pièces d’or. Il vous fabriquera une belle fournée que vous pourrez garder pour vous.", progress = "Le “Préservateur de houx” ressemble au premier abord à une sorte d’alambic, mais en l’observant plus attentivement, vous remarquez quelques modifications gobelinoïdes. Heureusement, votre compétence en cuisine vous permet tout de même de comprendre son fonctionnement.\n\nIl y a déjà du houx frais dans la machine. Il vous suffit d’ajouter du sel de Fonderoc et cinq pièces d’or pour la faire fonctionner.", completion = "La machine bourdonne pendant un certain temps, et lâche quelques filets de vapeur lorsqu’elle démarre soudainement.  Elle s’arrête peu de temps après, signalant la fin de son travail par un nouveau jet de vapeur.  Une trappe s’ouvre sur le côté, révélant une fournée de houx préservé.", rewards = "Vous recevrez :\n\nHoux préservé"},
[8764] = {title = "Changer de voie - adieu au Protecteur", objective = "Si vous décidez de suivre une autre voie, champion, vous devrez me remettre votre chevalière et une montagne de scarabées morts, que vous aurez tués à Ahn’Qiraj.", description = nil, progress = "Si vous décidez de suivre une autre voie, champion, vous devrez me remettre votre chevalière et une montagne de scarabées morts, que vous aurez tués à Ahn’Qiraj.", completion = "Portez-vous bien, &lt;nom&gt;. Si vous changez d’avis, je serai là pour vous aider.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nChevalière du Vol de bronzeChevalière du Vol de bronze"},
[8765] = {title = "Changer de voie - adieu à l'Invocateur", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nChevalière du Vol de bronzeChevalière du Vol de bronze"},
[8766] = {title = "Changer de voie - adieu au Conquérant", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nChevalière du Vol de bronzeChevalière du Vol de bronze"},
[8767] = {title = "Un cadeau secoué doucement", objective = "Ce cadeau donne l'impression d'avoir été secoué plusieurs fois. Il porte une petite carte qui dit\n\nA un <classe> <race> hors du commun.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau secoué doucement"},
[8768] = {title = "Un cadeau à l'emballage multicolore", objective = "Ce cadeau à l'emballage multicolore porte votre nom !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau à l'emballage multicolore"},
[8769] = {title = "Un cadeau tic-taquant", objective = "Encore un pour vous !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau tic-taquant"},
[8770] = {title = "Objectif : les défenseurs de la Ruche'Ashi", objective = "Tuez 30 Défenseurs de la Ruche’Ashi, et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat I pour terminer cette quête.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Ashi. Vos cibles prioritaires seront les défenseurs de la Ruche’Ashi.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Excellent travail, &lt;nom&gt;. Comme toujours, nous avons apprécié votre promptitude.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8771] = {title = "Objectif : les traqueuses des sables de la Ruche'Ashi", objective = "Tuez 30 Traqueuses des sables de la Ruche’Ashi, et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat II pour terminer cette quête.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Ashi. Vos cibles prioritaires seront les traqueuses des sables de la Ruche’Ashi.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Ashi a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8772] = {title = "Objectif : les patrouilleuses de la Ruche'Zora", objective = "Tuez 30 Patrouilleuses de la Ruche’Zora , puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat VI.", description = "Nous avons demandé à ce que des renforts rejoignent l’assaut sur la Ruche’Zora. Vous avez été <choisi/choisie> pour affronter les patrouilleuses de la Ruche'Zora. À la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Zora a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8773] = {title = "Objectif : les ravageuses de la Ruche'Zora", objective = "Tuez 30 Ravageuses de la Ruche’Zora, et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat IV pour terminer cette quête.", description = "Nous avons demandé à ce que des renforts rejoignent l’assaut sur la Ruche’Zora. Vous avez été <choisi/choisie> pour affronter les ravageuses de la Ruche'Zora. À la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous avez quelque chose à me dire, <classe> ?", completion = "A ce que j’ai entendu dire, vous vous êtes bien tiré de l’attaque de la Ruche’Zora. Continuez comme ça et la victoire nous reviendra bientôt.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8774] = {title = "Objectif : les embusquées de la Ruche'Regal", objective = "Tuez 30 Embusquées de la Ruche’Regal, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat VIII.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Regal. Vos cibles prioritaires seront les embusquées de la Ruche’Regal.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous voulez me dire quelque chose, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Regal a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8775] = {title = "Objectif : les crache-feu de la Ruche'Regal", objective = "Tuez 30 Crache-feu de la Ruche’Regal, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat IX.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Regal. Vos cibles prioritaires seront aériennes : les crache-feu de la Ruche’Ashi.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous voulez me dire quelque chose, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Regal a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8776] = {title = "Objectif : les esclavagistes de la Ruche'Regal", objective = "Tuez 30 Esclavagistes de la Ruche’Regal, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat X.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Regal. Vos cibles prioritaires seront les esclavagistes silithides.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous voulez me dire quelque chose, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Regal a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8777] = {title = "Objectif : les fouisseuses de la Ruche'Regal", objective = "Tuez 30 Fouisseuses de la Ruche’Regal, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat XI.", description = "L’effort de guerre progresse, mais la présence des silithides dans la région représente une menace de plus en plus importante pour nos opérations. Vous avez été <choisi/choisie> pour participer à l’assaut sur la Ruche’Regal. Vos cibles prioritaires seront les les fouisseuses de la Ruche’Regal.\n\nÀ la fin de la mission, présentez-vous au rapport devant le commandant Mar’alith.", progress = "Vous voulez me dire quelque chose, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Votre rôle dans l’attaque de la Ruche’Regal a été noté.", rewards = "Vous recevrez :\n\nBadge cénarien de combat"},
[8778] = {title = "La brigade d'Ironforge a besoin d'explosifs !", objective = "Apporter 6 Huildes d’immolation, 5 doses de Carburant de fusée des gobelins et 10 doses de Poudre d’explosion dense à l’arcaniste Nozzlespring, près de la Ruche’Zora en Silithus. Vous devez aussi apporter le Briefing logistique IV pour terminer cette quête.", description = "La brigade d’Ironforge a déposé une requête inhabituelle pour des composants extrêmement… volatils. Rassemblez-les et remettez-les à M. Nozzlespring, de la brigade d’Ironforge.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Ah oui, cela nous rendra bien service ! Mille mercis, &lt;nom&gt; !", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8779] = {title = "Le matériel de divination", objective = "Apporter un 1 Grand éclat brillant, 1 Gros éclat irradiant et 1 Enorme émeraude à la géologue Larksbane, au Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique V pour terminer cette quête.", description = "Les études de la géologue Larksbane ont rendu d’immenses services à nos opérations en Silithus. Elle a récemment demandé du matériel de divination pour ses recherches. Procurez-vous le nécessaire, et allez le lui livrer personnellement.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Ma foi, oui… tout cela me sera d’une grande aide ! Ces objets sont très difficiles à se procurer dans le désert, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8780] = {title = "Des renforts d'armure pour le champ de bataille", objective = "Apportez 8 Renforts d’armure robustes et 8 Renforts d’armure louds à Janela Stouthammer, à l’avant-poste de la brigade d’Ironforge, près de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VII pour terminer cette quête.", description = "Les réserves de renforts d’armures de la brigade d’Ironforge sont dangereusement basses. Procurez-vous-en, et livrez-les à Janela Stouthammer, à l’avant-poste de la brigade d’Ironfoge, près de la Ruche’Zora.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Merci. Je vais donner tout ça aux gars.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8781] = {title = "Des armes pour le champ de bataille", objective = "Apportez 2 Epées d’acier lunaire à Janela Stouthammer, à l’avant-poste de la brigade d’Ironforge, près de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VI pour terminer cette quête.", description = "La brigade d’Ironforge a joué un grand rôle dans nos combats en Silithus. Malheureusement, une bonne partie de son matériel s’est égarée au cours du transport. Procurez-vous des armes et livrez-les à Janela Stouthammer, à l’avant-poste de la brigade d’Ironfoge, près de la Ruche’Zora.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Oh, excellent ! Ils vont arrêter de venir me voir pour se plaindre que leurs lames sont émoussées. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8782] = {title = "La question des uniformes", objective = "Remettre 1 Etoffe lunaire, 2 Rouleaux d’étoffe runique et 1 Soie d’araignée toilacier à l’Imploratrice céleste Proudhorn au Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique VIII pour terminer cette quête.", description = "Le dernier afflux de volontaires nous laisse à court d’uniformes. Procurez-vous de quoi en fabriquer une série et présentez-vous à l’Imploratrice céleste Proudhorn.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Ah. En effet, nous en avions besoin. Nous apprécions votre travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8783] = {title = "Des matériaux extraordinaires", objective = "Remettre 2 Barres de thorium enchanté et 2 Cuirs enchantés à Vargus au Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique IX pour terminer cette quête.", description = "Vargus, le forgeron du Fort cénarien, a demandé des matériaux enchantés. Il compte s’en servir pour forger des armes redoutables à nos troupes. Procurez-vous ces matériaux et remettez-les directement à Vargus, afin que l’équipement des forces du Fort cénarien reste performant.", progress = "Avez-vous quelque chose pour moi, <nom> ?", completion = "Ah, oui. Ces matériaux sont de toute première qualité. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8784] = {title = "Les secrets des Qiraji", objective = "Remettre l’Ancien artefact qiraji aux dragons qui se cachent près de l’entrée du temple.", description = "Vous avez découvert un antique artefact qiraji ! L’un des dragons qui se trouve près de l’entrée du temple saura peut-être quoi en faire.", progress = "Vous brillez ! Je sais ce que cela signifie…", completion = "Une trouvaille exceptionnelle, &lt;nom&gt;. Tout simplement merveilleuse. Cela va nous donner une idée de la manière dont fonctionne l’esprit malade de notre ennemi.", rewards = "Vous allez être la cible du sort suivant :\n\nFaction Progéniture de Nozdormu +1000"},
[8785] = {title = "La légion d'Orgrimmar a besoin de mojo !", objective = "Apporter 6 Mojos puissants, 6 Flacons de grand mojo et 8 Huiles d’immolation à la Prêtresse des ombres Shai, près de la Ruche’Regal en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique IV.", description = "La légion d’Orgrimmar demande plusieurs ingrédients inhabituels. Vu la manière dont ils se comportent en Silithus, nous aimerions leur donner satisfaction aussi rapidement que possible. Récupérez ces objets et remettez-les à la trollesse, Shai.", progress = "Avez les objets dont j'ai besoin, <nom> ?", completion = "Ah, très bien. Juste ce qu’il me fallait. Je m'en servirai pour préparer une décoction très spéciale. Les silithides ne vont pas l'aimer. Pas du tout.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8786] = {title = "Des armes pour le champ de bataille", objective = "Remettre 3 Gigantesques haches en fer à Merok Longstride, au camp de la légion d’Orgrimmar, à l’extérieur de la Ruche’Regal. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique VI.", description = "La légion d’Orgrimmar a présenté une requête pour des armes supplémentaires, que nous sommes incapables d’honorer pour l’instant. Obtenez les armes demandées et apportez-les à Merok Longstride, à l’extérieur de la Ruche’Regal.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Excellent travail, &lt;nom&gt;. Nous allions en manquer.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8787] = {title = "Des renforts d'armure pour le champ de bataille", objective = "Apportez 8 Renforts d’armure robustes et 8 Renforts d’armure lourds à Merok Longstride près de la Ruche'Regal. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique VII.", description = "Les vaillants volontaires de la légion d’Orgrimmar sont venus en Silithus pour nous aider. Malheureusement, leur réserve de renforts d’armure s’est perdue au cours du voyage. Procurez-vous-en, et remettez-les à Merok Longstride, au camp de la légion d’Orgrimmar.", progress = "Avez-vous quelque chose pour moi, <nom> ?", completion = "Ah oui… Je vais les distribuer aux soldats, &lt;nom&gt;. La légion d'Orgrimmar vous remercie !", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8788] = {title = "Un cadeau secoué doucement", objective = "Ce cadeau donne l'impression d'avoir été secoué plusieurs fois. Il porte une petite carte qui dit\n\nA un <classe> <race> hors du commun.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau secoué doucement"},
[8789] = {title = "Les armes impériales qiraji", objective = "Arygos, dans le temple d’Ahn’Qiraj, vous fabriquera des armes imprégnées d’élémentium si vous lui procurez des Armes impériales qiraji et 3 Minerais d’élémentium.", description = "Nous ne sommes pas restés inactifs pendant un millénaire, <nom>.\n\nNous avons vu ces bêtes dévorer ceux des leurs qui ne leur semblaient plus utiles. Nous les avons écoutées alors qu’elles préparaient la destruction de notre monde. Et nous avons appris qu’elles connaissaient la trahison.\n\nDes faiblesses existent dans leurs rangs. Nous saurons comment les utiliser à notre avantage.\n\nAllez et trouvez-moi leurs armes de cérémonie. Combinées avec des éléments créés grâce à leur dieu volatil, elles deviendront une force de justice.", progress = "Allez chercher ce que je vous ai demandé. Vous deviendrez quelque chose de plus que la simple somme de vos éléments, champion.", completion = "Une fois imprégnées d’élementium, ces armes n’auront aucun mal à frapper les Qiraji et leur dieu.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHache de guerre qiraji bénieMousquet qiraji béniPugio qiraji béniPavois qiraji béni"},
[8790] = {title = "L'équipement impérial qiraji", objective = "Merithra du Rêve, au temple d’Ahn’Qiraj, vous fabriquera des armes imprégnées d’élémentium si vous lui ramenez un Equipement impérial qiraji et 3 Minerais d’élémentium.", description = "À en croire les théories d’Arygos, l’élément qui naît des conflits entre les Dieux très anciens et leurs séides peut devenir redoutable pour eux lorsque toutes les conditions sont réunies. Je parle de l’élémentium, <mortel/mortelle>.\n\nTrouvez-moi un Equipement impérial qiraji et cet élément toxique. Je vous fabriquerai des armes d’un grand pouvoir.", progress = "Vous les abattrez et vous nous libérerez de ces liens.", completion = "N’utilisez cet objet qu’à bon escient, &lt;nom&gt;. Qu’ils ressentent la douleur qu’ils infligent si volontiers.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBâton d'acolyte qiraji béniBâton d'augure qiraji béniMarteau de guerre qiraji béni"},
[8791] = {title = "La chute d'Ossirian", objective = "Remettez la Tête d’Ossirian l’Intouché au commandant Mar’alith, au Fort cénarien en Silithus.", description = "Une terrible menace est enfin neutralisée. Ossirian le cruel a été vaincu.\n\nLes habitants de Kalimdor seront soulagés lorsqu’ils auront connaissance de cette victoire. Prenez la tête d’Ossirian et présentez-la au commandant Mar’alith du Fort cénarien.", progress = "Ah, <nom>, vous voici de retour ! Et en un seul morceau, qui est plus est. Quelles nouvelles d’Ahn’Qiraj ?", completion = "Cet exploit mérite les plus grands éloges. Je vous offre un objet magique de votre choix, &lt;nom&gt;. Vous avez rendu un grand service aux peuples de Kalimdor.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCharme des Sables changeantsAmulette des Sables changeantsFoulard des Sables changeantsPendentif des Sables changeants\n\nVous recevrez également :\n\n"},
[8792] = {title = "La Horde a besoin de votre aide !", objective = "Parler au seigneur de guerre Gorchuk, dans la vallée des Esprits d’Orgrimmar.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. La Horde a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le seigneur de guerre Gorchuk. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?", progress = nil, completion = "Throm'ka, &lt;classe&gt; ! Il est bon de voir une foule de membres de la Horde, tels que vous, &lt;nom&gt;, s’empresser de jeter les bases de notre future guerre à Ahn’Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn’Qiraj.\n\nMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.", rewards = "Vous recevrez :\n\n"},
[8793] = {title = "La Horde a besoin de votre aide !", objective = "Parler au seigneur de guerre Gorchuk, dans la vallée des Esprits d’Orgrimmar.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. La Horde a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le seigneur de guerre Gorchuk. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[8794] = {title = "La Horde a besoin de votre aide !", objective = "Parler au seigneur de guerre Gorchuk, dans la vallée des Esprits d’Orgrimmar.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. La Horde a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le seigneur de guerre Gorchuk. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?", progress = nil, completion = "Throm'ka, &lt;classe&gt; ! Il est bon de voir une foule de membres de la Horde, tels que vous, &lt;nom&gt;, s’empresser de jeter les bases de notre future guerre à Ahn’Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn’Qiraj.\n\nMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.", rewards = "Vous recevrez :\n\n"},
[8795] = {title = "L'Alliance a besoin de votre aide !", objective = "Parler au grand maréchal Snowfall dans la Garde militaire d’Ironforge.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. L’Alliance a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le grand maréchal Snowfall. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?", progress = nil, completion = "Voilà une heureuse rencontre, mon gars ! Il est bon de voir une foule de membres d’Alliance, tels que vous, &lt;nom&gt;, s’empresser de jeter les bases de notre future guerre à Ahn’Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn’Qiraj.\n\nMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.", rewards = "Vous recevrez :\n\n"},
[8796] = {title = "L'Alliance a besoin de votre aide !", objective = "Parler au grand maréchal Snowfall dans la Garde militaire d’Ironforge.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. L’Alliance a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le grand maréchal Snowfall. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?", progress = nil, completion = "Voilà une heureuse rencontre, mon gars ! Il est bon de voir une foule de membres d’Alliance, tels que vous, &lt;nom&gt;, s’empresser de jeter les bases de notre future guerre à Ahn’Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn’Qiraj.\n\nMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.", rewards = "Vous recevrez :\n\n"},
[8797] = {title = "L'Alliance a besoin de votre aide !", objective = "Parler au grand maréchal Snowfall dans la Garde militaire d’Ironforge.", description = "Bonjour. Que vous ayez accepté de m’écouter est déjà une bonne chose. L’Alliance a besoin de toute l’aide possible pour se préparer à la guerre d’Ahn’Qiraj. Cela veut aussi dire votre aide ! Au moment où je vous parle, des collecteurs officiels récoltent tout ce qui sera nécessaire pendant la bataille, mais sans votre aide, <nom>, nous n’atteindrons pas nos objectifs ! Vous devriez aller parler au responsable, le grand maréchal Snowfall. Qu’en pensez-vous, <classe> ? Nous aiderez-vous dans ces préparatifs capitaux ?", progress = nil, completion = "Voilà une heureuse rencontre, mon gars ! Il est bon de voir une foule de membres d’Alliance, tels que vous, &lt;nom&gt;, s’empresser de jeter les bases de notre future guerre à Ahn’Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn’Qiraj.\n\nMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.", rewards = "Vous recevrez :\n\n"},
[8798] = {title = "Un yéti rien que pour vous", objective = "Je sais ! Vous êtes ingénieur, vous aussi ! Comme vous m’avez aidée à donner une leçon à mes amis, je vais vous apprendre à construire votre propre yéti mécanique ! Comme ça, vous n’aurez jamais fini de vous amuser, et vous pourrez faire peur à qui vous voulez ! Enfin, si vous arrivez à récupérer les éléments pour le fabriquer, bien sûr.\n\nQu’en dites-vous, <nom> ? Voulez-vous apprendre le secret de la fabrication des yétis mécaniques ?", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nYéti mécanique paisible"},
[8799] = {title = "Le héros du jour", objective = "Placer 1 Sel de Fonderoc et 5 pièces d’or dans un Préservateur de houx, et vous recevrez 5 Houx préservés.", description = "Écoutez… Je ne suis pas vraiment censé vous dire cela, mais comme vous êtes le héros du jour et tout ça…\n\nIl y a du houx frais partout à cette époque de l’année, mais il ne dure jamais bien longtemps.  Nous avons une machine qui préserve le houx - il ne se fane jamais ! Nous l’utilisons pour pimenter les fêtes… et faire de bons profits durant l’été !\n\nJe vous laisserai utiliser le préservateur, mais seulement si vous êtes un maître cuisinier. Vous aurez besoin d’un peu de sel de Fonderoc et de deux, trois, allez, disons cinq pièces d’or. Il vous fabriquera une belle fournée que vous pourrez garder pour vous.", progress = "Le “Préservateur de houx” ressemble au premier abord à une sorte d’alambic, mais en l’observant plus attentivement, vous remarquez quelques modifications gobelinoïdes. Heureusement, votre compétence en cuisine vous permet tout de même de comprendre son fonctionnement.\n\nIl y a déjà du houx frais dans la machine. Il vous suffit d’ajouter du sel de Fonderoc et cinq pièces d’or pour la faire fonctionner.", completion = "La machine bourdonne pendant un certain temps, et lâche quelques filets de vapeur lorsqu’elle démarre soudainement.  Elle s’arrête peu de temps après, signalant la fin de son travail par un nouveau jet de vapeur.  Une trappe s’ouvre sur le côté, révélant une fournée de houx préservé.", rewards = "Vous recevrez :\n\nHoux préservé"},
[8800] = {title = "La tenue de combat cénarienne", objective = "Parlez à Vargus, au Fort cénarien en Silithus.", description = "Lorsque vous aurez terminé les tâches qui vous sont assignées, allez voir Vargus, le forgeron. Montrez-lui les insignes que vous aurez reçus. Il vous fournira du matériel à la hauteur de votre dévotion à notre cause.", progress = nil, completion = "C’est Kaldon qui vous envoie ? Très bien, voyons ce que je peux faire pour vous.", rewards = nil},
[8801] = {title = "L'héritage de C'Thun", objective = "Remettre l’œil de C’Thun à Caelastrasz, dans le temple d’Ahn’Qiraj.", description = "Les murs d’Ahn’Qiraj tremblent. Une force maléfique plus vieille que ce monde a été détruite.\n\nAlors que vous contemplez les restes de cette abomination colossale, votre sang se glace. Même après sa mort, l’héritage de C’Thun reste perceptible dans le mal qui vous entoure.\n\nVous avez accompli l’impossible.\n\nVous vous emparez d’un œil pédonculé et le glissez dans votre sac à dos.\n\nApportez-le aux dragons qui se trouvent dans la pièce voisine.", progress = "<Caelastrasz s’agenouille devant vous.>\n\nMonseigneur <nom>, vous nous avez libérés de ses griffes.", completion = "Nous quitterons cet endroit par nos propres moyens, monseigneur &lt;nom&gt;, dès que nous serons certains que le mal qu’il renferme a été entièrement détruit. Votre voyage de légende touche à son terme.", rewards = "Vous recevrez :\n\n"},
[8802] = {title = "Le sauveur de Kalimdor", objective = "Apporter l’Oeil de C’Thun à Anachronos dans les grottes du Temps.", description = "Rendez-vous dans les grottes du Temps, <monseigneur/dame> <nom>. Anachronos attend votre retour. Donnez-lui l’œil de C’Thun. Il lui donnera certainement une place d’honneur dans la collection de son maître.", progress = "Seigneur <nom> ! C’est fini…", completion = "Le Maître a laissé ceci pour vous, champion. De sa cache intemporelle, une collection d’artefacts couvrant des milliers d’années – le choix vous appartient.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmulette du dieu déchuCape du dieu déchuAnneau du dieu déchu\n\nVous allez être la cible du sort suivant :\n\nFaction Progéniture de Nozdormu +1000\n\nVous recevrez également :\n\n"},
[8803] = {title = "Un cadeau de fête", objective = "La petite note placée sur le cadeau dit :\n\nPour <nom>,\n\nEn espérant que cela vous aidera à propager l’ambiance de fête et de bonnes nouvelles sur tout Azeroth.\n\nDe la part de Grandpère Hiver.", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCadeau de fête"},
[8804] = {title = "Survivre dans le désert", objective = "Ramener 4 Globes d’eau, 4 Anti-venins puissants et 4 Boulettes du désert fumées à Calandrath, à l’auberge du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique I.", description = "L’afflux de nouvelles recrues au Fort cénarien nous pose un problème. Comment les garder en vie dans le désert ? Les volontaires inexpérimentés risquent la déshydratation et l’empoisonnement – le sable grouille de créatures venimeuses. Rassemblez les matériaux nécessaires à la constitution de paquetages de survie dans le désert, et remettez-les à Calandrath au Fort cénarien.", progress = "Avez-vous quelque chose pour moi ?", completion = "Excellent ! Nous en avions besoin, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8805] = {title = "Des bottes pour la garde", objective = "Remettre 3 Bottes ornées en mithril à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique II.", description = "La division de cavalerie de la garde du Fort cénarien manque de bottes ornées en mithril. Procurez-vous en un stock et livrez-le immédiatement au capitaine Vish Kozus au Fort cénarien.", progress = "Vous avez quelque chose pour moi ?", completion = "Excellent. Nous en avions besoin. Bon boulot, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8806] = {title = "Des silex à aiguiser pour la Garde", objective = "Apporter 10 Silex à aiguiser denses, 10 Silex à aiguiser solides et 10 Silex à aiguiser lourds à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique III.", description = "La garde du Fort cénarien est presque à court de silex à aiguiser. Apportez-en un assortiment au capitaine Vish Kozus, du Fort cénarien.", progress = "Vous avez quelque chose pour moi ?", completion = "Excellent, nous avions bien besoin, &lt;nom&gt;. Bon travail.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8807] = {title = "Le matériel de divination", objective = "Apporter un 1 Grand éclat brillant, 1 Gros éclat irradiant et 1 Enorme émeraude à la géologue Larksbane, au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique V.", description = "Les études de la géologue Larksbane ont rendu d’immenses services à nos opérations en Silithus. Elle a récemment demandé du matériel de divination pour ses recherches. Procurez-vous le nécessaire, et allez le lui livrer personnellement.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Ma foi, oui… tout cela me sera d’une grande aide ! Ces objets sont très difficiles à se procurer dans le désert, &lt;nom&gt;. Merci.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8808] = {title = "La question des uniformes", objective = "Remettre 1 Etoffe lunaire, 2 Rouleaux d’étoffe runique et 1 Soie d’araignée toilacier à l’Imploratrice céleste Proudhorn au Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique VIII pour terminer cette quête.", description = "Le dernier afflux de volontaires nous laisse à court d’uniformes. Procurez-vous de quoi en fabriquer une série et présentez-vous à l’Imploratrice céleste Proudhorn.", progress = "Avez-vous quelque chose pour moi, <nom> ?", completion = "Ah. En effet, nous en avions besoin. Nous apprécions votre travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8809] = {title = "Des matériaux extraordinaires", objective = "Remettre 2 Barres de thorium enchanté et 2 Cuirs enchantés à Vargus au Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique IX pour terminer cette quête.", description = "Vargus, le forgeron du Fort cénarien, a demandé des matériaux enchantés. Il compte s’en servir pour forger des armes redoutables à nos troupes. Procurez-vous ces matériaux et remettez-les directement à Vargus, afin que l’équipement des forces du Fort cénarien reste performant.", progress = "Avez-vous quelque chose pour moi, <nom> ?", completion = "Ah, oui. Ces matériaux sont de toute première qualité. Merci, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique"},
[8810] = {title = "Des bandages pour la campagne", objective = "Apportez 30 Bandages épais en étoffe runique, 30 Bandages épais en soie et 30 Bandages épais en tisse-mage à l’imploratrice céleste Proudhorn. Vous devez aussi apporter le Briefing logistique X pour terminer cette quête.", description = "Après les dernières escarmouches, notre réserve de bandages est dangereusement basse. Procurez-vous le nécessaire et livrez-le à l’imploratrice céleste Proudhorn au Fort cénarien.", progress = "Vous avez quelque chose pour moi, <nom> ?", completion = "Juste à temps. Ces bandages sauveront des vies, &lt;nom&gt;. J’apprécie votre travail. Voici votre prochaine mission…", rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8811] = {title = "Une chevalière de mérite", objective = "Les aventuriers qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part de Darnassus.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons cet échange comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", description = nil, progress = "Les aventuriers qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part de Darnassus.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons cet échange comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", completion = "Très bien, vos actes ont été entrés dans nos archives, et vos efforts seront dûment reconnus. Continuez ainsi, &lt;classe&gt;.\n\nSi vous avez d’autres chevalières à remettre, je pourrai vous aider. Vous savez où me trouver.", rewards = nil},
[8812] = {title = "Une chevalière de mérite", objective = "Les aventuriers qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part des exilés de Gnomeregan.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons cet échange comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", description = nil, progress = "Les aventuriers qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part des exilés de Gnomeregan.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons cet échange comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", completion = "Très bien, vos actes ont été entrés dans nos archives, et vos efforts seront dûment reconnus. Continuez ainsi, &lt;classe&gt;.\n\nSi vous avez d’autres chevalières à remettre, je pourrai vous aider. Vous savez où me trouver.", rewards = nil},
