[8846] = {title = "Cinq chevalières pour des fournitures militaires", objective = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas la seule.\n\nJe peux vous en donner, mais uniquement en échange d’un certain nombre de chevalières de mérite. Bien sûr, dans ce cas, vous ne deviendrez pas plus célèbre, mais vous recevrez peut-être quelque chose qui vous gardera en vie lorsque la bataille commencera.", description = nil, progress = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas la seule.\n\n", completion = "Bien, voilà qui est réglé, &lt;classe&gt;, voilà vos fournitures. Si vous voulez procéder à un autre échange, je suis en mesure de l’autoriser. Vous n’aurez qu’à venir me le dire et je veillerai à ce que tout se passe rapidement.\n\nVous faites du bon travail, &lt;nom&gt;. Continuez. Si nous voulons gagner, nous aurons besoin de tout le matériel que nous pourrons ramasser. Si chacun fait son devoir, nous vaincrons !", rewards = "Vous recevrez :\n\nFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8847] = {title = "Dix chevalières pour des fournitures militaires", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8848] = {title = "Quinze chevalières pour des fournitures militaires", objective = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas la seule.\n\nJe peux vous en donner, mais uniquement en échange d’un certain nombre de chevalières de mérite. Bien sûr, dans ce cas, vous ne deviendrez pas plus célèbre, mais vous recevrez peut-être quelque chose qui vous gardera en vie lorsque la bataille commencera.", description = nil, progress = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas la seule.\n\n", completion = "Bien, voilà qui est réglé, &lt;classe&gt;, voici vos fournitures. Si vous voulez procéder à un autre échange, je suis en mesure de l’autoriser. Vous n’aurez qu’à venir me le dire et je veillerai à ce que tout se passe rapidement.\n\nVous faites du bon travail, &lt;nom&gt;. Continuez. Si nous voulons gagner, nous aurons besoin de tout le matériel que nous pourrons ramasser. Si chacun fait son devoir, nous vaincrons !", rewards = "Vous recevrez :\n\nFournitures de l'effort de guerre d'Ahn'Qiraj"},
