[8855] = {title = "Trente chevalières pour des fournitures militaires", objective = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas le seul.\n\nJe peux vous en donner, mais uniquement en échange d’un certain nombre de chevalières de mérite. Bien sûr, dans ce cas, vous ne deviendrez pas plus célèbre, mais vous recevrez peut-être quelque chose qui vous gardera en vie lorsque la bataille commencera.", description = nil, progress = "Ah ah, vous venez vous chercher quelques fournitures militaires, pas vrai ? Ma foi, je peux comprendre que vous ayez besoin de matériel… Après tout, vous n’avez qu’à regarder autour de vous pour vous rendre compte que vous n’êtes pas le seul.\n\n", completion = "Bien, voilà qui est réglé, &lt;classe&gt;, voici vos fournitures. Si vous voulez procéder à un autre échange, je suis en mesure de l’autoriser. Vous n’aurez qu’à venir me le dire et je veillerai à ce que tout se passe rapidement.\n\nVous faites du bon travail, &lt;nom&gt;. Continuez. Si nous voulons gagner, nous aurons besoin de tout le matériel que nous pourrons ramasser. Si chacun fait son devoir, nous vaincrons !", rewards = "Vous recevrez :\n\nFournitures de l'effort de guerre d'Ahn'Qiraj"},
[8856] = {title = "Survivre dans le désert", objective = "Ramener 4 Globes d’eau, 4 Anti-venins puissants et 4 Pains de saumon à Calandrath, à l’auberge du Fort cénarien en Silithus.", description = "L’afflux de nouvelles recrues au Fort cénarien nous pose un problème. Comment les garder en vie dans le désert ? Les volontaires inexpérimentés risquent la déshydratation et l’empoisonnement – le sable grouille de créatures venimeuses. Rassemblez les matériaux nécessaires à la constitution de paquetages de survie dans le désert, et remettez-les à Calandrath au Fort cénarien.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[8857] = {title = "Les secrets du Colosse - Ashi", objective = "Remettre la Carcasse du colosse d'Ashi à Oglethorpe Obnoticus, à Baie-du-Butin.", description = "Je suis à la recherche d’aventuriers endurcis, désireux de remettre un échantillon prélevé sur le Colosse d’Ahsi à Oglethorpe, qui vit à Baie-du-Butin. Non non, pas question de vous approcher du cadavre de cette chose. Prenez l’un de mes échantillons et surtout, faites vite. Une fois pourri, ce truc ne lui servira plus à rien.", progress = "Oui ? Qu’avez-vous là ?", completion = "Oh, quelle merveilleuse carcasse ! J’en ferai des poulets extraordinaires ! Bien joué, mon garçon !", rewards = "Vous recevrez :\n\nSac de butin colossal"},
[8858] = {title = "Les secrets du Colosse - Regal", objective = "Apporter la Carcasse du colosse de Regal au surveillant Oilfist, dans la gorge des Vents brûlants.", description = "Franchement, j’aimerais mieux balancer cette carcasse de cafard dans la sale gueule d’Oilfist… Sauf que j’suis coincé là à ramasser des bouts du bestiau. Vu sa taille, j’suis là jusqu’aux p’tites heures du matin.\n\nPrenez cet échantillon et portez-le à Oilfist de ma part. Et vite, <classe>. Il paye BIEN !\n\nOuais, l’est à la halte du Thorium, dans la gorge des Vents brûlants.", progress = "Hmmm…", completion = "Excellent. Nous pourrons certainement utiliser cette chitine pour en faire des armures ultra-solides. Voici les richesses promises.", rewards = "Vous recevrez :\n\nSac de butin colossal"},
[8859] = {title = "Les secrets du Colosse - Zora", objective = "Apporter la Carcasse du colosse de Zora au seigneur Maxwell Tyrosus, à la chapelle de l’Espoir de lumière, dans les Maleterres de l’est.", description = "Mes serviteurs ont failli se faire tuer en récupérant ce prélèvement. Vous devez absolument vous dépêcher ! Le seigneur Maxwell Tyrosus attend impatiemment un échantillon frais de la carcasse. Il estime que les secrets de ce colosse pourraient nous aidera dans notre lutte contre le Fléau !\n\nComment, vous êtes encore là ?Allez, en route pour l’Espoir de lumière ! Oui, oui, vous serez généreusement <récompensé/récompensée> pour vos efforts…", progress = "Vous avez l’air exténué, mon ami.", completion = "Excellent et juste à temps ! Bon travail, mon gars.", rewards = "Vous recevrez :\n\nSac de butin colossal"},
[8860] = {title = "Les fêtes du Nouvel an !", objective = "Apporter les marchandises des Gourmandises Fumebois à l'aubergiste Allison, à Stormwind.", description = "Stormwind organise une fête pour le nouvel an ! De l’alcool sera distribué gratuitement toute la journée, et la nuit, il y aura des feux d’artifice ! Ce sera sans doute une jolie fête ! Mais Baie-du-Butin ne sera pas en reste et aura sa propre fête ; et je parie qu’elle sera bien plus belle !\n\nSinon, l’aubergiste Allison, à Stormwind, a besoin de marchandises des Gourmandises Fumebois pour nourrir tous les fêtards.  Vous pouvez me faire une faveur, et la livrer à ma place ?\n\nMerci, <nom> ! C’est pour l’aubergiste Allison de la Rose dorée, à Stormwind.", progress = "Bonjour ! Vous êtes là pour la fête ? Ou peut-être que vous avez besoin de reposer vos jambes fatiguées…", completion = "Oh, ma livraison des Gourmandises Fumebois ! Splendide ! Je vais en avoir besoin pour nourrir tous ceux qui sont venus en ville pour la fête !\n\nMerci beaucoup, &lt;nom&gt;. Tenez, prenez ceci en guise de remerciement, et n’oubliez pas de boire et de danser avec tous les gens qui font la fête, dehors !", rewards = "Vous recevrez :\n\n"},
[8861] = {title = "Les fêtes du Nouvel an !", objective = "Apporter les Marchandises des Gourmandises Fumebois à l'aubergiste Pala, à Thunder Bluff.", description = "Thunder Bluff organise une fête pour le nouvel an ! De l’alcool sera distribué gratuitement toute la journée, et la nuit, il y aura des feux d’artifice ! Ce sera sans doute une jolie fête ! Mais Baie-du-Butin ne sera pas en reste et aura sa propre fête ; et je parie qu’elle sera bien plus belle !\n\nSinon, l’aubergiste Pala, à Thunder Bluff, a besoin de marchandises des Gourmandises Fumebois pour nourrir tous les fêtards.  Vous pouvez me faire une faveur, et la livrer à ma place ?\n\nMerci, <nom> ! C’est pour l’aubergiste Pala, dont l’établissement est situé près du pont qui mène à la Cime des chasseurs.", progress = "Bien le bonjour, <classe> ! Vous êtes venu à Thunder Bluff pour la fête ? Ou vous êtes juste venu reposer vos sabots fatigués entre deux chasses ?", completion = "Oh, très bien !  Cette livraison va m’aider à nourrir tous nos gens, venus ici pour célébrer la nouvelle année !\n\nJe vous remercie, &lt;nom&gt;.  J’ai une dette envers vous.  Je vous en prie, prenez ces quelques pièces… et suivez mon conseil : puisez de bon cœur dans les barils qui ont été mis en perce, et rejoignez ceux qui dansent et font la fête dehors !", rewards = "Vous recevrez :\n\n"},
[8862] = {title = "La chandelle d'Elune", objective = "La chandelle d’Elune est un artefact grandement révéré par les disciples de la Fête lunaire.  Elle contient de la véritable lumière lunaire, prête à être libérée !\n\nCette lumière est inoffensive pour la plupart des créatures, mais vous constaterez qu’elle brûle et éblouit Présage et ses serviteurs.", description = nil, progress = "La chandelle d’Elune est un artefact grandement révéré par les disciples de la Fête lunaire.  Elle contient de la véritable lumière lunaire, prête à être libérée !\n\nCette lumière est inoffensive pour la plupart des créatures, mais vous constaterez qu’elle brûle et éblouit Présage et ses serviteurs.", completion = "Parfait… J’accepte ces pièces des ancêtres.  Prenez cette chandelle d’Elune avec ma bénédiction. Et tenez, voici quelques feux d’artifice en prime.\n\nQue la Fête lunaire vous soit joyeuse et pleine de divertissements, &lt;nom&gt;.\n\nEt si vous décidez d’affronter Présage et ses serviteurs, vous verrez qu’une chandelle d’Elune peut se révéler très utile…", rewards = "Vous recevrez :\n\nChandelle d'EluneSac de feux d'artifice de la fête lunaire"},
[8863] = {title = "Des raviolis de fête", objective = "Si vous avez faim, alors vous ne vous êtes pas trompé d’adresse, mon ami !\n\nLes raviolis à la vapeur sont le plat traditionnel de la fête lunaire. On en a servi  lors de la toute première célébration de cette fête, et je suis très heureux de pouvoir en proposer moi aussi cette année.  En échange d’une seule pièce des ancêtres, je vous offrirai un échantillon de l’un des meilleurs plats que vous ayez jamais dégusté !", description = nil, progress = "Si vous avez faim, alors vous ne vous êtes pas trompé d’adresse, mon ami !\n\nLes raviolis à la vapeur sont le plat traditionnel de la fête lunaire. On en a servi  lors de la toute première célébration de cette fête, et je suis très heureux de pouvoir en proposer moi aussi cette année.  En échange d’une seule pièce des ancêtres, je vous offrirai un échantillon de l’un des meilleurs plats que vous ayez jamais dégusté !", completion = "Excellent ! Tenez, prenez ces raviolis avec tous mes compliments.  Ce n’est qu’un faible témoignage de reconnaissance pour l’honneur que vous avez gagné par vos actions, mais je pense que vous m’en direz des nouvelles.\n\nSi vous avez d’autres pièces des ancêtres, je pourrai vous offrir toute une gamme d’objets en échange.", rewards = "Vous recevrez :\n\nRaviolis de fête"},
[8864] = {title = "Les robes de la fête lunaire", objective = "J’ai tout un choix de robes qui vous intéresseront sûrement. Des robes comme celles-ci ont été portées lors des  fêtes lunaires des temps anciens, et la collection présente est peut-être la plus belle que j’aie jamais vue. Chaque robe a été cousue à la main dans les matériaux les plus fins et les plus doux.\n\nEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?", description = nil, progress = "J’ai tout un choix de robes qui vous intéresseront sûrement. Des robes comme celles-ci ont été portées lors des  fêtes lunaires des temps anciens, et la collection présente est peut-être la plus belle que j’aie jamais vue. Chaque robe a été cousue à la main dans les matériaux les plus fins et les plus doux.\n\nEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?", completion = "Parfait… J’accepte ces pièces des ancêtres. Prenez votre robe avec ma bénédiction. Et tenez, voici quelques feux d’artifice en prime.\n\nVous avez honoré les anciens, et vous m’honorez de même par votre présence.  Je vous remercie. Passez une joyeuse fête lunaire.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nRobe de fête verteRobe de fête roseRobe de fête violette\n\nVous recevrez également :\n\nSac de feux d'artifice de la fête lunaire"},
[8865] = {title = "Les habits de la fête lunaire", objective = "Je suis ravi de vous informer que je possède un excellent choix d'habits de fête. Vous pouvez les acheter… mais uniquement contre des pièces des ancêtres.  Si la mode est importante à vos yeux, c’est exactement ce qu’il vous faut ! Je vous promets que vous ne trouverez pas leurs pareils dans tout Azeroth.\n\nEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?", description = nil, progress = "Je suis ravi de vous informer que je possède un excellent choix d'habits de fête. Vous pouvez les acheter… mais uniquement contre des pièces des ancêtres.  Si la mode est importante à vos yeux, c’est exactement ce qu’il vous faut ! Je vous promets que vous ne trouverez pas leurs pareils dans tout Azeroth.\n\nEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?", completion = "Parfait… J’accepte ces pièces des ancêtres.  Prenez votre habit avec ma bénédiction. Et tenez, voici quelques feux d’artifice en prime.\n\nSi vous avez d’autres pièces des ancêtres à échanger, revenez me voir. Je pourrai vous les échanger contre différents objets pendant toute la fête lunaire.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHabit de fête noirHabit de fête bleuHabit de fête turquoise\n\nVous recevrez également :\n\nSac de feux d'artifice de la fête lunaire"},
[8866] = {title = "L'Ancien Bronzebeard", objective = "Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, <nom>, et vous offre ce gage de mon estime…", description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nForce Soi - Arc\n\nVous recevrez :\n\nPièce des ancêtres"},
[8867] = {title = "Le feu d'artifice lunaire", objective = "Lancez 8 Feux d'artifice lunaires et 2 Chapelets de feux d’artifice lunaires et retournez voir une Messagère de la Fête lunaire dans l’une des capitales.", description = "Tous les ans, les druides de Reflet-de-Lune organisent une fête pour célébrer le grand triomphe de notre ville sur un mal ancien.\n\nNous honorons la sagesse de nos ancêtres, partageons d’excellents festins et, bien sûr, nous tirons des feux d’artifice !\n\nEn échange d’une petite donation, vous pourrez vous procurer des comètes colorées auprès de notre vendeur.  Essayez d’utiliser les lanceurs que vous trouverez à proximité, <nom>.", progress = "Avez-vous trouvé les lanceurs, <nom> ?", completion = "Bien joué, &lt;nom&gt;.\n\nPuisque vous semblez d’humeur festive, pourquoi ne prenez-vous pas cette invitation pour la célébration de Reflet-de-Lune ?\n\nLes réjouissances y sont très sympathiques, si vous avez le temps d’y passer. Nous partageons là-bas des mets raffinés, d’excellentes boissons, des histoires et, bien sûr… d’autres feux d’artifice !\n\nOuvrez l’invitation lorsque vous vous trouverez à l’intérieur d’un cercle de Lumière lunaire supérieure, et vous serez téléporté à Reflet-de-Lune.", rewards = "Vous recevrez :\n\nInvitation à la fête lunaire"},
[8868] = {title = "La bénédiction d'Elune", objective = "Invoquez Présage, et vainquez-le pour gagner la Bénédiction d’Elune. Puis retournez voir Valadar Starsong à Havrenuit.", description = "La bête Présage était autrefois un héros de ce monde, un loup d’une grande force et d’une grande valeur. Présage combattit aux côtés des héros de la guerre des Anciens, jusqu’à ce qu’il succombe à des magies démoniaques. Se retournant contre ses alliés, il dévasta Azeroth, répandant mort et terreur sur son passage.\n\nIl fut finalement vaincu ici, à Reflet-de-Lune. Présage dort maintenant sous les eaux du lac Elune’ara. Mais à chaque nouvel an, durant la fête, il s’agite…\n\nRassemblez des compagnons, <nom>, pour invoquer et vaincre Présage. Il vous faut mériter la  bénédiction d’Elune !", progress = nil, completion = "Très bien joué, &lt;nom&gt;. La défaite de Présage a renvoyé son esprit sous les eaux d’Elune’ara.  La bête elle-même est bénie d’Elune et ne peut donc pas être tuée, mais sa colère est à présent calmée pour une année entière.\n\nIl faut célébrer votre victoire, &lt;nom&gt;, célébrer la puissance de Présage, la vôtre et celle de vos alliés, ainsi que la paix que vous avez donnée à ce héros tragique de notre passé.", rewards = "Vous recevrez :\n\nLanterne d'EluneSac de feux d'artifice de la fête lunairePierre solide"},
[8869] = {title = "Douce sérénité", objective = "Aller jusqu’à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le ramener à Lilith.", description = "Dans les confins du Bastion écarlate se trouve la douce Sérénité. Le Forgeur de marteaux cramoisi garde ce secret de sa vie. Battez-le et apportez-moi son tablier. En échange, je vous enseignerai comment forger des marteaux.\n\nMais sachez bien ceci : une fois que vous aurez choisi de suivre cette voie, les arts de la forge d'épées ou de haches vous seront à jamais fermées.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant de marteaux\n\nVous recevrez :\n\nPlans : Marteau de guerre enchanté"},
[8870] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire à la Garde mystique d’Ironforge. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8871] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire au Parc de Stormwind. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8872] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire à l'Enclave cénarienne de Darnassus. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8873] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire dans la Vallée de la sagesse à Orgrimmar. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8874] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire à l'entrée d'Undercity. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8875] = {title = "La fête lunaire", objective = "Parler à la messagère de la Fête lunaire à la Cime des Anciens de Thunder Bluff. Vous pouvez aussi parler aux messagers de la Fête lunaire des autres capitales.", description = "C’est l’époque des réjouissances, <nom> ! Le Cercle cénarien invite tous les habitants d’Azeroth à célébrer avec lui la Fête lunaire.  Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire.  Elle pourra vous en dire plus sur la fête.", progress = nil, completion = "Soyez le bienvenu, &lt;nom&gt;. Vous venez ici pour vous joindre à la fête ?", rewards = nil},
[8876] = {title = "Les petites comètes", objective = "Je connais le secret de la fabrication des comètes de la Fête lunaire, et je serais très heureuse de partager mes connaissances avec une personne aussi honorable que vous.\n\nEn échange de quelques pièces des ancêtres, je peux vous offrir les recettes de fabrication d’une petite comète…", description = nil, progress = "Je connais le secret de la fabrication des comètes de la Fête lunaire, et je serais très heureuse de partager mes connaissances avec une personne aussi honorable que vous.\n\nEn échange de quelques pièces des ancêtres, je peux vous offrir les recettes de fabrication d’une petite comète…", completion = "Ah, parfait… Voici vos recettes, &lt;nom&gt;, et qu’Elune vous bénisse.", rewards = "Vous recevrez :\n\nRecettes des petites comètesSac de feux d'artifice de la fête lunaire"},
[8877] = {title = "Le lanceur de fusées", objective = "Même si les comètes permettent d’animer la fête de merveilleuse façon, il faut les tirer avec un lanceur pour pouvoir les contempler dans toute leur splendeur.\n\nApportez-moi des pièces des ancêtres, et je vous apprendrai gracieusement comment fabriquer des lanceurs de fusée comme ceux qui se trouvent à Reflet-de-Lune.", description = nil, progress = "Même si les comètes permettent d’animer la fête de merveilleuse façon, il faut les tirer avec un lanceur pour pouvoir les contempler dans toute leur splendeur.\n\nApportez-moi des pièces des ancêtres, et je vous apprendrai gracieusement comment fabriquer des lanceurs de fusée comme ceux qui se trouvent à Reflet-de-Lune.", completion = "Ah, vous voici, &lt;nom&gt;. Voici le schéma permettant de fabriquer un lanceur de comètes. Placez le lanceur à l’endroit où vous voulez faire la fête, et vous pourrez ensuite accueillir les amis qui viendront vous rejoindre !", rewards = "Vous recevrez :\n\nSchéma : Lanceur de fuséesSac de feux d'artifice de la fête lunaire"},
[8878] = {title = "Des recettes de fête", objective = "Les robes et les habits que vous voyez sont des costumes traditionnels des temps anciens.  On les porte en l’honneur de nos vieilles coutumes et de nos chers disparus.\n\nSi vous m’apportez des pièces des ancêtres, <nom>, je vous donnerai le patron pour confectionner une robe rouge ou un habit rouge traditionnels.", description = nil, progress = "Les robes et les habits que vous voyez sont des costumes traditionnels des temps anciens.  On les porte en l’honneur de nos vieilles coutumes et de nos chers disparus.\n\nSi vous m’apportez des pièces des ancêtres, <nom>, je vous donnerai le patron pour confectionner une robe rouge ou un habit rouge traditionnels.", completion = "Voici les patrons, &lt;nom&gt;.  Je suis certaine que vous constaterez que ces vêtements sont d’une grande beauté.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPatron : Robe de fêtePatron : Habit de fête\n\nVous recevrez également :\n\nSac de feux d'artifice de la fête lunaire"},
[8879] = {title = "Les grandes comètes", objective = "Les grandes comètes de la Fête lunaire illuminent brillamment le ciel et leur magnificence n’est rivalisée que par celle des chapelets !\n\nApportez-moi des Pièces des ancêtres, <nom>, et je vous révélerai le secret de leur fabrication.", description = nil, progress = "Les grandes comètes de la Fête lunaire illuminent brillamment le ciel et leur magnificence n’est rivalisée que par celle des chapelets !\n\nApportez-moi des Pièces des ancêtres, <nom>, et je vous révélerai le secret de leur fabrication.", completion = "Parfait… J’accepte ces pièces des ancêtres. Voici vos recettes, &lt;nom&gt;. Puissiez-vous vous en servir pour célébrer la gloire d’Elune !", rewards = "Vous recevrez :\n\nRecettes de grandes comètesSac de feux d'artifice de la fête lunaire"},
[8880] = {title = "Les chapelets de comètes", objective = "Les chapelets de comètes sont un assemblage de comètes individuelles, et ils sont d’une beauté impressionnante ! Apportez-moi des pièces des ancêtres et je vous apprendrai le secret de leur fabrication…", description = nil, progress = "Les chapelets de comètes sont un assemblage de comètes individuelles, et ils sont d’une beauté impressionnante ! Apportez-moi des pièces des ancêtres et je vous apprendrai le secret de leur fabrication…", completion = "Ah, vous voici, &lt;nom&gt;. Prenez ces recettes et apprenez leurs secrets. Je vous souhaite tout le bonheur du monde, et j’attends avec impatience de voir vos magnifiques créations.", rewards = "Vous recevrez :\n\nRecettes de chapelet de comètesSac de feux d'artifice de la fête lunaire"},
[8881] = {title = "Les chapelets de grandes comètes", objective = "La fabrication des chapelets de comètes exige beaucoup de ressources et d’habileté, mais leur brillance et leur beauté valent largement les efforts ainsi déployés ! Apportez-moi des pièces des ancêtres et je vous révélerai le secret de leur création.", description = nil, progress = "La fabrication des chapelets de comètes exige beaucoup de ressources et d’habileté, mais leur brillance et leur beauté valent largement les efforts ainsi déployés ! Apportez-moi des pièces des ancêtres et je vous révélerai le secret de leur création.", completion = "Merci, &lt;nom&gt;. Voici la recette du chapelet de grandes comètes. Que vos créations apportent la joie et la chance à tous ceux qui les contempleront.", rewards = "Vous recevrez :\n\nRecettes de chapelet de grandes comètesSac de feux d'artifice de la fête lunaire"},
[8882] = {title = "Le lanceur de chapelets", objective = "Les plus beaux feux d’artifice se doivent de présenter des chapelets de comètes, et ces chapelets ne peuvent être tirés qu’avec un lanceur spécial ! Il me semble donc logique que vous appreniez le secret de la fabrication des lanceurs de chapelets. Apportez-moi des pièces des ancêtres et je partagerai ce secret avec vous.", description = nil, progress = "Les plus beaux feux d’artifice se doivent de présenter des chapelets de comètes, et ces chapelets ne peuvent être tirés qu’avec un lanceur spécial ! Il me semble donc logique que vous appreniez le secret de la fabrication des lanceurs de chapelets. Apportez-moi des pièces des ancêtres et je partagerai ce secret avec vous.", completion = "Et voici votre schéma… Étudiez-le attentivement, et apprenez-le…\n\nBonne chance, &lt;nom&gt;. Que votre célébration rivalise avec celle de la Fête lunaire elle-même !", rewards = "Vous recevrez :\n\nSchéma : Lanceur de chapeletsSac de feux d'artifice de la fête lunaire"},
[8883] = {title = "Valadar Starsong", objective = "Utilisez votre Invitation à la fête lunaire dans la lumière lunaire pour vous rendre à Reflet-de-Lune. À votre arrivée, parlez à Valadar Starsong.", description = "Maintenant que vous avez reçu votre invitation pour la Fête lunaire, vous pouvez vous rendre à Reflet-de-Lune. Vous y trouverez de nombreux célébrants. Valadar Starsong et sa soeur Fariel attendent ceux qui veulent participer à la célébration au village de Havrenuit.\n\nRendez-vous à Reflet-de-Lune via la lumière lunaire supérieure et parlez à Valadar Starsong. Voyons quels cadeaux vous pourrez gagner pendant la fête !", progress = nil, completion = "Bienvenue à Havrenuit pour cette Fête lunaire, &lt;nom&gt; ! En temps normal, notre village perdu est largement coupé du reste d’Azeroth, mais pendant cette célébration, nous ouvrons nos bras et nos cœurs à tous !\n\nSavourez votre visite, &lt;nom&gt;, et lorsque vous serez prêt, venez nous parler, à moi ou à ma sœur.", rewards = "Vous recevrez :\n\n"},
[8884] = {title = "Des têtes de poisson à la pelle", objective = "Collecter 8 Têtes de Murloc sinistrécaille et retourner voir Hathvelion Miresoleil dans le bois des Chants éternels sur le piton qui domine le Rivage paisible.", description = "Salutations, <classe>. Regardez vers la côte ; que voyez-vous ? En effet, notre plage... notre Rivage paisible, est infestée de cette nuisance connue sous le nom de Murlocs.\n\nNous devons la libérer de cette plaie !\n\nJ'ai une tâche à vous confier. Si vous pensez être à la hauteur, je souhaite avoir leurs têtes ! Voyons si nous parvenons à suffisamment réduire leur nombre pour qu'ils retournent dans les profondeurs troubles d'où ils sont venus, s'ils sont un tant soit peu raisonnables !", progress = "Nous autres forestiers de la retraite des Pérégrins nous consacrons à la réparation des dégâts qui ont frappé notre belle région. Nous sommes prêts à tout dans ce but.\n\nJ'imagine que vous avez les têtes de Murlocs que je vous ai chargé de rapporter ?", completion = "Bon travail, &lt;classe&gt;. Si on peut se fier à l'odeur, on dirait que vous apportez tout ce que je vous ai demandé, et peut-être même plus. Je suis certain que nous saurons quoi en faire. Un ragoût ou quelque chose de semblable.\n\nHélas, il semble que vos efforts n'aient pas été suffisants. Les Murlocs ne battent pas en retraite. Une action plus directe est nécessaire !", rewards = "Vous recevrez :\n\n"},
[8885] = {title = "L'anneau de Mmmrrrggglll", objective = "Récupérez l'Anneau de Mmmrrrggglll sur la patte sans vie du chef des Sinistrécaille. Rapportez-le à Hathvelion Miresoleil dans le bois des Chants éternels sur le piton surplombant le Rivage paisible.", description = "Les Murlocs sinistrécaille n'ont pas été effrayés par vos efforts. Mais je crois savoir ce qui leur ferait plier bagage, et me donnerait l'occasion de me venger par la même occasion.\n\nIls ont un chef murloc qui se donne le nom de Mmmrrrggglll. Il parcourt la Grève dorée au sud du fleuve. Cette bête a un jour tué l'un de mes compatriotes et porte maintenant son anneau pour nous défier et se moquer de nous.\n\nExécutez Mmmrrrggglll et rapportez-moi l'anneau de mon ami. Voilà qui devrait suffisamment intimider ces monstres !", progress = "Vous êtes l'instrument de mon succès et de ma vengeance, <classe>. Avez-vous l'anneau ?", completion = "Enfin ! Même si les Sinistrécaille ne sont pas partis comme nous l'espérions, c'était amusant de voir la panique et la confusion que vous avez semées quand vous avez abattu leur soi-disant chef. Je vous remercie, vous avez toute la gratitude des sin'dorei de la ville de Lune-d’Argent.\n\nVeuillez accepter l'un de ces objets en remerciement du service que vous nous avez rendu.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23395Objet #23396Objet #23397Objet #23398Objet #133694\n\nVous recevrez également :\n\n"},
[8886] = {title = "Les pirates Sinistrécaille !", objective = "Récupérez 6 caisses de la Cargaison du capitaine Kelisendra et rapportez-les à cette dernière au camp protégé juste à l'est du mouillage des Voiles du soleil dans le bois des Chants éternels.", description = "Heureusement que vous êtes là, <classe> ! Ces répugnants Murlocs sinistrécaille ont volé ma cargaison ! Comme si ça ne suffisait pas que les Déshérités aient pris le peu de marchandises magiques que j'avais, les Murlocs ont pris le reste ! Qu'est donc devenu cet endroit ?\n\nPourriez-vous récupérer ma cargaison ? Je ne m'attends pas à ce que vous puissiez tout rapporter, mais au point où j'en suis, je vous serais reconnaissante pour la moindre part. C'était ce groupe de Murlocs sinistrécaille dans les huttes juste à l'ouest et au sud du mouillage de la Grève dorée, j'en suis certaine !", progress = "J'apprécie beaucoup votre aide, <nom>. Ça me rend presque le sourire. Mais ensuite je repense à ce que ces monstres ont fait à mon bateau et à ce qui se passe à Quel'Thalas.\n\nAvez-vous réussi à récupérer une partie de ma cargaison ?", completion = "Vous avez réussi ! Vous m'avez sauvée de la ruine et vengée de ces horribles créatures !\n\nMaintenant, si j'arrivais à convaincre ces beaux forestiers de m'aider à charger la cargaison, je pourrais enfin partir d'ici ! Il faudra que je revienne quand Velendris aura repris le mouillage.\n\nTenez, prenez ces pièces. C'est tout ce que je peux vous donner, mais c'est la moindre des choses pour vous remercier de vos efforts.", rewards = "Vous recevrez :\n\n"},
[8887] = {title = "Les portulans perdus du capitaine Kelisendra", objective = "Rendez les Portulans perdus du capitaine Kelisendra à cette dernière au camp protégé, juste à l'est du mouillage des Voiles du soleil dans le bois des Chants éternels.", description = "Intéressant… vous avez trouvé un tube de cuir étanche contenant un certain nombre de feuilles de parchemin. Il s’agit de toute évidence de cartes marines, et elles portent toutes la signature d’un certain capitaine Kelisendra.\n\nVous avez entendu parler d’un petit camp fortifié, juste à l’est du mouillage des Voiles du soleil. Le capitaine y est peut-être ?", progress = "Salutations, <classe>, votre vue me fait bien plaisir. Je sais, maintenant que le mouillage a été conquis par les Déshérités, je ne devrais vraiment pas rester là. Velendris et ses forestiers ont juré de me protéger, à condition que je m’en aille dès que j’aurai récupéré ma cargaison.\n\nQu’avez-vous là… cela me semble vaguement familier ?", completion = "Oh, vous êtes vraiment un merveilleux, un extraordinaire &lt;classe&gt; ! Ces infects Murlocs sinistrécaille avaient aussi embarqué mes portulans et je ne m’en doutais même pas ! Sans eux, je n’aurai jamais pu reprendre la mer, même une fois le mouillage reconquis et le navire réparé.\n\nMerci, merci beaucoup ! Tenez, prenez cet argent, c’est le moins que je puisse faire pour vous montrer ma reconnaissance.", rewards = "Vous recevrez :\n\n"},
[8888] = {title = "L'apprentie du magistère", objective = "Parler à l'apprentie Loralthalis près de la Flèche de Ternesoir dans le bois des Chants éternels.<classe>, écoutez ma requête. Pour des raisons que je ne peux donner pour l'instant, j'ai décidé de fermer mon école, qui se trouve près d'ici. Il y a quelques jours, j'ai envoyé là-bas l'une de mes élèves, l'apprentie Loralthalis. Je n'ai cependant pas eu de ses nouvelles depuis.\n\nPourriez-vous s'il vous plaît vous rendre à la Flèche de Ternesoir et vous assurer qu'elle va bien ? Pour cela, dirigez-vous vers le nord à la sortie de la retraite des Pérégrins, puis allez à droite à l'embranchement.\n\nMerci.", description = "<classe>, écoutez ma requête. Pour des raisons que je ne peux donner pour l'instant, j'ai décidé de fermer mon école, qui se trouve près d'ici. Il y a quelques jours, j'ai envoyé là-bas l'une de mes élèves, l'apprentie Loralthalis. Je n'ai cependant pas eu de ses nouvelles depuis.\n\nPourriez-vous s'il vous plaît vous rendre à la Flèche de Ternesoir et vous assurer qu'elle va bien ? Pour cela, dirigez-vous vers le nord à la sortie de la retraite des Pérégrins, puis allez à droite à l'embranchement.\n\nMerci.", progress = nil, completion = "Le magistère s'inquiétait pour moi ? Comme c'est gentil à lui. Dommage qu'il ne m'ait pas témoigné plus d'intérêt avant, quand nous étions sur la Flèche.\n\nMais peu importe maintenant. Écoutez-moi attentivement, &lt;classe&gt;, car j'ai une faveur à vous demander.", rewards = "Vous recevrez :\n\n"},
[8889] = {title = "Désactiver la flèche", objective = "Désactiver les 3 Sources d'énergie de la Flèche de Ternesoir à l'intérieur de la flèche de Ternesoir. Puis rapporter le Joyau de désactivation à l'apprentie Loralthalis dans le bois des Chants éternels.", description = "Comme vous le savez peut-être déjà, le magistère Ternesoir m'a envoyée pour désactiver les sources d'énergie qui alimentent la Flèche. Il y en a trois, chacune à un endroit différent à l'intérieur.\n\nMalheureusement, comme vous pouvez le constater, on dirait que je suis arrivée trop tard, et la flèche de Ternesoir est envahie d'étranges créatures magiques. Je n'ai pas les compétences pour mener à bien cette tâche, mais <un/une:c> <classe> comme vous pourrait sûrement le faire facilement, non ?", progress = "Je ne vois pas bien à cette distance… Avez-vous déjà coupé l'alimentation à la flèche de Ternesoir ?", completion = "Je vous suis reconnaissante pour votre aide, mais je suis aussi attristée d'apprendre que certains de mes camarades apprentis ont succombé à leur addiction.\n\nMaintenant que l'alimentation de la Flèche a été coupée, je crois que je vais rester ici un moment et voir si la situation se calme assez longtemps pour que je puisse me glisser là-bas et récupérer leurs restes.", rewards = "Vous recevrez :\n\n"},
[8890] = {title = "Une communication de la flèche", objective = "Retourner voir le magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.<nom>, j'ai une dernière faveur à vous demander. Voudriez-vous tenir au courant de ce qui s'est passé ici le magistère Ternesoir à la retraite des Pérégrins ? Dites-lui que je vais bien, mais surtout faites en sorte qu'il sache que certains apprentis sont devenus des Déshérités.\n\nMerci pour votre aide !", description = "<nom>, j'ai une dernière faveur à vous demander. Voudriez-vous tenir au courant de ce qui s'est passé ici le magistère Ternesoir à la retraite des Pérégrins ? Dites-lui que je vais bien, mais surtout faites en sorte qu'il sache que certains apprentis sont devenus des Déshérités.\n\nMerci pour votre aide !", progress = nil, completion = "Non ! J'ai trop tardé. Tout est de ma faute.\n\nJ'ai perdu le contrôle de mes recherches sur la purification de sources de magie alternatives avant de pouvoir y mettre fin. Si seulement j'y étais allé moi-même... Si seulement ils m'avaient écouté, et tenu compte de mes avertissements !\n\nJ'ai du sang sur les mains, &lt;classe&gt;. Je vous remercie cependant d'avoir donné le repos aux âmes torturées de mes anciens apprentis. C'est une mince consolation de savoir qu'ils ne demeurent pas dans cet état auquel un Elfe de sang préfère la mort.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nObjet #23399\n\nVous recevrez également :\n\n"},
[8891] = {title = "Des recherches abandonnées", objective = "Rapporter le Journal du magistère Ternesoir au magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.", description = "Vous avez découvert ce qui semble être un journal de recherches, laissé là par le magistère Ternesoir. Un bref examen de son contenu vous révèle de choquantes tentatives de filtration de flux magiques corrompus, ce qui pourrait expliquer ce qui s'est passé ici à la flèche de Ternesoir. Il est certain que le magistère voudrait qu'on le lui rapporte.", progress = "Qu'est-ce que c'est ? Ça me rappelle quelque chose. Oh non, ce journal... mes recherches... Voilà la cause de tout cela.", completion = "La voilà, &lt;nom&gt;, la preuve de mon crime. Ce journal contient toutes mes malencontreuses études.\n\nJ’ai poursuivi mes recherches sans tenir compte des avertissements, jusqu’à ce qu’il soit presque trop tard. Puis, quand j’ai compris mon erreur, j’ai fait ce que j’ai pu. Mais à ce stade, certains de mes élèves étaient déjà allés trop loin. J’ai fait évacuer la Flèche pour les éloigner de la corruption, mais dans ma hâte, j’ai oublié de couper les sources d’énergie.\n\nJe vais brûler ce grimoire afin que personne d’autre ne devienne la victime du savoir qu’il renferme. Je voulais seulement aider les Sin’dorei.", rewards = "Vous recevrez :\n\n"},
[8892] = {title = "La situation au mouillage des Voiles du soleil", objective = "Tuez 5 Nervis déshérités et 5 Voyous déshérités, puis allez faire votre rapport au forestier Degolien au bois des Chants éternels.", description = "Le mouillage des Voiles du soleil a été conquis par des vermines de Déshérités. Dès que nous aurons des renforts, nous montrerons à ces brutes qui est le patron, <nom>.\n\nDans l’intervalle, ralentissez-les donc un peu tout en leur apprenant un peu de discipline. Allez-y, et montrez-leur qu’on ne se moque pas de nous impunément. Vous trouverez le mouillage des Voiles du soleil juste à l’ouest du village de Brise-clémente.", progress = nil, completion = "Voilà qui leur apprendra à nous laisser tranquilles. Bon travail, &lt;nom&gt;.", rewards = "Vous recevrez :\n\n"},
[8893] = {title = "Le Super-Oeuf-O-Matic", objective = "Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C'est une machinerie très impressionnante.\n\nLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.", description = nil, progress = "Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C'est une machinerie très impressionnante.\n\nLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.", completion = "Vous placez l'œuf d'hippogryphe dans la machine. Des signaux sonores s'enchaînent, sur un fond de bruits mécaniques.\n\nEt le Calibre-œuf a pesé, mesuré et empaqueté votre œuf. Ça c'est du service rapide !", rewards = "Vous recevrez :\n\nCaisse d'oeufs"},
[8894] = {title = "Corvée de nettoyage", objective = "Tuez 6 Serpents de mana et 6 Fieléthers, puis retournez voir le paysagiste Wyllithen, sur les Terres de Ternesoir, dans le bois des Chants éternels.", description = "C’est affreux ! Affreux ! Il se passe des choses étranges à la flèche, le magistère et ses apprentis s’enfuient, et juste après, voilà que tout le domaine est infesté de bestioles magiques ! Et qui s’est donné la peine de prévenir ce pauvre Wyllithen ? Personne, voilà qui !\n\nIl va falloir que vous m’aidiez à faire disparaître ces monstres, <classe>… Je ne peux pas entretenir le domaine avec ces « anomalies » qui galopent dans tous les coins !", progress = nil, completion = "Bon, je suppose qu’il faudra bien que cela fasse l’affaire, n’est-ce pas ? Merci de votre aide, &lt;classe&gt;. J’espère que tout ce gâchis sera nettoyé lorsque le magistère reviendra à la flèche de Ternesoir.\n\nTenez, prenez cette menue monnaie. Ce n’est pas grand-chose, mais c’est tout ce que j’ai pour l’instant. Oh, vous seriez gentil d’en tuer quelques autres en partant, si cela ne vous dérange pas.", rewards = "Vous recevrez :\n\n"},
[8895] = {title = "Une livraison au sanctum septentrional", objective = "Remettre la Lettre sans marque au telluriste Caidanis, au Sanctum septentrional du bois des Chants éternels.", description = "Il est bon de découvrir que vous êtes au moins modérément <compétent/compétente>, <nom>. Et comme vous semblez très <désireux/désireuse> de faire vos preuves, je vais vous confier une autre tâche.\n\nVoici une lettre pour le telluriste Caidanis, l’arcaniste qui veille à ce que le sanctum septentrional continue à fonctionner. Lorsque vous quittez la place de l'Épervier, allez au sud-ouest et vous le trouverez. C’est une personne très importante. J’espère que vous ne l'importunerez pas trop avec des bavardages inutiles.", progress = "Oui, <classe> ?", completion = "Merci, &lt;nom&gt;. J’attendais cette lettre.", rewards = "Vous recevrez :\n\n"},
[8896] = {title = "L'espion des nains", objective = "Trouvez et tuez le prospecteur Garde-enclume au Sanctum septentrional, puis faites votre rapport à Aeldon Signesol, dans le bois des Chants éternels.Vous êtes <sûr/sûre> que vous avez trouvé ces notes sur un elfe de la nuit ? Elles sont presque entièrement rédigées dans la langue des nains…\n\nLe prospecteur Garde-enclume ! Il nous est arrivé de Forgefer en mission diplomatique. J’aurais dû me douter qu’il s’intéressait d’un peu trop près à nos sanctum arcaniques. <nom>, il se trouve au sanctum septentrional. Trouvez-le et occupez-vous de lui. Discrètement.", description = "Vous êtes <sûr/sûre> que vous avez trouvé ces notes sur un elfe de la nuit ? Elles sont presque entièrement rédigées dans la langue des nains…\n\nLe prospecteur Garde-enclume ! Il nous est arrivé de Forgefer en mission diplomatique. J’aurais dû me douter qu’il s’intéressait d’un peu trop près à nos sanctum arcaniques. <nom>, il se trouve au sanctum septentrional. Trouvez-le et occupez-vous de lui. Discrètement.", progress = nil, completion = nil, rewards = nil},
[8897] = {title = "Très chère Colara,", objective = "Apporter la Note soigneusement calligraphiée du lieutenant Heldric à Colara Dean, devant la banque de Stormwind.", description = "Je suis forcé de rester ici à monter la garde devant la porte, mais je m’inquiète pour Colara, ma bien-aimée. Je ne la vois que quelques heures, quand j’ai de la chance, et bon, regardez-moi… J’ai une paye d'officier subalterne et on peut m’expédier au front d’un moment à l’autre.\n\nEt si elle m’oubliait ? Les hommes ne manquent pas en ville. Y compris des hommes riches.\n\nBref, j’ai essayé de lui écrire. Ce n’est pas grand-chose, mais si vous pouviez lui apporter ma lettre, ce serait merveilleux.", progress = "Bonjour, beau gosse. Puis-je faire quelque chose pour vous ?", completion = "Oh, comme c’est gentil ! C’est la première fois qu’il m’envoie quelque chose. Ça pourrait devenir sérieux, vous ne croyez pas ?\n\nColara Heldric ? Je trouve que ça sonne bien… Mais bon, ce n’est pas encore fait. Merci, en tout cas.", rewards = nil},
[8898] = {title = "Très chère Colara,", objective = "Apporter la Lettre froissée à Colara Dean, devant la banque de Stormwind.", description = "La dernière fois que je suis passé à Stormwind pour les affaires de la banque, j’ai rencontré une fille et elle m’a volé mon cœur. Je n’arrête pas de penser à elle ! Je lui ai écrit une lettre – je m’y suis repris à douze fois !\n\nJe n’ai pas confiance dans la poste, et je veux être sûr qu’elle l’aura. Si vous allez dans cette direction, pourriez-vous me rendre service ?", progress = "Bonjour, beau gosse. Puis-je faire quelque chose pour vous ?", completion = "Tormek ? Bien sûr que je m’en souviens ! Une belle barbe, avec un joli sourire dessous.\n\nIl s’est souvenu de moi ? Je n’arrive pas à y croire !", rewards = nil},
[8899] = {title = "Très chère Colara,", objective = "Apporter la Lettre immaculée à Colara Dean, devant la banque à Stormwind.", description = "Comment décrire sa beauté ? Des milliers d’années à manier les mots, et me voilà à court.\n\nCes mortelles perturbent notre esprit et font de nous des fous balbutiants.\n\nJ’ai contemplé ces mots pendant trop longtemps. Je ne peux rien en tirer de plus éloquent. Non, elle doit avoir ma lettre maintenant, sans quoi un autre soupirant finira par attirer son attention.", progress = "Bonjour, beau gosse. Puis-je faire quelque chose pour vous ?", completion = "Je n’ai jamais reçu ce genre de chose avant. Comme c’est gentil !", rewards = nil},
[8900] = {title = "Très chère Elenia,", objective = "Apporter la Note légèrement froissée à Elenia Haydon, près de la banque d'Undercity.", description = "Elle était si triste. Je le voyais bien, en regardant au-delà de son état. Je veux dire, elle semblait triste. Ne l'auriez-vous pas été ?\n\nMais lorsque je lui ai parlé, nous avons créé un lien. Je n'aurais jamais cru que quelqu'un pourrait comprendre ce que je pensais, mais elle y était parvenue.\n\nQuand j'en ai parlé aux autres, ils se sont moqués de moi, alors je ne lui ai jamais reparlé. Mais elle me manque. Pouvez-vous lui apporter cette lettre de ma part ? Je veux être sûr qu'elIe lui sera remise en mains propres.", progress = "Oh, et à qui dois-je ce plaisir ?", completion = "On ne s'attendrait pas à ce qu'un orc se montre si éloquent. Bien sûr, nous n'avions jamais eu vraiment l'occasion de les connaître avant aujourd'hui. Merci de m'avoir apporté cette lettre.", rewards = nil},
[8901] = {title = "Très chère Elenia,", objective = "Apporter la Lettre écrite avec soin à Elenia Haydon, près de la banque d'Undercity.", description = "Avez-vous déjà connu l'amour, jeune <homme/femme> ? Ce sentiment m'était totalement étranger, jusqu'à ce que je rencontre dernièrement une fille d'Undercity, Elenia. Il est déjà rare pour les gens comme nous de chercher ailleurs que dans notre peuple, alors ne parlons même pas des Réprouvés.\n\nMais aujourd'hui, elle hante mon esprit jour et nuit.\n\nSi cela vous est possible, pouvez-vous lui remettre cette lettre ? Je voudrais qu'elle vienne ici, à Mulgore. J'espère qu'elle dira oui.", progress = "Oh, et à qui dois-je ce plaisir ?", completion = "Temma m’écrit de fort belles choses. Ses mots m’émeuvent, mais je ne peux pas accepter l’amour d’un &lt;race&gt;. Nous sommes trop différents. Nos corps, nos esprits et nos pensées sont trop éloignés.\n\nHeureusement qu’il n’est pas venu me faire part de ses pensées en personne. Lui briser le cœur m’aurait fait souffrir.", rewards = nil},
[8902] = {title = "Très chère Elenia,", objective = "Apporter la Lettre pleine d'amour à Elenia Haydon, près de la banque d’Undercity.", description = "C’était dans une autre vie, mais j’ai été promis à Elenia, mon amour d’enfance. Je l’avais oubliée depuis des années mais depuis peu, je pense de plus en plus à elle.\n\nMalgré tout ce qui s’est passé, il reste peut-être un peu de place pour l’amour dans nos existences.\n\nJe suis sûr qu’elle a changé, elle aussi. Pouvez-vous lui remettre cette lettre de ma part ? Je suis trop nerveux pour la lui donner en personne.", progress = nil, completion = nil, rewards = nil},
[8903] = {title = "Les périls de l'amour", objective = "Obtenez une Carte de garde de Stormwind et ramenez-là à Aristan Mottar, à Stormwind.", description = "Cette épidémie d’amour a quelque chose de pas naturel. Ce n’est ni esthétique, ni convenable. Et pire, cela pourrait poser une menace pour la sécurité de l’Alliance toute entière.\n\nQue se passerait-il si les gardes étaient atteints par cette étrange maladie ? Il faut faire quelque chose.\n\nExaminez donc les gardes de Stormwind et voyez s’ils sont devenus aussi déraisonnables que les autres.", progress = "Alors, avais-je raison de m’inquiéter ? Nos gardes sont-ils malades d’amour, eux aussi ?", completion = "Mes craintes étaient justifiées. C’est incroyable. Comment est-ce possible ? Laissez-moi réfléchir un moment. Il doit y avoir une raison à tout ceci.", rewards = nil},
[8904] = {title = "Les périls de l'amour", objective = "Obtenez une Carte de garde moisie et ramenez-là à Fenstad Argyle, à Undercity.", description = "Il y a quelque chose de pas naturel dans cette épidémie amoureuse. Elle est écœurante, elle affaiblit nos défenses, et elle pourrait nous mettre tous en danger.\n\nQue la plupart d’entre nous soient en train de se rendre ridicule est déjà déplaisant. Mais j’ai peur que même nos gardes, qui devraient être immunisés à ce genre de chose, ne soient touchés.\n\nExaminez donc les gardes et voyez s’ils sont devenus aussi déraisonnables que les autres.", progress = "Alors, avais-je raison de m’inquiéter ? Nos imbéciles de gardes sont-ils atteints ?", completion = "Incroyable. J’avais raison de m’inquiéter. Comment est-ce possible ? Laissez-moi réfléchir un moment. Il doit y avoir une raison à tout ceci.", rewards = nil},
[8905] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards du Coeur-sauvage à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards Cœur-Farouche"},
[8906] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Manchettes de bestiaire à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nManchettes de belluaire"},
[8907] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Bracelets de magistère à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nManchettes du sorcier"},
[8908] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de Sancteforge à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards d'Âmeforge"},
[8909] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de dévot à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards vertueux"},
[8910] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Bracelets Sombreruse à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards Sombremante"},
[8911] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de Brume-funeste à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards Mortebrume"},
[8912] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de vaillance à Deliana à Ironforge.", description = "Voilà une heureuse rencontre, <classe>, car j’ai quelque chose qui pourrait vous intéresser.\n\nJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.\n\nEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards d'héroïsme"},
[8913] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards du Coeur-sauvage à Mokvar, à Orgrimmar.", description = "Salut, <classe> ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n’avez jamais vu une pièce d’armure comme celle-ci.\n\nSi vous m’accordez une petite faveur, je suis prêt à vous l’échanger contre une paire de brassards ordinaires.\n\nJ’ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d’or en plus, et nous ferons l’échange.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards Cœur-Farouche"},
[8914] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Manchettes de bestiaire à Mokvar, à Orgrimmar.", description = "Salut, <classe> ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n’avez jamais vu une pièce d’armure comme celle-ci.\n\nSi vous m’accordez une petite faveur, je suis prêt à vous l’échanger contre une paire de brassards ordinaires.\n\nJ’ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d’or en plus, et nous ferons l’échange.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nManchettes de belluaire"},
