[8918] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets des éléments à Mokvar, à Orgrimmar.", description = "Salut, <classe> ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n’avez jamais vu une pièce d’armure comme celle-ci.\n\nSi vous m’accordez une petite faveur, je suis prêt à vous l’échanger contre une paire de brassards ordinaires.\n\nJ’ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d’or en plus, et nous ferons l’échange.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nManchettes des Cinq tonnerres"},
[8919] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de Brume-funeste à Mokvar, à Orgrimmar.", description = "Salut, <classe> ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n’avez jamais vu une pièce d’armure comme celle-ci.\n\nSi vous m’accordez une petite faveur, je suis prêt à vous l’échanger contre une paire de brassards ordinaires.\n\nJ’ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d’or en plus, et nous ferons l’échange.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards Mortebrume"},
[8920] = {title = "Une proposition sérieuse", objective = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de vaillance à Mokvar, à Orgrimmar.", description = "Salut, <classe> ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n’avez jamais vu une pièce d’armure comme celle-ci.\n\nSi vous m’accordez une petite faveur, je suis prêt à vous l’échanger contre une paire de brassards ordinaires.\n\nJ’ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d’or en plus, et nous ferons l’échange.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBrassards d'héroïsme"},
[8921] = {title = "L'alambic ectoplasmique", objective = "Retournez voir Mux Manascrambler à Gadgetzan avec 1 Convertisseur d’arcanite délicat, 4 Essences éternelles supérieures, 10 Huiles de pierre-écaille, 25 Cendres volcaniques et 40 pièces d’or.", description = "Hum, vous allez avoir besoin de mon dernier projet… le révélateur de fantômes extradimensionnel ! Malheureusement je me suis retrouvé à cours de fonds et de personnel.\n\nVous dites que vous êtes <prêt/prête> à aider ? Très bien ! Notre première besogne sera de construire un engin capable de récolter l’essence même des morts ! Fabriquer un Alambic ectoplasmique ne sera pas une tâche facile, <nom>.\n\nJe vais avoir besoin de vous pour m’apporter un convertisseur d’arcanite, de l’essence éternelle supérieure et de l’huile de pierre-écaille. Il me faudra aussi des cendres volcaniques prélevées dans les mares de lave des Steppes ardentes pour faire un filtre.", progress = "Je sais que tout cela coûte un peu cher… mais je vous garantis que nous allons avoir besoin de tout !", completion = "C’est exactement ce qu’il me fallait. Et pile au bon moment, en plus, &lt;nom&gt; !\n\nVotre alambic sera prêt en un rien de temps ! En attendant, prenez ça, avec mes remerciements pour votre aide.", rewards = "Vous recevrez :\n\nMarchandises premier choix de Mux"},
[8922] = {title = "Un objet surnaturel", objective = "Remettre le Récipient de sang scellé à Mux Manascrambler, à Gadgetzan en Tanaris.", description = "Je dois trouver un moyen de parler à Anthion Harmon… enfin, avec son fantôme !\n\nJe connais un ingénieur qui, bizarrement, s’intéresse au surnaturel. Il prétend être capable de construire une machine qui permettrait de parler avec les morts !\n\nLe sang que vous avez récolté est pour lui. Rendez-vous à Gadgetzan et donnez-le lui pour payer ses services !", progress = "Vous avez quelque chose pour moi ?", completion = "Formidable ! J’étais justement sur le point d’en manquer !\n\nVous dites que c’est Deliana qui vous envoie ?", rewards = "Vous recevrez :\n\n"},
[8923] = {title = "Un objet surnaturel", objective = "Remettez le Récipient de venin scellé à Mux Manascrambler, à Gadgetzan.", description = "Vous devez être très brave pour être <resté/restée> dans les parages depuis. Ou alors, cette pièce d'armure a piqué votre intérêt. J'en ai d'autres, si vous acceptez de me donner un coup de main.\n\nLes échantillons de venin que vous avez récoltés sont pour l’une de mes connaissances, un ingénieur nommé Mux Manascrambler. Il s’intéresse au surnaturel, et travaille sur un appareil qui permet de communiquer avec les morts ! Je n’ai plus qu’un espoir : contacter Anthion et en apprendre plus sur ma situation.", progress = "Vous souhaitez me parler ?", completion = "Formidable ! J’étais justement sur le point d’en manquer !\n\nVous dites que c’est Mokvar qui vous envoie ?", rewards = "Vous recevrez :\n\n"},
[8924] = {title = "La chasse aux ectoplasmes", objective = "Utilisez l’Alambic ectoplasmique à proximité de morts-vivants désincarnés pour recueillir 12 Ectoplasmes brûlés en Silithus, 12 Ectoplasmes glacés au Berceau-de-l’hiver et 12 Ectoplasmes stables dans les Maleterres de l’est. Remettez à Mux Manascrambler à Gadgetzan. Il veut aussi récupérer l'Alambic ectoplasmique.", description = "Un petit bijou d’ingénierie, et je ne dis pas ça parce que c’est moi qui l’ait construit ! Hum… J’ai bien peur que vous ne soyez <obligé/obligée> de voyager un peu pour trouver les morts-vivants désincarnés dont nous avons besoin.\n\nEn fait, les différences climatiques influent sur la consistance de la trame spectrale des morts. Les elfes de la nuit torturés de Silithus, les esprits des bien-nés de Berceau de l’Hiver et les fantômes et les banshees des Maleterres de l’est devraient nous fournir les différents types d’ectoplasmes dont nous avons besoin. Pensez à placer l’alambic à proximité avant de faire la récolte !", progress = "Avez-vous récolté les ectoplasmes, <race> ?", completion = "Oui, ils conviendront à merveille !\n\nEn captant les énergies de l’autre monde que contiennent ces substances, nous allons pouvoir prendre contact avec ceux dont les âmes n’ont pas encore tout à fait quitté le nôtre !", rewards = "Vous recevrez :\n\n"},
[8925] = {title = "Une source d’énergie portable", objective = "Trouvez le Seigneur-magma Bokk dans les Steppes ardentes, prenez son Coeur de magma et rapportez-le à Mux Manascrambler, à Gadgetzan.", description = "Il nous faut maintenant une source d’énergie portable et stable pour que les ectoplasmes restent actifs. J’ai entendu parler d’un élémentaire redoutable appelé le seigneur-magma Bokk, dont le cœur est un puissant noyau de magma : une source de chaleur inépuisable !\n\nIl paraît qu’il sévit quelque part dans les steppes ardentes, au sud du mont Blackrock. Apportez-moi son cœur de magma et nous aurons assez d’énergie pour alimenter le révélateur de fantômes extradimensionnel !", progress = "Alors, avez-vous trouvé le seigneur-magma, <nom> ?", completion = "Vous en êtes venu à bout ! Il va très certainement nous fournir assez d’énergie pour alimenter le révélateur de fantômes extradimensionnel !", rewards = "Vous recevrez :\n\n"},
[8926] = {title = "Une juste compensation", objective = "Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Deliana à Ironforge.", description = "Vous avez tenu parole et ramené l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Ramenez-moi la ceinture et la paire de gants que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture Cœur-FaroucheGants Cœur-Farouche"},
[8927] = {title = "Une juste compensation", objective = "Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture Cœur-FaroucheGants Cœur-Farouche"},
[8928] = {title = "Un marchand à éclipses", objective = "Trouvez un diablotin qui vivrait dans une caverne à l'entrée de la gorge du Sombre murmure, au sud du Berceau-de-l'hiver. Achetez-lui un Bâtonnet élémentaire de corruption, puis retournez voir Mux Manascrambler à Gadgetzan.", description = "Le cœur nous donnera assez de jus pour alimenter notre appareil. Maintenant, il nous faut fabriquer un bâtonnet qui permette de canaliser cette énergie sans fondre. J’ai rencontré un diablotin au Berceau-de-l’Hiver qui vendait une multitude de marchandises exotiques. Il possédait notamment un bâtonnet élémentaire qui conviendrait parfaitement. Je n’ai pas pensé à l’acheter sur le moment… je me donnerai des claques !\n\nIl vit dans une caverne à l'entrée de la gorge du Sombre murmure. Essayez de le retrouver.\n\nOh, il m'avait annoncé un prix. Quarante pièces d'or. Ne le laissez pas vous demander plus !", progress = "Êtes-vous parvenu à mettre la main sur le diablotin de la gorge du Sombre murmure ?", completion = "Vous y êtes arrivé ! Ce bâtonnet fera parfaitement l’affaire ! Maintenant, assemblons le tout…", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8929] = {title = "À la recherche d'Anthion", objective = "Utilisez le Révélateur de fantômes extradimensionnel à l’entrée de Stratholme et parlez au fantôme d’Anthion Harmon.\n\nObjet fourni : \n", description = "Hé bien, il ne nous reste plus qu’à tester l’invention du gobelin. J’ai entendu dire qu’Anthion s’était fait massacrer par les légions de morts-vivants de Stratholme lorsqu’il a tenté d’y pénétrer.\n\nEssayez d’utiliser l’objet là-bas et de découvrir ce que savait Anthion.", progress = nil, completion = "Deliana vous a demandé de me contacter ? Je ferai de mon mieux pour vous aider, mais je vais d'abord vous demander de me rendre un grand service.", rewards = "Vous recevrez :\n\n"},
[8930] = {title = "À la recherche d'Anthion", objective = "Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme, et parlez au fantôme d'Anthion Harmon.\n\nObjet fourni : \n", description = "Très bien, <nom>. Nous n’avons plus qu’à tester l’invention du gobelin. J’ai entendu dire qu’Anthion avait tenté de pénétrer dans Stratholme. Il n’a même pas franchi les portes, les légions des morts-vivants l’ont tué avant.\n\nEssayez d’utiliser l’objet là-bas et voyez si vous pouvez effectivement voir les morts !", progress = nil, completion = "Mokvar vous a demandé de me contacter ?  Je ferai de mon mieux pour vous aider, mais je dois d'abord vous demander une grande faveur.", rewards = "Vous recevrez :\n\n"},
[8931] = {title = "Une juste compensation", objective = "Apportez une Ceinture de bestiaire et une paire de Gants de bestiaire à Deliana à Ironforge.", description = "Vous avez tenu parole et ramené l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Ramenez-moi la ceinture et la paire de gants que vous souhaitez améliorer.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture de belluaireGants de belluaire"},
[8932] = {title = "Une juste compensation", objective = "Apportez une Ceinture de magistère et une paire de Gants de magistère à Deliana à Ironforge.", description = "Vous avez tenu parole et ramené l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Ramenez-moi la ceinture et la paire de gants que vous souhaitez améliorer.", progress = "Êtes-vous prêt à honorer notre marché ?", completion = "Vous avez respecté votre part du marché, je respecterai la mienne.\n\nSouvenez-vous quand même que je garde les meilleures pièces tant que vous n’avez pas terminé votre tâche.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture du sorcierGants du sorcier"},
[8933] = {title = "Une juste compensation", objective = "Apportez une Ceinture de Sancteforge et une paire de Gantelets de Sancteforge à Deliana à Ironforge.", description = "Vous avez tenu parole et ramené l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Ramenez-moi la ceinture et la paire de gantelets que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture d'ÂmeforgeGantelets d'Âmeforge"},
