[8937] = {title = "Une juste compensation", objective = "Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Deliana à Ironforge.", description = "Vous avez tenu parole et ramené l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gantelets que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture d'héroïsmeGantelets d'héroïsme"},
[8938] = {title = "Une juste compensation", objective = "Apportez une Ceinture de bestiaire et une paire de Gants de bestiaire à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.", progress = "Êtes-vous prêt à faire l’échange ?", completion = "Notre accord tient toujours. Souvenez-vous, ce n’est qu'un avant-goût de ce qui vous attend. Si vous m’aidez à échapper à mon destin, je vous remettrai des objets réellement puissants.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture de belluaireGants de belluaire"},
[8939] = {title = "Une juste compensation", objective = "Apportez une Ceinture de magistère et une paire de Gants de magistère à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture du sorcierGants du sorcier"},
