[8942] = {title = "Une juste compensation", objective = "Apportez une Corde des éléments et une paire de Gantelets des éléments à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gantelets. Si nous survivons tous les deux, je vous remettrai les autres pièces.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCorde des Cinq tonnerresGantelets des cinq tonnerres"},
[8943] = {title = "Une juste compensation", objective = "Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture MortebrumeProtège-mains Mortebrume"},
[8944] = {title = "Une juste compensation", objective = "Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Mokvar à Orgrimmar.", description = "Vous avez fait la preuve de votre fiabilité, <nom>. Je suis sûr que vous m’aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.\n\nPour le moment, je me contenterai de remplacer votre ceinture et vos gantelets. Si nous survivons tous les deux, je vous remettrai les autres pièces.", progress = "Êtes-vous prêt à faire l’échange ?", completion = "Notre accord tient toujours. Souvenez-vous, ce n’est qu'un avant-goût de ce qui vous attend. Si vous m’aidez à échapper à mon destin, je vous remettrai des objets réellement puissants.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture d'héroïsmeGantelets d'héroïsme"},
[8945] = {title = "La supplique du mort", objective = "Entrez à Stratholme et sauvez Ysida Harmon du baron Rivendare.", description = "Vous aurez vos informations, <nom>, mais il y a plus important.\n\nMon épouse bien-aimée a été capturée par la vermine morte-vivante du baron Rivendare.\n\nJe ne voulais pas qu’elle rejoigne l’absurde croisade de l’Aube d’argent, mais cela n’a plus d’importance. Vous devez achever ce que j’ai commencé, vous devez arracher Ysida aux griffes du baron !", progress = nil, completion = "Merci de m’avoir sauvée… J’ai bien cru que j’allais mourir. Prenez ceci, en gage de reconnaissance.\n\nAnthion est… non… ce n’est pas possible.", rewards = "Vous allez être la cible du sort suivant :\n\nAugmenter la réputation\n\nVous recevrez :\n\nSacoche d'Ysida"},
[8946] = {title = "Une preuve de vie", objective = "Remettre le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’est.", description = "Un destin cruel a voulu que mon bien-aimé périsse en tentant de me sauver. Pourtant, vous me dites que vous pouvez lui parler.\n\nRemettez-lui ce médaillon pour lui prouver que je suis en bonne santé. Il ne doit pas s’attarder dans ce monde, cela me briserait le cœur.\n\nAdieu, <nom>. Je serai toujours votre débitrice.", progress = "Ysida… est-elle en vie ?", completion = "Ce médaillon… vous l’avez trouvée ! Je peux enfin reposer en paix.\n\nJe vais répondre à vos questions, &lt;nom&gt;. Mais dépêchez-vous, car je ne resterai pas longtemps en ce monde.", rewards = "Vous recevrez :\n\n"},
[8947] = {title = "L'étonnante requête d'Anthion", objective = "Remettre 3 Barres de sombre fer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l’est.", description = "Nous n’avons pas réalisé l’importance du médaillon de Valthalak. Nous l’avons donc partagé comme le reste des dépouilles. Le premier morceau a été pris par un nain, un certain Theldren. Lorsque j’ai essayé de le lui reprendre, il bien failli me tuer. Vous devrez récupérer ce fragment par la force.\n\nAux dernières nouvelles, Theldren s'était fait gladiateur chez les nains Sombrefer. Vous risquez d’avoir un peu de mal à le pousser à vous affronter.\n\nJe vais avoir besoin des matériaux suivants… En fait, non, vous allez en avoir besoin.", progress = "Avez-vous les matériaux dont j’ai besoin, <nom> ?", completion = "Excellent. Je vais les transmuter en quelque chose de plus adapté à nos besoins.", rewards = "Vous recevrez :\n\n"},
[8948] = {title = "Le vieil ami d'Anthion", objective = "Apportez la Bannière de défi incomplète à Farlin Treeshaper, dans la bibliothèque de Hache-tripes.", description = "Theldren n’est pas du genre à participer de son plein gré à un combat honnête. J’ai donc fabriqué cette bannière aux couleurs de sa famille.\n\nMoyennant une petite touche de magie supplémentaire, il sera incapable de résister à cette provocation.\n\nFalrin, l’une de mes vieilles connaissances, connaît la marche à suivre. Vous le trouverez dans la bibliothèque de Hache-tripes.", progress = "Eh bien, parlez, étranger. Vous ne voyez pas que je suis occupé ?", completion = "Vous dites qu'Anthion vous envoie ?  Je pensais qu'il était mort.  Bon, je suppose que j'ai déjà entendu des choses plus étranges dans ma vie.\n\nTrès bien, que voulez-vous que je fasse avec cette bannière ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8949] = {title = "La vendetta de Falrin", objective = "Collecter 25 Perles de guerre ogres à l’intérieur de Hache-tripes ou du Pic Blackrock, puis revenir voir Falrin Treeshaper, à l'intérieur de l'Athenaeum à Hache-tripes.", description = "En effet, je connais l’enchantement dont vous avez besoin, <classe>. Mais je ne suis pas de ceux qui distribuent des faveurs gratuitement, même si vous m’avez été <envoyé/envoyée> par un vieil ami.\n\nJe hais mes voisins ogres, ces brutes méprisables. J’exècre les séides d’Omokk autant que les sujets du roi Gordok.\n\nTuez-les ! Tuez-en beaucoup ! Ramenez-moi les perles qu’ils portent autour du cou comme preuve de vos actions. Lorsque vous m’en aurez rapporté assez, nous reparlerons de votre requête.", progress = "Je vous avais demandé une faveur, <nom>. Avez-vous terminé ?", completion = "Hmmm… curieusement, cela n’efface pas la mort de mon frère, qui a été tué par ces brutes.\n\nBref… vous avez rempli votre part du marché. Voyons ce que je peux faire pour vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPerles de puissance ogrePerles de mojo ogre\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8950] = {title = "L'enchantement du provocateur", objective = "Apportez les choses suivantes à Falrin Treeshaper dans Hache-tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants.", description = "Enchanter la bannière ne sera pas bien compliqué, <nom>. Malheureusement, je n’ai pas les matériaux nécessaires. Entre nous, les gens demandent rarement des charmes de ce genre.\n\nIl va me falloir l’essence de l’un des fantômes d’Eldreth qui hantent ces salles, une poignée de runes ténébreuses de la Scholomance et quelques grands éclats brillants. Ramenez-moi ces composants, je m’occuperai du reste.", progress = "Avez-vous les matériaux dont j’ai besoin, <nom> ?", completion = "Oui, ils feront parfaitement l’affaire. Lorsque j’en aurai terminé, aucune force au monde ne pourra empêcher votre victime de relever votre défi.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8951] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes Cœur-FaroucheKilt Cœur-FaroucheSpallières Cœur-Farouche"},
[8952] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes de belluairePantalon de belluaireMantelet de belluaire"},
[8953] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes du sorcierJambières du sorcierMantelet du sorcier"},
