[8955] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Sandales de dévot, un Pantalon de dévot et un Mantelet de dévot.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSandales vertueusesJupe vertueuseMantelet vertueux"},
[8956] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !", progress = "Vous revoilà, <nom>. Vous allez tout me raconter. Mais commençons par parler de votre récompense.", completion = "Je n’arrive pas à croire que nous soyons condamnés à mort à cause d’un médaillon ridicule ! Êtes-vous sûr qu’Anthion a parlé de Bodley ?\n\nBref… vous avez fait votre travail, parlons donc de votre récompense.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes SombremantePantalon SombremanteSpallières Sombremante"},
[8957] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Bottes des éléments, un Kilt des éléments et des Espauliers des éléments.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes des Cinq tonnerresKilt des Cinq tonnerresEspauliers des Cinq tonnerres"},
[8958] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSandales MortebrumeJambières MortebrumeMantelet Mortebrume"},
[8959] = {title = "Les adieux d'Anthion", objective = "Retournez voir Deliana à Ironforge avec des Bottes de vaillance, des Jambières de vaillance et des Spallières de vaillance.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes d'héroïsmeCuissards d'héroïsmeSpallières d'héroïsme"},
[8960] = {title = "Le triste destin de Bodley", objective = "Rendez-vous au mont Blackrock, près du pic Blackrock, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.", description = "Alors il faut que nous récupérions le reste du médaillon ? Trouver Bodley risque d’être un tantinet compliqué. Il est retourné au mont Blackrock dans l’espoir de pénétrer dans le pic Blackrock, et il n’est jamais revenu.\n\nJe crains le pire… Un conseil, prenez la machine gobeline à faire apparaître les fantômes avec vous.", progress = nil, completion = "Je suis heureux que vous puissiez me voir. J’ai enfin quelqu’un à qui parler ! Accepteriez-vous de nous aider, &lt;nom&gt; ? Nous avons commis une faute terrible, et nous avons besoin de quelqu’un pour l’effacer. Si vous avez vraiment le morceau supérieur de l’amulette du seigneur Valthalak, je pense que je peux vous indiquer où trouver les deux autres. Lorsqu’ils seront réunis, vous pourrez mettre un terme à tout cela.\n\nAh, j’oubliais… Bonjour, je m’appelle Bodley. Un plaisir de vous rencontrer.", rewards = "Vous recevrez :\n\n"},
[8961] = {title = "Les trois rois des flammes", objective = "Récupérez l’Incendicite d’Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu'un Brasero béni, puis retournez voir Bodley au mont Blackrock.", description = "Avant d’invoquer le seigneur Valthalak au pic Blackrock et de mettre un terme à ce problème, nous devons retrouver les deux autres tiers de l’amulette. Pour cela, il nous faut un brasero et des charbons peu ordinaires…\n\nTrois puissants nobles élémentaires ont ce qu’il nous faut. Ce sont le seigneur Incendius dans les profondeurs de Blackrock, le pyrogarde Prophète ardent au pic Blackrock et le duc des Cendres en Silithus. Récupérez un morceau de leurs restes, puis revenez me voir avec un Brasero béni, que vous pourrez acheter auprès de l’Aube d’argent si vous êtes <honoré/honorée> auprès d’eux.", progress = "Ce dernier boulot était une folie qui a scellé notre destin. Si seulement nous n’avions pas volé un morceau de l’esprit du seigneur Valthalak en même temps que l’amulette ! Nous ne savions pas qu'elle contenait son esprit ! Et si nous n’avions pas été cupides, nous ne nous serions pas partagés l’amulette… Je pourrais être en vie aujourd’hui. Je serais peut-être en train de boire une bière ou de jouer avec mes enfants.\n\n<nom>, prenez garde à ce que la convoitise de notre ancienne compagnie de mercenaires ne vous condamne pas à mort vous aussi.", completion = "Je suis impressionné, &lt;classe&gt;, mais nous n’avons pas de temps à perdre. Je vous expliquerai bientôt votre prochaine tâche. Il faut encore que nous nous procurions quelques composants importants avant d’entrer dans le vif du sujet.\n\nLorsque vous vous sentirez prêt pour les défis qui nous attendent, revenez me parler.", rewards = "Vous recevrez :\n\n"},
[8962] = {title = "Des composants importants", objective = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Maintenant que nous avons le brasero et le moyen de l’allumer, il ne nous manque plus qu’un composant pour l’alimenter ; quelque chose qui soit assez puissant pour attirer l’esprit de mon ancien camarade décédé.\n\nMor Grayhoof, notre meilleur druide, avait d’excellents amis au sein du Cercle cénarien, dont certains sont tombés sous les coups des silithides. J’ai besoin que vous récupériez des restes druidiques auprès des silithides qui vivent dans les environs de la Ruche’Regal, au sud-est de Silithus.", progress = "Êtes-vous déjà de retour avec ce dont j’ai besoin, <classe> ?", completion = "Du bon travail, &lt;nom&gt;. Je vais imprégner le brasero de l’essence des restes.\n\nVous aurez juste à descendre dans les profondeurs du pic Blackrock, jusqu’aux appartements du maître de guerre Voone à Tazz'Alaor, puis à utiliser le brasero pour invoquer l’esprit corrompu de mon ancien associé, Mor Grayhoof. Il ne connaîtra pas le repos tant que vous ne lui aurez pas repris le morceau d’amulette.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8963] = {title = "Des composants importants", objective = "Procurez-vous une Relique de Brise-stellaire et rapportez-la à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Maintenant que nous avons le brasero et le moyen de l’allumer, il ne nous manque plus qu’un composant pour l’alimenter ; quelque chose qui soit assez puissant pour attirer l’esprit de mon ancienne camarade décédée.\n\nIsalien, notre prêtresse, a grandi au Berceau-de-l’Hiver, à Brise-stellaire. J’ai besoin que vous alliez chercher une relique de Brise-stellaire auprès des géants Cognegivre de la gorge du Blanc murmure, au sud de Berceau-de-l’Hiver. Ils sont célèbres pour les raids qu’ils lancent de temps en temps dans le nord.", progress = "Êtes-vous déjà de retour avec ce dont j’ai besoin, <classe> ?", completion = "Du bon travail, &lt;nom&gt;. Je vais imprégner le brasero de l’essence de la relique.\n\nIl ne vous restera plus qu’à aller au sanctuaire d’Eldretharr, dans l’aile est de Hache-tripes, et à utiliser le brasero pour invoquer l’esprit de mon ancienne associée, Isalien. Le morceau de l’amulette, et surtout la portion d’âme du seigneur Valthalak qu’il renferme, ont corrompu son esprit.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8964] = {title = "Des composants importants", objective = "Procurez-vous une Epée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Maintenant que nous avons le brasero et le moyen de l’allumer, il ne nous manque plus qu’un composant pour l’alimenter ; quelque chose qui nous fournisse un point focal assez puissant pour attirer l’esprit de mes anciens camarades décédés.\n\nJarien et Sothos croyaient aux idéaux de la Croisade écarlate. Ils souhaitaient devenir chevaliers au sein de cette vile organisation. Rendez-vous à la Main de Tyr, dans les Maleterres de l’est, et récupérez une Epée brillante de fanatisme sur les prétoriens qui y sont cantonnés.", progress = "Êtes-vous déjà de retour avec ce dont j’ai besoin, <classe> ?", completion = "Du bon travail, &lt;nom&gt;. Je vais imprégner le brasero avec l’essence de l’épée.\n\nIl ne vous restera plus qu’à aller devant le trône cramoisi, à l’intérieur du Bastion écarlate de Stratholme, et à y utiliser le brasero pour faire apparaître mes anciens associés, Jarien et Sothos. Leurs âmes ont été encore plus perverties par le morceau de l’amulette et l’esprit qu’il contient.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8965] = {title = "Des composants importants", objective = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Maintenant que nous avons le brasero et le moyen de l’allumer, il ne nous manque plus qu’un composant pour l’alimenter ; quelque chose qui soit assez puissant pour attirer l’esprit de mon ancien camarade décédé.\n\nUn nécromancien ogre qui voyageait avec nous, Kormok, adorait invoquer les âmes des morts bannis sur l’Île de la purification, près de la côté méridionale des contreforts d’Hillsbrad. Rendez-vous là-bas et récupérez un peu de cendres d'âme de banni sur leurs restes…Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8966] = {title = "Le morceau gauche de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Grayhoof, puis tuez-le. Ensuite, retournez voir Bodley à l'intérieur du mont Blackrock avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.", description = "Mon ami, Mor Grayhoof, a été le premier à être possédé par un morceau de l’amulette du seigneur Valthalak, la première victime du fragment d’esprit corrupteur qu’elle renferme. Après avoir dérobé l’amulette et le livre de sorts du seigneur Valthalak, nous avons fui le sommet du pic Blackrock pour sauver nos vies. Mor s’est égaré et est tombé dans les profondeurs du pic.\n\nPar la suite, nous avons découvert qu’il avait survécu à sa chute, mais qu’il avait été capturé et torturé par le maître de guerre Voone. Quelques assassins spectraux se sont faufilés dans les profondeurs et l’ont tué sous les yeux de Voone.", progress = "Est-ce fait ? Avez-vous retrouvé le Morceau gauche de l’amulette du seigneur Valthalak et apporté le repos à l’esprit de mon vieux compagnon, Mor Grayhoof ?", completion = "Vous avez accompli un grand exploit, &lt;nom&gt;. Un esprit repose en paix, mais il nous reste beaucoup à faire avant que nous ne puissions oublier tout cela.\n\nMalheureusement, je ne sais pas où se trouvait le possesseur du morceau droit de l’amulette lorsqu’il est mort. Mais n’ayez pas peur. De mon vivant, je m’intéressais à la divination. J’ai une autre tâche pour vous, qui nous permettra de découvrir où se trouve le dernier morceau.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8967] = {title = "Le morceau gauche de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.", description = "Sur la fin, alors que nous faisions notre possible pour rester en vie, nous avons appris que la prêtresse elfe de la nuit de notre compagnie, Isalien, s’était rendue dans une antique cité de son peuple, la ville que nous connaissons sous le nom de « Hache-tripes ». D’après ce que nous avons compris, elle avait des raisons personnelles pour s’y installer, mais elle voulait aussi découvrir les secrets du morceau d’amulette qu’elle détenait.\n\nElle n’y est pas parvenue. Nous avons entendu dire qu’elle avait été victime d’une embuscade tendue par Alzzin le Modeleur et ses forces au sanctuaire d’Eldretharr.", progress = "Vous n’avez sans doute pas encore eu le temps de sauver l’esprit d’Isalien et de récupérer le Morceau gauche de l’amulette du seigneur Valthalak, <nom>. Si ?", completion = "Merci d’avoir apporté le repos à l’âme d’Isalien, &lt;nom&gt;. Elle trouvera peut-être la paix auprès de sa déesse. Mais il nous reste encore énormément à faire pour nous extraire du bourbier dans lequel nous nous débattons.\n\nMalheureusement, je ne sais pas où se trouvait le possesseur du morceau droit de l’amulette lorsqu’il est mort. Mais n’ayez pas peur. De mon vivant, je m’intéressais à la divination. J’ai une autre tâche pour vous, qui nous permettra de découvrir où se trouve le dernier morceau.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8968] = {title = "Le morceau gauche de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.", description = "Lorsque notre compagnie de mercenaires a éclaté, Sothos et Jarien, un frère et une sœur, ont decidé de rejoindre la Croisade écarlate. Ils ont emmené le Morceau gauche de l’amulette du seigneur Valthalak avec eux. C’était plutôt un bon débarras… sauf qu’il nous faut ce morceau.\n\nÀ ce que j’ai compris, ils ont échoué lors de leur initiation, et ont été tués par le Grand croisé Dathrohan en personne dans ses appartements du Bastion écarlate.\n\nQue ce soit vrai ou non, nous devons… je veux dire, vous devez, récupérer ce morceau d’amulette.", progress = "Cela veut-il dire que vous avez déjà procuré le repos aux âmes de ces deux imbéciles et récupéré le Morceau gauche de l’amulette du seigneur Valthalak, <classe> ?", completion = "Je ne pouvais pas les sentir de leur vivant, mais je suppose que ce n’est pas plus mal que les âmes de ces deux-là reposent en paix. Quoi qu’il en soit, nous avons ce que nous cherchions, et c’est indiscutablement une bonne chose !\n\nMalheureusement, je ne sais pas où se trouvait le possesseur du morceau droit de l’amulette lorsqu’il est mort. Mais n’ayez pas peur. De mon vivant, je m’intéressais à la divination. J’ai une autre tâche pour vous, qui nous permettra de découvrir où se trouve le dernier morceau.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8969] = {title = "Le morceau gauche de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.", description = "Maintenant que nous avons tout ce qu’il nous faut, il est temps que nous parlions de notre prochaine invocation.\n\nPour un ogre, Kormok n’était pas désagréable, jusqu’à ce qu’il se mette à la nécromancie. Après… après, il donnait la chair de poule à tous les membres de la compagnie. Personne n’a été étonné qu’il emmène son morceau d’amulette dans son nouveau foyer, la Scholomance. Même là, ou peut-être « surtout là », il n’était pas à l’abri des assassins spectraux. Ils l’ont tué devant son maître, Ras Murmegivre.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8970] = {title = "Votre avenir passe par l'île d'Alcaz", objective = "Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Blackrock.", description = "Comme je vous le disais, <classe>, de mon vivant, j’avais envisagé la possibilité de devenir devin. Mais comme vous le savez peut-être, ça n’est pas un métier très rentable. Non seulement c’est dangereux, mais en plus les composants sont à la fois rares et coûteux. Toutefois, j’en ai appris assez pour localiser le dernier morceau de l’amulette, ainsi que l’esprit de mon ancien camarade.\n\nC’est là que vous intervenez, <nom>. J’ai besoin que vous alliez sur l’île d’Alcaz, au large du marécage d’Âprefange, et que vous récupériez du varech de sang sur les nagas Strashaz qui y vivent.", progress = "Il me faut du varech de sang, <nom>. Une grande quantité. C'est indispensable pour alimenter mes sorts de divination. Je vous conseille de prendre au moins deux amis avec vous pour la récolte. Ces Strashaz sont peu commodes !", completion = "Entre nous, je suis surpris de vous voir revenir en un seul morceau, &lt;nom&gt;. Mais bon, en ce moment, l’île d’Alcaz est le cadet de nos soucis.\n\nDonnez-moi un moment… La divination n’est pas quelque chose d’instantané. Il ne suffit pas de se concentrer et de claquer des doigts pour avoir une réponse.", rewards = "Vous allez être la cible du sort suivant :\n\nTranse divinatoire\n\nVous recevrez :\n\n"},
[8971] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux de Stormwind"},
[8972] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux d'Orgrimmar"},
[8973] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux de Darnassus"},
[8974] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux d'Undercity"},
[8975] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux de Thunder Bluff"},
[8976] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAssortiment de cadeaux d'Ironforge"},
[8977] = {title = "Retourner voir Deliana", objective = "Apportez le Révélateur de fantômes extradimensionnel à Deliana à Ironforge.", description = "Travailler avec vous était très agréable, <nom>. Voici le produit fini.\n\nJ’espère qu’il vous rendra service dans vos activités présentes. Oh… Et si cela ne vous dérange pas trop, parlez de moi autour de vous. J’aimerais bien avoir davantage de clients.", progress = "Vous êtes de retour ?", completion = "Excellent ! C'est du bon travail, &lt;nom&gt;. Je n'ai pas complètement confiance dans les talents du gobelin, mais je n'ai pas le choix…", rewards = "Vous recevrez :\n\n"},
[8978] = {title = "Retourner voir Mokvar", objective = "Retournez voir Mokvar à Orgrimmar avec le Révélateur de fantômes extradimensionnel.", description = "Travailler avec vous était très agréable, <nom>. Voici le produit fini.\n\nJ’espère qu’il vous rendra service dans vos activités présentes. Oh… Et si cela ne vous dérange pas trop, parlez de moi autour de vous. J’aimerais bien avoir davantage de clients.", progress = "De retour avec l’appareil ?", completion = "Vous êtes de retour avec l’appareil ! Votre ténacité est impressionnante, &lt;nom&gt;. Excellent travail.", rewards = "Vous recevrez :\n\n"},
[8979] = {title = "L'intuition de Fenstad", objective = "Remettez 1 bouteille d’Eau de Cologne et 1 Flacon de parfum à l’apothicaire Zinge, dans l’Apothicarium d’Undercity.", description = "Je crois que je sais d’où provient cette conduite inadmissible. Avez-vous senti cette nouvelle odeur qui recouvre la puanteur des canaux ? Celle de ce parfum et de cette eau de Cologne qui sont à la mode depuis peu ?\n\nEn réalité, nos esprits sont embrumés par l’alchimie !\n\nIl n’y a qu’un moyen de s’en assurer : apportez un flacon de parfum et une bouteille d’eau de Cologne à mon amie l’apothicaire Zinge. La Société royale des apothicaires découvrira la vérité.\n\nBien sûr, à votre retour, je vous rembourserai vos achats.", progress = "En quoi puis-je vous servir ?", completion = "On dirait que Fenstad s’est trouvé une nouvelle obsession. Je suppose qu’il s’imagine que la Société royale des apothicaires n’a rien d’autre à faire qu’à l’aider dans ses ridicules enquêtes ?\n\nTrès bien, je vais lui rendre service une fois de plus.", rewards = nil},
[8980] = {title = "L'évaluation de Zinge", objective = "Retourner voir Fenstad Argyle, devant la banque d’Undercity.", description = "Voilà qui est inattendu. On dirait que Fenstad a bel et bien levé un lièvre. J’ai trouvé des quantités infimes de substances utilisées dans les potions de contrôle mental.\n\nDans les parfums, ce n’est pas complètement inhabituel, mais certaines de mes trouvailles… C’est de l’alchimie de haut niveau, digne d’un membre de la Société royale des apothicaires.", progress = nil, completion = "Ainsi, j’avais raison. Nous ne devons surtout pas perdre de temps. Nous devons déterminer l’origine de ces senteurs perverties.\n\nOh, tenez, voilà de quoi vous rembourser vos frais d’eau de Cologne et de parfum.", rewards = "Vous recevrez :\n\nBoîte de chocolatsPoignée de pétales de rose"},
[8981] = {title = "Faire des cadeaux", objective = "Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?", description = nil, progress = "Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?", completion = "Merveilleux ! Merveilleux ! Je vais le mettre avec tous les autres cadeaux !\n\nJe n’en espérais pas autant ! Vous devez vraiment beaucoup aimer vos chefs.\n\nMaintenant, j’ajoute un au décompte…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoignée de pétales de roseFlèche en argent\n\nVous allez être la cible du sort suivant :\n\nFête - Saint-Valentin, cadeau donné\n\nVous recevrez également :\n\nBoîte de chocolats"},
[8982] = {title = "Remonter à la source", objective = "Parler à l’aubergiste Norman d’Undercity.", description = "Nous devons trouver le fournisseur. L’apothicaire Katrina avait un flacon de parfum dans son sac. Elle m’a dit qu’elle l’avait acheté à Norman, l’aubergiste.", progress = nil, completion = "En effet, j’ai reçu récemment un stock de parfum et d’eau de Cologne. Je ne sais pas combien de temps je vais le garder, cela dit, parce que ces produits partent comme des petits pains.\n\nEntre nous, je ne vois pas bien pourquoi…", rewards = nil},
[8983] = {title = "Remonter à la source", objective = "Parlez à Mara Rennick, à la boutique du tailleur du quartier des mages d’Undercity.", description = "Un problème avec mes produits ? Vous plaisantez, tout le monde se précipite dessus, je n’ai jamais vu ça.\n\nJ’ai acheté mon stock auprès d’une marchande nommée Mara Rennick. Elle est nouvelle en ville.\n\nElle m’a dit qu’elle avait aussi une livraison à faire auprès du tailleur du quartier des mages.", progress = nil, completion = "Je suis désolée, mais j’ai tout vendu à Norman, l’aubergiste. Si vous voulez du parfum ou de l’eau de Cologne, allez le voir… tant qu’il lui en reste.\n\nÀ mon avis, cela ne durera pas. Vous verrez, cette eau de Cologne est irrésistible !", rewards = nil},
[8984] = {title = "La source est découverte !", objective = "Trouver l’apothicaire Staffron Lerent dans les contreforts d’Hillsbrad, au-delà du manoir de Ravenholdt.", description = "Écoutez, les faits et gestes d’un apothicaire renégat ne me concernent en rien. S’il nuit à notre cause, au contraire, je tiens à vous orienter dans la bonne direction.\n\nS’il est innocent, il n’a rien à cacher, n’est-ce pas ?\n\nJ’ai acheté ces marchandises à l’apothicaire Staffron Lerent. Il travaille dans un coin perdu des contreforts d’Hillsbrad, au-delà du manoir de Ravenholdt. Pour être honnête, je l’ai trouvé un peu bizarre…", progress = nil, completion = "Mais oui, j’ai conçu ces parfums. Ils sont merveilleux, n’est-ce pas ? Irrésistibles.\n\nLorsque les guerriers de l’Alliance et de la Horde seront tous abêtis par l’amour, ils seront incapables de s’opposer aux progrès du Conseil des ombres.\n\nIls seront pris au dépourvus, affaiblis, rongés d’angoisse à l’idée du sort qui menace ceux qu’ils aiment…\n\nC’était une idée si simple, je me demande pourquoi il m’a fallu aussi longtemps pour y penser. Le cœur est le point faible de tout un chacun. Et vous ne pouvez rien faire pour empêcher l’inévitable.", rewards = nil},
[8985] = {title = "D'autres composants importants", objective = "Procurez-vous une Relique de Brise-stellaire et rapportez-la à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Nous savons où se trouve le dernier morceau de l’amulette, mais il nous faut encore un composant que nous utiliserons pour imprégner le brasero, quelque chose qui nous fournisse un point focal assez puissant pour attirer l’esprit de mon ancienne associée.\n\nIsalien, notre prêtresse, a grandi au Berceau-de-l’hiver, dans le village de Brise-stellaire. J’ai besoin que vous récupériez une Relique de Brise-stellaire sur les géants Cognegivre de la gorge du Blanc murmure, dans le sud du Berceau-de-l’hiver. Ils font régulièrement des raids dans le nord.", progress = "Êtes-vous déjà de retour avec ce dont j’ai besoin, <classe> ?", completion = "Du bon travail, &lt;nom&gt;. Je vais imprégner le brasero de l’essence de la relique.\n\nIl ne vous restera plus qu’à aller au sanctuaire d’Eldretharr, dans l’aile est de Hache-tripes, et à utiliser le brasero pour invoquer l’esprit de mon ancienne associée, Isalien. Le morceau de l’amulette, et surtout la portion d’âme du seigneur Valthalak qu’il renferme, ont corrompu son esprit.\n\nOh, à propos, il me restait un peu du varech de sang que vous m’avez rapporté de l’île d’Alcaz. Je vous ai préparé quelques potions. Faites votre choix !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nElixir d'esquive de varech de sangElixir de résistance de varech de sang\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8986] = {title = "D'autres composants importants", objective = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Nous savons où se trouve le dernier morceau de l’amulette, mais il nous faut encore un composant que nous utiliserons pour imprégner le brasero, quelque chose qui nous fournisse un point focal assez puissant pour attirer l’esprit de mon ancien camarade.\n\nMor Grayhoof, notre meilleur druide, avait de nombreux amis dans le Cercle cénarien. Certains ont été dévorés par les silithides. Je vous demande de reprendre des Restes druidiques aux silithides qui vivent dans les environs de Ruche’Regal, dans le sud-est de Silithus.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nElixir d'esquive de varech de sangElixir de résistance de varech de sang\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8987] = {title = "D'autres composants importants", objective = "Procurez-vous une Epée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Maintenant que nous savons où se trouve le dernier morceau de l’amulette, il nous faut encore un composant que nous utiliserons pour imprégner le brasero, quelque chose qui nous fournisse un point focal assez puissant pour attirer l’esprit de mes anciens camarades.\n\nJarien et Sothos croyaient aux idéaux de la Croisade écarlate. Ils souhaitaient devenir chevaliers au sein de cette vile organisation. Rendez-vous à la Main de Tyr, dans les Maleterres de l’est, et récupérez une Epée brillante de fanatisme sur les prétoriens qui y sont cantonnés.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nElixir d'esquive de varech de sangElixir de résistance de varech de sang\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8988] = {title = "D'autres composants importants", objective = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Blackrock.", description = "Écoutez-moi attentivement, <classe>. Nous savons où se trouve le dernier morceau de l’amulette, mais il nous faut encore un composant que nous utiliserons pour imprégner le brasero, quelque chose qui nous fournisse un point focal assez puissant pour attirer l’esprit de mon ancien camarade.\n\nUn nécromancien ogre nommé Kormok voyageait avec nous. Il prenait beaucoup de plaisir à faire apparaître les âmes des morts bannis de l’île de la purification, au sud des contreforts d’Hillsbrad. Allez là-bas et récupérez des Cendres d'âme de banni sur leurs restes.", progress = "Êtes-vous déjà de retour avec ce dont j’ai besoin, <classe> ?", completion = "Du bon travail, &lt;nom&gt;. Je vais imprégner le brasero de l’essence des cendres.\n\nIl ne vous restera plus qu’à vous rendre à la Scholomance, dans les appartements de Ras Murmegivre, et à utiliser le brasero pour invoquer l’esprit de mon ancien associé, Kormok. Il était déjà corrompu, et son état a été aggravé par le morceau d’amulette et le fragment de l’esprit de Valthalak qu’il contient. Il faudra que vous le lui repreniez de force.\n\nOh, à propos, il me restait un peu du varech de sang que vous m’avez rapporté de l’île d’Alcaz. Je vous ai préparé quelques potions. Faites votre choix !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nElixir d'esquive de varech de sangElixir de résistance de varech de sang\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[8989] = {title = "Le morceau droit de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Grayhoof, puis tuez-le. Ensuite, retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.", description = "Mon ami, Mor Grayhoof, a été le premier à être possédé par un morceau de l’amulette du seigneur Valthalak, la première victime du fragment d’esprit corrupteur qu’elle renferme. Après avoir dérobé l’amulette et le livre de sorts du seigneur Valthalak, nous avons fui le sommet du pic Blackrock pour sauver nos vies. Mor s’est égaré et est tombé dans les profondeurs du pic.\n\nPar la suite, nous avons découvert qu’il avait survécu à sa chute, mais qu’il avait été capturé et torturé par le maître de guerre Voone. Quelques assassins spectraux se sont faufilés dans les profondeurs et l’ont tué sous les yeux de Voone.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8990] = {title = "Le morceau droit de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.", description = "Sur la fin, alors que nous faisions notre possible pour rester en vie, nous avons appris que la prêtresse elfe de la nuit de notre compagnie, Isalien, s’était rendue dans une antique cité de son peuple, la ville que nous connaissons sous le nom de « Hache-tripes ». D’après ce que nous avons compris, elle avait des raisons personnelles pour s’y installer, mais elle voulait aussi découvrir les secrets du morceau d’amulette qu’elle détenait.\n\nElle n’y est pas parvenue. Nous avons entendu dire qu’elle avait été victime d’une embuscade tendue par Alzzin le Modeleur et ses forces au sanctuaire d’Eldretharr.", progress = "Vous n’avez sans doute pas encore eu le temps de sauver l’esprit d’Isalien et de récupérer le Morceau droit de l’amulette du seigneur Valthalak, <nom>. Si ? N’oubliez pas de réassembler les morceaux de l’amulette avant de me la donner.", completion = "Merci d’avoir apporté le repos à l’âme d’Isalien, &lt;nom&gt;. Elle trouvera peut-être la paix auprès de sa déesse. Mais la tâche qui nous attend est la plus difficile de toutes.\n\nIl nous manque encore quelques objets pour que le brasero soit capable d’invoquer le seigneur Valthalak. Il va falloir que vous les récoltiez et que vous me les rameniez.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8991] = {title = "Le morceau droit de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos, puis tuez-les. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.", description = "Lorsque notre compagnie de mercenaires a éclaté, Sothos et Jarien, un frère et une sœur, ont decidé de rejoindre la Croisade écarlate. Ils ont emmené le Morceau gauche de l’amulette du seigneur Valthalak avec eux. C’était plutôt un bon débarras… sauf qu’il nous faut ce morceau.\n\nÀ ce que j’ai compris, ils ont échoué lors de leur initiation, et ont été tués par le Grand croisé Dathrohan en personne dans ses appartements du Bastion écarlate.\n\nQue ce soit vrai ou non, nous devons… je veux dire, vous devez, récupérer ce morceau d’amulette.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8992] = {title = "Le morceau droit de l'amulette du seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.", description = "Maintenant que nous avons tout ce qu’il nous faut, il est temps que nous parlions de notre prochaine invocation.\n\nPour un ogre, Kormok n’était pas désagréable, jusqu’à ce qu’il se mette à la nécromancie. Après… après, il donnait la chair de poule à tous les membres de la compagnie. Personne n’a été étonné qu’il emmène son morceau d’amulette dans son nouveau foyer, la Scholomance. Même là, ou peut-être « surtout là », il n’était pas à l’abri des assassins spectraux. Ils l’ont tué devant son maître, Ras Murmegivre.", progress = "Si vous êtes déjà de retour avec l’amulette entière, je vous félicite, <nom>. Si vous n’êtes pas encore parti, hâtez-vous ! Je vous assure que nous n’avons pas de temps à perdre !", completion = "Bien joué, &lt;nom&gt; ! De son vivant, Kormok n’était pas un mauvais bougre. J’espère qu’il jouira du repos qu’il mérite. Nous avons enfin l’amulette complète ! Mais le plus dur reste à faire.\n\nPour que le brasero soit capable d’invoquer le seigneur Valthalak, il reste quelques objets à rassembler et à me ramener.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[8993] = {title = "Faire des cadeaux", objective = "Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?", description = nil, progress = "Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?", completion = "Merveilleux ! Merveilleux ! Je vais le mettre avec tous les autres cadeaux !\n\nJe n’en espérais pas autant ! Vous devez vraiment beaucoup aimer vos chefs.\n\nMaintenant, j’ajoute un au décompte…", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPoignée de pétales de roseFlèche en argent\n\nVous allez être la cible du sort suivant :\n\nFête - Saint-Valentin, cadeau donné\n\nVous recevrez également :\n\nBoîte de chocolats"},
[8994] = {title = "Derniers préparatifs", objective = "Collectez 40 Brassards blackrock et un Flacon de pouvoir suprême. Ensuite, retournez voir Bodley au mont Blackrock.", description = "Nous sommes presque prêts, <classe>. Il ne nous reste plus qu’à récupérer quelques composants pour modifier le brasero et lui permettre de faire apparaître le seigneur Valthalak.\n\nPour commencer, je vous demande de vous rendre au pic Blackrock et d’y tuer des orcs. Ils portent des brassards qui contiennent de très faibles quantités du métal dont j’ai besoin. Pour que je puisse en extraire suffisamment, il va m’en falloir beaucoup. Ensuite, pour achever le processus d’imprégnation, il me faudra un Flacon de pouvoir suprême.\n\nBonne chance, <nom>.", progress = "Nous avons fait une longue route ensemble, <nom>, et je voulais vous dire que je vous remercie du fond du cœur, quoi qu'il arrive. Vous avez affronté de terribles dangers pour aider les survivants de la Lame voilée, notre compagnie de mercenaires. En ce qui me concerne, vous êtes désormais l’un des nôtres.", completion = "Nous y voilà. Je vais extraire le métal des brassards et imprégner le brasero avec ces derniers composants. Ensuite, il sera prêt à invoquer le seigneur Valthalak, et nous pourrons lui rendre l’amulette qui contient son esprit. Vous avez fait le plus gros, &lt;nom&gt;, ne lâchez pas prise maintenant que la fin est en vue !", rewards = "Vous recevrez :\n\n"},
[8995] = {title = "Mea culpa, seigneur Valthalak", objective = "Utilisez le Brasero de signal pour invoquer le seigneur Valthalak. Tuez-le, puis utilisez l’Amulette du seigneur Valthalak sur le corps. Ensuite, rendez l’amulette à l’Esprit du seigneur Valthalak.", description = "Tout est prêt, <nom>.\n\nLes appartements du seigneur Valthalak se trouvaient dans ce qui est devenu depuis la chambre de la Bête. Allez-y et servez-vous du Brasero de signal pour faire apparaître le seigneur Valthalak. Lorsqu’il redeviendra matériel, vous devrez le tuer une nouvelle fois. Si j’étais vous, je commencerais par m’occuper de la Bête, et je veillerais à emmener assez d’ami pour survivre aux dangers du sommet du pic Blackrock.\n\nLorsque vous aurez réglé son compte à Valthalak, utilisez l’amulette sur son cadavre. Lorsque son esprit sera réunifié, il voudra probablement la récupérer.\n\nBonne chance !", progress = "Vous osez troublez mon repos, <classe> !", completion = "Heureusement pour vous, je sais que vous n’êtes pas l’un de mes voleurs.\n\nÀ présent, je vais reprendre ce qui m’appartient, mortel ! Rendez-moi l’amulette !", rewards = "Vous recevrez :\n\n"},
[8996] = {title = "Retourner voir Bodley", objective = "Retournez voir Bodley à l'intérieur du mont Blackrock et donnez-lui le Brasero de signal.", description = "Je vais ignorer votre impertinence pour cette fois, <classe>, car en me rendant la part de mon esprit qui m’avait été dérobée, vous avez accompli quelque chose de noble. Malgré votre nature faible, <race>, vous avez fait preuve de courage, là où ceux qui m’ont volé en ont manqué. Le courage est certainement une notion qui les dépasse !\n\nRetournez les voir, avant que je ne change d’avis et que je ne vous abatte sur place. Allez, et dites-leur qu’ils sont en sécurité… pour l’instant.", progress = "Vous êtes de retour, <nom>, et toujours en vie ! Hé bien, cela fait au moins un survivant.\n\nIl va falloir que vous me racontiez ça !", completion = "Il a vraiment dit tout ça ? Je n’arrive pas à croire qu’il va rappeler ses assassins et ses traqueurs spectraux, même s’il a laissé entendre qu’il s’en prendrait de nouveau à mes compagnons survivants dans l’avenir.\n\nC’est un grand jour, &lt;nom&gt; ! Vous avez accompli un exploit remarquable et vous nous avez absous de nos anciens péchés – en partie, du moins.\n\nMerci ! En signe de gratitude, je vous donne ceci. Vous pourrez vous en servir pour invoquer des esprits dans les lieux hantés que vous connaissez déjà… et dans quelques autres.", rewards = "Vous recevrez :\n\nBrasero d'invocationMode d'emploi du brasero d'invocation"},
[8997] = {title = "Retour au commencement", objective = "Parlez à Deliana au Haut Siège d'Ironforge.", description = "Je suppose qu’il est temps de se dire au revoir, <mon ami/mon amie>. Si vous avez envie de revenir me voir pour bavarder, je serai toujours là. Je vous reverrai sans doute la prochaine fois que vous ne saurez pas trop quoi faire en attendant que vos amis vous rejoignent pour un raid sur le pic Blackrock.\n\nBon, allez-vous en avant que je ne me mette à pleurer. Retournez voir Deliana à Ironforge, et racontez-lui ce qui s’est passé.", progress = nil, completion = "Je suis heureuse de voir que vous revenez sans une égratignure, &lt;nom&gt;. Vous avez l’air en bonne forme, même si vous semblez quelque peu fatigué.\n\nVenez, racontez-moi ce qui s’est passé.", rewards = "Vous recevrez :\n\n"},
[8998] = {title = "Retour au commencement", objective = "Parlez à Mokvar au Fort Grommash, dans la Vallée de la Sagesse d'Orgrimmar.", description = "Je suppose qu’il est temps de se dire au revoir, <mon ami/mon amie>. Si vous avez envie de revenir me voir pour bavarder, je serai toujours là. Je vous reverrai sans doute la prochaine fois que vous ne saurez pas trop quoi faire en attendant que vos amis vous rejoignent pour un raid sur le pic Blackrock.\n\nBon, allez-vous en avant que je ne me mette à pleurer. Retournez voir Mokvar à Orgrimmar, et racontez-lui ce qui s’est passé.", progress = nil, completion = "C’est bon de voir que vous avez survécu, &lt;nom&gt;. Vous avez l’air en forme, et j’ai même l’impression que ces événements vous ont endurci.\n\nVenez, racontez-moi ce qui s’est passé.", rewards = "Vous recevrez :\n\n"},
[8999] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Coiffe du Coeur-sauvage et votre Gilet du Coeur-sauvage à Deliana.", description = "C’est une histoire stupéfiante, <nom> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude. Je dormirai peut-être mieux la nuit, maintenant.\n\nQuant à votre récompense… Je crois que j’ai quelques trucs qui devraient beaucoup vous plaire.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCapuche Cœur-FaroucheGilet Cœur-Farouche"},
[9000] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Coiffe de bestiaire et votre Tunique de bestiaire à Deliana.", description = "C’est une histoire stupéfiante, <nom> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude. Je dormirai peut-être mieux la nuit, maintenant.\n\nQuant à votre récompense… Je crois que j’ai quelques trucs qui devraient beaucoup vous plaire.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCoiffe de belluaireTunique de belluaire"},
[9001] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Collerette de magistère et votre Robe de magistère à Deliana.", description = "C’est une histoire stupéfiante, <nom> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude. Je dormirai peut-être mieux la nuit, maintenant.\n\nQuant à votre récompense… Je crois que j’ai quelques trucs qui devraient beaucoup vous plaire.", progress = "Êtes-vous prêt  à me donner comme convenu vos pièces d’armure de magistère en échange d’une Couronne et d’une Robe du sorcier ?", completion = "Vous allez me manquer, &lt;nom&gt;. J’ai une dette de gratitude envers vous. J’ai peur de ne jamais pouvoir vous la rembourser.\n\nJ’espère que vous apprécierez vos nouvelles protections de tête et de torse, et qu’elles vous protègeront pendant très longtemps.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCouronne du sorcierRobe du sorcier"},
[9002] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Casque de Sancteforge et votre Cuirasse de Sancteforge à Deliana.", description = "C’est une histoire stupéfiante, <nom> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude. Je dormirai peut-être mieux la nuit, maintenant.\n\nQuant à votre récompense… Je crois que j’ai quelques trucs qui devraient beaucoup vous plaire.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCasque d'ÂmeforgeCuirasse d'Âmeforge"},
