[9012] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Masque de Brume-funeste et votre Robe de Brume-funeste à Mokvar.", description = "Une histoire extraordinaire, <nom> ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.\n\nQuant à votre récompense, j’ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nMasque MortebrumeRobe Mortebrume"},
[9013] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Casque de vaillance et votre Cuirasse de vaillance à Mokvar.", description = "Une histoire extraordinaire, <nom> ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.\n\nQuant à votre récompense, j’ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.", progress = "Êtes-vous prêt à me donner vos pièces d’armure de vaillance en échange d’un Casque et d’une Cuirasse d’héroïsme ?", completion = "Vous allez vraiment me manquer, &lt;nom&gt;. J’ai une dette envers vous, une dette que je ne serais jamais en mesure de payer entièrement.\n\nJ’espère que vos nouvelles protections de la tête et du torse vous plairont, qu’elles vous feront un long usage et qu’elles vous permettront de gagner davantage d’honneur !", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCasque d'héroïsmeCuirasse d'héroïsme"},
[9014] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre Collerette de magistère et votre Robe de magistère à Mokvar.", description = "Une histoire extraordinaire, <nom> ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.\n\nQuant à votre récompense, j’ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCouronne du sorcierRobe du sorcier"},
[9015] = {title = "Le défi", objective = "Rendez-vous dans le Cercle de la loi, dans les profondeurs de Blackrock, et placez la Bannière de provocation en son centre lorsque vous serez <condamné/condamnée> par le Juge supérieur Grimstone. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’est avec le premier morceau de l’amulette du seigneur Valthalak.", description = "Écoutez-moi bien, <nom>. Si vous voulez que la bannière fonctionne comme vous le désirez, vous devez pénétrer dans le Cercle de la loi, dans les profondeurs de Blackrock. Laissez-vous condamner par le Juge supérieur Grimstone et plantez la bannière dans le sol de l’arène, en signe de défi.\n\nVotre victime sera incapable de se maîtriser, elle sera consumée par le désir de vous affronter. Lorsque vous aurez ce que vous voulez, retournez voir Anthion.", progress = "Vous êtes de retour, <nom> !", completion = "Avez-vous retrouvé un morceau du médaillon, &lt;nom&gt; ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[9016] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes Cœur-FaroucheKilt Cœur-FaroucheSpallières Cœur-Farouche"},
[9017] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !", progress = "Vous êtes de retour, <nom>, et je vois dans vos yeux que vous avez bien des choses à me dire. Mais occupons-nous d'abord de votre récompense.", completion = "Nous avons été maudits pour un simple médaillon. Ce seigneur Valthalak est vraiment, vraiment rancunier.\n\nNous allons essayer de trouver les morceaux manquants, si possible avant que je me fasse tuer. Mais d’abord, parlons de votre récompense.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes de belluairePantalon de belluaireMantelet de belluaire"},
[9018] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes du sorcierJambières du sorcierMantelet du sorcier"},
[9019] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Sandales de dévot, un Pantalon de dévot et un Mantelet de dévot.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSandales vertueusesJupe vertueuseMantelet vertueux"},
[9020] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes SombremantePantalon SombremanteSpallières Sombremante"},
[9021] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSandales MortebrumeJambières MortebrumeMantelet Mortebrume"},
[9022] = {title = "Les adieux d'Anthion", objective = "Retournez voir Mokvar à Orgrimmar avec des Bottes de vaillance, des Jambières de vaillance et des Spallières de vaillance.", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !", progress = "Vous êtes de retour, <nom>, et je vois dans vos yeux que vous avez bien des choses à me dire. Mais occupons-nous d'abord de votre récompense.", completion = "Nous avons été maudits pour un simple médaillon. Ce seigneur Valthalak est vraiment, vraiment rancunier.\n\nNous allons essayer de trouver les morceaux manquants, si possible avant que je me fasse tuer. Mais d’abord, parlons de votre récompense.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nBottes d'héroïsmeCuissards d'héroïsmeSpallières d'héroïsme"},
[9023] = {title = "Le poison parfait", objective = "Dirk Thunderwood, du Fort cénarien en Silithus, veut que vous lui rameniez la Glande à venin de Venoxis et la Glande à venin de Kurinaxx.", description = "Mon frère et moi nous occupons de tout ce qui concerne les poisons en dehors du manoir de Ravenholdt.\n\nLe seigneur Ravenholdt m’a chargé de mettre la main sur un nouveau poison composite qui peut être préparé à partir des glandes à venin des habitants de Zul’Gurub et des ruines d’Ahn’Qiraj.\n\nDeux des créatures qui hantent ces ruines maudites ont exactement ce qu’il nous faut, <classe>. Ramenez-moi les Glandes à venin de Kurinnaxx et de Venoxis, et ma reconnaissance éternelle vous sera acquise.", progress = "Ça ne va pas être une petite baston toute simple, <nom>. Amenez des copains.", completion = "Ravenholdt vous remercie, héros ! Faites votre choix !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nTrancheur de RavenholdtKriss de ShivsprocketLe tisonnier de ThunderwoodMortulus primeArbalète à répétition de FahradMarteau de culture de Simona\n\nVous recevrez également :\n\n"},
[9024] = {title = "L'intuition d'Aristan", objective = "Remettez 1 bouteille d’Eau de Cologne et 1 Flacon de parfum à Morgan Pestle, dans le Quartier commerçant de Stormwind.", description = "Vous sentez cette odeur ? C’est celle des parfums et de l’eau de Cologne qui sont à la mode ces temps-ci. Nos gardes ne négligeraient pas leur devoir aussi facilement.\n\nSauf si leur jugement a été obscurci par le biais d’une quelconque alchimie...\n\nIl n’y a qu’un moyen de s’en assurer : remettez un flacon de parfum et une bouteille d’eau de Cologne à Morgan Pestle, et faites-lui part de mes soupçons. Je vous rembourserai vos achats lorsque vous reviendrez me voir.", progress = "Puis-je vous aider ?", completion = "Je comprends qu’Aristan s’inquiète, mais je pense qu’il en fait trop. Il faut bien que jeunesse se passe, après tout. Aristan a oublié ce que c’était d’être jeune et amoureux.\n\nMais bon, il vaut mieux ne pas le lui dire. Faisons comme si…", rewards = nil},
[9025] = {title = "La découverte de Morgan", objective = "Retourner voir Aristan Mottar, à côté de la banque, dans le Quartier commerçant de Stormwind.", description = "Hé bien, cela m’étonne aussi, mais on dirait qu’Aristan a mis le doigt sur quelque chose. J’ai trouvé des traces de certaines substances utilisées dans les philtres d’amour, et d’une décoction subtile qui altère le jugement.\n\nCe n’est pas totalement inhabituel pour des parfums, mais certains de ces ingrédients… ne sentent pas bon, si vous voyez ce que je veux dire.", progress = nil, completion = "Mes pires craintes se confirment. Je trouve cela très angoissant. Nous devons réfléchir à la suite des opérations.\n\nTenez, voilà déjà de quoi vous rembourser vos frais de parfum et d’eau de Cologne.", rewards = "Vous recevrez :\n\nBoîte de chocolatsPoignée de pétales de rose"},
[9026] = {title = "Remonter à la source", objective = "Parler à l’aubergiste Allison à la Rose dorée, dans le Quartier commerçant de Stormwind.", description = "Nous devons remonter à la source. Il y a beaucoup plus de gens qui entrent et sortent de la Rose dorée que d’habitude… y compris des gardes. Parlez à Allison. Si elle vend ces parfums, elle pourra vous dire d’où ils viennent.", progress = nil, completion = "Oh oui, j’ai fait des stocks de parfum et d’eau de Cologne. Ils se vendent si bien qu’ils vont être épuisés en un rien de temps.\n\nSi vous voulez mon avis, c’est un peu barbant. D’accord, c’est une odeur agréable, mais un monde où tout le monde sent pareil…", rewards = nil},
[9027] = {title = "Remonter à la source", objective = "Parler à Evert Sorisam, au Fil le plus fin, au bord des canaux de Stormwind.", description = "Quelque chose d’anormal dans l’eau de Cologne ? C’est possible. Je n’ai jamais vu autant de gens se ruer sur un produit.\n\nÉcoutez, s’il y a un problème, je veux le savoir. J’ai acheté ma réserve à un marchand nommé Evert Sorisam. Il est arrivé en ville il n’y a pas longtemps.\n\nIl m’a parlé d’une livraison à faire au Fil le plus fin.", progress = nil, completion = "Mais oui, bien sûr, ces parfums sont le produit phare de cette saison. Vous devez être la cinquième ou la sixième personne à me poser la question en moins d’une heure.\n\nHélas, j’ai tout vendu. Si vous en voulez, vous devriez parler à Alison, l’aubergiste de la Rose dorée.\n\nMais faites vite. Vous verrez, cette eau de Cologne est irrésistible.", rewards = nil},
[9028] = {title = "La source est découverte !", objective = "Trouver l’apothicaire Staffron Lerent dans les contreforts d’Hillsbrad, derrière le manoir de Ravenholdt.", description = "Comment ça, une trahison ? Non, je vous assure que mes intentions sont complètement innocentes.\n\nQuel mal y a-t-il à aider ceux qui souhaitent simplifier les rites complexes de la séduction ? Cela n’a rien d’un crime !\n\nTenez, pour vous prouver que je ne voulais de mal à personne, je vais même vous indiquer ma source.\n\nTous ces produits venaient d’un certain Staffron Lerent, un apothicaire ou quelque chose de ce genre. Je ne l’ai jamais vu.\n\nL’intermédaire, un gobelin, m’a dit qu’il travaillait dans les contreforts d’Hillsbrad, derrière le mystérieux manoir de Ravenholdt. Si vous voulez aller le voir, je vous souhaite bonne chance !", progress = nil, completion = "Mais oui, j’ai conçu ces parfums. Ils sont merveilleux, n’est-ce pas ? Irrésistibles.\n\nLorsque les guerriers de l’Alliance et de la Horde seront tous abêtis par l’amour, ils seront incapables de s’opposer aux progrès du Conseil des ombres.\n\nIls seront pris au dépourvus, affaiblis, rongés d’angoisse à l’idée du sort qui menace ceux qu’ils aiment…\n\nC’était une idée si simple, je me demande pourquoi il m’a fallu aussi longtemps pour y penser. Le cœur est le point faible de tout un chacun. Et vous ne pouvez rien faire pour empêcher l’inévitable.", rewards = nil},
[9029] = {title = "Un chaudron bouillonnant", objective = "Une odeur agréable s'échappe du chaudron.", description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nHabit de soirée bleuHabit de soirée violetHabit de soirée rougeSuperbe robe bleueSuperbe robe violetteSuperbe robe rouge"},
[9030] = {title = "Les adieux d'Anthion", objective = "Allez voir Deliana à Forgefer.\n\nObjet fourni : \n", description = "L’âme de Valthalak était conservée dans cette amulette.\n\nAveuglés par la cupidité, nous l’avons brisée en trois, sans savoir que nous allions être maudits pour cela.\n\nLe seul moyen d’arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.\n\nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[9032] = {title = "Le triste destin de Bodley", objective = "Rendez-vous au mont Blackrock, près du pic Blackrock, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.Ce médaillon contenait l’âme du seigneur Valthalak ? Je comprends mieux qu’il ait été gardé par une puissante malédiction.\n\nLocaliser Bodley risque d’être difficile. Aux dernières nouvelles, il se préparait à retourner au pic Blackrock. On n’a plus jamais entendu parler de lui.\n\nVous devriez le chercher au mont Blackrock, même s’il est probablement déjà mort. Je vous suggère de prendre la machine du gobelin avec vous, <mon ami/mon amie>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", description = "Ce médaillon contenait l’âme du seigneur Valthalak ? Je comprends mieux qu’il ait été gardé par une puissante malédiction.\n\nLocaliser Bodley risque d’être difficile. Aux dernières nouvelles, il se préparait à retourner au pic Blackrock. On n’a plus jamais entendu parler de lui.\n\nVous devriez le chercher au mont Blackrock, même s’il est probablement déjà mort. Je vous suggère de prendre la machine du gobelin avec vous, <mon ami/mon amie>.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[9033] = {title = "Les échos de la guerre", objective = "Le commandant Eligor Dawnbringer, de la chapelle de l’Espoir de Lumière dans les Maleterres de l'est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau de pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin.", description = "Cinq ans se sont écoulés depuis la dernière guerre…\n\nDes dizaines de milliers de morts, et pour quoi ? La menace n’a jamais été éradiquée.\n\nLe roi-liche s’agite à nouveau. Son lèche-bottes, Kel’Thuzad, ourdit une nouvelle attaque contre nos terres.\n\nNous ne le laisserons pas faire ! Prouvez votre volonté de servir ! Prouvez que vous êtes <prêt/prête> à risquer votre vie et votre âme pour mettre un terme à cette folie ! Si vous y parvenez, la puissance combinée de l’Aube et de la Croisade seront à votre service.\n\nPénétrez dans Naxxramas et anéantissez le Fléau qui y rôde…", progress = nil, completion = "De l’excellent travail ! Les services des hommes et des femmes de l’Espoir de Lumière seront votre récompense.", rewards = "Vous recevrez :\n\n"},
[9034] = {title = "Cuirasse de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d’armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuirasse de cuirassier"},
[9036] = {title = "Cuissards de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des cuissards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Cuissots désacralisés, 20 Débris d’armure en plaques, 4 Barres d’arcanite et 3 Peaux robustes traitées.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuissards de cuirassier"},
[9037] = {title = "Casque de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera un casque de cuirassier si vous lui apportez les choses suivantes : 1 Heaume désacralisé, 15 Débris d’armure en plaques, 5 Barres d’arcanite et 1 Cristal de nexus.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCasque de cuirassier"},
[9038] = {title = "Espauliers de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des espauliers de cuirassier si vous lui apportez les choses suivantes : 1 paire d'Espauliers désacralisés, 12 Débris d’armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nEspauliers de cuirassier"},
[9039] = {title = "Solerets de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des solerets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Solerets désacralisés, 12 Débris d’armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSolerets de cuirassier"},
[9040] = {title = "Gantelets de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des gantelets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Gantelets désacralisés, 8 Débris d’armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGantelets de cuirassier"},
[9041] = {title = "Sangle de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera une sangle de cuirassier si vous lui apportez les choses suivantes : 1 Sangle désacralisée, 8 Débris d’armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSangle de cuirassier"},
[9042] = {title = "Brassards de cuirassier", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des brassards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Brassards désacralisés, 6 Débris d’armure en plaques, 1 Barre d’arcanite et 1 Cristal de nexus.", description = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d’armures désacralisées et des débris d’armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.", progress = "Les poignets sont la seconde partie la plus exposée du corps... Ou alors la quatrième ?", completion = "Rappelez-vous, le poignet est le cinquième point le plus vulnérable du corps ! Protégez vos poignets, et vos poignets protègeront vos coudes... probablement.", rewards = "Vous recevrez :\n\nBrassards de cuirassier"},
[9043] = {title = "La tunique de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera une Tunique de rédemption si vous lui rapportez 1 Tunique désacralisée, 25 Débris d'armure en plaques, 4 Barres d’arcanite et 3 Peaux robustes traitées.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique de rédemption"},
[9044] = {title = "Les cuissards de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des Cuissards de rédemption si vous lui rapportez 1 paire de Cuissards désacralisés, 20 Débris d'armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuissards de rédemption"},
[9045] = {title = "Le couvre-chef de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera un Couvre-chef de rédemption si vous lui rapportez 1 Couvre-chef désacralisé, 15 Débris d'armure en plaques, 5 Barres d’arcanite et 2 Peaux robustes traitées.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouvre-chef de rédemption"},
[9046] = {title = "Les spallières de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des Spallières de rédemption si vous lui rapportez 1 paire de Spallières désacralisées, 12 Débris d'armure en plaques, 2 Barres d’arcanite et 2 Cristaux de nexus.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSpallières de rédemption"},
[9047] = {title = "Les bottes de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des Bottes de rédemption si vous lui rapportez 1 paire de Bottes désacralisées, 12 Débris d'armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBottes de rédemption"},
[9048] = {title = "Les garde-mains de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des garde-mains de rédemption si vous lui rapportez 1 paire de Garde-mains désacralisés, 8 Débris d'armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGarde-mains de rédemption"},
[9049] = {title = "Le ceinturon de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera un Ceinturon de rédemption si vous lui rapportez 1 Ceinturon désacralisé, 8 Débris d'armure en plaques, 1 Barre d’arcanite et 3 Cristaux de nexus.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinturon de rédemption"},
[9050] = {title = "Les protège-poignets de rédemption", objective = "Le commandant Eligor Dawnbringer de la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des Protège-poignets de rédemption si vous lui rapportez 1 paire de Protège-poignets désacralisés, 6 Débris d'armure en plaques, 1 Barre d’arcanite et 2 Peaux robustes traitées.", description = "Vous trouverez les restes de l’équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas. Rapportez-moi ces souvenirs désacralisés ainsi que des débris d’armures et des matériaux d’artisanat capables de revitaliser les pièces d’armures maudites. Ils me permettront de vous confectionner une superbe protection.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nProtège-poignets de rédemption"},
[9051] = {title = "Test de toxicité", objective = "Piquez un Diablosaure avec l'Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d'Un'goro lorsque vous aurez accompli cette tâche.", description = "La toxine que vous m'avez aidé à créer est destinée à un usage particulier. Les grands diablosaures du cratère rendent la chasse dangereuse et la survie difficile. Même si j'avais la force nécessaire pour en tuer un, cela permettrait seulement à un autre de s'emparer de son territoire.\n\nPrenez cet aiguillon empoisonné et plongez-le dans le corps d'un diablosaure vivant. La toxine devrait pacifier la créature, mais j'ignore combien de temps cela prendra...", progress = nil, completion = "Merci, &lt;nom&gt;. Vous êtes courageux et sage.\n\nDites-moi, comment le diablosaure a-t-il réagi à la toxine ?", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\n"},
[9052] = {title = "Le poison de Pétale-de-sang", objective = "Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro.", description = "Je voudrais que vous m'aidiez à créer une sorte de toxine, afin de calmer une grande créature qui vit ici dans le cratère. Elle n'est pas mortelle, et seuls les yeux vifs d'un <classe> peuvent espérer trouver les ingrédients.\n\nLes champignons chapeaux de sang se ramassent à l'intérieur des pousses de Pétale-de-sang partout dans le cratère. Les dards de Gorishi proviennent des guêpes volantes géantes à l'intérieur et autour de la Balafre sinueuse, qui se trouve dans la partie sud du cratère.", progress = "Avez-vous réussi ?", completion = "Les ingrédients, enfin !\n\nEn les ajoutant à l'humus d'Un'goro que j'ai recueilli, il sera facile de concocter la toxine...", rewards = "Vous recevrez :\n\nPotion de soins majeure"},
[9053] = {title = "Un meilleur ingrédient", objective = "Récupérez une Liane putride sur le Gardien au fond du Temple englouti et revenez voir Torwa Pathfinder.", description = "C'est ce que je craignais - la toxine n'est tout simplement pas assez efficace pour une créature si puissante.\n\nSi nous voulons créer une toxine assez virulente, vous devez vous rendre au fond du temple d'Atal'Hakkar, découvrir les secrets de l'autel et récupérer une liane putride auprès du gardien qui s'y trouve. Le temple est dangereux, vous devriez vous entourer d'amis.\n\nRevenez me voir quand ce sera fait.", progress = "Avez-vous récupéré la liane ?", completion = "Enfin, la toxine peut être créée dans toute sa puissance. Je n'ose pas vous demander de l'inoculer une nouvelle fois à la créature, car je vous en ai déjà trop demandé.\n\nVous méritez mes remerciements et mon respect. Que vos voyages se déroulent sans encombre, &lt;nom&gt;.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nFourrure grisonnanteEtreinte de la forêtBâton d'ombrelune\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[9054] = {title = "La tunique de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera une tunique de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Tunique désacralisée, 25 Débris d’armure en mailles, 4 Barres d’arcanite, et 3 Peaux robustes traitées.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique de traqueur des cryptes"},
[9055] = {title = "Les cuissards de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des cuissards de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Cuissards désacralisés, 20 Débris d’armure en mailles, 3 Barres d’arcanite, et 5 Peaux robustes traitées.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuissards de traqueur des cryptes"},
[9056] = {title = "Le couvre-chef de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera un couvre-chef de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Couvre-chef désacralisé, 15 Débris d’armure en mailles, 4 Barres d’arcanite et 2 Cristaux de nexus.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouvre-chef de traqueur des cryptes"},
