[9059] = {title = "Les garde-mains de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des garde-mains de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Garde-mains désacralisés, 8 Débris d’armure en mailles, 1 Barre d’arcanite et 5 Peaux robustes traitées.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !", progress = "Avez-vous les objets que je vous ai demandés, <classe> ?", completion = "Puisse la fureur du démon des cryptes guider votre main, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nGarde-mains de traqueur des cryptes"},
[9060] = {title = "Le ceinturon de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera un ceinturon de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Ceinturon désacralisé, 8 Débris d’armure en mailles, 1 Barre d’arcanite et 3 Cristaux de nexus.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !", progress = "Avez-vous les objets que je vous ai demandés, <classe> ?", completion = "Un ceinturon de roi ! Et il est pour vous, &lt;nom&gt;.", rewards = "Vous recevrez :\n\nCeinturon de traqueur des cryptes"},
[9061] = {title = "Les protège-poignets de traqueur des cryptes", objective = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, vous fabriquera des protège-poignets de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Protège-poignets désacralisés, 6 Débris d’armure en mailles, 1 Barre d’arcanite et 2 Peaux robustes traitées.", description = "J’ai découvert un moyen d’utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d’armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.\n\nApportez-moi les éléments nécessaires et je vous fabriquerai une armure d’un genre encore inconnu dans notre monde !", progress = "Avez-vous les objets que je vous ai demandés, <classe> ?", completion = "Les protège-poignets sont prêts. Amusez-vous bien !", rewards = "Vous recevrez :\n\nProtège-poignets de traqueur des cryptes"},
[9063] = {title = "Torwa Pathfinder", objective = "Parler à Torwa Pathfinder au cratère d'Un'goro.", description = "Un chasseur du nom de Torwa Pathfinder a demandé l'aide d'un druide. Il dit que nous seuls possédons les aptitudes et le respect envers la nature nécessaires pour l'aider.\n\nUne route relie le cratère d'Un'goro au désert de Tanaris. Vous trouverez Torwa près de l'endroit où la route pénètre dans le cratère.", progress = nil, completion = "Vous avez fait un long voyage pour me rencontrer, &lt;classe&gt;, et vous arrivez juste à temps.", rewards = "Vous recevrez :\n\n"},
[9065] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em.Vous apprendrez :\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em.Vous apprendrez :\n\n", progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nSoins\n\nVous allez être la cible du sort suivant :\n\nPoulet autre\n\nVous recevrez également :\n\nEau de sourcePotion de soins mineure"},
[9068] = {title = "La tunique de Brise-terre", objective = "Rimblat Brise-terre à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est vous fabriquera une tunique de Brise-terre si vous lui apportez les objets suivants : 1 Tunique désacralisée, 25 Débris d'armure en mailles, 4 Barres d'arcanite et 3 Peaux robustes traitées.", description = "Me ferez-vous l’honneur de me rapporter les armures de ceux qui sont tombés en défendant ces terres ?\n\nLes armures ont été désacralisées et sont sans nul doute utilisées à mauvais escient, mais en combinant ces pièces désacralisées avec d’autres débris d’armures datant de la guerre, on peut les renouveler et en faire des armures efficace pour les batailles à venir.\n\nApportez-moi les restes d’armure de nos disparus et quelques ingrédients de purification, et vous pourrez porter l’armure de Brise-terre.\n\nCherchez dans Naxxramas.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique de Brise-terre"},
[9069] = {title = "Le kilt de Brise-terre", objective = "Rimblat Brise-terre à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est vous fabriquera un kilt de Brise-terre si vous lui apportez les objets suivants : 1 paire de Cuissards désacralisés, 20 Débris d'armure en mailles, 3 Barres d'arcanite et 5 Peaux robustes traitées.", description = "Me ferez-vous l’honneur de me rapporter les armures de ceux qui sont tombés en défendant ces terres ?\n\nLes armures ont été désacralisées et sont sans nul doute utilisées à mauvais escient, mais en combinant ces pièces désacralisées avec d’autres débris d’armures datant de la guerre, on peut les renouveler et en faire des armures efficace pour les batailles à venir.\n\nApportez-moi les restes d’armure de nos disparus et quelques ingrédients de purification, et vous pourrez porter l’armure de Brise-terre.\n\nCherchez dans Naxxramas.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nKilt de Brise-terre"},
