[84163] = {title = "Une juste compensation", objective = "Apportez une ceinture du Cœur-sauvage et une paire de gants du Cœur-sauvage à Deliana, à Ironforge.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gants que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture félinsEnsemble gants et ceinture astrauxEnsemble gants et ceinture du gardienEnsemble gants et ceinture du soigneur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84164] = {title = "Une juste compensation", objective = "Apportez une ceinture de bestiaire et une paire de gants de bestiaire à Deliana, à Ironforge.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi une ceinture et une paire de gants ordinaires que vous souhaiteriez améliorer.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture de poursuivantEnsemble gants et ceinture de rôdeur\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84165] = {title = "Une juste compensation", objective = "Apportez une ceinture de magistère et une paire de gants de magistère à Deliana, à Ironforge.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi une ceinture et une paire de gants ordinaires que vous souhaiteriez améliorer.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nCeinture du sorcierGantelets du sorcier"},
[84166] = {title = "Une juste compensation", objective = "Apportez une ceinture de Sancteforge et une paire de gantelets de Sancteforge à Deliana, à Ironforge.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gantelets que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture miséricordieuxEnsemble gants et ceinture radieuxEnsemble gants et ceinture de la volonté divine\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84167] = {title = "Une juste compensation", objective = "Apportez une ceinture de dévot et une paire de gants de dévot à Deliana, à Ironforge.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gants que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture de l’aubeEnsemble gants et ceinture du crépuscule\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84168] = {title = "Une juste compensation", objective = "Apportez une ceinture Sombreruse et une paire de gants Sombreruse à Deliana, à Forgefer.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gants que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.", progress = "Êtes-vous prêt à honorer notre marché ?", completion = "Vous avez respecté votre part du marché, je respecterai la mienne.\n\nSouvenez-vous quand même que je garde les meilleures pièces tant que vous n’aurez pas terminé votre tâche.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture du frissonEnsemble gants et ceinture de bataille\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84169] = {title = "Une juste compensation", objective = "Apportez une ceinture de Brume-funeste et des protège-mains de Brume-funeste à Deliana, à Forgefer.", description = "Vous avez tenu parole et rapporté l’invention de Mux. Je pense qu’une récompense s’impose, ne serait-ce que pour que vous restiez <motivé et désireux/motivée et désireuse> de sauver ma peau. Rapportez-moi la ceinture et la paire de gants que vous souhaitez améliorer. Je vous promets que les pièces que je vous donnerai en échange seront très supérieures.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble gants et ceinture corrompusEnsemble gants et ceinture pernicieux\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
