[84208] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre coiffe des éléments et votre haubergeon des éléments à Mokvar.", description = "Une histoire extraordinaire, <nom> ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.\n\nQuant à votre récompense, j’ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble heaume et plastron du soulagementEnsemble heaume et plastron d’éruptionEnsemble heaume et plastron d’impactEnsemble heaume et plastron de résolution\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84210] = {title = "Garder le meilleur pour la fin", objective = "Donnez votre casque de vaillance et votre cuirasse de vaillance à Mokvar.", description = "Une histoire extraordinaire, <nom> ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.\n\nQuant à votre récompense, j’ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nEnsemble heaume et plastron inamoviblesEnsemble heaume et plastron irrésistibles\n\nVous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez également :\n\n"},
[84213] = {title = "Faille sur demande", objective = "Aidez le docteur Jurgens à ouvrir une faille aux clairières de Tirisfal ou à la marche de l’Ouest.", description = "Participez à cette expérience historique avec moi pour admirer ma merveilleuse invention ! J’ai calculé deux emplacements avec un niveau adapté d’énergie de bioflux géothermique. Grâce aux phaseurs manuels à verrouillage automatique, je suis prêt à nous téléporter aux coordonnées des régions compatibles.", progress = nil, completion = "Jurgens a disparu dans le chaos. Vous voyez un morceau scintillant dans un conteneur cylindrique en cristal. Il contient les restes brisés des rouages internes du golem. Vous enfoncez la main dedans, détachez quelques câbles du boîtier et l’ouvrez.", rewards = "Vous recevrez :\n\nLunettes de soleilPrémonition et Prévoyance du combat"},
[84317] = {title = "Minuit infini", objective = "Gagner des intuitions astrales", description = "L’immense titan vous enveloppe d’une aurore d’éthérée de sagesse et d’expériences séculaires qui se mêlent à vos souvenirs.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nIntuition du vagabond intemporel"},
[84318] = {title = "Ohé !", objective = "Trouvez le marteau perdu d’Orthas à la croisée de Corrin.", description = "Ohé ! <classe> ! Oui, vous ! J’vous dois une fière chandelle pour avoir escrabouillé cette déprimante enveloppe corporelle que j’occupais depuis toutes ces années, mais j’sens point l’besoin de passer illico à aut’ chose. J’ai une « affaire en suspens » que j’dois régler avant de filer… Tête de bûche ! J’viens d’vous enrôler pour aider !\n\nMais j’aurais besoin que vous z’alliez m’chercher mon marteau. Y devrait s’trouver quelque part vers la croisée de Corrin, et y s’ra difficile à rater. \n\nHé, prenez ça aussi. C’est ma dent d’or favorite. Frottez-la quand z’aurez trouvé mon arme.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[84319] = {title = "Oh non, que nenni !", objective = "Orthas vous a demandé de récupérer son armure perdue dans le corps d’une abomination, quelque part dans Pestebois.", description = "Bon boulot avec le marteau, <classe>. Maint’nant, y a mon armure. J’pourrai point m’en passer pour partir dans l’grand au-delà. \n\nLe problème, c’est qu’elle est, euh… dans les entrailles d’une de ces abominations. Je sais, je sais, c’est beaucoup d’mander, mais comprenez que j’étais un thane puissant parmi les puissants sous la montagne. J’peux point passer à aut’chose, sachant que l’armure ancestrale d’mon clan se dissout dans les sucs gastriques d’une montagne de barbaque pourrie géante !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[84320] = {title = "Héritage perdu", objective = "Récupérez les objets de famille dans la crypte de la colline des Chagrins, dans les Maleterres de l’ouest, puis retournez voir la grande prêtresse Laurena, à la cathédrale de Stormwind.", description = "Je suis venue à Stormwind comme réfugiée, fuyant la dévastation apportée à Lordareon par le Fléau. Louée soit la Lumière que ma famille et moi ayons pu nous enfuir, mais une partie de nos trésors de famille est restée aux Maleterres.\n\nSi vous pouviez récupérer ces objets familiaux à l’endroit où ils reposent dans la crypte de la colline des Chagrins pour que je puisse les déposer dans les catacombes de la cathédrale, je serais votre obligée.", progress = nil, completion = nil, rewards = nil},
[84322] = {title = "Recherches écarlates", objective = "Cherchez l’artéfact dans le bastion de la Croisade écarlate, à la Main de Tyr, dans les Maleterres de l’est.", description = "Une page du registre attire votre attention :\n\n« Artéfact - récupéré non loin de la crypte de la colline des Chagrins. Forte harmonisation à la lumière. Ne conviendrait pas au projet à cause de ses fortes propriétés protectrices et de sa résistance aux enchantements d’amplification. Délivré à la Main de Tyr pour étude plus approfondie. »", progress = nil, completion = nil, rewards = nil},
[84330] = {title = "Un zeste de nécromancie", objective = "Obtenez une pierre runique nécrotique auprès de Maleki le Blafard à Stratholme, puis trouvez le cadavre de Nain en décomposition près du caveau au sud-ouest des Maleterres de l’est.", description = "Il faudra trouver un cadavre de Nain convenable, et lui faire accomplir un p’tit rituel pour que mon esprit s’enracine et que je poursuive ma route ! Rien d’anormal, jusque-là ! On aura aussi besoin d’une pierre runique nécrotique. D’un nécromancien, bien sûr. Paraît qu’il y en a un à Stratholme. Il se fait appeler Maleki le Blafard ou quelque chose comme ça. J’pense pas qu’il sera très enclin à s’en séparer, mais il y a toujours une solution !\n\nTrouvez-moi cette pierre et dirigez-vous vers le caveau. Un cadavre s’y trouve qui fera l’affaire !Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[84331] = {title = "Le miracle", objective = "Utilisez votre anneau diplomatique sur les éclats.", description = "Les éclats sont réunis, <nom>. Il ne reste plus que votre anneau.", progress = nil, completion = nil, rewards = nil},
[84338] = {title = "Un contrat contraignant", objective = "Apportez le Contrat de la Confrérie du Thorium à Lokhtos Sombrescompte, si vous voulez recevoir les plans du marteau de sulfuron.", description = "Le soussigné déclare par la présente que le lingot de sulfuron qu’il livre à la Confrérie du Thorium (CT SARL) est authentique et n’est pas une imitation. Le soussigné reconnaît de même que tous les dommages qu’<il/elle> pourrait subir en tentant de modeler, forger, trouver, créer, vendre ou manger du sulfuras n’est pas de la responsabilité ou une faute de CT SARL.\n\nEn signant ce contrat, vous en acceptez tous les termes.\n\n_________________\n\nSignatureVous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPlans : Marteau en sulfuron"},
[84348] = {title = "Cible prioritaire : duc Tectonis", objective = "Hansel Lourdemains à la Halte du Thorium attend de vous que vous détruisiez le duc Tectonis. Ce dernier se trouve dans une petite vallée à l’ouest de l’entrée de la gorge des Vents brûlants au mont Blackrock.", description = "Il y a un élémentaire particulièrement agressif appelé Tectonis qui mène la danse près de la base du mont Rochenoire. Il faut qu’il disparaisse ! Mettez un terme à ce tas de cailloux et faites-moi un rapport quand le travail sera accompli !\n\nVous trouverez le duc Tectonis dans une vallée au sud-est, près de l’entrée du mont Blackrock.", progress = nil, completion = "Ça va repousser nos ennemis, &lt;nom&gt; ! Hourra !", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84349] = {title = "Cible prioritaire : duc Brûlesceau", objective = "Le capitaine Lolo Heurteloin attend de vous que vous détruisiez le duc Brûlesceau. Vous trouverez ce dernier dans les profondeurs des grottes de la Fosse aux scories, directement au sud de la Halte du Thorium.", description = "Nos éclaireurs signalent qu’un seigneur du feu se faisant appeler duc Brûlesceau a été aperçu dans les profondeurs du Chaudron, travaillant sans relâche à l’invocation d’autres élémentaires des terres de Feu ! Nous avons besoin de vous pour remédier à la situation avant qu’elle ne devienne incontrôlable.", progress = nil, completion = "Bravo, &lt;nom&gt; ! Après toutes ces péripéties, je ne dirais pas non à un verre !", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84350] = {title = "Broyage sans concession", objective = "Evonice Fumesuie vous demande de tuer 10 Saccageurs en obsidienne dans la Gorge des Vents brûlants. Vous trouverez ces derniers le long de la section sud de la Gorge des Vents brûlants, et près de l’entrée du Mont Blackrock.", description = "Nous avons des élémentaires de terre à ne plus savoir quoi en faire ! Donnez-leur une bonne raclée et renvoyez-les dans les terres de Feu !", progress = nil, completion = "Hah ! Ça leur apprendra !", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84351] = {title = "Plus de matière grise, moins de sueur", objective = "Le Sous-chef Scrange attend de vous que vous tuiez des Surgisseurs d’obsidienne dans la gorge des Vents brûlants et que vous lui rameniez leurs noyaux d’énergie. Les Surgeons d’obsidienne se trouvent dans la partie sud de la gorge des Vents brûlants, près de l’entrée du mont Blackrock.", description = "Depuis le début des éruptions, nous nous battons bec et ongles pour contenir ces satanés élémentaires. Nos artisans sont mis à rude épreuve. Il s’avère que maintenir l’équipement et le matériel des troupes représente une charge de travail considérable. Heureusement, nous autres, Nains, sommes passés maîtres dans l’art de travailler intelligemment, et nous avons découvert que les noyaux d’énergie à l’intérieur des Surgisseurs d’obsidienne au sud-est de la Halte du Thorium peuvent être utilisés comme pierres à aiguiser pour affûter facilement nos lames !\n\nVous voulez bien aller en chercher pour nous ?", progress = "Hein ?", completion = "Ça fera l’affaire, &lt;classe&gt;. Merci !", rewards = "Vous recevrez :\n\n"},
[84355] = {title = "Des pauvres-flammes, plutôt !", objective = "Le Sous-chef Scrange attend de vous que vous tuiez les défenseurs et les élémentalistes porte-flammes à la Crête de Guet-du-feu, à l’ouest de la Halte du Thorium.", description = "Comme si nous n’avions pas déjà assez à faire ici, l’enclave du Marteau du crépuscule, juste à l’ouest de la Halte du Thorium, est en pleine effervescence depuis que la montagne s’est mise en branle et a vu son sommet exploser. D’après ce que nous savons, ce sont les nouveaux Porte-flammes qui dirigent les opérations. \n\nPourquoi ne pas vous rendre là-bas et en détruire le plus grand nombre possible ?", progress = nil, completion = "Bon débarras !", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84356] = {title = "Oh, ça brille !", objective = "Le Maître forgeron Brûlotin à la Halte du Thorium attend de vous que vous récupériez 8 blocs de pierre à feu auprès des esclavagistes Sombrefer dans la Fosse aux scories. Vous trouverez l’entrée de la Fosse à l’intérieur du Chaudron, au sud-est de la Halte du Thorium.", description = "Un groupe de Sombrefer a récemment été capturé en possession de gemmes enchantées pour le moins étranges. Ces gemmes ne semblent pas être originaires d’Azeroth, et je dois ABSOLUMENT les étudier de plus près ! Leurs esclaves sont en train de creuser dans le Chaudron. J’ai besoin que vous y alliez aussi vite que possible et que vous me rapportiez des échantillons supplémentaires. Je ferai en sorte que vos efforts soient récompensés !", progress = "Vous m’apportez quelque chose ?", completion = "Elles sont magnifiques ! J’ai hâte de les passer sous mon monoscope. Merci beaucoup, &lt;classe&gt;.", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84359] = {title = "Nuits blanches", objective = "Evonice Fumesuie attend de vous que vous buviez le jus onirique spécialement élaboré et que vous tuiez 5 Traqueurs porte-flammes près de la Halte du Thorium, dans la gorge des Vents brûlants.", description = "Non seulement ces bestioles nous attaquent de jour, elles doivent aussi nous tourmenter durant notre sommeil ! Le nouveau Seigneur du Crépuscule affectionne particulièrement les manigances oniriques et envoie des assassins pour nous attaquer dans nos rêves ! J’ai besoin que vous buviez quelques gorgées de mon « jus onirique » spécialement élaboré, d’origine locale et sans GNO. Cela devrait vous permettre de franchir la frontière entre le monde réel et celui du rêve, et d’arrêter ces malfaiteurs.", progress = "Vous leur avez donné une leçon ?", completion = "Bien joué, &lt;nom&gt;. Ils y réfléchiront à deux fois avant de pénétrer à nouveau dans la Halte du Thorium !", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84360] = {title = "Extinction d’incendie", objective = "Le surveillant Huilepoing attend de vous que vous tuiez 15 Envahisseurs des terres de Feu dans le Chaudron, au sud de la Halte du Thorium.", description = "Vous là, on vient de vous enrôler ! Les élémentaires de feu ne cessent de jaillir du Chaudron. J’ai besoin de vous pour cautériser la plaie, si vous voyez ce que je veux dire. À votre poste, <soldat/soldate> !:", progress = "Eh bien ?", completion = "Bien joué, &lt;nom&gt;. Vous avez du cran, je le reconnais.", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84369] = {title = "Soigner le guérisseur", objective = "Récupérez le flacon insolite auprès des Arbrefer marteleurs et apportez-le aux sources de Givrefeu au Berceau-de-l’Hiver.", description = "J’ai besoin de votre aide. Les tréants corrompus du bois d’Arbrefer, à Gangrebois, m’ont volé mon flacon. Le mélange d’herbes devrait soigner mes blessures, mais cela ne suffira pas. Apportez-la aux sources chaudes du Berceau-de-l’Hiver. Les eaux thérapeutiques qui s’y trouvent m’aideront à me rétablir.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\n[DNT] Calyx - Complete Quest\n\nVous recevrez :\n\n"},
[84372] = {title = "Au cœur du magma", objective = "Apportez un morceau de minerai en fusion chatoyant à Hansel Lourdemains. Vous trouverez ce minéral dans les bassins de lave de la Fosse aux scories, au plus profond du Chaudron.", description = "Nos éclaireurs m’ont signalé la présence d’un gros rocher incandescent dans la partie la plus profonde des bassins de lave sous le Chaudron. Les élémentaires semblent réagir à ce matériau. J’ai besoin de vous pour vous faufiler et récupérer un morceau de ce rocher. Il fait très chaud là-bas, à plus d’un titre. Je ne saurais donc trop vous conseiller de vous munir de potions de protection contre le feu !", progress = "Qu’avez-vous là ?", completion = "Espérons que cela nous permettra d’en apprendre davantage sur la nature du problème.", rewards = "Vous recevrez :\n\nBraise des terres de Feu"},
[84377] = {title = "La fin de la Horde sombre", objective = "Apportez la Tête de Rend Main-noire à Maître Mathias Shaw à Stormwind.", description = "Mission accomplie. Le corps sans vie de Dal’rend Main-noire, chef de guerre de la Horde sombre, gît à vos pieds. Prenez sa tête et présentez-la à maître Shaw.", progress = "Par la Lumière !", completion = "Bravo, champion. Le chef de guerre de la Horde sombre est mort, mettant fin à une ère de terreur sur nos terres. Que l’annonce de votre victoire se répande dans tout Hurlevent !", rewards = "Vous recevrez :\n\n"},
[84384] = {title = "Supercheries démoniaques", objective = "Récupérez 6 glandes pinéales de chouettard sur les chouettards du Berceau-de-l’Hiver, puis retournez voir l’émissaire crocs-d’ombre dans Gangrebois.", description = "Les Loas m’ont dit qu’un poison montait en puissance à Ashenvale, sur le sol corrompu où l’grand démon Mannoroth a été tué. Apparemment, quelqu’un puise du pouvoir sur la dépouille du seigneur des abîmes.\n\nCette personne doit s’servir d’illusions pour cacher ses rituels. Si vous voulez l’arrêter, vous d’vez vous immuniser contre sa supercherie.\n\nMa tribu utilise un extrait de glandes de chouettard dans un enchant’ment pour différencier la vérité des mensonges. Récupérez ces glandes sur les chouettards du Berceau-de-l’Hiver.", progress = "L’enchantement est presque prêt, <nom>. Vous avez ramené c’que je vous ai demandé ?", completion = "&lt;La trolle chante son incantation au-dessus d’un objet, puis vous le tend.&gt;\nTenez, &lt;nom&gt;. Ça vous protègera des illusions des démons.", rewards = "Vous recevrez :\n\nGardien d’illusion crocs-d’ombre"},
[84394] = {title = "Mécène de la bibliothèque", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous apprendrez :\n\nGravure de cape (Barrage des arcanes)\n\nVous allez être la cible du sort suivant :\n\n[DNT] Arcane Barrage"},
[84395] = {title = "Pommes de terre mortes-vivantes", objective = "Avez-vous apporté quelque chose pour enrichir notre collection ?", description = nil, progress = "Avez-vous apporté quelque chose pour enrichir notre collection ?", completion = "Merci, &lt;nom&gt;. Notre savoir s’enrichit grâce à vos efforts.\n\nSi vous découvrez d’autres ouvrages magiques qui pourraient profiter à notre bibliothèque, apportez-les-moi.", rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84396] = {title = "Magma ou lave ?", objective = "Avez-vous apporté quelque chose pour enrichir notre collection ?", description = nil, progress = "Avez-vous apporté quelque chose pour enrichir notre collection ?", completion = "Merci, &lt;nom&gt;. Notre savoir s’enrichit grâce à vos efforts.\n\nSi vous découvrez d’autres ouvrages magiques qui pourraient profiter à notre bibliothèque, apportez-les-moi.", rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84397] = {title = "Le guide complet du nord de Kalimdor", objective = "Avez-vous apporté quelque chose pour enrichir notre collection ?", description = nil, progress = "Avez-vous apporté quelque chose pour enrichir notre collection ?", completion = "Merci, &lt;nom&gt;. Notre savoir s’enrichit grâce à vos efforts.\n\nSi vous découvrez d’autres ouvrages magiques qui pourraient profiter à notre bibliothèque, apportez-les-moi.", rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84398] = {title = "Étude de la Lumière", objective = "Avez-vous apporté quelque chose pour enrichir notre collection ?", description = nil, progress = "Avez-vous apporté quelque chose pour enrichir notre collection ?", completion = "Merci, &lt;nom&gt;. Notre savoir s’enrichit grâce à vos efforts.\n\nSi vous découvrez d’autres ouvrages magiques qui pourraient profiter à notre bibliothèque, apportez-les-moi.", rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84399] = {title = "Badaboum !", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84400] = {title = "La Dame et le Chevalier", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84401] = {title = "Le Fléau : menace morte-vivante ou phénomène incompris ?", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84402] = {title = "La nécromancie pour les nuls", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCharme de compréhension"},
[84405] = {title = "Héritage perdu", objective = "Récupérez les objets de famille dans la crypte de la Colline des chagrins, dans les Maleterres de l’ouest, puis retournez voir Dietrich Praice à Orgrimmar.", description = "Avant que la peste ne me transforme, j’étais un marchand important à Andorhal. La ville a sûrement enterré mes anciennes richesses et mes archives familiales dans la crypte de la Colline des chagrins quand j’ai disparu.\n\nAccepteriez-vous de récupérer mes affaires dans la crypte et de me les ramener ?", progress = nil, completion = nil, rewards = nil},
[84406] = {title = "Relique de lumière", objective = "Rendez-vous à Âtreval, dans les Maleterres de l’ouest, et cherchez des informations sur l’artéfact décrit dans le journal.", description = "Cette arme de lumière décrite dans le journal m’inquiète. Si la Croisade écarlate ou l’Alliance venaient à obtenir une telle chose, les Réprouvés courraient un grave danger.\n\nLa plupart des archives encore existantes d’Andorhal sont sous la protection de la Croisade écarlate à Âtreval. Consultez-les et voyez si elles contiennent d’autres informations.", progress = nil, completion = nil, rewards = nil},
[84407] = {title = "Le prix intérieur", objective = "Trouvez un moyen d’ouvrir la boîte et de récupérer l’artéfact, puis apportez-le à Dietrich Praice à Orgrimmar.", description = "Un pouvoir irradie de l’intérieur de la boîte. Ce doit être l’artéfact ! Vous n’avez plus qu’à l’ouvrir…Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nÉpiphanie jubilatoire"},
[84408] = {title = "Offres diplomatiques", objective = "Réunissez les fournitures et apportez-les à Dietrich Praice à Orgrimmar.", description = "<nom>, alors que j’étudiais le fragment de lumière que vous m’avez apporté, celui-ci m’a conféré des visions. J’ai vu un prêtre de l’Alliance trouver un fragment similaire, et j’ai vu l’Alliance et la Horde s’unir dans un flot de lumière.\n\nHélas, l’Alliance continue de nous traiter comme de vulgaires vermines.\n\nJe suggère de leur préparer un cadeau diplomatique en guise de bonne foi. Apportez-moi ces fournitures, et nous verrons s’il est possible d’instaurer un dialogue entre nos peuples.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGardien altruiste"},
[84411] = {title = "Anneau diplomatique", objective = "Apportez les matériaux demandés à Dietrich Praice à Orgrimmar.", description = "Le cadeau diplomatique que vous avez créé est parvenu à la grande prêtresse Laurena à Stormwind, et j’ai discrètement établi le contact avec elle. Nous avons convenu que ces recherches ne devraient être révélées qu’aux fidèles. Si les fragments peuvent être utilisés comme une arme, mieux vaut qu’ils ne tombent pas entre les mains de nos dirigeants respectifs.\n\nNous avons imaginé un moyen d’identification secret pour celles et ceux qui cherchent les fragments. Apportez-moi les matériaux nécessaires pour forger un anneau qui contiendra une infime portion de l’un des fragments.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAnneau diplomatique"},
[84418] = {title = "Le chevalier disparu", objective = "Une connaissance commune a besoin d’aide pour retrouver un chevalier disparu nommé Dalton. Son jeune écuyer et lui ont été aperçus pour la dernière fois dans les Maleterres, et personne ne les a revus depuis un bon moment. Si vous passez dans la région, ouvrez l’œil.\n\nNous n’avons pas d’autres indices, mais vous avez le don de vous retrouver dans des situations intéressantes. Cela ne m’étonnerait pas que vous tombiez nez à nez avec le chevalier et son jeune écuyer en plein milieu de ces Maleterres infernales !", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTestament du destrier divin"},
[84495] = {title = "Gantelets en plaques de feu", objective = "Apportez à Malyfous Sombremartel 6 Barres de thorium enchanté, 2 Essences de feu et 4 Rubis étoilés. Remettez-lui également vos Gantelets en plaques inachevés.", description = "Par la barbe de Thaurissan !\n\nOù les avez-vous trouvés ?\n\nEt plus important encore, voudriez-vous vous en séparer ? Naturellement, je paierais pour un geste si noble.\n\nJe vais vous dire, <nom>… si vous me donnez ces gantelets inachevés, je vous enseignerai comment en faire par vous-même. Tout ce dont vous avez besoin est de me trouver les parties nécessaires afin que je puisse trouver par élimination la recette exacte.\n\nSommes-nous d’accord ??\n\nVoici la liste des choses dont j’ai besoin. Je préparerai moi-même le thorium non enchanté puisque vous fournissez les gantelets.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nPlans : Gantelets en plaques de feu de la technique cachéeGantelets en plaques de feu de la technique cachée"},
[84496] = {title = "Douce sérénité", objective = "Allez jusqu’à Stratholme et tuez le Forgeur de marteaux cramoisi. Récupérer son Tablier et rapportez-le à Lilith.", description = "Dans les confins du Bastion écarlate se trouve la douce Sérénité. Le forgeur de marteaux cramoisi garde ce secret de sa vie. Battez-le et apportez-moi son tablier. En échange, je vous enseignerai comment forger des marteaux.\n\nMais sachez bien ceci : une fois que vous aurez choisi de suivre cette voie, les arts de la forge d’épées ou de haches vous seront à jamais fermées.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant de marteaux\n\nVous recevrez :\n\nPlans : Marteau d’armes subtilement enchanté"},
[84525] = {title = "Trésor venu d’ailleurs", objective = "Voilà, boss !Vous recevrez :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTrésor venu d’ailleurs"},
[84545] = {title = "La récompense du héros", objective = "Allez chercher votre récompense dans le Coffre d’Hydraxis.", description = "<nom>, les services que vous avez rendus aux Seigneurs de la guerre surpassent tout ce que nous attendions des habitants de ce monde.\n\nNous ne comprenons pas la notion de gratitude, ou de récompense pour des bonnes actions, mais dans ce cas… une prime semble être à l’ordre du jour.\n\nSous les flots à la base sud de cette île, vous trouverez un coffre. Il contient votre… récompense.\n\nAllez, <nom>. Allez récupérer votre récompense.", progress = nil, completion = "La voix d’Hydraxis descend depuis la surface…\n\n« Choisissez ce qui vous convient, &lt;nom&gt;. Puisse ce don vous protéger des ennemis des Hydraxiens. »", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBrise de l’océanJonc des flots\n\nVous recevrez également :\n\n"},
[84546] = {title = "Le bâton des anciens", objective = "Vous devez trouver et tuer quatre corrupteurs démoniaques :\n\nSimona la Séductrice.\n\nKlinfran l’Enragé.\n\nSolenor le Tueur.\n\nArtorius le Néfaste.\n\nDétruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois.\n\nVous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire.\n\nVous DEVEZ agir seul.", description = "Les agents de la Légion ardente sont toujours actifs dans notre monde, <classe>. Ils corrompent tout ce qu’ils touchent. En leur présence, la nature se flétrit et pleure.\n\nVous devez traquer ces corrupteurs démoniaques et les détruire, <nom>. Mais attention, vous devez agir seul. Ils fuiront s’ils voient un groupe. En revanche, si vous êtes seul, ils tenteront leur chance et essayeront de vous tuer. Vous devez les frapper, changer leur arrogance en souffrance.\n\nJe vous donne un morceau de mon écorce, les inscriptions qui s’y trouvent vous conduiront à vos cibles.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBâton runique gravé des anciens"},
[84548] = {title = "Garona : une étude en discrétion et en trahison", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d’Eldre’Thalas"},
[84549] = {title = "Les recettes de l’arcaniste", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d’Eldre’Thalas"},
[84550] = {title = "Le codex de défense", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d’Eldre’Thalas"},
[84551] = {title = "La lumière et comment l’altérer", objective = "Rendez ce livre à ses légitimes propriétaires.", description = "Ce livre porte la marque de l’Athenaeum.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nSceau royal d’Eldre’Thalas"},
[84555] = {title = "Le guide de Nostro", objective = "Rapportez Le guide de Nostro du tueur de dragons à l’Athenaeum.", description = "Vous avez découvert un objet à l’importance capitale. Ce livre est tout à fait unique.\n\nIl semble que quelqu’un ou quelque chose est parvenu à briser le sceau de l’Athenaeum. Le texte à l’intérieur est à peine lisible.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[84556] = {title = "Forger Quel’Serrar", objective = "Donnez la lame elfique inachevée au Gardien du savoir Lydros.", description = "Si vous voulez entreprendre cette tâche, apportez la lame émoussée à Lydros.", progress = nil, completion = nil, rewards = nil},
[84557] = {title = "Forger Quel’Serrar", objective = "Vous devez faire en sorte qu’Onyxia crache le feu sur la Lame ancienne brute. Une fois que ce sera fait, prenez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement, le temps est compté.\n\nLa dernière étape avant de revenir me voir est de tuer la bête et de planter la Lame ancienne chauffée dans son cadavre.\n\nSi vous le faites, Quel’Serrar sera à vous.", description = "Emportez cette lame antique inachevée au repaire d’Onyxia et affrontez cette dernière.\n\nVous devrez faire preuve de ruse pour chauffer la lame. Pendant le combat, le dragon tentera certainement de vous incinérer avec son souffle ardent. Vous devrez planter la lame antique dans le sol près de vous, et espérer que ce souffle suffira à la chauffer. Si vous survivez à cette étape, prenez la lame chauffée et achevez le dragon.\n\nPlongez la lame chauffée dans son cadavre fumant pour effectuer le revenu de la lame.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nQuel’Serrar"},
[84560] = {title = "Célébrer le triomphe", objective = "Allez voir le major Mattingly dans la vallée des Héros.", description = "Allez voir le major Mattingly dans la vallée des Héros, <nom>. Il vous attend.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nTalisman de sang d’OnyxiaChevalière du tueur de dragonPendentif en dent d’Onyxia\n\nVous recevrez également :\n\n"},
[84561] = {title = "Pour que tous voient", objective = "Allez voir le seigneur Runthak dans la vallée de la Force.", description = "Le seigneur Runthak attend votre arrivée dans la vallée de la Force.\n\n<Thrall vous salue.>\n\nNe faites pas attendre votre public, héros.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nTalisman de sang d’OnyxiaChevalière du tueur de dragonPendentif en dent d’Onyxia\n\nVous recevrez également :\n\n"},
[84590] = {title = "L’équilibre de la Lumière et de l’Ombre", objective = "Sauvez 50 Paysans avant que 15 d’entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havrefeu.\n\nConsultez le Panneau des morts pour voir combien de paysans ont été tués.", description = "Vous devez accomplir ce que je n’ai pas pu faire : sauver les paysans qui ont été tués alors qu’ils fuyaient Stratholme.\n\nIls marcheront vers la lumière, et vous devez veiller à ce qu’ils survivent. S’ils sont trop nombreux à tomber, notre existence maudite continuera et vous aurez échoué.\n\nToutes les prières, toutes les capacités, tous les sorts que vous connaissez seront mis à l’épreuve. Puisse la Lumière vous protéger, <nom>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nÉclat de Nordrassil"},
[84777] = {title = "Des plumes pour Nafien", objective = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi. Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs. Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", description = nil, progress = "Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi. Je pourrai peut-être vous aider dans cette tâche.\n\nCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs. Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.", completion = "Bien joué, &lt;nom&gt; ! Je ferai en sorte que vos actions soient connues par mon peuple.\n\nN’oubliez pas de m’apporter toutes les plumes que vous trouverez. Je continuerai à en accepter aussi longtemps que nécessaire.", rewards = nil},
[84870] = {title = "Le sombre butin", objective = "Entrez dans l’entrepôt du pic Blackrock et volez ce qui s’y trouve. Vous devrez terminer cette mission en solo.", description = "Ce document est un rapport d’un des sous-fifres de Tranchetripe. Selon certaines rumeurs, les orcs Blackrock cachent des artéfacts magiques illicites dans l’entrepôt. On ne sait pas encore s’il s’agit simplement de contrebande ou de quelque chose de plus important.\n\nDans tous les cas, le butin sera sûrement lucratif. Le mieux serait d’y aller en solo, pour éviter de vous faire repérer. Et de partager le butin.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85034] = {title = "Les ruines d’Andorhal", objective = "Prenez le sang du Porteur de Lumière et explorez Andorhal.", description = "Ce genre de reliques possède des propriétés bien mystérieuses. Les plus puissantes d’entre elles semblent parfois même douées de conscience ou de personnalité, notamment en présence d’individus ou de lieux qu’elles ont connus par le passé. \n\nS’il s’agit vraiment de celui d’Uther, le sang pourrait réagir en approchant près de l’endroit où Uther a succombé. Explorez la ville, et voyez ce qui se passe.", progress = nil, completion = "Alors il n’y a aucun doute, ce sang est authentique. C’est un vrai trésor que vous tenez là, &lt;classe&gt;. Protégez-le de votre vie.", rewards = nil},
[85063] = {title = "Aboutissement", objective = "Défendez Gregory pendant qu’il mène le rituel pour détruire l’orbe d’écho de Mannoroc.", description = "Je n’ai aucun moyen de prévoir ce qui se passera lorsque nous commencerons le rituel. Cet endroit est envahi de démons, et s’ils détectent notre rituel, nous aurons peut-être besoin de nous défendre. Ada et vous devrez vous en occuper pendant que je canaliserai le sort. Je vous en prie, ne vous éloignez pas. Vous êtes un élément essentiel de cette magie.", progress = "Soyez sur vos gardes, <classe>.", completion = "Non… non. C’est impossible ! Nous étions si proches ! \n\nJe ne peux pas avoir échoué. Azgaloth est libre. Nous devons nous rassembler pour établir un plan.", rewards = "Vous recevrez :\n\nAmulette d’Ada"},
[85064] = {title = "Pis-aller", objective = "Rendez-vous à Andorhal, trouvez Gregory et demandez-lui ce qu’il faut faire.", description = "Le temps joue contre nous. Le seigneur de l’effroi a évoqué le canyon de la Malechute, alors la bonne nouvelle est que nous savons où ils se rendent. La mauvaise, c’est que notre rituel raté a sans doute renforcé l’ancrage d’Azgaloth sur Azeroth. Même si nous tuons Azgaloth maintenant, il pourrait se manifester à nouveau.\n\nJ’ai une idée. Elle est désespérée, mais c’est peut-être notre seul espoir… Il y a quelqu’un à Andorhal, une personne dotée de capacités très spécifiques, qui pourrait nous aider. Mais il faudra lui donner une raison de nous faire confiance.", progress = "Très bien, vous êtes là.", completion = "Le reliquaire contenant le sang d’Uther était la clé de ce rituel, mais malheureusement, nous l’avons perdu dans l’attaque. Comme je vous l’ai dit, la magie est une histoire de liens, de liens construits et brisés. Si nous trouvons un autre échantillon de sang, nous pourrons l’utiliser contre la forme physique d’Azgaloth et le tuer, puis bannir son âme loin d’Azeroth une bonne fois pour toutes.\n\nQue savez-vous au sujet des Dragons de bronze ?", rewards = nil},
[85065] = {title = "Une Gnome des plus étranges", objective = "Parlez à Chromie à Andorhal et persuadez-la de vous aider.", description = "Ce dont nous avons besoin pour accomplir cette mission se trouve ici, à Andorhal. Mais pas en ce moment. \n\nDans la pièce derrière moi se trouve une « Gnome » appelée Chromie. Cette créature pour le moins étrange utilise un type bien spécifique de magie draconique… Une magie temporelle, pour tout vous dire.\n\nSi nous la persuadons d’utiliser sa magie pour nous aider, nous pourrons peut-être remonter dans le passé brièvement et obtenir ce dont nous avons besoin. C’est un pari à prendre, mais c’est peut-être notre seule solution. Essayez de la persuader.", progress = nil, completion = "C’est un plaisir de vous revoir, &lt;nom&gt; ! Enfin, je crois que ce n’est pas notre première rencontre. Nous nous connaissons déjà, n’est-ce pas ? C’est difficile de se souvenir de toutes les versions de chaque personne que j’ai rencontrée… ou que je rencontrerai.", rewards = nil},
[85066] = {title = "Préparatifs", objective = "Parlez à Gregory à Andorhal et demandez-lui de vous accompagner jusqu’à l’incendie d’Andorhal.", description = "Des invasions de démons, des rituels de mort… Tout ça fait très peur. Heureusement, cette petite bulle temporelle si pratique dans laquelle nous nous trouvons aide à nous connecter à un point temporel spécifique.\n\nCe sera dangereux, cela dit. Prévenez-moi lorsque votre ami et vous voudrez partir.", progress = nil, completion = "Alors tout est vrai… \n\nJe répugne à l’admettre, mais je ne suis sans doute pas le mieux placé pour partir avec vous. Entre l’attaque des démons et le feu sacré d’Aeonas, mon corps a trop souffert. Dans mon état, je vous ralentirais plus qu’autre chose. Et puisqu’Ada est morte, je pense que nous avons besoin de renforts.", rewards = nil},
[85067] = {title = "Un paladin de la Main d’argent", objective = "Allez au tombeau d’Uther et expliquez la situation à Aeonas.", description = "J’ai dit ne pas croire au destin, mais je ne sais pas si c’était l’entière vérité. J’ai ouvert les yeux sur tellement de choses, depuis la fin de mon existence mortelle… Mais plus je me consacre à cette mission, plus je commence à voir les liens et les schémas récurrents autour de nous. Je crois que vous le savez déjà : c’est Aeonas qui doit vous accompagner.\n\nCroyez-moi, j’aimerais pouvoir laisser mon vieil ami en paix, mais cet événement nous dépasse. Allez au tombeau d’Uther, et expliquez-lui la situation.", progress = nil, completion = "&lt;Gregory vous fait un signe de tête, ainsi qu’à Aeonas.&gt;\n\nLe moment est venu. &lt;nom&gt;, allez parler à Chromie lorsque vous pourrez partir.", rewards = nil},
[85068] = {title = "Qui a dit qu’on ne pouvait pas revenir en arrière ?", objective = "Empruntez le portail vers l’incendie d’Andorhal", description = "Le portail est prêt.\n\nUne fois que vous l’aurez franchi, vous arriverez à Andorhal juste après sa chute. Pour vous éviter d’attirer l’attention, je vous ai préparé des déguisements magiques. Ils feront l’affaire face à la plupart des habitants de l’époque, mais ne vous faites pas remarquer. Lorsque vous aurez trouvé ce qu’il vous faut, revenez à ce même endroit dans le passé. Le portail vous attendra.", progress = nil, completion = "Nous avons réussi. Préparez-vous, &lt;nom&gt;.", rewards = nil},
[85074] = {title = "L’incendie d’Andorhal", objective = "Accomplissez votre objectif et échappez à l’incendie d’Andorhal.", description = "J’ignore ce qui nous attend ici, mais ce ne sera rien de bon. \n\nNous devons entrer, trouver l’endroit où Uther est mort, puis voir si nous pouvons recueillir quelques gouttes de sang. Nous devrons ensuite rentrer à l’auberge du côté ouest de la ville et nous enfuir. Il faut faire vite, mais avec l’attention et le respect que le seigneur Uther méritait. L’idée de déranger l’endroit où il est tombé me met très mal à l’aise.\n\nFinissons-en.", progress = "C’était répugnant, mais nous avons accompli ce que nous venions faire.", completion = "J’imagine que nos déguisements ne réapparaîtront pas. Nous allons donc devoir combattre pour nous enfuir. Préparez-vous, &lt;nom&gt;.", rewards = nil},
[85087] = {title = "Une fuite désespérée", objective = "Frayez-vous un chemin jusqu’à l’auberge et retournez à votre propre époque. Si Aeonas et vous êtes libérés, sonnez du cor terni pour le rappeler à votre côté.", description = "Les morts-vivants sont passés et ont envahi le côté ouest de la ville. Ce combat s’annonce difficile, <nom>. Le temps joue contre nous, et nous devons éviter les zones les plus occupées par le Fléau. \n\nOh, j’ai failli oublier, prenez ceci. Si nous nous séparons, sonnez le cor et je vous rejoindrai.", progress = "Ce n’est rien… Juste une égratignure. Laissez-moi reprendre mes…", completion = "&lt;Aeonas commence à perdre connaissance avant d’ouvrir soudain les paupières pour plonger le regard dans le vôtre.&gt;", rewards = nil},
[85090] = {title = "Retour vers le futur", objective = "Reprenez le portail vers votre époque et remettez Porte-Vérité à Gregory.", description = "<Aeonas sourcille. Il est grièvement blessé> Je crois… que je n’irai pas plus loin, <nom>. Ce… Ce n’est rien. C’était… ma place. Je suis heureux d’être ici, avec mes camarades… à la fin.\n\nTenez, prenez ceci. Je l’ai forgé… en souvenir. Pour ne jamais oublier les amis que j’ai perdus ici, et toujours leur rester fidèle. C’est même le nom que je lui ai donné… Porte-Vérité. \n\nRemettez-la à Gregory pour moi. Elle l’aidera sans doute à se souvenir qui il est. Je pense que vous l’avez vu aussi. Il a… changé. \n\nJe…", progress = "Où est Aeonas ? Que s’est-il passé ?", completion = "Racontez-moi tout.", rewards = nil},
[85091] = {title = "Le coût de la victoire", objective = "Consacrez votre arme avec le sang du Porteur de Lumière et éliminez Azgaloth dans le canyon de la Malechute.", description = "Merci… de me l’avoir rapportée. Cette lame est consacrée, il me sera très douloureux de la manier, mais c’est un petit sacrifice à réaliser pour mon… mon ami.\n\nLe chagrin attendra. Pour le moment, finissons-en. Rassemblez vos camarades de confiance et rendez-vous au canyon de la Malechute. Azgaloth ne se révélera peut-être pas immédiatement, mais si vous lui lancez un défi approprié, il répondra. \n\nPrenez le sang, utilisez-le pour consacrer votre arme et le détruire. Pour Aeonas, et pour Ada, il est temps d’en finir.", progress = "…", completion = "Ma mission est enfin terminée.\n\nCelle-ci m’a absorbé pendant si longtemps que je n’avais jamais vraiment réfléchi à ce que la victoire sous-entendrait. De toute évidence, notre alliance doit maintenant prendre fin, et je ferais bien de rentrer à Norfendre…\n\n&lt;Un silence gêné s’installe entre vous.&gt;", rewards = nil},
[85092] = {title = "Porte-Vérité", objective = "Dites adieu à Gregory.Aeonas s’en est rendu compte bien avant moi. Il a remarqué combien j’avais changé pendant cette mission. Je ressens à nouveau… de la tristesse, des regrets et de l’amour. De la tristesse pour Ada, des regrets pour ma trahison et de l’amour pour mon ami. J’ignore ce que tout cela signifie, mais je sais que je ne peux pas retourner à Norfendre.\n\nEt si je me rendais à Lordaeron ? D’autres personnes comme moi vivent peut-être là-bas. Celles qui se sont éloignées de la Lumière… et qui s’efforcent de la retrouver. Je pourrai peut-être les aider, tout comme mon ami m’a aidé.", description = "Aeonas s’en est rendu compte bien avant moi. Il a remarqué combien j’avais changé pendant cette mission. Je ressens à nouveau… de la tristesse, des regrets et de l’amour. De la tristesse pour Ada, des regrets pour ma trahison et de l’amour pour mon ami. J’ignore ce que tout cela signifie, mais je sais que je ne peux pas retourner à Norfendre.\n\nEt si je me rendais à Lordaeron ? D’autres personnes comme moi vivent peut-être là-bas. Celles qui se sont éloignées de la Lumière… et qui s’efforcent de la retrouver. Je pourrai peut-être les aider, tout comme mon ami m’a aidé.", progress = nil, completion = "Manier Porte-Vérité ne me fait plus souffrir, et cela m’indique clairement la voie que je dois suivre.\n\nCependant, je crois que la lame devrait rester avec vous. Aeonas comprendrait, et je suis certain qu’il approuverait. Mon apogée en tant que combattant est derrière moi, et une arme comme celle-ci mérite d’être utilisée au service de la Lumière.\n\nAu revoir, &lt;nom&gt;. Que la Lumière soit avec vous.", rewards = "Vous allez être la cible du sort suivant :\n\n[DNT] Cancel Aura\n\nVous recevrez :\n\nPorte-Vérité"},
[85248] = {title = "Tout le monde sait que les insectes ne volent pas", objective = "Affrontez un dard silithide afin de l’affaiblir, puis utilisez votre compétence Trait de choc pour le ralentir. Lorsqu’il se met à s’agiter, utilisez Tir tranquillisant pour l’assommer. Ligotez-le, traînez-le jusqu’au fort Cénarien et accrochez-le à la barre d’attache en face de la salle de guerre du commandant Mar’alith pour que nous puissions l’étudier.\n\nRetournez voir le commandant Mar’alith au fort Cénarien lorsque vous aurez terminé.\n\nVous pouvez apprendre Tir tranquillisant dans le raid du Cœur du Magma.", description = "D’après vos rapports, les dards sont indubitablement plus rapides, mais nous devons en savoir plus à leur sujet. Si nous parvenons à en étudier un, nous découvrirons peut-être comment les neutraliser plus efficacement.\n\nVos talents à la chasse devraient permettre d’immobiliser l’un des dards et de le ramener ici pour que nous puissions en apprendre davantage à son sujet. Trouvez-en un, capturez-le et mettez-le dans la cage que nous avons installée pour l’étudier.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85304] = {title = "Essence de feu", objective = "Découvrez à quoi sert le parchemin inhabituel, puis faites part de vos conclusions aux bibliothécaires de Stormwind ou d’Undercity.", description = "Une énergie ardente émane du parchemin, qui ne ressemble à aucun de ceux que vous avez trouvés jusque-là. Une pierre magique près de Draco’dar, dans les steppes Ardentes, pourrait vous aider à comprendre son utilité. Traduisez le parchemin, puis découvrez sa fonction avant d’aller dévoiler vos découvertes aux bibliothécaires de Stormwind ou d’Undercity.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85386] = {title = "Essence de givre", objective = "Inspectez la gorge du Blanc murmure en quête d’un mystérieux pouvoir de givre.", description = "Il y a quelque temps, j’ai eu vent d’étranges phénomènes se produisant à la gorge du Blanc murmure. Il semblerait que ces géants de glace aient trouvé une sorte de pouvoir ancien. J’irais bien enquêter moi-même, mais j’ai trop à faire ici. Rapportez-moi quelque chose d’intéressant, d’accord ? Si vous en sortez indemne, évidemment.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85401] = {title = "Le refuge algide des saisons", objective = "Trouvez Nandieb dans le refuge des saisons près de Pluie-d’Étoiles, au Berceau-de-l’Hiver, et récupérez son bâton. Vous devez agir en solitaire.", description = "Tout comme la vie peut jaillir de la décomposition, ce qui est contre nature vient parfois servir le naturel.\n\nLe cœur peut être transformé en un bâton à la forme changeante, mais je vais avoir besoin d’un calice assez puissant pour contenir son pouvoir.\n\nIl y a un refuge des saisons près de Pluie-d’Étoiles, au Berceau-de-l’Hiver. La véritable entrée n’apparaîtra que si vous êtes en solitaire.\n\nÀ l’intérieur, vous trouverez un gardien ayant perdu son chemin il y a bien longtemps, Nandieb. Son bâton sera le calice du cœur. Je regrette d’avoir à le suggérer, mais il n’est plus le grand gardien que je connaissais jadis.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGla’sir"},
[85441] = {title = "Tonneraan le Cherchevent", objective = "Pour maîtriser le pouvoir du Cherchevent, vous devez présenter au généralissime Demitrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d’élémentium et l’Essence du seigneur du Feu dans la vallée des Cristaux.", description = "Je vous ai dit tout ce que je sais, <nom>. C’est à vous de trouver l’élémentium. C’est à vous de détruire la forme physique du seigneur du Feu.\n\nSi vous y parvenez, vous recevrez la bénédiction de Tonneraan.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85442] = {title = "Examiner le calice", objective = "Examinez le calice de la renaissance et rapportez-le au généralissime Demitrian.", description = "Examinez le calice utilisé pour libérer la tempête éphémère. C’est à partir de lui que le Cherchevent a pu renaître et, à présent, il tire son pouvoir renouvelé de la vallée des Cristaux.", progress = nil, completion = nil, rewards = nil},
[85445] = {title = "Le disque doré", objective = "Trouvez quelqu’un qui pourra vous en dire plus sur le disque doré chatoyant.", description = "Vous ignorez ce que peut être cet objet, mais il s’agit à l’évidence d’un artéfact doté d’une immense puissance. Vous devriez trouver quelqu’un qui puisse vous en dire plus sur cet artéfact et sa véritable fonction.", progress = "Je vous en prie, pressez-vous, <nom>.", completion = "Attendez, qu’avez-vous là ? On dirait… non, c’est impossible. Je ne l’ai vu que dans des livres, mais… il a été détruit. Ce n’est sûrement pas ce que je pense…\n\n&lt;Garek cesse momentanément de regarder l’objet accroché à votre ceinture et lève les yeux, son regard croisant le vôtre.&gt;\n\nOù avez-vous trouvé cet objet, &lt;classe&gt; ? Je vous en prie, je veux connaître tous les détails !", rewards = nil},
[85455] = {title = "Le sang du Porteur de Lumière", objective = "Trouvez quelqu’un qui pourra vous parler du sang du Porteur de Lumière.\n\n(Veuillez noter que vous devez avoir achevé la quête Rendez-vous dans les Maleterres avant de pouvoir achever celle-ci.)", description = "Votre main frémit légèrement alors que vous tenez la petite fiole de sang. En dehors de l’inscription sur l’étiquette, vous sentez une chaleur et une énergie émaner de l’échantillon. Serait-ce vraiment le sang du héros légendaire, Uther le Porteur de Lumière ? Vous devriez trouver quelqu’un qui puisse vérifier l’authenticité de cet échantillon.", progress = "Que la paix soit avec vous, <classe>.", completion = "Attendez, qu’est-ce que vous avez là ?\n\n&lt;Le grand prêtre Thel’danis écarquille les yeux en examinant le reliquaire.&gt;\n\nC’est impossible. Comment les Dragons noirs pourraient-ils obtenir un échantillon du sang du seigneur Uther ?\n\nSi c’est vrai, cela en ferait une relique d’une importance capitale. Approfondissons la question.", rewards = nil},
[85457] = {title = "Exactement ce qu’il fallait", objective = "Apportez le sang du Porteur de Lumière à Gregory à Caer Darrow dans les Maleterres de l’Ouest.", description = "Je devine déjà que vous avez l’intention d’apporter le sang à Gregory. Bien. Mon jugement a été pour le moins discutable, et j’ai toujours considéré qu’il s’agissait d’un jeu de jeune paladin auquel je ne faisais que participer.\n\nJe ne sais toujours pas ce que je dois ressentir, mais je suis heureux de constater que vous êtes désormais le type de paladin que vous vouliez devenir.", progress = "Oui, <nom> ?", completion = "Je ne m’attendais pas à vous revoir ici, du moins pas si tôt. De quoi s’agit-il ?", rewards = nil},
[85458] = {title = "La gorge du Sombre murmure", objective = "Rencontrez Gregory à la Gorge du Sombre murmure, au Berceau-de-l’Hiver.", description = "C’est… incroyable. Je suis bien trop réaliste pour croire au destin, mais il s’agit là d’un retournement de situation fortuit. Je pense que nous avons tout ce qu’il nous faut pour accomplir le rituel et détruire l’orbe pour de bon. Comme dans tout bon rituel, l’emplacement est essentiel. Connaissez-vous la gorge du Sombre murmure au Berceau-de-l’Hiver ? C’est un endroit maudit, infesté de démons, mais c’est là que nous devons aller pour en finir.\n\nJe réunirai l’orbe et les matériaux restants, et je vous rejoindrai là-bas. La fin de ma mission est proche !", progress = "Vous avez réussi, bravo. Soyez sur vos gardes, <nom>.", completion = "Je sais que c’est un peu éloigné, mais nous avons besoin d’une zone où la barrière entre notre réalité et le Néant est mince, avec une grande concentration d’énergie arcanique latente. La dernière fois, nous avons choisi Gangrebois en raison de sa proximité avec le mont Hyjal. Pour ce rituel, je ne veux prendre aucun risque, et je voulais m’approcher le plus possible du Puits d’éternité actuellement inactif.\n\nJe sais déjà que c’est l’endroit idéal. Je peux presque sentir l’énergie dans l’air. Venez, commençons.", rewards = nil},
[85480] = {title = "La reconnaissance de Procrastimond", objective = "Vous recevrez :\n\n", description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTome de Cassandre"},
[85485] = {title = "Âme du Vide", objective = "Trouvez le marcheur du Vide près de la croisée de Corin dans les Maleterres de l’Est et ajoutez son âme à la faux.", description = "La faux évolue bien. La prochaine âme que vous devriez essayer d’ajouter est celle d’un marcheur du Vide. J’en connais un particulièrement puissant qui persiste malgré la mort de son maître dans les environs. Son âme devrait constituer un bon ajout.", progress = nil, completion = nil, rewards = nil},
[85486] = {title = "Âme d’ensorcellement", objective = "Utilisez un parchemin lumineux de guérison spatiale sur une grande faille gangrenée pour invoquer un intrus gangrené et obtenir son âme.", description = "Votre prochaine tâche est beaucoup plus délicate et concerne les gangreportails qui sont apparus un peu partout. J’ai entendu dire que lorsque les mages utilisent des parchemins spéciaux, ils invoquent de puissants intrus gangrenés. Les membres du Fléau de Pestebois semblent utiliser la même technique. Utilisez le démon qu’ils tentent d’invoquer de la même manière pour le prochain fragment d’âme.", progress = nil, completion = nil, rewards = nil},
[85501] = {title = "Le cœur de Chromaggus", objective = "Trouvez quelqu’un capable de saisir le pouvoir du cœur chromatique.", description = "Le cœur du jadis redoutable Chromaggus repose entre vos mains. Ses teintes polychromes sont aussi exquises que grotesques. Vous sentez un grand pouvoir résidant dans ce cœur, quelque chose qui dépasse votre compréhension. Pour en savoir plus, il vous faudra l’aide d’un être bien plus puissant et ancien que vous.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85505] = {title = "Âme de dévoreur", objective = "Trouvez les mages près du lac de Noirbois et demandez-leur de vous lancer des sorts jusqu’à ce que le gangrechien apparaisse.", description = "Cette âme devrait être intéressante. Pendant votre absence, j’ai entendu dire qu’un gangrechien errant s’en prenait à des mages près du lac de Noirbois. Prenez ce fragment d’âme spécial. Il devrait amplifier les effets de la magie arcanique lancée sur vous. Ce molosse n’y résistera pas.", progress = nil, completion = nil, rewards = nil},
[85506] = {title = "Une dernière épreuve", objective = "Obtenez l’âme de Des’Altek dans le canyon de la Malechute et utilisez-la pour finir de restaurer la faux.", description = "Je devrais maintenant vous révéler mon véritable dessein, <nom>. Je crois que cette faux peut aider à mettre un terme à Des’Altek une fois pour toutes. Retrouvez-moi au canyon de la Malechute, à Ashenvale, pour que nous puissions l’utiliser comme la toute dernière âme nécessaire pour redonner à la faux toute sa puissance.", progress = nil, completion = nil, rewards = nil},
[85507] = {title = "Notre ami vagabond", objective = "Trouvez Aeonas près de la colline des Chagrins dans les Maleterres de l’Ouest.", description = "Je me réjouis de votre présence ici, <nom>. Nous avons appris qu’un voyageur correspondant à la description de notre ami Aeonas a été vu près du camp du Noroît, en direction de la colline des Chagrins.\n\nSuite aux évènements de Gangrebois, je souhaitais lui laisser un peu de liberté, mais certains membres de l’ordre se méfient encore de lui… Tôt ou tard, il va falloir qu’il vienne expliquer pourquoi il a caché son implication prolongée avec un agent connu du roi-liche. Trouvez-le, et voyez si vous pouvez le convaincre de se confier à vous.", progress = nil, completion = "Je me doutais bien que vous reviendriez tôt ou tard. Je suis désolé de vous décevoir, mais le temps n’est pas encore venu pour moi de rentrer. C’est la meilleure prérogative au fait d’être un « ancien » membre de la Main d’argent : je ne réponds plus à personne dans l’Ordre.\n\nUn jour, je reviendrai, oui. En attendant, veuillez dire à Katherine que j’ai pris acte de sa demande, mais que je ne suis pas encore prêt.", rewards = nil},
[85521] = {title = "Poursuivre le trappeur", objective = "Trouvez le camp abandonné à l’ouest des steppes Ardentes, au sud de la route menant à l’Autel des Tempêtes, et examinez la zone.", description = "La note que vous avez trouvée semble être une quittance pour les pièges de suppression qui entourent le repaire du seigneur des couvées Lanistaire. La note indique que s’il a besoin d’autres pièges de suppression, il peut les acheter au camp du vendeur, près de la partie ouest des steppes Ardentes, juste au sud de la route menant à l’Autel des Tempêtes. La note indique également que le vendeur risque de déménager bientôt, et que le seigneur doit donc se dépêcher s’il veut d’autres pièges.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85556] = {title = "Des compétences très particulières", objective = "Trouvez un moyen d’entrer dans le repaire de l’Aile noire et de parler au maître élémentaire Krixix le Sculpteur sans engager le combat avec lui.", description = "Krixix est un vrai génie, mais je doute qu’il apprécie de vous voir débarquer de but en blanc pour exiger son aide… sans parler de tous les malabars qui traînent au mont Rochenoire. Je vous conseille de le rejoindre discrètement, sans faire de vagues, mais ça risque de ne pas être facile.\n\nSi vous trouvez un moyen d’entrer sans poignarder, électrocuter ou brûler qui que ce soit, ça sera déjà un bon début. Je ne sais pas du tout comment vous pourriez faire pour y arriver, mais bonne chance quand même !", progress = nil, completion = nil, rewards = nil},
[85558] = {title = "Engagement qualité", objective = "Regardez le maître élémentaire Krixix le Sculpteur vous fabriquer votre objet.", description = "J’ai réfléchi à ce que je pourrais faire avec ce morceau de métal, et je crois que j’ai trouvé le truc idéal. Donnez-moi quelques minutes que je vous prépare ça.", progress = nil, completion = "La voilà. Canon, pas vrai ? Ne vous fiez pas au temps que ça m’a pris pour la fabriquer. J’ai tellement de talent que tout a l’air facile avec moi. Mais je vous assure que c’est un chef-d’œuvre.\n\nC’est peut-être même ma plus belle pièce en date. Bien sûr, c’est vrai pour toutes mes créations. Bon, c’était divertissant, mais je dois me remettre au travail. À la revoyure.", rewards = "Vous recevrez :\n\nTerrestris"},
[85595] = {title = "La présence de la puissance", objective = "Zanza peut créer les anciens enchantements des Trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les tas d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRapportez-moi ces choses, et je vous façonnerai un enchantement puissant !", description = nil, progress = "Zanza peut créer les anciens enchantements des Trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les tas d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRapportez-moi ces choses, et je vous façonnerai un enchantement puissant !", completion = "Utilisez-le à bon escient, &lt;classe&gt;. Ne faites preuve d’aucune pitié envers les Hakkari !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPrésence de la puissancePrésence de la vaillance"},
