[85598] = {title = "L’aura prophétique", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAura prophétiqueMalédiction prophétique"},
[85599] = {title = "Le maléfice porte-guigne", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nMaléfice porte-guigneMalédiction vaudou"},
