[85602] = {title = "La caresse de l’animiste", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nFureur de l’animisteRugissement de l’animisteÉquilibre de l’animisteCaresse de l’animiste"},
[85603] = {title = "L’étreinte vigilante du vaudouisan", objective = "Zanza peut créer les anciens enchantements des Trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les tas d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRapportez-moi ces choses, et je vous façonnerai un enchantement puissant !", description = nil, progress = "Zanza peut créer les anciens enchantements des Trolls s’il dispose des composants appropriés.\n\nLe premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants hakkari : Jin’do et le Seigneur sanglant.\n\nLe second est une poupée vaudou percée. On peut en trouver dans les tas d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.\n\nRapportez-moi ces choses, et je vous façonnerai un enchantement puissant !", completion = "Utilisez-le à bon escient, &lt;classe&gt;. Ne faites preuve d’aucune pitié envers les Hakkari !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCaresse du vaudouisanVigilance du vaudouisanLinceul du vaudouisanCharme du vaudouisan"},
[85605] = {title = "Parangons de puissance : les brassards d’augure", objective = "Rapportez des brachiales primordiales hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les augures de notre tribu sont révérés pour leur don de seconde vue. Ce ne sont pas des féticheurs qui passent leur temps à lancer des os ou à lire des feuilles pour comprendre le monde… et ils ne lancent pas de maléfices à tort et à travers, eux. Vous êtes <chaman/chamane>, vous connaissez déjà une partie des pouvoirs de l’augure. Nous autres, Zandalar, estimons la sagesse que les augures apportent à la tribu.\n\nFaites-moi offrande d’un des parangons de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai des brassards que nos augures apprécient par-dessus tout !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrassards d’augure zandalar"},
[85606] = {title = "Parangons de puissance : la ceinture d’augure", objective = "Rapportez un ceinturon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les augures connaissent le mojo des éléments. Ils s’en servent pour guider la tribu vers la gloire. Dans les jours sombres qui ont suivi l’éclatement de l’empire Gurubashi, nos augures nous ont conduits à l’abri dans les mers du Sud. Et puis ils nous ont ramenés ici, dans la vallée, tout près du mal qui grandit au cœur de Zul’Gurub.\n\nFaites-moi offrande d’un des parangons de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai une ceinture d’augure contenant un puissant mojo !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinture d’augure zandalar"},
[85607] = {title = "Parangons de puissance : le haubert d’augure", objective = "Rapportez un tabard primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Tous les augures des Zandalar portent une pièce d’amure caractéristique, un haubert. Il est orné des plus belles soieries imaginables, mais il est fait de solides chaînes. C’est un symbole de leur contact avec le divin… et de leur autorité. Il n’est jamais sage de contrarier ceux qui ont voué leur vie au contact avec les esprits…\n\nRapportez-moi en offrande un des parangons de puissance de Zul’Gurub, et prouvez-nous votre valeur. Si vous y parvenez, je vous donnerai l’un de nos plus beaux hauberts, digne des plus grands augures !", progress = nil, completion = "Je sais ce que vous avez dû traverser pour me rapporter ce parangon de puissance, &lt;nom&gt;. Vaincre le mal qui suinte de Zul’Gurub comme le pus d’une blessure infectée n’a pas été facile, mais maintenant que tout est fait et dit, vous serez révérée parmi les Zandalar pendant des siècles et des siècles !\n\nPrenez ce haubert d’augure, et portez-le avec fierté !", rewards = "Vous recevrez :\n\nHaubert d’augure zandalar"},
[85609] = {title = "Parangons de puissance : les brassards d’haruspice", objective = "Rapportez un étançon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nMaywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "L’haruspice est un membre très important de notre tribu, vous avez tout intérêt à écouter ses divinations. Par sa communion avec les animaux, et en les sacrifiant aux esprits lorsque c’est nécessaire, il nous fait profiter des conseils des dieux. Au temps jadis, la sagesse des haruspices nous a donné l’avantage dans la lutte sauvage que nous avons dû soutenir contre les tribus divisées des Gurubashi.\n\nPour prouver votre valeur à nos yeux, apportez-moi en offrande un des parangons de puissance qui se trouvent dans Zul’Gurub. Si vous y parvenez, je vous donnerai des brassards qui feraient envie à tous les haruspices des Zandalar.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrassards d’haruspice zandalar"},
[85610] = {title = "Parangons de puissance : la ceinture d’haruspice", objective = "Rapportez une écharpe primordiale hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Honorer (au minimum).", description = "Nous autres, Zandalar, ignorons les voies des druides. La nature doit se plier à nos besoins, et non l’inverse. Malgré tout, l’haruspice est sans doute celui de nous qui est le plus proche des voies de la nature, et pour d’excellentes raisons. Offrir le fantôme d’une bête, c’est aussi se mettre dans sa peau… Tel est le pouvoir de la nature.\n\nPour prouver votre valeur à nos yeux, apportez-moi en offrande un des parangons de puissance de Zul’Gurub. Si vous y parvenez, je vous donnerai un objet de grand pouvoir, une ceinture comme celles que portent beaucoup de nos haruspices.\n\nBeaucoup de mojo, oh oui !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinture d’haruspice zandalar"},
[85611] = {title = "Parangons de puissance : la tunique d’haruspice", objective = "Rapportez un tabard primordial hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Révérer (au minimum).", description = "L’ultime symbole de la puissance d’un haruspice réside dans sa vêture, <nom>. Sa tunique symbolise le lien entre sa personne et la sagesse divine qu’il recherche. Il y ajoute souvent des morceaux d’animaux qu’il a sacrifiés, en souvenir du lien qu’il a entretenu avec leurs dons.\n\nPour prouver votre valeur à nos yeux, apportez-moi en offrande un des parangons de puissance qui se trouve dans Zul’Gurub. Si vous y parvenez, une tunique forte de la véritable puissance des haruspices sera vôtre.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique d’haruspice zandalar"},
[85612] = {title = "La rage de Mugamba", objective = "Le roi Rastakhan vous transmet ses meilleures salutations, maître <nom>. Un tel honneur n’a encore jamais été accordé à une personne étrangère à la tribu Zandalar.\n\n\n\nDonnez-moi votre talisman pour que je puisse l’améliorer une nouvelle fois. Sachez que la Rage de Mugamba est maintenant intrinsèquement liée à votre âme.", description = nil, progress = "Le roi Rastakhan vous transmet ses meilleures salutations, maître <nom>. Un tel honneur n’a encore jamais été accordé à une personne étrangère à la tribu Zandalar.\n\n\n\nDonnez-moi votre talisman pour que je puisse l’améliorer une nouvelle fois. Sachez que la Rage de Mugamba est maintenant intrinsèquement liée à votre âme.", completion = "Zul’jin envierait vos exploits, &lt;classe&gt;. Partez à la conquête de vos ennemis !", rewards = "Vous recevrez :\n\nRage de Mugamba"},
[85613] = {title = "Parangons de puissance : les garde-bras de redresseur de torts", objective = "Rapportez des brachiales primordiales hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "La vengeance est une force. Les redresseurs de torts zandalar utilisent cette force. La tribu a beaucoup d’ennemis. Le redresseur de torts les châtie. Aucun crime commis contre nous ne reste impuni, car ils veillent au châtiment. Nos ennemis craignent notre vengeance. Ils ont raison. Ils la craindront à jamais.\n\nDevenez l’un de nos redresseurs de torts. Cherchez un parangon de puissance dans Zul’Gurub. Tuez les séides d’Hakkar et accomplissez la vengeance de la tribu. Vous serez <récompensé/récompensée>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGarde-bras de redresseur de torts zandalar"},
[85614] = {title = "Parangons de puissance : la ceinture de redresseur de torts", objective = "Rapportez un ceinturon primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "L’ultime vengeance attend à l’intérieur de Zul’Gurub. Hakkar ne doit pas revenir. Hakkar a détruit l’empire Gurubashi de l’intérieur. Aucun sacrifice n’était suffisant. Les Trolls ne sont plus que l’ombre de leur gloire passée. Je sais que c’est la faute d’Hakkar.\n\nVotre destin est de redresser les torts. Accomplissez-le. Détruisez les séides des ténèbres. Zul’Gurub doit goûter à la vengeance des Zandalar. Rapportez-moi une preuve de vos actions, un parangon de puissance. En échange, vous recevrez la ceinture de redresseur de torts. Vous recevrez la vraie puissance.\n\nAllez.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinture de redresseur de torts zandalar"},
[85615] = {title = "Parangons de puissance : la cuirasse de redresseur de torts", objective = "Rapportez une casaque primordiale hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le symbole de la puissance du redresseur de torts est sa cuirasse, forgée d’un puissant mojo. Elle n’est remise qu’à ceux que nous révérons. C’est le symbole de la vengeance des Zandalar.\n\nDevenir un redresseur de torts, c’est ne plus faire qu’un avec la vengeance. Prenez le parangon de puissance dont nous avons besoin à Zul’Gurub. Rapportez-le-nous. Nous reprendrons le mojo qui nous a été dérobé. Nous ferons payer les séides d’Hakkar. Et nous vous récompenserons avec la cuirasse de redresseur de torts.\n\nAllez. Soyez notre vengeance, <nom>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCuirasse de redresseur de torts zandalar"},
[85617] = {title = "La marque du héros", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMarque de héros"},
[85618] = {title = "Parangons de puissance : les garde-bras de libre-penseur", objective = "Rapportez des manchettes primordiales hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Vous êtes <un incroyant/une incroyante>. Les gens comment vous ont une place au sein de la tribu. Ce sont les libres-penseurs des Zandalar. Les libres-penseurs ne craignent pas l’oppression. Les libres-penseurs meurent pour leurs opinions. Nous savons que vous êtes <prêt/prête> à mourir pour vos opinions. Pour cela, nous vous saluons. Pour cela, nous vous donnons une chance de faire vos preuves.\n\nIl nous faut les parangons de puissance. Allez à Zul’Gurub. Tuez les séides d’Hakkar. Revenez lorsque vous aurez ce que je recherche. Par vos actes, vous recevrez la première pièce d’armure d’un libre-penseur zandalar.\n\nAllez.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nGarde-bras de libre-penseur zandalar"},
[85619] = {title = "Parangons de puissance : la ceinture de libre-penseur", objective = "Rapportez un châle primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Vos croyances nous sont étrangères, <incroyant/incroyante>. Autrefois, au temps de la puissance de l’empire Gurubashi, des Zandalar furent qualifiés d’hérétiques. Ces incroyants osèrent défier les prêtres d’Hakkar. Ils furent traqués et exterminés comme de la vermine. Mais ils n’ont jamais faibli, ni renoncé à se battre contre le Dieu sanglant. Nous honorons le prix qu’ils ont payé. Ils étaient les libres-penseurs.\n\nDétruisez les séides d’Hakkar à Zul’Gurub. Rapportez-moi le parangon de puissance que je recherche. Votre succès sera généreusement récompensé.\n\nAllez.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinture de libre-penseur zandalar"},
[85620] = {title = "Parangons de puissance : la cuirasse de libre-penseur", objective = "Rapportez un tabard primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nJin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les armes et les armures donnent du pouvoir au sein de la tribu. Les libres-penseurs sont honorés pour cela. Ce sont des zélotes. Ils imprègnent leurs cuirasses d’un mojo puissant. Lorsque leur foi vient à faiblir face à l’adversaire, il leur reste toujours leur cuirasse.\n\nVous devez être <révéré/révérée> parmi nous pour posséder une telle cuirasse. Allez à Zul’Gurub. Prenez le parangon de puissance dont j’ai besoin, sans oublier de faire souffrir son imbécile de propriétaire. Rapportez-le-moi. Prouvez votre valeur comme libre-penseur, une fois pour toutes.", progress = "Avez-vous le parangon ? Il contient du mojo. Il nous le faut. Vous nous aiderez.", completion = "Bien peu de gens ont accompli ce que vous avez réussi. Vous avez mis les séides d’Hakkar à genoux. Vous leur avez montré ce que pouvait faire un libre-penseur. Vous nous avez montré qu’une hérétique pouvait être révérée dans la tribu. La puissance n’est pas vôtre, vous ÊTES la puissance.\n\nPrenez cette cuirasse, libre-penseur. Écrasez vos adversaires.", rewards = "Vous recevrez :\n\nCuirasse de libre-penseur zandalar"},
[85622] = {title = "Parangons de puissance : les couvre-bras de confesseur", objective = "Rapportez un étançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Nous autres Zandalar donnons du pouvoir à ceux dont la voix résonne de l’autorité des dieux. Nos prêtres ne sont pas seulement des guérisseurs, ce sont aussi des confesseurs. Le mal rôde à l’extérieur, comme le montre la menace d’Hakkar, mais il vient aussi de l’intérieur. Nos confesseurs sont nos juges, chargés de nous préserver du mal qui a dévoré les Gurubashi de l’intérieur.\n\nRendez-vous à Zul’Gurub et rapportez-en un parangon de puissance des Gurubashi. Apprenez ce que cela signifie d’être le confesseur, et protégez-nous du mal.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouvre-bras de confesseur zandalar"},
[85623] = {title = "Parangons de puissance : le cordon de confesseur", objective = "Rapportez une écharpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Peu après la chute des Gurubashi, nous autres Zandalar avons failli succomber, dévorés de l’intérieur par le mal. L’ascension des confesseurs date de ce temps-là. Ils ont préservé la tribu en chassant ceux qui étaient prêts à détruire leurs propres frères. Non seulement ils préservent notre lien avec les esprits, mais ils sauvent notre chair.\n\nAllez à Zul’Gurub. Témoignez de la dépravation d’Hakkar et des Gurubashi. Arrachez-leur le parangon de puissance dont nous avons besoin. Comme de juste, vous serez <récompensé/récompensée>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nLien de confesseur zandalar"},
[85624] = {title = "Parangons de puissance : le mantelet de confesseur", objective = "Rapportez une égide primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Les confesseurs des Zandalar portent tous un mantelet caractéristique, qui indique qu’ils préservent la tribu. Ils sont tissés de puissant mojo qui les aide à juger ceux qui risquent de la menacer. En tant que <prêtre/prêtresse>, vous devez aussi souvent séparer les dignes des indignes. Un tel mantelet vous serait certainement utile.\n\nSi vous combattez les séides d’Hakkar à Zul’Gurub et que vous me rapportez le parangon de puissance dont j’ai besoin, je vous remettrai un mantelet digne de nos meilleurs confesseurs.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet de confesseur zandalar"},
[85626] = {title = "Parangons de puissance : les couvre-bras de démoniaque", objective = "Rapportez un étançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Lorsqu’ils négocient avec les démons, les démonistes s’aventurent sur un terrain dangereux, mais nos démoniaques poussent le processus encore plus loin. Grâce à un ancien rituel des arcanes, ils permettent à un démon d’entrer dans leur corps. Mais ils ne sont pas possédés : ils réduisent le démon en esclave de l’intérieur, absorbant le pouvoir de la bête pour leurs propres fins. C’est un exploit que bien peu sont capables d’accomplir.\n\nSi vous voulez apprendre le pouvoir des démoniaques, il me faut un parangon de puissance de Zul’Gurub. Allez-y, et rapportez-moi ce que je cherche.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouvre-bras de démoniaque zandalar"},
[85627] = {title = "Parangons de puissance : le mantelet de démoniaque", objective = "Rapportez une écharpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le démoniaque cherche à incarner la puissance, pas seulement à la posséder. Nombre d’entre eux finissent par être vaincus par un démon. Menacés comme nous le sommes par nos ennemis, surtout à Zul’Gurub, la puissance qu’un démoniaque est capable de déchaîner compense largement leur sacrifice. Si nous voulons survivre, nous devons écraser ceux qui cherchent à nous détruire. C’est la grande leçon que nous a apprise la chute de l’empire des Gurubashi.\n\nRendez-vous à Zul’Gurub et récupérez le parangon de puissance qu’il nous faut. Si vous y parvenez, nous vous donnerons un outil de grande valeur appartenant à un démoniaque.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet de démoniaque zandalar"},
[85628] = {title = "Parangons de puissance : la robe de démoniaque", objective = "Rapportez une casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Le principal symbole du pouvoir au sein de la tribu reste la tenue que nous portons au combat. Les robes d’un démoniaque entremêlent de l’étoffe runique et un mojo d’une puissance dévastatrice. Le visage qui les orne est censé instiller la peur dans l’esprit de ceux qui les contemplent… et surtout des démons que le démoniaque doit mater.\n\nVous devez me rapporter un parangon de puissance très particulier de Zul’Gurub. Ce sera difficile… mais si vous réussissez, vous aurez l’une de ces robes.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe de démoniaque zandalar"},
[85630] = {title = "Parangons de puissance : les couvre-bras d’illusionniste", objective = "Rapportez des manchettes primordiales hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Dans notre tribu, les mages sont appelés « illusionnistes ». Leurs incantations emploient des mojos puissants, semant la confusion et le trouble parmi les ennemis de la tribu.\n\n<Al’tabim éclate d’un rire mauvais.>\n\nQuel beau spectacle que celui d’un illusionniste au travail, mettant ses ennemis à genoux en les engloutissant sous leur propre folie !\n\nPour apprendre la voie de l’illusionniste, rendez-vous à Zul’Gurub et rapportez-moi un parangon de puissance. Si vous y parvenez, je vous donnerai les couvre-bras dont nos illusionnistes se servent pour tisser leurs sorts.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCouvre-bras d’illusionniste zandalar"},
[85631] = {title = "Parangons de puissance : le mantelet d’illusionniste", objective = "Rapportez un châle primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "La magie est une force brute, primitive, que seuls les plus forts peuvent modeler. Le mojo est une extension de notre pouvoir, et l’un de ses emplois les plus puissants est l’illusion. Comment peut-on vaincre un ennemi qui n’est pas réellement là ? Nous, les Zandalar, nous apprécions ce pouvoir, et les illusionnistes ont une place d’honneur au sein de la tribu.\n\nPrenez le parangon de puissance dont nous avons besoin à Zul’Gurub. Si vous y parvenez, vous serez <honoré/honorée> par la tribu, et nous vous remettrons un mantelet puissant, utilisé par nos meilleurs illusionnistes !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet d’illusionniste zandalar"},
[85632] = {title = "Parangons de puissance : la robe d’illusionniste", objective = "Rapportez une casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nAl’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Notre puissance et notre rang au sein de la tribu sont indiqués par ce que nous portons. Nos tenues sont faites à partir des matériaux les plus fins, et imprégnées du mojo dont nous nous servons pour devenir puissants. Les illusionnistes ne font pas exception. À ce que l’on dit, leurs robes matérialisent l’essence de l’illusion. D’après les légendes, les robes les plus anciennes n’ont jamais deux fois la même apparence.\n\nJe vous donnerai une robe d’illusionniste, <nom>… mais vous devez d’abord mériter que la tribu vous révère ! Rapportez-moi un parangon de puissance de Zul’Gurub !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRobe d’illusionniste zandalar"},
[85634] = {title = "Parangons de puissance : les brassards d’insensé", objective = "Rapportez des brachiales primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Nos insensés ressemblent aux voleurs, mais avant toutes choses, ils savourent la folie… le chaos… l’imprévisibilité de l’existence. Sur le champ de bataille, ils sont terrifiants. Aux temps sauvages, lorsque les tribus se sont divisées, ils ont semé les graines de la confusion et de la démence parmi nos ennemis. Sans eux, nous ne serions pas là aujourd’hui.\n\nRapportez-moi le parangon de puissance de Zul’Gurub que je recherche, et je vous remettrai la première pièce d’une précieuse armure d’insensé. Plongez dans la folie !", progress = "Cherchez la folie à l’intérieur de Zul’Gurub et noyez-la sous la vôtre, <nom> ! Si vous y arrivez, vous réussirez, et la réussite entraîne une récompense ! Empêchez le Dieu sanglant de triompher à nouveau !", completion = "Bien joué, &lt;nom&gt;… grâce à vos exploits à Zul’Gurub, vous avez obtenu le droit de considérer les Zandalar comme des amis. Je veillerai à ce que le parangon soit bien utilisé. Quant à vous, acceptez cette récompense !", rewards = "Vous recevrez :\n\nBrassards d’insensé zandalar"},
[85635] = {title = "Parangons de puissance : le mantelet d’insensé", objective = "Rapportez un ceinturon primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Khar’vaxal le Fêlé fut l’un des insensés les plus fameux qu’aient comptés les Zandalar. D’après la légende, lorsqu’il a affronté les ennemis de la tribu pour la première fois, Khar’vaxal s’est servi d’un mantelet tissé dans « l’étoffe de la folie ». Celui-ci dissimulait sa forme, mais aussi l’éclat de ses dagues jumelles. Les insensés d’aujourd’hui chérissent leurs mantelets comme signe de leur place dans la tribu.\n\nRapportez-moi le parangon de puissance que je recherche, et vous aurez l’un de ces mantelets. Ainsi, vous pourrez tisser la démence de vos ennemis.", progress = "Vous êtes de retour. Avez-vous le parangon de puissance dont j’ai besoin ?\n\nLa légende de Khar’vaxal le Fêlé nous rappelle qu’aucun ennemi, si puissant soit-il, n’est invincible. Le chaos finit par mettre tout le monde à genoux, c’est une certitude… et peut-être est-ce aussi le cas des éléments les moins chaotiques du chaos.", completion = "La victoire est à nous, grâce à la folie que vous avez semée parmi nos ennemis mutuels ! Vous serez honorée parmi les Zandalar, et il n’existe pas de meilleur moyen de vous montrer notre gratitude que de vous offrir le mantelet de l’insensé !", rewards = "Vous recevrez :\n\nMantelet d’insensé zandalar"},
[85636] = {title = "Parangons de puissance : la tunique d’insensé", objective = "Rapportez une égide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Mes yeux m’ont abandonné il y a bien longtemps, mais je ne les regrette pas. Même dans une tribu comme la nôtre, où les vêtements symbolisent le rang et la vocation, les tenues les plus puissantes irradient un pouvoir que l’œil nu ne peut pas voir. La précieuse tunique des insensés zandalar ne fait pas exception, car il en émane la puissance brute du chaos et de la démence qu’ils contrôlent.\n\nLe parangon de puissance dont j’ai besoin se trouve à Zul’Gurub. Rapportez-le-moi, et je vous donnerai l’une de ces tuniques légendaires, dignes d’un artisan de la folie.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nTunique d’insensé zandalar"},
[85638] = {title = "Parangons de puissance : les brassards de prédateur", objective = "Rapportez des manchettes primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Dans les jours sombres qui ont suivi la chute de l’empire Gurubashi, les prédateurs zandalar ont utilisé leurs pouvoirs pour nourrir la tribu. Les chasseurs prétendent qu’ils ressemblent à nos prédateurs, et il est vrai que la chasse est ce qui définit l’essence des prédateurs. Votre chasse dans Zul’Gurub nous montrera si vous figurez vraiment parmi les plus grands prédateurs.\n\nRapportez-moi un parangon de puissance de Zul’Gurub. Si vous y parvenez, vous ferez vos premiers pas sur la route qui fera de vous <un redoutable prédateur/une redoutable prédatrice>.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBrassards de prédateur zandalar"},
[85639] = {title = "Parangons de puissance : la ceinture de prédateur", objective = "Rapportez un châle primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Un prédateur sait traquer ses proies, mais un prédateur avisé sait aussi comment les frapper alors même qu’elles sont rassemblées. Vous devez maîtriser ces deux arts si vous voulez réussir à Zul’Gurub… et si vous voulez ressembler aux prédateurs des Zandalar.\n\nRapportez-moi un parangon de puissance de Zul’Gurub. Ma récompense sera la puissance contenue dans cet objet, et la vôtre sera une ceinture de prédateur zandalar. Croyez-moi, c’est un marché équitable.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nCeinture de prédateur zandalar"},
[85640] = {title = "Parangons de puissance : le mantelet de prédateur", objective = "Rapportez une égide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum).\n\nFalthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.", description = "Chez les Zandalar, les tenues sont le symbole des succès remportés. Malgré cela, vous n’avez pas besoin de voir ce que porte une personne pour sentir le pouvoir qui émane d’elle. Le pouvoir transcende la vision. Les vêtements de nos prédateurs sont ainsi, et le plus apprécié est leur mantelet. Il aide à les dissimuler… et à les rendre visibles lorsqu’ils le souhaitent.\n\nLes parangons de puissance attendent d’être sauvés de Zul’Gurub. Rapportez-moi ce que je cherche, et le mantelet de prédateur sera vôtre.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nMantelet de prédateur zandalar"},
[85643] = {title = "Le seigneur de Blackrock", objective = "Allez dans la vallée des Héros de Stormwind et parler au grand maréchal Pont-de-Pierre.", description = "Aller à la vallée des Héros et parler au grand maréchal Pont-de-Pierre.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nMédaillon du Maître-tueur de dragonOrbe du Maître-tueur de dragonBague du Maître-tueur de dragon\n\nVous recevrez également :\n\n"},
[85658] = {title = "Pour que tous voient", objective = "Allez voir le seigneur Runthak dans la vallée de la Force.", description = "Le seigneur Runthak attend votre arrivée dans la vallée de la Force.\n\n<Thrall vous salue.>\n\nNe faites pas attendre votre public, héros.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[85659] = {title = "Célébrer le triomphe", objective = "Allez voir le major Mattingly dans la vallée des Héros.", description = "Allez voir le major Mattingly dans la vallée des Héros, <nom>. Il vous attend.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[85660] = {title = "Le cœur d’Hakkar", objective = "Donnez le Cœur d’Hakkar à Molthor sur l’île de Yojamba.", description = "Le cœur d’Hakkar brûle de l’intérieur. En dépit de la défaite de l’Écorcheur d’âmes, l’essence de sa puissance repose encore dans cet organe maudit.", progress = nil, completion = "Ah, le cœur d’Hakkar. Ainsi, l’Écorcheur d’âmes a été tué ! Notre monde est sauvé !\n\n&lt;nom&gt;, vous nous avez rendu un immense service. En vérité, vous êtes parmi les plus grands héros qui aient jamais vécu !", rewards = nil},
[85699] = {title = "Pierre du serpent de la chasseresse des ombres", objective = "Aller jusqu’au pic Blackrock et abattre la chasseresse des ombres Vosh’gajin. Récupérer la pierre du serpent de Vosh’gajin et la rapporter à Kilram.", description = "Ne laissez pas sa beauté vous duper, <classe>. La chasseresse des ombres Vosh’gajin est extrêmement dangereuse et son esprit est dérangé.\n\n<Kilram désigne la cicatrice qu’il porte au visage.>\n\nOui, c’est elle qui m’en a fait cadeau. Une marque d’amour, pour employer ses termes.\n\nL’heure de la vengeance a enfin sonné.\n\nVous pouvez trouver Vosh’gajin au pic Blackrock. Tuez-la et rapportez-moi sa pierre du serpent. Accomplissez cet exploit, et je vous enseignerai l’art de fabriquer des haches !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant de haches\n\nVous recevrez :\n\nPlans : Courroux de l'aube"},
[85700] = {title = "Corruption", objective = "Trouver le fabricant d’épées de la Garde noire à Stratholme et le tuer. Récupérer l’insigne de la Garde noire et retourner auprès de Seril Plaie-du-Fléau.", description = "Si je ne m’étends pas avec vous, j’ai une bonne raison. Les plans pour la création de la grande lame, Corruption, ont été volés par la Garde noire : des unités squelettes d’élite du baron Vaillefendre.\n\nOui, le baron Vaillefendre de Stratholme.\n\nLe fabricant d’épées de la Garde noire détient à présent ces plans, et il donnerait sa… non-vie pour les protéger.\n\nTuez-le et rapportez-moi la preuve de votre exploit. Je vous enseignerai alors l’art de la fabrication des épées !Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nMaître fabricant d’épées\n\nVous recevrez :\n\nPlans : Rapière flamboyante"},
[85701] = {title = "Travail du cuir d’écailles de dragon", objective = "Apporter 2 cuirasses armées du scorpide, 2 gants armés du scorpide et 10 écailles de dragon usées à Peter Galen en Azshara.\n\nTerminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.\n\nTerminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.", description = "Le travail des écailles de dragons n’est pas chose aisée, mais les récompenses qu’on en retire sont nombreuses. Je vous enseignerai comment fabriquer cette belle cotte de mailles, mais cela seulement si vous acceptez certaines conditions.\n\nTout d’abord, en choisissant cette voie, vous vous engagez à ne jamais apprendre le travail du cuir élémentaire ou le travail du cuir tribal. Vous ne pouvez parvenir à l’excellence que dans un seul domaine. De plus, j’aurai besoin d’échantillons de vos meilleurs ouvrages d’armure de scorpide. Enfin, vous devez me prouver votre capacité à acquérir la matière première de cet art : des écailles de draconiens.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir d'écailles de dragon\n\nVous recevrez :\n\n"},
[85703] = {title = "Travail du cuir élémentaire", objective = "Apporter 2 cœurs de feu, 2 globes d’eau, 2 noyaux de terre et 2 souffles de vent à Sarah Tanner dans la gorge des Vents brûlants.\n\nL’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir d’écailles de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Le travail du cuir élémentaire est mon domaine, et si vous voulez ouvrir votre esprit aux plus grands pouvoirs de l’art, je partagerai avec vous tout ce qu’il y a à savoir.\n\nSachez ceci, <classe> : en prenant cette voie, vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir tribal. Vous ne pouvez atteindre l’excellence que dans un seul de ces trois domaines. De plus, j’aurai besoin de la preuve que vous êtes en relation avec les éléments de la nature. Pour ce faire, apportez-moi les essences les plus pures de feu, d’eau, de terre et de vent.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir élémentaire\n\nVous recevrez :\n\n"},
[85705] = {title = "Travail du cuir tribal", objective = "Apporter un gilet en cuir fauve et un casque en cuir fauve à Caryssia Chasselune en Feralas.\n\nL’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.\n\nL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir d’écailles de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.", description = "Apprendre le travail du cuir tribal nécessite une réelle compréhension de ce qu’est la véritable nature primale. Je sais que vous maîtrisez déjà l’art de la confection d’armures en cuir fauve, et je souhaite poursuivre votre entraînement.\n\nSachez ceci, <classe> : en choisissant de suivre cette voie, vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir élémentaire. Vous ne pouvez vraiment maîtriser qu’une seule des trois disciplines. De plus, apportez-moi les meilleurs exemplaires de vos armures en cuir fauve. À partir de là, nous pourrons poursuivre votre apprentissage.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nTravail du cuir tribal\n\nVous recevrez :\n\n"},
[85712] = {title = "L’art de l’armurier", objective = "Pour apprendre à fabriquer des armures, il vous faut forger les éléments suivants puis les apporter à Okothos : 4 heaumes ornés en mithril, 2 bottes ornées en mithril, 1 cuirasse ornée en mithril.", description = "La satisfaction. C’est ce que je retire du marteau et de l’enclume. Voir un fier guerrier de la Horde protégé par mon acier me rappelle ce que signifie être vivant. C’est un besoin dont j’espère ne jamais avoir à me passer, <nom>.\n\nJe ne peux pas vous octroyer cette satisfaction, mais simplement vous placer sur son chemin. Comme toute tentative dans la vie, le chemin de la fabrique d’armures est un voyage.\n\nSi vous voulez faire partie des rares élus, vous n’avez besoin que de demander et je vous entraînerai. Mais tout d’abord, vous devez accomplir une certaine tâche.Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nArtisan armurier\n\nVous recevrez :\n\n"},
[85713] = {title = "L’art de l’armurier", objective = "Pour apprendre à fabriquer des armures, il vous faut forger les éléments suivants puis les rapporter à Grumnus : 4 heaumes ornés en mithril, 2 bottes ornées en mithril, 1 cuirasse ornée en mithril.", description = "Ainsi vous avez pris la bonne décision.\n\nOn ne s’apprécie guère ici, moi et ce vieux Ferronus. Ce bon à rien de fabricant de jouets sait parfaitement qui sont les véritables artisans de valeur en ces contrées.\n\nLes guerres véritablement grandes sont gagnées avec une bonne défense. Quand c’est l’heure d’y aller, aucune arme ne vous fera de cadeau dans la bataille.\n\nMais passons, et mettons-nous au travail. Tout ce que vous avez à faire est de me montrer que vous avez le talent de base nécessaire. Après, j’aplatirai vos imperfections et vous mettrai dans le moule de la fabrique d’armures. Vous savez comment faire du mithril orné, pas vrai ?Vous allez être la cible du sort suivant :\n\n", progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nArtisan armurier\n\nVous recevrez :\n\n"},
[85798] = {title = "Des armes pour le champ de bataille", objective = "Apportez 2 Épées d’acier lunaire à Janela Stouthammer, à l’avant-poste de la brigade d’Ironforge, aux abords de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VI pour terminer cette quête.", description = "La brigade d’Ironforge a joué un grand rôle dans nos combats en Silithus. Malheureusement, une bonne partie de son matériel s’est égarée au cours du transport. Procurez-vous des armes et livrez-les à Janela Stouthammer, près de la Ruche’Zora.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nBadge cénarien de logistiqueAffectation logistique complémentaire"},
[85882] = {title = "La fin de la Horde sombre", objective = "Apportez la tête de Rend Blackhand à maître Mathias Shaw à Stormwind.", description = "Mission accomplie. Le corps sans vie de Dal’rend Blackhand, chef de guerre de la Horde sombre, gît à vos pieds. Prenez sa tête et présentez-la à maître Shaw.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85883] = {title = "Pour la Horde !", objective = "Aller au Pic Blackrock et tuer le chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar.", description = "Rend ose prononcer de telles revendications parce qu’il se sait sous la protection des dragons noirs.\n\nVous, <nom>, trouverez un moyen de traverser les Halls de l’Ascension. Après, vous trouverez le « chef de guerre » Rend Blackhand et vous le détruirez, POUR LA HORDE !\n\n<Thrall abat son poing sur le trône.>\n\nLa prochaine fois que vous viendrez dans mon domaine, vous porterez sa tête comme trophée et la présenterez à votre chef de guerre. Faites cela, et vous recevrez les honneurs héroïques de la Horde.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[85963] = {title = "Une chevalière de mérite", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85964] = {title = "Dix chevalières de mérite", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85965] = {title = "Une chevalière de mérite", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85966] = {title = "Dix chevalières de mérite", objective = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus de l’Aube d’argent. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prête à m’en remettre une série.", description = nil, progress = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus de l’Aube d’argent. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prête à m’en remettre une série.", completion = "Excellent ! Vous avez fait d’énormes sacrifices pour obtenir ces chevalières. Il est juste que vos services soient reconnus. Ce sont des aventurières comme vous, &lt;nom&gt;, qui font la différence.\n\nDites-moi si vous avez d’autres chevalières à remettre. Vous aider à nouveau sera un honneur.", rewards = nil},
[85967] = {title = "Dix chevalières de mérite", objective = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus du Cercle cénarien. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prêt à m’en remettre une série.", description = nil, progress = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus du Cercle cénarien. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prêt à m’en remettre une série.", completion = "Excellent ! Vous avez fait d’énormes sacrifices pour obtenir ces chevalières. Il est juste que vos services soient reconnus. Ce sont des aventuriers comme vous, &lt;nom&gt;, qui font la différence.\n\nDites-moi si vous avez d’autres chevalières à remettre. Vous aider à nouveau sera un honneur.", rewards = nil},
[85968] = {title = "Une chevalière de mérite", objective = "Les aventuriers et aventurières qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part du Cercle cénarien.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons l’échange de chevalière à l’unité comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", description = nil, progress = "Les aventuriers et aventurières qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part du Cercle cénarien.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons l’échange de chevalière à l’unité comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", completion = "Très bien, vos actes ont été consignés dans nos archives, et vos efforts seront dûment reconnus. Continuez ainsi, &lt;classe&gt;.\n\nSi vous avez d’autres chevalières à remettre, je pourrai vous aider. Vous savez où me trouver.", rewards = nil},
[85969] = {title = "Dix chevalières de mérite", objective = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus du Cercle cénarien. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prêt à m’en remettre une série.", description = nil, progress = "Je récupère les chevalières de mérite que les aventuriers et aventurières reçoivent lorsqu’ils font leur devoir. Pour chaque série de dix chevalières que vous me remettez, je veille à ce que vos exploits soient connus du Cercle cénarien. J’accepte aussi les chevalières à l’unité, même si cela est beaucoup moins rentable. Nous n’ignorons aucun exploit, mais les plus impressionnants sont mieux appréciés.\n\nCeci posé, je prendrai volontiers vos chevalières, si vous êtes prêt à m’en remettre une série.", completion = "Excellent ! Vous avez fait d’énormes sacrifices pour obtenir ces chevalières. Il est juste que vos services soient reconnus. Ce sont des aventuriers comme vous, &lt;nom&gt;, qui font la différence.\n\nDites-moi si vous avez d’autres chevalières à remettre. Vous aider à nouveau sera un honneur.", rewards = nil},
[85970] = {title = "Une chevalière de mérite", objective = "Les aventuriers et aventurières qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part du Cercle cénarien.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons l’échange de chevalière à l’unité comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", description = nil, progress = "Les aventuriers et aventurières qui n’ont qu’une seule chevalière de mérite ne recevront qu’une reconnaissance minime de la part du Cercle cénarien.\n\nN’oubliez pas qu’il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons l’échange de chevalière à l’unité comme un service pour ceux qui n’ont pas une pile de dix.\n\nCeci posé, je suis en mesure de vous aider si vous souhaitez me remettre une seule chevalière.", completion = "Très bien, vos actes ont été consignés dans nos archives, et vos efforts seront dûment reconnus. Continuez ainsi, &lt;classe&gt;.\n\nSi vous avez d’autres chevalières à remettre, je pourrai vous aider. Vous savez où me trouver.", rewards = nil},
