[87439] = {title = "Gants en étoffe de l’Aube d’argent", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de purification des morts-vivantsGants de purification des morts-vivantsGants de protection contre les morts-vivants"},
[87440] = {title = "Gants en étoffe de l’Aube d’argent", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nGants de purification des morts-vivantsGants de purification des morts-vivantsGants de protection contre les morts-vivants"},
[87441] = {title = "Atiesh, le grand bâton du Gardien", objective = "Anachronos, aux grottes du Temps en Tanaris, veut que vous emportiez Atiesh, le grand bâton du Gardien, à Stratholme et que vous le placiez sur la terre consacrée. Abattez l’entité qui sera extraite du bâton et retournez le voir.", description = "Cette dernière besogne sera la plus difficile de toutes, <nom>. Vous avez déjà affronté et vaincu un Dieu très ancien et le général du roi-liche, mais vous devez maintenant faire face à la main de Sargeras.\n\nApportez le bâton à Stratholme. C’est là-bas que vous trouverez une étendue de terre consacrée : le sol sur lequel les plus grands chevaliers du Lordaeron ont été abattus. Placez le bâton souillé sur le sol sacré et préparez-vous à ce qu’une entité au pouvoir immense s’en échappe… Exécutez l’être démoniaque qui contrôle le bâton, puis revenez me trouver.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAtiesh, grand bâton du Gardien"},
[87442] = {title = "Atiesh, le grand bâton du Gardien", objective = "Anachronos, aux grottes du Temps en Tanaris, veut que vous emportiez Atiesh, le grand bâton du Gardien, à Stratholme et que vous le placiez sur la terre consacrée. Abattez l’entité qui sera extraite du bâton et retournez le voir.", description = "Cette dernière besogne sera la plus difficile de toutes, <nom>. Vous avez déjà affronté et vaincu un Dieu très ancien et le général du roi-liche, mais vous devez maintenant faire face à la main de Sargeras.\n\nApportez le bâton à Stratholme. C’est là-bas que vous trouverez une étendue de terre consacrée : le sol sur lequel les plus grands chevaliers du Lordaeron ont été abattus. Placez le bâton souillé sur le sol sacré et préparez-vous à ce qu’une entité au pouvoir immense s’en échappe… Exécutez l’être démoniaque qui contrôle le bâton, puis revenez me trouver.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAtiesh, grand bâton du Gardien"},
[87444] = {title = "Atiesh, le grand bâton du Gardien", objective = "Anachronos, aux grottes du Temps en Tanaris, veut que vous emportiez Atiesh, le grand bâton du Gardien, à Stratholme et que vous le placiez sur la terre consacrée. Abattez l’entité qui sera extraite du bâton et retournez le voir.", description = "Cette dernière besogne sera la plus difficile de toutes, <nom>. Vous avez déjà affronté et vaincu un Dieu très ancien et le général du roi-liche, mais vous devez maintenant faire face à la main de Sargeras.\n\nApportez le bâton à Stratholme. C’est là-bas que vous trouverez une étendue de terre consacrée : le sol sur lequel les plus grands chevaliers du Lordaeron ont été abattus. Placez le bâton souillé sur le sol sacré et préparez-vous à ce qu’une entité au pouvoir immense s’en échappe… Exécutez l’être démoniaque qui contrôle le bâton, puis revenez me trouver.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAtiesh, grand bâton du Gardien"},
[87459] = {title = "Activités écarlates", objective = "Rendez-vous dans la région près de l’avant-poste des Croisés, au nord-ouest du Rempart dans les clairières de Tirisfal, et cherchez-y des traces récentes d’activité de la Croisade écarlate. Et rapportez tous les renseignements que vous trouverez à Leonid Barthalomew le Révéré.", description = "Pendant que nous sommes aux petits soins avec la Croisade écarlate, ses membres poursuivent leur comportement étrange ailleurs. Certains de mes contacts à Tirisfal me disent qu’ils ont lancé une incursion au cœur même d’Undercity, et nous avons reçu des rapports disant que de vastes caravanes transportent des provisions dans les Maleterres. Un groupe d’élite de la Croisade écarlate a été repéré près de l’avant-poste des Croisés dans les clairières de Tirisfal, entre la ferme des Balnir et la vallée de Tissevenin. Si vous voulez bien, allez voir ce qui se passe là-bas.", progress = "Comment avance votre mission, <nom> ?", completion = "Je vois. Donc, la Croisade aurait enlevé quelqu’un en ville. Quelqu’un d’important, en plus. C’est inquiétant. Merci, &lt;nom&gt;. Pour le moment, ne faites rien, et n’en parlez à personne. Notre alliance avec la Croisade écarlate est fragile, mais toute aide est la bienvenue dans la lutte qui nous oppose à Naxxramas. \n\nJe vais enquêter de mon côté. Je vous contacterai peut-être à l’avenir pour demander votre aide. En attendant, allez avec la lumière.", rewards = "Vous allez être la cible du sort suivant :\n\nGain d’expérience\n\nVous recevrez :\n\nEau sacrée potable de Stratholme"},
[87493] = {title = "Agitation à la Main de Tyr", objective = "Partez en reconnaissance sur le camp de la Croisade écarlate à l’ouest de la Main de Tyr, dans les Maleterres de l’est, et découvrez ce qui perturbe les troupes de la Croisade écarlate.", description = "Nous avons reçu de nouvelles informations intéressantes, <nom>. Il semblerait qu’alors que la Croisade écarlate s’intéressait à Naxxramas, les rangs de la Main de Tyr ont connu une certaine agitation. Nous n’avons pas tous les détails, mais de ce que nous comprenons, il existe des conflits internes au sein de la Croisade.\n\nJ’aimerais vous envoyer au camp à l’ouest de la Main de Tyr pour évaluer la situation. Faites-nous part de vos trouvailles dès que possible.", progress = nil, completion = "Bonjour, &lt;nom&gt;. Il est… bon de vous revoir. J’aurais aimé que ce soit sous de meilleurs auspices.", rewards = "Vous recevrez :\n\n"},
[87497] = {title = "La scission", objective = "Parlez à Beatrix pour en savoir plus sur le sort de l’enclave Écarlate de la Main de Tyr et faites votre rapport à Leonid Barthalomew le Révéré à la chapelle de l’Espoir de Lumière lorsque vous en saurez davantage.", description = "J’irai droit au but : nous avons perdu le contrôle de l’enclave de la Main de Tyr. Pendant notre excursion à Naxxramas, des membres de la Croisade hostiles ont attaqué de la cité de Stratholme pour s’emparer du bastion. L’entrée est bloquée et nos émissaires n’ont pas réapparu.\n\nJ’aurais préféré ne pas avoir à solliciter une aide extérieure, mais il se trame quelque chose de très grave et nous ne pourrons sans doute pas reprendre l’enclave par nous-mêmes.", progress = nil, completion = "Les nouvelles de la Main de Tyr sont… particulièrement intéressantes. Abbendis est probablement morte, et Balnazzar est de retour. Si une partie de moi ne demande qu’à voir la Croisade écarlate récolter ce qu’elle a semé, je crains que peu importe le dénouement, l’Aube d’argent sera entraînée dans ce conflit. Nos forces ont souffert lors de la campagne de Naxxramas, et le seigneur Tyrosus préférerait avoir le choix dans l’approche, plutôt qu’on nous force la main.\n\nVous… vous avez aussi dit que l’inquisiteur Caldoran était là-bas ?", rewards = "Vous recevrez :\n\n"},
[87498] = {title = "La Reconquête écarlate", objective = "Retournez voir la commandante Beatrix au camp de la Croisade à l’ouest de la Main de Tyr.", description = "<Le visage de Leonid s’assombrit quand vous confirmez la présence de Caldoran au camp de la Croisade. Après un instant, il reprend ses esprits.>\n\nMerci… merci, <nom>. En attendant, continuez d’aider Beatrix, si vous le voulez bien. Je m’entretiendrai avec le seigneur Tyrosus pour mettre au point un plan d’action, si l’Aube d’argent est contrainte de s’impliquer. Je prie pour que la situation ne soit pas si terrible, mais si nous devons intervenir pour y mettre un terme, nous y serons prêts.", progress = nil, completion = "Vous allez donc nous aider ? C’est un véritable soulagement. J’ai été témoin des capacités de vos camarades et vous-même et je suis ravie que vous soyez de notre côté pour cette opération. J’espérais que l’Aube d’argent nous apporte une assistance plus directe, mais je suis tout de même reconnaissante pour votre aide.\n\nParlez à l’inquisiteur Caldoran, sur la colline. Il vous aidera à vous préparer.", rewards = "Vous recevrez :\n\n"},
[87502] = {title = "Chasse aux renseignements", objective = "Pénétrez dans la Main de Tyr dans les Maleterres de l’Est et explorez la cathédrale centrale, ainsi que la tour des mages et le donjon à l’intérieur de la Nouvelle-Avalon avant de retourner voir Caldoran au camp de la Croisade.\n\nUne incursion directe est possible mais potentiellement dangereuse. Parlez à l’inquisitrice Jociphine au camp de la Croisade si vous préférez adopter une approche plus subtile.", description = "Je ne suis pas ravi de solliciter votre aide. Vous fréquentez des hérétiques et des personnes impures et accepter votre présence ici est indigne de moi et de notre ordre sacré. Toutefois… vous m’avez l’air de quelqu’un de capable et serez un instrument utile pour répondre à nos besoins ici.\n\nAllez à la Main de Tyr et explorez la cathédrale avant de vous enfoncer dans la Nouvelle-Avalon pour examiner le donjon et la tour des mages. Revenez sans plus tarder ici faire votre rapport. Nous devons savoir à quoi nous avons affaire.", progress = nil, completion = "&lt;Caldoran grogne tandis que vous finissez votre rapport.&gt;\n\nLe regroupement de forces à la Nouvelle-Avalon est préoccupant, mais leur nombre n’est pas insurmontable. \n\nIl semblerait aussi que Dathrohan… ou devrais-je dire Balnazzar consolide ses forces à la cathédrale, et le fait que sa magie impure en scelle l’entrée confirme qu’il y prépare quelque chose. Ce monstre profane notre saint lieu et il mourra par ma main. Je le jure sur ma vie.", rewards = "Vous recevrez :\n\n"},
[87506] = {title = "Affaiblir les défenses", objective = "Pénétrez dans la Main de Tyr dans les Maleterres de l’est. Éliminez trois commandants de siège de la Croisade écarlate.", description = "Pendant votre absence, nous avons finalisé notre plan d’attaque contre la Main de Tyr. Nous allons lancer un assaut frontal ainsi qu’une frappe sur leur flanc, que je mènerai moi-même. Mais tout d’abord, nous allons devoir affaiblir les défenses frontales. Je vais vous renvoyer là-bas pour éliminer le plus possible de membres du commandement de siège adverse, car toute la défense de l’enclave repose sur ces personnes.\n\nJe vais rejoindre mes troupes à notre position. Vous ferez votre rapport à la commandante Beatrix à votre retour.\n\nN’échouez pas.", progress = nil, completion = "Nous avons reçu le signal. Caldoran et sa garde sont en position et peuvent soutenir une attaque directe. \n\nPendant votre absence, une estafette de l’Aube d’argent a apporté un message, puis a pris congé prestement. Il semblerait qu’il y ait quelques problèmes à la chapelle de l’Espoir de Lumière et que votre présence soit requise. Je ne pourrais me permettre de vous en demander plus au vu de ce que vous avez déjà accompli. Merci pour tout, &lt;nom&gt;. La Croisade est aussi prête que jamais.", rewards = "Vous recevrez :\n\n"},
[87508] = {title = "Se présenter au seigneur Tyrosus", objective = "Parlez au seigneur Maxwell Tyrosus à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Je vous en prie, <nom>, une estafette arrivée. Vous devez retourner à la chapelle de l’Espoir de Lumière en toute hâte ! Nous subissons un assaut et le seigneur Maxwell Tyrosus requiert votre présence au plus vite.", progress = nil, completion = "Nous avons subi une attaque ! Une sorte… d’abomination ressemblant à un dragon a surgi du côté de l’enclave Écarlate et nous a fait grand mal. J’ai déjà vu des dragons, mais je n’avais jamais rien vu de tel.\n\nLe plus étrange est qu’elle est partie aussi vite qu’elle est arrivée. Elle a frappé d’une seule et terrible déflagration, puis s’est envolée. C’est une bénédiction, cela va sans dire, mais c’est aussi profondément troublant. Personne ici ne s’attendait à une telle attaque. Elle aurait pu infliger de lourds dégâts mais a choisi de ne pas le faire.", rewards = "Vous recevrez :\n\n"},
[87509] = {title = "La colère de l’Aube", objective = "Retournez voir la commandante Beatrix au camp de la Croisade écarlate dans les Maleterres de l’est et préparez-vous à reprendre l’enclave Écarlate.", description = "Peu importe la raison qui a poussé cette bête à retourner dans l’enclave, nous ne lui donnerons pas une autre occasion de nous éliminer. Il semble que nous n’ayons plus le choix : nous devons maintenant assigner toute la puissance de l’Aube d’argent à l’éradication de la menace représentée par l’enclave Écarlate.\n\nRetournez voir Beatrix au camp de la Croisade. Assurez-la de notre soutien… pour le moment.", progress = nil, completion = "Une sorte de bête a attaqué l’Espoir de Lumière ? Balnazzar s’est montré audacieux. Trop audacieux, car à présent, l’Aube d’argent s’est ralliée à notre cause. Je ne vais pas vous mentir, c’est un soulagement de pouvoir compter sur elle. Je ne pense pas que nous aurions été capables de prendre l’enclave avec les forces dont nous disposons actuellement.\n\nL’heure du dénouement approche, &lt;classe&gt;. Préparez vos troupes.", rewards = "Vous recevrez :\n\n"},
[87516] = {title = "Décapitation imminente", objective = "Pénétrez dans l’enclave Écarlate via le chemin de la montagne et attaquez les forces de défense de la Main de Tyr. Sonnez la cloche à l’intérieur de l’abbaye pour semer la confusion et signaler aux troupes de Beatrix d’attaquer.\n\nUne fois la cloche sonnée, affrontez Balnazzar et détruisez-le.", description = "Nous avons rassemblé nos troupes et nous les mettrons en position pour lancer l’assaut frontal tandis que les vôtres se faufileront sur l’arrière de la cathédrale en passant par la montagne.\n\nUne fois à l’intérieur, dirigez-vous vers l’abbaye et sonnez la cloche pour signaler l’attaque.\n\nVous serez en plein cœur du combat jusqu’à ce que nous arrivions, alors faites attention à vous.", progress = nil, completion = "Trahison ! Après la chute de Balnazzar, Beatrix a pris le contrôle des forces de défense restantes et a immédiatement retourné ses troupes contre nous ! Malgré les lourdes pertes subies, nous avons réussi à riposter avant de pouvoir nous replier et nous regrouper. Nous redoutions le pire pour vous jusqu’à ce que nos équipes de reconnaissance nous signalent votre présence.\n\nJe ne sais pas à quel jeu jouent Beatrix et Caldoran, mais je suis prêt à abattre toute personne portant du rouge et laisser la Lumière trier le bon grain de l’ivraie.", rewards = "Vous recevrez :\n\n"},
[87517] = {title = "Rouge = Mort", objective = "Joignez-vous à la bataille et accédez à la section intérieure de l’enclave Écarlate. Attaquez les troupes de la grande commandante Beatrix et éliminez-la, puis abattez Solistrasza la dragonne à l’intérieur de l’enclave.", description = "La bête qui a attaqué l’Espoir de la lumière était en fait la créature de Caldoran et il ne s’agissait que d’une ruse pour inciter nos troupes à s’engager dans cette attaque. Caldoran et Beatrix se sont servis de nous pour faire diversion et éliminer leur rival Balnazzar, avant de se retourner contre nous et de reprendre le contrôle des Maleterres pour en éliminer notre présence.\n\nIl nous manque encore beaucoup de réponses et cela ne sera pas facile, mais nous abattrons ces chiens pour cette trahison.", progress = nil, completion = "Ce que nous avons découvert dépasse les bornes. Un nouveau fléau ? Un dragon empreint de Lumière ? Siphonner les âmes des personnes pieuses pour alimenter leurs armes imprégnées de Lumière ? Une telle profanation me révulse, et j’ai peur d’imaginer les autres pouvoirs dont Caldoran peut disposer. La façon dont il a détruit Balnazzar est louche. Une telle puissance brute est au-delà des paladins les plus robustes. \n\nQuoi qu’il en soit, nous allons en finir. Nous ne ferons aucun quartier. Il ne saurait y avoir de rédemption pour ces atrocités.", rewards = "Vous recevrez :\n\n"},
[87518] = {title = "La chute du grand croisé", objective = "Tuez le grand croisé Baelin Caldoran dans le sanctuaire intérieur de l’enclave Écarlate.", description = "La voie qui s’ouvre à nous est aussi simple que brutale. Infiltrez le sanctuaire intérieur de l’enclave Écarlate et affrontez le nouveau « grand croisé » autoproclamé, Baelin Caldoran. Punissez-le pour ses crimes. Nous allons rester ici et garder cette position pour nous assurer que personne ne vous surprenne par-derrière.\n\nChâtiez ce monstre comme il le mérite.", progress = nil, completion = "Caldoran n’est plus, mais cette victoire reste amère par le sang qu’elle a vu couler. Les troupes de la Croisade ont été dispersées et l’enclave Écarlate est en flammes : nous avons réalisé un véritable exploit, ici. Il reste beaucoup à faire dans les Maleterres, mais cela fait toujours un adversaire de moins dont il faudra nous soucier. Et d’après moi, c’est une bonne chose à fêter.\n\nPour la Lumière ! Pour Lordaeron ! Pour l’Aube !", rewards = "Vous recevrez :\n\nPierre de foyer de l’Aube"},
[88654] = {title = "Une cargaison complète", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Vous allez être la cible du sort suivant :\n\nRéputation (Faction des marchands)\n\nVous recevrez :\n\n"},
[88715] = {title = "Jamais en paix", objective = "Apportez un autre cœur du Destin funeste au frère Luctus à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Apportez-moi toutes les âmes condamnées que vous croiserez, <nom>.\n\nJ’insiste, vous DEVEZ me les apporter.\nMON devoir est de rester pour guider les âmes perdues. Le VÔTRE est de me les rapporter.\n\nMais un conseil, ne vous chargez que d’une seule âme à la fois. Croyez-moi, votre propre âme n’en supporterait pas davantage. Et votre esprit… eh bien, il en supporterait encore moins.\n\nVoici donc votre fardeau. Puisque vous le pouvez, vous le devez.\n\nConsidérez cela comme une obligation morale.", progress = "Le Fléau ne se repose jamais, et nous devons en faire autant, <nom>.", completion = "&lt;nom&gt;, chaque cœur que vous rapportez est une leçon. Certaines de ces âmes appartenaient à de formidables guerriers, qui semblaient inébranlables, indomptables… mais qui pourtant… succombèrent.\n\nLe Fléau les avala, la corruption rongea leur esprit… et certains se soumirent même volontairement.\n\nLeur grande force fut ainsi étouffée.\n\nEt maintenant, grâce à vous, ils préservent leur dernières traces de valeur.\n\nSans vous, les horreurs de leur mort auraient éclipsé l’héroïsme de leur vie.", rewards = "Vous recevrez :\n\nVestiges de valeur"},
[88716] = {title = "Jamais en paix", objective = "Apportez un autre cœur du Destin funeste au frère Luctus à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Apportez-moi toutes les âmes condamnées que vous croiserez, <nom>.\n\nJ’insiste, vous DEVEZ me les apporter.\nMON devoir est de rester pour guider les âmes perdues. Le VÔTRE est de me les rapporter.\n\nMais un conseil, ne vous chargez que d’une seule âme à la fois. Croyez-moi, votre propre âme n’en supporterait pas davantage. Et votre esprit… eh bien, il en supporterait encore moins.\n\nVoici donc votre fardeau. Puisque vous le pouvez, vous le devez.\n\nConsidérez cela comme une obligation morale.", progress = "Le Fléau ne se repose jamais, et nous devons en faire autant, <nom>.", completion = "&lt;nom&gt;, chaque cœur que vous rapportez est une leçon. Certaines de ces âmes appartenaient à de formidables guerriers, qui semblaient inébranlables, indomptables… mais qui pourtant… succombèrent.\n\nLe Fléau les avala, la corruption rongea leur esprit… et certains se soumirent même volontairement.\n\nLeur grande force fut ainsi étouffée.\n\nEt maintenant, grâce à vous, ils préservent leur dernières traces de valeur.\n\nSans vous, les horreurs de leur mort auraient éclipsé l’héroïsme de leur vie.", rewards = "Vous recevrez :\n\nVestiges de valeur"},
[88721] = {title = "Armes de bataille excellentes – Ami de l’Aube", objective = "En échange de 30 insignes de l’Aube et 30 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets puissants ?\n\nIl faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l’Aube est Amical, vous paierez un gros supplément. Je vous conseille d’améliorer votre réputation auprès de l’Aube avant d’aller plus avant dans vos projets.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBague de piétéBague de résolutionDernière chance de VerimondeSac de fournituresJambières du chassepesteHeaume en cuir sanctifié"},
[88722] = {title = "Armes de bataille excellentes – Honoré auprès de l’Aube", objective = "En échange de 20 insignes de l’Aube et 20 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets puissants ?\n\nIl faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l’Aube est Honoré, vous paierez un supplément que je qualifierais de prohibitif. Je vous conseille d’améliorer votre réputation auprès de l’Aube avant d’aller plus avant dans vos projets.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBague de piétéBague de résolutionDernière chance de VerimondeSac de fournituresJambières du chassepesteHeaume en cuir sanctifié"},
[88723] = {title = "Armes de bataille excellentes – Révéré auprès de l’Aube", objective = "En échange de 7 insignes de l’Aube et 7 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets puissants ?\n\nLes objets proposés à ceux qui sont révérés auprès de l’Aube ont un prix tout à fait raisonnable. Je vous encourage à faire un achat !", progress = "Choisissez avec soin. Vous ne pourrez être remboursée.", completion = "Bonne journée à vous, &lt;nom&gt;. C’était un plaisir de faire affaire avec vous.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nBague de piétéBague de résolutionDernière chance de VerimondeSac de fournituresJambières du chassepesteHeaume en cuir sanctifié"},
[88724] = {title = "Armes de bataille excellentes – Exalté auprès de l’Aube", objective = "En échange de 6 insignes de l’Aube et 6 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets puissants ?\n\nVous bénéficiez d’une remise sur les objets proposés à ceux qui sont exaltés auprès de l’Aube. Je vous encourage à faire un achat !Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nBague de piétéBague de résolutionDernière chance de VerimondeSac de fournituresJambières du chassepesteHeaume en cuir sanctifié"},
[88725] = {title = "Armes de bataille épiques – Ami de l’Aube", objective = "En échange de 110 insignes de l’Aube et 110 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets d’une grande puissance ?\n\nIl faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l’Aube est Amical, vous paierez un très gros supplément. Je vous conseille d’améliorer votre réputation auprès de l’Aube avant d’aller plus avant dans vos projets.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmulette de l’AubeBrassards d’espoirBrassards de subterfugeMédaillon de l’AubeTalisman d’ascendanceLe Purificateur"},
[88726] = {title = "Armes de bataille épiques – Honoré auprès de l’Aube", objective = "En échange de 75 insignes de l’Aube et 75 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets d’une grande puissance ?\n\nIl faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l’Aube est Honoré, vous paierez un très gros supplément. Je vous conseille d’améliorer votre réputation auprès de l’Aube avant d’aller plus avant dans vos projets.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmulette de l’AubeBrassards d’espoirBrassards de subterfugeMédaillon de l’AubeTalisman d’ascendanceLe Purificateur"},
[88727] = {title = "Armes de bataille épiques – Révéré auprès de l’Aube", objective = "En échange de 45 insignes de l’Aube et 45 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets d’une grande puissance ?\n\nIl faut que je vous prévienne : les articles épiques achetés lorsqu’on est révéré auprès de l’Aube sont encore très chers. Je vous conseille d’améliorer votre réputation auprès de l’Aube avant d’aller plus avant dans vos projets.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmulette de l’AubeBrassards d’espoirBrassards de subterfugeMédaillon de l’AubeTalisman d’ascendanceLe Purificateur"},
[88728] = {title = "Armes de bataille épiques – Exalté auprès de l’Aube", objective = "En échange de 27 insignes de l’Aube et 27 insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l’Aube d’argent.", description = "Salutations, <ami/amie>. Avez-vous des insignes de l’Aube ou de la Croisade que vous aimeriez échanger contre des objets d’une grande puissance ?\n\nCeux qui sont exaltés auprès de l’Aube bénéficient de nos meilleures offres ! Je vous encourage à faire un achat.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nAmulette de l’AubeBrassards d’espoirBrassards de subterfugeMédaillon de l’AubeTalisman d’ascendanceLe Purificateur"},
[88729] = {title = "Étreinte de glace de Ramaladni", objective = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est, veut que vous lui rameniez 1 rune de givre, 1 saphir bleu et 1 barre d’arcanite.", description = "Réparer cet anneau pourrait bien être un vrai défi, <nom>. Il a été fabriqué à partir des runes que l’on trouve sur les bâtiments du Fléau, comme Naxxramas. D’autres objets sont nécessaires, mais votre premier souci doit être de récupérer ces runes de givre. Si vous me fournissez ce dont j’ai besoin, cet anneau retrouvera sa gloire première.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nÉtreinte de glace de Ramaladni"},
[88730] = {title = "C’est tout ce que j’ai à mon répertoire…", objective = "L’artisan Wilhelm de la chapelle de l’Espoir de Lumière, dans les Maleterres de l’est, veut 2 runes de givre, 2 essences d’eau, 2 saphirs bleus et 30 pièces d’or.", description = "Vous vous imaginez être <un héros/une héroïne> de l’Aube, pas vrai ? J’ai vu nos plus grands soldats submergés par la racaille de Kel’Thuzad ! Après ça, combien pensez-vous que je vais parier sur <un ahuri fraîchement débarqué/une ahurie fraîchement débarquée> ?\n\n<Wilheim soupire.>\n\nM’enfin, c’est pas comme si j’avais le choix. Y’a personne d’autre, alors autant vous aider.\n\nOmarion m’a laissé avec un seul patron. C’est tout ce que j’ai à mon répertoire… Je peux faire quelques variations sur ce thème de pantalon, il faudra juste que vous me trouviez les matériaux.", progress = "Vous n’auriez pas croisé Omarion, par hasard ?", completion = "&lt;Wilheim éponge la sueur de son front.&gt;\n\nC’était pas un travail facile ! Profitez bien de ce pantalon, &lt;classe&gt;. Au moins maintenant vous pourrez mourir avec classe.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nJambières glaciairesJambières plaie-de-glaceJambières glacécailleJambières polairesJambières givrées"},
[88744] = {title = "Sous les ombres", objective = "Surveillez votre carte pour trouver une région subissant une attaque du Fléau. Allez-y et endommagez une nécropole en exterminant les créatures du Fléau aux alentours. Rapportez ensuite 10 de leurs Runes nécrotiques au commandant Thomas Helleran, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Les nécropoles volantes du Fléau hantent les territoires de la Horde comme de l’Alliance. Les Terres foudroyées, Berceau-de-l’Hiver, les Steppes ardentes et Tanaris sont sillonnés par les ombres de ces forteresses aériennes.\n\nSeuls nos efforts coordonnés nous permettrons peut-être de les repousser.\n\nLes nécropoles sont soutenues par des cercles magiques en divers endroits des territoires envahis. Nous avons découvert que nous pouvons détruire leurs défenses en abattant les hordes de créatures décérébrées qui entourent ces cercles.", progress = "Il nous faudra du temps pour venir à bout de cette menace. Comment ça c’est passé pour vous, <nom> ?", completion = "Vous avez bien fait, &lt;nom&gt;. C’est par petits pas que nous pourrons triompher de cette nouvelle menace du Fléau.\n\nReposez-vous et reprenez des forces, mais ne tardez pas trop à retourner au front, sans quoi nous risquerions de perdre le terrain que nous avons gagné aujourd’hui.\n\nPour vous aider dans vos batailles à venir, nous allons vous permettre d’obtenir certains de nos objets spéciaux en échange d’autres runes nécrotiques.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHuile de sorcier bénitePierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88745] = {title = "Les ombres du destin", objective = "Rendez-vous sur un cercle d’invocation et tuez une Ombre funeste, puis retournez auprès du commandant Thomas Helleran, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Lorsque vous aurez anéanti les défenses des cercles d’invocation du Fléau apparus dans les zones attaquées, vous pourrez affronter les acolytes qui les protègent.\n\nCe ne sont pas des hommes en réalité. Ce sont des Ombres, qui comptent parmi les créatures les plus terrifiantes du roi-liche. Elles peuvent être démasquées à l’aide des runes nécrotiques qu’elles portent, puis détruites par la magie ou la force des armes.", progress = nil, completion = "Excellent travail, &lt;nom&gt;. Une fois les Ombres détruites, cela ne peut être qu’une question de temps avant que le roi-liche ne décide de rappeler ses nécropoles et de nous laisser en paix.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHuile de sorcier bénitePierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88746] = {title = "Pierre à aiguiser consacrée", objective = "Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirai une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche.", description = nil, progress = "Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirai une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche.", completion = "Merci bien, &lt;nom&gt;. Voici les pierres à aiguiser consacrées. Utilisez-les avec circonspection.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88747] = {title = "Pierre à aiguiser consacrée", objective = "Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirai une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche.", description = nil, progress = "Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirai une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche.", completion = "Merci bien, &lt;nom&gt;. Voici les pierres à aiguiser consacrées. Utilisez-les avec circonspection.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nPierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88748] = {title = "Cristal nécrotique fêlé", objective = "Apportez le Cristal nécrotique fêlé au lieutenant Orrin à l’extérieur des portes de Stormwind.", description = "Sur le cadavre de l’abomination, vous découvrez un cristal lézardé, animé d’une lente pulsation d’énergie nécrotique.", progress = "Avez-vous besoin de quelque chose ?", completion = "Hm, vous avez pris ceci sur le cadavre de l’une des abominations qui tentaient de nous envahir ?\n\nNous avons été informés des nécropoles que le Fléau invoque pour établir ses camps de base. Je suppose qu’ils voulaient en établir un à l’intérieur de Stormwind. Heureusement qu’ils ont échoué.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHuile de sorcier bénitePierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88749] = {title = "Cristal nécrotique voilé", objective = "Apportez le Cristal nécrotique voilé au lieutenant Rukag dans la cour d’Undercity.", description = "Sur le cadavre de la créature, vous découvrez un cristal qui émet faiblement de l’énergie nécrotique.", progress = "Puis-je vous aider ?", completion = "Vous dites que vous l’avez pris sur une créature qui attaquait la ville ?\n\nNous avons été informés des nécropoles que le Fléau invoque pour établir ses camps de base. Je suppose qu’ils tentaient d’en établir un à Undercity. Nous devrons nous montrer vigilants à l’avenir.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nHuile de sorcier bénitePierre à aiguiser consacréePierre à aiguiser consacrée lestée"},
[88882] = {title = "Huile de sorcier bénite", objective = "En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite.", description = nil, progress = "En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite.", completion = "J’espère que ces objets vous seront utiles lors de vos batailles à venir.", rewards = "Vous recevrez :\n\nHuile de sorcier bénite"},
[88883] = {title = "Huile de sorcier bénite", objective = "En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite.", description = nil, progress = "En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite.", completion = "J’espère que ces objets vous seront utiles lors de vos batailles à venir.", rewards = "Vous recevrez :\n\nHuile de sorcier bénite"},
[88968] = {title = "Le seigneur de Blackrock", objective = "Parlez au haut seigneur Saurfang à Orgrimmar. Il vous attend dans la vallée de la Force.", description = "Allez voir le haut seigneur Saurfang dans la vallée de la Force.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[88969] = {title = "Le seigneur de Blackrock", objective = "Allez dans la vallée des Héros de Stormwind et parlez au grand maréchal Pont-de-Pierre.", description = "Allez dans la vallée des Héros et parlez au grand maréchal Pont-de-Pierre.Lors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = nil},
[89224] = {title = "Pénurie de nourriture", objective = "Procurez-vous des restes peu ragoûtants dans la Nouvelle-Avalon et rapportez-les à la cheffe. Si vous avez du mal à en trouver, vous résoudrez peut-être plus facilement cette pénurie par la violence.", description = "<La cheffe prend la parole sans que vous n’ayez eu le temps de la saluer.>\n\nQue la Lumière soit louée, de l’aide est enfin arrivée ! Ni le fourneau ni le garde-manger n’aurait pu tenir face à l’afflux de commandes que nous avons reçues. Nos lignes de ravitaillement habituelles ont été coupées, et j’imagine que les cris que j’entends dehors ont quelque chose à voir avec ça.\n\nQuelle qu’en soit la raison, j’ai besoin d’aide. Tout de suite. Trouvez-moi quelque chose qui a l’air vaguement comestible en ville et nous partirons de là.", progress = nil, completion = nil, rewards = nil},
[89229] = {title = "Le chemin vertueux", objective = "Parlez à Leonid Barthalomew le Révéré à la chapelle de l’Espoir de Lumière pour recevoir votre récompense.", description = "Vous connaissez désormais toute l’histoire. La revivre fut difficile, mais cela faisait trop longtemps que je repoussais l’échéance. Étrangement, je me sens… mieux. Je prie depuis si longtemps pour obtenir justice, mais ce ne sera pas à moi de la rendre. J’ai choisi mon propre chemin, et si je laisse la vengeance me ramener dans les ténèbres, cela ne m’apportera pas la paix. Cela ne respectera pas non plus les souhaits de mon fils.\n\nJe rentre présenter mon rapport au seigneur Tyrosus. Rendez-vous à la chapelle de l’Espoir de Lumière. J’ai quelque chose qui vous revient.", progress = nil, completion = "Caldoran finira par payer. Les vermines maléfiques de son genre finissent toujours par s’autodétruire. J’y crois, tout comme je crois au rêve de mon fils.\n\nS’il vous plaît, prenez ceci. Liliana me l’a donné quand j’ai intégré la Main d’argent et il m’a servi à me rappeler mes serments envers ma famille et mon pays pendant mes années de service. J’espère qu’il pourra vous aider à vous rappeler que c’est avant l’aube que la nuit est la plus noire, mais que l’aube vient toujours.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nCharme de LeonidMain de la justice renaissanteSceau de la famille BarthalomewJournal du Révéré\n\nVous recevrez également :\n\n"},
[89234] = {title = "Une affaire personnelle", objective = "Retrouvez Leonid Barthalomew le Révéré devant l’entrée de service à l’est des portes de Stratholme.", description = "Ce dont nous avons parlé à la chapelle de l’Espoir de Lumière et mon passé avec Caldoran… Tout a commencé ici à Stratholme. Vous connaissez « l’épuration » de Stratholme qui a eu lieu au début de la Troisième guerre, n’est-ce pas ?\n\nEh bien, j’y étais, ainsi que Caldoran. C’est là que notre histoire a commencé. Si vous le voulez bien, retrouvez-moi à l’entrée de service de Stratholme à l’est.", progress = nil, completion = "Je suis content que vous soyez là. Je ne sais pas si j’aurais été capable de faire cela seul.", rewards = nil},
[89235] = {title = "L’épuration", objective = "Entrez dans Stratholme et engagez-vous sur la place du Massacre, et retrouvez-y Leonid Barthalomew le Révéré.", description = "Cette cité est maudite. J’y ai passé des années après ma mort, esclave du roi-liche. Pourtant, même dans ma servitude, j’ai conservé un brin de conscience. J’ai erré d’innombrables fois près du corps de ma femme, figée à jamais dans la terreur qu’elle a ressentie à son dernier instant.\n\nSi vous le voulez bien, traversez la porte vers la zone appelée la place du Massacre. Je vous y rejoindrai quand j’en aurai trouvé la force. Vous aurez besoin d’aide.", progress = nil, completion = "Vous comprenez désormais pourquoi je hais Caldoran. C’est un zélote empli de haine. Il l’était déjà à l’époque. Caldoran n’a pas suivi Arthas dans son expédition vers le Northrend, mais j’aurais tant aimé qu’il le fasse, qu’il meurt là-bas et que nos chemins ne se croisent plus jamais.", rewards = "Vous recevrez :\n\n"},
[89236] = {title = "Pommes et bonne poire", objective = "Trouvez le verger dans la section sud de la Nouvelle-Avalon et récupérez des pommes. Retournez ensuite voir Carrie Âtrefeu dans l’auberge de la Nouvelle-Avalon. Si vous trouvez les pommes trop chères, cherchez d’autres moyens de vous en procurer dans les environs.", description = "Si vous voulez mon avis, ce sont les fruits frais qui illuminent chaque repas. Ce que je préfère, ce sont les pommes, et il se trouve que nous avons un superbe verger, juste au sud.\n\nSi jamais il n’a pas brûlé, et rien n’est moins sûr, je dirais qu’une petite récolte s’impose !\n\nD’habitude, on me fait une ristourne, mais je leur dois une tarte depuis un moment. Vous devrez donc les acheter au prix fort, mais vous n’avez pas l’air d’être dans le besoin.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRecette : omelette du Lever de soleil"},
[89245] = {title = "Le thon du tonneau", objective = "Inspectez le bateau amarré au sud de la Nouvelle-Avalon en quête d’une cargaison de poissons et livrez-la à Carrie.", description = "J’ai fait mon service à Hearthglen pendant un moment, et je ne vous dis pas à quel point il était terrifiant de dépendre des ravitaillements qui devaient traverser les Maleterres pour nous nourrir. Heureusement que la Nouvelle-Avalon dispose d’une chaîne de ravitaillement maritime aussi fiable, du moins jusqu’à récemment.\n\nIl est temps pour un nouvel épisode de notre série « Carrie doit nourrir toute une armée dans une cuisine conçue pour une famille de quatre », et cette fois-ci, il me faut du poisson. Rejoignez les quais au sud pour voir si ma commande est arrivée.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRecette : filet de flanc"},
[89253] = {title = "Plat principal", objective = "Procurez-vous de la viande propre à la consommation humaine. Si vous n’en trouvez pas dans la Nouvelle-Avalon, vous pourrez (à force) en récupérer assez en chassant des bêtes dans les Maleterres de l’est.", description = "Aucun repas n’est digne de ce nom sans sa pièce maîtresse : la viande ! Comme vous pouvez l’imaginer, trouver de la viande propre à la consommation dans les Maleterres est un défi sans pareil.\n\nPour ne rien arranger, nos limiers ne mangent que ça ! Je suis sûre que vous voyez où je veux en venir et que vous comprenez mieux pourquoi je suis toujours en retard.\n\nEh bien, qu’attendez-vous ?Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRecette : steak de rôdeur"},
[89256] = {title = "Faire vos preuves : protège-épaules", objective = "Fabriquez des protège-épaules écarlates issus de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous une paire de protège-épaules. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = "Fabriquez, ou contribuez. À vous de voir. Notre armurerie est bien équipée pour tout ce qui nous attend, mais le plus important, c’est que nos artisans puissent travailler et améliorer leur technique.", completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89257] = {title = "Faire vos preuves : plastron", objective = "Fabriquez un plastron écarlate issu de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous un plastron. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = nil, completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89258] = {title = "Faire vos preuves : garde-poignets", objective = "Fabriquez des brassards écarlates issus de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous une paire de brassards. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = "Fabriquez, ou contribuez. À vous de voir. Notre armurerie est bien équipée pour tout ce qui nous attend, mais le plus important, c’est que nos artisans puissent travailler et améliorer leur technique.", completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89259] = {title = "Faire vos preuves : gants", objective = "Fabriquez des gants écarlates issus de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous une paire de gants. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = "Fabriquez, ou contribuez. À vous de voir. Notre armurerie est bien équipée pour tout ce qui nous attend, mais le plus important, c’est que nos artisans puissent travailler et améliorer leur technique.", completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89260] = {title = "Faire vos preuves : ceinture", objective = "Fabriquez une ceinture écarlate issue de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous une ceinture. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = "Fabriquez, ou contribuez. À vous de voir. Notre armurerie est bien équipée pour tout ce qui nous attend, mais le plus important, c’est que nos artisans puissent travailler et améliorer leur technique.", completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89261] = {title = "Faire vos preuves : garde-jambes", objective = "Fabriquez un pantalon écarlate issu de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous un pantalon. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = nil, completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89262] = {title = "Faire vos preuves : bottes", objective = "Fabriquez des bottes écarlates issues de n’importe quel métier de fabrication d’armure ou faites don d’une pièce d’uniforme écarlate issue de l’artisanat.\n\nSi vous optez pour un don, vous trouverez une caisse près de l’intendance dans la caserne. Livrez la pièce à Bryon Lamacier pour recevoir votre récompense.", description = "Pour garantir des pièces de qualité, il faut s’entraîner en permanence. Nos troupes placent leurs vies entre les mains d’anonymes, et c’est à moi de m’assurer de la qualité de chaque pièce d’armure.\n\nCe que je vous demande est simple. Si vous vous y connaissez en couture, en travail du cuir ou en forge, fabriquez-vous une paire de chaussures. Vous pourrez conserver votre œuvre.\n\nSi ça vous est impossible, commandez et faites don de n’importe quelle pièce d’uniforme de la Croisade à la place.", progress = "Fabriquez, ou contribuez. À vous de voir. Notre armurerie est bien équipée pour tout ce qui nous attend, mais le plus important, c’est que nos artisans puissent travailler et améliorer leur technique.", completion = "Excellent travail.\n\nNous avons commencé à emmagasiner des rebuts dans ces vieux coffres, et je manque d’espace pour les stocker, mais vous avez l’air capable d’apprécier les choses simples. Je pense que ce sera une récompense correcte pour une contribution ponctuelle.\n\nOh, et j’ai ajouté une surprise précieuse dans quelques paquets. On verra si vous avez de la chance.", rewards = "Vous recevrez :\n\nCoffret écarlate"},
[89310] = {title = "Val-Terreur", objective = "Allez à Val-Terreur et retrouvez Leonid Barthalomew le Révéré près de l’une des maisons.", description = "J’ai mis de nombreuses années à surmonter ma culpabilité après que mon esprit a été libéré de l’emprise du roi-liche. Une fois délivré par Sylvanas, j’ai refusé son offre et erré seul dans les Maleterres. Des mois durant, j’ai vagabondé. Je ne sais pas vraiment pourquoi, mais j’ai fini par arriver à la maison de ma famille et ce que j’y ai trouvé était… inattendu.\n\nAllez au village hanté connu aujourd’hui sous le nom de Val-Terreur, trouvez la maison la plus au nord. Retrouvez-moi là-bas pour connaître la suite.", progress = nil, completion = "Je suis malade de voir ce que mon foyer est devenu.", rewards = nil},
[89328] = {title = "Deuil", objective = "Écoutez la dernière partie de l’histoire de Leonid.", description = "Lorsque mon errance m’a amené ici, imaginez ma surprise de trouver mon fils en vie, et même en bonne santé. Il ne m’a pas rejeté comme les autres êtres vivants, il m’a tendu les bras. Il était devenu guérisseur et étudiait les morts-vivants. Il était persuadé qu’il pouvait non seulement empêcher cette affliction, mais même la guérir.\n\nPendant un bref moment, nous avons été ensemble et heureux. Je l’aidais avec ses recherches, et il m’offrait l’espoir dont j’avais besoin.\n\nDu moins, jusqu’à ce que Baelin Caldoran revienne dans nos vies.", progress = nil, completion = "À ma grande honte, j’ai survécu. Peu de temps après, le seigneur Tyrosus m’a retrouvé et remis sur pieds.\n\nBaelin Caldoran a été responsable non pas une fois, mais deux, de la mort d’une personne qui m’était chère. Son fanatisme arrogant est le cœur même de la corruption qui ronge la Croisade écarlate.\n\nJe ne me remettrai jamais de la douleur, mais je continue d’honorer mon fils en partageant son espoir et sa vision d’un avenir où la malédiction de la non-mort aurait été guérie. Je dois espérer qu’un jour, quelqu’un pourra terminer son œuvre.", rewards = "Vous recevrez :\n\n"},
[89329] = {title = "Écraser l’infestation", objective = "Tuez 5 marcheurs des cryptes et 8 démons des cryptes, puis retournez voir Leonid Barthalomew le Révéré dans son ancienne demeure de Val-Terreur.", description = "C’est écœurant. Cet endroit est infesté d’ouvriers nérubiens nécrosés. Je veux qu’ils soient détruits.", progress = nil, completion = "C’était probablement insignifiant, mais au moins je me sens un peu mieux.", rewards = "Vous recevrez :\n\n"},
[89340] = {title = "Annonce affreusement ampoulée", objective = "Terminez la livraison.", description = "À l’estimée cuisinière en chef de la Nouvelle-Avalon : Carrie Âtrefeu,\n\nJ’espère que cette lettre arrivera jusqu’à vous ! Votre départ de la Nouvelle-Âtreval a pesé sur nos cœurs, et nos estomacs. Pas un jour ne passe sans qu’on se plaigne du gruau matinal en espérant pouvoir déguster un de vos délicieux repas.\n\nC’est pourquoi nous organisons un banquet dans lequel seront servis les mets les plus délicats que Lordaeron ait connus : les vôtres.\n\nUne caravane sous escorte arrivera dans deux semaines. Vous et vos plats devront être prêts.", progress = nil, completion = nil, rewards = nil},
[89341] = {title = "Le grand festin", objective = "Aidez Carrie Âtrefeu à la Nouvelle-Avalon une dernière fois en collectant les ingrédients suivants :", description = "Votre aide a été inestimable. Le peuple et les troupes de la Nouvelle-Avalon pourront profiter d’un repas chaud pour ce soir et ceux qui suivront. Je vous en suis reconnaissante, vraiment.\n\nMais, comme vous l’avez apparemment déjà lu, il me reste une dernière tâche avant de pouvoir me reposer. Je peux me charger du plus gros moi-même, mais si vous voulez bien me rendre service une fois encore, je vous apprendrai mes plus célèbres recettes.\n\nVous mangerez comme un généralissime tous les soirs.Vous pourrez choisir une de ces récompenses :\n\n", progress = nil, completion = nil, rewards = "Vous pourrez choisir une de ces récompenses :\n\nFestin de loche à taches clairesGrand banquet de homard\n\nVous recevrez également :\n\nLivre de recettes de CarrieSels sacrésÉpices exquises"},
[89342] = {title = "Membre VIP du club de la Haute", objective = "Préparez vous-même une omelette du Lever de soleil et un steak de rôdeur et livrez-les à Devon Dubois devant l’auberge de la Nouvelle-Avalon.", description = "Hé, vous !\n\nVous ressemblez à la personne dont me parle Carrie ces derniers temps. Elle m’a dit beaucoup de bien de vous. Enfin, pas au début, mais elle a rapidement changé de ton.\n\nBref, si la cheffe vous aime bien, alors moi aussi. J’aimerais vous offrir une adhésion permanente, vous n’aurez plus besoin de porter la carte sur vous.\n\nTout ce que je vous demande en retour, c’est une omelette du Lever de soleil et un steak de rôdeur. Que vous aurez cuisinés vous-même, bien entendu.", progress = nil, completion = nil, rewards = nil},
[89381] = {title = "Technologie de pointes", objective = "Récupérez des flèches dans le champ de tir au sud de la place centrale de la Nouvelle-Avalon. Vous pouvez aussi obtenir des flèches en affrontant des personnages forestiers.", description = "Ouah ! C’est courageux de votre part de traverser le champ de tir en plein entraînement. On dirait presque que vous voulez vous prendre une flèche dans le genou, ou peut-être dans le bas du dos, vu comme vous vous dandinez.\n\nMais bon, ça vous regarde. Puisque vous n’avez pas l’air de reculer face au danger, pourquoi ne pas nous prêter main-forte ? La récupération de nos flèches après chaque salve nous fait perdre un temps précieux.\n\nEt si vous en ramassiez quelques-unes pour moi, hein ?Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPatron : carquois écarlate"},
[89421] = {title = "Paradis de balles", objective = "Fabriquez ou achetez des obus en thorium à un personnage-joueur doué en ingénierie et apportez-les à Kyndra Viveflèche près du champ de tir de la Nouvelle-Avalon.", description = "Vous vous demandez peut-être : « et si je voulais plutôt une giberne » ou encore « et si je dis un mot de travers, est-ce qu’elle va m’envoyer face aux balles ? ». Je ne suis pas dans votre tête, mais dans notre profession, il faut se préparer à tout.\n\nMais on n’utilise pas de balles, ici, même si je pousse pour que ça change. Si un tas de balles venait à apparaître à mes pieds, j’imagine que je devrais fabriquer un contenant pour les stocker.\n\nSi seulement cela se produisait.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nPatron : giberne écarlate"},
[89445] = {title = "Lames de lumière", objective = "Trouvez quelque spécialiste du travail de la forge capable de vous en dire plus sur la lame de Sancteforge détruite.", description = "Même ruinée et brisée, la lame présente devant vous a des propriétés impressionnantes. Si vous arriviez à mieux comprendre le matériau qui la compose, vous pourriez l’utiliser pour forger une arme exceptionnelle. Tout d’abord, vous devez trouver quelque spécialiste du travail de la forge capable d’en identifier les propriétés et de trouver un moyen de travailler ce matériau.", progress = "Hein ? J’ai pas de temps à perdre à bavasser avec vous ! Ces cuirasses vont pas se marteler toutes seules !", completion = "Oh ! Alors, ça, c’est ce que j’appelle une épée !\n\nVous dites que vous cherchez une personne capable de travailler ce matériau ? Hum, eh bien, je suis au regret de vous dire que les secrets de ce métal dépassent de loin mon expertise. Si seulement Omarion était là. C’est lui le maître artisan, ici, et c’est un expert sur les alliages et matériaux exotiques. Il saurait tout de suite de quoi il s’agit. Le seul problème, c’est qu’il a disparu !\n\nS’il est encore vivant, il pourra vous aider !", rewards = "Vous recevrez :\n\n"},
[89446] = {title = "L’artisan perdu", objective = "Trouvez le maître-artisan Omarion.", description = "<L’artisan Wilhem ne semble pas pouvoir vous aider, mais il a parlé de son ancien maître, un homme appelé Omarion, qui en serait capable. Si vous le trouvez, il en saura peut-être davantage sur ce matériau.>", progress = "<Le regard d’Omarion s’arrête à peine sur vous.>", completion = "J’ai bien compris. Personne ne vient me trouver si ce n’est pour me demander quelque chose. Ça va, ça va. J’ai pas besoin d’être secouru. Ça me va très bien de mourir ici dans cet endroit oublié de la Lumière. Je vous prie de me laisser.", rewards = "Vous recevrez :\n\n"},
[89447] = {title = "Goûts extravagants", objective = "Apportez dix portions de pyro-côtelettes de chimaerok à la Dirge au maître-artisan Omarion à Naxxramas.", description = "Vous avez un sacré bout de métal avec vous. Mais quelle importance ?\n\nOh, vous voulez que je vous en dise plus ? Eh bien, c’est une épée, et elle est cassée. C’est bon, on a fini ?\n\n<Il vous regarde sévèrement et finit par soupirer quand il se rend compte que vous n’allez pas repartir de sitôt.>\n\nBon, d’accord. Laissez-moi la lame et j’y jetterai un œil. En attendant, je mangerais bien un morceau. Je connais un gobelin, Dirge Quickcleave. Il prépare les meilleures côtelettes de chimaerok que j’ai pu goûter. Apportez-m’en.", progress = "Quand c’est des morts-vivants qui vous retiennent prisonnier, ils se soucient peu de votre estomac. Moi, je m’en fiche, j’aurais pu me laisser mourir de faim. Mais puisque vous refusez de me ficher la paix, vous pourriez au moins aller me chercher un dernier repas digne de ce nom.", completion = "Ça m’a fait du bien, &lt;classe&gt;.\n\nBon, voyons un peu cette lame. Elle est… vraiment remarquable. Elle émet de la chaleur et son tranchant est presque surnaturel. Il semblerait aussi qu’elle repousse les morts-vivants, vu qu’aucun zombie n’est venu tenter de me dévorer depuis que vous l’avez laissée ici.\n\nEt c’est bien dommage. Les zombies ont très peu de conversation, mais on se contente d’un rien dans un endroit comme celui-ci.", rewards = "Vous recevrez :\n\n"},
[89448] = {title = "Rassembler la Lumière", objective = "Apportez 12 lingots de fer de sancteforge au maître-artisan Omarion à Naxxramas et découvrez où la Croisade écarlate forge ces nouvelles armes.", description = "<Omarion semble bien plus vif que lors de votre première rencontre.>\n\nBon, <classe>, vous avez mon attention. Ce métal est parfaitement unique, et j’aimerais tenter d’autres expériences avec. Mais il va m’en falloir d’autres échantillons. Apportez-moi une bonne douzaine de lingots de ce fer de « sancteforge ». Voyez également ce que vous pouvez apprendre sur l’endroit où ces armes sont fabriquées. Pour forger de bonnes armes, il faut de bons outils et un bon atelier, après tout.", progress = "J’aurais bien aimé un peu de Kaja’Cola pour faire descendre ces côtelettes. Oh, vous ne connaissez pas le Kaja’Cola ? Si vous avez l’occasion d’en boire, ça vous changera la vie.", completion = "Ça devrait suffire. Vous avez appris autre chose ?\n\n&lt;Vous parlez à Omarion de la forge rayonnante que vous avez découverte dans l’enclave Écarlate.&gt;\n\nTrès intéressant. Il y aurait une enclume alimentée par la Lumière au sein de l’enclave Écarlate, et c’est là que ces armes sont fabriquées ?\n\nIl n’y a rien à faire. Je dois voir ça de mes yeux. Je suppose que je viendrai mourir dans cet endroit sinistre une autre fois.", rewards = "Vous recevrez :\n\n"},
[89463] = {title = "Accord de confidentialité", objective = "Foiramorce à la Nouvelle-Avalon a besoin d’une plume et de quoi rendre sa planque plus confortable. Vous pouvez trouver une plume chic dans l’hôtel de ville de la Nouvelle-Avalon et un élément de décor de maison près de la Scholomance ou dans les cryptes de Karazhan.", description = "Je ne suis pas le genre de gobelin à partager ses secrets avec n’importe qui, mais je SUIS du genre à partager les secrets des gnomes ! Il se trouve que je me suis procuré quelques schémas en venant ici et j’essaie de corriger les défauts sur ces modèles. Ces gnomes utilisent encore des fusibles de sécurité ! Vous y croyez, vous ? DES FUSIBLES DE SÉCURITÉ !!\n\nBref, j’ai hâte de partager mon progrès, mais j’ai besoin d’une plume pour griffonner tout ça. Il me faudrait aussi un endroit confortable pour réfléchir. Qu’en dites-vous ?", progress = "Ah, vous voilà ! J’ai hâte de voir ce que vous m’avez rapporté !", completion = "Je ne sais pas trop à quoi je m’attendais, mais ce n’était pas à… ça. Ça va bien avec les arbres, j’imagine. Je ne devrais pas me plaindre, principalement car je vais me mettre à crier, et ça ne plairait à personne.\n\nMais plus important encore, une plume ! J’ai oublié de vous dire que je n’avais plus d’encre, mais un peu d’huile de moteur devrait faire l’affaire.\n\n&lt;Foiramorce teste la plume sur un schéma improvisé.&gt;\n\nEt voilà.", rewards = "Vous recevrez :\n\nSchéma : arbuste improvisé"},
[89471] = {title = "Bricolage gobelin", objective = "Foiramorce à la Nouvelle-Avalon vous a donné une liste de composants d’ingénierie nécessaires à ses inventions. Rapportez-lui ces objets.", description = "Je pense qu’on peut dire que notre collaboration est déjà bien établie. Je suis le cerveau, vous êtes les muscles. Ça tombe bien, car je me suis rendu compte il y a environ trente secondes qu’il me manquait des composants essentiels !\n\nVoici une liste des choses dont j’ai besoin pour ces schémas, sans tenir compte de la camelote gnome. Je vais corriger les modèles en attendant. Quand vous serez de retour, on pourra se mettre au travail.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : boîte bricolée"},
[89485] = {title = "Horreurs fantasques", objective = "Déguisez-vous et faufilez-vous parmi les citoyens et citoyennes de la Nouvelle-Avalon pour leur donner un portiporteur. Une fois <convaincu/convaincue> que l’appareil ne causera pas votre mort instantanée, essayez-le par vous-même pour identifier la nature du problème mentionné par Foiramorce.", description = "Bien que je me délecte à l’idée de faire de vous le cobaye de toutes mes inventions, celle-ci me rend quelque peu perplexe. Elle est censée vous transporter dans quelques années, mais lorsque j’ai titillé le premier prototype à l’aide de ma baguette, il s’est volatilisé, emportant avec lui ma baguette !\n\nJ’ai depuis apporté plusieurs modifications au fil des divers prototypes. Vous aviez l’air de bien vous entendre avec les habitants et habitantes, tentez donc de les convaincre d’essayer ma machine. Ensuite, si vous vous en sentez le courage, vous pourrez l’essayer par vous-même.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : boîte bricolée : téléporteur"},
[89486] = {title = "Une pincée de poudre à canon", objective = "Atteignez les lieux suivants de la Nouvelle-Avalon dans le temps imparti.", description = "Je sais que vous mourez d’envie d’apprendre ce que j’ai prévu de faire avec cette poudre à canon.\n\nAvez-vous déjà entendu parler des nitro-survolteurs ? Je ne parle pas de nitro-survoleurs, mais bien de survolteurs. Si vous répondez oui, vous mentez, car ils n’ont pas encore été inventés. Du moins, jusqu’à ce que j’intervienne !\n\nJe vous offre l’immense honneur d’être <le premier/la première> à les essayer. Il vous suffit d’ajouter une pincée de poudre à canon ici, puis d’appuyer sur le bouton. Si vous avez envie d’aller encore plus vite, ajoutez donc une petite pincée !\n\nAssurez-vous de traverser plusieurs reliefs différents avant de revenir.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : boîte bricolée : nitro-survolteurs"},
[89487] = {title = "L’attrait des aimants", objective = "Utilisez le prototype d’aimant dans la Nouvelle-Avalon pour attirer des objets magnétiques. Lorsque vous aurez suffisamment prouvé la théorie de Foiramorce, retournez le voir.", description = "Même avec les composants que vous m’apportez, je ne peux pas faire grand-chose sans mon atelier. Mais j’ai conçu un plan, un plan de génie, pour comprendre comment fonctionnent ces étranges champs magnétiques. Je pense qu’à l’aide de l’ingénierie gobeline de pointe, je pourrai trouver un moyen de réduire au minimum la distance qui sépare deux personnes ! Plus personne ne pourra partir sans m’acheter quelque chose.\n\nPour prouver ma théorie, prenez ce prototype et utilisez-le dans la Nouvelle-Avalon. Avec un peu de chance, vous trouverez quelque chose !Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : boîte bricolée : déplacement magnétique"},
[89489] = {title = "Augmentation du taux de butin", objective = "Foiramorce à la Nouvelle-Avalon souhaite acquérir de nombreuses ceintures, et pour de bonnes raisons. Les soldats de la Nouvelle Avalon représentent certainement une source probable de cet équipement.", description = "Maintenant qu’on sait que mes inventions fonctionnent de manière autonome, la prochaine étape logique en matière d’innovation est d’améliorer la réutilisabilité et l’ergonomie ! Je pense que personne n’a envie de jeter une poignée de pièces d’or juste pour passer au-dessus d’une flaque d’eau.\n\nComme toujours, j’ai une idée.\n\nLes ceintures sont un équipement tristement sous-estimé, et elles sont simples à atteindre. Il serait judicieux de les améliorer avec des gadgets réutilisables, mais il m’en faut quelques-unes pour m’entraîner. Allez en voler.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nManuel de bricolage de Foiramorce"},
[89491] = {title = "Un plan d’évasion complexe", objective = "Utilisez le samophlange de triangulation à trois endroits inopportuns, puis utilisez votre transporteur ultra-sécurisé : Gadgetzan ou votre déchiqueteur dimensionnel – Long-Guet en vous tenant debout sur le module de téléportation pour terminer le calibrage. Retournez ensuite voir Foiramorce à la Nouvelle-Avalon.", description = "Eh bien, c’était chouette, mais je pense qu’on a passé trop de temps ici. J’ai envisagé d’utiliser mes nouveaux gadgets pour m’en sortir en cas de besoin, mais je ne vais pas pouvoir transporter toutes mes nouvelles affaires en un seul voyage !\n\nEn arrivant ici, j’ai réussi à installer un module de téléportation, comme vous avez pu le constater. Il ne reste plus qu’à le calibrer.\n\nPrenez cet appareil et utilisez-le près des portes, du champ de tir à l’arc et à l’intérieur de la taverne. Puis, et seulement à ce moment-là, placez-vous au-dessus de mon téléporteur et utilisez votre appareil de téléportation vers Gadgetzan ou Long-Guet pour le mettre en route.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nSchéma : transporteur semi-sécurisé – Nouvelle-Avalon"},
[89562] = {title = "Mon vieil ennemi", objective = "Apprenez-en plus sur Baelin Caldoran auprès de Leonid Barthalomew le Révéré.", description = "J’avais entendu dire que Caldoran était présent à Naxxramas et je redoutais de me retrouver en première ligne à ses côtés si le combat dégénérait.\n\nMême si l’Aube d’argent est favorable à ce que vous apportiez votre aide aux forces de la Reconquête écarlate, je me dois de vous prévenir de manière très claire : méfiez-vous de Baelin Caldoran. Mes mains tremblent de colère rien qu’en pensant à cet homme et aux atrocités qu’il a fait subir à des innocents. Vous ne devez PAS lui faire confiance. Je vous en conjure, tenez compte de mes paroles.", progress = nil, completion = "Voilà tout ce que j’ai à dire sur le sujet pour le moment. Cela m’a pris des années pour sortir mon âme du gouffre ténébreux où elle se trouvait après tout ce que cet homme m’a infligé.\n\nMême si nous sommes aujourd’hui des alliés temporaires, je ferai en sorte que, un jour, Caldoran paie pour ses crimes. J’en fais le serment. En attendant, faites preuve d’une extrême prudence dans vos échanges avec lui.", rewards = "Vous recevrez :\n\n"},
[89563] = {title = "Le fardeau de Leonid", objective = "Recevez les instructions du seigneur Maxwell Tyrosus.", description = "Je n’ai pas pu me retenir d’écouter votre conversation avec Leonid au sujet de l’inquisiteur Caldoran. Les quelques détails qu’il vous a donnés ne sont qu’une fraction de l’histoire qu’ils ont en commun et des souffrances que Caldoran lui a infligées. J’étais à ses côtés lorsque Leonid était au bord du précipice et je l’ai aidé à se relever.\n\nJe crains que notre coopération avec la Croisade écarlate n’affecte Leonid, surtout si celle-ci le rapproche de cet homme.", progress = nil, completion = "Je vais garder un œil sur la situation, et vous ferez de même avec Caldoran aux côtés des troupes de la reconquête. Aucun de nos « alliés » ne m’inspire confiance, et lui encore moins.\n\nRetournez voir Leonid. J’ai une mission pour lui et je souhaiterais que vous l’accompagniez. Je pense que cela lui ferait le plus grand bien de passer du temps loin d’ici.", rewards = "Vous recevrez :\n\n"},
[89567] = {title = "La caravane accidentée", objective = "Examinez les débris de la caravane écarlate à Pestebois, le long de la route de Stratholme, et parlez à Leonid Barthalomew le Révéré lorsque vous en saurez plus.", description = "Le seigneur Tyrosus m’a chargé d’enquêter sur les débris d’une caravane de la Croisade écarlate située à Pestebois, le long de la route de Stratholme.\n\nDes rapports récents indiquent que d’importants déplacements de la Croisade ont été observés dans toutes les Maleterres avant le schisme survenu à la Main de Tyr. Cette caravane est susceptible de nous fournir des indications sur son objectif.\n\nJe vous retrouverai là-bas afin que nous puissions mener l’enquête ensemble.", progress = "Tout ceci est décidément bien étrange. Vous avez découvert quelque chose d’intéressant ?", completion = "Cette caravane contenait donc… des échantillons de peste prélevés à Naxxramas ? Mais pourquoi ? Dans quel but ? La Croisade écarlate cherchait-elle à étudier la peste pour la contrer ?", rewards = "Vous recevrez :\n\n"},
[89568] = {title = "Quelque chose de nouveau", objective = "Utilisez les échantillons de Peste nouvelle sur les goules cannibales, les horreurs raccommodées, les mages maudits, les soldats du Fléau et les gardiens du Fléau affaiblis que vous trouverez à Pestebois, et observez ses effets.", description = "Nous devons en apprendre plus sur cette nouvelle peste. Elle semble avoir pour objectif de… tuer les morts-vivants autant que les vivants ? Les morts-vivants sont par nature protégés contre le fléau de la non-mort, puisqu’ils en sont nés. Si mes soupçons sont fondés, il pourrait bien être question de quelque chose de nouveau, de terrible.\n\nJe ne souhaite pas soumettre les morts-vivants de cet endroit à de nouveaux tourments, mais nous devons en apprendre davantage avant de retourner à l’Espoir de Lumière.", progress = "Être si proche de Stratholme est déstabilisant pour moi suite à…\n\n<Leonid Barthalomew le Révéré marque une pause et tourne le regard vers Stratholme. Vous remarquez que sa main commence à trembler légèrement.>\n\nNe vous inquiétez pas, ce n’est rien.\n\nTerminons rapidement ce que nous sommes venus faire ici, <nom>.", completion = "L’effet de cette peste sur les morts-vivants est puissant et terrifiant. Si jamais elle venait à être utilisée contre les Réprouvés des ruines de Lordaeron, cela pourrait être désastreux.\n\nIl reste un autre test à effectuer.", rewards = "Vous recevrez :\n\n"},
[89574] = {title = "Les serviteurs de la mort", objective = "Utilisez les échantillons de Peste nouvelle sur les invocateurs des ténèbres et les nécromanciens que vous trouverez dans les Maleterres de l’Est et observez ses effets.", description = "À mes yeux, il n’existe rien de pire que les agents vivants du roi-liche. Je méprise et rejette toute personne ayant le libre arbitre de distinguer le bien du mal, mais qui décide de servir délibérément la mort. Prenez les échantillons de peste et testez-les sur les membres vivants du Culte des damnés qui se trouvent non loin.\n\nCes monstres ne méritent ni la pitié, ni la clémence. Ils ont jeté leur dévolu sur les damnés, alors faisons-leur goûter aux enfers.", progress = "J’ai étudié ces notes, et ce que j’y lis est terrifiant.\n\nC’est la Croisade écarlate qui a développé cette épidémie.", completion = "Exactement comme je m’y attendais, cette peste a des effets similaires sur les vivants et les morts. Je crains que cela ne présage rien de bon pour tout le monde.\n\nComment la Croisade écarlate a-t-elle pu mettre au point une telle peste ? Cela nécessiterait une connaissance précise de la peste morte-vivante originelle, et la recherche sur celle-ci est… délicate pour les vivants. C’est pour le moins préoccupant.\n\nJe pense que nous avons découvert tout ce que nous pouvions pour le moment. Mais avant de repartir, puis-je vous demander une faveur ?", rewards = "Vous recevrez :\n\n"},
[90107] = {title = "La lame réformée", objective = "Reculez et observez le maître-artisan Omarion pendant qu’il tente de forger la lame de Porte-Cendres reforgée.", description = "Les alliages que j’ai obtenus me semblent suffisamment fiables pour fabriquer des lingots. Heureusement, nous avons également beaucoup de matières premières avec tout ce que vous avez rassemblé pour moi jusqu’à présent.\n\nReculez un peu si vous le voulez bien. Travailler avec la forge peut être… spectaculaire.", progress = nil, completion = "Voilà qui est fait. Bien que mon alliage sancteforge soit un produit de la magie du sacré, cette lame, dans sa forme actuelle, n’est qu’une simple épée. C’est à vous et à votre ami fantomatique qu’il incombe de rassembler les pièces restantes.\n\nJ’ai le sentiment du devoir accompli pour la première fois depuis longtemps, mais je vous confesse mon mauvais pressentiment à propos de tout ça. Je me demande s’il n’aurait pas été plus prudent de laisser Porte-Cendres en morceaux. J’ai l’impression que ce n’est pas normal. Comme si cela n’était pas censé se produire.", rewards = "Vous recevrez :\n\nLame reforgée du Porte-Cendres"},
[90116] = {title = "Fils sacrés", objective = "Obtenez de l’étoffe de l’Aube en tissant des rouleaux à proximité directe du métier à tisser de croisé. Retournez voir Taylor quand vous en aurez suffisamment.", description = "Ce métier à tisser est spécial. Vous le saviez ? Nos spécialistes de l’artisanat ont vu leurs outils bénis par notre grande prêtrise.\n\nCe métier en particulier attire les fils et tissus destinés à être utilisés pour nos tenues cérémonielles les plus sacrées. Avec le temps, nous en aurons rassemblé suffisamment pour créer une nouvelle robe, et ça, c’est quelque chose de prodigieux, pour moi, du moins.\n\nSi cela vous intéresse, tissez quelques rouleaux près du métier et admirez la Lumière à l’œuvre.", progress = "D’habitude, il faut plusieurs projets de taille comme des chemises ou des pantalons pour accumuler suffisamment d’étoffe de l’Aube, mais pour cette petite démonstration, tisser des rouleaux devrait suffire.", completion = "Splendide ! Bien sûr, il ne s’agit que d’une petite partie d’une robe d’abbé écarlate, mais j’imagine que vous en savez désormais un peu plus sur votre propre art.\n\nJe vais vous débarrasser de ceci pour le ranger. Le motif des robes sacrées est un secret bien gardé, mais j’aimerais vous offrir ceci à la place. Les sacs profonds et robustes se font rares de nos jours, mais ils valent largement l’investissement. Qui sait, vous ferez peut-être de bonnes affaires en vendant des sacs ?", rewards = "Vous recevrez :\n\nPatron : sac à dos de croisade"},
[90120] = {title = "Rouge comme le sang neuf", objective = "Trouvez différents composants pouvant être utilisés comme teinture rouge vif. De la teinture et des roses rouges peuvent être achetées chez les marchands et marchandes. Les fleurs de feu peuvent être trouvées chez les herboristes. Du sang des héros peut être trouvé dans les Maleterres. Des feuillelames cramoisies dont on peut extraire de la teinture sont récupérables près du lac Mennar en Azshara.", description = "Hum, en parlant de secrets, je travaille sur un nouveau projet : des sacs de luxe pour nos troupes de haut rang. Ils doivent être grands, faits à partir des meilleures soies et, bien évidemment, aussi rouges que le blason de la Croisade écarlate.\n\nTrouver les matériaux sera le plus facile. J’entends utiliser votre étoffe de l’Aube. Mettre la main sur la teinture idéale, en revanche, dépasse mes compétences. Arpentez le monde en quête de la nuance de rouge parfaite et nous serons partenaires sur ce projet : je partagerai mon patron final avec vous.", progress = "Prenez votre temps, vraiment. Il s’agit d’un projet passion pour moi, rien de plus. Il est plus important de trouver la teinture idéale que de constituer rapidement des stocks, je préfère toujours un travail long et soigné à un autre rapide et bâclé.\n\nJe vous attends ici.", completion = "Vous avez l’œil, dites-moi ! Non pas que j’en doutais, mais je ne m’attendais pas à ce que vous trouviez si vite une nuance de rouge qui me touche autant. Et vous en avez même trouvé plusieurs !\n\n&lt;Taylor admire les teintures en lice une par une, sans se soucier du fait que l’une d’elles est une fiole de sang.&gt;\n\nCelles appelées « sang des héros » et « feuillelames cramoisies » sont mes préférées, et le choix est ardu. Il serait logique que nous utilisions chacun une teinture différente. Je vais donc prendre les feuillelames.", rewards = "Vous recevrez :\n\nPatron : sac en étoffe de l’Aube cramoisie"},
[90510] = {title = "La Nouvelle-Avalon", objective = "Utilisez l’insigne écarlate une fois que vous aurez suffisamment de pièces de déguisement pour tromper les membres de la Croisade écarlate de la Nouvelle-Avalon, puis retournez voir l’inquisitrice Jociphine. Les personnages-joueurs pratiquant des métiers de fabrication d’armure peuvent utiliser les plans et recettes d’armure écarlate que l’on trouve sur les croisés hostiles de la Main de Tyr et de la Nouvelle-Avalon.", description = "Comme vous avez pu le constater, la Nouvelle-Avalon est dotée d’une présence militaire conséquente qui garantit la sécurité de ses citoyens.\n\nSi vous parvenez à bricoler un déguisement qui tienne sur la durée, n’hésitez pas à prêter main-forte. Vous intégrer au peuple pourrait s’avérer utile dans notre reconquête de l’enclave, sans parler de l’occasion pour vous de « réquisitionner » certaines des ressources disponibles ici : vous en sortiriez les poches remplies tout en privant la force militaire du seigneur de l’effroi de précieuses ressources.", progress = nil, completion = "Je pense que ça suffira.\n\nLa Nouvelle-Avalon a perdu quelques épéistes d’élite lors d’une expédition vers Hearthglen il y a quelques années, mais je vois que tous les patrons n’ont pas été perdus.\n\nSi vous n’avez pas aiguisé vos compétences en artisanat, vous aurez du mal à faire votre trou dans la Nouvelle-Avalon. Cependant, que vous sachiez manier une aiguille, un marteau ou rien du tout, je vous conseille d’aller rendre visite à l’intendance dans la caserne. Il y aura peut-être aussi des choses intéressantes dans l’entrepôt.", rewards = nil},
[90518] = {title = "Une pomme par jour et les morts-vivants crient au secours", objective = "Trouvez le verger dans la partie sud de la Nouvelle-Avalon et récupérez des pommes. Retournez ensuite voir Carrie Âtrefeu dans l’auberge de la Nouvelle-Avalon. Si vous trouvez les pommes trop chères, cherchez d’autres moyens de vous en procurer dans les environs.", description = "C’est un plaisir de vous revoir. Je n’ai eu aucun mal à ravitailler la cuisine pendant votre absence, mais j’ai remarqué ce matin qu’il me manquait des pommes pour faire une tarte. Je me suis dit que je méritais bien une petite gâterie.\n\nSi vous avez un peu de temps devant vous, pourriez-vous passer au verger en cueillir quelques-unes ? Malheureusement, je n’ai pas non plus préparé la tarte de Johnny, mais je ne peux pas faire de tarte sans pommes et je ne vais pas en gâcher pour celle de Johnny !\n\nBien sûr, je vous en donnerai une part aussi.", progress = "N’oubliez pas que Johnny risque de vous faire payer davantage pour ses meilleures pommes, mais je suis sûre que vous trouverez une autre solution si vous vous refusez à remplir ses poches.", completion = "Merveilleux, je me mets immédiatement au travail ! Ces pommes sont encore plus appétissantes que votre dernière livraison, j’en viendrais presque à croire que vous tentez de gagner mes faveurs…\n\n&lt;Alors que Carrie organise son espace pour préparer la tarte, elle fait un geste exagéré pour mettre en évidence l’alliance à son doigt.&gt;\n\nMerci d’avoir participé à améliorer notre dîner. Markus et moi espérons vous revoir très vite !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSteak de rôdeurFilet de flancOmelette du Lever de soleilSels sacrés\n\nVous recevrez également :\n\nPointe de tarte aux pommes de CarrieÉpices exquises"},
[90519] = {title = "Poisson demandé", objective = "Inspectez le bateau amarré au sud de la Nouvelle-Avalon en quête d’une cargaison de poissons et livrez-la à Carrie.", description = "Je déteste le poisson. Je n’en supporte pas l’odeur. Les poissons sont vraiment immondes. La pire créature qui soit.\n\nPuisqu’il s’agit de ma cuisine, je suis parfaitement en droit d’interdire les arrivages de poissons, mais parfois, nos troupes se mettent en tête d’en réclamer un festin.\n\nIl semblerait que ce soit le cas ce soir. J’ai besoin de poisson, et en quantité !", progress = "Merci de ne pas livrer de commande incomplète. Je préfère m’en débarrasser d’un seul coup.\n\nSi vous ne trouvez pas assez de poissons pour la soirée, vous n’avez qu’à aller récupérer des restes, encore une fois. Je pense sincèrement que ce serait une option à privilégier.", completion = "Ah, j’espérais que vous auriez mieux à faire ce soir, mais je vois que vous êtes toujours aussi fiable.\n\nBon. Je ferais mieux de m’y mettre.", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSteak de rôdeurFilet de flancOmelette du Lever de soleilSels sacrés\n\nVous recevrez également :\n\nÉpices exquises"},
[90520] = {title = "Hygiène alimentaire", objective = "Procurez-vous de la viande propre à la consommation humaine. Si vous n’en trouvez pas dans la Nouvelle-Avalon, vous pourrez (à force) en récupérer assez en chassant des bêtes dans les Maleterres de l’est.", description = "Je crois me souvenir que l’un des premiers ingrédients que je vous ai demandé de rapporter était de la viande. Je me souviens aussi de nombreuses plaintes ce soir-là à propos de maux de ventre après le repas ? C’était très étrange.\n\nEnfin bref, le garde-manger va à nouveau manquer de viande et si je pouvais compter sur quelqu’un de confiance pour le remplir, ce serait très apprécié. La dernière chose dont j’avais besoin, c’est d’apprendre que la personne censée me livrer est morte depuis une semaine !", progress = "Le dîner sera servi en retard, à ce rythme.", completion = "Votre constance est incroyable, et elle vous honore. Ces portions sont coupées à la perfection, et possèdent la même couleur et la même consistance que celles de votre dernière livraison. Si je me retrouve un jour à devoir chasser ma propre nourriture, j’espère vous avoir à mes côtés.\n\nAinsi que Markus, bien entendu.\n\nJe vais vous débarrasser de ceci et me mettre au travail. La Nouvelle-Avalon mangera à sa faim, ce soir !", rewards = "Vous pourrez choisir une de ces récompenses :\n\nSteak de rôdeurFilet de flancOmelette du Lever de soleilSels sacrés\n\nVous recevrez également :\n\nÉpices exquises"},
[90560] = {title = "Une puanteur bien familière", objective = "Récupérez des cœurs de bêtes décolorés sur les créatures des Maleterres puis apportez-les, ainsi que la potion de soins manipulée sans soin, à un membre de la Société royale des apothicaires d’Undercity qui serait intéressé.", description = "<Vous avez trouvé sur une table de laboratoire une fiole remplie d’un infâme liquide visqueux. Elle se trouvait au milieu de divers ingrédients méticuleusement dosés et hachés en portions soigneusement ordonnées. Vous ne parvenez pas à identifier ces herbes, mais un cœur de bête intact quoique décoloré est placé à proximité.\n\nLa décoction vous paraît familière et vous rappelle les récentes expériences de la Société royale des apothicaires. Si votre curiosité parvenait à surmonter votre dégoût, peut-être pourriez-vous amener la fiole à l’un de ses membres : cela l’intéresserait certainement.>", progress = nil, completion = nil, rewards = nil},
[90567] = {title = "Une puanteur peu familière", objective = "Récupérez des cœurs de bêtes décolorés et des cœurs saignants des Maleterres. Apportez-les, ainsi que la potion de soins manipulée sans soin, à un alchimiste de Darnassus qui serait intéressé.", description = "<Vous avez trouvé sur une table de laboratoire une fiole remplie d’un infâme liquide visqueux. Elle se trouvait au milieu de divers ingrédients méticuleusement dosés et hachés en portions soigneusement ordonnées. Vous ne parvenez pas à identifier les herbes, mais un cœur de bête intact, quoique décoloré, est placé à proximité.\n\nLes alchimistes de Darnassus sauront peut-être comment tirer profit des effets curatifs potentiels de cette potion. Pensez à leur apporter des fleurs, il serait malvenu de débarquer comme ça avec un simple tas de cœurs.>Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nRecette : Potion de soins décoloréeRecette : potion de soins majeure décolorée"},
[90625] = {title = "Des ailes effroyables", objective = "Apportez l’aile de Balnazzar à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Cette aile en lambeaux est tout ce qu’il reste du seigneur de l’effroi Balnazzar.\n\nCela pourrait intéresser quelqu’un à la chapelle de l’Espoir de Lumière.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[90626] = {title = "Tendon de lumière", objective = "Terrassez Solistrasza et obtenez un tendon de dragon de lumière adulte, puis apportez-le à Grok’lo à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.", description = "Grok’lo arrangera rendez-vous avec artisan spécial une fois que vous aurez déniché corde pour cette aile de chauve-souris géante.\n\nGrok’lo vous conseille trouver meilleure corde possible.\n\n<Grok’lo sourit sous son casque.>\n\nUn tendon de dragon, meilleure corde possible.Vous recevrez :\n\nLors de l'achèvement de cette quête vous gagnerez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\n"},
[90627] = {title = "L’Ingénieux généreux", objective = "Rencontrez Mizzle l’Ingénieux dans la partie nord de Hache-Tripes.\n\nVous devez l’aborder sans qu’il soit distrait, donc ne tuez aucun des Ogres importants sur votre chemin, sinon il devra s’occuper de les faire remplacer et ne pourra pas vous venir en aide. \n\nAllez-y seul.", description = "Bien, nom artisan est Mizzle l’Ingénieux.\n\nC’est si facile, même Grok’lo comprend ! Tout le monde croit il s’appelle comme ça parce que lui est intelligent ! NON ! Lui ogre, pas intelligent ! Juste doué pour bricolage !\n\n<Grok’lo opine du chef.>\n\nAllez dans nord de Hache-Tripes pour trouver lui. Assurez-vous que rien le distrait pendant vous deux parler.\n\nAllez sans personne d’autre.Vous recevrez :\n\n", progress = nil, completion = nil, rewards = "Vous recevrez :\n\nAile et corde"},
}
